);
create index weekly_contact_recheck_tasks_due_idx on public.weekly_contact_recheck_tasks(state,due_at_utc,id);

alter table public.weekly_contact_pause_scopes OWNER TO CURRENT_USER;
alter table public.weekly_contact_pause_commands OWNER TO CURRENT_USER;
alter table public.weekly_contact_pause_events OWNER TO CURRENT_USER;
alter table public.weekly_contact_submission_permits OWNER TO CURRENT_USER;
alter table public.weekly_contact_delivery_memberships OWNER TO CURRENT_USER;
alter table public.weekly_contact_recheck_tasks OWNER TO CURRENT_USER;
do $security$
declare v_table text;
begin
 foreach v_table in array array['weekly_contact_pause_scopes','weekly_contact_pause_commands','weekly_contact_pause_events',
