-- CONTACT_PREPARER_UNIT 18 repeatable supabase/repeatable/08012026_invoice_sql_first_rpcs_generator_paid_batches.sql SHA256 846bbeeeb3902faf8144bfa4cd5ee6be25fded6a5556a1fd25fa123dc29d40dd
-- ============================================================
-- CloudTMS: SQL-first invoice generator (supports HOURS + BY_WEEK)
-- RPC: public.invoice_generate_from_outbox_batch(p_outbox_ids uuid[], p_actor_user_id uuid)
--
-- 100% aligned to your pasted JS logic for:
-- - handleCreateInvoiceTsfin (HOURS)
-- - handleCreateInvoiceTsfinByWeek (BY_WEEK)
-- - extractBillableSegmentsForWeek
-- - lockSegmentsForInvoice
-- - findOrCreateSelfBillInvoice
-- - writeAudit semantics (but SQL has no req headers → ip/user_agent/correlation_id only from payload if provided)
--
-- Safe to re-run: all functions are CREATE OR REPLACE.
-- ============================================================

-- --------------------------
-- Helpers: rounding + ISO UTC
-- --------------------------
create or replace function public._inv_round2(n numeric)
returns numeric
language sql
immutable
as $$
  select round(coalesce(n,0)::numeric, 2);
$$;

create or replace function public._inv_iso_utc(ts timestamptz)
returns text
language sql
immutable
as $$
  select to_char((ts at time zone 'UTC'), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
$$;

-- ------------------------------------------
-- Helpers: schedule-aware reference gating
-- Mirrors handleCreateInvoiceTsfin local helpers
-- ------------------------------------------
create or replace function public._inv_day_refs_has_any(day_refs jsonb)
returns boolean
language sql
immutable
as $$
  select exists (
    select 1
    from jsonb_each_text(coalesce(day_refs, '{}'::jsonb)) e
    where btrim(coalesce(e.value,'')) <> ''
  );
$$;

create or replace function public._inv_weekly_manual_schedule_has_complete_refs(schedule jsonb)
returns boolean
language plpgsql
immutable
as $$
declare
  seg jsonb;
  v_start text;
  v_end   text;
  v_ref   text;
  n int;
begin
  if schedule is null or jsonb_typeof(schedule) <> 'array' then
    return false;
  end if;

  n := jsonb_array_length(schedule);
  if n <= 0 then
    return false;
  end if;

  for seg in
    select value from jsonb_array_elements(schedule) value
  loop
    if seg is null or jsonb_typeof(seg) <> 'object' then
      continue;
    end if;

    v_start := btrim(coalesce(seg->>'start',''));
    v_end   := btrim(coalesce(seg->>'end',''));

    if v_start <> '' and v_end <> '' then
      v_ref := btrim(coalesce(seg->>'ref_num',''));
      if v_ref = '' then
        return false;
      end if;
    end if;
  end loop;

  return true;
end;
$$;

create or replace function public._inv_timesheet_has_invoice_reference(
  p_sheet_scope text,
  p_submission_mode text,
  p_reference_number text,
  p_day_references_json jsonb,
  p_actual_schedule_json jsonb
)
returns boolean
language plpgsql
immutable
as $$
declare
  scope text := upper(btrim(coalesce(p_sheet_scope,'')));
  mode  text := upper(btrim(coalesce(p_submission_mode,'')));
begin
  if scope = 'WEEKLY' and mode = 'MANUAL' then
    return public._inv_weekly_manual_schedule_has_complete_refs(p_actual_schedule_json);
  end if;

  if scope = 'WEEKLY' then
    return (btrim(coalesce(p_reference_number,'')) <> '') or public._inv_day_refs_has_any(p_day_references_json);
  end if;

  return (btrim(coalesce(p_reference_number,'')) <> '');
end;
$$;

create or replace function public._inv_collect_weekly_manual_schedule_refs(
  p_sheet_scope text,
  p_submission_mode text,
  p_actual_schedule_json jsonb
)
returns jsonb
language plpgsql
immutable
as $$
declare
  scope text := upper(btrim(coalesce(p_sheet_scope,'')));
  mode  text := upper(btrim(coalesce(p_submission_mode,'')));
  seg jsonb;
  v_start text;
  v_end   text;
  v_ref   text;
  seen text[] := array[]::text[];
  out jsonb := '[]'::jsonb;
begin
  if not (scope = 'WEEKLY' and mode = 'MANUAL') then
    return '[]'::jsonb;
  end if;

  if p_actual_schedule_json is null or jsonb_typeof(p_actual_schedule_json) <> 'array' then
    return '[]'::jsonb;
  end if;

  for seg in
    select value from jsonb_array_elements(p_actual_schedule_json) value
  loop
    if seg is null or jsonb_typeof(seg) <> 'object' then
      continue;
    end if;

    v_start := btrim(coalesce(seg->>'start',''));
    v_end   := btrim(coalesce(seg->>'end',''));
    if not (v_start <> '' and v_end <> '') then
      continue;
    end if;

    v_ref := btrim(coalesce(seg->>'ref_num',''));
    if v_ref = '' then
      continue;
    end if;

    if v_ref = any(seen) then
      continue;
    end if;

    seen := array_append(seen, v_ref);
    out := out || jsonb_build_array(v_ref);
  end loop;

  return out;
end;
$$;

-- ------------------------------------------
-- Helper: write audit row (mirrors writeAudit, but no req headers)
-- ip/user_agent/correlation_id can be optionally supplied by payload.
-- ------------------------------------------
create or replace function public._inv_write_audit(
  p_actor_user_id uuid,
  p_action text,
  p_after_json jsonb,
  p_entity text,
  p_subject_id text,
  p_before_json jsonb default null,
  p_reason text default null,
  p_ip text default null,
  p_user_agent text default null,
  p_correlation_id text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_display text := null;
  v_actor_role text := 'system';
begin
  if p_actor_user_id is not null then
    select
      nullif(btrim(coalesce(u.display_name,'')), ''),
      nullif(btrim(coalesce(u.role,'')), '')
    into v_actor_display, v_actor_role
    from public.tms_users u
    where u.id = p_actor_user_id
    limit 1;

    if v_actor_display is null then
      select nullif(btrim(coalesce(u.email,'')), '')
      into v_actor_display
      from public.tms_users u
      where u.id = p_actor_user_id
      limit 1;
    end if;
  end if;

  if v_actor_display is null then
    v_actor_display := 'CloudTMS server';
  end if;

  if v_actor_role is null then
    v_actor_role := 'system';
  end if;

  insert into public.audit_events(
    object_type,
    object_id_text,
    action,
    before_json,
    after_json,
    reason,
    actor_user_id,
    actor_display,
    actor_role_at_time,
    ip,
    user_agent,
    correlation_id
  )
  values (
    coalesce(nullif(btrim(p_entity),''), 'generic'),
    nullif(btrim(p_subject_id), ''),
    coalesce(nullif(btrim(p_action),''), 'EVENT'),
    p_before_json,
    p_after_json,
    p_reason,
    p_actor_user_id,
    v_actor_display,
    v_actor_role,
    nullif(btrim(p_ip), ''),
    nullif(btrim(p_user_agent), ''),
    nullif(btrim(p_correlation_id), '')
  );
end;
$$;

-- ------------------------------------------
-- Helper: lock ALL segments in invoice_breakdown_json (HOURS endpoint)
-- Matches handleCreateInvoiceTsfin step 7 (locks every seg without lock).
-- ------------------------------------------
create or replace function public._inv_lock_all_segments_json(p_ib jsonb, p_invoice_id uuid)
returns jsonb
language plpgsql
immutable
as $$
declare
  seg jsonb;
  out_segs jsonb := '[]'::jsonb;
begin
  if p_ib is null or jsonb_typeof(p_ib) <> 'object' then
    return p_ib;
  end if;

  if coalesce(p_ib->>'mode','') <> 'SEGMENTS' then
    return p_ib;
  end if;

  if jsonb_typeof(p_ib->'segments') <> 'array' then
    return p_ib;
  end if;

  for seg in
    select value from jsonb_array_elements(p_ib->'segments') value
  loop
    if seg is null or jsonb_typeof(seg) <> 'object' then
      out_segs := out_segs || jsonb_build_array(seg);
    else
      if nullif(coalesce(seg->>'invoice_locked_invoice_id',''), '') is null then
        seg := jsonb_set(seg, '{invoice_locked_invoice_id}', to_jsonb(p_invoice_id::text), true);
      end if;
      out_segs := out_segs || jsonb_build_array(seg);
    end if;
  end loop;

  return jsonb_set(p_ib, '{segments}', out_segs, true);
end;
$$;
-- ------------------------------------------
-- Helper: lock segments for BY_WEEK (exact mirror of lockSegmentsForInvoice JS)
-- segmentRefs_json must be jsonb array of objects: {tsfin_id, segment_id}
-- ------------------------------------------
create or replace function public._inv_lock_segments_for_invoice(p_invoice_id uuid, p_segment_refs jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_iso text := public._inv_iso_utc(now());
  ref jsonb;
  v_tsfin_id uuid;

  -- per-tsfin
  v_lock_whole boolean;
  v_seg_ids text[];

  snap record;
  ib jsonb;
  basis text;
  is_selfbill_or_nhsp boolean;
  all_locked boolean;

  seg jsonb;
  segs_out jsonb;
  sid text;
  locked text;

  i int;

  -- =====================================================
  -- DEBUG (invoice_debug): single audit row per RPC call
  -- =====================================================
  v_invoice_debug boolean := false;
  v_dbg_started_at timestamptz := now();
  v_dbg_steps jsonb := '[]'::jsonb;
  v_dbg_sqlstate text := null;
  v_dbg_error text := null;
  v_dbg_stats jsonb := '{}'::jsonb;

  v_tsfins_seen int := 0;
  v_tsfins_updated int := 0;
  v_segments_newly_locked int := 0;
  v_summaries_set int := 0;
begin
  -- Load invoice_debug flag (safe even if column not yet present)
  begin
    select coalesce(sd.invoice_debug, false)
    into v_invoice_debug
    from public.settings_defaults sd
    where sd.id = 1
    limit 1;
  exception when undefined_column then
    v_invoice_debug := false;
  end;

  if v_invoice_debug then
    v_dbg_steps := v_dbg_steps || jsonb_build_array(
      jsonb_build_object(
        'step','start',
        'at_utc', public._inv_iso_utc(v_dbg_started_at),
        'invoice_id', coalesce(p_invoice_id::text,'')
      )
    );
  end if;

  if p_segment_refs is null or jsonb_typeof(p_segment_refs) <> 'array' then
    return;
  end if;

  -- Build distinct tsfin_ids
  for ref in
    select value from jsonb_array_elements(p_segment_refs) value
  loop
    if jsonb_typeof(ref) <> 'object' then
      continue;
    end if;

    if nullif(coalesce(ref->>'tsfin_id',''), '') is null then
      continue;
    end if;
  end loop;

  -- Process each tsfin_id separately (mirror JS loop)
  for v_tsfin_id in
    select distinct (x->>'tsfin_id')::uuid
    from jsonb_array_elements(p_segment_refs) x
    where nullif(coalesce(x->>'tsfin_id',''), '') is not null
  loop
    v_tsfins_seen := v_tsfins_seen + 1;

    -- Gather ref set for this tsfin_id
    select
      bool_or(nullif(coalesce(x->>'segment_id',''), '') is null) as lock_whole,
      array_agg(distinct (x->>'segment_id')) filter (where nullif(coalesce(x->>'segment_id',''), '') is not null) as seg_ids
    into v_lock_whole, v_seg_ids
    from jsonb_array_elements(p_segment_refs) x
    where (x->>'tsfin_id')::uuid = v_tsfin_id;

    v_lock_whole := coalesce(v_lock_whole,false);
    v_seg_ids := coalesce(v_seg_ids, array[]::text[]);

    -- Load snapshot (✅ FIX: lock the tsfin row to prevent concurrent lost-updates)
    select tf.id, tf.basis, tf.locked_by_invoice_id, tf.invoice_breakdown_json
    into snap
    from public.timesheets_financials tf
    where tf.id = v_tsfin_id
    for update;

    if not found then
      continue;
    end if;

    ib := snap.invoice_breakdown_json;
    basis := upper(coalesce(snap.basis::text,''));

    is_selfbill_or_nhsp :=
      basis = 'NHSP' or
      basis = 'NHSP_ADJUSTMENT' or
      basis = 'HEALTHROSTER_SELF_BILL' or
      basis = 'HEALTHROSTER_ADJUSTMENT';

    all_locked := true;
    segs_out := null;

    if ib is not null
       and jsonb_typeof(ib) = 'object'
       and coalesce(ib->>'mode','') = 'SEGMENTS'
       and jsonb_typeof(ib->'segments') = 'array'
    then
      segs_out := '[]'::jsonb;

      for seg in
        select value from jsonb_array_elements(ib->'segments') value
      loop
        if seg is null or jsonb_typeof(seg) <> 'object' then
          segs_out := segs_out || jsonb_build_array(seg);

          -- ✅ FIX (defensive, does not affect valid data):
          -- If we are NOT explicitly locking whole, invalid segment elements must prevent
          -- whole-timesheet lock inference (avoids marking locked_by_invoice_id due to JSON nulls).
          if not v_lock_whole then
            all_locked := false;
          end if;

          continue;
        end if;

        sid := coalesce(seg->>'segment_id','');
        locked := nullif(coalesce(seg->>'invoice_locked_invoice_id',''), '');

        if v_lock_whole or (sid <> '' and sid = any(v_seg_ids)) then
          if locked is null then
            locked := p_invoice_id::text;
            v_segments_newly_locked := v_segments_newly_locked + 1;
          end if;
        end if;

        if locked is null then
          all_locked := false;
        end if;

    seg := jsonb_set(seg, '{invoice_locked_invoice_id}', coalesce(to_jsonb(locked), 'null'::jsonb), true);

        segs_out := segs_out || jsonb_build_array(seg);
      end loop;

      ib := jsonb_set(ib, '{segments}', segs_out, true);
    else
      -- No segments
      all_locked := (snap.locked_by_invoice_id is not null) or v_lock_whole;
    end if;

    if (not is_selfbill_or_nhsp) and all_locked then
      v_summaries_set := v_summaries_set + 1;
    end if;

    -- Patch
    if ib is not null then
      update public.timesheets_financials
      set
        updated_at = now(),
        invoice_breakdown_json = ib,
        locked_by_invoice_id = case
          when (not is_selfbill_or_nhsp) and all_locked then p_invoice_id
          else locked_by_invoice_id
        end,
        locked_at_utc = case
          when (not is_selfbill_or_nhsp) and all_locked then now()
          else locked_at_utc
        end
      where id = v_tsfin_id;
    else
      update public.timesheets_financials
      set
        updated_at = now(),
        locked_by_invoice_id = case
          when (not is_selfbill_or_nhsp) and all_locked then p_invoice_id
          else locked_by_invoice_id
        end,
        locked_at_utc = case
          when (not is_selfbill_or_nhsp) and all_locked then now()
          else locked_at_utc
        end
      where id = v_tsfin_id;
    end if;

    v_tsfins_updated := v_tsfins_updated + 1;
  end loop;

  if v_invoice_debug then
    begin
      v_dbg_stats := jsonb_build_object(
        'tsfins_seen', v_tsfins_seen,
        'tsfins_updated', v_tsfins_updated,
        'segments_newly_locked', v_segments_newly_locked,
        'summaries_set', v_summaries_set
      );

      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','finish',
          'at_utc', public._inv_iso_utc(now()),
          'stats', v_dbg_stats
        )
      );

      perform public._inv_write_audit(
        null,
        'INV_LOCK_SEGMENTS_DEBUG',
        jsonb_build_object(
          'invoice_id', coalesce(p_invoice_id::text,''),
          'stats', v_dbg_stats,
          'steps', v_dbg_steps
        ),
        'timesheets_financials',
        ('invoice:' || coalesce(p_invoice_id::text,'')),
        null,
        'INVOICE_DEBUG',
        null, null, null
      );
    exception when others then
      null;
    end;
  end if;

exception when others then
  v_dbg_sqlstate := SQLSTATE;
  v_dbg_error := SQLERRM;

  if v_invoice_debug then
    begin
      v_dbg_stats := jsonb_build_object(
        'tsfins_seen', v_tsfins_seen,
        'tsfins_updated', v_tsfins_updated,
        'segments_newly_locked', v_segments_newly_locked,
        'summaries_set', v_summaries_set
      );

      perform public._inv_write_audit(
        null,
        'INV_LOCK_SEGMENTS_ERROR',
        jsonb_build_object(
          'invoice_id', coalesce(p_invoice_id::text,''),
          'sqlstate', v_dbg_sqlstate,
          'error', v_dbg_error,
          'stats', v_dbg_stats,
          'steps', v_dbg_steps
        ),
        'timesheets_financials',
        ('invoice:' || coalesce(p_invoice_id::text,'')),
        null,
        'INVOICE_DEBUG',
        null, null, null
      );
    exception when others then
      null;
    end;
  end if;

  raise;
end;
$$;

create or replace function public.invoice_create_credit_note_and_unlock(
  p_invoice_id uuid,
  p_actor_user_id uuid
)
returns table (
  credit_note_id uuid,
  unlocked_snapshots int
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := now();

  v_inv record;
  v_base_hdr jsonb := '{}'::jsonb;

  v_original_issued_at timestamptz;
  v_anchor_ymd date;

  v_stationery_key text;
  v_margins jsonb;
  v_hide_bank_footer boolean;

  v_bank jsonb;
  v_vat_reg text;

  v_client_name text;
  v_client_addr text;
  v_client_email text;
  v_vat_chargeable boolean;
  v_terms_days int;

  v_applied_vat numeric;
  v_global_vat numeric := 20;
  v_client_vat_override numeric;

  v_due_at timestamptz;

  v_credit_id uuid;

  v_ts_ids uuid[];

  v_cn_ex numeric := 0;
  v_cn_vat numeric := 0;
  v_cn_inc numeric := 0;
begin
  if p_invoice_id is null then
    raise exception 'invoice_id is required';
  end if;

  -- Load original invoice
  select *
  into v_inv
  from public.invoices
  where id = p_invoice_id;

  if not found then
    raise exception 'Invoice not found';
  end if;

  if v_inv.type::text = 'CREDIT_NOTE' then
    raise exception 'Cannot credit a CREDIT_NOTE';
  end if;

  if jsonb_typeof(v_inv.header_snapshot_json) = 'object' then
    v_base_hdr := v_inv.header_snapshot_json;
  end if;

  -- Original issued time (prefer invoice.issued_at_utc, else snapshot.issued_at_utc, else now)
  v_original_issued_at := v_inv.issued_at_utc;
  if v_original_issued_at is null and (v_base_hdr ? 'issued_at_utc') then
    begin
      v_original_issued_at := (v_base_hdr->>'issued_at_utc')::timestamptz;
    exception when others then
      v_original_issued_at := null;
    end;
  end if;
  if v_original_issued_at is null then
    v_original_issued_at := v_now;
  end if;

  v_anchor_ymd := (v_original_issued_at at time zone 'Europe/London')::date;

  -- Stationery key
  v_stationery_key := nullif(btrim(coalesce(v_base_hdr->>'stationery_key','')), '');
  if v_stationery_key is null then
    v_stationery_key := 'Assets/Stationery/Letterhead/A4/Letterhead_v1@300dpi.png';
  end if;

  if right(lower(v_stationery_key), 4) = '.pdf' then
    v_stationery_key := left(v_stationery_key, length(v_stationery_key) - 4) || '@300dpi.png';
  end if;

  while left(v_stationery_key, 1) = '/' loop
    v_stationery_key := substr(v_stationery_key, 2);
  end loop;

  -- Margins
  v_margins := v_base_hdr->'stationery_margins_mm';
  if jsonb_typeof(v_margins) = 'array' and jsonb_array_length(v_margins) = 4 then
    v_margins := jsonb_build_object(
      'top',    coalesce((v_margins->>0)::numeric, 32),
      'right',  coalesce((v_margins->>1)::numeric, 12),
      'bottom', coalesce((v_margins->>2)::numeric, 20),
      'left',   coalesce((v_margins->>3)::numeric, 12)
    );
  elsif jsonb_typeof(v_margins) = 'object' then
    v_margins := jsonb_build_object(
      'top',    coalesce((v_margins->>'top')::numeric, 32),
      'right',  coalesce((v_margins->>'right')::numeric, 12),
      'bottom', coalesce((v_margins->>'bottom')::numeric, 20),
      'left',   coalesce((v_margins->>'left')::numeric, 12)
    );
  else
    v_margins := jsonb_build_object('top',32,'right',12,'bottom',20,'left',12);
  end if;

  -- hide_bank_footer default TRUE
  if jsonb_typeof(v_base_hdr->'hide_bank_footer') = 'boolean' then
    v_hide_bank_footer := (v_base_hdr->>'hide_bank_footer')::boolean;
  else
    v_hide_bank_footer := true;
  end if;

  -- Bank + VAT registration
  if jsonb_typeof(v_base_hdr->'bank') = 'object' then
    v_bank := v_base_hdr->'bank';
  else
    v_bank := null;
  end if;

  v_vat_reg := nullif(btrim(coalesce(v_base_hdr->>'vat_registration_number','')), '');

  if v_bank is null or v_vat_reg is null then
    declare
      v_def record;
    begin
      select bank_name, bank_sort_code, bank_account_number, vat_registration_number
      into v_def
      from public.settings_defaults
      where id = 1
      limit 1;

      if v_bank is null then
        v_bank := jsonb_build_object(
          'name', v_def.bank_name,
          'sort_code', v_def.bank_sort_code,
          'account_number', v_def.bank_account_number
        );
      end if;

      if v_vat_reg is null then
        v_vat_reg := v_def.vat_registration_number;
      end if;
    end;
  end if;

  -- Client info
  v_client_name  := nullif(btrim(coalesce(v_base_hdr->>'client_name','')), '');
  v_client_addr  := nullif(btrim(coalesce(v_base_hdr->>'client_invoice_address','')), '');
  v_client_email := nullif(btrim(coalesce(v_base_hdr->>'client_primary_invoice_email','')), '');

  if jsonb_typeof(v_base_hdr->'vat_chargeable') = 'boolean' then
    v_vat_chargeable := (v_base_hdr->>'vat_chargeable')::boolean;
  else
    v_vat_chargeable := null;
  end if;

  if (v_base_hdr ? 'payment_terms_days') then
    begin
      v_terms_days := (v_base_hdr->>'payment_terms_days')::int;
    exception when others then
      v_terms_days := null;
    end;
  else
    v_terms_days := null;
  end if;

  if v_client_name is null or v_client_addr is null or v_vat_chargeable is null or v_terms_days is null then
    declare
      v_cli record;
    begin
      select name, invoice_address, primary_invoice_email, vat_chargeable, payment_terms_days
      into v_cli
      from public.clients
      where id = v_inv.client_id
      limit 1;

      if v_client_name is null then v_client_name := v_cli.name; end if;
      if v_client_addr is null then v_client_addr := v_cli.invoice_address; end if;
      if v_client_email is null then v_client_email := v_cli.primary_invoice_email; end if;

      if v_vat_chargeable is null then
        v_vat_chargeable := coalesce(v_cli.vat_chargeable, true);
      end if;

      if v_terms_days is null then
        v_terms_days := coalesce(v_cli.payment_terms_days, 30);
      end if;
    end;
  end if;

  -- VAT % (prefer original snapshot applied_vat_rate_pct; else compute anchored)
  v_applied_vat := null;
  if (v_base_hdr ? 'applied_vat_rate_pct') then
    begin
      v_applied_vat := (v_base_hdr->>'applied_vat_rate_pct')::numeric;
    exception when others then
      v_applied_vat := null;
    end;
  end if;

  if v_applied_vat is null then
    select coalesce(sf.vat_rate_pct, 20)
    into v_global_vat
    from public.settings_finance_pick(v_anchor_ymd) sf
    limit 1;

    select cs.vat_rate_pct
    into v_client_vat_override
    from public.client_settings cs
    where cs.client_id = v_inv.client_id
      and cs.effective_from <= v_anchor_ymd
    order by cs.effective_from desc
    limit 1;

    v_applied_vat := case
      when v_vat_chargeable = false then 0
      else coalesce(v_client_vat_override, v_global_vat, 20)
    end;
  else
    if v_vat_chargeable = false then
      v_applied_vat := 0;
    end if;
  end if;

  v_due_at := v_now + make_interval(days => coalesce(v_terms_days, 30));

  -- Create the credit note invoice row
  insert into public.invoices (
    client_id,
    type,
    status,
    status_date_utc,
    issued_at_utc,
    due_at_utc,
    subtotal_ex_vat,
    vat_amount,
    total_inc_vat,
    original_invoice_id,
    header_snapshot_json
  )
  values (
    v_inv.client_id,
    'CREDIT_NOTE'::public.invoice_type_enum,
    'ISSUED'::public.invoice_status_enum,
    v_now,
    v_now,
    v_due_at,
    0,
    0,
    0,
    v_inv.id,
    jsonb_build_object(
      'client_id', v_inv.client_id::text,
      'client_name', v_client_name,
      'client_invoice_address', v_client_addr,
      'client_primary_invoice_email', v_client_email,
      'vat_chargeable', coalesce(v_vat_chargeable, true),
      'applied_vat_rate_pct', coalesce(v_applied_vat, 0),
      'payment_terms_days', coalesce(v_terms_days, 30),
      'issued_at_utc', public._inv_iso_utc(v_now),
      'due_at_utc', public._inv_iso_utc(v_due_at),
      'stationery_key', v_stationery_key,
      'stationery_margins_mm', v_margins,
      'hide_bank_footer', v_hide_bank_footer,
      'bank', v_bank,
      'vat_registration_number', v_vat_reg,
      'meta', jsonb_build_object(
        'source', 'CREDIT_NOTE',
        'original_invoice_id', v_inv.id::text,
        'vat_anchor_ymd', v_anchor_ymd::text,
        'original_invoice_issued_at_utc', public._inv_iso_utc(v_original_issued_at)
      )
    )
  )
  returning id into v_credit_id;

  -- ✅ Insert negative mirror lines (one-for-one from original invoice_lines)
  insert into public.invoice_lines(
    invoice_id, timesheet_id, booking_id, description,
    hours_day, hours_night, hours_sat, hours_sun, hours_bh,
    pay_day, pay_night, pay_sat, pay_sun, pay_bh,
    charge_day, charge_night, charge_sat, charge_sun, charge_bh,
    total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
    vat_rate_pct, vat_amount, total_inc_vat,
    paper_ts_r2_key, meta_json, source_key
  )
  select
    v_credit_id,
    l.timesheet_id,
    l.booking_id,
    ('CREDIT NOTE – ' || coalesce(l.description,'')),

    l.hours_day, l.hours_night, l.hours_sat, l.hours_sun, l.hours_bh,

    l.pay_day, l.pay_night, l.pay_sat, l.pay_sun, l.pay_bh,
    l.charge_day, l.charge_night, l.charge_sat, l.charge_sun, l.charge_bh,

    public._inv_round2(-1 * coalesce(l.total_pay_ex_vat,0)),
    public._inv_round2(-1 * coalesce(l.total_charge_ex_vat,0)),
    public._inv_round2(-1 * coalesce(l.margin_ex_vat,0)),

    l.vat_rate_pct,
    public._inv_round2(-1 * coalesce(l.vat_amount,0)),
    public._inv_round2(-1 * coalesce(l.total_inc_vat,0)),

    l.paper_ts_r2_key,

    (coalesce(l.meta_json,'{}'::jsonb) ||
      jsonb_build_object(
        'credit_note', true,
        'original_invoice_id', v_inv.id::text,
        'original_invoice_line_id', l.id::text
      )
    ),

    ('CN:' || v_credit_id::text || ':LINE:' || l.id::text)
  from public.invoice_lines l
  where l.invoice_id = p_invoice_id;

  -- Update credit note totals from its lines
  select
    coalesce(sum(l2.total_charge_ex_vat),0)::numeric,
    coalesce(sum(l2.vat_amount),0)::numeric,
    coalesce(sum(l2.total_inc_vat),0)::numeric
  into v_cn_ex, v_cn_vat, v_cn_inc
  from public.invoice_lines l2
  where l2.invoice_id = v_credit_id;

  update public.invoices
  set
    subtotal_ex_vat = public._inv_round2(v_cn_ex),
    vat_amount      = public._inv_round2(v_cn_vat),
    total_inc_vat   = public._inv_round2(v_cn_inc),
    updated_at      = v_now
  where id = v_credit_id;

  -- Audit credit note creation (includes totals)
  perform public._audit_insert(
    'invoice',
    v_credit_id::text,
    'CREDIT_NOTE_CREATED',
    null,
    jsonb_build_object(
      'credit_note_id', v_credit_id::text,
      'original_invoice_id', v_inv.id::text,
      'subtotal_ex_vat', public._inv_round2(v_cn_ex),
      'vat_amount', public._inv_round2(v_cn_vat),
      'total_inc_vat', public._inv_round2(v_cn_inc)
    ),
    null,
    p_actor_user_id
  );

  -- Unlock snapshots locked by the original invoice
  select array_agg(distinct tf.timesheet_id)
  into v_ts_ids
  from public.timesheets_financials tf
  where tf.is_current = true
    and tf.locked_by_invoice_id = p_invoice_id
    and tf.timesheet_id is not null;

  unlocked_snapshots := coalesce(array_length(v_ts_ids, 1), 0);

  if unlocked_snapshots > 0 then
    update public.timesheets_financials tf
    set locked_by_invoice_id = null,
        locked_at_utc = null,
        unlocked_by_credit_note_id = v_credit_id,
        is_stale = true,
        stale_reason = 'UNLOCKED_BY_CREDIT',
        updated_at = v_now
    where tf.is_current = true
      and tf.locked_by_invoice_id = p_invoice_id;

    -- Enqueue recompute (batch, idempotent)
    insert into public.ts_financials_outbox(timesheet_id, reason, attempt_count, next_attempt_at, last_error, created_at)
    select
      x.timesheet_id,
      'VERSION_ROTATED'::public.ts_fin_reason_enum,
      0,
      v_now,
      null,
      v_now
    from (select unnest(v_ts_ids) as timesheet_id) x
    on conflict on constraint uq_tsfin_outbox do nothing;

    perform public._audit_insert(
      'invoice',
      v_credit_id::text,
      'CREDIT_NOTE_UNLOCKED_SNAPSHOTS',
      null,
      jsonb_build_object(
        'credit_note_id', v_credit_id::text,
        'original_invoice_id', v_inv.id::text,
        'timesheet_ids', to_jsonb(coalesce(v_ts_ids, array[]::uuid[])),
        'unlocked_count', unlocked_snapshots
      ),
      null,
      p_actor_user_id
    );
  end if;

  credit_note_id := v_credit_id;
  return next;
end;
$$;

-- CONTACT_PREPARER_UNIT 19 repeatable supabase/repeatable/30072026_1216_invoice_timesheet_refs_ward_selective_numbering.sql SHA256 7f490b9c50541b05eda94655aef5e29527249b4c948b8e7e711d014bba9797b6
\set ON_ERROR_STOP on

begin;

\set ON_ERROR_STOP on

select exists (
  select 1
  from public.invoice_operation_chunks
  where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT')
    and (
      (chunk_type='DOCUMENT_PLAN' and phase='BUILD_MANIFEST')
      or (chunk_type='ISSUE_INVOICE' and phase='FREEZE')
    )
) as invoice_presentation_active_work
\gset

\if :invoice_presentation_active_work
do $blocked$
begin
  raise exception 'INVOICE_PRESENTATION_SNAPSHOT_ACTIVE_WORK';
end;
$blocked$;
\else

create or replace function private._invoice_presentation_snapshot_batch(
    p_requests jsonb,
    p_now_utc timestamptz default null
)
returns table (
    request_key text,
    snapshot_schema_version text,
    presentation_model jsonb,
    timesheet_sources jsonb,
    supporting_sources jsonb,
    higher_rate_support jsonb,
    snapshot_json jsonb,
    snapshot_hash text,
    valid boolean,
    error_code text,
    error_detail jsonb
)
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
#variable_conflict use_column
declare
  v_now timestamptz := coalesce(p_now_utc, now());
begin
  if p_requests is null or jsonb_typeof(p_requests) is distinct from 'array' then
    raise exception using errcode='22023',
      message='p_requests must be a JSON array containing 1..100 requests';
  end if;

  if jsonb_array_length(p_requests) < 1
     or jsonb_array_length(p_requests) > 100 then
    raise exception using errcode='22023',
      message='p_requests must be a JSON array containing 1..100 requests';
  end if;

  return query
  with recursive raw_requests as materialized (
    select x.ordinality::integer request_no,
           x.value raw_request,
           nullif(btrim(coalesce(x.value->>'request_key','')),'') req_key,
           upper(nullif(btrim(coalesce(x.value->>'entity_type','')),'')) entity_type,
           case when coalesce(x.value->>'entity_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             then (x.value->>'entity_id')::uuid end entity_id,
           upper(nullif(btrim(coalesce(x.value->>'purpose','')),'')) purpose,
           coalesce(nullif(btrim(x.value->>'template_version'),''),'invoice-professional-v2') template_version,
           case when pg_input_is_valid(nullif(x.value->>'issue_at_utc',''),'timestamptz') then (x.value->>'issue_at_utc')::timestamptz end issue_at_utc,
           case when pg_input_is_valid(nullif(x.value->>'tax_point_utc',''),'timestamptz') then (x.value->>'tax_point_utc')::timestamptz end tax_point_utc,
           case when pg_input_is_valid(nullif(x.value->>'due_at_utc',''),'timestamptz') then (x.value->>'due_at_utc')::timestamptz end due_at_utc
    from jsonb_array_elements(p_requests) with ordinality x(value,ordinality)
  ),
  key_stats as materialized (
    select req_key,count(*)::integer key_count,min(request_no) first_request_no
    from raw_requests
    where req_key is not null
    group by req_key
  ),
  duplicate_key_results as materialized (
    select r.request_no,
           r.req_key request_key,
           'INVALID_PRESENTATION_REQUEST'::text snapshot_schema_version,
           '{}'::jsonb presentation_model,
           '[]'::jsonb timesheet_sources,
           '[]'::jsonb supporting_sources,
           jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support,
           jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',r.request_no,'request_key',r.req_key) snapshot_json,
           encode(digest(jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',r.request_no,'request_key',r.req_key)::text,'sha256'),'hex') snapshot_hash,
           false valid,
           'DUPLICATE_REQUEST_KEY'::text error_code,
           jsonb_build_object('request_no',r.request_no,'request_key',r.req_key,'duplicate_count',ks.key_count,'first_request_no',ks.first_request_no) error_detail
    from raw_requests r
    join key_stats ks on ks.req_key=r.req_key
    where ks.key_count > 1
  ),
  processable as materialized (
    select r.*
    from raw_requests r
    left join key_stats ks on ks.req_key=r.req_key
    where coalesce(ks.key_count,0) <= 1
  ),
  invalid_request_results as materialized (
    select p.request_no,
           coalesce(p.req_key,'__request_'||p.request_no::text) request_key,
           'INVALID_PRESENTATION_REQUEST'::text snapshot_schema_version,
           '{}'::jsonb presentation_model,
           '[]'::jsonb timesheet_sources,
           '[]'::jsonb supporting_sources,
           jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support,
           jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',p.request_no,'request_key',p.req_key) snapshot_json,
           encode(digest(jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',p.request_no,'request_key',p.req_key)::text,'sha256'),'hex') snapshot_hash,
           false valid,
           case
             when p.req_key is null then 'REQUEST_KEY_REQUIRED'
             when length(p.req_key) > 256 then 'REQUEST_KEY_TOO_LONG'
             when p.entity_type not in('INVOICE','TIMESHEET') then 'ENTITY_TYPE_UNSUPPORTED'
             when p.entity_id is null then 'ENTITY_ID_INVALID'
             when p.purpose not in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET') then 'PURPOSE_UNSUPPORTED'
             when p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null) then 'FINAL_ISSUE_DATES_REQUIRED'
             else 'PRESENTATION_REQUEST_INVALID' end error_code,
           jsonb_build_object('request_no',p.request_no,'entity_type',p.entity_type,'purpose',p.purpose) error_detail
    from processable p
    where p.req_key is null
       or length(p.req_key) > 256
       or p.entity_type not in('INVOICE','TIMESHEET')
       or p.entity_id is null
       or p.purpose not in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
       or (p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null))
  ),
  valid_requests as materialized (
    select p.*
    from processable p
    where p.req_key is not null and length(p.req_key) <= 256
      and p.entity_type in('INVOICE','TIMESHEET')
      and p.entity_id is not null
      and p.purpose in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
      and not (p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null))
  ),
  requested_invoices as materialized (
    select entity_id invoice_id from valid_requests where entity_type='INVOICE'
  ),
  reference_scope as materialized (
    select r.*
    from private._invoice_reference_rows_batch(
      coalesce((select array_agg(distinct invoice_id) from requested_invoices), array[]::uuid[])
    ) r
  ),
  invoice_line_base as materialized (
    select il.*,
           coalesce(nullif(btrim(vs.candidate_name),''),nullif(btrim(t.occupant_key_norm),'')) worker_name,
           coalesce(t.week_ending_date,
             case when pg_input_is_valid(nullif(il.meta_json->>'week_ending_date',''),'date')
               then (il.meta_json->>'week_ending_date')::date end)
             timesheet_week_ending_date,
           row_number() over(partition by il.invoice_id order by il.created_at,il.id)::integer base_display_order,
           case when pg_input_is_valid(nullif(il.meta_json->>'quantity',''),'numeric') then nullif(il.meta_json->>'quantity','')::numeric end meta_quantity,
           case when pg_input_is_valid(nullif(il.meta_json->>'units',''),'numeric') then nullif(il.meta_json->>'units','')::numeric end meta_units,
           case when il.timesheet_id is null
             then coalesce(nullif(btrim(il.meta_json->>'reference'),''),
               nullif(btrim(il.meta_json->>'po_number'),''))
             else refs.reference end canonical_reference,
           case when il.timesheet_id is null then 'CUSTOM_LINE'
             else coalesce(refs.reference_source,'NONE') end reference_source,
           case when il.timesheet_id is null then 'CUSTOM_LINE'
             else coalesce(refs.reference_scope,'TIMESHEET') end reference_scope,
           coalesce(refs.reference_source_row_keys,'[]'::jsonb)
             reference_source_row_keys,
           coalesce(refs.reference_required,false) reference_required
    from public.invoice_lines il
    left join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=il.timesheet_id
    left join lateral (
      select
        string_agg(x.current_reference,', ' order by x.first_row_key) reference,
        case when count(*)=1 then min(x.reference_source)
          else 'AGGREGATED_CANONICAL' end reference_source,
        case when count(*)=1 then min(x.reference_scope)
          else 'AGGREGATED_TIMESHEET' end reference_scope,
        jsonb_agg(x.row_key order by x.first_row_key) reference_source_row_keys,
        bool_or(x.is_required) reference_required
      from (
        select r.current_reference,min(r.row_key) first_row_key,
          min(r.row_key) row_key,
          min(case
            when r.ref_target='SEGMENT' then 'SEGMENT'
            when r.day_ymd is not null then 'DAY'
            else 'TIMESHEET' end) reference_source,
          min(case
            when r.ref_target='SEGMENT' then 'EXACT_SEGMENT'
            when r.day_ymd is not null then 'EXACT_DAY'
            else 'WHOLE_TIMESHEET' end) reference_scope,
          bool_or(r.is_required) is_required
        from reference_scope r
        where r.invoice_id=il.invoice_id and r.timesheet_id=il.timesheet_id
          and nullif(btrim(r.current_reference),'') is not null
        group by r.current_reference
      ) x
    ) refs on true
    where il.invoice_id in(select invoice_id from requested_invoices)
  ),
  invoice_line_component_raw as materialized (
    select b.invoice_id,b.id,b.created_at,
           (b.base_display_order*100+v.display_suffix)::integer base_display_order,
           coalesce(nullif(b.source_key,''),b.id::text)||':'||v.bucket row_key,
           v.label description,
           b.canonical_reference reference,b.reference_required,b.reference_scope,
           b.reference_source,b.reference_source_row_keys,
           'hours'::text unit,
           round(coalesce(v.hours,0),4) quantity_raw,
           round(coalesce(v.hours,0)*coalesce(v.rate,0),4) net_raw,
           round(coalesce(b.total_charge_ex_vat,0),2) line_net,
           round(coalesce(b.vat_amount,0),2) line_vat,
           coalesce(b.vat_rate_pct,0) vat_rate,
           b.source_key,b.id source_invoice_line_id,b.worker_name,
           b.timesheet_week_ending_date
    from invoice_line_base b
    cross join lateral (values
      ('DAY','Day',1,coalesce(b.hours_day,0),coalesce(b.charge_day,0)),
      ('NIGHT','Night',2,coalesce(b.hours_night,0),coalesce(b.charge_night,0)),
      ('SATURDAY','Saturday',3,coalesce(b.hours_sat,0),coalesce(b.charge_sat,0)),
      ('SUNDAY','Sunday',4,coalesce(b.hours_sun,0),coalesce(b.charge_sun,0)),
      ('BANK_HOLIDAY','Bank holiday',5,coalesce(b.hours_bh,0),coalesce(b.charge_bh,0))
    ) v(bucket,label,display_suffix,hours,rate)
    where coalesce(v.hours,0)<>0
    union all
    select b.invoice_id,b.id,b.created_at,(b.base_display_order*100+90)::integer,
           coalesce(nullif(b.source_key,''),b.id::text)||':'||lower(coalesce(nullif(b.meta_json->>'line_type',''),'residual')),
           case
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%MILEAGE%' then 'Mileage'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%TRAVEL%' then 'Travel'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ACCOMMODATION%' then 'Accommodation'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%HIGHER%' then 'Higher rate'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ADDITIONAL%' then 'Additional rate'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%REVERS%' then 'Reversal'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%CREDIT%' then 'Credit'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ADJUST%' then 'Adjustment'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%EXPENSE%' then 'Other expenses'
             else coalesce(nullif(b.description,''),'Invoice line') end,
           b.canonical_reference,b.reference_required,b.reference_scope,
           b.reference_source,b.reference_source_row_keys,
           case when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%MILEAGE%' then 'miles' else 'item' end,
           round(coalesce(b.meta_quantity,b.meta_units,1),4),
           round(coalesce(b.total_charge_ex_vat,0) - (
             coalesce(b.hours_day,0)*coalesce(b.charge_day,0)
             + coalesce(b.hours_night,0)*coalesce(b.charge_night,0)
             + coalesce(b.hours_sat,0)*coalesce(b.charge_sat,0)
             + coalesce(b.hours_sun,0)*coalesce(b.charge_sun,0)
             + coalesce(b.hours_bh,0)*coalesce(b.charge_bh,0)
           ),4),
           round(coalesce(b.total_charge_ex_vat,0),2),round(coalesce(b.vat_amount,0),2),coalesce(b.vat_rate_pct,0),b.source_key,b.id,b.worker_name,
           b.timesheet_week_ending_date
    from invoice_line_base b
    where abs(coalesce(b.total_charge_ex_vat,0) - (
      coalesce(b.hours_day,0)*coalesce(b.charge_day,0)
      + coalesce(b.hours_night,0)*coalesce(b.charge_night,0)
      + coalesce(b.hours_sat,0)*coalesce(b.charge_sat,0)
      + coalesce(b.hours_sun,0)*coalesce(b.charge_sun,0)
      + coalesce(b.hours_bh,0)*coalesce(b.charge_bh,0)
    )) > 0.004
       or not exists (
         select 1 from (values
           (coalesce(b.hours_day,0),coalesce(b.charge_day,0)),
           (coalesce(b.hours_night,0),coalesce(b.charge_night,0)),
           (coalesce(b.hours_sat,0),coalesce(b.charge_sat,0)),
           (coalesce(b.hours_sun,0),coalesce(b.charge_sun,0)),
           (coalesce(b.hours_bh,0),coalesce(b.charge_bh,0))
         ) nonzero(h,a) where coalesce(h,0)<>0 or coalesce(a,0)<>0)
  ),
  invoice_line_component_ranked as materialized (
    select r.*,
      row_number() over(partition by r.id order by r.base_display_order,r.row_key)::integer component_no,
      count(*) over(partition by r.id)::integer component_count,
      case when coalesce(r.line_net,0)<>0 then r.line_vat * r.net_raw / r.line_net
           else r.line_vat / nullif(count(*) over(partition by r.id),0) end raw_vat
    from invoice_line_component_raw r
  ),
  invoice_line_components as materialized (
    select q.invoice_id,q.id,q.created_at,q.base_display_order,q.row_key,q.description,
           q.reference,q.reference_required,q.reference_scope,q.reference_source,
           q.reference_source_row_keys,q.unit,
           q.quantity_raw quantity,
           case when q.quantity_raw<>0 then round(q.net_amount/q.quantity_raw,4) else q.net_amount end unit_price,
           q.net_amount,q.vat_rate,q.vat_amount,round(q.net_amount+q.vat_amount,2) gross_amount,
           q.source_key,q.source_invoice_line_id,q.worker_name,
           q.timesheet_week_ending_date
    from (
      select r.*,
        case when r.component_no=r.component_count
          then round(r.line_net - coalesce(sum(round(r.net_raw,2)) over(partition by r.id order by r.component_no rows between unbounded preceding and 1 preceding),0),2)
          else round(r.net_raw,2) end net_amount,
        case when r.component_no=r.component_count
          then round(r.line_vat - coalesce(sum(round(coalesce(r.raw_vat,0),2)) over(partition by r.id order by r.component_no rows between unbounded preceding and 1 preceding),0),2)
          else round(coalesce(r.raw_vat,0),2) end vat_amount
      from invoice_line_component_ranked r
    ) q
  ),
  invoice_line_rows as materialized (
    select c.invoice_id,
           jsonb_agg(jsonb_build_object(
             'row_key',c.row_key,
             'source_invoice_line_id',c.source_invoice_line_id,
             'source_key',coalesce(c.source_key,c.source_invoice_line_id::text),
             'description',c.description,
             'worker',c.worker_name,
             'week_ending_date',c.timesheet_week_ending_date,
             'reference',c.reference,
             'reference_required',c.reference_required,
             'reference_scope',c.reference_scope,
             'reference_source',c.reference_source,
             'reference_source_row_keys',c.reference_source_row_keys,
             'unit',c.unit,
             'quantity',c.quantity::text,
             'unit_price',c.unit_price::text,
             'net_amount',c.net_amount::text,
             'vat_rate',c.vat_rate::text,
             'vat_amount',c.vat_amount::text,
             'gross_amount',c.gross_amount::text,
             'display_order',c.base_display_order
           ) order by c.created_at,c.id,c.base_display_order) lines,
           round(sum(c.net_amount),2) line_net,
           round(sum(c.vat_amount),2) line_vat,
           round(sum(c.gross_amount),2) line_gross
    from invoice_line_components c
    group by c.invoice_id
  ),
  timesheet_targets as materialized (
    select distinct il.invoice_id,t.timesheet_id
    from requested_invoices ri
    join public.invoice_lines il on il.invoice_id=ri.invoice_id
      and il.timesheet_id is not null
    join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    union
    select null::uuid,vr.entity_id
    from valid_requests vr
    where vr.entity_type='TIMESHEET'
  ),
  timesheet_base as materialized (
    select target.invoice_id,t.timesheet_id,t.document_revision,
      upper(coalesce(t.sheet_scope::text,'')) sheet_scope,
      upper(coalesce(t.submission_mode::text,'')) submission_mode,
      t.contract_id,t.week_ending_date,
      t.worked_start_iso,t.worked_end_iso,t.break_start_iso,t.break_end_iso,
      coalesce(t.break_minutes,0) break_minutes,t.actual_schedule_json,
      t.day_references_json,t.reference_number,t.additional_units_week,
      t.additional_units_per_day,t.authorised_at_server,t.auth_name,
      t.auth_job_title,t.r2_nurse_key,t.r2_auth_key,t.img_sha256_nurse,
      t.img_sha256_auth,t.qr_status::text qr_status,t.qr_token,
      t.qr_payload_json,t.qr_signed_hash,t.qr_signed_at_utc,
      coalesce(vs.candidate_id,tf.candidate_id,ct.candidate_id) candidate_id,
      coalesce(vs.client_id,tf.client_id,ct.client_id) client_id,
      coalesce(nullif(btrim(cand.first_name),''),
        split_part(coalesce(vs.candidate_name,t.occupant_key_norm,''),' ',1))
        candidate_first_name,
      coalesce(nullif(btrim(cand.last_name),''),
        nullif(btrim(regexp_replace(
          coalesce(vs.candidate_name,t.occupant_key_norm,''),
          '^[^ ]+[ ]*','','g')),'')) candidate_surname,
      coalesce(nullif(btrim(tf.role),''),nullif(btrim(t.job_title_norm),''),
        nullif(btrim(ct.role),'')) job_profile_title,
      coalesce(nullif(btrim(cl.name),''),nullif(btrim(vs.client_name),''),
        nullif(btrim(t.hospital_norm),'')) client_name,
      nullif(lower(btrim(t.hospital_norm)),'') hospital_norm,
      nullif(lower(btrim(t.ward_norm)),'') ward_norm,
      coalesce(
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.hospital_norm),''))),
            '\mSt Richards\M','St Richard''s','g'),
          '\mNhs\M','NHS','g'),
        nullif(btrim(cl.name),''),
        nullif(btrim(vs.client_name),'')) hospital,
      regexp_replace(
        regexp_replace(
          initcap(lower(nullif(btrim(t.ward_norm),''))),
          '\mNhs\M','NHS','g'),
        '\mIcu\M','ICU','g') ward_display,
      concat_ws(' - ',
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.hospital_norm),''))),
            '\mSt Richards\M','St Richard''s','g'),
          '\mNhs\M','NHS','g'),
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.ward_norm),''))),
            '\mNhs\M','NHS','g'),
          '\mIcu\M','ICU','g')) site_ward,
      coalesce(nullif(btrim(tf.band),''),nullif(btrim(t.band),'')) band,
      coalesce(tf.invoice_breakdown_json,'{}'::jsonb) invoice_breakdown_json,
      coalesce(tf.additional_units_json,
        tf.invoice_breakdown_json#>'{additional,units}',
        '{}'::jsonb) additional_units_json,
      coalesce((authority.settings_json#>>'{values,week_ending_weekday}')::integer,0)
        configured_week_ending_weekday,
      coalesce(pc.require_reference_to_invoice,false)
        or coalesce(pc.reference_number_required_to_issue_invoice,false)
        reference_required,
      sd.agency_name,
      case
        when nullif(coalesce(
          sd.invoice_document_presentation_json#>>'{branding,logo,r2_key}',
          sd.import_config_json#>>'{invoice_document_presentation,branding,logo,r2_key}'),'') is null
          then '{}'::jsonb
        else jsonb_build_object(
          'r2_key',coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,r2_key}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,r2_key}'),
          'sha256',lower(coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,sha256}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,sha256}')),
          'size_bytes',case when coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}',
            '')~'^[1-9][0-9]{0,18}$' then coalesce(
              sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
              sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}')::bigint end,
          'media_type',lower(coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,media_type}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,media_type}')))
      end logo_identity,
      coalesce(sd.timesheet_header_json,'{}'::jsonb) header_wording,
      coalesce(sd.timesheet_footer_json,'{}'::jsonb) footer_wording,
      coalesce(sd.temporary_worker_declaration_json,'{}'::jsonb)
        temporary_worker_declaration,
      coalesce(sd.client_declaration_json,'{}'::jsonb) client_declaration
    from timesheet_targets target
    join public.timesheets t on t.timesheet_id=target.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=t.timesheet_id
    left join public.contracts ct on ct.id=t.contract_id
    left join public.candidates cand on cand.id=coalesce(vs.candidate_id,ct.candidate_id)
    left join public.clients cl on cl.id=coalesce(vs.client_id,ct.client_id)
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=t.timesheet_id
    left join lateral (
      select tf0.*
      from public.timesheets_financials tf0
      where tf0.timesheet_id=t.timesheet_id and tf0.is_current
      order by tf0.computed_at_utc desc nulls last,tf0.created_at desc nulls last,
        tf0.updated_at desc nulls last,tf0.id desc
      limit 1
    ) tf on true
    cross join lateral (
      select private._timesheet_settings_authority_frozen_v1(t.timesheet_id)
        as settings_json
    ) authority
    cross join public.settings_defaults sd
    where sd.id=1
  ),
  timesheet_number_fnv(
    invoice_id,timesheet_id,source_text,character_no,fnv_hash
  ) as (
    select b.invoice_id,b.timesheet_id,b.timesheet_id::text,1::integer,
      2166136261::bigint
    from timesheet_base b
    union all
    select h.invoice_id,h.timesheet_id,h.source_text,h.character_no+1,
      mod(
        ((h.fnv_hash # ascii(substr(
          h.source_text,h.character_no,1))::bigint)*16777619::bigint),
        4294967296::bigint)
    from timesheet_number_fnv h
    where h.character_no<=length(h.source_text)
  ),
  timesheet_week_context as materialized (
    select b.*,
      coalesce(b.week_ending_date,
        (b.worked_start_iso at time zone 'Europe/London')::date+
          ((b.configured_week_ending_weekday-
            extract(dow from (b.worked_start_iso at time zone
              'Europe/London')::date)::integer+7)%7)) resolved_week_ending_date
    from timesheet_base b
  ),
  timesheet_schedule_source as materialized (
    select b.invoice_id,b.timesheet_id,s.ordinality::integer source_order,s.value row_json
    from timesheet_week_context b
    cross join lateral jsonb_array_elements(
      case
        when upper(coalesce(b.invoice_breakdown_json->>'mode',''))='SEGMENTS'
          and jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
          then b.invoice_breakdown_json->'segments'
        when jsonb_typeof(b.actual_schedule_json)='array'
          then b.actual_schedule_json
        else '[]'::jsonb
      end) with ordinality s(value,ordinality)
    union all
    select b.invoice_id,b.timesheet_id,1,jsonb_build_object(
      'date',(b.worked_start_iso at time zone 'Europe/London')::date,
      'start_utc',b.worked_start_iso,'end_utc',b.worked_end_iso,
      'break_start',case when b.break_start_iso is not null
        then to_char(b.break_start_iso at time zone 'Europe/London','HH24:MI') end,
      'break_end',case when b.break_end_iso is not null
        then to_char(b.break_end_iso at time zone 'Europe/London','HH24:MI') end,
      'break_minutes',b.break_minutes,'ref_num',b.reference_number)
    from timesheet_week_context b
    where b.sheet_scope='DAILY'
      and not exists(
        select 1 from jsonb_array_elements(
          case
            when upper(coalesce(b.invoice_breakdown_json->>'mode',''))='SEGMENTS'
              and jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
              then b.invoice_breakdown_json->'segments'
            when jsonb_typeof(b.actual_schedule_json)='array'
              then b.actual_schedule_json
            else '[]'::jsonb
          end) existing)
  ),
  timesheet_schedule_normalised as materialized (
    select s.*,b.resolved_week_ending_date,b.reference_required,
      coalesce(nullif(btrim(s.row_json->>'segment_id'),''),
        case when nullif(btrim(s.row_json->>'start_utc'),'') is not null
          and nullif(btrim(s.row_json->>'end_utc'),'') is not null
          then 'SE:'||(s.row_json->>'start_utc')||'|'||
            (s.row_json->>'end_utc') end,
        'ts:'||s.timesheet_id::text||':'||(s.source_order-1)::text) segment_id,
      coalesce(nullif(btrim(s.row_json->>'date'),''),
        nullif(btrim(s.row_json->>'day'),''),
        case when pg_input_is_valid(nullif(coalesce(
            s.row_json->>'worked_start',s.row_json->>'start_utc'),''),
            'timestamptz')
          then (coalesce(s.row_json->>'worked_start',
            s.row_json->>'start_utc')::timestamptz at time zone
              'Europe/London')::date::text end,
        case when b.sheet_scope='DAILY'
          then (b.worked_start_iso at time zone 'Europe/London')::date::text end)
        work_date,
      coalesce(nullif(btrim(s.row_json->>'worked_start'),''),
        nullif(btrim(s.row_json->>'start_utc'),''),
        nullif(btrim(s.row_json->>'start'),'')) worked_start,
      coalesce(nullif(btrim(s.row_json->>'worked_end'),''),
        nullif(btrim(s.row_json->>'end_utc'),''),
        nullif(btrim(s.row_json->>'end'),'')) worked_end,
      case
        when nullif(btrim(s.row_json->>'break_start'),'') is not null
          and nullif(btrim(s.row_json->>'break_end'),'') is not null
          then 'EXPLICIT_INTERVAL'
        when coalesce(s.row_json->>'break_minutes',
            s.row_json->>'break_mins','')~'^[0-9]{1,5}$'
          and coalesce(s.row_json->>'break_minutes',
            s.row_json->>'break_mins')::integer>0
          then 'MINUTES_ONLY'
        else 'NONE' end break_display_mode,
      case when coalesce(s.row_json->>'break_minutes',
          s.row_json->>'break_mins','')~'^[0-9]{1,5}$'
        then coalesce(s.row_json->>'break_minutes',
          s.row_json->>'break_mins')::integer else 0 end break_minutes,
      coalesce(nullif(btrim(s.row_json->>'ref_num'),''),
        nullif(btrim(s.row_json->>'reference'),'')) source_reference
    from timesheet_schedule_source s
    join timesheet_week_context b
      on b.invoice_id is not distinct from s.invoice_id
     and b.timesheet_id=s.timesheet_id
  ),
  timesheet_schedule_rows as materialized (
    select s.invoice_id,s.timesheet_id,s.source_order,s.segment_id,s.work_date,
      jsonb_build_object(
        'row_key',s.timesheet_id::text||'|SEGMENT|'||s.segment_id||'|'||
          coalesce(s.work_date,''),
        'display_order',row_number() over(
          partition by s.invoice_id,s.timesheet_id,s.work_date
          order by
            case when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
              then s.worked_start::timestamptz end nulls last,
            s.worked_start,s.segment_id,s.source_order),
        'segment_id',s.segment_id,
        'date',s.work_date,
        'worked_start_utc',case when pg_input_is_valid(
          nullif(s.worked_start,''),'timestamptz')
          then s.worked_start::timestamptz end,
        'worked_end_utc',case when pg_input_is_valid(
          nullif(s.worked_end,''),'timestamptz')
          then s.worked_end::timestamptz end,
        'display_start_local',case
          when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
            then to_char(s.worked_start::timestamptz at time zone
              'Europe/London','HH24:MI')
          when s.worked_start~'^[0-2][0-9]:[0-5][0-9]' then left(s.worked_start,5)
          end,
        'display_end_local',case
          when pg_input_is_valid(nullif(s.worked_end,''),'timestamptz')
            then to_char(s.worked_end::timestamptz at time zone
              'Europe/London','HH24:MI')
          when s.worked_end~'^[0-2][0-9]:[0-5][0-9]' then left(s.worked_end,5)
          end,
        'break_start_local',nullif(btrim(s.row_json->>'break_start'),''),
        'break_end_local',nullif(btrim(s.row_json->>'break_end'),''),
        'break_minutes',s.break_minutes,
        'break_display_mode',s.break_display_mode,
        'bucket_hours',jsonb_build_object(
          'DAY',coalesce(s.row_json->'hours_day','0'::jsonb),
          'NIGHT',coalesce(s.row_json->'hours_night','0'::jsonb),
          'SATURDAY',coalesce(s.row_json->'hours_sat','0'::jsonb),
          'SUNDAY',coalesce(s.row_json->'hours_sun','0'::jsonb),
          'BANK_HOLIDAY',coalesce(s.row_json->'hours_bh','0'::jsonb)),
        'paid_minutes',coalesce(
          case when (select sum(case when coalesce(v,'')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
              then v::numeric else 0 end)
            from(values(s.row_json->>'hours_day'),
              (s.row_json->>'hours_night'),(s.row_json->>'hours_sat'),
              (s.row_json->>'hours_sun'),(s.row_json->>'hours_bh')) h(v))>0
            then round(60*(select sum(case when coalesce(v,'')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
              then v::numeric else 0 end)
              from(values(s.row_json->>'hours_day'),
                (s.row_json->>'hours_night'),(s.row_json->>'hours_sat'),
                (s.row_json->>'hours_sun'),(s.row_json->>'hours_bh')) h(v)))::integer
          end,
          case when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
              and pg_input_is_valid(nullif(s.worked_end,''),'timestamptz')
            then greatest(0,round(extract(epoch from(
              s.worked_end::timestamptz-s.worked_start::timestamptz))/60)
                -s.break_minutes)::integer end,
          case when coalesce(s.row_json->>'hours',
              s.row_json->>'units','')~
                '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
            then round(coalesce(s.row_json->>'hours',
              s.row_json->>'units')::numeric*60)::integer end),
        'band',b.band,
        'booking_reference',coalesce(
          (select rs.current_reference from reference_scope rs
            where rs.invoice_id=s.invoice_id
              and rs.timesheet_id=s.timesheet_id
              and rs.segment_id=s.segment_id
              and nullif(rs.current_reference,'') is not null
            order by rs.row_key limit 1),
          s.source_reference,
          (select rs.current_reference from reference_scope rs
            where rs.invoice_id=s.invoice_id
              and rs.timesheet_id=s.timesheet_id
              and rs.day_ymd=s.work_date
              and nullif(rs.current_reference,'') is not null
            order by rs.row_key limit 1),
          case when jsonb_typeof(b.day_references_json)='object'
            then coalesce(
              b.day_references_json#>>array[s.work_date,'reference'],
              b.day_references_json#>>array[s.work_date,'ref_num'],
              b.day_references_json->>s.work_date) end,
          nullif(b.reference_number,'')),
        'reference_required',b.reference_required,
        'reference_source',case
          when exists(select 1 from reference_scope rs
            where rs.invoice_id=s.invoice_id and rs.timesheet_id=s.timesheet_id
              and rs.segment_id=s.segment_id
              and nullif(rs.current_reference,'') is not null) then 'SEGMENT'
          when nullif(s.source_reference,'') is not null then 'SEGMENT_SOURCE'
          when exists(select 1 from reference_scope rs
            where rs.invoice_id=s.invoice_id and rs.timesheet_id=s.timesheet_id
              and rs.day_ymd=s.work_date
              and nullif(rs.current_reference,'') is not null) then 'DAY'
          when nullif(b.reference_number,'') is not null then 'TIMESHEET'
          else 'NONE' end,
        'reference_row_key',coalesce(
          (select rs.row_key from reference_scope rs
            where rs.invoice_id=s.invoice_id and rs.timesheet_id=s.timesheet_id
              and rs.segment_id=s.segment_id order by rs.row_key limit 1),
          s.timesheet_id::text||'|SEGMENT|'||s.segment_id||'|'||
            coalesce(s.work_date,'')))
        shift_model
    from timesheet_schedule_normalised s
    join timesheet_week_context b
      on b.invoice_id is not distinct from s.invoice_id
     and b.timesheet_id=s.timesheet_id
  ),
  timesheet_current_additional_rows as materialized (
    select b.invoice_id,b.timesheet_id,d.code,d.unit_date,d.quantity
    from timesheet_week_context b
    cross join lateral (
      select upper(day_unit.key) code,day_value.key unit_date,
        (day_value.value#>>'{}')::numeric quantity
      from jsonb_each(case
        when jsonb_typeof(b.additional_units_per_day)='object'
          then b.additional_units_per_day else '{}'::jsonb end) day_unit(key,value)
      cross join lateral jsonb_each(case
        when jsonb_typeof(day_unit.value)='object'
          then day_unit.value else '{}'::jsonb end) day_value(key,value)
      where coalesce(day_value.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
        and (day_value.value#>>'{}')::numeric<>0
      union all
      select upper(week_unit.key),null::text,
        (week_unit.value#>>'{}')::numeric
      from jsonb_each(case
        when jsonb_typeof(b.additional_units_week)='object'
          then b.additional_units_week else '{}'::jsonb end) week_unit(key,value)
      where coalesce(week_unit.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
        and (week_unit.value#>>'{}')::numeric<>0
        and not exists(
          select 1
          from jsonb_each(case
            when jsonb_typeof(b.additional_units_per_day)='object'
              then b.additional_units_per_day else '{}'::jsonb end) per_day(code,value)
          cross join lateral jsonb_each(case
            when jsonb_typeof(per_day.value)='object'
              then per_day.value else '{}'::jsonb end) per_value(day,value)
          where upper(per_day.code)=upper(week_unit.key)
            and coalesce(per_value.value#>>'{}','')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
            and (per_value.value#>>'{}')::numeric<>0)
    ) d
  ),
  timesheet_additional_rows as materialized (
    select b.invoice_id,b.timesheet_id,a.key code,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) rate_type,
      nullif(d.key,'') unit_date,
      case
        when d.key is not null and coalesce(d.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(d.value#>>'{}')::numeric
        when d.key is null and coalesce(a.value->>'unit_count','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(a.value->>'unit_count')::numeric
      end quantity,
      coalesce(nullif(a.value->>'unit_name',''),'unit') unit_name,
      case when d.key is null then 'WEEKLY' else 'PER_DAY' end frequency,
      case when coalesce(a.value->>'configured_display_order',
          a.value->>'display_order','')~'^[0-9]{1,9}$'
        then coalesce(a.value->>'configured_display_order',
          a.value->>'display_order')::integer else 2147483647 end configured_order
    from timesheet_week_context b
    cross join lateral jsonb_each(case
      when jsonb_typeof(b.additional_units_json)='object'
        then b.additional_units_json else '{}'::jsonb end) a(key,value)
    left join lateral jsonb_each(case
      when jsonb_typeof(a.value->'days')='object' and a.value->'days'<>'{}'::jsonb
        then a.value->'days' else '{}'::jsonb end) d(key,value) on true
    where jsonb_typeof(a.value)='object'
      and case
        when d.key is not null and coalesce(d.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(d.value#>>'{}')::numeric<>0
        when d.key is null and coalesce(a.value->>'unit_count','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(a.value->>'unit_count')::numeric<>0
        else false end
  ),
  timesheet_additional_staleness as materialized (
    select b.invoice_id,b.timesheet_id,
      exists(
        (select upper(c.code),c.unit_date,trim_scale(c.quantity)
         from timesheet_current_additional_rows c
         where c.invoice_id is not distinct from b.invoice_id
           and c.timesheet_id=b.timesheet_id
         except
         select upper(a.code),a.unit_date,trim_scale(a.quantity)
         from timesheet_additional_rows a
         where a.invoice_id is not distinct from b.invoice_id
           and a.timesheet_id=b.timesheet_id)
        union all
        (select upper(a.code),a.unit_date,trim_scale(a.quantity)
         from timesheet_additional_rows a
         where a.invoice_id is not distinct from b.invoice_id
           and a.timesheet_id=b.timesheet_id
         except
         select upper(c.code),c.unit_date,trim_scale(c.quantity)
         from timesheet_current_additional_rows c
         where c.invoice_id is not distinct from b.invoice_id
           and c.timesheet_id=b.timesheet_id)
      ) snapshot_stale
    from timesheet_week_context b
  ),
  timesheet_v2_models as materialized (
    select b.invoice_id,b.timesheet_id,
      jsonb_build_object(
        'schema_version','TIMESHEET_RENDER_MODEL_V2',
        'template_version','timesheet-professional-v2',
        'layout_contract_version','TIMESHEET_ONE_PAGE_LANDSCAPE_V2',
        'timesheet_id',b.timesheet_id,
        'document_revision',b.document_revision,
        'timesheet_number',coalesce((
          select lpad((h.fnv_hash%100000000)::text,8,'0')
          from timesheet_number_fnv h
          where h.invoice_id is not distinct from b.invoice_id
            and h.timesheet_id=b.timesheet_id
            and h.character_no=length(h.source_text)+1
          limit 1),'00000000'),
        'sheet_scope',b.sheet_scope,
        'form_variant',case
          when b.submission_mode='MANUAL' and upper(coalesce(b.qr_status,''))='PENDING'
            then 'QR_UNSIGNED'
          when b.submission_mode='ELECTRONIC'
            and b.authorised_at_server is not null
            and nullif(b.r2_nurse_key,'') is not null
            and nullif(b.r2_auth_key,'') is not null
            then 'ELECTRONIC_SIGNED'
          else 'ELECTRONIC_UNSIGNED' end,
        'submission_mode',b.submission_mode,
        'locale','en-GB','time_zone','Europe/London',
        'week_period',jsonb_build_object(
          'start_date',b.resolved_week_ending_date-6,
          'end_date',b.resolved_week_ending_date,
          'end_weekday_index',extract(dow from b.resolved_week_ending_date)::integer,
          'end_weekday_name',trim(to_char(b.resolved_week_ending_date,'Day')),
          'start_weekday_name',trim(to_char(b.resolved_week_ending_date-6,'Day')),
          'source',case when b.week_ending_date is not null
            then 'TIMESHEET_WEEK_ENDING_DATE'
            else 'TIMESHEET_SETTINGS_AUTHORITY' end,
          'configured_week_ending_weekday',b.configured_week_ending_weekday,
          'days',(select jsonb_agg(jsonb_build_object(
            'row_key','day:'||d.day_date::text,
            'display_order',d.display_order,
            'date',d.day_date,
            'weekday_index',extract(dow from d.day_date)::integer,
            'weekday_name',trim(to_char(d.day_date,'Day')),
            'weekday_abbreviation',trim(to_char(d.day_date,'Dy')),
            'shift_lines',coalesce((select jsonb_agg(r.shift_model order by
              (r.shift_model->>'display_order')::integer,r.source_order)
              from timesheet_schedule_rows r
              where r.invoice_id is not distinct from b.invoice_id
                and r.timesheet_id=b.timesheet_id
                and r.work_date=d.day_date::text),'[]'::jsonb))
            order by d.display_order)
            from(select (b.resolved_week_ending_date-7+g)::date day_date,
                g::integer display_order
              from generate_series(1,7) g) d)),
        'worker',jsonb_build_object(
          'first_name',b.candidate_first_name,
          'surname',b.candidate_surname,
          'job_profile_title',b.job_profile_title),
        'client',jsonb_build_object(
          'name',b.client_name,
          'hospital_norm',b.hospital_norm,
          'ward_norm',b.ward_norm,
          'hospital',b.hospital,
          'hospital_display',b.hospital,
          'ward_display',b.ward_display,
          'site_ward',b.site_ward,
          'hospital_ward_display',b.site_ward),
        'band',b.band,
        'branding',jsonb_build_object(
          'agency_name',coalesce(nullif(b.agency_name,''),'ARMS'),
          'logo',b.logo_identity),
        'wording',jsonb_build_object(
          'header',b.header_wording,'footer',b.footer_wording,
          'temporary_worker_declaration',b.temporary_worker_declaration,
          'client_declaration',b.client_declaration),
        'presentation_settings_hash',encode(digest(jsonb_build_object(
          'agency_name',b.agency_name,'logo',b.logo_identity,
          'header',b.header_wording,'footer',b.footer_wording,
          'temporary_worker_declaration',b.temporary_worker_declaration,
          'client_declaration',b.client_declaration)::text,'sha256'),'hex'),
        'additional_units_section',jsonb_build_object(
          'schema_version','TIMESHEET_ADDITIONAL_UNITS_V1',
          'visible',exists(select 1 from timesheet_additional_rows a
            where a.invoice_id is not distinct from b.invoice_id
              and a.timesheet_id=b.timesheet_id),
          'title','Additional rates / units',
          'column_labels',jsonb_build_object(
            'rate_type','Rate Type','date','Date',
            'quantity','Quantity','unit','Unit'),
          'minimum_blank_space_rows',1,
          'rows',coalesce((select jsonb_agg(jsonb_build_object(
            'row_key','additional:'||a.code||':'||coalesce(a.unit_date,'weekly'),
            'display_order',a.display_order,'code',a.code,
            'rate_type',a.rate_type,'date',a.unit_date,
            'quantity',trim_scale(a.quantity),'unit',a.unit_name,
            'frequency',a.frequency) order by a.display_order)
            from(select a0.*,row_number() over(order by a0.configured_order,
                a0.code,a0.unit_date nulls last)::integer display_order
              from timesheet_additional_rows a0
              where a0.invoice_id is not distinct from b.invoice_id
                and a0.timesheet_id=b.timesheet_id) a),'[]'::jsonb)),
        'additional_units_snapshot_stale',coalesce((
          select s.snapshot_stale
          from timesheet_additional_staleness s
          where s.invoice_id is not distinct from b.invoice_id
            and s.timesheet_id=b.timesheet_id),false),
        'totals',jsonb_build_object(
          'paid_minutes',coalesce((select sum(
            (r.shift_model->>'paid_minutes')::numeric)
            from timesheet_schedule_rows r
            where r.invoice_id is not distinct from b.invoice_id
              and r.timesheet_id=b.timesheet_id),0)),
        'authorisation',jsonb_build_object(
          'authorised',b.authorised_at_server is not null,
          'name',b.auth_name,'role',b.auth_job_title,
          'authorised_at_utc',b.authorised_at_server),
        'signatures',jsonb_build_object(
          'candidate',case when nullif(b.r2_nurse_key,'') is null then '{}'::jsonb
            else jsonb_build_object('r2_key',b.r2_nurse_key,
              'sha256',lower(b.img_sha256_nurse),'size_bytes',null,
              'media_type','image/png',
              'signed_date',b.authorised_at_server::date) end,
          'authoriser',case when nullif(b.r2_auth_key,'') is null then '{}'::jsonb
            else jsonb_build_object('r2_key',b.r2_auth_key,
              'sha256',lower(b.img_sha256_auth),'size_bytes',null,
              'media_type','image/png',
              'signed_date',b.authorised_at_server::date) end),
        'qr',jsonb_build_object(
          'required',b.submission_mode='MANUAL'
            and upper(coalesce(b.qr_status,''))='PENDING',
          'signed',b.qr_signed_hash is not null,
          'status',b.qr_status,'token',b.qr_token,
          'payload',case when jsonb_typeof(b.qr_payload_json)='object'
            then b.qr_payload_json else '{}'::jsonb end,
          'signed_hash',b.qr_signed_hash,'signed_at_utc',b.qr_signed_at_utc),
        'layout',jsonb_build_object(
          'one_page_required',true,
          'allowed_modes',jsonb_build_array('NORMAL','COMPACT','ULTRA'),
          'second_page_allowed',false,
          'minimum_font_size',5.5,
          'minimum_row_height_mm',3.45,
          'minimum_signature_height_mm',7,
          'minimum_additional_blank_rows',1),
        'week_period_hash',encode(digest(jsonb_build_object(
          'start_date',b.resolved_week_ending_date-6,
          'end_date',b.resolved_week_ending_date,
          'configured_week_ending_weekday',
            b.configured_week_ending_weekday)::text,'sha256'),'hex'),
        'reference_signature',encode(digest(coalesce((
          select string_agg((r.shift_model->>'reference_row_key')||'='||
            coalesce(r.shift_model->>'booking_reference',''),'||'
            order by r.work_date,(r.shift_model->>'display_order')::integer)
          from timesheet_schedule_rows r
          where r.invoice_id is not distinct from b.invoice_id
            and r.timesheet_id=b.timesheet_id),'') ,'sha256'),'hex'),
        'additional_units_hash',encode(digest(coalesce((
          select jsonb_agg(jsonb_build_object(
            'code',a.code,'date',a.unit_date,'quantity',a.quantity,
            'unit',a.unit_name) order by a.configured_order,a.code,
              a.unit_date nulls last)::text
          from timesheet_additional_rows a
          where a.invoice_id is not distinct from b.invoice_id
            and a.timesheet_id=b.timesheet_id),'[]'),'sha256'),'hex')
      ) render_model
    from timesheet_week_context b
  ),
  invoice_timesheet_rows as materialized (
    select il.invoice_id,t.timesheet_id,
      coalesce(v2.render_model,jsonb_build_object(
        'schema_version','TIMESHEET_RENDER_MODEL_V1',
        'timesheet_id',t.timesheet_id,
        'document_revision',t.document_revision,
        'candidate',jsonb_build_object('id',coalesce(vs.candidate_id::text,null),'name',coalesce(vs.candidate_name,t.occupant_key_norm)),
        'client',jsonb_build_object('id',coalesce(vs.client_id::text,null),'name',vs.client_name),
        'contract',jsonb_build_object('id',coalesce(t.contract_id::text,null),'reference',t.booking_id),
        'work',jsonb_build_object(
          'hospital',t.hospital_norm,
          'site',t.hospital_norm,
          'ward',t.ward_norm,
          'assignment',coalesce(
            nullif(btrim(t.job_title_norm),''),
            case when nullif(btrim(t.shift_label_norm),'') is not null
                   and length(t.shift_label_norm) <= 80
                   and t.shift_label_norm !~* '^weekly-correction-'
                   and t.shift_label_norm !~* '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
              then t.shift_label_norm end),
          'job_title',t.job_title_norm,
          'band',t.band,
          'shift_type',case when nullif(btrim(t.shift_label_norm),'') is not null
                              and length(t.shift_label_norm) <= 80
                              and t.shift_label_norm !~* '^weekly-correction-'
                              and t.shift_label_norm !~* '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
                         then t.shift_label_norm end),
        'week_ending_date',t.week_ending_date,
        'submission_mode',t.submission_mode::text,
        'sheet_scope',t.sheet_scope::text,
        'daily_schedule_rows',coalesce((
           select jsonb_agg(jsonb_build_object(
             'date',coalesce(s.value->>'date',s.value->>'day',to_char(t.worked_start_iso::date,'YYYY-MM-DD')),
             'scheduled_start',coalesce(s.value->>'scheduled_start',s.value->>'start',s.value->>'start_utc',t.scheduled_start_iso::text),
             'scheduled_end',coalesce(s.value->>'scheduled_end',s.value->>'end',s.value->>'end_utc',t.scheduled_end_iso::text),
             'worked_start',coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc',t.worked_start_iso::text),
             'worked_end',coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc',t.worked_end_iso::text),
             'break_start',coalesce(s.value->>'break_start',t.break_start_iso::text),
             'break_end',coalesce(s.value->>'break_end',t.break_end_iso::text),
             'break_minutes',case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$' then (coalesce(s.value->>'break_minutes',s.value->>'break_mins'))::integer else coalesce(t.break_minutes,0) end,
             'reference',coalesce(s.value->>'reference',s.value->>'ref_num',t.reference_number),
             'hours',coalesce(s.value->>'hours',s.value->>'units',case when t.worked_minutes is not null then round(t.worked_minutes::numeric/60,2)::text end),
             'units',coalesce(s.value->>'units',s.value->>'hours'),
             'display_order',s.ordinality)
             order by s.ordinality)
           from jsonb_array_elements(case when jsonb_typeof(t.actual_schedule_json)='array' then t.actual_schedule_json else '[]'::jsonb end) with ordinality s(value,ordinality)
           where upper(coalesce(t.sheet_scope::text,''))='DAILY'
        ), case when upper(coalesce(t.sheet_scope::text,''))='DAILY' then jsonb_build_array(jsonb_build_object(
             'date',t.worked_start_iso::date,'scheduled_start',t.scheduled_start_iso,'scheduled_end',t.scheduled_end_iso,
             'worked_start',t.worked_start_iso,'worked_end',t.worked_end_iso,
             'break_start',t.break_start_iso,'break_end',t.break_end_iso,'break_minutes',coalesce(t.break_minutes,0),
             'reference',t.reference_number,'hours',case when t.worked_minutes is not null then round(t.worked_minutes::numeric/60,2)::text end,'units',null,'display_order',1)) else '[]'::jsonb end),
        'weekly_schedule_rows',coalesce((
           select jsonb_agg(jsonb_build_object(
             'date',coalesce(s.value->>'date',s.value->>'day'),
             'scheduled_start',coalesce(s.value->>'scheduled_start',s.value->>'start',s.value->>'start_utc'),
             'scheduled_end',coalesce(s.value->>'scheduled_end',s.value->>'end',s.value->>'end_utc'),
             'worked_start',coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc'),
             'worked_end',coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc'),
             'break_start',s.value->>'break_start','break_end',s.value->>'break_end',
             'break_minutes',case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$' then (coalesce(s.value->>'break_minutes',s.value->>'break_mins'))::integer else 0 end,
             'reference',coalesce(s.value->>'reference',s.value->>'ref_num'),
             'hours',coalesce(
               s.value->>'hours',
               s.value->>'units',
               case when pg_input_is_valid(nullif(coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc'),''),'timestamptz')
                          and pg_input_is_valid(nullif(coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc'),''),'timestamptz')
                    then greatest(
                      0,
                      round((
                        extract(epoch from (
                          coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc')::timestamptz
                          - coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc')::timestamptz
                        )) / 60
                        - case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$'
                            then coalesce(s.value->>'break_minutes',s.value->>'break_mins')::numeric else 0 end
                      ) / 60,2)
                    )::text end),
             'units',coalesce(s.value->>'units',s.value->>'hours'),
             'display_order',s.ordinality)
             order by s.ordinality)
           from jsonb_array_elements(case when jsonb_typeof(t.actual_schedule_json)='array' then t.actual_schedule_json else '[]'::jsonb end) with ordinality s(value,ordinality)
           where upper(coalesce(t.sheet_scope::text,''))='WEEKLY'
        ),'[]'::jsonb),
        'references',jsonb_build_object(
          'whole',coalesce((select rs.current_reference from reference_scope rs where rs.invoice_id=il.invoice_id and rs.timesheet_id=t.timesheet_id and rs.segment_id is null and rs.day_ymd is null and nullif(rs.current_reference,'') is not null order by rs.row_key limit 1),nullif(t.reference_number,'')),
          'day',coalesce(
             (
               select jsonb_agg(
                 jsonb_build_object(
                   'day_key',ordered_reference.day_ymd,
                   'reference',ordered_reference.current_reference,
                   'display_order',ordered_reference.display_order
                 )
                 order by ordered_reference.display_order
               )
               from (
                 select
                   rs.day_ymd,
                   rs.current_reference,
                   row_number() over(order by rs.day_ymd,rs.row_key)::integer as display_order
                 from reference_scope rs
                 where rs.invoice_id=il.invoice_id
                   and rs.timesheet_id=t.timesheet_id
                   and rs.day_ymd is not null
                   and rs.segment_id is null
               ) ordered_reference
             ),
             (select jsonb_agg(jsonb_build_object('day_key',d.key,'reference',case when jsonb_typeof(d.value)='object' then coalesce(d.value->>'reference',d.value->>'ref_num',d.value->>'value') else trim(both '"' from d.value::text) end,'display_order',d.ordinality) order by d.ordinality) from jsonb_each(case when jsonb_typeof(t.day_references_json)='object' then t.day_references_json else '{}'::jsonb end) with ordinality d(key,value,ordinality)),
             '[]'::jsonb),
          'segment',coalesce(
            (
              select jsonb_agg(
                jsonb_build_object(
                  'segment_id',ordered_reference.segment_id,
                  'reference',ordered_reference.current_reference,
                  'display_order',ordered_reference.display_order
                )
                order by ordered_reference.display_order
              )
              from (
                select
                  rs.segment_id,
                  rs.current_reference,
                  row_number() over(order by rs.segment_id,rs.row_key)::integer as display_order
                from reference_scope rs
                where rs.invoice_id=il.invoice_id
                  and rs.timesheet_id=t.timesheet_id
                  and rs.segment_id is not null
              ) ordered_reference
            ),
            '[]'::jsonb
          )),
        'additional_units',coalesce((
          select jsonb_object_agg(
            au.key,
            case
              when jsonb_typeof(au.value)='number'
                then to_jsonb(trim_scale((au.value#>>'{}')::numeric)::text)
              else au.value
            end
            order by au.key
          )
          from jsonb_each(
            case when jsonb_typeof(t.additional_units_week)='object'
              then t.additional_units_week else '{}'::jsonb end
          ) au
        ),'{}'::jsonb),
        'authorisation',jsonb_build_object('authorised',t.authorised_at_server is not null,'name',t.auth_name,'role',t.auth_job_title,'authorised_at_utc',t.authorised_at_server),
        'signatures',jsonb_build_object(
          'candidate',case when nullif(t.r2_nurse_key,'') is null
            then jsonb_build_object('identity',coalesce(vs.candidate_name,t.occupant_key_norm),'role','Candidate / nurse')
            else jsonb_build_object('r2_key',t.r2_nurse_key,'sha256',t.img_sha256_nurse,'size_bytes',null,'media_type','image/png','identity',coalesce(vs.candidate_name,t.occupant_key_norm),'role','Candidate / nurse') end,
          'authoriser',case when nullif(t.r2_auth_key,'') is null
            then jsonb_build_object('identity',t.auth_name,'role',t.auth_job_title)
            else jsonb_build_object('r2_key',t.r2_auth_key,'sha256',t.img_sha256_auth,'size_bytes',null,'media_type','image/png','identity',t.auth_name,'role',t.auth_job_title) end),
        'qr',jsonb_build_object('required',t.qr_status is not null,'signed',t.qr_signed_hash is not null,'status',t.qr_status::text,'signed_hash',t.qr_signed_hash,'signed_at_utc',t.qr_signed_at_utc,'verification_summary',case when t.qr_signed_hash is not null then 'QR signature verified in frozen source' when t.qr_status is not null then t.qr_status::text else null end),
        'template_version','timesheet-professional-v1'
      )) render_model,
      t.submission_mode::text submission_mode,t.document_revision,t.manual_document_asset_id,
      coalesce(vs.client_is_nhsp,false) client_is_nhsp,
      coalesce(vs.client_no_timesheet_required,false) no_timesheet_required,
      coalesce(pc.effective_ts_attach_to_invoice,true) attach_timesheet
    from (
      select distinct il.invoice_id, il.timesheet_id
      from public.invoice_lines il
      where il.invoice_id in(select invoice_id from requested_invoices)
        and il.timesheet_id is not null
    ) il
    join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=t.timesheet_id
    left join timesheet_v2_models v2
      on v2.invoice_id=il.invoice_id and v2.timesheet_id=t.timesheet_id
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=t.timesheet_id
  ),
  invoice_timesheets_agg as materialized (
    select invoice_id,jsonb_agg(jsonb_build_object(
      'timesheet_id',timesheet_id,'submission_mode',submission_mode,'document_revision',document_revision,
      'manual_document_asset_id',manual_document_asset_id,'client_is_nhsp',client_is_nhsp,
      'no_timesheet_required',no_timesheet_required,'attach_timesheet',attach_timesheet,
      'render_model',render_model) order by timesheet_id) timesheet_sources
    from invoice_timesheet_rows group by invoice_id
  ),
  support_agg as materialized (
    select source_group.invoice_id,
      jsonb_agg(jsonb_build_object(
        'source_system',source_group.source_system,
        'import_id',(
          select s.import_id
          from public.invoice_hr_source_rows s
          where s.invoice_id=source_group.invoice_id
            and upper(s.source_system)=upper(source_group.source_system)
          order by s.import_id
          limit 1
        ),
        'render_model',jsonb_build_object(
          'schema_version',case when upper(source_group.source_system)='NHSP'
            then 'NHSP_PRESENTATION_V1' else 'HEALTHROSTER_PRESENTATION_V2' end,
          'rows',coalesce((select jsonb_agg(
            case when upper(source_group.source_system)='NHSP' then jsonb_build_object(
              'evidence_role',coalesce(
                nullif(btrim(r.value->>'evidence_role'),''),
                case
                  when upper(coalesce(
                    r.value->>'reversal_state',r.value->>'status',''))
                    in ('REVERSED','REVERSAL')
                  then 'NHSP Reversal'
                  else 'NHSP Shift'
                end),
              'worker',coalesce(
                r.value->>'worker',r.value->>'candidate',r.value->>'name',
                r.value->>'worker_name',r.value->>'staff_name'),
              'nhsp_shift_id',coalesce(
                r.value->>'nhsp_shift_id',r.value->>'shift_id',
                r.value->>'assignment_code',r.value->>'assignment'),
              'booking_reference',coalesce(
                r.value->>'booking_reference',r.value->>'reference',
                r.value->>'ref_num',r.value->>'assignment_code'),
              'site_ward',concat_ws(' / ',
                nullif(coalesce(
                  r.value->>'site',r.value->>'hospital',
                  r.value->>'trust',r.value->>'client'),''),
                nullif(r.value->>'ward','')),
              'shift_date',coalesce(
                r.value->>'shift_date',r.value->>'date',
                r.value->>'work_date',r.value->>'date_raw'),
              'shift_times',coalesce(
                r.value->>'shift_times',
                concat_ws(' - ',
                  nullif(coalesce(r.value->>'start',r.value->>'start_local'),''),
                  nullif(coalesce(r.value->>'end',r.value->>'end_local'),''))),
              'hours_units',coalesce(
                r.value->>'hours_units',r.value->>'hours',
                r.value->>'units',r.value->>'hours_worked',
                case
                  when coalesce(r.value->>'start_local','')
                         ~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$'
                   and coalesce(r.value->>'end_local','')
                         ~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$'
                   and coalesce(r.value->>'break_mins','0')
                         ~ '^[0-9]+([.][0-9]+)?$'
                  then trim(to_char(round((
                    extract(epoch from (
                      case
                        when (r.value->>'end_local')::time
                               >= (r.value->>'start_local')::time
                          then (r.value->>'end_local')::time
                               - (r.value->>'start_local')::time
                        else (r.value->>'end_local')::time
                               + interval '24 hours'
                               - (r.value->>'start_local')::time
                      end
                    )) / 3600
                    - (coalesce(r.value->>'break_mins','0')::numeric / 60)
                  )::numeric,2),'FM999999990.00'))
                end),
              'commission_amount',coalesce(
                r.value->>'commission_amount',r.value->>'commission',
                (select r.value->'raw_columns'->>((h.ordinality-1)::integer)
                 from jsonb_array_elements_text(
                   case when jsonb_typeof(s.header_columns)='array'
                     then s.header_columns else '[]'::jsonb end
                 ) with ordinality h(header_name,ordinality)
                 where lower(btrim(h.header_name))='commission'
                 order by h.ordinality
                 limit 1)),
              'total_amount',coalesce(
                r.value->>'total_amount',r.value->>'total_cost',
                (select r.value->'raw_columns'->>((h.ordinality-1)::integer)
                 from jsonb_array_elements_text(
                   case when jsonb_typeof(s.header_columns)='array'
                     then s.header_columns else '[]'::jsonb end
                 ) with ordinality h(header_name,ordinality)
                 where lower(btrim(h.header_name)) in ('total cost','total amount')
                 order by case when lower(btrim(h.header_name))='total cost'
                   then 0 else 1 end,h.ordinality
                 limit 1)),
              'source_identity',concat_ws(' · ',
                upper(coalesce(s.source_system,'NHSP')),
                'import row '||r.ordinality::text),
              'validation_state',coalesce(
                r.value->>'validation_state',r.value->>'status','Included'),
              'reversal_state',case
                when upper(coalesce(r.value->>'reversal_state',r.value->>'status','')) in ('REVERSED','REVERSAL')
                  or coalesce(
                    r.value->>'hours_units',r.value->>'hours',
                    r.value->>'units',r.value->>'hours_worked','') ~ '^-[0-9]'
                then 'REVERSED' else null end)
            else jsonb_build_object(
              'evidence_role',coalesce(
                nullif(btrim(r.value->>'evidence_role'),''),
                case
                  when upper(coalesce(
                    r.value->>'reversal_state',r.value->>'status',''))
                    in ('REVERSED','REVERSAL')
                  then 'HealthRoster Reversal'
                  else 'HealthRoster Shift'
                end),
              'worker',coalesce(
                r.value->>'worker',r.value->>'candidate',r.value->>'name',
                r.value->>'worker_name',r.value->>'staff_name'),
              'assignment',coalesce(
                r.value->>'assignment',r.value->>'role',
                r.value->>'job_title',r.value->>'assignment_code'),
              'shift_date',coalesce(
                r.value->>'shift_date',r.value->>'date',
                r.value->>'work_date',r.value->>'date_raw'),
              'shift_times',coalesce(
                r.value->>'shift_times',
                concat_ws(' - ',
                  nullif(coalesce(r.value->>'start',r.value->>'start_local'),''),
                  nullif(coalesce(r.value->>'end',r.value->>'end_local'),''))),
              'site',coalesce(
                r.value->>'site',r.value->>'hospital',
                r.value->>'trust',r.value->>'client'),
              'ward',r.value->>'ward',
              'booking_reference',case
                when coalesce(hr_match.reference_match_count,0)=1
                  then hr_match.ref_num
                else null end,
              'units_hours',coalesce(
                r.value->>'units_hours',r.value->>'hours',
                r.value->>'units',r.value->>'hours_worked'),
              'validation_state',coalesce(
                r.value->>'validation_state',r.value->>'status','Included'),
              'source_identity',concat_ws(' · ',
                upper(coalesce(s.source_system,'HEALTHROSTER')),
                'import row '||r.ordinality::text),
              'reference_match_state',case
                when coalesce(hr_match.reference_match_count,0)>1
                  then 'AMBIGUOUS'
                when coalesce(hr_match.reference_match_count,0)=0
                  then 'MISSING'
                when hr_match.match_priority=1
                  then 'EXACT_IMPORT_EXTERNAL_ROW'
                when hr_match.match_priority=2
                  then 'EXACT_IMPORT_REQUEST_ID'
                else 'CONTROLLED_UNIQUE_FALLBACK' end,
              'reference_match_count',coalesce(hr_match.reference_match_count,0),
              'reference_source','HEALTHROSTER_REF_NUM',
              'external_row_key',coalesce(
                hr_match.external_row_key,
                r.value->>'external_row_key',r.value->>'row_key',
                r.value->>'request_id',r.value->>'requestId'),
              'source_record_id',coalesce(
                hr_match.shift_id::text,r.value->>'unique_id'),
              'reversal_state',case
                when upper(coalesce(r.value->>'reversal_state',r.value->>'status','')) in ('REVERSED','REVERSAL')
                  or coalesce(
                    r.value->>'units_hours',r.value->>'hours',
                    r.value->>'units',r.value->>'hours_worked','') ~ '^-[0-9]'
                then 'REVERSED' else null end) end
            order by
              coalesce(
                r.value->>'shift_date',r.value->>'date',
                r.value->>'work_date',r.value->>'date_raw',''),
              coalesce(
                r.value->>'start',r.value->>'worked_start',
                r.value->>'start_local',''),
              s.import_id,
              r.ordinality)
            from public.invoice_hr_source_rows s
            cross join lateral jsonb_array_elements(
              case when jsonb_typeof(s.rows_json)='array' then s.rows_json else '[]'::jsonb end
            ) with ordinality r(value,ordinality)
            left join lateral (
              select
                min(ranked.match_priority) match_priority,
                count(*)::integer reference_match_count,
                case when count(*)=1 then min(ranked.ref_num) end ref_num,
                case when count(*)=1 then min(ranked.external_row_key) end external_row_key,
                case when count(*)=1 then min(ranked.shift_id::text)::uuid end shift_id
              from (
                select candidates.*,
                  min(candidates.match_priority) over () winning_priority
                from (
                  select ns.ref_num,ns.external_row_key,ns.id shift_id,1 match_priority
                  from public.nhsp_shifts ns
                  where upper(ns.source_system::text)=upper(s.source_system)
                    and ns.latest_import_id=s.import_id
                    and nullif(btrim(coalesce(
                      r.value->>'external_row_key',r.value->>'row_key','')),'') is not null
                    and ns.external_row_key=coalesce(
                      r.value->>'external_row_key',r.value->>'row_key')
                  union all
                  select ns.ref_num,ns.external_row_key,ns.id shift_id,2 match_priority
                  from public.nhsp_shifts ns
                  where upper(ns.source_system::text)=upper(s.source_system)
                    and ns.latest_import_id=s.import_id
                    and nullif(btrim(coalesce(
                      r.value->>'request_id',r.value->>'requestId','')),'') is not null
                    and ns.hr_request_id=coalesce(
                      r.value->>'request_id',r.value->>'requestId')
                  union all
                  select ns.ref_num,ns.external_row_key,ns.id shift_id,3 match_priority
                  from public.nhsp_shifts ns
                  where upper(ns.source_system::text)=upper(s.source_system)
                    and coalesce(r.value->>'work_date',r.value->>'date','')
                          ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
                    and ns.work_date=coalesce(
                      r.value->>'work_date',r.value->>'date')::date
                    and nullif(r.value->>'start_utc','') is not null
                    and nullif(r.value->>'end_utc','') is not null
                    and ns.start_utc=(r.value->>'start_utc')::timestamptz
                    and ns.end_utc=(r.value->>'end_utc')::timestamptz
                    and (
                      nullif(r.value->>'client_id','') is null
                      or ns.client_id=(r.value->>'client_id')::uuid
                    )
                    and lower(btrim(coalesce(ns.staff_name,'')))=
                        lower(btrim(coalesce(
                          r.value->>'staff_name',r.value->>'worker_name',
                          r.value->>'worker','')))
                    and lower(btrim(coalesce(ns.ward,'')))=
                        lower(btrim(coalesce(r.value->>'ward','')))
                ) candidates
              ) ranked
              where ranked.match_priority=ranked.winning_priority
            ) hr_match on upper(s.source_system)<>'NHSP'
            where s.invoice_id=source_group.invoice_id
              and upper(s.source_system)=upper(source_group.source_system)), '[]'::jsonb),
          'source_identity',jsonb_build_object(
            'source_system',source_group.source_system,
            'import_ids',coalesce((
              select jsonb_agg(to_jsonb(import_id) order by import_id)
              from (
                select distinct s.import_id
                from public.invoice_hr_source_rows s
                where s.invoice_id=source_group.invoice_id
                  and upper(s.source_system)=upper(source_group.source_system)
              ) imports
            ),'[]'::jsonb)))
       ) order by source_group.source_system) supporting_sources
    from (
      select distinct s.invoice_id,upper(s.source_system) source_system
      from public.invoice_hr_source_rows s
      where s.invoice_id in(select invoice_id from requested_invoices)
    ) source_group
    group by source_group.invoice_id
  ),
  supporting_manifest_agg as materialized (
    select evidence.invoice_id,
      jsonb_agg(jsonb_build_object(
        'timesheet_id',evidence.timesheet_id,
        'evidence_id',evidence.evidence_id,
        'kind',evidence.kind,
        'document_role',evidence.document_role,
        'candidate_component_id',evidence.candidate_component_id,
        'display_name',evidence.display_name,
        'storage_key',evidence.storage_key,
        'asset_id',evidence.asset_id,
        'source_kind',evidence.source_kind,
        'source_revision',evidence.source_revision,
        'original_r2_key',evidence.original_r2_key,
        'asset_sha256',evidence.asset_sha256,
        'asset_manifest_hash',evidence.asset_manifest_hash,
        'asset_size_bytes',evidence.asset_size_bytes,
        'asset_page_count',evidence.asset_page_count
      ) order by evidence.timesheet_id,
        case when evidence.document_role='EXPENSE_MILEAGE_APPROVAL_SUMMARY' then 0 else 1 end,
        case evidence.kind when 'MILEAGE' then 1 when 'TRAVEL' then 2
          when 'ACCOMMODATION' then 3 else 4 end,
        evidence.created_at,evidence.evidence_id) supporting_manifest
    from (
      select distinct il.invoice_id,e.timesheet_id,e.id evidence_id,
        upper(coalesce(e.kind,'OTHER')) kind,
        upper(coalesce(e.document_role,'')) document_role,
        e.candidate_component_id,
        coalesce(e.display_name,e.kind,'Evidence') display_name,
        e.storage_key,e.document_asset_id asset_id,a.source_kind,
        coalesce(a.source_revision,e.source_revision,encode(digest(concat_ws('|',
          e.id::text,e.storage_key,e.created_at::text),'sha256'),'hex')) source_revision,
        coalesce(a.original_r2_key,e.storage_key) original_r2_key,
        a.normalised_sha256 asset_sha256,
        a.normalised_manifest_hash asset_manifest_hash,
        a.normalised_size_bytes asset_size_bytes,
        a.normalised_page_count asset_page_count,e.created_at
      from public.invoice_lines il
      join public.timesheet_evidence e on e.timesheet_id=il.timesheet_id
      left join public.invoice_document_assets a on a.id=e.document_asset_id
      where il.invoice_id in(select invoice_id from requested_invoices)
        and il.timesheet_id is not null
        and nullif(coalesce(e.storage_key,''),'') is not null
        and upper(coalesce(e.kind,''))<>'TIMESHEET'
        and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
        and upper(coalesce(e.document_role,'')) not in(
          'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES')
        and upper(coalesce(e.kind,'')) not in(
          'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES')
        and exists(
          select 1 from public.invoice_lines expense_line
          where expense_line.invoice_id=il.invoice_id
            and expense_line.timesheet_id=e.timesheet_id
            and(
              upper(coalesce(expense_line.meta_json->>'line_type','')) in('MILEAGE','EXPENSES')
              or upper(coalesce(expense_line.meta_json->>'line_type','')) like '%EXPENSE%'
              or upper(coalesce(expense_line.meta_json->>'line_type','')) like '%TRAVEL%'
              or upper(coalesce(expense_line.meta_json->>'line_type','')) like '%ACCOMMODATION%'))
    ) evidence
    group by evidence.invoice_id
  ),
  higher_rate_agg as materialized (
    select il.invoice_id,
      jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows',
        coalesce(jsonb_agg(jsonb_build_object(
          'worker_source',coalesce(il.meta_json->>'worker',il.meta_json->>'candidate',il.booking_id),
          'shift_date',coalesce(il.meta_json->>'shift_date',il.meta_json->>'date'),
          'original_rate',il.meta_json->>'original_rate',
          'applied_rate',coalesce(il.meta_json->>'applied_rate',il.charge_day::text,il.charge_night::text,il.charge_sat::text,il.charge_sun::text,il.charge_bh::text),
          'units',coalesce(il.meta_json->>'units',il.meta_json->>'hours'),
          'display_amount',round(coalesce(il.total_charge_ex_vat,0),2)::text,
          'reason',coalesce(il.meta_json->>'reason',il.description),
          'approval_identity',il.meta_json->'approval_identity',
          'reference',coalesce(il.meta_json->>'reference',il.source_key)
        ) order by il.created_at,il.id) filter (where upper(coalesce(il.meta_json->>'line_type','') || ' ' || coalesce(il.description,'') || ' ' || coalesce(il.source_key,'')) like '%HIGHER%'), '[]'::jsonb)) higher_rate_support
    from public.invoice_lines il
    where il.invoice_id in(select invoice_id from requested_invoices)
    group by il.invoice_id
  ),
  invoice_models as materialized (
    select vr.request_no,vr.req_key request_key,
      case when vr.purpose='FINAL_ISSUE'
        then 'FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5'
        else 'INVOICE_PRESENTATION_SNAPSHOT_V5' end::text snapshot_schema_version,
      i.id invoice_id,
      jsonb_build_object(
        'schema_version','INVOICE_RENDER_MODEL_V1',
        'purpose',vr.purpose,
        'document_type',case when i.type::text='CREDIT_NOTE' then 'CREDIT_NOTE'
          when lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}',i.header_snapshot_json->>'self_bill','false')) in('true','t','1','yes') then 'SELF_BILL_INVOICE'
          else 'INVOICE' end,
        'is_draft',vr.purpose<>'FINAL_ISSUE',
        'invoice_id',i.id,
        'invoice_number',i.invoice_no,
        'issue_date',case when vr.purpose='FINAL_ISSUE' then vr.issue_at_utc else i.issued_at_utc end,
        'preview_date',case when vr.purpose='DRAFT_PREVIEW' then v_now end,
        'tax_point',case
          when vr.purpose='FINAL_ISSUE' then vr.tax_point_utc::text
          else coalesce(i.header_snapshot_json->>'tax_point_utc',i.issued_at_utc::text)
        end,
        'due_date',case when vr.purpose='FINAL_ISSUE' then vr.due_at_utc else i.due_at_utc end,
        'currency',coalesce(i.header_snapshot_json->>'currency','GBP'),
        'supplier',jsonb_build_object(
          'legal_name',coalesce(nullif(i.header_snapshot_json->>'agency_name',''),sd.agency_name),
          'trading_name',i.header_snapshot_json->>'agency_trading_name',
          'registered_address',coalesce((select jsonb_agg(btrim(line) order by ord) from regexp_split_to_table(coalesce(nullif(i.header_snapshot_json->>'registered_address',''),sd.registered_address,''), E'\r?\n') with ordinality a(line,ord) where btrim(line)<>''),'[]'::jsonb),
          'company_registration_number',coalesce(nullif(i.header_snapshot_json->>'company_reg_number',''),sd.company_reg_number),
          'vat_registration_number',coalesce(nullif(i.header_snapshot_json->>'vat_registration_number',''),sd.vat_registration_number),
          'contact_email',coalesce(i.header_snapshot_json->>'supplier_email',sd.finance_email,sd.system_email),
          'contact_phone',i.header_snapshot_json->>'supplier_phone'),
        'customer',jsonb_build_object(
          'legal_name',coalesce(nullif(i.header_snapshot_json->>'client_name',''),cl.name),
          'billing_address',coalesce((select jsonb_agg(btrim(line) order by ord) from regexp_split_to_table(coalesce(nullif(i.header_snapshot_json->>'client_invoice_address',''),cl.invoice_address,cl.client_address,''), E'\r?\n') with ordinality a(line,ord) where btrim(line)<>''),'[]'::jsonb),
          'account_reference',coalesce(i.header_snapshot_json->>'client_reference',cl.cli_ref)),
        'references',jsonb_build_object('purchase_order',coalesce(i.header_snapshot_json->>'po_reference',i.header_snapshot_json->>'po_number'),'client_reference',coalesce(i.header_snapshot_json->>'client_reference',cl.cli_ref),'work_location',i.header_snapshot_json->>'work_location'),
        'candidate_summary',i.header_snapshot_json->>'candidate_summary',
        'suppress_candidate_header',
          upper(coalesce(
            i.header_snapshot_json#>>'{meta,consolidation_mode}',
            i.header_snapshot_json#>>'{meta,invoice_consolidation_mode}',
            i.header_snapshot_json->>'consolidation_mode',
            i.header_snapshot_json->>'invoice_consolidation_mode','NONE'))
            in('BY_WEEK','ANY_WEEK')
          or exists(select 1 from public.invoice_hr_source_rows nhsp
            where nhsp.invoice_id=i.id and upper(nhsp.source_system)='NHSP')
          or (select count(distinct il.timesheet_id)
              from public.invoice_lines il
              where il.invoice_id=i.id and il.timesheet_id is not null)>1
          or (select count(distinct nullif(btrim(lb.worker_name),''))
              from invoice_line_base lb where lb.invoice_id=i.id)>1,
        'branding',jsonb_build_object(
          'logo',case
            when jsonb_typeof(i.header_snapshot_json->'agency_logo')='object'
              then jsonb_build_object(
                'r2_key',i.header_snapshot_json#>>'{agency_logo,r2_key}',
                'sha256',lower(i.header_snapshot_json#>>'{agency_logo,sha256}'),
                'size_bytes',case
                  when coalesce(i.header_snapshot_json#>>'{agency_logo,size_bytes}','') ~ '^[1-9][0-9]{0,18}$'
                    then (i.header_snapshot_json#>>'{agency_logo,size_bytes}')::bigint
                  else null end,
                'media_type',lower(i.header_snapshot_json#>>'{agency_logo,media_type}'))
            when jsonb_typeof(coalesce(
              sd.invoice_document_presentation_json#>'{branding,logo}',
              sd.import_config_json#>'{invoice_document_presentation,branding,logo}'
            ))='object'
              then jsonb_build_object(
                'r2_key',coalesce(
                  sd.invoice_document_presentation_json#>>'{branding,logo,r2_key}',
                  sd.import_config_json#>>'{invoice_document_presentation,branding,logo,r2_key}'),
                'sha256',lower(coalesce(
                  sd.invoice_document_presentation_json#>>'{branding,logo,sha256}',
                  sd.import_config_json#>>'{invoice_document_presentation,branding,logo,sha256}')),
                'size_bytes',case
                  when coalesce(
                    sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
                    sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}',
                    ''
                  ) ~ '^[1-9][0-9]{0,18}$'
                    then coalesce(
                      sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
                      sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}'
                    )::bigint
                  else null end,
                'media_type',lower(coalesce(
                  sd.invoice_document_presentation_json#>>'{branding,logo,media_type}',
                  sd.import_config_json#>>'{invoice_document_presentation,branding,logo,media_type}')))
            else '{}'::jsonb end),
        'lines',coalesce(l.lines,'[]'::jsonb),
        'vat_breakdown',coalesce((select jsonb_agg(jsonb_build_object(
          'rate',vb.vat_rate_pct::text,
          'net_amount',vb.net::text,
          'vat_amount',vb.vat::text,
          'gross_amount',vb.gross::text
        ) order by vb.vat_rate_pct) from (
          select coalesce(vat_rate_pct,0) vat_rate_pct,
            round(sum(coalesce(total_charge_ex_vat,0)),2) net,
            round(sum(coalesce(vat_amount,0)),2) vat,
            round(sum(coalesce(total_inc_vat,coalesce(total_charge_ex_vat,0)+coalesce(vat_amount,0))),2) gross
          from public.invoice_lines
          where invoice_id=i.id
          group by coalesce(vat_rate_pct,0)
        ) vb),'[]'::jsonb),
        'totals',jsonb_build_object(
          'net',round(coalesce(i.subtotal_ex_vat,0),2)::text,
          'vat',round(coalesce(i.vat_amount,0),2)::text,
          'gross',round(coalesce(i.total_inc_vat,0),2)::text,
          'amount_paid',coalesce((
            case when pg_input_is_valid(nullif(i.header_snapshot_json->>'amount_paid',''),'numeric')
              then (i.header_snapshot_json->>'amount_paid')::numeric end
          ),0)::text,
          'amount_credited',coalesce((
            case when pg_input_is_valid(nullif(i.header_snapshot_json->>'amount_credited',''),'numeric')
              then (i.header_snapshot_json->>'amount_credited')::numeric end
          ),0)::text,
          'amount_outstanding',coalesce((
            case when pg_input_is_valid(nullif(i.header_snapshot_json->>'amount_outstanding',''),'numeric')
              then (i.header_snapshot_json->>'amount_outstanding')::numeric end
          ),coalesce(i.total_inc_vat,0))::text),
        'payment',jsonb_build_object(
          'terms_days',coalesce(
            case when pg_input_is_valid(nullif(i.header_snapshot_json->>'payment_terms_days',''),'integer')
              then (i.header_snapshot_json->>'payment_terms_days')::integer end,
            cl.payment_terms_days,30),
          'terms_text',coalesce(
            nullif(i.header_snapshot_json->>'payment_terms_text',''),
            coalesce(
              case when pg_input_is_valid(nullif(i.header_snapshot_json->>'payment_terms_days',''),'integer')
                then (i.header_snapshot_json->>'payment_terms_days')::integer end,
              cl.payment_terms_days,
              30
            )::text || ' days from invoice date'
          ),
          'due_date_basis','ISSUE_DATE',
          'instructions',coalesce(
            i.header_snapshot_json->>'payment_instructions',
            sd.invoice_document_presentation_json->>'payment_instructions',
            sd.import_config_json#>>'{invoice_document_presentation,payment_instructions}'),
          'account_name',case when lower(coalesce(
            i.header_snapshot_json#>>'{meta,hide_bank_footer}',
            i.header_snapshot_json->>'hide_bank_footer',
            sd.invoice_document_presentation_json->>'hide_bank_footer_default',
            sd.import_config_json#>>'{invoice_document_presentation,hide_bank_footer_default}',
            'false')) in('true','t','1','yes') then null
            else coalesce(i.header_snapshot_json#>>'{bank,name}',i.header_snapshot_json->>'bank_name',sd.bank_name) end,
          'sort_code',case when lower(coalesce(
            i.header_snapshot_json#>>'{meta,hide_bank_footer}',
            i.header_snapshot_json->>'hide_bank_footer',
            sd.invoice_document_presentation_json->>'hide_bank_footer_default',
            sd.import_config_json#>>'{invoice_document_presentation,hide_bank_footer_default}',
            'false')) in('true','t','1','yes') then null
            else coalesce(i.header_snapshot_json#>>'{bank,sort_code}',i.header_snapshot_json->>'bank_sort_code',sd.bank_sort_code) end,
          'account_number',case when lower(coalesce(
            i.header_snapshot_json#>>'{meta,hide_bank_footer}',
            i.header_snapshot_json->>'hide_bank_footer',
            sd.invoice_document_presentation_json->>'hide_bank_footer_default',
            sd.import_config_json#>>'{invoice_document_presentation,hide_bank_footer_default}',
            'false')) in('true','t','1','yes') then null
            else coalesce(i.header_snapshot_json#>>'{bank,account_number}',i.header_snapshot_json->>'bank_account_number',sd.bank_account_number) end,
          'remittance_reference',i.invoice_no,
          'remittance_email',coalesce(i.header_snapshot_json->>'remittance_email',sd.finance_email),
          'hide_bank_footer',lower(coalesce(
            i.header_snapshot_json#>>'{meta,hide_bank_footer}',
            i.header_snapshot_json->>'hide_bank_footer',
            sd.invoice_document_presentation_json->>'hide_bank_footer_default',
            sd.import_config_json#>>'{invoice_document_presentation,hide_bank_footer_default}',
            'false')) in('true','t','1','yes')),
        'credit_note',jsonb_build_object('is_credit_note',i.type::text='CREDIT_NOTE','original_invoice_id',i.original_invoice_id,'original_invoice_number',coalesce(i.header_snapshot_json->>'original_invoice_number',orig.invoice_no),'original_invoice_date',coalesce(i.header_snapshot_json->>'original_invoice_date',orig.issued_at_utc::text),'reason',coalesce(i.header_snapshot_json->>'credit_reason',i.notes)),
        'self_bill',jsonb_build_object('is_self_bill',lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}',i.header_snapshot_json->>'self_bill','false')) in('true','t','1','yes'),'legal_wording',coalesce(i.header_snapshot_json->>'self_bill_wording',coalesce(sd.invoice_document_presentation_json->>'self_bill_legal_wording', sd.import_config_json#>>'{invoice_document_presentation,self_bill_legal_wording}'))),
        'legal_wording',coalesce(i.header_snapshot_json->'legal_wording',coalesce(sd.invoice_document_presentation_json->'legal_wording', sd.import_config_json#>'{invoice_document_presentation,legal_wording}'),'[]'::jsonb),
        'attachment_policy',coalesce(i.header_snapshot_json->'attach_policy',i.header_snapshot_json->'attachment_policy','{}'::jsonb),
        'template_version',vr.template_version,
        'locale',coalesce(i.header_snapshot_json->>'locale',sd.invoice_document_presentation_json->>'locale',sd.import_config_json#>>'{invoice_document_presentation,locale}','en-GB'),
        'page_geometry',coalesce(i.header_snapshot_json->>'page_geometry',sd.invoice_document_presentation_json->>'page_geometry',sd.import_config_json#>>'{invoice_document_presentation,page_geometry}','A4_PORTRAIT_210X297MM')) presentation_model,
      coalesce(ts.timesheet_sources,'[]'::jsonb) timesheet_sources,
      coalesce(sa.supporting_sources,'[]'::jsonb) supporting_sources,
      coalesce(hra.higher_rate_support,jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb)) higher_rate_support,
      coalesce(l.line_net,0) line_net,coalesce(l.line_vat,0) line_vat,coalesce(l.line_gross,0) line_gross,
      round(coalesce(i.subtotal_ex_vat,0),2) invoice_net,round(coalesce(i.vat_amount,0),2) invoice_vat,round(coalesce(i.total_inc_vat,0),2) invoice_gross
    from valid_requests vr
    join public.invoices i on vr.entity_type='INVOICE' and i.id=vr.entity_id
    left join public.invoices orig on orig.id=i.original_invoice_id
    join public.clients cl on cl.id=i.client_id
    cross join public.settings_defaults sd
    left join invoice_line_rows l on l.invoice_id=i.id
    left join invoice_timesheets_agg ts on ts.invoice_id=i.id
    left join support_agg sa on sa.invoice_id=i.id
    left join supporting_manifest_agg sma on sma.invoice_id=i.id
    left join higher_rate_agg hra on hra.invoice_id=i.id
    where sd.id=1
  ),
  timesheet_models as materialized (
    select vr.request_no,vr.req_key request_key,'TIMESHEET_PRESENTATION_SNAPSHOT_V5'::text snapshot_schema_version,
      coalesce(v2.render_model,jsonb_build_object(
        'schema_version','TIMESHEET_RENDER_MODEL_V1',
        'timesheet_id',t.timesheet_id,
        'document_revision',t.document_revision,
        'candidate',jsonb_build_object('id',coalesce(vs.candidate_id::text,null),'name',coalesce(vs.candidate_name,t.occupant_key_norm)),
        'client',jsonb_build_object('id',coalesce(vs.client_id::text,null),'name',vs.client_name),
        'contract',jsonb_build_object('id',coalesce(t.contract_id::text,null),'reference',t.booking_id),
        'work',jsonb_build_object(
          'hospital',t.hospital_norm,
          'site',t.hospital_norm,
          'ward',t.ward_norm,
          'assignment',coalesce(
            nullif(btrim(t.job_title_norm),''),
            case when nullif(btrim(t.shift_label_norm),'') is not null
                   and length(t.shift_label_norm) <= 80
                   and t.shift_label_norm !~* '^weekly-correction-'
                   and t.shift_label_norm !~* '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
              then t.shift_label_norm end),
          'job_title',t.job_title_norm,
          'band',t.band,
          'shift_type',case when nullif(btrim(t.shift_label_norm),'') is not null
                              and length(t.shift_label_norm) <= 80
                              and t.shift_label_norm !~* '^weekly-correction-'
                              and t.shift_label_norm !~* '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
                         then t.shift_label_norm end),
        'week_ending_date',t.week_ending_date,
        'submission_mode',t.submission_mode::text,
        'sheet_scope',t.sheet_scope::text,
        'daily_schedule_rows',coalesce((select jsonb_agg(jsonb_build_object('date',coalesce(s.value->>'date',s.value->>'day',to_char(t.worked_start_iso::date,'YYYY-MM-DD')),'scheduled_start',coalesce(s.value->>'scheduled_start',s.value->>'start',s.value->>'start_utc',t.scheduled_start_iso::text),'scheduled_end',coalesce(s.value->>'scheduled_end',s.value->>'end',s.value->>'end_utc',t.scheduled_end_iso::text),'worked_start',coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc',t.worked_start_iso::text),'worked_end',coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc',t.worked_end_iso::text),'break_start',coalesce(s.value->>'break_start',t.break_start_iso::text),'break_end',coalesce(s.value->>'break_end',t.break_end_iso::text),'break_minutes',case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$' then (coalesce(s.value->>'break_minutes',s.value->>'break_mins'))::integer else coalesce(t.break_minutes,0) end,'reference',coalesce(s.value->>'reference',s.value->>'ref_num',t.reference_number),'hours',coalesce(s.value->>'hours',s.value->>'units',case when t.worked_minutes is not null then round(t.worked_minutes::numeric/60,2)::text end),'units',coalesce(s.value->>'units',s.value->>'hours'),'display_order',s.ordinality) order by s.ordinality) from jsonb_array_elements(case when jsonb_typeof(t.actual_schedule_json)='array' then t.actual_schedule_json else '[]'::jsonb end) with ordinality s(value,ordinality) where upper(coalesce(t.sheet_scope::text,''))='DAILY'),case when upper(coalesce(t.sheet_scope::text,''))='DAILY' then jsonb_build_array(jsonb_build_object('date',t.worked_start_iso::date,'scheduled_start',t.scheduled_start_iso,'scheduled_end',t.scheduled_end_iso,'worked_start',t.worked_start_iso,'worked_end',t.worked_end_iso,'break_start',t.break_start_iso,'break_end',t.break_end_iso,'break_minutes',coalesce(t.break_minutes,0),'reference',t.reference_number,'hours',case when t.worked_minutes is not null then round(t.worked_minutes::numeric/60,2)::text end,'units',null,'display_order',1)) else '[]'::jsonb end),
        'weekly_schedule_rows',coalesce((select jsonb_agg(jsonb_build_object(
          'date',coalesce(s.value->>'date',s.value->>'day'),
          'scheduled_start',coalesce(s.value->>'scheduled_start',s.value->>'start',s.value->>'start_utc'),
          'scheduled_end',coalesce(s.value->>'scheduled_end',s.value->>'end',s.value->>'end_utc'),
          'worked_start',coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc'),
          'worked_end',coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc'),
          'break_start',s.value->>'break_start',
          'break_end',s.value->>'break_end',
          'break_minutes',case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$' then coalesce(s.value->>'break_minutes',s.value->>'break_mins')::integer else 0 end,
          'reference',coalesce(s.value->>'reference',s.value->>'ref_num'),
          'hours',coalesce(
            s.value->>'hours',
            s.value->>'units',
            case when pg_input_is_valid(nullif(coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc'),''),'timestamptz')
                       and pg_input_is_valid(nullif(coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc'),''),'timestamptz')
                 then greatest(
                   0,
                   round((
                     extract(epoch from (
                       coalesce(s.value->>'worked_end',s.value->>'end',s.value->>'end_utc')::timestamptz
                       - coalesce(s.value->>'worked_start',s.value->>'start',s.value->>'start_utc')::timestamptz
                     )) / 60
                     - case when coalesce(s.value->>'break_minutes',s.value->>'break_mins','') ~ '^[0-9]{1,5}$'
                         then coalesce(s.value->>'break_minutes',s.value->>'break_mins')::numeric else 0 end
                   ) / 60,2)
                 )::text end),
          'units',coalesce(s.value->>'units',s.value->>'hours'),
          'display_order',s.ordinality
        ) order by s.ordinality) from jsonb_array_elements(case when jsonb_typeof(t.actual_schedule_json)='array' then t.actual_schedule_json else '[]'::jsonb end) with ordinality s(value,ordinality) where upper(coalesce(t.sheet_scope::text,''))='WEEKLY'),'[]'::jsonb),
        'references',jsonb_build_object('whole',nullif(t.reference_number,''),'day',coalesce((select jsonb_agg(jsonb_build_object('day_key',d.key,'reference',case when jsonb_typeof(d.value)='object' then coalesce(d.value->>'reference',d.value->>'ref_num',d.value->>'value') else trim(both '"' from d.value::text) end,'display_order',d.ordinality) order by d.ordinality) from jsonb_each(case when jsonb_typeof(t.day_references_json)='object' then t.day_references_json else '{}'::jsonb end) with ordinality d(key,value,ordinality)), '[]'::jsonb),'segment','[]'::jsonb),
        'additional_units',coalesce((
          select jsonb_object_agg(
            au.key,
            case
              when jsonb_typeof(au.value)='number'
                then to_jsonb(trim_scale((au.value#>>'{}')::numeric)::text)
              else au.value
            end
            order by au.key
          )
          from jsonb_each(
            case when jsonb_typeof(t.additional_units_week)='object'
              then t.additional_units_week else '{}'::jsonb end
          ) au
        ),'{}'::jsonb),
        'authorisation',jsonb_build_object('authorised',t.authorised_at_server is not null,'name',t.auth_name,'role',t.auth_job_title,'authorised_at_utc',t.authorised_at_server),
        'signatures',jsonb_build_object(
          'candidate',case when nullif(t.r2_nurse_key,'') is null
            then jsonb_build_object('identity',coalesce(vs.candidate_name,t.occupant_key_norm),'role','Candidate / nurse')
            else jsonb_build_object('r2_key',t.r2_nurse_key,'sha256',t.img_sha256_nurse,'size_bytes',null,'media_type','image/png','identity',coalesce(vs.candidate_name,t.occupant_key_norm),'role','Candidate / nurse') end,
          'authoriser',case when nullif(t.r2_auth_key,'') is null
            then jsonb_build_object('identity',t.auth_name,'role',t.auth_job_title)
            else jsonb_build_object('r2_key',t.r2_auth_key,'sha256',t.img_sha256_auth,'size_bytes',null,'media_type','image/png','identity',t.auth_name,'role',t.auth_job_title) end),
        'qr',jsonb_build_object('required',t.qr_status is not null,'signed',t.qr_signed_hash is not null,'status',t.qr_status::text,'signed_hash',t.qr_signed_hash,'signed_at_utc',t.qr_signed_at_utc,'verification_summary',case when t.qr_signed_hash is not null then 'QR signature verified in frozen source' when t.qr_status is not null then t.qr_status::text else null end),
        'template_version','timesheet-professional-v1'
      )) presentation_model,
      '[]'::jsonb timesheet_sources,
      '[]'::jsonb supporting_sources,
      jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support
    from valid_requests vr
    join public.timesheets t on vr.entity_type='TIMESHEET' and t.timesheet_id=vr.entity_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=t.timesheet_id
    left join timesheet_v2_models v2
      on v2.invoice_id is null and v2.timesheet_id=t.timesheet_id
  ),
  missing_entity_results as materialized (
    select vr.request_no,vr.req_key request_key,
      case when vr.entity_type='INVOICE' then 'INVOICE_PRESENTATION_SNAPSHOT_V5' else 'TIMESHEET_PRESENTATION_SNAPSHOT_V5' end snapshot_schema_version,
      '{}'::jsonb presentation_model,'[]'::jsonb timesheet_sources,'[]'::jsonb supporting_sources,
      jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support,
      jsonb_build_object('snapshot_schema_version','PRESENTATION_ENTITY_NOT_FOUND','request_key',vr.req_key,'entity_type',vr.entity_type,'entity_id',vr.entity_id) snapshot_json,
      encode(digest(jsonb_build_object('snapshot_schema_version','PRESENTATION_ENTITY_NOT_FOUND','request_key',vr.req_key,'entity_type',vr.entity_type,'entity_id',vr.entity_id)::text,'sha256'),'hex') snapshot_hash,
      false valid,
      'PRESENTATION_ENTITY_NOT_FOUND'::text error_code,
      jsonb_build_object('entity_type',vr.entity_type,'entity_id',vr.entity_id) error_detail
    from valid_requests vr
    where not exists(select 1 from invoice_models im where im.request_no=vr.request_no)
      and not exists(select 1 from timesheet_models tm where tm.request_no=vr.request_no)
  ),
  all_models as materialized (
    select request_no,request_key,snapshot_schema_version,presentation_model,timesheet_sources,supporting_sources,higher_rate_support,
      case
        when snapshot_schema_version like '%INVOICE%' and nullif(presentation_model->>'document_type','') is null then 'INVOICE_PRESENTATION_DOCUMENT_TYPE_REQUIRED'
        when snapshot_schema_version like '%INVOICE%' and nullif(presentation_model->>'invoice_number','') is null then 'INVOICE_PRESENTATION_INVOICE_NUMBER_REQUIRED'
        when snapshot_schema_version like '%INVOICE%' and nullif(presentation_model#>>'{supplier,legal_name}','') is null then 'INVOICE_PRESENTATION_SUPPLIER_REQUIRED'
        when snapshot_schema_version like '%INVOICE%' and jsonb_array_length(case when jsonb_typeof(presentation_model#>'{supplier,registered_address}')='array' then presentation_model#>'{supplier,registered_address}' else '[]'::jsonb end)=0 then 'INVOICE_PRESENTATION_SUPPLIER_ADDRESS_REQUIRED'
        when snapshot_schema_version like '%INVOICE%' and nullif(presentation_model#>>'{customer,legal_name}','') is null then 'INVOICE_PRESENTATION_CUSTOMER_REQUIRED'
        when snapshot_schema_version like '%INVOICE%' and jsonb_array_length(case when jsonb_typeof(presentation_model#>'{customer,billing_address}')='array' then presentation_model#>'{customer,billing_address}' else '[]'::jsonb end)=0 then 'INVOICE_PRESENTATION_CUSTOMER_ADDRESS_REQUIRED'
        when snapshot_schema_version='FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5' and nullif(presentation_model->>'issue_date','') is null then 'INVOICE_PRESENTATION_ISSUE_DATE_REQUIRED'
        when snapshot_schema_version='FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5' and nullif(presentation_model->>'tax_point','') is null then 'INVOICE_PRESENTATION_TAX_POINT_REQUIRED'
        when snapshot_schema_version='FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5' and nullif(presentation_model->>'due_date','') is null then 'INVOICE_PRESENTATION_DUE_DATE_REQUIRED'
        when jsonb_array_length(coalesce(presentation_model->'lines','[]'::jsonb))=0
          and snapshot_schema_version like '%INVOICE%'
          and (coalesce(invoice_net,0)<>0 or coalesce(invoice_vat,0)<>0 or coalesce(invoice_gross,0)<>0)
          then 'INVOICE_PRESENTATION_REQUIRED_FIELD_MISSING'
        when snapshot_schema_version like '%INVOICE%' and (line_net,line_vat,line_gross) is distinct from (invoice_net,invoice_vat,invoice_gross) then 'INVOICE_PRESENTATION_LINE_TOTAL_MISMATCH'
        when snapshot_schema_version like '%INVOICE%' and invoice_vat<>0 and nullif(presentation_model#>>'{supplier,vat_registration_number}','') is null then 'INVOICE_PRESENTATION_VAT_NUMBER_REQUIRED'
        when (presentation_model->>'document_type')='CREDIT_NOTE' and nullif(coalesce(presentation_model#>>'{credit_note,original_invoice_number}',presentation_model#>>'{credit_note,original_invoice_id}'),'') is null then 'CREDIT_NOTE_ORIGINAL_REQUIRED'
        when (presentation_model->>'document_type')='CREDIT_NOTE' and nullif(presentation_model#>>'{credit_note,reason}','') is null then 'CREDIT_NOTE_REASON_REQUIRED'
        when (presentation_model->>'document_type')='SELF_BILL_INVOICE' and nullif(presentation_model#>>'{self_bill,legal_wording}','') is null then 'SELF_BILL_WORDING_REQUIRED'
        else null end error_code
    from invoice_models
    union all
    select request_no,request_key,snapshot_schema_version,presentation_model,timesheet_sources,supporting_sources,higher_rate_support,
      case
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and nullif(presentation_model#>>'{week_period,end_date}','') is null
          then 'TIMESHEET_WEEK_ENDING_DATE_MISSING'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and coalesce(presentation_model#>>'{week_period,configured_week_ending_weekday}','')~'^[0-6]$'
          and coalesce(presentation_model#>>'{week_period,end_weekday_index}','')~'^[0-6]$'
          and (presentation_model#>>'{week_period,configured_week_ending_weekday}')::integer
            <> (presentation_model#>>'{week_period,end_weekday_index}')::integer
          then 'TIMESHEET_WEEK_ENDING_WEEKDAY_MISMATCH'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and jsonb_array_length(case
            when jsonb_typeof(presentation_model#>'{week_period,days}')='array'
              then presentation_model#>'{week_period,days}' else '[]'::jsonb end)<>7
          then 'TIMESHEET_WEEK_PERIOD_INVALID'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and not exists(
            select 1
            from jsonb_array_elements(
              coalesce(presentation_model#>'{week_period,days}','[]'::jsonb)) d
            cross join lateral jsonb_array_elements(
              coalesce(d->'shift_lines','[]'::jsonb)) s)
          then 'TIMESHEET_PRESENTATION_SCHEDULE_MISSING'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and exists(
            select 1
            from jsonb_array_elements(
              coalesce(presentation_model#>'{week_period,days}','[]'::jsonb)) d
            cross join lateral jsonb_array_elements(
              coalesce(d->'shift_lines','[]'::jsonb)) s
            where s->>'date'<>d->>'date')
          then 'TIMESHEET_SCHEDULE_DATE_OUTSIDE_PERIOD'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and coalesce((presentation_model->>'additional_units_snapshot_stale')::boolean,false)
          then 'TIMESHEET_ADDITIONAL_UNITS_SNAPSHOT_STALE'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          and exists(
            select 1
            from jsonb_array_elements(coalesce(
              presentation_model#>'{additional_units_section,rows}',
              '[]'::jsonb)) a
            where nullif(a->>'date','') is not null
              and ((a->>'date')::date<
                (presentation_model#>>'{week_period,start_date}')::date
                or (a->>'date')::date>
                (presentation_model#>>'{week_period,end_date}')::date))
          then 'TIMESHEET_ADDITIONAL_UNIT_DATE_OUTSIDE_PERIOD'
        when presentation_model->>'schema_version'='TIMESHEET_RENDER_MODEL_V2'
          then null
        when jsonb_array_length(coalesce(
            presentation_model->'daily_schedule_rows','[]'::jsonb))=0
          and jsonb_array_length(coalesce(
            presentation_model->'weekly_schedule_rows','[]'::jsonb))=0
          then 'TIMESHEET_PRESENTATION_SCHEDULE_MISSING'
        else null end error_code
    from timesheet_models
  ),
  assembled as materialized (
    select m.*,
      encode(digest(m.presentation_model::text,'sha256'),'hex') presentation_model_hash,
      jsonb_build_object(
        'snapshot_schema_version',m.snapshot_schema_version,
        'request_key',m.request_key,
        'presentation_model',m.presentation_model,
        'presentation_model_hash',encode(digest(m.presentation_model::text,'sha256'),'hex'),
        'timesheet_sources',m.timesheet_sources,
        'supporting_sources',m.supporting_sources,
        'supporting_manifest',coalesce((select sma.supporting_manifest from supporting_manifest_agg sma where sma.invoice_id=(m.presentation_model->>'invoice_id')::uuid),'[]'::jsonb),
        'higher_rate_support',m.higher_rate_support
      ) snapshot_json
    from all_models m
  )
  select d.request_key,d.snapshot_schema_version,d.presentation_model,d.timesheet_sources,d.supporting_sources,d.higher_rate_support,d.snapshot_json,d.snapshot_hash,d.valid,d.error_code,d.error_detail
  from duplicate_key_results d
  union all
  select i.request_key,i.snapshot_schema_version,i.presentation_model,i.timesheet_sources,i.supporting_sources,i.higher_rate_support,i.snapshot_json,i.snapshot_hash,i.valid,i.error_code,i.error_detail
  from invalid_request_results i
  union all
  select m.request_key,m.snapshot_schema_version,m.presentation_model,m.timesheet_sources,m.supporting_sources,m.higher_rate_support,
         m.snapshot_json,encode(digest(m.snapshot_json::text,'sha256'),'hex'),m.error_code is null,
         m.error_code,
         case when m.error_code is null then '{}'::jsonb else jsonb_build_object('request_key',m.request_key,'code',m.error_code) end
  from assembled m
  union all
  select e.request_key,e.snapshot_schema_version,e.presentation_model,e.timesheet_sources,e.supporting_sources,e.higher_rate_support,e.snapshot_json,e.snapshot_hash,e.valid,e.error_code,e.error_detail
  from missing_entity_results e
  ;
end;
$function$;

revoke all on function private._invoice_presentation_snapshot_batch(jsonb,timestamptz)
  from public,anon,authenticated;
grant execute on function private._invoice_presentation_snapshot_batch(jsonb,timestamptz)
  to service_role;

\endif

create or replace function public.invoice_detail_get(
  p_invoice_id uuid,
  p_actor_user_id uuid
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_role text;
  v_service boolean:=coalesce(auth.role(),'')='service_role';
  v_result jsonb;
begin
  if p_invoice_id is null then
    raise exception using errcode='22023',message='invoice_id is required';
  end if;
  if not v_service
     and(auth.uid() is null or auth.uid() is distinct from p_actor_user_id) then
    raise exception using errcode='42501',message='Authenticated actor mismatch';
  end if;

  select lower(btrim(coalesce(u.role,''))) into v_role
  from public.tms_users u
  where u.id=p_actor_user_id and u.is_active;
  if(not found or v_role<>'admin') and not v_service then
    raise exception using errcode='42501',
      message='Invoice administrator permission required';
  end if;

  if not exists(select 1 from public.invoices i where i.id=p_invoice_id) then
    return jsonb_build_object('ok',false,'error_code','INVOICE_NOT_FOUND');
  end if;

  with
  inv as materialized (
    select i.* from public.invoices i where i.id=p_invoice_id
  ),
  lines as materialized (
    select l.*,td.r2_key exact_timesheet_document_r2_key,
      pc.precheck_status,pc.has_timesheet_evidence_pdf
    from public.invoice_lines l
    left join public.timesheets t
      on t.timesheet_id=l.timesheet_id and t.is_current
    left join lateral (
      select v.r2_key
      from public.invoice_document_versions v
      where v.entity_type='TIMESHEET'
        and v.entity_id=t.timesheet_id
        and v.purpose='TIMESHEET'
        and v.source_revision=t.document_revision::text
        and v.status='READY'
        and nullif(v.r2_key,'') is not null
        and nullif(v.sha256,'') is not null
        and coalesce(v.size_bytes,0)>0
        and coalesce(v.page_count,0)>0
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1
    ) td on true
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=l.timesheet_id
    where l.invoice_id=p_invoice_id
  ),
  source_timesheets as materialized (
    select distinct x.timesheet_id
    from (
      select l.timesheet_id from lines l where l.timesheet_id is not null
      union
      select case when coalesce(l.meta_json->>'timesheet_id','')~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (l.meta_json->>'timesheet_id')::uuid end
      from lines l
      where l.timesheet_id is null
    ) x
    where x.timesheet_id is not null
  ),
  references_batch as materialized (
    select r.*
    from private._invoice_reference_rows_batch(array[p_invoice_id]) r
  ),
  reference_rows as materialized (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'row_key',r.row_key,'timesheet_id',r.timesheet_id,
        'candidate_id',coalesce(ct.candidate_id,tf.candidate_id),
         'candidate_display',coalesce(nullif(btrim(cc.display_name),''),
           nullif(btrim(cf.display_name),'')),
         'week_ending_date',t.week_ending_date,
         'document_revision',t.document_revision,
         'sheet_scope',r.sheet_scope,'submission_mode',r.submission_mode,
        'ref_target',r.ref_target,'segment_id',r.segment_id,
        'day_ymd',r.day_ymd,'start_utc',r.start_utc,'end_utc',r.end_utc,
        'current_reference',r.current_reference,'is_required',r.is_required)
      order by r.timesheet_id,r.day_ymd nulls last,r.start_utc nulls last,
        r.segment_id nulls last),'[]'::jsonb) rows
    from references_batch r
    left join public.timesheets t
      on t.timesheet_id=r.timesheet_id and t.is_current
    left join public.contracts ct on ct.id=t.contract_id
    left join public.timesheets_financials tf
      on tf.timesheet_id=r.timesheet_id and tf.is_current
    left join public.candidates cc on cc.id=ct.candidate_id
    left join public.candidates cf on cf.id=tf.candidate_id
  ),
  current_financials as materialized (
    select distinct on (tf.timesheet_id) tf.*
    from public.timesheets_financials tf
    join source_timesheets s on s.timesheet_id=tf.timesheet_id
    where tf.is_current
    order by tf.timesheet_id,tf.updated_at desc nulls last,tf.created_at desc nulls last,tf.id desc
  ),
  reference_sources as materialized (
    select coalesce(jsonb_object_agg(t.timesheet_id::text,
       jsonb_build_object(
         'candidate_id',coalesce(ct.candidate_id,f.candidate_id),
         'candidate_display',coalesce(nullif(btrim(cc.display_name),''),
           nullif(btrim(cf.display_name),'')),
         'week_ending_date',t.week_ending_date,
         'document_revision',t.document_revision,
         'reference_number',t.reference_number,
         'hospital_norm',t.hospital_norm,
         'ward_norm',t.ward_norm,
         'source_mode',upper(coalesce(f.invoice_breakdown_json->>'mode','')),
         'day_references_json',t.day_references_json,
        'actual_schedule_json',case
          when upper(coalesce(f.invoice_breakdown_json->>'mode',''))='SEGMENTS'
            and jsonb_typeof(f.invoice_breakdown_json->'segments')='array'
          then coalesce((
            select jsonb_agg(jsonb_build_object(
              'segment_id',seg.value->>'segment_id',
              'date',seg.value->>'date',
              'start_utc',seg.value->>'start_utc',
              'end_utc',seg.value->>'end_utc',
              'start',seg.value->>'start_utc',
              'end',seg.value->>'end_utc',
              'ref_num',seg.value->>'ref_num',
              'source_system',seg.value->>'source_system')
              order by coalesce(seg.value->>'date',''),
                coalesce(seg.value->>'start_utc',''),
                coalesce(seg.value->>'segment_id',''))
            from jsonb_array_elements(f.invoice_breakdown_json->'segments') seg(value)
            where nullif(btrim(coalesce(
              seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
          ),'[]'::jsonb)
          when jsonb_typeof(t.actual_schedule_json)='array'
            then t.actual_schedule_json
          else '[]'::jsonb end)
      order by t.timesheet_id),'{}'::jsonb) rows
     from source_timesheets s
     join public.timesheets t on t.timesheet_id=s.timesheet_id and t.is_current
     left join current_financials f on f.timesheet_id=t.timesheet_id
     left join public.contracts ct on ct.id=t.contract_id
     left join public.candidates cc on cc.id=ct.candidate_id
     left join public.candidates cf on cf.id=f.candidate_id
   ),
  line_totals as materialized (
    select count(*)::integer line_count,
      round(coalesce(sum(l.total_charge_ex_vat),0),2) net,
      round(coalesce(sum(l.vat_amount),0),2) vat,
      round(coalesce(sum(l.total_inc_vat),0),2) gross
    from lines l
  ),
  timesheet_readiness as materialized (
    select t.timesheet_id,t.submission_mode,t.document_state,
      t.current_document_version_id,t.manual_document_asset_id,
      summary.client_no_timesheet_required,summary.client_is_nhsp,
      case
        when coalesce(summary.client_no_timesheet_required,false)
          or coalesce(summary.client_is_nhsp,false) then true
        else dv.status='READY'
      end ready,
      case
        when coalesce(summary.client_no_timesheet_required,false) then 'NOT_REQUIRED'
        when coalesce(summary.client_is_nhsp,false) then 'NHSP_SUPPORT'
        when upper(coalesce(t.submission_mode::text,'')) in('MANUAL','QR')
          then 'MANUAL_TIMESHEET'
        else 'ELECTRONIC_TIMESHEET'
      end support_type,
      coalesce(dv.page_count,0) pages
    from source_timesheets s
    left join public.timesheets t
      on t.timesheet_id=s.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base summary
      on summary.timesheet_id=s.timesheet_id
    left join lateral (
      select v.status,v.page_count
      from public.invoice_document_versions v
      where v.entity_type='TIMESHEET'
        and v.entity_id=t.timesheet_id
        and v.purpose='TIMESHEET'
        and v.source_revision=t.document_revision::text
        and v.status='READY'
        and nullif(v.r2_key,'') is not null
        and nullif(v.sha256,'') is not null
        and coalesce(v.size_bytes,0)>0
        and coalesce(v.page_count,0)>0
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1
    ) dv on true
  ),
  evidence_rows as materialized (
    select e.id,e.timesheet_id,e.kind,e.document_role,e.candidate_component_id,
      e.display_name,e.storage_key,e.created_at,
      e.document_asset_id,e.processing_state,e.processing_error_json,
      a.status asset_status,a.normalised_r2_key,a.normalised_sha256,
      a.normalised_size_bytes,a.normalised_page_count,
      case when e.document_asset_id is null then 'NOT_REGISTERED'
        when a.status='READY' then 'READY'
        when a.status in('UNSUPPORTED','CORRUPT','MISSING','FAILED') then 'FAILED'
        else 'NOT_READY' end readiness
    from public.timesheet_evidence e
    join source_timesheets s on s.timesheet_id=e.timesheet_id
    left join public.invoice_document_assets a on a.id=e.document_asset_id
  ),
  segment_stats as materialized (
    select f.timesheet_id,f.id tsfin_id,
      coalesce(jsonb_agg(seg.value order by coalesce(seg.value->>'date',''),
        coalesce(seg.value->>'segment_id','')) filter(
          where nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'')
            =p_invoice_id::text),'[]'::jsonb) invoiced_segments,
      count(*) filter(where nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'') is null)
        ::integer uninvoiced_segment_count,
      count(*) filter(where nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'') is not null
        and nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'')<>p_invoice_id::text)
        ::integer locked_elsewhere_segment_count
    from current_financials f
    cross join lateral jsonb_array_elements(
      case when upper(coalesce(f.invoice_breakdown_json->>'mode',''))='SEGMENTS'
          and jsonb_typeof(f.invoice_breakdown_json->'segments')='array'
        then f.invoice_breakdown_json->'segments' else '[]'::jsonb end) seg(value)
    group by f.timesheet_id,f.id
  ),
  segment_projection as materialized (
    select coalesce(jsonb_object_agg(s.timesheet_id::text,jsonb_build_object(
      'tsfin_id',s.tsfin_id,'invoiced_segments',s.invoiced_segments,
      'uninvoiced_segment_count',s.uninvoiced_segment_count,
      'locked_elsewhere_segment_count',s.locked_elsewhere_segment_count)
      order by s.timesheet_id),'{}'::jsonb) rows
    from segment_stats s
  ),
  history_audit as materialized (
    select jsonb_build_object(
      'kind','AUDIT','id',ae.id,'ts_utc',ae.ts_utc,
      'actor_user_id',ae.actor_user_id,
      'actor_display',coalesce(ae.actor_display,u.display_name,u.email,'CloudTMS server'),
      'actor_role_at_time',coalesce(ae.actor_role_at_time,u.role,'system'),
      'action',ae.action,'reason',ae.reason,'object_type',ae.object_type,
      'object_id_text',ae.object_id_text,'before_json',ae.before_json,
      'after_json',ae.after_json,'correlation_id',ae.correlation_id) row_json,
      ae.ts_utc
    from public.audit_events ae
    left join public.tms_users u on u.id=ae.actor_user_id
    where ae.object_type in('invoice','invoices')
      and ae.object_id_text=p_invoice_id::text
    order by ae.ts_utc desc,ae.id desc limit 500
  ),
  invoice_mail as materialized (
    select m.*,jsonb_build_object(
      'kind','EMAIL','mail_outbox_id',m.id,'ts_utc',m.created_at_utc,
      'status',m.status,'to',m."to",'cc',m.cc,'subject',m.subject,
      'reference',m.reference,'sent_at',m.sent_at,'failed_at',m.failed_at) row_json
    from public.mail_outbox m
    where upper(coalesce(m.type,''))='INVOICE'
      and jsonb_typeof(m.attachments)='array'
      and exists(
        select 1 from jsonb_array_elements(m.attachments) a(value)
        where a.value->>'invoice_id'=p_invoice_id::text
          or a.value->>'document_version_id'=(
            select i.issued_document_version_id::text from inv i))
    order by m.created_at_utc desc,m.id desc limit 200
  ),
  history_projection as materialized (
    select coalesce(jsonb_agg(x.row_json order by x.ts_utc desc),'[]'::jsonb) rows
    from (
      select h.row_json,h.ts_utc from history_audit h
      union all
      select m.row_json,m.created_at_utc from invoice_mail m
    ) x
  ),
  current_documents as materialized (
    select
      coalesce((
        select jsonb_build_object(
          'id',v.id,'operation_id',v.operation_id,'purpose',v.purpose,
          'source_revision',v.source_revision,'template_version',v.template_version,
          'status',v.status,'r2_key',v.r2_key,'sha256',v.sha256,
          'size_bytes',v.size_bytes,'page_count',v.page_count,
          'created_at_utc',v.created_at_utc,'ready_at_utc',v.ready_at_utc,
          'verified_at_utc',v.verified_at_utc,'error',v.error_json)
        from public.invoice_document_versions v
        join inv i on i.preview_document_version_id=v.id
        where v.entity_type='INVOICE' and v.entity_id=p_invoice_id
          and v.purpose='DRAFT_PREVIEW'),'null'::jsonb) preview,
      coalesce((
        select jsonb_build_object(
          'id',v.id,'operation_id',v.operation_id,'purpose',v.purpose,
          'source_revision',v.source_revision,'template_version',v.template_version,
          'status',v.status,'r2_key',v.r2_key,'sha256',v.sha256,
          'size_bytes',v.size_bytes,'page_count',v.page_count,
          'created_at_utc',v.created_at_utc,'ready_at_utc',v.ready_at_utc,
          'verified_at_utc',v.verified_at_utc,'error',v.error_json)
        from public.invoice_document_versions v
        join inv i on i.issued_document_version_id=v.id
        where v.entity_type='INVOICE' and v.entity_id=p_invoice_id
          and v.purpose='FINAL_ISSUE'),'null'::jsonb) issued,
      coalesce((
        select jsonb_build_object(
          'id',v.id,'operation_id',v.operation_id,'purpose',v.purpose,
          'source_revision',v.source_revision,'template_version',v.template_version,
          'status',v.status,'r2_key',v.r2_key,'sha256',v.sha256,
          'size_bytes',v.size_bytes,'page_count',v.page_count,
          'created_at_utc',v.created_at_utc,'ready_at_utc',v.ready_at_utc,
          'verified_at_utc',v.verified_at_utc,'error',v.error_json)
        from public.invoice_document_versions v
        where v.entity_type='INVOICE' and v.entity_id=p_invoice_id
        order by v.created_at_utc desc,v.id desc limit 1),'null'::jsonb) latest
  ),
  active_document as materialized (
    select o.id operation_id,o.status,o.phase,o.progress_json,o.error_json,o.change_seq
    from public.invoice_operations o
    join inv i on i.active_document_operation_id=o.id
  ),
  active_issue as materialized (
    select c.operation_id,c.id chunk_id,c.status,c.phase,c.progress_json,c.error_json,
      o.change_seq
    from public.invoice_operation_chunks c
    join public.invoice_operations o on o.id=c.operation_id
    where c.chunk_type='ISSUE_INVOICE' and c.entity_type='INVOICE'
      and c.entity_id=p_invoice_id
      and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
     order by c.updated_at_utc desc,c.id desc limit 1
  ),
  source_edit_authority as materialized (
    select
      (
        i.status in('DRAFT','ON_HOLD')
        and i.issued_at_utc is null
        and i.paid_at_utc is null
        and i.active_issue_operation_id is null
        and upper(coalesce(i.issue_state,'')) not in(
          'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
        and not exists(select 1 from active_issue)
        and not exists(
          select 1
          from source_timesheets s
          where coalesce((
            public._ctms_import_correction_classify_v1(s.timesheet_id)
              ->>'is_import_authoritative_correction')::boolean,false)
        )
      ) can_edit_source,
      coalesce((
        select jsonb_agg(code order by ordinal)
        from (
          values
            (1,case when i.status not in('DRAFT','ON_HOLD')
              then 'INVOICE_SOURCE_EDIT_STATUS_FORBIDDEN' end),
            (2,case when i.issued_at_utc is not null
              then 'INVOICE_SOURCE_EDIT_ISSUED' end),
            (3,case when i.paid_at_utc is not null
              then 'INVOICE_SOURCE_EDIT_PAID' end),
            (4,case when i.active_issue_operation_id is not null
              or upper(coalesce(i.issue_state,'')) in(
                'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
              or exists(select 1 from active_issue)
              then 'INVOICE_SOURCE_EDIT_ISSUE_IN_PROGRESS' end),
            (5,case when exists(
              select 1
              from source_timesheets s
              where coalesce((
                public._ctms_import_correction_classify_v1(s.timesheet_id)
                  ->>'is_import_authoritative_correction')::boolean,false))
              then 'IMPORT_AUTHORITATIVE_CORRECTION_SOURCE_EDIT_FORBIDDEN' end)
        ) blockers(ordinal,code)
        where code is not null
      ),'[]'::jsonb) source_edit_blocker_codes,
      exists(
        select 1
        from public.invoice_document_versions dv
        left join public.invoice_operations op on op.id=dv.operation_id
        where dv.entity_type='INVOICE'
          and dv.entity_id=i.id
          and dv.purpose='DRAFT_PREVIEW'
          and dv.source_revision=i.document_revision::text
          and (
            (dv.status='READY'
              and nullif(btrim(coalesce(dv.r2_key,'')),'') is not null
              and nullif(btrim(coalesce(dv.sha256,'')),'') is not null
              and coalesce(dv.size_bytes,0)>0
              and coalesce(dv.page_count,0)>0)
            or (
              dv.id=i.preview_document_version_id
              and dv.status in(
                'PLANNING','WAITING_FOR_INPUTS','RENDERING',
                'ASSEMBLING','VERIFYING','READY'))
            or (
              dv.operation_id=i.active_document_operation_id
              and op.operation_type='BUILD_DOCUMENT'
              and op.entity_type='INVOICE'
              and op.entity_id=i.id
              and op.source_revision=i.document_revision::text
              and coalesce(op.input_json->>'purpose','')='DRAFT_PREVIEW'
              and op.status in(
                'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
          )
      ) source_edit_will_replace_preview
    from inv i
  ),
  issue_validation as materialized (
    select v.*
    from inv i
    cross join lateral private._invoice_issue_validate_batch(
      jsonb_build_array(jsonb_build_object(
        'request_key','detail:'||i.id::text,
        'invoice_id',i.id,'expected_revision',i.document_revision,
        'allow_early',false,'deliver',true)),
      (now() at time zone 'Europe/London')::date) v
  ),
  support_summary as materialized (
    select
      count(*) filter(where support_type='ELECTRONIC_TIMESHEET')::integer
        electronic_timesheet_count,
      count(*) filter(where support_type='ELECTRONIC_TIMESHEET'
        and not coalesce(ready,false))::integer electronic_timesheet_not_ready_count,
      count(*) filter(where support_type='MANUAL_TIMESHEET')::integer
        manual_timesheet_count,
      count(*) filter(where support_type='MANUAL_TIMESHEET'
        and not coalesce(ready,false))::integer manual_timesheet_not_ready_count,
      coalesce(sum(pages),0)::integer estimated_timesheet_pages
    from timesheet_readiness
  ),
  evidence_summary as materialized (
    select count(*)::integer evidence_count,
      count(*) filter(where readiness='NOT_REGISTERED')::integer evidence_unregistered_count,
      count(*) filter(where readiness='NOT_READY')::integer evidence_not_ready_count,
      count(*) filter(where readiness='FAILED')::integer evidence_failed_count,
      coalesce(sum(normalised_page_count),0)::integer estimated_evidence_pages
    from evidence_rows
  ),
  projections as materialized (
    select
      (select coalesce(jsonb_agg(
        jsonb_build_object(
          'id',l.id,'invoice_id',l.invoice_id,'timesheet_id',l.timesheet_id,
          'booking_id',l.booking_id,'description',l.description,
          'hours_day',l.hours_day,'hours_night',l.hours_night,
          'hours_sat',l.hours_sat,'hours_sun',l.hours_sun,'hours_bh',l.hours_bh,
          'pay_day',l.pay_day,'pay_night',l.pay_night,'pay_sat',l.pay_sat,
          'pay_sun',l.pay_sun,'pay_bh',l.pay_bh,
          'charge_day',l.charge_day,'charge_night',l.charge_night,
          'charge_sat',l.charge_sat,'charge_sun',l.charge_sun,
          'charge_bh',l.charge_bh,'total_pay_ex_vat',l.total_pay_ex_vat,
          'total_charge_ex_vat',l.total_charge_ex_vat,
          'margin_ex_vat',l.margin_ex_vat,'vat_rate_pct',l.vat_rate_pct,
          'vat_amount',l.vat_amount,'total_inc_vat',l.total_inc_vat,
          'created_at',l.created_at,'paper_ts_r2_key',l.exact_timesheet_document_r2_key,
          'meta_json',l.meta_json,'source_key',l.source_key,
          'precheck_status',l.precheck_status,
          'has_timesheet_evidence_pdf',l.has_timesheet_evidence_pdf,
          'paper_ts_r2_key',l.exact_timesheet_document_r2_key,
          'is_adjustment',l.timesheet_id is null
            or upper(coalesce(l.meta_json->>'line_type',''))='ADJUSTMENT',
          'line_type_norm',upper(coalesce(l.meta_json->>'line_type','')))
        order by l.created_at,l.id),'[]'::jsonb) from lines l) line_rows,
      (select coalesce(jsonb_agg(jsonb_build_object(
        'id',e.id,'timesheet_id',e.timesheet_id,'kind',e.kind,
        'document_role',e.document_role,'candidate_component_id',e.candidate_component_id,
        'display_name',e.display_name,'storage_key',e.storage_key,
        'created_at',e.created_at,'document_asset_id',e.document_asset_id,
        'processing_state',e.processing_state,
        'processing_error',e.processing_error_json,'asset_status',e.asset_status,
        'normalised_r2_key',e.normalised_r2_key,
        'normalised_sha256',e.normalised_sha256,
        'normalised_size_bytes',e.normalised_size_bytes,
        'normalised_page_count',e.normalised_page_count,
        'readiness',e.readiness) order by e.created_at,e.id),
        '[]'::jsonb) from evidence_rows e) evidence,
      (select coalesce(jsonb_agg(jsonb_build_object(
        'id',e.id,'timesheet_id',e.timesheet_id,'kind',e.kind,
        'document_role',e.document_role,'candidate_component_id',e.candidate_component_id,
        'display_name',e.display_name,'storage_key',e.storage_key,
        'created_at',e.created_at,'document_asset_id',e.document_asset_id,
        'processing_state',e.processing_state,'asset_status',e.asset_status,
        'normalised_r2_key',e.normalised_r2_key,
        'normalised_sha256',e.normalised_sha256,
        'normalised_size_bytes',e.normalised_size_bytes,
        'normalised_page_count',e.normalised_page_count,
        'readiness',e.readiness) order by e.created_at,e.id),
        '[]'::jsonb) from evidence_rows e
        where upper(coalesce(e.kind,''))='TIMESHEET') timesheet_evidence,
      (select coalesce(jsonb_agg(jsonb_build_object(
        'id',e.id,'timesheet_id',e.timesheet_id,'kind',e.kind,
        'document_role',e.document_role,'candidate_component_id',e.candidate_component_id,
        'display_name',e.display_name,'storage_key',e.storage_key,
        'created_at',e.created_at,'document_asset_id',e.document_asset_id,
        'processing_state',e.processing_state,'asset_status',e.asset_status,
        'normalised_r2_key',e.normalised_r2_key,
        'normalised_sha256',e.normalised_sha256,
        'normalised_size_bytes',e.normalised_size_bytes,
        'normalised_page_count',e.normalised_page_count,
        'readiness',e.readiness) order by e.created_at,e.id),
        '[]'::jsonb) from evidence_rows e
        where upper(coalesce(e.kind,''))<>'TIMESHEET') evidence_other,
      (select coalesce(jsonb_agg(jsonb_build_object(
        'invoice_id',h.invoice_id,'source_system',h.source_system,
        'import_id',h.import_id,'header_rows',h.header_rows,
        'header_columns',h.header_columns,'rows_json',h.rows_json)
        order by h.source_system,h.import_id),
        '[]'::jsonb) from public.invoice_hr_source_rows h
        where h.invoice_id=p_invoice_id) hr_rows,
      (select coalesce(jsonb_agg(jsonb_build_object(
        'tsfin_id',f.id,'timesheet_id',f.timesheet_id,
        'external_source_rows_json',f.external_source_rows_json,
        'mileage_units',f.mileage_units,'mileage_pay_rate',f.mileage_pay_rate,
        'mileage_charge_rate',f.mileage_charge_rate)
        order by f.timesheet_id),'[]'::jsonb) from current_financials f) tsfin_rows,
      (select coalesce(jsonb_object_agg(f.timesheet_id::text,f.id::text
        order by f.timesheet_id),'{}'::jsonb) from current_financials f) tsfin_map
  ),
  assembled as materialized (
    select i.*,lt.*,rr.rows reference_rows,rs.rows reference_sources,
      sp.rows segments,p.*,hp.rows history_rows,ss.*,es.*,
      sea.can_edit_source,sea.source_edit_blocker_codes,
      sea.source_edit_will_replace_preview,
      cd.preview,cd.issued,cd.latest,
      ad.operation_id document_operation_id,ad.status document_operation_status,
      ad.phase document_operation_phase,ad.progress_json document_operation_progress,
      ad.error_json document_operation_error,ad.change_seq document_change_seq,
      ai.operation_id issue_operation_id,ai.chunk_id issue_chunk_id,
      ai.status issue_status,ai.phase issue_phase,ai.progress_json issue_progress,
      ai.error_json issue_error,ai.change_seq issue_change_seq,
      iv.hard_blocker_codes blocker_codes,iv.document_dependency_codes,
      iv.delivery_blocker_codes,iv.warning_codes,iv.can_issue_only,
      iv.can_issue_and_deliver,iv.route_policy_result,iv.detail_json
    from inv i cross join line_totals lt cross join reference_rows rr
    cross join reference_sources rs cross join segment_projection sp
    cross join projections p cross join history_projection hp
    cross join support_summary ss cross join evidence_summary es
    cross join source_edit_authority sea
    cross join current_documents cd
    left join active_document ad on true left join active_issue ai on true
    left join issue_validation iv on true
  ),
  allowlisted_snapshot as materialized (
    select a.*,
      jsonb_strip_nulls(jsonb_build_object(
        'agency_name',a.header_snapshot_json->'agency_name',
        'agency_logo',a.header_snapshot_json->'agency_logo',
        'agency_logo_url',a.header_snapshot_json->'agency_logo_url',
        'registered_address',a.header_snapshot_json->'registered_address',
        'company_reg_number',a.header_snapshot_json->'company_reg_number',
        'company_registration_number',
          a.header_snapshot_json->'company_registration_number',
        'vat_registration_number',
          a.header_snapshot_json->'vat_registration_number',
        'client_id',a.header_snapshot_json->'client_id',
        'client_name',a.header_snapshot_json->'client_name',
        'client_invoice_address',
          a.header_snapshot_json->'client_invoice_address',
        'client_primary_invoice_email',
          a.header_snapshot_json->'client_primary_invoice_email',
        'issued_at_utc',a.header_snapshot_json->'issued_at_utc',
        'due_at_utc',a.header_snapshot_json->'due_at_utc',
        'payment_terms_days',a.header_snapshot_json->'payment_terms_days',
        'vat_chargeable',a.header_snapshot_json->'vat_chargeable',
        'applied_vat_rate_pct',
          a.header_snapshot_json->'applied_vat_rate_pct',
        'hide_bank_footer',a.header_snapshot_json->'hide_bank_footer',
        'bank',jsonb_strip_nulls(jsonb_build_object(
          'name',a.header_snapshot_json#>'{bank,name}',
          'sort_code',a.header_snapshot_json#>'{bank,sort_code}',
          'account_number',a.header_snapshot_json#>'{bank,account_number}')),
        'stationery_key',a.header_snapshot_json->'stationery_key',
        'stationery_margins_mm',
          a.header_snapshot_json->'stationery_margins_mm',
        'attach_policy',jsonb_strip_nulls(jsonb_build_object(
          'ts_attach_to_invoice',
            a.header_snapshot_json#>'{attach_policy,ts_attach_to_invoice}',
          'hr_attach_to_invoice',
            a.header_snapshot_json#>'{attach_policy,hr_attach_to_invoice}',
          'requires_hr',
            a.header_snapshot_json#>'{attach_policy,requires_hr}')),
        'meta',jsonb_strip_nulls(jsonb_build_object(
          'consolidation_mode',
            a.header_snapshot_json#>'{meta,consolidation_mode}',
          'invoice_week_start',
            a.header_snapshot_json#>'{meta,invoice_week_start}',
          'segment_count',a.header_snapshot_json#>'{meta,segment_count}',
          'self_bill',a.header_snapshot_json#>'{meta,self_bill}',
          'source',a.header_snapshot_json#>'{meta,source}',
          'timesheet_count',
            a.header_snapshot_json#>'{meta,timesheet_count}'))
      )) business_header_snapshot
    from assembled a
  )
  select jsonb_build_object(
    'ok',true,
    'source_edit_queue_contract','INVOICE_SOURCE_EDIT_QUEUE_V1',
    'invoice',jsonb_build_object(
      'id',a.id,'type',a.type,'invoice_no',a.invoice_no,'client_id',a.client_id,
      'issued_at_utc',a.issued_at_utc,'due_at_utc',a.due_at_utc,
      'paid_at_utc',a.paid_at_utc,'status',a.status,
      'status_date_utc',a.status_date_utc,'subtotal_ex_vat',a.subtotal_ex_vat,
      'vat_amount',a.vat_amount,'total_inc_vat',a.total_inc_vat,
      'original_invoice_id',a.original_invoice_id,'notes',a.notes,
      'created_at',a.created_at,'updated_at',a.updated_at,
      'invoice_pdf_r2_key',a.invoice_pdf_r2_key,
      'invoice_pdf_generated_at_utc',a.invoice_pdf_generated_at_utc,
      'header_snapshot_json',a.business_header_snapshot,
      'on_hold_reason',a.on_hold_reason,'do_not_send',a.do_not_send,
      'credit_note_created_at_utc',a.credit_note_created_at_utc,
      'document_revision',a.document_revision,'document_state',a.document_state,
      'preview_document_version_id',a.preview_document_version_id,
      'issued_document_version_id',a.issued_document_version_id,
      'active_document_operation_id',a.active_document_operation_id,
      'issue_state',a.issue_state,
      'active_issue_operation_id',a.active_issue_operation_id,
      'last_document_error_json',a.last_document_error_json),
    'items',a.line_rows,'lines',a.line_rows,
    'header_snapshot_json',coalesce(a.business_header_snapshot,'{}'::jsonb),
    'attach_policy',a.business_header_snapshot->'attach_policy',
    'evidence',a.evidence,'timesheet_evidence',a.timesheet_evidence,
    'evidence_other',a.evidence_other,
    'hr_source_rows_cache',a.hr_rows,
    'tsfin_external_source_rows',a.tsfin_rows,
    'segments_on_invoice_by_timesheet',a.segments,
    'segments_by_timesheet',a.segments,
    'history',a.history_rows,
    'tsfin_id_by_timesheet_id',a.tsfin_map,
    'reference_rows',a.reference_rows,
    'timesheet_reference_sources_by_id',a.reference_sources,
    'email_summary',jsonb_build_object(
      'emailed_once',(select count(*)>0 from invoice_mail),
      'email_count',(select count(*) from invoice_mail),
      'last_email_at_utc',(select max(created_at_utc) from invoice_mail)),
    'financial_validation',jsonb_build_object(
      'stored_net',round(coalesce(a.subtotal_ex_vat,0),2),
      'calculated_net',a.net,'stored_vat',round(coalesce(a.vat_amount,0),2),
      'calculated_vat',a.vat,'stored_gross',round(coalesce(a.total_inc_vat,0),2),
      'calculated_gross',a.gross),
    'document_readiness',jsonb_build_object(
      'revision',a.document_revision,'state',a.document_state,
      'preview',a.preview,'issued',a.issued,'latest',a.latest,
      'operation_id',a.document_operation_id,'operation_status',a.document_operation_status,
      'operation_phase',a.document_operation_phase,'operation_progress',a.document_operation_progress,
      'operation_error',coalesce(a.document_operation_error,a.last_document_error_json),
      'change_seq',a.document_change_seq,
      'electronic_timesheet_count',a.electronic_timesheet_count,
      'electronic_timesheet_not_ready_count',a.electronic_timesheet_not_ready_count,
      'manual_timesheet_count',a.manual_timesheet_count,
      'manual_timesheet_not_ready_count',a.manual_timesheet_not_ready_count,
      'evidence_count',a.evidence_count,
      'evidence_unregistered_count',a.evidence_unregistered_count,
      'evidence_not_ready_count',a.evidence_not_ready_count,
      'evidence_failed_count',a.evidence_failed_count,
      'healthroster_support_count',(select count(*) from public.invoice_hr_source_rows h
        where h.invoice_id=p_invoice_id and upper(coalesce(h.source_system,''))='HEALTHROSTER'),
      'nhsp_support_count',(select count(*) from public.invoice_hr_source_rows h
        where h.invoice_id=p_invoice_id and upper(coalesce(h.source_system,''))='NHSP'),
      'higher_rate_support_count',(select count(*) from lines l
        where upper(coalesce(l.meta_json->>'line_type','')) like '%HIGHER_RATE%'),
      'estimated_supporting_pages',a.estimated_timesheet_pages+a.estimated_evidence_pages),
    'issue',jsonb_build_object(
      'state',a.issue_state,'operation_id',a.issue_operation_id,
      'chunk_id',a.issue_chunk_id,'status',a.issue_status,'phase',a.issue_phase,
      'progress',a.issue_progress,'error',a.issue_error,'change_seq',a.issue_change_seq,
      'validation_detail',a.detail_json,
      'document_dependencies',coalesce(a.document_dependency_codes,'[]'::jsonb),
      'delivery_blockers',coalesce(a.delivery_blocker_codes,'[]'::jsonb),
      'route_policy',coalesce(a.route_policy_result,'{}'::jsonb),
      'warnings',coalesce(a.warning_codes,'[]'::jsonb)),
    'blocker_codes',coalesce(a.blocker_codes,'[]'::jsonb),
    'source_edit_blocker_codes',coalesce(a.source_edit_blocker_codes,'[]'::jsonb),
    'source_edit_will_replace_preview',coalesce(a.source_edit_will_replace_preview,false),
    'actions',jsonb_build_object(
      'can_edit',a.status='DRAFT' and a.issue_operation_id is null,
      'can_edit_source',coalesce(a.can_edit_source,false),
      'can_issue',coalesce(a.can_issue_only,false)
        and a.issue_operation_id is null,
      'can_issue_only',coalesce(a.can_issue_only,false)
        and a.issue_operation_id is null,
      'can_issue_and_deliver',coalesce(a.can_issue_and_deliver,false)
        and a.issue_operation_id is null,
      'can_unissue',a.status='ISSUED',
      'can_retry_document',a.document_state='FAILED',
      'can_retry_issue',coalesce(
        a.issue_status in('BLOCKED','FAILED','DEAD_LETTER'),false))
  ) into v_result
  from allowlisted_snapshot a;

  return v_result;
end;
$function$;

revoke all on function public.invoice_detail_get(uuid,uuid)
  from public,anon,authenticated,service_role,supabase_admin;
grant execute on function public.invoice_detail_get(uuid,uuid)
  to CURRENT_USER,service_role;

CREATE OR REPLACE FUNCTION public.invoice_apply_edits(p_invoice_id uuid, p_payload jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();
  v_anchor_ymd date := (now() at time zone 'Europe/London')::date;


-- =====================================================
-- DEBUG (invoice_debug): single audit row per RPC call
-- =====================================================
v_invoice_debug boolean := false;
v_dbg_started_at timestamptz := now();
v_dbg_steps jsonb := '[]'::jsonb;
v_dbg_sqlstate text := null;
v_dbg_error text := null;
v_dbg_stats jsonb := '{}'::jsonb;


v_dbg_lines_deleted int := 0;
v_dbg_timesheets_unlocked int := 0;
v_dbg_seg_add_refs int := 0;
v_dbg_seg_remove_refs int := 0;
v_dbg_seg_tsfins int := 0;
v_dbg_seg_timesheets_rebuilt int := 0;
v_dbg_seg_timesheets_removed int := 0;
v_dbg_add_timesheets_found int := 0;
v_dbg_add_timesheets_skipped int := 0;

v_rc int := 0;

  v_inv record;
  v_week_start date;
  v_week_end date;

  v_remove_ids uuid[];
  v_add_ts_ids uuid[];

-- segment move payload (explicit segment add/remove)
v_remove_seg_refs jsonb;
v_add_seg_refs jsonb;
v_has_seg_ops boolean := false;
v_refresh_hr_cache boolean := false;
v_seg_tsfin_ids uuid[] := array[]::uuid[];
v_seg_ts_ids uuid[] := array[]::uuid[];
v_seg_refs_to_lock jsonb := '[]'::jsonb;
v_ref jsonb;
v_tsfin_id uuid;
v_seg_id text;
v_has_additional boolean;
v_has_expense_or_mileage boolean;

  -- reference updates (refs-to-issue)
  v_reference_updates jsonb;
  v_refupd jsonb;
  v_refupd_ts_id uuid;
  v_refupd_count int := 0;
  v_refupd_applied int := 0;
  v_refupd_set_refnum boolean;
  v_refupd_set_dayrefs boolean;
  v_refupd_set_sched boolean;
  v_refupd_dayrefs jsonb;
  v_refupd_sched jsonb;
  v_refupd_refnum text;

  -- timesheet hospital / ward source edits
  v_location_updates jsonb;
  v_location_update jsonb;
  v_location_ts_id uuid;
  v_location_count int := 0;
  v_location_applied int := 0;
  v_location_set_hospital boolean;
  v_location_set_ward boolean;
  v_location_hospital_norm text;
  v_location_ward_norm text;
  v_location_ts_ids uuid[] := array[]::uuid[];
  -- Source-edit contract state. Reference and location inputs are merged into
  -- one desired row per timesheet, then written by one statement so the
  -- statement-level invalidation trigger advances each source exactly once.
  v_source_updates_map jsonb := '{}'::jsonb;
  v_source_update jsonb;
  v_source_edit_key text;
  v_source_expected_revision bigint;
  v_source_changed_ts_ids uuid[] := array[]::uuid[];
  v_source_changed_revisions jsonb := '[]'::jsonb;
  v_source_edit_requested boolean := false;
  v_allowed_reference_fields text[]:=array[
    'timesheet_id','expected_document_revision','reference_number',
    'day_references_json','actual_schedule_json'];
  v_allowed_location_fields text[]:=array[
    'timesheet_id','expected_document_revision','hospital_norm','ward_norm'];
  v_allowed_reference_segment_fields text[]:=array[
    'segment_id','date','start_utc','end_utc','start','end','ref_num',
    'source_system'];
  v_source_unsupported_field text;
  v_source_financial_id uuid;
  v_source_mode text;
  v_source_ib jsonb;
  v_source_payload_schedule jsonb;
  v_source_canonical_schedule jsonb;
  v_source_new_segments jsonb;
  v_source_segment_updates jsonb;
  v_source_segment_reference_changed boolean;
  v_source_timesheet_row_changed boolean;
  v_source_match_count integer;
  v_source_match_segment jsonb;
  v_source_payload_segment jsonb;
  v_source_current_segment jsonb;
  v_source_payload_ord bigint;
  v_source_start timestamptz;
  v_source_end timestamptz;
  v_source_marker_rows jsonb:='{}'::jsonb;
  v_source_marker jsonb:='{}'::jsonb;
  v_source_edit_preexisting_preview boolean := false;
  v_source_edit_invoice_replacement_required boolean := false;
  v_pre_edit_invoice_revision bigint;
  v_pre_edit_preview_document_version_id uuid;
  v_pre_edit_active_document_operation_id uuid;
  v_expected_command_count int := 0;
  v_operation_result jsonb;
  v_operation_id uuid;
  v_document_version_id uuid;
  v_command_no int;
  v_command_type text;
  v_operation_status text;
  v_operation_input jsonb;
  v_validated_operations jsonb := '[]'::jsonb;
  v_document_commands jsonb := '[]'::jsonb;
  v_started_operations jsonb := '[]'::jsonb;

  -- reference update side-effects (meta refresh / segment ref sync)
  v_refupd_ts_ids uuid[] := array[]::uuid[];
  v_refupd_ts_ids_distinct uuid[] := array[]::uuid[];
  v_refupd_meta_rows_updated int := 0;
  v_refupd_tsfin_rows_updated int := 0;
  v_refupd_tsfin_segments_updated int := 0;
  v_refupd_invoice_fallback_invalidated boolean := false;

  -- temp vars for reference-derived meta and optional tsfin segment ref sync
  v_ref_ts_id uuid;
  v_ref_ts record;
  v_ref_schedule_refs jsonb := '[]'::jsonb;
  v_ref_schedule_refs_distinct jsonb := '[]'::jsonb;
  v_ref_sched_map jsonb := '{}'::jsonb;
  v_ref_seen_keys jsonb := '{}'::jsonb;
  v_ref_sched_key text;
  v_ref_sched_ref text;
  v_ref_tsfin_id uuid;
  v_ref_ib jsonb;
  v_ref_new_segments jsonb := '[]'::jsonb;
  v_ref_seg_obj jsonb;
  v_ref_seg_start text;
  v_ref_seg_end text;
    v_ref_seg_id text;
v_ref_seg_cur_ref text;
  v_ref_seg_new_ref text;
  v_ref_seg_has_update boolean := false;
  v_ref_seg_updates_this_ts int := 0;
  v_ref_seg_matches_this_ts int := 0;

  -- audit (history) accumulators (NOT debug-only)
  v_hist_adj jsonb := '[]'::jsonb;
  v_hist_seg_add jsonb := '[]'::jsonb;
  v_hist_seg_remove jsonb := '[]'::jsonb;
  v_hist_lines_removed jsonb := '[]'::jsonb;
  v_hist_add_ts jsonb := '[]'::jsonb;

  -- contract week status touch set
  v_cw_ts_ids uuid[] := array[]::uuid[];

  v_ts_ids_touched uuid[] := array[]::uuid[];
  -- FIX: timesheets fully removed from this invoice (no remaining invoice_lines) should be unlocked
  v_ts_ids_fully_removed uuid[] := array[]::uuid[];

  v_vat_chargeable boolean := true;
  v_vat_rate numeric := 0;

  -- adjustments
  adj jsonb;
  v_adj_token text;
  v_adj_desc text;
  v_adj_ex numeric;
  v_adj_vat numeric;
  v_adj_inc numeric;
  v_adj_source_key text;
  v_meta jsonb;

  -- timesheet loop
  tsid uuid;
  snap record;
  ts record;
  pc record;
  contract_id uuid;
  v_settings_authority jsonb;
  c_daily_calc boolean := false;
  c_bucket_labels jsonb := null;
  c_role text := null;
  c_display_site text := null;
  c_ward_hint text := null;

  -- segment filtering
  v_seg jsonb;
  segments jsonb := '[]'::jsonb;
  seg_target date;
  seg_date text;
  natural_start date;
  seg_locked text;
  seg_ref text;

  -- aggregation for weekly line
  h_day numeric; h_night numeric; h_sat numeric; h_sun numeric; h_bh numeric;
  pay_ex numeric; chg_ex numeric; margin_ex numeric;
  vat_amt numeric; inc_amt numeric;
  line_desc text;
  v_source_key text;
  v_exact_timesheet_document_r2_key text;

  -- daily aggregation record
  r_day record;

  -- segment refs for locking
  seg_refs jsonb := '[]'::jsonb;

  -- additional units
  kv record;
  ex jsonb;
  code text;
  unit_count numeric;
  bucket_name text;
  unit_name text;

  -- expenses notes
  v_note_travel text;
  v_note_accom text;
  v_note_other text;

  -- recompute totals
  v_new_ex numeric := 0;
  v_new_vat numeric := 0;
  v_new_inc numeric := 0;

  -- header meta counters (keep header_snapshot_json.meta in sync with current invoice state)
  v_hdr_ts_count_lines int := 0;
  v_hdr_ts_count_seglocks int := 0;
  v_hdr_seg_locked_count int := 0;
  v_hdr_meta_timesheet_count int := 0;
  v_hdr_meta_segment_count int := 0;

  v_manifest jsonb;
  v_correction_placement_only boolean:=false;
  v_correction_placement_ts_id uuid:=null;
  v_correction_placement_scope jsonb:='{}'::jsonb;
  v_correction_placement_states jsonb:='[]'::jsonb;
  v_service boolean:=coalesce(auth.role(),'')='service_role';
  v_actor_role text;
begin

  if not v_service
     and(auth.uid() is null or auth.uid() is distinct from p_actor_user_id) then
    raise exception using errcode='42501',
      message='AUTHENTICATED_ACTOR_MISMATCH';
  end if;
  select lower(btrim(coalesce(u.role,''))) into v_actor_role
  from public.tms_users u
  where u.id=p_actor_user_id and u.is_active;
  if(not found or v_actor_role<>'admin') and not v_service then
    raise exception using errcode='42501',
      message='INVOICE_ADMINISTRATOR_PERMISSION_REQUIRED';
  end if;

  perform public._ctms_assert_invoice_mutable_draft_v1(
    p_invoice_id,'INVOICE_APPLY_EDITS',true
  );
  v_correction_placement_only:=
    jsonb_typeof(coalesce(p_payload,'{}'::jsonb))='object'
    and not exists(select 1 from jsonb_object_keys(coalesce(p_payload,'{}'::jsonb)) payload_key
      where payload_key not in ('remove_invoice_line_ids','add_timesheet_ids'))
    and coalesce(jsonb_array_length(case when jsonb_typeof(p_payload->'remove_invoice_line_ids')='array'
      then p_payload->'remove_invoice_line_ids' else '[]'::jsonb end),0)
      +coalesce(jsonb_array_length(case when jsonb_typeof(p_payload->'add_timesheet_ids')='array'
      then p_payload->'add_timesheet_ids' else '[]'::jsonb end),0)=1
    and (
      (case when coalesce(p_payload#>>'{remove_invoice_line_ids,0}','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then exists(
          select 1 from public.invoice_lines placement_line
          where placement_line.id=(p_payload#>>'{remove_invoice_line_ids,0}')::uuid
            and placement_line.invoice_id=p_invoice_id
            and coalesce((public._ctms_import_correction_classify_v1(placement_line.timesheet_id)
              ->>'is_import_authoritative_correction')::boolean,false)) else false end)
      or
      (case when coalesce(p_payload#>>'{add_timesheet_ids,0}','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        coalesce((public._ctms_import_correction_classify_v1(
          (p_payload#>>'{add_timesheet_ids,0}')::uuid)->>'is_import_authoritative_correction')::boolean,false)
        else false end)
    );
  if public._ctms_invoice_payload_has_financial_edit_v1(p_payload)
     and not v_correction_placement_only
     and exists (
       select 1 from public.invoice_lines il
       where il.invoice_id=p_invoice_id and il.timesheet_id is not null
         and coalesce((public._ctms_import_correction_classify_v1(il.timesheet_id)
           ->>'is_import_authoritative_correction')::boolean,false)
     ) then
    raise exception 'IMPORT_CORRECTION_INVOICE_FINANCIAL_EDIT_FORBIDDEN'
      using errcode='P0001',detail=jsonb_build_object('invoice_id',p_invoice_id)::text;
  end if;
-- Load invoice_debug flag (safe even if column not yet present)
begin
  select coalesce(sd.invoice_debug, false)
  into v_invoice_debug
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;
exception when undefined_column then
  v_invoice_debug := false;
end;

if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','start',
      'at_utc', public._inv_iso_utc(v_dbg_started_at),
      'invoice_id', p_invoice_id::text
    )
  );
end if;

  if p_invoice_id is null then
    raise exception 'invoice_id is required';
  end if;

  select *
  into v_inv
  from public.invoices i
  where i.id = p_invoice_id
  for update
  limit 1;

  if not found then
    raise exception 'Invoice not found';
  end if;

  -- Editable gate: DRAFT/ON_HOLD and unpaid
  if v_inv.status::text not in ('DRAFT','ON_HOLD') then
    raise exception 'Invoice is not editable (status=%)', v_inv.status::text;
  end if;

  if v_inv.paid_at_utc is not null then
    raise exception 'Invoice is not editable (already paid)';
  end if;



if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','invoice_loaded',
      'status', coalesce(v_inv.status::text,''),
      'paid_at_utc', case when v_inv.paid_at_utc is null then null else public._inv_iso_utc(v_inv.paid_at_utc) end
    )
  );
end if;

  -- Require invoice_week_start in header_snapshot_json.meta
  if v_inv.header_snapshot_json is null
     or btrim(coalesce(v_inv.header_snapshot_json #>> '{meta,invoice_week_start}','')) = ''
     or (v_inv.header_snapshot_json #>> '{meta,invoice_week_start}') !~ '^\d{4}-\d{2}-\d{2}$'
  then
    raise exception 'Invoice header_snapshot_json.meta.invoice_week_start is required for edits';
  end if;

  v_week_start := (v_inv.header_snapshot_json #>> '{meta,invoice_week_start}')::date;
  v_week_end := (v_week_start + interval '6 days')::date;


if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','invoice_week_loaded',
      'invoice_week_start', v_week_start::text,
      'invoice_week_end', v_week_end::text
    )
  );
end if;

  -- VAT settings from invoice snapshot
  if jsonb_typeof(v_inv.header_snapshot_json->'vat_chargeable') = 'boolean' then
    v_vat_chargeable := (v_inv.header_snapshot_json->>'vat_chargeable')::boolean;
  else
    v_vat_chargeable := true;
  end if;

  if (v_inv.header_snapshot_json ? 'applied_vat_rate_pct') then
    begin
      v_vat_rate := (v_inv.header_snapshot_json->>'applied_vat_rate_pct')::numeric;
    exception when others then
      v_vat_rate := 0;
    end;
  else
    v_vat_rate := 0;
  end if;

  if v_vat_chargeable = false then
    v_vat_rate := 0;
  end if;

  -- Parse payload arrays
  v_remove_ids := null;
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'remove_invoice_line_ids') then
    select array_agg((x)::uuid)
    into v_remove_ids
    from jsonb_array_elements_text(coalesce(p_payload->'remove_invoice_line_ids','[]'::jsonb)) x
    where nullif(btrim(coalesce(x,'')),'') is not null;
  end if;

  v_add_ts_ids := null;
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_timesheet_ids') then
    select array_agg((x)::uuid)
    into v_add_ts_ids
    from jsonb_array_elements_text(coalesce(p_payload->'add_timesheet_ids','[]'::jsonb)) x
    where nullif(btrim(coalesce(x,'')),'') is not null;
  end if;

  IF v_correction_placement_only THEN
    IF COALESCE(cardinality(v_remove_ids),0)=1 THEN
      SELECT il.timesheet_id INTO v_correction_placement_ts_id
      FROM public.invoice_lines il
      WHERE il.id=v_remove_ids[1] AND il.invoice_id=p_invoice_id
      FOR UPDATE;
      IF v_correction_placement_ts_id IS NULL
         OR COALESCE((public._ctms_import_correction_classify_v1(v_correction_placement_ts_id)
             ->>'is_import_authoritative_correction')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_TARGET_INVALID' USING ERRCODE='P0001';
      END IF;
      v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
        v_correction_placement_ts_id,null::uuid,p_actor_user_id,true,100);
      IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
         OR v_correction_placement_scope->>'placement_state' NOT IN (
           'COMPLETE_SAME_INVOICE','COMPLETE_SPLIT_INVOICES') THEN
        RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_MOVE_NOT_STARTABLE'
          USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
      END IF;
    ELSIF COALESCE(cardinality(v_add_ts_ids),0)=1 THEN
      v_correction_placement_ts_id:=v_add_ts_ids[1];
      IF COALESCE((public._ctms_import_correction_classify_v1(v_correction_placement_ts_id)
             ->>'is_import_authoritative_correction')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_TARGET_INVALID' USING ERRCODE='P0001';
      END IF;
      v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
        v_correction_placement_ts_id,p_invoice_id,p_actor_user_id,true,100);
      IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
         OR v_correction_placement_scope->>'placement_state'<>'INCOMPLETE_MOVE'
         OR v_correction_placement_scope->>'missing_member_kind' IS DISTINCT FROM
              (SELECT t.correction_kind FROM public.timesheets t
               WHERE t.timesheet_id=v_correction_placement_ts_id)
         OR COALESCE((v_correction_placement_scope->>'target_appendable')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_TARGET_INVALID'
          USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
      END IF;
    ELSE
      RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_PAYLOAD_INVALID' USING ERRCODE='22023';
    END IF;
  END IF;


-- Parse segment move payloads (tsfin_id + segment_id)
v_remove_seg_refs := null;
if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'remove_segment_refs') then
  v_remove_seg_refs := coalesce(p_payload->'remove_segment_refs','[]'::jsonb);
  if jsonb_typeof(v_remove_seg_refs) <> 'array' then
    v_remove_seg_refs := '[]'::jsonb;
  end if;
end if;

v_add_seg_refs := null;
if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_segment_refs') then
  v_add_seg_refs := coalesce(p_payload->'add_segment_refs','[]'::jsonb);
  if jsonb_typeof(v_add_seg_refs) <> 'array' then
    v_add_seg_refs := '[]'::jsonb;
  end if;
end if;



-- Parse and strictly validate source edits. The expected source revision is
-- mandatory because values displayed by an older modal must never overwrite a
-- newer timesheet revision.
v_reference_updates := null;
if p_payload is not null and jsonb_typeof(p_payload)='object'
   and p_payload ? 'reference_updates' then
  v_reference_updates:=p_payload->'reference_updates';
  if jsonb_typeof(v_reference_updates)<>'array' then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
      detail=jsonb_build_object('field','reference_updates','reason','ARRAY_REQUIRED')::text;
  end if;
  v_refupd_count:=jsonb_array_length(v_reference_updates);
  for v_refupd in select value from jsonb_array_elements(v_reference_updates) value loop
    if v_refupd is not null and jsonb_typeof(v_refupd)='object' then
      select min(field_name) into v_source_unsupported_field
      from jsonb_object_keys(v_refupd) field_name
      where not (field_name=any(v_allowed_reference_fields));
      if v_source_unsupported_field is not null then
        raise exception using errcode='22023',
          message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
          detail=jsonb_build_object(
            'field','reference_updates','reason','UNSUPPORTED_FIELD',
            'unsupported_field',v_source_unsupported_field)::text;
      end if;
    end if;
    if v_refupd is null or jsonb_typeof(v_refupd)<>'object'
       or nullif(btrim(coalesce(v_refupd->>'timesheet_id','')),'') is null
       or coalesce(v_refupd->>'timesheet_id','') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       or coalesce(v_refupd->>'expected_document_revision','') !~ '^[1-9][0-9]*$'
       or not (
         v_refupd ? 'reference_number'
         or v_refupd ? 'day_references_json'
         or v_refupd ? 'actual_schedule_json'
       )
       or (
         v_refupd ? 'reference_number'
         and jsonb_typeof(v_refupd->'reference_number') not in('string','null')
       )
       or (
         v_refupd ? 'day_references_json'
         and jsonb_typeof(v_refupd->'day_references_json') not in('object','null')
       )
       or (
         v_refupd ? 'actual_schedule_json'
         and jsonb_typeof(v_refupd->'actual_schedule_json') not in('array','null')
       )
    then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
        detail=jsonb_build_object('field','reference_updates','reason','INVALID_ITEM')::text;
    end if;
    v_source_edit_key:=lower(v_refupd->>'timesheet_id');
    if v_source_updates_map ? v_source_edit_key then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_DUPLICATE_TIMESHEET',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'field','reference_updates')::text;
    end if;
    v_source_updates_map:=jsonb_set(
      v_source_updates_map,array[v_source_edit_key],
      jsonb_build_object(
        'timesheet_id',v_source_edit_key,
        'expected_document_revision',(v_refupd->>'expected_document_revision')::bigint,
        'has_reference_number',v_refupd ? 'reference_number',
        'reference_number',case when v_refupd ? 'reference_number'
          then to_jsonb(nullif(btrim(coalesce(v_refupd->>'reference_number','')),''))
          else 'null'::jsonb end,
        'has_day_references_json',v_refupd ? 'day_references_json',
        'day_references_json',case
          when not (v_refupd ? 'day_references_json') then 'null'::jsonb
          when jsonb_typeof(v_refupd->'day_references_json')='null' then 'null'::jsonb
          else v_refupd->'day_references_json' end,
        'has_actual_schedule_json',v_refupd ? 'actual_schedule_json',
        'actual_schedule_json',case
          when not (v_refupd ? 'actual_schedule_json') then 'null'::jsonb
          when jsonb_typeof(v_refupd->'actual_schedule_json')='null' then 'null'::jsonb
          else v_refupd->'actual_schedule_json' end,
        'has_hospital_norm',false,
        'has_ward_norm',false),
      true);
  end loop;
end if;

-- Hospital/ward edits merge into the same desired source row. A source may
-- appear once in each array, but both items must carry the same revision.
v_location_updates:=null;
if p_payload is not null and jsonb_typeof(p_payload)='object'
   and p_payload ? 'timesheet_location_updates' then
  v_location_updates:=p_payload->'timesheet_location_updates';
  if jsonb_typeof(v_location_updates)<>'array' then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
      detail=jsonb_build_object('field','timesheet_location_updates','reason','ARRAY_REQUIRED')::text;
  end if;
  v_location_count:=jsonb_array_length(v_location_updates);
  for v_location_update in select value from jsonb_array_elements(v_location_updates) value loop
    if v_location_update is not null and jsonb_typeof(v_location_update)='object' then
      select min(field_name) into v_source_unsupported_field
      from jsonb_object_keys(v_location_update) field_name
      where not (field_name=any(v_allowed_location_fields));
      if v_source_unsupported_field is not null then
        raise exception using errcode='22023',
          message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
          detail=jsonb_build_object(
            'field','timesheet_location_updates','reason','UNSUPPORTED_FIELD',
            'unsupported_field',v_source_unsupported_field)::text;
      end if;
    end if;
    if v_location_update is null or jsonb_typeof(v_location_update)<>'object'
       or nullif(btrim(coalesce(v_location_update->>'timesheet_id','')),'') is null
       or coalesce(v_location_update->>'timesheet_id','') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       or coalesce(v_location_update->>'expected_document_revision','') !~ '^[1-9][0-9]*$'
       or not (v_location_update ? 'hospital_norm' or v_location_update ? 'ward_norm')
       or (
         v_location_update ? 'hospital_norm'
         and jsonb_typeof(v_location_update->'hospital_norm') not in('string','null')
       )
       or (
         v_location_update ? 'ward_norm'
         and jsonb_typeof(v_location_update->'ward_norm') not in('string','null')
       )
    then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
        detail=jsonb_build_object('field','timesheet_location_updates','reason','INVALID_ITEM')::text;
    end if;
    v_source_edit_key:=lower(v_location_update->>'timesheet_id');
    v_source_expected_revision:=(v_location_update->>'expected_document_revision')::bigint;
    if v_source_updates_map ? v_source_edit_key
       and (
         coalesce((v_source_updates_map#>>
           array[v_source_edit_key,'has_hospital_norm'])::boolean,false)
         or coalesce((v_source_updates_map#>>
           array[v_source_edit_key,'has_ward_norm'])::boolean,false)
       ) then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_DUPLICATE_TIMESHEET',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'field','timesheet_location_updates')::text;
    end if;
    if v_source_updates_map ? v_source_edit_key
       and (v_source_updates_map#>>array[v_source_edit_key,'expected_document_revision'])::bigint
           is distinct from v_source_expected_revision then
      raise exception using errcode='40001',
        message='INVOICE_SOURCE_EDIT_STALE_REVISION',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'reason','EXPECTED_REVISION_CONFLICT')::text;
    end if;
    v_source_update:=coalesce(v_source_updates_map->v_source_edit_key,
      jsonb_build_object(
        'timesheet_id',v_source_edit_key,
        'expected_document_revision',v_source_expected_revision,
        'has_reference_number',false,
        'has_day_references_json',false,
        'has_actual_schedule_json',false));
    v_source_update:=v_source_update||jsonb_build_object(
      'has_hospital_norm',v_location_update ? 'hospital_norm',
      'hospital_norm',case when v_location_update ? 'hospital_norm'
        then to_jsonb(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'hospital_norm','')),
          '[[:space:]]+',' ','g')))
        else 'null'::jsonb end,
      'has_ward_norm',v_location_update ? 'ward_norm',
      'ward_norm',case when v_location_update ? 'ward_norm'
        then to_jsonb(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'ward_norm','')),
          '[[:space:]]+',' ','g')))
        else 'null'::jsonb end);
    v_source_updates_map:=jsonb_set(v_source_updates_map,array[v_source_edit_key],v_source_update,true);
  end loop;
end if;
v_source_edit_requested:=v_source_updates_map<>'{}'::jsonb;
v_has_seg_ops :=
  (v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0)
  or (v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0);

  v_refresh_hr_cache := (coalesce(array_length(v_add_ts_ids,1),0) > 0) or coalesce(v_has_seg_ops,false);

  if v_invoice_debug then
    v_dbg_stats := v_dbg_stats || jsonb_build_object(
      'remove_invoice_line_ids_count', coalesce(array_length(v_remove_ids,1),0),
      'add_timesheet_ids_count', coalesce(array_length(v_add_ts_ids,1),0),
      'add_adjustments_count', case when p_payload is not null and jsonb_typeof(p_payload)='object' and (p_payload ? 'add_adjustments') and jsonb_typeof(p_payload->'add_adjustments')='array' then jsonb_array_length(p_payload->'add_adjustments') else 0 end,
      'remove_segment_refs_count', case when v_remove_seg_refs is null then 0 else jsonb_array_length(coalesce(v_remove_seg_refs,'[]'::jsonb)) end,
      'add_segment_refs_count', case when v_add_seg_refs is null then 0 else jsonb_array_length(coalesce(v_add_seg_refs,'[]'::jsonb)) end,
      'timesheet_location_updates_count',v_location_count,
      'has_segment_ops', v_has_seg_ops
    );
    v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','payload_parsed','stats',v_dbg_stats));
  end if;

  if v_source_edit_requested then
    -- Source edits are a narrower authority than ordinary draft edits.
    if v_inv.issued_at_utc is not null then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_ISSUED';
    end if;
    if v_inv.paid_at_utc is not null then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_PAID';
    end if;
    if v_inv.active_issue_operation_id is not null
       or upper(coalesce(v_inv.issue_state,'')) in
          ('VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
       or exists(
         select 1
         from public.invoice_operation_chunks c
         where c.chunk_type='ISSUE_INVOICE'
           and c.entity_type='INVOICE'
           and c.entity_id=p_invoice_id
           and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
       )
    then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_ISSUE_IN_PROGRESS';
    end if;

    v_pre_edit_invoice_revision:=v_inv.document_revision;
    v_pre_edit_preview_document_version_id:=v_inv.preview_document_version_id;
    v_pre_edit_active_document_operation_id:=v_inv.active_document_operation_id;

    -- Only an exact current-revision V8 preview is authoritative. Legacy PDF
    -- summary fields do not independently force or suppress replacement.
    select exists(
      select 1
      from public.invoice_document_versions dv
      left join public.invoice_operations op on op.id=dv.operation_id
      where dv.entity_type='INVOICE'
        and dv.entity_id=p_invoice_id
        and dv.purpose='DRAFT_PREVIEW'
        and dv.source_revision=v_pre_edit_invoice_revision::text
        and (
          (dv.status='READY'
            and nullif(btrim(coalesce(dv.r2_key,'')),'') is not null
            and nullif(btrim(coalesce(dv.sha256,'')),'') is not null
            and coalesce(dv.size_bytes,0)>0
            and coalesce(dv.page_count,0)>0)
          or (
            dv.id=v_pre_edit_preview_document_version_id
            and dv.status in(
              'PLANNING','WAITING_FOR_INPUTS','RENDERING',
              'ASSEMBLING','VERIFYING','READY'))
          or (
            dv.operation_id=v_pre_edit_active_document_operation_id
            and op.operation_type='BUILD_DOCUMENT'
            and op.entity_type='INVOICE'
            and op.entity_id=p_invoice_id
            and op.source_revision=v_pre_edit_invoice_revision::text
            and coalesce(op.input_json->>'purpose','')='DRAFT_PREVIEW'
            and op.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
        )
    ) into v_source_edit_preexisting_preview;

    -- Clear any caller-controlled or earlier transaction-local value before
    -- establishing this function's exact-once invalidation marker.
    perform set_config('cloudtms.invoice_source_edit_marker','{}',true);

    -- Lock every target and its current financial snapshot in deterministic
    -- order before validating ownership, revisions or segment identities.
    for v_ref_ts in
      select t.*
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired on true
      where t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      order by t.timesheet_id
      for update of t
    loop
      null;
    end loop;
    for v_ref_ts in
      select tf.id
      from public.timesheets_financials tf
      join jsonb_each(v_source_updates_map) desired
        on tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where tf.is_current
      order by tf.timesheet_id,tf.id
      for update of tf
    loop
      null;
    end loop;

    if (
      select count(*)
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where t.is_current
    )<>(select count(*) from jsonb_each(v_source_updates_map)) then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_SOURCE_NOT_CURRENT';
    end if;

    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      join public.timesheets t
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where t.document_revision is distinct from
        (desired.value->>'expected_document_revision')::bigint
    ) then
      raise exception using errcode='40001',
        message='INVOICE_SOURCE_EDIT_STALE_REVISION';
    end if;

    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where not exists(
        select 1
        from public.invoice_lines owned_line
        where owned_line.invoice_id=p_invoice_id
          and (
            owned_line.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              owned_line.timesheet_id is null
              and coalesce(owned_line.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (owned_line.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
    ) then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_SOURCE_NOT_OWNED';
    end if;

    -- Preserve the established import-authoritative correction lock across
    -- both supported source carriers.
    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where coalesce((
        public._ctms_import_correction_classify_v1(
          (desired.value->>'timesheet_id')::uuid)
          ->>'is_import_authoritative_correction')::boolean,false)
    ) then
      raise exception using errcode='55000',
        message='IMPORT_AUTHORITATIVE_CORRECTION_SOURCE_EDIT_FORBIDDEN';
    end if;

    -- Reject a mixed command that edits a source while removing every carrier
    -- for that source in the same Save.
    if coalesce(array_length(v_remove_ids,1),0)>0 and exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where exists(
        select 1
        from public.invoice_lines carrier
        where carrier.invoice_id=p_invoice_id
          and (
            carrier.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              carrier.timesheet_id is null
              and coalesce(carrier.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (carrier.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
      and not exists(
        select 1
        from public.invoice_lines retained
        where retained.invoice_id=p_invoice_id
          and not (retained.id=any(v_remove_ids))
          and (
            retained.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              retained.timesheet_id is null
              and coalesce(retained.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (retained.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
    ) then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND';
    end if;

    -- Classify each source from the locked current financial snapshot. A
    -- SEGMENTS payload is an editable reference projection only: it can never
    -- replace timesheets.actual_schedule_json or any financial segment object.
    for v_ref_ts in
      select t.*,desired.value desired_value,
        tf.id financial_id,tf.invoice_breakdown_json financial_breakdown
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      left join lateral(
        select f.id,f.invoice_breakdown_json
        from public.timesheets_financials f
        where f.timesheet_id=t.timesheet_id and f.is_current
        order by f.updated_at desc nulls last,f.created_at desc nulls last,f.id desc
        limit 1
      ) tf on true
      where t.is_current
      order by t.timesheet_id
    loop
      v_source_update:=v_ref_ts.desired_value;
      v_source_financial_id:=v_ref_ts.financial_id;
      v_source_ib:=v_ref_ts.financial_breakdown;
      v_source_mode:=upper(coalesce(v_source_ib->>'mode',''));
      v_source_payload_schedule:=v_source_update->'actual_schedule_json';
      v_source_canonical_schedule:=v_ref_ts.actual_schedule_json;
      v_source_new_segments:=null;
      v_source_segment_updates:='[]'::jsonb;
      v_source_segment_reference_changed:=false;

      if (v_source_update->>'has_actual_schedule_json')::boolean then
        if jsonb_typeof(v_source_payload_schedule)<>'array' then
          raise exception using errcode='22023',
            message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
            detail=jsonb_build_object(
              'field','actual_schedule_json','reason','ARRAY_REQUIRED',
              'timesheet_id',v_ref_ts.timesheet_id)::text;
        end if;

        if v_source_mode='SEGMENTS' then
          if v_source_financial_id is null
             or jsonb_typeof(v_source_ib->'segments')<>'array' then
            raise exception using errcode='55000',
              message='INVOICE_SOURCE_EDIT_SOURCE_NOT_CURRENT';
          end if;

          v_ref_seen_keys:='{}'::jsonb;
          for v_source_payload_segment,v_source_payload_ord in
            select value,ord
            from jsonb_array_elements(v_source_payload_schedule)
              with ordinality payload(value,ord)
          loop
            if jsonb_typeof(v_source_payload_segment)<>'object' then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','INVALID_SEGMENT',
                  'ordinal',v_source_payload_ord)::text;
            end if;
            select min(field_name) into v_source_unsupported_field
            from jsonb_object_keys(v_source_payload_segment) field_name
            where not (field_name=any(v_allowed_reference_segment_fields));
            if v_source_unsupported_field is not null then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','UNSUPPORTED_FIELD',
                  'unsupported_field',v_source_unsupported_field,
                  'ordinal',v_source_payload_ord)::text;
            end if;
            if not (v_source_payload_segment ? 'ref_num') then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','REFERENCE_REQUIRED',
                  'ordinal',v_source_payload_ord)::text;
            end if;

            v_ref_seg_id:=nullif(btrim(coalesce(
              v_source_payload_segment->>'segment_id','')),'');
            v_source_match_count:=0;
            v_source_match_segment:=null;
            if v_ref_seg_id is not null then
              select count(*),min(seg.value::text)::jsonb
              into v_source_match_count,v_source_match_segment
              from jsonb_array_elements(v_source_ib->'segments') seg(value)
              where nullif(btrim(coalesce(seg.value->>'segment_id','')),'')=v_ref_seg_id
                and nullif(btrim(coalesce(
                  seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text;
            end if;

            if v_source_match_count=0 then
              begin
                v_source_start:=nullif(btrim(coalesce(
                  v_source_payload_segment->>'start_utc',
                  v_source_payload_segment->>'start','')),'')::timestamptz;
                v_source_end:=nullif(btrim(coalesce(
                  v_source_payload_segment->>'end_utc',
                  v_source_payload_segment->>'end','')),'')::timestamptz;
              exception when others then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                  detail=jsonb_build_object(
                    'field','actual_schedule_json','reason','INVALID_SEGMENT_TIME',
                    'ordinal',v_source_payload_ord)::text;
              end;
              if v_source_start is null or v_source_end is null then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                  detail=jsonb_build_object(
                    'field','actual_schedule_json','reason','SEGMENT_IDENTITY_REQUIRED',
                    'ordinal',v_source_payload_ord)::text;
              end if;
              select count(*),min(seg.value::text)::jsonb
              into v_source_match_count,v_source_match_segment
              from jsonb_array_elements(v_source_ib->'segments') seg(value)
              where nullif(btrim(coalesce(
                    seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
                and nullif(btrim(coalesce(
                    seg.value->>'start_utc',seg.value->>'start','')),'')::timestamptz
                    =v_source_start
                and nullif(btrim(coalesce(
                    seg.value->>'end_utc',seg.value->>'end','')),'')::timestamptz
                    =v_source_end;
            end if;

            if v_source_match_count<>1 or v_source_match_segment is null then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts.timesheet_id,
                  'ordinal',v_source_payload_ord,
                  'match_count',v_source_match_count)::text;
            end if;

            v_ref_sched_key:=coalesce(
              'SID:'||nullif(btrim(coalesce(
                v_source_match_segment->>'segment_id','')),''),
              'SE:'||coalesce(v_source_match_segment->>'start_utc',
                v_source_match_segment->>'start','')||'|'||
                coalesce(v_source_match_segment->>'end_utc',
                  v_source_match_segment->>'end',''));
            if v_ref_seen_keys ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts.timesheet_id,
                  'reason','DUPLICATE_IDENTITY')::text;
            end if;
            v_ref_seen_keys:=jsonb_set(
              v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
            v_ref_seg_new_ref:=nullif(btrim(coalesce(
              v_source_payload_segment->>'ref_num','')),'');
            v_source_segment_reference_changed:=
              v_source_segment_reference_changed or (
                nullif(btrim(coalesce(
                  v_source_match_segment->>'ref_num','')),'')
                is distinct from v_ref_seg_new_ref);
            v_source_segment_updates:=v_source_segment_updates||
              jsonb_build_array(jsonb_build_object(
                'segment_id',nullif(btrim(coalesce(
                  v_source_match_segment->>'segment_id','')),''),
                'start_identity',coalesce(v_source_match_segment->>'start_utc',
                  v_source_match_segment->>'start'),
                'end_identity',coalesce(v_source_match_segment->>'end_utc',
                  v_source_match_segment->>'end'),
                'ref_num',v_ref_seg_new_ref));
          end loop;

          v_source_new_segments:='[]'::jsonb;
          for v_source_current_segment in
            select value
            from jsonb_array_elements(v_source_ib->'segments')
              with ordinality current_segment(value,ord)
            order by ord
          loop
            v_source_payload_segment:=null;
            select update_item.value into v_source_payload_segment
            from jsonb_array_elements(v_source_segment_updates) update_item(value)
            where (
              nullif(update_item.value->>'segment_id','') is not null
              and nullif(btrim(coalesce(
                v_source_current_segment->>'segment_id','')),'')
                  =nullif(update_item.value->>'segment_id','')
            ) or (
              nullif(update_item.value->>'segment_id','') is null
              and coalesce(v_source_current_segment->>'start_utc',
                    v_source_current_segment->>'start')
                  is not distinct from update_item.value->>'start_identity'
              and coalesce(v_source_current_segment->>'end_utc',
                    v_source_current_segment->>'end')
                  is not distinct from update_item.value->>'end_identity'
            )
            limit 1;
            if v_source_payload_segment is not null then
              v_source_current_segment:=jsonb_set(
                v_source_current_segment,'{ref_num}',
                coalesce(v_source_payload_segment->'ref_num','null'::jsonb),true);
            end if;
            v_source_new_segments:=v_source_new_segments||
              jsonb_build_array(v_source_current_segment);
          end loop;
        else
          v_source_canonical_schedule:=coalesce(
            v_ref_ts.actual_schedule_json,'[]'::jsonb);
          if jsonb_typeof(v_source_canonical_schedule)<>'array'
             or jsonb_array_length(v_source_payload_schedule)
                <>jsonb_array_length(v_source_canonical_schedule) then
            raise exception using errcode='22023',
              message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
              detail=jsonb_build_object(
                'field','actual_schedule_json','reason','STRUCTURE_MISMATCH',
                'timesheet_id',v_ref_ts.timesheet_id)::text;
          end if;
          v_ref_new_segments:='[]'::jsonb;
          for v_source_payload_segment,v_source_current_segment,v_source_payload_ord in
            select p.value,c.value,p.ord
            from jsonb_array_elements(v_source_payload_schedule)
              with ordinality p(value,ord)
            join jsonb_array_elements(v_source_canonical_schedule)
              with ordinality c(value,ord) using(ord)
            order by p.ord
          loop
            if jsonb_typeof(v_source_payload_segment)<>'object'
               or jsonb_typeof(v_source_current_segment)<>'object'
               or not (v_source_payload_segment ? 'ref_num')
               or (v_source_payload_segment-'ref_num') is distinct from
                  (v_source_current_segment-'ref_num') then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','STRUCTURE_MISMATCH',
                  'ordinal',v_source_payload_ord)::text;
            end if;
            v_ref_new_segments:=v_ref_new_segments||jsonb_build_array(
              jsonb_set(v_source_current_segment,'{ref_num}',
                coalesce(v_source_payload_segment->'ref_num','null'::jsonb),true));
          end loop;
          v_source_canonical_schedule:=v_ref_new_segments;
        end if;
      end if;

      v_source_timesheet_row_changed:=(
        ((v_source_update->>'has_reference_number')::boolean
          and v_ref_ts.reference_number is distinct from
            nullif(btrim(coalesce(v_source_update->>'reference_number','')),''))
        or ((v_source_update->>'has_day_references_json')::boolean
          and v_ref_ts.day_references_json is distinct from
            case when jsonb_typeof(v_source_update->'day_references_json')='null'
              then null else v_source_update->'day_references_json' end)
        or ((v_source_update->>'has_actual_schedule_json')::boolean
          and v_source_mode<>'SEGMENTS'
          and v_ref_ts.actual_schedule_json is distinct from
            v_source_canonical_schedule)
        or ((v_source_update->>'has_hospital_norm')::boolean
          and lower(regexp_replace(
                btrim(coalesce(v_ref_ts.hospital_norm,'')),
                '[[:space:]]+',' ','g')) is distinct from
            coalesce(v_source_update->>'hospital_norm',''))
        or ((v_source_update->>'has_ward_norm')::boolean
          and lower(regexp_replace(
                btrim(coalesce(v_ref_ts.ward_norm,'')),
                '[[:space:]]+',' ','g')) is distinct from
            coalesce(v_source_update->>'ward_norm',''))
      );
      v_source_update:=v_source_update||jsonb_build_object(
        'source_mode',v_source_mode,
        'financial_id',v_source_financial_id,
        'canonical_actual_schedule_json',v_source_canonical_schedule,
        'new_financial_segments',v_source_new_segments,
        'segment_updates',v_source_segment_updates,
        'segment_reference_changed',v_source_segment_reference_changed,
        'timesheet_row_changed',v_source_timesheet_row_changed);
      v_source_updates_map:=jsonb_set(
        v_source_updates_map,array[v_ref_ts.timesheet_id::text],
        v_source_update,true);
    end loop;

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_source_changed_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_row_changed')::boolean
       or (desired.value->>'segment_reference_changed')::boolean;

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_refupd_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_id')::uuid=any(v_source_changed_ts_ids)
      and (
        (desired.value->>'has_reference_number')::boolean
        or (desired.value->>'has_day_references_json')::boolean
        or (
          (desired.value->>'has_actual_schedule_json')::boolean
          and (
            (desired.value->>'timesheet_row_changed')::boolean
            or (desired.value->>'segment_reference_changed')::boolean
          )
        )
      );

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_location_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_row_changed')::boolean
      and (
        (desired.value->>'has_hospital_norm')::boolean
        or (desired.value->>'has_ward_norm')::boolean
      );

    if exists(
      select 1 from jsonb_each(v_source_updates_map) desired
      where (desired.value->>'timesheet_row_changed')::boolean
    ) then
      with desired as materialized(
        select (value->>'timesheet_id')::uuid as timesheet_id,value
        from jsonb_each(v_source_updates_map)
      )
      update public.timesheets t
      set updated_at=v_now,
          reference_number=case when (d.value->>'has_reference_number')::boolean
            then nullif(btrim(coalesce(d.value->>'reference_number','')),'')
            else t.reference_number end,
          day_references_json=case when (d.value->>'has_day_references_json')::boolean
            then case when jsonb_typeof(d.value->'day_references_json')='null'
              then null else d.value->'day_references_json' end
            else t.day_references_json end,
          actual_schedule_json=case
            when (d.value->>'has_actual_schedule_json')::boolean
              and d.value->>'source_mode'<>'SEGMENTS'
            then d.value->'canonical_actual_schedule_json'
            else t.actual_schedule_json end,
          hospital_norm=case when (d.value->>'has_hospital_norm')::boolean
            then coalesce(d.value->>'hospital_norm','') else t.hospital_norm end,
          ward_norm=case when (d.value->>'has_ward_norm')::boolean
            then coalesce(d.value->>'ward_norm','') else t.ward_norm end
      from desired d
      where t.timesheet_id=d.timesheet_id
        and (d.value->>'timesheet_row_changed')::boolean
        and t.is_current;
    end if;

    v_refupd_applied:=cardinality(v_refupd_ts_ids);
    v_location_applied:=cardinality(v_location_ts_ids);

    -- Marker rows exist only where the timesheet statement has already advanced
    -- the source revision and the following SEGMENTS ref update would otherwise
    -- invalidate the same source a second time.
    select coalesce(jsonb_object_agg(
      t.timesheet_id::text,
      jsonb_build_object('expected_revision',t.document_revision)),
      '{}'::jsonb)
    into v_source_marker_rows
    from jsonb_each(v_source_updates_map) desired
    join public.timesheets t
      on t.timesheet_id=(desired.value->>'timesheet_id')::uuid and t.is_current
    where (desired.value->>'timesheet_row_changed')::boolean
      and (desired.value->>'segment_reference_changed')::boolean
      and t.document_revision=
        (desired.value->>'expected_document_revision')::bigint+1;
    if (select count(*) from jsonb_each(v_source_marker_rows))<>(
      select count(*) from jsonb_each(v_source_updates_map) desired
      where (desired.value->>'timesheet_row_changed')::boolean
        and (desired.value->>'segment_reference_changed')::boolean
    ) then
      raise exception using errcode='55000',
        message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
        detail=jsonb_build_object(
          'reason','SOURCE_REVISION_ADVANCE_NOT_EXACT')::text;
    end if;
    v_source_marker:=jsonb_build_object(
      'txid',txid_current()::text,'rows',v_source_marker_rows);
    perform set_config(
      'cloudtms.invoice_source_edit_marker',v_source_marker::text,true);

    -- The legacy per-array loops below remain structurally compatible for old
    -- payload code, but the strict merged statement above is now the sole
    -- execution path for accepted source edits.
    v_reference_updates:=null;
    v_location_updates:=null;
  end if;





  -- 0) Apply reference updates to timesheets (does NOT recompute TSFIN; it updates the source timesheet refs)
  if v_reference_updates is not null and jsonb_typeof(v_reference_updates)='array' and jsonb_array_length(v_reference_updates) > 0 then
    for v_refupd in
      select value from jsonb_array_elements(v_reference_updates) value
    loop
      if v_refupd is null or jsonb_typeof(v_refupd) <> 'object' then
        continue;
      end if;

      if nullif(btrim(coalesce(v_refupd->>'timesheet_id','')), '') is null then
        continue;
      end if;

      v_refupd_ts_id := (v_refupd->>'timesheet_id')::uuid;

      v_refupd_set_refnum := (v_refupd ? 'reference_number');
      v_refupd_set_dayrefs := (v_refupd ? 'day_references_json');
      v_refupd_set_sched := (v_refupd ? 'actual_schedule_json');

      v_refupd_refnum := null;
      if v_refupd_set_refnum then
        v_refupd_refnum := nullif(btrim(coalesce(v_refupd->>'reference_number','')), '');
      end if;

      v_refupd_dayrefs := null;
      if v_refupd_set_dayrefs then
        v_refupd_dayrefs := v_refupd->'day_references_json';
        if v_refupd_dayrefs is not null and jsonb_typeof(v_refupd_dayrefs) = 'null' then
          v_refupd_dayrefs := null;
        end if;
      end if;

      v_refupd_sched := null;
      if v_refupd_set_sched then
        v_refupd_sched := v_refupd->'actual_schedule_json';
        if v_refupd_sched is not null and jsonb_typeof(v_refupd_sched) = 'null' then
          v_refupd_sched := null;
        end if;
      end if;

      update public.timesheets tsu
      set
        updated_at = v_now,
        reference_number = case when v_refupd_set_refnum then v_refupd_refnum else tsu.reference_number end,
        day_references_json = case when v_refupd_set_dayrefs then v_refupd_dayrefs else tsu.day_references_json end,
        actual_schedule_json = case when v_refupd_set_sched then v_refupd_sched else tsu.actual_schedule_json end
      where tsu.timesheet_id = v_refupd_ts_id
        and tsu.is_current = true
        and exists(
          select 1
          from public.invoice_lines owned_line
          where owned_line.invoice_id=p_invoice_id
            and (
              owned_line.timesheet_id=tsu.timesheet_id
              or (
                owned_line.timesheet_id is null
                and coalesce(owned_line.meta_json->>'timesheet_id','')
                  ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                and (owned_line.meta_json->>'timesheet_id')::uuid=tsu.timesheet_id
              )
            )
        )
        and (
          (v_refupd_set_refnum and tsu.reference_number is distinct from v_refupd_refnum)
          or (v_refupd_set_dayrefs and tsu.day_references_json is distinct from v_refupd_dayrefs)
          or (v_refupd_set_sched and tsu.actual_schedule_json is distinct from v_refupd_sched)
        );

      get diagnostics v_rc = row_count;
      if coalesce(v_rc,0) > 0 then
        v_refupd_applied := v_refupd_applied + 1;
        v_refupd_ts_ids := v_refupd_ts_ids || v_refupd_ts_id;
      end if;

    end loop;

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object('step','reference_updates_applied','count_requested',v_refupd_count,'count_applied',v_refupd_applied)
      );
    end if;
  end if;

  -- 0a) Apply only material hospital/ward changes to current timesheets that
  -- are owned by this invoice. Identical canonical values perform no UPDATE,
  -- so they cannot dirty documents or queue replacement work.
  if v_location_updates is not null
     and jsonb_typeof(v_location_updates)='array'
     and jsonb_array_length(v_location_updates)>0 then
    for v_location_update in
      select value from jsonb_array_elements(v_location_updates) value
    loop
      if v_location_update is null
         or jsonb_typeof(v_location_update)<>'object'
         or nullif(btrim(coalesce(v_location_update->>'timesheet_id','')),'') is null then
        continue;
      end if;

      v_location_ts_id := (v_location_update->>'timesheet_id')::uuid;
      v_location_set_hospital := v_location_update ? 'hospital_norm';
      v_location_set_ward := v_location_update ? 'ward_norm';
      if not v_location_set_hospital and not v_location_set_ward then
        continue;
      end if;

      v_location_hospital_norm := null;
      if v_location_set_hospital then
        v_location_hospital_norm := nullif(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'hospital_norm','')),
          '[[:space:]]+',' ','g')), '');
      end if;
      v_location_ward_norm := null;
      if v_location_set_ward then
        v_location_ward_norm := nullif(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'ward_norm','')),
          '[[:space:]]+',' ','g')), '');
      end if;

      update public.timesheets tsu
      set updated_at=v_now,
          hospital_norm=case when v_location_set_hospital
            then v_location_hospital_norm else tsu.hospital_norm end,
          ward_norm=case when v_location_set_ward
            then v_location_ward_norm else tsu.ward_norm end
      where tsu.timesheet_id=v_location_ts_id
        and tsu.is_current=true
        and exists(
          select 1
          from public.invoice_lines owned_line
          where owned_line.invoice_id=p_invoice_id
            and (
              owned_line.timesheet_id=tsu.timesheet_id
              or (
                owned_line.timesheet_id is null
                and coalesce(owned_line.meta_json->>'timesheet_id','')
                  ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                and (owned_line.meta_json->>'timesheet_id')::uuid=tsu.timesheet_id
              )
            )
        )
        and (
          (v_location_set_hospital
            and tsu.hospital_norm is distinct from v_location_hospital_norm)
          or (v_location_set_ward
            and tsu.ward_norm is distinct from v_location_ward_norm)
        );

      get diagnostics v_rc=row_count;
      if coalesce(v_rc,0)>0 then
        v_location_applied:=v_location_applied+1;
        v_location_ts_ids:=v_location_ts_ids||v_location_ts_id;
      end if;
    end loop;

    if v_invoice_debug then
      v_dbg_steps:=v_dbg_steps||jsonb_build_array(jsonb_build_object(
        'step','timesheet_location_updates_applied',
        'count_requested',v_location_count,
        'count_applied',v_location_applied));
    end if;
  end if;
  -- 0b) After reference updates: refresh invoice_lines meta (ts_reference_number / schedule_ref_nums) and
  -- synchronise only the approved ref_num fields into the locked SEGMENTS
  -- financial projection. The full financial objects and their order are
  -- preserved from the locked current snapshot.
  if v_refupd_ts_ids is not null and coalesce(array_length(v_refupd_ts_ids,1),0) > 0 then

    with desired as materialized(
      select value
      from jsonb_each(v_source_updates_map)
      where (value->>'segment_reference_changed')::boolean
    )
    update public.timesheets_financials tf
    set invoice_breakdown_json=jsonb_set(
      coalesce(tf.invoice_breakdown_json,'{}'::jsonb),
      '{segments}',d.value->'new_financial_segments',true)
    from desired d
    where tf.id=(d.value->>'financial_id')::uuid
      and tf.is_current
      and tf.timesheet_id=(d.value->>'timesheet_id')::uuid
      and upper(coalesce(tf.invoice_breakdown_json->>'mode',''))='SEGMENTS'
      and tf.invoice_breakdown_json->'segments'
        is distinct from d.value->'new_financial_segments';
    get diagnostics v_refupd_tsfin_rows_updated=row_count;
    select coalesce(sum(jsonb_array_length(
      coalesce(value->'segment_updates','[]'::jsonb))),0)::integer
    into v_refupd_tsfin_segments_updated
    from jsonb_each(v_source_updates_map)
    where (value->>'segment_reference_changed')::boolean;

    -- The marker has served its single synchronisation statement. Clear it so
    -- no later statement in this transaction can inherit suppression authority.
    perform set_config('cloudtms.invoice_source_edit_marker','{}',true);

    select array_agg(distinct x)
    into v_refupd_ts_ids_distinct
    from unnest(v_refupd_ts_ids) x
    where x is not null;

    v_refupd_ts_ids_distinct := coalesce(v_refupd_ts_ids_distinct, array[]::uuid[]);

    foreach v_ref_ts_id in array v_refupd_ts_ids_distinct loop
      if v_ref_ts_id is null then
        continue;
      end if;

      select tsu.*
      into v_ref_ts
      from public.timesheets tsu
      where tsu.timesheet_id = v_ref_ts_id
        and tsu.is_current = true
      limit 1;

      if not found then
        continue;
      end if;
      v_source_update:=v_source_updates_map->v_ref_ts_id::text;
      v_source_mode:=upper(coalesce(v_source_update->>'source_mode',''));
      v_source_canonical_schedule:=case when v_source_mode='SEGMENTS'
        then coalesce(v_source_update->'new_financial_segments','[]'::jsonb)
        else coalesce(v_ref_ts.actual_schedule_json,'[]'::jsonb) end;

      -- Build the cache from the exact authority used by this invoice. SEGMENTS
      -- refs come from invoice-owned financial segments; other modes use the
      -- structurally preserved timesheet schedule.
      v_ref_schedule_refs := '[]'::jsonb;

      if nullif(btrim(coalesce(v_ref_ts.reference_number,'')), '') is not null then
        v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(nullif(btrim(v_ref_ts.reference_number),'')));
      end if;

      if v_ref_ts.day_references_json is not null and jsonb_typeof(v_ref_ts.day_references_json) = 'object' then
        for kv in
          select key as k, value as v
          from jsonb_each_text(v_ref_ts.day_references_json)
        loop
          if nullif(btrim(coalesce(kv.v,'')), '') is not null then
            v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(nullif(btrim(kv.v),'')));
          end if;
        end loop;
      end if;

      if jsonb_typeof(v_source_canonical_schedule)='array' then
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_source_canonical_schedule) value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            continue;
          end if;
          v_ref_sched_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
          if v_ref_sched_ref is not null then
            v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(v_ref_sched_ref));
          end if;
        end loop;
      end if;

      select coalesce(jsonb_agg(to_jsonb(x) order by x), '[]'::jsonb)
      into v_ref_schedule_refs_distinct
      from (
        select distinct btrim(t.x) as x
        from jsonb_array_elements_text(coalesce(v_ref_schedule_refs,'[]'::jsonb)) as t(x)
        where nullif(btrim(coalesce(t.x,'')), '') is not null
      ) q;

      -- Refresh meta_json on all invoice lines for this timesheet
      update public.invoice_lines ilu
      set meta_json = coalesce(ilu.meta_json, '{}'::jsonb) || jsonb_build_object(
        'ts_reference_number', nullif(btrim(coalesce(v_ref_ts.reference_number,'')), ''),
        'schedule_ref_nums', coalesce(v_ref_schedule_refs_distinct, '[]'::jsonb),
        'schedule_ref_count', jsonb_array_length(coalesce(v_ref_schedule_refs_distinct, '[]'::jsonb))
      )
      where ilu.invoice_id = p_invoice_id
        and (
          ilu.timesheet_id=v_ref_ts_id
          or (
            ilu.timesheet_id is null
            and coalesce(ilu.meta_json->>'timesheet_id','') ~
              '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            and (ilu.meta_json->>'timesheet_id')::uuid=v_ref_ts_id
          )
        )
        and (
          ilu.meta_json->'ts_reference_number' is distinct from
            coalesce(to_jsonb(nullif(btrim(coalesce(v_ref_ts.reference_number,'')),'')),'null'::jsonb)
          or ilu.meta_json->'schedule_ref_nums' is distinct from
            coalesce(v_ref_schedule_refs_distinct,'[]'::jsonb)
          or ilu.meta_json->'schedule_ref_count' is distinct from
            to_jsonb(jsonb_array_length(coalesce(v_ref_schedule_refs_distinct,'[]'::jsonb)))
        );

      get diagnostics v_rc = row_count;
      v_refupd_meta_rows_updated := v_refupd_meta_rows_updated + coalesce(v_rc,0);

      -- Best-effort sync: update tsfin.invoice_breakdown_json segments[].ref_num by matching start/end fields
      v_ref_seg_updates_this_ts := 0;
      v_ref_seg_matches_this_ts := 0;
      v_ref_tsfin_id := null;
      v_ref_ib := null;

        select tfu.id, tfu.invoice_breakdown_json
      into v_ref_tsfin_id, v_ref_ib
      from public.timesheets_financials tfu
      where tfu.timesheet_id = v_ref_ts_id
        and tfu.is_current = true
      limit 1
      for update;


      if v_ref_tsfin_id is not null
         and v_source_mode<>'SEGMENTS'
         and v_ref_ib is not null
         and jsonb_typeof(v_ref_ib) = 'object'
         and upper(coalesce(v_ref_ib->>'mode','')) = 'SEGMENTS'
         and jsonb_typeof(v_ref_ib->'segments') = 'array'
         and v_ref_ts.actual_schedule_json is not null
         and jsonb_typeof(v_ref_ts.actual_schedule_json) = 'array'
       then
         -- Build a map of segment_id (preferred) or start|end -> ref_num from actual_schedule_json
        v_ref_sched_map := '{}'::jsonb;
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_ref_ts.actual_schedule_json) value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            continue;
          end if;

          v_ref_sched_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
          v_ref_seg_id := nullif(btrim(coalesce(v_ref_seg_obj->>'segment_id','')), '');
          if v_ref_seg_id is not null then
            v_ref_sched_key := 'SID:' || v_ref_seg_id;
            if v_ref_sched_map ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                  'side','TIMESHEET_SCHEDULE')::text;
            end if;
            v_ref_sched_map := jsonb_set(v_ref_sched_map, array[v_ref_sched_key], case when v_ref_sched_ref is null then 'null'::jsonb else to_jsonb(v_ref_sched_ref) end, true);
            continue;
          end if;

          v_ref_seg_start := nullif(btrim(coalesce(v_ref_seg_obj->>'start_utc', v_ref_seg_obj->>'start', '')), '');
          v_ref_seg_end := nullif(btrim(coalesce(v_ref_seg_obj->>'end_utc', v_ref_seg_obj->>'end', '')), '');
          if v_ref_seg_start is null or v_ref_seg_end is null then
            continue;
          end if;

          v_ref_sched_key := 'SE:' || v_ref_seg_start || '|' || v_ref_seg_end;
          if v_ref_sched_map ? v_ref_sched_key then
            raise exception using errcode='22023',
              message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
              detail=jsonb_build_object(
                'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                'side','TIMESHEET_SCHEDULE')::text;
          end if;
          v_ref_sched_map := jsonb_set(v_ref_sched_map, array[v_ref_sched_key], case when v_ref_sched_ref is null then 'null'::jsonb else to_jsonb(v_ref_sched_ref) end, true);
        end loop;

        v_ref_new_segments := '[]'::jsonb;
        v_ref_seen_keys := '{}'::jsonb;
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_ref_ib->'segments') value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            v_ref_new_segments := v_ref_new_segments || jsonb_build_array(v_ref_seg_obj);
            continue;
          end if;

          v_ref_seg_new_ref := null;
          v_ref_seg_has_update := false;

          v_ref_seg_id := nullif(btrim(coalesce(v_ref_seg_obj->>'segment_id','')), '');
          if v_ref_seg_id is not null then
            v_ref_sched_key := 'SID:' || v_ref_seg_id;
            if v_ref_seen_keys ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                  'side','FINANCIAL_SEGMENTS')::text;
            end if;
            v_ref_seen_keys:=jsonb_set(v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
            if v_ref_sched_map ? v_ref_sched_key then
              v_ref_seg_new_ref := nullif(btrim(coalesce(v_ref_sched_map->>v_ref_sched_key,'')), '');
              v_ref_seg_has_update := true;
              v_ref_seg_matches_this_ts := v_ref_seg_matches_this_ts + 1;
            end if;
          end if;

          if not v_ref_seg_has_update then
            v_ref_seg_start := nullif(btrim(coalesce(v_ref_seg_obj->>'start_utc', v_ref_seg_obj->>'start', '')), '');
            v_ref_seg_end := nullif(btrim(coalesce(v_ref_seg_obj->>'end_utc', v_ref_seg_obj->>'end', '')), '');

            if v_ref_seg_start is not null and v_ref_seg_end is not null then
              v_ref_sched_key := 'SE:' || v_ref_seg_start || '|' || v_ref_seg_end;
              if v_ref_seen_keys ? v_ref_sched_key then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                  detail=jsonb_build_object(
                    'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                    'side','FINANCIAL_SEGMENTS')::text;
              end if;
              v_ref_seen_keys:=jsonb_set(v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
              if v_ref_sched_map ? v_ref_sched_key then
                v_ref_seg_new_ref := nullif(btrim(coalesce(v_ref_sched_map->>v_ref_sched_key,'')), '');
                v_ref_seg_has_update := true;
                v_ref_seg_matches_this_ts := v_ref_seg_matches_this_ts + 1;
              end if;
            end if;
          end if;

          if v_ref_seg_has_update then
            v_ref_seg_cur_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
            if v_ref_seg_cur_ref is distinct from v_ref_seg_new_ref then
              v_ref_seg_obj := jsonb_set(
                v_ref_seg_obj,
                '{ref_num}',
                case when v_ref_seg_new_ref is null then 'null'::jsonb else to_jsonb(v_ref_seg_new_ref) end,
                true
              );
              v_ref_seg_updates_this_ts := v_ref_seg_updates_this_ts + 1;
            end if;
          end if;

          v_ref_new_segments := v_ref_new_segments || jsonb_build_array(v_ref_seg_obj);
        end loop;



        if v_ref_sched_map is not null
           and jsonb_typeof(v_ref_sched_map) = 'object'
           and v_ref_sched_map <> '{}'::jsonb
           and coalesce(jsonb_array_length(coalesce(v_ref_ib->'segments','[]'::jsonb)),0) > 0
           and coalesce(v_ref_seg_matches_this_ts,0) = 0
        then
          raise exception 'SEGMENTS reference sync failed: no segments matched schedule keys (timesheet_id=% tsfin_id=%)', v_ref_ts_id, v_ref_tsfin_id;
        end if;

        if v_ref_seg_updates_this_ts > 0 then
              update public.timesheets_financials tfu2
          set invoice_breakdown_json = jsonb_set(coalesce(tfu2.invoice_breakdown_json, '{}'::jsonb), '{segments}', v_ref_new_segments, true)
          where tfu2.id = v_ref_tsfin_id
            and tfu2.is_current = true;


          get diagnostics v_rc = row_count;
          if coalesce(v_rc,0) > 0 then
            v_refupd_tsfin_rows_updated := v_refupd_tsfin_rows_updated + 1;
            v_refupd_tsfin_segments_updated := v_refupd_tsfin_segments_updated + v_ref_seg_updates_this_ts;
          end if;
        end if;

      end if;

    end loop;

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','reference_updates_meta_refreshed',
          'timesheets_count', coalesce(array_length(v_refupd_ts_ids_distinct,1),0),
          'invoice_line_rows_updated', v_refupd_meta_rows_updated,
          'tsfin_rows_updated', v_refupd_tsfin_rows_updated,
          'tsfin_segments_refnum_updated', v_refupd_tsfin_segments_updated
        )
      );
    end if;
  end if;

  -- 1) Removals (by invoice_line_id)
  if v_remove_ids is not null and coalesce(array_length(v_remove_ids,1),0) > 0 then
    -- collect timesheet_ids touched (any)
    select array_agg(distinct l.timesheet_id) filter (where l.timesheet_id is not null)
    into v_ts_ids_touched
    from public.invoice_lines l
    where l.invoice_id = p_invoice_id
      and l.id = any(v_remove_ids);

    -- record removed lines for history
    v_hist_lines_removed := coalesce(p_payload->'remove_invoice_line_ids','[]'::jsonb);

    -- Only unlock TSFIN when HOURS lines were removed (prevents accidental unlock when deleting only expenses/other lines)
    -- IMPORTANT: compute BEFORE deletion because we match on the removed invoice_line ids.
    select array_agg(distinct l.timesheet_id) filter (where l.timesheet_id is not null)
    into v_cw_ts_ids
    from public.invoice_lines l
    where l.invoice_id = p_invoice_id
      and l.id = any(v_remove_ids)
      and upper(coalesce(l.meta_json->>'line_type','')) in ('HOURS_WEEKLY','HOURS_DAILY');

    v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);



    if coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
      v_refresh_hr_cache := true;
    end if;
delete from public.invoice_lines
    where invoice_id = p_invoice_id
      and id = any(v_remove_ids);
    get diagnostics v_rc = row_count;
    v_dbg_lines_deleted := v_dbg_lines_deleted + coalesce(v_rc,0);

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','lines_removed',
          'rows_deleted', coalesce(v_rc,0),
          'timesheets_touched', coalesce(array_length(v_ts_ids_touched,1),0),
          'timesheets_to_unlock_count', coalesce(array_length(v_cw_ts_ids,1),0)
        )
      );
    end if;

    -- FIX: if a touched timesheet now has NO remaining invoice_lines on this invoice,
    -- unlock it even if the removed lines were expenses/mileage/additional (expense-only/SEGMENTS-empty case).
    v_ts_ids_fully_removed := array[]::uuid[];
    select array_agg(distinct x)
    into v_ts_ids_fully_removed
    from unnest(coalesce(v_ts_ids_touched, array[]::uuid[])) x
    where x is not null
      and not exists (
        select 1
        from public.invoice_lines l2
        where l2.invoice_id = p_invoice_id
          and l2.timesheet_id = x
      );

    v_ts_ids_fully_removed := coalesce(v_ts_ids_fully_removed, array[]::uuid[]);

    if coalesce(array_length(v_ts_ids_fully_removed,1),0) > 0 then
      -- unlock any segments locked to this invoice (safe no-op for SEGMENTS-empty)
      perform public._inv_unlock_segments_for_invoice(p_invoice_id, v_ts_ids_fully_removed);

      -- clear whole-timesheet lock if it was set for this invoice (SEGMENTS-empty / non-segments / pseudo segment_id null locks)
      update public.timesheets_financials tfu_lock
      set
        locked_by_invoice_id = null,
        locked_at_utc = null,
        updated_at = v_now
      where tfu_lock.is_current = true
        and tfu_lock.timesheet_id = any(v_ts_ids_fully_removed)
        and tfu_lock.locked_by_invoice_id = p_invoice_id;

      get diagnostics v_rc = row_count;
      v_dbg_timesheets_unlocked := v_dbg_timesheets_unlocked + coalesce(v_rc,0);

      v_refresh_hr_cache := true;

      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(
          jsonb_build_object(
            'step','timesheets_unlocked_after_full_removal',
            'timesheets_fully_removed_count', coalesce(array_length(v_ts_ids_fully_removed,1),0),
            'tsfin_rows_unlocked_count', coalesce(v_rc,0)
          )
        );
      end if;
    end if;

    v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);

    if v_cw_ts_ids is not null and coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
      perform public._inv_unlock_segments_for_invoice(p_invoice_id, v_cw_ts_ids);
      v_dbg_timesheets_unlocked := v_dbg_timesheets_unlocked + coalesce(array_length(v_cw_ts_ids,1),0);

      -- Cleanup: if no segments remain on THIS invoice for a touched timesheet, remove ALL remaining invoice lines for that timesheet
      foreach tsid in array v_cw_ts_ids loop
        if tsid is null then continue; end if;

        -- detect if any segments are still locked to THIS invoice
        select tf.*
        into snap
        from public.timesheets_financials tf
        where tf.is_current = true
          and tf.timesheet_id = tsid
        limit 1;

        if not found then
          continue;
        end if;

        segments := '[]'::jsonb;
        if snap.invoice_breakdown_json is not null
           and jsonb_typeof(snap.invoice_breakdown_json)='object'
           and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
           and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
        then
          for v_seg in
            select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
          loop
            if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
              continue;
            end if;
            seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
            if seg_locked = p_invoice_id::text then
              segments := segments || jsonb_build_array(v_seg);
            end if;
          end loop;

          if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
            delete from public.invoice_lines
            where invoice_id = p_invoice_id
              and timesheet_id = tsid;
          end if;
        else
          -- Non-segments: if snapshot is no longer locked to this invoice, remove all remaining invoice lines for this timesheet
          if snap.locked_by_invoice_id is null then
            delete from public.invoice_lines
            where invoice_id = p_invoice_id
              and timesheet_id = tsid;
          end if;
        end if;
      end loop;
    end if;

    -- History event (always)
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_LINES_REMOVED',
      null,
      jsonb_build_object('remove_invoice_line_ids', v_hist_lines_removed, 'timesheet_ids_touched', coalesce(to_jsonb(v_ts_ids_touched), '[]'::jsonb)),
      null,
      p_actor_user_id
    );

  end if;


  -- 1b) Segment edits (SEGMENTS mode only)
-- NOTE: Segment moves are NOT allowed when additional rates OR expenses/mileage exist on the TSFIN snapshot.
-- Payload contract uses tsfin_id + segment_id.
if v_has_seg_ops then

  v_dbg_seg_add_refs := case when v_add_seg_refs is null then 0 else jsonb_array_length(coalesce(v_add_seg_refs,'[]'::jsonb)) end;
  v_dbg_seg_remove_refs := case when v_remove_seg_refs is null then 0 else jsonb_array_length(coalesce(v_remove_seg_refs,'[]'::jsonb)) end;

  if v_invoice_debug then
    v_dbg_steps := v_dbg_steps || jsonb_build_array(
      jsonb_build_object(
        'step','segment_ops_start',
        'add_segment_refs_count', v_dbg_seg_add_refs,
        'remove_segment_refs_count', v_dbg_seg_remove_refs
      )
    );
  end if;

  -- Collect distinct tsfin_ids involved in segment ops
  select array_agg(distinct (x->>'tsfin_id')::uuid)
  into v_seg_tsfin_ids
  from (
    select value as x
    from jsonb_array_elements(coalesce(v_remove_seg_refs,'[]'::jsonb))
    union all
    select value as x
    from jsonb_array_elements(coalesce(v_add_seg_refs,'[]'::jsonb))
  ) u
  where jsonb_typeof(x) = 'object'
    and nullif(btrim(coalesce(x->>'tsfin_id','')), '') is not null;

  v_seg_tsfin_ids := coalesce(v_seg_tsfin_ids, array[]::uuid[]);

  v_dbg_seg_tsfins := coalesce(array_length(v_seg_tsfin_ids,1),0);
  if v_invoice_debug then
    v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','segment_ops_targets','tsfin_count',v_dbg_seg_tsfins));
  end if;

  if coalesce(array_length(v_seg_tsfin_ids,1),0) > 0 then

    -- Validate that each snapshot is current SEGMENTS mode and has NO additional/expenses/mileage
    foreach v_tsfin_id in array v_seg_tsfin_ids loop
      select *
      into snap
      from public.timesheets_financials tf
      where tf.id = v_tsfin_id
      limit 1;

      if not found then
        raise exception 'Segment edit refers to unknown tsfin_id %', v_tsfin_id;
      end if;

      if snap.is_current is not true then
        raise exception 'Segment edit requires current tsfin snapshot (tsfin_id=%)', v_tsfin_id;
      end if;

      if snap.client_id is distinct from v_inv.client_id then
        raise exception 'Segment edit timesheet client mismatch (tsfin_id=%)', v_tsfin_id;
      end if;

      if snap.invoice_breakdown_json is null
         or jsonb_typeof(snap.invoice_breakdown_json) <> 'object'
         or upper(coalesce(snap.invoice_breakdown_json->>'mode','')) <> 'SEGMENTS'
         or jsonb_typeof(snap.invoice_breakdown_json->'segments') <> 'array'
      then
        raise exception 'Segment edit is only supported for SEGMENTS timesheets (tsfin_id=%)', v_tsfin_id;
      end if;

      v_has_additional :=
        public._inv_round2(coalesce(snap.additional_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.additional_charge_ex_vat,0)) <> 0
        or (snap.additional_units_json is not null and jsonb_typeof(snap.additional_units_json)='object' and snap.additional_units_json <> '{}'::jsonb);

      v_has_expense_or_mileage :=
        public._inv_round2(coalesce(snap.expenses_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.expenses_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_units,0)) <> 0
        or public._inv_round2(coalesce(snap.travel_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.travel_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.accommodation_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.accommodation_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.other_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.other_charge_ex_vat,0)) <> 0;

      if v_has_additional then
        raise exception 'Segments cannot be moved when additional rates exist (timesheet_id=% tsfin_id=%)', snap.timesheet_id, v_tsfin_id;
      end if;

      if v_has_expense_or_mileage then
        raise exception 'Segments cannot be moved when expenses or mileage exist (timesheet_id=% tsfin_id=%)', snap.timesheet_id, v_tsfin_id;
      end if;
    end loop;

    -- Validate and apply add_segment_refs (lock selected segments)
    v_seg_refs_to_lock := '[]'::jsonb;
    if v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0 then
      for v_ref in
        select value from jsonb_array_elements(v_add_seg_refs) value
      loop
        if v_ref is null or jsonb_typeof(v_ref) <> 'object' then
          continue;
        end if;

        if nullif(btrim(coalesce(v_ref->>'tsfin_id','')), '') is null then
          continue;
        end if;

        v_tsfin_id := (v_ref->>'tsfin_id')::uuid;
        v_seg_id := nullif(btrim(coalesce(v_ref->>'segment_id','')), '');

        if v_seg_id is null then
          raise exception 'add_segment_refs requires segment_id (tsfin_id=%)', v_tsfin_id;
        end if;

          -- Load snapshot + timesheet + precheck (must be OK)
        select
          tf.*,
          tsr.sheet_scope::text as sheet_scope,
          coalesce(tsr.submission_mode::text,'') as submission_mode,
          tsr.day_references_json,
          tsr.actual_schedule_json,
          tsr.week_ending_date,
          cw.contract_id
        into snap
        from public.timesheets_financials tf
        join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
        left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
        join public.v_ts_invoice_precheck pcv on pcv.timesheet_id = tf.timesheet_id
        where tf.id = v_tsfin_id
          and tf.is_current = true
          and tf.client_id = v_inv.client_id
          and upper(coalesce(pcv.precheck_status,''))
            in ('OK','BLOCK_NO_PDF')
        limit 1;

        if not found then
          raise exception 'Segment add failed eligibility (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        natural_start := (snap.week_ending_date::date - 6);

        -- Locate the segment object
        v_seg := null;
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;
          if nullif(btrim(coalesce(v_seg->>'segment_id','')), '') = v_seg_id then
            exit;
          end if;
          v_seg := null;
        end loop;

        if v_seg is null then
          raise exception 'Segment not found (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
        if seg_locked is not null then
          raise exception 'Segment already invoiced (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        seg_target := nullif(btrim(coalesce(v_seg->>'invoice_target_week_start','')), '')::date;
        seg_ref := btrim(coalesce(v_seg->>'ref_num',''));

        -- segment-level ref gating if required
        select * into pc from public.v_ts_invoice_precheck where timesheet_id = snap.timesheet_id limit 1;
        if pc.require_reference_to_invoice is true and seg_ref = '' then
          raise exception 'Segment missing reference number (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
        end if;

        -- Week eligibility
        if seg_target is null or seg_target = natural_start then
          if v_week_start <> natural_start then
            raise exception 'Segment not eligible for this invoice week (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
        else
          if v_week_start <> seg_target then
            raise exception 'Delayed segment not eligible for this invoice week (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
          if seg_target > v_anchor_ymd then
            raise exception 'Delayed segment cannot be invoiced early (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
        end if;

        v_seg_refs_to_lock := v_seg_refs_to_lock || jsonb_build_array(
          jsonb_build_object(
            'tsfin_id', v_tsfin_id::text,
            'segment_id', v_seg_id
          )
        );
      end loop;

      if jsonb_typeof(v_seg_refs_to_lock) = 'array' and jsonb_array_length(v_seg_refs_to_lock) > 0 then
        perform public._inv_lock_segments_for_invoice(p_invoice_id, v_seg_refs_to_lock);
      end if;
    end if;

      -- Apply remove_segment_refs (unlock selected segments on THIS invoice)
    if v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0 then
      perform public._inv_unlock_segment_refs_for_invoice(p_invoice_id, v_remove_seg_refs::jsonb, p_actor_user_id);
    end if;



    -- History: segment ops (always)
    if v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0 then
      perform public._audit_insert(
        'invoices',
        p_invoice_id::text,
        'INVOICE_SEGMENTS_ADDED',
        null,
        jsonb_build_object('add_segment_refs', v_add_seg_refs),
        null,
        p_actor_user_id
      );
    end if;
    if v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0 then
      perform public._audit_insert(
        'invoices',
        p_invoice_id::text,
        'INVOICE_SEGMENTS_REMOVED',
        null,
        jsonb_build_object('remove_segment_refs', v_remove_seg_refs),
        null,
        p_actor_user_id
      );
    end if;

    -- Rebuild HOURS lines for touched timesheets on this invoice
    select array_agg(distinct tf.timesheet_id)
    into v_seg_ts_ids
    from public.timesheets_financials tf
    where tf.id = any(v_seg_tsfin_ids);

    v_seg_ts_ids := coalesce(v_seg_ts_ids, array[]::uuid[]);

    foreach tsid in array v_seg_ts_ids loop
      if tsid is null then
        continue;
      end if;

      -- Load snapshot + timesheet + contract (no READY_FOR_INVOICE restriction; this is an invoice edit)
      select
        tf.*,
        tsr.booking_id,
        tsr.week_ending_date,
        tsr.reference_number,
        tsr.sheet_scope::text as sheet_scope,
        coalesce(tsr.submission_mode::text,'') as submission_mode,
        tsr.day_references_json,
        tsr.actual_schedule_json,
        cw.contract_id
      into snap
      from public.timesheets_financials tf
      join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
      left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
      where tf.timesheet_id = tsid
        and tf.is_current = true
      limit 1;

      if not found then
        v_dbg_add_timesheets_skipped := v_dbg_add_timesheets_skipped + 1;
        if v_invoice_debug then
          v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_skipped','timesheet_id',tsid::text));
        end if;
        continue;
      end if;

      v_dbg_add_timesheets_found := v_dbg_add_timesheets_found + 1;
      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_loaded','timesheet_id',tsid::text,'tsfin_id',snap.id::text));
      end if;

      select v.r2_key
      into v_exact_timesheet_document_r2_key
      from public.timesheets t
      join public.invoice_document_versions v
        on v.entity_type='TIMESHEET'
       and v.entity_id=t.timesheet_id
       and v.purpose='TIMESHEET'
       and v.source_revision=t.document_revision::text
       and v.status='READY'
       and nullif(v.r2_key,'') is not null
       and nullif(v.sha256,'') is not null
       and coalesce(v.size_bytes,0)>0
       and coalesce(v.page_count,0)>0
      where t.timesheet_id=tsid and t.is_current
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1;


      contract_id := snap.contract_id;
      c_daily_calc := false;
      c_bucket_labels := null;
      c_display_site := null;

      if contract_id is not null then
        select
          nullif(btrim(coalesce(display_site,'')), '')
        into
          c_display_site
        from public.contracts
        where id = contract_id
        limit 1;
      end if;

      v_settings_authority := private._timesheet_settings_authority_frozen_v1(tsid);
      c_daily_calc := coalesce(
        (v_settings_authority#>>'{values,daily_calc_of_invoices}')::boolean,
        false
      );
      c_bucket_labels := case
        when coalesce((v_settings_authority->>'override_client_settings')::boolean,false)
          then v_settings_authority#>'{values,bucket_labels_json}'
        else null
      end;

      if c_bucket_labels is null then
        c_bucket_labels := jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH');
      end if;

      -- Build segment set locked to THIS invoice
      segments := '[]'::jsonb;
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
         and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
      then
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
          if seg_locked = p_invoice_id::text then
            segments := segments || jsonb_build_array(v_seg);
          end if;
        end loop;
      end if;

      if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
        -- If no segments remain on this invoice for this timesheet, remove ALL invoice lines for that timesheet
        delete from public.invoice_lines
        where invoice_id = p_invoice_id
          and timesheet_id = tsid;
        v_dbg_seg_timesheets_removed := v_dbg_seg_timesheets_removed + 1;
        continue;
      end if;

      v_dbg_seg_timesheets_rebuilt := v_dbg_seg_timesheets_rebuilt + 1;

      -- Replace HOURS lines for this timesheet on this invoice
      delete from public.invoice_lines
      where invoice_id = p_invoice_id
        and timesheet_id = tsid
        and upper(coalesce(meta_json->>'line_type','')) in ('HOURS_WEEKLY','HOURS_DAILY');
        -- HOURS lines
        if c_daily_calc then
          -- Daily: group by segment.date
          for r_day in
            with rows as (
              select
                nullif(btrim(coalesce(seg_el->>'date','')), '') as ymd,
                coalesce((seg_el->>'hours_day')::numeric,0)   as h_day,
                coalesce((seg_el->>'hours_night')::numeric,0) as h_night,
                coalesce((seg_el->>'hours_sat')::numeric,0)   as h_sat,
                coalesce((seg_el->>'hours_sun')::numeric,0)   as h_sun,
                coalesce((seg_el->>'hours_bh')::numeric,0)    as h_bh,
                coalesce((seg_el->>'pay_amount')::numeric,0)  as pay_ex,
                coalesce((seg_el->>'charge_amount')::numeric,0) as chg_ex
              from jsonb_array_elements(segments) seg_el
            ),
            agg as (
              select
                ymd,
                sum(rows.h_day)::numeric as hours_day,
                sum(rows.h_night)::numeric as hours_night,
                sum(rows.h_sat)::numeric as hours_sat,
                sum(rows.h_sun)::numeric as hours_sun,
                sum(rows.h_bh)::numeric as hours_bh,
                sum(rows.pay_ex)::numeric as pay_ex,
                sum(rows.chg_ex)::numeric as chg_ex
              from rows
              where ymd is not null and ymd ~ '^\d{4}-\d{2}-\d{2}$'
              group by ymd
            )
            select * from agg order by ymd
          loop
          chg_ex := public._inv_round2(r_day.chg_ex);
if chg_ex = 0 then continue; end if;

if (coalesce(r_day.hours_day,0)+coalesce(r_day.hours_night,0)+coalesce(r_day.hours_sat,0)+coalesce(r_day.hours_sun,0)+coalesce(r_day.hours_bh,0)) = 0 then
  continue;
end if;


            pay_ex := public._inv_round2(r_day.pay_ex);
            margin_ex := public._inv_round2(chg_ex - pay_ex);
            vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
            inc_amt := public._inv_round2(chg_ex + vat_amt);

            line_desc := coalesce(nullif(btrim(coalesce(c_display_site,'')) ,''), ('TS '||tsid::text)) ||
                         ' – '|| r_day.ymd || ' – W/E '|| coalesce(snap.week_ending_date::text,'');

            v_meta := jsonb_build_object(
              'line_type','HOURS_DAILY',
              'timesheet_id', tsid::text,
              'tsfin_id', snap.id::text,
              'candidate_display', coalesce(nullif(btrim(coalesce(c_display_site,'')),''), null),
              'role', c_role,
              'hospital', c_display_site,
              'ward', c_ward_hint,
              'week_ending_date', snap.week_ending_date::text,
              'date', r_day.ymd,
              'bucket_labels', c_bucket_labels
            );

            v_source_key := 'TS:' || tsid::text || ':HOURS:' || r_day.ymd;

            insert into public.invoice_lines(
              invoice_id, timesheet_id, booking_id, description,
              hours_day, hours_night, hours_sat, hours_sun, hours_bh,
              pay_day, pay_night, pay_sat, pay_sun, pay_bh,
              charge_day, charge_night, charge_sat, charge_sun, charge_bh,
              total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
              vat_rate_pct, vat_amount, total_inc_vat,
              paper_ts_r2_key, meta_json, source_key
            )
            values (
              p_invoice_id, tsid, snap.booking_id, line_desc,
              public._inv_round2(r_day.hours_day), public._inv_round2(r_day.hours_night), public._inv_round2(r_day.hours_sat), public._inv_round2(r_day.hours_sun), public._inv_round2(r_day.hours_bh),
              null,null,null,null,null,
              null,null,null,null,null,
              pay_ex, chg_ex, margin_ex,
              v_vat_rate, vat_amt, inc_amt,
              v_exact_timesheet_document_r2_key,
              v_meta,
              v_source_key
            )
            on conflict (invoice_id, source_key) do nothing;
          end loop;
        else
          -- Weekly hours line
          select
            public._inv_round2(coalesce(sum((seg_el->>'hours_day')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_night')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_sat')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_sun')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_bh')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'pay_amount')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'charge_amount')::numeric),0))
          into h_day, h_night, h_sat, h_sun, h_bh, pay_ex, chg_ex
          from jsonb_array_elements(segments) seg_el;

       if chg_ex <> 0 and (coalesce(h_day,0)+coalesce(h_night,0)+coalesce(h_sat,0)+coalesce(h_sun,0)+coalesce(h_bh,0)) <> 0 then
  margin_ex := public._inv_round2(chg_ex - pay_ex);
  vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
  inc_amt := public._inv_round2(chg_ex + vat_amt);

  line_desc := coalesce(nullif(btrim(coalesce(c_display_site,'')) ,''), ('TS '||tsid::text)) ||
               ' – W/E '|| coalesce(snap.week_ending_date::text,'');

  v_meta := jsonb_build_object(
    'line_type','HOURS_WEEKLY',
    'timesheet_id', tsid::text,
    'tsfin_id', snap.id::text,
    'week_ending_date', snap.week_ending_date::text,
    'bucket_labels', c_bucket_labels
  );

  v_source_key := 'TS:' || tsid::text || ':HOURS:WEEK';

  insert into public.invoice_lines(
    invoice_id, timesheet_id, booking_id, description,
    hours_day, hours_night, hours_sat, hours_sun, hours_bh,
    pay_day, pay_night, pay_sat, pay_sun, pay_bh,
    charge_day, charge_night, charge_sat, charge_sun, charge_bh,
    total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
    vat_rate_pct, vat_amount, total_inc_vat,
    paper_ts_r2_key, meta_json, source_key
  )
  values (
    p_invoice_id, tsid, snap.booking_id, line_desc,
    h_day, h_night, h_sat, h_sun, h_bh,
    null,null,null,null,null,
    null,null,null,null,null,
    pay_ex, chg_ex, margin_ex,
    v_vat_rate, vat_amt, inc_amt,
    v_exact_timesheet_document_r2_key,
    v_meta,
    v_source_key
  )
  on conflict (invoice_id, source_key) do nothing;
end if;

        end if;

        -- Additional rates


    end loop;
  end if;
end if;

  -- 2) Add adjustments
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_adjustments') then
    if jsonb_typeof(p_payload->'add_adjustments') = 'array' then
      for adj in
        select value from jsonb_array_elements(p_payload->'add_adjustments') value
      loop
        if adj is null or jsonb_typeof(adj) <> 'object' then
          continue;
        end if;

        v_adj_token := nullif(btrim(coalesce(adj->>'client_token','')), '');
        v_adj_desc  := nullif(btrim(coalesce(adj->>'description','')), '');
        begin
          v_adj_ex := (adj->>'amount_ex_vat')::numeric;
        exception when others then
          v_adj_ex := null;
        end;

        if v_adj_token is null or v_adj_desc is null or v_adj_ex is null then
          continue;
        end if;

        v_adj_vat := public._inv_round2(v_adj_ex * v_vat_rate / 100);
        if v_vat_rate = 0 then v_adj_vat := 0; end if;
        v_adj_inc := public._inv_round2(v_adj_ex + v_adj_vat);

        v_adj_source_key := 'ADJ:' || v_adj_token;

        v_meta := jsonb_build_object(
          'line_type','ADJUSTMENT',
          'client_token', v_adj_token,
          'description', v_adj_desc,
          'amount_ex_vat', public._inv_round2(v_adj_ex),
          'vat_rate_pct', v_vat_rate,
          'vat_chargeable', v_vat_chargeable
        );

        v_hist_adj := v_hist_adj || jsonb_build_array(v_meta);

        insert into public.invoice_lines(
          invoice_id, timesheet_id, booking_id, description,
          hours_day, hours_night, hours_sat, hours_sun, hours_bh,
          pay_day, pay_night, pay_sat, pay_sun, pay_bh,
          charge_day, charge_night, charge_sat, charge_sun, charge_bh,
          total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
          vat_rate_pct, vat_amount, total_inc_vat,
          paper_ts_r2_key, meta_json, source_key
        )
        values (
          p_invoice_id, null, null, v_adj_desc,
          0,0,0,0,0,
          null,null,null,null,null,
          null,null,null,null,null,
          0, public._inv_round2(v_adj_ex), public._inv_round2(v_adj_ex),
          v_vat_rate, v_adj_vat, v_adj_inc,
          null,
          v_meta,
          v_adj_source_key
        )
        on conflict (invoice_id, source_key) do nothing;
      end loop;
    end if;
  end if;

  -- History: adjustments added (always)
  if jsonb_typeof(v_hist_adj)='array' and jsonb_array_length(v_hist_adj) > 0 then
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_ADJUSTMENTS_ADDED',
      null,
      jsonb_build_object('adjustments', v_hist_adj),
      null,
      p_actor_user_id
    );
  end if;


  -- 3) Add timesheets (full parity: hours + additional + expenses + mileage), for THIS invoice week_start
  if v_add_ts_ids is not null and coalesce(array_length(v_add_ts_ids,1),0) > 0 then
    foreach tsid in array v_add_ts_ids loop
      if tsid is null then
        continue;
      end if;

      -- Load snapshot + timesheet + precheck
      select
        tf.*,
        tsr.booking_id,
        tsr.week_ending_date,
        tsr.reference_number,
        tsr.sheet_scope::text as sheet_scope,
        coalesce(tsr.submission_mode::text,'') as submission_mode,
        tsr.day_references_json,
        tsr.actual_schedule_json,
        cw.contract_id
      into snap
      from public.timesheets_financials tf
      join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
      left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
      join public.v_ts_invoice_precheck pcv on pcv.timesheet_id = tf.timesheet_id
      where tf.timesheet_id = tsid
        and tf.is_current = true
        and tf.locked_by_invoice_id is null
        and tf.processing_status = 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
        and upper(coalesce(pcv.precheck_status,''))
          in ('OK','BLOCK_NO_PDF')
        and tf.client_id = v_inv.client_id
        and (
          pcv.require_reference_to_invoice is not true
          or public._inv_timesheet_has_invoice_reference(
                tsr.sheet_scope::text,
                coalesce(tsr.submission_mode::text,''),
                tsr.reference_number,
                tsr.day_references_json,
                tsr.actual_schedule_json
             )
        )
      limit 1;

      if not found then
        v_dbg_add_timesheets_skipped := v_dbg_add_timesheets_skipped + 1;
        if v_invoice_debug then
          v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_skipped','timesheet_id',coalesce(tsid::text,'')));
        end if;
        continue;
      end if;

      v_dbg_add_timesheets_found := v_dbg_add_timesheets_found + 1;
      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_loaded','timesheet_id',coalesce(tsid::text,''),'tsfin_id',coalesce(snap.id::text,'')));
      end if;

      select v.r2_key
      into v_exact_timesheet_document_r2_key
      from public.timesheets t
      join public.invoice_document_versions v
        on v.entity_type='TIMESHEET'
       and v.entity_id=t.timesheet_id
       and v.purpose='TIMESHEET'
       and v.source_revision=t.document_revision::text
       and v.status='READY'
       and nullif(v.r2_key,'') is not null
       and nullif(v.sha256,'') is not null
       and coalesce(v.size_bytes,0)>0
       and coalesce(v.page_count,0)>0
      where t.timesheet_id=tsid and t.is_current
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1;
      contract_id := snap.contract_id;
      c_daily_calc := false;
      c_bucket_labels := null;
      c_role := null;
      c_display_site := null;
      c_ward_hint := null;

      if contract_id is not null then
        select
          nullif(btrim(coalesce(role,'')), ''),
          nullif(btrim(coalesce(display_site,'')), ''),
          nullif(btrim(coalesce(ward_hint,'')), '')
        into
          c_role, c_display_site, c_ward_hint
        from public.contracts
        where id = contract_id
        limit 1;
      end if;

      v_settings_authority := private._timesheet_settings_authority_frozen_v1(tsid);
      c_daily_calc := coalesce(
        (v_settings_authority#>>'{values,daily_calc_of_invoices}')::boolean,
        false
      );
      c_bucket_labels := case
        when coalesce((v_settings_authority->>'override_client_settings')::boolean,false)
          then v_settings_authority#>'{values,bucket_labels_json}'
        else null
      end;

      if c_bucket_labels is null then
        c_bucket_labels := jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH');
      end if;

      natural_start := (snap.week_ending_date::date - 6);

      segments := '[]'::jsonb;

      -- Build invoiceable segment set for THIS invoice week_start
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
         and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
      then
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
          if seg_locked is not null then
            continue; -- already invoiced
          end if;

          seg_target := nullif(btrim(coalesce(v_seg->>'invoice_target_week_start','')), '')::date;
          seg_ref := btrim(coalesce(v_seg->>'ref_num',''));

          -- segment-level ref gating if required
          select * into pc from public.v_ts_invoice_precheck where timesheet_id = tsid limit 1;
          if pc.require_reference_to_invoice is true and seg_ref = '' then
            continue;
          end if;

          -- delayed detection
          if seg_target is null or seg_target = natural_start then
            -- not delayed: belongs to natural week only
            if v_week_start <> natural_start then
              continue;
            end if;
            -- allow early is implicit for invoice edits (invoice is already being edited)
            segments := segments || jsonb_build_array(v_seg);
          else
            -- delayed: only if this invoice week matches target AND target has arrived (no early invoicing for delayed)
            if v_week_start = seg_target and seg_target <= v_anchor_ymd then
              segments := segments || jsonb_build_array(v_seg);
            end if;
          end if;
        end loop;
      else
        -- Non-segments: include only when invoice week matches natural week
        if v_week_start = natural_start then
          segments := jsonb_build_array(
            jsonb_build_object(
              'segment_id', null,
              'date', coalesce(snap.week_ending_date::text, v_week_start::text),
              'hours_day', public._inv_round2(coalesce(snap.hours_day,0)),
              'hours_night', public._inv_round2(coalesce(snap.hours_night,0)),
              'hours_sat', public._inv_round2(coalesce(snap.hours_sat,0)),
              'hours_sun', public._inv_round2(coalesce(snap.hours_sun,0)),
              'hours_bh', public._inv_round2(coalesce(snap.hours_bh,0)),
              'pay_amount', public._inv_round2(
                coalesce(snap.total_pay_ex_vat,0)
                - coalesce(snap.additional_pay_ex_vat,0)
                - coalesce(snap.expenses_pay_ex_vat,0)
                - coalesce(snap.mileage_pay_ex_vat,0)
              ),
              'charge_amount', public._inv_round2(
                coalesce(snap.total_charge_ex_vat,0)
                - coalesce(snap.additional_charge_ex_vat,0)
                - coalesce(snap.expenses_charge_ex_vat,0)
                - coalesce(snap.mileage_charge_ex_vat,0)
              ),
              'ref_num', coalesce(snap.reference_number,'')
            )
          );
        end if;
      end if;

      if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
        continue;
      end if;

      -- Build the exact invoice-line economics from the frozen current financial snapshot.
      -- This mirrors Invoice Async V8 generation and never derives economics from mutable live rows.
      select p.vat_rate
      into v_vat_rate
      from private._invoice_generation_vat_policy_batch(jsonb_build_array(jsonb_build_object(
        'source_member_key','invoice-edit:'||tsid::text,
        'source_type','TIMESHEET',
        'source_id',tsid,
        'timesheet_id',tsid,
        'effective_date',snap.week_ending_date
      ))) p
      where p.source_member_key='invoice-edit:'||tsid::text
        and p.valid
        and p.vat_rate is not null
      limit 1;

      if not found then
        raise exception 'INVOICE_EDIT_VAT_POLICY_UNRESOLVED'
          using errcode='P0001',detail=jsonb_build_object(
            'invoice_id',p_invoice_id,'timesheet_id',tsid)::text;
      end if;

      insert into public.invoice_lines(
        invoice_id,timesheet_id,booking_id,description,
        hours_day,hours_night,hours_sat,hours_sun,hours_bh,
        pay_day,pay_night,pay_sat,pay_sun,pay_bh,
        charge_day,charge_night,charge_sat,charge_sun,charge_bh,
        total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,
        vat_rate_pct,vat_amount,total_inc_vat,
        paper_ts_r2_key,meta_json,source_key
      )
      with base as materialized (
        select coalesce(
          (select nullif(btrim(coalesce(cd.display_name,'')),'')
             from public.candidates cd where cd.id=snap.candidate_id limit 1),
          'TS '||tsid::text
        ) candidate_display
      ),
      segment_rows as materialized (
        select
          case when left(coalesce(s.value->>'date',''),10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
            then left(s.value->>'date',10) end work_date,
          case when pg_input_is_valid(s.value->>'hours_day','numeric') then (s.value->>'hours_day')::numeric else 0 end h_day,
          case when pg_input_is_valid(s.value->>'hours_night','numeric') then (s.value->>'hours_night')::numeric else 0 end h_night,
          case when pg_input_is_valid(s.value->>'hours_sat','numeric') then (s.value->>'hours_sat')::numeric else 0 end h_sat,
          case when pg_input_is_valid(s.value->>'hours_sun','numeric') then (s.value->>'hours_sun')::numeric else 0 end h_sun,
          case when pg_input_is_valid(s.value->>'hours_bh','numeric') then (s.value->>'hours_bh')::numeric else 0 end h_bh,
          case
            when pg_input_is_valid(s.value->>'pay_amount','numeric') then (s.value->>'pay_amount')::numeric
            when pg_input_is_valid(s.value->>'pay_ex_vat','numeric') then (s.value->>'pay_ex_vat')::numeric
            else 0 end pay_ex,
          case
            when pg_input_is_valid(s.value->>'charge_amount','numeric') then (s.value->>'charge_amount')::numeric
            when pg_input_is_valid(s.value->>'charge_ex_vat','numeric') then (s.value->>'charge_ex_vat')::numeric
            else 0 end charge_ex
        from jsonb_array_elements(segments) s(value)
      ),
      hour_daily as materialized (
        select s.work_date,sum(s.h_day) h_day,sum(s.h_night) h_night,sum(s.h_sat) h_sat,
          sum(s.h_sun) h_sun,sum(s.h_bh) h_bh,sum(s.pay_ex) pay_ex,sum(s.charge_ex) charge_ex
        from segment_rows s
        where c_daily_calc and s.work_date is not null
        group by s.work_date
      ),
      hour_weekly as materialized (
        select sum(s.h_day) h_day,sum(s.h_night) h_night,sum(s.h_sat) h_sat,
          sum(s.h_sun) h_sun,sum(s.h_bh) h_bh,sum(s.pay_ex) pay_ex,sum(s.charge_ex) charge_ex
        from segment_rows s
        having not c_daily_calc or not exists(select 1 from segment_rows d where d.work_date is not null)
      ),
      additional_source as materialized (
        select upper(a.key) code,a.value unit
        from jsonb_each(case when jsonb_typeof(snap.additional_units_json)='object'
          then snap.additional_units_json else '{}'::jsonb end) a
        where jsonb_typeof(a.value)='object' and btrim(a.key)<>''
      ),
      additional_daily as materialized (
        select a.code,left(d.key,10) work_date,
          case when pg_input_is_valid(d.value,'numeric') then d.value::numeric else 0 end units,
          case when pg_input_is_valid(a.unit->>'pay_rate','numeric') then (a.unit->>'pay_rate')::numeric else 0 end pay_rate,
          case when pg_input_is_valid(a.unit->>'charge_rate','numeric') then (a.unit->>'charge_rate')::numeric else 0 end charge_rate,
          coalesce(nullif(a.unit->>'bucket_name',''),a.code) bucket_name,
          coalesce(nullif(a.unit->>'unit_name',''),'units') unit_name,
          a.unit->'frequency' frequency
        from additional_source a
        cross join lateral jsonb_each_text(case when jsonb_typeof(a.unit->'days')='object'
          then a.unit->'days' else '{}'::jsonb end) d
        where c_daily_calc
          and left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
          and pg_input_is_valid(d.value,'numeric')
          and d.value::numeric<>0
          and exists(select 1 from segment_rows where work_date is not null)
      ),
      additional_weekly as materialized (
        select a.code,
          case when pg_input_is_valid(a.unit->>'unit_count','numeric') then (a.unit->>'unit_count')::numeric else 0 end units,
          case when pg_input_is_valid(a.unit->>'pay_rate','numeric') then (a.unit->>'pay_rate')::numeric else 0 end pay_rate,
          case when pg_input_is_valid(a.unit->>'charge_rate','numeric') then (a.unit->>'charge_rate')::numeric else 0 end charge_rate,
          case when pg_input_is_valid(a.unit->>'pay_ex_vat','numeric') then (a.unit->>'pay_ex_vat')::numeric else 0 end pay_ex,
          case when pg_input_is_valid(a.unit->>'charge_ex_vat','numeric') then (a.unit->>'charge_ex_vat')::numeric else 0 end charge_ex,
          coalesce(nullif(a.unit->>'bucket_name',''),a.code) bucket_name,
          coalesce(nullif(a.unit->>'unit_name',''),'units') unit_name,
          a.unit->'frequency' frequency
        from additional_source a
        where not(c_daily_calc
          and exists(select 1 from jsonb_each_text(case when jsonb_typeof(a.unit->'days')='object'
            then a.unit->'days' else '{}'::jsonb end) d
            where left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(d.value,'numeric') and d.value::numeric<>0))
          and (
            (case when pg_input_is_valid(a.unit->>'pay_ex_vat','numeric') then (a.unit->>'pay_ex_vat')::numeric else 0 end)<>0
            or (case when pg_input_is_valid(a.unit->>'charge_ex_vat','numeric') then (a.unit->>'charge_ex_vat')::numeric else 0 end)<>0
          )
      ),
      expense_lines as materialized (
        select e.code,e.pay_ex,e.charge_ex
        from (values
          ('TRAVEL',coalesce(snap.travel_pay_ex_vat,0),coalesce(snap.travel_charge_ex_vat,0)),
          ('ACCOMMODATION',coalesce(snap.accommodation_pay_ex_vat,0),coalesce(snap.accommodation_charge_ex_vat,0)),
          ('OTHER',coalesce(snap.other_pay_ex_vat,0),coalesce(snap.other_charge_ex_vat,0)),
          ('EXPENSES_FALLBACK',
            case when coalesce(snap.travel_pay_ex_vat,0)+coalesce(snap.accommodation_pay_ex_vat,0)+coalesce(snap.other_pay_ex_vat,0)=0
              then coalesce(snap.expenses_pay_ex_vat,0) else 0 end,
            case when coalesce(snap.travel_charge_ex_vat,0)+coalesce(snap.accommodation_charge_ex_vat,0)+coalesce(snap.other_charge_ex_vat,0)=0
              then coalesce(snap.expenses_charge_ex_vat,0) else 0 end),
          ('MILEAGE',coalesce(snap.mileage_pay_ex_vat,0),coalesce(snap.mileage_charge_ex_vat,0))
        ) e(code,pay_ex,charge_ex)
        where e.pay_ex<>0 or e.charge_ex<>0
      ),
      line_union as materialized (
        select b.candidate_display||' - '||h.work_date||' - W/E '||coalesce(snap.week_ending_date::text,'' ) description,
          h.h_day,h.h_night,h.h_sat,h.h_sun,h.h_bh,h.pay_ex,h.charge_ex,
          'HOURS_DAILY' line_type,'TS:'||tsid::text||':HOURS:'||h.work_date source_key,
          jsonb_build_object('date',h.work_date) detail
        from hour_daily h cross join base b
        union all
        select b.candidate_display||' - W/E '||coalesce(snap.week_ending_date::text,''),
          h.h_day,h.h_night,h.h_sat,h.h_sun,h.h_bh,h.pay_ex,h.charge_ex,
          'HOURS_WEEKLY','TS:'||tsid::text||':HOURS:WEEK','{}'::jsonb
        from hour_weekly h cross join base b
        union all
        select b.candidate_display||' - '||a.bucket_name||' - '||a.work_date||' - '||a.units||' '||a.unit_name,
          0,0,0,0,0,round(a.units*a.pay_rate,2),round(a.units*a.charge_rate,2),
          'ADDITIONAL_RATE_DAILY','TS:'||tsid::text||':ADD:'||a.code||':'||a.work_date,
          jsonb_build_object('date',a.work_date,'bucket',jsonb_build_object(
            'code',a.code,'bucket_name',a.bucket_name,'unit_name',a.unit_name,'frequency',a.frequency),
            'units',jsonb_build_object('unit_count',a.units,'pay_rate',a.pay_rate,'charge_rate',a.charge_rate))
        from additional_daily a cross join base b
        union all
        select b.candidate_display||' - '||a.bucket_name||' - '||a.units||' '||a.unit_name,
          0,0,0,0,0,a.pay_ex,a.charge_ex,
          'ADDITIONAL_RATE','TS:'||tsid::text||':ADD:'||a.code||':WEEK',
          jsonb_build_object('bucket',jsonb_build_object(
            'code',a.code,'bucket_name',a.bucket_name,'unit_name',a.unit_name,'frequency',a.frequency),
            'units',jsonb_build_object('unit_count',a.units,'pay_rate',a.pay_rate,'charge_rate',a.charge_rate))
        from additional_weekly a cross join base b
        union all
        select case when e.code='MILEAGE' then 'Mileage - '||coalesce(snap.mileage_units,0)||' miles (W/E '||coalesce(snap.week_ending_date::text,'')||')'
          when e.code='EXPENSES_FALLBACK' then 'Expenses (W/E '||coalesce(snap.week_ending_date::text,'')||')'
          else initcap(replace(e.code,'_',' '))||' expenses (W/E '||coalesce(snap.week_ending_date::text,'')||')' end,
          0,0,0,0,0,e.pay_ex,e.charge_ex,
          case when e.code='MILEAGE' then 'MILEAGE'
            when e.code='EXPENSES_FALLBACK' then 'EXPENSES_TOTAL'
            else 'EXPENSE_'||e.code end,
          case when e.code='MILEAGE' then 'TS:'||tsid::text||':MILEAGE'
            when e.code='EXPENSES_FALLBACK' then 'TS:'||tsid::text||':EXP:TOTAL'
            else 'TS:'||tsid::text||':EXP:'||e.code end,
          jsonb_build_object('expense',case when e.code='MILEAGE' then jsonb_build_object(
            'category','MILEAGE','mileage_units',snap.mileage_units,
            'pay_rate',snap.mileage_pay_rate,'charge_rate',snap.mileage_charge_rate,
            'evidence_r2_key',snap.mileage_evidence_r2_key,'evidence_manifest',snap.mileage_evidence_manifest)
            else jsonb_build_object('category',e.code,'note',snap.expenses_description,
              'evidence_r2_key',snap.expenses_evidence_r2_key,'evidence_manifest',snap.expenses_evidence_manifest) end)
        from expense_lines e
      )
      select p_invoice_id,tsid,snap.booking_id,l.description,
        round(l.h_day,2),round(l.h_night,2),round(l.h_sat,2),round(l.h_sun,2),round(l.h_bh,2),
        null,null,null,null,null,
        snap.charge_day,snap.charge_night,snap.charge_sat,snap.charge_sun,snap.charge_bh,
        round(l.pay_ex,2),round(l.charge_ex,2),round(l.charge_ex-l.pay_ex,2),v_vat_rate,
        round(l.charge_ex*v_vat_rate/100,2),round(l.charge_ex+(l.charge_ex*v_vat_rate/100),2),
        v_exact_timesheet_document_r2_key,
        jsonb_build_object('line_type',l.line_type,'timesheet_id',tsid,'tsfin_id',snap.id,
          'candidate_display',l.description,'week_ending_date',snap.week_ending_date,
          'role',c_role,'hospital',c_display_site,'ward',c_ward_hint,'bucket_labels',c_bucket_labels,
          'totals',jsonb_build_object('line_pay_ex_vat',round(l.pay_ex,2),
            'line_charge_ex_vat',round(l.charge_ex,2),'margin_ex_vat',round(l.charge_ex-l.pay_ex,2),
            'vat_rate_pct',v_vat_rate,'vat_amount',round(l.charge_ex*v_vat_rate/100,2),
            'total_inc_vat',round(l.charge_ex+(l.charge_ex*v_vat_rate/100),2)))||l.detail,
        l.source_key
      from line_union l
      on conflict(invoice_id,source_key) do nothing;
      -- Build segment refs to lock
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
      then
        for v_seg in
          select value from jsonb_array_elements(segments) value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_refs := seg_refs || jsonb_build_array(
            jsonb_build_object(
              'tsfin_id', snap.id::text,
              'segment_id', nullif(btrim(coalesce(v_seg->>'segment_id','')), '')
            )
          );
        end loop;
      else
        -- lock whole for non-segments
        seg_refs := seg_refs || jsonb_build_array(
          jsonb_build_object('tsfin_id', snap.id::text, 'segment_id', null)
        );
      end if;
    end loop;

    -- Apply segment locks for the exact selected source rows.
    if jsonb_typeof(seg_refs) = 'array' and jsonb_array_length(seg_refs) > 0 then
      perform public._inv_lock_segments_for_invoice(p_invoice_id, seg_refs);
    end if;

    -- History: timesheets added (always; includes requested ids)
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_TIMESHEETS_ADDED',
      null,
      jsonb_build_object('add_timesheet_ids', coalesce(to_jsonb(v_add_ts_ids), '[]'::jsonb)),
      null,
      p_actor_user_id
    );
  end if;

  -- 3c) Contract week status: set INVOICED only when timesheet is FULLY invoiced (segment-aware), and revert INVOICED -> AUTHORISED if no longer fully invoiced.
  -- Touch set = union of: add_timesheet_ids, line-removal touched (hours), segment-op touched.
  v_cw_ts_ids := array[]::uuid[];
  if v_add_ts_ids is not null and coalesce(array_length(v_add_ts_ids,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_add_ts_ids;
  end if;
  if v_ts_ids_touched is not null and coalesce(array_length(v_ts_ids_touched,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_ts_ids_touched;
  end if;
  if v_seg_ts_ids is not null and coalesce(array_length(v_seg_ts_ids,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_seg_ts_ids;
  end if;

  -- de-dup
  select array_agg(distinct x)
  into v_cw_ts_ids
  from unnest(coalesce(v_cw_ts_ids, array[]::uuid[])) x
  where x is not null;

  v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);

  if coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
    with src as (
      select
        cw.timesheet_id,
        cw.status as cw_status,
        tf.locked_by_invoice_id,
        tf.invoice_breakdown_json,
        (
          case
            when tf.invoice_breakdown_json is not null
             and jsonb_typeof(tf.invoice_breakdown_json)='object'
             and coalesce(tf.invoice_breakdown_json->>'mode','')='SEGMENTS'
             and jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
             and jsonb_array_length(tf.invoice_breakdown_json->'segments') > 0
            then
              not exists (
                select 1
                from jsonb_array_elements(tf.invoice_breakdown_json->'segments') s(seg)
                where nullif(btrim(coalesce(s.seg->>'invoice_locked_invoice_id','')), '') is null
              )
            else
              (tf.locked_by_invoice_id is not null)
          end
        ) as fully_invoiced
      from public.contract_weeks cw
      join public.timesheets_financials tf
        on tf.is_current = true
       and tf.timesheet_id = cw.timesheet_id
      where cw.timesheet_id = any(v_cw_ts_ids)
    )
    update public.contract_weeks cw
    set status = case
      when src.fully_invoiced then 'INVOICED'::public.contract_week_status_enum
      when cw.status = 'INVOICED'::public.contract_week_status_enum then 'AUTHORISED'::public.contract_week_status_enum
      else cw.status
    end
    from src
    where cw.timesheet_id = src.timesheet_id;
  end if;


  -- 4) Recompute invoice totals from invoice_lines and clear PDF key
  select
    public._inv_round2(coalesce(sum(coalesce(l.total_charge_ex_vat,0)),0)),
    public._inv_round2(coalesce(sum(coalesce(l.vat_amount,0)),0)),
    public._inv_round2(coalesce(sum(coalesce(l.total_inc_vat,0)),0))
  into v_new_ex, v_new_vat, v_new_inc
  from public.invoice_lines l
  where l.invoice_id = p_invoice_id;


  perform public.invoice_recompute_totals(p_invoice_id);

  -- Recompute header_snapshot_json.meta counters to avoid stale values after edits
  select count(distinct l.timesheet_id)
  into v_hdr_ts_count_lines
  from public.invoice_lines l
  where l.invoice_id = p_invoice_id
    and l.timesheet_id is not null;

  select count(*)
  into v_hdr_seg_locked_count
  from public.timesheets_financials tf
  cross join lateral jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) as seg(seg_obj)
  where tf.is_current = true
    and coalesce(seg.seg_obj->>'invoice_locked_invoice_id','') = p_invoice_id::text;

  select count(distinct tf.timesheet_id)
  into v_hdr_ts_count_seglocks
  from public.timesheets_financials tf
  where tf.is_current = true
    and exists (
      select 1
      from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) as seg(seg_obj)
      where coalesce(seg.seg_obj->>'invoice_locked_invoice_id','') = p_invoice_id::text
    );

  if coalesce(v_hdr_seg_locked_count,0) > 0 then
    v_hdr_meta_timesheet_count := coalesce(v_hdr_ts_count_seglocks,0);
    v_hdr_meta_segment_count := coalesce(v_hdr_seg_locked_count,0);
  else
    v_hdr_meta_timesheet_count := coalesce(v_hdr_ts_count_lines,0);
    v_hdr_meta_segment_count := coalesce(v_hdr_meta_timesheet_count,0);
  end if;

  -- The statement triggers are the sole document/issue invalidation authority.
  -- This update changes only the authoritative business snapshot counters.
  update public.invoices invu
  set header_snapshot_json=jsonb_set(jsonb_set(coalesce(invu.header_snapshot_json,'{}'::jsonb),
      '{meta,timesheet_count}',to_jsonb(v_hdr_meta_timesheet_count),true),
      '{meta,segment_count}',to_jsonb(v_hdr_meta_segment_count),true),
    updated_at=now()
  where invu.id=p_invoice_id;

-- Refresh invoice-level NHSP/HR cache after timesheet/segment changes
  if coalesce(v_refresh_hr_cache,false) = true then
    perform 1
    from public.invoice_source_rows_collect(p_invoice_id, true) sr
    limit 1;
  end if;

  -- Revalidate ownership after every line and segment move in this Save. A
  -- source edit must not queue work for a source that was detached later in the
  -- same transaction, and every edited SEGMENTS identity must still be locked
  -- to this exact invoice.
  if cardinality(v_source_changed_ts_ids)>0 and exists(
    select 1
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_id')::uuid=any(v_source_changed_ts_ids)
      and not exists(
        select 1 from public.invoice_lines carrier
        where carrier.invoice_id=p_invoice_id
          and (
            carrier.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              carrier.timesheet_id is null
              and coalesce(carrier.meta_json->>'timesheet_id','')~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (carrier.meta_json->>'timesheet_id')::uuid=
                (desired.value->>'timesheet_id')::uuid
            )
          )
      )
      and not exists(
        select 1
        from public.timesheets_financials tf
        cross join lateral jsonb_array_elements(
          coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) seg(value)
        where tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
          and tf.is_current
          and nullif(btrim(coalesce(
            seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
      )
  ) then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND',
      detail=jsonb_build_object('reason','POST_EDIT_SOURCE_DETACHED')::text;
  end if;

  if cardinality(v_source_changed_ts_ids)>0 and exists(
    select 1
    from jsonb_each(v_source_updates_map) desired
    cross join lateral jsonb_array_elements(
      coalesce(desired.value->'segment_updates','[]'::jsonb)) requested(value)
    where desired.value->>'source_mode'='SEGMENTS'
      and not exists(
        select 1
        from public.timesheets_financials tf
        cross join lateral jsonb_array_elements(
          coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) seg(value)
        where tf.id=(desired.value->>'financial_id')::uuid
          and tf.is_current
          and tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
          and nullif(btrim(coalesce(
            seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
          and (
            (
              nullif(requested.value->>'segment_id','') is not null
              and nullif(btrim(coalesce(seg.value->>'segment_id','')),'')
                =nullif(requested.value->>'segment_id','')
            ) or (
              nullif(requested.value->>'segment_id','') is null
              and coalesce(seg.value->>'start_utc',seg.value->>'start')
                is not distinct from requested.value->>'start_identity'
              and coalesce(seg.value->>'end_utc',seg.value->>'end')
                is not distinct from requested.value->>'end_identity'
            )
          )
      )
  ) then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND',
      detail=jsonb_build_object('reason','POST_EDIT_SEGMENT_DETACHED')::text;
  end if;

  -- A material source edit always starts or reuses the exact replacement
  -- timesheet work. Replacement of an existing invoice preview is derived from
  -- the locked pre-edit V8 state; browser flags cannot suppress it.
  if cardinality(v_source_changed_ts_ids)>0 then
    select coalesce(jsonb_agg(jsonb_build_object(
      'command_type','VIEW_TIMESHEET_DOCUMENT',
      'timesheet_id',changed_id,
      'purpose','TIMESHEET',
      'priority_reason','SOURCE_EDIT_REPLACEMENT',
      'template_version','timesheet-professional-v2')
      order by changed_id),'[]'::jsonb)
    into v_document_commands
    from unnest(v_source_changed_ts_ids) changed_id;

    v_source_edit_invoice_replacement_required:=
      v_source_edit_preexisting_preview
      or lower(coalesce(p_payload->>'request_preview','false'))
           in('true','1','yes','on');
    if v_source_edit_invoice_replacement_required then
      v_document_commands:=v_document_commands||jsonb_build_array(
        jsonb_build_object(
          'command_type','VIEW_INVOICE_DOCUMENT',
          'invoice_id',p_invoice_id,
          'purpose','DRAFT_PREVIEW',
          'priority_reason',case when v_source_edit_preexisting_preview
            then 'SOURCE_EDIT_REPLACEMENT' else 'VIEW_NOW' end,
          'template_version','invoice-professional-v2'));
    end if;

    v_expected_command_count:=jsonb_array_length(v_document_commands);
    if v_expected_command_count>1000 then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_TOO_MANY_REPLACEMENTS';
    end if;

    v_started_operations:=public.invoice_operation_start_batch(
      v_document_commands,p_actor_user_id,v_now);

    if jsonb_typeof(v_started_operations)<>'array'
       or jsonb_array_length(v_started_operations)<>v_expected_command_count then
      raise exception using errcode='55000',
        message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
        detail=jsonb_build_object(
          'reason','RESULT_COUNT',
          'expected',v_expected_command_count,
          'actual',case when jsonb_typeof(v_started_operations)='array'
            then jsonb_array_length(v_started_operations) else null end)::text;
    end if;

    for v_command_no in 1..v_expected_command_count loop
      select value into v_operation_result
      from jsonb_array_elements(v_started_operations) value
      where coalesce(value->>'command_no','')~'^[1-9][0-9]*$'
        and (value->>'command_no')::int=v_command_no;

      if not found or (
        select count(*)
        from jsonb_array_elements(v_started_operations) value
        where coalesce(value->>'command_no','')~'^[1-9][0-9]*$'
          and (value->>'command_no')::int=v_command_no
      )<>1 then
        raise exception using errcode='55000',
          message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
          detail=jsonb_build_object('reason','COMMAND_NO','command_no',v_command_no)::text;
      end if;

      v_source_update:=v_document_commands->(v_command_no-1);
      v_command_type:=v_source_update->>'command_type';
      if v_operation_result->>'command_type' is distinct from v_command_type
         or lower(coalesce(v_operation_result->>'accepted','false'))
              not in('true','1','yes','on')
         or lower(coalesce(v_operation_result->>'blocked','false'))
              in('true','1','yes','on') then
        raise exception using errcode='55000',
          message=case
            when lower(coalesce(v_operation_result->>'blocked','false'))
                   in('true','1','yes','on')
              then 'SOURCE_EDIT_REPLACEMENT_BLOCKED'
            else 'SOURCE_EDIT_REPLACEMENT_REJECTED' end,
          detail=jsonb_build_object(
            'command_no',v_command_no,
            'terminal_error',v_operation_result->'terminal_error')::text;
      end if;

      v_operation_status:=upper(coalesce(v_operation_result->>'status',''));
      v_operation_id:=case when coalesce(v_operation_result->>'operation_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (v_operation_result->>'operation_id')::uuid end;
      v_document_version_id:=case when coalesce(v_operation_result->>'document_version_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (v_operation_result->>'document_version_id')::uuid end;

      if v_operation_status='READY' then
        if v_document_version_id is null or v_operation_id is not null
           or not exists(
             select 1
             from public.invoice_document_versions dv
             where dv.id=v_document_version_id
               and dv.entity_type=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'INVOICE' end
               and dv.entity_id=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (v_source_update->>'timesheet_id')::uuid else p_invoice_id end
               and dv.purpose=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'DRAFT_PREVIEW' end
               and dv.source_revision=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (
                   select t.document_revision::text from public.timesheets t
                   where t.timesheet_id=(v_source_update->>'timesheet_id')::uuid
                     and t.is_current)
                 else (
                   select i.document_revision::text from public.invoices i
                   where i.id=p_invoice_id)
                 end
               and dv.template_version=v_source_update->>'template_version'
               and dv.status='READY'
               and nullif(btrim(coalesce(dv.r2_key,'')),'') is not null
               and nullif(btrim(coalesce(dv.sha256,'')),'') is not null
               and coalesce(dv.size_bytes,0)>0
               and coalesce(dv.page_count,0)>0
           ) then
          raise exception using errcode='55000',
            message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
            detail=jsonb_build_object(
              'reason','READY_IDENTITY','command_no',v_command_no)::text;
        end if;
      else
        if v_operation_id is null
           or v_operation_status not in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
           or not exists(
             select 1
             from public.invoice_operations op
             where op.id=v_operation_id
               and op.operation_type='BUILD_DOCUMENT'
               and op.entity_type=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'INVOICE' end
               and op.entity_id=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (v_source_update->>'timesheet_id')::uuid else p_invoice_id end
               and op.source_revision=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (
                   select t.document_revision::text from public.timesheets t
                   where t.timesheet_id=(v_source_update->>'timesheet_id')::uuid
                     and t.is_current)
                 else (
                   select i.document_revision::text from public.invoices i
                   where i.id=p_invoice_id)
                 end
               and op.template_version=v_source_update->>'template_version'
               and coalesce(op.input_json->>'purpose','')=
                 case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                   then 'TIMESHEET' else 'DRAFT_PREVIEW' end
               and op.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
           ) then
          raise exception using errcode='55000',
            message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
            detail=jsonb_build_object(
              'reason','ACTIVE_IDENTITY','command_no',v_command_no)::text;
        end if;
      end if;

      v_validated_operations:=v_validated_operations||jsonb_build_array(v_operation_result);
    end loop;

    select coalesce(jsonb_agg(jsonb_build_object(
      'timesheet_id',t.timesheet_id,
      'document_revision',t.document_revision)
      order by t.timesheet_id),'[]'::jsonb)
    into v_source_changed_revisions
    from public.timesheets t
    where t.timesheet_id=any(v_source_changed_ts_ids) and t.is_current;
  end if;

-- Return compact state only; never build a manifest or PDF here.
  select jsonb_build_object('invoice_id',i.id,'status',i.status,
    'subtotal_ex_vat',i.subtotal_ex_vat,'vat_amount',i.vat_amount,'total_inc_vat',i.total_inc_vat,
    'document_revision',i.document_revision,'document_state',i.document_state,
    'preview_document_version_id',i.preview_document_version_id,
    'active_document_operation_id',i.active_document_operation_id,
    'issue_state',i.issue_state,'active_issue_operation_id',i.active_issue_operation_id,
    'reference_updates_applied',v_refupd_applied,
    'timesheet_location_updates_applied',v_location_applied,
    'timesheet_source_changed',
      cardinality(v_source_changed_ts_ids)>0,
    'source_edit_queue_contract',case when v_source_edit_requested
      then 'INVOICE_SOURCE_EDIT_QUEUE_V1' else null end,
    'changed_timesheet_ids',coalesce(to_jsonb(v_source_changed_ts_ids),'[]'::jsonb),
    'changed_timesheet_revisions',coalesce(v_source_changed_revisions,'[]'::jsonb),
    'source_edit_preexisting_preview',v_source_edit_preexisting_preview,
    'invoice_replacement_required',v_source_edit_invoice_replacement_required,
    'accepted_operations',coalesce(v_validated_operations,'[]'::jsonb),
    'document_queue_requested',jsonb_array_length(v_document_commands)>0)
  into v_manifest from public.invoices i where i.id=p_invoice_id;

  if v_invoice_debug then
    begin
      -- attach finish marker (avoid extra heavy queries here)
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','finish',
          'at_utc', public._inv_iso_utc(now()),
          'invoice_total_charge_ex_vat', v_new_ex,
          'invoice_vat_amount', v_new_vat,
          'invoice_total_inc_vat', v_new_inc
        )
      );

      v_dbg_stats := v_dbg_stats || jsonb_build_object(
        'lines_deleted', v_dbg_lines_deleted,
        'timesheets_unlocked_via_line_removal', v_dbg_timesheets_unlocked,
        'segment_add_refs', v_dbg_seg_add_refs,
        'segment_remove_refs', v_dbg_seg_remove_refs,
        'segment_tsfin_count', v_dbg_seg_tsfins,
        'segment_timesheets_rebuilt', v_dbg_seg_timesheets_rebuilt,
        'segment_timesheets_removed', v_dbg_seg_timesheets_removed,
        'add_timesheets_found', v_dbg_add_timesheets_found,
        'add_timesheets_skipped', v_dbg_add_timesheets_skipped
      );

      perform public._inv_write_audit(
        p_actor_user_id,
        'INVOICE_APPLY_EDITS_DEBUG',
        jsonb_build_object(
          'invoice_id', p_invoice_id::text,
          'week_start', v_week_start::text,
          'week_end', v_week_end::text,
          'stats', v_dbg_stats,
          'steps', v_dbg_steps
        ),
        'invoices',
        p_invoice_id::text,
        null,
        'INVOICE_DEBUG',
        null, null, null
      );
    exception when others then
      null;
    end;
  end if;

  perform public._ctms_assert_invoice_correction_lines_v1(
    p_invoice_id,p_actor_user_id,false,'INVOICE_APPLY_EDITS_RESULT'
  );

  IF v_correction_placement_ts_id IS NOT NULL THEN
    v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
      v_correction_placement_ts_id,null::uuid,p_actor_user_id,false,100);
    IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
       OR v_correction_placement_scope->>'placement_state' NOT IN (
         'COMPLETE_SAME_INVOICE','COMPLETE_SPLIT_INVOICES','INCOMPLETE_MOVE','UNPLACED') THEN
      RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_RESULT_INVALID'
        USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
    END IF;
    v_correction_placement_states:=jsonb_build_array(jsonb_build_object(
      'correction_id',v_correction_placement_scope->>'correction_id',
      'pair_timesheet_ids',v_correction_placement_scope->'pair_timesheet_ids',
      'placement_state',v_correction_placement_scope->>'placement_state',
      'missing_member_kind',v_correction_placement_scope->>'missing_member_kind',
      'placement_invoices',v_correction_placement_scope->'placement_invoices'));
    v_manifest:=v_manifest||jsonb_build_object(
      'correction_pair_placement_states',v_correction_placement_states);
  END IF;

  return v_manifest;

exception when others then
  v_dbg_sqlstate := SQLSTATE;
  v_dbg_error := SQLERRM;

  if v_invoice_debug then
    begin
      perform public._inv_write_audit(
        p_actor_user_id,
        'INVOICE_APPLY_EDITS_ERROR',
        jsonb_build_object(
          'invoice_id', coalesce(p_invoice_id::text,''),
          'sqlstate', v_dbg_sqlstate,
          'error', v_dbg_error,
          'stats', v_dbg_stats,
          'steps', v_dbg_steps
        ),
        'invoices',
        coalesce(p_invoice_id::text,''),
        null,
        'INVOICE_DEBUG',
        null, null, null
      );
    exception when others then
      null;
    end;
  end if;

  raise;
end;
$function$;

revoke all on function public.invoice_apply_edits(uuid,jsonb,uuid)
  from public,anon,authenticated,service_role,supabase_admin;
grant execute on function public.invoice_apply_edits(uuid,jsonb,uuid)
  to CURRENT_USER,service_role;

create or replace function private._invoice_document_advance_batch_v6_downstream(
  p_claims jsonb,
  p_now_utc timestamptz
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_result jsonb:='[]'::jsonb;
  v_part jsonb;
begin
  -- BUILD_MANIFEST creates metadata and bounded dependency work only.
  with recursive claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id from jsonb_array_elements(p_claims) x
    where x->>'phase'='BUILD_MANIFEST'
  ),
  base as materialized (
    select c.*,o.source_revision,o.template_version,
      coalesce(c.payload_json->>'purpose',
        case when c.entity_type='TIMESHEET' then 'TIMESHEET' else 'DRAFT_PREVIEW' end) purpose
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoice_operations o on o.id=c.operation_id
  ),
  reference_scope as materialized (
    select r.*
    from private._invoice_reference_rows_batch((
      select coalesce(array_agg(distinct b.entity_id),
        array[]::uuid[])
      from base b where b.entity_type='INVOICE'
    )) r
  ),
  legacy_version_seed as materialized (
    select b.*,v.id version_id,
      case when b.purpose='FINAL_ISSUE' then v.snapshot_json
        when b.entity_type='INVOICE' then
          jsonb_build_object(
            'snapshot_schema_version','INVOICE_PRESENTATION_SNAPSHOT_V4',
            'presentation_model',(select jsonb_build_object(
              'document_type',case when i.type='CREDIT_NOTE' then 'CREDIT_NOTE'
                when lower(coalesce(i.header_snapshot_json->>'self_bill','false'))='true' then 'SELF_BILL_INVOICE'
                else 'INVOICE' end,
              'invoice_number',i.invoice_no,
              'issue_date',i.issued_at_utc,
              'preview_date',case when i.status='DRAFT' then v_now else null end,
              'tax_point',i.header_snapshot_json->'tax_point_utc',
              'due_date',i.due_at_utc,
              'currency',coalesce(i.header_snapshot_json->'currency','"GBP"'::jsonb),
              'po_reference',i.header_snapshot_json->'po_reference',
              'payment_terms_days',i.header_snapshot_json->'payment_terms_days',
              'payment_terms_text',i.header_snapshot_json->'payment_terms_text',
              'supplier_legal_name',i.header_snapshot_json->'agency_name',
              'supplier_trading_name',i.header_snapshot_json->'agency_trading_name',
              'supplier_registered_address',i.header_snapshot_json->'registered_address',
              'company_registration_number',i.header_snapshot_json->'company_reg_number',
              'vat_registration_number',i.header_snapshot_json->'vat_registration_number',
              'supplier_contact',i.header_snapshot_json->'supplier_contact',
              'bank_name',i.header_snapshot_json->'bank_name',
              'bank_sort_code',i.header_snapshot_json->'bank_sort_code',
              'bank_account_number',i.header_snapshot_json->'bank_account_number',
              'client_legal_name',i.header_snapshot_json->'client_name',
              'client_billing_address',i.header_snapshot_json->'client_invoice_address',
              'client_reference',i.header_snapshot_json->'client_reference',
              'net_total',i.subtotal_ex_vat,'vat_total',i.vat_amount,'gross_total',i.total_inc_vat,
              'amount_paid',i.header_snapshot_json->'amount_paid',
              'amount_credited',i.header_snapshot_json->'amount_credited',
              'amount_outstanding',i.header_snapshot_json->'amount_outstanding',
              'vat_breakdown',i.header_snapshot_json->'vat_breakdown',
              'credit_note',jsonb_build_object('original_invoice_id',i.original_invoice_id,
                'original_invoice_number',i.header_snapshot_json->'original_invoice_number',
                'original_invoice_date',i.header_snapshot_json->'original_invoice_date',
                'reason',i.header_snapshot_json->'credit_reason'),
              'self_bill_wording',i.header_snapshot_json->'self_bill_wording',
              'legal_wording',i.header_snapshot_json->'legal_wording',
              'attachment_policy',i.header_snapshot_json->'attachment_policy',
              'branding_asset_identity',i.header_snapshot_json->'agency_logo',
              'template_version',b.template_version,'locale','en-GB',
              'page_geometry','A4_PORTRAIT_210X297MM')
              from public.invoices i where i.id=b.entity_id),
            'invoice',(select jsonb_build_object(
              'id',i.id,'type',i.type,'status',i.status,'invoice_no',i.invoice_no,
              'client_id',i.client_id,'status_date_utc',i.status_date_utc,
              'issued_at_utc',i.issued_at_utc,'due_at_utc',i.due_at_utc,
              'subtotal_ex_vat',i.subtotal_ex_vat,'vat_amount',i.vat_amount,
              'total_inc_vat',i.total_inc_vat,'original_invoice_id',i.original_invoice_id,
              'notes',i.notes,'header',i.header_snapshot_json,
              'document_revision',i.document_revision)
              from public.invoices i where i.id=b.entity_id),
            'lines',coalesce((select jsonb_agg(jsonb_build_object(
              'id',l.id,'timesheet_id',l.timesheet_id,'booking_id',l.booking_id,
              'description',l.description,'hours_day',l.hours_day,
              'hours_night',l.hours_night,'hours_sat',l.hours_sat,
              'hours_sun',l.hours_sun,'hours_bh',l.hours_bh,
              'pay_day',l.pay_day,'pay_night',l.pay_night,'pay_sat',l.pay_sat,
              'pay_sun',l.pay_sun,'pay_bh',l.pay_bh,
              'charge_day',l.charge_day,'charge_night',l.charge_night,
              'charge_sat',l.charge_sat,'charge_sun',l.charge_sun,
              'charge_bh',l.charge_bh,'total_pay_ex_vat',l.total_pay_ex_vat,
              'total_charge_ex_vat',l.total_charge_ex_vat,
              'margin_ex_vat',l.margin_ex_vat,'vat_rate_pct',l.vat_rate_pct,
              'vat_amount',l.vat_amount,'total_inc_vat',l.total_inc_vat,
              'source_key',l.source_key,'business_meta',l.meta_json)
              order by l.created_at,l.id)
              from public.invoice_lines l where l.invoice_id=b.entity_id),'[]'::jsonb),
            'timesheet_sources',coalesce((select jsonb_agg(jsonb_build_object(
              'timesheet_id',src.timesheet_id,
              'submission_mode',src.submission_mode,
              'document_revision',src.document_revision,
              'manual_document_asset_id',src.manual_document_asset_id,
              'client_is_nhsp',src.client_is_nhsp,
              'no_timesheet_required',src.no_timesheet_required,
              'attach_timesheet',src.attach_timesheet,
              'render_model',src.render_model) order by src.timesheet_id)
              from (
                select distinct t.timesheet_id,
                  t.submission_mode::text submission_mode,
                  t.document_revision,t.manual_document_asset_id,
                  coalesce(vs.client_is_nhsp,false) client_is_nhsp,
                  coalesce(vs.client_no_timesheet_required,false)
                    no_timesheet_required,
                  coalesce(pc.effective_ts_attach_to_invoice,true)
                    attach_timesheet,
                  jsonb_build_object(
                    'timesheet_id',t.timesheet_id,
                    'booking_id',t.booking_id,
                    'contract_id',t.contract_id,
                    'candidate_display',t.occupant_key_norm,
                    'hospital',t.hospital_norm,'ward',t.ward_norm,
                    'job_title',t.job_title_norm,'band',t.band,
                    'shift_label',t.shift_label_norm,
                    'week_ending_date',t.week_ending_date,
                    'reference_number',t.reference_number,
                    'sheet_scope',t.sheet_scope,
                    'submission_mode',t.submission_mode,
                    'scheduled_start_iso',t.scheduled_start_iso,
                    'scheduled_end_iso',t.scheduled_end_iso,
                    'worked_start_iso',t.worked_start_iso,
                    'worked_end_iso',t.worked_end_iso,
                    'break_start_iso',t.break_start_iso,
                    'break_end_iso',t.break_end_iso,
                    'break_minutes',t.break_minutes,
                    'worked_minutes',t.worked_minutes,
                    'day_references',t.day_references_json,
                    'actual_schedule',t.actual_schedule_json,
                    'additional_units_week',t.additional_units_week,
                    'additional_units_per_day',t.additional_units_per_day,
                    'authorisation',jsonb_build_object(
                      'name',t.auth_name,'job_title',t.auth_job_title,
                      'authorised_at_utc',t.authorised_at_server),
                    'signatures',jsonb_build_object(
                      'nurse_r2_key',t.r2_nurse_key,
                      'authorisation_r2_key',t.r2_auth_key,
                      'nurse_sha256',t.img_sha256_nurse,
                      'authorisation_sha256',t.img_sha256_auth),
                    'qr',jsonb_build_object(
                      'status',t.qr_status,'signed_hash',t.qr_signed_hash,
                      'signed_at_utc',t.qr_signed_at_utc,
                      'immutable_r2_key',t.qr_r2_key),
                    'template_version','timesheet-professional-v1',
                    'version',t.version,
                    'document_revision',t.document_revision,
                    'financials',jsonb_build_object(
                      'id',f.id,'timesheet_version',f.timesheet_version,
                      'basis',f.basis,'hours_day',f.hours_day,
                      'hours_night',f.hours_night,'hours_sat',f.hours_sat,
                      'hours_sun',f.hours_sun,'hours_bh',f.hours_bh,
                      'total_pay_ex_vat',f.total_pay_ex_vat,
                      'total_charge_ex_vat',f.total_charge_ex_vat,
                      'invoice_breakdown',f.invoice_breakdown_json))
                    render_model
                from public.invoice_lines il
                join public.timesheets t
                  on t.timesheet_id=il.timesheet_id and t.is_current
                left join public.timesheets_financials f
                  on f.timesheet_id=t.timesheet_id and f.is_current
                left join public.v_timesheets_summary_base vs
                  on vs.timesheet_id=t.timesheet_id
                left join public.v_ts_invoice_precheck pc
                  on pc.timesheet_id=t.timesheet_id
                where il.invoice_id=b.entity_id and il.timesheet_id is not null
              ) src),'[]'::jsonb),
            'references',coalesce((select jsonb_agg(jsonb_build_object(
              'timesheet_id',r.timesheet_id,'sheet_scope',r.sheet_scope,
              'submission_mode',r.submission_mode,'ref_target',r.ref_target,
              'segment_id',r.segment_id,'day_ymd',r.day_ymd,
              'current_reference',r.current_reference,'is_required',r.is_required,
              'row_key',r.row_key) order by r.row_key)
              from reference_scope r where r.invoice_id=b.entity_id),'[]'::jsonb),
            'supporting_sources',coalesce((select jsonb_agg(jsonb_build_object(
              'source_system',s.source_system,'import_id',s.import_id,
              'header_rows',s.header_rows,'header_columns',s.header_columns,
              'rows',s.rows_json) order by s.source_system,s.import_id)
              from public.invoice_hr_source_rows s
              where s.invoice_id=b.entity_id),'[]'::jsonb))
        else
          jsonb_build_object(
            'snapshot_schema_version','TIMESHEET_PRESENTATION_SNAPSHOT_V4',
            'timesheet',(select jsonb_build_object(
              'timesheet_id',t.timesheet_id,'booking_id',t.booking_id,
              'contract_id',t.contract_id,
              'candidate_display',t.occupant_key_norm,
              'hospital',t.hospital_norm,'ward',t.ward_norm,
              'job_title',t.job_title_norm,'band',t.band,
              'shift_label',t.shift_label_norm,
              'week_ending_date',t.week_ending_date,'reference_number',t.reference_number,
              'sheet_scope',t.sheet_scope,'submission_mode',t.submission_mode,
              'scheduled_start_iso',t.scheduled_start_iso,
              'scheduled_end_iso',t.scheduled_end_iso,
              'worked_start_iso',t.worked_start_iso,
              'worked_end_iso',t.worked_end_iso,
              'break_start_iso',t.break_start_iso,
              'break_end_iso',t.break_end_iso,
              'break_minutes',t.break_minutes,'worked_minutes',t.worked_minutes,
              'day_references',t.day_references_json,
              'actual_schedule',t.actual_schedule_json,
              'additional_units_week',t.additional_units_week,
              'additional_units_per_day',t.additional_units_per_day,
              'authorisation',jsonb_build_object(
                'name',t.auth_name,'job_title',t.auth_job_title,
                'authorised_at_utc',t.authorised_at_server),
              'signatures',jsonb_build_object(
                'nurse_r2_key',t.r2_nurse_key,
                'authorisation_r2_key',t.r2_auth_key,
                'nurse_sha256',t.img_sha256_nurse,
                'authorisation_sha256',t.img_sha256_auth),
              'qr',jsonb_build_object(
                'status',t.qr_status,'signed_hash',t.qr_signed_hash,
                'signed_at_utc',t.qr_signed_at_utc,
                'immutable_r2_key',t.qr_r2_key),
              'template_version','timesheet-professional-v1',
              'version',t.version,'document_revision',t.document_revision)
              from public.timesheets t
              where t.timesheet_id=b.entity_id and t.is_current),
            'financials',(select jsonb_build_object(
              'id',f.id,'timesheet_version',f.timesheet_version,'basis',f.basis,
              'hours_day',f.hours_day,'hours_night',f.hours_night,
              'hours_sat',f.hours_sat,'hours_sun',f.hours_sun,'hours_bh',f.hours_bh,
              'total_pay_ex_vat',f.total_pay_ex_vat,
              'total_charge_ex_vat',f.total_charge_ex_vat,
              'invoice_breakdown',f.invoice_breakdown_json)
              from public.timesheets_financials f
              where f.timesheet_id=b.entity_id and f.is_current))
        end
      snapshot_json
    from base b
    join public.invoice_document_versions v
      on v.id=b.document_version_id and v.operation_id=b.operation_id
      and v.entity_type=b.entity_type and v.entity_id=b.entity_id
      and v.purpose=b.purpose
  ),
  presentation_batch as materialized (
    select p.*
    from private._invoice_presentation_snapshot_batch(
      (select coalesce(jsonb_agg(jsonb_build_object(
        'request_key',s.id::text,
        'entity_type',s.entity_type,
        'entity_id',s.entity_id,
        'purpose',s.purpose,
        'template_version',s.template_version
      ) order by s.id),'[]'::jsonb)
      from legacy_version_seed s
      where s.purpose<>'FINAL_ISSUE'),
      v_now
    ) p
  ),
  version_seed as materialized (
    select s.*,
      case when s.purpose='FINAL_ISSUE' then s.snapshot_json
        else p.snapshot_json end snapshot_json_v5,
      p.snapshot_hash snapshot_hash_v5,
      p.valid presentation_valid,
      p.error_code presentation_error_code,
      p.error_detail presentation_error_detail
    from legacy_version_seed s
    left join presentation_batch p on p.request_key=s.id::text
  ),
  missing_versions as materialized (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        error_json=jsonb_build_object(
          'code',coalesce(s.presentation_error_code,'DOCUMENT_VERSION_REQUIRED'),
          'document_version_id',c.document_version_id,
          'detail',coalesce(s.presentation_error_detail,'{}'::jsonb)),
        updated_at_utc=v_now
    from base b
    left join version_seed s on s.id=b.id
    where c.id=b.id and (s.id is null
      or (s.purpose<>'FINAL_ISSUE' and coalesce(s.presentation_valid,false)=false))
    returning c.id,c.status,c.phase,c.document_version_id,c.error_json
  ),
  updated_versions as (
    update public.invoice_document_versions v
    set snapshot_json=case when s.purpose='FINAL_ISSUE'
          then v.snapshot_json else s.snapshot_json_v5 end,
        snapshot_hash=case when s.purpose='FINAL_ISSUE'
          then v.snapshot_hash else s.snapshot_hash_v5 end,
        status=case when v.status='FAILED' then 'PLANNING' else v.status end
    from version_seed s where v.id=s.version_id
      and (s.purpose='FINAL_ISSUE' or s.presentation_valid)
    returning v.id
  ),
  linked as materialized (
    select c.*,s.purpose,s.version_id resolved_document_version_id
    from public.invoice_operation_chunks c join version_seed s on s.id=c.id
      and (s.purpose='FINAL_ISSUE' or s.presentation_valid)
  ),
  invoice_timesheets as materialized (
    select distinct l.id chunk_id,l.resolved_document_version_id document_version_id,
      l.operation_id,il.timesheet_id,t.submission_mode::text submission_mode,
      t.document_revision,t.manual_document_asset_id,
      coalesce(v.client_is_nhsp,false) client_is_nhsp,
      coalesce(v.client_no_timesheet_required,false) no_timesheet_required,
      coalesce(pc.effective_ts_attach_to_invoice,true) attach_timesheet,
      false frozen_source
    from linked l
    join public.invoice_lines il on l.entity_type='INVOICE' and il.invoice_id=l.entity_id
    join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base v on v.timesheet_id=t.timesheet_id
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=t.timesheet_id
    where l.purpose<>'FINAL_ISSUE'
    union
    select l.id,l.resolved_document_version_id,l.operation_id,t.timesheet_id,
      t.submission_mode::text,t.document_revision,t.manual_document_asset_id,
      coalesce(v.client_is_nhsp,false),coalesce(v.client_no_timesheet_required,false),
      true,false
    from linked l join public.timesheets t
      on l.entity_type='TIMESHEET' and t.timesheet_id=l.entity_id and t.is_current
    left join public.v_timesheets_summary_base v on v.timesheet_id=t.timesheet_id
    union
    select l.id,l.resolved_document_version_id,l.operation_id,
      case when coalesce(x.value->>'timesheet_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then (x.value->>'timesheet_id')::uuid end,
      x.value->>'submission_mode',
      case when coalesce(x.value->>'document_revision','')~'^[0-9]+$'
        then (x.value->>'document_revision')::bigint end,
      case when coalesce(x.value->>'manual_document_asset_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(x.value->>'manual_document_asset_id')::uuid end,
      lower(coalesce(x.value->>'client_is_nhsp','false')) in('true','t','1','yes'),
      lower(coalesce(x.value->>'no_timesheet_required','false')) in('true','t','1','yes'),
      lower(coalesce(x.value->>'attach_timesheet','true')) in('true','t','1','yes'),true
    from linked l
    join public.invoice_document_versions dv
      on dv.id=l.resolved_document_version_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(dv.snapshot_json->'timesheet_sources')='array'
        then dv.snapshot_json->'timesheet_sources' else '[]'::jsonb end) x(value)
    where l.entity_type='INVOICE' and l.purpose='FINAL_ISSUE'
      and coalesce(x.value->>'timesheet_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and coalesce(x.value->>'document_revision','')~'^[0-9]+$'
  ),
  missing_manual_timesheet_source as materialized (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        error_json=jsonb_build_object(
          'code','MANUAL_TIMESHEET_ASSET_REQUIRED',
          'timesheet_id',it.timesheet_id,
          'submission_mode',it.submission_mode),
        updated_at_utc=v_now
    from linked l
    join invoice_timesheets it on it.chunk_id=l.id
    where c.id=l.id
      and l.entity_type='TIMESHEET'
      and upper(coalesce(it.submission_mode,'')) in('MANUAL','QR')
      and it.manual_document_asset_id is null
      and not exists(
        select 1
        from public.invoice_document_versions v
        where v.id=l.resolved_document_version_id
          and v.snapshot_json#>>'{presentation_model,schema_version}'=
            'TIMESHEET_RENDER_MODEL_V2'
          and v.snapshot_json#>>'{presentation_model,form_variant}'=
            'QR_UNSIGNED')
    returning c.id
  ),
  unsigned_electronic_timesheet_source as materialized (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        error_json=jsonb_build_object(
          'code','TIMESHEET_SIGNED_EVIDENCE_REQUIRED',
          'timesheet_id',src.timesheet_id),
        updated_at_utc=v_now
    from linked l
    join public.invoice_document_versions v
      on v.id=l.resolved_document_version_id
    cross join lateral (
      select (x.value->>'timesheet_id')::uuid timesheet_id
      from jsonb_array_elements(case
        when jsonb_typeof(v.snapshot_json->'timesheet_sources')='array'
          then v.snapshot_json->'timesheet_sources'
        else '[]'::jsonb end) x(value)
      where coalesce(x.value->>'timesheet_id','')~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        and x.value#>>'{render_model,schema_version}'=
          'TIMESHEET_RENDER_MODEL_V2'
        and x.value#>>'{render_model,form_variant}'=
          'ELECTRONIC_UNSIGNED'
        and lower(coalesce(x.value->>'attach_timesheet','true'))
          in('true','t','1','yes')
      limit 1
    ) src
    where c.id=l.id and l.entity_type='INVOICE'
    returning c.id
  ),
  evidence_candidates as materialized (
    select distinct it.chunk_id,it.document_version_id,it.operation_id,
      te.id source_id,te.timesheet_id,'TIMESHEET_EVIDENCE'::text source_kind,
      te.storage_key original_r2_key,te.display_name,
      upper(coalesce(te.kind,'OTHER')) kind,
      upper(coalesce(te.document_role,'')) document_role,
      coalesce(nullif(te.source_revision,''),encode(digest(concat_ws('|',
        te.id::text,te.storage_key,te.created_at::text),'sha256'),'hex'))
        source_revision,te.document_asset_id,te.created_at
    from invoice_timesheets it join public.timesheet_evidence te
      on te.timesheet_id=it.timesheet_id
    join linked root on root.id=it.chunk_id and root.entity_type='INVOICE'
    where not it.frozen_source
      and nullif(btrim(coalesce(te.storage_key,'')),'') is not null
      and upper(coalesce(te.kind,''))<>'TIMESHEET'
      and upper(coalesce(te.processing_state,''))<>'SUPERSEDED'
      and upper(coalesce(te.document_role,'')) not in(
        'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES')
      and upper(coalesce(te.kind,'')) not in(
        'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES')
      and exists(
        select 1 from public.invoice_lines il
        where il.invoice_id=root.entity_id and il.timesheet_id=it.timesheet_id
          and(
            upper(coalesce(il.meta_json->>'line_type','')) in('MILEAGE','EXPENSES')
            or upper(coalesce(il.meta_json->>'line_type','')) like '%EXPENSE%'
            or upper(coalesce(il.meta_json->>'line_type','')) like '%TRAVEL%'
            or upper(coalesce(il.meta_json->>'line_type','')) like '%ACCOMMODATION%'))
    union
    select distinct it.chunk_id,it.document_version_id,it.operation_id,
      it.timesheet_id,it.timesheet_id,'MANUAL_TIMESHEET',a.original_r2_key,
      coalesce(a.original_filename,'Manual timesheet'),'TIMESHEET','SIGNED_TIMESHEET',
      a.source_revision,a.id,a.created_at_utc
    from invoice_timesheets it join public.invoice_document_assets a
      on a.id=it.manual_document_asset_id
    where upper(coalesce(it.submission_mode,'')) in('MANUAL','QR')
      and it.attach_timesheet and not it.no_timesheet_required
    union
    select distinct l.id,l.resolved_document_version_id,l.operation_id,
      (x.value->>'evidence_id')::uuid,
      case when coalesce(x.value->>'timesheet_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then (x.value->>'timesheet_id')::uuid end,
      'TIMESHEET_EVIDENCE',
      coalesce(x.value->>'original_r2_key',x.value->>'storage_key'),
      coalesce(x.value->>'display_name',x.value->>'kind','Evidence'),
      upper(coalesce(x.value->>'kind','OTHER')),
      upper(coalesce(
        resolved_evidence.document_role,nullif(btrim(x.value->>'document_role'),''),''
      )),
      x.value->>'source_revision',
      (x.value->>'asset_id')::uuid,v.created_at_utc
    from linked l
    join public.invoice_document_versions v
      on v.id=l.resolved_document_version_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(v.snapshot_json->'supporting_manifest')='array'
        then v.snapshot_json->'supporting_manifest' else '[]'::jsonb end) x(value)
    left join public.timesheet_evidence resolved_evidence
      on resolved_evidence.id=case
        when coalesce(x.value->>'evidence_id','') ~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then (x.value->>'evidence_id')::uuid end
    where l.purpose='FINAL_ISSUE'
      and upper(coalesce(x.value->>'kind',''))<>'TIMESHEET'
      and upper(coalesce(resolved_evidence.processing_state,''))<>'SUPERSEDED'
      and nullif(upper(coalesce(
        resolved_evidence.document_role,nullif(btrim(x.value->>'document_role'),''),''
      )),'') is not null
      and upper(coalesce(
        resolved_evidence.document_role,nullif(btrim(x.value->>'document_role'),''),''
      )) not in(
        'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES')
      and upper(coalesce(x.value->>'kind','')) not in(
        'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES')
      and coalesce(x.value->>'asset_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and coalesce(x.value->>'evidence_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),
  evidence_items as materialized (
    select e.chunk_id,e.document_version_id,e.operation_id,
      2000+row_number() over(partition by e.chunk_id
        order by case e.kind when 'TIMESHEET' then 0 else 1 end,
          e.timesheet_id,
          case when e.document_role='EXPENSE_MILEAGE_APPROVAL_SUMMARY' then 0 else 1 end,
          case e.kind when 'MILEAGE' then 1 when 'TRAVEL' then 2
            when 'ACCOMMODATION' then 3 else 4 end,
          e.created_at,e.source_id)::integer ordinal,
      e.source_id,e.source_kind,e.original_r2_key,e.display_name,e.kind,
      e.source_revision,e.document_asset_id
    from evidence_candidates e
  ),
  assets as materialized (
    select e.*,a.id asset_id,a.status asset_status,a.normalised_page_count,
      a.normalised_size_bytes,a.normalised_r2_key,a.normalised_manifest_json,
      a.normalised_sha256,a.normalised_manifest_hash,
      a.operation_id asset_operation_id
      ,exists(
        select 1 from public.invoice_operations ao
        where ao.id=a.operation_id
          and ao.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT'))
        asset_operation_active
    from evidence_items e left join public.invoice_document_assets a
      on a.id=e.document_asset_id
      and a.source_kind=e.source_kind and a.source_id=e.source_id
      and a.source_revision=e.source_revision and a.original_r2_key=e.original_r2_key
  ),
  render_items as materialized (
    select it.chunk_id,it.document_version_id,
      1000+row_number() over(partition by it.chunk_id order by it.timesheet_id)::integer ordinal,
      'ELECTRONIC_TIMESHEET'::text input_type,'TIMESHEET'::text source_entity_type,
      it.timesheet_id source_entity_id,it.document_revision::text source_revision,
      'Electronic timesheet'::text display_label,null::integer expected_page_count,
      'TIMESHEET_POLICY'::text inclusion_reason
    from invoice_timesheets it
    join linked root on root.id=it.chunk_id and root.entity_type='INVOICE'
    where upper(coalesce(it.submission_mode,''))='ELECTRONIC'
      and it.attach_timesheet and not it.client_is_nhsp and not it.no_timesheet_required
    union all
    select l.id,l.resolved_document_version_id,
      3000+row_number() over(partition by l.id
        order by r.source_system,r.import_id)::integer,
      case when upper(r.source_system)='NHSP' then 'NHSP_SUPPORT'
        else 'HEALTHROSTER_SUPPORT' end,
      upper(r.source_system),r.import_id,
      encode(digest(concat_ws('|',r.import_id::text,r.header_rows::text,
        r.header_columns::text,r.rows_json::text),'sha256'),'hex'),
      initcap(lower(r.source_system))||' supporting report',null::integer,
      'FROZEN_SOURCE_SUPPORT'
    from linked l join public.invoice_hr_source_rows r
      on l.entity_type='INVOICE' and r.invoice_id=l.entity_id
    where l.purpose<>'FINAL_ISSUE'
    union all
    select l.id,l.resolved_document_version_id,
      3000+x.ordinality::integer,
      case when upper(x.value->>'source_system')='NHSP' then 'NHSP_SUPPORT'
        else 'HEALTHROSTER_SUPPORT' end,
      upper(x.value->>'source_system'),
      (x.value->>'import_id')::uuid,
      encode(digest(concat_ws('|',x.value->>'import_id',
        (x.value->'header_rows')::text,(x.value->'header_columns')::text,
        (x.value->'rows')::text),'sha256'),'hex'),
      initcap(lower(x.value->>'source_system'))||' supporting report',
      null::integer,'FROZEN_SOURCE_SUPPORT'
    from linked l
    join public.invoice_document_versions v
      on v.id=l.resolved_document_version_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(v.snapshot_json->'source_support')='array'
        then v.snapshot_json->'source_support' else '[]'::jsonb end)
      with ordinality x(value,ordinality)
    where l.purpose='FINAL_ISSUE'
      and coalesce(x.value->>'import_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    union all
    select l.id,l.resolved_document_version_id,4000,'HIGHER_RATE_SUPPORT',
      'INVOICE',l.entity_id,
      encode(digest(coalesce(jsonb_agg(jsonb_build_object(
        'line_id',il.id,'source_key',il.source_key,'meta',il.meta_json)
        order by il.id)::text,'[]'),'sha256'),'hex'),
      'Higher-rate supporting schedule',null::integer,'HIGHER_RATE_POLICY'
    from linked l join public.invoice_lines il
      on l.entity_type='INVOICE' and il.invoice_id=l.entity_id
    where l.purpose<>'FINAL_ISSUE'
      and (upper(coalesce(il.meta_json->>'line_type','')) like '%HIGHER%'
        or il.meta_json ? 'higher_rate')
    group by l.id,l.resolved_document_version_id,l.entity_id
    union all
    select l.id,l.resolved_document_version_id,4000,'HIGHER_RATE_SUPPORT',
      'INVOICE',l.entity_id,
      encode(digest(coalesce(jsonb_agg(x.value order by x.ordinality)::text,
        '[]'),'sha256'),'hex'),
      'Higher-rate supporting schedule',null::integer,'HIGHER_RATE_POLICY'
    from linked l
    join public.invoice_document_versions v
      on v.id=l.resolved_document_version_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(v.snapshot_json->'lines')='array'
        then v.snapshot_json->'lines' else '[]'::jsonb end)
      with ordinality x(value,ordinality)
    where l.purpose='FINAL_ISSUE'
      and (upper(coalesce(x.value#>>'{business_meta,line_type}','')) like '%HIGHER%'
        or coalesce(x.value->'business_meta','{}'::jsonb)?'higher_rate')
    group by l.id,l.resolved_document_version_id,l.entity_id
  ),
  section_pages as materialized (
    select l.id chunk_id,l.resolved_document_version_id document_version_id,
      1900 ordinal,'SECTION_SEPARATOR' input_type,
      'DOCUMENT' source_entity_type,
      l.resolved_document_version_id source_entity_id,
      encode(digest(l.resolved_document_version_id::text||
        '|EVIDENCE','sha256'),'hex') source_revision,
      null::uuid asset_id,null::uuid input_document_version_id,
      'Timesheet and evidence attachments' display_label,
      1 expected_page_count,'SECTION_SEPARATOR' inclusion_reason
    from linked l
    where exists(select 1 from assets a where a.chunk_id=l.id)
    union all
    select l.id,l.resolved_document_version_id,2900,'SECTION_SEPARATOR',
      'DOCUMENT',l.resolved_document_version_id,
      encode(digest(l.resolved_document_version_id::text||
        '|SOURCE_SUPPORT','sha256'),'hex'),
      null,null,'HealthRoster and NHSP support',1,'SECTION_SEPARATOR'
    from linked l
    where exists(select 1 from render_items r
      where r.chunk_id=l.id and r.input_type in(
        'HEALTHROSTER_SUPPORT','NHSP_SUPPORT'))
    union all
    select l.id,l.resolved_document_version_id,3900,'SECTION_SEPARATOR',
      'DOCUMENT',l.resolved_document_version_id,
      encode(digest(l.resolved_document_version_id::text||
        '|HIGHER_RATE_SUPPORT','sha256'),'hex'),
      null,null,'Higher-rate support',1,'SECTION_SEPARATOR'
    from linked l
    where exists(select 1 from render_items r
      where r.chunk_id=l.id and r.input_type='HIGHER_RATE_SUPPORT')
  ),
  manifest_items_raw as materialized (
    select l.id chunk_id,l.resolved_document_version_id document_version_id,0 ordinal,
      case when l.entity_type='INVOICE' then 'INVOICE_CORE'
        else 'ELECTRONIC_TIMESHEET' end input_type,l.entity_type source_entity_type,
      l.entity_id source_entity_id,
      coalesce((select source_revision from public.invoice_document_versions v where v.id=l.resolved_document_version_id),'') source_revision,
      null::uuid asset_id,null::uuid input_document_version_id,'Invoice core' display_label,
      null::integer expected_page_count,'CORE' inclusion_reason
    from linked l
    where not exists(
        select 1 from missing_manual_timesheet_source missing
        where missing.id=l.id)
      and not exists(
        select 1 from unsigned_electronic_timesheet_source unsigned_source
        where unsigned_source.id=l.id)
      and (
        l.entity_type='INVOICE'
        or exists(
          select 1 from invoice_timesheets it
          where it.chunk_id=l.id
            and upper(coalesce(it.submission_mode,''))='ELECTRONIC')
        or (
          l.entity_type='TIMESHEET'
          and exists(
            select 1
            from public.invoice_document_versions v
            where v.id=l.resolved_document_version_id
              and v.snapshot_json#>>'{presentation_model,schema_version}'=
                'TIMESHEET_RENDER_MODEL_V2'
              and v.snapshot_json#>>'{presentation_model,form_variant}'=
                'QR_UNSIGNED'))
      )
    union all
    select s.chunk_id,s.document_version_id,s.ordinal,s.input_type,
      s.source_entity_type,s.source_entity_id,s.source_revision,s.asset_id,
      s.input_document_version_id,s.display_label,s.expected_page_count,s.inclusion_reason
    from section_pages s
    union all
    select r.chunk_id,r.document_version_id,r.ordinal,r.input_type,
      r.source_entity_type,r.source_entity_id,r.source_revision,
      null::uuid,null::uuid,r.display_label,r.expected_page_count,r.inclusion_reason
    from render_items r
    union all
    select a.chunk_id,a.document_version_id,a.ordinal,'ASSET',a.source_kind,a.source_id,a.source_revision,
      a.asset_id,null,a.display_name,a.normalised_page_count,'CONFIGURED_EVIDENCE'
    from assets a
  ),
  manifest_items as materialized (
    select r.chunk_id,r.document_version_id,
      row_number() over(partition by r.chunk_id
        order by r.ordinal,r.input_type,r.source_entity_type,
          r.source_entity_id,r.asset_id)::integer-1 ordinal,
      r.input_type,r.source_entity_type,r.source_entity_id,r.source_revision,
      r.asset_id,r.input_document_version_id,r.display_label,
      r.expected_page_count,r.inclusion_reason
    from manifest_items_raw r
  ),
  manifests as materialized (
    select m.chunk_id,m.document_version_id,
      jsonb_agg(jsonb_build_object('ordinal',m.ordinal,'input_type',m.input_type,
        'source_entity_type',m.source_entity_type,'source_entity_id',m.source_entity_id,
        'source_revision',m.source_revision,'document_asset_id',m.asset_id,
        'input_document_version_id',m.input_document_version_id,'display_label',m.display_label,
        'expected_page_count',m.expected_page_count,'inclusion_reason',m.inclusion_reason,
        'source_chunk_key',encode(digest(concat_ws('|',m.document_version_id::text,
          m.ordinal::text,m.input_type,m.source_entity_type,m.source_entity_id::text,
          m.source_revision),'sha256'),'hex'))
        order by m.ordinal,m.source_entity_id) manifest_json
    from manifest_items m group by m.chunk_id,m.document_version_id
  ),
  version_updates as (
    update public.invoice_document_versions v
    set manifest_json=m.manifest_json,manifest_hash=encode(digest(m.manifest_json::text,'sha256'),'hex'),
      status='WAITING_FOR_INPUTS',
      expected_page_count=(select sum(coalesce(x.expected_page_count,0)) from manifest_items x where x.chunk_id=m.chunk_id)
    from manifests m where v.id=m.document_version_id returning v.id
  ),
  core_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,status,priority,run_after_utc,payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select l.operation_id,
      case when l.entity_type='INVOICE' then 'INVOICE_CORE_RENDER' else 'SOURCE_RENDER' end,
      'RENDER',
      encode(digest(concat_ws('|',
        case when l.entity_type='INVOICE' then 'INVOICE_CORE_RENDER'
          else 'SOURCE_RENDER' end,l.resolved_document_version_id::text,
        '0',mi.input_type,mi.source_revision,
        case when l.entity_type='TIMESHEET' then 'timesheet-professional-v2'
          else (select template_version from public.invoice_document_versions v
            where v.id=l.resolved_document_version_id) end,'1'),'sha256'),'hex'),
      0,l.entity_type,l.entity_id,l.resolved_document_version_id,'QUEUED',l.priority,v_now,
      jsonb_build_object('render_kind',case when l.entity_type='INVOICE' then 'INVOICE_CORE' else 'ELECTRONIC_TIMESHEET' end,
        'template_version',case when l.entity_type='TIMESHEET'
          then 'timesheet-professional-v2'
          else (select template_version from public.invoice_document_versions v
            where v.id=l.resolved_document_version_id) end,
        'source_chunk_key',encode(digest(concat_ws('|',l.resolved_document_version_id::text,
          '0',case when l.entity_type='INVOICE' then 'INVOICE_CORE' else 'ELECTRONIC_TIMESHEET' end,
          l.entity_type,l.entity_id::text,
          (select source_revision from public.invoice_document_versions v
            where v.id=l.resolved_document_version_id)),'sha256'),'hex')),
      o.control_version,v_now,v_now
    from linked l
    join manifest_items mi on mi.chunk_id=l.id and mi.ordinal=0
    join public.invoice_operations o on o.id=l.operation_id
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing returning id,operation_id
  ),
  source_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,
      entity_type,entity_id,document_version_id,status,priority,run_after_utc,payload_json,
      operation_control_version,created_at_utc,updated_at_utc)
    select l.operation_id,'SOURCE_RENDER','RENDER',
      encode(digest(concat_ws('|','SOURCE_RENDER',m.document_version_id::text,
        m.ordinal::text,m.input_type,m.source_revision,
        case when m.input_type='ELECTRONIC_TIMESHEET'
          then 'timesheet-professional-v2'
          else (select template_version from public.invoice_document_versions v
            where v.id=l.resolved_document_version_id) end,'1'),'sha256'),'hex'),
      m.ordinal,m.source_entity_type,
      m.source_entity_id,l.resolved_document_version_id,'QUEUED',l.priority,v_now,
      jsonb_build_object('render_kind',m.input_type,'source_revision',m.source_revision,
        'source_chunk_key',encode(digest(concat_ws('|',m.document_version_id::text,
          m.ordinal::text,m.input_type,m.source_entity_type,m.source_entity_id::text,
          m.source_revision),'sha256'),'hex'),
        'template_version',case when m.input_type='ELECTRONIC_TIMESHEET'
          then 'timesheet-professional-v2'
          else (select template_version from public.invoice_document_versions v
            where v.id=l.resolved_document_version_id) end),
      o.control_version,v_now,v_now
    from linked l join manifest_items m on m.chunk_id=l.id
    join public.invoice_operations o on o.id=l.operation_id
    where m.ordinal>0 and m.input_type not in('ASSET','ATTACHMENT_INDEX')
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key)
    do update set priority=greatest(
      public.invoice_operation_chunks.priority,excluded.priority),
      updated_at_utc=excluded.updated_at_utc
    returning id,operation_id
  ),
  asset_chunks as (
    select null::uuid id,null::uuid operation_id,
      null::uuid document_asset_id
    where false
  ),
  asset_owner_update as (
    update public.invoice_document_assets a
    set operation_id=c.operation_id,status='INSPECTING',updated_at_utc=v_now
    from asset_chunks c
    where a.id=c.document_asset_id and a.status='DISCOVERED'
    returning a.id
  ),
  attachment_metadata as materialized (
    select m.chunk_id,m.document_version_id,m.ordinal,
      coalesce(
        (select ts.candidate_name
         from public.v_timesheets_summary_base ts
         where ts.timesheet_id=case
           when m.source_entity_type in('TIMESHEET','MANUAL_TIMESHEET')
             then m.source_entity_id
           when m.source_entity_type='TIMESHEET_EVIDENCE'
             then(select te.timesheet_id from public.timesheet_evidence te
                  where te.id=m.source_entity_id limit 1)
         end limit 1),
        (select nullif(r.value->>'worker','')
         from public.invoice_document_versions dv
         cross join lateral jsonb_array_elements(
           coalesce(dv.snapshot_json->'supporting_sources','[]'::jsonb)) s(value)
         cross join lateral jsonb_array_elements(
           coalesce(s.value#>'{render_model,rows}','[]'::jsonb)) r(value)
         where dv.id=m.document_version_id
           and s.value->>'import_id'=m.source_entity_id::text
           and nullif(r.value->>'worker','') is not null
         limit 1),
        (select coalesce(nullif(r.value->>'worker_name',''),
                         nullif(r.value->>'staff_name',''))
         from public.invoice_hr_source_rows hr
         cross join lateral jsonb_array_elements(
           coalesce(hr.rows_json,'[]'::jsonb)) r(value)
         where hr.import_id=m.source_entity_id
         limit 1)
      ) worker,
      coalesce(
        (select ts.week_ending_date::text
         from public.v_timesheets_summary_base ts
         where ts.timesheet_id=case
           when m.source_entity_type in('TIMESHEET','MANUAL_TIMESHEET')
             then m.source_entity_id
           when m.source_entity_type='TIMESHEET_EVIDENCE'
             then(select te.timesheet_id from public.timesheet_evidence te
                  where te.id=m.source_entity_id limit 1)
         end limit 1),
        (select nullif(r.value->>'shift_date','')
         from public.invoice_document_versions dv
         cross join lateral jsonb_array_elements(
           coalesce(dv.snapshot_json->'supporting_sources','[]'::jsonb)) s(value)
         cross join lateral jsonb_array_elements(
           coalesce(s.value#>'{render_model,rows}','[]'::jsonb)) r(value)
         where dv.id=m.document_version_id
           and s.value->>'import_id'=m.source_entity_id::text
           and nullif(r.value->>'shift_date','') is not null
         order by r.value->>'shift_date'
         limit 1),
        (select coalesce(nullif(r.value->>'work_date',''),
                         nullif(r.value->>'date_raw',''))
         from public.invoice_hr_source_rows hr
         cross join lateral jsonb_array_elements(
           coalesce(hr.rows_json,'[]'::jsonb)) r(value)
         where hr.import_id=m.source_entity_id
         order by coalesce(r.value->>'work_date',r.value->>'date_raw')
         limit 1)
      ) week_or_date,
      coalesce(
        (select nullif(r.value->>'booking_reference','')
         from public.invoice_document_versions dv
         cross join lateral jsonb_array_elements(
           coalesce(dv.snapshot_json->'supporting_sources','[]'::jsonb)) s(value)
         cross join lateral jsonb_array_elements(
           coalesce(s.value#>'{render_model,rows}','[]'::jsonb)) r(value)
         where dv.id=m.document_version_id
           and s.value->>'import_id'=m.source_entity_id::text
           and nullif(r.value->>'booking_reference','') is not null
         limit 1),
        (select coalesce(nullif(r.value->>'reference',''),
                         nullif(r.value->>'ref_num',''),
                         nullif(r.value->>'unique_id',''))
         from public.invoice_hr_source_rows hr
         cross join lateral jsonb_array_elements(
           coalesce(hr.rows_json,'[]'::jsonb)) r(value)
         where hr.import_id=m.source_entity_id
         limit 1),
        case when m.source_entity_type='TIMESHEET_EVIDENCE'
          then m.display_label end
      ) reference
    from manifest_items m
  ),
  input_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,document_asset_id,status,priority,run_after_utc,payload_json,
      result_json,error_json,expected_page_count,actual_page_count,expected_byte_count,actual_byte_count,
      operation_control_version,created_at_utc,updated_at_utc)
    select l.operation_id,'DOCUMENT_INPUT','DEPENDENCY',
      encode(digest(concat_ws('|','DOCUMENT_INPUT',m.document_version_id::text,
        m.ordinal::text,m.input_type,m.source_revision,
        coalesce(m.asset_id::text,m.input_document_version_id::text,
          m.source_entity_id::text),'1'),'sha256'),'hex'),
      m.ordinal,m.source_entity_type,m.source_entity_id,
      l.resolved_document_version_id,m.asset_id,
      case when m.input_type='ASSET' and a.status='READY' then 'COMPLETE'
        when m.input_type='ASSET' and m.asset_id is null then 'BLOCKED'
        when m.input_type='ASSET' and a.status in(
          'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED') then 'BLOCKED'
        when m.input_type='ASSET' and not coalesce(ax.asset_operation_active,false)
          then 'BLOCKED'
        else 'WAITING' end,
      l.priority,v_now,
      jsonb_build_object('ordinal',m.ordinal,'input_type',m.input_type,
        'display_label',m.display_label,
        'worker',am.worker,'week_or_date',am.week_or_date,
        'reference',am.reference,
        'source_revision',m.source_revision,'source_entity_type',m.source_entity_type,
        'source_entity_id',m.source_entity_id,
        'source_chunk_key',encode(digest(concat_ws('|',m.document_version_id::text,
          m.ordinal::text,m.input_type,m.source_entity_type,m.source_entity_id::text,
          m.source_revision),'sha256'),'hex')),
      case when m.input_type='ASSET' and a.status='READY' then jsonb_build_object(
        'r2_key',a.normalised_r2_key,'parts',a.normalised_manifest_json,
        'sha256',a.normalised_sha256,
        'normalised_manifest_hash',a.normalised_manifest_hash,
        'size_bytes',a.normalised_size_bytes,
        'page_count',a.normalised_page_count,'source_revision',m.source_revision,
        'document_asset_id',a.id) end,
      case when m.input_type='ASSET' and a.status in(
        'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED')
        then jsonb_build_object('code','ASSET_DEPENDENCY_PERMANENT_FAILURE',
          'asset_status',a.status,'document_asset_id',a.id,'source_entity_id',m.source_entity_id)
        when m.input_type='ASSET' and m.asset_id is null
        then jsonb_build_object('code','ASSET_NOT_REGISTERED',
          'source_entity_id',m.source_entity_id,
          'source_revision',m.source_revision)
        when m.input_type='ASSET' and not coalesce(ax.asset_operation_active,false)
        then jsonb_build_object('code','ASSET_PREPARATION_NOT_STARTED',
          'document_asset_id',m.asset_id,'source_entity_id',m.source_entity_id,
          'source_revision',m.source_revision)
      end,
      m.expected_page_count,
      case when m.input_type='ASSET' and a.status='READY'
        then a.normalised_page_count end,
      case when m.input_type='ASSET' and a.status='READY'
        then a.normalised_size_bytes end,
      case when m.input_type='ASSET' and a.status='READY'
        then a.normalised_size_bytes end,
      o.control_version,v_now,v_now
    from linked l join manifest_items m on m.chunk_id=l.id
    left join attachment_metadata am on am.chunk_id=m.chunk_id
      and am.document_version_id=m.document_version_id
      and am.ordinal=m.ordinal
    left join public.invoice_document_assets a on a.id=m.asset_id
    left join assets ax on ax.chunk_id=l.id and ax.asset_id=m.asset_id
    join public.invoice_operations o on o.id=l.operation_id
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key)
    do update set
      status=case when excluded.status in('COMPLETE','BLOCKED') then excluded.status
        else invoice_operation_chunks.status end,
      result_json=coalesce(excluded.result_json,invoice_operation_chunks.result_json),
      error_json=coalesce(excluded.error_json,invoice_operation_chunks.error_json),
      actual_page_count=coalesce(excluded.actual_page_count,
        invoice_operation_chunks.actual_page_count),
      actual_byte_count=coalesce(excluded.actual_byte_count,
        invoice_operation_chunks.actual_byte_count)
      where invoice_operation_chunks.status not in('SUPERSEDED','CANCELLED')
    returning id
  ),
  advanced as (
    update public.invoice_operation_chunks c
    set document_version_id=l.resolved_document_version_id,phase='WAIT_FOR_INPUTS',status='WAITING',
      progress_json=jsonb_build_object('status_message','Waiting for document inputs',
        'manifest_items',(select jsonb_array_length(v.manifest_json) from public.invoice_document_versions v where v.id=l.resolved_document_version_id)),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from linked l where c.id=l.id
    returning c.id,c.status,c.phase,c.document_version_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'chunk_id',id,'status',status,'phase',phase,
    'document_version_id',document_version_id,'error',error_json)),'[]'::jsonb)
  into v_part
  from(
    select id,status,phase,document_version_id,null::jsonb error_json from advanced
    union all
    select id,status,phase,document_version_id,error_json from missing_versions
  ) outcomes;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- WAIT_FOR_INPUTS: dependencies only; no R2 polling.
  with recursive claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id from jsonb_array_elements(p_claims) x
    where x->>'phase'='WAIT_FOR_INPUTS'
  ),
  claim_scope as materialized (
    select c.id chunk_id,c.operation_id,c.document_version_id,c.priority,
      o.control_version,v.template_version,
      o.config_json->'processor_policy' processor_policy
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoice_operations o on o.id=c.operation_id
    join public.invoice_document_versions v on v.id=c.document_version_id
  ),
  current_graph as materialized (
    select g.*
    from private._invoice_current_chunks_batch(
      (select array_agg(operation_id) from claim_scope),null,null,10000) g
    where g.replacement_chain_status='VALID'
  ),
  current_inputs as materialized (
    select d.*
    from current_graph g
    join public.invoice_operation_chunks d on d.id=g.current_chunk_id
    where d.chunk_type='DOCUMENT_INPUT'
  ),
  attachment_index_ready as materialized (
    select s.*,
      index_input.id index_input_chunk_id,index_input.sequence_no index_ordinal,
      index_input.payload_json->>'source_chunk_key' source_chunk_key,
      index_input.payload_json->>'display_label' index_display_label,
      index_input.payload_json->>'input_type' index_input_type,
      index_input.payload_json->>'source_revision' index_source_revision,
      index_input.payload_json->>'snapshot_hash' snapshot_hash,
      count(other.id)::integer supporting_input_count,
      coalesce(sum(other.actual_page_count),0)::integer supporting_pages,
      coalesce(sum(other.actual_byte_count),0)::bigint supporting_bytes,
      coalesce(max(other.actual_page_count) filter(
        where other.payload_json->>'input_type'='INVOICE_CORE'),0)::integer
        core_page_count,
      jsonb_agg(jsonb_build_object(
        'input_chunk_id',other.id,'ordinal',other.sequence_no,
        'logical_source_key',other.payload_json->>'source_chunk_key',
        'label',other.payload_json->>'display_label',
        'input_type',other.payload_json->>'input_type',
        'worker',other.payload_json->>'worker',
        'week_or_date',other.payload_json->>'week_or_date',
        'reference',other.payload_json->>'reference',
        'page_count',other.actual_page_count)
        order by other.sequence_no,other.id)
        filter(where other.id is not null
          and other.payload_json->>'input_type' not in(
            'INVOICE_CORE','ATTACHMENT_INDEX','SECTION_SEPARATOR')) attachments,
      coalesce((
        select jsonb_agg(section.row_json order by section.ordinal,
          section.physical_part_no,section.input_chunk_id)
        from(
          select stream_input.sequence_no ordinal,
            stream_input.id input_chunk_id,
            part.ordinality::integer physical_part_no,
            jsonb_build_object(
              'input_chunk_id',stream_input.id,
              'ordinal',stream_input.sequence_no,
              'physical_part_no',part.ordinality,
              'logical_source_key',
                stream_input.payload_json->>'source_chunk_key',
              'input_type',stream_input.payload_json->>'input_type',
              'label',stream_input.payload_json->>'display_label',
              'worker',stream_input.payload_json->>'worker',
              'week_or_date',stream_input.payload_json->>'week_or_date',
              'reference',stream_input.payload_json->>'reference',
              'page_count',case
                when stream_input.payload_json->>'input_type'=
                    'ATTACHMENT_INDEX'
                  then 0
                when coalesce(part.value->>'page_count','')~'^[1-9][0-9]*$'
                  then(part.value->>'page_count')::integer
                else stream_input.actual_page_count end,
              'is_displayed_attachment',
                stream_input.payload_json->>'input_type' not in(
                  'INVOICE_CORE','ATTACHMENT_INDEX','SECTION_SEPARATOR'),
              'is_separator',
                stream_input.payload_json->>'input_type'='SECTION_SEPARATOR')
              row_json
          from current_inputs stream_input
          cross join lateral jsonb_array_elements(
            case
              when stream_input.payload_json->>'input_type'='ATTACHMENT_INDEX'
                then jsonb_build_array(jsonb_build_object('page_count',0))
              when jsonb_typeof(stream_input.result_json->'parts')='array'
                  and jsonb_array_length(stream_input.result_json->'parts')>0
                then stream_input.result_json->'parts'
              else jsonb_build_array(jsonb_build_object(
                'page_count',stream_input.actual_page_count))
            end) with ordinality part(value,ordinality)
          where stream_input.operation_id=s.operation_id
            and stream_input.document_version_id=s.document_version_id
            and(
              stream_input.id=index_input.id
              or stream_input.status='COMPLETE')
        ) section
      ),'[]'::jsonb) pagination_stream
    from claim_scope s
    join current_inputs index_input
      on index_input.operation_id=s.operation_id
      and index_input.document_version_id=s.document_version_id
      and index_input.payload_json->>'input_type'='ATTACHMENT_INDEX'
      and index_input.status='WAITING'
    left join current_inputs other
      on other.operation_id=s.operation_id
      and other.document_version_id=s.document_version_id
      and other.id<>index_input.id
    group by s.chunk_id,s.operation_id,s.document_version_id,s.priority,
      s.control_version,s.template_version,s.processor_policy,
      index_input.id,index_input.sequence_no,index_input.payload_json
    having count(other.id)>0 and bool_and(other.status='COMPLETE'
      and coalesce(other.actual_page_count,0)>0
      and coalesce(other.actual_byte_count,0)>0)
  ),
  attachment_index_measure as (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,plan_generation,sequence_no,
      entity_type,entity_id,document_version_id,status,priority,run_after_utc,
      payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select a.operation_id,'SOURCE_RENDER','ATTACHMENT_INDEX_MEASURE',
      encode(digest(concat_ws('|','ATTACHMENT_INDEX',a.document_version_id::text,
        a.index_ordinal::text,a.source_chunk_key,'MEASURE','1',
        a.template_version),'sha256'),'hex'),
      1,a.index_ordinal,'DOCUMENT',a.document_version_id,
      a.document_version_id,'QUEUED',a.priority,v_now,
      jsonb_build_object(
        'render_kind','ATTACHMENT_INDEX','layout_phase','MEASURE',
        'layout_pass',1,'max_layout_passes',
          (a.processor_policy#>>
            '{attachment_index,max_render_passes}')::integer,
        'template_version',a.template_version,
        'source_chunk_key',a.source_chunk_key,
        'source_revision',a.index_source_revision,
        'presentation_model_schema_version',
          'ATTACHMENT_INDEX_PRESENTATION_V1',
        'presentation_model_hash',encode(digest(jsonb_build_object(
          'display_label',a.index_display_label,
          'input_type',a.index_input_type,
          'manifest_ordinal',a.index_ordinal)::text,'sha256'),'hex'),
        'snapshot_hash',a.snapshot_hash,
        'core_page_count',a.core_page_count,
        'supporting_input_count',a.supporting_input_count,
        'supporting_pages',a.supporting_pages,
        'supporting_bytes',a.supporting_bytes,
        'display_rows',coalesce(a.attachments,'[]'::jsonb),
        'attachments',coalesce(a.attachments,'[]'::jsonb),
        'pagination_stream',coalesce(a.pagination_stream,'[]'::jsonb),
        'determinism',jsonb_build_object(
          'policy_version',a.processor_policy->>'version',
          'layout_version',a.processor_policy#>>
            '{attachment_index,layout_version}',
          'renderer_version',a.processor_policy#>>
            '{attachment_index,renderer_version}',
          'template_version',a.processor_policy#>>
            '{attachment_index,template_version}',
          'css_font_identity',a.processor_policy#>>
            '{attachment_index,css_font_identity}',
          'page_geometry',a.processor_policy#>>
            '{attachment_index,page_geometry}',
          'locale_identity',a.processor_policy#>>
            '{attachment_index,locale_identity}')),
      a.control_version,v_now,v_now
    from attachment_index_ready a
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key)
      do nothing
    returning id
  ),
  state as materialized (
    select c.id chunk_id,c.operation_id,c.document_version_id,
      count(d.id) dependencies,count(d.id) filter(where d.status='COMPLETE') ready,
      count(d.id) filter(where d.status in ('FAILED','DEAD_LETTER','BLOCKED')
        or(d.status='COMPLETE'
          and nullif(d.result_json->>'r2_key','') is null
          and jsonb_array_length(case
            when jsonb_typeof(d.result_json->'parts')='array'
              then d.result_json->'parts' else '[]'::jsonb end)=0)) failed
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join current_inputs d
      on d.operation_id=c.operation_id
      and d.document_version_id=c.document_version_id
    group by c.id,c.operation_id,c.document_version_id
  ),
  blocked as (
    update public.invoice_operation_chunks c set status='BLOCKED',phase='BLOCKED',
      error_json=jsonb_build_object('code','DOCUMENT_INPUT_FAILED',
        'failed_inputs',(select jsonb_agg(jsonb_build_object('chunk_id',d.id,'entity_id',d.entity_id,'error',d.error_json))
                         from current_inputs d where d.operation_id=c.operation_id
                           and d.document_version_id=c.document_version_id
                           and d.chunk_type='DOCUMENT_INPUT' and d.status in ('FAILED','DEAD_LETTER','BLOCKED'))),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from state s where c.id=s.chunk_id and s.failed>0 returning c.id
  ),
  ready_plans as materialized (
    select s.* from state s where s.dependencies>0 and s.dependencies=s.ready and s.failed=0
  ),
  physical_inputs as materialized (
    select d.id,d.operation_id,d.document_version_id,d.sequence_no,
      d.payload_json||jsonb_build_object(
        'physical_part_no',p.ordinality,
        'logical_input_chunk_id',d.id) payload_json,
      coalesce(nullif(p.value->>'r2_key',''),nullif(p.value->>'key',''))
        physical_r2_key,
      coalesce(nullif(p.value->>'sha256',''),
        nullif(d.result_json->>'sha256','')) physical_sha256,
      case when coalesce(p.value->>'page_count','')~'^[1-9][0-9]*$'
        then(p.value->>'page_count')::integer
        when jsonb_array_length(case
          when jsonb_typeof(d.result_json->'parts')='array'
            then d.result_json->'parts' else '[]'::jsonb end)=0
          then d.actual_page_count end physical_page_count,
      case when coalesce(p.value->>'size_bytes','')~'^[1-9][0-9]*$'
        then(p.value->>'size_bytes')::bigint
        when jsonb_array_length(case
          when jsonb_typeof(d.result_json->'parts')='array'
            then d.result_json->'parts' else '[]'::jsonb end)=0
          then d.actual_byte_count end physical_byte_count,
      p.ordinality::integer physical_part_no,
      d.result_json||jsonb_build_object(
        'r2_key',coalesce(nullif(p.value->>'r2_key',''),
          nullif(p.value->>'key','')),
        'sha256',coalesce(nullif(p.value->>'sha256',''),
          nullif(d.result_json->>'sha256','')))
        result_json
    from ready_plans r
    join current_inputs d
      on d.operation_id=r.operation_id and d.chunk_type='DOCUMENT_INPUT'
      and d.document_version_id=r.document_version_id
      and d.status='COMPLETE'
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(d.result_json->'parts')='array'
          and jsonb_array_length(d.result_json->'parts')>0
        then d.result_json->'parts'
        else jsonb_build_array(jsonb_build_object(
          'r2_key',d.result_json->>'r2_key',
          'sha256',d.result_json->>'sha256',
          'page_count',d.actual_page_count,
          'size_bytes',d.actual_byte_count))
      end) with ordinality p(value,ordinality)
    where nullif(coalesce(p.value->>'r2_key',p.value->>'key'),'') is not null
      and coalesce(p.value->>'sha256',d.result_json->>'sha256','')<>''
  ),
  physical_receipt_inputs as materialized (
    select p.*,
      coalesce(nullif(p.payload_json->>'source_chunk_key',''),
        p.id::text) logical_source_key,
      p.sequence_no logical_manifest_ordinal,
      encode(digest(jsonb_build_object(
        'receipt_contract','ACTUAL_BYTES_OBJECT_RECEIPT_V3',
        'logical_source_key',coalesce(
          nullif(p.payload_json->>'source_chunk_key',''),p.id::text),
        'logical_manifest_ordinal',p.sequence_no,
        'physical_part_no',p.physical_part_no,
        'object_key',p.physical_r2_key,
        'stored_sha256',p.physical_sha256,
        'expected_page_count',p.physical_page_count,
        'expected_byte_count',p.physical_byte_count
      )::text,'sha256'),'hex') expected_physical_receipt
    from physical_inputs p
  ),
  logical_receipts as materialized (
    select p.operation_id,p.document_version_id,p.id logical_input_chunk_id,
      p.logical_source_key,p.logical_manifest_ordinal,
      count(*)::integer physical_part_count,
      encode(digest(jsonb_build_object(
        'receipt_contract','LOGICAL_SOURCE_RECEIPT_V3',
        'logical_source_key',p.logical_source_key,
        'logical_manifest_ordinal',p.logical_manifest_ordinal,
        'ordered_physical_receipts',string_agg(
          p.expected_physical_receipt,'||'
          order by p.physical_part_no)
      )::text,'sha256'),'hex') expected_logical_receipt
    from physical_receipt_inputs p
    group by p.operation_id,p.document_version_id,p.id,
      p.logical_source_key,p.logical_manifest_ordinal
  ),
  receipt_inputs as materialized (
    select p.*,l.expected_logical_receipt,l.physical_part_count
    from physical_receipt_inputs p
    join logical_receipts l
      on l.operation_id=p.operation_id
     and l.document_version_id=p.document_version_id
     and l.logical_input_chunk_id=p.id
  ),
  ranked_inputs as materialized (
    select d.*,
      d.physical_page_count actual_page_count,
      d.physical_byte_count actual_byte_count,
      row_number() over(partition by d.operation_id,d.document_version_id
        order by d.sequence_no,d.physical_part_no,d.id)::integer input_no,
      case when coalesce(d.result_json->>'decoded_estimate_bytes','') ~ '^[0-9]{1,18}$'
        then(d.result_json->>'decoded_estimate_bytes')::bigint
        else coalesce(d.physical_byte_count,0)*4 end decoded_bytes,
      (o.config_json->'processor_policy'
        #>>'{merge,max_inputs}')::integer max_inputs,
      (o.config_json->'processor_policy'
        #>>'{merge,max_pages}')::integer max_pages,
      (o.config_json->'processor_policy'
        #>>'{merge,max_input_bytes}')::bigint max_bytes,
      (o.config_json->'processor_policy'
        #>>'{merge,max_estimated_decoded_bytes}')::bigint max_decoded_bytes
    from receipt_inputs d
    join public.invoice_operations o on o.id=d.operation_id
  ),
  oversized_inputs as materialized (
    select r.*
    from ranked_inputs r
    where coalesce(r.actual_page_count,0)<=0
       or coalesce(r.actual_byte_count,0)<=0
       or coalesce(r.decoded_bytes,0)<=0
       or r.actual_page_count>r.max_pages
       or r.actual_byte_count>r.max_bytes
       or r.decoded_bytes>r.max_decoded_bytes
  ),
  oversized_plans as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',
        error_json=jsonb_build_object(
          'code','MERGE_INPUT_EXCEEDS_POLICY',
          'document_version_id',bad.document_version_id,
          'input_chunk_id',bad.id,
          'page_count',bad.actual_page_count,
          'size_bytes',bad.actual_byte_count,
          'decoded_estimate_bytes',bad.decoded_bytes),
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from (
      select distinct on(operation_id,document_version_id)
        operation_id,document_version_id,id,actual_page_count,
        actual_byte_count,decoded_bytes
      from oversized_inputs
      order by operation_id,document_version_id,input_no
    ) bad
    where c.operation_id=bad.operation_id
      and c.document_version_id=bad.document_version_id
      and c.chunk_type='DOCUMENT_PLAN'
      and c.status not in('COMPLETE','FAILED','DEAD_LETTER',
        'CANCELLED','SUPERSEDED')
    returning c.document_version_id
  ),
  oversized_versions as (
    update public.invoice_document_versions v
    set status='FAILED',
        error_json=jsonb_build_object('code','MERGE_INPUT_EXCEEDS_POLICY')
    where v.id in(select document_version_id from oversized_plans)
      and v.status<>'READY'
    returning v.id
  ),
  packable_inputs as materialized (
    select r.*
    from ranked_inputs r
    where not exists(
      select 1 from oversized_inputs bad
      where bad.operation_id=r.operation_id
        and bad.document_version_id=r.document_version_id)
  ),
  page_numbered_inputs as materialized (
    select r.operation_id,r.document_version_id,r.input_no,
      r.actual_page_count,r.payload_json->>'input_type' input_type,
      coalesce(sum(r.actual_page_count) over(
        partition by r.operation_id,r.document_version_id
        order by r.input_no
        rows between unbounded preceding and 1 preceding),0)::integer
        preceding_page_count
    from packable_inputs r
  ),
  page_numbering_policies as materialized (
    select numbered.operation_id,numbered.document_version_id,
      coalesce(jsonb_agg(
        numbered.preceding_page_count+page_offset
        order by numbered.preceding_page_count+page_offset)
        filter(where page_offset is not null),'[]'::jsonb)
        excluded_pages
    from page_numbered_inputs numbered
    left join lateral generate_series(
      1,case when numbered.input_type='ELECTRONIC_TIMESHEET'
        then numbered.actual_page_count else 0 end
    ) page_offset on true
    group by numbered.operation_id,numbered.document_version_id
  ),
  leaf_pack(
    operation_id,document_version_id,input_no,group_no,group_input_count,
    group_pages,group_bytes,group_decoded_bytes
  ) as (
    select d.operation_id,d.document_version_id,d.input_no,0,
      1,d.actual_page_count,d.actual_byte_count,d.decoded_bytes
    from packable_inputs d
    where d.input_no=1
    union all
    select n.operation_id,n.document_version_id,n.input_no,
      p.group_no+case when split.start_new then 1 else 0 end,
      case when split.start_new then 1 else p.group_input_count+1 end,
      case when split.start_new then n.actual_page_count
        else p.group_pages+n.actual_page_count end,
      case when split.start_new then n.actual_byte_count
        else p.group_bytes+n.actual_byte_count end,
      case when split.start_new then n.decoded_bytes
        else p.group_decoded_bytes+n.decoded_bytes end
    from leaf_pack p
    join packable_inputs n
      on n.operation_id=p.operation_id
      and n.document_version_id=p.document_version_id
      and n.input_no=p.input_no+1
    cross join lateral (
      select p.group_input_count+1>n.max_inputs
        or p.group_pages+n.actual_page_count>n.max_pages
        or p.group_bytes+n.actual_byte_count>n.max_bytes
        or p.group_decoded_bytes+n.decoded_bytes>n.max_decoded_bytes
        start_new
    ) split
  ),
  leaf_group_logical as materialized (
    select d.operation_id,d.document_version_id,p.group_no,
      d.logical_source_key,min(d.logical_manifest_ordinal) logical_ordinal,
      encode(digest(jsonb_build_object(
        'receipt_contract','LOGICAL_SOURCE_RECEIPT_V3',
        'logical_source_key',d.logical_source_key,
        'logical_manifest_ordinal',min(d.logical_manifest_ordinal),
        'ordered_physical_receipts',string_agg(
          d.expected_physical_receipt,'||'
          order by d.logical_manifest_ordinal,d.physical_part_no,d.id)
      )::text,'sha256'),'hex') expected_logical_receipt
    from packable_inputs d
    join leaf_pack p
      on p.operation_id=d.operation_id
     and p.document_version_id=d.document_version_id
     and p.input_no=d.input_no
    group by d.operation_id,d.document_version_id,p.group_no,
      d.logical_source_key
  ),
  leaf_group_roots as materialized (
    select groups.operation_id,groups.document_version_id,groups.group_no,
      jsonb_agg(jsonb_build_object(
        'logical_source_key',groups.logical_source_key,
        'logical_manifest_ordinal',groups.logical_manifest_ordinal,
        'physical_part_no',groups.physical_part_no,
        'physical_receipt',groups.expected_physical_receipt)
        order by groups.input_no) expected_physical_receipts,
      encode(digest(string_agg(groups.expected_physical_receipt,'||'
        order by groups.input_no),'sha256'),'hex')
        expected_physical_receipt_root,
      encode(digest(string_agg(groups.expected_physical_receipt,'||'
        order by groups.input_no),'sha256'),'hex')
        expected_child_receipt_hash,
      (
        select encode(digest(string_agg(
          logical.expected_logical_receipt,'||'
          order by logical.logical_ordinal,logical.logical_source_key),
          'sha256'),'hex')
        from leaf_group_logical logical
        where logical.operation_id=groups.operation_id
          and logical.document_version_id=groups.document_version_id
          and logical.group_no=groups.group_no
      ) expected_logical_receipt_root
    from (
      select d.operation_id,d.document_version_id,p.group_no,d.input_no,
        d.logical_source_key,d.logical_manifest_ordinal,d.physical_part_no,
        d.expected_physical_receipt
      from packable_inputs d
      join leaf_pack p
        on p.operation_id=d.operation_id
       and p.document_version_id=d.document_version_id
       and p.input_no=d.input_no
    ) groups
    group by groups.operation_id,groups.document_version_id,groups.group_no
  ),
  leaf_groups as materialized (
    select d.operation_id,d.document_version_id,p.group_no,
      jsonb_agg(jsonb_build_object('input_chunk_id',d.id,
        'input_order',d.input_no,'ordinal',d.sequence_no,
        'physical_part_no',d.physical_part_no,
        'r2_key',d.physical_r2_key,'sha256',d.physical_sha256,
        'page_count',d.actual_page_count,'size_bytes',d.actual_byte_count,
        'logical_source_key',d.logical_source_key,
        'logical_manifest_ordinal',d.logical_manifest_ordinal,
        'expected_logical_receipt',d.expected_logical_receipt,
        'expected_physical_receipt',d.expected_physical_receipt,
        'decoded_estimate_bytes',d.result_json->>'decoded_estimate_bytes')
        order by d.sequence_no,d.physical_part_no,d.id) inputs,
      encode(digest(string_agg(concat_ws('|',d.input_no::text,d.id::text,
        d.physical_r2_key,d.physical_sha256,d.actual_page_count::text,
        d.actual_byte_count::text,''),'||'
        order by d.sequence_no,d.physical_part_no,d.id),
        'sha256'),'hex') ordered_input_hash,
      roots.expected_child_receipt_hash,
      roots.expected_logical_receipt_root,
      roots.expected_physical_receipt_root,
      roots.expected_physical_receipts,
      sum(coalesce(d.actual_page_count,0))::integer expected_pages,
      sum(coalesce(d.actual_byte_count,0))::bigint expected_bytes
    from packable_inputs d
    join leaf_pack p
      on p.operation_id=d.operation_id
      and p.document_version_id=d.document_version_id
      and p.input_no=d.input_no
    join leaf_group_roots roots
      on roots.operation_id=d.operation_id
     and roots.document_version_id=d.document_version_id
     and roots.group_no=p.group_no
    group by d.operation_id,d.document_version_id,p.group_no,
      roots.expected_child_receipt_hash,
      roots.expected_logical_receipt_root,
      roots.expected_physical_receipt_root,
      roots.expected_physical_receipts
    having count(*)<=max(d.max_inputs)
      and sum(d.actual_page_count)<=max(d.max_pages)
      and sum(d.actual_byte_count)<=max(d.max_bytes)
      and sum(d.decoded_bytes)<=max(d.max_decoded_bytes)
  ),
  independent_expectations as (
    update public.invoice_document_versions v
    set expected_page_count=e.expected_pages,
      status='ASSEMBLING',
      error_json=null
    from (
      select r.document_version_id,sum(r.actual_page_count)::integer expected_pages,
        encode(digest(string_agg(concat_ws('|',r.sequence_no::text,
          r.payload_json->>'source_chunk_key',r.physical_part_no::text,
          r.physical_sha256,r.actual_page_count::text),'||'
          order by r.sequence_no,r.physical_part_no),'sha256'),'hex')
          coverage_hash
      from packable_inputs r group by r.document_version_id
    ) e
    where v.id=e.document_version_id
    returning v.id,v.expected_page_count
  ),
  merge_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,plan_generation,sequence_no,level_no,
      entity_type,entity_id,document_version_id,status,priority,run_after_utc,payload_json,
      expected_page_count,expected_byte_count,operation_control_version,created_at_utc,updated_at_utc)
    select g.operation_id,'PDF_MERGE','MERGE',
      encode(digest(concat_ws('|','PDF_MERGE',g.document_version_id::text,
        '0',g.group_no::text,g.ordered_input_hash,pg.plan_generation::text,
        case when (select count(*) from leaf_groups all_groups
          where all_groups.operation_id=g.operation_id
            and all_groups.document_version_id=g.document_version_id)=1
          and (select entity_type from public.invoice_document_versions
            where id=g.document_version_id)='INVOICE'
          then 'FINAL_MERGE_SELECTIVE_V2' else 'NONE' end,
        coalesce(numbering.excluded_pages,'[]'::jsonb)::text),
        'sha256'),'hex'),
      pg.plan_generation,g.group_no,0,'DOCUMENT',
      g.document_version_id,g.document_version_id,'QUEUED',550,v_now,
      jsonb_build_object('level',0,'inputs',g.inputs,
        'fan_in',jsonb_array_length(g.inputs),
        'ordered_input_hash',g.ordered_input_hash,
        'expected_child_receipt_hash',g.expected_child_receipt_hash,
        'expected_logical_receipt_root',g.expected_logical_receipt_root,
        'expected_physical_receipt_root',g.expected_physical_receipt_root,
        'expected_physical_receipts',g.expected_physical_receipts,
        'receipt_contract','ACTUAL_BYTES_MERGE_RECEIPT_V3',
        'plan_generation',pg.plan_generation,
        'apply_final_page_numbers',
          (select count(*) from leaf_groups all_groups
             where all_groups.operation_id=g.operation_id
               and all_groups.document_version_id=g.document_version_id)=1
          and (select entity_type from public.invoice_document_versions
            where id=g.document_version_id)='INVOICE',
        'page_numbering_contract',case
          when (select count(*) from leaf_groups all_groups
             where all_groups.operation_id=g.operation_id
               and all_groups.document_version_id=g.document_version_id)=1
            and (select entity_type from public.invoice_document_versions
              where id=g.document_version_id)='INVOICE'
          then 'FINAL_MERGE_SELECTIVE_V2' else null end,
        'page_numbering_excluded_pages',case
          when (select count(*) from leaf_groups all_groups
             where all_groups.operation_id=g.operation_id
               and all_groups.document_version_id=g.document_version_id)=1
            and (select entity_type from public.invoice_document_versions
              where id=g.document_version_id)='INVOICE'
          then coalesce(numbering.excluded_pages,'[]'::jsonb)
          else '[]'::jsonb end,
        'document_entity_type',(select entity_type
          from public.invoice_document_versions where id=g.document_version_id),
        'document_version_id',g.document_version_id),
      g.expected_pages,g.expected_bytes,o.control_version,v_now,v_now
    from leaf_groups g
    join public.invoice_operations o on o.id=g.operation_id
    left join page_numbering_policies numbering
      on numbering.operation_id=g.operation_id
     and numbering.document_version_id=g.document_version_id
    cross join lateral (
      select coalesce((
        select prior.plan_generation
        from public.invoice_operation_chunks prior
        where prior.operation_id=g.operation_id and prior.chunk_type='PDF_MERGE'
          and prior.document_version_id=g.document_version_id
          and prior.level_no=0 and prior.sequence_no=g.group_no
          and prior.payload_json->>'ordered_input_hash'=g.ordered_input_hash
        order by prior.created_at_utc desc,prior.id desc limit 1),
        1+coalesce((select max(prior.plan_generation)
          from public.invoice_operation_chunks prior
          where prior.operation_id=g.operation_id and prior.chunk_type='PDF_MERGE'
            and prior.document_version_id=g.document_version_id
            and prior.level_no=0 and prior.sequence_no=g.group_no),0))
        plan_generation
    ) pg
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key)
    do update set priority=greatest(
      public.invoice_operation_chunks.priority,excluded.priority),
      updated_at_utc=excluded.updated_at_utc
    returning id,operation_id,document_version_id,level_no,sequence_no,plan_generation
  ),
  replaced_leaf_merges as (
    update public.invoice_operation_chunks stale
    set status='SUPERSEDED',phase='SUPERSEDED',completed_at_utc=v_now,
        failed_at_utc=null,
        replaced_by_chunk_id=fresh.id,replacement_required=true,
        result_json=coalesce(stale.result_json,'{}'::jsonb)
          ||jsonb_build_object('replacement_chunk_id',fresh.id),
        error_json=jsonb_build_object(
          'code','REPLACED_AFTER_UPSTREAM_RETRY',
          'replacement_chunk_id',fresh.id),
        updated_at_utc=v_now
    from merge_chunks fresh
    where stale.operation_id=fresh.operation_id
      and stale.chunk_type='PDF_MERGE'
      and stale.document_version_id=fresh.document_version_id
      and stale.level_no=fresh.level_no
      and stale.sequence_no=fresh.sequence_no
      and stale.id<>fresh.id and stale.status='BLOCKED'
      and stale.error_json->>'code'='UPSTREAM_RETRY_INVALIDATED'
    returning stale.id
  ),
  advanced as (
    update public.invoice_operation_chunks c
    set phase=case when s.failed>0 then 'BLOCKED'
                   when s.dependencies=s.ready and s.dependencies>0 then 'WAIT_FOR_MERGE'
                   else 'WAIT_FOR_INPUTS' end,
        status=case when s.failed>0 then 'BLOCKED' else 'WAITING' end,
        progress_json=jsonb_build_object('status_message',
          case when s.dependencies=s.ready and s.dependencies>0 then 'Inputs ready; merge queued' else 'Waiting for inputs' end,
          'inputs_ready',s.ready,'inputs_total',s.dependencies),
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from state s where c.id=s.chunk_id
    returning c.id,c.status,c.phase,c.progress_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,
    'progress',progress_json)),'[]'::jsonb) into v_part from advanced;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- WAIT_FOR_MERGE seeds one bounded level at a time.
  with recursive claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id from jsonb_array_elements(p_claims) x
    where x->>'phase'='WAIT_FOR_MERGE'
  ),
  claim_operations as materialized (
    select distinct c.operation_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
  ),
  current_graph as materialized (
    select g.*
    from private._invoice_current_chunks_batch(
      (select array_agg(operation_id) from claim_operations),
      null,null,10000) g
    where g.replacement_chain_status='VALID'
  ),
  current_merges as materialized (
    select m.*
    from current_graph g
    join public.invoice_operation_chunks m on m.id=g.current_chunk_id
    where m.chunk_type='PDF_MERGE'
  ),
  current_inputs as materialized (
    select d.*
    from current_graph g
    join public.invoice_operation_chunks d on d.id=g.current_chunk_id
    where d.chunk_type='DOCUMENT_INPUT'
  ),
  page_numbered_inputs as materialized (
    select d.operation_id,d.document_version_id,d.sequence_no,
      d.actual_page_count,d.payload_json->>'input_type' input_type,
      coalesce(sum(d.actual_page_count) over(
        partition by d.operation_id,d.document_version_id
        order by d.sequence_no,d.id
        rows between unbounded preceding and 1 preceding),0)::integer
        preceding_page_count
    from current_inputs d
    where d.status='COMPLETE'
  ),
  page_numbering_policies as materialized (
    select numbered.operation_id,numbered.document_version_id,
      coalesce(jsonb_agg(
        numbered.preceding_page_count+page_offset
        order by numbered.preceding_page_count+page_offset)
        filter(where page_offset is not null),'[]'::jsonb)
        excluded_pages
    from page_numbered_inputs numbered
    left join lateral generate_series(
      1,case when numbered.input_type='ELECTRONIC_TIMESHEET'
        then numbered.actual_page_count else 0 end
    ) page_offset on true
    group by numbered.operation_id,numbered.document_version_id
  ),
  plan_state as materialized (
    select c.id chunk_id,c.operation_id,c.document_version_id,
      coalesce(max(m.level_no),0) current_level,
      count(m.id) filter(where m.level_no=(select max(m2.level_no)
        from current_merges m2 where m2.operation_id=c.operation_id
          and m2.document_version_id=c.document_version_id)) level_count,
      count(m.id) filter(where m.level_no=(select max(m2.level_no)
        from current_merges m2 where m2.operation_id=c.operation_id
          and m2.document_version_id=c.document_version_id)
        and m.status='COMPLETE') complete_count,
      count(m.id) filter(where m.status in ('FAILED','DEAD_LETTER','BLOCKED')) failed_count
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join current_merges m on m.operation_id=c.operation_id
      and m.document_version_id=c.document_version_id
      and m.chunk_type='PDF_MERGE'
    group by c.id,c.operation_id,c.document_version_id
  ),
  ranked_merges as materialized (
    select m.*,ps.current_level,
      row_number() over(partition by m.operation_id,m.document_version_id
        order by m.sequence_no,m.id)::integer input_no,
      coalesce(m.actual_byte_count,0)*4 decoded_bytes,
      (o.config_json->'processor_policy'
        #>>'{merge,max_inputs}')::integer max_inputs,
      (o.config_json->'processor_policy'
        #>>'{merge,max_pages}')::integer max_pages,
      (o.config_json->'processor_policy'
        #>>'{merge,max_input_bytes}')::bigint max_bytes,
      (o.config_json->'processor_policy'
        #>>'{merge,max_estimated_decoded_bytes}')::bigint max_decoded_bytes
    from plan_state ps join current_merges m on m.operation_id=ps.operation_id
      and m.document_version_id=ps.document_version_id
      and m.chunk_type='PDF_MERGE' and m.level_no=ps.current_level and m.status='COMPLETE'
    join public.invoice_operations o on o.id=m.operation_id
    where ps.failed_count=0 and ps.level_count=ps.complete_count and ps.level_count>1
  ),
  merge_pack(
    operation_id,document_version_id,input_no,group_no,group_input_count,
    group_pages,group_bytes,group_decoded_bytes
  ) as (
    select m.operation_id,m.document_version_id,m.input_no,0,
      1,m.actual_page_count,m.actual_byte_count,m.decoded_bytes
    from ranked_merges m
    where m.input_no=1
    union all
    select n.operation_id,n.document_version_id,n.input_no,
      p.group_no+case when split.start_new then 1 else 0 end,
      case when split.start_new then 1 else p.group_input_count+1 end,
      case when split.start_new then n.actual_page_count
        else p.group_pages+n.actual_page_count end,
      case when split.start_new then n.actual_byte_count
        else p.group_bytes+n.actual_byte_count end,
      case when split.start_new then n.decoded_bytes
        else p.group_decoded_bytes+n.decoded_bytes end
    from merge_pack p
    join ranked_merges n
      on n.operation_id=p.operation_id
      and n.document_version_id=p.document_version_id
      and n.input_no=p.input_no+1
    cross join lateral (
      select p.group_input_count+1>n.max_inputs
        or p.group_pages+n.actual_page_count>n.max_pages
        or p.group_bytes+n.actual_byte_count>n.max_bytes
        or p.group_decoded_bytes+n.decoded_bytes>n.max_decoded_bytes
        start_new
    ) split
  ),
  numbered_merges as materialized (
    select m.*,p.group_no,p.group_input_count input_order
    from ranked_merges m
    join merge_pack p
      on p.operation_id=m.operation_id
      and p.document_version_id=m.document_version_id
      and p.input_no=m.input_no
  ),
  next_group_physical as materialized (
    select m.operation_id,m.document_version_id,m.current_level,m.group_no,
      m.sequence_no child_sequence_no,m.id child_chunk_id,
      part.ordinality::integer child_physical_no,
      part.value physical_receipt
    from numbered_merges m
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(
          m.result_json#>'{merge_receipt,physical_receipts}')='array'
        then m.result_json#>'{merge_receipt,physical_receipts}'
        else '[]'::jsonb end) with ordinality part(value,ordinality)
  ),
  next_group_logical as materialized (
    select p.operation_id,p.document_version_id,p.current_level,p.group_no,
      p.physical_receipt->>'logical_source_key' logical_source_key,
      min((p.physical_receipt->>'logical_manifest_ordinal')::integer)
        logical_manifest_ordinal,
      encode(digest(jsonb_build_object(
        'receipt_contract','LOGICAL_SOURCE_RECEIPT_V3',
        'logical_source_key',
          p.physical_receipt->>'logical_source_key',
        'logical_manifest_ordinal',
          min((p.physical_receipt->>
            'logical_manifest_ordinal')::integer),
        'ordered_physical_receipts',string_agg(
          p.physical_receipt->>'physical_receipt','||'
          order by(p.physical_receipt->>
            'logical_manifest_ordinal')::integer,
            (p.physical_receipt->>'physical_part_no')::integer,
            p.child_sequence_no,p.child_physical_no)
      )::text,'sha256'),'hex') logical_receipt
    from next_group_physical p
    where coalesce(p.physical_receipt->>'logical_manifest_ordinal','')
        ~'^[0-9]{1,9}$'
      and coalesce(p.physical_receipt->>'physical_part_no','')
        ~'^[1-9][0-9]{0,8}$'
      and coalesce(p.physical_receipt->>'physical_receipt','')
        ~'^[0-9a-f]{64}$'
      and nullif(p.physical_receipt->>'logical_source_key','') is not null
    group by p.operation_id,p.document_version_id,p.current_level,p.group_no,
      p.physical_receipt->>'logical_source_key'
  ),
  next_group_roots as materialized (
    select p.operation_id,p.document_version_id,p.current_level,p.group_no,
      count(*)::integer physical_receipt_count,
      jsonb_agg(p.physical_receipt order by
        (p.physical_receipt->>'logical_manifest_ordinal')::integer,
        (p.physical_receipt->>'physical_part_no')::integer,
        p.child_sequence_no,p.child_physical_no) physical_receipts,
      encode(digest(string_agg(
        p.physical_receipt->>'physical_receipt','||'
        order by(p.physical_receipt->>'logical_manifest_ordinal')::integer,
          (p.physical_receipt->>'physical_part_no')::integer,
          p.child_sequence_no,p.child_physical_no),
        'sha256'),'hex') expected_physical_receipt_root,
      (
        select encode(digest(string_agg(
          l.logical_receipt,'||'
          order by l.logical_manifest_ordinal,l.logical_source_key),
          'sha256'),'hex')
        from next_group_logical l
        where l.operation_id=p.operation_id
          and l.document_version_id=p.document_version_id
          and l.current_level=p.current_level
          and l.group_no=p.group_no
      ) expected_logical_receipt_root
    from next_group_physical p
    where coalesce(p.physical_receipt->>'logical_manifest_ordinal','')
        ~'^[0-9]{1,9}$'
      and coalesce(p.physical_receipt->>'physical_part_no','')
        ~'^[1-9][0-9]{0,8}$'
      and coalesce(p.physical_receipt->>'physical_receipt','')
        ~'^[0-9a-f]{64}$'
    group by p.operation_id,p.document_version_id,p.current_level,p.group_no
  ),
  next_groups as materialized (
    select m.operation_id,m.document_version_id,(m.current_level+1) next_level,m.group_no,
      jsonb_agg(jsonb_build_object('input_chunk_id',m.id,
        'input_order',m.input_order,'r2_key',m.result_json->>'r2_key',
        'sha256',m.result_json->>'sha256','page_count',m.actual_page_count,
        'size_bytes',m.actual_byte_count,
        'child_merge_receipt',m.result_json->'merge_receipt',
        'child_merge_receipt_hash',encode(digest(
          coalesce(m.result_json->'merge_receipt','{}'::jsonb)::text,
          'sha256'),'hex'),
        'logical_receipt_root',m.result_json#>>
          '{merge_receipt,combined_logical_receipt_root}',
        'physical_receipt_root',m.result_json#>>
          '{merge_receipt,combined_physical_receipt_root}')
        order by m.sequence_no,m.id) inputs,
      encode(digest(string_agg(concat_ws('|',m.input_no::text,m.id::text,
        m.result_json->>'r2_key',m.result_json->>'sha256',m.actual_page_count::text,
        m.actual_byte_count::text,encode(digest(
          coalesce(m.result_json->'merge_receipt','{}'::jsonb)::text,
          'sha256'),'hex')),'||' order by m.sequence_no,m.id),
        'sha256'),'hex') ordered_input_hash,
      encode(digest(string_agg(encode(digest(
        coalesce(m.result_json->'merge_receipt','{}'::jsonb)::text,
        'sha256'),'hex'),'||' order by m.sequence_no,m.id),
        'sha256'),'hex') expected_child_receipt_hash,
      roots.expected_logical_receipt_root,
      roots.expected_physical_receipt_root,
      roots.physical_receipts,
      sum(m.actual_page_count)::integer expected_pages,sum(m.actual_byte_count)::bigint expected_bytes
    from numbered_merges m
    join next_group_roots roots
      on roots.operation_id=m.operation_id
     and roots.document_version_id=m.document_version_id
     and roots.current_level=m.current_level
     and roots.group_no=m.group_no
    group by m.operation_id,m.document_version_id,m.current_level,m.group_no
      ,roots.expected_logical_receipt_root
      ,roots.expected_physical_receipt_root,roots.physical_receipts
    having count(*)<=max(m.max_inputs)
      and sum(m.actual_page_count)<=max(m.max_pages)
      and sum(m.actual_byte_count)<=max(m.max_bytes)
      and sum(m.decoded_bytes)<=max(m.max_decoded_bytes)
  ),
  next_merges as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,plan_generation,sequence_no,level_no,
      entity_type,entity_id,document_version_id,status,priority,run_after_utc,payload_json,
      expected_page_count,expected_byte_count,operation_control_version,created_at_utc,updated_at_utc)
    select g.operation_id,'PDF_MERGE','MERGE',
      encode(digest(concat_ws('|','PDF_MERGE',g.document_version_id::text,
        g.next_level::text,g.group_no::text,g.ordered_input_hash,
        pg.plan_generation::text,
        case when (select count(*) from next_groups all_groups
          where all_groups.operation_id=g.operation_id
            and all_groups.document_version_id=g.document_version_id)=1
          and (select entity_type from public.invoice_document_versions
            where id=g.document_version_id)='INVOICE'
          then 'FINAL_MERGE_SELECTIVE_V2' else 'NONE' end,
        coalesce(numbering.excluded_pages,'[]'::jsonb)::text),
        'sha256'),'hex'),
      pg.plan_generation,g.group_no,g.next_level,'DOCUMENT',g.document_version_id,
      g.document_version_id,'QUEUED',550,v_now,
      jsonb_build_object('level',g.next_level,'inputs',g.inputs,
        'fan_in',jsonb_array_length(g.inputs),
        'ordered_input_hash',g.ordered_input_hash,
        'expected_child_receipt_hash',g.expected_child_receipt_hash,
        'expected_logical_receipt_root',g.expected_logical_receipt_root,
        'expected_physical_receipt_root',g.expected_physical_receipt_root,
        'expected_physical_receipts',g.physical_receipts,
        'receipt_contract','ACTUAL_BYTES_MERGE_RECEIPT_V3',
        'plan_generation',pg.plan_generation,
        'apply_final_page_numbers',
          (select count(*) from next_groups all_groups
             where all_groups.operation_id=g.operation_id
               and all_groups.document_version_id=g.document_version_id)=1
          and (select entity_type from public.invoice_document_versions
            where id=g.document_version_id)='INVOICE',
        'page_numbering_contract',case
          when (select count(*) from next_groups all_groups
             where all_groups.operation_id=g.operation_id
               and all_groups.document_version_id=g.document_version_id)=1
            and (select entity_type from public.invoice_document_versions
              where id=g.document_version_id)='INVOICE'
          then 'FINAL_MERGE_SELECTIVE_V2' else null end,
        'page_numbering_excluded_pages',case
          when (select count(*) from next_groups all_groups
             where all_groups.operation_id=g.operation_id
               and all_groups.document_version_id=g.document_version_id)=1
            and (select entity_type from public.invoice_document_versions
              where id=g.document_version_id)='INVOICE'
          then coalesce(numbering.excluded_pages,'[]'::jsonb)
          else '[]'::jsonb end,
        'document_entity_type',(select entity_type
          from public.invoice_document_versions where id=g.document_version_id),
        'document_version_id',g.document_version_id),
      g.expected_pages,g.expected_bytes,o.control_version,v_now,v_now
    from next_groups g join public.invoice_operations o on o.id=g.operation_id
    left join page_numbering_policies numbering
      on numbering.operation_id=g.operation_id
     and numbering.document_version_id=g.document_version_id
    cross join lateral (
      select coalesce((
        select prior.plan_generation
        from public.invoice_operation_chunks prior
        where prior.operation_id=g.operation_id and prior.chunk_type='PDF_MERGE'
          and prior.document_version_id=g.document_version_id
          and prior.level_no=g.next_level and prior.sequence_no=g.group_no
          and prior.payload_json->>'ordered_input_hash'=g.ordered_input_hash
        order by prior.created_at_utc desc,prior.id desc limit 1),
        1+coalesce((select max(prior.plan_generation)
          from public.invoice_operation_chunks prior
          where prior.operation_id=g.operation_id and prior.chunk_type='PDF_MERGE'
            and prior.document_version_id=g.document_version_id
            and prior.level_no=g.next_level and prior.sequence_no=g.group_no),0))
        plan_generation
    ) pg
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key)
    do update set priority=greatest(
      public.invoice_operation_chunks.priority,excluded.priority),
      updated_at_utc=excluded.updated_at_utc
    returning id,operation_id,document_version_id,level_no,sequence_no,plan_generation
  ),
  replaced_next_merges as (
    update public.invoice_operation_chunks stale
    set status='SUPERSEDED',phase='SUPERSEDED',completed_at_utc=v_now,
        failed_at_utc=null,
        replaced_by_chunk_id=fresh.id,replacement_required=true,
        result_json=coalesce(stale.result_json,'{}'::jsonb)
          ||jsonb_build_object('replacement_chunk_id',fresh.id),
        error_json=jsonb_build_object(
          'code','REPLACED_AFTER_UPSTREAM_RETRY',
          'replacement_chunk_id',fresh.id),
        updated_at_utc=v_now
    from next_merges fresh
    where stale.operation_id=fresh.operation_id
      and stale.chunk_type='PDF_MERGE'
      and stale.document_version_id=fresh.document_version_id
      and stale.level_no=fresh.level_no
      and stale.sequence_no=fresh.sequence_no
      and stale.id<>fresh.id and stale.status='BLOCKED'
      and stale.error_json->>'code'='UPSTREAM_RETRY_INVALIDATED'
    returning stale.id
  ),
  final_merge as materialized (
    select ps.*,m.id merge_chunk_id,m.payload_json,m.result_json,
      m.actual_page_count,m.actual_byte_count
    from plan_state ps join current_merges m on m.operation_id=ps.operation_id
      and m.document_version_id=ps.document_version_id
      and m.chunk_type='PDF_MERGE' and m.level_no=ps.current_level and m.status='COMPLETE'
    where ps.level_count=1 and ps.complete_count=1 and ps.failed_count=0
  ),
  verify_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,plan_generation,sequence_no,entity_type,entity_id,
      document_version_id,status,priority,run_after_utc,payload_json,expected_page_count,expected_byte_count,
      operation_control_version,created_at_utc,updated_at_utc)
    select f.operation_id,'DOCUMENT_VERIFY','VERIFY',
      encode(digest(concat_ws('|','DOCUMENT_VERIFY',
        f.document_version_id::text,f.result_json->>'sha256',
        v.manifest_hash,coverage.manifest_coverage_hash,
        f.payload_json->>'expected_logical_receipt_root',
        f.payload_json->>'expected_physical_receipt_root',
        pg.plan_generation::text),'sha256'),'hex'),
      pg.plan_generation,0,'DOCUMENT',f.document_version_id,f.document_version_id,
      'QUEUED',550,v_now,jsonb_build_object('candidate_chunk_id',f.merge_chunk_id,
        'candidate_r2_key',f.result_json->>'r2_key','candidate_sha256',f.result_json->>'sha256',
        'candidate_size_bytes',f.actual_byte_count,'candidate_page_count',f.actual_page_count,
        'manifest_hash',v.manifest_hash,
        'expected_coverage_hash',coverage.manifest_coverage_hash,
        'resolved_input_coverage_hash',coverage.input_coverage_hash,
        'expected_input_count',coverage.manifest_input_count,
        'resolved_input_count',coverage.resolved_input_count,
        'expected_physical_input_count',coverage.physical_input_count,
        'expected_physical_input_hash',coverage.physical_input_hash,
        'expected_logical_source_count',receipts.logical_source_count,
        'expected_logical_root_receipt',
          f.payload_json->>'expected_logical_receipt_root',
        'expected_physical_root_receipt',
          f.payload_json->>'expected_physical_receipt_root',
        'expected_ordered_input_root',
          f.payload_json->>'expected_child_receipt_hash',
        'root_merge_receipt_identity',encode(digest(
          jsonb_build_object(
            'receipt_contract','DOCUMENT_ROOT_RECEIPT_V3',
            'logical_root',
              f.payload_json->>'expected_logical_receipt_root',
            'physical_root',
              f.payload_json->>'expected_physical_receipt_root',
            'ordered_input_root',
              f.payload_json->>'expected_child_receipt_hash',
            'page_count',v.expected_page_count,
            'output_sha256',f.result_json->>'sha256')::text,
          'sha256'),'hex'),
        'receipt_contract','ACTUAL_BYTES_MERGE_RECEIPT_V3',
        'plan_generation',pg.plan_generation,
        'final_merge_receipt',f.result_json->'merge_receipt',
        'final_merge_receipt_hash',encode(digest(
          coalesce(f.result_json->'merge_receipt','{}'::jsonb)::text,
          'sha256'),'hex'),
        'independent_expected_page_count',v.expected_page_count),
      v.expected_page_count,f.actual_byte_count,
      o.control_version,v_now,v_now
    from final_merge f join public.invoice_document_versions v on v.id=f.document_version_id
    join public.invoice_operations o on o.id=f.operation_id
    join lateral (
      select
        (select encode(digest(string_agg(concat_ws('|',
            x.value->>'ordinal',x.value->>'source_chunk_key'),
            '||' order by (x.value->>'ordinal')::integer),
          'sha256'),'hex')
         from jsonb_array_elements(v.manifest_json) x(value)
         where coalesce(x.value->>'ordinal','')~'^[0-9]+$')
          manifest_coverage_hash,
        (select encode(digest(string_agg(concat_ws('|',r.sequence_no::text,
            r.payload_json->>'source_chunk_key'),
            '||' order by r.sequence_no,r.id),'sha256'),'hex')
         from current_inputs r
         where r.operation_id=f.operation_id
           and r.document_version_id=f.document_version_id
           and r.chunk_type='DOCUMENT_INPUT' and r.status='COMPLETE')
          input_coverage_hash,
        jsonb_array_length(v.manifest_json)::integer manifest_input_count,
        (select count(*)::integer
         from current_inputs r
         where r.operation_id=f.operation_id
           and r.document_version_id=f.document_version_id
           and r.chunk_type='DOCUMENT_INPUT' and r.status='COMPLETE')
          resolved_input_count,
        (select count(*)::integer
         from current_inputs r
         cross join lateral jsonb_array_elements(
           case when jsonb_typeof(r.result_json->'normalised_manifest')='array'
                  and jsonb_array_length(r.result_json->'normalised_manifest')>0
             then r.result_json->'normalised_manifest'
             else jsonb_build_array(jsonb_build_object(
               'r2_key',coalesce(r.result_json->>'r2_key',
                 r.result_json->>'normalised_r2_key'),
               'sha256',r.result_json->>'sha256')) end)
           with ordinality part(value,ordinality)
         where r.operation_id=f.operation_id
           and r.document_version_id=f.document_version_id
           and r.chunk_type='DOCUMENT_INPUT' and r.status='COMPLETE'
           and coalesce(part.value->>'r2_key','')<>'')
          physical_input_count,
        (select encode(digest(string_agg(concat_ws('|',
            r.sequence_no::text,part.ordinality::text,
            part.value->>'r2_key',
            coalesce(part.value->>'sha256',r.result_json->>'sha256','')),
            '||' order by r.sequence_no,part.ordinality),'sha256'),'hex')
         from current_inputs r
         cross join lateral jsonb_array_elements(
           case when jsonb_typeof(r.result_json->'normalised_manifest')='array'
                  and jsonb_array_length(r.result_json->'normalised_manifest')>0
             then r.result_json->'normalised_manifest'
             else jsonb_build_array(jsonb_build_object(
               'r2_key',coalesce(r.result_json->>'r2_key',
                 r.result_json->>'normalised_r2_key'),
               'sha256',r.result_json->>'sha256')) end)
           with ordinality part(value,ordinality)
         where r.operation_id=f.operation_id
           and r.document_version_id=f.document_version_id
           and r.chunk_type='DOCUMENT_INPUT' and r.status='COMPLETE'
           and coalesce(part.value->>'r2_key','')<>'')
          physical_input_hash
    ) coverage on coverage.manifest_coverage_hash=coverage.input_coverage_hash
      and coverage.manifest_input_count=coverage.resolved_input_count
    join lateral (
      with physical as materialized (
        select r.id input_chunk_id,r.sequence_no,
          coalesce(nullif(r.payload_json->>'source_chunk_key',''),
            r.id::text) logical_source_key,
          part.ordinality::integer physical_part_no,
          coalesce(nullif(part.value->>'r2_key',''),
            nullif(part.value->>'key',''),
            nullif(r.result_json->>'r2_key',''),
            nullif(r.result_json->>'normalised_r2_key','')) object_key,
          coalesce(nullif(part.value->>'sha256',''),
            nullif(r.result_json->>'sha256','')) stored_sha256,
          case when coalesce(part.value->>'page_count','')
              ~'^[1-9][0-9]*$'
            then(part.value->>'page_count')::integer
            else r.actual_page_count end page_count,
          case when coalesce(part.value->>'size_bytes','')
              ~'^[1-9][0-9]*$'
            then(part.value->>'size_bytes')::bigint
            else r.actual_byte_count end byte_count
        from current_inputs r
        cross join lateral jsonb_array_elements(
          case
            when jsonb_typeof(r.result_json->'parts')='array'
                and jsonb_array_length(r.result_json->'parts')>0
              then r.result_json->'parts'
            when jsonb_typeof(r.result_json->'normalised_manifest')='array'
                and jsonb_array_length(r.result_json->'normalised_manifest')>0
              then r.result_json->'normalised_manifest'
            else jsonb_build_array(jsonb_build_object(
              'r2_key',coalesce(r.result_json->>'r2_key',
                r.result_json->>'normalised_r2_key'),
              'sha256',r.result_json->>'sha256',
              'page_count',r.actual_page_count,
              'size_bytes',r.actual_byte_count))
          end) with ordinality part(value,ordinality)
        where r.operation_id=f.operation_id
          and r.document_version_id=f.document_version_id
          and r.chunk_type='DOCUMENT_INPUT' and r.status='COMPLETE'
      ),
      physical_receipts as materialized (
        select p.*,encode(digest(jsonb_build_object(
          'receipt_contract','ACTUAL_BYTES_OBJECT_RECEIPT_V3',
          'logical_source_key',p.logical_source_key,
          'logical_manifest_ordinal',p.sequence_no,
          'physical_part_no',p.physical_part_no,
          'object_key',p.object_key,
          'stored_sha256',p.stored_sha256,
          'expected_page_count',p.page_count,
          'expected_byte_count',p.byte_count
        )::text,'sha256'),'hex') physical_receipt
        from physical p
      ),
      logical_receipts as materialized (
        select p.input_chunk_id,p.sequence_no,p.logical_source_key,
          encode(digest(jsonb_build_object(
            'receipt_contract','LOGICAL_SOURCE_RECEIPT_V3',
            'logical_source_key',p.logical_source_key,
            'logical_manifest_ordinal',p.sequence_no,
            'ordered_physical_receipts',string_agg(
              p.physical_receipt,'||' order by p.physical_part_no)
          )::text,'sha256'),'hex') logical_receipt
        from physical_receipts p
        group by p.input_chunk_id,p.sequence_no,p.logical_source_key
      )
      select
        (select count(*)::integer from logical_receipts)
          logical_source_count,
        (select encode(digest(string_agg(l.logical_receipt,'||'
          order by l.sequence_no,l.logical_source_key),
          'sha256'),'hex') from logical_receipts l)
          expected_logical_root_receipt,
        (select encode(digest(string_agg(p.physical_receipt,'||'
          order by p.sequence_no,p.physical_part_no,p.input_chunk_id),
          'sha256'),'hex') from physical_receipts p)
          expected_physical_root_receipt,
        (select encode(digest(string_agg(concat_ws('|',
          p.sequence_no::text,p.logical_source_key,
          p.physical_part_no::text,p.physical_receipt),'||'
          order by p.sequence_no,p.physical_part_no,p.input_chunk_id),
          'sha256'),'hex') from physical_receipts p)
          expected_ordered_input_root
    ) receipts on receipts.logical_source_count=coverage.manifest_input_count
      and receipts.expected_logical_root_receipt=
        f.payload_json->>'expected_logical_receipt_root'
      and receipts.expected_physical_root_receipt=
        f.payload_json->>'expected_physical_receipt_root'
    cross join lateral (
      select coalesce((
        select prior.plan_generation
        from public.invoice_operation_chunks prior
        where prior.operation_id=f.operation_id
          and prior.chunk_type='DOCUMENT_VERIFY'
          and prior.document_version_id=f.document_version_id
          and prior.level_no=0 and prior.sequence_no=0
          and prior.payload_json->>'candidate_sha256'=f.result_json->>'sha256'
          and prior.payload_json->>'expected_physical_input_hash'=
            coverage.physical_input_hash
        order by prior.created_at_utc desc,prior.id desc limit 1),
        1+coalesce((select max(prior.plan_generation)
          from public.invoice_operation_chunks prior
          where prior.operation_id=f.operation_id
            and prior.chunk_type='DOCUMENT_VERIFY'
            and prior.document_version_id=f.document_version_id
            and prior.level_no=0 and prior.sequence_no=0),0))
        plan_generation
    ) pg
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key)
    do update set priority=greatest(
      public.invoice_operation_chunks.priority,excluded.priority),
      updated_at_utc=excluded.updated_at_utc
    returning id,operation_id,document_version_id,level_no,sequence_no,plan_generation
  ),
  replaced_verifications as (
    update public.invoice_operation_chunks stale
    set status='SUPERSEDED',phase='SUPERSEDED',completed_at_utc=v_now,
        failed_at_utc=null,
        replaced_by_chunk_id=fresh.id,replacement_required=true,
        result_json=coalesce(stale.result_json,'{}'::jsonb)
          ||jsonb_build_object('replacement_chunk_id',fresh.id),
        error_json=jsonb_build_object(
          'code','REPLACED_AFTER_UPSTREAM_RETRY',
          'replacement_chunk_id',fresh.id),
        updated_at_utc=v_now
    from verify_chunks fresh
    where stale.operation_id=fresh.operation_id
      and stale.chunk_type='DOCUMENT_VERIFY'
      and stale.document_version_id=fresh.document_version_id
      and stale.level_no=fresh.level_no
      and stale.sequence_no=fresh.sequence_no
      and stale.id<>fresh.id and stale.status='BLOCKED'
      and stale.error_json->>'code'='UPSTREAM_RETRY_INVALIDATED'
    returning stale.id
  ),
  advanced as (
    update public.invoice_operation_chunks c
    set phase=case when ps.failed_count>0 then 'BLOCKED'
                   when ps.level_count=1 and ps.complete_count=1 then 'COMPLETE'
                   else 'WAIT_FOR_MERGE' end,
        status=case when ps.failed_count>0 then 'BLOCKED'
                    when ps.level_count=1 and ps.complete_count=1 then 'WAITING'
                    else 'WAITING' end,
        error_json=case when ps.failed_count>0 then jsonb_build_object('code','MERGE_FAILED') else null end,
        progress_json=jsonb_build_object('status_message',
          case when ps.level_count=1 and ps.complete_count=1 then 'Final verification queued'
               else 'Waiting for merge level' end,'merge_level',ps.current_level,
          'parts_complete',ps.complete_count,'parts_total',ps.level_count),
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from plan_state ps where c.id=ps.chunk_id returning c.id,c.status,c.phase,c.progress_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,
    'progress',progress_json)),'[]'::jsonb) into v_part from advanced;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- COMPLETE only observes a verified READY version.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id from jsonb_array_elements(p_claims) x
    where x->>'phase'='COMPLETE'
  ),
  ready as materialized (
    select c.*,v.r2_key,v.sha256,v.size_bytes,v.page_count
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoice_document_versions v on v.id=c.document_version_id and v.status='READY'
  ),
  invoice_ptr as (
    update public.invoices i set
      preview_document_version_id=case when v.purpose='DRAFT_PREVIEW' then v.id else i.preview_document_version_id end,
      invoice_pdf_r2_key=case when v.purpose='DRAFT_PREVIEW' then v.r2_key else i.invoice_pdf_r2_key end,
      invoice_pdf_generated_at_utc=case when v.purpose='DRAFT_PREVIEW' then v.verified_at_utc else i.invoice_pdf_generated_at_utc end,
      document_state=case when v.purpose='DRAFT_PREVIEW' then 'READY' else i.document_state end,
      active_document_operation_id=case when i.active_document_operation_id=v.operation_id then null else i.active_document_operation_id end,
      last_document_error_json=null,updated_at=v_now
    from ready r join public.invoice_document_versions v on v.id=r.document_version_id
    where r.entity_type='INVOICE' and i.id=r.entity_id returning i.id
  ),
  timesheet_ptr as (
    update public.timesheets t set current_document_version_id=v.id,
      manual_pdf_r2_key=case when t.manual_document_asset_id is not null
        then v.r2_key else t.manual_pdf_r2_key end,
      generated_pdf_at_utc=v.verified_at_utc,document_state='READY',
      active_document_operation_id=null,last_document_error_json=null,updated_at=v_now
    from ready r join public.invoice_document_versions v on v.id=r.document_version_id
    where r.entity_type='TIMESHEET' and t.timesheet_id=r.entity_id and t.is_current returning t.timesheet_id
  ),
  issue_requeue as (
    update public.invoice_operation_chunks issue
    set status='QUEUED',phase='FINALISE',run_after_utc=v_now,updated_at_utc=v_now
    from ready r
    where issue.chunk_type='ISSUE_INVOICE' and issue.phase='WAIT_DOCUMENT'
      and issue.document_version_id=r.document_version_id and issue.status='WAITING'
    returning issue.id
  ),
  completed as (
    update public.invoice_operation_chunks c set status='COMPLETE',
      completed_at_utc=v_now,updated_at_utc=v_now,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      result_json=jsonb_build_object('document_version_id',r.document_version_id,'r2_key',r.r2_key,
        'sha256',r.sha256,'size_bytes',r.size_bytes,'page_count',r.page_count)
    from ready r where c.id=r.id returning c.id,c.status,c.phase,c.result_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'result',result_json)),'[]'::jsonb)
    into v_part from completed;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  return coalesce(v_result,'[]'::jsonb);
end;
$function$;

revoke all on function private._invoice_document_advance_batch_v6_downstream(jsonb,timestamptz) from public,anon,authenticated;
grant execute on function private._invoice_document_advance_batch_v6_downstream(jsonb,timestamptz) to service_role;

create or replace function public.invoice_work_context_batch(
  p_claims jsonb,
  p_now_utc timestamptz default now()
) returns jsonb
language plpgsql
security definer
set search_path to 'public','extensions','pg_temp'
as $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_result jsonb;
begin
  if p_claims is null or jsonb_typeof(p_claims) is distinct from 'array' then
    raise exception using errcode='22023',
      message='p_claims must be an array containing 1..100 claims';
  end if;
  if jsonb_array_length(p_claims)<1
     or jsonb_array_length(p_claims)>100 then
    raise exception using errcode='22023',
      message='p_claims must be an array containing 1..100 claims';
  end if;

  with supplied as materialized (
    select x.ordinality::integer request_no,x.value raw_claim,
      case when coalesce(x.value->>'chunk_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then (x.value->>'chunk_id')::uuid end chunk_id,
      case when coalesce(x.value->>'lease_token','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then (x.value->>'lease_token')::uuid end lease_token,
      case when coalesce(x.value->>'fence_token','') ~ '^[0-9]{1,18}$'
        then (x.value->>'fence_token')::bigint end fence_token,
      case when coalesce(x.value->>'operation_control_version','') ~ '^[0-9]{1,18}$'
        then (x.value->>'operation_control_version')::bigint end operation_control_version
    from jsonb_array_elements(p_claims) with ordinality x(value,ordinality)
  ),
  current_graph as materialized (
    select g.*
    from private._invoice_current_chunks_batch(
      coalesce((
        select array_agg(distinct c.operation_id)
        from supplied s
        join public.invoice_operation_chunks c on c.id=s.chunk_id),
        array['00000000-0000-0000-0000-000000000000'::uuid]),
      null,null,10000) g
  ),
  inspected as materialized (
    select s.*,c.operation_id,c.chunk_type,c.phase,c.entity_type,c.entity_id,
      c.document_version_id,c.document_asset_id,c.input_document_version_id,
      c.payload_json,c.plan_generation,c.level_no,c.sequence_no,
      c.expected_page_count,c.expected_byte_count,
      c.lease_token current_lease_token,c.fence_token current_fence_token,
      c.operation_control_version current_control_version,
      c.lease_expires_at_utc,c.status current_status,
      o.control_version operation_current_control_version,o.status operation_status,
      o.config_json operation_config,
      case
        when s.chunk_id is null or s.lease_token is null
          or s.fence_token is null or s.operation_control_version is null then 'INVALID_CLAIM'
        when c.id is null then 'CHUNK_NOT_FOUND'
        when exists(select 1 from current_graph g
          where g.operation_id=c.operation_id
            and g.replacement_chain_status='INVALID')
          then 'INVALID_REPLACEMENT_GRAPH'
        when not exists(select 1 from current_graph g
          where g.current_chunk_id=c.id
            and g.replacement_chain_status='VALID')
          then 'CHUNK_NOT_CURRENT'
        when c.status<>'RUNNING' then 'CHUNK_NOT_RUNNING'
        when c.lease_token is distinct from s.lease_token then 'LEASE_TOKEN_MISMATCH'
        when c.fence_token is distinct from s.fence_token then 'FENCE_TOKEN_MISMATCH'
        when c.operation_control_version is distinct from s.operation_control_version
          or o.control_version is distinct from s.operation_control_version then 'CONTROL_VERSION_MISMATCH'
        when c.lease_expires_at_utc is null or c.lease_expires_at_utc<=v_now then 'LEASE_EXPIRED'
        when o.status in('COMPLETE','FAILED','DEAD_LETTER','CANCELLED','SUPERSEDED')
          then 'OPERATION_TERMINAL'
      end ownership_error
    from supplied s
    left join public.invoice_operation_chunks c on c.id=s.chunk_id
    left join public.invoice_operations o on o.id=c.operation_id
  ),
  valid as materialized (
    select i.*,a.id asset_exists,a.source_kind,a.source_id,a.source_revision asset_source_revision,
      a.original_r2_key,a.original_filename,a.declared_media_type,a.detected_media_type,
      a.original_sha256,a.original_size_bytes,
      a.orientation_degrees,a.source_page_count,a.normalised_manifest_json,
      dv.id version_exists,dv.entity_type document_entity_type,dv.entity_id document_entity_id,
      dv.purpose,dv.source_revision document_source_revision,dv.template_version,
      dv.snapshot_json,dv.snapshot_hash,
      case when dv.snapshot_json is not null then encode(digest(dv.snapshot_json::text,'sha256'),'hex') end calculated_snapshot_hash,
      case when dv.snapshot_json ? 'presentation_model' then dv.snapshot_json->'presentation_model'
           when dv.snapshot_json ? 'timesheet' then dv.snapshot_json
           else '{}'::jsonb end root_presentation_model,
      case when dv.snapshot_json ? 'presentation_model' then dv.snapshot_json#>>'{presentation_model,schema_version}'
           when dv.snapshot_json ? 'timesheet' then coalesce(dv.snapshot_json#>>'{timesheet,schema_version}',dv.snapshot_json->>'snapshot_schema_version')
           else null end root_presentation_schema_version,
      case when dv.snapshot_json ? 'presentation_model' then coalesce(dv.snapshot_json->>'presentation_model_hash', dv.snapshot_json#>>'{presentation_model,presentation_model_hash}', encode(digest((dv.snapshot_json->'presentation_model')::text,'sha256'),'hex'))
           when dv.snapshot_json ? 'timesheet' then encode(digest(dv.snapshot_json::text,'sha256'),'hex')
           else null end root_presentation_model_hash,
      dv.manifest_json,dv.manifest_hash,
      input_v.status input_document_status,input_v.r2_key input_document_r2_key,
      input_v.sha256 input_document_sha256,input_v.size_bytes input_document_size_bytes,
      input_v.page_count input_document_page_count,
      i.operation_config->'processor_policy' processor_limits
    from inspected i
    left join public.invoice_document_assets a on a.id=i.document_asset_id
    left join public.invoice_document_versions dv on dv.id=i.document_version_id
    left join public.invoice_document_versions input_v on input_v.id=i.input_document_version_id
    where i.ownership_error is null
  ),
  source_models as materialized (
    select v.chunk_id,m.value manifest_item,
      case
        when m.value->>'input_type'='ELECTRONIC_TIMESHEET' then coalesce(
          (select x.value->'render_model'
           from jsonb_array_elements(
             case when jsonb_typeof(v.snapshot_json->'timesheet_sources')='array'
               then v.snapshot_json->'timesheet_sources' else '[]'::jsonb end)
             x(value)
           where x.value->>'timesheet_id'=m.value->>'source_entity_id'
           limit 1),
          case when v.document_entity_type='TIMESHEET'
            then coalesce(v.snapshot_json->'presentation_model',v.snapshot_json) end)
        when m.value->>'input_type' in('HEALTHROSTER_SUPPORT','NHSP_SUPPORT')
          then coalesce(
            (select coalesce(x.value->'render_model',x.value)
             from jsonb_array_elements(
               case when jsonb_typeof(v.snapshot_json->'source_support')='array'
                 then v.snapshot_json->'source_support'
                 when jsonb_typeof(v.snapshot_json->'supporting_sources')='array'
                 then v.snapshot_json->'supporting_sources'
                 else '[]'::jsonb end) x(value)
             where x.value->>'import_id'=m.value->>'source_entity_id'
             limit 1),'{}'::jsonb)
        when m.value->>'input_type'='HIGHER_RATE_SUPPORT' then
          coalesce(
            case when jsonb_typeof(v.snapshot_json->'higher_rate_support')='object'
              then v.snapshot_json->'higher_rate_support' end,
            jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1',
              'rows',coalesce((
                select jsonb_agg(x.value order by x.ordinality)
                from jsonb_array_elements(
                  case when jsonb_typeof(v.snapshot_json->'lines')='array'
                    then v.snapshot_json->'lines' else '[]'::jsonb end)
                  with ordinality x(value,ordinality)
                where upper(coalesce(x.value#>>'{business_meta,line_type}',''))
                    like '%HIGHER%'
                  or coalesce(x.value->'business_meta','{}'::jsonb)?'higher_rate'
              ),'[]'::jsonb))
          )
        when m.value->>'input_type' in('ATTACHMENT_INDEX','SECTION_SEPARATOR')
          then jsonb_build_object(
            'display_label',m.value->>'display_label',
            'input_type',m.value->>'input_type',
            'manifest_ordinal',m.value->'ordinal')
        else coalesce(m.value->'frozen_model','{}'::jsonb)
      end frozen_model,
      case
        when m.value->>'input_type'='ELECTRONIC_TIMESHEET' then coalesce(
          (select x.value#>>'{render_model,schema_version}'
           from jsonb_array_elements(
             case when jsonb_typeof(v.snapshot_json->'timesheet_sources')='array'
               then v.snapshot_json->'timesheet_sources' else '[]'::jsonb end)
             x(value)
           where x.value->>'timesheet_id'=m.value->>'source_entity_id'
           limit 1),
          case when v.document_entity_type='TIMESHEET'
            then coalesce(v.snapshot_json#>>'{presentation_model,schema_version}',
              v.snapshot_json->>'schema_version') end)
        when m.value->>'input_type'='HEALTHROSTER_SUPPORT' then coalesce(
          (select coalesce(x.value#>>'{render_model,schema_version}',
            x.value->>'schema_version')
           from jsonb_array_elements(
             case when jsonb_typeof(v.snapshot_json->'source_support')='array'
               then v.snapshot_json->'source_support'
               when jsonb_typeof(v.snapshot_json->'supporting_sources')='array'
               then v.snapshot_json->'supporting_sources'
               else '[]'::jsonb end) x(value)
           where x.value->>'import_id'=m.value->>'source_entity_id'
           limit 1),
          'HEALTHROSTER_PRESENTATION_V1')
        when m.value->>'input_type'='NHSP_SUPPORT' then 'NHSP_PRESENTATION_V1'
        when m.value->>'input_type'='HIGHER_RATE_SUPPORT' then 'HIGHER_RATE_PRESENTATION_V1'
        when m.value->>'input_type'='ATTACHMENT_INDEX' then 'ATTACHMENT_INDEX_PRESENTATION_V1'
        else coalesce(m.value#>>'{frozen_model,schema_version}',m.value->>'schema_version')
      end frozen_model_schema_version,
      encode(digest((case
        when m.value->>'input_type'='ELECTRONIC_TIMESHEET' then coalesce(
          (select x.value->'render_model'
           from jsonb_array_elements(
             case when jsonb_typeof(v.snapshot_json->'timesheet_sources')='array'
               then v.snapshot_json->'timesheet_sources' else '[]'::jsonb end)
             x(value)
           where x.value->>'timesheet_id'=m.value->>'source_entity_id'
           limit 1),
          case when v.document_entity_type='TIMESHEET' then coalesce(v.snapshot_json->'presentation_model',v.snapshot_json) end)
        when m.value->>'input_type' in('HEALTHROSTER_SUPPORT','NHSP_SUPPORT') then coalesce(
          (select coalesce(x.value->'render_model',x.value)
           from jsonb_array_elements(case when jsonb_typeof(v.snapshot_json->'source_support')='array'
              then v.snapshot_json->'source_support' when jsonb_typeof(v.snapshot_json->'supporting_sources')='array'
              then v.snapshot_json->'supporting_sources' else '[]'::jsonb end) x(value)
           where x.value->>'import_id'=m.value->>'source_entity_id' limit 1),'{}'::jsonb)
        when m.value->>'input_type'='HIGHER_RATE_SUPPORT' then coalesce(
          case when jsonb_typeof(v.snapshot_json->'higher_rate_support')='object'
            then v.snapshot_json->'higher_rate_support' end,
          jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1',
            'rows',coalesce((
              select jsonb_agg(x.value order by x.ordinality)
              from jsonb_array_elements(
                case when jsonb_typeof(v.snapshot_json->'lines')='array'
                  then v.snapshot_json->'lines' else '[]'::jsonb end)
                with ordinality x(value,ordinality)
              where upper(coalesce(x.value#>>'{business_meta,line_type}',''))
                  like '%HIGHER%'
                or coalesce(x.value->'business_meta','{}'::jsonb)?'higher_rate'
            ),'[]'::jsonb))
        )
        when m.value->>'input_type' in('ATTACHMENT_INDEX','SECTION_SEPARATOR') then jsonb_build_object('display_label',m.value->>'display_label','input_type',m.value->>'input_type','manifest_ordinal',m.value->'ordinal')
        else coalesce(m.value->'frozen_model','{}'::jsonb)
      end)::text,'sha256'),'hex') frozen_model_hash
    from valid v
    left join lateral jsonb_array_elements(
      case when jsonb_typeof(v.manifest_json)='array' then v.manifest_json else '[]'::jsonb end
    ) m(value) on
      case when coalesce(v.payload_json->>'manifest_ordinal','') ~ '^[0-9]{1,9}$'
             and coalesce(m.value->>'ordinal','') ~ '^[0-9]{1,9}$'
        then (m.value->>'ordinal')::integer=(v.payload_json->>'manifest_ordinal')::integer
        else nullif(m.value->>'source_chunk_key','') is not null
             and m.value->>'source_chunk_key'=v.payload_json->>'source_chunk_key' end
    where v.chunk_type='SOURCE_RENDER'
  ),
  projected as materialized (
    select v.request_no,v.chunk_id,v.operation_id,v.chunk_type,v.phase,
      v.entity_type,v.entity_id,v.document_version_id,v.document_asset_id,
      case
        when v.processor_limits is null
          or jsonb_typeof(v.processor_limits)<>'object'
          or nullif(coalesce(
              v.processor_limits->>'policy_version',
              v.processor_limits->>'version'
            ),'') is null
          then 'PROCESSOR_POLICY_MISSING'
        when v.chunk_type in('ASSET_INSPECT','ASSET_NORMALISE') and v.asset_exists is null
          then 'ASSET_NOT_FOUND'
        when v.chunk_type in('SOURCE_RENDER','INVOICE_CORE_RENDER','PDF_MERGE','DOCUMENT_VERIFY')
          and v.version_exists is null then 'DOCUMENT_VERSION_NOT_FOUND'
        when v.chunk_type in('SOURCE_RENDER','INVOICE_CORE_RENDER')
          and(jsonb_typeof(v.snapshot_json)<>'object' or v.snapshot_json='{}'::jsonb)
          then 'FROZEN_SNAPSHOT_MISSING'
        when v.chunk_type in('SOURCE_RENDER','INVOICE_CORE_RENDER')
          and (v.snapshot_hash is null
            or v.calculated_snapshot_hash is distinct from v.snapshot_hash)
          then 'FROZEN_SNAPSHOT_HASH_MISMATCH'
        when v.chunk_type='SOURCE_RENDER' and sm.manifest_item is null
          then 'SOURCE_MANIFEST_ITEM_MISSING'
        when v.chunk_type='SOURCE_RENDER'
          and coalesce(sm.frozen_model,'{}'::jsonb)='{}'::jsonb
          then 'SOURCE_FROZEN_MODEL_MISSING'
        when v.chunk_type='INVOICE_CORE_RENDER'
          and coalesce(v.root_presentation_schema_version,'') <> 'INVOICE_RENDER_MODEL_V1'
          then 'RENDER_MODEL_SCHEMA_UNSUPPORTED'
        when v.chunk_type='SOURCE_RENDER' and (
          case coalesce(sm.manifest_item->>'render_kind',
              sm.manifest_item->>'input_type',v.payload_json->>'render_kind')
            when 'ELECTRONIC_TIMESHEET' then coalesce(sm.frozen_model->>'schema_version','')
              not in('TIMESHEET_RENDER_MODEL_V1','TIMESHEET_RENDER_MODEL_V2')
            when 'HEALTHROSTER_SUPPORT' then coalesce(sm.frozen_model->>'schema_version','')
              not in('HEALTHROSTER_PRESENTATION_V1','HEALTHROSTER_PRESENTATION_V2')
            when 'NHSP_SUPPORT' then coalesce(sm.frozen_model->>'schema_version','')<>'NHSP_PRESENTATION_V1'
            when 'HIGHER_RATE_SUPPORT' then coalesce(sm.frozen_model->>'schema_version','')<>'HIGHER_RATE_PRESENTATION_V1'
            when 'ATTACHMENT_INDEX' then false
            when 'SECTION_SEPARATOR' then false
            else false end)
          then 'RENDER_MODEL_KIND_MISMATCH'
        when v.chunk_type='SOURCE_RENDER'
          and nullif(v.payload_json->>'presentation_model_hash','') is not null
          and v.payload_json->>'presentation_model_hash' is distinct from sm.frozen_model_hash
          then 'RENDER_MODEL_HASH_MISMATCH'
        when v.chunk_type='SOURCE_RENDER'
          and nullif(v.payload_json->>'presentation_model_schema_version','') is not null
          and v.payload_json->>'presentation_model_schema_version' is distinct from sm.frozen_model_schema_version
          then 'RENDER_MODEL_SCHEMA_MISMATCH'
        when v.chunk_type in('ASSET_INSPECT','ASSET_NORMALISE')
          and nullif(v.payload_json->>'source_revision','') is not null
          and v.payload_json->>'source_revision'<>v.asset_source_revision
          then 'SOURCE_REVISION_CHANGED'
        when v.chunk_type='SOURCE_RENDER'
          and nullif(v.payload_json->>'source_revision','') is not null
          and v.payload_json->>'source_revision'
            is distinct from sm.manifest_item->>'source_revision'
          then 'SOURCE_REVISION_CHANGED'
        when v.input_document_version_id is not null and v.input_document_status<>'READY'
          then 'INPUT_DOCUMENT_NOT_READY'
        when v.chunk_type='INVOICE_CORE_RENDER'
          and nullif(v.payload_json->>'presentation_model_hash','') is not null
          and v.payload_json->>'presentation_model_hash' is distinct from v.root_presentation_model_hash
          then 'RENDER_MODEL_HASH_MISMATCH'
        when v.chunk_type='INVOICE_CORE_RENDER'
          and nullif(v.payload_json->>'presentation_model_schema_version','') is not null
          and v.payload_json->>'presentation_model_schema_version' is distinct from v.root_presentation_schema_version
          then 'RENDER_MODEL_SCHEMA_MISMATCH'
        when v.chunk_type='DOCUMENT_VERIFY'
          and(coalesce(v.payload_json->>'candidate_r2_key','')=''
            or coalesce(v.payload_json->>'candidate_sha256','')='')
          then 'FINAL_CANDIDATE_MISSING'
      end context_error,
      case
        when v.chunk_type in('ASSET_INSPECT','ASSET_NORMALISE') then jsonb_build_object(
          'processor_policy_version',coalesce(v.processor_limits->>'policy_version',v.processor_limits->>'version'),
          'original_r2_key',v.original_r2_key,
          'expected_original_r2_key',case when v.chunk_type='ASSET_NORMALISE' then v.original_r2_key end,
          'expected_original_sha256',case when v.chunk_type='ASSET_NORMALISE' then v.original_sha256 end,
          'expected_original_size_bytes',case when v.chunk_type='ASSET_NORMALISE' then v.original_size_bytes end,
          'expected_original_media_type',case when v.chunk_type='ASSET_NORMALISE' then coalesce(v.detected_media_type,v.declared_media_type) end,
          'expected_source_revision',v.asset_source_revision,
          'expected_source_page_count',case when v.chunk_type='ASSET_NORMALISE' then v.source_page_count end,
          'allowed_media_types',v.processor_limits#>'{asset,allowed_media_types}',
          'max_source_bytes',v.processor_limits#>'{asset,max_source_bytes}',
          'original_filename',v.original_filename,
          'declared_media_type',v.declared_media_type,
          'detected_media_type',v.detected_media_type,
          'source_kind',v.source_kind,'source_id',v.source_id,
          'source_revision',v.asset_source_revision,
          'orientation_degrees',v.orientation_degrees,
          'source_page_count',v.source_page_count,
          'normalised_manifest',v.normalised_manifest_json,
          'page_range',v.payload_json->'page_range',
          'output_profile',coalesce(v.processor_limits->'asset','{}'::jsonb)
            ||jsonb_build_object(
              'mime_type','application/pdf','preserve_readability',true,
              'allow_upscale',false,'reject_encrypted',true),
          'immutable_destination_prefix','invoice-assets/'||v.document_asset_id||'/'||
            v.asset_source_revision||'/'||v.chunk_id||'/'||v.fence_token||'/')
        when v.chunk_type='SOURCE_RENDER' then jsonb_build_object(
          'render_kind',coalesce(sm.manifest_item->>'render_kind',
            sm.manifest_item->>'input_type',v.payload_json->>'render_kind'),
          'source_entity_type',sm.manifest_item->>'source_entity_type',
          'source_entity_id',sm.manifest_item->>'source_entity_id',
          'source_revision',sm.manifest_item->>'source_revision',
          'manifest_ordinal',sm.manifest_item->'ordinal',
          'frozen_presentation_model',coalesce(
            sm.frozen_model,'{}'::jsonb),
          'presentation_model_schema_version',sm.frozen_model_schema_version,
          'presentation_model_hash',sm.frozen_model_hash,
          'snapshot_hash',v.snapshot_hash,
          'render_variant',sm.frozen_model->>'form_variant',
          'source_template_version',sm.frozen_model->>'template_version',
          'layout_contract_version',sm.frozen_model->>'layout_contract_version',
          'one_page_required',sm.frozen_model#>'{layout,one_page_required}',
          'additional_units_hash',sm.frozen_model->>'additional_units_hash',
          'reference_signature',sm.frozen_model->>'reference_signature',
          'component_page_numbering',coalesce(
            sm.manifest_item->>'component_page_numbering','NONE'),
          'asset_dependencies',coalesce(sm.manifest_item->'asset_dependencies','[]'::jsonb),
          'attachment_index_layout',case
            when v.payload_json->>'render_kind'='ATTACHMENT_INDEX'
            then jsonb_build_object(
              'layout_phase',v.payload_json->>'layout_phase',
              'layout_pass',v.payload_json->'layout_pass',
              'max_layout_passes',v.payload_json->'max_layout_passes',
              'expected_index_page_count',
                v.payload_json->'expected_index_page_count',
               'core_page_count',v.payload_json->'core_page_count',
               'attachments',v.payload_json->'attachments',
               'display_rows',v.payload_json->'display_rows',
               'displayed_row_count',v.payload_json->'displayed_row_count',
               'pagination_stream',v.payload_json->'pagination_stream',
               'pagination_stream_hash',
                 v.payload_json->>'pagination_stream_hash',
               'expected_start_pages_hash',
                 v.payload_json->>'expected_start_pages_hash',
              'determinism',v.payload_json->'determinism',
              'prior_measurements',
                v.payload_json->'previous_layout_measurements')
            else null end,
          'template_version',coalesce(
            v.payload_json->>'template_version',
            sm.frozen_model->>'template_version',
            v.template_version),
          'processor_policy_version',coalesce(v.processor_limits->>'policy_version',v.processor_limits->>'version'),
          'immutable_destination_prefix','invoice-documents/'||v.document_version_id||
            '/source/'||v.chunk_id||'/'||v.fence_token||'/')
        when v.chunk_type='INVOICE_CORE_RENDER' then jsonb_build_object(
          'render_kind','INVOICE_CORE',
          'document_entity_type',v.document_entity_type,
          'document_entity_id',v.document_entity_id,
          'purpose',v.purpose,
          'source_revision',v.document_source_revision,
          'frozen_presentation_model',coalesce(v.root_presentation_model,'{}'::jsonb),
          'presentation_model_schema_version',v.root_presentation_schema_version,
          'presentation_model_hash',v.root_presentation_model_hash,
          'snapshot_hash',v.snapshot_hash,
          'attachment_index',coalesce(v.snapshot_json->'attachment_index','[]'::jsonb),
          'component_page_numbering',case
            when v.document_entity_type='INVOICE' then 'NONE'
            else 'LOCAL' end,
          'template_version',v.template_version,
          'processor_policy_version',coalesce(v.processor_limits->>'policy_version',v.processor_limits->>'version'),
          'immutable_destination_prefix','invoice-documents/'||v.document_version_id||
            '/core/'||v.chunk_id||'/'||v.fence_token||'/')
        when v.chunk_type='PDF_MERGE' then jsonb_build_object(
          'ordered_inputs',v.payload_json->'inputs',
          'merge_level',v.level_no,'sequence_no',v.sequence_no,
          'plan_generation',v.plan_generation,
          'apply_final_page_numbers',coalesce(
            (v.payload_json->>'apply_final_page_numbers')::boolean,false),
          'page_numbering_contract',
            v.payload_json->>'page_numbering_contract',
          'page_numbering_excluded_pages',coalesce(
            v.payload_json->'page_numbering_excluded_pages','[]'::jsonb),
          'document_entity_type',v.document_entity_type,
          'document_version_id',v.document_version_id,
          'expected_page_count',v.expected_page_count,
          'expected_byte_count',v.expected_byte_count,
          'expected_ordered_input_hash',
            v.payload_json->>'ordered_input_hash',
          'expected_child_receipt_hash',
            v.payload_json->>'expected_child_receipt_hash',
          'expected_logical_receipt_root',
            v.payload_json->>'expected_logical_receipt_root',
          'expected_physical_receipt_root',
            v.payload_json->>'expected_physical_receipt_root',
          'expected_parent_receipt_hash',encode(digest(
            jsonb_build_object(
              'child_receipt_hash',
                v.payload_json->>'expected_child_receipt_hash',
              'logical_receipt_root',
                v.payload_json->>'expected_logical_receipt_root',
              'physical_receipt_root',
                v.payload_json->>'expected_physical_receipt_root',
              'expected_page_count',v.expected_page_count,
              'plan_generation',v.plan_generation)::text,
            'sha256'),'hex'),
          'required_receipt_contract','ACTUAL_BYTES_MERGE_RECEIPT_V3',
          'required_object_receipt_contract',
            'ACTUAL_BYTES_OBJECT_RECEIPT_V3',
          'required_logical_receipt_contract',
            'LOGICAL_SOURCE_RECEIPT_V3',
          'source_revision',v.document_source_revision,
          'template_version',v.template_version,
          'receipt_evidence_requirements',jsonb_build_object(
            'hash_actual_fetched_bytes',true,
            'hash_algorithm','SHA-256',
            'parse_each_pdf',true,
            'report_actual_page_count',true,
            'report_actual_byte_count',true,
            'preserve_actual_input_order',true,
            'include_processor_and_parser_versions',true),
          'processor_policy_version',coalesce(v.processor_limits->>'policy_version',v.processor_limits->>'version'),
          'limits',coalesce(v.payload_json->'limits',
            v.processor_limits->'merge','{}'::jsonb),
          'immutable_destination_prefix','invoice-documents/'||v.document_version_id||
            '/merge/'||v.level_no||'/'||v.sequence_no||'/'||v.chunk_id||'/'||
            v.fence_token||'/')
        when v.chunk_type='DOCUMENT_VERIFY' then jsonb_build_object(
          'processor_policy_version',coalesce(v.processor_limits->>'policy_version',v.processor_limits->>'version'),
          'verification_mode','VERIFY_EXISTING_CANDIDATE',
          'final_candidate_key',v.payload_json->>'candidate_r2_key',
          'final_candidate_sha256',v.payload_json->>'candidate_sha256',
          'final_candidate_size_bytes',v.payload_json->'candidate_size_bytes',
          'expected_manifest_hash',v.manifest_hash,
          'expected_coverage_hash',v.payload_json->>'expected_coverage_hash',
          'expected_physical_input_count',
            v.payload_json->'expected_physical_input_count',
          'expected_physical_input_hash',
            v.payload_json->>'expected_physical_input_hash',
          'expected_page_count',v.expected_page_count,
          'expected_input_count',v.payload_json->'expected_input_count',
          'expected_logical_input_hash',
            v.payload_json->>'expected_coverage_hash',
          'resolved_logical_input_hash',
            v.payload_json->>'resolved_input_coverage_hash',
          'expected_physical_input_count',
            v.payload_json->'expected_physical_input_count',
          'expected_physical_input_hash',
            v.payload_json->>'expected_physical_input_hash',
          'expected_logical_source_count',
            v.payload_json->'expected_logical_source_count',
          'expected_logical_root_receipt',
            v.payload_json->>'expected_logical_root_receipt',
          'expected_physical_root_receipt',
            v.payload_json->>'expected_physical_root_receipt',
          'expected_ordered_input_root',
            v.payload_json->>'expected_ordered_input_root',
          'root_merge_receipt_identity',
            v.payload_json->>'root_merge_receipt_identity',
          'receipt_contract',v.payload_json->>'receipt_contract',
          'source_revision',v.document_source_revision,
          'template_version',v.template_version,
          'receipt_evidence_requirements',jsonb_build_object(
            'reopen_final_candidate',true,
            'verify_actual_final_hash',true,
            'verify_actual_final_page_count',true,
            'verify_root_receipt_chain',true),
          'plan_generation',v.payload_json->'plan_generation',
          'final_merge_receipt',v.payload_json->'final_merge_receipt',
          'final_merge_receipt_hash',
            v.payload_json->>'final_merge_receipt_hash',
          'verification_policy',v.processor_limits->'verify',
          'document_version_id',v.document_version_id)
        else '{}'::jsonb
      end context
    from valid v left join source_models sm on sm.chunk_id=v.chunk_id
  ),
  sized as materialized (
    select p.*,
      octet_length(p.context::text) context_size_bytes,
      case when coalesce(p.context_error,'')='' and octet_length(p.context::text)>
          case when coalesce(v.processor_limits->'context'->>v.chunk_type,'')~
              '^[0-9]{1,9}$'
            then(v.processor_limits->'context'->>v.chunk_type)::integer
            else 0 end
        then 'CONTEXT_TOO_LARGE'
        else p.context_error end sized_context_error
    from projected p join valid v on v.chunk_id=p.chunk_id
  ),
  all_results as (
    select i.request_no,jsonb_build_object(
      'chunk_id',i.chunk_id,'status','REJECTED','accepted',false,
      'code',i.ownership_error) result
    from inspected i where i.ownership_error is not null
    union all
    select p.request_no,
      case when p.sized_context_error is null then jsonb_build_object(
        'chunk_id',p.chunk_id,'operation_id',p.operation_id,
        'chunk_type',p.chunk_type,'phase',p.phase,
        'entity_type',p.entity_type,'entity_id',p.entity_id,
        'document_version_id',p.document_version_id,
        'document_asset_id',p.document_asset_id,
        'status','OK','accepted',true,
        'expected_result_identity',jsonb_build_object(
          'chunk_id',p.chunk_id,'fence_token',v.fence_token,
          'plan_generation',v.plan_generation,
          'action',p.chunk_type,'document_version_id',p.document_version_id,
          'document_asset_id',p.document_asset_id,
          'source_revision',p.context->>'source_revision',
          'template_version',p.context->>'template_version',
          'processor_policy_version',
            p.context->>'processor_policy_version',
          'immutable_destination_prefix',
            p.context->>'immutable_destination_prefix',
          'render_kind',p.context->>'render_kind',
          'presentation_model_schema_version',p.context->>'presentation_model_schema_version',
          'presentation_model_hash',p.context->>'presentation_model_hash',
          'snapshot_hash',p.context->>'snapshot_hash',
          'ordered_input_hash',coalesce(p.context->>'ordered_input_hash',p.context->>'expected_ordered_input_hash'),
          'apply_final_page_numbers',p.context->'apply_final_page_numbers',
          'page_numbering_contract',p.context->>'page_numbering_contract',
          'page_numbering_excluded_pages',
            p.context->'page_numbering_excluded_pages'),
        'context',p.context)
      else jsonb_build_object(
        'chunk_id',p.chunk_id,'operation_id',p.operation_id,
        'chunk_type',p.chunk_type,'phase',p.phase,
        'status','CONTEXT_ERROR','accepted',true,
        'permanent',p.sized_context_error<>'CONTEXT_TOO_LARGE',
        'retryable',p.sized_context_error='CONTEXT_TOO_LARGE',
        'code',p.sized_context_error,
        'context_size_bytes',p.context_size_bytes)
      end result
    from sized p join valid v on v.chunk_id=p.chunk_id
  )
  select coalesce(jsonb_agg(result order by request_no),'[]'::jsonb)
  into v_result from all_results;

  return v_result;
end;
$function$;

revoke all on function public.invoice_work_context_batch(jsonb,timestamptz)
  from public,anon,authenticated;
grant execute on function public.invoice_work_context_batch(jsonb,timestamptz)
  to service_role;

create or replace function public.invoice_work_complete_batch(
  p_results jsonb,
  p_now_utc timestamptz default now()
) returns jsonb
language plpgsql
security definer
set search_path to 'public','extensions','pg_temp'
as $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_valid_results jsonb:='[]'::jsonb;
  v_rejections jsonb:='[]'::jsonb;
  v_result jsonb:='[]'::jsonb;
  v_ignored integer;
begin
  if p_results is null or jsonb_typeof(p_results)<>'array' then
    raise exception using errcode='22023',
      message='p_results must be an array containing 1..100 items';
  end if;

  if jsonb_array_length(p_results)<1
     or jsonb_array_length(p_results)>100 then
    raise exception using errcode='22023',
      message='p_results must be an array containing 1..100 items';
  end if;

  /*
   * Ownership and payload validity are classified per item.  Ownership
   * failures are returned without mutation.  A current claim with a malformed
   * processor result is transitioned to a permanent failure or bounded retry;
   * it is never left RUNNING.
   */
  with supplied as materialized (
    select x.ordinality::integer request_no,x.value raw_result,
      case when coalesce(x.value->>'chunk_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then (x.value->>'chunk_id')::uuid end chunk_id,
      case when coalesce(x.value->>'lease_token','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then (x.value->>'lease_token')::uuid end lease_token,
      case when coalesce(x.value->>'fence_token','') ~ '^[0-9]{1,18}$'
        then (x.value->>'fence_token')::bigint end fence_token,
      case when coalesce(x.value->>'operation_control_version','') ~ '^[0-9]{1,18}$'
        then (x.value->>'operation_control_version')::bigint end operation_control_version,
      upper(coalesce(x.value->>'outcome','')) outcome,
      coalesce(x.value->'result','{}'::jsonb) processor_result,
      coalesce(x.value->'error','{}'::jsonb) processor_error
    from jsonb_array_elements(p_results) with ordinality x(value,ordinality)
  ),
  current_graph as materialized (
    select g.*
    from private._invoice_current_chunks_batch(
      coalesce((
        select array_agg(distinct c.operation_id)
        from supplied s
        join public.invoice_operation_chunks c on c.id=s.chunk_id),
        array['00000000-0000-0000-0000-000000000000'::uuid]),
      null,null,10000) g
  ),
  inspected as materialized (
    select s.*,c.operation_id,c.chunk_type,c.phase,c.plan_generation,
      c.level_no,c.sequence_no,
      c.entity_type,c.entity_id,
      c.document_version_id,c.document_asset_id,c.input_document_version_id,
      c.payload_json,c.expected_page_count,c.expected_byte_count,c.attempt_count,c.max_attempts,
      c.status current_status,c.lease_token current_lease_token,
      c.fence_token current_fence_token,c.operation_control_version current_control_version,
      c.lease_expires_at_utc,o.status operation_status,
      o.control_version operation_current_control_version,
      o.config_json->'processor_policy' processor_policy,
      a.source_revision asset_source_revision,
      a.original_r2_key registered_original_r2_key,
      a.original_sha256 registered_original_sha256,
      a.original_size_bytes registered_original_size_bytes,
      dv.source_revision document_source_revision,dv.manifest_hash,dv.manifest_json,
      dv.snapshot_json,dv.snapshot_hash,
      case
        when s.chunk_id is null or s.lease_token is null
          or s.fence_token is null or s.operation_control_version is null then 'INVALID_COMPLETION'
        when c.id is null then 'CHUNK_NOT_FOUND'
        when exists(select 1 from current_graph g
          where g.operation_id=c.operation_id
            and g.replacement_chain_status='INVALID')
          then 'INVALID_REPLACEMENT_GRAPH'
        when not exists(select 1 from current_graph g
          where g.current_chunk_id=c.id
            and g.replacement_chain_status='VALID')
          then 'CHUNK_NOT_CURRENT'
        when c.status<>'RUNNING' then 'CHUNK_NOT_RUNNING'
        when c.lease_token is distinct from s.lease_token then 'LEASE_TOKEN_MISMATCH'
        when c.fence_token is distinct from s.fence_token then 'FENCE_TOKEN_MISMATCH'
        when c.operation_control_version is distinct from s.operation_control_version
          or o.control_version is distinct from s.operation_control_version then 'CONTROL_VERSION_MISMATCH'
        when c.lease_expires_at_utc is null or c.lease_expires_at_utc<=v_now then 'LEASE_EXPIRED'
        when o.status in('COMPLETE','FAILED','DEAD_LETTER','CANCELLED','SUPERSEDED')
          then 'OPERATION_TERMINAL'
      end ownership_error
    from supplied s
    left join public.invoice_operation_chunks c on c.id=s.chunk_id
    left join public.invoice_operations o on o.id=c.operation_id
    left join public.invoice_document_assets a on a.id=c.document_asset_id
    left join public.invoice_document_versions dv on dv.id=c.document_version_id
  ),
  identified as materialized (
    select i.*,
      case
        when i.chunk_type in('ASSET_NORMALISE','ASSET_INSPECT')
          then 'invoice-assets/'||i.document_asset_id||'/'||
            coalesce(i.asset_source_revision,'')||'/'||i.chunk_id||'/'||
            i.fence_token||'/'
        when i.chunk_type='SOURCE_RENDER'
          then 'invoice-documents/'||i.document_version_id||'/source/'||
            i.chunk_id||'/'||i.fence_token||'/'
        when i.chunk_type='INVOICE_CORE_RENDER'
          then 'invoice-documents/'||i.document_version_id||'/core/'||
            i.chunk_id||'/'||i.fence_token||'/'
        when i.chunk_type='PDF_MERGE'
          then 'invoice-documents/'||i.document_version_id||'/merge/'||
            i.level_no||'/'||i.sequence_no||'/'||i.chunk_id||'/'||
            i.fence_token||'/'
        when i.chunk_type='DOCUMENT_VERIFY' then null
      end expected_output_prefix,
      case when coalesce(
          i.processor_policy->'result'->>i.chunk_type,'')~'^[1-9][0-9]{0,9}$'
        then(i.processor_policy->'result'->>i.chunk_type)::integer
      end result_limit_bytes
    from inspected i
  ),
  classified as materialized (
    select i.*,
      case
        when i.outcome not in('SUCCESS','RETRY','BLOCKED','FAILED','SUPERSEDED','CANCELLED')
          then 'INVALID_OUTCOME'
        when coalesce(i.processor_policy->>'policy_version',i.processor_policy->>'version')<>'INVOICE_PROCESSOR_LIMITS_V4'
          or i.result_limit_bytes is null
          then 'PROCESSOR_POLICY_INVALID'
        when jsonb_typeof(i.processor_result)<>'object'
          or octet_length(i.processor_result::text)>i.result_limit_bytes
          or lower(i.processor_result::text) ~
            '"(base64|file_bytes|raw_bytes|processor_dump)"[[:space:]]*:'
          then 'INVALID_RESULT_PAYLOAD'
        when i.outcome='SUCCESS' and(
          coalesce(i.processor_result->>'chunk_id','')<>i.chunk_id::text
          or coalesce(i.processor_result->>'fence_token','')<>i.fence_token::text
          or upper(coalesce(i.processor_result->>'action',''))<>
            case i.chunk_type
              when 'ASSET_INSPECT' then 'ASSET_INSPECT'
              when 'ASSET_NORMALISE' then 'ASSET_NORMALISE'
              when 'SOURCE_RENDER' then 'SOURCE_RENDER'
              when 'INVOICE_CORE_RENDER' then 'INVOICE_CORE_RENDER'
              when 'PDF_MERGE' then 'PDF_MERGE'
              when 'DOCUMENT_VERIFY' then 'DOCUMENT_VERIFY'
              else upper(i.chunk_type) end
          or(i.document_asset_id is not null
            and coalesce(i.processor_result->>'document_asset_id','')
              <>i.document_asset_id::text)
          or(i.document_version_id is not null
            and coalesce(i.processor_result->>'document_version_id','')
              <>i.document_version_id::text)
          or coalesce(i.processor_result->>'plan_generation','')<>
            i.plan_generation::text
          or coalesce(i.processor_result->>'processor_policy_version','')<>
            coalesce(i.processor_policy->>'policy_version',i.processor_policy->>'version','')
          or(i.chunk_type<>'DOCUMENT_VERIFY' and
            coalesce(i.processor_result->>'output_prefix','')<>
              coalesce(i.expected_output_prefix,''))
          or(i.document_version_id is not null
            and nullif(i.document_source_revision,'') is not null
            and coalesce(i.processor_result->>'template_version','')<>
              case when i.chunk_type='SOURCE_RENDER'
                then coalesce(i.payload_json->>'template_version','')
                else coalesce((select v.template_version
                  from public.invoice_document_versions v
                  where v.id=i.document_version_id),'')
              end)
          or(i.chunk_type in('SOURCE_RENDER','INVOICE_CORE_RENDER')
            and coalesce(i.processor_result->>'render_kind','')<>
              coalesce(i.payload_json->>'render_kind',
                case when i.chunk_type='INVOICE_CORE_RENDER'
                  then 'INVOICE_CORE' end,''))
          or(i.chunk_type='PDF_MERGE'
            and coalesce(i.processor_result->>'ordered_input_hash','')<>
              coalesce(i.payload_json->>'ordered_input_hash',''))
          or(i.chunk_type='PDF_MERGE'
            and coalesce(i.processor_result->>'apply_final_page_numbers','false')
              is distinct from coalesce(
                i.payload_json->>'apply_final_page_numbers','false'))
          or(i.chunk_type='PDF_MERGE'
            and coalesce(i.processor_result->>'page_numbering_contract','')
              is distinct from coalesce(
                i.payload_json->>'page_numbering_contract',''))
          or(i.chunk_type='PDF_MERGE'
            and coalesce(i.processor_result->'page_numbering_excluded_pages',
                  '[]'::jsonb)
              is distinct from coalesce(
                i.payload_json->'page_numbering_excluded_pages','[]'::jsonb))
        ) then 'PROCESSOR_RESULT_IDENTITY_MISMATCH'
        when i.outcome='SUCCESS'
          and i.chunk_type in('SOURCE_RENDER','INVOICE_CORE_RENDER')
          and (
            /*
             * Render completion must prove the same frozen presentation model
             * identity that was planned and handed out by context.  For source
             * renders the source-model identity must come from the chunk
             * payload / expected_result_identity; we deliberately do not fall
             * back to the invoice-root model hash for source chunks.
             */
            nullif(coalesce(
              i.processor_result->>'presentation_model_schema_version',
              i.processor_result#>>'{render_identity,presentation_model_schema_version}',
              i.processor_result#>>'{identity,presentation_model_schema_version}',
              ''),'') is null
            or nullif(coalesce(
              i.processor_result->>'presentation_model_hash',
              i.processor_result#>>'{render_identity,presentation_model_hash}',
              i.processor_result#>>'{identity,presentation_model_hash}',
              ''),'') is null
            or nullif(coalesce(
              i.processor_result->>'snapshot_hash',
              i.processor_result#>>'{render_identity,snapshot_hash}',
              i.processor_result#>>'{identity,snapshot_hash}',
              ''),'') is null
            or nullif(coalesce(
              i.payload_json->>'presentation_model_schema_version',
              i.payload_json#>>'{expected_result_identity,presentation_model_schema_version}',
              case when i.chunk_type='INVOICE_CORE_RENDER'
                then i.snapshot_json#>>'{presentation_model,schema_version}' end,
              ''),'') is null
            or nullif(coalesce(
              i.payload_json->>'presentation_model_hash',
              i.payload_json#>>'{expected_result_identity,presentation_model_hash}',
              case when i.chunk_type='INVOICE_CORE_RENDER'
                then i.snapshot_json->>'presentation_model_hash' end,
              ''),'') is null
            or nullif(coalesce(
              i.payload_json->>'snapshot_hash',
              i.payload_json#>>'{expected_result_identity,snapshot_hash}',
              i.snapshot_hash,
              ''),'') is null
            or nullif(coalesce(
              i.processor_result->>'presentation_model_schema_version',
              i.processor_result#>>'{render_identity,presentation_model_schema_version}',
              i.processor_result#>>'{identity,presentation_model_schema_version}',
              ''),'') is distinct from nullif(coalesce(
              i.payload_json->>'presentation_model_schema_version',
              i.payload_json#>>'{expected_result_identity,presentation_model_schema_version}',
              case when i.chunk_type='INVOICE_CORE_RENDER'
                then i.snapshot_json#>>'{presentation_model,schema_version}' end,
              ''),'')
            or nullif(coalesce(
              i.processor_result->>'presentation_model_hash',
              i.processor_result#>>'{render_identity,presentation_model_hash}',
              i.processor_result#>>'{identity,presentation_model_hash}',
              ''),'') is distinct from nullif(coalesce(
              i.payload_json->>'presentation_model_hash',
              i.payload_json#>>'{expected_result_identity,presentation_model_hash}',
              case when i.chunk_type='INVOICE_CORE_RENDER'
                then i.snapshot_json->>'presentation_model_hash' end,
              ''),'')
            or nullif(coalesce(
              i.processor_result->>'snapshot_hash',
              i.processor_result#>>'{render_identity,snapshot_hash}',
              i.processor_result#>>'{identity,snapshot_hash}',
              ''),'') is distinct from nullif(coalesce(
              i.payload_json->>'snapshot_hash',
              i.payload_json#>>'{expected_result_identity,snapshot_hash}',
              i.snapshot_hash,
              ''),'')
          ) then 'RENDER_MODEL_IDENTITY_MISMATCH'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and lower(coalesce(i.processor_result->>'detected_media_type',
            i.processor_result->>'detected_kind','')) in('','unknown','application/octet-stream')
          then 'ASSET_MEDIA_TYPE_UNSUPPORTED'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and lower(coalesce(i.processor_result->>'detected_kind',''))='empty'
          then 'ASSET_EMPTY'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and lower(coalesce(i.processor_result->>'detected_kind',''))='truncated'
          then 'ASSET_TRUNCATED'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and lower(coalesce(i.processor_result->>'detected_kind',''))='missing'
          then 'MISSING_SOURCE'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and coalesce(i.processor_result->>'is_encrypted','false')='true'
          then 'ASSET_PDF_ENCRYPTED'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and lower(coalesce(i.processor_result->>'detected_media_type',
            i.processor_result->>'detected_kind','')) not in(
              'application/pdf','pdf','image/jpeg','jpeg','jpg','image/png','png')
          then 'ASSET_MEDIA_TYPE_UNSUPPORTED'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and(coalesce(i.processor_result->>'original_size_bytes','') !~ '^[0-9]{1,18}$'
            or case when coalesce(i.processor_result->>'original_size_bytes','')
                ~ '^[0-9]{1,18}$'
              then(i.processor_result->>'original_size_bytes')::bigint
              else 0 end<=0
            or coalesce(i.processor_result->>'original_sha256','')
              !~ '^[0-9a-f]{64}$')
          then 'INVALID_INSPECTION_RESULT'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and(
            (i.processor_result->>'original_size_bytes')::bigint>
              (i.processor_policy#>>'{asset,max_source_bytes}')::bigint
            or not exists(
              select 1
              from jsonb_array_elements_text(
                i.processor_policy#>'{asset,allowed_media_types}') allowed(media_type)
              where allowed.media_type=lower(
                i.processor_result->>'detected_media_type')))
          then 'ASSET_SOURCE_SIZE_EXCEEDED'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and lower(coalesce(i.processor_result->>'detected_media_type',
            i.processor_result->>'detected_kind','')) in('application/pdf','pdf')
          and(coalesce(i.processor_result->>'page_count','') !~ '^[1-9][0-9]{0,8}$'
            or coalesce(i.processor_result->>'parse_verified','false')<>'true'
            or coalesce(i.processor_result->>'is_encrypted','false')<>'false')
          then 'INVALID_PDF_INSPECTION_RESULT'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and lower(coalesce(i.processor_result->>'detected_media_type',
            i.processor_result->>'detected_kind','')) in(
              'image/jpeg','jpeg','jpg','image/png','png')
          and(coalesce(i.processor_result->>'width_pixels','') !~ '^[1-9][0-9]{0,8}$'
            or coalesce(i.processor_result->>'height_pixels','') !~ '^[1-9][0-9]{0,8}$'
            or coalesce(i.processor_result->>'estimated_decoded_bytes','')
              !~ '^[1-9][0-9]{0,17}$'
            or coalesce(i.processor_result->>'decode_verified','false')<>'true'
            or coalesce(i.processor_result->>'orientation_degrees','')
              !~ '^(0|90|180|270)$')
          then 'INVALID_IMAGE_INSPECTION_RESULT'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and lower(coalesce(i.processor_result->>'detected_media_type',
            i.processor_result->>'detected_kind','')) in(
              'image/jpeg','jpeg','jpg','image/png','png')
          and(
            (i.processor_result->>'width_pixels')::bigint*
              (i.processor_result->>'height_pixels')::bigint>
                (i.processor_policy#>>'{asset,max_pixels}')::bigint
            or(i.processor_result->>'estimated_decoded_bytes')::bigint>
                (i.processor_policy#>>'{asset,max_decoded_bytes}')::bigint)
          then 'ASSET_DECODE_POLICY_EXCEEDED'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_INSPECT'
          and i.registered_original_sha256 is not null
          and i.processor_result->>'original_sha256'
            is distinct from i.registered_original_sha256
          then 'ORIGINAL_HASH_MISMATCH'
        when i.outcome='SUCCESS'
          and i.chunk_type in('ASSET_NORMALISE','SOURCE_RENDER','INVOICE_CORE_RENDER','PDF_MERGE')
          and(coalesce(i.processor_result->>'r2_key','')=''
            or coalesce(i.processor_result->>'sha256','')
              !~ '^[0-9a-f]{64}$'
            or coalesce(i.processor_result->>'size_bytes','') !~ '^[0-9]{1,18}$'
            or case when coalesce(i.processor_result->>'size_bytes','')
                ~ '^[0-9]{1,18}$'
              then(i.processor_result->>'size_bytes')::bigint else 0 end<=0
            or coalesce(i.processor_result->>'page_count','') !~ '^[0-9]{1,9}$'
            or case when coalesce(i.processor_result->>'page_count','')
                ~ '^[0-9]{1,9}$'
              then(i.processor_result->>'page_count')::integer else 0 end<=0
            or coalesce(i.processor_result->>'parse_verified','false')<>'true')
          then 'INVALID_ARTIFACT_RESULT'
        when i.outcome='SUCCESS'
          and i.chunk_type in('ASSET_NORMALISE','SOURCE_RENDER','INVOICE_CORE_RENDER','PDF_MERGE')
          and left(i.processor_result->>'r2_key',length(
            case
              when i.chunk_type in('ASSET_NORMALISE','ASSET_INSPECT')
                then 'invoice-assets/'||i.document_asset_id||'/'||
                  coalesce(i.asset_source_revision,'')||'/'||i.chunk_id||'/'||
                  i.fence_token||'/'
              when i.chunk_type='SOURCE_RENDER'
                then 'invoice-documents/'||i.document_version_id||'/source/'||
                  i.chunk_id||'/'||i.fence_token||'/'
              when i.chunk_type='INVOICE_CORE_RENDER'
                then 'invoice-documents/'||i.document_version_id||'/core/'||
                  i.chunk_id||'/'||i.fence_token||'/'
              when i.chunk_type='PDF_MERGE'
                then 'invoice-documents/'||i.document_version_id||'/merge/'||
                  i.level_no||'/'||i.sequence_no||'/'||
                  i.chunk_id||'/'||i.fence_token||'/'
              else 'invoice-documents/'||i.document_version_id||'/verify/'||
                i.chunk_id||'/'||i.fence_token||'/'
            end)) is distinct from
            case
              when i.chunk_type in('ASSET_NORMALISE','ASSET_INSPECT')
                then 'invoice-assets/'||i.document_asset_id||'/'||
                  coalesce(i.asset_source_revision,'')||'/'||i.chunk_id||'/'||
                  i.fence_token||'/'
              when i.chunk_type='SOURCE_RENDER'
                then 'invoice-documents/'||i.document_version_id||'/source/'||
                  i.chunk_id||'/'||i.fence_token||'/'
              when i.chunk_type='INVOICE_CORE_RENDER'
                then 'invoice-documents/'||i.document_version_id||'/core/'||
                  i.chunk_id||'/'||i.fence_token||'/'
              when i.chunk_type='PDF_MERGE'
                then 'invoice-documents/'||i.document_version_id||'/merge/'||
                  i.level_no||'/'||i.sequence_no||'/'||
                  i.chunk_id||'/'||i.fence_token||'/'
              else 'invoice-documents/'||i.document_version_id||'/verify/'||
                i.chunk_id||'/'||i.fence_token||'/'
            end
          then 'OUTPUT_IDENTITY_MISMATCH'
        when i.outcome='SUCCESS' and i.chunk_type='PDF_MERGE'
          and(coalesce(i.processor_result->>'input_count','') !~ '^[0-9]{1,9}$'
            or case when coalesce(i.processor_result->>'input_count','')
                ~ '^[0-9]{1,9}$'
              then(i.processor_result->>'input_count')::integer else -1 end<>
                jsonb_array_length(coalesce(i.payload_json->'inputs','[]'::jsonb))
            or coalesce(i.processor_result->>'ordered_input_hash','')<>
              coalesce(i.payload_json->>'ordered_input_hash',''))
          then 'MERGE_INPUT_MISMATCH'
        when i.outcome='SUCCESS' and i.chunk_type='PDF_MERGE'
          and(
            jsonb_typeof(i.processor_result->'input_receipts')<>'array'
            or jsonb_array_length(i.processor_result->'input_receipts')<>
              jsonb_array_length(coalesce(i.payload_json->'inputs','[]'::jsonb))
            or exists(
              select 1
              from jsonb_array_elements(coalesce(
                i.payload_json->'inputs','[]'::jsonb))
                with ordinality expected(value,ordinality)
              full join jsonb_array_elements(coalesce(
                i.processor_result->'input_receipts','[]'::jsonb))
                with ordinality actual(value,ordinality)
                using(ordinality)
              where expected.value is null or actual.value is null
                or actual.value->>'input_chunk_id'
                  is distinct from expected.value->>'input_chunk_id'
                or actual.value->>'actual_input_order'
                  is distinct from expected.value->>'input_order'
                or actual.value->>'actual_input_order'
                  is distinct from actual.ordinality::text
                or actual.value->>'actual_r2_key'
                  is distinct from expected.value->>'r2_key'
                or actual.value->>'actual_sha256'
                  is distinct from expected.value->>'sha256'
                or actual.value->>'actual_page_count'
                  is distinct from expected.value->>'page_count'
                or actual.value->>'actual_size_bytes'
                  is distinct from expected.value->>'size_bytes'
                or(
                  expected.value?'expected_physical_receipt'
                  and(
                    actual.value->>'logical_source_key'
                      is distinct from expected.value->>'logical_source_key'
                    or actual.value->>'logical_manifest_ordinal'
                      is distinct from
                        expected.value->>'logical_manifest_ordinal'
                    or actual.value->>'physical_part_no'
                      is distinct from expected.value->>'physical_part_no'
                    or actual.value->>'actual_physical_receipt'
                      is distinct from
                        expected.value->>'expected_physical_receipt'
                    or actual.value->>'actual_physical_receipt'
                      is distinct from encode(digest(jsonb_build_object(
                        'receipt_contract','ACTUAL_BYTES_OBJECT_RECEIPT_V3',
                        'logical_source_key',
                          actual.value->>'logical_source_key',
                        'logical_manifest_ordinal',
                          case when coalesce(actual.value->>
                              'logical_manifest_ordinal','')~'^[0-9]{1,9}$'
                            then(actual.value->>
                              'logical_manifest_ordinal')::integer end,
                        'physical_part_no',
                          case when coalesce(actual.value->>
                              'physical_part_no','')~'^[1-9][0-9]{0,8}$'
                            then(actual.value->>
                              'physical_part_no')::integer end,
                        'object_key',actual.value->>'actual_r2_key',
                        'stored_sha256',actual.value->>'actual_sha256',
                        'expected_page_count',
                          case when coalesce(actual.value->>
                              'actual_page_count','')~'^[1-9][0-9]{0,8}$'
                            then(actual.value->>
                              'actual_page_count')::integer end,
                        'expected_byte_count',
                          case when coalesce(actual.value->>
                              'actual_size_bytes','')~'^[1-9][0-9]{0,17}$'
                            then(actual.value->>
                              'actual_size_bytes')::bigint end
                      )::text,'sha256'),'hex')))
                or(
                  expected.value?'child_merge_receipt_hash'
                  and(
                    actual.value->'actual_child_merge_receipt'
                      is distinct from expected.value->'child_merge_receipt'
                    or encode(digest(coalesce(actual.value->
                        'actual_child_merge_receipt','{}'::jsonb)::text,
                      'sha256'),'hex')
                        is distinct from
                          expected.value->>'child_merge_receipt_hash'
                    or actual.value->>'actual_child_merge_receipt_hash'
                      is distinct from
                        expected.value->>'child_merge_receipt_hash'))
            ))
          then 'MERGE_RECEIPT_MISMATCH'
        when i.outcome='SUCCESS' and i.chunk_type='PDF_MERGE'
          and(
            jsonb_typeof(i.processor_result->'merge_receipt')<>'object'
            or coalesce(i.processor_result#>>
              '{merge_receipt,receipt_contract}','')<>
                'ACTUAL_BYTES_MERGE_RECEIPT_V3'
            or jsonb_typeof(i.processor_result#>
              '{merge_receipt,input_receipts}')<>'array'
            or i.processor_result#>'{merge_receipt,input_receipts}'
              is distinct from i.processor_result->'input_receipts'
            or nullif(i.processor_result#>>
              '{merge_receipt,processor_version}','') is null
            or coalesce(i.processor_result#>>
              '{merge_receipt,processor_policy_version}','')<>
                coalesce(i.processor_policy->>'policy_version',i.processor_policy->>'version','')
            or coalesce(i.processor_result#>>
              '{merge_receipt,actual_ordered_input_hash}','')<>
                coalesce(i.payload_json->>'ordered_input_hash','')
            or coalesce(i.processor_result#>>
              '{merge_receipt,output_sha256}','')<>
                coalesce(i.processor_result->>'sha256','')
            or coalesce(i.processor_result#>>
              '{merge_receipt,output_page_count}','')<>
                coalesce(i.processor_result->>'page_count','')
            or coalesce(i.processor_result#>>
              '{merge_receipt,actual_child_receipt_hash}','')<>
                coalesce(i.payload_json->>'expected_child_receipt_hash','')
            or coalesce(i.processor_result#>>
              '{merge_receipt,actual_child_receipt_hash}','')<>
              coalesce((
                select encode(digest(string_agg(coalesce(
                  nullif(r.value->>'actual_physical_receipt',''),
                  encode(digest(coalesce(r.value->
                    'actual_child_merge_receipt','{}'::jsonb)::text,
                    'sha256'),'hex')),'||'
                  order by r.ordinality),'sha256'),'hex')
                from jsonb_array_elements(coalesce(
                  i.processor_result->'input_receipts','[]'::jsonb))
                  with ordinality r(value,ordinality)
              ),'')
            or i.processor_result#>'{merge_receipt,physical_receipts}'
                is distinct from
                  coalesce(i.payload_json->'expected_physical_receipts',
                    '[]'::jsonb)
            or coalesce(i.processor_result#>>
              '{merge_receipt,combined_logical_receipt_root}','')<>
                coalesce(i.payload_json->>'expected_logical_receipt_root','')
            or coalesce(i.processor_result#>>
              '{merge_receipt,combined_physical_receipt_root}','')<>
                coalesce(i.payload_json->>'expected_physical_receipt_root','')
            or coalesce(i.processor_result#>>
              '{merge_receipt,combined_physical_receipt_root}','')<>
              coalesce((
                select encode(digest(string_agg(
                  r.value->>'physical_receipt','||'
                  order by
                    case when coalesce(r.value->>
                        'logical_manifest_ordinal','')~'^[0-9]{1,9}$'
                      then(r.value->>
                        'logical_manifest_ordinal')::integer end,
                    case when coalesce(r.value->>
                        'physical_part_no','')~'^[1-9][0-9]{0,8}$'
                      then(r.value->>'physical_part_no')::integer end,
                    r.ordinality),'sha256'),'hex')
                from jsonb_array_elements(coalesce(i.processor_result#>
                  '{merge_receipt,physical_receipts}','[]'::jsonb))
                  with ordinality r(value,ordinality)
                where coalesce(r.value->>'physical_receipt','')
                  ~'^[0-9a-f]{64}$'
              ),'')
            or coalesce(i.processor_result#>>
              '{merge_receipt,combined_logical_receipt_root}','')<>
              coalesce((
                select encode(digest(string_agg(
                  logical.logical_receipt,'||'
                  order by logical.logical_manifest_ordinal,
                    logical.logical_source_key),'sha256'),'hex')
                from(
                  select r.value->>'logical_source_key'
                      logical_source_key,
                    min(case when coalesce(r.value->>
                        'logical_manifest_ordinal','')~'^[0-9]{1,9}$'
                      then(r.value->>
                        'logical_manifest_ordinal')::integer end)
                      logical_manifest_ordinal,
                    encode(digest(jsonb_build_object(
                      'receipt_contract','LOGICAL_SOURCE_RECEIPT_V3',
                      'logical_source_key',
                        r.value->>'logical_source_key',
                      'logical_manifest_ordinal',
                        min(case when coalesce(r.value->>
                            'logical_manifest_ordinal','')
                              ~'^[0-9]{1,9}$'
                          then(r.value->>
                            'logical_manifest_ordinal')::integer end),
                      'ordered_physical_receipts',string_agg(
                        r.value->>'physical_receipt','||'
                        order by case when coalesce(r.value->>
                            'logical_manifest_ordinal','')
                              ~'^[0-9]{1,9}$'
                          then(r.value->>
                            'logical_manifest_ordinal')::integer end,
                          case when coalesce(r.value->>
                            'physical_part_no','')
                              ~'^[1-9][0-9]{0,8}$'
                          then(r.value->>
                            'physical_part_no')::integer end,
                          r.ordinality)
                    )::text,'sha256'),'hex') logical_receipt
                  from jsonb_array_elements(coalesce(
                    i.processor_result#>
                      '{merge_receipt,physical_receipts}',
                    '[]'::jsonb)) with ordinality r(value,ordinality)
                  where nullif(r.value->>
                      'logical_source_key','') is not null
                    and coalesce(r.value->>'physical_receipt','')
                      ~'^[0-9a-f]{64}$'
                  group by r.value->>'logical_source_key'
                ) logical
              ),'')
            or coalesce(i.processor_result#>>
              '{merge_receipt,plan_generation}','')<>
                i.plan_generation::text
            or coalesce(i.processor_result#>>
              '{merge_receipt,page_numbering_applied}','false')<>
                coalesce(i.payload_json->>'apply_final_page_numbers','false')
            or coalesce(i.processor_result#>>
              '{merge_receipt,page_numbering_contract}','')<>
                coalesce(i.payload_json->>'page_numbering_contract','')
            or coalesce(i.processor_result#>
              '{merge_receipt,page_numbering_excluded_pages}','[]'::jsonb)<>
                coalesce(i.payload_json->'page_numbering_excluded_pages',
                  '[]'::jsonb)
          ) then 'MERGE_RECEIPT_CHAIN_MISMATCH'
        when i.outcome='SUCCESS' and i.chunk_type='PDF_MERGE'
          and(i.expected_page_count is null
            or case when coalesce(i.processor_result->>'page_count','')
                ~ '^[0-9]{1,9}$'
              then(i.processor_result->>'page_count')::integer else -1 end<>
                i.expected_page_count)
          then 'MERGE_PAGE_COUNT_MISMATCH'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_NORMALISE'
          and(coalesce(i.processor_result->>'consumed_original_r2_key','')<>coalesce(i.registered_original_r2_key,'')
            or coalesce(i.processor_result->>'consumed_original_sha256','')<>coalesce(i.registered_original_sha256,'')
            or coalesce(i.processor_result->>'consumed_original_size_bytes','')<>coalesce(i.registered_original_size_bytes::text,''))
          then 'ASSET_SOURCE_IDENTITY_CHANGED'
        when i.outcome='SUCCESS' and i.chunk_type='ASSET_NORMALISE'
          and(i.expected_page_count is null
            or case when coalesce(i.processor_result->>'page_count','')
                ~ '^[0-9]{1,9}$'
              then(i.processor_result->>'page_count')::integer else -1 end<>
                i.expected_page_count)
          then 'ASSET_PART_PAGE_COUNT_MISMATCH'
        when i.outcome='SUCCESS'
          and i.chunk_type in('SOURCE_RENDER','INVOICE_CORE_RENDER')
          and(
            lower(coalesce(i.processor_result->>'output_type','')) not in(
              'pdf','application/pdf')
            or coalesce(i.processor_result->>'template_version','')<>
              coalesce(i.payload_json->>'template_version','')
            or coalesce(i.processor_result->>'render_kind','')<>
              coalesce(i.payload_json->>'render_kind','')
            or coalesce(i.processor_result->>'document_version_id','')<>
              i.document_version_id::text)
          then 'RENDER_CONTRACT_MISMATCH'
        when i.outcome='SUCCESS' and i.chunk_type='SOURCE_RENDER'
          and i.payload_json->>'render_kind'='ATTACHMENT_INDEX'
          and(
            coalesce(i.processor_result->>'layout_phase','')<>
              coalesce(i.payload_json->>'layout_phase','')
            or coalesce(i.processor_result->>'layout_pass','')<>
              coalesce(i.payload_json->>'layout_pass','')
            or coalesce(i.processor_result->>'layout_page_count','')<>
              coalesce(i.processor_result->>'page_count','')
            or nullif(i.processor_result->>'processor_version','') is null
            or coalesce(i.processor_result->>'processor_policy_version','')<>
              coalesce(i.processor_policy->>'policy_version',i.processor_policy->>'version','')
            or(i.payload_json->>'layout_phase'='FINAL'
              and(
                coalesce(i.processor_result->>'displayed_start_pages_hash','')<>
                  coalesce(i.payload_json->>'expected_start_pages_hash','')
                or jsonb_typeof(i.processor_result->'displayed_page_map')<>'array'
                or i.processor_result->'displayed_page_map'
                  is distinct from i.payload_json->'attachments'
                or encode(digest(coalesce(
                    i.processor_result->'displayed_page_map','[]'::jsonb)::text,
                    'sha256'),'hex')<>
                  coalesce(i.payload_json->>'expected_start_pages_hash','')
                or coalesce(i.processor_result->>'displayed_page_map_hash','')<>
                  coalesce(i.payload_json->>'expected_start_pages_hash','')
                or coalesce(i.processor_result->>'displayed_row_count','')<>
                  coalesce(i.payload_json->>'displayed_row_count','')
                or coalesce(i.processor_result->>'final_index_page_count','')<>
                  coalesce(i.processor_result->>'page_count','')
                or coalesce(i.processor_result->>'pagination_stream_hash','')<>
                  coalesce(i.payload_json->>'pagination_stream_hash','')
                or coalesce(i.processor_result->>'layout_identity_hash','')<>
                  encode(digest(coalesce(i.payload_json->'determinism',
                    '{}'::jsonb)::text,'sha256'),'hex')
                or coalesce(i.processor_result->>'displayed_rows_verified','false')
                  <>'true'))
          ) then 'ATTACHMENT_INDEX_CONTRACT_MISMATCH'
        when i.outcome='SUCCESS' and i.chunk_type='DOCUMENT_VERIFY'
          and(coalesce(i.processor_result->>'manifest_coverage_verified','false')<>'true'
            or coalesce(i.processor_result->>'ordering_verified','false')<>'true'
            or coalesce(i.processor_result->>'manifest_hash','')<>i.manifest_hash
            or coalesce(i.processor_result->>'root_merge_receipt_hash','')<>
              coalesce(i.payload_json->>'final_merge_receipt_hash','')
            or encode(digest(coalesce(
              i.payload_json->'final_merge_receipt','{}'::jsonb)::text,
              'sha256'),'hex')<>
              coalesce(i.payload_json->>'final_merge_receipt_hash','')
            or coalesce(i.payload_json#>>
              '{final_merge_receipt,receipt_contract}','')<>
                'ACTUAL_BYTES_MERGE_RECEIPT_V3'
            or coalesce(i.payload_json#>>
              '{final_merge_receipt,combined_logical_receipt_root}','')<>
                coalesce(i.payload_json->>
                  'expected_logical_root_receipt','')
            or coalesce(i.payload_json#>>
              '{final_merge_receipt,combined_physical_receipt_root}','')<>
                coalesce(i.payload_json->>
                  'expected_physical_root_receipt','')
            or coalesce(i.payload_json#>>
              '{final_merge_receipt,actual_child_receipt_hash}','')<>
                coalesce(i.payload_json->>'expected_ordered_input_root','')
            or coalesce(i.payload_json#>>
              '{final_merge_receipt,output_page_count}','')<>
                coalesce(i.payload_json->>'independent_expected_page_count','')
            or coalesce(i.payload_json#>>
              '{final_merge_receipt,output_sha256}','')<>
                coalesce(i.payload_json->>'candidate_sha256','')
            or coalesce(i.processor_result->>
              'root_merge_receipt_identity','')<>
                coalesce(i.payload_json->>'root_merge_receipt_identity','')
            or coalesce(i.processor_result->>
              'actual_logical_root_receipt','')<>
                coalesce(i.payload_json->>
                  'expected_logical_root_receipt','')
            or coalesce(i.processor_result->>
              'actual_physical_root_receipt','')<>
                coalesce(i.payload_json->>
                  'expected_physical_root_receipt','')
            or coalesce(i.processor_result->>
              'actual_ordered_input_root','')<>
                coalesce(i.payload_json->>'expected_ordered_input_root','')
            or encode(digest(jsonb_build_object(
                'receipt_contract','DOCUMENT_ROOT_RECEIPT_V3',
                'logical_root',i.processor_result->>
                  'actual_logical_root_receipt',
                'physical_root',i.processor_result->>
                  'actual_physical_root_receipt',
                'ordered_input_root',i.processor_result->
                  'actual_ordered_input_root',
                'page_count',case when coalesce(
                    i.processor_result->>'actual_page_count','')~'^[1-9][0-9]{0,8}$'
                  then(i.processor_result->>'actual_page_count')::integer end,
                'output_sha256',i.processor_result->>'verified_candidate_sha256')::text,
              'sha256'),'hex')<>
                coalesce(i.payload_json->>'root_merge_receipt_identity','')
            or coalesce(i.processor_result->>
              'verified_candidate_sha256','')<>
                coalesce(i.payload_json->>'candidate_sha256','')
            or coalesce(i.processor_result->>'verified_candidate_size_bytes','')<>
                coalesce(i.payload_json->>'candidate_size_bytes','')
            or coalesce(i.processor_result->>'actual_page_count','')<>
                coalesce(i.expected_page_count::text,'')
            or coalesce(i.processor_result->>
              'verified_candidate_r2_key','')<>
                coalesce(i.payload_json->>'candidate_r2_key','')
            or coalesce(i.payload_json->>'resolved_input_coverage_hash','')<>
              coalesce(i.payload_json->>'expected_coverage_hash','')
            or coalesce(i.processor_result->>'assembled_input_coverage_hash','')<>
              coalesce(i.payload_json->>'expected_coverage_hash','')
            or coalesce(i.processor_result->>'assembled_input_count','')!~
              '^[0-9]{1,9}$'
            or case when coalesce(
                i.processor_result->>'assembled_input_count','')~'^[0-9]{1,9}$'
              then(i.processor_result->>'assembled_input_count')::integer end
                is distinct from case when coalesce(
                  i.payload_json->>'expected_input_count','')~'^[0-9]{1,9}$'
                  then(i.payload_json->>'expected_input_count')::integer end
            or coalesce(
                i.processor_result->>'assembled_physical_input_count','')
                !~ '^[0-9]{1,9}$'
            or jsonb_typeof(i.processor_result->'actual_input_receipts')<>'array'
            or case when coalesce(
                i.processor_result->>'assembled_physical_input_count','')
                  ~'^[0-9]{1,9}$'
              then(i.processor_result->>
                'assembled_physical_input_count')::integer end
                is distinct from case when coalesce(
                  i.payload_json->>'expected_physical_input_count','')
                    ~'^[0-9]{1,9}$'
                  then(i.payload_json->>
                    'expected_physical_input_count')::integer end
            or coalesce(
                i.processor_result->>'assembled_physical_input_hash','')<>
              coalesce(i.payload_json->>'expected_physical_input_hash','')
            or coalesce((
              select encode(digest(string_agg(concat_ws('|',
                receipt.value->>'logical_ordinal',
                receipt.value->>'physical_part_no',
                receipt.value->>'r2_key',
                receipt.value->>'sha256'),'||'
                 order by case when coalesce(
                     receipt.value->>'logical_ordinal','')~'^[0-9]{1,9}$'
                     then(receipt.value->>'logical_ordinal')::integer end,
                   case when coalesce(
                     receipt.value->>'physical_part_no','')
                       ~'^[1-9][0-9]{0,8}$'
                     then(receipt.value->>'physical_part_no')::integer end),
                'sha256'),'hex')
              from jsonb_array_elements(
                case when jsonb_typeof(
                    i.processor_result->'actual_input_receipts')='array'
                  then i.processor_result->'actual_input_receipts'
                  else '[]'::jsonb end) receipt(value)
              where coalesce(receipt.value->>'logical_ordinal','')~'^[0-9]{1,9}$'
                and coalesce(receipt.value->>'physical_part_no','')~'^[1-9][0-9]{0,8}$'
                and nullif(receipt.value->>'r2_key','') is not null
                and coalesce(receipt.value->>'sha256','')~'^[0-9a-f]{64}$'
            ),'')<>coalesce(i.payload_json->>'expected_physical_input_hash','')
            or case when coalesce(i.processor_result->>'page_count','')
                ~ '^[0-9]{1,9}$'
              then(i.processor_result->>'page_count')::integer end
                is distinct from i.expected_page_count)
          then 'FINAL_VERIFICATION_MISMATCH'
        when i.outcome='SUCCESS'
          and coalesce(
            case when i.chunk_type='SOURCE_RENDER'
              then i.payload_json->>'source_revision' end,
            i.asset_source_revision,i.document_source_revision,
            i.payload_json->>'source_revision','')<>''
          and coalesce(i.processor_result->>'source_revision','')<>
            coalesce(
              case when i.chunk_type='SOURCE_RENDER'
                then i.payload_json->>'source_revision' end,
              i.asset_source_revision,i.document_source_revision,
              i.payload_json->>'source_revision','')
          then 'SOURCE_REVISION_MISMATCH'
      end result_error
    from identified i
  ),
  valid as materialized (
    select c.*,
      case
        when c.result_error is null then c.outcome
        when c.result_error in(
          'INVALID_OUTCOME','INVALID_RESULT_PAYLOAD','INVALID_INSPECTION_RESULT',
          'INVALID_ARTIFACT_RESULT') then 'RETRY'
        else 'FAILED'
      end effective_outcome,
      case when c.result_error is null then c.processor_error
        else jsonb_build_object('code',c.result_error,'retryable',
          c.result_error in(
            'INVALID_OUTCOME','INVALID_RESULT_PAYLOAD','INVALID_INSPECTION_RESULT',
            'INVALID_ARTIFACT_RESULT')) end effective_error
    from classified c where c.ownership_error is null
  )
  select
    coalesce((select jsonb_agg(jsonb_build_object(
      'request_no',v.request_no,'chunk_id',v.chunk_id,'operation_id',v.operation_id,
      'chunk_type',v.chunk_type,'phase',v.phase,'entity_type',v.entity_type,
      'entity_id',v.entity_id,'document_version_id',v.document_version_id,
      'document_asset_id',v.document_asset_id,
      'input_document_version_id',v.input_document_version_id,
      'payload_json',v.payload_json,'expected_page_count',v.expected_page_count,
      'expected_byte_count',v.expected_byte_count,'attempt_count',v.attempt_count,
      'max_attempts',v.max_attempts,'fence_token',v.fence_token,
      'processor_policy',v.processor_policy,
      'outcome',v.effective_outcome,'result',v.processor_result,'error',v.effective_error
    ) order by v.request_no) from valid v),'[]'::jsonb),
    coalesce((select jsonb_agg(jsonb_build_object(
      'request_no',c.request_no,'chunk_id',c.chunk_id,'status','REJECTED',
      'accepted',false,'code',c.ownership_error
    ) order by c.request_no) from classified c where c.ownership_error is not null),'[]'::jsonb)
  into v_valid_results,v_rejections;

  /* Successful inspection is explicit and always creates bounded next work. */
  with supplied as materialized (
    select x.value item,(x.value->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(v_valid_results) x(value)
    where x.value->>'outcome'='SUCCESS' and x.value->>'chunk_type'='ASSET_INSPECT'
  ),
  inspected_assets as materialized (
    update public.invoice_document_assets a
    set detected_media_type=case lower(coalesce(s.item#>>'{result,detected_media_type}',
          s.item#>>'{result,detected_kind}'))
          when 'pdf' then 'application/pdf'
          when 'jpeg' then 'image/jpeg' when 'jpg' then 'image/jpeg'
          when 'png' then 'image/png'
          else lower(coalesce(s.item#>>'{result,detected_media_type}',
            s.item#>>'{result,detected_kind}')) end,
        original_sha256=s.item#>>'{result,original_sha256}',
        original_size_bytes=(s.item#>>'{result,original_size_bytes}')::bigint,
        width_pixels=case when coalesce(s.item#>>'{result,width_pixels}','') ~ '^[0-9]{1,9}$'
          then(s.item#>>'{result,width_pixels}')::integer end,
        height_pixels=case when coalesce(s.item#>>'{result,height_pixels}','') ~ '^[0-9]{1,9}$'
          then(s.item#>>'{result,height_pixels}')::integer end,
        orientation_degrees=case
          when coalesce(s.item#>>'{result,orientation_degrees}','') ~ '^(0|90|180|270)$'
            then(s.item#>>'{result,orientation_degrees}')::integer
          else a.orientation_degrees end,
        source_page_count=case
          when coalesce(s.item#>>'{result,page_count}','') ~ '^[0-9]{1,9}$'
            then(s.item#>>'{result,page_count}')::integer
          when lower(coalesce(s.item#>>'{result,detected_media_type}',
            s.item#>>'{result,detected_kind}')) in(
              'image/jpeg','jpeg','jpg','image/png','png') then 1
          else null end,
        is_encrypted=false,status='NORMALISING',updated_at_utc=v_now,error_json=null
    from supplied s
    join public.invoice_operation_chunks c on c.id=s.chunk_id
    where a.id=c.document_asset_id
    returning a.*,c.operation_id work_operation_id,c.priority,
      s.item->'processor_policy' processor_policy,
      case when coalesce(s.item#>>'{result,estimated_decoded_bytes}','')
          ~ '^[0-9]{1,18}$'
        then(s.item#>>'{result,estimated_decoded_bytes}')::bigint else 0 end
        estimated_decoded_bytes,
      case when jsonb_typeof(s.item#>'{result,recommended_ranges}')='array'
        then s.item#>'{result,recommended_ranges}' else '[]'::jsonb end
        recommended_ranges
  ),
  adaptive_limits as materialized (
    select i.*,
      greatest(1,least(
        (i.processor_policy
          #>>'{asset,max_pdf_part_pages}')::integer,least(
        case when i.source_page_count>0
          then greatest(1,floor(
            (i.processor_policy
              #>>'{asset,max_part_input_bytes}')::numeric/
            greatest(i.original_size_bytes::numeric/i.source_page_count,1))::integer)
          else 1 end,
        case when i.estimated_decoded_bytes>0 and i.source_page_count>0
          then greatest(1,floor(
            (i.processor_policy
              #>>'{asset,max_part_estimated_decoded_bytes}')::numeric/
            greatest(i.estimated_decoded_bytes::numeric/i.source_page_count,1))::integer)
          else(i.processor_policy
            #>>'{asset,max_pdf_part_pages}')::integer end))) target_pages
    from inspected_assets i
  ),
  recommended_range_rows as materialized (
    select i.id,i.source_page_count,x.ordinality,
      case when coalesce(x.value->>'start','')~'^[0-9]{1,9}$'
        then(x.value->>'start')::integer end range_start,
      case when coalesce(x.value->>'end','')~'^[0-9]{1,9}$'
        then(x.value->>'end')::integer end range_end
    from adaptive_limits i
    cross join lateral jsonb_array_elements(i.recommended_ranges)
      with ordinality x(value,ordinality)
  ),
  recommended_range_checks as materialized (
    select i.id,
      jsonb_array_length(i.recommended_ranges)>0
      and count(r.ordinality)=jsonb_array_length(i.recommended_ranges)
      and bool_and(r.range_start is not null and r.range_end is not null
        and r.range_start between 1 and i.source_page_count
        and r.range_end between r.range_start and i.source_page_count)
      and min(r.range_start)=1 and max(r.range_end)=i.source_page_count
      and sum(r.range_end-r.range_start+1)=i.source_page_count
      and bool_and(coalesce(r.range_start=lagged.previous_end+1,
        r.range_start=1)) recommended_valid
    from adaptive_limits i
    left join lateral (
      select p.*,
        lag(p.range_end) over(order by p.range_start,p.range_end,p.ordinality)
          previous_end
      from recommended_range_rows p where p.id=i.id
    ) lagged on true
    left join recommended_range_rows r
      on r.id=lagged.id and r.ordinality=lagged.ordinality
    group by i.id,i.recommended_ranges,i.source_page_count
  ),
  ranges as materialized (
    select i.*,
      r.range_start,r.range_end,
      row_number() over(partition by i.id order by r.range_start)::integer-1 sequence_no
    from adaptive_limits i
    cross join lateral (
      select x.range_start,x.range_end
      from recommended_range_rows x
      join recommended_range_checks ck on ck.id=x.id
      where x.id=i.id and ck.recommended_valid
      union all
      select g,least(g+i.target_pages-1,i.source_page_count)
      from generate_series(1,i.source_page_count,i.target_pages) g
      where not coalesce((select ck.recommended_valid
        from recommended_range_checks ck where ck.id=i.id),false)
    ) r
  ),
  seeded as (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_asset_id,status,priority,run_after_utc,payload_json,
      expected_page_count,expected_byte_count,operation_control_version,
      created_at_utc,updated_at_utc)
    select r.work_operation_id,'ASSET_NORMALISE','NORMALISE',
      encode(digest(concat_ws('|','ASSET_NORMALISE',r.id::text,
        r.source_revision,r.range_start::text,r.range_end::text,
        r.processor_policy->>'policy_version','1'),'sha256'),'hex'),
      r.sequence_no,
      'DOCUMENT_ASSET',r.id,r.id,'QUEUED',r.priority,v_now,
      jsonb_build_object(
        'page_range',jsonb_build_object('start',r.range_start,'end',r.range_end),
        'detected_media_type',r.detected_media_type,
        'source_revision',r.source_revision,
        'adaptive_limits',jsonb_build_object(
          'policy_version',r.processor_policy->>'policy_version',
          'max_part_pages',r.target_pages,
          'max_input_bytes',(r.processor_policy
            #>>'{asset,max_part_input_bytes}')::bigint,
          'max_estimated_decoded_bytes',(r.processor_policy
            #>>'{asset,max_part_estimated_decoded_bytes}')::bigint)),
      r.range_end-r.range_start+1,
      greatest(1,ceil(r.original_size_bytes::numeric*
        (r.range_end-r.range_start+1)/greatest(r.source_page_count,1)))::bigint,
      o.control_version,v_now,v_now
    from ranges r join public.invoice_operations o on o.id=r.work_operation_id
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing
    returning id
  ),
  completed_inspection as (
    update public.invoice_operation_chunks c
    set status='COMPLETE',phase='COMPLETE',
        result_json=s.item->'result',error_json=null,
        completed_at_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    from supplied s where c.id=s.chunk_id
    returning c.id
  )
  select count(*) into v_ignored from completed_inspection;

  /* All other validated successful artifacts become immutable chunk results. */
  with supplied as materialized (
    select x.value item,(x.value->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(v_valid_results) x(value)
    where x.value->>'outcome'='SUCCESS'
      and x.value->>'chunk_type'<>'ASSET_INSPECT'
  ),
  completed as (
    update public.invoice_operation_chunks c
    set status='COMPLETE',phase='COMPLETE',result_json=s.item->'result',error_json=null,
        actual_page_count=(s.item#>>'{result,page_count}')::integer,
        actual_byte_count=(s.item#>>'{result,size_bytes}')::bigint,
        completed_at_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    from supplied s where c.id=s.chunk_id
    returning c.id
  )
  select count(*) into v_ignored from completed;

  /*
   * The attachment index is stabilised within the frozen policy's bounded
   * deterministic pass budget.
   * A new pass is inserted before the prior pass is typed as replaced, so the
   * old pass remains current if creation of its replacement fails.
   */
  with index_results as materialized (
    select c.*,o.control_version,o.config_json->'processor_policy'
      processor_policy
    from jsonb_array_elements(v_valid_results) x
    join public.invoice_operation_chunks c on c.id=(x->>'chunk_id')::uuid
    join public.invoice_operations o on o.id=c.operation_id
    where x->>'outcome'='SUCCESS' and c.chunk_type='SOURCE_RENDER'
      and c.status='COMPLETE'
      and c.payload_json->>'render_kind'='ATTACHMENT_INDEX'
  ),
  next_pass_source as materialized (
    select r.*,
      (r.payload_json->>'layout_pass')::integer+1 next_pass,
      r.actual_page_count expected_index_page_count
    from index_results r
    where r.payload_json->>'layout_phase'='MEASURE'
       or(r.payload_json->>'layout_phase'='FINAL'
          and r.actual_page_count is distinct from
            (r.payload_json->>'expected_index_page_count')::integer
          and(r.payload_json->>'layout_pass')::integer<
            (r.processor_policy#>>
              '{attachment_index,max_render_passes}')::integer)
  ),
  final_attachments as materialized (
    select n.id prior_chunk_id,n.operation_id,n.document_version_id,
      n.sequence_no,n.priority,n.plan_generation,n.control_version,
      n.next_pass,n.expected_index_page_count,n.processor_policy,
      n.payload_json,calculated.attachments,
      calculated.source_display_count,calculated.matched_display_count,
      encode(digest(coalesce(n.payload_json->'pagination_stream',
        '[]'::jsonb)::text,'sha256'),'hex') pagination_stream_hash
    from next_pass_source n
    cross join lateral (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'row_id',coalesce(
            nullif(display_row.value->>'logical_source_key',''),
            nullif(display_row.value->>'row_id','')),
          'attachment_number',coalesce(
            (display_row.value->>'attachment_number')::integer,
            display_row.display_no::integer),
          'worker',coalesce(
            nullif(display_row.value->>'worker',''),
            nullif(display_row.value->>'source','')),
          'week_or_date',nullif(display_row.value->>'week_or_date',''),
          'document_type',coalesce(
            nullif(display_row.value->>'document_type',''),
            nullif(display_row.value->>'label',''),
            nullif(display_row.value->>'input_type','')),
          'evidence_description',coalesce(
            nullif(display_row.value->>'evidence_description',''),
            nullif(display_row.value->>'label','')),
          'reference',nullif(display_row.value->>'reference',''),
          'page_count',(display_row.value->>'page_count')::integer,
          'start_page',1+coalesce((
            select sum(case
              when preceding.value->>'input_type'='ATTACHMENT_INDEX'
                then n.expected_index_page_count
              else (preceding.value->>'page_count')::integer end)
            from jsonb_array_elements(
              case when jsonb_typeof(n.payload_json->'pagination_stream')='array'
                then n.payload_json->'pagination_stream'
                else '[]'::jsonb end) with ordinality
              preceding(value,stream_no)
            where preceding.stream_no<target.stream_no),0))
        order by target.stream_no,
          display_row.value->>'input_chunk_id'),'[]'::jsonb) attachments,
        jsonb_array_length(case
          when jsonb_typeof(n.payload_json->'display_rows')='array'
            then n.payload_json->'display_rows'
          when jsonb_typeof(n.payload_json->'attachments')='array'
            then n.payload_json->'attachments'
          else '[]'::jsonb end)::integer source_display_count,
        count(*)::integer matched_display_count
      from jsonb_array_elements(
        case when jsonb_typeof(n.payload_json->'display_rows')='array'
          then n.payload_json->'display_rows'
          when jsonb_typeof(n.payload_json->'attachments')='array'
          then n.payload_json->'attachments'
          else '[]'::jsonb end) with ordinality
        display_row(value,display_no)
      join lateral (
        select stream.stream_no
        from jsonb_array_elements(
          case when jsonb_typeof(n.payload_json->'pagination_stream')='array'
            then n.payload_json->'pagination_stream'
            else '[]'::jsonb end) with ordinality stream(value,stream_no)
        where stream.value->>'logical_source_key'=coalesce(
            display_row.value->>'logical_source_key',
            display_row.value->>'row_id')
          and coalesce(stream.value->>'is_displayed_attachment','false')='true'
        order by stream.stream_no
        limit 1
      ) target on true
    ) calculated
  ),
  replacement_index_passes as (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,plan_generation,sequence_no,
      entity_type,entity_id,document_version_id,status,priority,run_after_utc,
      payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select f.operation_id,'SOURCE_RENDER','ATTACHMENT_INDEX_FINAL',
      encode(digest(concat_ws('|','ATTACHMENT_INDEX',
        f.document_version_id::text,f.sequence_no::text,
        f.payload_json->>'source_chunk_key','FINAL',f.next_pass::text,
        f.expected_index_page_count::text,
        encode(digest(f.attachments::text,'sha256'),'hex'),
        f.payload_json->>'template_version'),'sha256'),'hex'),
      f.plan_generation+1,f.sequence_no,'DOCUMENT',f.document_version_id,
      f.document_version_id,'QUEUED',f.priority,v_now,
      f.payload_json||jsonb_build_object(
        'layout_phase','FINAL','layout_pass',f.next_pass,
        'expected_index_page_count',f.expected_index_page_count,
        'attachments',f.attachments,
        'display_rows',f.attachments,
        'displayed_row_count',jsonb_array_length(f.attachments),
        'pagination_stream_hash',f.pagination_stream_hash,
        'expected_start_pages_hash',
          encode(digest(f.attachments::text,'sha256'),'hex'),
        'previous_layout_measurements',
          coalesce(f.payload_json->'previous_layout_measurements','[]'::jsonb)
          ||jsonb_build_array(jsonb_build_object(
            'pass',(f.payload_json->>'layout_pass')::integer,
            'phase',f.payload_json->>'layout_phase',
            'page_count',f.expected_index_page_count))),
      f.control_version,v_now,v_now
    from final_attachments f
    where f.source_display_count=f.matched_display_count
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key)
      do update set priority=greatest(
        public.invoice_operation_chunks.priority,excluded.priority),
        updated_at_utc=excluded.updated_at_utc
    returning id,operation_id,document_version_id,sequence_no,plan_generation
  ),
  linked_index_passes as (
    update public.invoice_operation_chunks old
    set status='SUPERSEDED',phase='SUPERSEDED',
      replaced_by_chunk_id=fresh.id,replacement_required=true,
      completed_at_utc=v_now,failed_at_utc=null,updated_at_utc=v_now,
      result_json=coalesce(old.result_json,'{}'::jsonb)||
        jsonb_build_object('replacement_chunk_id',fresh.id)
    from replacement_index_passes fresh
    where old.id in(
      select prior_chunk_id from final_attachments f
      where f.operation_id=fresh.operation_id
        and f.document_version_id=fresh.document_version_id
        and f.sequence_no=fresh.sequence_no
        and f.plan_generation+1=fresh.plan_generation)
    returning old.id
  ),
  unstable_passes as materialized (
    update public.invoice_operation_chunks c
    set status='FAILED',phase='FAILED',failed_at_utc=v_now,
      completed_at_utc=null,updated_at_utc=v_now,
      error_json=jsonb_build_object(
        'code',case
          when calc.prior_chunk_id is not null
            and calc.source_display_count<>calc.matched_display_count
            then 'ATTACHMENT_INDEX_PAGINATION_MAPPING_INVALID'
          else 'ATTACHMENT_INDEX_LAYOUT_UNSTABLE' end,
        'retryable',false,'max_layout_passes',
          (r.processor_policy#>>
            '{attachment_index,max_render_passes}')::integer,
        'expected_page_count',
          (c.payload_json->>'expected_index_page_count')::integer,
        'actual_page_count',c.actual_page_count,
        'measurements',
          coalesce(c.payload_json->'previous_layout_measurements','[]'::jsonb)
          ||jsonb_build_array(jsonb_build_object(
            'pass',(r.payload_json->>'layout_pass')::integer,
            'phase','FINAL','page_count',c.actual_page_count)))
    from index_results r
    left join final_attachments calc on calc.prior_chunk_id=r.id
    where c.id=r.id
      and(
        (calc.prior_chunk_id is not null
          and calc.source_display_count<>calc.matched_display_count)
        or(
          r.payload_json->>'layout_phase'='FINAL'
          and(r.payload_json->>'layout_pass')::integer=
            (r.processor_policy#>>
              '{attachment_index,max_render_passes}')::integer
          and r.actual_page_count is distinct from
            (r.payload_json->>'expected_index_page_count')::integer))
    returning c.id,c.operation_id,c.document_version_id,
      c.payload_json->>'source_chunk_key' source_chunk_key,c.error_json
  ),
  blocked_index_dependencies as (
    update public.invoice_operation_chunks d
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
      completed_at_utc=null,updated_at_utc=v_now,
      error_json=u.error_json
    from unstable_passes u
    where d.operation_id=u.operation_id
      and d.document_version_id=u.document_version_id
      and d.chunk_type='DOCUMENT_INPUT' and d.status='WAITING'
      and d.payload_json->>'source_chunk_key'=u.source_chunk_key
    returning d.document_version_id
  ),
  failed_index_versions as (
    update public.invoice_document_versions v
    set status='FAILED',error_json=jsonb_build_object(
      'code','ATTACHMENT_INDEX_LAYOUT_UNSTABLE','retryable',false)
    where v.id in(select document_version_id
      from blocked_index_dependencies)
      and v.status not in('READY','SUPERSEDED','CANCELLED')
    returning v.id
  )
  select count(*) into v_ignored from linked_index_passes;

  /* Finalise an asset only after every adaptive output part is complete. */
  with affected as materialized (
    select distinct c.document_asset_id
    from jsonb_array_elements(v_valid_results) x
    join public.invoice_operation_chunks c on c.id=(x->>'chunk_id')::uuid
    where x->>'outcome'='SUCCESS' and c.chunk_type='ASSET_NORMALISE'
  ),
  current_normalise as materialized (
    select c.*
    from private._invoice_current_chunks_batch(
      null,null,(select array_agg(document_asset_id) from affected),10000) g
    join public.invoice_operation_chunks c on c.id=g.current_chunk_id
    where g.replacement_chain_status='VALID'
      and c.chunk_type='ASSET_NORMALISE'
  ),
  ready as materialized (
    select a.id,
      jsonb_agg(jsonb_build_object(
        'sequence_no',c.sequence_no,'r2_key',c.result_json->>'r2_key',
        'sha256',c.result_json->>'sha256','size_bytes',c.actual_byte_count,
        'page_count',c.actual_page_count,'page_range',c.payload_json->'page_range')
        order by c.sequence_no) manifest,
      sum(c.actual_byte_count)::bigint bytes,
      sum(c.actual_page_count)::integer pages,
      min(c.result_json->>'sha256') filter(where c.sequence_no=0) single_hash,
      encode(digest(jsonb_agg(jsonb_build_object(
        'sequence_no',c.sequence_no,'r2_key',c.result_json->>'r2_key',
        'sha256',c.result_json->>'sha256','size_bytes',c.actual_byte_count,
        'page_count',c.actual_page_count,'page_range',c.payload_json->'page_range')
        order by c.sequence_no)::text,'sha256'),'hex') manifest_hash
    from affected x
    join public.invoice_document_assets a on a.id=x.document_asset_id
    join current_normalise c on c.document_asset_id=a.id
    group by a.id
    having count(*)>0 and bool_and(c.status='COMPLETE')
      and bool_and(c.actual_byte_count>0 and c.actual_page_count>0
        and coalesce(c.result_json->>'r2_key','')<>''
        and coalesce(c.result_json->>'sha256','')<>'')
      and min((c.payload_json#>>'{page_range,start}')::integer)=1
      and max((c.payload_json#>>'{page_range,end}')::integer)=a.source_page_count
      and sum((c.payload_json#>>'{page_range,end}')::integer
        -(c.payload_json#>>'{page_range,start}')::integer+1)=a.source_page_count
      and sum(c.actual_page_count)=a.source_page_count
      and not exists(
        select 1
        from (
          select
            (c2.payload_json#>>'{page_range,start}')::integer range_start,
            lag((c2.payload_json#>>'{page_range,end}')::integer)
              over(order by
                (c2.payload_json#>>'{page_range,start}')::integer,
                (c2.payload_json#>>'{page_range,end}')::integer,
                c2.sequence_no,c2.id) previous_end
          from current_normalise c2
          where c2.document_asset_id=a.id
            and coalesce(c2.payload_json#>>'{page_range,start}','')
              ~'^[0-9]{1,9}$'
            and coalesce(c2.payload_json#>>'{page_range,end}','')
              ~'^[0-9]{1,9}$'
        ) ordered_ranges
        where range_start<>coalesce(previous_end+1,1))
  ),
  updated_assets as materialized (
    update public.invoice_document_assets a
    set normalised_manifest_json=case when jsonb_array_length(r.manifest)=1
          then '[]'::jsonb else r.manifest end,
        normalised_r2_key=case when jsonb_array_length(r.manifest)=1
          then r.manifest->0->>'r2_key' else null end,
        normalised_sha256=case when jsonb_array_length(r.manifest)=1
          then r.single_hash else null end,
        normalised_manifest_hash=case when jsonb_array_length(r.manifest)>1
          then r.manifest_hash else null end,
        normalised_size_bytes=r.bytes,
        normalised_page_count=r.pages,status='READY',ready_at_utc=v_now,
        updated_at_utc=v_now,error_json=null
    from ready r where a.id=r.id
    returning a.*
  ),
  evidence_ready as (
    update public.timesheet_evidence e
    set document_asset_id=a.id,
        source_revision=a.source_revision,
        processing_state='READY',
        processing_error_json=null
    from updated_assets a
    where a.source_kind='TIMESHEET_EVIDENCE' and e.id=a.source_id
    returning e.id,e.timesheet_id,e.kind,e.document_asset_id
  ),
  manual_evidence_ready as (
    update public.timesheets t
    set manual_document_asset_id=e.document_asset_id,
        manual_pdf_r2_key=null,
        document_state='QUEUED',last_document_error_json=null,updated_at=v_now
    from evidence_ready e
    join updated_assets a on a.id=e.document_asset_id
    where upper(e.kind)='TIMESHEET' and t.timesheet_id=e.timesheet_id and t.is_current
    returning t.timesheet_id
  ),
  manual_asset_ready as (
    update public.timesheets t
    set manual_document_asset_id=a.id,
        manual_pdf_r2_key=null,
        document_state='QUEUED',last_document_error_json=null,updated_at=v_now
    from updated_assets a
    where a.source_kind='MANUAL_TIMESHEET'
      and t.timesheet_id=a.source_id and t.is_current
    returning t.timesheet_id
  ),
  manual_document_targets as materialized (
    select distinct t.timesheet_id,t.document_revision,a.operation_id
      asset_operation_id,asset_op.actor_user_id,
      asset_op.config_json->'processor_policy' processor_policy
    from updated_assets a
    join public.invoice_operations asset_op on asset_op.id=a.operation_id
    join public.timesheets t on t.is_current and(
      (a.source_kind='MANUAL_TIMESHEET' and t.timesheet_id=a.source_id)
      or(a.source_kind='TIMESHEET_EVIDENCE' and exists(
        select 1 from public.timesheet_evidence e
        where e.id=a.source_id and e.timesheet_id=t.timesheet_id
          and upper(coalesce(e.kind,''))='TIMESHEET')))
    where not exists(
      select 1 from public.invoice_document_versions v
      where v.entity_type='TIMESHEET' and v.entity_id=t.timesheet_id
        and v.purpose='TIMESHEET'
        and v.source_revision=t.document_revision::text
        and v.template_version='timesheet-professional-v1'
        and v.status in('PLANNING','WAITING_FOR_INPUTS','RENDERING',
          'ASSEMBLING','VERIFYING','READY'))
  ),
  inserted_manual_document_operations as materialized (
    insert into public.invoice_operations(
      parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,
      input_json,config_json,progress_json,total_units,chunk_count,
      control_version,change_seq,created_at_utc,updated_at_utc)
    select t.asset_operation_id,'BUILD_DOCUMENT','TIMESHEET',t.timesheet_id,
      t.actor_user_id,
      encode(digest(concat_ws('|','BUILD_DOCUMENT','TIMESHEET',
        t.timesheet_id::text,t.document_revision::text,
        'timesheet-professional-v1'),'sha256'),'hex'),
      'QUEUED','BUILD_MANIFEST',800,t.document_revision::text,
      'timesheet-professional-v1',
      jsonb_build_object('entity_type','TIMESHEET',
        'entity_id',t.timesheet_id,'purpose','TIMESHEET',
        'source_revision',t.document_revision::text,
        'template_version','timesheet-professional-v1',
        'reason','MANUAL_ASSET_READY'),
      jsonb_build_object('processor_policy',t.processor_policy),
      jsonb_build_object(
        'status_message','Manual timesheet document queued'),
      1,1,1,nextval('public.invoice_operation_change_seq'),v_now,v_now
    from manual_document_targets t
    on conflict do nothing
    returning *
  ),
  selected_manual_document_operations as materialized (
    select t.timesheet_id,t.document_revision,
      coalesce(created.id,existing.id) operation_id,
      coalesce(created.control_version,existing.control_version)
        control_version
    from manual_document_targets t
    left join inserted_manual_document_operations created
      on created.entity_id=t.timesheet_id
        and created.source_revision=t.document_revision::text
    left join lateral(
      select o.id,o.control_version
      from public.invoice_operations o
      where o.operation_type='BUILD_DOCUMENT'
        and o.entity_type='TIMESHEET' and o.entity_id=t.timesheet_id
        and o.source_revision=t.document_revision::text
        and o.template_version='timesheet-professional-v1'
        and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      order by o.created_at_utc desc,o.id desc limit 1
    ) existing on created.id is null
    where coalesce(created.id,existing.id) is not null
  ),
  inserted_manual_document_versions as materialized (
    insert into public.invoice_document_versions(
      entity_type,entity_id,purpose,operation_id,source_revision,
      template_version,status,snapshot_json,snapshot_hash,manifest_json,
      manifest_hash,created_at_utc)
    select 'TIMESHEET',s.timesheet_id,'TIMESHEET',s.operation_id,
      s.document_revision::text,'timesheet-professional-v1','PLANNING',
      '{}'::jsonb,encode(digest('{}','sha256'),'hex'),'[]'::jsonb,
      encode(digest('[]','sha256'),'hex'),v_now
    from selected_manual_document_operations s
    on conflict do nothing
    returning *
  ),
  selected_manual_document_versions as materialized (
    select s.*,coalesce(created.id,existing.id) document_version_id
    from selected_manual_document_operations s
    left join inserted_manual_document_versions created
      on created.operation_id=s.operation_id
    left join public.invoice_document_versions existing
      on created.id is null
      and existing.entity_type='TIMESHEET'
      and existing.entity_id=s.timesheet_id
      and existing.purpose='TIMESHEET'
      and existing.source_revision=s.document_revision::text
      and existing.template_version='timesheet-professional-v1'
      and existing.status in('PLANNING','WAITING_FOR_INPUTS','RENDERING',
        'ASSEMBLING','VERIFYING','READY')
  ),
  inserted_manual_document_plans as (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,sequence_no,level_no,
      entity_type,entity_id,document_version_id,status,priority,
      run_after_utc,payload_json,operation_control_version,
      created_at_utc,updated_at_utc)
    select s.operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',
        s.document_version_id::text,s.document_revision::text,
        'timesheet-professional-v1','1'),'sha256'),'hex'),
      0,0,'TIMESHEET',s.timesheet_id,s.document_version_id,
      'QUEUED',800,v_now,
      jsonb_build_object('purpose','TIMESHEET',
        'source_revision',s.document_revision::text,
        'template_version','timesheet-professional-v1',
        'reason','MANUAL_ASSET_READY'),
      s.control_version,v_now,v_now
    from selected_manual_document_versions s
    where s.document_version_id is not null
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key)
      do nothing
    returning operation_id,document_version_id
  ),
  manual_document_pointer_updates as (
    update public.timesheets t
    set active_document_operation_id=s.operation_id,
      document_state=case when v.status='READY' then 'READY' else 'QUEUED' end,
      current_document_version_id=case when v.status='READY'
        then v.id else t.current_document_version_id end,
      updated_at=v_now
    from selected_manual_document_versions s
    join public.invoice_document_versions v
      on v.id=s.document_version_id
    where t.timesheet_id=s.timesheet_id and t.is_current
    returning t.timesheet_id
  ),
  released_dependencies as materialized (
    update public.invoice_operation_chunks d
    set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,updated_at_utc=v_now,
        result_json=jsonb_build_object(
          'asset_id',a.id,'source_revision',a.source_revision,
          'normalised_r2_key',a.normalised_r2_key,
          'normalised_manifest',a.normalised_manifest_json,
          'parts',a.normalised_manifest_json,
          'sha256',a.normalised_sha256,
          'normalised_manifest_hash',a.normalised_manifest_hash,
          'size_bytes',a.normalised_size_bytes,
          'page_count',a.normalised_page_count),
        expected_page_count=a.normalised_page_count,
        actual_page_count=a.normalised_page_count,
        expected_byte_count=a.normalised_size_bytes,
        actual_byte_count=a.normalised_size_bytes,error_json=null
    from updated_assets a
    where d.chunk_type='DOCUMENT_INPUT' and d.document_asset_id=a.id
      and(
        d.status='WAITING'
        or(d.status='BLOCKED'
          and d.error_json->>'code'='DOCUMENT_DEPENDENCY_PERMANENT_FAILURE'))
    returning d.id,d.operation_id,d.document_version_id
  ),
  reset_document_versions as (
    update public.invoice_document_versions v
    set status='WAITING_FOR_INPUTS',error_json=null
    where v.id in(select document_version_id from released_dependencies)
      and v.status='FAILED'
      and v.error_json->>'code'='DOCUMENT_DEPENDENCY_PERMANENT_FAILURE'
    returning v.id
  ),
  plan_wake as (
    update public.invoice_operation_chunks p
    set status='QUEUED',phase='WAIT_FOR_INPUTS',run_after_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where p.chunk_type='DOCUMENT_PLAN'
      and p.status in('QUEUED','WAITING','RETRY_WAIT','BLOCKED')
      and p.document_version_id in(
        select document_version_id from released_dependencies)
    returning p.id
  ),
  released_operation_updates as materialized (
    select r.*
    from private._invoice_operation_rollup_batch(
      coalesce((select array_agg(distinct d.operation_id)
        from released_dependencies d),array[]::uuid[]),
      v_now,true) r
  )
  select count(*) into v_ignored from released_dependencies;

  /*
   * A terminal set of normalisation parts that does not cover the registered
   * source exactly is a permanent asset failure.  It must never leave the
   * asset in NORMALISING with every worker chunk complete.
   */
  with affected as materialized (
    select distinct c.document_asset_id
    from jsonb_array_elements(v_valid_results) x
    join public.invoice_operation_chunks c on c.id=(x->>'chunk_id')::uuid
    where x->>'outcome'='SUCCESS' and c.chunk_type='ASSET_NORMALISE'
  ),
  current_normalise as materialized (
    select c.*
    from private._invoice_current_chunks_batch(
      null,null,(select array_agg(document_asset_id) from affected),10000) g
    join public.invoice_operation_chunks c on c.id=g.current_chunk_id
    where g.replacement_chain_status='VALID'
      and c.chunk_type='ASSET_NORMALISE'
  ),
  coverage_failures as materialized (
    update public.invoice_document_assets a
    set status='FAILED',updated_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','ASSET_RANGE_COVERAGE_MISMATCH',
          'class','PERMANENT','retryable',false,
          'source_page_count',a.source_page_count)
    where a.id in(select document_asset_id from affected)
      and a.status='NORMALISING'
      and exists(
        select 1 from current_normalise n
        where n.document_asset_id=a.id)
      and not exists(
        select 1 from current_normalise n
        where n.document_asset_id=a.id and n.status<>'COMPLETE')
    returning a.*
  ),
  evidence_failed as (
    update public.timesheet_evidence e
    set processing_state='FAILED',processing_error_json=a.error_json
    from coverage_failures a
    where a.source_kind='TIMESHEET_EVIDENCE' and e.id=a.source_id
    returning e.id,e.timesheet_id,e.kind
  ),
  manual_failed as (
    update public.timesheets t
    set document_state='FAILED',last_document_error_json=a.error_json,
        updated_at=v_now
    from coverage_failures a
    where t.is_current and(
       (a.source_kind='MANUAL_TIMESHEET' and t.timesheet_id=a.source_id)
       or(a.source_kind='TIMESHEET_EVIDENCE'
          and exists(select 1 from evidence_failed e
            where e.id=a.source_id and upper(e.kind)='TIMESHEET'
              and e.timesheet_id=t.timesheet_id)))
    returning t.timesheet_id
  ),
  blocked_inputs as materialized (
    update public.invoice_operation_chunks d
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
        updated_at_utc=v_now,error_json=jsonb_build_object(
          'code','DOCUMENT_DEPENDENCY_PERMANENT_FAILURE',
          'asset_error',a.error_json,'document_asset_id',a.id)
    from coverage_failures a
    where d.chunk_type='DOCUMENT_INPUT' and d.document_asset_id=a.id
      and d.status in('WAITING','BLOCKED')
    returning d.operation_id,d.document_version_id
  ),
  failed_versions as materialized (
    update public.invoice_document_versions v
    set status='FAILED',error_json=jsonb_build_object(
      'code','DOCUMENT_DEPENDENCY_PERMANENT_FAILURE',
      'asset_code','ASSET_RANGE_COVERAGE_MISMATCH')
    where v.id in(select document_version_id from blocked_inputs)
      and v.status not in('READY','SUPERSEDED','CANCELLED')
    returning v.id
  ),
  plan_wake as (
    update public.invoice_operation_chunks p
    set status='QUEUED',phase='WAIT_FOR_INPUTS',run_after_utc=v_now,
        updated_at_utc=v_now,lease_owner=null,lease_token=null,
        lease_expires_at_utc=null
    where p.chunk_type='DOCUMENT_PLAN'
      and p.document_version_id in(select id from failed_versions)
      and p.status in('WAITING','RETRY_WAIT','BLOCKED')
    returning p.id
  ),
  issue_block as (
    update public.invoice_operation_chunks i
    set status='BLOCKED',phase='WAIT_DOCUMENT',failed_at_utc=v_now,
        updated_at_utc=v_now,error_json=jsonb_build_object(
          'code','FINAL_DOCUMENT_PERMANENT_FAILURE',
          'document_version_id',v.id,
          'document_error','ASSET_RANGE_COVERAGE_MISMATCH')
    from failed_versions v
    where i.chunk_type='ISSUE_INVOICE' and i.phase='WAIT_DOCUMENT'
      and i.status in('WAITING','RETRY_WAIT')
      and coalesce(
        case when coalesce(i.payload_json->>'document_version_id','')~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(i.payload_json->>'document_version_id')::uuid end,
        case when coalesce(i.payload_json->>'final_document_version_id','')~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(i.payload_json->>'final_document_version_id')::uuid end)=v.id
    returning i.id
  )
  select count(*) into v_ignored from coverage_failures;

  /* Source/core render dependencies may also be shared across child operations. */
  with rendered as materialized (
    select c.*
    from jsonb_array_elements(v_valid_results) x
    join public.invoice_operation_chunks c on c.id=(x->>'chunk_id')::uuid
    where x->>'outcome'='SUCCESS'
      and c.chunk_type in('SOURCE_RENDER','INVOICE_CORE_RENDER')
      and c.status='COMPLETE'
  ),
  released as materialized (
    update public.invoice_operation_chunks d
    set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,updated_at_utc=v_now,
        result_json=r.result_json,actual_page_count=r.actual_page_count,
        actual_byte_count=r.actual_byte_count,error_json=null
    from rendered r
    where d.chunk_type='DOCUMENT_INPUT' and d.status='WAITING'
      and d.document_version_id=r.document_version_id
      and(
        d.payload_json->>'source_chunk_key'=r.payload_json->>'source_chunk_key'
        or(d.entity_type=r.entity_type and d.entity_id=r.entity_id
          and d.payload_json->>'input_type'=case
            when r.chunk_type='INVOICE_CORE_RENDER' then 'INVOICE_CORE'
            else r.payload_json->>'render_kind' end))
    returning d.operation_id,d.document_version_id
  ),
  plan_wake as (
    update public.invoice_operation_chunks p
    set status='QUEUED',phase='WAIT_FOR_INPUTS',run_after_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where p.chunk_type='DOCUMENT_PLAN' and p.status in('WAITING','RETRY_WAIT')
      and p.document_version_id in(select document_version_id from released)
    returning p.id
  )
  select count(*) into v_ignored from released;

  /*
   * Verification is authoritative only when it agrees with the independently
   * frozen manifest hash, coverage hash, order and expected page count.
   */
  with verified as materialized (
    select c.id chunk_id,c.operation_id,c.document_version_id,x->'result' result
    from jsonb_array_elements(v_valid_results) x
    join public.invoice_operation_chunks c on c.id=(x->>'chunk_id')::uuid
    join public.invoice_document_versions v on v.id=c.document_version_id
    where x->>'outcome'='SUCCESS' and c.chunk_type='DOCUMENT_VERIFY'
      and c.status='COMPLETE'
      and x#>>'{result,parse_verified}'='true'
      and x#>>'{result,manifest_coverage_verified}'='true'
      and x#>>'{result,ordering_verified}'='true'
      and x#>>'{result,manifest_hash}'=v.manifest_hash
      and c.payload_json->>'resolved_input_coverage_hash'=
        c.payload_json->>'expected_coverage_hash'
      and x#>>'{result,assembled_input_coverage_hash}'=
        c.payload_json->>'expected_coverage_hash'
      and coalesce(x#>>'{result,assembled_input_count}','')~'^[0-9]{1,9}$'
      and coalesce(c.payload_json->>'expected_input_count','')~'^[0-9]{1,9}$'
      and(x#>>'{result,assembled_input_count}')::integer=
        (c.payload_json->>'expected_input_count')::integer
      and coalesce(x#>>'{result,assembled_physical_input_count}','')
        ~'^[0-9]{1,9}$'
      and coalesce(c.payload_json->>'expected_physical_input_count','')
        ~'^[0-9]{1,9}$'
      and(x#>>'{result,assembled_physical_input_count}')::integer=
        (c.payload_json->>'expected_physical_input_count')::integer
      and x#>>'{result,assembled_physical_input_hash}'=
        c.payload_json->>'expected_physical_input_hash'
      and x#>>'{result,actual_logical_root_receipt}'=
        c.payload_json->>'expected_logical_root_receipt'
      and x#>>'{result,actual_physical_root_receipt}'=
        c.payload_json->>'expected_physical_root_receipt'
      and x#>>'{result,actual_ordered_input_root}'=
        c.payload_json->>'expected_ordered_input_root'
      and x#>>'{result,root_merge_receipt_identity}'=
        c.payload_json->>'root_merge_receipt_identity'
      and x#>>'{result,verified_candidate_sha256}'=
        c.payload_json->>'candidate_sha256'
      and x#>>'{result,verified_candidate_r2_key}'=
        c.payload_json->>'candidate_r2_key'
      and x#>>'{result,verified_candidate_size_bytes}'=c.payload_json->>'candidate_size_bytes'
      and (
        v.entity_type<>'INVOICE'
        or (
          c.payload_json#>>'{final_merge_receipt,page_numbering_applied}'='true'
          and c.payload_json#>>'{final_merge_receipt,page_numbering_contract}'
            in('FINAL_MERGE_GLOBAL_V1','FINAL_MERGE_SELECTIVE_V2')
          and (
            c.payload_json#>>'{final_merge_receipt,page_numbering_contract}'
              <>'FINAL_MERGE_SELECTIVE_V2'
            or jsonb_typeof(c.payload_json#>
              '{final_merge_receipt,page_numbering_excluded_pages}')='array'
          )
        )
      )
      and coalesce(x#>>'{result,actual_page_count}','')~'^[0-9]{1,9}$'
      and(x#>>'{result,actual_page_count}')::integer=c.expected_page_count
  ),
  ready_versions as materialized (
    update public.invoice_document_versions v
    set status='READY',r2_key=q.result->>'verified_candidate_r2_key',
        sha256=q.result->>'verified_candidate_sha256',
        size_bytes=(q.result->>'verified_candidate_size_bytes')::bigint,
        page_count=(q.result->>'actual_page_count')::integer,
        core_page_count=case when coalesce(q.result->>'core_page_count','') ~ '^[0-9]{1,9}$'
          then(q.result->>'core_page_count')::integer end,
        supporting_page_count=case
          when coalesce(q.result->>'supporting_page_count','') ~ '^[0-9]{1,9}$'
          then(q.result->>'supporting_page_count')::integer end,
        ready_at_utc=v_now,verified_at_utc=v_now,error_json=null
    from verified q where v.id=q.document_version_id
    returning v.*
  ),
  invoice_preview_ready as (
    update public.invoices i
    set preview_document_version_id=v.id,document_state='READY',
        invoice_pdf_r2_key=v.r2_key,invoice_pdf_generated_at_utc=v.verified_at_utc,
        active_document_operation_id=case when i.active_document_operation_id=v.operation_id
          then null else i.active_document_operation_id end,
        last_document_error_json=null,updated_at=v_now
    from ready_versions v
    where v.entity_type='INVOICE' and v.purpose='DRAFT_PREVIEW'
      and i.id=v.entity_id and i.document_revision::text=v.source_revision
    returning i.id
  ),
  timesheet_document_ready as (
    update public.timesheets t
    set current_document_version_id=v.id,document_state='READY',
        manual_pdf_r2_key=case
          when v.snapshot_json#>>'{presentation_model,schema_version}'
              ='TIMESHEET_RENDER_MODEL_V1'
            and t.manual_document_asset_id is not null
          then v.r2_key else t.manual_pdf_r2_key end,
        generated_pdf_refs_snapshot_json=case
          when v.snapshot_json#>>'{presentation_model,schema_version}'
              ='TIMESHEET_RENDER_MODEL_V2'
          then coalesce((
            select jsonb_agg(jsonb_build_object(
              'row_key',shift.value->>'reference_row_key',
              'current_reference',shift.value->>'booking_reference')
              order by (day.value->>'display_order')::integer,
                (shift.value->>'display_order')::integer)
            from jsonb_array_elements(coalesce(
              v.snapshot_json#>'{presentation_model,week_period,days}',
              '[]'::jsonb)) day(value)
            cross join lateral jsonb_array_elements(coalesce(
              day.value->'shift_lines','[]'::jsonb)) shift(value)
            where nullif(shift.value->>'booking_reference','') is not null
          ),'[]'::jsonb)
          else t.generated_pdf_refs_snapshot_json end,
        generated_pdf_refs_sig=case
          when v.snapshot_json#>>'{presentation_model,schema_version}'
              ='TIMESHEET_RENDER_MODEL_V2'
          then v.snapshot_json#>>'{presentation_model,reference_signature}'
          else t.generated_pdf_refs_sig end,
        generated_pdf_refs_captured_at_utc=case
          when v.snapshot_json#>>'{presentation_model,schema_version}'
              ='TIMESHEET_RENDER_MODEL_V2'
          then v_now else t.generated_pdf_refs_captured_at_utc end,
        generated_pdf_at_utc=case
          when v.snapshot_json#>>'{presentation_model,schema_version}'
              ='TIMESHEET_RENDER_MODEL_V2'
          then v_now else t.generated_pdf_at_utc end,
        active_document_operation_id=case when t.active_document_operation_id=v.operation_id
          then null else t.active_document_operation_id end,
        last_document_error_json=null,updated_at=v_now
    from ready_versions v
    where v.entity_type='TIMESHEET' and v.purpose='TIMESHEET'
      and t.timesheet_id=v.entity_id and t.document_revision::text=v.source_revision
    returning t.timesheet_id
  ),
  qr_mail_release as (
    update public.mail_outbox m
    set attachments=jsonb_build_array(jsonb_build_object(
          'r2_key',v.r2_key,
          'filename','Timesheet_'||
            coalesce(t.week_ending_date::text,t.timesheet_id::text)||'.pdf',
          'sha256',v.sha256,
          'size_bytes',v.size_bytes,
          'document_version_id',v.id)),
        status='QUEUED'::public.mail_status_enum,
        scheduled_for_utc=v_now,
        next_attempt_at_utc=v_now,
        last_error=null,
        failed_at=null,
        payment_scope_json=coalesce(m.payment_scope_json,'{}'::jsonb)
          ||jsonb_build_object(
            'mail_held_until_pdf_rendered',false,
            'mail_hold_reason',null,
            'mail_delayed_for_pdf_render',false,
            'requires_pdf_render',false,
            'release_mail_after_pdf_render',false,
            'pdf_storage_key',v.r2_key,
            'pdf_sha256',v.sha256,
            'pdf_size_bytes',v.size_bytes,
            'document_version_id',v.id,
            'pdf_ready_at_utc',v_now)
    from ready_versions v
    join public.timesheets t on t.timesheet_id=v.entity_id and t.is_current
    where v.entity_type='TIMESHEET' and v.purpose='TIMESHEET'
      and v.snapshot_json#>>'{presentation_model,schema_version}'
        ='TIMESHEET_RENDER_MODEL_V2'
      and v.snapshot_json#>>'{presentation_model,form_variant}'='QR_UNSIGNED'
      and t.document_revision::text=v.source_revision
      and upper(coalesce(t.qr_status::text,''))='PENDING'
      and nullif(t.qr_scanned_at::text,'') is null
      and nullif(t.qr_signed_hash,'') is null
      and nullif(t.qr_signed_at_utc::text,'') is null
      -- Candidate PAPER email is released only by the complete-pack scheduler.
      -- The ordinary QR base-document completion must never replace its frozen
      -- workflow binding, hold state or complete-pack attachment.
      and nullif(btrim(coalesce(
        m.payment_scope_json->>'candidate_workflow_id','')),'') is null
      and not exists(
        select 1
        from public.candidate_submission_workflows candidate_workflow
        where candidate_workflow.route='PAPER'
          and candidate_workflow.state='AWAITING_PAPER_RETURN'
          and (candidate_workflow.target_timesheet_id=t.timesheet_id
            or candidate_workflow.anchor_timesheet_id=t.timesheet_id)
      )
      and m.type='TIMESHEET_QR'
      and m.context_kind='timesheets'
      and m.context_id=t.timesheet_id
      and m.status<>'SENT'::public.mail_status_enum
      and m."to"=m.payment_scope_json->>'recipient_email'
      and m.payment_scope_json->>'current_timesheet_id'=t.timesheet_id::text
      and m.payment_scope_json->>'document_version_id'=v.id::text
      and m.payment_scope_json->>'document_revision'=v.source_revision
      and m.payment_scope_json->>'template_version'=v.template_version
      and m.payment_scope_json->>'qr_token_hash'=encode(
        digest(coalesce(t.qr_token,''),'sha256'),'hex')
      and m.payment_scope_json->>'qr_payload_hash'=encode(
        digest(coalesce(t.qr_payload_json,'{}'::jsonb)::text,'sha256'),'hex')
      and m.payment_scope_json->>'week_period_hash'=
        v.snapshot_json#>>'{presentation_model,week_period_hash}'
      and m.payment_scope_json->>'reference_signature'=
        v.snapshot_json#>>'{presentation_model,reference_signature}'
      and m.payment_scope_json->>'additional_units_hash'=
        v.snapshot_json#>>'{presentation_model,additional_units_hash}'
      and m.payment_scope_json->>'presentation_settings_hash'=
        v.snapshot_json#>>'{presentation_model,presentation_settings_hash}'
    returning m.id
  ),
  issue_wake as (
    update public.invoice_operation_chunks i
    set status='QUEUED',phase='FINALISE',run_after_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,error_json=null
    where i.chunk_type='ISSUE_INVOICE' and i.phase='WAIT_DOCUMENT'
      and i.status in('WAITING','RETRY_WAIT')
      and coalesce(
        case when coalesce(i.payload_json->>'document_version_id','') ~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(i.payload_json->>'document_version_id')::uuid end,
        case when coalesce(i.payload_json->>'final_document_version_id','') ~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(i.payload_json->>'final_document_version_id')::uuid end
      ) in(
        select id from ready_versions where purpose='FINAL_ISSUE')
    returning i.operation_id
  )
  select count(*) into v_ignored from ready_versions;

  /*
   * Non-success outcomes, and malformed current success results reclassified
   * above, receive one explicit transition with bounded error history.
   */
  with supplied as materialized (
    select x.value item,(x.value->>'chunk_id')::uuid chunk_id,
      upper(x.value->>'outcome') outcome,
      upper(coalesce(x.value#>>'{error,code}','PROCESSOR_FAILURE')) error_code,
      (lower(coalesce(x.value#>>'{error,transient}','false'))='true'
        or upper(coalesce(x.value#>>'{error,class}',''))='TRANSIENT'
        or upper(x.value->>'outcome')='RETRY') transient
    from jsonb_array_elements(v_valid_results) x(value)
    where x.value->>'outcome'<>'SUCCESS'
  ),
  transitioned as materialized (
    update public.invoice_operation_chunks c
    set status=case
          when s.outcome='CANCELLED' then 'CANCELLED'
          when s.outcome='SUPERSEDED' then 'SUPERSEDED'
          when s.outcome='BLOCKED' then 'BLOCKED'
          when s.transient and c.attempt_count<c.max_attempts then 'RETRY_WAIT'
          when s.transient then 'DEAD_LETTER'
          else 'FAILED' end,
        phase=case
          when s.outcome='CANCELLED' then 'CANCELLED'
          when s.outcome='SUPERSEDED' then 'SUPERSEDED'
          when s.outcome='BLOCKED' then 'BLOCKED'
          when s.transient and c.attempt_count<c.max_attempts then c.phase
          when s.transient then 'DEAD_LETTER'
          else 'FAILED' end,
        run_after_utc=case when s.transient and c.attempt_count<c.max_attempts
          then v_now+make_interval(secs=>
            least(1800,30*(2^least(greatest(c.attempt_count-1,0),6)))::integer
            +floor(random()*least(60,5*greatest(c.attempt_count,1)))::integer)
          else c.run_after_utc end,
        error_json=jsonb_build_object(
          'code',s.error_code,
          'class',case when s.transient then 'TRANSIENT' else 'PERMANENT' end,
          'retryable',s.transient and c.attempt_count<c.max_attempts,
          'details',s.item->'error',
          'history',coalesce((
            select jsonb_agg(h.value order by h.ordinality)
            from jsonb_array_elements(coalesce(c.error_json->'history','[]'::jsonb))
                 with ordinality h(value,ordinality)
            where h.ordinality>greatest(
              jsonb_array_length(coalesce(c.error_json->'history','[]'::jsonb))-6,0)
          ),'[]'::jsonb)||jsonb_build_array(jsonb_build_object(
            'code',coalesce(c.error_json->>'code','UNKNOWN'),'at_utc',v_now))),
        failed_at_utc=case
          when not(s.transient and c.attempt_count<c.max_attempts) then v_now else null end,
        completed_at_utc=case when s.outcome in('CANCELLED','SUPERSEDED') then v_now
          else c.completed_at_utc end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=v_now
    from supplied s where c.id=s.chunk_id
    returning c.*
  ),
  asset_failures as materialized (
    update public.invoice_document_assets a
    set status=case upper(coalesce(t.error_json->>'code',''))
          when 'ASSET_MEDIA_TYPE_UNSUPPORTED' then 'UNSUPPORTED'
          when 'ASSET_PDF_ENCRYPTED' then 'UNSUPPORTED'
          when 'CORRUPT_PDF' then 'CORRUPT'
          when 'TRUNCATED_FILE' then 'CORRUPT'
          when 'EMPTY_FILE' then 'CORRUPT'
          when 'MISSING_SOURCE' then 'MISSING'
          else 'FAILED' end,
        error_json=t.error_json,updated_at_utc=v_now
    from transitioned t
    where a.id=t.document_asset_id
      and t.status in('FAILED','DEAD_LETTER','BLOCKED')
      and a.status not in('READY','SUPERSEDED')
    returning a.*
  ),
  evidence_failed as (
    update public.timesheet_evidence e
    set processing_state=a.status,processing_error_json=a.error_json
    from asset_failures a
    where a.source_kind='TIMESHEET_EVIDENCE' and e.id=a.source_id
    returning e.id,e.timesheet_id,e.kind,e.document_asset_id
  ),
  manual_evidence_failed as (
    update public.timesheets t
    set document_state='FAILED',last_document_error_json=a.error_json,updated_at=v_now
    from evidence_failed e
    join asset_failures a on a.id=e.document_asset_id
    where upper(e.kind)='TIMESHEET' and t.timesheet_id=e.timesheet_id and t.is_current
    returning t.timesheet_id
  ),
  manual_asset_failed as (
    update public.timesheets t
    set document_state='FAILED',last_document_error_json=a.error_json,
        updated_at=v_now
    from asset_failures a
    where a.source_kind='MANUAL_TIMESHEET'
      and t.timesheet_id=a.source_id and t.is_current
    returning t.timesheet_id
  ),
  blocked_dependencies as materialized (
    update public.invoice_operation_chunks d
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,updated_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','DOCUMENT_DEPENDENCY_PERMANENT_FAILURE',
          'document_asset_id',a.id,'source_kind',a.source_kind,
          'source_id',a.source_id,'asset_error',a.error_json)
    from asset_failures a
    where d.chunk_type='DOCUMENT_INPUT' and d.document_asset_id=a.id
      and d.status='WAITING'
    returning d.id,d.operation_id,d.document_version_id,d.error_json
  ),
  failed_document_versions as (
    update public.invoice_document_versions v
    set status='FAILED',error_json=jsonb_build_object(
          'code','DOCUMENT_DEPENDENCY_PERMANENT_FAILURE',
          'source_errors',coalesce((
            select jsonb_agg(d.error_json order by d.id)
            from blocked_dependencies d
            where d.document_version_id=v.id),'[]'::jsonb)),
        superseded_at_utc=null
    where v.id in(select document_version_id from blocked_dependencies)
      and v.status not in('READY','SUPERSEDED','CANCELLED')
    returning v.id,v.operation_id,v.entity_type,v.entity_id,v.purpose,v.error_json
  ),
  plan_wake as (
    update public.invoice_operation_chunks p
    set status='QUEUED',phase='WAIT_FOR_INPUTS',run_after_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where p.chunk_type='DOCUMENT_PLAN'
      and p.document_version_id in(select document_version_id from blocked_dependencies)
      and p.status in('WAITING','RETRY_WAIT','BLOCKED')
    returning p.id
  ),
  issue_block as (
    update public.invoice_operation_chunks i
    set status='BLOCKED',phase='WAIT_DOCUMENT',failed_at_utc=v_now,updated_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','FINAL_DOCUMENT_PERMANENT_FAILURE',
          'document_version_id',v.id,'document_error',v.error_json)
    from failed_document_versions v
    where i.chunk_type='ISSUE_INVOICE' and i.phase='WAIT_DOCUMENT'
      and i.status in('WAITING','RETRY_WAIT')
      and coalesce(
        case when coalesce(i.payload_json->>'document_version_id','')~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(i.payload_json->>'document_version_id')::uuid end,
        case when coalesce(i.payload_json->>'final_document_version_id','')~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(i.payload_json->>'final_document_version_id')::uuid end)=v.id
    returning i.operation_id
  ),
  blocked_operation_updates as materialized (
    select r.*
    from private._invoice_operation_rollup_batch(
      coalesce((select array_agg(distinct affected.operation_id)
        from (
          select d.operation_id from blocked_dependencies d
          union
          select i.operation_id from issue_block i
        ) affected),array[]::uuid[]),
      v_now,true) r
  )
  select count(*) into v_ignored from transitioned;

  /* Merge completion or dependency change wakes the owning plan exactly once. */
  with affected_versions as materialized (
    select distinct c.document_version_id
    from jsonb_array_elements(v_valid_results) x
    join public.invoice_operation_chunks c on c.id=(x->>'chunk_id')::uuid
    where c.document_version_id is not null
      and c.chunk_type in(
        'ASSET_NORMALISE','SOURCE_RENDER','INVOICE_CORE_RENDER','PDF_MERGE','DOCUMENT_VERIFY')
      and c.status in('COMPLETE','FAILED','DEAD_LETTER','BLOCKED')
  ),
  plan_wake as (
    update public.invoice_operation_chunks p
    set status='QUEUED',run_after_utc=v_now,updated_at_utc=v_now,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where p.chunk_type='DOCUMENT_PLAN' and p.status in('WAITING','RETRY_WAIT')
      and p.document_version_id in(select document_version_id from affected_versions)
    returning p.id
  )
  select count(*) into v_ignored from plan_wake;

  with affected as materialized (
    select distinct c.operation_id
    from jsonb_array_elements(v_valid_results) x
    join public.invoice_operation_chunks c on c.id=(x->>'chunk_id')::uuid
    union
    select distinct d.operation_id
    from jsonb_array_elements(v_valid_results) x
    join public.invoice_operation_chunks source
      on source.id=(x->>'chunk_id')::uuid
    join public.invoice_operation_chunks d
      on d.chunk_type='DOCUMENT_INPUT'
      and d.document_asset_id=source.document_asset_id
    where source.document_asset_id is not null
    union
    select distinct p.operation_id
    from jsonb_array_elements(v_valid_results) x
    join public.invoice_operation_chunks source
      on source.id=(x->>'chunk_id')::uuid
    join public.invoice_operation_chunks p
      on p.chunk_type='DOCUMENT_PLAN'
      and p.document_version_id=source.document_version_id
    where source.document_version_id is not null
  ),
  operation_updates as (
    select r.*
    from private._invoice_operation_rollup_batch(
      coalesce((select array_agg(operation_id) from affected),
        array[]::uuid[]),v_now,true) r
  )
  select count(*) into v_ignored from operation_updates;

  with valid_items as (
    select x.value item from jsonb_array_elements(v_valid_results) x(value)
  ),
  results as (
    select (item->>'request_no')::integer request_no,jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,'accepted',true,
      'run_after_utc',c.run_after_utc,'attempt_count',c.attempt_count,
      'error',c.error_json,'result',case when c.status='COMPLETE' then c.result_json end) result
    from valid_items v join public.invoice_operation_chunks c
      on c.id=(v.item->>'chunk_id')::uuid
    union all
    select (x.value->>'request_no')::integer request_no,x.value result
    from jsonb_array_elements(v_rejections) x(value)
  )
  select coalesce(jsonb_agg(result order by request_no),'[]'::jsonb)
  into v_result from results;

  return v_result;
end;
$function$;

revoke all on function public.invoice_work_complete_batch(jsonb,timestamptz)
  from public,anon,authenticated;
grant execute on function public.invoice_work_complete_batch(jsonb,timestamptz)
  to service_role;

-- The historical detail/editor source pages above still carry their original
-- browser grants. Reassert the current service-only authority inside this
-- recursive closure so an incremental replay cannot end before the later
-- standalone ACL repeatable is selected again.
-- The current invoice editor is re-included by later July repeatables. Reassert
-- its final service-only ACL after the frozen-settings source change so NEW and
-- UPGRADE installations end with the same browser-isolated authority.

alter function public.invoice_apply_edits(uuid,jsonb,uuid) OWNER TO CURRENT_USER;

revoke all on function public.invoice_apply_edits(uuid,jsonb,uuid)
  from public,anon,authenticated,service_role,supabase_admin;

grant execute on function public.invoice_apply_edits(uuid,jsonb,uuid)
  to CURRENT_USER,service_role;

alter function public.invoice_detail_get(uuid,uuid) OWNER TO CURRENT_USER;

revoke all on function public.invoice_detail_get(uuid,uuid)
  from public,anon,authenticated,service_role,supabase_admin;

grant execute on function public.invoice_detail_get(uuid,uuid)
  to CURRENT_USER,service_role;


commit;

-- CONTACT_PREPARER_UNIT 20 repeatable supabase/repeatable/30072026_1745_invoice_source_edit_residual_fix.sql SHA256 b1ced3bf4edaefda95495b690a90bbaf3150cde5f5303a4e07ac9f3430b3633e




create or replace function public.trg_timesheet_document_invalidate()
returns trigger
language plpgsql
security definer
set search_path to 'public','pg_temp'
as $function$
declare
  v_timesheet_ids uuid[]:=array[]::uuid[];
  v_timesheet_version_ids uuid[]:=array[]::uuid[];
  v_invoice_ids uuid[]:=array[]::uuid[];
  v_invoice_version_ids uuid[]:=array[]::uuid[];
  v_timesheet_document_operation_ids uuid[]:=array[]::uuid[];
  v_invoice_document_operation_ids uuid[]:=array[]::uuid[];
  v_issue_operation_ids uuid[]:=array[]::uuid[];
  v_delivery_operation_ids uuid[]:=array[]::uuid[];
  v_operation_ids uuid[]:=array[]::uuid[];
  v_source_marker jsonb:='{}'::jsonb;
begin
  begin
    v_source_marker:=coalesce(
      nullif(current_setting('cloudtms.invoice_source_edit_marker',true),'')::jsonb,
      '{}'::jsonb);
  exception when others then
    v_source_marker:='{}'::jsonb;
  end;
  if tg_table_name='timesheets' and tg_op='UPDATE' then
    select coalesce(array_agg(distinct n.timesheet_id),array[]::uuid[])
    into v_timesheet_ids
    from new_rows n join old_rows o on o.timesheet_id=n.timesheet_id
    where(n.is_current or o.is_current) and(
      n.booking_id is distinct from o.booking_id
      or n.occupant_key_norm is distinct from o.occupant_key_norm
      or n.hospital_norm is distinct from o.hospital_norm
      or n.ward_norm is distinct from o.ward_norm
      or n.job_title_norm is distinct from o.job_title_norm
      or n.shift_label_norm is distinct from o.shift_label_norm
      or n.scheduled_start_iso is distinct from o.scheduled_start_iso
      or n.scheduled_end_iso is distinct from o.scheduled_end_iso
      or n.worked_start_iso is distinct from o.worked_start_iso
      or n.worked_end_iso is distinct from o.worked_end_iso
      or n.break_start_iso is distinct from o.break_start_iso
      or n.break_end_iso is distinct from o.break_end_iso
      or n.break_minutes is distinct from o.break_minutes
      or n.worked_minutes is distinct from o.worked_minutes
      or n.week_ending_date is distinct from o.week_ending_date
      or n.auth_name is distinct from o.auth_name
      or n.auth_job_title is distinct from o.auth_job_title
      or n.authorised_at_server is distinct from o.authorised_at_server
      or n.r2_nurse_key is distinct from o.r2_nurse_key
      or n.r2_auth_key is distinct from o.r2_auth_key
      or n.img_sha256_nurse is distinct from o.img_sha256_nurse
      or n.img_sha256_auth is distinct from o.img_sha256_auth
      or n.reference_number is distinct from o.reference_number
      or n.status is distinct from o.status
      or n.version is distinct from o.version
      or n.is_current is distinct from o.is_current
      or n.revoked_at is distinct from o.revoked_at
      or n.contract_id is distinct from o.contract_id
      or n.submission_mode is distinct from o.submission_mode
      or n.line_type is distinct from o.line_type
      or n.sheet_scope is distinct from o.sheet_scope
      or n.actual_schedule_json is distinct from o.actual_schedule_json
      or n.additional_units_week is distinct from o.additional_units_week
      or n.additional_units_per_day is distinct from o.additional_units_per_day
      or n.day_references_json is distinct from o.day_references_json
      or n.qr_token is distinct from o.qr_token
      or n.qr_payload_json is distinct from o.qr_payload_json
      or n.qr_signed_hash is distinct from o.qr_signed_hash
      or n.qr_signed_at_utc is distinct from o.qr_signed_at_utc
      or n.qr_status is distinct from o.qr_status
      or n.qr_r2_key is distinct from o.qr_r2_key
      or n.candidate_hint_text is distinct from o.candidate_hint_text
      or n.band is distinct from o.band
      or n.is_adjustment is distinct from o.is_adjustment
      or n.parent_timesheet_id is distinct from o.parent_timesheet_id
      or n.correction_id is distinct from o.correction_id
      or n.correction_kind is distinct from o.correction_kind
      or n.adjustment_origin is distinct from o.adjustment_origin);
  elsif tg_table_name='timesheets_financials' and tg_op='INSERT' then
    select coalesce(array_agg(distinct timesheet_id),array[]::uuid[])
    into v_timesheet_ids from new_rows where is_current;
  elsif tg_table_name='timesheets_financials' and tg_op='DELETE' then
    select coalesce(array_agg(distinct timesheet_id),array[]::uuid[])
    into v_timesheet_ids from old_rows where is_current;
  elsif tg_table_name='timesheets_financials' and tg_op='UPDATE' then
    select coalesce(array_agg(distinct timesheet_id),array[]::uuid[])
    into v_timesheet_ids
    from (
      select n.timesheet_id
      from new_rows n join old_rows o on o.id=n.id
      where(n.is_current or o.is_current) and(
        n.timesheet_id is distinct from o.timesheet_id
        or n.timesheet_version is distinct from o.timesheet_version
        or n.basis is distinct from o.basis
        or n.is_current is distinct from o.is_current
        or n.is_stale is distinct from o.is_stale
        or n.worked_start_iso is distinct from o.worked_start_iso
        or n.worked_end_iso is distinct from o.worked_end_iso
        or n.break_start_iso is distinct from o.break_start_iso
        or n.break_end_iso is distinct from o.break_end_iso
        or n.break_minutes is distinct from o.break_minutes
        or n.candidate_id is distinct from o.candidate_id
        or n.client_id is distinct from o.client_id
        or n.role is distinct from o.role
        or n.band is distinct from o.band
        or n.policy_snapshot_json is distinct from o.policy_snapshot_json
        or n.rate_source_refs_json is distinct from o.rate_source_refs_json
        or n.hours_day is distinct from o.hours_day
        or n.hours_night is distinct from o.hours_night
        or n.hours_sat is distinct from o.hours_sat
        or n.hours_sun is distinct from o.hours_sun
        or n.hours_bh is distinct from o.hours_bh
        or n.pay_day is distinct from o.pay_day
        or n.pay_night is distinct from o.pay_night
        or n.pay_sat is distinct from o.pay_sat
        or n.pay_sun is distinct from o.pay_sun
        or n.pay_bh is distinct from o.pay_bh
        or n.charge_day is distinct from o.charge_day
        or n.charge_night is distinct from o.charge_night
        or n.charge_sat is distinct from o.charge_sat
        or n.charge_sun is distinct from o.charge_sun
        or n.charge_bh is distinct from o.charge_bh
        or n.total_hours is distinct from o.total_hours
        or n.total_pay_ex_vat is distinct from o.total_pay_ex_vat
        or n.total_charge_ex_vat is distinct from o.total_charge_ex_vat
        or n.margin_ex_vat is distinct from o.margin_ex_vat
        or n.processing_status is distinct from o.processing_status
        or n.expenses_pay_ex_vat is distinct from o.expenses_pay_ex_vat
        or n.expenses_charge_ex_vat is distinct from o.expenses_charge_ex_vat
        or n.expenses_description is distinct from o.expenses_description
        or n.expenses_evidence_manifest is distinct from o.expenses_evidence_manifest
        or n.mileage_pay_ex_vat is distinct from o.mileage_pay_ex_vat
        or n.mileage_charge_ex_vat is distinct from o.mileage_charge_ex_vat
        or n.mileage_pay_rate is distinct from o.mileage_pay_rate
        or n.mileage_charge_rate is distinct from o.mileage_charge_rate
        or n.mileage_evidence_manifest is distinct from o.mileage_evidence_manifest
        or n.actual_schedule_json is distinct from o.actual_schedule_json
        or n.actual_minutes_by_day_json is distinct from o.actual_minutes_by_day_json
        or n.additional_units_json is distinct from o.additional_units_json
        or n.additional_pay_ex_vat is distinct from o.additional_pay_ex_vat
        or n.additional_charge_ex_vat is distinct from o.additional_charge_ex_vat
        or n.additional_margin_ex_vat is distinct from o.additional_margin_ex_vat
        or n.invoice_breakdown_json is distinct from o.invoice_breakdown_json
        or n.nhsp_import_id is distinct from o.nhsp_import_id
        or n.has_rate_issue is distinct from o.has_rate_issue
        or n.hr_crosscheck_status is distinct from o.hr_crosscheck_status
        or n.hr_crosscheck_issues is distinct from o.hr_crosscheck_issues
        or n.external_source_rows_json is distinct from o.external_source_rows_json
        or n.mileage_units is distinct from o.mileage_units
        or n.travel_pay_ex_vat is distinct from o.travel_pay_ex_vat
        or n.travel_charge_ex_vat is distinct from o.travel_charge_ex_vat
        or n.accommodation_pay_ex_vat is distinct from o.accommodation_pay_ex_vat
        or n.accommodation_charge_ex_vat is distinct from o.accommodation_charge_ex_vat
        or n.other_pay_ex_vat is distinct from o.other_pay_ex_vat
        or n.other_charge_ex_vat is distinct from o.other_charge_ex_vat)
      union
      select o.timesheet_id
      from old_rows o join new_rows n on n.id=o.id
      where n.timesheet_id is distinct from o.timesheet_id
    ) changed
    where timesheet_id is not null;

    -- A source-edit transaction may synchronise only SEGMENTS.ref_num into the
    -- current financial projection. Suppress that second invalidation solely
    -- when the row shape is ref-only and the transaction-local marker proves
    -- this exact timesheet revision already advanced. Any other TSFIN change
    -- keeps the ordinary invalidation path.
    v_timesheet_ids:=array(
      select changed_id.candidate_id
      from unnest(v_timesheet_ids) changed_id(candidate_id)
      where exists(
        select 1
        from new_rows n
        join old_rows o on o.id=n.id
        where (n.timesheet_id=changed_id.candidate_id
          or o.timesheet_id=changed_id.candidate_id)
          and not (
            (to_jsonb(n)-'invoice_breakdown_json'-'updated_at')
              is not distinct from
            (to_jsonb(o)-'invoice_breakdown_json'-'updated_at')
            and n.id=o.id
            and n.timesheet_id=o.timesheet_id
            and n.is_current and o.is_current
            and upper(coalesce(n.invoice_breakdown_json->>'mode',''))='SEGMENTS'
            and upper(coalesce(o.invoice_breakdown_json->>'mode',''))='SEGMENTS'
            and jsonb_typeof(n.invoice_breakdown_json->'segments')='array'
            and jsonb_typeof(o.invoice_breakdown_json->'segments')='array'
            and jsonb_array_length(n.invoice_breakdown_json->'segments')
                =jsonb_array_length(o.invoice_breakdown_json->'segments')
            and v_source_marker->>'txid'=txid_current()::text
            and jsonb_typeof(v_source_marker->'rows')='object'
            and (v_source_marker->'rows') ? changed_id.candidate_id::text
            and coalesce(v_source_marker#>>
                  array['rows',changed_id.candidate_id::text,'expected_revision'],'')
                  ~'^[1-9][0-9]*$'
            and exists(
              select 1
              from public.timesheets marker_ts
              where marker_ts.timesheet_id=changed_id.candidate_id
                and marker_ts.is_current
                and marker_ts.document_revision=(
                  v_source_marker#>>
                    array['rows',changed_id.candidate_id::text,'expected_revision'])::bigint
            )
            and (
              select coalesce(jsonb_agg(seg.value-'ref_num' order by seg.ord),'[]'::jsonb)
              from jsonb_array_elements(n.invoice_breakdown_json->'segments')
                with ordinality seg(value,ord)
            ) is not distinct from (
              select coalesce(jsonb_agg(seg.value-'ref_num' order by seg.ord),'[]'::jsonb)
              from jsonb_array_elements(o.invoice_breakdown_json->'segments')
                with ordinality seg(value,ord)
            )
            and not exists(
              select 1
              from jsonb_array_elements(n.invoice_breakdown_json->'segments')
                with ordinality ns(value,ord)
              join jsonb_array_elements(o.invoice_breakdown_json->'segments')
                with ordinality os(value,ord) using(ord)
              where nullif(btrim(coalesce(ns.value->>'ref_num','')),'')
                      is distinct from
                    nullif(btrim(coalesce(os.value->>'ref_num','')),'')
                and not exists(
                  select 1
                  from public.timesheets ts
                  where ts.timesheet_id=n.timesheet_id
                    and ts.is_current
                    and (
                      (
                        jsonb_typeof(ts.actual_schedule_json)='array'
                        and (
                      (
                        nullif(btrim(coalesce(ns.value->>'segment_id','')),'') is not null
                        and (
                          select count(*)
                          from jsonb_array_elements(ts.actual_schedule_json) sch(value)
                          where nullif(btrim(coalesce(sch.value->>'segment_id','')),'')
                            =nullif(btrim(coalesce(ns.value->>'segment_id','')),'')
                        )=1
                        and (
                          select nullif(btrim(coalesce(sch.value->>'ref_num','')),'')
                          from jsonb_array_elements(ts.actual_schedule_json) sch(value)
                          where nullif(btrim(coalesce(sch.value->>'segment_id','')),'')
                            =nullif(btrim(coalesce(ns.value->>'segment_id','')),'')
                          limit 1
                        ) is not distinct from
                          nullif(btrim(coalesce(ns.value->>'ref_num','')),'')
                      )
                      or (
                        (
                          nullif(btrim(coalesce(ns.value->>'segment_id','')),'') is null
                          or (
                            select count(*)
                            from jsonb_array_elements(ts.actual_schedule_json) sch(value)
                            where nullif(btrim(coalesce(sch.value->>'segment_id','')),'')
                              =nullif(btrim(coalesce(ns.value->>'segment_id','')),'')
                          )=0
                        )
                        and nullif(btrim(coalesce(
                          ns.value->>'start_utc',ns.value->>'start','')),'') is not null
                        and nullif(btrim(coalesce(
                          ns.value->>'end_utc',ns.value->>'end','')),'') is not null
                        and (
                          select count(*)
                          from jsonb_array_elements(ts.actual_schedule_json) sch(value)
                          where nullif(btrim(coalesce(
                                  sch.value->>'start_utc',sch.value->>'start','')),'')
                                =nullif(btrim(coalesce(
                                  ns.value->>'start_utc',ns.value->>'start','')),'')
                            and nullif(btrim(coalesce(
                                  sch.value->>'end_utc',sch.value->>'end','')),'')
                                =nullif(btrim(coalesce(
                                  ns.value->>'end_utc',ns.value->>'end','')),'')
                        )=1
                        and (
                          select nullif(btrim(coalesce(sch.value->>'ref_num','')),'')
                          from jsonb_array_elements(ts.actual_schedule_json) sch(value)
                          where nullif(btrim(coalesce(
                                  sch.value->>'start_utc',sch.value->>'start','')),'')
                                =nullif(btrim(coalesce(
                                  ns.value->>'start_utc',ns.value->>'start','')),'')
                            and nullif(btrim(coalesce(
                                  sch.value->>'end_utc',sch.value->>'end','')),'')
                                =nullif(btrim(coalesce(
                                  ns.value->>'end_utc',ns.value->>'end','')),'')
                          limit 1
                        ) is not distinct from
                          nullif(btrim(coalesce(ns.value->>'ref_num','')),'')
                      )
                        )
                      )
                      or (
                        v_source_marker->>'txid'=txid_current()::text
                        and (v_source_marker->'rows') ? changed_id.candidate_id::text
                      )
                    )
                )
            )
          )
      )
    );
  elsif tg_table_name='timesheet_evidence' and tg_op='INSERT' then
    select coalesce(array_agg(distinct timesheet_id),array[]::uuid[])
    into v_timesheet_ids from new_rows;
  elsif tg_table_name='timesheet_evidence' and tg_op='DELETE' then
    select coalesce(array_agg(distinct timesheet_id),array[]::uuid[])
    into v_timesheet_ids from old_rows;
  elsif tg_table_name='timesheet_evidence' and tg_op='UPDATE' then
    select coalesce(array_agg(distinct timesheet_id),array[]::uuid[])
    into v_timesheet_ids
    from (
      select n.timesheet_id
      from new_rows n join old_rows o on o.id=n.id
      where n.timesheet_id is distinct from o.timesheet_id
        or n.kind is distinct from o.kind
        or n.storage_key is distinct from o.storage_key
        or n.source_revision is distinct from o.source_revision
        or n.display_name is distinct from o.display_name
      union
      select o.timesheet_id
      from old_rows o join new_rows n on n.id=o.id
      where n.timesheet_id is distinct from o.timesheet_id
        or n.kind is distinct from o.kind
        or n.storage_key is distinct from o.storage_key
        or n.source_revision is distinct from o.source_revision
        or n.display_name is distinct from o.display_name
    ) changed
    where timesheet_id is not null;
  end if;

  if cardinality(v_timesheet_ids)=0 then return null; end if;

  update public.timesheets t
  set document_revision=t.document_revision+1,document_state='STALE',
    current_document_version_id=null,active_document_operation_id=null,
    last_document_error_json=null
  where t.timesheet_id=any(v_timesheet_ids) and t.is_current;

  with changed as materialized (
    update public.invoice_document_versions v
    set status='SUPERSEDED',superseded_at_utc=now(),
      error_json=jsonb_build_object(
        'code','TIMESHEET_SOURCE_CHANGED','timesheet_id',v.entity_id)
    where v.entity_type='TIMESHEET' and v.entity_id=any(v_timesheet_ids)
      and v.purpose='TIMESHEET'
      and v.status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING')
    returning v.id,v.operation_id
  )
  select coalesce(array_agg(id),array[]::uuid[]),
    coalesce(array_agg(distinct operation_id),array[]::uuid[])
  into v_timesheet_version_ids,v_timesheet_document_operation_ids
  from changed;

  update public.invoice_operation_chunks c
  set status='SUPERSEDED',phase='SUPERSEDED',
    replacement_required=false,replaced_by_chunk_id=null,
    lease_owner=null,lease_token=null,lease_expires_at_utc=null,
    completed_at_utc=now(),updated_at_utc=now(),
    error_json=jsonb_build_object(
      'code','TIMESHEET_SOURCE_CHANGED','timesheet_id',c.entity_id)
  where c.document_version_id=any(v_timesheet_version_ids)
    and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED');

  update public.invoice_operations o
  set control_version=o.control_version+1,status='SUPERSEDED',phase='SUPERSEDED',
    completed_at_utc=now(),updated_at_utc=now(),
    error_json=jsonb_build_object('code','TIMESHEET_SOURCE_CHANGED'),
    change_seq=nextval('public.invoice_operation_change_seq')
  where o.id=any(v_timesheet_document_operation_ids)
    and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED');

  select coalesce(array_agg(distinct l.invoice_id),array[]::uuid[])
  into v_invoice_ids
  from public.invoice_lines l
  join public.invoices i on i.id=l.invoice_id
  where (
      l.timesheet_id=any(v_timesheet_ids)
      or (
        l.timesheet_id is null
        and coalesce(l.meta_json->>'timesheet_id','') ~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        and (l.meta_json->>'timesheet_id')::uuid=any(v_timesheet_ids)
      )
    )
    and i.status in('DRAFT','ON_HOLD')
    and i.issued_at_utc is null
    and i.paid_at_utc is null;

  if cardinality(v_invoice_ids)>0 then
    update public.invoices i
    set document_revision=i.document_revision+1,document_state='STALE',
      preview_document_version_id=null,active_document_operation_id=null,
      issue_state=case
        when i.issue_state in('VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
          then 'SUPERSEDED' else i.issue_state end,
      active_issue_operation_id=null,last_document_error_json=null
    where i.id=any(v_invoice_ids);

    with changed as materialized (
      update public.invoice_document_versions v
      set status='SUPERSEDED',superseded_at_utc=now(),
        error_json=jsonb_build_object(
          'code','TIMESHEET_SOURCE_CHANGED','invoice_id',v.entity_id)
      where v.entity_type='INVOICE' and v.entity_id=any(v_invoice_ids)
        and v.purpose in('DRAFT_PREVIEW','FINAL_ISSUE')
        and v.status in(
          'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING')
      returning v.id,v.operation_id
    )
    select coalesce(array_agg(id),array[]::uuid[]),
      coalesce(array_agg(distinct operation_id),array[]::uuid[])
    into v_invoice_version_ids,v_invoice_document_operation_ids
    from changed;

    update public.invoice_operation_chunks c
    set status='SUPERSEDED',phase='SUPERSEDED',
      replacement_required=false,replaced_by_chunk_id=null,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      completed_at_utc=now(),updated_at_utc=now(),
      error_json=jsonb_build_object(
        'code','TIMESHEET_SOURCE_CHANGED','document_version_id',c.document_version_id)
    where c.document_version_id=any(v_invoice_version_ids)
      and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED');

    update public.invoice_operations o
    set control_version=o.control_version+1,updated_at_utc=now(),
      change_seq=nextval('public.invoice_operation_change_seq')
    where o.id=any(v_invoice_document_operation_ids)
      and o.operation_type='BUILD_DOCUMENT'
      and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED');

    with changed as materialized (
      update public.invoice_operation_chunks c
      set status='SUPERSEDED',phase='SUPERSEDED',
        replacement_required=false,replaced_by_chunk_id=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        completed_at_utc=now(),updated_at_utc=now(),
        error_json=jsonb_build_object(
          'code','TIMESHEET_SOURCE_CHANGED','invoice_id',c.entity_id)
      where c.chunk_type='ISSUE_INVOICE' and c.entity_type='INVOICE'
        and c.entity_id=any(v_invoice_ids)
        and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      returning c.operation_id
    )
    select coalesce(array_agg(distinct operation_id),array[]::uuid[])
    into v_issue_operation_ids from changed;

    with changed as materialized (
      update public.invoice_operation_chunks c
      set status='SUPERSEDED',phase='SUPERSEDED',
        replacement_required=false,replaced_by_chunk_id=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        completed_at_utc=now(),updated_at_utc=now(),
        error_json=jsonb_build_object(
          'code','TIMESHEET_SOURCE_CHANGED','invoice_id',c.entity_id)
      where c.chunk_type='DELIVERY_PREPARE' and c.entity_type='INVOICE'
        and c.entity_id=any(v_invoice_ids)
        and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      returning c.operation_id
    )
    select coalesce(array_agg(distinct operation_id),array[]::uuid[])
    into v_delivery_operation_ids from changed;
  end if;

  v_operation_ids:=array(
    select distinct x
    from unnest(coalesce(v_invoice_document_operation_ids,array[]::uuid[])
      ||coalesce(v_issue_operation_ids,array[]::uuid[])
      ||coalesce(v_delivery_operation_ids,array[]::uuid[])) x
    where x is not null);

  -- Keep the statement trigger bounded to direct invalidation.  Descendant
  -- aggregation is performed later by the worker/reconciliation path.
  update public.invoice_operations o
  set progress_json=jsonb_set(coalesce(o.progress_json,'{}'::jsonb),
        '{rollup_required}','true'::jsonb,true),
    updated_at_utc=now(),
    change_seq=nextval('public.invoice_operation_change_seq')
  where o.id=any(v_operation_ids)
    and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED');

  return null;
end;
$function$;

revoke all on function public.trg_timesheet_document_invalidate()
  from public,anon,authenticated;

create or replace function public.trg_invoice_document_invalidate()
returns trigger
language plpgsql
security definer
set search_path to 'public','pg_temp'
as $function$
declare
  v_invoice_ids uuid[]:=array[]::uuid[];
  v_version_ids uuid[]:=array[]::uuid[];
  v_document_operation_ids uuid[]:=array[]::uuid[];
  v_issue_operation_ids uuid[]:=array[]::uuid[];
  v_delivery_operation_ids uuid[]:=array[]::uuid[];
  v_operation_ids uuid[]:=array[]::uuid[];
begin
  if tg_table_name='invoices' and tg_op='UPDATE' then
    select coalesce(array_agg(distinct n.id),array[]::uuid[]) into v_invoice_ids
    from new_rows n join old_rows o on o.id=n.id
    where n.status in('DRAFT','ON_HOLD')
      and o.status in('DRAFT','ON_HOLD')
      and n.issued_at_utc is null and o.issued_at_utc is null
      and n.paid_at_utc is null and o.paid_at_utc is null
      and(
       n.client_id is distinct from o.client_id
       or n.invoice_no is distinct from o.invoice_no
       or n.type is distinct from o.type
       or n.original_invoice_id is distinct from o.original_invoice_id
       or n.subtotal_ex_vat is distinct from o.subtotal_ex_vat
       or n.vat_amount is distinct from o.vat_amount
       or n.total_inc_vat is distinct from o.total_inc_vat
       or n.due_at_utc is distinct from o.due_at_utc
       or n.notes is distinct from o.notes
       or n.do_not_send is distinct from o.do_not_send
       or n.header_snapshot_json is distinct from o.header_snapshot_json);
  elsif tg_table_name='invoice_lines' and tg_op='INSERT' then
    select coalesce(array_agg(distinct invoice_id),array[]::uuid[]) into v_invoice_ids from new_rows;
  elsif tg_table_name='invoice_lines' and tg_op='DELETE' then
    select coalesce(array_agg(distinct invoice_id),array[]::uuid[]) into v_invoice_ids from old_rows;
  elsif tg_table_name='invoice_lines' and tg_op='UPDATE' then
    select coalesce(array_agg(distinct invoice_id),array[]::uuid[]) into v_invoice_ids
    from (
      select n.invoice_id from new_rows n join old_rows o on o.id=n.id
      where n.invoice_id is distinct from o.invoice_id
         or n.timesheet_id is distinct from o.timesheet_id
         or n.booking_id is distinct from o.booking_id
         or n.source_key is distinct from o.source_key
         or n.description is distinct from o.description
         or n.hours_day is distinct from o.hours_day
         or n.hours_night is distinct from o.hours_night
         or n.hours_sat is distinct from o.hours_sat
         or n.hours_sun is distinct from o.hours_sun
         or n.hours_bh is distinct from o.hours_bh
         or n.pay_day is distinct from o.pay_day
         or n.pay_night is distinct from o.pay_night
         or n.pay_sat is distinct from o.pay_sat
         or n.pay_sun is distinct from o.pay_sun
         or n.pay_bh is distinct from o.pay_bh
         or n.charge_day is distinct from o.charge_day
         or n.charge_night is distinct from o.charge_night
         or n.charge_sat is distinct from o.charge_sat
         or n.charge_sun is distinct from o.charge_sun
         or n.charge_bh is distinct from o.charge_bh
         or n.total_pay_ex_vat is distinct from o.total_pay_ex_vat
         or n.total_charge_ex_vat is distinct from o.total_charge_ex_vat
         or n.vat_rate_pct is distinct from o.vat_rate_pct
         or n.vat_amount is distinct from o.vat_amount
         or n.total_inc_vat is distinct from o.total_inc_vat
         or n.margin_ex_vat is distinct from o.margin_ex_vat
         or (
           n.meta_json is distinct from o.meta_json
           and not exists(
             select 1
             from public.timesheets ts
             cross join lateral (
               select coalesce(jsonb_agg(to_jsonb(ref_value) order by ref_value),'[]'::jsonb) refs
               from (
                 select nullif(btrim(coalesce(ts.reference_number,'')),'') ref_value
                 union
                  select nullif(btrim(value),'')
                  from jsonb_each_text(coalesce(ts.day_references_json,'{}'::jsonb))
                  union
                  select nullif(btrim(coalesce(seg->>'ref_num','')),'')
                  from jsonb_array_elements(
                    coalesce(ts.actual_schedule_json,'[]'::jsonb)) seg
                  where not exists(
                    select 1
                    from public.timesheets_financials mode_tf
                    where mode_tf.timesheet_id=ts.timesheet_id
                      and mode_tf.is_current
                      and upper(coalesce(
                        mode_tf.invoice_breakdown_json->>'mode',''))='SEGMENTS'
                  )
                  union
                  select nullif(btrim(coalesce(seg.value->>'ref_num','')),'')
                  from public.timesheets_financials tf
                  cross join lateral jsonb_array_elements(
                    coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) seg(value)
                  where tf.timesheet_id=ts.timesheet_id
                    and tf.is_current
                    and upper(coalesce(tf.invoice_breakdown_json->>'mode',''))='SEGMENTS'
                    and nullif(btrim(coalesce(
                      seg.value->>'invoice_locked_invoice_id','')),'')=n.invoice_id::text
               ) canonical_refs
               where ref_value is not null
             ) calculated
             where ts.is_current
               and ts.timesheet_id=coalesce(
                 n.timesheet_id,
                 case when coalesce(n.meta_json->>'timesheet_id','') ~
                   '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                   then (n.meta_json->>'timesheet_id')::uuid end)
               and (
                 n.timesheet_id is null
                 or not (coalesce(n.meta_json->>'timesheet_id','') ~
                   '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')
                 or (n.meta_json->>'timesheet_id')::uuid=n.timesheet_id)
               and (coalesce(n.meta_json,'{}'::jsonb)
                     -'ts_reference_number'-'schedule_ref_nums'-'schedule_ref_count')
                   is not distinct from
                   (coalesce(o.meta_json,'{}'::jsonb)
                     -'ts_reference_number'-'schedule_ref_nums'-'schedule_ref_count')
               and n.meta_json->'ts_reference_number' is not distinct from
                 coalesce(to_jsonb(nullif(btrim(coalesce(ts.reference_number,'')),'')),'null'::jsonb)
               and n.meta_json->'schedule_ref_nums' is not distinct from calculated.refs
               and n.meta_json->'schedule_ref_count' is not distinct from
                 to_jsonb(jsonb_array_length(calculated.refs))
           )
         )
      union
      select o.invoice_id from old_rows o join new_rows n on n.id=o.id
      where n.invoice_id is distinct from o.invoice_id
         or n.timesheet_id is distinct from o.timesheet_id
         or n.booking_id is distinct from o.booking_id
         or n.source_key is distinct from o.source_key
         or n.description is distinct from o.description
         or n.hours_day is distinct from o.hours_day
         or n.hours_night is distinct from o.hours_night
         or n.hours_sat is distinct from o.hours_sat
         or n.hours_sun is distinct from o.hours_sun
         or n.hours_bh is distinct from o.hours_bh
         or n.pay_day is distinct from o.pay_day
         or n.pay_night is distinct from o.pay_night
         or n.pay_sat is distinct from o.pay_sat
         or n.pay_sun is distinct from o.pay_sun
         or n.pay_bh is distinct from o.pay_bh
         or n.charge_day is distinct from o.charge_day
         or n.charge_night is distinct from o.charge_night
         or n.charge_sat is distinct from o.charge_sat
         or n.charge_sun is distinct from o.charge_sun
         or n.charge_bh is distinct from o.charge_bh
         or n.total_pay_ex_vat is distinct from o.total_pay_ex_vat
         or n.total_charge_ex_vat is distinct from o.total_charge_ex_vat
         or n.vat_rate_pct is distinct from o.vat_rate_pct
         or n.vat_amount is distinct from o.vat_amount
         or n.total_inc_vat is distinct from o.total_inc_vat
         or n.margin_ex_vat is distinct from o.margin_ex_vat
         or (
           n.meta_json is distinct from o.meta_json
           and not exists(
             select 1
             from public.timesheets ts
             cross join lateral (
               select coalesce(jsonb_agg(to_jsonb(ref_value) order by ref_value),'[]'::jsonb) refs
               from (
                 select nullif(btrim(coalesce(ts.reference_number,'')),'') ref_value
                 union
                  select nullif(btrim(value),'')
                  from jsonb_each_text(coalesce(ts.day_references_json,'{}'::jsonb))
                  union
                  select nullif(btrim(coalesce(seg->>'ref_num','')),'')
                  from jsonb_array_elements(
                    coalesce(ts.actual_schedule_json,'[]'::jsonb)) seg
                  where not exists(
                    select 1
                    from public.timesheets_financials mode_tf
                    where mode_tf.timesheet_id=ts.timesheet_id
                      and mode_tf.is_current
                      and upper(coalesce(
                        mode_tf.invoice_breakdown_json->>'mode',''))='SEGMENTS'
                  )
                  union
                  select nullif(btrim(coalesce(seg.value->>'ref_num','')),'')
                  from public.timesheets_financials tf
                  cross join lateral jsonb_array_elements(
                    coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) seg(value)
                  where tf.timesheet_id=ts.timesheet_id
                    and tf.is_current
                    and upper(coalesce(tf.invoice_breakdown_json->>'mode',''))='SEGMENTS'
                    and nullif(btrim(coalesce(
                      seg.value->>'invoice_locked_invoice_id','')),'')=o.invoice_id::text
               ) canonical_refs
               where ref_value is not null
             ) calculated
             where ts.is_current
               and ts.timesheet_id=coalesce(
                 n.timesheet_id,
                 case when coalesce(n.meta_json->>'timesheet_id','') ~
                   '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                   then (n.meta_json->>'timesheet_id')::uuid end)
               and (
                 n.timesheet_id is null
                 or not (coalesce(n.meta_json->>'timesheet_id','') ~
                   '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')
                 or (n.meta_json->>'timesheet_id')::uuid=n.timesheet_id)
               and (coalesce(n.meta_json,'{}'::jsonb)
                     -'ts_reference_number'-'schedule_ref_nums'-'schedule_ref_count')
                   is not distinct from
                   (coalesce(o.meta_json,'{}'::jsonb)
                     -'ts_reference_number'-'schedule_ref_nums'-'schedule_ref_count')
               and n.meta_json->'ts_reference_number' is not distinct from
                 coalesce(to_jsonb(nullif(btrim(coalesce(ts.reference_number,'')),'')),'null'::jsonb)
               and n.meta_json->'schedule_ref_nums' is not distinct from calculated.refs
               and n.meta_json->'schedule_ref_count' is not distinct from
                 to_jsonb(jsonb_array_length(calculated.refs))
           )
         )
    ) s;
  elsif tg_table_name='invoice_hr_source_rows' and tg_op='INSERT' then
    select coalesce(array_agg(distinct invoice_id),array[]::uuid[]) into v_invoice_ids from new_rows;
  elsif tg_table_name='invoice_hr_source_rows' and tg_op='DELETE' then
    select coalesce(array_agg(distinct invoice_id),array[]::uuid[]) into v_invoice_ids from old_rows;
  elsif tg_table_name='invoice_hr_source_rows' and tg_op='UPDATE' then
    select coalesce(array_agg(distinct coalesce(n.invoice_id,o.invoice_id)),array[]::uuid[])
      into v_invoice_ids
    from new_rows n full join old_rows o
      on n.invoice_id=o.invoice_id
     and n.source_system=o.source_system
     and n.import_id is not distinct from o.import_id
    where n.invoice_id is null or o.invoice_id is null
       or n.header_rows is distinct from o.header_rows
       or n.header_columns is distinct from o.header_columns
       or n.rows_json is distinct from o.rows_json;
  end if;

  if cardinality(v_invoice_ids)=0 then return null; end if;

  select coalesce(array_agg(i.id),array[]::uuid[]) into v_invoice_ids
  from public.invoices i
  where i.id=any(v_invoice_ids)
    and i.status in('DRAFT','ON_HOLD')
    and i.issued_at_utc is null
    and i.paid_at_utc is null;
  if cardinality(v_invoice_ids)=0 then return null; end if;

  update public.invoices i set document_revision=i.document_revision+1,
    document_state='STALE',preview_document_version_id=null,active_document_operation_id=null,
    invoice_pdf_r2_key=null,invoice_pdf_generated_at_utc=null,
    issue_state=case when i.issue_state in ('VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
      then 'SUPERSEDED' else i.issue_state end,last_document_error_json=null
  where i.id=any(v_invoice_ids)
    and i.status in('DRAFT','ON_HOLD')
    and i.issued_at_utc is null
    and i.paid_at_utc is null;

  with changed as materialized (
    update public.invoice_document_versions v
    set status='SUPERSEDED',superseded_at_utc=now(),
      error_json=jsonb_build_object(
        'code','INVOICE_SOURCE_CHANGED','invoice_id',v.entity_id)
    where v.entity_type='INVOICE' and v.entity_id=any(v_invoice_ids)
      and v.purpose in('DRAFT_PREVIEW','FINAL_ISSUE')
      and v.status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING')
    returning v.id,v.operation_id
  )
  select coalesce(array_agg(id),array[]::uuid[]),
    coalesce(array_agg(distinct operation_id),array[]::uuid[])
  into v_version_ids,v_document_operation_ids from changed;

  with changed as materialized (
    update public.invoice_operation_chunks c
    set status='SUPERSEDED',phase='SUPERSEDED',
      replacement_required=false,replaced_by_chunk_id=null,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      completed_at_utc=now(),updated_at_utc=now(),
      error_json=jsonb_build_object(
        'code','INVOICE_SOURCE_CHANGED','invoice_id',c.entity_id)
    where c.chunk_type='ISSUE_INVOICE' and c.entity_type='INVOICE'
      and c.entity_id=any(v_invoice_ids)
      and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    returning c.operation_id
  )
  select coalesce(array_agg(distinct operation_id),array[]::uuid[])
  into v_issue_operation_ids from changed;

  with changed as materialized (
    update public.invoice_operation_chunks c
    set status='SUPERSEDED',phase='SUPERSEDED',
      replacement_required=false,replaced_by_chunk_id=null,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      completed_at_utc=now(),updated_at_utc=now(),
      error_json=jsonb_build_object(
        'code','INVOICE_SOURCE_CHANGED','invoice_id',c.entity_id)
    where c.chunk_type='DELIVERY_PREPARE' and c.entity_type='INVOICE'
      and c.entity_id=any(v_invoice_ids)
      and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    returning c.operation_id
  )
  select coalesce(array_agg(distinct operation_id),array[]::uuid[])
  into v_delivery_operation_ids from changed;

  update public.invoice_operation_chunks c
  set status='SUPERSEDED',phase='SUPERSEDED',
    replacement_required=false,replaced_by_chunk_id=null,
    lease_owner=null,lease_token=null,lease_expires_at_utc=null,
    completed_at_utc=now(),updated_at_utc=now(),
    error_json=jsonb_build_object(
      'code','INVOICE_SOURCE_CHANGED','document_version_id',c.document_version_id)
  where c.document_version_id=any(v_version_ids)
    and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED');

  update public.invoice_operations o
  set control_version=o.control_version+1,updated_at_utc=now(),
    change_seq=nextval('public.invoice_operation_change_seq')
  where o.id=any(v_document_operation_ids)
    and o.operation_type='BUILD_DOCUMENT'
    and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED');

  v_operation_ids:=array(
    select distinct x
    from unnest(coalesce(v_document_operation_ids,array[]::uuid[])
      ||coalesce(v_issue_operation_ids,array[]::uuid[])
      ||coalesce(v_delivery_operation_ids,array[]::uuid[])) x
    where x is not null);

  update public.invoices i
  set active_issue_operation_id=null
  where i.id=any(v_invoice_ids)
    and i.active_issue_operation_id=any(v_operation_ids);

  -- A statement trigger must remain bounded to the directly affected rows.  It
  -- marks their roots dirty; the normal worker/reconciliation path performs
  -- descendant aggregation outside the write-trigger call stack.
  update public.invoice_operations o
  set progress_json=jsonb_set(coalesce(o.progress_json,'{}'::jsonb),
        '{rollup_required}','true'::jsonb,true),
    updated_at_utc=now(),
    change_seq=nextval('public.invoice_operation_change_seq')
  where o.id=any(v_operation_ids)
    and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED');
  return null;
end;
$function$;

revoke all on function public.trg_invoice_document_invalidate() from public,anon,authenticated;

CREATE OR REPLACE FUNCTION public.invoice_apply_edits(p_invoice_id uuid, p_payload jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();
  v_anchor_ymd date := (now() at time zone 'Europe/London')::date;


-- =====================================================
-- DEBUG (invoice_debug): single audit row per RPC call
-- =====================================================
v_invoice_debug boolean := false;
v_dbg_started_at timestamptz := now();
v_dbg_steps jsonb := '[]'::jsonb;
v_dbg_sqlstate text := null;
v_dbg_error text := null;
v_dbg_stats jsonb := '{}'::jsonb;


v_dbg_lines_deleted int := 0;
v_dbg_timesheets_unlocked int := 0;
v_dbg_seg_add_refs int := 0;
v_dbg_seg_remove_refs int := 0;
v_dbg_seg_tsfins int := 0;
v_dbg_seg_timesheets_rebuilt int := 0;
v_dbg_seg_timesheets_removed int := 0;
v_dbg_add_timesheets_found int := 0;
v_dbg_add_timesheets_skipped int := 0;

v_rc int := 0;

  v_inv record;
  v_week_start date;
  v_week_end date;

  v_remove_ids uuid[];
  v_add_ts_ids uuid[];

-- segment move payload (explicit segment add/remove)
v_remove_seg_refs jsonb;
v_add_seg_refs jsonb;
v_has_seg_ops boolean := false;
v_refresh_hr_cache boolean := false;
v_seg_tsfin_ids uuid[] := array[]::uuid[];
v_seg_ts_ids uuid[] := array[]::uuid[];
v_seg_refs_to_lock jsonb := '[]'::jsonb;
v_ref jsonb;
v_tsfin_id uuid;
v_seg_id text;
v_has_additional boolean;
v_has_expense_or_mileage boolean;

  -- reference updates (refs-to-issue)
  v_reference_updates jsonb;
  v_refupd jsonb;
  v_refupd_ts_id uuid;
  v_refupd_count int := 0;
  v_refupd_applied int := 0;
  v_refupd_set_refnum boolean;
  v_refupd_set_dayrefs boolean;
  v_refupd_set_sched boolean;
  v_refupd_dayrefs jsonb;
  v_refupd_sched jsonb;
  v_refupd_refnum text;

  -- timesheet hospital / ward source edits
  v_location_updates jsonb;
  v_location_update jsonb;
  v_location_ts_id uuid;
  v_location_count int := 0;
  v_location_applied int := 0;
  v_location_set_hospital boolean;
  v_location_set_ward boolean;
  v_location_hospital_norm text;
  v_location_ward_norm text;
  v_location_ts_ids uuid[] := array[]::uuid[];
  -- Source-edit contract state. Reference and location inputs are merged into
  -- one desired row per timesheet, then written by one statement so the
  -- statement-level invalidation trigger advances each source exactly once.
  v_source_updates_map jsonb := '{}'::jsonb;
  v_source_update jsonb;
  v_source_edit_key text;
  v_source_expected_revision bigint;
  v_source_changed_ts_ids uuid[] := array[]::uuid[];
  v_source_changed_revisions jsonb := '[]'::jsonb;
  v_source_edit_requested boolean := false;
  v_allowed_reference_fields text[]:=array[
    'timesheet_id','expected_document_revision','reference_number',
    'day_references_json','actual_schedule_json'];
  v_allowed_location_fields text[]:=array[
    'timesheet_id','expected_document_revision','hospital_norm','ward_norm'];
  v_allowed_reference_segment_fields text[]:=array[
    'segment_id','date','start_utc','end_utc','start','end','ref_num',
    'source_system'];
  v_source_unsupported_field text;
  v_source_financial_id uuid;
  v_source_mode text;
  v_source_ib jsonb;
  v_source_payload_schedule jsonb;
  v_source_canonical_schedule jsonb;
  v_source_new_segments jsonb;
  v_source_segment_updates jsonb;
  v_source_segment_reference_changed boolean;
  v_source_timesheet_row_changed boolean;
  v_source_match_count integer;
  v_source_match_segment jsonb;
  v_source_payload_segment jsonb;
  v_source_current_segment jsonb;
  v_source_payload_ord bigint;
  v_source_start timestamptz;
  v_source_end timestamptz;
  v_source_marker_rows jsonb:='{}'::jsonb;
  v_source_marker jsonb:='{}'::jsonb;
  v_source_edit_preexisting_preview boolean := false;
  v_source_edit_invoice_replacement_required boolean := false;
  v_pre_edit_invoice_revision bigint;
  v_pre_edit_preview_document_version_id uuid;
  v_pre_edit_active_document_operation_id uuid;
  v_expected_command_count int := 0;
  v_operation_result jsonb;
  v_operation_id uuid;
  v_document_version_id uuid;
  v_command_no int;
  v_command_type text;
  v_operation_status text;
  v_operation_input jsonb;
  v_validated_operations jsonb := '[]'::jsonb;
  v_document_commands jsonb := '[]'::jsonb;
  v_started_operations jsonb := '[]'::jsonb;

  -- reference update side-effects (meta refresh / segment ref sync)
  v_refupd_ts_ids uuid[] := array[]::uuid[];
  v_refupd_ts_ids_distinct uuid[] := array[]::uuid[];
  v_refupd_meta_rows_updated int := 0;
  v_refupd_tsfin_rows_updated int := 0;
  v_refupd_tsfin_segments_updated int := 0;
  v_refupd_invoice_fallback_invalidated boolean := false;

  -- temp vars for reference-derived meta and optional tsfin segment ref sync
  v_ref_ts_id uuid;
  v_ref_ts record;
  v_ref_schedule_refs jsonb := '[]'::jsonb;
  v_ref_schedule_refs_distinct jsonb := '[]'::jsonb;
  v_ref_sched_map jsonb := '{}'::jsonb;
  v_ref_seen_keys jsonb := '{}'::jsonb;
  v_ref_sched_key text;
  v_ref_sched_ref text;
  v_ref_tsfin_id uuid;
  v_ref_ib jsonb;
  v_ref_new_segments jsonb := '[]'::jsonb;
  v_ref_seg_obj jsonb;
  v_ref_seg_start text;
  v_ref_seg_end text;
    v_ref_seg_id text;
v_ref_seg_cur_ref text;
  v_ref_seg_new_ref text;
  v_ref_seg_has_update boolean := false;
  v_ref_seg_updates_this_ts int := 0;
  v_ref_seg_matches_this_ts int := 0;

  -- audit (history) accumulators (NOT debug-only)
  v_hist_adj jsonb := '[]'::jsonb;
  v_hist_seg_add jsonb := '[]'::jsonb;
  v_hist_seg_remove jsonb := '[]'::jsonb;
  v_hist_lines_removed jsonb := '[]'::jsonb;
  v_hist_add_ts jsonb := '[]'::jsonb;

  -- contract week status touch set
  v_cw_ts_ids uuid[] := array[]::uuid[];

  v_ts_ids_touched uuid[] := array[]::uuid[];
  -- FIX: timesheets fully removed from this invoice (no remaining invoice_lines) should be unlocked
  v_ts_ids_fully_removed uuid[] := array[]::uuid[];

  v_vat_chargeable boolean := true;
  v_vat_rate numeric := 0;

  -- adjustments
  adj jsonb;
  v_adj_token text;
  v_adj_desc text;
  v_adj_ex numeric;
  v_adj_vat numeric;
  v_adj_inc numeric;
  v_adj_source_key text;
  v_meta jsonb;

  -- timesheet loop
  tsid uuid;
  snap record;
  ts record;
  pc record;
  contract_id uuid;
  v_settings_authority jsonb;
  c_daily_calc boolean := false;
  c_bucket_labels jsonb := null;
  c_role text := null;
  c_display_site text := null;
  c_ward_hint text := null;

  -- segment filtering
  v_seg jsonb;
  segments jsonb := '[]'::jsonb;
  seg_target date;
  seg_date text;
  natural_start date;
  seg_locked text;
  seg_ref text;

  -- aggregation for weekly line
  h_day numeric; h_night numeric; h_sat numeric; h_sun numeric; h_bh numeric;
  pay_ex numeric; chg_ex numeric; margin_ex numeric;
  vat_amt numeric; inc_amt numeric;
  line_desc text;
  v_source_key text;
  v_exact_timesheet_document_r2_key text;

  -- daily aggregation record
  r_day record;

  -- segment refs for locking
  seg_refs jsonb := '[]'::jsonb;

  -- additional units
  kv record;
  ex jsonb;
  code text;
  unit_count numeric;
  bucket_name text;
  unit_name text;

  -- expenses notes
  v_note_travel text;
  v_note_accom text;
  v_note_other text;

  -- recompute totals
  v_new_ex numeric := 0;
  v_new_vat numeric := 0;
  v_new_inc numeric := 0;

  -- header meta counters (keep header_snapshot_json.meta in sync with current invoice state)
  v_hdr_ts_count_lines int := 0;
  v_hdr_ts_count_seglocks int := 0;
  v_hdr_seg_locked_count int := 0;
  v_hdr_meta_timesheet_count int := 0;
  v_hdr_meta_segment_count int := 0;

  v_manifest jsonb;
  v_correction_placement_only boolean:=false;
  v_correction_placement_ts_id uuid:=null;
  v_correction_placement_scope jsonb:='{}'::jsonb;
  v_correction_placement_states jsonb:='[]'::jsonb;
  v_service boolean:=coalesce(auth.role(),'')='service_role';
  v_actor_role text;
begin

  if not v_service
     and(auth.uid() is null or auth.uid() is distinct from p_actor_user_id) then
    raise exception using errcode='42501',
      message='AUTHENTICATED_ACTOR_MISMATCH';
  end if;
  select lower(btrim(coalesce(u.role,''))) into v_actor_role
  from public.tms_users u
  where u.id=p_actor_user_id and u.is_active;
  if(not found or v_actor_role<>'admin') and not v_service then
    raise exception using errcode='42501',
      message='INVOICE_ADMINISTRATOR_PERMISSION_REQUIRED';
  end if;

  perform public._ctms_assert_invoice_mutable_draft_v1(
    p_invoice_id,'INVOICE_APPLY_EDITS',true
  );
  v_correction_placement_only:=
    jsonb_typeof(coalesce(p_payload,'{}'::jsonb))='object'
    and not exists(select 1 from jsonb_object_keys(coalesce(p_payload,'{}'::jsonb)) payload_key
      where payload_key not in ('remove_invoice_line_ids','add_timesheet_ids'))
    and coalesce(jsonb_array_length(case when jsonb_typeof(p_payload->'remove_invoice_line_ids')='array'
      then p_payload->'remove_invoice_line_ids' else '[]'::jsonb end),0)
      +coalesce(jsonb_array_length(case when jsonb_typeof(p_payload->'add_timesheet_ids')='array'
      then p_payload->'add_timesheet_ids' else '[]'::jsonb end),0)=1
    and (
      (case when coalesce(p_payload#>>'{remove_invoice_line_ids,0}','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then exists(
          select 1 from public.invoice_lines placement_line
          where placement_line.id=(p_payload#>>'{remove_invoice_line_ids,0}')::uuid
            and placement_line.invoice_id=p_invoice_id
            and coalesce((public._ctms_import_correction_classify_v1(placement_line.timesheet_id)
              ->>'is_import_authoritative_correction')::boolean,false)) else false end)
      or
      (case when coalesce(p_payload#>>'{add_timesheet_ids,0}','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        coalesce((public._ctms_import_correction_classify_v1(
          (p_payload#>>'{add_timesheet_ids,0}')::uuid)->>'is_import_authoritative_correction')::boolean,false)
        else false end)
    );
  if public._ctms_invoice_payload_has_financial_edit_v1(p_payload)
     and not v_correction_placement_only
     and exists (
       select 1 from public.invoice_lines il
       where il.invoice_id=p_invoice_id and il.timesheet_id is not null
         and coalesce((public._ctms_import_correction_classify_v1(il.timesheet_id)
           ->>'is_import_authoritative_correction')::boolean,false)
     ) then
    raise exception 'IMPORT_CORRECTION_INVOICE_FINANCIAL_EDIT_FORBIDDEN'
      using errcode='P0001',detail=jsonb_build_object('invoice_id',p_invoice_id)::text;
  end if;
-- Load invoice_debug flag (safe even if column not yet present)
begin
  select coalesce(sd.invoice_debug, false)
  into v_invoice_debug
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;
exception when undefined_column then
  v_invoice_debug := false;
end;

if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','start',
      'at_utc', public._inv_iso_utc(v_dbg_started_at),
      'invoice_id', p_invoice_id::text
    )
  );
end if;

  if p_invoice_id is null then
    raise exception 'invoice_id is required';
  end if;

  select *
  into v_inv
  from public.invoices i
  where i.id = p_invoice_id
  for update
  limit 1;

  if not found then
    raise exception 'Invoice not found';
  end if;

  -- Editable gate: DRAFT/ON_HOLD and unpaid
  if v_inv.status::text not in ('DRAFT','ON_HOLD') then
    raise exception 'Invoice is not editable (status=%)', v_inv.status::text;
  end if;

  if v_inv.paid_at_utc is not null then
    raise exception 'Invoice is not editable (already paid)';
  end if;



if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','invoice_loaded',
      'status', coalesce(v_inv.status::text,''),
      'paid_at_utc', case when v_inv.paid_at_utc is null then null else public._inv_iso_utc(v_inv.paid_at_utc) end
    )
  );
end if;

  -- Require invoice_week_start in header_snapshot_json.meta
  if v_inv.header_snapshot_json is null
     or btrim(coalesce(v_inv.header_snapshot_json #>> '{meta,invoice_week_start}','')) = ''
     or (v_inv.header_snapshot_json #>> '{meta,invoice_week_start}') !~ '^\d{4}-\d{2}-\d{2}$'
  then
    raise exception 'Invoice header_snapshot_json.meta.invoice_week_start is required for edits';
  end if;

  v_week_start := (v_inv.header_snapshot_json #>> '{meta,invoice_week_start}')::date;
  v_week_end := (v_week_start + interval '6 days')::date;


if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','invoice_week_loaded',
      'invoice_week_start', v_week_start::text,
      'invoice_week_end', v_week_end::text
    )
  );
end if;

  -- VAT settings from invoice snapshot
  if jsonb_typeof(v_inv.header_snapshot_json->'vat_chargeable') = 'boolean' then
    v_vat_chargeable := (v_inv.header_snapshot_json->>'vat_chargeable')::boolean;
  else
    v_vat_chargeable := true;
  end if;

  if (v_inv.header_snapshot_json ? 'applied_vat_rate_pct') then
    begin
      v_vat_rate := (v_inv.header_snapshot_json->>'applied_vat_rate_pct')::numeric;
    exception when others then
      v_vat_rate := 0;
    end;
  else
    v_vat_rate := 0;
  end if;

  if v_vat_chargeable = false then
    v_vat_rate := 0;
  end if;

  -- Parse payload arrays
  v_remove_ids := null;
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'remove_invoice_line_ids') then
    select array_agg((x)::uuid)
    into v_remove_ids
    from jsonb_array_elements_text(coalesce(p_payload->'remove_invoice_line_ids','[]'::jsonb)) x
    where nullif(btrim(coalesce(x,'')),'') is not null;
  end if;

  v_add_ts_ids := null;
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_timesheet_ids') then
    select array_agg((x)::uuid)
    into v_add_ts_ids
    from jsonb_array_elements_text(coalesce(p_payload->'add_timesheet_ids','[]'::jsonb)) x
    where nullif(btrim(coalesce(x,'')),'') is not null;
  end if;

  IF v_correction_placement_only THEN
    IF COALESCE(cardinality(v_remove_ids),0)=1 THEN
      SELECT il.timesheet_id INTO v_correction_placement_ts_id
      FROM public.invoice_lines il
      WHERE il.id=v_remove_ids[1] AND il.invoice_id=p_invoice_id
      FOR UPDATE;
      IF v_correction_placement_ts_id IS NULL
         OR COALESCE((public._ctms_import_correction_classify_v1(v_correction_placement_ts_id)
             ->>'is_import_authoritative_correction')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_TARGET_INVALID' USING ERRCODE='P0001';
      END IF;
      v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
        v_correction_placement_ts_id,null::uuid,p_actor_user_id,true,100);
      IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
         OR v_correction_placement_scope->>'placement_state' NOT IN (
           'COMPLETE_SAME_INVOICE','COMPLETE_SPLIT_INVOICES') THEN
        RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_MOVE_NOT_STARTABLE'
          USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
      END IF;
    ELSIF COALESCE(cardinality(v_add_ts_ids),0)=1 THEN
      v_correction_placement_ts_id:=v_add_ts_ids[1];
      IF COALESCE((public._ctms_import_correction_classify_v1(v_correction_placement_ts_id)
             ->>'is_import_authoritative_correction')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_TARGET_INVALID' USING ERRCODE='P0001';
      END IF;
      v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
        v_correction_placement_ts_id,p_invoice_id,p_actor_user_id,true,100);
      IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
         OR v_correction_placement_scope->>'placement_state'<>'INCOMPLETE_MOVE'
         OR v_correction_placement_scope->>'missing_member_kind' IS DISTINCT FROM
              (SELECT t.correction_kind FROM public.timesheets t
               WHERE t.timesheet_id=v_correction_placement_ts_id)
         OR COALESCE((v_correction_placement_scope->>'target_appendable')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_TARGET_INVALID'
          USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
      END IF;
    ELSE
      RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_PAYLOAD_INVALID' USING ERRCODE='22023';
    END IF;
  END IF;


-- Parse segment move payloads (tsfin_id + segment_id)
v_remove_seg_refs := null;
if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'remove_segment_refs') then
  v_remove_seg_refs := coalesce(p_payload->'remove_segment_refs','[]'::jsonb);
  if jsonb_typeof(v_remove_seg_refs) <> 'array' then
    v_remove_seg_refs := '[]'::jsonb;
  end if;
end if;

v_add_seg_refs := null;
if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_segment_refs') then
  v_add_seg_refs := coalesce(p_payload->'add_segment_refs','[]'::jsonb);
  if jsonb_typeof(v_add_seg_refs) <> 'array' then
    v_add_seg_refs := '[]'::jsonb;
  end if;
end if;



-- Parse and strictly validate source edits. The expected source revision is
-- mandatory because values displayed by an older modal must never overwrite a
-- newer timesheet revision.
v_reference_updates := null;
if p_payload is not null and jsonb_typeof(p_payload)='object'
   and p_payload ? 'reference_updates' then
  v_reference_updates:=p_payload->'reference_updates';
  if jsonb_typeof(v_reference_updates)<>'array' then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
      detail=jsonb_build_object('field','reference_updates','reason','ARRAY_REQUIRED')::text;
  end if;
  v_refupd_count:=jsonb_array_length(v_reference_updates);
  for v_refupd in select value from jsonb_array_elements(v_reference_updates) value loop
    if v_refupd is not null and jsonb_typeof(v_refupd)='object' then
      select min(field_name) into v_source_unsupported_field
      from jsonb_object_keys(v_refupd) field_name
      where not (field_name=any(v_allowed_reference_fields));
      if v_source_unsupported_field is not null then
        raise exception using errcode='22023',
          message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
          detail=jsonb_build_object(
            'field','reference_updates','reason','UNSUPPORTED_FIELD',
            'unsupported_field',v_source_unsupported_field)::text;
      end if;
    end if;
    if v_refupd is null or jsonb_typeof(v_refupd)<>'object'
       or nullif(btrim(coalesce(v_refupd->>'timesheet_id','')),'') is null
       or coalesce(v_refupd->>'timesheet_id','') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       or coalesce(v_refupd->>'expected_document_revision','') !~ '^[1-9][0-9]*$'
       or not (
         v_refupd ? 'reference_number'
         or v_refupd ? 'day_references_json'
         or v_refupd ? 'actual_schedule_json'
       )
       or (
         v_refupd ? 'reference_number'
         and jsonb_typeof(v_refupd->'reference_number') not in('string','null')
       )
       or (
         v_refupd ? 'day_references_json'
         and jsonb_typeof(v_refupd->'day_references_json') not in('object','null')
       )
       or (
         v_refupd ? 'actual_schedule_json'
         and jsonb_typeof(v_refupd->'actual_schedule_json') not in('array','null')
       )
    then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
        detail=jsonb_build_object('field','reference_updates','reason','INVALID_ITEM')::text;
    end if;
    v_source_edit_key:=lower(v_refupd->>'timesheet_id');
    if v_source_updates_map ? v_source_edit_key then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_DUPLICATE_TIMESHEET',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'field','reference_updates')::text;
    end if;
    v_source_updates_map:=jsonb_set(
      v_source_updates_map,array[v_source_edit_key],
      jsonb_build_object(
        'timesheet_id',v_source_edit_key,
        'expected_document_revision',(v_refupd->>'expected_document_revision')::bigint,
        'has_reference_number',v_refupd ? 'reference_number',
        'reference_number',case when v_refupd ? 'reference_number'
          then to_jsonb(nullif(btrim(coalesce(v_refupd->>'reference_number','')),''))
          else 'null'::jsonb end,
        'has_day_references_json',v_refupd ? 'day_references_json',
        'day_references_json',case
          when not (v_refupd ? 'day_references_json') then 'null'::jsonb
          when jsonb_typeof(v_refupd->'day_references_json')='null' then 'null'::jsonb
          else v_refupd->'day_references_json' end,
        'has_actual_schedule_json',v_refupd ? 'actual_schedule_json',
        'actual_schedule_json',case
          when not (v_refupd ? 'actual_schedule_json') then 'null'::jsonb
          when jsonb_typeof(v_refupd->'actual_schedule_json')='null' then 'null'::jsonb
          else v_refupd->'actual_schedule_json' end,
        'has_hospital_norm',false,
        'has_ward_norm',false),
      true);
  end loop;
end if;

-- Hospital/ward edits merge into the same desired source row. A source may
-- appear once in each array, but both items must carry the same revision.
v_location_updates:=null;
if p_payload is not null and jsonb_typeof(p_payload)='object'
   and p_payload ? 'timesheet_location_updates' then
  v_location_updates:=p_payload->'timesheet_location_updates';
  if jsonb_typeof(v_location_updates)<>'array' then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
      detail=jsonb_build_object('field','timesheet_location_updates','reason','ARRAY_REQUIRED')::text;
  end if;
  v_location_count:=jsonb_array_length(v_location_updates);
  for v_location_update in select value from jsonb_array_elements(v_location_updates) value loop
    if v_location_update is not null and jsonb_typeof(v_location_update)='object' then
      select min(field_name) into v_source_unsupported_field
      from jsonb_object_keys(v_location_update) field_name
      where not (field_name=any(v_allowed_location_fields));
      if v_source_unsupported_field is not null then
        raise exception using errcode='22023',
          message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
          detail=jsonb_build_object(
            'field','timesheet_location_updates','reason','UNSUPPORTED_FIELD',
            'unsupported_field',v_source_unsupported_field)::text;
      end if;
    end if;
    if v_location_update is null or jsonb_typeof(v_location_update)<>'object'
       or nullif(btrim(coalesce(v_location_update->>'timesheet_id','')),'') is null
       or coalesce(v_location_update->>'timesheet_id','') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       or coalesce(v_location_update->>'expected_document_revision','') !~ '^[1-9][0-9]*$'
       or not (v_location_update ? 'hospital_norm' or v_location_update ? 'ward_norm')
       or (
         v_location_update ? 'hospital_norm'
         and jsonb_typeof(v_location_update->'hospital_norm') not in('string','null')
       )
       or (
         v_location_update ? 'ward_norm'
         and jsonb_typeof(v_location_update->'ward_norm') not in('string','null')
       )
    then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
        detail=jsonb_build_object('field','timesheet_location_updates','reason','INVALID_ITEM')::text;
    end if;
    v_source_edit_key:=lower(v_location_update->>'timesheet_id');
    v_source_expected_revision:=(v_location_update->>'expected_document_revision')::bigint;
    if v_source_updates_map ? v_source_edit_key
       and (
         coalesce((v_source_updates_map#>>
           array[v_source_edit_key,'has_hospital_norm'])::boolean,false)
         or coalesce((v_source_updates_map#>>
           array[v_source_edit_key,'has_ward_norm'])::boolean,false)
       ) then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_DUPLICATE_TIMESHEET',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'field','timesheet_location_updates')::text;
    end if;
    if v_source_updates_map ? v_source_edit_key
       and (v_source_updates_map#>>array[v_source_edit_key,'expected_document_revision'])::bigint
           is distinct from v_source_expected_revision then
      raise exception using errcode='40001',
        message='INVOICE_SOURCE_EDIT_STALE_REVISION',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'reason','EXPECTED_REVISION_CONFLICT')::text;
    end if;
    v_source_update:=coalesce(v_source_updates_map->v_source_edit_key,
      jsonb_build_object(
        'timesheet_id',v_source_edit_key,
        'expected_document_revision',v_source_expected_revision,
        'has_reference_number',false,
        'has_day_references_json',false,
        'has_actual_schedule_json',false));
    v_source_update:=v_source_update||jsonb_build_object(
      'has_hospital_norm',v_location_update ? 'hospital_norm',
      'hospital_norm',case when v_location_update ? 'hospital_norm'
        then to_jsonb(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'hospital_norm','')),
          '[[:space:]]+',' ','g')))
        else 'null'::jsonb end,
      'has_ward_norm',v_location_update ? 'ward_norm',
      'ward_norm',case when v_location_update ? 'ward_norm'
        then to_jsonb(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'ward_norm','')),
          '[[:space:]]+',' ','g')))
        else 'null'::jsonb end);
    v_source_updates_map:=jsonb_set(v_source_updates_map,array[v_source_edit_key],v_source_update,true);
  end loop;
end if;
v_source_edit_requested:=v_source_updates_map<>'{}'::jsonb;
v_has_seg_ops :=
  (v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0)
  or (v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0);

  v_refresh_hr_cache := (coalesce(array_length(v_add_ts_ids,1),0) > 0) or coalesce(v_has_seg_ops,false);

  if v_invoice_debug then
    v_dbg_stats := v_dbg_stats || jsonb_build_object(
      'remove_invoice_line_ids_count', coalesce(array_length(v_remove_ids,1),0),
      'add_timesheet_ids_count', coalesce(array_length(v_add_ts_ids,1),0),
      'add_adjustments_count', case when p_payload is not null and jsonb_typeof(p_payload)='object' and (p_payload ? 'add_adjustments') and jsonb_typeof(p_payload->'add_adjustments')='array' then jsonb_array_length(p_payload->'add_adjustments') else 0 end,
      'remove_segment_refs_count', case when v_remove_seg_refs is null then 0 else jsonb_array_length(coalesce(v_remove_seg_refs,'[]'::jsonb)) end,
      'add_segment_refs_count', case when v_add_seg_refs is null then 0 else jsonb_array_length(coalesce(v_add_seg_refs,'[]'::jsonb)) end,
      'timesheet_location_updates_count',v_location_count,
      'has_segment_ops', v_has_seg_ops
    );
    v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','payload_parsed','stats',v_dbg_stats));
  end if;

  if v_source_edit_requested then
    -- Source edits are a narrower authority than ordinary draft edits.
    if v_inv.issued_at_utc is not null then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_ISSUED';
    end if;
    if v_inv.paid_at_utc is not null then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_PAID';
    end if;
    if v_inv.active_issue_operation_id is not null
       or upper(coalesce(v_inv.issue_state,'')) in
          ('VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
       or exists(
         select 1
         from public.invoice_operation_chunks c
         where c.chunk_type='ISSUE_INVOICE'
           and c.entity_type='INVOICE'
           and c.entity_id=p_invoice_id
           and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
       )
    then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_ISSUE_IN_PROGRESS';
    end if;

    v_pre_edit_invoice_revision:=v_inv.document_revision;
    v_pre_edit_preview_document_version_id:=v_inv.preview_document_version_id;
    v_pre_edit_active_document_operation_id:=v_inv.active_document_operation_id;

    -- Only an exact current-revision V8 preview is authoritative. Legacy PDF
    -- summary fields do not independently force or suppress replacement.
    select exists(
      select 1
      from public.invoice_document_versions dv
      left join public.invoice_operations op on op.id=dv.operation_id
      where dv.entity_type='INVOICE'
        and dv.entity_id=p_invoice_id
        and dv.purpose='DRAFT_PREVIEW'
        and dv.source_revision=v_pre_edit_invoice_revision::text
        and (
          (dv.status='READY'
            and nullif(btrim(coalesce(dv.r2_key,'')),'') is not null
            and nullif(btrim(coalesce(dv.sha256,'')),'') is not null
            and coalesce(dv.size_bytes,0)>0
            and coalesce(dv.page_count,0)>0)
          or (
            dv.id=v_pre_edit_preview_document_version_id
            and dv.status in(
              'PLANNING','WAITING_FOR_INPUTS','RENDERING',
              'ASSEMBLING','VERIFYING','READY'))
          or (
            dv.operation_id=v_pre_edit_active_document_operation_id
            and op.operation_type='BUILD_DOCUMENT'
            and op.entity_type='INVOICE'
            and op.entity_id=p_invoice_id
            and op.source_revision=v_pre_edit_invoice_revision::text
            and coalesce(op.input_json->>'purpose','')='DRAFT_PREVIEW'
            and op.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
        )
    ) into v_source_edit_preexisting_preview;

    -- Clear any caller-controlled or earlier transaction-local value before
    -- establishing this function's exact-once invalidation marker.
    perform set_config('cloudtms.invoice_source_edit_marker','{}',true);

    -- Lock every target and its current financial snapshot in deterministic
    -- order before validating ownership, revisions or segment identities.
    for v_ref_ts in
      select t.*
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired on true
      where t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      order by t.timesheet_id
      for update of t
    loop
      null;
    end loop;
    for v_ref_ts in
      select tf.id
      from public.timesheets_financials tf
      join jsonb_each(v_source_updates_map) desired
        on tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where tf.is_current
      order by tf.timesheet_id,tf.id
      for update of tf
    loop
      null;
    end loop;

    if (
      select count(*)
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where t.is_current
    )<>(select count(*) from jsonb_each(v_source_updates_map)) then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_SOURCE_NOT_CURRENT';
    end if;

    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      join public.timesheets t
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where t.document_revision is distinct from
        (desired.value->>'expected_document_revision')::bigint
    ) then
      raise exception using errcode='40001',
        message='INVOICE_SOURCE_EDIT_STALE_REVISION';
    end if;

    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where not exists(
        select 1
        from public.invoice_lines owned_line
        where owned_line.invoice_id=p_invoice_id
          and (
            owned_line.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              owned_line.timesheet_id is null
              and coalesce(owned_line.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (owned_line.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
    ) then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_SOURCE_NOT_OWNED';
    end if;

    -- Preserve the established import-authoritative correction lock across
    -- both supported source carriers.
    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where coalesce((
        public._ctms_import_correction_classify_v1(
          (desired.value->>'timesheet_id')::uuid)
          ->>'is_import_authoritative_correction')::boolean,false)
    ) then
      raise exception using errcode='55000',
        message='IMPORT_AUTHORITATIVE_CORRECTION_SOURCE_EDIT_FORBIDDEN';
    end if;

    -- Reject a mixed command that edits a source while removing every carrier
    -- for that source in the same Save.
    if coalesce(array_length(v_remove_ids,1),0)>0 and exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where exists(
        select 1
        from public.invoice_lines carrier
        where carrier.invoice_id=p_invoice_id
          and (
            carrier.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              carrier.timesheet_id is null
              and coalesce(carrier.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (carrier.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
      and not exists(
        select 1
        from public.invoice_lines retained
        where retained.invoice_id=p_invoice_id
          and not (retained.id=any(v_remove_ids))
          and (
            retained.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              retained.timesheet_id is null
              and coalesce(retained.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (retained.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
    ) then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND';
    end if;

    -- Classify each source from the locked current financial snapshot. A
    -- SEGMENTS payload is an editable reference projection only: it can never
    -- replace timesheets.actual_schedule_json or any financial segment object.
    for v_ref_ts in
      select t.*,desired.value desired_value,
        tf.id financial_id,tf.invoice_breakdown_json financial_breakdown
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      left join lateral(
        select f.id,f.invoice_breakdown_json
        from public.timesheets_financials f
        where f.timesheet_id=t.timesheet_id and f.is_current
        order by f.updated_at desc nulls last,f.created_at desc nulls last,f.id desc
        limit 1
      ) tf on true
      where t.is_current
      order by t.timesheet_id
    loop
      v_source_update:=v_ref_ts.desired_value;
      v_source_financial_id:=v_ref_ts.financial_id;
      v_source_ib:=v_ref_ts.financial_breakdown;
      v_source_mode:=upper(coalesce(v_source_ib->>'mode',''));
      v_source_payload_schedule:=v_source_update->'actual_schedule_json';
      v_source_canonical_schedule:=v_ref_ts.actual_schedule_json;
      v_source_new_segments:=null;
      v_source_segment_updates:='[]'::jsonb;
      v_source_segment_reference_changed:=false;

      if (v_source_update->>'has_actual_schedule_json')::boolean then
        if jsonb_typeof(v_source_payload_schedule)<>'array' then
          raise exception using errcode='22023',
            message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
            detail=jsonb_build_object(
              'field','actual_schedule_json','reason','ARRAY_REQUIRED',
              'timesheet_id',v_ref_ts.timesheet_id)::text;
        end if;

        if v_source_mode='SEGMENTS' then
          if v_source_financial_id is null
             or jsonb_typeof(v_source_ib->'segments')<>'array' then
            raise exception using errcode='55000',
              message='INVOICE_SOURCE_EDIT_SOURCE_NOT_CURRENT';
          end if;

          v_ref_seen_keys:='{}'::jsonb;
          for v_source_payload_segment,v_source_payload_ord in
            select value,ord
            from jsonb_array_elements(v_source_payload_schedule)
              with ordinality payload(value,ord)
          loop
            if jsonb_typeof(v_source_payload_segment)<>'object' then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','INVALID_SEGMENT',
                  'ordinal',v_source_payload_ord)::text;
            end if;
            select min(field_name) into v_source_unsupported_field
            from jsonb_object_keys(v_source_payload_segment) field_name
            where not (field_name=any(v_allowed_reference_segment_fields));
            if v_source_unsupported_field is not null then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','UNSUPPORTED_FIELD',
                  'unsupported_field',v_source_unsupported_field,
                  'ordinal',v_source_payload_ord)::text;
            end if;
            if not (v_source_payload_segment ? 'ref_num') then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','REFERENCE_REQUIRED',
                  'ordinal',v_source_payload_ord)::text;
            end if;

            v_ref_seg_id:=nullif(btrim(coalesce(
              v_source_payload_segment->>'segment_id','')),'');
            v_source_match_count:=0;
            v_source_match_segment:=null;
            if v_ref_seg_id is not null then
              select count(*),min(seg.value::text)::jsonb
              into v_source_match_count,v_source_match_segment
              from jsonb_array_elements(v_source_ib->'segments') seg(value)
              where nullif(btrim(coalesce(seg.value->>'segment_id','')),'')=v_ref_seg_id
                and nullif(btrim(coalesce(
                  seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text;
            end if;

            if v_source_match_count=0 then
              begin
                v_source_start:=nullif(btrim(coalesce(
                  v_source_payload_segment->>'start_utc',
                  v_source_payload_segment->>'start','')),'')::timestamptz;
                v_source_end:=nullif(btrim(coalesce(
                  v_source_payload_segment->>'end_utc',
                  v_source_payload_segment->>'end','')),'')::timestamptz;
              exception when others then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                  detail=jsonb_build_object(
                    'field','actual_schedule_json','reason','INVALID_SEGMENT_TIME',
                    'ordinal',v_source_payload_ord)::text;
              end;
              if v_source_start is null or v_source_end is null then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                  detail=jsonb_build_object(
                    'field','actual_schedule_json','reason','SEGMENT_IDENTITY_REQUIRED',
                    'ordinal',v_source_payload_ord)::text;
              end if;
              select count(*),min(seg.value::text)::jsonb
              into v_source_match_count,v_source_match_segment
              from jsonb_array_elements(v_source_ib->'segments') seg(value)
              where nullif(btrim(coalesce(
                    seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
                and nullif(btrim(coalesce(
                    seg.value->>'start_utc',seg.value->>'start','')),'')::timestamptz
                    =v_source_start
                and nullif(btrim(coalesce(
                    seg.value->>'end_utc',seg.value->>'end','')),'')::timestamptz
                    =v_source_end;
            end if;

            if v_source_match_count<>1 or v_source_match_segment is null then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts.timesheet_id,
                  'ordinal',v_source_payload_ord,
                  'match_count',v_source_match_count)::text;
            end if;

            v_ref_sched_key:=coalesce(
              'SID:'||nullif(btrim(coalesce(
                v_source_match_segment->>'segment_id','')),''),
              'SE:'||coalesce(v_source_match_segment->>'start_utc',
                v_source_match_segment->>'start','')||'|'||
                coalesce(v_source_match_segment->>'end_utc',
                  v_source_match_segment->>'end',''));
            if v_ref_seen_keys ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts.timesheet_id,
                  'reason','DUPLICATE_IDENTITY')::text;
            end if;
            v_ref_seen_keys:=jsonb_set(
              v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
            v_ref_seg_new_ref:=nullif(btrim(coalesce(
              v_source_payload_segment->>'ref_num','')),'');
            v_source_segment_reference_changed:=
              v_source_segment_reference_changed or (
                nullif(btrim(coalesce(
                  v_source_match_segment->>'ref_num','')),'')
                is distinct from v_ref_seg_new_ref);
            v_source_segment_updates:=v_source_segment_updates||
              jsonb_build_array(jsonb_build_object(
                'segment_id',nullif(btrim(coalesce(
                  v_source_match_segment->>'segment_id','')),''),
                'start_identity',coalesce(v_source_match_segment->>'start_utc',
                  v_source_match_segment->>'start'),
                'end_identity',coalesce(v_source_match_segment->>'end_utc',
                  v_source_match_segment->>'end'),
                'ref_num',v_ref_seg_new_ref));
          end loop;

          v_source_new_segments:='[]'::jsonb;
          for v_source_current_segment in
            select value
            from jsonb_array_elements(v_source_ib->'segments')
              with ordinality current_segment(value,ord)
            order by ord
          loop
            v_source_payload_segment:=null;
            select update_item.value into v_source_payload_segment
            from jsonb_array_elements(v_source_segment_updates) update_item(value)
            where (
              nullif(update_item.value->>'segment_id','') is not null
              and nullif(btrim(coalesce(
                v_source_current_segment->>'segment_id','')),'')
                  =nullif(update_item.value->>'segment_id','')
            ) or (
              nullif(update_item.value->>'segment_id','') is null
              and coalesce(v_source_current_segment->>'start_utc',
                    v_source_current_segment->>'start')
                  is not distinct from update_item.value->>'start_identity'
              and coalesce(v_source_current_segment->>'end_utc',
                    v_source_current_segment->>'end')
                  is not distinct from update_item.value->>'end_identity'
            )
            limit 1;
            if v_source_payload_segment is not null then
              v_source_current_segment:=jsonb_set(
                v_source_current_segment,'{ref_num}',
                coalesce(v_source_payload_segment->'ref_num','null'::jsonb),true);
            end if;
            v_source_new_segments:=v_source_new_segments||
              jsonb_build_array(v_source_current_segment);
          end loop;
        else
          v_source_canonical_schedule:=coalesce(
            v_ref_ts.actual_schedule_json,'[]'::jsonb);
          if jsonb_typeof(v_source_canonical_schedule)<>'array'
             or jsonb_array_length(v_source_payload_schedule)
                <>jsonb_array_length(v_source_canonical_schedule) then
            raise exception using errcode='22023',
              message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
              detail=jsonb_build_object(
                'field','actual_schedule_json','reason','STRUCTURE_MISMATCH',
                'timesheet_id',v_ref_ts.timesheet_id)::text;
          end if;
          v_ref_new_segments:='[]'::jsonb;
          for v_source_payload_segment,v_source_current_segment,v_source_payload_ord in
            select p.value,c.value,p.ord
            from jsonb_array_elements(v_source_payload_schedule)
              with ordinality p(value,ord)
            join jsonb_array_elements(v_source_canonical_schedule)
              with ordinality c(value,ord) using(ord)
            order by p.ord
          loop
            if jsonb_typeof(v_source_payload_segment)<>'object'
               or jsonb_typeof(v_source_current_segment)<>'object'
               or not (v_source_payload_segment ? 'ref_num')
               or (v_source_payload_segment-'ref_num') is distinct from
                  (v_source_current_segment-'ref_num') then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','STRUCTURE_MISMATCH',
                  'ordinal',v_source_payload_ord)::text;
            end if;
            v_ref_new_segments:=v_ref_new_segments||jsonb_build_array(
              jsonb_set(v_source_current_segment,'{ref_num}',
                coalesce(v_source_payload_segment->'ref_num','null'::jsonb),true));
          end loop;
          v_source_canonical_schedule:=v_ref_new_segments;
        end if;
      end if;

      v_source_timesheet_row_changed:=(
        ((v_source_update->>'has_reference_number')::boolean
          and v_ref_ts.reference_number is distinct from
            nullif(btrim(coalesce(v_source_update->>'reference_number','')),''))
        or ((v_source_update->>'has_day_references_json')::boolean
          and v_ref_ts.day_references_json is distinct from
            case when jsonb_typeof(v_source_update->'day_references_json')='null'
              then null else v_source_update->'day_references_json' end)
        or ((v_source_update->>'has_actual_schedule_json')::boolean
          and v_source_mode<>'SEGMENTS'
          and v_ref_ts.actual_schedule_json is distinct from
            v_source_canonical_schedule)
        or ((v_source_update->>'has_hospital_norm')::boolean
          and lower(regexp_replace(
                btrim(coalesce(v_ref_ts.hospital_norm,'')),
                '[[:space:]]+',' ','g')) is distinct from
            coalesce(v_source_update->>'hospital_norm',''))
        or ((v_source_update->>'has_ward_norm')::boolean
          and lower(regexp_replace(
                btrim(coalesce(v_ref_ts.ward_norm,'')),
                '[[:space:]]+',' ','g')) is distinct from
            coalesce(v_source_update->>'ward_norm',''))
      );
      v_source_update:=v_source_update||jsonb_build_object(
        'source_mode',v_source_mode,
        'financial_id',v_source_financial_id,
        'canonical_actual_schedule_json',v_source_canonical_schedule,
        'new_financial_segments',v_source_new_segments,
        'segment_updates',v_source_segment_updates,
        'segment_reference_changed',v_source_segment_reference_changed,
        'timesheet_row_changed',v_source_timesheet_row_changed);
      v_source_updates_map:=jsonb_set(
        v_source_updates_map,array[v_ref_ts.timesheet_id::text],
        v_source_update,true);
    end loop;

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_source_changed_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_row_changed')::boolean
       or (desired.value->>'segment_reference_changed')::boolean;

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_refupd_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_id')::uuid=any(v_source_changed_ts_ids)
      and (
        (desired.value->>'has_reference_number')::boolean
        or (desired.value->>'has_day_references_json')::boolean
        or (
          (desired.value->>'has_actual_schedule_json')::boolean
          and (
            (desired.value->>'timesheet_row_changed')::boolean
            or (desired.value->>'segment_reference_changed')::boolean
          )
        )
      );

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_location_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_row_changed')::boolean
      and (
        (desired.value->>'has_hospital_norm')::boolean
        or (desired.value->>'has_ward_norm')::boolean
      );

    if exists(
      select 1 from jsonb_each(v_source_updates_map) desired
      where (desired.value->>'timesheet_row_changed')::boolean
    ) then
      with desired as materialized(
        select (value->>'timesheet_id')::uuid as timesheet_id,value
        from jsonb_each(v_source_updates_map)
      )
      update public.timesheets t
      set updated_at=v_now,
          reference_number=case when (d.value->>'has_reference_number')::boolean
            then nullif(btrim(coalesce(d.value->>'reference_number','')),'')
            else t.reference_number end,
          day_references_json=case when (d.value->>'has_day_references_json')::boolean
            then case when jsonb_typeof(d.value->'day_references_json')='null'
              then null else d.value->'day_references_json' end
            else t.day_references_json end,
          actual_schedule_json=case
            when (d.value->>'has_actual_schedule_json')::boolean
              and d.value->>'source_mode'<>'SEGMENTS'
            then d.value->'canonical_actual_schedule_json'
            else t.actual_schedule_json end,
          hospital_norm=case when (d.value->>'has_hospital_norm')::boolean
            then coalesce(d.value->>'hospital_norm','') else t.hospital_norm end,
          ward_norm=case when (d.value->>'has_ward_norm')::boolean
            then coalesce(d.value->>'ward_norm','') else t.ward_norm end
      from desired d
      where t.timesheet_id=d.timesheet_id
        and (d.value->>'timesheet_row_changed')::boolean
        and t.is_current;
    end if;

    v_refupd_applied:=cardinality(v_refupd_ts_ids);
    v_location_applied:=cardinality(v_location_ts_ids);

    -- Marker rows exist only where the timesheet statement has already advanced
    -- the source revision and the following SEGMENTS ref update would otherwise
    -- invalidate the same source a second time.
    select coalesce(jsonb_object_agg(
      t.timesheet_id::text,
      jsonb_build_object('expected_revision',t.document_revision)),
      '{}'::jsonb)
    into v_source_marker_rows
    from jsonb_each(v_source_updates_map) desired
    join public.timesheets t
      on t.timesheet_id=(desired.value->>'timesheet_id')::uuid and t.is_current
    where (desired.value->>'timesheet_row_changed')::boolean
      and (desired.value->>'segment_reference_changed')::boolean
      and t.document_revision=
        (desired.value->>'expected_document_revision')::bigint+1;
    if (select count(*) from jsonb_each(v_source_marker_rows))<>(
      select count(*) from jsonb_each(v_source_updates_map) desired
      where (desired.value->>'timesheet_row_changed')::boolean
        and (desired.value->>'segment_reference_changed')::boolean
    ) then
      raise exception using errcode='55000',
        message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
        detail=jsonb_build_object(
          'reason','SOURCE_REVISION_ADVANCE_NOT_EXACT')::text;
    end if;
    v_source_marker:=jsonb_build_object(
      'txid',txid_current()::text,'rows',v_source_marker_rows);
    perform set_config(
      'cloudtms.invoice_source_edit_marker',v_source_marker::text,true);

    -- The legacy per-array loops below remain structurally compatible for old
    -- payload code, but the strict merged statement above is now the sole
    -- execution path for accepted source edits.
    v_reference_updates:=null;
    v_location_updates:=null;
  end if;





  -- 0) Apply reference updates to timesheets (does NOT recompute TSFIN; it updates the source timesheet refs)
  if v_reference_updates is not null and jsonb_typeof(v_reference_updates)='array' and jsonb_array_length(v_reference_updates) > 0 then
    for v_refupd in
      select value from jsonb_array_elements(v_reference_updates) value
    loop
      if v_refupd is null or jsonb_typeof(v_refupd) <> 'object' then
        continue;
      end if;

      if nullif(btrim(coalesce(v_refupd->>'timesheet_id','')), '') is null then
        continue;
      end if;

      v_refupd_ts_id := (v_refupd->>'timesheet_id')::uuid;

      v_refupd_set_refnum := (v_refupd ? 'reference_number');
      v_refupd_set_dayrefs := (v_refupd ? 'day_references_json');
      v_refupd_set_sched := (v_refupd ? 'actual_schedule_json');

      v_refupd_refnum := null;
      if v_refupd_set_refnum then
        v_refupd_refnum := nullif(btrim(coalesce(v_refupd->>'reference_number','')), '');
      end if;

      v_refupd_dayrefs := null;
      if v_refupd_set_dayrefs then
        v_refupd_dayrefs := v_refupd->'day_references_json';
        if v_refupd_dayrefs is not null and jsonb_typeof(v_refupd_dayrefs) = 'null' then
          v_refupd_dayrefs := null;
        end if;
      end if;

      v_refupd_sched := null;
      if v_refupd_set_sched then
        v_refupd_sched := v_refupd->'actual_schedule_json';
        if v_refupd_sched is not null and jsonb_typeof(v_refupd_sched) = 'null' then
          v_refupd_sched := null;
        end if;
      end if;

      update public.timesheets tsu
      set
        updated_at = v_now,
        reference_number = case when v_refupd_set_refnum then v_refupd_refnum else tsu.reference_number end,
        day_references_json = case when v_refupd_set_dayrefs then v_refupd_dayrefs else tsu.day_references_json end,
        actual_schedule_json = case when v_refupd_set_sched then v_refupd_sched else tsu.actual_schedule_json end
      where tsu.timesheet_id = v_refupd_ts_id
        and tsu.is_current = true
        and exists(
          select 1
          from public.invoice_lines owned_line
          where owned_line.invoice_id=p_invoice_id
            and (
              owned_line.timesheet_id=tsu.timesheet_id
              or (
                owned_line.timesheet_id is null
                and coalesce(owned_line.meta_json->>'timesheet_id','')
                  ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                and (owned_line.meta_json->>'timesheet_id')::uuid=tsu.timesheet_id
              )
            )
        )
        and (
          (v_refupd_set_refnum and tsu.reference_number is distinct from v_refupd_refnum)
          or (v_refupd_set_dayrefs and tsu.day_references_json is distinct from v_refupd_dayrefs)
          or (v_refupd_set_sched and tsu.actual_schedule_json is distinct from v_refupd_sched)
        );

      get diagnostics v_rc = row_count;
      if coalesce(v_rc,0) > 0 then
        v_refupd_applied := v_refupd_applied + 1;
        v_refupd_ts_ids := v_refupd_ts_ids || v_refupd_ts_id;
      end if;

    end loop;

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object('step','reference_updates_applied','count_requested',v_refupd_count,'count_applied',v_refupd_applied)
      );
    end if;
  end if;

  -- 0a) Apply only material hospital/ward changes to current timesheets that
  -- are owned by this invoice. Identical canonical values perform no UPDATE,
  -- so they cannot dirty documents or queue replacement work.
  if v_location_updates is not null
     and jsonb_typeof(v_location_updates)='array'
     and jsonb_array_length(v_location_updates)>0 then
    for v_location_update in
      select value from jsonb_array_elements(v_location_updates) value
    loop
      if v_location_update is null
         or jsonb_typeof(v_location_update)<>'object'
         or nullif(btrim(coalesce(v_location_update->>'timesheet_id','')),'') is null then
        continue;
      end if;

      v_location_ts_id := (v_location_update->>'timesheet_id')::uuid;
      v_location_set_hospital := v_location_update ? 'hospital_norm';
      v_location_set_ward := v_location_update ? 'ward_norm';
      if not v_location_set_hospital and not v_location_set_ward then
        continue;
      end if;

      v_location_hospital_norm := null;
      if v_location_set_hospital then
        v_location_hospital_norm := nullif(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'hospital_norm','')),
          '[[:space:]]+',' ','g')), '');
      end if;
      v_location_ward_norm := null;
      if v_location_set_ward then
        v_location_ward_norm := nullif(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'ward_norm','')),
          '[[:space:]]+',' ','g')), '');
      end if;

      update public.timesheets tsu
      set updated_at=v_now,
          hospital_norm=case when v_location_set_hospital
            then v_location_hospital_norm else tsu.hospital_norm end,
          ward_norm=case when v_location_set_ward
            then v_location_ward_norm else tsu.ward_norm end
      where tsu.timesheet_id=v_location_ts_id
        and tsu.is_current=true
        and exists(
          select 1
          from public.invoice_lines owned_line
          where owned_line.invoice_id=p_invoice_id
            and (
              owned_line.timesheet_id=tsu.timesheet_id
              or (
                owned_line.timesheet_id is null
                and coalesce(owned_line.meta_json->>'timesheet_id','')
                  ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                and (owned_line.meta_json->>'timesheet_id')::uuid=tsu.timesheet_id
              )
            )
        )
        and (
          (v_location_set_hospital
            and tsu.hospital_norm is distinct from v_location_hospital_norm)
          or (v_location_set_ward
            and tsu.ward_norm is distinct from v_location_ward_norm)
        );

      get diagnostics v_rc=row_count;
      if coalesce(v_rc,0)>0 then
        v_location_applied:=v_location_applied+1;
        v_location_ts_ids:=v_location_ts_ids||v_location_ts_id;
      end if;
    end loop;

    if v_invoice_debug then
      v_dbg_steps:=v_dbg_steps||jsonb_build_array(jsonb_build_object(
        'step','timesheet_location_updates_applied',
        'count_requested',v_location_count,
        'count_applied',v_location_applied));
    end if;
  end if;
  -- 0b) After reference updates: refresh invoice_lines meta (ts_reference_number / schedule_ref_nums) and
  -- synchronise only the approved ref_num fields into the locked SEGMENTS
  -- financial projection. The full financial objects and their order are
  -- preserved from the locked current snapshot.
  if v_refupd_ts_ids is not null and coalesce(array_length(v_refupd_ts_ids,1),0) > 0 then

    with desired as materialized(
      select value
      from jsonb_each(v_source_updates_map)
      where (value->>'segment_reference_changed')::boolean
    )
    update public.timesheets_financials tf
    set invoice_breakdown_json=jsonb_set(
      coalesce(tf.invoice_breakdown_json,'{}'::jsonb),
      '{segments}',d.value->'new_financial_segments',true)
    from desired d
    where tf.id=(d.value->>'financial_id')::uuid
      and tf.is_current
      and tf.timesheet_id=(d.value->>'timesheet_id')::uuid
      and upper(coalesce(tf.invoice_breakdown_json->>'mode',''))='SEGMENTS'
      and tf.invoice_breakdown_json->'segments'
        is distinct from d.value->'new_financial_segments';
    get diagnostics v_refupd_tsfin_rows_updated=row_count;
    select coalesce(sum(jsonb_array_length(
      coalesce(value->'segment_updates','[]'::jsonb))),0)::integer
    into v_refupd_tsfin_segments_updated
    from jsonb_each(v_source_updates_map)
    where (value->>'segment_reference_changed')::boolean;

    -- The marker has served its single synchronisation statement. Clear it so
    -- no later statement in this transaction can inherit suppression authority.
    perform set_config('cloudtms.invoice_source_edit_marker','{}',true);

    select array_agg(distinct x)
    into v_refupd_ts_ids_distinct
    from unnest(v_refupd_ts_ids) x
    where x is not null;

    v_refupd_ts_ids_distinct := coalesce(v_refupd_ts_ids_distinct, array[]::uuid[]);

    foreach v_ref_ts_id in array v_refupd_ts_ids_distinct loop
      if v_ref_ts_id is null then
        continue;
      end if;

      select tsu.*
      into v_ref_ts
      from public.timesheets tsu
      where tsu.timesheet_id = v_ref_ts_id
        and tsu.is_current = true
      limit 1;

      if not found then
        continue;
      end if;
      v_source_update:=v_source_updates_map->v_ref_ts_id::text;
      v_source_mode:=upper(coalesce(v_source_update->>'source_mode',''));
      v_source_canonical_schedule:=case when v_source_mode='SEGMENTS'
        then coalesce(v_source_update->'new_financial_segments','[]'::jsonb)
        else coalesce(v_ref_ts.actual_schedule_json,'[]'::jsonb) end;

      -- Build the cache from the exact authority used by this invoice. SEGMENTS
      -- refs come from invoice-owned financial segments; other modes use the
      -- structurally preserved timesheet schedule.
      v_ref_schedule_refs := '[]'::jsonb;

      if nullif(btrim(coalesce(v_ref_ts.reference_number,'')), '') is not null then
        v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(nullif(btrim(v_ref_ts.reference_number),'')));
      end if;

      if v_ref_ts.day_references_json is not null and jsonb_typeof(v_ref_ts.day_references_json) = 'object' then
        for kv in
          select key as k, value as v
          from jsonb_each_text(v_ref_ts.day_references_json)
        loop
          if nullif(btrim(coalesce(kv.v,'')), '') is not null then
            v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(nullif(btrim(kv.v),'')));
          end if;
        end loop;
      end if;

      if jsonb_typeof(v_source_canonical_schedule)='array' then
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_source_canonical_schedule) value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            continue;
          end if;
          v_ref_sched_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
          if v_ref_sched_ref is not null then
            v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(v_ref_sched_ref));
          end if;
        end loop;
      end if;

      select coalesce(jsonb_agg(to_jsonb(x) order by x), '[]'::jsonb)
      into v_ref_schedule_refs_distinct
      from (
        select distinct btrim(t.x) as x
        from jsonb_array_elements_text(coalesce(v_ref_schedule_refs,'[]'::jsonb)) as t(x)
        where nullif(btrim(coalesce(t.x,'')), '') is not null
      ) q;

      -- Refresh meta_json on all invoice lines for this timesheet
      update public.invoice_lines ilu
      set meta_json = coalesce(ilu.meta_json, '{}'::jsonb) || jsonb_build_object(
        'ts_reference_number', nullif(btrim(coalesce(v_ref_ts.reference_number,'')), ''),
        'schedule_ref_nums', coalesce(v_ref_schedule_refs_distinct, '[]'::jsonb),
        'schedule_ref_count', jsonb_array_length(coalesce(v_ref_schedule_refs_distinct, '[]'::jsonb))
      )
      where ilu.invoice_id = p_invoice_id
        and (
          ilu.timesheet_id=v_ref_ts_id
          or (
            ilu.timesheet_id is null
            and coalesce(ilu.meta_json->>'timesheet_id','') ~
              '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            and (ilu.meta_json->>'timesheet_id')::uuid=v_ref_ts_id
          )
        )
        and (
          ilu.meta_json->'ts_reference_number' is distinct from
            coalesce(to_jsonb(nullif(btrim(coalesce(v_ref_ts.reference_number,'')),'')),'null'::jsonb)
          or ilu.meta_json->'schedule_ref_nums' is distinct from
            coalesce(v_ref_schedule_refs_distinct,'[]'::jsonb)
          or ilu.meta_json->'schedule_ref_count' is distinct from
            to_jsonb(jsonb_array_length(coalesce(v_ref_schedule_refs_distinct,'[]'::jsonb)))
        );

      get diagnostics v_rc = row_count;
      v_refupd_meta_rows_updated := v_refupd_meta_rows_updated + coalesce(v_rc,0);

      -- Best-effort sync: update tsfin.invoice_breakdown_json segments[].ref_num by matching start/end fields
      v_ref_seg_updates_this_ts := 0;
      v_ref_seg_matches_this_ts := 0;
      v_ref_tsfin_id := null;
      v_ref_ib := null;

        select tfu.id, tfu.invoice_breakdown_json
      into v_ref_tsfin_id, v_ref_ib
      from public.timesheets_financials tfu
      where tfu.timesheet_id = v_ref_ts_id
        and tfu.is_current = true
      limit 1
      for update;


      if v_ref_tsfin_id is not null
         and v_source_mode<>'SEGMENTS'
         and v_ref_ib is not null
         and jsonb_typeof(v_ref_ib) = 'object'
         and upper(coalesce(v_ref_ib->>'mode','')) = 'SEGMENTS'
         and jsonb_typeof(v_ref_ib->'segments') = 'array'
         and v_ref_ts.actual_schedule_json is not null
         and jsonb_typeof(v_ref_ts.actual_schedule_json) = 'array'
       then
         -- Build a map of segment_id (preferred) or start|end -> ref_num from actual_schedule_json
        v_ref_sched_map := '{}'::jsonb;
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_ref_ts.actual_schedule_json) value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            continue;
          end if;

          v_ref_sched_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
          v_ref_seg_id := nullif(btrim(coalesce(v_ref_seg_obj->>'segment_id','')), '');
          if v_ref_seg_id is not null then
            v_ref_sched_key := 'SID:' || v_ref_seg_id;
            if v_ref_sched_map ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                  'side','TIMESHEET_SCHEDULE')::text;
            end if;
            v_ref_sched_map := jsonb_set(v_ref_sched_map, array[v_ref_sched_key], case when v_ref_sched_ref is null then 'null'::jsonb else to_jsonb(v_ref_sched_ref) end, true);
            continue;
          end if;

          v_ref_seg_start := nullif(btrim(coalesce(v_ref_seg_obj->>'start_utc', v_ref_seg_obj->>'start', '')), '');
          v_ref_seg_end := nullif(btrim(coalesce(v_ref_seg_obj->>'end_utc', v_ref_seg_obj->>'end', '')), '');
          if v_ref_seg_start is null or v_ref_seg_end is null then
            continue;
          end if;

          v_ref_sched_key := 'SE:' || v_ref_seg_start || '|' || v_ref_seg_end;
          if v_ref_sched_map ? v_ref_sched_key then
            raise exception using errcode='22023',
              message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
              detail=jsonb_build_object(
                'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                'side','TIMESHEET_SCHEDULE')::text;
          end if;
          v_ref_sched_map := jsonb_set(v_ref_sched_map, array[v_ref_sched_key], case when v_ref_sched_ref is null then 'null'::jsonb else to_jsonb(v_ref_sched_ref) end, true);
        end loop;

        v_ref_new_segments := '[]'::jsonb;
        v_ref_seen_keys := '{}'::jsonb;
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_ref_ib->'segments') value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            v_ref_new_segments := v_ref_new_segments || jsonb_build_array(v_ref_seg_obj);
            continue;
          end if;

          v_ref_seg_new_ref := null;
          v_ref_seg_has_update := false;

          v_ref_seg_id := nullif(btrim(coalesce(v_ref_seg_obj->>'segment_id','')), '');
          if v_ref_seg_id is not null then
            v_ref_sched_key := 'SID:' || v_ref_seg_id;
            if v_ref_seen_keys ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                  'side','FINANCIAL_SEGMENTS')::text;
            end if;
            v_ref_seen_keys:=jsonb_set(v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
            if v_ref_sched_map ? v_ref_sched_key then
              v_ref_seg_new_ref := nullif(btrim(coalesce(v_ref_sched_map->>v_ref_sched_key,'')), '');
              v_ref_seg_has_update := true;
              v_ref_seg_matches_this_ts := v_ref_seg_matches_this_ts + 1;
            end if;
          end if;

          if not v_ref_seg_has_update then
            v_ref_seg_start := nullif(btrim(coalesce(v_ref_seg_obj->>'start_utc', v_ref_seg_obj->>'start', '')), '');
            v_ref_seg_end := nullif(btrim(coalesce(v_ref_seg_obj->>'end_utc', v_ref_seg_obj->>'end', '')), '');

            if v_ref_seg_start is not null and v_ref_seg_end is not null then
              v_ref_sched_key := 'SE:' || v_ref_seg_start || '|' || v_ref_seg_end;
              if v_ref_seen_keys ? v_ref_sched_key then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                  detail=jsonb_build_object(
                    'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                    'side','FINANCIAL_SEGMENTS')::text;
              end if;
              v_ref_seen_keys:=jsonb_set(v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
              if v_ref_sched_map ? v_ref_sched_key then
                v_ref_seg_new_ref := nullif(btrim(coalesce(v_ref_sched_map->>v_ref_sched_key,'')), '');
                v_ref_seg_has_update := true;
                v_ref_seg_matches_this_ts := v_ref_seg_matches_this_ts + 1;
              end if;
            end if;
          end if;

          if v_ref_seg_has_update then
            v_ref_seg_cur_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
            if v_ref_seg_cur_ref is distinct from v_ref_seg_new_ref then
              v_ref_seg_obj := jsonb_set(
                v_ref_seg_obj,
                '{ref_num}',
                case when v_ref_seg_new_ref is null then 'null'::jsonb else to_jsonb(v_ref_seg_new_ref) end,
                true
              );
              v_ref_seg_updates_this_ts := v_ref_seg_updates_this_ts + 1;
            end if;
          end if;

          v_ref_new_segments := v_ref_new_segments || jsonb_build_array(v_ref_seg_obj);
        end loop;



        if v_ref_sched_map is not null
           and jsonb_typeof(v_ref_sched_map) = 'object'
           and v_ref_sched_map <> '{}'::jsonb
           and coalesce(jsonb_array_length(coalesce(v_ref_ib->'segments','[]'::jsonb)),0) > 0
           and coalesce(v_ref_seg_matches_this_ts,0) = 0
        then
          raise exception 'SEGMENTS reference sync failed: no segments matched schedule keys (timesheet_id=% tsfin_id=%)', v_ref_ts_id, v_ref_tsfin_id;
        end if;

        if v_ref_seg_updates_this_ts > 0 then
              update public.timesheets_financials tfu2
          set invoice_breakdown_json = jsonb_set(coalesce(tfu2.invoice_breakdown_json, '{}'::jsonb), '{segments}', v_ref_new_segments, true)
          where tfu2.id = v_ref_tsfin_id
            and tfu2.is_current = true;


          get diagnostics v_rc = row_count;
          if coalesce(v_rc,0) > 0 then
            v_refupd_tsfin_rows_updated := v_refupd_tsfin_rows_updated + 1;
            v_refupd_tsfin_segments_updated := v_refupd_tsfin_segments_updated + v_ref_seg_updates_this_ts;
          end if;
        end if;

      end if;

    end loop;

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','reference_updates_meta_refreshed',
          'timesheets_count', coalesce(array_length(v_refupd_ts_ids_distinct,1),0),
          'invoice_line_rows_updated', v_refupd_meta_rows_updated,
          'tsfin_rows_updated', v_refupd_tsfin_rows_updated,
          'tsfin_segments_refnum_updated', v_refupd_tsfin_segments_updated
        )
      );
    end if;
  end if;

  -- 1) Removals (by invoice_line_id)
  if v_remove_ids is not null and coalesce(array_length(v_remove_ids,1),0) > 0 then
    -- collect timesheet_ids touched (any)
    select array_agg(distinct l.timesheet_id) filter (where l.timesheet_id is not null)
    into v_ts_ids_touched
    from public.invoice_lines l
    where l.invoice_id = p_invoice_id
      and l.id = any(v_remove_ids);

    -- record removed lines for history
    v_hist_lines_removed := coalesce(p_payload->'remove_invoice_line_ids','[]'::jsonb);

    -- Only unlock TSFIN when HOURS lines were removed (prevents accidental unlock when deleting only expenses/other lines)
    -- IMPORTANT: compute BEFORE deletion because we match on the removed invoice_line ids.
    select array_agg(distinct l.timesheet_id) filter (where l.timesheet_id is not null)
    into v_cw_ts_ids
    from public.invoice_lines l
    where l.invoice_id = p_invoice_id
      and l.id = any(v_remove_ids)
      and upper(coalesce(l.meta_json->>'line_type','')) in ('HOURS_WEEKLY','HOURS_DAILY');

    v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);



    if coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
      v_refresh_hr_cache := true;
    end if;
delete from public.invoice_lines
    where invoice_id = p_invoice_id
      and id = any(v_remove_ids);
    get diagnostics v_rc = row_count;
    v_dbg_lines_deleted := v_dbg_lines_deleted + coalesce(v_rc,0);

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','lines_removed',
          'rows_deleted', coalesce(v_rc,0),
          'timesheets_touched', coalesce(array_length(v_ts_ids_touched,1),0),
          'timesheets_to_unlock_count', coalesce(array_length(v_cw_ts_ids,1),0)
        )
      );
    end if;

    -- FIX: if a touched timesheet now has NO remaining invoice_lines on this invoice,
    -- unlock it even if the removed lines were expenses/mileage/additional (expense-only/SEGMENTS-empty case).
    v_ts_ids_fully_removed := array[]::uuid[];
    select array_agg(distinct x)
    into v_ts_ids_fully_removed
    from unnest(coalesce(v_ts_ids_touched, array[]::uuid[])) x
    where x is not null
      and not exists (
        select 1
        from public.invoice_lines l2
        where l2.invoice_id = p_invoice_id
          and l2.timesheet_id = x
      );

    v_ts_ids_fully_removed := coalesce(v_ts_ids_fully_removed, array[]::uuid[]);

    if coalesce(array_length(v_ts_ids_fully_removed,1),0) > 0 then
      -- unlock any segments locked to this invoice (safe no-op for SEGMENTS-empty)
      perform public._inv_unlock_segments_for_invoice(p_invoice_id, v_ts_ids_fully_removed);

      -- clear whole-timesheet lock if it was set for this invoice (SEGMENTS-empty / non-segments / pseudo segment_id null locks)
      update public.timesheets_financials tfu_lock
      set
        locked_by_invoice_id = null,
        locked_at_utc = null,
        updated_at = v_now
      where tfu_lock.is_current = true
        and tfu_lock.timesheet_id = any(v_ts_ids_fully_removed)
        and tfu_lock.locked_by_invoice_id = p_invoice_id;

      get diagnostics v_rc = row_count;
      v_dbg_timesheets_unlocked := v_dbg_timesheets_unlocked + coalesce(v_rc,0);

      v_refresh_hr_cache := true;

      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(
          jsonb_build_object(
            'step','timesheets_unlocked_after_full_removal',
            'timesheets_fully_removed_count', coalesce(array_length(v_ts_ids_fully_removed,1),0),
            'tsfin_rows_unlocked_count', coalesce(v_rc,0)
          )
        );
      end if;
    end if;

    v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);

    if v_cw_ts_ids is not null and coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
      perform public._inv_unlock_segments_for_invoice(p_invoice_id, v_cw_ts_ids);
      v_dbg_timesheets_unlocked := v_dbg_timesheets_unlocked + coalesce(array_length(v_cw_ts_ids,1),0);

      -- Cleanup: if no segments remain on THIS invoice for a touched timesheet, remove ALL remaining invoice lines for that timesheet
      foreach tsid in array v_cw_ts_ids loop
        if tsid is null then continue; end if;

        -- detect if any segments are still locked to THIS invoice
        select tf.*
        into snap
        from public.timesheets_financials tf
        where tf.is_current = true
          and tf.timesheet_id = tsid
        limit 1;

        if not found then
          continue;
        end if;

        segments := '[]'::jsonb;
        if snap.invoice_breakdown_json is not null
           and jsonb_typeof(snap.invoice_breakdown_json)='object'
           and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
           and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
        then
          for v_seg in
            select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
          loop
            if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
              continue;
            end if;
            seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
            if seg_locked = p_invoice_id::text then
              segments := segments || jsonb_build_array(v_seg);
            end if;
          end loop;

          if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
            delete from public.invoice_lines
            where invoice_id = p_invoice_id
              and timesheet_id = tsid;
          end if;
        else
          -- Non-segments: if snapshot is no longer locked to this invoice, remove all remaining invoice lines for this timesheet
          if snap.locked_by_invoice_id is null then
            delete from public.invoice_lines
            where invoice_id = p_invoice_id
              and timesheet_id = tsid;
          end if;
        end if;
      end loop;
    end if;

    -- History event (always)
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_LINES_REMOVED',
      null,
      jsonb_build_object('remove_invoice_line_ids', v_hist_lines_removed, 'timesheet_ids_touched', coalesce(to_jsonb(v_ts_ids_touched), '[]'::jsonb)),
      null,
      p_actor_user_id
    );

  end if;


  -- 1b) Segment edits (SEGMENTS mode only)
-- NOTE: Segment moves are NOT allowed when additional rates OR expenses/mileage exist on the TSFIN snapshot.
-- Payload contract uses tsfin_id + segment_id.
if v_has_seg_ops then

  v_dbg_seg_add_refs := case when v_add_seg_refs is null then 0 else jsonb_array_length(coalesce(v_add_seg_refs,'[]'::jsonb)) end;
  v_dbg_seg_remove_refs := case when v_remove_seg_refs is null then 0 else jsonb_array_length(coalesce(v_remove_seg_refs,'[]'::jsonb)) end;

  if v_invoice_debug then
    v_dbg_steps := v_dbg_steps || jsonb_build_array(
      jsonb_build_object(
        'step','segment_ops_start',
        'add_segment_refs_count', v_dbg_seg_add_refs,
        'remove_segment_refs_count', v_dbg_seg_remove_refs
      )
    );
  end if;

  -- Collect distinct tsfin_ids involved in segment ops
  select array_agg(distinct (x->>'tsfin_id')::uuid)
  into v_seg_tsfin_ids
  from (
    select value as x
    from jsonb_array_elements(coalesce(v_remove_seg_refs,'[]'::jsonb))
    union all
    select value as x
    from jsonb_array_elements(coalesce(v_add_seg_refs,'[]'::jsonb))
  ) u
  where jsonb_typeof(x) = 'object'
    and nullif(btrim(coalesce(x->>'tsfin_id','')), '') is not null;

  v_seg_tsfin_ids := coalesce(v_seg_tsfin_ids, array[]::uuid[]);

  v_dbg_seg_tsfins := coalesce(array_length(v_seg_tsfin_ids,1),0);
  if v_invoice_debug then
    v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','segment_ops_targets','tsfin_count',v_dbg_seg_tsfins));
  end if;

  if coalesce(array_length(v_seg_tsfin_ids,1),0) > 0 then

    -- Validate that each snapshot is current SEGMENTS mode and has NO additional/expenses/mileage
    foreach v_tsfin_id in array v_seg_tsfin_ids loop
      select *
      into snap
      from public.timesheets_financials tf
      where tf.id = v_tsfin_id
      limit 1;

      if not found then
        raise exception 'Segment edit refers to unknown tsfin_id %', v_tsfin_id;
      end if;

      if snap.is_current is not true then
        raise exception 'Segment edit requires current tsfin snapshot (tsfin_id=%)', v_tsfin_id;
      end if;

      if snap.client_id is distinct from v_inv.client_id then
        raise exception 'Segment edit timesheet client mismatch (tsfin_id=%)', v_tsfin_id;
      end if;

      if snap.invoice_breakdown_json is null
         or jsonb_typeof(snap.invoice_breakdown_json) <> 'object'
         or upper(coalesce(snap.invoice_breakdown_json->>'mode','')) <> 'SEGMENTS'
         or jsonb_typeof(snap.invoice_breakdown_json->'segments') <> 'array'
      then
        raise exception 'Segment edit is only supported for SEGMENTS timesheets (tsfin_id=%)', v_tsfin_id;
      end if;

      v_has_additional :=
        public._inv_round2(coalesce(snap.additional_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.additional_charge_ex_vat,0)) <> 0
        or (snap.additional_units_json is not null and jsonb_typeof(snap.additional_units_json)='object' and snap.additional_units_json <> '{}'::jsonb);

      v_has_expense_or_mileage :=
        public._inv_round2(coalesce(snap.expenses_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.expenses_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_units,0)) <> 0
        or public._inv_round2(coalesce(snap.travel_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.travel_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.accommodation_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.accommodation_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.other_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.other_charge_ex_vat,0)) <> 0;

      if v_has_additional then
        raise exception 'Segments cannot be moved when additional rates exist (timesheet_id=% tsfin_id=%)', snap.timesheet_id, v_tsfin_id;
      end if;

      if v_has_expense_or_mileage then
        raise exception 'Segments cannot be moved when expenses or mileage exist (timesheet_id=% tsfin_id=%)', snap.timesheet_id, v_tsfin_id;
      end if;
    end loop;

    -- Validate and apply add_segment_refs (lock selected segments)
    v_seg_refs_to_lock := '[]'::jsonb;
    if v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0 then
      for v_ref in
        select value from jsonb_array_elements(v_add_seg_refs) value
      loop
        if v_ref is null or jsonb_typeof(v_ref) <> 'object' then
          continue;
        end if;

        if nullif(btrim(coalesce(v_ref->>'tsfin_id','')), '') is null then
          continue;
        end if;

        v_tsfin_id := (v_ref->>'tsfin_id')::uuid;
        v_seg_id := nullif(btrim(coalesce(v_ref->>'segment_id','')), '');

        if v_seg_id is null then
          raise exception 'add_segment_refs requires segment_id (tsfin_id=%)', v_tsfin_id;
        end if;

          -- Load snapshot + timesheet + precheck (must be OK)
        select
          tf.*,
          tsr.sheet_scope::text as sheet_scope,
          coalesce(tsr.submission_mode::text,'') as submission_mode,
          tsr.day_references_json,
          tsr.actual_schedule_json,
          tsr.week_ending_date,
          cw.contract_id
        into snap
        from public.timesheets_financials tf
        join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
        left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
        join public.v_ts_invoice_precheck pcv on pcv.timesheet_id = tf.timesheet_id
        where tf.id = v_tsfin_id
          and tf.is_current = true
          and tf.client_id = v_inv.client_id
          and upper(coalesce(pcv.precheck_status,''))
            in ('OK','BLOCK_NO_PDF')
        limit 1;

        if not found then
          raise exception 'Segment add failed eligibility (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        natural_start := (snap.week_ending_date::date - 6);

        -- Locate the segment object
        v_seg := null;
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;
          if nullif(btrim(coalesce(v_seg->>'segment_id','')), '') = v_seg_id then
            exit;
          end if;
          v_seg := null;
        end loop;

        if v_seg is null then
          raise exception 'Segment not found (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
        if seg_locked is not null then
          raise exception 'Segment already invoiced (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        seg_target := nullif(btrim(coalesce(v_seg->>'invoice_target_week_start','')), '')::date;
        seg_ref := btrim(coalesce(v_seg->>'ref_num',''));

        -- segment-level ref gating if required
        select * into pc from public.v_ts_invoice_precheck where timesheet_id = snap.timesheet_id limit 1;
        if pc.require_reference_to_invoice is true and seg_ref = '' then
          raise exception 'Segment missing reference number (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
        end if;

        -- Week eligibility
        if seg_target is null or seg_target = natural_start then
          if v_week_start <> natural_start then
            raise exception 'Segment not eligible for this invoice week (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
        else
          if v_week_start <> seg_target then
            raise exception 'Delayed segment not eligible for this invoice week (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
          if seg_target > v_anchor_ymd then
            raise exception 'Delayed segment cannot be invoiced early (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
        end if;

        v_seg_refs_to_lock := v_seg_refs_to_lock || jsonb_build_array(
          jsonb_build_object(
            'tsfin_id', v_tsfin_id::text,
            'segment_id', v_seg_id
          )
        );
      end loop;

      if jsonb_typeof(v_seg_refs_to_lock) = 'array' and jsonb_array_length(v_seg_refs_to_lock) > 0 then
        perform public._inv_lock_segments_for_invoice(p_invoice_id, v_seg_refs_to_lock);
      end if;
    end if;

      -- Apply remove_segment_refs (unlock selected segments on THIS invoice)
    if v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0 then
      perform public._inv_unlock_segment_refs_for_invoice(p_invoice_id, v_remove_seg_refs::jsonb, p_actor_user_id);
    end if;



    -- History: segment ops (always)
    if v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0 then
      perform public._audit_insert(
        'invoices',
        p_invoice_id::text,
        'INVOICE_SEGMENTS_ADDED',
        null,
        jsonb_build_object('add_segment_refs', v_add_seg_refs),
        null,
        p_actor_user_id
      );
    end if;
    if v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0 then
      perform public._audit_insert(
        'invoices',
        p_invoice_id::text,
        'INVOICE_SEGMENTS_REMOVED',
        null,
        jsonb_build_object('remove_segment_refs', v_remove_seg_refs),
        null,
        p_actor_user_id
      );
    end if;

    -- Rebuild HOURS lines for touched timesheets on this invoice
    select array_agg(distinct tf.timesheet_id)
    into v_seg_ts_ids
    from public.timesheets_financials tf
    where tf.id = any(v_seg_tsfin_ids);

    v_seg_ts_ids := coalesce(v_seg_ts_ids, array[]::uuid[]);

    foreach tsid in array v_seg_ts_ids loop
      if tsid is null then
        continue;
      end if;

      -- Load snapshot + timesheet + contract (no READY_FOR_INVOICE restriction; this is an invoice edit)
      select
        tf.*,
        tsr.booking_id,
        tsr.week_ending_date,
        tsr.reference_number,
        tsr.sheet_scope::text as sheet_scope,
        coalesce(tsr.submission_mode::text,'') as submission_mode,
        tsr.day_references_json,
        tsr.actual_schedule_json,
        cw.contract_id
      into snap
      from public.timesheets_financials tf
      join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
      left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
      where tf.timesheet_id = tsid
        and tf.is_current = true
      limit 1;

      if not found then
        v_dbg_add_timesheets_skipped := v_dbg_add_timesheets_skipped + 1;
        if v_invoice_debug then
          v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_skipped','timesheet_id',tsid::text));
        end if;
        continue;
      end if;

      v_dbg_add_timesheets_found := v_dbg_add_timesheets_found + 1;
      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_loaded','timesheet_id',tsid::text,'tsfin_id',snap.id::text));
      end if;

      select v.r2_key
      into v_exact_timesheet_document_r2_key
      from public.timesheets t
      join public.invoice_document_versions v
        on v.entity_type='TIMESHEET'
       and v.entity_id=t.timesheet_id
       and v.purpose='TIMESHEET'
       and v.source_revision=t.document_revision::text
       and v.status='READY'
       and nullif(v.r2_key,'') is not null
       and nullif(v.sha256,'') is not null
       and coalesce(v.size_bytes,0)>0
       and coalesce(v.page_count,0)>0
      where t.timesheet_id=tsid and t.is_current
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1;


      contract_id := snap.contract_id;
      c_daily_calc := false;
      c_bucket_labels := null;
      c_display_site := null;

      if contract_id is not null then
        select
          nullif(btrim(coalesce(display_site,'')), '')
        into
          c_display_site
        from public.contracts
        where id = contract_id
        limit 1;
      end if;

      v_settings_authority := private._timesheet_settings_authority_frozen_v1(tsid);
      c_daily_calc := coalesce(
        (v_settings_authority#>>'{values,daily_calc_of_invoices}')::boolean,
        false
      );
      c_bucket_labels := case
        when coalesce((v_settings_authority->>'override_client_settings')::boolean,false)
          then v_settings_authority#>'{values,bucket_labels_json}'
        else null
      end;

      if c_bucket_labels is null then
        c_bucket_labels := jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH');
      end if;

      -- Build segment set locked to THIS invoice
      segments := '[]'::jsonb;
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
         and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
      then
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
          if seg_locked = p_invoice_id::text then
            segments := segments || jsonb_build_array(v_seg);
          end if;
        end loop;
      end if;

      if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
        -- If no segments remain on this invoice for this timesheet, remove ALL invoice lines for that timesheet
        delete from public.invoice_lines
        where invoice_id = p_invoice_id
          and timesheet_id = tsid;
        v_dbg_seg_timesheets_removed := v_dbg_seg_timesheets_removed + 1;
        continue;
      end if;

      v_dbg_seg_timesheets_rebuilt := v_dbg_seg_timesheets_rebuilt + 1;

      -- Replace HOURS lines for this timesheet on this invoice
      delete from public.invoice_lines
      where invoice_id = p_invoice_id
        and timesheet_id = tsid
        and upper(coalesce(meta_json->>'line_type','')) in ('HOURS_WEEKLY','HOURS_DAILY');
        -- HOURS lines
        if c_daily_calc then
          -- Daily: group by segment.date
          for r_day in
            with rows as (
              select
                nullif(btrim(coalesce(seg_el->>'date','')), '') as ymd,
                coalesce((seg_el->>'hours_day')::numeric,0)   as h_day,
                coalesce((seg_el->>'hours_night')::numeric,0) as h_night,
                coalesce((seg_el->>'hours_sat')::numeric,0)   as h_sat,
                coalesce((seg_el->>'hours_sun')::numeric,0)   as h_sun,
                coalesce((seg_el->>'hours_bh')::numeric,0)    as h_bh,
                coalesce((seg_el->>'pay_amount')::numeric,0)  as pay_ex,
                coalesce((seg_el->>'charge_amount')::numeric,0) as chg_ex
              from jsonb_array_elements(segments) seg_el
            ),
            agg as (
              select
                ymd,
                sum(rows.h_day)::numeric as hours_day,
                sum(rows.h_night)::numeric as hours_night,
                sum(rows.h_sat)::numeric as hours_sat,
                sum(rows.h_sun)::numeric as hours_sun,
                sum(rows.h_bh)::numeric as hours_bh,
                sum(rows.pay_ex)::numeric as pay_ex,
                sum(rows.chg_ex)::numeric as chg_ex
              from rows
              where ymd is not null and ymd ~ '^\d{4}-\d{2}-\d{2}$'
              group by ymd
            )
            select * from agg order by ymd
          loop
          chg_ex := public._inv_round2(r_day.chg_ex);
if chg_ex = 0 then continue; end if;

if (coalesce(r_day.hours_day,0)+coalesce(r_day.hours_night,0)+coalesce(r_day.hours_sat,0)+coalesce(r_day.hours_sun,0)+coalesce(r_day.hours_bh,0)) = 0 then
  continue;
end if;


            pay_ex := public._inv_round2(r_day.pay_ex);
            margin_ex := public._inv_round2(chg_ex - pay_ex);
            vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
            inc_amt := public._inv_round2(chg_ex + vat_amt);

            line_desc := coalesce(nullif(btrim(coalesce(c_display_site,'')) ,''), ('TS '||tsid::text)) ||
                         ' – '|| r_day.ymd || ' – W/E '|| coalesce(snap.week_ending_date::text,'');

            v_meta := jsonb_build_object(
              'line_type','HOURS_DAILY',
              'timesheet_id', tsid::text,
              'tsfin_id', snap.id::text,
              'candidate_display', coalesce(nullif(btrim(coalesce(c_display_site,'')),''), null),
              'role', c_role,
              'hospital', c_display_site,
              'ward', c_ward_hint,
              'week_ending_date', snap.week_ending_date::text,
              'date', r_day.ymd,
              'bucket_labels', c_bucket_labels
            );

            v_source_key := 'TS:' || tsid::text || ':HOURS:' || r_day.ymd;

            insert into public.invoice_lines(
              invoice_id, timesheet_id, booking_id, description,
              hours_day, hours_night, hours_sat, hours_sun, hours_bh,
              pay_day, pay_night, pay_sat, pay_sun, pay_bh,
              charge_day, charge_night, charge_sat, charge_sun, charge_bh,
              total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
              vat_rate_pct, vat_amount, total_inc_vat,
              paper_ts_r2_key, meta_json, source_key
            )
            values (
              p_invoice_id, tsid, snap.booking_id, line_desc,
              public._inv_round2(r_day.hours_day), public._inv_round2(r_day.hours_night), public._inv_round2(r_day.hours_sat), public._inv_round2(r_day.hours_sun), public._inv_round2(r_day.hours_bh),
              null,null,null,null,null,
              null,null,null,null,null,
              pay_ex, chg_ex, margin_ex,
              v_vat_rate, vat_amt, inc_amt,
              v_exact_timesheet_document_r2_key,
              v_meta,
              v_source_key
            )
            on conflict (invoice_id, source_key) do nothing;
          end loop;
        else
          -- Weekly hours line
          select
            public._inv_round2(coalesce(sum((seg_el->>'hours_day')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_night')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_sat')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_sun')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_bh')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'pay_amount')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'charge_amount')::numeric),0))
          into h_day, h_night, h_sat, h_sun, h_bh, pay_ex, chg_ex
          from jsonb_array_elements(segments) seg_el;

       if chg_ex <> 0 and (coalesce(h_day,0)+coalesce(h_night,0)+coalesce(h_sat,0)+coalesce(h_sun,0)+coalesce(h_bh,0)) <> 0 then
  margin_ex := public._inv_round2(chg_ex - pay_ex);
  vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
  inc_amt := public._inv_round2(chg_ex + vat_amt);

  line_desc := coalesce(nullif(btrim(coalesce(c_display_site,'')) ,''), ('TS '||tsid::text)) ||
               ' – W/E '|| coalesce(snap.week_ending_date::text,'');

  v_meta := jsonb_build_object(
    'line_type','HOURS_WEEKLY',
    'timesheet_id', tsid::text,
    'tsfin_id', snap.id::text,
    'week_ending_date', snap.week_ending_date::text,
    'bucket_labels', c_bucket_labels
  );

  v_source_key := 'TS:' || tsid::text || ':HOURS:WEEK';

  insert into public.invoice_lines(
    invoice_id, timesheet_id, booking_id, description,
    hours_day, hours_night, hours_sat, hours_sun, hours_bh,
    pay_day, pay_night, pay_sat, pay_sun, pay_bh,
    charge_day, charge_night, charge_sat, charge_sun, charge_bh,
    total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
    vat_rate_pct, vat_amount, total_inc_vat,
    paper_ts_r2_key, meta_json, source_key
  )
  values (
    p_invoice_id, tsid, snap.booking_id, line_desc,
    h_day, h_night, h_sat, h_sun, h_bh,
    null,null,null,null,null,
    null,null,null,null,null,
    pay_ex, chg_ex, margin_ex,
    v_vat_rate, vat_amt, inc_amt,
    v_exact_timesheet_document_r2_key,
    v_meta,
    v_source_key
  )
  on conflict (invoice_id, source_key) do nothing;
end if;

        end if;

        -- Additional rates


    end loop;
  end if;
end if;

  -- 2) Add adjustments
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_adjustments') then
    if jsonb_typeof(p_payload->'add_adjustments') = 'array' then
      for adj in
        select value from jsonb_array_elements(p_payload->'add_adjustments') value
      loop
        if adj is null or jsonb_typeof(adj) <> 'object' then
          continue;
        end if;

        v_adj_token := nullif(btrim(coalesce(adj->>'client_token','')), '');
        v_adj_desc  := nullif(btrim(coalesce(adj->>'description','')), '');
        begin
          v_adj_ex := (adj->>'amount_ex_vat')::numeric;
        exception when others then
          v_adj_ex := null;
        end;

        if v_adj_token is null or v_adj_desc is null or v_adj_ex is null then
          continue;
        end if;

        v_adj_vat := public._inv_round2(v_adj_ex * v_vat_rate / 100);
        if v_vat_rate = 0 then v_adj_vat := 0; end if;
        v_adj_inc := public._inv_round2(v_adj_ex + v_adj_vat);

        v_adj_source_key := 'ADJ:' || v_adj_token;

        v_meta := jsonb_build_object(
          'line_type','ADJUSTMENT',
          'client_token', v_adj_token,
          'description', v_adj_desc,
          'amount_ex_vat', public._inv_round2(v_adj_ex),
          'vat_rate_pct', v_vat_rate,
          'vat_chargeable', v_vat_chargeable
        );

        v_hist_adj := v_hist_adj || jsonb_build_array(v_meta);

        insert into public.invoice_lines(
          invoice_id, timesheet_id, booking_id, description,
          hours_day, hours_night, hours_sat, hours_sun, hours_bh,
          pay_day, pay_night, pay_sat, pay_sun, pay_bh,
          charge_day, charge_night, charge_sat, charge_sun, charge_bh,
          total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
          vat_rate_pct, vat_amount, total_inc_vat,
          paper_ts_r2_key, meta_json, source_key
        )
        values (
          p_invoice_id, null, null, v_adj_desc,
          0,0,0,0,0,
          null,null,null,null,null,
          null,null,null,null,null,
          0, public._inv_round2(v_adj_ex), public._inv_round2(v_adj_ex),
          v_vat_rate, v_adj_vat, v_adj_inc,
          null,
          v_meta,
          v_adj_source_key
        )
        on conflict (invoice_id, source_key) do nothing;
      end loop;
    end if;
  end if;

  -- History: adjustments added (always)
  if jsonb_typeof(v_hist_adj)='array' and jsonb_array_length(v_hist_adj) > 0 then
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_ADJUSTMENTS_ADDED',
      null,
      jsonb_build_object('adjustments', v_hist_adj),
      null,
      p_actor_user_id
    );
  end if;


  -- 3) Add timesheets (full parity: hours + additional + expenses + mileage), for THIS invoice week_start
  if v_add_ts_ids is not null and coalesce(array_length(v_add_ts_ids,1),0) > 0 then
    foreach tsid in array v_add_ts_ids loop
      if tsid is null then
        continue;
      end if;

      -- Load snapshot + timesheet + precheck
      select
        tf.*,
        tsr.booking_id,
        tsr.week_ending_date,
        tsr.reference_number,
        tsr.sheet_scope::text as sheet_scope,
        coalesce(tsr.submission_mode::text,'') as submission_mode,
        tsr.day_references_json,
        tsr.actual_schedule_json,
        cw.contract_id
      into snap
      from public.timesheets_financials tf
      join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
      left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
      join public.v_ts_invoice_precheck pcv on pcv.timesheet_id = tf.timesheet_id
      where tf.timesheet_id = tsid
        and tf.is_current = true
        and tf.locked_by_invoice_id is null
        and tf.processing_status = 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
        and upper(coalesce(pcv.precheck_status,''))
          in ('OK','BLOCK_NO_PDF')
        and tf.client_id = v_inv.client_id
        and (
          pcv.require_reference_to_invoice is not true
          or public._inv_timesheet_has_invoice_reference(
                tsr.sheet_scope::text,
                coalesce(tsr.submission_mode::text,''),
                tsr.reference_number,
                tsr.day_references_json,
                tsr.actual_schedule_json
             )
        )
      limit 1;

      if not found then
        v_dbg_add_timesheets_skipped := v_dbg_add_timesheets_skipped + 1;
        if v_invoice_debug then
          v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_skipped','timesheet_id',coalesce(tsid::text,'')));
        end if;
        continue;
      end if;

      v_dbg_add_timesheets_found := v_dbg_add_timesheets_found + 1;
      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_loaded','timesheet_id',coalesce(tsid::text,''),'tsfin_id',coalesce(snap.id::text,'')));
      end if;

      select v.r2_key
      into v_exact_timesheet_document_r2_key
      from public.timesheets t
      join public.invoice_document_versions v
        on v.entity_type='TIMESHEET'
       and v.entity_id=t.timesheet_id
       and v.purpose='TIMESHEET'
       and v.source_revision=t.document_revision::text
       and v.status='READY'
       and nullif(v.r2_key,'') is not null
       and nullif(v.sha256,'') is not null
       and coalesce(v.size_bytes,0)>0
       and coalesce(v.page_count,0)>0
      where t.timesheet_id=tsid and t.is_current
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1;
      contract_id := snap.contract_id;
      c_daily_calc := false;
      c_bucket_labels := null;
      c_role := null;
      c_display_site := null;
      c_ward_hint := null;

      if contract_id is not null then
        select
          nullif(btrim(coalesce(role,'')), ''),
          nullif(btrim(coalesce(display_site,'')), ''),
          nullif(btrim(coalesce(ward_hint,'')), '')
        into
          c_role, c_display_site, c_ward_hint
        from public.contracts
        where id = contract_id
        limit 1;
      end if;

      v_settings_authority := private._timesheet_settings_authority_frozen_v1(tsid);
      c_daily_calc := coalesce(
        (v_settings_authority#>>'{values,daily_calc_of_invoices}')::boolean,
        false
      );
      c_bucket_labels := case
        when coalesce((v_settings_authority->>'override_client_settings')::boolean,false)
          then v_settings_authority#>'{values,bucket_labels_json}'
        else null
      end;

      if c_bucket_labels is null then
        c_bucket_labels := jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH');
      end if;

      natural_start := (snap.week_ending_date::date - 6);

      segments := '[]'::jsonb;

      -- Build invoiceable segment set for THIS invoice week_start
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
         and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
      then
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
          if seg_locked is not null then
            continue; -- already invoiced
          end if;

          seg_target := nullif(btrim(coalesce(v_seg->>'invoice_target_week_start','')), '')::date;
          seg_ref := btrim(coalesce(v_seg->>'ref_num',''));

          -- segment-level ref gating if required
          select * into pc from public.v_ts_invoice_precheck where timesheet_id = tsid limit 1;
          if pc.require_reference_to_invoice is true and seg_ref = '' then
            continue;
          end if;

          -- delayed detection
          if seg_target is null or seg_target = natural_start then
            -- not delayed: belongs to natural week only
            if v_week_start <> natural_start then
              continue;
            end if;
            -- allow early is implicit for invoice edits (invoice is already being edited)
            segments := segments || jsonb_build_array(v_seg);
          else
            -- delayed: only if this invoice week matches target AND target has arrived (no early invoicing for delayed)
            if v_week_start = seg_target and seg_target <= v_anchor_ymd then
              segments := segments || jsonb_build_array(v_seg);
            end if;
          end if;
        end loop;
      else
        -- Non-segments: include only when invoice week matches natural week
        if v_week_start = natural_start then
          segments := jsonb_build_array(
            jsonb_build_object(
              'segment_id', null,
              'date', coalesce(snap.week_ending_date::text, v_week_start::text),
              'hours_day', public._inv_round2(coalesce(snap.hours_day,0)),
              'hours_night', public._inv_round2(coalesce(snap.hours_night,0)),
              'hours_sat', public._inv_round2(coalesce(snap.hours_sat,0)),
              'hours_sun', public._inv_round2(coalesce(snap.hours_sun,0)),
              'hours_bh', public._inv_round2(coalesce(snap.hours_bh,0)),
              'pay_amount', public._inv_round2(
                coalesce(snap.total_pay_ex_vat,0)
                - coalesce(snap.additional_pay_ex_vat,0)
                - coalesce(snap.expenses_pay_ex_vat,0)
                - coalesce(snap.mileage_pay_ex_vat,0)
              ),
              'charge_amount', public._inv_round2(
                coalesce(snap.total_charge_ex_vat,0)
                - coalesce(snap.additional_charge_ex_vat,0)
                - coalesce(snap.expenses_charge_ex_vat,0)
                - coalesce(snap.mileage_charge_ex_vat,0)
              ),
              'ref_num', coalesce(snap.reference_number,'')
            )
          );
        end if;
      end if;

      if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
        continue;
      end if;

      -- Build the exact invoice-line economics from the frozen current financial snapshot.
      -- This mirrors Invoice Async V8 generation and never derives economics from mutable live rows.
      select p.vat_rate
      into v_vat_rate
      from private._invoice_generation_vat_policy_batch(jsonb_build_array(jsonb_build_object(
        'source_member_key','invoice-edit:'||tsid::text,
        'source_type','TIMESHEET',
        'source_id',tsid,
        'timesheet_id',tsid,
        'effective_date',snap.week_ending_date
      ))) p
      where p.source_member_key='invoice-edit:'||tsid::text
        and p.valid
        and p.vat_rate is not null
      limit 1;

      if not found then
        raise exception 'INVOICE_EDIT_VAT_POLICY_UNRESOLVED'
          using errcode='P0001',detail=jsonb_build_object(
            'invoice_id',p_invoice_id,'timesheet_id',tsid)::text;
      end if;

      insert into public.invoice_lines(
        invoice_id,timesheet_id,booking_id,description,
        hours_day,hours_night,hours_sat,hours_sun,hours_bh,
        pay_day,pay_night,pay_sat,pay_sun,pay_bh,
        charge_day,charge_night,charge_sat,charge_sun,charge_bh,
        total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,
        vat_rate_pct,vat_amount,total_inc_vat,
        paper_ts_r2_key,meta_json,source_key
      )
      with base as materialized (
        select coalesce(
          (select nullif(btrim(coalesce(cd.display_name,'')),'')
             from public.candidates cd where cd.id=snap.candidate_id limit 1),
          'TS '||tsid::text
        ) candidate_display
      ),
      segment_rows as materialized (
        select
          case when left(coalesce(s.value->>'date',''),10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
            then left(s.value->>'date',10) end work_date,
          case when pg_input_is_valid(s.value->>'hours_day','numeric') then (s.value->>'hours_day')::numeric else 0 end h_day,
          case when pg_input_is_valid(s.value->>'hours_night','numeric') then (s.value->>'hours_night')::numeric else 0 end h_night,
          case when pg_input_is_valid(s.value->>'hours_sat','numeric') then (s.value->>'hours_sat')::numeric else 0 end h_sat,
          case when pg_input_is_valid(s.value->>'hours_sun','numeric') then (s.value->>'hours_sun')::numeric else 0 end h_sun,
          case when pg_input_is_valid(s.value->>'hours_bh','numeric') then (s.value->>'hours_bh')::numeric else 0 end h_bh,
          case
            when pg_input_is_valid(s.value->>'pay_amount','numeric') then (s.value->>'pay_amount')::numeric
            when pg_input_is_valid(s.value->>'pay_ex_vat','numeric') then (s.value->>'pay_ex_vat')::numeric
            else 0 end pay_ex,
          case
            when pg_input_is_valid(s.value->>'charge_amount','numeric') then (s.value->>'charge_amount')::numeric
            when pg_input_is_valid(s.value->>'charge_ex_vat','numeric') then (s.value->>'charge_ex_vat')::numeric
            else 0 end charge_ex
        from jsonb_array_elements(segments) s(value)
      ),
      hour_daily as materialized (
        select s.work_date,sum(s.h_day) h_day,sum(s.h_night) h_night,sum(s.h_sat) h_sat,
          sum(s.h_sun) h_sun,sum(s.h_bh) h_bh,sum(s.pay_ex) pay_ex,sum(s.charge_ex) charge_ex
        from segment_rows s
        where c_daily_calc and s.work_date is not null
        group by s.work_date
      ),
      hour_weekly as materialized (
        select sum(s.h_day) h_day,sum(s.h_night) h_night,sum(s.h_sat) h_sat,
          sum(s.h_sun) h_sun,sum(s.h_bh) h_bh,sum(s.pay_ex) pay_ex,sum(s.charge_ex) charge_ex
        from segment_rows s
        having not c_daily_calc or not exists(select 1 from segment_rows d where d.work_date is not null)
      ),
      additional_source as materialized (
        select upper(a.key) code,a.value unit
        from jsonb_each(case when jsonb_typeof(snap.additional_units_json)='object'
          then snap.additional_units_json else '{}'::jsonb end) a
        where jsonb_typeof(a.value)='object' and btrim(a.key)<>''
      ),
      additional_daily as materialized (
        select a.code,left(d.key,10) work_date,
          case when pg_input_is_valid(d.value,'numeric') then d.value::numeric else 0 end units,
          case when pg_input_is_valid(a.unit->>'pay_rate','numeric') then (a.unit->>'pay_rate')::numeric else 0 end pay_rate,
          case when pg_input_is_valid(a.unit->>'charge_rate','numeric') then (a.unit->>'charge_rate')::numeric else 0 end charge_rate,
          coalesce(nullif(a.unit->>'bucket_name',''),a.code) bucket_name,
          coalesce(nullif(a.unit->>'unit_name',''),'units') unit_name,
          a.unit->'frequency' frequency
        from additional_source a
        cross join lateral jsonb_each_text(case when jsonb_typeof(a.unit->'days')='object'
          then a.unit->'days' else '{}'::jsonb end) d
        where c_daily_calc
          and left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
          and pg_input_is_valid(d.value,'numeric')
          and d.value::numeric<>0
          and exists(select 1 from segment_rows where work_date is not null)
      ),
      additional_weekly as materialized (
        select a.code,
          case when pg_input_is_valid(a.unit->>'unit_count','numeric') then (a.unit->>'unit_count')::numeric else 0 end units,
          case when pg_input_is_valid(a.unit->>'pay_rate','numeric') then (a.unit->>'pay_rate')::numeric else 0 end pay_rate,
          case when pg_input_is_valid(a.unit->>'charge_rate','numeric') then (a.unit->>'charge_rate')::numeric else 0 end charge_rate,
          case when pg_input_is_valid(a.unit->>'pay_ex_vat','numeric') then (a.unit->>'pay_ex_vat')::numeric else 0 end pay_ex,
          case when pg_input_is_valid(a.unit->>'charge_ex_vat','numeric') then (a.unit->>'charge_ex_vat')::numeric else 0 end charge_ex,
          coalesce(nullif(a.unit->>'bucket_name',''),a.code) bucket_name,
          coalesce(nullif(a.unit->>'unit_name',''),'units') unit_name,
          a.unit->'frequency' frequency
        from additional_source a
        where not(c_daily_calc
          and exists(select 1 from jsonb_each_text(case when jsonb_typeof(a.unit->'days')='object'
            then a.unit->'days' else '{}'::jsonb end) d
            where left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(d.value,'numeric') and d.value::numeric<>0))
          and (
            (case when pg_input_is_valid(a.unit->>'pay_ex_vat','numeric') then (a.unit->>'pay_ex_vat')::numeric else 0 end)<>0
            or (case when pg_input_is_valid(a.unit->>'charge_ex_vat','numeric') then (a.unit->>'charge_ex_vat')::numeric else 0 end)<>0
          )
      ),
      expense_lines as materialized (
        select e.code,e.pay_ex,e.charge_ex
        from (values
          ('TRAVEL',coalesce(snap.travel_pay_ex_vat,0),coalesce(snap.travel_charge_ex_vat,0)),
          ('ACCOMMODATION',coalesce(snap.accommodation_pay_ex_vat,0),coalesce(snap.accommodation_charge_ex_vat,0)),
          ('OTHER',coalesce(snap.other_pay_ex_vat,0),coalesce(snap.other_charge_ex_vat,0)),
          ('EXPENSES_FALLBACK',
            case when coalesce(snap.travel_pay_ex_vat,0)+coalesce(snap.accommodation_pay_ex_vat,0)+coalesce(snap.other_pay_ex_vat,0)=0
              then coalesce(snap.expenses_pay_ex_vat,0) else 0 end,
            case when coalesce(snap.travel_charge_ex_vat,0)+coalesce(snap.accommodation_charge_ex_vat,0)+coalesce(snap.other_charge_ex_vat,0)=0
              then coalesce(snap.expenses_charge_ex_vat,0) else 0 end),
          ('MILEAGE',coalesce(snap.mileage_pay_ex_vat,0),coalesce(snap.mileage_charge_ex_vat,0))
        ) e(code,pay_ex,charge_ex)
        where e.pay_ex<>0 or e.charge_ex<>0
      ),
      line_union as materialized (
        select b.candidate_display||' - '||h.work_date||' - W/E '||coalesce(snap.week_ending_date::text,'' ) description,
          h.h_day,h.h_night,h.h_sat,h.h_sun,h.h_bh,h.pay_ex,h.charge_ex,
          'HOURS_DAILY' line_type,'TS:'||tsid::text||':HOURS:'||h.work_date source_key,
          jsonb_build_object('date',h.work_date) detail
        from hour_daily h cross join base b
        union all
        select b.candidate_display||' - W/E '||coalesce(snap.week_ending_date::text,''),
          h.h_day,h.h_night,h.h_sat,h.h_sun,h.h_bh,h.pay_ex,h.charge_ex,
          'HOURS_WEEKLY','TS:'||tsid::text||':HOURS:WEEK','{}'::jsonb
        from hour_weekly h cross join base b
        union all
        select b.candidate_display||' - '||a.bucket_name||' - '||a.work_date||' - '||a.units||' '||a.unit_name,
          0,0,0,0,0,round(a.units*a.pay_rate,2),round(a.units*a.charge_rate,2),
          'ADDITIONAL_RATE_DAILY','TS:'||tsid::text||':ADD:'||a.code||':'||a.work_date,
          jsonb_build_object('date',a.work_date,'bucket',jsonb_build_object(
            'code',a.code,'bucket_name',a.bucket_name,'unit_name',a.unit_name,'frequency',a.frequency),
            'units',jsonb_build_object('unit_count',a.units,'pay_rate',a.pay_rate,'charge_rate',a.charge_rate))
        from additional_daily a cross join base b
        union all
        select b.candidate_display||' - '||a.bucket_name||' - '||a.units||' '||a.unit_name,
          0,0,0,0,0,a.pay_ex,a.charge_ex,
          'ADDITIONAL_RATE','TS:'||tsid::text||':ADD:'||a.code||':WEEK',
          jsonb_build_object('bucket',jsonb_build_object(
            'code',a.code,'bucket_name',a.bucket_name,'unit_name',a.unit_name,'frequency',a.frequency),
            'units',jsonb_build_object('unit_count',a.units,'pay_rate',a.pay_rate,'charge_rate',a.charge_rate))
        from additional_weekly a cross join base b
        union all
        select case when e.code='MILEAGE' then 'Mileage - '||coalesce(snap.mileage_units,0)||' miles (W/E '||coalesce(snap.week_ending_date::text,'')||')'
          when e.code='EXPENSES_FALLBACK' then 'Expenses (W/E '||coalesce(snap.week_ending_date::text,'')||')'
          else initcap(replace(e.code,'_',' '))||' expenses (W/E '||coalesce(snap.week_ending_date::text,'')||')' end,
          0,0,0,0,0,e.pay_ex,e.charge_ex,
          case when e.code='MILEAGE' then 'MILEAGE'
            when e.code='EXPENSES_FALLBACK' then 'EXPENSES_TOTAL'
            else 'EXPENSE_'||e.code end,
          case when e.code='MILEAGE' then 'TS:'||tsid::text||':MILEAGE'
            when e.code='EXPENSES_FALLBACK' then 'TS:'||tsid::text||':EXP:TOTAL'
            else 'TS:'||tsid::text||':EXP:'||e.code end,
          jsonb_build_object('expense',case when e.code='MILEAGE' then jsonb_build_object(
            'category','MILEAGE','mileage_units',snap.mileage_units,
            'pay_rate',snap.mileage_pay_rate,'charge_rate',snap.mileage_charge_rate,
            'evidence_r2_key',snap.mileage_evidence_r2_key,'evidence_manifest',snap.mileage_evidence_manifest)
            else jsonb_build_object('category',e.code,'note',snap.expenses_description,
              'evidence_r2_key',snap.expenses_evidence_r2_key,'evidence_manifest',snap.expenses_evidence_manifest) end)
        from expense_lines e
      )
      select p_invoice_id,tsid,snap.booking_id,l.description,
        round(l.h_day,2),round(l.h_night,2),round(l.h_sat,2),round(l.h_sun,2),round(l.h_bh,2),
        null,null,null,null,null,
        snap.charge_day,snap.charge_night,snap.charge_sat,snap.charge_sun,snap.charge_bh,
        round(l.pay_ex,2),round(l.charge_ex,2),round(l.charge_ex-l.pay_ex,2),v_vat_rate,
        round(l.charge_ex*v_vat_rate/100,2),round(l.charge_ex+(l.charge_ex*v_vat_rate/100),2),
        v_exact_timesheet_document_r2_key,
        jsonb_build_object('line_type',l.line_type,'timesheet_id',tsid,'tsfin_id',snap.id,
          'candidate_display',l.description,'week_ending_date',snap.week_ending_date,
          'role',c_role,'hospital',c_display_site,'ward',c_ward_hint,'bucket_labels',c_bucket_labels,
          'totals',jsonb_build_object('line_pay_ex_vat',round(l.pay_ex,2),
            'line_charge_ex_vat',round(l.charge_ex,2),'margin_ex_vat',round(l.charge_ex-l.pay_ex,2),
            'vat_rate_pct',v_vat_rate,'vat_amount',round(l.charge_ex*v_vat_rate/100,2),
            'total_inc_vat',round(l.charge_ex+(l.charge_ex*v_vat_rate/100),2)))||l.detail,
        l.source_key
      from line_union l
      on conflict(invoice_id,source_key) do nothing;
      -- Build segment refs to lock
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
      then
        for v_seg in
          select value from jsonb_array_elements(segments) value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_refs := seg_refs || jsonb_build_array(
            jsonb_build_object(
              'tsfin_id', snap.id::text,
              'segment_id', nullif(btrim(coalesce(v_seg->>'segment_id','')), '')
            )
          );
        end loop;
      else
        -- lock whole for non-segments
        seg_refs := seg_refs || jsonb_build_array(
          jsonb_build_object('tsfin_id', snap.id::text, 'segment_id', null)
        );
      end if;
    end loop;

    -- Apply segment locks for the exact selected source rows.
    if jsonb_typeof(seg_refs) = 'array' and jsonb_array_length(seg_refs) > 0 then
      perform public._inv_lock_segments_for_invoice(p_invoice_id, seg_refs);
    end if;

    -- History: timesheets added (always; includes requested ids)
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_TIMESHEETS_ADDED',
      null,
      jsonb_build_object('add_timesheet_ids', coalesce(to_jsonb(v_add_ts_ids), '[]'::jsonb)),
      null,
      p_actor_user_id
    );
  end if;

  -- 3c) Contract week status: set INVOICED only when timesheet is FULLY invoiced (segment-aware), and revert INVOICED -> AUTHORISED if no longer fully invoiced.
  -- Touch set = union of: add_timesheet_ids, line-removal touched (hours), segment-op touched.
  v_cw_ts_ids := array[]::uuid[];
  if v_add_ts_ids is not null and coalesce(array_length(v_add_ts_ids,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_add_ts_ids;
  end if;
  if v_ts_ids_touched is not null and coalesce(array_length(v_ts_ids_touched,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_ts_ids_touched;
  end if;
  if v_seg_ts_ids is not null and coalesce(array_length(v_seg_ts_ids,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_seg_ts_ids;
  end if;

  -- de-dup
  select array_agg(distinct x)
  into v_cw_ts_ids
  from unnest(coalesce(v_cw_ts_ids, array[]::uuid[])) x
  where x is not null;

  v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);

  if coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
    with src as (
      select
        cw.timesheet_id,
        cw.status as cw_status,
        tf.locked_by_invoice_id,
        tf.invoice_breakdown_json,
        (
          case
            when tf.invoice_breakdown_json is not null
             and jsonb_typeof(tf.invoice_breakdown_json)='object'
             and coalesce(tf.invoice_breakdown_json->>'mode','')='SEGMENTS'
             and jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
             and jsonb_array_length(tf.invoice_breakdown_json->'segments') > 0
            then
              not exists (
                select 1
                from jsonb_array_elements(tf.invoice_breakdown_json->'segments') s(seg)
                where nullif(btrim(coalesce(s.seg->>'invoice_locked_invoice_id','')), '') is null
              )
            else
              (tf.locked_by_invoice_id is not null)
          end
        ) as fully_invoiced
      from public.contract_weeks cw
      join public.timesheets_financials tf
        on tf.is_current = true
       and tf.timesheet_id = cw.timesheet_id
      where cw.timesheet_id = any(v_cw_ts_ids)
    )
    update public.contract_weeks cw
    set status = case
      when src.fully_invoiced then 'INVOICED'::public.contract_week_status_enum
      when cw.status = 'INVOICED'::public.contract_week_status_enum then 'AUTHORISED'::public.contract_week_status_enum
      else cw.status
    end
    from src
    where cw.timesheet_id = src.timesheet_id;
  end if;


  -- 4) Recompute invoice totals from invoice_lines and clear PDF key
  select
    public._inv_round2(coalesce(sum(coalesce(l.total_charge_ex_vat,0)),0)),
    public._inv_round2(coalesce(sum(coalesce(l.vat_amount,0)),0)),
    public._inv_round2(coalesce(sum(coalesce(l.total_inc_vat,0)),0))
  into v_new_ex, v_new_vat, v_new_inc
  from public.invoice_lines l
  where l.invoice_id = p_invoice_id;


  perform public.invoice_recompute_totals(p_invoice_id);

  -- Recompute header_snapshot_json.meta counters to avoid stale values after edits
  select count(distinct l.timesheet_id)
  into v_hdr_ts_count_lines
  from public.invoice_lines l
  where l.invoice_id = p_invoice_id
    and l.timesheet_id is not null;

  select count(*)
  into v_hdr_seg_locked_count
  from public.timesheets_financials tf
  cross join lateral jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) as seg(seg_obj)
  where tf.is_current = true
    and coalesce(seg.seg_obj->>'invoice_locked_invoice_id','') = p_invoice_id::text;

  select count(distinct tf.timesheet_id)
  into v_hdr_ts_count_seglocks
  from public.timesheets_financials tf
  where tf.is_current = true
    and exists (
      select 1
      from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) as seg(seg_obj)
      where coalesce(seg.seg_obj->>'invoice_locked_invoice_id','') = p_invoice_id::text
    );

  if coalesce(v_hdr_seg_locked_count,0) > 0 then
    v_hdr_meta_timesheet_count := coalesce(v_hdr_ts_count_seglocks,0);
    v_hdr_meta_segment_count := coalesce(v_hdr_seg_locked_count,0);
  else
    v_hdr_meta_timesheet_count := coalesce(v_hdr_ts_count_lines,0);
    v_hdr_meta_segment_count := coalesce(v_hdr_meta_timesheet_count,0);
  end if;

  -- The statement triggers are the sole document/issue invalidation authority.
  -- This update changes only the authoritative business snapshot counters.
  update public.invoices invu
  set header_snapshot_json=jsonb_set(jsonb_set(coalesce(invu.header_snapshot_json,'{}'::jsonb),
      '{meta,timesheet_count}',to_jsonb(v_hdr_meta_timesheet_count),true),
      '{meta,segment_count}',to_jsonb(v_hdr_meta_segment_count),true),
    updated_at=now()
  where invu.id=p_invoice_id;

-- Refresh invoice-level NHSP/HR cache after timesheet/segment changes
  if coalesce(v_refresh_hr_cache,false) = true then
    perform 1
    from public.invoice_source_rows_collect(p_invoice_id, true) sr
    limit 1;
  end if;

  -- Revalidate ownership after every line and segment move in this Save. A
  -- source edit must not queue work for a source that was detached later in the
  -- same transaction, and every edited SEGMENTS identity must still be locked
  -- to this exact invoice.
  if cardinality(v_source_changed_ts_ids)>0 and exists(
    select 1
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_id')::uuid=any(v_source_changed_ts_ids)
      and not exists(
        select 1 from public.invoice_lines carrier
        where carrier.invoice_id=p_invoice_id
          and (
            carrier.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              carrier.timesheet_id is null
              and coalesce(carrier.meta_json->>'timesheet_id','')~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (carrier.meta_json->>'timesheet_id')::uuid=
                (desired.value->>'timesheet_id')::uuid
            )
          )
      )
      and not exists(
        select 1
        from public.timesheets_financials tf
        cross join lateral jsonb_array_elements(
          coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) seg(value)
        where tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
          and tf.is_current
          and nullif(btrim(coalesce(
            seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
      )
  ) then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND',
      detail=jsonb_build_object('reason','POST_EDIT_SOURCE_DETACHED')::text;
  end if;

  if cardinality(v_source_changed_ts_ids)>0 and exists(
    select 1
    from jsonb_each(v_source_updates_map) desired
    cross join lateral jsonb_array_elements(
      coalesce(desired.value->'segment_updates','[]'::jsonb)) requested(value)
    where desired.value->>'source_mode'='SEGMENTS'
      and not exists(
        select 1
        from public.timesheets_financials tf
        cross join lateral jsonb_array_elements(
          coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) seg(value)
        where tf.id=(desired.value->>'financial_id')::uuid
          and tf.is_current
          and tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
          and nullif(btrim(coalesce(
            seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
          and (
            (
              nullif(requested.value->>'segment_id','') is not null
              and nullif(btrim(coalesce(seg.value->>'segment_id','')),'')
                =nullif(requested.value->>'segment_id','')
            ) or (
              nullif(requested.value->>'segment_id','') is null
              and coalesce(seg.value->>'start_utc',seg.value->>'start')
                is not distinct from requested.value->>'start_identity'
              and coalesce(seg.value->>'end_utc',seg.value->>'end')
                is not distinct from requested.value->>'end_identity'
            )
          )
      )
  ) then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND',
      detail=jsonb_build_object('reason','POST_EDIT_SEGMENT_DETACHED')::text;
  end if;

  -- A material source edit always starts or reuses the exact replacement
  -- timesheet work. Replacement of an existing invoice preview is derived from
  -- the locked pre-edit V8 state; browser flags cannot suppress it.
  if cardinality(v_source_changed_ts_ids)>0 then
    select coalesce(jsonb_agg(jsonb_build_object(
      'command_type','VIEW_TIMESHEET_DOCUMENT',
      'timesheet_id',changed_id,
      'purpose','TIMESHEET',
      'priority_reason','SOURCE_EDIT_REPLACEMENT',
      'template_version','timesheet-professional-v2')
      order by changed_id),'[]'::jsonb)
    into v_document_commands
    from unnest(v_source_changed_ts_ids) changed_id;

    v_source_edit_invoice_replacement_required:=
      v_source_edit_preexisting_preview
      or lower(coalesce(p_payload->>'request_preview','false'))
           in('true','1','yes','on');
    if v_source_edit_invoice_replacement_required then
      v_document_commands:=v_document_commands||jsonb_build_array(
        jsonb_build_object(
          'command_type','VIEW_INVOICE_DOCUMENT',
          'invoice_id',p_invoice_id,
          'purpose','DRAFT_PREVIEW',
          'priority_reason',case when v_source_edit_preexisting_preview
            then 'SOURCE_EDIT_REPLACEMENT' else 'VIEW_NOW' end,
          'template_version','invoice-professional-v2'));
    end if;

    v_expected_command_count:=jsonb_array_length(v_document_commands);
    if v_expected_command_count>1000 then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_TOO_MANY_REPLACEMENTS';
    end if;

    v_started_operations:=public.invoice_operation_start_batch(
      v_document_commands,p_actor_user_id,v_now);

    if jsonb_typeof(v_started_operations)<>'array'
       or jsonb_array_length(v_started_operations)<>v_expected_command_count then
      raise exception using errcode='55000',
        message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
        detail=jsonb_build_object(
          'reason','RESULT_COUNT',
          'expected',v_expected_command_count,
          'actual',case when jsonb_typeof(v_started_operations)='array'
            then jsonb_array_length(v_started_operations) else null end)::text;
    end if;

    for v_command_no in 1..v_expected_command_count loop
      select value into v_operation_result
      from jsonb_array_elements(v_started_operations) value
      where coalesce(value->>'command_no','')~'^[1-9][0-9]*$'
        and (value->>'command_no')::int=v_command_no;

      if not found or (
        select count(*)
        from jsonb_array_elements(v_started_operations) value
        where coalesce(value->>'command_no','')~'^[1-9][0-9]*$'
          and (value->>'command_no')::int=v_command_no
      )<>1 then
        raise exception using errcode='55000',
          message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
          detail=jsonb_build_object('reason','COMMAND_NO','command_no',v_command_no)::text;
      end if;

      v_source_update:=v_document_commands->(v_command_no-1);
      v_command_type:=v_source_update->>'command_type';
      if v_operation_result->>'command_type' is distinct from v_command_type
         or lower(coalesce(v_operation_result->>'accepted','false'))
              not in('true','1','yes','on')
         or lower(coalesce(v_operation_result->>'blocked','false'))
              in('true','1','yes','on') then
        raise exception using errcode='55000',
          message=case
            when lower(coalesce(v_operation_result->>'blocked','false'))
                   in('true','1','yes','on')
              then 'SOURCE_EDIT_REPLACEMENT_BLOCKED'
            else 'SOURCE_EDIT_REPLACEMENT_REJECTED' end,
          detail=jsonb_build_object(
            'command_no',v_command_no,
            'terminal_error',v_operation_result->'terminal_error')::text;
      end if;

      v_operation_status:=upper(coalesce(v_operation_result->>'status',''));
      v_operation_id:=case when coalesce(v_operation_result->>'operation_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (v_operation_result->>'operation_id')::uuid end;
      v_document_version_id:=case when coalesce(v_operation_result->>'document_version_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (v_operation_result->>'document_version_id')::uuid end;

      if v_operation_status='READY' then
        if v_document_version_id is null or v_operation_id is not null
           or not exists(
             select 1
             from public.invoice_document_versions dv
             where dv.id=v_document_version_id
               and dv.entity_type=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'INVOICE' end
               and dv.entity_id=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (v_source_update->>'timesheet_id')::uuid else p_invoice_id end
               and dv.purpose=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'DRAFT_PREVIEW' end
               and dv.source_revision=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (
                   select t.document_revision::text from public.timesheets t
                   where t.timesheet_id=(v_source_update->>'timesheet_id')::uuid
                     and t.is_current)
                 else (
                   select i.document_revision::text from public.invoices i
                   where i.id=p_invoice_id)
                 end
               and dv.template_version=v_source_update->>'template_version'
               and dv.status='READY'
               and nullif(btrim(coalesce(dv.r2_key,'')),'') is not null
               and nullif(btrim(coalesce(dv.sha256,'')),'') is not null
               and coalesce(dv.size_bytes,0)>0
               and coalesce(dv.page_count,0)>0
           ) then
          raise exception using errcode='55000',
            message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
            detail=jsonb_build_object(
              'reason','READY_IDENTITY','command_no',v_command_no)::text;
        end if;
      else
        if v_operation_id is null
           or v_operation_status not in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
           or not exists(
             select 1
             from public.invoice_operations op
             where op.id=v_operation_id
               and op.operation_type='BUILD_DOCUMENT'
               and op.entity_type=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'INVOICE' end
               and op.entity_id=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (v_source_update->>'timesheet_id')::uuid else p_invoice_id end
               and op.source_revision=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (
                   select t.document_revision::text from public.timesheets t
                   where t.timesheet_id=(v_source_update->>'timesheet_id')::uuid
                     and t.is_current)
                 else (
                   select i.document_revision::text from public.invoices i
                   where i.id=p_invoice_id)
                 end
               and op.template_version=v_source_update->>'template_version'
               and coalesce(op.input_json->>'purpose','')=
                 case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                   then 'TIMESHEET' else 'DRAFT_PREVIEW' end
               and op.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
           ) then
          raise exception using errcode='55000',
            message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
            detail=jsonb_build_object(
              'reason','ACTIVE_IDENTITY','command_no',v_command_no)::text;
        end if;
      end if;

      v_validated_operations:=v_validated_operations||jsonb_build_array(v_operation_result);
    end loop;

    select coalesce(jsonb_agg(jsonb_build_object(
      'timesheet_id',t.timesheet_id,
      'document_revision',t.document_revision)
      order by t.timesheet_id),'[]'::jsonb)
    into v_source_changed_revisions
    from public.timesheets t
    where t.timesheet_id=any(v_source_changed_ts_ids) and t.is_current;
  end if;

-- Return compact state only; never build a manifest or PDF here.
  select jsonb_build_object('invoice_id',i.id,'status',i.status,
    'subtotal_ex_vat',i.subtotal_ex_vat,'vat_amount',i.vat_amount,'total_inc_vat',i.total_inc_vat,
    'document_revision',i.document_revision,'document_state',i.document_state,
    'preview_document_version_id',i.preview_document_version_id,
    'active_document_operation_id',i.active_document_operation_id,
    'issue_state',i.issue_state,'active_issue_operation_id',i.active_issue_operation_id,
    'reference_updates_applied',v_refupd_applied,
    'timesheet_location_updates_applied',v_location_applied,
    'timesheet_source_changed',
      cardinality(v_source_changed_ts_ids)>0,
    'source_edit_queue_contract',case when v_source_edit_requested
      then 'INVOICE_SOURCE_EDIT_QUEUE_V1' else null end,
    'changed_timesheet_ids',coalesce(to_jsonb(v_source_changed_ts_ids),'[]'::jsonb),
    'changed_timesheet_revisions',coalesce(v_source_changed_revisions,'[]'::jsonb),
    'source_edit_preexisting_preview',v_source_edit_preexisting_preview,
    'invoice_replacement_required',v_source_edit_invoice_replacement_required,
    'accepted_operations',coalesce(v_validated_operations,'[]'::jsonb),
    'document_queue_requested',jsonb_array_length(v_document_commands)>0)
  into v_manifest from public.invoices i where i.id=p_invoice_id;

  if v_invoice_debug then
    begin
      -- attach finish marker (avoid extra heavy queries here)
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','finish',
          'at_utc', public._inv_iso_utc(now()),
          'invoice_total_charge_ex_vat', v_new_ex,
          'invoice_vat_amount', v_new_vat,
          'invoice_total_inc_vat', v_new_inc
        )
      );

      v_dbg_stats := v_dbg_stats || jsonb_build_object(
        'lines_deleted', v_dbg_lines_deleted,
        'timesheets_unlocked_via_line_removal', v_dbg_timesheets_unlocked,
        'segment_add_refs', v_dbg_seg_add_refs,
        'segment_remove_refs', v_dbg_seg_remove_refs,
        'segment_tsfin_count', v_dbg_seg_tsfins,
        'segment_timesheets_rebuilt', v_dbg_seg_timesheets_rebuilt,
        'segment_timesheets_removed', v_dbg_seg_timesheets_removed,
        'add_timesheets_found', v_dbg_add_timesheets_found,
        'add_timesheets_skipped', v_dbg_add_timesheets_skipped
      );

      perform public._inv_write_audit(
        p_actor_user_id,
        'INVOICE_APPLY_EDITS_DEBUG',
        jsonb_build_object(
          'invoice_id', p_invoice_id::text,
          'week_start', v_week_start::text,
          'week_end', v_week_end::text,
          'stats', v_dbg_stats,
          'steps', v_dbg_steps
        ),
        'invoices',
        p_invoice_id::text,
        null,
        'INVOICE_DEBUG',
        null, null, null
      );
    exception when others then
      null;
    end;
  end if;

  perform public._ctms_assert_invoice_correction_lines_v1(
    p_invoice_id,p_actor_user_id,false,'INVOICE_APPLY_EDITS_RESULT'
  );

  IF v_correction_placement_ts_id IS NOT NULL THEN
    v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
      v_correction_placement_ts_id,null::uuid,p_actor_user_id,false,100);
    IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
       OR v_correction_placement_scope->>'placement_state' NOT IN (
         'COMPLETE_SAME_INVOICE','COMPLETE_SPLIT_INVOICES','INCOMPLETE_MOVE','UNPLACED') THEN
      RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_RESULT_INVALID'
        USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
    END IF;
    v_correction_placement_states:=jsonb_build_array(jsonb_build_object(
      'correction_id',v_correction_placement_scope->>'correction_id',
      'pair_timesheet_ids',v_correction_placement_scope->'pair_timesheet_ids',
      'placement_state',v_correction_placement_scope->>'placement_state',
      'missing_member_kind',v_correction_placement_scope->>'missing_member_kind',
      'placement_invoices',v_correction_placement_scope->'placement_invoices'));
    v_manifest:=v_manifest||jsonb_build_object(
      'correction_pair_placement_states',v_correction_placement_states);
  END IF;

  return v_manifest;

exception when others then
  v_dbg_sqlstate := SQLSTATE;
  v_dbg_error := SQLERRM;

  if v_invoice_debug then
    begin
      perform public._inv_write_audit(
        p_actor_user_id,
        'INVOICE_APPLY_EDITS_ERROR',
        jsonb_build_object(
          'invoice_id', coalesce(p_invoice_id::text,''),
          'sqlstate', v_dbg_sqlstate,
          'error', v_dbg_error,
          'stats', v_dbg_stats,
          'steps', v_dbg_steps
        ),
        'invoices',
        coalesce(p_invoice_id::text,''),
        null,
        'INVOICE_DEBUG',
        null, null, null
      );
    exception when others then
      null;
    end;
  end if;

  raise;
end;
$function$;

revoke all on function public.invoice_apply_edits(uuid,jsonb,uuid)
  from public,anon,authenticated,service_role,supabase_admin;
grant execute on function public.invoice_apply_edits(uuid,jsonb,uuid)
  to CURRENT_USER,service_role;

create or replace function public.invoice_detail_get(
  p_invoice_id uuid,
  p_actor_user_id uuid
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_role text;
  v_service boolean:=coalesce(auth.role(),'')='service_role';
  v_result jsonb;
begin
  if p_invoice_id is null then
    raise exception using errcode='22023',message='invoice_id is required';
  end if;
  if not v_service
     and(auth.uid() is null or auth.uid() is distinct from p_actor_user_id) then
    raise exception using errcode='42501',message='Authenticated actor mismatch';
  end if;

  select lower(btrim(coalesce(u.role,''))) into v_role
  from public.tms_users u
  where u.id=p_actor_user_id and u.is_active;
  if(not found or v_role<>'admin') and not v_service then
    raise exception using errcode='42501',
      message='Invoice administrator permission required';
  end if;

  if not exists(select 1 from public.invoices i where i.id=p_invoice_id) then
    return jsonb_build_object('ok',false,'error_code','INVOICE_NOT_FOUND');
  end if;

  with
  inv as materialized (
    select i.* from public.invoices i where i.id=p_invoice_id
  ),
  lines as materialized (
    select l.*,td.r2_key exact_timesheet_document_r2_key,
      pc.precheck_status,pc.has_timesheet_evidence_pdf
    from public.invoice_lines l
    left join public.timesheets t
      on t.timesheet_id=l.timesheet_id and t.is_current
    left join lateral (
      select v.r2_key
      from public.invoice_document_versions v
      where v.entity_type='TIMESHEET'
        and v.entity_id=t.timesheet_id
        and v.purpose='TIMESHEET'
        and v.source_revision=t.document_revision::text
        and v.status='READY'
        and nullif(v.r2_key,'') is not null
        and nullif(v.sha256,'') is not null
        and coalesce(v.size_bytes,0)>0
        and coalesce(v.page_count,0)>0
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1
    ) td on true
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=l.timesheet_id
    where l.invoice_id=p_invoice_id
  ),
  source_timesheets as materialized (
    select distinct x.timesheet_id
    from (
      select l.timesheet_id from lines l where l.timesheet_id is not null
      union
      select case when coalesce(l.meta_json->>'timesheet_id','')~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (l.meta_json->>'timesheet_id')::uuid end
      from lines l
      where l.timesheet_id is null
    ) x
    where x.timesheet_id is not null
  ),
  references_batch as materialized (
    select r.*
    from private._invoice_reference_rows_batch(array[p_invoice_id]) r
  ),
  reference_rows as materialized (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'row_key',r.row_key,'timesheet_id',r.timesheet_id,
        'candidate_id',coalesce(ct.candidate_id,tf.candidate_id),
         'candidate_display',coalesce(nullif(btrim(cc.display_name),''),
           nullif(btrim(cf.display_name),'')),
         'week_ending_date',t.week_ending_date,
         'document_revision',t.document_revision,
         'sheet_scope',r.sheet_scope,'submission_mode',r.submission_mode,
        'ref_target',r.ref_target,'segment_id',r.segment_id,
        'day_ymd',r.day_ymd,'start_utc',r.start_utc,'end_utc',r.end_utc,
        'current_reference',r.current_reference,'is_required',r.is_required)
      order by r.timesheet_id,r.day_ymd nulls last,r.start_utc nulls last,
        r.segment_id nulls last),'[]'::jsonb) rows
    from references_batch r
    left join public.timesheets t
      on t.timesheet_id=r.timesheet_id and t.is_current
    left join public.contracts ct on ct.id=t.contract_id
    left join public.timesheets_financials tf
      on tf.timesheet_id=r.timesheet_id and tf.is_current
    left join public.candidates cc on cc.id=ct.candidate_id
    left join public.candidates cf on cf.id=tf.candidate_id
  ),
  current_financials as materialized (
    select distinct on (tf.timesheet_id) tf.*
    from public.timesheets_financials tf
    join source_timesheets s on s.timesheet_id=tf.timesheet_id
    where tf.is_current
    order by tf.timesheet_id,tf.updated_at desc nulls last,tf.created_at desc nulls last,tf.id desc
  ),
  reference_sources as materialized (
    select coalesce(jsonb_object_agg(t.timesheet_id::text,
       jsonb_build_object(
         'candidate_id',coalesce(ct.candidate_id,f.candidate_id),
         'candidate_display',coalesce(nullif(btrim(cc.display_name),''),
           nullif(btrim(cf.display_name),'')),
         'week_ending_date',t.week_ending_date,
         'document_revision',t.document_revision,
         'reference_number',t.reference_number,
         'hospital_norm',t.hospital_norm,
         'ward_norm',t.ward_norm,
         'source_mode',upper(coalesce(f.invoice_breakdown_json->>'mode','')),
         'day_references_json',t.day_references_json,
        'actual_schedule_json',case
          when upper(coalesce(f.invoice_breakdown_json->>'mode',''))='SEGMENTS'
            and jsonb_typeof(f.invoice_breakdown_json->'segments')='array'
          then coalesce((
            select jsonb_agg(jsonb_build_object(
              'segment_id',seg.value->>'segment_id',
              'date',seg.value->>'date',
              'start_utc',seg.value->>'start_utc',
              'end_utc',seg.value->>'end_utc',
              'start',seg.value->>'start_utc',
              'end',seg.value->>'end_utc',
              'ref_num',seg.value->>'ref_num',
              'source_system',seg.value->>'source_system')
              order by coalesce(seg.value->>'date',''),
                coalesce(seg.value->>'start_utc',''),
                coalesce(seg.value->>'segment_id',''))
            from jsonb_array_elements(f.invoice_breakdown_json->'segments') seg(value)
            where nullif(btrim(coalesce(
              seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
          ),'[]'::jsonb)
          when jsonb_typeof(t.actual_schedule_json)='array'
            then t.actual_schedule_json
          else '[]'::jsonb end)
      order by t.timesheet_id),'{}'::jsonb) rows
     from source_timesheets s
     join public.timesheets t on t.timesheet_id=s.timesheet_id and t.is_current
     left join current_financials f on f.timesheet_id=t.timesheet_id
     left join public.contracts ct on ct.id=t.contract_id
     left join public.candidates cc on cc.id=ct.candidate_id
     left join public.candidates cf on cf.id=f.candidate_id
   ),
  line_totals as materialized (
    select count(*)::integer line_count,
      round(coalesce(sum(l.total_charge_ex_vat),0),2) net,
      round(coalesce(sum(l.vat_amount),0),2) vat,
      round(coalesce(sum(l.total_inc_vat),0),2) gross
    from lines l
  ),
  timesheet_readiness as materialized (
    select t.timesheet_id,t.submission_mode,t.document_state,
      t.current_document_version_id,t.manual_document_asset_id,
      summary.client_no_timesheet_required,summary.client_is_nhsp,
      case
        when coalesce(summary.client_no_timesheet_required,false)
          or coalesce(summary.client_is_nhsp,false) then true
        else dv.status='READY'
      end ready,
      case
        when coalesce(summary.client_no_timesheet_required,false) then 'NOT_REQUIRED'
        when coalesce(summary.client_is_nhsp,false) then 'NHSP_SUPPORT'
        when upper(coalesce(t.submission_mode::text,'')) in('MANUAL','QR')
          then 'MANUAL_TIMESHEET'
        else 'ELECTRONIC_TIMESHEET'
      end support_type,
      coalesce(dv.page_count,0) pages
    from source_timesheets s
    left join public.timesheets t
      on t.timesheet_id=s.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base summary
      on summary.timesheet_id=s.timesheet_id
    left join lateral (
      select v.status,v.page_count
      from public.invoice_document_versions v
      where v.entity_type='TIMESHEET'
        and v.entity_id=t.timesheet_id
        and v.purpose='TIMESHEET'
        and v.source_revision=t.document_revision::text
        and v.status='READY'
        and nullif(v.r2_key,'') is not null
        and nullif(v.sha256,'') is not null
        and coalesce(v.size_bytes,0)>0
        and coalesce(v.page_count,0)>0
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1
    ) dv on true
  ),
  evidence_rows as materialized (
    select e.id,e.timesheet_id,e.kind,e.document_role,e.candidate_component_id,
      e.display_name,e.storage_key,e.created_at,
      e.document_asset_id,e.processing_state,e.processing_error_json,
      a.status asset_status,a.normalised_r2_key,a.normalised_sha256,
      a.normalised_size_bytes,a.normalised_page_count,
      case when e.document_asset_id is null then 'NOT_REGISTERED'
        when a.status='READY' then 'READY'
        when a.status in('UNSUPPORTED','CORRUPT','MISSING','FAILED') then 'FAILED'
        else 'NOT_READY' end readiness
    from public.timesheet_evidence e
    join source_timesheets s on s.timesheet_id=e.timesheet_id
    left join public.invoice_document_assets a on a.id=e.document_asset_id
  ),
  segment_stats as materialized (
    select f.timesheet_id,f.id tsfin_id,
      coalesce(jsonb_agg(seg.value order by coalesce(seg.value->>'date',''),
        coalesce(seg.value->>'segment_id','')) filter(
          where nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'')
            =p_invoice_id::text),'[]'::jsonb) invoiced_segments,
      count(*) filter(where nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'') is null)
        ::integer uninvoiced_segment_count,
      count(*) filter(where nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'') is not null
        and nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'')<>p_invoice_id::text)
        ::integer locked_elsewhere_segment_count
    from current_financials f
    cross join lateral jsonb_array_elements(
      case when upper(coalesce(f.invoice_breakdown_json->>'mode',''))='SEGMENTS'
          and jsonb_typeof(f.invoice_breakdown_json->'segments')='array'
        then f.invoice_breakdown_json->'segments' else '[]'::jsonb end) seg(value)
    group by f.timesheet_id,f.id
  ),
  segment_projection as materialized (
    select coalesce(jsonb_object_agg(s.timesheet_id::text,jsonb_build_object(
      'tsfin_id',s.tsfin_id,'invoiced_segments',s.invoiced_segments,
      'uninvoiced_segment_count',s.uninvoiced_segment_count,
      'locked_elsewhere_segment_count',s.locked_elsewhere_segment_count)
      order by s.timesheet_id),'{}'::jsonb) rows
    from segment_stats s
  ),
  history_audit as materialized (
    select jsonb_build_object(
      'kind','AUDIT','id',ae.id,'ts_utc',ae.ts_utc,
      'actor_user_id',ae.actor_user_id,
      'actor_display',coalesce(ae.actor_display,u.display_name,u.email,'CloudTMS server'),
      'actor_role_at_time',coalesce(ae.actor_role_at_time,u.role,'system'),
      'action',ae.action,'reason',ae.reason,'object_type',ae.object_type,
      'object_id_text',ae.object_id_text,'before_json',ae.before_json,
      'after_json',ae.after_json,'correlation_id',ae.correlation_id) row_json,
      ae.ts_utc
    from public.audit_events ae
    left join public.tms_users u on u.id=ae.actor_user_id
    where ae.object_type in('invoice','invoices')
      and ae.object_id_text=p_invoice_id::text
    order by ae.ts_utc desc,ae.id desc limit 500
  ),
  invoice_mail as materialized (
    select m.*,jsonb_build_object(
      'kind','EMAIL','mail_outbox_id',m.id,'ts_utc',m.created_at_utc,
      'status',m.status,'to',m."to",'cc',m.cc,'subject',m.subject,
      'reference',m.reference,'sent_at',m.sent_at,'failed_at',m.failed_at) row_json
    from public.mail_outbox m
    where upper(coalesce(m.type,''))='INVOICE'
      and jsonb_typeof(m.attachments)='array'
      and exists(
        select 1 from jsonb_array_elements(m.attachments) a(value)
        where a.value->>'invoice_id'=p_invoice_id::text
          or a.value->>'document_version_id'=(
            select i.issued_document_version_id::text from inv i))
    order by m.created_at_utc desc,m.id desc limit 200
  ),
  history_projection as materialized (
    select coalesce(jsonb_agg(x.row_json order by x.ts_utc desc),'[]'::jsonb) rows
    from (
      select h.row_json,h.ts_utc from history_audit h
      union all
      select m.row_json,m.created_at_utc from invoice_mail m
    ) x
  ),
  current_documents as materialized (
    select
      coalesce((
        select jsonb_build_object(
          'id',v.id,'operation_id',v.operation_id,'purpose',v.purpose,
          'source_revision',v.source_revision,'template_version',v.template_version,
          'status',v.status,'r2_key',v.r2_key,'sha256',v.sha256,
          'size_bytes',v.size_bytes,'page_count',v.page_count,
          'created_at_utc',v.created_at_utc,'ready_at_utc',v.ready_at_utc,
          'verified_at_utc',v.verified_at_utc,'error',v.error_json)
        from public.invoice_document_versions v
        join inv i on i.preview_document_version_id=v.id
        where v.entity_type='INVOICE' and v.entity_id=p_invoice_id
          and v.purpose='DRAFT_PREVIEW'),'null'::jsonb) preview,
      coalesce((
        select jsonb_build_object(
          'id',v.id,'operation_id',v.operation_id,'purpose',v.purpose,
          'source_revision',v.source_revision,'template_version',v.template_version,
          'status',v.status,'r2_key',v.r2_key,'sha256',v.sha256,
          'size_bytes',v.size_bytes,'page_count',v.page_count,
          'created_at_utc',v.created_at_utc,'ready_at_utc',v.ready_at_utc,
          'verified_at_utc',v.verified_at_utc,'error',v.error_json)
        from public.invoice_document_versions v
        join inv i on i.issued_document_version_id=v.id
        where v.entity_type='INVOICE' and v.entity_id=p_invoice_id
          and v.purpose='FINAL_ISSUE'),'null'::jsonb) issued,
      coalesce((
        select jsonb_build_object(
          'id',v.id,'operation_id',v.operation_id,'purpose',v.purpose,
          'source_revision',v.source_revision,'template_version',v.template_version,
          'status',v.status,'r2_key',v.r2_key,'sha256',v.sha256,
          'size_bytes',v.size_bytes,'page_count',v.page_count,
          'created_at_utc',v.created_at_utc,'ready_at_utc',v.ready_at_utc,
          'verified_at_utc',v.verified_at_utc,'error',v.error_json)
        from public.invoice_document_versions v
        where v.entity_type='INVOICE' and v.entity_id=p_invoice_id
        order by v.created_at_utc desc,v.id desc limit 1),'null'::jsonb) latest
  ),
  active_document as materialized (
    select o.id operation_id,o.status,o.phase,o.progress_json,o.error_json,o.change_seq
    from public.invoice_operations o
    join inv i on i.active_document_operation_id=o.id
  ),
  active_issue as materialized (
    select c.operation_id,c.id chunk_id,c.status,c.phase,c.progress_json,c.error_json,
      o.change_seq
    from public.invoice_operation_chunks c
    join public.invoice_operations o on o.id=c.operation_id
    where c.chunk_type='ISSUE_INVOICE' and c.entity_type='INVOICE'
      and c.entity_id=p_invoice_id
      and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
     order by c.updated_at_utc desc,c.id desc limit 1
  ),
  source_edit_authority as materialized (
    select
      (
        i.status in('DRAFT','ON_HOLD')
        and i.issued_at_utc is null
        and i.paid_at_utc is null
        and i.active_issue_operation_id is null
        and upper(coalesce(i.issue_state,'')) not in(
          'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
        and not exists(select 1 from active_issue)
        and not exists(
          select 1
          from source_timesheets s
          where coalesce((
            public._ctms_import_correction_classify_v1(s.timesheet_id)
              ->>'is_import_authoritative_correction')::boolean,false)
        )
      ) can_edit_source,
      coalesce((
        select jsonb_agg(code order by ordinal)
        from (
          values
            (1,case when i.status not in('DRAFT','ON_HOLD')
              then 'INVOICE_SOURCE_EDIT_STATUS_FORBIDDEN' end),
            (2,case when i.issued_at_utc is not null
              then 'INVOICE_SOURCE_EDIT_ISSUED' end),
            (3,case when i.paid_at_utc is not null
              then 'INVOICE_SOURCE_EDIT_PAID' end),
            (4,case when i.active_issue_operation_id is not null
              or upper(coalesce(i.issue_state,'')) in(
                'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
              or exists(select 1 from active_issue)
              then 'INVOICE_SOURCE_EDIT_ISSUE_IN_PROGRESS' end),
            (5,case when exists(
              select 1
              from source_timesheets s
              where coalesce((
                public._ctms_import_correction_classify_v1(s.timesheet_id)
                  ->>'is_import_authoritative_correction')::boolean,false))
              then 'IMPORT_AUTHORITATIVE_CORRECTION_SOURCE_EDIT_FORBIDDEN' end)
        ) blockers(ordinal,code)
        where code is not null
      ),'[]'::jsonb) source_edit_blocker_codes,
      exists(
        select 1
        from public.invoice_document_versions dv
        left join public.invoice_operations op on op.id=dv.operation_id
        where dv.entity_type='INVOICE'
          and dv.entity_id=i.id
          and dv.purpose='DRAFT_PREVIEW'
          and dv.source_revision=i.document_revision::text
          and (
            (dv.status='READY'
              and nullif(btrim(coalesce(dv.r2_key,'')),'') is not null
              and nullif(btrim(coalesce(dv.sha256,'')),'') is not null
              and coalesce(dv.size_bytes,0)>0
              and coalesce(dv.page_count,0)>0)
            or (
              dv.id=i.preview_document_version_id
              and dv.status in(
                'PLANNING','WAITING_FOR_INPUTS','RENDERING',
                'ASSEMBLING','VERIFYING','READY'))
            or (
              dv.operation_id=i.active_document_operation_id
              and op.operation_type='BUILD_DOCUMENT'
              and op.entity_type='INVOICE'
              and op.entity_id=i.id
              and op.source_revision=i.document_revision::text
              and coalesce(op.input_json->>'purpose','')='DRAFT_PREVIEW'
              and op.status in(
                'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
          )
      ) source_edit_will_replace_preview
    from inv i
  ),
  issue_validation as materialized (
    select v.*
    from inv i
    cross join lateral private._invoice_issue_validate_batch(
      jsonb_build_array(jsonb_build_object(
        'request_key','detail:'||i.id::text,
        'invoice_id',i.id,'expected_revision',i.document_revision,
        'allow_early',false,'deliver',true)),
      (now() at time zone 'Europe/London')::date) v
  ),
  support_summary as materialized (
    select
      count(*) filter(where support_type='ELECTRONIC_TIMESHEET')::integer
        electronic_timesheet_count,
      count(*) filter(where support_type='ELECTRONIC_TIMESHEET'
        and not coalesce(ready,false))::integer electronic_timesheet_not_ready_count,
      count(*) filter(where support_type='MANUAL_TIMESHEET')::integer
        manual_timesheet_count,
      count(*) filter(where support_type='MANUAL_TIMESHEET'
        and not coalesce(ready,false))::integer manual_timesheet_not_ready_count,
      coalesce(sum(pages),0)::integer estimated_timesheet_pages
    from timesheet_readiness
  ),
  evidence_summary as materialized (
    select count(*)::integer evidence_count,
      count(*) filter(where readiness='NOT_REGISTERED')::integer evidence_unregistered_count,
      count(*) filter(where readiness='NOT_READY')::integer evidence_not_ready_count,
      count(*) filter(where readiness='FAILED')::integer evidence_failed_count,
      coalesce(sum(normalised_page_count),0)::integer estimated_evidence_pages
    from evidence_rows
  ),
  projections as materialized (
    select
      (select coalesce(jsonb_agg(
        jsonb_build_object(
          'id',l.id,'invoice_id',l.invoice_id,'timesheet_id',l.timesheet_id,
          'booking_id',l.booking_id,'description',l.description,
          'hours_day',l.hours_day,'hours_night',l.hours_night,
          'hours_sat',l.hours_sat,'hours_sun',l.hours_sun,'hours_bh',l.hours_bh,
          'pay_day',l.pay_day,'pay_night',l.pay_night,'pay_sat',l.pay_sat,
          'pay_sun',l.pay_sun,'pay_bh',l.pay_bh,
          'charge_day',l.charge_day,'charge_night',l.charge_night,
          'charge_sat',l.charge_sat,'charge_sun',l.charge_sun,
          'charge_bh',l.charge_bh,'total_pay_ex_vat',l.total_pay_ex_vat,
          'total_charge_ex_vat',l.total_charge_ex_vat,
          'margin_ex_vat',l.margin_ex_vat,'vat_rate_pct',l.vat_rate_pct,
          'vat_amount',l.vat_amount,'total_inc_vat',l.total_inc_vat,
          'created_at',l.created_at,'paper_ts_r2_key',l.exact_timesheet_document_r2_key,
          'meta_json',l.meta_json,'source_key',l.source_key,
          'precheck_status',l.precheck_status,
          'has_timesheet_evidence_pdf',l.has_timesheet_evidence_pdf,
          'paper_ts_r2_key',l.exact_timesheet_document_r2_key,
          'is_adjustment',l.timesheet_id is null
            or upper(coalesce(l.meta_json->>'line_type',''))='ADJUSTMENT',
          'line_type_norm',upper(coalesce(l.meta_json->>'line_type','')))
        order by l.created_at,l.id),'[]'::jsonb) from lines l) line_rows,
      (select coalesce(jsonb_agg(jsonb_build_object(
        'id',e.id,'timesheet_id',e.timesheet_id,'kind',e.kind,
        'document_role',e.document_role,'candidate_component_id',e.candidate_component_id,
        'display_name',e.display_name,'storage_key',e.storage_key,
        'created_at',e.created_at,'document_asset_id',e.document_asset_id,
        'processing_state',e.processing_state,
        'processing_error',e.processing_error_json,'asset_status',e.asset_status,
        'normalised_r2_key',e.normalised_r2_key,
        'normalised_sha256',e.normalised_sha256,
        'normalised_size_bytes',e.normalised_size_bytes,
        'normalised_page_count',e.normalised_page_count,
        'readiness',e.readiness) order by e.created_at,e.id),
        '[]'::jsonb) from evidence_rows e) evidence,
      (select coalesce(jsonb_agg(jsonb_build_object(
        'id',e.id,'timesheet_id',e.timesheet_id,'kind',e.kind,
        'document_role',e.document_role,'candidate_component_id',e.candidate_component_id,
        'display_name',e.display_name,'storage_key',e.storage_key,
        'created_at',e.created_at,'document_asset_id',e.document_asset_id,
        'processing_state',e.processing_state,'asset_status',e.asset_status,
        'normalised_r2_key',e.normalised_r2_key,
        'normalised_sha256',e.normalised_sha256,
        'normalised_size_bytes',e.normalised_size_bytes,
        'normalised_page_count',e.normalised_page_count,
        'readiness',e.readiness) order by e.created_at,e.id),
        '[]'::jsonb) from evidence_rows e
        where upper(coalesce(e.kind,''))='TIMESHEET') timesheet_evidence,
      (select coalesce(jsonb_agg(jsonb_build_object(
        'id',e.id,'timesheet_id',e.timesheet_id,'kind',e.kind,
        'document_role',e.document_role,'candidate_component_id',e.candidate_component_id,
        'display_name',e.display_name,'storage_key',e.storage_key,
        'created_at',e.created_at,'document_asset_id',e.document_asset_id,
        'processing_state',e.processing_state,'asset_status',e.asset_status,
        'normalised_r2_key',e.normalised_r2_key,
        'normalised_sha256',e.normalised_sha256,
        'normalised_size_bytes',e.normalised_size_bytes,
        'normalised_page_count',e.normalised_page_count,
        'readiness',e.readiness) order by e.created_at,e.id),
        '[]'::jsonb) from evidence_rows e
        where upper(coalesce(e.kind,''))<>'TIMESHEET') evidence_other,
      (select coalesce(jsonb_agg(jsonb_build_object(
        'invoice_id',h.invoice_id,'source_system',h.source_system,
        'import_id',h.import_id,'header_rows',h.header_rows,
        'header_columns',h.header_columns,'rows_json',h.rows_json)
        order by h.source_system,h.import_id),
        '[]'::jsonb) from public.invoice_hr_source_rows h
        where h.invoice_id=p_invoice_id) hr_rows,
      (select coalesce(jsonb_agg(jsonb_build_object(
        'tsfin_id',f.id,'timesheet_id',f.timesheet_id,
        'external_source_rows_json',f.external_source_rows_json,
        'mileage_units',f.mileage_units,'mileage_pay_rate',f.mileage_pay_rate,
        'mileage_charge_rate',f.mileage_charge_rate)
        order by f.timesheet_id),'[]'::jsonb) from current_financials f) tsfin_rows,
      (select coalesce(jsonb_object_agg(f.timesheet_id::text,f.id::text
        order by f.timesheet_id),'{}'::jsonb) from current_financials f) tsfin_map
  ),
  assembled as materialized (
    select i.*,lt.*,rr.rows reference_rows,rs.rows reference_sources,
      sp.rows segments,p.*,hp.rows history_rows,ss.*,es.*,
      sea.can_edit_source,sea.source_edit_blocker_codes,
      sea.source_edit_will_replace_preview,
      cd.preview,cd.issued,cd.latest,
      ad.operation_id document_operation_id,ad.status document_operation_status,
      ad.phase document_operation_phase,ad.progress_json document_operation_progress,
      ad.error_json document_operation_error,ad.change_seq document_change_seq,
      ai.operation_id issue_operation_id,ai.chunk_id issue_chunk_id,
      ai.status issue_status,ai.phase issue_phase,ai.progress_json issue_progress,
      ai.error_json issue_error,ai.change_seq issue_change_seq,
      iv.hard_blocker_codes blocker_codes,iv.document_dependency_codes,
      iv.delivery_blocker_codes,iv.warning_codes,iv.can_issue_only,
      iv.can_issue_and_deliver,iv.route_policy_result,iv.detail_json
    from inv i cross join line_totals lt cross join reference_rows rr
    cross join reference_sources rs cross join segment_projection sp
    cross join projections p cross join history_projection hp
    cross join support_summary ss cross join evidence_summary es
    cross join source_edit_authority sea
    cross join current_documents cd
    left join active_document ad on true left join active_issue ai on true
    left join issue_validation iv on true
  ),
  allowlisted_snapshot as materialized (
    select a.*,
      jsonb_strip_nulls(jsonb_build_object(
        'agency_name',a.header_snapshot_json->'agency_name',
        'agency_logo',a.header_snapshot_json->'agency_logo',
        'agency_logo_url',a.header_snapshot_json->'agency_logo_url',
        'registered_address',a.header_snapshot_json->'registered_address',
        'company_reg_number',a.header_snapshot_json->'company_reg_number',
        'company_registration_number',
          a.header_snapshot_json->'company_registration_number',
        'vat_registration_number',
          a.header_snapshot_json->'vat_registration_number',
        'client_id',a.header_snapshot_json->'client_id',
        'client_name',a.header_snapshot_json->'client_name',
        'client_invoice_address',
          a.header_snapshot_json->'client_invoice_address',
        'client_primary_invoice_email',
          a.header_snapshot_json->'client_primary_invoice_email',
        'issued_at_utc',a.header_snapshot_json->'issued_at_utc',
        'due_at_utc',a.header_snapshot_json->'due_at_utc',
        'payment_terms_days',a.header_snapshot_json->'payment_terms_days',
        'vat_chargeable',a.header_snapshot_json->'vat_chargeable',
        'applied_vat_rate_pct',
          a.header_snapshot_json->'applied_vat_rate_pct',
        'hide_bank_footer',a.header_snapshot_json->'hide_bank_footer',
        'bank',jsonb_strip_nulls(jsonb_build_object(
          'name',a.header_snapshot_json#>'{bank,name}',
          'sort_code',a.header_snapshot_json#>'{bank,sort_code}',
          'account_number',a.header_snapshot_json#>'{bank,account_number}')),
        'stationery_key',a.header_snapshot_json->'stationery_key',
        'stationery_margins_mm',
          a.header_snapshot_json->'stationery_margins_mm',
        'attach_policy',jsonb_strip_nulls(jsonb_build_object(
          'ts_attach_to_invoice',
            a.header_snapshot_json#>'{attach_policy,ts_attach_to_invoice}',
          'hr_attach_to_invoice',
            a.header_snapshot_json#>'{attach_policy,hr_attach_to_invoice}',
          'requires_hr',
            a.header_snapshot_json#>'{attach_policy,requires_hr}')),
        'meta',jsonb_strip_nulls(jsonb_build_object(
          'consolidation_mode',
            a.header_snapshot_json#>'{meta,consolidation_mode}',
          'invoice_week_start',
            a.header_snapshot_json#>'{meta,invoice_week_start}',
          'segment_count',a.header_snapshot_json#>'{meta,segment_count}',
          'self_bill',a.header_snapshot_json#>'{meta,self_bill}',
          'source',a.header_snapshot_json#>'{meta,source}',
          'timesheet_count',
            a.header_snapshot_json#>'{meta,timesheet_count}'))
      )) business_header_snapshot
    from assembled a
  )
  select jsonb_build_object(
    'ok',true,
    'source_edit_queue_contract','INVOICE_SOURCE_EDIT_QUEUE_V1',
    'invoice',jsonb_build_object(
      'id',a.id,'type',a.type,'invoice_no',a.invoice_no,'client_id',a.client_id,
      'issued_at_utc',a.issued_at_utc,'due_at_utc',a.due_at_utc,
      'paid_at_utc',a.paid_at_utc,'status',a.status,
      'status_date_utc',a.status_date_utc,'subtotal_ex_vat',a.subtotal_ex_vat,
      'vat_amount',a.vat_amount,'total_inc_vat',a.total_inc_vat,
      'original_invoice_id',a.original_invoice_id,'notes',a.notes,
      'created_at',a.created_at,'updated_at',a.updated_at,
      'invoice_pdf_r2_key',a.invoice_pdf_r2_key,
      'invoice_pdf_generated_at_utc',a.invoice_pdf_generated_at_utc,
      'header_snapshot_json',a.business_header_snapshot,
      'on_hold_reason',a.on_hold_reason,'do_not_send',a.do_not_send,
      'credit_note_created_at_utc',a.credit_note_created_at_utc,
      'document_revision',a.document_revision,'document_state',a.document_state,
      'preview_document_version_id',a.preview_document_version_id,
      'issued_document_version_id',a.issued_document_version_id,
      'active_document_operation_id',a.active_document_operation_id,
      'issue_state',a.issue_state,
      'active_issue_operation_id',a.active_issue_operation_id,
      'last_document_error_json',a.last_document_error_json),
    'items',a.line_rows,'lines',a.line_rows,
    'header_snapshot_json',coalesce(a.business_header_snapshot,'{}'::jsonb),
    'attach_policy',a.business_header_snapshot->'attach_policy',
    'evidence',a.evidence,'timesheet_evidence',a.timesheet_evidence,
    'evidence_other',a.evidence_other,
    'hr_source_rows_cache',a.hr_rows,
    'tsfin_external_source_rows',a.tsfin_rows,
    'segments_on_invoice_by_timesheet',a.segments,
    'segments_by_timesheet',a.segments,
    'history',a.history_rows,
    'tsfin_id_by_timesheet_id',a.tsfin_map,
    'reference_rows',a.reference_rows,
    'timesheet_reference_sources_by_id',a.reference_sources,
    'email_summary',jsonb_build_object(
      'emailed_once',(select count(*)>0 from invoice_mail),
      'email_count',(select count(*) from invoice_mail),
      'last_email_at_utc',(select max(created_at_utc) from invoice_mail)),
    'financial_validation',jsonb_build_object(
      'stored_net',round(coalesce(a.subtotal_ex_vat,0),2),
      'calculated_net',a.net,'stored_vat',round(coalesce(a.vat_amount,0),2),
      'calculated_vat',a.vat,'stored_gross',round(coalesce(a.total_inc_vat,0),2),
      'calculated_gross',a.gross),
    'document_readiness',jsonb_build_object(
      'revision',a.document_revision,'state',a.document_state,
      'preview',a.preview,'issued',a.issued,'latest',a.latest,
      'operation_id',a.document_operation_id,'operation_status',a.document_operation_status,
      'operation_phase',a.document_operation_phase,'operation_progress',a.document_operation_progress,
      'operation_error',coalesce(a.document_operation_error,a.last_document_error_json),
      'change_seq',a.document_change_seq,
      'electronic_timesheet_count',a.electronic_timesheet_count,
      'electronic_timesheet_not_ready_count',a.electronic_timesheet_not_ready_count,
      'manual_timesheet_count',a.manual_timesheet_count,
      'manual_timesheet_not_ready_count',a.manual_timesheet_not_ready_count,
      'evidence_count',a.evidence_count,
      'evidence_unregistered_count',a.evidence_unregistered_count,
      'evidence_not_ready_count',a.evidence_not_ready_count,
      'evidence_failed_count',a.evidence_failed_count,
      'healthroster_support_count',(select count(*) from public.invoice_hr_source_rows h
        where h.invoice_id=p_invoice_id and upper(coalesce(h.source_system,''))='HEALTHROSTER'),
      'nhsp_support_count',(select count(*) from public.invoice_hr_source_rows h
        where h.invoice_id=p_invoice_id and upper(coalesce(h.source_system,''))='NHSP'),
      'higher_rate_support_count',(select count(*) from lines l
        where upper(coalesce(l.meta_json->>'line_type','')) like '%HIGHER_RATE%'),
      'estimated_supporting_pages',a.estimated_timesheet_pages+a.estimated_evidence_pages),
    'issue',jsonb_build_object(
      'state',a.issue_state,'operation_id',a.issue_operation_id,
      'chunk_id',a.issue_chunk_id,'status',a.issue_status,'phase',a.issue_phase,
      'progress',a.issue_progress,'error',a.issue_error,'change_seq',a.issue_change_seq,
      'validation_detail',a.detail_json,
      'document_dependencies',coalesce(a.document_dependency_codes,'[]'::jsonb),
      'delivery_blockers',coalesce(a.delivery_blocker_codes,'[]'::jsonb),
      'route_policy',coalesce(a.route_policy_result,'{}'::jsonb),
      'warnings',coalesce(a.warning_codes,'[]'::jsonb)),
    'blocker_codes',coalesce(a.blocker_codes,'[]'::jsonb),
    'source_edit_blocker_codes',coalesce(a.source_edit_blocker_codes,'[]'::jsonb),
    'source_edit_will_replace_preview',coalesce(a.source_edit_will_replace_preview,false),
    'actions',jsonb_build_object(
      'can_edit',a.status='DRAFT' and a.issue_operation_id is null,
      'can_edit_source',coalesce(a.can_edit_source,false),
      'can_issue',coalesce(a.can_issue_only,false)
        and a.issue_operation_id is null,
      'can_issue_only',coalesce(a.can_issue_only,false)
        and a.issue_operation_id is null,
      'can_issue_and_deliver',coalesce(a.can_issue_and_deliver,false)
        and a.issue_operation_id is null,
      'can_unissue',a.status='ISSUED',
      'can_retry_document',a.document_state='FAILED',
      'can_retry_issue',coalesce(
        a.issue_status in('BLOCKED','FAILED','DEAD_LETTER'),false))
  ) into v_result
  from allowlisted_snapshot a;

  return v_result;
end;
$function$;

revoke all on function public.invoice_detail_get(uuid,uuid)
  from public,anon,authenticated,service_role,supabase_admin;
grant execute on function public.invoice_detail_get(uuid,uuid)
  to CURRENT_USER,service_role;




-- CONTACT_PREPARER_UNIT 21 repeatable supabase/repeatable/31072026_1450_invoice_week_ending_document_identity.sql SHA256 bdc2c0413c3dde4bac00389eee9a7979577a7eb1e856621777ed9bd6f9e831db




CREATE OR REPLACE FUNCTION public.invoice_apply_edits(p_invoice_id uuid, p_payload jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();
  v_anchor_ymd date := (now() at time zone 'Europe/London')::date;


-- =====================================================
-- DEBUG (invoice_debug): single audit row per RPC call
-- =====================================================
v_invoice_debug boolean := false;
v_dbg_started_at timestamptz := now();
v_dbg_steps jsonb := '[]'::jsonb;
v_dbg_sqlstate text := null;
v_dbg_error text := null;
v_dbg_stats jsonb := '{}'::jsonb;


v_dbg_lines_deleted int := 0;
v_dbg_timesheets_unlocked int := 0;
v_dbg_seg_add_refs int := 0;
v_dbg_seg_remove_refs int := 0;
v_dbg_seg_tsfins int := 0;
v_dbg_seg_timesheets_rebuilt int := 0;
v_dbg_seg_timesheets_removed int := 0;
v_dbg_add_timesheets_found int := 0;
v_dbg_add_timesheets_skipped int := 0;

v_rc int := 0;

  v_inv record;
  v_week_start date;
  v_week_end date;

  v_remove_ids uuid[];
  v_add_ts_ids uuid[];

-- segment move payload (explicit segment add/remove)
v_remove_seg_refs jsonb;
v_add_seg_refs jsonb;
v_has_seg_ops boolean := false;
v_refresh_hr_cache boolean := false;
v_seg_tsfin_ids uuid[] := array[]::uuid[];
v_seg_ts_ids uuid[] := array[]::uuid[];
v_seg_refs_to_lock jsonb := '[]'::jsonb;
v_ref jsonb;
v_tsfin_id uuid;
v_seg_id text;
v_has_additional boolean;
v_has_expense_or_mileage boolean;

  -- reference updates (refs-to-issue)
  v_reference_updates jsonb;
  v_refupd jsonb;
  v_refupd_ts_id uuid;
  v_refupd_count int := 0;
  v_refupd_applied int := 0;
  v_refupd_set_refnum boolean;
  v_refupd_set_dayrefs boolean;
  v_refupd_set_sched boolean;
  v_refupd_dayrefs jsonb;
  v_refupd_sched jsonb;
  v_refupd_refnum text;

  -- timesheet hospital / ward source edits
  v_location_updates jsonb;
  v_location_update jsonb;
  v_location_ts_id uuid;
  v_location_count int := 0;
  v_location_applied int := 0;
  v_location_set_hospital boolean;
  v_location_set_ward boolean;
  v_location_hospital_norm text;
  v_location_ward_norm text;
  v_location_ts_ids uuid[] := array[]::uuid[];
  -- Source-edit contract state. Reference and location inputs are merged into
  -- one desired row per timesheet, then written by one statement so the
  -- statement-level invalidation trigger advances each source exactly once.
  v_source_updates_map jsonb := '{}'::jsonb;
  v_source_update jsonb;
  v_source_edit_key text;
  v_source_expected_revision bigint;
  v_source_changed_ts_ids uuid[] := array[]::uuid[];
  v_source_changed_revisions jsonb := '[]'::jsonb;
  v_source_edit_requested boolean := false;
  v_allowed_reference_fields text[]:=array[
    'timesheet_id','expected_document_revision','reference_number',
    'day_references_json','actual_schedule_json'];
  v_allowed_location_fields text[]:=array[
    'timesheet_id','expected_document_revision','hospital_norm','ward_norm'];
  v_allowed_reference_segment_fields text[]:=array[
    'segment_id','date','start_utc','end_utc','start','end','ref_num',
    'source_system'];
  v_source_unsupported_field text;
  v_source_financial_id uuid;
  v_source_mode text;
  v_source_ib jsonb;
  v_source_payload_schedule jsonb;
  v_source_canonical_schedule jsonb;
  v_source_new_segments jsonb;
  v_source_segment_updates jsonb;
  v_source_segment_reference_changed boolean;
  v_source_timesheet_row_changed boolean;
  v_source_match_count integer;
  v_source_match_segment jsonb;
  v_source_payload_segment jsonb;
  v_source_current_segment jsonb;
  v_source_payload_ord bigint;
  v_source_start timestamptz;
  v_source_end timestamptz;
  v_source_marker_rows jsonb:='{}'::jsonb;
  v_source_marker jsonb:='{}'::jsonb;
  v_source_edit_preexisting_preview boolean := false;
  v_source_edit_invoice_replacement_required boolean := false;
  v_pre_edit_invoice_revision bigint;
  v_pre_edit_preview_document_version_id uuid;
  v_pre_edit_active_document_operation_id uuid;
  v_expected_command_count int := 0;
  v_operation_result jsonb;
  v_operation_id uuid;
  v_document_version_id uuid;
  v_command_no int;
  v_command_type text;
  v_operation_status text;
  v_operation_input jsonb;
  v_validated_operations jsonb := '[]'::jsonb;
  v_document_commands jsonb := '[]'::jsonb;
  v_started_operations jsonb := '[]'::jsonb;

  -- reference update side-effects (meta refresh / segment ref sync)
  v_refupd_ts_ids uuid[] := array[]::uuid[];
  v_refupd_ts_ids_distinct uuid[] := array[]::uuid[];
  v_refupd_meta_rows_updated int := 0;
  v_refupd_tsfin_rows_updated int := 0;
  v_refupd_tsfin_segments_updated int := 0;
  v_refupd_invoice_fallback_invalidated boolean := false;

  -- temp vars for reference-derived meta and optional tsfin segment ref sync
  v_ref_ts_id uuid;
  v_ref_ts record;
  v_ref_schedule_refs jsonb := '[]'::jsonb;
  v_ref_schedule_refs_distinct jsonb := '[]'::jsonb;
  v_ref_sched_map jsonb := '{}'::jsonb;
  v_ref_seen_keys jsonb := '{}'::jsonb;
  v_ref_sched_key text;
  v_ref_sched_ref text;
  v_ref_tsfin_id uuid;
  v_ref_ib jsonb;
  v_ref_new_segments jsonb := '[]'::jsonb;
  v_ref_seg_obj jsonb;
  v_ref_seg_start text;
  v_ref_seg_end text;
    v_ref_seg_id text;
v_ref_seg_cur_ref text;
  v_ref_seg_new_ref text;
  v_ref_seg_has_update boolean := false;
  v_ref_seg_updates_this_ts int := 0;
  v_ref_seg_matches_this_ts int := 0;

  -- audit (history) accumulators (NOT debug-only)
  v_hist_adj jsonb := '[]'::jsonb;
  v_hist_seg_add jsonb := '[]'::jsonb;
  v_hist_seg_remove jsonb := '[]'::jsonb;
  v_hist_lines_removed jsonb := '[]'::jsonb;
  v_hist_add_ts jsonb := '[]'::jsonb;

  -- contract week status touch set
  v_cw_ts_ids uuid[] := array[]::uuid[];

  v_ts_ids_touched uuid[] := array[]::uuid[];
  -- FIX: timesheets fully removed from this invoice (no remaining invoice_lines) should be unlocked
  v_ts_ids_fully_removed uuid[] := array[]::uuid[];

  v_vat_chargeable boolean := true;
  v_vat_rate numeric := 0;

  -- adjustments
  adj jsonb;
  v_adj_token text;
  v_adj_desc text;
  v_adj_ex numeric;
  v_adj_vat numeric;
  v_adj_inc numeric;
  v_adj_source_key text;
  v_meta jsonb;

  -- timesheet loop
  tsid uuid;
  snap record;
  ts record;
  pc record;
  contract_id uuid;
  v_settings_authority jsonb;
  c_daily_calc boolean := false;
  c_bucket_labels jsonb := null;
  c_role text := null;
  c_display_site text := null;
  c_ward_hint text := null;

  -- segment filtering
  v_seg jsonb;
  segments jsonb := '[]'::jsonb;
  seg_target date;
  seg_date text;
  natural_start date;
  seg_locked text;
  seg_ref text;

  -- aggregation for weekly line
  h_day numeric; h_night numeric; h_sat numeric; h_sun numeric; h_bh numeric;
  pay_ex numeric; chg_ex numeric; margin_ex numeric;
  vat_amt numeric; inc_amt numeric;
  line_desc text;
  v_source_key text;
  v_exact_timesheet_document_r2_key text;

  -- daily aggregation record
  r_day record;

  -- segment refs for locking
  seg_refs jsonb := '[]'::jsonb;

  -- additional units
  kv record;
  ex jsonb;
  code text;
  unit_count numeric;
  bucket_name text;
  unit_name text;

  -- expenses notes
  v_note_travel text;
  v_note_accom text;
  v_note_other text;

  -- recompute totals
  v_new_ex numeric := 0;
  v_new_vat numeric := 0;
  v_new_inc numeric := 0;

  -- header meta counters (keep header_snapshot_json.meta in sync with current invoice state)
  v_hdr_ts_count_lines int := 0;
  v_hdr_ts_count_seglocks int := 0;
  v_hdr_seg_locked_count int := 0;
  v_hdr_meta_timesheet_count int := 0;
  v_hdr_meta_segment_count int := 0;

  v_manifest jsonb;
  v_correction_placement_only boolean:=false;
  v_correction_placement_ts_id uuid:=null;
  v_correction_placement_scope jsonb:='{}'::jsonb;
  v_correction_placement_states jsonb:='[]'::jsonb;
  v_service boolean:=coalesce(auth.role(),'')='service_role';
  v_actor_role text;
begin

  if not v_service
     and(auth.uid() is null or auth.uid() is distinct from p_actor_user_id) then
    raise exception using errcode='42501',
      message='AUTHENTICATED_ACTOR_MISMATCH';
  end if;
  select lower(btrim(coalesce(u.role,''))) into v_actor_role
  from public.tms_users u
  where u.id=p_actor_user_id and u.is_active;
  if(not found or v_actor_role<>'admin') and not v_service then
    raise exception using errcode='42501',
      message='INVOICE_ADMINISTRATOR_PERMISSION_REQUIRED';
  end if;

  perform public._ctms_assert_invoice_mutable_draft_v1(
    p_invoice_id,'INVOICE_APPLY_EDITS',true
  );
  v_correction_placement_only:=
    jsonb_typeof(coalesce(p_payload,'{}'::jsonb))='object'
    and not exists(select 1 from jsonb_object_keys(coalesce(p_payload,'{}'::jsonb)) payload_key
      where payload_key not in ('remove_invoice_line_ids','add_timesheet_ids'))
    and coalesce(jsonb_array_length(case when jsonb_typeof(p_payload->'remove_invoice_line_ids')='array'
      then p_payload->'remove_invoice_line_ids' else '[]'::jsonb end),0)
      +coalesce(jsonb_array_length(case when jsonb_typeof(p_payload->'add_timesheet_ids')='array'
      then p_payload->'add_timesheet_ids' else '[]'::jsonb end),0)=1
    and (
      (case when coalesce(p_payload#>>'{remove_invoice_line_ids,0}','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then exists(
          select 1 from public.invoice_lines placement_line
          where placement_line.id=(p_payload#>>'{remove_invoice_line_ids,0}')::uuid
            and placement_line.invoice_id=p_invoice_id
            and coalesce((public._ctms_import_correction_classify_v1(placement_line.timesheet_id)
              ->>'is_import_authoritative_correction')::boolean,false)) else false end)
      or
      (case when coalesce(p_payload#>>'{add_timesheet_ids,0}','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        coalesce((public._ctms_import_correction_classify_v1(
          (p_payload#>>'{add_timesheet_ids,0}')::uuid)->>'is_import_authoritative_correction')::boolean,false)
        else false end)
    );
  if public._ctms_invoice_payload_has_financial_edit_v1(p_payload)
     and not v_correction_placement_only
     and exists (
       select 1 from public.invoice_lines il
       where il.invoice_id=p_invoice_id and il.timesheet_id is not null
         and coalesce((public._ctms_import_correction_classify_v1(il.timesheet_id)
           ->>'is_import_authoritative_correction')::boolean,false)
     ) then
    raise exception 'IMPORT_CORRECTION_INVOICE_FINANCIAL_EDIT_FORBIDDEN'
      using errcode='P0001',detail=jsonb_build_object('invoice_id',p_invoice_id)::text;
  end if;
-- Load invoice_debug flag (safe even if column not yet present)
begin
  select coalesce(sd.invoice_debug, false)
  into v_invoice_debug
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;
exception when undefined_column then
  v_invoice_debug := false;
end;

if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','start',
      'at_utc', public._inv_iso_utc(v_dbg_started_at),
      'invoice_id', p_invoice_id::text
    )
  );
end if;

  if p_invoice_id is null then
    raise exception 'invoice_id is required';
  end if;

  select *
  into v_inv
  from public.invoices i
  where i.id = p_invoice_id
  for update
  limit 1;

  if not found then
    raise exception 'Invoice not found';
  end if;

  -- Editable gate: DRAFT/ON_HOLD and unpaid
  if v_inv.status::text not in ('DRAFT','ON_HOLD') then
    raise exception 'Invoice is not editable (status=%)', v_inv.status::text;
  end if;

  if v_inv.paid_at_utc is not null then
    raise exception 'Invoice is not editable (already paid)';
  end if;



if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','invoice_loaded',
      'status', coalesce(v_inv.status::text,''),
      'paid_at_utc', case when v_inv.paid_at_utc is null then null else public._inv_iso_utc(v_inv.paid_at_utc) end
    )
  );
end if;

  -- Require invoice_week_start in header_snapshot_json.meta
  if v_inv.header_snapshot_json is null
     or btrim(coalesce(v_inv.header_snapshot_json #>> '{meta,invoice_week_start}','')) = ''
     or (v_inv.header_snapshot_json #>> '{meta,invoice_week_start}') !~ '^\d{4}-\d{2}-\d{2}$'
  then
    raise exception 'Invoice header_snapshot_json.meta.invoice_week_start is required for edits';
  end if;

  v_week_start := (v_inv.header_snapshot_json #>> '{meta,invoice_week_start}')::date;
  v_week_end := (v_week_start + interval '6 days')::date;


if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','invoice_week_loaded',
      'invoice_week_start', v_week_start::text,
      'invoice_week_end', v_week_end::text
    )
  );
end if;

  -- VAT settings from invoice snapshot
  if jsonb_typeof(v_inv.header_snapshot_json->'vat_chargeable') = 'boolean' then
    v_vat_chargeable := (v_inv.header_snapshot_json->>'vat_chargeable')::boolean;
  else
    v_vat_chargeable := true;
  end if;

  if (v_inv.header_snapshot_json ? 'applied_vat_rate_pct') then
    begin
      v_vat_rate := (v_inv.header_snapshot_json->>'applied_vat_rate_pct')::numeric;
    exception when others then
      v_vat_rate := 0;
    end;
  else
    v_vat_rate := 0;
  end if;

  if v_vat_chargeable = false then
    v_vat_rate := 0;
  end if;

  -- Parse payload arrays
  v_remove_ids := null;
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'remove_invoice_line_ids') then
    select array_agg((x)::uuid)
    into v_remove_ids
    from jsonb_array_elements_text(coalesce(p_payload->'remove_invoice_line_ids','[]'::jsonb)) x
    where nullif(btrim(coalesce(x,'')),'') is not null;
  end if;

  v_add_ts_ids := null;
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_timesheet_ids') then
    select array_agg((x)::uuid)
    into v_add_ts_ids
    from jsonb_array_elements_text(coalesce(p_payload->'add_timesheet_ids','[]'::jsonb)) x
    where nullif(btrim(coalesce(x,'')),'') is not null;
  end if;

  IF v_correction_placement_only THEN
    IF COALESCE(cardinality(v_remove_ids),0)=1 THEN
      SELECT il.timesheet_id INTO v_correction_placement_ts_id
      FROM public.invoice_lines il
      WHERE il.id=v_remove_ids[1] AND il.invoice_id=p_invoice_id
      FOR UPDATE;
      IF v_correction_placement_ts_id IS NULL
         OR COALESCE((public._ctms_import_correction_classify_v1(v_correction_placement_ts_id)
             ->>'is_import_authoritative_correction')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_TARGET_INVALID' USING ERRCODE='P0001';
      END IF;
      v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
        v_correction_placement_ts_id,null::uuid,p_actor_user_id,true,100);
      IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
         OR v_correction_placement_scope->>'placement_state' NOT IN (
           'COMPLETE_SAME_INVOICE','COMPLETE_SPLIT_INVOICES') THEN
        RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_MOVE_NOT_STARTABLE'
          USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
      END IF;
    ELSIF COALESCE(cardinality(v_add_ts_ids),0)=1 THEN
      v_correction_placement_ts_id:=v_add_ts_ids[1];
      IF COALESCE((public._ctms_import_correction_classify_v1(v_correction_placement_ts_id)
             ->>'is_import_authoritative_correction')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_TARGET_INVALID' USING ERRCODE='P0001';
      END IF;
      v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
        v_correction_placement_ts_id,p_invoice_id,p_actor_user_id,true,100);
      IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
         OR v_correction_placement_scope->>'placement_state'<>'INCOMPLETE_MOVE'
         OR v_correction_placement_scope->>'missing_member_kind' IS DISTINCT FROM
              (SELECT t.correction_kind FROM public.timesheets t
               WHERE t.timesheet_id=v_correction_placement_ts_id)
         OR COALESCE((v_correction_placement_scope->>'target_appendable')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_TARGET_INVALID'
          USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
      END IF;
    ELSE
      RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_PAYLOAD_INVALID' USING ERRCODE='22023';
    END IF;
  END IF;


-- Parse segment move payloads (tsfin_id + segment_id)
v_remove_seg_refs := null;
if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'remove_segment_refs') then
  v_remove_seg_refs := coalesce(p_payload->'remove_segment_refs','[]'::jsonb);
  if jsonb_typeof(v_remove_seg_refs) <> 'array' then
    v_remove_seg_refs := '[]'::jsonb;
  end if;
end if;

v_add_seg_refs := null;
if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_segment_refs') then
  v_add_seg_refs := coalesce(p_payload->'add_segment_refs','[]'::jsonb);
  if jsonb_typeof(v_add_seg_refs) <> 'array' then
    v_add_seg_refs := '[]'::jsonb;
  end if;
end if;



-- Parse and strictly validate source edits. The expected source revision is
-- mandatory because values displayed by an older modal must never overwrite a
-- newer timesheet revision.
v_reference_updates := null;
if p_payload is not null and jsonb_typeof(p_payload)='object'
   and p_payload ? 'reference_updates' then
  v_reference_updates:=p_payload->'reference_updates';
  if jsonb_typeof(v_reference_updates)<>'array' then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
      detail=jsonb_build_object('field','reference_updates','reason','ARRAY_REQUIRED')::text;
  end if;
  v_refupd_count:=jsonb_array_length(v_reference_updates);
  for v_refupd in select value from jsonb_array_elements(v_reference_updates) value loop
    if v_refupd is not null and jsonb_typeof(v_refupd)='object' then
      select min(field_name) into v_source_unsupported_field
      from jsonb_object_keys(v_refupd) field_name
      where not (field_name=any(v_allowed_reference_fields));
      if v_source_unsupported_field is not null then
        raise exception using errcode='22023',
          message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
          detail=jsonb_build_object(
            'field','reference_updates','reason','UNSUPPORTED_FIELD',
            'unsupported_field',v_source_unsupported_field)::text;
      end if;
    end if;
    if v_refupd is null or jsonb_typeof(v_refupd)<>'object'
       or nullif(btrim(coalesce(v_refupd->>'timesheet_id','')),'') is null
       or coalesce(v_refupd->>'timesheet_id','') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       or coalesce(v_refupd->>'expected_document_revision','') !~ '^[1-9][0-9]*$'
       or not (
         v_refupd ? 'reference_number'
         or v_refupd ? 'day_references_json'
         or v_refupd ? 'actual_schedule_json'
       )
       or (
         v_refupd ? 'reference_number'
         and jsonb_typeof(v_refupd->'reference_number') not in('string','null')
       )
       or (
         v_refupd ? 'day_references_json'
         and jsonb_typeof(v_refupd->'day_references_json') not in('object','null')
       )
       or (
         v_refupd ? 'actual_schedule_json'
         and jsonb_typeof(v_refupd->'actual_schedule_json') not in('array','null')
       )
    then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
        detail=jsonb_build_object('field','reference_updates','reason','INVALID_ITEM')::text;
    end if;
    v_source_edit_key:=lower(v_refupd->>'timesheet_id');
    if v_source_updates_map ? v_source_edit_key then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_DUPLICATE_TIMESHEET',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'field','reference_updates')::text;
    end if;
    v_source_updates_map:=jsonb_set(
      v_source_updates_map,array[v_source_edit_key],
      jsonb_build_object(
        'timesheet_id',v_source_edit_key,
        'expected_document_revision',(v_refupd->>'expected_document_revision')::bigint,
        'has_reference_number',v_refupd ? 'reference_number',
        'reference_number',case when v_refupd ? 'reference_number'
          then to_jsonb(nullif(btrim(coalesce(v_refupd->>'reference_number','')),''))
          else 'null'::jsonb end,
        'has_day_references_json',v_refupd ? 'day_references_json',
        'day_references_json',case
          when not (v_refupd ? 'day_references_json') then 'null'::jsonb
          when jsonb_typeof(v_refupd->'day_references_json')='null' then 'null'::jsonb
          else v_refupd->'day_references_json' end,
        'has_actual_schedule_json',v_refupd ? 'actual_schedule_json',
        'actual_schedule_json',case
          when not (v_refupd ? 'actual_schedule_json') then 'null'::jsonb
          when jsonb_typeof(v_refupd->'actual_schedule_json')='null' then 'null'::jsonb
          else v_refupd->'actual_schedule_json' end,
        'has_hospital_norm',false,
        'has_ward_norm',false),
      true);
  end loop;
end if;

-- Hospital/ward edits merge into the same desired source row. A source may
-- appear once in each array, but both items must carry the same revision.
v_location_updates:=null;
if p_payload is not null and jsonb_typeof(p_payload)='object'
   and p_payload ? 'timesheet_location_updates' then
  v_location_updates:=p_payload->'timesheet_location_updates';
  if jsonb_typeof(v_location_updates)<>'array' then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
      detail=jsonb_build_object('field','timesheet_location_updates','reason','ARRAY_REQUIRED')::text;
  end if;
  v_location_count:=jsonb_array_length(v_location_updates);
  for v_location_update in select value from jsonb_array_elements(v_location_updates) value loop
    if v_location_update is not null and jsonb_typeof(v_location_update)='object' then
      select min(field_name) into v_source_unsupported_field
      from jsonb_object_keys(v_location_update) field_name
      where not (field_name=any(v_allowed_location_fields));
      if v_source_unsupported_field is not null then
        raise exception using errcode='22023',
          message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
          detail=jsonb_build_object(
            'field','timesheet_location_updates','reason','UNSUPPORTED_FIELD',
            'unsupported_field',v_source_unsupported_field)::text;
      end if;
    end if;
    if v_location_update is null or jsonb_typeof(v_location_update)<>'object'
       or nullif(btrim(coalesce(v_location_update->>'timesheet_id','')),'') is null
       or coalesce(v_location_update->>'timesheet_id','') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       or coalesce(v_location_update->>'expected_document_revision','') !~ '^[1-9][0-9]*$'
       or not (v_location_update ? 'hospital_norm' or v_location_update ? 'ward_norm')
       or (
         v_location_update ? 'hospital_norm'
         and jsonb_typeof(v_location_update->'hospital_norm') not in('string','null')
       )
       or (
         v_location_update ? 'ward_norm'
         and jsonb_typeof(v_location_update->'ward_norm') not in('string','null')
       )
    then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
        detail=jsonb_build_object('field','timesheet_location_updates','reason','INVALID_ITEM')::text;
    end if;
    v_source_edit_key:=lower(v_location_update->>'timesheet_id');
    v_source_expected_revision:=(v_location_update->>'expected_document_revision')::bigint;
    if v_source_updates_map ? v_source_edit_key
       and (
         coalesce((v_source_updates_map#>>
           array[v_source_edit_key,'has_hospital_norm'])::boolean,false)
         or coalesce((v_source_updates_map#>>
           array[v_source_edit_key,'has_ward_norm'])::boolean,false)
       ) then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_DUPLICATE_TIMESHEET',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'field','timesheet_location_updates')::text;
    end if;
    if v_source_updates_map ? v_source_edit_key
       and (v_source_updates_map#>>array[v_source_edit_key,'expected_document_revision'])::bigint
           is distinct from v_source_expected_revision then
      raise exception using errcode='40001',
        message='INVOICE_SOURCE_EDIT_STALE_REVISION',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'reason','EXPECTED_REVISION_CONFLICT')::text;
    end if;
    v_source_update:=coalesce(v_source_updates_map->v_source_edit_key,
      jsonb_build_object(
        'timesheet_id',v_source_edit_key,
        'expected_document_revision',v_source_expected_revision,
        'has_reference_number',false,
        'has_day_references_json',false,
        'has_actual_schedule_json',false));
    v_source_update:=v_source_update||jsonb_build_object(
      'has_hospital_norm',v_location_update ? 'hospital_norm',
      'hospital_norm',case when v_location_update ? 'hospital_norm'
        then to_jsonb(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'hospital_norm','')),
          '[[:space:]]+',' ','g')))
        else 'null'::jsonb end,
      'has_ward_norm',v_location_update ? 'ward_norm',
      'ward_norm',case when v_location_update ? 'ward_norm'
        then to_jsonb(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'ward_norm','')),
          '[[:space:]]+',' ','g')))
        else 'null'::jsonb end);
    v_source_updates_map:=jsonb_set(v_source_updates_map,array[v_source_edit_key],v_source_update,true);
  end loop;
end if;
v_source_edit_requested:=v_source_updates_map<>'{}'::jsonb;
v_has_seg_ops :=
  (v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0)
  or (v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0);

  v_refresh_hr_cache := (coalesce(array_length(v_add_ts_ids,1),0) > 0) or coalesce(v_has_seg_ops,false);

  if v_invoice_debug then
    v_dbg_stats := v_dbg_stats || jsonb_build_object(
      'remove_invoice_line_ids_count', coalesce(array_length(v_remove_ids,1),0),
      'add_timesheet_ids_count', coalesce(array_length(v_add_ts_ids,1),0),
      'add_adjustments_count', case when p_payload is not null and jsonb_typeof(p_payload)='object' and (p_payload ? 'add_adjustments') and jsonb_typeof(p_payload->'add_adjustments')='array' then jsonb_array_length(p_payload->'add_adjustments') else 0 end,
      'remove_segment_refs_count', case when v_remove_seg_refs is null then 0 else jsonb_array_length(coalesce(v_remove_seg_refs,'[]'::jsonb)) end,
      'add_segment_refs_count', case when v_add_seg_refs is null then 0 else jsonb_array_length(coalesce(v_add_seg_refs,'[]'::jsonb)) end,
      'timesheet_location_updates_count',v_location_count,
      'has_segment_ops', v_has_seg_ops
    );
    v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','payload_parsed','stats',v_dbg_stats));
  end if;

  if v_source_edit_requested then
    -- Source edits are a narrower authority than ordinary draft edits.
    if v_inv.issued_at_utc is not null then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_ISSUED';
    end if;
    if v_inv.paid_at_utc is not null then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_PAID';
    end if;
    if v_inv.active_issue_operation_id is not null
       or upper(coalesce(v_inv.issue_state,'')) in
          ('VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
       or exists(
         select 1
         from public.invoice_operation_chunks c
         where c.chunk_type='ISSUE_INVOICE'
           and c.entity_type='INVOICE'
           and c.entity_id=p_invoice_id
           and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
       )
    then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_ISSUE_IN_PROGRESS';
    end if;

    v_pre_edit_invoice_revision:=v_inv.document_revision;
    v_pre_edit_preview_document_version_id:=v_inv.preview_document_version_id;
    v_pre_edit_active_document_operation_id:=v_inv.active_document_operation_id;

    -- Only an exact current-revision V8 preview is authoritative. Legacy PDF
    -- summary fields do not independently force or suppress replacement.
    select exists(
      select 1
      from public.invoice_document_versions dv
      left join public.invoice_operations op on op.id=dv.operation_id
      where dv.entity_type='INVOICE'
        and dv.entity_id=p_invoice_id
        and dv.purpose='DRAFT_PREVIEW'
        and dv.source_revision=v_pre_edit_invoice_revision::text
        and (
          (dv.status='READY'
            and nullif(btrim(coalesce(dv.r2_key,'')),'') is not null
            and nullif(btrim(coalesce(dv.sha256,'')),'') is not null
            and coalesce(dv.size_bytes,0)>0
            and coalesce(dv.page_count,0)>0)
          or (
            dv.id=v_pre_edit_preview_document_version_id
            and dv.status in(
              'PLANNING','WAITING_FOR_INPUTS','RENDERING',
              'ASSEMBLING','VERIFYING','READY'))
          or (
            dv.operation_id=v_pre_edit_active_document_operation_id
            and op.operation_type='BUILD_DOCUMENT'
            and op.entity_type='INVOICE'
            and op.entity_id=p_invoice_id
            and op.source_revision=v_pre_edit_invoice_revision::text
            and coalesce(op.input_json->>'purpose','')='DRAFT_PREVIEW'
            and op.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
        )
    ) into v_source_edit_preexisting_preview;

    -- Clear any caller-controlled or earlier transaction-local value before
    -- establishing this function's exact-once invalidation marker.
    perform set_config('cloudtms.invoice_source_edit_marker','{}',true);

    -- Lock every target and its current financial snapshot in deterministic
    -- order before validating ownership, revisions or segment identities.
    for v_ref_ts in
      select t.*
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired on true
      where t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      order by t.timesheet_id
      for update of t
    loop
      null;
    end loop;
    for v_ref_ts in
      select tf.id
      from public.timesheets_financials tf
      join jsonb_each(v_source_updates_map) desired
        on tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where tf.is_current
      order by tf.timesheet_id,tf.id
      for update of tf
    loop
      null;
    end loop;

    if (
      select count(*)
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where t.is_current
    )<>(select count(*) from jsonb_each(v_source_updates_map)) then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_SOURCE_NOT_CURRENT';
    end if;

    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      join public.timesheets t
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where t.document_revision is distinct from
        (desired.value->>'expected_document_revision')::bigint
    ) then
      raise exception using errcode='40001',
        message='INVOICE_SOURCE_EDIT_STALE_REVISION';
    end if;

    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where not exists(
        select 1
        from public.invoice_lines owned_line
        where owned_line.invoice_id=p_invoice_id
          and (
            owned_line.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              owned_line.timesheet_id is null
              and coalesce(owned_line.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (owned_line.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
    ) then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_SOURCE_NOT_OWNED';
    end if;

    -- Preserve the established import-authoritative correction lock across
    -- both supported source carriers.
    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where coalesce((
        public._ctms_import_correction_classify_v1(
          (desired.value->>'timesheet_id')::uuid)
          ->>'is_import_authoritative_correction')::boolean,false)
    ) then
      raise exception using errcode='55000',
        message='IMPORT_AUTHORITATIVE_CORRECTION_SOURCE_EDIT_FORBIDDEN';
    end if;

    -- Reject a mixed command that edits a source while removing every carrier
    -- for that source in the same Save.
    if coalesce(array_length(v_remove_ids,1),0)>0 and exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where exists(
        select 1
        from public.invoice_lines carrier
        where carrier.invoice_id=p_invoice_id
          and (
            carrier.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              carrier.timesheet_id is null
              and coalesce(carrier.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (carrier.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
      and not exists(
        select 1
        from public.invoice_lines retained
        where retained.invoice_id=p_invoice_id
          and not (retained.id=any(v_remove_ids))
          and (
            retained.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              retained.timesheet_id is null
              and coalesce(retained.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (retained.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
    ) then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND';
    end if;

    -- Classify each source from the locked current financial snapshot. A
    -- SEGMENTS payload is an editable reference projection only: it can never
    -- replace timesheets.actual_schedule_json or any financial segment object.
    for v_ref_ts in
      select t.*,desired.value desired_value,
        tf.id financial_id,tf.invoice_breakdown_json financial_breakdown
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      left join lateral(
        select f.id,f.invoice_breakdown_json
        from public.timesheets_financials f
        where f.timesheet_id=t.timesheet_id and f.is_current
        order by f.updated_at desc nulls last,f.created_at desc nulls last,f.id desc
        limit 1
      ) tf on true
      where t.is_current
      order by t.timesheet_id
    loop
      v_source_update:=v_ref_ts.desired_value;
      v_source_financial_id:=v_ref_ts.financial_id;
      v_source_ib:=v_ref_ts.financial_breakdown;
      v_source_mode:=upper(coalesce(v_source_ib->>'mode',''));
      v_source_payload_schedule:=v_source_update->'actual_schedule_json';
      v_source_canonical_schedule:=v_ref_ts.actual_schedule_json;
      v_source_new_segments:=null;
      v_source_segment_updates:='[]'::jsonb;
      v_source_segment_reference_changed:=false;

      if (v_source_update->>'has_actual_schedule_json')::boolean then
        if jsonb_typeof(v_source_payload_schedule)<>'array' then
          raise exception using errcode='22023',
            message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
            detail=jsonb_build_object(
              'field','actual_schedule_json','reason','ARRAY_REQUIRED',
              'timesheet_id',v_ref_ts.timesheet_id)::text;
        end if;

        if v_source_mode='SEGMENTS' then
          if v_source_financial_id is null
             or jsonb_typeof(v_source_ib->'segments')<>'array' then
            raise exception using errcode='55000',
              message='INVOICE_SOURCE_EDIT_SOURCE_NOT_CURRENT';
          end if;

          v_ref_seen_keys:='{}'::jsonb;
          for v_source_payload_segment,v_source_payload_ord in
            select value,ord
            from jsonb_array_elements(v_source_payload_schedule)
              with ordinality payload(value,ord)
          loop
            if jsonb_typeof(v_source_payload_segment)<>'object' then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','INVALID_SEGMENT',
                  'ordinal',v_source_payload_ord)::text;
            end if;
            select min(field_name) into v_source_unsupported_field
            from jsonb_object_keys(v_source_payload_segment) field_name
            where not (field_name=any(v_allowed_reference_segment_fields));
            if v_source_unsupported_field is not null then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','UNSUPPORTED_FIELD',
                  'unsupported_field',v_source_unsupported_field,
                  'ordinal',v_source_payload_ord)::text;
            end if;
            if not (v_source_payload_segment ? 'ref_num') then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','REFERENCE_REQUIRED',
                  'ordinal',v_source_payload_ord)::text;
            end if;

            v_ref_seg_id:=nullif(btrim(coalesce(
              v_source_payload_segment->>'segment_id','')),'');
            v_source_match_count:=0;
            v_source_match_segment:=null;
            if v_ref_seg_id is not null then
              select count(*),min(seg.value::text)::jsonb
              into v_source_match_count,v_source_match_segment
              from jsonb_array_elements(v_source_ib->'segments') seg(value)
              where nullif(btrim(coalesce(seg.value->>'segment_id','')),'')=v_ref_seg_id
                and nullif(btrim(coalesce(
                  seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text;
            end if;

            if v_source_match_count=0 then
              begin
                v_source_start:=nullif(btrim(coalesce(
                  v_source_payload_segment->>'start_utc',
                  v_source_payload_segment->>'start','')),'')::timestamptz;
                v_source_end:=nullif(btrim(coalesce(
                  v_source_payload_segment->>'end_utc',
                  v_source_payload_segment->>'end','')),'')::timestamptz;
              exception when others then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                  detail=jsonb_build_object(
                    'field','actual_schedule_json','reason','INVALID_SEGMENT_TIME',
                    'ordinal',v_source_payload_ord)::text;
              end;
              if v_source_start is null or v_source_end is null then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                  detail=jsonb_build_object(
                    'field','actual_schedule_json','reason','SEGMENT_IDENTITY_REQUIRED',
                    'ordinal',v_source_payload_ord)::text;
              end if;
              select count(*),min(seg.value::text)::jsonb
              into v_source_match_count,v_source_match_segment
              from jsonb_array_elements(v_source_ib->'segments') seg(value)
              where nullif(btrim(coalesce(
                    seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
                and nullif(btrim(coalesce(
                    seg.value->>'start_utc',seg.value->>'start','')),'')::timestamptz
                    =v_source_start
                and nullif(btrim(coalesce(
                    seg.value->>'end_utc',seg.value->>'end','')),'')::timestamptz
                    =v_source_end;
            end if;

            if v_source_match_count<>1 or v_source_match_segment is null then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts.timesheet_id,
                  'ordinal',v_source_payload_ord,
                  'match_count',v_source_match_count)::text;
            end if;

            v_ref_sched_key:=coalesce(
              'SID:'||nullif(btrim(coalesce(
                v_source_match_segment->>'segment_id','')),''),
              'SE:'||coalesce(v_source_match_segment->>'start_utc',
                v_source_match_segment->>'start','')||'|'||
                coalesce(v_source_match_segment->>'end_utc',
                  v_source_match_segment->>'end',''));
            if v_ref_seen_keys ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts.timesheet_id,
                  'reason','DUPLICATE_IDENTITY')::text;
            end if;
            v_ref_seen_keys:=jsonb_set(
              v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
            v_ref_seg_new_ref:=nullif(btrim(coalesce(
              v_source_payload_segment->>'ref_num','')),'');
            v_source_segment_reference_changed:=
              v_source_segment_reference_changed or (
                nullif(btrim(coalesce(
                  v_source_match_segment->>'ref_num','')),'')
                is distinct from v_ref_seg_new_ref);
            v_source_segment_updates:=v_source_segment_updates||
              jsonb_build_array(jsonb_build_object(
                'segment_id',nullif(btrim(coalesce(
                  v_source_match_segment->>'segment_id','')),''),
                'start_identity',coalesce(v_source_match_segment->>'start_utc',
                  v_source_match_segment->>'start'),
                'end_identity',coalesce(v_source_match_segment->>'end_utc',
                  v_source_match_segment->>'end'),
                'ref_num',v_ref_seg_new_ref));
          end loop;

          v_source_new_segments:='[]'::jsonb;
          for v_source_current_segment in
            select value
            from jsonb_array_elements(v_source_ib->'segments')
              with ordinality current_segment(value,ord)
            order by ord
          loop
            v_source_payload_segment:=null;
            select update_item.value into v_source_payload_segment
            from jsonb_array_elements(v_source_segment_updates) update_item(value)
            where (
              nullif(update_item.value->>'segment_id','') is not null
              and nullif(btrim(coalesce(
                v_source_current_segment->>'segment_id','')),'')
                  =nullif(update_item.value->>'segment_id','')
            ) or (
              nullif(update_item.value->>'segment_id','') is null
              and coalesce(v_source_current_segment->>'start_utc',
                    v_source_current_segment->>'start')
                  is not distinct from update_item.value->>'start_identity'
              and coalesce(v_source_current_segment->>'end_utc',
                    v_source_current_segment->>'end')
                  is not distinct from update_item.value->>'end_identity'
            )
            limit 1;
            if v_source_payload_segment is not null then
              v_source_current_segment:=jsonb_set(
                v_source_current_segment,'{ref_num}',
                coalesce(v_source_payload_segment->'ref_num','null'::jsonb),true);
            end if;
            v_source_new_segments:=v_source_new_segments||
              jsonb_build_array(v_source_current_segment);
          end loop;
        else
          v_source_canonical_schedule:=coalesce(
            v_ref_ts.actual_schedule_json,'[]'::jsonb);
          if jsonb_typeof(v_source_canonical_schedule)<>'array'
             or jsonb_array_length(v_source_payload_schedule)
                <>jsonb_array_length(v_source_canonical_schedule) then
            raise exception using errcode='22023',
              message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
              detail=jsonb_build_object(
                'field','actual_schedule_json','reason','STRUCTURE_MISMATCH',
                'timesheet_id',v_ref_ts.timesheet_id)::text;
          end if;
          v_ref_new_segments:='[]'::jsonb;
          for v_source_payload_segment,v_source_current_segment,v_source_payload_ord in
            select p.value,c.value,p.ord
            from jsonb_array_elements(v_source_payload_schedule)
              with ordinality p(value,ord)
            join jsonb_array_elements(v_source_canonical_schedule)
              with ordinality c(value,ord) using(ord)
            order by p.ord
          loop
            if jsonb_typeof(v_source_payload_segment)<>'object'
               or jsonb_typeof(v_source_current_segment)<>'object'
               or not (v_source_payload_segment ? 'ref_num')
               or (v_source_payload_segment-'ref_num') is distinct from
                  (v_source_current_segment-'ref_num') then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','STRUCTURE_MISMATCH',
                  'ordinal',v_source_payload_ord)::text;
            end if;
            v_ref_new_segments:=v_ref_new_segments||jsonb_build_array(
              jsonb_set(v_source_current_segment,'{ref_num}',
                coalesce(v_source_payload_segment->'ref_num','null'::jsonb),true));
          end loop;
          v_source_canonical_schedule:=v_ref_new_segments;
        end if;
      end if;

      v_source_timesheet_row_changed:=(
        ((v_source_update->>'has_reference_number')::boolean
          and v_ref_ts.reference_number is distinct from
            nullif(btrim(coalesce(v_source_update->>'reference_number','')),''))
        or ((v_source_update->>'has_day_references_json')::boolean
          and v_ref_ts.day_references_json is distinct from
            case when jsonb_typeof(v_source_update->'day_references_json')='null'
              then null else v_source_update->'day_references_json' end)
        or ((v_source_update->>'has_actual_schedule_json')::boolean
          and v_source_mode<>'SEGMENTS'
          and v_ref_ts.actual_schedule_json is distinct from
            v_source_canonical_schedule)
        or ((v_source_update->>'has_hospital_norm')::boolean
          and lower(regexp_replace(
                btrim(coalesce(v_ref_ts.hospital_norm,'')),
                '[[:space:]]+',' ','g')) is distinct from
            coalesce(v_source_update->>'hospital_norm',''))
        or ((v_source_update->>'has_ward_norm')::boolean
          and lower(regexp_replace(
                btrim(coalesce(v_ref_ts.ward_norm,'')),
                '[[:space:]]+',' ','g')) is distinct from
            coalesce(v_source_update->>'ward_norm',''))
      );
      v_source_update:=v_source_update||jsonb_build_object(
        'source_mode',v_source_mode,
        'financial_id',v_source_financial_id,
        'canonical_actual_schedule_json',v_source_canonical_schedule,
        'new_financial_segments',v_source_new_segments,
        'segment_updates',v_source_segment_updates,
        'segment_reference_changed',v_source_segment_reference_changed,
        'timesheet_row_changed',v_source_timesheet_row_changed);
      v_source_updates_map:=jsonb_set(
        v_source_updates_map,array[v_ref_ts.timesheet_id::text],
        v_source_update,true);
    end loop;

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_source_changed_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_row_changed')::boolean
       or (desired.value->>'segment_reference_changed')::boolean;

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_refupd_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_id')::uuid=any(v_source_changed_ts_ids)
      and (
        (desired.value->>'has_reference_number')::boolean
        or (desired.value->>'has_day_references_json')::boolean
        or (
          (desired.value->>'has_actual_schedule_json')::boolean
          and (
            (desired.value->>'timesheet_row_changed')::boolean
            or (desired.value->>'segment_reference_changed')::boolean
          )
        )
      );

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_location_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_row_changed')::boolean
      and (
        (desired.value->>'has_hospital_norm')::boolean
        or (desired.value->>'has_ward_norm')::boolean
      );

    if exists(
      select 1 from jsonb_each(v_source_updates_map) desired
      where (desired.value->>'timesheet_row_changed')::boolean
    ) then
      with desired as materialized(
        select (value->>'timesheet_id')::uuid as timesheet_id,value
        from jsonb_each(v_source_updates_map)
      )
      update public.timesheets t
      set updated_at=v_now,
          reference_number=case when (d.value->>'has_reference_number')::boolean
            then nullif(btrim(coalesce(d.value->>'reference_number','')),'')
            else t.reference_number end,
          day_references_json=case when (d.value->>'has_day_references_json')::boolean
            then case when jsonb_typeof(d.value->'day_references_json')='null'
              then null else d.value->'day_references_json' end
            else t.day_references_json end,
          actual_schedule_json=case
            when (d.value->>'has_actual_schedule_json')::boolean
              and d.value->>'source_mode'<>'SEGMENTS'
            then d.value->'canonical_actual_schedule_json'
            else t.actual_schedule_json end,
          hospital_norm=case when (d.value->>'has_hospital_norm')::boolean
            then coalesce(d.value->>'hospital_norm','') else t.hospital_norm end,
          ward_norm=case when (d.value->>'has_ward_norm')::boolean
            then coalesce(d.value->>'ward_norm','') else t.ward_norm end
      from desired d
      where t.timesheet_id=d.timesheet_id
        and (d.value->>'timesheet_row_changed')::boolean
        and t.is_current;
    end if;

    v_refupd_applied:=cardinality(v_refupd_ts_ids);
    v_location_applied:=cardinality(v_location_ts_ids);

    -- Marker rows exist only where the timesheet statement has already advanced
    -- the source revision and the following SEGMENTS ref update would otherwise
    -- invalidate the same source a second time.
    select coalesce(jsonb_object_agg(
      t.timesheet_id::text,
      jsonb_build_object('expected_revision',t.document_revision)),
      '{}'::jsonb)
    into v_source_marker_rows
    from jsonb_each(v_source_updates_map) desired
    join public.timesheets t
      on t.timesheet_id=(desired.value->>'timesheet_id')::uuid and t.is_current
    where (desired.value->>'timesheet_row_changed')::boolean
      and (desired.value->>'segment_reference_changed')::boolean
      and t.document_revision=
        (desired.value->>'expected_document_revision')::bigint+1;
    if (select count(*) from jsonb_each(v_source_marker_rows))<>(
      select count(*) from jsonb_each(v_source_updates_map) desired
      where (desired.value->>'timesheet_row_changed')::boolean
        and (desired.value->>'segment_reference_changed')::boolean
    ) then
      raise exception using errcode='55000',
        message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
        detail=jsonb_build_object(
          'reason','SOURCE_REVISION_ADVANCE_NOT_EXACT')::text;
    end if;
    v_source_marker:=jsonb_build_object(
      'txid',txid_current()::text,'rows',v_source_marker_rows);
    perform set_config(
      'cloudtms.invoice_source_edit_marker',v_source_marker::text,true);

    -- The legacy per-array loops below remain structurally compatible for old
    -- payload code, but the strict merged statement above is now the sole
    -- execution path for accepted source edits.
    v_reference_updates:=null;
    v_location_updates:=null;
  end if;





  -- 0) Apply reference updates to timesheets (does NOT recompute TSFIN; it updates the source timesheet refs)
  if v_reference_updates is not null and jsonb_typeof(v_reference_updates)='array' and jsonb_array_length(v_reference_updates) > 0 then
    for v_refupd in
      select value from jsonb_array_elements(v_reference_updates) value
    loop
      if v_refupd is null or jsonb_typeof(v_refupd) <> 'object' then
        continue;
      end if;

      if nullif(btrim(coalesce(v_refupd->>'timesheet_id','')), '') is null then
        continue;
      end if;

      v_refupd_ts_id := (v_refupd->>'timesheet_id')::uuid;

      v_refupd_set_refnum := (v_refupd ? 'reference_number');
      v_refupd_set_dayrefs := (v_refupd ? 'day_references_json');
      v_refupd_set_sched := (v_refupd ? 'actual_schedule_json');

      v_refupd_refnum := null;
      if v_refupd_set_refnum then
        v_refupd_refnum := nullif(btrim(coalesce(v_refupd->>'reference_number','')), '');
      end if;

      v_refupd_dayrefs := null;
      if v_refupd_set_dayrefs then
        v_refupd_dayrefs := v_refupd->'day_references_json';
        if v_refupd_dayrefs is not null and jsonb_typeof(v_refupd_dayrefs) = 'null' then
          v_refupd_dayrefs := null;
        end if;
      end if;

      v_refupd_sched := null;
      if v_refupd_set_sched then
        v_refupd_sched := v_refupd->'actual_schedule_json';
        if v_refupd_sched is not null and jsonb_typeof(v_refupd_sched) = 'null' then
          v_refupd_sched := null;
        end if;
      end if;

      update public.timesheets tsu
      set
        updated_at = v_now,
        reference_number = case when v_refupd_set_refnum then v_refupd_refnum else tsu.reference_number end,
        day_references_json = case when v_refupd_set_dayrefs then v_refupd_dayrefs else tsu.day_references_json end,
        actual_schedule_json = case when v_refupd_set_sched then v_refupd_sched else tsu.actual_schedule_json end
      where tsu.timesheet_id = v_refupd_ts_id
        and tsu.is_current = true
        and exists(
          select 1
          from public.invoice_lines owned_line
          where owned_line.invoice_id=p_invoice_id
            and (
              owned_line.timesheet_id=tsu.timesheet_id
              or (
                owned_line.timesheet_id is null
                and coalesce(owned_line.meta_json->>'timesheet_id','')
                  ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                and (owned_line.meta_json->>'timesheet_id')::uuid=tsu.timesheet_id
              )
            )
        )
        and (
          (v_refupd_set_refnum and tsu.reference_number is distinct from v_refupd_refnum)
          or (v_refupd_set_dayrefs and tsu.day_references_json is distinct from v_refupd_dayrefs)
          or (v_refupd_set_sched and tsu.actual_schedule_json is distinct from v_refupd_sched)
        );

      get diagnostics v_rc = row_count;
      if coalesce(v_rc,0) > 0 then
        v_refupd_applied := v_refupd_applied + 1;
        v_refupd_ts_ids := v_refupd_ts_ids || v_refupd_ts_id;
      end if;

    end loop;

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object('step','reference_updates_applied','count_requested',v_refupd_count,'count_applied',v_refupd_applied)
      );
    end if;
  end if;

  -- 0a) Apply only material hospital/ward changes to current timesheets that
  -- are owned by this invoice. Identical canonical values perform no UPDATE,
  -- so they cannot dirty documents or queue replacement work.
  if v_location_updates is not null
     and jsonb_typeof(v_location_updates)='array'
     and jsonb_array_length(v_location_updates)>0 then
    for v_location_update in
      select value from jsonb_array_elements(v_location_updates) value
    loop
      if v_location_update is null
         or jsonb_typeof(v_location_update)<>'object'
         or nullif(btrim(coalesce(v_location_update->>'timesheet_id','')),'') is null then
        continue;
      end if;

      v_location_ts_id := (v_location_update->>'timesheet_id')::uuid;
      v_location_set_hospital := v_location_update ? 'hospital_norm';
      v_location_set_ward := v_location_update ? 'ward_norm';
      if not v_location_set_hospital and not v_location_set_ward then
        continue;
      end if;

      v_location_hospital_norm := null;
      if v_location_set_hospital then
        v_location_hospital_norm := nullif(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'hospital_norm','')),
          '[[:space:]]+',' ','g')), '');
      end if;
      v_location_ward_norm := null;
      if v_location_set_ward then
        v_location_ward_norm := nullif(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'ward_norm','')),
          '[[:space:]]+',' ','g')), '');
      end if;

      update public.timesheets tsu
      set updated_at=v_now,
          hospital_norm=case when v_location_set_hospital
            then v_location_hospital_norm else tsu.hospital_norm end,
          ward_norm=case when v_location_set_ward
            then v_location_ward_norm else tsu.ward_norm end
      where tsu.timesheet_id=v_location_ts_id
        and tsu.is_current=true
        and exists(
          select 1
          from public.invoice_lines owned_line
          where owned_line.invoice_id=p_invoice_id
            and (
              owned_line.timesheet_id=tsu.timesheet_id
              or (
                owned_line.timesheet_id is null
                and coalesce(owned_line.meta_json->>'timesheet_id','')
                  ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                and (owned_line.meta_json->>'timesheet_id')::uuid=tsu.timesheet_id
              )
            )
        )
        and (
          (v_location_set_hospital
            and tsu.hospital_norm is distinct from v_location_hospital_norm)
          or (v_location_set_ward
            and tsu.ward_norm is distinct from v_location_ward_norm)
        );

      get diagnostics v_rc=row_count;
      if coalesce(v_rc,0)>0 then
        v_location_applied:=v_location_applied+1;
        v_location_ts_ids:=v_location_ts_ids||v_location_ts_id;
      end if;
    end loop;

    if v_invoice_debug then
      v_dbg_steps:=v_dbg_steps||jsonb_build_array(jsonb_build_object(
        'step','timesheet_location_updates_applied',
        'count_requested',v_location_count,
        'count_applied',v_location_applied));
    end if;
  end if;
  -- 0b) After reference updates: refresh invoice_lines meta (ts_reference_number / schedule_ref_nums) and
  -- synchronise only the approved ref_num fields into the locked SEGMENTS
  -- financial projection. The full financial objects and their order are
  -- preserved from the locked current snapshot.
  if v_refupd_ts_ids is not null and coalesce(array_length(v_refupd_ts_ids,1),0) > 0 then

    with desired as materialized(
      select value
      from jsonb_each(v_source_updates_map)
      where (value->>'segment_reference_changed')::boolean
    )
    update public.timesheets_financials tf
    set invoice_breakdown_json=jsonb_set(
      coalesce(tf.invoice_breakdown_json,'{}'::jsonb),
      '{segments}',d.value->'new_financial_segments',true)
    from desired d
    where tf.id=(d.value->>'financial_id')::uuid
      and tf.is_current
      and tf.timesheet_id=(d.value->>'timesheet_id')::uuid
      and upper(coalesce(tf.invoice_breakdown_json->>'mode',''))='SEGMENTS'
      and tf.invoice_breakdown_json->'segments'
        is distinct from d.value->'new_financial_segments';
    get diagnostics v_refupd_tsfin_rows_updated=row_count;
    select coalesce(sum(jsonb_array_length(
      coalesce(value->'segment_updates','[]'::jsonb))),0)::integer
    into v_refupd_tsfin_segments_updated
    from jsonb_each(v_source_updates_map)
    where (value->>'segment_reference_changed')::boolean;

    -- The marker has served its single synchronisation statement. Clear it so
    -- no later statement in this transaction can inherit suppression authority.
    perform set_config('cloudtms.invoice_source_edit_marker','{}',true);

    select array_agg(distinct x)
    into v_refupd_ts_ids_distinct
    from unnest(v_refupd_ts_ids) x
    where x is not null;

    v_refupd_ts_ids_distinct := coalesce(v_refupd_ts_ids_distinct, array[]::uuid[]);

    foreach v_ref_ts_id in array v_refupd_ts_ids_distinct loop
      if v_ref_ts_id is null then
        continue;
      end if;

      select tsu.*
      into v_ref_ts
      from public.timesheets tsu
      where tsu.timesheet_id = v_ref_ts_id
        and tsu.is_current = true
      limit 1;

      if not found then
        continue;
      end if;
      v_source_update:=v_source_updates_map->v_ref_ts_id::text;
      v_source_mode:=upper(coalesce(v_source_update->>'source_mode',''));
      v_source_canonical_schedule:=case when v_source_mode='SEGMENTS'
        then coalesce(v_source_update->'new_financial_segments','[]'::jsonb)
        else coalesce(v_ref_ts.actual_schedule_json,'[]'::jsonb) end;

      -- Build the cache from the exact authority used by this invoice. SEGMENTS
      -- refs come from invoice-owned financial segments; other modes use the
      -- structurally preserved timesheet schedule.
      v_ref_schedule_refs := '[]'::jsonb;

      if nullif(btrim(coalesce(v_ref_ts.reference_number,'')), '') is not null then
        v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(nullif(btrim(v_ref_ts.reference_number),'')));
      end if;

      if v_ref_ts.day_references_json is not null and jsonb_typeof(v_ref_ts.day_references_json) = 'object' then
        for kv in
          select key as k, value as v
          from jsonb_each_text(v_ref_ts.day_references_json)
        loop
          if nullif(btrim(coalesce(kv.v,'')), '') is not null then
            v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(nullif(btrim(kv.v),'')));
          end if;
        end loop;
      end if;

      if jsonb_typeof(v_source_canonical_schedule)='array' then
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_source_canonical_schedule) value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            continue;
          end if;
          v_ref_sched_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
          if v_ref_sched_ref is not null then
            v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(v_ref_sched_ref));
          end if;
        end loop;
      end if;

      select coalesce(jsonb_agg(to_jsonb(x) order by x), '[]'::jsonb)
      into v_ref_schedule_refs_distinct
      from (
        select distinct btrim(t.x) as x
        from jsonb_array_elements_text(coalesce(v_ref_schedule_refs,'[]'::jsonb)) as t(x)
        where nullif(btrim(coalesce(t.x,'')), '') is not null
      ) q;

      -- Refresh meta_json on all invoice lines for this timesheet
      update public.invoice_lines ilu
      set meta_json = coalesce(ilu.meta_json, '{}'::jsonb) || jsonb_build_object(
        'ts_reference_number', nullif(btrim(coalesce(v_ref_ts.reference_number,'')), ''),
        'schedule_ref_nums', coalesce(v_ref_schedule_refs_distinct, '[]'::jsonb),
        'schedule_ref_count', jsonb_array_length(coalesce(v_ref_schedule_refs_distinct, '[]'::jsonb))
      )
      where ilu.invoice_id = p_invoice_id
        and (
          ilu.timesheet_id=v_ref_ts_id
          or (
            ilu.timesheet_id is null
            and coalesce(ilu.meta_json->>'timesheet_id','') ~
              '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            and (ilu.meta_json->>'timesheet_id')::uuid=v_ref_ts_id
          )
        )
        and (
          ilu.meta_json->'ts_reference_number' is distinct from
            coalesce(to_jsonb(nullif(btrim(coalesce(v_ref_ts.reference_number,'')),'')),'null'::jsonb)
          or ilu.meta_json->'schedule_ref_nums' is distinct from
            coalesce(v_ref_schedule_refs_distinct,'[]'::jsonb)
          or ilu.meta_json->'schedule_ref_count' is distinct from
            to_jsonb(jsonb_array_length(coalesce(v_ref_schedule_refs_distinct,'[]'::jsonb)))
        );

      get diagnostics v_rc = row_count;
      v_refupd_meta_rows_updated := v_refupd_meta_rows_updated + coalesce(v_rc,0);

      -- Best-effort sync: update tsfin.invoice_breakdown_json segments[].ref_num by matching start/end fields
      v_ref_seg_updates_this_ts := 0;
      v_ref_seg_matches_this_ts := 0;
      v_ref_tsfin_id := null;
      v_ref_ib := null;

        select tfu.id, tfu.invoice_breakdown_json
      into v_ref_tsfin_id, v_ref_ib
      from public.timesheets_financials tfu
      where tfu.timesheet_id = v_ref_ts_id
        and tfu.is_current = true
      limit 1
      for update;


      if v_ref_tsfin_id is not null
         and v_source_mode<>'SEGMENTS'
         and v_ref_ib is not null
         and jsonb_typeof(v_ref_ib) = 'object'
         and upper(coalesce(v_ref_ib->>'mode','')) = 'SEGMENTS'
         and jsonb_typeof(v_ref_ib->'segments') = 'array'
         and v_ref_ts.actual_schedule_json is not null
         and jsonb_typeof(v_ref_ts.actual_schedule_json) = 'array'
       then
         -- Build a map of segment_id (preferred) or start|end -> ref_num from actual_schedule_json
        v_ref_sched_map := '{}'::jsonb;
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_ref_ts.actual_schedule_json) value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            continue;
          end if;

          v_ref_sched_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
          v_ref_seg_id := nullif(btrim(coalesce(v_ref_seg_obj->>'segment_id','')), '');
          if v_ref_seg_id is not null then
            v_ref_sched_key := 'SID:' || v_ref_seg_id;
            if v_ref_sched_map ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                  'side','TIMESHEET_SCHEDULE')::text;
            end if;
            v_ref_sched_map := jsonb_set(v_ref_sched_map, array[v_ref_sched_key], case when v_ref_sched_ref is null then 'null'::jsonb else to_jsonb(v_ref_sched_ref) end, true);
            continue;
          end if;

          v_ref_seg_start := nullif(btrim(coalesce(v_ref_seg_obj->>'start_utc', v_ref_seg_obj->>'start', '')), '');
          v_ref_seg_end := nullif(btrim(coalesce(v_ref_seg_obj->>'end_utc', v_ref_seg_obj->>'end', '')), '');
          if v_ref_seg_start is null or v_ref_seg_end is null then
            continue;
          end if;

          v_ref_sched_key := 'SE:' || v_ref_seg_start || '|' || v_ref_seg_end;
          if v_ref_sched_map ? v_ref_sched_key then
            raise exception using errcode='22023',
              message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
              detail=jsonb_build_object(
                'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                'side','TIMESHEET_SCHEDULE')::text;
          end if;
          v_ref_sched_map := jsonb_set(v_ref_sched_map, array[v_ref_sched_key], case when v_ref_sched_ref is null then 'null'::jsonb else to_jsonb(v_ref_sched_ref) end, true);
        end loop;

        v_ref_new_segments := '[]'::jsonb;
        v_ref_seen_keys := '{}'::jsonb;
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_ref_ib->'segments') value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            v_ref_new_segments := v_ref_new_segments || jsonb_build_array(v_ref_seg_obj);
            continue;
          end if;

          v_ref_seg_new_ref := null;
          v_ref_seg_has_update := false;

          v_ref_seg_id := nullif(btrim(coalesce(v_ref_seg_obj->>'segment_id','')), '');
          if v_ref_seg_id is not null then
            v_ref_sched_key := 'SID:' || v_ref_seg_id;
            if v_ref_seen_keys ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                  'side','FINANCIAL_SEGMENTS')::text;
            end if;
            v_ref_seen_keys:=jsonb_set(v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
            if v_ref_sched_map ? v_ref_sched_key then
              v_ref_seg_new_ref := nullif(btrim(coalesce(v_ref_sched_map->>v_ref_sched_key,'')), '');
              v_ref_seg_has_update := true;
              v_ref_seg_matches_this_ts := v_ref_seg_matches_this_ts + 1;
            end if;
          end if;

          if not v_ref_seg_has_update then
            v_ref_seg_start := nullif(btrim(coalesce(v_ref_seg_obj->>'start_utc', v_ref_seg_obj->>'start', '')), '');
            v_ref_seg_end := nullif(btrim(coalesce(v_ref_seg_obj->>'end_utc', v_ref_seg_obj->>'end', '')), '');

            if v_ref_seg_start is not null and v_ref_seg_end is not null then
              v_ref_sched_key := 'SE:' || v_ref_seg_start || '|' || v_ref_seg_end;
              if v_ref_seen_keys ? v_ref_sched_key then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                  detail=jsonb_build_object(
                    'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                    'side','FINANCIAL_SEGMENTS')::text;
              end if;
              v_ref_seen_keys:=jsonb_set(v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
              if v_ref_sched_map ? v_ref_sched_key then
                v_ref_seg_new_ref := nullif(btrim(coalesce(v_ref_sched_map->>v_ref_sched_key,'')), '');
                v_ref_seg_has_update := true;
                v_ref_seg_matches_this_ts := v_ref_seg_matches_this_ts + 1;
              end if;
            end if;
          end if;

          if v_ref_seg_has_update then
            v_ref_seg_cur_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
            if v_ref_seg_cur_ref is distinct from v_ref_seg_new_ref then
              v_ref_seg_obj := jsonb_set(
                v_ref_seg_obj,
                '{ref_num}',
                case when v_ref_seg_new_ref is null then 'null'::jsonb else to_jsonb(v_ref_seg_new_ref) end,
                true
              );
              v_ref_seg_updates_this_ts := v_ref_seg_updates_this_ts + 1;
            end if;
          end if;

          v_ref_new_segments := v_ref_new_segments || jsonb_build_array(v_ref_seg_obj);
        end loop;



        if v_ref_sched_map is not null
           and jsonb_typeof(v_ref_sched_map) = 'object'
           and v_ref_sched_map <> '{}'::jsonb
           and coalesce(jsonb_array_length(coalesce(v_ref_ib->'segments','[]'::jsonb)),0) > 0
           and coalesce(v_ref_seg_matches_this_ts,0) = 0
        then
          raise exception 'SEGMENTS reference sync failed: no segments matched schedule keys (timesheet_id=% tsfin_id=%)', v_ref_ts_id, v_ref_tsfin_id;
        end if;

        if v_ref_seg_updates_this_ts > 0 then
              update public.timesheets_financials tfu2
          set invoice_breakdown_json = jsonb_set(coalesce(tfu2.invoice_breakdown_json, '{}'::jsonb), '{segments}', v_ref_new_segments, true)
          where tfu2.id = v_ref_tsfin_id
            and tfu2.is_current = true;


          get diagnostics v_rc = row_count;
          if coalesce(v_rc,0) > 0 then
            v_refupd_tsfin_rows_updated := v_refupd_tsfin_rows_updated + 1;
            v_refupd_tsfin_segments_updated := v_refupd_tsfin_segments_updated + v_ref_seg_updates_this_ts;
          end if;
        end if;

      end if;

    end loop;

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','reference_updates_meta_refreshed',
          'timesheets_count', coalesce(array_length(v_refupd_ts_ids_distinct,1),0),
          'invoice_line_rows_updated', v_refupd_meta_rows_updated,
          'tsfin_rows_updated', v_refupd_tsfin_rows_updated,
          'tsfin_segments_refnum_updated', v_refupd_tsfin_segments_updated
        )
      );
    end if;
  end if;

  -- 1) Removals (by invoice_line_id)
  if v_remove_ids is not null and coalesce(array_length(v_remove_ids,1),0) > 0 then
    -- collect timesheet_ids touched (any)
    select array_agg(distinct l.timesheet_id) filter (where l.timesheet_id is not null)
    into v_ts_ids_touched
    from public.invoice_lines l
    where l.invoice_id = p_invoice_id
      and l.id = any(v_remove_ids);

    -- record removed lines for history
    v_hist_lines_removed := coalesce(p_payload->'remove_invoice_line_ids','[]'::jsonb);

    -- Only unlock TSFIN when HOURS lines were removed (prevents accidental unlock when deleting only expenses/other lines)
    -- IMPORTANT: compute BEFORE deletion because we match on the removed invoice_line ids.
    select array_agg(distinct l.timesheet_id) filter (where l.timesheet_id is not null)
    into v_cw_ts_ids
    from public.invoice_lines l
    where l.invoice_id = p_invoice_id
      and l.id = any(v_remove_ids)
      and upper(coalesce(l.meta_json->>'line_type','')) in ('HOURS_WEEKLY','HOURS_DAILY');

    v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);



    if coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
      v_refresh_hr_cache := true;
    end if;
delete from public.invoice_lines
    where invoice_id = p_invoice_id
      and id = any(v_remove_ids);
    get diagnostics v_rc = row_count;
    v_dbg_lines_deleted := v_dbg_lines_deleted + coalesce(v_rc,0);

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','lines_removed',
          'rows_deleted', coalesce(v_rc,0),
          'timesheets_touched', coalesce(array_length(v_ts_ids_touched,1),0),
          'timesheets_to_unlock_count', coalesce(array_length(v_cw_ts_ids,1),0)
        )
      );
    end if;

    -- FIX: if a touched timesheet now has NO remaining invoice_lines on this invoice,
    -- unlock it even if the removed lines were expenses/mileage/additional (expense-only/SEGMENTS-empty case).
    v_ts_ids_fully_removed := array[]::uuid[];
    select array_agg(distinct x)
    into v_ts_ids_fully_removed
    from unnest(coalesce(v_ts_ids_touched, array[]::uuid[])) x
    where x is not null
      and not exists (
        select 1
        from public.invoice_lines l2
        where l2.invoice_id = p_invoice_id
          and l2.timesheet_id = x
      );

    v_ts_ids_fully_removed := coalesce(v_ts_ids_fully_removed, array[]::uuid[]);

    if coalesce(array_length(v_ts_ids_fully_removed,1),0) > 0 then
      -- unlock any segments locked to this invoice (safe no-op for SEGMENTS-empty)
      perform public._inv_unlock_segments_for_invoice(p_invoice_id, v_ts_ids_fully_removed);

      -- clear whole-timesheet lock if it was set for this invoice (SEGMENTS-empty / non-segments / pseudo segment_id null locks)
      update public.timesheets_financials tfu_lock
      set
        locked_by_invoice_id = null,
        locked_at_utc = null,
        updated_at = v_now
      where tfu_lock.is_current = true
        and tfu_lock.timesheet_id = any(v_ts_ids_fully_removed)
        and tfu_lock.locked_by_invoice_id = p_invoice_id;

      get diagnostics v_rc = row_count;
      v_dbg_timesheets_unlocked := v_dbg_timesheets_unlocked + coalesce(v_rc,0);

      v_refresh_hr_cache := true;

      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(
          jsonb_build_object(
            'step','timesheets_unlocked_after_full_removal',
            'timesheets_fully_removed_count', coalesce(array_length(v_ts_ids_fully_removed,1),0),
            'tsfin_rows_unlocked_count', coalesce(v_rc,0)
          )
        );
      end if;
    end if;

    v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);

    if v_cw_ts_ids is not null and coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
      perform public._inv_unlock_segments_for_invoice(p_invoice_id, v_cw_ts_ids);
      v_dbg_timesheets_unlocked := v_dbg_timesheets_unlocked + coalesce(array_length(v_cw_ts_ids,1),0);

      -- Cleanup: if no segments remain on THIS invoice for a touched timesheet, remove ALL remaining invoice lines for that timesheet
      foreach tsid in array v_cw_ts_ids loop
        if tsid is null then continue; end if;

        -- detect if any segments are still locked to THIS invoice
        select tf.*
        into snap
        from public.timesheets_financials tf
        where tf.is_current = true
          and tf.timesheet_id = tsid
        limit 1;

        if not found then
          continue;
        end if;

        segments := '[]'::jsonb;
        if snap.invoice_breakdown_json is not null
           and jsonb_typeof(snap.invoice_breakdown_json)='object'
           and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
           and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
        then
          for v_seg in
            select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
          loop
            if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
              continue;
            end if;
            seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
            if seg_locked = p_invoice_id::text then
              segments := segments || jsonb_build_array(v_seg);
            end if;
          end loop;

          if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
            delete from public.invoice_lines
            where invoice_id = p_invoice_id
              and timesheet_id = tsid;
          end if;
        else
          -- Non-segments: if snapshot is no longer locked to this invoice, remove all remaining invoice lines for this timesheet
          if snap.locked_by_invoice_id is null then
            delete from public.invoice_lines
            where invoice_id = p_invoice_id
              and timesheet_id = tsid;
          end if;
        end if;
      end loop;
    end if;

    -- History event (always)
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_LINES_REMOVED',
      null,
      jsonb_build_object('remove_invoice_line_ids', v_hist_lines_removed, 'timesheet_ids_touched', coalesce(to_jsonb(v_ts_ids_touched), '[]'::jsonb)),
      null,
      p_actor_user_id
    );

  end if;


  -- 1b) Segment edits (SEGMENTS mode only)
-- NOTE: Segment moves are NOT allowed when additional rates OR expenses/mileage exist on the TSFIN snapshot.
-- Payload contract uses tsfin_id + segment_id.
if v_has_seg_ops then

  v_dbg_seg_add_refs := case when v_add_seg_refs is null then 0 else jsonb_array_length(coalesce(v_add_seg_refs,'[]'::jsonb)) end;
  v_dbg_seg_remove_refs := case when v_remove_seg_refs is null then 0 else jsonb_array_length(coalesce(v_remove_seg_refs,'[]'::jsonb)) end;

  if v_invoice_debug then
    v_dbg_steps := v_dbg_steps || jsonb_build_array(
      jsonb_build_object(
        'step','segment_ops_start',
        'add_segment_refs_count', v_dbg_seg_add_refs,
        'remove_segment_refs_count', v_dbg_seg_remove_refs
      )
    );
  end if;

  -- Collect distinct tsfin_ids involved in segment ops
  select array_agg(distinct (x->>'tsfin_id')::uuid)
  into v_seg_tsfin_ids
  from (
    select value as x
    from jsonb_array_elements(coalesce(v_remove_seg_refs,'[]'::jsonb))
    union all
    select value as x
    from jsonb_array_elements(coalesce(v_add_seg_refs,'[]'::jsonb))
  ) u
  where jsonb_typeof(x) = 'object'
    and nullif(btrim(coalesce(x->>'tsfin_id','')), '') is not null;

  v_seg_tsfin_ids := coalesce(v_seg_tsfin_ids, array[]::uuid[]);

  v_dbg_seg_tsfins := coalesce(array_length(v_seg_tsfin_ids,1),0);
  if v_invoice_debug then
    v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','segment_ops_targets','tsfin_count',v_dbg_seg_tsfins));
  end if;

  if coalesce(array_length(v_seg_tsfin_ids,1),0) > 0 then

    -- Validate that each snapshot is current SEGMENTS mode and has NO additional/expenses/mileage
    foreach v_tsfin_id in array v_seg_tsfin_ids loop
      select *
      into snap
      from public.timesheets_financials tf
      where tf.id = v_tsfin_id
      limit 1;

      if not found then
        raise exception 'Segment edit refers to unknown tsfin_id %', v_tsfin_id;
      end if;

      if snap.is_current is not true then
        raise exception 'Segment edit requires current tsfin snapshot (tsfin_id=%)', v_tsfin_id;
      end if;

      if snap.client_id is distinct from v_inv.client_id then
        raise exception 'Segment edit timesheet client mismatch (tsfin_id=%)', v_tsfin_id;
      end if;

      if snap.invoice_breakdown_json is null
         or jsonb_typeof(snap.invoice_breakdown_json) <> 'object'
         or upper(coalesce(snap.invoice_breakdown_json->>'mode','')) <> 'SEGMENTS'
         or jsonb_typeof(snap.invoice_breakdown_json->'segments') <> 'array'
      then
        raise exception 'Segment edit is only supported for SEGMENTS timesheets (tsfin_id=%)', v_tsfin_id;
      end if;

      v_has_additional :=
        public._inv_round2(coalesce(snap.additional_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.additional_charge_ex_vat,0)) <> 0
        or (snap.additional_units_json is not null and jsonb_typeof(snap.additional_units_json)='object' and snap.additional_units_json <> '{}'::jsonb);

      v_has_expense_or_mileage :=
        public._inv_round2(coalesce(snap.expenses_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.expenses_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_units,0)) <> 0
        or public._inv_round2(coalesce(snap.travel_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.travel_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.accommodation_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.accommodation_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.other_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.other_charge_ex_vat,0)) <> 0;

      if v_has_additional then
        raise exception 'Segments cannot be moved when additional rates exist (timesheet_id=% tsfin_id=%)', snap.timesheet_id, v_tsfin_id;
      end if;

      if v_has_expense_or_mileage then
        raise exception 'Segments cannot be moved when expenses or mileage exist (timesheet_id=% tsfin_id=%)', snap.timesheet_id, v_tsfin_id;
      end if;
    end loop;

    -- Validate and apply add_segment_refs (lock selected segments)
    v_seg_refs_to_lock := '[]'::jsonb;
    if v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0 then
      for v_ref in
        select value from jsonb_array_elements(v_add_seg_refs) value
      loop
        if v_ref is null or jsonb_typeof(v_ref) <> 'object' then
          continue;
        end if;

        if nullif(btrim(coalesce(v_ref->>'tsfin_id','')), '') is null then
          continue;
        end if;

        v_tsfin_id := (v_ref->>'tsfin_id')::uuid;
        v_seg_id := nullif(btrim(coalesce(v_ref->>'segment_id','')), '');

        if v_seg_id is null then
          raise exception 'add_segment_refs requires segment_id (tsfin_id=%)', v_tsfin_id;
        end if;

          -- Load snapshot + timesheet + precheck (must be OK)
        select
          tf.*,
          tsr.sheet_scope::text as sheet_scope,
          coalesce(tsr.submission_mode::text,'') as submission_mode,
          tsr.day_references_json,
          tsr.actual_schedule_json,
          tsr.week_ending_date,
          cw.contract_id
        into snap
        from public.timesheets_financials tf
        join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
        left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
        join public.v_ts_invoice_precheck pcv on pcv.timesheet_id = tf.timesheet_id
        where tf.id = v_tsfin_id
          and tf.is_current = true
          and tf.client_id = v_inv.client_id
          and upper(coalesce(pcv.precheck_status,''))
            in ('OK','BLOCK_NO_PDF')
        limit 1;

        if not found then
          raise exception 'Segment add failed eligibility (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        natural_start := (snap.week_ending_date::date - 6);

        -- Locate the segment object
        v_seg := null;
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;
          if nullif(btrim(coalesce(v_seg->>'segment_id','')), '') = v_seg_id then
            exit;
          end if;
          v_seg := null;
        end loop;

        if v_seg is null then
          raise exception 'Segment not found (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
        if seg_locked is not null then
          raise exception 'Segment already invoiced (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        seg_target := nullif(btrim(coalesce(v_seg->>'invoice_target_week_start','')), '')::date;
        seg_ref := btrim(coalesce(v_seg->>'ref_num',''));

        -- segment-level ref gating if required
        select * into pc from public.v_ts_invoice_precheck where timesheet_id = snap.timesheet_id limit 1;
        if pc.require_reference_to_invoice is true and seg_ref = '' then
          raise exception 'Segment missing reference number (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
        end if;

        -- Week eligibility
        if seg_target is null or seg_target = natural_start then
          if v_week_start <> natural_start then
            raise exception 'Segment not eligible for this invoice week (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
        else
          if v_week_start <> seg_target then
            raise exception 'Delayed segment not eligible for this invoice week (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
          if seg_target > v_anchor_ymd then
            raise exception 'Delayed segment cannot be invoiced early (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
        end if;

        v_seg_refs_to_lock := v_seg_refs_to_lock || jsonb_build_array(
          jsonb_build_object(
            'tsfin_id', v_tsfin_id::text,
            'segment_id', v_seg_id
          )
        );
      end loop;

      if jsonb_typeof(v_seg_refs_to_lock) = 'array' and jsonb_array_length(v_seg_refs_to_lock) > 0 then
        perform public._inv_lock_segments_for_invoice(p_invoice_id, v_seg_refs_to_lock);
      end if;
    end if;

      -- Apply remove_segment_refs (unlock selected segments on THIS invoice)
    if v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0 then
      perform public._inv_unlock_segment_refs_for_invoice(p_invoice_id, v_remove_seg_refs::jsonb, p_actor_user_id);
    end if;



    -- History: segment ops (always)
    if v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0 then
      perform public._audit_insert(
        'invoices',
        p_invoice_id::text,
        'INVOICE_SEGMENTS_ADDED',
        null,
        jsonb_build_object('add_segment_refs', v_add_seg_refs),
        null,
        p_actor_user_id
      );
    end if;
    if v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0 then
      perform public._audit_insert(
        'invoices',
        p_invoice_id::text,
        'INVOICE_SEGMENTS_REMOVED',
        null,
        jsonb_build_object('remove_segment_refs', v_remove_seg_refs),
        null,
        p_actor_user_id
      );
    end if;

    -- Rebuild HOURS lines for touched timesheets on this invoice
    select array_agg(distinct tf.timesheet_id)
    into v_seg_ts_ids
    from public.timesheets_financials tf
    where tf.id = any(v_seg_tsfin_ids);

    v_seg_ts_ids := coalesce(v_seg_ts_ids, array[]::uuid[]);

    foreach tsid in array v_seg_ts_ids loop
      if tsid is null then
        continue;
      end if;

      -- Load snapshot + timesheet + contract (no READY_FOR_INVOICE restriction; this is an invoice edit)
      select
        tf.*,
        tsr.booking_id,
        tsr.week_ending_date,
        tsr.reference_number,
        tsr.sheet_scope::text as sheet_scope,
        coalesce(tsr.submission_mode::text,'') as submission_mode,
        tsr.day_references_json,
        tsr.actual_schedule_json,
        cw.contract_id
      into snap
      from public.timesheets_financials tf
      join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
      left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
      where tf.timesheet_id = tsid
        and tf.is_current = true
      limit 1;

      if not found then
        v_dbg_add_timesheets_skipped := v_dbg_add_timesheets_skipped + 1;
        if v_invoice_debug then
          v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_skipped','timesheet_id',tsid::text));
        end if;
        continue;
      end if;

      v_dbg_add_timesheets_found := v_dbg_add_timesheets_found + 1;
      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_loaded','timesheet_id',tsid::text,'tsfin_id',snap.id::text));
      end if;

      select v.r2_key
      into v_exact_timesheet_document_r2_key
      from public.timesheets t
      join public.invoice_document_versions v
        on v.entity_type='TIMESHEET'
       and v.entity_id=t.timesheet_id
       and v.purpose='TIMESHEET'
       and v.source_revision=t.document_revision::text
       and v.status='READY'
       and nullif(v.r2_key,'') is not null
       and nullif(v.sha256,'') is not null
       and coalesce(v.size_bytes,0)>0
       and coalesce(v.page_count,0)>0
      where t.timesheet_id=tsid and t.is_current
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1;


      contract_id := snap.contract_id;
      c_daily_calc := false;
      c_bucket_labels := null;
      c_display_site := null;

      if contract_id is not null then
        select
          nullif(btrim(coalesce(display_site,'')), '')
        into
          c_display_site
        from public.contracts
        where id = contract_id
        limit 1;
      end if;

      v_settings_authority := private._timesheet_settings_authority_frozen_v1(tsid);
      c_daily_calc := coalesce(
        (v_settings_authority#>>'{values,daily_calc_of_invoices}')::boolean,
        false
      );
      c_bucket_labels := case
        when coalesce((v_settings_authority->>'override_client_settings')::boolean,false)
          then v_settings_authority#>'{values,bucket_labels_json}'
        else null
      end;

      if c_bucket_labels is null then
        c_bucket_labels := jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH');
      end if;

      -- Build segment set locked to THIS invoice
      segments := '[]'::jsonb;
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
         and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
      then
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
          if seg_locked = p_invoice_id::text then
            segments := segments || jsonb_build_array(v_seg);
          end if;
        end loop;
      end if;

      if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
        -- If no segments remain on this invoice for this timesheet, remove ALL invoice lines for that timesheet
        delete from public.invoice_lines
        where invoice_id = p_invoice_id
          and timesheet_id = tsid;
        v_dbg_seg_timesheets_removed := v_dbg_seg_timesheets_removed + 1;
        continue;
      end if;

      v_dbg_seg_timesheets_rebuilt := v_dbg_seg_timesheets_rebuilt + 1;

      -- Replace HOURS lines for this timesheet on this invoice
      delete from public.invoice_lines
      where invoice_id = p_invoice_id
        and timesheet_id = tsid
        and upper(coalesce(meta_json->>'line_type','')) in ('HOURS_WEEKLY','HOURS_DAILY');
        -- HOURS lines
        if c_daily_calc then
          -- Daily: group by segment.date
          for r_day in
            with rows as (
              select
                nullif(btrim(coalesce(seg_el->>'date','')), '') as ymd,
                coalesce((seg_el->>'hours_day')::numeric,0)   as h_day,
                coalesce((seg_el->>'hours_night')::numeric,0) as h_night,
                coalesce((seg_el->>'hours_sat')::numeric,0)   as h_sat,
                coalesce((seg_el->>'hours_sun')::numeric,0)   as h_sun,
                coalesce((seg_el->>'hours_bh')::numeric,0)    as h_bh,
                coalesce((seg_el->>'pay_amount')::numeric,0)  as pay_ex,
                coalesce((seg_el->>'charge_amount')::numeric,0) as chg_ex
              from jsonb_array_elements(segments) seg_el
            ),
            agg as (
              select
                ymd,
                sum(rows.h_day)::numeric as hours_day,
                sum(rows.h_night)::numeric as hours_night,
                sum(rows.h_sat)::numeric as hours_sat,
                sum(rows.h_sun)::numeric as hours_sun,
                sum(rows.h_bh)::numeric as hours_bh,
                sum(rows.pay_ex)::numeric as pay_ex,
                sum(rows.chg_ex)::numeric as chg_ex
              from rows
              where ymd is not null and ymd ~ '^\d{4}-\d{2}-\d{2}$'
              group by ymd
            )
            select * from agg order by ymd
          loop
          chg_ex := public._inv_round2(r_day.chg_ex);
if chg_ex = 0 then continue; end if;

if (coalesce(r_day.hours_day,0)+coalesce(r_day.hours_night,0)+coalesce(r_day.hours_sat,0)+coalesce(r_day.hours_sun,0)+coalesce(r_day.hours_bh,0)) = 0 then
  continue;
end if;


            pay_ex := public._inv_round2(r_day.pay_ex);
            margin_ex := public._inv_round2(chg_ex - pay_ex);
            vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
            inc_amt := public._inv_round2(chg_ex + vat_amt);

            line_desc := coalesce(nullif(btrim(coalesce(c_display_site,'')) ,''), ('TS '||tsid::text)) ||
                         ' – '|| r_day.ymd || ' – W/E '|| coalesce(snap.week_ending_date::text,'');

            v_meta := jsonb_build_object(
              'line_type','HOURS_DAILY',
              'timesheet_id', tsid::text,
              'tsfin_id', snap.id::text,
              'candidate_display', coalesce(nullif(btrim(coalesce(c_display_site,'')),''), null),
              'role', c_role,
              'hospital', c_display_site,
              'ward', c_ward_hint,
              'week_ending_date', snap.week_ending_date::text,
              'date', r_day.ymd,
              'bucket_labels', c_bucket_labels
            );

            v_source_key := 'TS:' || tsid::text || ':HOURS:' || r_day.ymd;

            insert into public.invoice_lines(
              invoice_id, timesheet_id, booking_id, description,
              hours_day, hours_night, hours_sat, hours_sun, hours_bh,
              pay_day, pay_night, pay_sat, pay_sun, pay_bh,
              charge_day, charge_night, charge_sat, charge_sun, charge_bh,
              total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
              vat_rate_pct, vat_amount, total_inc_vat,
              paper_ts_r2_key, meta_json, source_key
            )
            values (
              p_invoice_id, tsid, snap.booking_id, line_desc,
              public._inv_round2(r_day.hours_day), public._inv_round2(r_day.hours_night), public._inv_round2(r_day.hours_sat), public._inv_round2(r_day.hours_sun), public._inv_round2(r_day.hours_bh),
              null,null,null,null,null,
              null,null,null,null,null,
              pay_ex, chg_ex, margin_ex,
              v_vat_rate, vat_amt, inc_amt,
              v_exact_timesheet_document_r2_key,
              v_meta,
              v_source_key
            )
            on conflict (invoice_id, source_key) do nothing;
          end loop;
        else
          -- Weekly hours line
          select
            public._inv_round2(coalesce(sum((seg_el->>'hours_day')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_night')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_sat')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_sun')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_bh')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'pay_amount')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'charge_amount')::numeric),0))
          into h_day, h_night, h_sat, h_sun, h_bh, pay_ex, chg_ex
          from jsonb_array_elements(segments) seg_el;

       if chg_ex <> 0 and (coalesce(h_day,0)+coalesce(h_night,0)+coalesce(h_sat,0)+coalesce(h_sun,0)+coalesce(h_bh,0)) <> 0 then
  margin_ex := public._inv_round2(chg_ex - pay_ex);
  vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
  inc_amt := public._inv_round2(chg_ex + vat_amt);

  line_desc := coalesce(nullif(btrim(coalesce(c_display_site,'')) ,''), ('TS '||tsid::text)) ||
               ' – W/E '|| coalesce(snap.week_ending_date::text,'');

  v_meta := jsonb_build_object(
    'line_type','HOURS_WEEKLY',
    'timesheet_id', tsid::text,
    'tsfin_id', snap.id::text,
    'week_ending_date', snap.week_ending_date::text,
    'bucket_labels', c_bucket_labels
  );

  v_source_key := 'TS:' || tsid::text || ':HOURS:WEEK';

  insert into public.invoice_lines(
    invoice_id, timesheet_id, booking_id, description,
    hours_day, hours_night, hours_sat, hours_sun, hours_bh,
    pay_day, pay_night, pay_sat, pay_sun, pay_bh,
    charge_day, charge_night, charge_sat, charge_sun, charge_bh,
    total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
    vat_rate_pct, vat_amount, total_inc_vat,
    paper_ts_r2_key, meta_json, source_key
  )
  values (
    p_invoice_id, tsid, snap.booking_id, line_desc,
    h_day, h_night, h_sat, h_sun, h_bh,
    null,null,null,null,null,
    null,null,null,null,null,
    pay_ex, chg_ex, margin_ex,
    v_vat_rate, vat_amt, inc_amt,
    v_exact_timesheet_document_r2_key,
    v_meta,
    v_source_key
  )
  on conflict (invoice_id, source_key) do nothing;
end if;

        end if;

        -- Additional rates


    end loop;
  end if;
end if;

  -- 2) Add adjustments
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_adjustments') then
    if jsonb_typeof(p_payload->'add_adjustments') = 'array' then
      for adj in
        select value from jsonb_array_elements(p_payload->'add_adjustments') value
      loop
        if adj is null or jsonb_typeof(adj) <> 'object' then
          continue;
        end if;

        v_adj_token := nullif(btrim(coalesce(adj->>'client_token','')), '');
        v_adj_desc  := nullif(btrim(coalesce(adj->>'description','')), '');
        begin
          v_adj_ex := (adj->>'amount_ex_vat')::numeric;
        exception when others then
          v_adj_ex := null;
        end;

        if v_adj_token is null or v_adj_desc is null or v_adj_ex is null then
          continue;
        end if;

        v_adj_vat := public._inv_round2(v_adj_ex * v_vat_rate / 100);
        if v_vat_rate = 0 then v_adj_vat := 0; end if;
        v_adj_inc := public._inv_round2(v_adj_ex + v_adj_vat);

        v_adj_source_key := 'ADJ:' || v_adj_token;

        v_meta := jsonb_build_object(
          'line_type','ADJUSTMENT',
          'client_token', v_adj_token,
          'description', v_adj_desc,
          'amount_ex_vat', public._inv_round2(v_adj_ex),
          'vat_rate_pct', v_vat_rate,
          'vat_chargeable', v_vat_chargeable
        );

        v_hist_adj := v_hist_adj || jsonb_build_array(v_meta);

        insert into public.invoice_lines(
          invoice_id, timesheet_id, booking_id, description,
          hours_day, hours_night, hours_sat, hours_sun, hours_bh,
          pay_day, pay_night, pay_sat, pay_sun, pay_bh,
          charge_day, charge_night, charge_sat, charge_sun, charge_bh,
          total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
          vat_rate_pct, vat_amount, total_inc_vat,
          paper_ts_r2_key, meta_json, source_key
        )
        values (
          p_invoice_id, null, null, v_adj_desc,
          0,0,0,0,0,
          null,null,null,null,null,
          null,null,null,null,null,
          0, public._inv_round2(v_adj_ex), public._inv_round2(v_adj_ex),
          v_vat_rate, v_adj_vat, v_adj_inc,
          null,
          v_meta,
          v_adj_source_key
        )
        on conflict (invoice_id, source_key) do nothing;
      end loop;
    end if;
  end if;

  -- History: adjustments added (always)
  if jsonb_typeof(v_hist_adj)='array' and jsonb_array_length(v_hist_adj) > 0 then
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_ADJUSTMENTS_ADDED',
      null,
      jsonb_build_object('adjustments', v_hist_adj),
      null,
      p_actor_user_id
    );
  end if;


  -- 3) Add timesheets (full parity: hours + additional + expenses + mileage), for THIS invoice week_start
  if v_add_ts_ids is not null and coalesce(array_length(v_add_ts_ids,1),0) > 0 then
    foreach tsid in array v_add_ts_ids loop
      if tsid is null then
        continue;
      end if;

      -- Load snapshot + timesheet + precheck
      select
        tf.*,
        tsr.booking_id,
        tsr.week_ending_date,
        tsr.reference_number,
        tsr.sheet_scope::text as sheet_scope,
        coalesce(tsr.submission_mode::text,'') as submission_mode,
        tsr.day_references_json,
        tsr.actual_schedule_json,
        cw.contract_id
      into snap
      from public.timesheets_financials tf
      join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
      left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
      join public.v_ts_invoice_precheck pcv on pcv.timesheet_id = tf.timesheet_id
      where tf.timesheet_id = tsid
        and tf.is_current = true
        and tf.locked_by_invoice_id is null
        and tf.processing_status = 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
        and upper(coalesce(pcv.precheck_status,''))
          in ('OK','BLOCK_NO_PDF')
        and tf.client_id = v_inv.client_id
        and (
          pcv.require_reference_to_invoice is not true
          or public._inv_timesheet_has_invoice_reference(
                tsr.sheet_scope::text,
                coalesce(tsr.submission_mode::text,''),
                tsr.reference_number,
                tsr.day_references_json,
                tsr.actual_schedule_json
             )
        )
      limit 1;

      if not found then
        v_dbg_add_timesheets_skipped := v_dbg_add_timesheets_skipped + 1;
        if v_invoice_debug then
          v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_skipped','timesheet_id',coalesce(tsid::text,'')));
        end if;
        continue;
      end if;

      v_dbg_add_timesheets_found := v_dbg_add_timesheets_found + 1;
      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_loaded','timesheet_id',coalesce(tsid::text,''),'tsfin_id',coalesce(snap.id::text,'')));
      end if;

      select v.r2_key
      into v_exact_timesheet_document_r2_key
      from public.timesheets t
      join public.invoice_document_versions v
        on v.entity_type='TIMESHEET'
       and v.entity_id=t.timesheet_id
       and v.purpose='TIMESHEET'
       and v.source_revision=t.document_revision::text
       and v.status='READY'
       and nullif(v.r2_key,'') is not null
       and nullif(v.sha256,'') is not null
       and coalesce(v.size_bytes,0)>0
       and coalesce(v.page_count,0)>0
      where t.timesheet_id=tsid and t.is_current
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1;
      contract_id := snap.contract_id;
      c_daily_calc := false;
      c_bucket_labels := null;
      c_role := null;
      c_display_site := null;
      c_ward_hint := null;

      if contract_id is not null then
        select
          nullif(btrim(coalesce(role,'')), ''),
          nullif(btrim(coalesce(display_site,'')), ''),
          nullif(btrim(coalesce(ward_hint,'')), '')
        into
          c_role, c_display_site, c_ward_hint
        from public.contracts
        where id = contract_id
        limit 1;
      end if;

      v_settings_authority := private._timesheet_settings_authority_frozen_v1(tsid);
      c_daily_calc := coalesce(
        (v_settings_authority#>>'{values,daily_calc_of_invoices}')::boolean,
        false
      );
      c_bucket_labels := case
        when coalesce((v_settings_authority->>'override_client_settings')::boolean,false)
          then v_settings_authority#>'{values,bucket_labels_json}'
        else null
      end;

      if c_bucket_labels is null then
        c_bucket_labels := jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH');
      end if;

      natural_start := (snap.week_ending_date::date - 6);

      segments := '[]'::jsonb;

      -- Build invoiceable segment set for THIS invoice week_start
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
         and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
      then
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
          if seg_locked is not null then
            continue; -- already invoiced
          end if;

          seg_target := nullif(btrim(coalesce(v_seg->>'invoice_target_week_start','')), '')::date;
          seg_ref := btrim(coalesce(v_seg->>'ref_num',''));

          -- segment-level ref gating if required
          select * into pc from public.v_ts_invoice_precheck where timesheet_id = tsid limit 1;
          if pc.require_reference_to_invoice is true and seg_ref = '' then
            continue;
          end if;

          -- delayed detection
          if seg_target is null or seg_target = natural_start then
            -- not delayed: belongs to natural week only
            if v_week_start <> natural_start then
              continue;
            end if;
            -- allow early is implicit for invoice edits (invoice is already being edited)
            segments := segments || jsonb_build_array(v_seg);
          else
            -- delayed: only if this invoice week matches target AND target has arrived (no early invoicing for delayed)
            if v_week_start = seg_target and seg_target <= v_anchor_ymd then
              segments := segments || jsonb_build_array(v_seg);
            end if;
          end if;
        end loop;
      else
        -- Non-segments: include only when invoice week matches natural week
        if v_week_start = natural_start then
          segments := jsonb_build_array(
            jsonb_build_object(
              'segment_id', null,
              'date', coalesce(snap.week_ending_date::text, v_week_start::text),
              'hours_day', public._inv_round2(coalesce(snap.hours_day,0)),
              'hours_night', public._inv_round2(coalesce(snap.hours_night,0)),
              'hours_sat', public._inv_round2(coalesce(snap.hours_sat,0)),
              'hours_sun', public._inv_round2(coalesce(snap.hours_sun,0)),
              'hours_bh', public._inv_round2(coalesce(snap.hours_bh,0)),
              'pay_amount', public._inv_round2(
                coalesce(snap.total_pay_ex_vat,0)
                - coalesce(snap.additional_pay_ex_vat,0)
                - coalesce(snap.expenses_pay_ex_vat,0)
                - coalesce(snap.mileage_pay_ex_vat,0)
              ),
              'charge_amount', public._inv_round2(
                coalesce(snap.total_charge_ex_vat,0)
                - coalesce(snap.additional_charge_ex_vat,0)
                - coalesce(snap.expenses_charge_ex_vat,0)
                - coalesce(snap.mileage_charge_ex_vat,0)
              ),
              'ref_num', coalesce(snap.reference_number,'')
            )
          );
        end if;
      end if;

      if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
        continue;
      end if;

      -- Build the exact invoice-line economics from the frozen current financial snapshot.
      -- This mirrors Invoice Async V8 generation and never derives economics from mutable live rows.
      select p.vat_rate
      into v_vat_rate
      from private._invoice_generation_vat_policy_batch(jsonb_build_array(jsonb_build_object(
        'source_member_key','invoice-edit:'||tsid::text,
        'source_type','TIMESHEET',
        'source_id',tsid,
        'timesheet_id',tsid,
        'effective_date',snap.week_ending_date
      ))) p
      where p.source_member_key='invoice-edit:'||tsid::text
        and p.valid
        and p.vat_rate is not null
      limit 1;

      if not found then
        raise exception 'INVOICE_EDIT_VAT_POLICY_UNRESOLVED'
          using errcode='P0001',detail=jsonb_build_object(
            'invoice_id',p_invoice_id,'timesheet_id',tsid)::text;
      end if;

      insert into public.invoice_lines(
        invoice_id,timesheet_id,booking_id,description,
        hours_day,hours_night,hours_sat,hours_sun,hours_bh,
        pay_day,pay_night,pay_sat,pay_sun,pay_bh,
        charge_day,charge_night,charge_sat,charge_sun,charge_bh,
        total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,
        vat_rate_pct,vat_amount,total_inc_vat,
        paper_ts_r2_key,meta_json,source_key
      )
      with base as materialized (
        select coalesce(
          (select nullif(btrim(coalesce(cd.display_name,'')),'')
             from public.candidates cd where cd.id=snap.candidate_id limit 1),
          'TS '||tsid::text
        ) candidate_display
      ),
      segment_rows as materialized (
        select
          case when left(coalesce(s.value->>'date',''),10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
            then left(s.value->>'date',10) end work_date,
          case when pg_input_is_valid(s.value->>'hours_day','numeric') then (s.value->>'hours_day')::numeric else 0 end h_day,
          case when pg_input_is_valid(s.value->>'hours_night','numeric') then (s.value->>'hours_night')::numeric else 0 end h_night,
          case when pg_input_is_valid(s.value->>'hours_sat','numeric') then (s.value->>'hours_sat')::numeric else 0 end h_sat,
          case when pg_input_is_valid(s.value->>'hours_sun','numeric') then (s.value->>'hours_sun')::numeric else 0 end h_sun,
          case when pg_input_is_valid(s.value->>'hours_bh','numeric') then (s.value->>'hours_bh')::numeric else 0 end h_bh,
          case
            when pg_input_is_valid(s.value->>'pay_amount','numeric') then (s.value->>'pay_amount')::numeric
            when pg_input_is_valid(s.value->>'pay_ex_vat','numeric') then (s.value->>'pay_ex_vat')::numeric
            else 0 end pay_ex,
          case
            when pg_input_is_valid(s.value->>'charge_amount','numeric') then (s.value->>'charge_amount')::numeric
            when pg_input_is_valid(s.value->>'charge_ex_vat','numeric') then (s.value->>'charge_ex_vat')::numeric
            else 0 end charge_ex
        from jsonb_array_elements(segments) s(value)
      ),
      hour_daily as materialized (
        select s.work_date,sum(s.h_day) h_day,sum(s.h_night) h_night,sum(s.h_sat) h_sat,
          sum(s.h_sun) h_sun,sum(s.h_bh) h_bh,sum(s.pay_ex) pay_ex,sum(s.charge_ex) charge_ex
        from segment_rows s
        where c_daily_calc and s.work_date is not null
        group by s.work_date
      ),
      hour_weekly as materialized (
        select sum(s.h_day) h_day,sum(s.h_night) h_night,sum(s.h_sat) h_sat,
          sum(s.h_sun) h_sun,sum(s.h_bh) h_bh,sum(s.pay_ex) pay_ex,sum(s.charge_ex) charge_ex
        from segment_rows s
        having not c_daily_calc or not exists(select 1 from segment_rows d where d.work_date is not null)
      ),
      additional_source as materialized (
        select upper(a.key) code,a.value unit
        from jsonb_each(case when jsonb_typeof(snap.additional_units_json)='object'
          then snap.additional_units_json else '{}'::jsonb end) a
        where jsonb_typeof(a.value)='object' and btrim(a.key)<>''
      ),
      additional_daily as materialized (
        select a.code,left(d.key,10) work_date,
          case when pg_input_is_valid(d.value,'numeric') then d.value::numeric else 0 end units,
          case when pg_input_is_valid(a.unit->>'pay_rate','numeric') then (a.unit->>'pay_rate')::numeric else 0 end pay_rate,
          case when pg_input_is_valid(a.unit->>'charge_rate','numeric') then (a.unit->>'charge_rate')::numeric else 0 end charge_rate,
          coalesce(nullif(a.unit->>'bucket_name',''),a.code) bucket_name,
          coalesce(nullif(a.unit->>'unit_name',''),'units') unit_name,
          a.unit->'frequency' frequency
        from additional_source a
        cross join lateral jsonb_each_text(case when jsonb_typeof(a.unit->'days')='object'
          then a.unit->'days' else '{}'::jsonb end) d
        where c_daily_calc
          and left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
          and pg_input_is_valid(d.value,'numeric')
          and d.value::numeric<>0
          and exists(select 1 from segment_rows where work_date is not null)
      ),
      additional_weekly as materialized (
        select a.code,
          case when pg_input_is_valid(a.unit->>'unit_count','numeric') then (a.unit->>'unit_count')::numeric else 0 end units,
          case when pg_input_is_valid(a.unit->>'pay_rate','numeric') then (a.unit->>'pay_rate')::numeric else 0 end pay_rate,
          case when pg_input_is_valid(a.unit->>'charge_rate','numeric') then (a.unit->>'charge_rate')::numeric else 0 end charge_rate,
          case when pg_input_is_valid(a.unit->>'pay_ex_vat','numeric') then (a.unit->>'pay_ex_vat')::numeric else 0 end pay_ex,
          case when pg_input_is_valid(a.unit->>'charge_ex_vat','numeric') then (a.unit->>'charge_ex_vat')::numeric else 0 end charge_ex,
          coalesce(nullif(a.unit->>'bucket_name',''),a.code) bucket_name,
          coalesce(nullif(a.unit->>'unit_name',''),'units') unit_name,
          a.unit->'frequency' frequency
        from additional_source a
        where not(c_daily_calc
          and exists(select 1 from jsonb_each_text(case when jsonb_typeof(a.unit->'days')='object'
            then a.unit->'days' else '{}'::jsonb end) d
            where left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(d.value,'numeric') and d.value::numeric<>0))
          and (
            (case when pg_input_is_valid(a.unit->>'pay_ex_vat','numeric') then (a.unit->>'pay_ex_vat')::numeric else 0 end)<>0
            or (case when pg_input_is_valid(a.unit->>'charge_ex_vat','numeric') then (a.unit->>'charge_ex_vat')::numeric else 0 end)<>0
          )
      ),
      expense_lines as materialized (
        select e.code,e.pay_ex,e.charge_ex
        from (values
          ('TRAVEL',coalesce(snap.travel_pay_ex_vat,0),coalesce(snap.travel_charge_ex_vat,0)),
          ('ACCOMMODATION',coalesce(snap.accommodation_pay_ex_vat,0),coalesce(snap.accommodation_charge_ex_vat,0)),
          ('OTHER',coalesce(snap.other_pay_ex_vat,0),coalesce(snap.other_charge_ex_vat,0)),
          ('EXPENSES_FALLBACK',
            case when coalesce(snap.travel_pay_ex_vat,0)+coalesce(snap.accommodation_pay_ex_vat,0)+coalesce(snap.other_pay_ex_vat,0)=0
              then coalesce(snap.expenses_pay_ex_vat,0) else 0 end,
            case when coalesce(snap.travel_charge_ex_vat,0)+coalesce(snap.accommodation_charge_ex_vat,0)+coalesce(snap.other_charge_ex_vat,0)=0
              then coalesce(snap.expenses_charge_ex_vat,0) else 0 end),
          ('MILEAGE',coalesce(snap.mileage_pay_ex_vat,0),coalesce(snap.mileage_charge_ex_vat,0))
        ) e(code,pay_ex,charge_ex)
        where e.pay_ex<>0 or e.charge_ex<>0
      ),
      line_union as materialized (
        select b.candidate_display||' - '||h.work_date||' - W/E '||coalesce(snap.week_ending_date::text,'' ) description,
          h.h_day,h.h_night,h.h_sat,h.h_sun,h.h_bh,h.pay_ex,h.charge_ex,
          'HOURS_DAILY' line_type,'TS:'||tsid::text||':HOURS:'||h.work_date source_key,
          jsonb_build_object('date',h.work_date) detail
        from hour_daily h cross join base b
        union all
        select b.candidate_display||' - W/E '||coalesce(snap.week_ending_date::text,''),
          h.h_day,h.h_night,h.h_sat,h.h_sun,h.h_bh,h.pay_ex,h.charge_ex,
          'HOURS_WEEKLY','TS:'||tsid::text||':HOURS:WEEK','{}'::jsonb
        from hour_weekly h cross join base b
        union all
        select b.candidate_display||' - '||a.bucket_name||' - '||a.work_date||' - '||a.units||' '||a.unit_name,
          0,0,0,0,0,round(a.units*a.pay_rate,2),round(a.units*a.charge_rate,2),
          'ADDITIONAL_RATE_DAILY','TS:'||tsid::text||':ADD:'||a.code||':'||a.work_date,
          jsonb_build_object('date',a.work_date,'bucket',jsonb_build_object(
            'code',a.code,'bucket_name',a.bucket_name,'unit_name',a.unit_name,'frequency',a.frequency),
            'units',jsonb_build_object('unit_count',a.units,'pay_rate',a.pay_rate,'charge_rate',a.charge_rate))
        from additional_daily a cross join base b
        union all
        select b.candidate_display||' - '||a.bucket_name||' - '||a.units||' '||a.unit_name,
          0,0,0,0,0,a.pay_ex,a.charge_ex,
          'ADDITIONAL_RATE','TS:'||tsid::text||':ADD:'||a.code||':WEEK',
          jsonb_build_object('bucket',jsonb_build_object(
            'code',a.code,'bucket_name',a.bucket_name,'unit_name',a.unit_name,'frequency',a.frequency),
            'units',jsonb_build_object('unit_count',a.units,'pay_rate',a.pay_rate,'charge_rate',a.charge_rate))
        from additional_weekly a cross join base b
        union all
        select case when e.code='MILEAGE' then 'Mileage - '||coalesce(snap.mileage_units,0)||' miles (W/E '||coalesce(snap.week_ending_date::text,'')||')'
          when e.code='EXPENSES_FALLBACK' then 'Expenses (W/E '||coalesce(snap.week_ending_date::text,'')||')'
          else initcap(replace(e.code,'_',' '))||' expenses (W/E '||coalesce(snap.week_ending_date::text,'')||')' end,
          0,0,0,0,0,e.pay_ex,e.charge_ex,
          case when e.code='MILEAGE' then 'MILEAGE'
            when e.code='EXPENSES_FALLBACK' then 'EXPENSES_TOTAL'
            else 'EXPENSE_'||e.code end,
          case when e.code='MILEAGE' then 'TS:'||tsid::text||':MILEAGE'
            when e.code='EXPENSES_FALLBACK' then 'TS:'||tsid::text||':EXP:TOTAL'
            else 'TS:'||tsid::text||':EXP:'||e.code end,
          jsonb_build_object('expense',case when e.code='MILEAGE' then jsonb_build_object(
            'category','MILEAGE','mileage_units',snap.mileage_units,
            'pay_rate',snap.mileage_pay_rate,'charge_rate',snap.mileage_charge_rate,
            'evidence_r2_key',snap.mileage_evidence_r2_key,'evidence_manifest',snap.mileage_evidence_manifest)
            else jsonb_build_object('category',e.code,'note',snap.expenses_description,
              'evidence_r2_key',snap.expenses_evidence_r2_key,'evidence_manifest',snap.expenses_evidence_manifest) end)
        from expense_lines e
      )
      select p_invoice_id,tsid,snap.booking_id,l.description,
        round(l.h_day,2),round(l.h_night,2),round(l.h_sat,2),round(l.h_sun,2),round(l.h_bh,2),
        null,null,null,null,null,
        snap.charge_day,snap.charge_night,snap.charge_sat,snap.charge_sun,snap.charge_bh,
        round(l.pay_ex,2),round(l.charge_ex,2),round(l.charge_ex-l.pay_ex,2),v_vat_rate,
        round(l.charge_ex*v_vat_rate/100,2),round(l.charge_ex+(l.charge_ex*v_vat_rate/100),2),
        v_exact_timesheet_document_r2_key,
        jsonb_build_object('line_type',l.line_type,'timesheet_id',tsid,'tsfin_id',snap.id,
          'candidate_display',l.description,'week_ending_date',snap.week_ending_date,
          'role',c_role,'hospital',c_display_site,'ward',c_ward_hint,'bucket_labels',c_bucket_labels,
          'totals',jsonb_build_object('line_pay_ex_vat',round(l.pay_ex,2),
            'line_charge_ex_vat',round(l.charge_ex,2),'margin_ex_vat',round(l.charge_ex-l.pay_ex,2),
            'vat_rate_pct',v_vat_rate,'vat_amount',round(l.charge_ex*v_vat_rate/100,2),
            'total_inc_vat',round(l.charge_ex+(l.charge_ex*v_vat_rate/100),2)))||l.detail,
        l.source_key
      from line_union l
      on conflict(invoice_id,source_key) do nothing;
      -- Build segment refs to lock
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
      then
        for v_seg in
          select value from jsonb_array_elements(segments) value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_refs := seg_refs || jsonb_build_array(
            jsonb_build_object(
              'tsfin_id', snap.id::text,
              'segment_id', nullif(btrim(coalesce(v_seg->>'segment_id','')), '')
            )
          );
        end loop;
      else
        -- lock whole for non-segments
        seg_refs := seg_refs || jsonb_build_array(
          jsonb_build_object('tsfin_id', snap.id::text, 'segment_id', null)
        );
      end if;
    end loop;

    -- Apply segment locks for the exact selected source rows.
    if jsonb_typeof(seg_refs) = 'array' and jsonb_array_length(seg_refs) > 0 then
      perform public._inv_lock_segments_for_invoice(p_invoice_id, seg_refs);
    end if;

    -- History: timesheets added (always; includes requested ids)
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_TIMESHEETS_ADDED',
      null,
      jsonb_build_object('add_timesheet_ids', coalesce(to_jsonb(v_add_ts_ids), '[]'::jsonb)),
      null,
      p_actor_user_id
    );
  end if;

  -- 3c) Contract week status: set INVOICED only when timesheet is FULLY invoiced (segment-aware), and revert INVOICED -> AUTHORISED if no longer fully invoiced.
  -- Touch set = union of: add_timesheet_ids, line-removal touched (hours), segment-op touched.
  v_cw_ts_ids := array[]::uuid[];
  if v_add_ts_ids is not null and coalesce(array_length(v_add_ts_ids,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_add_ts_ids;
  end if;
  if v_ts_ids_touched is not null and coalesce(array_length(v_ts_ids_touched,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_ts_ids_touched;
  end if;
  if v_seg_ts_ids is not null and coalesce(array_length(v_seg_ts_ids,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_seg_ts_ids;
  end if;

  -- de-dup
  select array_agg(distinct x)
  into v_cw_ts_ids
  from unnest(coalesce(v_cw_ts_ids, array[]::uuid[])) x
  where x is not null;

  v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);

  if coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
    with src as (
      select
        cw.timesheet_id,
        cw.status as cw_status,
        tf.locked_by_invoice_id,
        tf.invoice_breakdown_json,
        (
          case
            when tf.invoice_breakdown_json is not null
             and jsonb_typeof(tf.invoice_breakdown_json)='object'
             and coalesce(tf.invoice_breakdown_json->>'mode','')='SEGMENTS'
             and jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
             and jsonb_array_length(tf.invoice_breakdown_json->'segments') > 0
            then
              not exists (
                select 1
                from jsonb_array_elements(tf.invoice_breakdown_json->'segments') s(seg)
                where nullif(btrim(coalesce(s.seg->>'invoice_locked_invoice_id','')), '') is null
              )
            else
              (tf.locked_by_invoice_id is not null)
          end
        ) as fully_invoiced
      from public.contract_weeks cw
      join public.timesheets_financials tf
        on tf.is_current = true
       and tf.timesheet_id = cw.timesheet_id
      where cw.timesheet_id = any(v_cw_ts_ids)
    )
    update public.contract_weeks cw
    set status = case
      when src.fully_invoiced then 'INVOICED'::public.contract_week_status_enum
      when cw.status = 'INVOICED'::public.contract_week_status_enum then 'AUTHORISED'::public.contract_week_status_enum
      else cw.status
    end
    from src
    where cw.timesheet_id = src.timesheet_id;
  end if;


  -- 4) Recompute invoice totals from invoice_lines and clear PDF key
  select
    public._inv_round2(coalesce(sum(coalesce(l.total_charge_ex_vat,0)),0)),
    public._inv_round2(coalesce(sum(coalesce(l.vat_amount,0)),0)),
    public._inv_round2(coalesce(sum(coalesce(l.total_inc_vat,0)),0))
  into v_new_ex, v_new_vat, v_new_inc
  from public.invoice_lines l
  where l.invoice_id = p_invoice_id;


  perform public.invoice_recompute_totals(p_invoice_id);

  -- Recompute header_snapshot_json.meta counters to avoid stale values after edits
  select count(distinct l.timesheet_id)
  into v_hdr_ts_count_lines
  from public.invoice_lines l
  where l.invoice_id = p_invoice_id
    and l.timesheet_id is not null;

  select count(*)
  into v_hdr_seg_locked_count
  from public.timesheets_financials tf
  cross join lateral jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) as seg(seg_obj)
  where tf.is_current = true
    and coalesce(seg.seg_obj->>'invoice_locked_invoice_id','') = p_invoice_id::text;

  select count(distinct tf.timesheet_id)
  into v_hdr_ts_count_seglocks
  from public.timesheets_financials tf
  where tf.is_current = true
    and exists (
      select 1
      from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) as seg(seg_obj)
      where coalesce(seg.seg_obj->>'invoice_locked_invoice_id','') = p_invoice_id::text
    );

  if coalesce(v_hdr_seg_locked_count,0) > 0 then
    v_hdr_meta_timesheet_count := coalesce(v_hdr_ts_count_seglocks,0);
    v_hdr_meta_segment_count := coalesce(v_hdr_seg_locked_count,0);
  else
    v_hdr_meta_timesheet_count := coalesce(v_hdr_ts_count_lines,0);
    v_hdr_meta_segment_count := coalesce(v_hdr_meta_timesheet_count,0);
  end if;

  -- The statement triggers are the sole document/issue invalidation authority.
  -- This update changes only the authoritative business snapshot counters.
  update public.invoices invu
  set header_snapshot_json=jsonb_set(jsonb_set(coalesce(invu.header_snapshot_json,'{}'::jsonb),
      '{meta,timesheet_count}',to_jsonb(v_hdr_meta_timesheet_count),true),
      '{meta,segment_count}',to_jsonb(v_hdr_meta_segment_count),true),
    updated_at=now()
  where invu.id=p_invoice_id;

-- Refresh invoice-level NHSP/HR cache after timesheet/segment changes
  if coalesce(v_refresh_hr_cache,false) = true then
    perform 1
    from public.invoice_source_rows_collect(p_invoice_id, true) sr
    limit 1;
  end if;

  -- Revalidate ownership after every line and segment move in this Save. A
  -- source edit must not queue work for a source that was detached later in the
  -- same transaction, and every edited SEGMENTS identity must still be locked
  -- to this exact invoice.
  if cardinality(v_source_changed_ts_ids)>0 and exists(
    select 1
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_id')::uuid=any(v_source_changed_ts_ids)
      and not exists(
        select 1 from public.invoice_lines carrier
        where carrier.invoice_id=p_invoice_id
          and (
            carrier.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              carrier.timesheet_id is null
              and coalesce(carrier.meta_json->>'timesheet_id','')~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (carrier.meta_json->>'timesheet_id')::uuid=
                (desired.value->>'timesheet_id')::uuid
            )
          )
      )
      and not exists(
        select 1
        from public.timesheets_financials tf
        cross join lateral jsonb_array_elements(
          coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) seg(value)
        where tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
          and tf.is_current
          and nullif(btrim(coalesce(
            seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
      )
  ) then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND',
      detail=jsonb_build_object('reason','POST_EDIT_SOURCE_DETACHED')::text;
  end if;

  if cardinality(v_source_changed_ts_ids)>0 and exists(
    select 1
    from jsonb_each(v_source_updates_map) desired
    cross join lateral jsonb_array_elements(
      coalesce(desired.value->'segment_updates','[]'::jsonb)) requested(value)
    where desired.value->>'source_mode'='SEGMENTS'
      and not exists(
        select 1
        from public.timesheets_financials tf
        cross join lateral jsonb_array_elements(
          coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) seg(value)
        where tf.id=(desired.value->>'financial_id')::uuid
          and tf.is_current
          and tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
          and nullif(btrim(coalesce(
            seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
          and (
            (
              nullif(requested.value->>'segment_id','') is not null
              and nullif(btrim(coalesce(seg.value->>'segment_id','')),'')
                =nullif(requested.value->>'segment_id','')
            ) or (
              nullif(requested.value->>'segment_id','') is null
              and coalesce(seg.value->>'start_utc',seg.value->>'start')
                is not distinct from requested.value->>'start_identity'
              and coalesce(seg.value->>'end_utc',seg.value->>'end')
                is not distinct from requested.value->>'end_identity'
            )
          )
      )
  ) then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND',
      detail=jsonb_build_object('reason','POST_EDIT_SEGMENT_DETACHED')::text;
  end if;

  -- A material source edit always starts or reuses the exact replacement
  -- timesheet work. Replacement of an existing invoice preview is derived from
  -- the locked pre-edit V8 state; browser flags cannot suppress it.
  if cardinality(v_source_changed_ts_ids)>0 then
    select coalesce(jsonb_agg(jsonb_build_object(
      'command_type','VIEW_TIMESHEET_DOCUMENT',
      'timesheet_id',changed_id,
      'purpose','TIMESHEET',
      'priority_reason','SOURCE_EDIT_REPLACEMENT',
      'template_version','timesheet-professional-v2')
      order by changed_id),'[]'::jsonb)
    into v_document_commands
    from unnest(v_source_changed_ts_ids) changed_id;

    v_source_edit_invoice_replacement_required:=
      v_source_edit_preexisting_preview
      or lower(coalesce(p_payload->>'request_preview','false'))
           in('true','1','yes','on');
    if v_source_edit_invoice_replacement_required then
      v_document_commands:=v_document_commands||jsonb_build_array(
        jsonb_build_object(
          'command_type','VIEW_INVOICE_DOCUMENT',
          'invoice_id',p_invoice_id,
          'purpose','DRAFT_PREVIEW',
          'priority_reason',case when v_source_edit_preexisting_preview
            then 'SOURCE_EDIT_REPLACEMENT' else 'VIEW_NOW' end,
          'template_version','invoice-professional-v2'));
    end if;

    v_expected_command_count:=jsonb_array_length(v_document_commands);
    if v_expected_command_count>1000 then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_TOO_MANY_REPLACEMENTS';
    end if;

    v_started_operations:=public.invoice_operation_start_batch(
      v_document_commands,p_actor_user_id,v_now);

    if jsonb_typeof(v_started_operations)<>'array'
       or jsonb_array_length(v_started_operations)<>v_expected_command_count then
      raise exception using errcode='55000',
        message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
        detail=jsonb_build_object(
          'reason','RESULT_COUNT',
          'expected',v_expected_command_count,
          'actual',case when jsonb_typeof(v_started_operations)='array'
            then jsonb_array_length(v_started_operations) else null end)::text;
    end if;

    for v_command_no in 1..v_expected_command_count loop
      select value into v_operation_result
      from jsonb_array_elements(v_started_operations) value
      where coalesce(value->>'command_no','')~'^[1-9][0-9]*$'
        and (value->>'command_no')::int=v_command_no;

      if not found or (
        select count(*)
        from jsonb_array_elements(v_started_operations) value
        where coalesce(value->>'command_no','')~'^[1-9][0-9]*$'
          and (value->>'command_no')::int=v_command_no
      )<>1 then
        raise exception using errcode='55000',
          message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
          detail=jsonb_build_object('reason','COMMAND_NO','command_no',v_command_no)::text;
      end if;

      v_source_update:=v_document_commands->(v_command_no-1);
      v_command_type:=v_source_update->>'command_type';
      if v_operation_result->>'command_type' is distinct from v_command_type
         or lower(coalesce(v_operation_result->>'accepted','false'))
              not in('true','1','yes','on')
         or lower(coalesce(v_operation_result->>'blocked','false'))
              in('true','1','yes','on') then
        raise exception using errcode='55000',
          message=case
            when lower(coalesce(v_operation_result->>'blocked','false'))
                   in('true','1','yes','on')
              then 'SOURCE_EDIT_REPLACEMENT_BLOCKED'
            else 'SOURCE_EDIT_REPLACEMENT_REJECTED' end,
          detail=jsonb_build_object(
            'command_no',v_command_no,
            'terminal_error',v_operation_result->'terminal_error')::text;
      end if;

      v_operation_status:=upper(coalesce(v_operation_result->>'status',''));
      v_operation_id:=case when coalesce(v_operation_result->>'operation_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (v_operation_result->>'operation_id')::uuid end;
      v_document_version_id:=case when coalesce(v_operation_result->>'document_version_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (v_operation_result->>'document_version_id')::uuid end;

      if v_operation_status='READY' then
        if v_document_version_id is null or v_operation_id is not null
           or not exists(
             select 1
             from public.invoice_document_versions dv
             where dv.id=v_document_version_id
               and dv.entity_type=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'INVOICE' end
               and dv.entity_id=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (v_source_update->>'timesheet_id')::uuid else p_invoice_id end
               and dv.purpose=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'DRAFT_PREVIEW' end
               and dv.source_revision=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (
                   select t.document_revision::text from public.timesheets t
                   where t.timesheet_id=(v_source_update->>'timesheet_id')::uuid
                     and t.is_current)
                 else (
                   select i.document_revision::text from public.invoices i
                   where i.id=p_invoice_id)
                 end
               and dv.template_version=v_source_update->>'template_version'
               and dv.status='READY'
               and nullif(btrim(coalesce(dv.r2_key,'')),'') is not null
               and nullif(btrim(coalesce(dv.sha256,'')),'') is not null
               and coalesce(dv.size_bytes,0)>0
               and coalesce(dv.page_count,0)>0
           ) then
          raise exception using errcode='55000',
            message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
            detail=jsonb_build_object(
              'reason','READY_IDENTITY','command_no',v_command_no)::text;
        end if;
      else
        if v_operation_id is null
           or v_operation_status not in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
           or not exists(
             select 1
             from public.invoice_operations op
             where op.id=v_operation_id
               and op.operation_type='BUILD_DOCUMENT'
               and op.entity_type=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'INVOICE' end
               and op.entity_id=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (v_source_update->>'timesheet_id')::uuid else p_invoice_id end
               and op.source_revision=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (
                   select t.document_revision::text from public.timesheets t
                   where t.timesheet_id=(v_source_update->>'timesheet_id')::uuid
                     and t.is_current)
                 else (
                   select i.document_revision::text from public.invoices i
                   where i.id=p_invoice_id)
                 end
               and op.template_version=v_source_update->>'template_version'
               and coalesce(op.input_json->>'purpose','')=
                 case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                   then 'TIMESHEET' else 'DRAFT_PREVIEW' end
               and op.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
           ) then
          raise exception using errcode='55000',
            message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
            detail=jsonb_build_object(
              'reason','ACTIVE_IDENTITY','command_no',v_command_no)::text;
        end if;
      end if;

      v_validated_operations:=v_validated_operations||jsonb_build_array(v_operation_result);
    end loop;

    select coalesce(jsonb_agg(jsonb_build_object(
      'timesheet_id',t.timesheet_id,
      'document_revision',t.document_revision)
      order by t.timesheet_id),'[]'::jsonb)
    into v_source_changed_revisions
    from public.timesheets t
    where t.timesheet_id=any(v_source_changed_ts_ids) and t.is_current;
  end if;

-- Return compact state only; never build a manifest or PDF here.
  select jsonb_build_object('invoice_id',i.id,'status',i.status,
    'subtotal_ex_vat',i.subtotal_ex_vat,'vat_amount',i.vat_amount,'total_inc_vat',i.total_inc_vat,
    'document_revision',i.document_revision,'document_state',i.document_state,
    'preview_document_version_id',i.preview_document_version_id,
    'active_document_operation_id',i.active_document_operation_id,
    'issue_state',i.issue_state,'active_issue_operation_id',i.active_issue_operation_id,
    'reference_updates_applied',v_refupd_applied,
    'timesheet_location_updates_applied',v_location_applied,
    'timesheet_source_changed',
      cardinality(v_source_changed_ts_ids)>0,
    'source_edit_queue_contract',case when v_source_edit_requested
      then 'INVOICE_SOURCE_EDIT_QUEUE_V1' else null end,
    'changed_timesheet_ids',coalesce(to_jsonb(v_source_changed_ts_ids),'[]'::jsonb),
    'changed_timesheet_revisions',coalesce(v_source_changed_revisions,'[]'::jsonb),
    'source_edit_preexisting_preview',v_source_edit_preexisting_preview,
    'invoice_replacement_required',v_source_edit_invoice_replacement_required,
    'accepted_operations',coalesce(v_validated_operations,'[]'::jsonb),
    'document_queue_requested',jsonb_array_length(v_document_commands)>0)
  into v_manifest from public.invoices i where i.id=p_invoice_id;

  if v_invoice_debug then
    begin
      -- attach finish marker (avoid extra heavy queries here)
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','finish',
          'at_utc', public._inv_iso_utc(now()),
          'invoice_total_charge_ex_vat', v_new_ex,
          'invoice_vat_amount', v_new_vat,
          'invoice_total_inc_vat', v_new_inc
        )
      );

      v_dbg_stats := v_dbg_stats || jsonb_build_object(
        'lines_deleted', v_dbg_lines_deleted,
        'timesheets_unlocked_via_line_removal', v_dbg_timesheets_unlocked,
        'segment_add_refs', v_dbg_seg_add_refs,
        'segment_remove_refs', v_dbg_seg_remove_refs,
        'segment_tsfin_count', v_dbg_seg_tsfins,
        'segment_timesheets_rebuilt', v_dbg_seg_timesheets_rebuilt,
        'segment_timesheets_removed', v_dbg_seg_timesheets_removed,
        'add_timesheets_found', v_dbg_add_timesheets_found,
        'add_timesheets_skipped', v_dbg_add_timesheets_skipped
      );

      perform public._inv_write_audit(
        p_actor_user_id,
        'INVOICE_APPLY_EDITS_DEBUG',
        jsonb_build_object(
          'invoice_id', p_invoice_id::text,
          'week_start', v_week_start::text,
          'week_end', v_week_end::text,
          'stats', v_dbg_stats,
          'steps', v_dbg_steps
        ),
        'invoices',
        p_invoice_id::text,
        null,
        'INVOICE_DEBUG',
        null, null, null
      );
    exception when others then
      null;
    end;
  end if;

  perform public._ctms_assert_invoice_correction_lines_v1(
    p_invoice_id,p_actor_user_id,false,'INVOICE_APPLY_EDITS_RESULT'
  );

  IF v_correction_placement_ts_id IS NOT NULL THEN
    v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
      v_correction_placement_ts_id,null::uuid,p_actor_user_id,false,100);
    IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
       OR v_correction_placement_scope->>'placement_state' NOT IN (
         'COMPLETE_SAME_INVOICE','COMPLETE_SPLIT_INVOICES','INCOMPLETE_MOVE','UNPLACED') THEN
      RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_RESULT_INVALID'
        USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
    END IF;
    v_correction_placement_states:=jsonb_build_array(jsonb_build_object(
      'correction_id',v_correction_placement_scope->>'correction_id',
      'pair_timesheet_ids',v_correction_placement_scope->'pair_timesheet_ids',
      'placement_state',v_correction_placement_scope->>'placement_state',
      'missing_member_kind',v_correction_placement_scope->>'missing_member_kind',
      'placement_invoices',v_correction_placement_scope->'placement_invoices'));
    v_manifest:=v_manifest||jsonb_build_object(
      'correction_pair_placement_states',v_correction_placement_states);
  END IF;

  return v_manifest;

exception when others then
  v_dbg_sqlstate := SQLSTATE;
  v_dbg_error := SQLERRM;

  if v_invoice_debug then
    begin
      perform public._inv_write_audit(
        p_actor_user_id,
        'INVOICE_APPLY_EDITS_ERROR',
        jsonb_build_object(
          'invoice_id', coalesce(p_invoice_id::text,''),
          'sqlstate', v_dbg_sqlstate,
          'error', v_dbg_error,
          'stats', v_dbg_stats,
          'steps', v_dbg_steps
        ),
        'invoices',
        coalesce(p_invoice_id::text,''),
        null,
        'INVOICE_DEBUG',
        null, null, null
      );
    exception when others then
      null;
    end;
  end if;

  raise;
end;
$function$;

revoke all on function public.invoice_apply_edits(uuid,jsonb,uuid)
  from public,anon,authenticated,service_role,supabase_admin;
grant execute on function public.invoice_apply_edits(uuid,jsonb,uuid)
  to CURRENT_USER,service_role;

create or replace function private._invoice_batch_generate_classification_v2(
  p_allow_early boolean default false,
  p_scope_keys text[] default null,
  p_now_utc timestamptz default now()
) returns table(
  selection_key text,
  candidate_json jsonb
)
language plpgsql
stable
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_scope_keys text[];
begin
  if p_scope_keys is not null then
    if cardinality(p_scope_keys)>250 then
      raise exception using
        errcode='22023',
        message='CANDIDATE_SCOPE_KEY_LIMIT_EXCEEDED';
    end if;
    if exists(
      select 1
      from unnest(p_scope_keys) value
      where value is null
        or btrim(value)=''
        or length(btrim(value))>512
    ) then
      raise exception using
        errcode='22023',
        message='CANDIDATE_SCOPE_KEY_INVALID';
    end if;
    select coalesce(array_agg(value order by value),'{}'::text[])
    into v_scope_keys
    from(
      select distinct btrim(raw_value) value
      from unnest(p_scope_keys) raw_value
    ) deduplicated;
  end if;

  return query
  with
  anchor as materialized (
    select
      coalesce(p_now_utc,statement_timestamp()) evaluation_utc,
      (
        coalesce(p_now_utc,statement_timestamp())
        at time zone 'Europe/London'
      )::date today
  ),
  source_candidates as materialized (
    select distinct financial.timesheet_id
    from public.timesheets_financials financial
    join public.timesheets timesheet
      on timesheet.timesheet_id=financial.timesheet_id
     and timesheet.is_current
     and timesheet.revoked_at is null
    where financial.is_current
      and financial.client_id is not null
    order by financial.timesheet_id
  ),
  command as materialized (
    select jsonb_build_array(jsonb_build_object(
      'command_type','GENERATE_SELECTED',
      'source_ids',coalesce(
        jsonb_agg(source.timesheet_id order by source.timesheet_id),
        '[]'::jsonb
      ),
      'allow_early',coalesce(p_allow_early,false),
      'scope_keys',case
        when v_scope_keys is null then null
        else to_jsonb(v_scope_keys)
      end
    )) commands
    from source_candidates source
  ),
  groups as materialized (
    select resolved.*
    from command
    cross join anchor
    cross join lateral private._invoice_generation_resolve_command_groups(
      command.commands,
      null,
      anchor.evaluation_utc
    ) resolved
    where v_scope_keys is null
       or resolved.group_key=any(v_scope_keys)
  ),
  group_sources as materialized (
    select
      group_row.*,
      member.value member,
      case
        when coalesce(member.value->>'source_id','')~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
          then (member.value->>'source_id')::uuid
      end source_id,
      case
        when coalesce(
          member.value->>'related_timesheet_id',
          member.value->>'source_id',
          ''
        )~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
          then coalesce(
            member.value->>'related_timesheet_id',
            member.value->>'source_id'
          )::uuid
      end timesheet_id,
      nullif(member.value->>'segment_id','') segment_id
    from groups group_row
    cross join lateral jsonb_array_elements(
      group_row.canonical_source_members
    ) member(value)
  ),
  vat_policy as materialized (
    select policy.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',source.member->>'source_member_key',
        'source_type',source.member->>'source_type',
        'source_id',source.source_id,
        'timesheet_id',source.member->>'related_timesheet_id',
        'segment_id',source.segment_id,
        'effective_date',source.effective_settings_date
      ) order by
        source.group_key,
        source.member->>'source_member_key'
      )
      from group_sources source
    ),'[]'::jsonb)) policy
  ),
  reference_policy as materialized (
    select policy.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',source.member->>'source_member_key',
        'source_type',source.member->>'source_type',
        'source_id',source.source_id,
        'related_timesheet_id',source.timesheet_id,
        'segment_id',source.segment_id,
        'target_invoice_week',source.target_invoice_week,
        'invoice_stream',source.invoice_stream,
        'consolidation_mode',source.consolidation_mode
      ) order by
        source.group_key,
        source.member->>'source_member_key'
      )
      from group_sources source
    ),'[]'::jsonb)) policy
  ),
  correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generate-candidate:'||group_row.group_key,
      'scope_key',group_row.group_key,
      'validation_purpose','CANDIDATE_GENERATION',
      'expected_client_id',group_row.client_id,
      'expected_contract_id',case
        when cardinality(group_row.contract_ids)=1
          then group_row.contract_ids[1]
      end,
      'natural_source_week',case
        when cardinality(group_row.natural_source_weeks)=1
          then group_row.natural_source_weeks[1]
      end,
      'target_invoice_week',group_row.target_invoice_week,
      'expected_invoice_stream',group_row.invoice_stream,
      'planned_members',coalesce((
        select jsonb_agg(jsonb_build_object(
          'timesheet_id',source.timesheet_id,
          'source_type',source.member->>'source_type',
          'source_id',source.source_id,
          'source_member_key',source.member->>'source_member_key',
          'segment_id',source.segment_id,
          'target_invoice_week',source.target_invoice_week,
          'vat_rate_pct',vat.vat_rate
        ) order by source.member->>'source_member_key')
        from group_sources source
        left join vat_policy vat
          on vat.source_member_key=
            source.member->>'source_member_key'
        where source.group_key=group_row.group_key
      ),'[]'::jsonb)
    ) order by group_row.group_key),'[]'::jsonb) scopes
    from groups group_row
  ),
  correction_validation as materialized (
    select validation.*
    from correction_scopes scope
    cross join lateral private._invoice_correction_validate_batch(
      scope.scopes,
      (select today from anchor)
    ) validation
  ),
  correction_group_results as materialized (
    select
      validation.scope_key group_key,
      validation.valid,
      validation.blocker_code,
      validation.blocker_codes,
      validation.detail_json details
    from correction_validation validation
  ),
  independent_member_blockers as materialized (
    select
      source.group_key,
      source.member->>'source_member_key' source_member_key,
      blocker.code blocker_code,
      blocker.ordinality blocker_order
    from group_sources source
    left join public.timesheets timesheet
      on timesheet.timesheet_id=source.timesheet_id
     and timesheet.is_current
    left join public.timesheets_financials financial
      on financial.timesheet_id=source.timesheet_id
     and financial.is_current
    left join public.v_ts_invoice_precheck precheck
      on precheck.timesheet_id=source.timesheet_id
    left join reference_policy reference
      on reference.source_member_key=
        source.member->>'source_member_key'
    left join vat_policy vat
      on vat.source_member_key=source.member->>'source_member_key'
    cross join lateral unnest(array_remove(array[
      case
        when timesheet.timesheet_id is null
          then 'TIMESHEET_NOT_CURRENT'
      end,
      case
        when financial.timesheet_id is null
          then 'CURRENT_FINANCIALS_MISSING'
      end,
      case
        when coalesce(financial.is_stale,true)
          then 'FINANCIALS_STALE'
      end,
      case
        when coalesce(financial.processing_status::text,'')
          <>'READY_FOR_INVOICE'
          then 'NOT_READY_FOR_INVOICE'
      end,
      case
        when coalesce(financial.has_rate_issue,false)
          then 'RATE_MISSING'
      end,
      case
        when coalesce(financial.has_pay_channel_issue,false)
          then 'PAY_CHANNEL_MISSING'
      end,
      case
        when financial.locked_by_invoice_id is not null
          then 'SOURCE_ALREADY_LOCKED'
      end,
      case
        when upper(coalesce(timesheet.submission_mode::text,''))='QR'
         and (
           nullif(timesheet.qr_signed_hash,'') is null
           or timesheet.qr_signed_at_utc is null
         )
          then 'QR_TIMESHEET_UNSIGNED'
      end,
      case
        when coalesce(precheck.require_reference_to_invoice,false)
         and coalesce(financial.total_hours,0)>0
         and coalesce(reference.reference_ready,false) is not true
          then coalesce(reference.blocker_code,'MISSING_REFERENCE')
      end,
      case
        when (
          coalesce(financial.mileage_pay_ex_vat,0)<>0
          or coalesce(financial.mileage_charge_ex_vat,0)<>0
        )
        and not exists(
          select 1
          from public.timesheet_evidence evidence
          where evidence.timesheet_id=source.timesheet_id
            and upper(coalesce(evidence.kind,''))='MILEAGE'
            and nullif(evidence.storage_key,'') is not null
        )
          then 'MISSING_MILEAGE_EVIDENCE'
      end,
      case
        when (
          coalesce(financial.expenses_pay_ex_vat,0)<>0
          or coalesce(financial.expenses_charge_ex_vat,0)<>0
          or coalesce(financial.travel_pay_ex_vat,0)<>0
          or coalesce(financial.travel_charge_ex_vat,0)<>0
          or coalesce(financial.accommodation_pay_ex_vat,0)<>0
          or coalesce(financial.accommodation_charge_ex_vat,0)<>0
        )
        and not exists(
          select 1
          from public.timesheet_evidence evidence
          where evidence.timesheet_id=source.timesheet_id
            and upper(coalesce(evidence.kind,'')) in(
              'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES'
            )
            and nullif(evidence.storage_key,'') is not null
        )
          then 'MISSING_EXPENSE_EVIDENCE'
      end,
      case
        when exists(
          select 1
          from public.timesheet_evidence evidence
          join public.invoice_document_assets asset
            on asset.id=evidence.document_asset_id
          where evidence.timesheet_id=source.timesheet_id
            and asset.status in(
              'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED'
            )
        )
          then 'REQUIRED_ASSET_PERMANENT_FAILURE'
      end,
      case
        when coalesce(vat.valid,false) is not true
          then coalesce(vat.blocker_code,'VAT_POLICY_UNRESOLVED')
      end,
      case
        when exists(
          select 1
          from public.invoice_lines line
          join public.invoices invoice on invoice.id=line.invoice_id
          where line.timesheet_id=source.timesheet_id
            and invoice.status in('DRAFT','ISSUED','ON_HOLD')
            and coalesce(
              financial.invoice_breakdown_json->>'mode',
              ''
            )<>'SEGMENTS'
        )
          then 'SOURCE_ALREADY_INVOICED'
      end
    ],null)) with ordinality blocker(code,ordinality)
  ),
  independent_group_blockers as materialized (
    select
      blocker.group_key,
      (
        array_agg(
          blocker.blocker_code
          order by blocker.source_member_key,blocker.blocker_order
        )
      )[1] blocker_code,
      jsonb_build_object(
        'code',(
          array_agg(
            blocker.blocker_code
            order by blocker.source_member_key,blocker.blocker_order
          )
        )[1],
        'sources',jsonb_agg(jsonb_build_object(
          'source_member_key',blocker.source_member_key,
          'code',blocker.blocker_code
        ) order by blocker.source_member_key,blocker.blocker_order)
      ) blocker_detail
    from independent_member_blockers blocker
    group by blocker.group_key
  ),
  selected_member_totals as materialized (
    select
      source.group_key,
      source.member->>'source_member_key' source_member_key,
      source.timesheet_id,
      source.segment_id,
      round(case
        when source.segment_id is not null then coalesce((
          select sum(case
            when coalesce(segment.value->>'charge_amount','')~
              '^[+-]?[0-9]+([.][0-9]+)?$'
              then (segment.value->>'charge_amount')::numeric
            when coalesce(segment.value->>'charge_ex_vat','')~
              '^[+-]?[0-9]+([.][0-9]+)?$'
              then (segment.value->>'charge_ex_vat')::numeric
            else 0
          end)
          from jsonb_array_elements(
            case
              when jsonb_typeof(
                financial.invoice_breakdown_json->'segments'
              )='array'
                then financial.invoice_breakdown_json->'segments'
              else '[]'::jsonb
            end
          ) segment(value)
          where coalesce(
            nullif(segment.value->>'segment_id',''),
            left(
              encode(
                digest(segment.value::text,'sha256'),
                'hex'
              ),
              24
            )
          )=source.segment_id
        ),0)
        else coalesce(financial.total_charge_ex_vat,0)
      end,2) total_charge_ex_vat,
      round(case
        when source.segment_id is not null then coalesce((
          select sum(
            case
              when coalesce(segment.value->>'hours_day','')~
                '^[+-]?[0-9]+([.][0-9]+)?$'
                then (segment.value->>'hours_day')::numeric
              else 0
            end
            +case
              when coalesce(segment.value->>'hours_night','')~
                '^[+-]?[0-9]+([.][0-9]+)?$'
                then (segment.value->>'hours_night')::numeric
              else 0
            end
            +case
              when coalesce(segment.value->>'hours_sat','')~
                '^[+-]?[0-9]+([.][0-9]+)?$'
                then (segment.value->>'hours_sat')::numeric
              else 0
            end
            +case
              when coalesce(segment.value->>'hours_sun','')~
                '^[+-]?[0-9]+([.][0-9]+)?$'
                then (segment.value->>'hours_sun')::numeric
              else 0
            end
            +case
              when coalesce(segment.value->>'hours_bh','')~
                '^[+-]?[0-9]+([.][0-9]+)?$'
                then (segment.value->>'hours_bh')::numeric
              else 0
            end
          )
          from jsonb_array_elements(
            case
              when jsonb_typeof(
                financial.invoice_breakdown_json->'segments'
              )='array'
                then financial.invoice_breakdown_json->'segments'
              else '[]'::jsonb
            end
          ) segment(value)
          where coalesce(
            nullif(segment.value->>'segment_id',''),
            left(
              encode(
                digest(segment.value::text,'sha256'),
                'hex'
              ),
              24
            )
          )=source.segment_id
        ),0)
        else coalesce(financial.total_hours,0)
      end,2) total_hours
    from group_sources source
    join public.timesheets_financials financial
      on financial.timesheet_id=source.timesheet_id
     and financial.is_current
  ),
  generation_totals as materialized (
    select
      source.group_key,
      round(coalesce(sum(total.total_charge_ex_vat),0),2)
        total_ex_vat,
      round(coalesce(sum(round(
        total.total_charge_ex_vat*coalesce(vat.vat_rate,0)/100,
        2
      )),0),2) vat_amount,
      round(coalesce(sum(total.total_hours),0),2) total_hours
    from group_sources source
    join selected_member_totals total
      on total.group_key=source.group_key
     and total.source_member_key=
       source.member->>'source_member_key'
    left join vat_policy vat
      on vat.source_member_key=source.member->>'source_member_key'
    group by source.group_key
  ),
  timesheet_totals as materialized (
    select
      total.group_key,
      total.timesheet_id,
      round(sum(total.total_charge_ex_vat),2) total_charge_ex_vat,
      round(sum(total.total_hours),2) total_hours
    from selected_member_totals total
    group by total.group_key,total.timesheet_id
  ),
  source_display as materialized (
    select distinct
      source.group_key,
      financial.timesheet_id,
      financial.client_id,
      financial.candidate_id,
      timesheet.week_ending_date,
      timesheet.submission_mode,
      financial.basis,
      total.total_charge_ex_vat,
      total.total_hours,
      summary.client_name,
      summary.candidate_name,
      summary.validation_status,
      coalesce(
        summary.hr_validation_required_for_invoice,
        false
      ) hr_validation_required_for_invoice,
      coalesce(
        summary.hr_validation_required_for_invoice,
        false
      )
      and (
        summary.validation_status is null
        or summary.validation_status<>all(array[
          'VALIDATION_OK'::public.validation_status_enum,
          'OVERRIDDEN'::public.validation_status_enum
        ])
      ) blocked_by_hr_validation,
      precheck.precheck_status,
      exists(
        select 1
        from public.timesheet_evidence evidence
        left join public.invoice_document_assets asset
          on asset.id=evidence.document_asset_id
        where evidence.timesheet_id=financial.timesheet_id
          and evidence.processing_state not in('SUPERSEDED')
          and (asset.id is null or asset.status<>'READY')
      ) unready_evidence_asset,
      exists(
        select 1
        from public.invoice_document_versions version
        where version.entity_type='TIMESHEET'
          and version.entity_id=financial.timesheet_id
          and version.purpose='TIMESHEET'
          and version.source_revision=timesheet.document_revision::text
          and version.status='READY'
          and version.r2_key is not null
          and version.sha256~'^[0-9a-f]{64}$'
          and coalesce(version.size_bytes,0)>0
          and coalesce(version.page_count,0)>0
      ) timesheet_document_ready,
      timesheet.document_revision,
      timesheet.document_state,
      timesheet.current_document_version_id
    from group_sources source
    join public.timesheets_financials financial
      on financial.timesheet_id=source.timesheet_id
     and financial.is_current
    join public.timesheets timesheet
      on timesheet.timesheet_id=financial.timesheet_id
     and timesheet.is_current
    join timesheet_totals total
      on total.group_key=source.group_key
     and total.timesheet_id=source.timesheet_id
    join public.v_ts_invoice_precheck precheck
      on precheck.timesheet_id=financial.timesheet_id
    left join public.v_timesheets_summary_base summary
      on summary.timesheet_id=financial.timesheet_id
  ),
  active_exact as materialized (
    select distinct on(
      chunk.payload_json->>'group_key',
      chunk.payload_json->>'source_revision'
    )
      chunk.payload_json->>'group_key' group_key,
      operation.id operation_id,
      operation.status,
      chunk.payload_json->>'source_revision' source_revision,
      operation.progress_json,
      operation.error_json,
      operation.updated_at_utc
    from public.invoice_operation_chunks chunk
    join public.invoice_operations operation
      on operation.id=chunk.operation_id
    where chunk.chunk_type='GENERATION_GROUP'
      and chunk.status in(
        'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
      )
      and operation.status in(
        'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
      )
      and coalesce(
        chunk.payload_json->>'is_selection_expander',
        'false'
      )<>'true'
      and (not chunk.is_manifest_member or chunk.manifest_committed)
      and (
        not chunk.is_manifest_member
        or coalesce(chunk.entity_type,'')<>'OPERATION'
      )
    order by
      chunk.payload_json->>'group_key',
      chunk.payload_json->>'source_revision',
      operation.priority desc,
      operation.created_at_utc desc
  ),
  group_classification as materialized (
    select
      group_row.client_id,
      group_row.group_key,
      group_row.target_invoice_week,
      group_row.consolidation_mode,
      group_row.invoice_stream,
      group_row.source_revision_hash,
      group_row.canonical_source_ids,
      group_row.canonical_source_members,
      totals.total_ex_vat,
      totals.vat_amount,
      totals.total_hours,
      coalesce(jsonb_agg(
        distinct to_jsonb(display.candidate_id)
        order by to_jsonb(display.candidate_id)
      )
        filter(where display.candidate_id is not null),'[]'::jsonb)
        candidate_ids,
      coalesce(jsonb_agg(
        distinct to_jsonb(display.candidate_name)
        order by to_jsonb(display.candidate_name)
      )
        filter(where nullif(display.candidate_name,'') is not null),
        '[]'::jsonb) candidate_names,
      coalesce(jsonb_agg(distinct to_jsonb(display.week_ending_date)
        order by to_jsonb(display.week_ending_date))
        filter(where display.week_ending_date is not null),
        '[]'::jsonb) week_ending_dates,
      max(display.week_ending_date) week_ending_date,
      case
        when group_row.blocker_code is not null
          then group_row.blocker_code
        when independent.blocker_code is not null
          then independent.blocker_code
        when coalesce(correction.valid,true) is not true
          then coalesce(
            correction.blocker_code,
            'INVOICE_CORRECTION_UNIT_INVALID'
          )
        when bool_or(display.blocked_by_hr_validation)
          then 'HR_VALIDATION_BLOCKED'
        when not coalesce(p_allow_early,false)
         and exists(
           select 1
           from jsonb_array_elements(
             group_row.canonical_source_members
           ) early(value)
           where case
             when pg_input_is_valid(
               coalesce(early.value->>'target_invoice_week',''),
               'date'
             )
               then (
                 early.value->>'target_invoice_week'
               )::date+6 >= (select today from anchor)
             else false
           end
         )
          then 'EARLY_GENERATION_NOT_ALLOWED'
      end blocker_code,
      case
        when group_row.blocker_code is not null
          then group_row.blocker_detail
        when independent.blocker_code is not null
          then independent.blocker_detail
        when coalesce(correction.valid,true) is not true
          then jsonb_build_object(
            'code',coalesce(
              correction.blocker_code,
              'INVOICE_CORRECTION_UNIT_INVALID'
            ),
            'correction_validation',correction.details
          )
        when bool_or(display.blocked_by_hr_validation)
          then jsonb_build_object(
            'code','HR_VALIDATION_BLOCKED',
            'sources',coalesce(
              jsonb_agg(display.timesheet_id order by display.timesheet_id)
                filter(where display.blocked_by_hr_validation),
              '[]'::jsonb
            )
          )
        when not coalesce(p_allow_early,false)
         and exists(
           select 1
           from jsonb_array_elements(
             group_row.canonical_source_members
           ) early(value)
           where case
             when pg_input_is_valid(
               coalesce(early.value->>'target_invoice_week',''),
               'date'
             )
               then (
                 early.value->>'target_invoice_week'
               )::date+6 >= (select today from anchor)
             else false
           end
         )
          then jsonb_build_object(
            'code','EARLY_GENERATION_NOT_ALLOWED'
          )
      end blocker_detail,
      active.operation_id active_operation_id,
      active.status active_status,
      active.progress_json active_progress,
      active.error_json active_error,
      coalesce(correction.details,'[]'::jsonb)
        correction_validation,
      jsonb_agg(jsonb_build_object(
        'timesheet_id',display.timesheet_id,
        'candidate_name',display.candidate_name,
        'week_ending_date',display.week_ending_date,
        'total_charge_ex_vat',display.total_charge_ex_vat,
        'total_hours',display.total_hours,
        'basis',display.basis::text,
        'submission_mode',coalesce(display.submission_mode::text,''),
        'validation_status',coalesce(display.validation_status::text,''),
        'hr_validation_required_for_invoice',
          display.hr_validation_required_for_invoice,
        'blocked_by_hr_validation',display.blocked_by_hr_validation,
        'precheck_status',coalesce(display.precheck_status::text,''),
        'document_revision',display.document_revision,
        'document_state',display.document_state,
        'current_document_version_id',
          display.current_document_version_id,
        'timesheet_document_ready',
          display.timesheet_document_ready,
        'unready_evidence_asset',display.unready_evidence_asset
      ) order by
        display.candidate_name nulls last,
        display.timesheet_id
      ) timesheet_projection
    from groups group_row
    join generation_totals totals
      on totals.group_key=group_row.group_key
    join source_display display
      on display.group_key=group_row.group_key
    left join independent_group_blockers independent
      on independent.group_key=group_row.group_key
    left join correction_group_results correction
      on correction.group_key=group_row.group_key
    left join active_exact active
      on active.group_key=group_row.group_key
     and active.source_revision=group_row.source_revision_hash
    group by
      group_row.client_id,
      group_row.group_key,
      group_row.target_invoice_week,
      group_row.consolidation_mode,
      group_row.invoice_stream,
      group_row.source_revision_hash,
      group_row.canonical_source_ids,
      group_row.canonical_source_members,
      group_row.blocker_code,
      group_row.blocker_detail,
      totals.total_ex_vat,
      totals.vat_amount,
      totals.total_hours,
      independent.blocker_code,
      independent.blocker_detail,
      correction.valid,
      correction.blocker_code,
      correction.details,
      active.operation_id,
      active.status,
      active.progress_json,
      active.error_json
  ),
  create_rows as materialized (
    select
      'generate:'||classification.group_key selection_key,
      jsonb_build_object(
        'selection_key','generate:'||classification.group_key,
        'row_kind','CREATE_INVOICE',
        'scope_key',classification.group_key,
        'invoice_id',null,
        'client_id',classification.client_id,
        'client_name',client.name,
        'candidate_ids',classification.candidate_ids,
        'candidate_names',classification.candidate_names,
        'candidate_display',case
          when jsonb_array_length(classification.candidate_names)=1
            then classification.candidate_names->>0
          when jsonb_array_length(classification.candidate_names)>1
            then 'Multiple candidates ('||
              jsonb_array_length(classification.candidate_names)::text||
              ')'
          else 'Unknown candidate'
        end,
        'week_ending_dates',classification.week_ending_dates,
        'week_ending_date',classification.week_ending_date,
        'currency','GBP',
        'invoice_stream',upper(coalesce(
          nullif(classification.invoice_stream,''),
          'NORMAL'
        )),
        'total_ex_vat',round(classification.total_ex_vat,2),
        'vat_amount',round(classification.vat_amount,2),
        'total_inc_vat',round(
          classification.total_ex_vat+classification.vat_amount,
          2
        ),
        'generation_state','NOT_GENERATED',
        'primary_blocker_code',classification.blocker_code,
        'action_blocker_codes',coalesce((
          select jsonb_agg(to_jsonb(code) order by first_order,code)
          from (
            select code,min(code_order) first_order
            from (
              select
                1 code_order,
                nullif(classification.blocker_code,'') code
              union all
              select
                2,
                nullif(classification.blocker_detail->>'code','')
              union all
              select
                100+source.ordinality::integer,
                nullif(source.value->>'code','')
              from jsonb_array_elements(
                case
                  when jsonb_typeof(
                    classification.blocker_detail->'sources'
                  )='array'
                    then classification.blocker_detail->'sources'
                  else '[]'::jsonb
                end
              ) with ordinality source(value,ordinality)
            ) raw_code
            where code is not null
              and code not in(
                'EARLY_GENERATION_NOT_ALLOWED',
                'SOURCE_ALREADY_INVOICED'
              )
            group by code
          ) code_row
        ),'[]'::jsonb),
        'informational_codes',case
          when classification.active_status in(
            'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
          )
            then jsonb_build_array('GENERATING')
          else '[]'::jsonb
        end,
        'is_active',classification.active_status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
        ),
        'active_operation_id',classification.active_operation_id,
        'active_operation_status',classification.active_status,
        'source_revision',classification.source_revision_hash,
        'document_revision',null,
        'command_payload',jsonb_build_object(
          'command_type','GENERATE_SELECTED',
          'canonical_source_ids',
            to_jsonb(classification.canonical_source_ids),
          'canonical_source_members',
            classification.canonical_source_members,
          'group_key',classification.group_key,
          'source_revision',classification.source_revision_hash,
          'target_invoice_week',classification.target_invoice_week,
          'consolidation_mode',classification.consolidation_mode,
          'invoice_stream',classification.invoice_stream,
          'correction_validation',
            classification.correction_validation,
          'allow_early',coalesce(p_allow_early,false)
        ),
        'is_early',coalesce(
          classification.week_ending_date
            >=(select today from anchor),
          false
        ),
        'selectable',
          jsonb_array_length(coalesce((
            select jsonb_agg(to_jsonb(code))
            from (
              select distinct code
              from (
                select nullif(classification.blocker_code,'') code
                union all
                select nullif(
                  classification.blocker_detail->>'code',
                  ''
                )
              ) code_source
              where code is not null
                and code not in(
                  'EARLY_GENERATION_NOT_ALLOWED',
                  'SOURCE_ALREADY_INVOICED'
                )
            ) blocking
          ),'[]'::jsonb))=0
          and classification.active_status is null,
        'row_status',case
          when classification.blocker_code is not null
           and classification.blocker_code not in(
             'EARLY_GENERATION_NOT_ALLOWED',
             'SOURCE_ALREADY_INVOICED'
           )
            then 'BLOCKED'
          when classification.active_status in(
            'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
          )
            then 'IN_PROGRESS'
          else 'READY'
        end,
        '_private',jsonb_build_object(
          'canonical_source_ids',
            to_jsonb(classification.canonical_source_ids),
          'canonical_source_members',
            classification.canonical_source_members,
          'target_invoice_week',classification.target_invoice_week,
          'consolidation_mode',classification.consolidation_mode,
          'correction_validation',
            classification.correction_validation,
          'blocker_detail',classification.blocker_detail,
          'total_hours',classification.total_hours,
          'timesheets',classification.timesheet_projection,
          'active_progress',classification.active_progress,
          'active_error',classification.active_error
        )
      ) candidate_json
    from group_classification classification
    join public.clients client on client.id=classification.client_id
    where coalesce(classification.blocker_code,'')
      not in('SOURCE_ALREADY_INVOICED','EARLY_GENERATION_NOT_ALLOWED')
  ),
  stale_invoice_timesheets as materialized (
    select
      line.invoice_id,
      coalesce(jsonb_agg(
        distinct to_jsonb(summary.candidate_id)
        order by to_jsonb(summary.candidate_id)
      )
        filter(where summary.candidate_id is not null),'[]'::jsonb)
        candidate_ids,
      coalesce(jsonb_agg(
        distinct to_jsonb(summary.candidate_name)
        order by to_jsonb(summary.candidate_name)
      )
        filter(where nullif(summary.candidate_name,'') is not null),
        '[]'::jsonb) candidate_names,
      coalesce(jsonb_agg(
        distinct to_jsonb(summary.week_ending_date)
        order by to_jsonb(summary.week_ending_date)
      )
        filter(where summary.week_ending_date is not null),
        '[]'::jsonb) week_ending_dates,
      min(summary.week_ending_date) min_week_ending,
      max(summary.week_ending_date) max_week_ending
    from public.invoice_lines line
    left join public.v_timesheets_summary_base summary
      on summary.timesheet_id=line.timesheet_id
    group by line.invoice_id
  ),
  stale_rows as materialized (
    select
      'invoice:'||invoice.id::text selection_key,
      jsonb_build_object(
        'selection_key','invoice:'||invoice.id::text,
        'row_kind',case
          when coalesce(invoice.document_state,'')='FAILED'
            then 'RETRY_GENERATION'
          else 'REGENERATE_DRAFT'
        end,
        'scope_key',invoice.id::text,
        'invoice_id',invoice.id,
        'client_id',invoice.client_id,
        'client_name',client.name,
        'candidate_ids',coalesce(
          timesheet.candidate_ids,
          '[]'::jsonb
        ),
        'candidate_names',coalesce(
          timesheet.candidate_names,
          '[]'::jsonb
        ),
        'candidate_display',case
          when jsonb_array_length(coalesce(
            timesheet.candidate_names,
            '[]'::jsonb
          ))=1
            then timesheet.candidate_names->>0
          when jsonb_array_length(coalesce(
            timesheet.candidate_names,
            '[]'::jsonb
          ))>1
            then 'Multiple candidates ('||
              jsonb_array_length(timesheet.candidate_names)::text||
              ')'
          else 'Unknown candidate'
        end,
        'week_ending_dates',coalesce(
          timesheet.week_ending_dates,
          '[]'::jsonb
        ),
        'week_ending_date',coalesce(
          timesheet.min_week_ending,
          case
            when pg_input_is_valid(
              invoice.header_snapshot_json#>>'{meta,invoice_week_start}',
              'date'
            )
              then (
                invoice.header_snapshot_json#>>
                  '{meta,invoice_week_start}'
              )::date+6
          end
        ),
        'currency',coalesce(
          nullif(
            invoice.header_snapshot_json#>>'{meta,currency}',
            ''
          ),
          nullif(invoice.header_snapshot_json->>'currency',''),
          'GBP'
        ),
        'invoice_stream',upper(coalesce(
          nullif(
            invoice.header_snapshot_json#>>'{meta,invoice_stream}',
            ''
          ),
          nullif(invoice.header_snapshot_json->>'invoice_stream',''),
          case
            when lower(coalesce(
              invoice.header_snapshot_json#>>'{meta,self_bill}',
              invoice.header_snapshot_json->>'self_bill',
              'false'
            )) in('true','t','1','yes')
              then 'SELF_BILL'
          end,
          'NORMAL'
        )),
        'total_ex_vat',round(coalesce(invoice.subtotal_ex_vat,0),2),
        'vat_amount',round(coalesce(invoice.vat_amount,0),2),
        'total_inc_vat',round(coalesce(
          invoice.total_inc_vat,
          coalesce(invoice.subtotal_ex_vat,0)
            +coalesce(invoice.vat_amount,0)
        ),2),
        'generation_state',case
          when coalesce(invoice.document_state,'')='FAILED'
            then 'FAILED'
          when exists(
            select 1
            from public.invoice_document_versions version
            where version.entity_type='INVOICE'
              and version.entity_id=invoice.id
              and version.purpose='DRAFT_PREVIEW'
          )
            then 'STALE'
          else 'NOT_GENERATED'
        end,
        'primary_blocker_code',null,
        'action_blocker_codes','[]'::jsonb,
        'informational_codes',case
          when active.status in(
            'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
          )
            then jsonb_build_array('GENERATING')
          when exists(
            select 1
            from public.invoice_document_versions version
            where version.entity_type='INVOICE'
              and version.entity_id=invoice.id
              and version.purpose='DRAFT_PREVIEW'
          )
            then jsonb_build_array('STALE')
          else jsonb_build_array('NOT_GENERATED')
        end,
        'is_active',active.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
        ),
        'active_operation_id',active.operation_id,
        'active_operation_status',active.status,
        'source_revision',invoice.document_revision::text,
        'document_revision',invoice.document_revision::text,
        'command_payload',jsonb_build_object(
          'command_type','VIEW_INVOICE_DOCUMENT',
          'invoice_id',invoice.id,
          'purpose','DRAFT_PREVIEW',
          'expected_revision',invoice.document_revision,
          'source_revision',invoice.document_revision::text
        ),
        'is_early',coalesce(
          timesheet.max_week_ending,
          case
            when pg_input_is_valid(
              invoice.header_snapshot_json#>>
                '{meta,invoice_week_start}',
              'date'
            )
              then (
                invoice.header_snapshot_json#>>
                  '{meta,invoice_week_start}'
              )::date+6
          end
        ) >= (select today from anchor),
        'selectable',active.operation_id is null,
        'row_status',case
          when active.status in(
            'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
          )
            then 'IN_PROGRESS'
          when coalesce(invoice.document_state,'')='FAILED'
            then 'FAILED'
          when exists(
            select 1
            from public.invoice_document_versions version
            where version.entity_type='INVOICE'
              and version.entity_id=invoice.id
              and version.purpose='DRAFT_PREVIEW'
          )
            then 'STALE'
          else 'READY'
        end,
        '_private','{}'::jsonb
      ) candidate_json
    from public.invoices invoice
    join public.clients client on client.id=invoice.client_id
    left join stale_invoice_timesheets timesheet
      on timesheet.invoice_id=invoice.id
    left join lateral (
      select
        operation.id operation_id,
        operation.status
      from public.invoice_operations operation
      where operation.operation_type='BUILD_DOCUMENT'
        and operation.entity_type='INVOICE'
        and operation.entity_id=invoice.id
        and operation.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
        )
      order by
        operation.created_at_utc desc,
        operation.id desc
      limit 1
    ) active on true
    where invoice.type::text='INVOICE'
      and invoice.status::text in('DRAFT','ON_HOLD')
      and coalesce(invoice.document_revision,0)>0
      and (
        v_scope_keys is null
        or invoice.id::text=any(v_scope_keys)
      )
      and not exists(
        select 1
        from public.invoice_document_versions version
        where version.entity_type='INVOICE'
          and version.entity_id=invoice.id
          and version.purpose='DRAFT_PREVIEW'
          and version.source_revision=invoice.document_revision::text
          and version.template_version='invoice-professional-v2'
          and version.status='READY'
          and version.r2_key is not null
          and version.sha256~'^[0-9a-f]{64}$'
          and coalesce(version.size_bytes,0)>0
          and coalesce(version.page_count,0)>0
      )
  )
  select create_row.selection_key,create_row.candidate_json
  from create_rows create_row
  union all
  select stale_row.selection_key,stale_row.candidate_json
  from stale_rows stale_row
  order by selection_key;
end;
$function$;

alter function private._invoice_batch_generate_classification_v2(
  boolean,text[],timestamptz
) OWNER TO CURRENT_USER;
revoke all on function private._invoice_batch_generate_classification_v2(
  boolean,text[],timestamptz
) from public,anon,authenticated;
grant execute on function private._invoice_batch_generate_classification_v2(
  boolean,text[],timestamptz
) to service_role;

create or replace function private._invoice_batch_issue_classification_v2(
  p_allow_early boolean default false,
  p_invoice_ids uuid[] default null,
  p_now_utc timestamptz default now()
) returns table(
  selection_key text,
  candidate_json jsonb
)
language sql
stable
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
with
anchor as materialized (
  select (
    coalesce(p_now_utc,statement_timestamp())
    at time zone 'Europe/London'
  )::date today
),
base as materialized (
  select
    invoice.*,
    client.name client_name,
    case
      when pg_input_is_valid(
        coalesce(
          invoice.header_snapshot_json#>>
            '{meta,invoice_week_start}',
          ''
        ),
        'date'
      )
        then (
          invoice.header_snapshot_json#>>
            '{meta,invoice_week_start}'
        )::date
    end invoice_week_start,
    lower(coalesce(
      invoice.header_snapshot_json#>>'{meta,self_bill}',
      invoice.header_snapshot_json->>'self_bill',
      'false'
    )) in('true','t','1','yes') is_self_bill
  from public.invoices invoice
  join public.clients client on client.id=invoice.client_id
  where invoice.type::text='INVOICE'
    and invoice.status::text in('DRAFT','ON_HOLD')
    and (
      p_invoice_ids is null
      or invoice.id=any(p_invoice_ids)
    )
),
validation_requests as materialized (
  select coalesce(jsonb_agg(jsonb_build_object(
    'request_key','candidate:'||invoice.id::text,
    'invoice_id',invoice.id,
    'expected_revision',invoice.document_revision,
    'allow_early',coalesce(p_allow_early,false),
    'deliver',true
  ) order by invoice.id),'[]'::jsonb) commands
  from base invoice
),
validations as materialized (
  select validation.*
  from validation_requests request
  cross join lateral private._invoice_issue_validate_batch(
    request.commands,
    (select today from anchor)
  ) validation
),
candidate_projection as materialized (
  select
    invoice.id invoice_id,
    coalesce(jsonb_agg(
      distinct to_jsonb(summary.candidate_id)
      order by to_jsonb(summary.candidate_id)
    )
      filter(where summary.candidate_id is not null),'[]'::jsonb)
      candidate_ids,
    coalesce(jsonb_agg(
      distinct to_jsonb(summary.candidate_name)
      order by to_jsonb(summary.candidate_name)
    )
      filter(where nullif(summary.candidate_name,'') is not null),
      '[]'::jsonb) candidate_names,
    coalesce(jsonb_agg(distinct to_jsonb(summary.week_ending_date)
      order by to_jsonb(summary.week_ending_date))
      filter(where summary.week_ending_date is not null),
      '[]'::jsonb) week_ending_dates,
    min(summary.week_ending_date) min_week_ending,
    max(summary.week_ending_date) max_week_ending
  from base invoice
  left join public.invoice_lines line on line.invoice_id=invoice.id
  left join public.v_timesheets_summary_base summary
    on summary.timesheet_id=line.timesheet_id
  group by invoice.id
),
active_issue as materialized (
  select distinct on(chunk.entity_id)
    chunk.entity_id invoice_id,
    chunk.operation_id,
    chunk.id chunk_id,
    chunk.status,
    chunk.phase,
    chunk.progress_json,
    chunk.error_json,
    operation.change_seq
  from public.invoice_operation_chunks chunk
  join public.invoice_operations operation
    on operation.id=chunk.operation_id
  join base invoice on invoice.id=chunk.entity_id
  where chunk.chunk_type='ISSUE_INVOICE'
    and chunk.entity_type='INVOICE'
    and chunk.status in(
      'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
    )
    and operation.status in(
      'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
    )
    and coalesce(
      chunk.payload_json->>'is_selection_expander',
      'false'
    )<>'true'
    and (not chunk.is_manifest_member or chunk.manifest_committed)
    and (
      not chunk.is_manifest_member
      or coalesce(chunk.entity_type,'')<>'OPERATION'
    )
  order by
    chunk.entity_id,
    chunk.updated_at_utc desc,
    chunk.id desc
),
classified as materialized (
  select
    invoice.*,
    invoice.invoice_week_start+6 week_ending_date,
    coalesce(validation.hard_blocker_codes,'[]'::jsonb)
      hard_blocker_codes,
    coalesce(validation.warning_codes,'[]'::jsonb) warning_codes,
    coalesce(validation.document_dependency_codes,'[]'::jsonb)
      document_dependency_codes,
    coalesce(validation.delivery_blocker_codes,'[]'::jsonb)
      delivery_blocker_codes,
    coalesce(validation.can_issue_only,false) can_issue_only,
    coalesce(validation.can_issue_and_deliver,false)
      can_issue_and_deliver,
    validation.detail_json validation_detail,
    validation.route_policy_result->'canonical_to' recipient,
    projection.candidate_ids,
    projection.candidate_names,
    projection.week_ending_dates,
    projection.min_week_ending,
    projection.max_week_ending,
    active.operation_id current_issue_operation_id,
    active.chunk_id current_issue_chunk_id,
    active.status current_issue_status,
    active.phase current_issue_phase,
    active.progress_json current_issue_progress,
    active.error_json current_issue_error,
    active.change_seq current_issue_change_seq,
    case
      when exists(
        select 1
        from public.invoice_document_versions version
        where version.entity_type='INVOICE'
          and version.entity_id=invoice.id
          and version.purpose='DRAFT_PREVIEW'
          and version.source_revision=
            invoice.document_revision::text
          and version.template_version='invoice-professional-v2'
          and version.status='READY'
          and version.r2_key is not null
          and version.sha256~'^[0-9a-f]{64}$'
          and coalesce(version.size_bytes,0)>0
          and coalesce(version.page_count,0)>0
      )
        then 'FRESH'
      when exists(
        select 1
        from public.invoice_document_versions version
        where version.entity_type='INVOICE'
          and version.entity_id=invoice.id
          and version.purpose='DRAFT_PREVIEW'
          and version.template_version='invoice-professional-v2'
          and version.status='READY'
          and version.r2_key is not null
          and version.sha256~'^[0-9a-f]{64}$'
          and coalesce(version.size_bytes,0)>0
          and coalesce(version.page_count,0)>0
      )
        then case
          when invoice.active_document_operation_id is not null
            then 'ACTIVE'
          when upper(coalesce(invoice.document_state,''))='FAILED'
            or invoice.last_document_error_json is not null
            then 'FAILED'
          else 'STALE'
        end
      else 'NEVER_GENERATED'
    end generated_state
  from base invoice
  left join validations validation
    on validation.request_key='candidate:'||invoice.id::text
   and validation.invoice_id=invoice.id
  join candidate_projection projection
    on projection.invoice_id=invoice.id
  left join active_issue active on active.invoice_id=invoice.id
),
candidate_state as materialized (
  select
    classified.*,
    coalesce(
      jsonb_array_length(classified.delivery_blocker_codes)>0
      and classified.can_issue_only
      and not classified.can_issue_and_deliver,
      false
    ) blocked_for_sending,
    (
      classified.hard_blocker_codes
    ) issue_blocker_codes,
    (
      case
        when jsonb_array_length(
          classified.delivery_blocker_codes
        )>0
         and classified.can_issue_only
         and not classified.can_issue_and_deliver
          then jsonb_build_array('BLOCKED_FOR_SENDING')
        else '[]'::jsonb
      end
      ||classified.document_dependency_codes
      ||classified.warning_codes
    ) informational_codes
  from classified
),
final_rows as materialized (
  select
    state.*,
    (
      state.can_issue_only
      and jsonb_array_length(state.hard_blocker_codes)=0
      and state.current_issue_operation_id is null
    ) selectable,
    case
      when state.current_issue_operation_id is not null
        then 'IN_PROGRESS'
      when not state.can_issue_only
        or jsonb_array_length(state.hard_blocker_codes)>0
        then 'BLOCKED'
      else 'READY'
    end row_status
  from candidate_state state
  where state.status::text in('DRAFT','ON_HOLD')
    and nullif(state.invoice_no,'') is not null
)
select
  'invoice:'||invoice.id::text selection_key,
  jsonb_build_object(
    'selection_key','invoice:'||invoice.id::text,
    'invoice_id',invoice.id,
    'invoice_number',invoice.invoice_no,
    'source_revision',invoice.document_revision::text,
    'document_revision',invoice.document_revision,
    'client_id',invoice.client_id,
    'client_name',invoice.client_name,
    'candidate_ids',invoice.candidate_ids,
    'candidate_names',invoice.candidate_names,
    'candidate_display',case
      when jsonb_array_length(invoice.candidate_names)=1
        then invoice.candidate_names->>0
      when jsonb_array_length(invoice.candidate_names)>1
        then 'Multiple candidates ('||
          jsonb_array_length(invoice.candidate_names)::text||
          ')'
      else 'Unknown candidate'
    end,
    'week_ending_dates',case
      when jsonb_array_length(invoice.week_ending_dates)>0
        then invoice.week_ending_dates
      else jsonb_build_array(invoice.week_ending_date)
    end,
    'week_ending_date',coalesce(
      invoice.min_week_ending,
      invoice.week_ending_date
    ),
    'currency',coalesce(
      nullif(invoice.header_snapshot_json#>>'{meta,currency}',''),
      nullif(invoice.header_snapshot_json->>'currency',''),
      'GBP'
    ),
    'invoice_stream',upper(coalesce(
      nullif(
        invoice.header_snapshot_json#>>'{meta,invoice_stream}',
        ''
      ),
      nullif(invoice.header_snapshot_json->>'invoice_stream',''),
      case when invoice.is_self_bill then 'SELF_BILL' end,
      'NORMAL'
    )),
    'total_ex_vat',round(coalesce(invoice.subtotal_ex_vat,0),2),
    'vat_amount',round(coalesce(invoice.vat_amount,0),2),
    'total_inc_vat',round(coalesce(
      invoice.total_inc_vat,
      coalesce(invoice.subtotal_ex_vat,0)
        +coalesce(invoice.vat_amount,0)
    ),2),
    'preview_document_state',
      upper(coalesce(invoice.document_state,'')),
    'invoice_status',upper(coalesce(invoice.status::text,'')),
    'hard_blocker_codes',invoice.hard_blocker_codes,
    'document_dependency_codes',
      invoice.document_dependency_codes,
    'delivery_blocker_codes',invoice.delivery_blocker_codes,
    'warning_codes',invoice.warning_codes,
    'issue_blocker_codes',invoice.issue_blocker_codes,
    'informational_codes',invoice.informational_codes,
    'can_issue_only',invoice.can_issue_only,
    'can_issue_and_deliver',invoice.can_issue_and_deliver,
    'validation_detail',invoice.validation_detail,
    'support_readiness',null,
    'generated_state',invoice.generated_state,
    'blocked_for_sending',invoice.blocked_for_sending,
    'selectable',invoice.selectable,
    'row_status',invoice.row_status,
    'is_early',coalesce(
      invoice.max_week_ending,
      invoice.week_ending_date
    ) >= (select today from anchor),
    'active_issue_operation_id',invoice.current_issue_operation_id,
    'active_issue_operation',case
      when invoice.current_issue_operation_id is not null
        then jsonb_build_object(
          'id',invoice.current_issue_operation_id,
          'chunk_id',invoice.current_issue_chunk_id,
          'status',invoice.current_issue_status,
          'phase',invoice.current_issue_phase,
          'progress',invoice.current_issue_progress,
          'error',invoice.current_issue_error,
          'change_seq',invoice.current_issue_change_seq
        )
    end,
    'active_document_operation_id',
      invoice.active_document_operation_id,
    'last_issue_error',invoice.current_issue_error,
    'last_document_error',invoice.last_document_error_json,
    '_private',jsonb_build_object(
      'recipient',invoice.recipient,
      'routing_warnings',invoice.warning_codes
    )
  ) candidate_json
from final_rows invoice
order by invoice.client_name nulls last,
  invoice.week_ending_date desc nulls last,
  invoice.invoice_no nulls last,
  invoice.id;
$function$;

alter function private._invoice_batch_issue_classification_v2(
  boolean,uuid[],timestamptz
) OWNER TO CURRENT_USER;
revoke all on function private._invoice_batch_issue_classification_v2(
  boolean,uuid[],timestamptz
) from public,anon,authenticated;
grant execute on function private._invoice_batch_issue_classification_v2(
  boolean,uuid[],timestamptz
) to service_role;


create or replace function private._invoice_batch_generate_candidate_rows_v2(
  p_query jsonb default '{}'::jsonb,
  p_now_utc timestamptz default now()
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_query jsonb := coalesce(p_query,'{}'::jsonb);
  v_mode text;
  v_filters jsonb;
  v_sort jsonb;
  v_selection jsonb;
  v_selection_keys jsonb;
  v_expected_source_revisions jsonb;
  v_page_size integer;
  v_after_key text;
  v_allow_early boolean;
  v_display_mode text;
  v_input_snapshot jsonb;
  v_snapshot jsonb;
  v_snapshot_after jsonb;
  v_filter_hash text;
  v_query_hash text;
  v_selection_hash text;
  v_result jsonb;
begin
  v_query := private._invoice_batch_query_validate_v2(v_query, 'GENERATE');

  if jsonb_typeof(v_query) is distinct from 'object' then
    raise exception using errcode='22023', message='INVOICE_BATCH_QUERY_INVALID';
  end if;

  if coalesce(v_query->>'contract_version','INVOICE_BATCH_QUERY_V2') <> 'INVOICE_BATCH_QUERY_V2' then
    raise exception using errcode='22023', message='INVOICE_BATCH_QUERY_CONTRACT_INVALID';
  end if;

  v_mode := upper(coalesce(nullif(v_query->>'mode',''),'PAGE'));
  if v_mode not in ('PAGE','FACETS','SUMMARY','EXPAND_SELECTION','EXPLICIT_KEYS') then
    raise exception using errcode='22023', message='INVOICE_BATCH_QUERY_MODE_INVALID';
  end if;

  v_selection_keys := coalesce(v_query->'selection_keys','[]'::jsonb);
  v_expected_source_revisions := coalesce(
    v_query->'expected_source_revisions',
    '{}'::jsonb
  );
  if v_mode='EXPLICIT_KEYS' then
    if jsonb_typeof(v_selection_keys) is distinct from 'array'
       or jsonb_array_length(v_selection_keys) < 1
       or jsonb_array_length(v_selection_keys) > 100
       or jsonb_typeof(v_expected_source_revisions) is distinct from 'object'
       or exists (
         select 1
         from jsonb_array_elements(v_selection_keys) with ordinality key_item(value,ordinality)
         where jsonb_typeof(key_item.value) is distinct from 'string'
            or nullif(btrim(key_item.value #>> '{}'),'') is null
            or length(btrim(key_item.value #>> '{}')) > 512
       )
       or (
         select count(*) from jsonb_array_elements_text(v_selection_keys)
       ) <> (
         select count(distinct value)
         from jsonb_array_elements_text(v_selection_keys) explicit_key(value)
       )
       or exists (
         select 1
         from jsonb_array_elements_text(v_selection_keys) explicit_key(value)
         where nullif(v_expected_source_revisions->>explicit_key.value,'') is null
       ) then
      raise exception using
        errcode='22023',
        message='INVOICE_BATCH_EXPLICIT_KEYS_INVALID';
    end if;
  end if;

  v_filters := case when jsonb_typeof(v_query->'filters') = 'object' then v_query->'filters' else '{}'::jsonb end;
  v_sort := case when jsonb_typeof(v_query->'sort') = 'object' then v_query->'sort' else '{}'::jsonb end;
  v_selection := case when jsonb_typeof(v_query->'selection') = 'object' then v_query->'selection' else jsonb_build_object(
    'contract_version','INVOICE_BATCH_SELECTION_V2',
    'mode','IMPLICIT_ALL',
    'default_selected',true,
    'rules','[]'::jsonb
  ) end;

  -- Validate the selection ledger up-front even when the current mode only pages rows.
  perform 1 from private._invoice_batch_selection_rules_v2(v_selection) limit 1;

  v_allow_early := coalesce((v_filters->>'allow_early')::boolean,false);
  v_display_mode := upper(coalesce(
    nullif(v_filters->>'display_mode',''),
    'ALL'
  ));
  if v_display_mode not in ('ALL','READY','BLOCKED') then
    raise exception using errcode='22023', message='INVOICE_BATCH_DISPLAY_MODE_INVALID';
  end if;

  if upper(coalesce(v_sort->>'group_preset','WEEK_CLIENT_CANDIDATE')) not in (
    'WEEK_CLIENT_CANDIDATE','CLIENT_WEEK_CANDIDATE','CANDIDATE_WEEK_CLIENT','STATUS_WEEK_CLIENT'
  ) then
    raise exception using errcode='22023', message='INVOICE_BATCH_GROUP_PRESET_INVALID';
  end if;

  if upper(coalesce(v_sort->>'sort_key','WEEK_ENDING_DATE')) not in (
    'WEEK_ENDING_DATE','CLIENT_NAME','CANDIDATE_NAME','TOTAL_EX_VAT','TOTAL_INC_VAT','STATUS'
  ) then
    raise exception using errcode='22023', message='INVOICE_BATCH_SORT_KEY_INVALID';
  end if;

  -- PAGE, EXPAND_SELECTION and EXPLICIT_KEYS always obtain their bounded
  -- keyset first. The complete classifier remains the scalar authority for
  -- exact filtering, totals and group state, but it must never cause the
  -- rich presentation hydrator to receive an unrestricted scope.

  v_page_size := case
    when v_mode = 'EXPAND_SELECTION'
      then (v_query->>'page_size')::integer
    when v_mode = 'PAGE'
      then (v_query->>'page_size')::integer
    else 100
  end;
  v_after_key := nullif(v_query#>>'{cursor,after_selection_key}', '');

  v_input_snapshot := v_query->'snapshot';
  if v_input_snapshot is null
     or jsonb_typeof(v_input_snapshot) = 'null' then
    if v_mode <> 'PAGE' or v_after_key is not null then
      raise exception using errcode='22023', message='BATCH_SNAPSHOT_REQUIRED';
    end if;
    v_snapshot := private._invoice_candidate_snapshot_get_v2(
      'GENERATE',
      coalesce(p_now_utc,now())
    );
  else
    v_snapshot := private._invoice_candidate_snapshot_verify_v2(
      'GENERATE',
      v_input_snapshot,
      coalesce(p_now_utc,now())
    );
  end if;

  v_filter_hash := private._invoice_batch_hash_v2(jsonb_build_object(
    'action','GENERATE',
    'filters',v_filters,
    'sort',v_sort
  ));
  v_query_hash := private._invoice_batch_hash_v2(jsonb_build_object(
    'contract_version','INVOICE_BATCH_QUERY_V2',
    'action','GENERATE',
    'filters',v_filters,
    'sort',v_sort,
    'snapshot',jsonb_build_object(
      'contract_version',v_snapshot->>'contract_version',
      'action',v_snapshot->>'action',
      'at_utc',v_snapshot->>'at_utc',
      'revision',v_snapshot->>'revision',
      'expires_at_utc',v_snapshot->>'expires_at_utc',
      'key_id',v_snapshot->>'key_id'
    )
  ));
  v_selection_hash := private._invoice_batch_hash_v2(v_selection);

  with
  params as materialized (
    select
      v_mode mode,
      v_allow_early allow_early,
      v_display_mode display_mode,
      v_page_size page_size,
      v_after_key after_key,
      lower(nullif(btrim(coalesce(v_filters->>'search','')),'')) search_text,
      case when pg_input_is_valid(nullif(v_filters->>'week_ending_from',''),'date')
        then (v_filters->>'week_ending_from')::date end week_ending_from,
      case when pg_input_is_valid(nullif(v_filters->>'week_ending_to',''),'date')
        then (v_filters->>'week_ending_to')::date end week_ending_to,
      (coalesce(p_now_utc,now()) at time zone 'Europe/London')::date today,
      case when jsonb_typeof(v_filters->'client_ids')='array' then v_filters->'client_ids' else '[]'::jsonb end client_ids,
      case when jsonb_typeof(v_filters->'candidate_ids')='array' then v_filters->'candidate_ids' else '[]'::jsonb end candidate_ids,
      case when jsonb_typeof(v_filters->'week_endings')='array' then v_filters->'week_endings' else '[]'::jsonb end week_endings,
      case when jsonb_typeof(v_filters->'status_codes')='array' then v_filters->'status_codes' else '[]'::jsonb end status_codes,
      case when jsonb_typeof(v_filters->'blocker_codes')='array' then v_filters->'blocker_codes' else '[]'::jsonb end blocker_codes,
      case when jsonb_typeof(v_filters->'invoice_streams')='array' then v_filters->'invoice_streams' else '[]'::jsonb end invoice_streams,
      coalesce(nullif(upper(v_sort->>'group_preset'),''),'WEEK_CLIENT_CANDIDATE') group_preset,
      coalesce(nullif(upper(v_sort->>'sort_key'),''),'WEEK_ENDING_DATE') sort_key,
      case when upper(coalesce(v_sort->>'sort_direction','ASC'))='DESC' then 'DESC' else 'ASC' end sort_direction,
      case when pg_input_is_valid(
        nullif(coalesce(v_query#>>'{cursor,after_sort_date}',''),''),
        'date'
      )
        then (v_query#>>'{cursor,after_sort_date}')::date end after_sort_date,
      nullif(coalesce(v_query#>>'{cursor,after_sort_text}',''),'') after_sort_text,
      case when coalesce(v_query#>>'{cursor,after_sort_numeric}','') ~ '^[+-]?[0-9]+([.][0-9]+)?$'
        then (v_query#>>'{cursor,after_sort_numeric}')::numeric end after_sort_numeric,
      lower(nullif(btrim(coalesce(v_query#>>'{facet_request,search}','')),'')) facet_search,
      case when coalesce(v_query#>>'{facet_request,limit_per_kind}','') ~ '^[1-9][0-9]{0,2}$'
        then least((v_query#>>'{facet_request,limit_per_kind}')::integer,100)
        else 100 end facet_limit,
      case when jsonb_typeof(v_query#>'{facet_request,kinds}')='array'
        then v_query#>'{facet_request,kinds}'
        else '["CLIENTS","CANDIDATES","WEEK_ENDINGS","STATUSES","BLOCKERS"]'::jsonb end facet_kinds,
      lower(nullif(v_query#>>'{facet_request,cursors,clients,after_label}','')) facet_client_after_label,
      nullif(v_query#>>'{facet_request,cursors,clients,after_id}','') facet_client_after_id,
      lower(nullif(v_query#>>'{facet_request,cursors,candidates,after_label}','')) facet_candidate_after_label,
      nullif(v_query#>>'{facet_request,cursors,candidates,after_id}','') facet_candidate_after_id,
      case when pg_input_is_valid(
        coalesce(v_query#>>'{facet_request,cursors,week_endings,after_value}',''),
        'date'
      ) then (v_query#>>'{facet_request,cursors,week_endings,after_value}')::date end facet_week_after_value,
      nullif(v_query#>>'{facet_request,cursors,statuses,after_code}','') facet_status_after_code,
      nullif(v_query#>>'{facet_request,cursors,blockers,after_code}','') facet_blocker_after_code
  ),
  selection_rules as materialized (
    select * from private._invoice_batch_selection_rules_v2(v_selection)
  ),
  candidate_keys as materialized (
    select key_row.*
    from (
      select 1
      where v_mode in ('PAGE','EXPAND_SELECTION','EXPLICIT_KEYS')
    ) gate
    cross join lateral private._invoice_batch_generate_candidate_key_rows_v2(
      v_query,
      coalesce(p_now_utc,now())
    ) key_row
  ),
  create_scope_request as materialized (
    select
      case
        when v_mode in ('FACETS','SUMMARY') then '{}'::text[]
        else coalesce(array_agg(k.scope_key order by k.page_ordinal)
          filter (
            where k.row_kind='CREATE_INVOICE'
              and k.page_ordinal<=v_page_size
          ),'{}'::text[])
      end scope_keys
    from candidate_keys k
  ),
  source_groups as materialized (
    select
      '{}'::jsonb client_json,
      source.client_id::text client_id_text,
      source.client_name,
      source.group_json
    from create_scope_request request
    cross join lateral private._invoice_batch_generate_group_rows_v2(
      true,
      null,
      request.scope_keys,
      coalesce(p_now_utc,now())
    ) source
    where v_mode in ('PAGE','EXPAND_SELECTION','EXPLICIT_KEYS')
      and cardinality(request.scope_keys)>0
  ),
  generation_timesheets as materialized (
    select
      lg.group_json->>'group_key' group_key,
      t.value timesheet_json,
      case when pg_input_is_valid(t.value->>'timesheet_id','uuid') then (t.value->>'timesheet_id')::uuid end timesheet_id,
      t.value->>'candidate_name' candidate_name,
      case when pg_input_is_valid(t.value->>'week_ending_date','date') then (t.value->>'week_ending_date')::date end week_ending_date,
      case when coalesce(t.value->>'total_charge_ex_vat','') ~ '^[+-]?[0-9]+([.][0-9]+)?$'
        then (t.value->>'total_charge_ex_vat')::numeric else 0 end total_ex_vat
    from source_groups lg
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(lg.group_json->'timesheets')='array' then lg.group_json->'timesheets' else '[]'::jsonb end
    ) t(value)
  ),
  generation_candidate_ids as materialized (
    select gt.group_key,
      coalesce(jsonb_agg(distinct to_jsonb(s.candidate_id)) filter(where s.candidate_id is not null),'[]'::jsonb) candidate_ids,
      coalesce(jsonb_agg(distinct to_jsonb(gt.candidate_name)) filter(where nullif(gt.candidate_name,'') is not null),'[]'::jsonb) candidate_names
    from generation_timesheets gt


    left join public.v_timesheets_summary_base s on s.timesheet_id=gt.timesheet_id
    group by gt.group_key
  ),
  generation_vat_members as materialized (
    select distinct on (lg.group_json->>'group_key', gt.timesheet_id)
      lg.group_json->>'group_key' group_key,
      gt.timesheet_id,
      coalesce(gt.total_ex_vat,0) total_ex_vat,
      coalesce(vat.vat_rate,0) vat_rate
    from source_groups lg
    left join lateral jsonb_array_elements(
      case when jsonb_typeof(lg.group_json->'canonical_source_members')='array'
        then lg.group_json->'canonical_source_members' else '[]'::jsonb end
    ) member(value) on true
    left join generation_timesheets gt
      on gt.group_key=lg.group_json->>'group_key'
     and gt.timesheet_id=case when pg_input_is_valid(coalesce(member.value->>'related_timesheet_id',member.value->>'source_id',''),'uuid')
       then coalesce(member.value->>'related_timesheet_id',member.value->>'source_id')::uuid end
    left join lateral private._invoice_generation_vat_policy_batch(jsonb_build_array(jsonb_build_object(
      'source_member_key',coalesce(nullif(member.value->>'source_member_key',''), lg.group_json->>'group_key'||':'||coalesce(gt.timesheet_id::text,'')),
      'source_type',member.value->>'source_type',
      'source_id',member.value->>'source_id',
      'timesheet_id',coalesce(member.value->>'related_timesheet_id',member.value->>'source_id'),
      'segment_id',nullif(member.value->>'segment_id',''),
      'effective_date',member.value->>'effective_settings_date'
    ))) vat on true
    where gt.timesheet_id is not null
    order by lg.group_json->>'group_key', gt.timesheet_id, coalesce(vat.vat_rate,0) desc
  ),
  generation_vat as materialized (
    select group_key,
      round(coalesce(sum(total_ex_vat * vat_rate / 100.0),0),2) vat_amount
    from generation_vat_members
    group by group_key
  ),
  create_rows as materialized (
    select
      'generate:'||coalesce(lg.group_json->>'group_key','') selection_key,
      'CREATE_INVOICE' row_kind,
      lg.group_json->>'group_key' scope_key,
      null::uuid invoice_id,
      case when pg_input_is_valid(lg.client_id_text,'uuid') then lg.client_id_text::uuid end client_id,
      lg.client_name,
      coalesce(gci.candidate_ids,'[]'::jsonb) candidate_ids,
      coalesce(gci.candidate_names,'[]'::jsonb) candidate_names,
      case when jsonb_array_length(coalesce(gci.candidate_names,'[]'::jsonb))=1
        then gci.candidate_names->>0
        when jsonb_array_length(coalesce(gci.candidate_names,'[]'::jsonb))>1
        then 'Multiple candidates ('||jsonb_array_length(gci.candidate_names)::text||')'
        else 'Unknown candidate' end candidate_display,
      coalesce((
        select jsonb_agg(distinct to_jsonb(gt.week_ending_date) order by to_jsonb(gt.week_ending_date))
        from generation_timesheets gt where gt.group_key=lg.group_json->>'group_key' and gt.week_ending_date is not null
      ),'[]'::jsonb) week_ending_dates,
      case when pg_input_is_valid(lg.group_json->>'week_ending_date','date') then (lg.group_json->>'week_ending_date')::date end week_ending_date,
      coalesce(nullif(lg.group_json#>>'{command_payload,currency}',''),'GBP') currency,
      upper(coalesce(
        nullif(lg.group_json->>'invoice_stream',''),
        nullif(lg.group_json->>'stream',''),
        'NORMAL'
      )) invoice_stream,
      case when coalesce(lg.group_json->>'subtotal_ex_vat','') ~ '^[+-]?[0-9]+([.][0-9]+)?$'
        then round((lg.group_json->>'subtotal_ex_vat')::numeric,2) else 0 end total_ex_vat,
      coalesce(gv.vat_amount,0) vat_amount,
      round((case when coalesce(lg.group_json->>'subtotal_ex_vat','') ~ '^[+-]?[0-9]+([.][0-9]+)?$'
        then (lg.group_json->>'subtotal_ex_vat')::numeric else 0 end) + coalesce(gv.vat_amount,0),2) total_inc_vat,
      'NOT_GENERATED' generation_state,
      coalesce(lg.group_json->>'blocker_code','') primary_blocker_code,
      coalesce((
        select jsonb_agg(to_jsonb(blocker_code) order by blocker_order, blocker_code)
        from (
          select blocker_code, min(blocker_order) blocker_order
          from (
            select 1 blocker_order, nullif(lg.group_json->>'blocker_code','') blocker_code
            union all
            select 2, nullif(lg.group_json#>>'{blocker_detail,code}','')
            union all
            select 10 + arr.ordinality::integer, nullif(arr.value,'')
            from jsonb_array_elements_text(
              case when jsonb_typeof(lg.group_json->'blocker_codes')='array'
                then lg.group_json->'blocker_codes' else '[]'::jsonb end
            ) with ordinality arr(value, ordinality)
            union all
            select 100 + src.ordinality::integer, nullif(src.value->>'code','')
            from jsonb_array_elements(
              case when jsonb_typeof(lg.group_json#>'{blocker_detail,sources}')='array'
                then lg.group_json#>'{blocker_detail,sources}' else '[]'::jsonb end
            ) with ordinality src(value, ordinality)
          ) raw_codes
          where blocker_code is not null
            and blocker_code not in (
              'EARLY_GENERATION_NOT_ALLOWED',
              'SEGMENT_ALREADY_LOCKED',
              'SOURCE_ALREADY_LOCKED',
              'SOURCE_ALREADY_INVOICED'
            )
          group by blocker_code
        ) blocker_rows
      ),'[]'::jsonb) action_blocker_codes,
      case when coalesce(lg.group_json->>'active_generation_status','') in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        then jsonb_build_array('GENERATING') else '[]'::jsonb end informational_codes,
      (coalesce(lg.group_json->>'active_generation_status','') in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')) is_active,
      lg.group_json->>'active_generation_operation_id' active_operation_id_text,
      lg.group_json->>'active_generation_status' active_operation_status,
      lg.group_json->>'canonical_source_revision' source_revision,
      null::text document_revision,
      lg.group_json->'command_payload' command_payload,
      case when pg_input_is_valid(lg.group_json->>'week_ending_date','date')
        then (lg.group_json->>'week_ending_date')::date >= (coalesce(p_now_utc,now()) at time zone 'Europe/London')::date
        else false end is_early
    from source_groups lg
    left join generation_candidate_ids gci on gci.group_key=lg.group_json->>'group_key'
    left join generation_vat gv on gv.group_key=lg.group_json->>'group_key'
    where coalesce(lg.group_json->>'group_key','')<>''
      and coalesce(lg.group_json->>'blocker_code','') not in (
        'SOURCE_ALREADY_INVOICED',
        'SEGMENT_ALREADY_LOCKED',
        'SOURCE_ALREADY_LOCKED',
        'EARLY_GENERATION_NOT_ALLOWED'
      )
      and coalesce(lg.group_json#>>'{blocker_detail,code}','') not in (
        'SOURCE_ALREADY_INVOICED',
        'SEGMENT_ALREADY_LOCKED',
        'SOURCE_ALREADY_LOCKED'
      )
      and not exists (
        select 1
        from jsonb_array_elements_text(
          case
            when jsonb_typeof(lg.group_json->'blocker_codes')='array'
              then lg.group_json->'blocker_codes'
            else '[]'::jsonb
          end
        ) blocked_code(value)
        where blocked_code.value in (
          'SOURCE_ALREADY_INVOICED',
          'SEGMENT_ALREADY_LOCKED',
          'SOURCE_ALREADY_LOCKED'
        )
      )
      and not exists (
        select 1
        from jsonb_array_elements(
          case
            when jsonb_typeof(lg.group_json#>'{blocker_detail,sources}')='array'
              then lg.group_json#>'{blocker_detail,sources}'
            else '[]'::jsonb
          end
        ) blocked_source(value)
        where blocked_source.value->>'code' in (
          'SOURCE_ALREADY_INVOICED',
          'SEGMENT_ALREADY_LOCKED',
          'SOURCE_ALREADY_LOCKED'
        )
      )
  ),
  stale_invoice_timesheets as materialized (
    select l.invoice_id,
      coalesce(jsonb_agg(distinct to_jsonb(s.candidate_id)) filter(where s.candidate_id is not null),'[]'::jsonb) candidate_ids,
      coalesce(jsonb_agg(distinct to_jsonb(s.candidate_name)) filter(where nullif(s.candidate_name,'') is not null),'[]'::jsonb) candidate_names,
      coalesce(jsonb_agg(distinct to_jsonb(s.week_ending_date)) filter(where s.week_ending_date is not null),'[]'::jsonb) week_ending_dates,
      min(s.week_ending_date) min_week_ending,
      max(s.week_ending_date) max_week_ending
    from public.invoice_lines l
    left join public.v_timesheets_summary_base s on s.timesheet_id=l.timesheet_id
    group by l.invoice_id
  ),
  stale_rows as materialized (
    select
      'invoice:'||i.id::text selection_key,
      case when coalesce(i.document_state,'')='FAILED' then 'RETRY_GENERATION' else 'REGENERATE_DRAFT' end row_kind,
      i.id::text scope_key,
      i.id invoice_id,
      i.client_id,
      c.name client_name,
      coalesce(sit.candidate_ids,'[]'::jsonb) candidate_ids,
      coalesce(sit.candidate_names,'[]'::jsonb) candidate_names,
      case when jsonb_array_length(coalesce(sit.candidate_names,'[]'::jsonb))=1
        then sit.candidate_names->>0
        when jsonb_array_length(coalesce(sit.candidate_names,'[]'::jsonb))>1
        then 'Multiple candidates ('||jsonb_array_length(sit.candidate_names)::text||')'
        else 'Unknown candidate' end candidate_display,
      coalesce(sit.week_ending_dates,'[]'::jsonb) week_ending_dates,
      coalesce(sit.min_week_ending, case when pg_input_is_valid(i.header_snapshot_json#>>'{meta,invoice_week_start}','date') then (i.header_snapshot_json#>>'{meta,invoice_week_start}')::date + 6 end) week_ending_date,
      coalesce(nullif(i.header_snapshot_json#>>'{meta,currency}',''), nullif(i.header_snapshot_json->>'currency',''), 'GBP') currency,
      upper(coalesce(
        nullif(i.header_snapshot_json#>>'{meta,invoice_stream}',''),
        nullif(i.header_snapshot_json->>'invoice_stream',''),
        case when lower(coalesce(
          i.header_snapshot_json#>>'{meta,self_bill}',
          i.header_snapshot_json->>'self_bill',
          'false'
        )) in ('true','t','1','yes') then 'SELF_BILL' end,
        'NORMAL'
      )) invoice_stream,
      round(coalesce(i.subtotal_ex_vat,0),2) total_ex_vat,
      round(coalesce(i.vat_amount,0),2) vat_amount,
      round(coalesce(i.total_inc_vat,coalesce(i.subtotal_ex_vat,0)+coalesce(i.vat_amount,0)),2) total_inc_vat,
      case
        when coalesce(i.document_state,'')='FAILED' then 'FAILED'
        when exists (
          select 1 from public.invoice_document_versions prior_state
          where prior_state.entity_type='INVOICE'
            and prior_state.entity_id=i.id
            and prior_state.purpose='DRAFT_PREVIEW'
        ) then 'STALE'
        else 'NOT_GENERATED'
      end generation_state,
      null::text primary_blocker_code,
      '[]'::jsonb action_blocker_codes,


      case when coalesce(active.status,'') in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        then jsonb_build_array('GENERATING')
        when exists (
          select 1 from public.invoice_document_versions prior_state
          where prior_state.entity_type='INVOICE'
            and prior_state.entity_id=i.id
            and prior_state.purpose='DRAFT_PREVIEW'
        ) then jsonb_build_array('STALE')
        else jsonb_build_array('NOT_GENERATED') end informational_codes,
      (coalesce(active.status,'') in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')) is_active,
      active.operation_id::text active_operation_id_text,
      active.status active_operation_status,
      i.document_revision::text source_revision,
      i.document_revision::text document_revision,
      jsonb_build_object(
        'command_type','VIEW_INVOICE_DOCUMENT',
        'invoice_id',i.id,
        'purpose','DRAFT_PREVIEW',
        'expected_revision',i.document_revision,
        'source_revision',i.document_revision::text
      ) command_payload,
      coalesce(
        sit.max_week_ending,
        case when pg_input_is_valid(i.header_snapshot_json#>>'{meta,invoice_week_start}','date')
          then (i.header_snapshot_json#>>'{meta,invoice_week_start}')::date + 6 end
      ) >= (coalesce(p_now_utc,now()) at time zone 'Europe/London')::date is_early
    from public.invoices i
    join public.clients c on c.id=i.client_id
    left join stale_invoice_timesheets sit on sit.invoice_id=i.id
    left join lateral (
      select o.id operation_id,o.status
      from public.invoice_operations o
      where o.operation_type='BUILD_DOCUMENT'
        and o.entity_type='INVOICE'
        and o.entity_id=i.id
        and o.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      order by o.created_at_utc desc,o.id desc
      limit 1
    ) active on true
    where i.type::text='INVOICE'
      and i.status::text in ('DRAFT','ON_HOLD')
      and coalesce(i.document_revision,0)>0
      and (
        v_mode in ('FACETS','SUMMARY')
        or exists (
          select 1
          from candidate_keys selected_key
          where selected_key.row_kind<>'CREATE_INVOICE'
            and selected_key.invoice_id=i.id
            and selected_key.page_ordinal<=v_page_size
        )
      )
      and not exists (
        select 1
        from public.invoice_document_versions v
        where v.entity_type='INVOICE'
          and v.entity_id=i.id
          and v.purpose='DRAFT_PREVIEW'
          and v.source_revision=i.document_revision::text
          and v.template_version='invoice-professional-v2'
          and v.status='READY'
          and v.r2_key is not null
          and v.sha256 ~ '^[0-9a-f]{64}$'
          and coalesce(v.size_bytes,0)>0
          and coalesce(v.page_count,0)>0
      )

  ),
  all_rows_raw as materialized (
    select * from create_rows
  ),
  all_rows as materialized (
    select r.*,
      (jsonb_array_length(coalesce(r.action_blocker_codes,'[]'::jsonb))=0 and not r.is_active) selectable,
      case when jsonb_array_length(coalesce(r.action_blocker_codes,'[]'::jsonb))>0 then 'BLOCKED'
           when r.is_active then 'IN_PROGRESS'
           when r.generation_state='STALE' then 'STALE'
           when r.generation_state='FAILED' then 'FAILED'
           else 'READY' end row_status
    from all_rows_raw r
  ),
  classification_source as materialized (
    -- PAGE-family requests reuse the exact candidate payload that the keyset
    -- helper already classified. FACETS/SUMMARY do not invoke the keyset
    -- helper, so they retain one direct full-scope classification pass.
    select key_row.selection_key,key_row.candidate_json
    from candidate_keys key_row
    where key_row.page_ordinal<=v_page_size
    union all
    select candidate.selection_key,candidate.candidate_json
    from (
      select 1
      where v_mode in ('FACETS','SUMMARY')
    ) gate
    cross join lateral private._invoice_batch_generate_classification_v2(
      true,
      null,
      coalesce(p_now_utc,statement_timestamp())
    ) candidate
  ),
  authoritative_rows as materialized (
    select
      candidate.candidate_json->>'selection_key' selection_key,
      candidate.candidate_json->>'row_kind' row_kind,
      candidate.candidate_json->>'scope_key' scope_key,
      case
        when pg_input_is_valid(
          coalesce(candidate.candidate_json->>'invoice_id',''),
          'uuid'
        )
          then (candidate.candidate_json->>'invoice_id')::uuid
      end invoice_id,
      case
        when pg_input_is_valid(
          coalesce(candidate.candidate_json->>'client_id',''),
          'uuid'
        )
          then (candidate.candidate_json->>'client_id')::uuid
      end client_id,
      candidate.candidate_json->>'client_name' client_name,
      coalesce(
        candidate.candidate_json->'candidate_ids',
        '[]'::jsonb
      ) candidate_ids,
      coalesce(
        candidate.candidate_json->'candidate_names',
        '[]'::jsonb
      ) candidate_names,
      candidate.candidate_json->>'candidate_display' candidate_display,
      coalesce(
        candidate.candidate_json->'week_ending_dates',
        '[]'::jsonb
      ) week_ending_dates,
      case
        when pg_input_is_valid(
          coalesce(candidate.candidate_json->>'week_ending_date',''),
          'date'
        )
          then (candidate.candidate_json->>'week_ending_date')::date
      end week_ending_date,
      coalesce(
        nullif(candidate.candidate_json->>'currency',''),
        'GBP'
      ) currency,
      upper(coalesce(
        nullif(candidate.candidate_json->>'invoice_stream',''),
        'NORMAL'
      )) invoice_stream,
      coalesce(
        (candidate.candidate_json->>'total_ex_vat')::numeric,
        0
      ) total_ex_vat,
      coalesce(
        (candidate.candidate_json->>'vat_amount')::numeric,
        0
      ) vat_amount,
      coalesce(
        (candidate.candidate_json->>'total_inc_vat')::numeric,
        0
      ) total_inc_vat,
      candidate.candidate_json->>'generation_state' generation_state,
      nullif(
        candidate.candidate_json->>'primary_blocker_code',
        ''
      ) primary_blocker_code,
      coalesce(
        candidate.candidate_json->'action_blocker_codes',
        '[]'::jsonb
      ) action_blocker_codes,
      coalesce(
        candidate.candidate_json->'informational_codes',
        '[]'::jsonb
      ) informational_codes,
      coalesce(
        (candidate.candidate_json->>'is_active')::boolean,
        false
      ) is_active,
      candidate.candidate_json->>'active_operation_id'
        active_operation_id_text,
      candidate.candidate_json->>'active_operation_status'
        active_operation_status,
      candidate.candidate_json->>'source_revision' source_revision,
      candidate.candidate_json->>'document_revision' document_revision,
      candidate.candidate_json->'command_payload' command_payload,
      coalesce(
        (candidate.candidate_json->>'is_early')::boolean,
        false
      ) is_early,
      coalesce(
        (candidate.candidate_json->>'selectable')::boolean,
        false
      ) selectable,
      candidate.candidate_json->>'row_status' row_status
    from classification_source candidate
    where candidate.candidate_json->>'row_kind'='CREATE_INVOICE'
      and (
        v_mode in ('FACETS','SUMMARY')
        or candidate.candidate_json->>'selection_key' in (
          select selected_key.selection_key
          from candidate_keys selected_key
          where selected_key.page_ordinal<=v_page_size
        )
      )
      and coalesce(
        candidate.candidate_json->>'primary_blocker_code',
        ''
      ) not in (
      'SOURCE_ALREADY_INVOICED',
      'SEGMENT_ALREADY_LOCKED',
      'SOURCE_ALREADY_LOCKED'
    )
      and not exists (
        select 1
        from jsonb_array_elements_text(
          case
            when jsonb_typeof(
              candidate.candidate_json->'action_blocker_codes'
            )='array'
              then candidate.candidate_json->'action_blocker_codes'
            else '[]'::jsonb
          end
        ) blocked_code(value)
        where blocked_code.value in (
          'SOURCE_ALREADY_INVOICED',
          'SEGMENT_ALREADY_LOCKED',
          'SOURCE_ALREADY_LOCKED'
        )
      )
  ),
  filter_match_rows as materialized (
    select
      r.*,
      (
        jsonb_array_length(p.client_ids)=0
        or r.client_id::text in (
          select value from jsonb_array_elements_text(p.client_ids)
        )
      ) client_filter_match,
      (
        jsonb_array_length(p.candidate_ids)=0
        or exists (
          select 1
          from jsonb_array_elements_text(r.candidate_ids) row_candidate(id)
          where row_candidate.id in (
            select value from jsonb_array_elements_text(p.candidate_ids)
          )
        )
      ) candidate_filter_match,
      (
        jsonb_array_length(p.week_endings)=0
        or r.week_ending_date::text in (
          select value from jsonb_array_elements_text(p.week_endings)
        )
      ) week_filter_match,
      (
        jsonb_array_length(p.status_codes)=0
        or r.row_status in (
          select upper(value)
          from jsonb_array_elements_text(p.status_codes)
        )
      ) status_filter_match,
      (
        jsonb_array_length(p.blocker_codes)=0
        or exists (
          select 1
          from jsonb_array_elements_text(
            coalesce(r.action_blocker_codes,'[]'::jsonb)
            || coalesce(r.informational_codes,'[]'::jsonb)
          ) badge(code)
          where badge.code in (
            select upper(value)
            from jsonb_array_elements_text(p.blocker_codes)
          )
        )
      ) blocker_filter_match
    from authoritative_rows r
    cross join params p
    where (p.allow_early or not coalesce(r.is_early,false))
      and (
        jsonb_array_length(p.invoice_streams)=0
        or r.invoice_stream in (
          select upper(value)
          from jsonb_array_elements_text(p.invoice_streams)
        )
      )
      and (
        v_mode <> 'EXPLICIT_KEYS'
        or r.selection_key in (
          select value
          from jsonb_array_elements_text(v_selection_keys)
        )
      )
      and (p.search_text is null
        or lower(coalesce(r.client_name,'')||' '||coalesce(r.candidate_display,'')||' '||coalesce(r.scope_key,'')) like '%'||p.search_text||'%')
      and (p.week_ending_from is null or r.week_ending_date >= p.week_ending_from)
      and (p.week_ending_to is null or r.week_ending_date <= p.week_ending_to)
  ),
  scope_rows as materialized (
    select r.*
    from filter_match_rows r
    where r.client_filter_match
      and r.candidate_filter_match
      and r.week_filter_match
      and r.status_filter_match
      and r.blocker_filter_match
  ),
  facet_client_rows as materialized (
    select r.* from filter_match_rows r
    where r.candidate_filter_match and r.week_filter_match
      and r.status_filter_match and r.blocker_filter_match
  ),
  facet_candidate_rows as materialized (
    select r.* from filter_match_rows r
    where r.client_filter_match and r.week_filter_match
      and r.status_filter_match and r.blocker_filter_match
  ),
  facet_week_rows as materialized (
    select r.* from filter_match_rows r
    where r.client_filter_match and r.candidate_filter_match
      and r.status_filter_match and r.blocker_filter_match
  ),
  facet_status_rows as materialized (
    select r.* from filter_match_rows r
    where r.client_filter_match and r.candidate_filter_match
      and r.week_filter_match and r.blocker_filter_match
  ),
  facet_blocker_rows as materialized (
    select r.* from filter_match_rows r
    where r.client_filter_match and r.candidate_filter_match
      and r.week_filter_match and r.status_filter_match
  ),
  facet_client_values_base as materialized (
    select
      client_id,
      min(coalesce(nullif(client_name,''),client_id::text)) label,
      count(*)::integer row_count
    from facet_client_rows
    where client_id is not null
    group by client_id
  ),
  facet_client_values as materialized (
    select b.*,
      row_number() over(order by lower(b.label),b.client_id) facet_ordinal,
      count(*) over() facet_total
    from facet_client_values_base b
    cross join params p
    where (p.facet_search is null
        or lower(b.label) like '%'||p.facet_search||'%'
        or b.client_id::text like p.facet_search||'%')
      and (p.facet_client_after_label is null
        or (lower(b.label),b.client_id::text)>
           (p.facet_client_after_label,coalesce(p.facet_client_after_id,'')))
  ),
  facet_candidate_values_base as materialized (
    select
      candidate.value candidate_id,
      min(coalesce(
        nullif(r.candidate_names->>(candidate.ordinality::integer-1),''),
        candidate.value
      )) label,
      count(distinct r.selection_key)::integer row_count
    from facet_candidate_rows r
    cross join lateral jsonb_array_elements_text(
      coalesce(r.candidate_ids,'[]'::jsonb)
    ) with ordinality candidate(value,ordinality)
    group by candidate.value
  ),
  facet_candidate_values as materialized (
    select b.*,
      row_number() over(order by lower(b.label),b.candidate_id) facet_ordinal,
      count(*) over() facet_total
    from facet_candidate_values_base b
    cross join params p
    where (p.facet_search is null
        or lower(b.label) like '%'||p.facet_search||'%'
        or b.candidate_id like p.facet_search||'%')
      and (p.facet_candidate_after_label is null
        or (lower(b.label),b.candidate_id)>
           (p.facet_candidate_after_label,coalesce(p.facet_candidate_after_id,'')))
  ),
  facet_week_values as materialized (
    select b.*,
      row_number() over(order by b.week_ending_date desc) facet_ordinal,
      count(*) over() facet_total
    from (
      select week_ending_date,count(*)::integer row_count
      from facet_week_rows
      where week_ending_date is not null
      group by week_ending_date
    ) b
    cross join params p
    where (p.facet_search is null
        or to_char(b.week_ending_date,'DD/MM/YYYY') like '%'||p.facet_search||'%'
        or b.week_ending_date::text like '%'||p.facet_search||'%')
      and (p.facet_week_after_value is null
        or b.week_ending_date<p.facet_week_after_value)
  ),
  facet_status_values as materialized (
    select b.*,
      row_number() over(order by b.row_status) facet_ordinal,
      count(*) over() facet_total
    from (
      select row_status,count(*)::integer row_count
      from facet_status_rows
      group by row_status
    ) b
    cross join params p
    where (p.facet_search is null
        or lower(b.row_status) like '%'||p.facet_search||'%'
        or lower(replace(b.row_status,'_',' ')) like '%'||p.facet_search||'%')
      and (p.facet_status_after_code is null
        or b.row_status>p.facet_status_after_code)
  ),
  facet_blocker_values as materialized (
    select b.*,
      row_number() over(order by b.code) facet_ordinal,
      count(*) over() facet_total
    from (
      select badge.code,count(distinct r.selection_key)::integer row_count
      from facet_blocker_rows r
      cross join lateral jsonb_array_elements_text(
        coalesce(r.action_blocker_codes,'[]'::jsonb)
        || coalesce(r.informational_codes,'[]'::jsonb)
      ) badge(code)
      group by badge.code
    ) b
    cross join params p
    where (p.facet_search is null
        or lower(b.code) like '%'||p.facet_search||'%'
        or lower(replace(b.code,'_',' ')) like '%'||p.facet_search||'%')
      and (p.facet_blocker_after_code is null
        or b.code>p.facet_blocker_after_code)
  ),
  grouped_scope_rows as materialized (
    select
      r.*,
      private._invoice_batch_hash_v2(jsonb_build_object(
        'action','GENERATE',
        'group_preset',p.group_preset,
        'status_code',case when p.group_preset='STATUS_WEEK_CLIENT' then r.row_status end,
        'week_ending_date',r.week_ending_date,
        'client_id',r.client_id,
        'candidate_ids',case
          when p.group_preset='STATUS_WEEK_CLIENT' then '[]'::jsonb
          else coalesce(r.candidate_ids,'[]'::jsonb)
        end
      )) group_key
    from scope_rows r
    cross join params p
  ),
  selection_scope_rows as materialized (
    select
      fr.*,
      coalesce((
        select sr.action
        from selection_rules sr
        where (sr.selector_type='ROW' and sr.selection_key=fr.selection_key)
           or (sr.selector_type='WEEK' and sr.week_ending_date=fr.week_ending_date)
           or (sr.selector_type='CLIENT' and sr.client_id=fr.client_id)
           or (sr.selector_type='CANDIDATE' and exists (
             select 1 from jsonb_array_elements_text(fr.candidate_ids) cid(value)
             where pg_input_is_valid(cid.value,'uuid') and cid.value::uuid=sr.candidate_id
           ))
           or (sr.selector_type='STATUS' and sr.status_code=fr.row_status)
           or (sr.selector_type='WEEK_CLIENT' and sr.week_ending_date=fr.week_ending_date and sr.client_id=fr.client_id)
           or (sr.selector_type='WEEK_CLIENT_CANDIDATE' and sr.week_ending_date=fr.week_ending_date and sr.client_id=fr.client_id and exists (
             select 1 from jsonb_array_elements_text(fr.candidate_ids) cid(value)
             where pg_input_is_valid(cid.value,'uuid') and cid.value::uuid=sr.candidate_id
           ))
           or (sr.selector_type='STATUS_WEEK' and sr.status_code=fr.row_status and sr.week_ending_date=fr.week_ending_date)
           or (sr.selector_type='STATUS_WEEK_CLIENT' and sr.status_code=fr.row_status and sr.week_ending_date=fr.week_ending_date and sr.client_id=fr.client_id)
           or (sr.selector_type='DIMENSION_GROUP'
             and (sr.week_ending_date is null or sr.week_ending_date=fr.week_ending_date)
             and (sr.client_id is null or sr.client_id=fr.client_id)
             and (sr.status_code is null or sr.status_code=fr.row_status)
             and (sr.candidate_id is null or exists (
               select 1 from jsonb_array_elements_text(fr.candidate_ids) cid(value)
               where pg_input_is_valid(cid.value,'uuid') and cid.value::uuid=sr.candidate_id
             )))
        order by sr.rule_sequence desc
        limit 1
      ),'INCLUDE') last_selection_action
    from grouped_scope_rows fr
  ),
  filtered_rows as materialized (
    select r.*
    from selection_scope_rows r
    cross join params p
    where (
      v_mode='EXPAND_SELECTION'
      or p.display_mode='ALL'
      or (p.display_mode='READY' and r.selectable)
      or (p.display_mode='BLOCKED' and r.row_status='BLOCKED')
    )
      and (
        v_mode<>'EXPAND_SELECTION'
        or (
          r.selectable
          and r.last_selection_action<>'EXCLUDE'
        )
      )
  ),
  sortable_rows as materialized (
    select fr.*,
      case when p.sort_key='WEEK_ENDING_DATE' then coalesce(fr.week_ending_date, case when p.sort_direction='DESC' then date '0001-01-01' else date '9999-12-31' end) end sort_date_key,
      case when p.sort_key='CLIENT_NAME' then coalesce(lower(fr.client_name), case when p.sort_direction='DESC' then '' else repeat('~',100) end)
           when p.sort_key='CANDIDATE_NAME' then coalesce(lower(fr.candidate_display), case when p.sort_direction='DESC' then '' else repeat('~',100) end)
           when p.sort_key='STATUS' then
             lpad((case fr.row_status
               when 'READY' then 10
               when 'STALE' then 20
               when 'FAILED' then 30
               when 'IN_PROGRESS' then 40
               else 50
             end)::text,3,'0')||'|'||lower(coalesce(fr.row_status,'BLOCKED'))
           end sort_text_key,
      case when p.sort_key='TOTAL_EX_VAT' then coalesce(fr.total_ex_vat, case when p.sort_direction='DESC' then -999999999999999999::numeric else 999999999999999999::numeric end)
           when p.sort_key='TOTAL_INC_VAT' then coalesce(fr.total_inc_vat, case when p.sort_direction='DESC' then -999999999999999999::numeric else 999999999999999999::numeric end) end sort_numeric_key
    from filtered_rows fr cross join params p
  ),
  cursor_filtered_rows as materialized (
    select sr.*
    from sortable_rows sr
    cross join params p
    where p.after_key is null
       or (
         p.sort_key='WEEK_ENDING_DATE'
         and p.after_sort_date is not null
         and ((p.sort_direction='ASC' and (sr.sort_date_key > p.after_sort_date or (sr.sort_date_key=p.after_sort_date and sr.selection_key>p.after_key)))
           or (p.sort_direction='DESC' and (sr.sort_date_key < p.after_sort_date or (sr.sort_date_key=p.after_sort_date and sr.selection_key>p.after_key))))
       )
       or (
         p.sort_key in ('CLIENT_NAME','CANDIDATE_NAME','STATUS')
         and p.after_sort_text is not null
         and ((p.sort_direction='ASC' and (sr.sort_text_key > p.after_sort_text or (sr.sort_text_key=p.after_sort_text and sr.selection_key>p.after_key)))
           or (p.sort_direction='DESC' and (sr.sort_text_key < p.after_sort_text or (sr.sort_text_key=p.after_sort_text and sr.selection_key>p.after_key))))
       )
       or (
         p.sort_key in ('TOTAL_EX_VAT','TOTAL_INC_VAT')
         and p.after_sort_numeric is not null
         and ((p.sort_direction='ASC' and (sr.sort_numeric_key > p.after_sort_numeric or (sr.sort_numeric_key=p.after_sort_numeric and sr.selection_key>p.after_key)))
           or (p.sort_direction='DESC' and (sr.sort_numeric_key < p.after_sort_numeric or (sr.sort_numeric_key=p.after_sort_numeric and sr.selection_key>p.after_key))))
       )
       or (
         ((p.sort_key='WEEK_ENDING_DATE' and p.after_sort_date is null)
           or (p.sort_key in ('CLIENT_NAME','CANDIDATE_NAME','STATUS') and p.after_sort_text is null)
           or (p.sort_key in ('TOTAL_EX_VAT','TOTAL_INC_VAT') and p.after_sort_numeric is null))
         and sr.selection_key > p.after_key
       )
  ),
  selected_rows as materialized (
    select * from cursor_filtered_rows
  ),
  candidate_page_source as materialized (
    select * from selected_rows where v_mode='EXPAND_SELECTION'
    union all
    select * from selected_rows where v_mode in('PAGE','EXPLICIT_KEYS')
  ),
  ordered_page_rows as materialized (
    select src.*,
      row_number() over (order by
        case when v_mode='EXPAND_SELECTION' then src.selection_key end asc,
        case when p.sort_key='WEEK_ENDING_DATE' and p.sort_direction='ASC' then src.sort_date_key end asc nulls last,
        case when p.sort_key='WEEK_ENDING_DATE' and p.sort_direction='DESC' then src.sort_date_key end desc nulls last,
        case when p.sort_key in ('CLIENT_NAME','CANDIDATE_NAME','STATUS') and p.sort_direction='ASC' then src.sort_text_key end asc nulls last,
        case when p.sort_key in ('CLIENT_NAME','CANDIDATE_NAME','STATUS') and p.sort_direction='DESC' then src.sort_text_key end desc nulls last,
        case when p.sort_key in ('TOTAL_EX_VAT','TOTAL_INC_VAT') and p.sort_direction='ASC' then src.sort_numeric_key end asc nulls last,
        case when p.sort_key in ('TOTAL_EX_VAT','TOTAL_INC_VAT') and p.sort_direction='DESC' then src.sort_numeric_key end desc nulls last,
        src.selection_key asc
      ) page_ordinal
    from candidate_page_source src cross join params p
  ),
  page_rows as materialized (
    select * from ordered_page_rows
    where page_ordinal <= (select page_size + 1 from params)
  ),
  visible_rows as materialized (
    select * from page_rows
    where page_ordinal <= (select page_size from params)
  ),
  totals as materialized (
    select
      count(*)::integer all_count,
      count(*) filter(where selectable)::integer ready_count,
      count(*) filter(where selectable and last_selection_action <> 'EXCLUDE')::integer selected_count,
      count(*) filter(where not selectable)::integer blocked_count,
      count(*) filter(where row_status='IN_PROGRESS')::integer in_progress_count,
      count(*) filter(where generation_state='NOT_GENERATED')::integer not_generated_count,
      count(*) filter(where generation_state='STALE')::integer stale_count,
      count(*) filter(where generation_state='FAILED')::integer failed_retryable_count
    from selection_scope_rows
  ),
  display_totals as materialized (
    select count(*)::integer display_count
    from filtered_rows
  ),
  visible_group_keys as materialized (
    select distinct group_key
    from visible_rows
    where v_mode = 'PAGE'
  ),
  page_group_rollup as materialized (
    select
      r.group_key,
      min(r.week_ending_date) week_ending_date,
      (array_agg(r.client_id order by r.selection_key))[1] client_id,
      min(r.row_status) row_status,
      (array_agg(r.candidate_ids order by r.selection_key))[1] candidate_ids,
      count(*)::integer row_total,
      count(*) filter (where r.selectable)::integer eligible_total,
      count(*) filter (
        where r.selectable and r.last_selection_action <> 'EXCLUDE'
      )::integer selected_total,
      count(*) filter (where v.group_key is not null)::integer visible_total
    from selection_scope_rows r
    join visible_group_keys g on g.group_key = r.group_key
    left join visible_rows v
      on v.group_key = r.group_key
     and v.selection_key = r.selection_key
    group by r.group_key
  ),
  page_group_selection_json as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'group_key',g.group_key,
      'selector',case
        when p.group_preset='STATUS_WEEK_CLIENT' then jsonb_build_object(
          'type','STATUS_WEEK_CLIENT',
          'status_code',g.row_status,
          'week_ending_date',g.week_ending_date,
          'client_id',g.client_id
        )
        when jsonb_array_length(coalesce(g.candidate_ids,'[]'::jsonb))=1
          then jsonb_build_object(
            'type','WEEK_CLIENT_CANDIDATE',
            'week_ending_date',g.week_ending_date,
            'client_id',g.client_id,
            'candidate_id',g.candidate_ids->>0
          )
        else jsonb_build_object(
          'type','WEEK_CLIENT',
          'week_ending_date',g.week_ending_date,
          'client_id',g.client_id
        )
      end,
      'eligible_total',g.eligible_total,
      'selected_total',g.selected_total,
      'state',case
        when g.eligible_total = 0 then 'DISABLED'
        when g.selected_total = 0 then 'UNCHECKED'
        when g.selected_total = g.eligible_total then 'CHECKED'
        else 'INDETERMINATE'
      end,
      'has_hidden_override',
        g.visible_total < g.row_total
        and g.selected_total not in (0,g.eligible_total)
    ) order by g.group_key),'[]'::jsonb) groups
    from page_group_rollup g
    cross join params p
  ),
  requested_group_selectors as materialized (
    select
      selector.ordinality::integer request_ordinal,
      selector.value selector,
      upper(selector.value->>'type') selector_type,
      nullif(btrim(selector.value->>'selection_key'),'') selection_key,
      case when selector.value ? 'week_ending_date'
        then (selector.value->>'week_ending_date')::date end week_ending_date,
      case when selector.value ? 'client_id'
        then (selector.value->>'client_id')::uuid end client_id,
      case when selector.value ? 'candidate_id'
        then (selector.value->>'candidate_id')::uuid end candidate_id,
      nullif(upper(btrim(selector.value->>'status_code')),'') status_code
    from jsonb_array_elements(coalesce(v_query->'group_selectors','[]'::jsonb))
      with ordinality selector(value, ordinality)
    where v_mode = 'SUMMARY'
  ),
  requested_group_members as materialized (
    select
      requested.request_ordinal,
      requested.selector,
      row_scope.*
    from requested_group_selectors requested
    join selection_scope_rows row_scope on row_scope.selectable
      and (
        (requested.selector_type='ROW'
          and requested.selection_key=row_scope.selection_key)
        or (requested.selector_type='WEEK'
          and requested.week_ending_date=row_scope.week_ending_date)
        or (requested.selector_type='CLIENT'
          and requested.client_id=row_scope.client_id)
        or (requested.selector_type='CANDIDATE' and exists (
          select 1
          from jsonb_array_elements_text(
            coalesce(row_scope.candidate_ids,'[]'::jsonb)
          ) candidate(value)
          where pg_input_is_valid(candidate.value,'uuid')
            and candidate.value::uuid=requested.candidate_id
        ))
        or (requested.selector_type='STATUS'
          and requested.status_code=row_scope.row_status)
        or (requested.selector_type='WEEK_CLIENT'
          and requested.week_ending_date=row_scope.week_ending_date
          and requested.client_id=row_scope.client_id)
        or (requested.selector_type='WEEK_CLIENT_CANDIDATE'
          and requested.week_ending_date=row_scope.week_ending_date
          and requested.client_id=row_scope.client_id
          and exists (
            select 1
            from jsonb_array_elements_text(
              coalesce(row_scope.candidate_ids,'[]'::jsonb)
            ) candidate(value)
            where pg_input_is_valid(candidate.value,'uuid')
              and candidate.value::uuid=requested.candidate_id
          ))
        or (requested.selector_type='STATUS_WEEK'
          and requested.status_code=row_scope.row_status
          and requested.week_ending_date=row_scope.week_ending_date)
        or (requested.selector_type='STATUS_WEEK_CLIENT'
          and requested.status_code=row_scope.row_status
          and requested.week_ending_date=row_scope.week_ending_date
          and requested.client_id=row_scope.client_id)
        or (requested.selector_type='DIMENSION_GROUP'
          and (requested.week_ending_date is null or requested.week_ending_date=row_scope.week_ending_date)
          and (requested.client_id is null or requested.client_id=row_scope.client_id)
          and (requested.status_code is null or requested.status_code=row_scope.row_status)
          and (requested.candidate_id is null or exists (
            select 1 from jsonb_array_elements_text(row_scope.candidate_ids) candidate(value)
            where pg_input_is_valid(candidate.value,'uuid')
              and candidate.value::uuid=requested.candidate_id
          )))
      )
  ),
  requested_group_base as materialized (
    select
      requested.*,
      coalesce((
        select rule.action
        from selection_rules rule
        where exists (
          select 1
          from requested_group_members member
          where member.request_ordinal=requested.request_ordinal
        )
          and not exists (
            select 1
            from requested_group_members member
            where member.request_ordinal=requested.request_ordinal
              and (
                (rule.selector_type='ROW'
                  and rule.selection_key=member.selection_key)
                or (rule.selector_type='WEEK'
                  and rule.week_ending_date=member.week_ending_date)
                or (rule.selector_type='CLIENT'
                  and rule.client_id=member.client_id)
                or (rule.selector_type='CANDIDATE' and exists (
                  select 1
                  from jsonb_array_elements_text(
                    coalesce(member.candidate_ids,'[]'::jsonb)
                  ) candidate(value)
                  where pg_input_is_valid(candidate.value,'uuid')
                    and candidate.value::uuid=rule.candidate_id
                ))
                or (rule.selector_type='STATUS'
                  and rule.status_code=member.row_status)
                or (rule.selector_type='WEEK_CLIENT'
                  and rule.week_ending_date=member.week_ending_date
                  and rule.client_id=member.client_id)
                or (rule.selector_type='WEEK_CLIENT_CANDIDATE'
                  and rule.week_ending_date=member.week_ending_date
                  and rule.client_id=member.client_id
                  and exists (
                    select 1
                    from jsonb_array_elements_text(
                      coalesce(member.candidate_ids,'[]'::jsonb)
                    ) candidate(value)
                    where pg_input_is_valid(candidate.value,'uuid')
                      and candidate.value::uuid=rule.candidate_id
                  ))
                or (rule.selector_type='STATUS_WEEK'
                  and rule.status_code=member.row_status
                  and rule.week_ending_date=member.week_ending_date)
                or (rule.selector_type='STATUS_WEEK_CLIENT'
                  and rule.status_code=member.row_status
                  and rule.week_ending_date=member.week_ending_date
                  and rule.client_id=member.client_id)
                or (rule.selector_type='DIMENSION_GROUP'
                  and (rule.week_ending_date is null or rule.week_ending_date=member.week_ending_date)
                  and (rule.client_id is null or rule.client_id=member.client_id)
                  and (rule.status_code is null or rule.status_code=member.row_status)
                  and (rule.candidate_id is null or exists (
                    select 1 from jsonb_array_elements_text(member.candidate_ids) candidate(value)
                    where pg_input_is_valid(candidate.value,'uuid')
                      and candidate.value::uuid=rule.candidate_id
                  )))
              ) is not true
          )
        order by rule.rule_sequence desc
        limit 1
      ),'INCLUDE') base_action
    from requested_group_selectors requested
  ),
  requested_group_rollup as materialized (
    select
      requested.request_ordinal,
      requested.selector,
      case when count(distinct member.group_key)=1
        then min(member.group_key) end group_key,
      count(member.selection_key)::integer eligible_total,
      count(member.selection_key) filter (
        where member.last_selection_action <> 'EXCLUDE'
      )::integer selected_total,
      coalesce(bool_or(
        member.last_selection_action is distinct from requested.base_action
      ) filter (where member.selection_key is not null),false)
        has_hidden_override
    from requested_group_base requested
    left join requested_group_members member
      on member.request_ordinal=requested.request_ordinal
    group by
      requested.request_ordinal,
      requested.selector,
      requested.base_action
  ),
  summary_group_selection_json as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'selector',rollup.selector,
      'group_key',rollup.group_key,
      'eligible_total',rollup.eligible_total,
      'selected_total',rollup.selected_total,
      'state',case
        when rollup.eligible_total=0 then 'DISABLED'
        when rollup.selected_total=0 then 'UNCHECKED'
        when rollup.selected_total=rollup.eligible_total
          and not rollup.has_hidden_override then 'CHECKED'
        else 'INDETERMINATE'
      end,
      'has_hidden_override',rollup.has_hidden_override
    ) order by rollup.request_ordinal),'[]'::jsonb) groups
    from requested_group_rollup rollup
  ),
  group_selection_json as materialized (
    select case
      when v_mode='SUMMARY' then summary_groups.groups
      else page_groups.groups
    end groups
    from page_group_selection_json page_groups
    cross join summary_group_selection_json summary_groups
  ),
  facet_json as materialized (
    select jsonb_strip_nulls(jsonb_build_object(
      'clients',case when p.facet_kinds ? 'CLIENTS' then jsonb_build_object(
        'items',coalesce((select jsonb_agg(jsonb_build_object(
          'id',f.client_id,'label',f.label,'count',f.row_count
        ) order by f.facet_ordinal) from facet_client_values f
          where f.facet_ordinal<=p.facet_limit),'[]'::jsonb),
        'has_more',coalesce((select max(f.facet_total)>p.facet_limit
          from facet_client_values f),false),
        'next_cursor_values',case when coalesce((select max(f.facet_total)>p.facet_limit
          from facet_client_values f),false) then (
          select jsonb_build_object('after_label',lower(f.label),'after_id',f.client_id)
          from facet_client_values f where f.facet_ordinal=p.facet_limit
        ) end
      ) end,
      'candidates',case when p.facet_kinds ? 'CANDIDATES' then jsonb_build_object(
        'items',coalesce((select jsonb_agg(jsonb_build_object(
          'id',f.candidate_id,'label',f.label,'count',f.row_count
        ) order by f.facet_ordinal) from facet_candidate_values f
          where f.facet_ordinal<=p.facet_limit),'[]'::jsonb),
        'has_more',coalesce((select max(f.facet_total)>p.facet_limit
          from facet_candidate_values f),false),
        'next_cursor_values',case when coalesce((select max(f.facet_total)>p.facet_limit
          from facet_candidate_values f),false) then (
          select jsonb_build_object('after_label',lower(f.label),'after_id',f.candidate_id)
          from facet_candidate_values f where f.facet_ordinal=p.facet_limit
        ) end
      ) end,
      'week_endings',case when p.facet_kinds ? 'WEEK_ENDINGS' then jsonb_build_object(
        'items',coalesce((select jsonb_agg(jsonb_build_object(
          'value',f.week_ending_date,'label',to_char(f.week_ending_date,'DD/MM/YYYY'),
          'count',f.row_count
        ) order by f.facet_ordinal) from facet_week_values f
          where f.facet_ordinal<=p.facet_limit),'[]'::jsonb),
        'has_more',coalesce((select max(f.facet_total)>p.facet_limit
          from facet_week_values f),false),
        'next_cursor_values',case when coalesce((select max(f.facet_total)>p.facet_limit
          from facet_week_values f),false) then (
          select jsonb_build_object('after_value',f.week_ending_date)
          from facet_week_values f where f.facet_ordinal=p.facet_limit
        ) end
      ) end,
      'statuses',case when p.facet_kinds ? 'STATUSES' then jsonb_build_object(
        'items',coalesce((select jsonb_agg(jsonb_build_object(
          'code',f.row_status,'label',initcap(replace(lower(f.row_status),'_',' ')),
          'count',f.row_count
        ) order by f.facet_ordinal) from facet_status_values f
          where f.facet_ordinal<=p.facet_limit),'[]'::jsonb),
        'has_more',coalesce((select max(f.facet_total)>p.facet_limit
          from facet_status_values f),false),
        'next_cursor_values',case when coalesce((select max(f.facet_total)>p.facet_limit
          from facet_status_values f),false) then (
          select jsonb_build_object('after_code',f.row_status)
          from facet_status_values f where f.facet_ordinal=p.facet_limit
        ) end
      ) end,
      'blockers',case when p.facet_kinds ? 'BLOCKERS' then jsonb_build_object(
        'items',coalesce((select jsonb_agg(jsonb_build_object(
          'code',f.code,'count',f.row_count
        ) order by f.facet_ordinal) from facet_blocker_values f
          where f.facet_ordinal<=p.facet_limit),'[]'::jsonb),
        'has_more',coalesce((select max(f.facet_total)>p.facet_limit
          from facet_blocker_values f),false),
        'next_cursor_values',case when coalesce((select max(f.facet_total)>p.facet_limit
          from facet_blocker_values f),false) then (
          select jsonb_build_object('after_code',f.code)
          from facet_blocker_values f where f.facet_ordinal=p.facet_limit
        ) end
      ) end
    )) facets
    from params p
  ),
  row_json as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'selection_key',selection_key,
      'group_key',group_key,
      'row_kind',row_kind,
      'scope_key',scope_key,
      'invoice_id',invoice_id,
      'client_id',client_id,
      'client_name',client_name,
      'candidate_ids',candidate_ids,
      'candidate_names',candidate_names,
      'candidate_display',candidate_display,
      'week_ending_dates',week_ending_dates,
      'week_ending_date',week_ending_date,
      'week_ending_display',case when jsonb_array_length(week_ending_dates)>1 then 'Multiple weeks' else to_char(week_ending_date,'DD/MM/YYYY') end,
      'currency',currency,
      'invoice_stream',invoice_stream,
      'total_ex_vat',total_ex_vat,
      'vat_amount',vat_amount,
      'total_inc_vat',total_inc_vat,
      'generation_state',generation_state,
      'row_status',row_status,
      'is_early',is_early,
      'selectable',selectable,
      'selected',selectable and last_selection_action <> 'EXCLUDE',
      'action_blocker_codes',coalesce(action_blocker_codes,'[]'::jsonb),
      'informational_codes',coalesce(informational_codes,'[]'::jsonb),
      'active_operation_id',active_operation_id_text,
      'active_operation_status',active_operation_status,
      'source_revision',source_revision,
      'document_revision',document_revision,
      'command_payload',command_payload,
      'sort_tuple',jsonb_build_object(
        'sort_date',case when sort_date_key is not null then sort_date_key::text end,
        'sort_text',sort_text_key,
        'sort_numeric',case when sort_numeric_key is not null then sort_numeric_key::text end,
        'selection_key',selection_key
      )
    ) order by page_ordinal),'[]'::jsonb) rows
    from visible_rows
  )
  select jsonb_build_object(
    'contract_version','INVOICE_BATCH_CANDIDATES_V2',
    'action','GENERATE',
    'mode',v_mode,
    'snapshot',v_snapshot,
    'normalised_filter',v_filters,
    'normalised_sort',v_sort,
    'filter_hash',v_filter_hash,
    'query_hash',v_query_hash,
    'selection_hash',v_selection_hash,
    'rows',(select rows from row_json),
    'page',jsonb_build_object(
      'page_size',v_page_size,
      'returned_count',(select count(*) from visible_rows),
      'total_count',case
        when v_mode in ('PAGE','EXPAND_SELECTION','EXPLICIT_KEYS')
          then coalesce((select max(k.full_scope_count) from candidate_keys k),0)
        else (select display_count from display_totals)
      end,
      'has_more',case
        when v_mode in ('PAGE','EXPAND_SELECTION','EXPLICIT_KEYS')
          then exists (
            select 1
            from candidate_keys k
            where k.page_ordinal>v_page_size
          )
        else (select count(*) from page_rows)>v_page_size
      end,
      'next_cursor_values',case when (
        case
          when v_mode in ('PAGE','EXPAND_SELECTION','EXPLICIT_KEYS')
            then exists (
              select 1
              from candidate_keys k
              where k.page_ordinal>v_page_size
            )
          else (select count(*) from page_rows)>v_page_size
        end
      ) then (
        select case when v_mode='EXPAND_SELECTION'
          then jsonb_build_object('after_selection_key',selection_key)
          else jsonb_build_object(
            'after_selection_key',selection_key,
            'after_sort_date',case when sort_date_key is not null then sort_date_key::text end,
            'after_sort_text',sort_text_key,
            'after_sort_numeric',case when sort_numeric_key is not null then sort_numeric_key::text end
          )
        end
        from (
          select
            selection_key,
            sort_date_key,
            sort_text_key,
            sort_numeric_key,
            page_ordinal
          from candidate_keys
          where page_ordinal<=v_page_size
        ) cursor_source
        order by page_ordinal desc
        limit 1
      ) else null end
    ),
    'totals',jsonb_build_object(
      'all',(select all_count from totals),
      'filtered_total',(select all_count from totals),
      'display_total',(select display_count from display_totals),
      'eligible_total',(select ready_count from totals),
      'selected_total',(select selected_count from totals),
      'excluded_total',(select ready_count-selected_count from totals),
      'ready',(select ready_count from totals),
      'blocked',(select blocked_count from totals),
      'blocked_total',(select blocked_count from totals),
      'in_progress',(select in_progress_count from totals),
      'not_generated',(select not_generated_count from totals),
      'stale',(select stale_count from totals),
      'failed_retryable',(select failed_retryable_count from totals)
    ),
    'selection_summary',jsonb_build_object(
      'eligible_total',(select ready_count from totals),
      'selected_total',(select selected_count from totals),
      'excluded_total',(select ready_count-selected_count from totals),
      'blocked_total',(select blocked_count from totals),
      'exact',v_mode in ('FACETS','SUMMARY')
    ),
    'group_selection',(select groups from group_selection_json),
    'facets',case
      when v_mode='FACETS' then (select facets from facet_json)
      else jsonb_build_object()
    end,
    'selection_seed',jsonb_build_object('mode','IMPLICIT_ALL','default_selected',true)
  ) into v_result;

  if v_mode='SUMMARY'
     and coalesce((v_result#>>'{totals,filtered_total}')::integer,0)>25000 then
    raise exception using
      errcode='54000',
      message='BATCH_SUMMARY_SCOPE_TOO_LARGE';
  end if;

  if v_mode='EXPLICIT_KEYS' and (
    jsonb_array_length(coalesce(v_result->'rows','[]'::jsonb))
      <> jsonb_array_length(v_selection_keys)
    or exists (
      select 1
      from jsonb_array_elements(v_result->'rows') row_item(row_json)
      where coalesce(row_json->>'source_revision','')
        is distinct from coalesce(
          v_expected_source_revisions->>(row_json->>'selection_key'),
          ''
        )
    )
  ) then
    raise exception using
      errcode='40001',
      message='BATCH_SOURCE_CHANGED';
  end if;

  v_snapshot_after := private._invoice_candidate_snapshot_verify_v2(
    'GENERATE',
    v_snapshot,
    coalesce(p_now_utc,now())
  );
  if v_snapshot_after->>'revision' <> v_snapshot->>'revision' then
    raise exception using errcode='40001', message='BATCH_SNAPSHOT_CHANGED';
  end if;

  return v_result;
end;
$function$;

alter function private._invoice_batch_generate_candidate_rows_v2(jsonb,timestamptz) OWNER TO CURRENT_USER;
revoke all on function private._invoice_batch_generate_candidate_rows_v2(jsonb,timestamptz) from public, anon, authenticated;
grant execute on function private._invoice_batch_generate_candidate_rows_v2(jsonb,timestamptz) to service_role;


create or replace function private._invoice_batch_issue_candidate_rows_v2(
  p_query jsonb default '{}'::jsonb,
  p_now_utc timestamptz default now()
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_query jsonb := coalesce(p_query,'{}'::jsonb);
  v_mode text;
  v_filters jsonb;
  v_sort jsonb;
  v_selection jsonb;
  v_selection_keys jsonb;
  v_expected_source_revisions jsonb;
  v_page_size integer;
  v_after_key text;
  v_allow_early boolean;
  v_display_mode text;
  v_input_snapshot jsonb;
  v_snapshot jsonb;
  v_snapshot_after jsonb;
  v_filter_hash text;
  v_query_hash text;
  v_selection_hash text;
  v_result jsonb;
begin
  v_query := private._invoice_batch_query_validate_v2(v_query, 'ISSUE');

  if jsonb_typeof(v_query) is distinct from 'object' then
    raise exception using errcode='22023', message='INVOICE_BATCH_QUERY_INVALID';
  end if;

  if coalesce(v_query->>'contract_version','INVOICE_BATCH_QUERY_V2') <> 'INVOICE_BATCH_QUERY_V2' then
    raise exception using errcode='22023', message='INVOICE_BATCH_QUERY_CONTRACT_INVALID';
  end if;

  v_mode := upper(coalesce(nullif(v_query->>'mode',''),'PAGE'));
  if v_mode not in ('PAGE','FACETS','SUMMARY','EXPAND_SELECTION','EXPLICIT_KEYS') then
    raise exception using errcode='22023', message='INVOICE_BATCH_QUERY_MODE_INVALID';
  end if;

  v_selection_keys := coalesce(v_query->'selection_keys','[]'::jsonb);
  v_expected_source_revisions := coalesce(
    v_query->'expected_source_revisions',
    '{}'::jsonb
  );
  if v_mode='EXPLICIT_KEYS' then
    if jsonb_typeof(v_selection_keys) is distinct from 'array'
       or jsonb_array_length(v_selection_keys) < 1
       or jsonb_array_length(v_selection_keys) > 100
       or jsonb_typeof(v_expected_source_revisions) is distinct from 'object'
       or exists (
         select 1
         from jsonb_array_elements(v_selection_keys) with ordinality key_item(value,ordinality)
         where jsonb_typeof(key_item.value) is distinct from 'string'
            or nullif(btrim(key_item.value #>> '{}'),'') is null
            or length(btrim(key_item.value #>> '{}')) > 512
       )
       or (
         select count(*) from jsonb_array_elements_text(v_selection_keys)
       ) <> (
         select count(distinct value)
         from jsonb_array_elements_text(v_selection_keys) explicit_key(value)
       )
       or exists (
         select 1
         from jsonb_array_elements_text(v_selection_keys) explicit_key(value)
         where nullif(v_expected_source_revisions->>explicit_key.value,'') is null
       ) then
      raise exception using
        errcode='22023',
        message='INVOICE_BATCH_EXPLICIT_KEYS_INVALID';
    end if;
  end if;

  v_filters := case when jsonb_typeof(v_query->'filters') = 'object' then v_query->'filters' else '{}'::jsonb end;
  v_sort := case when jsonb_typeof(v_query->'sort') = 'object' then v_query->'sort' else '{}'::jsonb end;
  v_selection := case when jsonb_typeof(v_query->'selection') = 'object' then v_query->'selection' else jsonb_build_object(
    'contract_version','INVOICE_BATCH_SELECTION_V2',
    'mode','IMPLICIT_ALL',
    'default_selected',true,
    'rules','[]'::jsonb
  ) end;

  perform 1 from private._invoice_batch_selection_rules_v2(v_selection) limit 1;

  v_allow_early := coalesce((v_filters->>'allow_early')::boolean,false);
  v_display_mode := upper(coalesce(
    nullif(v_filters->>'display_mode',''),
    'ALL'
  ));
  if v_display_mode not in ('ALL','READY','BLOCKED') then
    raise exception using errcode='22023', message='INVOICE_BATCH_DISPLAY_MODE_INVALID';
  end if;

  if upper(coalesce(v_sort->>'group_preset','WEEK_CLIENT_CANDIDATE')) not in (
    'WEEK_CLIENT_CANDIDATE','CLIENT_WEEK_CANDIDATE','CANDIDATE_WEEK_CLIENT','STATUS_WEEK_CLIENT'
  ) then
    raise exception using errcode='22023', message='INVOICE_BATCH_GROUP_PRESET_INVALID';
  end if;

  if upper(coalesce(v_sort->>'sort_key','WEEK_ENDING_DATE')) not in (
    'WEEK_ENDING_DATE','CLIENT_NAME','CANDIDATE_NAME','TOTAL_EX_VAT','TOTAL_INC_VAT','STATUS','INVOICE_NUMBER'
  ) then
    raise exception using errcode='22023', message='INVOICE_BATCH_SORT_KEY_INVALID';
  end if;

  -- V8 Issue totals, selection summaries, status ordering and cursors always
  -- use the shared authoritative scalar classifier.
  -- PAGE, EXPAND_SELECTION and EXPLICIT_KEYS always obtain their bounded
  -- keyset first. The complete classifier remains the scalar authority for
  -- exact filtering, totals and group state, but it must never cause the
  -- rich presentation hydrator to receive an unrestricted invoice set.

  v_page_size := case
    when v_mode = 'EXPAND_SELECTION'
      then (v_query->>'page_size')::integer
    when v_mode = 'PAGE'
      then (v_query->>'page_size')::integer
    else 100
  end;
  v_after_key := nullif(v_query#>>'{cursor,after_selection_key}', '');

  v_input_snapshot := v_query->'snapshot';
  if v_input_snapshot is null
     or jsonb_typeof(v_input_snapshot) = 'null' then
    if v_mode <> 'PAGE' or v_after_key is not null then
      raise exception using errcode='22023', message='BATCH_SNAPSHOT_REQUIRED';
    end if;
    v_snapshot := private._invoice_candidate_snapshot_get_v2(
      'ISSUE',
      coalesce(p_now_utc,now())
    );
  else
    v_snapshot := private._invoice_candidate_snapshot_verify_v2(
      'ISSUE',
      v_input_snapshot,
      coalesce(p_now_utc,now())
    );
  end if;

  v_filter_hash := private._invoice_batch_hash_v2(jsonb_build_object(
    'action','ISSUE',
    'filters',v_filters,
    'sort',v_sort
  ));
  v_query_hash := private._invoice_batch_hash_v2(jsonb_build_object(
    'contract_version','INVOICE_BATCH_QUERY_V2',
    'action','ISSUE',
    'filters',v_filters,
    'sort',v_sort,
    'snapshot',jsonb_build_object(
      'contract_version',v_snapshot->>'contract_version',
      'action',v_snapshot->>'action',
      'at_utc',v_snapshot->>'at_utc',
      'revision',v_snapshot->>'revision',
      'expires_at_utc',v_snapshot->>'expires_at_utc',
      'key_id',v_snapshot->>'key_id'
    )
  ));
  v_selection_hash := private._invoice_batch_hash_v2(v_selection);

  with
  params as materialized (
    select
      v_mode mode,
      v_allow_early allow_early,
      v_display_mode display_mode,
      v_page_size page_size,
      v_after_key after_key,
      lower(nullif(btrim(coalesce(v_filters->>'search','')),'')) search_text,
      case when pg_input_is_valid(nullif(v_filters->>'week_ending_from',''),'date') then (v_filters->>'week_ending_from')::date end week_ending_from,
      case when pg_input_is_valid(nullif(v_filters->>'week_ending_to',''),'date') then (v_filters->>'week_ending_to')::date end week_ending_to,
      (coalesce(p_now_utc,now()) at time zone 'Europe/London')::date today,
      case when jsonb_typeof(v_filters->'client_ids')='array' then v_filters->'client_ids' else '[]'::jsonb end client_ids,
      case when jsonb_typeof(v_filters->'candidate_ids')='array' then v_filters->'candidate_ids' else '[]'::jsonb end candidate_ids,
      case when jsonb_typeof(v_filters->'week_endings')='array' then v_filters->'week_endings' else '[]'::jsonb end week_endings,
      case when jsonb_typeof(v_filters->'status_codes')='array' then v_filters->'status_codes' else '[]'::jsonb end status_codes,
      case when jsonb_typeof(v_filters->'blocker_codes')='array' then v_filters->'blocker_codes' else '[]'::jsonb end blocker_codes,
      case when jsonb_typeof(v_filters->'invoice_streams')='array' then v_filters->'invoice_streams' else '[]'::jsonb end invoice_streams,
      coalesce(nullif(upper(v_sort->>'group_preset'),''),'WEEK_CLIENT_CANDIDATE') group_preset,
      coalesce(nullif(upper(v_sort->>'sort_key'),''),'WEEK_ENDING_DATE') sort_key,
      case when upper(coalesce(v_sort->>'sort_direction','ASC'))='DESC' then 'DESC' else 'ASC' end sort_direction,
      case when pg_input_is_valid(
        nullif(coalesce(v_query#>>'{cursor,after_sort_date}',''),''),
        'date'
      )
        then (v_query#>>'{cursor,after_sort_date}')::date end after_sort_date,
      nullif(coalesce(v_query#>>'{cursor,after_sort_text}',''),'') after_sort_text,
      case when coalesce(v_query#>>'{cursor,after_sort_numeric}','') ~ '^[+-]?[0-9]+([.][0-9]+)?$'
        then (v_query#>>'{cursor,after_sort_numeric}')::numeric end after_sort_numeric,
      lower(nullif(btrim(coalesce(v_query#>>'{facet_request,search}','')),'')) facet_search,
      case when coalesce(v_query#>>'{facet_request,limit_per_kind}','') ~ '^[1-9][0-9]{0,2}$'
        then least((v_query#>>'{facet_request,limit_per_kind}')::integer,100)
        else 100 end facet_limit,
      case when jsonb_typeof(v_query#>'{facet_request,kinds}')='array'
        then v_query#>'{facet_request,kinds}'
        else '["CLIENTS","CANDIDATES","WEEK_ENDINGS","STATUSES","BLOCKERS"]'::jsonb end facet_kinds,
      lower(nullif(v_query#>>'{facet_request,cursors,clients,after_label}','')) facet_client_after_label,
      nullif(v_query#>>'{facet_request,cursors,clients,after_id}','') facet_client_after_id,
      lower(nullif(v_query#>>'{facet_request,cursors,candidates,after_label}','')) facet_candidate_after_label,
      nullif(v_query#>>'{facet_request,cursors,candidates,after_id}','') facet_candidate_after_id,
      case when pg_input_is_valid(
        coalesce(v_query#>>'{facet_request,cursors,week_endings,after_value}',''),
        'date'
      ) then (v_query#>>'{facet_request,cursors,week_endings,after_value}')::date end facet_week_after_value,
      nullif(v_query#>>'{facet_request,cursors,statuses,after_code}','') facet_status_after_code,
      nullif(v_query#>>'{facet_request,cursors,blockers,after_code}','') facet_blocker_after_code
  ),
  selection_rules as materialized (
    select * from private._invoice_batch_selection_rules_v2(v_selection)
  ),
  candidate_keys as materialized (
    select key_row.*
    from (
      select 1
      where v_mode in ('PAGE','EXPAND_SELECTION','EXPLICIT_KEYS')
    ) gate
    cross join lateral private._invoice_batch_issue_candidate_key_rows_v2(
      v_query,
      coalesce(p_now_utc,now())
    ) key_row
  ),
  issue_scope_request as materialized (
    select
      case
        when v_mode in ('FACETS','SUMMARY') then '{}'::uuid[]
        else coalesce(array_agg(k.invoice_id order by k.page_ordinal)
          filter (where k.page_ordinal<=v_page_size),'{}'::uuid[])
      end invoice_ids
    from candidate_keys k
  ),
  source_weeks as materialized (
    select
      '{}'::jsonb client_json,
      source.client_id::text client_id_text,
      source.client_name,
      source.invoice_week_start,
      source.week_ending_date,
      source.invoice_json
    from issue_scope_request request
    cross join lateral private._invoice_batch_issue_source_rows_for_ids_v2(
      request.invoice_ids,
      true,
      coalesce(p_now_utc,now())
    ) source
    where v_mode in ('PAGE','EXPAND_SELECTION','EXPLICIT_KEYS')
      and cardinality(request.invoice_ids)>0
  ),
  invoice_rows_raw as materialized (
    select
      'invoice:'||coalesce(inv.value->>'invoice_id','') selection_key,


      case when pg_input_is_valid(inv.value->>'invoice_id','uuid') then (inv.value->>'invoice_id')::uuid end invoice_id,
      inv.value->>'invoice_no' invoice_number,
      case when pg_input_is_valid(lw.client_id_text,'uuid') then lw.client_id_text::uuid end client_id,
      lw.client_name,
      case when pg_input_is_valid(inv.value->>'document_revision','int8') then (inv.value->>'document_revision')::bigint end document_revision,
      lw.week_ending_date,
      case when lw.week_ending_date is not null
        then lw.week_ending_date >= (coalesce(p_now_utc,now()) at time zone 'Europe/London')::date
        else false end is_early,
      coalesce(nullif(inv.value->>'currency',''),'GBP') currency,
      upper(coalesce(nullif(inv.value->>'invoice_stream',''),'NORMAL')) invoice_stream,
      case when coalesce(inv.value->>'subtotal_ex_vat','') ~ '^[+-]?[0-9]+([.][0-9]+)?$' then round((inv.value->>'subtotal_ex_vat')::numeric,2) else 0 end total_ex_vat,
      case when coalesce(inv.value->>'vat_amount','') ~ '^[+-]?[0-9]+([.][0-9]+)?$' then round((inv.value->>'vat_amount')::numeric,2) else 0 end vat_amount,
      case when coalesce(inv.value->>'total_inc_vat','') ~ '^[+-]?[0-9]+([.][0-9]+)?$' then round((inv.value->>'total_inc_vat')::numeric,2) else 0 end total_inc_vat,
      upper(coalesce(inv.value->>'preview_document_state','')) preview_document_state,
      upper(coalesce(inv.value->>'status','')) invoice_status,
      coalesce(inv.value->'stable_blocker_codes','[]'::jsonb) hard_blocker_codes,
      coalesce(inv.value->'document_dependency_codes','[]'::jsonb) document_dependency_codes,
      coalesce(inv.value->'delivery_blocker_codes','[]'::jsonb) delivery_blocker_codes,
      coalesce(inv.value->'recipient_routing_warnings','[]'::jsonb) warning_codes,
      coalesce(inv.value->>'can_issue_only','false') in ('true','t','1','yes','on') can_issue_only,
      coalesce(inv.value->>'can_issue_and_deliver','false') in ('true','t','1','yes','on') can_issue_and_deliver,
      inv.value->'validation_detail' validation_detail,
      inv.value->'support_readiness' support_readiness,
      inv.value->>'active_issue_operation_id' active_issue_operation_id_text,
      inv.value->'active_issue_operation' active_issue_operation,
      inv.value->>'active_document_operation_id' active_document_operation_id_text,
      inv.value->'last_issue_error' last_issue_error,
      inv.value->'last_document_error' last_document_error
    from source_weeks lw
    cross join lateral (select lw.invoice_json value) inv
  ),
  candidate_names as materialized (
    select r.invoice_id,
      coalesce(jsonb_agg(distinct to_jsonb(s.candidate_id)) filter(where s.candidate_id is not null),'[]'::jsonb) candidate_ids,
      coalesce(jsonb_agg(distinct to_jsonb(s.candidate_name)) filter(where nullif(s.candidate_name,'') is not null),'[]'::jsonb) candidate_names,
      coalesce(jsonb_agg(distinct to_jsonb(s.week_ending_date)) filter(where s.week_ending_date is not null),'[]'::jsonb) week_ending_dates
    from invoice_rows_raw r
    left join public.invoice_lines l on l.invoice_id=r.invoice_id
    left join public.v_timesheets_summary_base s on s.timesheet_id=l.timesheet_id
    group by r.invoice_id
  ),
  rows_with_state as materialized (
    select r.*,
      coalesce(cn.candidate_ids,'[]'::jsonb) candidate_ids,
      coalesce(cn.candidate_names,'[]'::jsonb) candidate_names,
      case when jsonb_array_length(coalesce(cn.candidate_names,'[]'::jsonb))=1
        then cn.candidate_names->>0
        when jsonb_array_length(coalesce(cn.candidate_names,'[]'::jsonb))>1
        then 'Multiple candidates ('||jsonb_array_length(cn.candidate_names)::text||')'
        else 'Unknown candidate' end candidate_display,
      case when jsonb_array_length(coalesce(cn.week_ending_dates,'[]'::jsonb))>0 then cn.week_ending_dates else jsonb_build_array(r.week_ending_date) end week_ending_dates,
      case
        when exists (
          select 1 from public.invoice_document_versions v
          where v.entity_type='INVOICE'
            and v.entity_id=r.invoice_id
            and v.purpose='DRAFT_PREVIEW'
            and v.source_revision=r.document_revision::text
            and v.template_version='invoice-professional-v2'
            and v.status='READY'
            and v.r2_key is not null
            and v.sha256 ~ '^[0-9a-f]{64}$'
            and coalesce(v.size_bytes,0)>0
            and coalesce(v.page_count,0)>0
        ) then 'FRESH'
        when exists (
          select 1 from public.invoice_document_versions prior_ready
          where prior_ready.entity_type='INVOICE'
            and prior_ready.entity_id=r.invoice_id
            and prior_ready.purpose='DRAFT_PREVIEW'
            and prior_ready.template_version='invoice-professional-v2'
            and prior_ready.status='READY'
            and prior_ready.r2_key is not null
            and prior_ready.sha256 ~ '^[0-9a-f]{64}$'
            and coalesce(prior_ready.size_bytes,0)>0
            and coalesce(prior_ready.page_count,0)>0
        ) then case
          when nullif(r.active_document_operation_id_text,'') is not null then 'ACTIVE'
          when r.preview_document_state in ('FAILED') or r.last_document_error is not null then 'FAILED'
          else 'STALE'
        end
        else 'NEVER_GENERATED'
      end generated_state,
      nullif(r.active_issue_operation_id_text,'') is not null is_active_issue,
      coalesce((jsonb_array_length(r.delivery_blocker_codes)>0 and r.can_issue_only and not r.can_issue_and_deliver),false) blocked_for_sending
    from invoice_rows_raw r
    left join candidate_names cn on cn.invoice_id=r.invoice_id
  ),
  candidate_rows as materialized (
    select r.*,
      coalesce(r.hard_blocker_codes,'[]'::jsonb) issue_blocker_codes,
      case when r.blocked_for_sending then jsonb_build_array('BLOCKED_FOR_SENDING') else '[]'::jsonb end
        || coalesce(r.document_dependency_codes,'[]'::jsonb)
        || coalesce(r.warning_codes,'[]'::jsonb) informational_codes,
      (r.can_issue_only
        and jsonb_array_length(coalesce(r.hard_blocker_codes,'[]'::jsonb))=0
        and not r.is_active_issue) selectable,
      case when r.is_active_issue then 'IN_PROGRESS'
           when not r.can_issue_only or jsonb_array_length(coalesce(r.hard_blocker_codes,'[]'::jsonb))>0
             then 'BLOCKED'
           else 'READY' end row_status
    from rows_with_state r
    where r.invoice_status in ('DRAFT','ON_HOLD')
      and nullif(r.invoice_number,'') is not null
  ),
  classification_source as materialized (
    -- PAGE-family requests reuse the exact candidate payload that the keyset
    -- helper already classified. FACETS/SUMMARY do not invoke the keyset
    -- helper, so they retain one direct full-scope classification pass.
    select key_row.selection_key,key_row.candidate_json
    from candidate_keys key_row
    where key_row.page_ordinal<=v_page_size
    union all
    select candidate.selection_key,candidate.candidate_json
    from (
      select 1
      where v_mode in ('FACETS','SUMMARY')
    ) gate
    cross join lateral private._invoice_batch_issue_classification_v2(
      true,
      null,
      coalesce(p_now_utc,statement_timestamp())
    ) candidate
  ),
  authoritative_rows as materialized (
    select
      candidate.candidate_json->>'selection_key' selection_key,
      (candidate.candidate_json->>'invoice_id')::uuid invoice_id,
      candidate.candidate_json->>'invoice_number' invoice_number,
      (candidate.candidate_json->>'client_id')::uuid client_id,
      candidate.candidate_json->>'client_name' client_name,
      (candidate.candidate_json->>'document_revision')::bigint
        document_revision,
      case
        when pg_input_is_valid(
          coalesce(candidate.candidate_json->>'week_ending_date',''),
          'date'
        )
          then (candidate.candidate_json->>'week_ending_date')::date
      end week_ending_date,
      coalesce(
        (candidate.candidate_json->>'is_early')::boolean,
        false
      ) is_early,
      coalesce(
        nullif(candidate.candidate_json->>'currency',''),
        'GBP'
      ) currency,
      upper(coalesce(
        nullif(candidate.candidate_json->>'invoice_stream',''),
        'NORMAL'
      )) invoice_stream,
      coalesce(
        (candidate.candidate_json->>'total_ex_vat')::numeric,
        0
      ) total_ex_vat,
      coalesce(
        (candidate.candidate_json->>'vat_amount')::numeric,
        0
      ) vat_amount,
      coalesce(
        (candidate.candidate_json->>'total_inc_vat')::numeric,
        0
      ) total_inc_vat,
      candidate.candidate_json->>'preview_document_state'
        preview_document_state,
      candidate.candidate_json->>'invoice_status' invoice_status,
      coalesce(
        candidate.candidate_json->'hard_blocker_codes',
        '[]'::jsonb
      ) hard_blocker_codes,
      coalesce(
        candidate.candidate_json->'document_dependency_codes',
        '[]'::jsonb
      ) document_dependency_codes,
      coalesce(
        candidate.candidate_json->'delivery_blocker_codes',
        '[]'::jsonb
      ) delivery_blocker_codes,
      coalesce(
        candidate.candidate_json->'warning_codes',
        '[]'::jsonb
      ) warning_codes,
      coalesce(
        (candidate.candidate_json->>'can_issue_only')::boolean,
        false
      ) can_issue_only,
      coalesce(
        (candidate.candidate_json->>'can_issue_and_deliver')::boolean,
        false
      ) can_issue_and_deliver,
      candidate.candidate_json->'validation_detail'
        validation_detail,
      candidate.candidate_json->'support_readiness'
        support_readiness,
      candidate.candidate_json->>'active_issue_operation_id'
        active_issue_operation_id_text,
      candidate.candidate_json->'active_issue_operation'
        active_issue_operation,
      candidate.candidate_json->>'active_document_operation_id'
        active_document_operation_id_text,
      candidate.candidate_json->'last_issue_error'
        last_issue_error,
      candidate.candidate_json->'last_document_error'
        last_document_error,
      coalesce(
        candidate.candidate_json->'candidate_ids',
        '[]'::jsonb
      ) candidate_ids,
      coalesce(
        candidate.candidate_json->'candidate_names',
        '[]'::jsonb
      ) candidate_names,
      candidate.candidate_json->>'candidate_display'
        candidate_display,
      coalesce(
        candidate.candidate_json->'week_ending_dates',
        '[]'::jsonb
      ) week_ending_dates,
      candidate.candidate_json->>'generated_state'
        generated_state,
      coalesce(
        (candidate.candidate_json->>'blocked_for_sending')::boolean,
        false
      ) blocked_for_sending,
      coalesce(
        candidate.candidate_json->'issue_blocker_codes',
        '[]'::jsonb
      ) issue_blocker_codes,
      coalesce(
        candidate.candidate_json->'informational_codes',
        '[]'::jsonb
      ) informational_codes,
      coalesce(
        (candidate.candidate_json->>'selectable')::boolean,
        false
      ) selectable,
      candidate.candidate_json->>'row_status' row_status
    from classification_source candidate
  ),
  filter_match_rows as materialized (
    select
      r.*,
      (
        jsonb_array_length(p.client_ids)=0
        or r.client_id::text in (
          select value from jsonb_array_elements_text(p.client_ids)
        )
      ) client_filter_match,
      (
        jsonb_array_length(p.candidate_ids)=0
        or exists (
          select 1
          from jsonb_array_elements_text(r.candidate_ids) row_candidate(id)
          where row_candidate.id in (
            select value from jsonb_array_elements_text(p.candidate_ids)
          )
        )
      ) candidate_filter_match,
      (
        jsonb_array_length(p.week_endings)=0
        or r.week_ending_date::text in (
          select value from jsonb_array_elements_text(p.week_endings)
        )
      ) week_filter_match,
      (
        jsonb_array_length(p.status_codes)=0
        or r.row_status in (
          select upper(value)
          from jsonb_array_elements_text(p.status_codes)
        )
      ) status_filter_match,
      (
        jsonb_array_length(p.blocker_codes)=0
        or exists (
          select 1
          from jsonb_array_elements_text(
            coalesce(r.issue_blocker_codes,'[]'::jsonb)
            || coalesce(r.delivery_blocker_codes,'[]'::jsonb)
            || coalesce(r.informational_codes,'[]'::jsonb)
          ) badge(code)
          where badge.code in (
            select upper(value)
            from jsonb_array_elements_text(p.blocker_codes)
          )
        )
      ) blocker_filter_match
    from authoritative_rows r
    cross join params p
    where (p.allow_early or not coalesce(r.is_early,false))
      and (
        jsonb_array_length(p.invoice_streams)=0
        or r.invoice_stream in (
          select upper(value)
          from jsonb_array_elements_text(p.invoice_streams)
        )
      )
      and (
        v_mode <> 'EXPLICIT_KEYS'
        or r.selection_key in (
          select value
          from jsonb_array_elements_text(v_selection_keys)
        )
      )
      and (p.search_text is null


        or lower(coalesce(r.invoice_number,'')||' '||coalesce(r.client_name,'')||' '||coalesce(r.candidate_display,'')||' '||coalesce(r.invoice_id::text,'')) like '%'||p.search_text||'%')
      and (p.week_ending_from is null or r.week_ending_date >= p.week_ending_from)
      and (p.week_ending_to is null or r.week_ending_date <= p.week_ending_to)
  ),
  scope_rows as materialized (
    select r.*
    from filter_match_rows r
    where r.client_filter_match
      and r.candidate_filter_match
      and r.week_filter_match
      and r.status_filter_match
      and r.blocker_filter_match
  ),
  facet_client_rows as materialized (
    select r.* from filter_match_rows r
    where r.candidate_filter_match and r.week_filter_match
      and r.status_filter_match and r.blocker_filter_match
  ),
  facet_candidate_rows as materialized (
    select r.* from filter_match_rows r
    where r.client_filter_match and r.week_filter_match
      and r.status_filter_match and r.blocker_filter_match
  ),
  facet_week_rows as materialized (
    select r.* from filter_match_rows r
    where r.client_filter_match and r.candidate_filter_match
      and r.status_filter_match and r.blocker_filter_match
  ),
  facet_status_rows as materialized (
    select r.* from filter_match_rows r
    where r.client_filter_match and r.candidate_filter_match
      and r.week_filter_match and r.blocker_filter_match
  ),
  facet_blocker_rows as materialized (
    select r.* from filter_match_rows r
    where r.client_filter_match and r.candidate_filter_match
      and r.week_filter_match and r.status_filter_match
  ),
  facet_client_values_base as materialized (
    select
      client_id,
      min(coalesce(nullif(client_name,''),client_id::text)) label,
      count(*)::integer row_count
    from facet_client_rows
    where client_id is not null
    group by client_id
  ),
  facet_client_values as materialized (
    select b.*,
      row_number() over(order by lower(b.label),b.client_id) facet_ordinal,
      count(*) over() facet_total
    from facet_client_values_base b
    cross join params p
    where (p.facet_search is null
        or lower(b.label) like '%'||p.facet_search||'%'
        or b.client_id::text like p.facet_search||'%')
      and (p.facet_client_after_label is null
        or (lower(b.label),b.client_id::text)>
           (p.facet_client_after_label,coalesce(p.facet_client_after_id,'')))
  ),
  facet_candidate_values_base as materialized (
    select
      candidate.value candidate_id,
      min(coalesce(
        nullif(r.candidate_names->>(candidate.ordinality::integer-1),''),
        candidate.value
      )) label,
      count(distinct r.selection_key)::integer row_count
    from facet_candidate_rows r
    cross join lateral jsonb_array_elements_text(
      coalesce(r.candidate_ids,'[]'::jsonb)
    ) with ordinality candidate(value,ordinality)
    group by candidate.value
  ),
  facet_candidate_values as materialized (
    select b.*,
      row_number() over(order by lower(b.label),b.candidate_id) facet_ordinal,
      count(*) over() facet_total
    from facet_candidate_values_base b
    cross join params p
    where (p.facet_search is null
        or lower(b.label) like '%'||p.facet_search||'%'
        or b.candidate_id like p.facet_search||'%')
      and (p.facet_candidate_after_label is null
        or (lower(b.label),b.candidate_id)>
           (p.facet_candidate_after_label,coalesce(p.facet_candidate_after_id,'')))
  ),
  facet_week_values as materialized (
    select b.*,
      row_number() over(order by b.week_ending_date desc) facet_ordinal,
      count(*) over() facet_total
    from (
      select week_ending_date,count(*)::integer row_count
      from facet_week_rows
      where week_ending_date is not null
      group by week_ending_date
    ) b
    cross join params p
    where (p.facet_search is null
        or to_char(b.week_ending_date,'DD/MM/YYYY') like '%'||p.facet_search||'%'
        or b.week_ending_date::text like '%'||p.facet_search||'%')
      and (p.facet_week_after_value is null
        or b.week_ending_date<p.facet_week_after_value)
  ),
  facet_status_values as materialized (
    select b.*,
      row_number() over(order by b.row_status) facet_ordinal,
      count(*) over() facet_total
    from (
      select row_status,count(*)::integer row_count
      from facet_status_rows
      group by row_status
    ) b
    cross join params p
    where (p.facet_search is null
        or lower(b.row_status) like '%'||p.facet_search||'%'
        or lower(replace(b.row_status,'_',' ')) like '%'||p.facet_search||'%')
      and (p.facet_status_after_code is null
        or b.row_status>p.facet_status_after_code)
  ),
  facet_blocker_values as materialized (
    select b.*,
      row_number() over(order by b.code) facet_ordinal,
      count(*) over() facet_total
    from (
      select badge.code,count(distinct r.selection_key)::integer row_count
      from facet_blocker_rows r
      cross join lateral jsonb_array_elements_text(
        coalesce(r.issue_blocker_codes,'[]'::jsonb)
        || coalesce(r.delivery_blocker_codes,'[]'::jsonb)
        || coalesce(r.informational_codes,'[]'::jsonb)
      ) badge(code)
      group by badge.code
    ) b
    cross join params p
    where (p.facet_search is null
        or lower(b.code) like '%'||p.facet_search||'%'
        or lower(replace(b.code,'_',' ')) like '%'||p.facet_search||'%')
      and (p.facet_blocker_after_code is null
        or b.code>p.facet_blocker_after_code)
  ),
  grouped_scope_rows as materialized (
    select
      r.*,
      private._invoice_batch_hash_v2(jsonb_build_object(
        'action','ISSUE',
        'group_preset',p.group_preset,
        'status_code',case when p.group_preset='STATUS_WEEK_CLIENT' then r.row_status end,
        'week_ending_date',r.week_ending_date,
        'client_id',r.client_id,
        'candidate_ids',case
          when p.group_preset='STATUS_WEEK_CLIENT' then '[]'::jsonb
          else coalesce(r.candidate_ids,'[]'::jsonb)
        end
      )) group_key
    from scope_rows r
    cross join params p
  ),
  selection_scope_rows as materialized (
    select
      fr.*,
      coalesce((
        select sr.action
        from selection_rules sr
        where (sr.selector_type='ROW' and sr.selection_key=fr.selection_key)
           or (sr.selector_type='WEEK' and sr.week_ending_date=fr.week_ending_date)
           or (sr.selector_type='CLIENT' and sr.client_id=fr.client_id)
           or (sr.selector_type='CANDIDATE' and exists (
             select 1 from jsonb_array_elements_text(fr.candidate_ids) cid(value)
             where pg_input_is_valid(cid.value,'uuid') and cid.value::uuid=sr.candidate_id
           ))
           or (sr.selector_type='STATUS' and sr.status_code=fr.row_status)
           or (sr.selector_type='WEEK_CLIENT' and sr.week_ending_date=fr.week_ending_date and sr.client_id=fr.client_id)
           or (sr.selector_type='WEEK_CLIENT_CANDIDATE' and sr.week_ending_date=fr.week_ending_date and sr.client_id=fr.client_id and exists (
             select 1 from jsonb_array_elements_text(fr.candidate_ids) cid(value)
             where pg_input_is_valid(cid.value,'uuid') and cid.value::uuid=sr.candidate_id
           ))
           or (sr.selector_type='STATUS_WEEK' and sr.status_code=fr.row_status and sr.week_ending_date=fr.week_ending_date)
           or (sr.selector_type='STATUS_WEEK_CLIENT' and sr.status_code=fr.row_status and sr.week_ending_date=fr.week_ending_date and sr.client_id=fr.client_id)
           or (sr.selector_type='DIMENSION_GROUP'
             and (sr.week_ending_date is null or sr.week_ending_date=fr.week_ending_date)
             and (sr.client_id is null or sr.client_id=fr.client_id)
             and (sr.status_code is null or sr.status_code=fr.row_status)
             and (sr.candidate_id is null or exists (
               select 1 from jsonb_array_elements_text(fr.candidate_ids) cid(value)
               where pg_input_is_valid(cid.value,'uuid') and cid.value::uuid=sr.candidate_id
             )))
        order by sr.rule_sequence desc
        limit 1
      ),'INCLUDE') last_selection_action
    from grouped_scope_rows fr
  ),
  filtered_rows as materialized (
    select r.*
    from selection_scope_rows r
    cross join params p
    where (
      v_mode='EXPAND_SELECTION'
      or p.display_mode='ALL'
      or (p.display_mode='READY' and r.selectable)
      or (
        p.display_mode='BLOCKED'
        and (
          r.row_status in ('BLOCKED','STALE','FAILED')
          or r.blocked_for_sending
        )
      )
    )
      and (
        v_mode<>'EXPAND_SELECTION'
        or (
          r.selectable
          and r.last_selection_action<>'EXCLUDE'
        )
      )
  ),
  sortable_rows as materialized (
    select fr.*,
      case when p.sort_key='WEEK_ENDING_DATE' then coalesce(fr.week_ending_date, case when p.sort_direction='DESC' then date '0001-01-01' else date '9999-12-31' end) end sort_date_key,
      case when p.sort_key='CLIENT_NAME' then coalesce(lower(fr.client_name), case when p.sort_direction='DESC' then '' else repeat('~',100) end)
           when p.sort_key='CANDIDATE_NAME' then coalesce(lower(fr.candidate_display), case when p.sort_direction='DESC' then '' else repeat('~',100) end)
           when p.sort_key='STATUS' then
             lpad((case
               when fr.row_status='READY' and not fr.blocked_for_sending then 10
               when fr.row_status='READY' and fr.blocked_for_sending then 20
               when fr.row_status='STALE' then 30
               when fr.row_status='IN_PROGRESS' then 40
               when fr.row_status='FAILED' then 50
               else 60
             end)::text,3,'0')||'|'||lower(coalesce(fr.row_status,'BLOCKED'))
           when p.sort_key='INVOICE_NUMBER' then coalesce(lower(fr.invoice_number), case when p.sort_direction='DESC' then '' else repeat('~',100) end) end sort_text_key,
      case when p.sort_key='TOTAL_EX_VAT' then coalesce(fr.total_ex_vat, case when p.sort_direction='DESC' then -999999999999999999::numeric else 999999999999999999::numeric end)
           when p.sort_key='TOTAL_INC_VAT' then coalesce(fr.total_inc_vat, case when p.sort_direction='DESC' then -999999999999999999::numeric else 999999999999999999::numeric end) end sort_numeric_key
    from filtered_rows fr cross join params p
  ),
  cursor_filtered_rows as materialized (
    select sr.*
    from sortable_rows sr
    cross join params p
    where p.after_key is null
       or (
         p.sort_key='WEEK_ENDING_DATE'
         and p.after_sort_date is not null
         and ((p.sort_direction='ASC' and (sr.sort_date_key > p.after_sort_date or (sr.sort_date_key=p.after_sort_date and sr.selection_key>p.after_key)))
           or (p.sort_direction='DESC' and (sr.sort_date_key < p.after_sort_date or (sr.sort_date_key=p.after_sort_date and sr.selection_key>p.after_key))))
       )
       or (
         p.sort_key in ('CLIENT_NAME','CANDIDATE_NAME','STATUS','INVOICE_NUMBER')
         and p.after_sort_text is not null
         and ((p.sort_direction='ASC' and (sr.sort_text_key > p.after_sort_text or (sr.sort_text_key=p.after_sort_text and sr.selection_key>p.after_key)))
           or (p.sort_direction='DESC' and (sr.sort_text_key < p.after_sort_text or (sr.sort_text_key=p.after_sort_text and sr.selection_key>p.after_key))))
       )
       or (
         p.sort_key in ('TOTAL_EX_VAT','TOTAL_INC_VAT')
         and p.after_sort_numeric is not null
         and ((p.sort_direction='ASC' and (sr.sort_numeric_key > p.after_sort_numeric or (sr.sort_numeric_key=p.after_sort_numeric and sr.selection_key>p.after_key)))
           or (p.sort_direction='DESC' and (sr.sort_numeric_key < p.after_sort_numeric or (sr.sort_numeric_key=p.after_sort_numeric and sr.selection_key>p.after_key))))
       )
       or (
         ((p.sort_key='WEEK_ENDING_DATE' and p.after_sort_date is null)
           or (p.sort_key in ('CLIENT_NAME','CANDIDATE_NAME','STATUS','INVOICE_NUMBER') and p.after_sort_text is null)
           or (p.sort_key in ('TOTAL_EX_VAT','TOTAL_INC_VAT') and p.after_sort_numeric is null))
         and sr.selection_key > p.after_key
       )
  ),
  selected_rows as materialized (
    select * from cursor_filtered_rows
  ),
  candidate_page_source as materialized (
    select * from selected_rows where v_mode='EXPAND_SELECTION'
    union all
    select * from selected_rows where v_mode in('PAGE','EXPLICIT_KEYS')
  ),
  ordered_page_rows as materialized (
    select src.*,
      row_number() over (order by
        case when v_mode='EXPAND_SELECTION' then src.selection_key end asc,
        case when p.sort_key='WEEK_ENDING_DATE' and p.sort_direction='ASC' then src.sort_date_key end asc nulls last,
        case when p.sort_key='WEEK_ENDING_DATE' and p.sort_direction='DESC' then src.sort_date_key end desc nulls last,
        case when p.sort_key in ('CLIENT_NAME','CANDIDATE_NAME','STATUS','INVOICE_NUMBER') and p.sort_direction='ASC' then src.sort_text_key end asc nulls last,
        case when p.sort_key in ('CLIENT_NAME','CANDIDATE_NAME','STATUS','INVOICE_NUMBER') and p.sort_direction='DESC' then src.sort_text_key end desc nulls last,
        case when p.sort_key in ('TOTAL_EX_VAT','TOTAL_INC_VAT') and p.sort_direction='ASC' then src.sort_numeric_key end asc nulls last,
        case when p.sort_key in ('TOTAL_EX_VAT','TOTAL_INC_VAT') and p.sort_direction='DESC' then src.sort_numeric_key end desc nulls last,
        src.selection_key asc
      ) page_ordinal
    from candidate_page_source src cross join params p
  ),
  page_rows as materialized (
    select * from ordered_page_rows
    where page_ordinal <= (select page_size + 1 from params)
  ),
  visible_rows as materialized (
    select * from page_rows
    where page_ordinal <= (select page_size from params)
  ),
  visible_invoice_request as materialized (
    select array_agg(invoice_id order by invoice_id) invoice_ids
    from visible_rows
    where invoice_id is not null
  ),
  nonempty_visible_invoice_request as materialized (
    select invoice_ids
    from visible_invoice_request
    where cardinality(invoice_ids)>0
  ),
  visible_support as materialized (
    select
      (source.invoice_json->>'invoice_id')::uuid support_invoice_id,
      source.invoice_json
    from nonempty_visible_invoice_request request
    cross join lateral private._invoice_batch_issue_source_rows_for_ids_v2(
      request.invoice_ids,
      true,
      coalesce(p_now_utc,statement_timestamp())
    ) source
  ),
  totals as materialized (
    select
      count(*)::integer all_count,
      count(*) filter(where selectable)::integer ready_count,
      count(*) filter(where selectable and last_selection_action <> 'EXCLUDE')::integer selected_count,
      count(*) filter(where not selectable)::integer blocked_count,
      count(*) filter(where blocked_for_sending)::integer blocked_for_sending_count,
      count(*) filter(where generated_state='STALE')::integer stale_count,
      count(*) filter(where row_status='IN_PROGRESS')::integer in_progress_count
    from selection_scope_rows
  ),
  display_totals as materialized (
    select count(*)::integer display_count
    from filtered_rows
  ),
  visible_group_keys as materialized (
    select distinct group_key
    from visible_rows
    where v_mode = 'PAGE'
  ),
  page_group_rollup as materialized (
    select
      r.group_key,
      min(r.week_ending_date) week_ending_date,
      (array_agg(r.client_id order by r.selection_key))[1] client_id,
      min(r.row_status) row_status,
      (array_agg(r.candidate_ids order by r.selection_key))[1] candidate_ids,
      count(*)::integer row_total,
      count(*) filter (where r.selectable)::integer eligible_total,
      count(*) filter (
        where r.selectable and r.last_selection_action <> 'EXCLUDE'
      )::integer selected_total,
      count(*) filter (where v.group_key is not null)::integer visible_total
    from selection_scope_rows r
    join visible_group_keys g on g.group_key = r.group_key
    left join visible_rows v
      on v.group_key = r.group_key
     and v.selection_key = r.selection_key
    group by r.group_key
  ),
  page_group_selection_json as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'group_key',g.group_key,
      'selector',case
        when p.group_preset='STATUS_WEEK_CLIENT' then jsonb_build_object(
          'type','STATUS_WEEK_CLIENT',
          'status_code',g.row_status,
          'week_ending_date',g.week_ending_date,
          'client_id',g.client_id
        )
        when jsonb_array_length(coalesce(g.candidate_ids,'[]'::jsonb))=1
          then jsonb_build_object(
            'type','WEEK_CLIENT_CANDIDATE',
            'week_ending_date',g.week_ending_date,
            'client_id',g.client_id,
            'candidate_id',g.candidate_ids->>0
          )
        else jsonb_build_object(
          'type','WEEK_CLIENT',
          'week_ending_date',g.week_ending_date,
          'client_id',g.client_id
        )
      end,
      'eligible_total',g.eligible_total,
      'selected_total',g.selected_total,
      'state',case
        when g.eligible_total = 0 then 'DISABLED'
        when g.selected_total = 0 then 'UNCHECKED'
        when g.selected_total = g.eligible_total then 'CHECKED'
        else 'INDETERMINATE'
      end,
      'has_hidden_override',
        g.visible_total < g.row_total
        and g.selected_total not in (0,g.eligible_total)
    ) order by g.group_key),'[]'::jsonb) groups
    from page_group_rollup g
    cross join params p
  ),
  requested_group_selectors as materialized (
    select
      selector.ordinality::integer request_ordinal,
      selector.value selector,
      upper(selector.value->>'type') selector_type,
      nullif(btrim(selector.value->>'selection_key'),'') selection_key,
      case when selector.value ? 'week_ending_date'
        then (selector.value->>'week_ending_date')::date end week_ending_date,
      case when selector.value ? 'client_id'
        then (selector.value->>'client_id')::uuid end client_id,
      case when selector.value ? 'candidate_id'
        then (selector.value->>'candidate_id')::uuid end candidate_id,
      nullif(upper(btrim(selector.value->>'status_code')),'') status_code
    from jsonb_array_elements(coalesce(v_query->'group_selectors','[]'::jsonb))
      with ordinality selector(value, ordinality)
    where v_mode = 'SUMMARY'
  ),
  requested_group_members as materialized (
    select
      requested.request_ordinal,
      requested.selector,
      row_scope.*
    from requested_group_selectors requested
    join selection_scope_rows row_scope on row_scope.selectable
      and (
        (requested.selector_type='ROW'
          and requested.selection_key=row_scope.selection_key)
        or (requested.selector_type='WEEK'
          and requested.week_ending_date=row_scope.week_ending_date)
        or (requested.selector_type='CLIENT'
          and requested.client_id=row_scope.client_id)
        or (requested.selector_type='CANDIDATE' and exists (
          select 1
          from jsonb_array_elements_text(
            coalesce(row_scope.candidate_ids,'[]'::jsonb)
          ) candidate(value)
          where pg_input_is_valid(candidate.value,'uuid')
            and candidate.value::uuid=requested.candidate_id
        ))
        or (requested.selector_type='STATUS'
          and requested.status_code=row_scope.row_status)
        or (requested.selector_type='WEEK_CLIENT'
          and requested.week_ending_date=row_scope.week_ending_date
          and requested.client_id=row_scope.client_id)
        or (requested.selector_type='WEEK_CLIENT_CANDIDATE'
          and requested.week_ending_date=row_scope.week_ending_date
          and requested.client_id=row_scope.client_id
          and exists (
            select 1
            from jsonb_array_elements_text(
              coalesce(row_scope.candidate_ids,'[]'::jsonb)
            ) candidate(value)
            where pg_input_is_valid(candidate.value,'uuid')
              and candidate.value::uuid=requested.candidate_id
          ))
        or (requested.selector_type='STATUS_WEEK'
          and requested.status_code=row_scope.row_status
          and requested.week_ending_date=row_scope.week_ending_date)
        or (requested.selector_type='STATUS_WEEK_CLIENT'
          and requested.status_code=row_scope.row_status
          and requested.week_ending_date=row_scope.week_ending_date
          and requested.client_id=row_scope.client_id)
        or (requested.selector_type='DIMENSION_GROUP'
          and (requested.week_ending_date is null or requested.week_ending_date=row_scope.week_ending_date)
          and (requested.client_id is null or requested.client_id=row_scope.client_id)
          and (requested.status_code is null or requested.status_code=row_scope.row_status)
          and (requested.candidate_id is null or exists (
            select 1 from jsonb_array_elements_text(row_scope.candidate_ids) candidate(value)
            where pg_input_is_valid(candidate.value,'uuid')
              and candidate.value::uuid=requested.candidate_id
          )))
      )
  ),
  requested_group_base as materialized (
    select
      requested.*,
      coalesce((
        select rule.action
        from selection_rules rule
        where exists (
          select 1
          from requested_group_members member
          where member.request_ordinal=requested.request_ordinal
        )
          and not exists (
            select 1
            from requested_group_members member
            where member.request_ordinal=requested.request_ordinal
              and (
                (rule.selector_type='ROW'
                  and rule.selection_key=member.selection_key)
                or (rule.selector_type='WEEK'
                  and rule.week_ending_date=member.week_ending_date)
                or (rule.selector_type='CLIENT'
                  and rule.client_id=member.client_id)
                or (rule.selector_type='CANDIDATE' and exists (
                  select 1
                  from jsonb_array_elements_text(
                    coalesce(member.candidate_ids,'[]'::jsonb)
                  ) candidate(value)
                  where pg_input_is_valid(candidate.value,'uuid')
                    and candidate.value::uuid=rule.candidate_id
                ))
                or (rule.selector_type='STATUS'
                  and rule.status_code=member.row_status)
                or (rule.selector_type='WEEK_CLIENT'
                  and rule.week_ending_date=member.week_ending_date
                  and rule.client_id=member.client_id)
                or (rule.selector_type='WEEK_CLIENT_CANDIDATE'
                  and rule.week_ending_date=member.week_ending_date
                  and rule.client_id=member.client_id
                  and exists (
                    select 1
                    from jsonb_array_elements_text(
                      coalesce(member.candidate_ids,'[]'::jsonb)
                    ) candidate(value)
                    where pg_input_is_valid(candidate.value,'uuid')
                      and candidate.value::uuid=rule.candidate_id
                  ))
                or (rule.selector_type='STATUS_WEEK'
                  and rule.status_code=member.row_status
                  and rule.week_ending_date=member.week_ending_date)
                or (rule.selector_type='STATUS_WEEK_CLIENT'
                  and rule.status_code=member.row_status
                  and rule.week_ending_date=member.week_ending_date
                  and rule.client_id=member.client_id)
                or (rule.selector_type='DIMENSION_GROUP'
                  and (rule.week_ending_date is null or rule.week_ending_date=member.week_ending_date)
                  and (rule.client_id is null or rule.client_id=member.client_id)
                  and (rule.status_code is null or rule.status_code=member.row_status)
                  and (rule.candidate_id is null or exists (
                    select 1 from jsonb_array_elements_text(member.candidate_ids) candidate(value)
                    where pg_input_is_valid(candidate.value,'uuid')
                      and candidate.value::uuid=rule.candidate_id
                  )))
              ) is not true
          )
        order by rule.rule_sequence desc
        limit 1
      ),'INCLUDE') base_action
    from requested_group_selectors requested
  ),
  requested_group_rollup as materialized (
    select
      requested.request_ordinal,
      requested.selector,
      case when count(distinct member.group_key)=1
        then min(member.group_key) end group_key,
      count(member.selection_key)::integer eligible_total,
      count(member.selection_key) filter (
        where member.last_selection_action <> 'EXCLUDE'
      )::integer selected_total,
      coalesce(bool_or(
        member.last_selection_action is distinct from requested.base_action
      ) filter (where member.selection_key is not null),false)
        has_hidden_override
    from requested_group_base requested
    left join requested_group_members member
      on member.request_ordinal=requested.request_ordinal
    group by
      requested.request_ordinal,
      requested.selector,
      requested.base_action
  ),
  summary_group_selection_json as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'selector',rollup.selector,
      'group_key',rollup.group_key,
      'eligible_total',rollup.eligible_total,
      'selected_total',rollup.selected_total,
      'state',case
        when rollup.eligible_total=0 then 'DISABLED'
        when rollup.selected_total=0 then 'UNCHECKED'
        when rollup.selected_total=rollup.eligible_total
          and not rollup.has_hidden_override then 'CHECKED'
        else 'INDETERMINATE'
      end,
      'has_hidden_override',rollup.has_hidden_override
    ) order by rollup.request_ordinal),'[]'::jsonb) groups
    from requested_group_rollup rollup
  ),
  group_selection_json as materialized (
    select case
      when v_mode='SUMMARY' then summary_groups.groups
      else page_groups.groups
    end groups
    from page_group_selection_json page_groups
    cross join summary_group_selection_json summary_groups
  ),
  facet_json as materialized (
    select jsonb_strip_nulls(jsonb_build_object(
      'clients',case when p.facet_kinds ? 'CLIENTS' then jsonb_build_object(
        'items',coalesce((select jsonb_agg(jsonb_build_object(
          'id',f.client_id,'label',f.label,'count',f.row_count
        ) order by f.facet_ordinal) from facet_client_values f
          where f.facet_ordinal<=p.facet_limit),'[]'::jsonb),
        'has_more',coalesce((select max(f.facet_total)>p.facet_limit
          from facet_client_values f),false),
        'next_cursor_values',case when coalesce((select max(f.facet_total)>p.facet_limit
          from facet_client_values f),false) then (
          select jsonb_build_object('after_label',lower(f.label),'after_id',f.client_id)
          from facet_client_values f where f.facet_ordinal=p.facet_limit
        ) end
      ) end,
      'candidates',case when p.facet_kinds ? 'CANDIDATES' then jsonb_build_object(
        'items',coalesce((select jsonb_agg(jsonb_build_object(
          'id',f.candidate_id,'label',f.label,'count',f.row_count
        ) order by f.facet_ordinal) from facet_candidate_values f
          where f.facet_ordinal<=p.facet_limit),'[]'::jsonb),
        'has_more',coalesce((select max(f.facet_total)>p.facet_limit
          from facet_candidate_values f),false),
        'next_cursor_values',case when coalesce((select max(f.facet_total)>p.facet_limit
          from facet_candidate_values f),false) then (
          select jsonb_build_object('after_label',lower(f.label),'after_id',f.candidate_id)
          from facet_candidate_values f where f.facet_ordinal=p.facet_limit
        ) end
      ) end,
      'week_endings',case when p.facet_kinds ? 'WEEK_ENDINGS' then jsonb_build_object(
        'items',coalesce((select jsonb_agg(jsonb_build_object(
          'value',f.week_ending_date,'label',to_char(f.week_ending_date,'DD/MM/YYYY'),
          'count',f.row_count
        ) order by f.facet_ordinal) from facet_week_values f
          where f.facet_ordinal<=p.facet_limit),'[]'::jsonb),
        'has_more',coalesce((select max(f.facet_total)>p.facet_limit
          from facet_week_values f),false),
        'next_cursor_values',case when coalesce((select max(f.facet_total)>p.facet_limit
          from facet_week_values f),false) then (
          select jsonb_build_object('after_value',f.week_ending_date)
          from facet_week_values f where f.facet_ordinal=p.facet_limit
        ) end
      ) end,
      'statuses',case when p.facet_kinds ? 'STATUSES' then jsonb_build_object(
        'items',coalesce((select jsonb_agg(jsonb_build_object(
          'code',f.row_status,'label',initcap(replace(lower(f.row_status),'_',' ')),
          'count',f.row_count
        ) order by f.facet_ordinal) from facet_status_values f
          where f.facet_ordinal<=p.facet_limit),'[]'::jsonb),
        'has_more',coalesce((select max(f.facet_total)>p.facet_limit
          from facet_status_values f),false),
        'next_cursor_values',case when coalesce((select max(f.facet_total)>p.facet_limit
          from facet_status_values f),false) then (
          select jsonb_build_object('after_code',f.row_status)
          from facet_status_values f where f.facet_ordinal=p.facet_limit
        ) end
      ) end,
      'blockers',case when p.facet_kinds ? 'BLOCKERS' then jsonb_build_object(
        'items',coalesce((select jsonb_agg(jsonb_build_object(
          'code',f.code,'count',f.row_count
        ) order by f.facet_ordinal) from facet_blocker_values f
          where f.facet_ordinal<=p.facet_limit),'[]'::jsonb),
        'has_more',coalesce((select max(f.facet_total)>p.facet_limit
          from facet_blocker_values f),false),
        'next_cursor_values',case when coalesce((select max(f.facet_total)>p.facet_limit
          from facet_blocker_values f),false) then (
          select jsonb_build_object('after_code',f.code)
          from facet_blocker_values f where f.facet_ordinal=p.facet_limit
        ) end
      ) end
    )) facets
    from params p
  ),
  row_json as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'selection_key',selection_key,
      'group_key',group_key,
      'invoice_id',invoice_id,
      'invoice_number',invoice_number,
      'source_revision',document_revision::text,
      'document_revision',document_revision,
      'client_id',client_id,


      'client_name',client_name,
      'candidate_ids',candidate_ids,
      'candidate_names',candidate_names,
      'candidate_display',candidate_display,
      'week_ending_dates',week_ending_dates,
      'week_ending_date',week_ending_date,
      'week_ending_display',case when jsonb_array_length(week_ending_dates)>1 then 'Multiple weeks' else to_char(week_ending_date,'DD/MM/YYYY') end,
      'currency',currency,
      'invoice_stream',invoice_stream,
      'total_ex_vat',total_ex_vat,
      'vat_amount',vat_amount,
      'total_inc_vat',total_inc_vat,
      'generated_state',generated_state,
      'row_status',row_status,
      'is_early',is_early,
      'selectable',selectable,
      'selected',selectable and last_selection_action <> 'EXCLUDE',
      'issue_blocker_codes',coalesce(issue_blocker_codes,'[]'::jsonb),
      'delivery_blocker_codes',coalesce(delivery_blocker_codes,'[]'::jsonb),
      'informational_codes',coalesce(informational_codes,'[]'::jsonb),
      'blocked_for_sending',blocked_for_sending,
      'can_issue_only',can_issue_only,
      'can_issue_and_deliver',can_issue_and_deliver,
      'active_issue_operation_id',active_issue_operation_id_text,
      'active_issue_status',active_issue_operation->>'status',
      'active_issue_operation',active_issue_operation,
      'active_document_operation_id',active_document_operation_id_text,
      'validation_detail',validation_detail,
      'support_readiness',coalesce(
        support.invoice_json->'support_readiness',
        visible_rows.support_readiness
      ),
      'sort_tuple',jsonb_build_object(
        'sort_date',case when sort_date_key is not null then sort_date_key::text end,
        'sort_text',sort_text_key,
        'sort_numeric',case when sort_numeric_key is not null then sort_numeric_key::text end,
        'selection_key',selection_key
      )
    ) order by page_ordinal),'[]'::jsonb) rows
    from visible_rows
    left join visible_support support
      on support.support_invoice_id=visible_rows.invoice_id
  )
  select jsonb_build_object(
    'contract_version','INVOICE_BATCH_CANDIDATES_V2',
    'action','ISSUE',
    'mode',v_mode,
    'snapshot',v_snapshot,
    'normalised_filter',v_filters,
    'normalised_sort',v_sort,
    'filter_hash',v_filter_hash,
    'query_hash',v_query_hash,
    'selection_hash',v_selection_hash,
    'rows',(select rows from row_json),
    'page',jsonb_build_object(
      'page_size',v_page_size,
      'returned_count',(select count(*) from visible_rows),
      'total_count',case
        when v_mode in ('PAGE','EXPAND_SELECTION','EXPLICIT_KEYS')
          then coalesce((select max(k.full_scope_count) from candidate_keys k),0)
        else (select display_count from display_totals)
      end,
      'has_more',case
        when v_mode in ('PAGE','EXPAND_SELECTION','EXPLICIT_KEYS')
          then exists (
            select 1
            from candidate_keys k
            where k.page_ordinal>v_page_size
          )
        else (select count(*) from page_rows)>v_page_size
      end,
      'next_cursor_values',case when (
        case
          when v_mode in ('PAGE','EXPAND_SELECTION','EXPLICIT_KEYS')
            then exists (
              select 1
              from candidate_keys k
              where k.page_ordinal>v_page_size
            )
          else (select count(*) from page_rows)>v_page_size
        end
      ) then (
        select case when v_mode='EXPAND_SELECTION'
          then jsonb_build_object('after_selection_key',selection_key)
          else jsonb_build_object(
            'after_selection_key',selection_key,
            'after_sort_date',case when sort_date_key is not null then sort_date_key::text end,
            'after_sort_text',sort_text_key,
            'after_sort_numeric',case when sort_numeric_key is not null then sort_numeric_key::text end
          )
        end
        from (
          select
            selection_key,
            sort_date_key,
            sort_text_key,
            sort_numeric_key,
            page_ordinal
          from candidate_keys
          where page_ordinal<=v_page_size
        ) cursor_source
        order by page_ordinal desc
        limit 1
      ) else null end
    ),
    'totals',jsonb_build_object(
      'all',(select all_count from totals),
      'filtered_total',(select all_count from totals),
      'display_total',(select display_count from display_totals),
      'eligible_total',(select ready_count from totals),
      'selected_total',(select selected_count from totals),
      'excluded_total',(select ready_count-selected_count from totals),
      'ready',(select ready_count from totals),
      'blocked',(select blocked_count from totals),
      'blocked_total',(select blocked_count from totals),
      'blocked_for_sending',(select blocked_for_sending_count from totals),
      'stale',(select stale_count from totals),
      'in_progress',(select in_progress_count from totals)
    ),
    'selection_summary',jsonb_build_object(
      'eligible_total',(select ready_count from totals),
      'selected_total',(select selected_count from totals),
      'excluded_total',(select ready_count-selected_count from totals),
      'blocked_total',(select blocked_count from totals),
      'exact',v_mode in ('FACETS','SUMMARY')
    ),
    'group_selection',(select groups from group_selection_json),
    'facets',case
      when v_mode='FACETS' then (select facets from facet_json)
      else jsonb_build_object()
    end,
    'selection_seed',jsonb_build_object('mode','IMPLICIT_ALL','default_selected',true)
  ) into v_result;

  if v_mode='SUMMARY'
     and coalesce((v_result#>>'{totals,filtered_total}')::integer,0)>25000 then
    raise exception using
      errcode='54000',
      message='BATCH_SUMMARY_SCOPE_TOO_LARGE';
  end if;

  if v_mode='EXPLICIT_KEYS' and (
    jsonb_array_length(coalesce(v_result->'rows','[]'::jsonb))
      <> jsonb_array_length(v_selection_keys)
    or exists (
      select 1
      from jsonb_array_elements(v_result->'rows') row_item(row_json)
      where coalesce(row_json->>'source_revision','')
        is distinct from coalesce(
          v_expected_source_revisions->>(row_json->>'selection_key'),
          ''
        )
    )
  ) then
    raise exception using
      errcode='40001',
      message='BATCH_SOURCE_CHANGED';
  end if;

  v_snapshot_after := private._invoice_candidate_snapshot_verify_v2(
    'ISSUE',
    v_snapshot,
    coalesce(p_now_utc,now())
  );
  if v_snapshot_after->>'revision' <> v_snapshot->>'revision' then
    raise exception using errcode='40001', message='BATCH_SNAPSHOT_CHANGED';
  end if;

  return v_result;
end;
$function$;

alter function private._invoice_batch_issue_candidate_rows_v2(jsonb,timestamptz) OWNER TO CURRENT_USER;
revoke all on function private._invoice_batch_issue_candidate_rows_v2(jsonb,timestamptz) from public, anon, authenticated;
grant execute on function private._invoice_batch_issue_candidate_rows_v2(jsonb,timestamptz) to service_role;

drop function if exists private._invoice_operation_start_core_v8(jsonb,uuid,timestamptz);
create function private._invoice_operation_start_core_v8(
  p_commands jsonb,
  p_actor_user_id uuid,
  p_now_utc timestamptz default now()
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_jwt_role text:=coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    auth.jwt()->>'role','');
  v_auth_user uuid:=auth.uid();
  v_result jsonb;
begin
  if jsonb_typeof(p_commands)<>'array'
     or jsonb_array_length(p_commands)<1
     or jsonb_array_length(p_commands)>1000 then
    raise exception using errcode='22023',
      message='p_commands must be a JSON array containing 1..1000 commands';
  end if;

  if p_actor_user_id is null
     or not exists(select 1 from public.tms_users u
       where u.id=p_actor_user_id and u.is_active and lower(u.role)='admin')
     or(v_jwt_role<>'service_role' and v_auth_user is distinct from p_actor_user_id) then
    raise exception using errcode='42501',
      message='Active administrator actor and matching authenticated/service caller required';
  end if;

  with raw as materialized (
    select e.ordinality::integer command_no,e.value command_json,
      upper(btrim(coalesce(e.value->>'command_type',e.value->>'type',''))) command_type
    from jsonb_array_elements(p_commands) with ordinality e(value,ordinality)
  ),
  command_ids as materialized (
    select r.command_no,r.command_type,x.ordinality::integer item_no,x.value id_text,
      x.value ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        valid_uuid
    from raw r
    cross join lateral jsonb_array_elements_text(
      case
        when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
          then r.command_json->'nhsp_shift_ids'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_NHSP','GENERATE_AUTO')
          and jsonb_typeof(r.command_json->'source_ids')='array'
          then r.command_json->'source_ids'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_NHSP','GENERATE_AUTO')
          and jsonb_typeof(r.command_json->'timesheet_ids')='array'
          then r.command_json->'timesheet_ids'
        when r.command_type in('GENERATE_CREDIT_NOTE','ISSUE_INVOICES','DELIVER_INVOICES')
          and jsonb_typeof(r.command_json->'invoice_ids')='array'
          then r.command_json->'invoice_ids'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and coalesce(r.command_json->>'base_invoice_id','')<>'' then
          jsonb_build_array(r.command_json->>'base_invoice_id')
        when r.command_type in(
          'GENERATE_CREDIT_NOTE','VIEW_INVOICE_DOCUMENT','DELIVER_INVOICES')
          and coalesce(r.command_json->>'invoice_id','')<>'' then
          jsonb_build_array(r.command_json->>'invoice_id')
        when r.command_type='VIEW_TIMESHEET_DOCUMENT'
          and coalesce(r.command_json->>'timesheet_id','')<>'' then
          jsonb_build_array(r.command_json->>'timesheet_id')
        else '[]'::jsonb
      end
    ) with ordinality x(value,ordinality)
  ),
  canonical_ids as materialized (
    select command_no,array_agg(distinct id_text::uuid order by id_text::uuid) ids
    from command_ids where valid_uuid group by command_no
  ),
  generation_groups as materialized (
    select *
    from private._invoice_generation_resolve_command_groups(
      p_commands,p_actor_user_id,v_now)
  ),
  view_facts as materialized (
    select r.command_no,r.command_type,
      case when r.command_type='VIEW_INVOICE_DOCUMENT' then 'INVOICE' else 'TIMESHEET' end entity_type,
      (array_agg(ci.id_text::uuid order by ci.item_no))[1] entity_id,
      case when r.command_type='VIEW_INVOICE_DOCUMENT'
        then i.document_revision else t.document_revision end document_revision,
      case when r.command_type='VIEW_INVOICE_DOCUMENT'
        then 'DRAFT_PREVIEW' else 'TIMESHEET' end purpose,
      coalesce(nullif(r.command_json->>'template_version',''),
        case when r.command_type='VIEW_INVOICE_DOCUMENT'
          then 'invoice-professional-v2' else 'timesheet-professional-v1' end) template_version
    from raw r
    left join command_ids ci on ci.command_no=r.command_no and ci.valid_uuid
    left join public.invoices i
      on r.command_type='VIEW_INVOICE_DOCUMENT' and i.id=ci.id_text::uuid
    left join public.timesheets t
      on r.command_type='VIEW_TIMESHEET_DOCUMENT' and t.timesheet_id=ci.id_text::uuid
    where r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    group by r.command_no,r.command_type,i.document_revision,t.document_revision,r.command_json
  ),
  issue_facts as materialized (
    select r.command_no,
      array_agg(i.id order by i.id) invoice_ids,
      encode(digest(string_agg(i.id||':'||i.document_revision,
        '|' order by i.id),'sha256'),'hex') invoice_revision_hash,
      count(*)::integer resolved_count
    from raw r join canonical_ids ci on ci.command_no=r.command_no
    cross join unnest(ci.ids) invoice_id
    join public.invoices i on i.id=invoice_id
    where r.command_type='ISSUE_INVOICES'
    group by r.command_no
  ),
  delivery_facts as materialized (
    select r.command_no,
      array_agg(i.id order by i.id) invoice_ids,
      array_agg(i.issued_document_version_id order by i.id) document_version_ids,
      encode(digest(string_agg(concat_ws(':',i.id::text,
        i.issued_document_version_id::text,v.sha256,v.size_bytes::text,v.page_count::text),
        '|' order by i.id),'sha256'),'hex') delivery_revision,
      count(*)::integer resolved_count
    from raw r join canonical_ids ci on ci.command_no=r.command_no
    cross join unnest(ci.ids) invoice_id
    join public.invoices i on i.id=invoice_id
    join public.invoice_document_versions v
      on v.id=i.issued_document_version_id and v.status='READY'
      and v.purpose='FINAL_ISSUE' and v.entity_type='INVOICE' and v.entity_id=i.id
    where r.command_type='DELIVER_INVOICES' and i.status in('ISSUED','PAID')
    group by r.command_no
  ),
  recipient_sets as materialized (
    select r.command_no,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'recipient_set')='array'
              then r.command_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_recipients,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'cc')='array'
              then r.command_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_cc,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'bcc')='array'
              then r.command_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_bcc,
      (select count(*)::integer
        from(
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'recipient_set')='array'
              then r.command_json->'recipient_set' else '[]'::jsonb end)
          union all
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'cc')='array'
              then r.command_json->'cc' else '[]'::jsonb end)
          union all
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'bcc')='array'
              then r.command_json->'bcc' else '[]'::jsonb end)
        ) e
        where nullif(btrim(e.value),'') is not null
          and btrim(e.value)!~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
        invalid_count
    from raw r
    where r.command_type='DELIVER_INVOICES'
  ),
  delivery_route_requests as materialized (
    select r.command_no,i.invoice_id,jsonb_build_object(
      'request_key',r.command_no::text||':'||i.invoice_id::text,
      'invoice_id',i.invoice_id,
      'recipient_set',rs.canonical_recipients,
      'cc',rs.canonical_cc,
      'bcc',rs.canonical_bcc,
      'delivery_policy',upper(coalesce(
        nullif(r.command_json->>'delivery_policy',''),'ATTACH')),
      'template_version',coalesce(
        nullif(r.command_json->>'delivery_template_version',''),
        'invoice-delivery-v1')) request_json
    from raw r
    join delivery_facts f on f.command_no=r.command_no
    join recipient_sets rs on rs.command_no=r.command_no
    cross join unnest(f.invoice_ids) i(invoice_id)
    where r.command_type='DELIVER_INVOICES'
  ),
  delivery_routes as materialized (
    select q.command_no,d.*
    from private._invoice_delivery_routes_batch(coalesce((
      select jsonb_agg(q.request_json order by q.command_no,q.invoice_id)
      from delivery_route_requests q),'[]'::jsonb),
      (v_now at time zone 'Europe/London')::date) d
    join delivery_route_requests q
      on q.request_json->>'request_key'=d.request_key
      and q.invoice_id=d.invoice_id
  ),
  delivery_route_groups as materialized (
    select command_no,
      encode(digest(string_agg(invoice_id::text||':'||route_policy_hash,
        '|' order by invoice_id),'sha256'),'hex') route_set_hash,
      jsonb_agg(jsonb_build_object(
        'invoice_id',invoice_id,'to',canonical_to,'cc',canonical_cc,
        'bcc',canonical_bcc,'recipient_set_hash',recipient_set_hash,
        'route_policy_hash',route_policy_hash,
        'route_source',route_source,'do_not_send',do_not_send,
        'warning_codes',warning_codes,'blocker_codes',blocker_codes,
        'evaluated_date',(v_now at time zone 'Europe/London')::date)
        order by invoice_id) frozen_routes
    from delivery_routes
    group by command_no
  ),
  issue_delivery_intents as materialized (
    select r.command_no,
      (intent.intent_json-'recipient_set'-'cc'-'bcc')
        ||jsonb_build_object(
          'recipient_set',recipients.canonical,
          'cc',cc.canonical,'bcc',bcc.canonical) canonical_intent,
      recipients.requested_count+cc.requested_count+bcc.requested_count requested_count,
      recipients.valid_count+cc.valid_count+bcc.valid_count valid_count
    from raw r
    cross join lateral(
      select case when jsonb_typeof(r.command_json->'delivery_intent')='object'
        then r.command_json->'delivery_intent' else '{}'::jsonb end intent_json
    ) intent
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
                then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
              then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
              then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) recipients
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'cc')='array'
                then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'cc')='array'
              then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'cc')='array'
              then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) cc
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'bcc')='array'
                then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'bcc')='array'
              then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'bcc')='array'
              then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) bcc
    where r.command_type='ISSUE_INVOICES'
  ),
  asset_specs as materialized (
    select r.command_no,r.command_json,
      upper(btrim(coalesce(r.command_json->>'source_kind',''))) source_kind,
      case when coalesce(r.command_json->>'source_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(r.command_json->>'source_id')::uuid end source_id,
      nullif(btrim(r.command_json->>'source_revision'),'') source_revision,
      nullif(btrim(r.command_json->>'original_r2_key'),'') original_r2_key,
      nullif(btrim(r.command_json->>'original_filename'),'') original_filename,
      nullif(btrim(r.command_json->>'declared_media_type'),'') declared_media_type,
      case when coalesce(r.command_json->>'rotation_degrees','') ~ '^(0|90|180|270)$'
        then(r.command_json->>'rotation_degrees')::integer end rotation_degrees,
      r.command_json?'rotation_degrees' rotation_supplied
    from raw r where r.command_type='PREPARE_ASSET'
  ),
  issue_entity_locks as materialized (
    select pg_advisory_xact_lock(
      hashtextextended('ISSUE_INVOICE|'||ci.id_text,0))
    from command_ids ci join raw r on r.command_no=ci.command_no
    where r.command_type='ISSUE_INVOICES' and ci.valid_uuid
    order by ci.id_text
  ),
  command_validation as materialized (
    select r.command_no,r.command_type,
      case
        when jsonb_typeof(r.command_json)<>'object'
          then 'COMMAND_MUST_BE_OBJECT'
        when r.command_type not in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS','GENERATE_EXPENSES',
          'GENERATE_NHSP','GENERATE_CREDIT_NOTE','GENERATE_AUTO',
          'VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT','PREPARE_ASSET',
          'ISSUE_INVOICES','DELIVER_INVOICES','RECONCILE')
          then 'UNSUPPORTED_COMMAND_TYPE'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_AUTO')
          and not(
            jsonb_typeof(r.command_json->'source_ids')='array'
            or jsonb_typeof(r.command_json->'timesheet_ids')='array')
          then 'GENERATION_SOURCE_ARRAY_REQUIRED'
        when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')<>'array'
          then 'NHSP_SHIFT_ARRAY_REQUIRED'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and r.command_json?'consolidation_mode'
          and upper(coalesce(r.command_json->>'consolidation_mode','')) not in(
            'NONE','BY_WEEK','ANY_WEEK')
          then 'INVALID_CONSOLIDATION_MODE'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and r.command_json?'allow_early'
          and jsonb_typeof(r.command_json->'allow_early')<>'boolean'
          then 'ALLOW_EARLY_MUST_BE_BOOLEAN'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(
            r.command_json->>'target_invoice_week','')),'') is not null
          and not pg_input_is_valid(
            r.command_json->>'target_invoice_week','date')
          then 'INVALID_TARGET_INVOICE_WEEK'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'base_invoice_id','')),'') is null
          then 'BASE_INVOICE_ID_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and(select count(*) from command_ids x
            where x.command_no=r.command_no)<>1
          then 'EXACTLY_ONE_BASE_INVOICE_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'credit_reason','')),'') is null
          then 'CREDIT_REASON_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'command_token','')),'') is null
          then 'CREDIT_COMMAND_TOKEN_REQUIRED'
        when exists(select 1 from command_ids x
          where x.command_no=r.command_no and not x.valid_uuid)
          then 'MALFORMED_UUID'
        when r.command_type like 'GENERATE_%' and not exists(
          select 1 from generation_groups g where g.command_no=r.command_no)
          then 'GENERATION_SOURCES_REQUIRED'
        when r.command_type like 'GENERATE_%'
          and (select count(*) from generation_groups g
            where g.command_no=r.command_no)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and(select count(*) from command_ids x where x.command_no=r.command_no)<>1
          then 'EXACTLY_ONE_DOCUMENT_ENTITY_REQUIRED'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and nullif(btrim(coalesce(r.command_json->>'priority_reason','')),'') is null
          then 'DOCUMENT_PRIORITY_REASON_REQUIRED'
        when r.command_type='VIEW_INVOICE_DOCUMENT'
          and upper(coalesce(nullif(r.command_json->>'purpose',''),
            'DRAFT_PREVIEW'))<>'DRAFT_PREVIEW'
          then 'INVALID_INVOICE_DOCUMENT_PURPOSE'
        when r.command_type='VIEW_TIMESHEET_DOCUMENT'
          and upper(coalesce(nullif(r.command_json->>'purpose',''),
            'TIMESHEET'))<>'TIMESHEET'
          then 'INVALID_TIMESHEET_DOCUMENT_PURPOSE'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and not exists(select 1 from view_facts v
            where v.command_no=r.command_no and v.document_revision is not null)
          then 'DOCUMENT_ENTITY_NOT_FOUND'
        when r.command_type='PREPARE_ASSET' and not exists(
          select 1 from asset_specs a
          where a.command_no=r.command_no
            and a.source_kind in(
              'MANUAL_TIMESHEET','TIMESHEET_EVIDENCE','OTHER_EVIDENCE',
              'HR_REPORT','NHSP_REPORT','HIGHER_RATE_SUPPORT')
            and a.source_id is not null and a.source_revision is not null
            and a.original_r2_key is not null and a.original_filename is not null
            and a.declared_media_type is not null
            and(not a.rotation_supplied or a.rotation_degrees is not null))
          then 'INVALID_ASSET_SOURCE_METADATA'
        when r.command_type='PREPARE_ASSET'
          and r.command_json?'rotation_degrees'
          and coalesce(r.command_json->>'rotation_degrees','')!~'^(0|90|180|270)$'
          then 'INVALID_ASSET_ROTATION'
        when r.command_type='ISSUE_INVOICES'
          and(jsonb_typeof(r.command_json->'invoice_ids')<>'array'
            or coalesce(cardinality((select ids from canonical_ids x
              where x.command_no=r.command_no)),0)=0
            or coalesce((select resolved_count from issue_facts f
              where f.command_no=r.command_no),0)<>
              coalesce(cardinality((select ids from canonical_ids x
                where x.command_no=r.command_no)),0))
          then 'ISSUE_INVOICES_NOT_RESOLVED'
        when r.command_type='ISSUE_INVOICES'
          and (r.command_json?'allow_early'
            and jsonb_typeof(r.command_json->'allow_early')<>'boolean'
            or r.command_json?'deliver'
            and jsonb_typeof(r.command_json->'deliver')<>'boolean')
          then 'ISSUE_FLAGS_MUST_BE_BOOLEAN'
        when r.command_type='ISSUE_INVOICES'
          and coalesce(nullif(r.command_json->>'command_token',''),'')=''
          then 'ISSUE_COMMAND_TOKEN_REQUIRED'
        when r.command_type='ISSUE_INVOICES'
          and coalesce(cardinality((select ids from canonical_ids x
            where x.command_no=r.command_no)),0)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='ISSUE_INVOICES'
          and r.command_json?'delivery_intent'
          and jsonb_typeof(r.command_json->'delivery_intent')<>'object'
          then 'ISSUE_DELIVERY_INTENT_MUST_BE_OBJECT'
        when r.command_type='ISSUE_INVOICES'
          and jsonb_typeof(r.command_json->'delivery_intent')='object'
          and (
            r.command_json->'delivery_intent'?'recipient_set'
              and jsonb_typeof(r.command_json->'delivery_intent'->'recipient_set')<>'array'
            or r.command_json->'delivery_intent'?'cc'
              and jsonb_typeof(r.command_json->'delivery_intent'->'cc')<>'array'
            or r.command_json->'delivery_intent'?'bcc'
              and jsonb_typeof(r.command_json->'delivery_intent'->'bcc')<>'array')
          then 'ISSUE_DELIVERY_RECIPIENT_SET_MUST_BE_ARRAY'
        when r.command_type='ISSUE_INVOICES'
          and exists(
            select 1 from issue_delivery_intents intent
            where intent.command_no=r.command_no
              and intent.requested_count<>intent.valid_count)
          then 'ISSUE_DELIVERY_RECIPIENT_SET_INVALID'
        when r.command_type='ISSUE_INVOICES' and exists(
          select 1 from command_ids x
          join public.invoice_operation_chunks c
            on c.chunk_type='ISSUE_INVOICE' and c.entity_type='INVOICE'
            and c.entity_id=x.id_text::uuid
            and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
          where x.command_no=r.command_no and x.valid_uuid)
          and not exists(
            select 1
            from public.invoice_operations exact
            join issue_facts f on f.command_no=r.command_no
            join issue_delivery_intents intent on intent.command_no=r.command_no
            where exact.idempotency_key=encode(digest(concat_ws('|',
              'ISSUE_INVOICES',f.invoice_revision_hash,
              coalesce(r.command_json->>'allow_early','false'),
              coalesce(r.command_json->>'deliver','false'),
              coalesce(r.command_json->>'command_token',''),
              encode(digest(intent.canonical_intent::text,'sha256'),'hex')),
              'sha256'),'hex')
              and exact.status in(
                'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
          then 'ACTIVE_ISSUE_CONFLICT'
        when r.command_type='DELIVER_INVOICES'
          and not(
            jsonb_typeof(r.command_json->'invoice_ids')='array'
            or nullif(btrim(coalesce(r.command_json->>'invoice_id','')),'') is not null)
          then 'DELIVERY_INVOICE_IDS_REQUIRED'
        when r.command_type='DELIVER_INVOICES'
          and nullif(btrim(coalesce(
            r.command_json->>'delivery_request_token','')),'') is null
          then 'DELIVERY_REQUEST_TOKEN_REQUIRED'
        when r.command_type='DELIVER_INVOICES'
          and coalesce(cardinality((select ids from canonical_ids x
            where x.command_no=r.command_no)),0)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'recipient_set'
          and jsonb_typeof(r.command_json->'recipient_set')<>'array'
          then 'DELIVERY_RECIPIENT_SET_MUST_BE_ARRAY'
        when r.command_type='DELIVER_INVOICES'
          and ((r.command_json?'cc' and jsonb_typeof(r.command_json->'cc')<>'array')
            or(r.command_json?'bcc' and jsonb_typeof(r.command_json->'bcc')<>'array'))
          then 'DELIVERY_CC_BCC_MUST_BE_ARRAY'
        when r.command_type='DELIVER_INVOICES'
          and exists(select 1 from recipient_sets rs
            where rs.command_no=r.command_no and rs.invalid_count>0)
          then 'DELIVERY_RECIPIENT_SET_INVALID'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'delivery_part_number'
          and coalesce(r.command_json->>'delivery_part_number','') !~ '^[1-9][0-9]*$'
          then 'INVALID_DELIVERY_PART_NUMBER'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'delivery_policy'
          and upper(coalesce(r.command_json->>'delivery_policy',''))
            not in('ATTACH','SPLIT','SECURE_LINK')
          then 'INVALID_DELIVERY_POLICY'
        when r.command_type='DELIVER_INVOICES'
          and(coalesce((select resolved_count from delivery_facts f
              where f.command_no=r.command_no),0)<>
              coalesce(cardinality((select ids from canonical_ids x
                where x.command_no=r.command_no)),0))
          then 'ISSUED_DOCUMENT_NOT_READY'
        when r.command_type='RECONCILE'
          and not(r.command_json?'operation_ids'
            or r.command_json?'older_than_seconds') then 'RECONCILE_SCOPE_REQUIRED'
        when r.command_type='RECONCILE'
          and r.command_json?'operation_ids'
          and jsonb_typeof(r.command_json->'operation_ids')<>'array'
          then 'RECONCILE_OPERATION_IDS_MUST_BE_ARRAY'
        when r.command_type='RECONCILE'
          and jsonb_typeof(r.command_json->'operation_ids')='array'
          and jsonb_array_length(r.command_json->'operation_ids')>500
          then 'RECONCILE_OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='RECONCILE'
          and r.command_json?'older_than_seconds'
          and coalesce(r.command_json->>'older_than_seconds','') !~ '^[0-9]{1,6}$'
          then 'RECONCILE_AGE_MUST_BE_INTEGER_SECONDS'
      end error_code,
      case when r.command_type like 'GENERATE_%' then (
        select jsonb_agg(jsonb_build_object(
          'group_key',g.group_key,'code',g.blocker_code,'detail',g.blocker_detail)
          order by g.group_key)
        from generation_groups g
        where g.command_no=r.command_no and g.blocker_code is not null)
      end error_detail
    from raw r cross join(select count(*) from issue_entity_locks) lock_barrier
  ),
  valid_commands as materialized (
    select r.* from raw r join command_validation v using(command_no,command_type)
    where v.error_code is null
  ),
  inserted_assets as materialized (
    insert into public.invoice_document_assets(
      source_kind,source_id,source_revision,original_r2_key,original_filename,
      declared_media_type,orientation_degrees,status,normalised_manifest_json,
      created_at_utc,updated_at_utc)
    select a.source_kind,a.source_id,a.source_revision,a.original_r2_key,
      a.original_filename,a.declared_media_type,a.rotation_degrees,
      'DISCOVERED','[]'::jsonb,v_now,v_now
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    on conflict(source_kind,source_id,source_revision,original_r2_key) do nothing
    returning *
  ),
  assets as materialized (
    select a.command_no,inserted.*
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    join inserted_assets inserted
      on inserted.source_kind=a.source_kind
      and inserted.source_id=a.source_id
      and inserted.source_revision=a.source_revision
      and inserted.original_r2_key=a.original_r2_key
    union all
    select a.command_no,registered.*
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    join public.invoice_document_assets registered
      on registered.source_kind=a.source_kind
      and registered.source_id=a.source_id
      and registered.source_revision=a.source_revision
      and registered.original_r2_key=a.original_r2_key
    where not exists(
      select 1 from inserted_assets inserted
      where inserted.source_kind=a.source_kind
        and inserted.source_id=a.source_id
        and inserted.source_revision=a.source_revision
        and inserted.original_r2_key=a.original_r2_key)
  ),
  asset_workflow_state as materialized (
    select a.*,
      exists(
        select 1
        from public.invoice_operation_chunks c
        join public.invoice_operations o on o.id=c.operation_id
        where c.document_asset_id=a.id
          and c.chunk_type in('ASSET_INSPECT','ASSET_NORMALISE')
          and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
          and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
      ) has_active_work
    from assets a
  ),
  operation_specs as materialized (
    select v.command_no,v.command_type,v.command_json,
      'GENERATE_INVOICES'::text operation_type,
      case when count(*)=1 then 'CLIENT' else 'INVOICE_BATCH' end entity_type,
      case when count(*)=1 then(array_agg(g.client_id order by g.client_id))[1]
        else null::uuid end entity_id,
      encode(digest(string_agg(g.source_revision_hash,'|' order by g.group_key),
        'sha256'),'hex') source_revision,
      null::text template_version,
      case when v.command_type='GENERATE_AUTO' then 200 else 600 end priority,
      count(*)::integer unit_count,
      jsonb_build_object('generation_groups',
        jsonb_agg(g.idempotency_components order by g.group_key)) canonical_input,
      encode(digest('GENERATE_INVOICES|'||
        string_agg(g.idempotency_components::text,'|' order by g.group_key),
        'sha256'),'hex') idempotency_key
    from valid_commands v join generation_groups g on g.command_no=v.command_no
    where v.command_type like 'GENERATE_%'
    group by v.command_no,v.command_type,v.command_json
    union all
    select v.command_no,v.command_type,v.command_json,'BUILD_DOCUMENT',
      f.entity_type,f.entity_id,f.document_revision::text,f.template_version,1000,1,
      jsonb_build_object('entity_type',f.entity_type,'entity_id',f.entity_id,
        'purpose',f.purpose,'document_revision',f.document_revision,
        'template_version',f.template_version),
      encode(digest(concat_ws('|','BUILD_DOCUMENT',f.entity_type,f.entity_id::text,
        f.purpose,f.document_revision::text,f.template_version),'sha256'),'hex')
    from valid_commands v join view_facts f on f.command_no=v.command_no
    where v.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and not exists(
        select 1 from public.invoice_document_versions ready
        where ready.entity_type=f.entity_type and ready.entity_id=f.entity_id
          and ready.purpose=f.purpose
          and ready.source_revision=f.document_revision::text
          and ready.template_version=f.template_version and ready.status='READY')
    union all
    select v.command_no,v.command_type,v.command_json,'PREPARE_ASSET',
      'DOCUMENT_ASSET',a.id,a.source_revision,null,550,1,
      jsonb_build_object('document_asset_id',a.id,'source_kind',a.source_kind,
        'source_id',a.source_id,'source_revision',a.source_revision,
        'original_r2_key',a.original_r2_key),
      encode(digest(concat_ws('|','PREPARE_ASSET',a.source_kind,a.source_id::text,
        a.source_revision,a.original_r2_key),'sha256'),'hex')
    from valid_commands v join asset_workflow_state a
      on a.command_no=v.command_no
    where v.command_type='PREPARE_ASSET'
      and a.status in('DISCOVERED','INSPECTING','NORMALISING')
      and not(a.status in('INSPECTING','NORMALISING')
        and not a.has_active_work)
    union all
    select v.command_no,v.command_type,v.command_json,'ISSUE_INVOICES',
      'INVOICE_BATCH',null,f.invoice_revision_hash,null,850,
      cardinality(f.invoice_ids),
      jsonb_build_object('invoice_ids',to_jsonb(f.invoice_ids),
        'invoice_revision_hash',f.invoice_revision_hash,
        'allow_early',coalesce(v.command_json->'allow_early','false'::jsonb),
        'deliver',coalesce(v.command_json->'deliver','false'::jsonb),
        'command_token',v.command_json->>'command_token',
        'delivery_request_token','ISSUE:'||(v.command_json->>'command_token'),
        'delivery_intent',intent.canonical_intent),
      encode(digest(concat_ws('|','ISSUE_INVOICES',f.invoice_revision_hash,
        coalesce(v.command_json->>'allow_early','false'),
        coalesce(v.command_json->>'deliver','false'),
        coalesce(v.command_json->>'command_token',''),
        encode(digest(intent.canonical_intent::text,'sha256'),'hex')),
        'sha256'),'hex')
    from valid_commands v join issue_facts f on f.command_no=v.command_no
    join issue_delivery_intents intent on intent.command_no=v.command_no
    where v.command_type='ISSUE_INVOICES'
    union all
    select v.command_no,v.command_type,v.command_json,'DELIVER_INVOICES',
      'INVOICE_BATCH',null,f.delivery_revision,
      coalesce(nullif(v.command_json->>'delivery_template_version',''),
        'invoice-delivery-v1'),400,cardinality(f.invoice_ids),
      jsonb_build_object('invoice_ids',to_jsonb(f.invoice_ids),
        'issued_document_version_ids',to_jsonb(f.document_version_ids),
        'delivery_revision',f.delivery_revision,
        'recipient_set',rs.canonical_recipients,
        'recipient_set_hash',drg.route_set_hash,
        'frozen_delivery_routes',drg.frozen_routes,
        'template_version',coalesce(nullif(v.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        'delivery_part_number',coalesce(v.command_json->'delivery_part_number','1'::jsonb),
        'delivery_request_token',v.command_json->>'delivery_request_token'),
      encode(digest(concat_ws('|','DELIVER_INVOICES',f.delivery_revision,
        drg.route_set_hash,
        coalesce(nullif(v.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        coalesce(v.command_json->>'delivery_part_number','1'),
        v.command_json->>'delivery_request_token'),'sha256'),'hex')
    from valid_commands v join delivery_facts f on f.command_no=v.command_no
    join recipient_sets rs on rs.command_no=v.command_no
    join delivery_route_groups drg on drg.command_no=v.command_no
    where v.command_type='DELIVER_INVOICES'
    union all
    select v.command_no,v.command_type,v.command_json,'RECONCILE_INVOICE_WORK',
      'SYSTEM',null,
      encode(digest(coalesce(v.command_json->'operation_ids','[]')::text||'|'||
        coalesce(v.command_json->>'older_than_seconds',''),'sha256'),'hex'),
      null,50,1,
      jsonb_build_object(
        'operation_ids',coalesce(v.command_json->'operation_ids','[]'::jsonb),
        'older_than_seconds',least(604800,greatest(30,case
          when coalesce(v.command_json->>'older_than_seconds','') ~ '^[0-9]{1,6}$'
            then(v.command_json->>'older_than_seconds')::integer else 300 end)),
        'max_rows',least(500,greatest(1,case
          when coalesce(v.command_json->>'max_rows','') ~ '^[0-9]{1,6}$'
            then(v.command_json->>'max_rows')::integer else 100 end))),
      encode(digest('RECONCILE|'||coalesce(v.command_json->'operation_ids','[]')::text||
        '|'||coalesce(v.command_json->>'older_than_seconds',''),'sha256'),'hex')
    from valid_commands v where v.command_type='RECONCILE'
  ),
  locks as materialized (
    select pg_advisory_xact_lock(hashtextextended(x.lock_key,0))
    from(
      select idempotency_key lock_key from operation_specs
      union
      select 'ISSUE_INVOICE|'||unnest(f.invoice_ids)::text
      from issue_facts f join valid_commands v on v.command_no=f.command_no
      where v.command_type='ISSUE_INVOICES'
    ) x order by x.lock_key
  ),
  existing_before as materialized (
    select s.command_no,o.*
    from operation_specs s
    join lateral (
      select candidate.*
      from public.invoice_operations candidate
      where candidate.idempotency_key=s.idempotency_key
        and candidate.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED','COMPLETE')
      order by(candidate.status='COMPLETE') desc,candidate.created_at_utc desc
      limit 1
    ) o on true
  ),
  inserted_operations as materialized (
    insert into public.invoice_operations(
      operation_type,entity_type,entity_id,actor_user_id,idempotency_key,
      status,phase,priority,source_revision,template_version,input_json,
      config_json,progress_json,total_units,chunk_count,control_version,
      change_seq,manifest_generation,manifest_committed,release_complete,
      created_at_utc,updated_at_utc)
    select s.operation_type,s.entity_type,s.entity_id,p_actor_user_id,
      s.idempotency_key,'QUEUED','SUBMITTED',s.priority,s.source_revision,
      s.template_version,s.canonical_input,
      jsonb_build_object(
        'command_type',s.command_type,
        'processor_policy',private._invoice_processor_limits()),
      jsonb_build_object('status_message','Accepted','total_units',s.unit_count,
        'completed_units',0,'failed_units',0),
      s.unit_count,s.unit_count,1,nextval('public.invoice_operation_change_seq'),
      case when s.command_type in ('ISSUE_INVOICES','DELIVER_INVOICES')
        then 1 else 0 end,
      true,true,
      v_now,v_now
    from operation_specs s cross join(select count(*) from locks) lock_barrier
    where not exists(select 1 from existing_before e where e.command_no=s.command_no)
    on conflict do nothing
    returning *
  ),
  chosen as materialized (
    select s.*,coalesce(i.id,e.id) operation_id,
      coalesce(i.status,e.status) operation_status,
      coalesce(i.phase,e.phase) operation_phase,
      coalesce(i.control_version,e.control_version) control_version,
      coalesce(i.change_seq,e.change_seq) change_seq,
      coalesce(i.priority,e.priority,s.priority) current_priority,
      i.id is not null created,e.id is not null reused
    from operation_specs s
    left join inserted_operations i on i.idempotency_key=s.idempotency_key
    left join existing_before e on e.command_no=s.command_no
  ),
  raised as materialized (
    update public.invoice_operations o
    set priority=greatest(o.priority,c.priority),updated_at_utc=v_now,
        change_seq=case when o.priority<c.priority
          then nextval('public.invoice_operation_change_seq') else o.change_seq end
    from chosen c
    where c.reused and o.id=c.operation_id
      and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    returning o.id
  ),
  existing_document_versions as materialized (
    select c.command_no,c.operation_id,v.*
    from chosen c join view_facts f on f.command_no=c.command_no
    join public.invoice_document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version
      and v.status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
  ),
  document_versions as materialized (
    insert into public.invoice_document_versions(
      entity_type,entity_id,purpose,operation_id,source_revision,template_version,
      status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select f.entity_type,f.entity_id,f.purpose,c.operation_id,
      f.document_revision::text,f.template_version,'PLANNING','{}'::jsonb,
      encode(digest('{}','sha256'),'hex'),'[]'::jsonb,
      encode(digest('[]','sha256'),'hex'),v_now
    from chosen c join view_facts f on f.command_no=c.command_no
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and c.operation_status<>'COMPLETE'
    on conflict(entity_type,entity_id,purpose,source_revision,template_version)
      where purpose in('DRAFT_PREVIEW','TIMESHEET') and status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning *
  ),
  all_document_versions as materialized (
    select c.command_no,c.operation_id,v.*
    from chosen c join view_facts f on f.command_no=c.command_no
    join document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    union all
    select e.* from existing_document_versions e
  ),
  chunk_specs as materialized (
    select c.operation_id,'GENERATION_GROUP'::text chunk_type,
      'VALIDATE_SOURCES'::text phase,
      encode(digest(concat_ws('|','GENERATION_GROUP',g.group_key,
        g.source_revision_hash,c.command_type,
        coalesce(g.idempotency_components->>'consolidation_mode',''),
        coalesce(g.idempotency_components->>'invoice_stream',''),'1'),
        'sha256'),'hex') work_key,
      row_number() over(partition by c.operation_id order by g.group_key)::integer-1 sequence_no,
      'CLIENT'::text entity_type,g.client_id entity_id,null::uuid document_version_id,
      null::uuid document_asset_id,
      g.idempotency_components||jsonb_build_object(
        'canonical_source_ids',to_jsonb(g.canonical_source_ids),
        'canonical_source_members',g.canonical_source_members,
        'source_types',to_jsonb(g.source_types),
        'source_revision',g.source_revision_hash,
        'resolver_blocker_code',g.blocker_code,
        'resolver_blocker_detail',g.blocker_detail) payload_json,
      c.priority,c.control_version
    from chosen c join generation_groups g on g.command_no=c.command_no
    where c.command_type like 'GENERATE_%' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',v.id::text,
        f.document_revision::text,f.template_version,'1'),'sha256'),'hex'),
      0,f.entity_type,f.entity_id,
      v.id,null,jsonb_build_object('purpose',f.purpose,
        'source_revision',f.document_revision::text,
        'template_version',f.template_version),c.priority,c.control_version
    from chosen c join view_facts f on f.command_no=c.command_no
    join all_document_versions v on v.command_no=c.command_no
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and c.operation_status<>'COMPLETE' and v.status<>'READY'
    union all
    select c.operation_id,'ASSET_INSPECT','INSPECT',
      encode(digest(concat_ws('|','ASSET_INSPECT',a.id::text,a.source_revision,
        private._invoice_processor_limits()->>'policy_version'),'sha256'),'hex'),
      0,'DOCUMENT_ASSET',a.id,
      null,a.id,jsonb_build_object('source_revision',a.source_revision,
        'source_kind',a.source_kind,'source_id',a.source_id,
        'rotation_degrees',a.orientation_degrees),c.priority,c.control_version
    from chosen c join assets a on a.command_no=c.command_no
    where c.command_type='PREPARE_ASSET' and c.operation_status<>'COMPLETE'
      and a.status not in('READY','INSPECTING','NORMALISING')
    union all
    select c.operation_id,'ISSUE_INVOICE','VALIDATE',
      encode(digest(concat_ws('|','ISSUE_INVOICE',i.id::text,
        i.document_revision::text,c.command_json->>'command_token'),'sha256'),'hex'),
      row_number() over(partition by c.operation_id order by i.id)::integer-1,
      'INVOICE',i.id,null,null,
      jsonb_build_object(
        'request_key',c.command_no::text||':'||i.id::text,
        'invoice_id',i.id,'source_revision',i.document_revision,
        'evaluation_date',(v_now at time zone 'Europe/London')::date,
        'frozen_issue_at_utc',v_now,
        'allow_early',coalesce(c.command_json->'allow_early','false'::jsonb),
        'deliver',coalesce(c.command_json->'deliver','false'::jsonb),
        'command_token',c.command_json->>'command_token',
        'delivery_request_token','ISSUE:'||(c.command_json->>'command_token'),
        'delivery_intent',intent.canonical_intent),
      c.priority,c.control_version
    from chosen c join issue_facts f on f.command_no=c.command_no
    join issue_delivery_intents intent on intent.command_no=c.command_no
    cross join unnest(f.invoice_ids) invoice_id
    join public.invoices i on i.id=invoice_id
    where c.command_type='ISSUE_INVOICES' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'DELIVERY_PREPARE','PREPARE',
      encode(digest(concat_ws('|','DELIVERY_PREPARE',
        i.issued_document_version_id::text,dr.route_policy_hash,
        coalesce(nullif(c.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        coalesce(c.command_json->>'delivery_part_number','1'),
        c.command_json->>'delivery_request_token'),'sha256'),'hex'),
      row_number() over(partition by c.operation_id order by i.id)::integer-1,
      'INVOICE',i.id,i.issued_document_version_id,null,
      jsonb_build_object(
        'invoice_id',i.id,'issued_document_version_id',i.issued_document_version_id,
        'recipient_set',dr.canonical_to,'cc',dr.canonical_cc,
        'bcc',dr.canonical_bcc,
        'recipient_set_hash',dr.recipient_set_hash,
        'route_policy_hash',dr.route_policy_hash,
        'routing_request',jsonb_build_object(
          'request_key',dr.request_key,
          'invoice_id',i.id,
          'recipient_set',rs.canonical_recipients,
          'cc',dr.canonical_cc,
          'bcc',dr.canonical_bcc,
          'delivery_policy',upper(coalesce(
            nullif(c.command_json->>'delivery_policy',''),'ATTACH')),
          'template_version',coalesce(
            nullif(c.command_json->>'delivery_template_version',''),
            'invoice-delivery-v1')),
        'frozen_delivery_route',jsonb_build_object(
          'request_key',dr.request_key,
          'to',dr.canonical_to,'cc',dr.canonical_cc,'bcc',dr.canonical_bcc,
          'recipient_set_hash',dr.recipient_set_hash,
          'route_policy_hash',dr.route_policy_hash,
          'route_source',dr.route_source,'do_not_send',dr.do_not_send,
          'delivery_suppressed',dr.delivery_suppressed,
          'suppression_reason',dr.suppression_reason,
          'self_bill',dr.self_bill,
          'template_version',coalesce(
            nullif(c.command_json->>'delivery_template_version',''),
            'invoice-delivery-v1'),
          'delivery_policy',upper(coalesce(
            nullif(c.command_json->>'delivery_policy',''),'ATTACH')),
          'warning_codes',dr.warning_codes,'blocker_codes',dr.blocker_codes,
          'evaluated_date',(v_now at time zone 'Europe/London')::date),
        'template_version',coalesce(nullif(c.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        'delivery_policy',upper(coalesce(
          nullif(c.command_json->>'delivery_policy',''),'ATTACH')),
        'delivery_part_number',coalesce(c.command_json->'delivery_part_number','1'::jsonb),
        'delivery_request_token',encode(digest(concat_ws('|',
          'DELIVERY_REQUEST',c.command_json->>'delivery_request_token',
          i.id::text,i.issued_document_version_id::text),'sha256'),'hex'),
        'user_command_token',c.command_json->>'delivery_request_token'),
      c.priority,c.control_version
    from chosen c join delivery_facts f on f.command_no=c.command_no
    join recipient_sets rs on rs.command_no=c.command_no
    cross join unnest(f.invoice_ids) invoice_id
    join public.invoices i on i.id=invoice_id
    join delivery_routes dr on dr.command_no=c.command_no
      and dr.request_key=c.command_no::text||':'||i.id::text
      and dr.invoice_id=i.id
    where c.command_type='DELIVER_INVOICES' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'RECONCILE','RECONCILE',
      encode(digest(concat_ws('|','RECONCILE',c.canonical_input::text,'1'),
        'sha256'),'hex'),
      0,'SYSTEM',null,null,null,
      c.canonical_input,c.priority,c.control_version
    from chosen c where c.command_type='RECONCILE' and c.operation_status<>'COMPLETE'
  ),
  inserted_chunks as materialized (
    insert into public.invoice_operation_chunks(
      id,operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,document_asset_id,status,priority,run_after_utc,
      payload_json,operation_control_version,manifest_generation,
      is_manifest_member,manifest_committed,result_visible,
      created_at_utc,updated_at_utc)
    select generated.id,c.operation_id,c.chunk_type,c.phase,c.work_key,c.sequence_no,
      c.entity_type,c.entity_id,
      c.document_version_id,c.document_asset_id,'QUEUED',c.priority,v_now,
      case when c.chunk_type='DELIVERY_PREPARE'
        then jsonb_set(
          jsonb_set(
            jsonb_set(
              coalesce(c.payload_json,'{}'::jsonb),
              '{request_key}',
              to_jsonb(generated.id::text),
              true),
            '{routing_request,request_key}',
            to_jsonb(generated.id::text),
            true),
          '{frozen_delivery_route,request_key}',
          to_jsonb(generated.id::text),
          true)
        else c.payload_json end,
      c.control_version,
      case when c.chunk_type in ('ISSUE_INVOICE','DELIVERY_PREPARE')
        then 1 else 0 end,
      c.chunk_type in ('ISSUE_INVOICE','DELIVERY_PREPARE'),
      c.chunk_type in ('ISSUE_INVOICE','DELIVERY_PREPARE'),
      false,
      v_now,v_now
    from chunk_specs c
    cross join lateral (
      select gen_random_uuid() id
      where c.operation_id is not null
    ) generated
    on conflict do nothing
    returning *
  ),
  asset_operation_links as (
    update public.invoice_document_assets a
    set operation_id=c.operation_id,
        status=case when a.status='DISCOVERED' then 'INSPECTING' else a.status end,
        updated_at_utc=v_now
    from chosen c join assets x on x.command_no=c.command_no
    where c.command_type='PREPARE_ASSET' and a.id=x.id and a.status<>'READY'
    returning a.id
  ),
  entity_pointers as (
    update public.invoices i
    set active_document_operation_id=case
          when c.command_type='VIEW_INVOICE_DOCUMENT' then c.operation_id
          else i.active_document_operation_id end,
        document_state=case when c.command_type='VIEW_INVOICE_DOCUMENT'
          then 'QUEUED' else i.document_state end,
        active_issue_operation_id=case when c.command_type='ISSUE_INVOICES'
          then c.operation_id else i.active_issue_operation_id end,
        issue_state=case when c.command_type='ISSUE_INVOICES'
          then 'VALIDATING' else i.issue_state end,
        updated_at=v_now
    from chosen c
    where(c.command_type='VIEW_INVOICE_DOCUMENT' and i.id=c.entity_id)
      or(c.command_type='ISSUE_INVOICES' and exists(
        select 1
        from issue_facts f
        where f.command_no=c.command_no
          and i.id=any(f.invoice_ids)))
    returning i.id
  ),
  timesheet_pointers as (
    update public.timesheets t
    set active_document_operation_id=c.operation_id,document_state='QUEUED',
        updated_at=v_now
    from chosen c
    where c.command_type='VIEW_TIMESHEET_DOCUMENT' and t.timesheet_id=c.entity_id
    returning t.timesheet_id
  ),
  refreshed_counts as (
    update public.invoice_operations o
    set total_units=greatest(o.total_units,q.n),
        chunk_count=greatest(o.chunk_count,q.n),
        progress_json=coalesce(o.progress_json,'{}'::jsonb)||jsonb_build_object(
          'status_message','Queued',
          'total_units',greatest(o.total_units,q.n)),
        updated_at_utc=v_now,
        change_seq=nextval('public.invoice_operation_change_seq')
    from(
      select intended.operation_id,count(*)::integer n
      from chunk_specs intended
      cross join(
        select count(*) from inserted_chunks
      ) ensure_chunk_insert
      group by intended.operation_id
    ) q
    where o.id=q.operation_id and o.status<>'COMPLETE'
    returning o.id,o.chunk_count n
  ),
  ready_results as (
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',null,'status','READY',
      'document_version_id',v.id,'r2_key',v.r2_key,
      'created',false,'reused_active',false,'reused_ready',true,
      'priority_raised',false,'blocked',false,'terminal_error',null) result
    from raw r join view_facts f on f.command_no=r.command_no
    join public.invoice_document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version and v.status='READY'
    where r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',null,'status','READY',
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',true,'priority_raised',false,'blocked',false,
      'terminal_error',null) result
    from raw r join assets a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET' and a.status='READY'
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',a.operation_id,'status',a.status,
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,'blocked',true,
      'retry_required',true,'terminal_error',coalesce(a.error_json,
        jsonb_build_object('code','ASSET_'||a.status))) result
    from raw r join assets a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET'
      and a.status in('UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED')
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',a.operation_id,'status','BLOCKED',
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,'blocked',true,
      'retry_required',true,'reconcile_available',true,
      'terminal_error',jsonb_build_object(
        'code','ASSET_WORKFLOW_INCONSISTENT',
        'asset_status',a.status,'document_asset_id',a.id)) result
    from raw r join asset_workflow_state a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET'
      and a.status in('INSPECTING','NORMALISING')
      and not a.has_active_work
  ),
  operation_results as (
    select c.command_no,jsonb_build_object(
      'command_no',c.command_no,'command_type',c.command_type,'accepted',true,
      'operation_id',c.operation_id,'operation_type',c.operation_type,
      'status',coalesce(o.status,c.operation_status),
      'phase',coalesce(o.phase,c.operation_phase),
      'source_revision',c.source_revision,
      'change_seq',coalesce(o.change_seq,c.change_seq),
      'created',c.created,
      'reused_active',c.reused and coalesce(o.status,c.operation_status)<>'COMPLETE',
      'reused_ready',c.reused and coalesce(o.status,c.operation_status)='COMPLETE',
      'priority_raised',c.reused and c.priority>c.current_priority,
      'blocked',coalesce(o.status,c.operation_status)='BLOCKED',
      'terminal_error',null,
      'chunk_count',greatest(c.unit_count,(select count(*)
        from chunk_specs intended
        where intended.operation_id=c.operation_id)))
      result
    from chosen c
    left join public.invoice_operations o on o.id=c.operation_id
    left join refreshed_counts rc on rc.id=c.operation_id
  ),
  error_results as (
    select v.command_no,jsonb_build_object(
      'command_no',v.command_no,'command_type',v.command_type,
      'accepted',false,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,
      'blocked',false,
      'terminal_error',jsonb_build_object('code',v.error_code,
        'detail',v.error_detail),
      'error',jsonb_build_object('code',v.error_code,'detail',v.error_detail)) result
    from command_validation v where v.error_code is not null
  ),
  combined as (
    select * from ready_results
    union all
    select o.* from operation_results o
    where not exists(select 1 from ready_results r where r.command_no=o.command_no)
    union all
    select * from error_results
  )
  select coalesce(jsonb_agg(result order by command_no),'[]'::jsonb)
  into v_result from combined;

  return v_result;
end;
$function$;

alter function private._invoice_operation_start_core_v8(jsonb,uuid,timestamptz) OWNER TO CURRENT_USER;
revoke all on function private._invoice_operation_start_core_v8(jsonb,uuid,timestamptz)
  from public,anon,authenticated;
grant execute on function private._invoice_operation_start_core_v8(jsonb,uuid,timestamptz)
  to service_role;

create or replace function private._invoice_generation_advance_core_v8(
  p_claims jsonb,
  p_now_utc timestamptz
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_now timestamptz := coalesce(p_now_utc,now());
  v_result jsonb := '[]'::jsonb;
  v_part jsonb;
begin
  -- VALIDATE_SOURCES: no invoice/header/line writes are permitted in this block.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='VALIDATE_SOURCES'
  ),
  member_values as materialized (
    select c.id chunk_id,c.operation_id,c.payload_json,
      m.value member,m.ordinality
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
          and jsonb_array_length(c.payload_json->'canonical_source_members')>0
        then c.payload_json->'canonical_source_members'
        else coalesce((
          select jsonb_agg(jsonb_build_object(
            'source_type','TIMESHEET','source_id',s.value,
            'related_timesheet_id',s.value) order by s.ordinality)
          from jsonb_array_elements_text(coalesce(
            c.payload_json->'canonical_source_ids',
            c.payload_json->'source_ids','[]'::jsonb))
            with ordinality s(value,ordinality)
        ),'[]'::jsonb) end) with ordinality m(value,ordinality)
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  members as materialized (
    select m.chunk_id,m.operation_id,m.payload_json,m.member,
      upper(coalesce(m.member->>'source_type','TIMESHEET')) source_type,
      case when coalesce(m.member->>'source_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(m.member->>'source_id')::uuid end source_id,
      case when coalesce(m.member->>'related_timesheet_id',
          m.member->>'source_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then coalesce(m.member->>'related_timesheet_id',
          m.member->>'source_id')::uuid end timesheet_id,
      nullif(btrim(m.member->>'segment_id'),'') segment_id,
      coalesce(nullif(btrim(m.member->>'source_member_key'),''),
        encode(digest(concat_ws('|',
          upper(coalesce(m.member->>'source_type','TIMESHEET')),
          coalesce(m.member->>'source_id',''),
          coalesce(m.member->>'related_timesheet_id',''),
          coalesce(m.member->>'segment_id','WHOLE'),
          coalesce(m.member->>'target_invoice_week','')),'sha256'),'hex'))
        source_member_key,
      nullif(btrim(coalesce(m.member->>'row_revision',
        m.member->>'source_revision','')),'') expected_revision,
      m.ordinality
    from member_values m
  ),
  reference_eval as materialized (
    select distinct on (r.source_member_key) r.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,'source_id',m.source_id,
        'related_timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'target_invoice_week',m.member->>'target_invoice_week',
        'invoice_stream',m.payload_json->>'invoice_stream',
        'consolidation_mode',m.payload_json->>'consolidation_mode',
        'source_revision',m.expected_revision)
        order by m.chunk_id,m.ordinality)
      from members m
    ),'[]'::jsonb)) r
    order by r.source_member_key
  ),
  vat_eval as materialized (
    select distinct on (v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,'source_id',m.source_id,
        'timesheet_id',m.timesheet_id,'segment_id',m.segment_id,
        'effective_date',coalesce(
          case when m.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                m.payload_json->>'effective_settings_date','date')
            then m.payload_json->>'effective_settings_date' end,
          (select ts_vat.week_ending_date::text
             from public.timesheets ts_vat
            where ts_vat.timesheet_id=m.timesheet_id
              and ts_vat.is_current
            limit 1)))
        order by m.chunk_id,m.ordinality)
      from members m
    ),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-validate:'||scope.chunk_id::text,
      'scope_key',scope.chunk_id::text,
      'validation_purpose','GENERATION_VALIDATE',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.chunk_id),'[]'::jsonb) scopes
    from(
      select m.chunk_id,min(m.payload_json::text)::jsonb payload_json,
        jsonb_agg(jsonb_build_object(
          'timesheet_id',m.timesheet_id,
          'source_type',m.source_type,
          'source_id',m.source_id,
          'source_member_key',m.source_member_key,
          'segment_id',m.segment_id,
          'target_invoice_week',m.payload_json->>'target_invoice_week',
          'vat_rate_pct',v.vat_rate)
          order by m.ordinality) planned_members
      from members m
      left join vat_eval v on v.source_member_key=m.source_member_key
      group by m.chunk_id
    ) scope
  ),
  correction_eval as materialized (
    select r.*
    from correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),  source_eval as materialized (
    select m.chunk_id,m.operation_id,m.timesheet_id,m.segment_id,
      m.source_member_key,m.ordinality,
      tf.id tsfin_id,
      encode(digest(concat_ws('|',tf.id::text,tf.timesheet_version::text,
        tf.updated_at::text,ts.version::text,ts.updated_at::text,
        coalesce(tf.invoice_breakdown_json::text,'')),'sha256'),'hex') row_revision,
      array_remove(array[
        case when ts.timesheet_id is null then 'TIMESHEET_NOT_FOUND' end,
        case when ts.timesheet_id is not null and (not ts.is_current or ts.revoked_at is not null) then 'TIMESHEET_NOT_CURRENT' end,
        case when tf.id is null then 'CURRENT_FINANCIALS_MISSING' end,
        case when tf.id is not null and tf.is_stale then 'FINANCIALS_STALE' end,
        case when tf.id is not null and tf.processing_status::text<>'READY_FOR_INVOICE' then 'NOT_READY_FOR_INVOICE' end,
        case when tf.id is not null and tf.has_rate_issue then 'RATE_MISSING' end,
        case when tf.id is not null and tf.has_pay_channel_issue then 'PAY_CHANNEL_MISSING' end,
        case when tf.id is not null and tf.client_id is null then 'CLIENT_UNRESOLVED' end,
        case when tf.id is not null and tf.locked_by_invoice_id is not null then 'SOURCE_ALREADY_LOCKED' end,
        case when ts.authorised_at_server is null
          then 'TIMESHEET_NOT_AUTHORISED' end,
        case when upper(coalesce(ts.submission_mode::text,''))='QR'
          and(nullif(ts.qr_signed_hash,'') is null
            or ts.qr_signed_at_utc is null)
          then 'QR_TIMESHEET_UNSIGNED' end,
        case when pc.require_reference_to_invoice
          and coalesce(ref.reference_ready,false) is not true
          then coalesce(ref.blocker_code,'MISSING_REFERENCE') end,
        case when coalesce(tf.mileage_pay_ex_vat,0)<>0
            or coalesce(tf.mileage_charge_ex_vat,0)<>0
          then case when not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and nullif(e.storage_key,'') is not null)
            then 'MISSING_MILEAGE_EVIDENCE' end end,
        case when(coalesce(tf.mileage_pay_ex_vat,0)<>0
            or coalesce(tf.mileage_charge_ex_vat,0)<>0)
          and exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and nullif(e.storage_key,'') is not null
              and e.document_asset_id is null)
          then 'MILEAGE_ASSET_NOT_REGISTERED' end,
        case when coalesce(tf.expenses_pay_ex_vat,0)<>0
            or coalesce(tf.expenses_charge_ex_vat,0)<>0
            or coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0
            or coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0
          then case when not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null)
            then 'MISSING_EXPENSE_EVIDENCE' end end,
        case when(
            coalesce(tf.expenses_pay_ex_vat,0)<>0
            or coalesce(tf.expenses_charge_ex_vat,0)<>0
            or coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0
            or coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null
              and e.document_asset_id is null)
          then 'EXPENSE_ASSET_NOT_REGISTERED' end,
        case when(coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='TRAVEL'
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_TRAVEL_EVIDENCE' end,
        case when(coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='ACCOMMODATION'
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_ACCOMMODATION_EVIDENCE' end,
        case when(coalesce(tf.other_pay_ex_vat,0)<>0
            or coalesce(tf.other_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_OTHER_EXPENSE_EVIDENCE' end,
        case when exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
            where e.timesheet_id=m.timesheet_id
              and a.status in(
                'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED'))
          then 'REQUIRED_ASSET_PERMANENT_FAILURE' end,
        case when coalesce(vat.valid,false) is not true
          then coalesce(vat.blocker_code,'VAT_POLICY_UNRESOLVED') end,
        case when corr.valid is false
          then coalesce(corr.blocker_code,'CORRECTION_VALIDATION_FAILED') end,
        case when coalesce(vs.hr_validation_required_for_invoice,false)
          and upper(coalesce(tf.hr_crosscheck_status,'')) not in(
            'OK','PASS','PASSED','MATCHED','NOT_REQUIRED')
          then 'HEALTHROSTER_VALIDATION_REQUIRED' end,
        case when coalesce(vs.client_is_nhsp,false)
          and coalesce(vs.nhsp_shift_count,0)>0
          and not exists(
            select 1
            from public.nhsp_shifts ns_ready
            where ns_ready.timesheet_id=m.timesheet_id
              and ns_ready.invoice_status='PENDING'
              and ns_ready.invoice_id is null
              and ns_ready.cancelled_at_utc is null)
          then 'NHSP_SOURCE_NOT_READY' end,
        case when exists(select 1 from public.invoice_lines l join public.invoices i on i.id=l.invoice_id
                         where l.timesheet_id=m.timesheet_id and i.status in ('DRAFT','ISSUED','ON_HOLD'))
             and coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS' then 'SOURCE_ALREADY_INVOICED' end
      ],null)::text[] blockers
    from members m
    left join public.timesheets ts on ts.timesheet_id=m.timesheet_id
    left join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=m.timesheet_id
    left join public.v_timesheets_summary_base vs
      on vs.timesheet_id=m.timesheet_id
    left join reference_eval ref on ref.source_member_key=m.source_member_key
    left join vat_eval vat on vat.source_member_key=m.source_member_key
    left join correction_eval corr
      on corr.scope_key=m.chunk_id::text
  ),
  resolver_inputs as materialized (
    select c.id chunk_id,c.payload_json,
      row_number() over(order by c.id)::integer command_no
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  canonical_now as materialized (
    select ri.chunk_id,r.group_key,r.source_revision_hash,
      r.blocker_code,r.blocker_detail
    from private._invoice_generation_resolve_command_groups(
      (select coalesce(jsonb_agg(ri.payload_json order by ri.command_no),
        '[]'::jsonb) from resolver_inputs ri),null,v_now) r
    join resolver_inputs ri on ri.command_no=r.command_no
    where r.group_key=case
      when left(coalesce(ri.payload_json->>'selection_key',''),9)='generate:'
        then substr(ri.payload_json->>'selection_key',10)
      else ri.payload_json->>'group_key' end
  ),
  per_chunk as materialized (
    select c.id chunk_id,
      n.source_revision_hash current_revision,
      coalesce(jsonb_agg(jsonb_build_object('source_id',se.timesheet_id,
        'segment_id',se.segment_id,
        'codes',to_jsonb(se.blockers)) order by se.ordinality)
        filter(where cardinality(se.blockers)>0),'[]'::jsonb)
        ||case when n.blocker_code is null then '[]'::jsonb
          else jsonb_build_array(coalesce(n.blocker_detail,
            jsonb_build_object('code',n.blocker_code))) end blockers,
      count(se.timesheet_id)::integer source_count
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join source_eval se on se.chunk_id=c.id
    left join canonical_now n on n.chunk_id=c.id
    group by c.id,n.source_revision_hash,n.blocker_code,n.blocker_detail
  ),
  updated as (
    update public.invoice_operation_chunks c
    set phase=case
          when p.source_count=0 then 'BLOCKED'
          when jsonb_array_length(p.blockers)>0 then 'BLOCKED'
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then 'SUPERSEDED'
          else 'PLAN' end,
        status=case
          when p.source_count=0 or jsonb_array_length(p.blockers)>0 then 'BLOCKED'
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then 'SUPERSEDED'
          else 'QUEUED' end,
        payload_json=c.payload_json||jsonb_build_object('source_revision',p.current_revision,'source_count',p.source_count),
        progress_json=jsonb_build_object('status_message',
          case when p.source_count=0 then 'No sources resolved'
               when jsonb_array_length(p.blockers)>0 then 'Source validation blocked'
               when nullif(c.payload_json->>'source_revision','') is not null
                and c.payload_json->>'source_revision'<>p.current_revision then 'Source changed'
               else 'Sources validated' end,'source_count',p.source_count),
        error_json=case
          when p.source_count=0 then jsonb_build_object('code','NO_SOURCES','sources','[]'::jsonb)
          when jsonb_array_length(p.blockers)>0 then jsonb_build_object('code','SOURCE_VALIDATION_BLOCKED','sources',p.blockers)
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then jsonb_build_object('code','SOURCE_CHANGED')
          else null end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from per_chunk p where c.id=p.chunk_id
    returning c.id,c.operation_id,c.status,c.phase,c.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]'::jsonb)
  into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Credit-note validation is deliberately separate from normal timesheet sources.
  with claim_ids as (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='VALIDATE_SOURCES'
  ),
  credit_eval as (
    select c.id chunk_id,i.id invoice_id,
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),'sha256'),'hex') revision,
      case when i.id is null then 'INVOICE_NOT_FOUND'
           when i.type::text<>'INVOICE' then 'CREDIT_SOURCE_NOT_INVOICE'
           when i.status::text not in ('ISSUED','PAID') then 'CREDIT_SOURCE_NOT_ISSUED'
           when exists(select 1 from public.invoices cn where cn.original_invoice_id=i.id and cn.type='CREDIT_NOTE'
                       and cn.status in('DRAFT','ISSUED','PAID')) then 'CREDIT_ALREADY_EXISTS'
           else null end blocker
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join public.invoices i on i.id=c.entity_id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
  ),
  updated as (
    update public.invoice_operation_chunks c
    set phase=case when e.blocker is null then 'PLAN' else 'BLOCKED' end,
        status=case when e.blocker is null then 'QUEUED' else 'BLOCKED' end,
        payload_json=c.payload_json||jsonb_build_object('source_revision',e.revision,'source_invoice_id',e.invoice_id),
        progress_json=jsonb_build_object('status_message',case when e.blocker is null then 'Credit source validated' else 'Credit source blocked' end),
        error_json=case when e.blocker is null then null else jsonb_build_object('code',e.blocker,'invoice_id',c.entity_id) end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from credit_eval e where c.id=e.chunk_id
    returning c.id,c.status,c.phase,c.error_json
  )
  select v_result||coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]'::jsonb)
  into v_result from updated;

  -- PLAN: compact financial/settings summary only; no complete line arrays.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='PLAN'
  ),
  members as materialized (
    select c.id chunk_id,c.payload_json,
      case when pg_input_is_valid(s.value,'uuid')
        then s.value::uuid end timesheet_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    cross join lateral jsonb_array_elements_text(coalesce(
      c.payload_json->'canonical_source_ids',c.payload_json->'source_ids','[]'::jsonb)) s(value)
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
      and pg_input_is_valid(s.value,'uuid')
  ),
  values_by_chunk as materialized (
    select m.chunk_id,count(*)::integer source_count,
      round(sum(coalesce(tf.total_pay_ex_vat,0)),2) expected_pay_ex_vat,
      round(sum(coalesce(tf.total_charge_ex_vat,0)),2) expected_charge_ex_vat,
      (array_agg(tf.client_id order by tf.client_id))[1] client_id,
      jsonb_build_object(
        'client_id',(array_agg(tf.client_id order by tf.client_id))[1],'consolidation_mode',max(c.payload_json->>'consolidation_mode'),
        'stream',max(c.payload_json->>'invoice_stream'),
        'invoice_week_start',max(c.payload_json->>'target_invoice_week'),
        'client',jsonb_build_object('name',max(cl.name),'vat_chargeable',bool_and(cl.vat_chargeable),
          'payment_terms_days',max(cl.payment_terms_days),'primary_invoice_email',max(cl.primary_invoice_email)),
        'attach_policy',jsonb_build_object(
          'hr_attach_to_invoice',coalesce(bool_or(cs.hr_attach_to_invoice),bool_or(sd.hr_attach_to_invoice),true),
          'ts_attach_to_invoice',coalesce(bool_or(cs.ts_attach_to_invoice),bool_or(sd.ts_attach_to_invoice),true),
          'requires_hr',coalesce(bool_or(cs.requires_hr),false))
      ) settings_snapshot
    from members m join public.invoice_operation_chunks c on c.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.clients cl on cl.id=tf.client_id
    left join lateral (
      select s.* from public.client_settings s where s.client_id=tf.client_id
       and (s.effective_from is null or s.effective_from<=coalesce(
      case when c.payload_json->>'effective_settings_date' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
          and pg_input_is_valid(c.payload_json->>'effective_settings_date','date')
           then (c.payload_json->>'effective_settings_date')::date end,
         (v_now at time zone 'Europe/London')::date))
      order by s.effective_from desc nulls last,s.updated_at desc nulls last,
        s.created_at desc nulls last,s.id desc
      limit 1
    ) cs on true
    cross join public.settings_defaults sd
    where sd.id=1
    group by m.chunk_id
  ),
  plans as materialized (
    select c.id chunk_id,coalesce(
      case when pg_input_is_valid(
        nullif(c.payload_json->>'planned_invoice_id',''),'uuid')
        then(c.payload_json->>'planned_invoice_id')::uuid end,
      case when c.payload_json->>'consolidation_mode' in ('BY_WEEK','ANY_WEEK') then (
        select i.id from public.invoices i
        where i.client_id=v.client_id and i.status='DRAFT' and i.type='INVOICE'
          and coalesce(i.header_snapshot_json#>>'{meta,consolidation_mode}','NONE')=c.payload_json->>'consolidation_mode'
          and coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false')=
              case when c.payload_json->>'invoice_stream'='SELF_BILL' then 'true' else 'false' end
          and (c.payload_json->>'consolidation_mode'='ANY_WEEK'
               or i.header_snapshot_json#>>'{meta,invoice_week_start}'=c.payload_json->>'target_invoice_week')
        order by i.created_at desc limit 1
      ) end,gen_random_uuid()) planned_invoice_id,
      v.source_count,v.expected_charge_ex_vat,v.expected_pay_ex_vat,v.client_id,
      v.settings_snapshot,encode(digest(v.settings_snapshot::text,'sha256'),'hex') settings_hash
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join values_by_chunk v on v.chunk_id=c.id
  ),
  credit_plans as materialized (
    select c.id chunk_id,gen_random_uuid() planned_invoice_id,1 source_count,
      -i.subtotal_ex_vat expected_charge_ex_vat,-coalesce(sum(l.total_pay_ex_vat),0) expected_pay_ex_vat,
      i.client_id,jsonb_build_object('source_invoice_id',i.id,'source_invoice_no',i.invoice_no,
        'client_id',i.client_id,'credit_note',true) settings_snapshot,
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text),'sha256'),'hex') settings_hash
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i on i.id=c.entity_id
    left join public.invoice_lines l on l.invoice_id=i.id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
    group by c.id,i.id
  ),
  all_plans as materialized (select * from plans union all select * from credit_plans),
  updated as (
    update public.invoice_operation_chunks c
    set phase='COMMIT',status='QUEUED',
      payload_json=c.payload_json||jsonb_build_object('plan',jsonb_build_object(
        'planned_invoice_id',p.planned_invoice_id,'intended_invoice_count',1,
        'source_count',p.source_count,'expected_pay_ex_vat',p.expected_pay_ex_vat,
        'expected_charge_ex_vat',p.expected_charge_ex_vat,'settings_snapshot',p.settings_snapshot,
        'settings_hash',p.settings_hash,'source_revision',c.payload_json->>'source_revision')),
      progress_json=jsonb_build_object('status_message','Generation plan ready','source_count',p.source_count),
      error_json=null,lease_owner=null,lease_token=null,
      lease_expires_at_utc=null,updated_at_utc=v_now
    from all_plans p where c.id=p.chunk_id
    returning c.id,c.status,c.phase,c.payload_json->'plan' plan
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'plan',plan)),'[]'::jsonb)
    into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- COMMIT: revalidate immediately, then headers, lines, locks, documents and audit set-wise.
  with recursive claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='COMMIT'
  ),
  normal_chunks as materialized (
    select c.*,case when pg_input_is_valid(
        c.payload_json#>>'{plan,planned_invoice_id}','uuid')
      then(c.payload_json#>>'{plan,planned_invoice_id}')::uuid end planned_invoice_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  members as materialized (
    select c.id chunk_id,c.operation_id,c.planned_invoice_id,c.payload_json,
      upper(coalesce(s.value->>'source_type','TIMESHEET')) source_type,
      case when pg_input_is_valid(s.value->>'source_id','uuid')
        then(s.value->>'source_id')::uuid end source_id,
      case when pg_input_is_valid(coalesce(
          s.value->>'related_timesheet_id',s.value->>'source_id'),'uuid')
        then coalesce(s.value->>'related_timesheet_id',
          s.value->>'source_id')::uuid end timesheet_id,
      nullif(btrim(s.value->>'segment_id'),'') segment_id,
      coalesce(nullif(btrim(s.value->>'source_member_key'),''),
        encode(digest(concat_ws('|',
          upper(coalesce(s.value->>'source_type','TIMESHEET')),
          coalesce(s.value->>'source_id',''),
          coalesce(s.value->>'related_timesheet_id',''),
          coalesce(s.value->>'segment_id','WHOLE'),
          coalesce(s.value->>'target_invoice_week','')),'sha256'),'hex'))
        source_member_key
    from normal_chunks c
    cross join lateral jsonb_array_elements(case
      when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
        and jsonb_array_length(c.payload_json->'canonical_source_members')>0
      then c.payload_json->'canonical_source_members'
      else coalesce((
        select jsonb_agg(jsonb_build_object(
          'source_type','TIMESHEET','source_id',ids.value,
          'related_timesheet_id',ids.value) order by ids.ordinality)
        from jsonb_array_elements_text(coalesce(
          c.payload_json->'canonical_source_ids',
          c.payload_json->'source_ids','[]'::jsonb))
          with ordinality ids(value,ordinality)
      ),'[]'::jsonb) end) s(value)
    where pg_input_is_valid(coalesce(
      s.value->>'related_timesheet_id',s.value->>'source_id'),'uuid')
  ),
  selected_segments as materialized (
    select c.id chunk_id,
      (m.value->>'source_id')::uuid timesheet_id,
      array_agg(distinct m.value->>'segment_id'
        order by m.value->>'segment_id')
        filter(where nullif(m.value->>'segment_id','') is not null) segment_ids
    from normal_chunks c
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
        then c.payload_json->'canonical_source_members' else '[]'::jsonb end)
      m(value)
    where coalesce(m.value->>'source_id','')~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    group by c.id,(m.value->>'source_id')::uuid
  ),
  commit_reference_eval as materialized (
    select distinct on(r.source_member_key) r.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,
        'source_id',m.source_id,
        'related_timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'target_invoice_week',m.payload_json->>'target_invoice_week',
        'invoice_stream',m.payload_json->>'invoice_stream',
        'consolidation_mode',m.payload_json->>'consolidation_mode')
        order by m.chunk_id,m.source_member_key)
      from members m),'[]'::jsonb)) r
    order by r.source_member_key
  ),
  commit_vat_eval as materialized (
    select distinct on(v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,
        'source_id',m.source_id,
        'timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'effective_date',coalesce(
          case when m.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                m.payload_json->>'effective_settings_date','date')
            then m.payload_json->>'effective_settings_date' end,
          (select ts_vat.week_ending_date::text
             from public.timesheets ts_vat
            where ts_vat.timesheet_id=m.timesheet_id
              and ts_vat.is_current
            limit 1)))
        order by m.chunk_id,m.source_member_key)
      from members m),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  commit_correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-commit:'||scope.planned_invoice_id::text,
      'scope_key',scope.planned_invoice_id::text,
      'invoice_id',case when exists(select 1 from public.invoices existing
        where existing.id=scope.planned_invoice_id)
        then scope.planned_invoice_id end,
      'validation_purpose','GENERATION_COMMIT',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.planned_invoice_id),'[]'::jsonb) scopes
    from(
      select m.planned_invoice_id,min(m.payload_json::text)::jsonb payload_json,
        jsonb_agg(jsonb_build_object(
          'timesheet_id',m.timesheet_id,
          'source_type',m.source_type,
          'source_id',m.source_id,
          'source_member_key',m.source_member_key,
          'segment_id',m.segment_id,
          'target_invoice_week',m.payload_json->>'target_invoice_week',
          'vat_rate_pct',v.vat_rate)
          order by m.source_member_key) planned_members
      from members m
      left join commit_vat_eval v
        on v.source_member_key=m.source_member_key
      group by m.planned_invoice_id
    ) scope
  ),
  commit_correction_eval as materialized (
    select r.*
    from commit_correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),  source_still_valid as materialized (
    select m.chunk_id,
      bool_and(tf.processing_status='READY_FOR_INVOICE' and not tf.is_stale
        and (tf.locked_by_invoice_id is null
          or coalesce(tf.invoice_breakdown_json->>'mode','')='SEGMENTS')
        and ts.authorised_at_server is not null
        and not(upper(coalesce(ts.submission_mode::text,''))='QR'
          and(nullif(ts.qr_signed_hash,'') is null
            or ts.qr_signed_at_utc is null))
        and(not coalesce(pc.require_reference_to_invoice,false)
          or coalesce(ref.reference_ready,false))
        and coalesce(vat.valid,false)
        and coalesce(corr.valid,true)
        and not(coalesce(vs.hr_validation_required_for_invoice,false)
          and upper(coalesce(tf.hr_crosscheck_status,'')) not in(
            'OK','PASS','PASSED','MATCHED','NOT_REQUIRED'))
        and not(coalesce(vs.client_is_nhsp,false)
          and coalesce(vs.nhsp_shift_count,0)>0
          and not exists(
            select 1
            from public.nhsp_shifts ns_ready
            where ns_ready.timesheet_id=m.timesheet_id
              and ns_ready.invoice_status='PENDING'
              and ns_ready.invoice_id is null
              and ns_ready.cancelled_at_utc is null))
        and not((coalesce(tf.mileage_pay_ex_vat,0)<>0
              or coalesce(tf.mileage_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.travel_pay_ex_vat,0)<>0
              or coalesce(tf.travel_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='TRAVEL'
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.accommodation_pay_ex_vat,0)<>0
              or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='ACCOMMODATION'
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.expenses_pay_ex_vat,0)<>0
              or coalesce(tf.expenses_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.other_pay_ex_vat,0)<>0
              or coalesce(tf.other_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and nullif(e.storage_key,'') is not null))
        and not exists(
          select 1
          from public.timesheet_evidence e
          left join public.invoice_document_assets a
            on a.id=e.document_asset_id
          where e.timesheet_id=m.timesheet_id
            and(
              (upper(coalesce(e.kind,''))='MILEAGE'
                and(coalesce(tf.mileage_pay_ex_vat,0)<>0
                  or coalesce(tf.mileage_charge_ex_vat,0)<>0))
              or(upper(coalesce(e.kind,'')) in(
                  'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
                and(coalesce(tf.expenses_pay_ex_vat,0)<>0
                  or coalesce(tf.expenses_charge_ex_vat,0)<>0
                  or coalesce(tf.travel_pay_ex_vat,0)<>0
                  or coalesce(tf.travel_charge_ex_vat,0)<>0
                  or coalesce(tf.accommodation_pay_ex_vat,0)<>0
                  or coalesce(tf.accommodation_charge_ex_vat,0)<>0)))
            and(e.document_asset_id is null
              or a.status in('UNSUPPORTED','CORRUPT','MISSING',
                'FAILED','SUPERSEDED')))
        and not exists(
          select 1
          from public.invoice_lines l
          join public.invoices existing on existing.id=l.invoice_id
          where l.timesheet_id=m.timesheet_id
            and existing.id<>m.planned_invoice_id
            and existing.status in('DRAFT','ISSUED','ON_HOLD')
            and coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS')
      ) still_valid
    from members m join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current and ts.revoked_at is null
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=m.timesheet_id
    left join public.v_timesheets_summary_base vs
      on vs.timesheet_id=m.timesheet_id
    left join commit_reference_eval ref
      on ref.source_member_key=m.source_member_key
    left join commit_vat_eval vat
      on vat.source_member_key=m.source_member_key
    left join commit_correction_eval corr
      on corr.scope_key=m.planned_invoice_id::text
    group by m.chunk_id
  ),
  commit_resolver_inputs as materialized (
    select c.id chunk_id,c.payload_json,
      row_number() over(order by c.id)::integer command_no
    from normal_chunks c
  ),
  commit_resolver_results as materialized (
    select ri.chunk_id,r.source_revision_hash,r.blocker_code
    from private._invoice_generation_resolve_command_groups(
      (select coalesce(jsonb_agg(ri.payload_json order by ri.command_no),
        '[]'::jsonb) from commit_resolver_inputs ri),null,v_now) r
    join commit_resolver_inputs ri on ri.command_no=r.command_no
    where r.group_key=case
      when left(coalesce(ri.payload_json->>'selection_key',''),9)='generate:'
        then substr(ri.payload_json->>'selection_key',10)
      else ri.payload_json->>'group_key' end
  ),
  revision_check as materialized (
    select c.id chunk_id,r.source_revision_hash current_revision,
      s.still_valid and r.blocker_code is null still_valid
    from normal_chunks c
    join source_still_valid s on s.chunk_id=c.id
    join commit_resolver_results r on r.chunk_id=c.id
  ),
  rejected as (
    update public.invoice_operation_chunks c
    set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code','SOURCE_CHANGED_BEFORE_COMMIT'),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from revision_check r
    where c.id=r.chunk_id and (not r.still_valid or r.current_revision<>c.payload_json->>'source_revision')
    returning c.id
  ),
  valid_chunks as materialized (
    select c.* from normal_chunks c join revision_check r on r.chunk_id=c.id
    where r.still_valid and r.current_revision=c.payload_json->>'source_revision'
      and not exists(select 1 from rejected x where x.id=c.id)
  ),
  header_source as materialized (
    select vc.id chunk_id,vc.planned_invoice_id,(array_agg(tf.client_id order by tf.client_id))[1] client_id,
      max(cl.name) client_name,max(cl.invoice_address) client_invoice_address,
      max(cl.primary_invoice_email) primary_invoice_email,bool_and(cl.vat_chargeable) vat_chargeable,
      max(cl.payment_terms_days) payment_terms_days,
      max(sd.agency_name) agency_name,max(sd.agency_logo) agency_logo,
      max(sd.registered_address) registered_address,max(sd.company_reg_number) company_reg_number,
      max(sd.bank_name) bank_name,max(sd.bank_sort_code) bank_sort_code,
      max(sd.bank_account_number) bank_account_number,max(sd.vat_registration_number) vat_registration_number,
      count(*)::integer source_count
    from valid_chunks vc join members m on m.chunk_id=vc.id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.clients cl on cl.id=tf.client_id cross join public.settings_defaults sd
    where sd.id=1 group by vc.id,vc.planned_invoice_id
  ),
  source_rows_base as materialized (
    select m.chunk_id,m.planned_invoice_id,m.payload_json,
      m.source_member_key,m.source_type,m.source_id,m.segment_id,tf.*,ts.booking_id,
      ts.week_ending_date,ts.reference_number,ts.sheet_scope,ts.submission_mode,ts.day_references_json,
      ts.actual_schedule_json,coalesce(ts.contract_id,cw.contract_id) contract_id,
      coalesce(cd.display_name,'Candidate '||left(coalesce(tf.candidate_id::text,m.timesheet_id::text),8)) candidate_display,
      coalesce(ct.daily_calc_of_invoices,false) daily_calc_of_invoices,
      coalesce(ct.bucket_labels_json,
        jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH'))
        bucket_labels_json,
      ct.role contract_role,ct.display_site contract_display_site,
      ct.ward_hint contract_ward_hint,
      null::numeric ordinary_vat_rate,
      case when ts.sheet_scope::text='WEEKLY'
          and ts.submission_mode::text='MANUAL'
          and jsonb_typeof(ts.actual_schedule_json)='array'
        then coalesce((
          select jsonb_agg(jsonb_build_object(
            'date',e.value->>'date','start',e.value->>'start',
            'end',e.value->>'end','start_utc',e.value->>'start_utc',
            'end_utc',e.value->>'end_utc','ref_num',e.value->>'ref_num')
            order by e.ordinality)
          from jsonb_array_elements(ts.actual_schedule_json)
            with ordinality e(value,ordinality)
          where nullif(btrim(e.value->>'start'),'') is not null
            and nullif(btrim(e.value->>'end'),'') is not null
        ),'[]'::jsonb)
        else '[]'::jsonb end schedule_refs
    from members m join valid_chunks vc on vc.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current
    left join lateral (
      select w.contract_id
      from public.contract_weeks w
      where w.timesheet_id=m.timesheet_id
      order by w.updated_at desc nulls last,w.created_at desc nulls last,w.id desc
      limit 1
    ) cw on true
    left join public.contracts ct on ct.id=coalesce(ts.contract_id,cw.contract_id)
    left join public.candidates cd on cd.id=tf.candidate_id
  ),
  vat_policy as materialized (
    select distinct on (v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',s.source_member_key,
        'source_type',s.source_type,'source_id',s.source_id,
        'timesheet_id',s.timesheet_id,'segment_id',s.segment_id,
        'ordinary_rate',s.ordinary_vat_rate,
        'effective_date',coalesce(
          case when s.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                s.payload_json->>'effective_settings_date','date')
            then(s.payload_json->>'effective_settings_date')::date end,
          s.week_ending_date::date))
        order by s.chunk_id,s.timesheet_id)
      from source_rows_base s
    ),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  source_rows as materialized (
    select s.*,v.vat_rate
    from source_rows_base s
    join vat_policy v on v.source_member_key=s.source_member_key and v.valid
  ),
  source_timesheet_ancestry(
    planned_invoice_id,
    root_timesheet_id,
    source_timesheet_id,
    ancestry_path,
    ancestry_depth
  ) as materialized (
    select distinct s.planned_invoice_id,s.timesheet_id,s.timesheet_id,
      array[s.timesheet_id]::uuid[],0
    from source_rows s
    union all
    select a.planned_invoice_id,a.root_timesheet_id,t.parent_timesheet_id,
      a.ancestry_path||t.parent_timesheet_id,a.ancestry_depth+1
    from source_timesheet_ancestry a
    join public.timesheets t
      on t.timesheet_id=a.source_timesheet_id
     and t.is_current
    where t.parent_timesheet_id is not null
      and not(t.parent_timesheet_id=any(a.ancestry_path))
      and a.ancestry_depth<32
  ),
  adjustment_segment_refs as materialized (
    select distinct s.planned_invoice_id,s.timesheet_id root_timesheet_id,
      coalesce(
        (s.payload_json#>>'{plan,settings_snapshot,attach_policy,hr_attach_to_invoice}')::boolean,
        true
      ) healthroster_attach_allowed,
      nullif(btrim(seg.value->>'ref_num'),'') ref_num,
      case when pg_input_is_valid(
          seg.value->>'start_utc','timestamp with time zone')
        then(seg.value->>'start_utc')::timestamptz end start_utc,
      case when pg_input_is_valid(
          seg.value->>'end_utc','timestamp with time zone')
        then(seg.value->>'end_utc')::timestamptz end end_utc,
      lower(coalesce(seg.value->>'is_reversal','false')) in(
        'true','t','1','yes') is_reversal
    from source_rows s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)
      seg(value)
    where s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
  ),
  segment_lock_targets_pre as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'invoice_id',s.planned_invoice_id,
      'timesheet_id',s.timesheet_id,
      'segment_ids',to_jsonb(p.segment_ids),
      'expected_financial_revision',encode(digest(jsonb_build_object(
        'financial_id',s.id,
        'timesheet_version',s.timesheet_version,
        'updated_at',s.updated_at,
        'basis',s.basis,
        'invoice_breakdown_json',s.invoice_breakdown_json
      )::text,'sha256'),'hex'))
      order by s.planned_invoice_id,s.timesheet_id),'[]'::jsonb) targets
    from source_rows s
    join selected_segments p
      on p.chunk_id=s.chunk_id and p.timesheet_id=s.timesheet_id
    where cardinality(coalesce(p.segment_ids,array[]::text[]))>0
      and exists(
        select 1
        from public.invoices existing_header
        where existing_header.id=s.planned_invoice_id)
  ),
  segment_lock_authority_pre as materialized (
    select r.*
    from segment_lock_targets_pre t
    cross join lateral private._invoice_segment_lock_batch(t.targets,v_now) r
  ),
  segment_lock_failures_pre as materialized (
    select * from segment_lock_authority_pre where not success
  ),
  segment_entries as materialized (
    select s.*,seg.ordinality,
      coalesce(nullif(seg.value->>'segment_id',''),
        left(encode(digest(seg.value::text,'sha256'),'hex'),24)) segment_id,
      case when left(coalesce(seg.value->>'date',''),10)
        ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        then left(seg.value->>'date',10) end work_date,
      case when coalesce(seg.value->>'hours_day','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_day')::numeric
        else 0 end segment_hours_day,
      case when coalesce(seg.value->>'hours_night','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_night')::numeric
        else 0 end segment_hours_night,
      case when coalesce(seg.value->>'hours_sat','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_sat')::numeric
        else 0 end segment_hours_sat,
      case when coalesce(seg.value->>'hours_sun','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_sun')::numeric
        else 0 end segment_hours_sun,
      case when coalesce(seg.value->>'hours_bh','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_bh')::numeric
        else 0 end segment_hours_bh,
      case
        when coalesce(seg.value->>'pay_amount','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'pay_amount')::numeric
        when coalesce(seg.value->>'pay_ex_vat','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'pay_ex_vat')::numeric
        else 0 end segment_pay_ex,
      case
        when coalesce(seg.value->>'charge_amount','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'charge_amount')::numeric
        when coalesce(seg.value->>'charge_ex_vat','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'charge_ex_vat')::numeric
        else 0 end segment_charge_ex
    from source_rows s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)
      with ordinality seg(value,ordinality)
    where upper(coalesce(s.invoice_breakdown_json->>'mode',''))='SEGMENTS'
      and nullif(seg.value->>'invoice_locked_invoice_id','') is null
      and exists(
        select 1 from selected_segments picked
        where picked.chunk_id=s.chunk_id
          and picked.timesheet_id=s.timesheet_id
          and coalesce(nullif(seg.value->>'segment_id',''),
            left(encode(digest(seg.value::text,'sha256'),'hex'),24))
            =any(coalesce(picked.segment_ids,array[]::text[])))
  ),
  segment_daily_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,s.work_date,
      sum(s.segment_hours_day) h_day,sum(s.segment_hours_night) h_night,
      sum(s.segment_hours_sat) h_sat,sum(s.segment_hours_sun) h_sun,
      sum(s.segment_hours_bh) h_bh,sum(s.segment_pay_ex) pay_ex,
      sum(s.segment_charge_ex) charge_ex,max(s.vat_rate) vat_rate,
      max(s.charge_day) charge_day,max(s.charge_night) charge_night,
      max(s.charge_sat) charge_sat,max(s.charge_sun) charge_sun,
      max(s.charge_bh) charge_bh,
      max(s.timesheet_version) timesheet_version,
      (array_agg(s.id order by s.id))[1] tsfin_id,
      max(s.contract_role) contract_role,
      max(s.contract_display_site) contract_display_site,
      max(s.contract_ward_hint) contract_ward_hint,
      (array_agg(s.bucket_labels_json order by s.ordinality))[1]
        bucket_labels_json
    from segment_entries s
    where s.daily_calc_of_invoices and s.work_date is not null
    group by s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,s.work_date
  ),
  segment_weekly_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,
      sum(s.segment_hours_day) h_day,sum(s.segment_hours_night) h_night,
      sum(s.segment_hours_sat) h_sat,sum(s.segment_hours_sun) h_sun,
      sum(s.segment_hours_bh) h_bh,sum(s.segment_pay_ex) pay_ex,
      sum(s.segment_charge_ex) charge_ex,max(s.vat_rate) vat_rate,
      max(s.charge_day) charge_day,max(s.charge_night) charge_night,
      max(s.charge_sat) charge_sat,max(s.charge_sun) charge_sun,
      max(s.charge_bh) charge_bh,
      max(s.timesheet_version) timesheet_version,
      (array_agg(s.id order by s.id))[1] tsfin_id,
      max(s.contract_role) contract_role,
      max(s.contract_display_site) contract_display_site,
      max(s.contract_ward_hint) contract_ward_hint,
      (array_agg(s.bucket_labels_json order by s.ordinality))[1]
        bucket_labels_json
    from segment_entries s
    where not s.daily_calc_of_invoices
       or not exists(select 1 from segment_entries d
         where d.chunk_id=s.chunk_id and d.timesheet_id=s.timesheet_id
           and d.daily_calc_of_invoices and d.work_date is not null)
    group by s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date
  ),
  nonsegment_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      coalesce(s.hours_day,0) h_day,coalesce(s.hours_night,0) h_night,coalesce(s.hours_sat,0) h_sat,
      coalesce(s.hours_sun,0) h_sun,coalesce(s.hours_bh,0) h_bh,
      round(coalesce(s.total_pay_ex_vat,0)-coalesce(s.additional_pay_ex_vat,0)
        -coalesce(s.expenses_pay_ex_vat,0)-coalesce(s.mileage_pay_ex_vat,0),2) pay_ex,
      round(coalesce(s.total_charge_ex_vat,0)-coalesce(s.additional_charge_ex_vat,0)
        -coalesce(s.expenses_charge_ex_vat,0)-coalesce(s.mileage_charge_ex_vat,0),2) charge_ex,
      s.vat_rate,s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,
      s.charge_bh,s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    where upper(coalesce(s.invoice_breakdown_json->>'mode',''))<>'SEGMENTS'
       or jsonb_array_length(case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
                                  then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)=0
  ),
  additional_daily_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,upper(a.key) code,
      left(d.key,10) work_date,
      case when pg_input_is_valid(d.value,'numeric')
        then d.value::numeric else 0 end units,
      case when pg_input_is_valid(a.value->>'pay_rate','numeric')
        then(a.value->>'pay_rate')::numeric else 0 end pay_rate,
      case when pg_input_is_valid(a.value->>'charge_rate','numeric')
        then(a.value->>'charge_rate')::numeric else 0 end charge_rate,
      round((case when pg_input_is_valid(d.value,'numeric')
          then d.value::numeric else 0 end)*
        (case when pg_input_is_valid(a.value->>'pay_rate','numeric')
          then(a.value->>'pay_rate')::numeric else 0 end),2) pay_ex,
      round((case when pg_input_is_valid(d.value,'numeric')
          then d.value::numeric else 0 end)*
        (case when pg_input_is_valid(a.value->>'charge_rate','numeric')
          then(a.value->>'charge_rate')::numeric else 0 end),2) charge_ex,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) bucket_name,
      coalesce(nullif(a.value->>'unit_name',''),'units') unit_name,
      a.value->'frequency' frequency,s.vat_rate,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    cross join lateral jsonb_each(
      case when jsonb_typeof(s.additional_units_json)='object'
        then s.additional_units_json else '{}'::jsonb end) a
    cross join lateral jsonb_each_text(
      case when jsonb_typeof(a.value->'days')='object'
        then a.value->'days' else '{}'::jsonb end) d
    where s.daily_calc_of_invoices
      and left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      and exists(select 1 from segment_entries se
        where se.chunk_id=s.chunk_id and se.timesheet_id=s.timesheet_id
          and se.work_date is not null)
  ),
  additional_weekly_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      upper(a.key) code,
      case when pg_input_is_valid(a.value->>'unit_count','numeric')
        then(a.value->>'unit_count')::numeric else 0 end units,
      case when pg_input_is_valid(a.value->>'pay_rate','numeric')
        then(a.value->>'pay_rate')::numeric else 0 end pay_rate,
      case when pg_input_is_valid(a.value->>'charge_rate','numeric')
        then(a.value->>'charge_rate')::numeric else 0 end charge_rate,
      case when pg_input_is_valid(a.value->>'pay_ex_vat','numeric')
        then(a.value->>'pay_ex_vat')::numeric else 0 end pay_ex,
      case when pg_input_is_valid(a.value->>'charge_ex_vat','numeric')
        then(a.value->>'charge_ex_vat')::numeric else 0 end charge_ex,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) bucket_name,
      coalesce(nullif(a.value->>'unit_name',''),'units') unit_name,
      a.value->'frequency' frequency,s.vat_rate,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s cross join lateral jsonb_each(
      case when jsonb_typeof(s.additional_units_json)='object'
        then s.additional_units_json else '{}'::jsonb end) a
    where jsonb_typeof(a.value)='object'
      and ((case when pg_input_is_valid(a.value->>'pay_ex_vat','numeric')
              then(a.value->>'pay_ex_vat')::numeric else 0 end)<>0
        or (case when pg_input_is_valid(a.value->>'charge_ex_vat','numeric')
              then(a.value->>'charge_ex_vat')::numeric else 0 end)<>0)
      and not(s.daily_calc_of_invoices
        and jsonb_typeof(a.value->'days')='object'
        and exists(select 1 from jsonb_each_text(
          case when jsonb_typeof(a.value->'days')='object'
            then a.value->'days' else '{}'::jsonb end) d
          where left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'))
  ),
  expense_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      e.code,e.pay_ex,e.charge_ex,s.vat_rate,s.expenses_description,
      s.expenses_evidence_r2_key,s.expenses_evidence_manifest,
      s.mileage_units,s.mileage_pay_rate,s.mileage_charge_rate,
      s.mileage_evidence_r2_key,s.mileage_evidence_manifest,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    cross join lateral (
      values
       ('TRAVEL',coalesce(s.travel_pay_ex_vat,0),coalesce(s.travel_charge_ex_vat,0)),
       ('ACCOMMODATION',coalesce(s.accommodation_pay_ex_vat,0),coalesce(s.accommodation_charge_ex_vat,0)),
       ('OTHER',coalesce(s.other_pay_ex_vat,0),coalesce(s.other_charge_ex_vat,0)),
       ('EXPENSES_FALLBACK',
          case when coalesce(s.travel_pay_ex_vat,0)+coalesce(s.accommodation_pay_ex_vat,0)+coalesce(s.other_pay_ex_vat,0)=0 then coalesce(s.expenses_pay_ex_vat,0) else 0 end,
          case when coalesce(s.travel_charge_ex_vat,0)+coalesce(s.accommodation_charge_ex_vat,0)+coalesce(s.other_charge_ex_vat,0)=0 then coalesce(s.expenses_charge_ex_vat,0) else 0 end),
       ('MILEAGE',coalesce(s.mileage_pay_ex_vat,0),coalesce(s.mileage_charge_ex_vat,0))
    ) e(code,pay_ex,charge_ex)
    where e.pay_ex<>0 or e.charge_ex<>0
  ),
  line_union as materialized (
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||work_date description,h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric pay_day,null::numeric pay_night,null::numeric pay_sat,
      null::numeric pay_sun,null::numeric pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_DAILY' line_type,
      'TS:'||timesheet_id||':HOURS:'||work_date source_key,
      jsonb_build_object('date',work_date,'timesheet_version',timesheet_version,
        'tsfin_id',tsfin_id,'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json) detail
    from segment_daily_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - W/E '||week_ending_date, h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_WEEKLY','TS:'||timesheet_id||':HOURS:WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json)
    from segment_weekly_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - W/E '||week_ending_date, h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_WEEKLY','TS:'||timesheet_id||':HOURS:WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json)
    from nonsegment_lines
    where pay_ex<>0 or charge_ex<>0 or h_day+h_night+h_sat+h_sun+h_bh<>0
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||bucket_name||' - '||work_date||' - '||
        units||' '||unit_name,0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'ADDITIONAL_RATE_DAILY',
      'TS:'||timesheet_id||':ADD:'||code||':'||work_date,
      jsonb_build_object('date',work_date,'timesheet_version',timesheet_version,
        'tsfin_id',tsfin_id,'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'bucket',jsonb_build_object('code',code,'bucket_name',bucket_name,
          'unit_name',unit_name,'frequency',frequency),
        'units',jsonb_build_object('unit_count',units,'pay_rate',pay_rate,
          'charge_rate',charge_rate))
    from additional_daily_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||bucket_name||' - '||units||' '||unit_name,0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'ADDITIONAL_RATE',
      'TS:'||timesheet_id||':ADD:'||code||':WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'bucket',jsonb_build_object('code',code,'bucket_name',bucket_name,
          'unit_name',unit_name,'frequency',frequency),
        'units',jsonb_build_object('unit_count',units,'pay_rate',pay_rate,
          'charge_rate',charge_rate))
    from additional_weekly_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      case when code='MILEAGE' then 'Mileage - '||coalesce(mileage_units,0)||
          ' miles (W/E '||week_ending_date||')'
        else initcap(replace(code,'_',' '))||' (W/E '||week_ending_date||')' end,
      0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,
      case when code='MILEAGE' then 'MILEAGE'
        when code='EXPENSES_FALLBACK' then 'EXPENSES_TOTAL'
        else 'EXPENSE_'||code end,
      case when code='MILEAGE' then 'TS:'||timesheet_id||':MILEAGE'
        when code='EXPENSES_FALLBACK' then 'TS:'||timesheet_id||':EXP:TOTAL'
        else 'TS:'||timesheet_id||':EXP:'||code end,
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'expense',case when code='MILEAGE' then jsonb_build_object(
          'category','MILEAGE','mileage_units',mileage_units,
          'pay_rate',mileage_pay_rate,'charge_rate',mileage_charge_rate,
          'evidence_r2_key',mileage_evidence_r2_key,
          'evidence_manifest',mileage_evidence_manifest)
        else jsonb_build_object('category',code,'note',expenses_description,
          'evidence_r2_key',expenses_evidence_r2_key,
          'evidence_manifest',expenses_evidence_manifest) end)
    from expense_lines
  ),
  correction_scopes_pre as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-prewrite:'||scope.planned_invoice_id::text,
      'scope_key',scope.planned_invoice_id::text,
      'invoice_id',case when exists(select 1 from public.invoices existing
        where existing.id=scope.planned_invoice_id)
        then scope.planned_invoice_id end,
      'validation_purpose','GENERATION_PREWRITE',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.planned_invoice_id),'[]'::jsonb) scopes
    from(
      select l.planned_invoice_id,min(vc.payload_json::text)::jsonb payload_json,
        jsonb_agg(distinct jsonb_build_object(
          'timesheet_id',l.timesheet_id,
          'vat_rate_pct',l.vat_rate))
          filter(where l.timesheet_id is not null) planned_members
      from line_union l
      join valid_chunks vc on vc.id=l.chunk_id
      group by l.planned_invoice_id
    ) scope
  ),
  correction_validation_pre as materialized (
    select r.*
    from correction_scopes_pre s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),
  correction_failures_pre as materialized (
    select scope_key,blocker_code,detail_json detail
    from correction_validation_pre
    where not valid
  ),  write_eligible_chunks as materialized (
    select vc.*
    from valid_chunks vc
    where not exists(
      select 1 from correction_failures_pre f
      where f.scope_key=vc.planned_invoice_id::text)
  ),
  line_totals as materialized (
    select l.planned_invoice_id,
      round(sum(round(l.charge_ex,2)),2) subtotal_ex_vat,
      round(sum(round(l.charge_ex*l.vat_rate/100,2)),2) vat_amount,
      round(sum(round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2)),2) total_inc_vat
    from line_union l
    join write_eligible_chunks w on w.id=l.chunk_id
    group by l.planned_invoice_id
  ),
  existing_target_headers as materialized (
    select vc.id chunk_id,i.id invoice_id
    from write_eligible_chunks vc
    join header_source h on h.chunk_id=vc.id
    join public.invoices i on i.id=vc.planned_invoice_id
      and i.client_id=h.client_id and i.type='INVOICE' and i.status='DRAFT'
    where not exists(
      select 1 from segment_lock_failures_pre f
      where f.invoice_id=vc.planned_invoice_id)
  ),
  inserted_headers as (
    insert into public.invoices(id,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
      header_snapshot_json,document_revision,document_state,created_at,updated_at)
    select h.planned_invoice_id,h.client_id,'DRAFT',v_now,
      t.subtotal_ex_vat,t.vat_amount,t.total_inc_vat,
      jsonb_build_object('client_id',h.client_id,'client_name',h.client_name,
        'client_invoice_address',h.client_invoice_address,'client_primary_invoice_email',h.primary_invoice_email,
        'agency_name',h.agency_name,'agency_logo',h.agency_logo,'registered_address',h.registered_address,
        'company_reg_number',h.company_reg_number,'company_registration_number',h.company_reg_number,
        'vat_chargeable',h.vat_chargeable,'payment_terms_days',h.payment_terms_days,
        'issued_at_utc',null,'due_at_utc',null,
        'totals',jsonb_build_object(
          'subtotal_ex_vat',t.subtotal_ex_vat,
          'vat_amount',t.vat_amount,'total_inc_vat',t.total_inc_vat),
        'bank',jsonb_build_object('name',h.bank_name,'sort_code',h.bank_sort_code,'account_number',h.bank_account_number),
        'vat_registration_number',h.vat_registration_number,
        'meta',jsonb_build_object('source','INVOICE_OPERATION_QUEUE',
          'invoice_week_start',vc.payload_json->>'target_invoice_week',
          'consolidation_mode',vc.payload_json->>'consolidation_mode',
          'self_bill',vc.payload_json->>'invoice_stream'='SELF_BILL','timesheet_count',h.source_count),
        'attach_policy',vc.payload_json#>'{plan,settings_snapshot,attach_policy}'),
      1,'STALE',v_now,v_now
    from header_source h join write_eligible_chunks vc on vc.id=h.chunk_id
    join line_totals t on t.planned_invoice_id=h.planned_invoice_id
    where not exists(
      select 1 from segment_lock_failures_pre f
      where f.invoice_id=h.planned_invoice_id)
    on conflict(id) do nothing returning id
  ),
  target_headers as materialized (
    select e.chunk_id,e.invoice_id
    from existing_target_headers e
    where not exists(
      select 1
      from inserted_headers h
      where h.id=e.invoice_id)
  ),
  deferred_new_headers as (
    update public.invoice_operation_chunks c
    set status='QUEUED',
      phase='COMMIT',
      progress_json=coalesce(c.progress_json,'{}'::jsonb)
        ||jsonb_build_object('status_message',
          'Invoice header created; applying authoritative source ownership'),
      error_json=null,
      lease_owner=null,
      lease_token=null,
      lease_expires_at_utc=null,
      updated_at_utc=v_now
    from inserted_headers h
    join write_eligible_chunks vc on vc.planned_invoice_id=h.id
    where c.id=vc.id
    returning c.id
  ),
  inserted_lines as (
    insert into public.invoice_lines(
      invoice_id,timesheet_id,booking_id,description,hours_day,hours_night,hours_sat,hours_sun,hours_bh,
      pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,
      paper_ts_r2_key,meta_json,source_key
    )
    select l.planned_invoice_id,l.timesheet_id,l.booking_id,l.description,
      round(l.h_day,2),round(l.h_night,2),round(l.h_sat,2),round(l.h_sun,2),round(l.h_bh,2),
      l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
      l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,
      round(l.pay_ex,2),round(l.charge_ex,2),round(l.charge_ex-l.pay_ex,2),l.vat_rate,
      round(l.charge_ex*l.vat_rate/100,2),round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2),
      null,jsonb_build_object('line_type',l.line_type,'timesheet_id',l.timesheet_id,
        'candidate_display',l.description,'week_ending_date',
        (select s.week_ending_date from source_rows s where s.timesheet_id=l.timesheet_id limit 1),
        'schedule_references',
        (select s.schedule_refs from source_rows s where s.timesheet_id=l.timesheet_id limit 1),
        'totals',jsonb_build_object('line_pay_ex_vat',round(l.pay_ex,2),
          'line_charge_ex_vat',round(l.charge_ex,2),'margin_ex_vat',round(l.charge_ex-l.pay_ex,2),
          'vat_rate_pct',l.vat_rate,'vat_amount',round(l.charge_ex*l.vat_rate/100,2),
          'total_inc_vat',round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2)))||l.detail,l.source_key
    from line_union l join target_headers h on h.invoice_id=l.planned_invoice_id
    on conflict(invoice_id,source_key) do nothing
    returning invoice_id,timesheet_id,total_charge_ex_vat,vat_amount,total_inc_vat
  ),
  all_target_lines as materialized (
    select l.invoice_id,l.total_charge_ex_vat,l.vat_amount,l.total_inc_vat
    from public.invoice_lines l
    where l.invoice_id in(select invoice_id from target_headers)
    union all
    select l.invoice_id,l.total_charge_ex_vat,l.vat_amount,l.total_inc_vat
    from inserted_lines l
  ),
  all_line_totals as materialized (
    select l.invoice_id,count(*)::integer line_count,
      round(sum(l.total_charge_ex_vat),2) subtotal_ex_vat,
      round(sum(l.vat_amount),2) vat_amount,
      round(sum(l.total_inc_vat),2) total_inc_vat
    from all_target_lines l
    group by l.invoice_id
  ),
  updated_header_totals as (
    update public.invoices i
    set subtotal_ex_vat=t.subtotal_ex_vat,vat_amount=t.vat_amount,
      total_inc_vat=t.total_inc_vat,document_state='STALE',
      header_snapshot_json=coalesce(i.header_snapshot_json,'{}'::jsonb)
        ||jsonb_build_object('totals',jsonb_build_object(
          'subtotal_ex_vat',t.subtotal_ex_vat,'vat_amount',t.vat_amount,
          'total_inc_vat',t.total_inc_vat)),
      updated_at=v_now
    from all_line_totals t where i.id=t.invoice_id
    returning i.id
  ),
  segment_lock_targets as materialized (
    select targets from segment_lock_targets_pre
  ),
  segment_lock_authority as materialized (
    select * from segment_lock_authority_pre
  ),
  segment_lock_failures as materialized (
    select * from segment_lock_authority where not success
  ),
  whole_lock as (
    update public.timesheets_financials tf
    set locked_by_invoice_id=vc.planned_invoice_id,locked_at_utc=v_now,updated_at=v_now
    from members m join write_eligible_chunks vc on vc.id=m.chunk_id
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    cross join (select count(*) applied_count from segment_lock_authority) segment_application
    where tf.timesheet_id=m.timesheet_id and tf.is_current
      and (coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS'
        or not exists(select 1 from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) e
                      where nullif(e->>'invoice_locked_invoice_id','') is null))
    returning tf.timesheet_id
  ),
  week_lock as (
    update public.contract_weeks cw set status='INVOICED',updated_at=v_now
    where cw.timesheet_id in(
      select m.timesheet_id
      from members m
      join target_headers h on h.chunk_id=m.chunk_id)
      and exists(select 1 from public.timesheets_financials tf where tf.timesheet_id=cw.timesheet_id
        and tf.is_current and (tf.locked_by_invoice_id is not null or
          not exists(select 1 from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) e
                     where nullif(e->>'invoice_locked_invoice_id','') is null)))
    returning cw.id
  ),
  nhsp_shift_inclusion as (
    update public.nhsp_shifts ns
    set invoice_status='INCLUDED',
      invoice_id=h.invoice_id,
      updated_at=v_now
    from source_rows s
    join target_headers h
      on h.chunk_id=s.chunk_id and h.invoice_id=s.planned_invoice_id
    where ns.timesheet_id=s.timesheet_id
      and ns.invoice_status='PENDING'
      and ns.invoice_id is null
      and ns.cancelled_at_utc is null
      and exists(
        select 1
        from jsonb_array_elements(
          case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
            then s.invoice_breakdown_json->'segments'
            else '[]'::jsonb end) segment(value)
        where coalesce(
            nullif(segment.value->>'nhsp_shift_id',''),
            nullif(segment.value->>'shift_id',''))=ns.id::text)
    returning ns.id
  ),
  hr_sources as (
    insert into public.invoice_hr_source_rows(invoice_id,source_system,import_id,header_columns,rows_json,header_rows)
    select distinct h.invoice_id,
      case when tf.basis::text in('NHSP','NHSP_ADJUSTMENT')
        then 'NHSP' else 'HEALTHROSTER' end,
      tf.nhsp_import_id,'[]'::jsonb,
      case when jsonb_typeof(tf.external_source_rows_json)='array' then tf.external_source_rows_json else '[]'::jsonb end,
      '[]'::jsonb
    from members m
    join target_headers h on h.chunk_id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    where tf.nhsp_import_id is not null
    on conflict(invoice_id,source_system,import_id) do update set rows_json=excluded.rows_json
    returning invoice_id
  ),
  source_segments as materialized (
    select distinct h.invoice_id planned_invoice_id,
      coalesce(
        case when coalesce(x.value->>'nhsp_shift_id','')~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(x.value->>'nhsp_shift_id')::uuid end,
        case when coalesce(x.value->>'shift_id','')~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(x.value->>'shift_id')::uuid end,
        case when substr(coalesce(x.value->>'segment_id',''),6)~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then substr(x.value->>'segment_id',6)::uuid end) shift_id,
      case
        when s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
         and (
           lower(coalesce(x.value->>'is_reversal','false')) in(
             'true','t','1','yes')
           or coalesce(s.total_hours,0)<0
         ) then 'REVERSAL'
        when s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
          then 'CORRECTED_HOURS'
        else 'SOURCE'
      end evidence_role_key
    from source_rows s
    join target_headers h
      on h.chunk_id=s.chunk_id and h.invoice_id=s.planned_invoice_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end) x(value)
    where coalesce(
        nullif(x.value->>'nhsp_shift_id',''),
        nullif(x.value->>'shift_id',''),
        case when left(x.value->>'segment_id',5)='nhsp:'
          then substr(x.value->>'segment_id',6) end)~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and (
        upper(coalesce(x.value->>'source_system',''))='NHSP'
        or (upper(coalesce(x.value->>'source_system',''))='HEALTHROSTER'
          and coalesce((s.payload_json#>>'{plan,settings_snapshot,attach_policy,hr_attach_to_invoice}')::boolean,true)))
    union
    select distinct r.planned_invoice_id,n.id shift_id,
      case when r.is_reversal then 'REVERSAL'
        else 'CORRECTED_HOURS' end evidence_role_key
    from adjustment_segment_refs r
    join source_timesheet_ancestry a
      on a.planned_invoice_id=r.planned_invoice_id
     and a.root_timesheet_id=r.root_timesheet_id
     and a.ancestry_depth>0
    join public.nhsp_shifts n
      on n.timesheet_id=a.source_timesheet_id
     and n.latest_import_id is not null
     and n.external_row_key is not null
     and (
       upper(coalesce(n.source_system::text,''))='NHSP'
       or (
         upper(coalesce(n.source_system::text,''))='HEALTHROSTER'
         and r.healthroster_attach_allowed
       )
     )
     and (
       (r.ref_num is not null
         and btrim(coalesce(n.ref_num,''))=r.ref_num)
       or (
         r.ref_num is null
         and r.start_utc is not null
         and r.end_utc is not null
         and n.start_utc=r.start_utc
         and n.end_utc=r.end_utc
       )
     )
  ),
  source_import_rows as materialized (
    select distinct s.planned_invoice_id,
      upper(coalesce(n.source_system::text,'UNKNOWN')) source_system,
      n.latest_import_id import_id,n.external_row_key,s.evidence_role_key
    from source_segments s
    join public.nhsp_shifts n on n.id=s.shift_id
    where n.latest_import_id is not null
      and n.external_row_key is not null
  ),
  source_imports as materialized (
    select s.planned_invoice_id,s.source_system,s.import_id,
      jsonb_agg(jsonb_build_object(
        'external_row_key',s.external_row_key,
        'evidence_role_key',s.evidence_role_key)
        order by s.external_row_key,s.evidence_role_key) row_occurrences
    from source_import_rows s
    group by s.planned_invoice_id,s.source_system,s.import_id
  ),
  authoritative_hr_sources as (
    insert into public.invoice_hr_source_rows(
      invoice_id,source_system,import_id,header_columns,rows_json)
    select g.planned_invoice_id,g.source_system,g.import_id,
      case when jsonb_typeof(i.parse_summary_json->'header_columns')='array'
        then i.parse_summary_json->'header_columns' else '[]'::jsonb end,
      coalesce((select jsonb_agg(
          r.payload_json
            ||jsonb_build_object(
              'evidence_role',case occurrence.value->>'evidence_role_key'
                when 'REVERSAL' then case when g.source_system='NHSP'
                  then 'NHSP Reversal' else 'HealthRoster Reversal' end
                when 'CORRECTED_HOURS' then case when g.source_system='NHSP'
                  then 'NHSP Corrected Hours' else 'HealthRoster Corrected Hours' end
                else case when g.source_system='NHSP'
                  then 'NHSP Shift' else 'HealthRoster Shift' end
              end)
            ||case when occurrence.value->>'evidence_role_key'='REVERSAL'
              then jsonb_build_object('reversal_state','REVERSED')
              else '{}'::jsonb end
          order by r.id,occurrence.value->>'evidence_role_key')
        from jsonb_array_elements(g.row_occurrences) occurrence(value)
        join public.hr_rows r
          on r.import_id=g.import_id
         and r.external_row_key=occurrence.value->>'external_row_key'),
        '[]'::jsonb)
    from source_imports g join public.hr_imports i on i.id=g.import_id
    on conflict(invoice_id,source_system,import_id) do update
      set header_columns=excluded.header_columns,rows_json=excluded.rows_json
    returning invoice_id
  ),
  audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,after_json,reason)
    select v_now,o.actor_user_id,u.display_name,u.role,'invoices',vc.planned_invoice_id::text,
      case when exists(select 1 from inserted_headers h
        where h.id=vc.planned_invoice_id)
        then 'INVOICE_CREATED' else 'INVOICE_DRAFT_APPENDED' end,
      jsonb_build_object('invoice_id',vc.planned_invoice_id,
        'source_ids',coalesce(vc.payload_json->'canonical_source_ids',
          vc.payload_json->'source_ids','[]'::jsonb),
        'source_revision',vc.payload_json->>'source_revision',
        'operation_id',vc.operation_id),'INVOICE_OPERATION_QUEUE'
    from write_eligible_chunks vc
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    join public.invoice_operations o on o.id=vc.operation_id
    left join public.tms_users u on u.id=o.actor_user_id
    returning id
  ),
  correction_failures as materialized (
    select scope_key::uuid invoice_id,blocker_code,detail
    from correction_failures_pre
    where scope_key~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  update public.invoice_operation_chunks c
    set status=case when exists(select 1 from all_line_totals l
                               where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then 'COMPLETE' else 'BLOCKED' end,
      phase=case when exists(select 1 from all_line_totals l
                            where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then 'COMPLETE' else 'BLOCKED' end,
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(vc.planned_invoice_id),
        'source_revision',vc.payload_json->>'source_revision'),
      error_json=case
        when not exists(select 1 from all_line_totals l
          where l.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code','NO_INVOICE_LINES_CREATED')
        when exists(select 1 from segment_lock_failures sf
          where sf.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code','SEGMENT_LOCK_FAILED','detail',(
            select jsonb_agg(to_jsonb(sf))
            from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id))
        when exists(select 1 from correction_failures cf
          where cf.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code',(
            select cf.blocker_code from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id))
        else null end,
      completed_at_utc=case
        when exists(select 1 from all_line_totals l
          where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then v_now else null end,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from valid_chunks vc
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    cross join (select count(*) applied_count from segment_lock_authority) segment_application
    cross join (select count(*) cached_count from authoritative_hr_sources) source_cache_application
    where c.id=vc.id
  ;
  select coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,
      'result',c.result_json,'error',c.error_json)),'[]'::jsonb)
    into v_part
  from jsonb_array_elements(p_claims) x
  join public.invoice_operation_chunks c
    on c.id=case when coalesce(x->>'chunk_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x->>'chunk_id')::uuid end
  where x->>'phase'='COMMIT'
    and coalesce(c.payload_json->>'command_type','')<>'GENERATE_CREDIT_NOTE';
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Credit-note COMMIT: exact negative line clone and source unlock; document creation stays asynchronous.
  execute $q$
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements($1) x where x->>'phase'='COMMIT'
  ),
  credit_revisions as materialized (
    select c.*,i.id source_invoice_id,(c.payload_json#>>'{plan,planned_invoice_id}')::uuid credit_note_id
      ,encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),
        'sha256'),'hex') current_revision
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i on i.id=c.entity_id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
      and i.type='INVOICE' and i.status in ('ISSUED','PAID')
  ),
  credit_correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','credit-source:'||c.source_invoice_id::text,
      'scope_key',c.source_invoice_id::text,
      'invoice_id',c.source_invoice_id,
      'validation_purpose','CREDIT_SOURCE')
      order by c.source_invoice_id),'[]'::jsonb) scopes
    from(select distinct source_invoice_id from credit_revisions) c
  ),
  credit_correction_failures as materialized (
    select r.invoice_id source_invoice_id,r.blocker_code,r.detail_json
    from credit_correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,($2 at time zone 'Europe/London')::date) r
    where not r.valid
  ),
  credit_rejected as (
    update public.invoice_operation_chunks q
    set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code',case
        when c.current_revision<>c.payload_json->>'source_revision'
          then 'CREDIT_SOURCE_CHANGED_BEFORE_COMMIT'
        else coalesce((select f.blocker_code
          from credit_correction_failures f
          where f.source_invoice_id=c.source_invoice_id
          order by f.blocker_code limit 1),'CREDIT_CORRECTION_VALIDATION_FAILED')
        end),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=$2
    from credit_revisions c
    where q.id=c.id and(
      c.current_revision<>c.payload_json->>'source_revision'
      or exists(select 1 from credit_correction_failures f
        where f.source_invoice_id=c.source_invoice_id))
    returning q.id
  ),
  credits as materialized (
    select c.* from credit_revisions c
    where c.current_revision=c.payload_json->>'source_revision'
      and not exists(select 1 from credit_rejected r where r.id=c.id)
  ),
  inserted_credit as (
    insert into public.invoices(id,type,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
      original_invoice_id,notes,header_snapshot_json,document_revision,document_state,created_at,updated_at)
    select c.credit_note_id,'CREDIT_NOTE',i.client_id,'DRAFT',$2,
      -i.subtotal_ex_vat,-i.vat_amount,-i.total_inc_vat,i.id,
      c.payload_json->>'credit_reason',
      i.header_snapshot_json||jsonb_build_object(
        'credit_source_invoice_id',i.id,
        'credit_reason',c.payload_json->>'credit_reason'),1,'STALE',$2,$2
    from credits c join public.invoices i on i.id=c.source_invoice_id
    on conflict(id) do nothing returning id
  ),
  cloned_lines as (
    insert into public.invoice_lines(invoice_id,timesheet_id,booking_id,description,
      hours_day,hours_night,hours_sat,hours_sun,hours_bh,pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,total_pay_ex_vat,total_charge_ex_vat,
      margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,paper_ts_r2_key,meta_json,source_key)
    select c.credit_note_id,l.timesheet_id,l.booking_id,
      'CREDIT NOTE – '||coalesce(l.description,''),
      l.hours_day,l.hours_night,l.hours_sat,l.hours_sun,l.hours_bh,
      l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
      l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,
      -l.total_pay_ex_vat,-l.total_charge_ex_vat,-l.margin_ex_vat,l.vat_rate_pct,
      -l.vat_amount,-l.total_inc_vat,l.paper_ts_r2_key,
      coalesce(l.meta_json,'{}'::jsonb)||jsonb_build_object(
        'credit_note',true,'original_invoice_id',c.source_invoice_id,
        'original_invoice_line_id',l.id,'credit_of_line_id',l.id,'line_type',
        'CREDIT_'||coalesce(l.meta_json->>'line_type','LINE')),
      'CN:'||c.credit_note_id||':LINE:'||l.id
    from credits c join public.invoice_lines l on l.invoice_id=c.source_invoice_id
    on conflict(invoice_id,source_key) do nothing returning invoice_id
  ),
  source_mark as (
    update public.invoices i set credit_note_created_at_utc=$2,updated_at=$2
    where i.id in(select source_invoice_id from credits) returning i.id
  ),
  unlocks as (
    update public.timesheets_financials tf
    set locked_by_invoice_id=null,locked_at_utc=null,
      unlocked_by_credit_note_id=c.credit_note_id,is_stale=true,
      stale_reason='UNLOCKED_BY_CREDIT',updated_at=$2
    from credits c
    where tf.locked_by_invoice_id=c.source_invoice_id and tf.is_current returning tf.timesheet_id
  ),
  segment_unlocks as (
    update public.timesheets_financials tf
    set invoice_breakdown_json=jsonb_set(tf.invoice_breakdown_json,'{segments}',
      (select jsonb_agg(case
        when e.value->>'invoice_locked_invoice_id'=c.source_invoice_id::text
          then (e.value-'invoice_locked_invoice_id'-'invoice_locked_at_utc')
        else e.value end order by e.ordinality)
       from jsonb_array_elements(tf.invoice_breakdown_json->'segments')
         with ordinality e(value,ordinality)),true),
      unlocked_by_credit_note_id=c.credit_note_id,is_stale=true,
      stale_reason='UNLOCKED_BY_CREDIT',updated_at=$2
    from credits c
    where tf.is_current and jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
      and exists(select 1 from jsonb_array_elements(tf.invoice_breakdown_json->'segments') e
        where e->>'invoice_locked_invoice_id'=c.source_invoice_id::text)
    returning tf.timesheet_id
  ),
  recompute_outbox as (
    insert into public.ts_financials_outbox(
      timesheet_id,reason,attempt_count,next_attempt_at,last_error,created_at)
    select distinct u.timesheet_id,'VERSION_ROTATED'::public.ts_fin_reason_enum,
      0,$2,null,$2
    from (
      select timesheet_id from unlocks
      union all select timesheet_id from segment_unlocks
    ) u
    on conflict on constraint uq_tsfin_outbox do nothing
    returning timesheet_id
  ),
  credit_audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,
      actor_role_at_time,object_type,object_id_text,action,after_json,reason)
    select $2,o.actor_user_id,u.display_name,u.role,'invoices',
      c.credit_note_id::text,'CREDIT_NOTE_CREATED',
      jsonb_build_object('credit_note_id',c.credit_note_id,
        'original_invoice_id',c.source_invoice_id,
        'credit_reason',c.payload_json->>'credit_reason',
        'command_token',c.payload_json->>'command_token',
        'subtotal_ex_vat',-i.subtotal_ex_vat,'vat_amount',-i.vat_amount,
        'total_inc_vat',-i.total_inc_vat,
        'financial_recompute_enqueued',true),
      'INVOICE_OPERATION_QUEUE'
    from credits c join public.invoices i on i.id=c.source_invoice_id
    join public.invoice_operations o on o.id=c.operation_id
    left join public.tms_users u on u.id=o.actor_user_id
    returning id
  ),
  completed as (
    update public.invoice_operation_chunks q
    set status='QUEUED',
      phase='QUEUE_DOCUMENT',
      error_json=null,
      completed_at_utc=null,lease_owner=null,lease_token=null,
      lease_expires_at_utc=null,updated_at_utc=$2,
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(c.credit_note_id),
        'credit_note_id',c.credit_note_id,'source_invoice_id',c.source_invoice_id)
    from credits c
    cross join (select count(*) outbox_count from recompute_outbox) outbox_application
    cross join (select count(*) audit_count from credit_audits) audit_application
    where q.id=c.id
    returning q.id,q.status,q.phase,q.result_json,q.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'chunk_id',id,'status',status,'phase',phase,
    'result',result_json,'error',error_json)),'[]'::jsonb)
  from completed
  $q$
  into v_part using p_claims,v_now;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Document work is queued in a separate SQL statement so source-invalidation
  -- statement triggers cannot supersede the freshly-created document operation.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='QUEUE_DOCUMENT'
  ),
  queued_sources as materialized (
    select c.id chunk_id,c.operation_id parent_operation_id,
      (c.payload_json#>>'{plan,planned_invoice_id}')::uuid planned_invoice_id,
      c.payload_json->>'source_revision' source_revision,
      c.payload_json->>'command_type' command_type,
      c.payload_json->>'command_token' command_token,
      c.payload_json->>'credit_reason' credit_reason,
      i.document_revision::text document_revision
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i
      on i.id=(c.payload_json#>>'{plan,planned_invoice_id}')::uuid
  ),
  existing_doc_versions as materialized (
    select distinct on(q.chunk_id) q.chunk_id,v.id document_version_id,
      v.operation_id,v.status
    from queued_sources q
    join public.invoice_document_versions v
      on v.entity_type='INVOICE'
     and v.entity_id=q.planned_invoice_id
     and v.purpose='DRAFT_PREVIEW'
     and v.source_revision=q.document_revision
     and v.template_version='invoice-professional-v2'
     and v.status in(
       'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING',
       'VERIFYING','READY')
    where q.command_type<>'GENERATE_CREDIT_NOTE'
    order by q.chunk_id,case when v.status='READY' then 0 else 1 end,
      v.created_at_utc desc,v.id desc
  ),
  doc_ops as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,created_at_utc,updated_at_utc)
    select q.parent_operation_id,'BUILD_DOCUMENT','INVOICE',q.planned_invoice_id,o.actor_user_id,
      encode(digest('DRAFT_PREVIEW|'||q.planned_invoice_id||'|'||q.document_revision||
        '|invoice-professional-v2','sha256'),'hex'),
      'QUEUED','BUILD_MANIFEST',550,q.document_revision,'invoice-professional-v2',
      jsonb_build_object('invoice_id',q.planned_invoice_id,'purpose','DRAFT_PREVIEW'),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,
      nextval('public.invoice_operation_change_seq'),v_now,v_now
    from queued_sources q join public.invoice_operations o on o.id=q.parent_operation_id
    where q.command_type<>'GENERATE_CREDIT_NOTE'
      and not exists(
        select 1 from existing_doc_versions e where e.chunk_id=q.chunk_id)
    on conflict(idempotency_key) where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,excluded.priority),updated_at_utc=v_now
    returning *
  ),
  selected_doc_ops as materialized (
    select q.chunk_id,q.planned_invoice_id,q.document_revision source_revision,
      d.id operation_id,d.control_version,null::uuid existing_version_id,
      null::text existing_status
    from queued_sources q join doc_ops d on d.entity_id=q.planned_invoice_id
    union all
    select q.chunk_id,q.planned_invoice_id,q.document_revision,
      e.operation_id,o.control_version,e.document_version_id,e.status
    from queued_sources q
    join existing_doc_versions e on e.chunk_id=q.chunk_id
    join public.invoice_operations o on o.id=e.operation_id
  ),
  doc_versions as materialized (
    insert into public.invoice_document_versions(entity_type,entity_id,purpose,operation_id,source_revision,
      template_version,status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select 'INVOICE',d.planned_invoice_id,'DRAFT_PREVIEW',d.operation_id,d.source_revision,
      'invoice-professional-v2','PLANNING','{}',encode(digest('{}','sha256'),'hex'),
      '[]',encode(digest('[]','sha256'),'hex'),v_now
    from selected_doc_ops d
    where d.existing_version_id is null
    on conflict(entity_type,entity_id,purpose,source_revision,template_version)
      where purpose in('DRAFT_PREVIEW','TIMESHEET')
        and status in ('PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning id,entity_id,operation_id
  ),
  all_doc_versions as materialized (
    select d.chunk_id,d.planned_invoice_id,d.operation_id,d.control_version,
      d.source_revision,
      coalesce(d.existing_version_id,v.id) document_version_id,
      coalesce(d.existing_status,'PLANNING') document_status
    from selected_doc_ops d
    left join doc_versions v
      on v.entity_id=d.planned_invoice_id and v.operation_id=d.operation_id
    where d.existing_version_id is not null or v.id is not null
  ),
  doc_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,status,priority,run_after_utc,payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select d.operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',d.document_version_id::text,
        d.source_revision,'invoice-professional-v2','1'),'sha256'),'hex'),
      0,'INVOICE',d.planned_invoice_id,d.document_version_id,
      'QUEUED',550,v_now,jsonb_build_object('purpose','DRAFT_PREVIEW'),d.control_version,v_now,v_now
    from all_doc_versions d
    where d.document_status<>'READY'
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing returning operation_id
  ),
  invoice_ptrs as (
    update public.invoices i set preview_document_version_id=d.document_version_id,
      active_document_operation_id=case when d.document_status='READY'
        then null else d.operation_id end,
      document_state=case when d.document_status='READY'
        then 'READY' else 'QUEUED' end,updated_at=v_now
    from all_doc_versions d where i.id=d.planned_invoice_id returning i.id
  ),
  credit_issue_ops as materialized (
    insert into public.invoice_operations(
      parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,
      input_json,config_json,progress_json,total_units,chunk_count,
      control_version,change_seq,created_at_utc,updated_at_utc)
    select q.parent_operation_id,'ISSUE_INVOICES','INVOICE_BATCH',null,
      o.actor_user_id,
      encode(digest('CREDIT_ISSUE|'||q.planned_invoice_id||'|'||
        q.document_revision||'|'||coalesce(q.command_token,''),'sha256'),'hex'),
      'QUEUED','VALIDATE',850,q.document_revision,'invoice-professional-v2',
      jsonb_build_object(
        'invoice_ids',jsonb_build_array(q.planned_invoice_id),
        'credit_note',true,'credit_reason',q.credit_reason,
        'command_token',q.command_token,'deliver',false),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,nextval('public.invoice_operation_change_seq'),v_now,v_now
    from queued_sources q
    join public.invoice_operations o on o.id=q.parent_operation_id
    where q.command_type='GENERATE_CREDIT_NOTE'
    on conflict(idempotency_key)
      where status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,excluded.priority),
      updated_at_utc=v_now
    returning *
  ),
  selected_credit_issue as materialized (
    select q.chunk_id,q.planned_invoice_id,q.document_revision,
      q.command_token,q.credit_reason,o.id operation_id,o.control_version
    from queued_sources q
    join credit_issue_ops o on o.parent_operation_id=q.parent_operation_id
      and o.operation_type='ISSUE_INVOICES'
    where q.command_type='GENERATE_CREDIT_NOTE'
  ),
  credit_issue_chunks as (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,status,
      priority,run_after_utc,payload_json,operation_control_version,
      created_at_utc,updated_at_utc)
    select s.operation_id,'ISSUE_INVOICE','VALIDATE',
      encode(digest(concat_ws('|','ISSUE_INVOICE',s.planned_invoice_id::text,
        s.document_revision,s.command_token),'sha256'),'hex'),
      0,'INVOICE',
      s.planned_invoice_id,'QUEUED',850,v_now,
      jsonb_build_object(
        'invoice_id',s.planned_invoice_id,
        'source_revision',s.document_revision,
        'allow_early',true,'deliver',false,
        'command_token',s.command_token,
        'credit_note',true,'credit_reason',s.credit_reason),
      s.control_version,v_now,v_now
    from selected_credit_issue s
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing
    returning operation_id
  ),
  credit_issue_ptrs as (
    update public.invoices i
    set active_issue_operation_id=s.operation_id,issue_state='VALIDATING',
      updated_at=v_now
    from selected_credit_issue s
    where i.id=s.planned_invoice_id
    returning i.id
  ),
  child_results as materialized (
    select d.chunk_id,d.operation_id document_operation_id,
      d.document_version_id,null::uuid issue_operation_id
    from all_doc_versions d
    union all
    select s.chunk_id,null::uuid,null::uuid,s.operation_id
    from selected_credit_issue s
  )
  update public.invoice_operation_chunks c
    set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,updated_at_utc=v_now,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      result_json=coalesce(c.result_json,'{}'::jsonb)||jsonb_build_object(
        'document_operation_id',d.document_operation_id,
        'document_version_id',d.document_version_id,
        'issue_operation_id',d.issue_operation_id)
    from child_results d where c.id=d.chunk_id
  ;
  select coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,
      'result',c.result_json,'error',c.error_json)),'[]'::jsonb)
    into v_part
  from jsonb_array_elements(p_claims) x
  join public.invoice_operation_chunks c
    on c.id=case when coalesce(x->>'chunk_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x->>'chunk_id')::uuid end
  where x->>'phase'='QUEUE_DOCUMENT';
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  return coalesce(v_result,'[]'::jsonb);
end;
$function$;

alter function private._invoice_generation_advance_core_v8(jsonb,timestamptz) OWNER TO CURRENT_USER;
revoke all on function private._invoice_generation_advance_core_v8(jsonb,timestamptz) from public,anon,authenticated;
grant execute on function private._invoice_generation_advance_core_v8(jsonb,timestamptz) to service_role;

create or replace function private._invoice_issue_advance_core_v8(
  p_claims jsonb,
  p_now_utc timestamptz
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_result jsonb:='[]'::jsonb;
  v_part jsonb;
begin
  if p_claims is null or jsonb_typeof(p_claims) is distinct from 'array' then
    raise exception using errcode='22023',
      message='p_claims must be a JSON array containing 1..100 claims';
  end if;
  if jsonb_array_length(p_claims) < 1 or jsonb_array_length(p_claims) > 100 then
    raise exception using errcode='22023',
      message='p_claims must be a JSON array containing 1..100 claims';
  end if;

  -- VALIDATE preserves stable issue blocker codes and makes no legal transition.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','')~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      then (x->>'chunk_id')::uuid end chunk_id
    from jsonb_array_elements(p_claims) x
    where x->>'phase'='VALIDATE'
  ),
  requests as materialized (
    select c.id chunk_id,c.operation_id,c.entity_id invoice_id,
      case when pg_input_is_valid(
          nullif(c.payload_json->>'evaluation_date',''),'date')
        then(c.payload_json->>'evaluation_date')::date end
        evaluation_date,
      jsonb_build_object(
        'request_key',c.id::text,
        'invoice_id',c.entity_id,
        'operation_id',c.operation_id,
        'expected_revision',case
          when coalesce(c.payload_json->>'source_revision','')~'^[0-9]+$'
            then to_jsonb((c.payload_json->>'source_revision')::bigint)
          else c.payload_json->'source_revision'
        end,
        'allow_early',coalesce(c.payload_json->'allow_early','false'::jsonb),
        'deliver',coalesce(c.payload_json->'deliver','false'::jsonb),
        'recipient_set',coalesce(c.payload_json#>'{delivery_intent,recipient_set}',
          '[]'::jsonb),
        'cc',coalesce(c.payload_json#>'{delivery_intent,cc}','[]'::jsonb),
        'bcc',coalesce(c.payload_json#>'{delivery_intent,bcc}','[]'::jsonb)
      ) request_json
    from ids x
    join public.invoice_operation_chunks c on c.id=x.chunk_id
  ),
  validation_groups as materialized (
    select r.evaluation_date,
      jsonb_agg(r.request_json order by r.chunk_id) request_json
    from requests r
    group by r.evaluation_date
  ),
  shared_validation as materialized (
    select v.*
    from validation_groups g
    cross join lateral private._invoice_issue_validate_batch(
      g.request_json,g.evaluation_date) v
  ),
  eval as materialized (
    select r.chunk_id,r.operation_id,r.invoice_id,
      array(select jsonb_array_elements_text(
        coalesce(v.hard_blocker_codes,'[]'::jsonb))) blockers
    from requests r
    left join shared_validation v
      on v.request_key=r.chunk_id::text and v.invoice_id=r.invoice_id
  ),
  updated as (
    update public.invoice_operation_chunks c set
      phase=case when cardinality(e.blockers)=0 then 'FREEZE' else 'BLOCKED' end,
      status=case when cardinality(e.blockers)=0 then 'QUEUED' else 'BLOCKED' end,
      error_json=case when cardinality(e.blockers)=0 then null else
        jsonb_build_object('code',e.blockers[1],'blocker_codes',to_jsonb(e.blockers),'invoice_id',e.invoice_id) end,
      progress_json=jsonb_build_object('status_message',
        case when cardinality(e.blockers)=0 then 'Issue validation passed' else 'Issue blocked' end,
        'blocker_codes',to_jsonb(e.blockers)),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from eval e where c.id=e.chunk_id returning c.id,c.status,c.phase,c.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]')
    into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]');

  -- FREEZE: immutable legal/render snapshot; invoice deliberately remains DRAFT.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (x->>'chunk_id')::uuid end chunk_id from jsonb_array_elements(p_claims) x where x->>'phase'='FREEZE'
  ),
  freeze_route_requests as materialized (
    select c.id chunk_id,
      case when pg_input_is_valid(
          nullif(c.payload_json->>'evaluation_date',''),'date')
        then(c.payload_json->>'evaluation_date')::date end
        evaluation_date,
      jsonb_build_object(
      'request_key',c.id::text,
      'invoice_id',c.entity_id,
      'recipient_set',coalesce(
        c.payload_json#>'{delivery_intent,recipient_set}','[]'::jsonb),
      'cc',coalesce(c.payload_json#>'{delivery_intent,cc}','[]'::jsonb),
      'bcc',coalesce(c.payload_json#>'{delivery_intent,bcc}','[]'::jsonb),
      'delivery_policy',coalesce(
        c.payload_json#>>'{delivery_intent,delivery_policy}','ATTACH'),
      'template_version',coalesce(
        c.payload_json#>>'{delivery_intent,template_version}',
        'invoice-delivery-v1')
    ) request_json
    from ids x join public.invoice_operation_chunks c on c.id=x.chunk_id
  ),
  freeze_route_groups as materialized (
    select q.evaluation_date,
      jsonb_agg(q.request_json order by q.chunk_id) request_json
    from freeze_route_requests q
    group by q.evaluation_date
  ),
  frozen_routes as materialized (
    select r.*
    from freeze_route_groups g
    cross join lateral private._invoice_delivery_routes_batch(
      g.request_json,g.evaluation_date) r
  ),
  freeze_seed as materialized (
    select c.id chunk_id,c.operation_id,c.entity_id invoice_id,c.payload_json,
      i.document_revision,i.invoice_no,i.client_id,
      frozen_clock.issue_at_utc,
      frozen_clock.issue_at_utc tax_point_utc,
      frozen_clock.issue_at_utc+make_interval(days=>coalesce(
        case when pg_input_is_valid(nullif(i.header_snapshot_json->>'payment_terms_days',''),'integer')
          then greatest(0,least(3650,(i.header_snapshot_json->>'payment_terms_days')::integer)) end,
        cl.payment_terms_days,30)) due_at_utc,
      rr.request_json routing_request,
      jsonb_build_object(
        'request_key',dr.request_key,
        'to',coalesce(dr.canonical_to,'[]'::jsonb),
        'cc',coalesce(dr.canonical_cc,'[]'::jsonb),
        'bcc',coalesce(dr.canonical_bcc,'[]'::jsonb),
        'recipient_set_hash',dr.recipient_set_hash,
        'route_policy_hash',dr.route_policy_hash,
        'route_source',dr.route_source,
        'do_not_send',dr.do_not_send,
        'delivery_suppressed',dr.delivery_suppressed,
        'suppression_reason',dr.suppression_reason,
        'client_settings_id',dr.client_settings_id,
        'contract_settings_ids',dr.contract_settings_ids,
        'effective_date',dr.effective_date,
        'client_id',dr.client_id,
        'invoice_group_identity',dr.invoice_group_identity,
        'self_bill',dr.self_bill,
        'grouping_identity',dr.grouping_identity,
        'template_version',coalesce(c.payload_json#>>'{delivery_intent,template_version}','invoice-delivery-v1'),
        'delivery_policy',upper(coalesce(c.payload_json#>>'{delivery_intent,delivery_policy}','ATTACH')),
        'warning_codes',coalesce(dr.warning_codes,'[]'::jsonb),
        'blocker_codes',coalesce(dr.blocker_codes,'[]'::jsonb),
        'evaluated_date',dr.effective_date
      ) delivery_route,
      coalesce(nullif(c.payload_json->>'delivery_request_token',''),
        'ISSUE:'||coalesce(c.payload_json->>'command_token',c.id::text)) delivery_request_token,
      coalesce(c.payload_json->'deliver','false'::jsonb) deliver
    from ids x
    join public.invoice_operation_chunks c on c.id=x.chunk_id
    join public.invoices i on i.id=c.entity_id and i.status='DRAFT'
    join public.clients cl on cl.id=i.client_id
    cross join lateral (
      select case when pg_input_is_valid(nullif(c.payload_json->>'frozen_issue_at_utc',''),'timestamptz')
        then (c.payload_json->>'frozen_issue_at_utc')::timestamptz else v_now end issue_at_utc
    ) frozen_clock
    left join frozen_routes dr on dr.request_key=c.id::text and dr.invoice_id=i.id
    left join freeze_route_requests rr on rr.chunk_id=c.id
  ),
  presentation_requests as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
        'request_key',fs.chunk_id::text,
        'entity_type','INVOICE',
        'entity_id',fs.invoice_id,
        'purpose','FINAL_ISSUE',
        'template_version','invoice-professional-v2',
        'issue_at_utc',fs.issue_at_utc,
        'tax_point_utc',fs.tax_point_utc,
        'due_at_utc',fs.due_at_utc
      ) order by fs.chunk_id),'[]'::jsonb) requests
    from freeze_seed fs
  ),
  presentation_batch as materialized (
    select p.*
    from (
      select pr.requests
      from presentation_requests pr
      where jsonb_typeof(pr.requests)='array'
        and jsonb_array_length(pr.requests)>0
    ) pr
    cross join lateral private._invoice_presentation_snapshot_batch(
      pr.requests,v_now) p
  ),
  frozen as materialized (
    select fs.chunk_id,fs.operation_id,fs.invoice_id,fs.payload_json,
      fs.document_revision,fs.invoice_no,fs.client_id,
      (
        pb.snapshot_json
        || jsonb_build_object(
          'snapshot_schema_version','FINAL_ISSUE_PRESENTATION_SNAPSHOT_V5',
          'issue_date_utc',fs.issue_at_utc,
          'tax_point_utc',fs.tax_point_utc,
          'due_date_utc',fs.due_at_utc,
          'routing_request',coalesce(fs.routing_request,'{}'::jsonb),
          'delivery_route',coalesce(fs.delivery_route,'{}'::jsonb),
          'delivery_intent',coalesce(fs.payload_json->'delivery_intent','{}'::jsonb),
          'delivery_request_token',fs.delivery_request_token,
          'deliver',fs.deliver,
          'presentation_model_hash',coalesce(pb.presentation_model->>'presentation_model_hash',pb.snapshot_json->>'presentation_model_hash',encode(digest(coalesce(pb.presentation_model,'{}'::jsonb)::text,'sha256'),'hex'))
        )
      ) snapshot,
      pb.valid presentation_valid,
      pb.error_code presentation_error_code,
      pb.error_detail presentation_error_detail
    from freeze_seed fs
    left join presentation_batch pb on pb.request_key=fs.chunk_id::text
  ),
  existing_versions as materialized (
    select f.*,v.id existing_document_version_id,v.operation_id doc_operation_id,
      o.control_version doc_control_version,v.status document_status,
      v.snapshot_hash existing_snapshot_hash
    from frozen f join public.invoice_document_versions v
      on coalesce(f.presentation_valid,false) is true
      and v.entity_type='INVOICE' and v.entity_id=f.invoice_id
      and v.purpose='FINAL_ISSUE'
      and v.snapshot_hash=encode(digest(f.snapshot::text,'sha256'),'hex')
      and v.template_version='invoice-professional-v2'
      and v.status in('PLANNING','WAITING_FOR_INPUTS','RENDERING',
        'ASSEMBLING','VERIFYING','READY')
    join public.invoice_operations o on o.id=v.operation_id
  ),
  doc_ops as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,created_at_utc,updated_at_utc)
    select f.operation_id,'BUILD_DOCUMENT','INVOICE',f.invoice_id,o.actor_user_id,
      encode(digest('FINAL_ISSUE|'||f.invoice_id||'|'||
        encode(digest(f.snapshot::text,'sha256'),'hex')||
        '|invoice-professional-v2','sha256'),'hex'),
      'QUEUED','BUILD_MANIFEST',850,f.document_revision::text,'invoice-professional-v2',
      jsonb_build_object('invoice_id',f.invoice_id,'purpose','FINAL_ISSUE'),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,
      nextval('public.invoice_operation_change_seq'),v_now,v_now
    from frozen f join public.invoice_operations o on o.id=f.operation_id
    where coalesce(f.presentation_valid,false) is true
      and not exists(select 1 from existing_versions e where e.chunk_id=f.chunk_id)
    on conflict(idempotency_key) where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,850),updated_at_utc=v_now
    returning *
  ),
  selected as materialized (
    select f.chunk_id,f.operation_id,f.invoice_id,f.payload_json,f.document_revision,
      f.invoice_no,f.client_id,f.snapshot,d.id doc_operation_id,d.control_version doc_control_version,
      null::uuid existing_document_version_id,null::text document_status,
      null::text existing_snapshot_hash
    from frozen f join doc_ops d on d.entity_id=f.invoice_id
    where coalesce(f.presentation_valid,false) is true
    union all
    select f.chunk_id,f.operation_id,f.invoice_id,f.payload_json,f.document_revision,
      f.invoice_no,f.client_id,f.snapshot,e.doc_operation_id,e.doc_control_version,
      e.existing_document_version_id,e.document_status,e.existing_snapshot_hash
    from frozen f join existing_versions e on e.chunk_id=f.chunk_id
    where coalesce(f.presentation_valid,false) is true
  ),
  presentation_blocked as (
    update public.invoice_operation_chunks c set
      status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
      error_json=jsonb_build_object(
        'code',coalesce(f.presentation_error_code,'FINAL_ISSUE_PRESENTATION_INVALID'),
        'detail',coalesce(f.presentation_error_detail,'{}'::jsonb),
        'invoice_id',f.invoice_id),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from frozen f
    where c.id=f.chunk_id and coalesce(f.presentation_valid,false) is not true
    returning c.id,c.status,c.phase,c.document_version_id
  ),
  versions as materialized (
    insert into public.invoice_document_versions(entity_type,entity_id,purpose,operation_id,source_revision,
      template_version,status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select 'INVOICE',s.invoice_id,'FINAL_ISSUE',s.doc_operation_id,s.document_revision::text,
      'invoice-professional-v2','PLANNING',s.snapshot,encode(digest(s.snapshot::text,'sha256'),'hex'),
      '[]',encode(digest('[]','sha256'),'hex'),v_now
    from selected s
    where s.existing_document_version_id is null
    on conflict(entity_type,entity_id,purpose,snapshot_hash,template_version)
      where purpose='FINAL_ISSUE'
        and status in ('PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning id,entity_id,operation_id,snapshot_hash
  ),
  exact_versions as materialized (
    select s.*,coalesce(s.existing_document_version_id,v.id) document_version_id,
      coalesce(s.existing_snapshot_hash,v.snapshot_hash) snapshot_hash,
      coalesce(s.document_status,'PLANNING') exact_document_status
    from selected s left join versions v
      on v.entity_id=s.invoice_id and v.operation_id=s.doc_operation_id
  ),
  doc_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,status,priority,run_after_utc,payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select s.doc_operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',
        s.document_version_id::text,s.document_revision::text,
        'invoice-professional-v2','1'),'sha256'),'hex'),
      0,'INVOICE',s.invoice_id,s.document_version_id,
      'QUEUED',850,v_now,jsonb_build_object('purpose','FINAL_ISSUE'),s.doc_control_version,v_now,v_now
    from exact_versions s
    where s.exact_document_status<>'READY'
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing returning id
  ),
  invoice_state as (
    update public.invoices i set issue_state='PREPARING_DOCUMENT',
      active_issue_operation_id=s.operation_id,
      active_document_operation_id=case when s.exact_document_status='READY'
        then i.active_document_operation_id else s.doc_operation_id end,
      document_state=case when s.exact_document_status='READY'
        then i.document_state else 'PREPARING' end,updated_at=v_now
    from exact_versions s where i.id=s.invoice_id and i.status='DRAFT' returning i.id
  ),
  advanced as (
    update public.invoice_operation_chunks c set
      phase=case when s.exact_document_status='READY' then 'FINALISE' else 'WAIT_DOCUMENT' end,
      status=case when s.exact_document_status='READY' then 'QUEUED' else 'WAITING' end,
      document_version_id=s.document_version_id,
      payload_json=c.payload_json||jsonb_build_object('frozen_document_revision',s.document_revision,
        'document_version_id',s.document_version_id,'document_operation_id',s.doc_operation_id,
        'snapshot_hash',s.snapshot_hash,
        'routing_request',s.snapshot->'routing_request',
        'frozen_delivery_route',s.snapshot->'delivery_route',
        'delivery_request_token',s.snapshot->>'delivery_request_token'),
      progress_json=jsonb_build_object('status_message',
        case when s.exact_document_status='READY'
          then 'Exact final document is ready' else 'Final issue document is preparing' end),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from exact_versions s where c.id=s.chunk_id
    returning c.id,c.status,c.phase,c.document_version_id
  ),
  freeze_outcomes as (
    select id,status,phase,document_version_id from advanced
    union all
    select id,status,phase,document_version_id from presentation_blocked
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,
    'document_version_id',document_version_id)),'[]') into v_part from freeze_outcomes;
  v_result:=v_result||coalesce(v_part,'[]');

  -- WAIT_DOCUMENT observes only the exact row and never R2.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (x->>'chunk_id')::uuid end chunk_id from jsonb_array_elements(p_claims) x where x->>'phase'='WAIT_DOCUMENT'
  ),
  updated as (
    update public.invoice_operation_chunks c set
      phase=case when v.status='READY' then 'FINALISE'
                 when v.status in ('FAILED','SUPERSEDED','CANCELLED') then 'BLOCKED'
                 else 'WAIT_DOCUMENT' end,
      status=case when v.status='READY' then 'QUEUED'
                  when v.status in ('FAILED','SUPERSEDED','CANCELLED') then 'BLOCKED'
                  else 'WAITING' end,
      error_json=case when v.status in ('FAILED','SUPERSEDED','CANCELLED')
        then jsonb_build_object('code','FINAL_DOCUMENT_'||v.status,'document_version_id',v.id,'detail',v.error_json)
        else null end,run_after_utc=case when v.status='READY' then v_now else c.run_after_utc end,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from ids x,public.invoice_document_versions v
    where c.id=x.chunk_id and v.id=c.document_version_id
    returning c.id,c.status,c.phase,c.error_json
  ),
  missing as (
    update public.invoice_operation_chunks c set
      phase='BLOCKED',status='BLOCKED',
      error_json=jsonb_build_object(
        'code','FINAL_DOCUMENT_VERSION_MISSING',
        'document_version_id',c.document_version_id),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from ids x
    where c.id=x.chunk_id
      and not exists(
        select 1 from public.invoice_document_versions v
        where v.id=c.document_version_id)
    returning c.id,c.status,c.phase,c.error_json
  ),
  outcomes as (
    select * from updated
    union all
    select * from missing
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]')
    into v_part from outcomes;
  v_result:=v_result||coalesce(v_part,'[]');

  -- FINALISE is the only legal issue transition and demands the exact verified version.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (x->>'chunk_id')::uuid end chunk_id from jsonb_array_elements(p_claims) x where x->>'phase'='FINALISE'
  ),
  locked_invoices as materialized (
    select invoice.id
    from ids supplied
    join public.invoice_operation_chunks carrier
      on carrier.id=supplied.chunk_id
    join public.invoices invoice
      on invoice.id=carrier.entity_id
    order by invoice.id
    for update of invoice
  ),
  eligible as materialized (
    select c.*,i.document_revision,v.id final_document_version_id,v.r2_key,v.sha256,v.size_bytes,v.page_count,
      v.verified_at_utc,
      case when pg_input_is_valid(
        nullif(v.snapshot_json->>'issue_date_utc',''),'timestamptz')
        then (v.snapshot_json->>'issue_date_utc')::timestamptz
        else v_now end issue_at,
      case when pg_input_is_valid(
        nullif(v.snapshot_json->>'tax_point_utc',''),'timestamptz')
        then (v.snapshot_json->>'tax_point_utc')::timestamptz end tax_point_at,
      case when pg_input_is_valid(
        nullif(v.snapshot_json->>'due_date_utc',''),'timestamptz')
        then (v.snapshot_json->>'due_date_utc')::timestamptz end due_at,
      v.snapshot_hash
    from ids x join public.invoice_operation_chunks c on c.id=x.chunk_id
    join locked_invoices locked_invoice on locked_invoice.id=c.entity_id
    join public.invoices i on i.id=locked_invoice.id and i.status='DRAFT'
      and i.issue_state='PREPARING_DOCUMENT'
      and i.active_issue_operation_id=c.operation_id
    join public.invoice_document_versions v on v.id=c.document_version_id and v.purpose='FINAL_ISSUE'
      and v.entity_type='INVOICE' and v.entity_id=c.entity_id
      and v.status='READY' and v.verified_at_utc is not null and v.r2_key is not null
      and v.sha256 is not null and v.size_bytes>0 and v.page_count>0
    where case when pg_input_is_valid(
        nullif(c.payload_json->>'frozen_document_revision',''),'bigint')
      then(c.payload_json->>'frozen_document_revision')::bigint=i.document_revision
      else false end
      and v.source_revision=i.document_revision::text
      and c.payload_json->>'snapshot_hash'=v.snapshot_hash
  ),
  issued as (
    update public.invoices i set status='ISSUED',status_date_utc=v_now,
      issued_at_utc=e.issue_at,due_at_utc=e.due_at,
      on_hold_reason=null,issued_document_version_id=e.final_document_version_id,
      invoice_pdf_r2_key=e.r2_key,invoice_pdf_generated_at_utc=e.verified_at_utc,
      issue_state='ISSUED',document_state='READY',active_issue_operation_id=null,
      active_document_operation_id=case
        when pg_input_is_valid(
          nullif(e.payload_json->>'document_operation_id',''),'uuid')
          then case when i.active_document_operation_id=
              (e.payload_json->>'document_operation_id')::uuid
            then null else i.active_document_operation_id end
        else i.active_document_operation_id end,updated_at=v_now
    from eligible e where i.id=e.entity_id returning i.id
  ),
  audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,after_json,reason)
    select v_now,o.actor_user_id,u.display_name,u.role,'invoice',e.entity_id::text,'INVOICE_ISSUED',
      jsonb_build_object('invoice_id',e.entity_id,'document_version_id',e.final_document_version_id,
        'issue_at_utc',e.issue_at,'tax_point_utc',e.tax_point_at,'due_at_utc',e.due_at,
        'sha256',e.sha256,'size_bytes',e.size_bytes,'page_count',e.page_count),'INVOICE_OPERATION_QUEUE'
    from eligible e join public.invoice_operations o on o.id=e.operation_id
    left join public.tms_users u on u.id=o.actor_user_id returning id
  ),
  advanced as (
    update public.invoice_operation_chunks c set
      phase=case when lower(coalesce(c.payload_json->>'deliver','false'))
        in('true','t','1','yes') then 'QUEUE_DELIVERY' else 'COMPLETE' end,
      status=case when lower(coalesce(c.payload_json->>'deliver','false'))
        in('true','t','1','yes') then 'QUEUED' else 'COMPLETE' end,
      completed_at_utc=case when lower(coalesce(
        c.payload_json->>'deliver','false')) in('true','t','1','yes')
        then null else v_now end,
      result_json=jsonb_build_object('invoice_id',e.entity_id,'document_version_id',e.final_document_version_id,
        'issue_at_utc',e.issue_at,'tax_point_utc',e.tax_point_at,'due_at_utc',e.due_at,
        'r2_key',e.r2_key,'sha256',e.sha256,'size_bytes',e.size_bytes,'page_count',e.page_count),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from eligible e where c.id=e.id
    returning c.id,c.status,c.phase,c.result_json,c.error_json
  ),
  ineligible as (
    update public.invoice_operation_chunks c
    set status='BLOCKED',phase='BLOCKED',failed_at_utc=v_now,
        error_json=jsonb_build_object(
          'code','ISSUE_FINALISE_OWNERSHIP_OR_DOCUMENT_MISMATCH',
          'invoice_id',c.entity_id,
          'document_version_id',c.document_version_id),
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from ids x
    where c.id=x.chunk_id
      and not exists(select 1 from eligible e where e.id=c.id)
    returning c.id,c.status,c.phase,c.result_json,c.error_json
  ),
  outcomes as (
    select * from advanced
    union all
    select * from ineligible
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'chunk_id',id,'status',status,'phase',phase,
    'result',result_json,'error',error_json)),'[]')
    into v_part from outcomes;
  v_result:=v_result||coalesce(v_part,'[]');

  -- QUEUE_DELIVERY durably delegates to the single delivery-routing authority.
  with ids as materialized (
    select case when coalesce(x->>'chunk_id','') ~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then (x->>'chunk_id')::uuid end chunk_id
    from jsonb_array_elements(p_claims) x
    where x->>'phase'='QUEUE_DELIVERY'
  ),
  delivery_specs as materialized (
    select c.id chunk_id,c.operation_id parent_operation_id,c.entity_id invoice_id,
      o.actor_user_id,i.issued_document_version_id,
      coalesce(c.payload_json->'delivery_intent','{}'::jsonb) delivery_intent,
      coalesce(c.payload_json->'routing_request','{}'::jsonb)
        routing_request,
      coalesce(c.payload_json->'frozen_delivery_route','{}'::jsonb)
        frozen_delivery_route,
      coalesce(nullif(c.payload_json->>'delivery_request_token',''),
        'ISSUE:'||coalesce(c.payload_json->>'command_token',c.id::text))
        delivery_request_token,
      nullif(c.payload_json#>>'{frozen_delivery_route,template_version}','')
        template_version,
      nullif(c.payload_json#>>'{frozen_delivery_route,recipient_set_hash}','')
        recipient_set_hash,
      nullif(c.payload_json#>>'{frozen_delivery_route,route_policy_hash}','')
        route_policy_hash,
      coalesce(c.payload_json#>'{frozen_delivery_route,to}','[]'::jsonb)
        canonical_to,
      coalesce(c.payload_json#>'{frozen_delivery_route,cc}','[]'::jsonb)
        canonical_cc,
      coalesce(c.payload_json#>'{frozen_delivery_route,bcc}','[]'::jsonb)
        canonical_bcc,
      lower(coalesce(
        c.payload_json#>>'{frozen_delivery_route,do_not_send}','false'))
        in('true','t','1','yes') do_not_send,
      lower(coalesce(
        c.payload_json#>>'{frozen_delivery_route,delivery_suppressed}','false'))
        in('true','t','1','yes') delivery_suppressed,
      c.payload_json#>>'{frozen_delivery_route,route_source}' route_source,
      coalesce(c.payload_json#>'{frozen_delivery_route,warning_codes}',
        '[]'::jsonb) route_warnings,
      coalesce(c.payload_json#>'{frozen_delivery_route,blocker_codes}',
        '[]'::jsonb) route_blockers,
      c.payload_json#>>'{frozen_delivery_route,route_policy_hash}' is not null
        and c.payload_json#>>'{frozen_delivery_route,recipient_set_hash}'
          is not null
        and c.payload_json#>>'{frozen_delivery_route,template_version}'
          is not null
        and upper(coalesce(
          c.payload_json#>>'{frozen_delivery_route,delivery_policy}',''))
          in('ATTACH','SPLIT','SECURE_LINK')
        and lower(coalesce(
          c.payload_json#>>'{frozen_delivery_route,do_not_send}','false'))
          not in('true','t','1','yes')
        and lower(coalesce(
          c.payload_json#>>'{frozen_delivery_route,delivery_suppressed}','false'))
          not in('true','t','1','yes')
        and (case
          when jsonb_typeof(c.payload_json#>'{frozen_delivery_route,blocker_codes}')='array'
            then jsonb_array_length(c.payload_json#>'{frozen_delivery_route,blocker_codes}')
          when c.payload_json#>'{frozen_delivery_route,blocker_codes}' is null then 0
          else 1
        end)=0
        frozen_route_usable,
      coalesce(case when coalesce(c.payload_json#>>'{delivery_intent,part_number}','') ~
        '^[0-9]+$' then(c.payload_json#>>'{delivery_intent,part_number}')::integer end,1)
        part_number,
      case when upper(coalesce(
          c.payload_json#>>'{delivery_intent,delivery_policy}','')) in(
            'ATTACH','SPLIT','SECURE_LINK')
        then upper(c.payload_json#>>'{delivery_intent,delivery_policy}')
        when upper(coalesce(
          c.payload_json#>>'{frozen_delivery_route,delivery_policy}','')) in(
            'ATTACH','SPLIT','SECURE_LINK')
        then upper(c.payload_json#>>'{frozen_delivery_route,delivery_policy}')
      end delivery_policy
    from ids x join public.invoice_operation_chunks c on c.id=x.chunk_id
    join public.invoice_operations o on o.id=c.operation_id
    join public.invoices i on i.id=c.entity_id and i.status='ISSUED'
      and i.issued_document_version_id=c.document_version_id
  ),
  delivery_groups as materialized (
    select d.parent_operation_id,
      (array_agg(d.actor_user_id order by d.chunk_id))[1] actor_user_id,
      (array_agg(d.template_version order by d.chunk_id))[1] template_version,
      encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
        d.route_policy_hash),'||' order by d.invoice_id),'sha256'),'hex')
        route_policy_hash,
      (array_agg(d.delivery_policy order by d.chunk_id))[1] delivery_policy,
      array_agg(d.invoice_id order by d.invoice_id) invoice_ids,
      array_agg(d.issued_document_version_id order by d.invoice_id)
        issued_document_version_ids,
      array_agg(d.delivery_request_token order by d.invoice_id)
        delivery_request_tokens,
      count(*)::integer unit_count,
      encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
        d.issued_document_version_id::text,d.delivery_request_token),
        '||' order by d.invoice_id),'sha256'),'hex') group_request_hash,
      encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
        d.issued_document_version_id::text,d.delivery_request_token,
        d.route_policy_hash),
        '||' order by d.invoice_id),'sha256'),'hex') delivery_revision,
      encode(digest(concat_ws('|','DELIVER_INVOICES',d.parent_operation_id::text,
        encode(digest(string_agg(concat_ws('|',d.invoice_id::text,
          d.issued_document_version_id::text,d.delivery_request_token),
          '||' order by d.invoice_id),'sha256'),'hex')),'sha256'),'hex')
        delivery_key
    from delivery_specs d
    group by d.parent_operation_id
  ),
  existing_delivery as materialized (
    select g.parent_operation_id,o.id operation_id,o.control_version,o.status
    from delivery_groups g join lateral(
      select x.* from public.invoice_operations x
      where x.idempotency_key=g.delivery_key
        and x.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED','COMPLETE')
      order by(x.status='COMPLETE') desc,x.created_at_utc desc limit 1
    ) o on true
  ),
  inserted_delivery as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,
      entity_type,entity_id,actor_user_id,idempotency_key,status,phase,priority,
      source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,requires_user_action,
      error_json,created_at_utc,updated_at_utc)
    select g.parent_operation_id,'DELIVER_INVOICES','INVOICE_BATCH',null,
      g.actor_user_id,g.delivery_key,'QUEUED','PREPARE',700,
      g.delivery_revision,g.template_version,
      jsonb_build_object('invoice_ids',to_jsonb(g.invoice_ids),
        'issued_document_version_ids',to_jsonb(g.issued_document_version_ids),
        'template_version',g.template_version,
        'delivery_request_tokens',to_jsonb(g.delivery_request_tokens),
        'group_request_hash',g.group_request_hash,
        'route_policy_hash',g.route_policy_hash,
        'delivery_policy',g.delivery_policy),
      jsonb_build_object(
        'delivery_request_tokens',to_jsonb(g.delivery_request_tokens),
        'group_request_hash',g.group_request_hash,
        'route_policy_hash',g.route_policy_hash,
        'processor_policy',parent.config_json->'processor_policy'),
      jsonb_build_object('status_message','Batch delivery preparation queued'),
      g.unit_count,g.unit_count,1,nextval('public.invoice_operation_change_seq'),
      false,null,v_now,v_now
    from delivery_groups g
    join public.invoice_operations parent on parent.id=g.parent_operation_id
    where not exists(
      select 1 from existing_delivery e
      where e.parent_operation_id=g.parent_operation_id)
    on conflict do nothing
    returning *
  ),
  selected_delivery_groups as materialized (
    select g.*,coalesce(e.operation_id,n.id) delivery_operation_id,
      coalesce(e.control_version,n.control_version) delivery_control_version,
      coalesce(e.status,n.status) delivery_status
    from delivery_groups g
    left join existing_delivery e
      on e.parent_operation_id=g.parent_operation_id
    left join inserted_delivery n on n.idempotency_key=g.delivery_key
  ),
  selected_delivery as materialized (
    select d.*,g.delivery_operation_id,g.delivery_control_version,
      g.delivery_status
    from delivery_specs d
    join selected_delivery_groups g
      on g.parent_operation_id=d.parent_operation_id
  ),
  delivery_chunk_specs as materialized (
    select d.*,gen_random_uuid() delivery_chunk_id
    from selected_delivery d
    where d.delivery_status<>'COMPLETE'
  ),
  delivery_chunks as (
    insert into public.invoice_operation_chunks(id,operation_id,chunk_type,phase,
      work_key,sequence_no,entity_type,entity_id,document_version_id,status,priority,
      run_after_utc,payload_json,error_json,operation_control_version,
      created_at_utc,updated_at_utc)
    select d.delivery_chunk_id,d.delivery_operation_id,'DELIVERY_PREPARE',
      case when d.frozen_route_usable then 'PREPARE' else 'BLOCKED' end,
      encode(digest(concat_ws('|','DELIVERY_PREPARE',
        d.issued_document_version_id::text,d.route_policy_hash,
        d.template_version,d.part_number::text,d.delivery_request_token),
        'sha256'),'hex'),
      row_number() over(partition by d.delivery_operation_id
        order by d.invoice_id)::integer-1,
      'INVOICE',d.invoice_id,d.issued_document_version_id,
      case when d.frozen_route_usable then 'QUEUED' else 'BLOCKED' end,
      700,v_now,
      jsonb_build_object('request_key',d.delivery_chunk_id::text,
        'invoice_id',d.invoice_id,
        'issued_document_version_id',d.issued_document_version_id,
        'recipient_set',d.canonical_to,'cc',d.canonical_cc,'bcc',d.canonical_bcc,
        'recipient_set_hash',d.recipient_set_hash,'template_version',d.template_version,
        'route_policy_hash',d.route_policy_hash,
        'delivery_part_number',d.part_number,'do_not_send',d.do_not_send,
        'delivery_suppressed',d.delivery_suppressed,
        'delivery_policy',d.delivery_policy,
        'route_source',d.route_source,
        'delivery_request_token',d.delivery_request_token,
        'routing_request',d.routing_request,
        'frozen_delivery_route',d.frozen_delivery_route),
      case when d.frozen_route_usable then null else jsonb_build_object(
        'code','FROZEN_DELIVERY_ROUTE_UNUSABLE',
        'frozen_route',d.frozen_delivery_route,
        'route_blockers',d.route_blockers) end,
      d.delivery_control_version,v_now,v_now
    from delivery_chunk_specs d
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing
    returning id
  ),
  completed_delivery_request as (
    update public.invoice_operation_chunks c set status='COMPLETE',phase='COMPLETE',
      completed_at_utc=v_now,updated_at_utc=v_now,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      payload_json=coalesce(c.payload_json,'{}'::jsonb)
        || jsonb_build_object(
          'blocked_for_sending',
          not d.frozen_route_usable
        ),
      result_json=coalesce(c.result_json,'{}')||jsonb_build_object(
        'delivery_operation_id',d.delivery_operation_id,
        'delivery_status',case when d.frozen_route_usable
          then d.delivery_status else 'BLOCKED' end,
        'delivery_requested',true,
        'delivery_request_token',d.delivery_request_token,
        'delivery_blocker',case when d.frozen_route_usable then null
          else jsonb_build_object('code','FROZEN_DELIVERY_ROUTE_UNUSABLE',
            'frozen_route',d.frozen_delivery_route,
            'route_blockers',d.route_blockers) end)
    from selected_delivery d where c.id=d.chunk_id
    returning c.id,c.status,c.phase,c.result_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,
    'phase',phase,'result',result_json)),'[]') into v_part
  from completed_delivery_request;
  v_result:=v_result||coalesce(v_part,'[]');

  return coalesce(v_result,'[]'::jsonb);
end;
$function$;

alter function private._invoice_issue_advance_core_v8(jsonb,timestamptz) OWNER TO CURRENT_USER;
revoke all on function private._invoice_issue_advance_core_v8(jsonb,timestamptz) from public,anon,authenticated;
grant execute on function private._invoice_issue_advance_core_v8(jsonb,timestamptz) to service_role;

create or replace function private._invoice_batch_manifest_advance_v2(
  p_claims jsonb,
  p_action text,
  p_now_utc timestamptz default now()
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_now timestamptz := coalesce(p_now_utc,now());
  v_action text := upper(btrim(coalesce(p_action,'')));
  v_chunk_type text;
  v_result jsonb := '[]'::jsonb;
  v_expander record;
  v_page jsonb;
  v_page_rows jsonb;
  v_has_more boolean;
  v_next_cursor jsonb;
  v_row_count integer;
  v_manifest_generation integer;
  v_release_ids uuid[];
  v_remaining integer;
  v_requests jsonb;
  v_ensure jsonb;
begin
  if v_action not in ('GENERATE','ISSUE') then
    raise exception using
      errcode='22023',
      message='INVOICE_BATCH_MANIFEST_ACTION_INVALID';
  end if;

  if jsonb_typeof(coalesce(p_claims,'null'::jsonb)) is distinct from 'array'
     or jsonb_array_length(p_claims) < 1
     or jsonb_array_length(p_claims) > 100 then
    raise exception using
      errcode='22023',
      message='p_claims must contain 1..100 claims';
  end if;

  v_chunk_type := case
    when v_action='GENERATE' then 'GENERATION_GROUP'
    else 'ISSUE_INVOICE'
  end;

  for v_expander in
    select
      c.*,
      o.actor_user_id,
      o.control_version root_control_version,
      o.manifest_generation root_manifest_generation,
      o.input_json root_input_json
    from jsonb_array_elements(p_claims) claim
    join public.invoice_operation_chunks c
      on c.id = case
        when pg_input_is_valid(coalesce(claim->>'chunk_id',''),'uuid')
          then (claim->>'chunk_id')::uuid
      end
    join public.invoice_operations o on o.id=c.operation_id
    where c.chunk_type=v_chunk_type
      and c.phase in ('BUILD_MANIFEST','RELEASE_MANIFEST')
      and coalesce(c.payload_json->>'is_selection_expander','false')
        in ('true','t','1','yes','on')
    order by c.id
  loop
    v_manifest_generation := greatest(
      1,
      coalesce(v_expander.root_manifest_generation,0),
      case
        when coalesce(v_expander.payload_json->>'manifest_generation','')
          ~ '^[1-9][0-9]{0,8}$'
          then (v_expander.payload_json->>'manifest_generation')::integer
        else 1
      end
    );

    if v_expander.phase='BUILD_MANIFEST' then
      begin
        v_page := case
          when v_action='GENERATE' then
            private._invoice_batch_generate_candidate_rows_v2(
              (case
                when jsonb_typeof(v_expander.payload_json->'query')='object'
                  then v_expander.payload_json->'query'
                else '{}'::jsonb
              end)
              || jsonb_build_object(
                'contract_version','INVOICE_BATCH_QUERY_V2',
                'action',v_action,
                'mode','EXPAND_SELECTION',
                'page_size',250,
                'cursor',case
                  when jsonb_typeof(v_expander.payload_json->'cursor')='object'
                    then v_expander.payload_json->'cursor'
                  else '{}'::jsonb
                end,
                'selection',coalesce(
                  v_expander.payload_json#>'{selection_contract,selection}',
                  v_expander.payload_json#>'{query,selection}'
                )
              ),
              v_now
            )
          else
            private._invoice_batch_issue_candidate_rows_v2(
              (case
                when jsonb_typeof(v_expander.payload_json->'query')='object'
                  then v_expander.payload_json->'query'
                else '{}'::jsonb
              end)
              || jsonb_build_object(
                'contract_version','INVOICE_BATCH_QUERY_V2',
                'action',v_action,
                'mode','EXPAND_SELECTION',
                'page_size',250,
                'cursor',case
                  when jsonb_typeof(v_expander.payload_json->'cursor')='object'
                    then v_expander.payload_json->'cursor'
                  else '{}'::jsonb
                end,
                'selection',coalesce(
                  v_expander.payload_json#>'{selection_contract,selection}',
                  v_expander.payload_json#>'{query,selection}'
                )
              ),
              v_now
            )
        end;
      exception
        when serialization_failure then
          update public.invoice_operation_chunks c
          set
            status='SUPERSEDED',
            phase='SOURCE_CHANGED',
            manifest_committed=true,
            result_visible=(
              coalesce(c.payload_json->>'manifest_outcome','') <> 'EXCLUDED'
            ),
            result_json=coalesce(c.result_json,'{}'::jsonb)
              || jsonb_build_object(
                'result_category','CHANGED',
                'code','BATCH_SNAPSHOT_CHANGED_DURING_EXPANSION'
              ),
            completed_at_utc=v_now,
            updated_at_utc=v_now
          where c.operation_id=v_expander.operation_id
            and c.is_manifest_member
            and c.manifest_generation=v_manifest_generation
            and not c.manifest_committed;

          update public.invoice_operation_chunks c
          set
            status='BLOCKED',
            phase='SOURCE_CHANGED',
            error_json=jsonb_build_object(
              'code','BATCH_SNAPSHOT_CHANGED_DURING_EXPANSION'
            ),
            completed_at_utc=v_now,
            lease_owner=null,
            lease_token=null,
            lease_expires_at_utc=null,
            updated_at_utc=v_now
          where c.id=v_expander.id;

          update public.invoice_operations o
          set
            status='BLOCKED',
            phase='SOURCE_CHANGED',
            manifest_committed=false,
            release_complete=false,
            requires_user_action=true,
            error_json=jsonb_build_object(
              'code','BATCH_SNAPSHOT_CHANGED_DURING_EXPANSION'
            ),
            progress_json=coalesce(o.progress_json,'{}'::jsonb)
              || jsonb_build_object(
                'selection_expansion_pending',false,
                'manifest_committed',false,
                'manifest_status','SUPERSEDED',
                'release_pending_total',0,
                'release_complete',false,
                'superseded_manifest_generation',
                  v_manifest_generation,
                'status_message','Candidate data changed; reload the selection'
              ),
            updated_at_utc=v_now,
            change_seq=nextval('public.invoice_operation_change_seq')
          where o.id=v_expander.operation_id;

          v_result := v_result || jsonb_build_array(jsonb_build_object(
            'chunk_id',v_expander.id,
            'status','BLOCKED',
            'phase','SOURCE_CHANGED',
            'error',jsonb_build_object(
              'code','BATCH_SNAPSHOT_CHANGED_DURING_EXPANSION'
            )
          ));
          continue;
      end;

      v_page_rows := case
        when jsonb_typeof(v_page->'rows')='array' then v_page->'rows'
        else '[]'::jsonb
      end;
      v_row_count := jsonb_array_length(v_page_rows);
      v_has_more := coalesce(
        (v_page#>>'{page,has_more}')::boolean,
        false
      );
      v_next_cursor := case
        when jsonb_typeof(v_page#>'{page,next_cursor_values}')='object'
          then v_page#>'{page,next_cursor_values}'
        else '{}'::jsonb
      end;

      insert into public.invoice_operation_chunks(
        operation_id,
        chunk_type,
        phase,
        work_key,
        sequence_no,
        level_no,
        entity_type,
        entity_id,
        status,
        priority,
        run_after_utc,
        payload_json,
        progress_json,
        result_json,
        operation_control_version,
        manifest_generation,
        is_manifest_member,
        manifest_committed,
        result_visible,
        created_at_utc,
        updated_at_utc
      )
      select
        v_expander.operation_id,
        v_chunk_type,
        'AWAITING_MANIFEST_COMMIT',
        private._invoice_batch_hash_v2(jsonb_build_object(
          'root_operation_id',v_expander.operation_id,
          'manifest_generation',v_manifest_generation,
          'selection_key',row_json->>'selection_key',
          'source_revision',coalesce(
            row_json->>'source_revision',
            row_json->>'document_revision'
          ),
          'outcome',case
            when coalesce((row_json->>'selectable')::boolean,false)
             and coalesce((row_json->>'selected')::boolean,false)
              then 'SELECTED'
            when coalesce((row_json->>'selectable')::boolean,false)
              then 'EXCLUDED'
            when coalesce(row_json->>'row_status','')='IN_PROGRESS'
              then 'ALREADY_ACTIVE'
            else 'BLOCKED'
          end
        )),
        coalesce(
          case
            when coalesce(v_expander.payload_json->>'scanned','')
              ~ '^[0-9]{1,9}$'
              then (v_expander.payload_json->>'scanned')::integer
            else 0
          end,
          0
        ) + row_item.ordinality::integer,
        0,
        'OPERATION',
        v_expander.operation_id,
        'WAITING',
        greatest(
          coalesce(v_expander.priority,case when v_action='ISSUE' then 850 else 600 end),
          case when v_action='ISSUE' then 850 else 600 end
        ),
        v_now,
        (
          case
            when v_action='GENERATE'
             and jsonb_typeof(row_json->'command_payload')='object'
              then row_json->'command_payload'
            else '{}'::jsonb
          end
        )
        || jsonb_build_object(
          'contract_version','INVOICE_BATCH_MANIFEST_CARRIER_V2',
          'selection_key',row_json->>'selection_key',
          'group_key',row_json->>'group_key',
          'manifest_generation',v_manifest_generation,
          'is_manifest_member',true,
          'manifest_outcome',case
            when coalesce((row_json->>'selectable')::boolean,false)
             and coalesce((row_json->>'selected')::boolean,false)
              then 'SELECTED'
            when coalesce((row_json->>'selectable')::boolean,false)
              then 'EXCLUDED'
            when coalesce(row_json->>'row_status','')='IN_PROGRESS'
              then 'ALREADY_ACTIVE'
            else 'BLOCKED'
          end,
          'result_category',case
            when coalesce((row_json->>'selectable')::boolean,false)
             and coalesce((row_json->>'selected')::boolean,false)
              then 'IN_PROGRESS'
            when coalesce((row_json->>'selectable')::boolean,false)
              then 'EXCLUDED'
            when coalesce(row_json->>'row_status','')='IN_PROGRESS'
              then 'ALREADY_ACTIVE'
            else 'BLOCKED'
          end,
          'row_kind',row_json->>'row_kind',
          'source_revision',coalesce(
            row_json->>'source_revision',
            row_json->>'document_revision'
          ),
          'expected_revision',coalesce(
            row_json->>'document_revision',
            row_json->>'source_revision'
          ),
          'invoice_id',row_json->>'invoice_id',
          'invoice_number',row_json->>'invoice_number',
          'client_id',row_json->>'client_id',
          'client_name',row_json->>'client_name',
          'candidate_display',row_json->>'candidate_display',
          'week_ending_display',row_json->>'week_ending_display',
          'currency',coalesce(row_json->>'currency','GBP'),
          'total_ex_vat',row_json->'total_ex_vat',
          'total_inc_vat',row_json->'total_inc_vat',
          'action_blocker_codes',coalesce(
            row_json->'action_blocker_codes',
            row_json->'issue_blocker_codes',
            '[]'::jsonb
          ),
          'delivery_blocker_codes',coalesce(
            row_json->'delivery_blocker_codes',
            '[]'::jsonb
          ),
          'blocked_for_sending',coalesce(
            row_json->'blocked_for_sending',
            'false'::jsonb
          ),
          'allow_early',coalesce(
            v_expander.payload_json#>'{query,filters,allow_early}',
            'false'::jsonb
          ),
          'deliver',coalesce(
            v_expander.payload_json->'deliver',
            'false'::jsonb
          ),
          'command_token',v_expander.root_input_json->>'command_token',
          'delivery_request_token',
            v_expander.payload_json->>'delivery_request_token',
          'delivery_intent',coalesce(
            v_expander.payload_json->'delivery_intent',
            '{}'::jsonb
          ),
          'parent_expander_chunk_id',v_expander.id
        ),
        jsonb_build_object(
          'contract_version','INVOICE_BATCH_PROGRESS_V2',
          'status_message','Waiting for manifest commit'
        ),
        jsonb_build_object(
          'result_category',case
            when coalesce((row_json->>'selectable')::boolean,false)
             and coalesce((row_json->>'selected')::boolean,false)
              then 'IN_PROGRESS'
            when coalesce((row_json->>'selectable')::boolean,false)
              then 'EXCLUDED'
            when coalesce(row_json->>'row_status','')='IN_PROGRESS'
              then 'ALREADY_ACTIVE'
            else 'BLOCKED'
          end,
          'badge_codes',coalesce(
            row_json->'action_blocker_codes',
            row_json->'issue_blocker_codes',
            '[]'::jsonb
          )
        ),
        v_expander.root_control_version,
        v_manifest_generation,
        true,
        false,
        false,
        v_now,
        v_now
      from jsonb_array_elements(v_page_rows)
        with ordinality row_item(row_json,ordinality)
      where nullif(row_json->>'selection_key','') is not null
      on conflict do nothing;

      update public.invoice_operation_chunks c
      set
        status='QUEUED',
        phase=case
          when v_has_more then 'BUILD_MANIFEST'
          else 'RELEASE_MANIFEST'
        end,
        run_after_utc=v_now,
        payload_json=coalesce(c.payload_json,'{}'::jsonb)
          || jsonb_build_object(
            'cursor',case when v_has_more then v_next_cursor else '{}'::jsonb end,
            'scanned',coalesce(
              case
                when coalesce(c.payload_json->>'scanned','') ~ '^[0-9]{1,9}$'
                  then (c.payload_json->>'scanned')::integer
                else 0
              end,
              0
            ) + v_row_count,
            'last_candidate_page',v_page->'page',
            'completed',not v_has_more
          ),
        progress_json=jsonb_build_object(
          'contract_version','INVOICE_BATCH_PROGRESS_V2',
          'status_message',case
            when v_has_more then 'Building selection manifest'
            else 'Manifest committed; releasing work'
          end
        ),
        lease_owner=null,
        lease_token=null,
        lease_expires_at_utc=null,
        updated_at_utc=v_now
      where c.id=v_expander.id;

      if not v_has_more then
        update public.invoice_operation_chunks member
        set
          phase='AWAITING_RELEASE',
          updated_at_utc=v_now
        where member.operation_id=v_expander.operation_id
          and member.is_manifest_member
          and member.manifest_generation=v_manifest_generation
          and not member.manifest_committed
          and member.phase='AWAITING_MANIFEST_COMMIT';
      end if;

      update public.invoice_operations o
      set
        status='QUEUED',
        phase=case
          when v_has_more then 'BUILD_MANIFEST'
          else 'RELEASE_MANIFEST'
        end,
        manifest_committed=not v_has_more,
        release_complete=false,
        progress_json=coalesce(o.progress_json,'{}'::jsonb)
          || jsonb_build_object(
            'contract_version','INVOICE_BATCH_PROGRESS_V2',
            'status_message',case
              when v_has_more then 'Building selection manifest'
              else 'Manifest committed; releasing work'
            end,
            'selection_expansion_pending',v_has_more,
            'manifest_committed',not v_has_more,
            'manifest_generation',v_manifest_generation,
            'manifest_status',case
              when v_has_more then 'BUILDING'
              else 'COMMITTED'
            end,
            'expected_scan_total',coalesce(
              case
                when coalesce(
                  o.progress_json->>'expected_scan_total',
                  ''
                ) ~ '^[0-9]+$'
                  then (
                    o.progress_json->>'expected_scan_total'
                  )::integer
              end,
              (
                select count(*)::integer
                from public.invoice_operation_chunks member
                where member.operation_id=o.id
                  and member.is_manifest_member
                  and member.manifest_generation=v_manifest_generation
              )
            ),
            'scanned_total',(
              select count(*)::integer
              from public.invoice_operation_chunks member
              where member.operation_id=o.id
                and member.is_manifest_member
                and member.manifest_generation=v_manifest_generation
            ),
            'selected_total',(
              select count(*)::integer
              from public.invoice_operation_chunks member
              where member.operation_id=o.id
                and member.is_manifest_member
                and member.manifest_generation=v_manifest_generation
                and member.payload_json->>'manifest_outcome'='SELECTED'
            ),
            'excluded_total',(
              select count(*)::integer
              from public.invoice_operation_chunks member
              where member.operation_id=o.id
                and member.is_manifest_member
                and member.manifest_generation=v_manifest_generation
                and member.payload_json->>'manifest_outcome'='EXCLUDED'
            ),
            'blocked_total',(
              select count(*)::integer
              from public.invoice_operation_chunks member
              where member.operation_id=o.id
                and member.is_manifest_member
                and member.manifest_generation=v_manifest_generation
                and member.payload_json->>'manifest_outcome'='BLOCKED'
            ),
            'already_active_total',(
              select count(*)::integer
              from public.invoice_operation_chunks member
              where member.operation_id=o.id
                and member.is_manifest_member
                and member.manifest_generation=v_manifest_generation
                and member.payload_json->>'manifest_outcome'
                  ='ALREADY_ACTIVE'
            ),
            'changed_total',(
              select count(*)::integer
              from public.invoice_operation_chunks member
              where member.operation_id=o.id
                and member.is_manifest_member
                and member.manifest_generation=v_manifest_generation
                and member.payload_json->>'manifest_outcome'='CHANGED'
            ),
            'missing_total',(
              select count(*)::integer
              from public.invoice_operation_chunks member
              where member.operation_id=o.id
                and member.is_manifest_member
                and member.manifest_generation=v_manifest_generation
                and member.payload_json->>'manifest_outcome'='MISSING'
            ),
            'release_pending_total',case
              when v_has_more then 0
              else (
                select count(*)::integer
                from public.invoice_operation_chunks member
                where member.operation_id=o.id
                  and member.is_manifest_member
                  and member.manifest_generation=v_manifest_generation
                  and member.payload_json->>'manifest_outcome'='SELECTED'
                  and not member.manifest_committed
              )
            end,
            'released_total',0,
            'release_conflict_total',0,
            'release_blocked_total',0,
            'release_complete',false,
            'committed_at_utc',case
              when v_has_more then o.progress_json->'committed_at_utc'
              else to_jsonb(v_now)
            end,
            'superseded_manifest_generation',
              o.progress_json->'superseded_manifest_generation',
            'expanded_total',(
              select count(*)::integer
              from public.invoice_operation_chunks member
              where member.operation_id=o.id
                and member.is_manifest_member
                and member.manifest_generation=v_manifest_generation
                and member.payload_json->>'manifest_outcome'='SELECTED'
            )
          ),
        chunk_count=(
          select count(*)::integer
          from public.invoice_operation_chunks member
          where member.operation_id=o.id
        ),
        updated_at_utc=v_now,
        change_seq=nextval('public.invoice_operation_change_seq')
      where o.id=v_expander.operation_id;

      v_result := v_result || jsonb_build_array(jsonb_build_object(
        'chunk_id',v_expander.id,
        'status','QUEUED',
        'phase',case
          when v_has_more then 'BUILD_MANIFEST'
          else 'RELEASE_MANIFEST'
        end,
        'result',jsonb_build_object(
          'manifest_committed',not v_has_more,
          'page',v_page->'page'
        )
      ));
      continue;
    end if;

    select coalesce(array_agg(release_member.id order by
      release_member.selection_key,
      release_member.id
    ),array[]::uuid[])
    into v_release_ids
    from (
      select c.id,c.selection_key
      from public.invoice_operation_chunks c
      where c.operation_id=v_expander.operation_id
        and c.is_manifest_member
        and c.manifest_generation=v_manifest_generation
        and not c.manifest_committed
      order by c.selection_key,c.id
      for update skip locked
      limit 250
    ) release_member;

    if cardinality(v_release_ids) > 0 then
      update public.invoice_operation_chunks c
      set
        manifest_committed=true,
        status=case c.payload_json->>'manifest_outcome'
          when 'EXCLUDED' then 'COMPLETE'
          when 'BLOCKED' then 'BLOCKED'
          when 'ALREADY_ACTIVE' then 'COMPLETE'
          else c.status
        end,
        phase=case c.payload_json->>'manifest_outcome'
          when 'EXCLUDED' then 'EXCLUDED'
          when 'BLOCKED' then 'BLOCKED'
          when 'ALREADY_ACTIVE' then 'ALREADY_ACTIVE'
          else c.phase
        end,
        result_visible=(
          c.payload_json->>'manifest_outcome' <> 'EXCLUDED'
        ),
        completed_at_utc=case
          when c.payload_json->>'manifest_outcome'
            in ('EXCLUDED','BLOCKED','ALREADY_ACTIVE')
            then v_now
          else c.completed_at_utc
        end,
        updated_at_utc=v_now
      where c.id=any(v_release_ids)
        and c.payload_json->>'manifest_outcome' <> 'SELECTED';

      if v_action='GENERATE' then
        update public.invoice_operation_chunks c
        set
          manifest_committed=true,
          entity_type='CLIENT',
          entity_id=case
            when pg_input_is_valid(coalesce(c.payload_json->>'client_id',''),'uuid')
              then (c.payload_json->>'client_id')::uuid
          end,
          status='QUEUED',
          phase='VALIDATE_SOURCES',
          result_visible=true,
          run_after_utc=v_now,
          progress_json=jsonb_build_object(
            'contract_version','INVOICE_BATCH_PROGRESS_V2',
            'status_message','Queued for invoice generation'
          ),
          updated_at_utc=v_now
        where c.id=any(v_release_ids)
          and c.payload_json->>'manifest_outcome'='SELECTED'
          and coalesce(c.payload_json->>'row_kind','CREATE_INVOICE')
            ='CREATE_INVOICE';

        select coalesce(jsonb_agg(jsonb_build_object(
          'request_key',c.selection_key,
          'invoice_id',c.payload_json->>'invoice_id',
          'document_revision',c.payload_json->>'expected_revision',
          'purpose','DRAFT_PREVIEW',
          'priority',greatest(c.priority,550),
          'parent_operation_id',c.operation_id,
          'actor_user_id',v_expander.actor_user_id,
          'template_version','invoice-professional-v2'
        ) order by c.selection_key),'[]'::jsonb)
        into v_requests
        from public.invoice_operation_chunks c
        where c.id=any(v_release_ids)
          and c.payload_json->>'manifest_outcome'='SELECTED'
          and coalesce(c.payload_json->>'row_kind','CREATE_INVOICE')
            <> 'CREATE_INVOICE';

        if jsonb_array_length(v_requests) > 0 then
          v_ensure := private._invoice_document_operation_ensure_batch(
            v_requests,
            v_now
          );

          update public.invoice_operation_chunks c
          set
            manifest_committed=true,
            status=case
              when result_row->>'status'='READY' then 'COMPLETE'
              when coalesce((result_row->>'ok')::boolean,false) then 'WAITING'
              when result_row->>'code' in ('SOURCE_CHANGED','INVOICE_NOT_FOUND')
                then 'SUPERSEDED'
              else 'BLOCKED'
            end,
            phase=case
              when result_row->>'status'='READY' then 'COMPLETE'
              when coalesce((result_row->>'ok')::boolean,false)
                then 'WAITING_DOCUMENT'
              when result_row->>'code'='SOURCE_CHANGED'
                then 'SOURCE_CHANGED'
              when result_row->>'code'='INVOICE_NOT_FOUND'
                then 'SOURCE_MISSING'
              else 'BLOCKED'
            end,
            result_visible=true,
            document_version_id=case
              when pg_input_is_valid(
                coalesce(result_row->>'document_version_id',''),
                'uuid'
              ) then (result_row->>'document_version_id')::uuid
              else c.document_version_id
            end,
            result_json=coalesce(c.result_json,'{}'::jsonb)
              || jsonb_build_object(
                'result_category',case
                  when result_row->>'status'='READY' then 'REGENERATED'
                  when coalesce((result_row->>'ok')::boolean,false)
                    then 'IN_PROGRESS'
                  when result_row->>'code'='SOURCE_CHANGED'
                    then 'CHANGED'
                  when result_row->>'code'='INVOICE_NOT_FOUND'
                    then 'MISSING'
                  else 'BLOCKED'
                end,
                'document_operation_id',result_row->>'operation_id',
                'document_version_id',result_row->>'document_version_id',
                'code',result_row->>'code'
              ),
            completed_at_utc=case
              when result_row->>'status'='READY'
                or not coalesce((result_row->>'ok')::boolean,false)
                then v_now
              else null
            end,
            updated_at_utc=v_now
          from jsonb_array_elements(
            coalesce(v_ensure->'results','[]'::jsonb)
          ) result_item(result_row)
          where c.id=any(v_release_ids)
            and c.selection_key=result_row->>'request_key';
        end if;
      else
        perform i.id
        from public.invoices i
        where i.id in (
          select (c.payload_json->>'invoice_id')::uuid
          from public.invoice_operation_chunks c
          where c.id=any(v_release_ids)
            and c.payload_json->>'manifest_outcome'='SELECTED'
            and pg_input_is_valid(
              coalesce(c.payload_json->>'invoice_id',''),
              'uuid'
            )
        )
        order by i.id
        for update;

        update public.invoice_operation_chunks c
        set
          manifest_committed=true,
          status='COMPLETE',
          phase='ALREADY_ACTIVE',
          result_visible=true,
          result_json=coalesce(c.result_json,'{}'::jsonb)
            || jsonb_build_object(
              'result_category','ALREADY_ACTIVE',
              'code','ALREADY_ACTIVE'
            ),
          completed_at_utc=v_now,
          updated_at_utc=v_now
        where c.id=any(v_release_ids)
          and c.payload_json->>'manifest_outcome'='SELECTED'
          and exists (
            select 1
            from public.invoice_operation_chunks active
            join public.invoice_operations active_operation
              on active_operation.id=active.operation_id
            where active.chunk_type='ISSUE_INVOICE'
              and active.entity_type='INVOICE'
              and active.entity_id=(c.payload_json->>'invoice_id')::uuid
              and active.status in (
                'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
              )
              and active.id<>c.id
              and active.replaced_by_chunk_id is null
              and active_operation.status
                in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
          );

        update public.invoice_operation_chunks c
        set
          manifest_committed=true,
          entity_type='INVOICE',
          entity_id=(c.payload_json->>'invoice_id')::uuid,
          status='QUEUED',
          phase='VALIDATE',
          result_visible=true,
          run_after_utc=v_now,
          payload_json=c.payload_json || jsonb_build_object(
            'request_key',c.selection_key,
            'evaluation_date',(v_now at time zone 'Europe/London')::date,
            'frozen_issue_at_utc',v_now
          ),
          progress_json=jsonb_build_object(
            'contract_version','INVOICE_BATCH_PROGRESS_V2',
            'status_message','Queued for legal issue'
          ),
          updated_at_utc=v_now
        where c.id=any(v_release_ids)
          and c.payload_json->>'manifest_outcome'='SELECTED'
          and c.status='WAITING';
      end if;
    end if;

    select count(*)::integer
    into v_remaining
    from public.invoice_operation_chunks c
    where c.operation_id=v_expander.operation_id
      and c.is_manifest_member
      and c.manifest_generation=v_manifest_generation
      and not c.manifest_committed;

    update public.invoice_operation_chunks c
    set
      status=case when v_remaining=0 then 'COMPLETE' else 'QUEUED' end,
      phase=case when v_remaining=0 then 'RELEASE_COMPLETE' else 'RELEASE_MANIFEST' end,
      run_after_utc=case when v_remaining=0 then c.run_after_utc else v_now end,
      completed_at_utc=case when v_remaining=0 then v_now else null end,
      payload_json=coalesce(c.payload_json,'{}'::jsonb)
        || jsonb_build_object(
          'release_remaining',v_remaining,
          'release_complete',v_remaining=0
        ),
      progress_json=jsonb_build_object(
        'contract_version','INVOICE_BATCH_PROGRESS_V2',
        'status_message',case
          when v_remaining=0 then 'Manifest release complete'
          else 'Releasing manifest work'
        end
      ),
      lease_owner=null,
      lease_token=null,
      lease_expires_at_utc=null,
      updated_at_utc=v_now
    where c.id=v_expander.id;

    update public.invoice_operations o
    set
      status='QUEUED',
      phase=case when v_remaining=0 then 'BUSINESS_WORK' else 'RELEASE_MANIFEST' end,
      manifest_committed=true,
      release_complete=v_remaining=0,
      progress_json=coalesce(o.progress_json,'{}'::jsonb)
        || jsonb_build_object(
          'contract_version','INVOICE_BATCH_PROGRESS_V2',
          'selection_expansion_pending',false,
          'manifest_committed',true,
          'manifest_generation',v_manifest_generation,
          'manifest_status',case
            when v_remaining=0 then 'RELEASE_COMPLETE'
            else 'RELEASE_MANIFEST'
          end,
          'release_pending_total',(
            select count(*)::integer
            from public.invoice_operation_chunks member
            where member.operation_id=o.id
              and member.is_manifest_member
              and member.manifest_generation=v_manifest_generation
              and member.payload_json->>'manifest_outcome'='SELECTED'
              and not member.manifest_committed
          ),
          'released_total',(
            select count(*)::integer
            from public.invoice_operation_chunks member
            where member.operation_id=o.id
              and member.is_manifest_member
              and member.manifest_generation=v_manifest_generation
              and member.payload_json->>'manifest_outcome'='SELECTED'
              and member.manifest_committed
              and coalesce(member.result_category,'') not in(
                'ALREADY_ACTIVE','BLOCKED','CHANGED','MISSING','FAILED'
              )
          ),
          'release_conflict_total',(
            select count(*)::integer
            from public.invoice_operation_chunks member
            where member.operation_id=o.id
              and member.is_manifest_member
              and member.manifest_generation=v_manifest_generation
              and member.payload_json->>'manifest_outcome'='SELECTED'
              and member.result_category='ALREADY_ACTIVE'
          ),
          'release_blocked_total',(
            select count(*)::integer
            from public.invoice_operation_chunks member
            where member.operation_id=o.id
              and member.is_manifest_member
              and member.manifest_generation=v_manifest_generation
              and member.payload_json->>'manifest_outcome'='SELECTED'
              and member.result_category in(
                'BLOCKED','CHANGED','MISSING','FAILED'
              )
          ),
          'release_complete',v_remaining=0,
          'status_message',case
            when v_remaining=0 then 'Processing selected work'
            else 'Releasing manifest work'
          end
        ),
      updated_at_utc=v_now,
      change_seq=nextval('public.invoice_operation_change_seq')
    where o.id=v_expander.operation_id;

    v_result := v_result || jsonb_build_array(jsonb_build_object(
      'chunk_id',v_expander.id,
      'status',case when v_remaining=0 then 'COMPLETE' else 'QUEUED' end,
      'phase',case
        when v_remaining=0 then 'RELEASE_COMPLETE'
        else 'RELEASE_MANIFEST'
      end,
      'result',jsonb_build_object(
        'released_count',cardinality(v_release_ids),
        'remaining_count',v_remaining,
        'release_complete',v_remaining=0
      )
    ));
  end loop;

  return v_result;
end;
$function$;

alter function private._invoice_batch_manifest_advance_v2(
