create or replace function public.import_auto_authorise_policy_resolve_v2(
  p_source_system public.hr_source_enum,
  p_client_id uuid,
  p_contract_id uuid,
  p_timesheet_id uuid,
  p_relevant_date date,
  p_validation_context boolean default false
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare
  v_source text:=upper(btrim(coalesce(p_source_system::text,'')));
  v_policy_source text;
  v_key text;
  v_authority jsonb;
  v_components jsonb;
  v_policy jsonb;
  v_source_label text;
  v_effective boolean;
begin
  if p_client_id is null then
    raise exception 'IMPORT_AUTO_AUTHORISE_CLIENT_ID_REQUIRED' using errcode='22023';
  end if;
  if p_relevant_date is null then
    raise exception 'IMPORT_AUTO_AUTHORISE_RELEVANT_DATE_REQUIRED' using errcode='22023';
  end if;
  if v_source not in ('HEALTHROSTER','HEALTHROSTER_DAILY','NHSP') then
    raise exception 'IMPORT_AUTO_AUTHORISE_SOURCE_SYSTEM_INVALID' using errcode='22023';
  end if;
  v_policy_source:=case when v_source in ('HEALTHROSTER','HEALTHROSTER_DAILY')
    then 'HEALTHROSTER' else 'NHSP' end;
  v_key:=case when v_policy_source='HEALTHROSTER'
    then 'healthroster_import_auto_authorise' else 'nhsp_import_auto_authorise' end;
  v_authority:=private._contract_settings_effective_core_v1(
    p_client_id,p_contract_id,p_relevant_date,
    case when v_source='HEALTHROSTER_DAILY' then 'DAILY' else 'IMPORT' end,
    p_timesheet_id
  );
  v_components:=v_authority#>array['components',v_key];
  v_source_label:=v_authority#>>array['sources',v_key];
  v_effective:=coalesce((v_authority#>>array['values',v_key])::boolean,false);
  v_policy:=jsonb_strip_nulls(jsonb_build_object(
    'source_system',v_source,'policy_source_system',v_policy_source,
    'validation_context',coalesce(p_validation_context,false),
    'client_id',p_client_id::text,'contract_id',p_contract_id::text,
    'global_import_value',(v_components->>'global')::boolean,
    'client_import_value',(v_components->>'client')::boolean,
    'contract_override_value',(v_components->>'contract_override')::boolean,
    'effective_import_value',v_effective,'effective_value',v_effective,
    'global_validation_value',coalesce((v_authority#>>'{values,auto_authorise_on_validation}')::boolean,false),
    'resolution_source',case v_source_label when 'CONTRACT' then 'CONTRACT_OVERRIDE'
      when 'CLIENT' then 'CLIENT_SETTING' else 'GLOBAL_FALLBACK_CLIENT_SETTING_MISSING' end
      ||case when coalesce(p_validation_context,false) then '_VALIDATION_EXACT_MATCH' else '' end,
    'client_setting_found',true,
    'client_settings_id',v_authority->>'client_settings_id',
    'client_settings_effective_from',v_authority->>'client_settings_effective_from',
    'client_settings_updated_at',v_authority->>'client_settings_updated_at',
    'contract_updated_at',v_authority->>'contract_updated_at',
    'global_settings_updated_at',v_authority->>'global_settings_updated_at',
    'authority_version',v_authority->>'authority_version',
    'authority_fingerprint',v_authority->>'authority_fingerprint',
    'relevant_date',p_relevant_date,
    'timesheet_id',p_timesheet_id
  ));
  return v_policy||jsonb_build_object(
    'policy_fingerprint',encode(digest(convert_to(v_policy::text,'UTF8'),'sha256'),'hex')
  );
end
$function$;

alter function public.import_auto_authorise_policy_resolve_v2(
  public.hr_source_enum,uuid,uuid,uuid,date,boolean
) OWNER TO CURRENT_USER;
revoke all on function public.import_auto_authorise_policy_resolve_v2(
  public.hr_source_enum,uuid,uuid,uuid,date,boolean
) from public,anon,authenticated;
grant execute on function public.import_auto_authorise_policy_resolve_v2(
  public.hr_source_enum,uuid,uuid,uuid,date,boolean
) to service_role;

-- One-time TEST correction and durable compatibility backfill. Planned weeks
-- are recalculated; existing real Timesheets receive a snapshot only when they
-- have never had one. No hours, rates, financials, invoices or payment rows are
-- altered.
do $backfill$
declare v_row record; v_snapshot jsonb; v_date date;
begin
  perform private._contract_settings_refresh_all_planned_v1();
  for v_row in
    select t.timesheet_id,t.contract_id,t.week_ending_date,t.sheet_scope,c.client_id
    from public.timesheets t
    join public.contracts c on c.id=t.contract_id
    where t.settings_authority_json='{}'::jsonb
      and t.sheet_scope='WEEKLY'::public.timesheet_scope_enum
    order by t.timesheet_id
  loop
    v_snapshot:=private._contract_settings_effective_core_v1(
      v_row.client_id,v_row.contract_id,v_row.week_ending_date,'WEEKLY',null
    );
    update public.timesheets set
      settings_authority_json=v_snapshot,
      settings_authority_version='CONTRACT_SETTINGS_AUTHORITY_V1',
      settings_authority_fingerprint=v_snapshot->>'authority_fingerprint',
      settings_authority_resolved_at=(v_snapshot->>'resolved_at_utc')::timestamptz
    where timesheet_id=v_row.timesheet_id and settings_authority_json='{}'::jsonb;
  end loop;
  for v_row in
    select distinct on (t.timesheet_id)
      t.timesheet_id,t.contract_id,t.week_ending_date,t.worked_start_iso,
      t.scheduled_start_iso,tf.client_id
    from public.timesheets t
    join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current=true
    where t.settings_authority_json='{}'::jsonb
      and t.sheet_scope='DAILY'::public.timesheet_scope_enum
      and tf.processed_at_utc is not null
    order by t.timesheet_id,tf.computed_at_utc desc nulls last,tf.updated_at desc,tf.id desc
  loop
    v_date:=coalesce(
      (v_row.worked_start_iso at time zone 'Europe/London')::date,
      (v_row.scheduled_start_iso at time zone 'Europe/London')::date,
      v_row.week_ending_date
    );
    v_snapshot:=private._contract_settings_effective_core_v1(
      v_row.client_id,v_row.contract_id,v_date,'DAILY',null
    );
    update public.timesheets set
      settings_authority_json=v_snapshot,
      settings_authority_version='CONTRACT_SETTINGS_AUTHORITY_V1',
      settings_authority_fingerprint=v_snapshot->>'authority_fingerprint',
      settings_authority_resolved_at=(v_snapshot->>'resolved_at_utc')::timestamptz
    where timesheet_id=v_row.timesheet_id and settings_authority_json='{}'::jsonb;
  end loop;
end
$backfill$;

notify pgrst, 'reload schema';

commit;

-- Final current authority for invoice generation planning.
-- Reasserts the frozen per-Timesheet settings source after every historical compatibility root.
-- This changes only settings provenance; invoice calculations, grouping, eligibility and actions are preserved.

\set ON_ERROR_STOP on

begin;

create or replace function private._invoice_generation_advance_core_v8(
  p_claims jsonb,
  p_now_utc timestamptz
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_now timestamptz := coalesce(p_now_utc,now());
  v_result jsonb := '[]'::jsonb;
  v_part jsonb;
begin
  -- VALIDATE_SOURCES: no invoice/header/line writes are permitted in this block.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='VALIDATE_SOURCES'
  ),
  member_values as materialized (
    select c.id chunk_id,c.operation_id,c.payload_json,
      m.value member,m.ordinality
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
          and jsonb_array_length(c.payload_json->'canonical_source_members')>0
        then c.payload_json->'canonical_source_members'
        else coalesce((
          select jsonb_agg(jsonb_build_object(
            'source_type','TIMESHEET','source_id',s.value,
            'related_timesheet_id',s.value) order by s.ordinality)
          from jsonb_array_elements_text(coalesce(
            c.payload_json->'canonical_source_ids',
            c.payload_json->'source_ids','[]'::jsonb))
            with ordinality s(value,ordinality)
        ),'[]'::jsonb) end) with ordinality m(value,ordinality)
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  members as materialized (
    select m.chunk_id,m.operation_id,m.payload_json,m.member,
      upper(coalesce(m.member->>'source_type','TIMESHEET')) source_type,
      case when coalesce(m.member->>'source_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(m.member->>'source_id')::uuid end source_id,
      case when coalesce(m.member->>'related_timesheet_id',
          m.member->>'source_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then coalesce(m.member->>'related_timesheet_id',
          m.member->>'source_id')::uuid end timesheet_id,
      nullif(btrim(m.member->>'segment_id'),'') segment_id,
      coalesce(nullif(btrim(m.member->>'source_member_key'),''),
        encode(digest(concat_ws('|',
          upper(coalesce(m.member->>'source_type','TIMESHEET')),
          coalesce(m.member->>'source_id',''),
          coalesce(m.member->>'related_timesheet_id',''),
          coalesce(m.member->>'segment_id','WHOLE'),
          coalesce(m.member->>'target_invoice_week','')),'sha256'),'hex'))
        source_member_key,
      nullif(btrim(coalesce(m.member->>'row_revision',
        m.member->>'source_revision','')),'') expected_revision,
      m.ordinality
    from member_values m
  ),
  reference_eval as materialized (
    select distinct on (r.source_member_key) r.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,'source_id',m.source_id,
        'related_timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'target_invoice_week',m.member->>'target_invoice_week',
        'invoice_stream',m.payload_json->>'invoice_stream',
        'consolidation_mode',m.payload_json->>'consolidation_mode',
        'source_revision',m.expected_revision)
        order by m.chunk_id,m.ordinality)
      from members m
    ),'[]'::jsonb)) r
    order by r.source_member_key
  ),
  vat_eval as materialized (
    select distinct on (v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,'source_id',m.source_id,
        'timesheet_id',m.timesheet_id,'segment_id',m.segment_id,
        'effective_date',coalesce(
          case when m.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                m.payload_json->>'effective_settings_date','date')
            then m.payload_json->>'effective_settings_date' end,
          (select ts_vat.week_ending_date::text
             from public.timesheets ts_vat
            where ts_vat.timesheet_id=m.timesheet_id
              and ts_vat.is_current
            limit 1)))
        order by m.chunk_id,m.ordinality)
      from members m
    ),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-validate:'||scope.chunk_id::text,
      'scope_key',scope.chunk_id::text,
      'validation_purpose','GENERATION_VALIDATE',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.chunk_id),'[]'::jsonb) scopes
    from(
      select m.chunk_id,min(m.payload_json::text)::jsonb payload_json,
        jsonb_agg(jsonb_build_object(
          'timesheet_id',m.timesheet_id,
          'source_type',m.source_type,
          'source_id',m.source_id,
          'source_member_key',m.source_member_key,
          'segment_id',m.segment_id,
          'target_invoice_week',m.payload_json->>'target_invoice_week',
          'vat_rate_pct',v.vat_rate)
          order by m.ordinality) planned_members
      from members m
      left join vat_eval v on v.source_member_key=m.source_member_key
      group by m.chunk_id
    ) scope
  ),
  correction_eval as materialized (
    select r.*
    from correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),  source_eval as materialized (
    select m.chunk_id,m.operation_id,m.timesheet_id,m.segment_id,
      m.source_member_key,m.ordinality,
      tf.id tsfin_id,
      encode(digest(concat_ws('|',tf.id::text,tf.timesheet_version::text,
        tf.updated_at::text,ts.version::text,ts.updated_at::text,
        coalesce(tf.invoice_breakdown_json::text,'')),'sha256'),'hex') row_revision,
      array_remove(array[
        case when ts.timesheet_id is null then 'TIMESHEET_NOT_FOUND' end,
        case when ts.timesheet_id is not null and (not ts.is_current or ts.revoked_at is not null) then 'TIMESHEET_NOT_CURRENT' end,
        case when tf.id is null then 'CURRENT_FINANCIALS_MISSING' end,
        case when tf.id is not null and tf.is_stale then 'FINANCIALS_STALE' end,
        case when tf.id is not null and tf.processing_status::text<>'READY_FOR_INVOICE' then 'NOT_READY_FOR_INVOICE' end,
        case when tf.id is not null and tf.has_rate_issue then 'RATE_MISSING' end,
        case when tf.id is not null and tf.has_pay_channel_issue then 'PAY_CHANNEL_MISSING' end,
        case when tf.id is not null and tf.client_id is null then 'CLIENT_UNRESOLVED' end,
        case when tf.id is not null and tf.locked_by_invoice_id is not null then 'SOURCE_ALREADY_LOCKED' end,
        case when ts.authorised_at_server is null
          then 'TIMESHEET_NOT_AUTHORISED' end,
        case when upper(coalesce(ts.submission_mode::text,''))='QR'
          and(nullif(ts.qr_signed_hash,'') is null
            or ts.qr_signed_at_utc is null)
          then 'QR_TIMESHEET_UNSIGNED' end,
        case when pc.require_reference_to_invoice
          and coalesce(ref.reference_ready,false) is not true
          then coalesce(ref.blocker_code,'MISSING_REFERENCE') end,
        case when coalesce(tf.mileage_pay_ex_vat,0)<>0
            or coalesce(tf.mileage_charge_ex_vat,0)<>0
          then case when not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null)
            then 'MISSING_MILEAGE_EVIDENCE' end end,
        case when(coalesce(tf.mileage_pay_ex_vat,0)<>0
            or coalesce(tf.mileage_charge_ex_vat,0)<>0)
          and exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null
              and e.document_asset_id is null)
          then 'MILEAGE_ASSET_NOT_REGISTERED' end,
        case when coalesce(tf.expenses_pay_ex_vat,0)<>0
            or coalesce(tf.expenses_charge_ex_vat,0)<>0
            or coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0
            or coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0
          then case when not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET','EXPENSE_MILEAGE_APPROVAL_SUMMARY')
              and nullif(e.storage_key,'') is not null)
            then 'MISSING_EXPENSE_EVIDENCE' end end,
        case when(
            coalesce(tf.expenses_pay_ex_vat,0)<>0
            or coalesce(tf.expenses_charge_ex_vat,0)<>0
            or coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0
            or coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null
              and e.document_asset_id is null)
          then 'EXPENSE_ASSET_NOT_REGISTERED' end,
        case when(coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='TRAVEL'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_TRAVEL_EVIDENCE' end,
        case when(coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='ACCOMMODATION'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_ACCOMMODATION_EVIDENCE' end,
        case when(coalesce(tf.other_pay_ex_vat,0)<>0
            or coalesce(tf.other_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET','EXPENSE_MILEAGE_APPROVAL_SUMMARY')
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_OTHER_EXPENSE_EVIDENCE' end,
        case when exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'MILEAGE','TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and a.status in(
                'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED'))
          then 'REQUIRED_ASSET_PERMANENT_FAILURE' end,
        case when coalesce(vat.valid,false) is not true
          then coalesce(vat.blocker_code,'VAT_POLICY_UNRESOLVED') end,
        case when corr.valid is false
          then coalesce(corr.blocker_code,'CORRECTION_VALIDATION_FAILED') end,
        case when coalesce(vs.hr_validation_required_for_invoice,false)
          and upper(coalesce(tf.hr_crosscheck_status,'')) not in(
            'OK','PASS','PASSED','MATCHED','NOT_REQUIRED')
          then 'HEALTHROSTER_VALIDATION_REQUIRED' end,
        case when coalesce(vs.client_is_nhsp,false)
          and coalesce(vs.nhsp_shift_count,0)>0
          and not exists(
            select 1
            from public.nhsp_shifts ns_ready
            where ns_ready.timesheet_id=m.timesheet_id
              and ns_ready.invoice_status='PENDING'
              and ns_ready.invoice_id is null
              and ns_ready.cancelled_at_utc is null)
          then 'NHSP_SOURCE_NOT_READY' end,
        case when exists(select 1 from public.invoice_lines l join public.invoices i on i.id=l.invoice_id
                         where l.timesheet_id=m.timesheet_id and i.status in ('DRAFT','ISSUED','ON_HOLD'))
             and coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS' then 'SOURCE_ALREADY_INVOICED' end
      ],null)::text[] blockers
    from members m
    left join public.timesheets ts on ts.timesheet_id=m.timesheet_id
    left join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=m.timesheet_id
    left join public.v_timesheets_summary_base vs
      on vs.timesheet_id=m.timesheet_id
    left join reference_eval ref on ref.source_member_key=m.source_member_key
    left join vat_eval vat on vat.source_member_key=m.source_member_key
    left join correction_eval corr
      on corr.scope_key=m.chunk_id::text
  ),
  resolver_inputs as materialized (
    select c.id chunk_id,c.payload_json,
      row_number() over(order by c.id)::integer command_no
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  canonical_now as materialized (
    select ri.chunk_id,r.group_key,r.source_revision_hash,
      r.blocker_code,r.blocker_detail
    from private._invoice_generation_resolve_command_groups(
      (select coalesce(jsonb_agg(ri.payload_json order by ri.command_no),
        '[]'::jsonb) from resolver_inputs ri),null,v_now) r
    join resolver_inputs ri on ri.command_no=r.command_no
    where r.group_key=case
      when left(coalesce(ri.payload_json->>'selection_key',''),9)='generate:'
        then substr(ri.payload_json->>'selection_key',10)
      else ri.payload_json->>'group_key' end
  ),
  per_chunk as materialized (
    select c.id chunk_id,
      n.source_revision_hash current_revision,
      coalesce(jsonb_agg(jsonb_build_object('source_id',se.timesheet_id,
        'segment_id',se.segment_id,
        'codes',to_jsonb(se.blockers)) order by se.ordinality)
        filter(where cardinality(se.blockers)>0),'[]'::jsonb)
        ||case when n.blocker_code is null then '[]'::jsonb
          else jsonb_build_array(coalesce(n.blocker_detail,
            jsonb_build_object('code',n.blocker_code))) end blockers,
      count(se.timesheet_id)::integer source_count
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join source_eval se on se.chunk_id=c.id
    left join canonical_now n on n.chunk_id=c.id
    group by c.id,n.source_revision_hash,n.blocker_code,n.blocker_detail
  ),
  updated as (
    update public.invoice_operation_chunks c
    set phase=case
          when p.source_count=0 then 'BLOCKED'
          when jsonb_array_length(p.blockers)>0 then 'BLOCKED'
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then 'SUPERSEDED'
          else 'PLAN' end,
        status=case
          when p.source_count=0 or jsonb_array_length(p.blockers)>0 then 'BLOCKED'
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then 'SUPERSEDED'
          else 'QUEUED' end,
        payload_json=c.payload_json||jsonb_build_object('source_revision',p.current_revision,'source_count',p.source_count),
        progress_json=jsonb_build_object('status_message',
          case when p.source_count=0 then 'No sources resolved'
               when jsonb_array_length(p.blockers)>0 then 'Source validation blocked'
               when nullif(c.payload_json->>'source_revision','') is not null
                and c.payload_json->>'source_revision'<>p.current_revision then 'Source changed'
               else 'Sources validated' end,'source_count',p.source_count),
        error_json=case
          when p.source_count=0 then jsonb_build_object('code','NO_SOURCES','sources','[]'::jsonb)
          when jsonb_array_length(p.blockers)>0 then jsonb_build_object('code','SOURCE_VALIDATION_BLOCKED','sources',p.blockers)
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then jsonb_build_object('code','SOURCE_CHANGED')
          else null end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from per_chunk p where c.id=p.chunk_id
    returning c.id,c.operation_id,c.status,c.phase,c.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]'::jsonb)
  into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Credit-note validation is deliberately separate from normal timesheet sources.
  with claim_ids as (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='VALIDATE_SOURCES'
  ),
  credit_eval as (
    select c.id chunk_id,i.id invoice_id,
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),'sha256'),'hex') revision,
      case when i.id is null then 'INVOICE_NOT_FOUND'
           when i.type::text<>'INVOICE' then 'CREDIT_SOURCE_NOT_INVOICE'
           when i.status::text not in ('ISSUED','PAID') then 'CREDIT_SOURCE_NOT_ISSUED'
           when exists(select 1 from public.invoices cn where cn.original_invoice_id=i.id and cn.type='CREDIT_NOTE'
                       and cn.status in('DRAFT','ISSUED','PAID')) then 'CREDIT_ALREADY_EXISTS'
           else null end blocker
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join public.invoices i on i.id=c.entity_id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
  ),
  updated as (
    update public.invoice_operation_chunks c
    set phase=case when e.blocker is null then 'PLAN' else 'BLOCKED' end,
        status=case when e.blocker is null then 'QUEUED' else 'BLOCKED' end,
        payload_json=c.payload_json||jsonb_build_object('source_revision',e.revision,'source_invoice_id',e.invoice_id),
        progress_json=jsonb_build_object('status_message',case when e.blocker is null then 'Credit source validated' else 'Credit source blocked' end),
        error_json=case when e.blocker is null then null else jsonb_build_object('code',e.blocker,'invoice_id',c.entity_id) end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from credit_eval e where c.id=e.chunk_id
    returning c.id,c.status,c.phase,c.error_json
  )
  select v_result||coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]'::jsonb)
  into v_result from updated;

  -- PLAN: compact financial/settings summary only; no complete line arrays.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='PLAN'
  ),
  members as materialized (
    select c.id chunk_id,c.payload_json,
      case when pg_input_is_valid(s.value,'uuid')
        then s.value::uuid end timesheet_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    cross join lateral jsonb_array_elements_text(coalesce(
      c.payload_json->'canonical_source_ids',c.payload_json->'source_ids','[]'::jsonb)) s(value)
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
      and pg_input_is_valid(s.value,'uuid')
  ),
  values_by_chunk as materialized (
    select m.chunk_id,count(*)::integer source_count,
      round(sum(coalesce(tf.total_pay_ex_vat,0)),2) expected_pay_ex_vat,
      round(sum(coalesce(tf.total_charge_ex_vat,0)),2) expected_charge_ex_vat,
      (array_agg(tf.client_id order by tf.client_id))[1] client_id,
      jsonb_build_object(
        'client_id',(array_agg(tf.client_id order by tf.client_id))[1],'consolidation_mode',max(c.payload_json->>'consolidation_mode'),
        'stream',max(c.payload_json->>'invoice_stream'),
        'invoice_week_start',max(c.payload_json->>'target_invoice_week'),
        'client',jsonb_build_object('name',max(cl.name),'vat_chargeable',bool_and(cl.vat_chargeable),
          'payment_terms_days',max(cl.payment_terms_days),'primary_invoice_email',max(cl.primary_invoice_email)),
        'attach_policy',jsonb_build_object(
          'hr_attach_to_invoice',coalesce(bool_or(
            (a.authority_json#>>'{values,hr_attach_to_invoice}')::boolean),true),
          'ts_attach_to_invoice',coalesce(bool_or(
            (a.authority_json#>>'{values,ts_attach_to_invoice}')::boolean),true),
          'requires_hr',coalesce(bool_or(
            (a.authority_json#>>'{values,requires_hr}')::boolean),false)),
        'settings_authority',jsonb_build_object(
          'version','CONTRACT_SETTINGS_AUTHORITY_V1',
          'fingerprints',jsonb_agg(distinct to_jsonb(
            a.authority_json->>'authority_fingerprint'
          ) order by to_jsonb(a.authority_json->>'authority_fingerprint')))
      ) settings_snapshot
    from members m join public.invoice_operation_chunks c on c.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current
    cross join lateral (
      select private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)
        authority_json
    ) a
    join public.clients cl on cl.id=tf.client_id
    group by m.chunk_id
  ),
  plans as materialized (
    select c.id chunk_id,coalesce(
      case when pg_input_is_valid(
        nullif(c.payload_json->>'planned_invoice_id',''),'uuid')
        then(c.payload_json->>'planned_invoice_id')::uuid end,
      case when c.payload_json->>'consolidation_mode' in ('BY_WEEK','ANY_WEEK') then (
        select i.id from public.invoices i
        where i.client_id=v.client_id and i.status='DRAFT' and i.type='INVOICE'
          and coalesce(i.header_snapshot_json#>>'{meta,consolidation_mode}','NONE')=c.payload_json->>'consolidation_mode'
          and coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false')=
              case when c.payload_json->>'invoice_stream'='SELF_BILL' then 'true' else 'false' end
          and (not private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
            or upper(coalesce(
              nullif(i.header_snapshot_json#>>'{meta,invoice_stream}',''),
              nullif(i.header_snapshot_json->>'invoice_stream',''),
              case when lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false'))
                in('true','t','1','yes') then 'SELF_BILL' else 'NORMAL' end
            ))=upper(coalesce(c.payload_json->>'invoice_stream','NORMAL')))
          and (c.payload_json->>'consolidation_mode'='ANY_WEEK'
               or i.header_snapshot_json#>>'{meta,invoice_week_start}'=c.payload_json->>'target_invoice_week')
        order by i.created_at desc limit 1
      ) end,gen_random_uuid()) planned_invoice_id,
      v.source_count,v.expected_charge_ex_vat,v.expected_pay_ex_vat,v.client_id,
      v.settings_snapshot,encode(digest(v.settings_snapshot::text,'sha256'),'hex') settings_hash
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join values_by_chunk v on v.chunk_id=c.id
  ),
  credit_plans as materialized (
    select c.id chunk_id,gen_random_uuid() planned_invoice_id,1 source_count,
      -i.subtotal_ex_vat expected_charge_ex_vat,-coalesce(sum(l.total_pay_ex_vat),0) expected_pay_ex_vat,
      i.client_id,jsonb_build_object('source_invoice_id',i.id,'source_invoice_no',i.invoice_no,
        'client_id',i.client_id,'credit_note',true) settings_snapshot,
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text),'sha256'),'hex') settings_hash
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i on i.id=c.entity_id
    left join public.invoice_lines l on l.invoice_id=i.id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
    group by c.id,i.id
  ),
  all_plans as materialized (select * from plans union all select * from credit_plans),
  updated as (
    update public.invoice_operation_chunks c
    set phase='COMMIT',status='QUEUED',
      payload_json=c.payload_json||jsonb_build_object('plan',jsonb_build_object(
        'planned_invoice_id',p.planned_invoice_id,'intended_invoice_count',1,
        'source_count',p.source_count,'expected_pay_ex_vat',p.expected_pay_ex_vat,
        'expected_charge_ex_vat',p.expected_charge_ex_vat,'settings_snapshot',p.settings_snapshot,
        'settings_hash',p.settings_hash,'source_revision',c.payload_json->>'source_revision')),
      progress_json=jsonb_build_object('status_message','Generation plan ready','source_count',p.source_count),
      error_json=null,lease_owner=null,lease_token=null,
      lease_expires_at_utc=null,updated_at_utc=v_now
    from all_plans p where c.id=p.chunk_id
    returning c.id,c.status,c.phase,c.payload_json->'plan' plan
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'plan',plan)),'[]'::jsonb)
    into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- COMMIT: revalidate immediately, then headers, lines, locks, documents and audit set-wise.
  with recursive claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='COMMIT'
  ),
  normal_chunks as materialized (
    select c.*,case when pg_input_is_valid(
        c.payload_json#>>'{plan,planned_invoice_id}','uuid')
      then(c.payload_json#>>'{plan,planned_invoice_id}')::uuid end planned_invoice_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  members as materialized (
    select c.id chunk_id,c.operation_id,c.planned_invoice_id,c.payload_json,
      upper(coalesce(s.value->>'source_type','TIMESHEET')) source_type,
      case when pg_input_is_valid(s.value->>'source_id','uuid')
        then(s.value->>'source_id')::uuid end source_id,
      case when pg_input_is_valid(coalesce(
          s.value->>'related_timesheet_id',s.value->>'source_id'),'uuid')
        then coalesce(s.value->>'related_timesheet_id',
          s.value->>'source_id')::uuid end timesheet_id,
      nullif(btrim(s.value->>'segment_id'),'') segment_id,
      coalesce(nullif(btrim(s.value->>'source_member_key'),''),
        encode(digest(concat_ws('|',
          upper(coalesce(s.value->>'source_type','TIMESHEET')),
          coalesce(s.value->>'source_id',''),
          coalesce(s.value->>'related_timesheet_id',''),
          coalesce(s.value->>'segment_id','WHOLE'),
          coalesce(s.value->>'target_invoice_week','')),'sha256'),'hex'))
        source_member_key
    from normal_chunks c
    cross join lateral jsonb_array_elements(case
      when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
        and jsonb_array_length(c.payload_json->'canonical_source_members')>0
      then c.payload_json->'canonical_source_members'
      else coalesce((
        select jsonb_agg(jsonb_build_object(
          'source_type','TIMESHEET','source_id',ids.value,
          'related_timesheet_id',ids.value) order by ids.ordinality)
        from jsonb_array_elements_text(coalesce(
          c.payload_json->'canonical_source_ids',
          c.payload_json->'source_ids','[]'::jsonb))
          with ordinality ids(value,ordinality)
      ),'[]'::jsonb) end) s(value)
    where pg_input_is_valid(coalesce(
      s.value->>'related_timesheet_id',s.value->>'source_id'),'uuid')
  ),
  selected_segments as materialized (
    select c.id chunk_id,
      (m.value->>'source_id')::uuid timesheet_id,
      array_agg(distinct m.value->>'segment_id'
        order by m.value->>'segment_id')
        filter(where nullif(m.value->>'segment_id','') is not null) segment_ids
    from normal_chunks c
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
        then c.payload_json->'canonical_source_members' else '[]'::jsonb end)
      m(value)
    where coalesce(m.value->>'source_id','')~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    group by c.id,(m.value->>'source_id')::uuid
  ),
  commit_reference_eval as materialized (
    select distinct on(r.source_member_key) r.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,
        'source_id',m.source_id,
        'related_timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'target_invoice_week',m.payload_json->>'target_invoice_week',
        'invoice_stream',m.payload_json->>'invoice_stream',
        'consolidation_mode',m.payload_json->>'consolidation_mode')
        order by m.chunk_id,m.source_member_key)
      from members m),'[]'::jsonb)) r
    order by r.source_member_key
  ),
  commit_vat_eval as materialized (
    select distinct on(v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,
        'source_id',m.source_id,
        'timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'effective_date',coalesce(
          case when m.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                m.payload_json->>'effective_settings_date','date')
            then m.payload_json->>'effective_settings_date' end,
          (select ts_vat.week_ending_date::text
             from public.timesheets ts_vat
            where ts_vat.timesheet_id=m.timesheet_id
              and ts_vat.is_current
            limit 1)))
        order by m.chunk_id,m.source_member_key)
      from members m),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  commit_correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-commit:'||scope.planned_invoice_id::text,
      'scope_key',scope.planned_invoice_id::text,
      'invoice_id',case when exists(select 1 from public.invoices existing
        where existing.id=scope.planned_invoice_id)
        then scope.planned_invoice_id end,
      'validation_purpose','GENERATION_COMMIT',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.planned_invoice_id),'[]'::jsonb) scopes
    from(
      select m.planned_invoice_id,min(m.payload_json::text)::jsonb payload_json,
        jsonb_agg(jsonb_build_object(
          'timesheet_id',m.timesheet_id,
          'source_type',m.source_type,
          'source_id',m.source_id,
          'source_member_key',m.source_member_key,
          'segment_id',m.segment_id,
          'target_invoice_week',m.payload_json->>'target_invoice_week',
          'vat_rate_pct',v.vat_rate)
          order by m.source_member_key) planned_members
      from members m
      left join commit_vat_eval v
        on v.source_member_key=m.source_member_key
      group by m.planned_invoice_id
    ) scope
  ),
  commit_correction_eval as materialized (
    select r.*
    from commit_correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),  source_still_valid as materialized (
    select m.chunk_id,
      bool_and(tf.processing_status='READY_FOR_INVOICE' and not tf.is_stale
        and (tf.locked_by_invoice_id is null
          or coalesce(tf.invoice_breakdown_json->>'mode','')='SEGMENTS')
        and ts.authorised_at_server is not null
        and not(upper(coalesce(ts.submission_mode::text,''))='QR'
          and(nullif(ts.qr_signed_hash,'') is null
            or ts.qr_signed_at_utc is null))
        and(not coalesce(pc.require_reference_to_invoice,false)
          or coalesce(ref.reference_ready,false))
        and coalesce(vat.valid,false)
        and coalesce(corr.valid,true)
        and not(coalesce(vs.hr_validation_required_for_invoice,false)
          and upper(coalesce(tf.hr_crosscheck_status,'')) not in(
            'OK','PASS','PASSED','MATCHED','NOT_REQUIRED'))
        and not(coalesce(vs.client_is_nhsp,false)
          and coalesce(vs.nhsp_shift_count,0)>0
          and not exists(
            select 1
            from public.nhsp_shifts ns_ready
            where ns_ready.timesheet_id=m.timesheet_id
              and ns_ready.invoice_status='PENDING'
              and ns_ready.invoice_id is null
              and ns_ready.cancelled_at_utc is null))
        and not((coalesce(tf.mileage_pay_ex_vat,0)<>0
              or coalesce(tf.mileage_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.travel_pay_ex_vat,0)<>0
              or coalesce(tf.travel_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='TRAVEL'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.accommodation_pay_ex_vat,0)<>0
              or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='ACCOMMODATION'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null))
        and not((((coalesce(tf.travel_pay_ex_vat,0)
                +coalesce(tf.accommodation_pay_ex_vat,0)
                +coalesce(tf.other_pay_ex_vat,0)=0)
              and coalesce(tf.expenses_pay_ex_vat,0)<>0)
            or ((coalesce(tf.travel_charge_ex_vat,0)
                +coalesce(tf.accommodation_charge_ex_vat,0)
                +coalesce(tf.other_charge_ex_vat,0)=0)
              and coalesce(tf.expenses_charge_ex_vat,0)<>0))
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET','EXPENSE_MILEAGE_APPROVAL_SUMMARY')
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.other_pay_ex_vat,0)<>0
              or coalesce(tf.other_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET','EXPENSE_MILEAGE_APPROVAL_SUMMARY')
              and nullif(e.storage_key,'') is not null))
        and not exists(
          select 1
          from public.timesheet_evidence e
          left join public.invoice_document_assets a
            on a.id=e.document_asset_id
          where e.timesheet_id=m.timesheet_id
            and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
            and upper(coalesce(e.document_role,'')) not in(
              'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
              'SIGNED_TIMESHEET')
            and(
              (upper(coalesce(e.kind,''))='MILEAGE'
                and(coalesce(tf.mileage_pay_ex_vat,0)<>0
                  or coalesce(tf.mileage_charge_ex_vat,0)<>0))
              or(upper(coalesce(e.kind,'')) in(
                  'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
                and(coalesce(tf.expenses_pay_ex_vat,0)<>0
                  or coalesce(tf.expenses_charge_ex_vat,0)<>0
                  or coalesce(tf.travel_pay_ex_vat,0)<>0
                  or coalesce(tf.travel_charge_ex_vat,0)<>0
                  or coalesce(tf.accommodation_pay_ex_vat,0)<>0
                  or coalesce(tf.accommodation_charge_ex_vat,0)<>0)))
            and(e.document_asset_id is null
              or a.status in('UNSUPPORTED','CORRUPT','MISSING',
                'FAILED','SUPERSEDED')))
        and not exists(
          select 1
          from public.invoice_lines l
          join public.invoices existing on existing.id=l.invoice_id
          where l.timesheet_id=m.timesheet_id
            and existing.id<>m.planned_invoice_id
            and existing.status in('DRAFT','ISSUED','ON_HOLD')
            and coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS')
      ) still_valid
    from members m join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current and ts.revoked_at is null
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=m.timesheet_id
    left join public.v_timesheets_summary_base vs
      on vs.timesheet_id=m.timesheet_id
    left join commit_reference_eval ref
      on ref.source_member_key=m.source_member_key
    left join commit_vat_eval vat
      on vat.source_member_key=m.source_member_key
    left join commit_correction_eval corr
      on corr.scope_key=m.planned_invoice_id::text
    group by m.chunk_id
  ),
  commit_resolver_inputs as materialized (
    select c.id chunk_id,c.payload_json,
      row_number() over(order by c.id)::integer command_no
    from normal_chunks c
  ),
  commit_resolver_results as materialized (
    select ri.chunk_id,r.source_revision_hash,r.blocker_code
    from private._invoice_generation_resolve_command_groups(
      (select coalesce(jsonb_agg(ri.payload_json order by ri.command_no),
        '[]'::jsonb) from commit_resolver_inputs ri),null,v_now) r
    join commit_resolver_inputs ri on ri.command_no=r.command_no
    where r.group_key=case
      when left(coalesce(ri.payload_json->>'selection_key',''),9)='generate:'
        then substr(ri.payload_json->>'selection_key',10)
      else ri.payload_json->>'group_key' end
  ),
  revision_check as materialized (
    select c.id chunk_id,r.source_revision_hash current_revision,
      s.still_valid and r.blocker_code is null still_valid
    from normal_chunks c
    join source_still_valid s on s.chunk_id=c.id
    join commit_resolver_results r on r.chunk_id=c.id
  ),
  rejected as (
    update public.invoice_operation_chunks c
    set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code','SOURCE_CHANGED_BEFORE_COMMIT'),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from revision_check r
    where c.id=r.chunk_id and (not r.still_valid or r.current_revision<>c.payload_json->>'source_revision')
    returning c.id
  ),
  valid_chunks as materialized (
    select c.* from normal_chunks c join revision_check r on r.chunk_id=c.id
    where r.still_valid and r.current_revision=c.payload_json->>'source_revision'
      and not exists(select 1 from rejected x where x.id=c.id)
  ),
  header_source as materialized (
    select vc.id chunk_id,vc.planned_invoice_id,(array_agg(tf.client_id order by tf.client_id))[1] client_id,
      max(cl.name) client_name,max(cl.invoice_address) client_invoice_address,
      max(a.authority_json#>>'{values,client_primary_invoice_email}') primary_invoice_email,
      bool_and(coalesce(
        (a.authority_json#>>'{values,client_vat_chargeable}')::boolean,true
      )) vat_chargeable,
      max((a.authority_json#>>'{values,client_payment_terms_days}')::integer)
        payment_terms_days,
      max(sd.agency_name) agency_name,max(sd.agency_logo) agency_logo,
      max(sd.registered_address) registered_address,max(sd.company_reg_number) company_reg_number,
      max(sd.bank_name) bank_name,max(sd.bank_sort_code) bank_sort_code,
      max(sd.bank_account_number) bank_account_number,max(sd.vat_registration_number) vat_registration_number,
      count(*)::integer source_count
    from valid_chunks vc join members m on m.chunk_id=vc.id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current
    cross join lateral (
      select private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)
        authority_json
    ) a
    join public.clients cl on cl.id=tf.client_id cross join public.settings_defaults sd
    where sd.id=1 group by vc.id,vc.planned_invoice_id
  ),
  source_rows_base as materialized (
    select m.chunk_id,m.planned_invoice_id,m.payload_json,
      m.source_member_key,m.source_type,m.source_id,m.segment_id,tf.*,ts.booking_id,
      ts.week_ending_date,ts.reference_number,ts.sheet_scope,ts.submission_mode,ts.day_references_json,
      ts.actual_schedule_json,coalesce(ts.contract_id,cw.contract_id) contract_id,
      coalesce(cd.display_name,'Candidate '||left(coalesce(tf.candidate_id::text,m.timesheet_id::text),8)) candidate_display,
      coalesce((a.authority_json#>>'{values,daily_calc_of_invoices}')::boolean,false)
        daily_calc_of_invoices,
      coalesce(a.authority_json#>'{values,bucket_labels_json}',
        jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH'))
        bucket_labels_json,
      ct.role contract_role,ct.display_site contract_display_site,
      ct.ward_hint contract_ward_hint,
      null::numeric ordinary_vat_rate,
      case when ts.sheet_scope::text='WEEKLY'
          and ts.submission_mode::text='MANUAL'
          and jsonb_typeof(ts.actual_schedule_json)='array'
        then coalesce((
          select jsonb_agg(jsonb_build_object(
            'date',e.value->>'date','start',e.value->>'start',
            'end',e.value->>'end','start_utc',e.value->>'start_utc',
            'end_utc',e.value->>'end_utc','ref_num',e.value->>'ref_num')
            order by e.ordinality)
          from jsonb_array_elements(ts.actual_schedule_json)
            with ordinality e(value,ordinality)
          where nullif(btrim(e.value->>'start'),'') is not null
            and nullif(btrim(e.value->>'end'),'') is not null
        ),'[]'::jsonb)
        else '[]'::jsonb end schedule_refs
    from members m join valid_chunks vc on vc.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current
    cross join lateral (
      select private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)
        authority_json
    ) a
    left join lateral (
      select w.contract_id
      from public.contract_weeks w
      where w.timesheet_id=m.timesheet_id
      order by w.updated_at desc nulls last,w.created_at desc nulls last,w.id desc
      limit 1
    ) cw on true
    left join public.contracts ct on ct.id=coalesce(ts.contract_id,cw.contract_id)
    left join public.candidates cd on cd.id=tf.candidate_id
  ),
  vat_policy as materialized (
    select distinct on (v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',s.source_member_key,
        'source_type',s.source_type,'source_id',s.source_id,
        'timesheet_id',s.timesheet_id,'segment_id',s.segment_id,
        'ordinary_rate',s.ordinary_vat_rate,
        'effective_date',coalesce(
          case when s.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                s.payload_json->>'effective_settings_date','date')
            then(s.payload_json->>'effective_settings_date')::date end,
          s.week_ending_date::date))
        order by s.chunk_id,s.timesheet_id)
      from source_rows_base s
    ),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  source_rows as materialized (
    select s.*,v.vat_rate
    from source_rows_base s
    join vat_policy v on v.source_member_key=s.source_member_key and v.valid
  ),
  source_timesheet_ancestry(
    planned_invoice_id,
    root_timesheet_id,
    source_timesheet_id,
    ancestry_path,
    ancestry_depth
  ) as materialized (
    select distinct s.planned_invoice_id,s.timesheet_id,s.timesheet_id,
      array[s.timesheet_id]::uuid[],0
    from source_rows s
    union all
    select a.planned_invoice_id,a.root_timesheet_id,t.parent_timesheet_id,
      a.ancestry_path||t.parent_timesheet_id,a.ancestry_depth+1
    from source_timesheet_ancestry a
    join public.timesheets t
      on t.timesheet_id=a.source_timesheet_id
     and t.is_current
    where t.parent_timesheet_id is not null
      and not(t.parent_timesheet_id=any(a.ancestry_path))
      and a.ancestry_depth<32
  ),
  adjustment_segment_refs as materialized (
    select distinct s.planned_invoice_id,s.timesheet_id root_timesheet_id,
      coalesce(
        (s.payload_json#>>'{plan,settings_snapshot,attach_policy,hr_attach_to_invoice}')::boolean,
        true
      ) healthroster_attach_allowed,
      nullif(btrim(seg.value->>'ref_num'),'') ref_num,
      case when pg_input_is_valid(
          seg.value->>'start_utc','timestamp with time zone')
        then(seg.value->>'start_utc')::timestamptz end start_utc,
      case when pg_input_is_valid(
          seg.value->>'end_utc','timestamp with time zone')
        then(seg.value->>'end_utc')::timestamptz end end_utc,
      lower(coalesce(seg.value->>'is_reversal','false')) in(
        'true','t','1','yes') is_reversal
    from source_rows s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)
      seg(value)
    where s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
  ),
  segment_lock_targets_pre as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'invoice_id',s.planned_invoice_id,
      'timesheet_id',s.timesheet_id,
      'segment_ids',to_jsonb(p.segment_ids),
      'expected_financial_revision',encode(digest(jsonb_build_object(
        'financial_id',s.id,
        'timesheet_version',s.timesheet_version,
        'updated_at',s.updated_at,
        'basis',s.basis,
        'invoice_breakdown_json',s.invoice_breakdown_json
      )::text,'sha256'),'hex'))
      order by s.planned_invoice_id,s.timesheet_id),'[]'::jsonb) targets
    from source_rows s
    join selected_segments p
      on p.chunk_id=s.chunk_id and p.timesheet_id=s.timesheet_id
    where cardinality(coalesce(p.segment_ids,array[]::text[]))>0
      and exists(
        select 1
        from public.invoices existing_header
        where existing_header.id=s.planned_invoice_id)
  ),
  segment_lock_authority_pre as materialized (
    select r.*
    from segment_lock_targets_pre t
    cross join lateral private._invoice_segment_lock_batch(t.targets,v_now) r
  ),
  segment_lock_failures_pre as materialized (
    select * from segment_lock_authority_pre where not success
  ),
  segment_entries as materialized (
    select s.*,seg.ordinality,
      coalesce(nullif(seg.value->>'segment_id',''),
        left(encode(digest(seg.value::text,'sha256'),'hex'),24)) segment_id,
      case when left(coalesce(seg.value->>'date',''),10)
        ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        then left(seg.value->>'date',10) end work_date,
      case when coalesce(seg.value->>'hours_day','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_day')::numeric
        else 0 end segment_hours_day,
      case when coalesce(seg.value->>'hours_night','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_night')::numeric
        else 0 end segment_hours_night,
      case when coalesce(seg.value->>'hours_sat','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_sat')::numeric
        else 0 end segment_hours_sat,
      case when coalesce(seg.value->>'hours_sun','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_sun')::numeric
        else 0 end segment_hours_sun,
      case when coalesce(seg.value->>'hours_bh','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_bh')::numeric
        else 0 end segment_hours_bh,
      case
        when coalesce(seg.value->>'pay_amount','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'pay_amount')::numeric
        when coalesce(seg.value->>'pay_ex_vat','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'pay_ex_vat')::numeric
        else 0 end segment_pay_ex,
      case
        when coalesce(seg.value->>'charge_amount','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'charge_amount')::numeric
        when coalesce(seg.value->>'charge_ex_vat','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'charge_ex_vat')::numeric
        else 0 end segment_charge_ex
    from (
      select distinct on (base.chunk_id,base.timesheet_id) base.*
      from source_rows base
      order by base.chunk_id,base.timesheet_id,base.source_member_key
    ) s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)
      with ordinality seg(value,ordinality)
    where upper(coalesce(s.invoice_breakdown_json->>'mode',''))='SEGMENTS'
      and nullif(seg.value->>'invoice_locked_invoice_id','') is null
      and exists(
        select 1 from selected_segments picked
        where picked.chunk_id=s.chunk_id
          and picked.timesheet_id=s.timesheet_id
          and coalesce(nullif(seg.value->>'segment_id',''),
            left(encode(digest(seg.value::text,'sha256'),'hex'),24))
            =any(coalesce(picked.segment_ids,array[]::text[])))
  ),
  segment_daily_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,s.work_date,
      sum(s.segment_hours_day) h_day,sum(s.segment_hours_night) h_night,
      sum(s.segment_hours_sat) h_sat,sum(s.segment_hours_sun) h_sun,
      sum(s.segment_hours_bh) h_bh,sum(s.segment_pay_ex) pay_ex,
      sum(s.segment_charge_ex) charge_ex,max(s.vat_rate) vat_rate,
      max(s.charge_day) charge_day,max(s.charge_night) charge_night,
      max(s.charge_sat) charge_sat,max(s.charge_sun) charge_sun,
      max(s.charge_bh) charge_bh,
      max(s.timesheet_version) timesheet_version,
      (array_agg(s.id order by s.id))[1] tsfin_id,
      max(s.contract_role) contract_role,
      max(s.contract_display_site) contract_display_site,
      max(s.contract_ward_hint) contract_ward_hint,
      (array_agg(s.bucket_labels_json order by s.ordinality))[1]
        bucket_labels_json
    from segment_entries s
    where s.daily_calc_of_invoices and s.work_date is not null
    group by s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,s.work_date
  ),
  segment_weekly_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,
      sum(s.segment_hours_day) h_day,sum(s.segment_hours_night) h_night,
      sum(s.segment_hours_sat) h_sat,sum(s.segment_hours_sun) h_sun,
      sum(s.segment_hours_bh) h_bh,sum(s.segment_pay_ex) pay_ex,
      sum(s.segment_charge_ex) charge_ex,max(s.vat_rate) vat_rate,
      max(s.charge_day) charge_day,max(s.charge_night) charge_night,
      max(s.charge_sat) charge_sat,max(s.charge_sun) charge_sun,
      max(s.charge_bh) charge_bh,
      max(s.timesheet_version) timesheet_version,
      (array_agg(s.id order by s.id))[1] tsfin_id,
      max(s.contract_role) contract_role,
      max(s.contract_display_site) contract_display_site,
      max(s.contract_ward_hint) contract_ward_hint,
      (array_agg(s.bucket_labels_json order by s.ordinality))[1]
        bucket_labels_json
    from segment_entries s
    where not s.daily_calc_of_invoices
       or not exists(select 1 from segment_entries d
         where d.chunk_id=s.chunk_id and d.timesheet_id=s.timesheet_id
           and d.daily_calc_of_invoices and d.work_date is not null)
    group by s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date
  ),
  nonsegment_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      coalesce(s.hours_day,0) h_day,coalesce(s.hours_night,0) h_night,coalesce(s.hours_sat,0) h_sat,
      coalesce(s.hours_sun,0) h_sun,coalesce(s.hours_bh,0) h_bh,
      round(coalesce(s.total_pay_ex_vat,0)-coalesce(s.additional_pay_ex_vat,0)
        -coalesce(s.expenses_pay_ex_vat,0)-coalesce(s.mileage_pay_ex_vat,0),2) pay_ex,
      round(coalesce(s.total_charge_ex_vat,0)-coalesce(s.additional_charge_ex_vat,0)
        -coalesce(s.expenses_charge_ex_vat,0)-coalesce(s.mileage_charge_ex_vat,0),2) charge_ex,
      s.vat_rate,s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,
      s.charge_bh,s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    where upper(coalesce(s.invoice_breakdown_json->>'mode',''))<>'SEGMENTS'
       or jsonb_array_length(case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
                                  then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)=0
  ),
  additional_daily_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,upper(a.key) code,
      left(d.key,10) work_date,
      case when pg_input_is_valid(d.value,'numeric')
        then d.value::numeric else 0 end units,
      case when pg_input_is_valid(a.value->>'pay_rate','numeric')
        then(a.value->>'pay_rate')::numeric else 0 end pay_rate,
      case when pg_input_is_valid(a.value->>'charge_rate','numeric')
        then(a.value->>'charge_rate')::numeric else 0 end charge_rate,
      round((case when pg_input_is_valid(d.value,'numeric')
          then d.value::numeric else 0 end)*
        (case when pg_input_is_valid(a.value->>'pay_rate','numeric')
          then(a.value->>'pay_rate')::numeric else 0 end),2) pay_ex,
      round((case when pg_input_is_valid(d.value,'numeric')
          then d.value::numeric else 0 end)*
        (case when pg_input_is_valid(a.value->>'charge_rate','numeric')
          then(a.value->>'charge_rate')::numeric else 0 end),2) charge_ex,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) bucket_name,
      coalesce(nullif(a.value->>'unit_name',''),'units') unit_name,
      a.value->'frequency' frequency,s.vat_rate,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    cross join lateral jsonb_each(
      case when jsonb_typeof(s.additional_units_json)='object'
        then s.additional_units_json else '{}'::jsonb end) a
    cross join lateral jsonb_each_text(
      case when jsonb_typeof(a.value->'days')='object'
        then a.value->'days' else '{}'::jsonb end) d
    where s.daily_calc_of_invoices
      and left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      and exists(select 1 from segment_entries se
        where se.chunk_id=s.chunk_id and se.timesheet_id=s.timesheet_id
          and se.work_date is not null)
  ),
  additional_weekly_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      upper(a.key) code,
      case when pg_input_is_valid(a.value->>'unit_count','numeric')
        then(a.value->>'unit_count')::numeric else 0 end units,
      case when pg_input_is_valid(a.value->>'pay_rate','numeric')
        then(a.value->>'pay_rate')::numeric else 0 end pay_rate,
      case when pg_input_is_valid(a.value->>'charge_rate','numeric')
        then(a.value->>'charge_rate')::numeric else 0 end charge_rate,
      case when pg_input_is_valid(a.value->>'pay_ex_vat','numeric')
        then(a.value->>'pay_ex_vat')::numeric else 0 end pay_ex,
      case when pg_input_is_valid(a.value->>'charge_ex_vat','numeric')
        then(a.value->>'charge_ex_vat')::numeric else 0 end charge_ex,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) bucket_name,
      coalesce(nullif(a.value->>'unit_name',''),'units') unit_name,
      a.value->'frequency' frequency,s.vat_rate,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s cross join lateral jsonb_each(
      case when jsonb_typeof(s.additional_units_json)='object'
        then s.additional_units_json else '{}'::jsonb end) a
    where jsonb_typeof(a.value)='object'
      and ((case when pg_input_is_valid(a.value->>'pay_ex_vat','numeric')
              then(a.value->>'pay_ex_vat')::numeric else 0 end)<>0
        or (case when pg_input_is_valid(a.value->>'charge_ex_vat','numeric')
              then(a.value->>'charge_ex_vat')::numeric else 0 end)<>0)
      and not(s.daily_calc_of_invoices
        and jsonb_typeof(a.value->'days')='object'
        and exists(select 1 from jsonb_each_text(
          case when jsonb_typeof(a.value->'days')='object'
            then a.value->'days' else '{}'::jsonb end) d
          where left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'))
  ),
  expense_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      e.code,e.pay_ex,e.charge_ex,s.vat_rate,s.expenses_description,
      s.expenses_evidence_r2_key,s.expenses_evidence_manifest,
      s.mileage_units,s.mileage_pay_rate,s.mileage_charge_rate,
      s.mileage_evidence_r2_key,s.mileage_evidence_manifest,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    cross join lateral (
      values
       ('TRAVEL',coalesce(s.travel_pay_ex_vat,0),coalesce(s.travel_charge_ex_vat,0)),
       ('ACCOMMODATION',coalesce(s.accommodation_pay_ex_vat,0),coalesce(s.accommodation_charge_ex_vat,0)),
       ('OTHER',coalesce(s.other_pay_ex_vat,0),coalesce(s.other_charge_ex_vat,0)),
       ('EXPENSES_FALLBACK',
          case when coalesce(s.travel_pay_ex_vat,0)+coalesce(s.accommodation_pay_ex_vat,0)+coalesce(s.other_pay_ex_vat,0)=0 then coalesce(s.expenses_pay_ex_vat,0) else 0 end,
          case when coalesce(s.travel_charge_ex_vat,0)+coalesce(s.accommodation_charge_ex_vat,0)+coalesce(s.other_charge_ex_vat,0)=0 then coalesce(s.expenses_charge_ex_vat,0) else 0 end),
       ('MILEAGE',coalesce(s.mileage_pay_ex_vat,0),coalesce(s.mileage_charge_ex_vat,0))
    ) e(code,pay_ex,charge_ex)
    where e.pay_ex<>0 or e.charge_ex<>0
  ),
  line_union as materialized (
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||work_date description,h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric pay_day,null::numeric pay_night,null::numeric pay_sat,
      null::numeric pay_sun,null::numeric pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_DAILY' line_type,
      'TS:'||timesheet_id||':HOURS:'||work_date source_key,
      jsonb_build_object('date',work_date,'timesheet_version',timesheet_version,
        'tsfin_id',tsfin_id,'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json) detail
    from segment_daily_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - W/E '||week_ending_date, h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_WEEKLY','TS:'||timesheet_id||':HOURS:WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json)
    from segment_weekly_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - W/E '||week_ending_date, h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_WEEKLY','TS:'||timesheet_id||':HOURS:WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json)
    from nonsegment_lines
    where pay_ex<>0 or charge_ex<>0 or h_day+h_night+h_sat+h_sun+h_bh<>0
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||bucket_name||' - '||work_date||' - '||
        units||' '||unit_name,0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'ADDITIONAL_RATE_DAILY',
      'TS:'||timesheet_id||':ADD:'||code||':'||work_date,
      jsonb_build_object('date',work_date,'timesheet_version',timesheet_version,
        'tsfin_id',tsfin_id,'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'bucket',jsonb_build_object('code',code,'bucket_name',bucket_name,
          'unit_name',unit_name,'frequency',frequency),
        'units',jsonb_build_object('unit_count',units,'pay_rate',pay_rate,
          'charge_rate',charge_rate))
    from additional_daily_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||bucket_name||' - '||units||' '||unit_name,0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'ADDITIONAL_RATE',
      'TS:'||timesheet_id||':ADD:'||code||':WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'bucket',jsonb_build_object('code',code,'bucket_name',bucket_name,
          'unit_name',unit_name,'frequency',frequency),
        'units',jsonb_build_object('unit_count',units,'pay_rate',pay_rate,
          'charge_rate',charge_rate))
    from additional_weekly_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      case when code='MILEAGE' then 'Mileage - '||coalesce(mileage_units,0)||
          ' miles (W/E '||week_ending_date||')'
        else initcap(replace(code,'_',' '))||' (W/E '||week_ending_date||')' end,
      0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,
      case when code='MILEAGE' then 'MILEAGE'
        when code='EXPENSES_FALLBACK' then 'EXPENSES_TOTAL'
        else 'EXPENSE_'||code end,
      case when code='MILEAGE' then 'TS:'||timesheet_id||':MILEAGE'
        when code='EXPENSES_FALLBACK' then 'TS:'||timesheet_id||':EXP:TOTAL'
        else 'TS:'||timesheet_id||':EXP:'||code end,
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'expense',case when code='MILEAGE' then jsonb_build_object(
          'category','MILEAGE','mileage_units',mileage_units,
          'pay_rate',mileage_pay_rate,'charge_rate',mileage_charge_rate,
          'evidence_r2_key',mileage_evidence_r2_key,
          'evidence_manifest',mileage_evidence_manifest)
        else jsonb_build_object('category',code,'note',expenses_description,
          'evidence_r2_key',expenses_evidence_r2_key,
          'evidence_manifest',expenses_evidence_manifest) end)
    from expense_lines
  ),
  correction_scopes_pre as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-prewrite:'||scope.planned_invoice_id::text,
      'scope_key',scope.planned_invoice_id::text,
      'invoice_id',case when exists(select 1 from public.invoices existing
        where existing.id=scope.planned_invoice_id)
        then scope.planned_invoice_id end,
      'validation_purpose','GENERATION_PREWRITE',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.planned_invoice_id),'[]'::jsonb) scopes
    from(
      select l.planned_invoice_id,min(vc.payload_json::text)::jsonb payload_json,
        jsonb_agg(distinct jsonb_build_object(
          'timesheet_id',l.timesheet_id,
          'vat_rate_pct',l.vat_rate))
          filter(where l.timesheet_id is not null) planned_members
      from line_union l
      join valid_chunks vc on vc.id=l.chunk_id
      group by l.planned_invoice_id
    ) scope
  ),
  correction_validation_pre as materialized (
    select r.*
    from correction_scopes_pre s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),
  correction_failures_pre as materialized (
    select scope_key,blocker_code,detail_json detail
    from correction_validation_pre
    where not valid
  ),  write_eligible_chunks as materialized (
    select vc.*
    from valid_chunks vc
    where not exists(
      select 1 from correction_failures_pre f
      where f.scope_key=vc.planned_invoice_id::text)
  ),
  line_totals as materialized (
    select l.planned_invoice_id,
      round(sum(round(l.charge_ex,2)),2) subtotal_ex_vat,
      round(sum(round(l.charge_ex*l.vat_rate/100,2)),2) vat_amount,
      round(sum(round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2)),2) total_inc_vat
    from line_union l
    join write_eligible_chunks w on w.id=l.chunk_id
    group by l.planned_invoice_id
  ),
  existing_target_headers as materialized (
    select vc.id chunk_id,i.id invoice_id
    from write_eligible_chunks vc
    join header_source h on h.chunk_id=vc.id
    join public.invoices i on i.id=vc.planned_invoice_id
      and i.client_id=h.client_id and i.type='INVOICE' and i.status='DRAFT'
    where not exists(
      select 1 from segment_lock_failures_pre f
      where f.invoice_id=vc.planned_invoice_id)
  ),
  inserted_headers as (
    insert into public.invoices(id,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
      header_snapshot_json,document_revision,document_state,created_at,updated_at)
    select h.planned_invoice_id,h.client_id,'DRAFT',v_now,
      t.subtotal_ex_vat,t.vat_amount,t.total_inc_vat,
      jsonb_build_object('client_id',h.client_id,'client_name',h.client_name)
      ||case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
        then jsonb_build_object('invoice_stream',upper(coalesce(vc.payload_json->>'invoice_stream','NORMAL')))
        else '{}'::jsonb end
      ||jsonb_build_object(
        'client_invoice_address',h.client_invoice_address,'client_primary_invoice_email',h.primary_invoice_email,
        'agency_name',h.agency_name,'agency_logo',h.agency_logo,'registered_address',h.registered_address,
        'company_reg_number',h.company_reg_number,'company_registration_number',h.company_reg_number,
        'vat_chargeable',h.vat_chargeable,'payment_terms_days',h.payment_terms_days,
        'issued_at_utc',null,'due_at_utc',null,
        'totals',jsonb_build_object(
          'subtotal_ex_vat',t.subtotal_ex_vat,
          'vat_amount',t.vat_amount,'total_inc_vat',t.total_inc_vat),
        'bank',jsonb_build_object('name',h.bank_name,'sort_code',h.bank_sort_code,'account_number',h.bank_account_number),
        'vat_registration_number',h.vat_registration_number,
        'meta',jsonb_build_object('source','INVOICE_OPERATION_QUEUE',
          'invoice_week_start',vc.payload_json->>'target_invoice_week',
          'consolidation_mode',vc.payload_json->>'consolidation_mode',
          'self_bill',vc.payload_json->>'invoice_stream'='SELF_BILL','timesheet_count',h.source_count)
          ||case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
            then jsonb_build_object('invoice_stream',upper(coalesce(vc.payload_json->>'invoice_stream','NORMAL')))
            else '{}'::jsonb end,
        'attach_policy',vc.payload_json#>'{plan,settings_snapshot,attach_policy}'),
      1,'STALE',v_now,v_now
    from header_source h join write_eligible_chunks vc on vc.id=h.chunk_id
    join line_totals t on t.planned_invoice_id=h.planned_invoice_id
    where not exists(
      select 1 from segment_lock_failures_pre f
      where f.invoice_id=h.planned_invoice_id)
    on conflict(id) do nothing returning id
  ),
  target_headers as materialized (
    select e.chunk_id,e.invoice_id
    from existing_target_headers e
    where not exists(
      select 1
      from inserted_headers h
      where h.id=e.invoice_id)
  ),
  deferred_new_headers as (
    update public.invoice_operation_chunks c
    set status='QUEUED',
      phase='COMMIT',
      progress_json=coalesce(c.progress_json,'{}'::jsonb)
        ||jsonb_build_object('status_message',
          'Invoice header created; applying authoritative source ownership'),
      error_json=null,
      lease_owner=null,
      lease_token=null,
      lease_expires_at_utc=null,
      updated_at_utc=v_now
    from inserted_headers h
    join write_eligible_chunks vc on vc.planned_invoice_id=h.id
    where c.id=vc.id
    returning c.id
  ),
  inserted_lines as (
    insert into public.invoice_lines(
      invoice_id,timesheet_id,booking_id,description,hours_day,hours_night,hours_sat,hours_sun,hours_bh,
      pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,
      paper_ts_r2_key,meta_json,source_key
    )
    select l.planned_invoice_id,l.timesheet_id,l.booking_id,l.description,
      round(l.h_day,2),round(l.h_night,2),round(l.h_sat,2),round(l.h_sun,2),round(l.h_bh,2),
      l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
      l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,
      round(l.pay_ex,2),round(l.charge_ex,2),round(l.charge_ex-l.pay_ex,2),l.vat_rate,
      round(l.charge_ex*l.vat_rate/100,2),round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2),
      null,jsonb_build_object('line_type',l.line_type,'timesheet_id',l.timesheet_id,
        'candidate_display',l.description,'week_ending_date',
        (select s.week_ending_date from source_rows s where s.timesheet_id=l.timesheet_id limit 1),
        'schedule_references',
        (select s.schedule_refs from source_rows s where s.timesheet_id=l.timesheet_id limit 1),
        'totals',jsonb_build_object('line_pay_ex_vat',round(l.pay_ex,2),
          'line_charge_ex_vat',round(l.charge_ex,2),'margin_ex_vat',round(l.charge_ex-l.pay_ex,2),
          'vat_rate_pct',l.vat_rate,'vat_amount',round(l.charge_ex*l.vat_rate/100,2),
          'total_inc_vat',round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2)))||l.detail,l.source_key
    from line_union l join target_headers h on h.invoice_id=l.planned_invoice_id
    on conflict(invoice_id,source_key) do nothing
    returning invoice_id,timesheet_id,total_charge_ex_vat,vat_amount,total_inc_vat
  ),
  all_target_lines as materialized (
    select l.invoice_id,l.total_charge_ex_vat,l.vat_amount,l.total_inc_vat
    from public.invoice_lines l
    where l.invoice_id in(select invoice_id from target_headers)
    union all
    select l.invoice_id,l.total_charge_ex_vat,l.vat_amount,l.total_inc_vat
    from inserted_lines l
  ),
  all_line_totals as materialized (
    select l.invoice_id,count(*)::integer line_count,
      round(sum(l.total_charge_ex_vat),2) subtotal_ex_vat,
      round(sum(l.vat_amount),2) vat_amount,
      round(sum(l.total_inc_vat),2) total_inc_vat
    from all_target_lines l
    group by l.invoice_id
  ),
  target_header_streams as materialized (
    select h.invoice_id,
      max(upper(coalesce(c.payload_json->>'invoice_stream','NORMAL'))) invoice_stream
    from target_headers h
    join public.invoice_operation_chunks c on c.id=h.chunk_id
    group by h.invoice_id
  ),
  updated_header_totals as (
    update public.invoices i
    set subtotal_ex_vat=t.subtotal_ex_vat,vat_amount=t.vat_amount,
      total_inc_vat=t.total_inc_vat,document_state='STALE',
      header_snapshot_json=coalesce(i.header_snapshot_json,'{}'::jsonb)
        ||jsonb_build_object('totals',jsonb_build_object(
          'subtotal_ex_vat',t.subtotal_ex_vat,'vat_amount',t.vat_amount,
          'total_inc_vat',t.total_inc_vat))
        ||case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
          then jsonb_build_object(
            'invoice_stream',s.invoice_stream,
            'meta',coalesce(i.header_snapshot_json->'meta','{}'::jsonb)
              ||jsonb_build_object('invoice_stream',s.invoice_stream))
          else '{}'::jsonb end,
      updated_at=v_now
    from all_line_totals t
    join target_header_streams s on s.invoice_id=t.invoice_id
    where i.id=t.invoice_id
    returning i.id
  ),
  segment_lock_targets as materialized (
    select targets from segment_lock_targets_pre
  ),
  segment_lock_authority as materialized (
    select * from segment_lock_authority_pre
  ),
  segment_lock_failures as materialized (
    select * from segment_lock_authority where not success
  ),
  whole_lock as (
    update public.timesheets_financials tf
    set locked_by_invoice_id=vc.planned_invoice_id,locked_at_utc=v_now,updated_at=v_now
    from members m join write_eligible_chunks vc on vc.id=m.chunk_id
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    cross join (select count(*) applied_count from segment_lock_authority) segment_application
    where tf.timesheet_id=m.timesheet_id and tf.is_current
      and (coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS'
        or not exists(select 1 from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) e
                      where nullif(e->>'invoice_locked_invoice_id','') is null))
    returning tf.timesheet_id
  ),
  week_lock as (
    update public.contract_weeks cw set status='INVOICED',updated_at=v_now
    where cw.timesheet_id in(
      select m.timesheet_id
      from members m
      join target_headers h on h.chunk_id=m.chunk_id)
      and exists(select 1 from public.timesheets_financials tf where tf.timesheet_id=cw.timesheet_id
        and tf.is_current and (tf.locked_by_invoice_id is not null or
          not exists(select 1 from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) e
                     where nullif(e->>'invoice_locked_invoice_id','') is null)))
    returning cw.id
  ),
  nhsp_shift_inclusion as (
    update public.nhsp_shifts ns
    set invoice_status='INCLUDED',
      invoice_id=h.invoice_id,
      updated_at=v_now
    from source_rows s
    join target_headers h
      on h.chunk_id=s.chunk_id and h.invoice_id=s.planned_invoice_id
    where ns.timesheet_id=s.timesheet_id
      and ns.invoice_status='PENDING'
      and ns.invoice_id is null
      and ns.cancelled_at_utc is null
      and exists(
        select 1
        from jsonb_array_elements(
          case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
            then s.invoice_breakdown_json->'segments'
            else '[]'::jsonb end) segment(value)
        where coalesce(
            nullif(segment.value->>'nhsp_shift_id',''),
            nullif(segment.value->>'shift_id',''))=ns.id::text)
    returning ns.id
  ),
  hr_sources as (
    insert into public.invoice_hr_source_rows(invoice_id,source_system,import_id,header_columns,rows_json,header_rows)
    select distinct h.invoice_id,
      case when tf.basis::text in('NHSP','NHSP_ADJUSTMENT')
        then 'NHSP' else 'HEALTHROSTER' end,
      tf.nhsp_import_id,'[]'::jsonb,
      case when jsonb_typeof(tf.external_source_rows_json)='array' then tf.external_source_rows_json else '[]'::jsonb end,
      '[]'::jsonb
    from members m
    join target_headers h on h.chunk_id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    where tf.nhsp_import_id is not null
    on conflict(invoice_id,source_system,import_id) do update set rows_json=excluded.rows_json
    returning invoice_id
  ),
  source_segments as materialized (
    select distinct h.invoice_id planned_invoice_id,
      coalesce(
        case when coalesce(x.value->>'nhsp_shift_id','')~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(x.value->>'nhsp_shift_id')::uuid end,
        case when coalesce(x.value->>'shift_id','')~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(x.value->>'shift_id')::uuid end,
        case when substr(coalesce(x.value->>'segment_id',''),6)~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then substr(x.value->>'segment_id',6)::uuid end) shift_id,
      case
        when s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
         and (
           lower(coalesce(x.value->>'is_reversal','false')) in(
             'true','t','1','yes')
           or coalesce(s.total_hours,0)<0
         ) then 'REVERSAL'
        when s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
          then 'CORRECTED_HOURS'
        else 'SOURCE'
      end evidence_role_key
    from source_rows s
    join target_headers h
      on h.chunk_id=s.chunk_id and h.invoice_id=s.planned_invoice_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end) x(value)
    where coalesce(
        nullif(x.value->>'nhsp_shift_id',''),
        nullif(x.value->>'shift_id',''),
        case when left(x.value->>'segment_id',5)='nhsp:'
          then substr(x.value->>'segment_id',6) end)~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and (
        upper(coalesce(x.value->>'source_system',''))='NHSP'
        or (upper(coalesce(x.value->>'source_system',''))='HEALTHROSTER'
          and coalesce((s.payload_json#>>'{plan,settings_snapshot,attach_policy,hr_attach_to_invoice}')::boolean,true)))
    union
    select distinct r.planned_invoice_id,n.id shift_id,
      case when r.is_reversal then 'REVERSAL'
        else 'CORRECTED_HOURS' end evidence_role_key
    from adjustment_segment_refs r
    join source_timesheet_ancestry a
      on a.planned_invoice_id=r.planned_invoice_id
     and a.root_timesheet_id=r.root_timesheet_id
     and a.ancestry_depth>0
    join public.nhsp_shifts n
      on n.timesheet_id=a.source_timesheet_id
     and n.latest_import_id is not null
     and n.external_row_key is not null
     and (
       upper(coalesce(n.source_system::text,''))='NHSP'
       or (
         upper(coalesce(n.source_system::text,''))='HEALTHROSTER'
         and r.healthroster_attach_allowed
       )
     )
     and (
       (r.ref_num is not null
         and btrim(coalesce(n.ref_num,''))=r.ref_num)
       or (
         r.ref_num is null
         and r.start_utc is not null
         and r.end_utc is not null
         and n.start_utc=r.start_utc
         and n.end_utc=r.end_utc
       )
     )
  ),
  source_import_rows as materialized (
    select distinct s.planned_invoice_id,
      upper(coalesce(n.source_system::text,'UNKNOWN')) source_system,
      n.latest_import_id import_id,n.external_row_key,s.evidence_role_key
    from source_segments s
    join public.nhsp_shifts n on n.id=s.shift_id
    where n.latest_import_id is not null
      and n.external_row_key is not null
  ),
  source_imports as materialized (
    select s.planned_invoice_id,s.source_system,s.import_id,
      jsonb_agg(jsonb_build_object(
        'external_row_key',s.external_row_key,
        'evidence_role_key',s.evidence_role_key)
        order by s.external_row_key,s.evidence_role_key) row_occurrences
    from source_import_rows s
    group by s.planned_invoice_id,s.source_system,s.import_id
  ),
  authoritative_hr_sources as (
    insert into public.invoice_hr_source_rows(
      invoice_id,source_system,import_id,header_columns,rows_json)
    select g.planned_invoice_id,g.source_system,g.import_id,
      case when jsonb_typeof(i.parse_summary_json->'header_columns')='array'
        then i.parse_summary_json->'header_columns' else '[]'::jsonb end,
      coalesce((select jsonb_agg(
          r.payload_json
            ||jsonb_build_object(
              'evidence_role',case occurrence.value->>'evidence_role_key'
                when 'REVERSAL' then case when g.source_system='NHSP'
                  then 'NHSP Reversal' else 'HealthRoster Reversal' end
                when 'CORRECTED_HOURS' then case when g.source_system='NHSP'
                  then 'NHSP Corrected Hours' else 'HealthRoster Corrected Hours' end
                else case when g.source_system='NHSP'
                  then 'NHSP Shift' else 'HealthRoster Shift' end
              end)
            ||case when occurrence.value->>'evidence_role_key'='REVERSAL'
              then jsonb_build_object('reversal_state','REVERSED')
              else '{}'::jsonb end
          order by r.id,occurrence.value->>'evidence_role_key')
        from jsonb_array_elements(g.row_occurrences) occurrence(value)
        join public.hr_rows r
          on r.import_id=g.import_id
         and r.external_row_key=occurrence.value->>'external_row_key'),
        '[]'::jsonb)
    from source_imports g join public.hr_imports i on i.id=g.import_id
    on conflict(invoice_id,source_system,import_id) do update
      set header_columns=excluded.header_columns,rows_json=excluded.rows_json
    returning invoice_id
  ),
  audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,after_json,reason)
    select v_now,o.actor_user_id,u.display_name,u.role,'invoices',vc.planned_invoice_id::text,
      case when exists(select 1 from inserted_headers h
        where h.id=vc.planned_invoice_id)
        then 'INVOICE_CREATED' else 'INVOICE_DRAFT_APPENDED' end,
      jsonb_build_object('invoice_id',vc.planned_invoice_id,
        'source_ids',coalesce(vc.payload_json->'canonical_source_ids',
          vc.payload_json->'source_ids','[]'::jsonb),
        'source_revision',vc.payload_json->>'source_revision',
        'operation_id',vc.operation_id),'INVOICE_OPERATION_QUEUE'
    from write_eligible_chunks vc
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    join public.invoice_operations o on o.id=vc.operation_id
    left join public.tms_users u on u.id=o.actor_user_id
    returning id
  ),
  correction_failures as materialized (
    select scope_key::uuid invoice_id,blocker_code,detail
    from correction_failures_pre
    where scope_key~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  update public.invoice_operation_chunks c
    set status=case when exists(select 1 from all_line_totals l
                               where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then 'COMPLETE' else 'BLOCKED' end,
      phase=case when exists(select 1 from all_line_totals l
                            where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then 'COMPLETE' else 'BLOCKED' end,
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(vc.planned_invoice_id),
        'source_revision',vc.payload_json->>'source_revision'),
      error_json=case
        when not exists(select 1 from all_line_totals l
          where l.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code','NO_INVOICE_LINES_CREATED')
        when exists(select 1 from segment_lock_failures sf
          where sf.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code','SEGMENT_LOCK_FAILED','detail',(
            select jsonb_agg(to_jsonb(sf))
            from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id))
        when exists(select 1 from correction_failures cf
          where cf.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code',(
            select cf.blocker_code from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id))
        else null end,
      completed_at_utc=case
        when exists(select 1 from all_line_totals l
          where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then v_now else null end,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from valid_chunks vc
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    cross join (select count(*) applied_count from segment_lock_authority) segment_application
    cross join (select count(*) cached_count from authoritative_hr_sources) source_cache_application
    where c.id=vc.id
  ;
  select coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,
      'result',c.result_json,'error',c.error_json)),'[]'::jsonb)
    into v_part
  from jsonb_array_elements(p_claims) x
  join public.invoice_operation_chunks c
    on c.id=case when coalesce(x->>'chunk_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x->>'chunk_id')::uuid end
  where x->>'phase'='COMMIT'
    and coalesce(c.payload_json->>'command_type','')<>'GENERATE_CREDIT_NOTE';
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Credit-note COMMIT: exact negative line clone and source unlock; document creation stays asynchronous.
  execute $q$
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements($1) x where x->>'phase'='COMMIT'
  ),
  credit_revisions as materialized (
    select c.*,i.id source_invoice_id,(c.payload_json#>>'{plan,planned_invoice_id}')::uuid credit_note_id
      ,encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),
        'sha256'),'hex') current_revision
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i on i.id=c.entity_id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
      and i.type='INVOICE' and i.status in ('ISSUED','PAID')
  ),
  credit_correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','credit-source:'||c.source_invoice_id::text,
      'scope_key',c.source_invoice_id::text,
      'invoice_id',c.source_invoice_id,
      'validation_purpose','CREDIT_SOURCE')
      order by c.source_invoice_id),'[]'::jsonb) scopes
    from(select distinct source_invoice_id from credit_revisions) c
  ),
  credit_correction_failures as materialized (
    select r.invoice_id source_invoice_id,r.blocker_code,r.detail_json
    from credit_correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,($2 at time zone 'Europe/London')::date) r
    where not r.valid
  ),
  credit_rejected as (
    update public.invoice_operation_chunks q
    set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code',case
        when c.current_revision<>c.payload_json->>'source_revision'
          then 'CREDIT_SOURCE_CHANGED_BEFORE_COMMIT'
        else coalesce((select f.blocker_code
          from credit_correction_failures f
          where f.source_invoice_id=c.source_invoice_id
          order by f.blocker_code limit 1),'CREDIT_CORRECTION_VALIDATION_FAILED')
        end),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=$2
    from credit_revisions c
    where q.id=c.id and(
      c.current_revision<>c.payload_json->>'source_revision'
      or exists(select 1 from credit_correction_failures f
        where f.source_invoice_id=c.source_invoice_id))
    returning q.id
  ),
  credits as materialized (
    select c.* from credit_revisions c
    where c.current_revision=c.payload_json->>'source_revision'
      and not exists(select 1 from credit_rejected r where r.id=c.id)
  ),
  inserted_credit as (
    insert into public.invoices(id,type,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
      original_invoice_id,notes,header_snapshot_json,document_revision,document_state,created_at,updated_at)
    select c.credit_note_id,'CREDIT_NOTE',i.client_id,'DRAFT',$2,
      -i.subtotal_ex_vat,-i.vat_amount,-i.total_inc_vat,i.id,
      c.payload_json->>'credit_reason',
      i.header_snapshot_json||jsonb_build_object(
        'credit_source_invoice_id',i.id,
        'credit_reason',c.payload_json->>'credit_reason'),1,'STALE',$2,$2
    from credits c join public.invoices i on i.id=c.source_invoice_id
    on conflict(id) do nothing returning id
  ),
  cloned_lines as (
    insert into public.invoice_lines(invoice_id,timesheet_id,booking_id,description,
      hours_day,hours_night,hours_sat,hours_sun,hours_bh,pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,total_pay_ex_vat,total_charge_ex_vat,
      margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,paper_ts_r2_key,meta_json,source_key)
    select c.credit_note_id,l.timesheet_id,l.booking_id,
      'CREDIT NOTE – '||coalesce(l.description,''),
      l.hours_day,l.hours_night,l.hours_sat,l.hours_sun,l.hours_bh,
      l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
      l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,
      -l.total_pay_ex_vat,-l.total_charge_ex_vat,-l.margin_ex_vat,l.vat_rate_pct,
      -l.vat_amount,-l.total_inc_vat,l.paper_ts_r2_key,
      coalesce(l.meta_json,'{}'::jsonb)||jsonb_build_object(
        'credit_note',true,'original_invoice_id',c.source_invoice_id,
        'original_invoice_line_id',l.id,'credit_of_line_id',l.id,'line_type',
        'CREDIT_'||coalesce(l.meta_json->>'line_type','LINE')),
      'CN:'||c.credit_note_id||':LINE:'||l.id
    from credits c join public.invoice_lines l on l.invoice_id=c.source_invoice_id
    on conflict(invoice_id,source_key) do nothing returning invoice_id
  ),
  source_mark as (
    update public.invoices i set credit_note_created_at_utc=$2,updated_at=$2
    where i.id in(select source_invoice_id from credits) returning i.id
  ),
  unlocks as (
    update public.timesheets_financials tf
    set locked_by_invoice_id=null,locked_at_utc=null,
      unlocked_by_credit_note_id=c.credit_note_id,is_stale=true,
      stale_reason='UNLOCKED_BY_CREDIT',updated_at=$2
    from credits c
    where tf.locked_by_invoice_id=c.source_invoice_id and tf.is_current returning tf.timesheet_id
  ),
  segment_unlocks as (
    update public.timesheets_financials tf
    set invoice_breakdown_json=jsonb_set(tf.invoice_breakdown_json,'{segments}',
      (select jsonb_agg(case
        when e.value->>'invoice_locked_invoice_id'=c.source_invoice_id::text
          then (e.value-'invoice_locked_invoice_id'-'invoice_locked_at_utc')
        else e.value end order by e.ordinality)
       from jsonb_array_elements(tf.invoice_breakdown_json->'segments')
         with ordinality e(value,ordinality)),true),
      unlocked_by_credit_note_id=c.credit_note_id,is_stale=true,
      stale_reason='UNLOCKED_BY_CREDIT',updated_at=$2
    from credits c
    where tf.is_current and jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
      and exists(select 1 from jsonb_array_elements(tf.invoice_breakdown_json->'segments') e
        where e->>'invoice_locked_invoice_id'=c.source_invoice_id::text)
    returning tf.timesheet_id
  ),
  recompute_outbox as (
    insert into public.ts_financials_outbox(
      timesheet_id,reason,attempt_count,next_attempt_at,last_error,created_at)
    select distinct u.timesheet_id,'VERSION_ROTATED'::public.ts_fin_reason_enum,
      0,$2,null,$2
    from (
      select timesheet_id from unlocks
      union all select timesheet_id from segment_unlocks
    ) u
    on conflict on constraint uq_tsfin_outbox do nothing
    returning timesheet_id
  ),
  credit_audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,
      actor_role_at_time,object_type,object_id_text,action,after_json,reason)
    select $2,o.actor_user_id,u.display_name,u.role,'invoices',
      c.credit_note_id::text,'CREDIT_NOTE_CREATED',
      jsonb_build_object('credit_note_id',c.credit_note_id,
        'original_invoice_id',c.source_invoice_id,
        'credit_reason',c.payload_json->>'credit_reason',
        'command_token',c.payload_json->>'command_token',
        'subtotal_ex_vat',-i.subtotal_ex_vat,'vat_amount',-i.vat_amount,
        'total_inc_vat',-i.total_inc_vat,
        'financial_recompute_enqueued',true),
      'INVOICE_OPERATION_QUEUE'
    from credits c join public.invoices i on i.id=c.source_invoice_id
    join public.invoice_operations o on o.id=c.operation_id
    left join public.tms_users u on u.id=o.actor_user_id
    returning id
  ),
  completed as (
    update public.invoice_operation_chunks q
    set status='QUEUED',
      phase='QUEUE_DOCUMENT',
      error_json=null,
      completed_at_utc=null,lease_owner=null,lease_token=null,
      lease_expires_at_utc=null,updated_at_utc=$2,
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(c.credit_note_id),
        'credit_note_id',c.credit_note_id,'source_invoice_id',c.source_invoice_id)
    from credits c
    cross join (select count(*) outbox_count from recompute_outbox) outbox_application
    cross join (select count(*) audit_count from credit_audits) audit_application
    where q.id=c.id
    returning q.id,q.status,q.phase,q.result_json,q.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'chunk_id',id,'status',status,'phase',phase,
    'result',result_json,'error',error_json)),'[]'::jsonb)
  from completed
  $q$
  into v_part using p_claims,v_now;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Document work is queued in a separate SQL statement so source-invalidation
  -- statement triggers cannot supersede the freshly-created document operation.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='QUEUE_DOCUMENT'
  ),
  queued_sources as materialized (
    select c.id chunk_id,c.operation_id parent_operation_id,
      (c.payload_json#>>'{plan,planned_invoice_id}')::uuid planned_invoice_id,
      c.payload_json->>'source_revision' source_revision,
      c.payload_json->>'command_type' command_type,
      c.payload_json->>'command_token' command_token,
      c.payload_json->>'credit_reason' credit_reason,
      i.document_revision::text document_revision
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i
      on i.id=(c.payload_json#>>'{plan,planned_invoice_id}')::uuid
  ),
  existing_doc_versions as materialized (
    select distinct on(q.chunk_id) q.chunk_id,v.id document_version_id,
      v.operation_id,v.status
    from queued_sources q
    join public.invoice_document_versions v
      on v.entity_type='INVOICE'
     and v.entity_id=q.planned_invoice_id
     and v.purpose='DRAFT_PREVIEW'
     and v.source_revision=q.document_revision
     and v.template_version='invoice-professional-v2'
     and v.status in(
       'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING',
       'VERIFYING','READY')
    where q.command_type<>'GENERATE_CREDIT_NOTE'
    order by q.chunk_id,case when v.status='READY' then 0 else 1 end,
      v.created_at_utc desc,v.id desc
  ),
  doc_ops as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,created_at_utc,updated_at_utc)
    select q.parent_operation_id,'BUILD_DOCUMENT','INVOICE',q.planned_invoice_id,o.actor_user_id,
      encode(digest('DRAFT_PREVIEW|'||q.planned_invoice_id||'|'||q.document_revision||
        '|invoice-professional-v2','sha256'),'hex'),
      'QUEUED','BUILD_MANIFEST',550,q.document_revision,'invoice-professional-v2',
      jsonb_build_object('invoice_id',q.planned_invoice_id,'purpose','DRAFT_PREVIEW'),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,
      nextval('public.invoice_operation_change_seq'),v_now,v_now
    from queued_sources q join public.invoice_operations o on o.id=q.parent_operation_id
    where q.command_type<>'GENERATE_CREDIT_NOTE'
      and not exists(
        select 1 from existing_doc_versions e where e.chunk_id=q.chunk_id)
    on conflict(idempotency_key) where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,excluded.priority),updated_at_utc=v_now
    returning *
  ),
  selected_doc_ops as materialized (
    select q.chunk_id,q.planned_invoice_id,q.document_revision source_revision,
      d.id operation_id,d.control_version,null::uuid existing_version_id,
      null::text existing_status
    from queued_sources q join doc_ops d on d.entity_id=q.planned_invoice_id
    union all
    select q.chunk_id,q.planned_invoice_id,q.document_revision,
      e.operation_id,o.control_version,e.document_version_id,e.status
    from queued_sources q
    join existing_doc_versions e on e.chunk_id=q.chunk_id
    join public.invoice_operations o on o.id=e.operation_id
  ),
  doc_versions as materialized (
    insert into public.invoice_document_versions(entity_type,entity_id,purpose,operation_id,source_revision,
      template_version,status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select 'INVOICE',d.planned_invoice_id,'DRAFT_PREVIEW',d.operation_id,d.source_revision,
      'invoice-professional-v2','PLANNING','{}',encode(digest('{}','sha256'),'hex'),
      '[]',encode(digest('[]','sha256'),'hex'),v_now
    from selected_doc_ops d
    where d.existing_version_id is null
    on conflict(entity_type,entity_id,purpose,source_revision,template_version)
      where purpose in('DRAFT_PREVIEW','TIMESHEET')
        and status in ('PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning id,entity_id,operation_id
  ),
  all_doc_versions as materialized (
    select d.chunk_id,d.planned_invoice_id,d.operation_id,d.control_version,
      d.source_revision,
      coalesce(d.existing_version_id,v.id) document_version_id,
      coalesce(d.existing_status,'PLANNING') document_status
    from selected_doc_ops d
    left join doc_versions v
      on v.entity_id=d.planned_invoice_id and v.operation_id=d.operation_id
    where d.existing_version_id is not null or v.id is not null
  ),
  doc_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,status,priority,run_after_utc,payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select d.operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',d.document_version_id::text,
        d.source_revision,'invoice-professional-v2','1'),'sha256'),'hex'),
      0,'INVOICE',d.planned_invoice_id,d.document_version_id,
      'QUEUED',550,v_now,jsonb_build_object('purpose','DRAFT_PREVIEW'),d.control_version,v_now,v_now
    from all_doc_versions d
    where d.document_status<>'READY'
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing returning operation_id
  ),
  invoice_ptrs as (
    update public.invoices i set preview_document_version_id=d.document_version_id,
      active_document_operation_id=case when d.document_status='READY'
        then null else d.operation_id end,
      document_state=case when d.document_status='READY'
        then 'READY' else 'QUEUED' end,updated_at=v_now
    from all_doc_versions d where i.id=d.planned_invoice_id returning i.id
  ),
  credit_issue_ops as materialized (
    insert into public.invoice_operations(
      parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,
      input_json,config_json,progress_json,total_units,chunk_count,
      control_version,change_seq,created_at_utc,updated_at_utc)
    select q.parent_operation_id,'ISSUE_INVOICES','INVOICE_BATCH',null,
      o.actor_user_id,
      encode(digest('CREDIT_ISSUE|'||q.planned_invoice_id||'|'||
        q.document_revision||'|'||coalesce(q.command_token,''),'sha256'),'hex'),
      'QUEUED','VALIDATE',850,q.document_revision,'invoice-professional-v2',
      jsonb_build_object(
        'invoice_ids',jsonb_build_array(q.planned_invoice_id),
        'credit_note',true,'credit_reason',q.credit_reason,
        'command_token',q.command_token,'deliver',false),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,nextval('public.invoice_operation_change_seq'),v_now,v_now
    from queued_sources q
    join public.invoice_operations o on o.id=q.parent_operation_id
    where q.command_type='GENERATE_CREDIT_NOTE'
    on conflict(idempotency_key)
      where status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,excluded.priority),
      updated_at_utc=v_now
    returning *
  ),
  selected_credit_issue as materialized (
    select q.chunk_id,q.planned_invoice_id,q.document_revision,
      q.command_token,q.credit_reason,o.id operation_id,o.control_version
    from queued_sources q
    join credit_issue_ops o on o.parent_operation_id=q.parent_operation_id
      and o.operation_type='ISSUE_INVOICES'
    where q.command_type='GENERATE_CREDIT_NOTE'
  ),
  credit_issue_chunks as (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,status,
      priority,run_after_utc,payload_json,operation_control_version,
      created_at_utc,updated_at_utc)
    select s.operation_id,'ISSUE_INVOICE','VALIDATE',
      encode(digest(concat_ws('|','ISSUE_INVOICE',s.planned_invoice_id::text,
        s.document_revision,s.command_token),'sha256'),'hex'),
      0,'INVOICE',
      s.planned_invoice_id,'QUEUED',850,v_now,
      jsonb_build_object(
        'invoice_id',s.planned_invoice_id,
        'source_revision',s.document_revision,
        'allow_early',true,'deliver',false,
        'command_token',s.command_token,
        'credit_note',true,'credit_reason',s.credit_reason),
      s.control_version,v_now,v_now
    from selected_credit_issue s
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing
    returning operation_id
  ),
  credit_issue_ptrs as (
    update public.invoices i
    set active_issue_operation_id=s.operation_id,issue_state='VALIDATING',
      updated_at=v_now
    from selected_credit_issue s
    where i.id=s.planned_invoice_id
    returning i.id
  ),
  child_results as materialized (
    select d.chunk_id,d.operation_id document_operation_id,
      d.document_version_id,null::uuid issue_operation_id
    from all_doc_versions d
    union all
    select s.chunk_id,null::uuid,null::uuid,s.operation_id
    from selected_credit_issue s
  )
  update public.invoice_operation_chunks c
    set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,updated_at_utc=v_now,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      result_json=coalesce(c.result_json,'{}'::jsonb)||jsonb_build_object(
        'document_operation_id',d.document_operation_id,
        'document_version_id',d.document_version_id,
        'issue_operation_id',d.issue_operation_id)
    from child_results d where c.id=d.chunk_id
  ;
  select coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,
      'result',c.result_json,'error',c.error_json)),'[]'::jsonb)
    into v_part
  from jsonb_array_elements(p_claims) x
  join public.invoice_operation_chunks c
    on c.id=case when coalesce(x->>'chunk_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x->>'chunk_id')::uuid end
  where x->>'phase'='QUEUE_DOCUMENT';
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  return coalesce(v_result,'[]'::jsonb);
end;
$function$;

alter function private._invoice_generation_advance_core_v8(jsonb,timestamptz) OWNER TO CURRENT_USER;
revoke all on function private._invoice_generation_advance_core_v8(jsonb,timestamptz)
  from public, anon, authenticated, service_role, supabase_admin;
grant execute on function private._invoice_generation_advance_core_v8(jsonb,timestamptz)
  to CURRENT_USER, service_role;

commit;

-- Frozen Timesheet settings must be read only for the source rows already
-- selected by the invoice command. PostgreSQL may otherwise move a STABLE
-- reader below the source join and evaluate an unrelated, legitimately
-- unprocessed Daily Timesheet whose authority has not frozen yet.

\set ON_ERROR_STOP on

begin;

alter function private._timesheet_settings_authority_frozen_v1(uuid) volatile;
alter function private._timesheet_settings_authority_frozen_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private._timesheet_settings_authority_frozen_v1(uuid)
  from public,anon,authenticated,service_role;

comment on function private._timesheet_settings_authority_frozen_v1(uuid) is
  'Fail-closed frozen Timesheet settings reader. VOLATILE is an evaluation barrier so invoice queries cannot inspect unrelated planned or unprocessed rows.';

notify pgrst, 'reload schema';

commit;

-- Candidate expense email admission authority.
-- A separated/import-authoritative expense claim cannot start until the
-- effective dedicated Expense Invoice Email is configured. The finalisation
-- guard remains authoritative; this repeatable moves the same failure to
-- Candidate capability and placement admission so no worker can complete a
-- claim that is guaranteed to fail after manager approval.

\set ON_ERROR_STOP on

begin;

create or replace function private._candidate_record_capabilities_v1(
  p_timesheet_id uuid default null,
  p_contract_week_id uuid default null,
  p_proposed_claim jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare
  v_week public.contract_weeks%rowtype;
  v_contract public.contracts%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_policy jsonb;
  v_source_policy jsonb;
  v_hours numeric:=0;
  v_additional numeric:=0;
  v_expenses numeric:=0;
  v_mileage numeric:=0;
  v_travel numeric:=0;
  v_accommodation numeric:=0;
  v_other numeric:=0;
  v_import boolean:=false;
  v_source_self_allowed boolean:=false;
  v_protected boolean:=false;
  v_paid boolean:=false;
  v_effective_pay_status text:='UNPAID';
  v_payment_only_expense_edit boolean:=false;
  v_candidate_mutation_locked boolean:=false;
  v_separate boolean:=false;
  v_expense_admission_ready boolean:=false;
  v_has_timesheet boolean:=false;
  v_has_claim_evidence boolean:=false;
  v_has_embedded_submission_evidence boolean:=false;
  v_has_worked_schedule boolean:=false;
  v_has_active_submission_workflow boolean:=false;
  v_role text;
  v_route jsonb;
  v_route_family text;
  v_hours_route_allowed boolean:=false;
  v_expense_route_allowed boolean:=false;
  v_paper_route_allowed boolean:=false;
  v_no_work_route_allowed boolean:=false;
  v_reasons jsonb:='[]'::jsonb;
  v_result jsonb;
  v_daily_candidate_id uuid;
  v_daily_environment text;
  v_daily_identity_count integer;
begin
  if p_timesheet_id is null and p_contract_week_id is null then
    raise exception 'CANDIDATE_RECORD_IDENTITY_REQUIRED' using errcode='22023';
  end if;

  if p_timesheet_id is not null then
    select * into v_timesheet from public.timesheets where timesheet_id=p_timesheet_id;
    if not found then raise exception 'CANDIDATE_TIMESHEET_NOT_FOUND' using errcode='P0002'; end if;
    if v_timesheet.sheet_scope='DAILY' and v_timesheet.contract_id is null
       and p_contract_week_id is null then
      -- Candidate-created Daily receipts are owned by the immutable booking
      -- workflow, not by a fictitious weekly Contract. Preserve all other paths.
      select count(*)::integer,min(identity_row.candidate_id::text)::uuid,
        min(identity_row.environment)
      into v_daily_identity_count,v_daily_candidate_id,v_daily_environment
      from (
        select distinct w.candidate_id,w.environment
        from public.candidate_submission_workflows w
        join public.timesheets origin on origin.timesheet_id=w.anchor_timesheet_id
        where w.workflow_kind='DAILY' and origin.booking_id=v_timesheet.booking_id
          and origin.idempotency_key like 'candidate-daily-first:%'
          and w.creation_identity_json#>>'{request,daily_source,booking_id}'=v_timesheet.booking_id
      ) identity_row;
      if v_daily_identity_count=1 then
        return private._candidate_daily_read_projection_v1(
          v_daily_environment,v_daily_candidate_id,p_timesheet_id,now())->'capabilities';
      end if;
    end if;
  end if;

  if p_contract_week_id is not null then
    select * into v_week from public.contract_weeks where id=p_contract_week_id;
  else
    select cw.* into v_week from public.contract_weeks cw
    where cw.timesheet_id=p_timesheet_id order by cw.updated_at desc,cw.id desc limit 1;
  end if;
  if v_week.id is null then
    -- DAILY is timesheet-owned and intentionally has no contract_weeks row.
    if v_timesheet.timesheet_id is null
       or v_timesheet.sheet_scope<>'DAILY'::public.timesheet_scope_enum
       or v_timesheet.contract_id is null then
      raise exception 'CANDIDATE_CONTRACT_WEEK_NOT_FOUND' using errcode='P0002';
    end if;
    select * into v_contract from public.contracts where id=v_timesheet.contract_id;
  else
    select * into v_contract from public.contracts where id=v_week.contract_id;
  end if;
  if not found then raise exception 'CANDIDATE_CONTRACT_NOT_FOUND' using errcode='P0002'; end if;

  if v_timesheet.timesheet_id is null and v_week.timesheet_id is not null then
    select * into v_timesheet from public.timesheets where timesheet_id=v_week.timesheet_id;
  end if;

  if v_timesheet.timesheet_id is not null then
    select * into v_fin from public.timesheets_financials
    where timesheet_id=v_timesheet.timesheet_id and is_current=true
    order by computed_at_utc desc nulls last,updated_at desc,id desc limit 1;
  end if;

  v_policy:=private._candidate_policy_resolve_v1(
    v_contract.client_id,v_contract.id,coalesce(v_week.week_ending_date,v_timesheet.week_ending_date)
  );
  v_route:=private._candidate_route_family_v1(v_timesheet.timesheet_id,v_week.id);
  v_route_family:=v_route->>'route_family';
  v_hours_route_allowed:=coalesce((v_route->>'candidate_hours_submission_allowed')::boolean,false);
  v_expense_route_allowed:=coalesce((v_route->>'candidate_expenses_allowed')::boolean,false);
  v_paper_route_allowed:=coalesce((v_route->>'candidate_paper_submission_allowed')::boolean,false);
  v_no_work_route_allowed:=coalesce((v_route->>'candidate_no_work_allowed')::boolean,false);
  v_separate:=coalesce((v_policy->>'expenses_require_separate_timesheet')::boolean,false);
  v_expense_admission_ready:=not v_separate
    or coalesce((v_policy->>'expense_invoice_email_ready')::boolean,false);
  if not v_expense_admission_ready then
    v_reasons:=v_reasons||'"EXPENSE_INVOICE_EMAIL_REQUIRED"'::jsonb;
  end if;
  v_hours:=coalesce(v_fin.total_hours,0);
  v_additional:=private._candidate_json_numeric_sum(coalesce(v_fin.additional_units_json,'{}'::jsonb));
  if v_additional=0 then
    v_additional:=private._candidate_json_numeric_sum(coalesce(v_timesheet.additional_units_week,'{}'::jsonb))
      +private._candidate_json_numeric_sum(coalesce(v_timesheet.additional_units_per_day,'{}'::jsonb));
  end if;
  v_mileage:=abs(coalesce(v_fin.mileage_units,0))+abs(coalesce(v_fin.mileage_pay_ex_vat,0))+abs(coalesce(v_fin.mileage_charge_ex_vat,0));
  v_travel:=abs(coalesce(v_fin.travel_pay_ex_vat,0))+abs(coalesce(v_fin.travel_charge_ex_vat,0));
  v_accommodation:=abs(coalesce(v_fin.accommodation_pay_ex_vat,0))+abs(coalesce(v_fin.accommodation_charge_ex_vat,0));
  v_other:=abs(coalesce(v_fin.expenses_pay_ex_vat,0))+abs(coalesce(v_fin.expenses_charge_ex_vat,0))
    +abs(coalesce(v_fin.other_pay_ex_vat,0))+abs(coalesce(v_fin.other_charge_ex_vat,0));
  v_expenses:=v_mileage+v_travel+v_accommodation+v_other;

  if jsonb_typeof(p_proposed_claim)='object' then
    v_expenses:=greatest(v_expenses,
      abs(coalesce(nullif(p_proposed_claim->>'expenses_pay_ex_vat','')::numeric,0))
      +abs(coalesce(nullif(p_proposed_claim->>'expenses_charge_ex_vat','')::numeric,0))
      +abs(coalesce(nullif(p_proposed_claim->>'mileage_pay_ex_vat','')::numeric,0))
      +abs(coalesce(nullif(p_proposed_claim->>'mileage_charge_ex_vat','')::numeric,0))
    );
    v_mileage:=greatest(v_mileage,
      abs(coalesce(nullif(p_proposed_claim->>'mileage_units','')::numeric,0))
      +abs(coalesce(nullif(p_proposed_claim->>'mileage_pay_ex_vat','')::numeric,0))
      +abs(coalesce(nullif(p_proposed_claim->>'mileage_charge_ex_vat','')::numeric,0)));
    v_travel:=greatest(v_travel,
      abs(coalesce(nullif(p_proposed_claim->>'travel_pay_ex_vat','')::numeric,0))
      +abs(coalesce(nullif(p_proposed_claim->>'travel_charge_ex_vat','')::numeric,0)));
    v_accommodation:=greatest(v_accommodation,
      abs(coalesce(nullif(p_proposed_claim->>'accommodation_pay_ex_vat','')::numeric,0))
      +abs(coalesce(nullif(p_proposed_claim->>'accommodation_charge_ex_vat','')::numeric,0)));
    v_other:=greatest(v_other,
      abs(coalesce(nullif(p_proposed_claim->>'expenses_pay_ex_vat','')::numeric,0))
      +abs(coalesce(nullif(p_proposed_claim->>'expenses_charge_ex_vat','')::numeric,0))
      +abs(coalesce(nullif(p_proposed_claim->>'other_pay_ex_vat','')::numeric,0))
      +abs(coalesce(nullif(p_proposed_claim->>'other_charge_ex_vat','')::numeric,0)));
    v_expenses:=greatest(v_expenses,v_mileage+v_travel+v_accommodation+v_other);
  end if;

  v_import:=coalesce((v_route->>'import_authoritative')::boolean,false);
  if v_import and v_week.id is not null and v_contract.id is not null
     and v_week.additional_seq=0 and not v_week.is_adjustment
     and v_week.week_ending_date-6 <= (pg_catalog.transaction_timestamp() at time zone 'Europe/London')::date then
    begin
      v_source_policy:=private._weekly_source_effective_policy_v1(
        v_contract.client_id,v_contract.id,v_week.week_ending_date
      );
    exception
      when sqlstate '55000' then
        if sqlerrm not in (
          'WEEKLY_SOURCE_GROUP_CARDINALITY_INVALID',
          'WEEKLY_SOURCE_CLIENT_POLICY_CARDINALITY_INVALID',
          'WEEKLY_SOURCE_CONTRACT_POLICY_CARDINALITY_INVALID',
          'WEEKLY_SOURCE_COMPLETED_PACK_RECIPIENT_REQUIRED'
        ) then raise; end if;
        -- An invalid policy disables this optional read capability. The
        -- candidate's other records must still load; admission stays strict.
        v_source_policy:=null;
      when sqlstate '22023' then
        if sqlerrm <> 'WEEKLY_SOURCE_POLICY_SCOPE_NOT_FOUND' then raise; end if;
        v_source_policy:=null;
    end;
    v_source_self_allowed:=coalesce(
      (v_source_policy->>'authority_mode')='SOURCE_AUTHORITY'
      and (v_source_policy->>'document_mode')='CHECK_ONLY',false
    );
  end if;
  if v_timesheet.timesheet_id is not null then
    select coalesce(
      case when coalesce(summary_pay_cache.summary_state_applies,false)
        then summary_pay_cache.summary_pay_status_code end,
      pay_state.summary_pay_status_code,
      case when pay_state.last_settled_at_utc is not null
          or v_fin.paid_at_utc is not null
        then 'PAID' else 'UNPAID' end
    )::text
    into v_effective_pay_status
    from (select 1) seed(seed_id)
    left join public.timesheet_summary_pay_state_cache summary_pay_cache
      on summary_pay_cache.timesheet_id=v_timesheet.timesheet_id
    left join public.timesheet_pay_state pay_state
      on pay_state.timesheet_id=v_timesheet.timesheet_id;
  end if;
  v_paid:=upper(coalesce(v_effective_pay_status,'UNPAID')) in ('PAID','PARTIALLY_PAID')
    or coalesce(
      (v_fin.policy_snapshot_json#>>'{candidate_expense_payment_edit_shell_v1,active}')::boolean,
      false
    );
  v_protected:=v_timesheet.archived_at_utc is not null
    or (v_timesheet.timesheet_id is not null and (not v_timesheet.is_current))
    or v_fin.locked_by_invoice_id is not null
    or coalesce(v_week.status in (
      'INVOICED'::public.contract_week_status_enum,'CANCELLED'::public.contract_week_status_enum
    ),false);
  v_candidate_mutation_locked:=v_fin.authorised_at_utc is not null
    or coalesce(v_fin.processing_status in (
      'PENDING_AUTH'::public.ts_fin_processing_status_enum,
      'READY_FOR_HR'::public.ts_fin_processing_status_enum,
      'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
    ),false);
  v_payment_only_expense_edit:=v_paid and not v_protected
    and v_fin.authorised_at_utc is null and v_fin.locked_by_invoice_id is null;
  if v_candidate_mutation_locked then
    v_reasons:=v_reasons||'"CANDIDATE_MUTATION_LOCKED_AUTHORISED"'::jsonb;
  end if;

  select exists(
    select 1 from public.timesheet_evidence e
    where e.timesheet_id=v_timesheet.timesheet_id
      and upper(btrim(e.kind))='TIMESHEET'
      and e.processing_state<>'SUPERSEDED'
  ) into v_has_timesheet;

  select exists(
    select 1 from public.timesheet_evidence e
    where e.timesheet_id=v_timesheet.timesheet_id
      and e.processing_state<>'SUPERSEDED'
  ) into v_has_claim_evidence;

  v_has_embedded_submission_evidence:=
    nullif(btrim(coalesce(v_timesheet.r2_nurse_key,'')),'') is not null
    or nullif(btrim(coalesce(v_timesheet.r2_auth_key,'')),'') is not null
    or nullif(btrim(coalesce(v_timesheet.qr_r2_key,'')),'') is not null
    or v_timesheet.qr_signed_hash is not null
    or v_timesheet.qr_signed_at_utc is not null
    or v_timesheet.authorised_at_server is not null;
  v_has_worked_schedule:=
    coalesce(v_timesheet.worked_minutes,0)<>0
    or v_timesheet.worked_start_iso is not null
    or v_timesheet.worked_end_iso is not null
    or coalesce(v_timesheet.actual_schedule_json,'{}'::jsonb) not in ('{}'::jsonb,'[]'::jsonb,'null'::jsonb);

  select exists(
    select 1
    from public.candidate_submission_workflows workflow
    where workflow.candidate_id=v_contract.candidate_id
      and workflow.contract_id=v_contract.id
      and workflow.week_ending_date=coalesce(v_week.week_ending_date,v_timesheet.week_ending_date)
      and workflow.state not in ('CANCELLED','EXPIRED','SUPERSEDED')
      and (
        workflow.contract_week_id is not distinct from v_week.id
        or workflow.target_timesheet_id=v_timesheet.timesheet_id
        or workflow.anchor_timesheet_id=v_timesheet.timesheet_id
      )
  ) into v_has_active_submission_workflow;

  if v_protected then v_role:='PROTECTED'; v_reasons:=v_reasons||'"LIFECYCLE_PROTECTED"'::jsonb;
  -- An additional expense carrier remains expense-only even when its Client
  -- inherits an import-authoritative route. Only an imported hours record that
  -- has also acquired expenses is a mixed-source conflict.
  elsif v_timesheet.line_type in ('EXPENSES','MILEAGE')
     and v_expenses<>0 and v_hours=0 and v_additional=0 then v_role:='EXPENSE_ONLY';
  elsif v_import and v_expenses<>0 then v_role:='CONFLICT'; v_reasons:=v_reasons||'"IMPORT_SOURCE_HAS_EXPENSES"'::jsonb;
  elsif v_import then v_role:='IMPORT_HOURS'; v_reasons:=v_reasons||'"IMPORT_AUTHORITATIVE_HOURS"'::jsonb;
  elsif v_separate and (v_hours<>0 or v_additional<>0) and v_expenses<>0 then v_role:='CONFLICT'; v_reasons:=v_reasons||'"SEPARATION_MIXED_ECONOMICS"'::jsonb;
  elsif v_expenses<>0 and v_hours=0 and v_additional=0 then v_role:='EXPENSE_ONLY';
  elsif (v_hours<>0 or v_additional<>0) and v_expenses=0 then v_role:='HOURS_ONLY';
  elsif not v_separate and v_timesheet.timesheet_id is not null then v_role:='COMBINED_ALLOWED';
  elsif v_week.additional_seq>0 and v_timesheet.timesheet_id is null then v_role:='FLEXIBLE';
  elsif v_week.additional_seq>0 and v_hours=0 and v_additional=0 and v_expenses=0 then v_role:='FLEXIBLE';
  else v_role:='HOURS_ONLY';
  end if;

  v_result:=jsonb_build_object(
    'record_role',v_role,
    'reason_codes',v_reasons,
    'timesheet_id',v_timesheet.timesheet_id,
    'contract_week_id',v_week.id,
    'contract_id',v_contract.id,
    'candidate_id',v_contract.candidate_id,
    'client_id',v_contract.client_id,
    'week_ending_date',v_week.week_ending_date,
    'additional_seq',v_week.additional_seq,
    'hours_value',v_hours,
    'additional_units_value',v_additional,
    'expense_value',v_expenses,
    'effective_separation',v_separate,
    'import_authoritative',v_import,
    'candidate_source_self_entry_allowed',v_source_self_allowed
      and not v_protected and not v_candidate_mutation_locked and not v_paid
      and v_fin.timesheet_id is null
      and coalesce(v_week.status not in (
        'AUTHORISED'::public.contract_week_status_enum,
        'INVOICED'::public.contract_week_status_enum,
        'CANCELLED'::public.contract_week_status_enum
      ),false),
    'route_family',v_route_family,
    'effective_submission_mode',v_route->'effective_submission_mode',
    'protected',v_protected,
    'payment_only_expense_edit',v_payment_only_expense_edit,
    'candidate_mutation_locked',v_candidate_mutation_locked,
    'has_active_timesheet_evidence',v_has_timesheet,
    'has_active_claim_evidence',v_has_claim_evidence,
    'has_embedded_submission_evidence',v_has_embedded_submission_evidence,
    'has_worked_schedule',v_has_worked_schedule,
    'has_active_submission_workflow',v_has_active_submission_workflow,
    'candidate_hours_submission_allowed',v_hours_route_allowed and not v_protected
      and not v_candidate_mutation_locked and not v_paid,
    -- An empty import-authoritative hours root cannot anchor an expense claim.
    -- Additional expense carriers remain editable, and an ordinary non-source
    -- Timesheet retains its existing capability unchanged.
    'candidate_expenses_allowed',v_expense_route_allowed and v_expense_admission_ready
      and (not v_import or coalesce(v_week.additional_seq,0)>0
        or v_hours>0 or v_additional>0 or v_has_worked_schedule) and (
      not v_protected or v_hours<>0 or v_additional<>0 or v_import
    ),
    'candidate_paper_submission_allowed',v_paper_route_allowed and not v_protected and not v_candidate_mutation_locked,
    'candidate_no_work_allowed',v_no_work_route_allowed and not v_protected
      and not v_candidate_mutation_locked and not v_paid
      and coalesce(v_week.additional_seq,0)=0 and not coalesce(v_week.is_adjustment,false)
      and v_hours=0 and v_additional=0 and v_expenses=0
      and not v_has_claim_evidence and not v_has_embedded_submission_evidence
      and not v_has_worked_schedule and not v_has_active_submission_workflow,
    'can_edit_hours',v_hours_route_allowed and v_role in ('HOURS_ONLY','COMBINED_ALLOWED','FLEXIBLE')
      and not v_protected and not v_candidate_mutation_locked and not v_paid and not v_import,
    -- Imported hours remain immutable, but the Candidate may start the
    -- mandatory separate expense route against that worked-week anchor.
    -- Authorised hours remain immutable, but can still anchor the separately
    -- allocated Candidate expense carrier. The placement resolver forbids
    -- SAME_RECORD when candidate_mutation_locked is true.
    'can_edit_expenses',v_expense_route_allowed and v_expense_admission_ready
      and (not v_import or coalesce(v_week.additional_seq,0)>0
        or v_hours>0 or v_additional>0 or v_has_worked_schedule) and (
      (
        not v_protected and (
          v_role in ('EXPENSE_ONLY','COMBINED_ALLOWED','FLEXIBLE','IMPORT_HOURS')
          or (v_role='HOURS_ONLY' and (v_separate or v_candidate_mutation_locked or v_paid))
        )
      )
      or (
        v_protected and (v_hours<>0 or v_additional<>0 or v_import)
      )
    ),
    'can_attach_timesheet',v_hours_route_allowed and v_role in ('HOURS_ONLY','COMBINED_ALLOWED')
      and not v_protected and not v_candidate_mutation_locked and not v_paid and not v_has_timesheet,
    'can_attach_expense_evidence',v_expense_route_allowed and v_expense_admission_ready and v_role in ('EXPENSE_ONLY','COMBINED_ALLOWED','FLEXIBLE') and not v_protected and (not v_candidate_mutation_locked or v_payment_only_expense_edit),
    'can_attach_mileage_evidence',v_expense_route_allowed and v_expense_admission_ready and v_role in ('EXPENSE_ONLY','COMBINED_ALLOWED','FLEXIBLE') and not v_protected and (not v_candidate_mutation_locked or v_payment_only_expense_edit) and v_mileage<>0,
    'can_attach_travel_evidence',v_expense_route_allowed and v_expense_admission_ready and v_role in ('EXPENSE_ONLY','COMBINED_ALLOWED','FLEXIBLE') and not v_protected and (not v_candidate_mutation_locked or v_payment_only_expense_edit) and v_travel<>0,
    'can_attach_accommodation_evidence',v_expense_route_allowed and v_expense_admission_ready and v_role in ('EXPENSE_ONLY','COMBINED_ALLOWED','FLEXIBLE') and not v_protected and (not v_candidate_mutation_locked or v_payment_only_expense_edit) and v_accommodation<>0,
    'can_attach_other_evidence',v_expense_route_allowed and v_expense_admission_ready and v_role in ('EXPENSE_ONLY','COMBINED_ALLOWED','FLEXIBLE') and not v_protected and (not v_candidate_mutation_locked or v_payment_only_expense_edit) and v_other<>0,
    'can_process',v_role not in ('PROTECTED','CONFLICT') and not v_protected
      and not v_candidate_mutation_locked and not v_paid,
    'can_reject_candidate_submission',v_timesheet.timesheet_id is not null
      and not v_protected and not v_paid and v_fin.authorised_at_utc is null,
    'reject_scope',case when v_role='EXPENSE_ONLY' then 'COMPLETE_EXPENSE_CLAIM' else 'COMPLETE_TIMESHEET_RECORD' end,
    'requires_carrier',v_role='IMPORT_HOURS'
      or (v_role='HOURS_ONLY' and (v_separate or v_candidate_mutation_locked))
      or (v_paid and (v_hours<>0 or v_additional<>0))
      or (v_protected and (v_hours<>0 or v_additional<>0 or v_import)),
    'expense_invoice_email_ready',coalesce((v_policy->>'expense_invoice_email_ready')::boolean,false),
    'policy',v_policy
  );

  return v_result||jsonb_build_object(
    'capability_hash',encode(extensions.digest(convert_to(v_result::text,'UTF8'),'sha256'),'hex')
  );
exception
  when invalid_text_representation then
    raise exception 'CANDIDATE_PROPOSED_CLAIM_INVALID' using errcode='22023';
end;
$function$;

alter function private._candidate_record_capabilities_v1(uuid,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private._candidate_record_capabilities_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;
grant execute on function private._candidate_record_capabilities_v1(uuid,uuid,jsonb) to CURRENT_USER;

create or replace function public.expense_placement_resolve_v1(
  p_candidate_id uuid,
  p_environment text,
  p_anchor_timesheet_id uuid,
  p_contract_week_id uuid default null,
  p_proposed_claim jsonb default '{}'::jsonb,
  p_now_utc timestamptz default now()
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_environment text;
  v_anchor_week public.contract_weeks%rowtype;
  v_contract public.contracts%rowtype;
  v_anchor_capabilities jsonb;
  v_positive_work boolean:=false;
  v_candidate_count integer:=0;
  v_candidate_week_id uuid;
  v_candidate_timesheet_id uuid;
  v_candidate_role text;
  v_result text;
  v_reason text;
begin
  v_environment:=private._candidate_assert_environment(p_environment);
  perform private._candidate_require_feature_v1(v_environment,'candidate_expense_atomic_placement');
  if p_candidate_id is null or (p_anchor_timesheet_id is null and p_contract_week_id is null) then
    raise exception 'EXPENSE_PLACEMENT_IDENTITY_REQUIRED' using errcode='22023';
  end if;
  if p_contract_week_id is not null then
    select * into v_anchor_week from public.contract_weeks where id=p_contract_week_id;
  else
    select * into v_anchor_week from public.contract_weeks
    where timesheet_id=p_anchor_timesheet_id order by updated_at desc,id desc limit 1;
  end if;
  if not found then raise exception 'EXPENSE_PLACEMENT_ANCHOR_NOT_FOUND' using errcode='P0002'; end if;
  select * into v_contract from public.contracts where id=v_anchor_week.contract_id and candidate_id=p_candidate_id;
  if not found then raise exception 'EXPENSE_PLACEMENT_CANDIDATE_MISMATCH' using errcode='28000'; end if;
  v_anchor_capabilities:=private._candidate_record_capabilities_v1(
    coalesce(p_anchor_timesheet_id,v_anchor_week.timesheet_id),v_anchor_week.id,coalesce(p_proposed_claim,'{}'::jsonb)
  );
  if coalesce(v_anchor_capabilities->'reason_codes','[]'::jsonb) ? 'EXPENSE_INVOICE_EMAIL_REQUIRED' then
    return jsonb_build_object(
      'ok',true,'placement','BLOCKED','reason_code','EXPENSE_INVOICE_EMAIL_REQUIRED',
      'anchor_timesheet_id',p_anchor_timesheet_id,'anchor_contract_week_id',v_anchor_week.id,
      'capabilities',v_anchor_capabilities
    );
  end if;
  if not coalesce((v_anchor_capabilities->>'candidate_expenses_allowed')::boolean,false) then
    return jsonb_build_object(
      'ok',true,'placement','BLOCKED','reason_code','CANDIDATE_RECORD_VIEW_ONLY',
      'anchor_timesheet_id',p_anchor_timesheet_id,'anchor_contract_week_id',v_anchor_week.id,
      'capabilities',v_anchor_capabilities
    );
  end if;

  select exists(
    select 1
    from public.contract_weeks cw
    join public.timesheets t on t.timesheet_id=cw.timesheet_id and t.is_current=true and t.archived_at_utc is null
    join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current=true
    where cw.contract_id=v_contract.id and cw.week_ending_date=v_anchor_week.week_ending_date
      and (
        coalesce(tf.total_hours,0)>0
        or private._candidate_json_numeric_sum(coalesce(tf.additional_units_json,'{}'::jsonb))>0
        or private._candidate_json_numeric_sum(coalesce(t.additional_units_week,'{}'::jsonb))
          +private._candidate_json_numeric_sum(coalesce(t.additional_units_per_day,'{}'::jsonb))>0
      )
  ) into v_positive_work;
  if not v_positive_work then
    -- Source-authority hours are deliberately not written into TSFIN before
    -- finalisation. A server-validated, immutable Candidate submission is
    -- nevertheless sufficient evidence that this is a worked week and may
    -- open the existing separate expense carrier. The expense never lands on
    -- the source-owned Timesheet and still follows manager approval.
    select exists(
      select 1
      from public.candidate_submission_workflows w
      cross join lateral (
        select
          coalesce(
            w.input_snapshot_json#>'{hours_submission,timesheet_patch_json,actual_schedule_json}',
            w.input_snapshot_json#>'{timesheet_patch_json,actual_schedule_json}',
            w.input_snapshot_json->'actual_schedule_json',
            '[]'::jsonb
          ) as actual_schedule_json,
          coalesce(
            w.input_snapshot_json#>'{hours_submission,timesheet_patch_json,additional_units_week}',
            w.input_snapshot_json#>'{timesheet_patch_json,additional_units_week}',
            w.input_snapshot_json->'additional_units_week',
            '{}'::jsonb
          ) as additional_units_week,
          coalesce(
            w.input_snapshot_json#>'{hours_submission,timesheet_patch_json,additional_units_per_day}',
            w.input_snapshot_json#>'{timesheet_patch_json,additional_units_per_day}',
            w.input_snapshot_json->'additional_units_per_day',
            '{}'::jsonb
          ) as additional_units_per_day
      ) submitted
      where w.candidate_id=p_candidate_id
        and w.contract_id=v_contract.id
        and w.week_ending_date=v_anchor_week.week_ending_date
        and w.workflow_kind in ('CONTRACT_HOURS','CONTRACT_COMBINED')
        and w.state in (
          'WORKER_SUBMITTED','WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',
          'READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL',
          'MANAGER_APPROVED','MANAGER_APPROVED_PENDING_FINAL_DOCUMENT',
          'READY_TO_FINALISE','RECEIVED','FINALISED'
        )
        and (
          (pg_catalog.jsonb_typeof(submitted.actual_schedule_json)='array'
            and pg_catalog.jsonb_array_length(submitted.actual_schedule_json)>0)
          or private._candidate_json_numeric_sum(submitted.additional_units_week)>0
          or private._candidate_json_numeric_sum(submitted.additional_units_per_day)>0
        )
    ) into v_positive_work;
  end if;
  if not v_positive_work then
    return jsonb_build_object(
      'ok',true,'placement','BLOCKED','reason_code','NO_POSITIVE_WORKED_TIME',
      'anchor_timesheet_id',p_anchor_timesheet_id,'anchor_contract_week_id',v_anchor_week.id,
      'capabilities',v_anchor_capabilities
    );
  end if;

  if coalesce((v_anchor_capabilities->>'effective_separation')::boolean,false)=false
     and v_anchor_capabilities->>'record_role' in ('COMBINED_ALLOWED','EXPENSE_ONLY','FLEXIBLE')
     and coalesce((v_anchor_capabilities->>'protected')::boolean,false)=false
     and coalesce((v_anchor_capabilities->>'candidate_mutation_locked')::boolean,false)=false
     and coalesce((v_anchor_capabilities->>'can_edit_expenses')::boolean,false) then
    return jsonb_build_object(
      'ok',true,'placement','SAME_RECORD','reason_code','COMBINED_ALLOWED',
      'anchor_timesheet_id',coalesce(p_anchor_timesheet_id,v_anchor_week.timesheet_id),
      'target_timesheet_id',coalesce(p_anchor_timesheet_id,v_anchor_week.timesheet_id),
      'target_contract_week_id',v_anchor_week.id,'capabilities',v_anchor_capabilities
    );
  end if;

  with candidate_carriers as (
    select cw.id as contract_week_id,cw.timesheet_id,
      private._candidate_record_capabilities_v1(cw.timesheet_id,cw.id,coalesce(p_proposed_claim,'{}'::jsonb)) as capabilities
    from public.contract_weeks cw
    left join public.timesheets t on t.timesheet_id=cw.timesheet_id
    where cw.contract_id=v_contract.id and cw.week_ending_date=v_anchor_week.week_ending_date
      and cw.additional_seq>0
      and (t.timesheet_id is null or (t.is_current=true and t.archived_at_utc is null))
      and not exists(
        select 1 from public.candidate_submission_workflows w
        where w.contract_week_id=cw.id and w.candidate_id<>p_candidate_id
          and w.state in ('CREATED','WORKER_SUBMITTED','AWAITING_MANAGER_APPROVAL','MANAGER_APPROVED','AWAITING_PAPER_RETURN','RECEIVED')
      )
  ), safe as (
    select * from candidate_carriers
    where capabilities->>'record_role' in ('EXPENSE_ONLY','FLEXIBLE')
      and coalesce((capabilities->>'protected')::boolean,false)=false
      and coalesce((capabilities->>'candidate_mutation_locked')::boolean,false)=false
      and coalesce((capabilities->>'import_authoritative')::boolean,false)=false
  )
  select count(*)::integer into v_candidate_count from safe;

  if v_candidate_count=1 then
    with candidate_carriers as (
      select cw.id as contract_week_id,cw.timesheet_id,
        private._candidate_record_capabilities_v1(cw.timesheet_id,cw.id,coalesce(p_proposed_claim,'{}'::jsonb)) as capabilities
      from public.contract_weeks cw
      left join public.timesheets t on t.timesheet_id=cw.timesheet_id
      where cw.contract_id=v_contract.id and cw.week_ending_date=v_anchor_week.week_ending_date
        and cw.additional_seq>0
        and (t.timesheet_id is null or (t.is_current=true and t.archived_at_utc is null))
        and not exists(
          select 1 from public.candidate_submission_workflows w
          where w.contract_week_id=cw.id and w.candidate_id<>p_candidate_id
            and w.state in ('CREATED','WORKER_SUBMITTED','AWAITING_MANAGER_APPROVAL','MANAGER_APPROVED','AWAITING_PAPER_RETURN','RECEIVED')
        )
    )
    select contract_week_id,timesheet_id,capabilities->>'record_role'
    into v_candidate_week_id,v_candidate_timesheet_id,v_candidate_role
    from candidate_carriers
    where capabilities->>'record_role' in ('EXPENSE_ONLY','FLEXIBLE')
      and coalesce((capabilities->>'protected')::boolean,false)=false
      and coalesce((capabilities->>'candidate_mutation_locked')::boolean,false)=false
      and coalesce((capabilities->>'import_authoritative')::boolean,false)=false
    order by contract_week_id
    limit 1;
  end if;

  if v_candidate_count>1 then v_result:='BLOCKED';v_reason:='EXPENSE_CARRIER_AMBIGUOUS';
  elsif v_candidate_count=1 then v_result:='REUSE_CARRIER';v_reason:='SAFE_EXISTING_CARRIER';
  else v_result:='CREATE_CARRIER';v_reason:='NO_SAFE_CARRIER'; end if;

  return jsonb_build_object(
    'ok',true,'placement',v_result,'reason_code',v_reason,
    'anchor_timesheet_id',coalesce(p_anchor_timesheet_id,v_anchor_week.timesheet_id),
    'anchor_contract_week_id',v_anchor_week.id,
    'target_timesheet_id',v_candidate_timesheet_id,
    'target_contract_week_id',v_candidate_week_id,
    'target_record_role',v_candidate_role,
    'capabilities',v_anchor_capabilities
  );
end;
$function$;

revoke all on function public.expense_placement_resolve_v1(uuid,text,uuid,uuid,jsonb,timestamptz) from public,anon,authenticated;
grant execute on function public.expense_placement_resolve_v1(uuid,text,uuid,uuid,jsonb,timestamptz) to service_role;

notify pgrst, 'reload schema';

commit;

-- Reconcile the historical QR refusal helper with the current Worker-only
-- database boundary. The Office Worker is its only HTTP caller and invokes it
-- with the service role after enforcing the admin and stale-record guards.
-- This changes no Timesheet lifecycle rule or function body.

\set ON_ERROR_STOP on

begin;

alter function public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid)
  OWNER TO CURRENT_USER;
alter function public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid)
  set search_path = pg_catalog, public, private, extensions, pg_temp;

revoke all on function public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid)
  from public,anon,authenticated,service_role;

do $acl$
begin
  if exists (
    select 1 from pg_catalog.pg_roles where rolname='authenticator'
  ) then
    execute 'revoke all on function public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid) from authenticator';
  end if;
  if exists (
    select 1 from pg_catalog.pg_roles where rolname='supabase_admin'
  ) then
    execute 'revoke all on function public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid) from supabase_admin';
  end if;
end;
$acl$;

grant execute on function public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid)
  to CURRENT_USER,service_role;

-- A later replay of the historical function definition can restore its old
-- browser grant while this repeatable remains unchanged in the release
-- ledger.  Reassert and prove the effective role privileges whenever this
-- closure is selected for release.
do $verify_acl$
begin
  if has_function_privilege(
       'anon',
       'public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid)',
       'EXECUTE'
     )
     or has_function_privilege(
       'authenticated',
       'public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid)',
       'EXECUTE'
     )
     or not has_function_privilege(
       'service_role',
       'public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid)',
       'EXECUTE'
     ) then
    raise exception 'TIMESHEET_QR_REFUSE_SERVICE_ACL_INVALID';
  end if;
end;
$verify_acl$;

commit;

-- Repeatable CloudTMS function/view authority: client_planned_override_refresh_v1
-- Use CREATE OR REPLACE and preserve owner, security, search_path, and ACL contracts.

\set ON_ERROR_STOP on

begin;

-- Client changes must revisit every remaining planned Contract week.  The
-- central resolver, rather than this row-selection helper, owns the
-- setting-by-setting Client/Contract precedence.  Excluding an entire Contract
-- merely because its broad override is enabled would leave its still
-- Client-owned values stale.
create or replace function private._contract_settings_refresh_planned_for_client_v1(
  p_client_id uuid
)
returns integer
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare v_row record; v_count integer:=0;
begin
  for v_row in
    select cw.id
    from public.contract_weeks cw
    join public.contracts c on c.id=cw.contract_id
    where c.client_id=p_client_id
      and cw.timesheet_id is null
    order by c.id,cw.week_ending_date,cw.id
  loop
    if private._contract_settings_apply_week_snapshot_v1(v_row.id) then
      v_count:=v_count+1;
    end if;
  end loop;
  return v_count;
end
$function$;

alter function private._contract_settings_refresh_planned_for_client_v1(uuid)
  OWNER TO CURRENT_USER;
revoke all on function private._contract_settings_refresh_planned_for_client_v1(uuid)
  from public,anon,authenticated,service_role;

commit;


drop function if exists private._invoice_correction_validate_batch(uuid[],date);
drop function if exists private._invoice_correction_validate_batch(uuid[],date,jsonb);
drop function if exists private._invoice_correction_validate_batch(jsonb,date);
create or replace function private._invoice_correction_validate_batch(
  p_scopes jsonb,
  p_evaluation_date date
) returns table(
  request_key text,
  scope_key text,
  invoice_id uuid,
  timesheet_id uuid,
  correction_classification text,
  correction_id text,
  correction_ids text[],
  required_member_ids uuid[],
  missing_member_ids uuid[],
  conflicting_invoice_ids uuid[],
  balanced boolean,
  valid boolean,
  blocker_code text,
  blocker_codes text[],
  detail_json jsonb
)
language sql
stable
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
with recursive scope_input as materialized (
  select e.ordinality::integer input_ordinal,e.value scope_json
  from jsonb_array_elements(case when jsonb_typeof(p_scopes)='array'
    then p_scopes else '[]'::jsonb end) with ordinality e(value,ordinality)
),
scopes as materialized (
  select
    coalesce(nullif(btrim(scope_json->>'request_key'),''),
      'correction:'||input_ordinal::text) request_key,
    coalesce(nullif(btrim(scope_json->>'scope_key'),''),
      nullif(btrim(scope_json->>'request_key'),''),
      'scope:'||input_ordinal::text) external_scope_key,
    coalesce(nullif(btrim(scope_json->>'request_key'),''),
      'correction:'||input_ordinal::text)||E'\\x1f'||
    coalesce(nullif(btrim(scope_json->>'scope_key'),''),
      nullif(btrim(scope_json->>'request_key'),''),
      'scope:'||input_ordinal::text) scope_key,
    case when coalesce(scope_json->>'invoice_id',
      scope_json->>'target_invoice_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then coalesce(scope_json->>'invoice_id',
        scope_json->>'target_invoice_id')::uuid end invoice_id,
    upper(coalesce(nullif(btrim(scope_json->>'validation_purpose'),''),
      'VALIDATE')) validation_purpose,
    case when coalesce(scope_json->>'expected_client_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(scope_json->>'expected_client_id')::uuid end expected_client_id,
    case when coalesce(scope_json->>'expected_contract_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(scope_json->>'expected_contract_id')::uuid end expected_contract_id,
    case when coalesce(scope_json->>'natural_source_week','')
      ~'^\\d{4}-\\d{2}-\\d{2}$'
      then(scope_json->>'natural_source_week')::date end natural_source_week,
    case when coalesce(scope_json->>'target_invoice_week','')
      ~'^\\d{4}-\\d{2}-\\d{2}$'
      then(scope_json->>'target_invoice_week')::date end target_invoice_week,
    nullif(upper(btrim(scope_json->>'expected_invoice_stream')),'')
      expected_invoice_stream,
    case when coalesce(scope_json->>'expected_vat_rate_pct','')
      ~'^[+-]?[0-9]+([.][0-9]+)?$'
      then(scope_json->>'expected_vat_rate_pct')::numeric end
      expected_vat_rate_pct,
    case when jsonb_typeof(scope_json->'planned_members')='array'
      then scope_json->'planned_members' else '[]'::jsonb end planned_members,
    scope_json
  from scope_input
),
planned_lines as materialized (
  select distinct s.scope_key,s.invoice_id,
    case when coalesce(x.value->>'timesheet_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x.value->>'timesheet_id')::uuid end timesheet_id,
    case when coalesce(x.value->>'vat_rate_pct','')
      ~'^[+-]?[0-9]+([.][0-9]+)?$'
      then(x.value->>'vat_rate_pct')::numeric
      else s.expected_vat_rate_pct end vat_rate_pct,
    nullif(btrim(coalesce(x.value->>'segment_id',
      x.value->>'segment_key')),'') segment_id
  from scopes s
  cross join lateral jsonb_array_elements(s.planned_members) x(value)
  where coalesce(x.value->>'timesheet_id','')~*
    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
),
targets as materialized (
  select distinct s.invoice_id,s.scope_key,l.timesheet_id
  from scopes s
  join public.invoice_lines l on l.invoice_id=s.invoice_id
  where s.invoice_id is not null and l.timesheet_id is not null
  union
  select p.invoice_id,p.scope_key,p.timesheet_id
  from planned_lines p
  where p.timesheet_id is not null
),
seed_units as materialized (
  select distinct t.correction_id,
    coalesce(t.candidate_hint_text->'correction_financials_policy_envelope',
      f.policy_snapshot_json->'correction_financials_policy_envelope',
      f.rate_source_refs_json->'correction_financials_policy_envelope')
      #>>'{operation,operation_id}' correction_operation_id,
    coalesce(t.candidate_hint_text->'correction_financials_policy_envelope',
      f.policy_snapshot_json->'correction_financials_policy_envelope',
      f.rate_source_refs_json->'correction_financials_policy_envelope')
      ->>'correction_chain_id' correction_chain_id
  from targets q
  join public.timesheets t on t.timesheet_id=q.timesheet_id
  left join public.timesheets_financials f
    on f.timesheet_id=t.timesheet_id and f.is_current
),all_current as materialized (
  select t.timesheet_id,t.correction_id,
    upper(btrim(coalesce(t.correction_kind,''))) correction_kind,
    upper(btrim(coalesce(t.adjustment_origin,''))) adjustment_origin,
    t.parent_timesheet_id,t.is_current,t.status::text timesheet_status,
    t.contract_id,t.week_ending_date,
    coalesce(f.client_id,c.client_id) client_id,
    f.id financial_id,f.processing_status::text processing_status,
    f.basis::text basis,f.total_charge_ex_vat,f.is_stale,f.stale_reason,
    f.total_hours,f.hours_day,f.hours_night,f.hours_sat,f.hours_sun,f.hours_bh,
    f.additional_pay_ex_vat,f.additional_charge_ex_vat,
    f.expenses_pay_ex_vat,f.expenses_charge_ex_vat,
    f.mileage_pay_ex_vat,f.mileage_charge_ex_vat,
    f.travel_pay_ex_vat,f.travel_charge_ex_vat,
    f.accommodation_pay_ex_vat,f.accommodation_charge_ex_vat,
    f.other_pay_ex_vat,f.other_charge_ex_vat,
    f.locked_by_invoice_id,f.invoice_breakdown_json,
    f.policy_snapshot_json,f.rate_source_refs_json,
    coalesce(
      t.candidate_hint_text->'correction_financials_policy_envelope',
      f.policy_snapshot_json->'correction_financials_policy_envelope',
      f.rate_source_refs_json->'correction_financials_policy_envelope') envelope
  from public.timesheets t
  left join public.timesheets_financials f
    on f.timesheet_id=t.timesheet_id and f.is_current
  left join public.contracts c on c.id=t.contract_id
  where exists(select 1 from targets q where q.timesheet_id=t.timesheet_id)
     or(t.correction_id is not null and exists(
       select 1 from seed_units u where u.correction_id=t.correction_id))
     or exists(
       select 1 from seed_units u
       where u.correction_operation_id is not null
         and u.correction_chain_id is not null
         and u.correction_operation_id=coalesce(
           t.candidate_hint_text->'correction_financials_policy_envelope',
           f.policy_snapshot_json->'correction_financials_policy_envelope',
           f.rate_source_refs_json->'correction_financials_policy_envelope')
             #>>'{operation,operation_id}'
         and u.correction_chain_id=coalesce(
           t.candidate_hint_text->'correction_financials_policy_envelope',
           f.policy_snapshot_json->'correction_financials_policy_envelope',
           f.rate_source_refs_json->'correction_financials_policy_envelope')
             ->>'correction_chain_id')
),
classified as materialized (
  select a.*,
    case
      when jsonb_typeof(a.envelope)='object'
      then encode(digest(convert_to(
        (a.envelope-'envelope_fingerprint')::text,'UTF8'),
        'sha256'),'hex')
    end recomputed_fingerprint,
    coalesce((authority.settings_json#>>'{values,is_nhsp}')::boolean,false) is_nhsp,
    coalesce((authority.settings_json#>>'{values,autoprocess_hr}')::boolean,false) autoprocess_hr,
    coalesce((authority.settings_json#>>'{values,no_timesheet_required}')::boolean,false) no_timesheet_required,
    coalesce((authority.settings_json#>>'{values,self_bill}')::boolean,false) self_bill,
    (a.adjustment_origin in(
        'IMPORT_CORRECTION','IMPORT_CANCELLATION',
        'HEALTHROSTER_CHANGED_HOURS','NHSP_CHANGED_HOURS',
        'HEALTHROSTER_CANCELLATION','NHSP_CANCELLATION')
      or a.correction_kind in(
        'CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT',
        'CANCELLATION_REVERSAL','CANCELLATION_REPLACEMENT'))
      import_declared,
    coalesce(
      a.adjustment_origin in(
        'IMPORT_CORRECTION','IMPORT_CANCELLATION',
        'HEALTHROSTER_CHANGED_HOURS','NHSP_CHANGED_HOURS',
        'HEALTHROSTER_CANCELLATION','NHSP_CANCELLATION')
      and a.correction_kind in(
        'CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT',
        'CANCELLATION_REVERSAL','CANCELLATION_REPLACEMENT')
      and jsonb_typeof(a.envelope)='object'
      and a.envelope->>'policy_schema_version'=
        'IMPORT_CORRECTION_FINANCIALS_POLICY_V2'
      and a.envelope->>'route_family'='IMPORT_AUTHORITATIVE'
      and lower(coalesce(a.envelope#>>'{classification,canonical}','false'))
        in('true','t','1','yes')
      and nullif(a.envelope#>>'{operation,operation_id}','') is not null
      and nullif(a.envelope->>'correction_chain_id','') is not null
      and a.envelope->>'envelope_fingerprint'=
        case
          when jsonb_typeof(a.envelope)='object'
          then encode(digest(convert_to(
            (a.envelope-'envelope_fingerprint')::text,'UTF8'),
            'sha256'),'hex')
        end
      and(
        (a.correction_kind like 'CHANGED_HOURS_%'
          and a.envelope#>>'{operation,correction_action}'='CHANGED_HOURS')
        or
        (a.correction_kind like 'CANCELLATION_%'
          and a.envelope#>>'{operation,correction_action}'='CANCELLATION')),
      false) authoritative
  from all_current a
  cross join lateral (
    select private._timesheet_settings_authority_frozen_v1(a.timesheet_id)
      as settings_json
  ) authority
),
policy_checked as materialized (
  select c.*,
    c.envelope#>>'{operation,operation_id}' correction_operation_id,
    c.envelope->>'correction_chain_id' correction_chain_id,
    c.envelope->>'root_timesheet_id' frozen_root_timesheet_id,
    upper(btrim(coalesce(c.envelope->>'correction_shape','')))
      correction_shape,
    case when coalesce(c.envelope->>'expected_member_count','')~'^[0-9]+$'
      then(c.envelope->>'expected_member_count')::integer end
      expected_member_count,
    c.envelope->'expected_member_roles' expected_member_roles,
    case
      when c.correction_kind in(
        'CHANGED_HOURS_REVERSAL','CANCELLATION_REVERSAL')
        then 'REVERSAL'
      when c.correction_kind in(
        'CHANGED_HOURS_REPLACEMENT','CANCELLATION_REPLACEMENT')
        then 'REPLACEMENT'
      else 'INVALID'
    end correction_role,
    case
      when c.correction_kind in(
        'CHANGED_HOURS_REVERSAL','CANCELLATION_REVERSAL')
        then c.envelope->'reversal'
      when c.correction_kind in(
        'CHANGED_HOURS_REPLACEMENT','CANCELLATION_REPLACEMENT')
        then c.envelope->'replacement'
    end correction_leg
  from classified c
),
policy_validated as materialized (
  select p.*,
    case when jsonb_typeof(p.correction_leg)='object'
      then encode(digest(convert_to(
        (p.correction_leg-'leg_fingerprint')::text,'UTF8'),'sha256'),'hex')
    end recomputed_leg_fingerprint,
    case when jsonb_typeof(p.correction_leg->'tsfin_policy')='object'
      then encode(digest(convert_to(
        ((p.correction_leg->'tsfin_policy')-'tsfin_policy_fingerprint')::text,
        'UTF8'),'sha256'),'hex')
    end recomputed_tsfin_policy_fingerprint,
    case when jsonb_typeof(p.correction_leg->'invoice_policy')='object'
      then encode(digest(convert_to(
        ((p.correction_leg->'invoice_policy')-'invoice_policy_fingerprint')::text,
        'UTF8'),'sha256'),'hex')
    end recomputed_invoice_policy_fingerprint,
    case
      when private._candidate_feature_enabled_current_v1(
        'candidate_expense_invoice_routing_v1'
      )
      and (
        abs(coalesce(p.total_hours,0))
        +abs(coalesce(p.hours_day,0))+abs(coalesce(p.hours_night,0))
        +abs(coalesce(p.hours_sat,0))+abs(coalesce(p.hours_sun,0))
        +abs(coalesce(p.hours_bh,0))
        +abs(coalesce(p.additional_pay_ex_vat,0))
        +abs(coalesce(p.additional_charge_ex_vat,0))
      )=0
      and (
        abs(coalesce(p.expenses_pay_ex_vat,0))
        +abs(coalesce(p.expenses_charge_ex_vat,0))
        +abs(coalesce(p.mileage_pay_ex_vat,0))
        +abs(coalesce(p.mileage_charge_ex_vat,0))
        +abs(coalesce(p.travel_pay_ex_vat,0))
        +abs(coalesce(p.travel_charge_ex_vat,0))
        +abs(coalesce(p.accommodation_pay_ex_vat,0))
        +abs(coalesce(p.accommodation_charge_ex_vat,0))
        +abs(coalesce(p.other_pay_ex_vat,0))
        +abs(coalesce(p.other_charge_ex_vat,0))
      )>0 then 'EXPENSE'
      when upper(coalesce(p.basis,'')) in(
        'NHSP','NHSP_ADJUSTMENT','HEALTHROSTER_SELF_BILL',
        'HEALTHROSTER_ADJUSTMENT'
      ) then 'SELF_BILL'
      when p.self_bill then 'SELF_BILL'
      else 'NORMAL'
    end current_invoice_stream
  from policy_checked p
),
policy_final as materialized (
  select p.*,
    (
      not p.import_declared
      or(
        jsonb_typeof(p.envelope)='object'
        and nullif(p.envelope->>'envelope_fingerprint','') is not null
        and p.envelope->>'envelope_fingerprint'=p.recomputed_fingerprint
        and p.correction_shape in('REVERSAL_ONLY','REVERSAL_REPLACEMENT')
        and p.expected_member_count between 1 and 100
        and jsonb_typeof(p.expected_member_roles)='array'
        and jsonb_array_length(p.expected_member_roles)=p.expected_member_count
        and nullif(p.correction_operation_id,'') is not null
        and nullif(p.correction_chain_id,'') is not null
        and jsonb_typeof(p.correction_leg)='object'
        and p.correction_leg->>'leg_fingerprint'
          =p.recomputed_leg_fingerprint
        and p.correction_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}'
          =p.recomputed_tsfin_policy_fingerprint
        and p.correction_leg#>>'{invoice_policy,invoice_policy_fingerprint}'
          =p.recomputed_invoice_policy_fingerprint
        and p.correction_leg#>>'{invoice_policy,invoice_stream}'
          =p.envelope->>'invoice_stream'
        and p.current_invoice_stream=p.envelope->>'invoice_stream'
        and coalesce(
          p.policy_snapshot_json->>'correction_financials_policy_envelope_fingerprint',
          p.policy_snapshot_json#>>
            '{correction_financials_policy_envelope,envelope_fingerprint}',
          p.rate_source_refs_json->>'correction_financials_policy_envelope_fingerprint')
          is not distinct from p.envelope->>'envelope_fingerprint'
        and coalesce(
          p.policy_snapshot_json->>'correction_leg_fingerprint',
          p.rate_source_refs_json->>'correction_leg_fingerprint')
          is not distinct from p.correction_leg->>'leg_fingerprint'
        and coalesce(
          p.policy_snapshot_json->>'correction_tsfin_policy_fingerprint',
          p.rate_source_refs_json->>'correction_tsfin_policy_fingerprint')
          is not distinct from
            p.correction_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}'
        and coalesce(
          p.policy_snapshot_json->>'correction_invoice_policy_fingerprint',
          p.rate_source_refs_json->>'correction_invoice_policy_fingerprint')
          is not distinct from
            p.correction_leg#>>'{invoice_policy,invoice_policy_fingerprint}'
        and p.policy_snapshot_json->'correction_invoice_policy'
          is not distinct from p.correction_leg->'invoice_policy'
        and upper(btrim(coalesce(
          p.policy_snapshot_json->>'correction_invoice_stream','')))
          is not distinct from p.envelope->>'invoice_stream'
      )
    ) frozen_policy_valid
  from policy_validated p
),
target_classes as materialized (
  select t.invoice_id,t.scope_key,t.timesheet_id,c.correction_id,
    c.correction_kind,c.import_declared,c.authoritative,c.envelope,c.client_id,c.contract_id,
    c.week_ending_date,c.basis,c.correction_operation_id,
    c.correction_chain_id
  from targets t
  join policy_final c on c.timesheet_id=t.timesheet_id
),
members as materialized (
  select tc.invoice_id,tc.scope_key,tc.timesheet_id target_timesheet_id,
    tc.correction_id,tc.correction_kind target_kind,
    tc.envelope target_envelope,
    m.timesheet_id,m.correction_kind,m.client_id,m.contract_id,
    m.week_ending_date,m.basis,m.financial_id,m.processing_status,
    m.is_stale,m.stale_reason,m.locked_by_invoice_id,
    m.invoice_breakdown_json,
    m.envelope,m.recomputed_fingerprint,m.is_nhsp,m.autoprocess_hr,
    m.no_timesheet_required,m.import_declared,m.authoritative,
    m.frozen_policy_valid,m.adjustment_origin,m.timesheet_status,
    m.policy_snapshot_json,m.rate_source_refs_json,
    m.recomputed_leg_fingerprint,m.recomputed_tsfin_policy_fingerprint,
    m.recomputed_invoice_policy_fingerprint,m.correction_role,m.correction_shape,m.expected_member_count,
    m.expected_member_roles,m.correction_operation_id,
    m.correction_chain_id,m.frozen_root_timesheet_id,
    m.current_invoice_stream,m.correction_leg
  from target_classes tc
  join policy_final m
    on m.timesheet_id=tc.timesheet_id
      or(
        tc.authoritative
        and m.authoritative
        and m.correction_operation_id=tc.correction_operation_id
        and m.correction_chain_id=tc.correction_chain_id)
      or(
        not tc.authoritative
        and tc.correction_id is not null
        and m.correction_id=tc.correction_id)
),
member_ancestors as (
  select m.scope_key,m.target_timesheet_id,m.timesheet_id member_timesheet_id,
    t.timesheet_id ancestor_id,t.parent_timesheet_id,0 depth,
    array[t.timesheet_id]::uuid[] path,false cycle
  from members m
  join public.timesheets t on t.timesheet_id=m.timesheet_id
  union all
  select a.scope_key,a.target_timesheet_id,a.member_timesheet_id,
    p.timesheet_id,p.parent_timesheet_id,a.depth+1,
    a.path||p.timesheet_id,p.timesheet_id=any(a.path)
  from member_ancestors a
  join public.timesheets p on p.timesheet_id=a.parent_timesheet_id
  where a.parent_timesheet_id is not null
    and not a.cycle and a.depth<32
),
member_roots as materialized (
  select distinct on(
      a.scope_key,a.target_timesheet_id,a.member_timesheet_id)
    a.scope_key,a.target_timesheet_id,a.member_timesheet_id,
    a.ancestor_id root_timesheet_id,a.cycle,
    a.depth=32 and a.parent_timesheet_id is not null depth_exceeded
  from member_ancestors a
  order by a.scope_key,a.target_timesheet_id,a.member_timesheet_id,
    a.depth desc,a.ancestor_id
),
rollup as materialized (
  select m.invoice_id,m.scope_key,m.target_timesheet_id timesheet_id,
    m.correction_id,
    bool_or(m.import_declared) import_declared,
    bool_or(m.authoritative) authoritative,
    array_agg(distinct m.timesheet_id order by m.timesheet_id) required_ids,
    count(*) filter(where m.financial_id is not null
      and upper(coalesce(m.processing_status,''))='READY_FOR_INVOICE') ready_count,
    count(*) filter(where m.financial_id is null) missing_financial_count,
    count(*) filter(where coalesce(m.is_stale,false)) stale_financial_count,
    count(*) filter(where m.financial_id is not null
      and upper(coalesce(m.processing_status,''))<>'READY_FOR_INVOICE')
      not_ready_financial_count,
    count(*) filter(where m.locked_by_invoice_id is not null
      and(m.invoice_id is null
        or m.locked_by_invoice_id<>m.invoice_id)) whole_lock_conflict_count,
    count(*) filter(where exists(
      select 1
      from jsonb_array_elements(case
        when jsonb_typeof(m.invoice_breakdown_json->'segments')='array'
          then m.invoice_breakdown_json->'segments'
        else '[]'::jsonb end) seg(value)
      where nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'') is not null
        and(m.invoice_id is null
          or seg.value->>'invoice_locked_invoice_id'<>m.invoice_id::text)
        and(
          not exists(
            select 1 from planned_lines selected
            where selected.scope_key=m.scope_key
              and selected.timesheet_id=m.timesheet_id
              and selected.segment_id is not null)
          or seg.value->>'segment_id' in(
            select selected.segment_id from planned_lines selected
            where selected.scope_key=m.scope_key
              and selected.timesheet_id=m.timesheet_id
              and selected.segment_id is not null)))
    )
      segment_lock_conflict_count,
    count(distinct m.timesheet_id) member_count,
    count(distinct m.client_id) client_count,
    (min(m.client_id::text))::uuid member_client_id,
    count(distinct m.contract_id) contract_count,
    (min(m.contract_id::text))::uuid member_contract_id,
    count(distinct m.week_ending_date) week_count,
    min(m.week_ending_date) member_week,
    count(distinct case when upper(coalesce(m.basis,'')) in(
      'NHSP','NHSP_ADJUSTMENT','HEALTHROSTER_SELF_BILL',
      'HEALTHROSTER_ADJUSTMENT') then 'SELF_BILL' else 'NORMAL' end)
      stream_count,
    min(case when m.import_declared then m.envelope->>'invoice_stream'
      else m.current_invoice_stream end) expected_invoice_stream,
    count(*) filter(where m.correction_kind like '%_REVERSAL') reversal_count,
    count(*) filter(where m.correction_kind like '%_REPLACEMENT')
      replacement_count,
    bool_or(m.correction_kind like 'CHANGED_HOURS_%') changed_hours,
    bool_or(m.correction_kind like 'CANCELLATION_%') cancellation,
    bool_and(m.frozen_policy_valid) envelope_valid,
    count(*) filter(where m.import_declared
      and jsonb_typeof(m.envelope) is distinct from 'object')
      missing_envelope_count,
    count(*) filter(where m.import_declared
      and coalesce(m.envelope->>'policy_schema_version','')<>
        'IMPORT_CORRECTION_FINANCIALS_POLICY_V2') invalid_schema_count,
    count(*) filter(where m.import_declared
      and coalesce(m.envelope->>'route_family','')<>'IMPORT_AUTHORITATIVE')
      invalid_route_count,
    count(*) filter(where m.import_declared and(
      lower(coalesce(m.envelope#>>'{classification,canonical}','false'))
        not in('true','t','1','yes')
      or lower(coalesce(
        m.envelope#>>'{classification,client_eligible_at_operation}',
        'false')) not in('true','t','1','yes')
      or nullif(btrim(m.envelope#>>'{classification,source_system}'),'')
        is null)) invalid_classification_count,
    count(*) filter(where m.import_declared
      and nullif(m.envelope#>>'{operation,operation_id}','') is null)
      missing_operation_count,
    count(*) filter(where m.import_declared
      and nullif(m.envelope->>'correction_chain_id','') is null)
      missing_chain_count,
    count(*) filter(where m.import_declared and(
      (m.correction_kind like 'CHANGED_HOURS_%'
        and coalesce(m.envelope#>>'{operation,correction_action}','')<>
          'CHANGED_HOURS')
      or(m.correction_kind like 'CANCELLATION_%'
        and coalesce(m.envelope#>>'{operation,correction_action}','')<>
          'CANCELLATION'))) invalid_action_count,
    count(*) filter(where m.import_declared and(
      nullif(m.envelope->>'envelope_fingerprint','') is null
      or m.envelope->>'envelope_fingerprint'
        is distinct from m.recomputed_fingerprint)) envelope_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared
      and jsonb_typeof(m.correction_leg) is distinct from 'object')
      missing_leg_count,
    count(*) filter(where m.import_declared and(
      nullif(m.correction_leg->>'leg_fingerprint','') is null
      or m.correction_leg->>'leg_fingerprint'
        is distinct from m.recomputed_leg_fingerprint))
      leg_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and(
      jsonb_typeof(m.correction_leg->'tsfin_policy') is distinct from 'object'
      or m.correction_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}'
        is distinct from m.recomputed_tsfin_policy_fingerprint))
      tsfin_policy_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and(
      jsonb_typeof(m.correction_leg->'invoice_policy')
        is distinct from 'object'
      or m.correction_leg#>>'{invoice_policy,invoice_policy_fingerprint}'
        is distinct from m.recomputed_invoice_policy_fingerprint))
      invoice_policy_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and(
      m.correction_leg#>>'{invoice_policy,invoice_stream}'
        is distinct from m.envelope->>'invoice_stream'
      or m.current_invoice_stream
        is distinct from m.envelope->>'invoice_stream'))
      policy_stream_mismatch_count,
    count(*) filter(where m.import_declared and coalesce(
      m.policy_snapshot_json->>'correction_financials_policy_envelope_fingerprint',
      m.policy_snapshot_json#>>
        '{correction_financials_policy_envelope,envelope_fingerprint}',
      m.rate_source_refs_json->>
        'correction_financials_policy_envelope_fingerprint')
      is distinct from m.envelope->>'envelope_fingerprint')
      current_envelope_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and coalesce(
      m.policy_snapshot_json->>'correction_leg_fingerprint',
      m.rate_source_refs_json->>'correction_leg_fingerprint')
      is distinct from m.correction_leg->>'leg_fingerprint')
      current_leg_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and coalesce(
      m.policy_snapshot_json->>'correction_tsfin_policy_fingerprint',
      m.rate_source_refs_json->>'correction_tsfin_policy_fingerprint')
      is distinct from
        m.correction_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}')
      current_tsfin_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and coalesce(
      m.policy_snapshot_json->>'correction_invoice_policy_fingerprint',
      m.rate_source_refs_json->>'correction_invoice_policy_fingerprint')
      is distinct from
        m.correction_leg#>>'{invoice_policy,invoice_policy_fingerprint}')
      current_invoice_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and(
      m.policy_snapshot_json->'correction_tsfin_policy'
        is distinct from m.correction_leg->'tsfin_policy'
      or m.policy_snapshot_json->'correction_invoice_policy'
        is distinct from m.correction_leg->'invoice_policy'))
      frozen_subpolicy_drift_count,
    count(distinct m.correction_operation_id)
      filter(where m.import_declared) correction_operation_count,
    count(distinct m.correction_chain_id)
      filter(where m.import_declared) correction_chain_count,
    count(distinct m.frozen_root_timesheet_id)
      filter(where m.import_declared) frozen_root_count,
    count(distinct mr.root_timesheet_id)
      filter(where m.import_declared) actual_root_count,
    bool_or(coalesce(mr.cycle,false)) chain_cycle,
    bool_or(coalesce(mr.depth_exceeded,false)) chain_depth_exceeded,
    bool_and(not m.import_declared
      or m.frozen_root_timesheet_id=mr.root_timesheet_id::text)
      frozen_root_matches,
    count(distinct m.envelope->>'envelope_fingerprint')
      filter(where m.import_declared) envelope_count,
    max(m.expected_member_count)
      filter(where m.import_declared) expected_member_count,
    count(distinct m.expected_member_count)
      filter(where m.import_declared) expected_count_variants,
    count(distinct m.correction_shape)
      filter(where m.import_declared) shape_variants,
    min(m.correction_shape)
      filter(where m.import_declared) correction_shape,
    coalesce(jsonb_agg(m.correction_role order by
      case m.correction_role when 'REVERSAL' then 1
        when 'REPLACEMENT' then 2 else 3 end,m.timesheet_id)
      filter(where m.import_declared),'[]'::jsonb) actual_member_roles,
    (min(m.expected_member_roles::text)
      filter(where m.import_declared))::jsonb expected_member_roles
  from members m
  left join member_roots mr on mr.scope_key=m.scope_key
    and mr.target_timesheet_id=m.target_timesheet_id
    and mr.member_timesheet_id=m.timesheet_id
  group by m.invoice_id,m.scope_key,m.target_timesheet_id,m.correction_id
),
candidate_lines as materialized (
  select distinct r.scope_key,r.invoice_id target_invoice_id,
    l.invoice_id line_invoice_id,l.timesheet_id,l.vat_rate_pct,
    false planned
  from rollup r
  join members m on m.scope_key=r.scope_key
    and m.target_timesheet_id=r.timesheet_id
  join public.invoice_lines l on l.timesheet_id=m.timesheet_id
  union all
  select p.scope_key,p.invoice_id,p.invoice_id,p.timesheet_id,p.vat_rate_pct,
    true
  from planned_lines p
  where not exists(
    select 1 from public.invoice_lines l
    where l.invoice_id=p.invoice_id and l.timesheet_id=p.timesheet_id)
),
line_scope as materialized (
  select r.invoice_id,r.scope_key,r.timesheet_id,
    array_agg(distinct l.timesheet_id order by l.timesheet_id)
      filter(where l.timesheet_id is not null and(
        l.planned or(
          r.invoice_id is not null and l.line_invoice_id=r.invoice_id)))
      present_ids,
    array_agg(distinct l.line_invoice_id order by l.line_invoice_id)
      filter(where not l.planned and(
        r.invoice_id is null or l.line_invoice_id<>r.invoice_id))
      conflicting_ids,
    count(distinct l.timesheet_id) filter(where l.timesheet_id is not null and(
      l.planned or(
        r.invoice_id is not null and l.line_invoice_id=r.invoice_id)))
      present_count,
    count(*) filter(where l.timesheet_id is not null and(
        l.planned or(
          r.invoice_id is not null and l.line_invoice_id=r.invoice_id))
      and coalesce(l.vat_rate_pct,-999999) is distinct from
        case when coalesce(
          m.correction_leg#>>'{invoice_policy,applied_vat_rate_pct}','')
          ~'^[+-]?[0-9]+([.][0-9]+)?$'
          then (m.correction_leg#>>
            '{invoice_policy,applied_vat_rate_pct}')::numeric
          else coalesce(l.vat_rate_pct,-999999) end) vat_mismatch_count
  from rollup r
  join members m on m.scope_key=r.scope_key
    and m.target_timesheet_id=r.timesheet_id
  left join candidate_lines l on l.scope_key=r.scope_key
    and l.timesheet_id=m.timesheet_id
  group by r.invoice_id,r.scope_key,r.timesheet_id
),
final as materialized (
  select r.*,coalesce(ls.present_ids,array[]::uuid[]) present_ids,
    coalesce(ls.conflicting_ids,array[]::uuid[]) conflicting_ids,
    coalesce(ls.present_count,0) present_count,
    coalesce(ls.vat_mismatch_count,0) vat_mismatch_count,
    array(select x from unnest(r.required_ids) x
      where not x=any(coalesce(ls.present_ids,array[]::uuid[]))) missing_ids,
    ti.id is not null target_exists,
    ti.status::text target_status,
    ti.issued_at_utc target_issued_at_utc,
    ti.client_id target_client_id,
    case
      when lower(coalesce(
        ti.header_snapshot_json#>>'{meta,self_bill}','false'))
        in('true','t','1','yes') then 'SELF_BILL'
      when private._candidate_feature_enabled_current_v1(
        'candidate_expense_invoice_routing_v1'
      ) and upper(coalesce(
        nullif(btrim(ti.header_snapshot_json->>'invoice_stream'),''),
        nullif(btrim(ti.header_snapshot_json#>>'{meta,invoice_stream}'),''),
        'NORMAL'
      ))='EXPENSE' then 'EXPENSE'
      else 'NORMAL'
    end target_invoice_stream,
    coalesce(pair_scope.scope_json,'{}'::jsonb) pair_scope_json,
    (
      not r.import_declared
      or(
        r.correction_operation_count=1
        and r.correction_chain_count=1
        and r.frozen_root_count=1
        and r.actual_root_count=1
        and r.frozen_root_matches
        and not r.chain_cycle
        and not r.chain_depth_exceeded
        and r.envelope_count=1
        and r.expected_count_variants=1
        and r.shape_variants=1
        and r.expected_member_count=r.member_count
        and r.actual_member_roles=r.expected_member_roles
        and r.reversal_count=1
        and r.replacement_count=case
          when r.correction_shape='REVERSAL_ONLY' then 0 else 1 end
        and r.correction_shape in('REVERSAL_ONLY','REVERSAL_REPLACEMENT')
      )
    ) pair_balanced
  from rollup r
  left join line_scope ls
    on ls.invoice_id is not distinct from r.invoice_id
   and ls.scope_key=r.scope_key
   and ls.timesheet_id=r.timesheet_id
  left join public.invoices ti on ti.id=r.invoice_id
  left join lateral (
    select public.invoice_correction_pair_scope_v1(
      r.timesheet_id,null::uuid,null::uuid,false,100) scope_json
    where r.import_declared
  ) pair_scope on true
),
member_results as materialized (
  select f.*,s.request_key,s.external_scope_key,s.validation_purpose,
    s.expected_client_id,s.expected_contract_id,s.natural_source_week,
    s.target_invoice_week,s.expected_invoice_stream scope_expected_stream,
    s.expected_vat_rate_pct,
    case when f.import_declared then 'IMPORT_AUTHORITATIVE'
      when f.correction_id is not null then 'NON_AUTHORITATIVE_CORRECTION'
      else 'ORDINARY' end correction_classification,
    b.blocker_codes,
    jsonb_build_object(
      'actual_member_count',f.member_count,
      'existing_line_member_count',f.present_count,
      'ready_count',f.ready_count,
      'missing_financial_count',f.missing_financial_count,
      'stale_financial_count',f.stale_financial_count,
      'not_ready_financial_count',f.not_ready_financial_count,
      'whole_lock_conflict_count',f.whole_lock_conflict_count,
      'segment_lock_conflict_count',f.segment_lock_conflict_count,
      'reversal_count',f.reversal_count,
      'replacement_count',f.replacement_count,
      'correction_shape',f.correction_shape,
      'expected_member_count',f.expected_member_count,
      'expected_member_roles',f.expected_member_roles,
      'actual_member_roles',f.actual_member_roles,
      'correction_operation_count',f.correction_operation_count,
      'correction_chain_count',f.correction_chain_count,
      'frozen_root_count',f.frozen_root_count,
      'actual_root_count',f.actual_root_count,
      'frozen_root_matches',f.frozen_root_matches,
      'chain_cycle',f.chain_cycle,
      'chain_depth_exceeded',f.chain_depth_exceeded,
      'expected_invoice_stream',f.expected_invoice_stream,
      'target_invoice_stream',case when f.invoice_id is null
        then null else f.target_invoice_stream end,
      'member_client_id',f.member_client_id,
      'member_contract_id',f.member_contract_id,
      'member_week',f.member_week,
      'target_client_id',f.target_client_id,
      'target_status',f.target_status,
      'vat_mismatch_count',f.vat_mismatch_count,
      'policy_failure_counts',jsonb_build_object(
        'missing_envelope',f.missing_envelope_count,
        'invalid_schema',f.invalid_schema_count,
        'invalid_route',f.invalid_route_count,
        'invalid_classification',f.invalid_classification_count,
        'missing_operation',f.missing_operation_count,
        'missing_chain',f.missing_chain_count,
        'invalid_action',f.invalid_action_count,
        'envelope_fingerprint',f.envelope_fingerprint_mismatch_count,
        'missing_leg',f.missing_leg_count,
        'leg_fingerprint',f.leg_fingerprint_mismatch_count,
        'tsfin_policy_fingerprint',f.tsfin_policy_fingerprint_mismatch_count,
        'invoice_policy_fingerprint',f.invoice_policy_fingerprint_mismatch_count,
        'policy_stream',f.policy_stream_mismatch_count,
        'current_envelope_fingerprint',
          f.current_envelope_fingerprint_mismatch_count,
        'current_leg_fingerprint',f.current_leg_fingerprint_mismatch_count,
        'current_tsfin_fingerprint',f.current_tsfin_fingerprint_mismatch_count,
        'current_invoice_fingerprint',
          f.current_invoice_fingerprint_mismatch_count,
        'frozen_subpolicy_drift',f.frozen_subpolicy_drift_count)) detail_json
  from final f
  join scopes s on s.scope_key=f.scope_key
  cross join lateral (
    select coalesce(array_agg(code order by ordinal)
      filter(where code is not null),array[]::text[]) blocker_codes
    from unnest(array[
      case when p_evaluation_date is null
        then 'EVALUATION_DATE_REQUIRED' end,
      case when f.invoice_id is not null
        and s.validation_purpose not in('CREDIT_SOURCE','RECONCILE')
        and not f.target_exists
        then 'INVOICE_CORRECTION_TARGET_NOT_FOUND' end,
      case when f.invoice_id is not null
        and s.validation_purpose not in('CREDIT_SOURCE','RECONCILE')
        and(upper(coalesce(f.target_status,''))<>'DRAFT'
          or f.target_issued_at_utc is not null)
        then 'INVOICE_CORRECTION_TARGET_NOT_APPENDABLE' end,
      case when f.invoice_id is not null
        and s.validation_purpose not in('CREDIT_SOURCE','RECONCILE')
        and f.target_client_id is distinct from f.member_client_id
        then 'INVOICE_CORRECTION_TARGET_CLIENT_MISMATCH' end,
      case when s.expected_client_id is not null
        and s.expected_client_id is distinct from f.member_client_id
        then 'INVOICE_CORRECTION_CLIENT_MISMATCH' end,
      case when s.expected_contract_id is not null
        and s.expected_contract_id is distinct from f.member_contract_id
        then 'INVOICE_CORRECTION_CONTRACT_MISMATCH' end,
      case when s.natural_source_week is not null
        and s.natural_source_week is distinct from f.member_week
        then 'INVOICE_CORRECTION_WEEK_MISMATCH' end,
      case when s.expected_invoice_stream is not null
        and s.expected_invoice_stream is distinct from f.expected_invoice_stream
        then 'INVOICE_CORRECTION_STREAM_MISMATCH' end,
      case when f.invoice_id is not null
        and s.validation_purpose not in('CREDIT_SOURCE','RECONCILE')
        and f.target_invoice_stream is distinct from f.expected_invoice_stream
        then 'INVOICE_CORRECTION_TARGET_STREAM_MISMATCH' end,
      case when f.import_declared and f.missing_envelope_count>0
        then 'INVOICE_CORRECTION_ENVELOPE_MISSING' end,
      case when f.import_declared and f.invalid_schema_count>0
        then 'INVOICE_CORRECTION_ENVELOPE_SCHEMA_INVALID' end,
      case when f.import_declared and f.invalid_route_count>0
        then 'INVOICE_CORRECTION_ROUTE_FAMILY_INVALID' end,
      case when f.import_declared and f.invalid_classification_count>0
        then 'INVOICE_CORRECTION_CLASSIFICATION_INVALID' end,
      case when f.import_declared and f.missing_operation_count>0
        then 'INVOICE_CORRECTION_OPERATION_IDENTITY_INVALID' end,
      case when f.import_declared and f.missing_chain_count>0
        then 'INVOICE_CORRECTION_CHAIN_IDENTITY_INVALID' end,
      case when f.import_declared and f.invalid_action_count>0
        then 'INVOICE_CORRECTION_ACTION_INVALID' end,
      case when f.import_declared and f.envelope_fingerprint_mismatch_count>0
        then 'INVOICE_CORRECTION_ENVELOPE_FINGERPRINT_MISMATCH' end,
      case when f.import_declared and f.envelope_count<>1
        then 'INVOICE_CORRECTION_MEMBER_ENVELOPE_MISMATCH' end,
      case when f.import_declared and f.missing_leg_count>0
        then 'INVOICE_CORRECTION_LEG_MISSING' end,
      case when f.import_declared and f.leg_fingerprint_mismatch_count>0
        then 'INVOICE_CORRECTION_LEG_FINGERPRINT_MISMATCH' end,
      case when f.import_declared
        and f.tsfin_policy_fingerprint_mismatch_count>0
        then 'INVOICE_CORRECTION_TSFIN_POLICY_FINGERPRINT_MISMATCH' end,
      case when f.import_declared
        and f.invoice_policy_fingerprint_mismatch_count>0
        then 'INVOICE_CORRECTION_INVOICE_POLICY_FINGERPRINT_MISMATCH' end,
      case when f.import_declared and f.policy_stream_mismatch_count>0
        then 'INVOICE_CORRECTION_STREAM_MISMATCH' end,
      case when f.import_declared
        and(f.current_envelope_fingerprint_mismatch_count>0
          or f.current_leg_fingerprint_mismatch_count>0
          or f.current_tsfin_fingerprint_mismatch_count>0
          or f.current_invoice_fingerprint_mismatch_count>0)
        then 'INVOICE_CORRECTION_CURRENT_POLICY_FINGERPRINT_MISMATCH' end,
      case when f.import_declared and f.frozen_subpolicy_drift_count>0
        then 'INVOICE_CORRECTION_FROZEN_POLICY_DRIFT' end,
      case when f.chain_cycle then 'INVOICE_CORRECTION_CHAIN_CYCLE' end,
      case when f.chain_depth_exceeded
        then 'INVOICE_CORRECTION_CHAIN_DEPTH_EXCEEDED' end,
      case when f.member_count>100
        then 'INVOICE_CORRECTION_MEMBER_LIMIT_EXCEEDED' end,
      case when f.import_declared and not f.frozen_root_matches
        then 'INVOICE_CORRECTION_ENVELOPE_ROOT_MISMATCH' end,
      case when f.missing_financial_count>0
        then 'INVOICE_CORRECTION_TSFIN_MISSING' end,
      case when f.stale_financial_count>0
        then 'INVOICE_CORRECTION_TSFIN_STALE' end,
      case when f.not_ready_financial_count>0
        or f.ready_count<>f.member_count
        then 'INVOICE_CORRECTION_TSFIN_NOT_READY' end,
      case when f.client_count<>1
        then 'INVOICE_CORRECTION_CLIENT_MISMATCH' end,
      case when f.contract_count<>1
        then 'INVOICE_CORRECTION_CONTRACT_MISMATCH' end,
      case when f.week_count<>1
        then 'INVOICE_CORRECTION_WEEK_MISMATCH' end,
      case when f.stream_count<>1
        then 'INVOICE_CORRECTION_STREAM_MISMATCH' end,
      case when f.whole_lock_conflict_count>0
        then 'INVOICE_CORRECTION_SOURCE_LOCK_CONFLICT' end,
      case when f.segment_lock_conflict_count>0
        then 'INVOICE_CORRECTION_SEGMENT_LOCK_CONFLICT' end,
      case when f.pair_scope_json->>'placement_state'='INCOMPLETE_MOVE'
        then 'INVOICE_CORRECTION_PAIR_PLACEMENT_INCOMPLETE' end,
      case when cardinality(f.conflicting_ids)>0
        and not (
          coalesce((f.pair_scope_json->>'valid')::boolean,false)
          and f.pair_scope_json->>'placement_state' in ('COMPLETE_SPLIT_INVOICES','INCOMPLETE_MOVE')
        )
        then 'INVOICE_CORRECTION_UNIT_SPLIT_ACROSS_INVOICES' end,
      case when (cardinality(f.missing_ids)>0
        and not (
          coalesce((f.pair_scope_json->>'valid')::boolean,false)
          and f.pair_scope_json->>'placement_state' in ('COMPLETE_SPLIT_INVOICES','INCOMPLETE_MOVE')
        ))
        or(f.import_declared
          and coalesce(f.expected_member_count,0)>f.member_count
          and f.pair_scope_json->>'placement_state'<>'INCOMPLETE_MOVE')
        then 'INVOICE_CORRECTION_MEMBER_MISSING' end,
      case when f.vat_mismatch_count>0
        then 'INVOICE_CORRECTION_VAT_POLICY_MISMATCH' end,
      case when f.import_declared and not f.pair_balanced
        then 'INVOICE_CORRECTION_UNIT_INVALID' end
    ]::text[]) with ordinality u(code,ordinal)
  ) b
),
scope_blockers as materialized (
  select s.scope_key,coalesce(array_agg(x.code order by x.first_ordinal)
      filter(where x.code is not null),array[]::text[]) blocker_codes
  from scopes s
  left join lateral (
    select u.code,min(u.ordinal)::integer first_ordinal
    from member_results m
    cross join lateral unnest(m.blocker_codes) with ordinality u(code,ordinal)
    where m.scope_key=s.scope_key
    group by u.code
  ) x on true
  group by s.scope_key
),
scope_summary as materialized (
  select s.request_key,s.external_scope_key scope_key,s.invoice_id,
    case when count(distinct m.timesheet_id)=1 then (min(m.timesheet_id::text))::uuid end
      timesheet_id,
    case when bool_or(coalesce(m.import_declared,false))
      then 'IMPORT_AUTHORITATIVE'
      when bool_or(m.correction_id is not null)
      then 'NON_AUTHORITATIVE_CORRECTION'
      else 'ORDINARY' end correction_classification,
    case when count(distinct m.correction_id)=1 then min(m.correction_id) end
      correction_id,
    coalesce(array_agg(distinct m.correction_id order by m.correction_id)
      filter(where m.correction_id is not null),array[]::text[])
      correction_ids,
    coalesce(array(select distinct x from member_results mr
      cross join lateral unnest(mr.required_ids) q(x)
      where mr.scope_key=s.scope_key order by x),array[]::uuid[])
      required_member_ids,
    coalesce(array(select distinct x from member_results mr
      cross join lateral unnest(mr.missing_ids) q(x)
      where mr.scope_key=s.scope_key order by x),array[]::uuid[])
      missing_member_ids,
    coalesce(array(select distinct x from member_results mr
      cross join lateral unnest(mr.conflicting_ids) q(x)
      where mr.scope_key=s.scope_key order by x),array[]::uuid[])
      conflicting_invoice_ids,
    coalesce(bool_and(m.pair_balanced),true) balanced,
    sb.blocker_codes,
    jsonb_build_object(
      'validation_purpose',s.validation_purpose,
      'evaluation_date',p_evaluation_date,
      'natural_source_week',s.natural_source_week,
      'target_invoice_week',s.target_invoice_week,
      'unit_count',count(distinct(m.correction_id,m.timesheet_id))
        filter(where m.correction_id is not null),
      'units',coalesce(jsonb_agg(jsonb_build_object(
        'timesheet_id',m.timesheet_id,
        'correction_id',m.correction_id,
        'classification',m.correction_classification,
        'required_member_ids',m.required_ids,
        'missing_member_ids',m.missing_ids,
        'conflicting_invoice_ids',m.conflicting_ids,
        'balanced',m.pair_balanced,
        'blocker_codes',m.blocker_codes,
        'detail',m.detail_json)
        order by m.correction_id nulls last,m.timesheet_id)
        filter(where m.timesheet_id is not null),'[]'::jsonb)) detail_json
  from scopes s
  left join member_results m on m.scope_key=s.scope_key
  join scope_blockers sb on sb.scope_key=s.scope_key
  group by s.request_key,s.external_scope_key,s.scope_key,s.invoice_id,
    s.validation_purpose,s.natural_source_week,s.target_invoice_week,
    sb.blocker_codes
)
select request_key,scope_key,invoice_id,timesheet_id,
  correction_classification,correction_id,correction_ids,
  required_member_ids,missing_member_ids,conflicting_invoice_ids,
  balanced,cardinality(blocker_codes)=0 valid,
  blocker_codes[1] blocker_code,blocker_codes,detail_json
from scope_summary
order by request_key,scope_key;
$function$;

revoke all on function private._invoice_correction_validate_batch(jsonb,date)
  from public,anon,authenticated;
grant execute on function private._invoice_correction_validate_batch(jsonb,date)
  to service_role;


commit;

-- CONTACT_PREPARER_UNIT 23 repeatable supabase/repeatable/15092026_1534_weekly_source_invoice_batch_ordinary_isolation_v1.sql SHA256 73137c8843aadb8a15aa1e67513ce92dea4cd67955e20e368d0ebc3c5de67732
-- Keep the established ordinary batch classifier byte-for-byte equivalent to
-- its v2 authority, except that a Timesheet owned by immutable Weekly-source
-- lineage can only be invoiced from its final-source Client manifest.  This
-- replacement must be installed after weekly_source_row_timesheet_lineages.
create or replace function private._invoice_batch_generate_classification_v2(
  p_allow_early boolean default false,
  p_scope_keys text[] default null,
  p_now_utc timestamptz default now()
) returns table(
  selection_key text,
  candidate_json jsonb
)
language plpgsql
stable
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_scope_keys text[];
begin
  if p_scope_keys is not null then
    if cardinality(p_scope_keys)>250 then
      raise exception using
        errcode='22023',
        message='CANDIDATE_SCOPE_KEY_LIMIT_EXCEEDED';
    end if;
    if exists(
      select 1
      from unnest(p_scope_keys) value
      where value is null
        or btrim(value)=''
        or length(btrim(value))>512
    ) then
      raise exception using
        errcode='22023',
        message='CANDIDATE_SCOPE_KEY_INVALID';
    end if;
    select coalesce(array_agg(value order by value),'{}'::text[])
    into v_scope_keys
    from(
      select distinct btrim(raw_value) value
      from unnest(p_scope_keys) raw_value
    ) deduplicated;
  end if;

  return query
  with
  anchor as materialized (
    select
      coalesce(p_now_utc,statement_timestamp()) evaluation_utc,
      (
        coalesce(p_now_utc,statement_timestamp())
        at time zone 'Europe/London'
      )::date today
  ),
  source_candidate_families as materialized (
    select distinct financial.timesheet_id,
      private.weekly_source_invoice_family_timesheet_ids_v1(financial.timesheet_id) family_ids
    from public.timesheets_financials financial
    join public.timesheets timesheet
      on timesheet.timesheet_id=financial.timesheet_id
     and timesheet.is_current
     and timesheet.revoked_at is null
    where financial.is_current
      and financial.client_id is not null
  ),
  source_candidates as materialized (
    select candidate.timesheet_id from source_candidate_families candidate
      -- Gate 13 hostile review F4 / standing rule 3: after S8 a physical root
      -- id is not a family identity, so this predicate - the one thing that
      -- keeps ordinary invoicing and Weekly-Source self-billing apart - is
      -- keyed on the Timesheet FAMILY.  A lineage-bound root that rotates keeps
      -- its lineage row on the OLD physical id; keyed on the bare id, the new
      -- current version was offered to the ordinary batch as READY and the same
      -- worked time could be invoiced twice.  Resolution goes through the one
      -- installed resolver adapter (proof/34 s10 rule 12); there is no second
      -- identity mechanism and no inline re-derivation here.  The resolver
      -- falls back to the singleton {id} for a Timesheet with no booking
      -- identity, so an unrotated Timesheet is classified exactly as before.
    where candidate.family_ids is not null and cardinality(candidate.family_ids)>0
      and not exists (
        select 1
        from public.weekly_source_row_timesheet_lineages lineage
        where lineage.timesheet_id=any(candidate.family_ids)
      )
      -- Protected-only ownership is the same Source invoice boundary as
      -- lineage. It cannot enter ordinary discovery before a valid import.
      and not exists (
        select 1 from public.weekly_exceptional_pay_target_families family
        where family.root_timesheet_id=any(candidate.family_ids)
          and family.ownership_state='TARGET_MANAGED'
      )
    order by candidate.timesheet_id
  ),
  command as materialized (
    select jsonb_build_array(jsonb_build_object(
      'command_type','GENERATE_SELECTED',
      'source_ids',coalesce(
        jsonb_agg(source.timesheet_id order by source.timesheet_id),
        '[]'::jsonb
      ),
      'allow_early',coalesce(p_allow_early,false),
      'scope_keys',case
        when v_scope_keys is null then null
        else to_jsonb(v_scope_keys)
      end
    )) commands
    from source_candidates source
  ),
  groups as materialized (
    select resolved.*
    from command
    cross join anchor
    cross join lateral private._invoice_generation_resolve_command_groups(
      command.commands,
      null,
      anchor.evaluation_utc
    ) resolved
    where v_scope_keys is null
       or resolved.group_key=any(v_scope_keys)
  ),
  group_sources as materialized (
    select
      group_row.*,
      member.value member,
      case
        when coalesce(member.value->>'source_id','')~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
          then (member.value->>'source_id')::uuid
      end source_id,
      case
        when coalesce(
          member.value->>'related_timesheet_id',
          member.value->>'source_id',
          ''
        )~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
          then coalesce(
            member.value->>'related_timesheet_id',
            member.value->>'source_id'
          )::uuid
      end timesheet_id,
      nullif(member.value->>'segment_id','') segment_id
    from groups group_row
    cross join lateral jsonb_array_elements(
      group_row.canonical_source_members
    ) member(value)
  ),
  vat_policy as materialized (
    select policy.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',source.member->>'source_member_key',
        'source_type',source.member->>'source_type',
        'source_id',source.source_id,
        'timesheet_id',source.member->>'related_timesheet_id',
        'segment_id',source.segment_id,
        'effective_date',source.effective_settings_date
      ) order by
        source.group_key,
        source.member->>'source_member_key'
      )
      from group_sources source
    ),'[]'::jsonb)) policy
  ),
  reference_policy as materialized (
    select policy.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',source.member->>'source_member_key',
        'source_type',source.member->>'source_type',
        'source_id',source.source_id,
        'related_timesheet_id',source.timesheet_id,
        'segment_id',source.segment_id,
        'target_invoice_week',source.target_invoice_week,
        'invoice_stream',source.invoice_stream,
        'consolidation_mode',source.consolidation_mode
      ) order by
        source.group_key,
        source.member->>'source_member_key'
      )
      from group_sources source
    ),'[]'::jsonb)) policy
  ),
  correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generate-candidate:'||group_row.group_key,
      'scope_key',group_row.group_key,
      'validation_purpose','CANDIDATE_GENERATION',
      'expected_client_id',group_row.client_id,
      'expected_contract_id',case
        when cardinality(group_row.contract_ids)=1
          then group_row.contract_ids[1]
      end,
      'natural_source_week',case
        when cardinality(group_row.natural_source_weeks)=1
          then group_row.natural_source_weeks[1]
      end,
      'target_invoice_week',group_row.target_invoice_week,
      'expected_invoice_stream',group_row.invoice_stream,
      'planned_members',coalesce((
        select jsonb_agg(jsonb_build_object(
          'timesheet_id',source.timesheet_id,
          'source_type',source.member->>'source_type',
          'source_id',source.source_id,
          'source_member_key',source.member->>'source_member_key',
          'segment_id',source.segment_id,
          'target_invoice_week',source.target_invoice_week,
          'vat_rate_pct',vat.vat_rate
        ) order by source.member->>'source_member_key')
        from group_sources source
        left join vat_policy vat
          on vat.source_member_key=
            source.member->>'source_member_key'
        where source.group_key=group_row.group_key
      ),'[]'::jsonb)
    ) order by group_row.group_key),'[]'::jsonb) scopes
    from groups group_row
  ),
  correction_validation as materialized (
    select validation.*
    from correction_scopes scope
    cross join lateral private._invoice_correction_validate_batch(
      scope.scopes,
      (select today from anchor)
    ) validation
  ),
  correction_group_results as materialized (
    select
      validation.scope_key group_key,
      validation.valid,
      validation.blocker_code,
      validation.blocker_codes,
      validation.detail_json details
    from correction_validation validation
  ),
  independent_member_blockers as materialized (
    select
      source.group_key,
      source.member->>'source_member_key' source_member_key,
      blocker.code blocker_code,
      blocker.ordinality blocker_order
    from group_sources source
    left join public.timesheets timesheet
      on timesheet.timesheet_id=source.timesheet_id
     and timesheet.is_current
    left join public.timesheets_financials financial
      on financial.timesheet_id=source.timesheet_id
     and financial.is_current
    left join public.v_ts_invoice_precheck precheck
      on precheck.timesheet_id=source.timesheet_id
    left join reference_policy reference
      on reference.source_member_key=
        source.member->>'source_member_key'
    left join vat_policy vat
      on vat.source_member_key=source.member->>'source_member_key'
    cross join lateral unnest(array_remove(array[
      case
        when timesheet.timesheet_id is null
          then 'TIMESHEET_NOT_CURRENT'
      end,
      case
        when financial.timesheet_id is null
          then 'CURRENT_FINANCIALS_MISSING'
      end,
      case
        when coalesce(financial.is_stale,true)
          then 'FINANCIALS_STALE'
      end,
      case
        when coalesce(financial.processing_status::text,'')
          <>'READY_FOR_INVOICE'
          then 'NOT_READY_FOR_INVOICE'
      end,
      case
        when coalesce(financial.has_rate_issue,false)
          then 'RATE_MISSING'
      end,
      case
        when coalesce(financial.has_pay_channel_issue,false)
          then 'PAY_CHANNEL_MISSING'
      end,
      case
        when financial.locked_by_invoice_id is not null
          then 'SOURCE_ALREADY_LOCKED'
      end,
      case
        when upper(coalesce(timesheet.submission_mode::text,''))='QR'
         and (
           nullif(timesheet.qr_signed_hash,'') is null
           or timesheet.qr_signed_at_utc is null
         )
          then 'QR_TIMESHEET_UNSIGNED'
      end,
      case
        when coalesce(precheck.require_reference_to_invoice,false)
         and coalesce(financial.total_hours,0)>0
         and coalesce(reference.reference_ready,false) is not true
          then coalesce(reference.blocker_code,'MISSING_REFERENCE')
      end,
      case
        when (
          coalesce(financial.mileage_pay_ex_vat,0)<>0
          or coalesce(financial.mileage_charge_ex_vat,0)<>0
        )
        and not exists(
          select 1
          from public.timesheet_evidence evidence
          where evidence.timesheet_id=source.timesheet_id
            and upper(coalesce(evidence.kind,''))='MILEAGE'
            and nullif(evidence.storage_key,'') is not null
        )
          then 'MISSING_MILEAGE_EVIDENCE'
      end,
      case
        when (
          coalesce(financial.expenses_pay_ex_vat,0)<>0
          or coalesce(financial.expenses_charge_ex_vat,0)<>0
          or coalesce(financial.travel_pay_ex_vat,0)<>0
          or coalesce(financial.travel_charge_ex_vat,0)<>0
          or coalesce(financial.accommodation_pay_ex_vat,0)<>0
          or coalesce(financial.accommodation_charge_ex_vat,0)<>0
        )
        and not exists(
          select 1
          from public.timesheet_evidence evidence
          where evidence.timesheet_id=source.timesheet_id
            and upper(coalesce(evidence.kind,'')) in(
              'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES'
            )
            and nullif(evidence.storage_key,'') is not null
        )
          then 'MISSING_EXPENSE_EVIDENCE'
      end,
      case
        when exists(
          select 1
          from public.timesheet_evidence evidence
          join public.invoice_document_assets asset
            on asset.id=evidence.document_asset_id
          where evidence.timesheet_id=source.timesheet_id
            and asset.status in(
              'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED'
            )
        )
          then 'REQUIRED_ASSET_PERMANENT_FAILURE'
      end,
      case
        when coalesce(vat.valid,false) is not true
          then coalesce(vat.blocker_code,'VAT_POLICY_UNRESOLVED')
      end,
      case
        when exists(
          select 1
          from public.invoice_lines line
          join public.invoices invoice on invoice.id=line.invoice_id
          where line.timesheet_id=source.timesheet_id
            and invoice.status in('DRAFT','ISSUED','ON_HOLD')
            and coalesce(
              financial.invoice_breakdown_json->>'mode',
              ''
            )<>'SEGMENTS'
        )
          then 'SOURCE_ALREADY_INVOICED'
      end
    ],null)) with ordinality blocker(code,ordinality)
  ),
  independent_group_blockers as materialized (
    select
      blocker.group_key,
      (
        array_agg(
          blocker.blocker_code
          order by blocker.source_member_key,blocker.blocker_order
        )
      )[1] blocker_code,
      jsonb_build_object(
        'code',(
          array_agg(
            blocker.blocker_code
            order by blocker.source_member_key,blocker.blocker_order
          )
        )[1],
        'sources',jsonb_agg(jsonb_build_object(
          'source_member_key',blocker.source_member_key,
          'code',blocker.blocker_code
        ) order by blocker.source_member_key,blocker.blocker_order)
      ) blocker_detail
    from independent_member_blockers blocker
    group by blocker.group_key
  ),
  selected_member_totals as materialized (
    select
      source.group_key,
      source.member->>'source_member_key' source_member_key,
      source.timesheet_id,
      source.segment_id,
      round(case
        when source.segment_id is not null then coalesce((
          select sum(case
            when coalesce(segment.value->>'charge_amount','')~
              '^[+-]?[0-9]+([.][0-9]+)?$'
              then (segment.value->>'charge_amount')::numeric
            when coalesce(segment.value->>'charge_ex_vat','')~
              '^[+-]?[0-9]+([.][0-9]+)?$'
              then (segment.value->>'charge_ex_vat')::numeric
            else 0
          end)
          from jsonb_array_elements(
            case
              when jsonb_typeof(
                financial.invoice_breakdown_json->'segments'
              )='array'
                then financial.invoice_breakdown_json->'segments'
              else '[]'::jsonb
            end
          ) segment(value)
          where coalesce(
            nullif(segment.value->>'segment_id',''),
            left(
              encode(
                digest(segment.value::text,'sha256'),
                'hex'
              ),
              24
            )
          )=source.segment_id
        ),0)
        else coalesce(financial.total_charge_ex_vat,0)
      end,2) total_charge_ex_vat,
      round(case
        when source.segment_id is not null then coalesce((
          select sum(
            case
              when coalesce(segment.value->>'hours_day','')~
                '^[+-]?[0-9]+([.][0-9]+)?$'
                then (segment.value->>'hours_day')::numeric
              else 0
            end
            +case
              when coalesce(segment.value->>'hours_night','')~
                '^[+-]?[0-9]+([.][0-9]+)?$'
                then (segment.value->>'hours_night')::numeric
              else 0
            end
            +case
              when coalesce(segment.value->>'hours_sat','')~
                '^[+-]?[0-9]+([.][0-9]+)?$'
                then (segment.value->>'hours_sat')::numeric
              else 0
            end
            +case
              when coalesce(segment.value->>'hours_sun','')~
                '^[+-]?[0-9]+([.][0-9]+)?$'
                then (segment.value->>'hours_sun')::numeric
              else 0
            end
            +case
              when coalesce(segment.value->>'hours_bh','')~
                '^[+-]?[0-9]+([.][0-9]+)?$'
                then (segment.value->>'hours_bh')::numeric
              else 0
            end
          )
          from jsonb_array_elements(
            case
              when jsonb_typeof(
                financial.invoice_breakdown_json->'segments'
              )='array'
                then financial.invoice_breakdown_json->'segments'
              else '[]'::jsonb
            end
          ) segment(value)
          where coalesce(
            nullif(segment.value->>'segment_id',''),
            left(
              encode(
                digest(segment.value::text,'sha256'),
                'hex'
              ),
              24
            )
          )=source.segment_id
        ),0)
        else coalesce(financial.total_hours,0)
      end,2) total_hours
    from group_sources source
    join public.timesheets_financials financial
      on financial.timesheet_id=source.timesheet_id
     and financial.is_current
  ),
  generation_totals as materialized (
    select
      source.group_key,
      round(coalesce(sum(total.total_charge_ex_vat),0),2)
        total_ex_vat,
      round(coalesce(sum(round(
        total.total_charge_ex_vat*coalesce(vat.vat_rate,0)/100,
        2
      )),0),2) vat_amount,
      round(coalesce(sum(total.total_hours),0),2) total_hours
    from group_sources source
    join selected_member_totals total
      on total.group_key=source.group_key
     and total.source_member_key=
       source.member->>'source_member_key'
    left join vat_policy vat
      on vat.source_member_key=source.member->>'source_member_key'
    group by source.group_key
  ),
  timesheet_totals as materialized (
    select
      total.group_key,
      total.timesheet_id,
      round(sum(total.total_charge_ex_vat),2) total_charge_ex_vat,
      round(sum(total.total_hours),2) total_hours
    from selected_member_totals total
    group by total.group_key,total.timesheet_id
  ),
  source_display as materialized (
    select distinct
      source.group_key,
      financial.timesheet_id,
      financial.client_id,
      financial.candidate_id,
      timesheet.week_ending_date,
      timesheet.submission_mode,
      financial.basis,
      total.total_charge_ex_vat,
      total.total_hours,
      summary.client_name,
      summary.candidate_name,
      summary.validation_status,
      coalesce(
        summary.hr_validation_required_for_invoice,
        false
      ) hr_validation_required_for_invoice,
      coalesce(
        summary.hr_validation_required_for_invoice,
        false
      )
      and (
        summary.validation_status is null
        or summary.validation_status<>all(array[
          'VALIDATION_OK'::public.validation_status_enum,
          'OVERRIDDEN'::public.validation_status_enum
        ])
      ) blocked_by_hr_validation,
      precheck.precheck_status,
      exists(
        select 1
        from public.timesheet_evidence evidence
        left join public.invoice_document_assets asset
          on asset.id=evidence.document_asset_id
        where evidence.timesheet_id=financial.timesheet_id
          and evidence.processing_state not in('SUPERSEDED')
          and (asset.id is null or asset.status<>'READY')
      ) unready_evidence_asset,
      exists(
        select 1
        from public.invoice_document_versions version
        where version.entity_type='TIMESHEET'
          and version.entity_id=financial.timesheet_id
          and version.purpose='TIMESHEET'
          and version.source_revision=timesheet.document_revision::text
          and version.status='READY'
          and version.r2_key is not null
          and version.sha256~'^[0-9a-f]{64}$'
          and coalesce(version.size_bytes,0)>0
          and coalesce(version.page_count,0)>0
      ) timesheet_document_ready,
      timesheet.document_revision,
      timesheet.document_state,
      timesheet.current_document_version_id
    from group_sources source
    join public.timesheets_financials financial
      on financial.timesheet_id=source.timesheet_id
     and financial.is_current
    join public.timesheets timesheet
      on timesheet.timesheet_id=financial.timesheet_id
     and timesheet.is_current
    join timesheet_totals total
      on total.group_key=source.group_key
     and total.timesheet_id=source.timesheet_id
    join public.v_ts_invoice_precheck precheck
      on precheck.timesheet_id=financial.timesheet_id
    left join public.v_timesheets_summary_base summary
      on summary.timesheet_id=financial.timesheet_id
  ),
  active_exact as materialized (
    select distinct on(
      chunk.payload_json->>'group_key',
      chunk.payload_json->>'source_revision'
    )
      chunk.payload_json->>'group_key' group_key,
      operation.id operation_id,
      operation.status,
      chunk.payload_json->>'source_revision' source_revision,
      operation.progress_json,
      operation.error_json,
      operation.updated_at_utc
    from public.invoice_operation_chunks chunk
    join public.invoice_operations operation
      on operation.id=chunk.operation_id
    where chunk.chunk_type='GENERATION_GROUP'
      and chunk.status in(
        'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
      )
      and operation.status in(
        'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
      )
      and coalesce(
        chunk.payload_json->>'is_selection_expander',
        'false'
      )<>'true'
      and (not chunk.is_manifest_member or chunk.manifest_committed)
      and (
        not chunk.is_manifest_member
        or coalesce(chunk.entity_type,'')<>'OPERATION'
      )
    order by
      chunk.payload_json->>'group_key',
      chunk.payload_json->>'source_revision',
      operation.priority desc,
      operation.created_at_utc desc
  ),
  group_classification as materialized (
    select
      group_row.client_id,
      group_row.group_key,
      group_row.target_invoice_week,
      group_row.consolidation_mode,
      group_row.invoice_stream,
      group_row.source_revision_hash,
      group_row.canonical_source_ids,
      group_row.canonical_source_members,
      totals.total_ex_vat,
      totals.vat_amount,
      totals.total_hours,
      coalesce(jsonb_agg(
        distinct to_jsonb(display.candidate_id)
        order by to_jsonb(display.candidate_id)
      )
        filter(where display.candidate_id is not null),'[]'::jsonb)
        candidate_ids,
      coalesce(jsonb_agg(
        distinct to_jsonb(display.candidate_name)
        order by to_jsonb(display.candidate_name)
      )
        filter(where nullif(display.candidate_name,'') is not null),
        '[]'::jsonb) candidate_names,
      coalesce(jsonb_agg(distinct to_jsonb(display.week_ending_date)
        order by to_jsonb(display.week_ending_date))
        filter(where display.week_ending_date is not null),
        '[]'::jsonb) week_ending_dates,
      max(display.week_ending_date) week_ending_date,
      case
        when group_row.blocker_code is not null
          then group_row.blocker_code
        when independent.blocker_code is not null
          then independent.blocker_code
        when coalesce(correction.valid,true) is not true
          then coalesce(
            correction.blocker_code,
            'INVOICE_CORRECTION_UNIT_INVALID'
          )
        when bool_or(display.blocked_by_hr_validation)
          then 'HR_VALIDATION_BLOCKED'
        when not coalesce(p_allow_early,false)
         and exists(
           select 1
           from jsonb_array_elements(
             group_row.canonical_source_members
           ) early(value)
           where case
             when pg_input_is_valid(
               coalesce(early.value->>'target_invoice_week',''),
               'date'
             )
               then (
                 early.value->>'target_invoice_week'
               )::date+6 >= (select today from anchor)
             else false
           end
         )
          then 'EARLY_GENERATION_NOT_ALLOWED'
      end blocker_code,
      case
        when group_row.blocker_code is not null
          then group_row.blocker_detail
        when independent.blocker_code is not null
          then independent.blocker_detail
        when coalesce(correction.valid,true) is not true
          then jsonb_build_object(
            'code',coalesce(
              correction.blocker_code,
              'INVOICE_CORRECTION_UNIT_INVALID'
            ),
            'correction_validation',correction.details
          )
        when bool_or(display.blocked_by_hr_validation)
          then jsonb_build_object(
            'code','HR_VALIDATION_BLOCKED',
            'sources',coalesce(
              jsonb_agg(display.timesheet_id order by display.timesheet_id)
                filter(where display.blocked_by_hr_validation),
              '[]'::jsonb
            )
          )
        when not coalesce(p_allow_early,false)
         and exists(
           select 1
           from jsonb_array_elements(
             group_row.canonical_source_members
           ) early(value)
           where case
             when pg_input_is_valid(
               coalesce(early.value->>'target_invoice_week',''),
               'date'
             )
               then (
                 early.value->>'target_invoice_week'
               )::date+6 >= (select today from anchor)
             else false
           end
         )
          then jsonb_build_object(
            'code','EARLY_GENERATION_NOT_ALLOWED'
          )
      end blocker_detail,
      active.operation_id active_operation_id,
      active.status active_status,
      active.progress_json active_progress,
      active.error_json active_error,
      coalesce(correction.details,'[]'::jsonb)
        correction_validation,
      jsonb_agg(jsonb_build_object(
        'timesheet_id',display.timesheet_id,
        'candidate_name',display.candidate_name,
        'week_ending_date',display.week_ending_date,
        'total_charge_ex_vat',display.total_charge_ex_vat,
        'total_hours',display.total_hours,
        'basis',display.basis::text,
        'submission_mode',coalesce(display.submission_mode::text,''),
        'validation_status',coalesce(display.validation_status::text,''),
        'hr_validation_required_for_invoice',
          display.hr_validation_required_for_invoice,
        'blocked_by_hr_validation',display.blocked_by_hr_validation,
        'precheck_status',coalesce(display.precheck_status::text,''),
        'document_revision',display.document_revision,
        'document_state',display.document_state,
        'current_document_version_id',
          display.current_document_version_id,
        'timesheet_document_ready',
          display.timesheet_document_ready,
        'unready_evidence_asset',display.unready_evidence_asset
      ) order by
        display.candidate_name nulls last,
        display.timesheet_id
      ) timesheet_projection
    from groups group_row
    join generation_totals totals
      on totals.group_key=group_row.group_key
    join source_display display
      on display.group_key=group_row.group_key
    left join independent_group_blockers independent
      on independent.group_key=group_row.group_key
    left join correction_group_results correction
      on correction.group_key=group_row.group_key
    left join active_exact active
      on active.group_key=group_row.group_key
     and active.source_revision=group_row.source_revision_hash
    group by
      group_row.client_id,
      group_row.group_key,
      group_row.target_invoice_week,
      group_row.consolidation_mode,
      group_row.invoice_stream,
      group_row.source_revision_hash,
      group_row.canonical_source_ids,
      group_row.canonical_source_members,
      group_row.blocker_code,
      group_row.blocker_detail,
      totals.total_ex_vat,
      totals.vat_amount,
      totals.total_hours,
      independent.blocker_code,
      independent.blocker_detail,
      correction.valid,
      correction.blocker_code,
      correction.details,
      active.operation_id,
      active.status,
      active.progress_json,
      active.error_json
  ),
  create_rows as materialized (
    select
      'generate:'||classification.group_key selection_key,
      jsonb_build_object(
        'selection_key','generate:'||classification.group_key,
        'row_kind','CREATE_INVOICE',
        'scope_key',classification.group_key,
        'invoice_id',null,
        'client_id',classification.client_id,
        'client_name',client.name,
        'candidate_ids',classification.candidate_ids,
        'candidate_names',classification.candidate_names,
        'candidate_display',case
          when jsonb_array_length(classification.candidate_names)=1
            then classification.candidate_names->>0
          when jsonb_array_length(classification.candidate_names)>1
            then 'Multiple candidates ('||
              jsonb_array_length(classification.candidate_names)::text||
              ')'
          else 'Unknown candidate'
        end,
        'week_ending_dates',classification.week_ending_dates,
        'week_ending_date',classification.week_ending_date,
        'currency','GBP',
        'invoice_stream',upper(coalesce(
          nullif(classification.invoice_stream,''),
          'NORMAL'
        )),
        'total_ex_vat',round(classification.total_ex_vat,2),
        'vat_amount',round(classification.vat_amount,2),
        'total_inc_vat',round(
          classification.total_ex_vat+classification.vat_amount,
          2
        ),
        'generation_state','NOT_GENERATED',
        'primary_blocker_code',classification.blocker_code,
        'action_blocker_codes',coalesce((
          select jsonb_agg(to_jsonb(code) order by first_order,code)
          from (
            select code,min(code_order) first_order
            from (
              select
                1 code_order,
                nullif(classification.blocker_code,'') code
              union all
              select
                2,
                nullif(classification.blocker_detail->>'code','')
              union all
              select
                100+source.ordinality::integer,
                nullif(source.value->>'code','')
              from jsonb_array_elements(
                case
                  when jsonb_typeof(
                    classification.blocker_detail->'sources'
                  )='array'
                    then classification.blocker_detail->'sources'
                  else '[]'::jsonb
                end
              ) with ordinality source(value,ordinality)
            ) raw_code
            where code is not null
              and code not in(
                'EARLY_GENERATION_NOT_ALLOWED',
                'SOURCE_ALREADY_INVOICED'
              )
            group by code
          ) code_row
        ),'[]'::jsonb),
        'informational_codes',case
          when classification.active_status in(
            'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
          )
            then jsonb_build_array('GENERATING')
          else '[]'::jsonb
        end,
        'is_active',classification.active_status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
        ),
        'active_operation_id',classification.active_operation_id,
        'active_operation_status',classification.active_status,
        'source_revision',classification.source_revision_hash,
        'document_revision',null,
        'command_payload',jsonb_build_object(
          'command_type','GENERATE_SELECTED',
          'canonical_source_ids',
            to_jsonb(classification.canonical_source_ids),
          'canonical_source_members',
            classification.canonical_source_members,
          'group_key',classification.group_key,
          'source_revision',classification.source_revision_hash,
          'target_invoice_week',classification.target_invoice_week,
          'consolidation_mode',classification.consolidation_mode,
          'invoice_stream',classification.invoice_stream,
          'correction_validation',
            classification.correction_validation,
          'allow_early',coalesce(p_allow_early,false)
        ),
        'is_early',coalesce(
          classification.week_ending_date
            >=(select today from anchor),
          false
        ),
        'selectable',
          jsonb_array_length(coalesce((
            select jsonb_agg(to_jsonb(code))
            from (
              select distinct code
              from (
                select nullif(classification.blocker_code,'') code
                union all
                select nullif(
                  classification.blocker_detail->>'code',
                  ''
                )
              ) code_source
              where code is not null
                and code not in(
                  'EARLY_GENERATION_NOT_ALLOWED',
                  'SOURCE_ALREADY_INVOICED'
                )
            ) blocking
          ),'[]'::jsonb))=0
          and classification.active_status is null,
        'row_status',case
          when classification.blocker_code is not null
           and classification.blocker_code not in(
             'EARLY_GENERATION_NOT_ALLOWED',
             'SOURCE_ALREADY_INVOICED'
           )
            then 'BLOCKED'
          when classification.active_status in(
            'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
          )
            then 'IN_PROGRESS'
          else 'READY'
        end,
        '_private',jsonb_build_object(
          'canonical_source_ids',
            to_jsonb(classification.canonical_source_ids),
          'canonical_source_members',
            classification.canonical_source_members,
          'target_invoice_week',classification.target_invoice_week,
          'consolidation_mode',classification.consolidation_mode,
          'correction_validation',
            classification.correction_validation,
          'blocker_detail',classification.blocker_detail,
          'total_hours',classification.total_hours,
          'timesheets',classification.timesheet_projection,
          'active_progress',classification.active_progress,
          'active_error',classification.active_error
        )
      ) candidate_json
    from group_classification classification
    join public.clients client on client.id=classification.client_id
    where coalesce(classification.blocker_code,'')
      not in('SOURCE_ALREADY_INVOICED','EARLY_GENERATION_NOT_ALLOWED')
  ),
  stale_invoice_timesheets as materialized (
    select
      line.invoice_id,
      coalesce(jsonb_agg(
        distinct to_jsonb(summary.candidate_id)
        order by to_jsonb(summary.candidate_id)
      )
        filter(where summary.candidate_id is not null),'[]'::jsonb)
        candidate_ids,
      coalesce(jsonb_agg(
        distinct to_jsonb(summary.candidate_name)
        order by to_jsonb(summary.candidate_name)
      )
        filter(where nullif(summary.candidate_name,'') is not null),
        '[]'::jsonb) candidate_names,
      coalesce(jsonb_agg(
        distinct to_jsonb(summary.week_ending_date)
        order by to_jsonb(summary.week_ending_date)
      )
        filter(where summary.week_ending_date is not null),
        '[]'::jsonb) week_ending_dates,
      min(summary.week_ending_date) min_week_ending,
      max(summary.week_ending_date) max_week_ending
    from public.invoice_lines line
    left join public.v_timesheets_summary_base summary
      on summary.timesheet_id=line.timesheet_id
    group by line.invoice_id
  ),
  stale_rows as materialized (
    select
      'invoice:'||invoice.id::text selection_key,
      jsonb_build_object(
        'selection_key','invoice:'||invoice.id::text,
        'row_kind',case
          when coalesce(invoice.document_state,'')='FAILED'
            then 'RETRY_GENERATION'
          else 'REGENERATE_DRAFT'
        end,
        'scope_key',invoice.id::text,
        'invoice_id',invoice.id,
        'client_id',invoice.client_id,
        'client_name',client.name,
        'candidate_ids',coalesce(
          timesheet.candidate_ids,
          '[]'::jsonb
        ),
        'candidate_names',coalesce(
          timesheet.candidate_names,
          '[]'::jsonb
        ),
        'candidate_display',case
          when jsonb_array_length(coalesce(
            timesheet.candidate_names,
            '[]'::jsonb
          ))=1
            then timesheet.candidate_names->>0
          when jsonb_array_length(coalesce(
            timesheet.candidate_names,
            '[]'::jsonb
          ))>1
            then 'Multiple candidates ('||
              jsonb_array_length(timesheet.candidate_names)::text||
              ')'
          else 'Unknown candidate'
        end,
        'week_ending_dates',coalesce(
          timesheet.week_ending_dates,
          '[]'::jsonb
        ),
        'week_ending_date',coalesce(
          timesheet.min_week_ending,
          case
            when pg_input_is_valid(
              invoice.header_snapshot_json#>>'{meta,invoice_week_start}',
              'date'
            )
              then (
                invoice.header_snapshot_json#>>
                  '{meta,invoice_week_start}'
              )::date+6
          end
        ),
        'currency',coalesce(
          nullif(
            invoice.header_snapshot_json#>>'{meta,currency}',
            ''
          ),
          nullif(invoice.header_snapshot_json->>'currency',''),
          'GBP'
        ),
        'invoice_stream',upper(coalesce(
          nullif(
            invoice.header_snapshot_json#>>'{meta,invoice_stream}',
            ''
          ),
          nullif(invoice.header_snapshot_json->>'invoice_stream',''),
          case
            when lower(coalesce(
              invoice.header_snapshot_json#>>'{meta,self_bill}',
              invoice.header_snapshot_json->>'self_bill',
              'false'
            )) in('true','t','1','yes')
              then 'SELF_BILL'
          end,
          'NORMAL'
        )),
        'total_ex_vat',round(coalesce(invoice.subtotal_ex_vat,0),2),
        'vat_amount',round(coalesce(invoice.vat_amount,0),2),
        'total_inc_vat',round(coalesce(
          invoice.total_inc_vat,
          coalesce(invoice.subtotal_ex_vat,0)
            +coalesce(invoice.vat_amount,0)
        ),2),
        'generation_state',case
          when coalesce(invoice.document_state,'')='FAILED'
            then 'FAILED'
          when exists(
            select 1
            from public.invoice_document_versions version
            where version.entity_type='INVOICE'
              and version.entity_id=invoice.id
              and version.purpose='DRAFT_PREVIEW'
          )
            then 'STALE'
          else 'NOT_GENERATED'
        end,
        'primary_blocker_code',null,
        'action_blocker_codes','[]'::jsonb,
        'informational_codes',case
          when active.status in(
            'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
          )
            then jsonb_build_array('GENERATING')
          when exists(
            select 1
            from public.invoice_document_versions version
            where version.entity_type='INVOICE'
              and version.entity_id=invoice.id
              and version.purpose='DRAFT_PREVIEW'
          )
            then jsonb_build_array('STALE')
          else jsonb_build_array('NOT_GENERATED')
        end,
        'is_active',active.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
        ),
        'active_operation_id',active.operation_id,
        'active_operation_status',active.status,
        'source_revision',invoice.document_revision::text,
        'document_revision',invoice.document_revision::text,
        'command_payload',jsonb_build_object(
          'command_type','VIEW_INVOICE_DOCUMENT',
          'invoice_id',invoice.id,
          'purpose','DRAFT_PREVIEW',
          'expected_revision',invoice.document_revision,
          'source_revision',invoice.document_revision::text
        ),
        'is_early',coalesce(
          timesheet.max_week_ending,
          case
            when pg_input_is_valid(
              invoice.header_snapshot_json#>>
                '{meta,invoice_week_start}',
              'date'
            )
              then (
                invoice.header_snapshot_json#>>
                  '{meta,invoice_week_start}'
              )::date+6
          end
        ) >= (select today from anchor),
        'selectable',active.operation_id is null,
        'row_status',case
          when active.status in(
            'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
          )
            then 'IN_PROGRESS'
          when coalesce(invoice.document_state,'')='FAILED'
            then 'FAILED'
          when exists(
            select 1
            from public.invoice_document_versions version
            where version.entity_type='INVOICE'
              and version.entity_id=invoice.id
              and version.purpose='DRAFT_PREVIEW'
          )
            then 'STALE'
          else 'READY'
        end,
        '_private','{}'::jsonb
      ) candidate_json
    from public.invoices invoice
    join public.clients client on client.id=invoice.client_id
    left join stale_invoice_timesheets timesheet
      on timesheet.invoice_id=invoice.id
    left join lateral (
      select
        operation.id operation_id,
        operation.status
      from public.invoice_operations operation
      where operation.operation_type='BUILD_DOCUMENT'
        and operation.entity_type='INVOICE'
        and operation.entity_id=invoice.id
        and operation.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'
        )
      order by
        operation.created_at_utc desc,
        operation.id desc
      limit 1
    ) active on true
    where invoice.type::text='INVOICE'
      and invoice.status::text in('DRAFT','ON_HOLD')
      and coalesce(invoice.document_revision,0)>0
      and (
        v_scope_keys is null
        or invoice.id::text=any(v_scope_keys)
      )
      and not exists(
        select 1
        from public.invoice_document_versions version
        where version.entity_type='INVOICE'
          and version.entity_id=invoice.id
          and version.purpose='DRAFT_PREVIEW'
          and version.source_revision=invoice.document_revision::text
          and version.template_version='invoice-professional-v2'
          and version.status='READY'
          and version.r2_key is not null
          and version.sha256~'^[0-9a-f]{64}$'
          and coalesce(version.size_bytes,0)>0
          and coalesce(version.page_count,0)>0
      )
  )
  select create_row.selection_key,create_row.candidate_json
  from create_rows create_row
  union all
  select stale_row.selection_key,stale_row.candidate_json
  from stale_rows stale_row
  order by selection_key;
end;
$function$;

alter function private._invoice_batch_generate_classification_v2(
  boolean,text[],timestamptz
) OWNER TO CURRENT_USER;
revoke all on function private._invoice_batch_generate_classification_v2(
  boolean,text[],timestamptz
) from public,anon,authenticated;
grant execute on function private._invoice_batch_generate_classification_v2(
  boolean,text[],timestamptz
) to service_role;

-- CONTACT_PREPARER_UNIT 24 repeatable supabase/repeatable/15092026_1534_weekly_source_query_delivery_v1.sql SHA256 11f6b61a855cd89b5a764915875b6b038c3915ead30fd9ce05faa00761828309
-- Repeatable CloudTMS authority: weekly_source_query_delivery_v1
--
-- Owns only the non-financial Weekly source discrepancy, outreach, deterministic
-- message-outbox, manager-review and Office-notice lifecycles. It deliberately
-- contains no provider call and cannot write Timesheet finance, pay, Workbench,
-- Banking Pay, invoice or source-finalisation state.





-- Compile the real qualified-coverage helpers before their SQL callers.
-- Canonical transaction-neutral qualified-coverage definitions.
-- Included inside each owning repeatable's atomic transaction, before SQL
-- readers are parsed. One body authority; no financial/release transitions.

-- Factual admission only. No reader locks, monetary hold, zero entitlement,
-- financial write, invoice change or present-day recheck of a retained Draft.
create or replace function private.weekly_source_pay_query_facts_v1(p_root_timesheet_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_scope jsonb; v_manual jsonb; v_hours jsonb:='[]'::jsonb;
  v_blocked boolean:=false; v_unavailable boolean:=false;
  v_row record; v_latest public.weekly_exceptional_pay_family_events%rowtype;
  v_generation uuid; v_count integer; v_approval_run uuid;
  v_invalid_wait_audit boolean;
  v_local_count integer; v_c1_count integer; v_next_count integer; v_audit_count integer;
  v_local jsonb; v_c1 jsonb; v_next jsonb; v_receipt jsonb; v_exception jsonb;
  v_state jsonb; v_digest bytea;
begin
  if p_root_timesheet_id is null then
    raise exception 'WEEKLY_SOURCE_PAY_QUERY_ROOT_REQUIRED' using errcode='22023'; end if;
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_timesheet_id);
  if v_scope is null then
    return jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_PAY_QUERY_SCOPE_UNAVAILABLE',
      'scope',null,'blocked',null,'query_state_sha256',null); end if;

  -- Work membership is the actual configured root week, across every owning
  -- report cutoff. Never substitute a Sunday or the report's cutoff period.
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'source_group_id',r.source_group_id,
    'source_cycle_id',r.source_cycle_id,'work_event_id',r.work_event_id,
    'candidate_id',r.candidate_id,'client_id',r.client_id,'contract_id',r.contract_id,
    'work_date',to_char(r.work_date,'YYYY-MM-DD'),'state',r.state) order by r.id),'[]'::jsonb),
    coalesce(bool_or(e.id is null or e.candidate_id is distinct from r.candidate_id
      or e.client_id is distinct from r.client_id or e.work_date is distinct from r.work_date
      or c.source_group_id is distinct from r.source_group_id),false)
  into v_manual,v_unavailable
  from private.weekly_source_manual_reviews r
  left join public.weekly_work_events e on e.id=r.work_event_id
  left join public.weekly_source_cycles c on c.id=r.source_cycle_id
  where r.state='OPEN' and r.candidate_id=(v_scope->>'candidate_id')::uuid
    and r.client_id=(v_scope->>'client_id')::uuid and r.contract_id=(v_scope->>'contract_id')::uuid
    and r.work_date between (v_scope->>'week_ending_date')::date-6 and (v_scope->>'week_ending_date')::date;
  v_blocked:=jsonb_array_length(v_manual)>0;

  for v_row in
    select i.*,e.work_date,e.candidate_id as event_candidate_id,e.client_id as event_client_id,
      x.id as comparison_id,x.incident_id as comparison_incident_id,x.contract_id as comparison_contract_id,
      owning.id as owning_comparison_id,owning.contract_id as owning_contract_id,
      tail.id as tail_comparison_id,
      x.issue_family,encode(x.material_comparison_fingerprint,'hex') as material_fingerprint,
      c.source_group_id as cycle_group_id
    from public.weekly_discrepancy_incidents i
    left join public.weekly_work_events e on e.id=i.work_event_id
    -- These immutable incident-owned revisions establish relevance independently
    -- of the suspect current pointer. The unique incident/revision index bounds
    -- both the first-owner point read and the actual backward-tail probe.
    left join public.weekly_issue_comparison_revisions owning
      on owning.incident_id=i.id and owning.revision_number=1
    left join lateral (select r.id from public.weekly_issue_comparison_revisions r
      where r.incident_id=i.id order by r.revision_number desc limit 1) tail on true
    left join public.weekly_issue_comparison_revisions x on x.id=i.current_comparison_revision_id
    left join public.weekly_source_cycles c on c.id=i.source_cycle_id
    where i.state='OPEN' and i.candidate_id=(v_scope->>'candidate_id')::uuid
      and i.client_id=(v_scope->>'client_id')::uuid
      and (e.work_date is null or e.work_date between
        (v_scope->>'week_ending_date')::date-6 and (v_scope->>'week_ending_date')::date)
      and (owning.contract_id is null or owning.contract_id=(v_scope->>'contract_id')::uuid)
    order by i.id
  loop
    if v_row.work_date is null or v_row.event_candidate_id is distinct from v_row.candidate_id
       or v_row.event_client_id is distinct from v_row.client_id
       or v_row.cycle_group_id is distinct from v_row.source_group_id
       or v_row.owning_comparison_id is null
       or v_row.owning_contract_id is distinct from (v_scope->>'contract_id')::uuid
       or v_row.comparison_id is null or v_row.comparison_incident_id is distinct from v_row.id
       or v_row.comparison_id is distinct from v_row.tail_comparison_id
       or v_row.comparison_contract_id is distinct from (v_scope->>'contract_id')::uuid
       or v_row.issue_family is null or v_row.material_fingerprint is null then
      v_unavailable:=true;
    end if;
    v_exception:=null;
    v_latest:=null;
    if v_scope->>'target_family_id' is not null then
      select e.* into v_latest from public.weekly_exceptional_pay_family_events e
        where e.family_id=(v_scope->>'target_family_id')::uuid
          and e.durable_work_event_id=v_row.work_event_id
        order by e.event_sequence desc limit 1;
    end if;
    if v_latest.id is not null and v_latest.state='WAIT' then
      -- Choose the actual approval's UNIQUE financial target-generation link.
      -- The Wait owner also appends generation-less, money-neutral audit rows
      -- for that same approval. They are not second payment publications, but
      -- must be genuine unchanged-vector WAIT evidence, never arbitrary nulls.
      -- A sibling publication may supersede the original financial generation;
      -- today's current_generation is not the immutable approval's pin.
      select count(*) filter (where t.financial_generation_id is not null),
        (array_agg(t.financial_generation_id) filter (where t.financial_generation_id is not null))[1],
        coalesce(bool_or(t.financial_generation_id is null and (
          t.reason is distinct from 'WAIT'
          or t.resulting_lifecycle_state is distinct from 'WAITING_SOURCE'
          or t.actor_user_id is null
          or t.complete_prior_family_vector_fingerprint is distinct from t.complete_next_family_vector_fingerprint
          or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',
            t.fixed_target_component_snapshot) is distinct from t.complete_next_family_vector_fingerprint
          or jsonb_typeof(t.current_source_proposal_snapshot) is distinct from 'object'
          or t.event_hash is distinct from private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_PROTECTED_TARGET_EVENT_V1',jsonb_build_object(
              'family_id',t.family_id,'event_sequence',t.event_sequence,
              'approval_id',t.approval_id,'generation_id',null,
              'prior_vector_hash',encode(t.complete_prior_family_vector_fingerprint,'hex'),
              'next_vector_hash',encode(t.complete_next_family_vector_fingerprint,'hex'),
              'reason','WAIT','actor_user_id',t.actor_user_id))
        )),false)
        into v_count,v_generation,v_invalid_wait_audit
        from public.weekly_exceptional_pay_target_events t
        where t.family_id=v_latest.family_id and t.approval_id=v_latest.evidence_approval_id;
      if v_latest.evidence_approval_id is null or v_count<>1 or v_generation is null or v_invalid_wait_audit then
        v_unavailable:=true;
      else
        v_local:=private.weekly_source_pay_query_local_receipt_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation);
        v_c1:=private.weekly_source_pay_query_c1_receipt_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation);
        v_next:=private.weekly_source_pay_query_next_receipt_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation);
        v_count:=(v_local is not null)::integer+(v_c1 is not null)::integer+(v_next is not null)::integer;
        select a.creation_orchestration_run_id into v_approval_run
          from public.weekly_exceptional_payment_approvals a where a.id=v_latest.evidence_approval_id;
        -- Count partial evidence too. A local RETIRED request is its audit row,
        -- not a second transport lane; unrelated sibling/history stays excluded.
        select count(*) into v_local_count
          from private.weekly_source_local_protected_decision_receipts l
          join public.weekly_exceptional_c1_publication_requests r on r.id=l.publication_request_id
          where l.generation_id=v_generation or r.orchestration_run_id=v_approval_run;
        select count(*),count(*) filter (where
          (v_local is not null and r.id::text=v_local->>'publication_request_id' and r.state='RETIRED')
          or (v_c1 is not null and r.id::text=v_c1->>'publication_request_id' and r.state='PUBLISHED'))
          into v_c1_count,v_audit_count
          from public.weekly_exceptional_c1_publication_requests r
          where r.generation_id=v_generation or r.orchestration_run_id=v_approval_run;
        select count(*) into v_next_count from private.bpay_next_protected_source_receipt r
          where r.approval_id=v_latest.evidence_approval_id or r.generation_id=v_generation
            or r.orchestration_run_id=v_approval_run;
        if v_count<>1 or v_approval_run is null
           or (v_local is not null and (v_local_count<>1 or v_c1_count<>1 or v_audit_count<>1 or v_next_count<>0))
           or (v_c1 is not null and (v_local_count<>0 or v_c1_count<>1 or v_audit_count<>1 or v_next_count<>0))
           or (v_next is not null and (v_local_count<>0 or v_c1_count<>0 or v_next_count<>1)) then v_unavailable:=true;
        else
          v_receipt:=coalesce(v_local,v_c1,v_next);
          v_exception:=jsonb_build_object('family_id',v_latest.family_id,
            'bound_version',v_scope->>'family_bound_version','event_sequence',v_latest.event_sequence::text,
            'state','WAIT','evidence_approval_id',v_latest.evidence_approval_id,'accepted_receipt',v_receipt);
        end if;
      end if;
    end if;
    if v_row.issue_family is distinct from 'CANDIDATE_TIMESHEET_MISSING' and v_exception is null then
      v_blocked:=true;
    end if;
    v_hours:=v_hours||jsonb_build_array(jsonb_build_object('id',v_row.id,
      'source_group_id',v_row.source_group_id,'source_cycle_id',v_row.source_cycle_id,
      'work_event_id',v_row.work_event_id,'candidate_id',v_row.candidate_id,'client_id',v_row.client_id,
      'state',v_row.state,'work_date',to_char(v_row.work_date,'YYYY-MM-DD'),
      'current_comparison_revision_id',v_row.comparison_id,'comparison_contract_id',v_row.comparison_contract_id,
      'issue_family',v_row.issue_family,'material_comparison_fingerprint',v_row.material_fingerprint,
      'latest_qualified_exception',v_exception));
  end loop;
  if v_unavailable then
    return jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE',
      'scope',v_scope,'blocked',null,'query_state_sha256',null); end if;
  v_state:=jsonb_build_object('schema_version','PAY_QUERY_STATE_V3','scope',v_scope,
    'manual_reviews',v_manual,'hours_incidents',v_hours);
  v_digest:=extensions.digest(convert_to(v_state::text,'UTF8'),'sha256');
  return jsonb_build_object('ok',true,'code','OK','scope',v_scope,'blocked',v_blocked,
    'query_state_sha256',encode(v_digest,'hex'),'hours_incidents',v_hours,'manual_reviews',v_manual);
end;
$function$;
alter function private.weekly_source_pay_query_facts_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_pay_query_facts_v1(uuid) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_covered_hours_incident_v1(p_incident_id uuid)
returns boolean language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_root uuid; v_count integer; v_facts jsonb;
begin
  select count(*),(array_agg(family.root_timesheet_id))[1] into v_count,v_root
  from public.weekly_discrepancy_incidents incident
  join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work on work.id=incident.work_event_id
  join public.weekly_exceptional_pay_target_families family
    on family.candidate_id=incident.candidate_id and family.contract_id=comparison.contract_id
    and work.work_date between family.week_start_date and family.week_ending_date
  join public.contracts contract on contract.id=family.contract_id and contract.client_id=incident.client_id
  where incident.id=p_incident_id and incident.state='OPEN'
    and exists(select 1 from public.weekly_exceptional_pay_family_events event
      where event.family_id=family.id and event.durable_work_event_id=work.id);
  if v_count<>1 or v_root is null then return false; end if;
  v_facts:=private.weekly_source_pay_query_facts_v1(v_root);
  if v_facts->'ok' is distinct from 'true'::jsonb then return false; end if;
  return exists(select 1 from jsonb_array_elements(v_facts->'hours_incidents') item
    where item->>'id'=p_incident_id::text and jsonb_typeof(item->'latest_qualified_exception')='object');
end;
$function$;
alter function private.weekly_source_covered_hours_incident_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_covered_hours_incident_v1(uuid) from public,anon,authenticated,service_role;




create or replace function private.weekly_source_candidate_generation_current_v1(p_generation_id uuid)
returns boolean language sql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
  select exists(select 1 from public.weekly_candidate_outreach_generations generation
    join public.weekly_candidate_cohorts cohort on cohort.id=generation.candidate_cohort_id
    where generation.id=p_generation_id and generation.state='ACTIVE'
      and generation.id=case when generation.request_kind='SUBMIT_TIMESHEET'
        then cohort.current_submission_generation_id else cohort.current_generation_id end);
$function$;

create or replace function private.weekly_source_waiting_requested_week_v1(
  p_cycle_id uuid,p_candidate_id uuid,p_client_id uuid,p_contract_id uuid,p_work_date date
) returns boolean language sql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
  select exists(select 1 from public.weekly_timesheet_submission_requests request
    join public.weekly_timesheet_submission_request_memberships membership on membership.submission_request_id=request.id
    where request.source_cycle_id=p_cycle_id and request.candidate_id=p_candidate_id
      and request.state in ('READY','ACTIVE','OVERDUE','PARTLY_SUBMITTED')
      and membership.state='WAITING' and membership.client_id=p_client_id
      and membership.contract_id=p_contract_id
      and p_work_date>membership.week_ending-7 and p_work_date<=membership.week_ending);
$function$;
alter function private.weekly_source_candidate_generation_current_v1(uuid) OWNER TO CURRENT_USER;
alter function private.weekly_source_waiting_requested_week_v1(uuid,uuid,uuid,uuid,date) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_candidate_generation_current_v1(uuid) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_waiting_requested_week_v1(uuid,uuid,uuid,uuid,date) from public,anon,authenticated,service_role;

-- One eligibility predicate is shared by selection, rendering and the final
-- render assertion. A one-week submission exception must not widen at a later
-- delivery stage into a candidate-wide manager notification.
create or replace function private.weekly_source_manager_due_event_covers_v1(p_event_id uuid,p_incident_id uuid)
returns boolean language sql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
  select exists(
    select 1 from public.weekly_manager_cohort_due_events event
    join public.weekly_candidate_cohorts cohort on cohort.id=event.candidate_cohort_id
    join public.weekly_discrepancy_incidents incident
      on incident.id=p_incident_id and incident.candidate_id=cohort.candidate_id
      and incident.source_cycle_id=cohort.source_cycle_id
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    left join public.weekly_timesheet_submission_request_memberships requested on requested.id=event.requested_week_membership_id
    where event.id=p_event_id and not private.weekly_source_covered_hours_incident_v1(incident.id)
      and (event.requested_week_membership_id is null
      or (requested.state='SUBMITTED_WITH_ISSUES' and requested.client_id=incident.client_id
        and requested.contract_id=comparison.contract_id
        and work_event.work_date>requested.week_ending-7 and work_event.work_date<=requested.week_ending
        and incident.candidate_action_state='NOT_REQUIRED'))
  );
$function$;
alter function private.weekly_source_manager_due_event_covers_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_due_event_covers_v1(uuid,uuid) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_query_require_service_v1()
returns void
language plpgsql
stable
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     ) <> 'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
end;
$function$;

-- Does an ACCEPTED manager review batch on this recipient route already own
-- this exact incident episode?
--
-- 04A section 6.1: EARLY_ALL makes every currently manager-actionable,
-- "unanswered and unsent" row due, but "never resends a row already in an
-- accepted batch".  04A section 6.5: "one accepted batch owns each row and the
-- other action rechecks the remainder. No row is sent twice."  04A section 8:
-- "A later cohort merely becoming due is not a revocation event for an earlier
-- accepted batch."
--
-- Ownership therefore belongs to the RECIPIENT ROUTE, not to one generation of
-- it: a generation rotates whenever anything on the route changes, and a rule
-- scoped to a single generation stops holding the moment it does.
--
-- Only a batch that reached provider submission owns anything.  04A section 9
-- names that exact moment: the sender "commits SUBMISSION_STARTED for the exact
-- dispatch attempt before making the external call", and the render carries
-- that state.  A render that was retired before submission is unsent work whose
-- rows are still owed, so it must not block a later send.
--
-- A later incident EPISODE is different work under 04A section 6 and is not
-- excluded: the episode is part of the key.
create or replace function private.weekly_source_query_manager_row_owned_v1(
  p_recipient_route_id uuid,
  p_incident_id uuid,
  p_incident_episode integer
) returns boolean
language sql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  select case
    when p_recipient_route_id is null or p_incident_id is null
      or p_incident_episode is null
    then true
    else exists(
      select 1
      from public.weekly_manager_review_items owning_item
      join public.weekly_manager_review_batches owning_batch
        on owning_batch.id=owning_item.review_batch_id
      join public.weekly_manager_recipient_generations owning_generation
        on owning_generation.id=owning_batch.recipient_generation_id
      join public.weekly_message_renders owning_render
        on owning_render.id=owning_batch.message_render_id
      where owning_item.incident_id=p_incident_id
        and owning_item.incident_episode=p_incident_episode
        and owning_generation.recipient_route_id=p_recipient_route_id
        and owning_batch.state in ('ACTIVE','COMPLETE')
        and owning_render.state in ('SUBMISSION_STARTED','ACCEPTED','AMBIGUOUS')
        and owning_item.response_state in ('UNANSWERED','ANSWERED')
    )
  end;
$function$;

create or replace function public.weekly_source_candidate_query_get_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_candidate_id uuid;
  v_generation_id uuid;
  v_publication_id uuid;
  v_generation public.weekly_candidate_outreach_generations%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_items jsonb;
  v_submission public.weekly_timesheet_submission_requests%rowtype;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('candidate_id','candidate_generation_id','projection_publication_id')) then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_QUERY_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_candidate_id:=(p_request->>'candidate_id')::uuid;
    v_generation_id:=(p_request->>'candidate_generation_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_QUERY_REQUEST_INVALID' using errcode='22023';
  end;
  select * into strict v_generation from public.weekly_candidate_outreach_generations
  where id=v_generation_id and candidate_id=v_candidate_id;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_generation.source_cycle_id;
  select * into strict v_group from public.weekly_source_groups where id=v_cycle.source_group_id;
  perform private.weekly_source_query_current_publication_v1(v_cycle.id,v_publication_id);
  if v_generation.request_kind='SUBMIT_TIMESHEET' then
    select * into strict v_submission from public.weekly_timesheet_submission_requests
    where candidate_cohort_id=v_generation.candidate_cohort_id
      and state in ('ACTIVE','OVERDUE','PARTLY_SUBMITTED');
    select coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'request_membership_id',membership.id,'week_ending',membership.week_ending,
        'client_name',client.name,'contract_id',membership.contract_id
      ) order by membership.week_ending,private.weekly_source_query_ascii_fold_v1(client.name) collate "C",membership.id
    ),'[]'::jsonb) into v_items
    from public.weekly_timesheet_submission_request_memberships membership
    join public.clients client on client.id=membership.client_id
    where membership.submission_request_id=v_submission.id and membership.state='WAITING';
    return pg_catalog.jsonb_build_object(
      'ok',true,'request_kind','SUBMIT_TIMESHEET','title','Submit your Timesheet',
      'submission_request_id',v_submission.id,'deadline_at_utc',v_submission.deadline_at_utc,
      'overdue',v_submission.state='OVERDUE','items',v_items
    );
  end if;
  if v_generation.state<>'ACTIVE' or pg_catalog.transaction_timestamp()>v_generation.deadline_at_utc then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_QUERY_UNAVAILABLE' using errcode='42501';
  end if;
  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'incident_id',incident.id,
      'current_fact_version',pg_catalog.encode(comparison.material_comparison_fingerprint,'hex'),
      'expected_timesheet_hash',pg_catalog.encode(
        private.weekly_source_query_candidate_timesheet_hash_v1(comparison.candidate_timesheet_id),'hex'
      ),
      'client_name',client.name,'work_date',work_event.work_date,
      'candidate_start',to_char(comparison.candidate_start_at_local,'HH24:MI'),
      'candidate_end',to_char(comparison.candidate_end_at_local,'HH24:MI'),
      'candidate_break_minutes',comparison.candidate_break_minutes,
      'system_start',case when comparison.source_presence='PRESENT' then to_char(comparison.system_start_at_local,'HH24:MI') end,
      'system_end',case when comparison.source_presence='PRESENT' then to_char(comparison.system_end_at_local,'HH24:MI') end,
      'system_break_minutes',case when comparison.source_presence='PRESENT' then comparison.system_break_minutes end,
      'system_hours_text',case
        when comparison.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' and v_group.source_family='NHSP'
          then 'Missing or not yet authorised'
        when comparison.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' then 'Not shown in system'
        when comparison.issue_family='HEALTHROSTER_NOT_FINALISED' then 'Not finalised - no actual hours'
        else null end,
      'response_options',pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('value','CANDIDATE_WRONG','label','My hours are wrong. The client is correct.'),
        pg_catalog.jsonb_build_object('value','CANDIDATE_CORRECT','label','My hours are correct.'),
        pg_catalog.jsonb_build_object('value','NEITHER_CORRECT','label','Both sets of hours are wrong.')
      ),
      'contact_manager_message','Please contact your manager urgently if the system hours need to be changed.'
    ) order by work_event.work_date,coalesce(comparison.candidate_start_at_local,comparison.system_start_at_local),incident.id
  ),'[]'::jsonb) into v_items
  from public.weekly_candidate_outreach_memberships membership
  join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
  join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work_event on work_event.id=incident.work_event_id
  join public.clients client on client.id=incident.client_id
  where membership.candidate_generation_id=v_generation.id and membership.state='ACTIONABLE'
    and incident.state='OPEN'
    and not private.weekly_source_covered_hours_incident_v1(incident.id);
  return pg_catalog.jsonb_build_object(
    'ok',true,'request_kind','CHECK_HOURS','title','Check your Timesheet hours',
    'deadline_at_utc',v_generation.deadline_at_utc,'items',v_items
  );
end;
$function$;

create or replace function public.weekly_source_message_render_input_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_intent_id uuid;
  v_publication_id uuid;
  v_intent public.weekly_message_intents%rowtype;
  v_generation public.weekly_manager_recipient_generations%rowtype;
  v_candidate_generation public.weekly_candidate_outreach_generations%rowtype;
  v_membership jsonb;
  v_membership_hash bytea;
  v_rows jsonb;
  v_shift_count integer;
  v_client_count integer;
  v_candidate_count integer;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('message_intent_id','projection_publication_id')) then
    raise exception 'WEEKLY_SOURCE_RENDER_INPUT_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_intent_id:=(p_request->>'message_intent_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_RENDER_INPUT_REQUEST_INVALID' using errcode='22023';
  end;
  select * into strict v_intent from public.weekly_message_intents
  where id=v_intent_id and state='DUE';
  perform private.weekly_source_query_current_publication_v1(v_intent.source_cycle_id,v_publication_id);
  if v_intent.audience_kind='CANDIDATE' then
    select * into strict v_candidate_generation from public.weekly_candidate_outreach_generations
    where id=v_intent.candidate_generation_id and state='ACTIVE';
    return pg_catalog.jsonb_build_object(
      'ok',true,'audience_kind','CANDIDATE','tranche_kind',v_intent.tranche_kind,
      'candidate_id',v_candidate_generation.candidate_id,
      'request_kind',v_candidate_generation.request_kind,
      'membership_hash',pg_catalog.encode(v_candidate_generation.membership_hash,'hex')
    );
  end if;
  if v_intent.audience_kind<>'MANAGER' then
    raise exception 'WEEKLY_SOURCE_RENDER_INPUT_AUDIENCE_UNSUPPORTED' using errcode='55000';
  end if;
  select * into strict v_generation from public.weekly_manager_recipient_generations
  where id=v_intent.recipient_generation_id and state='ACTIVE';
  v_membership:=coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'incident_id',ranked.incident_id,'incident_episode',ranked.episode_number,
        'comparison_revision_id',ranked.comparison_revision_id,
        'comparison_fingerprint',pg_catalog.encode(ranked.comparison_fingerprint,'hex'),
        'client_order',ranked.client_order,'candidate_order',ranked.candidate_order,
        'shift_order',ranked.shift_order
      ) order by ranked.client_order,ranked.candidate_order,ranked.shift_order
    )
    from (
      select incident.id as incident_id,incident.episode_number,
        comparison.id as comparison_revision_id,
        comparison.material_comparison_fingerprint as comparison_fingerprint,
        pg_catalog.dense_rank() over(order by private.weekly_source_query_ascii_fold_v1(client.name) collate "C",client.id)::integer as client_order,
        pg_catalog.dense_rank() over(partition by client.id order by private.weekly_source_query_ascii_fold_v1(coalesce(nullif(candidate.display_name,''),pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name))) collate "C",candidate.id)::integer as candidate_order,
        pg_catalog.row_number() over(partition by client.id,candidate.id order by work_event.work_date,coalesce(comparison.system_start_at_local,comparison.candidate_start_at_local),incident.id)::integer as shift_order
      from public.weekly_manager_recipient_memberships membership
      join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
      join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      join public.weekly_work_events work_event on work_event.id=incident.work_event_id
      join public.clients client on client.id=incident.client_id
      join public.candidates candidate on candidate.id=incident.candidate_id
      where membership.recipient_generation_id=v_generation.id
        and incident.state='OPEN' and incident.manager_action_state<>'RESPONDED'
        and (
          coalesce(pg_catalog.array_length(v_intent.sorted_due_event_ids,1),0)=0
          or exists(
            select 1 from public.weekly_manager_cohort_due_events event
            where event.id=any(v_intent.sorted_due_event_ids)
              and event.recipient_generation_id=v_generation.id
              and event.candidate_cohort_id=membership.candidate_cohort_id
              and private.weekly_source_manager_due_event_covers_v1(event.id,incident.id)
          )
        )
        and (v_intent.tranche_kind<>'MANAGER_T6_RESPONDED' or incident.candidate_action_state='RESPONDED')
        and not private.weekly_source_query_manager_row_owned_v1(
          v_generation.recipient_route_id,incident.id,incident.episode_number
        )
    ) ranked
  ),'[]'::jsonb);
  v_shift_count:=pg_catalog.jsonb_array_length(v_membership);
  if v_shift_count=0 then raise exception 'WEEKLY_SOURCE_MANAGER_RENDER_EMPTY' using errcode='55000'; end if;
  v_membership_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_MANAGER_REVIEW_BATCH_MEMBERSHIP_V1',v_membership
  );
  select pg_catalog.count(distinct incident.client_id),pg_catalog.count(distinct incident.candidate_id)
  into v_client_count,v_candidate_count
  from pg_catalog.jsonb_array_elements(v_membership) member
  join public.weekly_discrepancy_incidents incident on incident.id=(member->>'incident_id')::uuid;
  if v_client_count>100 or v_candidate_count>100 or v_shift_count>500 then
    raise exception 'WEEKLY_SOURCE_MANAGER_DIGEST_CAPACITY_EXCEEDED' using errcode='54000';
  end if;
  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'clientId',incident.client_id,'clientName',client.name,
      'candidateId',incident.candidate_id,
      'displayName',coalesce(nullif(candidate.display_name,''),pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name)),
      'issueId',incident.id,'workDate',work_event.work_date,
      'sourceStartInstant',coalesce(comparison.system_start_at_local,comparison.candidate_start_at_local),
      'start',to_char(comparison.candidate_start_at_local,'HH24:MI'),
      'end',to_char(comparison.candidate_end_at_local,'HH24:MI'),
      'breakMinutes',comparison.candidate_break_minutes,
      'systemStart',case when comparison.source_presence='PRESENT' then to_char(comparison.system_start_at_local,'HH24:MI') end,
      'systemEnd',case when comparison.source_presence='PRESENT' then to_char(comparison.system_end_at_local,'HH24:MI') end,
      'systemBreakMinutes',case when comparison.source_presence='PRESENT' then comparison.system_break_minutes end,
      'systemAbsent',comparison.source_presence<>'PRESENT',
      'issueFamily',case
        when comparison.issue_family='SOURCE_HOURS_DIFFER' then 'HOURS_DIFFER'
        when comparison.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' and source_group.source_family='NHSP' then 'NHSP_ABSENT'
        when comparison.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' then 'SOURCE_ABSENT'
        else 'HEALTHROSTER_NOT_FINALISED' end,
      'candidateRequested',incident.candidate_action_state='RESPONDED'
    ) order by (member->>'client_order')::integer,(member->>'candidate_order')::integer,(member->>'shift_order')::integer
  ),'[]'::jsonb) into v_rows
  from pg_catalog.jsonb_array_elements(v_membership) member
  join public.weekly_discrepancy_incidents incident on incident.id=(member->>'incident_id')::uuid
  join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work_event on work_event.id=incident.work_event_id
  join public.clients client on client.id=incident.client_id
  join public.candidates candidate on candidate.id=incident.candidate_id
  join public.weekly_source_groups source_group on source_group.id=incident.source_group_id;
  return pg_catalog.jsonb_build_object(
    'ok',true,'audience_kind','MANAGER','tranche_kind',v_intent.tranche_kind,
    'policy_version','1.8.0','renderer_version','1.4.0','structure_version','1.0.0',
    'membership_hash',pg_catalog.encode(v_membership_hash,'hex'),
    'shift_count',v_shift_count,'client_count',v_client_count,
    'candidate_count',v_candidate_count,'rows',v_rows
  );
end;
$function$;

create or replace function public.weekly_source_timesheet_submission_complete_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_candidate_id uuid;
  v_submission_id uuid;
  v_publication_id uuid;
  v_submission public.weekly_timesheet_submission_requests%rowtype;
  v_generation public.weekly_candidate_outreach_generations%rowtype;
  v_completion jsonb;
  v_membership public.weekly_timesheet_submission_request_memberships%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_timesheet_hash bytea;
  v_outcome text;
  v_context jsonb;
  v_route_id uuid;
  v_route_ids uuid[]:='{}'::uuid[];
  v_route_activation public.weekly_route_activations%rowtype;
  v_manager_generation jsonb;
  v_manager_generation_id uuid;
  v_due_ids uuid[];
  v_intent_id uuid;
  v_completed integer:=0;
  v_issue_count integer:=0;
  v_manager_intents jsonb:='[]'::jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('candidate_id','submission_request_id','projection_publication_id','completions'))
     or pg_catalog.jsonb_typeof(p_request->'completions')<>'array'
     or pg_catalog.jsonb_array_length(p_request->'completions')=0 then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_COMPLETION_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_candidate_id:=(p_request->>'candidate_id')::uuid;
    v_submission_id:=(p_request->>'submission_request_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_COMPLETION_REQUEST_INVALID' using errcode='22023';
  end;
  select * into strict v_submission from public.weekly_timesheet_submission_requests
  where id=v_submission_id for update;
  if v_submission.candidate_id<>v_candidate_id
     or v_submission.state not in ('ACTIVE','OVERDUE','PARTLY_SUBMITTED') then
    if v_submission.candidate_id=v_candidate_id and v_submission.state='COMPLETE' then
      return pg_catalog.jsonb_build_object('ok',true,'replay',true,'submission_request_id',v_submission.id);
    end if;
    raise exception 'WEEKLY_SOURCE_TIMESHEET_COMPLETION_STALE' using errcode='40001';
  end if;
  perform private.weekly_source_query_current_publication_v1(v_submission.source_cycle_id,v_publication_id);
  select generation.* into strict v_generation
  from public.weekly_candidate_outreach_generations generation
  join public.weekly_candidate_cohorts cohort on cohort.id=generation.candidate_cohort_id
  where generation.candidate_cohort_id=v_submission.candidate_cohort_id
    and generation.request_kind='SUBMIT_TIMESHEET' and generation.state='ACTIVE'
    and cohort.current_submission_generation_id=generation.id
  for update of generation;

  for v_completion in
    select value from pg_catalog.jsonb_array_elements(p_request->'completions')
    order by (value->>'membership_id')::uuid
  loop
    if pg_catalog.jsonb_typeof(v_completion)<>'object'
       or exists(select 1 from pg_catalog.jsonb_object_keys(v_completion) key
                 where key not in (
                   'membership_id','timesheet_id','timesheet_revision','timesheet_hash','outcome'
                 )) then
      raise exception 'WEEKLY_SOURCE_TIMESHEET_COMPLETION_ITEM_INVALID' using errcode='22023';
    end if;
    begin
      select * into strict v_membership
      from public.weekly_timesheet_submission_request_memberships
      where id=(v_completion->>'membership_id')::uuid
        and submission_request_id=v_submission.id and state='WAITING'
      for update;
      select * into strict v_timesheet from public.timesheets
      where timesheet_id=(v_completion->>'timesheet_id')::uuid
        and version=(v_completion->>'timesheet_revision')::integer
        and contract_id=v_membership.contract_id
        and week_ending_date=v_membership.week_ending
        and is_current and revoked_at is null and archived_at_utc is null
        and sheet_scope='WEEKLY' and line_type='HOURS'
        and r2_nurse_key is not null and img_sha256_nurse is not null;
    exception when no_data_found or invalid_text_representation then
      raise exception 'WEEKLY_SOURCE_TIMESHEET_COMPLETION_ITEM_STALE' using errcode='40001';
    end;
    v_timesheet_hash:=private.weekly_source_query_candidate_timesheet_hash_v1(v_timesheet.timesheet_id);
    if v_timesheet_hash<>private.weekly_source_query_hex32_v1(
      v_completion->>'timesheet_hash','WEEKLY_SOURCE_CANDIDATE_TIMESHEET_HASH_INVALID'
    ) then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_TIMESHEET_STALE' using errcode='40001';
    end if;
    v_outcome:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_completion->>'outcome','')));
    if v_outcome not in ('MATCHED','ISSUES') then
      raise exception 'WEEKLY_SOURCE_TIMESHEET_COMPLETION_OUTCOME_INVALID' using errcode='22023';
    end if;
    if v_outcome='MATCHED' and exists(
      select 1 from public.weekly_discrepancy_incidents incident
      join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      join public.weekly_work_events work_event on work_event.id=incident.work_event_id
      where incident.source_cycle_id=v_submission.source_cycle_id
        and incident.candidate_id=v_candidate_id and incident.client_id=v_membership.client_id
        and comparison.contract_id=v_membership.contract_id and incident.state='OPEN'
        and work_event.work_date>v_membership.week_ending-7
        and work_event.work_date<=v_membership.week_ending
    ) then
      raise exception 'WEEKLY_SOURCE_TIMESHEET_COMPLETION_HAS_ISSUES' using errcode='40001';
    elsif v_outcome='ISSUES' and not exists(
      select 1 from public.weekly_discrepancy_incidents incident
      join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      join public.weekly_work_events work_event on work_event.id=incident.work_event_id
      where incident.source_cycle_id=v_submission.source_cycle_id
        and incident.candidate_id=v_candidate_id and incident.client_id=v_membership.client_id
        and comparison.contract_id=v_membership.contract_id and incident.state='OPEN'
        and work_event.work_date>v_membership.week_ending-7
        and work_event.work_date<=v_membership.week_ending
    ) then
      raise exception 'WEEKLY_SOURCE_TIMESHEET_COMPLETION_ISSUES_MISSING' using errcode='40001';
    end if;
    update public.weekly_timesheet_submission_request_memberships
    set state=case when v_outcome='MATCHED' then 'SUBMITTED_MATCHED' else 'SUBMITTED_WITH_ISSUES' end,
        submitted_timesheet_id=v_timesheet.timesheet_id,
        submitted_timesheet_revision=v_timesheet.version,
        submitted_timesheet_hash=v_timesheet_hash,completed_at_utc=pg_catalog.transaction_timestamp()
    where id=v_membership.id;
    if v_outcome='ISSUES' then
      v_issue_count:=v_issue_count+1;
      update public.weekly_discrepancy_incidents incident
      set candidate_action_state='NOT_REQUIRED'
      from public.weekly_issue_comparison_revisions comparison,public.weekly_work_events work_event
      where comparison.id=incident.current_comparison_revision_id
        and work_event.id=incident.work_event_id
        and incident.source_cycle_id=v_submission.source_cycle_id
        and incident.candidate_id=v_candidate_id and incident.client_id=v_membership.client_id
        and comparison.contract_id=v_membership.contract_id and incident.state='OPEN'
        and work_event.work_date>v_membership.week_ending-7
        and work_event.work_date<=v_membership.week_ending;
      v_context:=private.weekly_source_query_cohort_ensure_v1(
        v_submission.source_cycle_id,v_candidate_id,v_membership.client_id,
        v_membership.contract_id,v_membership.week_ending
      );
      if coalesce((v_context->>'manager_queries_enabled')::boolean,false)
         and nullif(v_context->>'manager_route_id','') is not null then
        v_route_id:=(v_context->>'manager_route_id')::uuid;
        -- 04A section 6: a signed Timesheet that mismatches queues "the exact
        -- new shift incidents" for an immediate EARLY_ALL.  Section 6.1 makes
        -- only an unanswered AND unsent row due, so a row an accepted batch on
        -- this route already owns keeps its SENT state and is not re-queued.
        update public.weekly_discrepancy_incidents incident
        set manager_action_state='DUE'
        from public.weekly_issue_comparison_revisions comparison,public.weekly_work_events work_event
        where comparison.id=incident.current_comparison_revision_id
          and work_event.id=incident.work_event_id
          and incident.source_cycle_id=v_submission.source_cycle_id
          and incident.candidate_id=v_candidate_id and incident.client_id=v_membership.client_id
          and comparison.contract_id=v_membership.contract_id and incident.state='OPEN'
          and work_event.work_date>v_membership.week_ending-7
          and work_event.work_date<=v_membership.week_ending
          and incident.manager_potential_state='AVAILABLE'
          and not private.weekly_source_covered_hours_incident_v1(incident.id)
          and not private.weekly_source_query_manager_row_owned_v1(
            v_route_id,incident.id,incident.episode_number
          );
        insert into public.weekly_route_activations(
          source_cycle_id,candidate_id,client_id,audience_route,route_mode,
          activated_by_user_id,activated_at_utc,updated_at_utc
        ) values (
          v_submission.source_cycle_id,v_candidate_id,v_membership.client_id,
          'MANAGER','CANDIDATE_FIRST',null,pg_catalog.transaction_timestamp(),pg_catalog.transaction_timestamp()
        ) on conflict (source_cycle_id,candidate_id,client_id,audience_route)
        do nothing
        returning * into v_route_activation;
        if not (v_route_id=any(v_route_ids)) then
          v_route_ids:=pg_catalog.array_append(v_route_ids,v_route_id);
        end if;
      end if;
    end if;
    v_completed:=v_completed+1;
  end loop;
  if v_completed<>pg_catalog.jsonb_array_length(p_request->'completions') then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_COMPLETION_SELECTION_INVALID' using errcode='22023';
  end if;
  if exists(select 1 from public.weekly_timesheet_submission_request_memberships
            where submission_request_id=v_submission.id and state='WAITING') then
    update public.weekly_timesheet_submission_requests
    set state='PARTLY_SUBMITTED',updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_submission.id;
  else
    update public.weekly_timesheet_submission_requests
    set state='COMPLETE',updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_submission.id;
    update public.weekly_candidate_outreach_generations set state='COMPLETE'
    where id=v_generation.id;
    update public.weekly_message_intents set state='RETIRED'
    where candidate_generation_id=v_generation.id and state in ('DUE','RENDERED');
  end if;
  for v_route_id in
    select distinct route_id from pg_catalog.unnest(v_route_ids) route_id order by route_id
  loop
    v_manager_generation:=private.weekly_source_query_manager_generation_v1(
      v_route_id,'OFFICE_DIRECT',pg_catalog.transaction_timestamp(),true
    );
    v_manager_generation_id:=(v_manager_generation->>'recipient_generation_id')::uuid;
    select pg_catalog.array_agg(id order by id) into v_due_ids
    from public.weekly_manager_cohort_due_events
    where recipient_generation_id=v_manager_generation_id and event_kind='EARLY_ALL' and state='PENDING';
    if coalesce(pg_catalog.array_length(v_due_ids,1),0)>0
       and not exists(
         select 1 from public.weekly_message_intents intent
         where intent.recipient_generation_id=v_manager_generation_id
           and intent.state in ('DUE','RENDERED')
       )
       and exists(
         -- 04A section 6.1: a row already owned by an accepted batch on this
         -- route is neither unanswered-and-unsent nor due, so it cannot be the
         -- whole reason for an EARLY_ALL intent whose render would be empty.
         select 1 from public.weekly_manager_recipient_memberships membership
         join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
         where membership.recipient_generation_id=v_manager_generation_id
           and incident.state='OPEN' and incident.manager_action_state<>'RESPONDED'
           and not private.weekly_source_query_manager_row_owned_v1(
             v_route_id,incident.id,incident.episode_number
           )
       ) then
      v_intent_id:=private.weekly_source_query_manager_intent_v1(
        v_route_id,v_manager_generation_id,v_due_ids,'MANAGER_EARLY_ALL',1,
        pg_catalog.transaction_timestamp()
      );
      update public.weekly_manager_cohort_due_events set state='CONSUMED' where id=any(v_due_ids);
      v_manager_intents:=v_manager_intents||pg_catalog.jsonb_build_array(v_intent_id);
    end if;
  end loop;
  perform public._audit_insert(
    'weekly_timesheet_submission_request',v_submission.id::text,
    'WEEKLY_TIMESHEET_SUBMISSION_COMPLETED',null,
    pg_catalog.jsonb_build_object(
      'completed_scope_count',v_completed,'issue_scope_count',v_issue_count,
      'request_complete',not exists(select 1 from public.weekly_timesheet_submission_request_memberships
                                    where submission_request_id=v_submission.id and state='WAITING')
    ),'Candidate submitted requested Weekly Timesheet',null
  );
  return pg_catalog.jsonb_build_object(
    'ok',true,'replay',false,'completed_scope_count',v_completed,
    'issue_scope_count',v_issue_count,'manager_message_intent_ids',v_manager_intents
  );
end;
$function$;

create or replace function public.weekly_source_query_accept_system_hours_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_cycle_id uuid;
  v_publication_id uuid;
  v_guard jsonb;
  v_requested uuid[];
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_comparison public.weekly_issue_comparison_revisions%rowtype;
  v_count integer:=0;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('actor_user_id','source_cycle_id','projection_publication_id','incident_ids'))
     or pg_catalog.jsonb_typeof(p_request->'incident_ids')<>'array' then
    raise exception 'WEEKLY_SOURCE_ACCEPT_SYSTEM_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
    select pg_catalog.array_agg(value::uuid order by value::uuid) into v_requested
    from pg_catalog.jsonb_array_elements_text(p_request->'incident_ids');
  exception when others then
    raise exception 'WEEKLY_SOURCE_ACCEPT_SYSTEM_REQUEST_INVALID' using errcode='22023';
  end;
  if coalesce(pg_catalog.array_length(v_requested,1),0)=0 then
    raise exception 'WEEKLY_SOURCE_ACCEPT_SYSTEM_SELECTION_INVALID' using errcode='22023';
  end if;
  v_guard:=private.weekly_source_query_current_publication_v1(v_cycle_id,v_publication_id);
  perform private.weekly_source_office_authority_v1(
    v_actor,'ACCEPT_SYSTEM_HOURS',(v_guard->>'source_group_id')::uuid,null,
    (v_guard->>'finalisation_week_ending')::date
  );
  perform private.weekly_source_pay_query_admit_v2();
  for v_incident in
    select incident.* from public.weekly_discrepancy_incidents incident
    where incident.id=any(v_requested) order by incident.id for update
  loop
    v_guard:=private.weekly_source_query_current_publication_v1(v_cycle_id,v_publication_id);
    perform private.weekly_source_office_authority_v1(
      v_actor,'ACCEPT_SYSTEM_HOURS',(v_guard->>'source_group_id')::uuid,null,
      (v_guard->>'finalisation_week_ending')::date);
    if v_incident.source_cycle_id<>v_cycle_id or v_incident.state<>'OPEN' then
      raise exception 'WEEKLY_SOURCE_ACCEPT_SYSTEM_SELECTION_STALE' using errcode='40001';
    end if;
    select * into strict v_comparison from public.weekly_issue_comparison_revisions
    where id=v_incident.current_comparison_revision_id;
    update public.weekly_discrepancy_incidents
    set state='RESOLVED',reconciliation_state='RECONCILED',
        candidate_action_state='NOT_REQUIRED',manager_potential_state='NOT_REQUIRED',
        manager_action_state='NOT_REQUIRED',waiting_source_state='NOT_WAITING',
        resolved_at_utc=pg_catalog.transaction_timestamp(),
        resolution_kind='OFFICE_ACCEPTED_SYSTEM_HOURS'
    where id=v_incident.id;
    update public.weekly_candidate_outreach_memberships set state='RESOLVED'
    where incident_id=v_incident.id and state in ('ACTIONABLE','ANSWERED');
    update public.weekly_manager_review_items set response_state='FILTERED_RESOLVED'
    where incident_id=v_incident.id and response_state='UNANSWERED';
    update public.office_action_notifications set operational_state='RESOLVED',
      resolved_at_utc=pg_catalog.transaction_timestamp()
    where issue_id=v_incident.id and operational_state='OPEN';
    insert into public.weekly_discrepancy_events(
      incident_id,issue_episode,projection_publication_id,
      expected_comparison_fingerprint,event_kind,actor_kind,actor_user_id,
      bounded_payload_json,idempotency_key
    ) values (
      v_incident.id,v_incident.episode_number,v_publication_id,
      v_comparison.material_comparison_fingerprint,'OFFICE_ACCEPTED','OFFICE',v_actor,
      pg_catalog.jsonb_build_object('resolution','OFFICE_ACCEPTED_SYSTEM_HOURS'),
      'OFFICE_ACCEPTED:'||v_incident.id::text||':'||pg_catalog.encode(v_comparison.material_comparison_fingerprint,'hex')
    ) on conflict (event_kind,idempotency_key) do nothing;
    insert into public.weekly_discrepancy_events(
      incident_id,issue_episode,projection_publication_id,
      expected_comparison_fingerprint,event_kind,actor_kind,actor_user_id,
      bounded_payload_json,idempotency_key
    ) values (
      v_incident.id,v_incident.episode_number,v_publication_id,
      v_comparison.material_comparison_fingerprint,'RESOLVED','OFFICE',v_actor,
      pg_catalog.jsonb_build_object('resolution','OFFICE_ACCEPTED_SYSTEM_HOURS'),
      'OFFICE_ACCEPTED_RESOLVED:'||v_incident.id::text||':'||pg_catalog.encode(v_comparison.material_comparison_fingerprint,'hex')
    ) on conflict (event_kind,idempotency_key) do nothing;
    v_count:=v_count+1;
  end loop;
  if v_count<>pg_catalog.array_length(v_requested,1) then
    raise exception 'WEEKLY_SOURCE_ACCEPT_SYSTEM_SELECTION_STALE' using errcode='40001';
  end if;
  perform public._audit_insert(
    'weekly_source_query_resolution',v_publication_id::text,
    'WEEKLY_SOURCE_SYSTEM_HOURS_ACCEPTED',null,
    pg_catalog.jsonb_build_object('incident_count',v_count),
    'Office accepted system hours',v_actor
  );
  return pg_catalog.jsonb_build_object('ok',true,'resolved_count',v_count);
end;
$function$;

create or replace function public.weekly_source_office_notifications_list_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_limit integer;
  v_open_only boolean;
  v_rows jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('actor_user_id','limit','open_only')) then
    raise exception 'WEEKLY_SOURCE_OFFICE_NOTICE_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_limit:=coalesce(nullif(p_request->>'limit','')::integer,100);
    v_open_only:=coalesce((p_request->>'open_only')::boolean,true);
  exception when others then
    raise exception 'WEEKLY_SOURCE_OFFICE_NOTICE_REQUEST_INVALID' using errcode='22023';
  end;
  if v_limit<1 or v_limit>500 or not exists(
    select 1 from public.tms_users u where u.id=v_actor and u.is_active
      and pg_catalog.lower(pg_catalog.btrim(u.role)) in ('admin','user')
  ) then
    raise exception 'WEEKLY_SOURCE_OFFICE_NOTICE_FORBIDDEN' using errcode='42501';
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(row_data) order by row_data.created_at_utc desc,row_data.id),'[]'::jsonb)
  into v_rows
  from (
    select notice.id,notice.event_kind,notice.issue_id,notice.issue_generation,
      notice.payload_json,notice.operational_state,notice.read_at_utc,notice.created_at_utc
    from public.office_action_notifications notice
    where notice.recipient_user_id=v_actor
      and (not v_open_only or notice.operational_state='OPEN')
    order by notice.created_at_utc desc,notice.id
    limit v_limit
  ) row_data;
  return pg_catalog.jsonb_build_object('ok',true,'notifications',v_rows);
end;
$function$;

create or replace function public.weekly_source_office_notification_ack_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_notice_id uuid;
  v_notice public.office_action_notifications%rowtype;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('actor_user_id','notification_id')) then
    raise exception 'WEEKLY_SOURCE_OFFICE_NOTICE_ACK_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_notice_id:=(p_request->>'notification_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_OFFICE_NOTICE_ACK_INVALID' using errcode='22023';
  end;
  select * into strict v_notice from public.office_action_notifications
  where id=v_notice_id and recipient_user_id=v_actor for update;
  update public.office_action_notifications
  set read_at_utc=coalesce(read_at_utc,pg_catalog.transaction_timestamp())
  where id=v_notice.id;
  return pg_catalog.jsonb_build_object('ok',true,'notification_id',v_notice.id,'acknowledged',true);
exception when no_data_found then
  raise exception 'WEEKLY_SOURCE_OFFICE_NOTICE_NOT_FOUND' using errcode='42501';
end;
$function$;

create or replace function public.weekly_source_manager_review_get_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_credential_hash bytea;
  v_control_ticket uuid;
  v_receipt public.weekly_manager_route_receipts%rowtype;
  v_batch public.weekly_manager_review_batches%rowtype;
  v_items jsonb;
  v_remaining integer;
  v_total integer;
  v_completed integer;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('credential_hash','control_plane_ticket_id')) then
    raise exception 'WEEKLY_SOURCE_MANAGER_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_credential_hash:=private.weekly_source_query_hex32_v1(
      p_request->>'credential_hash','WEEKLY_SOURCE_MANAGER_CREDENTIAL_HASH_INVALID'
    );
    v_control_ticket:=(p_request->>'control_plane_ticket_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_MANAGER_REVIEW_REQUEST_INVALID' using errcode='22023';
  end;
  select receipt.* into strict v_receipt
  from public.weekly_manager_route_receipts receipt
  join public.weekly_manager_review_batches batch on batch.id=receipt.review_batch_id
  where receipt.credential_hash=v_credential_hash
    and receipt.control_plane_ticket_id=v_control_ticket
  for update of receipt;
  select * into strict v_batch from public.weekly_manager_review_batches
  where id=v_receipt.review_batch_id for update;
  if v_receipt.state not in ('ACTIVE','COMPLETE') or v_batch.state not in ('ACTIVE','COMPLETE') then
    raise exception 'WEEKLY_SOURCE_MANAGER_REVIEW_UNAVAILABLE' using errcode='42501';
  end if;
  if pg_catalog.transaction_timestamp()>=v_receipt.expires_at_utc then
    update public.weekly_manager_route_receipts
    set state='EXPIRED' where id=v_receipt.id and state='ACTIVE';
    update public.weekly_manager_review_batches
    set state='EXPIRED' where id=v_batch.id and state='ACTIVE';
    raise exception 'WEEKLY_SOURCE_MANAGER_REVIEW_EXPIRED' using errcode='42501';
  end if;
  update public.weekly_manager_review_items item
  set response_state='FILTERED_RESOLVED'
  from public.weekly_discrepancy_incidents incident
  where item.review_batch_id=v_batch.id and item.incident_id=incident.id
    and item.response_state='UNANSWERED' and (incident.state<>'OPEN'
      or (item.incident_episode=incident.episode_number
        and private.weekly_source_covered_hours_incident_v1(incident.id)));

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'review_item_id',row_data.review_item_id,
      'incident_episode',row_data.incident_episode,
      'current_fact_version',pg_catalog.encode(row_data.current_fingerprint,'hex'),
      'client_id',row_data.client_id,'client_name',row_data.client_name,
      'candidate_id',row_data.candidate_id,'candidate_name',row_data.candidate_name,
      'work_date',row_data.work_date,
      'source_start_instant',row_data.source_start_instant,
      'candidate_start',to_char(row_data.candidate_start,'HH24:MI'),
      'candidate_end',to_char(row_data.candidate_end,'HH24:MI'),
      'candidate_break_minutes',row_data.candidate_break,
      'system_start',case when row_data.source_presence='PRESENT' then to_char(row_data.system_start,'HH24:MI') end,
      'system_end',case when row_data.source_presence='PRESENT' then to_char(row_data.system_end,'HH24:MI') end,
      'system_break_minutes',case when row_data.source_presence='PRESENT' then row_data.system_break end,
      'system_hours_text',case
        when row_data.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' and row_data.source_family='NHSP'
          then 'Missing or not yet authorised'
        when row_data.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED'
          then 'Not shown in system'
        when row_data.issue_family='HEALTHROSTER_NOT_FINALISED'
          then 'Not finalised - no actual hours'
        else null end,
      'issue_family',case
        when row_data.issue_family='SOURCE_HOURS_DIFFER' then 'HOURS_DIFFER'
        when row_data.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' and row_data.source_family='NHSP' then 'NHSP_ABSENT'
        when row_data.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' then 'SOURCE_ABSENT'
        else 'HEALTHROSTER_NOT_FINALISED' end,
      'candidate_response',case when row_data.candidate_action_state='RESPONDED'
        then 'Candidate requested your review' end,
      'response_options',case
        when row_data.issue_family='SOURCE_HOURS_DIFFER' then pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object('value','SYSTEM_CORRECT','label','The system hours are correct. The candidate timesheet hours are wrong.'),
          pg_catalog.jsonb_build_object('value','MANAGER_CORRECTED_SOURCE','label','I have corrected the hours','requires_hours',true)
        )
        when row_data.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' and row_data.source_family='NHSP' then pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object('value','CANDIDATE_DID_NOT_WORK','label','The candidate did not work this shift'),
          pg_catalog.jsonb_build_object('value','MANAGER_CORRECTED_SOURCE','label','I have added and/or authorised the shift','requires_hours',true)
        )
        when row_data.issue_family='HEALTHROSTER_NOT_FINALISED' then pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object('value','CANDIDATE_DID_NOT_WORK','label','The candidate did not work this shift'),
          pg_catalog.jsonb_build_object('value','MANAGER_CORRECTED_SOURCE','label','I have added and/or finalised the hours','requires_hours',true)
        )
        else pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object('value','CANDIDATE_DID_NOT_WORK','label','The candidate did not work this shift'),
          pg_catalog.jsonb_build_object('value','MANAGER_CORRECTED_SOURCE','label','I have added the shift','requires_hours',true)
        ) end
    ) order by row_data.client_order,row_data.candidate_order,row_data.shift_order
  ),'[]'::jsonb),pg_catalog.count(*) into v_items,v_remaining
  from (
    select item.id as review_item_id,item.incident_episode,item.client_order,
      item.candidate_order,item.shift_order,comparison.material_comparison_fingerprint as current_fingerprint,
      incident.client_id,incident.candidate_id,
      client.name as client_name,
      coalesce(nullif(candidate.display_name,''),pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name)) as candidate_name,
      work_event.work_date,comparison.candidate_start_at_local as candidate_start,
      comparison.candidate_end_at_local as candidate_end,
      comparison.candidate_break_minutes as candidate_break,
      comparison.system_start_at_local as system_start,comparison.system_end_at_local as system_end,
      comparison.system_break_minutes as system_break,comparison.source_presence,
      comparison.issue_family,source_group.source_family,incident.candidate_action_state,
      (coalesce(comparison.system_start_at_local,comparison.candidate_start_at_local)
        at time zone 'Europe/London') as source_start_instant
    from public.weekly_manager_review_items item
    join public.weekly_discrepancy_incidents incident on incident.id=item.incident_id
      and incident.episode_number=item.incident_episode and incident.state='OPEN'
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    join public.clients client on client.id=incident.client_id
    join public.candidates candidate on candidate.id=incident.candidate_id
    join public.weekly_source_groups source_group on source_group.id=incident.source_group_id
    where item.review_batch_id=v_batch.id and item.response_state='UNANSWERED'
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
  ) row_data;
  if v_remaining=0 and v_batch.state='ACTIVE' then
    update public.weekly_manager_review_batches
    set state='COMPLETE',completed_at_utc=pg_catalog.transaction_timestamp()
    where id=v_batch.id;
    update public.weekly_manager_route_receipts set state='COMPLETE' where id=v_receipt.id;
  end if;
  select pg_catalog.count(*),
         pg_catalog.count(*) filter(where response_state<>'UNANSWERED')
  into v_total,v_completed
  from public.weekly_manager_review_items where review_batch_id=v_batch.id;
  return pg_catalog.jsonb_build_object(
    'ok',true,'review_batch_id',v_batch.id,
    'review_batch_version',v_batch.credential_generation,
    'response_fingerprint',pg_catalog.encode(v_batch.sent_content_hash,'hex'),
    'recipient_generation_id',v_batch.recipient_generation_id,
    'original_membership_hash',pg_catalog.encode(v_batch.original_membership_hash,'hex'),
    'credential_generation',v_batch.credential_generation,
    'expires_at_utc',v_batch.expires_at_utc,'total_count',v_total,
    'completed_count',v_completed,'remaining_count',v_remaining,'items',v_items
  );
exception when no_data_found then
  raise exception 'WEEKLY_SOURCE_MANAGER_REVIEW_UNAVAILABLE' using errcode='42501';
end;
$function$;

create or replace function public.weekly_source_manager_review_respond_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_credential_hash bytea;
  v_control_ticket uuid;
  v_request_key uuid;
  v_responses jsonb;
  v_review_batch_version integer;
  v_response_fingerprint bytea;
  v_semantic_hash bytea;
  v_semantic_hex text;
  v_existing_count integer;
  v_existing_expected integer;
  v_existing_hash text;
  v_receipt public.weekly_manager_route_receipts%rowtype;
  v_batch public.weekly_manager_review_batches%rowtype;
  v_response jsonb;
  v_item public.weekly_manager_review_items%rowtype;
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_comparison public.weekly_issue_comparison_revisions%rowtype;
  v_kind text;
  v_expected bytea;
  v_response_hash bytea;
  v_event_id uuid;
  v_work public.weekly_work_events%rowtype;
  v_client public.clients%rowtype;
  v_candidate public.candidates%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_summary text;
  v_answered integer:=0;
  v_notices integer:=0;
  v_intended_start timestamp without time zone;
  v_intended_end timestamp without time zone;
  v_intended_break integer;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in (
                 'credential_hash','control_plane_ticket_id',
                 'request_idempotency_key','review_batch_version','response_fingerprint','responses'
               ))
     or pg_catalog.jsonb_typeof(p_request->'responses')<>'array'
     or pg_catalog.jsonb_array_length(p_request->'responses')=0 then
    raise exception 'WEEKLY_SOURCE_MANAGER_RESPONSE_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_credential_hash:=private.weekly_source_query_hex32_v1(
      p_request->>'credential_hash','WEEKLY_SOURCE_MANAGER_CREDENTIAL_HASH_INVALID'
    );
    v_control_ticket:=(p_request->>'control_plane_ticket_id')::uuid;
    v_request_key:=(p_request->>'request_idempotency_key')::uuid;
    v_review_batch_version:=(p_request->>'review_batch_version')::integer;
    v_response_fingerprint:=private.weekly_source_query_hex32_v1(
      p_request->>'response_fingerprint','WEEKLY_SOURCE_MANAGER_RESPONSE_FINGERPRINT_INVALID'
    );
    v_responses:=(select pg_catalog.jsonb_agg(value order by (value->>'review_item_id')::uuid)
                 from pg_catalog.jsonb_array_elements(p_request->'responses'));
  exception when others then
    raise exception 'WEEKLY_SOURCE_MANAGER_RESPONSE_REQUEST_INVALID' using errcode='22023';
  end;
  v_semantic_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_MANAGER_RESPONSE_REQUEST_V1',pg_catalog.jsonb_build_object(
      'control_plane_ticket_id',v_control_ticket,
      'review_batch_version',v_review_batch_version,
      'response_fingerprint',pg_catalog.encode(v_response_fingerprint,'hex'),
      'responses',v_responses
    )
  );
  v_semantic_hex:=pg_catalog.encode(v_semantic_hash,'hex');
  -- Exact response replay wins before credential expiry or mutable fact checks.
  select pg_catalog.count(*),min(event.bounded_payload_json->>'request_item_count'),
         min(event.bounded_payload_json->>'request_semantic_hash')
  into v_existing_count,v_existing_expected,v_existing_hash
  from public.weekly_discrepancy_events event
  where event.event_kind='MANAGER_RESPONDED'
    and event.bounded_payload_json->>'request_idempotency_key'=v_request_key::text;
  if v_existing_count>0 then
    if v_existing_hash<>v_semantic_hex
       or v_existing_expected::integer<>pg_catalog.jsonb_array_length(v_responses)
       or v_existing_count<>v_existing_expected then
      raise exception 'WEEKLY_SOURCE_MANAGER_RESPONSE_REPLAY_CONFLICT' using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'replay',true,'request_idempotency_key',v_request_key,
      'answered_count',v_existing_count
    );
  end if;
  perform private.weekly_source_pay_query_admit_v2();
  select receipt.* into strict v_receipt
  from public.weekly_manager_route_receipts receipt
  join public.weekly_manager_review_batches batch on batch.id=receipt.review_batch_id
  where receipt.credential_hash=v_credential_hash
    and receipt.control_plane_ticket_id=v_control_ticket
  for update of receipt;
  select * into strict v_batch from public.weekly_manager_review_batches
  where id=v_receipt.review_batch_id for update;
  if v_receipt.state<>'ACTIVE' or v_batch.state<>'ACTIVE'
     or pg_catalog.transaction_timestamp()>=v_receipt.expires_at_utc then
    raise exception 'WEEKLY_SOURCE_MANAGER_REVIEW_UNAVAILABLE' using errcode='42501';
  end if;
  if v_review_batch_version<>v_batch.credential_generation
     or v_response_fingerprint<>v_batch.sent_content_hash then
    raise exception 'WEEKLY_SOURCE_MANAGER_RESPONSE_BATCH_STALE' using errcode='40001';
  end if;
  for v_response in
    select value from pg_catalog.jsonb_array_elements(v_responses)
    order by (value->>'review_item_id')::uuid
  loop
    if pg_catalog.jsonb_typeof(v_response)<>'object'
       or exists(select 1 from pg_catalog.jsonb_object_keys(v_response) key
                 where key not in (
                   'review_item_id','incident_episode','current_fact_version','response_kind',
                   'intended_start','intended_end','intended_break_minutes'
                 )) then
      raise exception 'WEEKLY_SOURCE_MANAGER_RESPONSE_ITEM_INVALID' using errcode='22023';
    end if;
    begin
      select * into strict v_item from public.weekly_manager_review_items
      where id=(v_response->>'review_item_id')::uuid and review_batch_id=v_batch.id
        and response_state='UNANSWERED' for update;
      select * into strict v_incident from public.weekly_discrepancy_incidents
      where id=v_item.incident_id for update;
      select * into strict v_comparison from public.weekly_issue_comparison_revisions
      where id=v_incident.current_comparison_revision_id;
      select * into strict v_work from public.weekly_work_events where id=v_incident.work_event_id;
    exception when no_data_found or invalid_text_representation then
      raise exception 'WEEKLY_SOURCE_MANAGER_RESPONSE_ITEM_STALE' using errcode='40001';
    end;
    v_expected:=private.weekly_source_query_hex32_v1(
      v_response->>'current_fact_version','WEEKLY_SOURCE_MANAGER_FACT_VERSION_INVALID'
    );
    if v_incident.state<>'OPEN' or v_incident.episode_number<>(v_response->>'incident_episode')::integer
       or v_item.incident_episode<>v_incident.episode_number
       or private.weekly_source_covered_hours_incident_v1(v_incident.id)
       or v_expected<>v_comparison.material_comparison_fingerprint then
      raise exception 'WEEKLY_SOURCE_MANAGER_RESPONSE_ITEM_STALE' using errcode='40001';
    end if;
    v_kind:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_response->>'response_kind','')));
    if v_kind not in ('SYSTEM_CORRECT','CANDIDATE_DID_NOT_WORK','MANAGER_CORRECTED_SOURCE')
       or (v_kind='SYSTEM_CORRECT' and v_comparison.issue_family<>'SOURCE_HOURS_DIFFER')
       or (v_kind='CANDIDATE_DID_NOT_WORK' and v_comparison.issue_family='SOURCE_HOURS_DIFFER') then
      raise exception 'WEEKLY_SOURCE_MANAGER_RESPONSE_KIND_INVALID' using errcode='22023';
    end if;
    v_intended_start:=null;
    v_intended_end:=null;
    v_intended_break:=null;
    if v_kind='MANAGER_CORRECTED_SOURCE' then
      begin
        if coalesce(v_response->>'intended_start','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
           or coalesce(v_response->>'intended_end','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
          raise exception 'invalid time';
        end if;
        v_intended_break:=(v_response->>'intended_break_minutes')::integer;
        v_intended_start:=v_work.work_date+(v_response->>'intended_start')::time;
        v_intended_end:=v_work.work_date+(v_response->>'intended_end')::time;
        -- 14 section 5.3.4 for the source side: "If start equals end, the row
        -- blocks because neither accepted profile supplies an explicit 24-hour
        -- marker."  The overnight roll below is for a genuine end-before-start
        -- shift; start equal to end is not a 24-hour shift and must not be
        -- recorded as one, now that Office reads this value.
        if v_intended_end=v_intended_start then raise exception 'equal start and end'; end if;
        if v_intended_end<v_intended_start then v_intended_end:=v_intended_end+interval '1 day'; end if;
        if v_intended_break<0 or v_intended_break>720
           or v_intended_end<=v_intended_start then raise exception 'invalid hours'; end if;
      exception when others then
        raise exception 'WEEKLY_SOURCE_MANAGER_INTENDED_HOURS_INVALID' using errcode='22023';
      end;
    elsif v_response ? 'intended_start' or v_response ? 'intended_end'
       or v_response ? 'intended_break_minutes' then
      raise exception 'WEEKLY_SOURCE_MANAGER_INTENDED_HOURS_INVALID' using errcode='22023';
    end if;
    v_response_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_MANAGER_RESPONSE_ITEM_V1',pg_catalog.jsonb_build_object(
        'review_item_id',v_item.id,'incident_id',v_incident.id,
        'incident_episode',v_incident.episode_number,
        'current_fact_version',pg_catalog.encode(v_expected,'hex'),
        'response_kind',v_kind,
        'intended_start_at_local',v_intended_start,
        'intended_end_at_local',v_intended_end,
        'intended_break_minutes',v_intended_break
      )
    );
    update public.weekly_manager_review_items
    set response_state='ANSWERED',response_kind=v_kind,
        intended_start_at_local=v_intended_start,
        intended_end_at_local=v_intended_end,
        intended_break_minutes=v_intended_break,
        response_fingerprint=v_response_hash,answered_at_utc=pg_catalog.transaction_timestamp()
    where id=v_item.id;
    insert into public.weekly_discrepancy_events(
      incident_id,issue_episode,projection_publication_id,
      expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,
      idempotency_key
    ) values (
      v_incident.id,v_incident.episode_number,v_comparison.projection_publication_id,
      v_expected,'MANAGER_RESPONDED','MANAGER',pg_catalog.jsonb_build_object(
        'response_kind',v_kind,'response_fingerprint',pg_catalog.encode(v_response_hash,'hex'),
        'request_idempotency_key',v_request_key,'request_semantic_hash',v_semantic_hex,
        'request_item_count',pg_catalog.jsonb_array_length(v_responses),
        'review_item_id',v_item.id
      ),'MANAGER_RESPONSE:'||v_request_key::text||':'||v_item.id::text
    ) returning id into v_event_id;
    -- A manager saying the source is right does not settle a candidate's
    -- explicit assertion that their own hours are right. Keep the ordinary
    -- open-incident authorisation hold until Office accepts current source
    -- hours or protects pay for this existing work identity.
    if v_kind in ('SYSTEM_CORRECT','CANDIDATE_DID_NOT_WORK')
       and not (v_incident.candidate_action_state='RESPONDED'
         and exists (
           select 1 from public.weekly_discrepancy_events candidate_answer
           where candidate_answer.incident_id=v_incident.id
             and candidate_answer.issue_episode=v_incident.episode_number
             and candidate_answer.event_kind='CANDIDATE_RESPONDED'
             and candidate_answer.bounded_payload_json->>'choice'='CANDIDATE_CORRECT'
         )) then
      update public.weekly_discrepancy_incidents
      set state='RESOLVED',reconciliation_state='RECONCILED',
          candidate_action_state=case when candidate_action_state='NOT_ASKED' then 'NOT_REQUIRED' else candidate_action_state end,
          manager_potential_state='NOT_REQUIRED',manager_action_state='RESPONDED',
          waiting_source_state='NOT_WAITING',resolved_at_utc=pg_catalog.transaction_timestamp(),
          resolution_kind='MANAGER_CONFIRMED_SYSTEM_HOURS'
      where id=v_incident.id;
      update public.weekly_candidate_outreach_memberships set state='RESOLVED'
      where incident_id=v_incident.id and state in ('ACTIONABLE','ANSWERED');
      insert into public.weekly_discrepancy_events(
        incident_id,issue_episode,projection_publication_id,
        expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,idempotency_key
      ) values (
        v_incident.id,v_incident.episode_number,v_comparison.projection_publication_id,
        v_expected,'RESOLVED','MANAGER',
        pg_catalog.jsonb_build_object('resolution','MANAGER_CONFIRMED_SYSTEM_HOURS'),
        'MANAGER_CONFIRMED:'||v_event_id::text
      );
    elsif v_kind='MANAGER_CORRECTED_SOURCE' then
      update public.weekly_discrepancy_incidents
      set reconciliation_state='WAITING_FOR_SOURCE',manager_action_state='RESPONDED',
          waiting_source_state='WAITING_REIMPORT'
      where id=v_incident.id;
    else
      update public.weekly_discrepancy_incidents
      set reconciliation_state='UNRESOLVED',manager_action_state='RESPONDED',
          waiting_source_state='NOT_WAITING'
      where id=v_incident.id;
    end if;
    select * into strict v_client from public.clients where id=v_incident.client_id;
    select * into strict v_candidate from public.candidates where id=v_incident.candidate_id;
    select * into strict v_group from public.weekly_source_groups where id=v_incident.source_group_id;
    v_summary:=case
      when v_comparison.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' and v_group.source_family='NHSP'
        then 'Shift missing or not yet authorised'
      when v_comparison.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED'
        then 'Shift not shown in system'
      else 'System hours reviewed'
    end;
    -- 04A section 4: "A corrected/added/finalised response records the manager's
    -- intended start, end and break and waits for a later accepted source
    -- upload; it never creates source hours."  The record lives on
    -- weekly_manager_review_items and is deliberately left out of every
    -- calculation.  It is repeated here, as plain non-financial text, so the
    -- Office notice this response raises actually carries the figures the
    -- manager gave; without them Office cannot compare the manager's stated
    -- correction with the later source, which is what section 6 expects it to
    -- do.  These keys are hours only: the fan-out owner rejects any pay,
    -- charge, rate, margin, VAT, invoice or banking key.
    v_notices:=v_notices+private.weekly_source_query_notice_fanout_v1(
      v_incident.id,v_event_id,
      case when v_kind='MANAGER_CORRECTED_SOURCE'
        then 'WEEKLY_MANAGER_SOURCE_CORRECTED' else 'WEEKLY_MANAGER_SYSTEM_CONFIRMED' end,
      pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'candidate_name',coalesce(nullif(v_candidate.display_name,''),
          pg_catalog.concat_ws(' ',v_candidate.first_name,v_candidate.last_name)),
        'client_name',v_client.name,'work_date',v_work.work_date,
        'issue_summary',v_summary,'manager_response',v_kind,
        'manager_intended_start',to_char(v_intended_start,'YYYY-MM-DD HH24:MI'),
        'manager_intended_end',to_char(v_intended_end,'YYYY-MM-DD HH24:MI'),
        'manager_intended_break_minutes',v_intended_break
      ))
    );
    v_answered:=v_answered+1;
  end loop;
  if v_answered<>pg_catalog.jsonb_array_length(v_responses) then
    raise exception 'WEEKLY_SOURCE_MANAGER_RESPONSE_SELECTION_INVALID' using errcode='22023';
  end if;
  if not exists(select 1 from public.weekly_manager_review_items
                where review_batch_id=v_batch.id and response_state='UNANSWERED') then
    update public.weekly_manager_review_batches set state='COMPLETE',
      completed_at_utc=pg_catalog.transaction_timestamp() where id=v_batch.id;
    update public.weekly_manager_route_receipts set state='COMPLETE' where id=v_receipt.id;
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'replay',false,'request_idempotency_key',v_request_key,
    'answered_count',v_answered,'office_notification_count',v_notices,
    'remaining_count',(select pg_catalog.count(*) from public.weekly_manager_review_items
                       where review_batch_id=v_batch.id and response_state='UNANSWERED')
  );
exception when no_data_found then
  raise exception 'WEEKLY_SOURCE_MANAGER_REVIEW_UNAVAILABLE' using errcode='42501';
end;
$function$;

create or replace function public.weekly_source_message_dispatch_claim_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_worker text;
  v_limit integer;
  v_lease_seconds integer;
  v_token uuid:=pg_catalog.gen_random_uuid();
  v_commands jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('worker_id','limit','lease_seconds')) then
    raise exception 'WEEKLY_SOURCE_DISPATCH_CLAIM_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_worker:=pg_catalog.btrim(p_request->>'worker_id');
    v_limit:=coalesce(nullif(p_request->>'limit','')::integer,25);
    v_lease_seconds:=coalesce(nullif(p_request->>'lease_seconds','')::integer,60);
  exception when others then
    raise exception 'WEEKLY_SOURCE_DISPATCH_CLAIM_REQUEST_INVALID' using errcode='22023';
  end;
  if v_worker is null or v_worker!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
     or v_limit<1 or v_limit>100 or v_lease_seconds<15 or v_lease_seconds>300 then
    raise exception 'WEEKLY_SOURCE_DISPATCH_CLAIM_REQUEST_INVALID' using errcode='22023';
  end if;
  with eligible as (
    select command.id
    from public.weekly_message_dispatch_commands command
    where command.target_set_state='NOT_PREPARED'
      and (
        (command.state in ('READY','FAILED')
          and coalesce(command.next_attempt_at_utc,'-infinity'::timestamptz)
            <=pg_catalog.transaction_timestamp())
        or
        (command.state='LEASED'
          and command.lease_expires_at_utc<=pg_catalog.transaction_timestamp())
      )
    order by command.next_attempt_at_utc nulls first,command.id
    limit v_limit
    for update skip locked
  ), claimed as (
    update public.weekly_message_dispatch_commands command
    set state='LEASED',lease_owner=v_worker,lease_token=v_token,
        lease_expires_at_utc=pg_catalog.transaction_timestamp()
          +pg_catalog.make_interval(secs=>v_lease_seconds)
    from eligible where command.id=eligible.id
    returning command.*
  )
  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'dispatch_command_id',claimed.id,'lease_token',claimed.lease_token,
      'lease_expires_at_utc',claimed.lease_expires_at_utc,
      'environment',claimed.environment,'agency_id',claimed.agency_id,
      'audience_kind',intent.audience_kind,'tranche_kind',claimed.tranche_kind,
      'candidate_id',candidate_generation.candidate_id,
      'candidate_generation_id',claimed.candidate_generation_id,
      'manager_recipient_route_id',claimed.recipient_route_id,
      'manager_recipient',route.protected_recipient_address,
      'manager_recipient_fingerprint',case when route.id is null then null
        else pg_catalog.encode(route.normalised_recipient_hash,'hex') end,
      'message_intent_id',intent.id,'message_render_id',render.id,
      'subject_text',render.subject_text,'html_body',render.html_body,
      'plain_body',render.plain_body,'provider_idempotency_key',render.provider_idempotency_key,
      'rendered_content_hash',pg_catalog.encode(render.rendered_content_hash,'hex'),
      'review_batch_id',batch.id,'control_plane_ticket_id',batch.control_plane_ticket_id
    ) order by claimed.id
  ),'[]'::jsonb) into v_commands
  from claimed
  join public.weekly_message_intents intent on intent.id=claimed.message_intent_id
  join public.weekly_message_renders render on render.id=claimed.message_render_id
  left join public.weekly_candidate_outreach_generations candidate_generation
    on candidate_generation.id=claimed.candidate_generation_id
  left join public.weekly_manager_recipient_routes route on route.id=claimed.recipient_route_id
  left join public.weekly_manager_review_batches batch on batch.message_render_id=render.id;
  return pg_catalog.jsonb_build_object(
    'ok',true,'worker_id',v_worker,'lease_token',v_token,
    'claimed_count',pg_catalog.jsonb_array_length(v_commands),'commands',v_commands
  );
end;
$function$;

create or replace function public.weekly_source_message_dispatch_submission_start_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_command_id uuid;
  v_lease_token uuid;
  v_worker text;
  v_channel text;
  v_target_kind text;
  v_target_hash bytea;
  v_command public.weekly_message_dispatch_commands%rowtype;
  v_intent public.weekly_message_intents%rowtype;
  v_render public.weekly_message_renders%rowtype;
  v_attempt public.weekly_message_provider_attempts%rowtype;
  v_attempt_number integer;
  v_provider_key text;
  v_policy jsonb;
  v_member record;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in (
                 'dispatch_command_id','lease_token','worker_id','channel','target_kind',
                 'keyed_target_fingerprint'
               )) then
    raise exception 'WEEKLY_SOURCE_DISPATCH_START_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_command_id:=(p_request->>'dispatch_command_id')::uuid;
    v_lease_token:=(p_request->>'lease_token')::uuid;
    v_worker:=p_request->>'worker_id';
    v_channel:=pg_catalog.upper(p_request->>'channel');
    v_target_kind:=pg_catalog.upper(p_request->>'target_kind');
    v_target_hash:=private.weekly_source_query_hex32_v1(
      p_request->>'keyed_target_fingerprint','WEEKLY_SOURCE_DISPATCH_TARGET_INVALID'
    );
  exception when others then
    raise exception 'WEEKLY_SOURCE_DISPATCH_START_REQUEST_INVALID' using errcode='22023';
  end;
  if v_channel not in ('PUSH','EMAIL') or v_target_kind not in (
    'CANDIDATE_DEVICE','MANAGER_ADDRESS','PACK_COPY_ADDRESS'
  ) or (v_channel='PUSH')<>(v_target_kind='CANDIDATE_DEVICE') then
    raise exception 'WEEKLY_SOURCE_DISPATCH_CHANNEL_INVALID' using errcode='22023';
  end if;
  select * into strict v_command from public.weekly_message_dispatch_commands
  where id=v_command_id for update;
  select * into strict v_intent from public.weekly_message_intents where id=v_command.message_intent_id;
  select * into strict v_render from public.weekly_message_renders where id=v_command.message_render_id for update;
  select * into v_attempt from public.weekly_message_provider_attempts
  where dispatch_command_id=v_command.id and keyed_target_fingerprint=v_target_hash
  order by attempt_number desc limit 1;
  if found and v_attempt.completed_at_utc is null
     and v_command.state in ('SUBMISSION_STARTED','ACCEPTED','AMBIGUOUS') then
    return pg_catalog.jsonb_build_object(
      'ok',true,'replay',true,'provider_attempt_id',v_attempt.id,
      'provider_idempotency_key',v_attempt.provider_idempotency_key,
      'state',v_command.state
    );
  end if;
  if v_command.state<>'LEASED' or v_command.lease_token<>v_lease_token
     or v_command.lease_owner<>v_worker
     or v_command.lease_expires_at_utc<=pg_catalog.transaction_timestamp()
     or v_intent.state<>'RENDERED' or v_render.state not in ('CURRENT','SUBMISSION_STARTED') then
    raise exception 'WEEKLY_SOURCE_DISPATCH_LEASE_STALE' using errcode='40001';
  end if;
  begin
    perform private.weekly_source_query_current_publication_v1(
      v_command.source_cycle_id,v_command.projection_publication_id
    );
  exception when others then
    update public.weekly_message_dispatch_commands set state='RETIRED',lease_owner=null,
      lease_token=null,lease_expires_at_utc=null where id=v_command.id;
    update public.weekly_message_intents set state='RETIRED' where id=v_intent.id;
    update public.weekly_message_renders set state='STALE' where id=v_render.id;
    return pg_catalog.jsonb_build_object('ok',false,'eligible',false,'reason','CURRENT_HOURS_CHANGED');
  end;
  if v_intent.audience_kind='CANDIDATE' then
    if not exists(
      select 1 from public.weekly_candidate_outreach_generations generation
      join public.weekly_candidate_cohorts cohort on cohort.id=generation.candidate_cohort_id
      where generation.id=v_command.candidate_generation_id and generation.state='ACTIVE'
        and private.weekly_source_candidate_generation_current_v1(generation.id)
    ) then
      update public.weekly_message_dispatch_commands set state='RETIRED',lease_owner=null,
        lease_token=null,lease_expires_at_utc=null where id=v_command.id;
      update public.weekly_message_intents set state='RETIRED' where id=v_intent.id;
      update public.weekly_message_renders set state='STALE' where id=v_render.id;
      return pg_catalog.jsonb_build_object('ok',false,'eligible',false,'reason','REQUEST_REPLACED');
    end if;
    if not exists(
      select 1
      from public.weekly_candidate_outreach_memberships membership
      join public.weekly_discrepancy_incidents incident
        on incident.id=membership.incident_id
      where membership.candidate_generation_id=v_command.candidate_generation_id
        and membership.state='ACTIONABLE' and incident.state='OPEN'
        and not private.weekly_source_covered_hours_incident_v1(incident.id)
    ) and not exists(
      select 1
      from public.weekly_candidate_outreach_generations generation
      join public.weekly_timesheet_submission_requests submission
        on submission.candidate_cohort_id=generation.candidate_cohort_id
       and submission.state in ('ACTIVE','OVERDUE','PARTLY_SUBMITTED')
      join public.weekly_timesheet_submission_request_memberships membership
        on membership.submission_request_id=submission.id and membership.state='WAITING'
      where generation.id=v_command.candidate_generation_id
        and generation.request_kind='SUBMIT_TIMESHEET'
    ) then
      update public.weekly_message_dispatch_commands set state='RETIRED',lease_owner=null,
        lease_token=null,lease_expires_at_utc=null where id=v_command.id;
      update public.weekly_message_intents set state='RETIRED' where id=v_intent.id;
      update public.weekly_message_renders set state='STALE' where id=v_render.id;
      return pg_catalog.jsonb_build_object('ok',false,'eligible',false,'reason','REQUEST_RESOLVED');
    end if;
    for v_member in
      select incident.id as incident_id,null::uuid as client_id,
             null::uuid as contract_id,null::date as work_date
      from public.weekly_candidate_outreach_memberships membership
      join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
      where membership.candidate_generation_id=v_command.candidate_generation_id
        and membership.state='ACTIONABLE'
        and incident.state='OPEN'
        and not private.weekly_source_covered_hours_incident_v1(incident.id)
      union all
      select null::uuid,membership.client_id,membership.contract_id,membership.week_ending
      from public.weekly_candidate_outreach_generations generation
      join public.weekly_timesheet_submission_requests submission
        on submission.candidate_cohort_id=generation.candidate_cohort_id
       and submission.state in ('ACTIVE','OVERDUE','PARTLY_SUBMITTED')
      join public.weekly_timesheet_submission_request_memberships membership
        on membership.submission_request_id=submission.id and membership.state='WAITING'
      where generation.id=v_command.candidate_generation_id
        and generation.request_kind='SUBMIT_TIMESHEET'
    loop
      v_policy:=case when v_member.incident_id is not null
        then private.weekly_source_query_incident_policy_v1(v_member.incident_id)
        else private._weekly_source_effective_policy_v1(
          v_member.client_id,v_member.contract_id,v_member.work_date
        ) end;
      if coalesce((v_policy->>'candidate_queries_enabled')::boolean,false) is not true then
        update public.weekly_message_dispatch_commands set state='RETIRED',lease_owner=null,
          lease_token=null,lease_expires_at_utc=null where id=v_command.id;
        update public.weekly_message_intents set state='RETIRED' where id=v_intent.id;
        update public.weekly_message_renders set state='STALE' where id=v_render.id;
        return pg_catalog.jsonb_build_object('ok',false,'eligible',false,'reason','CANDIDATE_CONTACT_DISABLED');
      end if;
    end loop;
  elsif v_intent.audience_kind='MANAGER' then
    if not exists(
      select 1 from public.weekly_manager_recipient_generations generation
      join public.weekly_manager_recipient_routes route on route.id=generation.recipient_route_id
      join public.weekly_manager_review_batches batch on batch.recipient_generation_id=generation.id
        and batch.message_render_id=v_render.id and batch.state='ACTIVE'
      where generation.id=v_intent.recipient_generation_id and generation.state='ACTIVE'
        and route.current_generation_id=generation.id
    ) then
      update public.weekly_message_dispatch_commands set state='RETIRED',lease_owner=null,
        lease_token=null,lease_expires_at_utc=null where id=v_command.id;
      update public.weekly_message_intents set state='RETIRED' where id=v_intent.id;
      update public.weekly_message_renders set state='STALE' where id=v_render.id;
      return pg_catalog.jsonb_build_object('ok',false,'eligible',false,'reason','REVIEW_REPLACED');
    end if;
    if exists(
      select 1
      from public.weekly_manager_review_batches batch
      join public.weekly_manager_review_items item on item.review_batch_id=batch.id
      join public.weekly_discrepancy_incidents incident on incident.id=item.incident_id
      join public.weekly_issue_comparison_revisions comparison
        on comparison.id=incident.current_comparison_revision_id
      where batch.message_render_id=v_render.id
        and (
          item.response_state<>'UNANSWERED'
          or incident.state<>'OPEN'
          or private.weekly_source_covered_hours_incident_v1(incident.id)
          or item.incident_episode<>incident.episode_number
          or item.sent_comparison_revision_id<>incident.current_comparison_revision_id
          or item.sent_comparison_fingerprint<>comparison.material_comparison_fingerprint
        )
    ) or not exists(
      select 1
      from public.weekly_manager_review_batches batch
      join public.weekly_manager_review_items item on item.review_batch_id=batch.id
      join public.weekly_discrepancy_incidents incident on incident.id=item.incident_id
      where batch.message_render_id=v_render.id
        and item.response_state='UNANSWERED' and incident.state='OPEN'
        and not private.weekly_source_covered_hours_incident_v1(incident.id)
    ) then
      update public.weekly_message_dispatch_commands set state='RETIRED',lease_owner=null,
        lease_token=null,lease_expires_at_utc=null where id=v_command.id;
      update public.weekly_message_intents set state='RETIRED' where id=v_intent.id;
      update public.weekly_message_renders set state='STALE' where id=v_render.id;
      update public.weekly_manager_review_batches
      set state='REVOKED' where message_render_id=v_render.id and state='ACTIVE';
      update public.weekly_manager_route_receipts receipt
      set state='REVOKED',revoked_at_utc=pg_catalog.transaction_timestamp()
      from public.weekly_manager_review_batches batch
      where receipt.review_batch_id=batch.id and batch.message_render_id=v_render.id
        and receipt.state='ACTIVE';
      update public.weekly_manager_review_items item
      set response_state='OBSOLETE'
      from public.weekly_manager_review_batches batch
      where item.review_batch_id=batch.id and batch.message_render_id=v_render.id
        and item.response_state='UNANSWERED';
      return pg_catalog.jsonb_build_object('ok',false,'eligible',false,'reason','REVIEW_CHANGED');
    end if;
    for v_member in
      select incident.id
      from public.weekly_manager_review_items item
      join public.weekly_discrepancy_incidents incident on incident.id=item.incident_id
      where item.review_batch_id=(select id from public.weekly_manager_review_batches where message_render_id=v_render.id)
        and item.response_state='UNANSWERED'
    loop
      v_policy:=private.weekly_source_query_incident_policy_v1(v_member.id);
      if coalesce((v_policy->>'manager_queries_enabled')::boolean,false) is not true then
        update public.weekly_message_dispatch_commands set state='RETIRED',lease_owner=null,
          lease_token=null,lease_expires_at_utc=null where id=v_command.id;
        update public.weekly_message_intents set state='RETIRED' where id=v_intent.id;
        update public.weekly_message_renders set state='STALE' where id=v_render.id;
        return pg_catalog.jsonb_build_object('ok',false,'eligible',false,'reason','MANAGER_CONTACT_DISABLED');
      end if;
    end loop;
  end if;
  select coalesce(pg_catalog.max(attempt_number),0)+1 into v_attempt_number
  from public.weekly_message_provider_attempts
  where dispatch_command_id=v_command.id and keyed_target_fingerprint=v_target_hash;
  v_provider_key:=v_render.provider_idempotency_key||'/'||pg_catalog.encode(v_target_hash,'hex')||'/'||v_attempt_number::text;
  insert into public.weekly_message_provider_attempts(
    dispatch_command_id,attempt_number,channel,target_kind,keyed_target_fingerprint,
    provider_idempotency_key,started_at_utc
  ) values (
    v_command.id,v_attempt_number,v_channel,v_target_kind,v_target_hash,
    v_provider_key,pg_catalog.transaction_timestamp()
  ) returning * into v_attempt;
  update public.weekly_message_renders set state='SUBMISSION_STARTED' where id=v_render.id;
  update public.weekly_message_dispatch_commands
  set state='SUBMISSION_STARTED',attempt_count=attempt_count+1
  where id=v_command.id;
  return pg_catalog.jsonb_build_object(
    'ok',true,'replay',false,'provider_attempt_id',v_attempt.id,
    'provider_idempotency_key',v_attempt.provider_idempotency_key,
    'submission_started_at_utc',v_attempt.started_at_utc
  );
end;
$function$;

create or replace function public.weekly_source_message_dispatch_result_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_attempt_id uuid;
  v_outcome text;
  v_provider_message_id text;
  v_receipt jsonb;
  v_error jsonb;
  v_attempt public.weekly_message_provider_attempts%rowtype;
  v_command public.weekly_message_dispatch_commands%rowtype;
  v_render public.weekly_message_renders%rowtype;
  v_intent public.weekly_message_intents%rowtype;
  v_result_hash bytea;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('provider_attempt_id','outcome','provider_message_id','receipt','error')) then
    raise exception 'WEEKLY_SOURCE_DISPATCH_RESULT_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_attempt_id:=(p_request->>'provider_attempt_id')::uuid;
    v_outcome:=pg_catalog.upper(p_request->>'outcome');
    v_provider_message_id:=nullif(p_request->>'provider_message_id','');
    v_receipt:=coalesce(p_request->'receipt','{}'::jsonb);
    v_error:=coalesce(p_request->'error','{}'::jsonb);
  exception when others then
    raise exception 'WEEKLY_SOURCE_DISPATCH_RESULT_REQUEST_INVALID' using errcode='22023';
  end;
  if v_outcome not in ('ACCEPTED','DEFINITELY_REJECTED','TRANSIENT_FAILURE','AMBIGUOUS')
     or pg_catalog.jsonb_typeof(v_receipt)<>'object' or pg_catalog.jsonb_typeof(v_error)<>'object'
     or pg_catalog.length(v_receipt::text)>20000 or pg_catalog.length(v_error::text)>20000
     or v_receipt ?| array['token','credential','password','secret','authorization']
     or v_error ?| array['token','credential','password','secret','authorization'] then
    raise exception 'WEEKLY_SOURCE_DISPATCH_RESULT_INVALID' using errcode='22023';
  end if;
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_MESSAGE_PROVIDER_RESULT_V1',pg_catalog.jsonb_build_object(
      'provider_attempt_id',v_attempt_id,'outcome',v_outcome,
      'provider_message_id',v_provider_message_id,'receipt',v_receipt,'error',v_error
    )
  );
  select * into strict v_attempt from public.weekly_message_provider_attempts
  where id=v_attempt_id for update;
  if v_attempt.completed_at_utc is not null then
    if v_attempt.outcome<>v_outcome
       or v_attempt.bounded_provider_receipt_json->>'result_hash'<>pg_catalog.encode(v_result_hash,'hex') then
      raise exception 'WEEKLY_SOURCE_DISPATCH_RESULT_REPLAY_CONFLICT' using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object('ok',true,'replay',true,'outcome',v_attempt.outcome);
  end if;
  select * into strict v_command from public.weekly_message_dispatch_commands
  where id=v_attempt.dispatch_command_id for update;
  select * into strict v_render from public.weekly_message_renders where id=v_command.message_render_id for update;
  select * into strict v_intent from public.weekly_message_intents where id=v_command.message_intent_id for update;
  if v_command.state<>'SUBMISSION_STARTED' then
    raise exception 'WEEKLY_SOURCE_DISPATCH_RESULT_STATE_INVALID' using errcode='40001';
  end if;
  update public.weekly_message_provider_attempts
  set completed_at_utc=pg_catalog.transaction_timestamp(),outcome=v_outcome,
      bounded_provider_receipt_json=v_receipt||pg_catalog.jsonb_build_object(
        'result_hash',pg_catalog.encode(v_result_hash,'hex'),'provider_message_id',v_provider_message_id
      ),bounded_error_json=v_error
  where id=v_attempt.id;
  if v_outcome='ACCEPTED' then
    update public.weekly_message_dispatch_commands
    set state='ACCEPTED',provider_message_id=v_provider_message_id,
        provider_accepted_at_utc=pg_catalog.transaction_timestamp(),
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_command.id;
    update public.weekly_message_renders set state='ACCEPTED' where id=v_render.id;
    update public.weekly_message_intents set state='DISPATCHED' where id=v_intent.id;
    if v_intent.audience_kind='MANAGER' then
      update public.weekly_discrepancy_incidents incident
      set manager_action_state='SENT'
      from public.weekly_manager_review_items item
      join public.weekly_manager_review_batches batch on batch.id=item.review_batch_id
      where batch.message_render_id=v_render.id and item.incident_id=incident.id
        and item.response_state='UNANSWERED' and incident.manager_action_state='DUE';
    elsif v_intent.audience_kind='CANDIDATE' then
      insert into public.weekly_discrepancy_events(
        incident_id,issue_episode,projection_publication_id,
        expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,
        idempotency_key
      )
      select incident.id,incident.episode_number,v_command.projection_publication_id,
        comparison.material_comparison_fingerprint,'REMINDER_SENT','SYSTEM',
        pg_catalog.jsonb_build_object('tranche_kind',v_command.tranche_kind),
        'CANDIDATE_MESSAGE_ACCEPTED:'||v_command.id::text||':'||incident.id::text
      from public.weekly_candidate_outreach_memberships membership
      join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
      join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      where membership.candidate_generation_id=v_command.candidate_generation_id
        and membership.state='ACTIONABLE'
      on conflict (event_kind,idempotency_key) do nothing;
    end if;
  elsif v_outcome='AMBIGUOUS' then
    update public.weekly_message_dispatch_commands set state='AMBIGUOUS',lease_owner=null,
      lease_token=null,lease_expires_at_utc=null where id=v_command.id;
    update public.weekly_message_renders set state='AMBIGUOUS' where id=v_render.id;
  else
    update public.weekly_message_dispatch_commands
    set state=case when v_outcome='TRANSIENT_FAILURE' then 'FAILED' else 'RETIRED' end,
      next_attempt_at_utc=case when v_outcome='TRANSIENT_FAILURE'
      then pg_catalog.transaction_timestamp()+pg_catalog.make_interval(secs=>least(3600,30*(2^least(attempt_count,7))::integer))
      else null end,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_command.id;
    update public.weekly_message_renders
    set state=case when v_outcome='TRANSIENT_FAILURE' then 'CURRENT' else 'DEFINITELY_REJECTED' end
    where id=v_render.id;
    if v_outcome='DEFINITELY_REJECTED' then
      update public.weekly_message_intents set state='RETIRED' where id=v_intent.id;
    end if;
  end if;
  return pg_catalog.jsonb_build_object('ok',true,'replay',false,'outcome',v_outcome);
end;
$function$;

create or replace function public.weekly_source_manager_route_prepare_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_intent_id uuid;
  v_publication_id uuid;
  v_intent public.weekly_message_intents%rowtype;
  v_generation public.weekly_manager_recipient_generations%rowtype;
  v_route public.weekly_manager_recipient_routes%rowtype;
  v_input jsonb;
  v_membership_hash bytea;
  v_preparation public.weekly_manager_route_preparations%rowtype;
  v_sequence integer;
  v_credential_generation integer;
  v_issued_at timestamptz;
  v_secure_link_lifetime interval;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('message_intent_id','projection_publication_id')) then
    raise exception 'WEEKLY_SOURCE_MANAGER_ROUTE_PREPARE_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_intent_id:=(p_request->>'message_intent_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_MANAGER_ROUTE_PREPARE_REQUEST_INVALID' using errcode='22023';
  end;

  select * into strict v_intent from public.weekly_message_intents
  where id=v_intent_id for update;
  if v_intent.audience_kind<>'MANAGER' then
    raise exception 'WEEKLY_SOURCE_MANAGER_ROUTE_PREPARE_AUDIENCE_INVALID' using errcode='22023';
  end if;
  if v_intent.state='RENDERED' then
    select * into strict v_preparation
    from public.weekly_manager_route_preparations
    where message_intent_id=v_intent.id and state='BOUND';
    if v_preparation.projection_publication_id<>v_publication_id then
      raise exception 'WEEKLY_SOURCE_MANAGER_ROUTE_PREPARE_REPLAY_CONFLICT' using errcode='23505';
    end if;
    select * into strict v_route from public.weekly_manager_recipient_routes
    where id=v_intent.recipient_route_id;
    return pg_catalog.jsonb_build_object(
      'ok',true,'replay',true,'state',v_preparation.state,
      'manager_route_preparation_id',v_preparation.id,
      'review_batch_id',v_preparation.review_batch_id,
      'recipient_generation_id',v_preparation.recipient_generation_id,
      'credential_generation',v_preparation.credential_generation,
      'membership_hash',pg_catalog.encode(v_preparation.original_membership_hash,'hex'),
      'issued_at_utc',v_preparation.issued_at_utc,'expires_at_utc',v_preparation.expires_at_utc,
      'environment',v_route.environment,'agency_id',v_route.agency_id,
      'manager_address',v_route.protected_recipient_address
    );
  end if;
  if v_intent.state<>'DUE' then
    raise exception 'WEEKLY_SOURCE_MESSAGE_INTENT_STALE' using errcode='40001';
  end if;
  perform private.weekly_source_query_current_publication_v1(v_intent.source_cycle_id,v_publication_id);
  select * into strict v_generation from public.weekly_manager_recipient_generations
  where id=v_intent.recipient_generation_id for update;
  select * into strict v_route from public.weekly_manager_recipient_routes
  where id=v_intent.recipient_route_id for update;
  if v_generation.state<>'ACTIVE' or v_route.current_generation_id<>v_generation.id
     or v_generation.recipient_route_id<>v_route.id then
    raise exception 'WEEKLY_SOURCE_MANAGER_MESSAGE_STALE' using errcode='40001';
  end if;

  v_input:=public.weekly_source_message_render_input_v1(pg_catalog.jsonb_build_object(
    'message_intent_id',v_intent.id,'projection_publication_id',v_publication_id
  ));
  v_membership_hash:=private.weekly_source_query_hex32_v1(
    v_input->>'membership_hash','WEEKLY_SOURCE_RENDER_MEMBERSHIP_HASH_INVALID'
  );

  select * into v_preparation
  from public.weekly_manager_route_preparations
  where message_intent_id=v_intent.id and state in ('PREPARED','BOUND')
  for update;
  if found then
    if v_preparation.state<>'PREPARED'
       or v_preparation.projection_publication_id<>v_publication_id
       or v_preparation.recipient_generation_id<>v_generation.id
       or v_preparation.original_membership_hash<>v_membership_hash then
      raise exception 'WEEKLY_SOURCE_MANAGER_ROUTE_PREPARE_REPLAY_CONFLICT' using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'replay',true,'state',v_preparation.state,
      'manager_route_preparation_id',v_preparation.id,
      'review_batch_id',v_preparation.review_batch_id,
      'recipient_generation_id',v_preparation.recipient_generation_id,
      'credential_generation',v_preparation.credential_generation,
      'membership_hash',pg_catalog.encode(v_preparation.original_membership_hash,'hex'),
      'issued_at_utc',v_preparation.issued_at_utc,'expires_at_utc',v_preparation.expires_at_utc,
      'environment',v_route.environment,'agency_id',v_route.agency_id,
      'manager_address',v_route.protected_recipient_address
    );
  end if;

  select coalesce(pg_catalog.max(preparation_sequence),0)+1 into v_sequence
  from public.weekly_manager_route_preparations where message_intent_id=v_intent.id;
  select coalesce(pg_catalog.max(number),0)+1 into v_credential_generation
  from (
    select batch.credential_generation as number
    from public.weekly_manager_review_batches batch
    where batch.recipient_generation_id=v_generation.id
    union all
    select preparation.credential_generation
    from public.weekly_manager_route_preparations preparation
    where preparation.recipient_generation_id=v_generation.id
  ) generations;
  v_issued_at:=pg_catalog.transaction_timestamp();
  select settings.manager_secure_link_lifetime
  into strict v_secure_link_lifetime
  from public.weekly_source_global_settings settings
  where settings.singleton;
  insert into public.weekly_manager_route_preparations(
    message_intent_id,projection_publication_id,recipient_generation_id,
    preparation_sequence,review_batch_id,credential_generation,
    original_membership_hash,issued_at_utc,expires_at_utc,state
  ) values (
    v_intent.id,v_publication_id,v_generation.id,v_sequence,
    pg_catalog.gen_random_uuid(),v_credential_generation,v_membership_hash,
    v_issued_at,v_issued_at+v_secure_link_lifetime,'PREPARED'
  ) returning * into v_preparation;
  return pg_catalog.jsonb_build_object(
    'ok',true,'replay',false,'state',v_preparation.state,
    'manager_route_preparation_id',v_preparation.id,
    'review_batch_id',v_preparation.review_batch_id,
    'recipient_generation_id',v_preparation.recipient_generation_id,
    'credential_generation',v_preparation.credential_generation,
    'membership_hash',pg_catalog.encode(v_preparation.original_membership_hash,'hex'),
    'issued_at_utc',v_preparation.issued_at_utc,'expires_at_utc',v_preparation.expires_at_utc,
    'environment',v_route.environment,'agency_id',v_route.agency_id,
    'manager_address',v_route.protected_recipient_address
  );
exception when no_data_found or too_many_rows then
  raise exception 'WEEKLY_SOURCE_MANAGER_ROUTE_PREPARE_STALE' using errcode='40001';
end;
$function$;

create or replace function public.weekly_source_message_render_stage_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_intent_id uuid;
  v_publication_id uuid;
  v_intent public.weekly_message_intents%rowtype;
  v_subject text;
  v_html text;
  v_plain text;
  v_policy_version text;
  v_renderer_version text;
  v_structure_version text;
  v_membership jsonb;
  v_membership_hash bytea;
  v_expected_hash bytea;
  v_content_hash bytea;
  v_trigger_hash bytea;
  v_render public.weekly_message_renders%rowtype;
  v_command public.weekly_message_dispatch_commands%rowtype;
  v_render_sequence integer;
  v_generation public.weekly_manager_recipient_generations%rowtype;
  v_candidate_generation public.weekly_candidate_outreach_generations%rowtype;
  v_route public.weekly_manager_recipient_routes%rowtype;
  v_batch public.weekly_manager_review_batches%rowtype;
  v_receipt public.weekly_manager_route_receipts%rowtype;
  v_preparation public.weekly_manager_route_preparations%rowtype;
  v_item jsonb;
  v_credential_hash bytea;
  v_credential_generation integer;
  v_control_ticket uuid;
  v_agency_receipt uuid;
  v_data_plane_identity text;
  v_route_version text;
  v_credential_version text;
  v_client_count integer;
  v_candidate_count integer;
  v_shift_count integer;
  v_provider_key text;
  v_command_key bytea;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in (
                 'message_intent_id','projection_publication_id','membership_hash',
                 'policy_version','renderer_version','structure_version',
                 'subject_text','html_body','plain_body','expected_rendered_content_hash',
                 'credential_hash','control_plane_ticket_id','agency_receipt_id',
                 'data_plane_identity','route_version','credential_version',
                 'manager_route_preparation_id'
               )) then
    raise exception 'WEEKLY_SOURCE_MESSAGE_RENDER_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_intent_id:=(p_request->>'message_intent_id')::uuid;
    v_publication_id:=nullif(p_request->>'projection_publication_id','')::uuid;
    v_subject:=nullif(p_request->>'subject_text','');
    v_html:=nullif(p_request->>'html_body','');
    v_plain:=p_request->>'plain_body';
    v_policy_version:=p_request->>'policy_version';
    v_renderer_version:=p_request->>'renderer_version';
    v_structure_version:=nullif(p_request->>'structure_version','');
    v_expected_hash:=case when nullif(p_request->>'expected_rendered_content_hash','') is null
      then null else private.weekly_source_query_hex32_v1(
        p_request->>'expected_rendered_content_hash','WEEKLY_SOURCE_RENDER_HASH_INVALID'
      ) end;
  exception when others then
    raise exception 'WEEKLY_SOURCE_MESSAGE_RENDER_REQUEST_INVALID' using errcode='22023';
  end;
  if v_plain is null or v_policy_version is null or v_renderer_version is null
     or pg_catalog.length(v_plain)>200000 or pg_catalog.length(coalesce(v_html,''))>1000000
     or pg_catalog.length(coalesce(v_subject,''))>300
     or (coalesce(v_subject,'')||' '||coalesce(v_html,'')||' '||v_plain)
        ~* '(^|[^[:alnum:]_])(pay|charge|rate|vat|invoice|banking|import|source|fingerprint|generation|incident|projection)([^[:alnum:]_]|$)' then
    raise exception 'WEEKLY_SOURCE_MESSAGE_CONTENT_INVALID' using errcode='22023';
  end if;
  select * into strict v_intent from public.weekly_message_intents
  where id=v_intent_id for update;
  if v_intent.state='RENDERED' then
    select render.* into strict v_render from public.weekly_message_renders render
    where render.message_intent_id=v_intent.id and render.state='CURRENT';
    select command.* into strict v_command from public.weekly_message_dispatch_commands command
    where command.message_render_id=v_render.id and command.state<>'RETIRED';
    if v_render.projection_publication_id is distinct from v_publication_id
       or v_render.membership_hash<>private.weekly_source_query_hex32_v1(
         p_request->>'membership_hash','WEEKLY_SOURCE_RENDER_MEMBERSHIP_HASH_INVALID'
       )
       or v_render.policy_version<>v_policy_version
       or v_render.renderer_version<>v_renderer_version
       or v_render.subject_text is distinct from v_subject
       or v_render.html_body is distinct from v_html
       or v_render.plain_body is distinct from v_plain
       or (v_expected_hash is not null and v_render.rendered_content_hash<>v_expected_hash) then
      raise exception 'WEEKLY_SOURCE_MESSAGE_RENDER_REPLAY_CONFLICT' using errcode='23505';
    end if;
    if v_intent.audience_kind='MANAGER' then
      begin
        select * into strict v_preparation
        from public.weekly_manager_route_preparations
        where id=(p_request->>'manager_route_preparation_id')::uuid
          and message_intent_id=v_intent.id and state='BOUND';
        v_credential_hash:=private.weekly_source_query_hex32_v1(
          p_request->>'credential_hash','WEEKLY_SOURCE_MANAGER_CREDENTIAL_HASH_INVALID'
        );
        v_control_ticket:=(p_request->>'control_plane_ticket_id')::uuid;
        v_agency_receipt:=(p_request->>'agency_receipt_id')::uuid;
        v_data_plane_identity:=p_request->>'data_plane_identity';
        v_route_version:=p_request->>'route_version';
        v_credential_version:=p_request->>'credential_version';
      exception when others then
        raise exception 'WEEKLY_SOURCE_MANAGER_ROUTE_AUTHORITY_INVALID' using errcode='22023';
      end;
      select * into strict v_batch from public.weekly_manager_review_batches
      where message_render_id=v_render.id;
      select * into strict v_receipt from public.weekly_manager_route_receipts
      where review_batch_id=v_batch.id;
      if v_batch.policy_version<>v_policy_version
         or v_batch.renderer_version<>v_renderer_version
         or v_batch.structure_version is distinct from v_structure_version
         or v_batch.control_plane_ticket_id<>v_control_ticket
         or v_batch.agency_receipt_id<>v_agency_receipt
         or v_batch.opaque_credential_hash<>v_credential_hash
         or v_batch.id<>v_preparation.review_batch_id
         or v_batch.credential_generation<>v_preparation.credential_generation
         or v_batch.original_membership_hash<>v_preparation.original_membership_hash
         or v_receipt.data_plane_identity<>v_data_plane_identity
         or v_receipt.route_version<>v_route_version
         or v_receipt.credential_version<>v_credential_version then
        raise exception 'WEEKLY_SOURCE_MESSAGE_RENDER_REPLAY_CONFLICT' using errcode='23505';
      end if;
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'replay',true,'message_render_id',v_render.id,
      'dispatch_command_id',v_command.id,
      'review_batch_id',(select batch.id from public.weekly_manager_review_batches batch
                         where batch.message_render_id=v_render.id)
    );
  end if;
  if v_intent.state<>'DUE' then
    raise exception 'WEEKLY_SOURCE_MESSAGE_INTENT_STALE' using errcode='40001';
  end if;
  perform private.weekly_source_query_current_publication_v1(v_intent.source_cycle_id,v_publication_id);

  if v_intent.audience_kind='CANDIDATE' then
    select * into strict v_candidate_generation
    from public.weekly_candidate_outreach_generations
    where id=v_intent.candidate_generation_id;
    if v_candidate_generation.state<>'ACTIVE'
       or not exists(select 1 from public.weekly_candidate_cohorts cohort
                     where cohort.id=v_candidate_generation.candidate_cohort_id
                       and private.weekly_source_candidate_generation_current_v1(v_candidate_generation.id)) then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_MESSAGE_STALE' using errcode='40001';
    end if;
    v_membership_hash:=v_candidate_generation.membership_hash;
    if v_subject is not null or v_html is not null then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_PUSH_CONTENT_INVALID' using errcode='22023';
    end if;
  elsif v_intent.audience_kind='MANAGER' then
    select * into strict v_generation from public.weekly_manager_recipient_generations
    where id=v_intent.recipient_generation_id;
    select * into strict v_route from public.weekly_manager_recipient_routes
    where id=v_intent.recipient_route_id for update;
    if v_generation.state<>'ACTIVE' or v_route.current_generation_id<>v_generation.id then
      raise exception 'WEEKLY_SOURCE_MANAGER_MESSAGE_STALE' using errcode='40001';
    end if;
    if v_policy_version<>'1.8.0' or v_renderer_version<>'1.4.0'
       or v_structure_version<>'1.0.0' or v_subject is null or v_html is null then
      raise exception 'WEEKLY_SOURCE_MANAGER_RENDER_POLICY_INVALID' using errcode='22023';
    end if;
    v_membership:=coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'incident_id',ranked.incident_id,
          'incident_episode',ranked.episode_number,
          'comparison_revision_id',ranked.comparison_revision_id,
          'comparison_fingerprint',pg_catalog.encode(ranked.comparison_fingerprint,'hex'),
          'client_order',ranked.client_order,
          'candidate_order',ranked.candidate_order,
          'shift_order',ranked.shift_order
        ) order by ranked.client_order,ranked.candidate_order,ranked.shift_order
      )
      from (
        select incident.id as incident_id,incident.episode_number,
          comparison.id as comparison_revision_id,
          comparison.material_comparison_fingerprint as comparison_fingerprint,
          pg_catalog.dense_rank() over(order by private.weekly_source_query_ascii_fold_v1(client.name) collate "C",client.id)::integer as client_order,
          pg_catalog.dense_rank() over(partition by client.id order by private.weekly_source_query_ascii_fold_v1(coalesce(nullif(candidate.display_name,''),pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name))) collate "C",candidate.id)::integer as candidate_order,
          pg_catalog.row_number() over(partition by client.id,candidate.id order by work_event.work_date,coalesce(comparison.system_start_at_local,comparison.candidate_start_at_local),incident.id)::integer as shift_order
        from public.weekly_manager_recipient_memberships membership
        join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
        join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
        join public.weekly_work_events work_event on work_event.id=incident.work_event_id
        join public.clients client on client.id=incident.client_id
        join public.candidates candidate on candidate.id=incident.candidate_id
        where membership.recipient_generation_id=v_generation.id
          and incident.state='OPEN' and incident.manager_action_state<>'RESPONDED'
          and not private.weekly_source_covered_hours_incident_v1(incident.id)
          and (
            coalesce(pg_catalog.array_length(v_intent.sorted_due_event_ids,1),0)=0
            or membership.candidate_cohort_id=any(
              select event.candidate_cohort_id from public.weekly_manager_cohort_due_events event
              where event.id=any(v_intent.sorted_due_event_ids)
                and event.recipient_generation_id=v_generation.id
                and private.weekly_source_manager_due_event_covers_v1(event.id,incident.id)
            )
          )
          and (v_intent.tranche_kind<>'MANAGER_T6_RESPONDED' or incident.candidate_action_state='RESPONDED')
          and not private.weekly_source_query_manager_row_owned_v1(
            v_generation.recipient_route_id,incident.id,incident.episode_number
          )
      ) ranked
    ),'[]'::jsonb);
    v_shift_count:=pg_catalog.jsonb_array_length(v_membership);
    if v_shift_count=0 then
      raise exception 'WEEKLY_SOURCE_MANAGER_RENDER_EMPTY' using errcode='55000';
    end if;
    select pg_catalog.count(distinct incident.client_id),
           pg_catalog.count(distinct incident.candidate_id)
    into v_client_count,v_candidate_count
    from pg_catalog.jsonb_array_elements(v_membership) member
    join public.weekly_discrepancy_incidents incident on incident.id=(member->>'incident_id')::uuid;
    if v_client_count>100 or v_candidate_count>100 or v_shift_count>500 then
      raise exception 'WEEKLY_SOURCE_MANAGER_DIGEST_CAPACITY_EXCEEDED' using errcode='54000';
    end if;
    if v_subject<>pg_catalog.format(
      'Timesheet queries requiring your review - %s %s',v_shift_count,
      case when v_shift_count=1 then 'shift' else 'shifts' end
    ) then
      raise exception 'WEEKLY_SOURCE_MANAGER_SUBJECT_INVALID' using errcode='22023';
    end if;
    v_membership_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_MANAGER_REVIEW_BATCH_MEMBERSHIP_V1',v_membership
    );
    begin
      select * into strict v_preparation
      from public.weekly_manager_route_preparations
      where id=(p_request->>'manager_route_preparation_id')::uuid
        and message_intent_id=v_intent.id and state='PREPARED'
      for update;
      v_credential_hash:=private.weekly_source_query_hex32_v1(
        p_request->>'credential_hash','WEEKLY_SOURCE_MANAGER_CREDENTIAL_HASH_INVALID'
      );
      v_control_ticket:=(p_request->>'control_plane_ticket_id')::uuid;
      v_agency_receipt:=(p_request->>'agency_receipt_id')::uuid;
      v_data_plane_identity:=p_request->>'data_plane_identity';
      v_route_version:=p_request->>'route_version';
      v_credential_version:=p_request->>'credential_version';
    exception when others then
      raise exception 'WEEKLY_SOURCE_MANAGER_ROUTE_AUTHORITY_INVALID' using errcode='22023';
    end;
    if nullif(v_data_plane_identity,'') is null or nullif(v_route_version,'') is null
       or nullif(v_credential_version,'') is null then
      raise exception 'WEEKLY_SOURCE_MANAGER_ROUTE_AUTHORITY_INVALID' using errcode='22023';
    end if;
    if v_preparation.projection_publication_id<>v_publication_id
       or v_preparation.recipient_generation_id<>v_generation.id
       or v_preparation.original_membership_hash<>v_membership_hash
       or v_preparation.expires_at_utc<=pg_catalog.transaction_timestamp() then
      raise exception 'WEEKLY_SOURCE_MANAGER_ROUTE_PREPARATION_STALE' using errcode='40001';
    end if;
  else
    raise exception 'WEEKLY_SOURCE_MESSAGE_AUDIENCE_UNSUPPORTED' using errcode='55000';
  end if;
  if v_membership_hash<>private.weekly_source_query_hex32_v1(
    p_request->>'membership_hash','WEEKLY_SOURCE_RENDER_MEMBERSHIP_HASH_INVALID'
  ) then
    raise exception 'WEEKLY_SOURCE_RENDER_MEMBERSHIP_STALE' using errcode='40001';
  end if;
  v_content_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_MESSAGE_RENDER_V1',pg_catalog.jsonb_build_object(
      'message_intent_id',v_intent.id,'projection_publication_id',v_publication_id,
      'membership_hash',pg_catalog.encode(v_membership_hash,'hex'),
      'policy_version',v_policy_version,'renderer_version',v_renderer_version,
      'structure_version',v_structure_version,'subject_text',v_subject,
      'html_body',v_html,'plain_body',v_plain
    )
  );
  if v_expected_hash is not null and v_expected_hash<>v_content_hash then
    raise exception 'WEEKLY_SOURCE_RENDER_HASH_MISMATCH' using errcode='40001';
  end if;
  select coalesce(pg_catalog.max(render_sequence),0)+1 into v_render_sequence
  from public.weekly_message_renders where message_intent_id=v_intent.id;
  v_provider_key:='weekly-source/'||pg_catalog.encode(v_content_hash,'hex');
  insert into public.weekly_message_renders(
    message_intent_id,render_sequence,projection_publication_id,membership_hash,
    policy_version,renderer_version,subject_text,html_body,plain_body,
    rendered_content_hash,provider_idempotency_key,state
  ) values (
    v_intent.id,v_render_sequence,v_publication_id,v_membership_hash,
    v_policy_version,v_renderer_version,v_subject,v_html,v_plain,
    v_content_hash,v_provider_key,'CURRENT'
  ) returning * into v_render;

  if v_intent.audience_kind='MANAGER' then
    v_credential_generation:=v_preparation.credential_generation;
    insert into public.weekly_manager_review_batches(
      id,recipient_generation_id,message_render_id,policy_version,renderer_version,
      structure_version,sent_content_hash,original_membership_hash,
      control_plane_ticket_id,agency_receipt_id,credential_generation,
      opaque_credential_hash,issued_at_utc,expires_at_utc,state,send_sequence
    ) values (
      v_preparation.review_batch_id,v_generation.id,v_render.id,v_policy_version,v_renderer_version,
      v_structure_version,v_content_hash,v_membership_hash,
      v_control_ticket,v_agency_receipt,v_credential_generation,v_credential_hash,
      v_preparation.issued_at_utc,v_preparation.expires_at_utc,
      'ACTIVE',v_intent.tranche_sequence
    ) returning * into v_batch;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_membership)
    loop
      insert into public.weekly_manager_review_items(
        review_batch_id,incident_id,incident_episode,sent_comparison_revision_id,
        sent_comparison_fingerprint,client_order,candidate_order,shift_order,response_state
      ) values (
        v_batch.id,(v_item->>'incident_id')::uuid,(v_item->>'incident_episode')::integer,
        (v_item->>'comparison_revision_id')::uuid,
        pg_catalog.decode(v_item->>'comparison_fingerprint','hex'),
        (v_item->>'client_order')::integer,(v_item->>'candidate_order')::integer,
        (v_item->>'shift_order')::integer,'UNANSWERED'
      );
    end loop;
    insert into public.weekly_manager_route_receipts(
      review_batch_id,recipient_generation_id,control_plane_ticket_id,environment,
      agency_id,data_plane_identity,route_version,credential_version,
      original_membership_hash,credential_generation,credential_hash,
      issued_at_utc,expires_at_utc,semantic_hash,state
    ) values (
      v_batch.id,v_generation.id,v_control_ticket,v_route.environment,v_route.agency_id,
      v_data_plane_identity,v_route_version,v_credential_version,v_membership_hash,
      v_credential_generation,v_credential_hash,v_batch.issued_at_utc,v_batch.expires_at_utc,
      private.weekly_source_sha256_jsonb_v1('WEEKLY_MANAGER_ROUTE_RECEIPT_V1',
        pg_catalog.jsonb_build_object(
          'review_batch_id',v_batch.id,'recipient_generation_id',v_generation.id,
          'control_plane_ticket_id',v_control_ticket,'agency_receipt_id',v_agency_receipt,
          'membership_hash',pg_catalog.encode(v_membership_hash,'hex'),
          'credential_generation',v_credential_generation
        )),'ACTIVE'
    ) returning * into v_receipt;
    update public.weekly_manager_route_preparations
    set state='BOUND',bound_at_utc=pg_catalog.transaction_timestamp()
    where id=v_preparation.id;
  end if;
  v_trigger_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_MESSAGE_TRIGGER_EVENTS_V1',pg_catalog.to_jsonb(v_intent.sorted_due_event_ids)
  );
  v_command_key:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_MESSAGE_DISPATCH_COMMAND_V1',pg_catalog.jsonb_build_object(
      'message_intent_id',v_intent.id,'message_render_id',v_render.id,
      'rendered_content_hash',pg_catalog.encode(v_content_hash,'hex')
    )
  );
  insert into public.weekly_message_dispatch_commands(
    message_intent_id,message_render_id,environment,agency_id,source_cycle_id,
    recipient_route_id,candidate_generation_id,tranche_kind,tranche_sequence,
    sorted_trigger_event_hash,membership_hash,policy_version,logical_key,state,
    next_attempt_at_utc,projection_publication_id,rendered_content_hash
  ) values (
    v_intent.id,v_render.id,v_intent.environment,v_intent.agency_id,v_intent.source_cycle_id,
    v_intent.recipient_route_id,v_intent.candidate_generation_id,v_intent.tranche_kind,
    v_intent.tranche_sequence,v_trigger_hash,v_membership_hash,v_policy_version,
    v_command_key,'READY',pg_catalog.transaction_timestamp(),v_publication_id,v_content_hash
  ) returning * into v_command;
  update public.weekly_message_intents set state='RENDERED' where id=v_intent.id;
  return pg_catalog.jsonb_build_object(
    'ok',true,'replay',false,'message_render_id',v_render.id,
    'rendered_content_hash',pg_catalog.encode(v_content_hash,'hex'),
    'dispatch_command_id',v_command.id,'review_batch_id',v_batch.id,
    'manager_route_receipt_id',v_receipt.id,
    'manager_route_preparation_id',v_preparation.id
  );
end;
$function$;

create or replace function public.weekly_source_query_scheduler_tick_v1(
  p_request jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_now timestamptz;
  v_limit integer;
  v_generation public.weekly_candidate_outreach_generations%rowtype;
  v_tranche text;
  v_intent_id uuid;
  v_candidate_count integer:=0;
  v_overdue_count integer:=0;
  v_manager_count integer:=0;
  v_route record;
  v_event_ids uuid[];
  v_due_kind text;
  v_manager_tranche text;
  v_actionable integer;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('now_utc','limit')) then
    raise exception 'WEEKLY_SOURCE_SCHEDULER_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_now:=coalesce(nullif(p_request->>'now_utc','')::timestamptz,pg_catalog.transaction_timestamp());
    v_limit:=coalesce(nullif(p_request->>'limit','')::integer,250);
  exception when others then
    raise exception 'WEEKLY_SOURCE_SCHEDULER_REQUEST_INVALID' using errcode='22023';
  end;
  if v_limit<1 or v_limit>1000 then
    raise exception 'WEEKLY_SOURCE_SCHEDULER_LIMIT_INVALID' using errcode='22023';
  end if;

  for v_generation in
    select generation.*
    from public.weekly_candidate_outreach_generations generation
    where generation.state='ACTIVE' and generation.reminder_due_at_utc<=v_now
      and exists(
        select 1 from public.weekly_message_intents intent
        where intent.candidate_generation_id=generation.id
          and intent.tranche_kind in ('CANDIDATE_INITIAL','TIMESHEET_SUBMISSION_INITIAL')
      )
      and not exists(
        select 1 from public.weekly_message_intents intent
        where intent.candidate_generation_id=generation.id
          and intent.tranche_kind in ('CANDIDATE_REMINDER_6H','TIMESHEET_SUBMISSION_REMINDER_6H')
      )
      and (
        (generation.request_kind='CHECK_HOURS' and exists(
          select 1 from public.weekly_candidate_outreach_memberships membership
          join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
          where membership.candidate_generation_id=generation.id and membership.state='ACTIONABLE'
            and incident.state='OPEN'
            and not private.weekly_source_covered_hours_incident_v1(incident.id)
        ))
        or
        (generation.request_kind='SUBMIT_TIMESHEET' and exists(
          select 1 from public.weekly_timesheet_submission_requests submission
          where submission.candidate_cohort_id=generation.candidate_cohort_id
            and submission.state in ('ACTIVE','PARTLY_SUBMITTED')
        ))
      )
    order by generation.reminder_due_at_utc,generation.id
    limit v_limit
    for update skip locked
  loop
    v_tranche:=case when v_generation.request_kind='SUBMIT_TIMESHEET'
      then 'TIMESHEET_SUBMISSION_REMINDER_6H' else 'CANDIDATE_REMINDER_6H' end;
    v_intent_id:=private.weekly_source_query_candidate_intent_v1(
      v_generation.id,v_tranche,1,v_generation.reminder_due_at_utc
    );
    if v_generation.request_kind='CHECK_HOURS' then
      insert into public.weekly_discrepancy_events(
        incident_id,issue_episode,projection_publication_id,
        expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,
        idempotency_key,occurred_at_utc
      )
      select incident.id,incident.episode_number,comparison.projection_publication_id,
        comparison.material_comparison_fingerprint,'REMINDER_DUE','SYSTEM',
        pg_catalog.jsonb_build_object('candidate_generation_id',v_generation.id),
        'CANDIDATE_REMINDER_DUE:'||v_generation.id::text||':'||incident.id::text,
        v_generation.reminder_due_at_utc
      from public.weekly_candidate_outreach_memberships membership
      join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
      join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      where membership.candidate_generation_id=v_generation.id and membership.state='ACTIONABLE'
        and incident.state='OPEN'
        and not private.weekly_source_covered_hours_incident_v1(incident.id)
      on conflict (event_kind,idempotency_key) do nothing;
    end if;
    v_candidate_count:=v_candidate_count+1;
  end loop;

  update public.weekly_timesheet_submission_requests submission
  set state='OVERDUE',updated_at_utc=v_now
  where submission.state in ('ACTIVE','PARTLY_SUBMITTED') and submission.deadline_at_utc<=v_now;
  get diagnostics v_overdue_count=row_count;

  for v_route in
    select route.id as route_id,generation.id as generation_id,event.event_kind,
           pg_catalog.min(event.due_at_utc) as first_due
    from public.weekly_manager_recipient_routes route
    join public.weekly_manager_recipient_generations generation
      on generation.id=route.current_generation_id and generation.state='ACTIVE'
    join public.weekly_manager_cohort_due_events event
      on event.recipient_generation_id=generation.id
     and event.state='PENDING' and event.due_at_utc<=v_now
    group by route.id,generation.id,event.event_kind
    order by pg_catalog.min(event.due_at_utc),route.id,event.event_kind
    limit v_limit
  loop
    if exists(
      select 1 from public.weekly_message_intents intent
      where intent.recipient_generation_id=v_route.generation_id
        and intent.state in ('DUE','RENDERED')
    ) then
      continue;
    end if;
    v_due_kind:=v_route.event_kind;
    select pg_catalog.array_agg(locked_event.id order by locked_event.due_at_utc,locked_event.id)
    into v_event_ids
    from (
      select event.id,event.due_at_utc
      from public.weekly_manager_cohort_due_events event
      where event.recipient_generation_id=v_route.generation_id
        and event.event_kind=v_due_kind and event.state='PENDING' and event.due_at_utc<=v_now
      order by event.due_at_utc,event.id
      for update
    ) locked_event;
    if coalesce(pg_catalog.array_length(v_event_ids,1),0)=0 then continue; end if;
    select pg_catalog.count(*) into v_actionable
    from public.weekly_manager_recipient_memberships membership
    join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
    where membership.recipient_generation_id=v_route.generation_id
      and membership.candidate_cohort_id=any(
        select event.candidate_cohort_id
        from public.weekly_manager_cohort_due_events event where event.id=any(v_event_ids)
          and private.weekly_source_manager_due_event_covers_v1(event.id,incident.id)
      )
      and incident.state='OPEN' and incident.manager_action_state<>'RESPONDED'
      and (
        v_due_kind<>'T6_RESPONDED'
        or incident.candidate_action_state='RESPONDED'
      )
      and not private.weekly_source_query_manager_row_owned_v1(
        v_route.route_id,incident.id,incident.episode_number
      );
    if v_actionable>0 then
      v_manager_tranche:=case v_due_kind
        when 'EARLY_ALL' then 'MANAGER_EARLY_ALL'
        when 'T6_RESPONDED' then 'MANAGER_T6_RESPONDED'
        else 'MANAGER_T12_REMAINDER' end;
      v_intent_id:=private.weekly_source_query_manager_intent_v1(
        v_route.route_id,v_route.generation_id,v_event_ids,v_manager_tranche,1,v_route.first_due
      );
      -- 04A section 6.1 makes only an "unanswered and unsent" row due.  A row an
      -- accepted batch still owns is neither, so it keeps its SENT state and the
      -- Office screen keeps saying `Manager informed`.
      update public.weekly_discrepancy_incidents incident set manager_action_state='DUE'
      from public.weekly_manager_recipient_memberships membership
      where membership.recipient_generation_id=v_route.generation_id
        and membership.incident_id=incident.id
        and membership.candidate_cohort_id=any(
          select event.candidate_cohort_id from public.weekly_manager_cohort_due_events event
          where event.id=any(v_event_ids)
            and private.weekly_source_manager_due_event_covers_v1(event.id,incident.id)
        ) and incident.manager_action_state in ('NOT_SENT','SENT')
        and not private.weekly_source_query_manager_row_owned_v1(
          v_route.route_id,incident.id,incident.episode_number
        );
      v_manager_count:=v_manager_count+1;
    end if;
    update public.weekly_manager_cohort_due_events set state='CONSUMED'
    where id=any(v_event_ids);
  end loop;
  return pg_catalog.jsonb_build_object(
    'ok',true,'now_utc',v_now,'candidate_reminder_intents',v_candidate_count,
    'timesheet_requests_marked_overdue',v_overdue_count,
    'manager_digest_intents',v_manager_count
  );
end;
$function$;

create or replace function public.weekly_source_candidate_response_submit_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_candidate_id uuid;
  v_generation_id uuid;
  v_publication_id uuid;
  v_request_key uuid;
  v_responses jsonb;
  v_semantic_hash bytea;
  v_semantic_hex text;
  v_existing_count integer;
  v_existing_expected integer;
  v_existing_hash text;
  v_generation public.weekly_candidate_outreach_generations%rowtype;
  v_cohort public.weekly_candidate_cohorts%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_item jsonb;
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_comparison public.weekly_issue_comparison_revisions%rowtype;
  v_membership public.weekly_candidate_outreach_memberships%rowtype;
  v_choice text;
  v_expected bytea;
  v_current_timesheet_hash bytea;
  v_response_hash bytea;
  v_draft public.weekly_candidate_response_drafts%rowtype;
  v_draft_version integer;
  v_event_id uuid;
  v_answered integer:=0;
  v_resolved integer:=0;
  v_notices integer:=0;
  v_work public.weekly_work_events%rowtype;
  v_client public.clients%rowtype;
  v_candidate public.candidates%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_policy jsonb;
  v_summary text;
  v_recipient_generation_id uuid;
  v_recipient_route_id uuid;
  v_due_ids uuid[];
  v_intent_id uuid;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in (
                 'candidate_id','candidate_generation_id','projection_publication_id',
                 'request_idempotency_key','responses'
               ))
     or pg_catalog.jsonb_typeof(p_request->'responses')<>'array'
     or pg_catalog.jsonb_array_length(p_request->'responses')=0 then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_INVALID' using errcode='22023';
  end if;
  begin
    v_candidate_id:=(p_request->>'candidate_id')::uuid;
    v_generation_id:=(p_request->>'candidate_generation_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
    v_request_key:=(p_request->>'request_idempotency_key')::uuid;
    v_responses:=(
      select pg_catalog.jsonb_agg(value order by (value->>'incident_id')::uuid)
      from pg_catalog.jsonb_array_elements(p_request->'responses')
    );
  exception when others then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_INVALID' using errcode='22023';
  end;
  v_semantic_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_CANDIDATE_RESPONSE_REQUEST_V1',
    pg_catalog.jsonb_build_object(
      'candidate_id',v_candidate_id,'candidate_generation_id',v_generation_id,
      'projection_publication_id',v_publication_id,'responses',v_responses
    )
  );
  v_semantic_hex:=pg_catalog.encode(v_semantic_hash,'hex');

  -- Exact durable replay is deliberately checked before any mutable generation,
  -- publication, Timesheet or incident test.
  select pg_catalog.count(*),
         min(event.bounded_payload_json->>'request_item_count'),
         min(event.bounded_payload_json->>'request_semantic_hash')
  into v_existing_count,v_existing_expected,v_existing_hash
  from public.weekly_discrepancy_events event
  where event.event_kind='CANDIDATE_RESPONDED'
    and event.bounded_payload_json->>'request_idempotency_key'=v_request_key::text;
  if v_existing_count>0 then
    if v_existing_hash<>v_semantic_hex
       or v_existing_expected::integer<>pg_catalog.jsonb_array_length(v_responses)
       or v_existing_count<>v_existing_expected then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_REPLAY_CONFLICT' using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'replay',true,'request_idempotency_key',v_request_key,
      'answered_count',v_existing_count
    );
  end if;

  perform private.weekly_source_pay_query_admit_v2();
  select * into strict v_generation
  from public.weekly_candidate_outreach_generations
  where id=v_generation_id for update;
  if v_generation.state<>'ACTIVE' or v_generation.request_kind<>'CHECK_HOURS'
     or v_generation.candidate_id<>v_candidate_id
     or pg_catalog.transaction_timestamp()>v_generation.deadline_at_utc then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_GENERATION_STALE' using errcode='40001';
  end if;
  select * into strict v_cohort from public.weekly_candidate_cohorts
  where id=v_generation.candidate_cohort_id for update;
  if v_cohort.current_generation_id<>v_generation.id then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_GENERATION_STALE' using errcode='40001';
  end if;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_generation.source_cycle_id;
  perform private.weekly_source_query_current_publication_v1(v_cycle.id,v_publication_id);
  select * into strict v_group from public.weekly_source_groups where id=v_cycle.source_group_id;
  select * into strict v_candidate from public.candidates where id=v_candidate_id;
  select coalesce(pg_catalog.max(draft_version),0)+1 into v_draft_version
  from public.weekly_candidate_response_drafts where candidate_generation_id=v_generation.id;
  insert into public.weekly_candidate_response_drafts(
    candidate_generation_id,candidate_id,draft_version,current_projection_publication_id,
    state,draft_hash,submitted_at_utc
  ) values (
    v_generation.id,v_candidate_id,v_draft_version,v_publication_id,
    'SUBMITTED',v_semantic_hash,pg_catalog.transaction_timestamp()
  ) returning * into v_draft;

  for v_item in
    select value from pg_catalog.jsonb_array_elements(v_responses)
    order by (value->>'incident_id')::uuid
  loop
    if pg_catalog.jsonb_typeof(v_item)<>'object'
       or exists(select 1 from pg_catalog.jsonb_object_keys(v_item) key
                 where key not in (
                   'incident_id','expected_comparison_fingerprint','expected_timesheet_hash',
                   'choice','corrected_start_at_local','corrected_end_at_local','corrected_break_minutes'
                 )) then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_ITEM_INVALID' using errcode='22023';
    end if;
    begin
      select * into strict v_incident from public.weekly_discrepancy_incidents
      where id=(v_item->>'incident_id')::uuid for update;
      select * into strict v_membership from public.weekly_candidate_outreach_memberships
      where candidate_generation_id=v_generation.id and incident_id=v_incident.id
        and state='ACTIONABLE' for update;
      select * into strict v_comparison from public.weekly_issue_comparison_revisions
      where id=v_incident.current_comparison_revision_id;
    exception when no_data_found or invalid_text_representation then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_ITEM_STALE' using errcode='40001';
    end;
    if v_incident.state<>'OPEN' or v_incident.candidate_id<>v_candidate_id
       or v_incident.source_cycle_id<>v_cycle.id
       or private.weekly_source_covered_hours_incident_v1(v_incident.id) then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_ITEM_STALE' using errcode='40001';
    end if;
    v_expected:=private.weekly_source_query_hex32_v1(
      v_item->>'expected_comparison_fingerprint',
      'WEEKLY_SOURCE_CANDIDATE_RESPONSE_FINGERPRINT_INVALID'
    );
    if v_expected<>v_comparison.material_comparison_fingerprint then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_ITEM_STALE' using errcode='40001';
    end if;
    v_current_timesheet_hash:=private.weekly_source_query_candidate_timesheet_hash_v1(
      v_comparison.candidate_timesheet_id
    );
    if v_current_timesheet_hash is null
       or v_current_timesheet_hash<>private.weekly_source_query_hex32_v1(
         v_item->>'expected_timesheet_hash','WEEKLY_SOURCE_CANDIDATE_TIMESHEET_HASH_INVALID'
       ) then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_TIMESHEET_STALE' using errcode='40001';
    end if;
    v_choice:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_item->>'choice','')));
    if v_choice not in ('CANDIDATE_WRONG','CANDIDATE_CORRECT','NEITHER_CORRECT') then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_CHOICE_INVALID' using errcode='22023';
    end if;
    if (
      nullif(v_item->>'corrected_start_at_local','') is null
      or nullif(v_item->>'corrected_end_at_local','') is null
      or nullif(v_item->>'corrected_break_minutes','') is null
    ) and not (
      nullif(v_item->>'corrected_start_at_local','') is null
      and nullif(v_item->>'corrected_end_at_local','') is null
      and nullif(v_item->>'corrected_break_minutes','') is null
    ) then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_CORRECTED_HOURS_INVALID' using errcode='22023';
    end if;
    if v_choice='CANDIDATE_CORRECT' and
       nullif(v_item->>'corrected_start_at_local','') is not null then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_CORRECTED_HOURS_NOT_ALLOWED' using errcode='22023';
    end if;
    if v_choice='NEITHER_CORRECT' and
       nullif(v_item->>'corrected_start_at_local','') is null then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_CORRECTED_HOURS_REQUIRED' using errcode='22023';
    end if;
    if v_choice='CANDIDATE_WRONG'
       and nullif(v_item->>'corrected_start_at_local','') is null
       and v_comparison.source_presence<>'ABSENT' then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_CORRECTED_HOURS_REQUIRED' using errcode='22023';
    end if;
    if nullif(v_item->>'corrected_start_at_local','') is not null and (
      nullif(v_item->>'corrected_break_minutes','')::integer<0
      or nullif(v_item->>'corrected_end_at_local','')::timestamp
         <=nullif(v_item->>'corrected_start_at_local','')::timestamp
    ) then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_CORRECTED_HOURS_INVALID' using errcode='22023';
    end if;
    v_response_hash:=private.weekly_source_query_response_fingerprint_v1(
      v_incident.id,v_comparison.id,v_candidate_id,v_draft_version,v_request_key,
      private.weekly_source_sha256_jsonb_v1('WEEKLY_CANDIDATE_RESPONSE_ITEM_V1',v_item)
    );
    insert into public.weekly_candidate_response_draft_items(
      response_draft_id,incident_id,comparison_revision_id,choice,
      corrected_start_at_local,corrected_end_at_local,corrected_break_minutes,
      response_fingerprint
    ) values (
      v_draft.id,v_incident.id,v_comparison.id,v_choice,
      nullif(v_item->>'corrected_start_at_local','')::timestamp,
      nullif(v_item->>'corrected_end_at_local','')::timestamp,
      nullif(v_item->>'corrected_break_minutes','')::integer,v_response_hash
    );
    insert into public.weekly_discrepancy_events(
      incident_id,issue_episode,projection_publication_id,
      expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,
      idempotency_key
    ) values (
      v_incident.id,v_incident.episode_number,v_publication_id,
      v_comparison.material_comparison_fingerprint,'CANDIDATE_RESPONDED','CANDIDATE',
      pg_catalog.jsonb_build_object(
        'choice',v_choice,'response_fingerprint',pg_catalog.encode(v_response_hash,'hex'),
        'request_idempotency_key',v_request_key,
        'request_semantic_hash',v_semantic_hex,
        'request_item_count',pg_catalog.jsonb_array_length(v_responses)
      ),'CANDIDATE_RESPONSE:'||v_request_key::text||':'||v_incident.id::text
    ) returning id into v_event_id;
    if v_choice='CANDIDATE_WRONG' then
      update public.weekly_discrepancy_incidents
      set state='RESOLVED',reconciliation_state='RECONCILED',
          candidate_action_state='RESPONDED',manager_potential_state='NOT_REQUIRED',
          manager_action_state='NOT_REQUIRED',waiting_source_state='NOT_WAITING',
          resolved_at_utc=pg_catalog.transaction_timestamp(),resolution_kind='CANDIDATE_CORRECTED'
      where id=v_incident.id;
      update public.weekly_candidate_outreach_memberships set state='RESOLVED'
      where candidate_generation_id=v_generation.id and incident_id=v_incident.id;
      update public.weekly_manager_review_items set response_state='FILTERED_RESOLVED'
      where incident_id=v_incident.id and response_state='UNANSWERED';
      insert into public.weekly_discrepancy_events(
        incident_id,issue_episode,projection_publication_id,
        expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,idempotency_key
      ) values (
        v_incident.id,v_incident.episode_number,v_publication_id,
        v_comparison.material_comparison_fingerprint,'RESOLVED','CANDIDATE',
        pg_catalog.jsonb_build_object('resolution','CANDIDATE_CORRECTED'),
        'CANDIDATE_CORRECTED:'||v_event_id::text
      );
      v_resolved:=v_resolved+1;
    else
      v_policy:=private.weekly_source_query_incident_policy_v1(v_incident.id);
      update public.weekly_discrepancy_incidents
      set candidate_action_state='RESPONDED',
          manager_potential_state=case
            when coalesce((v_policy->>'manager_queries_enabled')::boolean,false)
                 and nullif(v_policy->>'manager_query_recipient','') is not null
              then 'AVAILABLE'
            else 'NOT_AVAILABLE'
          end,
          manager_action_state=case
            when coalesce((v_policy->>'manager_queries_enabled')::boolean,false)
                 and nullif(v_policy->>'manager_query_recipient','') is not null
              then 'DUE'
            else 'NOT_REQUIRED'
          end,
          reconciliation_state='WAITING_FOR_SOURCE'
      where id=v_incident.id;
      update public.weekly_candidate_outreach_memberships set state='ANSWERED'
      where candidate_generation_id=v_generation.id and incident_id=v_incident.id;
      select * into strict v_work from public.weekly_work_events where id=v_incident.work_event_id;
      select * into strict v_client from public.clients where id=v_incident.client_id;
      v_summary:=case
        when v_comparison.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' and v_group.source_family='NHSP'
          then 'Shift missing or not yet authorised'
        when v_comparison.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED'
          then 'Shift missing from system hours'
        else 'System hours need review'
      end;
      v_notices:=v_notices+private.weekly_source_query_notice_fanout_v1(
        v_incident.id,v_event_id,'WEEKLY_CANDIDATE_SOURCE_DISPUTED',
        pg_catalog.jsonb_build_object(
          'candidate_name',coalesce(nullif(v_candidate.display_name,''),
            pg_catalog.concat_ws(' ',v_candidate.first_name,v_candidate.last_name)),
          'client_name',v_client.name,'work_date',v_work.work_date,
          'issue_summary',v_summary,'candidate_choice',v_choice
        )
      );
    end if;
    v_answered:=v_answered+1;
  end loop;
  if v_answered<>pg_catalog.jsonb_array_length(v_responses) then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_RESPONSE_SELECTION_INVALID' using errcode='22023';
  end if;
  if not exists(
    select 1 from public.weekly_candidate_outreach_memberships
    where candidate_generation_id=v_generation.id and state='ACTIONABLE'
  ) then
    update public.weekly_candidate_outreach_generations set state='COMPLETE'
    where id=v_generation.id;
    update public.weekly_message_intents set state='RETIRED'
    where candidate_generation_id=v_generation.id and state in ('DUE','RENDERED');

    select generation.id,generation.recipient_route_id
      into v_recipient_generation_id,v_recipient_route_id
    from public.weekly_manager_recipient_memberships membership
    join public.weekly_manager_recipient_generations generation
      on generation.id=membership.recipient_generation_id and generation.state='ACTIVE'
    join public.weekly_manager_recipient_routes route
      on route.id=generation.recipient_route_id
     and route.current_generation_id=generation.id
    where membership.candidate_cohort_id=v_cohort.id
    order by generation.generation_number desc
    limit 1
    for update of generation;
    if v_recipient_generation_id is not null
       and not exists(
         select 1
         from public.weekly_manager_recipient_memberships route_membership
         join public.weekly_route_activations activation
           on activation.id=route_membership.route_activation_id
          and activation.route_mode='CANDIDATE_FIRST'
         join public.weekly_candidate_cohorts candidate_cohort
           on candidate_cohort.id=route_membership.candidate_cohort_id
         join public.weekly_candidate_outreach_memberships candidate_membership
           on candidate_membership.candidate_generation_id=candidate_cohort.current_generation_id
          and candidate_membership.state='ACTIONABLE'
         where route_membership.recipient_generation_id=v_recipient_generation_id
       ) and exists(
      -- 04A section 6.1: only a row that is unanswered AND unsent becomes due.
      -- A row an accepted batch on this route already owns is not work, so it
      -- must not raise an EARLY_ALL event whose render would then be empty.
      select 1 from public.weekly_manager_recipient_memberships membership
      join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
      where membership.recipient_generation_id=v_recipient_generation_id
        and incident.state='OPEN' and incident.manager_action_state<>'RESPONDED'
        and not private.weekly_source_query_manager_row_owned_v1(
          v_recipient_route_id,incident.id,incident.episode_number
        )
    ) then
      insert into public.weekly_manager_cohort_due_events(
        recipient_generation_id,candidate_cohort_id,event_kind,cohort_started_at_utc,
        due_at_utc,state,trigger_hash
      ) select distinct
        v_recipient_generation_id,membership.candidate_cohort_id,'EARLY_ALL',
        candidate_generation.started_at_utc,pg_catalog.transaction_timestamp(),'PENDING',
        private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_MANAGER_COHORT_DUE_V1',pg_catalog.jsonb_build_object(
            'recipient_generation_id',v_recipient_generation_id,
            'candidate_cohort_id',membership.candidate_cohort_id,
            'event_kind','EARLY_ALL',
            'candidate_generation_id',candidate_generation.id
          )
        )
      from public.weekly_manager_recipient_memberships membership
      join public.weekly_route_activations activation
        on activation.id=membership.route_activation_id
       and activation.route_mode='CANDIDATE_FIRST'
      join public.weekly_candidate_cohorts candidate_cohort
        on candidate_cohort.id=membership.candidate_cohort_id
      join public.weekly_candidate_outreach_generations candidate_generation
        on candidate_generation.id=candidate_cohort.current_generation_id
      join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
      where membership.recipient_generation_id=v_recipient_generation_id
        and incident.state='OPEN' and incident.manager_action_state<>'RESPONDED'
      on conflict (recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
      select pg_catalog.array_agg(id order by id) into v_due_ids
      from public.weekly_manager_cohort_due_events
      where recipient_generation_id=v_recipient_generation_id
        and event_kind='EARLY_ALL' and state='PENDING';
      if coalesce(pg_catalog.array_length(v_due_ids,1),0)>0
         and not exists(
           select 1 from public.weekly_message_intents intent
           where intent.recipient_generation_id=v_recipient_generation_id
             and intent.state in ('DUE','RENDERED')
         ) then
        v_intent_id:=private.weekly_source_query_manager_intent_v1(
          (select recipient_route_id from public.weekly_manager_recipient_generations where id=v_recipient_generation_id),
          v_recipient_generation_id,v_due_ids,'MANAGER_EARLY_ALL',1,
          pg_catalog.transaction_timestamp()
        );
        update public.weekly_manager_cohort_due_events set state='CONSUMED'
        where id=any(v_due_ids);
      end if;
    end if;
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'replay',false,'request_idempotency_key',v_request_key,
    'answered_count',v_answered,'resolved_count',v_resolved,
    'office_notification_count',v_notices,'manager_message_intent_id',v_intent_id
  );
end;
$function$;

create or replace function public.weekly_source_query_send_manager_now_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_cycle_id uuid;
  v_publication_id uuid;
  v_guard jsonb;
  v_requested uuid[];
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_comparison public.weekly_issue_comparison_revisions%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_context jsonb;
  v_route_id uuid;
  v_current_route_id uuid;
  v_seen_keys text[]:='{}'::text[];
  v_selected_cohort_ids uuid[]:='{}'::uuid[];
  v_key text;
  v_selected record;
  v_candidate_generation public.weekly_candidate_outreach_generations%rowtype;
  v_generation jsonb;
  v_generation_id uuid;
  v_due_ids uuid[];
  v_intent_id uuid;
  v_settings public.weekly_source_global_settings%rowtype;
  v_route public.weekly_manager_recipient_routes%rowtype;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(
       select 1 from pg_catalog.jsonb_object_keys(p_request) key
       where key not in (
         'actor_user_id','source_cycle_id','projection_publication_id','incident_ids'
       )
     ) or pg_catalog.jsonb_typeof(p_request->'incident_ids')<>'array' then
    raise exception 'WEEKLY_SOURCE_MANAGER_SEND_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
    select pg_catalog.array_agg(value::uuid order by value::uuid) into v_requested
    from pg_catalog.jsonb_array_elements_text(p_request->'incident_ids');
  exception when others then
    raise exception 'WEEKLY_SOURCE_MANAGER_SEND_REQUEST_INVALID' using errcode='22023';
  end;
  if coalesce(pg_catalog.array_length(v_requested,1),0)=0
     or pg_catalog.array_length(v_requested,1)<>(
       select pg_catalog.count(distinct value) from pg_catalog.unnest(v_requested) value
     ) then
    raise exception 'WEEKLY_SOURCE_MANAGER_SEND_SELECTION_INVALID' using errcode='22023';
  end if;
  v_guard:=private.weekly_source_query_current_publication_v1(v_cycle_id,v_publication_id);
  perform private.weekly_source_office_authority_v1(
    v_actor,'SEND_MANAGER',(v_guard->>'source_group_id')::uuid,null,
    (v_guard->>'finalisation_week_ending')::date
  );

  for v_incident in
    select incident.*
    from public.weekly_discrepancy_incidents incident
    where incident.id=any(v_requested)
    order by incident.id
    for update
  loop
    if v_incident.source_cycle_id<>v_cycle_id or v_incident.state<>'OPEN'
       or v_incident.manager_potential_state<>'AVAILABLE'
       or private.weekly_source_covered_hours_incident_v1(v_incident.id)
       or v_incident.manager_action_state in ('RESPONDED','NOT_REQUIRED') then
      raise exception 'WEEKLY_SOURCE_MANAGER_SEND_SELECTION_STALE' using errcode='40001';
    end if;
    select * into strict v_comparison from public.weekly_issue_comparison_revisions
    where id=v_incident.current_comparison_revision_id;
    if v_comparison.candidate_timesheet_id is null then
      raise exception 'WEEKLY_SOURCE_MANAGER_REQUIRES_TIMESHEET' using errcode='55000';
    end if;
    select * into strict v_event from public.weekly_work_events where id=v_incident.work_event_id;
    v_context:=private.weekly_source_query_cohort_ensure_v1(
      v_cycle_id,v_incident.candidate_id,v_incident.client_id,
      v_comparison.contract_id,v_event.work_date
    );
    if coalesce((v_context->>'manager_queries_enabled')::boolean,false) is not true
       or nullif(v_context->>'manager_route_id','') is null then
      raise exception 'WEEKLY_SOURCE_MANAGER_QUERIES_DISABLED' using errcode='55000';
    end if;
    v_current_route_id:=(v_context->>'manager_route_id')::uuid;
    if v_route_id is null then v_route_id:=v_current_route_id;
    elsif v_route_id<>v_current_route_id then
      raise exception 'WEEKLY_SOURCE_MANAGER_SEND_ONE_RECIPIENT_REQUIRED' using errcode='22023';
    end if;
    if not ((v_context->>'cohort_id')::uuid=any(v_selected_cohort_ids)) then
      v_selected_cohort_ids:=pg_catalog.array_append(
        v_selected_cohort_ids,(v_context->>'cohort_id')::uuid
      );
    end if;
    v_key:=v_incident.candidate_id::text||':'||v_incident.client_id::text;
    if not (v_key=any(v_seen_keys)) then
      v_seen_keys:=pg_catalog.array_append(v_seen_keys,v_key);
      insert into public.weekly_route_activations(
        source_cycle_id,candidate_id,client_id,audience_route,route_mode,
        activated_by_user_id,activated_at_utc,updated_at_utc
      ) values (
        v_cycle_id,v_incident.candidate_id,v_incident.client_id,'MANAGER','MANAGER_DIRECT',
        v_actor,pg_catalog.transaction_timestamp(),pg_catalog.transaction_timestamp()
      ) on conflict (source_cycle_id,candidate_id,client_id,audience_route)
      do update set route_mode='MANAGER_DIRECT',
        activated_by_user_id=excluded.activated_by_user_id,
        activated_at_utc=coalesce(public.weekly_route_activations.activated_at_utc,excluded.activated_at_utc),
        updated_at_utc=excluded.updated_at_utc;
    end if;
  end loop;
  if (select pg_catalog.count(*) from public.weekly_discrepancy_incidents where id=any(v_requested))
     <>pg_catalog.array_length(v_requested,1) then
    raise exception 'WEEKLY_SOURCE_MANAGER_SEND_SELECTION_STALE' using errcode='40001';
  end if;
  if exists(
    select 1
    from public.weekly_candidate_cohorts cohort
    join public.weekly_discrepancy_incidents incident
      on incident.source_cycle_id=cohort.source_cycle_id
     and incident.candidate_id=cohort.candidate_id
     and incident.client_id=cohort.client_id
     and incident.state='OPEN'
     and incident.manager_potential_state='AVAILABLE'
     and incident.manager_action_state not in ('RESPONDED','NOT_REQUIRED')
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
     and comparison.candidate_timesheet_id is not null
    where cohort.id=any(v_selected_cohort_ids)
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
      and not (incident.id=any(v_requested))
  ) then
    raise exception 'WEEKLY_SOURCE_MANAGER_SEND_SELECTION_STALE' using errcode='40001';
  end if;

  -- Manager-direct is the durable route choice for every selected complete
  -- candidate cohort. Stop only candidate work that has not reached a provider;
  -- accepted, submission-started and ambiguous delivery history is retained.
  for v_selected in
    select cohort.id,cohort.candidate_id,cohort.client_id
    from public.weekly_candidate_cohorts cohort
    where cohort.id=any(v_selected_cohort_ids)
    order by cohort.id
  loop
    insert into public.weekly_route_activations(
      source_cycle_id,candidate_id,client_id,audience_route,route_mode,
      activated_by_user_id,activated_at_utc,updated_at_utc
    ) values (
      v_cycle_id,v_selected.candidate_id,v_selected.client_id,'CANDIDATE','MANAGER_DIRECT',
      v_actor,pg_catalog.transaction_timestamp(),pg_catalog.transaction_timestamp()
    ) on conflict (source_cycle_id,candidate_id,client_id,audience_route)
    do update set route_mode='MANAGER_DIRECT',
      activated_by_user_id=excluded.activated_by_user_id,
      activated_at_utc=coalesce(public.weekly_route_activations.activated_at_utc,excluded.activated_at_utc),
      updated_at_utc=excluded.updated_at_utc;
    select * into v_candidate_generation
    from public.weekly_candidate_outreach_generations
    where candidate_cohort_id=v_selected.id and state='ACTIVE' and request_kind='CHECK_HOURS'
    for update;
    if found then
      update public.weekly_candidate_cohorts
      set current_generation_id=null where id=v_selected.id;
      update public.weekly_message_renders render
      set state='STALE'
      from public.weekly_message_dispatch_commands command
      where command.message_render_id=render.id
        and command.candidate_generation_id=v_candidate_generation.id
        and command.state in ('READY','LEASED') and render.state='CURRENT';
      update public.weekly_message_dispatch_commands
      set state='RETIRED',lease_owner=null,lease_token=null,lease_expires_at_utc=null
      where candidate_generation_id=v_candidate_generation.id
        and state in ('READY','LEASED');
      update public.weekly_message_intents
      set state='RETIRED'
      where candidate_generation_id=v_candidate_generation.id
        and state in ('DUE','RENDERED');
      update public.weekly_candidate_outreach_memberships
      set state='SUPERSEDED'
      where candidate_generation_id=v_candidate_generation.id and state='ACTIONABLE';
      update public.weekly_candidate_outreach_generations
      set state='CANCELLED' where id=v_candidate_generation.id;
    end if;
    update public.weekly_discrepancy_incidents
    set candidate_action_state='NOT_REQUIRED'
    where source_cycle_id=v_cycle_id
      and candidate_id=v_selected.candidate_id and client_id=v_selected.client_id
      and id=any(v_requested) and candidate_action_state in ('NOT_ASKED','ASKED');
  end loop;

  select * into strict v_settings from public.weekly_source_global_settings where singleton;
  select * into strict v_route from public.weekly_manager_recipient_routes
  where id=v_route_id for update;
  if v_route.manager_send_available_at_utc is not null
     and pg_catalog.transaction_timestamp()<v_route.manager_send_available_at_utc then
    raise exception 'WEEKLY_SOURCE_MANAGER_SEND_COOLDOWN' using errcode='55000',
      detail=pg_catalog.jsonb_build_object(
        'available_at_utc',v_route.manager_send_available_at_utc
      )::text;
  end if;
  -- 04A section 6.5: a manual send "atomically claims its exact eligible rows",
  -- and "one accepted batch owns each row ... No row is sent twice."  If every
  -- selected row is already owned by an accepted batch on this route there is
  -- no remainder to claim, so refuse now rather than staging a due intent the
  -- renderer would have to reject and which would then hold the whole route.
  if not exists(
    select 1 from public.weekly_discrepancy_incidents incident
    where incident.id=any(v_requested)
      and not private.weekly_source_query_manager_row_owned_v1(
        v_route_id,incident.id,incident.episode_number
      )
  ) then
    raise exception 'WEEKLY_SOURCE_MANAGER_SEND_ALREADY_SENT' using errcode='55000';
  end if;
  v_generation:=private.weekly_source_query_manager_generation_v1(
    v_route_id,'OFFICE_DIRECT',pg_catalog.transaction_timestamp(),true
  );
  v_generation_id:=(v_generation->>'recipient_generation_id')::uuid;
  select pg_catalog.array_agg(id order by id) into v_due_ids
  from public.weekly_manager_cohort_due_events
  where recipient_generation_id=v_generation_id and event_kind='EARLY_ALL' and state='PENDING'
    and candidate_cohort_id=any(v_selected_cohort_ids);
  v_intent_id:=private.weekly_source_query_manager_intent_v1(
    v_route_id,v_generation_id,v_due_ids,'MANAGER_MANUAL_SELECTED',1,
    pg_catalog.transaction_timestamp()
  );
  update public.weekly_manager_cohort_due_events set state='CONSUMED'
  where id=any(coalesce(v_due_ids,'{}'::uuid[]));
  update public.weekly_manager_recipient_routes
  set manager_send_available_at_utc=pg_catalog.transaction_timestamp()+v_settings.manager_manual_send_cooldown
  where id=v_route_id;
  update public.weekly_discrepancy_incidents incident
  set manager_action_state='DUE'
  from public.weekly_manager_recipient_memberships membership
  where membership.recipient_generation_id=v_generation_id
    and membership.candidate_cohort_id=any(v_selected_cohort_ids)
    and membership.incident_id=incident.id
    and incident.manager_action_state in ('NOT_SENT','SENT')
    and not private.weekly_source_query_manager_row_owned_v1(
      v_route_id,incident.id,incident.episode_number
    );
  perform public._audit_insert(
    'weekly_source_manager_send',v_intent_id::text,'WEEKLY_SOURCE_MANAGER_SEND_STAGED',
    null,pg_catalog.jsonb_build_object(
      'recipient_route_id',v_route_id,'recipient_generation_id',v_generation_id,
      'selected_incident_count',pg_catalog.array_length(v_requested,1),
      'send_available_at_utc',pg_catalog.transaction_timestamp()+v_settings.manager_manual_send_cooldown
    ),'Manager review email staged',v_actor
  );
  return pg_catalog.jsonb_build_object(
    'ok',true,'message_intent_id',v_intent_id,'recipient_route_id',v_route_id,
    'recipient_generation_id',v_generation_id,
    'send_available_at_utc',pg_catalog.transaction_timestamp()+v_settings.manager_manual_send_cooldown
  );
end;
$function$;

create or replace function public.weekly_source_candidate_reminder_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_generation_id uuid;
  v_publication_id uuid;
  v_generation public.weekly_candidate_outreach_generations%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_settings public.weekly_source_global_settings%rowtype;
  v_intent_id uuid;
  v_tranche text;
  v_sequence integer;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('actor_user_id','candidate_generation_id','projection_publication_id')) then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_REMINDER_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_generation_id:=(p_request->>'candidate_generation_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_REMINDER_REQUEST_INVALID' using errcode='22023';
  end;
  select * into strict v_generation from public.weekly_candidate_outreach_generations
  where id=v_generation_id for update;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_generation.source_cycle_id;
  perform private.weekly_source_query_current_publication_v1(v_cycle.id,v_publication_id);
  perform private.weekly_source_office_authority_v1(
    v_actor,'ASK_CANDIDATES',v_cycle.source_group_id,v_generation.client_id,
    v_cycle.finalisation_week_ending
  );
  if not private.weekly_source_candidate_generation_current_v1(v_generation.id)
    or pg_catalog.transaction_timestamp()<v_generation.manual_reminder_available_at_utc
    or (v_generation.request_kind='CHECK_HOURS' and not exists(
      select 1 from public.weekly_candidate_outreach_memberships membership
      join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
      where membership.candidate_generation_id=v_generation.id and membership.state='ACTIONABLE'
        and incident.state='OPEN' and incident.candidate_action_state='ASKED'
        and not private.weekly_source_covered_hours_incident_v1(incident.id)
        and membership.comparison_revision_id=incident.current_comparison_revision_id))
    or (v_generation.request_kind='SUBMIT_TIMESHEET' and not exists(
      select 1 from public.weekly_timesheet_submission_requests request
      join public.weekly_timesheet_submission_request_memberships membership on membership.submission_request_id=request.id
      where request.candidate_cohort_id=v_generation.candidate_cohort_id
        and request.request_generation=v_generation.generation_number
        and request.state in ('ACTIVE','OVERDUE','PARTLY_SUBMITTED') and membership.state='WAITING')) then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_REMINDER_UNAVAILABLE' using errcode='55000';
  end if;
  select * into strict v_settings from public.weekly_source_global_settings where singleton;
  select coalesce(pg_catalog.max(tranche_sequence),0)+1 into v_sequence
  from public.weekly_message_intents
  where candidate_generation_id=v_generation.id
    and tranche_kind in ('CANDIDATE_MANUAL_REMINDER','TIMESHEET_SUBMISSION_REMINDER_6H');
  v_tranche:=case when v_generation.request_kind='SUBMIT_TIMESHEET'
    then 'TIMESHEET_SUBMISSION_REMINDER_6H' else 'CANDIDATE_MANUAL_REMINDER' end;
  v_intent_id:=private.weekly_source_query_candidate_intent_v1(
    v_generation.id,v_tranche,v_sequence,pg_catalog.transaction_timestamp()
  );
  update public.weekly_candidate_outreach_generations
  set manual_reminder_available_at_utc=pg_catalog.transaction_timestamp()+v_settings.candidate_manual_reminder_cooldown
  where id=v_generation.id;
  perform public._audit_insert(
    'weekly_source_candidate_reminder',v_intent_id::text,'WEEKLY_SOURCE_CANDIDATE_REMINDER_STAGED',
    null,pg_catalog.jsonb_build_object('candidate_generation_id',v_generation.id),
    'Candidate reminder staged',v_actor
  );
  return pg_catalog.jsonb_build_object(
    'ok',true,'message_intent_id',v_intent_id,
    'next_manual_reminder_at_utc',pg_catalog.transaction_timestamp()+v_settings.candidate_manual_reminder_cooldown
  );
end;
$function$;

create or replace function public.weekly_source_query_ask_candidate_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_cycle_id uuid;
  v_publication_id uuid;
  v_candidate_id uuid;
  v_client_id uuid;
  v_requested uuid[];
  v_current uuid[];
  v_guard jsonb;
  v_first_contract_id uuid;
  v_first_work_date date;
  v_context jsonb;
  v_result jsonb;
  v_manager_activation public.weekly_route_activations%rowtype;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(
       select 1 from pg_catalog.jsonb_object_keys(p_request) key
       where key not in (
         'actor_user_id','source_cycle_id','projection_publication_id',
         'candidate_id','client_id','incident_ids'
       )
     ) or pg_catalog.jsonb_typeof(p_request->'incident_ids')<>'array' then
    raise exception 'WEEKLY_SOURCE_ASK_CANDIDATE_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
    v_candidate_id:=(p_request->>'candidate_id')::uuid;
    v_client_id:=(p_request->>'client_id')::uuid;
    select pg_catalog.array_agg(value::uuid order by value::uuid) into v_requested
    from pg_catalog.jsonb_array_elements_text(p_request->'incident_ids');
  exception when others then
    raise exception 'WEEKLY_SOURCE_ASK_CANDIDATE_REQUEST_INVALID' using errcode='22023';
  end;
  if coalesce(pg_catalog.array_length(v_requested,1),0)=0
     or pg_catalog.array_length(v_requested,1)<>(
       select pg_catalog.count(distinct id_value) from pg_catalog.unnest(v_requested) id_value
     ) then
    raise exception 'WEEKLY_SOURCE_ASK_CANDIDATE_SELECTION_INVALID' using errcode='22023';
  end if;
  v_guard:=private.weekly_source_query_current_publication_v1(v_cycle_id,v_publication_id);
  perform private.weekly_source_office_authority_v1(
    v_actor,'ASK_CANDIDATES',(v_guard->>'source_group_id')::uuid,v_client_id,
    (v_guard->>'finalisation_week_ending')::date
  );
  select pg_catalog.array_agg(incident.id order by incident.id),
         min(comparison.contract_id::text)::uuid,min(work_event.work_date)
  into v_current,v_first_contract_id,v_first_work_date
  from public.weekly_discrepancy_incidents incident
  join public.weekly_issue_comparison_revisions comparison
    on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work_event on work_event.id=incident.work_event_id
  where incident.source_cycle_id=v_cycle_id and incident.candidate_id=v_candidate_id
    and incident.client_id=v_client_id and incident.state='OPEN'
    and not private.weekly_source_covered_hours_incident_v1(incident.id)
    and incident.candidate_action_state not in ('RESPONDED','NOT_REQUIRED');
  if v_current is null or v_current is distinct from v_requested then
    raise exception 'WEEKLY_SOURCE_ASK_CANDIDATE_SELECTION_STALE' using errcode='40001';
  end if;
  v_context:=private.weekly_source_query_cohort_ensure_v1(
    v_cycle_id,v_candidate_id,v_client_id,v_first_contract_id,v_first_work_date
  );
  if coalesce((v_context->>'candidate_queries_enabled')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_QUERIES_DISABLED' using errcode='55000';
  end if;
  if coalesce((v_context->>'manager_queries_enabled')::boolean,false)
     and nullif(v_context->>'manager_route_id','') is not null then
    insert into public.weekly_route_activations(
      source_cycle_id,candidate_id,client_id,audience_route,route_mode,
      activated_by_user_id,activated_at_utc,updated_at_utc
    ) values (
      v_cycle_id,v_candidate_id,v_client_id,'MANAGER','CANDIDATE_FIRST',
      v_actor,pg_catalog.transaction_timestamp(),pg_catalog.transaction_timestamp()
    ) on conflict (source_cycle_id,candidate_id,client_id,audience_route)
    do update set route_mode='CANDIDATE_FIRST',
      activated_by_user_id=coalesce(public.weekly_route_activations.activated_by_user_id,excluded.activated_by_user_id),
      activated_at_utc=coalesce(public.weekly_route_activations.activated_at_utc,excluded.activated_at_utc),
      updated_at_utc=excluded.updated_at_utc
    returning * into v_manager_activation;
  end if;
  v_result:=private.weekly_source_query_candidate_generation_v1(
    v_cycle_id,v_candidate_id,v_client_id,v_publication_id,
    'OFFICE_ASK',v_actor,pg_catalog.transaction_timestamp()
  );
  if v_manager_activation.id is not null then
    perform private.weekly_source_query_manager_generation_v1(
      (v_context->>'manager_route_id')::uuid,'T6_RESPONDED',
      pg_catalog.transaction_timestamp(),false
    );
  end if;
  perform public._audit_insert(
    'weekly_source_candidate_query',coalesce(v_result->>'candidate_generation_id',v_candidate_id::text),
    'WEEKLY_SOURCE_CANDIDATE_ASKED',null,v_result,
    'Candidate asked to check Weekly hours',v_actor
  );
  return v_result;
end;
$function$;

create or replace function private.weekly_source_submission_request_start_v1(
  p_request jsonb,
  p_automatic boolean
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_cycle_id uuid;
  v_publication_id uuid;
  v_candidate_id uuid;
  v_guard jsonb;
  v_scope jsonb;
  v_scopes jsonb;
  v_hash bytea;
  v_settings public.weekly_source_global_settings%rowtype;
  v_first_contract_id uuid;
  v_first_client_id uuid;
  v_first_work_date date;
  v_context jsonb;
  v_cohort public.weekly_candidate_cohorts%rowtype;
  v_activation public.weekly_route_activations%rowtype;
  v_old_request public.weekly_timesheet_submission_requests%rowtype;
  v_old_generation public.weekly_candidate_outreach_generations%rowtype;
  v_generation public.weekly_candidate_outreach_generations%rowtype;
  v_submission public.weekly_timesheet_submission_requests%rowtype;
  v_generation_number integer;
  v_ordinal integer:=0;
  v_intent_id uuid;
  v_contract public.contracts%rowtype;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(
       select 1 from pg_catalog.jsonb_object_keys(p_request) key
       where key not in (
         'actor_user_id','source_cycle_id','projection_publication_id','candidate_id','scopes'
       )
     ) or pg_catalog.jsonb_typeof(p_request->'scopes')<>'array'
     or pg_catalog.jsonb_array_length(p_request->'scopes')=0 then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
    v_candidate_id:=(p_request->>'candidate_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_REQUEST_INVALID' using errcode='22023';
  end;
  v_guard:=private.weekly_source_query_current_publication_v1(v_cycle_id,v_publication_id);
  if not p_automatic then
    perform private.weekly_source_office_authority_v1(
      v_actor,'ASK_CANDIDATES',(v_guard->>'source_group_id')::uuid,null,
      (v_guard->>'finalisation_week_ending')::date
    );
  end if;
  v_scopes:=coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'week_ending',value->>'week_ending','client_id',value->>'client_id',
        'contract_id',value->>'contract_id',
        'expected_source_fingerprint',value->>'expected_source_fingerprint'
      ) order by (value->>'week_ending')::date,(value->>'client_id')::uuid,(value->>'contract_id')::uuid
    )
    from pg_catalog.jsonb_array_elements(p_request->'scopes')
  ),'[]'::jsonb);
  if pg_catalog.jsonb_array_length(v_scopes)<>pg_catalog.jsonb_array_length(p_request->'scopes') then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_SCOPE_INVALID' using errcode='22023';
  end if;
  v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_TIMESHEET_SUBMISSION_SCOPE_V1',v_scopes);
  for v_scope in select value from pg_catalog.jsonb_array_elements(v_scopes)
  loop
    if exists(
      select 1 from pg_catalog.jsonb_object_keys(v_scope) key
      where key not in ('week_ending','client_id','contract_id','expected_source_fingerprint')
    ) then
      raise exception 'WEEKLY_SOURCE_TIMESHEET_SCOPE_INVALID' using errcode='22023';
    end if;
    select * into strict v_contract from public.contracts
    where id=(v_scope->>'contract_id')::uuid
      and client_id=(v_scope->>'client_id')::uuid
      and candidate_id=v_candidate_id;
    perform private.weekly_source_query_hex32_v1(
      v_scope->>'expected_source_fingerprint','WEEKLY_SOURCE_SCOPE_FINGERPRINT_INVALID'
    );
    if exists(
      select 1 from public.timesheets t
      where t.contract_id=v_contract.id and t.week_ending_date=(v_scope->>'week_ending')::date
        and t.is_current and t.revoked_at is null and t.archived_at_utc is null
        and t.sheet_scope='WEEKLY' and t.line_type='HOURS'
        and t.r2_nurse_key is not null and t.img_sha256_nurse is not null
    ) then
      raise exception 'WEEKLY_SOURCE_SIGNED_TIMESHEET_ALREADY_EXISTS' using errcode='55000';
    end if;
    if v_first_contract_id is null then
      v_first_contract_id:=v_contract.id;
      v_first_client_id:=v_contract.client_id;
      v_first_work_date:=(v_scope->>'week_ending')::date;
    end if;
    if coalesce((private._weekly_source_effective_policy_v1(
      v_contract.client_id,v_contract.id,(v_scope->>'week_ending')::date
    )->>'candidate_queries_enabled')::boolean,false) is not true then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_QUERIES_DISABLED' using errcode='55000';
    end if;
  end loop;
  v_context:=private.weekly_source_query_cohort_ensure_v1(
    v_cycle_id,v_candidate_id,v_first_client_id,v_first_contract_id,v_first_work_date
  );
  select * into strict v_cohort from public.weekly_candidate_cohorts
  where id=(v_context->>'cohort_id')::uuid for update;
  select * into v_old_request
  from public.weekly_timesheet_submission_requests
  where source_cycle_id=v_cycle_id and candidate_id=v_candidate_id
    and state in ('READY','ACTIVE','OVERDUE','PARTLY_SUBMITTED')
  for update;
  if found and (v_old_request.membership_hash=v_hash or (p_automatic and not exists (
    -- A new publication ID is not a new request. Compare relevant waiting
    -- weeks by business facts, retaining the original immutable membership.
    select 1 from pg_catalog.jsonb_array_elements(v_scopes) scope
    where not exists (
      select 1 from public.weekly_timesheet_submission_request_memberships membership
      where membership.submission_request_id=v_old_request.id
        and membership.week_ending=(scope->>'week_ending')::date
        and membership.client_id=(scope->>'client_id')::uuid
        and membership.contract_id=(scope->>'contract_id')::uuid
        and private.weekly_source_missing_scope_unchanged_v1(
          v_old_request.current_projection_publication_id,v_publication_id,v_candidate_id,
          membership.client_id,membership.contract_id,membership.week_ending)
    )
  ))) then
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','UNCHANGED','submission_request_id',v_old_request.id,
      'candidate_generation_id',v_cohort.current_submission_generation_id,
      'started_at_utc',v_old_request.started_at_utc,
      'reminder_due_at_utc',v_old_request.reminder_due_at_utc,
      'deadline_at_utc',v_old_request.deadline_at_utc
    );
  end if;
  if found then
    update public.weekly_timesheet_submission_requests
    set state='SUPERSEDED',updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_old_request.id;
  end if;
  insert into public.weekly_route_activations(
    source_cycle_id,candidate_id,client_id,audience_route,route_mode,
    activated_by_user_id,activated_at_utc,updated_at_utc
  ) values (
    v_cycle_id,v_candidate_id,v_first_client_id,'CANDIDATE','CANDIDATE_FIRST',
    v_actor,pg_catalog.transaction_timestamp(),pg_catalog.transaction_timestamp()
  ) on conflict (source_cycle_id,candidate_id,client_id,audience_route)
  do update set route_mode='CANDIDATE_FIRST',
    activated_by_user_id=coalesce(public.weekly_route_activations.activated_by_user_id,excluded.activated_by_user_id),
    activated_at_utc=coalesce(public.weekly_route_activations.activated_at_utc,excluded.activated_at_utc),
    updated_at_utc=excluded.updated_at_utc
  returning * into v_activation;
  select * into v_old_generation
  from public.weekly_candidate_outreach_generations
  where candidate_cohort_id=v_cohort.id and state='ACTIVE' and request_kind='SUBMIT_TIMESHEET' for update;
  if found then
    update public.weekly_candidate_cohorts set current_submission_generation_id=null where id=v_cohort.id;
    update public.weekly_candidate_outreach_generations
    set state='SUPERSEDED',superseded_at_utc=pg_catalog.transaction_timestamp()
    where id=v_old_generation.id;
    update public.weekly_message_intents set state='RETIRED'
    where candidate_generation_id=v_old_generation.id and state in ('DUE','RENDERED');
    update public.weekly_message_dispatch_commands set state='RETIRED'
    where candidate_generation_id=v_old_generation.id and state in ('READY','LEASED');
  end if;
  select * into strict v_settings from public.weekly_source_global_settings where singleton;
  select coalesce(pg_catalog.max(generation_number),0)+1 into v_generation_number
  from public.weekly_candidate_outreach_generations where candidate_cohort_id=v_cohort.id;
  insert into public.weekly_candidate_outreach_generations(
    source_cycle_id,candidate_cohort_id,candidate_id,client_id,generation_number,
    activation_id,trigger_kind,request_kind,route_mode,started_at_utc,
    reminder_due_at_utc,deadline_at_utc,manual_reminder_available_at_utc,state,membership_hash
  ) values (
    v_cycle_id,v_cohort.id,v_candidate_id,v_first_client_id,v_generation_number,
    v_activation.id,case when p_automatic then 'NEW_INCIDENT' else 'OFFICE_ASK' end,
    'SUBMIT_TIMESHEET','CANDIDATE_FIRST',
    pg_catalog.transaction_timestamp(),
    pg_catalog.transaction_timestamp()+v_settings.candidate_reminder_after,
    pg_catalog.transaction_timestamp()+v_settings.candidate_response_deadline_after,
    pg_catalog.transaction_timestamp()+v_settings.candidate_manual_reminder_cooldown,
    'ACTIVE',v_hash
  ) returning * into v_generation;
  update public.weekly_candidate_cohorts set current_submission_generation_id=v_generation.id where id=v_cohort.id;
  insert into public.weekly_timesheet_submission_requests(
    environment,agency_id,source_cycle_id,candidate_id,candidate_cohort_id,
    request_generation,current_upload_id,current_projection_publication_id,state,
    started_at_utc,reminder_due_at_utc,deadline_at_utc,membership_hash
  )
  select source_group.environment,source_group.agency_id,v_cycle_id,v_candidate_id,v_cohort.id,
    v_generation.generation_number,
    (v_guard->>'upload_id')::uuid,v_publication_id,'ACTIVE',v_generation.started_at_utc,
    v_generation.reminder_due_at_utc,v_generation.deadline_at_utc,v_hash
  from public.weekly_source_cycles cycle
  join public.weekly_source_groups source_group on source_group.id=cycle.source_group_id
  where cycle.id=v_cycle_id
  returning * into v_submission;
  for v_scope in
    select value from pg_catalog.jsonb_array_elements(v_scopes)
    order by (value->>'week_ending')::date,(value->>'client_id')::uuid,(value->>'contract_id')::uuid
  loop
    v_ordinal:=v_ordinal+1;
    insert into public.weekly_timesheet_submission_request_memberships(
      submission_request_id,ordinal,week_ending,client_id,contract_id,
      expected_source_fingerprint,state
    ) values (
      v_submission.id,v_ordinal,(v_scope->>'week_ending')::date,
      (v_scope->>'client_id')::uuid,(v_scope->>'contract_id')::uuid,
      private.weekly_source_query_hex32_v1(
        v_scope->>'expected_source_fingerprint','WEEKLY_SOURCE_SCOPE_FINGERPRINT_INVALID'
      ),'WAITING'
    );
  end loop;
  v_intent_id:=private.weekly_source_query_candidate_intent_v1(
    v_generation.id,'TIMESHEET_SUBMISSION_INITIAL',1,v_generation.started_at_utc
  );
  perform public._audit_insert(
    'weekly_timesheet_submission_request',v_submission.id::text,
    'WEEKLY_TIMESHEET_SUBMISSION_REQUESTED',null,
    pg_catalog.jsonb_build_object(
      'candidate_id',v_candidate_id,'source_cycle_id',v_cycle_id,
      'scope_count',pg_catalog.jsonb_array_length(v_scopes),
      'started_at_utc',v_submission.started_at_utc,
      'reminder_due_at_utc',v_submission.reminder_due_at_utc,
      'deadline_at_utc',v_submission.deadline_at_utc
    ),case when p_automatic then 'Candidate automatically asked to submit a Weekly Timesheet after import'
      else 'Candidate asked to submit a Weekly Timesheet' end,v_actor
  );
  return pg_catalog.jsonb_build_object(
    'ok',true,'status','CREATED','submission_request_id',v_submission.id,
    'candidate_generation_id',v_generation.id,'message_intent_id',v_intent_id,
    'started_at_utc',v_submission.started_at_utc,
    'reminder_due_at_utc',v_submission.reminder_due_at_utc,
    'deadline_at_utc',v_submission.deadline_at_utc,
    'scope_count',pg_catalog.jsonb_array_length(v_scopes)
  );
end;
$function$;

create or replace function public.weekly_source_timesheet_submission_request_start_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
begin
  return private.weekly_source_submission_request_start_v1(p_request,false);
end;
$function$;

alter function private.weekly_source_submission_request_start_v1(jsonb,boolean) owner to current_user;
revoke all on function private.weekly_source_submission_request_start_v1(jsonb,boolean)
  from public,anon,authenticated,service_role;


create or replace function private.weekly_source_query_manager_generation_v1(
  p_recipient_route_id uuid,
  p_trigger_kind text,
  p_started_at_utc timestamptz,
  p_force_new boolean default false
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_route public.weekly_manager_recipient_routes%rowtype;
  v_old public.weekly_manager_recipient_generations%rowtype;
  v_new public.weekly_manager_recipient_generations%rowtype;
  v_membership jsonb;
  v_hash bytea;
  v_generation integer;
  v_ordinal integer:=0;
  v_row record;
  v_candidate_generation public.weekly_candidate_outreach_generations%rowtype;
  v_settings public.weekly_source_global_settings%rowtype;
  v_event_kind text;
  v_due timestamptz;
  v_trigger_hash bytea;
begin
  if p_trigger_kind not in (
    'OFFICE_DIRECT','EARLY_ALL','T6_RESPONDED','T12_REMAINDER','NEW_INCIDENT','MANUAL_RESEND'
  ) or p_started_at_utc is null then
    raise exception 'WEEKLY_SOURCE_MANAGER_TRIGGER_INVALID' using errcode='22023';
  end if;
  select * into strict v_route
  from public.weekly_manager_recipient_routes
  where id=p_recipient_route_id for update;
  select * into v_old
  from public.weekly_manager_recipient_generations
  where id=v_route.current_generation_id and state='ACTIVE'
  for update;
  v_membership:=coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'activation_id',activation.id,
        'candidate_cohort_id',cohort.id,
        'candidate_generation_id',cohort.current_generation_id,
        'incident_id',incident.id,
        'comparison_revision_id',incident.current_comparison_revision_id
      ) order by private.weekly_source_query_ascii_fold_v1(client.name) collate "C",
                 client.id::text collate "C",
                 private.weekly_source_query_ascii_fold_v1(coalesce(
                   nullif(candidate.display_name,''),
                   pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name)
                 )) collate "C",
                 candidate.id::text collate "C",work_event.work_date,
                 comparison.system_start_at_local,incident.id
    )
    from public.weekly_candidate_cohorts cohort
    join public.weekly_route_activations activation
      on activation.source_cycle_id=cohort.source_cycle_id
     and activation.candidate_id=cohort.candidate_id
     and activation.client_id=cohort.client_id
     and activation.audience_route='MANAGER'
     and activation.route_mode in ('CANDIDATE_FIRST','MANAGER_DIRECT')
    join public.weekly_discrepancy_incidents incident
      on incident.source_cycle_id=cohort.source_cycle_id
     and incident.candidate_id=cohort.candidate_id
     and incident.client_id=cohort.client_id
     and incident.state='OPEN'
     and incident.manager_potential_state='AVAILABLE'
      -- 04A section 6: "Resolved and manager-answered/waiting-source items are
      -- not reintroduced", and section 1: an item "already answered by the
      -- manager but waiting for a later source remains visible to Office and is
      -- never included again".  A genuinely new EPISODE of the same incident is
      -- different work, and the recheck owner already resets manager_action_state
      -- when it raises the episode; nothing else may resurrect an answer.
      and incident.manager_action_state in ('NOT_SENT','DUE','SENT')
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
     and comparison.candidate_timesheet_id is not null
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    join public.clients client on client.id=incident.client_id
    join public.candidates candidate on candidate.id=incident.candidate_id
    where cohort.source_cycle_id=v_route.source_cycle_id
      and cohort.manager_recipient_route_key=v_route.normalised_recipient_hash
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
  ),'[]'::jsonb);
  if pg_catalog.jsonb_array_length(v_membership)=0 then
    return pg_catalog.jsonb_build_object('ok',true,'status','NO_MANAGER_ACTIONABLE_INCIDENTS');
  end if;
  v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_MANAGER_MEMBERSHIP_V1',v_membership);
  if v_old.id is not null and v_old.membership_hash=v_hash and not p_force_new then
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','UNCHANGED','recipient_generation_id',v_old.id,
      'recipient_route_id',v_route.id,'membership_hash',pg_catalog.encode(v_hash,'hex')
    );
  end if;
  if v_old.id is not null then
    update public.weekly_manager_recipient_routes set current_generation_id=null where id=v_route.id;
    update public.weekly_manager_recipient_generations
    set state='SUPERSEDED',superseded_at_utc=pg_catalog.transaction_timestamp()
    where id=v_old.id;
    -- 04A section 8: "A later cohort merely becoming due is not a revocation
    -- event for an earlier accepted batch", and section 1: a later generation
    -- "cannot broaden, alter, supersede or revoke an already accepted earlier
    -- batch merely by becoming due".  The only express revocation the pack names
    -- is correcting a final source.  So an ACCEPTED batch and its live secure
    -- link survive this rotation untouched, and section 8's promise -- the
    -- manager "may answer some items, close the page and return later" -- keeps
    -- holding.
    --
    -- A batch whose render never reached provider submission (section 9) was
    -- never accepted: nothing was sent, its command and intent are retired just
    -- below, and the delivery start guard would refuse it anyway.  That batch is
    -- revoked here so its rows return to the unsent pool rather than being
    -- silently owned by an email nobody received.
    update public.weekly_manager_review_batches batch
    set state='REVOKED'
    from public.weekly_message_renders render
    where render.id=batch.message_render_id
      and batch.recipient_generation_id=v_old.id and batch.state='ACTIVE'
      and render.state not in ('SUBMISSION_STARTED','ACCEPTED','AMBIGUOUS');
    update public.weekly_manager_route_receipts receipt
    set state='REVOKED',revoked_at_utc=pg_catalog.transaction_timestamp()
    from public.weekly_manager_review_batches batch
    where batch.id=receipt.review_batch_id
      and receipt.recipient_generation_id=v_old.id and receipt.state='ACTIVE'
      and batch.state='REVOKED';
    update public.weekly_manager_review_items item
    set response_state='OBSOLETE'
    from public.weekly_manager_review_batches batch
    where batch.id=item.review_batch_id
      and batch.recipient_generation_id=v_old.id and batch.state='REVOKED'
      and item.response_state='UNANSWERED';
    update public.weekly_manager_cohort_due_events
    set state='RETIRED' where recipient_generation_id=v_old.id and state='PENDING';
    update public.weekly_message_intents
    set state='RETIRED'
    where recipient_generation_id=v_old.id and state in ('DUE','RENDERED');
    update public.weekly_message_dispatch_commands command
    set state='RETIRED'
    from public.weekly_message_intents intent
    where command.message_intent_id=intent.id
      and intent.recipient_generation_id=v_old.id
      and command.state in ('READY','LEASED');
    update public.weekly_message_renders render
    set state='STALE'
    from public.weekly_message_intents intent
    where render.message_intent_id=intent.id and intent.recipient_generation_id=v_old.id
      and render.state='CURRENT';
  end if;
  select coalesce(pg_catalog.max(generation_number),0)+1 into v_generation
  from public.weekly_manager_recipient_generations where recipient_route_id=v_route.id;
  insert into public.weekly_manager_recipient_generations(
    recipient_route_id,generation_number,trigger_kind,state,membership_hash
  ) values (v_route.id,v_generation,p_trigger_kind,'ACTIVE',v_hash)
  returning * into v_new;
  for v_row in
    select
      activation.id as activation_id,cohort.id as cohort_id,
      cohort.current_generation_id as candidate_generation_id,
      incident.id as incident_id,incident.current_comparison_revision_id
    from public.weekly_candidate_cohorts cohort
    join public.weekly_route_activations activation
      on activation.source_cycle_id=cohort.source_cycle_id
     and activation.candidate_id=cohort.candidate_id
     and activation.client_id=cohort.client_id
     and activation.audience_route='MANAGER'
     and activation.route_mode in ('CANDIDATE_FIRST','MANAGER_DIRECT')
    join public.weekly_discrepancy_incidents incident
      on incident.source_cycle_id=cohort.source_cycle_id
     and incident.candidate_id=cohort.candidate_id
     and incident.client_id=cohort.client_id
      and incident.state='OPEN' and incident.manager_potential_state='AVAILABLE'
      -- 04A section 6: "Resolved and manager-answered/waiting-source items are
      -- not reintroduced", and section 1: an item "already answered by the
      -- manager but waiting for a later source remains visible to Office and is
      -- never included again".  A genuinely new EPISODE of the same incident is
      -- different work, and the recheck owner already resets manager_action_state
      -- when it raises the episode; nothing else may resurrect an answer.
      and incident.manager_action_state in ('NOT_SENT','DUE','SENT')
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
     and comparison.candidate_timesheet_id is not null
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    join public.clients client on client.id=incident.client_id
    join public.candidates candidate on candidate.id=incident.candidate_id
    where cohort.source_cycle_id=v_route.source_cycle_id
      and cohort.manager_recipient_route_key=v_route.normalised_recipient_hash
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
    order by private.weekly_source_query_ascii_fold_v1(client.name) collate "C",
             client.id::text collate "C",
             private.weekly_source_query_ascii_fold_v1(coalesce(
               nullif(candidate.display_name,''),
               pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name)
             )) collate "C",
             candidate.id::text collate "C",work_event.work_date,
             comparison.system_start_at_local,incident.id
  loop
    -- A due-but-unsent row returns to the unsent pool, because the intent,
    -- command and render that made it due are retired above and this generation
    -- must be able to drive it again.  A SENT row stays SENT and a RESPONDED row
    -- keeps its answer: 04A section 1 forbids a later generation from altering
    -- an already accepted batch, and section 6 forbids reintroducing a
    -- manager-answered or waiting-source item.
    if p_trigger_kind='NEW_INCIDENT' then
      update public.weekly_discrepancy_incidents
      set manager_action_state='NOT_SENT',waiting_source_state='NOT_WAITING',
          reconciliation_state='UNRESOLVED'
      where id=v_row.incident_id
        and manager_action_state='DUE'
        and not private.weekly_source_query_manager_row_owned_v1(
          v_route.id,id,episode_number
        );
    end if;
    v_ordinal:=v_ordinal+1;
    insert into public.weekly_manager_recipient_memberships(
      recipient_generation_id,route_activation_id,candidate_outreach_generation_id,
      candidate_cohort_id,incident_id,comparison_revision_id,membership_role,ordinal
    ) values (
      v_new.id,v_row.activation_id,v_row.candidate_generation_id,v_row.cohort_id,
      v_row.incident_id,v_row.current_comparison_revision_id,'MANAGER_ACTIONABLE',v_ordinal
    );
  end loop;
  update public.weekly_manager_recipient_routes
  set current_generation_id=v_new.id where id=v_route.id;

  select * into strict v_settings from public.weekly_source_global_settings where singleton;
  for v_row in
    select distinct membership.candidate_cohort_id,activation.route_mode
    from public.weekly_manager_recipient_memberships membership
    join public.weekly_route_activations activation on activation.id=membership.route_activation_id
    where membership.recipient_generation_id=v_new.id
    order by membership.candidate_cohort_id
  loop
    v_candidate_generation.id:=null;
    v_candidate_generation.started_at_utc:=null;
    v_candidate_generation.deadline_at_utc:=null;
    if v_row.route_mode='MANAGER_DIRECT' then
      v_event_kind:='EARLY_ALL';
      v_due:=p_started_at_utc;
    else
      select * into v_candidate_generation
      from public.weekly_candidate_outreach_generations
      where id=(select current_generation_id from public.weekly_candidate_cohorts where id=v_row.candidate_cohort_id);
      if not found then
        continue;
      end if;
      v_event_kind:='T6_RESPONDED';
      v_due:=v_candidate_generation.started_at_utc+v_settings.manager_partial_digest_after;
    end if;
    v_trigger_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_MANAGER_COHORT_DUE_V1',
      pg_catalog.jsonb_build_object(
        'recipient_generation_id',v_new.id,'candidate_cohort_id',v_row.candidate_cohort_id,
        'event_kind',v_event_kind,'due_at_utc',v_due
      )
    );
    insert into public.weekly_manager_cohort_due_events(
      recipient_generation_id,candidate_cohort_id,event_kind,cohort_started_at_utc,
      due_at_utc,state,trigger_hash
    ) values (
      v_new.id,v_row.candidate_cohort_id,v_event_kind,
      coalesce(v_candidate_generation.started_at_utc,p_started_at_utc),v_due,'PENDING',v_trigger_hash
    ) on conflict (recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
    if v_row.route_mode='CANDIDATE_FIRST' then
      v_event_kind:='T12_REMAINDER';
      v_due:=v_candidate_generation.deadline_at_utc;
      v_trigger_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_MANAGER_COHORT_DUE_V1',
        pg_catalog.jsonb_build_object(
          'recipient_generation_id',v_new.id,'candidate_cohort_id',v_row.candidate_cohort_id,
          'event_kind',v_event_kind,'due_at_utc',v_due
        )
      );
      insert into public.weekly_manager_cohort_due_events(
        recipient_generation_id,candidate_cohort_id,event_kind,cohort_started_at_utc,
        due_at_utc,state,trigger_hash
      ) values (
        v_new.id,v_row.candidate_cohort_id,v_event_kind,
        v_candidate_generation.started_at_utc,v_due,'PENDING',v_trigger_hash
      ) on conflict (recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
    end if;
  end loop;
  -- A requested signed week is a bounded exception, not a persistent route
  -- override. Recreate its exact due scope on generation rotation without
  -- changing its original completion time or touching Office choices.
  insert into public.weekly_manager_cohort_due_events(
    recipient_generation_id,candidate_cohort_id,event_kind,cohort_started_at_utc,
    due_at_utc,state,trigger_hash,requested_week_membership_id
  )
  select distinct v_new.id,membership.candidate_cohort_id,'EARLY_ALL',requested.completed_at_utc,
    requested.completed_at_utc,'PENDING',private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_REQUESTED_WEEK_MANAGER_DUE_V1',pg_catalog.jsonb_build_object(
        'recipient_generation_id',v_new.id,'requested_week_membership_id',requested.id)),requested.id
  from public.weekly_manager_recipient_memberships membership
  join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
  join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work_event on work_event.id=incident.work_event_id
  join public.weekly_timesheet_submission_requests request
    on request.source_cycle_id=incident.source_cycle_id and request.candidate_id=incident.candidate_id
  join public.weekly_timesheet_submission_request_memberships requested
    on requested.submission_request_id=request.id and requested.client_id=incident.client_id
    and requested.contract_id=comparison.contract_id and work_event.work_date>requested.week_ending-7
    and work_event.work_date<=requested.week_ending and requested.state='SUBMITTED_WITH_ISSUES'
  where membership.recipient_generation_id=v_new.id and incident.state='OPEN'
    and incident.candidate_action_state='NOT_REQUIRED'
    and not private.weekly_source_query_manager_row_owned_v1(v_route.id,incident.id,incident.episode_number)
  on conflict(recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
  return pg_catalog.jsonb_build_object(
    'ok',true,'status','CREATED','recipient_route_id',v_route.id,
    'recipient_generation_id',v_new.id,
    'membership_hash',pg_catalog.encode(v_new.membership_hash,'hex')
  );
end;
$function$;

create or replace function private.weekly_source_query_manager_intent_v1(
  p_recipient_route_id uuid,
  p_recipient_generation_id uuid,
  p_due_event_ids uuid[],
  p_tranche_kind text,
  p_tranche_sequence integer,
  p_due_at_utc timestamptz
) returns uuid
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_route public.weekly_manager_recipient_routes%rowtype;
  v_generation public.weekly_manager_recipient_generations%rowtype;
  v_intent public.weekly_message_intents%rowtype;
  v_events uuid[];
  v_key bytea;
begin
  if p_tranche_kind not in (
    'MANAGER_EARLY_ALL','MANAGER_T6_RESPONDED','MANAGER_T12_REMAINDER',
    'MANAGER_MANUAL_SELECTED','MANAGER_MANUAL_RESEND'
  ) or p_tranche_sequence<1 or p_due_at_utc is null then
    raise exception 'WEEKLY_SOURCE_MANAGER_INTENT_INVALID' using errcode='22023';
  end if;
  select * into strict v_route
  from public.weekly_manager_recipient_routes where id=p_recipient_route_id;
  select * into strict v_generation
  from public.weekly_manager_recipient_generations
  where id=p_recipient_generation_id and recipient_route_id=v_route.id and state='ACTIVE';
  select coalesce(pg_catalog.array_agg(event_id order by event_id),'{}'::uuid[]) into v_events
  from pg_catalog.unnest(coalesce(p_due_event_ids,'{}'::uuid[])) event_id;
  v_key:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_MESSAGE_INTENT_V1',
    pg_catalog.jsonb_build_object(
      'environment',v_route.environment,'agency_id',v_route.agency_id,
      'source_cycle_id',v_route.source_cycle_id,'recipient_route_id',v_route.id,
      'recipient_generation_id',v_generation.id,'due_event_ids',v_events,
      'tranche_kind',p_tranche_kind,'tranche_sequence',p_tranche_sequence,
      'membership_hash',pg_catalog.encode(v_generation.membership_hash,'hex')
    )
  );
  insert into public.weekly_message_intents(
    environment,agency_id,source_cycle_id,audience_kind,recipient_route_id,
    recipient_generation_id,sorted_due_event_ids,tranche_kind,tranche_sequence,
    logical_key,state,due_at_utc
  ) values (
    v_route.environment,v_route.agency_id,v_route.source_cycle_id,'MANAGER',v_route.id,
    v_generation.id,v_events,p_tranche_kind,p_tranche_sequence,v_key,'DUE',p_due_at_utc
  ) on conflict (logical_key) do nothing;
  select * into strict v_intent from public.weekly_message_intents where logical_key=v_key;
  return v_intent.id;
end;
$function$;

create or replace function private.weekly_source_query_restart_activated_cohort_v1(
  p_source_cycle_id uuid,
  p_candidate_id uuid,
  p_client_id uuid,
  p_projection_publication_id uuid
) returns void
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_activation public.weekly_route_activations%rowtype;
  v_candidate_result jsonb;
  v_first record;
  v_cohort_context jsonb;
begin
  -- Bootstrap only policy-eligible new work; previously this owner could
  -- restart an Office-activated route but never begin the first request.
  perform private.weekly_source_import_outreach_v1(p_projection_publication_id);
  select * into v_activation
  from public.weekly_route_activations
  where source_cycle_id=p_source_cycle_id and candidate_id=p_candidate_id
    and client_id=p_client_id and audience_route='CANDIDATE';
  if found and v_activation.route_mode='CANDIDATE_FIRST' then
    v_candidate_result:=private.weekly_source_query_candidate_generation_v1(
      p_source_cycle_id,p_candidate_id,p_client_id,p_projection_publication_id,
      'NEW_INCIDENT',v_activation.activated_by_user_id,pg_catalog.transaction_timestamp()
    );
  end if;
  select comparison.contract_id,work_event.work_date into v_first
  from public.weekly_discrepancy_incidents incident
  join public.weekly_issue_comparison_revisions comparison
    on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work_event on work_event.id=incident.work_event_id
  where incident.source_cycle_id=p_source_cycle_id and incident.candidate_id=p_candidate_id
    and incident.client_id=p_client_id and incident.state='OPEN'
  order by work_event.work_date,incident.id limit 1;
  if found then
    v_cohort_context:=private.weekly_source_query_cohort_ensure_v1(
      p_source_cycle_id,p_candidate_id,p_client_id,v_first.contract_id,v_first.work_date
    );
  end if;
  select * into v_activation
  from public.weekly_route_activations
  where source_cycle_id=p_source_cycle_id and candidate_id=p_candidate_id
    and client_id=p_client_id and audience_route='MANAGER';
  if found and v_activation.route_mode in ('CANDIDATE_FIRST','MANAGER_DIRECT')
     and nullif(v_cohort_context->>'manager_route_id','') is not null then
    perform private.weekly_source_query_manager_generation_v1(
      (v_cohort_context->>'manager_route_id')::uuid,'NEW_INCIDENT',
      pg_catalog.transaction_timestamp(),false
    );
  end if;
end;
$function$;


create or replace function private.weekly_source_query_cohort_ensure_v1(
  p_source_cycle_id uuid,
  p_candidate_id uuid,
  p_client_id uuid,
  p_contract_id uuid,
  p_work_date date
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_policy jsonb;
  v_recipient text;
  v_route_key bytea;
  v_cohort public.weekly_candidate_cohorts%rowtype;
  v_route public.weekly_manager_recipient_routes%rowtype;
begin
  select * into strict v_cycle
  from public.weekly_source_cycles where id=p_source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups where id=v_cycle.source_group_id;
  v_policy:=private._weekly_source_effective_policy_v1(p_client_id,p_contract_id,p_work_date);
  if v_policy->>'source_group_id'<>v_group.id::text
     or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or v_policy->>'document_mode'<>'CHECK_ONLY' then
    raise exception 'WEEKLY_SOURCE_SECURE_QUERY_NOT_APPLICABLE' using errcode='55000';
  end if;
  v_recipient:=case
    when coalesce((v_policy->>'manager_queries_enabled')::boolean,false)
    then private.weekly_source_query_normalise_recipient_v1(v_policy->>'manager_query_recipient')
    else null
  end;
  v_route_key:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_MANAGER_RECIPIENT_ROUTE_V1',
    pg_catalog.jsonb_build_object(
      'environment',v_group.environment,'agency_id',v_group.agency_id,
      'source_cycle_id',v_cycle.id,
      'recipient',coalesce(v_recipient,'NO_MANAGER_ROUTE')
    )
  );
  insert into public.weekly_candidate_cohorts(
    source_cycle_id,candidate_id,client_id,manager_recipient_route_key
  ) values (v_cycle.id,p_candidate_id,p_client_id,v_route_key)
  on conflict (source_cycle_id,candidate_id,client_id,manager_recipient_route_key)
  do nothing;
  select * into strict v_cohort
  from public.weekly_candidate_cohorts
  where source_cycle_id=v_cycle.id and candidate_id=p_candidate_id
    and client_id=p_client_id and manager_recipient_route_key=v_route_key;
  if v_recipient is not null then
    insert into public.weekly_manager_recipient_routes(
      environment,agency_id,source_cycle_id,normalised_recipient_hash,
      protected_recipient_address
    ) values (
      v_group.environment,v_group.agency_id,v_cycle.id,v_route_key,v_recipient
    ) on conflict (environment,agency_id,source_cycle_id,normalised_recipient_hash)
    do nothing;
    select * into strict v_route
    from public.weekly_manager_recipient_routes
    where environment=v_group.environment and agency_id=v_group.agency_id
      and source_cycle_id=v_cycle.id and normalised_recipient_hash=v_route_key;
    if private.weekly_source_query_normalise_recipient_v1(v_route.protected_recipient_address)
       is distinct from v_recipient then
      raise exception 'WEEKLY_SOURCE_MANAGER_RECIPIENT_ROUTE_CONFLICT' using errcode='55000';
    end if;
  end if;
  return pg_catalog.jsonb_build_object(
    'cohort_id',v_cohort.id,'manager_route_id',v_route.id,
    'manager_route_key',pg_catalog.encode(v_route_key,'hex'),
    'candidate_queries_enabled',coalesce((v_policy->>'candidate_queries_enabled')::boolean,false),
    'manager_queries_enabled',coalesce((v_policy->>'manager_queries_enabled')::boolean,false),
    'manager_recipient',v_recipient
  );
end;
$function$;

create or replace function private.weekly_source_query_candidate_intent_v1(
  p_generation_id uuid,
  p_tranche_kind text,
  p_tranche_sequence integer,
  p_due_at_utc timestamptz
) returns uuid
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_generation public.weekly_candidate_outreach_generations%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_intent public.weekly_message_intents%rowtype;
  v_key bytea;
begin
  if p_tranche_kind not in (
    'CANDIDATE_INITIAL','CANDIDATE_REMINDER_6H','CANDIDATE_MANUAL_REMINDER',
    'TIMESHEET_SUBMISSION_INITIAL','TIMESHEET_SUBMISSION_REMINDER_6H'
  ) or p_tranche_sequence<1 or p_due_at_utc is null then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_INTENT_INVALID' using errcode='22023';
  end if;
  select * into strict v_generation
  from public.weekly_candidate_outreach_generations where id=p_generation_id;
  select * into strict v_cycle
  from public.weekly_source_cycles where id=v_generation.source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups where id=v_cycle.source_group_id;
  v_key:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_MESSAGE_INTENT_V1',
    pg_catalog.jsonb_build_object(
      'environment',v_group.environment,'agency_id',v_group.agency_id,
      'source_cycle_id',v_cycle.id,'candidate_cohort_id',v_generation.candidate_cohort_id,
      'candidate_generation_id',v_generation.id,'tranche_kind',p_tranche_kind,
      'tranche_sequence',p_tranche_sequence
    )
  );
  insert into public.weekly_message_intents(
    environment,agency_id,source_cycle_id,audience_kind,candidate_cohort_id,
    candidate_generation_id,sorted_due_event_ids,tranche_kind,tranche_sequence,
    logical_key,state,due_at_utc
  ) values (
    v_group.environment,v_group.agency_id,v_cycle.id,'CANDIDATE',
    v_generation.candidate_cohort_id,v_generation.id,'{}'::uuid[],
    p_tranche_kind,p_tranche_sequence,v_key,'DUE',p_due_at_utc
  ) on conflict (logical_key) do nothing;
  select * into strict v_intent from public.weekly_message_intents where logical_key=v_key;
  return v_intent.id;
end;
$function$;

create or replace function private.weekly_source_query_candidate_generation_v1(
  p_source_cycle_id uuid,
  p_candidate_id uuid,
  p_client_id uuid,
  p_projection_publication_id uuid,
  p_trigger_kind text,
  p_actor_user_id uuid,
  p_started_at_utc timestamptz
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_first record;
  v_cohort_context jsonb;
  v_cohort public.weekly_candidate_cohorts%rowtype;
  v_activation public.weekly_route_activations%rowtype;
  v_old public.weekly_candidate_outreach_generations%rowtype;
  v_new public.weekly_candidate_outreach_generations%rowtype;
  v_settings public.weekly_source_global_settings%rowtype;
  v_membership jsonb;
  v_hash bytea;
  v_generation_number integer;
  v_ordinal integer:=0;
  v_row record;
  v_intent_id uuid;
begin
  if p_trigger_kind not in ('OFFICE_ASK','NEW_INCIDENT','REOPENED_INCIDENT') then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_TRIGGER_INVALID' using errcode='22023';
  end if;
  select incident.id,comparison.contract_id,work_event.work_date
  into v_first
  from public.weekly_discrepancy_incidents incident
  join public.weekly_issue_comparison_revisions comparison
    on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work_event on work_event.id=incident.work_event_id
  where incident.source_cycle_id=p_source_cycle_id and incident.candidate_id=p_candidate_id
    and incident.client_id=p_client_id and incident.state='OPEN'
    and not private.weekly_source_covered_hours_incident_v1(incident.id)
    and (
      not private.weekly_source_waiting_requested_week_v1(p_source_cycle_id,p_candidate_id,
        p_client_id,comparison.contract_id,work_event.work_date)
    ) and (
      (p_trigger_kind in ('NEW_INCIDENT','REOPENED_INCIDENT')
       and incident.candidate_action_state<>'NOT_REQUIRED')
      or incident.candidate_action_state not in ('RESPONDED','NOT_REQUIRED')
    )
  order by work_event.work_date,incident.id
  limit 1;
  if not found then
    return pg_catalog.jsonb_build_object('ok',true,'status','NO_ACTIONABLE_INCIDENTS');
  end if;
  v_cohort_context:=private.weekly_source_query_cohort_ensure_v1(
    p_source_cycle_id,p_candidate_id,p_client_id,v_first.contract_id,v_first.work_date
  );
  if coalesce((v_cohort_context->>'candidate_queries_enabled')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_QUERIES_DISABLED' using errcode='55000';
  end if;
  select * into strict v_cohort
  from public.weekly_candidate_cohorts where id=(v_cohort_context->>'cohort_id')::uuid
  for update;
  insert into public.weekly_route_activations(
    source_cycle_id,candidate_id,client_id,audience_route,route_mode,
    activated_by_user_id,activated_at_utc,updated_at_utc
  ) values (
    p_source_cycle_id,p_candidate_id,p_client_id,'CANDIDATE','CANDIDATE_FIRST',
    p_actor_user_id,p_started_at_utc,p_started_at_utc
  ) on conflict (source_cycle_id,candidate_id,client_id,audience_route)
  do update set
    route_mode='CANDIDATE_FIRST',
    activated_by_user_id=coalesce(public.weekly_route_activations.activated_by_user_id,excluded.activated_by_user_id),
    activated_at_utc=coalesce(public.weekly_route_activations.activated_at_utc,excluded.activated_at_utc),
    updated_at_utc=excluded.updated_at_utc
  returning * into v_activation;
  select * into v_old
  from public.weekly_candidate_outreach_generations
  where candidate_cohort_id=v_cohort.id and state='ACTIVE' and request_kind='CHECK_HOURS'
  for update;
  v_membership:=coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'incident_id',incident.id,
        'comparison_revision_id',incident.current_comparison_revision_id
      ) order by work_event.work_date,comparison.candidate_start_at_local,incident.id
    )
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    where incident.source_cycle_id=p_source_cycle_id and incident.candidate_id=p_candidate_id
      and incident.client_id=p_client_id and incident.state='OPEN'
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
      and (
        not private.weekly_source_waiting_requested_week_v1(p_source_cycle_id,p_candidate_id,
          p_client_id,comparison.contract_id,work_event.work_date)
      ) and (
        (p_trigger_kind in ('NEW_INCIDENT','REOPENED_INCIDENT')
         and incident.candidate_action_state<>'NOT_REQUIRED')
        or incident.candidate_action_state not in ('RESPONDED','NOT_REQUIRED')
      )
  ),'[]'::jsonb);
  if pg_catalog.jsonb_array_length(v_membership)=0 then
    return pg_catalog.jsonb_build_object('ok',true,'status','NO_ACTIONABLE_INCIDENTS');
  end if;
  v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CANDIDATE_MEMBERSHIP_V1',v_membership);
  if v_old.id is not null and v_old.membership_hash=v_hash then
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','UNCHANGED','candidate_generation_id',v_old.id,
      'candidate_cohort_id',v_cohort.id
    );
  end if;
  if v_old.id is not null then
    update public.weekly_candidate_cohorts set current_generation_id=null where id=v_cohort.id;
    update public.weekly_candidate_outreach_generations
    set state='SUPERSEDED',superseded_at_utc=pg_catalog.transaction_timestamp()
    where id=v_old.id;
    update public.weekly_candidate_outreach_memberships
    set state='SUPERSEDED' where candidate_generation_id=v_old.id and state='ACTIONABLE';
    update public.weekly_message_intents
    set state='RETIRED'
    where candidate_generation_id=v_old.id and state in ('DUE','RENDERED');
    update public.weekly_message_dispatch_commands
    set state='RETIRED'
    where candidate_generation_id=v_old.id and state in ('READY','LEASED');
    update public.weekly_message_renders render
    set state='STALE'
    from public.weekly_message_intents intent
    where render.message_intent_id=intent.id and intent.candidate_generation_id=v_old.id
      and render.state='CURRENT';
  end if;
  select * into strict v_settings from public.weekly_source_global_settings where singleton;
  select coalesce(pg_catalog.max(generation_number),0)+1 into v_generation_number
  from public.weekly_candidate_outreach_generations where candidate_cohort_id=v_cohort.id;
  insert into public.weekly_candidate_outreach_generations(
    source_cycle_id,candidate_cohort_id,candidate_id,client_id,generation_number,
    activation_id,trigger_kind,request_kind,route_mode,started_at_utc,
    reminder_due_at_utc,deadline_at_utc,manual_reminder_available_at_utc,
    state,membership_hash
  ) values (
    p_source_cycle_id,v_cohort.id,p_candidate_id,p_client_id,v_generation_number,
    v_activation.id,p_trigger_kind,'CHECK_HOURS','CANDIDATE_FIRST',p_started_at_utc,
    p_started_at_utc+v_settings.candidate_reminder_after,
    p_started_at_utc+v_settings.candidate_response_deadline_after,
    p_started_at_utc+v_settings.candidate_manual_reminder_cooldown,
    'ACTIVE',v_hash
  ) returning * into v_new;
  for v_row in
    select incident.id as incident_id,incident.current_comparison_revision_id
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    where incident.source_cycle_id=p_source_cycle_id and incident.candidate_id=p_candidate_id
      and incident.client_id=p_client_id and incident.state='OPEN'
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
      and (
        not private.weekly_source_waiting_requested_week_v1(p_source_cycle_id,p_candidate_id,
          p_client_id,comparison.contract_id,work_event.work_date)
      ) and (
        (p_trigger_kind in ('NEW_INCIDENT','REOPENED_INCIDENT')
         and incident.candidate_action_state<>'NOT_REQUIRED')
        or incident.candidate_action_state not in ('RESPONDED','NOT_REQUIRED')
      )
    order by work_event.work_date,comparison.candidate_start_at_local,incident.id
  loop
    v_ordinal:=v_ordinal+1;
    insert into public.weekly_candidate_outreach_memberships(
      candidate_generation_id,incident_id,comparison_revision_id,ordinal,state
    ) values (v_new.id,v_row.incident_id,v_row.current_comparison_revision_id,v_ordinal,'ACTIONABLE');
    update public.weekly_discrepancy_incidents
    set candidate_action_state='ASKED'
    where id=v_row.incident_id
      and candidate_action_state in ('NOT_ASKED','RESPONDED');
    insert into public.weekly_discrepancy_events(
      incident_id,issue_episode,projection_publication_id,
      expected_comparison_fingerprint,event_kind,actor_kind,actor_user_id,
      bounded_payload_json,idempotency_key,occurred_at_utc
    )
    select incident.id,incident.episode_number,p_projection_publication_id,
      comparison.material_comparison_fingerprint,'REQUESTED',
      case when p_actor_user_id is null then 'SYSTEM' else 'OFFICE' end,p_actor_user_id,
      pg_catalog.jsonb_build_object(
        'route','CANDIDATE_FIRST','candidate_generation_id',v_new.id
      ),
      'CANDIDATE_REQUESTED:'||v_new.id::text||':'||incident.id::text,p_started_at_utc
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
    where incident.id=v_row.incident_id
    on conflict (event_kind,idempotency_key) do nothing;
  end loop;
  update public.weekly_candidate_cohorts set current_generation_id=v_new.id where id=v_cohort.id;
  v_intent_id:=private.weekly_source_query_candidate_intent_v1(
    v_new.id,'CANDIDATE_INITIAL',1,p_started_at_utc
  );
  return pg_catalog.jsonb_build_object(
    'ok',true,'status','CREATED','candidate_generation_id',v_new.id,
    'candidate_cohort_id',v_cohort.id,'message_intent_id',v_intent_id,
    'started_at_utc',v_new.started_at_utc,
    'reminder_due_at_utc',v_new.reminder_due_at_utc,
    'deadline_at_utc',v_new.deadline_at_utc,
    'membership_hash',pg_catalog.encode(v_new.membership_hash,'hex')
  );
end;
$function$;


create or replace function private.weekly_source_query_hex32_v1(
  p_value text,
  p_code text
) returns bytea
language plpgsql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
begin
  if p_value is null or p_value !~ '^[0-9a-f]{64}$' then
    raise exception '%',coalesce(p_code,'WEEKLY_SOURCE_HASH_INVALID') using errcode='22023';
  end if;
  return pg_catalog.decode(p_value,'hex');
end;
$function$;

create or replace function private.weekly_source_query_ascii_fold_v1(p_value text)
returns text
language sql
immutable
strict
set search_path to 'pg_catalog','pg_temp'
as $function$
  select pg_catalog.translate(
    p_value,
    'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
    'abcdefghijklmnopqrstuvwxyz'
  );
$function$;

create or replace function private.weekly_source_query_normalise_recipient_v1(
  p_address text
) returns text
language plpgsql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_address text;
begin
  v_address:=pg_catalog.lower(normalize(pg_catalog.btrim(coalesce(p_address,'')),NFKC));
  if pg_catalog.char_length(v_address) not between 3 and 254
     or v_address !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or v_address ~ '[[:cntrl:]]' then
    raise exception 'WEEKLY_SOURCE_MANAGER_RECIPIENT_INVALID' using errcode='22023';
  end if;
  return v_address;
end;
$function$;

create or replace function private.weekly_source_query_current_publication_v1(
  p_source_cycle_id uuid,
  p_projection_publication_id uuid
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_cycle public.weekly_source_cycles%rowtype;
  v_publication_cycle public.weekly_source_cycles%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
begin
  if p_source_cycle_id is null or p_projection_publication_id is null then
    raise exception 'WEEKLY_SOURCE_QUERY_PUBLICATION_REQUIRED' using errcode='22023';
  end if;
  select * into v_cycle
  from public.weekly_source_cycles
  where id=p_source_cycle_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select * into v_publication
  from public.weekly_source_projection_publications
  where id=p_projection_publication_id;
  if not found or v_publication.state<>'CURRENT' then
    raise exception 'SOURCE_CHECK_IN_PROGRESS' using errcode='55000';
  end if;
  select * into strict v_publication_cycle
  from public.weekly_source_cycles
  where id=v_publication.source_cycle_id;
  if v_publication_cycle.source_group_id<>v_cycle.source_group_id
     or v_publication_cycle.scope_client_id is distinct from v_cycle.scope_client_id
     or v_publication_cycle.finalisation_week_ending<v_cycle.finalisation_week_ending then
    raise exception 'WEEKLY_SOURCE_QUERY_PUBLICATION_SCOPE_INVALID' using errcode='55000';
  end if;
  select * into strict v_upload
  from public.weekly_source_uploads
  where id=v_publication.upload_id and state='CURRENT';
  if v_publication.authority_scope_kind='CYCLE' then
    if v_publication.report_scope_id is not null
       or v_publication_cycle.current_complete_upload_id is distinct from v_publication.upload_id
       or v_publication_cycle.current_projection_publication_id is distinct from v_publication.id
       or v_publication_cycle.version is distinct from v_publication.authority_scope_version
       or v_publication_cycle.projection_state<>'CURRENT' then
      raise exception 'SOURCE_CHECK_IN_PROGRESS' using errcode='55000';
    end if;
  elsif v_publication.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into v_scope
    from public.weekly_source_report_scopes
    where id=v_publication.report_scope_id
      and source_cycle_id=v_publication_cycle.id;
    if not found
       or v_scope.current_complete_upload_id is distinct from v_publication.upload_id
       or v_scope.current_projection_publication_id is distinct from v_publication.id
       or v_scope.version is distinct from v_publication.authority_scope_version
       or v_scope.projection_state<>'CURRENT' then
      raise exception 'SOURCE_CHECK_IN_PROGRESS' using errcode='55000';
    end if;
  else
    raise exception 'WEEKLY_SOURCE_QUERY_PUBLICATION_SCOPE_INVALID' using errcode='55000';
  end if;
  return pg_catalog.jsonb_build_object(
    'source_cycle_id',v_publication_cycle.id,
    'origin_source_cycle_id',v_cycle.id,
    'source_group_id',v_cycle.source_group_id,
    'scope_client_id',v_publication_cycle.scope_client_id,
    'finalisation_week_ending',v_publication_cycle.finalisation_week_ending,
    'publication_id',v_publication.id,
    'upload_id',v_publication.upload_id,
    'authority_scope_kind',v_publication.authority_scope_kind,
    'report_scope_id',v_publication.report_scope_id,
    'authority_scope_version',v_publication.authority_scope_version
  );
end;
$function$;

create or replace function private.weekly_source_query_response_fingerprint_v1(
  p_review_batch_id uuid,
  p_review_item_id uuid,
  p_incident_id uuid,
  p_incident_episode integer,
  p_comparison_revision_id uuid,
  p_comparison_fingerprint bytea
) returns bytea
language sql
stable
security definer
set search_path to 'private','pg_catalog','pg_temp'
as $function$
  select private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_MANAGER_RESPONSE_FACT_V1',
    pg_catalog.jsonb_build_object(
      'review_batch_id',p_review_batch_id,
      'review_item_id',p_review_item_id,
      'incident_id',p_incident_id,
      'incident_episode',p_incident_episode,
      'comparison_revision_id',p_comparison_revision_id,
      'comparison_fingerprint',pg_catalog.encode(p_comparison_fingerprint,'hex')
    )
  );
$function$;

create or replace function private.weekly_source_query_candidate_timesheet_hash_v1(
  p_timesheet_id uuid
) returns bytea
language sql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  select private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_CANDIDATE_SIGNED_TIMESHEET_V1',
    pg_catalog.jsonb_build_object(
      'timesheet_id',t.timesheet_id,
      'version',t.version,
      'contract_id',t.contract_id,
      'week_ending_date',t.week_ending_date,
      'actual_schedule_json',coalesce(t.actual_schedule_json,'[]'::jsonb),
      'additional_units_week',coalesce(t.additional_units_week,'{}'::jsonb),
      'additional_units_per_day',coalesce(t.additional_units_per_day,'{}'::jsonb),
      'nurse_evidence_sha256',t.img_sha256_nurse,
      'nurse_evidence_key',t.r2_nurse_key,
      'candidate_manager_approved_at_utc',t.candidate_manager_approved_at_utc
    )
  )
  from public.timesheets t
  where t.timesheet_id=p_timesheet_id
    and t.is_current
    and t.revoked_at is null
    and t.archived_at_utc is null
    and t.sheet_scope='WEEKLY'
    and t.line_type='HOURS'
    and t.r2_nurse_key is not null
    and t.img_sha256_nurse is not null;
$function$;

create or replace function private.weekly_source_query_incident_policy_v1(
  p_incident_id uuid
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_comparison public.weekly_issue_comparison_revisions%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_policy jsonb;
begin
  select * into strict v_incident
  from public.weekly_discrepancy_incidents where id=p_incident_id;
  select * into strict v_comparison
  from public.weekly_issue_comparison_revisions
  where id=v_incident.current_comparison_revision_id;
  select * into strict v_event
  from public.weekly_work_events where id=v_incident.work_event_id;
  v_policy:=private._weekly_source_effective_policy_v1(
    v_incident.client_id,v_comparison.contract_id,v_event.work_date
  );
  if v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or v_policy->>'document_mode'<>'CHECK_ONLY' then
    raise exception 'WEEKLY_SOURCE_SECURE_QUERY_NOT_APPLICABLE' using errcode='55000';
  end if;
  return v_policy;
end;
$function$;

create or replace function private.weekly_source_query_notice_fanout_v1(
  p_incident_id uuid,
  p_event_id uuid,
  p_event_kind text,
  p_payload jsonb
) returns integer
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_inserted integer;
begin
  select * into strict v_incident
  from public.weekly_discrepancy_incidents where id=p_incident_id;
  if p_event_kind not in (
    'WEEKLY_CANDIDATE_SOURCE_DISPUTED',
    'WEEKLY_MANAGER_SYSTEM_CONFIRMED',
    'WEEKLY_MANAGER_SOURCE_CORRECTED'
  ) or pg_catalog.jsonb_typeof(p_payload)<>'object'
     or p_payload ?| array['pay','pay_rate','charge','charge_rate','margin','vat','invoice','banking'] then
    raise exception 'WEEKLY_SOURCE_NOTICE_PAYLOAD_INVALID' using errcode='22023';
  end if;
  insert into public.office_action_notifications(
    recipient_user_id,event_kind,issue_id,issue_generation,response_event_id,
    payload_json,dedupe_key,operational_state,resolved_at_utc
  )
  select
    office_user.id,p_event_kind,v_incident.id,v_incident.episode_number,p_event_id,
    p_payload,
    'WEEKLY_SOURCE_NOTICE_V1:'||p_event_id::text,
    case when v_incident.state='RESOLVED' then 'RESOLVED' else 'OPEN' end,
    case when v_incident.state='RESOLVED' then pg_catalog.transaction_timestamp() end
  from public.tms_users office_user
  where office_user.is_active
    and pg_catalog.lower(pg_catalog.btrim(office_user.role)) in ('admin','user')
  on conflict (recipient_user_id,response_event_id) do nothing;
  get diagnostics v_inserted=row_count;
  return v_inserted;
end;
$function$;

create or replace function private.weekly_source_query_comparison_fingerprint_v1(
  p_incident_id uuid,
  p_episode integer,
  p_work_event_id uuid,
  p_issue jsonb
) returns bytea
language sql
stable
security definer
set search_path to 'private','pg_catalog','pg_temp'
as $function$
  select private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_MATERIAL_COMPARISON_V1',
    pg_catalog.jsonb_build_object(
      'incident_id',p_incident_id,
      'episode_number',p_episode,
      'work_event_id',p_work_event_id,
      'candidate_timesheet_id',nullif(p_issue->>'candidate_timesheet_id','')::uuid,
      'candidate_timesheet_revision',nullif(p_issue->>'candidate_timesheet_revision','')::integer,
      'candidate_shift_fingerprint',pg_catalog.lower(nullif(p_issue->>'candidate_shift_fingerprint','')),
      'contract_id',nullif(p_issue->>'contract_id','')::uuid,
      'issue_family',pg_catalog.upper(pg_catalog.btrim(coalesce(p_issue->>'issue_family',''))),
      'source_presence',pg_catalog.upper(pg_catalog.btrim(coalesce(p_issue->>'source_presence',''))),
      'candidate_start_at_local',nullif(p_issue->>'candidate_start_at_local','')::timestamp,
      'candidate_end_at_local',nullif(p_issue->>'candidate_end_at_local','')::timestamp,
      'candidate_break_minutes',nullif(p_issue->>'candidate_break_minutes','')::integer,
      'system_start_at_local',nullif(p_issue->>'system_start_at_local','')::timestamp,
      'system_end_at_local',nullif(p_issue->>'system_end_at_local','')::timestamp,
      'system_break_minutes',nullif(p_issue->>'system_break_minutes','')::integer
    )
  );
$function$;

-- A resolution accepting the reviewed source facts survives a repeat import.
-- Compare business facts, not upload/report IDs or a whole-week signature
-- revision. A SOURCE_MATCHED resolution is deliberately different: its last
-- stored comparison describes the former disagreement, not the later match.
create or replace function private.weekly_source_query_resolved_decision_matches_v1(
  p_source_group_id uuid,p_work_event_id uuid,p_issue jsonb
) returns boolean language sql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
  with latest as (
    select incident.state,incident.resolution_kind,incident.current_comparison_revision_id
    from public.weekly_discrepancy_incidents incident
    where incident.source_group_id=p_source_group_id and incident.work_event_id=p_work_event_id
    order by incident.episode_number desc,incident.id desc limit 1
  )
  select coalesce((select latest.state='RESOLVED'
    and latest.resolution_kind in ('OFFICE_ACCEPTED_SYSTEM_HOURS','MANAGER_CONFIRMED_SYSTEM_HOURS','CANDIDATE_CORRECTED')
    and comparison.contract_id is not distinct from nullif(p_issue->>'contract_id','')::uuid
    and comparison.issue_family is not distinct from upper(btrim(p_issue->>'issue_family'))
    and comparison.source_presence is not distinct from upper(btrim(p_issue->>'source_presence'))
    and comparison.candidate_start_at_local is not distinct from nullif(p_issue->>'candidate_start_at_local','')::timestamp
    and comparison.candidate_end_at_local is not distinct from nullif(p_issue->>'candidate_end_at_local','')::timestamp
    and comparison.candidate_break_minutes is not distinct from nullif(p_issue->>'candidate_break_minutes','')::integer
    and comparison.system_start_at_local is not distinct from nullif(p_issue->>'system_start_at_local','')::timestamp
    and comparison.system_end_at_local is not distinct from nullif(p_issue->>'system_end_at_local','')::timestamp
    and comparison.system_break_minutes is not distinct from nullif(p_issue->>'system_break_minutes','')::integer
    from latest join public.weekly_issue_comparison_revisions comparison
      on comparison.id=latest.current_comparison_revision_id),false);
$function$;
alter function private.weekly_source_query_resolved_decision_matches_v1(uuid,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_query_resolved_decision_matches_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;

create or replace function public.weekly_source_query_sync_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_actor uuid;
  v_cycle_id uuid;
  v_publication_id uuid;
  v_guard jsonb;
  v_group_id uuid;
  v_upload_id uuid;
  v_scope_kind text;
  v_report_scope_id uuid;
  v_current_report_client_id uuid;
  v_final_authority_kind text;
  v_omission_meaning text;
  v_issue jsonb;
  v_event public.weekly_work_events%rowtype;
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_comparison public.weekly_issue_comparison_revisions%rowtype;
  v_policy jsonb;
  v_issue_family text;
  v_presence text;
  v_episode integer;
  v_revision integer;
  v_fingerprint bytea;
  v_expected bytea;
  v_contract_id uuid;
  v_timesheet_id uuid;
  v_timesheet_revision integer;
  v_candidate_shift_hash bytea;
  v_source_row_id uuid;
  v_source_link_id uuid;
  v_new_count integer:=0;
  v_changed_count integer:=0;
  v_unchanged_count integer:=0;
  v_resolved_count integer:=0;
  v_seen_work_events uuid[]:='{}'::uuid[];
  v_new_cohort_keys text[]:='{}'::text[];
  v_cohort_key text;
  v_is_new boolean;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(
       select 1 from pg_catalog.jsonb_object_keys(p_request) key
       where key not in ('actor_user_id','source_cycle_id','projection_publication_id','issues')
     ) or pg_catalog.jsonb_typeof(p_request->'issues')<>'array' then
    raise exception 'WEEKLY_SOURCE_QUERY_SYNC_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_QUERY_SYNC_REQUEST_INVALID' using errcode='22023';
  end;
  v_guard:=private.weekly_source_query_current_publication_v1(v_cycle_id,v_publication_id);
  v_group_id:=(v_guard->>'source_group_id')::uuid;
  v_upload_id:=(v_guard->>'upload_id')::uuid;
  v_scope_kind:=v_guard->>'authority_scope_kind';
  v_report_scope_id:=nullif(v_guard->>'report_scope_id','')::uuid;
  select profile.final_authority_kind,profile.omission_meaning
  into strict v_final_authority_kind,v_omission_meaning
  from public.weekly_source_uploads upload
  join public.weekly_source_format_profiles profile
    on profile.id=upload.source_format_profile_id
  where upload.id=v_upload_id;
  if v_scope_kind='NHSP_REPORT_SCOPE' then
    select client_id into strict v_current_report_client_id
    from public.weekly_source_report_scopes
    where id=v_report_scope_id and source_cycle_id=v_cycle_id;
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'RECHECK_SOURCE',v_group_id,null,(v_guard->>'finalisation_week_ending')::date
  );
  perform private.weekly_source_pay_query_admit_v2();
  perform 1 from public.weekly_source_cycles where id=v_cycle_id for update;
  v_guard:=private.weekly_source_query_current_publication_v1(v_cycle_id,v_publication_id);
  perform private.weekly_source_office_authority_v1(
    v_actor,'RECHECK_SOURCE',v_group_id,null,(v_guard->>'finalisation_week_ending')::date);

  for v_issue in
    select value
    from pg_catalog.jsonb_array_elements(p_request->'issues')
    order by value->>'work_event_id'
  loop
    if pg_catalog.jsonb_typeof(v_issue)<>'object'
       or exists(
         select 1 from pg_catalog.jsonb_object_keys(v_issue) key
         where key not in (
           'work_event_id','candidate_timesheet_id','candidate_timesheet_revision',
           'candidate_shift_fingerprint','source_row_id','source_work_event_link_id',
           'contract_id','issue_family','source_presence','candidate_start_at_local',
           'candidate_end_at_local','candidate_break_minutes','system_start_at_local',
           'system_end_at_local','system_break_minutes','expected_material_comparison_fingerprint'
         )
       ) then
      raise exception 'WEEKLY_SOURCE_QUERY_ISSUE_INVALID' using errcode='22023';
    end if;
    begin
      select * into strict v_event from public.weekly_work_events
      where id=(v_issue->>'work_event_id')::uuid
        and first_source_group_id=v_group_id
        and (nullif(v_guard->>'scope_client_id','') is null
          or client_id=(v_guard->>'scope_client_id')::uuid);
      v_contract_id:=nullif(v_issue->>'contract_id','')::uuid;
      v_timesheet_id:=nullif(v_issue->>'candidate_timesheet_id','')::uuid;
      v_timesheet_revision:=nullif(v_issue->>'candidate_timesheet_revision','')::integer;
      v_candidate_shift_hash:=case when nullif(v_issue->>'candidate_shift_fingerprint','') is null
        then null else private.weekly_source_query_hex32_v1(
          v_issue->>'candidate_shift_fingerprint','WEEKLY_SOURCE_CANDIDATE_SHIFT_HASH_INVALID'
        ) end;
      v_source_row_id:=nullif(v_issue->>'source_row_id','')::uuid;
      v_source_link_id:=nullif(v_issue->>'source_work_event_link_id','')::uuid;
    exception when no_data_found or invalid_text_representation then
      raise exception 'WEEKLY_SOURCE_QUERY_ISSUE_IDENTITY_INVALID' using errcode='22023';
    end;
    if v_event.id=any(v_seen_work_events) then
      raise exception 'WEEKLY_SOURCE_QUERY_DUPLICATE_WORK_EVENT' using errcode='22023';
    end if;
    v_seen_work_events:=pg_catalog.array_append(v_seen_work_events,v_event.id);
    v_issue_family:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_issue->>'issue_family','')));
    v_presence:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_issue->>'source_presence','')));
    if v_issue_family='CANDIDATE_TIMESHEET_MISSING' then
      raise exception 'WEEKLY_SOURCE_USE_TIMESHEET_SUBMISSION_REQUEST' using errcode='22023';
    end if;
    if v_issue_family not in (
      'SOURCE_MISSING_OR_NOT_AUTHORISED','SOURCE_HOURS_DIFFER',
      'REFERENCE_MISSING','HEALTHROSTER_NOT_FINALISED'
    ) or v_presence not in ('PRESENT','ABSENT','UNFINALISED') then
      raise exception 'WEEKLY_SOURCE_QUERY_ISSUE_KIND_INVALID' using errcode='22023';
    end if;
    if v_issue_family='SOURCE_HOURS_DIFFER' and v_presence<>'PRESENT' then
      raise exception 'WEEKLY_SOURCE_QUERY_PRESENCE_INVALID' using errcode='22023';
    end if;
    if v_issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED' and v_presence<>'ABSENT' then
      raise exception 'WEEKLY_SOURCE_QUERY_PRESENCE_INVALID' using errcode='22023';
    end if;
    if v_issue_family='HEALTHROSTER_NOT_FINALISED' and v_presence<>'UNFINALISED' then
      raise exception 'WEEKLY_SOURCE_QUERY_PRESENCE_INVALID' using errcode='22023';
    end if;
    if v_timesheet_id is null or v_timesheet_revision is null or v_candidate_shift_hash is null
       or not exists(
         select 1 from public.timesheets t
         where t.timesheet_id=v_timesheet_id
           and t.version=v_timesheet_revision
           and t.contract_id=v_contract_id
           and t.week_ending_date>=v_event.work_date
           and t.week_ending_date<v_event.work_date+7
           and t.is_current and t.revoked_at is null and t.archived_at_utc is null
           and t.sheet_scope='WEEKLY' and t.line_type='HOURS'
           and t.r2_nurse_key is not null and t.img_sha256_nurse is not null
       ) then
      raise exception 'WEEKLY_SOURCE_SIGNED_TIMESHEET_REQUIRED' using errcode='55000';
    end if;
    if v_source_row_id is not null and not exists(
      select 1 from public.weekly_source_upload_rows r
      where r.id=v_source_row_id and r.upload_id=v_upload_id
    ) then
      raise exception 'WEEKLY_SOURCE_QUERY_SOURCE_ROW_STALE' using errcode='55000';
    end if;
    if v_source_link_id is not null and not exists(
      select 1
      from public.weekly_work_event_source_links link
      join public.weekly_source_row_resolutions resolution
        on resolution.id=link.row_resolution_id
      where link.id=v_source_link_id and link.work_event_id=v_event.id
        and (v_source_row_id is null or link.upload_row_id=v_source_row_id)
        and resolution.mapping_state='RESOLVED'
        and resolution.work_event_id=v_event.id
        and resolution.candidate_id=v_event.candidate_id
        and resolution.client_id=v_event.client_id
        and resolution.contract_id=v_contract_id
    ) then
      raise exception 'WEEKLY_SOURCE_QUERY_SOURCE_LINK_INVALID' using errcode='55000';
    end if;
    v_policy:=private._weekly_source_effective_policy_v1(
      v_event.client_id,v_contract_id,v_event.work_date
    );
    if v_policy->>'source_group_id'<>v_group_id::text
       or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
       or v_policy->>'document_mode'<>'CHECK_ONLY' then
      raise exception 'WEEKLY_SOURCE_SECURE_QUERY_NOT_APPLICABLE' using errcode='55000';
    end if;

    perform 1 from public.weekly_work_events where id=v_event.id for update;
    if private.weekly_source_query_resolved_decision_matches_v1(v_group_id,v_event.id,v_issue) then
      v_unchanged_count:=v_unchanged_count+1;
      continue;
    end if;
    select * into v_incident
    from public.weekly_discrepancy_incidents
    where source_group_id=v_group_id and work_event_id=v_event.id and state='OPEN'
    for update;
    v_is_new:=not found;
    if v_is_new then
      select coalesce(pg_catalog.max(episode_number),0)+1 into v_episode
      from public.weekly_discrepancy_incidents
      where source_group_id=v_group_id and work_event_id=v_event.id;
      insert into public.weekly_discrepancy_incidents(
        source_group_id,work_event_id,episode_number,candidate_id,client_id,
        source_cycle_id,state,reconciliation_state,candidate_action_state,
        manager_potential_state,manager_action_state,waiting_source_state
      ) values (
        v_group_id,v_event.id,v_episode,v_event.candidate_id,v_event.client_id,
        v_cycle_id,'OPEN','UNRESOLVED',
        case when coalesce((v_policy->>'candidate_queries_enabled')::boolean,false)
          then 'NOT_ASKED' else 'NOT_REQUIRED' end,
        case when coalesce((v_policy->>'manager_queries_enabled')::boolean,false)
                   and nullif(v_policy->>'manager_query_recipient','') is not null
          then 'AVAILABLE' else 'NOT_AVAILABLE' end,
        case when coalesce((v_policy->>'manager_queries_enabled')::boolean,false)
                   and nullif(v_policy->>'manager_query_recipient','') is not null
          then 'NOT_SENT' else 'NOT_REQUIRED' end,
        'NOT_WAITING'
      ) returning * into v_incident;
      v_new_count:=v_new_count+1;
      v_new_cohort_keys:=pg_catalog.array_append(
        v_new_cohort_keys,
        v_cycle_id::text||':'||v_event.candidate_id::text||':'||v_event.client_id::text
      );
    else
      if v_incident.candidate_id is distinct from v_event.candidate_id
         or v_incident.client_id is distinct from v_event.client_id then
        raise exception 'WEEKLY_SOURCE_QUERY_INCIDENT_SCOPE_INVALID' using errcode='55000';
      end if;
      if v_incident.current_comparison_revision_id is null then
        raise exception 'WEEKLY_SOURCE_QUERY_INCIDENT_SCOPE_INVALID' using errcode='55000';
      end if;
      select * into strict v_comparison
      from public.weekly_issue_comparison_revisions
      where id=v_incident.current_comparison_revision_id;
      if v_comparison.contract_id is distinct from v_contract_id
         or exists(
           select 1
           from public.weekly_source_cycles origin_cycle
           where origin_cycle.id=v_incident.source_cycle_id
             and origin_cycle.finalisation_week_ending>(v_guard->>'finalisation_week_ending')::date
         ) then
        raise exception 'WEEKLY_SOURCE_QUERY_INCIDENT_SCOPE_INVALID' using errcode='55000';
      end if;
      v_episode:=v_incident.episode_number;
    end if;
    if v_is_new then
      v_comparison.id:=null;
    end if;
    v_fingerprint:=private.weekly_source_query_comparison_fingerprint_v1(
      v_incident.id,v_episode,v_event.id,v_issue
    );
    if not v_is_new and v_comparison.id is not null
       and v_comparison.material_comparison_fingerprint<>v_fingerprint then
      -- A changed source tuple is a new comparison revision of the same open
      -- episode. Only a resolved work event that reappears starts a new episode.
      -- Preserve route activation, due times and accepted manager memberships.
      v_changed_count:=v_changed_count+1;
    end if;
    if nullif(v_issue->>'expected_material_comparison_fingerprint','') is not null then
      v_expected:=private.weekly_source_query_hex32_v1(
        v_issue->>'expected_material_comparison_fingerprint',
        'WEEKLY_SOURCE_COMPARISON_HASH_INVALID'
      );
      if v_expected is distinct from v_fingerprint then
        raise exception 'WEEKLY_SOURCE_COMPARISON_HASH_MISMATCH' using errcode='40001';
      end if;
    end if;
    if v_comparison.id is not null
       and v_comparison.material_comparison_fingerprint=v_fingerprint then
      v_unchanged_count:=v_unchanged_count+1;
    else
      select coalesce(pg_catalog.max(revision_number),0)+1 into v_revision
      from public.weekly_issue_comparison_revisions
      where incident_id=v_incident.id;
      insert into public.weekly_issue_comparison_revisions(
        incident_id,revision_number,projection_publication_id,comparison_upload_id,
        final_revision_id,candidate_timesheet_id,candidate_timesheet_revision,
        candidate_shift_fingerprint,source_row_id,source_work_event_link_id,
        contract_id,issue_family,source_presence,candidate_start_at_local,
        candidate_end_at_local,candidate_break_minutes,system_start_at_local,
        system_end_at_local,system_break_minutes,material_comparison_fingerprint
      ) values (
        v_incident.id,v_revision,v_publication_id,v_upload_id,null,
        v_timesheet_id,v_timesheet_revision,v_candidate_shift_hash,v_source_row_id,
        v_source_link_id,v_contract_id,v_issue_family,v_presence,
        nullif(v_issue->>'candidate_start_at_local','')::timestamp,
        nullif(v_issue->>'candidate_end_at_local','')::timestamp,
        nullif(v_issue->>'candidate_break_minutes','')::integer,
        nullif(v_issue->>'system_start_at_local','')::timestamp,
        nullif(v_issue->>'system_end_at_local','')::timestamp,
        nullif(v_issue->>'system_break_minutes','')::integer,
        v_fingerprint
      ) returning * into v_comparison;
      update public.weekly_discrepancy_incidents
      set current_comparison_revision_id=v_comparison.id
      where id=v_incident.id;
      insert into public.weekly_discrepancy_events(
        incident_id,issue_episode,projection_publication_id,
        expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,
        idempotency_key
      ) values (
        v_incident.id,v_incident.episode_number,v_publication_id,v_fingerprint,
        'SOURCE_RECHECKED','SYSTEM',
        pg_catalog.jsonb_build_object(
          'issue_family',v_issue_family,'source_presence',v_presence,
          'comparison_revision_id',v_comparison.id
        ),
        'SOURCE_RECHECKED:'||v_incident.id::text||':'||pg_catalog.encode(v_fingerprint,'hex')
      ) on conflict (event_kind,idempotency_key) do nothing;
    end if;
  end loop;

  for v_incident in
    select incident.*
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
    join public.weekly_source_cycles origin_cycle
      on origin_cycle.id=incident.source_cycle_id
    where incident.source_group_id=v_group_id
      and incident.state='OPEN'
      and (nullif(v_guard->>'scope_client_id','') is null
        or incident.client_id=(v_guard->>'scope_client_id')::uuid)
      and not (incident.work_event_id=any(v_seen_work_events))
      and origin_cycle.finalisation_week_ending<=(v_guard->>'finalisation_week_ending')::date
      and (
        v_scope_kind='CYCLE'
        or (v_scope_kind='NHSP_REPORT_SCOPE' and incident.client_id=v_current_report_client_id)
      )
      and (
        v_omission_meaning='CANCEL_INSIDE_CONFIRMED_COVERAGE'
        or (
          v_final_authority_kind='NHSP_TRUST_BACKING_REPORT'
          and exists(
            select 1
            from public.weekly_work_event_source_links current_link
            join public.weekly_source_upload_rows current_row
              on current_row.id=current_link.upload_row_id
            join public.weekly_source_row_resolutions current_resolution
              on current_resolution.id=current_link.row_resolution_id
            where current_row.upload_id=v_upload_id
              and current_link.work_event_id=incident.work_event_id
              and current_link.link_kind in ('PROVISIONAL_SOURCE','POSITIVE_SOURCE')
              and current_row.row_finalisation_state='SOURCE_WORKED'
              and current_resolution.mapping_state='RESOLVED'
              and current_resolution.work_event_id=incident.work_event_id
              and current_resolution.candidate_id=incident.candidate_id
              and current_resolution.client_id=incident.client_id
              and current_resolution.contract_id=comparison.contract_id
              and current_row.start_at_local=comparison.candidate_start_at_local
              and current_row.end_at_local=comparison.candidate_end_at_local
              and current_row.break_minutes=comparison.candidate_break_minutes
          )
        )
      )
      and not exists(
        select 1
        from public.weekly_source_upload_rows current_row
        join public.weekly_source_row_resolutions current_resolution
          on current_resolution.upload_row_id=current_row.id
        where current_row.upload_id=v_upload_id
          and current_resolution.mapping_state='RESOLVED'
          and current_resolution.work_event_id=incident.work_event_id
          and (
            current_resolution.candidate_id is distinct from incident.candidate_id
            or current_resolution.client_id is distinct from incident.client_id
            or current_resolution.contract_id is distinct from comparison.contract_id
          )
      )
    order by incident.id
    for update of incident
  loop
    update public.weekly_discrepancy_incidents
    set state='RESOLVED',reconciliation_state='RECONCILED',
        candidate_action_state='NOT_REQUIRED',manager_potential_state='NOT_REQUIRED',
        manager_action_state='NOT_REQUIRED',waiting_source_state='SOURCE_MATCHED',
        resolved_at_utc=pg_catalog.transaction_timestamp(),resolution_kind='SOURCE_MATCHED'
    where id=v_incident.id;
    update public.weekly_candidate_outreach_memberships
    set state='RESOLVED'
    where incident_id=v_incident.id and state in ('ACTIONABLE','ANSWERED');
    update public.weekly_manager_review_items
    set response_state='FILTERED_RESOLVED'
    where incident_id=v_incident.id and response_state='UNANSWERED';
    update public.office_action_notifications
    set operational_state='RESOLVED',resolved_at_utc=pg_catalog.transaction_timestamp()
    where issue_id=v_incident.id and operational_state='OPEN';
    insert into public.weekly_discrepancy_events(
      incident_id,issue_episode,projection_publication_id,
      expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,
      idempotency_key
    ) values (
      v_incident.id,v_incident.episode_number,v_publication_id,null,
      'RESOLVED','SYSTEM',pg_catalog.jsonb_build_object('resolution','SOURCE_MATCHED'),
      'SOURCE_MATCHED:'||v_incident.id::text||':'||v_publication_id::text
    ) on conflict (event_kind,idempotency_key) do nothing;
    v_resolved_count:=v_resolved_count+1;
  end loop;

  for v_cohort_key in
    select distinct key_value collate "C" as key_value
    from pg_catalog.unnest(v_new_cohort_keys) as key_value
    order by key_value
  loop
    perform private.weekly_source_query_restart_activated_cohort_v1(
      pg_catalog.split_part(v_cohort_key,':',1)::uuid,
      pg_catalog.split_part(v_cohort_key,':',2)::uuid,
      pg_catalog.split_part(v_cohort_key,':',3)::uuid,
      v_publication_id
    );
  end loop;

  perform private.weekly_source_import_outreach_v1(v_publication_id);
  perform public._audit_insert(
    'weekly_source_query_sync',v_publication_id::text,'WEEKLY_SOURCE_QUERY_SYNCED',
    null,
    pg_catalog.jsonb_build_object(
      'source_cycle_id',v_cycle_id,'new_incidents',v_new_count,
      'changed_comparisons',v_changed_count,'unchanged_incidents',v_unchanged_count,
      'resolved_incidents',v_resolved_count
    ),
    'Current Weekly source comparison issues synchronised',v_actor
  );
  return pg_catalog.jsonb_build_object(
    'ok',true,'source_cycle_id',v_cycle_id,'projection_publication_id',v_publication_id,
    'new_incidents',v_new_count,'changed_comparisons',v_changed_count,
    'unchanged_incidents',v_unchanged_count,'resolved_incidents',v_resolved_count
  );
end;
$function$;

-- The broker/service boundary is the only callable API surface. Candidate and
-- manager browsers never receive direct function or table privileges.
do $acl$
declare
  v_name text;
  v_public_names constant text[]:=array[
    'weekly_source_candidate_query_get_v1',
    'weekly_source_message_render_input_v1',
    'weekly_source_timesheet_submission_complete_atomic_v1',
    'weekly_source_query_accept_system_hours_atomic_v1',
    'weekly_source_office_notifications_list_v1',
    'weekly_source_office_notification_ack_atomic_v1',
    'weekly_source_manager_review_get_v1',
    'weekly_source_manager_review_respond_atomic_v1',
    'weekly_source_message_dispatch_claim_v1',
    'weekly_source_message_dispatch_submission_start_atomic_v1',
    'weekly_source_message_dispatch_result_atomic_v1',
    'weekly_source_manager_route_prepare_atomic_v1',
    'weekly_source_message_render_stage_atomic_v1',
    'weekly_source_query_scheduler_tick_v1',
    'weekly_source_candidate_response_submit_atomic_v1',
    'weekly_source_query_send_manager_now_atomic_v1',
    'weekly_source_candidate_reminder_atomic_v1',
    'weekly_source_query_ask_candidate_atomic_v1',
    'weekly_source_timesheet_submission_request_start_atomic_v1',
    'weekly_source_query_sync_atomic_v1'
  ];
  v_private_names constant text[]:=array[
    'weekly_source_query_require_service_v1',
    'weekly_source_query_manager_row_owned_v1',
    'weekly_source_query_manager_generation_v1',
    'weekly_source_query_manager_intent_v1',
    'weekly_source_query_restart_activated_cohort_v1',
    'weekly_source_query_cohort_ensure_v1',
    'weekly_source_query_candidate_intent_v1',
    'weekly_source_query_candidate_generation_v1',
    'weekly_source_query_hex32_v1',
    'weekly_source_query_ascii_fold_v1',
    'weekly_source_query_normalise_recipient_v1',
    'weekly_source_query_current_publication_v1',
    'weekly_source_query_response_fingerprint_v1',
    'weekly_source_query_candidate_timesheet_hash_v1',
    'weekly_source_query_incident_policy_v1',
    'weekly_source_query_notice_fanout_v1',
    'weekly_source_query_comparison_fingerprint_v1'
  ];
begin
  -- Keep ownership provider-neutral: the authenticated release owner owns the
  -- routines on both the local proof database and the Miget TEST database.
  if (select pg_catalog.count(*)
      from pg_catalog.pg_proc procedure
      join pg_catalog.pg_namespace namespace on namespace.oid=procedure.pronamespace
      where namespace.nspname='public' and procedure.proname=any(v_public_names)
        and pg_catalog.pg_get_function_identity_arguments(procedure.oid)='p_request jsonb')
     <>pg_catalog.array_length(v_public_names,1) then
    raise exception 'WEEKLY_SOURCE_QUERY_PUBLIC_RPC_SURFACE_INCOMPLETE';
  end if;
  foreach v_name in array v_public_names loop
    execute pg_catalog.format('alter function public.%I(jsonb) owner to current_user',v_name);
    execute pg_catalog.format(
      'revoke all on function public.%I(jsonb) from public,anon,authenticated,service_role',v_name
    );
    execute pg_catalog.format('grant execute on function public.%I(jsonb) to service_role',v_name);
  end loop;
  foreach v_name in array v_private_names loop
    if not exists(
      select 1 from pg_catalog.pg_proc procedure
      join pg_catalog.pg_namespace namespace on namespace.oid=procedure.pronamespace
      where namespace.nspname='private' and procedure.proname=v_name
    ) then
      raise exception 'WEEKLY_SOURCE_QUERY_PRIVATE_ROUTINE_MISSING: %',v_name;
    end if;
  end loop;
  for v_name in
    select pg_catalog.format('%I.%I(%s)',namespace.nspname,procedure.proname,
             pg_catalog.pg_get_function_identity_arguments(procedure.oid))
    from pg_catalog.pg_proc procedure
    join pg_catalog.pg_namespace namespace on namespace.oid=procedure.pronamespace
    where namespace.nspname='private' and procedure.proname=any(v_private_names)
    order by procedure.proname,pg_catalog.pg_get_function_identity_arguments(procedure.oid)
  loop
    execute 'alter function '||v_name||' owner to current_user';
    execute 'revoke all on function '||v_name||' from public,anon,authenticated,service_role';
  end loop;
end;
$acl$;

-- This repeatable can be replayed after the target-delivery upgrade. Preserve
-- its per-target boundary rather than reviving the retired whole-command rail.
create or replace function public.weekly_source_message_dispatch_submission_start_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
begin
  -- A replay of this earlier repeatable must not reopen whole-command delivery.
  perform private.weekly_source_query_require_service_v1();
  raise exception 'WEEKLY_SOURCE_PER_TARGET_DISPATCH_REQUIRED' using errcode='55000';
end;
$function$;

create or replace function public.weekly_source_message_dispatch_result_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
begin
  perform private.weekly_source_query_require_service_v1();
  raise exception 'WEEKLY_SOURCE_PER_TARGET_DISPATCH_REQUIRED' using errcode='55000';
end;
$function$;

comment on function public.weekly_source_query_sync_atomic_v1(jsonb) is
  'Service-only, non-financial synchronisation of current Weekly source discrepancy facts.';
comment on function public.weekly_source_manager_review_respond_atomic_v1(jsonb) is
  'Service-only broker boundary for receipt-first, partial manager review responses.';
comment on function public.weekly_source_message_dispatch_submission_start_atomic_v1(jsonb) is
  'Retired whole-command submission route; per-target dispatch is required.';
comment on function public.weekly_source_manager_route_prepare_atomic_v1(jsonb) is
  'Service-only reservation of the exact manager review batch and credential generation before remote registration and deterministic email rendering.';

-- An incremental replay of this earlier owner must end with the current
-- per-target transport, exactly as a clean full replay does. In particular
-- it must not reinstate the old command claim or a differently sealed retired
-- submission entry point while the later root's own hash is unchanged.
-- Replaceable Weekly Source communications transport.
--
-- The rendered message remains immutable.  Dispatch state is owned by one
-- durable row per exact target so acceptance by one Candidate device can never
-- close another device.  Candidate in-app notification creation is in the
-- same transaction as every accepted request/reminder intent.

create or replace function private.weekly_source_delivery_target_immutable_v1()
returns trigger
language plpgsql
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
begin
  if new.dispatch_command_id is distinct from old.dispatch_command_id
     or new.target_ordinal is distinct from old.target_ordinal
     or new.channel is distinct from old.channel
     or new.target_kind is distinct from old.target_kind
     or new.provider is distinct from old.provider
     or new.external_target_id is distinct from old.external_target_id
     or new.keyed_target_fingerprint is distinct from old.keyed_target_fingerprint
     or new.target_snapshot_hash is distinct from old.target_snapshot_hash
     or new.target_version is distinct from old.target_version
     or new.safe_target_snapshot_json is distinct from old.safe_target_snapshot_json
     or new.rendered_content_hash is distinct from old.rendered_content_hash
     or new.provider_idempotency_key is distinct from old.provider_idempotency_key
     or new.maximum_attempts is distinct from old.maximum_attempts
     or new.created_at_utc is distinct from old.created_at_utc then
    raise exception 'WEEKLY_SOURCE_DELIVERY_TARGET_IMMUTABLE' using errcode='55000';
  end if;
  new.updated_at_utc:=pg_catalog.transaction_timestamp();
  return new;
end;
$function$;

create or replace function public.weekly_source_message_dispatch_target_result_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_attempt_id uuid;
  v_outcome text;
  v_provider_message_id text;
  v_receipt jsonb;
  v_error jsonb;
  v_attempt public.weekly_message_target_attempts%rowtype;
  v_target public.weekly_message_dispatch_targets%rowtype;
  v_result_hash bytea;
  v_delay_seconds integer;
  v_error_code text;
  v_retirement_recorded boolean;
  v_aggregate jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in (
                 'provider_attempt_id','outcome','provider_message_id',
                 'bounded_provider_receipt','bounded_error'
               )) then
    raise exception 'WEEKLY_SOURCE_TARGET_RESULT_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_attempt_id:=(p_request->>'provider_attempt_id')::uuid;
    v_outcome:=pg_catalog.upper(pg_catalog.btrim(p_request->>'outcome'));
    v_provider_message_id:=nullif(pg_catalog.btrim(p_request->>'provider_message_id'),'');
    v_receipt:=coalesce(p_request->'bounded_provider_receipt','{}'::jsonb);
    v_error:=coalesce(p_request->'bounded_error','{}'::jsonb);
  exception when others then
    raise exception 'WEEKLY_SOURCE_TARGET_RESULT_REQUEST_INVALID' using errcode='22023';
  end;
  if v_outcome not in (
       'ACCEPTED','DEFINITELY_REJECTED','TRANSIENT_FAILURE','AMBIGUOUS'
     )
     or pg_catalog.jsonb_typeof(v_receipt)<>'object'
     or pg_catalog.jsonb_typeof(v_error)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(v_receipt) key
               where key not in ('provider_status','provider_request_id','retirement_recorded','proved_no_network'))
     or exists(select 1 from pg_catalog.jsonb_object_keys(v_error) key
               where key not in ('error_code','provider_status','retry_after_seconds'))
     or pg_catalog.char_length(coalesce(v_provider_message_id,''))>500
     or pg_catalog.char_length(coalesce(v_receipt->>'provider_request_id',''))>500
     or pg_catalog.char_length(coalesce(v_error->>'error_code',''))>120 then
    raise exception 'WEEKLY_SOURCE_TARGET_RESULT_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    if v_receipt ? 'provider_status' then
      perform (v_receipt->>'provider_status')::integer;
    end if;
    if v_error ? 'provider_status' then
      perform (v_error->>'provider_status')::integer;
    end if;
    if v_error ? 'retry_after_seconds' then
      perform (v_error->>'retry_after_seconds')::integer;
    end if;
    if v_receipt ? 'retirement_recorded' then
      v_retirement_recorded:=(v_receipt->>'retirement_recorded')::boolean;
    end if;
  exception when others then
    raise exception 'WEEKLY_SOURCE_TARGET_RESULT_REQUEST_INVALID' using errcode='22023';
  end;
  v_error_code:=nullif(pg_catalog.upper(v_error->>'error_code'),'');
  if v_error_code is not null and v_error_code!~'^[A-Z][A-Z0-9_]{1,119}$' then
    raise exception 'WEEKLY_SOURCE_TARGET_RESULT_REQUEST_INVALID' using errcode='22023';
  end if;
  v_result_hash:=extensions.digest(pg_catalog.convert_to(
    pg_catalog.jsonb_build_object(
      'provider_attempt_id',v_attempt_id,'outcome',v_outcome,
      'provider_message_id',v_provider_message_id,
      'bounded_provider_receipt',v_receipt,'bounded_error',v_error
    )::text,'UTF8'),'sha256');

  select * into strict v_attempt from public.weekly_message_target_attempts
  where id=v_attempt_id for update;
  select * into strict v_target from public.weekly_message_dispatch_targets
  where id=v_attempt.dispatch_target_id for update;
  if v_attempt.completed_at_utc is not null then
    if v_attempt.result_hash<>v_result_hash then
      raise exception 'WEEKLY_SOURCE_TARGET_RESULT_REPLAY_CONFLICT' using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'replay',true,'target_state',v_target.state,
      'dispatch_target_id',v_target.id,'dispatch_command_id',v_target.dispatch_command_id
    );
  end if;
  if v_target.state<>'SUBMISSION_STARTED' or v_target.attempt_count<>v_attempt.attempt_number then
    raise exception 'WEEKLY_SOURCE_TARGET_RESULT_STALE' using errcode='40001';
  end if;

  perform private.weekly_contact_source_result_v1(
    v_attempt.id,v_outcome,v_provider_message_id,v_receipt,v_error
  );

  update public.weekly_message_target_attempts
  set completed_at_utc=pg_catalog.transaction_timestamp(),outcome=v_outcome,
      provider_message_id=v_provider_message_id,
      bounded_provider_receipt_json=v_receipt,bounded_error_json=v_error,
      result_hash=v_result_hash
  where id=v_attempt.id;

  if v_outcome='ACCEPTED' then
    update public.weekly_message_dispatch_targets
    set state='ACCEPTED',provider_message_id=v_provider_message_id,
        provider_accepted_at_utc=pg_catalog.transaction_timestamp(),
        terminal_at_utc=pg_catalog.transaction_timestamp(),terminal_reason='PROVIDER_ACCEPTED',
        next_attempt_at_utc=null,lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
  elsif v_outcome='AMBIGUOUS' then
    update public.weekly_message_dispatch_targets
    set state='AMBIGUOUS',provider_message_id=v_provider_message_id,
        terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason=coalesce(v_error_code,'PROVIDER_OUTCOME_UNKNOWN'),
        next_attempt_at_utc=null,lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    insert into public.weekly_message_delivery_failures(
      dispatch_command_id,dispatch_target_id,failure_class,safe_failure_code,safe_context_json
    ) values (
      v_target.dispatch_command_id,v_target.id,'PROVIDER_AMBIGUOUS',
      coalesce(v_error_code,'PROVIDER_OUTCOME_UNKNOWN'),
      pg_catalog.jsonb_build_object('target_id',v_target.id,'attempt_number',v_attempt.attempt_number)
    ) on conflict do nothing;
  elsif v_outcome='TRANSIENT_FAILURE' and v_attempt.attempt_number<v_target.maximum_attempts then
    v_delay_seconds:=case v_attempt.attempt_number
      when 1 then 30 when 2 then 120 when 3 then 600 else 1800 end;
    if v_error ? 'retry_after_seconds' then
      v_delay_seconds:=greatest(
        v_delay_seconds,least((v_error->>'retry_after_seconds')::integer,3600)
      );
    end if;
    update public.weekly_message_dispatch_targets
    set state='TRANSIENT_FAILURE',next_attempt_at_utc=pg_catalog.transaction_timestamp()
          +pg_catalog.make_interval(secs=>v_delay_seconds),
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
  else
    update public.weekly_message_dispatch_targets
    set state='DEFINITELY_REJECTED',terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason=case when v_outcome='TRANSIENT_FAILURE'
          then 'RETRIES_EXHAUSTED' else coalesce(v_error_code,'PROVIDER_REJECTED') end,
        next_attempt_at_utc=null,lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    if v_outcome='TRANSIENT_FAILURE' then
      insert into public.weekly_message_delivery_failures(
        dispatch_command_id,dispatch_target_id,failure_class,safe_failure_code,safe_context_json
      ) values (
        v_target.dispatch_command_id,v_target.id,'RETRIES_EXHAUSTED','RETRIES_EXHAUSTED',
        pg_catalog.jsonb_build_object('target_id',v_target.id,'attempt_count',v_attempt.attempt_number)
      ) on conflict do nothing;
    elsif v_error_code='INVALID_TARGET' then
      insert into public.weekly_message_delivery_failures(
        dispatch_command_id,dispatch_target_id,failure_class,safe_failure_code,safe_context_json
      ) values (
        v_target.dispatch_command_id,v_target.id,'INVALID_TARGET','INVALID_TARGET',
        pg_catalog.jsonb_build_object('target_id',v_target.id,'retirement_recorded',coalesce(v_retirement_recorded,false))
      ) on conflict do nothing;
      if not coalesce(v_retirement_recorded,false) then
        insert into public.weekly_message_delivery_failures(
          dispatch_command_id,dispatch_target_id,failure_class,safe_failure_code,safe_context_json
        ) values (
          v_target.dispatch_command_id,v_target.id,'TARGET_RETIREMENT_FAILED',
          'TARGET_RETIREMENT_NOT_RECORDED',pg_catalog.jsonb_build_object('target_id',v_target.id)
        ) on conflict do nothing;
      end if;
    elsif v_error_code='PROVIDER_NOT_READY' then
      insert into public.weekly_message_delivery_failures(
        dispatch_command_id,dispatch_target_id,failure_class,safe_failure_code,safe_context_json
      ) values (
        v_target.dispatch_command_id,v_target.id,'PROVIDER_CONFIGURATION','PROVIDER_NOT_READY',
        pg_catalog.jsonb_build_object('target_id',v_target.id,'provider',v_target.provider)
      ) on conflict do nothing;
    end if;
  end if;

  v_aggregate:=private.weekly_source_delivery_aggregate_command_v1(v_target.dispatch_command_id);
  return pg_catalog.jsonb_build_object(
    'ok',true,'replay',false,'dispatch_target_id',v_target.id,
    'dispatch_command_id',v_target.dispatch_command_id,'outcome',v_outcome,
    'aggregate',v_aggregate
  );
end;
$function$;

-- The original command-level result functions can close a multi-device command
-- after one provider response.  Keep their signatures for a bounded migration
-- failure, but make the unsafe route impossible to call.
create or replace function public.weekly_source_message_dispatch_submission_start_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
begin
  perform private.weekly_source_query_require_service_v1();
  raise exception 'WEEKLY_SOURCE_PER_TARGET_DISPATCH_REQUIRED' using errcode='55000';
end;
$function$;

create or replace function public.weekly_source_message_dispatch_result_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
begin
  perform private.weekly_source_query_require_service_v1();
  raise exception 'WEEKLY_SOURCE_PER_TARGET_DISPATCH_REQUIRED' using errcode='55000';
end;
$function$;

create or replace function public.weekly_source_message_dispatch_target_claim_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_worker text;
  v_limit integer;
  v_lease_seconds integer;
  v_token uuid:=pg_catalog.gen_random_uuid();
  v_targets jsonb;
  v_stale record;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('worker_id','limit','lease_seconds')) then
    raise exception 'WEEKLY_SOURCE_TARGET_CLAIM_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_worker:=pg_catalog.btrim(p_request->>'worker_id');
    v_limit:=coalesce(nullif(p_request->>'limit','')::integer,50);
    v_lease_seconds:=coalesce(nullif(p_request->>'lease_seconds','')::integer,60);
  exception when others then
    raise exception 'WEEKLY_SOURCE_TARGET_CLAIM_REQUEST_INVALID' using errcode='22023';
  end;
  if v_worker is null or v_worker!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
     or v_limit<1 or v_limit>200 or v_lease_seconds<15 or v_lease_seconds>300 then
    raise exception 'WEEKLY_SOURCE_TARGET_CLAIM_REQUEST_INVALID' using errcode='22023';
  end if;

  -- Once submission started, an expired lease is an unknown provider outcome.
  -- It is never guessed and never resubmitted automatically.
  for v_stale in
    update public.weekly_message_dispatch_targets target
    set state='AMBIGUOUS',terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason='SUBMISSION_LEASE_EXPIRED',
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where target.state='SUBMISSION_STARTED'
      and target.lease_expires_at_utc<=pg_catalog.transaction_timestamp()
    returning target.id,target.dispatch_command_id
  loop
    insert into public.weekly_message_delivery_failures(
      dispatch_command_id,dispatch_target_id,failure_class,safe_failure_code,safe_context_json
    ) values (
      v_stale.dispatch_command_id,v_stale.id,'PROVIDER_AMBIGUOUS',
      'SUBMISSION_LEASE_EXPIRED',pg_catalog.jsonb_build_object('target_id',v_stale.id)
    ) on conflict do nothing;
    perform private.weekly_source_delivery_aggregate_command_v1(v_stale.dispatch_command_id);
  end loop;

  for v_stale in
    update public.weekly_message_dispatch_targets target
    set state=case when target.state='SUBMISSION_STARTED' then 'AMBIGUOUS' else 'RETIRED' end,
        terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason=case when target.state='SUBMISSION_STARTED'
          then 'REQUEST_RETIRED_AFTER_SUBMISSION' else 'REQUEST_RETIRED' end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    from public.weekly_message_dispatch_commands command,
         public.weekly_message_intents intent,
         public.weekly_message_renders render
    where target.dispatch_command_id=command.id
      and intent.id=command.message_intent_id
      and render.id=command.message_render_id
      and target.state not in (
        'ACCEPTED','DEFINITELY_REJECTED','AMBIGUOUS','RETIRED','SKIPPED'
      )
      and (intent.state='RETIRED' or render.state='STALE')
    returning target.id,target.dispatch_command_id,target.state
  loop
    if v_stale.state='AMBIGUOUS' then
      insert into public.weekly_message_delivery_failures(
        dispatch_command_id,dispatch_target_id,failure_class,safe_failure_code,safe_context_json
      ) values (
        v_stale.dispatch_command_id,v_stale.id,'PROVIDER_AMBIGUOUS',
        'REQUEST_RETIRED_AFTER_SUBMISSION',pg_catalog.jsonb_build_object('target_id',v_stale.id)
      ) on conflict do nothing;
    end if;
    perform private.weekly_source_delivery_aggregate_command_v1(v_stale.dispatch_command_id);
  end loop;

  with eligible as (
    select target.id
    from public.weekly_message_dispatch_targets target
    where (
      (target.state in ('READY','TRANSIENT_FAILURE')
        and coalesce(target.next_attempt_at_utc,'-infinity'::timestamptz)
          <=pg_catalog.transaction_timestamp())
      or
      (target.state='LEASED'
        and target.lease_expires_at_utc<=pg_catalog.transaction_timestamp())
    )
    order by target.next_attempt_at_utc nulls first,target.id
    limit v_limit
    for update skip locked
  ), claimed as (
    update public.weekly_message_dispatch_targets target
    set state='LEASED',lease_owner=v_worker,lease_token=v_token,
        lease_expires_at_utc=pg_catalog.transaction_timestamp()
          +pg_catalog.make_interval(secs=>v_lease_seconds)
    from eligible where target.id=eligible.id
    returning target.*
  )
  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'dispatch_target_id',claimed.id,'dispatch_command_id',command.id,
      'lease_token',claimed.lease_token,'lease_expires_at_utc',claimed.lease_expires_at_utc,
      'channel',claimed.channel,'target_kind',claimed.target_kind,'provider',claimed.provider,
      'external_target_id',claimed.external_target_id,
      'target_fingerprint',pg_catalog.encode(claimed.keyed_target_fingerprint,'hex'),
      'target_snapshot_hash',pg_catalog.encode(claimed.target_snapshot_hash,'hex'),
      'target_version',claimed.target_version,
      'safe_target_snapshot',claimed.safe_target_snapshot_json,
      'provider_idempotency_key',claimed.provider_idempotency_key,
      'rendered_content_hash',pg_catalog.encode(claimed.rendered_content_hash,'hex'),
      'subject_text',render.subject_text,'html_body',render.html_body,
      'plain_body',render.plain_body,
      'push_title',case
        when command.tranche_kind like 'TIMESHEET_SUBMISSION%' then 'Please submit your Timesheet'
        when command.tranche_kind like '%REMINDER%' then 'Reminder: check your Timesheet hours'
        else 'Check your Timesheet hours' end,
      'deep_link',notification.deep_link_json,
      'manager_recipient',case when claimed.channel='EMAIL'
        then route.protected_recipient_address else null end
    ) order by claimed.id
  ),'[]'::jsonb) into v_targets
  from claimed
  join public.weekly_message_dispatch_commands command on command.id=claimed.dispatch_command_id
  join public.weekly_message_renders render on render.id=command.message_render_id
  join public.weekly_message_intents intent on intent.id=command.message_intent_id
  left join public.weekly_manager_recipient_routes route on route.id=command.recipient_route_id
  left join public.weekly_candidate_message_notifications message_notification
    on message_notification.message_intent_id=intent.id
  left join public.candidate_notifications notification
    on notification.id=message_notification.notification_id;
  return pg_catalog.jsonb_build_object(
    'ok',true,'worker_id',v_worker,'lease_token',v_token,
    'claimed_count',pg_catalog.jsonb_array_length(v_targets),'targets',v_targets
  );
end;
$function$;

create or replace function public.weekly_source_message_dispatch_target_start_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_target_id uuid;
  v_lease_token uuid;
  v_worker text;
  v_target public.weekly_message_dispatch_targets%rowtype;
  v_command public.weekly_message_dispatch_commands%rowtype;
  v_intent public.weekly_message_intents%rowtype;
  v_render public.weekly_message_renders%rowtype;
  v_attempt public.weekly_message_target_attempts%rowtype;
  v_attempt_number integer;
  v_reason text;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('dispatch_target_id','lease_token','worker_id')) then
    raise exception 'WEEKLY_SOURCE_TARGET_START_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_target_id:=(p_request->>'dispatch_target_id')::uuid;
    v_lease_token:=(p_request->>'lease_token')::uuid;
    v_worker:=p_request->>'worker_id';
  exception when others then
    raise exception 'WEEKLY_SOURCE_TARGET_START_REQUEST_INVALID' using errcode='22023';
  end;
  select * into strict v_target from public.weekly_message_dispatch_targets
  where id=v_target_id for update;
  select * into strict v_command from public.weekly_message_dispatch_commands
  where id=v_target.dispatch_command_id for update;
  select * into strict v_intent from public.weekly_message_intents
  where id=v_command.message_intent_id;
  select * into strict v_render from public.weekly_message_renders
  where id=v_command.message_render_id;
  select * into v_attempt from public.weekly_message_target_attempts
  where dispatch_target_id=v_target.id and completed_at_utc is null
  order by attempt_number desc limit 1;
  if found and v_target.state='SUBMISSION_STARTED' then
    return pg_catalog.jsonb_build_object(
      'ok',true,'replay',true,'provider_attempt_id',v_attempt.id,
      'provider_idempotency_key',v_attempt.provider_idempotency_key
    );
  end if;
  if v_target.state<>'LEASED' or v_target.lease_token<>v_lease_token
     or v_target.lease_owner<>v_worker
     or v_target.lease_expires_at_utc<=pg_catalog.transaction_timestamp()
     or v_intent.state<>'RENDERED' or v_render.state<>'CURRENT' then
    raise exception 'WEEKLY_SOURCE_TARGET_LEASE_STALE' using errcode='40001';
  end if;
  begin
    perform private.weekly_source_query_current_publication_v1(
      v_command.source_cycle_id,v_command.projection_publication_id
    );
  exception when others then
    update public.weekly_message_dispatch_targets
    set state='RETIRED',terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason='CURRENT_HOURS_CHANGED',next_attempt_at_utc=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    perform private.weekly_source_delivery_aggregate_command_v1(v_command.id);
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason','CURRENT_HOURS_CHANGED',
      'dispatch_target_id',v_target.id,'dispatch_command_id',v_command.id
    );
  end;
  if v_intent.audience_kind='CANDIDATE' and not exists(
    select 1 from public.weekly_candidate_outreach_generations generation
    join public.weekly_candidate_cohorts cohort on cohort.id=generation.candidate_cohort_id
    where generation.id=v_command.candidate_generation_id and generation.state='ACTIVE'
      and private.weekly_source_candidate_generation_current_v1(generation.id)
  ) then
    update public.weekly_message_dispatch_targets
    set state='RETIRED',terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason='CANDIDATE_GENERATION_CHANGED',next_attempt_at_utc=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    perform private.weekly_source_delivery_aggregate_command_v1(v_command.id);
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason','CANDIDATE_GENERATION_CHANGED',
      'dispatch_target_id',v_target.id,'dispatch_command_id',v_command.id
    );
  elsif v_intent.audience_kind='CANDIDATE' and not exists(
    select 1
    from public.weekly_candidate_outreach_memberships membership
    join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
    where membership.candidate_generation_id=v_command.candidate_generation_id
      and membership.state='ACTIONABLE' and incident.state='OPEN'
  ) and not exists(
    select 1
    from public.weekly_candidate_outreach_generations generation
    join public.weekly_timesheet_submission_requests submission
      on submission.candidate_cohort_id=generation.candidate_cohort_id
     and submission.state in ('ACTIVE','OVERDUE','PARTLY_SUBMITTED')
    join public.weekly_timesheet_submission_request_memberships membership
      on membership.submission_request_id=submission.id and membership.state='WAITING'
    where generation.id=v_command.candidate_generation_id
      and generation.request_kind='SUBMIT_TIMESHEET'
  ) then
    update public.weekly_message_dispatch_targets
    set state='RETIRED',terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason='REQUEST_RESOLVED',next_attempt_at_utc=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    perform private.weekly_source_delivery_aggregate_command_v1(v_command.id);
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason','REQUEST_RESOLVED',
      'dispatch_target_id',v_target.id,'dispatch_command_id',v_command.id
    );
  elsif v_intent.audience_kind='MANAGER' and not exists(
    select 1
    from public.weekly_manager_recipient_generations generation
    join public.weekly_manager_recipient_routes route on route.id=generation.recipient_route_id
    join public.weekly_manager_review_batches batch
      on batch.recipient_generation_id=generation.id
     and batch.message_render_id=v_render.id and batch.state='ACTIVE'
    where generation.id=v_intent.recipient_generation_id and generation.state='ACTIVE'
      and route.current_generation_id=generation.id
  ) then
    v_reason:='REVIEW_REPLACED';
  elsif v_intent.audience_kind='MANAGER' and (
    exists(
      select 1
      from public.weekly_manager_review_batches batch
      join public.weekly_manager_review_items item on item.review_batch_id=batch.id
      join public.weekly_discrepancy_incidents incident on incident.id=item.incident_id
      join public.weekly_issue_comparison_revisions comparison
        on comparison.id=incident.current_comparison_revision_id
      where batch.message_render_id=v_render.id
        and (
          item.response_state<>'UNANSWERED' or incident.state<>'OPEN'
          or item.incident_episode<>incident.episode_number
          or item.sent_comparison_revision_id<>incident.current_comparison_revision_id
          or item.sent_comparison_fingerprint<>comparison.material_comparison_fingerprint
        )
    ) or not exists(
      select 1
      from public.weekly_manager_review_batches batch
      join public.weekly_manager_review_items item on item.review_batch_id=batch.id
      join public.weekly_discrepancy_incidents incident on incident.id=item.incident_id
      where batch.message_render_id=v_render.id
        and item.response_state='UNANSWERED' and incident.state='OPEN'
    )
  ) then
    v_reason:='REVIEW_CHANGED';
  end if;
  if v_reason is not null then
    update public.weekly_message_dispatch_targets
    set state='RETIRED',terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason=v_reason,next_attempt_at_utc=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    update public.weekly_manager_review_batches
    set state='REVOKED'
    where message_render_id=v_render.id and state='ACTIVE';
    update public.weekly_manager_route_receipts receipt
    set state='REVOKED',revoked_at_utc=pg_catalog.transaction_timestamp()
    from public.weekly_manager_review_batches batch
    where receipt.review_batch_id=batch.id and batch.message_render_id=v_render.id
      and receipt.state='ACTIVE';
    update public.weekly_manager_review_items item
    set response_state='OBSOLETE'
    from public.weekly_manager_review_batches batch
    where item.review_batch_id=batch.id and batch.message_render_id=v_render.id
      and item.response_state='UNANSWERED';
    perform private.weekly_source_delivery_aggregate_command_v1(v_command.id);
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason',v_reason,
      'dispatch_target_id',v_target.id,'dispatch_command_id',v_command.id
    );
  end if;
  select coalesce(pg_catalog.max(attempt_number),0)+1 into v_attempt_number
  from public.weekly_message_target_attempts where dispatch_target_id=v_target.id;
  if v_attempt_number>v_target.maximum_attempts then
    raise exception 'WEEKLY_SOURCE_TARGET_RETRIES_EXHAUSTED' using errcode='55000';
  end if;
  insert into public.weekly_message_target_attempts(
    dispatch_target_id,attempt_number,provider_idempotency_key,
    lease_owner,lease_token,submission_started_at_utc
  ) values (
    v_target.id,v_attempt_number,
    v_target.provider_idempotency_key||'/attempt-'||v_attempt_number::text,
    v_worker,v_lease_token,pg_catalog.transaction_timestamp()
  ) returning * into v_attempt;
  update public.weekly_message_dispatch_targets
  set state='SUBMISSION_STARTED',attempt_count=v_attempt_number
  where id=v_target.id;
  update public.weekly_message_dispatch_commands set state='SUBMISSION_STARTED'
  where id=v_command.id;
  update public.weekly_message_renders set state='SUBMISSION_STARTED'
  where id=v_render.id;
  return pg_catalog.jsonb_build_object(
    'ok',true,'replay',false,'provider_attempt_id',v_attempt.id,
    'provider_idempotency_key',v_attempt.provider_idempotency_key,
    'submission_started_at_utc',v_attempt.submission_started_at_utc
  );
end;
$function$;

create or replace function public.weekly_source_message_dispatch_claim_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_worker text;
  v_limit integer;
  v_lease_seconds integer;
  v_token uuid:=pg_catalog.gen_random_uuid();
  v_commands jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('worker_id','limit','lease_seconds')) then
    raise exception 'WEEKLY_SOURCE_DISPATCH_CLAIM_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_worker:=pg_catalog.btrim(p_request->>'worker_id');
    v_limit:=coalesce(nullif(p_request->>'limit','')::integer,25);
    v_lease_seconds:=coalesce(nullif(p_request->>'lease_seconds','')::integer,60);
  exception when others then
    raise exception 'WEEKLY_SOURCE_DISPATCH_CLAIM_REQUEST_INVALID' using errcode='22023';
  end;
  if v_worker is null or v_worker!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
     or v_limit<1 or v_limit>100 or v_lease_seconds<15 or v_lease_seconds>300 then
    raise exception 'WEEKLY_SOURCE_DISPATCH_CLAIM_REQUEST_INVALID' using errcode='22023';
  end if;
  with eligible as (
    select command.id
    from public.weekly_message_dispatch_commands command
    where command.target_set_state='NOT_PREPARED'
      and (
        (command.state in ('READY','FAILED')
          and coalesce(command.next_attempt_at_utc,'-infinity'::timestamptz)
            <=pg_catalog.transaction_timestamp())
        or
        (command.state='LEASED'
          and command.lease_expires_at_utc<=pg_catalog.transaction_timestamp())
      )
    order by command.next_attempt_at_utc nulls first,command.id
    limit v_limit
    for update skip locked
  ), claimed as (
    update public.weekly_message_dispatch_commands command
    set state='LEASED',lease_owner=v_worker,lease_token=v_token,
        lease_expires_at_utc=pg_catalog.transaction_timestamp()
          +pg_catalog.make_interval(secs=>v_lease_seconds)
    from eligible where command.id=eligible.id
    returning command.*
  )
  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'dispatch_command_id',claimed.id,'lease_token',claimed.lease_token,
      'lease_expires_at_utc',claimed.lease_expires_at_utc,
      'environment',claimed.environment,'agency_id',claimed.agency_id,
      'audience_kind',intent.audience_kind,'tranche_kind',claimed.tranche_kind,
      'candidate_id',candidate_generation.candidate_id,
      'candidate_generation_id',claimed.candidate_generation_id,
      'manager_recipient_route_id',claimed.recipient_route_id,
      'manager_recipient',route.protected_recipient_address,
      'manager_recipient_fingerprint',case when route.id is null then null
        else pg_catalog.encode(route.normalised_recipient_hash,'hex') end,
      'message_intent_id',intent.id,'message_render_id',render.id,
      'subject_text',render.subject_text,'html_body',render.html_body,
      'plain_body',render.plain_body,
      'provider_idempotency_key',render.provider_idempotency_key,
      'rendered_content_hash',pg_catalog.encode(render.rendered_content_hash,'hex'),
      'review_batch_id',batch.id,'control_plane_ticket_id',batch.control_plane_ticket_id
    ) order by claimed.id
  ),'[]'::jsonb) into v_commands
  from claimed
  join public.weekly_message_intents intent on intent.id=claimed.message_intent_id
  join public.weekly_message_renders render on render.id=claimed.message_render_id
  left join public.weekly_candidate_outreach_generations candidate_generation
    on candidate_generation.id=claimed.candidate_generation_id
  left join public.weekly_manager_recipient_routes route on route.id=claimed.recipient_route_id
  left join public.weekly_manager_review_batches batch on batch.message_render_id=render.id;
  return pg_catalog.jsonb_build_object(
    'ok',true,'worker_id',v_worker,'lease_token',v_token,
    'claimed_count',pg_catalog.jsonb_array_length(v_commands),'commands',v_commands
  );
end;
$function$;

create or replace function public.weekly_source_message_targets_register_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_command_id uuid;
  v_lease_token uuid;
  v_worker text;
  v_control_snapshot uuid;
  v_suppression text;
  v_targets jsonb;
  v_normalised jsonb:='[]'::jsonb;
  v_item jsonb;
  v_safe jsonb;
  v_command public.weekly_message_dispatch_commands%rowtype;
  v_intent public.weekly_message_intents%rowtype;
  v_render public.weekly_message_renders%rowtype;
  v_route public.weekly_manager_recipient_routes%rowtype;
  v_external_id uuid;
  v_fingerprint bytea;
  v_snapshot_hash bytea;
  v_provider text;
  v_version integer;
  v_ordinal integer:=0;
  v_set_hash bytea;
  v_notification_id uuid;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in (
                 'dispatch_command_id','lease_token','worker_id',
                 'control_plane_snapshot_id','suppression_reason','targets'
               ))
     or pg_catalog.jsonb_typeof(coalesce(p_request->'targets','[]'::jsonb))<>'array' then
    raise exception 'WEEKLY_SOURCE_TARGET_SET_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_command_id:=(p_request->>'dispatch_command_id')::uuid;
    v_lease_token:=(p_request->>'lease_token')::uuid;
    v_worker:=p_request->>'worker_id';
    v_control_snapshot:=nullif(p_request->>'control_plane_snapshot_id','')::uuid;
    v_suppression:=nullif(pg_catalog.upper(pg_catalog.btrim(p_request->>'suppression_reason')),'');
    v_targets:=coalesce(p_request->'targets','[]'::jsonb);
  exception when others then
    raise exception 'WEEKLY_SOURCE_TARGET_SET_REQUEST_INVALID' using errcode='22023';
  end;
  if v_suppression is not null and v_suppression not in (
    'PERSONAL_PREFERENCE','NO_ACTIVE_DEVICE','PUSH_DELIVERY_UNAVAILABLE'
  ) then
    raise exception 'WEEKLY_SOURCE_TARGET_SUPPRESSION_INVALID' using errcode='22023';
  end if;
  select * into strict v_command from public.weekly_message_dispatch_commands
  where id=v_command_id for update;
  select * into strict v_intent from public.weekly_message_intents
  where id=v_command.message_intent_id for update;
  select * into strict v_render from public.weekly_message_renders
  where id=v_command.message_render_id for update;
  if v_command.state<>'LEASED' or v_command.lease_token<>v_lease_token
     or v_command.lease_owner<>v_worker
     or v_command.lease_expires_at_utc<=pg_catalog.transaction_timestamp()
     or v_intent.state<>'RENDERED' or v_render.state<>'CURRENT' then
    raise exception 'WEEKLY_SOURCE_DISPATCH_LEASE_STALE' using errcode='40001';
  end if;
  perform private.weekly_source_query_current_publication_v1(
    v_command.source_cycle_id,v_command.projection_publication_id
  );

  if v_suppression is not null then
    if v_intent.audience_kind<>'CANDIDATE'
       or pg_catalog.jsonb_array_length(v_targets)<>0
       or v_control_snapshot is null then
      raise exception 'WEEKLY_SOURCE_TARGET_SUPPRESSION_INVALID' using errcode='22023';
    end if;
    v_set_hash:=private.weekly_source_delivery_target_set_hash_v1(
      v_command.id,v_control_snapshot,v_suppression,'[]'::jsonb
    );
    update public.weekly_message_dispatch_commands
    set target_set_state='SUPPRESSED',target_set_hash=v_set_hash,
        control_plane_snapshot_id=v_control_snapshot,state='ACCEPTED',
        transport_finalised_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason=v_suppression,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_command.id;
    update public.weekly_message_renders set state='ACCEPTED' where id=v_render.id;
    update public.weekly_message_intents set state='DISPATCHED' where id=v_intent.id;
    select link.notification_id into strict v_notification_id
    from public.weekly_candidate_message_notifications link
    where link.message_intent_id=v_intent.id;
    update public.candidate_notifications
    set push_state='SKIPPED',last_error=v_suppression
    where id=v_notification_id;
    return pg_catalog.jsonb_build_object(
      'ok',true,'replay',false,'suppressed',true,
      'reason',v_suppression,'target_count',0,
      'target_set_hash',pg_catalog.encode(v_set_hash,'hex')
    );
  end if;
  if pg_catalog.jsonb_array_length(v_targets)<1
     or pg_catalog.jsonb_array_length(v_targets)>20 then
    raise exception 'WEEKLY_SOURCE_TARGET_SET_SIZE_INVALID' using errcode='22023';
  end if;

  if v_intent.audience_kind='MANAGER' then
    if v_control_snapshot is not null or pg_catalog.jsonb_array_length(v_targets)<>1 then
      raise exception 'WEEKLY_SOURCE_MANAGER_TARGET_SET_INVALID' using errcode='22023';
    end if;
    select * into strict v_route from public.weekly_manager_recipient_routes
    where id=v_command.recipient_route_id;
  elsif v_intent.audience_kind='CANDIDATE' then
    if v_control_snapshot is null then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_TARGET_SNAPSHOT_REQUIRED' using errcode='22023';
    end if;
  else
    raise exception 'WEEKLY_SOURCE_TARGET_AUDIENCE_INVALID' using errcode='22023';
  end if;

  for v_item in
    select value from pg_catalog.jsonb_array_elements(v_targets)
    order by value->>'provider',value->>'target_fingerprint',value->>'external_target_id'
  loop
    if pg_catalog.jsonb_typeof(v_item)<>'object'
       or exists(select 1 from pg_catalog.jsonb_object_keys(v_item) key
                 where key not in (
                   'external_target_id','target_fingerprint','target_snapshot_hash',
                   'target_version','provider','safe_target_snapshot'
                 )) then
      raise exception 'WEEKLY_SOURCE_TARGET_INVALID' using errcode='22023';
    end if;
    begin
      v_external_id:=(v_item->>'external_target_id')::uuid;
      v_fingerprint:=private.weekly_source_query_hex32_v1(
        v_item->>'target_fingerprint','WEEKLY_SOURCE_TARGET_FINGERPRINT_INVALID'
      );
      v_snapshot_hash:=private.weekly_source_query_hex32_v1(
        v_item->>'target_snapshot_hash','WEEKLY_SOURCE_TARGET_SNAPSHOT_HASH_INVALID'
      );
      v_version:=(v_item->>'target_version')::integer;
      v_provider:=pg_catalog.upper(v_item->>'provider');
      v_safe:=v_item->'safe_target_snapshot';
    exception when others then
      raise exception 'WEEKLY_SOURCE_TARGET_INVALID' using errcode='22023';
    end;
    if v_version<1 or pg_catalog.jsonb_typeof(v_safe)<>'object'
       or v_safe ?| array['token','token_ciphertext','email','address','authorization','secret','credential'] then
      raise exception 'WEEKLY_SOURCE_TARGET_INVALID' using errcode='22023';
    end if;
    if v_intent.audience_kind='CANDIDATE' then
      if v_provider not in ('APNS','FCM')
         or nullif(v_safe->>'control_plane_snapshot_id','')::uuid<>v_control_snapshot
         or nullif(v_safe->>'snapshot_device_id','')::uuid<>v_external_id
         or pg_catalog.upper(v_safe->>'provider')<>v_provider
         or private.weekly_source_query_hex32_v1(
              v_safe->>'target_revision_hash','WEEKLY_SOURCE_TARGET_REVISION_HASH_INVALID'
            )<>v_snapshot_hash then
        raise exception 'WEEKLY_SOURCE_CANDIDATE_TARGET_INVALID' using errcode='22023';
      end if;
    else
      if v_provider<>'POWER_AUTOMATE' or v_external_id<>v_route.id
         or v_fingerprint<>v_route.normalised_recipient_hash
         or v_safe<>pg_catalog.jsonb_build_object('recipient_route_id',v_route.id) then
        raise exception 'WEEKLY_SOURCE_MANAGER_TARGET_INVALID' using errcode='22023';
      end if;
    end if;
    v_ordinal:=v_ordinal+1;
    v_normalised:=v_normalised||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'external_target_id',v_external_id,
        'target_fingerprint',pg_catalog.encode(v_fingerprint,'hex'),
        'target_snapshot_hash',pg_catalog.encode(v_snapshot_hash,'hex'),
        'target_version',v_version,'provider',v_provider,
        'safe_target_snapshot',v_safe
      )
    );
    insert into public.weekly_message_dispatch_targets(
      dispatch_command_id,target_ordinal,channel,target_kind,provider,
      external_target_id,keyed_target_fingerprint,target_snapshot_hash,
      target_version,safe_target_snapshot_json,rendered_content_hash,
      provider_idempotency_key,state,next_attempt_at_utc
    ) values (
      v_command.id,v_ordinal,
      case when v_intent.audience_kind='CANDIDATE' then 'PUSH' else 'EMAIL' end,
      case when v_intent.audience_kind='CANDIDATE' then 'CANDIDATE_DEVICE' else 'MANAGER_ADDRESS' end,
      v_provider,v_external_id,v_fingerprint,v_snapshot_hash,v_version,v_safe,
      v_render.rendered_content_hash,
      v_render.provider_idempotency_key||'/'||pg_catalog.encode(v_fingerprint,'hex'),
      'READY',pg_catalog.transaction_timestamp()
    );
  end loop;
  v_set_hash:=private.weekly_source_delivery_target_set_hash_v1(
    v_command.id,v_control_snapshot,null,v_normalised
  );
  update public.weekly_message_dispatch_commands
  set target_set_state='PREPARED',target_set_hash=v_set_hash,
      control_plane_snapshot_id=v_control_snapshot,target_count=v_ordinal,
      state='READY',next_attempt_at_utc=null,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null
  where id=v_command.id;
  return pg_catalog.jsonb_build_object(
    'ok',true,'replay',false,'suppressed',false,'target_count',v_ordinal,
    'target_set_hash',pg_catalog.encode(v_set_hash,'hex')
  );
end;
$function$;

-- WP-44 F2.  A TRANSIENT failure of the Candidate push SNAPSHOT step.
--
-- The snapshot step asks the control plane which devices this Candidate has.
-- An absent binding, an unreachable control plane, a reset connection or an
-- answer this transport does not understand are all failures of the QUESTION,
-- never answers about the Candidate.  They must therefore not finalise the
-- command as `SUPPRESSED` (02 section 7.16 "opt-out or no device never changes
-- the request"; NTF-009 "provider fails temporarily -> visible bounded retry";
-- 03 section 11 "an exhausted message creates an Office-visible delivery
-- failure"), and nothing may persist a control-plane snapshot identity the
-- control plane did not give.
--
-- This owner therefore leaves `target_set_state` at `NOT_PREPARED` and
-- `control_plane_snapshot_id` untouched, returns the command to the claimable
-- `FAILED` state behind the same bounded backoff ladder the per-target retry
-- uses, and writes one Office-visible `TARGET_SNAPSHOT_FAILED` row per distinct
-- failure code so the gap is never silent.
create or replace function public.weekly_source_message_dispatch_snapshot_failure_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_command_id uuid;
  v_lease_token uuid;
  v_worker text;
  v_failure_code text;
  v_command public.weekly_message_dispatch_commands%rowtype;
  v_intent public.weekly_message_intents%rowtype;
  v_attempt integer;
  v_delay_seconds integer;
  v_next timestamptz;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in (
                 'dispatch_command_id','lease_token','worker_id','failure_code'
               )) then
    raise exception 'WEEKLY_SOURCE_SNAPSHOT_FAILURE_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_command_id:=(p_request->>'dispatch_command_id')::uuid;
    v_lease_token:=(p_request->>'lease_token')::uuid;
    v_worker:=p_request->>'worker_id';
    v_failure_code:=pg_catalog.upper(pg_catalog.btrim(p_request->>'failure_code'));
  exception when others then
    raise exception 'WEEKLY_SOURCE_SNAPSHOT_FAILURE_REQUEST_INVALID' using errcode='22023';
  end;
  if v_command_id is null or v_lease_token is null
     or v_worker is null or v_worker!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
     or v_failure_code is null or v_failure_code!~'^[A-Z][A-Z0-9_]{1,119}$' then
    raise exception 'WEEKLY_SOURCE_SNAPSHOT_FAILURE_REQUEST_INVALID' using errcode='22023';
  end if;

  -- Lock BEFORE reading any guarded state.
  select * into strict v_command from public.weekly_message_dispatch_commands
  where id=v_command_id for update;
  select * into strict v_intent from public.weekly_message_intents
  where id=v_command.message_intent_id for update;

  if v_command.state<>'LEASED' or v_command.lease_token<>v_lease_token
     or v_command.lease_owner<>v_worker
     or v_command.lease_expires_at_utc<=pg_catalog.transaction_timestamp() then
    raise exception 'WEEKLY_SOURCE_DISPATCH_LEASE_STALE' using errcode='40001';
  end if;
  if v_intent.audience_kind<>'CANDIDATE' then
    raise exception 'WEEKLY_SOURCE_SNAPSHOT_FAILURE_AUDIENCE_INVALID' using errcode='22023';
  end if;
  -- Fail closed.  A command whose target set has already been decided is not a
  -- snapshot failure and must never be reopened by this owner.
  if v_command.target_set_state<>'NOT_PREPARED'
     or v_command.transport_finalised_at_utc is not null then
    raise exception 'WEEKLY_SOURCE_TARGET_SET_ALREADY_DECIDED' using errcode='55000';
  end if;

  v_attempt:=v_command.attempt_count+1;
  v_delay_seconds:=case v_attempt
    when 1 then 30 when 2 then 120 when 3 then 600 else 1800 end;
  v_next:=pg_catalog.transaction_timestamp()
    +pg_catalog.make_interval(secs=>v_delay_seconds);

  update public.weekly_message_dispatch_commands
  set state='FAILED',attempt_count=v_attempt,next_attempt_at_utc=v_next,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null
  where id=v_command.id;

  -- One Office-visible row per distinct failure code for this command.  The
  -- table's uniqueness treats a null `dispatch_target_id` as distinct, so the
  -- existence check is explicit rather than left to `on conflict`.
  if not exists(
    select 1 from public.weekly_message_delivery_failures failure
    where failure.dispatch_command_id=v_command.id
      and failure.dispatch_target_id is null
      and failure.failure_class='TARGET_SNAPSHOT_FAILED'
      and failure.safe_failure_code=v_failure_code
  ) then
    insert into public.weekly_message_delivery_failures(
      dispatch_command_id,dispatch_target_id,failure_class,safe_failure_code,safe_context_json
    ) values (
      v_command.id,null,'TARGET_SNAPSHOT_FAILED',v_failure_code,
      pg_catalog.jsonb_build_object(
        'dispatch_command_id',v_command.id,'attempt_count',v_attempt)
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'deferred',true,'dispatch_command_id',v_command.id,
    'failure_code',v_failure_code,'attempt_count',v_attempt,
    'next_attempt_at_utc',v_next,'re_claimable',true,
    'target_set_state',v_command.target_set_state
  );
end;
$function$;

drop trigger if exists weekly_source_delivery_target_immutable
  on public.weekly_message_dispatch_targets;
create trigger weekly_source_delivery_target_immutable
before update on public.weekly_message_dispatch_targets
for each row execute function private.weekly_source_delivery_target_immutable_v1();

create or replace function private.weekly_source_candidate_notification_intent_v1()
returns trigger
language plpgsql
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_generation public.weekly_candidate_outreach_generations%rowtype;
  v_link public.candidate_app_global_membership_links%rowtype;
  v_account public.candidate_app_accounts%rowtype;
  v_notification public.candidate_notifications%rowtype;
  v_link_count integer;
  v_request_kind text;
  v_event_type text;
  v_template_key text;
  v_dedupe_key text;
  v_client_name text;
  v_timesheet_count integer;
  v_week_ending date;
begin
  if new.audience_kind<>'CANDIDATE' then return new; end if;
  if new.tranche_kind not in (
    'CANDIDATE_INITIAL','CANDIDATE_REMINDER_6H','CANDIDATE_MANUAL_REMINDER',
    'TIMESHEET_SUBMISSION_INITIAL','TIMESHEET_SUBMISSION_REMINDER_6H'
  ) then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_NOTIFICATION_TRANCHE_INVALID' using errcode='22023';
  end if;
  select * into strict v_generation
  from public.weekly_candidate_outreach_generations
  where id=new.candidate_generation_id;

  -- T0 is accepted only when exactly one active Candidate App account can own
  -- the durable in-app request.  Later reminders retain that same owner even
  -- if the central membership is subsequently disabled; this preserves the
  -- request record without re-routing it to another account.
  if new.tranche_kind in ('CANDIDATE_INITIAL','TIMESHEET_SUBMISSION_INITIAL') then
    select pg_catalog.count(*) into v_link_count
    from public.candidate_app_global_membership_links link
    join public.candidate_app_accounts account on account.id=link.account_id
    where link.candidate_id=v_generation.candidate_id
      and link.state='ACTIVE' and account.status='ACTIVE';
    if v_link_count<>1 then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_APP_UNAVAILABLE' using errcode='55000';
    end if;
    select link.* into strict v_link
    from public.candidate_app_global_membership_links link
    join public.candidate_app_accounts account on account.id=link.account_id
    where link.candidate_id=v_generation.candidate_id
      and link.state='ACTIVE' and account.status='ACTIVE';
  else
    select link.* into v_link
    from public.weekly_candidate_message_notifications prior
    join public.candidate_app_global_membership_links link
      on link.membership_id=prior.membership_id and link.account_id=prior.account_id
    where prior.candidate_generation_id=v_generation.id
    order by prior.created_at_utc,prior.message_intent_id
    limit 1;
    if not found then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_APP_UNAVAILABLE' using errcode='55000';
    end if;
  end if;
  select * into strict v_account from public.candidate_app_accounts where id=v_link.account_id;

  v_request_kind:=v_generation.request_kind;
  v_event_type:=case
    when new.tranche_kind in ('CANDIDATE_INITIAL','TIMESHEET_SUBMISSION_INITIAL')
      then 'WEEKLY_SOURCE_REQUEST'
    else 'WEEKLY_SOURCE_REMINDER' end;
  v_template_key:=case when v_request_kind='SUBMIT_TIMESHEET'
    then 'weekly-source-submit-timesheet-v1'
    else 'weekly-source-check-hours-v1' end;
  v_dedupe_key:='weekly-source-message-intent:'||new.id::text;

  if v_request_kind='SUBMIT_TIMESHEET' then
    select client.name into strict v_client_name
    from public.clients client
    where client.id=v_generation.client_id;

    select pg_catalog.count(*)::integer,pg_catalog.min(membership.week_ending)
      into v_timesheet_count,v_week_ending
    from public.weekly_timesheet_submission_requests submission
    join public.weekly_timesheet_submission_request_memberships membership
      on membership.submission_request_id=submission.id
    where submission.candidate_cohort_id=v_generation.candidate_cohort_id
      and submission.source_cycle_id=v_generation.source_cycle_id
      and submission.candidate_id=v_generation.candidate_id
      and submission.request_generation=v_generation.generation_number
      and submission.state not in ('SUPERSEDED','CANCELLED')
      and membership.state='WAITING';
    if coalesce(v_timesheet_count,0)<1 or v_week_ending is null then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_SUBMISSION_SCOPE_NOT_FOUND'
        using errcode='55000';
    end if;
  end if;

  insert into public.candidate_notifications(
    account_id,candidate_id,workflow_id,timesheet_id,event_type,
    preference_category,template_key,template_params,deep_link_json,
    state,push_state,dedupe_key,created_at_utc
  ) values (
    v_account.id,v_generation.candidate_id,null,null,v_event_type,
    'timesheet_expense_attention',v_template_key,
    pg_catalog.jsonb_build_object(
      'request_id',v_generation.id,
      'request_kind',v_request_kind,
      'tranche_kind',new.tranche_kind,
      'due_at_utc',new.due_at_utc,
      'deadline_at_utc',v_generation.deadline_at_utc
    )||case when v_request_kind='SUBMIT_TIMESHEET' then
      pg_catalog.jsonb_build_object(
        'timesheet_count',v_timesheet_count,
        'week_ending_label',pg_catalog.to_char(v_week_ending,'FMDD FMMonth YYYY'),
        'client_name',v_client_name
      ) else '{}'::jsonb end,
    pg_catalog.jsonb_build_object(
      'destination','WEEKLY_SOURCE_REQUEST','request_id',v_generation.id
    ),
    'UNREAD','PENDING',v_dedupe_key,pg_catalog.transaction_timestamp()
  )
  on conflict (dedupe_key) do update set dedupe_key=excluded.dedupe_key
  returning * into v_notification;

  insert into public.weekly_candidate_message_notifications(
    message_intent_id,candidate_generation_id,candidate_id,account_id,
    membership_id,notification_id,tranche_kind,dedupe_key
  ) values (
    new.id,v_generation.id,v_generation.candidate_id,v_account.id,
    v_link.membership_id,v_notification.id,new.tranche_kind,v_dedupe_key
  );
  return new;
end;
$function$;

