-- A8 late factual/legacy-financial callback boundary. Complete latest bodies
-- are retained, with only the initial owner gate added. This late successor
-- follows 0550 and every original definer/reassertion; never install it before
-- the NEXT module schema. Existing routine identities, ownership and ACLs are
-- preserved by CREATE OR REPLACE (no historical browser grants are replayed).
-- Source publish/withdraw owners still need their separately coordinated
-- non-LEGACY token/invalidation branch: these callback gates alone are not A8.
-- No factual trigger is disabled, no table/history scan or financial fallback.



create or replace function private.bpay_next_legacy_callback_enabled_v1()
returns boolean language plpgsql volatile security definer
set search_path=pg_catalog,private
as $function$
declare
  v_owner text;
  v_epoch bigint;
begin
  select m.active_owner,m.owner_epoch into v_owner,v_epoch
    from private.bpay_next_module_control m where m.id=1 for share;
  if not found or v_owner is null or v_owner not in ('LEGACY','NEXT','DISABLED')
     or v_epoch is null or v_epoch<=0 then
    raise exception using errcode='55000',message='BPAY_NEXT_OWNER_STATUS_UNAVAILABLE';
  end if;
  return v_owner='LEGACY';
end;
