        END IF;
        INSERT INTO pg_temp._bpay_wb_effect_identity_map_v1(
          relation_name,logical_source_id,actual_source_id)
        VALUES(v_trigger_table,v_internal_logical_source_id,v_internal_source_id);
      ELSE
        UPDATE pg_temp._bpay_wb_expected_effects expected SET proposed=true
        WHERE expected.build_token=v_internal_build_token
          AND expected.candidate_id=v_internal_candidate_id
          AND expected.timesheet_id IS NOT DISTINCT FROM v_internal_timesheet_id
          AND expected.relation_name=v_trigger_table AND expected.operation=TG_OP
          AND expected.source_id=v_internal_source_id
          AND expected.proposed IS NOT TRUE AND expected.observed IS NOT TRUE
          AND expected.expected_before_digest IS NOT DISTINCT FROM v_internal_before_digest
          AND expected.expected_after_digest IS NOT DISTINCT FROM v_internal_after_digest;
        GET DIAGNOSTICS v_expected_match_count=ROW_COUNT;
        IF v_expected_match_count<>1 THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
        END IF;
      END IF;
      IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;
  END IF;

  -- Natural-expiry fields are derived scheduler metadata.  An update confined
  -- to this allowlist must not create another generation or candidate build.
  IF TG_OP = 'UPDATE'
     AND v_trigger_table = 'pay_item_snoozes'
     AND (
       v_new_row - ARRAY[
         'natural_expiry_source_fingerprint',
         'natural_expiry_checked_fingerprint',
         'natural_expiry_checked_at_utc',
         'natural_expiry_state_changed',
         'natural_expiry_result_code'
       ]::text[]
     ) IS NOT DISTINCT FROM (
       v_old_row - ARRAY[
         'natural_expiry_source_fingerprint',
         'natural_expiry_checked_fingerprint',
         'natural_expiry_checked_at_utc',
         'natural_expiry_state_changed',
         'natural_expiry_result_code'
       ]::text[]
     ) THEN
    RETURN NEW;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re THEN
    v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid);
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re THEN
    v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid);
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', v_old_row->>'linked_timesheet_id', '')), '') ~* v_uuid_re THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', v_old_row->>'linked_timesheet_id', '')), '')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', v_new_row->>'linked_timesheet_id', '')), '') ~* v_uuid_re THEN
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', v_new_row->>'linked_timesheet_id', '')), '')::uuid;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '') ~* v_uuid_re THEN
    v_old_contract_id := NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '') ~* v_uuid_re THEN
    v_new_contract_id := NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '')::uuid;
  END IF;

  v_explicit_banking_pay_action := lower(BTRIM(COALESCE(current_setting('cloudtms.banking_pay_explicit_action', true), 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(current_setting('cloudtms.banking_pay_dirty_allowed', true), 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN (
      'timesheet_authorise',
      'timesheet_unauthorise',
      'timesheet_archive',
      'timesheet_unarchive',
      'authorise_timesheet',
      'unauthorise_timesheet',
      'archive_timesheet',
      'unarchive_timesheet',
      'banking_pay',
      'banking_pay_refresh',
      'banking_pay_dirty',
      'banking_pay_action',
      'banking_pay_recalculate',
      'banking_pay_decision',
      'banking_pay_case_resolution',
      'banking_pay_timesheet_advance',
      'banking_pay_patch'
    );

  IF TG_OP = 'INSERT'
     AND v_trigger_table = 'timesheets'
     AND v_explicit_banking_pay_action IS NOT TRUE
     AND lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('manual_timesheet_save', 'ordinary_timesheet_save', 'timesheet_manual_save', 'manual_save')
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', v_new_row->>'authorised_at_utc', '')), '') IS NULL
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', v_new_row->>'revoked_at_utc', '')), '') IS NULL THEN
    PERFORM public._temp_diag_log(
      'TEMP_TRIGGER_DIRTY_STAGE',
      'TEMP_BANKING_PAY_DIRTY',
      COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
      jsonb_build_object(
        'function_name', 'pay_workbench_mark_candidate_dirty',
        'stage', 'early_return_ordinary_timesheet_insert_save_no_dirty',
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'mutation_context', v_lifecycle_context,
        'authorised_at_server_present', false,
        'revoked_at_present', false,
        'explicit_banking_pay_action', false,
        'banking_pay_dirty_required', false,
        'source_build_required', false,
        'line_work_required', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    v_authorise_boundary_changed :=
      (
        NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL
      ) IS DISTINCT FROM (
        NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL
      );

    v_archive_boundary_changed :=
      (NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NOT NULL)
      IS DISTINCT FROM
      (NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL);

    v_material_live_source_changed :=
      (v_old_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
      OR (v_old_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
      OR (v_old_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
      OR (v_old_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
      OR (v_old_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
      OR (v_old_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
      OR (v_old_row->'additional_units_week') IS DISTINCT FROM (v_new_row->'additional_units_week')
      OR (v_old_row->'additional_units_per_day') IS DISTINCT FROM (v_new_row->'additional_units_per_day')
      OR (v_old_row->'week_ending_date') IS DISTINCT FROM (v_new_row->'week_ending_date')
      OR (v_old_row->'booking_id') IS DISTINCT FROM (v_new_row->'booking_id')
      OR (v_old_row->'line_type') IS DISTINCT FROM (v_new_row->'line_type')
      OR (v_old_row->'sheet_scope') IS DISTINCT FROM (v_new_row->'sheet_scope')
      OR (v_old_row->'reference_number') IS DISTINCT FROM (v_new_row->'reference_number')
      OR (v_old_row->'status') IS DISTINCT FROM (v_new_row->'status')
      OR (v_old_row->'submission_mode') IS DISTINCT FROM (v_new_row->'submission_mode')
      OR (v_old_row->'contract_id') IS DISTINCT FROM (v_new_row->'contract_id')
      OR (v_old_row->'is_adjustment') IS DISTINCT FROM (v_new_row->'is_adjustment')
      OR (v_old_row->'parent_timesheet_id') IS DISTINCT FROM (v_new_row->'parent_timesheet_id')
      OR (v_old_row->'correction_id') IS DISTINCT FROM (v_new_row->'correction_id')
      OR (v_old_row->'correction_kind') IS DISTINCT FROM (v_new_row->'correction_kind')
      OR (v_old_row->'adjustment_origin') IS DISTINCT FROM (v_new_row->'adjustment_origin');
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_authorise_boundary_changed :=
      (NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL)
      IS DISTINCT FROM
      (NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL);

    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_material_live_source_changed :=
      (v_old_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
      OR (v_old_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
      OR (v_old_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
      OR (v_old_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
      OR (v_old_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
      OR (v_old_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
      OR (v_old_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
      OR (v_old_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
      OR (v_old_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
      OR (v_old_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
      OR (v_old_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
      OR (v_old_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
      OR (v_old_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
      OR (v_old_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
      OR (v_old_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
      OR (v_old_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
      OR (v_old_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
      OR (v_old_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
      OR (v_old_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
      OR (v_old_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
      OR (v_old_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
      OR (v_old_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
      OR (v_old_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
      OR (v_old_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
      OR (v_old_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
      OR (v_old_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
      OR (v_old_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
      OR (v_old_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
      OR (v_old_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
      OR (v_old_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
      OR (v_old_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
      OR (v_old_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
      OR (v_old_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
      OR (v_old_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
      OR (v_old_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
      OR (v_old_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
      OR (v_old_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
      OR (v_old_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
      OR (v_old_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
      OR (v_old_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
      OR (v_old_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
      OR (v_old_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
      OR (v_old_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
      OR (v_old_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
    ELSE
      -- Snapshot rotation demotes the previous row before inserting its
      -- replacement.  The demotion itself is bookkeeping, not a live-source
      -- economic change and must not mark a frozen Draft stale.
      v_material_live_source_changed := false;
    END IF;
  ELSIF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      SELECT COALESCE(to_jsonb(previous_financial_row), '{}'::jsonb)
      INTO v_previous_tsfin_row
      FROM public.timesheets_financials AS previous_financial_row
      WHERE previous_financial_row.timesheet_id = v_new_timesheet_id
        AND previous_financial_row.id IS DISTINCT FROM
          CASE
            WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re
              THEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid
            ELSE NULL::uuid
          END
      ORDER BY
        previous_financial_row.timesheet_version DESC NULLS LAST,
        previous_financial_row.computed_at_utc DESC NULLS LAST,
        previous_financial_row.created_at DESC NULLS LAST,
        previous_financial_row.id DESC
      LIMIT 1;

      v_previous_tsfin_row := COALESCE(v_previous_tsfin_row, '{}'::jsonb);
      IF v_previous_tsfin_row = '{}'::jsonb THEN
        v_material_live_source_changed := true;
      ELSE
        v_material_live_source_changed :=
          (v_previous_tsfin_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
          OR (v_previous_tsfin_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
          OR (v_previous_tsfin_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
          OR (v_previous_tsfin_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
          OR (v_previous_tsfin_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
          OR (v_previous_tsfin_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
          OR (v_previous_tsfin_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
          OR (v_previous_tsfin_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
          OR (v_previous_tsfin_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
          OR (v_previous_tsfin_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
          OR (v_previous_tsfin_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
          OR (v_previous_tsfin_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
          OR (v_previous_tsfin_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
          OR (v_previous_tsfin_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
          OR (v_previous_tsfin_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
          OR (v_previous_tsfin_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
          OR (v_previous_tsfin_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
          OR (v_previous_tsfin_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
          OR (v_previous_tsfin_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
          OR (v_previous_tsfin_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
          OR (v_previous_tsfin_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
          OR (v_previous_tsfin_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
          OR (v_previous_tsfin_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
          OR (v_previous_tsfin_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
          OR (v_previous_tsfin_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
          OR (v_previous_tsfin_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
          OR (v_previous_tsfin_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
          OR (v_previous_tsfin_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
          OR (v_previous_tsfin_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
          OR (v_previous_tsfin_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
          OR (v_previous_tsfin_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
          OR (v_previous_tsfin_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
          OR (v_previous_tsfin_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
          OR (v_previous_tsfin_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
          OR (v_previous_tsfin_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
          OR (v_previous_tsfin_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
          OR (v_previous_tsfin_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
          OR (v_previous_tsfin_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
          OR (v_previous_tsfin_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
          OR (v_previous_tsfin_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
          OR (v_previous_tsfin_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
          OR (v_previous_tsfin_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    IF v_authorise_boundary_changed IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE
       AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    IF v_authorise_boundary_changed IS NOT TRUE AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_financials_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  END IF;

  IF TG_OP = 'INSERT'
     AND v_trigger_table = 'timesheets_financials'
     AND v_explicit_banking_pay_action IS NOT TRUE
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN
    PERFORM public._temp_diag_log(
      'TEMP_TRIGGER_DIRTY_STAGE',
      'TEMP_BANKING_PAY_DIRTY',
      COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
      jsonb_build_object(
        'function_name', 'pay_workbench_mark_candidate_dirty',
        'stage', 'early_return_ordinary_timesheet_financials_insert_edit_save_no_dirty',
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'mutation_context', v_lifecycle_context,
        'authorised_at_utc_present', false,
        'explicit_banking_pay_action', false,
        'banking_pay_dirty_required', false,
        'source_build_required', false,
        'line_work_required', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheet_pay_state' THEN
    v_timesheet_pay_state_settlement_changed :=
      (v_old_row->'last_settled_snapshot_json') IS DISTINCT FROM (v_new_row->'last_settled_snapshot_json')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_signature', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_signature', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_pay_batch_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_pay_batch_id', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_at_utc', '')), '');

    v_timesheet_pay_state_summary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_status_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_status_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_icon_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_icon_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_paid_at_utc', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_net_delta_ex_vat', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_net_delta_ex_vat', '')), '');

    IF v_timesheet_pay_state_settlement_changed IS NOT TRUE THEN
      v_timesheet_pay_state_bookkeeping_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false);
      v_timesheet_pay_state_noop_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false) IS NOT TRUE;

      PERFORM public._temp_diag_log(
        'TEMP_TRIGGER_DIRTY_STAGE',
        'TEMP_BANKING_PAY_DIRTY',
        COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
        jsonb_build_object(
          'function_name', 'pay_workbench_mark_candidate_dirty',
          'stage', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'early_return_timesheet_pay_state_bookkeeping_no_dirty'
            ELSE 'early_return_timesheet_pay_state_noop_no_dirty'
          END,
          'trigger_table', v_trigger_table,
          'trigger_op', TG_OP,
          'dirty_classification', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'TIMESHEET_PAY_STATE_BOOKKEEPING_IGNORED'
            ELSE 'TIMESHEET_PAY_STATE_NOOP_IGNORED'
          END,
          'timesheet_pay_state_settlement_changed', COALESCE(v_timesheet_pay_state_settlement_changed, false),
          'timesheet_pay_state_summary_changed', COALESCE(v_timesheet_pay_state_summary_changed, false),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
        )
      );
      RETURN NEW;
    END IF;

    v_timesheet_pay_state_routing_reason := 'SOURCE_BUILD_REQUIRED_PAY_STATE_SETTLED_BASELINE_CHANGE';
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL;
    IF v_old_payment_eligible IS NOT TRUE
       AND v_new_payment_eligible IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    IF v_old_payment_eligible IS NOT TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_tsfin_payability_state_changed :=
        NULLIF(BTRIM(COALESCE(v_old_row->>'paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'paid_by_user_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_by_user_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'payment_reference', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'payment_reference', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_reason', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_reason', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_since_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_since_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_by_invoice_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_by_invoice_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'unlocked_by_credit_note_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'unlocked_by_credit_note_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_last_sent_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_last_sent_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_send_count', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_send_count', '')), '');
      IF v_tsfin_payability_state_changed IS NOT TRUE THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'payability_state_changed', false, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        RETURN NEW;
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table IN ('timesheets', 'timesheets_financials')
     AND v_authorise_boundary_changed IS TRUE THEN
    IF v_new_payment_eligible IS TRUE AND v_old_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF v_old_payment_eligible IS TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_unauthorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN
      v_authorise_boundary_is_unauthorise := true;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table = 'timesheets'
     AND v_archive_boundary_changed IS TRUE THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL THEN
      v_archive_boundary_is_archive := true;
    ELSIF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NOT NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL THEN
      v_archive_boundary_is_unarchive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN
      v_archive_boundary_is_archive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN
      v_archive_boundary_is_unarchive := true;
    END IF;
  END IF;

  v_effective_lifecycle_context := CASE
    WHEN v_archive_boundary_is_archive IS TRUE THEN 'timesheet_archive'
    WHEN v_archive_boundary_is_unarchive IS TRUE THEN 'timesheet_unarchive'
    WHEN v_authorise_boundary_is_unauthorise IS TRUE THEN 'timesheet_unauthorise'
    WHEN v_authorise_boundary_is_authorise IS TRUE THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN 'timesheet_unauthorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN 'timesheet_archive'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN 'timesheet_unarchive'
    ELSE v_lifecycle_context
  END;

  v_banking_pay_dirty_required := v_authorise_boundary_changed IS TRUE
    OR v_archive_boundary_changed IS TRUE
    OR v_explicit_banking_pay_action IS TRUE
    OR (v_trigger_table = 'timesheet_pay_state' AND v_timesheet_pay_state_settlement_changed IS TRUE);
  v_ordinary_timesheet_edit_save_no_dirty := TG_OP = 'UPDATE'
    AND v_trigger_table IN ('timesheets', 'timesheets_financials')
    AND v_banking_pay_dirty_required IS NOT TRUE;

  IF v_old_timesheet_id IS NOT NULL OR v_new_timesheet_id IS NOT NULL THEN
    v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    SELECT COALESCE(array_agg(DISTINCT timesheet_ids.timesheet_id ORDER BY timesheet_ids.timesheet_id), ARRAY[]::uuid[])
    INTO v_targeted_timesheet_ids
    FROM (
      SELECT v_old_timesheet_id AS timesheet_id
      UNION ALL
      SELECT v_new_timesheet_id AS timesheet_id
    ) AS timesheet_ids
    WHERE timesheet_ids.timesheet_id IS NOT NULL;
  END IF;

  IF v_trigger_table = 'candidates' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid);
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid);
    END IF;

    IF TG_OP = 'UPDATE' THEN
      v_route_source_method := UPPER(BTRIM(COALESCE(v_old_row->>'pay_method', '')));
      v_route_target_method := UPPER(BTRIM(COALESCE(v_new_row->>'pay_method', '')));
      v_candidate_route_change := v_route_source_method IN ('PAYE', 'UMBRELLA')
        AND v_route_target_method IN ('PAYE', 'UMBRELLA')
        AND v_route_source_method <> v_route_target_method;

      IF v_candidate_route_change IS TRUE THEN
        IF v_route_operation_id IS NULL OR v_route_operation_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;
        IF v_route_actor_user_id IS NULL OR v_route_actor_user_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ACTOR_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;

        v_route_scope_result := public.candidate_pay_method_change_refresh_scope_v1(
          NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid,
          v_route_source_method,
          v_route_target_method
        );

        v_route_exact_scope := LOWER(BTRIM(COALESCE(v_route_scope_result->>'exact_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
        v_route_coverage_complete := LOWER(BTRIM(COALESCE(v_route_scope_result->>'coverage_complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

        IF COALESCE(v_route_scope_result->>'ok', 'false') <> 'true'
           OR v_route_exact_scope IS NOT TRUE
           OR v_route_coverage_complete IS NOT TRUE
           OR jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_EXACT_SCOPE_UNAVAILABLE'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        IF EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(v_route_scope_result->'targeted_timesheet_ids') AS raw_target(value)
          WHERE raw_target.value !~* v_uuid_re
        ) THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_SCOPE_INVALID'
            USING ERRCODE = 'P0001';
        END IF;

        SELECT COALESCE(array_agg(DISTINCT target_value::uuid ORDER BY target_value::uuid), ARRAY[]::uuid[])
        INTO v_targeted_timesheet_ids
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') = 'array'
              THEN v_route_scope_result->'targeted_timesheet_ids'
            ELSE '[]'::jsonb
          END
        ) AS target_values(target_value)
        WHERE target_value ~* v_uuid_re;

        v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
        v_route_targeted_scope_is_empty := COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0;
        v_route_authoritative_sessions := COALESCE(v_route_scope_result->'authoritative_sessions', '[]'::jsonb);
        v_route_replaced_source_session_ids := COALESCE(v_route_scope_result->'replaced_source_session_ids', '[]'::jsonb);
        v_route_target_details := COALESCE(v_route_scope_result->'target_details', '[]'::jsonb);
        v_route_authorised_timesheet_ids := COALESCE(v_route_scope_result->'authorised_timesheet_ids', '[]'::jsonb);
        v_route_active_advance_timesheet_ids := COALESCE(v_route_scope_result->'active_advance_timesheet_ids', '[]'::jsonb);
        v_route_retained_finance_timesheet_ids := COALESCE(v_route_scope_result->'retained_finance_timesheet_ids', '[]'::jsonb);
        v_route_authorised_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'authorised_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'authorised_timesheet_count')::integer END,
          0
        );
        v_route_active_advance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'active_advance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'active_advance_timesheet_count')::integer END,
          0
        );
        v_route_retained_finance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'retained_finance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'retained_finance_timesheet_count')::integer END,
          0
        );
        v_route_source_target_mismatch_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'source_target_mismatch_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'source_target_mismatch_count')::integer END,
          0
        );

        IF COALESCE(v_route_scope_result->>'durable_job_id', '') !~* v_uuid_re
           OR LOWER(BTRIM(COALESCE(v_route_scope_result->>'durable_scope_persisted', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_MISSING'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        v_route_job_id := (v_route_scope_result->>'durable_job_id')::uuid;
        v_route_job_status := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_status', '')), '');
        v_route_dedupe_key := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_dedupe_key', '')), '');
        v_route_job_source_change_seq := COALESCE(
          CASE
            WHEN COALESCE(v_route_scope_result->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_route_scope_result->>'source_change_seq')::bigint
            ELSE 0
          END,
          0
        );

        IF v_route_job_status NOT IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
           OR v_route_dedupe_key IS NULL
           OR v_route_job_source_change_seq <= 0 THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_INVALID'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        v_explicit_banking_pay_action := true;
        v_banking_pay_dirty_required := true;
        v_ordinary_timesheet_edit_save_no_dirty := false;
        v_effective_lifecycle_context := 'candidate_pay_method_change';
      END IF;
    END IF;
  END IF;

  IF v_trigger_table IN ('bank_name_checks', 'bank_payee_map') THEN
    v_entity_kind_old := UPPER(BTRIM(COALESCE(v_old_row->>'entity_kind', '')));
    v_entity_kind_new := UPPER(BTRIM(COALESCE(v_new_row->>'entity_kind', '')));
    IF v_entity_kind_old = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_old IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid;
    END IF;
    IF v_entity_kind_new = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_new IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_trigger_table = 'umbrellas' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_umbrella_id_old IS NOT NULL OR v_umbrella_id_new IS NOT NULL THEN
    FOR v_scope_id IN
      SELECT DISTINCT umbrella_scope.umbrella_id::text
      FROM (
        SELECT v_umbrella_id_old AS umbrella_id
        UNION ALL
        SELECT v_umbrella_id_new AS umbrella_id
      ) AS umbrella_scope
      WHERE umbrella_scope.umbrella_id IS NOT NULL
    LOOP
      v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;
      v_payload_json := jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'trigger_operation', TG_OP,
        'scope_kind', 'UMBRELLA',
        'scope_id', v_scope_id,
        'reason', v_reason,
        'fallback_reason', 'UMBRELLA_BANK_DETAIL_DIRTY',
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'source_build_required', true,
        'line_work_required', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
      PERFORM public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'CONTRACT_CLIENT_DIRTY_FANOUT',
        p_scope_kind => 'UMBRELLA',
        p_scope_id => v_scope_id,
        p_candidate_id => NULL::uuid,
        p_targeted_timesheet_ids => ARRAY[]::uuid[],
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      );
    END LOOP;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT candidate_candidates.candidate_id ORDER BY candidate_candidates.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS candidate_id
    UNION ALL
    SELECT contract_old.candidate_id FROM public.contracts AS contract_old WHERE contract_old.id = v_old_contract_id
    UNION ALL
    SELECT contract_new.candidate_id FROM public.contracts AS contract_new WHERE contract_new.id = v_new_contract_id
    UNION ALL
    SELECT financial_old.candidate_id FROM public.timesheets_financials AS financial_old WHERE financial_old.timesheet_id = v_old_timesheet_id AND financial_old.is_current = true
    UNION ALL
    SELECT financial_new.candidate_id FROM public.timesheets_financials AS financial_new WHERE financial_new.timesheet_id = v_new_timesheet_id AND financial_new.is_current = true
    UNION ALL
    SELECT timesheet_contract_old.candidate_id
    FROM public.timesheets AS timesheet_old
    JOIN public.contracts AS timesheet_contract_old ON timesheet_contract_old.id = timesheet_old.contract_id
    WHERE timesheet_old.timesheet_id = v_old_timesheet_id
    UNION ALL
    SELECT timesheet_contract_new.candidate_id
    FROM public.timesheets AS timesheet_new
    JOIN public.contracts AS timesheet_contract_new ON timesheet_contract_new.id = timesheet_new.contract_id
    WHERE timesheet_new.timesheet_id = v_new_timesheet_id
  ) AS candidate_candidates
  WHERE candidate_candidates.candidate_id IS NOT NULL;

  IF COALESCE(array_length(v_candidate_ids, 1), 0) = 0 THEN
    PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'return_no_candidate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  v_reason := CASE
    WHEN v_candidate_route_change IS TRUE
      THEN 'CANDIDATE_PAY_METHOD_CHANGE:' || v_route_source_method || '_TO_' || v_route_target_method
    ELSE 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP
  END;

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP

    IF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
      v_tsfin_insert_not_coalesced_reason := NULL::text;
      v_tsfin_insert_coalesced_job_id := NULL::uuid;
      v_tsfin_insert_coalesced_projection_run_id := NULL::uuid;
      v_tsfin_insert_coalesced_session_id := NULL::uuid;
      v_tsfin_insert_coalesced_source_change_seq := NULL::bigint;
      v_tsfin_insert_authorise_like := v_new_timesheet_id IS NOT NULL
        AND COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 1
        AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL
        AND COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') NOT IN ('false', 'f', '0', 'no', 'n', 'off');

      IF v_tsfin_insert_authorise_like IS TRUE THEN
        SELECT
          existing_delta.id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'projection_run_id', '') ~* v_uuid_re
              THEN (existing_delta.payload_json->>'projection_run_id')::uuid
            ELSE NULL::uuid
          END,
          existing_delta.session_id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_seq')::bigint
            WHEN COALESCE(existing_delta.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_sequence')::bigint
            ELSE NULL::bigint
          END
        INTO
          v_tsfin_insert_coalesced_job_id,
          v_tsfin_insert_coalesced_projection_run_id,
          v_tsfin_insert_coalesced_session_id,
          v_tsfin_insert_coalesced_source_change_seq
        FROM public.banking_pay_workbench_jobs AS existing_delta
        JOIN public.banking_pay_workbench_sessions AS existing_session
          ON existing_session.id = existing_delta.session_id
         AND UPPER(BTRIM(COALESCE(existing_session.status, ''))) = 'OPEN'
         AND existing_session.discarded_at_utc IS NULL
        WHERE existing_delta.candidate_id = v_candidate_id
          AND existing_delta.created_at_utc >= (v_now - INTERVAL '10 minutes')
          AND UPPER(BTRIM(COALESCE(existing_delta.status, ''))) IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
          AND UPPER(BTRIM(COALESCE(existing_delta.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'projection_class', ''))) = 'NORMAL_TIMESHEET'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_table', ''))) = 'TIMESHEETS'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_operation', existing_delta.payload_json->>'trigger_op', ''))) = 'UPDATE'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'mutation_context', existing_delta.payload_json->>'lifecycle_mutation_context', ''))) IN ('TIMESHEET_AUTHORISE', 'AUTHORISE_TIMESHEET')
          AND LOWER(BTRIM(COALESCE(existing_delta.payload_json->>'authorise_boundary_changed', existing_delta.payload_json#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(existing_delta.payload_json->'targeted_timesheet_ids') = 'array'
                  THEN existing_delta.payload_json->'targeted_timesheet_ids'
                ELSE '[]'::jsonb
              END
            ) AS targeted_timesheet_id(value)
            WHERE targeted_timesheet_id.value ~* v_uuid_re
              AND targeted_timesheet_id.value::uuid = v_new_timesheet_id
          )
        ORDER BY existing_delta.created_at_utc DESC, existing_delta.id DESC
        LIMIT 1;

        IF v_tsfin_insert_coalesced_job_id IS NOT NULL THEN
          PERFORM public._temp_diag_log(
            'TEMP_TRIGGER_DIRTY_STAGE',
            'TEMP_BANKING_PAY_DIRTY',
            v_new_timesheet_id::text,
            jsonb_build_object(
              'function_name', 'pay_workbench_mark_candidate_dirty',
              'stage', 'early_return_timesheet_financials_insert_authorise_coalesced_no_dirty',
              'trigger_table', v_trigger_table,
              'trigger_op', TG_OP,
              'coalesced_with_timesheets_authorise_delta', true,
              'coalesced_source_change_seq', v_tsfin_insert_coalesced_source_change_seq,
              'coalesced_job_id', v_tsfin_insert_coalesced_job_id::text,
              'coalesced_projection_run_id', CASE WHEN v_tsfin_insert_coalesced_projection_run_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_projection_run_id::text END,
              'coalesced_session_id', CASE WHEN v_tsfin_insert_coalesced_session_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_session_id::text END,
              'coalesced_candidate_id', v_candidate_id::text,
              'coalesced_timesheet_id', v_new_timesheet_id::text,
              'banking_pay_dirty_required', false,
              'source_build_required', false,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
              'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
            )
          );
          CONTINUE;
        END IF;

        v_tsfin_insert_not_coalesced_reason := 'NO_PRIOR_AUTHORISE_DELTA';
      ELSE
        v_tsfin_insert_not_coalesced_reason := CASE
          WHEN v_new_timesheet_id IS NULL THEN 'NO_TARGET_TIMESHEET'
          WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) <> 1 THEN 'MULTI_OR_EMPTY_TARGET_SCOPE'
          WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN 'UNAUTHORISED_INSERT'
          WHEN COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') IN ('false', 'f', '0', 'no', 'n', 'off') THEN 'NON_CURRENT_INSERT'
          ELSE 'UNKNOWN_SAFE_STATE'
        END;
      END IF;
    END IF;

    IF v_effective_lifecycle_context IN ('timesheet_authorise', 'timesheet_unauthorise', 'timesheet_archive', 'timesheet_unarchive') THEN
      v_lifecycle_dedupe_token := '|LIFECYCLE_DIRTY:' || v_effective_lifecycle_context || ':' || v_candidate_id::text || ':' || COALESCE(array_to_string(v_targeted_timesheet_ids, ','), '') || '|';
      v_lifecycle_dedupe_keys := COALESCE(current_setting('cloudtms.pay_dirty_dedupe_keys', true), '');
      IF POSITION(v_lifecycle_dedupe_token IN v_lifecycle_dedupe_keys) > 0 THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END, jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'dedupe_skip_lifecycle_duplicate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'mutation_context', v_lifecycle_context, 'candidate_id', v_candidate_id::text, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        CONTINUE;
      END IF;
      PERFORM set_config('cloudtms.pay_dirty_dedupe_keys', LEFT(v_lifecycle_dedupe_keys || v_lifecycle_dedupe_token, 60000), true);
    END IF;

    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'trigger_operation', TG_OP,
      'mutation_context', v_effective_lifecycle_context,
      'lifecycle_mutation_context', v_effective_lifecycle_context,
      'authorise_boundary_changed', COALESCE(v_authorise_boundary_is_authorise, false),
      'unauthorise_boundary_changed', COALESCE(v_authorise_boundary_is_unauthorise, false),
      'archive_boundary_changed', COALESCE(v_archive_boundary_is_archive, false),
      'unarchive_boundary_changed', COALESCE(v_archive_boundary_is_unarchive, false),
      'explicit_banking_pay_action', COALESCE(v_explicit_banking_pay_action, false) OR COALESCE(v_authorise_boundary_changed, false) OR COALESCE(v_archive_boundary_changed, false),
      'banking_pay_dirty_required', COALESCE(v_banking_pay_dirty_required, false),
      'ordinary_timesheet_edit_save_no_dirty', COALESCE(v_ordinary_timesheet_edit_save_no_dirty, false),
      'timesheets_financials_insert_not_coalesced_reason', CASE WHEN v_trigger_table = 'timesheets_financials' AND TG_OP = 'INSERT' THEN v_tsfin_insert_not_coalesced_reason ELSE NULL END,
      'timesheets_financials_insert_coalesced_authorise_delta', false,
      'scope_kind', 'CANDIDATE',
      'scope_id', v_candidate_id::text,
      'candidate_id', v_candidate_id::text,
      'reason', v_reason,
      'dirty_reason', v_reason,
      'timesheet_pay_state_settlement_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_settlement_changed, false) ELSE NULL END,
      'timesheet_pay_state_summary_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_summary_changed, false) ELSE NULL END,
      'timesheet_pay_state_bookkeeping_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_bookkeeping_ignored, false) ELSE NULL END,
      'timesheet_pay_state_noop_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_noop_ignored, false) ELSE NULL END,
      'pay_state_dirty_routing_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'source_build_required_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', '[]'::jsonb,
      'linked_scope_recompute_required', true,
      'source_build_required', true,
      'line_work_required', true,
      'line_work_only', false,
      'line_work_action', 'SOURCE_BUILD',
      'force_legacy', false,
      'force_broad_legacy', false,
      'projection_class', CASE
        WHEN v_candidate_route_change IS TRUE THEN 'PAYE_UMBRELLA_SWITCH'
        WHEN v_trigger_table IN ('timesheets', 'timesheets_financials')
             AND (v_authorise_boundary_changed IS TRUE OR v_archive_boundary_changed IS TRUE) THEN 'TIMESHEET_LIFECYCLE'
        ELSE 'DIRTY_TRIGGER'
      END,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );

    IF v_candidate_route_change IS TRUE THEN
      v_payload_json := v_payload_json
        || jsonb_strip_nulls(
          jsonb_build_object(
            'candidate_pay_method_change', true,
            'candidate_payment_status_changed', true,
            'pay_method_changed', true,
            'prospective_only', true,
            'old_pay_method', v_route_source_method,
            'new_pay_method', v_route_target_method,
            'route_change_operation_id', v_route_operation_id,
            'route_change_actor_user_id', v_route_actor_user_id,
            'actor_user_id', v_route_actor_user_id,
            'route_change_reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
            'route_change_source_method', v_route_source_method,
            'route_change_target_method', v_route_target_method,
            'authorised_timesheet_ids', v_route_authorised_timesheet_ids,
            'authorised_timesheet_count', v_route_authorised_timesheet_count,
            'active_advance_timesheet_ids', v_route_active_advance_timesheet_ids,
            'active_advance_timesheet_count', v_route_active_advance_timesheet_count,
            'retained_finance_timesheet_ids', v_route_retained_finance_timesheet_ids,
            'retained_finance_timesheet_count', v_route_retained_finance_timesheet_count,
            'source_target_mismatch_count', v_route_source_target_mismatch_count,
            'authoritative_sessions', v_route_authoritative_sessions,
            'replaced_source_session_ids', v_route_replaced_source_session_ids,
            'target_details', v_route_target_details,
            'coverage_basis', COALESCE(v_route_scope_result->>'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'),
            'coverage_complete', v_route_coverage_complete,
            'exact_target_scope', v_route_exact_scope,
            'targeted_scope_is_empty', v_route_targeted_scope_is_empty
          )
          || jsonb_build_object(
            'contracts_changed', 0,
            'contract_weeks_changed', 0,
            'timesheets_changed', 0,
            'rates_changed', 0,
            'tsfin_repricing_rows', 0,
            'source_records_mutated', false,
            'economic_truth_mutation_allowed', false,
            'refresh_completion_requires_terminal_exact_scope', true,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'policy_x_dirtying_only', true
          )
        );
    END IF;

    IF v_candidate_route_change IS TRUE THEN
      v_enqueue_result := jsonb_build_object(
        'ok', true,
        'job_id', v_route_job_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'status', v_route_job_status,
        'dedupe_key', v_route_dedupe_key,
        'scope_kind', 'CANDIDATE',
        'scope_id', v_candidate_id::text,
        'candidate_id', v_candidate_id::text,
        'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
        'latest_source_change_seq', v_route_job_source_change_seq,
        'exact_target_scope', true,
        'targeted_scope_is_empty', v_route_targeted_scope_is_empty,
        'durable_scope_persisted', true
      );
    ELSE
      SELECT public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        p_scope_kind => 'CANDIDATE',
        p_scope_id => v_candidate_id::text,
        p_candidate_id => v_candidate_id,
        p_targeted_timesheet_ids => v_targeted_timesheet_ids,
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      )
      INTO v_enqueue_result;
    END IF;

    v_jobs_queued := v_jobs_queued + 1;
  END LOOP;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_workbench_mark_candidate_dirty',
      'stage', CASE
        WHEN v_jobs_queued = 0 AND TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN 'return_no_dirty_after_timesheet_financials_insert_coalesced'
        ELSE 'return_enqueued_dirty_priority'
      END,
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'mutation_context', v_lifecycle_context,
      'candidate_count', COALESCE(array_length(v_candidate_ids, 1), 0),
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'jobs_queued', v_jobs_queued,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$;

-- Retained complete authority: supabase/repeatable/03102026_0500_h1h2_successor_authorities_after_retry.sql
CREATE OR REPLACE FUNCTION public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid DEFAULT NULL::uuid, p_targeted_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_linked_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_payload_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_priority integer DEFAULT '-1000'::integer, p_run_at_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_job_type text := UPPER(BTRIM(COALESCE(p_job_type, '')));
  v_scope_kind text := UPPER(BTRIM(COALESCE(p_scope_kind, '')));
  v_scope_id text := NULLIF(BTRIM(COALESCE(p_scope_id, '')), '');
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_key_part text := 'ALL';
  v_dedupe_key text;
  v_reason text := NULLIF(BTRIM(COALESCE(p_reason, '')), '');
  v_payload_json jsonb := '{}'::jsonb;
  v_incoming_payload jsonb := '{}'::jsonb;
  v_latest_source_change_seq bigint := 0;
  v_job_id uuid;
  v_job_status text;
  v_job_payload jsonb;
  v_priority integer := COALESCE(p_priority, -1000);
  v_run_at_utc timestamptz := COALESCE(p_run_at_utc, v_now);
  v_scope_uuid uuid := NULL::uuid;
  v_scope_invalidation_result jsonb := '{}'::jsonb;
  v_scope_change_tx_token uuid := NULL::uuid;
  -- A15 (PRE-EXISTING SB02 Workbench fix): bounded active-dedupe identity.
  v_full_dedupe_key text := NULL::text;
  v_dedupe_is_digest boolean := false;
BEGIN
  -- BEGIN A8 OWNER CALLBACK BOUNDARY
  IF NOT private.bpay_next_legacy_callback_enabled_v1() THEN
    RETURN jsonb_build_object(
      'ok',true,'skipped',true,'reason','FINANCIAL_OWNER_NOT_LEGACY',
      'job_id',NULL::text,'job_type',v_job_type,'status','SKIPPED',
      'dedupe_key',NULL::text,'queue_class','DIRTY_TRIGGER_PRIORITY',
      'priority',v_priority,'scope_kind',v_scope_kind,'scope_id',v_scope_id,
      'candidate_id',p_candidate_id::text,'targeted_timesheet_count',0,
      'latest_source_change_seq',NULL::bigint,'rerun_required',false);
  END IF;
  -- END A8 OWNER CALLBACK BOUNDARY
  IF v_job_type NOT IN (
    'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
    'CONTRACT_CLIENT_DIRTY_FANOUT'
  ) THEN
    RAISE EXCEPTION 'Unsupported Banking Pay dirty event job_type: %', p_job_type
      USING ERRCODE = '22023';
  END IF;

  IF v_scope_kind = '' OR v_scope_id IS NULL THEN
    RAISE EXCEPTION 'Banking Pay dirty event requires scope_kind and scope_id'
      USING ERRCODE = '22023';
  END IF;

  IF v_scope_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_scope_uuid := v_scope_id::uuid;
  END IF;

  IF v_job_type IN ('WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
     AND v_scope_uuid IS NULL THEN
    RAISE EXCEPTION 'Banking Pay dirty event scope_id must be a UUID for job_type %, scope_kind %, scope_id %', v_job_type, v_scope_kind, v_scope_id
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT target_id ORDER BY target_id), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_ids
  FROM unnest(COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[])) AS target_id
  WHERE target_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT linked_id ORDER BY linked_id), ARRAY[]::uuid[])
  INTO v_linked_timesheet_ids
  FROM unnest(COALESCE(p_linked_timesheet_ids, ARRAY[]::uuid[])) AS linked_id
  WHERE linked_id IS NOT NULL;

  -- The central invalidator owns durable candidate/timesheet economic state.
  -- Its guarded callback into this function preserves the installed queue
  -- envelope without recursion or a second queue authority.
  IF v_job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
     AND p_candidate_id IS NOT NULL
     AND COALESCE(current_setting('cloudtms.bpay_scope_invalidator_active',true),'')<>'true' THEN
    IF COALESCE(p_payload_json->>'scope_change_tx_token','')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_scope_change_tx_token:=(p_payload_json->>'scope_change_tx_token')::uuid;
    END IF;
    v_scope_invalidation_result:=private.pay_workbench_scope_invalidate_v1(
      CASE WHEN cardinality(v_targeted_timesheet_ids)=0 THEN ARRAY[p_candidate_id]
        ELSE array_fill(p_candidate_id,ARRAY[cardinality(v_targeted_timesheet_ids)]) END,
      CASE WHEN cardinality(v_targeted_timesheet_ids)=0 THEN ARRAY[NULL::uuid]
        ELSE v_targeted_timesheet_ids END,
      COALESCE(v_reason,'DIRTY_TRIGGER:'||v_scope_kind),
      v_scope_change_tx_token,
      COALESCE(p_payload_json,'{}'::jsonb)||jsonb_build_object('skip_candidate_job_enqueue',true)
    );
  END IF;

  IF COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN
    v_targeted_key_part := array_to_string(v_targeted_timesheet_ids, ',');
  END IF;

  IF p_candidate_id IS NOT NULL THEN
    PERFORM public._change_bump('pay_candidate:' || p_candidate_id::text);

    SELECT COALESCE(change_counter.seq, 0)
    INTO v_latest_source_change_seq
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;
  END IF;

  v_latest_source_change_seq := GREATEST(
    COALESCE(v_latest_source_change_seq, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'latest_source_change_seq', '') ~ '^\d+$' THEN (p_payload_json->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'source_change_seq', '') ~ '^\d+$' THEN (p_payload_json->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'source_change_sequence', '') ~ '^\d+$' THEN (p_payload_json->>'source_change_sequence')::bigint END, 0)
  );

  IF v_reason IS NULL THEN
    v_reason := 'DIRTY_TRIGGER:' || v_scope_kind;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN
    IF p_candidate_id IS NULL THEN
      RAISE EXCEPTION 'Candidate dirty apply job requires p_candidate_id'
        USING ERRCODE = '22023';
    END IF;
    v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_CANDIDATE_DIRTY_APPLY:CANDIDATE:'
      || p_candidate_id::text
      || ':TIMESHEETS:' || v_targeted_key_part;
    -- A15: the full key names every targeted Timesheet, so above about 69
    -- Timesheets it cannot be stored in the active-dedupe B-tree index
    -- (2,704-byte / 8,191-byte limits) and the whole business statement fails.
    -- Keys up to 2,048 bytes (<=52 Timesheets) keep their exact historical
    -- text.  A longer key is replaced by a fixed-size SHA-256 of the SAME
    -- canonical, sorted, de-duplicated Timesheet list, so equal scopes still
    -- share one key and different scopes still get different keys.  The full
    -- list stays in the unindexed payload_json.targeted_timesheet_ids that the
    -- consumer already reads; the key is never parsed.
    IF pg_catalog.octet_length(v_dedupe_key) > 2048 THEN
      v_full_dedupe_key := v_dedupe_key;
      v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_CANDIDATE_DIRTY_APPLY:CANDIDATE:'
        || p_candidate_id::text
        || ':TIMESHEETS:SHA256:'
        || pg_catalog.encode(
             pg_catalog.sha256(pg_catalog.convert_to(v_targeted_key_part, 'UTF8')),
             'hex'
           )
        || ':COUNT:' || cardinality(v_targeted_timesheet_ids)::text;
      v_dedupe_is_digest := true;
      -- Transition exactness: a job queued before A15 under the full key
      -- (53..69 Timesheets were storable) keeps absorbing the same scope.
      IF EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_jobs AS legacy_job
        WHERE legacy_job.dedupe_key = v_full_dedupe_key
          AND legacy_job.status IN ('QUEUED', 'RUNNING')
      ) THEN
        v_dedupe_key := v_full_dedupe_key;
        v_dedupe_is_digest := false;
      END IF;
    END IF;
  ELSIF v_job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' THEN
    v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_FINANCE_CASE_DIRTY_APPLY:' || v_scope_kind || ':' || v_scope_id;
  ELSE
    v_dedupe_key := 'DIRTY_TRIGGER:CONTRACT_CLIENT_DIRTY_FANOUT:' || v_scope_kind || ':' || v_scope_id;
  END IF;

  v_incoming_payload := jsonb_strip_nulls(
    COALESCE(p_payload_json, '{}'::jsonb)
    || jsonb_build_object(
      'job_type', v_job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority_class', 'DIRTY_TRIGGER_PRIORITY',
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'finance_case_id', CASE WHEN v_job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'contract_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'CONTRACT' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'client_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'CLIENT' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'umbrella_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'UMBRELLA' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb),
      'reason', v_reason,
      'reason_latest', v_reason,
      'reason_count', 1,
      'trigger_source', COALESCE(p_payload_json->>'trigger_source', p_payload_json->>'trigger_table', v_scope_kind),
      'latest_source_change_seq', v_latest_source_change_seq,
      'source_change_seq', v_latest_source_change_seq,
      'source_change_sequence', v_latest_source_change_seq,
      'latest_event_at_utc', v_now::text,
      'event_at_utc', v_now::text,
      'rerun_required', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'policy_x_dirtying_only', true,
      'economic_truth_mutation_allowed', false
    )
  );

  v_payload_json := public._pay_workbench_dirty_payload_merge('{}'::jsonb, v_incoming_payload);

  INSERT INTO public.banking_pay_workbench_jobs AS queued_job (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    v_job_type,
    'QUEUED',
    v_priority,
    v_run_at_utc,
    0,
    8,
    v_dedupe_key,
    NULL,
    NULL,
    CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN p_candidate_id ELSE NULL::uuid END,
    v_payload_json,
    v_now,
    v_now,
    NULL,
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET priority = LEAST(queued_job.priority, EXCLUDED.priority),
      run_at_utc = LEAST(queued_job.run_at_utc, EXCLUDED.run_at_utc),
      updated_at_utc = v_now,
      failed_at_utc = CASE WHEN queued_job.status = 'QUEUED' THEN NULL ELSE queued_job.failed_at_utc END,
      last_error_json = CASE WHEN queued_job.status = 'QUEUED' THEN NULL::jsonb ELSE queued_job.last_error_json END,
      payload_json = public._pay_workbench_dirty_payload_merge(
        COALESCE(queued_job.payload_json, '{}'::jsonb),
        COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
        || CASE
             WHEN queued_job.status = 'RUNNING' THEN jsonb_build_object('rerun_required', true)
             ELSE '{}'::jsonb
           END
      )
  -- A15: a digest key may only coalesce into a job that already covers every
  -- Timesheet of the incoming canonical scope (the durable targeted list only
  -- grows by union).  Anything else would be a digest collision: refuse it.
  WHERE v_dedupe_is_digest IS NOT TRUE
     OR NOT EXISTS (
       SELECT incoming_id.value::text
       FROM pg_catalog.unnest(v_targeted_timesheet_ids) AS incoming_id(value)
       EXCEPT
       SELECT covered_id.value
       FROM pg_catalog.jsonb_array_elements_text(
         CASE WHEN pg_catalog.jsonb_typeof(queued_job.payload_json->'targeted_timesheet_ids') = 'array'
           THEN queued_job.payload_json->'targeted_timesheet_ids'
           ELSE '[]'::jsonb END
       ) AS covered_id(value)
     )
  RETURNING queued_job.id, queued_job.status, queued_job.payload_json
  INTO v_job_id, v_job_status, v_job_payload;

  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_DEDUPE_DIGEST_SCOPE_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_DEDUPE_DIGEST_SCOPE_MISMATCH',
              'dedupe_key', v_dedupe_key,
              'candidate_id', p_candidate_id,
              'targeted_timesheet_count', cardinality(v_targeted_timesheet_ids)
            )::text;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    v_scope_id,
    jsonb_build_object(
      'function_name', 'pay_workbench_dirty_event_enqueue',
      'stage', CASE WHEN v_job_status = 'RUNNING' THEN 'dirty_enqueue_coalesced_existing_running' ELSE 'dirty_enqueue_inserted_or_coalesced_queued' END,
      'job_id', v_job_id::text,
      'job_type', v_job_type,
      'dedupe_key', v_dedupe_key,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority', v_priority,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'latest_source_change_seq', v_latest_source_change_seq,
      'rerun_required', COALESCE((v_job_payload->>'rerun_required')::boolean, false)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', v_job_type,
    'status', v_job_status,
    'dedupe_key', v_dedupe_key,
    'queue_class', 'DIRTY_TRIGGER_PRIORITY',
    'priority', v_priority,
    'scope_kind', v_scope_kind,
    'scope_id', v_scope_id,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
    'latest_source_change_seq', v_latest_source_change_seq,
    'rerun_required', COALESCE((v_job_payload->>'rerun_required')::boolean, false)
  );
END;
$function$;

-- Retained complete authority: supabase/repeatable/26092026_0203_banking_pay_stage2_workbench_draft_v1.sql
CREATE OR REPLACE FUNCTION private.weekly_source_entitlement_head_ledger_mark_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_anchor_bundle uuid;
  v_anchor_revision bigint;
  v_scope uuid[];
  v_token_text text;
  v_token uuid;
  v_result jsonb;
BEGIN
  -- BEGIN A8 OWNER CALLBACK BOUNDARY
  IF NOT private.bpay_next_legacy_callback_enabled_v1() THEN
    RETURN NULL;
  END IF;
  -- END A8 OWNER CALLBACK BOUNDARY
  -- Only a change of currentness is a ledger event: INSERT directly as COMMITTED_CURRENT, or an UPDATE whose
  -- state moves into or out of COMMITTED_CURRENT. STAGED inserts/updates and non-state updates return at once.
  IF TG_OP='INSERT' THEN
    IF NEW.state IS DISTINCT FROM 'COMMITTED_CURRENT' THEN RETURN NULL; END IF;
  ELSIF OLD.state IS NOT DISTINCT FROM NEW.state
     OR (OLD.state IS DISTINCT FROM 'COMMITTED_CURRENT' AND NEW.state IS DISTINCT FROM 'COMMITTED_CURRENT') THEN
    RETURN NULL;
  END IF;

  -- The publication this change belongs to.
  IF NEW.state='COMMITTED_CURRENT' THEN
    v_anchor_bundle:=NEW.decision_bundle_id; v_anchor_revision:=NEW.bundle_revision;
  ELSIF NEW.superseded_by_head_id IS NOT NULL THEN
    SELECT successor.decision_bundle_id,successor.bundle_revision
      INTO v_anchor_bundle,v_anchor_revision
      FROM public.weekly_source_entitlement_heads AS successor
     WHERE successor.id=NEW.superseded_by_head_id;
  END IF;

  SELECT COALESCE(pg_catalog.array_agg(DISTINCT root_id ORDER BY root_id),ARRAY[]::uuid[])
    INTO v_scope
    FROM (
      SELECT NEW.root_timesheet_id AS root_id
      UNION
      SELECT sibling.root_timesheet_id
        FROM public.weekly_source_entitlement_heads AS sibling
       WHERE v_anchor_bundle IS NOT NULL
         AND sibling.decision_bundle_id=v_anchor_bundle
         AND sibling.bundle_revision=v_anchor_revision
         AND sibling.candidate_id=NEW.candidate_id
         AND sibling.state IN ('STAGED','COMMITTED_CURRENT')
    ) AS scope_root;

  -- Exactly once per transaction scope: already marked under this transaction's token -> no write at all.
  v_token_text:=NULLIF(pg_catalog.btrim(COALESCE(
    pg_catalog.current_setting('cloudtms.banking_pay_scope_tx_token',true),'')),'');
  IF v_token_text IS NOT NULL
     AND v_token_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_token:=v_token_text::uuid;
    IF EXISTS (
         SELECT 1
           FROM public.banking_pay_workbench_jobs AS job_row
          WHERE job_row.candidate_id=NEW.candidate_id
            AND job_row.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
            AND job_row.status IN ('QUEUED','RUNNING')
            AND job_row.scope_change_tx_token=v_token
            AND NOT EXISTS (
              SELECT scope_id::text FROM pg_catalog.unnest(v_scope) AS wanted(scope_id)
              EXCEPT
              SELECT covered.value
                FROM pg_catalog.jsonb_array_elements_text(
                       CASE WHEN pg_catalog.jsonb_typeof(job_row.payload_json->'targeted_timesheet_ids')='array'
                            THEN job_row.payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END) AS covered(value)))
       AND NOT EXISTS (
         SELECT 1
           FROM pg_catalog.unnest(v_scope) AS wanted(scope_id)
           LEFT JOIN private.banking_pay_workbench_timesheet_scope_state AS scope_state
             ON scope_state.timesheet_id=wanted.scope_id
          WHERE scope_state.timesheet_id IS NULL
             OR scope_state.candidate_id IS DISTINCT FROM NEW.candidate_id
             OR scope_state.economic_state IS DISTINCT FROM 'DIRTY'
             OR scope_state.last_scope_change_tx_token IS DISTINCT FROM v_token) THEN
      RETURN NULL;
    END IF;
  END IF;

  v_result:=private.pay_workbench_scope_invalidate_v1(
    p_candidate_ids=>pg_catalog.array_fill(NEW.candidate_id,ARRAY[pg_catalog.cardinality(v_scope)]),
    p_timesheet_ids=>v_scope,
    p_reason=>'WEEKLY_SOURCE_ENTITLEMENT_HEAD_CURRENTNESS_CHANGED',
    p_scope_change_tx_token=>NULL::uuid,   -- the invalidator takes the transaction's one token
    p_payload_json=>pg_catalog.jsonb_build_object(
      'weekly_source_entitlement_head_change',pg_catalog.jsonb_build_object(
        'head_id',NEW.id,'head_revision',NEW.head_revision,
        'state_before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.state END,
        'state_after',NEW.state,
        'decision_bundle_id',NEW.decision_bundle_id,'bundle_revision',NEW.bundle_revision,
        'superseded_by_head_id',NEW.superseded_by_head_id,
        'superseded_by_withdrawal_id',NEW.superseded_by_withdrawal_id)));

  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
     OR (v_result->>'candidate_count')::integer IS DISTINCT FROM 1
     OR COALESCE((v_result->>'job_inserted_count')::integer,0)
        +COALESCE((v_result->>'job_coalesced_count')::integer,0)<1 THEN
    RAISE EXCEPTION 'WEEKLY_SOURCE_HEAD_LEDGER_MARK_FAILED'
      USING ERRCODE='55000',
            DETAIL=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_HEAD_LEDGER_MARK_FAILED','head_id',NEW.id,'invalidation',v_result)::text;
  END IF;
  RETURN NULL;
END;
$function$;

-- Retained complete authority: supabase/repeatable/31072026_2350_banking_pay_continuous_scope_runtime.sql
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_counter_stage_trg_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_inherited_generation bigint;
BEGIN
  -- BEGIN A8 OWNER CALLBACK BOUNDARY
  IF NOT private.bpay_next_legacy_callback_enabled_v1() THEN
    RETURN NEW;
  END IF;
  -- END A8 OWNER CALLBACK BOUNDARY
  IF NEW.entity_key !~* '^pay_candidate:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.seq IS NOT DISTINCT FROM OLD.seq THEN
    RETURN NEW;
  END IF;

  IF LOWER(BTRIM(COALESCE(current_setting('cloudtms.scope_generation_finalising', true), 'false')))
       IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_inherited_generation := NULLIF(BTRIM(COALESCE(
      current_setting('cloudtms.banking_pay_inherited_scope_generation', true),
      ''
    )), '')::bigint;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_INHERITED_SCOPE_GENERATION_INVALID'
      USING ERRCODE = 'P0001';
  END;

  IF v_inherited_generation IS NOT NULL THEN
    IF TG_OP = 'UPDATE'
       AND v_inherited_generation <= COALESCE(OLD.scope_change_generation, 0) THEN
      -- A retried/equal or older broad-fanout child is already represented.
      -- Preserve the ordinary candidate source sequence as well as generation.
      NEW.seq := OLD.seq;
      NEW.updated_at := OLD.updated_at;
      NEW.scope_change_generation := OLD.scope_change_generation;
      NEW.scope_change_tx_token := NULL::uuid;
      RETURN NEW;
    END IF;

    NEW.scope_change_generation := GREATEST(
      COALESCE(NEW.scope_change_generation, 0),
      v_inherited_generation
    );
    NEW.scope_change_tx_token := NULL::uuid;
  ELSE
    NEW.scope_change_tx_token := public.pay_workbench_scope_change_tx_token_v1();
  END IF;

  RETURN NEW;
END;
$function$;

-- Retained complete authority: supabase/repeatable/08092026_0804_pay_workbench_scope_invalidate_pair_arrays_v1.sql
CREATE OR REPLACE FUNCTION private.pay_workbench_scope_invalidate_v1(
  p_candidate_ids uuid[],
  p_timesheet_ids uuid[],
  p_reason text,
  p_scope_change_tx_token uuid DEFAULT NULL::uuid,
  p_payload_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
PARALLEL UNSAFE
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
  v_reason text := NULLIF(btrim(COALESCE(p_reason,'')), '');
  v_payload jsonb := COALESCE(p_payload_json,'{}'::jsonb);
  v_tx_token uuid;
  v_pair_count integer := 0;
  v_candidate_count integer := 0;
  v_timesheet_count integer := 0;
  v_registry_existing integer := 0;
  v_state_existing integer := 0;
  v_registry_affected integer := 0;
  v_state_affected integer := 0;
  v_job_inserted integer := 0;
  v_job_coalesced integer := 0;
  v_job_result jsonb;
  v_candidate record;
  v_source_change_seq bigint := 0;
  v_invalidation_at_utc timestamptz;
  v_pair_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_pair_timesheet_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  -- BEGIN A8 OWNER CALLBACK BOUNDARY
  IF NOT private.bpay_next_legacy_callback_enabled_v1() THEN
    RETURN jsonb_build_object(
      'ok',true,'skipped',true,'skip_reason','FINANCIAL_OWNER_NOT_LEGACY',
      'candidate_count',0,'timesheet_count',0,
      'registry_inserted_count',0,'registry_updated_count',0,
      'state_inserted_count',0,'state_updated_count',0,
      'job_inserted_count',0,'job_coalesced_count',0,
      'scope_change_tx_token',NULL::uuid,'reason',v_reason);
  END IF;
  -- END A8 OWNER CALLBACK BOUNDARY
  IF jsonb_typeof(v_payload) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID'
      USING ERRCODE='22023', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID',
        'field','p_payload_json'
      )::text;
  END IF;

  IF v_reason IS NULL
     OR cardinality(COALESCE(p_candidate_ids,ARRAY[]::uuid[]))
        <> cardinality(COALESCE(p_timesheet_ids,ARRAY[]::uuid[])) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID'
      USING ERRCODE='22023', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID',
        'candidate_count',cardinality(COALESCE(p_candidate_ids,ARRAY[]::uuid[])),
        'timesheet_count',cardinality(COALESCE(p_timesheet_ids,ARRAY[]::uuid[]))
      )::text;
  END IF;

  SELECT COALESCE(
           array_agg(
             canonical_pair.candidate_id
             ORDER BY canonical_pair.candidate_id,
                      canonical_pair.timesheet_id NULLS FIRST
           ),
           ARRAY[]::uuid[]
         ),
         COALESCE(
           array_agg(
             canonical_pair.timesheet_id
             ORDER BY canonical_pair.candidate_id,
                      canonical_pair.timesheet_id NULLS FIRST
           ),
           ARRAY[]::uuid[]
         )
  INTO v_pair_candidate_ids,v_pair_timesheet_ids
  FROM (
    SELECT DISTINCT input_pair.candidate_id,input_pair.timesheet_id
    FROM ROWS FROM (
      pg_catalog.unnest(COALESCE(p_candidate_ids,ARRAY[]::uuid[])),
      pg_catalog.unnest(COALESCE(p_timesheet_ids,ARRAY[]::uuid[]))
    ) AS input_pair(candidate_id,timesheet_id)
    WHERE input_pair.candidate_id IS NOT NULL
  ) AS canonical_pair;

  v_pair_count := cardinality(v_pair_candidate_ids);
  IF v_pair_count = 0 THEN
    RETURN jsonb_build_object(
      'ok',true,'candidate_count',0,'timesheet_count',0,
      'registry_inserted_count',0,'registry_updated_count',0,
      'state_inserted_count',0,'state_updated_count',0,
      'job_inserted_count',0,'job_coalesced_count',0,
      'scope_change_tx_token',NULL,'reason',v_reason
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM ROWS FROM (
      pg_catalog.unnest(v_pair_candidate_ids),
      pg_catalog.unnest(v_pair_timesheet_ids)
    ) AS invalidation_pair(candidate_id,timesheet_id)
    LEFT JOIN public.candidates AS candidate_row
      ON candidate_row.id=invalidation_pair.candidate_id
    WHERE candidate_row.id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH'
      USING ERRCODE='23503', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH',
        'kind','CANDIDATE_NOT_FOUND'
      )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM ROWS FROM (
      pg_catalog.unnest(v_pair_candidate_ids),
      pg_catalog.unnest(v_pair_timesheet_ids)
    ) AS invalidation_pair(candidate_id,timesheet_id)
    LEFT JOIN public.timesheets AS timesheet_row
      ON timesheet_row.timesheet_id=invalidation_pair.timesheet_id
    WHERE invalidation_pair.timesheet_id IS NOT NULL
      AND (
        timesheet_row.timesheet_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public.timesheets_financials AS ownership_financial
          WHERE ownership_financial.timesheet_id=invalidation_pair.timesheet_id
            AND ownership_financial.is_current
            AND ownership_financial.candidate_id IS DISTINCT FROM invalidation_pair.candidate_id
        )
      )
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH'
      USING ERRCODE='23503', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH',
        'kind','TIMESHEET_CANDIDATE_MISMATCH'
      )::text;
  END IF;

  v_tx_token := COALESCE(p_scope_change_tx_token,public.pay_workbench_scope_change_tx_token_v1());
  IF NOT EXISTS (
    SELECT 1 FROM public.banking_pay_scope_change_transactions AS scope_tx
    WHERE scope_tx.tx_token=v_tx_token AND scope_tx.state='PENDING'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_INVALID'
      USING ERRCODE='22023', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_INVALID',
        'scope_change_tx_token',v_tx_token
      )::text;
  END IF;

  SELECT count(DISTINCT candidate_id)::integer,
         count(DISTINCT timesheet_id) FILTER (WHERE timesheet_id IS NOT NULL)::integer
  INTO v_candidate_count,v_timesheet_count
  FROM ROWS FROM (
    pg_catalog.unnest(v_pair_candidate_ids),
    pg_catalog.unnest(v_pair_timesheet_ids)
  ) AS invalidation_pair(candidate_id,timesheet_id);

  SELECT count(*)::integer INTO v_registry_existing
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry
  WHERE registry.candidate_id IN (
    SELECT DISTINCT candidate_id
    FROM ROWS FROM (
      pg_catalog.unnest(v_pair_candidate_ids),
      pg_catalog.unnest(v_pair_timesheet_ids)
    ) AS invalidation_pair(candidate_id,timesheet_id)
  );

  -- Use one timestamp for every lifecycle column in the proposed inserts.
  -- PostgreSQL validates CHECK constraints on the proposed INSERT row before
  -- resolving ON CONFLICT, so separate clock_timestamp() calls can otherwise
  -- make created_at_utc a few microseconds later than last_dirtied/updated.
  v_invalidation_at_utc := clock_timestamp();
  v_source_change_seq := GREATEST(
    COALESCE(CASE WHEN COALESCE(v_payload->>'latest_source_change_seq','') ~ '^\d+$'
      THEN (v_payload->>'latest_source_change_seq')::bigint END,0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_seq','') ~ '^\d+$'
      THEN (v_payload->>'source_change_seq')::bigint END,0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_sequence','') ~ '^\d+$'
      THEN (v_payload->>'source_change_sequence')::bigint END,0)
  );

  INSERT INTO private.banking_pay_workbench_candidate_scope_registry AS registry(
    candidate_id,last_dirty_reason,last_scope_change_tx_token,
    current_source_change_seq,last_dirtied_at_utc,created_at_utc,updated_at_utc
  )
  SELECT DISTINCT candidate_id,v_reason,v_tx_token,v_source_change_seq,
         v_invalidation_at_utc,v_invalidation_at_utc,v_invalidation_at_utc
  FROM ROWS FROM (
    pg_catalog.unnest(v_pair_candidate_ids),
    pg_catalog.unnest(v_pair_timesheet_ids)
  ) AS invalidation_pair(candidate_id,timesheet_id)
  ORDER BY candidate_id
  ON CONFLICT(candidate_id) DO UPDATE
  SET last_dirty_reason=EXCLUDED.last_dirty_reason,
      last_scope_change_tx_token=EXCLUDED.last_scope_change_tx_token,
      current_source_change_seq=GREATEST(
        registry.current_source_change_seq,
        EXCLUDED.current_source_change_seq
      ),
      last_dirtied_at_utc=EXCLUDED.last_dirtied_at_utc,
      updated_at_utc=EXCLUDED.updated_at_utc;
  GET DIAGNOSTICS v_registry_affected = ROW_COUNT;

  SELECT count(*)::integer INTO v_state_existing
  FROM private.banking_pay_workbench_timesheet_scope_state AS scope_state
  WHERE scope_state.timesheet_id IN (
    SELECT timesheet_id
    FROM ROWS FROM (
      pg_catalog.unnest(v_pair_candidate_ids),
      pg_catalog.unnest(v_pair_timesheet_ids)
    ) AS invalidation_pair(candidate_id,timesheet_id)
    WHERE timesheet_id IS NOT NULL
  );

  INSERT INTO private.banking_pay_workbench_timesheet_scope_state AS scope_state(
    timesheet_id,candidate_id,economic_state,dirty_generation,
    last_dirty_reason,last_scope_change_tx_token,registered_at_utc,
    last_dirtied_at_utc,updated_at_utc
  )
  SELECT timesheet_id,candidate_id,'DIRTY',0,v_reason,v_tx_token,
         v_invalidation_at_utc,v_invalidation_at_utc,v_invalidation_at_utc
  FROM ROWS FROM (
    pg_catalog.unnest(v_pair_candidate_ids),
    pg_catalog.unnest(v_pair_timesheet_ids)
  ) AS invalidation_pair(candidate_id,timesheet_id)
  WHERE timesheet_id IS NOT NULL
  ORDER BY candidate_id,timesheet_id
  ON CONFLICT(timesheet_id) DO UPDATE
  SET candidate_id=EXCLUDED.candidate_id,
      economic_state='DIRTY',
      last_dirty_reason=EXCLUDED.last_dirty_reason,
      last_scope_change_tx_token=EXCLUDED.last_scope_change_tx_token,
      last_dirtied_at_utc=EXCLUDED.last_dirtied_at_utc,
      closed_at_utc=NULL,
      updated_at_utc=EXCLUDED.updated_at_utc;
  GET DIAGNOSTICS v_state_affected = ROW_COUNT;

  IF COALESCE((v_payload->>'skip_candidate_job_enqueue')::boolean,false) IS NOT TRUE THEN
    PERFORM set_config('cloudtms.bpay_scope_invalidator_active','true',true);
    FOR v_candidate IN
      SELECT candidate_id,
             COALESCE(array_agg(timesheet_id ORDER BY timesheet_id)
               FILTER (WHERE timesheet_id IS NOT NULL),ARRAY[]::uuid[]) AS timesheet_ids
      FROM ROWS FROM (
        pg_catalog.unnest(v_pair_candidate_ids),
        pg_catalog.unnest(v_pair_timesheet_ids)
      ) AS invalidation_pair(candidate_id,timesheet_id)
      GROUP BY candidate_id
      ORDER BY candidate_id
    LOOP
      v_job_result := public.pay_workbench_dirty_event_enqueue(
        p_job_type=>'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        p_scope_kind=>'CANDIDATE',
        p_scope_id=>v_candidate.candidate_id::text,
        p_candidate_id=>v_candidate.candidate_id,
        p_targeted_timesheet_ids=>v_candidate.timesheet_ids,
        p_linked_timesheet_ids=>ARRAY[]::uuid[],
        p_payload_json=>v_payload || jsonb_build_object(
          'scope_change_tx_token',v_tx_token,
          'bounded_scope_state_precedes_job',true
        ),
        p_reason=>v_reason,
        p_priority=>COALESCE((v_payload->>'priority')::integer,-1000),
        p_run_at_utc=>clock_timestamp()
      );
      IF COALESCE(v_job_result->>'status','')='QUEUED' THEN
        v_job_inserted := v_job_inserted+1;
      ELSE
        v_job_coalesced := v_job_coalesced+1;
      END IF;
      IF COALESCE(v_job_result->>'latest_source_change_seq','') ~ '^\d+$' THEN
        v_source_change_seq := (v_job_result->>'latest_source_change_seq')::bigint;
        UPDATE private.banking_pay_workbench_candidate_scope_registry
        SET current_source_change_seq=GREATEST(current_source_change_seq,v_source_change_seq),
            updated_at_utc=clock_timestamp()
        WHERE candidate_id=v_candidate.candidate_id;
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'ok',true,
    'candidate_count',v_candidate_count,
    'timesheet_count',v_timesheet_count,
    'registry_inserted_count',GREATEST(v_registry_affected-v_registry_existing,0),
    'registry_updated_count',LEAST(v_registry_existing,v_registry_affected),
    'state_inserted_count',GREATEST(v_state_affected-v_state_existing,0),
    'state_updated_count',LEAST(v_state_existing,v_state_affected),
    'job_inserted_count',v_job_inserted,
    'job_coalesced_count',v_job_coalesced,
    'scope_change_tx_token',v_tx_token,
    'reason',v_reason
  );
END;
$function$;

-- Retain A35's effective per-routine planner setting after its older ALTER
-- authority. No body/configuration of the unrelated item reader is changed.
do $a8_config$
begin
  if not exists(select 1 from pg_catalog.pg_proc p
    where p.oid='public.pay_timesheet_summary_pay_state_refresh_trigger()'::regprocedure
      and 'plan_cache_mode=force_custom_plan'=any(p.proconfig)
      and 'search_path=public, pg_temp'=any(p.proconfig)) then
    raise exception using errcode='55000',message='BPAY_NEXT_LEGACY_CALLBACK_A35_CONFIG_LOST';
  end if;
end;
$a8_config$;

notify pgrst, 'reload schema';



-- CONTACT_PREPARER_UNIT 32 repeatable supabase/repeatable/05102026_0308_weekly_source_pay_query_gate_v1.sql SHA256 128c6e5671e9623f2577e8c3c4e6c6a062c0a5acbaff993842a36e320ead04ef
-- Repeatable CloudTMS function/view authority: weekly_source_pay_query_gate_v1
-- Use CREATE OR REPLACE and preserve owner, security, search_path, and ACL contracts.





-- Canonical transaction-neutral qualified-coverage definitions.
-- Included inside each owning repeatable's atomic transaction, before SQL
-- readers are parsed. One body authority; no financial/release transitions.

-- Factual admission only. No reader locks, monetary hold, zero entitlement,
-- financial write, invoice change or present-day recheck of a retained Draft.
create or replace function private.weekly_source_pay_query_facts_v1(p_root_timesheet_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_scope jsonb; v_manual jsonb; v_hours jsonb:='[]'::jsonb;
  v_blocked boolean:=false; v_unavailable boolean:=false;
  v_row record; v_latest public.weekly_exceptional_pay_family_events%rowtype;
  v_generation uuid; v_count integer; v_approval_run uuid;
  v_invalid_wait_audit boolean;
  v_local_count integer; v_c1_count integer; v_next_count integer; v_audit_count integer;
  v_local jsonb; v_c1 jsonb; v_next jsonb; v_receipt jsonb; v_exception jsonb;
  v_state jsonb; v_digest bytea;
begin
  if p_root_timesheet_id is null then
    raise exception 'WEEKLY_SOURCE_PAY_QUERY_ROOT_REQUIRED' using errcode='22023'; end if;
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_timesheet_id);
  if v_scope is null then
    return jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_PAY_QUERY_SCOPE_UNAVAILABLE',
      'scope',null,'blocked',null,'query_state_sha256',null); end if;

  -- Work membership is the actual configured root week, across every owning
  -- report cutoff. Never substitute a Sunday or the report's cutoff period.
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'source_group_id',r.source_group_id,
    'source_cycle_id',r.source_cycle_id,'work_event_id',r.work_event_id,
    'candidate_id',r.candidate_id,'client_id',r.client_id,'contract_id',r.contract_id,
    'work_date',to_char(r.work_date,'YYYY-MM-DD'),'state',r.state) order by r.id),'[]'::jsonb),
    coalesce(bool_or(e.id is null or e.candidate_id is distinct from r.candidate_id
      or e.client_id is distinct from r.client_id or e.work_date is distinct from r.work_date
      or c.source_group_id is distinct from r.source_group_id),false)
  into v_manual,v_unavailable
  from private.weekly_source_manual_reviews r
  left join public.weekly_work_events e on e.id=r.work_event_id
  left join public.weekly_source_cycles c on c.id=r.source_cycle_id
  where r.state='OPEN' and r.candidate_id=(v_scope->>'candidate_id')::uuid
    and r.client_id=(v_scope->>'client_id')::uuid and r.contract_id=(v_scope->>'contract_id')::uuid
    and r.work_date between (v_scope->>'week_ending_date')::date-6 and (v_scope->>'week_ending_date')::date;
  v_blocked:=jsonb_array_length(v_manual)>0;

  for v_row in
    select i.*,e.work_date,e.candidate_id as event_candidate_id,e.client_id as event_client_id,
      x.id as comparison_id,x.incident_id as comparison_incident_id,x.contract_id as comparison_contract_id,
      owning.id as owning_comparison_id,owning.contract_id as owning_contract_id,
      tail.id as tail_comparison_id,
      x.issue_family,encode(x.material_comparison_fingerprint,'hex') as material_fingerprint,
      c.source_group_id as cycle_group_id
    from public.weekly_discrepancy_incidents i
    left join public.weekly_work_events e on e.id=i.work_event_id
    -- These immutable incident-owned revisions establish relevance independently
    -- of the suspect current pointer. The unique incident/revision index bounds
    -- both the first-owner point read and the actual backward-tail probe.
    left join public.weekly_issue_comparison_revisions owning
      on owning.incident_id=i.id and owning.revision_number=1
    left join lateral (select r.id from public.weekly_issue_comparison_revisions r
      where r.incident_id=i.id order by r.revision_number desc limit 1) tail on true
    left join public.weekly_issue_comparison_revisions x on x.id=i.current_comparison_revision_id
    left join public.weekly_source_cycles c on c.id=i.source_cycle_id
    where i.state='OPEN' and i.candidate_id=(v_scope->>'candidate_id')::uuid
      and i.client_id=(v_scope->>'client_id')::uuid
      and (e.work_date is null or e.work_date between
        (v_scope->>'week_ending_date')::date-6 and (v_scope->>'week_ending_date')::date)
      and (owning.contract_id is null or owning.contract_id=(v_scope->>'contract_id')::uuid)
    order by i.id
  loop
    if v_row.work_date is null or v_row.event_candidate_id is distinct from v_row.candidate_id
       or v_row.event_client_id is distinct from v_row.client_id
       or v_row.cycle_group_id is distinct from v_row.source_group_id
       or v_row.owning_comparison_id is null
       or v_row.owning_contract_id is distinct from (v_scope->>'contract_id')::uuid
       or v_row.comparison_id is null or v_row.comparison_incident_id is distinct from v_row.id
       or v_row.comparison_id is distinct from v_row.tail_comparison_id
       or v_row.comparison_contract_id is distinct from (v_scope->>'contract_id')::uuid
       or v_row.issue_family is null or v_row.material_fingerprint is null then
      v_unavailable:=true;
    end if;
    v_exception:=null;
    v_latest:=null;
    if v_scope->>'target_family_id' is not null then
      select e.* into v_latest from public.weekly_exceptional_pay_family_events e
        where e.family_id=(v_scope->>'target_family_id')::uuid
          and e.durable_work_event_id=v_row.work_event_id
        order by e.event_sequence desc limit 1;
    end if;
    if v_latest.id is not null and v_latest.state='WAIT' then
      -- Choose the actual approval's UNIQUE financial target-generation link.
      -- The Wait owner also appends generation-less, money-neutral audit rows
      -- for that same approval. They are not second payment publications, but
      -- must be genuine unchanged-vector WAIT evidence, never arbitrary nulls.
      -- A sibling publication may supersede the original financial generation;
      -- today's current_generation is not the immutable approval's pin.
      select count(*) filter (where t.financial_generation_id is not null),
        (array_agg(t.financial_generation_id) filter (where t.financial_generation_id is not null))[1],
        coalesce(bool_or(t.financial_generation_id is null and (
          t.reason is distinct from 'WAIT'
          or t.resulting_lifecycle_state is distinct from 'WAITING_SOURCE'
          or t.actor_user_id is null
          or t.complete_prior_family_vector_fingerprint is distinct from t.complete_next_family_vector_fingerprint
          or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',
            t.fixed_target_component_snapshot) is distinct from t.complete_next_family_vector_fingerprint
          or jsonb_typeof(t.current_source_proposal_snapshot) is distinct from 'object'
          or t.event_hash is distinct from private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_PROTECTED_TARGET_EVENT_V1',jsonb_build_object(
              'family_id',t.family_id,'event_sequence',t.event_sequence,
              'approval_id',t.approval_id,'generation_id',null,
              'prior_vector_hash',encode(t.complete_prior_family_vector_fingerprint,'hex'),
              'next_vector_hash',encode(t.complete_next_family_vector_fingerprint,'hex'),
              'reason','WAIT','actor_user_id',t.actor_user_id))
        )),false)
        into v_count,v_generation,v_invalid_wait_audit
        from public.weekly_exceptional_pay_target_events t
        where t.family_id=v_latest.family_id and t.approval_id=v_latest.evidence_approval_id;
      if v_latest.evidence_approval_id is null or v_count<>1 or v_generation is null or v_invalid_wait_audit then
        v_unavailable:=true;
      else
        v_local:=private.weekly_source_pay_query_local_receipt_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation);
        v_c1:=private.weekly_source_pay_query_c1_receipt_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation);
        v_next:=private.weekly_source_pay_query_next_receipt_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation);
        v_count:=(v_local is not null)::integer+(v_c1 is not null)::integer+(v_next is not null)::integer;
        select a.creation_orchestration_run_id into v_approval_run
          from public.weekly_exceptional_payment_approvals a where a.id=v_latest.evidence_approval_id;
        -- Count partial evidence too. A local RETIRED request is its audit row,
        -- not a second transport lane; unrelated sibling/history stays excluded.
        select count(*) into v_local_count
          from private.weekly_source_local_protected_decision_receipts l
          join public.weekly_exceptional_c1_publication_requests r on r.id=l.publication_request_id
          where l.generation_id=v_generation or r.orchestration_run_id=v_approval_run;
        select count(*),count(*) filter (where
          (v_local is not null and r.id::text=v_local->>'publication_request_id' and r.state='RETIRED')
          or (v_c1 is not null and r.id::text=v_c1->>'publication_request_id' and r.state='PUBLISHED'))
          into v_c1_count,v_audit_count
          from public.weekly_exceptional_c1_publication_requests r
          where r.generation_id=v_generation or r.orchestration_run_id=v_approval_run;
        select count(*) into v_next_count from private.bpay_next_protected_source_receipt r
          where r.approval_id=v_latest.evidence_approval_id or r.generation_id=v_generation
            or r.orchestration_run_id=v_approval_run;
        if v_count<>1 or v_approval_run is null
           or (v_local is not null and (v_local_count<>1 or v_c1_count<>1 or v_audit_count<>1 or v_next_count<>0))
           or (v_c1 is not null and (v_local_count<>0 or v_c1_count<>1 or v_audit_count<>1 or v_next_count<>0))
           or (v_next is not null and (v_local_count<>0 or v_c1_count<>0 or v_next_count<>1)) then v_unavailable:=true;
        else
          v_receipt:=coalesce(v_local,v_c1,v_next);
          v_exception:=jsonb_build_object('family_id',v_latest.family_id,
            'bound_version',v_scope->>'family_bound_version','event_sequence',v_latest.event_sequence::text,
            'state','WAIT','evidence_approval_id',v_latest.evidence_approval_id,'accepted_receipt',v_receipt);
        end if;
      end if;
    end if;
    if v_row.issue_family is distinct from 'CANDIDATE_TIMESHEET_MISSING' and v_exception is null then
      v_blocked:=true;
    end if;
    v_hours:=v_hours||jsonb_build_array(jsonb_build_object('id',v_row.id,
      'source_group_id',v_row.source_group_id,'source_cycle_id',v_row.source_cycle_id,
      'work_event_id',v_row.work_event_id,'candidate_id',v_row.candidate_id,'client_id',v_row.client_id,
      'state',v_row.state,'work_date',to_char(v_row.work_date,'YYYY-MM-DD'),
      'current_comparison_revision_id',v_row.comparison_id,'comparison_contract_id',v_row.comparison_contract_id,
      'issue_family',v_row.issue_family,'material_comparison_fingerprint',v_row.material_fingerprint,
      'latest_qualified_exception',v_exception));
  end loop;
  if v_unavailable then
    return jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE',
      'scope',v_scope,'blocked',null,'query_state_sha256',null); end if;
  v_state:=jsonb_build_object('schema_version','PAY_QUERY_STATE_V3','scope',v_scope,
    'manual_reviews',v_manual,'hours_incidents',v_hours);
  v_digest:=extensions.digest(convert_to(v_state::text,'UTF8'),'sha256');
  return jsonb_build_object('ok',true,'code','OK','scope',v_scope,'blocked',v_blocked,
    'query_state_sha256',encode(v_digest,'hex'),'hours_incidents',v_hours,'manual_reviews',v_manual);
end;
$function$;
alter function private.weekly_source_pay_query_facts_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_pay_query_facts_v1(uuid) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_covered_hours_incident_v1(p_incident_id uuid)
returns boolean language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_root uuid; v_count integer; v_facts jsonb;
begin
  select count(*),(array_agg(family.root_timesheet_id))[1] into v_count,v_root
  from public.weekly_discrepancy_incidents incident
  join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work on work.id=incident.work_event_id
  join public.weekly_exceptional_pay_target_families family
    on family.candidate_id=incident.candidate_id and family.contract_id=comparison.contract_id
    and work.work_date between family.week_start_date and family.week_ending_date
  join public.contracts contract on contract.id=family.contract_id and contract.client_id=incident.client_id
  where incident.id=p_incident_id and incident.state='OPEN'
    and exists(select 1 from public.weekly_exceptional_pay_family_events event
      where event.family_id=family.id and event.durable_work_event_id=work.id);
  if v_count<>1 or v_root is null then return false; end if;
  v_facts:=private.weekly_source_pay_query_facts_v1(v_root);
  if v_facts->'ok' is distinct from 'true'::jsonb then return false; end if;
  return exists(select 1 from jsonb_array_elements(v_facts->'hours_incidents') item
    where item->>'id'=p_incident_id::text and jsonb_typeof(item->'latest_qualified_exception')='object');
end;
$function$;
alter function private.weekly_source_covered_hours_incident_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_covered_hours_incident_v1(uuid) from public,anon,authenticated,service_role;




-- Keep the existing admission contract byte-for-field compatible. The Office
-- reader consumes the same qualified facts, not a second interpretation of pay.
create or replace function private.weekly_source_pay_query_gate_v1(p_root_timesheet_id uuid)
returns jsonb language sql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
  select private.weekly_source_pay_query_facts_v1(p_root_timesheet_id)-'hours_incidents'-'manual_reviews';
$function$;
alter function private.weekly_source_pay_query_gate_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_pay_query_gate_v1(uuid)
  from public,anon,authenticated,service_role;



-- CONTACT_PREPARER_UNIT 33 repeatable supabase/repeatable/05102026_0428_weekly_source_manual_review_commands_v2.sql SHA256 347d8a46cd773b71c3ce9fb9e5b4d30ff608db205c391ea2a4ed48840bc0b84b
-- Repeatable CloudTMS function/view authority: weekly_source_manual_review_commands_v2
-- Use CREATE OR REPLACE and preserve owner, security, search_path, and ACL contracts.





-- Immutable report-contained work, including unchanged snapshot rows and
-- physical NHSP reversals. Generated reversals, expenses and absent rows are
-- not evidence that a new file contained that shift.
create or replace function private.weekly_source_manual_review_final_rows_v2(p_final_revision_id uuid)
returns table(upload_row_id uuid,row_resolution_id uuid,work_event_id uuid,
  candidate_id uuid,client_id uuid,contract_id uuid,work_date date)
language sql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
  select s.upload_row_id,s.row_resolution_id,s.work_event_id,s.candidate_id,
    s.client_id,s.contract_id,s.work_date
  from public.weekly_source_final_snapshot_lines s
  where s.final_revision_id=p_final_revision_id
  union all
  select m.nhsp_upload_row_id,r.id,m.work_event_id,m.candidate_id,
    m.actual_client_id,m.contract_id,u.work_date
  from public.weekly_source_billing_movements m
  join public.weekly_source_upload_rows u on u.id=m.nhsp_upload_row_id
  join public.weekly_source_row_resolutions r
    on r.id=(m.source_facts_json->>'row_resolution_id')::uuid
    and r.upload_row_id=u.id and r.mapping_state='RESOLVED'
    and r.work_event_id=m.work_event_id and r.candidate_id=m.candidate_id
    and r.client_id=m.actual_client_id and r.contract_id=m.contract_id
  where m.final_revision_id=p_final_revision_id
    and m.source_profile_kind='NHSP_TRUST_BACKING_REPORT'
    and m.source_line_kind in ('NHSP_PHYSICAL_POSITIVE','NHSP_PHYSICAL_FULL_NEGATIVE');
$function$;
alter function private.weekly_source_manual_review_final_rows_v2(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manual_review_final_rows_v2(uuid)
  from public,anon,authenticated,service_role;

-- Read only the row's exact declared report scope. A Final takes precedence
-- over provisional data; do not choose a latest timestamp or another report.
create or replace function private.weekly_source_manual_review_source_v2(p_source_row_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_row public.weekly_source_upload_rows%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_report_scope public.weekly_source_report_scopes%rowtype;
  v_final public.weekly_source_final_revisions%rowtype;
  v_projection public.weekly_source_projection_publications%rowtype;
  v_mapping public.weekly_source_row_resolutions%rowtype;
  v_contract public.contracts%rowtype;
  v_count integer; v_resolution_id uuid; v_week date; v_generation integer;
begin
  select r.* into v_row from public.weekly_source_upload_rows r where r.id=p_source_row_id;
  if not found or v_row.row_finalisation_state not in ('NOT_APPLICABLE','SOURCE_WORKED') then return null; end if;
  select u.* into strict v_upload from public.weekly_source_uploads u where u.id=v_row.upload_id;
  select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=v_upload.source_cycle_id;
  if v_upload.report_scope_id is not null then
    select s.* into v_report_scope from public.weekly_source_report_scopes s
      where s.id=v_upload.report_scope_id and s.source_cycle_id=v_cycle.id
        and s.source_group_id=v_cycle.source_group_id and s.cutoff_at_utc=v_cycle.cutoff_at_utc;
    if not found then return null; end if;
  end if;
  select count(*) into v_count from public.weekly_source_final_revisions f
    where f.source_cycle_id=v_cycle.id and f.report_scope_id is not distinct from v_upload.report_scope_id
      and f.state='CURRENT';
  if v_count>1 then raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_AUTHORITY_AMBIGUOUS' using errcode='55000'; end if;
  if v_count=1 then
    select f.* into strict v_final from public.weekly_source_final_revisions f
      where f.source_cycle_id=v_cycle.id and f.report_scope_id is not distinct from v_upload.report_scope_id
        and f.state='CURRENT';
    if v_final.upload_id is distinct from v_upload.id or v_final.finalised_at_utc is null
       or not isfinite(v_final.finalised_at_utc) then return null; end if;
    if (v_final.authority_scope_kind='CYCLE' and (v_final.report_scope_id is not null
          or v_cycle.current_final_revision_id is distinct from v_final.id))
      or (v_final.authority_scope_kind='NHSP_REPORT_SCOPE' and (v_report_scope.id is null
          or v_report_scope.current_final_revision_id is distinct from v_final.id))
      or v_final.authority_scope_kind not in ('CYCLE','NHSP_REPORT_SCOPE') then return null; end if;
    select count(*),(array_agg(s.row_resolution_id))[1] into v_count,v_resolution_id
      from private.weekly_source_manual_review_final_rows_v2(v_final.id) s
      where s.upload_row_id=v_row.id;
    if v_count<>1 then return null; end if;
    select r.* into strict v_mapping from public.weekly_source_row_resolutions r where r.id=v_resolution_id;
  else
    if (v_upload.report_scope_id is null and v_cycle.current_final_revision_id is not null)
      or (v_upload.report_scope_id is not null and v_report_scope.current_final_revision_id is not null) then
      return null; end if;
    select count(*) into v_count from public.weekly_source_projection_publications p
      where p.source_cycle_id=v_cycle.id and p.report_scope_id is not distinct from v_upload.report_scope_id
        and p.upload_id=v_upload.id and p.state='CURRENT';
    if v_count<>1 then return null; end if;
    select p.* into strict v_projection from public.weekly_source_projection_publications p
      where p.source_cycle_id=v_cycle.id and p.report_scope_id is not distinct from v_upload.report_scope_id
        and p.upload_id=v_upload.id and p.state='CURRENT';
    if v_upload.state is distinct from 'CURRENT'
      or (v_projection.authority_scope_kind='CYCLE' and (v_projection.report_scope_id is not null
        or v_cycle.current_complete_upload_id is distinct from v_upload.id
        or v_cycle.current_projection_publication_id is distinct from v_projection.id
        or v_cycle.version is distinct from v_projection.authority_scope_version
        or v_cycle.projection_state is distinct from 'CURRENT'))
      or (v_projection.authority_scope_kind='NHSP_REPORT_SCOPE' and (v_report_scope.id is null
        or v_report_scope.current_complete_upload_id is distinct from v_upload.id
        or v_report_scope.current_projection_publication_id is distinct from v_projection.id
        or v_report_scope.version is distinct from v_projection.authority_scope_version
        or v_report_scope.projection_state is distinct from 'CURRENT'))
      or v_projection.authority_scope_kind not in ('CYCLE','NHSP_REPORT_SCOPE') then return null; end if;
    if v_projection.authority_scope_version>2147483647
       or coalesce(v_projection.projection_generation,0)>2147483647 then
      raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003'; end if;
    v_generation:=coalesce(v_projection.projection_generation,v_projection.authority_scope_version::integer);
    if v_generation is null or v_projection.published_at_utc is null
       or not isfinite(v_projection.published_at_utc) then return null; end if;
    select r.* into v_mapping from public.weekly_source_row_resolutions r
      where r.upload_row_id=v_row.id and r.generation=v_generation;
    if not found then return null; end if;
  end if;
  if v_mapping.mapping_state is distinct from 'RESOLVED'
     or v_mapping.upload_row_id is distinct from v_row.id then return null; end if;
  select c.* into strict v_contract from public.contracts c where c.id=v_mapping.contract_id;
  if v_contract.candidate_id is distinct from v_mapping.candidate_id
     or v_contract.client_id is distinct from v_mapping.client_id
     or v_contract.week_ending_weekday_snapshot is null
     or v_contract.week_ending_weekday_snapshot not between 0 and 6 then return null; end if;
  v_week:=v_row.work_date+((v_contract.week_ending_weekday_snapshot-extract(dow from v_row.work_date)::integer+7)%7);
  if not exists(select 1 from public.weekly_work_events e where e.id=v_mapping.work_event_id
    and e.candidate_id=v_mapping.candidate_id and e.client_id=v_mapping.client_id and e.work_date=v_row.work_date)
    or (v_final.id is not null and not exists(select 1 from public.weekly_source_client_manifests m
      where m.final_revision_id=v_final.id and m.client_id=v_mapping.client_id
        and m.source_group_id=v_cycle.source_group_id and m.source_cycle_id=v_cycle.id)) then return null; end if;
  return jsonb_build_object('source_group_id',v_cycle.source_group_id,'source_cycle_id',v_cycle.id,
    'upload_row_id',v_row.id,'row_resolution_id',v_mapping.id,'source_row_hash',encode(v_row.normalised_row_hash,'hex'),
    'work_event_id',v_mapping.work_event_id,'candidate_id',v_mapping.candidate_id,
    'client_id',v_mapping.client_id,'contract_id',v_mapping.contract_id,
    'work_date',to_char(v_row.work_date,'YYYY-MM-DD'),'week_ending_date',to_char(v_week,'YYYY-MM-DD'),
    'final_revision_id',v_final.id,'projection_publication_id',v_projection.id);
end;
$function$;
alter function private.weekly_source_manual_review_source_v2(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manual_review_source_v2(uuid)
  from public,anon,authenticated,service_role;

create or replace function public.weekly_source_manual_review_open_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid; v_row_id uuid; v_command_id uuid; v_reason text; v_hash bytea;
  v_prior private.weekly_source_manual_review_commands%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_source jsonb; v_route jsonb; v_result jsonb; v_review uuid; v_existing boolean;
  v_family_id uuid; v_sequence bigint; v_count integer;
begin
  perform private.weekly_source_query_require_service_v1();
  if jsonb_typeof(p_request) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_request) k
    where k not in ('actor_user_id','source_row_id','reason','command_id')) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023'; end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid; v_row_id:=(p_request->>'source_row_id')::uuid;
    v_command_id:=(p_request->>'command_id')::uuid;
  exception when others then raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023'; end;
  v_reason:=btrim(coalesce(p_request->>'reason',''));
  if v_actor is null or v_row_id is null or v_command_id is null or char_length(v_reason) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023'; end if;
  v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_MANUAL_REVIEW_OPEN_V2',p_request);
  select c.* into v_prior from private.weekly_source_manual_review_commands c where c.command_id=v_command_id;
  if found then
    if v_prior.command_kind is distinct from 'OPEN' or v_prior.actor_user_id is distinct from v_actor
       or v_prior.request_sha256 is distinct from v_hash then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_COMMAND_COLLISION' using errcode='23505'; end if;
    select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=v_prior.source_cycle_id;
    perform private.weekly_source_office_authority_v1(v_actor,'RECHECK_SOURCE',v_cycle.source_group_id,
      v_prior.client_id,v_cycle.finalisation_week_ending);
    return v_prior.result_json||jsonb_build_object('idempotent_replay',true);
  end if;
  perform private.weekly_source_pay_query_admit_v2();
  perform pg_advisory_xact_lock(hashtextextended('WEEKLY_SOURCE_MANUAL_REVIEW_COMMAND:'||v_command_id::text,0));
  select c.* into v_prior from private.weekly_source_manual_review_commands c where c.command_id=v_command_id;
  if found then
    if v_prior.command_kind is distinct from 'OPEN' or v_prior.actor_user_id is distinct from v_actor
       or v_prior.request_sha256 is distinct from v_hash then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_COMMAND_COLLISION' using errcode='23505'; end if;
    select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=v_prior.source_cycle_id;
    perform private.weekly_source_office_authority_v1(v_actor,'RECHECK_SOURCE',v_cycle.source_group_id,
      v_prior.client_id,v_cycle.finalisation_week_ending);
    return v_prior.result_json||jsonb_build_object('idempotent_replay',true);
  end if;
  -- The global try-key serialises participating source writers. Re-read the
  -- actual source and current authority after admission; never use a stale UI tuple.
  v_source:=private.weekly_source_manual_review_source_v2(v_row_id);
  if v_source is null then raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_SOURCE_STALE' using errcode='40001'; end if;
  select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=(v_source->>'source_cycle_id')::uuid;
  perform private.weekly_source_office_authority_v1(v_actor,'RECHECK_SOURCE',v_cycle.source_group_id,
    (v_source->>'client_id')::uuid,v_cycle.finalisation_week_ending);
  v_route:=private.weekly_source_office_route_key_v1(v_cycle.id,(v_source->>'candidate_id')::uuid,
    (v_source->>'client_id')::uuid,(v_source->>'contract_id')::uuid,(v_source->>'work_date')::date);
  if v_route->>'authority_mode' is distinct from 'SOURCE_AUTHORITY' then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_AUTHORITY_INVALID' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('WEEKLY_SOURCE_QUERY_FAMILY:'||
    (v_source->>'contract_id')||':'||(v_source->>'week_ending_date'),0));
  select r.id into v_review from private.weekly_source_manual_reviews r
    where r.source_group_id=v_cycle.source_group_id and r.work_event_id=(v_source->>'work_event_id')::uuid
      and r.state='OPEN' for update;
  v_existing:=v_review is not null;
  if v_existing and not exists(select 1 from private.weekly_source_manual_reviews r where r.id=v_review
    and r.candidate_id=(v_source->>'candidate_id')::uuid and r.client_id=(v_source->>'client_id')::uuid
    and r.contract_id=(v_source->>'contract_id')::uuid and r.work_date=(v_source->>'work_date')::date) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_AUTHORITY_INVALID' using errcode='55000'; end if;
  if not v_existing then
    select count(*),(array_agg(f.id))[1] into v_count,v_family_id
      from public.weekly_exceptional_pay_target_families f
      where f.contract_id=(v_source->>'contract_id')::uuid and f.candidate_id=(v_source->>'candidate_id')::uuid
        and f.week_ending_date=(v_source->>'week_ending_date')::date;
    if v_count>1 then raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_AUTHORITY_AMBIGUOUS' using errcode='55000'; end if;
    select coalesce(max(e.event_sequence),0) into v_sequence from public.weekly_exceptional_pay_family_events e
      where e.family_id=v_family_id and e.durable_work_event_id=(v_source->>'work_event_id')::uuid;
    insert into private.weekly_source_manual_reviews(source_group_id,source_cycle_id,upload_row_id,
      row_resolution_id,source_row_hash,work_event_id,candidate_id,client_id,contract_id,work_date,
      state,office_reason,opened_by_user_id)
    values(v_cycle.source_group_id,v_cycle.id,v_row_id,(v_source->>'row_resolution_id')::uuid,
      decode(v_source->>'source_row_hash','hex'),(v_source->>'work_event_id')::uuid,
      (v_source->>'candidate_id')::uuid,(v_source->>'client_id')::uuid,(v_source->>'contract_id')::uuid,
      (v_source->>'work_date')::date,'OPEN',v_reason,v_actor) returning id into v_review;
    perform public._audit_insert('weekly_source_manual_review',v_review::text,'WEEKLY_SOURCE_MANUAL_REVIEW_OPENED',null,
      jsonb_build_object('source_row_id',v_row_id,'work_event_id',v_source->'work_event_id','reason',v_reason,
        'opening_final_revision_id',v_source->'final_revision_id',
        'opening_projection_publication_id',v_source->'projection_publication_id'),
      'Office sent imported shift to Pay Queries',v_actor);
  end if;
  v_result:=jsonb_build_object('ok',true,'review_id',v_review,'already_open',v_existing,
    'problem','Manually queried','idempotent_replay',false);
  insert into private.weekly_source_manual_review_commands(command_id,command_kind,actor_user_id,request_sha256,
    review_id,source_cycle_id,client_id,week_ending_date,opening_final_revision_id,opening_projection_publication_id,
    opening_target_family_id,opening_event_sequence,result_json)
  values(v_command_id,'OPEN',v_actor,v_hash,v_review,v_cycle.id,(v_source->>'client_id')::uuid,
    (v_source->>'week_ending_date')::date,case when not v_existing then (v_source->>'final_revision_id')::uuid end,
    case when not v_existing then (v_source->>'projection_publication_id')::uuid end,
    case when not v_existing then v_family_id end,case when not v_existing then v_sequence end,v_result);
  return v_result;
end;
$function$;
alter function public.weekly_source_manual_review_open_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_manual_review_open_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_manual_review_open_v1(jsonb) to service_role;

-- Called only inside a genuine Final/Correct CURRENT transition, before the
-- existing Banking current selector. No monetary action or source projection.
create or replace function private.weekly_source_manual_reviews_finalised_v1(p_final_revision_id uuid,p_actor_user_id uuid)
returns integer language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_final public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_review private.weekly_source_manual_reviews%rowtype;
  v_anchor private.weekly_source_manual_review_commands%rowtype;
  v_opening_upload_id uuid;
  v_count integer:=0;
begin
  perform private.weekly_source_query_require_service_v1();
  select f.* into strict v_final from public.weekly_source_final_revisions f where f.id=p_final_revision_id;
  select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=v_final.source_cycle_id;
  if p_actor_user_id is null or v_final.state is distinct from 'CURRENT' or v_final.finalised_by_user_id is distinct from p_actor_user_id
     or v_final.finalised_at_utc is null or not isfinite(v_final.finalised_at_utc) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_FINAL_AUTHORITY_INVALID' using errcode='55000'; end if;
  perform private.weekly_source_pay_query_admit_v2();
  -- The sole reviewed Final/Correct mutation callers invoke this private hook
  -- after their successful CURRENT CAS, never on preparation or replay. Do not
  -- compare preparation timestamps, nor xmin to the top xid: the real owner
  -- may write in a PL/pgSQL exception subtransaction. Validate its actual CAS
  -- result here; caller closure and genuine-owner native proof are mandatory.
  if (v_final.authority_scope_kind='CYCLE' and v_cycle.current_final_revision_id is distinct from v_final.id)
    or (v_final.authority_scope_kind='NHSP_REPORT_SCOPE' and not exists(
      select 1 from public.weekly_source_report_scopes s where s.id=v_final.report_scope_id
        and s.source_cycle_id=v_cycle.id and s.current_final_revision_id=v_final.id)) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_FINAL_AUTHORITY_INVALID' using errcode='55000'; end if;
  for v_review in
    with contained as materialized (
      select distinct s.work_event_id,s.candidate_id,s.client_id,s.contract_id,s.work_date
      from private.weekly_source_manual_review_final_rows_v2(v_final.id) s
    )
    select r.* from contained s join private.weekly_source_manual_reviews r
      on r.source_group_id=v_cycle.source_group_id and r.work_event_id=s.work_event_id and r.state='OPEN'
      and r.candidate_id=s.candidate_id and r.client_id=s.client_id
      and r.contract_id=s.contract_id and r.work_date=s.work_date
    order by r.id for update of r
  loop
    select c.* into v_anchor from private.weekly_source_manual_review_commands c where c.review_id=v_review.id
      and (c.opening_final_revision_id is not null or c.opening_projection_publication_id is not null);
    -- A legacy review without captured opening provenance needs an explicit
    -- Office remedy. Never manufacture an anchor using today's report.
    if not found or v_anchor.opening_final_revision_id=p_final_revision_id
       or not exists(select 1 from public.weekly_source_client_manifests m where m.final_revision_id=v_final.id
         and m.source_group_id=v_cycle.source_group_id and m.source_cycle_id=v_cycle.id and m.client_id=v_review.client_id) then continue; end if;
    -- A new Final for the report already queried is not a new imported report.
    -- Resolve the immutable opening authority, not preparation timestamps or
    -- the currently displayed row; rebuilt projections of that upload also
    -- remain the same report. Missing opening evidence is never a remedy.
    if v_anchor.opening_final_revision_id is not null then
      select f.upload_id into v_opening_upload_id from public.weekly_source_final_revisions f
        where f.id=v_anchor.opening_final_revision_id;
    else
      select p.upload_id into v_opening_upload_id from public.weekly_source_projection_publications p
        where p.id=v_anchor.opening_projection_publication_id;
    end if;
    if v_opening_upload_id is null or v_opening_upload_id=v_final.upload_id then continue; end if;
    perform private.weekly_source_office_authority_v1(p_actor_user_id,'ACCEPT_SYSTEM_HOURS',
      v_cycle.source_group_id,v_review.client_id,v_cycle.finalisation_week_ending);
    update private.weekly_source_manual_reviews set state='RESOLVED',resolved_by_user_id=p_actor_user_id,
      resolved_at_utc=statement_timestamp(),resolution_kind='OFFICE_ACCEPTED_SOURCE' where id=v_review.id;
    perform public._audit_insert('weekly_source_manual_review',v_review.id::text,'WEEKLY_SOURCE_MANUAL_REVIEW_RESOLVED',null,
      jsonb_build_object('resolution_kind','OFFICE_ACCEPTED_SOURCE','work_event_id',v_review.work_event_id,
        'final_revision_id',v_final.id,'reason','A later finalised report contains this shift'),
      'Later finalised source report resolved imported-shift review',p_actor_user_id);
    v_count:=v_count+1;
  end loop;
  return v_count;
end;
$function$;
alter function private.weekly_source_manual_reviews_finalised_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manual_reviews_finalised_v1(uuid,uuid)
  from public,anon,authenticated,service_role;

create or replace function public.weekly_source_manual_review_resolve_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid; v_review_id uuid; v_command_id uuid; v_kind text; v_hash bytea;
  v_prior private.weekly_source_manual_review_commands%rowtype;
  v_review private.weekly_source_manual_reviews%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_approval public.weekly_exceptional_payment_approvals%rowtype;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_anchor private.weekly_source_manual_review_commands%rowtype;
  v_scope jsonb; v_source jsonb; v_result jsonb; v_receipt jsonb;
  v_local jsonb; v_c1 jsonb; v_next jsonb;
  v_approval_id uuid; v_generation_id uuid; v_source_row_id uuid;
  v_expected_hash text; v_count integer; v_local_count integer; v_c1_count integer;
  v_next_count integer; v_audit_count integer; v_week date;
begin
  perform private.weekly_source_query_require_service_v1();
  if jsonb_typeof(p_request) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_request) k
    where k not in ('actor_user_id','review_id','resolution_kind','expected_current_row_hash',
      'command_id','accepted_approval_id','accepted_generation_id')) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023'; end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid; v_review_id:=(p_request->>'review_id')::uuid;
    v_command_id:=(p_request->>'command_id')::uuid;
    v_approval_id:=(p_request->>'accepted_approval_id')::uuid;
    v_generation_id:=(p_request->>'accepted_generation_id')::uuid;
  exception when others then raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023'; end;
  v_kind:=p_request->>'resolution_kind';
  if v_actor is null or v_review_id is null or v_command_id is null
     or v_kind is null or v_kind not in ('OFFICE_ACCEPTED_SOURCE','PROTECTED_PAY') then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023'; end if;
  v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_MANUAL_REVIEW_RESOLVE_V2',p_request);
  select c.* into v_prior from private.weekly_source_manual_review_commands c where c.command_id=v_command_id;
  if found then
    if v_prior.command_kind is distinct from 'RESOLVE' or v_prior.actor_user_id is distinct from v_actor
       or v_prior.request_sha256 is distinct from v_hash or v_prior.review_id is distinct from v_review_id then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_COMMAND_COLLISION' using errcode='23505'; end if;
    select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=v_prior.source_cycle_id;
    perform private.weekly_source_office_authority_v1(v_actor,
      case when v_kind='PROTECTED_PAY' then 'APPROVE_PROTECTED_PAY' else 'ACCEPT_SYSTEM_HOURS' end,
      v_cycle.source_group_id,v_prior.client_id,v_cycle.finalisation_week_ending);
    return v_prior.result_json||jsonb_build_object('idempotent_replay',true);
  end if;
  perform private.weekly_source_pay_query_admit_v2();
  perform pg_advisory_xact_lock(hashtextextended('WEEKLY_SOURCE_MANUAL_REVIEW_COMMAND:'||v_command_id::text,0));
  select c.* into v_prior from private.weekly_source_manual_review_commands c where c.command_id=v_command_id;
  if found then
    if v_prior.command_kind is distinct from 'RESOLVE' or v_prior.actor_user_id is distinct from v_actor
       or v_prior.request_sha256 is distinct from v_hash or v_prior.review_id is distinct from v_review_id then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_COMMAND_COLLISION' using errcode='23505'; end if;
    select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=v_prior.source_cycle_id;
    perform private.weekly_source_office_authority_v1(v_actor,
      case when v_kind='PROTECTED_PAY' then 'APPROVE_PROTECTED_PAY' else 'ACCEPT_SYSTEM_HOURS' end,
      v_cycle.source_group_id,v_prior.client_id,v_cycle.finalisation_week_ending);
    return v_prior.result_json||jsonb_build_object('idempotent_replay',true);
  end if;
  select r.* into v_review from private.weekly_source_manual_reviews r where r.id=v_review_id;
  if not found or v_review.state is distinct from 'OPEN' then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_NOT_OPEN' using errcode='40001'; end if;
  select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=v_review.source_cycle_id;
  perform private.weekly_source_office_authority_v1(v_actor,
    case when v_kind='PROTECTED_PAY' then 'APPROVE_PROTECTED_PAY' else 'ACCEPT_SYSTEM_HOURS' end,
    v_review.source_group_id,v_review.client_id,v_cycle.finalisation_week_ending);
  select c.week_ending_weekday_snapshot into v_count from public.contracts c where c.id=v_review.contract_id;
  if v_count is null or v_count not between 0 and 6 then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_AUTHORITY_INVALID' using errcode='55000'; end if;
  v_week:=v_review.work_date+((v_count-extract(dow from v_review.work_date)::integer+7)%7);
  perform pg_advisory_xact_lock(hashtextextended('WEEKLY_SOURCE_QUERY_FAMILY:'||v_review.contract_id::text||':'||v_week::text,0));
  select r.* into strict v_review from private.weekly_source_manual_reviews r where r.id=v_review_id and r.state='OPEN' for update;
  if v_kind='OFFICE_ACCEPTED_SOURCE' then
    if v_approval_id is not null or v_generation_id is not null then
      if v_approval_id is null or v_generation_id is null or p_request->>'expected_current_row_hash' is not null then
        raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_CURRENT_SOURCE_REQUIRED' using errcode='22023'; end if;
      -- This union arm is an actual accepted WITHDRAW/RECONCILE decision, not
      -- a client-supplied absence flag or a relaxed latest-WAIT receipt.
      v_receipt:=private.weekly_source_accepted_removal_query_evidence_v1(
        v_review.id,v_approval_id,v_generation_id,v_actor,v_command_id);
      if v_receipt is null then
        raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_CURRENT_SOURCE_REQUIRED' using errcode='55000'; end if;
      v_source_row_id:=(v_receipt#>>'{selected_source_witness,basis,upload_row_id}')::uuid;
    else
    v_expected_hash:=p_request->>'expected_current_row_hash';
    if v_expected_hash is null or v_expected_hash!~'^[0-9a-f]{64}$'
       or v_approval_id is not null or v_generation_id is not null then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_CURRENT_SOURCE_REQUIRED' using errcode='22023'; end if;
    select u.* into strict v_upload from public.weekly_source_uploads u where u.id=(select r.upload_id
      from public.weekly_source_upload_rows r where r.id=v_review.upload_row_id);
    if not exists(select 1 from public.weekly_source_final_revisions f
      where f.source_cycle_id=v_cycle.id and f.report_scope_id is not distinct from v_upload.report_scope_id and f.state='CURRENT')
      and exists(select 1 from public.weekly_source_projection_publications p
        where p.source_cycle_id=v_cycle.id and p.report_scope_id is not distinct from v_upload.report_scope_id and p.state='CURRENT'
          and (p.authority_scope_version>2147483647 or coalesce(p.projection_generation,0)>2147483647)) then
      raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003'; end if;
    -- The unique CURRENT authority in the original declared report scope,
    -- not an arbitrary newest row or a different client/report's upload.
    with final_authority as (
      select f.id,f.upload_id from public.weekly_source_final_revisions f
      where f.source_cycle_id=v_cycle.id and f.report_scope_id is not distinct from v_upload.report_scope_id and f.state='CURRENT'
    ), candidates as (
      select s.upload_row_id,s.row_resolution_id from final_authority f
      cross join lateral private.weekly_source_manual_review_final_rows_v2(f.id) s
      where s.work_event_id=v_review.work_event_id and s.candidate_id=v_review.candidate_id
        and s.client_id=v_review.client_id and s.contract_id=v_review.contract_id and s.work_date=v_review.work_date
      union all
      select r.upload_row_id,r.id from public.weekly_source_projection_publications p
      join public.weekly_source_upload_rows u on u.upload_id=p.upload_id
      join public.weekly_source_row_resolutions r on r.upload_row_id=u.id
        and r.generation=coalesce(p.projection_generation,p.authority_scope_version::integer)
      where not exists(select 1 from final_authority) and p.source_cycle_id=v_cycle.id
        and p.report_scope_id is not distinct from v_upload.report_scope_id and p.state='CURRENT'
        and r.mapping_state='RESOLVED' and r.work_event_id=v_review.work_event_id
        and r.candidate_id=v_review.candidate_id and r.client_id=v_review.client_id
        and r.contract_id=v_review.contract_id and u.work_date=v_review.work_date
    ) select count(*),(array_agg(c.upload_row_id))[1] into v_count,v_source_row_id
      from candidates c join public.weekly_source_upload_rows u on u.id=c.upload_row_id
      where encode(u.normalised_row_hash,'hex')=v_expected_hash;
    if v_count<>1 then raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_SOURCE_STALE' using errcode='40001'; end if;
    v_source:=private.weekly_source_manual_review_source_v2(v_source_row_id);
    if v_source is null or v_source->>'work_event_id' is distinct from v_review.work_event_id::text
       or v_source->>'candidate_id' is distinct from v_review.candidate_id::text
       or v_source->>'client_id' is distinct from v_review.client_id::text
       or v_source->>'contract_id' is distinct from v_review.contract_id::text then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_SOURCE_STALE' using errcode='40001'; end if;
    end if;
  else
    if v_approval_id is null or v_generation_id is null or p_request->>'expected_current_row_hash' is not null then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_PROTECTED_PAY_REQUIRED' using errcode='22023'; end if;
    select a.* into v_approval from public.weekly_exceptional_payment_approvals a where a.id=v_approval_id;
    if not found or v_approval.work_event_id is distinct from v_review.work_event_id
       or v_approval.candidate_id is distinct from v_review.candidate_id or v_approval.client_id is distinct from v_review.client_id
       or v_approval.contract_id is distinct from v_review.contract_id or v_approval.week_ending is distinct from v_week then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_PROTECTED_PAY_REQUIRED' using errcode='55000'; end if;
    select f.* into strict v_family from public.weekly_exceptional_pay_target_families f where f.id=v_approval.pay_target_family_id;
    select c.* into v_anchor from private.weekly_source_manual_review_commands c where c.review_id=v_review.id
      and (c.opening_final_revision_id is not null or c.opening_projection_publication_id is not null);
    if found then
      if (v_anchor.opening_target_family_id is not null and v_anchor.opening_target_family_id is distinct from v_family.id)
        or not exists(select 1 from public.weekly_exceptional_pay_family_events e
          where e.family_id=v_family.id and e.durable_work_event_id=v_review.work_event_id
            and e.evidence_approval_id=v_approval.id and e.event_sequence>v_anchor.opening_event_sequence) then
        raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_PROTECTED_PAY_REQUIRED' using errcode='55000'; end if;
    elsif v_approval.approved_at_utc<v_review.opened_at_utc then
      -- Legacy reviews still allow an explicit new decision, not adoption of
      -- an earlier approval. No opening ancestry is fabricated for them.
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_PROTECTED_PAY_REQUIRED' using errcode='55000';
    end if;
    v_scope:=private.weekly_source_pay_query_scope_v1(v_family.root_timesheet_id);
    if v_scope is null or v_scope->>'target_family_id' is distinct from v_family.id::text then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_PROTECTED_PAY_REQUIRED' using errcode='55000'; end if;
    v_local:=private.weekly_source_pay_query_local_receipt_v1(v_family.root_timesheet_id,v_approval_id,v_generation_id);
    v_c1:=private.weekly_source_pay_query_c1_receipt_v1(v_family.root_timesheet_id,v_approval_id,v_generation_id);
    v_next:=private.weekly_source_pay_query_next_receipt_v1(v_family.root_timesheet_id,v_approval_id,v_generation_id);
    v_count:=(v_local is not null)::integer+(v_c1 is not null)::integer+(v_next is not null)::integer;
    select count(*) into v_local_count from private.weekly_source_local_protected_decision_receipts l
      join public.weekly_exceptional_c1_publication_requests r on r.id=l.publication_request_id
      where l.generation_id=v_generation_id or r.orchestration_run_id=v_approval.creation_orchestration_run_id;
    select count(*),count(*) filter (where
      (v_local is not null and r.id::text=v_local->>'publication_request_id' and r.state='RETIRED')
      or (v_c1 is not null and r.id::text=v_c1->>'publication_request_id' and r.state='PUBLISHED'))
      into v_c1_count,v_audit_count from public.weekly_exceptional_c1_publication_requests r
      where r.generation_id=v_generation_id or r.orchestration_run_id=v_approval.creation_orchestration_run_id;
    select count(*) into v_next_count from private.bpay_next_protected_source_receipt r
      where r.approval_id=v_approval_id or r.generation_id=v_generation_id
        or r.orchestration_run_id=v_approval.creation_orchestration_run_id;
    if v_count<>1
       or (v_local is not null and (v_local_count<>1 or v_c1_count<>1 or v_audit_count<>1 or v_next_count<>0))
       or (v_c1 is not null and (v_local_count<>0 or v_c1_count<>1 or v_audit_count<>1 or v_next_count<>0))
       or (v_next is not null and (v_local_count<>0 or v_c1_count<>0 or v_next_count<>1)) then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_PROTECTED_PAY_REQUIRED' using errcode='55000'; end if;
    v_receipt:=coalesce(v_local,v_c1,v_next);
  end if;
  update private.weekly_source_manual_reviews set state='RESOLVED',resolved_by_user_id=v_actor,
    resolved_at_utc=statement_timestamp(),resolution_kind=v_kind where id=v_review.id;
  perform public._audit_insert('weekly_source_manual_review',v_review.id::text,'WEEKLY_SOURCE_MANUAL_REVIEW_RESOLVED',null,
    jsonb_build_object('resolution_kind',v_kind,'work_event_id',v_review.work_event_id,
      'accepted_source_row_id',v_source_row_id,'accepted_receipt',v_receipt),
    'Office resolved imported-shift review',v_actor);
  v_result:=jsonb_build_object('ok',true,'review_id',v_review.id,'resolution_kind',v_kind,'idempotent_replay',false);
  insert into private.weekly_source_manual_review_commands(command_id,command_kind,actor_user_id,request_sha256,
    review_id,source_cycle_id,client_id,week_ending_date,result_json)
  values(v_command_id,'RESOLVE',v_actor,v_hash,v_review.id,v_cycle.id,v_review.client_id,v_week,v_result);
  return v_result;
end;
$function$;
alter function public.weekly_source_manual_review_resolve_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_manual_review_resolve_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_manual_review_resolve_v1(jsonb) to service_role;

notify pgrst, 'reload schema';



-- CONTACT_PREPARER_UNIT 34 repeatable supabase/repeatable/06102026_1214_self_bill_candidate_expense_separation_v1.sql SHA256 09adf8fe2ed3c423484a277d30e32f761bf6b482b6633eb45201c6d47b9c2501


-- Self-billed Candidate expenses must use a separate expense Timesheet,
-- including ordinary (non-import-authoritative) weekly and daily hours.
-- Preserve immutable Timesheet snapshots and all import/hour-entry authority.
-- No business rows, approved claims, finance or payment artifacts are changed.


create or replace function private._contract_settings_effective_core_v1(
  p_client_id uuid,
  p_contract_id uuid,
  p_relevant_date date,
  p_workflow text,
  p_timesheet_id uuid default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare
  v_contract public.contracts%rowtype;
  v_client public.client_settings%rowtype;
  v_client_record public.clients%rowtype;
  v_defaults public.settings_defaults%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_finance jsonb := '{}'::jsonb;
  v_client_id uuid := p_client_id;
  v_client_found boolean := false;
  v_unresolved_daily boolean := false;
  v_workflow text := upper(btrim(coalesce(p_workflow, '')));
  v_override boolean := false;
  v_is_nhsp boolean := false;
  v_requires_hr boolean := false;
  v_autoprocess_hr boolean := false;
  v_no_timesheet_required boolean := false;
  v_import_authoritative boolean := false;
  v_self_bill boolean := false;
  v_configuration_valid boolean := true;
  v_configuration_issue text;
  v_route text := 'STANDARD_WEEKLY';
  v_source text := 'CLIENT_SETTINGS';
  v_holidays jsonb := '[]'::jsonb;
  v_values jsonb;
  v_sources jsonb;
  v_components jsonb;
  v_applicability jsonb;
  v_payload jsonb;
  v_fingerprint text;
begin
  if p_relevant_date is null then
    raise exception 'CONTRACT_SETTINGS_RELEVANT_DATE_REQUIRED' using errcode='22023';
  end if;
  if v_workflow not in ('WEEKLY','DAILY','IMPORT','OFFICE','INVOICE','FINANCE') then
    raise exception 'CONTRACT_SETTINGS_WORKFLOW_INVALID' using errcode='22023';
  end if;

  if p_timesheet_id is not null then
    select * into v_timesheet
    from public.timesheets t
    where t.timesheet_id=p_timesheet_id and t.is_current=true;
    if not found then
      raise exception 'CONTRACT_SETTINGS_CURRENT_TIMESHEET_NOT_FOUND' using errcode='P0002';
    end if;
    if v_timesheet.settings_authority_json <> '{}'::jsonb then
      return private._timesheet_settings_authority_frozen_v1(p_timesheet_id);
    end if;
    if v_timesheet.sheet_scope='WEEKLY'::public.timesheet_scope_enum
       or exists(
         select 1 from public.timesheets_financials tf
         where tf.timesheet_id=v_timesheet.timesheet_id
           and tf.is_current=true
           and tf.processed_at_utc is not null
       ) then
      raise exception 'CONTRACT_SETTINGS_TIMESHEET_AUTHORITY_NOT_FROZEN' using errcode='55000';
    end if;
    if p_contract_id is not null and p_contract_id is distinct from v_timesheet.contract_id then
      raise exception 'CONTRACT_SETTINGS_TIMESHEET_CONTRACT_MISMATCH' using errcode='22023';
    end if;
  end if;

  if p_contract_id is not null then
    select * into v_contract from public.contracts c where c.id=p_contract_id;
    if not found then
      raise exception 'CONTRACT_SETTINGS_CONTRACT_NOT_FOUND' using errcode='P0002';
    end if;
    if v_client_id is not null and v_client_id<>v_contract.client_id then
      raise exception 'CONTRACT_SETTINGS_CLIENT_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    v_client_id:=v_contract.client_id;
    v_override:=coalesce(v_contract.overrideclientsettings,false);
  end if;
  if v_client_id is null then
    v_unresolved_daily:=(
      p_timesheet_id is not null
      and v_workflow='DAILY'
      and v_timesheet.sheet_scope='DAILY'::public.timesheet_scope_enum
      and v_timesheet.contract_id is null
      and v_timesheet.settings_authority_json='{}'::jsonb
    );
    if not v_unresolved_daily then
      raise exception 'CONTRACT_SETTINGS_CLIENT_REQUIRED' using errcode='22023';
    end if;
  else
    select * into v_client_record from public.clients cl where cl.id=v_client_id;
    if not found then
      raise exception 'CONTRACT_SETTINGS_CLIENT_NOT_FOUND' using errcode='P0002';
    end if;

    select * into v_client
    from public.client_settings cs
    where cs.client_id=v_client_id
      and (cs.effective_from is null or cs.effective_from<=p_relevant_date)
    order by cs.effective_from desc nulls last,cs.updated_at desc,cs.id desc
    limit 1;
    v_client_found:=found;
    if not v_client_found then
      raise exception 'CONTRACT_SETTINGS_CLIENT_SETTINGS_NOT_FOUND' using errcode='P0002';
    end if;
  end if;
  select * into v_defaults from public.settings_defaults d where d.id=1;
  if not found then
    raise exception 'CONTRACT_SETTINGS_GLOBAL_SETTINGS_NOT_FOUND' using errcode='P0002';
  end if;
  select to_jsonb(fin) into v_finance
  from public.settings_finance_pick(p_relevant_date) fin
  limit 1;
  v_finance:=coalesce(v_finance,'{}'::jsonb);

  v_is_nhsp:=case when v_override then coalesce(v_contract.is_nhsp,false)
    else coalesce(v_client.is_nhsp,false) end;
  v_requires_hr:=case when v_override then coalesce(v_contract.requires_hr,false)
    else coalesce(v_client.requires_hr,false) end;
  v_autoprocess_hr:=case when v_override then coalesce(v_contract.autoprocess_hr,false)
    else coalesce(v_client.autoprocess_hr,false) end;
  v_no_timesheet_required:=case when v_override then coalesce(v_contract.no_timesheet_required,false)
    else coalesce(v_client.no_timesheet_required,false) end;

  if v_is_nhsp and (v_requires_hr or v_autoprocess_hr or v_no_timesheet_required) then
    v_configuration_valid:=false;
    v_configuration_issue:='MULTIPLE_IMPORT_FAMILIES';
  elsif v_is_nhsp and v_workflow='DAILY' then
    v_configuration_valid:=false;
    v_configuration_issue:='NHSP_WEEKLY_WITH_DAILY_WORKFLOW';
  elsif v_no_timesheet_required and not v_autoprocess_hr then
    v_configuration_valid:=false;
    v_configuration_issue:='AUTHORITATIVE_ROSTER_WITHOUT_AUTOPROCESS';
  elsif v_requires_hr and not v_autoprocess_hr then
    v_configuration_valid:=false;
    v_configuration_issue:='ROSTER_VALIDATION_WITHOUT_AUTOPROCESS';
  elsif v_autoprocess_hr and not v_no_timesheet_required and not v_requires_hr then
    v_configuration_valid:=false;
    v_configuration_issue:='ROSTER_MODE_NOT_SELECTED';
  end if;

  v_route:=case
    when v_is_nhsp then 'DEDICATED_NHSP_WEEKLY'
    when v_autoprocess_hr and v_no_timesheet_required and v_workflow='DAILY' then 'HEALTHROSTER_DAILY_AUTHORITATIVE'
    when v_autoprocess_hr and v_no_timesheet_required then 'HEALTHROSTER_WEEKLY_AUTHORITATIVE'
    when v_autoprocess_hr and v_workflow='DAILY' then 'HEALTHROSTER_DAILY_VALIDATION'
    when v_autoprocess_hr then 'HEALTHROSTER_WEEKLY_VALIDATION'
    when v_workflow='DAILY' then 'STANDARD_DAILY'
    else 'STANDARD_WEEKLY' end;
  v_source:=case
    when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
    when v_override then 'CONTRACT_OVERRIDE'
    else 'CLIENT_SETTINGS' end;
  -- Historical contradictory rows fail safely: they can never grant Candidate
  -- hour entry merely because their old flags disagree.
  v_import_authoritative:=case
    when not v_configuration_valid then v_is_nhsp or v_no_timesheet_required
    else v_is_nhsp or (v_autoprocess_hr and v_no_timesheet_required)
  end;

  -- Self-billing controls expense separation, not Candidate hour-entry authority.
  v_self_bill:=case when v_override then coalesce(v_contract.self_bill,false)
    else coalesce(v_client.self_bill_no_invoices_sent,false) end;

  select coalesce(jsonb_agg(to_jsonb(h.date_value) order by h.date_value),'[]'::jsonb)
  into v_holidays
  from (
    select distinct btrim(x.date_value) date_value
    from (
      select jsonb_array_elements_text(
        case when jsonb_typeof(v_defaults.bh_list)='array' then v_defaults.bh_list else '[]'::jsonb end
      ) date_value
      union all
      select jsonb_array_elements_text(
        case when jsonb_typeof(v_defaults.bh_feed_list)='array' then v_defaults.bh_feed_list else '[]'::jsonb end
      ) date_value
    ) x
    where btrim(x.date_value) ~ '^\d{4}-\d{2}-\d{2}$'
  ) h;

  v_values:=jsonb_build_object(
    'timezone_id',coalesce(v_client.timezone_id,v_defaults.timezone_id,'Europe/London'),
    'day_start',coalesce(v_client.day_start,v_defaults.day_start),
    'day_end',coalesce(v_client.day_end,v_defaults.day_end),
    'night_start',coalesce(v_client.night_start,v_defaults.night_start),
    'night_end',coalesce(v_client.night_end,v_defaults.night_end),
    'sat_start',coalesce(v_client.sat_start,v_defaults.sat_start),
    'sat_end',coalesce(v_client.sat_end,v_defaults.sat_end),
    'sun_start',coalesce(v_client.sun_start,v_defaults.sun_start),
    'sun_end',coalesce(v_client.sun_end,v_defaults.sun_end),
    'bh_start',coalesce(v_client.bh_start,v_defaults.bh_start),
    'bh_end',coalesce(v_client.bh_end,v_defaults.bh_end),
    'bh_list',v_holidays,
    'vat_rate_pct',coalesce(v_client.vat_rate_pct,(v_finance->>'vat_rate_pct')::numeric,20),
    'holiday_pay_pct',coalesce(v_client.holiday_pay_pct,(v_finance->>'holiday_pay_pct')::numeric,12.07),
    'erni_pct',coalesce((v_finance->>'erni_pct')::numeric,13.8),
    'apply_holiday_to',coalesce(v_client.apply_holiday_to,v_finance->>'apply_holiday_to','PAYE_ONLY'),
    'apply_erni_to',coalesce(v_finance->>'apply_erni_to','PAYE_ONLY'),
    'margin_includes',coalesce(v_client.margin_includes,v_finance->'margin_includes','{}'::jsonb),
    'hr_validation_required',coalesce(v_client.hr_validation_required,false),
    'ts_reference_required',coalesce(v_client.ts_reference_required,v_defaults.ts_reference_required,false),
    'week_ending_weekday',coalesce(v_client.week_ending_weekday,
      case when p_contract_id is not null then v_contract.week_ending_weekday_snapshot end,0),
    'default_submission_mode',case when v_override then coalesce(v_contract.default_submission_mode,'ELECTRONIC')
      else coalesce(v_client.default_submission_mode,'ELECTRONIC') end,
    'is_nhsp',v_is_nhsp,
    'requires_hr',v_requires_hr,
    'autoprocess_hr',v_autoprocess_hr,
    'no_timesheet_required',v_no_timesheet_required
  )||jsonb_build_object(
    'hr_validation_required_for_invoice',case when v_override
      then coalesce(v_contract.requires_hr,false)
      else coalesce(v_client.hr_validation_required,false) end,
    'daily_calc_of_invoices',case when v_override then coalesce(v_contract.daily_calc_of_invoices,false)
      else coalesce(v_client.daily_calc_of_invoices,false) end,
    'group_nightsat_sunbh',case when v_override then coalesce(v_contract.group_nightsat_sunbh,false)
      else coalesce(v_client.group_nightsat_sunbh,false) end,
    'auto_invoice',case when v_override then coalesce(v_contract.auto_invoice,false)
      else coalesce(v_client.auto_invoice_default,false) end,
    'self_bill',v_self_bill,
    'require_reference_to_pay',case when v_override then coalesce(v_contract.require_reference_to_pay,false)
      else coalesce(v_client.pay_reference_required,false) end,
    'require_reference_to_invoice',case when v_override then coalesce(v_contract.require_reference_to_invoice,false)
      else coalesce(v_client.invoice_reference_required,false) end,
    'reference_number_required_to_issue_invoice',case when v_override
      then coalesce(v_contract.reference_number_required_to_issue_invoice,false)
      else coalesce(v_client.reference_number_required_to_issue_invoice,false) end,
    'hr_attach_to_invoice',case when v_override then coalesce(v_contract.hr_attach_to_invoice,true)
      else coalesce(v_client.hr_attach_to_invoice,v_defaults.hr_attach_to_invoice,true) end,
    'ts_attach_to_invoice',case when v_override then coalesce(v_contract.ts_attach_to_invoice,true)
      else coalesce(v_client.ts_attach_to_invoice,v_defaults.ts_attach_to_invoice,true) end,
    'send_manual_invoices_to_different_email',case when v_override
      then coalesce(v_contract.send_manual_invoices_to_different_email,false)
      else coalesce(v_client.send_manual_invoices_to_different_email,false) end,
    'manual_invoices_alt_email_address',case when v_override then v_contract.manual_invoices_alt_email_address
      else v_client.manual_invoices_alt_email_address end,
    'invoice_consolidation_mode',v_client.invoice_consolidation_mode,
    'healthroster_import_auto_authorise',case when v_unresolved_daily then false else
      coalesce(v_contract.healthroster_import_auto_authorise_override,
        v_client.healthroster_import_auto_authorise,
        v_defaults.healthroster_import_auto_authorise_default,false) end,
    'nhsp_import_auto_authorise',case when v_unresolved_daily then false else
      coalesce(v_contract.nhsp_import_auto_authorise_override,
        v_client.nhsp_import_auto_authorise,v_defaults.nhsp_import_auto_authorise_default,false) end,
    'candidate_electronic_auto_authorise',case when v_unresolved_daily then false else
      coalesce(v_contract.candidate_electronic_auto_authorise_override,
        v_client.candidate_electronic_auto_authorise,
        v_defaults.candidate_electronic_auto_authorise_default,false) end,
    'auto_authorise_on_validation',coalesce(v_defaults.auto_authorise_on_validation,false),
    'candidate_expenses_require_separate_timesheet',case when v_import_authoritative then true
      when v_self_bill then true
      else coalesce(v_contract.candidate_expenses_require_separate_timesheet_override,
        v_client.candidate_expenses_require_separate_timesheet,false) end,
    'candidate_paper_submission_enabled',case when v_import_authoritative then false
      else coalesce(v_contract.candidate_paper_submission_enabled_override,
        v_client.candidate_paper_submission_enabled,false) end,
    'candidate_expense_invoice_email',coalesce(v_contract.candidate_expense_invoice_email_override,
      v_client.candidate_expense_invoice_email),
    'candidate_manager_approval_policy_json',private._candidate_manager_authoriser_effective_v2(
      coalesce(v_client.candidate_manager_approval_policy_json,'{}'::jsonb),
      case when p_contract_id is null then null else v_contract.candidate_manager_approval_policy_json end
    ),
    'allow_daily_manager_authorise_on_phone',coalesce(v_client.allow_daily_manager_authorise_on_phone,true),
    'allow_daily_manager_authorise_by_email',coalesce(v_client.allow_daily_manager_authorise_by_email,false),
    'timesheet_break_entry_mode',case when v_import_authoritative then null
      when v_override then v_contract.timesheet_break_entry_mode else v_client.timesheet_break_entry_mode end,
    'weekly_timesheet_source',case when p_contract_id is null then null else v_contract.weekly_timesheet_source end,
    'rates_json',case when p_contract_id is null then null else v_contract.rates_json end,
    'additional_rates_json',case when p_contract_id is null then null else v_contract.additional_rates_json end,
    'mileage_pay_rate',case when p_contract_id is null then null else v_contract.mileage_pay_rate end,
    'mileage_charge_rate',case when p_contract_id is null then null else v_contract.mileage_charge_rate end,
    'mileage_pay_defaults',v_finance->'mileage_pay_defaults',
    'mileage_charge_defaults',v_finance->'mileage_charge_defaults',
    'bucket_labels_json',case when p_contract_id is null then null else v_contract.bucket_labels_json end,
    'client_vat_chargeable',coalesce(v_client_record.vat_chargeable,true),
    'client_payment_terms_days',v_client_record.payment_terms_days,
    'client_primary_invoice_email',v_client_record.primary_invoice_email
  );

  v_sources:=jsonb_build_object(
    'time_windows',case when v_unresolved_daily then 'GLOBAL' else 'CLIENT_THEN_GLOBAL' end,
    'bank_holiday_dates','GLOBAL_MANUAL_PLUS_GOV_UK_ENGLAND_AND_WALES',
    'bank_holiday_hours',case when v_unresolved_daily then 'GLOBAL' else 'CLIENT_THEN_GLOBAL' end,
    'erni_pct','GLOBAL_FINANCE_WINDOW',
    'apply_erni_to','GLOBAL_FINANCE_WINDOW',
    'finance_window',coalesce(v_finance->>'source','GLOBAL_FINANCE_WINDOW'),
    'contract_governed_settings',v_source,
    'healthroster_import_auto_authorise',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when p_contract_id is not null and v_contract.healthroster_import_auto_authorise_override is not null
        then 'CONTRACT'
      when v_client.healthroster_import_auto_authorise is not null then 'CLIENT'
      else 'GLOBAL' end,
    'nhsp_import_auto_authorise',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when p_contract_id is not null and v_contract.nhsp_import_auto_authorise_override is not null
        then 'CONTRACT'
      when v_client.nhsp_import_auto_authorise is not null then 'CLIENT'
      else 'GLOBAL' end,
    'candidate_electronic_auto_authorise',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when p_contract_id is not null and v_contract.candidate_electronic_auto_authorise_override is not null
        then 'CONTRACT'
      when v_client.candidate_electronic_auto_authorise is not null then 'CLIENT'
      else 'GLOBAL' end,
    'candidate_expenses_require_separate_timesheet',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when v_import_authoritative then 'IMPORT_MANDATORY'
      when v_self_bill then 'SELF_BILL_MANDATORY'
      when p_contract_id is not null
       and v_contract.candidate_expenses_require_separate_timesheet_override is not null then 'CONTRACT'
      else 'CLIENT' end,
    'candidate_paper_submission_enabled',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when v_import_authoritative then 'IMPORT_DISABLED'
      when p_contract_id is not null and v_contract.candidate_paper_submission_enabled_override is not null
        then 'CONTRACT'
      else 'CLIENT' end,
    'candidate_expense_invoice_email',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when p_contract_id is not null and v_contract.candidate_expense_invoice_email_override is not null
        then 'CONTRACT'
      else 'CLIENT' end,
    'candidate_manager_approval_policy_json',case
      when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
      when p_contract_id is not null and v_contract.candidate_manager_approval_policy_json is not null
        then 'CONTRACT'
      else 'CLIENT' end,
    'contract_rates','CONTRACT'
  );
  v_components:=jsonb_build_object(
    'healthroster_import_auto_authorise',jsonb_build_object(
      'global',v_defaults.healthroster_import_auto_authorise_default,
      'client',v_client.healthroster_import_auto_authorise,
      'contract_override',case when p_contract_id is null then null
        else v_contract.healthroster_import_auto_authorise_override end
    ),
    'nhsp_import_auto_authorise',jsonb_build_object(
      'global',v_defaults.nhsp_import_auto_authorise_default,
      'client',v_client.nhsp_import_auto_authorise,
      'contract_override',case when p_contract_id is null then null
        else v_contract.nhsp_import_auto_authorise_override end
    ),
    'candidate_electronic_auto_authorise',jsonb_build_object(
      'global',v_defaults.candidate_electronic_auto_authorise_default,
      'client',v_client.candidate_electronic_auto_authorise,
      'contract_override',case when p_contract_id is null then null
        else v_contract.candidate_electronic_auto_authorise_override end
    )
  );
  v_applicability:=jsonb_build_object(
    'configuration_valid',v_configuration_valid,
    'configuration_issue',v_configuration_issue,
    'import_authoritative',v_import_authoritative,
    'candidate_hours_view_only',v_import_authoritative,
    'candidate_expense_only_carrier_required',v_import_authoritative,
    'candidate_paper_timesheet',v_configuration_valid and not v_import_authoritative and v_workflow<>'DAILY',
    'timesheet_break_entry',v_configuration_valid and not v_import_authoritative and v_workflow<>'IMPORT',
    'invoice_settings',true,
    'finance_settings',true
  );
  v_payload:=jsonb_build_object(
    'authority_version','CONTRACT_SETTINGS_AUTHORITY_V1',
    'client_id',v_client_id,
    'contract_id',p_contract_id,
    'timesheet_id',p_timesheet_id,
    'relevant_date',p_relevant_date,
    'workflow',v_workflow,
    'client_settings_id',v_client.id,
    'client_settings_effective_from',v_client.effective_from,
    'client_settings_updated_at',v_client.updated_at,
    'global_settings_updated_at',v_defaults.updated_at,
    'finance_settings_id',nullif(v_finance->>'id','')::uuid,
    'finance_settings_date_from',nullif(v_finance->>'date_from','')::date,
    'contract_updated_at',case when p_contract_id is null then null else v_contract.updated_at end,
    'override_client_settings',v_override,
    'configured_route',v_route,
    'values',v_values,
    'sources',v_sources,
    'components',v_components,
    'applicability',v_applicability
  );
  v_fingerprint:=encode(digest(convert_to(v_payload::text,'UTF8'),'sha256'),'hex');
  return v_payload||jsonb_build_object(
    'authority_fingerprint',v_fingerprint,
    'resolved_at_utc',statement_timestamp()
  );
end
$function$;

alter function private._contract_settings_effective_core_v1(uuid,uuid,date,text,uuid) OWNER TO CURRENT_USER;
revoke all on function private._contract_settings_effective_core_v1(uuid,uuid,date,text,uuid)
  from public,anon,authenticated,service_role;

notify pgrst, 'reload schema';


-- CONTACT_PREPARER_UNIT 35 repeatable supabase/repeatable/06102026_1523_import_review_catalog_generic_plan_bound_v1.sql SHA256 e8168a094355971a81812034e221794448f1e18d7f12cb745641cc633865a880
-- Bound the Import Review classification plan without changing its decisions.
-- The preceding repository-derived PostgreSQL 17 definition is preserved in full.
-- Only classified AS MATERIALIZED changes: classify each bounded source row once,
-- then reuse those rows instead of expanding its lateral joins into downstream plans.
-- No timeout, plan-cache setting, source/pay/invoice policy or action limit changes.





CREATE OR REPLACE FUNCTION public._import_review_action_catalog_core_v1(p_import_id uuid, p_preview_generation integer, p_max_actions integer DEFAULT 5000)
 RETURNS TABLE(action_id text, action_kind text, action_category text, target_key text, source_identity text, hr_row_id uuid, timesheet_id uuid, shift_id uuid, client_id uuid, candidate_id uuid, contract_id uuid, issue_id uuid, evidence_fingerprint text, selectable boolean, default_selected boolean, blocking boolean, summary_json jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare v_count integer; v_weekly_preview jsonb;
begin
  if p_import_id is null or p_preview_generation<1 or p_max_actions<1 or p_max_actions>5000 then
    raise exception 'IMPORT_REVIEW_ACTION_CATALOG_INPUT_INVALID' using errcode='22023';
  end if;

  create temporary table if not exists pg_temp.import_review_catalog_v1 (
    action_id text, action_kind text, action_category text, target_key text, source_identity text,
    hr_row_id uuid, timesheet_id uuid, shift_id uuid, client_id uuid, candidate_id uuid,
    contract_id uuid, issue_id uuid, evidence_fingerprint text, selectable boolean,
    default_selected boolean, blocking boolean, summary_json jsonb
  ) on commit drop;
  truncate pg_temp.import_review_catalog_v1;

  if exists (
    select 1 from public.hr_imports hi
    where hi.id=p_import_id
      and upper(coalesce(hi.import_scope,''))='HR_DAILY'
      and coalesce((hi.parse_summary_json->>'declared_zero_shifts')::boolean,false)
  ) then
    select count(distinct t.timesheet_id) into v_count
    from public.hr_imports i
    join public.v_timesheets_daily_match t
      on (t.worked_start_iso at time zone 'Europe/London')::date
        between i.coverage_start_date and i.coverage_end_date
    join public.timesheets ts on ts.timesheet_id=t.timesheet_id
      and ts.is_current and ts.revoked_at is null
    where i.id=p_import_id
      and t.sheet_scope::text='DAILY'
      and (i.client_id is null or t.client_id=i.client_id)
      and (not exists(select 1 from public.import_review_scope_clients sc where sc.import_id=i.id)
        or exists(select 1 from public.import_review_scope_clients sc where sc.import_id=i.id and sc.client_id=t.client_id));
    if coalesce(v_count,0)>500 then
      raise exception 'DAILY_ZERO_DECLARATION_SCOPE_TOO_LARGE' using errcode='54000',
        detail=jsonb_build_object('supported_maximum',500,'target_count',v_count)::text;
    end if;
  end if;

  insert into pg_temp.import_review_catalog_v1
  with import_row as (
    select hi.* from public.hr_imports hi where hi.id=p_import_id
  ), raw as (
    select r.*, i.source_system::text as source_system, upper(coalesce(i.import_scope,'')) as import_scope,
      i.client_id as import_client_id,
      coalesce(nullif(r.staff_raw,''),nullif(r.payload_json->>'staff_name',''),nullif(r.staff_norm,'')) as staff_label,
      nullif(regexp_replace(lower(coalesce(nullif(r.staff_raw,''),r.payload_json->>'staff_name',r.staff_norm,'')),'[^a-z0-9]+','','g'),'') as staff_key,
      coalesce(nullif(r.payload_json->>'trust',''),nullif(r.payload_json->>'hospital_or_trust',''),nullif(r.unit_raw,''),nullif(r.unit_hint,'')) as client_label,
      nullif(regexp_replace(lower(coalesce(nullif(r.payload_json->>'trust',''),nullif(r.payload_json->>'hospital_or_trust',''),r.unit_raw,r.unit_hint,'')),'[^a-z0-9]+','','g'),'') as client_key,
      lower(btrim(coalesce(nullif(r.assignment_grade_norm,''),r.payload_json->>'grade_raw',r.payload_json->>'Request_Grade',''))) as grade_key,
      coalesce(nullif(r.external_row_key,''),'hr-row:'||r.id::text) as source_row_key
    from public.hr_rows r join import_row i on true where r.import_id=p_import_id
    order by r.id limit 501
  ), mapped as (
    select raw.*,
      coalesce(c_alias.id,c_map.candidate_id,c_exact.candidate_id) as resolved_candidate_id,
      coalesce(raw.import_client_id,ch.client_id,c_client.client_id) as resolved_client_id
    from raw
    left join lateral (
      select c.id from public.candidates c
      where c.nhsp_hr_name_aliases is not null and raw.staff_key is not null
        and c.nhsp_hr_name_aliases @> to_jsonb(array[raw.staff_key]::text[])
      order by c.id limit 1
    ) c_alias on true
    left join lateral (
      select hm.candidate_id from public.hr_name_mappings hm
      where hm.active and hm.hr_name_norm in (lower(btrim(coalesce(raw.staff_label,''))),raw.staff_key)
      order by hm.created_at desc,hm.id limit 1
    ) c_map on c_alias.id is null
    left join lateral (
      select case when count(*)=1 then (array_agg(c.id order by c.id))[1] end as candidate_id
      from public.candidates c where c.active and raw.staff_key is not null
        and (regexp_replace(lower(coalesce(c.first_name,'')||coalesce(c.last_name,'')),'[^a-z0-9]+','','g')=raw.staff_key
          or regexp_replace(lower(coalesce(c.last_name,'')||coalesce(c.first_name,'')),'[^a-z0-9]+','','g')=raw.staff_key)
    ) c_exact on c_alias.id is null and c_map.candidate_id is null
    left join lateral (
      select ch.client_id from public.client_hospitals ch
      where raw.client_key is not null and ch.hospital_name_norm @> to_jsonb(array[raw.client_key]::text[])
      order by ch.id limit 1
    ) ch on raw.import_client_id is null
    left join lateral (
      select case when count(*)=1 then (array_agg(c.id order by c.id))[1] end as client_id
      from public.clients c where raw.client_key is not null
        and regexp_replace(lower(coalesce(c.name,'')),'[^a-z0-9]+','','g')=raw.client_key
    ) c_client on raw.import_client_id is null and ch.client_id is null
  ), weekly_phase as materialized (
    -- weekly_import_phase2 remains the single authority for assignment-code
    -- mapping precedence and contract choice.  The review catalogue consumes
    -- its answer rather than maintaining a second resolver.
    select w.*
    from import_row i
    cross join lateral public.weekly_import_phase2(
      p_import_id,
      case when i.source_system='NHSP'::public.hr_source_enum then 'NHSP' else 'HR_WEEKLY' end
    ) w
    where not (upper(i.source_system::text)='HEALTHROSTER_DAILY'
      or upper(coalesce(i.import_scope,'')) like '%DAILY%')
  ), classified as materialized (
    select m.*,
      case when upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%'
        then case when rtsx.contract_id is not null then 1 else 0 end
        else con.contract_count end as contract_count,
      case when wp.hr_row_id is not null then wp.contract_id
        when upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%'
          then rtsx.contract_id
        else con.contract_id end as resolved_contract_id,
      wp.action as weekly_resolution_action,wp.reason as weekly_resolution_reason,
      wp.incoming_code as weekly_incoming_code,
      wp.week_ending_date as resolved_week_ending_date,
      wm.has_weekly_mapping,wm.mapping_evidence as weekly_mapping_evidence,
      dgm.mapping_count as daily_mapping_count,dgm.mapping_id as daily_mapping_id,
      dgm.role_code as daily_mapped_role,dgm.band_norm as daily_mapped_band,
      dgm.updated_at as daily_mapping_updated_at,(coalesce(dgm.mapping_count,0)=1) as has_grade_mapping,
      tsx.timesheet_count,tsx.timesheet_ids,tsx.auto_timesheet_id,tsx.timesheet_evidence_hash,
      dtsx.submitted_timesheet_count as daily_submitted_timesheet_count,
      dtsx.submitted_timesheet_evidence_hash as daily_submitted_timesheet_evidence_hash,
      tsx.timesheet_contract_ids,dcon.contract_ids as eligible_contract_ids,dcon.contract_evidence_hash,
      cr.route_eligible as contract_route_eligible,cr.rate_complete as contract_rate_complete,
      cr.import_authoritative,cr.authority_mode,cr.authority_fingerprint,
      cr.rate_evidence as contract_rate_evidence,
      wopts.options as weekly_contract_options,dopts.options as daily_role_options,
      res.resolved_timesheet_id as stored_timesheet_id,res.status as resolution_status,
      coalesce(case when res.resolved_timesheet_id=any(coalesce(tsx.timesheet_ids,array[]::uuid[])) then res.resolved_timesheet_id end,
        tsx.auto_timesheet_id) as resolved_timesheet_id,
      nss.id as existing_shift_id,nss.timesheet_id as existing_shift_timesheet_id,
      nss.start_utc as existing_shift_start_utc,nss.end_utc as existing_shift_end_utc,
      nss.break_mins as existing_shift_break_minutes,nss.pay_minutes as existing_shift_paid_minutes,
      nss.assignment_code as existing_shift_role,
      case when upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%' then true else false end as is_daily
    from mapped m
    left join weekly_phase wp on wp.hr_row_id=m.id
    left join lateral (
      select count(*)::integer contract_count,
             case when count(*)=1 then (array_agg(c.id order by c.id))[1] end contract_id
      from public.contracts c
      where c.candidate_id=m.resolved_candidate_id and c.client_id=m.resolved_client_id
        and c.start_date<=m.date_local and (c.end_date is null or c.end_date>=m.date_local)
    ) con on true
    left join lateral (
      select count(*)::integer mapping_count,
        (array_agg(gm.id order by gm.updated_at desc,gm.id))[1] mapping_id,
        (array_agg(gm.role_code order by gm.updated_at desc,gm.id))[1] role_code,
        (array_agg(gm.band_norm order by gm.updated_at desc,gm.id))[1] band_norm,
        (array_agg(gm.updated_at order by gm.updated_at desc,gm.id))[1] updated_at
      from public.hr_daily_grade_role_mappings gm
      where gm.client_id=m.resolved_client_id and gm.incoming_grade_norm=m.grade_key and gm.active
    ) dgm on upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%'
    left join lateral (
      select count(*)::integer contract_count,
        case when count(*)=1 then (array_agg(c.id order by c.id))[1] end contract_id,
        array_agg(c.id order by c.id) contract_ids,
        public._import_review_hash_v1(coalesce(string_agg(concat_ws('|',c.id,c.updated_at,c.role,c.band,a.authority_fingerprint),',' order by c.id),'')) contract_evidence_hash
      from public.contracts c
      cross join lateral public._import_review_effective_authority_core_v1('HR_DAILY',c.id,c.client_id,m.date_local) a
      where c.candidate_id=m.resolved_candidate_id and c.client_id=m.resolved_client_id
        and c.start_date<=m.date_local and (c.end_date is null or c.end_date>=m.date_local)
        and coalesce(dgm.mapping_count,0)=1 and a.route_eligible
        and lower(btrim(coalesce(c.role,'')))=lower(btrim(coalesce(dgm.role_code,'')))
        and (nullif(btrim(coalesce(dgm.band_norm,'')),'') is null
          or lower(btrim(coalesce(c.band,'')))=lower(btrim(dgm.band_norm)))
    ) dcon on upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%'
    left join lateral (
      select count(*)::integer submitted_timesheet_count,
        public._import_review_hash_v1(coalesce(string_agg(concat_ws('|',t.timesheet_id,t.worked_start_iso,
          t.worked_end_iso,t.break_minutes,t.worked_minutes,t.reference_number,t.processing_status,
          t.tsfin_role,t.tsfin_band,ts.contract_id,ts.updated_at),',' order by t.timesheet_id),''))
          submitted_timesheet_evidence_hash
      from public.v_timesheets_daily_match t
      join public.timesheets ts on ts.timesheet_id=t.timesheet_id and ts.is_current and ts.revoked_at is null
      where t.candidate_id=m.resolved_candidate_id and t.client_id=m.resolved_client_id
        and t.sheet_scope::text='DAILY'
        and (t.worked_start_iso at time zone 'Europe/London')::date=m.date_local
    ) dtsx on upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%'
    left join lateral (
      with candidates as (
        select abm.*,
          case when abm.candidate_id=m.resolved_candidate_id and abm.client_id=m.resolved_client_id then 3
            when abm.candidate_id=m.resolved_candidate_id and abm.client_id is null then 2
            when abm.candidate_id is null and abm.client_id=m.resolved_client_id then 1 else 0 end specificity
        from public.assignment_band_mappings abm
        where abm.active and upper(btrim(abm.system_type))=
          case when upper(m.source_system)='NHSP' then 'NHSP' else 'HR_WEEKLY' end
          and lower(btrim(abm.incoming_code))=m.grade_key
          and ((abm.candidate_id=m.resolved_candidate_id and abm.client_id=m.resolved_client_id)
            or (abm.candidate_id=m.resolved_candidate_id and abm.client_id is null)
            or (abm.candidate_id is null and abm.client_id=m.resolved_client_id)
            or (abm.candidate_id is null and abm.client_id is null))
      ), chosen as (select * from candidates where specificity=(select max(specificity) from candidates))
      select exists(select 1 from chosen) has_weekly_mapping,
        public._import_review_hash_v1(coalesce((select string_agg(concat_ws('|',id,updated_at,target_contract_id,band_match_pattern),',' order by id)
          from chosen),'')) mapping_evidence
    ) wm on not (upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%')
    left join lateral (
      select count(*)::integer timesheet_count,
             array_agg(t.timesheet_id order by t.worked_start_iso,t.timesheet_id) timesheet_ids,
             array_agg(ts.contract_id order by t.worked_start_iso,t.timesheet_id) timesheet_contract_ids,
             case when count(*)=1 then (array_agg(t.timesheet_id order by t.timesheet_id))[1] end auto_timesheet_id,
             public._import_review_hash_v1(coalesce(string_agg(concat_ws('|',t.timesheet_id,t.worked_start_iso,t.worked_end_iso,
               t.break_minutes,t.worked_minutes,t.reference_number,t.processing_status,t.tsfin_role,t.tsfin_band,
               ts.contract_id,ts.updated_at),',' order by t.timesheet_id),'')) timesheet_evidence_hash
      from public.v_timesheets_daily_match t
      join public.timesheets ts on ts.timesheet_id=t.timesheet_id and ts.is_current and ts.revoked_at is null
      where t.candidate_id=m.resolved_candidate_id and t.client_id=m.resolved_client_id
        and t.sheet_scope::text='DAILY'
        and (t.worked_start_iso at time zone 'Europe/London')::date=m.date_local
        and coalesce(dgm.mapping_count,0)=1
        and lower(btrim(coalesce(t.tsfin_role,'')))=lower(btrim(coalesce(dgm.role_code,'')))
        and (nullif(btrim(coalesce(dgm.band_norm,'')),'') is null
          or lower(btrim(coalesce(t.tsfin_band,'')))=lower(btrim(dgm.band_norm)))
    ) tsx on upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%'
    left join public.import_review_daily_timesheet_resolutions res
      on res.import_id=p_import_id and res.hr_row_id=m.id and res.status in ('CURRENT','APPLIED')
    left join lateral (
      select ts.contract_id
      from public.timesheets ts
      where ts.timesheet_id=coalesce(
        case when res.resolved_timesheet_id=any(coalesce(tsx.timesheet_ids,array[]::uuid[])) then res.resolved_timesheet_id end,
        tsx.auto_timesheet_id)
        and ts.is_current and ts.revoked_at is null
      order by ts.updated_at desc limit 1
    ) rtsx on upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%'
    left join lateral (
      select a.route_eligible,a.import_authoritative,a.authority_mode,a.authority_fingerprint,
        (jsonb_typeof(c.rates_json)='object'
          and upper(coalesce(c.pay_method_snapshot,'')) in ('PAYE','UMBRELLA')
          and case when upper(c.pay_method_snapshot)='PAYE' then
            (c.rates_json->>'paye_day')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'paye_night')~'^-?[0-9]+([.][0-9]+)?$'
            and (c.rates_json->>'paye_sat')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'paye_sun')~'^-?[0-9]+([.][0-9]+)?$'
            and (c.rates_json->>'paye_bh')~'^-?[0-9]+([.][0-9]+)?$'
          else
            (c.rates_json->>'umb_day')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'umb_night')~'^-?[0-9]+([.][0-9]+)?$'
            and (c.rates_json->>'umb_sat')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'umb_sun')~'^-?[0-9]+([.][0-9]+)?$'
            and (c.rates_json->>'umb_bh')~'^-?[0-9]+([.][0-9]+)?$' end
          and (c.rates_json->>'charge_day')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'charge_night')~'^-?[0-9]+([.][0-9]+)?$'
          and (c.rates_json->>'charge_sat')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'charge_sun')~'^-?[0-9]+([.][0-9]+)?$'
          and (c.rates_json->>'charge_bh')~'^-?[0-9]+([.][0-9]+)?$') rate_complete,
        public._import_review_hash_v1(concat_ws('|',c.id,c.updated_at,c.start_date,c.end_date,c.role,c.band,
          c.pay_method_snapshot,c.rates_json,c.overrideclientsettings,c.is_nhsp,c.autoprocess_hr,c.requires_hr,
          c.no_timesheet_required,a.client_settings_id,a.client_settings_updated_at,
          a.effective_is_nhsp,a.effective_autoprocess_hr,a.effective_requires_hr,
          a.effective_no_timesheet_required,a.authority_fingerprint)) rate_evidence
      from public.contracts c
      cross join lateral public._import_review_effective_authority_core_v1(
        case when upper(m.source_system)='NHSP' then 'NHSP'
          when upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%' then 'HR_DAILY'
          else 'HR_WEEKLY' end,c.id,c.client_id,coalesce(wp.week_ending_date,m.date_local)) a
      where c.id=case when wp.hr_row_id is not null then wp.contract_id
        when upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%'
          then rtsx.contract_id
        else con.contract_id end
    ) cr on true
    left join lateral (
      select coalesce(jsonb_agg(jsonb_build_object(
        'option_id','contract:'||o.id::text,'contract_id',o.id,'candidate_id',o.candidate_id,'client_id',o.client_id,
        'role',o.role,'band',o.band,'site',o.display_site,'start_date',o.start_date,'end_date',o.end_date,
        'source_route_eligible',coalesce(o.route_eligible,false),'rate_complete',coalesce(o.rate_complete,false),
        'authority_mode',o.authority_mode,
        -- Choosing a contract records the server-approved assignment mapping;
        -- it does not apply the import or grant financial authority.  An
        -- authoritative contract with incomplete rates must therefore remain
        -- selectable here and will still be blocked by the refreshed action
        -- catalogue before final application.
        'selectable',coalesce(o.route_eligible,false),
        'disabled_reason_code',case when not coalesce(o.route_eligible,false) then 'CONTRACT_NOT_ELIGIBLE' end,
        'display_label',concat_ws(' · ',nullif(o.role,''),nullif(o.band,''),nullif(o.display_site,''),
          to_char(o.start_date,'DD Mon YYYY')||' to '||coalesce(to_char(o.end_date,'DD Mon YYYY'),'open ended'))
      ) order by lower(coalesce(o.role,'')),lower(coalesce(o.band,'')),o.start_date desc,o.id),'[]'::jsonb) options
      from (
        select c.*,a.route_eligible,a.import_authoritative,a.authority_mode,
          (jsonb_typeof(c.rates_json)='object'
          and upper(coalesce(c.pay_method_snapshot,'')) in ('PAYE','UMBRELLA')
          and case when upper(c.pay_method_snapshot)='PAYE' then
            (c.rates_json->>'paye_day')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'paye_night')~'^-?[0-9]+([.][0-9]+)?$'
            and (c.rates_json->>'paye_sat')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'paye_sun')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'paye_bh')~'^-?[0-9]+([.][0-9]+)?$'
          else (c.rates_json->>'umb_day')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'umb_night')~'^-?[0-9]+([.][0-9]+)?$'
            and (c.rates_json->>'umb_sat')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'umb_sun')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'umb_bh')~'^-?[0-9]+([.][0-9]+)?$' end
          and (c.rates_json->>'charge_day')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'charge_night')~'^-?[0-9]+([.][0-9]+)?$'
          and (c.rates_json->>'charge_sat')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'charge_sun')~'^-?[0-9]+([.][0-9]+)?$' and (c.rates_json->>'charge_bh')~'^-?[0-9]+([.][0-9]+)?$') rate_complete
        from public.contracts c
        cross join lateral public._import_review_effective_authority_core_v1(
          case when upper(m.source_system)='NHSP' then 'NHSP' else 'HR_WEEKLY' end,
          c.id,c.client_id,coalesce(wp.week_ending_date,m.date_local)) a
        where c.candidate_id=m.resolved_candidate_id and c.client_id=m.resolved_client_id
          and c.start_date<=m.date_local and (c.end_date is null or c.end_date>=m.date_local)
        order by c.start_date desc,c.id limit 25
      ) o
    ) wopts on not (upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%')
    left join lateral (
      select coalesce(jsonb_agg(jsonb_build_object(
        'option_id','daily-role:'||public._import_review_hash_v1(lower(concat_ws('|',o.role,o.band))),
        'role_code',o.role,'band_norm',o.band,'selectable',true,
        'display_label',concat_ws(' · ',nullif(o.role,''),coalesce(nullif(o.band,''),'No band'))
      ) order by lower(o.role),lower(coalesce(o.band,''))),'[]'::jsonb) options
      from (
        select distinct t.tsfin_role role,t.tsfin_band band
        from public.v_timesheets_daily_match t
        where t.candidate_id=m.resolved_candidate_id
          and t.client_id=m.resolved_client_id
          and t.sheet_scope::text='DAILY'
          and (t.worked_start_iso at time zone 'Europe/London')::date=m.date_local
          and nullif(btrim(t.tsfin_role),'') is not null
        order by t.tsfin_role,t.tsfin_band
        limit 25
      ) o
    ) dopts on upper(m.source_system)='HEALTHROSTER_DAILY' or m.import_scope like '%DAILY%'
    left join public.nhsp_shifts nss
      on nss.external_row_key=m.source_row_key and nss.source_system::text=m.source_system
      and nss.cancelled_at_utc is null
  ), facts as (
    select c.*,
      ts.worked_start_iso,ts.worked_end_iso,ts.break_minutes as ts_break_minutes,ts.worked_minutes,
      ts.reference_number,ts.processing_status::text,ts.tsfin_role,ts.tsfin_band,
      coalesce(c.existing_shift_timesheet_id,base_week.timesheet_id) as authoritative_target_timesheet_id,
      public._import_review_timesheet_has_calculated_expenses_core_v1(
        coalesce(c.existing_shift_timesheet_id,base_week.timesheet_id)
      ) as authoritative_timesheet_has_calculated_expenses,
      mutable_replacement.timesheet_id as mutable_replacement_timesheet_id,
      mutable_replacement.protection as mutable_replacement_protection,
      source_timesheet.authorised_at_server as source_authorised_at_server,
      source_tf.authorised_at_utc as source_tsfin_authorised_at_utc,
      source_tf.policy_snapshot_json as source_policy_snapshot_json,
      source_tf.basis::text as source_tsfin_basis,
      authoritative_hours.hours_day as authoritative_hours_day,
      authoritative_hours.hours_night as authoritative_hours_night,
      authoritative_hours.hours_sat as authoritative_hours_sat,
      authoritative_hours.hours_sun as authoritative_hours_sun,
      authoritative_hours.hours_bh as authoritative_hours_bh,
      authoritative_hours.total_hours as authoritative_total_hours,
      coalesce((auto_authorise.value->>'effective_value')::boolean,false) as effective_auto_authorise,
      public._import_review_timesheet_protection_core_v1(coalesce(
        c.resolved_timesheet_id,c.existing_shift_timesheet_id,base_week.timesheet_id
      )) as protection
    from classified c
    left join public.v_timesheets_daily_match ts on ts.timesheet_id=c.resolved_timesheet_id
    left join lateral (
      select cw.timesheet_id
      from public.contract_weeks cw
      where not c.is_daily
        and coalesce(c.import_authoritative,false)
        and cw.contract_id=c.resolved_contract_id
        and cw.week_ending_date=coalesce(
          c.resolved_week_ending_date,
          c.date_local + ((7-extract(dow from c.date_local)::integer)%7)
        )
        and cw.is_adjustment=false
        and coalesce(cw.additional_seq,0)=0
      order by cw.id
      limit 1
    ) base_week on true
    left join public.timesheets source_timesheet
      on source_timesheet.timesheet_id=coalesce(c.existing_shift_timesheet_id,base_week.timesheet_id)
    left join public.timesheets_financials source_tf
      on source_tf.timesheet_id=source_timesheet.timesheet_id and source_tf.is_current=true
    left join lateral public._wkimp_bucket_hours_from_policy(
      coalesce(source_tf.policy_snapshot_json,'{}'::jsonb),
      (c.payload_json->>'start_utc')::timestamptz,
      (c.payload_json->>'end_utc')::timestamptz,
      coalesce((c.payload_json->>'actual_break_mins')::integer,
        (c.payload_json->>'actual_break_minutes')::integer,
        (c.payload_json->>'break_mins')::integer,
        (c.payload_json->>'break_minutes')::integer,0)
    ) authoritative_hours on not c.is_daily and coalesce(c.import_authoritative,false)
      and c.existing_shift_id is not null
    left join lateral (
      select case
        when not c.is_daily
          and coalesce(c.import_authoritative,false)
          and c.resolved_client_id is not null
          and c.resolved_contract_id is not null
        then public.import_auto_authorise_policy_resolve_v2(
          case when upper(c.source_system)='NHSP' then 'NHSP'::public.hr_source_enum else 'HEALTHROSTER'::public.hr_source_enum end,
          c.resolved_client_id,c.resolved_contract_id,source_timesheet.timesheet_id,c.date_local,false
        )
        else null::jsonb
      end as value
    ) auto_authorise on true
    left join lateral (
      select replacement_candidate.timesheet_id,replacement_candidate.protection
      from (
        select
          replacement_timesheet.timesheet_id,
          replacement_timesheet.updated_at,
          replacement_timesheet.created_at,
          public._import_review_timesheet_protection_core_v1(
            replacement_timesheet.timesheet_id
          ) as protection
        from public.timesheets replacement_timesheet
        where not c.is_daily
          and c.existing_shift_id is not null
          and replacement_timesheet.is_adjustment is true
          and replacement_timesheet.is_current is true
          and replacement_timesheet.correction_kind='CHANGED_HOURS_REPLACEMENT'
          and jsonb_typeof(replacement_timesheet.actual_schedule_json)='array'
          and replacement_timesheet.actual_schedule_json @> jsonb_build_array(
            jsonb_build_object(
              'shift_id',c.existing_shift_id::text,
              'external_row_key',c.source_row_key
            )
          )
      ) replacement_candidate
      where coalesce(
          (replacement_candidate.protection->>'paid')::boolean,
          false
        ) is false
        and coalesce(
          (replacement_candidate.protection->>'invoice_locked')::boolean,
          false
        ) is false
      order by
        replacement_candidate.updated_at desc nulls last,
        replacement_candidate.created_at desc nulls last
      limit 1
    ) mutable_replacement on true
  ), reconciliation_source_rows as (
    select
      f.*,
      ((row_number() over (order by f.source_row_key) - 1) / 100)::integer as reconciliation_batch
    from facts f
    where not f.is_daily and coalesce(f.import_authoritative,false) and f.existing_shift_id is not null
  ), reconciliation_inputs as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'source_identity',f.source_row_key,
      'source_system',case when upper(f.source_system)='NHSP' then 'NHSP' else 'HEALTHROSTER' end,
      'source_shift_id',f.existing_shift_id,
      'external_row_key',f.source_row_key,
      'hr_row_id',f.id,
      'source_timesheet_id',coalesce(f.existing_shift_timesheet_id,f.authoritative_target_timesheet_id),
      'candidate_id',f.resolved_candidate_id,'client_id',f.resolved_client_id,'contract_id',f.resolved_contract_id,
      'week_ending_date',coalesce(f.resolved_week_ending_date,f.date_local+((7-extract(dow from f.date_local)::integer)%7)),
      'invoice_stream',case when upper(coalesce(f.source_tsfin_basis,'')) in ('NHSP','NHSP_ADJUSTMENT','HEALTHROSTER_SELF_BILL','HEALTHROSTER_ADJUSTMENT') then 'SELF_BILL' else 'NORMAL' end,
      'authoritative_import_id',p_import_id,
      'authoritative_schedule_json',jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
        'date',f.date_local,'start_utc',f.payload_json->>'start_utc','end_utc',f.payload_json->>'end_utc',
        'break_mins',coalesce((f.payload_json->>'actual_break_mins')::integer,(f.payload_json->>'actual_break_minutes')::integer,
          (f.payload_json->>'break_mins')::integer,(f.payload_json->>'break_minutes')::integer,0),
        'shift_id',f.existing_shift_id,'external_row_key',f.source_row_key,'import_id',p_import_id,
        'ref_num',coalesce(f.hr_request_id,f.payload_json->>'ref_num',f.payload_json->>'reference_number')
      ))),
      'authoritative_hours',jsonb_build_object(
        'hours_day',coalesce(f.authoritative_hours_day,0),'hours_night',coalesce(f.authoritative_hours_night,0),
        'hours_sat',coalesce(f.authoritative_hours_sat,0),'hours_sun',coalesce(f.authoritative_hours_sun,0),
        'hours_bh',coalesce(f.authoritative_hours_bh,0),'total_hours',coalesce(f.authoritative_total_hours,f.hours_worked,0)
      )
    ) order by f.source_row_key),'[]'::jsonb) items
    from reconciliation_source_rows f
    group by f.reconciliation_batch
  ), reconciliation_balances as materialized (
    select b.source_identity,b.balance_json
    from reconciliation_inputs i
    cross join lateral public._import_review_effective_invoice_balance_core_v1(
      p_import_id,i.items,100,512,256,128
    ) b
  ), evidenced as (
    select c.*,
      rb.balance_json as reconciliation_balance,
      public._import_review_hash_v1(concat_ws('|','row-evidence-v1',c.source_row_key,c.staff_key,c.client_key,c.date_local,
        c.start_time_local,c.end_time_local,c.hours_worked,c.hr_request_id,c.resolved_candidate_id,c.resolved_client_id,
        c.resolved_contract_id,c.weekly_resolution_action,c.weekly_incoming_code,c.weekly_mapping_evidence,c.contract_rate_evidence,
        c.daily_mapping_id,c.daily_mapping_updated_at,c.daily_mapped_role,c.daily_mapped_band,
        c.timesheet_evidence_hash,c.daily_submitted_timesheet_evidence_hash,c.contract_evidence_hash,c.authority_fingerprint,
        c.authoritative_target_timesheet_id,c.authoritative_timesheet_has_calculated_expenses,
        c.mutable_replacement_timesheet_id,coalesce(c.mutable_replacement_protection::text,''),
        coalesce(c.eligible_contract_ids::text,''),coalesce(c.timesheet_ids::text,''),
        coalesce(c.timesheet_contract_ids::text,''),c.protection::text,coalesce(rb.balance_json::text,''),
        coalesce(c.payload_json::text,''))) as evidence_hash
    from facts c
    left join reconciliation_balances rb on rb.source_identity=c.source_row_key
  ), main_actions as (
    select
      case
        when f.resolved_candidate_id is null then 'ADVISORY'
        when f.resolved_client_id is null then 'ADVISORY'
        when f.is_daily and not coalesce(f.has_grade_mapping,false) then 'ADVISORY'
        when not f.is_daily and coalesce(f.weekly_resolution_action,'')<>'OK' then 'ADVISORY'
        when not f.is_daily and coalesce(f.contract_count,0)=0 then 'ADVISORY'
        when not f.is_daily and not coalesce(f.contract_route_eligible,false) then 'ADVISORY'
        when f.is_daily and coalesce(f.timesheet_count,0)=0 then 'ADVISORY'
        when f.is_daily and f.resolved_timesheet_id is null then 'DAILY_TIMESHEET_RESOLUTION'
        when f.is_daily then 'NO_ACTION'
        when not coalesce(f.import_authoritative,false) then 'NO_ACTION'
        when not coalesce(f.contract_rate_complete,false) then 'ADVISORY'
        when coalesce(f.authoritative_timesheet_has_calculated_expenses,false) then 'ADVISORY'
        when f.existing_shift_id is null then 'INCLUDE_SHIFT'
        when coalesce((f.reconciliation_balance->>'financial_position_requires_amendment')::boolean,false)
          then 'APPLY_AMENDMENT'
        when (f.payload_json->>'start_utc')::timestamptz is distinct from (select n.start_utc from public.nhsp_shifts n where n.id=f.existing_shift_id)
          or (f.payload_json->>'end_utc')::timestamptz is distinct from (select n.end_utc from public.nhsp_shifts n where n.id=f.existing_shift_id)
          or ((f.payload_json->>'break_mins') is not null
            and (f.payload_json->>'break_mins')::integer is distinct from
              coalesce((select n.break_mins from public.nhsp_shifts n where n.id=f.existing_shift_id),0))
          then 'APPLY_AMENDMENT'
        else 'NO_ACTION'
      end action_kind,
      f.*
    from evidenced f
  ), rendered as (
    select
      public._import_review_hash_v1(concat_ws('|','action-v1',p_import_id,m.action_kind,m.source_row_key)) action_id,
      m.action_kind,
      case when m.action_kind='ADVISORY'
             or nullif(m.reconciliation_balance->>'blocking_code','') is not null
             or coalesce((m.protection->>'active_pay_draft')::boolean,false) then 'BLOCKED'
           when m.action_kind='DAILY_TIMESHEET_RESOLUTION' then 'PENDING'
           when m.action_kind='NO_ACTION' then 'NO_ACTION' else 'READY' end action_category,
      'hr-row:'||m.id::text target_key,m.source_row_key source_identity,m.id hr_row_id,
      coalesce(m.resolved_timesheet_id,m.existing_shift_timesheet_id) timesheet_id,m.existing_shift_id shift_id,
      m.resolved_client_id client_id,m.resolved_candidate_id candidate_id,m.resolved_contract_id contract_id,
      null::uuid issue_id,m.evidence_hash evidence_fingerprint,
      (m.action_kind in ('INCLUDE_SHIFT','APPLY_AMENDMENT','NO_ACTION')
        and nullif(m.reconciliation_balance->>'blocking_code','') is null
        and not coalesce((m.protection->>'active_pay_draft')::boolean,false)) selectable,
      (m.action_kind in ('INCLUDE_SHIFT','APPLY_AMENDMENT','NO_ACTION')
        and nullif(m.reconciliation_balance->>'blocking_code','') is null
        and not coalesce((m.protection->>'active_pay_draft')::boolean,false)) default_selected,
      (m.action_kind in ('ADVISORY','DAILY_TIMESHEET_RESOLUTION')
        or nullif(m.reconciliation_balance->>'blocking_code','') is not null
        or coalesce((m.protection->>'active_pay_draft')::boolean,false)) blocking,
      jsonb_strip_nulls(jsonb_build_object(
        'reason_code',case
          when m.resolved_candidate_id is null then 'CANDIDATE_UNRESOLVED'
          when m.resolved_client_id is null then 'CLIENT_UNRESOLVED'
          when m.is_daily and not coalesce(m.has_grade_mapping,false) then 'GRADE_MAPPING_REQUIRED'
          when not m.is_daily and m.weekly_resolution_action='REJECT_NO_CONTRACT' then 'CONTRACT_MISSING'
          when not m.is_daily and m.weekly_resolution_action='REJECT_NO_CONTRACT_BAND_MISMATCH'
            and not coalesce(m.has_weekly_mapping,false) then 'GRADE_MAPPING_REQUIRED'
          when not m.is_daily and coalesce(m.weekly_resolution_action,'')<>'OK' then 'CONTRACT_OUT_OF_SCOPE'
          when not m.is_daily and coalesce(m.contract_count,0)=0 then 'CONTRACT_MISSING'
          when not m.is_daily and not coalesce(m.contract_route_eligible,false) then 'CONTRACT_OUT_OF_SCOPE'
          when not m.is_daily and coalesce(m.import_authoritative,false)
            and not coalesce(m.contract_rate_complete,false) then 'CONTRACT_RATES_INCOMPLETE'
          when not m.is_daily and coalesce(m.import_authoritative,false)
            and coalesce(m.authoritative_timesheet_has_calculated_expenses,false)
            then 'TIMESHEET_OCCUPIED_BY_EXPENSES'
          when m.is_daily and coalesce(m.timesheet_count,0)=0
            and coalesce(m.daily_submitted_timesheet_count,0)=0 then 'DAILY_TIMESHEET_NOT_SUBMITTED'
          when m.is_daily and coalesce(m.timesheet_count,0)=0 then 'DAILY_SHIFT_ABSENT_FROM_TIMESHEET'
          when m.is_daily and m.resolved_timesheet_id is null then 'TIMESHEET_AMBIGUOUS'
          when nullif(m.reconciliation_balance->>'blocking_code','') is not null
            then m.reconciliation_balance->>'blocking_code'
          when coalesce((m.protection->>'active_pay_draft')::boolean,false) then 'BLOCKED_ACTIVE_PAY_DRAFT'
          else null end,
        'source_system',m.source_system,'source_route',m.import_scope,'is_daily',m.is_daily,
        'existing_shift_id',m.existing_shift_id,
        'invoice_stream',m.reconciliation_balance->>'invoice_stream',
        'authority_mode',coalesce(m.authority_mode,case when m.is_daily or not coalesce(m.import_authoritative,false)
          then 'VALIDATION_ONLY' else 'AUTHORITATIVE' end),
        'authority_fingerprint',m.authority_fingerprint,
        'amendment_route',case
          when m.action_kind='APPLY_AMENDMENT'
            and coalesce((m.reconciliation_balance->>'active_mutable_generation')::boolean,false)
            then 'AMEND_EXISTING_REPLACEMENT'
          when m.action_kind='APPLY_AMENDMENT'
            and coalesce((m.reconciliation_balance->>'effective_hours_net_is_positive')::boolean,false)
            and coalesce((m.reconciliation_balance->>'B_standard_representable')::boolean,false)
            then 'CREATE_REVERSAL_REPLACEMENT'
          when m.action_kind='APPLY_AMENDMENT'
            and coalesce((m.protection->>'paid')::boolean,false)
            then 'AMEND_PAID_UNINVOICED_SOURCE'
          when m.action_kind='APPLY_AMENDMENT' then 'AMEND_SOURCE'
          else null
        end,
        'reconciliation_mode',case
          when m.action_kind='APPLY_AMENDMENT' and coalesce((m.reconciliation_balance#>>'{B_hours,total_hours}')::numeric,0)>0
            then 'FROZEN_INVOICE_BALANCE'
          when m.action_kind='APPLY_AMENDMENT' then 'ORDINARY_SOURCE'
          else null end,
        'mutable_replacement_timesheet_id',coalesce(
          (select x.value::uuid from jsonb_array_elements_text(coalesce(m.reconciliation_balance->'active_mutable_member_ids','[]'::jsonb)) x(value)
            join public.timesheets mutable_ts on mutable_ts.timesheet_id=x.value::uuid and mutable_ts.correction_kind='CHANGED_HOURS_REPLACEMENT' limit 1),
          m.mutable_replacement_timesheet_id),
        'correction_id',m.reconciliation_balance->>'active_mutable_correction_id',
        'reviewed_existing_correction_id',m.reconciliation_balance->>'reviewed_existing_correction_id',
        'repair_identity_mode',m.reconciliation_balance->>'repair_identity_mode',
        'physically_missing_mutable_roles',coalesce(m.reconciliation_balance->'physically_missing_mutable_roles','[]'::jsonb),
        'archived_ignored_roles',coalesce(m.reconciliation_balance->'archived_history_roles','[]'::jsonb),
        'reversal_repair_required',coalesce((m.reconciliation_balance->>'reversal_repair_required')::boolean,false),
        'replacement_repair_required',coalesce((m.reconciliation_balance->>'replacement_repair_required')::boolean,false),
        'correction_generation_required',coalesce((m.reconciliation_balance#>>'{B_hours,total_hours}')::numeric,0)>0
          and not coalesce((m.reconciliation_balance->>'active_mutable_generation')::boolean,false),
        'standard_representable',coalesce((m.reconciliation_balance->>'B_standard_representable')::boolean,true),
        'B_hours',m.reconciliation_balance->'B_hours','B_financials',m.reconciliation_balance->'B_financials',
        'B_standard_schedule_json',m.reconciliation_balance->'B_standard_schedule_json',
        'B_policy_fingerprint',m.reconciliation_balance->>'B_policy_fingerprint',
        'review_policy_basis_kind','IMPORT_AUTHORITATIVE_WEEKLY_V1',
        'review_policy_basis_fingerprint',public._import_review_hash_v1(concat_ws('|','review-policy-basis-v1',
          m.reconciliation_balance->>'source_scope_fingerprint',m.reconciliation_balance->>'effective_invoice_fingerprint',
          m.reconciliation_balance->>'role_evidence_fingerprint',m.authority_fingerprint,
          m.reconciliation_balance->>'B_policy_fingerprint',m.reconciliation_balance->>'invoice_stream')),
        'effective_invoice_ids',m.reconciliation_balance->'effective_invoice_ids',
        'effective_invoice_line_ids',m.reconciliation_balance->'effective_invoice_line_ids',
        'M_hours',m.reconciliation_balance->'M_hours','M_existing_financials',m.reconciliation_balance->'M_existing_financials',
        'A_hours',m.reconciliation_balance->'A_hours','A_schedule_json',m.reconciliation_balance->'A_schedule_json',
        'effective_invoice_fingerprint',m.reconciliation_balance->>'effective_invoice_fingerprint',
        'mutable_generation_fingerprint',m.reconciliation_balance->>'active_mutable_fingerprint',
        'authoritative_evidence_fingerprint',m.reconciliation_balance->>'A_evidence_fingerprint',
        'reconciliation_fingerprint',m.reconciliation_balance->>'reconciliation_fingerprint',
        'source_scope_fingerprint',m.reconciliation_balance->>'source_scope_fingerprint'
      ) || jsonb_build_object(
        'archived_timesheet_ids',m.reconciliation_balance->'archived_timesheet_ids',
        'archived_history_timesheet_ids',m.reconciliation_balance->'archived_history_timesheet_ids',
        'archived_history_roles',m.reconciliation_balance->'archived_history_roles',
        'historical_missing_timesheet_ids',m.reconciliation_balance->'historical_missing_timesheet_ids',
        'active_mutable_member_ids',m.reconciliation_balance->'active_mutable_member_ids',
        'missing_mutable_roles',m.reconciliation_balance->'active_mutable_missing_roles',
        'active_mutable_parent_timesheet_id',m.reconciliation_balance->>'active_mutable_parent_timesheet_id',
        'pre_apply_authorised',m.source_authorised_at_server is not null or m.source_tsfin_authorised_at_utc is not null,
        'effective_auto_authorise',m.effective_auto_authorise,
        'intended_authorisation_action',case
          when m.source_authorised_at_server is not null or m.source_tsfin_authorised_at_utc is not null then 'REAUTHORISE'
          when m.effective_auto_authorise then 'AUTHORISE' else 'LEAVE_UNAUTHORISED' end,
        'financial_validation_mode',case
          when m.action_kind='APPLY_AMENDMENT' and coalesce((m.reconciliation_balance#>>'{B_hours,total_hours}')::numeric,0)>0
            then 'CORRECTION_NEGATIVE_MUST_REVERSE_FROZEN_B_AND_POSITIVE_TSFIN_DEFINES_A'
          when m.action_kind='APPLY_AMENDMENT' then 'ORDINARY_TSFIN_DEFINES_A' end,
        'candidate_name',m.staff_label,'client_name',m.client_label,'work_date',m.date_local,
        'week_ending_date',m.date_local + ((7-extract(dow from m.date_local)::integer)%7),
        'start_time',m.start_time_local,'end_time',m.end_time_local,
        'break_minutes',coalesce((m.payload_json->>'actual_break_mins')::integer,(m.payload_json->>'actual_break_minutes')::integer,
          (m.payload_json->>'break_mins')::integer,(m.payload_json->>'break_minutes')::integer),
        'hours_worked',m.hours_worked,'role',coalesce(m.weekly_incoming_code,m.assignment_grade_norm),
        'imported_evidence',jsonb_strip_nulls(jsonb_build_object(
          'work_date',m.date_local,'start',m.start_time_local,'end',m.end_time_local,
          'break_minutes',coalesce((m.payload_json->>'actual_break_mins')::integer,(m.payload_json->>'actual_break_minutes')::integer,
            (m.payload_json->>'break_mins')::integer,(m.payload_json->>'break_minutes')::integer),
          'worked_hours',m.hours_worked,'worked_minutes',case when m.hours_worked is null then null else round(m.hours_worked*60) end,
          'reference',m.hr_request_id,'role',coalesce(m.weekly_incoming_code,m.assignment_grade_norm),'grade',m.grade_key)),
        'current_evidence',case when m.is_daily and m.resolved_timesheet_id is not null then jsonb_strip_nulls(jsonb_build_object(
          'work_date',(m.worked_start_iso at time zone 'Europe/London')::date,'start',m.worked_start_iso,'end',m.worked_end_iso,
          'break_minutes',m.ts_break_minutes,'elapsed_minutes',m.worked_minutes,
          'worked_minutes',greatest(m.worked_minutes-coalesce(m.ts_break_minutes,0),0),
          'worked_hours',round(greatest(m.worked_minutes-coalesce(m.ts_break_minutes,0),0)/60.0,2),
          'reference',m.reference_number,'role',m.tsfin_role,'band',m.tsfin_band,'timesheet_id',m.resolved_timesheet_id))
          when not m.is_daily and m.existing_shift_id is not null then jsonb_strip_nulls(jsonb_build_object(
          'work_date',m.date_local,'start',m.existing_shift_start_utc,'end',m.existing_shift_end_utc,
          'break_minutes',m.existing_shift_break_minutes,'worked_minutes',m.existing_shift_paid_minutes,
          'role',m.existing_shift_role,'timesheet_id',m.existing_shift_timesheet_id,'shift_id',m.existing_shift_id)) end,
        'difference_codes',to_jsonb(array_remove(array[
          case when m.existing_shift_id is null and not m.is_daily then 'NEW_SHIFT'::text end,
          case when m.is_daily and m.resolved_timesheet_id is null then 'TIMESHEET_SELECTION_REQUIRED'::text end,
          case when m.is_daily and m.resolved_timesheet_id is not null and m.start_time_local is distinct from
            (m.worked_start_iso at time zone 'Europe/London')::time then 'START_TIME'::text end,
          case when m.is_daily and m.resolved_timesheet_id is not null and m.end_time_local is distinct from
            (m.worked_end_iso at time zone 'Europe/London')::time then 'END_TIME'::text end,
          case when m.is_daily and m.resolved_timesheet_id is not null
            and coalesce((m.payload_json->>'break_evidence_supplied')::boolean,false)
            and (m.payload_json->>'break_mins')::integer is distinct from coalesce(m.ts_break_minutes,0)
            then 'BREAK_MINUTES'::text end,
          case when m.is_daily and m.resolved_timesheet_id is not null and m.hours_worked is not null
            and abs((m.hours_worked*60)-greatest(m.worked_minutes-coalesce(m.ts_break_minutes,0),0))>1
            then 'WORKED_HOURS'::text end,
          case when not m.is_daily and m.existing_shift_id is not null and m.start_time_local is distinct from
            (m.existing_shift_start_utc at time zone 'Europe/London')::time then 'START_TIME'::text end,
          case when not m.is_daily and m.existing_shift_id is not null and m.end_time_local is distinct from
            (m.existing_shift_end_utc at time zone 'Europe/London')::time then 'END_TIME'::text end,
          case when not m.is_daily and m.existing_shift_id is not null
            and coalesce((m.payload_json->>'break_evidence_supplied')::boolean,false)
            and (m.payload_json->>'break_mins')::integer is distinct from coalesce(m.existing_shift_break_minutes,0)
            then 'BREAK_MINUTES'::text end,
          case when not m.is_daily and m.existing_shift_id is not null and m.hours_worked is not null
            and abs((m.hours_worked*60)-m.existing_shift_paid_minutes)>1 then 'WORKED_HOURS'::text end,
          case when not m.is_daily and coalesce((m.reconciliation_balance->>'financial_position_requires_amendment')::boolean,false)
            then 'FINANCIAL_POSITION'::text end
        ],null)),
        'outcome_label',case
          when not m.is_daily and not coalesce(m.import_authoritative,false) then 'Validate candidate timesheet'
          when m.is_daily and coalesce(m.timesheet_count,0)=0
            and coalesce(m.daily_submitted_timesheet_count,0)=0 then 'Request timesheet from candidate'
          when m.is_daily and coalesce(m.timesheet_count,0)=0 then 'Candidate timesheet states they did not work this shift'
          when not m.is_daily and coalesce(m.authoritative_timesheet_has_calculated_expenses,false)
            then 'Timesheet occupied by expenses'
          when m.action_kind='INCLUDE_SHIFT' then 'TMS will add shift'
          when m.action_kind='APPLY_AMENDMENT'
            and coalesce((m.reconciliation_balance->>'active_mutable_generation')::boolean,false)
            then 'TMS will repair current correction generation'
          when m.action_kind='APPLY_AMENDMENT'
            and coalesce((m.reconciliation_balance#>>'{B_hours,total_hours}')::numeric,0)>0
            then 'TMS will create correction generation'
          when m.action_kind='APPLY_AMENDMENT' and coalesce((m.protection->>'paid')::boolean,false)
            then 'TMS will amend paid uninvoiced shift'
          when m.action_kind='APPLY_AMENDMENT' then 'TMS will amend shift'
          when m.action_kind='APPLY_CANCELLATION' then case when coalesce((m.protection->>'paid')::boolean,false)
            or coalesce((m.protection->>'invoice_locked')::boolean,false)
            then 'TMS will reverse shift' else 'TMS will cancel shift' end
          when m.action_kind='DAILY_TIMESHEET_RESOLUTION' then 'Choose existing timesheet' when m.action_kind='NO_ACTION' then 'No action required'
          else 'Resolve before continuing' end,
        'resolution_kind',case
          when m.resolved_candidate_id is null then 'CANDIDATE_LINK'
          when m.resolved_client_id is null then 'CLIENT_LINK'
          when m.is_daily and not coalesce(m.has_grade_mapping,false) then 'DAILY_GRADE_ROLE'
          when not m.is_daily and m.weekly_resolution_action='REJECT_NO_CONTRACT_BAND_MISMATCH'
            and not coalesce(m.has_weekly_mapping,false) then 'WEEKLY_ASSIGNMENT_CONTRACT'
          when m.is_daily and m.resolved_timesheet_id is null and coalesce(m.timesheet_count,0)>0 then 'DAILY_EXISTING_TIMESHEET' end,
        'resolution_options',case
          when m.is_daily and not coalesce(m.has_grade_mapping,false) then m.daily_role_options
          when not m.is_daily and m.weekly_resolution_action='REJECT_NO_CONTRACT_BAND_MISMATCH' then m.weekly_contract_options
          else '[]'::jsonb end,
        'mapping_evidence',case when m.is_daily then jsonb_strip_nulls(jsonb_build_object(
          'mapping_id',m.daily_mapping_id,'updated_at',m.daily_mapping_updated_at,'role',m.daily_mapped_role,'band',m.daily_mapped_band))
          else jsonb_strip_nulls(jsonb_build_object('mapping_fingerprint',m.weekly_mapping_evidence,
            'resolution_action',m.weekly_resolution_action,'resolution_reason',m.weekly_resolution_reason)) end,
        'timesheet_options',case when m.is_daily then to_jsonb(coalesce(m.timesheet_ids,array[]::uuid[])) else null end,
        'occupied_timesheet_id',case when coalesce(m.authoritative_timesheet_has_calculated_expenses,false)
          then m.authoritative_target_timesheet_id end,
        'protection',m.protection
      )) summary_json
    from main_actions m
  )
  select * from rendered;

  -- Daily mismatch/query actions are independent of the evidence association.
  insert into pg_temp.import_review_catalog_v1
  with r as (
    select h.*,d.resolved_timesheet_id as timesheet_id,t.candidate_id,t.client_id,t.worked_start_iso,t.worked_end_iso,
      t.break_minutes,t.worked_minutes,t.reference_number,t.processing_status::text,
      c.id contract_id,public._import_review_timesheet_protection_core_v1(d.resolved_timesheet_id) protection
    from public.hr_rows h
    join public.hr_imports i on i.id=h.import_id
    join public.import_review_daily_timesheet_resolutions d on d.import_id=h.import_id and d.hr_row_id=h.id and d.status in ('CURRENT','APPLIED')
    join public.v_timesheets_daily_match t on t.timesheet_id=d.resolved_timesheet_id
    left join public.contracts c on c.id=(select ts.contract_id from public.timesheets ts where ts.timesheet_id=t.timesheet_id)
    where h.import_id=p_import_id and (upper(i.source_system::text)='HEALTHROSTER_DAILY' or upper(coalesce(i.import_scope,'')) like '%DAILY%')
    order by h.id limit 501
  ), mismatch as (
    select r.*,
      case
        when r.hours_worked is not null and r.worked_minutes is not null
          and abs((r.hours_worked*60)-greatest(r.worked_minutes-coalesce(r.break_minutes,0),0))>1
          then 'ACTUAL_HOURS_MISMATCH'
        when r.start_time_local is distinct from (r.worked_start_iso at time zone 'Europe/London')::time then 'START_END_MISMATCH'
        when r.end_time_local is distinct from (r.worked_end_iso at time zone 'Europe/London')::time then 'START_END_MISMATCH'
        when coalesce((r.payload_json->>'break_evidence_supplied')::boolean,false)
          and (r.payload_json->>'break_mins')::integer is distinct from coalesce(r.break_minutes,0)
          then 'BREAK_MINUTES_MISMATCH'
      end reason_code
    from r
  ), issues as (
    select m.*,public._import_review_hash_v1(concat_ws('|','HEALTHROSTER_DAILY',m.reason_code,m.timesheet_id,m.hr_request_id,
      lower(coalesce(m.staff_norm,'')),m.date_local,m.start_time_local,m.end_time_local,m.hours_worked,m.worked_minutes)) issue_fingerprint,
      jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
        'comparison_key','hr-row:'||m.id::text,
        'work_date',m.date_local,
        'match_status',m.reason_code,
        'timesheet_start',to_char(m.worked_start_iso at time zone 'Europe/London','HH24:MI'),
        'timesheet_end',to_char(m.worked_end_iso at time zone 'Europe/London','HH24:MI'),
        'timesheet_break_mins',m.break_minutes,
        'healthroster_start',to_char(m.start_time_local,'HH24:MI'),
        'healthroster_end',to_char(m.end_time_local,'HH24:MI'),
        'healthroster_break_mins',case
          when coalesce((m.payload_json->>'break_evidence_supplied')::boolean,false)
            then nullif(m.payload_json->>'break_mins','')::integer end,
        'healthroster_unit',coalesce(nullif(m.payload_json->>'Unit',''),nullif(m.payload_json->>'unit',''),
          nullif(m.unit_raw,''),nullif(m.unit_hint,'')),
        'healthroster_hospital',coalesce(nullif(m.payload_json->>'hospital_or_trust',''),
          nullif(m.payload_json->>'trust','')),
        'healthroster_request_grade',coalesce(nullif(m.payload_json->>'Request Grade',''),
          nullif(m.payload_json->>'Request_Grade',''),nullif(m.payload_json->>'grade_raw',''),
          nullif(m.assignment_grade_norm,'')),
        'ref_before',m.reference_number,
        'ref_after',m.hr_request_id
      ))) email_comparisons,
      lower(btrim(case when coalesce(m.contract_id is not null and
        (select c.send_ts_queries_to_different_email from public.contracts c where c.id=m.contract_id),false)
        then (select c.ts_queries_alt_email_address from public.contracts c where c.id=m.contract_id)
        else (select c.ts_queries_email from public.clients c where c.id=m.client_id) end)) route_email
    from mismatch m where m.reason_code is not null
  )
  select
    public._import_review_hash_v1(concat_ws('|','action-v1',p_import_id,
      case when e.id is null then 'EMAIL_ISSUE' else 'EMAIL_REMINDER' end,i.issue_fingerprint)),
    case when e.id is null then 'EMAIL_ISSUE' else 'EMAIL_REMINDER' end,'EMAIL',
    'issue:'||i.issue_fingerprint,i.issue_fingerprint,i.id,i.timesheet_id,null::uuid,i.client_id,i.candidate_id,i.contract_id,e.id,
    public._import_review_hash_v1(concat_ws('|','issue-evidence-v2',i.issue_fingerprint,i.email_comparisons::text,i.protection::text,
      coalesce(e.delivery_history_status,'NEW'),coalesce(e.sent_count,0),
      case when coalesce(i.contract_id is not null and (select c.send_ts_queries_to_different_email from public.contracts c where c.id=i.contract_id),false)
        then (select concat_ws('|',c.updated_at,c.ts_queries_alt_email_address) from public.contracts c where c.id=i.contract_id)
        else (select concat_ws('|',c.rev,c.updated_at,c.ts_queries_email) from public.clients c where c.id=i.client_id) end)),
    not coalesce((i.protection->>'active_pay_draft')::boolean,false) and length(coalesce(i.route_email,'')) between 3 and 320 and position('@' in i.route_email)>1,
    e.id is null and not coalesce((i.protection->>'active_pay_draft')::boolean,false) and length(coalesce(i.route_email,'')) between 3 and 320 and position('@' in i.route_email)>1,
    false,
    jsonb_build_object('reason_code',i.reason_code,'issue_fingerprint',i.issue_fingerprint,'work_date',i.date_local,
      'candidate_name',i.staff_raw,'timesheet_id',i.timesheet_id,'recipient_scope_key',
      case when coalesce(i.contract_id is not null and (select c.send_ts_queries_to_different_email from public.contracts c where c.id=i.contract_id),false)
        then 'CONTRACT_OVERRIDE:'||i.contract_id::text else 'CLIENT_DEFAULT:'||i.client_id::text end,
      'recipient_route_fingerprint',case when coalesce(i.contract_id is not null and
        (select c.send_ts_queries_to_different_email from public.contracts c where c.id=i.contract_id),false)
        then (select public._import_review_hash_v1(concat_ws('|','query-route-v1','CONTRACT_OVERRIDE:'||c.id::text,
          lower(btrim(coalesce(c.ts_queries_alt_email_address,''))),c.updated_at)) from public.contracts c where c.id=i.contract_id)
        else (select public._import_review_hash_v1(concat_ws('|','query-route-v1','CLIENT_DEFAULT:'||c.id::text,
          lower(btrim(coalesce(c.ts_queries_email,''))),c.rev,c.updated_at)) from public.clients c where c.id=i.client_id) end,
      'delivery_history_status',coalesce(e.delivery_history_status,'NEW'),'sent_count',coalesce(e.sent_count,0),
      'comparisons',i.email_comparisons,
      'default_excluded_reason',case when e.id is not null then 'PREVIOUS_OR_LEGACY_HISTORY_REQUIRES_EXPLICIT_REMINDER'
        when length(coalesce(i.route_email,'')) not between 3 and 320 or position('@' in coalesce(i.route_email,''))<=1 then 'QUERY_RECIPIENT_EMAIL_MISSING_OR_INVALID'
        when coalesce((i.protection->>'active_pay_draft')::boolean,false) then 'BLOCKED_ACTIVE_PAY_DRAFT' end,
      'protection',i.protection)
  from issues i left join public.hr_issue_emails e on e.issue_fingerprint=i.issue_fingerprint;

  -- Weekly validation-only issues use the installed comparison engine, but
  -- normalise every user choice into the same server-owned decision catalogue.
  if exists(select 1 from public.hr_imports i where i.id=p_import_id
      and i.source_system='HEALTHROSTER'::public.hr_source_enum
      and upper(coalesce(i.import_scope,'HR_WEEKLY')) not like '%DAILY%') then
    v_weekly_preview:=public.hr_weekly_validation_preview(p_import_id);

    -- Validation-only Weekly evidence has two distinct, server-proven states.
    -- Neither state is an instruction to mutate CloudTMS financial records.
    insert into pg_temp.import_review_catalog_v1
    with preview_rows as (
      select r.value row_json,
        nullif(r.value->>'timesheet_id','')::uuid timesheet_id,
        nullif(r.value->>'client_id','')::uuid client_id,
        nullif(r.value->>'candidate_id','')::uuid candidate_id,
        nullif(r.value->>'contract_id','')::uuid contract_id
      from jsonb_array_elements(case when jsonb_typeof(v_weekly_preview->'rows')='array'
        then v_weekly_preview->'rows' else '[]'::jsonb end) r(value)
    ), eligible_validation_groups as (
      select d.candidate_id,d.summary_json->>'week_ending_date' week_ending_date
      from pg_temp.import_review_catalog_v1 d
      where d.candidate_id is not null
        and d.summary_json->>'source_route' not like '%DAILY%'
        and d.summary_json->>'authority_mode'='VALIDATION_ONLY'
      group by d.candidate_id,d.summary_json->>'week_ending_date'
      having bool_and(d.action_kind='NO_ACTION' and not d.blocking)
    ), missing_timesheets as (
      select p.row_json,p.timesheet_id,p.candidate_id,
        d.hr_row_id shift_hr_row_id,d.client_id shift_client_id,
        d.contract_id shift_contract_id,d.source_identity shift_source_identity,
        d.evidence_fingerprint shift_evidence_fingerprint,d.summary_json shift_summary_json,
        workflow.state workflow_state,
        workflow.worker_submitted_at_utc,
        workflow.manager_approved_at_utc,
        workflow.updated_at_utc workflow_updated_at_utc
      from preview_rows p
      join eligible_validation_groups g on g.candidate_id=p.candidate_id
        and g.week_ending_date=p.row_json->>'week_ending_date'
      join pg_temp.import_review_catalog_v1 d on d.candidate_id=p.candidate_id
        and d.summary_json->>'week_ending_date'=p.row_json->>'week_ending_date'
        and d.summary_json->>'source_route' not like '%DAILY%'
        and d.summary_json->>'authority_mode'='VALIDATION_ONLY'
        and d.action_kind='NO_ACTION' and not d.blocking
      left join lateral (
        select w.state,w.worker_submitted_at_utc,w.manager_approved_at_utc,w.updated_at_utc
        from public.candidate_submission_workflows w
        where w.candidate_id=p.candidate_id
          and w.contract_id=d.contract_id
          and w.week_ending_date=nullif(p.row_json->>'week_ending_date','')::date
          and w.scope='WEEKLY'
          and w.workflow_kind in ('CONTRACT_HOURS','CONTRACT_COMBINED')
          and w.state not in ('CANCELLED','EXPIRED','SUPERSEDED','REFUSED','REJECTED')
        order by w.generation desc,w.updated_at_utc desc,w.id desc
        limit 1
      ) workflow on true
      where p.row_json->>'overall_status'='MISSING_TIMESHEET'
    ), missing_timesheet_status as (
      select m.*,
        case
          when m.workflow_state in ('READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL')
            and m.manager_approved_at_utc is null
            then 'WEEKLY_TIMESHEET_AWAITING_MANAGER_APPROVAL'
          when m.workflow_state is null or m.workflow_state in ('CREATED','WORKER_DRAFT')
            then 'WEEKLY_TIMESHEET_NOT_SUBMITTED'
          else 'WEEKLY_TIMESHEET_COMPLETING'
        end missing_reason_code,
        case
          when m.workflow_state in ('READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL')
            and m.manager_approved_at_utc is null
            then 'MANAGER_APPROVAL_PENDING'
          when m.workflow_state is null or m.workflow_state in ('CREATED','WORKER_DRAFT')
            then 'TIMESHEET_NOT_SUBMITTED'
          else 'TIMESHEET_COMPLETION_PENDING'
        end missing_difference_code,
        case
          when m.workflow_state in ('READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL')
            and m.manager_approved_at_utc is null
            then 'Waiting for manager approval'
          when m.workflow_state is null or m.workflow_state in ('CREATED','WORKER_DRAFT')
            then 'Waiting for candidate to submit'
          else 'Waiting for completed timesheet'
        end missing_outcome_label
      from missing_timesheets m
    ), confirmed_exceptions as (
      select p.*,cx.value exception_json
      from preview_rows p
      cross join lateral jsonb_array_elements(coalesce(p.row_json->'confirmed_exceptions','[]'::jsonb)) cx(value)
      where p.timesheet_id is not null
    )
    select public._import_review_hash_v1(concat_ws('|','action-v1',p_import_id,
        m.missing_reason_code,m.shift_hr_row_id)),
      'ADVISORY','BLOCKED',
      concat_ws(':','weekly-timesheet-incomplete',m.shift_hr_row_id),
      m.shift_source_identity,
      m.shift_hr_row_id,null::uuid,null::uuid,m.shift_client_id,m.candidate_id,m.shift_contract_id,null::uuid,
      public._import_review_hash_v1(concat_ws('|','weekly-timesheet-incomplete-v3',
        m.shift_evidence_fingerprint,m.row_json::text,m.workflow_state,m.workflow_updated_at_utc)),
      false,false,true,
      jsonb_strip_nulls(m.shift_summary_json||jsonb_build_object(
        'reason_code',m.missing_reason_code,'source_route','HR_WEEKLY','authority_mode','VALIDATION_ONLY',
        'candidate_name',m.row_json->>'candidate_name','week_ending_date',m.row_json->>'week_ending_date',
        'candidate_workflow_state',m.workflow_state,
        'difference_codes',jsonb_build_array(m.missing_difference_code),
        'outcome_label',m.missing_outcome_label))
    from missing_timesheet_status m
    union all
    select public._import_review_hash_v1(concat_ws('|','action-v1',p_import_id,
        'WEEKLY_CANDIDATE_DID_NOT_WORK',c.exception_json->>'hr_row_id')),
      'NO_ACTION','NO_ACTION',
      concat_ws(':','weekly-candidate-did-not-work',c.exception_json->>'hr_row_id'),
      concat_ws('|',c.timesheet_id,c.exception_json->>'work_date',
        c.exception_json->>'healthroster_start',c.exception_json->>'healthroster_end'),
      nullif(c.exception_json->>'hr_row_id','')::uuid,c.timesheet_id,null::uuid,c.client_id,c.candidate_id,c.contract_id,null::uuid,
      c.exception_json->>'evidence_fingerprint',
      false,false,false,
      jsonb_build_object(
        'reason_code','CANDIDATE_DID_NOT_WORK_CONFIRMED','source_route','HR_WEEKLY','authority_mode','VALIDATION_ONLY',
        'resolution_kind','WEEKLY_CANDIDATE_DID_NOT_WORK',
        'candidate_name',c.row_json->>'candidate_name','week_ending_date',c.row_json->>'week_ending_date',
        'validation_total_shift_count',jsonb_array_length(coalesce(c.row_json->'comparisons','[]'::jsonb))
          + coalesce(nullif(c.row_json->>'confirmed_exception_count','')::integer,0),
        'confirmed_exception_count',coalesce(nullif(c.row_json->>'confirmed_exception_count','')::integer,0),
        'work_date',c.exception_json->>'work_date',
        'imported_evidence',jsonb_strip_nulls(jsonb_build_object(
          'work_date',c.exception_json->>'work_date','start',c.exception_json->>'healthroster_start',
          'end',c.exception_json->>'healthroster_end',
          'break_minutes',nullif(c.exception_json->>'healthroster_break_mins','')::integer,
          'reference',c.exception_json->>'reference')),
        'current_evidence',jsonb_build_object('timesheet_id',c.timesheet_id),
        'difference_codes',jsonb_build_array('CONFIRMED_EXCEPTION'),
        'outcome_label','Passed with confirmed exception')
    from confirmed_exceptions c;

    insert into pg_temp.import_review_catalog_v1
    with preview_rows as (
      select r.value row_json,
        nullif(r.value->>'timesheet_id','')::uuid timesheet_id,
        nullif(r.value->>'client_id','')::uuid client_id,
        nullif(r.value->>'candidate_id','')::uuid candidate_id,
        nullif(r.value->>'contract_id','')::uuid contract_id,
        nullif(r.value->>'issue_fingerprint','') issue_fingerprint
      from jsonb_array_elements(case when jsonb_typeof(v_weekly_preview->'rows')='array'
        then v_weekly_preview->'rows' else '[]'::jsonb end) r(value)
    ), email_filtered as (
      select p.*,
        coalesce((select jsonb_agg(cx.value||jsonb_strip_nulls(jsonb_build_object(
            'healthroster_unit',coalesce(nullif(hr.payload_json->>'Unit',''),nullif(hr.payload_json->>'unit',''),
              nullif(hr.unit_raw,''),nullif(hr.unit_hint,''),nullif(cx.value->>'location_after','')),
            'healthroster_hospital',coalesce(nullif(hr.payload_json->>'hospital_or_trust',''),
              nullif(hr.payload_json->>'trust','')),
            'healthroster_request_grade',coalesce(nullif(hr.payload_json->>'Request Grade',''),
              nullif(hr.payload_json->>'Request_Grade',''),nullif(hr.payload_json->>'grade_raw',''),
              nullif(hr.assignment_grade_norm,''))
          )) order by cx.value->>'work_date',cx.value->>'comparison_key')
          from jsonb_array_elements(coalesce(p.row_json->'comparisons','[]'::jsonb)) cx(value)
          left join public.hr_rows hr on hr.id=nullif(cx.value->>'hr_row_id','')::uuid
          where (
            coalesce(cx.value->>'match_status','MATCH') <> 'MATCH'
            or coalesce((cx.value->>'ref_changed')::boolean,false)
          )),'[]'::jsonb) email_comparisons,
        coalesce((select jsonb_agg(day_json.value order by day_json.value->>'date')
          from jsonb_array_elements(coalesce(p.row_json->'days','[]'::jsonb)) day_json(value)
          where exists (
            select 1
            from jsonb_array_elements(coalesce(p.row_json->'comparisons','[]'::jsonb)) cx(value)
            where cx.value->>'work_date'=day_json.value->>'date'
              and (
                coalesce(cx.value->>'match_status','MATCH') <> 'MATCH'
                or coalesce((cx.value->>'ref_changed')::boolean,false)
              )
          )),'[]'::jsonb) email_days,
        coalesce((select jsonb_agg(to_jsonb(fr.value))
          from jsonb_array_elements_text(coalesce(p.row_json->'failure_reasons','[]'::jsonb)) fr(value)),'[]'::jsonb) email_failure_reasons
      from preview_rows p
    ), routed as (
      select p.*,public._import_review_hash_v1(concat_ws('|','HEALTHROSTER_WEEKLY','validation-email-v2',
          p.timesheet_id,p.row_json->>'week_ending_date',p.email_comparisons::text)) email_issue_fingerprint,
        c.rev client_rev,c.updated_at client_updated_at,c.ts_queries_email,
        ct.send_ts_queries_to_different_email,ct.ts_queries_alt_email_address,ct.updated_at contract_updated_at,
        case when coalesce(ct.send_ts_queries_to_different_email,false)
          then 'CONTRACT_OVERRIDE:'||ct.id::text else 'CLIENT_DEFAULT:'||c.id::text end recipient_scope_key,
        case when coalesce(ct.send_ts_queries_to_different_email,false)
          then 'CONTRACT_OVERRIDE' else 'CLIENT_DEFAULT' end recipient_scope,
        lower(btrim(case when coalesce(ct.send_ts_queries_to_different_email,false)
          then ct.ts_queries_alt_email_address else c.ts_queries_email end)) recipient_email,
        public._import_review_timesheet_protection_core_v1(p.timesheet_id) protection,
        e.id issue_id,e.delivery_history_status,e.sent_count
      from email_filtered p
      join public.clients c on c.id=p.client_id
      left join public.contracts ct on ct.id=p.contract_id and ct.client_id=p.client_id
      left join public.hr_issue_emails e on e.issue_fingerprint=public._import_review_hash_v1(concat_ws('|',
        'HEALTHROSTER_WEEKLY','validation-email-v2',p.timesheet_id,p.row_json->>'week_ending_date',p.email_comparisons::text))
      where p.timesheet_id is not null and p.issue_fingerprint is not null
        and coalesce((p.row_json->>'has_mismatch')::boolean,false)
        and exists (
          select 1 from jsonb_array_elements(coalesce(p.row_json->'comparisons','[]'::jsonb)) cx(value)
          where coalesce(cx.value->>'match_status','MATCH') <> 'MATCH'
            or coalesce((cx.value->>'ref_changed')::boolean,false)
        )
    ), email_actions as (
      select r.*,
        public._import_review_hash_v1(concat_ws('|','query-route-v1',r.recipient_scope_key,r.recipient_email,
          case when r.recipient_scope='CONTRACT_OVERRIDE' then r.contract_updated_at::text
            else concat_ws('|',r.client_rev,r.client_updated_at) end)) route_fingerprint,
        length(coalesce(r.recipient_email,'')) between 3 and 320
          and r.recipient_email~* '^[A-Z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?(?:\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)+$' valid_email
      from routed r
    )
    select public._import_review_hash_v1(concat_ws('|','action-v1',p_import_id,
        case when a.issue_id is null then 'EMAIL_ISSUE' else 'EMAIL_REMINDER' end,a.email_issue_fingerprint)),
      case when a.issue_id is null then 'EMAIL_ISSUE' else 'EMAIL_REMINDER' end,
      case when coalesce((a.protection->>'active_pay_draft')::boolean,false) then 'BLOCKED' else 'EMAIL' end,
      'issue:'||a.email_issue_fingerprint,a.email_issue_fingerprint,null::uuid,a.timesheet_id,null::uuid,
      a.client_id,a.candidate_id,a.contract_id,a.issue_id,
      public._import_review_hash_v1(concat_ws('|','weekly-query-evidence-v2',a.timesheet_id,
        a.row_json->>'candidate_name',a.row_json->>'week_ending_date',
        a.email_comparisons::text,a.email_days::text,a.email_failure_reasons::text,a.protection::text,
        a.route_fingerprint,coalesce(a.delivery_history_status,'NEW'),coalesce(a.sent_count,0))),
      a.valid_email and not coalesce((a.protection->>'active_pay_draft')::boolean,false),
      a.issue_id is null and a.valid_email and not coalesce((a.protection->>'active_pay_draft')::boolean,false),
      coalesce((a.protection->>'active_pay_draft')::boolean,false),
      jsonb_build_object('reason_code','HEALTHROSTER_WEEKLY','issue_fingerprint',a.email_issue_fingerprint,
        'candidate_name',a.row_json->>'candidate_name','week_ending_date',a.row_json->>'week_ending_date',
        'validation_total_shift_count',jsonb_array_length(coalesce(a.row_json->'comparisons','[]'::jsonb))
          + coalesce(nullif(a.row_json->>'confirmed_exception_count','')::integer,0),
        'validation_difference_count',jsonb_array_length(a.email_comparisons),
      'failure_reasons',a.email_failure_reasons,
        'days',a.email_days,'comparisons',a.email_comparisons,
        'evidence_rows',coalesce((
          select jsonb_agg(jsonb_build_object(
            'imported_evidence',jsonb_strip_nulls(jsonb_build_object(
              'work_date',cx.value->>'work_date','start',cx.value->>'healthroster_start',
              'end',cx.value->>'healthroster_end','break_minutes',nullif(cx.value->>'healthroster_break_mins','')::integer,
              'worked_minutes',nullif(day_json.value->>'hr_minutes','')::integer,'reference',cx.value->>'ref_after')),
            'current_evidence',jsonb_strip_nulls(jsonb_build_object(
              'work_date',cx.value->>'work_date','start',cx.value->>'timesheet_start',
              'end',cx.value->>'timesheet_end','break_minutes',nullif(cx.value->>'timesheet_break_mins','')::integer,
              'worked_minutes',nullif(day_json.value->>'ts_minutes','')::integer,'reference',cx.value->>'ref_before')),
            'difference_codes',to_jsonb(array_remove(array[
              case when coalesce(cx.value->>'match_status','MATCH')<>'MATCH' then cx.value->>'match_status' end,
              case when coalesce((cx.value->>'ref_changed')::boolean,false) then 'REFERENCE' end,
              case when coalesce(day_json.value->>'day_status','OK')<>'OK' then 'WORKED_HOURS' end
            ],null))
          ) order by cx.value->>'work_date',cx.value->>'comparison_key')
          from jsonb_array_elements(a.email_comparisons) cx(value)
          left join lateral (select d.value from jsonb_array_elements(coalesce(a.row_json->'days','[]'::jsonb)) d(value)
            where d.value->>'date'=cx.value->>'work_date' limit 1) day_json on true
        ),'[]'::jsonb),
        'outcome_label',case when a.issue_id is null then 'Request amend shift' else 'Request amend shift reminder' end,
        'recipient_scope_key',a.recipient_scope_key,'recipient_route_fingerprint',a.route_fingerprint,
        'delivery_history_status',coalesce(a.delivery_history_status,'NEW'),'sent_count',coalesce(a.sent_count,0),
        'default_excluded_reason',case when a.issue_id is not null then 'PREVIOUS_OR_LEGACY_HISTORY_REQUIRES_EXPLICIT_REMINDER'
          when not a.valid_email then 'QUERY_RECIPIENT_EMAIL_MISSING_OR_INVALID'
          when coalesce((a.protection->>'active_pay_draft')::boolean,false) then 'BLOCKED_ACTIVE_PAY_DRAFT' end,
        'protection',a.protection)
    from email_actions a;

    insert into pg_temp.import_review_catalog_v1
    with preview_rows as (
      select r.value row_json,
        nullif(r.value->>'timesheet_id','')::uuid timesheet_id,
        nullif(r.value->>'client_id','')::uuid client_id,
        nullif(r.value->>'candidate_id','')::uuid candidate_id,
        nullif(r.value->>'contract_id','')::uuid contract_id
      from jsonb_array_elements(case when jsonb_typeof(v_weekly_preview->'rows')='array'
        then v_weekly_preview->'rows' else '[]'::jsonb end) r(value)
      where nullif(r.value->>'timesheet_id','') is not null
    ), invalidations as (
      select p.*,cx.value comparison_json,nullif(btrim(cx.value->>'comparison_key'),'') comparison_key,
        public._import_review_timesheet_protection_core_v1(p.timesheet_id) protection
      from preview_rows p
      cross join lateral jsonb_array_elements(coalesce(p.row_json->'comparisons','[]'::jsonb)) cx(value)
      where coalesce((cx.value->>'is_destructive_invalidation')::boolean,false)
        and exists(select 1 from public.hr_imports hi where hi.id=p_import_id
          and hi.coverage_mode in ('COMPLETE_ALL','COMPLETE_SELECTED_CANDIDATES'))
        and nullif(btrim(cx.value->>'comparison_key'),'') is not null
        and nullif(btrim(cx.value->>'ref_before'),'') is not null
    )
    select public._import_review_hash_v1(concat_ws('|','action-v1',p_import_id,'INVALIDATE_REFERENCE',i.timesheet_id,i.comparison_key)),
      'INVALIDATE_REFERENCE','PENDING','timesheet:'||i.timesheet_id::text||':'||i.comparison_key,
      i.comparison_key,null::uuid,i.timesheet_id,null::uuid,i.client_id,i.candidate_id,i.contract_id,null::uuid,
      public._import_review_hash_v1(concat_ws('|','weekly-reference-invalidation-v1',i.timesheet_id,i.comparison_json::text,i.protection::text)),
      not coalesce((i.protection->>'protected')::boolean,false),false,false,
      jsonb_build_object('reason_code','REFERENCE_ON_SHIFT_MISSING_OR_MISMATCHED_IN_COMPLETE_IMPORT',
        'candidate_name',i.row_json->>'candidate_name','week_ending_date',i.row_json->>'week_ending_date',
        'timesheet_id',i.timesheet_id,'comparison_key',i.comparison_key,'comparison',i.comparison_json,
        'protection',i.protection,'default_excluded_reason','REFERENCE_INVALIDATION_REQUIRES_EXPLICIT_SELECTION')
    from invalidations i;
  end if;

  -- Complete Daily coverage also exposes existing timesheets that are absent
  -- from the file.  Missing rows are query-email candidates; reference
  -- invalidation is a separate, explicit, default-off decision.
  insert into pg_temp.import_review_catalog_v1
  with i as (
    select * from public.hr_imports where id=p_import_id
  ), missing as (
    select t.*,ts.contract_id,c.first_name,c.last_name,cl.name as client_name,
      public._import_review_timesheet_protection_core_v1(t.timesheet_id) protection,
      lower(btrim(case when coalesce(ts.contract_id is not null and
        (select ct.send_ts_queries_to_different_email from public.contracts ct where ct.id=ts.contract_id),false)
        then (select ct.ts_queries_alt_email_address from public.contracts ct where ct.id=ts.contract_id)
        else cl.ts_queries_email end)) route_email,
      public._import_review_hash_v1(concat_ws('|','HEALTHROSTER_DAILY','MISSING_FROM_IMPORT',
        t.timesheet_id,t.candidate_id,t.client_id,(t.worked_start_iso at time zone 'Europe/London')::date,
        coalesce(t.reference_number,''))) issue_fingerprint
    from public.v_timesheets_daily_match t
    join public.timesheets ts on ts.timesheet_id=t.timesheet_id and ts.is_current and ts.revoked_at is null
    join public.candidates c on c.id=t.candidate_id
    join public.clients cl on cl.id=t.client_id
    join i on true
    where (upper(i.source_system::text)='HEALTHROSTER_DAILY' or upper(coalesce(i.import_scope,'')) like '%DAILY%')
      and i.coverage_mode in ('COMPLETE_ALL','COMPLETE_SELECTED_CANDIDATES')
      and (t.worked_start_iso at time zone 'Europe/London')::date between i.coverage_start_date and i.coverage_end_date
      and (i.client_id is null or t.client_id=i.client_id)
      and (not exists(select 1 from public.import_review_scope_clients sc where sc.import_id=i.id)
        or exists(select 1 from public.import_review_scope_clients sc where sc.import_id=i.id and sc.client_id=t.client_id))
      and (i.coverage_mode='COMPLETE_ALL' or exists(
        select 1 from public.import_review_scope_candidates sc where sc.import_id=i.id and sc.candidate_id=t.candidate_id))
      and not exists (
        select 1 from public.import_review_daily_timesheet_resolutions r
        where r.import_id=i.id and r.resolved_timesheet_id=t.timesheet_id and r.status in ('CURRENT','APPLIED')
      )
    order by t.timesheet_id limit 501
  )
  select
    public._import_review_hash_v1(concat_ws('|','action-v1',p_import_id,
      case when e.id is null then 'EMAIL_ISSUE' else 'EMAIL_REMINDER' end,m.issue_fingerprint)),
    case when e.id is null then 'EMAIL_ISSUE' else 'EMAIL_REMINDER' end,'EMAIL',
    'issue:'||m.issue_fingerprint,m.issue_fingerprint,null::uuid,m.timesheet_id,null::uuid,
    m.client_id,m.candidate_id,m.contract_id,e.id,
    public._import_review_hash_v1(concat_ws('|','missing-daily-email-v1',m.issue_fingerprint,m.protection::text,
      coalesce(e.delivery_history_status,'NEW'),coalesce(e.sent_count,0),
      case when coalesce(m.contract_id is not null and (select ct.send_ts_queries_to_different_email from public.contracts ct where ct.id=m.contract_id),false)
        then (select concat_ws('|',ct.updated_at,ct.ts_queries_alt_email_address) from public.contracts ct where ct.id=m.contract_id)
        else (select concat_ws('|',cl.rev,cl.updated_at,cl.ts_queries_email) from public.clients cl where cl.id=m.client_id) end)),
    not coalesce((m.protection->>'active_pay_draft')::boolean,false) and length(coalesce(m.route_email,'')) between 3 and 320 and position('@' in m.route_email)>1,
    e.id is null and not coalesce((m.protection->>'active_pay_draft')::boolean,false) and length(coalesce(m.route_email,'')) between 3 and 320 and position('@' in m.route_email)>1,false,
    jsonb_build_object('reason_code','MISSING_FROM_IMPORT','issue_fingerprint',m.issue_fingerprint,
      'work_date',(m.worked_start_iso at time zone 'Europe/London')::date,
      'week_ending_date',(m.worked_start_iso at time zone 'Europe/London')::date
        + ((7-extract(dow from (m.worked_start_iso at time zone 'Europe/London')::date)::integer)%7),
      'candidate_name',btrim(concat_ws(' ',m.first_name,m.last_name)),'client_name',m.client_name,
      'timesheet_id',m.timesheet_id,'reference_number',m.reference_number,
      'start_time',(m.worked_start_iso at time zone 'Europe/London')::time,
      'end_time',(m.worked_end_iso at time zone 'Europe/London')::time,
      'break_minutes',m.break_minutes,'role',m.tsfin_role,
      'recipient_scope_key',case when coalesce(m.contract_id is not null and
        (select ct.send_ts_queries_to_different_email from public.contracts ct where ct.id=m.contract_id),false)
        then 'CONTRACT_OVERRIDE:'||m.contract_id::text else 'CLIENT_DEFAULT:'||m.client_id::text end,
      'recipient_route_fingerprint',case when coalesce(m.contract_id is not null and
        (select ct.send_ts_queries_to_different_email from public.contracts ct where ct.id=m.contract_id),false)
        then (select public._import_review_hash_v1(concat_ws('|','query-route-v1','CONTRACT_OVERRIDE:'||ct.id::text,
          lower(btrim(coalesce(ct.ts_queries_alt_email_address,''))),ct.updated_at)) from public.contracts ct where ct.id=m.contract_id)
        else (select public._import_review_hash_v1(concat_ws('|','query-route-v1','CLIENT_DEFAULT:'||cl.id::text,
          lower(btrim(coalesce(cl.ts_queries_email,''))),cl.rev,cl.updated_at)) from public.clients cl where cl.id=m.client_id) end,
      'delivery_history_status',coalesce(e.delivery_history_status,'NEW'),'sent_count',coalesce(e.sent_count,0),
      'default_excluded_reason',case when e.id is not null then 'PREVIOUS_OR_LEGACY_HISTORY_REQUIRES_EXPLICIT_REMINDER'
        when length(coalesce(m.route_email,'')) not between 3 and 320 or position('@' in coalesce(m.route_email,''))<=1 then 'QUERY_RECIPIENT_EMAIL_MISSING_OR_INVALID'
        when coalesce((m.protection->>'active_pay_draft')::boolean,false) then 'BLOCKED_ACTIVE_PAY_DRAFT' end,
      'protection',m.protection)
  from missing m left join public.hr_issue_emails e on e.issue_fingerprint=m.issue_fingerprint;

  insert into pg_temp.import_review_catalog_v1
  with i as (select * from public.hr_imports where id=p_import_id), missing as (
    select t.*,ts.contract_id,public._import_review_timesheet_protection_core_v1(t.timesheet_id) protection
    from public.v_timesheets_daily_match t
    join public.timesheets ts on ts.timesheet_id=t.timesheet_id and ts.is_current and ts.revoked_at is null
    join i on true
    where (upper(i.source_system::text)='HEALTHROSTER_DAILY' or upper(coalesce(i.import_scope,'')) like '%DAILY%')
      and i.coverage_mode in ('COMPLETE_ALL','COMPLETE_SELECTED_CANDIDATES')
      and (t.worked_start_iso at time zone 'Europe/London')::date between i.coverage_start_date and i.coverage_end_date
      and (i.client_id is null or t.client_id=i.client_id)
      and (not exists(select 1 from public.import_review_scope_clients sc where sc.import_id=i.id)
        or exists(select 1 from public.import_review_scope_clients sc where sc.import_id=i.id and sc.client_id=t.client_id))
      and (i.coverage_mode='COMPLETE_ALL' or exists(
        select 1 from public.import_review_scope_candidates sc where sc.import_id=i.id and sc.candidate_id=t.candidate_id))
      and not exists(select 1 from public.import_review_daily_timesheet_resolutions r
        where r.import_id=i.id and r.resolved_timesheet_id=t.timesheet_id and r.status in ('CURRENT','APPLIED'))
    order by t.timesheet_id limit 501
  )
  select public._import_review_hash_v1(concat_ws('|','action-v1',p_import_id,'MARK_VALIDATION_ERROR',m.timesheet_id)),
    'MARK_VALIDATION_ERROR','READY','timesheet:'||m.timesheet_id::text,'missing-daily:'||m.timesheet_id::text,
    null::uuid,m.timesheet_id,null::uuid,m.client_id,m.candidate_id,m.contract_id,null::uuid,
    public._import_review_hash_v1(concat_ws('|','missing-daily-validation-v1',m.timesheet_id,m.worked_start_iso,
      m.worked_end_iso,m.break_minutes,m.worked_minutes,m.reference_number,m.protection::text)),
    not coalesce((m.protection->>'active_pay_draft')::boolean,false),
    not coalesce((m.protection->>'active_pay_draft')::boolean,false),
    coalesce((m.protection->>'active_pay_draft')::boolean,false),
    jsonb_build_object('reason_code',case when coalesce((m.protection->>'active_pay_draft')::boolean,false)
      then 'BLOCKED_ACTIVE_PAY_DRAFT' else 'MISSING_FROM_IMPORT' end,
      'work_date',(m.worked_start_iso at time zone 'Europe/London')::date,'timesheet_id',m.timesheet_id,
      'reference_number',m.reference_number,'start_time',(m.worked_start_iso at time zone 'Europe/London')::time,
      'end_time',(m.worked_end_iso at time zone 'Europe/London')::time,'break_minutes',m.break_minutes,
      'hours_worked',m.worked_minutes/60.0,'role',m.tsfin_role,'protection',m.protection)
  from missing m;

  insert into pg_temp.import_review_catalog_v1
  with i as (select * from public.hr_imports where id=p_import_id), missing as (
    select t.*,ts.contract_id,public._import_review_timesheet_protection_core_v1(t.timesheet_id) protection
    from public.v_timesheets_daily_match t
    join public.timesheets ts on ts.timesheet_id=t.timesheet_id and ts.is_current and ts.revoked_at is null
    join i on true
    where (upper(i.source_system::text)='HEALTHROSTER_DAILY' or upper(coalesce(i.import_scope,'')) like '%DAILY%')
      and i.coverage_mode in ('COMPLETE_ALL','COMPLETE_SELECTED_CANDIDATES')
      and nullif(btrim(t.reference_number),'') is not null
      and (t.worked_start_iso at time zone 'Europe/London')::date between i.coverage_start_date and i.coverage_end_date
      and (i.client_id is null or t.client_id=i.client_id)
      and (not exists(select 1 from public.import_review_scope_clients sc where sc.import_id=i.id)
        or exists(select 1 from public.import_review_scope_clients sc where sc.import_id=i.id and sc.client_id=t.client_id))
      and (i.coverage_mode='COMPLETE_ALL' or exists(
        select 1 from public.import_review_scope_candidates sc where sc.import_id=i.id and sc.candidate_id=t.candidate_id))
      and not exists (select 1 from public.import_review_daily_timesheet_resolutions r
        where r.import_id=i.id and r.resolved_timesheet_id=t.timesheet_id and r.status in ('CURRENT','APPLIED'))
    order by t.timesheet_id limit 501
  )
  select public._import_review_hash_v1(concat_ws('|','action-v1',p_import_id,'INVALIDATE_REFERENCE',m.timesheet_id)),
    'INVALIDATE_REFERENCE','PENDING','timesheet:'||m.timesheet_id::text,'missing-daily:'||m.timesheet_id::text,
    null::uuid,m.timesheet_id,null::uuid,m.client_id,m.candidate_id,m.contract_id,null::uuid,
    public._import_review_hash_v1(concat_ws('|','missing-daily-reference-v1',m.timesheet_id,m.reference_number,m.protection::text)),
    not coalesce((m.protection->>'protected')::boolean,false),false,false,
    jsonb_build_object('reason_code','REFERENCE_ON_SHIFT_MISSING_FROM_COMPLETE_IMPORT',
      'work_date',(m.worked_start_iso at time zone 'Europe/London')::date,'timesheet_id',m.timesheet_id,
      'reference_number',m.reference_number,'protection',m.protection,
      'default_excluded_reason','REFERENCE_INVALIDATION_REQUIRES_EXPLICIT_SELECTION')
  from missing m;

  -- Omitted existing shifts are proposed only inside immutable complete coverage.
  insert into pg_temp.import_review_catalog_v1
  with i as (select * from public.hr_imports where id=p_import_id), missing as (
    select s.*,public._import_review_timesheet_protection_core_v1(s.timesheet_id) protection
    from public.nhsp_shifts s
    join i on true
    cross join lateral public._import_review_effective_authority_core_v1(
      case when i.source_system='NHSP'::public.hr_source_enum then 'NHSP' else 'HR_WEEKLY' end,
      s.contract_id,s.client_id,coalesce(s.week_ending_date,s.work_date)) authority
    where i.coverage_mode in ('COMPLETE_ALL','COMPLETE_SELECTED_CANDIDATES')
      and s.source_system=i.source_system
      and authority.import_authoritative
      and s.cancelled_at_utc is null
      and s.work_date between i.coverage_start_date and i.coverage_end_date
      and (i.client_id is null or s.client_id=i.client_id)
      and (not exists(select 1 from public.import_review_scope_clients sc where sc.import_id=i.id)
        or exists(select 1 from public.import_review_scope_clients sc where sc.import_id=i.id and sc.client_id=s.client_id))
      and (i.coverage_mode='COMPLETE_ALL' or exists (
        select 1 from public.import_review_scope_candidates sc where sc.import_id=i.id and sc.candidate_id=s.candidate_id))
      and not exists (select 1 from public.hr_rows h where h.import_id=i.id and h.external_row_key=s.external_row_key)
    order by s.id limit 501
  )
  select public._import_review_hash_v1(concat_ws('|','action-v1',p_import_id,'APPLY_CANCELLATION',m.id)),
    'APPLY_CANCELLATION','READY','shift:'||m.id::text,m.external_row_key,null::uuid,m.timesheet_id,m.id,m.client_id,m.candidate_id,m.contract_id,null::uuid,
    public._import_review_hash_v1(concat_ws('|','missing-shift-v1',m.id,m.updated_at,m.timesheet_id,m.protection::text)),
    not coalesce((m.protection->>'active_pay_draft')::boolean,false),not coalesce((m.protection->>'active_pay_draft')::boolean,false),
    coalesce((m.protection->>'active_pay_draft')::boolean,false),
    jsonb_build_object('reason_code',case when coalesce((m.protection->>'active_pay_draft')::boolean,false) then 'BLOCKED_ACTIVE_PAY_DRAFT' else 'MISSING_FROM_COMPLETE_IMPORT' end,
      'work_date',m.work_date,'week_ending_date',m.week_ending_date,'candidate_id',m.candidate_id,'client_id',m.client_id,
      'start_time',m.start_utc,'end_time',m.end_utc,'break_minutes',m.break_mins,'role',m.assignment_code,'protection',m.protection)
  from missing m;

  -- Query emails can be committed only with one exact, complete, current
  -- timesheet PDF.  Invoice-linked validation records are never eligible for
  -- validation.  The same evidence fingerprint is frozen into the decision so
  -- document or invoice lifecycle movement makes a reviewed action stale.
  with evidence as materialized (
    select c.action_id,public._import_review_query_evidence_core_v1(c.timesheet_id) evidence_json
    from pg_temp.import_review_catalog_v1 c
    where c.timesheet_id is not null
      and (
        c.action_kind in ('EMAIL_ISSUE','EMAIL_REMINDER')
        or c.summary_json->>'authority_mode'='VALIDATION_ONLY'
        or coalesce(nullif(c.summary_json->>'is_daily','')::boolean,false)
      )
  )
  update pg_temp.import_review_catalog_v1 c
  set evidence_fingerprint=public._import_review_hash_v1(concat_ws('|','query-evidence-decision-v1',
        c.evidence_fingerprint,e.evidence_json->>'evidence_fingerprint')),
      action_category=case
        when c.action_kind in ('EMAIL_ISSUE','EMAIL_REMINDER')
          and nullif(e.evidence_json->>'reason_code','') is not null then 'PENDING'
        when (
          c.summary_json->>'authority_mode'='VALIDATION_ONLY'
          or coalesce(nullif(c.summary_json->>'is_daily','')::boolean,false)
        ) and e.evidence_json->>'reason_code'='TIMESHEET_PRESENT_BUT_INVOICED' then 'PENDING'
        else c.action_category end,
      selectable=case
        when c.action_kind in ('EMAIL_ISSUE','EMAIL_REMINDER')
          and nullif(e.evidence_json->>'reason_code','') is not null then false
        when (
          c.summary_json->>'authority_mode'='VALIDATION_ONLY'
          or coalesce(nullif(c.summary_json->>'is_daily','')::boolean,false)
        ) and e.evidence_json->>'reason_code'='TIMESHEET_PRESENT_BUT_INVOICED' then false
        else c.selectable end,
      default_selected=case
        when c.action_kind in ('EMAIL_ISSUE','EMAIL_REMINDER')
          and nullif(e.evidence_json->>'reason_code','') is not null then false
        when (
          c.summary_json->>'authority_mode'='VALIDATION_ONLY'
          or coalesce(nullif(c.summary_json->>'is_daily','')::boolean,false)
        ) and e.evidence_json->>'reason_code'='TIMESHEET_PRESENT_BUT_INVOICED' then false
        else c.default_selected end,
      blocking=case
        when c.action_kind in ('EMAIL_ISSUE','EMAIL_REMINDER')
          and nullif(e.evidence_json->>'reason_code','') is not null then true
        when (
          c.summary_json->>'authority_mode'='VALIDATION_ONLY'
          or coalesce(nullif(c.summary_json->>'is_daily','')::boolean,false)
        ) and e.evidence_json->>'reason_code'='TIMESHEET_PRESENT_BUT_INVOICED' then true
        else c.blocking end,
      summary_json=c.summary_json||jsonb_build_object(
        'attachment_evidence',e.evidence_json,
        'attachment_fingerprint',e.evidence_json->>'evidence_fingerprint'
      )||case
        when (
          c.action_kind in ('EMAIL_ISSUE','EMAIL_REMINDER')
          and nullif(e.evidence_json->>'reason_code','') is not null
        ) or (
          (
            c.summary_json->>'authority_mode'='VALIDATION_ONLY'
            or coalesce(nullif(c.summary_json->>'is_daily','')::boolean,false)
          ) and e.evidence_json->>'reason_code'='TIMESHEET_PRESENT_BUT_INVOICED'
        ) then jsonb_build_object(
          'reason_code',e.evidence_json->>'reason_code',
          'default_excluded_reason',e.evidence_json->>'reason_code',
          'outcome_label',case e.evidence_json->>'reason_code'
            when 'TIMESHEET_PRESENT_BUT_INVOICED' then 'Timesheet present but invoiced'
            when 'TIMESHEET_EVIDENCE_PREPARING' then 'Preparing timesheet evidence'
            else 'Timesheet evidence incomplete' end
        ) else '{}'::jsonb end
  from evidence e
  where e.action_id=c.action_id;

  -- An invoice-linked validation shift owns this blocker.  Do not also expose
  -- the aggregate query-email action as a second visual copy of the same
  -- shift.  Preserve any delivery history on the owning shift before removing
  -- only that redundant email row; genuine query emails remain untouched.
  update pg_temp.import_review_catalog_v1 owner_row
  set summary_json=owner_row.summary_json||jsonb_strip_nulls(jsonb_build_object(
        'delivery_history_status',email_row.summary_json->>'delivery_history_status',
        'sent_count',nullif(email_row.summary_json->>'sent_count','')::integer,
        'previously_queried',coalesce(nullif(email_row.summary_json->>'sent_count','')::integer,0)>0
      ))
  from pg_temp.import_review_catalog_v1 email_row
  where owner_row.timesheet_id=email_row.timesheet_id
    and owner_row.action_id<>email_row.action_id
    and owner_row.summary_json->>'authority_mode'='VALIDATION_ONLY'
    and owner_row.summary_json->>'reason_code'='TIMESHEET_PRESENT_BUT_INVOICED'
    and email_row.action_kind in ('EMAIL_ISSUE','EMAIL_REMINDER')
    and email_row.summary_json->>'reason_code'='TIMESHEET_PRESENT_BUT_INVOICED';

  delete from pg_temp.import_review_catalog_v1 email_row
  using pg_temp.import_review_catalog_v1 owner_row
  where email_row.timesheet_id=owner_row.timesheet_id
    and email_row.action_id<>owner_row.action_id
    and email_row.action_kind in ('EMAIL_ISSUE','EMAIL_REMINDER')
    and email_row.summary_json->>'reason_code'='TIMESHEET_PRESENT_BUT_INVOICED'
    and owner_row.summary_json->>'authority_mode'='VALIDATION_ONLY'
    and owner_row.summary_json->>'reason_code'='TIMESHEET_PRESENT_BUT_INVOICED';

  -- Daily validation is atomic per Daily timesheet.  An email, document hold
  -- or invoice blocker for that record prevents only that record from entering
  -- validation and TSFIN work.
  update pg_temp.import_review_catalog_v1 current_row
  set selectable=false,
      default_selected=false,
      evidence_fingerprint=public._import_review_hash_v1(concat_ws('|','daily-validation-held-v1',
        current_row.evidence_fingerprint,current_row.timesheet_id)),
      summary_json=current_row.summary_json||jsonb_build_object(
        'daily_validation_held',true,
        'validation_hold_label','Validation held: resolve this Daily timesheet first'
      )
  where current_row.action_kind='NO_ACTION'
    and coalesce(nullif(current_row.summary_json->>'is_daily','')::boolean,false)
    and current_row.timesheet_id is not null
    and exists (
      select 1 from pg_temp.import_review_catalog_v1 hold
      where hold.timesheet_id=current_row.timesheet_id
        and hold.action_id<>current_row.action_id
        and (hold.blocking or hold.action_category in ('EMAIL','PENDING','BLOCKED'))
    );

  -- Weekly validation is all-or-nothing per candidate/client/contract/week.
  -- One mismatch, unresolved exception, missing attachment or invoice blocker
  -- holds the whole Weekly timesheet while leaving the actual issue visible.
  update pg_temp.import_review_catalog_v1 current_row
  set selectable=false,
      default_selected=false,
      evidence_fingerprint=public._import_review_hash_v1(concat_ws('|','weekly-validation-held-v2',
        current_row.evidence_fingerprint,current_row.candidate_id,current_row.client_id,
        current_row.contract_id,current_row.summary_json->>'week_ending_date')),
      summary_json=current_row.summary_json||jsonb_build_object(
        'weekly_validation_held',true,
        'weekly_validation_badge_code','WEEKLY_VALIDATION_HELD',
        'weekly_validation_badge_label','Validation held: resolve outstanding shift',
        'validation_hold_label','Validation held: one or more shifts still require action'
      )
  where current_row.action_kind='NO_ACTION'
    and current_row.summary_json->>'authority_mode'='VALIDATION_ONLY'
    and current_row.summary_json->>'source_route' not like '%DAILY%'
    and exists (
      select 1 from pg_temp.import_review_catalog_v1 hold
      where hold.candidate_id=current_row.candidate_id
        and hold.client_id=current_row.client_id
        and hold.contract_id is not distinct from current_row.contract_id
        and hold.summary_json->>'week_ending_date'=current_row.summary_json->>'week_ending_date'
        and hold.action_id<>current_row.action_id
        and (hold.blocking or hold.action_category in ('EMAIL','PENDING','BLOCKED'))
    );

  select count(*) into v_count from pg_temp.import_review_catalog_v1;
  if v_count>p_max_actions then
    raise exception 'IMPORT_REVIEW_ACTION_LIMIT_EXCEEDED' using errcode='54000',
      detail=jsonb_build_object('count',v_count,'max',p_max_actions)::text;
  end if;

  return query select c.action_id,c.action_kind,c.action_category,c.target_key,c.source_identity,
    c.hr_row_id,c.timesheet_id,c.shift_id,c.client_id,c.candidate_id,c.contract_id,c.issue_id,
    c.evidence_fingerprint,c.selectable,c.default_selected,c.blocking,c.summary_json
  from pg_temp.import_review_catalog_v1 c order by c.action_id;
end
$function$
;

alter function public._import_review_action_catalog_core_v1(uuid,integer,integer) OWNER TO CURRENT_USER;
revoke all on function public._import_review_action_catalog_core_v1(uuid,integer,integer)
  from public,anon,authenticated,service_role;

notify pgrst, 'reload schema';


-- CONTACT_PREPARER_UNIT 36 repeatable supabase/repeatable/07102026_2215_weekly_source_same_file_recheck_recovery_v1.sql SHA256 d7dbef9a38c09d869cdd7a2e33a41975b33158918fa299cf8a757a0fc9fd4849
-- Repeatable CloudTMS function/view authority: weekly_source_same_file_recheck_recovery_v1
-- Use CREATE OR REPLACE and preserve owner, security, search_path, and ACL contracts.




create or replace function public.weekly_source_projection_rows_apply_atomic_v1(
  p_actor_user_id uuid,
  p_publication_id uuid,
  p_rows jsonb
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_publication public.weekly_source_projection_publications%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_row_json jsonb;
  v_source_row public.weekly_source_upload_rows%rowtype;
  v_contract public.contracts%rowtype;
  v_work_event public.weekly_work_events%rowtype;
  v_resolution_id uuid;
  v_work_event_id uuid;
  v_mapping_state text;
  v_selection_method text;
  v_candidate_id uuid;
  v_client_id uuid;
  v_contract_id uuid;
  v_prior_work_event_id uuid;
  v_identity_kind text;
  v_link_kind text;
  v_work_event_match_kind text;
  v_work_event_match_fingerprint bytea;
  v_work_event_was_present boolean;
  v_profile_external_key text;
  v_durable_identity_hash bytea;
  -- WP-37: the `24 §9` step-2 candidate set, counted explicitly.  Safety is
  -- never expressed through `limit`/`order by` here: anything other than
  -- exactly one compatible root takes a named branch.
  v_compatible_count integer;
  v_compatible_event_id uuid;
  v_protected_matches jsonb;
  v_protected_choice uuid;
  v_protected_count integer;
  v_protected_separate boolean;
  v_eligible_ids jsonb;
  v_eligible_hash bytea;
  v_generation integer;
  v_applied integer:=0;
  v_expected integer;
  v_existing integer;
  v_qualification jsonb;
  v_charge jsonb;
  v_economic jsonb;
  v_effective_policy jsonb;
  v_contract_settings_authority jsonb;
  v_canonical_economic jsonb;
  v_contract_rate_fingerprint bytea;
  v_effective_policy_fingerprint bytea;
  v_invoice_vat_policy_fingerprint bytea;
  v_calculation_fingerprint bytea;
  v_expense_policy_snapshot_hash bytea;
  v_source_mode text;
  v_row_sign smallint;
  v_invoice_vat_chargeable boolean;
  v_invoice_vat_rate_pct numeric;
  v_source_expense_vat_enabled boolean;
  v_source_authority boolean;
  v_has_worked_tuple boolean;
  v_expected_pay_pence bigint;
  v_expected_charge_pence bigint;
  v_result text;
  v_passed boolean;
  v_charge_source_pence bigint;
  v_charge_calculated_pence bigint;
  v_charge_difference_pence bigint;
  v_charge_row_sign_kind text;
  v_charge_claimed_result text;
  v_charge_expected_result text;
  v_charge_expected_sign_kind text;
  v_mode_a_policy jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_actor_user_id is null or p_publication_id is null
     or pg_catalog.jsonb_typeof(p_rows)<>'array' then
    raise exception 'WEEKLY_SOURCE_PROJECTION_INPUT_INVALID' using errcode='22023';
  end if;

  -- Read immutable identity first, then enter the same scope lock order as
  -- begin/publish before taking any row lock. Exact retries can therefore race
  -- safely without forming a publication-to-scope lock cycle.
  select * into v_publication
  from public.weekly_source_projection_publications
  where id=p_publication_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_NOT_FOUND' using errcode='22023';
  end if;
  select * into strict v_upload
  from public.weekly_source_uploads
  where id=v_publication.upload_id;
  select * into strict v_cycle
  from public.weekly_source_cycles
  where id=v_publication.source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  perform private.weekly_source_pay_query_admit_v2();
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.encode(v_upload.declared_scope_fingerprint,'hex'),73241837
    )
  );

  if v_publication.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into strict v_cycle
    from public.weekly_source_cycles
    where id=v_publication.source_cycle_id;
    select * into strict v_scope
    from public.weekly_source_report_scopes
    where id=v_publication.report_scope_id
    for update;
  else
    select * into strict v_cycle
    from public.weekly_source_cycles
    where id=v_publication.source_cycle_id
    for update;
  end if;
  select * into strict v_publication
  from public.weekly_source_projection_publications
  where id=p_publication_id
  for update;
  if v_publication.state not in ('BUILDING','CORRECTION_READY')
     or (v_publication.state='CORRECTION_READY'
         and v_publication.correction_session_id is null) then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_NOT_BUILDING' using errcode='55000';
  end if;
  select * into strict v_upload
  from public.weekly_source_uploads
  where id=v_publication.upload_id
  for share;
  select * into strict v_profile
  from public.weekly_source_format_profiles profile
  where profile.id=v_upload.source_format_profile_id and profile.active;

  if v_publication.authority_scope_kind='NHSP_REPORT_SCOPE' then
    if v_scope.version is distinct from v_publication.authority_scope_version
       or (
         v_publication.correction_session_id is null
         and (v_scope.current_complete_upload_id is distinct from v_upload.id
              or v_scope.projection_state<>'REBUILDING')
       ) then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_STALE' using errcode='40001';
    end if;
  elsif v_cycle.version is distinct from v_publication.authority_scope_version
        or (
          v_publication.correction_session_id is null
          and (v_cycle.current_complete_upload_id is distinct from v_upload.id
               or v_cycle.projection_state<>'REBUILDING')
        ) then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_STALE' using errcode='40001';
  end if;

  if v_publication.correction_session_id is not null then
    select * into v_correction
    from public.weekly_final_source_correction_sessions
    where id=v_publication.correction_session_id for update;
    if not found
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from v_publication.authority_scope_kind
       or v_correction.report_scope_id is distinct from v_publication.report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.actor_user_id is distinct from p_actor_user_id
       or v_upload.purpose<>'FINAL_SOURCE_CORRECTION'
       or v_upload.state<>'CORRECTION_READY'
       or (v_publication.state='BUILDING'
         and v_publication.rebuild_idempotency_key is null and (
         v_correction.state<>'READY'
         or v_correction.replacement_projection_publication_id is not null
       ))
       or (v_publication.state='BUILDING'
         and v_publication.rebuild_idempotency_key is not null and (
         v_publication.projection_generation is null
         or v_publication.ready_session_version is null
         or v_correction.state<>'REVIEWED'
         or v_correction.version<>v_publication.ready_session_version
         or v_correction.replacement_projection_publication_id is null
         or v_correction.replacement_projection_publication_id=v_publication.id
       ))
       or (v_publication.state='CORRECTION_READY'
         and v_correction.replacement_projection_publication_id
               is distinct from v_publication.id)
       or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
            is distinct from v_correction.expected_current_final_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PUBLICATION_STALE' using errcode='40001';
    end if;
  elsif v_upload.purpose<>'ORDINARY' or v_upload.state<>'CURRENT' then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_STALE' using errcode='40001';
  end if;

  perform private.weekly_source_office_authority_v1(
    p_actor_user_id,'RECHECK_SOURCE',v_group.id,
    case when v_publication.authority_scope_kind='NHSP_REPORT_SCOPE' then v_scope.client_id else null end,
    v_cycle.finalisation_week_ending
  );

  if v_publication.authority_scope_version>2147483647
     or coalesce(v_publication.projection_generation,0)>2147483647 then
    raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003';
  end if;
  v_generation:=coalesce(
    v_publication.projection_generation,
    v_publication.authority_scope_version::integer
  );

  select pg_catalog.count(*)::integer into v_expected
  from public.weekly_source_upload_rows source_row
  where source_row.upload_id=v_upload.id;
  if pg_catalog.jsonb_array_length(p_rows)<>v_expected then
    raise exception 'WEEKLY_SOURCE_PROJECTION_ROW_CENSUS_MISMATCH'
      using errcode='22023',detail=pg_catalog.jsonb_build_object(
        'expected',v_expected,'received',pg_catalog.jsonb_array_length(p_rows)
      )::text;
  end if;

  select pg_catalog.count(*)::integer into v_existing
  from public.weekly_source_row_resolutions resolution
  join public.weekly_source_upload_rows source_row
    on source_row.id=resolution.upload_row_id
  where source_row.upload_id=v_upload.id
    and resolution.generation=v_generation;
  if v_publication.state='CORRECTION_READY' or v_existing>0 then
    if v_existing<>v_expected or exists(
      select 1
      from public.weekly_source_upload_rows source_row
      where source_row.upload_id=v_upload.id
        and not exists(
          select 1
          from public.weekly_source_row_resolutions resolution
          where resolution.upload_row_id=source_row.id
            and resolution.generation=v_generation
            and resolution.source_row_fingerprint=source_row.normalised_row_hash
        )
    ) then
      raise exception 'WEEKLY_SOURCE_PROJECTION_RESOLUTION_CENSUS_INCOMPLETE'
        using errcode='55000';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'publication_id',v_publication.id,'upload_id',v_upload.id,
      'authority_scope_version',v_publication.authority_scope_version,
      'generation',v_generation,'applied_row_count',v_existing,'idempotent',true
    );
  end if;

  for v_row_json in select value from pg_catalog.jsonb_array_elements(p_rows)
  loop
    if pg_catalog.jsonb_typeof(v_row_json)<>'object' then
      raise exception 'WEEKLY_SOURCE_PROJECTION_ROW_INVALID' using errcode='22023';
    end if;
    select * into strict v_source_row
    from public.weekly_source_upload_rows source_row
    where source_row.id=(v_row_json->>'upload_row_id')::uuid
      and source_row.upload_id=v_upload.id
    for share;

    if exists(
      select 1 from public.weekly_source_row_resolutions resolution
      where resolution.upload_row_id=v_source_row.id and resolution.generation=v_generation
    ) then
      raise exception 'WEEKLY_SOURCE_PROJECTION_ROW_ALREADY_APPLIED' using errcode='23505';
    end if;

    v_mapping_state:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_row_json->>'mapping_state','')));
    if v_mapping_state not in (
      'RESOLVED','CANDIDATE_NOT_FOUND','CLIENT_NOT_FOUND','NO_ELIGIBLE_CONTRACT',
      'AMBIGUOUS_CONTRACT','CONTRACT_SELECTION_REQUIRED','SOURCE_ROW_BLOCKED'
    ) then
      raise exception 'WEEKLY_SOURCE_MAPPING_STATE_INVALID' using errcode='22023';
    end if;
    v_candidate_id:=nullif(v_row_json->>'candidate_id','')::uuid;
    v_client_id:=nullif(v_row_json->>'client_id','')::uuid;
    v_contract_id:=nullif(v_row_json->>'contract_id','')::uuid;
    v_prior_work_event_id:=nullif(v_row_json->>'prior_work_event_id','')::uuid;
    v_selection_method:=nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(v_row_json->>'contract_selection_method',''))),'');
    v_work_event_id:=null;
    v_link_kind:=null;
    v_work_event_match_kind:=null;
    v_work_event_match_fingerprint:=null;
    v_work_event_was_present:=false;
    v_compatible_count:=0;
    v_compatible_event_id:=null;
    v_economic:=v_row_json->'economic_snapshot';
    v_effective_policy:=null;
    v_contract_settings_authority:=null;
    v_canonical_economic:=null;
    v_contract_rate_fingerprint:=null;
    v_effective_policy_fingerprint:=null;
    v_invoice_vat_policy_fingerprint:=null;
    v_calculation_fingerprint:=null;
    v_expense_policy_snapshot_hash:=null;
    v_source_mode:=null;
    v_row_sign:=null;
    v_invoice_vat_chargeable:=null;
    v_invoice_vat_rate_pct:=null;
    v_source_expense_vat_enabled:=null;
    v_source_authority:=false;
    v_has_worked_tuple:=false;

    v_eligible_ids:=coalesce((
      select pg_catalog.jsonb_agg(contract_id order by contract_id)
      from (
        select distinct value as contract_id
        from pg_catalog.jsonb_array_elements_text(coalesce(v_row_json->'qualifying_contract_ids','[]'::jsonb))
      ) ordered
    ),'[]'::jsonb);
    v_eligible_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_QUALIFYING_CONTRACT_SET_V1',v_eligible_ids
    );

    if v_mapping_state='RESOLVED' then
      if v_candidate_id is null or v_client_id is null or v_contract_id is null
         or v_selection_method not in ('AUTO_UNIQUE','OFFICE_SELECTED','DURABLE_LINEAGE') then
        raise exception 'WEEKLY_SOURCE_RESOLVED_MAPPING_INCOMPLETE' using errcode='22023';
      end if;
      select * into strict v_contract
      from public.contracts contract
      where contract.id=v_contract_id
        and contract.candidate_id=v_candidate_id
        and contract.client_id=v_client_id
        and v_source_row.work_date between contract.start_date and coalesce(contract.end_date,'infinity'::date);
      if not (v_eligible_ids ? v_contract_id::text) then
        raise exception 'WEEKLY_SOURCE_SELECTED_CONTRACT_NOT_QUALIFIED' using errcode='22023';
      end if;
      -- G6-4: the selection method must be provable from server-derived
      -- facts, not asserted by the caller. Authority: 24 §8 ("If one Contract
      -- remains, the system selects it… The system must never offer a chooser
      -- when only one Contract is eligible"), 24 §9 (unique prior lineage),
      -- 25 §7, XSG-011, XSG-012.
      if v_selection_method='AUTO_UNIQUE'
         and pg_catalog.jsonb_array_length(v_eligible_ids)<>1 then
        raise exception 'WEEKLY_SOURCE_AUTO_UNIQUE_NOT_UNIQUE' using errcode='22023',
          detail=pg_catalog.jsonb_build_object(
            'source_row_ordinal',v_source_row.source_row_ordinal,
            'qualifying_contract_count',pg_catalog.jsonb_array_length(v_eligible_ids)
          )::text;
      end if;
      if v_selection_method='OFFICE_SELECTED'
         and pg_catalog.jsonb_array_length(v_eligible_ids)<2 then
        raise exception 'WEEKLY_SOURCE_OFFICE_CHOICE_NOT_WARRANTED' using errcode='22023',
          detail=pg_catalog.jsonb_build_object(
            'source_row_ordinal',v_source_row.source_row_ordinal,
            'qualifying_contract_count',pg_catalog.jsonb_array_length(v_eligible_ids)
          )::text;
      end if;
      if v_selection_method='DURABLE_LINEAGE' then
        if v_prior_work_event_id is null then
          raise exception 'WEEKLY_SOURCE_DURABLE_LINEAGE_UNPROVEN' using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'source_row_ordinal',v_source_row.source_row_ordinal,
              'reason','PRIOR_WORK_EVENT_ABSENT'
            )::text;
        end if;
        perform 1
        from public.weekly_work_events prior_event
        join public.weekly_source_row_resolutions prior_resolution
          on prior_resolution.work_event_id=prior_event.id
        where prior_event.id=v_prior_work_event_id
          and prior_event.candidate_id=v_candidate_id
          and prior_event.client_id=v_client_id
          and prior_event.first_source_group_id=v_group.id
          and prior_resolution.mapping_state='RESOLVED'
          and prior_resolution.contract_id=v_contract_id
          and (prior_resolution.upload_row_id<>v_source_row.id
            or (prior_resolution.generation<v_generation
              and prior_resolution.source_row_fingerprint=v_source_row.normalised_row_hash
              and exists(select 1 from public.weekly_source_projection_publications prior_publication
                where prior_publication.upload_id=v_upload.id
                  and coalesce(prior_publication.projection_generation,prior_publication.authority_scope_version)=prior_resolution.generation
                  and prior_publication.published_at_utc is not null
                  and prior_publication.state in ('CURRENT','STALE'))));
        if not found then
          raise exception 'WEEKLY_SOURCE_DURABLE_LINEAGE_UNPROVEN' using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'source_row_ordinal',v_source_row.source_row_ordinal,
              'reason','NO_PRIOR_RESOLVED_CONTRACT_FOR_WORK_EVENT'
            )::text;
        end if;
      end if;

      v_effective_policy:=private._weekly_source_effective_policy_v1(
        v_client_id,v_contract_id,v_source_row.work_date
      );
      v_effective_policy_fingerprint:=private.weekly_source_projection_hex32_v1(
        v_effective_policy->>'policy_sha256','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
      );
      if nullif(v_row_json->>'effective_policy_fingerprint','') is not null
         and private.weekly_source_projection_hex32_v1(
           v_row_json->>'effective_policy_fingerprint','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
         ) is distinct from v_effective_policy_fingerprint then
        raise exception 'WEEKLY_SOURCE_POLICY_STALE' using errcode='40001';
      end if;
      v_source_authority:=coalesce(v_effective_policy->>'authority_mode','')='SOURCE_AUTHORITY';
      v_source_mode:=nullif(v_effective_policy->>'c1_source_mode','');
      if v_source_authority and (
           coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) is not true
           or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
         ) then
        raise exception 'WEEKLY_SOURCE_C1_MODE_UNRESOLVED' using errcode='55000';
      end if;
      if not v_source_authority and v_source_mode is not null then
        raise exception 'WEEKLY_SOURCE_TIMESHEET_AUTHORITY_C1_MODE_FORBIDDEN' using errcode='55000';
      end if;
      if (v_profile.profile_code in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1'))
           is distinct from (v_source_mode='NHSP_WEEKLY')
         and v_source_authority then
        raise exception 'WEEKLY_SOURCE_PROFILE_MODE_MISMATCH' using errcode='55000';
      end if;

      v_contract_settings_authority:=private._contract_settings_effective_core_v1(
        v_client_id,v_contract_id,v_source_row.work_date,'IMPORT',null
      );
      v_invoice_vat_chargeable:=coalesce(
        (v_contract_settings_authority#>>'{values,client_vat_chargeable}')::boolean,true
      );
      v_invoice_vat_rate_pct:=case when v_invoice_vat_chargeable then
        coalesce((v_contract_settings_authority#>>'{values,vat_rate_pct}')::numeric,20)
        else 0::numeric end;
      if v_invoice_vat_rate_pct<0 or v_invoice_vat_rate_pct>100 then
        raise exception 'WEEKLY_SOURCE_INVOICE_VAT_RATE_INVALID' using errcode='22023';
      end if;
      v_source_expense_vat_enabled:=coalesce(
        (v_effective_policy->>'source_expense_vat_enabled')::boolean,false
      );
      v_invoice_vat_policy_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_INVOICE_VAT_POLICY_V1',
        pg_catalog.jsonb_build_object(
          'client_id',v_client_id,'contract_id',v_contract_id,'work_date',v_source_row.work_date,
          'client_settings_id',v_contract_settings_authority->>'client_settings_id',
          'client_settings_effective_from',v_contract_settings_authority->>'client_settings_effective_from',
          'finance_settings_id',v_contract_settings_authority->>'finance_settings_id',
          'finance_settings_date_from',v_contract_settings_authority->>'finance_settings_date_from',
          'client_vat_chargeable',v_invoice_vat_chargeable,
          'vat_rate_pct',v_invoice_vat_rate_pct,
          'source_expense_vat_enabled',v_source_expense_vat_enabled,
          'settings_authority_fingerprint',v_contract_settings_authority->>'authority_fingerprint'
        )
      );

      -- G8-1/G8-2 (XSG-009).  `24 §14` and `25 §9`: a signed-Timesheet-authority
      -- row belongs to the established validation-only Mode A journey, never to
      -- source finalisation, and "merely labelling the row as Timesheet evidence
      -- is insufficient".  The unified upload owner therefore records the
      -- resolved Mode A authority as production data on the
      -- `weekly_timesheet_authority_resolutions` relation, which until now had
      -- no writer outside a verification fixture.
      -- `Reference required before pay` and `require_reference_to_invoice` come
      -- from the installed contract-settings authority and default to false;
      -- the auto-authorisation decision is taken from the established resolver
      -- `public.import_auto_authorise_policy_resolve_v2` in validation context,
      -- exactly as `public._import_review_auto_authorise_targets_core_v1` reads
      -- it, so no second policy engine is introduced.
      if not v_source_authority then
        if coalesce(v_effective_policy->>'document_mode','')<>'INVOICE_EVIDENCE_REQUIRED'
           or coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) then
          raise exception 'WEEKLY_SOURCE_TIMESHEET_AUTHORITY_POLICY_INVALID' using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'source_row_ordinal',v_source_row.source_row_ordinal,
              'document_mode',v_effective_policy->>'document_mode',
              'self_bill_enabled',v_effective_policy->>'self_bill_enabled'
            )::text;
        end if;
        v_mode_a_policy:=public.import_auto_authorise_policy_resolve_v2(
          case when v_profile.profile_code in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1')
            then 'NHSP'::public.hr_source_enum
            else 'HEALTHROSTER'::public.hr_source_enum end,
          v_client_id,v_contract_id,null,v_source_row.work_date,true
        );
        insert into public.weekly_timesheet_authority_resolutions(
          source_cycle_id,client_id,contract_id,work_date,authority_mode,document_mode,
          require_reference_to_pay,require_reference_to_invoice,auto_authorise_enabled,
          effective_policy_fingerprint
        ) values (
          v_cycle.id,v_client_id,v_contract_id,v_source_row.work_date,
          'TIMESHEET_AUTHORITY','INVOICE_EVIDENCE_REQUIRED',
          coalesce((v_contract_settings_authority#>>'{values,require_reference_to_pay}')::boolean,false),
          coalesce((v_contract_settings_authority#>>'{values,require_reference_to_invoice}')::boolean,false),
          coalesce((v_mode_a_policy->>'effective_value')::boolean,false),
          v_effective_policy_fingerprint
        ) on conflict (source_cycle_id,contract_id,work_date,effective_policy_fingerprint) do nothing;
      end if;

      v_has_worked_tuple:=v_source_row.start_at_local is not null
        and v_source_row.end_at_local is not null
        and v_source_row.break_minutes is not null
        and coalesce(v_source_row.actual_net_minutes,0)>0;

      v_identity_kind:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_row_json->>'identity_kind','')));
      if v_identity_kind not in ('PROFILE_EXTERNAL_KEY','SCHEDULE_TUPLE') then
        raise exception 'WEEKLY_SOURCE_WORK_EVENT_IDENTITY_INVALID' using errcode='22023';
      end if;
      if v_profile.profile_code in (
        'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
        'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1',
        'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1'
      ) and v_identity_kind<>'PROFILE_EXTERNAL_KEY' then
        raise exception 'WEEKLY_SOURCE_PROFILE_EXTERNAL_EVENT_KEY_REQUIRED' using errcode='22023';
      end if;
      -- WP-58 / WP-50 finding F7, the mirror image of the guard above.
      -- Pack 24 section 1 supersedes "the NHSP Reference Number is the durable
      -- identity of the real shift", and 24 section 9 states the Reference
      -- Number is "not sole durable work identity": it, the ward and the
      -- location may all change during a correction. An NHSP shift is the same
      -- shift as another by the schedule tuple
      -- (private.weekly_source_work_event_schedule_compatible_v1), never by the
      -- reference. Reference-keyed identity on an NHSP row makes a reversal and
      -- its re-issue three separate work events for one corrected shift, which
      -- is what WP-50 executed. Until this guard existed, the only thing
      -- sending SCHEDULE_TUPLE for NHSP was one ternary in the broker
      -- (broker/src/weekly-source/upload-publication-owner.mjs), so the rule
      -- held on exactly one route. It is enforced here, where no caller can go
      -- round it.
      if v_profile.profile_code in (
        'NHSP_PREFINAL_RELEASED_V1',
        'NHSP_FINAL_BACKING_V1'
      ) and v_identity_kind<>'SCHEDULE_TUPLE' then
        raise exception 'WEEKLY_SOURCE_SCHEDULE_TUPLE_EVENT_KEY_REQUIRED' using errcode='22023';
      end if;
      v_profile_external_key:=case when v_identity_kind='PROFILE_EXTERNAL_KEY'
        then nullif(pg_catalog.btrim(coalesce(v_row_json->>'profile_external_key','')),'') end;
      if v_identity_kind='PROFILE_EXTERNAL_KEY'
         and (v_profile_external_key is null
              or v_profile_external_key is distinct from nullif(pg_catalog.btrim(v_source_row.external_source_key),'')) then
        raise exception 'WEEKLY_SOURCE_EXTERNAL_EVENT_KEY_REQUIRED' using errcode='22023';
      end if;

      if v_source_authority then
        v_protected_matches:=private.weekly_source_protected_match_candidates_v1(v_source_row.id,v_candidate_id,v_client_id);
        select choice.work_event_id,choice.separate_shift into v_protected_choice,v_protected_separate
          from private.weekly_source_office_row_choices choice
          where choice.upload_row_id=v_source_row.id and choice.candidate_id=v_candidate_id
            and choice.client_id=v_client_id and choice.contract_id=v_contract_id
          order by choice.id desc limit 1;
        if v_protected_choice is not null then
          if v_prior_work_event_id is distinct from v_protected_choice
            or not exists(select 1 from jsonb_array_elements(v_protected_matches) match
              where match->>'work_event_id'=v_protected_choice::text and match->>'contract_id'=v_contract_id::text) then
            raise exception 'WEEKLY_SOURCE_PROTECTED_MATCH_NOT_ELIGIBLE' using errcode='40001';
          end if;
        elsif not coalesce(v_protected_separate,false) then
          if exists(select 1 from jsonb_array_elements(v_protected_matches) match
            where match->>'contract_id'=v_contract_id::text and (match->>'retained_source_identity')::boolean) then
            select coalesce(jsonb_agg(match),'[]'::jsonb) into v_protected_matches
              from jsonb_array_elements(v_protected_matches) match
              where match->>'contract_id'=v_contract_id::text and (match->>'retained_source_identity')::boolean;
          elsif exists(select 1 from jsonb_array_elements(v_protected_matches) match
            where match->>'contract_id'=v_contract_id::text and (match->>'schedule_compatible')::boolean) then
            select coalesce(jsonb_agg(match),'[]'::jsonb) into v_protected_matches
              from jsonb_array_elements(v_protected_matches) match
              where match->>'contract_id'=v_contract_id::text and (match->>'schedule_compatible')::boolean;
          end if;
          select count(*) into v_protected_count from jsonb_array_elements(v_protected_matches) match
            where match->>'contract_id'=v_contract_id::text;
          if v_protected_count>0 and (v_protected_count<>1 or not exists(
            select 1 from jsonb_array_elements(v_protected_matches) match
            where match->>'contract_id'=v_contract_id::text
              and ((match->>'schedule_compatible')::boolean or (match->>'retained_source_identity')::boolean)
              and match->>'work_event_id'=v_prior_work_event_id::text)) then
            raise exception 'WEEKLY_SOURCE_PROTECTED_MATCH_REQUIRED' using errcode='55000';
          end if;
        end if;
      end if;
      if v_prior_work_event_id is not null then
        select * into strict v_work_event
        from public.weekly_work_events work_event
        where work_event.id=v_prior_work_event_id
          and work_event.candidate_id=v_candidate_id
          and work_event.client_id=v_client_id
          and work_event.first_source_group_id=v_group.id;
        if v_identity_kind='PROFILE_EXTERNAL_KEY'
           and exists(
             select 1
             from public.weekly_work_events other_event
             where other_event.first_source_group_id=v_group.id
               and other_event.source_format_profile_id=v_upload.source_format_profile_id
               and other_event.identity_kind='PROFILE_EXTERNAL_KEY'
               and other_event.profile_external_key=v_profile_external_key
               and other_event.id<>v_work_event.id
           ) then
          raise exception 'WEEKLY_SOURCE_PROFILE_EVENT_KEY_CONFLICT' using errcode='55000';
        end if;
        v_work_event_id:=v_work_event.id;
        v_work_event_match_kind:='EXACT_DURABLE_LINEAGE';
      else
        if v_identity_kind='PROFILE_EXTERNAL_KEY' then
          v_durable_identity_hash:=private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_WORK_EVENT_PROFILE_KEY_V1',
            pg_catalog.jsonb_build_object(
              'source_group_id',v_group.id,
              'source_format_profile_id',v_upload.source_format_profile_id,
              'profile_external_key',v_profile_external_key
            )
          );
        else
          -- WP-37 / `24 §9` step 2 and step 4.  The guarded set is read only
          -- after the family lock is held, so a concurrent publication cannot
          -- create a second root for the same work between this read and the
          -- insert below.
          perform pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(
              v_group.id::text||'|'||v_upload.source_format_profile_id::text||'|'
                ||v_candidate_id::text||'|'||v_client_id::text||'|'
                ||v_source_row.work_date::text,
              17092026
            )
          );
          select pg_catalog.count(*)::integer,
                 pg_catalog.min(work_event.id::text)::uuid
            into v_compatible_count,v_compatible_event_id
          from public.weekly_work_events work_event
          where work_event.first_source_group_id=v_group.id
            and work_event.source_format_profile_id=v_upload.source_format_profile_id
            and work_event.identity_kind='SCHEDULE_TUPLE'
            and work_event.candidate_id=v_candidate_id
            and work_event.client_id=v_client_id
            and work_event.work_date=v_source_row.work_date
            and private.weekly_source_work_event_schedule_compatible_v1(
                  work_event.id,v_source_row.start_at_local,v_source_row.end_at_local
                );
          if v_compatible_count>1 then
            -- `24 §9`: "Office confirmation when more than one plausible
            -- relationship remains.  It never guesses."  No root is chosen.
            raise exception 'WEEKLY_SOURCE_WORK_EVENT_IDENTITY_AMBIGUOUS' using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'source_row_ordinal',v_source_row.source_row_ordinal,
                'candidate_id',v_candidate_id,'client_id',v_client_id,
                'work_date',v_source_row.work_date,
                'compatible_work_event_count',v_compatible_count
              )::text;
          end if;
          -- The hash still carries this row's own schedule, so a genuinely
          -- different, non-overlapping shift on the same date gets its own
          -- durable identity.  It is a uniqueness token for a NEW root, not
          -- the identity rule: the rule is the compatible-schedule set above.
          v_durable_identity_hash:=private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_WORK_EVENT_SCHEDULE_TUPLE_V1',
            pg_catalog.jsonb_build_object(
              'source_group_id',v_group.id,'source_format_profile_id',v_upload.source_format_profile_id,
              'candidate_id',v_candidate_id,'client_id',v_client_id,'work_date',v_source_row.work_date,
              'start_at_local',v_source_row.start_at_local,'end_at_local',v_source_row.end_at_local
            )
          );
        end if;
        if v_identity_kind='SCHEDULE_TUPLE' and v_compatible_count=1 then
          select * into strict v_work_event
          from public.weekly_work_events work_event
          where work_event.id=v_compatible_event_id;
          v_work_event_was_present:=true;
        else
          select exists(
            select 1 from public.weekly_work_events work_event
            where work_event.durable_identity_hash=v_durable_identity_hash
          ) into v_work_event_was_present;
          insert into public.weekly_work_events(
            candidate_id,client_id,work_date,identity_kind,profile_external_key,
            durable_identity_hash,first_source_group_id,source_format_profile_id
          ) values (
            v_candidate_id,v_client_id,v_source_row.work_date,v_identity_kind,
            v_profile_external_key,v_durable_identity_hash,v_group.id,v_upload.source_format_profile_id
          ) on conflict (durable_identity_hash) do nothing;
          select * into strict v_work_event
          from public.weekly_work_events work_event
          where work_event.durable_identity_hash=v_durable_identity_hash;
        end if;
        if v_work_event.candidate_id is distinct from v_candidate_id
           or v_work_event.client_id is distinct from v_client_id
           or v_work_event.identity_kind is distinct from v_identity_kind
           or v_work_event.profile_external_key is distinct from v_profile_external_key
           or v_work_event.first_source_group_id is distinct from v_group.id
           or v_work_event.source_format_profile_id is distinct from v_upload.source_format_profile_id
           or (v_identity_kind='SCHEDULE_TUPLE' and v_work_event.work_date is distinct from v_source_row.work_date) then
          raise exception 'WEEKLY_SOURCE_WORK_EVENT_IDENTITY_COLLISION' using errcode='55000';
        end if;
        v_work_event_id:=v_work_event.id;
        v_work_event_match_kind:=case
          when v_identity_kind='PROFILE_EXTERNAL_KEY' and v_work_event_was_present then 'REUSED_PROFILE_KEY'
          when v_identity_kind='PROFILE_EXTERNAL_KEY' then 'NEW_PROFILE_KEY'
          when v_work_event_was_present then 'EXACT_DURABLE_LINEAGE'
          else 'NEW_SCHEDULE_TUPLE'
        end;
      end if;
      v_work_event_match_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_WORK_EVENT_MATCH_V1',
        pg_catalog.jsonb_build_object(
          'upload_row_id',v_source_row.id,'work_event_id',v_work_event_id,
          'match_kind',v_work_event_match_kind,'prior_work_event_id',v_prior_work_event_id,
          'source_row_fingerprint',pg_catalog.encode(v_source_row.normalised_row_hash,'hex')
        )
      );
    end if;

    -- Only a resolved, source-authoritative worked row owns a C1 economic
    -- snapshot.  Timesheet-authoritative validation rows, unfinished rows and
    -- explicit source-zero positions must never cross the pay boundary.
    if v_mapping_state='RESOLVED'
       and v_source_authority
       and v_source_row.row_finalisation_state in ('NOT_APPLICABLE','SOURCE_WORKED') then
      if not v_has_worked_tuple then
        raise exception 'WEEKLY_SOURCE_WORKED_TUPLE_REQUIRED' using errcode='22023';
      end if;
      if pg_catalog.jsonb_typeof(v_economic)<>'object'
         or v_economic->>'schema_version' is distinct from 'WEEKLY_SOURCE_CANONICAL_ECONOMIC_SNAPSHOT_V1'
         or v_economic->>'calculator_version' is distinct from 'WEEKLY_SHIFT_FINANCIAL_SEGMENT_V1'
         or pg_catalog.upper(coalesce(v_economic->>'source_mode','')) is distinct from v_source_mode
         or pg_catalog.upper(coalesce(v_economic->>'rate_method',''))
              is distinct from v_effective_policy->>'weekly_rate_classification_method'
         or pg_catalog.jsonb_typeof(v_economic->'bucket_minutes')<>'object'
         or pg_catalog.jsonb_typeof(v_economic->'hours')<>'object'
         or pg_catalog.jsonb_typeof(v_economic->'pay_rates')<>'object'
         or pg_catalog.jsonb_typeof(v_economic->'charge_rates')<>'object' then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_SNAPSHOT_INVALID' using errcode='22023';
      end if;

      -- A structurally valid NHSP £0 line is still a worked row.  Source money
      -- decides whether a physical row is a reversal only when it is negative;
      -- zero therefore keeps the positive worked-time/pay sign while the
      -- invoice movement retains the exact £0 source value.
      v_row_sign:=case when v_source_mode='NHSP_WEEKLY' then
        case when coalesce(v_source_row.source_shift_charge_pence,0)<0 then -1 else 1 end
        else 1 end;
      if v_row_sign not in (-1,1)
         or coalesce(v_economic->>'sign','')!~'^[-]?[0-9]+$'
         or (v_economic->>'sign')::smallint is distinct from v_row_sign
         or coalesce(v_economic->>'paid_minutes','')!~'^[0-9]+$'
         or (v_economic->>'paid_minutes')::integer is distinct from v_source_row.actual_net_minutes
         or coalesce(v_economic->>'break_minutes','')!~'^[0-9]+$'
         or (v_economic->>'break_minutes')::integer is distinct from v_source_row.break_minutes then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_SOURCE_TUPLE_MISMATCH' using errcode='22023';
      end if;

      if exists(
        select 1
        from (values ('day'),('night'),('sat'),('sun'),('bh')) bucket(name)
        where coalesce(v_economic#>>array['bucket_minutes',bucket.name],'')!~'^[0-9]+$'
           or coalesce(v_economic#>>array['hours',bucket.name],'')!~'^[+-]?[0-9]+([.][0-9]+)?$'
           or coalesce(v_economic#>>array['pay_rates',bucket.name],'')!~'^[+]?[0-9]+([.][0-9]+)?$'
           or coalesce(v_economic#>>array['charge_rates',bucket.name],'')!~'^[+]?[0-9]+([.][0-9]+)?$'
           or (v_economic#>>array['pay_rates',bucket.name])::numeric<=0
           or (v_economic#>>array['charge_rates',bucket.name])::numeric<=0
      ) then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_BUCKET_INVALID' using errcode='22023';
      end if;
      if (
        (v_economic#>>'{bucket_minutes,day}')::integer+
        (v_economic#>>'{bucket_minutes,night}')::integer+
        (v_economic#>>'{bucket_minutes,sat}')::integer+
        (v_economic#>>'{bucket_minutes,sun}')::integer+
        (v_economic#>>'{bucket_minutes,bh}')::integer
      ) is distinct from v_source_row.actual_net_minutes then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_MINUTES_MISMATCH' using errcode='22023';
      end if;
      if exists(
        select 1
        from (values ('day'),('night'),('sat'),('sun'),('bh')) bucket(name)
        where (v_economic#>>array['hours',bucket.name])::numeric is distinct from
          pg_catalog.round(
            ((v_economic#>>array['bucket_minutes',bucket.name])::numeric/60)*v_row_sign,2
          )
      ) then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_HOURS_MISMATCH' using errcode='22023';
      end if;
      if coalesce(v_economic->>'total_pay_pence','')!~'^[-]?[0-9]+$'
         or coalesce(v_economic->>'calculated_charge_pence','')!~'^[-]?[0-9]+$' then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_TOTAL_INVALID' using errcode='22023';
      end if;

      v_expected_pay_pence:=(pg_catalog.round(
        pg_catalog.round(
          pg_catalog.abs((v_economic#>>'{hours,day}')::numeric)*(v_economic#>>'{pay_rates,day}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,night}')::numeric)*(v_economic#>>'{pay_rates,night}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,sat}')::numeric)*(v_economic#>>'{pay_rates,sat}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,sun}')::numeric)*(v_economic#>>'{pay_rates,sun}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,bh}')::numeric)*(v_economic#>>'{pay_rates,bh}')::numeric,2
        )*100,0
      )::bigint)*v_row_sign;
      v_expected_charge_pence:=(pg_catalog.round(
        pg_catalog.round(
          pg_catalog.abs((v_economic#>>'{hours,day}')::numeric)*(v_economic#>>'{charge_rates,day}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,night}')::numeric)*(v_economic#>>'{charge_rates,night}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,sat}')::numeric)*(v_economic#>>'{charge_rates,sat}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,sun}')::numeric)*(v_economic#>>'{charge_rates,sun}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,bh}')::numeric)*(v_economic#>>'{charge_rates,bh}')::numeric,2
        )*100,0
      )::bigint)*v_row_sign;
      if (v_economic->>'total_pay_pence')::bigint is distinct from v_expected_pay_pence
         or (v_economic->>'calculated_charge_pence')::bigint is distinct from v_expected_charge_pence then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_TOTAL_MISMATCH' using errcode='22023';
      end if;

      v_contract_rate_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_CONTRACT_RATE_AUTHORITY_V1',
        pg_catalog.jsonb_build_object(
          'contract_id',v_contract.id,'contract_updated_at',v_contract.updated_at,
          'rates_json',v_contract.rates_json,'additional_rates_json',v_contract.additional_rates_json,
          'rate_method',v_effective_policy->>'weekly_rate_classification_method',
          'duration_break_tie_rule',v_effective_policy->>'duration_break_tie_rule',
          'canonical_pay_rates',v_economic->'pay_rates',
          'canonical_charge_rates',v_economic->'charge_rates',
          'settings_authority_fingerprint',v_contract_settings_authority->>'authority_fingerprint'
        )
      );
      v_canonical_economic:=pg_catalog.jsonb_build_object(
        'schema_version','WEEKLY_SOURCE_CANONICAL_ECONOMIC_SNAPSHOT_V1',
        'calculator_version','WEEKLY_SHIFT_FINANCIAL_SEGMENT_V1',
        'source_mode',v_source_mode,
        'rate_method',v_effective_policy->>'weekly_rate_classification_method',
        'sign',v_row_sign,
        'paid_minutes',v_source_row.actual_net_minutes,
        'break_minutes',v_source_row.break_minutes,
        'bucket_minutes',v_economic->'bucket_minutes',
        'hours',v_economic->'hours',
        'pay_rates',v_economic->'pay_rates',
        'charge_rates',v_economic->'charge_rates',
        'total_pay_pence',v_expected_pay_pence::text,
        'calculated_charge_pence',v_expected_charge_pence::text,
        'invoice_vat_chargeable',v_invoice_vat_chargeable,
        'invoice_vat_rate_pct',v_invoice_vat_rate_pct,
        'source_expense_vat_enabled',v_source_expense_vat_enabled,
        'contract_and_rate_fingerprint',pg_catalog.encode(v_contract_rate_fingerprint,'hex'),
        'effective_policy_fingerprint',pg_catalog.encode(v_effective_policy_fingerprint,'hex'),
        'invoice_vat_policy_fingerprint',pg_catalog.encode(v_invoice_vat_policy_fingerprint,'hex'),
        'break_allocation',v_economic->'break_allocation'
      );
      v_calculation_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_CANONICAL_ECONOMIC_SNAPSHOT_V1',v_canonical_economic
      );
    else
      if pg_catalog.jsonb_typeof(v_economic)='object' then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_SNAPSHOT_NOT_APPLICABLE' using errcode='22023';
      end if;
      if v_mapping_state='RESOLVED' and v_source_authority
         and v_source_row.row_finalisation_state='SOURCE_ABSENT_ZERO'
         and coalesce(v_source_row.actual_net_minutes,-1)<>0 then
        raise exception 'WEEKLY_SOURCE_SOURCE_ZERO_INVALID' using errcode='22023';
      end if;
    end if;

    if v_mapping_state='RESOLVED' then
      v_link_kind:=case
        when not v_source_authority then 'TIMESHEET_EVIDENCE'
        when v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1'
          or v_source_row.row_finalisation_state='SOURCE_UNFINALISED' then 'PROVISIONAL_SOURCE'
        when v_source_row.row_finalisation_state='SOURCE_ABSENT_ZERO' then 'ZERO_SOURCE'
        when v_source_mode='NHSP_WEEKLY' and v_row_sign=-1 then 'FULL_NEGATIVE_SOURCE'
        else 'POSITIVE_SOURCE'
      end;
      if nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(v_row_json->>'link_kind',''))),'')
           is distinct from v_link_kind then
        raise exception 'WEEKLY_SOURCE_LINK_KIND_MISMATCH' using errcode='22023';
      end if;
    elsif nullif(pg_catalog.btrim(coalesce(v_row_json->>'link_kind','')),'') is not null then
      raise exception 'WEEKLY_SOURCE_LINK_NOT_APPLICABLE' using errcode='22023';
    end if;

    insert into public.weekly_source_row_resolutions(
      upload_row_id,generation,candidate_id,client_id,contract_id,work_event_id,
      paid_minutes,rate_classifications_json,mapping_state,blocker_code,
      contract_selection_method,work_event_match_kind,work_event_match_fingerprint,
      qualification_profile_fingerprint,
      qualifying_contract_count,qualifying_contract_set_hash,source_row_fingerprint,
      contract_and_rate_fingerprint,effective_policy_fingerprint
    ) values (
      v_source_row.id,v_generation,v_candidate_id,v_client_id,v_contract_id,v_work_event_id,
      v_source_row.actual_net_minutes,v_canonical_economic,
      v_mapping_state,nullif(v_row_json->>'blocker_code',''),v_selection_method,
      v_work_event_match_kind,v_work_event_match_fingerprint,
      private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_QUALIFICATION_PROFILE_V1',
        pg_catalog.jsonb_build_object(
          'upload_row_id',v_source_row.id,'generation',v_generation,
          'qualifying_contract_ids',v_eligible_ids,'mapping_state',v_mapping_state
        )
      ),
      pg_catalog.jsonb_array_length(v_eligible_ids),v_eligible_hash,
      v_source_row.normalised_row_hash,
      case when v_mapping_state='RESOLVED' then coalesce(
        v_contract_rate_fingerprint,
        private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_SOURCE_NON_ECONOMIC_CONTRACT_AUTHORITY_V1',
          pg_catalog.jsonb_build_object(
            'contract_id',v_contract.id,'contract_updated_at',v_contract.updated_at,
            'rates_json',v_contract.rates_json,'additional_rates_json',v_contract.additional_rates_json,
            'source_row_state',v_source_row.row_finalisation_state
          )
        )
      ) end,
      case when v_mapping_state='RESOLVED' then v_effective_policy_fingerprint end
    ) returning id into v_resolution_id;

    if v_canonical_economic is not null then
      insert into public.weekly_source_row_economic_snapshots(
        row_resolution_id,upload_row_id,generation,work_event_id,
        candidate_id,client_id,contract_id,calculator_version,source_mode,rate_method,row_sign,
        paid_minutes,break_minutes,minutes_day,minutes_night,minutes_sat,minutes_sun,minutes_bh,
        hours_day,hours_night,hours_sat,hours_sun,hours_bh,
        pay_day,pay_night,pay_sat,pay_sun,pay_bh,
        charge_day,charge_night,charge_sat,charge_sun,charge_bh,
        total_pay_pence,calculated_charge_pence,
        invoice_vat_chargeable,invoice_vat_rate_pct,source_expense_vat_enabled,
        canonical_result_json,contract_and_rate_fingerprint,effective_policy_fingerprint,
        invoice_vat_policy_fingerprint,calculation_fingerprint
      ) values (
        v_resolution_id,v_source_row.id,v_generation,v_work_event_id,
        v_candidate_id,v_client_id,v_contract_id,'WEEKLY_SHIFT_FINANCIAL_SEGMENT_V1',
        v_source_mode,v_effective_policy->>'weekly_rate_classification_method',v_row_sign,
        v_source_row.actual_net_minutes,v_source_row.break_minutes,
        (v_economic#>>'{bucket_minutes,day}')::integer,
        (v_economic#>>'{bucket_minutes,night}')::integer,
        (v_economic#>>'{bucket_minutes,sat}')::integer,
        (v_economic#>>'{bucket_minutes,sun}')::integer,
        (v_economic#>>'{bucket_minutes,bh}')::integer,
        (v_economic#>>'{hours,day}')::numeric,
        (v_economic#>>'{hours,night}')::numeric,
        (v_economic#>>'{hours,sat}')::numeric,
        (v_economic#>>'{hours,sun}')::numeric,
        (v_economic#>>'{hours,bh}')::numeric,
        (v_economic#>>'{pay_rates,day}')::numeric,
        (v_economic#>>'{pay_rates,night}')::numeric,
        (v_economic#>>'{pay_rates,sat}')::numeric,
        (v_economic#>>'{pay_rates,sun}')::numeric,
        (v_economic#>>'{pay_rates,bh}')::numeric,
        (v_economic#>>'{charge_rates,day}')::numeric,
        (v_economic#>>'{charge_rates,night}')::numeric,
        (v_economic#>>'{charge_rates,sat}')::numeric,
        (v_economic#>>'{charge_rates,sun}')::numeric,
        (v_economic#>>'{charge_rates,bh}')::numeric,
        v_expected_pay_pence,v_expected_charge_pence,
        v_invoice_vat_chargeable,v_invoice_vat_rate_pct,v_source_expense_vat_enabled,
        v_canonical_economic,v_contract_rate_fingerprint,v_effective_policy_fingerprint,
        v_invoice_vat_policy_fingerprint,v_calculation_fingerprint
      );
    end if;

    if v_mapping_state='RESOLVED'
       and v_source_authority
       and v_profile.profile_code='ROSTER_WEEKLY_SUMMARY_ACTUAL_V1'
       and coalesce((v_effective_policy->>'source_fixed_expenses_enabled')::boolean,false) then
      if v_source_row.source_expense_pence is null
         or v_source_row.source_expense_parse_state not in ('VALID','OMITTED_ZERO')
         or (v_source_row.source_expense_parse_state='OMITTED_ZERO'
             and v_source_row.source_expense_pence<>0) then
        raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_SNAPSHOT_INPUT_INVALID'
          using errcode='22023';
      end if;
      if v_source_row.source_expense_pence>0 and (
           v_source_row.start_at_local is null or v_source_row.end_at_local is null
           or v_source_row.end_at_local<=v_source_row.start_at_local
           or v_source_row.break_minutes is null
         ) then
        raise exception 'WEEKLY_SOURCE_EXPENSE_DISPLAY_TUPLE_REQUIRED'
          using errcode='22023';
      end if;
      v_expense_policy_snapshot_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_ROW_EXPENSE_POLICY_SNAPSHOT_V1',
        pg_catalog.jsonb_build_object(
          'row_resolution_id',v_resolution_id,'upload_row_id',v_source_row.id,
          'generation',v_generation,'work_event_id',v_work_event_id,
          'candidate_id',v_candidate_id,'client_id',v_client_id,
          'contract_id',v_contract_id,'row_finalisation_state',v_source_row.row_finalisation_state,
          'source_expense_pence',v_source_row.source_expense_pence,
          'source_expense_parse_state',v_source_row.source_expense_parse_state,
          'source_expense_vat_enabled',v_source_expense_vat_enabled,
          'invoice_vat_chargeable',v_invoice_vat_chargeable,
          'invoice_vat_rate_pct',v_invoice_vat_rate_pct,
          'correction_presentation',v_effective_policy->>'self_bill_correction_presentation',
          'effective_policy_fingerprint',pg_catalog.encode(v_effective_policy_fingerprint,'hex'),
          'invoice_vat_policy_fingerprint',pg_catalog.encode(v_invoice_vat_policy_fingerprint,'hex')
        )
      );
      insert into public.weekly_source_row_expense_policy_snapshots(
        row_resolution_id,upload_row_id,generation,work_event_id,
        candidate_id,client_id,contract_id,source_expense_pence,
        source_expense_parse_state,source_expense_vat_enabled,
        invoice_vat_chargeable,invoice_vat_rate_pct,correction_presentation,effective_policy_fingerprint,
        invoice_vat_policy_fingerprint,snapshot_hash
      ) values (
        v_resolution_id,v_source_row.id,v_generation,v_work_event_id,
        v_candidate_id,v_client_id,v_contract_id,v_source_row.source_expense_pence,
        v_source_row.source_expense_parse_state,v_source_expense_vat_enabled,
        v_invoice_vat_chargeable,v_invoice_vat_rate_pct,
        v_effective_policy->>'self_bill_correction_presentation',v_effective_policy_fingerprint,
        v_invoice_vat_policy_fingerprint,v_expense_policy_snapshot_hash
      );
    end if;

    if v_mapping_state='RESOLVED' then
      insert into public.weekly_work_event_source_links(
        work_event_id,upload_row_id,row_resolution_id,link_kind,link_hash
      ) values (
        v_work_event_id,v_source_row.id,v_resolution_id,
        v_link_kind,
        private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_SOURCE_WORK_EVENT_LINK_V1',
          pg_catalog.jsonb_build_object(
            'work_event_id',v_work_event_id,'upload_row_id',v_source_row.id,
            'resolution_id',v_resolution_id,'link_kind',v_link_kind
          )
        )
      );
    end if;

    for v_qualification in
      select value from pg_catalog.jsonb_array_elements(coalesce(v_row_json->'qualification_observations','[]'::jsonb))
    loop
      if v_profile.profile_code not in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1') then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_PROFILE_NOT_APPLICABLE' using errcode='22023';
      end if;
      v_result:=pg_catalog.upper(coalesce(v_qualification->>'comparison_result',''));
      -- G6-2/G6-4: a per-Contract qualification verdict is re-derived here
      -- from the immutable source pence and the caller's canonical pence for
      -- that Contract, using the same symmetric NHSP_TWO_COMPONENT_PENCE_V1
      -- rule (25 §6; 24 §8, §13; 14 §4.3 items 1 and 5; NHSP-BR-013). The
      -- eligible set that the selection method is proved against is therefore
      -- the set the server itself would admit. UNVERIFIABLE stays available
      -- as the fail-closed verdict and is never upgraded.
      v_charge_source_pence:=nullif(v_qualification->>'source_shift_charge_pence','')::bigint;
      v_charge_calculated_pence:=nullif(v_qualification->>'canonical_calculated_pence','')::bigint;
      if v_charge_source_pence is distinct from v_source_row.source_shift_charge_pence then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_SOURCE_PENCE_MISMATCH' using errcode='22023',
          detail=pg_catalog.jsonb_build_object(
            'source_row_ordinal',v_source_row.source_row_ordinal,
            'contract_id',v_qualification->>'contract_id'
          )::text;
      end if;
      v_charge_difference_pence:=case
        when v_charge_source_pence is null or v_charge_calculated_pence is null then null
        else v_charge_source_pence-v_charge_calculated_pence end;
      v_charge_expected_result:=case
        when v_charge_source_pence is null or v_charge_calculated_pence is null then 'UNVERIFIABLE'
        when v_charge_source_pence=0 and v_charge_calculated_pence<>0 then 'ZERO_SOURCE_CHARGE'
        when v_charge_calculated_pence=0 then 'MISMATCH'
        when v_charge_difference_pence=0 then 'EXACT'
        when (v_charge_difference_pence=1 or v_charge_difference_pence=-1)
          and ((v_charge_source_pence>0 and v_charge_calculated_pence>0)
            or (v_charge_source_pence<0 and v_charge_calculated_pence<0))
          then 'SOURCE_ROUNDING_EQUIVALENT'
        else 'MISMATCH' end;
      if v_result<>'UNVERIFIABLE' and v_result is distinct from v_charge_expected_result then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_RESULT_NOT_REDERIVED' using errcode='22023',
          detail=pg_catalog.jsonb_build_object(
            'source_row_ordinal',v_source_row.source_row_ordinal,
            'contract_id',v_qualification->>'contract_id',
            'claimed_result',v_result,'rederived_result',v_charge_expected_result,
            'signed_difference_pence',v_charge_difference_pence
          )::text;
      end if;
      -- Price does not decide Contract identity. Every safe canonical
      -- observation remains in the reliable base set; warning admission is a
      -- separate Office decision after Contract resolution.
      v_passed:=v_result in ('EXACT','SOURCE_ROUNDING_EQUIVALENT','MISMATCH','ZERO_SOURCE_CHARGE');
      perform 1
      from public.contracts contract
      where contract.id=(v_qualification->>'contract_id')::uuid
        and contract.candidate_id=v_candidate_id
        and contract.client_id=v_client_id
        and v_source_row.work_date between contract.start_date and coalesce(contract.end_date,'infinity'::date)
        and v_eligible_ids ? contract.id::text;
      if not found then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_CONTRACT_OUT_OF_SCOPE' using errcode='22023';
      end if;
      insert into public.weekly_source_contract_qualification_observations(
        upload_row_id,generation,candidate_id,client_id,contract_id,
        source_format_profile_id,qualification_profile_version,
        qualification_profile_fingerprint,contract_revision_fingerprint,
        source_shift_charge_pence,canonical_calculated_pence,
        source_charge_difference_pence,comparison_result,qualification_passed,
        ordered_reason_codes,evidence_fingerprint
      ) values (
        v_source_row.id,v_generation,v_candidate_id,v_client_id,
        (v_qualification->>'contract_id')::uuid,v_upload.source_format_profile_id,
        'NHSP_TWO_COMPONENT_PENCE_V1',
        private.weekly_source_sha256_jsonb_v1('NHSP_QUALIFICATION_PROFILE_V1',v_qualification),
        private.weekly_source_projection_hex32_v1(
          v_qualification->>'contract_revision_fingerprint','WEEKLY_SOURCE_CONTRACT_REVISION_FINGERPRINT_INVALID'
        ),
        v_charge_source_pence,
        v_charge_calculated_pence,
        v_charge_difference_pence,
        v_result,v_passed,
        coalesce(array(select pg_catalog.jsonb_array_elements_text(v_qualification->'reason_codes')),'{}'::text[]),
        private.weekly_source_sha256_jsonb_v1('NHSP_CONTRACT_QUALIFICATION_EVIDENCE_V1',v_qualification)
      );
    end loop;

    v_charge:=v_row_json->'charge_check';
    if v_charge is not null and pg_catalog.jsonb_typeof(v_charge)='object' then
      if v_profile.profile_code not in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1')
         or v_mapping_state<>'RESOLVED' then
        raise exception 'WEEKLY_SOURCE_CHARGE_CHECK_NOT_APPLICABLE' using errcode='22023';
      end if;
      if v_calculation_fingerprint is null then
        raise exception 'WEEKLY_SOURCE_CHARGE_FINGERPRINT_MISSING' using errcode='55000';
      end if;
      if nullif(v_charge->>'charge_calculation_fingerprint','') is not null
         and private.weekly_source_projection_hex32_v1(
               v_charge->>'charge_calculation_fingerprint',
               'WEEKLY_SOURCE_CHARGE_FINGERPRINT_INVALID'
             ) is distinct from v_calculation_fingerprint then
        raise exception 'WEEKLY_SOURCE_CHARGE_FINGERPRINT_MISMATCH' using errcode='22023';
      end if;
      if nullif(v_charge->>'source_commission_pence','')::bigint
            is distinct from v_source_row.source_commission_pence
         or nullif(v_charge->>'source_total_cost_pence','')::bigint
            is distinct from v_source_row.source_total_cost_pence
         or nullif(v_charge->>'source_shift_charge_pence','')::bigint
            is distinct from v_source_row.source_shift_charge_pence
         or nullif(v_charge->>'calculated_segment_charge_pence','')::bigint
            is distinct from v_expected_charge_pence then
        raise exception 'WEEKLY_SOURCE_CHARGE_CHECK_ECONOMIC_MISMATCH' using errcode='22023';
      end if;
      -- G6-2: server-side re-derivation of the NHSP_TWO_COMPONENT_PENCE_V1
      -- verdict. Authority: 25 §6; 24 §13; 14 §4.3 items 1 and 5;
      -- NHSP-BR-013; PRC-006, PRC-007, PRC-020, NHSBR-019, NHSBR-020.
      -- The four inputs are already anchored above to the immutable upload
      -- row and to this server's own canonical calculation, so the verdict
      -- is recomputed here from those facts. A caller may never upgrade a
      -- verdict: anything other than the fail-closed UNVERIFIABLE must equal
      -- the re-derived result, and the sign kind must equal the re-derived
      -- sign kind. EXACT is a zero difference. SOURCE_ROUNDING_EQUIVALENT is
      -- the same non-zero sign on the source and calculated pence with an
      -- absolute difference of exactly one penny in either arithmetic
      -- direction; no directional constraint is permitted.
      v_charge_source_pence:=v_source_row.source_shift_charge_pence;
      v_charge_calculated_pence:=v_expected_charge_pence;
      v_charge_difference_pence:=case
        when v_charge_source_pence is null or v_charge_calculated_pence is null then null
        else v_charge_source_pence-v_charge_calculated_pence end;
      v_charge_expected_sign_kind:=case
        when v_charge_source_pence is null then null
        when v_charge_source_pence>0 then 'POSITIVE'
        when v_charge_source_pence<0 then 'FULL_NEGATIVE'
        when v_charge_calculated_pence>0 then 'POSITIVE'
        when v_charge_calculated_pence<0 then 'FULL_NEGATIVE' end;
      v_charge_expected_result:=case
        when v_source_row.source_commission_pence is null
          or v_source_row.source_total_cost_pence is null
          or v_charge_source_pence is null
          or v_charge_calculated_pence is null then 'UNVERIFIABLE'
        when v_charge_source_pence=0 and v_charge_calculated_pence<>0 then 'ZERO_SOURCE_CHARGE'
        when v_charge_calculated_pence=0 then 'MISMATCH'
        when v_charge_difference_pence=0 then 'EXACT'
        when (v_charge_difference_pence=1 or v_charge_difference_pence=-1)
          and ((v_charge_source_pence>0 and v_charge_calculated_pence>0)
            or (v_charge_source_pence<0 and v_charge_calculated_pence<0))
          then 'SOURCE_ROUNDING_EQUIVALENT'
        else 'MISMATCH' end;
      v_charge_claimed_result:=pg_catalog.upper(pg_catalog.btrim(
        coalesce(v_charge->>'comparison_result','')));
      v_charge_row_sign_kind:=pg_catalog.upper(pg_catalog.btrim(
        coalesce(v_charge->>'row_sign_kind','')));
      if v_charge_claimed_result<>'UNVERIFIABLE'
         and v_charge_claimed_result is distinct from v_charge_expected_result then
        raise exception 'WEEKLY_SOURCE_CHARGE_CHECK_RESULT_NOT_REDERIVED'
          using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'source_row_ordinal',v_source_row.source_row_ordinal,
              'claimed_result',v_charge_claimed_result,
              'rederived_result',v_charge_expected_result,
              'signed_difference_pence',v_charge_difference_pence
            )::text;
      end if;
      if v_charge_claimed_result<>'UNVERIFIABLE'
         and v_charge_row_sign_kind is distinct from v_charge_expected_sign_kind then
        raise exception 'WEEKLY_SOURCE_CHARGE_CHECK_SIGN_NOT_REDERIVED'
          using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'source_row_ordinal',v_source_row.source_row_ordinal,
              'claimed_row_sign_kind',v_charge_row_sign_kind,
              'rederived_row_sign_kind',v_charge_expected_sign_kind
            )::text;
      end if;
      insert into public.weekly_source_charge_checks(
        upload_row_id,row_resolution_id,generation,row_sign_kind,
        source_commission_pence,source_total_cost_pence,source_shift_charge_pence,
        calculated_segment_charge_pence,source_charge_difference_pence,
        comparison_profile_version,comparison_result,comparison_reason_code,
        phase_severity,blocker_code,charge_calculation_fingerprint
      ) values (
        v_source_row.id,v_resolution_id,v_generation,
        coalesce(v_charge_expected_sign_kind,v_charge_row_sign_kind),
        v_source_row.source_commission_pence,
        v_source_row.source_total_cost_pence,
        v_charge_source_pence,
        v_charge_calculated_pence,
        v_charge_difference_pence,
        'NHSP_TWO_COMPONENT_PENCE_V1',v_charge_claimed_result,
        coalesce(v_charge->>'comparison_reason_code',''),pg_catalog.upper(v_charge->>'phase_severity'),
        nullif(v_charge->>'blocker_code',''),
        v_calculation_fingerprint
      );
    end if;

    v_applied:=v_applied+1;
  end loop;

  if v_applied<>v_expected or exists(
    select 1 from public.weekly_source_upload_rows source_row
    where source_row.upload_id=v_upload.id
      and not exists(
        select 1 from public.weekly_source_row_resolutions resolution
        where resolution.upload_row_id=source_row.id and resolution.generation=v_generation
      )
  ) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_RESOLUTION_CENSUS_INCOMPLETE' using errcode='55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'publication_id',v_publication.id,'upload_id',v_upload.id,
    'authority_scope_version',v_publication.authority_scope_version,
    'generation',v_generation,'applied_row_count',v_applied
  );
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'WEEKLY_SOURCE_PROJECTION_VALUE_INVALID' using errcode='22023';
end;
$function$;


create or replace function public.weekly_source_combined_review_workspace_v1(p_request jsonb)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_request jsonb; v_scope_page jsonb; v_scopes jsonb:='[]'; v_scope jsonb;
  v_workspace jsonb; v_owner_request jsonb; v_rows jsonb:='[]'; v_item jsonb;
  v_manual_children jsonb; v_question_children jsonb; v_child jsonb;
  v_follow_workspace jsonb; v_follow_up jsonb;
  v_versions jsonb:='[]'; v_owners jsonb:='[]'; v_summary jsonb;
  v_tab text:=coalesce(nullif(p_request->>'tab',''),'queries');
  v_section text:=coalesce(nullif(p_request->>'section',''),'questions');
  v_sort text:=coalesce(nullif(p_request->>'sort_key',''),case when nullif(p_request->>'client_id','') is null then 'client' else 'candidate' end);
  v_direction text:=coalesce(nullif(p_request->>'sort_direction',''),'asc');
  v_seek text:=private.weekly_source_query_ascii_fold_v1(coalesce(p_request->>'seek',''));
  v_limit integer:=coalesce((p_request->>'limit')::integer,50);
  v_offset integer:=0; v_base integer:=0; v_total integer; v_page jsonb; v_counts jsonb;
  v_version text; v_cursor jsonb; v_client uuid; v_seen text[]:='{}'; v_key text; v_owner_key text;
  v_attention jsonb; v_attention_first boolean:=coalesce((p_request->>'attention_first')::boolean,false);
  v_attention_kind text:=coalesce(p_request->>'attention_kind','');
  v_pending record; v_pending_checks jsonb:='[]'::jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  perform private._weekly_source_settings_assert_request_v1(p_request,
    array['actor_user_id','source_group_id','client_id','week_ending','tab','section',
      'sort_key','sort_direction','seek','cursor','limit','report_key','attention_first','attention_kind'],'WEEKLY_SOURCE_COMBINED_REQUEST_INVALID');
  if v_tab='history' then
    return public.weekly_source_report_history_v1(p_request-'tab'-'section');
  end if;
  if p_request ? 'report_key' then
    raise exception 'WEEKLY_SOURCE_COMBINED_REQUEST_INVALID' using errcode='22023';
  end if;
  if v_tab not in ('imports','queries') or v_section not in ('questions','checks','protected','current','archive')
    or v_sort not in ('client','candidate','day_date','status','file','uploaded')
    or v_direction not in ('asc','desc') or v_limit not between 1 and 100 or length(v_seek)>100
    or v_attention_kind not in ('','missing_source','questions','checks','protected')
    or (p_request ? 'attention_first' and jsonb_typeof(p_request->'attention_first')<>'boolean') then
    raise exception 'WEEKLY_SOURCE_COMBINED_REQUEST_INVALID' using errcode='22023';
  end if;
  v_client:=nullif(p_request->>'client_id','')::uuid;
  v_request:=p_request-'tab'-'section'-'sort_key'-'sort_direction'-'seek'-'cursor'-'limit'-'attention_first'-'attention_kind';
  loop
    v_scope_page:=public.weekly_source_workspace_scopes_v1(v_request);
    v_summary:=v_scope_page-'rows'-'next_cursor'-'has_more';
    v_scopes:=v_scopes||(v_scope_page->'rows');
    exit when not (v_scope_page->>'has_more')::boolean;
    v_request:=v_request||jsonb_build_object('cursor',v_scope_page->>'next_cursor');
  end loop;
  -- A cycle publication is shared across its client scopes. If it has no
  -- cycle publication, each NHSP client's current report scope can instead
  -- own distinct query work. Visit each such scope exactly once.
  for v_scope in select distinct on (item->>'source_cycle_id',
      case when v_tab='queries' and cycle.current_projection_publication_id is null then item->>'client_id' else '' end)
      item||jsonb_build_object('cycle_publication_id',cycle.current_projection_publication_id)
    from jsonb_array_elements(v_scopes) item
    join public.weekly_source_cycles cycle on cycle.id=(item->>'source_cycle_id')::uuid
    order by item->>'source_cycle_id',
      case when v_tab='queries' and cycle.current_projection_publication_id is null then item->>'client_id' else '' end,
      case when item->>'report_scope_id' is null then 1 else 0 end,
      item->>'cutoff' desc nulls last,item->>'key'
  loop
    v_owner_request:=jsonb_build_object('actor_user_id',p_request->>'actor_user_id',
      'tab',v_tab,'source_group_id',v_scope->>'source_group_id',
      'source_cycle_id',v_scope->>'source_cycle_id','limit',100);
    if v_scope->>'source_family'='ROSTER' or
      (v_tab='queries' and v_scope->>'source_family'='NHSP' and v_scope->>'cycle_publication_id' is null
        and v_scope->>'report_scope_id' is not null) then
      v_owner_request:=v_owner_request||jsonb_build_object('client_id',v_scope->>'client_id');
    end if;
    if v_tab='queries' and v_scope->>'source_family'='NHSP' and v_scope->>'cycle_publication_id' is null
      and v_scope->>'report_scope_id' is not null then
      v_owner_request:=v_owner_request||jsonb_build_object('report_scope_id',v_scope->>'report_scope_id');
    end if;
    loop
      v_workspace:=public.weekly_source_office_workspace_v1(v_owner_request);
      v_owner_key:=case when v_tab='imports' then v_scope->>'source_cycle_id'
        else (v_scope->>'source_cycle_id')||':'||
          coalesce(v_workspace#>>'{selected,projection_publication_id}','none') end;
      v_versions:=v_versions||jsonb_build_array(jsonb_build_array(v_scope->>'source_cycle_id',v_workspace->>'workspace_version'));
      if not (v_owner_request ? 'cursor') then
        v_owners:=v_owners||jsonb_build_array(jsonb_build_object('key',v_owner_key,
          'source',v_scope->>'source','period',v_scope->>'period','scope',v_workspace->'selected',
          'bulk_actions',v_workspace#>'{queries,bulk_actions}',
          'protected_pay_enabled',v_workspace#>'{queries,protected_pay_enabled}'));
      end if;
      for v_item in select item from jsonb_array_elements(coalesce(v_workspace#>array[v_tab,'rows'],'[]')) item
      loop
        v_key:=v_tab||':'||v_owner_key;
        v_key:=v_key||':'||(v_item->>'row_key');
        if v_key=any(v_seen) then continue; end if;
        v_seen:=array_append(v_seen,v_key);
        if nullif(v_item->>'client_id','') is not null and not exists(select 1
          from jsonb_array_elements(v_scopes) permitted where permitted->>'source_cycle_id'=v_scope->>'source_cycle_id'
            and permitted->>'client_id'=v_item->>'client_id') then continue; end if;
        if v_client is not null and nullif(v_item->>'client_id','') is not null
          and (v_item->>'client_id')::uuid<>v_client then continue; end if;
        if v_tab='imports' then
          -- Upload errors remain in their immediate review receipt, not an
          -- ever-growing archive. Retain only accepted current work here.
          if v_item->>'state' is distinct from 'CURRENT' then continue; end if;
          if exists(select 1 from public.weekly_source_final_revisions revision
            join public.weekly_source_client_manifests manifest on manifest.final_revision_id=revision.id
            where revision.upload_id=(v_item->>'row_key')::uuid
              and revision.state in ('CURRENT','SUPERSEDED')
              and (nullif(v_item->>'client_id','') is null
                or manifest.client_id=(v_item->>'client_id')::uuid))
            and not exists(select 1 from jsonb_array_elements(v_scopes) sibling
              where sibling->>'upload_id'=v_item->>'row_key'
                and not coalesce((sibling->>'completed')::boolean,false)) then continue; end if;
        end if;
        if v_tab='queries' then
          -- An Office-created pay review is an Office check, not a request for
          -- candidate/manager hours evidence. Split only those children so a
          -- mixed group can retain its genuine Hours questions independently.
          select coalesce(jsonb_agg(child.value order by child.ordinality)
              filter(where child.value ? 'manual_review_id'),'[]'::jsonb),
            coalesce(jsonb_agg(child.value order by child.ordinality)
              filter(where not (child.value ? 'manual_review_id')),'[]'::jsonb)
            into v_manual_children,v_question_children
          from jsonb_array_elements(coalesce(v_item->'children','[]'::jsonb))
            with ordinality child(value,ordinality);
          for v_child in select value from jsonb_array_elements(v_manual_children)
          loop
            v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
              'combined_key','manual-check:'||(v_child->>'manual_review_id'),
              'row_key',v_child->>'row_key','section','checks',
              'scope_key',v_owner_key,
              'source',v_scope->>'source','source_family',v_scope->>'source_family',
              'period',v_scope->>'period',
              'client',v_item->>'client','client_id',v_item->>'client_id',
              'candidate',v_item->>'candidate','candidate_id',v_item->>'candidate_id',
              'day_date',v_child->>'day_date','system_hours',v_child->>'system_hours',
              'status',v_child->'status','manual_query',v_child->'manual_query',
              'problem','Accept current source hours or protect pay.',
              'pay_blocking',true,'actions',v_child->'actions'));
          end loop;
          if jsonb_array_length(v_question_children)=0 then continue; end if;
          if jsonb_array_length(v_manual_children)>0 then
            v_item:=jsonb_set(v_item,'{actions,0,payload,detail,shifts}',v_question_children,false)
              ||jsonb_build_object('children',v_question_children,
                'issues',greatest(0,coalesce((v_item->>'issues')::integer,0)
                  -jsonb_array_length(v_manual_children)));
          end if;
        end if;
        v_rows:=v_rows||jsonb_build_array(v_item||jsonb_build_object(
          'combined_key',v_key,'scope_key',v_owner_key,'source',v_scope->>'source',
          'source_family',v_scope->>'source_family',
          'period',v_scope->>'period','section',case when v_tab='queries' then 'questions' else 'current' end,
          'client',coalesce(nullif(v_item->>'client',''),(select name from public.clients
            where id=nullif(v_item->>'client_id','')::uuid),'Source-wide file')));
      end loop;
      if v_tab='queries' and not (v_owner_request ? 'cursor') then
        for v_item in
          select item||jsonb_build_object('section','checks') from jsonb_array_elements(coalesce(v_workspace#>'{queries,office_checks,rows}','[]')) item
          union all
          select item||jsonb_build_object('section','protected') from jsonb_array_elements(coalesce(v_workspace#>'{queries,protected_shifts,rows}','[]')) item
        loop
          v_key:=case when v_item->>'section'='protected' then
            'protected:'||(v_item->>'family_id')||':'||(v_item->>'work_event_id')
            else (v_item->>'section')||':'||v_owner_key||':'||(v_item->>'row_key') end;
          if v_key=any(v_seen) then continue; end if;
          v_seen:=array_append(v_seen,v_key);
          if nullif(v_item->>'client_id','') is not null and not exists(select 1
            from jsonb_array_elements(v_scopes) permitted where permitted->>'source_group_id'=v_scope->>'source_group_id'
              and permitted->>'client_id'=v_item->>'client_id') then continue; end if;
          if v_client is not null and nullif(v_item->>'client_id','') is not null
            and (v_item->>'client_id')::uuid<>v_client then continue; end if;
          v_rows:=v_rows||jsonb_build_array(v_item||jsonb_build_object('combined_key',v_key,
            'scope_key',v_owner_key,'source',v_scope->>'source','period',
              case when v_item->>'section'='protected' then 'Awaiting source period' else v_scope->>'period' end));
        end loop;
      end if;
      exit when not coalesce((v_workspace#>>array[v_tab,'has_more'])::boolean,false);
      v_owner_request:=v_owner_request||jsonb_build_object('cursor',v_workspace#>>array[v_tab,'next_cursor']);
    end loop;
  end loop;
  -- Finalisation does not complete its separately tracked approved-hours work.
  -- Keep that exact owner/action reachable from outstanding Office checks.
  if v_tab='queries' then
    for v_scope in select item from jsonb_array_elements(v_scopes) item
      where item->>'completion_kind'='FINAL_SOURCE'
    loop
      v_follow_workspace:=public.weekly_source_office_workspace_v1(jsonb_build_object(
        'actor_user_id',p_request->>'actor_user_id','tab','finalise',
        'source_group_id',v_scope->>'source_group_id','source_cycle_id',v_scope->>'source_cycle_id',
        'client_id',v_scope->>'client_id','report_scope_id',v_scope->>'report_scope_id'));
      v_follow_up:=v_follow_workspace#>'{finalise,approved_hours_follow_up}';
      if nullif(v_follow_up->>'title','') is null then continue; end if;
      v_key:='approved-hours:'||(v_scope->>'key');
      v_versions:=v_versions||jsonb_build_array(jsonb_build_array(v_key,v_follow_workspace->>'workspace_version',v_follow_up));
      v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
        'combined_key',v_key,'row_key',v_key,'section','checks',
        'client',v_scope->>'client','client_id',v_scope->>'client_id',
        'source',v_scope->>'source','period',v_scope->>'period',
        'candidate','Report follow-up','requires_attention',
          v_follow_up->>'state' in ('ACTION_REQUIRED','RECOVERY_REQUIRED')
          or jsonb_typeof(v_follow_up->'action')='object',
        'status',jsonb_build_object('text',v_follow_up->>'title'),
        'problem',v_follow_up->>'body','follow_up_scope',v_follow_workspace->'selected','actions','[]'::jsonb));
    end loop;
  end if;
  -- Rechecks invalidate the old authority before the replacement is ready.
  -- Retain old unresolved rows as explicitly non-actionable history, with only
  -- the exact saved recheck available. Never treat a missing CURRENT pointer
  -- as proof that Office has no work remaining.
  if v_tab='queries' then
    for v_pending in
      select recheck.request_id,recheck.actor_user_id,recheck.request_json,
        recheck.upload_id,recheck.publication_id,source_row.id as upload_row_id,
        source_row.work_date,source_row.source_client_identity,source_row.source_candidate_identity,
        source_row.external_source_key,source_row.start_at_local,source_row.end_at_local,source_row.break_minutes,
        coalesce(candidate.display_name,source_row.bounded_raw_columns_json->>'worker_name',
          source_row.bounded_raw_columns_json->>'candidate',source_row.source_candidate_identity) as candidate_name,
        resolution.mapping_state,charge.phase_severity,cycle.source_group_id,cycle.finalisation_week_ending,
        (select item->>'source' from jsonb_array_elements(v_scopes) item
          where item->>'source_cycle_id'=cycle.id::text limit 1) as source_name
      from private.weekly_source_office_rechecks recheck
      join public.weekly_source_projection_publications publication on publication.id=recheck.publication_id
      join public.weekly_source_projection_publications prior_publication on prior_publication.id=recheck.prior_publication_id
      join public.weekly_source_uploads upload on upload.id=recheck.upload_id
      join public.weekly_source_cycles cycle on cycle.id=upload.source_cycle_id
      left join public.weekly_source_report_scopes scope on scope.id=upload.report_scope_id
      join public.weekly_source_upload_rows source_row on source_row.upload_id=upload.id
      join public.weekly_source_row_resolutions resolution on resolution.upload_row_id=source_row.id
        and resolution.generation=coalesce(prior_publication.projection_generation,prior_publication.authority_scope_version)
      left join public.weekly_source_charge_checks charge on charge.upload_row_id=source_row.id
        and charge.generation=resolution.generation
      left join public.candidates candidate on candidate.id=coalesce(
        (select choice.candidate_id from private.weekly_source_office_row_choices choice
          where choice.upload_row_id=source_row.id order by choice.id desc limit 1),resolution.candidate_id)
      where publication.state='BUILDING' and upload.state='CURRENT'
        and publication.authority_scope_version=case when upload.report_scope_id is null then cycle.version else scope.version end
        and upload.id=case when upload.report_scope_id is null then cycle.current_complete_upload_id else scope.current_complete_upload_id end
        and exists(select 1 from jsonb_array_elements(v_scopes) item where item->>'source_cycle_id'=cycle.id::text)
        and (v_client is null or resolution.client_id=v_client or scope.client_id=v_client)
      order by recheck.request_id,source_row.source_row_ordinal
    loop
      v_key:='recheck:'||v_pending.request_id::text||':'||v_pending.upload_row_id::text;
      v_pending_checks:=v_pending_checks||jsonb_build_array(jsonb_build_object(
        'combined_key',v_key,'row_key',v_key,'section','checks','recheck_pending',true,
        'client',v_pending.source_client_identity,'candidate',v_pending.candidate_name,
        'source_reference',v_pending.source_candidate_identity,'booking_reference',v_pending.external_source_key,
        'source',v_pending.source_name,'period',to_char(v_pending.finalisation_week_ending,'FMDD Mon YYYY'),
        'work_date',v_pending.work_date,'day_date',to_char(v_pending.work_date,'FMDD Mon YYYY'),
        'system_hours',to_char(v_pending.start_at_local,'HH24:MI')||'–'||to_char(v_pending.end_at_local,'HH24:MI')
          ||' · '||v_pending.break_minutes::text||' min break',
        'pay_blocking',v_pending.mapping_state<>'RESOLVED',
        'status',jsonb_build_object('text','Recheck incomplete'),
        'problem',case when v_pending.mapping_state<>'RESOLVED' then 'Previous linking check — selection saved; replacement check incomplete.'
          when v_pending.phase_severity in ('PROVISIONAL_WARNING','FINALISATION_BLOCKER') then 'Previous contract charge warning — replacement check incomplete.'
          else 'Previous check — replacement check incomplete.' end,
        'actions',jsonb_build_array(jsonb_build_object('label','Retry recheck',
          'enabled',v_pending.actor_user_id=(p_request->>'actor_user_id')::uuid,
          'command','RECHECK_SOURCE','payload',v_pending.request_json-'actor_user_id'))));
    end loop;
    v_rows:=v_rows||v_pending_checks;
    v_summary:=v_summary||jsonb_build_object('recheck_pending_count',jsonb_array_length(v_pending_checks));
  end if;
  -- Classify the complete permitted collection before counting or paging.
  -- A waiting signature alone is informational; red unresolved work and green
  -- charge/reconciliation decisions remain visible and count as Office work.
  select coalesce(jsonb_agg(item||jsonb_build_object(
    'attention_missing_source_count',case when item->>'section'='questions' then
      (select count(*) from jsonb_array_elements(coalesce(item->'children','[]')) child
        where child->'candidate_shift_absent_from_import'='true'::jsonb) else 0 end,
    'attention_question_count',case when item->>'section'='questions' then
      (select count(*) from jsonb_array_elements(coalesce(item->'children','[]')) child
        where child->>'issue' is distinct from 'Timesheet missing'
          and child->'candidate_shift_absent_from_import' is distinct from 'true'::jsonb) else 0 end,
    'requires_attention',case
    when item->>'section'='questions' then exists(select 1
      from jsonb_array_elements(coalesce(item->'children','[]')) child
      where child->>'issue' is distinct from 'Timesheet missing')
    when item->>'section'='checks' then case when item ? 'follow_up_scope'
      then coalesce((item->>'requires_attention')::boolean,false) else true end
    when item->>'section'='protected' then coalesce((item->>'requires_attention')::boolean,false)
    else false end)),'[]') into v_rows from jsonb_array_elements(v_rows) item;
  select jsonb_build_object('missing_source',coalesce(sum((item->>'attention_missing_source_count')::integer),0),
    'questions',coalesce(sum((item->>'attention_question_count')::integer),0),
    'checks',count(*) filter(where item->>'section'='checks'),
    'protected',count(*) filter(where item->>'section'='protected'),
    'total',coalesce(sum((item->>'attention_missing_source_count')::integer
      +(item->>'attention_question_count')::integer),0)
      +count(*) filter(where item->>'section' in ('checks','protected')),'complete',true) into v_attention
  from jsonb_array_elements(v_rows) item where item->'requires_attention'='true'::jsonb;
  select jsonb_build_object('questions',count(*) filter(where item->>'section'='questions'),
    'checks',count(*) filter(where item->>'section'='checks'),'protected',count(*) filter(where item->>'section'='protected'),
    'current',count(*) filter(where item->>'section'='current'),'archive',count(*) filter(where item->>'section'='archive'))
    into v_counts from jsonb_array_elements(v_rows) item;
  v_version:=encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_COMBINED_REVIEW_V1',
    jsonb_build_object('scopes',v_summary->>'version','owners',v_versions,'attention_rows',v_rows,
      'filters',p_request-'cursor'-'limit')),'hex');
  -- Attention is an exact view filter, not a tab-total alias. The full census
  -- above stays intact; only this page collection is narrowed. Never rewrite
  -- server-owned action selections or comparison/financial proof payloads.
  if v_attention_kind<>'' then
    select coalesce(jsonb_agg(item),'[]') into v_rows from jsonb_array_elements(v_rows) item
    where item->'requires_attention'='true'::jsonb and case v_attention_kind
      when 'missing_source' then item->>'section'='questions' and (item->>'attention_missing_source_count')::integer>0
      when 'questions' then item->>'section'='questions' and (item->>'attention_question_count')::integer>0
      when 'checks' then item->>'section'='checks'
      when 'protected' then item->>'section'='protected'
      else false end;
    if v_attention_kind in ('missing_source','questions') then
      for v_item in select item from jsonb_array_elements(v_rows) item
      loop
        select coalesce(jsonb_agg(child.value order by child.ordinality),'[]') into v_question_children
          from jsonb_array_elements(v_item->'children') with ordinality child(value,ordinality)
          where child.value->>'issue' is distinct from 'Timesheet missing' and case v_attention_kind
            when 'missing_source' then child.value->'candidate_shift_absent_from_import'='true'::jsonb
            else child.value->'candidate_shift_absent_from_import' is distinct from 'true'::jsonb end;
        v_item:=v_item||jsonb_build_object('children',v_question_children,'issues',jsonb_array_length(v_question_children),
          'actions',(select coalesce(jsonb_agg(case when action->>'label'='Open'
            then jsonb_set(action,'{payload,detail,shifts}',v_question_children,false) else action end),'[]')
            from jsonb_array_elements(coalesce(v_item->'actions','[]')) action));
        select coalesce(jsonb_agg(case when item->>'combined_key'=v_item->>'combined_key' then v_item else item end),'[]')
          into v_rows from jsonb_array_elements(v_rows) item;
      end loop;
    end if;
  end if;
  if nullif(p_request->>'cursor','') is not null then
    begin
      v_cursor:=convert_from(decode(p_request->>'cursor','base64'),'UTF8')::jsonb;
      v_offset:=(v_cursor->>'offset')::integer;
      if v_offset is null or v_offset<0 or v_cursor->>'version' is distinct from v_version then raise exception 'stale'; end if;
    exception when others then raise exception 'WEEKLY_SOURCE_WORKSPACE_CURSOR_STALE' using errcode='40001'; end;
  end if;
  with keyed as (
    select item,private.weekly_source_query_ascii_fold_v1(coalesce(case v_sort
      when 'candidate' then coalesce(item->>'candidate_sort',item->>'candidate') when 'client' then item->>'client'
      when 'day_date' then item->>'work_date' when 'file' then item->>'file' when 'uploaded' then item->>'uploaded_at'
      when 'status' then item#>>'{status,text}' end,'')) sort_value
    from jsonb_array_elements(v_rows) item where item->>'section'=v_section
  ), ordered as (
    select *,row_number() over(order by case when v_attention_first and v_seek='' then
      case v_attention_kind when 'missing_source' then ((item->>'attention_missing_source_count')::integer>0)::integer
        when 'questions' then ((item->>'attention_question_count')::integer>0)::integer
        else 0 end else 0 end desc,
      case when v_attention_first and v_seek=''
      then coalesce((item->>'requires_attention')::boolean,false)::integer else 0 end desc,
      case when v_direction='asc' then sort_value end collate "C" asc,
      case when v_direction='desc' then sort_value end collate "C" desc,
      private.weekly_source_query_ascii_fold_v1(item->>'client') collate "C",
      private.weekly_source_query_ascii_fold_v1(coalesce(item->>'candidate_sort',item->>'candidate')) collate "C",
      item->>'work_date',item->>'combined_key') ordinal from keyed
  ), origin as (select coalesce(min(ordinal) filter(where v_seek<>'' and starts_with(sort_value,v_seek)),1)-1 base from ordered)
  select count(*)::integer,coalesce(max(origin.base),0)::integer,coalesce(jsonb_agg(item order by ordinal)
    filter(where ordinal>origin.base+v_offset and ordinal<=origin.base+v_offset+v_limit),'[]')
    into v_total,v_base,v_page from ordered cross join origin;
  return jsonb_build_object('ok',true,'contract','WEEKLY_SOURCE_COMBINED_REVIEW_V1','tab',v_tab,'section',v_section,
    'version',v_version,'rows',v_page,'total_count',v_total,'owners',v_owners,'scope_options',v_scopes,
    'summary',v_summary,'counts',v_counts,'attention',v_attention,
    'attention_kind',v_attention_kind,
    'sort_key',v_sort,'sort_direction',v_direction,
    'has_more',v_base+v_offset+v_limit<v_total,'next_cursor',case when v_base+v_offset+v_limit<v_total
      then encode(convert_to(jsonb_build_object('version',v_version,'offset',v_offset+v_limit)::text,'UTF8'),'base64') else '' end);
end;
$function$;

alter function public.weekly_source_projection_rows_apply_atomic_v1(uuid,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_projection_rows_apply_atomic_v1(uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_projection_rows_apply_atomic_v1(uuid,uuid,jsonb) to service_role;
alter function public.weekly_source_combined_review_workspace_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_combined_review_workspace_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_combined_review_workspace_v1(jsonb) to service_role;
notify pgrst, 'reload schema';


-- CONTACT_PREPARER_UNIT 37 repeatable supabase/repeatable/08102026_1635_weekly_source_released_client_eligibility_v1.sql SHA256 e60461a8b191bff635356a50df680193e4d30e65762e8d2911cdef2b20180e59
-- Repeatable CloudTMS authority: released NHSP row-wise client eligibility.
-- Full replacements preserve the established service/Office authority,
-- concurrency, replay, immutable source, contract and finance boundaries.




-- Client eligibility is derived from the saved profile, never a caller flag.
-- Previously released NHSP checking files may contain any NHSP-enabled client.
-- Use the existing effective-date settings order; older/future true flags must
-- not override the applicable setting. Missing settings fail closed.
-- Final backing reports and every other profile retain their source membership
-- and exact report-client boundaries. Contract/policy eligibility is unchanged.
create or replace function private.weekly_source_upload_client_eligible_v1(
  p_upload_id uuid,p_client_id uuid,p_work_date date
) returns boolean
language sql stable
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  select p_work_date is not null and exists(
    select 1
    from public.weekly_source_uploads upload
    join public.weekly_source_format_profiles profile on profile.id=upload.source_format_profile_id
    join public.weekly_source_cycles cycle on cycle.id=upload.source_cycle_id
    join public.weekly_source_groups source_group on source_group.id=cycle.source_group_id
    join public.clients client on client.id=p_client_id
    left join public.weekly_source_report_scopes scope on scope.id=upload.report_scope_id
    where upload.id=p_upload_id
      and case when profile.profile_code='NHSP_PREFINAL_RELEASED_V1' then
        source_group.source_family='NHSP'
        and upload.report_scope_id is null
        and profile.row_finalisation_capability='CHECKING_ONLY'
        and not profile.single_client_required
        and coalesce((
          select settings.is_nhsp
          from public.client_settings settings
          where settings.client_id=client.id
            and (settings.effective_from is null or settings.effective_from<=p_work_date)
          order by settings.effective_from desc nulls last,settings.updated_at desc,settings.id desc
          limit 1
        ),false)
      else
        exists(select 1 from public.weekly_source_group_clients membership
          where membership.source_group_id=cycle.source_group_id
            and membership.client_id=client.id
            and p_work_date between membership.valid_from and coalesce(membership.valid_to,'infinity'::date))
        and (upload.report_scope_id is null or (
          scope.client_id=client.id and scope.source_cycle_id=cycle.id
          and scope.source_group_id=cycle.source_group_id))
      end
  );
$function$;
alter function private.weekly_source_upload_client_eligible_v1(uuid,uuid,date) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_upload_client_eligible_v1(uuid,uuid,date)
  from public,anon,authenticated,service_role;

create or replace function public.weekly_source_upload_context_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_allowed constant text[]:=array[
    'operation','actor_user_id','source_group_id','source_cycle_id',
    'report_scope_id','client_id','upload_id'
  ]::text[];
  v_operation text;
  v_actor uuid;
  v_group_id uuid;
  v_cycle_id uuid;
  v_report_scope_id uuid;
  v_client_id uuid;
  v_row_client_id uuid;
  v_upload_id uuid;
  v_group public.weekly_source_groups%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_source_row public.weekly_source_upload_rows%rowtype;
  v_office_choice private.weekly_source_office_row_choices%rowtype;
  v_source_name text;
  v_source_id text;
  v_source_id_2 text;
  v_source_id_3 text;
  v_source_client text;
  v_norm_name text;
  v_norm_compact text;
  v_candidate_ids uuid[];
  v_candidate_id uuid;
  v_candidate_matches jsonb;
  v_contracts jsonb;
  v_prior_contract_id uuid;
  v_prior_work_event_id uuid;
  -- WP-37: the `24 §9` step-2 compatible-schedule set, counted explicitly.
  v_prior_candidate_count integer;
  v_rows jsonb:='[]'::jsonb;
  v_client_name text;
  v_client_choices jsonb:='[]'::jsonb;
  v_client_choice_count integer:=0;
  v_unknown text;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CONTEXT_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown
  from pg_catalog.jsonb_object_keys(p_request) key
  where not key=any(v_allowed)
  order by key limit 1;
  if v_unknown is not null then
    raise exception 'WEEKLY_SOURCE_CONTEXT_UNKNOWN_FIELD'
      using errcode='22023',detail=v_unknown;
  end if;
  begin
    v_operation:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'operation','')));
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_group_id:=nullif(p_request->>'source_group_id','')::uuid;
    v_cycle_id:=nullif(p_request->>'source_cycle_id','')::uuid;
    v_report_scope_id:=nullif(p_request->>'report_scope_id','')::uuid;
    v_client_id:=nullif(p_request->>'client_id','')::uuid;
    v_upload_id:=nullif(p_request->>'upload_id','')::uuid;
  exception when invalid_text_representation then
    raise exception 'WEEKLY_SOURCE_CONTEXT_REQUEST_INVALID' using errcode='22023';
  end;
  if v_actor is null or v_operation not in ('DISCOVER_SCOPE','BUILD_PROJECTION') then
    raise exception 'WEEKLY_SOURCE_CONTEXT_REQUEST_INVALID' using errcode='22023';
  end if;

  if v_operation='BUILD_PROJECTION' then
    if v_upload_id is null then
      raise exception 'WEEKLY_SOURCE_CONTEXT_UPLOAD_REQUIRED' using errcode='22023';
    end if;
    select * into v_upload from public.weekly_source_uploads where id=v_upload_id;
    if not found or v_upload.state not in ('CURRENT','CORRECTION_READY')
       or v_upload.row_manifest_hash is null then
      raise exception 'WEEKLY_SOURCE_CONTEXT_UPLOAD_NOT_SEALED' using errcode='55000';
    end if;
    v_cycle_id:=v_upload.source_cycle_id;
    v_report_scope_id:=v_upload.report_scope_id;
  elsif v_cycle_id is null then
    raise exception 'WEEKLY_SOURCE_CONTEXT_SCOPE_REQUIRED' using errcode='22023';
  end if;

  select * into v_cycle from public.weekly_source_cycles where id=v_cycle_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CONTEXT_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select * into v_group from public.weekly_source_groups where id=v_cycle.source_group_id;
  if not found or not v_group.active
     or (v_group_id is not null and v_group.id is distinct from v_group_id) then
    raise exception 'WEEKLY_SOURCE_CONTEXT_GROUP_MISMATCH' using errcode='22023';
  end if;
  v_group_id:=v_group.id;

  if v_report_scope_id is not null then
    select * into v_scope
    from public.weekly_source_report_scopes where id=v_report_scope_id;
    if not found or v_group.source_family<>'NHSP'
       or v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id
       or v_scope.environment is distinct from v_group.environment
       or v_scope.agency_id is distinct from v_group.agency_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc
       or (v_client_id is not null and v_scope.client_id is distinct from v_client_id) then
      raise exception 'WEEKLY_SOURCE_CONTEXT_REPORT_SCOPE_MISMATCH' using errcode='22023';
    end if;
    v_client_id:=v_scope.client_id;
  else
    if v_group.source_family='NHSP' and v_operation='BUILD_PROJECTION'
       and exists(
         select 1 from public.weekly_source_format_profiles profile
         where profile.id=v_upload.source_format_profile_id
           and profile.profile_code='NHSP_FINAL_BACKING_V1'
       ) then
      raise exception 'WEEKLY_SOURCE_CONTEXT_REPORT_SCOPE_REQUIRED' using errcode='22023';
    end if;
    if v_operation='BUILD_PROJECTION' then
      begin
        v_client_id:=nullif(v_upload.file_metadata_json->>'client_id','')::uuid;
      exception when invalid_text_representation then
        raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_INVALID' using errcode='55000';
      end;
    end if;
    if v_client_id is not null and not exists(
      select 1 from public.weekly_source_group_clients membership
      where membership.source_group_id=v_group.id
        and membership.client_id=v_client_id
        and v_cycle.finalisation_week_ending between membership.valid_from
          and coalesce(membership.valid_to,'infinity'::date)
    ) then
      raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_SCOPE_MISMATCH' using errcode='22023';
    end if;
  end if;
  if v_client_id is not null then
    if v_operation='BUILD_PROJECTION' and v_cycle.scope_client_id is not null and v_cycle.scope_client_id<>v_client_id then
      raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_SCOPE_MISMATCH' using errcode='22023';
    end if;
    select client.name into strict v_client_name
    from public.clients client where client.id=v_client_id;
  elsif v_group.source_family='ROSTER' then
    select pg_catalog.count(*),coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object('client_id',client.id,'client_name',client.name)
      order by client.name,client.id
    ),'[]'::jsonb)
      into v_client_choice_count,v_client_choices
    from public.weekly_source_group_clients membership
    join public.clients client on client.id=membership.client_id
    where membership.source_group_id=v_group.id
      and v_cycle.finalisation_week_ending between membership.valid_from
        and coalesce(membership.valid_to,'infinity'::date);
    if v_client_choice_count=1 then
      v_client_id:=(v_client_choices->0->>'client_id')::uuid;
      v_client_name:=v_client_choices->0->>'client_name';
    elsif v_client_choice_count=0 then
      raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_NOT_FOUND' using errcode='22023';
    end if;
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,
    case when v_operation='DISCOVER_SCOPE' then 'UPLOAD_SOURCE' else 'RECHECK_SOURCE' end,
    v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );

  if v_operation='DISCOVER_SCOPE' then
    return pg_catalog.jsonb_build_object(
      'ok',true,'context_version','WEEKLY_SOURCE_UPLOAD_CONTEXT_V1',
      'environment',v_group.environment,'agency_id',v_group.agency_id,
      'source_group_id',v_group.id,'source_group_code',v_group.code,
      'source_group_name',v_group.display_name,'source_family',v_group.source_family,
      'source_cycle_id',v_cycle.id,'finalisation_week_ending',v_cycle.finalisation_week_ending,
      'cutoff_at_utc',v_cycle.cutoff_at_utc,'cycle_state',v_cycle.state,
      'previous_coverage',(
        select pg_catalog.jsonb_build_object(
          'start_local_date',prior.confirmed_coverage_start_local_date,
          'end_local_date',prior.confirmed_coverage_end_local_date
        )
        from public.weekly_source_uploads prior
        where prior.id=v_cycle.current_complete_upload_id
          and prior.state='CURRENT'
      ),
      'report_scope_id',v_report_scope_id,'client_id',v_client_id,
      'client_name',v_client_name,'nhsp_report_heading_name',v_group.nhsp_report_heading_name,
      'client_selection_required',v_group.source_family='ROSTER' and v_client_id is null,
      'client_choices',v_client_choices,
      'authority_scope_version',coalesce(v_scope.version,v_cycle.version),
      'authority_scope_kind',case when v_report_scope_id is null then 'CYCLE' else 'NHSP_REPORT_SCOPE' end
    );
  end if;

  select * into strict v_profile
  from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;

  for v_source_row in
    select source_row.*
    from public.weekly_source_upload_rows source_row
    where source_row.upload_id=v_upload.id
    order by source_row.source_row_ordinal,source_row.id
  loop
    -- Released reports identify the client on each row. A legacy upload-level
    -- client hint must not silently assign every row to that one client.
    v_row_client_id:=case when v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1'
      then null else v_client_id end;
    select * into v_office_choice from private.weekly_source_office_row_choices
      where upload_row_id=v_source_row.id order by id desc limit 1;
    v_source_name:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'worker_name',
      v_source_row.bounded_raw_columns_json->>'candidate',
      v_source_row.source_candidate_identity
    )), '');
    v_source_id:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'worker_unique_id',
      v_source_row.bounded_raw_columns_json->>'candidate_id',''
    )), '');
    v_source_id_2:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'candidate_uid',''
    )), '');
    v_source_id_3:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'payroll_number',''
    )), '');
    v_source_client:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'trust',
      v_source_row.source_client_identity
    )), '');
    if v_row_client_id is null and v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1' then
      select case when pg_catalog.count(*)=1 then pg_catalog.min(client.id::text)::uuid end
        into v_row_client_id
      from public.clients client
      where private.weekly_source_upload_client_eligible_v1(
          v_upload.id,client.id,v_source_row.work_date)
        and pg_catalog.lower(pg_catalog.btrim(client.name))=
          pg_catalog.lower(pg_catalog.btrim(coalesce(v_source_client,'')));
    end if;
    if v_office_choice.client_id is not null then
      select client.id into v_row_client_id
      from public.clients client
      where client.id=v_office_choice.client_id
        and private.weekly_source_upload_client_eligible_v1(
          v_upload.id,client.id,v_source_row.work_date);
    end if;
    v_norm_name:=pg_catalog.lower(pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(v_source_name,'')),'[[:space:]]+',' ','g'
    ));
    v_norm_compact:=pg_catalog.regexp_replace(v_norm_name,'[^a-z0-9]+','','g');

    select coalesce(pg_catalog.array_agg(candidate_id order by candidate_id),'{}'::uuid[])
      into v_candidate_ids
    from (
      select distinct candidate.id as candidate_id
      from public.candidates candidate
      where candidate.active
        and (
          (v_source_id is not null and pg_catalog.lower(pg_catalog.btrim(candidate.tms_ref))=
             pg_catalog.lower(v_source_id))
          or (v_source_id_2 is not null and pg_catalog.lower(pg_catalog.btrim(candidate.tms_ref))=
             pg_catalog.lower(v_source_id_2))
          or (v_source_id_3 is not null and pg_catalog.lower(pg_catalog.btrim(candidate.tms_ref))=
             pg_catalog.lower(v_source_id_3))
          or exists(
            select 1
            from pg_catalog.jsonb_array_elements_text(
              case when pg_catalog.jsonb_typeof(candidate.nhsp_hr_name_aliases)='array'
                then candidate.nhsp_hr_name_aliases else '[]'::jsonb end
            ) alias(value)
            where pg_catalog.lower(pg_catalog.btrim(alias.value))=v_norm_name
               or pg_catalog.regexp_replace(pg_catalog.lower(alias.value),'[^a-z0-9]+','','g')=v_norm_compact
          )
          or exists(
            select 1 from public.hr_name_mappings mapping
            where mapping.active and mapping.candidate_id=candidate.id
              and (
                pg_catalog.lower(pg_catalog.btrim(mapping.hr_name_norm))=v_norm_name
                or pg_catalog.regexp_replace(pg_catalog.lower(mapping.hr_name_norm),'[^a-z0-9]+','','g')=v_norm_compact
              )
              and (nullif(pg_catalog.btrim(coalesce(mapping.hospital_or_trust,'')),'') is null
                or pg_catalog.lower(pg_catalog.btrim(mapping.hospital_or_trust))=
                   pg_catalog.lower(pg_catalog.btrim(coalesce(v_source_client,''))))
          )
        )
    ) exact_saved;
    if v_office_choice.candidate_id is not null then
      select coalesce(pg_catalog.array_agg(id),'{}'::uuid[]) into v_candidate_ids
        from public.candidates where id=v_office_choice.candidate_id and active;
    end if;
    v_candidate_id:=case when pg_catalog.cardinality(v_candidate_ids)=1 then v_candidate_ids[1] end;
    select coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'candidate_id',candidate.id,'display_name',coalesce(nullif(candidate.display_name,''),
          pg_catalog.btrim(coalesce(candidate.first_name,'')||' '||coalesce(candidate.last_name,''))),
        'tms_ref',candidate.tms_ref
      ) order by candidate.id
    ),'[]'::jsonb) into v_candidate_matches
    from public.candidates candidate where candidate.id=any(v_candidate_ids);

    v_contracts:='[]'::jsonb;
    v_prior_contract_id:=null;
    v_prior_work_event_id:=null;
    v_prior_candidate_count:=0;
    if v_candidate_id is not null and v_row_client_id is not null then
      select coalesce(pg_catalog.jsonb_agg(contract_item order by contract_item->>'contract_id'),'[]'::jsonb)
        into v_contracts
      from (
        select pg_catalog.jsonb_build_object(
          'contract_id',contract.id,
          'candidate_id',contract.candidate_id,
          'client_id',contract.client_id,
          'valid_from',contract.start_date,
          'valid_to',contract.end_date,
          'display_label',pg_catalog.concat_ws(' · ',nullif(contract.role,''),nullif(contract.band,''),nullif(contract.display_site,'')),
          'role',contract.role,'band',contract.band,
          'pay_type',contract.pay_method_snapshot,
          'rates_json',contract.rates_json,
          'contract_updated_at',contract.updated_at,
          'weekly_source_applicable',true,
          'schedule_compatible',private.weekly_source_schedule_compatible_v1(
            contract.std_schedule_json,v_source_row.work_date
          ),
          'verified_role_band_match',private.weekly_source_verified_role_band_match_v1(
            case when v_profile.profile_code in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1')
              then 'NHSP' else 'HR_WEEKLY' end,
            v_source_row.role_band_source,v_candidate_id,v_row_client_id,
            contract.id,contract.band,v_source_row.work_date
          ),
          'effective_policy',private._weekly_source_effective_policy_v1(
            v_row_client_id,contract.id,v_source_row.work_date
          ),
          'settings_authority',private._contract_settings_effective_core_v1(
            v_row_client_id,contract.id,v_source_row.work_date,'IMPORT',null
          )
        ) contract_item
        from public.contracts contract
        where contract.candidate_id=v_candidate_id
          and contract.client_id=v_row_client_id
          and v_source_row.work_date between contract.start_date and coalesce(contract.end_date,'infinity'::date)
      ) eligible;

      -- G6-13 / XSG-010.  Only the three roster profiles use the source
      -- system's own line identity as the durable work-event key.  An NHSP
      -- Reference Number is evidence, never sole durable identity
      -- (`24 §9`; `25 §7` Removed), so NHSP lineage resolves through the
      -- schedule tuple below, exactly as the publication owner now keys it.
      if v_profile.profile_code in (
        'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
        'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1',
        'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1'
      ) and nullif(pg_catalog.btrim(coalesce(v_source_row.external_source_key,'')),'') is not null then
        select event.id,resolution.contract_id
          into v_prior_work_event_id,v_prior_contract_id
        from public.weekly_work_events event
        left join lateral (
          select saved.contract_id
          from public.weekly_source_row_resolutions saved
          where saved.work_event_id=event.id and saved.mapping_state='RESOLVED'
          order by saved.created_at_utc desc,saved.id desc limit 1
        ) resolution on true
        where event.first_source_group_id=v_group.id
          and event.source_format_profile_id=v_profile.id
          and event.identity_kind='PROFILE_EXTERNAL_KEY'
          and event.profile_external_key=v_source_row.external_source_key
          and event.candidate_id=v_candidate_id and event.client_id=v_row_client_id
        order by event.created_at_utc,event.id limit 1;
      else
        -- WP-37, against `24 §9` step 2.  The pack keys identity on "exact
        -- Candidate, actual Client, worked date and **compatible** schedule",
        -- so lineage must NOT demand exact Actual start and end: `24 §6.2`
        -- ("Paid eight hours becomes nine") is a later source change on ONE
        -- root, and an NHSP correction routinely moves the times.  The
        -- cardinality is checked explicitly: none means new work, and more than
        -- one is `24 §9` step 4 (Office confirmation), where nothing is
        -- suggested and the server refuses to guess.
        select pg_catalog.count(*)::integer,
               pg_catalog.min(event.id::text)::uuid
          into v_prior_candidate_count,v_prior_work_event_id
        from public.weekly_work_events event
        where event.first_source_group_id=v_group.id
          and event.source_format_profile_id=v_profile.id
          and event.identity_kind='SCHEDULE_TUPLE'
          and event.candidate_id=v_candidate_id and event.client_id=v_row_client_id
          and event.work_date=v_source_row.work_date
          and private.weekly_source_work_event_schedule_compatible_v1(
                event.id,v_source_row.start_at_local,v_source_row.end_at_local
              );
        if v_prior_candidate_count<>1 then
          v_prior_work_event_id:=null;
        else
          -- The Contract is a SUGGESTION only: `weekly_source_projection_build_v1`
          -- re-proves DURABLE_LINEAGE against a prior RESOLVED resolution for
          -- this same work event before it will accept the selection method.
          select saved.contract_id into v_prior_contract_id
          from public.weekly_source_row_resolutions saved
          where saved.work_event_id=v_prior_work_event_id
            and saved.mapping_state='RESOLVED'
          order by saved.created_at_utc desc,saved.id desc limit 1;
        end if;
      end if;
    end if;

    v_rows:=v_rows||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'upload_row_id',v_source_row.id,
      'source_row_ordinal',v_source_row.source_row_ordinal,
      'external_source_key',v_source_row.external_source_key,
      'source_candidate_identity',v_source_row.source_candidate_identity,
      'source_client_identity',v_source_row.source_client_identity,
      'work_date',v_source_row.work_date,
      'start_at_local',v_source_row.start_at_local,
      'end_at_local',v_source_row.end_at_local,
      'break_minutes',v_source_row.break_minutes,
      'actual_net_minutes',v_source_row.actual_net_minutes,
      'row_finalisation_state',v_source_row.row_finalisation_state,
      'role_band_source',v_source_row.role_band_source,
      'source_commission_pence',v_source_row.source_commission_pence,
      'source_total_cost_pence',v_source_row.source_total_cost_pence,
      'source_shift_charge_pence',v_source_row.source_shift_charge_pence,
      'source_money_parse_state',v_source_row.source_money_parse_state,
      'source_expense_pence',v_source_row.source_expense_pence,
      'source_expense_parse_state',v_source_row.source_expense_parse_state,
      'candidate_match_count',pg_catalog.cardinality(v_candidate_ids),
      'candidate_matches',v_candidate_matches,
      'candidate_id',v_candidate_id,
      'office_selected_contract_id',v_office_choice.contract_id,
      'office_selected_work_event_id',v_office_choice.work_event_id,
      'office_separate_shift',coalesce(v_office_choice.separate_shift,false),
      'protected_matches',private.weekly_source_protected_match_candidates_v1(v_source_row.id,v_candidate_id,v_row_client_id),
      'client_id',v_row_client_id,
      'contracts',v_contracts,
      'prior_accepted_contract_id',v_prior_contract_id,
      'prior_work_event_id',v_prior_work_event_id,
      -- `24 §9` step 4.  True means more than one plausible existing work
      -- record remains, so Office must confirm the relationship; the server
      -- refuses to publish the row until it does.
      'prior_work_event_ambiguous',v_prior_candidate_count>1
    ));
  end loop;

  if v_upload.correction_session_id is not null then
    select publication.* into v_publication
    from public.weekly_final_source_correction_sessions correction
    join public.weekly_source_projection_publications publication
      on publication.id=correction.replacement_projection_publication_id
    where correction.id=v_upload.correction_session_id
      and correction.replacement_correction_upload_id=v_upload.id
      and publication.upload_id=v_upload.id
      and publication.correction_session_id=correction.id
      and publication.state='CORRECTION_READY';
  else
    select publication.* into v_publication
    from public.weekly_source_projection_publications publication
    where publication.upload_id=v_upload.id
      and publication.state='CURRENT'
    order by publication.published_at_utc desc nulls last,publication.id desc
    limit 1;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'context_version','WEEKLY_SOURCE_PROJECTION_CONTEXT_V1',
    'environment',v_group.environment,'agency_id',v_group.agency_id,
    'source_group_id',v_group.id,'source_family',v_group.source_family,
    'source_cycle_id',v_cycle.id,'report_scope_id',v_report_scope_id,
    'client_id',v_client_id,'client_name',v_client_name,
    'profile_id',v_profile.profile_code,'profile_version',v_profile.version,
    'upload_id',v_upload.id,
    'row_manifest_hash',case when v_upload.row_manifest_hash is null then null
      else pg_catalog.encode(v_upload.row_manifest_hash,'hex') end,
    'projection_publication_id',v_publication.id,
    'projection_state',v_publication.state,
    'comparison_manifest_hash',case when v_publication.comparison_manifest_hash is null then null
      else pg_catalog.encode(v_publication.comparison_manifest_hash,'hex') end,
    'issue_set_hash',case when v_publication.issue_set_hash is null then null
      else pg_catalog.encode(v_publication.issue_set_hash,'hex') end,
    'correction_session_id',v_upload.correction_session_id,
    'correction_session_version',case when v_upload.correction_session_id is null then null else (
      select correction.version
      from public.weekly_final_source_correction_sessions correction
      where correction.id=v_upload.correction_session_id
    ) end,
    'authority_scope_kind',case when v_report_scope_id is null then 'CYCLE' else 'NHSP_REPORT_SCOPE' end,
    'authority_scope_version',coalesce(v_scope.version,v_cycle.version),
    'rows',v_rows
  );
end;
$function$;

alter function public.weekly_source_upload_context_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_upload_context_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_upload_context_v1(jsonb) to service_role;

create or replace function public.weekly_source_office_recheck_begin_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_request_id uuid;
  v_hash bytea;
  v_upload public.weekly_source_uploads%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_prior private.weekly_source_office_rechecks%rowtype;
  v_row public.weekly_source_upload_rows%rowtype;
  v_choice private.weekly_source_office_row_choices%rowtype;
  v_resolution public.weekly_source_row_resolutions%rowtype;
  v_candidate uuid;
  v_client uuid;
  v_contract uuid;
  v_work_event uuid;
  v_match_reason text;
  v_separate_shift boolean:=false;
  v_version bigint;
  v_current_publication uuid;
  v_current_upload uuid;
  v_begin jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
    or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key where key not in
      ('actor_user_id','request_id','upload_id','projection_publication_id',
       'expected_authority_scope_version','expected_row_manifest_hash','upload_row_id',
       'candidate_id','client_id','contract_id','work_event_id','match_reason','separate_shift')) then
    raise exception 'WEEKLY_SOURCE_RECHECK_REQUEST_INVALID' using errcode='22023';
  end if;
  v_actor:=(p_request->>'actor_user_id')::uuid;
  v_request_id:=(p_request->>'request_id')::uuid;
  if v_actor is null or v_request_id is null then
    raise exception 'WEEKLY_SOURCE_RECHECK_REQUEST_INVALID' using errcode='22023';
  end if;
  v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_OFFICE_RECHECK_V1',p_request);
  select * into strict v_upload from public.weekly_source_uploads where id=(p_request->>'upload_id')::uuid;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    pg_catalog.encode(v_upload.declared_scope_fingerprint,'hex'),73241837));
  select * into strict v_cycle from public.weekly_source_cycles where id=v_upload.source_cycle_id for update;
  select * into strict v_upload from public.weekly_source_uploads where id=v_upload.id;
  if v_upload.report_scope_id is null then
    v_version:=v_cycle.version; v_current_upload:=v_cycle.current_complete_upload_id;
    v_current_publication:=v_cycle.current_projection_publication_id;
  else
    select * into strict v_scope from public.weekly_source_report_scopes where id=v_upload.report_scope_id for update;
    v_version:=v_scope.version; v_current_upload:=v_scope.current_complete_upload_id;
    v_current_publication:=v_scope.current_projection_publication_id;
  end if;
  perform private.weekly_source_office_authority_v1(v_actor,'RECHECK_SOURCE',v_cycle.source_group_id,
    coalesce(v_scope.client_id,nullif(v_upload.file_metadata_json->>'client_id','')::uuid),v_cycle.finalisation_week_ending);
  if v_upload.purpose<>'ORDINARY' or v_upload.state<>'CURRENT'
    or v_current_upload is distinct from v_upload.id or v_cycle.state in ('FINALISING','FINALISED')
    or v_scope.state in ('FINALISING','FINALISED') then
    raise exception 'WEEKLY_SOURCE_RECHECK_NOT_CURRENT' using errcode='55000';
  end if;
  select * into v_prior from private.weekly_source_office_rechecks where request_id=v_request_id;
  if found then
    if v_prior.request_hash is distinct from v_hash or v_prior.actor_user_id<>v_actor then
      raise exception 'WEEKLY_SOURCE_RECHECK_REPLAY_CONFLICT' using errcode='23505';
    end if;
    select * into strict v_publication from public.weekly_source_projection_publications where id=v_prior.publication_id;
    if v_publication.authority_scope_version<>v_version or v_publication.state not in ('BUILDING','CURRENT') then
      raise exception 'WEEKLY_SOURCE_RECHECK_NOT_CURRENT' using errcode='55000';
    end if;
    return pg_catalog.jsonb_build_object('ok',true,'status',v_publication.state,
      'publication_id',v_publication.id,'upload_id',v_upload.id,'authority_scope_version',v_version,'idempotent',true);
  end if;
  if v_version is distinct from (p_request->>'expected_authority_scope_version')::bigint
    or v_current_publication is distinct from (p_request->>'projection_publication_id')::uuid
    or v_upload.row_manifest_hash is distinct from private.weekly_source_hex32_v1(
      p_request->>'expected_row_manifest_hash','WEEKLY_SOURCE_ROW_MANIFEST_HASH_REQUIRED') then
    raise exception 'WEEKLY_SOURCE_PREVIEW_STALE' using errcode='40001';
  end if;
  select * into strict v_publication from public.weekly_source_projection_publications where id=v_current_publication for update;
  if v_publication.state<>'CURRENT' or v_publication.upload_id<>v_upload.id then
    raise exception 'WEEKLY_SOURCE_PREVIEW_STALE' using errcode='40001';
  end if;
  if p_request ?| array['candidate_id','client_id','contract_id','work_event_id','separate_shift'] then
    select * into strict v_row from public.weekly_source_upload_rows
      where id=(p_request->>'upload_row_id')::uuid and upload_id=v_upload.id;
    select * into v_choice from private.weekly_source_office_row_choices
      where upload_row_id=v_row.id order by id desc limit 1;
    select * into v_resolution from public.weekly_source_row_resolutions
      where upload_row_id=v_row.id order by generation desc,id desc limit 1;
    v_candidate:=coalesce((p_request->>'candidate_id')::uuid,v_choice.candidate_id,v_resolution.candidate_id);
    v_client:=coalesce((p_request->>'client_id')::uuid,v_choice.client_id,v_resolution.client_id);
    v_contract:=case when p_request ? 'contract_id' then (p_request->>'contract_id')::uuid
      when p_request ?| array['candidate_id','client_id'] then null else v_choice.contract_id end;
    if v_candidate is not null and not exists(select 1 from public.candidates where id=v_candidate and active) then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_INACTIVE_OR_MISSING' using errcode='22023';
    end if;
    if v_client is not null and not private.weekly_source_upload_client_eligible_v1(
      v_upload.id,v_client,v_row.work_date) then
      raise exception 'WEEKLY_SOURCE_CLIENT_NOT_ELIGIBLE' using errcode='22023';
    end if;
    if v_scope.client_id is not null and v_client is distinct from v_scope.client_id then
      raise exception 'WEEKLY_SOURCE_CLIENT_NOT_ELIGIBLE' using errcode='22023';
    end if;
    if v_contract is not null and not exists(select 1 from public.contracts
      where id=v_contract and candidate_id=v_candidate and client_id=v_client
        and v_row.work_date between start_date and coalesce(end_date,'infinity'::date)) then
      raise exception 'WEEKLY_SOURCE_CONTRACT_NOT_ELIGIBLE' using errcode='22023';
    end if;
    if p_request ? 'separate_shift' then
      if p_request->'separate_shift'<>'true'::jsonb or p_request ? 'work_event_id' then
        raise exception 'WEEKLY_SOURCE_PROTECTED_MATCH_NOT_ELIGIBLE' using errcode='22023';
      end if;
      v_separate_shift:=true;
      v_match_reason:=btrim(p_request->>'match_reason');
      v_contract:=coalesce(v_contract,v_resolution.contract_id);
      if v_contract is null or v_match_reason is null or char_length(v_match_reason) not between 1 and 1000
        or jsonb_array_length(private.weekly_source_protected_match_candidates_v1(v_row.id,v_candidate,v_client))=0
        or exists(select 1 from public.weekly_exceptional_pay_family_events item
          where item.durable_work_event_id=v_resolution.work_event_id) then
        raise exception 'WEEKLY_SOURCE_PROTECTED_MATCH_NOT_ELIGIBLE' using errcode='22023';
      end if;
    elsif p_request ? 'work_event_id' then
      v_work_event:=(p_request->>'work_event_id')::uuid;
      v_match_reason:=btrim(p_request->>'match_reason');
      if v_work_event is null or v_match_reason is null or char_length(v_match_reason) not between 1 and 1000
        or not exists(select 1 from jsonb_array_elements(
          private.weekly_source_protected_match_candidates_v1(v_row.id,v_candidate,v_client)) choice
          where choice->>'work_event_id'=v_work_event::text
            and choice->>'contract_id'=coalesce(v_contract,v_resolution.contract_id)::text) then
        raise exception 'WEEKLY_SOURCE_PROTECTED_MATCH_NOT_ELIGIBLE' using errcode='22023';
      end if;
      v_contract:=coalesce(v_contract,v_resolution.contract_id);
      -- A source identity already included in final authority cannot be moved
      -- to another payable identity by this pre-finalisation choice.
      if exists(select 1 from public.weekly_source_row_resolutions old_resolution
        where old_resolution.upload_row_id=v_row.id and old_resolution.work_event_id<>v_work_event
          and (exists(select 1 from public.weekly_source_final_snapshot_lines final_line
            where final_line.work_event_id=old_resolution.work_event_id)
            or exists(select 1 from public.weekly_source_billing_movements movement
              where movement.work_event_id=old_resolution.work_event_id))) then
        raise exception 'WEEKLY_SOURCE_PROTECTED_MATCH_FINAL_AUTHORITY_CONFLICT' using errcode='55000';
      end if;
    elsif not (p_request ?| array['candidate_id','client_id','contract_id']) then
      v_work_event:=v_choice.work_event_id; v_match_reason:=v_choice.match_reason;
    end if;
    insert into private.weekly_source_office_row_choices(upload_row_id,candidate_id,client_id,contract_id,actor_user_id,work_event_id,match_reason,separate_shift)
      values(v_row.id,v_candidate,v_client,v_contract,v_actor,v_work_event,v_match_reason,v_separate_shift);
  elsif p_request ? 'upload_row_id' then
    raise exception 'WEEKLY_SOURCE_RECHECK_REQUEST_INVALID' using errcode='22023';
  end if;
  update public.weekly_source_projection_publications set state='STALE' where id=v_publication.id;
  if v_upload.report_scope_id is null then
    update public.weekly_source_cycles set version=version+1,projection_state='REBUILDING',current_projection_publication_id=null
      where id=v_cycle.id returning version into v_version;
  else
    update public.weekly_source_report_scopes set version=version+1,projection_state='REBUILDING',current_projection_publication_id=null,
      updated_at_utc=pg_catalog.transaction_timestamp() where id=v_scope.id returning version into v_version;
  end if;
  v_begin:=public.weekly_source_projection_begin_atomic_v1(pg_catalog.jsonb_build_object(
    'actor_user_id',v_actor,'upload_id',v_upload.id,'expected_authority_scope_version',v_version));
  if v_begin->>'status'<>'BUILDING' then
    raise exception 'WEEKLY_SOURCE_RECHECK_BEGIN_FAILED' using errcode='55000';
  end if;
  -- This is a new comparison of an existing immutable upload, not its first
  -- publication. Keep earlier resolutions as history and explicitly identify
  -- the new generation; the publisher must census this generation only.
  if v_version>2147483647 then
    raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003';
  end if;
  update public.weekly_source_projection_publications
    set projection_generation=v_version::integer
    where id=(v_begin->>'publication_id')::uuid and state='BUILDING';
  v_begin:=v_begin||pg_catalog.jsonb_build_object('projection_generation',v_version::integer);
  insert into private.weekly_source_office_rechecks(request_id,actor_user_id,upload_id,prior_publication_id,publication_id,request_hash,request_json)
    values(v_request_id,v_actor,v_upload.id,v_publication.id,(v_begin->>'publication_id')::uuid,v_hash,p_request);
  return v_begin;
end;
$function$;
alter function public.weekly_source_office_recheck_begin_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_office_recheck_begin_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_office_recheck_begin_v1(jsonb) to service_role;

notify pgrst, 'reload schema';



-- CONTACT_PREPARER_UNIT 38 repeatable supabase/repeatable/09102026_1250_weekly_source_nhsp_client_setup_v1.sql SHA256 4584327faafef9a084c825584e1282d527ff7f42afa069ba7580cd54f5e3dfec
-- Dedicated NHSP Client setup before its first source contract.
-- Full existing definitions: no contract creation, reconciliation shortcut or
-- financial authority change. Preserve effective dates, CAS and service ACLs.


CREATE OR REPLACE FUNCTION private._weekly_source_settings_client_shape_v1(p_agency_id uuid, p_environment text, p_client_id uuid, p_effective_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_environment text:=private._weekly_source_settings_deployment_v1(p_agency_id,p_environment);
  v_membership public.weekly_source_group_clients%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_policy public.weekly_source_client_policies%rowtype;
  v_scope_date date:=coalesce(p_effective_date,current_date);
  v_membership_count integer;
  v_policy_count integer;
  v_family_count integer;
  v_mode_count integer;
  v_self_bill_count integer;
  v_contract_count integer;
  v_client_nhsp_basis boolean:=false;
  v_derived_family text;
  v_derived_authority text;
  v_derived_document text;
  v_derived_self_bill boolean;
  v_configured boolean:=false;
  v_eligible boolean:=false;
  v_expense_profile_supported boolean:=false;
  v_settings jsonb;
  v_capabilities jsonb;
  v_version text;
  v_default_group_id uuid;
  v_nhsp_group_count integer;
begin
  if p_client_id is null or not exists(select 1 from public.clients client where client.id=p_client_id) then
    raise exception 'WEEKLY_SOURCE_SETTINGS_CLIENT_NOT_FOUND' using errcode='22023';
  end if;

  select pg_catalog.count(*),
         pg_catalog.count(distinct case
           when contract.weekly_timesheet_source::text='NHSP' then 'NHSP'
           when contract.weekly_timesheet_source::text='HEALTHROSTER' then 'ROSTER'
         end),
         pg_catalog.count(distinct case
           when contract.weekly_timesheet_source::text='NHSP'
             or coalesce(contract.no_timesheet_required,false) then 'SOURCE_AUTHORITY'
           else 'TIMESHEET_AUTHORITY'
         end),
         pg_catalog.count(distinct contract.self_bill),
         pg_catalog.min(case
           when contract.weekly_timesheet_source::text='NHSP' then 'NHSP'
           when contract.weekly_timesheet_source::text='HEALTHROSTER' then 'ROSTER'
         end),
         pg_catalog.min(case
           when contract.weekly_timesheet_source::text='NHSP'
             or coalesce(contract.no_timesheet_required,false) then 'SOURCE_AUTHORITY'
           else 'TIMESHEET_AUTHORITY'
         end),
         pg_catalog.bool_and(contract.self_bill)
  into v_contract_count,v_family_count,v_mode_count,v_self_bill_count,
       v_derived_family,v_derived_authority,v_derived_self_bill
  from public.contracts contract
  where contract.client_id=p_client_id
    and contract.weekly_timesheet_source::text<>'NONE'
    and contract.end_date>=v_scope_date;


  -- Client setup precedes contracts. Only the currently effective dedicated
  -- NHSP client mode may supply this pre-contract configuration basis.
  -- Existing source contracts (including conflicting ones) remain authoritative.
  if v_contract_count=0 and coalesce((
    select settings.is_nhsp
      and not coalesce(settings.requires_hr,false)
      and not coalesce(settings.autoprocess_hr,false)
      and not coalesce(settings.no_timesheet_required,false)
    from public.client_settings settings
    where settings.client_id=p_client_id
      and (settings.effective_from is null or settings.effective_from<=v_scope_date)
    order by settings.effective_from desc nulls last,settings.updated_at desc,settings.id desc
    limit 1
  ),false) then
    v_derived_family:='NHSP';
    v_derived_authority:='SOURCE_AUTHORITY';
    v_derived_self_bill:=true;
    v_family_count:=1;
    v_mode_count:=1;
    v_self_bill_count:=1;
    v_client_nhsp_basis:=true;
  end if;

  v_derived_document:=case v_derived_authority
    when 'SOURCE_AUTHORITY' then 'CHECK_ONLY'
    when 'TIMESHEET_AUTHORITY' then 'INVOICE_EVIDENCE_REQUIRED'
  end;
  v_eligible:=(v_contract_count>0 or v_client_nhsp_basis) and v_family_count=1 and v_mode_count=1
    and v_self_bill_count=1
    and ((v_derived_authority='SOURCE_AUTHORITY' and v_derived_self_bill)
      or (v_derived_authority='TIMESHEET_AUTHORITY' and not v_derived_self_bill));

  if v_derived_family='NHSP' then
    select pg_catalog.count(*) into v_nhsp_group_count
    from public.weekly_source_groups source_group
    where source_group.agency_id=p_agency_id
      and source_group.environment=v_environment
      and source_group.source_family='NHSP'
      and source_group.active;
    if v_nhsp_group_count>1 then
      raise exception 'WEEKLY_SOURCE_NHSP_GROUP_CARDINALITY_INVALID' using errcode='55000';
    elsif v_nhsp_group_count=1 then
      select source_group.id into strict v_default_group_id
      from public.weekly_source_groups source_group
      where source_group.agency_id=p_agency_id
        and source_group.environment=v_environment
        and source_group.source_family='NHSP'
        and source_group.active;
    end if;
  end if;

  select pg_catalog.count(*) into v_membership_count
  from public.weekly_source_group_clients membership
  join public.weekly_source_groups source_group on source_group.id=membership.source_group_id
  where membership.client_id=p_client_id
    and source_group.agency_id=p_agency_id
    and source_group.environment=v_environment
    and v_scope_date between membership.valid_from and coalesce(membership.valid_to,'infinity'::date);
  if v_membership_count>1 then
    raise exception 'WEEKLY_SOURCE_SETTINGS_MEMBERSHIP_CARDINALITY_INVALID' using errcode='55000';
  end if;

  if v_membership_count=1 then
    select membership.*
    into strict v_membership
    from public.weekly_source_group_clients membership
    join public.weekly_source_groups source_group on source_group.id=membership.source_group_id
    where membership.client_id=p_client_id
      and source_group.agency_id=p_agency_id
      and source_group.environment=v_environment
      and v_scope_date between membership.valid_from and coalesce(membership.valid_to,'infinity'::date);
    select source_group.* into strict v_group
    from public.weekly_source_groups source_group
    where source_group.id=v_membership.source_group_id;

    select pg_catalog.count(*) into v_policy_count
    from public.weekly_source_client_policies policy
    where policy.source_group_id=v_group.id
      and policy.client_id=p_client_id
      and v_scope_date between policy.effective_from and coalesce(policy.effective_to,'infinity'::date);
    if v_policy_count<>1 then
      raise exception 'WEEKLY_SOURCE_SETTINGS_CLIENT_POLICY_CARDINALITY_INVALID' using errcode='55000';
    end if;
    select * into strict v_policy
    from public.weekly_source_client_policies policy
    where policy.source_group_id=v_group.id
      and policy.client_id=p_client_id
      and v_scope_date between policy.effective_from and coalesce(policy.effective_to,'infinity'::date);
    v_configured:=true;
    v_eligible:=v_eligible or true;
  end if;

  if v_configured then
    select exists(
      select 1
      from public.weekly_source_uploads upload
      join public.weekly_source_cycles cycle on cycle.id=upload.source_cycle_id
      join public.weekly_source_format_profiles profile on profile.id=upload.source_format_profile_id
      where cycle.source_group_id=v_group.id
        and profile.profile_json ? 'expense_column'
        and upload.state in ('SEALED','CURRENT','SUPERSEDED','CORRECTION_READY')
    ) or v_policy.source_fixed_expenses_enabled
    into v_expense_profile_supported;

    v_settings:=pg_catalog.jsonb_build_object(
      'source_group_id',v_group.id,
      -- A first Client policy is deliberately stored from 1900-01-01 so an
      -- existing prior-week source file can be imported immediately.  Present
      -- the requested scope date as the next editable date, however, so a
      -- later settings change creates a new effective-dated row instead of
      -- rewriting that historical baseline.
      'effective_from',case when v_policy.effective_from=date '1900-01-01'
        then v_scope_date else v_policy.effective_from end,
      'authority_mode',v_policy.authority_mode,
      'document_mode',v_policy.document_mode,
      'self_bill_enabled',v_policy.self_bill_enabled,
      'self_bill_correction_presentation',v_policy.self_bill_correction_presentation,
      'source_fixed_expenses_enabled',v_policy.source_fixed_expenses_enabled,
      'source_expense_vat_enabled',v_policy.source_expense_vat_enabled,
      'weekly_rate_classification_method',v_policy.weekly_rate_classification_method,
      'duration_break_tie_rule',case when v_policy.weekly_rate_classification_method='SPLIT_RATE_WINDOWS'
        then v_policy.duration_break_tie_rule else null end,
      'candidate_queries_enabled',v_policy.candidate_queries_enabled,
      'manager_queries_enabled',v_policy.manager_queries_enabled,
      'manager_query_recipient',case when v_policy.manager_queries_enabled then v_policy.manager_query_recipient else null end,
      'completed_pack_copy_enabled',v_policy.completed_pack_copy_enabled,
      'completed_pack_recipient',case when v_policy.completed_pack_copy_enabled then v_policy.completed_pack_recipient else null end
    );
    v_version:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
      pg_catalog.jsonb_build_object(
        'membership_id',v_membership.id,'membership_from',v_membership.valid_from,
        'membership_to',v_membership.valid_to,'policy_id',v_policy.id,
        'policy_from',v_policy.effective_from,'policy_to',v_policy.effective_to,
        'group_version',v_group.version,'settings',v_settings
      )::text,'UTF8'),'sha256'),'hex');
    v_capabilities:=pg_catalog.jsonb_build_object(
      'source_family',v_group.source_family,
      'authority_mode',v_policy.authority_mode,
      'document_mode',v_policy.document_mode,
      'self_bill_enabled',v_policy.self_bill_enabled,
      'show_query_settings',v_policy.authority_mode='SOURCE_AUTHORITY' and v_policy.document_mode='CHECK_ONLY',
      'show_completed_pack',v_policy.document_mode in ('CHECK_ONLY','INVOICE_EVIDENCE_REQUIRED'),
      'show_rate_settings',true,
      'show_source_expenses',v_expense_profile_supported,
      'show_self_bill_correction',v_policy.self_bill_enabled and v_group.source_family='ROSTER'
    );
  else
    v_settings:=pg_catalog.jsonb_build_object(
      'source_group_id',case when v_derived_family='NHSP' then v_default_group_id else null end,
      'effective_from',v_scope_date,
      'authority_mode',v_derived_authority,
      'document_mode',v_derived_document,
      'self_bill_enabled',v_derived_self_bill,
      'self_bill_correction_presentation',case when v_derived_self_bill and v_derived_family='ROSTER'
        then 'FULL_REVERSAL_REPLACEMENT' else null end,
      'source_fixed_expenses_enabled',false,
      'source_expense_vat_enabled',false,
      'weekly_rate_classification_method','SPLIT_RATE_WINDOWS',
      'duration_break_tie_rule','EARLIEST_LONGEST_PORTION',
      'candidate_queries_enabled',v_derived_authority='SOURCE_AUTHORITY' and v_derived_document='CHECK_ONLY',
      'manager_queries_enabled',v_derived_authority='SOURCE_AUTHORITY' and v_derived_document='CHECK_ONLY',
      'manager_query_recipient',case when v_derived_authority='SOURCE_AUTHORITY' and v_derived_document='CHECK_ONLY'
        then (select nullif(pg_catalog.btrim(client.ts_queries_email),'') from public.clients client where client.id=p_client_id) end,
      'completed_pack_copy_enabled',false,
      'completed_pack_recipient',null
    );
    v_version:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
      'UNCONFIGURED:'||p_client_id::text||':'||v_scope_date::text||':'||coalesce(v_derived_family,'')||':'||coalesce(v_derived_authority,'')||':'||coalesce(v_default_group_id::text,''),
      'UTF8'),'sha256'),'hex');
    v_capabilities:=pg_catalog.jsonb_build_object(
      'source_family',v_derived_family,
      'authority_mode',v_derived_authority,
      'document_mode',v_derived_document,
      'self_bill_enabled',v_derived_self_bill,
      'show_query_settings',v_derived_authority='SOURCE_AUTHORITY' and v_derived_document='CHECK_ONLY',
      'show_completed_pack',v_derived_document in ('CHECK_ONLY','INVOICE_EVIDENCE_REQUIRED'),
      'show_rate_settings',v_eligible,
      'show_source_expenses',false,
      'show_self_bill_correction',v_derived_self_bill and v_derived_family='ROSTER'
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'eligible',v_eligible,'configured',v_configured,
    'client_id',p_client_id,'effective_date',v_scope_date,
    'settings_version',v_version,'capabilities',v_capabilities,
    'settings',v_settings,
    'source_groups',private._weekly_source_settings_group_list_v1(
      p_agency_id,v_environment,coalesce(v_group.source_family,v_derived_family),true
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.weekly_source_client_settings_save_atomic_v1(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_agency uuid;
  v_environment text;
  v_client uuid;
  v_expected text;
  v_input jsonb;
  v_effective_from date;
  v_current_shape jsonb;
  v_group_id uuid;
  v_group public.weekly_source_groups%rowtype;
  v_old_group_id uuid;
  v_membership public.weekly_source_group_clients%rowtype;
  v_policy public.weekly_source_client_policies%rowtype;
  v_policy_found boolean:=false;
  v_contract_count integer;
  v_client_nhsp_basis boolean:=false;
  v_family_count integer;
  v_mode_count integer;
  v_self_bill_count integer;
  v_family text;
  v_authority text;
  v_document text;
  v_self_bill boolean;
  v_correction text;
  v_source_expenses boolean;
  v_source_expense_vat boolean;
  v_rate_method text;
  v_tie_rule text;
  v_candidate_queries boolean;
  v_manager_queries boolean;
  v_manager_recipient text;
  v_completed_copy boolean;
  v_completed_recipient text;
  v_expense_supported boolean;
  v_prior_end date;
  v_nhsp_group_count integer;
  v_membership_history_count integer;
  v_policy_history_count integer;
  v_membership_effective_from date;
  v_policy_effective_from date;
begin
  perform private._weekly_source_settings_assert_request_v1(
    p_request,array[
      'actor_user_id','agency_id','environment','client_id',
      'expected_settings_version','settings'
    ],'WEEKLY_SOURCE_CLIENT_SETTINGS_SAVE_REQUEST_INVALID'
  );
  v_input:=p_request->'settings';
  perform private._weekly_source_settings_assert_request_v1(
    v_input,array[
      'source_group_id','effective_from','authority_mode','document_mode','self_bill_enabled',
      'self_bill_correction_presentation','source_fixed_expenses_enabled','source_expense_vat_enabled',
      'weekly_rate_classification_method','duration_break_tie_rule',
      'candidate_queries_enabled','manager_queries_enabled','manager_query_recipient',
      'completed_pack_copy_enabled','completed_pack_recipient'
    ],'WEEKLY_SOURCE_CLIENT_SETTINGS_VALUES_INVALID'
  );
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_agency:=(p_request->>'agency_id')::uuid;
    v_client:=(p_request->>'client_id')::uuid;
    v_expected:=pg_catalog.btrim(p_request->>'expected_settings_version');
    v_effective_from:=coalesce(nullif(v_input->>'effective_from','')::date,current_date);
    v_group_id:=nullif(v_input->>'source_group_id','')::uuid;
    v_correction:=nullif(pg_catalog.upper(pg_catalog.btrim(v_input->>'self_bill_correction_presentation')),'');
    v_source_expenses:=(v_input->>'source_fixed_expenses_enabled')::boolean;
    v_source_expense_vat:=(v_input->>'source_expense_vat_enabled')::boolean;
    v_rate_method:=pg_catalog.upper(pg_catalog.btrim(v_input->>'weekly_rate_classification_method'));
    v_tie_rule:=nullif(pg_catalog.upper(pg_catalog.btrim(v_input->>'duration_break_tie_rule')),'');
    v_candidate_queries:=(v_input->>'candidate_queries_enabled')::boolean;
    v_manager_queries:=(v_input->>'manager_queries_enabled')::boolean;
    v_manager_recipient:=nullif(pg_catalog.btrim(v_input->>'manager_query_recipient'),'');
    v_completed_copy:=(v_input->>'completed_pack_copy_enabled')::boolean;
    v_completed_recipient:=nullif(pg_catalog.btrim(v_input->>'completed_pack_recipient'),'');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CLIENT_SETTINGS_SAVE_REQUEST_INVALID' using errcode='22023';
  end;
  perform private._weekly_source_settings_require_admin_v1(v_actor);
  v_environment:=private._weekly_source_settings_deployment_v1(v_agency,p_request->>'environment');
  if v_effective_from<current_date or nullif(v_expected,'') is null then
    raise exception 'WEEKLY_SOURCE_CLIENT_SETTINGS_SAVE_REQUEST_INVALID' using errcode='22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly-source-settings-client:'||v_client::text,0
  ));
  v_current_shape:=private._weekly_source_settings_client_shape_v1(
    v_agency,v_environment,v_client,v_effective_from
  );
  if v_current_shape->>'settings_version'<>v_expected then
    raise exception 'WEEKLY_SOURCE_SETTINGS_STALE' using errcode='40001';
  end if;
  if not (v_current_shape->>'eligible')::boolean then
    raise exception 'WEEKLY_SOURCE_CLIENT_SETTINGS_NOT_APPLICABLE' using errcode='22023';
  end if;

  select pg_catalog.count(*),
         pg_catalog.count(distinct case
           when contract.weekly_timesheet_source::text='NHSP' then 'NHSP'
           when contract.weekly_timesheet_source::text='HEALTHROSTER' then 'ROSTER'
         end),
         pg_catalog.count(distinct case
           when contract.weekly_timesheet_source::text='NHSP'
             or coalesce(contract.no_timesheet_required,false) then 'SOURCE_AUTHORITY'
           else 'TIMESHEET_AUTHORITY'
         end),
         pg_catalog.count(distinct contract.self_bill),
         pg_catalog.min(case
           when contract.weekly_timesheet_source::text='NHSP' then 'NHSP'
           when contract.weekly_timesheet_source::text='HEALTHROSTER' then 'ROSTER'
         end),
         pg_catalog.min(case
           when contract.weekly_timesheet_source::text='NHSP'
             or coalesce(contract.no_timesheet_required,false) then 'SOURCE_AUTHORITY'
           else 'TIMESHEET_AUTHORITY'
         end),
         pg_catalog.bool_and(contract.self_bill)
  into v_contract_count,v_family_count,v_mode_count,v_self_bill_count,
       v_family,v_authority,v_self_bill
  from public.contracts contract
  where contract.client_id=v_client
    and contract.weekly_timesheet_source::text<>'NONE'
    and contract.end_date>=v_effective_from;

  -- Client setup precedes contracts. Only the currently effective dedicated
  -- NHSP client mode may supply this pre-contract configuration basis.
  -- Existing source contracts (including conflicting ones) remain authoritative.
  if v_contract_count=0 and coalesce((
    select settings.is_nhsp
      and not coalesce(settings.requires_hr,false)
      and not coalesce(settings.autoprocess_hr,false)
      and not coalesce(settings.no_timesheet_required,false)
    from public.client_settings settings
    where settings.client_id=v_client
      and (settings.effective_from is null or settings.effective_from<=v_effective_from)
    order by settings.effective_from desc nulls last,settings.updated_at desc,settings.id desc
    limit 1
  ),false) then
    v_family:='NHSP';
    v_authority:='SOURCE_AUTHORITY';
    v_self_bill:=true;
    v_family_count:=1;
    v_mode_count:=1;
    v_self_bill_count:=1;
    v_client_nhsp_basis:=true;
  end if;

  if (v_contract_count=0 and not v_client_nhsp_basis) or v_family_count<>1 or v_mode_count<>1 or v_self_bill_count<>1
     or (v_authority='SOURCE_AUTHORITY' and not v_self_bill)
     or (v_authority='TIMESHEET_AUTHORITY' and v_self_bill) then
    raise exception 'WEEKLY_SOURCE_CLIENT_CONTRACT_POLICY_INCONSISTENT' using errcode='55000';
  end if;
  v_document:=case v_authority when 'SOURCE_AUTHORITY' then 'CHECK_ONLY'
    else 'INVOICE_EVIDENCE_REQUIRED' end;
  if (v_input ? 'authority_mode' and v_input->>'authority_mode'<>v_authority)
     or (v_input ? 'document_mode' and v_input->>'document_mode'<>v_document)
     or (v_input ? 'self_bill_enabled' and (v_input->>'self_bill_enabled')::boolean<>v_self_bill) then
    raise exception 'WEEKLY_SOURCE_CLIENT_READ_ONLY_POLICY_MISMATCH' using errcode='22023';
  end if;

  if v_family='NHSP' then
    select pg_catalog.count(*) into v_nhsp_group_count
    from public.weekly_source_groups source_group
    where source_group.agency_id=v_agency
      and source_group.environment=v_environment
      and source_group.source_family='NHSP'
      and source_group.active;
    if v_nhsp_group_count<>1 then
      raise exception 'WEEKLY_SOURCE_NHSP_GROUP_REQUIRED' using errcode='55000';
    end if;
    select source_group.id into strict v_group_id
    from public.weekly_source_groups source_group
    where source_group.agency_id=v_agency
      and source_group.environment=v_environment
      and source_group.source_family='NHSP'
      and source_group.active;
  end if;

  select * into v_group from public.weekly_source_groups source_group
  where source_group.id=v_group_id for update;
  if not found or v_group.agency_id<>v_agency or v_group.environment<>v_environment
     or not v_group.active or v_group.source_family<>v_family then
    raise exception 'WEEKLY_SOURCE_CLIENT_GROUP_NOT_APPLICABLE' using errcode='22023';
  end if;
  if v_rate_method not in ('SPLIT_RATE_WINDOWS','WHOLE_SHIFT_START_DAY')
     or (v_rate_method='SPLIT_RATE_WINDOWS' and v_tie_rule not in ('EARLIEST_LONGEST_PORTION','LATEST_LONGEST_PORTION')) then
    raise exception 'WEEKLY_SOURCE_CLIENT_RATE_SETTINGS_INVALID' using errcode='22023';
  end if;
  if v_rate_method<>'SPLIT_RATE_WINDOWS' then v_tie_rule:=null; end if;

  if v_self_bill and v_family='ROSTER' then
    if v_correction not in ('FULL_REVERSAL_REPLACEMENT','NET_DIFFERENCE_PRESENTATION') then
      raise exception 'WEEKLY_SOURCE_CLIENT_CORRECTION_SETTING_REQUIRED' using errcode='22023';
    end if;
  elsif v_correction is not null then
    raise exception 'WEEKLY_SOURCE_CLIENT_CORRECTION_SETTING_NOT_APPLICABLE' using errcode='22023';
  end if;

  select exists(
    select 1
    from public.weekly_source_uploads upload
    join public.weekly_source_cycles cycle on cycle.id=upload.source_cycle_id
    join public.weekly_source_format_profiles profile on profile.id=upload.source_format_profile_id
    where cycle.source_group_id=v_group_id
      and profile.profile_json ? 'expense_column'
      and upload.state in ('SEALED','CURRENT','SUPERSEDED','CORRECTION_READY')
  ) or coalesce((v_current_shape->'settings'->>'source_fixed_expenses_enabled')::boolean,false)
  into v_expense_supported;
  if v_source_expenses and not v_expense_supported then
    raise exception 'WEEKLY_SOURCE_CLIENT_SOURCE_EXPENSES_NOT_APPLICABLE' using errcode='22023';
  end if;
  if not v_source_expenses then v_source_expense_vat:=false; end if;

  if v_authority<>'SOURCE_AUTHORITY' then
    if v_candidate_queries or v_manager_queries or v_manager_recipient is not null
       or v_completed_copy or v_completed_recipient is not null then
      raise exception 'WEEKLY_SOURCE_CLIENT_QUERY_SETTINGS_NOT_APPLICABLE' using errcode='22023';
    end if;
  else
    if not v_manager_queries then v_manager_recipient:=null; end if;
    if v_manager_queries and v_manager_recipient is null then
      select nullif(pg_catalog.btrim(client.ts_queries_email),'') into v_manager_recipient
      from public.clients client where client.id=v_client;
    end if;
    if v_manager_queries and v_manager_recipient is null then
      raise exception 'WEEKLY_SOURCE_MANAGER_QUERY_RECIPIENT_REQUIRED' using errcode='22023';
    end if;
    if not v_completed_copy then v_completed_recipient:=null; end if;
    if v_completed_copy and v_completed_recipient is null then
      select coalesce(
        v_manager_recipient,
        nullif(pg_catalog.btrim(client.ts_queries_email),'')
      ) into v_completed_recipient
      from public.clients client where client.id=v_client;
    end if;
    if v_completed_copy and v_completed_recipient is null then
      raise exception 'WEEKLY_SOURCE_COMPLETED_PACK_RECIPIENT_REQUIRED' using errcode='22023';
    end if;
  end if;

  select membership.* into v_membership
  from public.weekly_source_group_clients membership
  join public.weekly_source_groups source_group on source_group.id=membership.source_group_id
  where membership.client_id=v_client
    and source_group.agency_id=v_agency and source_group.environment=v_environment
    and v_effective_from between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)
  for update of membership;
  if found then v_old_group_id:=v_membership.source_group_id; end if;

  select pg_catalog.count(*) into v_membership_history_count
  from public.weekly_source_group_clients membership
  join public.weekly_source_groups source_group on source_group.id=membership.source_group_id
  where membership.client_id=v_client
    and source_group.agency_id=v_agency and source_group.environment=v_environment;
  v_membership_effective_from:=case when v_membership_history_count=0
    then date '1900-01-01' else v_effective_from end;

  if v_old_group_id is null then
    insert into public.weekly_source_group_clients(
      source_group_id,client_id,valid_from,created_by_user_id
    ) values (v_group_id,v_client,v_membership_effective_from,v_actor)
    returning * into v_membership;
  elsif v_old_group_id<>v_group_id then
    if v_membership.valid_from=v_effective_from then
      update public.weekly_source_group_clients
      set source_group_id=v_group_id
      where id=v_membership.id returning * into v_membership;
    else
      v_prior_end:=v_membership.valid_to;
      update public.weekly_source_group_clients set valid_to=v_effective_from-1
      where id=v_membership.id;
      insert into public.weekly_source_group_clients(
        source_group_id,client_id,valid_from,valid_to,created_by_user_id
      ) values (v_group_id,v_client,v_effective_from,v_prior_end,v_actor)
      returning * into v_membership;
    end if;
  end if;

  if v_old_group_id is not null then
    select * into v_policy
    from public.weekly_source_client_policies policy
    where policy.source_group_id=v_old_group_id and policy.client_id=v_client
      and v_effective_from between policy.effective_from and coalesce(policy.effective_to,'infinity'::date)
    for update;
    v_policy_found:=found;
  end if;
  select pg_catalog.count(*) into v_policy_history_count
  from public.weekly_source_client_policies policy
  join public.weekly_source_groups source_group on source_group.id=policy.source_group_id
  where policy.client_id=v_client
    and source_group.agency_id=v_agency and source_group.environment=v_environment;
  v_policy_effective_from:=case when v_policy_history_count=0
    then date '1900-01-01' else v_effective_from end;
  if v_policy_found and v_policy.effective_from=v_effective_from then
    update public.weekly_source_client_policies
    set source_group_id=v_group_id,authority_mode=v_authority,document_mode=v_document,
        self_bill_enabled=v_self_bill,self_bill_correction_presentation=v_correction,
        source_fixed_expenses_enabled=v_source_expenses,
        source_expense_vat_enabled=v_source_expense_vat,
        weekly_rate_classification_method=v_rate_method,duration_break_tie_rule=v_tie_rule,
        candidate_queries_enabled=v_candidate_queries,manager_queries_enabled=v_manager_queries,
        manager_query_recipient=v_manager_recipient,
        completed_pack_copy_enabled=v_completed_copy,completed_pack_recipient=v_completed_recipient,
        created_by_user_id=v_actor,created_at_utc=pg_catalog.transaction_timestamp()
    where id=v_policy.id;
  else
    if v_policy_found then
      v_prior_end:=v_policy.effective_to;
      update public.weekly_source_client_policies set effective_to=v_effective_from-1
      where id=v_policy.id;
    else
      v_prior_end:=null;
    end if;
    insert into public.weekly_source_client_policies(
      source_group_id,client_id,effective_from,effective_to,
      authority_mode,document_mode,self_bill_enabled,self_bill_correction_presentation,
      source_fixed_expenses_enabled,source_expense_vat_enabled,
      weekly_rate_classification_method,duration_break_tie_rule,
      candidate_queries_enabled,manager_queries_enabled,manager_query_recipient,
      completed_pack_copy_enabled,completed_pack_recipient,created_by_user_id
    ) values (
      v_group_id,v_client,v_policy_effective_from,v_prior_end,
      v_authority,v_document,v_self_bill,v_correction,
      v_source_expenses,v_source_expense_vat,v_rate_method,v_tie_rule,
      v_candidate_queries,v_manager_queries,v_manager_recipient,
      v_completed_copy,v_completed_recipient,v_actor
    );
  end if;

  if v_old_group_id is not null and v_old_group_id<>v_group_id then
    perform private._weekly_source_settings_stale_open_v1(v_old_group_id,v_client);
  end if;
  perform private._weekly_source_settings_stale_open_v1(v_group_id,v_client);
  return private._weekly_source_settings_client_shape_v1(
    v_agency,v_environment,v_client,v_effective_from
  );
exception when exclusion_violation then
  raise exception 'WEEKLY_SOURCE_CLIENT_SETTINGS_EFFECTIVE_RANGE_CONFLICT' using errcode='23P01';
end;
$function$;

alter function private._weekly_source_settings_client_shape_v1(uuid,text,uuid,date) owner to current_user;
revoke all on function private._weekly_source_settings_client_shape_v1(uuid,text,uuid,date) from public,anon,authenticated,service_role;
alter function public.weekly_source_client_settings_save_atomic_v1(jsonb) owner to current_user;
revoke all on function public.weekly_source_client_settings_save_atomic_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_client_settings_save_atomic_v1(jsonb) to service_role;
notify pgrst, 'reload schema';


-- CONTACT_PREPARER_UNIT 39 repeatable supabase/repeatable/09102026_2018_banking_pay_next_foundation_pending_successors_v1.sql SHA256 680f09f32686a57fb934cd526ee2da5f6ad731f2859d9ed7c2e0644329e554a6
-- F-05 complete current successors of the22 changed functions in18 reviewed RESET deltas.
-- Reuse every unchanged function/body and installed migration. F-06 binding/evidence/readers
-- ship in the same release. F-04 sole target valuer is1157, never this file.
-- Owner/epoch admission and frozen input identity remain exactly the saved authorities.



-- F-05-D02 successor of supabase/repeatable/03102026_1530_banking_pay_next_ordinary_approval_v1.sql
create or replace function private.bpay_next_publish_ordinary_from_financial_v1(
  p_financial_id uuid
) returns uuid
language plpgsql security definer
set search_path = pg_catalog, public, private
as $function$
declare
  v_tf public.timesheets_financials%rowtype;
  v_ts public.timesheets%rowtype;
  v_contract public.contracts%rowtype;
  v_work private.bpay_next_work%rowtype;
  v_revision_id uuid;
  v_line_id uuid;
  v_shift_id uuid;
  v_command_id uuid:=pg_catalog.gen_random_uuid();
  v_mode text;
  v_route text;
  v_detail_kind text;
  v_segment jsonb;
  v_segment_row record;
  v_schedule jsonb;
  v_shift_entry jsonb;
  v_extra record;
  v_bucket record;
  v_break jsonb;
  v_segment_count integer:=0;
  v_additional_count integer:=0;
  v_expense_count integer:=0;
  v_mileage_count integer:=0;
  v_base_count integer:=0;
  v_expected_count integer;
  v_schedule_count integer;
  v_resolved_daily_rates boolean;
  v_available_daily_evidence jsonb;
  v_available_daily_rows jsonb;
  v_line_no integer:=0;
  v_rate_detail_count integer;
  v_break_no integer;
  v_shift_no integer;
  v_break_total integer;
  v_break_mins integer;
  v_begin_mins integer;
  v_end_mins integer;
  v_break_start text;
  v_break_end text;
  v_shift_start_local text;
  v_shift_end_local text;
  v_hours numeric;
  v_amount numeric;
  v_base_amount numeric;
  v_expense_total numeric;
  v_expected_total numeric;
  v_written_total numeric:=0;
  v_work_date date;
  v_component_key text;
  v_excluded boolean;
  v_candidate_name text;
  v_candidate_ref text;
  v_candidate_mileage_pay_rate numeric;
  v_client_name text;
  v_client_mileage_charge_rate numeric;
  v_mileage_pay_rate numeric;
  v_mileage_charge_rate numeric;
begin
  if p_financial_id is null then
    raise exception using errcode='22023', message='BPAY_NEXT_ORDINARY_FINANCIAL_ID_REQUIRED';
  end if;
  if (select active_owner from private.bpay_next_module_control
        where id=1 for share)<>'NEXT' then
    raise exception using errcode='55000', message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select * into strict v_tf from public.timesheets_financials
    where id=p_financial_id;
  select * into strict v_ts from public.timesheets
    where timesheet_id=v_tf.timesheet_id;
  select * into strict v_contract from public.contracts
    where id=v_ts.contract_id;
  v_route:=private.bpay_next_approval_route_v1(v_ts.timesheet_id);
  if v_route not in ('ORDINARY_HOURS','EXPENSE_CARRIER')
     or v_tf.is_current is distinct from true
     or v_tf.is_stale is distinct from false
     or v_tf.authorised_at_utc is null
     or v_ts.authorised_at_server is null
     or v_tf.timesheet_version<>v_ts.version
     or v_tf.candidate_id is distinct from v_contract.candidate_id
     or v_tf.client_id is distinct from v_contract.client_id
     or upper(coalesce(v_tf.pay_method,'')) not in ('PAYE','UMBRELLA') then
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_APPROVAL_NOT_CURRENT';
  end if;
  select coalesce(nullif(btrim(c.display_name),''),
                  nullif(btrim(concat_ws(' ',c.first_name,c.last_name)),''),
                  c.id::text),c.tms_ref,c.mileage_pay_rate
    into strict v_candidate_name,v_candidate_ref,v_candidate_mileage_pay_rate
    from public.candidates c where c.id=v_contract.candidate_id;
  select name,mileage_charge_rate into strict
    v_client_name,v_client_mileage_charge_rate from public.clients
    where id=v_contract.client_id;
  v_mode:=upper(coalesce(v_tf.invoice_breakdown_json->>'mode',''));
  if v_mode='SEGMENTS' then
    if jsonb_typeof(v_tf.invoice_breakdown_json->'segments')<>'array' then
      raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_SEGMENTS_NOT_ARRAY';
    end if;
    v_segment_count:=jsonb_array_length(v_tf.invoice_breakdown_json->'segments');
    -- Validate identities before grouping. Physical segment IDs are retained
    -- as original evidence, not continuing financial obligations.
    for v_segment in select value from jsonb_array_elements(
      v_tf.invoice_breakdown_json->'segments')
    loop
      if jsonb_typeof(v_segment)<>'object'
         or nullif(btrim(v_segment->>'segment_id'),'') is null
         or coalesce(v_segment->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_SEGMENT_ID_OR_DATE_INVALID';
      end if;
    end loop;
    select count(distinct (value->>'date')::date) into v_segment_count
      from jsonb_array_elements(v_tf.invoice_breakdown_json->'segments');
    v_detail_kind:='SHIFT';
  elsif v_mode='AGGREGATE' then
    v_detail_kind:='AGGREGATE';
    v_base_amount:=v_tf.total_pay_ex_vat-v_tf.additional_pay_ex_vat
      -coalesce(v_tf.expenses_pay_ex_vat,0)-coalesce(v_tf.mileage_pay_ex_vat,0);
    v_base_count:=case when v_base_amount<>0 or v_tf.total_hours<>0 then 1 else 0 end;
  elsif v_mode='EXPENSES_ONLY' and v_route='EXPENSE_CARRIER' then
    v_detail_kind:='FIXED';
  else
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_FINANCIAL_MODE_UNSUPPORTED';
  end if;
  if jsonb_typeof(v_tf.additional_units_json)<>'object' then
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_ADDITIONAL_NOT_OBJECT';
  end if;
  select count(*) into v_additional_count from jsonb_each(v_tf.additional_units_json);
  if v_route='EXPENSE_CARRIER' then
    if v_segment_count<>0 or v_base_count<>0 or v_additional_count<>0
       or v_tf.total_hours<>0 or v_tf.additional_pay_ex_vat<>0
       or v_tf.hours_day<>0 or v_tf.hours_night<>0
       or v_tf.hours_sat<>0 or v_tf.hours_sun<>0 or v_tf.hours_bh<>0
       or v_tf.total_pay_ex_vat is distinct from
          coalesce(v_tf.expenses_pay_ex_vat,0)+coalesce(v_tf.mileage_pay_ex_vat,0) then
      raise exception using errcode='23514', message='BPAY_NEXT_EXPENSE_CARRIER_MONEY_SHAPE_INVALID';
    end if;
    v_detail_kind:='FIXED';
  end if;
  v_expense_total:=coalesce(v_tf.travel_pay_ex_vat,0)
    +coalesce(v_tf.accommodation_pay_ex_vat,0)+coalesce(v_tf.other_pay_ex_vat,0);
  if v_expense_total<>0 then
    if coalesce(v_tf.expenses_pay_ex_vat,0) not in (0,v_expense_total) then
      raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_EXPENSE_TOTAL_CONFLICT';
    end if;
    v_expense_count:=(case when v_tf.travel_pay_ex_vat<>0 then 1 else 0 end)
      +(case when v_tf.accommodation_pay_ex_vat<>0 then 1 else 0 end)
      +(case when v_tf.other_pay_ex_vat<>0 then 1 else 0 end);
  else
    v_expense_total:=coalesce(v_tf.expenses_pay_ex_vat,0);
    v_expense_count:=case when v_expense_total<>0 then 1 else 0 end;
  end if;
  v_mileage_count:=case when v_tf.mileage_pay_ex_vat<>0
    or v_tf.mileage_units<>0 then 1 else 0 end;
  v_expected_count:=v_segment_count+v_base_count+v_additional_count
    +v_expense_count+v_mileage_count;
  -- Both production snapshot writers include additional pay, expenses and
  -- mileage in total_pay_ex_vat. They are components of this total, not extras.
  v_expected_total:=v_tf.total_pay_ex_vat;
  if v_expected_total<>round(v_expected_total,2)
     or v_tf.total_pay_ex_vat<>round(v_tf.total_pay_ex_vat,2)
     or v_tf.additional_pay_ex_vat<>round(v_tf.additional_pay_ex_vat,2)
     or v_tf.expenses_pay_ex_vat<>round(v_tf.expenses_pay_ex_vat,2)
     or v_tf.travel_pay_ex_vat<>round(v_tf.travel_pay_ex_vat,2)
     or v_tf.accommodation_pay_ex_vat<>round(v_tf.accommodation_pay_ex_vat,2)
     or v_tf.other_pay_ex_vat<>round(v_tf.other_pay_ex_vat,2)
     or v_tf.mileage_pay_ex_vat<>round(v_tf.mileage_pay_ex_vat,2) then
    raise exception using errcode='22003', message='BPAY_NEXT_ORDINARY_MONEY_PRECISION_INVALID';
  end if;
  v_mileage_pay_rate:=coalesce(v_tf.mileage_pay_rate,
                               v_contract.mileage_pay_rate,
                               v_candidate_mileage_pay_rate);
  v_mileage_charge_rate:=coalesce(v_tf.mileage_charge_rate,
                                  v_contract.mileage_charge_rate,
                                  v_client_mileage_charge_rate);
  v_resolved_daily_rates:=v_route in ('ORDINARY_HOURS','DAILY_HOURS')
    and v_ts.sheet_scope='DAILY'::public.timesheet_scope_enum;
  if v_resolved_daily_rates then
    v_available_daily_evidence:=private.bpay_next_daily_approval_evidence_v1(v_tf.id);
    select (v_available_daily_evidence->'rates')
      ||coalesce(jsonb_agg(to_jsonb(r) order by r.rate_family,r.rate_code),'[]'::jsonb)
      into v_available_daily_rows
      from private.bpay_next_contract_rate_rows_v1(
        '{}'::jsonb,v_contract.bucket_labels_json,v_contract.additional_rates_json,
        v_mileage_pay_rate,v_mileage_charge_rate) r;
    v_schedule_count:=jsonb_array_length(v_available_daily_rows);
  else
    select count(*) into v_schedule_count
      from private.bpay_next_contract_rate_rows_v1(
        v_contract.rates_json,v_contract.bucket_labels_json,v_contract.additional_rates_json,
        v_mileage_pay_rate,v_mileage_charge_rate);
  end if;

  insert into private.bpay_next_worker_control(candidate_id)
    values (v_contract.candidate_id) on conflict (candidate_id) do nothing;
  select * into v_work from private.bpay_next_work
    where booking_id=v_ts.booking_id for update;
  if not found then
    insert into private.bpay_next_work
      (candidate_id,contract_id,original_timesheet_id,booking_id,
       work_kind,week_ending_date)
      values (v_contract.candidate_id,v_contract.id,v_ts.timesheet_id,
              v_ts.booking_id,
              case when v_route='EXPENSE_CARRIER' then 'EXPENSE' else 'ORDINARY' end,
              v_ts.week_ending_date)
      returning * into v_work;
  elsif v_work.candidate_id<>v_contract.candidate_id
     or v_work.contract_id<>v_contract.id
     or v_work.week_ending_date<>v_ts.week_ending_date
     or v_work.work_kind<>(case when v_route='EXPENSE_CARRIER'
       then 'EXPENSE' else 'ORDINARY' end) then
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_WORK_IDENTITY_CONFLICT';
  end if;
  insert into private.bpay_next_work_revision
    (work_id,revision_no,source_kind,physical_timesheet_id,
     financial_snapshot_id,physical_timesheet_version,
     source_pay_channel,week_ending_date,detail_kind,
     expected_line_count,expected_rate_schedule_count,certified_zero,
     approved_source_ex_vat,candidate_display_name,candidate_reference,
     client_display_name,job_title,band_label,timesheet_reference)
    values (v_work.id,v_work.current_revision_no+1,
            case when v_route='EXPENSE_CARRIER' then 'EXPENSE' else 'ORDINARY' end,
            v_ts.timesheet_id,v_tf.id,v_ts.version,upper(v_tf.pay_method),
            v_ts.week_ending_date,v_detail_kind,v_expected_count,
            v_schedule_count,v_expected_total=0,v_expected_total,
            v_candidate_name,v_candidate_ref,v_client_name,
            v_contract.role,v_contract.band,v_ts.reference_number)
    returning id into v_revision_id;
  if v_resolved_daily_rates then
    insert into private.bpay_next_rate_schedule
      (revision_id,rate_family,rate_code,unit_label,paye_rate,umbrella_rate,charge_rate)
      select v_revision_id,r.rate_family,r.rate_code,r.unit_label,r.paye_rate,r.umbrella_rate,r.charge_rate
      from jsonb_to_recordset(v_available_daily_rows)
        r(rate_family text,rate_code text,unit_label text,paye_rate numeric,umbrella_rate numeric,charge_rate numeric);
  else
    insert into private.bpay_next_rate_schedule
      (revision_id,rate_family,rate_code,unit_label,paye_rate,umbrella_rate,charge_rate)
      select v_revision_id,r.rate_family,r.rate_code,r.unit_label,r.paye_rate,r.umbrella_rate,r.charge_rate
      from private.bpay_next_contract_rate_rows_v1(
        v_contract.rates_json,v_contract.bucket_labels_json,v_contract.additional_rates_json,
        v_mileage_pay_rate,v_mileage_charge_rate) r;
  end if;

  if v_mode='SEGMENTS' then
    -- One pass ordered by stable business date and original array ordinal.
    -- Window sums use exact stored amounts, not a new hours/rates calculator.
    -- Child INSERTs retain every original shift, including zero/excluded ones.
    for v_segment_row in
      select value,ordinality,
        row_number() over day_order as detail_no,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
            then 0 else (value->>'pay_amount')::numeric end) over day_set as day_pay,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_day')::numeric,0)
          +coalesce((value->>'hours_night')::numeric,0)
          +coalesce((value->>'hours_sat')::numeric,0)
          +coalesce((value->>'hours_sun')::numeric,0)
          +coalesce((value->>'hours_bh')::numeric,0) end) over day_set as day_hours,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_day')::numeric,0) end) over day_set as day_day,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_night')::numeric,0) end) over day_set as day_night,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_sat')::numeric,0) end) over day_set as day_sat,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_sun')::numeric,0) end) over day_set as day_sun,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_bh')::numeric,0) end) over day_set as day_bh
      from jsonb_array_elements(v_tf.invoice_breakdown_json->'segments') with ordinality
      window day_set as (partition by (value->>'date')::date),
        day_order as (partition by (value->>'date')::date order by ordinality)
      order by (value->>'date')::date,ordinality
    loop
      v_segment:=v_segment_row.value;
      if jsonb_typeof(v_segment)<>'object'
         or nullif(btrim(v_segment->>'segment_id'),'') is null
         or coalesce(v_segment->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_SEGMENT_ID_OR_DATE_INVALID';
      end if;
      v_work_date:=(v_segment->>'date')::date;
      -- TS_DAY is the supported payment choice. A new physical UUID, edited
      -- clock/break or array order cannot create another DAY obligation.
      -- Per-segment authorisation exclusions remain independent below.
      v_component_key:='WORK:DAY:'||v_work_date::text;
      v_excluded:=coalesce((v_segment->>'exclude_from_pay')::boolean,false);
      v_amount:=case when v_excluded then 0
        else (v_segment->>'pay_amount')::numeric end;
      if v_amount is null or v_amount<>round(v_amount,2) then
        raise exception using errcode='22003', message='BPAY_NEXT_ORDINARY_SEGMENT_AMOUNT_INVALID';
      end if;
      v_hours:=0; v_rate_detail_count:=0;
      for v_bucket in select * from (values
        ('DAY'::text,'hours_day'::text,v_tf.pay_day),
        ('NIGHT','hours_night',v_tf.pay_night),
        ('SAT','hours_sat',v_tf.pay_sat),
        ('SUN','hours_sun',v_tf.pay_sun),
        ('BH','hours_bh',v_tf.pay_bh)) b(code,hours_key,pay_rate)
      loop
        if coalesce((v_segment->>v_bucket.hours_key)::numeric,0)<0
           or coalesce((v_segment->>v_bucket.hours_key)::numeric,0)
                <>round(coalesce((v_segment->>v_bucket.hours_key)::numeric,0),6) then
          raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_SEGMENT_HOURS_INVALID';
        end if;
        v_hours:=v_hours+coalesce((v_segment->>v_bucket.hours_key)::numeric,0);
        if not v_excluded and coalesce((v_segment->>v_bucket.hours_key)::numeric,0)>0 then
          if v_bucket.pay_rate is null
             or v_bucket.pay_rate<>round(v_bucket.pay_rate,6)
             or abs(v_bucket.pay_rate)>=1000000000000 then
            raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_USED_RATE_MISSING';
          end if;
          v_rate_detail_count:=v_rate_detail_count+1;
        end if;
      end loop;
      if v_segment_row.detail_no=1 then
        v_rate_detail_count:=(case when v_segment_row.day_day>0 then 1 else 0 end)
          +(case when v_segment_row.day_night>0 then 1 else 0 end)
          +(case when v_segment_row.day_sat>0 then 1 else 0 end)
          +(case when v_segment_row.day_sun>0 then 1 else 0 end)
          +(case when v_segment_row.day_bh>0 then 1 else 0 end);
        v_line_no:=v_line_no+1;
        insert into private.bpay_next_approved_line
          (revision_id,line_no,component_key,component_kind,work_date,
           approved_quantity,expected_rate_detail_count,source_pay_ex_vat,tax_treatment,evidence_ref)
          values (v_revision_id,v_line_no,v_component_key,'WORK',v_work_date,
            v_segment_row.day_hours,v_rate_detail_count,v_segment_row.day_pay,'TAXABLE',
            'timesheets_financials:'||v_tf.id::text||'#day:'||v_work_date::text)
          returning id into v_line_id;
        insert into private.bpay_next_rate_detail
          (approved_line_id,bucket,approved_hours,source_pay_rate)
          select v_line_id,b.code,b.hours,b.pay_rate from (values
            ('DAY'::text,v_segment_row.day_day,v_tf.pay_day),
            ('NIGHT',v_segment_row.day_night,v_tf.pay_night),
            ('SAT',v_segment_row.day_sat,v_tf.pay_sat),
            ('SUN',v_segment_row.day_sun,v_tf.pay_sun),
            ('BH',v_segment_row.day_bh,v_tf.pay_bh)) b(code,hours,pay_rate)
          where b.hours>0;
      end if;
      v_shift_start_local:=nullif(btrim(coalesce(v_segment->>'start_local',v_segment->>'start','')),'');
      v_shift_end_local:=nullif(btrim(coalesce(v_segment->>'end_local',v_segment->>'end','')),'');
      if (v_shift_start_local is null)<>(v_shift_end_local is null)
         or (v_shift_start_local is not null and
           (v_shift_start_local !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
            or v_shift_end_local !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')) then
        raise exception using errcode='23514',message='BPAY_NEXT_ORDINARY_SCHEDULE_CLOCK_INVALID';
      end if;
      insert into private.bpay_next_shift_detail
        (approved_line_id,detail_no,work_date,shift_start_at,shift_end_at,
         shift_start_local,shift_end_local,shift_overnight,
         approved_minutes,approved_hours,immutable_evidence_ref,
         segment_pay_ex_vat,pay_excluded,hours_day,hours_night,hours_sat,hours_sun,hours_bh)
        values (v_line_id,v_segment_row.detail_no::integer,v_work_date,
          nullif(v_segment->>'start_utc','')::timestamptz,
          nullif(v_segment->>'end_utc','')::timestamptz,
          v_shift_start_local,v_shift_end_local,
          nullif(v_segment->>'overnight','')::boolean,
          case when v_hours*60=trunc(v_hours*60) then (v_hours*60)::integer end,
          v_hours,'timesheets_financials:'||v_tf.id::text||'#segment:'||v_segment_row.ordinality::text,
          v_amount,v_excluded,
          coalesce((v_segment->>'hours_day')::numeric,0),
          coalesce((v_segment->>'hours_night')::numeric,0),
          coalesce((v_segment->>'hours_sat')::numeric,0),
          coalesce((v_segment->>'hours_sun')::numeric,0),
          coalesce((v_segment->>'hours_bh')::numeric,0)) returning id into v_shift_id;
      v_break_total:=0; v_break_no:=0;
      if v_segment ? 'breaks' and jsonb_typeof(v_segment->'breaks')<>'array' then
        raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_BREAK_SHAPE_INVALID';
      end if;
      for v_break in select value from jsonb_array_elements(
        coalesce(v_segment->'breaks','[]'::jsonb))
      loop
        v_break_start:=v_break->>'start';
        v_break_end:=v_break->>'end';
        if jsonb_typeof(v_break)<>'object'
           or coalesce(v_break_start,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
           or coalesce(v_break_end,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
          raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_BREAK_CLOCK_INVALID';
        end if;
        v_begin_mins:=substring(v_break_start,1,2)::integer*60
          +substring(v_break_start,4,2)::integer;
        v_end_mins:=substring(v_break_end,1,2)::integer*60
          +substring(v_break_end,4,2)::integer;
        v_break_mins:=(v_end_mins-v_begin_mins+1440)%1440;
        if v_break_mins=0 then
          raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_BREAK_ZERO_WINDOW';
        end if;
        v_break_no:=v_break_no+1;
        v_break_total:=v_break_total+v_break_mins;
        insert into private.bpay_next_break_detail
          (shift_detail_id,break_no,break_start_local,break_end_local,break_minutes)
          values (v_shift_id,v_break_no,v_break_start,v_break_end,v_break_mins);
      end loop;
      if v_break_no=0 and coalesce((v_segment->>'break_mins')::integer,
                                   (v_segment->>'break_minutes')::integer,0)>0 then
        insert into private.bpay_next_break_detail
          (shift_detail_id,break_no,break_minutes)
          values (v_shift_id,1,coalesce((v_segment->>'break_mins')::integer,
                                        (v_segment->>'break_minutes')::integer));
      elsif v_break_no>0 and (v_segment ? 'break_mins' or v_segment ? 'break_minutes')
         and v_break_total<>coalesce((v_segment->>'break_mins')::integer,
                                    (v_segment->>'break_minutes')::integer) then
        raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_BREAK_DURATION_CONFLICT';
      end if;
      v_written_total:=v_written_total+v_amount;
    end loop;
  elsif v_base_count=1 then
    for v_bucket in select * from (values
      (v_tf.hours_day,v_tf.pay_day),(v_tf.hours_night,v_tf.pay_night),
      (v_tf.hours_sat,v_tf.pay_sat),(v_tf.hours_sun,v_tf.pay_sun),
      (v_tf.hours_bh,v_tf.pay_bh)) b(hours,pay_rate)
    loop
      if v_bucket.hours<0 or v_bucket.hours<>round(v_bucket.hours,6)
         or (v_bucket.hours>0 and
             (v_bucket.pay_rate is null
              or v_bucket.pay_rate<>round(v_bucket.pay_rate,6)
              or abs(v_bucket.pay_rate)>=1000000000000)) then
        raise exception using errcode='23514',
          message='BPAY_NEXT_ORDINARY_AGGREGATE_RATE_INVALID';
      end if;
    end loop;
    v_rate_detail_count:=
      (case when v_tf.hours_day>0 then 1 else 0 end)
      +(case when v_tf.hours_night>0 then 1 else 0 end)
      +(case when v_tf.hours_sat>0 then 1 else 0 end)
      +(case when v_tf.hours_sun>0 then 1 else 0 end)
      +(case when v_tf.hours_bh>0 then 1 else 0 end);
    v_line_no:=v_line_no+1;
    insert into private.bpay_next_approved_line
      (revision_id,line_no,component_key,component_kind,approved_quantity,
       expected_rate_detail_count,source_pay_ex_vat,tax_treatment,evidence_ref)
      values (v_revision_id,v_line_no,'WORK:AGGREGATE','WORK',v_tf.total_hours,
              v_rate_detail_count,v_base_amount,'TAXABLE',
              'timesheets_financials:'||v_tf.id::text||'#aggregate')
      returning id into v_line_id;
    insert into private.bpay_next_rate_detail
      (approved_line_id,bucket,approved_hours,source_pay_rate)
      select v_line_id,b.code,b.hours,b.pay_rate
      from (values ('DAY'::text,v_tf.hours_day,v_tf.pay_day),
                   ('NIGHT',v_tf.hours_night,v_tf.pay_night),
                   ('SAT',v_tf.hours_sat,v_tf.pay_sat),
                   ('SUN',v_tf.hours_sun,v_tf.pay_sun),
                   ('BH',v_tf.hours_bh,v_tf.pay_bh)) b(code,hours,pay_rate)
      where b.hours>0;
    -- An AGGREGATE money line can still originate from an entered weekly
    -- schedule. Keep the entered date/clock/break evidence as small typed
    -- children, without inventing a money split across those shifts.
    if v_tf.actual_schedule_json is not null
       and jsonb_typeof(v_tf.actual_schedule_json)<>'array' then
      raise exception using errcode='23514',
        message='BPAY_NEXT_ORDINARY_SCHEDULE_SHAPE_INVALID';
    end if;
    v_schedule:=case
      when jsonb_typeof(v_tf.actual_schedule_json)='array'
       and jsonb_array_length(v_tf.actual_schedule_json)>0
        then v_tf.actual_schedule_json
      else v_ts.actual_schedule_json end;
    if v_schedule is not null and jsonb_typeof(v_schedule)<>'array' then
      raise exception using errcode='23514',
        message='BPAY_NEXT_ORDINARY_SCHEDULE_SHAPE_INVALID';
    end if;
    v_shift_no:=0;
    for v_shift_entry in select value from jsonb_array_elements(
      coalesce(v_schedule,'[]'::jsonb))
    loop
      if jsonb_typeof(v_shift_entry)<>'object'
         or coalesce(v_shift_entry->>'date',v_shift_entry->>'work_date','')
              !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception using errcode='23514',
          message='BPAY_NEXT_ORDINARY_SCHEDULE_DATE_INVALID';
      end if;
      v_shift_start_local:=nullif(btrim(coalesce(v_shift_entry->>'start','')),'');
      v_shift_end_local:=nullif(btrim(coalesce(v_shift_entry->>'end','')),'');
      if (v_shift_start_local is null)<>(v_shift_end_local is null)
         or (v_shift_start_local is not null and
             (v_shift_start_local !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
              or v_shift_end_local !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')) then
        raise exception using errcode='23514',
          message='BPAY_NEXT_ORDINARY_SCHEDULE_CLOCK_INVALID';
      end if;
      v_shift_no:=v_shift_no+1;
      insert into private.bpay_next_shift_detail
        (approved_line_id,detail_no,work_date,shift_start_at,shift_end_at,
         shift_start_local,shift_end_local,approved_minutes,approved_hours)
        values (v_line_id,v_shift_no,
          coalesce(v_shift_entry->>'date',v_shift_entry->>'work_date')::date,
          nullif(v_shift_entry->>'start_utc','')::timestamptz,
          nullif(v_shift_entry->>'end_utc','')::timestamptz,
          v_shift_start_local,v_shift_end_local,
          nullif(v_shift_entry->>'worked_minutes','')::integer,
          nullif(v_shift_entry->>'approved_hours','')::numeric)
        returning id into v_shift_id;
      if v_shift_entry ? 'breaks'
         and jsonb_typeof(v_shift_entry->'breaks') not in ('array','null') then
        raise exception using errcode='23514',
          message='BPAY_NEXT_ORDINARY_BREAK_SHAPE_INVALID';
      end if;
      v_break_no:=0; v_break_total:=0;
      for v_break in select value from jsonb_array_elements(
        case when jsonb_typeof(v_shift_entry->'breaks')='array'
          then v_shift_entry->'breaks' else '[]'::jsonb end)
      loop
        v_break_start:=v_break->>'start';
        v_break_end:=v_break->>'end';
        if jsonb_typeof(v_break)<>'object'
           or coalesce(v_break_start,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
           or coalesce(v_break_end,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
          raise exception using errcode='23514',
            message='BPAY_NEXT_ORDINARY_BREAK_CLOCK_INVALID';
        end if;
        v_begin_mins:=substring(v_break_start,1,2)::integer*60
          +substring(v_break_start,4,2)::integer;
        v_end_mins:=substring(v_break_end,1,2)::integer*60
          +substring(v_break_end,4,2)::integer;
        v_break_mins:=(v_end_mins-v_begin_mins+1440)%1440;
        if v_break_mins=0 then
          raise exception using errcode='23514',
            message='BPAY_NEXT_ORDINARY_BREAK_ZERO_WINDOW';
        end if;
        v_break_no:=v_break_no+1;
        v_break_total:=v_break_total+v_break_mins;
        insert into private.bpay_next_break_detail
          (shift_detail_id,break_no,break_start_local,break_end_local,break_minutes)
          values (v_shift_id,v_break_no,v_break_start,v_break_end,v_break_mins);
      end loop;
      if v_break_no=0
         and coalesce((v_shift_entry->>'break_minutes')::integer,
                      (v_shift_entry->>'break_mins')::integer,0)>0 then
        insert into private.bpay_next_break_detail
          (shift_detail_id,break_no,break_minutes)
          values (v_shift_id,1,
            coalesce((v_shift_entry->>'break_minutes')::integer,
                     (v_shift_entry->>'break_mins')::integer));
      elsif v_break_no>0
         and (v_shift_entry ? 'break_minutes' or v_shift_entry ? 'break_mins')
         and v_break_total<>coalesce((v_shift_entry->>'break_minutes')::integer,
                                    (v_shift_entry->>'break_mins')::integer) then
        raise exception using errcode='23514',
          message='BPAY_NEXT_ORDINARY_BREAK_DURATION_CONFLICT';
      end if;
    end loop;
    v_written_total:=v_written_total+v_base_amount;
  end if;

  for v_extra in select key,value from jsonb_each(v_tf.additional_units_json)
                 order by key
  loop
    if jsonb_typeof(v_extra.value)<>'object'
       or nullif(btrim(v_extra.key),'') is null
       or length('ADDITIONAL:'||upper(btrim(v_extra.key)))>256 then
      raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_ADDITIONAL_SHAPE_INVALID';
    end if;
    v_amount:=coalesce((v_extra.value->>'pay_ex_vat')::numeric,
      (v_extra.value->>'amount_ex_vat')::numeric,
      coalesce((v_extra.value->>'unit_count')::numeric,
               (v_extra.value->>'units_week')::numeric,0)
       *coalesce((v_extra.value->>'pay_rate')::numeric,
                 (v_extra.value->>'rate')::numeric,0));
    if v_amount<>round(v_amount,2) then
      raise exception using errcode='22003', message='BPAY_NEXT_ORDINARY_ADDITIONAL_PRECISION_INVALID';
    end if;
    v_line_no:=v_line_no+1;
    insert into private.bpay_next_approved_line
      (revision_id,line_no,component_key,component_kind,unit_label,
       approved_quantity,approved_unit_rate,source_pay_ex_vat,evidence_ref)
      values (v_revision_id,v_line_no,'ADDITIONAL:'||upper(btrim(v_extra.key)),
        'ADDITIONAL',nullif(v_extra.value->>'unit_name',''),
        coalesce((v_extra.value->>'unit_count')::numeric,
                 (v_extra.value->>'units_week')::numeric),
        coalesce((v_extra.value->>'pay_rate')::numeric,
                 (v_extra.value->>'rate')::numeric),v_amount,
        'timesheets_financials:'||v_tf.id::text||'#additional:'||v_extra.key);
    v_written_total:=v_written_total+v_amount;
  end loop;
  if v_written_total <> v_tf.total_pay_ex_vat-v_expense_total
      -v_tf.mileage_pay_ex_vat then
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_WORK_TOTAL_MISMATCH';
  end if;

  for v_extra in select * from (values
      ('TRAVEL'::text,v_tf.travel_pay_ex_vat),
      ('ACCOMMODATION',v_tf.accommodation_pay_ex_vat),
      ('OTHER',v_tf.other_pay_ex_vat),
      ('EXPENSES',case when v_expense_count=1
        and v_tf.travel_pay_ex_vat=0 and v_tf.accommodation_pay_ex_vat=0
        and v_tf.other_pay_ex_vat=0 then v_expense_total else 0 end)) x(code,amount)
  loop
    if v_extra.amount<>0 then
      if v_extra.amount<>round(v_extra.amount,2) then
        raise exception using errcode='22003', message='BPAY_NEXT_ORDINARY_EXPENSE_PRECISION_INVALID';
      end if;
      v_line_no:=v_line_no+1;
      insert into private.bpay_next_approved_line
        (revision_id,line_no,component_key,component_kind,
         source_pay_ex_vat,evidence_ref)
        values (v_revision_id,v_line_no,'EXPENSE:'||v_extra.code,'EXPENSE',
          v_extra.amount,'timesheets_financials:'||v_tf.id::text||'#expense:'||v_extra.code);
      v_written_total:=v_written_total+v_extra.amount;
    end if;
  end loop;
  if v_mileage_count=1 then
    v_line_no:=v_line_no+1;
    insert into private.bpay_next_approved_line
      (revision_id,line_no,component_key,component_kind,unit_label,
       approved_quantity,approved_unit_rate,source_pay_ex_vat,evidence_ref)
      values (v_revision_id,v_line_no,'MILEAGE:MILE','MILEAGE','mile',
        v_tf.mileage_units,v_mileage_pay_rate,v_tf.mileage_pay_ex_vat,
        'timesheets_financials:'||v_tf.id::text||'#mileage');
    v_written_total:=v_written_total+v_tf.mileage_pay_ex_vat;
  end if;
  if v_line_no<>v_expected_count or v_written_total<>v_expected_total then
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_COMPONENT_TOTAL_MISMATCH';
  end if;
  perform private.bpay_next_publish_staged_revision_v1(
    v_work.id,v_revision_id,v_command_id);
  return v_revision_id;
end
$function$;

ALTER FUNCTION private.bpay_next_publish_ordinary_from_financial_v1(uuid) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_publish_ordinary_from_financial_v1(uuid) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D01 successor of supabase/repeatable/03102026_1600_banking_pay_next_prepare_pin_v1.sql
create or replace function private.bpay_next_claim_prepare_job_v1(
  p_job_id uuid,p_lease_seconds integer default 120
) returns table(lease_nonce uuid,owner_epoch bigint)
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_job private.bpay_next_job%rowtype;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_run_id uuid;
  v_module_epoch bigint;
  v_channel text;
  v_umbrella_id uuid;
  v_umbrella_vat_chargeable boolean;
  v_owner_epoch bigint;
  v_nonce uuid;
begin
  if p_job_id is null or p_lease_seconds not between 1 and 120 then
    raise exception using errcode='22023',
      message='BPAY_NEXT_PREPARE_LEASE_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_module_epoch
    from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_module_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select j.candidate_id,rc.run_id into strict v_job.candidate_id,v_run_id
    from private.bpay_next_job j
    join private.bpay_next_run_command rc on rc.command_id=j.command_id
    where j.id=p_job_id and j.job_kind='PREPARE';
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for share;
  insert into private.bpay_next_worker_control(candidate_id)
    values(v_job.candidate_id) on conflict(candidate_id) do nothing;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_job.candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED'
     or v_job.job_kind<>'PREPARE' or v_job.module_epoch<>v_module_epoch
     or not exists(select 1 from private.bpay_next_command command
       where command.id=v_job.command_id and command.agency_sequence=v_job.command_sequence
         and command.module_epoch=v_module_epoch and command.command_kind='PREPARE'
         and command.status='SEALED' and command.sealed_at_utc is not null
         and command.expected_member_count=v_run.selected_candidate_count
         and command.enrolled_member_count=command.expected_member_count)
     or v_job.status not in ('READY','LEASED')
     or (v_job.status='LEASED'
       and v_job.lease_until_utc>pg_catalog.clock_timestamp()) then
    raise exception using errcode='55000',
      message='BPAY_NEXT_PREPARE_JOB_NOT_CLAIMABLE';
  end if;
  if exists(select 1 from private.bpay_next_job earlier
      where earlier.candidate_id=v_job.candidate_id
        and earlier.command_sequence<v_job.command_sequence
        and earlier.status<>'DONE') then
    raise exception using errcode='55000',
      message='BPAY_NEXT_EARLIER_WORKER_COMMAND_PENDING';
  end if;
  select * into v_worker from private.bpay_next_run_worker
    where run_id=v_run_id and candidate_id=v_job.candidate_id for update;
  if not found then
    select upper(c.pay_method),c.umbrella_id,u.vat_chargeable
      into strict v_channel,v_umbrella_id,v_umbrella_vat_chargeable
      from public.candidates c
      left join public.umbrellas u on u.id=c.umbrella_id
      where c.id=v_job.candidate_id for share of c;
    if v_channel not in ('PAYE','UMBRELLA') then
      raise exception using errcode='23514',
        message='BPAY_NEXT_PREPARE_PAY_CHANNEL_UNSUPPORTED';
    end if;
    insert into private.bpay_next_run_worker
      (run_id,candidate_id,target_pay_channel,target_umbrella_id,
       target_umbrella_vat_chargeable,status)
      values(v_run_id,v_job.candidate_id,v_channel,
        case when v_channel='UMBRELLA' then v_umbrella_id else null end,
        case when v_channel='UMBRELLA' then v_umbrella_vat_chargeable
          else null end,'PREPARING')
      returning * into v_worker;
  elsif v_worker.status<>'PREPARING' then
    raise exception using errcode='55000',
      message='BPAY_NEXT_PREPARE_WORKER_STATE_CHANGED';
  end if;
  update private.bpay_next_worker_control
    set active_owner_epoch=active_owner_epoch+1,
        updated_at_utc=pg_catalog.transaction_timestamp()
    where candidate_id=v_job.candidate_id
    returning active_owner_epoch into v_owner_epoch;
  v_nonce:=pg_catalog.gen_random_uuid();
  update private.bpay_next_job
    set status='LEASED',owner_epoch=v_owner_epoch,lease_nonce=v_nonce,
        lease_until_utc=pg_catalog.clock_timestamp()
          +pg_catalog.make_interval(secs=>p_lease_seconds),
        attempt_count=attempt_count+1
    where id=p_job_id;
  lease_nonce:=v_nonce;owner_epoch:=v_owner_epoch;
  return next;
end
$function$;

ALTER FUNCTION private.bpay_next_claim_prepare_job_v1(uuid,integer) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_claim_prepare_job_v1(uuid,integer) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D06 successor of supabase/repeatable/03102026_1610_banking_pay_next_position_capture_v1.sql
create or replace function private.bpay_next_capture_position_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_work_cursor uuid,p_expected_component_cursor text,
  p_limit integer default 100
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private
as $function$
declare
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_module_epoch bigint;
  v_row record;
  v_member record;
  v_seen integer:=0;
  v_selected_seen integer:=0;
  v_resolution_count integer:=0;
  v_managed_seen integer:=0;
  v_needs_resolution boolean;
  v_collection private.bpay_next_work_collection%rowtype;
  v_work_cursor uuid;
  v_component_cursor text;
  v_issue text;
  v_issue_work_id uuid;
  v_query_pin private.bpay_next_run_work_query_pin_v2%rowtype;
  v_binding private.bpay_next_source_component_binding_version%rowtype;v_book record;
  v_seed_effect uuid;v_seed_hold uuid;v_seed_holds uuid[];v_seed record;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_limit not between 1 and 100
     or (p_expected_work_cursor is null and p_expected_component_cursor is not null) then
    raise exception using errcode='22023',
      message='BPAY_NEXT_CAPTURE_POSITION_INPUT_INVALID';
  end if;
  select rc.run_id into strict v_run_id
    from private.bpay_next_job j
    join private.bpay_next_run_command rc on rc.command_id=j.command_id
    where j.id=p_job_id and j.job_kind='PREPARE';
  select m.owner_epoch into v_module_epoch
    from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_module_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for share;
  select candidate_id into strict v_job.candidate_id
    from private.bpay_next_job where id=p_job_id;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_job.candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED'
     or v_job.job_kind<>'PREPARE' or v_job.status<>'LEASED'
     or v_job.phase not in ('RESERVE','ALLOCATE')
     or v_job.module_epoch<>v_module_epoch
     or v_job.lease_nonce<>p_lease_nonce
     or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CAPTURE_POSITION_LEASE_STALE';
  end if;
  if v_job.phase='ALLOCATE' then
    return pg_catalog.jsonb_build_object('done',true,'phase','ALLOCATE',
      'replay',true,'rows_visited',0);
  end if;
  if v_job.position_work_cursor is distinct from p_expected_work_cursor
     or v_job.position_component_cursor is distinct from p_expected_component_cursor then
    return pg_catalog.jsonb_build_object('done',false,'phase','RESERVE',
      'replay',true,'rows_visited',0,
      'work_cursor',v_job.position_work_cursor,
      'component_cursor',v_job.position_component_cursor);
  end if;
  select * into strict v_worker from private.bpay_next_run_worker
    where run_id=v_run_id and candidate_id=v_job.candidate_id for update;
  if v_worker.status<>'PREPARING' or v_worker.review_issue_code is not null then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CAPTURE_POSITION_WORKER_NOT_PREPARING';
  end if;
  v_work_cursor:=v_job.position_work_cursor;
  v_component_cursor:=v_job.position_component_cursor;
  for v_member in
    -- Each lane emits at most one page before the bounded merge. SUBSET is
    -- driven by selected membership, not an EXISTS filter over all positions.
    -- A selected missing position remains a member and is refused below.
    with all_page as materialized (
      select rw.id as run_work_id,rw.work_id,rw.captured_revision_id,
             p.component_key,'ALL'::text as selection_mode
        from private.bpay_next_run_work rw
        join private.bpay_next_work_choice choice
          on choice.run_id=v_run_id and choice.work_id=rw.work_id
         and choice.selection_mode='ALL' and choice.selection_state='SEALED'
         and choice.expected_revision_id=rw.captured_revision_id
        join private.bpay_next_position p
          on p.work_id=rw.work_id
         and p.applied_revision_id=rw.captured_revision_id
        where rw.run_worker_id=v_worker.id
          and (v_work_cursor is null or rw.work_id>v_work_cursor
            or (rw.work_id=v_work_cursor and p.component_key>v_component_cursor))
        order by rw.work_id,p.component_key limit p_limit
    ), selected_page as materialized (
      select rw.id as run_work_id,rw.work_id,rw.captured_revision_id,
             member.component_key,'SUBSET'::text as selection_mode
        from private.bpay_next_selected_component member
        join private.bpay_next_run_work rw
          on rw.work_id=member.work_id
         and rw.captured_revision_id=member.expected_revision_id
        join private.bpay_next_work_choice choice
          on choice.run_id=member.run_id and choice.work_id=member.work_id
         and choice.selection_mode='SUBSET' and choice.selection_state='SEALED'
         and choice.expected_revision_id=rw.captured_revision_id
        where member.run_id=v_run_id and rw.run_worker_id=v_worker.id
          and (v_work_cursor is null or member.work_id>v_work_cursor
            or (member.work_id=v_work_cursor and member.component_key>v_component_cursor))
        order by member.work_id,member.component_key limit p_limit
    )
    select * from (
      select * from all_page union all select * from selected_page
    ) page order by work_id,component_key limit p_limit
  loop
    -- The Candidate control is already exclusively held. Lock this exact
    -- selected WORK before its position, matching the reentrant seed order.
    perform 1 from private.bpay_next_work w where w.id=v_member.work_id
      and w.candidate_id=v_worker.candidate_id for update;
    if not found then raise exception using errcode='23514',message='BPAY_NEXT_CAPTURE_POSITION_WORK_SCOPE_INVALID';end if;
    -- Read and lock the exact position after choosing the bounded member.
    -- Do not FOR SHARE the nullable side of an outer join (PostgreSQL refuses
    -- that), and never turn a missing selected position into an omitted line.
    select v_member.run_work_id as run_work_id,v_member.work_id as work_id,
           v_member.captured_revision_id as captured_revision_id,
           p.component_key,p.applied_revision_id,
           p.approved_source_ex_vat,p.realised_source_ex_vat,
           p.held_source_ex_vat,p.realised_target_ex_vat,
           p.realised_target_vat,p.realised_target_inc_vat,
           p.held_target_ex_vat,p.held_target_vat,
           p.held_target_inc_vat,p.source_basis_channel,
           rev.source_pay_channel,rev.source_kind,rev.source_event_id,
           rev.source_head_id,rev.financial_snapshot_id,
           rev.physical_timesheet_id,rev.physical_timesheet_version,
           w.work_kind,w.candidate_id as origin_candidate_id,
           l.component_kind,l.id as approved_line_id,
           l.source_pay_ex_vat as approved_line_source_ex_vat,l.tax_treatment,
           p.source_book_state,p.source_book_revision
      into v_row
      from private.bpay_next_position p
      join private.bpay_next_work_revision rev
        on rev.id=v_member.captured_revision_id and rev.work_id=v_member.work_id
      join private.bpay_next_work w on w.id=rev.work_id
      left join private.bpay_next_approved_line l
        on l.revision_id=v_member.captured_revision_id
       and l.component_key=v_member.component_key
      where p.work_id=v_member.work_id and p.component_key=v_member.component_key
      for update of p;
    v_issue:=null;
    if not found
       or v_row.applied_revision_id is distinct from v_member.captured_revision_id then
      v_issue:='CAPTURE_POSITION_CHANGED';
    elsif v_row.approved_line_id is null
       and v_row.approved_source_ex_vat<>0 then
      v_issue:='POSITION_COMPONENT_EVIDENCE_MISSING';
    elsif v_row.approved_line_id is not null
       and v_row.approved_line_source_ex_vat is distinct from
         v_row.approved_source_ex_vat then
      v_issue:='POSITION_APPROVAL_AMOUNT_MISMATCH';
    end if;
    if v_worker.target_pay_channel='UMBRELLA' and v_issue is null and
       (v_row.source_pay_channel is distinct from 'UMBRELLA'
        or v_row.work_kind not in ('ORDINARY','SOURCE')
        or v_row.component_kind is distinct from 'WORK'
        or v_row.tax_treatment is distinct from 'TAXABLE') then
      v_issue:='UMBRELLA_WORK_EXECUTION_UNSUPPORTED';
    end if;
    if v_issue is not null then
      update private.bpay_next_run_worker
        set status='REVIEW',review_issue_code=v_issue,
            review_issue_work_id=v_member.work_id
        where id=v_worker.id;
      update private.bpay_next_job
        set status='DONE',phase='DONE',cursor_key=null,
            lease_nonce=null,lease_until_utc=null
        where id=p_job_id;
      return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
        'issue_code',v_issue,'work_id',v_member.work_id,'replay',false);
    end if;
    -- Typed initial I-1 is the ONLY new no-HEAD binding arm. Initial and
    -- common-HEAD captures require self-canonical same-channel TAXABLE WORK.
    v_binding:=null;v_book:=null;
    if v_row.work_kind='SOURCE' and (v_row.source_head_id is not null
      or (v_row.source_kind='SOURCE' and v_row.source_event_id is not null
        and v_row.financial_snapshot_id is not null)) then
      select v.* into v_binding from private.bpay_next_source_component_binding b
        join private.bpay_next_source_component_binding_version v on v.id=b.current_binding_version_id
        where b.canonical_work_id=v_row.work_id and b.canonical_component_key=v_row.component_key
          and v.approval_work_id=v_row.work_id and v.approval_revision_id=v_row.captured_revision_id
          and v.approval_component_key=v_row.component_key
          and ((v_row.source_head_id is not null and v.origin_kind='COMMON_HEAD_RECEIPT_V1'
              and v.head_id=v_row.source_head_id)
            or (v_row.source_head_id is null and v.origin_kind='INITIAL_AUTHORISED_TSFIN_V1'
              and v.initial_root_authorisation_id=v_row.source_event_id
              and v.initial_financial_snapshot_id=v_row.financial_snapshot_id
              and v.initial_root_timesheet_id=v_row.physical_timesheet_id
              and v.initial_root_version=v_row.physical_timesheet_version));
      if v_binding.id is null or v_binding.publication_command_id_2 is not null
         or v_row.source_pay_channel not in ('PAYE','UMBRELLA')
         or v_worker.target_pay_channel is distinct from v_row.source_pay_channel
         or v_row.component_kind is distinct from 'WORK' or v_row.tax_treatment is distinct from 'TAXABLE' then
        v_issue:='SOURCE_BOOK_APPROVAL_UNBOUND';
      else
        if v_row.source_book_state='UNBOUND' then
          -- Capture is already a bounded selected point with real APPLIED/DONE
          -- authority. Adoption never borrows a queued writer's lease here.
          v_seed_effect:=null;v_seed_hold:=null;v_seed_holds:=null;
          if v_row.realised_source_ex_vat>0 then
            select b.original_effect_id into v_seed_effect from private.bpay_next_work_collection b
              where b.work_id=v_row.work_id and b.component_key=v_row.component_key
                and b.candidate_id=v_worker.candidate_id and b.paid_basis_qualified;
          end if;
          if v_row.held_source_ex_vat>0 then
            select pg_catalog.array_agg(h.id order by h.id) into v_seed_holds from (
              select id from private.bpay_next_hold where work_id=v_row.work_id
                and component_key=v_row.component_key and status='ACTIVE' order by id limit 2) h;
            if pg_catalog.cardinality(v_seed_holds) is distinct from 1 then
              raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_BOOK_ACTIVE_HOLD_WITNESS_AMBIGUOUS';
            end if;
            v_seed_hold:=v_seed_holds[1];
          end if;
          select seed.* into strict v_seed from private.bpay_next_source_disposition_seed_v1(
            v_row.work_id,v_row.component_key,v_row.captured_revision_id,v_seed_effect,v_seed_hold) seed;
          if v_seed.qualification_state is distinct from 'READY' then
            raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_BOOK_SELECTED_SEED_NOT_READY';
          end if;
          select p.source_book_state,p.source_book_revision into v_row.source_book_state,v_row.source_book_revision
            from private.bpay_next_position p where p.work_id=v_row.work_id and p.component_key=v_row.component_key;
        end if;
        select s.* into strict v_book from private.bpay_next_bound_source_snapshot_v1(
          v_binding.id,v_row.source_book_revision) s;
        if v_book.qualification_state is distinct from 'READY'
           or (v_book.candidate_id,v_book.canonical_work_id,v_book.canonical_component_key,
               v_book.approval_work_id,v_book.approval_revision_id,v_book.approved_line_id,
               v_book.source_channel,v_book.tax_treatment,v_book.approved_source_ex_vat,
               v_book.native_realised_paye,v_book.native_held_paye,v_book.native_realised_umbrella,v_book.native_held_umbrella)
             is distinct from (v_worker.candidate_id,v_row.work_id,v_row.component_key,
               v_row.work_id,v_row.captured_revision_id,v_row.approved_line_id,
               v_row.source_pay_channel,'TAXABLE'::text,v_row.approved_source_ex_vat,
               case when v_row.source_pay_channel='PAYE' then v_row.realised_source_ex_vat else 0::numeric end,
               case when v_row.source_pay_channel='PAYE' then v_row.held_source_ex_vat else 0::numeric end,
               case when v_row.source_pay_channel='UMBRELLA' then v_row.realised_source_ex_vat else 0::numeric end,
               case when v_row.source_pay_channel='UMBRELLA' then v_row.held_source_ex_vat else 0::numeric end) then
          v_issue:='SOURCE_BOOK_APPROVAL_UNBOUND';
        end if;
      end if;
      if v_issue is not null then
        update private.bpay_next_run_worker set status='REVIEW',review_issue_code=v_issue,
          review_issue_work_id=v_row.work_id where id=v_worker.id;
        update private.bpay_next_job set status='DONE',phase='DONE',cursor_key=null,
          lease_nonce=null,lease_until_utc=null where id=p_job_id;
        return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW','issue_code',v_issue,
          'work_id',v_row.work_id,'rows_visited',v_seen,'replay',false);
      end if;
    end if;
    v_collection:=null;
    -- Only the exact typed original ordinary PAYE liability can own a
    -- negative residual. Unknown signed/cross-basis/held shapes still REVIEW.
    if v_worker.target_pay_channel='PAYE' and v_row.source_pay_channel='PAYE'
       and v_row.approved_source_ex_vat-v_row.realised_source_ex_vat<0
       and (v_row.held_source_ex_vat,v_row.held_target_ex_vat,v_row.held_target_vat,v_row.held_target_inc_vat)
         is not distinct from (0::numeric,0::numeric,0::numeric,0::numeric) then
      select b.* into v_collection from private.bpay_next_work_collection b
        where b.work_id=v_row.work_id and b.component_key=v_row.component_key;
      if v_collection.case_id is not null then
        v_collection:=private.bpay_next_work_collection_origin_v1(
          v_collection.case_id,v_collection.case_component_id,v_worker.candidate_id);
      else v_collection:=null;end if;
      if v_collection.id is not null and
         (v_collection.observed_revision_id,v_collection.observed_approved_source_ex_vat,v_collection.observed_realised_source_ex_vat)
           is distinct from (v_row.captured_revision_id,v_row.approved_source_ex_vat,v_row.realised_source_ex_vat) then
        v_collection:=null;
      end if;
    end if;
    v_needs_resolution:=v_collection.id is null and (
       v_row.approved_line_id is null
       or v_row.approved_source_ex_vat<0
       or ((v_row.realised_source_ex_vat<>0
          or v_row.held_source_ex_vat<>0
          or v_row.realised_target_inc_vat<>0
          or v_row.held_target_inc_vat<>0)
         and v_row.source_basis_channel is distinct from v_row.source_pay_channel)
       or v_row.realised_source_ex_vat<0
       or v_row.realised_target_ex_vat<0 or v_row.realised_target_vat<0 or v_row.realised_target_inc_vat<0
       or (v_row.held_source_ex_vat>0 and v_row.approved_source_ex_vat-v_row.realised_source_ex_vat-v_row.held_source_ex_vat<=0)
       or (v_row.held_source_ex_vat=0 and v_row.held_target_inc_vat<>0)
       or v_row.approved_source_ex_vat-v_row.realised_source_ex_vat-v_row.held_source_ex_vat<0);
    -- Only genuine positive Source WORK consumes the retained disposition.
    -- Expense/additional/ordinary, zero, realised/held-away, managed negative
    -- and already-unresolved financial shapes do not become query holds.
    -- The actual pin validated the typed origin before this immutable row;
    -- missing evidence is REVIEW, never a lazy live Source reader fallback.
    if v_row.work_kind='SOURCE' and v_row.source_kind in ('SOURCE','PROTECTED')
       and v_row.source_event_id is not null
       and v_row.component_kind in ('WORK','PROTECTED_WORK')
       and not v_needs_resolution
       and v_row.approved_source_ex_vat-v_row.realised_source_ex_vat-v_row.held_source_ex_vat>0 then
      select qp.* into v_query_pin from private.bpay_next_run_work_query_pin_v2 qp
        where qp.run_work_id=v_row.run_work_id;
      if found and (v_query_pin.run_worker_id,v_query_pin.candidate_id,
          v_query_pin.work_id,v_query_pin.captured_revision_id,
          v_query_pin.prepare_job_id,v_query_pin.module_epoch,v_query_pin.gate_version)
          is distinct from (v_worker.id,v_worker.candidate_id,
          v_row.work_id,v_row.captured_revision_id,p_job_id,v_module_epoch,'PAY_QUERY_STATE_V3'::text) then
        raise exception using errcode='23514',message='BPAY_NEXT_CAPTURE_QUERY_PIN_MISMATCH';
      end if;
      if not found or v_query_pin.disposition='UNAVAILABLE' then
        v_issue:='SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE';
      elsif v_query_pin.disposition='BLOCKED' then
        v_issue:='SOURCE_PAY_QUERY_OPEN';
      elsif v_query_pin.disposition<>'CLEAR' or v_query_pin.scope is null
         or v_query_pin.query_state_sha256 is null
         or pg_catalog.octet_length(v_query_pin.query_state_sha256)<>32 then
        raise exception using errcode='23514',message='BPAY_NEXT_CAPTURE_QUERY_PIN_INVALID';
      end if;
      if v_issue is not null then
        update private.bpay_next_run_worker
          set status='REVIEW',review_issue_code=v_issue,review_issue_work_id=v_row.work_id
          where id=v_worker.id;
        update private.bpay_next_job
          set status='DONE',phase='DONE',cursor_key=null,
              lease_nonce=null,lease_until_utc=null
          where id=p_job_id;
        return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
          'issue_code',v_issue,'work_id',v_row.work_id,'rows_visited',v_seen,'replay',false);
      end if;
    end if;
    insert into private.bpay_next_run_position
      (run_worker_id,run_work_id,work_id,captured_revision_id,
       component_key,approved_line_id,source_pay_channel,
       source_basis_channel,
       approved_source_ex_vat,realised_source_ex_vat,held_source_ex_vat,
       residual_source_ex_vat,realised_target_ex_vat,realised_target_vat,
       realised_target_inc_vat,held_target_ex_vat,held_target_vat,
       held_target_inc_vat,needs_financial_resolution,work_collection_id,work_collection_revision,
       source_binding_version_id,canonical_source_work_id,canonical_source_component_key,source_book_revision)
      values(v_worker.id,v_row.run_work_id,v_row.work_id,
       v_row.captured_revision_id,v_row.component_key,v_row.approved_line_id,
       v_row.source_pay_channel,v_row.source_basis_channel,
       v_row.approved_source_ex_vat,
       v_row.realised_source_ex_vat,v_row.held_source_ex_vat,
       v_row.approved_source_ex_vat-v_row.realised_source_ex_vat
         -v_row.held_source_ex_vat,
       v_row.realised_target_ex_vat,v_row.realised_target_vat,
       v_row.realised_target_inc_vat,v_row.held_target_ex_vat,
       v_row.held_target_vat,v_row.held_target_inc_vat,
       v_needs_resolution,v_collection.id,v_collection.reconcile_revision,
       v_binding.id,v_binding.canonical_work_id,v_binding.canonical_component_key,
       case when v_binding.id is null then null else v_row.source_book_revision end);
    if v_needs_resolution then
      v_resolution_count:=v_resolution_count+1;
    end if;
    if v_collection.id is not null then v_managed_seen:=v_managed_seen+1;end if;
    v_work_cursor:=v_row.work_id;
    v_component_cursor:=v_row.component_key;
    v_seen:=v_seen+1;
    if v_member.selection_mode='SUBSET' then
      v_selected_seen:=v_selected_seen+1;
    end if;
  end loop;
  if v_resolution_count>0 then
    update private.bpay_next_run_worker
      set financial_resolution_count=financial_resolution_count+v_resolution_count
      where id=v_worker.id;
  end if;
  if v_seen>0 then
    update private.bpay_next_run_worker
      set captured_position_count=captured_position_count+v_seen,
          expected_managed_position_count=expected_managed_position_count+v_managed_seen,
          captured_selected_component_count=
            captured_selected_component_count+v_selected_seen
      where id=v_worker.id;
  end if;
  if v_seen<p_limit then
    if v_worker.captured_selected_component_count+v_selected_seen
       <>v_worker.expected_selected_component_count then
      select rw.work_id into strict v_issue_work_id
        from private.bpay_next_run_work rw
        join private.bpay_next_work_choice choice
          on choice.run_id=v_run_id and choice.work_id=rw.work_id
         and choice.selection_mode='SUBSET'
        where rw.run_worker_id=v_worker.id
        order by rw.work_id limit 1;
      update private.bpay_next_run_worker
        set status='REVIEW',review_issue_code='CAPTURE_POSITION_CHANGED',
            review_issue_work_id=v_issue_work_id
        where id=v_worker.id;
      update private.bpay_next_job
        set status='DONE',phase='DONE',cursor_key=null,
            lease_nonce=null,lease_until_utc=null
        where id=p_job_id;
      return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
        'issue_code','CAPTURE_POSITION_CHANGED','work_id',v_issue_work_id,'replay',false);
    end if;
    update private.bpay_next_job
      set phase='ALLOCATE',position_work_cursor=null,
          position_component_cursor=null
      where id=p_job_id;
    return pg_catalog.jsonb_build_object('done',true,'phase','ALLOCATE',
      'rows_visited',v_seen,'replay',false);
  end if;
  update private.bpay_next_job
    set position_work_cursor=v_work_cursor,
        position_component_cursor=v_component_cursor
    where id=p_job_id;
  return pg_catalog.jsonb_build_object('done',false,'phase','RESERVE',
    'rows_visited',v_seen,'work_cursor',v_work_cursor,
    'component_cursor',v_component_cursor,'replay',false);
end
$function$;

ALTER FUNCTION private.bpay_next_capture_position_page_v1(uuid,uuid,bigint,uuid,text,integer) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_capture_position_page_v1(uuid,uuid,bigint,uuid,text,integer) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D05 successor of supabase/repeatable/03102026_1620_banking_pay_next_fresh_positive_hold_v1.sql
create or replace function private.bpay_next_hold_fresh_position_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_work_cursor uuid,p_expected_component_cursor text,
  p_limit integer default 100
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_module_epoch bigint;
  v_issue_work_id uuid;
  v_row record;
  v_position private.bpay_next_position%rowtype;
  v_value record;v_book record;
  v_run_line_id uuid;
  v_seen integer:=0;
  v_work_cursor uuid;
  v_component_cursor text;
  v_line_count bigint;
  v_managed_count bigint;
  v_total_ex numeric(18,2);
  v_total_vat numeric(18,2);
  v_total_inc numeric(18,2);
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_limit not between 1 and 100
     or (p_expected_work_cursor is null and p_expected_component_cursor is not null) then
    raise exception using errcode='22023',message='BPAY_NEXT_HOLD_INPUT_INVALID';
  end if;
  select rc.run_id into strict v_run_id
    from private.bpay_next_job j
    join private.bpay_next_run_command rc on rc.command_id=j.command_id
    where j.id=p_job_id and j.job_kind='PREPARE';
  select m.owner_epoch into v_module_epoch
    from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_module_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for share;
  select candidate_id into strict v_job.candidate_id
    from private.bpay_next_job where id=p_job_id;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_job.candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED'
     or v_job.job_kind<>'PREPARE' or v_job.status<>'LEASED'
     or v_job.phase not in ('ALLOCATE','FINANCE_ALLOCATE')
     or v_job.module_epoch<>v_module_epoch
     or v_job.lease_nonce<>p_lease_nonce
     or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() then
    raise exception using errcode='55000',message='BPAY_NEXT_HOLD_LEASE_STALE';
  end if;
  if v_job.phase='FINANCE_ALLOCATE' then
    return pg_catalog.jsonb_build_object('done',true,
      'phase','FINANCE_ALLOCATE','rows_visited',0,'replay',true);
  end if;
  if v_job.position_work_cursor is distinct from p_expected_work_cursor
     or v_job.position_component_cursor is distinct from p_expected_component_cursor then
    return pg_catalog.jsonb_build_object('done',false,'phase','ALLOCATE',
      'rows_visited',0,'replay',true,
      'work_cursor',v_job.position_work_cursor,
      'component_cursor',v_job.position_component_cursor);
  end if;
  select * into strict v_worker from private.bpay_next_run_worker
    where run_id=v_run_id and candidate_id=v_job.candidate_id for update;
  if v_worker.status<>'PREPARING' or v_worker.review_issue_code is not null then
    raise exception using errcode='55000',
      message='BPAY_NEXT_HOLD_WORKER_NOT_PREPARING';
  end if;
  if v_worker.financial_resolution_count>0 then
    select rp.work_id into strict v_issue_work_id
      from private.bpay_next_run_position rp
      where rp.run_worker_id=v_worker.id and rp.needs_financial_resolution
      order by rp.work_id,rp.component_key limit 1;
    update private.bpay_next_run_worker
      set status='REVIEW',review_issue_code='FINANCIAL_RESOLUTION_REQUIRED',
          review_issue_work_id=v_issue_work_id
      where id=v_worker.id;
    update private.bpay_next_job
      set status='DONE',phase='DONE',cursor_key=null,
          lease_nonce=null,lease_until_utc=null
      where id=p_job_id;
    return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
      'issue_code','FINANCIAL_RESOLUTION_REQUIRED',
      'work_id',v_issue_work_id,'replay',false);
  end if;
  if v_worker.target_pay_channel='UMBRELLA'
     and (v_worker.target_umbrella_id is null
       or v_worker.target_umbrella_vat_chargeable is null) then
    select rp.work_id into v_issue_work_id
      from private.bpay_next_run_position rp
      where rp.run_worker_id=v_worker.id
      order by rp.work_id,rp.component_key limit 1;
    if v_issue_work_id is not null then
      update private.bpay_next_run_worker
        set status='REVIEW',review_issue_code='TARGET_UMBRELLA_MISSING',
            review_issue_work_id=v_issue_work_id
        where id=v_worker.id;
      update private.bpay_next_job
        set status='DONE',phase='DONE',cursor_key=null,
            lease_nonce=null,lease_until_utc=null
        where id=p_job_id;
      return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
        'issue_code','TARGET_UMBRELLA_MISSING',
        'work_id',v_issue_work_id,'replay',false);
    end if;
  end if;
  v_work_cursor:=v_job.position_work_cursor;
  v_component_cursor:=v_job.position_component_cursor;
  v_line_count:=v_worker.captured_line_count;
  v_managed_count:=v_worker.captured_managed_position_count;
  v_total_ex:=v_worker.gross_ex_vat;
  v_total_vat:=v_worker.gross_vat;
  v_total_inc:=v_worker.gross_inc_vat;
  for v_row in
    select rp.*,rw.id as pinned_work_id,rev.valuation_policy_id
      from private.bpay_next_run_position rp
      join private.bpay_next_run_work rw on rw.id=rp.run_work_id
      join private.bpay_next_work_revision rev
        on rev.id=rp.captured_revision_id and rev.work_id=rp.work_id
      where rp.run_worker_id=v_worker.id
        and (v_work_cursor is null or rp.work_id>v_work_cursor
          or (rp.work_id=v_work_cursor
            and rp.component_key>v_component_cursor))
      order by rp.work_id,rp.component_key limit p_limit
  loop
    if v_row.needs_financial_resolution
       or (v_row.work_collection_id is null and
         (v_row.approved_line_id is null or v_row.residual_source_ex_vat<0)) then
      raise exception using errcode='23514',
        message='BPAY_NEXT_HOLD_UNEXPECTED_POSITION_SHAPE';
    end if;
    select * into strict v_position from private.bpay_next_position
      where work_id=v_row.work_id and component_key=v_row.component_key
      for update;
    if v_position.applied_revision_id is distinct from v_row.captured_revision_id
       or v_position.approved_source_ex_vat is distinct from
         v_row.approved_source_ex_vat
       or v_position.realised_source_ex_vat is distinct from
         v_row.realised_source_ex_vat
       or v_position.held_source_ex_vat is distinct from
         v_row.held_source_ex_vat
       or v_position.source_basis_channel is distinct from
         v_row.source_basis_channel
       or v_position.realised_target_ex_vat is distinct from
         v_row.realised_target_ex_vat
       or v_position.realised_target_vat is distinct from
         v_row.realised_target_vat
       or v_position.realised_target_inc_vat is distinct from
         v_row.realised_target_inc_vat
       or v_position.held_target_ex_vat is distinct from
         v_row.held_target_ex_vat
       or v_position.held_target_vat is distinct from
         v_row.held_target_vat
       or v_position.held_target_inc_vat is distinct from
         v_row.held_target_inc_vat then
      raise exception using errcode='55000',
        message='BPAY_NEXT_HOLD_CURRENT_POSITION_CHANGED';
    end if;
    if v_row.source_binding_version_id is not null then
      select s.* into strict v_book from private.bpay_next_bound_source_snapshot_v1(
        v_row.source_binding_version_id,v_row.source_book_revision) s;
      if v_book.qualification_state is distinct from 'READY'
         or (v_book.canonical_work_id,v_book.canonical_component_key,v_book.approval_work_id,
             v_book.approval_revision_id,v_book.approved_line_id,v_book.source_channel,v_book.tax_treatment,
             v_book.approved_source_ex_vat,v_book.native_realised_paye,v_book.native_held_paye,
             v_book.native_realised_umbrella,v_book.native_held_umbrella)
           is distinct from (v_row.work_id,v_row.component_key,v_row.work_id,
             v_row.captured_revision_id,v_row.approved_line_id,v_row.source_pay_channel,'TAXABLE'::text,
             v_row.approved_source_ex_vat,
             case when v_row.source_pay_channel='PAYE' then v_row.realised_source_ex_vat else 0::numeric end,
             case when v_row.source_pay_channel='PAYE' then v_row.held_source_ex_vat else 0::numeric end,
             case when v_row.source_pay_channel='UMBRELLA' then v_row.realised_source_ex_vat else 0::numeric end,
             case when v_row.source_pay_channel='UMBRELLA' then v_row.held_source_ex_vat else 0::numeric end)
         or v_row.source_pay_channel not in ('PAYE','UMBRELLA')
         or v_worker.target_pay_channel is distinct from v_row.source_pay_channel
         or v_row.canonical_source_work_id is distinct from v_row.work_id
         or v_row.canonical_source_component_key is distinct from v_row.component_key then
        raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_BOOK_CAPTURE_CHANGED';
      end if;
    end if;
    if v_row.work_collection_id is not null then
      -- Classification and original provenance were frozen by RESERVE. Never
      -- reread a newer WORK approval or create an ordinary negative/zero hold.
      update private.bpay_next_run_position set managed_capture_completed=true
        where id=v_row.id and not managed_capture_completed;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_CAPTURE_ALREADY_SPENT';end if;
      v_managed_count:=v_managed_count+1;
    else
    select * into strict v_value
      from private.bpay_next_value_source_for_target_v1(
        v_row.residual_source_ex_vat,v_row.source_pay_channel,
        v_worker.target_pay_channel,
        case when v_worker.target_pay_channel='UMBRELLA'
          then v_worker.target_umbrella_vat_chargeable else false end,
        v_row.valuation_policy_id,v_run.pay_date);
    v_line_count:=v_line_count+1;
    insert into private.bpay_next_run_line
      (run_worker_id,run_work_id,line_no,approved_line_id,
       captured_revision_id,work_id,component_key,source_consumed_ex_vat,
       source_pay_channel,target_pay_channel,valuation_policy_id,
       policy_window_id,frozen_ex_vat,frozen_vat,frozen_inc_vat,source_binding_version_id,
       canonical_source_work_id,canonical_source_component_key,source_book_revision,updates_original_source_scalar)
      values(v_worker.id,v_row.run_work_id,v_line_count,
       v_row.approved_line_id,v_row.captured_revision_id,v_row.work_id,
       v_row.component_key,v_row.residual_source_ex_vat,
       v_row.source_pay_channel,v_worker.target_pay_channel,
       v_row.valuation_policy_id,v_value.policy_window_id,
       v_value.target_ex_vat,v_value.target_vat,v_value.target_inc_vat,
       v_row.source_binding_version_id,v_row.canonical_source_work_id,v_row.canonical_source_component_key,
       v_row.source_book_revision,case when v_row.source_binding_version_id is null then null else true end)
      returning id into v_run_line_id;
    -- An authorised zero still has immutable shift/rate advice detail. It
    -- becomes a frozen zero line, never a zero-valued financial hold.
    if v_row.residual_source_ex_vat>0 then
      insert into private.bpay_next_hold
        (run_line_id,work_id,component_key,source_reserved_ex_vat,
         target_amount_ex_vat,target_amount_vat,target_amount_inc_vat,status)
        values(v_run_line_id,v_row.work_id,v_row.component_key,
         v_row.residual_source_ex_vat,v_value.target_ex_vat,
         v_value.target_vat,v_value.target_inc_vat,'ACTIVE');
      update private.bpay_next_position
        set held_source_ex_vat=held_source_ex_vat+v_row.residual_source_ex_vat,
            held_target_ex_vat=held_target_ex_vat+v_value.target_ex_vat,
            held_target_vat=held_target_vat+v_value.target_vat,
            held_target_inc_vat=held_target_inc_vat+v_value.target_inc_vat,
            updated_at_utc=pg_catalog.transaction_timestamp()
        where work_id=v_row.work_id and component_key=v_row.component_key;
    end if;
    v_total_ex:=v_total_ex+v_value.target_ex_vat;
    v_total_vat:=v_total_vat+v_value.target_vat;
    v_total_inc:=v_total_inc+v_value.target_inc_vat;
    end if;
    v_work_cursor:=v_row.work_id;
    v_component_cursor:=v_row.component_key;
    v_seen:=v_seen+1;
  end loop;
  if v_seen>0 then
    update private.bpay_next_run_worker
      set captured_line_count=v_line_count,
          captured_managed_position_count=v_managed_count,
          gross_ex_vat=v_total_ex,gross_vat=v_total_vat,
          gross_inc_vat=v_total_inc
      where id=v_worker.id;
    update private.bpay_next_worker_control
      set financial_view_revision=financial_view_revision+1,
          updated_at_utc=pg_catalog.transaction_timestamp()
      where candidate_id=v_job.candidate_id;
  end if;
  if v_seen<p_limit then
    if v_managed_count<>v_worker.expected_managed_position_count or exists(
      select 1 from private.bpay_next_run_position where run_worker_id=v_worker.id
        and work_collection_id is not null and not managed_capture_completed) then
      raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_CAPTURE_COUNT_MISMATCH';
    end if;
    update private.bpay_next_job
      set phase='FINANCE_ALLOCATE',position_work_cursor=null,
          position_component_cursor=null
      where id=p_job_id;
    return pg_catalog.jsonb_build_object('done',true,
      'phase','FINANCE_ALLOCATE','rows_visited',v_seen,'replay',false);
  end if;
  update private.bpay_next_job
    set position_work_cursor=v_work_cursor,
        position_component_cursor=v_component_cursor
    where id=p_job_id;
  return pg_catalog.jsonb_build_object('done',false,'phase','ALLOCATE',
    'rows_visited',v_seen,'work_cursor',v_work_cursor,
    'component_cursor',v_component_cursor,'replay',false);
end
$function$;

ALTER FUNCTION private.bpay_next_hold_fresh_position_page_v1(uuid,uuid,bigint,uuid,text,integer) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_hold_fresh_position_page_v1(uuid,uuid,bigint,uuid,text,integer) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D04 successor of supabase/repeatable/03102026_2359_banking_pay_next_simple_review_confirm_v1.sql
create or replace function private.bpay_next_confirm_simple_run_v1(
  p_run_id uuid,p_review_revision bigint
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run private.bpay_next_pay_run%rowtype;
  v_module_epoch bigint;
  v_command private.bpay_next_command%rowtype;
begin
  if p_run_id is null or p_review_revision is null then
    raise exception using errcode='22023',
      message='BPAY_NEXT_CONFIRM_INPUT_INVALID';
  end if;
  select owner_epoch into v_module_epoch
    from private.bpay_next_module_control
    where id=1 and active_owner='NEXT' for share;
  if v_module_epoch is null then
    raise exception using errcode='55000',
      message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=p_run_id for update;
  if v_run.status='DRAFT' and v_run.review_revision=p_review_revision
     and v_run.confirmed_at_utc is not null then
    return pg_catalog.jsonb_build_object('phase','DRAFT','replay',true,
      'review_revision',v_run.review_revision,
      'drafts',private.bpay_next_channel_drafts_page_v1(p_run_id)->'rows');
  end if;
  if v_run.status<>'REVIEW' or v_run.selection_state<>'SEALED'
     or v_run.work_choice_count<>v_run.selection_count
     or v_run.sealed_work_choice_count<>v_run.selection_count
     or v_run.review_revision<>p_review_revision
     or v_run.confirmed_at_utc is not null then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CONFIRM_REVIEW_STATE_INVALID';
  end if;
  -- The real clock is read AFTER the header lock: a transaction started
  -- before the deadline cannot confirm late after waiting for that lock.
  -- The completed DRAFT replay above is permanent and never expires.
  if v_run.preparation_expires_at_utc is null
     or v_run.preparation_expires_at_utc<=pg_catalog.clock_timestamp() then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CONFIRM_PREPARATION_EXPIRED_OR_UNBOUND';
  end if;
  select c.* into strict v_command
    from private.bpay_next_run_command rc
    join private.bpay_next_command c on c.id=rc.command_id
    where rc.run_id=p_run_id;
  if v_command.status<>'SEALED' or v_command.module_epoch<>v_module_epoch
     or v_command.expected_member_count<>v_run.selected_candidate_count
     or v_command.enrolled_member_count<>v_run.selected_candidate_count
     or exists (select 1 from private.bpay_next_job j
        where j.command_id=v_command.id and j.job_kind='PREPARE'
          and j.status<>'DONE')
     or exists (
       select 1 from private.bpay_next_run_worker
       where run_id=p_run_id and status<>'READY') then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CONFIRM_UNRESOLVED_WORKER';
  end if;
  -- Each bounded holder transaction wrote its line, position and ACTIVE hold
  -- atomically before its worker became READY. Future cancellation/expiry
  -- owners must lock this parent and make a worker non-ready before release;
  -- no such owner is granted or activated in this narrow proof.
  update private.bpay_next_pay_run
    set status='DRAFT',confirmed_at_utc=pg_catalog.transaction_timestamp()
    where id=p_run_id;
  return pg_catalog.jsonb_build_object('phase','DRAFT','replay',false,
    'review_revision',p_review_revision,
    'drafts',private.bpay_next_channel_drafts_page_v1(p_run_id)->'rows');
end
$function$;

ALTER FUNCTION private.bpay_next_confirm_simple_run_v1(uuid,bigint) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_confirm_simple_run_v1(uuid,bigint) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D07 successor of supabase/repeatable/04102026_0120_banking_pay_next_simple_transfer_begin_v1.sql
create or replace function private.bpay_next_begin_simple_transfer_v1(
  p_command_id uuid,p_run_worker_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_sequence bigint;
  v_candidate_id uuid;
  v_case_selection_revision bigint;
begin
  if p_command_id is null or p_run_worker_id is null then
    raise exception using errcode='22023',
      message='BPAY_NEXT_TRANSFER_BEGIN_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control m
                where m.id=1 and m.active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select run_id,candidate_id,case_selection_revision
    into strict v_run_id,v_candidate_id,v_case_selection_revision from private.bpay_next_run_worker
    where id=p_run_worker_id;
  if v_case_selection_revision>0 then
    return private.bpay_next_begin_case_transfer_v1(p_command_id,p_run_worker_id);
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for update;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate_id for update;
  select * into strict v_worker from private.bpay_next_run_worker
    where id=p_run_worker_id for update;
  select * into v_transfer from private.bpay_next_transfer
    where build_command_id=p_command_id;
  if found then
    if v_transfer.run_worker_id<>p_run_worker_id
       or v_transfer.candidate_id<>v_worker.candidate_id then
      raise exception using errcode='23514',
        message='BPAY_NEXT_TRANSFER_BEGIN_REPLAY_CONFLICT';
    end if;
    select agency_sequence into strict v_sequence
      from private.bpay_next_command
      where id=p_command_id and command_kind='TRANSFER_BUILD';
    return pg_catalog.jsonb_build_object('sequence',v_sequence,
      'transfer_id',v_transfer.id,'phase',v_transfer.status,'replay',true);
  end if;
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null
     or exists(select 1 from private.bpay_next_cancel_request r
               where r.run_worker_id=v_worker.id and r.status in ('REQUESTED','CANCELLING'))
     or v_worker.status<>'READY'
     or v_worker.target_pay_channel not in ('PAYE','UMBRELLA')
     or (v_worker.target_pay_channel='PAYE' and
         (v_worker.net_projection_revision<>1 or v_worker.net_request_revision<>1))
     or (v_worker.target_pay_channel='UMBRELLA' and
         (v_worker.net_projection_revision<>0 or v_worker.net_request_revision<>0
          or v_worker.entered_paye_net is not null
          or v_worker.target_umbrella_id is null or v_worker.target_umbrella_vat_chargeable is null
          or v_worker.gross_inc_vat<=0 or v_worker.captured_line_count<1
          or v_worker.financial_resolution_count<>0 or v_worker.expected_managed_position_count<>0
          or exists(select 1 from private.bpay_next_paye_net_request where run_worker_id=v_worker.id)))
     or v_worker.case_selection_revision<>0
     or exists(select 1 from private.bpay_next_transfer t
               where t.run_worker_id=v_worker.id) then
    raise exception using errcode='55000',
      message='BPAY_NEXT_SIMPLE_TRANSFER_NOT_ELIGIBLE';
  end if;
  if v_worker.target_pay_channel='UMBRELLA' then
    -- No payroll NET request/value, CASE adjustment or live financial lookup.
    -- Bounded member pages must certify every included line as same-channel
    -- TAXABLE WORK before the transfer can become issuable.
    insert into private.bpay_next_net_projection
      (run_worker_id,request_command_id,projection_no,input_kind,
       gross_ex_vat,gross_vat,gross_inc_vat,entered_paye_net,accepted_recoveries,cash_amount)
      values(v_worker.id,null,1,'UMBRELLA',v_worker.gross_ex_vat,v_worker.gross_vat,
        v_worker.gross_inc_vat,null,0,v_worker.gross_inc_vat);
    update private.bpay_next_run_worker set net_projection_revision=1 where id=v_worker.id;
  end if;
  select * into strict v_projection from private.bpay_next_net_projection
    where run_worker_id=v_worker.id and projection_no=1;
  if v_worker.target_pay_channel='PAYE' and (v_projection.input_kind<>'PAYE_MANUAL'
     or v_projection.gross_ex_vat<>v_worker.gross_ex_vat
     or v_projection.gross_vat<>0
     or v_projection.gross_inc_vat<>v_worker.gross_inc_vat
     or v_projection.entered_paye_net is distinct from
        v_worker.entered_paye_net
     or v_projection.accepted_recoveries<>0
     or v_projection.cash_amount<0
     or v_projection.cash_amount<>v_worker.entered_paye_net
     or v_projection.request_command_id is null) then
    raise exception using errcode='23514',
      message='BPAY_NEXT_SIMPLE_TRANSFER_PROJECTION_INVALID';
  end if;
  if v_worker.target_pay_channel='UMBRELLA' and
     ((v_projection.input_kind,v_projection.gross_ex_vat,v_projection.gross_vat,
       v_projection.gross_inc_vat,v_projection.cash_amount,v_projection.accepted_recoveries,
       v_projection.accepted_gross_additions,v_projection.accepted_gross_deductions,v_projection.accepted_net_additions)
       is distinct from ('UMBRELLA'::text,v_worker.gross_ex_vat,v_worker.gross_vat,
         v_worker.gross_inc_vat,v_worker.gross_inc_vat,0::numeric,0::numeric,0::numeric,0::numeric)
      or v_projection.entered_paye_net is not null or v_projection.request_command_id is not null) then
    raise exception using errcode='23514',message='BPAY_NEXT_SIMPLE_TRANSFER_PROJECTION_INVALID';
  end if;
  v_sequence:=private.bpay_next_receive_command_v1(
    p_command_id,'TRANSFER_BUILD');
  insert into private.bpay_next_command_member
    (command_id,candidate_id,member_no)
    values(p_command_id,v_worker.candidate_id,1);
  insert into private.bpay_next_transfer
    (run_worker_id,candidate_id,projection_id,build_command_id,
     transfer_no,beneficiary_kind,beneficiary_id,cash_amount,status,execution_kind)
    values(v_worker.id,v_worker.candidate_id,v_projection.id,p_command_id,
      1,case when v_worker.target_pay_channel='UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end,
      case when v_worker.target_pay_channel='UMBRELLA' then v_worker.target_umbrella_id else v_worker.candidate_id end,
      v_projection.cash_amount,'BUILDING',
      case when v_projection.cash_amount=0 then 'INTERNAL_ZERO' else 'BANK' end)
    returning * into v_transfer;
  update private.bpay_next_command
    set expected_member_count=1,status='SEALED',
        sealed_at_utc=pg_catalog.transaction_timestamp()
    where id=p_command_id;
  return pg_catalog.jsonb_build_object('sequence',v_sequence,
    'transfer_id',v_transfer.id,'phase','BUILDING','replay',false);
end
$function$;

ALTER FUNCTION private.bpay_next_begin_simple_transfer_v1(uuid,uuid) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_begin_simple_transfer_v1(uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D16 successor of supabase/repeatable/04102026_0130_banking_pay_next_simple_transfer_members_v1.sql
create or replace function private.bpay_next_build_simple_transfer_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_cursor bigint,p_limit integer
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_candidate_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_line record;
  v_seen integer:=0;
  v_member_count bigint;
  v_cash_sum numeric(18,2);
  v_cursor bigint;
  v_adjustment numeric(18,2);
  v_epoch bigint;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_limit is null or p_limit not between 1 and 100
     or p_expected_cursor is not null and p_expected_cursor<1 then
    raise exception using errcode='22023',
      message='BPAY_NEXT_TRANSFER_PAGE_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id,w.candidate_id into strict v_run_id,v_candidate_id
    from private.bpay_next_job j
    join private.bpay_next_transfer t on t.build_command_id=j.command_id
    join private.bpay_next_run_worker w on w.id=t.run_worker_id
    where j.id=p_job_id and j.candidate_id=w.candidate_id;
  if exists(select 1 from private.bpay_next_destination_group b
     join private.bpay_next_transfer t on t.id=b.anchor_transfer_id
     join private.bpay_next_job j on j.command_id=t.build_command_id where j.id=p_job_id) then
    return private.bpay_next_build_destination_group_page_v1(
      p_job_id,p_lease_nonce,p_owner_epoch,p_expected_cursor,p_limit);
  end if;
  if exists(select 1 from private.bpay_next_case_transfer_build b
     join private.bpay_next_transfer t on t.id=b.transfer_id
     join private.bpay_next_job j on j.command_id=t.build_command_id
     where j.id=p_job_id) then
    return private.bpay_next_build_case_transfer_page_v1(
      p_job_id,p_lease_nonce,p_owner_epoch,p_expected_cursor,p_limit);
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for update;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  select * into strict v_transfer from private.bpay_next_transfer
    where build_command_id=v_job.command_id for update;
  select * into strict v_worker from private.bpay_next_run_worker
    where id=v_transfer.run_worker_id for update;
  select * into strict v_projection from private.bpay_next_net_projection
    where id=v_transfer.projection_id;
  if v_job.job_kind<>'TRANSFER_BUILD'
     or v_job.module_epoch<>v_epoch
     or v_job.candidate_id<>v_worker.candidate_id
     or v_transfer.candidate_id<>v_worker.candidate_id
     or not ((v_worker.target_pay_channel='PAYE' and
          v_transfer.beneficiary_kind='CANDIDATE' and v_transfer.beneficiary_id=v_worker.candidate_id)
       or (v_worker.target_pay_channel='UMBRELLA' and v_worker.target_umbrella_id is not null and
          v_transfer.beneficiary_kind='UMBRELLA' and v_transfer.beneficiary_id=v_worker.target_umbrella_id))
     or v_run.id<>v_worker.run_id
     or v_projection.run_worker_id<>v_worker.id then
    raise exception using errcode='23514',
      message='BPAY_NEXT_TRANSFER_JOB_SCOPE_INVALID';
  end if;
  if v_job.status='DONE' and v_job.phase='MEMBERS_READY'
     and v_transfer.status<>'BUILDING' then
    return pg_catalog.jsonb_build_object('phase','MEMBERS_READY',
      'transfer_status',v_transfer.status,
      'transfer_id',v_transfer.id,'cursor',v_job.cursor_key,
      'member_count',v_transfer.member_count,'replay',true);
  end if;
  if v_job.status<>'LEASED' or v_job.phase<>'WORK'
     or v_job.lease_nonce<>p_lease_nonce
     or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null
     or v_worker.status<>'READY'
     or v_worker.net_projection_revision<>1
     or v_projection.projection_no<>1
     or v_projection.cash_amount<>v_transfer.cash_amount
     or v_transfer.status<>'BUILDING'
     or v_transfer.account_approval_ref is not null
     or v_transfer.original_transfer_id is not null
     or v_transfer.member_count>v_worker.captured_line_count then
    raise exception using errcode='55000',
      message='BPAY_NEXT_TRANSFER_BUILD_NOT_ELIGIBLE';
  end if;
  if v_job.cursor_key is distinct from p_expected_cursor::text then
    return pg_catalog.jsonb_build_object('phase','BUILDING',
      'transfer_id',v_transfer.id,'cursor',v_job.cursor_key,
      'member_count',v_transfer.member_count,'replay',true);
  end if;
  v_member_count:=v_transfer.member_count;
  v_cash_sum:=v_transfer.member_cash_sum;
  v_cursor:=p_expected_cursor;
  for v_line in
    select l.id,l.line_no,l.frozen_inc_vat,l.frozen_ex_vat,l.source_consumed_ex_vat,
      l.source_pay_channel,l.target_pay_channel,l.component_key,l.work_id,
      a.id as qualified_line_id,a.component_kind,a.tax_treatment,
      r.id as qualified_revision_id
    from private.bpay_next_run_line l
    left join private.bpay_next_approved_line a on a.id=l.approved_line_id
      and a.revision_id=l.captured_revision_id and a.component_key=l.component_key
    left join private.bpay_next_work_revision r on r.id=l.captured_revision_id and r.work_id=l.work_id
    where l.run_worker_id=v_worker.id
      and (v_cursor is null or l.line_no>v_cursor)
    order by l.line_no,l.id limit p_limit
  loop
    if v_worker.target_pay_channel='UMBRELLA' and
       (v_projection.input_kind is distinct from 'UMBRELLA'
        or v_worker.case_selection_revision<>0 or v_worker.net_request_revision<>0
        or v_projection.entered_paye_net is not null or v_projection.request_command_id is not null
        or v_projection.cash_amount is distinct from v_worker.gross_inc_vat
        or v_line.qualified_line_id is null or v_line.qualified_revision_id is null
        or v_line.component_kind is distinct from 'WORK' or v_line.tax_treatment is distinct from 'TAXABLE'
        or v_line.source_pay_channel is distinct from 'UMBRELLA'
        or v_line.target_pay_channel is distinct from 'UMBRELLA'
        or v_line.source_consumed_ex_vat<0
        or v_line.frozen_ex_vat is distinct from v_line.source_consumed_ex_vat) then
      raise exception using errcode='55000',message='BPAY_NEXT_UMBRELLA_WORK_EXECUTION_UNSUPPORTED';
    end if;
    v_seen:=v_seen+1;
    v_member_count:=v_member_count+1;
    v_cash_sum:=v_cash_sum+v_line.frozen_inc_vat;
    insert into private.bpay_next_transfer_member
      (transfer_id,run_worker_id,member_no,subject_kind,
       run_line_id,signed_cash_contribution)
      values(v_transfer.id,v_worker.id,v_member_count,'WORK',
             v_line.id,v_line.frozen_inc_vat);
    v_cursor:=v_line.line_no;
  end loop;
  if v_member_count>v_worker.captured_line_count then
    raise exception using errcode='23514',
      message='BPAY_NEXT_TRANSFER_LINE_COUNT_EXCEEDED';
  end if;
  if v_member_count=v_worker.captured_line_count then
    if exists(select 1 from private.bpay_next_run_line l
              where l.run_worker_id=v_worker.id
                and (v_cursor is null or l.line_no>v_cursor))
       or v_cash_sum<>v_worker.gross_inc_vat then
      raise exception using errcode='23514',
        message='BPAY_NEXT_TRANSFER_FROZEN_GROSS_MISMATCH';
    end if;
    if v_worker.target_pay_channel='PAYE' then
      v_adjustment:=v_projection.cash_amount-v_worker.gross_inc_vat;
      insert into private.bpay_next_transfer_member
        (transfer_id,run_worker_id,member_no,subject_kind,
         signed_cash_contribution)
        values(v_transfer.id,v_worker.id,v_member_count+1,
               'NET_ADJUSTMENT',v_adjustment);
      v_member_count:=v_member_count+1;
      v_cash_sum:=v_cash_sum+v_adjustment;
    end if;
    if v_cash_sum<>v_projection.cash_amount then
      raise exception using errcode='23514',
        message='BPAY_NEXT_TRANSFER_CASH_MISMATCH';
    end if;
    update private.bpay_next_transfer
      set member_count=v_member_count,member_cash_sum=v_cash_sum,
          status='MEMBERS_READY'
      where id=v_transfer.id;
    update private.bpay_next_job
      set status='DONE',phase='MEMBERS_READY',
          cursor_key=v_cursor::text,
          lease_nonce=null,lease_until_utc=null
      where id=p_job_id;
    update private.bpay_next_command set status='COMPLETE'
      where id=v_job.command_id;
    return pg_catalog.jsonb_build_object('phase','MEMBERS_READY',
      'transfer_id',v_transfer.id,'cursor',v_cursor,
      'member_count',v_member_count,'rows_visited',v_seen,'replay',false);
  end if;
  if v_seen=0 then
    raise exception using errcode='23514',
      message='BPAY_NEXT_TRANSFER_FROZEN_LINE_MISSING';
  end if;
  update private.bpay_next_transfer
    set member_count=v_member_count,member_cash_sum=v_cash_sum
    where id=v_transfer.id;
  update private.bpay_next_job set cursor_key=v_cursor::text
    where id=p_job_id;
  return pg_catalog.jsonb_build_object('phase','BUILDING',
    'transfer_id',v_transfer.id,'cursor',v_cursor,
    'member_count',v_member_count,'rows_visited',v_seen,'replay',false);
end
$function$;

ALTER FUNCTION private.bpay_next_build_simple_transfer_page_v1(uuid,uuid,bigint,bigint,integer) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_build_simple_transfer_page_v1(uuid,uuid,bigint,bigint,integer) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D15 successor of supabase/repeatable/04102026_0140_banking_pay_next_simple_csv_destination_v1.sql
create or replace function private.bpay_next_bind_simple_csv_destination_v1(
  p_transfer_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_candidate public.candidates%rowtype;
  v_umbrella public.umbrellas%rowtype;
  v_leg private.bpay_next_destination_group_leg%rowtype;
  v_origin private.bpay_next_stored_credit_origin%rowtype;
  v_name text;
  v_sort text;
  v_account text;
  v_hash text;
  v_replay boolean;
begin
  if p_transfer_id is null then
    raise exception using errcode='22023',
      message='BPAY_NEXT_CSV_DESTINATION_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control m
                where m.id=1 and m.active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id into strict v_run_id
    from private.bpay_next_transfer t
    join private.bpay_next_run_worker w on w.id=t.run_worker_id
    where t.id=p_transfer_id;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w
    join private.bpay_next_transfer t on t.run_worker_id=w.id
    where t.id=p_transfer_id for update of w;
  select * into strict v_transfer from private.bpay_next_transfer
    where id=p_transfer_id for update;
  v_leg:=private.bpay_next_destination_execution_leg_v1(p_transfer_id);
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null
     or exists(select 1 from private.bpay_next_cancel_request r
               where r.run_worker_id=v_worker.id and r.status in ('REQUESTED','CANCELLING'))
     or (v_worker.status<>'READY' and not (v_worker.status='COMPLETE'
       and v_leg.transfer_id is not null and v_transfer.original_transfer_id is not null))
     or v_worker.target_pay_channel not in ('PAYE','UMBRELLA')
     or v_transfer.status<>'MEMBERS_READY'
     or v_transfer.candidate_id<>v_worker.candidate_id
     or not ((v_worker.target_pay_channel='PAYE' and
          v_transfer.beneficiary_kind='CANDIDATE' and v_transfer.beneficiary_id=v_worker.candidate_id)
       or (v_worker.target_pay_channel='UMBRELLA' and v_worker.target_umbrella_id is not null and
          v_transfer.beneficiary_kind='UMBRELLA' and v_transfer.beneficiary_id=v_worker.target_umbrella_id))
     or (v_transfer.projection_id is null and v_transfer.return_cash_id is null)
     or v_transfer.cash_amount<=0
     or v_transfer.member_count<=0
     or v_transfer.member_cash_sum<>v_transfer.cash_amount
     or (not exists(select 1 from private.bpay_next_command c
                   where c.id=v_transfer.build_command_id
                     and c.command_kind in ('TRANSFER_BUILD','CASH_REISSUE')
                     and c.status='COMPLETE')
       and not (v_leg.transfer_id is not null and v_transfer.original_transfer_id is null)) then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_DESTINATION_NOT_ELIGIBLE';
  end if;
  select * into strict v_candidate from public.candidates
    where id=v_worker.candidate_id;
  v_name:=nullif(pg_catalog.btrim(v_candidate.account_holder),'');
  v_sort:=pg_catalog.regexp_replace(
    coalesce(v_candidate.sort_code,''),'[^0-9]','','g');
  v_account:=pg_catalog.regexp_replace(
    coalesce(v_candidate.account_number,''),'[^0-9]','','g');
  v_hash:=public._bank_hash(v_candidate.sort_code,
    v_candidate.account_number,v_candidate.account_holder);
  if v_worker.target_pay_channel='UMBRELLA' then
    if v_leg.transfer_id is not null or v_worker.case_selection_revision<>0
       or v_candidate.active is not true
       or pg_catalog.upper(coalesce(v_candidate.pay_method,''))<>'UMBRELLA'
       or v_candidate.umbrella_id is distinct from v_worker.target_umbrella_id then
      raise exception using errcode='55000',message='BPAY_NEXT_CSV_UMBRELLA_DESTINATION_NOT_READY';
    end if;
    select * into strict v_umbrella from public.umbrellas where id=v_worker.target_umbrella_id for share;
    v_name:=nullif(pg_catalog.btrim(v_umbrella.name),'');
    v_sort:=pg_catalog.regexp_replace(coalesce(v_umbrella.sort_code,''),'[^0-9]','','g');
    v_account:=pg_catalog.regexp_replace(coalesce(v_umbrella.account_number,''),'[^0-9]','','g');
    v_hash:=public._bank_hash(v_umbrella.sort_code,v_umbrella.account_number,v_umbrella.name);
    if v_umbrella.enabled is not true or v_hash is distinct from v_umbrella.bank_details_hash then
      raise exception using errcode='55000',message='BPAY_NEXT_CSV_UMBRELLA_DESTINATION_NOT_READY';
    end if;
  end if;
  if v_leg.leg_kind='ONEOFF' then
    select o.* into strict v_origin from private.bpay_next_net_destination_amount d
      join private.bpay_next_stored_credit_origin o on o.command_id=d.first_origin_command_id
      where d.destination_id=v_leg.destination_id;
    v_name:=nullif(pg_catalog.btrim(v_origin.beneficiary_name),'');
    v_sort:=v_origin.sort_code;v_account:=v_origin.account_number;v_hash:=v_origin.bank_details_hash;
  end if;
  if v_candidate.active is not true
     or pg_catalog.upper(coalesce(v_candidate.pay_method,''))<>v_worker.target_pay_channel
     or v_name is null
     or v_sort !~ '^[0-9]{6}$'
     or v_account !~ '^[0-9]{8}$'
     or v_hash is null
     or (v_worker.target_pay_channel='PAYE' and
         v_leg.leg_kind is distinct from 'ONEOFF' and v_hash is distinct from v_candidate.bank_details_hash) then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_BANK_DETAILS_NOT_READY';
  end if;
  v_replay:=coalesce(v_transfer.destination_rail='CSV'
    and v_transfer.beneficiary_name_snapshot=v_name
    and v_transfer.sort_code_snapshot=v_sort
    and v_transfer.account_number_snapshot=v_account
    and v_transfer.bank_details_hash_snapshot=v_hash,false);
  if not v_replay then
    update private.bpay_next_transfer
      set destination_rail='CSV',beneficiary_name_snapshot=v_name,
          sort_code_snapshot=v_sort,account_number_snapshot=v_account,
          bank_details_hash_snapshot=v_hash
      where id=p_transfer_id;
  end if;
  return pg_catalog.jsonb_build_object('transfer_id',p_transfer_id,
    'phase','MEMBERS_READY','destination_rail','CSV',
    'bank_hash',v_hash,'replay',v_replay,
    'instruction_issued',false);
end
$function$;

ALTER FUNCTION private.bpay_next_bind_simple_csv_destination_v1(uuid) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_bind_simple_csv_destination_v1(uuid) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D14 successor of supabase/repeatable/04102026_0150_banking_pay_next_simple_csv_issue_v1.sql
create or replace function private.bpay_next_issue_simple_csv_v1(
  p_instruction_id uuid,p_transfer_id uuid,p_actor_user_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_candidate public.candidates%rowtype;
  v_umbrella public.umbrellas%rowtype;
  v_actor public.tms_users%rowtype;
  v_existing private.bpay_next_csv_instruction%rowtype;
  v_leg private.bpay_next_destination_group_leg%rowtype;
  v_origin private.bpay_next_stored_credit_origin%rowtype;
  v_columns jsonb;
  v_options jsonb;
  v_with_account_type boolean;
  v_name text;
  v_sort text;
  v_account text;
  v_hash text;
  v_reference text;
  v_file_name text;
  v_csv text;
  v_sha text;
begin
  if p_instruction_id is null or p_transfer_id is null
     or p_actor_user_id is null then
    raise exception using errcode='22023',
      message='BPAY_NEXT_CSV_ISSUE_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control m
                where m.id=1 and m.active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id into strict v_run_id
    from private.bpay_next_transfer t
    join private.bpay_next_run_worker w on w.id=t.run_worker_id
    where t.id=p_transfer_id;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w
    join private.bpay_next_transfer t on t.run_worker_id=w.id
    where t.id=p_transfer_id for update of w;
  select * into strict v_transfer from private.bpay_next_transfer
    where id=p_transfer_id for update;
  select * into strict v_actor from public.tms_users
    where id=p_actor_user_id for share;
  if v_actor.is_active is not true
     or (v_actor.payment_authoriser is not true
         and v_actor.payment_golden_key is not true) then
    raise exception using errcode='42501',
      message='BPAY_NEXT_CSV_ACTOR_NOT_AUTHORISED';
  end if;
  select * into v_existing from private.bpay_next_csv_instruction
    where id=p_instruction_id;
  if found then
    if v_existing.transfer_id<>p_transfer_id then
      raise exception using errcode='23514',
        message='BPAY_NEXT_CSV_ISSUE_REPLAY_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'instruction_id',v_existing.id,'transfer_id',p_transfer_id,
      'file_name',v_existing.file_name,'csv_sha256',v_existing.csv_sha256,
      'csv_text',v_existing.csv_text,'replay',true,
      'payment_recorded',exists(select 1 from private.bpay_next_outcome_request r
        where r.transfer_id=p_transfer_id and r.posting_complete));
  end if;
  if exists(select 1 from private.bpay_next_csv_instruction i
            where i.transfer_id=p_transfer_id) then
    raise exception using errcode='23514',
      message='BPAY_NEXT_CSV_TRANSFER_ALREADY_ISSUED';
  end if;
  -- Exact issued receipt readback above precedes current bank safety checks.
  v_leg:=private.bpay_next_destination_execution_leg_v1(p_transfer_id);
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null
     or exists(select 1 from private.bpay_next_cancel_request r
               where r.run_worker_id=v_worker.id and r.status in ('REQUESTED','CANCELLING'))
     or (v_worker.status<>'READY' and not (v_worker.status='COMPLETE'
       and v_leg.transfer_id is not null and v_transfer.original_transfer_id is not null))
     or v_worker.target_pay_channel not in ('PAYE','UMBRELLA')
     or v_transfer.status<>'MEMBERS_READY'
     or v_transfer.candidate_id<>v_worker.candidate_id
     or not ((v_worker.target_pay_channel='PAYE' and
          v_transfer.beneficiary_kind='CANDIDATE' and v_transfer.beneficiary_id=v_worker.candidate_id)
       or (v_worker.target_pay_channel='UMBRELLA' and v_worker.target_umbrella_id is not null and
          v_transfer.beneficiary_kind='UMBRELLA' and v_transfer.beneficiary_id=v_worker.target_umbrella_id))
     or v_transfer.destination_rail<>'CSV'
     or v_transfer.account_approval_ref is not null
     or v_transfer.member_count<=0
     or v_transfer.member_cash_sum<>v_transfer.cash_amount
     or v_transfer.cash_amount<=0 then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_ISSUE_NOT_ELIGIBLE';
  end if;
  -- The Candidate row lock makes the actual issue and a simultaneous bank
  -- change resolve in one order. No historical account or Timesheet scan.
  select * into strict v_candidate from public.candidates
    where id=v_worker.candidate_id for share;
  v_name:=nullif(pg_catalog.btrim(v_candidate.account_holder),'');
  v_sort:=pg_catalog.regexp_replace(
    coalesce(v_candidate.sort_code,''),'[^0-9]','','g');
  v_account:=pg_catalog.regexp_replace(
    coalesce(v_candidate.account_number,''),'[^0-9]','','g');
  v_hash:=public._bank_hash(v_candidate.sort_code,
    v_candidate.account_number,v_candidate.account_holder);
  if v_worker.target_pay_channel='UMBRELLA' then
    if v_leg.transfer_id is not null or v_worker.case_selection_revision<>0
       or v_candidate.active is not true
       or pg_catalog.upper(coalesce(v_candidate.pay_method,''))<>'UMBRELLA'
       or v_candidate.umbrella_id is distinct from v_worker.target_umbrella_id then
      raise exception using errcode='55000',message='BPAY_NEXT_CSV_UMBRELLA_DESTINATION_NOT_READY';
    end if;
    select * into strict v_umbrella from public.umbrellas where id=v_worker.target_umbrella_id for share;
    v_name:=nullif(pg_catalog.btrim(v_umbrella.name),'');
    v_sort:=pg_catalog.regexp_replace(coalesce(v_umbrella.sort_code,''),'[^0-9]','','g');
    v_account:=pg_catalog.regexp_replace(coalesce(v_umbrella.account_number,''),'[^0-9]','','g');
    v_hash:=public._bank_hash(v_umbrella.sort_code,v_umbrella.account_number,v_umbrella.name);
    if v_umbrella.enabled is not true or v_hash is distinct from v_umbrella.bank_details_hash then
      raise exception using errcode='55000',message='BPAY_NEXT_CSV_UMBRELLA_DESTINATION_NOT_READY';
    end if;
  end if;
  if v_leg.leg_kind='ONEOFF' then
    select o.* into strict v_origin from private.bpay_next_net_destination_amount d
      join private.bpay_next_stored_credit_origin o on o.command_id=d.first_origin_command_id
      where d.destination_id=v_leg.destination_id;
    v_name:=nullif(pg_catalog.btrim(v_origin.beneficiary_name),'');
    v_sort:=v_origin.sort_code;v_account:=v_origin.account_number;v_hash:=v_origin.bank_details_hash;
  end if;
  if v_candidate.active is not true
     or pg_catalog.upper(coalesce(v_candidate.pay_method,''))<>v_worker.target_pay_channel
     or v_name is null
     or pg_catalog.octet_length(v_name)>70
     or position(E'\r' in v_name)>0
     or position(E'\n' in v_name)>0
     or v_sort !~ '^[0-9]{6}$'
     or v_account !~ '^[0-9]{8}$'
     or v_hash is null
     or (v_worker.target_pay_channel='PAYE' and
         v_leg.leg_kind is distinct from 'ONEOFF' and v_hash is distinct from v_candidate.bank_details_hash)
     or v_name is distinct from v_transfer.beneficiary_name_snapshot
     or v_sort is distinct from v_transfer.sort_code_snapshot
     or v_account is distinct from v_transfer.account_number_snapshot
     or v_hash is distinct from v_transfer.bank_details_hash_snapshot then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_DESTINATION_CHANGED_BEFORE_ISSUE';
  end if;
  select sd.pay_export_csv_columns_json,
         coalesce(sd.pay_export_csv_format_json,'{}'::jsonb)
    into strict v_columns,v_options
    from public.settings_defaults sd where sd.id=1;
  if v_options<>'{}'::jsonb then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_CONFIGURED_FORMAT_NOT_YET_SUPPORTED';
  end if;
  v_with_account_type:=coalesce(v_columns=
    '["payment_reference","payee_name","sort_code","account_number","account_type","amount"]'::jsonb,false);
  if not v_with_account_type and v_columns is distinct from
      '["payment_reference","payee_name","sort_code","account_number","amount"]'::jsonb then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_CONFIGURED_COLUMNS_NOT_YET_SUPPORTED';
  end if;
  v_reference:='BP'||substring(
    pg_catalog.replace(p_transfer_id::text,'-','') from 1 for 18);
  v_file_name:='bpay-next-'||p_instruction_id::text||'.csv';
  v_csv:='Payment reference,Payee name,Sort code,Bank account number,';
  if v_with_account_type then
    v_csv:=v_csv||'Bank account type,';
  end if;
  v_csv:=v_csv||'Amount'||E'\n'||v_reference||',"'||
    pg_catalog.replace(v_name,'"','""')||'",'||v_sort||','||v_account||',';
  if v_with_account_type then
    v_csv:=v_csv||',';
  end if;
  v_csv:=v_csv||pg_catalog.to_char(v_transfer.cash_amount,
    'FM9999999999999990.00')||E'\n';
  v_sha:=pg_catalog.encode(pg_catalog.sha256(
    pg_catalog.convert_to(v_csv,'UTF8')),'hex');
  insert into private.bpay_next_csv_instruction
    (id,transfer_id,run_worker_id,actor_user_id,payment_reference,
     bank_details_hash_snapshot,cash_amount,file_name,csv_text,csv_sha256)
    values(p_instruction_id,p_transfer_id,v_worker.id,p_actor_user_id,
      v_reference,v_hash,v_transfer.cash_amount,v_file_name,v_csv,v_sha);
  update private.bpay_next_transfer
    set account_approval_ref='CSV_INSTRUCTION:'||p_instruction_id::text,
        status='ISSUED_CSV'
    where id=p_transfer_id;
  return pg_catalog.jsonb_build_object(
    'instruction_id',p_instruction_id,'transfer_id',p_transfer_id,
    'file_name',v_file_name,'csv_sha256',v_sha,'csv_text',v_csv,
    'replay',false,'payment_recorded',false);
end
$function$;

ALTER FUNCTION private.bpay_next_issue_simple_csv_v1(uuid,uuid,uuid) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_issue_simple_csv_v1(uuid,uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D13 successor of supabase/repeatable/04102026_0200_banking_pay_next_simple_csv_settlement_v1.sql
create or replace function private.bpay_next_receive_simple_csv_settlement_v1(
  p_command_id uuid,p_transfer_id uuid,p_receipt_id text,
  p_amount numeric,p_occurred_at timestamptz,p_actor_user_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_candidate_id uuid;
  v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_actor public.tms_users%rowtype;
  v_receipt private.bpay_next_transfer_outcome%rowtype;
  v_request private.bpay_next_outcome_request%rowtype;
  v_sequence bigint;
begin
  if p_command_id is null or p_transfer_id is null or p_receipt_id is null
     or pg_catalog.octet_length(p_receipt_id) not between 1 and 256
     or p_amount is null or p_amount<=0
     or p_amount<>pg_catalog.round(p_amount,2)
     or p_occurred_at is null or not pg_catalog.isfinite(p_occurred_at)
     or p_actor_user_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_SETTLEMENT_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control
                where id=1 and active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id,w.candidate_id into strict v_run_id,v_candidate_id
    from private.bpay_next_transfer t
    join private.bpay_next_run_worker w on w.id=t.run_worker_id
    where t.id=p_transfer_id;
  perform 1 from private.bpay_next_pay_run where id=v_run_id for update;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w
    join private.bpay_next_transfer t on t.run_worker_id=w.id
    where t.id=p_transfer_id for update of w;
  select * into strict v_transfer from private.bpay_next_transfer
    where id=p_transfer_id for update;
  select * into strict v_actor from public.tms_users
    where id=p_actor_user_id for share;
  if v_actor.is_active is not true
     or (v_actor.payment_authoriser is not true
         and v_actor.payment_golden_key is not true) then
    raise exception using errcode='42501',message='BPAY_NEXT_SETTLEMENT_ACTOR_NOT_AUTHORISED';
  end if;
  select * into v_receipt from private.bpay_next_transfer_outcome
    where receipt_id=p_receipt_id;
  if found then
    if v_receipt.transfer_id<>p_transfer_id or v_receipt.outcome_kind<>'SETTLED'
       or v_receipt.whole_transfer_amount<>p_amount
       or v_receipt.occurred_at_utc<>p_occurred_at then
      raise exception using errcode='23514',message='BPAY_NEXT_SETTLEMENT_RECEIPT_CONFLICT';
    end if;
    select * into strict v_request from private.bpay_next_outcome_request
      where outcome_id=v_receipt.id;
    return pg_catalog.jsonb_build_object('command_id',v_request.command_id,
      'outcome_id',v_receipt.id,'replay',true,
      'posting_complete',v_request.posting_complete);
  end if;
  if exists(select 1 from private.bpay_next_outcome_request
            where command_id=p_command_id or transfer_id=p_transfer_id) then
    raise exception using errcode='23514',message='BPAY_NEXT_SETTLEMENT_COMMAND_CONFLICT';
  end if;
  if v_transfer.status not in ('ISSUED_CSV','UNKNOWN')
     or v_transfer.destination_rail<>'CSV'
     or v_transfer.cash_amount<>p_amount
     or not exists(select 1 from private.bpay_next_csv_instruction i
                   where i.transfer_id=p_transfer_id and i.cash_amount=p_amount)
     or not (v_worker.target_pay_channel='PAYE' or
       (v_worker.target_pay_channel='UMBRELLA' and v_worker.case_selection_revision=0
        and v_worker.target_umbrella_id is not null
        and v_transfer.beneficiary_kind='UMBRELLA'
        and v_transfer.beneficiary_id=v_worker.target_umbrella_id
        and exists(select 1 from private.bpay_next_net_projection p
          where p.id=coalesce(v_transfer.projection_id,
            (select projection_id from private.bpay_next_transfer where id=v_transfer.original_transfer_id))
            and p.run_worker_id=v_worker.id and p.input_kind='UMBRELLA'
            and p.entered_paye_net is null and p.request_command_id is null
            and p.cash_amount=v_worker.gross_inc_vat))) then
    raise exception using errcode='55000',message='BPAY_NEXT_SETTLEMENT_NOT_ELIGIBLE';
  end if;
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'CSV_SETTLEMENT');
  insert into private.bpay_next_command_member(command_id,candidate_id,member_no)
    values(p_command_id,v_worker.candidate_id,1);
  insert into private.bpay_next_transfer_outcome
    (transfer_id,receipt_id,outcome_kind,whole_transfer_amount,occurred_at_utc)
    values(p_transfer_id,p_receipt_id,'SETTLED',p_amount,p_occurred_at)
    returning * into v_receipt;
  insert into private.bpay_next_outcome_request
    (command_id,outcome_id,transfer_id,run_worker_id,candidate_id,actor_user_id)
    values(p_command_id,v_receipt.id,p_transfer_id,v_worker.id,
      v_worker.candidate_id,p_actor_user_id);
  update private.bpay_next_transfer set status='SETTLED' where id=p_transfer_id;
  update private.bpay_next_command
    set expected_member_count=1,status='SEALED',sealed_at_utc=pg_catalog.transaction_timestamp()
    where id=p_command_id;
  return pg_catalog.jsonb_build_object('command_id',p_command_id,
    'outcome_id',v_receipt.id,'sequence',v_sequence,'replay',false,'posting_complete',false);
end
$function$;

ALTER FUNCTION private.bpay_next_receive_simple_csv_settlement_v1(uuid,uuid,text,numeric,timestamp with time zone,uuid) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_receive_simple_csv_settlement_v1(uuid,uuid,text,numeric,timestamp with time zone,uuid) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D13 successor of supabase/repeatable/04102026_0200_banking_pay_next_simple_csv_settlement_v1.sql
create or replace function private.bpay_next_post_simple_outcome_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_cursor bigint,p_limit integer
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;
  v_run uuid;
  v_candidate uuid;
  v_job private.bpay_next_job%rowtype;
  v_request private.bpay_next_outcome_request%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_line private.bpay_next_run_line%rowtype;
  v_hold private.bpay_next_hold%rowtype;
  v_member record;
  v_cursor bigint;
  v_count bigint;
  v_seen integer:=0;
  v_original uuid;
  v_effect uuid;v_seed_effect uuid;
  v_return_cash private.bpay_next_return_cash%rowtype;
  v_internal private.bpay_next_internal_receipt%rowtype;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_limit is null or p_limit not between 1 and 100
     or p_expected_cursor is not null and p_expected_cursor<1 then
    raise exception using errcode='22023',message='BPAY_NEXT_OUTCOME_PAGE_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id,j.candidate_id into strict v_run,v_candidate
    from private.bpay_next_job j
    join private.bpay_next_outcome_request r on r.command_id=j.command_id
    join private.bpay_next_run_worker w on w.id=r.run_worker_id
    where j.id=p_job_id and r.candidate_id=j.candidate_id;
  perform 1 from private.bpay_next_pay_run where id=v_run for update;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_job from private.bpay_next_job where id=p_job_id for update;
  select * into strict v_request from private.bpay_next_outcome_request
    where command_id=v_job.command_id for update;
  perform 1 from private.bpay_next_run_worker where id=v_request.run_worker_id for update;
  select * into strict v_transfer from private.bpay_next_transfer
    where id=v_request.transfer_id for update;
  if exists(select 1 from private.bpay_next_run_worker w
            where w.id=v_request.run_worker_id and w.status in ('CANCELLING','CANCELLED')) then
    raise exception using errcode='55000',message='BPAY_NEXT_OUTCOME_CANCELLED_GROUP';
  end if;
  if v_job.job_kind not in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') or v_job.module_epoch<>v_epoch
     or v_transfer.candidate_id<>v_candidate
     or v_transfer.run_worker_id<>v_request.run_worker_id then
    raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_SCOPE_INVALID';
  end if;
  if v_job.job_kind='INTERNAL_SETTLEMENT' then
    select * into strict v_internal from private.bpay_next_internal_receipt where id=v_request.internal_receipt_id;
    if v_request.outcome_id is not null or v_internal.command_id<>v_job.command_id
       or v_internal.transfer_id<>v_transfer.id or v_internal.run_worker_id<>v_request.run_worker_id
       or v_internal.candidate_id<>v_candidate or v_internal.projection_id<>v_transfer.projection_id
       or v_transfer.execution_kind<>'INTERNAL_ZERO' or v_transfer.cash_amount<>0
       or v_transfer.original_transfer_id is not null or v_transfer.return_cash_id is not null then
      raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_OUTCOME_SCOPE_INVALID';
    end if;
  elsif v_transfer.execution_kind<>'BANK' or v_request.outcome_id is null or v_request.internal_receipt_id is not null then
    raise exception using errcode='23514',message='BPAY_NEXT_BANK_OUTCOME_SCOPE_INVALID';
  end if;
  if v_job.status='DONE' and v_request.posting_complete then
    return pg_catalog.jsonb_build_object('done',true,'replay',true,
      'posted_members',v_request.posted_member_count);
  end if;
  if v_job.status<>'LEASED' or v_job.phase<>'MEMBERS'
     or v_job.lease_nonce<>p_lease_nonce or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or (v_job.job_kind='CSV_SETTLEMENT' and v_transfer.status not in ('SETTLED','RETURNED'))
     or (v_job.job_kind='INTERNAL_SETTLEMENT' and v_transfer.status<>'INTERNAL_PROCESSING')
     or (v_job.job_kind='INTERNAL_SETTLEMENT' and not exists(select 1 from private.bpay_next_worker_control
       where candidate_id=v_candidate and active_owner_epoch=p_owner_epoch))
     or exists(select 1 from private.bpay_next_job j where j.candidate_id=v_candidate
               and j.command_sequence<v_job.command_sequence and j.status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_OUTCOME_POST_NOT_ELIGIBLE';
  end if;
  if v_job.cursor_key is distinct from p_expected_cursor::text then
    return pg_catalog.jsonb_build_object('done',false,'replay',true,
      'cursor',v_job.cursor_key,'posted_members',v_request.posted_member_count);
  end if;
  v_cursor:=p_expected_cursor; v_count:=v_request.posted_member_count;
  if v_transfer.return_cash_id is not null then
    select * into strict v_return_cash from private.bpay_next_return_cash
      where id=v_transfer.return_cash_id for update;
    if v_transfer.member_count<>1 or v_return_cash.candidate_id<>v_candidate
       or v_return_cash.original_transfer_id<>v_transfer.original_transfer_id
       or v_return_cash.amount_held<v_transfer.cash_amount then
      raise exception using errcode='23514',message='BPAY_NEXT_REISSUE_CASH_HOLD_MISMATCH';
    end if;
  end if;
  for v_member in select * from private.bpay_next_transfer_member
    where transfer_id=v_transfer.id and (v_cursor is null or member_no>v_cursor)
    order by member_no limit p_limit
  loop
    if v_member.subject_kind='CASH_REISSUE' then
      if v_transfer.return_cash_id is null
         or v_member.signed_cash_contribution<>v_transfer.cash_amount then
        raise exception using errcode='23514',message='BPAY_NEXT_REISSUE_MEMBER_MISMATCH';
      end if;
      update private.bpay_next_return_cash
        set amount_held=amount_held-v_transfer.cash_amount,
            amount_reissued_paid=amount_reissued_paid+v_transfer.cash_amount
        where id=v_return_cash.id;
    elsif v_transfer.return_cash_id is not null then
      raise exception using errcode='23514',message='BPAY_NEXT_REISSUE_PAYROLL_MEMBER_FORBIDDEN';
    elsif v_member.subject_kind='WORK' then
      select * into strict v_line from private.bpay_next_run_line where id=v_member.run_line_id;
      if v_line.run_worker_id<>v_request.run_worker_id
         or v_line.target_pay_channel not in ('PAYE','UMBRELLA')
         or v_line.frozen_inc_vat<>v_member.signed_cash_contribution then
        raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_FROZEN_MEMBER_MISMATCH';
      end if;
      if v_line.target_pay_channel='UMBRELLA' and
         (v_line.source_pay_channel is distinct from 'UMBRELLA'
          or v_line.frozen_ex_vat is distinct from v_line.source_consumed_ex_vat
          or not exists(select 1 from private.bpay_next_approved_line a
            where a.id=v_line.approved_line_id and a.revision_id=v_line.captured_revision_id
              and a.component_key=v_line.component_key and a.component_kind='WORK' and a.tax_treatment='TAXABLE')) then
        raise exception using errcode='55000',message='BPAY_NEXT_UMBRELLA_WORK_EXECUTION_UNSUPPORTED';
      end if;
      if v_line.source_consumed_ex_vat>0 then
        select * into strict v_hold from private.bpay_next_hold where run_line_id=v_line.id for update;
        if v_hold.status<>'ACTIVE' or v_hold.work_id<>v_line.work_id
           or v_hold.component_key<>v_line.component_key
           or v_hold.source_reserved_ex_vat<>v_line.source_consumed_ex_vat
           or v_hold.target_amount_ex_vat<>v_line.frozen_ex_vat
           or v_hold.target_amount_vat<>v_line.frozen_vat
           or v_hold.target_amount_inc_vat<>v_line.frozen_inc_vat then
          raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_HOLD_MISMATCH';
        end if;
        -- A retained unbound frozen child may settle after common-HEAD adoption.
        -- Seed from the real ACTIVE hold/current APPLIED position only; never
        -- require its old capture to point at a newly-created binding version.
        if exists(select 1 from private.bpay_next_position p
          join private.bpay_next_source_component_binding b on b.canonical_work_id=p.work_id
            and b.canonical_component_key=p.component_key
          join private.bpay_next_source_component_binding_version v on v.id=b.current_binding_version_id
          where p.work_id=v_line.work_id and p.component_key=v_line.component_key
            and p.source_book_state='UNBOUND' and v.approval_work_id=p.work_id
            and v.approval_revision_id=p.applied_revision_id and v.publication_command_id_2 is null
            and v.approval_source_channel=v_line.source_pay_channel
            and v.approval_source_channel in ('PAYE','UMBRELLA') and v.tax_treatment='TAXABLE') then
          select b.original_effect_id into v_seed_effect from private.bpay_next_work_collection b
            join private.bpay_next_position p on p.work_id=b.work_id and p.component_key=b.component_key
            where b.work_id=v_line.work_id and b.component_key=v_line.component_key and p.realised_source_ex_vat>0;
          perform * from private.bpay_next_source_disposition_seed_v1(v_line.work_id,v_line.component_key,
            (select applied_revision_id from private.bpay_next_position where work_id=v_line.work_id
              and component_key=v_line.component_key),v_seed_effect,v_hold.id);
        end if;
        select original_timesheet_id into strict v_original from private.bpay_next_work where id=v_line.work_id;
        insert into private.bpay_next_financial_effect
          (operation_id,operation_item_id,effect_kind,candidate_id,work_id,component_key,
           original_timesheet_id,original_transfer_id,source_disposition_ex_vat,
           target_amount_ex_vat,target_amount_vat,target_amount_inc_vat,source_run_line_id,
           source_binding_version_id,canonical_source_work_id,canonical_source_component_key,native_source_channel)
          values(v_job.command_id,v_hold.id,'PAYROLL_SETTLED',v_candidate,
            v_line.work_id,v_line.component_key,v_original,v_transfer.id,
            v_hold.source_reserved_ex_vat,v_hold.target_amount_ex_vat,
            v_hold.target_amount_vat,v_hold.target_amount_inc_vat,
            case when v_line.source_binding_version_id is null then null else v_line.id end,
            v_line.source_binding_version_id,v_line.canonical_source_work_id,v_line.canonical_source_component_key,
            case when v_line.source_binding_version_id is null then null else v_line.source_pay_channel end)
          returning id into v_effect;
        update private.bpay_next_run_worker
          set realised_effect_count=realised_effect_count+1
          where id=v_request.run_worker_id;
        update private.bpay_next_position
          set held_source_ex_vat=held_source_ex_vat-v_hold.source_reserved_ex_vat,
              held_target_ex_vat=held_target_ex_vat-v_hold.target_amount_ex_vat,
              held_target_vat=held_target_vat-v_hold.target_amount_vat,
              held_target_inc_vat=held_target_inc_vat-v_hold.target_amount_inc_vat,
              realised_source_ex_vat=realised_source_ex_vat+v_hold.source_reserved_ex_vat,
              realised_target_ex_vat=realised_target_ex_vat+v_hold.target_amount_ex_vat,
              realised_target_vat=realised_target_vat+v_hold.target_amount_vat,
              realised_target_inc_vat=realised_target_inc_vat+v_hold.target_amount_inc_vat,
              updated_at_utc=pg_catalog.transaction_timestamp()
          where work_id=v_line.work_id and component_key=v_line.component_key
            and source_basis_channel=v_line.source_pay_channel
            and held_source_ex_vat>=v_hold.source_reserved_ex_vat;
        if not found then
          raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_POSITION_MISMATCH';
        end if;
        update private.bpay_next_hold set status='REALISED',finished_at_utc=pg_catalog.transaction_timestamp()
          where id=v_hold.id;
        perform private.bpay_next_reconcile_work_collection_v1(
          p_job_id,v_line.work_id,v_line.component_key,v_effect);
      end if;
    elsif v_member.subject_kind='CASE' then
      perform private.bpay_next_post_case_transfer_member_v1(p_job_id,v_transfer.id,v_member.member_no);
    elsif v_member.subject_kind<>'NET_ADJUSTMENT' then
      raise exception using errcode='55000',message='BPAY_NEXT_SIMPLE_OUTCOME_CASE_NOT_SUPPORTED';
    end if;
    v_cursor:=v_member.member_no; v_count:=v_count+1; v_seen:=v_seen+1;
  end loop;
  if v_seen=0 or v_count>v_transfer.member_count then
    raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_MEMBER_COUNT_INVALID';
  end if;
  update private.bpay_next_outcome_request
    set posted_member_count=v_count,posting_complete=(v_count=v_transfer.member_count)
    where command_id=v_job.command_id;
  update private.bpay_next_worker_control
    set financial_view_revision=financial_view_revision+1,
        updated_at_utc=pg_catalog.transaction_timestamp()
    where candidate_id=v_candidate;
  if v_count=v_transfer.member_count then
    if exists(select 1 from private.bpay_next_transfer_member
              where transfer_id=v_transfer.id and member_no>v_cursor) then
      raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_EXTRA_MEMBER';
    end if;
    if v_job.job_kind='INTERNAL_SETTLEMENT' then
      perform private.bpay_next_complete_internal_zero_v1(p_job_id,v_cursor);
    else
      perform private.bpay_next_apply_week_outcome_v1(p_job_id,null);
    end if;
    perform private.bpay_next_complete_destination_leg_v1(p_job_id);
    update private.bpay_next_job set status='DONE',phase='COMPLETE',cursor_key=v_cursor::text,
      lease_nonce=null,lease_until_utc=null where id=p_job_id;
    update private.bpay_next_command set status='COMPLETE' where id=v_job.command_id;
  else
    update private.bpay_next_job set cursor_key=v_cursor::text where id=p_job_id;
  end if;
  return pg_catalog.jsonb_build_object('done',v_count=v_transfer.member_count,
    'replay',false,'cursor',v_cursor,'posted_members',v_count,'rows_visited',v_seen);
end
$function$;

ALTER FUNCTION private.bpay_next_post_simple_outcome_page_v1(uuid,uuid,bigint,bigint,integer) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_post_simple_outcome_page_v1(uuid,uuid,bigint,bigint,integer) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D12 successor of supabase/repeatable/04102026_0240_banking_pay_next_simple_cash_reissue_v1.sql
create or replace function private.bpay_next_receive_simple_reissue_v1(
  p_command_id uuid,p_return_cash_id uuid,p_actor_user_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run uuid;
  v_original private.bpay_next_transfer%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_actor public.tms_users%rowtype;
  v_request private.bpay_next_reissue_request%rowtype;
  v_cash private.bpay_next_return_cash%rowtype;
  v_sequence bigint;
begin
  if p_command_id is null or p_return_cash_id is null or p_actor_user_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_REISSUE_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id into strict v_run from private.bpay_next_return_cash c
    join private.bpay_next_transfer t on t.id=c.original_transfer_id
    join private.bpay_next_run_worker w on w.id=t.run_worker_id where c.id=p_return_cash_id;
  perform 1 from private.bpay_next_pay_run where id=v_run for update;
  select t.* into strict v_original from private.bpay_next_return_cash c
    join private.bpay_next_transfer t on t.id=c.original_transfer_id where c.id=p_return_cash_id;
  select * into strict v_worker from private.bpay_next_run_worker where id=v_original.run_worker_id for update;
  select * into strict v_actor from public.tms_users where id=p_actor_user_id for share;
  if v_actor.is_active is not true or
     (v_actor.payment_authoriser is not true and v_actor.payment_golden_key is not true) then
    raise exception using errcode='42501',message='BPAY_NEXT_REISSUE_ACTOR_NOT_AUTHORISED';
  end if;
  select * into v_request from private.bpay_next_reissue_request where command_id=p_command_id;
  if found then
    if v_request.return_cash_id<>p_return_cash_id then
      raise exception using errcode='23514',message='BPAY_NEXT_REISSUE_REPLAY_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object('command_id',p_command_id,'transfer_id',v_request.transfer_id,'replay',true);
  end if;
  if v_original.status<>'RETURNED'
     or not ((v_original.beneficiary_kind='CANDIDATE' and v_original.beneficiary_id=v_original.candidate_id)
       or (v_worker.target_pay_channel='UMBRELLA' and v_worker.case_selection_revision=0
         and v_worker.target_umbrella_id is not null and v_original.beneficiary_kind='UMBRELLA'
         and v_original.beneficiary_id=v_worker.target_umbrella_id))
     or not exists(select 1 from private.bpay_next_return_request r
                   where r.transfer_id=v_original.id and r.posting_complete) then
    raise exception using errcode='55000',message='BPAY_NEXT_REISSUE_RETURN_NOT_COMPLETE';
  end if;
  -- Reject duplicate NEW requests before receiving a command. Otherwise an
  -- unfulfillable earlier job could block the actual settlement/return.
  -- Run lock serialises all supported cash writers; the pending index also
  -- prevents two accepted requests before either one builds its transfer.
  select * into strict v_cash from private.bpay_next_return_cash where id=p_return_cash_id for update;
  if v_cash.amount_owed-v_cash.amount_held-v_cash.amount_reissued_paid<=0
     or exists(select 1 from private.bpay_next_reissue_request
               where return_cash_id=p_return_cash_id and transfer_id is null) then
    raise exception using errcode='55000',message='BPAY_NEXT_REISSUE_ALREADY_REQUESTED_OR_RESERVED';
  end if;
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'CASH_REISSUE');
  insert into private.bpay_next_command_member(command_id,candidate_id,member_no)
    values(p_command_id,v_original.candidate_id,1);
  insert into private.bpay_next_reissue_request(command_id,return_cash_id,run_worker_id,candidate_id,actor_user_id)
    values(p_command_id,p_return_cash_id,v_original.run_worker_id,v_original.candidate_id,p_actor_user_id);
  update private.bpay_next_command set status='SEALED',expected_member_count=1,
    sealed_at_utc=pg_catalog.transaction_timestamp() where id=p_command_id;
  return pg_catalog.jsonb_build_object('command_id',p_command_id,'sequence',v_sequence,'replay',false);
end
$function$;

ALTER FUNCTION private.bpay_next_receive_simple_reissue_v1(uuid,uuid,uuid) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_receive_simple_reissue_v1(uuid,uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D11 successor of supabase/repeatable/04102026_0255_banking_pay_next_original_csv_advice_page_v1.sql
create or replace function public.bpay_next_original_csv_advice_page_v1(
  p_actor_user_id uuid,p_instruction_id uuid,p_kind text,
  p_run_work_id uuid default null,p_run_line_id uuid default null,p_shift_detail_id uuid default null,
  p_after_work_id uuid default null,p_after_member_no bigint default null,
  p_after_detail_no integer default null,p_after_break_no integer default null,
  p_after_bucket text default null,p_after_rate_family text default null,p_after_rate_code text default null,
  p_limit integer default 50
) returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,private,public
set timezone='UTC'
as $function$
declare
  v_instruction private.bpay_next_csv_instruction%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_run private.bpay_next_pay_run%rowtype;
  v_leg private.bpay_next_destination_group_leg%rowtype;
  v_group private.bpay_next_destination_group%rowtype;
  v_net private.bpay_next_net_destination_state%rowtype;
  v_destination private.bpay_next_net_destination_amount%rowtype;
  v_origin private.bpay_next_stored_credit_origin%rowtype;
  v_destination_kind text:='OWN';
  v_approved_line uuid;
  v_revision uuid;
  v_sql text;
  v_row record;
  v_rows jsonb:='[]'::jsonb;
  v_bytes integer:=512;
  v_count integer:=0;
  v_more boolean:=false;
begin
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
    nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role'
    or not exists(select 1 from public.tms_users u where u.id=p_actor_user_id
      and u.is_active is true and u.role::text='admin') then
    raise exception using errcode='42501',message='BPAY_NEXT_ADVICE_FORBIDDEN';
  end if;
  if not exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT') then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  if p_instruction_id is null or p_kind is null
    or p_kind not in ('HEADER','WORKS','MEMBERS','SHIFTS','BREAKS','RATE_DETAILS','RATE_SCHEDULE')
    or p_limit is null or p_limit not between 1 and 100
    or (p_after_member_no is not null and p_after_member_no<0)
    or (p_after_detail_no is not null and p_after_detail_no<0)
    or (p_after_break_no is not null and p_after_break_no<0)
    or (p_after_bucket is not null and p_after_bucket not in ('BH','DAY','NIGHT','SAT','SUN'))
    or ((p_after_rate_family is null)<>(p_after_rate_code is null))
    or (p_after_rate_family is not null and (p_after_rate_family not in ('ADDITIONAL','MILEAGE','STANDARD')
      or char_length(p_after_rate_code) not between 1 and 128)) then
    raise exception using errcode='22023',message='BPAY_NEXT_ADVICE_REQUEST_INVALID';
  end if;
  -- Closed shape: no cursor or child ID is silently ignored by a different kind.
  if (p_run_work_id is not null and p_kind<>'RATE_SCHEDULE')
    or (p_run_line_id is not null and p_kind not in ('SHIFTS','BREAKS','RATE_DETAILS'))
    or (p_shift_detail_id is not null and p_kind<>'BREAKS')
    or (p_after_work_id is not null and p_kind<>'WORKS')
    or (p_after_member_no is not null and p_kind<>'MEMBERS')
    or (p_after_detail_no is not null and p_kind<>'SHIFTS')
    or (p_after_break_no is not null and p_kind<>'BREAKS')
    or (p_after_bucket is not null and p_kind<>'RATE_DETAILS')
    or (p_after_rate_family is not null and p_kind<>'RATE_SCHEDULE')
    or (p_kind='RATE_SCHEDULE' and p_run_work_id is null)
    or (p_kind in ('SHIFTS','BREAKS','RATE_DETAILS') and p_run_line_id is null)
    or (p_kind='BREAKS' and p_shift_detail_id is null) then
    raise exception using errcode='22023',message='BPAY_NEXT_ADVICE_REQUEST_INVALID';
  end if;
  select * into v_instruction from private.bpay_next_csv_instruction where id=p_instruction_id;
  if not found then
    raise exception using errcode='P0002',message='BPAY_NEXT_ADVICE_INSTRUCTION_NOT_FOUND';
  end if;
  select * into strict v_transfer from private.bpay_next_transfer where id=v_instruction.transfer_id;
  if v_transfer.original_transfer_id is not null or v_transfer.projection_id is null then
    raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_ORIGINAL_CSV_REQUIRED';
  end if;
  select * into strict v_projection from private.bpay_next_net_projection where id=v_transfer.projection_id;
  select * into strict v_worker from private.bpay_next_run_worker where id=v_instruction.run_worker_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_worker.run_id;
  if v_transfer.original_transfer_id is not null or v_transfer.execution_kind<>'BANK'
    or not ((v_worker.target_pay_channel='PAYE' and v_transfer.beneficiary_kind='CANDIDATE')
      or (v_worker.target_pay_channel='UMBRELLA' and v_transfer.beneficiary_kind='UMBRELLA'
        and v_worker.target_umbrella_id is not null and v_projection.input_kind='UMBRELLA'
        and v_worker.case_selection_revision=0))
    or v_transfer.run_worker_id<>v_worker.id or v_transfer.candidate_id<>v_worker.candidate_id
    or v_projection.run_worker_id<>v_worker.id
    or v_transfer.beneficiary_id is distinct from
      (case when v_worker.target_pay_channel='UMBRELLA' then v_worker.target_umbrella_id else v_worker.candidate_id end)
    or v_transfer.return_cash_id is not null
    or v_instruction.cash_amount<>v_transfer.cash_amount
    or v_instruction.bank_details_hash_snapshot is distinct from v_transfer.bank_details_hash_snapshot
    or v_transfer.member_count<1 or v_transfer.member_cash_sum<>v_transfer.cash_amount
    or (v_worker.target_pay_channel='PAYE' and v_projection.input_kind not in ('PAYE_MANUAL','PAYE_IMPORT','CASE_PAYOUT'))
    or (v_worker.target_pay_channel='UMBRELLA' and
      (v_projection.entered_paye_net is not null or v_projection.request_command_id is not null
       or v_projection.cash_amount is distinct from v_projection.gross_inc_vat)) then
    raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_ORIGINAL_CSV_REQUIRED';
  end if;
  -- A frozen leg may be smaller than its accepted Candidate projection. This
  -- is a point read of immutable sealed facts, NOT the execution qualifier:
  -- that qualifier checks today's bank version and must not invalidate advice
  -- for an already-issued original instruction after factual account changes.
  select * into v_leg from private.bpay_next_destination_group_leg where transfer_id=v_transfer.id;
  if not found then
    if v_projection.cash_amount<>v_transfer.cash_amount
      or exists(select 1 from private.bpay_next_destination_group where run_worker_id=v_worker.id) then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
  else
    select * into strict v_group from private.bpay_next_destination_group where anchor_transfer_id=v_leg.anchor_transfer_id;
    select * into strict v_net from private.bpay_next_net_destination_state where state_id=v_group.net_state_id;
    if v_group.stage<>'COMPLETE' or v_group.completed_at_utc is null
      or v_group.run_worker_id<>v_worker.id or v_group.candidate_id<>v_worker.candidate_id
      or v_group.projection_id<>v_projection.id or v_net.run_worker_id<>v_worker.id
      or v_net.projection_id is distinct from v_projection.id or v_net.completed_at_utc is null
      or v_group.processed_work_count<>v_group.expected_work_count or v_group.processed_case_count<>v_group.expected_case_count
      or v_group.created_leg_count<>v_group.expected_leg_count or v_group.sealed_leg_count<>v_group.expected_leg_count
      or v_group.expected_leg_count<>v_net.external_leg_count+1
      or v_group.member_cash_total<>v_projection.cash_amount or v_group.sealed_cash_total<>v_projection.cash_amount
      or v_net.cash_amount is distinct from v_projection.cash_amount
      or v_net.own_amount+v_net.external_amount is distinct from v_projection.cash_amount then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
    v_destination_kind:=v_leg.leg_kind;
    if v_leg.leg_kind='OWN' then
      if v_transfer.id<>v_group.anchor_transfer_id or v_leg.destination_id is not null
        or v_transfer.cash_amount is distinct from v_net.own_amount then
        raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
    else
      select * into strict v_destination from private.bpay_next_net_destination_amount where destination_id=v_leg.destination_id;
      select * into strict v_origin from private.bpay_next_stored_credit_origin where command_id=v_destination.first_origin_command_id;
      if v_destination.state_id<>v_net.state_id or v_destination.amount<>v_transfer.cash_amount
        or v_origin.candidate_id<>v_worker.candidate_id or v_destination.bank_details_hash<>v_origin.bank_details_hash
        or v_origin.original_source_pay_channel<>'UMBRELLA' or v_origin.original_tax_treatment<>'NON_TAXABLE'
        or v_origin.original_routing_kind<>'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
        or (v_transfer.bank_details_hash_snapshot,v_transfer.beneficiary_name_snapshot,
            v_transfer.sort_code_snapshot,v_transfer.account_number_snapshot)
          is distinct from (v_origin.bank_details_hash,pg_catalog.btrim(v_origin.beneficiary_name),
            v_origin.sort_code,v_origin.account_number) then
        raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
    end if;
  end if;
  -- CSV issuance is the immutable read gate. Current worker/transfer/outcome
  -- status and retirement of this NET projection cannot re-price this issue.
  if p_kind='HEADER' then
    v_rows:=jsonb_build_array(jsonb_build_object(
      'instruction_id',v_instruction.id,'transfer_id',v_transfer.id,'projection_id',v_projection.id,
      'projection_no',v_projection.projection_no::text,'input_kind',v_projection.input_kind,
      'run_id',v_run.id,'run_worker_id',v_worker.id,'candidate_id',v_worker.candidate_id,
      'pay_date',v_run.pay_date,'target_pay_channel',v_worker.target_pay_channel,
      'beneficiary_name_snapshot',v_transfer.beneficiary_name_snapshot,
      'payment_reference',v_instruction.payment_reference,'issued_at_utc',v_instruction.issued_at_utc,
      'member_count',v_transfer.member_count::text,
      'gross_ex_vat',v_projection.gross_ex_vat::text,'gross_vat',v_projection.gross_vat::text,
      'gross_inc_vat',v_projection.gross_inc_vat::text,'entered_paye_net',v_projection.entered_paye_net::text,
      'accepted_gross_additions',v_projection.accepted_gross_additions::text,
      'accepted_gross_deductions',v_projection.accepted_gross_deductions::text,
      'accepted_net_additions',v_projection.accepted_net_additions::text,
      'accepted_recoveries',v_projection.accepted_recoveries::text,'cash_amount',v_instruction.cash_amount::text,
      'projection_cash_amount',v_projection.cash_amount::text,'destination_kind',v_destination_kind));
    if octet_length(v_rows::text)>120000 then
      raise exception using errcode='54000',message='BPAY_NEXT_ADVICE_ROW_TOO_LARGE';
    end if;
    return jsonb_build_object('rows',v_rows,'complete',true);
  end if;
  if p_kind in ('SHIFTS','BREAKS','RATE_DETAILS') then
    select l.approved_line_id into v_approved_line
    from private.bpay_next_transfer_member m join private.bpay_next_run_line l on l.id=m.run_line_id
    where m.transfer_id=v_transfer.id and m.subject_kind='WORK' and l.id=p_run_line_id
      and l.run_worker_id=v_worker.id;
    if not found then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_LINE_NOT_IN_INSTRUCTION';
    end if;
  elsif p_kind='RATE_SCHEDULE' then
    select rw.captured_revision_id into v_revision from private.bpay_next_run_work rw
    where rw.id=p_run_work_id and rw.run_worker_id=v_worker.id and exists(
      select 1 from private.bpay_next_run_line l join private.bpay_next_transfer_member m on m.run_line_id=l.id
      where l.run_work_id=rw.id and m.transfer_id=v_transfer.id and m.subject_kind='WORK');
    if not found then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_WORK_NOT_IN_INSTRUCTION';
    end if;
  end if;
  if p_kind='WORKS' then
    v_sql:=$query$select private.bpay_next_advice_work_v1(rw.id) row_value
      from private.bpay_next_run_work rw where rw.run_worker_id=$2
        and ($6::uuid is null or rw.work_id>$6) and exists(
          select 1 from private.bpay_next_run_line l join private.bpay_next_transfer_member m on m.run_line_id=l.id
          where l.run_work_id=rw.id and m.transfer_id=$1 and m.subject_kind='WORK')
      order by rw.work_id limit $12$query$;
  elsif p_kind='MEMBERS' then
    v_sql:=$query$select jsonb_build_object(
      'member_no',m.member_no::text,'subject_kind',m.subject_kind,'signed_cash_contribution',m.signed_cash_contribution::text,
      'work',case when m.subject_kind='WORK' then private.bpay_next_advice_work_v1(l.run_work_id) end,
      'line',case when m.subject_kind='WORK' then jsonb_build_object(
        'run_line_id',l.id,'run_work_id',l.run_work_id,'captured_revision_id',l.captured_revision_id,
        'line_no',l.line_no::text,'component_key',l.component_key,'component_kind',a.component_kind,
        'work_date',a.work_date,'unit_label',a.unit_label,'approved_quantity',a.approved_quantity::text,
        'approved_unit_rate',a.approved_unit_rate::text,'expected_rate_detail_count',a.expected_rate_detail_count,
        'evidence_ref',a.evidence_ref,'approved_source_ex_vat',a.source_pay_ex_vat::text,
        'source_consumed_ex_vat',l.source_consumed_ex_vat::text,'frozen_ex_vat',l.frozen_ex_vat::text,
        'frozen_vat',l.frozen_vat::text,'frozen_inc_vat',l.frozen_inc_vat::text) end,
      'case',case when m.subject_kind='CASE' then jsonb_build_object(
        'case_instruction_id',ci.id,'allocation_result_id',cr.id,'case_id',ci.case_id,
        'case_kind',ci.case_kind,'case_subtype',ci.case_subtype,'tax_treatment',ci.tax_treatment,
        'instruction_kind',ci.instruction_kind,'direction',ci.direction,'payroll_stage',ci.payroll_stage,
        'resolution_ref',ci.resolution_ref,'explanation',ci.explanation,
        'allocated_target_ex_vat',cr.allocated_target_ex_vat::text,'allocated_target_vat',cr.allocated_target_vat::text,
        'allocated_target_inc_vat',cr.allocated_target_inc_vat::text) end) row_value
      from private.bpay_next_transfer_member m
      left join private.bpay_next_run_line l on l.id=m.run_line_id and l.run_worker_id=m.run_worker_id
      left join private.bpay_next_approved_line a on a.id=l.approved_line_id and a.revision_id=l.captured_revision_id
      left join private.bpay_next_run_case_instruction ci on ci.id=m.case_instruction_id and ci.run_worker_id=m.run_worker_id
      left join private.bpay_next_case_allocation_result cr on cr.id=m.case_allocation_result_id and cr.instruction_id=ci.id
      where m.transfer_id=$1 and m.member_no>coalesce($7::bigint,0)
      order by m.member_no limit $12$query$;
  elsif p_kind='SHIFTS' then
    v_sql:=$query$select to_jsonb(page) row_value from (
      select s.id shift_detail_id,s.detail_no,s.work_date,s.shift_start_at,s.shift_end_at,s.shift_start_local,
        s.shift_end_local,s.shift_overnight,s.submitted_minutes,s.approved_minutes,s.approved_hours::text,s.detail_label,
        s.segment_pay_ex_vat::text,s.pay_excluded,s.hours_day::text,s.hours_night::text,s.hours_sat::text,s.hours_sun::text,s.hours_bh::text
      from private.bpay_next_shift_detail s where s.approved_line_id=$4 and s.detail_no>coalesce($8::integer,0)
      order by s.detail_no limit $12) page$query$;
  elsif p_kind='BREAKS' then
    if not exists(select 1 from private.bpay_next_shift_detail where id=p_shift_detail_id and approved_line_id=v_approved_line) then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_BREAK_NOT_IN_LINE';
    end if;
    v_sql:=$query$select to_jsonb(page) row_value from (
      select b.id break_detail_id,b.break_no,b.break_start_at,b.break_end_at,b.break_start_local,b.break_end_local,b.break_minutes
      from private.bpay_next_break_detail b where b.shift_detail_id=$5 and b.break_no>coalesce($8::integer,0)
      order by b.break_no limit $12) page$query$;
  elsif p_kind='RATE_DETAILS' then
    v_sql:=$query$select to_jsonb(page) row_value from (
      select d.id rate_detail_id,d.bucket,d.approved_hours::text,d.source_pay_rate::text
      from private.bpay_next_rate_detail d where d.approved_line_id=$4 and ($9::text is null or d.bucket>$9)
      order by d.bucket limit $12) page$query$;
  else
    v_sql:=$query$select to_jsonb(page) row_value from (
      select s.id rate_schedule_id,s.rate_family,s.rate_code,s.unit_label,s.paye_rate::text,s.umbrella_rate::text,s.charge_rate::text
      from private.bpay_next_rate_schedule s where s.revision_id=$3
        and ($10::text is null or (s.rate_family,s.rate_code)>($10,$11))
      order by s.rate_family,s.rate_code limit $12) page$query$;
  end if;
  for v_row in execute v_sql using v_transfer.id,v_worker.id,v_revision,v_approved_line,p_shift_detail_id,
    p_after_work_id,p_after_member_no,coalesce(p_after_detail_no,p_after_break_no),p_after_bucket,p_after_rate_family,p_after_rate_code,p_limit
  loop
    if v_bytes+octet_length(v_row.row_value::text)+1>120000 then
      if v_count=0 then raise exception using errcode='54000',message='BPAY_NEXT_ADVICE_ROW_TOO_LARGE';end if;
      v_more:=true;exit;
    end if;
    v_bytes:=v_bytes+octet_length(v_row.row_value::text)+1;
    v_rows:=v_rows||jsonb_build_array(v_row.row_value);v_count:=v_count+1;
  end loop;
  return jsonb_build_object('rows',v_rows,'complete',not(v_more or v_count=p_limit));
end
$function$;

ALTER FUNCTION public.bpay_next_original_csv_advice_page_v1(uuid,uuid,text,uuid,uuid,uuid,uuid,bigint,integer,integer,text,text,text,integer) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION public.bpay_next_original_csv_advice_page_v1(uuid,uuid,text,uuid,uuid,uuid,uuid,bigint,integer,integer,text,text,text,integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.bpay_next_original_csv_advice_page_v1(uuid,uuid,text,uuid,uuid,uuid,uuid,bigint,integer,integer,text,text,text,integer) TO service_role;

-- F-05-D10 successor of supabase/repeatable/04102026_0260_banking_pay_next_simple_cancel_v1.sql
create or replace function private.bpay_next_simple_cancel_block_v1(
  p_run_worker_id uuid,p_allow_building boolean default false
) returns text
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_count integer;
begin
  select * into strict v_worker from private.bpay_next_run_worker
    where id=p_run_worker_id;
  -- Only a no-case, never-executed frozen UMB worker may use SIMPLE_CANCEL.
  -- No current Candidate/rate/Source lookup and no UMB NET/CSV admission.
  if v_worker.target_pay_channel='UMBRELLA' then
    if v_worker.status<>'READY' or v_worker.target_umbrella_id is null
       or v_worker.target_umbrella_vat_chargeable is null
       or v_worker.gross_ex_vat<0 or v_worker.gross_vat<0 or v_worker.gross_inc_vat<0
       or v_worker.gross_inc_vat<>v_worker.gross_ex_vat+v_worker.gross_vat
       or (v_worker.target_umbrella_vat_chargeable is false and v_worker.gross_vat<>0) then
      return 'BPAY_NEXT_CANCEL_GROUP_NOT_SIMPLE_DRAFT';
    end if;
    if v_worker.realised_effect_count<>0 or v_worker.financial_resolution_count<>0
       or not exists(select 1 from private.bpay_next_worker_control c
         where c.candidate_id=v_worker.candidate_id and c.pending_outcome_count=0) then
      return 'BPAY_NEXT_CANCEL_REALISED_OR_PENDING';
    end if;
    if v_worker.case_selection_revision<>0 or v_worker.active_case_hold_count<>0
       or v_worker.case_instruction_count<>0 or v_worker.case_allocated_count<>0
       or v_worker.case_pending_binding_count<>0
       or exists(select 1 from private.bpay_next_case_hold h where h.run_worker_id=v_worker.id) then
      return 'BPAY_NEXT_CANCEL_CASE_GROUP_UNSUPPORTED';
    end if;
    -- UMB uses frozen gross-inc cash, never a payroll NET request/value.
    if v_worker.net_request_revision is distinct from 0
       or v_worker.net_projection_revision not in (0,1)
       or v_worker.net_projection_revision is null
       or v_worker.entered_paye_net is not null
       or exists(select 1 from private.bpay_next_paye_net_request n where n.run_worker_id=v_worker.id) then
      return 'BPAY_NEXT_CANCEL_PROJECTION_UNSUPPORTED';
    end if;
    select count(*) into v_count from
      (select 1 from private.bpay_next_net_projection p
       where p.run_worker_id=v_worker.id order by p.projection_no limit 2) p;
    if v_count>1 or v_count is distinct from v_worker.net_projection_revision then
      return 'BPAY_NEXT_CANCEL_PROJECTION_UNSUPPORTED';
    end if;
    if v_count=1 then
      select p.* into strict v_projection from private.bpay_next_net_projection p
        where p.run_worker_id=v_worker.id;
      if (v_projection.run_worker_id,v_projection.projection_no,v_projection.input_kind,
          v_projection.gross_ex_vat,v_projection.gross_vat,v_projection.gross_inc_vat,
          v_projection.cash_amount,v_projection.accepted_recoveries,
          v_projection.accepted_gross_additions,v_projection.accepted_gross_deductions,
          v_projection.accepted_net_additions)
         is distinct from
         (v_worker.id,1::bigint,'UMBRELLA'::text,
          v_worker.gross_ex_vat,v_worker.gross_vat,v_worker.gross_inc_vat,
          v_worker.gross_inc_vat,0::numeric,0::numeric,0::numeric,0::numeric)
         or v_projection.entered_paye_net is not null
         or v_projection.request_command_id is not null
         or v_projection.retired_at_utc is not null then
        return 'BPAY_NEXT_CANCEL_PROJECTION_UNSUPPORTED';
      end if;
    end if;
    -- One original transfer only. Intake may precede its earlier builder;
    -- the unchanged claimant waits, and first ordered page disallows BUILDING.
    select count(*) into v_count from
      (select 1 from private.bpay_next_transfer t
       where t.run_worker_id=v_worker.id order by t.transfer_no limit 2) t;
    if v_count>1 then return 'BPAY_NEXT_CANCEL_MULTI_TRANSFER_UNSUPPORTED';end if;
    if v_count=1 then
      select t.* into strict v_transfer from private.bpay_next_transfer t
        where t.run_worker_id=v_worker.id;
      if v_projection.id is null
         or (v_transfer.run_worker_id,v_transfer.candidate_id,v_transfer.transfer_no,
             v_transfer.beneficiary_kind,v_transfer.beneficiary_id,
             v_transfer.projection_id,v_transfer.cash_amount,v_transfer.execution_kind)
            is distinct from
            (v_worker.id,v_worker.candidate_id,1::bigint,
             'UMBRELLA'::text,v_worker.target_umbrella_id,
             v_projection.id,v_projection.cash_amount,'BANK'::text)
         or v_transfer.cash_amount<=0
         or v_transfer.original_transfer_id is not null
         or v_transfer.return_cash_id is not null then
        return 'BPAY_NEXT_CANCEL_REISSUE_OR_NON_CANDIDATE_UNSUPPORTED';
      end if;
      if v_transfer.status not in ('MEMBERS_READY','DRAFT','SCHEDULED')
         and not (p_allow_building is true and v_transfer.status='BUILDING') then
        return 'BPAY_NEXT_CANCEL_TRANSFER_PROTECTED';
      end if;
      if v_transfer.account_approval_ref is not null
         or exists(select 1 from private.bpay_next_csv_instruction i where i.transfer_id=v_transfer.id)
         or exists(select 1 from private.bpay_next_transfer_outcome o where o.transfer_id=v_transfer.id)
         or exists(select 1 from private.bpay_next_internal_receipt r where r.transfer_id=v_transfer.id) then
        return 'BPAY_NEXT_CANCEL_INSTRUCTION_OR_OUTCOME_PROTECTED';
      end if;
    end if;
    return null;
  end if;
  if v_worker.case_selection_revision>0 then
    return private.bpay_next_case_cancel_block_v1(p_run_worker_id,p_allow_building);
  end if;
  if v_worker.status<>'READY' or v_worker.target_pay_channel<>'PAYE'
     or v_worker.target_umbrella_id is not null or v_worker.gross_vat<>0
     or v_worker.gross_inc_vat<0
     or v_worker.net_request_revision not between 0 and 1
     or v_worker.net_projection_revision not between 0 and 1
     or v_worker.net_projection_revision>v_worker.net_request_revision then
    return 'BPAY_NEXT_CANCEL_GROUP_NOT_SIMPLE_DRAFT';
  end if;
  if v_worker.realised_effect_count<>0
     or v_worker.financial_resolution_count<>0
     or exists(select 1 from private.bpay_next_worker_control c
               where c.candidate_id=v_worker.candidate_id
                 and c.pending_outcome_count<>0) then
    return 'BPAY_NEXT_CANCEL_GROUP_REALISED_OR_PENDING_OUTCOME';
  end if;
  if v_worker.case_selection_revision<>0
     or exists(select 1 from private.bpay_next_case_hold h
               where h.run_worker_id=v_worker.id) then
    return 'BPAY_NEXT_CANCEL_CASE_GROUP_UNSUPPORTED';
  end if;
  if exists(select 1 from private.bpay_next_net_projection p
            where p.run_worker_id=v_worker.id
              and (p.projection_no<>1 or p.input_kind<>'PAYE_MANUAL'
                   or p.accepted_recoveries<>0
                   or p.retired_at_utc is not null)) then
    return 'BPAY_NEXT_CANCEL_PROJECTION_UNSUPPORTED';
  end if;
  if p_allow_building is not true
     and v_worker.net_request_revision<>v_worker.net_projection_revision then
    return 'BPAY_NEXT_CANCEL_PROJECTION_PENDING';
  end if;
  -- The existing original builder admits at most one original transfer.
  -- LIMIT 2 is deliberate: a broader/reissue group is not this owner's slice.
  select count(*) into v_count from
    (select 1 from private.bpay_next_transfer t
     where t.run_worker_id=v_worker.id order by t.transfer_no limit 2) t;
  if v_count>1 then return 'BPAY_NEXT_CANCEL_MULTI_TRANSFER_UNSUPPORTED'; end if;
  if v_count=1 then
    select * into strict v_transfer from private.bpay_next_transfer
      where run_worker_id=v_worker.id;
    if v_transfer.original_transfer_id is not null
       or v_transfer.return_cash_id is not null
       or v_transfer.projection_id is null
       or v_transfer.candidate_id<>v_worker.candidate_id
       or v_transfer.beneficiary_kind<>'CANDIDATE'
       or v_transfer.beneficiary_id<>v_worker.candidate_id then
      return 'BPAY_NEXT_CANCEL_REISSUE_OR_NON_CANDIDATE_UNSUPPORTED';
    end if;
    if v_transfer.status not in ('MEMBERS_READY','DRAFT','SCHEDULED')
       and not (p_allow_building is true and v_transfer.status='BUILDING') then
      return 'BPAY_NEXT_CANCEL_TRANSFER_PROTECTED';
    end if;
    if v_transfer.account_approval_ref is not null
       or exists(select 1 from private.bpay_next_csv_instruction i
                 where i.transfer_id=v_transfer.id)
       or exists(select 1 from private.bpay_next_transfer_outcome o
                 where o.transfer_id=v_transfer.id)
       or exists(select 1 from private.bpay_next_internal_receipt r
                 where r.transfer_id=v_transfer.id) then
      return 'BPAY_NEXT_CANCEL_INSTRUCTION_OR_OUTCOME_PROTECTED';
    end if;
  end if;
  return null;
end
$function$;

ALTER FUNCTION private.bpay_next_simple_cancel_block_v1(uuid,boolean) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_simple_cancel_block_v1(uuid,boolean) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D09 successor of supabase/repeatable/04102026_0270_banking_pay_next_financial_intake_service_v1.sql
create or replace function public.bpay_next_financial_intake_v1(
  p_actor_user_id uuid,p_action text,p_args jsonb
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_keys text[];
  v_key text;
  v_command_id uuid;
  v_worker_id uuid;
  v_transfer_id uuid;
  v_instruction_id uuid;
  v_return_cash_id uuid;
  v_run_id uuid;
  v_amount numeric;
  v_occurred_at timestamptz;
  v_result jsonb;
  v_output jsonb;
  v_sequence text;
  v_projection_revision bigint;
  v_case_selection_revision bigint;
  v_case_component_id uuid;
  v_component_revision bigint;
begin
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
      nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role'
     or p_actor_user_id is null
     or not exists(select 1 from public.tms_users u
                   where u.id=p_actor_user_id and u.is_active is true
                     and u.role::text='admin' for share) then
    raise exception using errcode='42501',message='BPAY_NEXT_COMMAND_FORBIDDEN';
  end if;
  if not exists(select 1 from private.bpay_next_module_control m
                where m.id=1 and m.active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  if p_action is null or p_action not in
      ('PAYE_NET','CASE_PAYOUT','TRANSFER_BEGIN','CANCEL_REQUEST','CASH_REISSUE','REISSUE_CANCEL',
       'CSV_ISSUE','CSV_SETTLEMENT','CSV_RETURN','INTERNAL_SETTLE','PREPARATION_EXPIRE','WRITE_OFF')
     or p_args is null or pg_catalog.jsonb_typeof(p_args) is distinct from 'object'
     or pg_catalog.octet_length(p_args::text)>2048 then
    raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
  end if;
  v_keys:=case p_action
    when 'WRITE_OFF' then array['command_id','case_component_id','expected_component_revision','scope','reason']
      || case when p_args->>'scope'='AMOUNT' then array['amount'] else array[]::text[] end
    when 'PAYE_NET' then array['command_id','run_worker_id','entered_paye_net']
      || case when p_args ? 'expected_projection_revision' then array['expected_projection_revision'] else array[]::text[] end
    when 'CASE_PAYOUT' then array['command_id','run_worker_id','expected_projection_revision']
    when 'TRANSFER_BEGIN' then array['command_id','run_worker_id']
    when 'CANCEL_REQUEST' then array['command_id','run_worker_id']
      || case when p_args ? 'run_id' or p_args ? 'pay_channel'
        then array['run_id','pay_channel'] else array[]::text[] end
    when 'CASH_REISSUE' then array['command_id','return_cash_id']
    when 'REISSUE_CANCEL' then array['command_id','transfer_id']
    when 'CSV_ISSUE' then array['instruction_id','transfer_id']
    when 'INTERNAL_SETTLE' then array['command_id','transfer_id']
    when 'PREPARATION_EXPIRE' then array['command_id','run_id','expected_deadline']
    else array['command_id','transfer_id','receipt_id','amount','occurred_at'] end;
  if (select count(*) from pg_catalog.jsonb_object_keys(p_args))<>pg_catalog.array_length(v_keys,1)
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_args) k
               where not(k=any(v_keys))) then
    raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
  end if;
  foreach v_key in array v_keys loop
    if pg_catalog.jsonb_typeof(p_args->v_key) is distinct from 'string' then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
    if v_key in ('command_id','run_worker_id','transfer_id','instruction_id','return_cash_id','run_id','case_component_id')
       and (p_args->>v_key)!~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
    if v_key='pay_channel' and (p_args->>v_key) not in ('PAYE','UMBRELLA') then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
  end loop;
  v_command_id:=(p_args->>'command_id')::uuid;
  v_worker_id:=(p_args->>'run_worker_id')::uuid;
  v_transfer_id:=(p_args->>'transfer_id')::uuid;
  v_instruction_id:=(p_args->>'instruction_id')::uuid;
  v_return_cash_id:=(p_args->>'return_cash_id')::uuid;
  if p_action='WRITE_OFF' then
    v_case_component_id:=(p_args->>'case_component_id')::uuid;
    if (p_args->>'expected_component_revision')!~'^[1-9][0-9]{0,18}$'
       or (p_args->>'expected_component_revision')::numeric>9223372036854775807 then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
    v_component_revision:=(p_args->>'expected_component_revision')::bigint;
  end if;
  if p_action='PREPARATION_EXPIRE' then
    v_run_id:=(p_args->>'run_id')::uuid;
    if (p_args->>'expected_deadline')!~
        '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,6})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$' then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
    v_occurred_at:=(p_args->>'expected_deadline')::timestamptz;
    if not pg_catalog.isfinite(v_occurred_at) then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
  end if;
  if p_args ? 'expected_projection_revision' then
    if (p_args->>'expected_projection_revision')!~'^(0|[1-9][0-9]{0,18})$'
       or (p_args->>'expected_projection_revision')::numeric>=9223372036854775807 then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
    v_projection_revision:=(p_args->>'expected_projection_revision')::bigint;
  end if;
  if p_action in ('PAYE_NET','CSV_SETTLEMENT','CSV_RETURN') then
    v_key:=case when p_action='PAYE_NET' then 'entered_paye_net' else 'amount' end;
    -- Current money columns are numeric(18,2). Explicit finite, ordinary
    -- decimal syntax prevents exponent/NaN, narrowing and JSON-number coercion.
    if (p_args->>v_key)!~'^(0|[1-9][0-9]{0,15})([.][0-9]{1,2})?$' then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
    v_amount:=(p_args->>v_key)::numeric;
    if p_action<>'PAYE_NET' and v_amount<=0 then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
  end if;
  if p_action in ('CSV_SETTLEMENT','CSV_RETURN') then
    if pg_catalog.octet_length(p_args->>'receipt_id') not between 1 and 256
       or (p_args->>'occurred_at')!~
         '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,6})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$' then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
    v_occurred_at:=(p_args->>'occurred_at')::timestamptz;
    if not pg_catalog.isfinite(v_occurred_at) then
      raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
    end if;
  end if;

  -- Fixed branches and exact typed IDs only. No dynamic identifier, query,
  -- caller actor, arbitrary RPC, live finance/history reconstruction or drain.
  case p_action
    when 'WRITE_OFF' then
      v_result:=private.bpay_next_accept_write_off_v1(v_command_id,v_case_component_id,p_actor_user_id,
        v_component_revision,p_args->>'scope',p_args->>'amount',p_args->>'reason');
      v_output:=pg_catalog.jsonb_build_object('command_id',v_result->>'command_id',
        'case_id',v_result->>'case_id','case_component_id',v_result->>'case_component_id',
        'sequence',v_result->>'sequence','phase',v_result->>'phase','requested_scope',v_result->>'requested_scope',
        'applied_amount',v_result->>'applied_amount','remaining_amount',v_result->>'remaining_amount',
        'protected_amount',v_result->>'protected_amount','event_id',v_result->>'event_id',
        'issue_code',v_result->>'issue_code','replay',v_result->'replay');
    when 'PREPARATION_EXPIRE' then
      -- NULL clock selects the real server clock AFTER acquiring the header.
      -- Office cannot supply SYSTEM authority, now, or a renewal duration.
      v_result:=private.bpay_next_accept_preparation_expiry_v1(
        v_command_id,v_run_id,p_actor_user_id,v_occurred_at,null);
      v_output:=pg_catalog.jsonb_build_object(
        'command_id',v_result->>'command_id','run_id',v_result->>'run_id',
        'sequence',v_result->>'sequence','phase',v_result->>'phase',
        'expected_candidates',v_result->>'expected_candidates',
        'completed_candidates',v_result->>'completed_candidates',
        'replay',v_result->'replay');
    when 'PAYE_NET' then
      -- Route by the worker's FROZEN selection, never by live Candidate cases.
      -- Explicit prior projection protects resaves from overwriting a newer one.
      select w.case_selection_revision into strict v_case_selection_revision
        from private.bpay_next_run_worker w where w.id=v_worker_id;
      if v_case_selection_revision>0 then
        if v_projection_revision is null then
          raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
        end if;
        v_result:=private.bpay_next_accept_case_paye_net_v1(
          v_command_id,v_worker_id,p_actor_user_id,v_amount,v_projection_revision);
      else
        if v_projection_revision is not null then
          raise exception using errcode='22023',message='BPAY_NEXT_COMMAND_REQUEST_INVALID';
        end if;
        v_result:=private.bpay_next_accept_simple_paye_net_v1(v_command_id,v_worker_id,v_amount);
      end if;
      v_output:=pg_catalog.jsonb_build_object(
        'command_id',v_command_id,'run_worker_id',v_worker_id,
        'sequence',v_result->>'sequence','request_no',v_result->>'request_no',
        'phase',v_result->>'phase','replay',v_result->'replay');
    when 'CASE_PAYOUT' then
      v_result:=private.bpay_next_accept_case_payout_projection_v1(
        v_command_id,v_worker_id,p_actor_user_id,v_projection_revision);
      v_output:=pg_catalog.jsonb_build_object(
        'command_id',v_command_id,'run_worker_id',v_worker_id,
        'sequence',v_result->>'sequence','request_no',v_result->>'request_no',
        'phase',v_result->>'phase','replay',v_result->'replay');
    when 'TRANSFER_BEGIN' then
      v_result:=private.bpay_next_begin_simple_transfer_v1(v_command_id,v_worker_id);
      v_output:=pg_catalog.jsonb_build_object(
        'command_id',v_command_id,'run_worker_id',v_worker_id,
        'sequence',v_result->>'sequence','transfer_id',v_result->>'transfer_id',
        'phase',v_result->>'phase','replay',v_result->'replay');
    when 'CANCEL_REQUEST' then
      -- Optional address is strictly paired and independently bound before accepting intent.
      if p_args ? 'run_id' and not exists(select 1 from private.bpay_next_run_worker w
        where w.id=v_worker_id and w.run_id=(p_args->>'run_id')::uuid
          and w.target_pay_channel=p_args->>'pay_channel') then
        raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_CHANNEL_SCOPE_INVALID';
      end if;
      v_result:=private.bpay_next_accept_simple_cancel_v1(v_command_id,v_worker_id);
      v_output:=pg_catalog.jsonb_build_object(
        'command_id',v_command_id,'run_worker_id',v_worker_id,
        'sequence',v_result->>'sequence','phase',v_result->>'phase',
        'cursor',v_result->>'cursor','released_line_count',v_result->>'released_line_count',
        'blocked_code',v_result->>'blocked_code','replay',v_result->'replay');
    when 'CASH_REISSUE' then
      v_result:=private.bpay_next_receive_simple_reissue_v1(v_command_id,v_return_cash_id,p_actor_user_id);
      select c.agency_sequence::text into strict v_sequence
        from private.bpay_next_command c where c.id=v_command_id and c.command_kind='CASH_REISSUE';
      v_output:=pg_catalog.jsonb_build_object(
        'command_id',v_command_id,'return_cash_id',v_return_cash_id,
        'sequence',v_sequence,'transfer_id',v_result->>'transfer_id',
        'phase',case when v_result->>'transfer_id' is null
          then 'ACCEPTED_PENDING_BUILD' else 'TRANSFER_CREATED' end,
        'replay',v_result->'replay');
    when 'REISSUE_CANCEL' then
      v_result:=private.bpay_next_accept_reissue_cancel_v1(v_command_id,v_transfer_id,p_actor_user_id);
      select r.blocked_code into v_key from private.bpay_next_reissue_cancel_request r where r.command_id=v_command_id;
      v_output:=pg_catalog.jsonb_build_object('command_id',v_command_id,'transfer_id',v_transfer_id,
        'sequence',v_result->>'sequence','phase',v_result->>'phase','blocked_code',v_key,'replay',v_result->'replay');
    when 'CSV_ISSUE' then
      -- A new CSV issue first binds its current approved destination using the
      -- existing owner. Already-issued replay never rebinds or changes bytes.
      -- Both calls use the same transaction and parent run mutex; any issue
      -- permission/state failure rolls the destination preparation back too.
      -- Acquire that mutex BEFORE checking instruction existence: concurrent
      -- same-ID retry must see the first committed issue and skip rebinding.
      select w.run_id into strict v_run_id
        from private.bpay_next_transfer t
        join private.bpay_next_run_worker w on w.id=t.run_worker_id
        where t.id=v_transfer_id;
      perform 1 from private.bpay_next_pay_run where id=v_run_id for update;
      if not exists(select 1 from private.bpay_next_csv_instruction i where i.id=v_instruction_id) then
        perform private.bpay_next_bind_simple_csv_destination_v1(v_transfer_id);
      end if;
      v_result:=private.bpay_next_issue_simple_csv_v1(v_instruction_id,v_transfer_id,p_actor_user_id);
      v_output:=pg_catalog.jsonb_build_object(
        'instruction_id',v_result->>'instruction_id','transfer_id',v_result->>'transfer_id',
        'file_name',v_result->>'file_name','csv_sha256',v_result->>'csv_sha256',
        'csv_text',v_result->>'csv_text','phase','ISSUED_CSV',
        'payment_recorded',v_result->'payment_recorded','replay',v_result->'replay');
    when 'CSV_SETTLEMENT' then
      v_result:=private.bpay_next_receive_simple_csv_settlement_v1(
        v_command_id,v_transfer_id,p_args->>'receipt_id',v_amount,v_occurred_at,p_actor_user_id);
      select c.agency_sequence::text into strict v_sequence
        from private.bpay_next_command c
        where c.id=(v_result->>'command_id')::uuid and c.command_kind='CSV_SETTLEMENT';
      v_output:=pg_catalog.jsonb_build_object(
        'command_id',v_result->>'command_id','transfer_id',v_transfer_id,
        'outcome_id',v_result->>'outcome_id','sequence',v_sequence,
        'posting_complete',v_result->'posting_complete','replay',v_result->'replay',
        'phase',case when (v_result->>'posting_complete')::boolean
          then 'POSTED' else 'ACCEPTED_PENDING_POSTING' end);
    when 'INTERNAL_SETTLE' then
      -- The server creates an internal receipt for an exact zero-cash frozen
      -- envelope. There is no caller amount, bank receipt or CSV instruction.
      v_result:=private.bpay_next_receive_internal_settlement_v1(
        v_command_id,v_transfer_id,p_actor_user_id);
      v_output:=pg_catalog.jsonb_build_object(
        'command_id',v_result->>'command_id','transfer_id',v_result->>'transfer_id',
        'internal_receipt_id',v_result->>'internal_receipt_id','sequence',v_result->>'sequence',
        'posting_complete',v_result->'posting_complete','phase',v_result->>'phase','replay',v_result->'replay');
    when 'CSV_RETURN' then
      v_result:=private.bpay_next_receive_simple_csv_return_v1(
        v_command_id,v_transfer_id,p_args->>'receipt_id',v_amount,v_occurred_at,p_actor_user_id);
      select c.agency_sequence::text into strict v_sequence
        from private.bpay_next_command c
        where c.id=(v_result->>'command_id')::uuid and c.command_kind='CSV_RETURN';
      v_output:=pg_catalog.jsonb_build_object(
        'command_id',v_result->>'command_id','transfer_id',v_transfer_id,
        'outcome_id',v_result->>'outcome_id','sequence',v_sequence,
        'posting_complete',v_result->'posting_complete','replay',v_result->'replay',
        'phase',case when (v_result->>'posting_complete')::boolean
          then 'POSTED' else 'ACCEPTED_PENDING_POSTING' end);
  end case;
  if pg_catalog.jsonb_typeof(v_result->'replay') is distinct from 'boolean'
     or pg_catalog.octet_length(v_output::text)>120000 then
    -- Exception aborts the whole request transaction; no partial issue or
    -- accepted financial request is committed without its bounded receipt.
    raise exception using errcode='54000',message='BPAY_NEXT_COMMAND_RESPONSE_INVALID';
  end if;
  return v_output;
end
$function$;

ALTER FUNCTION public.bpay_next_financial_intake_v1(uuid,text,jsonb) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION public.bpay_next_financial_intake_v1(uuid,text,jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.bpay_next_financial_intake_v1(uuid,text,jsonb) TO service_role;

-- F-05-D08 successor of supabase/repeatable/04102026_0430_banking_pay_next_week_lifecycle_v1.sql
create or replace function private.bpay_next_apply_week_outcome_v1(
  p_job_id uuid,p_return_cash_id uuid default null
) returns void
language plpgsql security definer set search_path=pg_catalog,private,public
as $function$
declare
  v_job private.bpay_next_job%rowtype;
  v_control private.bpay_next_worker_control%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_original private.bpay_next_transfer%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_outcome private.bpay_next_transfer_outcome%rowtype;
  v_settlement private.bpay_next_outcome_request%rowtype;
  v_return private.bpay_next_return_request%rowtype;
  v_cash private.bpay_next_return_cash%rowtype;
  v_week private.bpay_next_worker_week%rowtype;
  v_prior private.bpay_next_worker_week_contribution%rowtype;
  v_run private.bpay_next_pay_run%rowtype;
  v_epoch bigint;v_worker_id uuid;v_candidate uuid;v_transfer_id uuid;
  v_outcome_id uuid;v_posted boolean;v_next_state text;v_payout boolean;
  v_old_resolved numeric;v_unresolved_delta integer:=0;
  v_leg private.bpay_next_destination_group_leg%rowtype;
  v_destination private.bpay_next_net_destination_state%rowtype;
begin
  if p_job_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_WEEK_OUTCOME_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select j.* into strict v_job from private.bpay_next_job j where j.id=p_job_id;
  if v_job.job_kind='CSV_SETTLEMENT' then
    select r.* into strict v_settlement from private.bpay_next_outcome_request r where r.command_id=v_job.command_id;
    v_worker_id:=v_settlement.run_worker_id;v_candidate:=v_settlement.candidate_id;
    v_transfer_id:=v_settlement.transfer_id;v_outcome_id:=v_settlement.outcome_id;
    if p_return_cash_id is not null then
      raise exception using errcode='22023',message='BPAY_NEXT_WEEK_SETTLEMENT_CASH_ARGUMENT_INVALID';
    end if;
  elsif v_job.job_kind='CSV_RETURN' then
    select r.* into strict v_return from private.bpay_next_return_request r where r.command_id=v_job.command_id;
    v_worker_id:=v_return.run_worker_id;v_candidate:=v_return.candidate_id;
    v_transfer_id:=v_return.transfer_id;v_outcome_id:=v_return.outcome_id;
    if p_return_cash_id is null then
      raise exception using errcode='22023',message='BPAY_NEXT_WEEK_RETURN_CASH_REQUIRED';
    end if;
  else raise exception using errcode='23514',message='BPAY_NEXT_WEEK_OUTCOME_JOB_KIND_INVALID';end if;
  -- Same order as the posting caller, also safe for an owner-only first-use
  -- probe: header -> Candidate control -> job -> worker -> transfer/cash -> week.
  select r.* into strict v_run from private.bpay_next_pay_run r
    join private.bpay_next_run_worker w on w.run_id=r.id where w.id=v_worker_id for update of r;
  select c.* into strict v_control from private.bpay_next_worker_control c where c.candidate_id=v_candidate for update;
  select j.* into strict v_job from private.bpay_next_job j where j.id=p_job_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w where w.id=v_worker_id for update;
  select t.* into strict v_transfer from private.bpay_next_transfer t where t.id=v_transfer_id for update;
  select o.* into strict v_outcome from private.bpay_next_transfer_outcome o where o.id=v_outcome_id;
  if v_job.job_kind='CSV_SETTLEMENT' then
    select r.* into strict v_settlement from private.bpay_next_outcome_request r where r.command_id=v_job.command_id;
    v_posted:=v_settlement.posting_complete and v_settlement.posted_member_count=v_transfer.member_count;
  else
    select r.* into strict v_return from private.bpay_next_return_request r where r.command_id=v_job.command_id;
    v_posted:=v_return.posting_complete;
  end if;
  if v_job.module_epoch<>v_epoch or v_job.candidate_id<>v_candidate
     or v_worker.candidate_id<>v_candidate or v_worker.run_id<>v_run.id
     or v_transfer.candidate_id<>v_candidate or v_transfer.run_worker_id<>v_worker.id
     or not ((v_worker.target_pay_channel='PAYE' and v_transfer.beneficiary_kind='CANDIDATE'
         and v_transfer.beneficiary_id=v_candidate)
       or (v_worker.target_pay_channel='UMBRELLA' and v_worker.case_selection_revision=0
         and v_worker.target_umbrella_id is not null and v_transfer.beneficiary_kind='UMBRELLA'
         and v_transfer.beneficiary_id=v_worker.target_umbrella_id))
     or v_outcome.transfer_id<>v_transfer.id or v_outcome.whole_transfer_amount<>v_transfer.cash_amount
     or v_outcome.outcome_kind<>(case when v_job.job_kind='CSV_SETTLEMENT' then 'SETTLED' else 'RETURNED' end)
     or v_posted is not true then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_OUTCOME_SCOPE_INVALID';
  end if;
  select t.* into strict v_original from private.bpay_next_transfer t
    where t.id=coalesce(v_transfer.original_transfer_id,v_transfer.id) for update;
  if v_original.original_transfer_id is not null or v_original.return_cash_id is not null
     or v_original.run_worker_id<>v_worker.id or v_original.candidate_id<>v_candidate
     or v_original.beneficiary_kind is distinct from v_transfer.beneficiary_kind
     or v_original.beneficiary_id is distinct from v_transfer.beneficiary_id then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_ORIGINAL_TRANSFER_INVALID';
  end if;
  if v_job.job_kind='CSV_RETURN' or v_transfer.return_cash_id is not null then
    select c.* into strict v_cash from private.bpay_next_return_cash c
      where c.id=coalesce(p_return_cash_id,v_transfer.return_cash_id) for update;
    if v_cash.original_transfer_id<>v_original.id or v_cash.candidate_id<>v_candidate
       or v_cash.amount_owed<>v_original.cash_amount
       or (v_transfer.return_cash_id is not null and v_transfer.return_cash_id<>v_cash.id) then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_RETURN_CASH_NOT_EXACT';
    end if;
  end if;
  -- The posting transition and this helper commit atomically. A delayed old
  -- DONE helper is readback, not adoption/backfill of its old reissue pointer.
  if v_job.status='DONE' then return;end if;
  if v_job.status<>'LEASED' or v_job.lease_nonce is null
     or v_job.owner_epoch<>v_control.active_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or v_transfer.status not in ('SETTLED','RETURNED')
     or (v_job.job_kind='CSV_RETURN' and v_transfer.status<>'RETURNED') then
    raise exception using errcode='55000',message='BPAY_NEXT_WEEK_OUTCOME_OWNER_INVALID';
  end if;
  if v_worker.target_pay_channel<>'PAYE' then return;end if;
  v_leg:=private.bpay_next_destination_execution_leg_v1(v_original.id);
  if v_leg.transfer_id is not null then
    -- One-off cash is not the Candidate's own weekly take-home contribution.
    -- Its exact receipt still posts its CASE members through the normal owner.
    if v_leg.leg_kind='ONEOFF' then return;end if;
    select n.* into strict v_destination from private.bpay_next_destination_group g
      join private.bpay_next_net_destination_state n on n.state_id=g.net_state_id
      where g.anchor_transfer_id=v_leg.anchor_transfer_id;
  end if;
  select w.* into v_week from private.bpay_next_worker_week w
    where w.candidate_id=v_candidate
      and w.pay_week_start=v_run.pay_date-(extract(isodow from v_run.pay_date)::integer-1) for update;
  select x.* into v_prior from private.bpay_next_worker_week_contribution x
    where x.original_run_worker_id=v_worker.id for update;
  if v_prior.id is null then
    if v_worker.case_selection_revision<>0 then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_CASE_CONTRIBUTION_MISSING';
    end if;
    -- An explicitly unbound no-case READY floor has no contribution. Do not
    -- reconstruct one from a now-paid transfer or guess its earlier earnings.
    raise notice 'BPAY_NEXT_WEEK_ORIGINAL_CONTRIBUTION_UNBOUND';return;
  end if;
  select p.* into strict v_projection from private.bpay_next_net_projection p where p.id=v_original.projection_id;
  if v_week.candidate_id is null or v_prior.candidate_id<>v_candidate
     or v_prior.pay_week_start<>v_week.pay_week_start
     or v_prior.original_pay_date<>v_run.pay_date or v_prior.original_created_at_utc<>v_run.created_at_utc
     or v_prior.original_gross_amount<>v_projection.gross_inc_vat
     or v_prior.accepted_projection_id is distinct from v_projection.id
     or v_prior.accepted_bank_cash is distinct from v_projection.cash_amount
     or v_projection.run_worker_id<>v_worker.id
     or v_original.cash_amount<>(case when v_leg.transfer_id is null then v_projection.cash_amount else v_destination.own_amount end)
     or (v_prior.original_transfer_id is not null and v_prior.original_transfer_id<>v_original.id) then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_ORIGINAL_CONTRIBUTION_NOT_EXACT';
  end if;
  v_payout:=v_projection.input_kind='CASE_PAYOUT';
  if v_payout and (v_prior.basis_kind<>'GROSS_FALLBACK' or v_prior.original_gross_amount<>0
     or v_prior.original_payroll_net is not null or v_prior.eligibility_state<>'EXCLUDED'
     or v_prior.eligible_arranged_amount is distinct from 0::numeric) then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_NON_EARNINGS_BASIS_INVALID';
  end if;
  if v_job.job_kind='CSV_SETTLEMENT' and v_transfer.original_transfer_id is null then
    -- RETURNED may already be RECEIVED: original payroll posting still comes
    -- first. The ordered return owner will later publish the actual cash FK.
    if v_prior.payment_state='PAID' and v_prior.original_transfer_id=v_original.id then return;end if;
    if v_prior.payment_state<>'ARRANGED' or v_prior.eligibility_state='UNBOUND' then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_ORIGINAL_SETTLEMENT_STATE_INVALID';
    end if;
    update private.bpay_next_worker_week_contribution set payment_state='PAID',original_transfer_id=v_original.id,
      contribution_revision=contribution_revision+1,primary_binding_revision=primary_binding_revision+1 where id=v_prior.id;
    update private.bpay_next_worker_week set period_revision=period_revision+1
      where candidate_id=v_candidate and pay_week_start=v_week.pay_week_start;
    return;
  end if;
  if v_prior.original_transfer_id is distinct from v_original.id
     or (v_prior.returned_cash_id is not null and v_prior.returned_cash_id<>v_cash.id) then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_RETURN_ORIGINAL_NOT_PAID';
  end if;
  if v_job.job_kind='CSV_SETTLEMENT' then
    v_next_state:='REISSUED_PAID';
    if v_prior.payment_state='REISSUED_PAID' and v_prior.reissue_transfer_id=v_transfer.id then return;end if;
    if v_prior.payment_state<>'RETURNED_OWED' or v_prior.returned_cash_id is distinct from v_cash.id
       or v_cash.amount_reissued_paid<v_transfer.cash_amount then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_REISSUE_SETTLEMENT_STATE_INVALID';
    end if;
  else
    v_next_state:='RETURNED_OWED';
    if v_prior.payment_state='RETURNED_OWED' and v_prior.returned_cash_id=v_cash.id
       and (v_transfer.original_transfer_id is null or v_prior.reissue_transfer_id=v_transfer.id) then return;end if;
    if (v_transfer.original_transfer_id is null and v_prior.payment_state<>'PAID')
       or (v_transfer.original_transfer_id is not null and
         (v_prior.payment_state<>'REISSUED_PAID' or v_prior.reissue_transfer_id is distinct from v_transfer.id)) then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_RETURN_PAYMENT_STATE_INVALID';
    end if;
  end if;
  v_old_resolved:=coalesce(v_prior.eligible_arranged_amount,0);
  if not v_payout and v_prior.eligibility_state<>'UNBOUND' then v_unresolved_delta:=1;end if;
  update private.bpay_next_worker_week_contribution set payment_state=v_next_state,returned_cash_id=v_cash.id,
    reissue_transfer_id=case when v_transfer.original_transfer_id is not null then v_transfer.id else reissue_transfer_id end,
    eligibility_state=case when v_payout then 'EXCLUDED' else 'UNBOUND' end,
    eligible_arranged_amount=case when v_payout then 0 else null end,
    contribution_revision=contribution_revision+1,primary_binding_revision=primary_binding_revision+1 where id=v_prior.id;
  update private.bpay_next_worker_week set resolved_arranged_take_home=resolved_arranged_take_home-v_old_resolved,
    unresolved_contribution_count=unresolved_contribution_count+v_unresolved_delta,period_revision=period_revision+1
    where candidate_id=v_candidate and pay_week_start=v_week.pay_week_start
      and resolved_arranged_take_home>=v_old_resolved;
  if not found then raise exception using errcode='23514',message='BPAY_NEXT_WEEK_RESOLVED_DELTA_INVALID';end if;
end
$function$;

ALTER FUNCTION private.bpay_next_apply_week_outcome_v1(uuid,uuid) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_apply_week_outcome_v1(uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D19 successor of supabase/repeatable/04102026_0557_banking_pay_next_source_owner_completion_v1.sql
CREATE OR REPLACE FUNCTION public.weekly_source_first_authorise_v1(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_expected_row_signature text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_lock jsonb;
  v_core jsonb;
  v_canonical uuid;
  -- BEGIN A8 SOURCE FIRST AUTHORISE DECLARATIONS
  v_work uuid;
  v_revision uuid;
  v_event uuid;
  -- END A8 SOURCE FIRST AUTHORISE DECLARATIONS
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;

  if p_timesheet_id is null or p_actor_user_id is null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_FIRST_AUTHORISE_REQUEST_INVALID',
      'retryable',false,'reason','TIMESHEET_AND_ACTOR_REQUIRED');
  end if;

  -- One plain read before the gate, because the gate is pinned to a Candidate.
  -- Nothing is written by it and the identity is re-resolved under the locks.
  v_context:=private.bpay_source_authorise_identity_v1(p_timesheet_id);
  if coalesce((v_context->>'ok')::boolean,false) is not true then
    return v_context;
  end if;

  -- BEGIN QUERY V2 FIRST AUTHORISE ADMISSION
  -- Admit before the first Source/Candidate lock; contention remains exact
  -- 55P03, not a financial REVIEW or an automatic owner retry.
  perform private.weekly_source_pay_query_admit_v2();
  -- END QUERY V2 FIRST AUTHORISE ADMISSION

  v_lock:=private.bpay_source_authorise_lock_v1(
    (v_context->>'candidate_id')::uuid,p_timesheet_id,pg_catalog.gen_random_uuid());
  if coalesce((v_lock->>'ok')::boolean,false) is not true then
    return v_lock;
  end if;

  select (family_element.value->>'canonical_timesheet_id')::uuid
    into v_canonical
  from pg_catalog.jsonb_array_elements(coalesce(v_lock->'families','[]'::jsonb))
    as family_element(value)
  where (family_element.value->>'requested_timesheet_id')::uuid=p_timesheet_id;

  if p_expected_timesheet_id is not null
     and p_expected_timesheet_id is distinct from v_canonical then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION',
      'retryable',false,'timesheet_id',p_timesheet_id,
      'canonical_timesheet_id',v_canonical);
  end if;

  v_core:=private.weekly_source_first_authorise_core_v1(
    p_timesheet_id,p_expected_row_signature,p_actor_user_id,v_lock);
  -- BEGIN A8 SOURCE FIRST AUTHORISE NEXT TAIL
  -- Capture only after the real outer first-authorise owner succeeds. The
  -- unchanged private core also runs inside two-root head publication and must
  -- never publish an intermediate B revision.
  if coalesce((v_core->>'ok')::boolean,false) is true
     and (select active_owner from private.bpay_next_module_control
          where id=1)='NEXT' then
    v_event:=(v_core->>'root_authorisation_id')::uuid;
    select s.work_id,s.revision_id into strict v_work,v_revision
      from private.bpay_next_stage_source_current_v1(
        p_timesheet_id,v_event,null) s;
    perform * from private.bpay_next_publish_source_staged_pair_v1(
      array[v_work],array[v_revision],array[v_event]);
    -- Metadata only, after the real outer stage/publication; no position or
    -- financial seed while the queued POSITION_APPLY is still incomplete.
    perform * from private.bpay_next_initial_tsfin_bind_v1(v_event);
  end if;
  -- END A8 SOURCE FIRST AUTHORISE NEXT TAIL
  return v_core||pg_catalog.jsonb_build_object('gate',v_lock->>'gate');
end;
$function$;

ALTER FUNCTION public.weekly_source_first_authorise_v1(uuid,uuid,text,uuid) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION public.weekly_source_first_authorise_v1(uuid,uuid,text,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.weekly_source_first_authorise_v1(uuid,uuid,text,uuid) TO service_role;

-- F-05-D18 successor of supabase/repeatable/04102026_0575_banking_pay_next_preparation_service_v1.sql
create or replace function private.bpay_next_preparation_args_v1(p_args jsonb,p_keys text[])
returns void language plpgsql security invoker
set search_path=pg_catalog
as $function$
declare v_key text;v_type text;v_text text;
begin
  if p_args is null or pg_catalog.jsonb_typeof(p_args) is distinct from 'object'
    or pg_catalog.octet_length(p_args::text)>32768
    or (select count(*) from pg_catalog.jsonb_object_keys(p_args))<>pg_catalog.cardinality(p_keys)
    or exists(select 1 from pg_catalog.jsonb_object_keys(p_args) k where not(k=any(p_keys))) then
    raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
  end if;
  foreach v_key in array p_keys loop
    v_type:=pg_catalog.jsonb_typeof(p_args->v_key);v_text:=p_args->>v_key;
    if v_key in ('choices','approved_line_ids','component_ids','selected') then
      if v_type is distinct from 'array' or pg_catalog.jsonb_array_length(p_args->v_key) not between 1 and 100 then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    elsif v_key='limit' then
      if v_type is distinct from 'number' or v_text!~'^[0-9]{1,3}$' or v_text::integer not between 1 and 100 then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    elsif v_key like 'after_%' and v_type='null' then
      continue;
    elsif v_type is distinct from 'string' then
      raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
    elsif v_key like '%_id' then
      if v_text!~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    elsif v_key in ('pay_date','after_week') then
      if v_text!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or not pg_catalog.isfinite(v_text::date)
        or v_text::date::text<>v_text then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    elsif v_key='pay_channel' then
      if v_text not in ('PAYE','UMBRELLA') then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    elsif v_key='after_bucket' then
      if v_text not in ('DAY','NIGHT','SAT','SUN','BH') then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    else
      if v_text!~'^(0|[1-9][0-9]{0,18})$' or v_text::numeric>9223372036854775807
        or (v_key in ('page_no','selection_revision','review_revision') and v_text='0') then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    end if;
  end loop;
end
$function$;

ALTER FUNCTION private.bpay_next_preparation_args_v1(jsonb,text[]) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_preparation_args_v1(jsonb,text[]) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D18 successor of supabase/repeatable/04102026_0575_banking_pay_next_preparation_service_v1.sql
create or replace function public.bpay_next_preparation_intake_v1(p_actor_user_id uuid,p_action text,p_args jsonb)
returns jsonb language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_keys text[];v_run uuid;v_work uuid;v_revision uuid;v_candidate uuid;v_result jsonb;v_output jsonb;
  v_ids uuid[];v_selected boolean[];v_entry jsonb;v_header private.bpay_next_pay_run%rowtype;
begin
  perform private.bpay_next_preparation_authority_v1(p_actor_user_id);
  v_keys:=case p_action
    when 'CREATE' then array['run_id','pay_date']
    when 'WORK_PAGE' then array['run_id','page_no','choices']
    when 'COMPONENT_PAGE' then array['run_id','work_id','expected_revision_id','page_no','approved_line_ids']
    when 'COMPONENT_SEAL' then array['run_id','work_id','expected_revision_id','expected_pages','expected_count']
    when 'CASE_PAGE' then array['run_id','candidate_id','selection_revision','page_no','request_id','component_ids','selected']
    when 'CASE_SEAL' then array['run_id','candidate_id','selection_revision','expected_pages','expected_items']
    when 'SEAL_ENQUEUE' then array['run_id','command_id','expected_pages','expected_count']
    when 'REVIEW' then array['run_id']
    when 'CONFIRM' then array['run_id','review_revision'] else null end;
  if v_keys is null then raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';end if;
  perform private.bpay_next_preparation_args_v1(p_args,v_keys);
  v_run:=(p_args->>'run_id')::uuid;v_work:=(p_args->>'work_id')::uuid;
  v_revision:=(p_args->>'expected_revision_id')::uuid;v_candidate:=(p_args->>'candidate_id')::uuid;
  if p_action in ('COMPONENT_PAGE','CASE_PAGE') then
    for v_entry in select value from pg_catalog.jsonb_array_elements(
      p_args->case when p_action='CASE_PAGE' then 'component_ids' else 'approved_line_ids' end) loop
      if pg_catalog.jsonb_typeof(v_entry) is distinct from 'string'
        or (v_entry#>>'{}')!~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
      v_ids:=pg_catalog.array_append(v_ids,(v_entry#>>'{}')::uuid);
    end loop;
    if p_action='CASE_PAGE' then
      if pg_catalog.jsonb_array_length(p_args->'selected')<>pg_catalog.cardinality(v_ids) then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
      for v_entry in select value from pg_catalog.jsonb_array_elements(p_args->'selected') loop
        if pg_catalog.jsonb_typeof(v_entry) is distinct from 'boolean' then
          raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
        end if;
        v_selected:=pg_catalog.array_append(v_selected,(v_entry#>>'{}')::boolean);
      end loop;
    end if;
  end if;
  case p_action
  when 'CREATE' then
    v_result:=private.bpay_next_create_preparation_v1(v_run,p_actor_user_id,(p_args->>'pay_date')::date);
    select r.* into strict v_header from private.bpay_next_pay_run r where r.id=v_run;
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'status',v_result->>'status',
      'selection_state',v_result->>'selection_state','selection_count',v_header.selection_count::text,
      'selected_candidate_count',v_header.selected_candidate_count::text);
  when 'WORK_PAGE' then
    v_output:=private.bpay_next_append_work_choices_v1(v_run,(p_args->>'page_no')::bigint,p_args->'choices');
  when 'COMPONENT_PAGE' then
    v_output:=private.bpay_next_append_component_selection_page_v1(v_run,v_work,v_revision,(p_args->>'page_no')::bigint,v_ids);
  when 'COMPONENT_SEAL' then
    v_output:=private.bpay_next_seal_component_selection_v1(v_run,v_work,v_revision,
      (p_args->>'expected_pages')::bigint,(p_args->>'expected_count')::bigint);
  when 'CASE_PAGE' then
    v_result:=private.bpay_next_append_case_selection_page_v1(v_run,v_candidate,(p_args->>'selection_revision')::bigint,
      (p_args->>'page_no')::bigint,(p_args->>'request_id')::uuid,v_ids,v_selected);
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'candidate_id',v_candidate,
      'selection_revision',p_args->>'selection_revision','page_no',v_result->>'page_no',
      'item_count',v_result->>'item_count','replay',v_result->'replay');
  when 'CASE_SEAL' then
    v_result:=private.bpay_next_seal_case_selection_v1(v_run,v_candidate,(p_args->>'selection_revision')::bigint,
      (p_args->>'expected_pages')::bigint,(p_args->>'expected_items')::bigint);
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'candidate_id',v_candidate,
      'selection_revision',v_result->>'selection_revision','sealed',v_result->'sealed',
      'selected_count',v_result->>'selected_count','excluded_count',v_result->>'excluded_count','replay',v_result->'replay');
  when 'SEAL_ENQUEUE' then
    perform private.bpay_next_seal_selection_v1(v_run,(p_args->>'expected_pages')::bigint,(p_args->>'expected_count')::bigint);
    v_result:=private.bpay_next_enqueue_preparation_v1(v_run,(p_args->>'command_id')::uuid);
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'command_id',v_result->>'command_id',
      'agency_sequence',v_result->>'agency_sequence','replay',v_result->'replay');
  when 'REVIEW' then
    v_result:=private.bpay_next_review_simple_run_v1(v_run);
    select r.* into strict v_header from private.bpay_next_pay_run r where r.id=v_run;
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'phase',v_result->>'phase','reason',v_result->>'reason',
      'review_revision',v_header.review_revision::text,'all_ready',v_result->'all_ready',
      'replay',coalesce(v_result->'replay','false'::jsonb));
  when 'CONFIRM' then
    v_result:=private.bpay_next_confirm_simple_run_v1(v_run,(p_args->>'review_revision')::bigint);
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'phase',v_result->>'phase',
      'review_revision',v_result->>'review_revision','replay',v_result->'replay','drafts',v_result->'drafts');
  end case;
  if pg_catalog.octet_length(v_output::text)>120000 then
    raise exception using errcode='54000',message='BPAY_NEXT_PREPARATION_RESPONSE_TOO_LARGE';
  end if;
  return v_output;
end
$function$;

ALTER FUNCTION public.bpay_next_preparation_intake_v1(uuid,text,jsonb) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION public.bpay_next_preparation_intake_v1(uuid,text,jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.bpay_next_preparation_intake_v1(uuid,text,jsonb) TO service_role;

-- F-05-D18 successor of supabase/repeatable/04102026_0575_banking_pay_next_preparation_service_v1.sql
create or replace function public.bpay_next_preparation_page_v1(p_actor_user_id uuid,p_kind text,p_args jsonb)
returns jsonb language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_keys text[];v_work uuid;v_revision uuid;v_line uuid;v_shift uuid;v_limit integer;
  v_row jsonb;v_page jsonb[];v_rows jsonb:='[]'::jsonb;v_n integer:=0;v_complete boolean:=true;
begin
  perform private.bpay_next_preparation_authority_v1(p_actor_user_id);
  v_keys:=case p_kind
    when 'COMPONENTS' then array['work_id','expected_revision_id','after_line_no','limit']
    when 'WORK_CHOICES' then array['run_id','after_work_id','limit']
    when 'SELECTED_COMPONENTS' then array['run_id','work_id','after_selection_no','limit']
    when 'CHANNEL_DRAFTS' then array['run_id']
    when 'CHANNEL_WORKERS' then array['run_id','pay_channel','after_candidate_id','limit']
    when 'CHANNEL_STATUS' then array['run_id','pay_channel','run_worker_id','after_transfer_no','limit']
    when 'WORKERS' then array['run_id','after_candidate_id','limit']
    when 'REVISION_COMPARISON' then array['run_worker_id','after_work_id','limit']
    when 'LINES' then array['run_worker_id','after_line_no','limit']
    when 'SHIFTS' then array['work_id','expected_revision_id','approved_line_id','after_detail_no','limit']
    when 'BREAKS' then array['work_id','expected_revision_id','approved_line_id','shift_detail_id','after_break_no','limit']
    when 'RATES' then array['work_id','expected_revision_id','approved_line_id','after_bucket','limit']
    when 'CURRENT_WORK' then array['candidate_id','after_week','after_work_id','limit']
    when 'CURRENT_CASES' then array['candidate_id','after_case_id','limit']
    when 'CURRENT_STORED_CREDITS' then array['candidate_id','after_legacy_case_id','limit']
    when 'CASE_COMPONENTS' then array['candidate_id','case_id','after_component_ordinal','limit']
    when 'STATUS' then array['run_id','run_worker_id','after_transfer_no','limit']
    when 'RETURN_CASH' then array['run_id','run_worker_id','after_transfer_no','limit'] else null end;
  if v_keys is null then raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';end if;
  perform private.bpay_next_preparation_args_v1(p_args,v_keys);
  v_work:=(p_args->>'work_id')::uuid;v_revision:=(p_args->>'expected_revision_id')::uuid;
  v_line:=(p_args->>'approved_line_id')::uuid;v_shift:=(p_args->>'shift_detail_id')::uuid;v_limit:=(p_args->>'limit')::integer;
  if p_kind='CHANNEL_DRAFTS' then
    return private.bpay_next_channel_drafts_page_v1((p_args->>'run_id')::uuid);
  elsif p_kind='CHANNEL_WORKERS' then
    return private.bpay_next_channel_worker_page_v1((p_args->>'run_id')::uuid,
      p_args->>'pay_channel',(p_args->>'after_candidate_id')::uuid,v_limit);
  elsif p_kind='CHANNEL_STATUS' then
    if p_args->'after_transfer_no'<>'null'::jsonb and ((p_args->>'after_transfer_no')::numeric<1
      or (p_args->>'after_transfer_no')::numeric>2147483647) then
      raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
    end if;
    return private.bpay_next_channel_status_page_v1((p_args->>'run_id')::uuid,p_args->>'pay_channel',
      (p_args->>'run_worker_id')::uuid,(p_args->>'after_transfer_no')::integer,v_limit);
  end if;
  -- Only the two exact factual0580 owners; no competing reader or financial
  -- history/calculation path. CURRENT_WORK does not certify payability.
  if p_kind='CURRENT_WORK' then
    return private.bpay_next_current_work_page_v1((p_args->>'candidate_id')::uuid,
      (p_args->>'after_week')::date,(p_args->>'after_work_id')::uuid,v_limit);
  elsif p_kind='CURRENT_CASES' then
    return private.bpay_next_current_case_page_v1((p_args->>'candidate_id')::uuid,
      (p_args->>'after_case_id')::uuid,v_limit);
  elsif p_kind='CURRENT_STORED_CREDITS' then
    -- Factual, exact-Candidate possible origins only; binding revalidates the
    -- retained creator/component/account facts. This is not pay eligibility.
    -- Closed raw reply includes scan_cursor from the bounded raw window;
    -- filtering can produce an empty nonterminal page without restarting it.
    return private.bpay_next_current_stored_credit_page_v1((p_args->>'candidate_id')::uuid,
      (p_args->>'after_legacy_case_id')::uuid,v_limit);
  elsif p_kind='CASE_COMPONENTS' then
    return private.bpay_next_current_case_component_page_v1((p_args->>'candidate_id')::uuid,
      (p_args->>'case_id')::uuid,(p_args->>'after_component_ordinal')::bigint,v_limit);
  elsif p_kind in ('STATUS','RETURN_CASH') then
    if p_args->'after_transfer_no'<>'null'::jsonb and ((p_args->>'after_transfer_no')::numeric<1
      or (p_args->>'after_transfer_no')::numeric>2147483647) then
      raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
    end if;
    if p_kind='RETURN_CASH' then
      return private.bpay_next_return_cash_page_v1((p_args->>'run_id')::uuid,
        (p_args->>'run_worker_id')::uuid,(p_args->>'after_transfer_no')::integer,v_limit);
    end if;
    return private.bpay_next_worker_status_page_v1((p_args->>'run_id')::uuid,
      (p_args->>'run_worker_id')::uuid,(p_args->>'after_transfer_no')::integer,v_limit);
  end if;
  if p_kind in ('COMPONENTS','SHIFTS','BREAKS','RATES') then
    if not exists(select 1 from private.bpay_next_work w
      join private.bpay_next_work_revision r on r.work_id=w.id and r.id=v_revision
      where w.id=v_work and w.approval_state='APPROVED' and w.current_revision_id=v_revision
        and w.applied_revision_id=v_revision and r.sealed_at_utc is not null and r.approved_at_utc is not null) then
      raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_REVISION_NOT_CURRENT';
    end if;
    if p_kind<>'COMPONENTS' and not exists(select 1 from private.bpay_next_approved_line l where l.id=v_line and l.revision_id=v_revision) then
      raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_LINE_NOT_IN_REVISION';
    end if;
    if p_kind='BREAKS' and not exists(select 1 from private.bpay_next_shift_detail s where s.id=v_shift and s.approved_line_id=v_line) then
      raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_LINE_NOT_IN_REVISION';
    end if;
  elsif p_kind in ('WORK_CHOICES','SELECTED_COMPONENTS') then
    perform 1 from private.bpay_next_pay_run r where r.id=(p_args->>'run_id')::uuid;
    if not found then raise exception using errcode='P0002',message='BPAY_NEXT_PREPARATION_NOT_FOUND';end if;
    if p_kind='SELECTED_COMPONENTS' then
      perform 1 from private.bpay_next_work_choice c where c.run_id=(p_args->>'run_id')::uuid and c.work_id=v_work;
      if not found then raise exception using errcode='P0002',message='BPAY_NEXT_PREPARATION_NOT_FOUND';end if;
    end if;
  end if;
  -- Each branch is a <=100 indexed relational page. A byte boundary ends
  -- before an entire row, never truncates facts; callers resume its last key.
  -- CASE evaluates only its chosen subquery, so unrelated review owners are
  -- never called with NULL scope. Each subquery orders/limits BEFORE packing.
  select case p_kind
    when 'COMPONENTS' then array(
      select pg_catalog.jsonb_build_object(
        'approved_line_id',l.id,'line_no',l.line_no::text,'component_key',l.component_key,'component_kind',l.component_kind,
        'work_date',l.work_date,'source_pay_channel',r.source_pay_channel,'approved_source_ex_vat',l.source_pay_ex_vat::text,
        'realised_source_ex_vat',p.realised_source_ex_vat::text,'held_source_ex_vat',p.held_source_ex_vat::text,
        'residual_source_ex_vat',(l.source_pay_ex_vat-p.realised_source_ex_vat-p.held_source_ex_vat)::text,
        'position_ready',coalesce(p.applied_revision_id=v_revision and p.approved_source_ex_vat=l.source_pay_ex_vat,false)) as value
        from private.bpay_next_approved_line l join private.bpay_next_work_revision r on r.id=l.revision_id
        left join private.bpay_next_position p on p.work_id=v_work and p.component_key=l.component_key
        where l.revision_id=v_revision and l.line_no>coalesce((p_args->>'after_line_no')::bigint,0)
        order by l.line_no,l.id limit v_limit)
    when 'WORK_CHOICES' then array(
      select pg_catalog.jsonb_build_object('work_id',c.work_id,'expected_revision_id',c.expected_revision_id,
        'selection_mode',c.selection_mode,'selection_state',c.selection_state,'page_count',c.page_count::text,'component_count',c.component_count::text)
        from private.bpay_next_work_choice c where c.run_id=(p_args->>'run_id')::uuid
          and ((p_args->>'after_work_id') is null or c.work_id>(p_args->>'after_work_id')::uuid)
        order by c.work_id limit v_limit)
    when 'SELECTED_COMPONENTS' then array(
      select pg_catalog.jsonb_build_object('selection_no',c.selection_no::text,
        'approved_line_id',c.approved_line_id,'expected_revision_id',c.expected_revision_id,'component_key',c.component_key)
        from private.bpay_next_selected_component c where c.run_id=(p_args->>'run_id')::uuid and c.work_id=v_work
          and c.selection_no>coalesce((p_args->>'after_selection_no')::bigint,0)
        order by c.selection_no limit v_limit)
    when 'WORKERS' then array(
      select pg_catalog.jsonb_build_object('run_worker_id',w.run_worker_id,'candidate_id',w.candidate_id,
        'worker_status',w.worker_status,'frozen_ex_vat',w.frozen_ex_vat::text,'frozen_vat',w.frozen_vat::text,
        'frozen_inc_vat',w.frozen_inc_vat::text,'review_issue_code',w.review_issue_code)
        from private.bpay_next_simple_review_worker_page_v1((p_args->>'run_id')::uuid,(p_args->>'after_candidate_id')::uuid,v_limit) w
        order by w.candidate_id limit v_limit)
    when 'REVISION_COMPARISON' then array(
      select pg_catalog.jsonb_build_object('run_work_id',w.run_work_id,'work_id',w.work_id,'original_timesheet_id',w.original_timesheet_id,
        'captured_revision_id',w.captured_revision_id,'current_revision_id',w.current_revision_id,'newer_approval_available',w.newer_approval_available)
        from private.bpay_next_simple_revision_comparison_page_v1((p_args->>'run_worker_id')::uuid,(p_args->>'after_work_id')::uuid,v_limit) w
        order by w.work_id limit v_limit)
    when 'LINES' then array(
      select pg_catalog.jsonb_build_object('run_line_id',l.run_line_id,'line_no',l.line_no::text,
        'original_timesheet_id',l.original_timesheet_id,'captured_revision_id',l.captured_revision_id,'component_key',l.component_key,
        'component_kind',l.component_kind,'work_date',l.work_date,'source_pay_channel',l.source_pay_channel,'target_pay_channel',l.target_pay_channel,
        'source_consumed_ex_vat',l.source_consumed_ex_vat::text,'frozen_ex_vat',l.frozen_ex_vat::text,'frozen_vat',l.frozen_vat::text,'frozen_inc_vat',l.frozen_inc_vat::text)
        from private.bpay_next_simple_review_line_page_v1((p_args->>'run_worker_id')::uuid,(p_args->>'after_line_no')::bigint,v_limit) l
        order by l.line_no limit v_limit)
    when 'SHIFTS' then array(
      select pg_catalog.jsonb_build_object('shift_detail_id',s.id,'detail_no',s.detail_no::text,'work_date',s.work_date,
        'shift_start_at',s.shift_start_at,'shift_end_at',s.shift_end_at,'shift_start_local',s.shift_start_local,'shift_end_local',s.shift_end_local,
        'shift_overnight',s.shift_overnight,'submitted_minutes',s.submitted_minutes::text,'approved_minutes',s.approved_minutes::text,
        'approved_hours',s.approved_hours::text,'detail_label',s.detail_label,'segment_pay_ex_vat',s.segment_pay_ex_vat::text,'pay_excluded',s.pay_excluded,
        'hours_day',s.hours_day::text,'hours_night',s.hours_night::text,'hours_sat',s.hours_sat::text,'hours_sun',s.hours_sun::text,'hours_bh',s.hours_bh::text)
        from private.bpay_next_shift_detail s where s.approved_line_id=v_line and s.detail_no>coalesce((p_args->>'after_detail_no')::bigint,0)
        order by s.detail_no limit v_limit)
    when 'BREAKS' then array(
      select pg_catalog.jsonb_build_object('break_detail_id',b.id,'break_no',b.break_no::text,'break_start_at',b.break_start_at,
        'break_end_at',b.break_end_at,'break_start_local',b.break_start_local,'break_end_local',b.break_end_local,'break_minutes',b.break_minutes::text)
        from private.bpay_next_break_detail b where b.shift_detail_id=v_shift and b.break_no>coalesce((p_args->>'after_break_no')::bigint,0)
        order by b.break_no limit v_limit)
    when 'RATES' then array(
      select pg_catalog.jsonb_build_object('rate_detail_id',r.id,'bucket',r.bucket,'approved_hours',r.approved_hours::text,'source_pay_rate',r.source_pay_rate::text)
        from private.bpay_next_rate_detail r where r.approved_line_id=v_line
          and ((p_args->>'after_bucket') is null or r.bucket>p_args->>'after_bucket')
        order by r.bucket limit v_limit)
  end into v_page;
  foreach v_row in array v_page
  loop
    if pg_catalog.octet_length((v_rows||pg_catalog.jsonb_build_array(v_row))::text)>120000 then
      if v_n=0 then raise exception using errcode='54000',message='BPAY_NEXT_PREPARATION_RESPONSE_TOO_LARGE';end if;
      v_complete:=false;exit;
    end if;
    v_rows:=v_rows||pg_catalog.jsonb_build_array(v_row);v_n:=v_n+1;
  end loop;
  if v_n=v_limit then v_complete:=false;end if;
  return pg_catalog.jsonb_build_object('rows',v_rows,'complete',v_complete);
end
$function$;

ALTER FUNCTION public.bpay_next_preparation_page_v1(uuid,text,jsonb) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION public.bpay_next_preparation_page_v1(uuid,text,jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.bpay_next_preparation_page_v1(uuid,text,jsonb) TO service_role;

-- F-05-D17 successor of supabase/repeatable/04102026_1519_banking_pay_next_work_collection_v1.sql
create or replace function private.bpay_next_reconcile_work_collection_v1(
  p_job_id uuid,p_work_id uuid,p_component_key text,p_effect_id uuid default null
) returns void
language plpgsql security invoker
set search_path=pg_catalog,private
as $function$
declare
  v_epoch bigint;v_candidate uuid;v_control private.bpay_next_worker_control%rowtype;
  v_job private.bpay_next_job%rowtype;v_work private.bpay_next_work%rowtype;
  v_position private.bpay_next_position%rowtype;v_revision private.bpay_next_work_revision%rowtype;
  v_original_revision private.bpay_next_work_revision%rowtype;
  v_original_approved private.bpay_next_approved_line%rowtype;
  v_basis private.bpay_next_work_collection%rowtype;v_effect private.bpay_next_financial_effect%rowtype;
  v_line private.bpay_next_run_line%rowtype;v_approved private.bpay_next_approved_line%rowtype;
  v_case private.bpay_next_finance_case%rowtype;v_component private.bpay_next_case_component%rowtype;
  v_state text;v_qualified boolean;v_capturable boolean;v_supported_paid boolean;
  v_original_detail text;v_whole_zero boolean;v_paired_origin boolean;
  v_principal numeric;v_delta numeric;v_event text;
begin
  if p_job_id is null or p_work_id is null or p_component_key is null
     or pg_catalog.char_length(p_component_key) not between 1 and 256 then
    raise exception using errcode='22023',message='BPAY_NEXT_WORK_COLLECTION_INPUT_INVALID';
  end if;
  -- Parent owners already hold run (when applicable), Candidate control and
  -- job, in that order. These reentrant locks never acquire another run.
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select j.candidate_id into strict v_candidate from private.bpay_next_job j where j.id=p_job_id;
  select c.* into strict v_control from private.bpay_next_worker_control c where c.candidate_id=v_candidate for update;
  select j.* into strict v_job from private.bpay_next_job j where j.id=p_job_id for update;
  if v_job.status<>'LEASED' or v_job.module_epoch<>v_epoch
     or v_job.owner_epoch<>v_control.active_owner_epoch or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or exists(select 1 from private.bpay_next_job j where j.candidate_id=v_candidate
       and j.command_sequence<v_job.command_sequence and j.status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_WORK_COLLECTION_OWNER_STALE';
  end if;
  select w.* into strict v_work from private.bpay_next_work w where w.id=p_work_id and w.candidate_id=v_candidate;
  select p.* into strict v_position from private.bpay_next_position p
    where p.work_id=p_work_id and p.component_key=p_component_key for update;
  if v_job.job_kind='POSITION_APPLY' then
    if p_effect_id is not null or v_job.phase not in ('NEW','REMOVED') or not exists(
      select 1 from private.bpay_next_publication p where p.command_id=v_job.command_id
        and p.work_id=p_work_id and p.candidate_id=v_candidate and p.status in ('QUEUED','APPLYING')
        and p.revision_id=v_position.applied_revision_id) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_POSITION_SCOPE_INVALID';
    end if;
  elsif v_job.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') then
    if p_effect_id is null or v_job.phase<>'MEMBERS' then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_SETTLEMENT_SCOPE_INVALID';
    end if;
    select e.* into strict v_effect from private.bpay_next_financial_effect e where e.id=p_effect_id;
    if v_effect.effect_kind='WORK_COLLECTION_RECOVERED' then
      -- The negative WORK disposition is exactly the genuine posted CASE
      -- recovery, never a caller supplied negative or a cash-return inverse.
      if not exists(select 1 from private.bpay_next_work_collection b
        join private.bpay_next_case_event ce on ce.id=v_effect.operation_item_id and ce.case_id=b.case_id
        join private.bpay_next_run_case_instruction i on i.id=ce.instruction_id and i.work_collection_id=b.id
        join private.bpay_next_case_hold h on h.id=ce.operation_item_id and h.status='REALISED'
        join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='REALISED' and u.realisation_event_id=ce.id
        join private.bpay_next_outcome_request r on r.command_id=v_job.command_id and r.transfer_id=ce.original_transfer_id
        where b.work_id=p_work_id and b.component_key=p_component_key and b.candidate_id=v_candidate
          and ce.operation_id=v_job.command_id and ce.event_kind='RECOVERED'
          and ce.case_component_id=b.case_component_id and ce.source_amount_ex_vat>0
          and v_effect.operation_id=v_job.command_id and v_effect.work_id=b.work_id
          and v_effect.component_key=b.component_key and v_effect.candidate_id=b.candidate_id
          and v_effect.case_id=b.case_id and v_effect.original_transfer_id=ce.original_transfer_id
          and (v_effect.source_disposition_ex_vat,v_effect.target_amount_ex_vat,v_effect.target_amount_vat,v_effect.target_amount_inc_vat)
            is not distinct from (-ce.source_amount_ex_vat,-ce.target_amount_ex_vat,-ce.target_amount_vat,-ce.target_amount_inc_vat)) then
        raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_RECOVERY_SCOPE_INVALID';
      end if;
      v_capturable:=false;v_supported_paid:=true;
    else
    select l.* into strict v_line from private.bpay_next_hold h
      join private.bpay_next_run_line l on l.id=h.run_line_id
      join private.bpay_next_outcome_request r on r.command_id=v_job.command_id
      join private.bpay_next_transfer t on t.id=r.transfer_id
      where h.id=v_effect.operation_item_id and h.status='REALISED'
        and l.run_worker_id=r.run_worker_id and l.work_id=p_work_id and l.component_key=p_component_key
        and t.id=v_effect.original_transfer_id and t.candidate_id=v_candidate
        and t.original_transfer_id is null and t.return_cash_id is null
        and ((v_job.job_kind='CSV_SETTLEMENT' and t.execution_kind='BANK' and t.status in ('SETTLED','RETURNED'))
          or (v_job.job_kind='INTERNAL_SETTLEMENT' and t.execution_kind='INTERNAL_ZERO' and t.status='INTERNAL_PROCESSING'));
    if v_effect.operation_id<>v_job.command_id or v_effect.effect_kind<>'PAYROLL_SETTLED'
       or (v_effect.work_id,v_effect.component_key,v_effect.candidate_id)
         is distinct from (p_work_id,p_component_key,v_candidate)
       or v_effect.source_disposition_ex_vat<>v_line.source_consumed_ex_vat
       or v_effect.source_disposition_ex_vat<=0 then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_EFFECT_SCOPE_INVALID';
    end if;
    select a.* into strict v_approved from private.bpay_next_approved_line a where a.id=v_line.approved_line_id;
    -- Original ordinary or genuine Source PAYE -> PAYE WORK only. NULL
    -- tax is capturable as exact UNBOUND evidence, never inferred taxable.
    -- Do not return before checking an existing link: a later unsupported
    -- actual posting invalidates its paid qualification, not the payment.
    v_capturable:=v_work.work_kind='ORDINARY' and v_approved.component_kind='WORK'
      and v_line.source_pay_channel='PAYE' and v_line.target_pay_channel='PAYE'
      and exists(select 1 from private.bpay_next_work_revision r
        where r.id=v_line.captured_revision_id and r.source_kind='ORDINARY');
    -- PROTECTED is admitted only for 1550's actual committed-head branch;
    -- 0345's independent/headless protected target is not this authority.
    v_capturable:=v_capturable or (v_work.work_kind='SOURCE' and v_approved.component_kind='WORK'
      and v_approved.source_component_id is not null
      and v_approved.component_key='SOURCE:'||v_approved.source_component_id::text
      and v_line.source_pay_channel='PAYE' and v_line.target_pay_channel='PAYE'
      and exists(select 1 from private.bpay_next_work_revision r
        where r.id=v_line.captured_revision_id and r.work_id=v_work.id
          and ((r.source_kind='SOURCE' and r.source_event_id is not null
            and (r.source_head_id is null or r.source_event_id=r.source_head_id)) or (r.source_kind='PROTECTED'
            and r.source_head_id is not null and r.source_event_id=r.source_head_id))));
    v_supported_paid:=v_capturable and v_approved.tax_treatment is not distinct from 'TAXABLE';
    end if;
  elsif v_job.job_kind='SIMPLE_CANCEL' then
    if p_effect_id is not null or v_job.phase<>'RELEASE' or not exists(
      select 1 from private.bpay_next_work_collection b
      join private.bpay_next_case_cancel_binding cb on cb.command_id=v_job.command_id and cb.candidate_id=b.candidate_id
      join private.bpay_next_cancel_request r on r.command_id=cb.command_id and r.status='CANCELLING'
      join private.bpay_next_run_worker w on w.id=cb.run_worker_id and w.status='CANCELLING'
      join private.bpay_next_case_hold h on h.run_worker_id=w.id and h.status='RELEASED'
      join private.bpay_next_run_case_instruction i on i.id=h.instruction_id and i.work_collection_id=b.id
      join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='RELEASED'
      where b.work_id=p_work_id and b.component_key=p_component_key and b.candidate_id=v_candidate
        and cb.status='CANCELLING' and cb.stage='CASE'
        and i.case_id=b.case_id and i.case_component_id=b.case_component_id) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_CANCEL_SCOPE_INVALID';
    end if;
  elsif v_job.job_kind='PREPARATION_EXPIRY' then
    if p_effect_id is not null or v_job.phase<>'RELEASE' or not exists(
      select 1 from private.bpay_next_work_collection b
      where b.work_id=p_work_id and b.component_key=p_component_key and b.candidate_id=v_candidate
        and private.bpay_next_expired_work_collection_scope_v1(p_job_id,b.id,null)) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_EXPIRY_SCOPE_INVALID';
    end if;
  else
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_JOB_KIND_INVALID';
  end if;
  select b.* into v_basis from private.bpay_next_work_collection b
    where b.work_id=p_work_id and b.component_key=p_component_key for update;
  if not found then
    -- An unpaid hold is not realised money. Existing pre-install paid rows
    -- have no invented basis/backfill; future actual settlement captures it.
    if p_effect_id is null or not v_capturable then return;end if;
    insert into private.bpay_next_work_collection
      (work_id,component_key,candidate_id,original_effect_id,original_run_line_id,
       original_revision_id,original_approved_line_id,original_transfer_id,
       original_source_pay_channel,original_tax_treatment,paid_basis_qualified,original_valuation_policy_id,
       qualification_state,observed_revision_id,observed_approved_source_ex_vat,observed_realised_source_ex_vat,last_job_id,last_effect_id)
      values(p_work_id,p_component_key,v_candidate,p_effect_id,v_line.id,v_line.captured_revision_id,
        v_line.approved_line_id,v_effect.original_transfer_id,v_line.source_pay_channel,v_approved.tax_treatment,
        v_approved.tax_treatment is not distinct from 'TAXABLE'
          and v_position.realised_source_ex_vat=v_effect.source_disposition_ex_vat,v_line.valuation_policy_id,
        'CURRENT_APPROVAL_UNBOUND',v_position.applied_revision_id,v_position.approved_source_ex_vat,
        v_position.realised_source_ex_vat,p_job_id,p_effect_id) returning * into v_basis;
  elsif v_basis.last_job_id=p_job_id and
      not (p_effect_id is not null and v_effect.effect_kind='WORK_COLLECTION_RECOVERED'
        and v_basis.last_effect_id is distinct from p_effect_id) then
    if (v_basis.observed_revision_id,v_basis.observed_approved_source_ex_vat,v_basis.observed_realised_source_ex_vat,v_basis.last_effect_id)
       is distinct from (v_position.applied_revision_id,v_position.approved_source_ex_vat,v_position.realised_source_ex_vat,p_effect_id) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_SAME_JOB_CHANGED';
    end if;
    return;
  end if;
  v_qualified:=v_basis.paid_basis_qualified;
  if p_effect_id is not null and not v_supported_paid then v_qualified:=false;end if;
  select r.* into strict v_revision from private.bpay_next_work_revision r where r.id=v_position.applied_revision_id;
  select r.detail_kind into strict v_original_detail from private.bpay_next_work_revision r
    where r.id=v_basis.original_revision_id and r.work_id=p_work_id;
  select r.* into strict v_original_revision from private.bpay_next_work_revision r
    where r.id=v_basis.original_revision_id and r.work_id=p_work_id;
  select a.* into strict v_original_approved from private.bpay_next_approved_line a
    where a.id=v_basis.original_approved_line_id and a.revision_id=v_original_revision.id;
  v_paired_origin:=(v_work.work_kind='ORDINARY' and v_original_revision.source_kind='ORDINARY'
      and v_revision.source_kind='ORDINARY')
    or (v_work.work_kind='SOURCE' and v_original_approved.component_kind='WORK'
      and v_original_approved.source_component_id is not null
      and p_component_key='SOURCE:'||v_original_approved.source_component_id::text
      and ((v_original_revision.source_kind='SOURCE' and v_original_revision.source_event_id is not null
        and (v_original_revision.source_head_id is null
        or v_original_revision.source_event_id=v_original_revision.source_head_id)) or (v_original_revision.source_kind='PROTECTED'
        and v_original_revision.source_head_id is not null
        and v_original_revision.source_event_id=v_original_revision.source_head_id))
      and ((v_revision.source_kind='SOURCE' and v_revision.source_event_id is not null
        and (v_revision.source_head_id is null
        or v_revision.source_event_id=v_revision.source_head_id)) or (v_revision.source_kind='PROTECTED'
        and v_revision.source_head_id is not null and v_revision.source_event_id=v_revision.source_head_id)));
  -- Absence of a DAY key does not prove removal: an AGGREGATE or another
  -- business-date component may retain the entitlement. This first slice
  -- qualifies unchanged typed identity only. A genuinely sealed, certified
  -- whole-base empty zero is the sole missing-key exception; reconciliation
  -- across representations remains explicitly UNBOUND, not discarded.
  v_whole_zero:=v_revision.sealed_at_utc is not null and v_revision.certified_zero
    and v_revision.approved_source_ex_vat=0 and v_revision.expected_line_count=0;
  if v_basis.original_tax_treatment is distinct from 'TAXABLE' then v_state:='ORIGINAL_TAX_UNBOUND';
  elsif not v_qualified then v_state:='PAID_BASIS_UNBOUND';
  elsif v_job.job_kind not in ('SIMPLE_CANCEL','PREPARATION_EXPIRY') and v_effect.effect_kind is distinct from 'WORK_COLLECTION_RECOVERED'
      and (v_work.approval_state<>'APPROVED'
        or v_work.current_revision_id is distinct from v_position.applied_revision_id) then
    v_state:='CURRENT_APPROVAL_UNBOUND';
  elsif v_paired_origin is not true or v_revision.source_pay_channel<>'PAYE'
      or v_position.source_basis_channel is distinct from 'PAYE'
      or (not v_whole_zero and (v_revision.detail_kind<>v_original_detail
        or not exists(select 1 from private.bpay_next_approved_line a
          where a.revision_id=v_revision.id and a.component_key=p_component_key
            and a.component_kind='WORK' and a.tax_treatment='TAXABLE'
            and (v_work.work_kind='ORDINARY'
              or a.source_component_id=v_original_approved.source_component_id)))) then
    v_state:='CURRENT_SOURCE_UNBOUND';
  elsif v_position.approved_source_ex_vat<0 or v_position.realised_source_ex_vat<0 then v_state:='SIGNED_SOURCE_UNBOUND';
  else v_state:='READY';end if;
  if v_work.work_kind='SOURCE' and v_revision.source_head_id is not null and not exists (
    select 1 from private.bpay_next_source_component_binding b
      join private.bpay_next_source_component_binding_version v on v.id=b.current_binding_version_id
      join private.weekly_source_entitlement_publication_receipts receipt on receipt.id=v.source_receipt_id
      join public.weekly_source_entitlement_decision_bundles bundle on bundle.decision_bundle_id=v.decision_bundle_id
        and bundle.bundle_revision=v.bundle_revision and bundle.state='COMMITTED'
      join public.weekly_source_entitlement_heads head on head.id=v.head_id and head.state='COMMITTED_CURRENT'
      join public.weekly_source_root_authorisations auth on auth.current_entitlement_head_id=head.id
        and auth.root_timesheet_id=head.root_timesheet_id and auth.withdrawn_at_utc is null
      join private.bpay_next_publication publication on publication.command_id=v.publication_command_id_1
        and publication.work_id=v.approval_work_id and publication.revision_id=v.approval_revision_id
        and publication.candidate_id=v_candidate
      where b.canonical_work_id=p_work_id and b.canonical_component_key=p_component_key
        and v.approval_work_id=p_work_id and v.approval_component_key=p_component_key
        and v.approval_revision_id=v_position.applied_revision_id
        and v.head_id=v_revision.source_head_id and v_revision.source_event_id=v.head_id
        and v.publication_command_id_2 is null and v.candidate_id=v_candidate
        and v.approval_source_channel='PAYE' and v.tax_treatment='TAXABLE'
        and receipt.decision_bundle_id=v.decision_bundle_id and receipt.bundle_revision=v.bundle_revision
        and receipt.request_digest=v.request_digest and pg_catalog.cardinality(receipt.head_ids)=1
        and receipt.head_ids[1]=v.head_id and v_work.current_revision_id=v.approval_revision_id
        and ((v_job.job_kind='POSITION_APPLY' and publication.command_id=v_job.command_id
              and publication.status in ('QUEUED','APPLYING'))
          or (v_job.job_kind<>'POSITION_APPLY' and publication.status='APPLIED' and publication.phase='DONE'))
  ) then v_state:='CURRENT_SOURCE_UNBOUND';end if;
  if v_state='READY' then
    if v_basis.case_id is null then
      v_principal:=greatest(v_position.realised_source_ex_vat-v_position.approved_source_ex_vat,0);
      if v_principal>0 then
        insert into private.bpay_next_finance_case
          (id,candidate_id,case_kind,tax_treatment,status,principal_approved,order_key,case_revision)
          values(v_basis.id,v_candidate,'OVERPAYMENT','TAXABLE','OPEN',v_principal,v_job.command_sequence,1);
        insert into private.bpay_next_case_rule
          (id,case_id,candidate_id,rule_revision,case_kind,case_subtype,tax_treatment,case_created_at_utc)
          values(v_basis.id,v_basis.id,v_candidate,1,'OVERPAYMENT','OVERPAYMENT','TAXABLE',pg_catalog.transaction_timestamp());
        update private.bpay_next_finance_case set current_rule_id=v_basis.id,current_rule_revision=1 where id=v_basis.id;
        insert into private.bpay_next_case_component
          (id,case_id,candidate_id,component_key,component_ordinal,component_revision,rule_id,
           case_kind,case_subtype,tax_treatment,instruction_kind,direction,payroll_stage,
           source_pay_channel,currency,approved_source_ex_vat,resolution_state)
          values(v_basis.id,v_basis.id,v_candidate,'RECOVERY',1,1,v_basis.id,
            'OVERPAYMENT','OVERPAYMENT','TAXABLE','RECOVERY','DEDUCTION','GROSS_DEDUCT','PAYE','GBP',v_principal,'REVIEW');
        v_basis.case_id:=v_basis.id;v_basis.case_component_id:=v_basis.id;v_delta:=v_principal;v_event:='APPROVED';
      end if;
    else
      select c.* into strict v_case from private.bpay_next_finance_case c where c.id=v_basis.case_id for update;
      select c.* into strict v_component from private.bpay_next_case_component c where c.id=v_basis.case_component_id for update;
      if (v_case.principal_approved,v_case.principal_recovered,v_case.principal_written_off,v_case.active_recovery_hold_amount)
         is distinct from (v_component.approved_source_ex_vat,v_component.recovered_source_ex_vat,
           v_component.written_off_source_ex_vat,v_component.active_recovery_source_ex_vat) then
        raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_BALANCE_MISMATCH';
      end if;
      -- R is actual SOURCE disposition, never held money/bank cash. Genuine
      -- future recovery must lower R with its own signed effect. Forgiveness
      -- W is separate; protected H is not repriced or released by an approval.
      v_principal:=v_case.principal_recovered+v_case.principal_written_off+
        greatest(v_position.realised_source_ex_vat-v_position.approved_source_ex_vat-v_case.principal_written_off,
          v_case.active_recovery_hold_amount,0);
      v_delta:=v_principal-v_case.principal_approved;
      if v_delta<>0 then
        update private.bpay_next_finance_case set principal_approved=v_principal,
          status=case when v_principal=principal_recovered+principal_written_off then 'CLOSED'
            when status='PAUSED' then 'PAUSED' else 'OPEN' end,
          case_revision=case_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_basis.case_id;
        update private.bpay_next_case_component set approved_source_ex_vat=v_principal,
          component_revision=component_revision+1,resolution_state='REVIEW',
          target_pay_channel=null,target_ex_vat=null,target_vat=null,target_inc_vat=null,
          valuation_policy_id=null,valuation_window_id=null,resolution_ref=null,
          updated_at_utc=pg_catalog.transaction_timestamp() where id=v_basis.case_component_id;
        v_event:='CORRECTED';
      elsif v_principal=v_case.principal_recovered+v_case.principal_written_off and v_case.status<>'CLOSED' then
        update private.bpay_next_finance_case set status='CLOSED',case_revision=case_revision+1,
          updated_at_utc=pg_catalog.transaction_timestamp() where id=v_basis.case_id;
      end if;
    end if;
    if v_event is not null then
      insert into private.bpay_next_case_event
        (case_id,operation_id,operation_item_id,event_kind,approved_delta,original_transfer_id,original_effect_id)
        values(v_basis.case_id,v_job.command_id,v_basis.id,v_event,v_delta,
          v_basis.original_transfer_id,v_basis.original_effect_id);
    end if;
  end if;
  -- First insert records exact basis; this single follow-up records the
  -- observation/case under the same actual owner transaction. No view counter
  -- is independently incremented: existing position/posting owners do that.
  update private.bpay_next_work_collection set case_id=v_basis.case_id,case_component_id=v_basis.case_component_id,
    paid_basis_qualified=v_qualified,qualification_state=v_state,observed_revision_id=v_position.applied_revision_id,
    observed_approved_source_ex_vat=v_position.approved_source_ex_vat,
    observed_realised_source_ex_vat=v_position.realised_source_ex_vat,
    reconcile_revision=reconcile_revision+1,last_job_id=p_job_id,last_effect_id=p_effect_id,
    updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_basis.id;
end
$function$;

ALTER FUNCTION private.bpay_next_reconcile_work_collection_v1(uuid,uuid,text,uuid) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_reconcile_work_collection_v1(uuid,uuid,text,uuid) FROM PUBLIC, anon, authenticated, service_role;

-- F-05-D17 successor of supabase/repeatable/04102026_1519_banking_pay_next_work_collection_v1.sql
create or replace function private.bpay_next_apply_work_collection_recovery_v1(p_job_id uuid,p_case_event_id uuid)
returns void language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_job private.bpay_next_job%rowtype;v_event private.bpay_next_case_event%rowtype;
  v_basis private.bpay_next_work_collection%rowtype;v_instruction private.bpay_next_run_case_instruction%rowtype;
  v_effect private.bpay_next_financial_effect%rowtype;v_effect_id uuid;
  v_source_line private.bpay_next_run_line%rowtype;
begin
  select * into strict v_job from private.bpay_next_job where id=p_job_id;
  select * into strict v_event from private.bpay_next_case_event where id=p_case_event_id;
  select * into strict v_instruction from private.bpay_next_run_case_instruction where id=v_event.instruction_id;
  select * into strict v_basis from private.bpay_next_work_collection where id=v_instruction.work_collection_id;
  if v_job.job_kind not in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') or v_job.phase<>'MEMBERS' or v_job.status<>'LEASED'
     or v_job.candidate_id<>v_basis.candidate_id or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or (v_event.operation_id,v_event.case_id,v_event.case_component_id,v_event.candidate_id)
       is distinct from (v_job.command_id,v_basis.case_id,v_basis.case_component_id,v_basis.candidate_id)
     or v_event.event_kind<>'RECOVERED' or v_event.source_amount_ex_vat<=0
     or v_instruction.valuation_policy_id<>v_basis.original_valuation_policy_id
     or (v_event.source_amount_ex_vat,v_event.target_amount_ex_vat,v_event.target_amount_vat,v_event.target_amount_inc_vat)
       is distinct from (v_event.recovered_delta,v_event.recovered_delta,0::numeric,v_event.recovered_delta)
     or not exists(select 1 from private.bpay_next_module_control m
       join private.bpay_next_worker_control c on c.candidate_id=v_basis.candidate_id
       where m.id=1 and m.active_owner='NEXT' and m.owner_epoch=v_job.module_epoch and c.active_owner_epoch=v_job.owner_epoch)
     or not exists(select 1 from private.bpay_next_case_hold h
       join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='REALISED' and u.realisation_event_id=v_event.id
       join private.bpay_next_outcome_request r on r.command_id=v_job.command_id and r.transfer_id=v_event.original_transfer_id
       join private.bpay_next_transfer_member member on member.transfer_id=r.transfer_id and member.case_hold_id=h.id
         and member.case_instruction_id=v_instruction.id and member.case_allocation_result_id=v_event.allocation_result_id
       where h.id=v_event.operation_item_id and h.status='REALISED' and h.instruction_id=v_instruction.id
         and h.source_reserved_ex_vat=v_event.source_amount_ex_vat and h.run_worker_id=r.run_worker_id) then
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_RECOVERY_SCOPE_INVALID';
  end if;
  select * into strict v_source_line from private.bpay_next_run_line where id=v_basis.original_run_line_id;
  insert into private.bpay_next_financial_effect(operation_id,operation_item_id,effect_kind,candidate_id,
    work_id,component_key,case_id,original_timesheet_id,original_transfer_id,source_disposition_ex_vat,
    target_amount_ex_vat,target_amount_vat,target_amount_inc_vat,occurred_at_utc,source_run_line_id,
    source_binding_version_id,canonical_source_work_id,canonical_source_component_key,native_source_channel,source_case_event_id)
    select v_job.command_id,v_event.id,'WORK_COLLECTION_RECOVERED',v_basis.candidate_id,
      v_basis.work_id,v_basis.component_key,v_basis.case_id,w.original_timesheet_id,v_event.original_transfer_id,
      -v_event.source_amount_ex_vat,-v_event.target_amount_ex_vat,-v_event.target_amount_vat,-v_event.target_amount_inc_vat,v_event.occurred_at_utc,
      case when v_source_line.source_binding_version_id is null then null else v_source_line.id end,
      v_source_line.source_binding_version_id,v_source_line.canonical_source_work_id,v_source_line.canonical_source_component_key,
      case when v_source_line.source_binding_version_id is null then null else v_source_line.source_pay_channel end,
      case when v_source_line.source_binding_version_id is null then null else v_event.id end
      from private.bpay_next_work w where w.id=v_basis.work_id
    on conflict(operation_id,operation_item_id,effect_kind) do nothing returning id into v_effect_id;
  if v_effect_id is null then
    select * into strict v_effect from private.bpay_next_financial_effect where operation_id=v_job.command_id
      and operation_item_id=v_event.id and effect_kind='WORK_COLLECTION_RECOVERED';
    if (v_effect.candidate_id,v_effect.work_id,v_effect.component_key,v_effect.case_id,v_effect.original_transfer_id,
        v_effect.source_disposition_ex_vat,v_effect.target_amount_ex_vat,v_effect.target_amount_vat,v_effect.target_amount_inc_vat)
      is distinct from (v_basis.candidate_id,v_basis.work_id,v_basis.component_key,v_basis.case_id,v_event.original_transfer_id,
        -v_event.source_amount_ex_vat,-v_event.target_amount_ex_vat,-v_event.target_amount_vat,-v_event.target_amount_inc_vat) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_RECOVERY_REPLAY_CONFLICT';
    end if;
    if (v_effect.source_run_line_id,v_effect.source_binding_version_id,v_effect.canonical_source_work_id,
        v_effect.canonical_source_component_key,v_effect.native_source_channel,v_effect.source_case_event_id)
      is distinct from (case when v_source_line.source_binding_version_id is null then null else v_source_line.id end,
        v_source_line.source_binding_version_id,v_source_line.canonical_source_work_id,v_source_line.canonical_source_component_key,
        case when v_source_line.source_binding_version_id is null then null else v_source_line.source_pay_channel end,
        case when v_source_line.source_binding_version_id is null then null else v_event.id end) then
      raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_BOOK_EFFECT_REPLAY_CONFLICT';
    end if;
    return;
  end if;
  update private.bpay_next_position set realised_source_ex_vat=realised_source_ex_vat-v_event.source_amount_ex_vat,
    realised_target_ex_vat=realised_target_ex_vat-v_event.target_amount_ex_vat,
    realised_target_vat=realised_target_vat-v_event.target_amount_vat,
    realised_target_inc_vat=realised_target_inc_vat-v_event.target_amount_inc_vat,
    updated_at_utc=pg_catalog.transaction_timestamp()
    where work_id=v_basis.work_id and component_key=v_basis.component_key and source_basis_channel='PAYE'
      and realised_source_ex_vat>=v_event.source_amount_ex_vat
      and (realised_target_ex_vat,realised_target_vat,realised_target_inc_vat)
        is not distinct from (realised_source_ex_vat,0::numeric,realised_source_ex_vat);
  if not found then raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_RECOVERY_POSITION_INVALID';end if;
  perform private.bpay_next_reconcile_work_collection_v1(p_job_id,v_basis.work_id,v_basis.component_key,v_effect_id);
end
$function$;

ALTER FUNCTION private.bpay_next_apply_work_collection_recovery_v1(uuid,uuid) OWNER TO CURRENT_USER;
REVOKE ALL ON FUNCTION private.bpay_next_apply_work_collection_recovery_v1(uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;

notify pgrst, 'reload schema';


-- CONTACT_PREPARER_UNIT 40 repeatable supabase/repeatable/10102026_0151_banking_pay_next_rule_b_selection_consumers_v1.sql SHA256 720da16203199b37638c0f9edca450f28ea97b968593652cc7ee114e8bf1afcc
-- F-25 owner rule B; four exact three-way surviving owner seams only.
-- Preserve original PIN REVIEW/validation, F-05 claim order and live money locks.



create or replace function private.bpay_next_seal_selection_v1(
  p_run_id uuid,p_expected_pages bigint,p_expected_count bigint
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private
as $function$
declare v_run private.bpay_next_pay_run%rowtype;v_selected record;
begin
  if p_run_id is null or p_expected_pages is null or p_expected_count is null
     or p_expected_pages<0 or p_expected_count<0
     or (p_expected_pages=0) is distinct from (p_expected_count=0) then
    raise exception using errcode='22023',
      message='BPAY_NEXT_SELECTION_SEAL_INPUT_INVALID';
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=p_run_id for update;
  if v_run.selection_page_count<>p_expected_pages
     or v_run.selection_count<>p_expected_count then
    raise exception using errcode='23514',
      message='BPAY_NEXT_SELECTION_SEAL_COUNT_MISMATCH';
  end if;
  if v_run.work_choice_count<>v_run.selection_count
     or v_run.sealed_work_choice_count<>v_run.selection_count then
    raise exception using errcode='55000',
      message='BPAY_NEXT_SELECTION_COMPONENT_CHOICES_NOT_SEALED';
  end if;
  if v_run.selection_state='SEALED' then
    return jsonb_build_object('run_id',p_run_id,'sealed',true,
      'selection_count',v_run.selection_count,'replay',true);
  end if;
  -- A case-only run contains genuine selected case components, not fictitious
  -- WORK rows. The root-locked seal counter is maintained once per Candidate
  -- by0330; checking it does not scan every Candidate at final confirmation.
  if p_expected_count=0 and (v_run.selected_candidate_count<1
     or v_run.sealed_case_candidate_count<>v_run.selected_candidate_count) then
    raise exception using errcode='55000',message='BPAY_NEXT_SELECTION_CASE_ONLY_NOT_SEALED';
  end if;
  if v_run.status<>'PREPARING' then
    raise exception using errcode='55000',
      message='BPAY_NEXT_SELECTION_SEAL_STATUS_INVALID';
  end if;
  -- Owner rule B: capture only the existing ticked expected revisions.
  -- Exact sealed replay above never refreshes settings or query state.
  perform private.weekly_source_pay_query_admit_v2();
  update private.bpay_next_selection_candidate selected
    set target_pay_channel=upper(candidate.pay_method),
        target_umbrella_id=candidate.umbrella_id,
        target_umbrella_vat_chargeable=umbrella.vat_chargeable,
        min_take_home_wtd=candidate.min_take_home_wtd
    from public.candidates candidate left join public.umbrellas umbrella on umbrella.id=candidate.umbrella_id
    where selected.run_id=p_run_id and selected.candidate_id=candidate.id;
  for v_selected in
    select choice.work_id,choice.expected_revision_id,revision.physical_timesheet_id
      from private.bpay_next_run_selection selected
      join private.bpay_next_work_choice choice on choice.run_id=selected.run_id and choice.work_id=selected.work_id
      join private.bpay_next_work work on work.id=selected.work_id
      join private.bpay_next_work_revision revision on revision.work_id=choice.work_id and revision.id=choice.expected_revision_id
      where selected.run_id=p_run_id and work.work_kind='SOURCE' and revision.source_kind in ('SOURCE','PROTECTED')
      order by selected.selection_no
  loop
    insert into private.bpay_next_run_work_query_snapshot(run_id,work_id,expected_revision_id,physical_timesheet_id,gate_result,captured_at_utc)
      values(p_run_id,v_selected.work_id,v_selected.expected_revision_id,v_selected.physical_timesheet_id,
        private.weekly_source_pay_query_gate_v1(v_selected.physical_timesheet_id),pg_catalog.transaction_timestamp());
  end loop;
  update private.bpay_next_pay_run
    set selection_state='SEALED',review_revision=review_revision+1
    where id=p_run_id;
  return jsonb_build_object('run_id',p_run_id,'sealed',true,
    'selection_count',v_run.selection_count,'replay',false);
end
$function$;


create or replace function private.bpay_next_claim_prepare_job_v1(
  p_job_id uuid,p_lease_seconds integer default 120
) returns table(lease_nonce uuid,owner_epoch bigint)
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_job private.bpay_next_job%rowtype;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_run_id uuid;
  v_module_epoch bigint;
  v_channel text;
  v_umbrella_id uuid;
  v_umbrella_vat_chargeable boolean;
  v_owner_epoch bigint;
  v_nonce uuid;
begin
  if p_job_id is null or p_lease_seconds not between 1 and 120 then
    raise exception using errcode='22023',
      message='BPAY_NEXT_PREPARE_LEASE_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_module_epoch
    from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_module_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select j.candidate_id,rc.run_id into strict v_job.candidate_id,v_run_id
    from private.bpay_next_job j
    join private.bpay_next_run_command rc on rc.command_id=j.command_id
    where j.id=p_job_id and j.job_kind='PREPARE';
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for share;
  insert into private.bpay_next_worker_control(candidate_id)
    values(v_job.candidate_id) on conflict(candidate_id) do nothing;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_job.candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED'
     or v_job.job_kind<>'PREPARE' or v_job.module_epoch<>v_module_epoch
     or not exists(select 1 from private.bpay_next_command command
       where command.id=v_job.command_id and command.agency_sequence=v_job.command_sequence
         and command.module_epoch=v_module_epoch and command.command_kind='PREPARE'
         and command.status='SEALED' and command.sealed_at_utc is not null
         and command.expected_member_count=v_run.selected_candidate_count
         and command.enrolled_member_count=command.expected_member_count)
     or v_job.status not in ('READY','LEASED')
     or (v_job.status='LEASED'
       and v_job.lease_until_utc>pg_catalog.clock_timestamp()) then
    raise exception using errcode='55000',
      message='BPAY_NEXT_PREPARE_JOB_NOT_CLAIMABLE';
  end if;
  if exists(select 1 from private.bpay_next_job earlier
      where earlier.candidate_id=v_job.candidate_id
        and earlier.command_sequence<v_job.command_sequence
        and earlier.status<>'DONE') then
    raise exception using errcode='55000',
      message='BPAY_NEXT_EARLIER_WORKER_COMMAND_PENDING';
  end if;
  select * into v_worker from private.bpay_next_run_worker
    where run_id=v_run_id and candidate_id=v_job.candidate_id for update;
  if not found then
    select selected.target_pay_channel,selected.target_umbrella_id,selected.target_umbrella_vat_chargeable
      into strict v_channel,v_umbrella_id,v_umbrella_vat_chargeable
      from private.bpay_next_selection_candidate selected
      where selected.run_id=v_run_id and selected.candidate_id=v_job.candidate_id;
    if v_channel not in ('PAYE','UMBRELLA') then
      raise exception using errcode='23514',
        message='BPAY_NEXT_PREPARE_PAY_CHANNEL_UNSUPPORTED';
    end if;
    insert into private.bpay_next_run_worker
      (run_id,candidate_id,target_pay_channel,target_umbrella_id,
       target_umbrella_vat_chargeable,status)
      values(v_run_id,v_job.candidate_id,v_channel,
        case when v_channel='UMBRELLA' then v_umbrella_id else null end,
        case when v_channel='UMBRELLA' then v_umbrella_vat_chargeable
          else null end,'PREPARING')
      returning * into v_worker;
  elsif v_worker.status<>'PREPARING' then
    raise exception using errcode='55000',
      message='BPAY_NEXT_PREPARE_WORKER_STATE_CHANGED';
  end if;
  update private.bpay_next_worker_control
    set active_owner_epoch=active_owner_epoch+1,
        updated_at_utc=pg_catalog.transaction_timestamp()
    where candidate_id=v_job.candidate_id
    returning active_owner_epoch into v_owner_epoch;
  v_nonce:=pg_catalog.gen_random_uuid();
  update private.bpay_next_job
    set status='LEASED',owner_epoch=v_owner_epoch,lease_nonce=v_nonce,
        lease_until_utc=pg_catalog.clock_timestamp()
          +pg_catalog.make_interval(secs=>p_lease_seconds),
        attempt_count=attempt_count+1
    where id=p_job_id;
  lease_nonce:=v_nonce;owner_epoch:=v_owner_epoch;
  return next;
end
$function$;


create or replace function private.bpay_next_pin_selected_work_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_cursor bigint
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private
as $function$
declare
  v_job private.bpay_next_job%rowtype;
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker_id uuid;
  v_worker private.bpay_next_run_worker%rowtype;
  v_selection private.bpay_next_run_selection%rowtype;
  v_choice private.bpay_next_work_choice%rowtype;
  v_work private.bpay_next_work%rowtype;
  v_revision private.bpay_next_work_revision%rowtype;
  v_current_cursor bigint;
  v_module_epoch bigint;
  v_query_admitted boolean:=false;
  v_source_classified boolean;
  v_source_origin record;
  v_query_gate jsonb;
  v_query_scope jsonb;
  v_query_disposition text;
  v_query_digest bytea;
  v_run_work_id uuid;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or (p_expected_cursor is not null and p_expected_cursor<1) then
    raise exception using errcode='22023',
      message='BPAY_NEXT_PIN_INPUT_INVALID';
  end if;
  -- Authorised direct callers use the same outer entry as 0280. Discover
  -- without a job/module/run lock; do not newly admit retained replay/stale
  -- inputs. This read never substitutes for the original locked owner checks.
  select j.* into strict v_job from private.bpay_next_job j
    where j.id=p_job_id and j.job_kind='PREPARE';
  select rc.run_id into strict v_run_id from private.bpay_next_run_command rc
    where rc.command_id=v_job.command_id;
  if v_job.status='LEASED' and v_job.phase in ('NEW','PINNING')
     and v_job.lease_nonce is not distinct from p_lease_nonce
     and v_job.owner_epoch is not distinct from p_owner_epoch
     and v_job.lease_until_utc>pg_catalog.clock_timestamp()
     and v_job.cursor_key::bigint is not distinct from p_expected_cursor then
    perform private.weekly_source_pay_query_admit_v2();
    v_query_admitted:=true;
  end if;
  select m.owner_epoch into v_module_epoch
    from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_module_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for share;
  select candidate_id into strict v_job.candidate_id
    from private.bpay_next_job where id=p_job_id;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_job.candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  if v_job.status='DONE' and v_job.phase='DONE'
     and v_job.job_kind='PREPARE' and v_job.owner_epoch=p_owner_epoch then
    select * into strict v_worker from private.bpay_next_run_worker
      where run_id=v_run_id and candidate_id=v_job.candidate_id;
    if v_worker.status='REVIEW' and v_worker.review_issue_code is not null then
      return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
        'issue_code',v_worker.review_issue_code,
        'work_id',v_worker.review_issue_work_id,'replay',true);
    end if;
  end if;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED'
     or v_job.status<>'LEASED' or v_job.job_kind<>'PREPARE'
     or v_job.module_epoch<>v_module_epoch
     or v_job.lease_nonce<>p_lease_nonce
     or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() then
    raise exception using errcode='55000',message='BPAY_NEXT_PIN_LEASE_STALE';
  end if;
  if v_job.phase='RESERVE' then
    return pg_catalog.jsonb_build_object('done',true,'phase','RESERVE',
      'replay',true);
  end if;
  if v_job.phase not in ('NEW','PINNING') then
    raise exception using errcode='23514',message='BPAY_NEXT_PIN_PHASE_INVALID';
  end if;
  v_current_cursor:=v_job.cursor_key::bigint;
  if v_current_cursor is distinct from p_expected_cursor then
    return pg_catalog.jsonb_build_object('done',false,'phase',v_job.phase,
      'next_cursor',v_current_cursor,'replay',true);
  end if;
  if not v_query_admitted then
    -- A changed discovery cannot become a fresh mutation after Bank locks.
    -- Roll back and retry the original STEP via the existing 40001 channel;
    -- never acquire the Source key late, fabricate REVIEW or adopt a nonce.
    raise exception using errcode='40001',message='BPAY_NEXT_PIN_ADMISSION_CHANGED';
  end if;
  select * into strict v_worker from private.bpay_next_run_worker
    where run_id=v_run_id and candidate_id=v_job.candidate_id for update;
  v_worker_id:=v_worker.id;
  select * into v_selection from private.bpay_next_run_selection
    where run_id=v_run_id and candidate_id=v_job.candidate_id
      and selection_no>coalesce(v_current_cursor,0)
    order by selection_no limit 1;
  if not found then
    update private.bpay_next_job set phase='RESERVE',cursor_key=null
      where id=p_job_id;
    return pg_catalog.jsonb_build_object('done',true,'phase','RESERVE',
      'replay',false);
  end if;
  select * into strict v_work from private.bpay_next_work
    where id=v_selection.work_id for share;
  if v_work.candidate_id<>v_job.candidate_id then
    raise exception using errcode='23514',
      message='BPAY_NEXT_PIN_CANDIDATE_MISMATCH';
  end if;
  select * into strict v_choice from private.bpay_next_work_choice
    where run_id=v_run_id and work_id=v_work.id;
  if v_choice.selection_state<>'SEALED' then
    raise exception using errcode='55000',
      message='BPAY_NEXT_SELECTION_COMPONENT_CHOICES_NOT_SEALED';
  end if;
  if v_work.approval_state<>'APPROVED'
     or v_work.current_revision_id is null
     or v_choice.expected_revision_id is null
     or v_choice.expected_revision_id is distinct from v_work.current_revision_id
     or v_work.current_revision_id is distinct from v_work.applied_revision_id then
    -- A newly published revision may be waiting behind this PREPARE command.
    -- End only this worker's non-executable attempt so its later position job
    -- can run. Do not silently omit the work or retain an executable offer.
    update private.bpay_next_run_worker
      set status='REVIEW',review_issue_code=case
        when v_work.approval_state<>'APPROVED' or v_work.current_revision_id is null
          or v_choice.expected_revision_id is null
          then 'SELECTED_WORK_NOT_APPROVED'
        when v_choice.expected_revision_id is distinct from v_work.current_revision_id
          then 'SELECTED_WORK_REVISION_CHANGED'
        else 'SELECTED_WORK_POSITION_PENDING' end,
        review_issue_work_id=v_work.id
      where id=v_worker_id;
    update private.bpay_next_job
      set status='DONE',phase='DONE',cursor_key=null,
          lease_nonce=null,lease_until_utc=null
      where id=p_job_id;
    return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
      'issue_code',case
        when v_work.approval_state<>'APPROVED' or v_work.current_revision_id is null
          or v_choice.expected_revision_id is null
          then 'SELECTED_WORK_NOT_APPROVED'
        when v_choice.expected_revision_id is distinct from v_work.current_revision_id
          then 'SELECTED_WORK_REVISION_CHANGED'
        else 'SELECTED_WORK_POSITION_PENDING' end,
      'work_id',v_work.id,'replay',false);
  end if;
  select * into strict v_revision from private.bpay_next_work_revision
    where id=v_choice.expected_revision_id and work_id=v_work.id for share;
  if v_revision.sealed_at_utc is null or v_revision.approved_at_utc is null then
    raise exception using errcode='23514',
      message='BPAY_NEXT_PIN_APPROVAL_NOT_SEALED';
  end if;
  if v_work.work_kind='SOURCE' and v_revision.source_kind in ('SOURCE','PROTECTED') then
    -- Exact point qualification of the approved captured origin. No I3
    -- financial-completion reader, inventory/history rebuild or live price.
    -- Initial authorised TSFIN, committed HEAD and genuine headless direct
    -- NEXT are distinct lanes; none may manufacture the other's authority.
    -- Evaluate the actual classifier as its own statement even for self-bill:
    -- OR/CASE short-circuiting must not hide its permission/integrity errors.
    -- Current domain facts qualify a returned Scope, not immutable provenance
    -- when Source explicitly reports that the current scope is unavailable.
    v_source_classified:=private._candidate_expense_source_family_v1(v_revision.physical_timesheet_id);
    select t.timesheet_id,t.version,t.booking_id,c.client_id,
           family.id as family_id,family.bound_version,
           (t.sheet_scope='WEEKLY'::public.timesheet_scope_enum
            and t.contract_id=v_work.contract_id and c.candidate_id=v_work.candidate_id
            and t.week_ending_date=v_work.week_ending_date
            and t.version=v_revision.physical_timesheet_version
            and t.booking_id=v_work.booking_id and c.client_id is not null
            and v_revision.week_ending_date=v_work.week_ending_date) as root_exact,
           (t.line_type='HOURS'::public.timesheet_line_type_enum and not t.is_adjustment
            and (c.self_bill is true or v_source_classified is true)
            and cw.timesheet_id=t.timesheet_id and not cw.is_adjustment
            and (family.id is null or (family.root_timesheet_id=t.timesheet_id
              and family.root_family_booking_id=t.booking_id
              and family.candidate_id=v_work.candidate_id
              and family.contract_id=v_work.contract_id
              and family.week_ending_date=v_work.week_ending_date
              and family.bound_version>0))) as scope_exact,
           case when v_revision.source_head_id is not null then
             h.id=v_revision.source_event_id and h.root_timesheet_id=t.timesheet_id
             and h.root_timesheet_version=t.version and h.root_family_booking_id=t.booking_id
             and h.candidate_id=v_work.candidate_id and h.contract_id=v_work.contract_id
             and h.week_ending_date=v_work.week_ending_date and h.state in ('COMMITTED_CURRENT','SUPERSEDED')
             and h.committed_at_utc is not null and pg_catalog.isfinite(h.committed_at_utc)
             and h.authority_kind=case when v_revision.source_kind='PROTECTED'
               then 'PROTECTED' else 'LOCKED_FINAL_SOURCE' end
           when v_revision.source_kind='SOURCE' then
             auth.id=v_revision.source_event_id and auth.root_timesheet_id=t.timesheet_id
             and auth.family_booking_id=t.booking_id and auth.timesheet_version=t.version
             and auth.authorised_at_utc is not null and pg_catalog.isfinite(auth.authorised_at_utc)
             and tf.id=v_revision.financial_snapshot_id and tf.timesheet_id=t.timesheet_id
             and tf.timesheet_version=t.version and tf.candidate_id=v_work.candidate_id
             and tf.client_id=c.client_id and tf.authorised_at_utc is not null
             and pg_catalog.isfinite(tf.authorised_at_utc)
           else
             v_revision.source_head_id is null and v_revision.financial_snapshot_id is null
             and receipt.approval_id=v_revision.source_event_id
             and receipt.work_id=v_work.id and receipt.revision_id=v_revision.id
             and receipt.command_id=publication.command_id and receipt.family_id=family.id
             and receipt.agency_sequence=command.agency_sequence
             and receipt.accepted_family_bound_version<=family.bound_version
             and approval.creation_orchestration_run_id=receipt.orchestration_run_id
             and approval.pay_target_family_id=family.id and approval.candidate_id=v_work.candidate_id
             and approval.client_id=c.client_id and approval.contract_id=v_work.contract_id
             and approval.week_ending=v_work.week_ending_date
             and generation.family_id=family.id and generation.lifecycle_state in ('PUBLISHED','SUPERSEDED')
             and generation.published_at_utc is not null
             and generation.result_hash=receipt.publication_request_sha256
             and orchestration.family_id=family.id and orchestration.state='COMPLETE'
             and orchestration.requested_by_user_id=receipt.actor_user_id
             and orchestration.request_fingerprint=receipt.prepared_request_sha256
             and orchestration.after_state_fingerprint=receipt.publication_request_sha256
             and orchestration.completed_at_utc is not null
           end as origin_exact,
           case when v_revision.source_head_id is not null then
             h.state='COMMITTED_CURRENT' and live_auth.current_entitlement_head_id=h.id
           when v_revision.source_kind='SOURCE' then
             live_auth.id=auth.id and live_auth.current_entitlement_head_id is null
             and not exists(select 1 from public.weekly_source_entitlement_heads current_head
               where pg_catalog.btrim(current_head.root_family_booking_id)=pg_catalog.btrim(t.booking_id)
                 and current_head.state='COMMITTED_CURRENT')
           else approval.withdrawn_at_utc is null end as financial_current,
           (publication.candidate_id=v_work.candidate_id
             and publication.revision_no=v_revision.revision_no
             and publication.status='APPLIED' and publication.phase='DONE'
             and command.command_kind='POSITION_APPLY' and command.module_epoch=v_module_epoch
             and command.id=private.bpay_next_source_command_id_v1(v_revision.source_event_id)
             and command.status='COMPLETE' and command.sealed_at_utc is not null
             and command.expected_member_count=command.enrolled_member_count
             and member.member_no is not null) as publication_exact
      into v_source_origin
      from public.timesheets t
      join public.contracts c on c.id=t.contract_id
      -- uq_contract_week makes this one indexed ordinary configured-week
      -- point; a same-contract/week row for another physical root is not scope.
      left join public.contract_weeks cw
        on cw.contract_id=t.contract_id and cw.week_ending_date=t.week_ending_date
          and cw.additional_seq=0
      left join public.weekly_exceptional_pay_target_families family
        on pg_catalog.btrim(family.root_family_booking_id)=pg_catalog.btrim(t.booking_id)
      left join public.weekly_source_entitlement_heads h on h.id=v_revision.source_head_id
      left join public.weekly_source_root_authorisations auth
        on auth.id=v_revision.source_event_id and v_revision.source_head_id is null
          and v_revision.source_kind='SOURCE'
      left join public.weekly_source_root_authorisations live_auth
        on live_auth.root_timesheet_id=t.timesheet_id and live_auth.withdrawn_at_utc is null
      left join public.timesheets_financials tf on tf.id=v_revision.financial_snapshot_id
      left join private.bpay_next_protected_source_receipt receipt
        on receipt.revision_id=v_revision.id and receipt.work_id=v_work.id
      left join public.weekly_exceptional_payment_approvals approval on approval.id=receipt.approval_id
      left join public.weekly_exceptional_pay_generations generation on generation.id=receipt.generation_id
      left join public.weekly_exceptional_orchestration_runs orchestration on orchestration.id=receipt.orchestration_run_id
      left join private.bpay_next_publication publication
        on publication.work_id=v_work.id and publication.revision_id=v_revision.id
      left join private.bpay_next_command command on command.id=publication.command_id
      left join private.bpay_next_command_member member
        on member.command_id=command.id and member.candidate_id=v_work.candidate_id
      where t.timesheet_id=v_revision.physical_timesheet_id;
    if not found or v_source_origin.root_exact is not true
       or v_source_origin.origin_exact is not true or v_source_origin.publication_exact is not true then
      raise exception using errcode='23514',message='BPAY_NEXT_PIN_SOURCE_ORIGIN_INVALID';
    end if;
    -- Consume the raw Source-owned gate captured for this exact ticked revision.
    select snapshot.gate_result into v_query_gate
      from private.bpay_next_run_work_query_snapshot snapshot
      where snapshot.run_id=v_run_id and snapshot.work_id=v_work.id
        and snapshot.expected_revision_id=v_revision.id
        and snapshot.physical_timesheet_id=v_revision.physical_timesheet_id;
    if not found then
      raise exception using errcode='23514',message='BPAY_NEXT_PIN_QUERY_SNAPSHOT_MISSING';
    end if;
    if (pg_catalog.jsonb_typeof(v_query_gate)='object'
        and v_query_gate ?& array['ok','code','scope','blocked','query_state_sha256']
        and v_query_gate-array['ok','code','scope','blocked','query_state_sha256']='{}'::jsonb
        and pg_catalog.jsonb_typeof(v_query_gate->'ok')='boolean'
        and pg_catalog.jsonb_typeof(v_query_gate->'code')='string') is not true then
      raise exception using errcode='23514',message='BPAY_NEXT_PIN_QUERY_RESPONSE_INVALID';
    end if;
    v_query_scope:=nullif(v_query_gate->'scope','null'::jsonb);
    if v_query_scope is not null then
      if (v_source_origin.scope_exact is true
          and pg_catalog.jsonb_typeof(v_query_scope)='object'
          and v_query_scope ?& array['root_timesheet_id','family_booking_id','target_family_id',
            'candidate_id','client_id','contract_id','week_ending_date','root_version','family_bound_version']
          and v_query_scope-array['root_timesheet_id','family_booking_id','target_family_id',
            'candidate_id','client_id','contract_id','week_ending_date','root_version','family_bound_version']='{}'::jsonb
          and pg_catalog.jsonb_typeof(v_query_scope->'root_timesheet_id')='string'
          and pg_catalog.jsonb_typeof(v_query_scope->'family_booking_id')='string'
          and pg_catalog.jsonb_typeof(v_query_scope->'candidate_id')='string'
          and pg_catalog.jsonb_typeof(v_query_scope->'client_id')='string'
          and pg_catalog.jsonb_typeof(v_query_scope->'contract_id')='string'
          and pg_catalog.jsonb_typeof(v_query_scope->'week_ending_date')='string'
          and pg_catalog.jsonb_typeof(v_query_scope->'root_version')='string'
          and v_query_scope->>'root_timesheet_id'=v_revision.physical_timesheet_id::text
          and v_query_scope->>'root_version'=v_revision.physical_timesheet_version::text
          and v_query_scope->>'family_booking_id'=v_work.booking_id
          and v_query_scope->>'candidate_id'=v_work.candidate_id::text
          and v_query_scope->>'client_id'=v_source_origin.client_id::text
          and v_query_scope->>'contract_id'=v_work.contract_id::text
          and v_query_scope->>'week_ending_date'=v_work.week_ending_date::text
          and v_query_scope->'target_family_id'=coalesce(pg_catalog.to_jsonb(v_source_origin.family_id::text),'null'::jsonb)
          and v_query_scope->'family_bound_version'=coalesce(pg_catalog.to_jsonb(v_source_origin.bound_version::text),'null'::jsonb)) is not true then
        raise exception using errcode='23514',message='BPAY_NEXT_PIN_QUERY_SCOPE_MISMATCH';
      end if;
    end if;
    v_query_digest:=null;
    if v_query_gate->'ok'='true'::jsonb then
      if (v_query_gate->>'code'='OK' and v_query_scope is not null
          and pg_catalog.jsonb_typeof(v_query_gate->'blocked')='boolean'
          and pg_catalog.jsonb_typeof(v_query_gate->'query_state_sha256')='string'
          and v_query_gate->>'query_state_sha256' ~ '^[0-9a-f]{64}$') is not true then
        raise exception using errcode='23514',message='BPAY_NEXT_PIN_QUERY_RESPONSE_INVALID';
      end if;
      -- The query Scope has no HEAD id. An available/current query root must
      -- never make a superseded or otherwise unmapped financial origin pay.
      -- Conversely an actual defined unavailable current scope retains its
      -- genuine immutable origin and reaches positive-WORK REVIEW below.
      if v_source_origin.financial_current is not true then
        raise exception using errcode='23514',message='BPAY_NEXT_PIN_SOURCE_AUTHORITY_CHANGED';
      end if;
      v_query_digest:=pg_catalog.decode(v_query_gate->>'query_state_sha256','hex');
      v_query_disposition:=case when v_query_gate->'blocked'='true'::jsonb then 'BLOCKED' else 'CLEAR' end;
    elsif ((v_query_gate->>'code'='WEEKLY_SOURCE_PAY_QUERY_SCOPE_UNAVAILABLE' and v_query_scope is null)
        or (v_query_gate->>'code'='WEEKLY_SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE' and v_query_scope is not null))
        and v_query_gate->'blocked'='null'::jsonb and v_query_gate->'query_state_sha256'='null'::jsonb then
      v_query_disposition:='UNAVAILABLE';
    else
      raise exception using errcode='23514',message='BPAY_NEXT_PIN_QUERY_RESPONSE_INVALID';
    end if;
  else
    v_query_disposition:=null;
  end if;
  insert into private.bpay_next_run_work
    (run_worker_id,candidate_id,work_id,captured_revision_id)
    values(v_worker_id,v_job.candidate_id,v_work.id,v_revision.id)
    returning id into v_run_work_id;
  if v_query_disposition is not null then
    insert into private.bpay_next_run_work_query_pin_v2
      (run_work_id,run_worker_id,candidate_id,work_id,captured_revision_id,
       prepare_job_id,module_epoch,gate_version,disposition,scope,query_state_sha256)
      values(v_run_work_id,v_worker_id,v_job.candidate_id,v_work.id,v_revision.id,
        p_job_id,v_module_epoch,'PAY_QUERY_STATE_V3',v_query_disposition,v_query_scope,v_query_digest);
  end if;
  if v_choice.selection_mode='SUBSET' then
    update private.bpay_next_run_worker
      set expected_selected_component_count=
        expected_selected_component_count+v_choice.component_count
      where id=v_worker_id;
  end if;
  update private.bpay_next_job
    set phase='PINNING',cursor_key=v_selection.selection_no::text
    where id=p_job_id;
  return pg_catalog.jsonb_build_object('done',false,'phase','PINNING',
    'next_cursor',v_selection.selection_no,'work_id',v_work.id,
    'captured_revision_id',v_revision.id,'replay',false);
end
$function$;


create or replace function private.bpay_next_prepare_case_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_cursor bigint default null,p_limit integer default 100
) returns jsonb
language plpgsql security invoker
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;v_run_id uuid;v_candidate uuid;v_saved_cursor bigint;
  v_run private.bpay_next_pay_run%rowtype;
  v_control private.bpay_next_worker_control%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_selection private.bpay_next_case_selection%rowtype;
  v_state private.bpay_next_case_allocation_state%rowtype;
  v_channel private.bpay_next_case_allocation_channel%rowtype;
  v_week private.bpay_next_worker_week%rowtype;
  v_case private.bpay_next_finance_case%rowtype;
  v_component private.bpay_next_case_component%rowtype;
  v_rule private.bpay_next_case_rule%rowtype;
  v_period_rule private.bpay_next_case_rule%rowtype;
  v_origin private.bpay_next_case_create_request%rowtype;
  v_collection private.bpay_next_work_collection%rowtype;
  v_policy_id uuid;
  v_automatic boolean;v_week_not_affected boolean;
  v_period private.bpay_next_case_period%rowtype;
  v_item record;v_prior record;v_value record;v_row record;
  v_instruction private.bpay_next_run_case_instruction%rowtype;
  v_floor numeric;v_outstanding numeric;v_case_outstanding numeric;
  v_nominal numeric;v_opening_due numeric;v_capacity numeric;v_taken numeric;v_e numeric;v_h numeric;
  v_next_e numeric;v_next_h numeric;
  v_gross numeric;v_week_start date;v_age timestamptz;v_age_key bigint;
  v_purpose text;v_explanation text;v_issue text;v_seen bigint:=0;
  v_result_id uuid;v_hold_id uuid;v_instruction_id uuid;v_has_more boolean;v_terminal boolean:=false;
  v_cap_reason text;v_affordability_reason text;v_capacity_reason text;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null or p_owner_epoch<1
     or p_expected_cursor<0 or p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode='22023',message='BPAY_NEXT_CASE_PREPARE_INPUT_INVALID';
  end if;
  select rc.run_id,j.candidate_id into strict v_run_id,v_candidate
    from private.bpay_next_job j join private.bpay_next_run_command rc on rc.command_id=j.command_id
    where j.id=p_job_id and j.job_kind='PREPARE';
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  -- Same lock order as the real lane; root UPDATE fences confirmation/cancel.
  select r.* into strict v_run from private.bpay_next_pay_run r where r.id=v_run_id for update;
  select c.* into strict v_control from private.bpay_next_worker_control c where c.candidate_id=v_candidate for update;
  select j.* into strict v_job from private.bpay_next_job j where j.id=p_job_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w
    where w.run_id=v_run_id and w.candidate_id=v_candidate for update;
  select s.* into v_state from private.bpay_next_case_allocation_state s where s.job_id=p_job_id
    and s.run_worker_id=v_worker.id and s.pass_kind='DRAFT' and s.projection_no=0 for update;
  if v_job.module_epoch<>v_epoch then
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_PREPARE_OWNER_STALE';
  end if;
  if v_job.status='DONE' and v_job.phase='READY' and v_state.status='COMPLETE'
     and v_worker.status in ('READY','DRAFT','ISSUED','COMPLETE','CANCELLING','CANCELLED') then
    return pg_catalog.jsonb_build_object('done',true,'phase','READY','cursor',null,'rows_visited','0',
      'replay',true,'run_worker_id',v_worker.id,'worker_status',v_worker.status);
  end if;
  if v_job.status='DONE' and v_job.phase='DONE' and v_worker.status='REVIEW'
     and v_worker.review_issue_code in ('CASE_SELECTION_REQUIRED','CASE_TARGET_UNSUPPORTED','CASE_INPUT_UNBOUND',
       'CASE_WEEK_BASIS_UNBOUND','CASE_RETURN_FLOOR_UNBOUND','CASE_NO_PAYABLE_AMOUNT') then
    return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW','cursor',null,'rows_visited','0',
      'replay',true,'run_worker_id',v_worker.id,'worker_status',v_worker.status,'issue_code',v_worker.review_issue_code);
  end if;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED' or v_job.status<>'LEASED'
     or v_job.phase<>'FINANCE_ALLOCATE' or v_job.lease_nonce<>p_lease_nonce or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() or v_control.active_owner_epoch<>p_owner_epoch
     or v_worker.status<>'PREPARING' or v_worker.review_issue_code is not null
     or v_worker.financial_resolution_count<>0 then
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_PREPARE_STATE_INVALID';
  end if;
  if v_worker.captured_position_count<>v_worker.captured_line_count+v_worker.captured_managed_position_count
     or v_worker.expected_managed_position_count<>v_worker.captured_managed_position_count
     or exists(select 1 from private.bpay_next_run_position where run_worker_id=v_worker.id
       and work_collection_id is not null and not managed_capture_completed) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_LINE_COUNT_MISMATCH';
  end if;
  if v_job.cursor_key is not null and v_job.cursor_key !~ '^[0-9]{1,19}$' then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_CURSOR_CORRUPT';
  end if;
  v_saved_cursor:=coalesce(v_job.cursor_key::bigint,0);
  if coalesce(p_expected_cursor,0)<v_saved_cursor then
    -- Lost STEP reply: read back the persisted checkpoint without a second
    -- capture, hold, cursor spend or financial-view bump. Ahead is not replay.
    return pg_catalog.jsonb_build_object('done',false,'phase','FINANCE_ALLOCATE','cursor',v_job.cursor_key,
      'rows_visited','0','replay',true,'run_worker_id',v_worker.id,'worker_status',v_worker.status);
  end if;
  if coalesce(p_expected_cursor,0)>v_saved_cursor then
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_PREPARE_CURSOR_STALE';
  end if;
  -- Only a positively proved no-case context may retain the old owner path.
  if v_state.id is null and not exists(select 1 from private.bpay_next_finance_case c where c.candidate_id=v_candidate)
     and not exists(select 1 from private.bpay_next_case_selection s where s.run_id=v_run_id and s.candidate_id=v_candidate) then
    return private.bpay_next_complete_no_case_worker_v1(p_job_id,p_lease_nonce,p_owner_epoch);
  end if;

  <<prepare_page>>
  begin
    -- A resumed weekly/capture/allocation page uses its exact frozen selection
    -- revision. Refuse Source origins before any stage writes, including when
    -- the collection's current qualification reader would return no row.
    if v_state.id is not null and exists(
      select 1 from private.bpay_next_case_selection_item si
      join private.bpay_next_work_collection c on c.case_id=si.case_id
        and c.case_component_id=si.case_component_id and c.candidate_id=si.candidate_id
      join private.bpay_next_work w on w.id=c.work_id and w.candidate_id=si.candidate_id
      where si.run_id=v_run_id and si.candidate_id=v_candidate
        and si.selection_revision=v_state.selection_revision and si.is_selected
        and w.work_kind='SOURCE') then
      raise exception using errcode='55000',message='BPAY_NEXT_COMPARISON_NOT_INSTALLED';
    end if;
    if v_state.id is null then
      select s.* into v_selection from private.bpay_next_case_selection s
        where s.run_id=v_run_id and s.candidate_id=v_candidate order by s.selection_revision desc limit 1;
      if v_selection.run_id is null or v_selection.status<>'SEALED' then
        v_issue:='CASE_SELECTION_REQUIRED';exit prepare_page;
      end if;
      -- Comparison is owned by the later CM chain. Existing immutable Source
      -- origin identity is enough to refuse it; no absent pack column/type or
      -- fabricated financial certificate is consulted or created here.
      if exists(select 1 from private.bpay_next_case_selection_item si
        join private.bpay_next_work_collection c on c.case_id=si.case_id
          and c.case_component_id=si.case_component_id and c.candidate_id=si.candidate_id
        join private.bpay_next_work w on w.id=c.work_id and w.candidate_id=si.candidate_id
        where si.run_id=v_run_id and si.candidate_id=v_candidate
          and si.selection_revision=v_selection.selection_revision and si.is_selected
          and w.work_kind='SOURCE') then
        raise exception using errcode='55000',message='BPAY_NEXT_COMPARISON_NOT_INSTALLED';
      end if;
      if v_worker.target_pay_channel<>'PAYE' or v_worker.gross_vat<>0
         or v_worker.gross_ex_vat<>v_worker.gross_inc_vat then
        v_issue:='CASE_TARGET_UNSUPPORTED';exit prepare_page;
      end if;
      select selected.min_take_home_wtd into strict v_floor from private.bpay_next_selection_candidate selected
        where selected.run_id=v_run_id and selected.candidate_id=v_candidate;
      if v_floor is null or v_floor::text in ('NaN','Infinity','-Infinity') or v_floor<0
         or v_floor<>pg_catalog.trunc(v_floor,2) then
        v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
      end if;
      v_week_start:=v_run.pay_date-(extract(isodow from v_run.pay_date)::integer-1);
      -- OVERPAYMENT gross recovery does not consume the protected-debt H/floor
      -- operand (0290). Prove the exact nonempty SEALED selected set, not merely
      -- that no protected row happened to be found. Missing identities/counts
      -- remain week-dependent; instruction capture and allocation re-prove it.
      select count(*)=v_selection.selected_count and count(*)>0
        and coalesce(bool_and((fc.case_kind,cc.case_kind,cc.instruction_kind,cc.payroll_stage)
          is not distinct from ('OVERPAYMENT','OVERPAYMENT','RECOVERY','GROSS_DEDUCT')),false)
        into v_week_not_affected
        from private.bpay_next_case_selection_item si
        left join private.bpay_next_case_component cc
          on cc.id=si.case_component_id and cc.case_id=si.case_id and cc.candidate_id=si.candidate_id
        left join private.bpay_next_finance_case fc on fc.id=si.case_id and fc.candidate_id=si.candidate_id
        where si.run_id=v_selection.run_id and si.candidate_id=v_selection.candidate_id
          and si.selection_revision=v_selection.selection_revision and si.is_selected;
      -- Exact indexed metadata absence is required BEFORE establishing a new
      -- zero week. Missing prior NEW facts are unresolved, not zero/history SUM.
      if not v_week_not_affected and exists(select 1 from private.bpay_next_run_worker w
        join private.bpay_next_pay_run r on r.id=w.run_id
        where w.candidate_id=v_candidate and w.status in ('READY','DRAFT','ISSUED','COMPLETE')
          and r.pay_date>=v_week_start and r.pay_date<v_week_start+7
          and (r.pay_date,r.created_at_utc,w.id)<(v_run.pay_date,v_run.created_at_utc,v_worker.id)
          and not exists(select 1 from private.bpay_next_worker_week_contribution x where x.original_run_worker_id=w.id)) then
        v_issue:='CASE_WEEK_BASIS_UNBOUND';exit prepare_page;
      end if;
      insert into private.bpay_next_worker_week(candidate_id,pay_week_start,period_revision,
        default_floor,default_floor_revision,resolved_arranged_take_home)
        values(v_candidate,v_week_start,1,v_floor,1,0) on conflict(candidate_id,pay_week_start) do nothing;
      select w.* into strict v_week from private.bpay_next_worker_week w
        where w.candidate_id=v_candidate and w.pay_week_start=v_week_start for update;
      if not v_week_not_affected and v_week.unresolved_contribution_count<>0 then v_issue:='CASE_WEEK_BASIS_UNBOUND';exit prepare_page;end if;
      if v_week.default_floor<>v_floor then
        update private.bpay_next_worker_week set default_floor=v_floor,default_floor_revision=default_floor_revision+1,
          period_revision=period_revision+1 where candidate_id=v_candidate and pay_week_start=v_week_start returning * into v_week;
      end if;
      update private.bpay_next_run_worker set case_selection_revision=v_selection.selection_revision where id=v_worker.id;
      v_worker.case_selection_revision:=v_selection.selection_revision;
      insert into private.bpay_next_case_allocation_state
        (run_worker_id,run_id,candidate_id,selection_revision,preparation_revision,pass_kind,projection_no,
         command_id,job_id,module_epoch,owner_epoch,financial_view_revision,status,weekly_binding_state,
         expected_instruction_count,initial_worker_take_home,remaining_worker_take_home,prepare_stage,
         captured_default_floor,captured_default_floor_revision,pay_week_start,captured_week_revision,captured_work_gross)
        values(v_worker.id,v_run_id,v_candidate,v_selection.selection_revision,v_worker.preparation_revision,'DRAFT',0,
         v_job.command_id,p_job_id,v_epoch,p_owner_epoch,v_control.financial_view_revision,'BUILDING',
         case when v_week_not_affected then 'NOT_AFFECTED' else 'UNBOUND' end,
         v_selection.selected_count,v_worker.gross_ex_vat,v_worker.gross_ex_vat,
         case when v_week_not_affected then 'INSTRUCTION_CAPTURE' else 'WEEK_CAPTURE' end,
         v_floor,v_week.default_floor_revision,v_week_start,v_week.period_revision,v_worker.gross_ex_vat)
        returning * into v_state;
      insert into private.bpay_next_case_allocation_channel(state_id,allocation_channel,initial_headroom,remaining_headroom)
        values(v_state.id,'PAYE',v_worker.gross_ex_vat,v_worker.gross_ex_vat);
    else
      if v_state.status<>'BUILDING' or v_state.preparation_revision<>v_worker.preparation_revision
         or v_state.selection_revision<>v_worker.case_selection_revision or v_state.prepare_stage='NOT_CASE_PREPARE' then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_BINDING_MISMATCH';
      end if;
      -- Lease takeover does not reset the captured economic cursors/headroom.
      if v_state.owner_epoch<>p_owner_epoch then
        update private.bpay_next_case_allocation_state set owner_epoch=p_owner_epoch where id=v_state.id;
        v_state.owner_epoch:=p_owner_epoch;
      end if;
    end if;

    if v_state.prepare_stage='WEEK_CAPTURE' then
      for v_prior in select x.* from private.bpay_next_worker_week_contribution x
        where x.candidate_id=v_candidate and x.pay_week_start=v_state.pay_week_start
          and (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)
            <(v_run.pay_date,v_run.created_at_utc,v_worker.id)
          and (v_state.prior_worker_cursor is null or
            (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)
              >(v_state.prior_pay_date_cursor,v_state.prior_created_at_cursor,v_state.prior_worker_cursor))
        order by x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id limit p_limit
      loop
        v_seen:=v_seen+1;
        if v_prior.eligibility_state='UNBOUND' then
          v_issue:=case when v_prior.payment_state in ('RETURNED_OWED','REISSUED_PAID')
            then 'CASE_RETURN_FLOOR_UNBOUND' else 'CASE_WEEK_BASIS_UNBOUND' end;
          exit prepare_page;
        end if;
        v_state.captured_prior_take_home:=v_state.captured_prior_take_home+v_prior.eligible_arranged_amount;
        v_state.initial_worker_take_home:=v_state.initial_worker_take_home+v_prior.eligible_arranged_amount;
        v_state.remaining_worker_take_home:=v_state.remaining_worker_take_home+v_prior.eligible_arranged_amount;
        v_state.prior_pay_date_cursor:=v_prior.original_pay_date;
        v_state.prior_created_at_cursor:=v_prior.original_created_at_utc;
        v_state.prior_worker_cursor:=v_prior.original_run_worker_id;
      end loop;
      select exists(select 1 from private.bpay_next_worker_week_contribution x
        where x.candidate_id=v_candidate and x.pay_week_start=v_state.pay_week_start
          and (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)<(v_run.pay_date,v_run.created_at_utc,v_worker.id)
          and (v_state.prior_worker_cursor is null or (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)
            >(v_state.prior_pay_date_cursor,v_state.prior_created_at_cursor,v_state.prior_worker_cursor))) into v_has_more;
      update private.bpay_next_case_allocation_state set captured_prior_take_home=v_state.captured_prior_take_home,
        initial_worker_take_home=v_state.initial_worker_take_home,remaining_worker_take_home=v_state.remaining_worker_take_home,
        prior_pay_date_cursor=v_state.prior_pay_date_cursor,prior_created_at_cursor=v_state.prior_created_at_cursor,
        prior_worker_cursor=v_state.prior_worker_cursor,weekly_binding_state=case when v_has_more then 'UNBOUND' else 'BOUND' end,
        prepare_stage=case when v_has_more then 'WEEK_CAPTURE' else 'INSTRUCTION_CAPTURE' end where id=v_state.id;
      exit prepare_page;
    end if;

    if v_state.prepare_stage='INSTRUCTION_CAPTURE' then
      for v_item in select i.* from private.bpay_next_case_selection_item i
        where i.run_id=v_run_id and i.candidate_id=v_candidate and i.selection_revision=v_state.selection_revision
          and i.is_selected and i.selection_no>v_state.instruction_capture_cursor order by i.selection_no limit p_limit
      loop
        v_seen:=v_seen+1;
        select c.* into strict v_case from private.bpay_next_finance_case c where c.id=v_item.case_id and c.candidate_id=v_candidate for update;
        select c.* into strict v_component from private.bpay_next_case_component c
          where c.id=v_item.case_component_id and c.case_id=v_case.id and c.candidate_id=v_candidate for update;
        select r.* into v_rule from private.bpay_next_case_rule r where r.id=v_case.current_rule_id
          and r.case_id=v_case.id and r.candidate_id=v_candidate and r.rule_revision=v_case.current_rule_revision;
        select r.* into v_origin from private.bpay_next_case_create_request r where r.case_id=v_case.id and r.candidate_id=v_candidate;
        -- Refuse the immutable selected identity before qualification: a stale
        -- Source collection must not disappear into an ordinary review path.
        if exists(select 1 from private.bpay_next_work_collection c
          join private.bpay_next_work w on w.id=c.work_id and w.candidate_id=c.candidate_id
          where c.case_id=v_case.id and c.case_component_id=v_component.id
            and c.candidate_id=v_candidate and w.work_kind='SOURCE') then
          raise exception using errcode='55000',message='BPAY_NEXT_COMPARISON_NOT_INSTALLED';
        end if;
        v_collection:=private.bpay_next_work_collection_origin_v1(v_case.id,v_component.id,v_candidate);
        v_automatic:=v_collection.id is not null;
        if v_state.weekly_binding_state='NOT_AFFECTED'
          and (v_case.case_kind,v_component.case_kind,v_component.instruction_kind,v_component.payroll_stage)
            is distinct from ('OVERPAYMENT','OVERPAYMENT','RECOVERY','GROSS_DEDUCT') then
          v_issue:='CASE_WEEK_BASIS_UNBOUND';exit prepare_page;
        end if;
        if v_rule.id is null or v_case.case_revision<1 or v_component.rule_id<>v_rule.id then
          v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
        end if;
        if v_automatic then
          -- Genuine paid WORK origin, not a fabricated CASE_CREATE receipt.
          -- The immutable original paid policy and the exact applied position
          -- are authority; a newer queued WORK approval is not a reprice.
          if v_origin.command_id is not null then v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;end if;
          v_policy_id:=v_collection.original_valuation_policy_id;
        elsif v_origin.command_id is null
           or v_component.rule_id<>v_rule.id or v_origin.case_kind<>v_case.case_kind
           or v_origin.source_pay_channel<>v_component.source_pay_channel
           or v_origin.principal_source_ex_vat<>v_component.approved_source_ex_vat
           or (v_component.id<>v_origin.primary_component_id
             and (v_origin.recovery_component_id is null or v_component.id<>v_origin.recovery_component_id))
           or (v_component.id=v_origin.primary_component_id and v_component.instruction_kind<>
             case when v_case.case_kind in ('LOAN','ADVANCE') then 'PAYOUT'
               when v_case.case_kind='CREDIT' then 'CREDIT' else 'RECOVERY' end)
           or (v_component.id=v_origin.recovery_component_id and v_component.instruction_kind<>'RECOVERY') then
          v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
        else
          v_policy_id:=v_origin.valuation_policy_id;
        end if;
        if v_component.source_pay_channel<>'PAYE' or v_worker.target_pay_channel<>'PAYE' then
          v_issue:='CASE_TARGET_UNSUPPORTED';exit prepare_page;
        end if;
        v_explanation:='Exact approved case; same-channel PAYE current basis captured';
        v_outstanding:=case when v_component.case_kind in ('LOAN','ADVANCE') then v_component.funded_source_ex_vat
          else v_component.approved_source_ex_vat end-v_component.recovered_source_ex_vat-v_component.written_off_source_ex_vat;
        v_case_outstanding:=case when v_case.case_kind in ('LOAN','ADVANCE') then v_case.principal_funded
          else v_case.principal_approved end-v_case.principal_recovered-v_case.principal_written_off-v_case.principal_paid_credit;
        if v_component.instruction_kind='RECOVERY' then
          if v_automatic then
            -- Retained automatic OVERPAYMENT policy has no instalment. Its
            -- remaining principal already excludes realised recovery and W;
            -- capacity below subtracts each disjoint active hold only once.
            v_nominal:=least(v_outstanding,v_case_outstanding);
            v_explanation:='Exact original ordinary PAYE collection; remaining outstanding, no instalment';
          else
          if v_rule.weekly_due_source_ex_vat is null then v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;end if;
          if v_case.case_kind in ('LOAN','ADVANCE') and v_case.principal_funded>0
             and (v_rule.original_funding_event_id is null or v_rule.original_funded_at_utc is null) then
            v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
          end if;
          v_nominal:=case when v_state.pay_week_start>=v_rule.next_due_monday
            then least(v_rule.weekly_due_source_ex_vat,v_outstanding,v_case_outstanding) else 0 end;
          if v_case.case_kind in ('LOAN','ADVANCE') and v_case.principal_funded=0 then
            v_nominal:=0;v_explanation:='Approved loan/advance is unfunded; repayment not eligible';
          elsif v_state.pay_week_start<v_rule.next_due_monday then
            v_explanation:='Repayment schedule is not yet due in the pay-date week';
          end if;
          end if;
          v_purpose:=case when v_component.payroll_stage='GROSS_DEDUCT' then 'GROSS_RECOVERY' else 'NET_RECOVERY_CAPACITY' end;
        else
          v_outstanding:=v_component.approved_source_ex_vat-v_component.funded_source_ex_vat
            -v_component.paid_credit_source_ex_vat-v_component.written_off_source_ex_vat;
          v_case_outstanding:=v_case.principal_approved-v_case.principal_funded
            -v_case.principal_paid_credit-v_case.principal_written_off;
          v_nominal:=least(v_outstanding,v_case_outstanding);v_purpose:='PAYOUT';
        end if;
        -- Weekly due exists independently of this particular arrangement's
        -- eligibility. An early/paused selection must not make the whole
        -- week's legitimate opening due permanently zero for later pay dates.
        v_opening_due:=case when v_component.instruction_kind='RECOVERY' then v_nominal else 0 end;
        if v_case.status<>'OPEN' or (v_case.due_date is not null and v_case.due_date>v_run.pay_date) then
          v_nominal:=0;v_explanation:='Selected case is not currently open/due; no reservation';
        end if;
        if v_outstanding<0 or v_case_outstanding<0 or v_nominal<0 then
          v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
        end if;
        -- Opening due is independent of later principal. Never subtract the
        -- same realised recovery twice or use max(overlapping counters).
        insert into private.bpay_next_case_period(case_component_id,case_id,candidate_id,pay_week_start,rule_id,
          period_revision,opening_outstanding_source_ex_vat,opening_due_source_ex_vat,work_collection_id)
          values(v_component.id,v_case.id,v_candidate,v_state.pay_week_start,v_rule.id,1,v_outstanding,
            v_opening_due,case when v_automatic then v_collection.id else null end)
          on conflict(case_component_id,pay_week_start) do nothing;
        select p.* into strict v_period from private.bpay_next_case_period p
          where p.case_component_id=v_component.id and p.pay_week_start=v_state.pay_week_start for update;
        if v_period.work_collection_id is distinct from (case when v_automatic then v_collection.id else null end) then
          v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
        end if;
        if v_period.rule_id<>v_rule.id then
          -- Genuine original funding advances an immutable loan rule solely
          -- to bind its age/evidence. It is NOT a schedule/policy reprice.
          select * into strict v_period_rule from private.bpay_next_case_rule where id=v_period.rule_id;
          if v_case.case_kind not in ('LOAN','ADVANCE') or v_rule.original_funding_event_id is null
             or (v_period_rule.case_id,v_period_rule.candidate_id,v_period_rule.case_kind,v_period_rule.case_subtype,
               v_period_rule.tax_treatment,v_period_rule.case_created_at_utc,v_period_rule.minimum_earnings_threshold,
               v_period_rule.take_home_floor_override,v_period_rule.weekly_due_source_ex_vat,v_period_rule.schedule_start_monday,
               v_period_rule.next_due_monday,v_period_rule.schedule_week_count)
               is distinct from (v_rule.case_id,v_rule.candidate_id,v_rule.case_kind,v_rule.case_subtype,
                 v_rule.tax_treatment,v_rule.case_created_at_utc,v_rule.minimum_earnings_threshold,v_rule.take_home_floor_override,
                 v_rule.weekly_due_source_ex_vat,v_rule.schedule_start_monday,v_rule.next_due_monday,v_rule.schedule_week_count)
             or not exists(select 1 from private.bpay_next_case_event e where e.id=v_rule.original_funding_event_id
               and e.case_id=v_case.id and e.event_kind='FUNDED' and e.occurred_at_utc=v_rule.original_funded_at_utc)
             or (v_period_rule.original_funding_event_id is not null and
               (v_period_rule.original_funding_event_id,v_period_rule.original_funded_at_utc)
                 is distinct from (v_rule.original_funding_event_id,v_rule.original_funded_at_utc)) then
            v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
          end if;
          if v_component.instruction_kind='RECOVERY' and v_period_rule.original_funding_event_id is null then
            if (v_period.opening_outstanding_source_ex_vat,v_period.opening_due_source_ex_vat,
                v_period.realised_recovery_source_ex_vat,v_period.active_unrealised_recovery_source_ex_vat,v_period.active_payout_source_ex_vat)
                is distinct from (0::numeric,0::numeric,0::numeric,0::numeric,0::numeric) then
              v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
            end if;
            -- Only this exact zero/unconsumed pay-week is made ready. Its
            -- frozen old zero instructions/results remain immutable and zero.
            update private.bpay_next_case_period set rule_id=v_rule.id,opening_outstanding_source_ex_vat=v_outstanding,
              opening_due_source_ex_vat=v_opening_due,period_revision=period_revision+1
              where case_component_id=v_component.id and pay_week_start=v_state.pay_week_start returning * into v_period;
          end if;
          -- A consumed funded period (or original payout period) retains its
          -- recorded opening rule and counters; only the new instruction's
          -- captured_rule_id/age advance to the genuine current funded rule.
        end if;
        v_capacity:=case when v_automatic then
          least(v_nominal,greatest(v_outstanding-v_component.active_recovery_source_ex_vat,0),
            greatest(v_case_outstanding-v_case.active_recovery_hold_amount,0))
          when v_component.instruction_kind='RECOVERY' then
          least(v_nominal,greatest(v_period.opening_due_source_ex_vat-v_period.realised_recovery_source_ex_vat
            -v_period.active_unrealised_recovery_source_ex_vat,0),
            greatest(v_outstanding-v_component.active_recovery_source_ex_vat,0),
            greatest(v_case_outstanding-v_case.active_recovery_hold_amount,0))
          else least(v_nominal,greatest(v_outstanding-v_component.active_payout_source_ex_vat,0),
            greatest(v_case_outstanding-v_case.active_payout_hold_amount,0)) end;
        begin
          select x.* into strict v_value from private.bpay_next_value_source_for_target_v1(
            v_component.approved_source_ex_vat,'PAYE','PAYE',null,v_policy_id,v_run.pay_date) x;
        exception when check_violation then
          if sqlerrm in ('BPAY_NEXT_TARGET_POLICY_WINDOW_MISSING','BPAY_NEXT_TARGET_POLICY_WINDOW_AMBIGUOUS') then
            v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
          else raise;end if;
        end;
        if v_value.target_ex_vat<>v_component.approved_source_ex_vat or v_value.target_vat<>0
           or v_value.target_inc_vat<>v_value.target_ex_vat then
          v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
        end if;
        update private.bpay_next_case_component set resolution_state='RESOLVED',target_pay_channel='PAYE',
          target_ex_vat=v_value.target_ex_vat,target_vat=0,target_inc_vat=v_value.target_inc_vat,
          valuation_policy_id=v_policy_id,valuation_window_id=v_value.policy_window_id,
          resolution_ref=case when v_automatic then 'WORK_COLLECTION:'||v_collection.id::text||':PAYE'
            else 'CASE_CREATE:'||v_origin.command_id::text||':PAYE' end,component_revision=component_revision+1,
          updated_at_utc=pg_catalog.transaction_timestamp() where id=v_component.id returning * into v_component;
        v_age:=coalesce(v_rule.original_funded_at_utc,v_rule.case_created_at_utc);
        -- A genuinely bound stored credit keeps its original creator age. The
        -- exact point sidecar is immutable, not a live legacy money read.
        if not v_automatic then
          select coalesce(o.original_created_at_utc,v_age) into v_age
            from (select 1) s left join private.bpay_next_stored_credit_origin o
              on o.command_id=v_component.id and o.candidate_id=v_candidate;
        end if;
        v_age_key:=(extract(epoch from v_age)*1000000)::bigint;
        insert into private.bpay_next_run_case_instruction
          (run_worker_id,run_id,candidate_id,selection_revision,preparation_revision,case_component_id,case_id,
           captured_case_revision,captured_component_revision,captured_period_revision,rule_id,rule_revision,
           case_kind,case_subtype,tax_treatment,instruction_kind,direction,payroll_stage,hold_purpose,
           age_key,debt_age_at_utc,component_ordinal,pay_week_start,source_pay_channel,target_pay_channel,allocation_channel,currency,
           nominal_source_ex_vat,nominal_target_ex_vat,nominal_target_vat,nominal_target_inc_vat,
           capacity_source_ex_vat,capacity_target_ex_vat,capacity_target_vat,capacity_target_inc_vat,
           minimum_earnings_threshold,take_home_floor_override,captured_default_floor,captured_default_floor_revision,
           resolved_take_home_floor,valuation_policy_id,valuation_window_id,resolution_ref,explanation,work_collection_id)
          values(v_worker.id,v_run_id,v_candidate,v_state.selection_revision,v_worker.preparation_revision,v_component.id,v_case.id,
           v_case.case_revision,v_component.component_revision,v_period.period_revision,v_rule.id,v_rule.rule_revision,
           v_component.case_kind,v_component.case_subtype,v_component.tax_treatment,v_component.instruction_kind,
           v_component.direction,v_component.payroll_stage,v_purpose,v_age_key,v_age,v_component.component_ordinal,
           v_state.pay_week_start,'PAYE','PAYE','PAYE','GBP',v_nominal,v_nominal,0,v_nominal,v_capacity,v_capacity,0,v_capacity,
           v_rule.minimum_earnings_threshold,v_rule.take_home_floor_override,v_state.captured_default_floor,
           v_state.captured_default_floor_revision,coalesce(v_rule.take_home_floor_override,v_state.captured_default_floor),
           v_policy_id,v_value.policy_window_id,v_component.resolution_ref,v_explanation,
           case when v_automatic then v_collection.id else null end)
          returning id into v_instruction_id;
        perform private.bpay_next_capture_instruction_destination_v1(v_instruction_id);
        v_state.instruction_capture_cursor:=v_item.selection_no;
        v_state.captured_instruction_count:=v_state.captured_instruction_count+1;
        if v_component.payroll_stage='NET_ADD' then v_state.payout_instruction_count:=v_state.payout_instruction_count+1;end if;
        update private.bpay_next_run_worker set case_instruction_count=case_instruction_count+1 where id=v_worker.id;
      end loop;
      select exists(select 1 from private.bpay_next_case_selection_item i where i.run_id=v_run_id
        and i.candidate_id=v_candidate and i.selection_revision=v_state.selection_revision and i.is_selected
        and i.selection_no>v_state.instruction_capture_cursor) into v_has_more;
      if not v_has_more and v_state.captured_instruction_count<>v_state.expected_instruction_count then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_CAPTURE_COUNT_MISMATCH';
      end if;
      update private.bpay_next_case_allocation_state set instruction_capture_cursor=v_state.instruction_capture_cursor,
        captured_instruction_count=v_state.captured_instruction_count,payout_instruction_count=v_state.payout_instruction_count,
        prepare_stage=case when v_has_more then 'INSTRUCTION_CAPTURE' else 'ALLOCATE' end where id=v_state.id;
      exit prepare_page;
    end if;

    if v_state.weekly_binding_state='NOT_AFFECTED' then
      -- Only frozen instructions are authoritative from this point. This
      -- scalar metadata proof is scoped to this exact run worker/revisions;
      -- it never reconstructs money or reads prior payment history.
      select count(*)=v_state.expected_instruction_count and count(*)>0
        and coalesce(bool_and((i.case_kind,i.instruction_kind,i.payroll_stage,i.hold_purpose)
          is not distinct from ('OVERPAYMENT','RECOVERY','GROSS_DEDUCT','GROSS_RECOVERY')
          and si.case_id is not null),false)
        into v_week_not_affected
        from private.bpay_next_run_case_instruction i
        left join private.bpay_next_case_selection_item si
          on si.run_id=i.run_id and si.candidate_id=i.candidate_id and si.selection_revision=i.selection_revision
            and si.case_id=i.case_id and si.case_component_id=i.case_component_id and si.is_selected
        where i.run_worker_id=v_worker.id and i.run_id=v_run_id and i.candidate_id=v_candidate
          and i.preparation_revision=v_worker.preparation_revision and i.selection_revision=v_state.selection_revision;
      if not v_week_not_affected
        or v_state.captured_instruction_count<>v_state.expected_instruction_count
        or v_worker.case_instruction_count<>v_state.expected_instruction_count
        or not exists(select 1 from private.bpay_next_case_selection cs where cs.run_id=v_run_id
          and cs.candidate_id=v_candidate and cs.selection_revision=v_state.selection_revision
          and cs.status='SEALED' and cs.selected_count=v_state.expected_instruction_count) then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_ALLOCATION_NOT_BOUND';
      end if;
    end if;
    if v_state.prepare_stage<>'ALLOCATE' or v_state.weekly_binding_state not in ('BOUND','NOT_AFFECTED') then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_ALLOCATION_NOT_BOUND';
    end if;
    select c.* into strict v_channel from private.bpay_next_case_allocation_channel c
      where c.state_id=v_state.id and c.allocation_channel='PAYE' for update;
    v_e:=v_channel.remaining_headroom;v_h:=v_state.remaining_worker_take_home;
    for v_instruction in select i.* from private.bpay_next_run_case_instruction i
      where i.run_worker_id=v_worker.id and i.preparation_revision=v_worker.preparation_revision
        and i.selection_revision=v_state.selection_revision
        and (v_state.cursor_case_component_id is null or (i.age_key,i.case_id,i.component_ordinal,i.case_component_id)
          >(v_state.cursor_age_key,v_state.cursor_case_id,v_state.cursor_component_ordinal,v_state.cursor_case_component_id))
      order by i.age_key,i.case_id,i.component_ordinal,i.case_component_id limit p_limit
    loop
      v_seen:=v_seen+1;
      if v_instruction.hold_purpose='PAYOUT' then
        v_taken:=least(v_instruction.nominal_target_ex_vat,v_instruction.capacity_target_ex_vat);
        v_cap_reason:=null;v_affordability_reason:=null;
        v_capacity_reason:=case when v_instruction.capacity_target_ex_vat<v_instruction.nominal_target_ex_vat then 'CASE_CAPACITY' else null end;
        v_next_e:=v_e;v_next_h:=v_h;
      else
        select x.* into strict v_row from private.bpay_next_case_allocation_row_v1(v_instruction.case_kind,
          v_instruction.nominal_target_ex_vat,v_instruction.capacity_target_ex_vat,v_e,v_h,
          v_instruction.minimum_earnings_threshold,v_instruction.take_home_floor_override,v_instruction.captured_default_floor) x;
        v_taken:=v_row.taken_amount;v_cap_reason:=v_row.cap_reason;
        v_affordability_reason:=v_row.affordability_reason;v_capacity_reason:=v_row.capacity_reason;
        v_next_e:=v_row.next_channel_headroom;v_next_h:=v_row.next_worker_take_home;
      end if;
      insert into private.bpay_next_case_allocation_result
        (state_id,instruction_id,run_worker_id,candidate_id,preparation_revision,selection_revision,result_no,
         pass_kind,allocation_channel,hold_purpose,nominal_target_ex_vat,usable_capacity_target_ex_vat,
         allocated_source_ex_vat,allocated_target_ex_vat,allocated_target_vat,allocated_target_inc_vat,shortfall_target_ex_vat,
         cap_reason,affordability_reason,capacity_reason,channel_headroom_before,channel_headroom_after,worker_take_home_before,worker_take_home_after)
        values(v_state.id,v_instruction.id,v_worker.id,v_candidate,v_worker.preparation_revision,v_state.selection_revision,
         v_state.processed_instruction_count+1,'DRAFT','PAYE',v_instruction.hold_purpose,v_instruction.nominal_target_ex_vat,
         v_instruction.capacity_target_ex_vat,v_taken,v_taken,0,v_taken,v_instruction.nominal_target_ex_vat-v_taken,
         v_cap_reason,v_affordability_reason,v_capacity_reason,v_e,v_next_e,v_h,v_next_h)
        returning id into v_result_id;
      if v_taken>0 then
        select c.* into strict v_case from private.bpay_next_finance_case c where c.id=v_instruction.case_id for update;
        select c.* into strict v_component from private.bpay_next_case_component c where c.id=v_instruction.case_component_id for update;
        select p.* into strict v_period from private.bpay_next_case_period p
          where p.case_component_id=v_component.id and p.pay_week_start=v_instruction.pay_week_start for update;
        insert into private.bpay_next_case_hold
          (run_worker_id,candidate_id,case_id,amount,status,instruction_id,allocation_result_id,allocation_pass_kind,
           case_component_id,purpose,pay_week_start,source_reserved_ex_vat,target_amount_ex_vat,target_amount_vat,target_amount_inc_vat)
          values(v_worker.id,v_candidate,v_case.id,v_taken,'ACTIVE',v_instruction.id,v_result_id,'DRAFT',
           v_component.id,v_instruction.hold_purpose,v_instruction.pay_week_start,v_taken,v_taken,0,v_taken) returning id into v_hold_id;
        insert into private.bpay_next_case_capacity_use(case_hold_id,case_component_id,case_id,candidate_id,
          pay_week_start,purpose,status,source_amount_ex_vat)
          values(v_hold_id,v_component.id,v_case.id,v_candidate,v_instruction.pay_week_start,v_instruction.hold_purpose,'ACTIVE',v_taken);
        if v_instruction.hold_purpose='PAYOUT' then
          update private.bpay_next_case_component set active_payout_source_ex_vat=active_payout_source_ex_vat+v_taken,
            component_revision=component_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_component.id;
          update private.bpay_next_finance_case set active_payout_hold_amount=active_payout_hold_amount+v_taken,
            active_hold_amount=active_hold_amount+v_taken,case_revision=case_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_case.id;
          update private.bpay_next_case_period set active_payout_source_ex_vat=active_payout_source_ex_vat+v_taken,
            period_revision=period_revision+1 where case_component_id=v_component.id and pay_week_start=v_instruction.pay_week_start;
        else
          update private.bpay_next_case_component set active_recovery_source_ex_vat=active_recovery_source_ex_vat+v_taken,
            component_revision=component_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_component.id;
          update private.bpay_next_finance_case set active_recovery_hold_amount=active_recovery_hold_amount+v_taken,
            active_hold_amount=active_hold_amount+v_taken,case_revision=case_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_case.id;
          update private.bpay_next_case_period set active_unrealised_recovery_source_ex_vat=active_unrealised_recovery_source_ex_vat+v_taken,
            period_revision=period_revision+1 where case_component_id=v_component.id and pay_week_start=v_instruction.pay_week_start;
          v_state.recovered_source_total:=v_state.recovered_source_total+v_taken;
          v_state.recovered_target_total:=v_state.recovered_target_total+v_taken;
        end if;
        update private.bpay_next_run_worker set active_case_hold_count=active_case_hold_count+1 where id=v_worker.id;
      end if;
      if v_instruction.payroll_stage='GROSS_ADD' then v_state.allocated_gross_additions:=v_state.allocated_gross_additions+v_taken;
      elsif v_instruction.payroll_stage='GROSS_DEDUCT' then v_state.allocated_gross_deductions:=v_state.allocated_gross_deductions+v_taken;
      elsif v_instruction.payroll_stage='NET_ADD' then v_state.allocated_net_additions:=v_state.allocated_net_additions+v_taken;end if;
      v_e:=v_next_e;v_h:=v_next_h;
      v_state.processed_instruction_count:=v_state.processed_instruction_count+1;
      v_state.cursor_age_key:=v_instruction.age_key;v_state.cursor_case_id:=v_instruction.case_id;
      v_state.cursor_component_ordinal:=v_instruction.component_ordinal;v_state.cursor_case_component_id:=v_instruction.case_component_id;
      update private.bpay_next_run_worker set case_allocated_count=case_allocated_count+1 where id=v_worker.id;
    end loop;
    update private.bpay_next_case_allocation_channel set remaining_headroom=v_e where state_id=v_state.id and allocation_channel='PAYE';
    update private.bpay_next_case_allocation_state set processed_instruction_count=v_state.processed_instruction_count,
      remaining_worker_take_home=v_h,recovered_source_total=v_state.recovered_source_total,recovered_target_total=v_state.recovered_target_total,
      cursor_age_key=v_state.cursor_age_key,cursor_case_id=v_state.cursor_case_id,cursor_component_ordinal=v_state.cursor_component_ordinal,
      cursor_case_component_id=v_state.cursor_case_component_id,allocated_gross_additions=v_state.allocated_gross_additions,
      allocated_gross_deductions=v_state.allocated_gross_deductions,allocated_net_additions=v_state.allocated_net_additions where id=v_state.id;
    select exists(select 1 from private.bpay_next_run_case_instruction i where i.run_worker_id=v_worker.id
      and i.preparation_revision=v_worker.preparation_revision and i.selection_revision=v_state.selection_revision
      and (v_state.cursor_case_component_id is null or (i.age_key,i.case_id,i.component_ordinal,i.case_component_id)
        >(v_state.cursor_age_key,v_state.cursor_case_id,v_state.cursor_component_ordinal,v_state.cursor_case_component_id))) into v_has_more;
    if not v_has_more then
      if v_state.processed_instruction_count<>v_state.expected_instruction_count then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_ALLOCATION_COUNT_MISMATCH';
      end if;
      v_gross:=v_state.captured_work_gross+v_state.allocated_gross_additions-v_state.allocated_gross_deductions;
      if v_gross<0 or v_gross>=10000000000000000 or v_state.allocated_net_additions>=10000000000000000 then
        v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
      end if;
      -- Preserve certified-zero WORK/Source rows; case-only NET additions are
      -- real payable cash, not a made-up positive payroll gross or net.
      if v_worker.captured_line_count=0 and v_gross=0 and v_state.allocated_net_additions=0 then
        v_issue:='CASE_NO_PAYABLE_AMOUNT';exit prepare_page;
      end if;
      if v_worker.captured_line_count=0 and v_gross=0 and v_state.payout_instruction_count>0 then
        insert into private.bpay_next_case_payout_basis(run_worker_id,candidate_id,preparation_revision,currency,
          beneficiary_kind,beneficiary_id,expected_instruction_count,captured_instruction_count,source_total_ex_vat,
          target_total_ex_vat,target_total_vat,target_total_inc_vat,status)
          values(v_worker.id,v_candidate,v_worker.preparation_revision,'GBP','CANDIDATE',v_candidate,
            v_state.payout_instruction_count,v_state.payout_instruction_count,v_state.allocated_net_additions,
            v_state.allocated_net_additions,0,v_state.allocated_net_additions,'SEALED');
      end if;
      select w.* into strict v_week from private.bpay_next_worker_week w
        where w.candidate_id=v_candidate and w.pay_week_start=v_state.pay_week_start for update;
      insert into private.bpay_next_worker_week_contribution(candidate_id,pay_week_start,original_run_worker_id,
        original_pay_date,original_created_at_utc,contribution_revision,basis_kind,original_gross_amount,
        payment_state,eligibility_state,eligible_arranged_amount,primary_binding_revision)
        values(v_candidate,v_state.pay_week_start,v_worker.id,v_run.pay_date,v_run.created_at_utc,1,'GROSS_FALLBACK',
          v_gross,'ARRANGED',case when v_gross>0 then 'ELIGIBLE' else 'EXCLUDED' end,v_gross,1);
      update private.bpay_next_worker_week set resolved_arranged_take_home=resolved_arranged_take_home+v_gross,
        period_revision=period_revision+1 where candidate_id=v_candidate and pay_week_start=v_state.pay_week_start;
      update private.bpay_next_case_allocation_state set status='COMPLETE',prepare_stage='COMPLETE',
        completed_at_utc=pg_catalog.transaction_timestamp() where id=v_state.id;
      update private.bpay_next_run_worker set gross_ex_vat=v_gross,gross_vat=0,gross_inc_vat=v_gross,
        status='READY',case_pending_binding_count=0 where id=v_worker.id;
      update private.bpay_next_job set status='DONE',phase='READY',cursor_key=null,lease_nonce=null,lease_until_utc=null,
        position_work_cursor=null,position_component_cursor=null where id=p_job_id;
      v_terminal:=true;
    end if;
  end prepare_page;

  if v_issue is not null then
    -- Candidate-wide issue: WORK FK remains NULL. Earlier frozen WORK and any
    -- already-created ACTIVE reservations remain exact and non-confirmable.
    update private.bpay_next_run_worker set status='REVIEW',review_issue_code=v_issue,review_issue_work_id=null,
      financial_resolution_count=financial_resolution_count+1,case_pending_binding_count=
        case when v_issue in ('CASE_SELECTION_REQUIRED','CASE_INPUT_UNBOUND','CASE_WEEK_BASIS_UNBOUND','CASE_RETURN_FLOOR_UNBOUND') then 1 else 0 end
      where id=v_worker.id;
    if v_state.id is not null then
      update private.bpay_next_case_allocation_state set prepare_stage='REVIEW',weekly_binding_state='UNBOUND',
        instruction_capture_cursor=v_state.instruction_capture_cursor,captured_instruction_count=v_state.captured_instruction_count,
        payout_instruction_count=v_state.payout_instruction_count where id=v_state.id;
    end if;
    update private.bpay_next_job set status='DONE',phase='DONE',cursor_key=null,lease_nonce=null,lease_until_utc=null,
      position_work_cursor=null,position_component_cursor=null where id=p_job_id;
    v_terminal:=true;
  elsif not v_terminal then
    update private.bpay_next_job set cursor_key=(v_saved_cursor+1)::text where id=p_job_id;
  end if;
  update private.bpay_next_worker_control set financial_view_revision=financial_view_revision+1,
    updated_at_utc=pg_catalog.transaction_timestamp() where candidate_id=v_candidate;
  return pg_catalog.jsonb_build_object('done',v_terminal,'phase',case when v_issue is not null then 'REVIEW'
    when v_terminal then 'READY' else 'FINANCE_ALLOCATE' end,'cursor',case when v_terminal then null else (v_saved_cursor+1)::text end,
    'rows_visited',v_seen::text,'replay',false,'run_worker_id',v_worker.id,
    'worker_status',case when v_issue is not null then 'REVIEW' when v_terminal then 'READY' else 'PREPARING' end)
    ||case when v_issue is not null then pg_catalog.jsonb_build_object('issue_code',v_issue) else '{}'::jsonb end;
end
