      where id=p_run_id;
  end if;
  return pg_catalog.jsonb_build_object('sealed',true,'selection_revision',p_selection_revision::text,
    'selected_count',v_header.selected_count::text,'excluded_count',v_header.excluded_count::text,'replay',false);
