-- CONTACT_PREPARER_UNIT 83 repeatable supabase/repeatable/12102026_2227_banking_pay_next_accepted_resolution_pin_v1.sql SHA256 95d98279b706eec18a2f64f9685b4b29d172c5c7463c4923c2926f93d01dee77
-- Repeatable CloudTMS function/view authority: banking_pay_next_accepted_resolution_pin_v1
-- Use CREATE OR REPLACE and preserve owner, security, search_path, and ACL contracts.





-- WB29 / BD158: only the accepted cut reads live ACTIVE treatment.
create or replace function private.bpay_next_accepted_resolution_refs_v1(
 p_run_id uuid,p_work_id uuid,p_boundary_revision_id uuid
) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,private
as $function$
declare
 r private.bpay_next_work_revision%rowtype;w private.bpay_next_work%rowtype;
 run private.bpay_next_pay_run%rowtype;c public.candidates%rowtype;u public.umbrellas%rowtype;
 d private.bpay_next_component_resolution%rowtype;active record;
 v_line uuid;v_refs jsonb:='[]';v_seen integer:=0;v_keys text[]:='{}';v_key text;
 v_target text;v_umbrella uuid;v_vat boolean;
begin
 if p_run_id is null or p_work_id is null or p_boundary_revision_id is null then
  raise exception using errcode='22023',message='BPAY_NEXT_RESOLUTION_IDENTITY_INVALID';end if;
 select x.* into w from private.bpay_next_work x where x.id=p_work_id;
 select x.* into r from private.bpay_next_work_revision x where x.id=p_boundary_revision_id and x.work_id=p_work_id;
 select x.* into run from private.bpay_next_pay_run x where x.id=p_run_id;
 select x.* into c from public.candidates x where x.id=w.candidate_id;
 select x.* into u from public.umbrellas x where x.id=c.umbrella_id;
 if w.id is null or r.id is null or r.approved_at_utc is null or r.sealed_at_utc is null
  or run.id is null or run.pay_date is null or c.id is null or c.active is not true
  or upper(c.pay_method) not in ('PAYE','UMBRELLA') or c.pay_method is null
  or (upper(c.pay_method)='UMBRELLA' and (u.id is null or u.enabled is not true or u.vat_chargeable is null)) then
  raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_ACCEPTED_CONTEXT_INVALID';end if;
 v_target:=upper(c.pay_method);v_umbrella:=case when v_target='UMBRELLA' then u.id end;
 v_vat:=case when v_target='UMBRELLA' then u.vat_chargeable end;
 -- Physical mapped-boundary candidates first, compatibility after bounded cut.
 -- No approval-child enumeration, financial history or late ACTIVE fallback.
 for d in select x.* from private.bpay_next_component_resolution x where x.work_id=p_work_id and x.state='ACTIVE'
   and (x.based_on_revision_id=p_boundary_revision_id or x.published_revision_id=p_boundary_revision_id)
   order by case when x.based_on_revision_id=p_boundary_revision_id then x.approved_line_id else x.published_line_id end,
    x.rate_family,x.rate_code,x.id limit 101 loop
  v_seen:=v_seen+1;
  if v_seen>100 then raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
  if (d.candidate_id,d.target_pay_channel,d.target_umbrella_id,d.target_umbrella_vat_chargeable,d.valuation_policy_id,d.valuation_date)
   is distinct from (w.candidate_id,v_target,v_umbrella,v_vat,r.valuation_policy_id,run.pay_date) then continue;end if;
  v_line:=case when d.based_on_revision_id=p_boundary_revision_id then d.approved_line_id else d.published_line_id end;
  select x.* into active from private.bpay_next_component_resolution_active_v1(p_work_id,p_boundary_revision_id,v_line,
   d.rate_family,d.rate_code,v_target,v_umbrella,v_vat,r.valuation_policy_id,run.pay_date) x;
  if active.id is distinct from d.id or active.decision_version is distinct from d.decision_version then
   raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_ACCEPTED_BASIS_CHANGED';end if;
  v_key:=jsonb_build_array(v_line,d.rate_family,d.rate_code)::text;
  if v_key=any(v_keys) then raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_COMPATIBILITY_AMBIGUOUS';end if;
  v_keys:=array_append(v_keys,v_key);
  v_refs:=v_refs||jsonb_build_array(jsonb_build_object('approved_line_id',v_line,
   'rate_family',d.rate_family,'rate_code',d.rate_code,'decision_id',d.id,'decision_version',d.decision_version::text));
 end loop;
 if octet_length(v_refs::text)>32768 then
  raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
 return v_refs;
end
$function$;

