-- Complete latest Create/guard successors; only accepted-reference additions.
create or replace function private.bpay_next_work_choice_guard_v1()
returns trigger language plpgsql security definer
set search_path=pg_catalog,private
as $function$
declare
  v_run private.bpay_next_pay_run%rowtype;v_choice private.bpay_next_work_choice%rowtype;
  v_page private.bpay_next_component_selection_page%rowtype;v_count integer;
begin
  if tg_op='DELETE' then
    raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_IMMUTABLE';
  end if;
  if tg_op='UPDATE' and tg_table_name<>'bpay_next_work_choice' then
    raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_IMMUTABLE';
  end if;
  select r.* into strict v_run from private.bpay_next_pay_run r
    where r.id=new.run_id for update;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'OPEN' then
    raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_NOT_OPEN';
  end if;
  if tg_table_name='bpay_next_work_choice' and tg_op='INSERT' then
    -- Original choice construction only, under the exact Work lock. This also
    -- covers retained manifest callers; no delayed capture can refill it.
    perform 1 from private.bpay_next_work where id=new.work_id for share;
    -- WB29: exact accepted references, before SelectionCandidate is inserted.
    if new.accepted_resolution_refs is not null and new.accepted_resolution_refs is distinct from
      private.bpay_next_accepted_resolution_refs_v1(new.run_id,new.work_id,new.expected_revision_id) then
      raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_ACCEPTED_BASIS_CHANGED';end if;
    select w.pay_hold_control_version,w.pay_hold_changed_at_utc,t.timesheet_id,tf.id,
      coalesce(tf.pay_on_hold,false),case when tf.pay_on_hold then tf.pay_on_hold_reason end
      into new.pay_hold_control_version,new.pay_hold_changed_at_utc,new.pay_hold_physical_timesheet_id,
        new.pay_hold_financial_id,new.pay_hold,new.pay_hold_reason
      from private.bpay_next_work w left join public.timesheets t on t.booking_id=w.booking_id and t.is_current
      left join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current where w.id=new.work_id;
  end if;
  if tg_op='UPDATE' then
    -- OPEN subsets have the same immutable cut as sealed choices.
    if new.accepted_resolution_refs is distinct from old.accepted_resolution_refs then
      raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_IMMUTABLE';end if;
    if tg_table_name='bpay_next_work_choice' and
      (new.pay_hold_control_version,new.pay_hold_changed_at_utc,new.pay_hold_physical_timesheet_id,
        new.pay_hold_financial_id,new.pay_hold,new.pay_hold_reason) is distinct from
      (old.pay_hold_control_version,old.pay_hold_changed_at_utc,old.pay_hold_physical_timesheet_id,
        old.pay_hold_financial_id,old.pay_hold,old.pay_hold_reason) then
      raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_IMMUTABLE';end if;
    if (old.selection_state='SEALED' and (to_jsonb(new)-'segment_page_count'-'segment_count'-'segment_sealed_count')
        is distinct from (to_jsonb(old)-'segment_page_count'-'segment_count'-'segment_sealed_count'))
      or new.run_id<>old.run_id or new.work_id<>old.work_id
      or new.expected_revision_id is distinct from old.expected_revision_id
      or new.selection_mode<>old.selection_mode
      or new.page_count<old.page_count or new.component_count<old.component_count then
      raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_IMMUTABLE';
    end if;
    if (old.segment_sealed_count is not null and (new.segment_page_count,new.segment_count,new.segment_sealed_count)
      is distinct from (old.segment_page_count,old.segment_count,old.segment_sealed_count)) or new.segment_control_sequence is distinct from old.segment_control_sequence
      or new.segment_page_count<old.segment_page_count or new.segment_count<old.segment_count then
      raise exception using errcode='55000',message='BPAY_NEXT_SEGMENT_SELECTION_IMMUTABLE';
    end if;
    if new.segment_page_count<>old.segment_page_count or new.segment_count<>old.segment_count then
      if new.segment_page_count<>old.segment_page_count+1 or new.segment_count<=old.segment_count
        or new.segment_count-old.segment_count>100 or not exists(select 1 from private.bpay_next_segment_selection_page p
          where p.run_id=new.run_id and p.work_id=new.work_id and p.page_no=new.segment_page_count
            and p.first_member_no=old.segment_count+1 and p.item_count=new.segment_count-old.segment_count)
        or (select count(*) from private.bpay_next_selected_segment s where s.run_id=new.run_id and s.work_id=new.work_id
          and s.selection_no>old.segment_count and s.selection_no<=new.segment_count)<>new.segment_count-old.segment_count then
        raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_PAGE_COUNT_MISMATCH';
      end if;
    end if;
    if new.page_count<>old.page_count or new.component_count<>old.component_count then
      select p.* into strict v_page from private.bpay_next_component_selection_page p
        where p.run_id=new.run_id and p.work_id=new.work_id and p.page_no=new.page_count;
      select count(*)::integer into v_count from private.bpay_next_selected_component c
        where c.run_id=new.run_id and c.work_id=new.work_id and c.page_no=new.page_count;
      if new.page_count<>old.page_count+1 or v_page.first_selection_no<>old.component_count+1
        or new.component_count<>old.component_count+v_page.item_count or v_count<>v_page.item_count
        or new.selection_state<>old.selection_state then
        raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_PAGE_COUNT_MISMATCH';
      end if;
    end if;
  elsif tg_table_name='bpay_next_work_choice' then
    if new.page_count<>0 or new.component_count<>0
      or (new.selection_mode='SUBSET' and new.selection_state<>'OPEN') then
      raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_PAGE_COUNT_MISMATCH';
    end if;
  else
    select c.* into strict v_choice from private.bpay_next_work_choice c
      where c.run_id=new.run_id and c.work_id=new.work_id;
    if v_choice.selection_mode<>'SUBSET' or v_choice.selection_state<>'OPEN'
      or new.page_no<>v_choice.page_count+1 then
      raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_NOT_OPEN';
    end if;
    if tg_table_name='bpay_next_component_selection_page' then
      if new.first_selection_no<>v_choice.component_count+1 then
        raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_PAGE_COUNT_MISMATCH';
      end if;
    else
      select p.* into strict v_page from private.bpay_next_component_selection_page p
        where p.run_id=new.run_id and p.work_id=new.work_id and p.page_no=new.page_no;
      if new.expected_revision_id<>v_choice.expected_revision_id or new.page_item_no>v_page.item_count
        or new.selection_no<>v_page.first_selection_no+new.page_item_no-1 then
        raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_PAGE_COUNT_MISMATCH';
      end if;
    end if;
  end if;
  return new;
end
$function$;


create or replace function private.bpay_next_create_preparation_v1(
 p_run_id uuid,p_actor_user_id uuid,p_pay_date date,p_descriptor jsonb,p_command_id uuid,p_guard jsonb
) returns jsonb language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
 v_run private.bpay_next_pay_run%rowtype;v_result jsonb;v_ns jsonb;v_intent jsonb;
 v_row jsonb;v_array text;v_keys text[];v_field text;v_id uuid;v_header jsonb;
 v_query_admitted boolean:=true;v_policy text:='NONE';v_channel text:='ALL';
 v_reason text;v_proof uuid;v_guard jsonb;v_scope jsonb;v_policy_args jsonb;
 v_locked_candidates uuid[];v_locked_works uuid[];v_locked_revisions uuid[];v_locked_cases uuid[];
 v_candidate uuid;v_work uuid;v_revision uuid;v_sequence bigint;v_gate jsonb;v_query_exclusions jsonb;v_member record;
 v_memory boolean:=p_descriptor ? 'memory_baseline_run_id';v_baseline uuid;v_page_no bigint;v_lines uuid[];v_subset record;
 v_mode text;v_selected boolean;v_count bigint;v_code text;v_week_start date;v_work_count bigint:=0;
begin
 if p_guard is not null then
  if jsonb_typeof(p_guard) is distinct from 'object' or not(p_guard ?& array['decision','reason','reauth_proof_id'])
   or p_guard-array['decision','reason','reauth_proof_id']<>'{}'::jsonb
   or jsonb_typeof(p_guard->'decision') is distinct from 'string'
   or p_guard->>'decision' not in ('UMBRELLA_ONLY','VERIFY_BOTH','VERIFY_PAYE') then
   raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';end if;
  v_policy:=p_guard->>'decision';v_channel:=case v_policy when 'UMBRELLA_ONLY' then 'UMBRELLA' when 'VERIFY_PAYE' then 'PAYE' else 'ALL' end;
  if v_policy='UMBRELLA_ONLY' then
   if p_guard->'reason'<>'null'::jsonb or p_guard->'reauth_proof_id'<>'null'::jsonb then
    raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';end if;
  else
   if jsonb_typeof(p_guard->'reason') is distinct from 'string' or btrim(p_guard->>'reason')=''
    or octet_length(p_guard->>'reason') not between 1 and 500
    or jsonb_typeof(p_guard->'reauth_proof_id') is distinct from 'string'
    or p_guard->>'reauth_proof_id'!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
    raise exception using errcode='22023',message='BPAY_NEXT_REAUTH_REQUEST_INVALID';end if;
   v_reason:=p_guard->>'reason';v_proof:=(p_guard->>'reauth_proof_id')::uuid;
  end if;
 end if;
 if p_command_id is null or jsonb_typeof(p_descriptor) is distinct from 'object'
   or octet_length(p_descriptor::text)>32768
   or not(p_descriptor ?& array['namespace','intent','revision','workbench_revision','adoption_revision'])
   or p_descriptor-array['namespace','intent','revision','workbench_revision','adoption_revision','memory_baseline_run_id']<>'{}'::jsonb then
  raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';
 end if;
 if v_memory and p_descriptor->'memory_baseline_run_id'<>'null'::jsonb and
  (jsonb_typeof(p_descriptor->'memory_baseline_run_id')<>'string' or p_descriptor->>'memory_baseline_run_id'!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$') then
  raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
 v_ns:=p_descriptor->'namespace';v_intent:=p_descriptor->'intent';
 if jsonb_typeof(v_ns) is distinct from 'object'
   or not(v_ns ?& array['agency_id','owner_epoch','actor_user_id','official_pay_date','scope'])
   or v_ns-array['agency_id','owner_epoch','actor_user_id','official_pay_date','scope']<>'{}'::jsonb
   or jsonb_typeof(v_ns->'scope') is distinct from 'object'
   or not(v_ns->'scope' ?& array['candidate_id','client_id','channel'])
   or (v_ns->'scope')-array['candidate_id','client_id','channel']<>'{}'::jsonb
   or jsonb_typeof(v_intent) is distinct from 'object'
   or not(v_intent ?& array['mode','candidates','works','components','cases'])
   or v_intent-array['mode','candidates','works','components','cases']<>'{}'::jsonb
   or jsonb_typeof(v_intent->'mode') is distinct from 'string'
   or v_intent->>'mode' not in ('ALL_MATCHING','NONE') then
  raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';
 end if;
 foreach v_array in array array['candidates','works','components','cases'] loop
  if jsonb_typeof(v_intent->v_array) is distinct from 'array'
    or jsonb_array_length(v_intent->v_array)>1000 then
   raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
  v_keys:=case v_array when 'candidates' then array['candidate_id','selected']
    when 'works' then array['candidate_id','work_id','expected_revision_id','selected','mode']
    when 'components' then array['candidate_id','work_id','expected_revision_id','approved_line_id','selected']
    else array['candidate_id','case_component_id','selected'] end;
  for v_row in select value from jsonb_array_elements(v_intent->v_array) loop
   if jsonb_typeof(v_row) is distinct from 'object' or not(v_row ?& v_keys)
     or v_row-v_keys<>'{}'::jsonb or jsonb_typeof(v_row->'selected') is distinct from 'boolean' then
    raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
   foreach v_field in array v_keys loop
    if v_field in ('selected','mode') then continue;end if;
    if jsonb_typeof(v_row->v_field) is distinct from 'string'
      or v_row->>v_field!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
     raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
   end loop;
   if v_array='works' and (jsonb_typeof(v_row->'mode') is distinct from 'string'
      or v_row->>'mode' not in ('ALL','SUBSET')) then
    raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(v_intent->v_array) a(value)
    group by case v_array when 'candidates' then a.value->>'candidate_id'
      when 'works' then a.value->>'work_id' when 'components' then a.value->>'approved_line_id'
      else a.value->>'case_component_id' end having count(*)>1) then
   raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
 end loop;
 if jsonb_typeof(v_ns->'agency_id') is distinct from 'string'
   or v_ns->>'agency_id'!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or jsonb_typeof(v_ns->'actor_user_id') is distinct from 'string'
   or v_ns->>'actor_user_id'!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or jsonb_typeof(v_ns->'owner_epoch') is distinct from 'string'
   or v_ns->>'owner_epoch'!~'^[1-9][0-9]{0,18}$'
   or jsonb_typeof(v_ns->'official_pay_date') is distinct from 'string'
   or v_ns->>'official_pay_date'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or jsonb_typeof(v_ns->'scope'->'channel') is distinct from 'string'
   or v_ns->'scope'->>'channel' not in ('ALL','PAYE','UMBRELLA') then
  raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
 foreach v_field in array array['candidate_id','client_id'] loop
  if v_ns->'scope'->v_field<>'null'::jsonb and (jsonb_typeof(v_ns->'scope'->v_field) is distinct from 'string'
    or v_ns->'scope'->>v_field!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$') then
   raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
 end loop;
 if jsonb_typeof(p_descriptor->'workbench_revision') is distinct from 'string'
   or p_descriptor->>'workbench_revision'!~'^(0|[1-9][0-9]{0,18})$'
   or jsonb_typeof(p_descriptor->'adoption_revision') is distinct from 'string'
   or p_descriptor->>'adoption_revision'!~'^(0|[1-9][0-9]{0,18})$' then
  raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
 -- An exact receipt replay acquires no new source/cut/FK-parent locks.
 select src.* into v_run from private.bpay_next_pay_run src where id=p_run_id;
 if found then
  if v_run.accepted_choice_descriptor is null then
   raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_RUN_NOT_EMPTY';end if;
  v_result:=private.bpay_next_create_preparation_v1(p_run_id,p_actor_user_id,p_pay_date);
  select src.* into strict v_run from private.bpay_next_pay_run src where id=p_run_id;
  if v_run.accepted_choice_descriptor is distinct from p_descriptor
    or v_run.accepted_choice_command_id is distinct from p_command_id then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_DESCRIPTOR_REPLAY_CONFLICT';end if;
  if (v_run.paye_guard_decision,v_run.channel_scope,v_run.paye_override_reason,v_run.reauth_proof_id,
    v_run.paye_override_actor) is distinct from (v_policy,v_channel,v_reason,v_proof,
      case when v_policy='NONE' then null::uuid else p_actor_user_id end) then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_DESCRIPTOR_REPLAY_CONFLICT';end if;
  if v_proof is not null then
   perform private.bpay_next_reauth_consume_v1(v_proof,p_actor_user_id,'PAYE_SAME_WEEK_OVERRIDE',v_run.paye_guard_scope_sha256,p_command_id);
  end if;
  select agency_sequence into v_sequence from private.bpay_next_command where id=p_command_id;
  return v_result||jsonb_build_object('command_id',p_command_id,'agency_sequence',v_sequence::text,
    'choice_work_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='WORK'),
    'choice_case_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='CASE_COMPONENT'),
    'selected_candidate_count',v_run.selected_candidate_count::text,'empty',v_run.selected_candidate_count=0,'replay',true);
 end if;
 -- Source admission precedes the original module/run/snooze cut locks.
 begin perform private.weekly_source_pay_query_admit_v2();
 exception when lock_not_available then v_query_admitted:=false;end;
 perform 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
 -- FK parent locks precede the inherited snooze command-clock SHARE.
 -- No revision-meta lock: Snooze writers already take clock before meta.
 select coalesce(array_agg(parent.id),'{}'::uuid[]) into v_locked_candidates from (select candidate.id from public.candidates candidate where exists(select 1 from private.bpay_next_workbench_item i
   where i.candidate_id=candidate.id and i.section='READY' and i.selectable
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel'))
   or exists(select 1 from unnest(array['candidates','works','components','cases']) kind
     cross join lateral jsonb_array_elements(v_intent->kind) a(value) where a.value->>'candidate_id'=candidate.id::text)
   order by candidate.id for share) parent;
 if exists(select 1 from jsonb_array_elements(v_intent->'candidates') requested
   where not ((requested->>'candidate_id')::uuid=any(v_locked_candidates))) then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_NATIVE_IDENTITY_INVALID';end if;
 perform 1 from public.umbrellas umbrella where exists(select 1 from public.candidates candidate
   join private.bpay_next_workbench_item i on i.candidate_id=candidate.id and i.section='READY' and i.selectable
   where candidate.umbrella_id=umbrella.id
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel'))
   order by umbrella.id for share;
 select coalesce(array_agg(parent.id),'{}'::uuid[]) into v_locked_works from (select w.id from private.bpay_next_work w where exists(select 1 from private.bpay_next_workbench_item i
   where i.work_id=w.id and i.section='READY' and i.selectable
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel'))
   or exists(select 1 from jsonb_array_elements(v_intent->'works') a(value) where a.value->>'work_id'=w.id::text)
   order by w.id for share) parent;
 select coalesce(array_agg(parent.id),'{}'::uuid[]) into v_locked_revisions from (select r.id from private.bpay_next_work_revision r where exists(select 1 from private.bpay_next_workbench_item i
   where i.revision_id=r.id and i.section='READY' and i.selectable
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel'))
   or exists(select 1 from jsonb_array_elements(v_intent->'works') a(value) where a.value->>'expected_revision_id'=r.id::text)
   order by r.work_id,r.id for share) parent;
 select coalesce(array_agg(parent.id),'{}'::uuid[]) into v_locked_cases from (select component.id from private.bpay_next_case_component component where exists(select 1 from private.bpay_next_workbench_item i
   where i.case_component_id=component.id and i.section='READY' and i.selectable
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel'))
   or exists(select 1 from jsonb_array_elements(v_intent->'cases') a(value) where a.value->>'case_component_id'=component.id::text)
   order by component.candidate_id,component.id for share) parent;
 if exists(select 1 from private.bpay_next_command c where c.status in ('RECEIVED','ENROLLING'))
   or exists(select 1 from private.bpay_next_job j join private.bpay_next_command c on c.id=j.command_id
   where j.status<>'DONE' and j.candidate_id=any(v_locked_candidates)) then
  raise exception using errcode='55000',message='BPAY_NEXT_ACCEPT_INPUT_EARLIER_ECONOMIC_COMMAND_PENDING';end if;
 -- Acquire UPDATE once before the inherited SHARE, avoiding concurrent upgrades.
 perform 1 from private.bpay_next_command_clock where id=1 for update;
 if exists(select 1 from private.bpay_next_command c where c.status in ('RECEIVED','ENROLLING'))
   or exists(select 1 from private.bpay_next_job j join private.bpay_next_command c on c.id=j.command_id
   where j.status<>'DONE' and j.candidate_id=any(v_locked_candidates)) then
  raise exception using errcode='55000',message='BPAY_NEXT_ACCEPT_INPUT_EARLIER_ECONOMIC_COMMAND_PENDING';end if;
 if exists(select 1 from private.bpay_next_command where id=p_command_id) then
  raise exception using errcode='23514',message='BPAY_NEXT_PREPARE_COMMAND_REPLAY_CONFLICT';end if;
 -- A same-run concurrent legacy writer must never make clock->run wait.
 perform 1 from private.bpay_next_pay_run where id=p_run_id for update nowait;
 if found and exists(select 1 from private.bpay_next_pay_run where id=p_run_id and accepted_choice_descriptor is null) then
  raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_RUN_NOT_EMPTY';end if;
 -- Original UUID/actor/date/deadline owner is preserved, including replay.
 v_result:=private.bpay_next_create_preparation_v1(p_run_id,p_actor_user_id,p_pay_date);
 select r.* into strict v_run from private.bpay_next_pay_run r where r.id=p_run_id for update;
 if v_run.accepted_choice_descriptor is not null then
  if v_run.accepted_choice_descriptor is distinct from p_descriptor
    or v_run.accepted_choice_command_id is distinct from p_command_id then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_DESCRIPTOR_REPLAY_CONFLICT';end if;
  if (v_run.paye_guard_decision,v_run.channel_scope,v_run.paye_override_reason,v_run.reauth_proof_id,
    v_run.paye_override_actor) is distinct from (v_policy,v_channel,v_reason,v_proof,
      case when v_policy='NONE' then null::uuid else p_actor_user_id end) then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_DESCRIPTOR_REPLAY_CONFLICT';end if;
  if v_proof is not null then
   perform private.bpay_next_reauth_consume_v1(v_proof,p_actor_user_id,'PAYE_SAME_WEEK_OVERRIDE',v_run.paye_guard_scope_sha256,p_command_id);
  end if;
  select agency_sequence into v_sequence from private.bpay_next_command where id=p_command_id;
  return v_result||jsonb_build_object('command_id',p_command_id,'agency_sequence',v_sequence::text,
    'choice_work_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='WORK'),
    'choice_case_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='CASE_COMPONENT'),
    'selected_candidate_count',v_run.selected_candidate_count::text,'empty',v_run.selected_candidate_count=0,'replay',true);
 end if;
 if v_run.status<>'PREPARING' or v_run.selection_state<>'OPEN' or v_run.selection_page_count<>0
   or v_run.selection_count<>0 or v_run.selected_candidate_count<>0
   or exists(select 1 from private.bpay_next_run_selection where run_id=p_run_id)
   or exists(select 1 from private.bpay_next_selection_candidate where run_id=p_run_id)
   or exists(select 1 from private.bpay_next_case_selection where run_id=p_run_id)
   or exists(select 1 from private.bpay_next_run_command where run_id=p_run_id)
   or v_run.preparation_expires_at_utc<=clock_timestamp() then
  raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_RUN_NOT_EMPTY';end if;
 -- Compare real authenticated identity/context; caller fields are never authority.
 v_header:=public.bpay_next_workbench_page_v1(jsonb_build_object('actor_user_id',p_actor_user_id,
   'kind','HEADER','candidate_id',v_ns->'scope'->'candidate_id','client_id',v_ns->'scope'->'client_id',
   'channel',v_ns->'scope'->>'channel','section','READY','search','','sort','NAME_ASC',
   'group_key',null,'item_id',null,'reason_code',null,'count_selection',null,'after',null,'limit',100));
 if v_ns->>'agency_id' is distinct from v_header->'context'->>'agency_id'
   or v_ns->>'actor_user_id' is distinct from p_actor_user_id::text
   or v_ns->>'owner_epoch' is distinct from v_header->'context'->>'owner_epoch'
   or v_ns->>'official_pay_date' is distinct from v_run.pay_date::text
   or p_descriptor->>'workbench_revision' is distinct from v_header->'context'->>'workbench_revision'
   or p_descriptor->>'adoption_revision' is distinct from v_header->'context'->>'adoption_revision'
   or jsonb_typeof(p_descriptor->'revision') is distinct from 'number'
   or p_descriptor->>'revision'!~'^(0|[1-9][0-9]{0,15})$' then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_CONTEXT_CHANGED';end if;
 -- Validate every deliberate subordinate identity before any accepted cut.
 for v_array,v_row in select k,value from unnest(array['works','components']) k
   cross join lateral jsonb_array_elements(v_intent->k) a(value) loop
  v_work:=(v_row->>'work_id')::uuid;v_candidate:=(v_row->>'candidate_id')::uuid;
  v_revision:=(v_row->>'expected_revision_id')::uuid;
  if not exists(select 1 from private.bpay_next_work w join private.bpay_next_work_revision r
    on r.work_id=w.id and r.id=v_revision where w.id=v_work and w.candidate_id=v_candidate)
    or (v_array='components' and not exists(select 1 from private.bpay_next_approved_line l
      where l.id=(v_row->>'approved_line_id')::uuid and l.revision_id=v_revision)) then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_NATIVE_IDENTITY_INVALID';end if;
 end loop;
 -- WB25: component-only memory overlays retain untouched native defaults.
 -- A supplied parent must match; an absent parent must be current, scoped and
 -- eligible under the original held Work/revision locks. Legacy stays SUBSET.
 if exists(select 1 from jsonb_array_elements(v_intent->'components') c(value)
   where case when exists(select 1 from jsonb_array_elements(v_intent->'works') w(value)
      where w.value->>'work_id'=c.value->>'work_id') then
     not exists(select 1 from jsonb_array_elements(v_intent->'works') w(value)
      where w.value->>'work_id'=c.value->>'work_id' and w.value->>'candidate_id'=c.value->>'candidate_id'
       and w.value->>'expected_revision_id'=c.value->>'expected_revision_id'
       and (v_memory or w.value->>'mode'='SUBSET' and w.value->'selected'='true'::jsonb))
    else not v_memory or not exists(select 1 from private.bpay_next_work w join private.bpay_next_work_revision r on r.work_id=w.id
       join private.bpay_next_workbench_item i on i.work_id=w.id and i.revision_id=r.id
       join private.bpay_next_workbench_group g on g.group_key=i.group_key and g.candidate_id=i.candidate_id
       where w.id=(c.value->>'work_id')::uuid and w.candidate_id=(c.value->>'candidate_id')::uuid
        and r.id=(c.value->>'expected_revision_id')::uuid and w.current_revision_id=r.id and w.applied_revision_id=r.id
        and i.approved_line_id=(c.value->>'approved_line_id')::uuid and i.candidate_id=w.candidate_id
        and i.section='READY' and i.selectable and i.amount_known and not i.is_selected
        and i.portion_kind in ('AVAILABLE','ZERO') and g.complete and not g.dirty
        and g.progress_state='CURRENT' and i.progress_state='CURRENT'
        and i.projection_revision=g.projection_revision and i.financial_view_revision=g.financial_view_revision
        and (v_ns->'scope'->>'candidate_id' is null or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
        and (v_ns->'scope'->>'client_id' is null or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
        and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel')) end) then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_NATIVE_IDENTITY_INVALID';end if;
 if exists(select 1 from jsonb_array_elements(v_intent->'cases') a(value) where not exists(
   select 1 from private.bpay_next_case_component c where c.id=(a.value->>'case_component_id')::uuid
     and c.candidate_id=(a.value->>'candidate_id')::uuid)) then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_NATIVE_IDENTITY_INVALID';end if;
 -- DR-10: fresh serialized policy admission, before the original member cut.
 v_guard:=private.bpay_next_paye_guard_page_v1(p_actor_user_id,p_run_id,p_descriptor);
 if v_policy='NONE' and (v_guard->>'guard_applies')::boolean then
  raise exception using errcode='55000',message='BPAY_NEXT_PAYE_SAME_WEEK_GUARD_UNRESOLVED';end if;
 if v_policy<>'NONE' and not(v_guard->>'guard_applies')::boolean then
  raise exception using errcode='23514',message='BPAY_NEXT_PAYE_GUARD_CHANGED';end if;
 if v_policy in ('VERIFY_BOTH','VERIFY_PAYE') then
  if (v_guard->>'unexecuted')::boolean then
   raise exception using errcode='55000',message='BPAY_NEXT_PAYE_SAME_WEEK_GUARD_UNEXECUTED';end if;
  v_policy_args:=jsonb_build_object('run_id',p_run_id,'command_id',p_command_id,'decision',v_policy,'reason',v_reason,
    'context',p_descriptor-array['intent','revision','memory_baseline_run_id']);
  v_scope:=private.bpay_next_reauth_scope_v1(p_actor_user_id,'PAYE_SAME_WEEK_OVERRIDE',v_policy_args,false);
  perform private.bpay_next_reauth_consume_v1(v_proof,p_actor_user_id,'PAYE_SAME_WEEK_OVERRIDE',v_scope->>'scope_sha256',p_command_id);
 end if;
 update private.bpay_next_pay_run set paye_guard_decision=v_policy,channel_scope=v_channel,
  paye_override_actor=case when v_policy='NONE' then null else p_actor_user_id end,
  paye_override_reason=v_reason,reauth_proof_id=v_proof,paye_guard_scope_sha256=v_scope->>'scope_sha256' where id=p_run_id;
 -- The original run boundary retained its snooze cut; no second clock or kind.
 insert into private.bpay_next_run_selection_exclusion(run_id,page_no,candidate_id,actor_user_id)
   select p_run_id,(row_number() over(order by a.value->>'candidate_id')+99)/100,
     (a.value->>'candidate_id')::uuid,p_actor_user_id
   from jsonb_array_elements(v_intent->'candidates') a(value) where a.value->'selected'='false'::jsonb;
 insert into private.bpay_next_run_selection_exclusion(run_id,page_no,work_id,actor_user_id)
   select p_run_id,((select count(*) from private.bpay_next_run_selection_exclusion where run_id=p_run_id)
     +row_number() over(order by a.value->>'work_id')+99)/100,(a.value->>'work_id')::uuid,p_actor_user_id
   from jsonb_array_elements(v_intent->'works') a(value) where a.value->'selected'='false'::jsonb;
 -- No membership may acquire an unheld FK parent after the command clock.
 if exists(select 1 from private.bpay_next_workbench_item i
   where i.section='READY' and i.selectable
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel')
     and (not(i.candidate_id=any(v_locked_candidates))
       or (i.work_id is not null and (not(i.work_id=any(v_locked_works)) or not(i.revision_id=any(v_locked_revisions))))
       or (i.case_component_id is not null and not(i.case_component_id=any(v_locked_cases))))) then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_CONTEXT_CHANGED';end if;
 -- Memory is captured under the original parent locks and final context check.
 if v_memory then
  v_baseline:=private.bpay_next_selection_memory_resolve_v1(v_ns,jsonb_build_object('run_id',p_descriptor->'memory_baseline_run_id','scope',v_ns->'scope'));
  perform private.bpay_next_selection_memory_capture_v1(p_run_id,p_descriptor);
  with choices as materialized(select * from private.bpay_next_selection_memory_choices_v1(v_ns->'scope',v_baseline,v_intent)),
  works as (select l.work_id,l.candidate_id,
    coalesce((ov.value->>'expected_revision_id')::uuid,l.revision_id) expected_revision_id,
    case when bool_and(l.selected) then 'ALL' else 'SUBSET' end selection_mode
   from choices l left join lateral(select value from jsonb_array_elements(v_intent->'works') where value->>'work_id'=l.work_id::text) ov on true
   where l.work_id is not null and l.direction='PAYMENT'
    and (v_policy<>'VERIFY_PAYE' or exists(select 1 from public.candidates c where c.id=l.candidate_id and upper(c.pay_method)='PAYE'))
   group by l.work_id,l.candidate_id,coalesce((ov.value->>'expected_revision_id')::uuid,l.revision_id)
   having bool_or(l.selected)),
  work_members as (insert into private.bpay_next_run_choice_member(run_id,member_kind,member_id,candidate_id,work_id,expected_revision_id,selection_mode,selected,member_no)
   select p_run_id,'WORK',w.work_id,w.candidate_id,w.work_id,w.expected_revision_id,w.selection_mode,true,
    row_number() over(order by (w.selection_mode='SUBSET') desc,w.work_id) from works w returning candidate_id),
  case_members as (insert into private.bpay_next_run_choice_member(run_id,member_kind,member_id,candidate_id,case_component_id,selected,member_no)
   select p_run_id,'CASE_COMPONENT',l.case_component_id,l.candidate_id,l.case_component_id,l.selected,
    row_number() over(order by l.candidate_id,l.case_component_id) from choices l
   where l.case_component_id is not null
    and (v_channel='ALL' or exists(select 1 from public.candidates c where c.id=l.candidate_id and upper(c.pay_method)=v_channel)) and
    (exists(select 1 from work_members w where w.candidate_id=l.candidate_id)
     or exists(select 1 from choices payment where payment.candidate_id=l.candidate_id and payment.case_component_id is not null and payment.direction='PAYMENT' and payment.selected))
   returning candidate_id)
  select (select count(*) from work_members)+(select count(*) from case_members) into v_count;
 else
 -- Retain Work and Case membership in one statement snapshot.
 with work_members as (insert into private.bpay_next_run_choice_member(run_id,member_kind,member_id,candidate_id,
   work_id,expected_revision_id,selection_mode,selected,member_no)
 select p_run_id,'WORK',i.work_id,i.candidate_id,i.work_id,
   coalesce((ov.value->>'expected_revision_id')::uuid,i.revision_id),coalesce(ov.value->>'mode','ALL'),true,
   row_number() over(order by (coalesce(ov.value->>'mode','ALL')='SUBSET') desc,i.work_id)
 from private.bpay_next_workbench_item i join private.bpay_next_workbench_group g
   on g.group_key=i.group_key and g.candidate_id=i.candidate_id
 left join lateral(select a.value from jsonb_array_elements(v_intent->'works') a(value)
   where a.value->>'work_id'=i.work_id::text) ov on true
 where i.section='READY' and i.selectable and i.work_id is not null and i.amount_known
   and i.direction='PAYMENT' and i.portion_kind in ('AVAILABLE','ZERO')
   and (v_policy<>'VERIFY_PAYE' or exists(select 1 from public.candidates c where c.id=i.candidate_id and upper(c.pay_method)='PAYE'))
   and g.complete and not g.dirty and g.progress_state='CURRENT' and i.progress_state='CURRENT'
   and i.projection_revision=g.projection_revision and i.financial_view_revision=g.financial_view_revision
   and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
   and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
   and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel')
   and not exists(select 1 from private.bpay_next_run_selection_exclusion e where e.run_id=p_run_id
     and (e.candidate_id=i.candidate_id or e.work_id=i.work_id))
   and (v_intent->>'mode'='ALL_MATCHING' or ov.value->'selected'='true'::jsonb or exists(
     select 1 from jsonb_array_elements(v_intent->'candidates') a(value)
       where a.value->>'candidate_id'=i.candidate_id::text and a.value->'selected'='true'::jsonb))
 group by i.work_id,i.candidate_id,coalesce((ov.value->>'expected_revision_id')::uuid,i.revision_id),coalesce(ov.value->>'mode','ALL') returning candidate_id),
 case_members as (insert into private.bpay_next_run_choice_member(run_id,member_kind,member_id,candidate_id,case_component_id,selected,member_no)
 select p_run_id,'CASE_COMPONENT',i.case_component_id,i.candidate_id,i.case_component_id,
   coalesce((ov.value->>'selected')::boolean,true),row_number() over(order by i.candidate_id,i.case_component_id)
 from private.bpay_next_workbench_item i join private.bpay_next_workbench_group g
   on g.group_key=i.group_key and g.candidate_id=i.candidate_id
 left join lateral(select a.value from jsonb_array_elements(v_intent->'cases') a(value)
   where a.value->>'case_component_id'=i.case_component_id::text) ov on true
 where i.section='READY' and i.selectable and i.case_component_id is not null
   and (v_channel='ALL' or exists(select 1 from public.candidates c where c.id=i.candidate_id and upper(c.pay_method)=v_channel))
   and g.complete and not g.dirty and g.progress_state='CURRENT' and i.progress_state='CURRENT'
   and i.projection_revision=g.projection_revision and i.financial_view_revision=g.financial_view_revision
   and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
   and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
   and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel')
   and not exists(select 1 from private.bpay_next_run_selection_exclusion e where e.run_id=p_run_id
     and e.candidate_id=i.candidate_id)
   and (exists(select 1 from work_members m where m.candidate_id=i.candidate_id)
     or exists(select 1 from private.bpay_next_workbench_item payment
       join private.bpay_next_workbench_group payment_group
         on payment_group.group_key=payment.group_key and payment_group.candidate_id=payment.candidate_id
       left join lateral(select a.value from jsonb_array_elements(v_intent->'cases') a(value)
         where a.value->>'case_component_id'=payment.case_component_id::text) chosen on true
       where payment.candidate_id=i.candidate_id and payment.case_component_id is not null
         and payment.section='READY' and payment.selectable and payment.direction='PAYMENT'
         and payment.amount_known and payment.portion_kind in ('AVAILABLE','ZERO')
         and payment_group.complete and not payment_group.dirty
         and payment_group.progress_state='CURRENT' and payment.progress_state='CURRENT'
         and payment.projection_revision=payment_group.projection_revision
         and payment.financial_view_revision=payment_group.financial_view_revision
         and coalesce((chosen.value->>'selected')::boolean,true)
         and (v_ns->'scope'->'client_id'='null'::jsonb or payment.client_id=(v_ns->'scope'->>'client_id')::uuid)
         and (v_ns->'scope'->>'channel'='ALL' or payment.target_pay_channel=v_ns->'scope'->>'channel')
         and (v_intent->>'mode'='ALL_MATCHING' or chosen.value->'selected'='true'::jsonb
           or exists(select 1 from jsonb_array_elements(v_intent->'candidates') a(value)
             where a.value->>'candidate_id'=i.candidate_id::text and a.value->'selected'='true'::jsonb))))
 group by i.case_component_id,i.candidate_id,coalesce((ov.value->>'selected')::boolean,true) returning candidate_id)
 select (select count(*) from work_members)+(select count(*) from case_members) into v_count;
 end if;
 v_week_start:=date_trunc('week',v_run.snooze_business_date::timestamp)::date;
 for v_member in select m.*,w.approval_state,w.current_revision_id,w.applied_revision_id,w.week_ending_date,
   r.physical_timesheet_id,r.source_kind,r.approved_at_utc,r.sealed_at_utc,upper(c.pay_method) as pay_channel
   from private.bpay_next_run_choice_member m join private.bpay_next_work w on w.id=m.work_id
   join private.bpay_next_work_revision r on r.work_id=w.id and r.id=m.expected_revision_id
   join public.candidates c on c.id=m.candidate_id
   where m.run_id=p_run_id and m.member_kind='WORK' order by m.member_no loop
  v_code:=null;
  if v_policy='UMBRELLA_ONLY' and v_member.pay_channel='PAYE' then
   v_code:='PAYE_EXCLUDED_BY_SAME_WEEK_GUARD';
  elsif v_member.approval_state<>'APPROVED' or v_member.approved_at_utc is null or v_member.sealed_at_utc is null then
   v_code:='BPAY_NEXT_SELECTION_WORK_NOT_APPROVED';
  elsif v_member.current_revision_id is distinct from v_member.expected_revision_id
    or v_member.applied_revision_id is distinct from v_member.expected_revision_id then
   v_code:='BPAY_NEXT_SELECTION_REVISION_NOT_CURRENT';
  elsif v_member.week_ending_date-6>v_week_start then v_code:='BPAY_NEXT_WORK_WEEK_NOT_YET_PAYABLE';
  elsif not exists(select 1 from private.bpay_next_work w
    join public.timesheets t on t.booking_id=w.booking_id and t.is_current
    join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
    where w.id=v_member.work_id) then v_code:='BPAY_NEXT_SELECTION_REVISION_NOT_CURRENT';
  elsif exists(select 1 from private.bpay_next_work w
    join public.timesheets t on t.booking_id=w.booking_id and t.is_current=true
    join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current=true
    where w.id=v_member.work_id and tf.pay_on_hold is true) then
   v_code:='BPAY_NEXT_SELECTION_ON_HOLD';
  elsif not exists(select 1 from private.bpay_next_revision_worker_basis where revision_id=v_member.expected_revision_id) then
   raise exception using errcode='55000',message='BPAY_NEXT_SELECTION_BASIS_UNAVAILABLE';
  elsif exists(select 1 from private.bpay_next_snooze sn
    join lateral(select ev.after_state from private.bpay_next_snooze_event ev
      where ev.snooze_id=sn.id and ev.control_sequence<=v_run.snooze_control_sequence
      order by ev.control_sequence desc limit 1) e on true
    join private.bpay_next_revision_worker_basis b on b.revision_id=v_member.expected_revision_id
    where sn.work_id=v_member.work_id and sn.scope_kind='WHOLE_TIMESHEET'
      and (e.after_state->>'active')::boolean
      and ((e.after_state->>'until_date') is null or (e.after_state->>'until_date')::date>=v_run.snooze_business_date)
      and (e.after_state->>'worker_pay_basis')::bytea=b.whole_basis) then
   v_code:='BPAY_NEXT_SELECTION_SNOOZED';
  end if;
  v_gate:=null;v_query_exclusions:=null;
  if v_code is null and v_member.source_kind in ('SOURCE','PROTECTED') then
   if not v_query_admitted then v_code:='SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE';
   else begin v_gate:=private.weekly_source_pay_query_gate_v1(v_member.physical_timesheet_id);
    if v_gate->'ok' is distinct from 'true'::jsonb or v_gate->>'code' is distinct from 'OK'
      or jsonb_typeof(v_gate->'blocked') is distinct from 'boolean' then
     v_code:='SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE';
    else
     v_query_exclusions:=private.bpay_next_source_query_segment_exclusions_v1(v_member.expected_revision_id,v_gate);
     if v_gate->'blocked'='true'::jsonb and v_query_exclusions is null then v_code:='SOURCE_PAY_QUERY_OPEN';end if;
    end if;
   exception when others then v_code:='SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE';end;end if;
  end if;
  if v_code is null and v_member.selection_mode='SUBSET' and v_memory then
   if not exists(select 1 from private.bpay_next_selection_memory_choices_v1(v_ns->'scope',v_baseline,v_intent) l
     where l.work_id=v_member.work_id and l.revision_id=v_member.expected_revision_id and l.selected and l.direction='PAYMENT') then
    v_code:='BPAY_NEXT_SELECTION_SIGNED_LINE_NOT_ELIGIBLE';end if;
  elsif not v_memory then
  if v_code is null and v_member.selection_mode='SUBSET' and (not exists(
    select 1 from private.bpay_next_workbench_item i
    join jsonb_array_elements(v_intent->'components') a(value)
      on a.value->>'approved_line_id'=i.approved_line_id::text and a.value->'selected'='true'::jsonb
    where i.work_id=v_member.work_id and i.revision_id=v_member.expected_revision_id
      and i.section='READY' and i.selectable and i.amount_known and i.direction='PAYMENT'
      and i.portion_kind in ('AVAILABLE','ZERO'))
    or exists(select 1 from jsonb_array_elements(v_intent->'components') chosen
      where chosen->>'work_id'=v_member.work_id::text and chosen->'selected'='true'::jsonb
        and not exists(select 1 from private.bpay_next_workbench_item i
          where i.work_id=v_member.work_id and i.revision_id=v_member.expected_revision_id
            and i.approved_line_id=(chosen->>'approved_line_id')::uuid and i.section='READY'
            and i.selectable and i.amount_known and i.direction='PAYMENT'
            and i.portion_kind in ('AVAILABLE','ZERO')))) then
   v_code:='BPAY_NEXT_SELECTION_SIGNED_LINE_NOT_ELIGIBLE';end if;
  end if;
  if v_code is not null then
   update private.bpay_next_run_choice_member set skip_code=v_code
     where run_id=p_run_id and member_kind='WORK' and member_id=v_member.member_id;
  else
   -- Use the existing Rule B objects as the only captured financial authority.
   v_work_count:=v_work_count+1;
   insert into private.bpay_next_run_selection(run_id,selection_no,work_id,candidate_id)
     values(p_run_id,v_work_count,v_member.work_id,v_member.candidate_id);
   insert into private.bpay_next_work_choice(run_id,work_id,expected_revision_id,selection_mode,selection_state,accepted_resolution_refs)
     values(p_run_id,v_member.work_id,v_member.expected_revision_id,v_member.selection_mode,
       case when v_member.selection_mode='ALL' then 'SEALED' else 'OPEN' end,
       private.bpay_next_accepted_resolution_refs_v1(p_run_id,v_member.work_id,v_member.expected_revision_id));
   if v_gate is not null then
    insert into private.bpay_next_run_work_query_snapshot(run_id,work_id,expected_revision_id,physical_timesheet_id,gate_result,captured_at_utc,segment_query_exclusions)
      values(p_run_id,v_member.work_id,v_member.expected_revision_id,v_member.physical_timesheet_id,v_gate,transaction_timestamp(),v_query_exclusions);
   end if;
  end if;
 end loop;
 -- Publish genuine native counters before the unchanged component seal.
 if v_memory then
  update private.bpay_next_pay_run set work_choice_count=v_work_count,
   sealed_work_choice_count=(select count(*) from private.bpay_next_work_choice where run_id=p_run_id and selection_state='SEALED') where id=p_run_id;
  for v_subset in select c.* from private.bpay_next_work_choice c where c.run_id=p_run_id and c.selection_mode='SUBSET' order by c.work_id loop
   v_page_no:=0;
   for v_lines in select array_agg(q.approved_line_id order by q.approved_line_id) from
    (select l.approved_line_id,(row_number() over(order by l.approved_line_id)-1)/100 page_no
     from private.bpay_next_selection_memory_choices_v1(v_ns->'scope',v_baseline,v_intent) l
     where l.work_id=v_subset.work_id and l.revision_id=v_subset.expected_revision_id and l.selected and l.direction='PAYMENT') q
    group by q.page_no order by q.page_no loop
    v_page_no:=v_page_no+1;
    perform private.bpay_next_append_component_selection_page_v1(p_run_id,v_subset.work_id,v_subset.expected_revision_id,v_page_no,v_lines);
   end loop;
   select c.* into strict v_subset from private.bpay_next_work_choice c where c.run_id=p_run_id and c.work_id=v_subset.work_id;
   perform private.bpay_next_seal_component_selection_v1(p_run_id,v_subset.work_id,v_subset.expected_revision_id,v_subset.page_count,v_subset.component_count);
  end loop;
 end if;
 -- Capture the existing Rule B Candidate settings exactly once in this cut.
 insert into private.bpay_next_selection_candidate(run_id,candidate_id,member_no,
   target_pay_channel,target_umbrella_id,target_umbrella_vat_chargeable,min_take_home_wtd)
 select p_run_id,c.id,row_number() over(order by c.id),upper(c.pay_method),c.umbrella_id,u.vat_chargeable,c.min_take_home_wtd
 from public.candidates c left join public.umbrellas u on u.id=c.umbrella_id
 where exists(select 1 from private.bpay_next_run_choice_member m where m.run_id=p_run_id
   and m.candidate_id=c.id and m.selected and m.skip_code is null
   and (m.member_kind='WORK' or exists(select 1 from private.bpay_next_workbench_item i
     where i.case_component_id=m.case_component_id and i.direction='PAYMENT' and i.section='READY')));
 get diagnostics v_count=row_count;
 -- Optimistic context check, with no meta row lock or downstream recalculation.
 if not exists(select 1 from private.bpay_next_workbench_revision r where r.id=1
   and r.workbench_revision::text=p_descriptor->>'workbench_revision'
   and r.adoption_revision::text=p_descriptor->>'adoption_revision' and r.adoption_state='CURRENT') then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_CONTEXT_CHANGED';end if;
 if v_count>0 then
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'PREPARE');
  insert into private.bpay_next_run_command(run_id,command_id) values(p_run_id,p_command_id);
 end if;
 update private.bpay_next_pay_run set accepted_choice_descriptor=p_descriptor,
   accepted_choice_command_id=p_command_id,selected_candidate_count=v_count,
   selection_count=v_work_count,work_choice_count=v_work_count,
   sealed_work_choice_count=(select count(*) from private.bpay_next_work_choice where run_id=p_run_id and selection_state='SEALED') where id=p_run_id;
 if v_memory then
  update private.bpay_next_selection_mode_memory set command_id=case when v_sequence is not null then p_command_id end,
   agency_sequence=v_sequence where run_id=p_run_id and row_kind='HEADER' and v_sequence is not null;
  for v_subset in select c.work_id from private.bpay_next_work_choice c where c.run_id=p_run_id and c.selection_mode='SUBSET' and c.selection_state='SEALED' order by c.work_id loop
   perform private.bpay_next_materialise_choice_segments_v1(p_run_id,v_subset.work_id);
  end loop;
 end if;
 return v_result||jsonb_build_object('command_id',p_command_id,'agency_sequence',v_sequence::text,
   'selection_count',v_work_count::text,
   'selected_candidate_count',v_count::text,'empty',v_count=0,
   'choice_work_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='WORK'),
   'choice_case_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='CASE_COMPONENT'),'replay',false);
end
$function$;


alter function private.bpay_next_work_choice_guard_v1() OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_work_choice_guard_v1() from public,anon,authenticated,service_role;
alter function private.bpay_next_create_preparation_v1(uuid,uuid,date,jsonb,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_create_preparation_v1(uuid,uuid,date,jsonb,uuid,jsonb) from public,anon,authenticated,service_role;



-- CONTACT_PREPARER_UNIT 84 repeatable supabase/repeatable/13102026_0005_banking_pay_next_captured_resolution_hold_v1.sql SHA256 241f1010593ad6cde054a6cfb36908103dc937ceeffa66530c012372d0a13609
-- WB29/BD164: exact accepted treatment consumes one native Source reserve.
-- Current1419/1236 full successors; source-only canonical evidence, actual captured IDs retained.


create or replace function private.bpay_next_capture_position_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_work_cursor uuid,p_expected_component_cursor text,
  p_limit integer default 100
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private
as $function$
declare
  v_approval_revision_id uuid;v_approval_line_id uuid;v_effective_source_event_id uuid;
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_module_epoch bigint;
  v_row record;
  v_member record;
  v_seen integer:=0;
  v_selected_seen integer:=0;
  v_resolution_count integer:=0;
  v_managed_seen integer:=0;
  v_needs_resolution boolean;
  v_collection private.bpay_next_work_collection%rowtype;
  v_work_cursor uuid;
  v_component_cursor text;
  v_issue text;v_answered_source boolean;
  v_issue_work_id uuid;
  v_query_pin private.bpay_next_run_work_query_pin_v2%rowtype;
  v_binding private.bpay_next_source_component_binding_version%rowtype;v_book record;
  v_segments bigint;v_snooze jsonb;v_segment_result jsonb;v_segment_visited integer:=0;
  v_seed_effect uuid;v_seed_hold uuid;v_seed_holds uuid[];v_seed record;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_limit not between 1 and 100
     or (p_expected_work_cursor is null and p_expected_component_cursor is not null) then
    raise exception using errcode='22023',
      message='BPAY_NEXT_CAPTURE_POSITION_INPUT_INVALID';
  end if;
  select private.bpay_next_prepare_job_run_v1(j.id) into strict v_run_id
    from private.bpay_next_job j
    where j.id=p_job_id and j.job_kind='PREPARE';
  select m.owner_epoch into v_module_epoch
    from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_module_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select dr38_point_4.* into strict v_run from private.bpay_next_pay_run dr38_point_4
    where id=v_run_id for update;
  select candidate_id into strict v_job.candidate_id
    from private.bpay_next_job where id=p_job_id;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_job.candidate_id for update;
  select dr38_point_5.* into strict v_job from private.bpay_next_job dr38_point_5
    where id=p_job_id for update;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED'
     or v_job.job_kind<>'PREPARE' or v_job.status<>'LEASED'
     or v_job.phase not in ('RESERVE','ALLOCATE')
     or v_job.module_epoch<>v_module_epoch
     or v_job.lease_nonce<>p_lease_nonce
     or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CAPTURE_POSITION_LEASE_STALE';
  end if;
  if v_job.phase='ALLOCATE' then
    return pg_catalog.jsonb_build_object('done',true,'phase','ALLOCATE',
      'replay',true,'rows_visited',0);
  end if;
  if v_job.position_work_cursor is distinct from p_expected_work_cursor
     or v_job.position_component_cursor is distinct from p_expected_component_cursor then
    return pg_catalog.jsonb_build_object('done',false,'phase','RESERVE',
      'replay',true,'rows_visited',0,
      'work_cursor',v_job.position_work_cursor,
      'component_cursor',v_job.position_component_cursor);
  end if;
  select dr38_point_6.* into strict v_worker from private.bpay_next_run_worker dr38_point_6
    where run_id=v_run_id and candidate_id=v_job.candidate_id for update;
  if not private.bpay_next_prepare_job_active_v1(p_job_id) then
    raise exception using errcode='55000',message='BPAY_NEXT_WORKER_ACTION_REVISION_STALE';end if;
  if v_worker.status<>'PREPARING' or v_worker.review_issue_code is not null then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CAPTURE_POSITION_WORKER_NOT_PREPARING';
  end if;
  v_work_cursor:=v_job.position_work_cursor;
  v_component_cursor:=v_job.position_component_cursor;
  for v_member in
    select s.* from private.bpay_next_selected_position_keys_v1(v_worker.id,v_work_cursor,v_component_cursor,p_limit) s
  loop
    -- The Candidate control is already exclusively held. Lock this exact
    -- selected WORK before its position, matching the reentrant seed order.
    perform 1 from private.bpay_next_work w where w.id=v_member.work_id
      and w.candidate_id=v_worker.candidate_id for update;
    if not found then raise exception using errcode='23514',message='BPAY_NEXT_CAPTURE_POSITION_WORK_SCOPE_INVALID';end if;
    -- Read and lock the exact position after choosing the bounded member.
    -- Do not FOR SHARE the nullable side of an outer join (PostgreSQL refuses
    -- that), and never turn a missing selected position into an omitted line.
    select v_member.run_work_id as run_work_id,v_member.work_id as work_id,
           v_member.captured_revision_id as captured_revision_id,
           p.component_key,p.applied_revision_id,
           p.approved_source_ex_vat,p.realised_source_ex_vat,
           p.held_source_ex_vat,p.realised_target_ex_vat,
           p.realised_target_vat,p.realised_target_inc_vat,
           p.held_target_ex_vat,p.held_target_vat,
           p.held_target_inc_vat,p.source_basis_channel,
           rev.source_pay_channel,rev.source_kind,rev.source_event_id,
           rev.source_head_id,rev.financial_snapshot_id,
           rev.physical_timesheet_id,rev.physical_timesheet_version,
           w.work_kind,w.candidate_id as origin_candidate_id,
           l.component_kind,l.id as approved_line_id,
           l.source_pay_ex_vat as approved_line_source_ex_vat,l.tax_treatment,
           p.source_book_state,p.source_book_revision
      into v_row
      from private.bpay_next_position p
      join private.bpay_next_work_revision rev
        on rev.id=v_member.captured_revision_id and rev.work_id=v_member.work_id
      join private.bpay_next_work w on w.id=rev.work_id
      left join private.bpay_next_approved_line l
        on l.revision_id=v_member.captured_revision_id
       and l.component_key=v_member.component_key
      where p.work_id=v_member.work_id and p.component_key=v_member.component_key
      for update of p;
    v_issue:=null;
    if not found
       or v_row.applied_revision_id is distinct from v_member.captured_revision_id then
      v_issue:='CAPTURE_POSITION_CHANGED';
    elsif v_row.approved_line_id is null
       and v_row.approved_source_ex_vat<>0 then
      v_issue:='POSITION_COMPONENT_EVIDENCE_MISSING';
    elsif v_row.approved_line_id is not null
       and v_row.approved_line_source_ex_vat is distinct from
         v_row.approved_source_ex_vat then
      v_issue:='POSITION_APPROVAL_AMOUNT_MISMATCH';
    end if;
    v_approval_revision_id:=v_row.captured_revision_id;v_approval_line_id:=v_row.approved_line_id;
    v_effective_source_event_id:=v_row.source_event_id;
    if v_issue is null and v_row.work_kind='SOURCE' then
      -- Only Source evidence uses the positively qualified canonical approval.
      -- Actual selected, captured and Position identities above remain strict.
      v_approval_revision_id:=private.bpay_next_treatment_approval_revision_v1(v_row.captured_revision_id);
      select r.source_event_id,a.id into v_effective_source_event_id,v_approval_line_id
        from private.bpay_next_work_revision r left join private.bpay_next_approved_line a
          on a.revision_id=r.id and a.component_key=v_row.component_key
        where r.id=v_approval_revision_id and r.work_id=v_row.work_id;
    end if;
    -- The Direct no-HEAD PROTECTED_WORK route retains its original restrictions.
    v_answered_source:=coalesce(v_row.work_kind='SOURCE'
      and (v_row.source_head_id is not null
        or (v_row.source_kind='SOURCE' and v_effective_source_event_id is not null
          and v_row.financial_snapshot_id is not null))
      and v_row.source_pay_channel in ('PAYE','UMBRELLA')
      and ((v_row.component_kind in ('WORK','ADDITIONAL') and v_row.tax_treatment='TAXABLE')
        or (v_row.component_kind in ('EXPENSE','MILEAGE') and v_row.tax_treatment='NON_TAXABLE')),false);
    if v_worker.target_pay_channel='UMBRELLA' and v_issue is null and not v_answered_source
      and not coalesce(v_row.source_pay_channel in ('PAYE','UMBRELLA') and (
        (v_row.work_kind='ORDINARY' and (
          (v_row.component_kind in ('WORK','ADDITIONAL') and v_row.tax_treatment='TAXABLE')
          or (v_row.component_kind in ('EXPENSE','MILEAGE') and v_row.tax_treatment='NON_TAXABLE')))
        or (v_row.work_kind='EXPENSE' and v_row.source_kind='EXPENSE' and v_row.financial_snapshot_id is not null
          and v_row.component_kind in ('EXPENSE','MILEAGE') and v_row.tax_treatment='NON_TAXABLE')),false) and
       (v_row.source_pay_channel is distinct from 'UMBRELLA'
        or v_row.work_kind not in ('ORDINARY','SOURCE')
        or v_row.component_kind is distinct from 'WORK'
        or v_row.tax_treatment is distinct from 'TAXABLE') then
      v_issue:='UMBRELLA_WORK_EXECUTION_UNSUPPORTED';
    end if;
    if v_issue is not null then
      v_issue_work_id:=v_member.work_id;exit;
    end if;
    -- Typed initial I-1 is the ONLY new no-HEAD binding arm. Initial and
    -- common-HEAD captures require self-canonical, exactly classified Source components.
    v_binding:=null;v_book:=null;
    if v_row.work_kind='SOURCE' and (v_row.source_head_id is not null
      or (v_row.source_kind='SOURCE' and v_effective_source_event_id is not null
        and v_row.financial_snapshot_id is not null)) then
      select v.* into v_binding from private.bpay_next_source_component_binding b
        join private.bpay_next_source_component_binding_version v on v.id=b.current_binding_version_id
        where b.canonical_work_id=v_row.work_id and b.canonical_component_key=v_row.component_key
          and v.approval_work_id=v_row.work_id and v.approval_revision_id=v_approval_revision_id
          and v.approval_component_key=v_row.component_key
          and ((v_row.source_head_id is not null and v.origin_kind='COMMON_HEAD_RECEIPT_V1'
              and v.head_id=v_row.source_head_id)
            or (v_row.source_head_id is null and v.origin_kind='INITIAL_AUTHORISED_TSFIN_V1'
              and v.initial_root_authorisation_id=v_effective_source_event_id
              and v.initial_financial_snapshot_id=v_row.financial_snapshot_id
              and v.initial_root_timesheet_id=v_row.physical_timesheet_id
              and v.initial_root_version=v_row.physical_timesheet_version));
      if v_binding.id is null or v_binding.publication_command_id_2 is not null
         or v_row.source_pay_channel not in ('PAYE','UMBRELLA')
         or not v_answered_source then
        v_issue:='SOURCE_BOOK_APPROVAL_UNBOUND';
      else
        if v_row.source_book_state='UNBOUND' then
          -- Capture is already a bounded selected point with real APPLIED/DONE
          -- authority. Adoption never borrows a queued writer's lease here.
          v_seed_effect:=null;v_seed_hold:=null;v_seed_holds:=null;
          if v_row.realised_source_ex_vat>0 then
            select b.original_effect_id into v_seed_effect from private.bpay_next_work_collection b
              where b.work_id=v_row.work_id and b.component_key=v_row.component_key
                and b.candidate_id=v_worker.candidate_id and b.paid_basis_qualified;
          end if;
          if v_row.held_source_ex_vat>0 then
            select pg_catalog.array_agg(h.id order by h.id) into v_seed_holds from (
              select id from private.bpay_next_hold where work_id=v_row.work_id
                and component_key=v_row.component_key and status='ACTIVE' order by id limit 2) h;
            if pg_catalog.cardinality(v_seed_holds) is distinct from 1 then
              raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_BOOK_ACTIVE_HOLD_WITNESS_AMBIGUOUS';
            end if;
            v_seed_hold:=v_seed_holds[1];
          end if;
          select seed.* into strict v_seed from private.bpay_next_source_disposition_seed_v1(
            v_row.work_id,v_row.component_key,v_row.captured_revision_id,v_seed_effect,v_seed_hold) seed;
          if v_seed.qualification_state is distinct from 'READY' then
            raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_BOOK_SELECTED_SEED_NOT_READY';
          end if;
          select p.source_book_state,p.source_book_revision into v_row.source_book_state,v_row.source_book_revision
            from private.bpay_next_position p where p.work_id=v_row.work_id and p.component_key=v_row.component_key;
        end if;
        select s.* into strict v_book from private.bpay_next_bound_source_snapshot_v1(
          v_binding.id,v_row.source_book_revision) s;
        if v_book.qualification_state is distinct from 'READY'
           or (v_book.candidate_id,v_book.canonical_work_id,v_book.canonical_component_key,
               v_book.approval_work_id,v_book.approval_revision_id,v_book.approved_line_id,
               v_book.source_channel,v_book.tax_treatment,v_book.approved_source_ex_vat,
               v_book.native_realised_paye,v_book.native_held_paye,v_book.native_realised_umbrella,v_book.native_held_umbrella)
             is distinct from (v_worker.candidate_id,v_row.work_id,v_row.component_key,
               v_row.work_id,v_approval_revision_id,v_approval_line_id,
               v_row.source_pay_channel,v_row.tax_treatment,v_row.approved_source_ex_vat,
               case when v_row.source_pay_channel='PAYE' then v_row.realised_source_ex_vat else 0::numeric end,
               case when v_row.source_pay_channel='PAYE' then v_row.held_source_ex_vat else 0::numeric end,
               case when v_row.source_pay_channel='UMBRELLA' then v_row.realised_source_ex_vat else 0::numeric end,
               case when v_row.source_pay_channel='UMBRELLA' then v_row.held_source_ex_vat else 0::numeric end) then
          v_issue:='SOURCE_BOOK_APPROVAL_UNBOUND';
        end if;
      end if;
      if v_issue is not null then
        v_issue_work_id:=v_row.work_id;exit;
      end if;
    end if;
    v_collection:=null;
    -- Only the exact typed original ordinary PAYE liability can own a
    -- negative residual. Unknown signed/cross-basis/held shapes still REVIEW.
    if v_worker.target_pay_channel='PAYE' and v_row.source_pay_channel='PAYE'
       and v_row.approved_source_ex_vat-v_row.realised_source_ex_vat<0
       and (v_row.held_source_ex_vat,v_row.held_target_ex_vat,v_row.held_target_vat,v_row.held_target_inc_vat)
         is not distinct from (0::numeric,0::numeric,0::numeric,0::numeric) then
      select b.* into v_collection from private.bpay_next_work_collection b
        where b.work_id=v_row.work_id and b.component_key=v_row.component_key;
      if v_collection.case_id is not null then
        v_collection:=private.bpay_next_work_collection_origin_v1(
          v_collection.case_id,v_collection.case_component_id,v_worker.candidate_id);
      else v_collection:=null;end if;
      if v_collection.id is not null and
         (v_collection.observed_revision_id,v_collection.observed_approved_source_ex_vat,v_collection.observed_realised_source_ex_vat)
           is distinct from (v_row.captured_revision_id,v_row.approved_source_ex_vat,v_row.realised_source_ex_vat) then
        v_collection:=null;
      end if;
    end if;
    v_needs_resolution:=v_collection.id is null and (
       v_row.approved_line_id is null
       or v_row.approved_source_ex_vat<0
       or ((v_row.realised_source_ex_vat<>0
          or v_row.held_source_ex_vat<>0
          or v_row.realised_target_inc_vat<>0
          or v_row.held_target_inc_vat<>0)
         and v_row.source_basis_channel is distinct from v_row.source_pay_channel)
       or v_row.realised_source_ex_vat<0
       or v_row.realised_target_ex_vat<0 or v_row.realised_target_vat<0 or v_row.realised_target_inc_vat<0
       or (v_row.held_source_ex_vat>0 and v_row.approved_source_ex_vat-v_row.realised_source_ex_vat-v_row.held_source_ex_vat<=0)
       or (v_row.held_source_ex_vat=0 and v_row.held_target_inc_vat<>0)
       or v_row.approved_source_ex_vat-v_row.realised_source_ex_vat-v_row.held_source_ex_vat<0);
    -- Only genuine positive Source WORK consumes the retained disposition.
    -- Expense/additional/ordinary, zero, realised/held-away, managed negative
    -- and already-unresolved financial shapes do not become query holds.
    -- The actual pin validated the typed origin before this immutable row;
    -- missing evidence is REVIEW, never a lazy live Source reader fallback.
    if v_row.work_kind='SOURCE' and v_row.source_kind in ('SOURCE','PROTECTED')
       and v_effective_source_event_id is not null
       and v_row.component_kind in ('WORK','PROTECTED_WORK')
       and not v_needs_resolution
       and v_row.approved_source_ex_vat-v_row.realised_source_ex_vat-v_row.held_source_ex_vat>0 then
      select qp.* into v_query_pin from private.bpay_next_run_work_query_pin_v2 qp
        where qp.run_work_id=v_row.run_work_id;
      if found and (private.bpay_next_prepare_job_run_v1(v_query_pin.prepare_job_id) is distinct from v_run_id
        or (v_query_pin.run_worker_id,v_query_pin.candidate_id,
          v_query_pin.work_id,v_query_pin.captured_revision_id,
          v_query_pin.module_epoch,v_query_pin.gate_version)
          is distinct from (v_worker.id,v_worker.candidate_id,
          v_row.work_id,v_row.captured_revision_id,v_module_epoch,'PAY_QUERY_STATE_V3'::text)) then
        raise exception using errcode='23514',message='BPAY_NEXT_CAPTURE_QUERY_PIN_MISMATCH';
      end if;
      if not found or v_query_pin.disposition='UNAVAILABLE' then
        v_issue:='SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE';
      elsif v_query_pin.disposition='BLOCKED' then
        -- Only the original cut's complete, exact named shift exclusions
        -- can bypass a whole-Work blocker. Never read today's query here.
        if not exists(select 1 from private.bpay_next_run_work_query_snapshot snapshot
          where snapshot.run_id=v_run_id and snapshot.work_id=v_row.work_id
            and snapshot.expected_revision_id=v_row.captured_revision_id
            and snapshot.physical_timesheet_id::text=(v_query_pin.scope->>'root_timesheet_id')
            and jsonb_typeof(snapshot.segment_query_exclusions)='array'
            and jsonb_array_length(snapshot.segment_query_exclusions)>0)
        then v_issue:='SOURCE_PAY_QUERY_OPEN';end if;
      elsif v_query_pin.disposition<>'CLEAR' or v_query_pin.scope is null
         or v_query_pin.query_state_sha256 is null
         or pg_catalog.octet_length(v_query_pin.query_state_sha256)<>32 then
        raise exception using errcode='23514',message='BPAY_NEXT_CAPTURE_QUERY_PIN_INVALID';
      end if;
      if v_issue is not null then
        v_issue_work_id:=v_row.work_id;exit;
      end if;
    end if;
    select count(*) into v_segments from (
      select s.segment_key from private.bpay_next_approved_segment s
        where s.revision_id=v_row.captured_revision_id and s.component_key=v_row.component_key
      union select s.segment_key from private.bpay_next_work_segment_origin_share s
        where s.work_id=v_row.work_id and s.component_key=v_row.component_key) members;
    if v_segments>0 and v_row.work_kind='ORDINARY' then
      -- Exact segment negative ownership is sealed after complete child capture.
      -- Initial native net-negative classification cannot bypass that census.
      if v_collection.id is not null then v_needs_resolution:=true;end if;
      v_collection:=null;
    end if;
    v_snooze:=null;
    if v_segments=0 then
      v_snooze:=private.bpay_next_snooze_at_cut_v1(v_row.work_id,v_row.captured_revision_id,
        null,v_row.component_key,v_run.snooze_control_sequence,v_run.snooze_business_date);
    end if;
    insert into private.bpay_next_run_position
      (run_worker_id,run_work_id,work_id,captured_revision_id,
       component_key,approved_line_id,source_pay_channel,
       source_basis_channel,
       approved_source_ex_vat,realised_source_ex_vat,held_source_ex_vat,
       residual_source_ex_vat,realised_target_ex_vat,realised_target_vat,
       realised_target_inc_vat,held_target_ex_vat,held_target_vat,
       held_target_inc_vat,needs_financial_resolution,work_collection_id,work_collection_revision,
       source_binding_version_id,canonical_source_work_id,canonical_source_component_key,source_book_revision,
       segment_expected_member_count,segment_attribution_complete,snooze_id,snooze_version,snooze_excluded_positive_ex_vat)
      values(v_worker.id,v_row.run_work_id,v_row.work_id,
       v_row.captured_revision_id,v_row.component_key,v_row.approved_line_id,
       v_row.source_pay_channel,v_row.source_basis_channel,
       v_row.approved_source_ex_vat,
       v_row.realised_source_ex_vat,v_row.held_source_ex_vat,
       v_row.approved_source_ex_vat-v_row.realised_source_ex_vat
         -v_row.held_source_ex_vat,
       v_row.realised_target_ex_vat,v_row.realised_target_vat,
       v_row.realised_target_inc_vat,v_row.held_target_ex_vat,
       v_row.held_target_vat,v_row.held_target_inc_vat,
       v_needs_resolution,v_collection.id,v_collection.reconcile_revision,
       v_binding.id,v_binding.canonical_work_id,v_binding.canonical_component_key,
       case when v_binding.id is null then null else v_row.source_book_revision end,
       v_segments,v_segments=0,(v_snooze->>'id')::uuid,(v_snooze->>'version')::bigint,
       case when v_snooze is not null then greatest(v_row.approved_source_ex_vat-v_row.realised_source_ex_vat-v_row.held_source_ex_vat,0) else 0 end);
    if v_needs_resolution then
      v_resolution_count:=v_resolution_count+1;
    end if;
    if v_collection.id is not null then v_managed_seen:=v_managed_seen+1;end if;
    v_work_cursor:=v_row.work_id;
    v_component_cursor:=v_row.component_key;
    v_seen:=v_seen+1;
    if v_member.selection_mode='SUBSET' then
      v_selected_seen:=v_selected_seen+1;
    end if;
  end loop;
  if v_resolution_count>0 then
    update private.bpay_next_run_worker
      set financial_resolution_count=financial_resolution_count+v_resolution_count
      where id=v_worker.id;
  end if;
  if v_seen>0 then
    update private.bpay_next_run_worker
      set captured_position_count=captured_position_count+v_seen,
          expected_managed_position_count=expected_managed_position_count+v_managed_seen,
          captured_selected_component_count=
            captured_selected_component_count+v_selected_seen
      where id=v_worker.id;
  end if;
  update private.bpay_next_job set position_work_cursor=v_work_cursor,position_component_cursor=v_component_cursor where id=p_job_id;
  if v_issue is not null then
    update private.bpay_next_run_worker set status='REVIEW',review_issue_code=v_issue,review_issue_work_id=v_issue_work_id where id=v_worker.id;
    return private.bpay_next_begin_prepare_projection_v1(p_job_id,p_lease_nonce,p_owner_epoch,v_seen);
  end if;
  if v_seen<p_limit then
    if v_worker.captured_selected_component_count+v_selected_seen
       <>v_worker.expected_selected_component_count then
      select rw.work_id into strict v_issue_work_id
        from private.bpay_next_run_work rw
        join private.bpay_next_work_choice choice
          on choice.run_id=v_run_id and choice.work_id=rw.work_id
         and choice.selection_mode='SUBSET'
        where rw.run_worker_id=v_worker.id
        order by rw.work_id limit 1;
      update private.bpay_next_run_worker
        set status='REVIEW',review_issue_code='CAPTURE_POSITION_CHANGED',
            review_issue_work_id=v_issue_work_id
        where id=v_worker.id;
      return private.bpay_next_begin_prepare_projection_v1(p_job_id,p_lease_nonce,p_owner_epoch,v_seen);
    end if;
    v_segment_result:=private.bpay_next_capture_segment_page_v1(v_worker.id,p_limit-v_seen);
    v_segment_visited:=(v_segment_result->>'rows_visited')::integer;
    select w.* into strict v_worker from private.bpay_next_run_worker w where w.id=v_worker.id;
    if v_worker.status='REVIEW' then
      return private.bpay_next_begin_prepare_projection_v1(p_job_id,p_lease_nonce,p_owner_epoch,v_seen+v_segment_visited);
    end if;
    if not (v_segment_result->>'done')::boolean then
      update private.bpay_next_job set position_work_cursor=v_work_cursor,position_component_cursor=v_component_cursor where id=p_job_id;
      return jsonb_build_object('done',false,'phase','RESERVE','rows_visited',v_seen+v_segment_visited,
        'work_cursor',v_work_cursor,'component_cursor',v_component_cursor,'replay',false);
    end if;
    update private.bpay_next_job
      set phase='ALLOCATE',position_work_cursor=null,
          position_component_cursor=null
      where id=p_job_id;
    return pg_catalog.jsonb_build_object('done',true,'phase','ALLOCATE',
      'rows_visited',v_seen+v_segment_visited,'replay',false);
  end if;
  update private.bpay_next_job
    set position_work_cursor=v_work_cursor,
        position_component_cursor=v_component_cursor
    where id=p_job_id;
  return pg_catalog.jsonb_build_object('done',false,'phase','RESERVE',
    'rows_visited',v_seen+v_segment_visited,'work_cursor',v_work_cursor,
    'component_cursor',v_component_cursor,'replay',false);
end
$function$;
create or replace function private.bpay_next_hold_fresh_position_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_work_cursor uuid,p_expected_component_cursor text,
  p_limit integer default 100
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_approval_revision_id uuid;v_approval_line_id uuid;v_choice_refs jsonb;v_line_refs jsonb;v_selected_quote jsonb;
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_module_epoch bigint;
  v_issue_work_id uuid;
  v_row record;
  v_position private.bpay_next_position%rowtype;
  v_value record;v_book record;
  v_reimbursement_window uuid;v_reimbursement_vat_pct numeric;v_reimbursement_window_count bigint;v_reimbursement_amounts jsonb;
  v_run_line_id uuid;v_hold_id uuid;v_included_source numeric(18,2);v_freeze_zero boolean;
  v_seen integer:=0;
  v_affected_work_ids uuid[]:=array[]::uuid[];
  v_work_cursor uuid;
  v_component_cursor text;
  v_line_count bigint;
  v_managed_count bigint;
  v_total_ex numeric(18,2);
  v_total_vat numeric(18,2);
  v_total_inc numeric(18,2);
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_limit not between 1 and 100
     or (p_expected_work_cursor is null and p_expected_component_cursor is not null) then
    raise exception using errcode='22023',message='BPAY_NEXT_HOLD_INPUT_INVALID';
  end if;
  select private.bpay_next_prepare_job_run_v1(j.id) into strict v_run_id
    from private.bpay_next_job j
    where j.id=p_job_id and j.job_kind='PREPARE';
  select m.owner_epoch into v_module_epoch
    from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_module_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select dr38_point_7.* into strict v_run from private.bpay_next_pay_run dr38_point_7
    where id=v_run_id for update;
  select candidate_id into strict v_job.candidate_id
    from private.bpay_next_job where id=p_job_id;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_job.candidate_id for update;
  select dr38_point_8.* into strict v_job from private.bpay_next_job dr38_point_8
    where id=p_job_id for update;
  if not private.bpay_next_prepare_job_active_v1(p_job_id) then
    raise exception using errcode='55000',message='BPAY_NEXT_WORKER_ACTION_REVISION_STALE';end if;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED'
     or v_job.job_kind<>'PREPARE' or v_job.status<>'LEASED'
     or v_job.phase not in ('ALLOCATE','FINANCE_ALLOCATE')
     or v_job.module_epoch<>v_module_epoch
     or v_job.lease_nonce<>p_lease_nonce
     or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() then
    raise exception using errcode='55000',message='BPAY_NEXT_HOLD_LEASE_STALE';
  end if;
  if v_job.phase='FINANCE_ALLOCATE' then
    return pg_catalog.jsonb_build_object('done',true,
      'phase','FINANCE_ALLOCATE','rows_visited',0,'replay',true);
  end if;
  if v_job.position_work_cursor is distinct from p_expected_work_cursor
     or v_job.position_component_cursor is distinct from p_expected_component_cursor then
    return pg_catalog.jsonb_build_object('done',false,'phase','ALLOCATE',
      'rows_visited',0,'replay',true,
      'work_cursor',v_job.position_work_cursor,
      'component_cursor',v_job.position_component_cursor);
  end if;
  select dr38_point_9.* into strict v_worker from private.bpay_next_run_worker dr38_point_9
    where run_id=v_run_id and candidate_id=v_job.candidate_id for update;
  if v_worker.status<>'PREPARING' or v_worker.review_issue_code is not null then
    raise exception using errcode='55000',
      message='BPAY_NEXT_HOLD_WORKER_NOT_PREPARING';
  end if;
  if v_worker.financial_resolution_count>0 then
    select rp.work_id into strict v_issue_work_id
      from private.bpay_next_run_position rp
      where rp.run_worker_id=v_worker.id and rp.needs_financial_resolution
      order by rp.work_id,rp.component_key limit 1;
    update private.bpay_next_run_worker
      set status='REVIEW',review_issue_code='FINANCIAL_RESOLUTION_REQUIRED',
          review_issue_work_id=v_issue_work_id
      where id=v_worker.id;
    return private.bpay_next_begin_prepare_projection_v1(p_job_id,p_lease_nonce,p_owner_epoch,0);
  end if;
  if v_worker.target_pay_channel='UMBRELLA'
     and (v_worker.target_umbrella_id is null
       or v_worker.target_umbrella_vat_chargeable is null) then
    select rp.work_id into v_issue_work_id
      from private.bpay_next_run_position rp
      where rp.run_worker_id=v_worker.id
      order by rp.work_id,rp.component_key limit 1;
    if v_issue_work_id is not null then
      update private.bpay_next_run_worker
        set status='REVIEW',review_issue_code='TARGET_UMBRELLA_MISSING',
            review_issue_work_id=v_issue_work_id
        where id=v_worker.id;
      return private.bpay_next_begin_prepare_projection_v1(p_job_id,p_lease_nonce,p_owner_epoch,0);
    end if;
  end if;
  v_work_cursor:=v_job.position_work_cursor;
  v_component_cursor:=v_job.position_component_cursor;
  v_line_count:=v_worker.captured_line_count;
  v_managed_count:=v_worker.captured_managed_position_count;
  v_total_ex:=v_worker.gross_ex_vat;
  v_total_vat:=v_worker.gross_vat;
  v_total_inc:=v_worker.gross_inc_vat;
  for v_row in
    select rp.*,rw.id as pinned_work_id,rev.valuation_policy_id,rev.source_kind as captured_source_kind,
      rev.financial_snapshot_id as captured_financial_snapshot_id,
      w.work_kind as captured_work_kind,l.component_kind as captured_component_kind,l.tax_treatment as captured_tax_treatment
      from private.bpay_next_run_position rp
      join private.bpay_next_run_work rw on rw.id=rp.run_work_id
      join private.bpay_next_work_revision rev
        on rev.id=rp.captured_revision_id and rev.work_id=rp.work_id
      join private.bpay_next_work w on w.id=rp.work_id
      left join private.bpay_next_approved_line l on l.id=rp.approved_line_id
        and l.revision_id=rp.captured_revision_id and l.component_key=rp.component_key
      where rp.run_worker_id=v_worker.id
        and (v_work_cursor is null or rp.work_id>v_work_cursor
          or (rp.work_id=v_work_cursor
            and rp.component_key>v_component_cursor))
      order by rp.work_id,rp.component_key limit p_limit
  loop
    if not v_row.segment_attribution_complete then
      raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_CAPTURE_INCOMPLETE';
    end if;
    v_included_source:=case when v_row.segment_member_count>0 then v_row.segment_included_positive_ex_vat
      else greatest(v_row.residual_source_ex_vat,0)-v_row.snooze_excluded_positive_ex_vat end;
    v_freeze_zero:=v_row.approved_line_id is not null and v_row.approved_source_ex_vat=0 and v_row.realised_source_ex_vat=0 and v_row.held_source_ex_vat=0
      and v_row.snooze_id is null and (v_row.segment_member_count=0 or exists(
        select 1 from private.bpay_next_run_work_segment_parent p join private.bpay_next_run_work_segment s on s.id=p.run_work_segment_id
          where p.run_work_id=v_row.run_work_id and p.component_key=v_row.component_key and s.disposition='INCLUDED'));
    if v_row.segment_member_count=0 and not private.bpay_next_choice_leaf_eligible_v1(
      v_run.id,v_row.work_id,v_row.captured_revision_id,v_row.approved_line_id,null) then
      -- Complete A/R/H remains captured; an unselected component supplies no pay.
      v_included_source:=0;v_freeze_zero:=false;
    end if;
    if v_row.needs_financial_resolution
       or (v_row.work_collection_id is null and
         ((v_row.approved_line_id is null and (v_row.segment_member_count=0 or v_included_source>0)) or v_row.residual_source_ex_vat<0)) then
      raise exception using errcode='23514',
        message='BPAY_NEXT_HOLD_UNEXPECTED_POSITION_SHAPE';
    end if;
    select dr38_point_10.* into strict v_position from private.bpay_next_position dr38_point_10
      where work_id=v_row.work_id and component_key=v_row.component_key
      for update;
    if v_position.applied_revision_id is distinct from v_row.captured_revision_id
       or v_position.approved_source_ex_vat is distinct from
         v_row.approved_source_ex_vat
       or v_position.realised_source_ex_vat is distinct from
         v_row.realised_source_ex_vat
       or v_position.held_source_ex_vat is distinct from
         v_row.held_source_ex_vat
       or v_position.source_basis_channel is distinct from
         v_row.source_basis_channel
       or v_position.realised_target_ex_vat is distinct from
         v_row.realised_target_ex_vat
       or v_position.realised_target_vat is distinct from
         v_row.realised_target_vat
       or v_position.realised_target_inc_vat is distinct from
         v_row.realised_target_inc_vat
       or v_position.held_target_ex_vat is distinct from
         v_row.held_target_ex_vat
       or v_position.held_target_vat is distinct from
         v_row.held_target_vat
       or v_position.held_target_inc_vat is distinct from
         v_row.held_target_inc_vat then
      raise exception using errcode='55000',
        message='BPAY_NEXT_HOLD_CURRENT_POSITION_CHANGED';
    end if;
    if v_row.source_binding_version_id is not null then
      v_approval_revision_id:=private.bpay_next_treatment_approval_revision_v1(v_row.captured_revision_id);
      select a.id into v_approval_line_id from private.bpay_next_approved_line a
        where a.revision_id=v_approval_revision_id and a.component_key=v_row.component_key;
      select s.* into strict v_book from private.bpay_next_bound_source_snapshot_v1(
        v_row.source_binding_version_id,v_row.source_book_revision) s;
      if v_book.qualification_state is distinct from 'READY'
         or (v_book.canonical_work_id,v_book.canonical_component_key,v_book.approval_work_id,
             v_book.approval_revision_id,v_book.approved_line_id,v_book.source_channel,v_book.tax_treatment,
             v_book.approved_source_ex_vat,v_book.native_realised_paye,v_book.native_held_paye,
             v_book.native_realised_umbrella,v_book.native_held_umbrella)
           is distinct from (v_row.work_id,v_row.component_key,v_row.work_id,
             v_approval_revision_id,v_approval_line_id,v_row.source_pay_channel,v_row.captured_tax_treatment,
             v_row.approved_source_ex_vat,
             case when v_row.source_pay_channel='PAYE' then v_row.realised_source_ex_vat else 0::numeric end,
             case when v_row.source_pay_channel='PAYE' then v_row.held_source_ex_vat else 0::numeric end,
             case when v_row.source_pay_channel='UMBRELLA' then v_row.realised_source_ex_vat else 0::numeric end,
             case when v_row.source_pay_channel='UMBRELLA' then v_row.held_source_ex_vat else 0::numeric end)
         or v_row.source_pay_channel not in ('PAYE','UMBRELLA')
         or coalesce(v_row.captured_work_kind='SOURCE'
           and ((v_row.captured_component_kind in ('WORK','ADDITIONAL') and v_row.captured_tax_treatment='TAXABLE')
             or (v_row.captured_component_kind in ('EXPENSE','MILEAGE') and v_row.captured_tax_treatment='NON_TAXABLE')),false) is not true
         or v_row.canonical_source_work_id is distinct from v_row.work_id
         or v_row.canonical_source_component_key is distinct from v_row.component_key then
        raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_BOOK_CAPTURE_CHANGED';
      end if;
    end if;
    select c.accepted_resolution_refs into v_choice_refs from private.bpay_next_work_choice c
      where c.run_id=v_run.id and c.work_id=v_row.work_id and c.expected_revision_id=v_row.captured_revision_id;
    v_line_refs:=null;
    if v_choice_refs is not null then
      select coalesce(jsonb_agg(x.value order by x.value->>'rate_family',x.value->>'rate_code'),'[]') into v_line_refs
        from jsonb_array_elements(v_choice_refs) x where (x.value->>'approved_line_id')::uuid=v_row.approved_line_id;
    end if;
    if v_row.work_collection_id is not null then
      -- Classification and original provenance were frozen by RESERVE. Never
      -- reread a newer WORK approval or create an ordinary negative/zero hold.
      update private.bpay_next_run_position set managed_capture_completed=true
        where id=v_row.id and not managed_capture_completed;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_CAPTURE_ALREADY_SPENT';end if;
      v_managed_count:=v_managed_count+1;
    end if;
    if v_included_source>0 or v_freeze_zero then
    if ((v_row.source_binding_version_id is not null and v_row.captured_work_kind='SOURCE')
        or v_row.captured_work_kind='ORDINARY'
        or (v_row.captured_work_kind='EXPENSE' and v_row.captured_source_kind='EXPENSE'
          and v_row.captured_financial_snapshot_id is not null))
      and v_row.captured_component_kind in ('EXPENSE','MILEAGE') and v_row.captured_tax_treatment='NON_TAXABLE' then
      -- A classified ordinary/Source reimbursement keeps source ex; only ordinary line VAT applies.
      -- Use the same immutable winning policy window and existing VAT calculator.
      if v_included_source is null or v_row.valuation_policy_id is null or v_run.pay_date is null
        or v_row.source_pay_channel is null or v_row.source_pay_channel not in ('PAYE','UMBRELLA')
        or v_worker.target_pay_channel is null or v_worker.target_pay_channel not in ('PAYE','UMBRELLA')
        or (v_worker.target_pay_channel='UMBRELLA' and v_worker.target_umbrella_vat_chargeable is null)
        or v_included_source<>pg_catalog.round(v_included_source,2) then
        raise exception using errcode='22023',message='BPAY_NEXT_TARGET_VALUATION_INPUT_INVALID';end if;
      v_reimbursement_window:=null;v_reimbursement_vat_pct:=null;v_reimbursement_window_count:=null;
      select w.source_window_id,w.vat_rate_pct,count(*) over(partition by w.date_from)
        into v_reimbursement_window,v_reimbursement_vat_pct,v_reimbursement_window_count
        from private.bpay_next_valuation_policy_window w
        where w.policy_id=v_row.valuation_policy_id and v_run.pay_date>=w.date_from
          and v_run.pay_date<=coalesce(w.date_to,'infinity'::date)
        order by w.date_from desc,w.source_window_id desc limit 1;
      if v_reimbursement_window is null then
        raise exception using errcode='23514',message='BPAY_NEXT_TARGET_POLICY_WINDOW_MISSING';end if;
      if v_reimbursement_window_count<>1 then
        raise exception using errcode='23514',message='BPAY_NEXT_TARGET_POLICY_WINDOW_AMBIGUOUS';end if;
      if v_worker.target_pay_channel='UMBRELLA' then
        v_reimbursement_amounts:=public._pay_umbrella_vat_calc(v_included_source,
          v_reimbursement_vat_pct,v_worker.target_umbrella_vat_chargeable);
        select v_reimbursement_window as policy_window_id,v_included_source as target_ex_vat,
          (v_reimbursement_amounts->>'vat')::numeric as target_vat,
          (v_reimbursement_amounts->>'inc')::numeric as target_inc_vat into strict v_value;
      else
        select v_reimbursement_window as policy_window_id,v_included_source as target_ex_vat,
          0::numeric as target_vat,v_included_source as target_inc_vat into strict v_value;
      end if;
    elsif v_line_refs is not null and jsonb_array_length(v_line_refs)>0 then
      v_selected_quote:=private.bpay_next_captured_component_resolution_quote_v1(v_row.id,null);
      if v_selected_quote->'accepted_resolution_refs' is distinct from v_line_refs
        or (v_selected_quote->>'included_source_component_ex_vat')::numeric is distinct from v_included_source then
        raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_ACCEPTED_BASIS_CHANGED';end if;
      select (v_selected_quote->>'valuation_window_id')::uuid as policy_window_id,
        (v_selected_quote#>>'{component_quote,ex}')::numeric as target_ex_vat,
        (v_selected_quote#>>'{component_quote,vat}')::numeric as target_vat,
        (v_selected_quote#>>'{component_quote,inc}')::numeric as target_inc_vat into strict v_value;
    else
    select * into strict v_value
      from private.bpay_next_value_source_for_target_v1(
        v_included_source,v_row.source_pay_channel,
        v_worker.target_pay_channel,
        case when v_worker.target_pay_channel='UMBRELLA'
          then v_worker.target_umbrella_vat_chargeable else false end,
        v_row.valuation_policy_id,v_run.pay_date);
    end if;
    v_line_count:=v_line_count+1;
    insert into private.bpay_next_run_line
      (run_worker_id,run_work_id,line_no,approved_line_id,
       captured_revision_id,work_id,component_key,source_consumed_ex_vat,
       source_pay_channel,target_pay_channel,valuation_policy_id,
       policy_window_id,frozen_ex_vat,frozen_vat,frozen_inc_vat,source_binding_version_id,
       canonical_source_work_id,canonical_source_component_key,source_book_revision,updates_original_source_scalar,accepted_resolution_refs)
      values(v_worker.id,v_row.run_work_id,v_line_count,
       v_row.approved_line_id,v_row.captured_revision_id,v_row.work_id,
       v_row.component_key,v_included_source,
       v_row.source_pay_channel,v_worker.target_pay_channel,
       v_row.valuation_policy_id,v_value.policy_window_id,
       v_value.target_ex_vat,v_value.target_vat,v_value.target_inc_vat,
       v_row.source_binding_version_id,v_row.canonical_source_work_id,v_row.canonical_source_component_key,
       v_row.source_book_revision,case when v_row.source_binding_version_id is null then null else true end,v_line_refs)
      returning id into v_run_line_id;
    -- An authorised zero still has immutable shift/rate advice detail. It
    -- becomes a frozen zero line, never a zero-valued financial hold.
    if v_included_source>0 then
      insert into private.bpay_next_hold
        (run_line_id,work_id,component_key,source_reserved_ex_vat,
         target_amount_ex_vat,target_amount_vat,target_amount_inc_vat,status)
        values(v_run_line_id,v_row.work_id,v_row.component_key,
         v_included_source,v_value.target_ex_vat,
         v_value.target_vat,v_value.target_inc_vat,'ACTIVE') returning id into v_hold_id;
      perform private.bpay_next_record_work_segment_origin_shares_v1(v_run_line_id,v_hold_id);
      update private.bpay_next_position
        set held_source_ex_vat=held_source_ex_vat+v_included_source,
            held_target_ex_vat=held_target_ex_vat+v_value.target_ex_vat,
            held_target_vat=held_target_vat+v_value.target_vat,
            held_target_inc_vat=held_target_inc_vat+v_value.target_inc_vat,
            updated_at_utc=pg_catalog.transaction_timestamp()
        where work_id=v_row.work_id and component_key=v_row.component_key;
    end if;
    v_total_ex:=v_total_ex+v_value.target_ex_vat;
    v_total_vat:=v_total_vat+v_value.target_vat;
    v_total_inc:=v_total_inc+v_value.target_inc_vat;
    end if;
    v_affected_work_ids:=array_append(v_affected_work_ids,v_row.work_id);
    v_work_cursor:=v_row.work_id;
    v_component_cursor:=v_row.component_key;
    v_seen:=v_seen+1;
  end loop;
  if v_seen>0 then
    update private.bpay_next_run_worker
      set captured_line_count=v_line_count,
          captured_managed_position_count=v_managed_count,
          gross_ex_vat=v_total_ex,gross_vat=v_total_vat,
          gross_inc_vat=v_total_inc
      where id=v_worker.id;
    update private.bpay_next_worker_control
      set financial_view_revision=financial_view_revision+1,
          updated_at_utc=pg_catalog.transaction_timestamp()
      where candidate_id=v_job.candidate_id;
    perform private.bpay_next_workbench_refresh_many_v1(v_affected_work_ids,null);
  end if;
  if v_seen<p_limit then
    if v_managed_count<>v_worker.expected_managed_position_count or exists(
      select 1 from private.bpay_next_run_position where run_worker_id=v_worker.id
        and work_collection_id is not null and not managed_capture_completed) then
      raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_CAPTURE_COUNT_MISMATCH';
    end if;
    update private.bpay_next_job
      set phase='FINANCE_ALLOCATE',position_work_cursor=null,
          position_component_cursor=null
      where id=p_job_id;
    return pg_catalog.jsonb_build_object('done',true,
      'phase','FINANCE_ALLOCATE','rows_visited',v_seen,'replay',false);
  end if;
  update private.bpay_next_job
    set position_work_cursor=v_work_cursor,
        position_component_cursor=v_component_cursor
    where id=p_job_id;
  return pg_catalog.jsonb_build_object('done',false,'phase','ALLOCATE',
    'rows_visited',v_seen,'work_cursor',v_work_cursor,
    'component_cursor',v_component_cursor,'replay',false);
end
$function$;
create or replace function private.bpay_next_record_work_segment_origin_shares_v1(p_run_line_id uuid,p_hold_id uuid)
returns void language plpgsql volatile security invoker set search_path=pg_catalog,private
as $function$
declare
  v_line private.bpay_next_run_line%rowtype; v_hold private.bpay_next_hold%rowtype;
  v_position private.bpay_next_run_position%rowtype; v_worker private.bpay_next_run_worker%rowtype;
  v_run private.bpay_next_pay_run%rowtype; v_total record; v_expected bigint;v_selected_quote jsonb;
begin
  select l.* into strict v_line from private.bpay_next_run_line l where l.id=p_run_line_id;
  select h.* into strict v_hold from private.bpay_next_hold h where h.id=p_hold_id;
  select p.* into strict v_position from private.bpay_next_run_position p
    where p.run_work_id=v_line.run_work_id and p.component_key=v_line.component_key;
  if (v_hold.run_line_id,v_hold.work_id,v_hold.component_key,v_hold.source_reserved_ex_vat,
      v_hold.target_amount_ex_vat,v_hold.target_amount_vat,v_hold.target_amount_inc_vat,v_hold.status)
    is distinct from (v_line.id,v_line.work_id,v_line.component_key,v_line.source_consumed_ex_vat,
      v_line.frozen_ex_vat,v_line.frozen_vat,v_line.frozen_inc_vat,'ACTIVE'::text) then
    raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_HOLD_PARENT_MISMATCH';
  end if;
  if v_position.segment_member_count=0 then return; end if;
  if not v_position.segment_attribution_complete or v_position.segment_included_positive_ex_vat<>v_hold.source_reserved_ex_vat then
    raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_HOLD_CAPTURE_INCOMPLETE';
  end if;
  select w.* into strict v_worker from private.bpay_next_run_worker w where w.id=v_line.run_worker_id;
  select r.* into strict v_run from private.bpay_next_pay_run r where r.id=v_worker.run_id;
  -- One completed captured parent; no live approval/history or NET allocation.
  -- Shared gross valuation of cumulative prefixes conserves the parent's pennies.
  if v_line.accepted_resolution_refs is not null and jsonb_array_length(v_line.accepted_resolution_refs)>0 then
    -- One complete native gather and cumulative bucket plan, never one gather per prefix.
    v_selected_quote:=private.bpay_next_captured_component_resolution_quote_v1(v_position.id,null);
    if v_selected_quote->'accepted_resolution_refs' is distinct from v_line.accepted_resolution_refs
      or ((v_selected_quote#>>'{component_quote,ex}')::numeric,(v_selected_quote#>>'{component_quote,vat}')::numeric,
          (v_selected_quote#>>'{component_quote,inc}')::numeric)
        is distinct from (v_line.frozen_ex_vat,v_line.frozen_vat,v_line.frozen_inc_vat) then
      raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_HOLD_SHARE_TOTAL_MISMATCH';end if;
    with prefixes as materialized (
      select x.segment_key,x.run_work_segment_id,x.source_ex_vat,
        (x.quote->>'ex')::numeric target_ex,(x.quote->>'vat')::numeric target_vat
      from jsonb_to_recordset(v_selected_quote->'prefix_targets') as x(segment_key text,run_work_segment_id uuid,source_ex_vat numeric,quote jsonb)
    ), shares as (
      select p.*,p.target_ex-coalesce(lag(p.target_ex) over(order by p.segment_key),0) share_ex,
        p.target_vat-coalesce(lag(p.target_vat) over(order by p.segment_key),0) share_vat from prefixes p
    )
    insert into private.bpay_next_work_segment_origin_share(hold_id,run_line_id,run_work_segment_id,
      work_id,component_key,segment_key,source_reserved_ex_vat,target_reserved_ex_vat,target_reserved_vat,target_reserved_inc_vat)
    select v_hold.id,v_line.id,p.run_work_segment_id,v_line.work_id,v_line.component_key,p.segment_key,
      p.source_ex_vat,p.share_ex,p.share_vat,p.share_ex+p.share_vat from shares p;
  else
  with members as materialized (
    select p.*,sum(p.included_positive_source_ex_vat) over(order by p.segment_key) cumulative_source
    from private.bpay_next_run_work_segment_parent p where p.run_work_id=v_line.run_work_id
      and p.component_key=v_line.component_key and p.included_positive_source_ex_vat>0
  ), quoted as materialized (
    select p.*,q.target_ex_vat,q.target_vat,q.target_inc_vat from members p
    cross join lateral private.bpay_next_value_source_for_target_v1(p.cumulative_source,v_line.source_pay_channel,
      v_line.target_pay_channel,case when v_line.target_pay_channel='UMBRELLA'
        then v_worker.target_umbrella_vat_chargeable else false end,v_line.valuation_policy_id,v_run.pay_date) q
  ), shares as (
    select p.*,p.target_ex_vat-coalesce(lag(p.target_ex_vat) over(order by p.segment_key),0) share_ex,
      p.target_vat-coalesce(lag(p.target_vat) over(order by p.segment_key),0) share_vat
    from quoted p
  )
  insert into private.bpay_next_work_segment_origin_share(hold_id,run_line_id,run_work_segment_id,
    work_id,component_key,segment_key,source_reserved_ex_vat,target_reserved_ex_vat,target_reserved_vat,target_reserved_inc_vat)
  select v_hold.id,v_line.id,p.run_work_segment_id,v_line.work_id,v_line.component_key,p.segment_key,
    p.included_positive_source_ex_vat,p.share_ex,p.share_vat,p.share_ex+p.share_vat from shares p;
  end if;
  select count(*),sum(s.source_reserved_ex_vat) source_total,sum(s.target_reserved_ex_vat) target_ex,
    sum(s.target_reserved_vat) target_vat,sum(s.target_reserved_inc_vat) target_inc into v_total
    from private.bpay_next_work_segment_origin_share s where s.hold_id=v_hold.id;
  select count(*) into v_expected from private.bpay_next_run_work_segment_parent p
    where p.run_work_id=v_line.run_work_id and p.component_key=v_line.component_key and p.included_positive_source_ex_vat>0;
  if (v_total.count,v_total.source_total,v_total.target_ex,v_total.target_vat,v_total.target_inc)
    is distinct from (v_expected,v_hold.source_reserved_ex_vat,v_hold.target_amount_ex_vat,v_hold.target_amount_vat,v_hold.target_amount_inc_vat) then
    raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_HOLD_SHARE_TOTAL_MISMATCH';
  end if;
end
$function$;
alter function private.bpay_next_capture_position_page_v1(uuid,uuid,bigint,uuid,text,integer) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_capture_position_page_v1(uuid,uuid,bigint,uuid,text,integer) from public,anon,authenticated,service_role;
alter function private.bpay_next_hold_fresh_position_page_v1(uuid,uuid,bigint,uuid,text,integer) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_hold_fresh_position_page_v1(uuid,uuid,bigint,uuid,text,integer) from public,anon,authenticated,service_role;
alter function private.bpay_next_record_work_segment_origin_shares_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_record_work_segment_origin_shares_v1(uuid,uuid) from public,anon,authenticated,service_role;


-- CONTACT_PREPARER_UNIT 85 repeatable supabase/repeatable/13102026_0016_banking_pay_next_accepted_eligible_leaf_v1.sql SHA256 3f3be9f3154500646cbccb365224a80ab0a186d58ca2a562ba3b7bcb9f9dbd1e
-- WB29: original eligible leaf cut; complete A/R/H parents retained.


create or replace function private.bpay_next_choice_leaf_eligible_v1(
 p_run_id uuid,p_work_id uuid,p_revision_id uuid,p_line_id uuid,p_segment_id uuid
) returns boolean language plpgsql stable security invoker set search_path=pg_catalog,private
as $function$
declare
 r private.bpay_next_pay_run%rowtype;h private.bpay_next_selection_mode_memory%rowtype;
 c private.bpay_next_work_choice%rowtype;a private.bpay_next_approved_line%rowtype;
 s private.bpay_next_approved_segment%rowtype;v_candidate uuid;
begin
 select x.* into r from private.bpay_next_pay_run x where x.id=p_run_id;
 select x.* into h from private.bpay_next_selection_mode_memory x where x.run_id=p_run_id and x.row_kind='HEADER';
 if h.run_id is null then
  if r.id is null or r.accepted_choice_descriptor is not null then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_ELIGIBLE_CAPTURE_MISSING';end if;
  -- Original non-descriptor selection owners retain their existing admission.
  return true;
 end if;
 if r.id is null or (h.actor_user_id,h.official_pay_date) is distinct from (r.actor_user_id,r.pay_date)
  or (r.accepted_choice_descriptor is not null and
    (h.accepted_context is distinct from r.accepted_choice_descriptor-'intent'
      or h.raw_intent is distinct from r.accepted_choice_descriptor->'intent')) then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_ELIGIBLE_CAPTURE_MISSING';end if;
 select x.* into c from private.bpay_next_work_choice x where x.run_id=p_run_id and x.work_id=p_work_id;
 select x.* into a from private.bpay_next_approved_line x where x.id=p_line_id and x.revision_id=p_revision_id;
 select x.candidate_id into v_candidate from private.bpay_next_work x where x.id=p_work_id;
 if c.work_id is null or c.expected_revision_id is distinct from p_revision_id
  or c.selection_state is distinct from 'SEALED' or a.id is null or v_candidate is null
  or not exists(select 1 from private.bpay_next_work_revision x where x.id=p_revision_id and x.work_id=p_work_id)
  or (c.selection_mode='SUBSET' and not exists(select 1 from private.bpay_next_selected_component x
    where x.run_id=p_run_id and x.work_id=p_work_id and x.expected_revision_id=p_revision_id
      and x.approved_line_id=p_line_id and x.component_key=a.component_key)) then return false;end if;
 if p_segment_id is not null then
  select x.* into s from private.bpay_next_approved_segment x where x.id=p_segment_id;
  if s.id is null or (s.revision_id,s.approved_line_id,s.component_key)
    is distinct from (p_revision_id,p_line_id,a.component_key) then return false;end if;
 end if;
 return exists(select 1 from private.bpay_next_selection_mode_memory m
  where m.run_id=p_run_id and m.row_kind='LEAF' and m.candidate_id=v_candidate
    and m.work_id=p_work_id and m.approved_line_id=p_line_id
    and m.leaf_key='WORK:'||p_work_id::text||':'||a.component_key||':'||
      case when p_segment_id is null then 'WORK_COMPONENT:'||a.component_key else 'WORK_SEGMENT:'||s.segment_key end
    and m.basis->>'revision_id'=p_revision_id::text and m.basis->>'approved_line_id'=p_line_id::text
    and m.basis->>'component_key'=a.component_key and m.basis->>'direction'='PAYMENT'
    and ((p_segment_id is null and m.basis->>'member_kind'='WORK_COMPONENT'
      and m.basis->'approved_segment_id'='null'::jsonb and m.basis->'segment_key'='null'::jsonb)
     or (p_segment_id is not null and m.basis->>'member_kind'='WORK_SEGMENT'
      and m.basis->>'approved_segment_id'=p_segment_id::text and m.basis->>'segment_key'=s.segment_key)));
end
$function$;

create or replace function private.bpay_next_selection_memory_capture_v1(p_run uuid,p_descriptor jsonb)
returns void language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_ns jsonb:=p_descriptor->'namespace';v_baseline uuid:=(p_descriptor->>'memory_baseline_run_id')::uuid;v_kind text;v_row jsonb;v_id uuid;v_leaf record;v_group text;v_next_group text;v_rows bigint:=0;v_bytes bigint:=0;v_encoded jsonb;
begin
 insert into private.bpay_next_selection_mode_memory(run_id,row_kind,leaf_key,agency_id,owner_epoch,actor_user_id,official_pay_date,scope,mode,intent_revision,baseline_run_id,basis,raw_intent,accepted_context)
 values(p_run,'HEADER','HEADER',(v_ns->>'agency_id')::uuid,(v_ns->>'owner_epoch')::bigint,(v_ns->>'actor_user_id')::uuid,(v_ns->>'official_pay_date')::date,v_ns->'scope',p_descriptor->'intent'->>'mode',(p_descriptor->>'revision')::bigint,v_baseline,'{}',p_descriptor->'intent',p_descriptor-'intent');
 -- Finite per-component proof, streamed without a global Draft cap.
 for v_leaf in select l.* from private.bpay_next_selection_memory_leaves_v1(v_ns->'scope') l
   order by l.candidate_id,l.work_id,l.approved_line_id,l.case_component_id,l.leaf_key loop
  v_next_group:=jsonb_build_array(v_leaf.candidate_id,v_leaf.work_id,v_leaf.approved_line_id,v_leaf.case_component_id)::text;
  if v_group is distinct from v_next_group then v_group:=v_next_group;v_rows:=0;v_bytes:=0;end if;
  v_encoded:=jsonb_build_object('run_id',p_run,'row_kind','LEAF','leaf_key',v_leaf.leaf_key,
   'agency_id',v_ns->'agency_id','owner_epoch',v_ns->'owner_epoch','actor_user_id',v_ns->'actor_user_id',
   'official_pay_date',v_ns->'official_pay_date','scope',v_ns->'scope','mode',p_descriptor->'intent'->'mode',
   'intent_revision',p_descriptor->'revision','baseline_run_id',v_baseline,
   'candidate_id',v_leaf.candidate_id,'work_id',v_leaf.work_id,'approved_line_id',v_leaf.approved_line_id,
   'case_component_id',v_leaf.case_component_id,'basis',v_leaf.basis);
  v_rows:=v_rows+1;v_bytes:=v_bytes+octet_length(v_encoded::text);
  if v_rows>10000 or v_bytes>8388608 then
   raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
  insert into private.bpay_next_selection_mode_memory(run_id,row_kind,leaf_key,agency_id,owner_epoch,actor_user_id,official_pay_date,scope,mode,intent_revision,baseline_run_id,candidate_id,work_id,approved_line_id,case_component_id,basis)
  values(p_run,'LEAF',v_leaf.leaf_key,(v_ns->>'agency_id')::uuid,(v_ns->>'owner_epoch')::bigint,(v_ns->>'actor_user_id')::uuid,(v_ns->>'official_pay_date')::date,v_ns->'scope',p_descriptor->'intent'->>'mode',(p_descriptor->>'revision')::bigint,v_baseline,v_leaf.candidate_id,v_leaf.work_id,v_leaf.approved_line_id,v_leaf.case_component_id,v_leaf.basis);
 end loop;
 -- Carry the original basis reference; never requalify inherited unticks.
 insert into private.bpay_next_selection_exclusion_memory
 select p_run,e.agency_id,e.owner_epoch,e.actor_user_id,e.official_pay_date,e.scope,e.intent_kind,e.native_id,e.candidate_id,e.work_id,e.expected_revision_id,e.approved_line_id,e.case_component_id,e.selected,e.basis_ref_run_id,e.intent_json,transaction_timestamp()
 from private.bpay_next_selection_exclusion_memory e where e.run_id=v_baseline
  and not exists(select 1 from jsonb_array_elements(p_descriptor->'intent'->e.intent_kind) raw
   where coalesce(raw->>'case_component_id',raw->>'approved_line_id',raw->>'work_id',raw->>'candidate_id')=e.native_id::text)
  and not exists(select 1 from jsonb_array_elements(p_descriptor->'intent'->'candidates') raw
   where raw->>'candidate_id'=e.candidate_id::text and raw->'selected'='true'::jsonb)
  and not (e.intent_kind='components' and exists(select 1 from jsonb_array_elements(p_descriptor->'intent'->'works') raw
   where raw->>'work_id'=e.work_id::text and raw->'selected'='true'::jsonb and raw->>'mode'='ALL'));
 foreach v_kind in array array['candidates','works','components','cases'] loop
  for v_row in select value from jsonb_array_elements(p_descriptor->'intent'->v_kind) loop
   v_id:=(coalesce(v_row->>'case_component_id',v_row->>'approved_line_id',v_row->>'work_id',v_row->>'candidate_id'))::uuid;
   insert into private.bpay_next_selection_exclusion_memory(run_id,agency_id,owner_epoch,actor_user_id,official_pay_date,scope,intent_kind,native_id,candidate_id,work_id,expected_revision_id,approved_line_id,case_component_id,selected,basis_ref_run_id,intent_json)
   values(p_run,(v_ns->>'agency_id')::uuid,(v_ns->>'owner_epoch')::bigint,(v_ns->>'actor_user_id')::uuid,(v_ns->>'official_pay_date')::date,v_ns->'scope',v_kind,v_id,(v_row->>'candidate_id')::uuid,(v_row->>'work_id')::uuid,(v_row->>'expected_revision_id')::uuid,(v_row->>'approved_line_id')::uuid,(v_row->>'case_component_id')::uuid,(v_row->>'selected')::boolean,p_run,v_row);
  end loop;
 end loop;
end
$function$;
create or replace function private.bpay_next_create_preparation_v1(
 p_run_id uuid,p_actor_user_id uuid,p_pay_date date,p_descriptor jsonb,p_command_id uuid,p_guard jsonb
) returns jsonb language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
 v_run private.bpay_next_pay_run%rowtype;v_result jsonb;v_ns jsonb;v_intent jsonb;
 v_row jsonb;v_array text;v_keys text[];v_field text;v_id uuid;v_header jsonb;
 v_query_admitted boolean:=true;v_policy text:='NONE';v_channel text:='ALL';
 v_reason text;v_proof uuid;v_guard jsonb;v_scope jsonb;v_policy_args jsonb;
 v_locked_candidates uuid[];v_locked_works uuid[];v_locked_revisions uuid[];v_locked_cases uuid[];
 v_candidate uuid;v_work uuid;v_revision uuid;v_sequence bigint;v_gate jsonb;v_query_exclusions jsonb;v_member record;
 v_memory boolean:=p_descriptor ? 'memory_baseline_run_id';v_baseline uuid;v_page_no bigint;v_lines uuid[];v_subset record;
 v_mode text;v_selected boolean;v_count bigint;v_code text;v_week_start date;v_work_count bigint:=0;
begin
 if p_guard is not null then
  if jsonb_typeof(p_guard) is distinct from 'object' or not(p_guard ?& array['decision','reason','reauth_proof_id'])
   or p_guard-array['decision','reason','reauth_proof_id']<>'{}'::jsonb
   or jsonb_typeof(p_guard->'decision') is distinct from 'string'
   or p_guard->>'decision' not in ('UMBRELLA_ONLY','VERIFY_BOTH','VERIFY_PAYE') then
   raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';end if;
  v_policy:=p_guard->>'decision';v_channel:=case v_policy when 'UMBRELLA_ONLY' then 'UMBRELLA' when 'VERIFY_PAYE' then 'PAYE' else 'ALL' end;
  if v_policy='UMBRELLA_ONLY' then
   if p_guard->'reason'<>'null'::jsonb or p_guard->'reauth_proof_id'<>'null'::jsonb then
    raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';end if;
  else
   if jsonb_typeof(p_guard->'reason') is distinct from 'string' or btrim(p_guard->>'reason')=''
    or octet_length(p_guard->>'reason') not between 1 and 500
    or jsonb_typeof(p_guard->'reauth_proof_id') is distinct from 'string'
    or p_guard->>'reauth_proof_id'!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
    raise exception using errcode='22023',message='BPAY_NEXT_REAUTH_REQUEST_INVALID';end if;
   v_reason:=p_guard->>'reason';v_proof:=(p_guard->>'reauth_proof_id')::uuid;
  end if;
 end if;
 if p_command_id is null or jsonb_typeof(p_descriptor) is distinct from 'object'
   or octet_length(p_descriptor::text)>32768
   or not(p_descriptor ?& array['namespace','intent','revision','workbench_revision','adoption_revision'])
   or p_descriptor-array['namespace','intent','revision','workbench_revision','adoption_revision','memory_baseline_run_id']<>'{}'::jsonb then
  raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';
 end if;
 if v_memory and p_descriptor->'memory_baseline_run_id'<>'null'::jsonb and
  (jsonb_typeof(p_descriptor->'memory_baseline_run_id')<>'string' or p_descriptor->>'memory_baseline_run_id'!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$') then
  raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
 v_ns:=p_descriptor->'namespace';v_intent:=p_descriptor->'intent';
 if jsonb_typeof(v_ns) is distinct from 'object'
   or not(v_ns ?& array['agency_id','owner_epoch','actor_user_id','official_pay_date','scope'])
   or v_ns-array['agency_id','owner_epoch','actor_user_id','official_pay_date','scope']<>'{}'::jsonb
   or jsonb_typeof(v_ns->'scope') is distinct from 'object'
   or not(v_ns->'scope' ?& array['candidate_id','client_id','channel'])
   or (v_ns->'scope')-array['candidate_id','client_id','channel']<>'{}'::jsonb
   or jsonb_typeof(v_intent) is distinct from 'object'
   or not(v_intent ?& array['mode','candidates','works','components','cases'])
   or v_intent-array['mode','candidates','works','components','cases']<>'{}'::jsonb
   or jsonb_typeof(v_intent->'mode') is distinct from 'string'
   or v_intent->>'mode' not in ('ALL_MATCHING','NONE') then
  raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';
 end if;
 foreach v_array in array array['candidates','works','components','cases'] loop
  if jsonb_typeof(v_intent->v_array) is distinct from 'array'
    or jsonb_array_length(v_intent->v_array)>1000 then
   raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
  v_keys:=case v_array when 'candidates' then array['candidate_id','selected']
    when 'works' then array['candidate_id','work_id','expected_revision_id','selected','mode']
    when 'components' then array['candidate_id','work_id','expected_revision_id','approved_line_id','selected']
    else array['candidate_id','case_component_id','selected'] end;
  for v_row in select value from jsonb_array_elements(v_intent->v_array) loop
   if jsonb_typeof(v_row) is distinct from 'object' or not(v_row ?& v_keys)
     or v_row-v_keys<>'{}'::jsonb or jsonb_typeof(v_row->'selected') is distinct from 'boolean' then
    raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
   foreach v_field in array v_keys loop
    if v_field in ('selected','mode') then continue;end if;
    if jsonb_typeof(v_row->v_field) is distinct from 'string'
      or v_row->>v_field!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
     raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
   end loop;
   if v_array='works' and (jsonb_typeof(v_row->'mode') is distinct from 'string'
      or v_row->>'mode' not in ('ALL','SUBSET')) then
    raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(v_intent->v_array) a(value)
    group by case v_array when 'candidates' then a.value->>'candidate_id'
      when 'works' then a.value->>'work_id' when 'components' then a.value->>'approved_line_id'
      else a.value->>'case_component_id' end having count(*)>1) then
   raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
 end loop;
 if jsonb_typeof(v_ns->'agency_id') is distinct from 'string'
   or v_ns->>'agency_id'!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or jsonb_typeof(v_ns->'actor_user_id') is distinct from 'string'
   or v_ns->>'actor_user_id'!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or jsonb_typeof(v_ns->'owner_epoch') is distinct from 'string'
   or v_ns->>'owner_epoch'!~'^[1-9][0-9]{0,18}$'
   or jsonb_typeof(v_ns->'official_pay_date') is distinct from 'string'
   or v_ns->>'official_pay_date'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or jsonb_typeof(v_ns->'scope'->'channel') is distinct from 'string'
   or v_ns->'scope'->>'channel' not in ('ALL','PAYE','UMBRELLA') then
  raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
 foreach v_field in array array['candidate_id','client_id'] loop
  if v_ns->'scope'->v_field<>'null'::jsonb and (jsonb_typeof(v_ns->'scope'->v_field) is distinct from 'string'
    or v_ns->'scope'->>v_field!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$') then
   raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
 end loop;
 if jsonb_typeof(p_descriptor->'workbench_revision') is distinct from 'string'
   or p_descriptor->>'workbench_revision'!~'^(0|[1-9][0-9]{0,18})$'
   or jsonb_typeof(p_descriptor->'adoption_revision') is distinct from 'string'
   or p_descriptor->>'adoption_revision'!~'^(0|[1-9][0-9]{0,18})$' then
  raise exception using errcode='22023',message='BPAY_NEXT_CHOICE_DESCRIPTOR_INVALID';end if;
 -- An exact receipt replay acquires no new source/cut/FK-parent locks.
 select src.* into v_run from private.bpay_next_pay_run src where id=p_run_id;
 if found then
  if v_run.accepted_choice_descriptor is null then
   raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_RUN_NOT_EMPTY';end if;
  v_result:=private.bpay_next_create_preparation_v1(p_run_id,p_actor_user_id,p_pay_date);
  select src.* into strict v_run from private.bpay_next_pay_run src where id=p_run_id;
  if v_run.accepted_choice_descriptor is distinct from p_descriptor
    or v_run.accepted_choice_command_id is distinct from p_command_id then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_DESCRIPTOR_REPLAY_CONFLICT';end if;
  if (v_run.paye_guard_decision,v_run.channel_scope,v_run.paye_override_reason,v_run.reauth_proof_id,
    v_run.paye_override_actor) is distinct from (v_policy,v_channel,v_reason,v_proof,
      case when v_policy='NONE' then null::uuid else p_actor_user_id end) then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_DESCRIPTOR_REPLAY_CONFLICT';end if;
  if v_proof is not null then
   perform private.bpay_next_reauth_consume_v1(v_proof,p_actor_user_id,'PAYE_SAME_WEEK_OVERRIDE',v_run.paye_guard_scope_sha256,p_command_id);
  end if;
  select agency_sequence into v_sequence from private.bpay_next_command where id=p_command_id;
  return v_result||jsonb_build_object('command_id',p_command_id,'agency_sequence',v_sequence::text,
    'choice_work_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='WORK'),
    'choice_case_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='CASE_COMPONENT'),
    'selected_candidate_count',v_run.selected_candidate_count::text,'empty',v_run.selected_candidate_count=0,'replay',true);
 end if;
 -- Source admission precedes the original module/run/snooze cut locks.
 begin perform private.weekly_source_pay_query_admit_v2();
 exception when lock_not_available then v_query_admitted:=false;end;
 perform 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
 -- FK parent locks precede the inherited snooze command-clock SHARE.
 -- No revision-meta lock: Snooze writers already take clock before meta.
 select coalesce(array_agg(parent.id),'{}'::uuid[]) into v_locked_candidates from (select candidate.id from public.candidates candidate where exists(select 1 from private.bpay_next_workbench_item i
   where i.candidate_id=candidate.id and i.section='READY' and i.selectable
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel'))
   or exists(select 1 from unnest(array['candidates','works','components','cases']) kind
     cross join lateral jsonb_array_elements(v_intent->kind) a(value) where a.value->>'candidate_id'=candidate.id::text)
   order by candidate.id for share) parent;
 if exists(select 1 from jsonb_array_elements(v_intent->'candidates') requested
   where not ((requested->>'candidate_id')::uuid=any(v_locked_candidates))) then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_NATIVE_IDENTITY_INVALID';end if;
 perform 1 from public.umbrellas umbrella where exists(select 1 from public.candidates candidate
   join private.bpay_next_workbench_item i on i.candidate_id=candidate.id and i.section='READY' and i.selectable
   where candidate.umbrella_id=umbrella.id
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel'))
   order by umbrella.id for share;
 select coalesce(array_agg(parent.id),'{}'::uuid[]) into v_locked_works from (select w.id from private.bpay_next_work w where exists(select 1 from private.bpay_next_workbench_item i
   where i.work_id=w.id and i.section='READY' and i.selectable
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel'))
   or exists(select 1 from jsonb_array_elements(v_intent->'works') a(value) where a.value->>'work_id'=w.id::text)
   order by w.id for share) parent;
 select coalesce(array_agg(parent.id),'{}'::uuid[]) into v_locked_revisions from (select r.id from private.bpay_next_work_revision r where exists(select 1 from private.bpay_next_workbench_item i
   where i.revision_id=r.id and i.section='READY' and i.selectable
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel'))
   or exists(select 1 from jsonb_array_elements(v_intent->'works') a(value) where a.value->>'expected_revision_id'=r.id::text)
   order by r.work_id,r.id for share) parent;
 select coalesce(array_agg(parent.id),'{}'::uuid[]) into v_locked_cases from (select component.id from private.bpay_next_case_component component where exists(select 1 from private.bpay_next_workbench_item i
   where i.case_component_id=component.id and i.section='READY' and i.selectable
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel'))
   or exists(select 1 from jsonb_array_elements(v_intent->'cases') a(value) where a.value->>'case_component_id'=component.id::text)
   order by component.candidate_id,component.id for share) parent;
 if exists(select 1 from private.bpay_next_command c where c.status in ('RECEIVED','ENROLLING'))
   or exists(select 1 from private.bpay_next_job j join private.bpay_next_command c on c.id=j.command_id
   where j.status<>'DONE' and j.candidate_id=any(v_locked_candidates)) then
  raise exception using errcode='55000',message='BPAY_NEXT_ACCEPT_INPUT_EARLIER_ECONOMIC_COMMAND_PENDING';end if;
 -- Acquire UPDATE once before the inherited SHARE, avoiding concurrent upgrades.
 perform 1 from private.bpay_next_command_clock where id=1 for update;
 if exists(select 1 from private.bpay_next_command c where c.status in ('RECEIVED','ENROLLING'))
   or exists(select 1 from private.bpay_next_job j join private.bpay_next_command c on c.id=j.command_id
   where j.status<>'DONE' and j.candidate_id=any(v_locked_candidates)) then
  raise exception using errcode='55000',message='BPAY_NEXT_ACCEPT_INPUT_EARLIER_ECONOMIC_COMMAND_PENDING';end if;
 if exists(select 1 from private.bpay_next_command where id=p_command_id) then
  raise exception using errcode='23514',message='BPAY_NEXT_PREPARE_COMMAND_REPLAY_CONFLICT';end if;
 -- A same-run concurrent legacy writer must never make clock->run wait.
 perform 1 from private.bpay_next_pay_run where id=p_run_id for update nowait;
 if found and exists(select 1 from private.bpay_next_pay_run where id=p_run_id and accepted_choice_descriptor is null) then
  raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_RUN_NOT_EMPTY';end if;
 -- Original UUID/actor/date/deadline owner is preserved, including replay.
 v_result:=private.bpay_next_create_preparation_v1(p_run_id,p_actor_user_id,p_pay_date);
 select r.* into strict v_run from private.bpay_next_pay_run r where r.id=p_run_id for update;
 if v_run.accepted_choice_descriptor is not null then
  if v_run.accepted_choice_descriptor is distinct from p_descriptor
    or v_run.accepted_choice_command_id is distinct from p_command_id then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_DESCRIPTOR_REPLAY_CONFLICT';end if;
  if (v_run.paye_guard_decision,v_run.channel_scope,v_run.paye_override_reason,v_run.reauth_proof_id,
    v_run.paye_override_actor) is distinct from (v_policy,v_channel,v_reason,v_proof,
      case when v_policy='NONE' then null::uuid else p_actor_user_id end) then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_DESCRIPTOR_REPLAY_CONFLICT';end if;
  if v_proof is not null then
   perform private.bpay_next_reauth_consume_v1(v_proof,p_actor_user_id,'PAYE_SAME_WEEK_OVERRIDE',v_run.paye_guard_scope_sha256,p_command_id);
  end if;
  select agency_sequence into v_sequence from private.bpay_next_command where id=p_command_id;
  return v_result||jsonb_build_object('command_id',p_command_id,'agency_sequence',v_sequence::text,
    'choice_work_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='WORK'),
    'choice_case_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='CASE_COMPONENT'),
    'selected_candidate_count',v_run.selected_candidate_count::text,'empty',v_run.selected_candidate_count=0,'replay',true);
 end if;
 if v_run.status<>'PREPARING' or v_run.selection_state<>'OPEN' or v_run.selection_page_count<>0
   or v_run.selection_count<>0 or v_run.selected_candidate_count<>0
   or exists(select 1 from private.bpay_next_run_selection where run_id=p_run_id)
   or exists(select 1 from private.bpay_next_selection_candidate where run_id=p_run_id)
   or exists(select 1 from private.bpay_next_case_selection where run_id=p_run_id)
   or exists(select 1 from private.bpay_next_run_command where run_id=p_run_id)
   or v_run.preparation_expires_at_utc<=clock_timestamp() then
  raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_RUN_NOT_EMPTY';end if;
 -- Compare real authenticated identity/context; caller fields are never authority.
 v_header:=public.bpay_next_workbench_page_v1(jsonb_build_object('actor_user_id',p_actor_user_id,
   'kind','HEADER','candidate_id',v_ns->'scope'->'candidate_id','client_id',v_ns->'scope'->'client_id',
   'channel',v_ns->'scope'->>'channel','section','READY','search','','sort','NAME_ASC',
   'group_key',null,'item_id',null,'reason_code',null,'count_selection',null,'after',null,'limit',100));
 if v_ns->>'agency_id' is distinct from v_header->'context'->>'agency_id'
   or v_ns->>'actor_user_id' is distinct from p_actor_user_id::text
   or v_ns->>'owner_epoch' is distinct from v_header->'context'->>'owner_epoch'
   or v_ns->>'official_pay_date' is distinct from v_run.pay_date::text
   or p_descriptor->>'workbench_revision' is distinct from v_header->'context'->>'workbench_revision'
   or p_descriptor->>'adoption_revision' is distinct from v_header->'context'->>'adoption_revision'
   or jsonb_typeof(p_descriptor->'revision') is distinct from 'number'
   or p_descriptor->>'revision'!~'^(0|[1-9][0-9]{0,15})$' then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_CONTEXT_CHANGED';end if;
 -- Validate every deliberate subordinate identity before any accepted cut.
 for v_array,v_row in select k,value from unnest(array['works','components']) k
   cross join lateral jsonb_array_elements(v_intent->k) a(value) loop
  v_work:=(v_row->>'work_id')::uuid;v_candidate:=(v_row->>'candidate_id')::uuid;
  v_revision:=(v_row->>'expected_revision_id')::uuid;
  if not exists(select 1 from private.bpay_next_work w join private.bpay_next_work_revision r
    on r.work_id=w.id and r.id=v_revision where w.id=v_work and w.candidate_id=v_candidate)
    or (v_array='components' and not exists(select 1 from private.bpay_next_approved_line l
      where l.id=(v_row->>'approved_line_id')::uuid and l.revision_id=v_revision)) then
   raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_NATIVE_IDENTITY_INVALID';end if;
 end loop;
 -- WB25: component-only memory overlays retain untouched native defaults.
 -- A supplied parent must match; an absent parent must be current, scoped and
 -- eligible under the original held Work/revision locks. Legacy stays SUBSET.
 if exists(select 1 from jsonb_array_elements(v_intent->'components') c(value)
   where case when exists(select 1 from jsonb_array_elements(v_intent->'works') w(value)
      where w.value->>'work_id'=c.value->>'work_id') then
     not exists(select 1 from jsonb_array_elements(v_intent->'works') w(value)
      where w.value->>'work_id'=c.value->>'work_id' and w.value->>'candidate_id'=c.value->>'candidate_id'
       and w.value->>'expected_revision_id'=c.value->>'expected_revision_id'
       and (v_memory or w.value->>'mode'='SUBSET' and w.value->'selected'='true'::jsonb))
    else not v_memory or not exists(select 1 from private.bpay_next_work w join private.bpay_next_work_revision r on r.work_id=w.id
       join private.bpay_next_workbench_item i on i.work_id=w.id and i.revision_id=r.id
       join private.bpay_next_workbench_group g on g.group_key=i.group_key and g.candidate_id=i.candidate_id
       where w.id=(c.value->>'work_id')::uuid and w.candidate_id=(c.value->>'candidate_id')::uuid
        and r.id=(c.value->>'expected_revision_id')::uuid and w.current_revision_id=r.id and w.applied_revision_id=r.id
        and i.approved_line_id=(c.value->>'approved_line_id')::uuid and i.candidate_id=w.candidate_id
        and i.section='READY' and i.selectable and i.amount_known and not i.is_selected
        and i.portion_kind in ('AVAILABLE','ZERO') and g.complete and not g.dirty
        and g.progress_state='CURRENT' and i.progress_state='CURRENT'
        and i.projection_revision=g.projection_revision and i.financial_view_revision=g.financial_view_revision
        and (v_ns->'scope'->>'candidate_id' is null or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
        and (v_ns->'scope'->>'client_id' is null or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
        and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel')) end) then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_NATIVE_IDENTITY_INVALID';end if;
 if exists(select 1 from jsonb_array_elements(v_intent->'cases') a(value) where not exists(
   select 1 from private.bpay_next_case_component c where c.id=(a.value->>'case_component_id')::uuid
     and c.candidate_id=(a.value->>'candidate_id')::uuid)) then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_NATIVE_IDENTITY_INVALID';end if;
 -- DR-10: fresh serialized policy admission, before the original member cut.
 v_guard:=private.bpay_next_paye_guard_page_v1(p_actor_user_id,p_run_id,p_descriptor);
 if v_policy='NONE' and (v_guard->>'guard_applies')::boolean then
  raise exception using errcode='55000',message='BPAY_NEXT_PAYE_SAME_WEEK_GUARD_UNRESOLVED';end if;
 if v_policy<>'NONE' and not(v_guard->>'guard_applies')::boolean then
  raise exception using errcode='23514',message='BPAY_NEXT_PAYE_GUARD_CHANGED';end if;
 if v_policy in ('VERIFY_BOTH','VERIFY_PAYE') then
  if (v_guard->>'unexecuted')::boolean then
   raise exception using errcode='55000',message='BPAY_NEXT_PAYE_SAME_WEEK_GUARD_UNEXECUTED';end if;
  v_policy_args:=jsonb_build_object('run_id',p_run_id,'command_id',p_command_id,'decision',v_policy,'reason',v_reason,
    'context',p_descriptor-array['intent','revision','memory_baseline_run_id']);
  v_scope:=private.bpay_next_reauth_scope_v1(p_actor_user_id,'PAYE_SAME_WEEK_OVERRIDE',v_policy_args,false);
  perform private.bpay_next_reauth_consume_v1(v_proof,p_actor_user_id,'PAYE_SAME_WEEK_OVERRIDE',v_scope->>'scope_sha256',p_command_id);
 end if;
 update private.bpay_next_pay_run set paye_guard_decision=v_policy,channel_scope=v_channel,
  paye_override_actor=case when v_policy='NONE' then null else p_actor_user_id end,
  paye_override_reason=v_reason,reauth_proof_id=v_proof,paye_guard_scope_sha256=v_scope->>'scope_sha256' where id=p_run_id;
 -- The original run boundary retained its snooze cut; no second clock or kind.
 insert into private.bpay_next_run_selection_exclusion(run_id,page_no,candidate_id,actor_user_id)
   select p_run_id,(row_number() over(order by a.value->>'candidate_id')+99)/100,
     (a.value->>'candidate_id')::uuid,p_actor_user_id
   from jsonb_array_elements(v_intent->'candidates') a(value) where a.value->'selected'='false'::jsonb;
 insert into private.bpay_next_run_selection_exclusion(run_id,page_no,work_id,actor_user_id)
   select p_run_id,((select count(*) from private.bpay_next_run_selection_exclusion where run_id=p_run_id)
     +row_number() over(order by a.value->>'work_id')+99)/100,(a.value->>'work_id')::uuid,p_actor_user_id
   from jsonb_array_elements(v_intent->'works') a(value) where a.value->'selected'='false'::jsonb;
 -- No membership may acquire an unheld FK parent after the command clock.
 if exists(select 1 from private.bpay_next_workbench_item i
   where i.section='READY' and i.selectable
     and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
     and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
     and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel')
     and (not(i.candidate_id=any(v_locked_candidates))
       or (i.work_id is not null and (not(i.work_id=any(v_locked_works)) or not(i.revision_id=any(v_locked_revisions))))
       or (i.case_component_id is not null and not(i.case_component_id=any(v_locked_cases))))) then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_CONTEXT_CHANGED';end if;
 -- The eligible leaf cut is universal; optional remembered-choice semantics remain original.
 perform private.bpay_next_selection_memory_capture_v1(p_run_id,p_descriptor);
 if v_memory then
  v_baseline:=private.bpay_next_selection_memory_resolve_v1(v_ns,jsonb_build_object('run_id',p_descriptor->'memory_baseline_run_id','scope',v_ns->'scope'));
  with choices as materialized(select * from private.bpay_next_selection_memory_choices_v1(v_ns->'scope',v_baseline,v_intent)),
  works as (select l.work_id,l.candidate_id,
    coalesce((ov.value->>'expected_revision_id')::uuid,l.revision_id) expected_revision_id,
    case when bool_and(l.selected) then 'ALL' else 'SUBSET' end selection_mode
   from choices l left join lateral(select value from jsonb_array_elements(v_intent->'works') where value->>'work_id'=l.work_id::text) ov on true
   where l.work_id is not null and l.direction='PAYMENT'
    and (v_policy<>'VERIFY_PAYE' or exists(select 1 from public.candidates c where c.id=l.candidate_id and upper(c.pay_method)='PAYE'))
   group by l.work_id,l.candidate_id,coalesce((ov.value->>'expected_revision_id')::uuid,l.revision_id)
   having bool_or(l.selected)),
  work_members as (insert into private.bpay_next_run_choice_member(run_id,member_kind,member_id,candidate_id,work_id,expected_revision_id,selection_mode,selected,member_no)
   select p_run_id,'WORK',w.work_id,w.candidate_id,w.work_id,w.expected_revision_id,w.selection_mode,true,
    row_number() over(order by (w.selection_mode='SUBSET') desc,w.work_id) from works w returning candidate_id),
  case_members as (insert into private.bpay_next_run_choice_member(run_id,member_kind,member_id,candidate_id,case_component_id,selected,member_no)
   select p_run_id,'CASE_COMPONENT',l.case_component_id,l.candidate_id,l.case_component_id,l.selected,
    row_number() over(order by l.candidate_id,l.case_component_id) from choices l
   where l.case_component_id is not null
    and (v_channel='ALL' or exists(select 1 from public.candidates c where c.id=l.candidate_id and upper(c.pay_method)=v_channel)) and
    (exists(select 1 from work_members w where w.candidate_id=l.candidate_id)
     or exists(select 1 from choices payment where payment.candidate_id=l.candidate_id and payment.case_component_id is not null and payment.direction='PAYMENT' and payment.selected))
   returning candidate_id)
  select (select count(*) from work_members)+(select count(*) from case_members) into v_count;
 else
 -- Retain Work and Case membership in one statement snapshot.
 with work_members as (insert into private.bpay_next_run_choice_member(run_id,member_kind,member_id,candidate_id,
   work_id,expected_revision_id,selection_mode,selected,member_no)
 select p_run_id,'WORK',i.work_id,i.candidate_id,i.work_id,
   coalesce((ov.value->>'expected_revision_id')::uuid,i.revision_id),coalesce(ov.value->>'mode','ALL'),true,
   row_number() over(order by (coalesce(ov.value->>'mode','ALL')='SUBSET') desc,i.work_id)
 from private.bpay_next_workbench_item i join private.bpay_next_workbench_group g
   on g.group_key=i.group_key and g.candidate_id=i.candidate_id
 left join lateral(select a.value from jsonb_array_elements(v_intent->'works') a(value)
   where a.value->>'work_id'=i.work_id::text) ov on true
 where i.section='READY' and i.selectable and i.work_id is not null and i.amount_known
   and i.direction='PAYMENT' and i.portion_kind in ('AVAILABLE','ZERO')
   and (v_policy<>'VERIFY_PAYE' or exists(select 1 from public.candidates c where c.id=i.candidate_id and upper(c.pay_method)='PAYE'))
   and g.complete and not g.dirty and g.progress_state='CURRENT' and i.progress_state='CURRENT'
   and i.projection_revision=g.projection_revision and i.financial_view_revision=g.financial_view_revision
   and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
   and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
   and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel')
   and not exists(select 1 from private.bpay_next_run_selection_exclusion e where e.run_id=p_run_id
     and (e.candidate_id=i.candidate_id or e.work_id=i.work_id))
   and (v_intent->>'mode'='ALL_MATCHING' or ov.value->'selected'='true'::jsonb or exists(
     select 1 from jsonb_array_elements(v_intent->'candidates') a(value)
       where a.value->>'candidate_id'=i.candidate_id::text and a.value->'selected'='true'::jsonb))
 group by i.work_id,i.candidate_id,coalesce((ov.value->>'expected_revision_id')::uuid,i.revision_id),coalesce(ov.value->>'mode','ALL') returning candidate_id),
 case_members as (insert into private.bpay_next_run_choice_member(run_id,member_kind,member_id,candidate_id,case_component_id,selected,member_no)
 select p_run_id,'CASE_COMPONENT',i.case_component_id,i.candidate_id,i.case_component_id,
   coalesce((ov.value->>'selected')::boolean,true),row_number() over(order by i.candidate_id,i.case_component_id)
 from private.bpay_next_workbench_item i join private.bpay_next_workbench_group g
   on g.group_key=i.group_key and g.candidate_id=i.candidate_id
 left join lateral(select a.value from jsonb_array_elements(v_intent->'cases') a(value)
   where a.value->>'case_component_id'=i.case_component_id::text) ov on true
 where i.section='READY' and i.selectable and i.case_component_id is not null
   and (v_channel='ALL' or exists(select 1 from public.candidates c where c.id=i.candidate_id and upper(c.pay_method)=v_channel))
   and g.complete and not g.dirty and g.progress_state='CURRENT' and i.progress_state='CURRENT'
   and i.projection_revision=g.projection_revision and i.financial_view_revision=g.financial_view_revision
   and (v_ns->'scope'->'candidate_id'='null'::jsonb or i.candidate_id=(v_ns->'scope'->>'candidate_id')::uuid)
   and (v_ns->'scope'->'client_id'='null'::jsonb or i.client_id=(v_ns->'scope'->>'client_id')::uuid)
   and (v_ns->'scope'->>'channel'='ALL' or i.target_pay_channel=v_ns->'scope'->>'channel')
   and not exists(select 1 from private.bpay_next_run_selection_exclusion e where e.run_id=p_run_id
     and e.candidate_id=i.candidate_id)
   and (exists(select 1 from work_members m where m.candidate_id=i.candidate_id)
     or exists(select 1 from private.bpay_next_workbench_item payment
       join private.bpay_next_workbench_group payment_group
         on payment_group.group_key=payment.group_key and payment_group.candidate_id=payment.candidate_id
       left join lateral(select a.value from jsonb_array_elements(v_intent->'cases') a(value)
         where a.value->>'case_component_id'=payment.case_component_id::text) chosen on true
       where payment.candidate_id=i.candidate_id and payment.case_component_id is not null
         and payment.section='READY' and payment.selectable and payment.direction='PAYMENT'
         and payment.amount_known and payment.portion_kind in ('AVAILABLE','ZERO')
         and payment_group.complete and not payment_group.dirty
         and payment_group.progress_state='CURRENT' and payment.progress_state='CURRENT'
         and payment.projection_revision=payment_group.projection_revision
         and payment.financial_view_revision=payment_group.financial_view_revision
         and coalesce((chosen.value->>'selected')::boolean,true)
         and (v_ns->'scope'->'client_id'='null'::jsonb or payment.client_id=(v_ns->'scope'->>'client_id')::uuid)
         and (v_ns->'scope'->>'channel'='ALL' or payment.target_pay_channel=v_ns->'scope'->>'channel')
         and (v_intent->>'mode'='ALL_MATCHING' or chosen.value->'selected'='true'::jsonb
           or exists(select 1 from jsonb_array_elements(v_intent->'candidates') a(value)
             where a.value->>'candidate_id'=i.candidate_id::text and a.value->'selected'='true'::jsonb))))
 group by i.case_component_id,i.candidate_id,coalesce((ov.value->>'selected')::boolean,true) returning candidate_id)
 select (select count(*) from work_members)+(select count(*) from case_members) into v_count;
 end if;
 v_week_start:=date_trunc('week',v_run.snooze_business_date::timestamp)::date;
 for v_member in select m.*,w.approval_state,w.current_revision_id,w.applied_revision_id,w.week_ending_date,
   r.physical_timesheet_id,r.source_kind,r.approved_at_utc,r.sealed_at_utc,upper(c.pay_method) as pay_channel
   from private.bpay_next_run_choice_member m join private.bpay_next_work w on w.id=m.work_id
   join private.bpay_next_work_revision r on r.work_id=w.id and r.id=m.expected_revision_id
   join public.candidates c on c.id=m.candidate_id
   where m.run_id=p_run_id and m.member_kind='WORK' order by m.member_no loop
  v_code:=null;
  if v_policy='UMBRELLA_ONLY' and v_member.pay_channel='PAYE' then
   v_code:='PAYE_EXCLUDED_BY_SAME_WEEK_GUARD';
  elsif v_member.approval_state<>'APPROVED' or v_member.approved_at_utc is null or v_member.sealed_at_utc is null then
   v_code:='BPAY_NEXT_SELECTION_WORK_NOT_APPROVED';
  elsif v_member.current_revision_id is distinct from v_member.expected_revision_id
    or v_member.applied_revision_id is distinct from v_member.expected_revision_id then
   v_code:='BPAY_NEXT_SELECTION_REVISION_NOT_CURRENT';
  elsif v_member.week_ending_date-6>v_week_start then v_code:='BPAY_NEXT_WORK_WEEK_NOT_YET_PAYABLE';
  elsif not exists(select 1 from private.bpay_next_work w
    join public.timesheets t on t.booking_id=w.booking_id and t.is_current
    join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
    where w.id=v_member.work_id) then v_code:='BPAY_NEXT_SELECTION_REVISION_NOT_CURRENT';
  elsif exists(select 1 from private.bpay_next_work w
    join public.timesheets t on t.booking_id=w.booking_id and t.is_current=true
    join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current=true
    where w.id=v_member.work_id and tf.pay_on_hold is true) then
   v_code:='BPAY_NEXT_SELECTION_ON_HOLD';
  elsif not exists(select 1 from private.bpay_next_revision_worker_basis where revision_id=v_member.expected_revision_id) then
   raise exception using errcode='55000',message='BPAY_NEXT_SELECTION_BASIS_UNAVAILABLE';
  elsif exists(select 1 from private.bpay_next_snooze sn
    join lateral(select ev.after_state from private.bpay_next_snooze_event ev
      where ev.snooze_id=sn.id and ev.control_sequence<=v_run.snooze_control_sequence
      order by ev.control_sequence desc limit 1) e on true
    join private.bpay_next_revision_worker_basis b on b.revision_id=v_member.expected_revision_id
    where sn.work_id=v_member.work_id and sn.scope_kind='WHOLE_TIMESHEET'
      and (e.after_state->>'active')::boolean
      and ((e.after_state->>'until_date') is null or (e.after_state->>'until_date')::date>=v_run.snooze_business_date)
      and (e.after_state->>'worker_pay_basis')::bytea=b.whole_basis) then
   v_code:='BPAY_NEXT_SELECTION_SNOOZED';
  end if;
  v_gate:=null;v_query_exclusions:=null;
  if v_code is null and v_member.source_kind in ('SOURCE','PROTECTED') then
   if not v_query_admitted then v_code:='SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE';
   else begin v_gate:=private.weekly_source_pay_query_gate_v1(v_member.physical_timesheet_id);
    if v_gate->'ok' is distinct from 'true'::jsonb or v_gate->>'code' is distinct from 'OK'
      or jsonb_typeof(v_gate->'blocked') is distinct from 'boolean' then
     v_code:='SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE';
    else
     v_query_exclusions:=private.bpay_next_source_query_segment_exclusions_v1(v_member.expected_revision_id,v_gate);
     if v_gate->'blocked'='true'::jsonb and v_query_exclusions is null then v_code:='SOURCE_PAY_QUERY_OPEN';end if;
    end if;
   exception when others then v_code:='SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE';end;end if;
  end if;
  if v_code is null and v_member.selection_mode='SUBSET' and v_memory then
   if not exists(select 1 from private.bpay_next_selection_memory_choices_v1(v_ns->'scope',v_baseline,v_intent) l
     where l.work_id=v_member.work_id and l.revision_id=v_member.expected_revision_id and l.selected and l.direction='PAYMENT') then
    v_code:='BPAY_NEXT_SELECTION_SIGNED_LINE_NOT_ELIGIBLE';end if;
  elsif not v_memory then
  if v_code is null and v_member.selection_mode='SUBSET' and (not exists(
    select 1 from private.bpay_next_workbench_item i
    join jsonb_array_elements(v_intent->'components') a(value)
      on a.value->>'approved_line_id'=i.approved_line_id::text and a.value->'selected'='true'::jsonb
    where i.work_id=v_member.work_id and i.revision_id=v_member.expected_revision_id
      and i.section='READY' and i.selectable and i.amount_known and i.direction='PAYMENT'
      and i.portion_kind in ('AVAILABLE','ZERO'))
    or exists(select 1 from jsonb_array_elements(v_intent->'components') chosen
      where chosen->>'work_id'=v_member.work_id::text and chosen->'selected'='true'::jsonb
        and not exists(select 1 from private.bpay_next_workbench_item i
          where i.work_id=v_member.work_id and i.revision_id=v_member.expected_revision_id
            and i.approved_line_id=(chosen->>'approved_line_id')::uuid and i.section='READY'
            and i.selectable and i.amount_known and i.direction='PAYMENT'
            and i.portion_kind in ('AVAILABLE','ZERO')))) then
   v_code:='BPAY_NEXT_SELECTION_SIGNED_LINE_NOT_ELIGIBLE';end if;
  end if;
  if v_code is not null then
   update private.bpay_next_run_choice_member set skip_code=v_code
     where run_id=p_run_id and member_kind='WORK' and member_id=v_member.member_id;
  else
   -- Use the existing Rule B objects as the only captured financial authority.
   v_work_count:=v_work_count+1;
   insert into private.bpay_next_run_selection(run_id,selection_no,work_id,candidate_id)
     values(p_run_id,v_work_count,v_member.work_id,v_member.candidate_id);
   insert into private.bpay_next_work_choice(run_id,work_id,expected_revision_id,selection_mode,selection_state,accepted_resolution_refs)
     values(p_run_id,v_member.work_id,v_member.expected_revision_id,v_member.selection_mode,
       case when v_member.selection_mode='ALL' then 'SEALED' else 'OPEN' end,
       private.bpay_next_accepted_resolution_refs_v1(p_run_id,v_member.work_id,v_member.expected_revision_id));
   if v_gate is not null then
    insert into private.bpay_next_run_work_query_snapshot(run_id,work_id,expected_revision_id,physical_timesheet_id,gate_result,captured_at_utc,segment_query_exclusions)
      values(p_run_id,v_member.work_id,v_member.expected_revision_id,v_member.physical_timesheet_id,v_gate,transaction_timestamp(),v_query_exclusions);
   end if;
  end if;
 end loop;
 -- Seal both original descriptor paths at the accepted cut with native pages.
 update private.bpay_next_pay_run set work_choice_count=v_work_count,
  sealed_work_choice_count=(select count(*) from private.bpay_next_work_choice where run_id=p_run_id and selection_state='SEALED') where id=p_run_id;
 for v_subset in select c.* from private.bpay_next_work_choice c where c.run_id=p_run_id and c.selection_mode='SUBSET' order by c.work_id loop
  v_page_no:=0;
  for v_lines in select array_agg(q.approved_line_id order by q.approved_line_id) from
   (select chosen.approved_line_id,(row_number() over(order by chosen.approved_line_id)-1)/100 page_no from (
     select l.approved_line_id from private.bpay_next_selection_memory_choices_v1(v_ns->'scope',v_baseline,v_intent) l
      where v_memory and l.work_id=v_subset.work_id and l.revision_id=v_subset.expected_revision_id and l.selected and l.direction='PAYMENT'
     union all select (l.value->>'approved_line_id')::uuid from jsonb_array_elements(v_intent->'components') l
      where not v_memory and l.value->>'work_id'=v_subset.work_id::text
       and l.value->>'expected_revision_id'=v_subset.expected_revision_id::text and l.value->'selected'='true'::jsonb
   ) chosen) q group by q.page_no order by q.page_no loop
   v_page_no:=v_page_no+1;
   perform private.bpay_next_append_component_selection_page_v1(p_run_id,v_subset.work_id,v_subset.expected_revision_id,v_page_no,v_lines);
  end loop;
  select c.* into strict v_subset from private.bpay_next_work_choice c where c.run_id=p_run_id and c.work_id=v_subset.work_id;
  perform private.bpay_next_seal_component_selection_v1(p_run_id,v_subset.work_id,v_subset.expected_revision_id,v_subset.page_count,v_subset.component_count);
 end loop;
 -- Capture the existing Rule B Candidate settings exactly once in this cut.
 insert into private.bpay_next_selection_candidate(run_id,candidate_id,member_no,
   target_pay_channel,target_umbrella_id,target_umbrella_vat_chargeable,min_take_home_wtd)
 select p_run_id,c.id,row_number() over(order by c.id),upper(c.pay_method),c.umbrella_id,u.vat_chargeable,c.min_take_home_wtd
 from public.candidates c left join public.umbrellas u on u.id=c.umbrella_id
 where exists(select 1 from private.bpay_next_run_choice_member m where m.run_id=p_run_id
   and m.candidate_id=c.id and m.selected and m.skip_code is null
   and (m.member_kind='WORK' or exists(select 1 from private.bpay_next_workbench_item i
     where i.case_component_id=m.case_component_id and i.direction='PAYMENT' and i.section='READY')));
 get diagnostics v_count=row_count;
 -- Optimistic context check, with no meta row lock or downstream recalculation.
 if not exists(select 1 from private.bpay_next_workbench_revision r where r.id=1
   and r.workbench_revision::text=p_descriptor->>'workbench_revision'
   and r.adoption_revision::text=p_descriptor->>'adoption_revision' and r.adoption_state='CURRENT') then
  raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_CONTEXT_CHANGED';end if;
 if v_count>0 then
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'PREPARE');
  insert into private.bpay_next_run_command(run_id,command_id) values(p_run_id,p_command_id);
 end if;
 update private.bpay_next_pay_run set accepted_choice_descriptor=p_descriptor,
   accepted_choice_command_id=p_command_id,selected_candidate_count=v_count,
   selection_count=v_work_count,work_choice_count=v_work_count,
   sealed_work_choice_count=(select count(*) from private.bpay_next_work_choice where run_id=p_run_id and selection_state='SEALED') where id=p_run_id;
 if v_memory then
  update private.bpay_next_selection_mode_memory set command_id=case when v_sequence is not null then p_command_id end,
   agency_sequence=v_sequence where run_id=p_run_id and row_kind='HEADER' and v_sequence is not null;
 end if;
 -- ACK can only acknowledge these already frozen segments; no later READY reread.
 for v_subset in select c.work_id from private.bpay_next_work_choice c where c.run_id=p_run_id and c.selection_state='SEALED' order by c.work_id loop
  perform private.bpay_next_materialise_choice_segments_v1(p_run_id,v_subset.work_id);
 end loop;
 return v_result||jsonb_build_object('command_id',p_command_id,'agency_sequence',v_sequence::text,
   'selection_count',v_work_count::text,
   'selected_candidate_count',v_count::text,'empty',v_count=0,
   'choice_work_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='WORK'),
   'choice_case_count',(select count(*)::text from private.bpay_next_run_choice_member where run_id=p_run_id and member_kind='CASE_COMPONENT'),'replay',false);
end
$function$;
create or replace function private.bpay_next_materialise_choice_segments_v1(p_run_id uuid,p_work_id uuid)
returns void language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_choice private.bpay_next_work_choice%rowtype;v_run private.bpay_next_pay_run%rowtype;v_keys text[];
 v_after text;v_pages bigint:=0;v_count bigint:=0;
begin
 select r.* into strict v_run from private.bpay_next_pay_run r where r.id=p_run_id;
 select src.* into strict v_choice from private.bpay_next_work_choice src
   where run_id=p_run_id and work_id=p_work_id;
 if v_choice.segment_sealed_count is not null then return;end if;
 if v_choice.selection_state<>'SEALED' or v_choice.segment_page_count<>0 or v_choice.segment_count<>0 then
  raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_SELECTION_NOT_OPEN';end if;
 loop
  select array_agg(page.segment_key order by page.segment_key collate "C") into v_keys from (
    select s.segment_key from private.bpay_next_approved_segment s
    where s.revision_id=v_choice.expected_revision_id
      and (private.bpay_next_choice_leaf_eligible_v1(p_run_id,p_work_id,v_choice.expected_revision_id,s.approved_line_id,s.id)
       or private.bpay_next_snooze_at_cut_v1(p_work_id,v_choice.expected_revision_id,s.segment_key,s.component_key,
         v_choice.segment_control_sequence,v_run.snooze_business_date) is not null
       or exists(select 1 from private.bpay_next_run_work_query_snapshot snapshot
         cross join lateral jsonb_array_elements(snapshot.segment_query_exclusions) exclusion(value)
         where snapshot.run_id=p_run_id and snapshot.work_id=p_work_id and snapshot.expected_revision_id=v_choice.expected_revision_id
           and exclusion.value->>'segment_key'=s.segment_key))
      and (v_after is null or s.segment_key collate "C">v_after collate "C")
      and (v_choice.selection_mode='ALL' or exists(select 1 from private.bpay_next_selected_component c
        where c.run_id=p_run_id and c.work_id=p_work_id and c.component_key=s.component_key))
    order by s.segment_key collate "C" limit 100) page;
  exit when v_keys is null;
  v_pages:=v_pages+1;v_count:=v_count+cardinality(v_keys);
  perform private.bpay_next_append_segment_selection_page_v1(p_run_id,p_work_id,v_choice.expected_revision_id,
    v_pages,gen_random_uuid(),v_keys);
  v_after:=v_keys[cardinality(v_keys)];
 end loop;
 perform private.bpay_next_seal_segment_selection_v1(p_run_id,p_work_id,v_choice.expected_revision_id,v_pages,v_count);
end
$function$;
create or replace function private.bpay_next_seal_segment_selection_v1(
  p_run_id uuid,p_work_id uuid,p_expected_revision_id uuid,p_expected_pages bigint,p_expected_count bigint)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_run private.bpay_next_pay_run%rowtype; v_choice private.bpay_next_work_choice%rowtype; v_count bigint;
begin
  if p_expected_pages is null or p_expected_count is null or p_expected_pages<0 or p_expected_count<0 then
    raise exception using errcode='22023',message='BPAY_NEXT_SEGMENT_SELECTION_INPUT_INVALID';
  end if;
  select r.* into strict v_run from private.bpay_next_pay_run r where r.id=p_run_id for update;
  select c.* into strict v_choice from private.bpay_next_work_choice c where c.run_id=p_run_id and c.work_id=p_work_id;
  if (v_choice.expected_revision_id,v_choice.segment_page_count,v_choice.segment_count)
    is distinct from (p_expected_revision_id,p_expected_pages,p_expected_count) then
    raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_SELECTION_SEAL_COUNT_MISMATCH';
  end if;
  if v_choice.segment_sealed_count is not null then
    return jsonb_build_object('run_id',p_run_id,'work_id',p_work_id,'expected_revision_id',p_expected_revision_id,
      'sealed',true,'segment_count',v_choice.segment_count::text,'replay',true);
  end if;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'OPEN' or v_choice.selection_state<>'SEALED' then
    raise exception using errcode='55000',message='BPAY_NEXT_SEGMENT_SELECTION_NOT_OPEN';
  end if;
  select count(*) into v_count from private.bpay_next_approved_segment s where s.revision_id=p_expected_revision_id
    and (private.bpay_next_choice_leaf_eligible_v1(p_run_id,p_work_id,p_expected_revision_id,s.approved_line_id,s.id)
       or private.bpay_next_snooze_at_cut_v1(p_work_id,p_expected_revision_id,s.segment_key,s.component_key,
         v_choice.segment_control_sequence,v_run.snooze_business_date) is not null
       or exists(select 1 from private.bpay_next_run_work_query_snapshot snapshot
         cross join lateral jsonb_array_elements(snapshot.segment_query_exclusions) exclusion(value)
         where snapshot.run_id=p_run_id and snapshot.work_id=p_work_id and snapshot.expected_revision_id=p_expected_revision_id
           and exclusion.value->>'segment_key'=s.segment_key))
    and (v_choice.selection_mode='ALL' or exists(select 1 from private.bpay_next_selected_component c
      where c.run_id=p_run_id and c.work_id=p_work_id and c.component_key=s.component_key));
  if v_count<>p_expected_count or exists(select 1 from private.bpay_next_approved_segment s
    where s.revision_id=p_expected_revision_id
    and (private.bpay_next_choice_leaf_eligible_v1(p_run_id,p_work_id,p_expected_revision_id,s.approved_line_id,s.id)
       or private.bpay_next_snooze_at_cut_v1(p_work_id,p_expected_revision_id,s.segment_key,s.component_key,
         v_choice.segment_control_sequence,v_run.snooze_business_date) is not null
       or exists(select 1 from private.bpay_next_run_work_query_snapshot snapshot
         cross join lateral jsonb_array_elements(snapshot.segment_query_exclusions) exclusion(value)
         where snapshot.run_id=p_run_id and snapshot.work_id=p_work_id and snapshot.expected_revision_id=p_expected_revision_id
           and exclusion.value->>'segment_key'=s.segment_key)) and (v_choice.selection_mode='ALL' or exists(select 1 from private.bpay_next_selected_component c
      where c.run_id=p_run_id and c.work_id=p_work_id and c.component_key=s.component_key))
      and not exists(select 1 from private.bpay_next_selected_segment m where m.run_id=p_run_id and m.work_id=p_work_id and m.segment_key=s.segment_key)) then
    raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_SELECTION_INVENTORY_INCOMPLETE';
  end if;
  update private.bpay_next_work_choice set segment_sealed_count=segment_count where run_id=p_run_id and work_id=p_work_id;
  return jsonb_build_object('run_id',p_run_id,'work_id',p_work_id,'expected_revision_id',p_expected_revision_id,
    'sealed',true,'segment_count',v_choice.segment_count::text,'replay',false);
end
$function$;
create or replace function private.bpay_next_segment_fact_guard_v1()
returns trigger language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare
  v_choice private.bpay_next_work_choice%rowtype;v_run private.bpay_next_pay_run%rowtype;
  v_segment private.bpay_next_approved_segment%rowtype;v_captured private.bpay_next_run_work_segment%rowtype;
  v_parent private.bpay_next_run_position%rowtype;v_origin private.bpay_next_work_segment_origin_share%rowtype;
  v_effect private.bpay_next_financial_effect%rowtype;v_effect_share private.bpay_next_work_segment_effect_share%rowtype;
  v_hold private.bpay_next_hold%rowtype;v_line private.bpay_next_run_line%rowtype;
  v_case_event private.bpay_next_case_event%rowtype;v_case_hold private.bpay_next_case_hold%rowtype;
  v_snapshot jsonb;v_query_reason text;v_balance record;v_count bigint;v_disposition text;v_amount numeric;v_recovery numeric;v_overhang numeric;
begin
  if tg_op<>'INSERT' then raise exception using errcode='55000',message='BPAY_NEXT_SEGMENT_FACT_IMMUTABLE';end if;
  if tg_table_name in ('bpay_next_segment_selection_page','bpay_next_selected_segment') then
    select c.* into strict v_choice from private.bpay_next_work_choice c where c.run_id=new.run_id and c.work_id=new.work_id;
    select r.* into strict v_run from private.bpay_next_pay_run r where r.id=new.run_id;
    if v_run.status<>'PREPARING' or v_run.selection_state<>'OPEN' or v_choice.selection_state<>'SEALED'
      or v_choice.segment_sealed_count is not null then
      raise exception using errcode='55000',message='BPAY_NEXT_SEGMENT_SELECTION_CLOSED';
    end if;
    if tg_table_name='bpay_next_segment_selection_page' then
      if new.page_no<>v_choice.segment_page_count+1 or new.first_member_no<>v_choice.segment_count+1
        or jsonb_typeof(new.request_body) is distinct from 'array'
        or jsonb_array_length(new.request_body)<>new.item_count
        or exists(select 1 from jsonb_array_elements(new.request_body) item where jsonb_typeof(item)<>'string') then
        raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_PAGE_SCOPE_INVALID';
      end if;
    else
      select s.* into strict v_segment from private.bpay_next_approved_segment s where s.id=new.approved_segment_id;
      v_snapshot:=private.bpay_next_snooze_at_cut_v1(new.work_id,new.expected_revision_id,new.segment_key,
        new.component_key,v_choice.segment_control_sequence,v_run.snooze_business_date);
      v_query_reason:=null;
      select reason.value->>'reason' into v_query_reason
        from private.bpay_next_run_work_query_snapshot snapshot
        cross join lateral jsonb_array_elements(snapshot.segment_query_exclusions) reason(value)
        where snapshot.run_id=new.run_id and snapshot.work_id=new.work_id
          and snapshot.expected_revision_id=new.expected_revision_id and reason.value->>'segment_key'=new.segment_key
        order by reason.value->>'reason' limit 1;
      if new.query_hold_reason is distinct from v_query_reason then
        raise exception using errcode='23514',message='BPAY_NEXT_SELECTED_SEGMENT_QUERY_SCOPE_INVALID';end if;
      if (new.expected_revision_id,new.component_key,new.segment_key,new.control_sequence)
        is distinct from (v_choice.expected_revision_id,v_segment.component_key,v_segment.segment_key,v_choice.segment_control_sequence)
        or v_segment.revision_id<>new.expected_revision_id
        or (new.disposition='INCLUDED' and new.query_hold_reason is null
          and not private.bpay_next_choice_leaf_eligible_v1(new.run_id,new.work_id,new.expected_revision_id,v_segment.approved_line_id,v_segment.id))
        or (new.disposition,new.snooze_id,new.snooze_version) is distinct from
          (case when v_snapshot is null then 'INCLUDED'::text else 'SNOOZED'::text end,(v_snapshot->>'id')::uuid,(v_snapshot->>'version')::bigint)
        or not exists(select 1 from private.bpay_next_segment_selection_page p where p.run_id=new.run_id and p.work_id=new.work_id
          and p.page_no=v_choice.segment_page_count+1 and new.selection_no between p.first_member_no and p.first_member_no+p.item_count-1
          and p.request_body ? new.segment_key)
        or (v_choice.selection_mode='SUBSET' and not exists(select 1 from private.bpay_next_selected_component c
          where c.run_id=new.run_id and c.work_id=new.work_id and c.component_key=new.component_key)) then
        raise exception using errcode='23514',message='BPAY_NEXT_SELECTED_SEGMENT_SCOPE_INVALID';
      end if;
    end if;
    return new;
  end if;
  if tg_table_name='bpay_next_run_work_segment' then
    if not private.bpay_next_segment_prepare_owner_v1(new.run_worker_id,'RESERVE') then
      raise exception using errcode='55000',message='BPAY_NEXT_SEGMENT_CAPTURE_OWNER_STALE';
    end if;
    select s.* into v_segment from private.bpay_next_approved_segment s
      where s.revision_id=new.captured_revision_id and s.segment_key=new.segment_key;
    select case when s.query_hold_reason is not null then 'NOT_SELECTED' else s.disposition end into v_disposition from private.bpay_next_selected_segment s
      join private.bpay_next_run_worker w on w.run_id=s.run_id and w.id=new.run_worker_id
      where s.work_id=new.work_id and s.expected_revision_id=new.captured_revision_id and s.approved_segment_id=v_segment.id;
    v_disposition:=case when v_segment.id is null then 'REMOVED' else coalesce(v_disposition,'NOT_SELECTED') end;
    if new.approved_segment_id is distinct from v_segment.id or new.disposition<>v_disposition
      or (v_segment.id is null and not exists(select 1 from private.bpay_next_work_segment_origin_share o
        where o.work_id=new.work_id and o.segment_key=new.segment_key)) then
      raise exception using errcode='23514',message='BPAY_NEXT_CAPTURED_SEGMENT_SCOPE_INVALID';
    end if;
    return new;
  end if;
  if tg_table_name='bpay_next_run_work_segment_parent' then
    select p.* into strict v_parent from private.bpay_next_run_position p where p.run_work_id=new.run_work_id and p.component_key=new.component_key;
    select s.* into strict v_captured from private.bpay_next_run_work_segment s where s.id=new.run_work_segment_id;
    select s.* into v_segment from private.bpay_next_approved_segment s where s.revision_id=new.captured_revision_id
      and s.segment_key=new.segment_key and s.component_key=new.component_key;
    select b.* into strict v_balance from private.bpay_next_work_segment_gross_balance_v1(new.work_id,new.component_key,new.segment_key) b;
    v_amount:=greatest(coalesce(v_segment.approved_source_ex_vat,0)-v_balance.realised_source_ex_vat-v_balance.active_held_source_ex_vat,0);
    v_recovery:=greatest(v_balance.realised_source_ex_vat-coalesce(v_segment.approved_source_ex_vat,0),0);
    v_overhang:=greatest(v_balance.active_held_source_ex_vat-greatest(coalesce(v_segment.approved_source_ex_vat,0)-v_balance.realised_source_ex_vat,0),0);
    if not private.bpay_next_segment_prepare_owner_v1(v_parent.run_worker_id,'RESERVE') or v_parent.segment_attribution_complete
      or (new.work_id,new.captured_revision_id,new.segment_key) is distinct from (v_captured.work_id,v_captured.captured_revision_id,v_captured.segment_key)
      or (new.approved_segment_id,new.approved_line_id,new.work_date,new.approved_source_ex_vat,new.realised_source_ex_vat,new.held_source_ex_vat)
        is distinct from (v_segment.id,v_segment.approved_line_id,v_segment.work_date,coalesce(v_segment.approved_source_ex_vat,0),
          v_balance.realised_source_ex_vat,v_balance.active_held_source_ex_vat)
      or (new.included_positive_source_ex_vat,new.excluded_positive_source_ex_vat,new.recovery_source_ex_vat,new.held_overhang_source_ex_vat)
        is distinct from (case when v_captured.disposition='INCLUDED' then v_amount else 0::numeric end,
          case when v_captured.disposition='INCLUDED' then 0::numeric else v_amount end,v_recovery,v_overhang)
      or (v_segment.id is null and not exists(select 1 from private.bpay_next_work_segment_origin_share o
        where o.work_id=new.work_id and o.component_key=new.component_key and o.segment_key=new.segment_key)) then
      raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_PARENT_ATTRIBUTION_INVALID';
    end if;
    return new;
  end if;
  if tg_table_name='bpay_next_work_segment_origin_share' then
    select h.* into strict v_hold from private.bpay_next_hold h where h.id=new.hold_id;
    select l.* into strict v_line from private.bpay_next_run_line l where l.id=new.run_line_id;
    select s.* into strict v_captured from private.bpay_next_run_work_segment s where s.id=new.run_work_segment_id;
    select p.* into strict v_parent from private.bpay_next_run_position p where p.run_work_id=v_captured.run_work_id and p.component_key=new.component_key;
    if not private.bpay_next_segment_prepare_owner_v1(v_line.run_worker_id,'ALLOCATE') or v_hold.status<>'ACTIVE'
      or v_hold.run_line_id<>v_line.id or not v_parent.segment_attribution_complete or v_captured.disposition<>'INCLUDED'
      or (new.work_id,new.component_key,new.segment_key) is distinct from (v_line.work_id,v_line.component_key,v_captured.segment_key)
      or v_captured.run_work_id<>v_line.run_work_id or not exists(select 1 from private.bpay_next_run_work_segment_parent p
        where p.run_work_segment_id=new.run_work_segment_id and p.component_key=new.component_key
          and p.included_positive_source_ex_vat=new.source_reserved_ex_vat)
      or (v_hold.source_reserved_ex_vat,v_hold.target_amount_ex_vat,v_hold.target_amount_vat,v_hold.target_amount_inc_vat)
        is distinct from (v_line.source_consumed_ex_vat,v_line.frozen_ex_vat,v_line.frozen_vat,v_line.frozen_inc_vat) then
      raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_ORIGIN_SHARE_SCOPE_INVALID';
    end if;
    return new;
  end if;
  if tg_table_name='bpay_next_work_segment_effect_share' then
    select e.* into strict v_effect from private.bpay_next_financial_effect e where e.id=new.effect_id;
    if v_effect.effect_kind='WORK_COLLECTION_RECOVERED' then
      select e.* into strict v_case_event from private.bpay_next_case_event e where e.id=v_effect.operation_item_id;
      select h.* into strict v_case_hold from private.bpay_next_case_hold h where h.id=v_case_event.operation_item_id and h.status='REALISED';
      select sum(s.reserved_source_ex_vat) into v_amount from private.bpay_next_work_segment_recovery_share s
        where s.case_hold_id=v_case_hold.id and s.work_id=new.work_id and s.component_key=new.component_key and s.segment_key=new.segment_key;
      if (new.work_id,new.component_key) is distinct from (v_effect.work_id,v_effect.component_key)
        or (new.source_disposition_ex_vat,new.target_ex_vat,new.target_vat,new.target_inc_vat)
          is distinct from (-v_amount,-v_amount,0::numeric,-v_amount) or v_amount is null
        or not exists(select 1 from private.bpay_next_job j
          join private.bpay_next_outcome_request r on r.command_id=j.command_id and r.transfer_id=v_case_event.original_transfer_id
          join private.bpay_next_transfer_member m on m.transfer_id=r.transfer_id and m.case_hold_id=v_case_hold.id
            and m.case_instruction_id=v_case_event.instruction_id and m.case_allocation_result_id=v_case_event.allocation_result_id and m.subject_kind='CASE'
          join private.bpay_next_case_capacity_use u on u.case_hold_id=v_case_hold.id and u.status='REALISED' and u.realisation_event_id=v_case_event.id
          join private.bpay_next_worker_control c on c.candidate_id=j.candidate_id and c.active_owner_epoch=j.owner_epoch
          join private.bpay_next_module_control mod on mod.id=1 and mod.active_owner='NEXT' and mod.owner_epoch=j.module_epoch
          where j.command_id=v_effect.operation_id and j.candidate_id=v_effect.candidate_id and j.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT')
            and j.phase='MEMBERS' and j.status='LEASED' and j.lease_until_utc>clock_timestamp()
            and v_case_event.event_kind='RECOVERED' and v_case_event.operation_id=j.command_id
            and v_case_event.case_id=v_effect.case_id and v_case_event.source_amount_ex_vat=v_case_hold.source_reserved_ex_vat
            and v_case_event.candidate_id=j.candidate_id and v_case_hold.run_worker_id=r.run_worker_id) then
        raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_RECOVERY_EFFECT_SHARE_INVALID';
      end if;
      return new;
    end if;
    if (new.work_id,new.component_key) is distinct from (v_effect.work_id,v_effect.component_key)
      or v_effect.effect_kind<>'PAYROLL_SETTLED' then
      raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_EFFECT_SHARE_SCOPE_INVALID';
    end if;
    select h.* into strict v_hold from private.bpay_next_hold h where h.id=v_effect.operation_item_id and h.status='ACTIVE';
    select s.* into strict v_origin from private.bpay_next_work_segment_origin_share s where s.hold_id=v_hold.id and s.segment_key=new.segment_key;
    if (new.work_id,new.component_key) is distinct from (v_origin.work_id,v_origin.component_key)
      or (v_hold.work_id,v_hold.component_key) is distinct from (v_effect.work_id,v_effect.component_key)
      or (new.source_disposition_ex_vat,new.target_ex_vat,new.target_vat,new.target_inc_vat)
      is distinct from (v_origin.source_reserved_ex_vat,v_origin.target_reserved_ex_vat,v_origin.target_reserved_vat,v_origin.target_reserved_inc_vat)
      or not exists(select 1 from private.bpay_next_job j
        join private.bpay_next_outcome_request r on r.command_id=j.command_id and r.transfer_id=v_effect.original_transfer_id
        join private.bpay_next_transfer t on t.id=r.transfer_id and t.original_transfer_id is null and t.return_cash_id is null
        join private.bpay_next_transfer_member m on m.transfer_id=t.id and m.run_line_id=v_hold.run_line_id and m.subject_kind='WORK'
        join private.bpay_next_worker_control c on c.candidate_id=j.candidate_id and c.active_owner_epoch=j.owner_epoch
        join private.bpay_next_module_control mod on mod.id=1 and mod.active_owner='NEXT' and mod.owner_epoch=j.module_epoch
        where j.command_id=v_effect.operation_id and j.candidate_id=v_effect.candidate_id and j.status='LEASED' and j.phase='MEMBERS'
          and j.lease_until_utc>clock_timestamp() and ((j.job_kind='CSV_SETTLEMENT' and t.execution_kind='BANK' and t.status in ('SETTLED','RETURNED'))
            or (j.job_kind='INTERNAL_SETTLEMENT' and t.execution_kind='INTERNAL_ZERO' and t.status='INTERNAL_PROCESSING'))) then
      raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_EFFECT_SHARE_OWNER_INVALID';
    end if;
    return new;
  end if;
  if tg_table_name='bpay_next_work_segment_effect_origin' then
    select e.* into strict v_effect_share from private.bpay_next_work_segment_effect_share e where e.id=new.effect_share_id;
    select s.* into strict v_origin from private.bpay_next_work_segment_origin_share s where s.id=new.origin_share_id;
    select e.* into strict v_effect from private.bpay_next_financial_effect e where e.id=v_effect_share.effect_id;
    if v_effect.effect_kind='WORK_COLLECTION_RECOVERED' then
      select e.* into strict v_case_event from private.bpay_next_case_event e where e.id=v_effect.operation_item_id;
      if (v_effect_share.work_id,v_effect_share.component_key,v_effect_share.segment_key)
        is distinct from (v_origin.work_id,v_origin.component_key,v_origin.segment_key)
        or new.source_disposition_ex_vat>=0 or not exists(select 1 from private.bpay_next_work_segment_recovery_share s
          where s.case_hold_id=v_case_event.operation_item_id and s.origin_share_id=v_origin.id
            and s.work_id=v_effect.work_id and s.component_key=v_effect.component_key
            and s.reserved_source_ex_vat=-new.source_disposition_ex_vat)
        or -new.source_disposition_ex_vat>coalesce((select sum(e.source_disposition_ex_vat)
          from private.bpay_next_work_segment_effect_origin e where e.origin_share_id=v_origin.id),0) then
        raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_RECOVERY_ORIGIN_INVALID';
      end if;
      return new;
    end if;
    if (v_effect_share.work_id,v_effect_share.component_key,v_effect_share.segment_key)
      is distinct from (v_origin.work_id,v_origin.component_key,v_origin.segment_key)
      or v_effect.operation_item_id<>v_origin.hold_id or v_effect.effect_kind<>'PAYROLL_SETTLED'
      or new.source_disposition_ex_vat<>v_origin.source_reserved_ex_vat
      or new.source_disposition_ex_vat<>v_effect_share.source_disposition_ex_vat then
      raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_EFFECT_ORIGIN_SCOPE_INVALID';
    end if;
    return new;
  end if;
  raise exception using errcode='23514',message='BPAY_NEXT_SEGMENT_FACT_RELATION_UNSUPPORTED';
end
$function$;
alter function private.bpay_next_choice_leaf_eligible_v1(uuid,uuid,uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_choice_leaf_eligible_v1(uuid,uuid,uuid,uuid,uuid) from public,anon,authenticated,service_role;
alter function private.bpay_next_selection_memory_capture_v1(uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_selection_memory_capture_v1(uuid,jsonb) from public,anon,authenticated,service_role;
alter function private.bpay_next_create_preparation_v1(uuid,uuid,date,jsonb,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_create_preparation_v1(uuid,uuid,date,jsonb,uuid,jsonb) from public,anon,authenticated,service_role;
alter function private.bpay_next_materialise_choice_segments_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_materialise_choice_segments_v1(uuid,uuid) from public,anon,authenticated,service_role;
alter function private.bpay_next_seal_segment_selection_v1(uuid,uuid,uuid,bigint,bigint) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_seal_segment_selection_v1(uuid,uuid,uuid,bigint,bigint) from public,anon,authenticated,service_role;
alter function private.bpay_next_segment_fact_guard_v1() OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_segment_fact_guard_v1() from public,anon,authenticated,service_role;


-- CONTACT_PREPARER_UNIT 86 repeatable supabase/repeatable/13102026_0028_banking_pay_next_frozen_selected_treatment_v1.sql SHA256 7f9a0bf83a21fe75f33abdf4c14b19fc1f767cf26712cf11ed89494df82c272d
-- WB29: qualified frozen selected treatment; original source pages and admission retained.


create or replace function public.bpay_next_frozen_detail_page_v1(
  p_actor_user_id uuid,p_kind text,p_run_line_id uuid default null,
  p_run_work_id uuid default null,p_shift_detail_id uuid default null,
  p_after_detail_no integer default null,p_after_break_no integer default null,
  p_after_bucket text default null,p_after_rate_family text default null,
  p_after_rate_code text default null,p_limit integer default 50
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_rows jsonb:='[]'::jsonb;
  v_sql text;
  v_page record;
  v_bytes bigint:=512;
  v_count integer:=0;
  v_more boolean:=false;
  v_origin jsonb;
  v_revision_id uuid;
  v_used_line jsonb;
  v_treatment jsonb;
  v_treatment_line private.bpay_next_run_line%rowtype;
  v_treatment_position private.bpay_next_run_position%rowtype;
  v_treatment_worker private.bpay_next_run_worker%rowtype;
  v_treatment_work private.bpay_next_run_work%rowtype;
  v_treatment_run private.bpay_next_pay_run%rowtype;
  v_selected_quote jsonb;
  v_selected_buckets jsonb:='[]'::jsonb;
  v_selected_bucket jsonb;

begin
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
      nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role'
     or not exists(select 1 from public.tms_users u where u.id=p_actor_user_id
                   and u.is_active is true and u.role::text='admin') then
    raise exception using errcode='42501',message='BPAY_NEXT_FROZEN_FORBIDDEN';
  end if;
  if not exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT') then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  if p_kind is null or p_kind not in ('SHIFTS','BREAKS','RATE_DETAILS','RATE_SCHEDULE')
     or p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode='22023',message='BPAY_NEXT_FROZEN_REQUEST_INVALID';
  end if;
  if p_kind='RATE_SCHEDULE' then
    if p_run_work_id is null or p_run_line_id is not null or p_shift_detail_id is not null
       or p_after_detail_no is not null or p_after_break_no is not null or p_after_bucket is not null then
      raise exception using errcode='22023',message='BPAY_NEXT_FROZEN_REQUEST_INVALID';
    end if;
    v_sql:=$query$select to_jsonb(page) row_value
    from (select rate_schedule_id,rate_family,rate_code,unit_label,
          paye_rate::text,umbrella_rate::text,charge_rate::text
          from private.bpay_next_simple_rate_schedule_page_v1($1,$5,$6,$7)) page$query$;
  else
    if p_run_line_id is null or p_run_work_id is not null
       or p_after_rate_family is not null or p_after_rate_code is not null then
      raise exception using errcode='22023',message='BPAY_NEXT_FROZEN_REQUEST_INVALID';
    end if;
    if p_kind='SHIFTS' then
      if p_shift_detail_id is not null or p_after_break_no is not null or p_after_bucket is not null then
        raise exception using errcode='22023',message='BPAY_NEXT_FROZEN_REQUEST_INVALID';
      end if;
      v_sql:=$query$select to_jsonb(page) row_value
      from (select shift_detail_id,detail_no,work_date,shift_start_at,shift_end_at,
            shift_start_local,shift_end_local,shift_overnight,submitted_minutes,
            approved_minutes,approved_hours::text,detail_label,
            segment_pay_ex_vat::text,pay_excluded,
            hours_day::text,hours_night::text,hours_sat::text,hours_sun::text,hours_bh::text
            from private.bpay_next_simple_shift_page_v2($1,$3,$7)) page$query$;
    elsif p_kind='BREAKS' then
      if p_after_detail_no is not null or p_after_bucket is not null then
        raise exception using errcode='22023',message='BPAY_NEXT_FROZEN_REQUEST_INVALID';
      end if;
      v_sql:=$query$select to_jsonb(page) row_value
      from private.bpay_next_simple_break_page_v1($1,$2,$3,$7) page$query$;
    else
      if p_shift_detail_id is not null or p_after_detail_no is not null or p_after_break_no is not null then
        raise exception using errcode='22023',message='BPAY_NEXT_FROZEN_REQUEST_INVALID';
      end if;
      v_sql:=$query$select to_jsonb(page) row_value
      from (select rate_detail_id,bucket,approved_hours::text,source_pay_rate::text
            from private.bpay_next_simple_rate_detail_page_v1($1,$4,$7)) page$query$;
    end if;
  end if;
  -- One captured revision subject, never a current Client/Contract lookup.
  if p_kind='RATE_SCHEDULE' then
    select rw.captured_revision_id into strict v_revision_id
      from private.bpay_next_run_work rw where rw.id=p_run_work_id;
  else
    select g.captured_revision_id into strict v_revision_id
      from private.bpay_next_simple_frozen_line_guard_v1(p_run_line_id) g;
  end if;
  v_origin:=private.bpay_next_payment_client_origin_v1(v_revision_id);
  if p_kind='RATE_DETAILS' then
    -- The guarded immutable line/revision pair owns actual used quantities/rates.
    -- No live rate, amount division or capture/publisher change is permitted.
    select jsonb_build_object('component_kind',l.component_kind,
      'component_key',l.component_key,'unit_label',l.unit_label,
      'approved_quantity',l.approved_quantity::text,
      'approved_unit_rate',l.approved_unit_rate::text)
      into strict v_used_line
      from private.bpay_next_simple_frozen_line_guard_v1(p_run_line_id) g
      join private.bpay_next_approved_line l on l.id=g.approved_line_id
        and l.revision_id=g.captured_revision_id;
  end if;

  -- WB29: exact frozen line, never today's decision/target/Position.
  if p_kind='RATE_DETAILS' then
    select l.* into strict v_treatment_line from private.bpay_next_run_line l where l.id=p_run_line_id;
    if v_treatment_line.accepted_resolution_refs is not null
       and jsonb_array_length(v_treatment_line.accepted_resolution_refs)>0 then
      select p.* into v_treatment_position from private.bpay_next_run_position p
        where p.run_work_id=v_treatment_line.run_work_id and p.component_key=v_treatment_line.component_key;
      select w.* into v_treatment_worker from private.bpay_next_run_worker w where w.id=v_treatment_line.run_worker_id;
      select w.* into v_treatment_work from private.bpay_next_run_work w where w.id=v_treatment_line.run_work_id;
      select r.* into v_treatment_run from private.bpay_next_pay_run r where r.id=v_treatment_worker.run_id;
      if v_treatment_position.id is null or v_treatment_worker.id is null or v_treatment_work.id is null or v_treatment_run.id is null
        or (v_treatment_position.run_worker_id,v_treatment_position.work_id,v_treatment_position.captured_revision_id,v_treatment_position.approved_line_id)
          is distinct from (v_treatment_line.run_worker_id,v_treatment_line.work_id,v_treatment_line.captured_revision_id,v_treatment_line.approved_line_id)
        or (v_treatment_work.run_worker_id,v_treatment_work.work_id,v_treatment_work.captured_revision_id,v_treatment_work.candidate_id)
          is distinct from (v_treatment_worker.id,v_treatment_line.work_id,v_treatment_line.captured_revision_id,v_treatment_worker.candidate_id)
        or v_treatment_line.target_pay_channel is distinct from v_treatment_worker.target_pay_channel
        or v_treatment_line.source_pay_channel is distinct from v_treatment_position.source_pay_channel then
        raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_ACCEPTED_BASIS_CHANGED';end if;
      v_selected_quote:=private.bpay_next_captured_component_resolution_quote_v1(v_treatment_position.id,null);
      if v_selected_quote->'accepted_resolution_refs' is distinct from v_treatment_line.accepted_resolution_refs
        or (v_selected_quote->>'included_source_component_ex_vat')::numeric is distinct from v_treatment_line.source_consumed_ex_vat
        or ((v_selected_quote#>>'{component_quote,ex}')::numeric,(v_selected_quote#>>'{component_quote,vat}')::numeric,(v_selected_quote#>>'{component_quote,inc}')::numeric)
          is distinct from (v_treatment_line.frozen_ex_vat,v_treatment_line.frozen_vat,v_treatment_line.frozen_inc_vat)
        or ((v_selected_quote->>'valuation_policy_id')::uuid,(v_selected_quote->>'valuation_window_id')::uuid)
          is distinct from (v_treatment_line.valuation_policy_id,v_treatment_line.policy_window_id)
        or jsonb_typeof(v_selected_quote->'bucket_details') is distinct from 'array'
        or jsonb_array_length(v_selected_quote->'bucket_details') not between 1 and 5
        or (select count(distinct jsonb_build_array(x.value->>'rate_family',x.value->>'rate_code'))
          from jsonb_array_elements(v_selected_quote->'bucket_details') x)<>jsonb_array_length(v_selected_quote->'bucket_details') then
        raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_ACCEPTED_BASIS_CHANGED';end if;
      for v_selected_bucket in select x.value from jsonb_array_elements(v_selected_quote->'bucket_details') x loop
        if ((v_selected_bucket->>'valuation_policy_id')::uuid,(v_selected_bucket->>'valuation_window_id')::uuid)
          is distinct from (v_treatment_line.valuation_policy_id,v_treatment_line.policy_window_id) then
          raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_ACCEPTED_BASIS_CHANGED';end if;
        v_selected_buckets:=v_selected_buckets||jsonb_build_array(jsonb_build_object(
          'rate_family',v_selected_bucket->>'rate_family','rate_code',v_selected_bucket->>'rate_code',
          'decision_id',v_selected_bucket->>'decision_id','decision_version',v_selected_bucket->>'decision_version',
          'treatment',v_selected_bucket->>'treatment','resolution_mode',v_selected_bucket->>'resolution_mode',
          'approved_units',v_selected_bucket->>'approved_units','included_units',v_selected_bucket->>'included_units',
          'source_rate',v_selected_bucket->>'source_rate','source_ex_vat',v_selected_bucket->>'source_ex_vat',
          'manual_replacement_rate',v_selected_bucket->>'manual_replacement_rate','manual_amount_ex_vat',v_selected_bucket->>'manual_amount_ex_vat',
          'quote',jsonb_build_object('ex',v_selected_bucket#>>'{quote,ex}','vat',v_selected_bucket#>>'{quote,vat}',
            'inc',v_selected_bucket#>>'{quote,inc}','rate',v_selected_bucket#>>'{quote,rate}'),
          'valuation_policy_id',v_selected_bucket->>'valuation_policy_id','valuation_window_id',v_selected_bucket->>'valuation_window_id'));
      end loop;
      v_treatment:=jsonb_build_object('run_line_id',v_treatment_line.id,'run_work_id',v_treatment_work.id,
        'run_worker_id',v_treatment_worker.id,'candidate_id',v_treatment_worker.candidate_id,
        'captured_revision_id',v_treatment_line.captured_revision_id,'approved_line_id',v_treatment_line.approved_line_id,
        'component_key',v_treatment_line.component_key,'source_pay_channel',v_treatment_line.source_pay_channel,
        'target_pay_channel',v_treatment_worker.target_pay_channel,'target_umbrella_id',v_treatment_worker.target_umbrella_id,
        'target_umbrella_vat_chargeable',v_treatment_worker.target_umbrella_vat_chargeable,
        'valuation_policy_id',v_treatment_line.valuation_policy_id,'valuation_window_id',v_treatment_line.policy_window_id,
        'valuation_date',v_treatment_run.pay_date,'source_consumed_ex_vat',v_treatment_line.source_consumed_ex_vat::text,
        'component_quote',jsonb_build_object('ex',v_treatment_line.frozen_ex_vat::text,'vat',v_treatment_line.frozen_vat::text,'inc',v_treatment_line.frozen_inc_vat::text),
        'buckets',v_selected_buckets);
    end if;
    -- Metadata is charged once, before the original source row page.
    v_bytes:=v_bytes+coalesce(octet_length(v_treatment::text),4);
    if v_bytes>120000 then raise exception using errcode='54000',message='BPAY_NEXT_FROZEN_DETAIL_ROW_TOO_LARGE';end if;
  end if;
  v_bytes:=v_bytes+octet_length(v_origin::text)+coalesce(octet_length(v_used_line::text),4);
  if v_bytes>120000 then
    raise exception using errcode='54000',message='BPAY_NEXT_FROZEN_DETAIL_ROW_TOO_LARGE';
  end if;
  -- Fixed SQL choices only: no caller-supplied identifier/query. Each source
  -- returns <=100 rows. Charge encoded bytes BEFORE adding each row to the
  -- response; a byte-short page is explicitly incomplete, not end-of-data.
  for v_page in execute v_sql using coalesce(p_run_line_id,p_run_work_id),p_shift_detail_id,
    coalesce(p_after_detail_no,p_after_break_no),p_after_bucket,p_after_rate_family,p_after_rate_code,p_limit
  loop
    if v_bytes+octet_length(v_page.row_value::text)+1>120000 then
      if v_count=0 then
        raise exception using errcode='54000',message='BPAY_NEXT_FROZEN_DETAIL_ROW_TOO_LARGE';
      end if;
      v_more:=true;
      exit;
    end if;
    v_bytes:=v_bytes+octet_length(v_page.row_value::text)+1;
    v_rows:=v_rows||jsonb_build_array(v_page.row_value);
    v_count:=v_count+1;
  end loop;
  -- Exact-full row pages may need one final empty request; no count scan.
  return jsonb_build_object('rows',v_rows,'complete',not(v_more or v_count=p_limit),'origin',v_origin,'used_line',v_used_line)||case when p_kind='RATE_DETAILS' then jsonb_build_object('selected_treatment',v_treatment) else '{}'::jsonb end;
end
$function$;
create or replace function public.bpay_next_original_csv_advice_page_v1(
  p_actor_user_id uuid,p_instruction_id uuid,p_kind text,
  p_run_work_id uuid default null,p_run_line_id uuid default null,p_shift_detail_id uuid default null,
  p_after_work_id uuid default null,p_after_member_no bigint default null,
  p_after_detail_no integer default null,p_after_break_no integer default null,
  p_after_bucket text default null,p_after_rate_family text default null,p_after_rate_code text default null,
  p_limit integer default 50
) returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,private,public
set timezone='UTC'
as $function$
declare
  v_instruction private.bpay_next_csv_instruction%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_run private.bpay_next_pay_run%rowtype;
  v_leg private.bpay_next_destination_group_leg%rowtype;
  v_group private.bpay_next_destination_group%rowtype;
  v_net private.bpay_next_net_destination_state%rowtype;
  v_destination private.bpay_next_net_destination_amount%rowtype;
  v_origin private.bpay_next_stored_credit_origin%rowtype;
  v_destination_kind text:='OWN';
  v_approved_line uuid;
  v_revision uuid;
  v_sql text;
  v_row record;
  v_rows jsonb:='[]'::jsonb;
  v_bytes integer:=512;
  v_count integer:=0;
  v_more boolean:=false;
  v_treatment jsonb;
  v_treatment_line private.bpay_next_run_line%rowtype;
  v_treatment_position private.bpay_next_run_position%rowtype;
  v_treatment_worker private.bpay_next_run_worker%rowtype;
  v_treatment_work private.bpay_next_run_work%rowtype;
  v_treatment_run private.bpay_next_pay_run%rowtype;
  v_selected_quote jsonb;
  v_selected_buckets jsonb:='[]'::jsonb;
  v_selected_bucket jsonb;

begin
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
    nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role'
    or not exists(select 1 from public.tms_users u where u.id=p_actor_user_id
      and u.is_active is true and u.role::text='admin') then
    raise exception using errcode='42501',message='BPAY_NEXT_ADVICE_FORBIDDEN';
  end if;
  if not exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT') then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  if p_instruction_id is null or p_kind is null
    or p_kind not in ('HEADER','WORKS','MEMBERS','SHIFTS','BREAKS','RATE_DETAILS','RATE_SCHEDULE')
    or p_limit is null or p_limit not between 1 and 100
    or (p_after_member_no is not null and p_after_member_no<0)
    or (p_after_detail_no is not null and p_after_detail_no<0)
    or (p_after_break_no is not null and p_after_break_no<0)
    or (p_after_bucket is not null and p_after_bucket not in ('BH','DAY','NIGHT','SAT','SUN'))
    or ((p_after_rate_family is null)<>(p_after_rate_code is null))
    or (p_after_rate_family is not null and (p_after_rate_family not in ('ADDITIONAL','MILEAGE','STANDARD')
      or char_length(p_after_rate_code) not between 1 and 128)) then
    raise exception using errcode='22023',message='BPAY_NEXT_ADVICE_REQUEST_INVALID';
  end if;
  -- Closed shape: no cursor or child ID is silently ignored by a different kind.
  if (p_run_work_id is not null and p_kind<>'RATE_SCHEDULE')
    or (p_run_line_id is not null and p_kind not in ('SHIFTS','BREAKS','RATE_DETAILS'))
    or (p_shift_detail_id is not null and p_kind<>'BREAKS')
    or (p_after_work_id is not null and p_kind<>'WORKS')
    or (p_after_member_no is not null and p_kind<>'MEMBERS')
    or (p_after_detail_no is not null and p_kind<>'SHIFTS')
    or (p_after_break_no is not null and p_kind<>'BREAKS')
    or (p_after_bucket is not null and p_kind<>'RATE_DETAILS')
    or (p_after_rate_family is not null and p_kind<>'RATE_SCHEDULE')
    or (p_kind='RATE_SCHEDULE' and p_run_work_id is null)
    or (p_kind in ('SHIFTS','BREAKS','RATE_DETAILS') and p_run_line_id is null)
    or (p_kind='BREAKS' and p_shift_detail_id is null) then
    raise exception using errcode='22023',message='BPAY_NEXT_ADVICE_REQUEST_INVALID';
  end if;
  select * into v_instruction from private.bpay_next_csv_instruction where id=p_instruction_id;
  if not found then
    raise exception using errcode='P0002',message='BPAY_NEXT_ADVICE_INSTRUCTION_NOT_FOUND';
  end if;
  select * into strict v_transfer from private.bpay_next_transfer where id=v_instruction.transfer_id;
  if v_transfer.original_transfer_id is not null or v_transfer.projection_id is null then
    raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_ORIGINAL_CSV_REQUIRED';
  end if;
  select * into strict v_projection from private.bpay_next_net_projection where id=v_transfer.projection_id;
  select * into strict v_worker from private.bpay_next_run_worker where id=v_instruction.run_worker_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_worker.run_id;
  if v_transfer.original_transfer_id is not null or v_transfer.execution_kind<>'BANK'
    or not ((v_worker.target_pay_channel='PAYE' and v_transfer.beneficiary_kind='CANDIDATE')
      or (v_worker.target_pay_channel='UMBRELLA' and v_transfer.beneficiary_kind='UMBRELLA'
        and v_worker.target_umbrella_id is not null and v_projection.input_kind='UMBRELLA'
        and v_worker.case_selection_revision=0))
    or v_transfer.run_worker_id<>v_worker.id or v_transfer.candidate_id<>v_worker.candidate_id
    or v_projection.run_worker_id<>v_worker.id
    or v_transfer.beneficiary_id is distinct from
      (case when v_worker.target_pay_channel='UMBRELLA' then v_worker.target_umbrella_id else v_worker.candidate_id end)
    or v_transfer.return_cash_id is not null
    or v_instruction.cash_amount<>v_transfer.cash_amount
    or v_instruction.bank_details_hash_snapshot is distinct from v_transfer.bank_details_hash_snapshot
    or v_transfer.member_count<1 or v_transfer.member_cash_sum<>v_transfer.cash_amount
    or (v_worker.target_pay_channel='PAYE' and v_projection.input_kind not in ('PAYE_MANUAL','PAYE_IMPORT','CASE_PAYOUT'))
    or (v_worker.target_pay_channel='UMBRELLA' and
      (v_projection.entered_paye_net is not null or v_projection.request_command_id is not null
       or v_projection.cash_amount is distinct from v_projection.gross_inc_vat)) then
    raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_ORIGINAL_CSV_REQUIRED';
  end if;
  -- A frozen leg may be smaller than its accepted Candidate projection. This
  -- is a point read of immutable sealed facts, NOT the execution qualifier:
  -- that qualifier checks today's bank version and must not invalidate advice
  -- for an already-issued original instruction after factual account changes.
  select * into v_leg from private.bpay_next_destination_group_leg where transfer_id=v_transfer.id;
  if not found then
    if v_projection.cash_amount<>v_transfer.cash_amount
      or exists(select 1 from private.bpay_next_destination_group where run_worker_id=v_worker.id) then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
  else
    select * into strict v_group from private.bpay_next_destination_group where anchor_transfer_id=v_leg.anchor_transfer_id;
    select * into strict v_net from private.bpay_next_net_destination_state where state_id=v_group.net_state_id;
    if v_group.stage<>'COMPLETE' or v_group.completed_at_utc is null
      or v_group.run_worker_id<>v_worker.id or v_group.candidate_id<>v_worker.candidate_id
      or v_group.projection_id<>v_projection.id or v_net.run_worker_id<>v_worker.id
      or v_net.projection_id is distinct from v_projection.id or v_net.completed_at_utc is null
      or v_group.processed_work_count<>v_group.expected_work_count or v_group.processed_case_count<>v_group.expected_case_count
      or v_group.created_leg_count<>v_group.expected_leg_count or v_group.sealed_leg_count<>v_group.expected_leg_count
      or v_group.expected_leg_count<>v_net.external_leg_count+1
      or v_group.member_cash_total<>v_projection.cash_amount or v_group.sealed_cash_total<>v_projection.cash_amount
      or v_net.cash_amount is distinct from v_projection.cash_amount
      or v_net.own_amount+v_net.external_amount is distinct from v_projection.cash_amount then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
    v_destination_kind:=v_leg.leg_kind;
    if v_leg.leg_kind='OWN' then
      if v_transfer.id<>v_group.anchor_transfer_id or v_leg.destination_id is not null
        or v_transfer.cash_amount is distinct from v_net.own_amount then
        raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
    else
      select * into strict v_destination from private.bpay_next_net_destination_amount where destination_id=v_leg.destination_id;
      select * into strict v_origin from private.bpay_next_stored_credit_origin where command_id=v_destination.first_origin_command_id;
      if v_destination.state_id<>v_net.state_id or v_destination.amount<>v_transfer.cash_amount
        or v_origin.candidate_id<>v_worker.candidate_id or v_destination.bank_details_hash<>v_origin.bank_details_hash
        or v_origin.original_source_pay_channel<>'UMBRELLA' or v_origin.original_tax_treatment<>'NON_TAXABLE'
        or v_origin.original_routing_kind<>'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
        or (v_transfer.bank_details_hash_snapshot,v_transfer.beneficiary_name_snapshot,
            v_transfer.sort_code_snapshot,v_transfer.account_number_snapshot)
          is distinct from (v_origin.bank_details_hash,pg_catalog.btrim(v_origin.beneficiary_name),
            v_origin.sort_code,v_origin.account_number) then
        raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
    end if;
  end if;
  -- CSV issuance is the immutable read gate. Current worker/transfer/outcome
  -- status and retirement of this NET projection cannot re-price this issue.
  if p_kind='HEADER' then
    v_rows:=jsonb_build_array(jsonb_build_object(
      'instruction_id',v_instruction.id,'transfer_id',v_transfer.id,'projection_id',v_projection.id,
      'projection_no',v_projection.projection_no::text,'input_kind',v_projection.input_kind,
      'run_id',v_run.id,'run_worker_id',v_worker.id,'candidate_id',v_worker.candidate_id,
      'pay_date',v_run.pay_date,'target_pay_channel',v_worker.target_pay_channel,
      'beneficiary_name_snapshot',v_transfer.beneficiary_name_snapshot,
      'payment_reference',v_instruction.payment_reference,'issued_at_utc',v_instruction.issued_at_utc,
      'member_count',v_transfer.member_count::text,
      'gross_ex_vat',v_projection.gross_ex_vat::text,'gross_vat',v_projection.gross_vat::text,
      'gross_inc_vat',v_projection.gross_inc_vat::text,'entered_paye_net',v_projection.entered_paye_net::text,
      'accepted_gross_additions',v_projection.accepted_gross_additions::text,
      'accepted_gross_deductions',v_projection.accepted_gross_deductions::text,
      'accepted_net_additions',v_projection.accepted_net_additions::text,
      'accepted_recoveries',v_projection.accepted_recoveries::text,'cash_amount',v_instruction.cash_amount::text,
      'projection_cash_amount',v_projection.cash_amount::text,'destination_kind',v_destination_kind));
    if octet_length(v_rows::text)>120000 then
      raise exception using errcode='54000',message='BPAY_NEXT_ADVICE_ROW_TOO_LARGE';
    end if;
    return jsonb_build_object('rows',v_rows,'complete',true);
  end if;
  if p_kind in ('SHIFTS','BREAKS','RATE_DETAILS') then
    select l.approved_line_id into v_approved_line
    from private.bpay_next_transfer_member m join private.bpay_next_run_line l on l.id=m.run_line_id
    where m.transfer_id=v_transfer.id and m.subject_kind='WORK' and l.id=p_run_line_id
      and l.run_worker_id=v_worker.id;
    if not found then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_LINE_NOT_IN_INSTRUCTION';
    end if;
  elsif p_kind='RATE_SCHEDULE' then
    select rw.captured_revision_id into v_revision from private.bpay_next_run_work rw
    where rw.id=p_run_work_id and rw.run_worker_id=v_worker.id and exists(
      select 1 from private.bpay_next_run_line l join private.bpay_next_transfer_member m on m.run_line_id=l.id
      where l.run_work_id=rw.id and m.transfer_id=v_transfer.id and m.subject_kind='WORK');
    if not found then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_WORK_NOT_IN_INSTRUCTION';
    end if;
  end if;

  -- WB29: exact frozen line, never today's decision/target/Position.
  if p_kind='RATE_DETAILS' then
    select l.* into strict v_treatment_line from private.bpay_next_run_line l where l.id=p_run_line_id;
    if v_treatment_line.accepted_resolution_refs is not null
       and jsonb_array_length(v_treatment_line.accepted_resolution_refs)>0 then
      select p.* into v_treatment_position from private.bpay_next_run_position p
        where p.run_work_id=v_treatment_line.run_work_id and p.component_key=v_treatment_line.component_key;
      select w.* into v_treatment_worker from private.bpay_next_run_worker w where w.id=v_treatment_line.run_worker_id;
      select w.* into v_treatment_work from private.bpay_next_run_work w where w.id=v_treatment_line.run_work_id;
      select r.* into v_treatment_run from private.bpay_next_pay_run r where r.id=v_treatment_worker.run_id;
      if v_treatment_position.id is null or v_treatment_worker.id is null or v_treatment_work.id is null or v_treatment_run.id is null
        or (v_treatment_position.run_worker_id,v_treatment_position.work_id,v_treatment_position.captured_revision_id,v_treatment_position.approved_line_id)
          is distinct from (v_treatment_line.run_worker_id,v_treatment_line.work_id,v_treatment_line.captured_revision_id,v_treatment_line.approved_line_id)
        or (v_treatment_work.run_worker_id,v_treatment_work.work_id,v_treatment_work.captured_revision_id,v_treatment_work.candidate_id)
          is distinct from (v_treatment_worker.id,v_treatment_line.work_id,v_treatment_line.captured_revision_id,v_treatment_worker.candidate_id)
        or v_treatment_line.target_pay_channel is distinct from v_treatment_worker.target_pay_channel
        or v_treatment_line.source_pay_channel is distinct from v_treatment_position.source_pay_channel then
        raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_ACCEPTED_BASIS_CHANGED';end if;
      v_selected_quote:=private.bpay_next_captured_component_resolution_quote_v1(v_treatment_position.id,null);
      if v_selected_quote->'accepted_resolution_refs' is distinct from v_treatment_line.accepted_resolution_refs
        or (v_selected_quote->>'included_source_component_ex_vat')::numeric is distinct from v_treatment_line.source_consumed_ex_vat
        or ((v_selected_quote#>>'{component_quote,ex}')::numeric,(v_selected_quote#>>'{component_quote,vat}')::numeric,(v_selected_quote#>>'{component_quote,inc}')::numeric)
          is distinct from (v_treatment_line.frozen_ex_vat,v_treatment_line.frozen_vat,v_treatment_line.frozen_inc_vat)
        or ((v_selected_quote->>'valuation_policy_id')::uuid,(v_selected_quote->>'valuation_window_id')::uuid)
          is distinct from (v_treatment_line.valuation_policy_id,v_treatment_line.policy_window_id)
        or jsonb_typeof(v_selected_quote->'bucket_details') is distinct from 'array'
        or jsonb_array_length(v_selected_quote->'bucket_details') not between 1 and 5
        or (select count(distinct jsonb_build_array(x.value->>'rate_family',x.value->>'rate_code'))
          from jsonb_array_elements(v_selected_quote->'bucket_details') x)<>jsonb_array_length(v_selected_quote->'bucket_details') then
        raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_ACCEPTED_BASIS_CHANGED';end if;
      for v_selected_bucket in select x.value from jsonb_array_elements(v_selected_quote->'bucket_details') x loop
        if ((v_selected_bucket->>'valuation_policy_id')::uuid,(v_selected_bucket->>'valuation_window_id')::uuid)
          is distinct from (v_treatment_line.valuation_policy_id,v_treatment_line.policy_window_id) then
          raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_ACCEPTED_BASIS_CHANGED';end if;
        v_selected_buckets:=v_selected_buckets||jsonb_build_array(jsonb_build_object(
          'rate_family',v_selected_bucket->>'rate_family','rate_code',v_selected_bucket->>'rate_code',
          'decision_id',v_selected_bucket->>'decision_id','decision_version',v_selected_bucket->>'decision_version',
          'treatment',v_selected_bucket->>'treatment','resolution_mode',v_selected_bucket->>'resolution_mode',
          'approved_units',v_selected_bucket->>'approved_units','included_units',v_selected_bucket->>'included_units',
          'source_rate',v_selected_bucket->>'source_rate','source_ex_vat',v_selected_bucket->>'source_ex_vat',
          'manual_replacement_rate',v_selected_bucket->>'manual_replacement_rate','manual_amount_ex_vat',v_selected_bucket->>'manual_amount_ex_vat',
          'quote',jsonb_build_object('ex',v_selected_bucket#>>'{quote,ex}','vat',v_selected_bucket#>>'{quote,vat}',
            'inc',v_selected_bucket#>>'{quote,inc}','rate',v_selected_bucket#>>'{quote,rate}'),
          'valuation_policy_id',v_selected_bucket->>'valuation_policy_id','valuation_window_id',v_selected_bucket->>'valuation_window_id'));
      end loop;
      v_treatment:=jsonb_build_object('run_line_id',v_treatment_line.id,'run_work_id',v_treatment_work.id,
        'run_worker_id',v_treatment_worker.id,'candidate_id',v_treatment_worker.candidate_id,
        'captured_revision_id',v_treatment_line.captured_revision_id,'approved_line_id',v_treatment_line.approved_line_id,
        'component_key',v_treatment_line.component_key,'source_pay_channel',v_treatment_line.source_pay_channel,
        'target_pay_channel',v_treatment_worker.target_pay_channel,'target_umbrella_id',v_treatment_worker.target_umbrella_id,
        'target_umbrella_vat_chargeable',v_treatment_worker.target_umbrella_vat_chargeable,
        'valuation_policy_id',v_treatment_line.valuation_policy_id,'valuation_window_id',v_treatment_line.policy_window_id,
        'valuation_date',v_treatment_run.pay_date,'source_consumed_ex_vat',v_treatment_line.source_consumed_ex_vat::text,
        'component_quote',jsonb_build_object('ex',v_treatment_line.frozen_ex_vat::text,'vat',v_treatment_line.frozen_vat::text,'inc',v_treatment_line.frozen_inc_vat::text),
        'buckets',v_selected_buckets);
    end if;
    -- Metadata is charged once, before the original source row page.
    v_bytes:=v_bytes+coalesce(octet_length(v_treatment::text),4);
    if v_bytes>120000 then raise exception using errcode='54000',message='BPAY_NEXT_ADVICE_ROW_TOO_LARGE';end if;
  end if;
  if p_kind='WORKS' then
    v_sql:=$query$select private.bpay_next_advice_work_v1(rw.id) row_value
      from private.bpay_next_run_work rw where rw.run_worker_id=$2
        and ($6::uuid is null or rw.work_id>$6) and exists(
          select 1 from private.bpay_next_run_line l join private.bpay_next_transfer_member m on m.run_line_id=l.id
          where l.run_work_id=rw.id and m.transfer_id=$1 and m.subject_kind='WORK')
      order by rw.work_id limit $12$query$;
  elsif p_kind='MEMBERS' then
    v_sql:=$query$select jsonb_build_object(
      'member_no',m.member_no::text,'subject_kind',m.subject_kind,'signed_cash_contribution',m.signed_cash_contribution::text,
      'work',case when m.subject_kind='WORK' then private.bpay_next_advice_work_v1(l.run_work_id) end,
      'line',case when m.subject_kind='WORK' then jsonb_build_object(
        'run_line_id',l.id,'run_work_id',l.run_work_id,'captured_revision_id',l.captured_revision_id,
        'line_no',l.line_no::text,'component_key',l.component_key,'component_kind',a.component_kind,
        'work_date',a.work_date,'unit_label',a.unit_label,'approved_quantity',a.approved_quantity::text,
        'approved_unit_rate',a.approved_unit_rate::text,'expected_rate_detail_count',a.expected_rate_detail_count,
        'evidence_ref',a.evidence_ref,'approved_source_ex_vat',a.source_pay_ex_vat::text,
        'source_consumed_ex_vat',l.source_consumed_ex_vat::text,'frozen_ex_vat',l.frozen_ex_vat::text,
        'frozen_vat',l.frozen_vat::text,'frozen_inc_vat',l.frozen_inc_vat::text) end,
      'case',case when m.subject_kind='CASE' then jsonb_build_object(
        'case_instruction_id',ci.id,'allocation_result_id',cr.id,'case_id',ci.case_id,
        'case_kind',ci.case_kind,'case_subtype',ci.case_subtype,'tax_treatment',ci.tax_treatment,
        'instruction_kind',ci.instruction_kind,'direction',ci.direction,'payroll_stage',ci.payroll_stage,
        'resolution_ref',ci.resolution_ref,'explanation',ci.explanation,
        'allocated_target_ex_vat',cr.allocated_target_ex_vat::text,'allocated_target_vat',cr.allocated_target_vat::text,
        'allocated_target_inc_vat',cr.allocated_target_inc_vat::text) end) row_value
      from private.bpay_next_transfer_member m
      left join private.bpay_next_run_line l on l.id=m.run_line_id and l.run_worker_id=m.run_worker_id
      left join private.bpay_next_approved_line a on a.id=l.approved_line_id and a.revision_id=l.captured_revision_id
      left join private.bpay_next_run_case_instruction ci on ci.id=m.case_instruction_id and ci.run_worker_id=m.run_worker_id
      left join private.bpay_next_case_allocation_result cr on cr.id=m.case_allocation_result_id and cr.instruction_id=ci.id
      where m.transfer_id=$1 and m.member_no>coalesce($7::bigint,0)
      order by m.member_no limit $12$query$;
  elsif p_kind='SHIFTS' then
    v_sql:=$query$select to_jsonb(page) row_value from (
      select s.id shift_detail_id,s.detail_no,s.work_date,s.shift_start_at,s.shift_end_at,s.shift_start_local,
        s.shift_end_local,s.shift_overnight,s.submitted_minutes,s.approved_minutes,s.approved_hours::text,s.detail_label,
        s.segment_pay_ex_vat::text,s.pay_excluded,s.hours_day::text,s.hours_night::text,s.hours_sat::text,s.hours_sun::text,s.hours_bh::text
      from private.bpay_next_shift_detail s where s.approved_line_id=$4 and s.detail_no>coalesce($8::integer,0)
      order by s.detail_no limit $12) page$query$;
  elsif p_kind='BREAKS' then
    if not exists(select 1 from private.bpay_next_shift_detail where id=p_shift_detail_id and approved_line_id=v_approved_line) then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_BREAK_NOT_IN_LINE';
    end if;
    v_sql:=$query$select to_jsonb(page) row_value from (
      select b.id break_detail_id,b.break_no,b.break_start_at,b.break_end_at,b.break_start_local,b.break_end_local,b.break_minutes
      from private.bpay_next_break_detail b where b.shift_detail_id=$5 and b.break_no>coalesce($8::integer,0)
      order by b.break_no limit $12) page$query$;
  elsif p_kind='RATE_DETAILS' then
    v_sql:=$query$select to_jsonb(page) row_value from (
      select d.id rate_detail_id,d.bucket,d.approved_hours::text,d.source_pay_rate::text
      from private.bpay_next_rate_detail d where d.approved_line_id=$4 and ($9::text is null or d.bucket>$9)
      order by d.bucket limit $12) page$query$;
  else
    v_sql:=$query$select to_jsonb(page) row_value from (
      select s.id rate_schedule_id,s.rate_family,s.rate_code,s.unit_label,s.paye_rate::text,s.umbrella_rate::text,s.charge_rate::text
      from private.bpay_next_rate_schedule s where s.revision_id=$3
        and ($10::text is null or (s.rate_family,s.rate_code)>($10,$11))
      order by s.rate_family,s.rate_code limit $12) page$query$;
  end if;
  for v_row in execute v_sql using v_transfer.id,v_worker.id,v_revision,v_approved_line,p_shift_detail_id,
    p_after_work_id,p_after_member_no,coalesce(p_after_detail_no,p_after_break_no),p_after_bucket,p_after_rate_family,p_after_rate_code,p_limit
  loop
    if v_bytes+octet_length(v_row.row_value::text)+1>120000 then
      if v_count=0 then raise exception using errcode='54000',message='BPAY_NEXT_ADVICE_ROW_TOO_LARGE';end if;
      v_more:=true;exit;
    end if;
    v_bytes:=v_bytes+octet_length(v_row.row_value::text)+1;
    v_rows:=v_rows||jsonb_build_array(v_row.row_value);v_count:=v_count+1;
  end loop;
  return jsonb_build_object('rows',v_rows,'complete',not(v_more or v_count=p_limit))||case when p_kind='RATE_DETAILS' then jsonb_build_object('selected_treatment',v_treatment) else '{}'::jsonb end;
end
$function$;
alter function public.bpay_next_frozen_detail_page_v1(uuid,text,uuid,uuid,uuid,integer,integer,text,text,text,integer) OWNER TO CURRENT_USER;
revoke all on function public.bpay_next_frozen_detail_page_v1(uuid,text,uuid,uuid,uuid,integer,integer,text,text,text,integer) from public,anon,authenticated,service_role;
grant execute on function public.bpay_next_frozen_detail_page_v1(uuid,text,uuid,uuid,uuid,integer,integer,text,text,text,integer) to service_role;
alter function public.bpay_next_original_csv_advice_page_v1(uuid,uuid,text,uuid,uuid,uuid,uuid,bigint,integer,integer,text,text,text,integer) OWNER TO CURRENT_USER;
revoke all on function public.bpay_next_original_csv_advice_page_v1(uuid,uuid,text,uuid,uuid,uuid,uuid,bigint,integer,integer,text,text,text,integer) from public,anon,authenticated,service_role;
grant execute on function public.bpay_next_original_csv_advice_page_v1(uuid,uuid,text,uuid,uuid,uuid,uuid,bigint,integer,integer,text,text,text,integer) to service_role;
notify pgrst,'reload schema';


-- CONTACT_PREPARER_UNIT 87 repeatable supabase/repeatable/13102026_0113_banking_pay_next_chosen_display_refresh_quote_v1.sql SHA256 e2e67b9a405d65fb7e2f5cc6e6a3f3fffe42cea4c915e99032cf068bec85ac1c
-- WB-29 Ready chosen display; BD168. Shared native arithmetic and Source summaries unchanged.



create or replace function private.bpay_next_current_component_resolution_quote_v1(
 p_work_id uuid,p_revision_id uuid,p_approved_line_id uuid,p_pay_date date,
 p_selected_leaf_keys text[],p_through_segment_key text,p_projection_refresh boolean
) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,private
as $function$
declare
 w private.bpay_next_work%rowtype;r private.bpay_next_work_revision%rowtype;
 a private.bpay_next_approved_line%rowtype;pos private.bpay_next_position%rowtype;
 g private.bpay_next_workbench_group%rowtype;c public.candidates%rowtype;u public.umbrellas%rowtype;
 md private.bpay_next_workbench_candidate_metadata%rowtype;v_fvr bigint;v_date jsonb;
 d private.bpay_next_component_resolution%rowtype;first_d private.bpay_next_component_resolution%rowtype;active record;
 v_target text;v_umbrella uuid;v_vat boolean;v_line uuid;v_seen integer:=0;
 v_refs jsonb:='[]';v_versions jsonb:='[]';v_decision_keys text[]:='{}';v_key text;
 v_count bigint;v_bad boolean;v_approval_count bigint;v_approval_a numeric;v_selected_count bigint;
 v_segmented boolean;v_member jsonb;v_members jsonb[]:=array[]::jsonb[];v_bytes bigint:=0;
 v_a numeric:=0;v_r numeric:=0;v_h numeric:=0;v_included numeric:=0;v_excluded numeric:=0;
 v_recovery numeric:=0;v_overhang numeric:=0;v_basis jsonb;v_required_included numeric;
 v_working jsonb;v_result jsonb;leaf record;v_native_version text;
begin
 if p_projection_refresh is null or p_work_id is null or p_revision_id is null or p_approved_line_id is null or p_pay_date is null
  or not isfinite(p_pay_date) or p_selected_leaf_keys is null
  or cardinality(p_selected_leaf_keys) not between 1 and 10000
  or array_ndims(p_selected_leaf_keys) is distinct from 1
  or exists(select 1 from unnest(p_selected_leaf_keys) x where x is null or octet_length(x) not between 1 and 8192)
  or (select count(distinct x) from unnest(p_selected_leaf_keys) x)<>cardinality(p_selected_leaf_keys)
  or octet_length(to_jsonb(p_selected_leaf_keys)::text)>8388608 then
  raise exception using errcode='22023',message='BPAY_NEXT_RESOLUTION_IDENTITY_INVALID';end if;
 select x.* into w from private.bpay_next_work x where x.id=p_work_id;
 select x.* into r from private.bpay_next_work_revision x where x.id=p_revision_id and x.work_id=w.id;
 select x.* into a from private.bpay_next_approved_line x where x.id=p_approved_line_id and x.revision_id=r.id;
 select x.* into pos from private.bpay_next_position x where x.work_id=w.id and x.component_key=a.component_key;
 select x.* into c from public.candidates x where x.id=w.candidate_id;
 select x.* into u from public.umbrellas x where x.id=c.umbrella_id;
 select x.* into g from private.bpay_next_workbench_group x where x.work_id=w.id;
 select x.* into md from private.bpay_next_workbench_candidate_metadata x where x.candidate_id=w.candidate_id;
 select x.financial_view_revision into v_fvr from private.bpay_next_worker_control x where x.candidate_id=w.candidate_id;
 v_date:=public.pay_banking_official_date_context_v1(null::timestamptz);
 v_target:=upper(c.pay_method);v_umbrella:=case when v_target='UMBRELLA' then u.id end;
 v_vat:=case when v_target='UMBRELLA' then u.vat_chargeable end;
 if w.id is null or r.id is null or a.id is null or pos.work_id is null or c.id is null or g.work_id is null
  or md.candidate_id is null or v_fvr is null or c.active is not true
  or v_target is null or v_target not in ('PAYE','UMBRELLA')
  or (v_target='UMBRELLA' and (u.id is null or u.enabled is not true or u.vat_chargeable is null))
  or w.approval_state is distinct from 'APPROVED' or w.current_revision_id is distinct from r.id
  or w.applied_revision_id is distinct from r.id or pos.applied_revision_id is distinct from r.id
  or r.approved_at_utc is null or r.sealed_at_utc is null or a.tax_treatment is distinct from 'TAXABLE'
  or pos.approved_source_ex_vat is distinct from a.source_pay_ex_vat
  or g.group_kind is distinct from 'WORK' or g.candidate_id is distinct from c.id
  or g.current_revision_id is distinct from r.id or g.target_pay_channel is distinct from v_target
  or g.source_pay_channel is distinct from r.source_pay_channel or g.complete is not true or g.dirty is not false
  or g.progress_state is distinct from 'CURRENT' or g.financial_view_revision is distinct from v_fvr
  or g.metadata_version is distinct from md.metadata_version
  or (not p_projection_refresh and (md.continuation_pending is not false
    or md.adopted_metadata_version is distinct from md.metadata_version))
  or v_date->>'ok' is distinct from 'true' or (v_date->>'current_official_pay_date')::date is distinct from p_pay_date then
  raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_POSITION_INCOMPATIBLE';end if;
 -- Physical inputs are bounded before filtering any eligibility or selected rows.
 with native as materialized(select x.* from private.bpay_next_approved_segment x
   where x.revision_id=r.id and x.component_key=a.component_key order by x.segment_key limit 10001)
 select count(*),coalesce(sum(case when pay_excluded then 0 else approved_source_ex_vat end),0),
  coalesce(bool_or(approved_line_id is distinct from a.id),false)
 into v_approval_count,v_approval_a,v_bad from native;
 if v_approval_count>10000 then raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
 if v_bad then raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_POSITION_INCOMPATIBLE';end if;
 with native as materialized(select x.* from private.bpay_next_workbench_item x
   where x.work_id=w.id and x.component_key=a.component_key order by x.segment_key,x.portion_kind,x.id limit 50001)
 select count(*),coalesce(bool_or(group_key is distinct from g.group_key or candidate_id is distinct from c.id
   or revision_id is distinct from r.id or approved_line_id is distinct from a.id
   or member_kind not in ('WORK_COMPONENT','WORK_SEGMENT') or amount_known is not true or progress_state is distinct from 'CURRENT'
   or financial_view_revision is distinct from v_fvr or projection_revision is distinct from g.projection_revision
   or metadata_version is distinct from md.metadata_version or source_pay_channel is distinct from r.source_pay_channel
   or target_pay_channel is distinct from v_target),false),coalesce(bool_or(member_kind='WORK_SEGMENT'),false)
 into v_count,v_bad,v_segmented from native;
 if v_count>50000 then raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
 v_segmented:=v_segmented or v_approval_count>0;
 if v_bad or (v_segmented and v_approval_a is distinct from pos.approved_source_ex_vat)
  or exists(select 1 from private.bpay_next_workbench_item x where x.work_id=w.id and x.component_key=a.component_key
    and x.member_kind is distinct from case when v_segmented then 'WORK_SEGMENT' else 'WORK_COMPONENT' end) then
  raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_POSITION_INCOMPATIBLE';end if;
 -- Exact native READY keys only. Need checks precede the no-saved-decision return.
 v_selected_count:=0;
 for leaf in select i.* from private.bpay_next_workbench_item i where i.work_id=w.id and i.component_key=a.component_key
   and ('WORK:'||w.id::text||':'||i.component_key||':'||i.member_kind||':'||i.member_key)=any(p_selected_leaf_keys)
   and i.portion_kind in ('AVAILABLE','ZERO') order by i.member_key loop
  v_selected_count:=v_selected_count+1;
  if iSfinite(p_pay_date) is not true or leaf.section is distinct from 'READY' or leaf.selectable is not true
   or leaf.is_selected is not false or leaf.amount_known is not true or leaf.direction is distinct from 'PAYMENT'
   or coalesce(leaf.pay_hold,false) or leaf.snooze_id is not null
   or (v_segmented and not exists(select 1 from private.bpay_next_approved_segment s where s.id=leaf.approved_segment_id
     and s.revision_id=r.id and s.approved_line_id=a.id and s.component_key=a.component_key and s.segment_key=leaf.segment_key
     and not s.pay_excluded)) then
   raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_POSITION_INCOMPATIBLE';end if;
  if leaf.included_source_ex_vat>0 and private.bpay_next_component_resolution_need_v1(w.id,r.id,a.id,
    leaf.approved_segment_id,v_target,v_umbrella,v_vat,p_pay_date) is not null then
   raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_SOURCE_BASIS_UNAVAILABLE';end if;
 end loop;
 if v_selected_count<>cardinality(p_selected_leaf_keys) then
  raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_POSITION_INCOMPATIBLE';end if;
 -- Complete native A/R/H coverage: all portions plus exhausted current approvals.
 with portions as materialized(select i.segment_key,count(*) n,
   sum(i.approved_source_ex_vat) a,sum(i.realised_source_ex_vat) r,sum(i.active_reserved_source_ex_vat) h,
   sum(i.residual_source_ex_vat) residual,sum(i.included_source_ex_vat+i.excluded_source_ex_vat) positive,
   sum(i.recovery_source_ex_vat) recovery,sum(i.held_overhang_source_ex_vat) overhang,
   sum(case when ('WORK:'||w.id::text||':'||i.component_key||':'||i.member_kind||':'||i.member_key)=any(p_selected_leaf_keys)
     and i.portion_kind='AVAILABLE' then i.included_source_ex_vat else 0 end) included
   from private.bpay_next_workbench_item i where i.work_id=w.id and i.component_key=a.component_key group by i.segment_key),
 native as materialized(select s.* from private.bpay_next_approved_segment s
   where s.revision_id=r.id and s.component_key=a.component_key),
 keys as materialized(select segment_key from portions union select segment_key from native)
 select count(*) into v_count from (select segment_key from keys limit 10001) bounded;
 if v_count>10000 then raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
 for v_member in
  with portions as materialized(select i.segment_key,count(*) n,
    sum(i.approved_source_ex_vat) a,sum(i.realised_source_ex_vat) r,sum(i.active_reserved_source_ex_vat) h,
    sum(i.residual_source_ex_vat) residual,sum(i.included_source_ex_vat+i.excluded_source_ex_vat) positive,
    sum(i.recovery_source_ex_vat) recovery,sum(i.held_overhang_source_ex_vat) overhang,
    sum(case when ('WORK:'||w.id::text||':'||i.component_key||':'||i.member_kind||':'||i.member_key)=any(p_selected_leaf_keys)
      and i.portion_kind='AVAILABLE' then i.included_source_ex_vat else 0 end) included
    from private.bpay_next_workbench_item i where i.work_id=w.id and i.component_key=a.component_key group by i.segment_key),
  native as materialized(select s.* from private.bpay_next_approved_segment s
    where s.revision_id=r.id and s.component_key=a.component_key),
  keys as materialized(select segment_key from portions union select segment_key from native)
  select jsonb_build_object('segment_key',k.segment_key,'approved_segment_id',s.id,
    'approved_source_ex_vat',case when p.n is null then case when s.pay_excluded then 0 else s.approved_source_ex_vat end else p.a end,
    'realised_source_ex_vat',case when p.n is null then case when s.pay_excluded then 0 else s.approved_source_ex_vat end else p.r end,
    'held_source_ex_vat',coalesce(p.h,0),'included_source_ex_vat',coalesce(p.included,0),
    'excluded_source_ex_vat',coalesce(p.positive-p.included,0),'recovery_source_ex_vat',coalesce(p.recovery,0),
    'held_overhang_source_ex_vat',coalesce(p.overhang,0),'native_source_ex_vat',case when s.pay_excluded then 0 else s.approved_source_ex_vat end,
    'projected_residual',coalesce(p.residual,0),
    'hours',jsonb_build_array(s.hours_day,s.hours_night,s.hours_sat,s.hours_sun,s.hours_bh),
    'rates',jsonb_build_array(s.pay_day,s.pay_night,s.pay_sat,s.pay_sun,s.pay_bh))
  from keys k left join portions p on p.segment_key is not distinct from k.segment_key
   left join native s on s.segment_key=k.segment_key order by k.segment_key nulls first
 loop
  if ((v_member->>'approved_segment_id') is not null
      and (v_member->>'approved_source_ex_vat')::numeric is distinct from (v_member->>'native_source_ex_vat')::numeric)
   or (v_segmented and v_member->>'approved_segment_id' is null and (v_member->>'approved_source_ex_vat')::numeric<>0)
   or (v_member->>'approved_source_ex_vat')::numeric-(v_member->>'realised_source_ex_vat')::numeric
      -(v_member->>'held_source_ex_vat')::numeric is distinct from (v_member->>'projected_residual')::numeric
   or (v_member->>'included_source_ex_vat')::numeric+(v_member->>'excluded_source_ex_vat')::numeric
      -(v_member->>'recovery_source_ex_vat')::numeric-(v_member->>'held_overhang_source_ex_vat')::numeric
      is distinct from (v_member->>'projected_residual')::numeric then
   raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_POSITION_INCOMPATIBLE';end if;
  v_a:=v_a+(v_member->>'approved_source_ex_vat')::numeric;v_r:=v_r+(v_member->>'realised_source_ex_vat')::numeric;
  v_h:=v_h+(v_member->>'held_source_ex_vat')::numeric;v_included:=v_included+(v_member->>'included_source_ex_vat')::numeric;
  v_excluded:=v_excluded+(v_member->>'excluded_source_ex_vat')::numeric;v_recovery:=v_recovery+(v_member->>'recovery_source_ex_vat')::numeric;
  v_overhang:=v_overhang+(v_member->>'held_overhang_source_ex_vat')::numeric;
  v_bytes:=v_bytes+octet_length(v_member::text)+2;
  if v_bytes>8388608 then raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
  if v_segmented then v_members:=array_append(v_members,v_member);end if;
 end loop;
 if (v_a,v_r,v_h) is distinct from (pos.approved_source_ex_vat,pos.realised_source_ex_vat,pos.held_source_ex_vat)
  or v_a-v_r-v_h is distinct from v_included+v_excluded-v_recovery-v_overhang then
  raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_POSITION_INCOMPATIBLE';end if;
 -- Same101 physical mapped-boundary discovery as the accepted owner, without a Run.
 for d in select x.* from private.bpay_next_component_resolution x where x.work_id=w.id and x.state='ACTIVE'
   and (x.based_on_revision_id=r.id or x.published_revision_id=r.id)
   and (case when x.based_on_revision_id=r.id then x.approved_line_id else x.published_line_id end)=a.id
   order by case when x.based_on_revision_id=r.id then x.approved_line_id else x.published_line_id end,
     x.rate_family,x.rate_code,x.id limit 101 loop
  v_seen:=v_seen+1;
  if v_seen>100 then raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
  v_line:=case when d.based_on_revision_id=r.id then d.approved_line_id else d.published_line_id end;
  if v_line is distinct from a.id or (d.candidate_id,d.target_pay_channel,d.target_umbrella_id,d.target_umbrella_vat_chargeable,
    d.valuation_policy_id,d.valuation_date) is distinct from(c.id,v_target,v_umbrella,v_vat,r.valuation_policy_id,p_pay_date) then continue;end if;
  select x.* into active from private.bpay_next_component_resolution_active_v1(w.id,r.id,a.id,d.rate_family,d.rate_code,
    v_target,v_umbrella,v_vat,r.valuation_policy_id,p_pay_date) x;
  if active.id is distinct from d.id or active.decision_version is distinct from d.decision_version then
   raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_BASIS_CHANGED';end if;
  v_key:=jsonb_build_array(d.rate_family,d.rate_code)::text;
  if v_key=any(v_decision_keys) then raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_COMPATIBILITY_AMBIGUOUS';end if;
  v_decision_keys:=array_append(v_decision_keys,v_key);
  if cardinality(v_decision_keys)>5 then raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_BUCKET_MISSING';end if;
  if first_d.id is null then first_d:=d;end if;
  v_refs:=v_refs||jsonb_build_array(jsonb_build_object('approved_line_id',a.id,'rate_family',d.rate_family,
    'rate_code',d.rate_code,'decision_id',d.id,'decision_version',d.decision_version::text));
  select x.xmin::text into v_native_version from private.bpay_next_component_resolution x where x.id=d.id;
  v_versions:=v_versions||jsonb_build_array(jsonb_build_array('RATE_DECISION',d.id::text,d.decision_version::text,v_native_version));
 end loop;
 if first_d.id is null then return null;end if;
 v_basis:=jsonb_build_object('approved_source_ex_vat',v_a,'realised_source_ex_vat',v_r,
   'held_source_ex_vat',v_h,'source_basis_channel',pos.source_basis_channel);
 v_required_included:=v_included;
 if p_through_segment_key is not null then
  if not v_segmented or not exists(select 1 from unnest(v_members) x where x->>'segment_key'=p_through_segment_key
    and (x->>'included_source_ex_vat')::numeric>0 and x->>'approved_segment_id' is not null) then
   raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_POSITION_INCOMPATIBLE';end if;
  select jsonb_build_object('approved_source_ex_vat',sum((x->>'approved_source_ex_vat')::numeric),
    'realised_source_ex_vat',sum((x->>'realised_source_ex_vat')::numeric),'held_source_ex_vat',sum((x->>'held_source_ex_vat')::numeric),
    'source_basis_channel',pos.source_basis_channel),sum((x->>'included_source_ex_vat')::numeric)
   into v_basis,v_required_included from unnest(v_members) x where x->>'segment_key'<=p_through_segment_key;
 end if;
 v_working:=jsonb_build_object('work_id',w.id,'revision_id',r.id,'approved_line_id',a.id,'pay_date',p_pay_date,
  'valuation_policy_id',r.valuation_policy_id,'refs',v_refs,'members',to_jsonb(v_members),
  'included_source_ex_vat',v_included,'current_decision_versions',v_versions);
 if octet_length(v_working::text)>8388608 then raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
 v_result:=private.bpay_next_component_resolution_input_quote_v1(first_d,r.id,v_basis,v_required_included,null,p_through_segment_key,v_working);
 return v_result;
end
$function$;

create or replace function private.bpay_next_current_component_resolution_quote_v1(
 p_work_id uuid,p_revision_id uuid,p_approved_line_id uuid,p_pay_date date,
 p_selected_leaf_keys text[],p_through_segment_key text default null
) returns jsonb language sql stable security invoker set search_path=pg_catalog,private
as $function$
 select private.bpay_next_current_component_resolution_quote_v1(
  p_work_id,p_revision_id,p_approved_line_id,p_pay_date,p_selected_leaf_keys,p_through_segment_key,false)
$function$;

create or replace function private.bpay_next_workbench_refresh_group_display_v1(p_group_key text)
returns void language plpgsql security definer set search_path=pg_catalog,private,public
as $function$
declare
 g private.bpay_next_workbench_group%rowtype;w private.bpay_next_work%rowtype;
 r private.bpay_next_work_revision%rowtype;c public.candidates%rowtype;u public.umbrellas%rowtype;
 v_date_context jsonb;v_pay_date date;v_sensitive boolean:=false;v_component record;
 v_keys text[];v_source numeric;v_quote jsonb;v_delta numeric:=0;
begin
  perform private.bpay_next_workbench_require_next_v1();
  if p_group_key is null then raise exception using errcode='22023',message='BPAY_NEXT_WORKBENCH_GROUP_INVALID';end if;
  select x.* into g from private.bpay_next_workbench_group x where x.group_key=p_group_key;
  -- Native projection owners hold Candidate then Work and prove Source A/R/H
  -- before this display-only replacement. No summary/delta money changes.
  if g.group_kind='WORK' and g.complete and not g.dirty and g.progress_state='CURRENT' then
    select x.* into strict w from private.bpay_next_work x where x.id=g.work_id;
    select x.* into strict r from private.bpay_next_work_revision x where x.id=g.current_revision_id and x.work_id=w.id;
    select x.* into strict c from public.candidates x where x.id=g.candidate_id;
    select x.* into u from public.umbrellas x where x.id=c.umbrella_id;
    v_date_context:=public.pay_banking_official_date_context_v1(null::timestamptz);
    if v_date_context->>'ok' is distinct from 'true' or v_date_context->>'current_official_pay_date' is null then
      raise exception using errcode='55000',message='BPAY_NEXT_WORKBENCH_DATE_UNAVAILABLE';end if;
    v_pay_date:=(v_date_context->>'current_official_pay_date')::date;
    -- EXISTS uses native Work/revision mappings. It cannot cap the complete
    -- number of components or mistake an incompatible older date for timeless.
    v_sensitive:=exists(select 1 from private.bpay_next_component_resolution d where d.work_id=w.id and d.state='ACTIVE'
      and (d.based_on_revision_id=r.id or d.published_revision_id=r.id));
    if not v_sensitive then
      v_sensitive:=exists(select 1 from (select distinct i.approved_line_id,i.approved_segment_id
        from private.bpay_next_workbench_item i where i.group_key=g.group_key and i.revision_id=r.id
          and i.tax_treatment='TAXABLE' and i.section in ('READY','ACTION')
          and i.approved_line_id is not null) native
        where private.bpay_next_component_resolution_need_v1(w.id,r.id,native.approved_line_id,native.approved_segment_id,
          g.target_pay_channel,case when g.target_pay_channel='UMBRELLA' then u.id end,
          case when g.target_pay_channel='UMBRELLA' then u.vat_chargeable end,null::date) is not null);
    end if;
    for v_component in select distinct i.approved_line_id,i.component_key
      from private.bpay_next_workbench_item i where i.group_key=g.group_key and i.revision_id=r.id
        and i.tax_treatment='TAXABLE' and i.section='READY' and i.selectable and i.amount_known and not i.is_selected
        and i.direction='PAYMENT' and i.portion_kind in ('AVAILABLE','ZERO')
        and exists(select 1 from private.bpay_next_component_resolution d where d.work_id=w.id and d.state='ACTIVE'
          and (d.based_on_revision_id=r.id or d.published_revision_id=r.id)
          and (case when d.based_on_revision_id=r.id then d.approved_line_id else d.published_line_id end)=i.approved_line_id)
      order by i.component_key,i.approved_line_id loop
      with native as materialized(select i.* from private.bpay_next_workbench_item i
        where i.group_key=g.group_key and i.revision_id=r.id and i.approved_line_id=v_component.approved_line_id
          and i.component_key=v_component.component_key and i.section='READY' and i.selectable and i.amount_known
          and not i.is_selected and i.direction='PAYMENT' and i.portion_kind in ('AVAILABLE','ZERO')
        order by i.member_kind,i.member_key,i.id limit 10001)
      select array_agg('WORK:'||w.id::text||':'||i.component_key||':'||i.member_kind||':'||i.member_key
        order by i.member_kind,i.member_key,i.id),sum(i.included_source_ex_vat)
        into v_keys,v_source from native i;
      if cardinality(v_keys)>10000 then
        raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
      v_quote:=private.bpay_next_current_component_resolution_quote_v1(w.id,r.id,v_component.approved_line_id,
        v_pay_date,v_keys,null,true);
      if v_quote is not null then
        if jsonb_typeof(v_quote->'component_quote') is distinct from 'object'
          or v_quote->'component_quote'->>'ex' is null then
          raise exception using errcode='23514',message='BPAY_NEXT_RESOLUTION_POSITION_INCOMPATIBLE';end if;
        v_delta:=v_delta+(v_quote->'component_quote'->>'ex')::numeric-v_source;
      end if;
    end loop;
  end if;
  delete from private.bpay_next_workbench_group_display where parent_group_key=p_group_key;
-- WB15 own-list display projection. Values never enter a financial command.
insert into private.bpay_next_workbench_group_display(
  presentation_key,presentation_kind,presentation_id,parent_group_key,candidate_id,case_component_id,
  section,client_id,week_ending_date,client_display_name,payment_label,timesheet_reference,
  target_pay_channel,has_deduction,selectable,reason_code,reason_priority,group_amount,ready_net_add_amount,
  gross_deduction_balance,net_deduction_balance,waiting_amount,waiting_net_add_amount,
  accepted_run_id,accepted_command_id,accepted_module_epoch,snooze_until_date,eligible_from_date,pay_hold_reason
)
with members as (
  select g.group_key parent_group_key,g.candidate_id,g.client_id,g.week_ending_date,g.target_pay_channel,g.certified_zero,
    case when g.group_kind='WORK' then 'WORK' when fc.case_kind='OVERPAYMENT' or i.case_component_id is null then 'CASE' else 'ROW' end presentation_kind,
    case when g.group_kind='WORK' then g.work_id when fc.case_kind='OVERPAYMENT' or i.case_component_id is null then g.case_id else i.case_component_id end presentation_id,
    case when g.group_kind='CASE' and fc.case_kind<>'OVERPAYMENT' then i.case_component_id end case_component_id,
    case when g.group_kind='WORK' then i.client_display_name else cl.name end client_display_name,
    case when g.group_kind='WORK' then 'Timesheet' when fc.case_kind='OVERPAYMENT' then 'Overpayment recovery'
      when cc.case_subtype in ('LOAN','PAYMENT_ADVANCE') then case when cc.direction='DEDUCTION' then 'Payment Advance repayment' else 'Payment Advance' end
      when cc.case_subtype='MANUAL_CREDIT' then 'Manual Credit' when cc.case_subtype='UNDERPAYMENT' then 'Underpayment'
      when cc.case_subtype='MANUAL_DEBT' then 'Manual Debt' else 'Payment needs attention' end payment_label,
    i.id,i.section item_section,i.direction,i.payroll_stage,i.portion_kind,i.member_kind,i.reason_code,i.reason_priority,
    i.is_selected,i.selectable,i.amount_known,i.selected_amount_known,i.timesheet_reference,i.included_source_ex_vat,
    i.gross_due_source_ex_vat,i.nominal_source_ex_vat,i.deduction_balance_source_ex_vat,
    i.active_reserved_source_ex_vat,i.selected_source_ex_vat,i.accepted_run_id,i.accepted_command_id,i.accepted_module_epoch,
    i.snooze_until_date,i.eligible_from_date,i.pay_hold_reason,
    (i.reason_code='MANUAL_COLLECTION_UNAVAILABLE' or not i.amount_known and not(g.certified_zero and i.member_kind='GROUP_EVIDENCE')
      or i.is_selected and not i.selected_amount_known) amount_unavailable,
    case when i.is_selected then i.selected_source_ex_vat
      when i.portion_kind='RESERVED' then i.active_reserved_source_ex_vat
      when i.direction='PAYMENT' and i.section='READY' then i.included_source_ex_vat
      when i.direction='PAYMENT' and i.section='WAITING' and i.payroll_stage='GROSS_ADD' then i.gross_due_source_ex_vat
      else i.nominal_source_ex_vat end display_value,
    case when i.is_selected and i.accepted_run_id is not null and i.accepted_command_id is not null and i.accepted_module_epoch is not null
      and exists(select 1 from private.bpay_next_run_command rc join private.bpay_next_command cmd on cmd.id=rc.command_id
        join private.bpay_next_pay_run pr on pr.id=rc.run_id where rc.run_id=i.accepted_run_id and rc.command_id=i.accepted_command_id
          and cmd.command_kind='PREPARE' and cmd.module_epoch=i.accepted_module_epoch and pr.selection_state='SEALED'
          and pr.status in ('PREPARING','REVIEW','DRAFT','EXECUTING'))
      then pg_catalog.jsonb_build_array(i.accepted_run_id::text,i.accepted_command_id::text,i.accepted_module_epoch::text) end accepted_pair
  from private.bpay_next_workbench_group g join private.bpay_next_workbench_item i on i.group_key=g.group_key
  left join private.bpay_next_finance_case fc on fc.id=g.case_id
  left join private.bpay_next_case_component cc on cc.id=i.case_component_id and cc.case_id=g.case_id
  left join public.clients cl on cl.id=g.client_id
  where g.group_key=p_group_key
), scoped as (
  select m.*,sec.section from members m cross join lateral(values(m.item_section),('ALL'::text)) sec(section)
), reduced as (
  select presentation_kind,presentation_id,parent_group_key,candidate_id,case_component_id,section,client_id,week_ending_date,target_pay_channel,
    min(client_display_name::text) client_display_name,min(payment_label::text) payment_label,min(timesheet_reference::text) timesheet_reference,
    bool_or(direction='DEDUCTION') has_deduction,bool_or(selectable) selectable,
    (array_agg(reason_code order by reason_priority,id))[1] reason_code,min(reason_priority::smallint) reason_priority,
    bool_or(amount_unavailable) amount_unavailable,
    coalesce(sum(case when direction='DEDUCTION' then -display_value when direction='PAYMENT' then display_value when reason_code='MANUAL_COLLECTION' and direction='INFORMATIONAL' then display_value else 0 end),0) group_amount,
    coalesce(sum(included_source_ex_vat) filter(where item_section='READY' and direction='PAYMENT' and payroll_stage='NET_ADD'),0) ready_net_add_amount,
    coalesce(sum(deduction_balance_source_ex_vat) filter(where direction='DEDUCTION' and payroll_stage='GROSS_DEDUCT'),0) gross_deduction_balance,
    coalesce(sum(deduction_balance_source_ex_vat) filter(where direction='DEDUCTION' and payroll_stage='NET_DEDUCT'),0) net_deduction_balance,
    coalesce(sum(gross_due_source_ex_vat) filter(where item_section='WAITING' and direction='PAYMENT' and payroll_stage='GROSS_ADD' and portion_kind<>'RESERVED'),0) waiting_amount,
    coalesce(sum(nominal_source_ex_vat) filter(where item_section='WAITING' and direction='PAYMENT' and payroll_stage='NET_ADD' and portion_kind<>'RESERVED'),0) waiting_net_add_amount,
    array_agg(distinct accepted_pair) filter(where accepted_pair is not null) accepted_pairs,
    min(snooze_until_date::date) snooze_until_date,min(eligible_from_date::date) eligible_from_date,min(pay_hold_reason::text) pay_hold_reason
  from scoped group by presentation_kind,presentation_id,parent_group_key,candidate_id,case_component_id,section,client_id,week_ending_date,target_pay_channel
)
select presentation_kind||':'||presentation_id::text,presentation_kind,presentation_id,parent_group_key,candidate_id,case_component_id,
  section,client_id,week_ending_date,client_display_name,payment_label,timesheet_reference,
  target_pay_channel,has_deduction,selectable,reason_code,reason_priority,
  case when not amount_unavailable then group_amount end,case when not amount_unavailable then ready_net_add_amount end,
  case when not amount_unavailable then gross_deduction_balance end,case when not amount_unavailable then net_deduction_balance end,
  case when not amount_unavailable then waiting_amount end,case when not amount_unavailable then waiting_net_add_amount end,
  case when cardinality(accepted_pairs)=1 then (accepted_pairs[1]->>0)::uuid end,
  case when cardinality(accepted_pairs)=1 then (accepted_pairs[1]->>1)::uuid end,
  case when cardinality(accepted_pairs)=1 then (accepted_pairs[1]->>2)::bigint end,
  snooze_until_date,eligible_from_date,pay_hold_reason
from reduced;
  if g.group_kind='WORK' and g.complete and not g.dirty and g.progress_state='CURRENT' then
    update private.bpay_next_workbench_group_display set group_amount=group_amount+v_delta
      where parent_group_key=p_group_key and presentation_kind='WORK' and section='READY' and group_amount is not null;
    -- Certification follows the complete replacement, never partial paging.
    update private.bpay_next_workbench_group set chosen_display_date_sensitive=v_sensitive,
      chosen_display_pay_date=case when v_sensitive then v_pay_date end where group_key=p_group_key;
  end if;
end
$function$;

alter function private.bpay_next_current_component_resolution_quote_v1(uuid,uuid,uuid,date,text[],text,boolean) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_current_component_resolution_quote_v1(uuid,uuid,uuid,date,text[],text,boolean) from public,anon,authenticated,service_role;
alter function private.bpay_next_current_component_resolution_quote_v1(uuid,uuid,uuid,date,text[],text) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_current_component_resolution_quote_v1(uuid,uuid,uuid,date,text[],text) from public,anon,authenticated,service_role;
alter function private.bpay_next_workbench_refresh_group_display_v1(text) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_workbench_refresh_group_display_v1(text) from public,anon,authenticated,service_role;


-- CONTACT_PREPARER_UNIT 88 repeatable supabase/repeatable/13102026_0721_banking_pay_next_frozen_decisions_clear_v1.sql SHA256 d9228c918e2ff5806b69cdb4549549dbf4a601ff2cd5296126ebf8eec722a41c
-- WB28/BD175: precise frozen future clear and actor defaults.



-- WB28/BD175: immutable unit defaults, no accepted-record deletion.
create or replace function private.bpay_next_selection_remembered_unit_v1(p_leaves bigint,p_recorded bigint,p_low boolean,p_high boolean)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog,private
as $function$
begin
 if p_recorded=0 then return null;end if;
 if p_leaves<>p_recorded or p_low is null or p_high is null or p_low<>p_high then
  raise exception using errcode='23514',message='BPAY_NEXT_SELECTION_MEMORY_UNIT_MISSING';end if;
 return p_low;
end
$function$;
create or replace function private.bpay_next_selection_reset_matches_v1(p_baseline uuid,p_candidate uuid,p_work uuid,p_revision uuid,p_line uuid,p_case uuid)
returns boolean language sql stable security invoker set search_path=pg_catalog,private
as $function$
 select exists(select 1 from private.bpay_next_selection_mode_memory h
  join private.bpay_next_decisions_clear_operation o on o.agency_id=h.agency_id and o.owner_epoch=h.owner_epoch
   and o.actor_user_id=h.actor_user_id and o.official_pay_date=h.official_pay_date
   and o.reset_sequence>h.agency_sequence
  where h.run_id=p_baseline and h.row_kind='HEADER' and h.acknowledged_at_utc is not null
   and(o.scope->>'candidate_id' is null or o.scope->>'candidate_id'=p_candidate::text)
   and exists(select 1 from private.bpay_next_workbench_item i where i.candidate_id=p_candidate
    and i.work_id is not distinct from p_work and i.revision_id is not distinct from p_revision
    and i.approved_line_id is not distinct from p_line and i.case_component_id is not distinct from p_case
    and i.section='READY' and i.selectable and i.amount_known and not i.is_selected
    and i.portion_kind in('AVAILABLE','ZERO') and i.progress_state='CURRENT'
    and(o.scope->>'client_id' is null or o.scope->>'client_id'=i.client_id::text)
    and(o.scope->>'channel'='ALL' or o.scope->>'channel'=i.target_pay_channel)))
$function$;

create or replace function private.bpay_next_selection_memory_choices_v1(p_scope jsonb,p_baseline uuid,p_intent jsonb)
returns table(leaf_key text,candidate_id uuid,work_id uuid,revision_id uuid,approved_line_id uuid,case_component_id uuid,direction text,basis jsonb,selected boolean,new_changed boolean)
language sql stable security invoker set search_path=pg_catalog,private
as $function$
 with current_leaves as materialized(select * from private.bpay_next_selection_memory_leaves_v1(p_scope)),
 unit_facts as (select l.candidate_id,l.work_id,l.revision_id,l.approved_line_id,l.case_component_id,l.direction,
  case when l.work_id is not null then 'WORK:'||l.work_id::text||':'||(l.basis->>'component_key') else 'CASE:'||l.case_component_id::text end unit_key,
  bool_or(b.basis is distinct from l.basis) or
   exists(select 1 from private.bpay_next_selection_mode_memory prior where prior.run_id=p_baseline and prior.row_kind='LEAF'
    and prior.candidate_id=l.candidate_id and (prior.work_id=l.work_id and prior.approved_line_id=l.approved_line_id or prior.case_component_id=l.case_component_id)
    and not exists(select 1 from current_leaves now_leaf where now_leaf.leaf_key=prior.leaf_key and now_leaf.basis=prior.basis)) changed,
  count(*) leaf_count,count(b.remembered_selected) remembered_count,
  bool_and(b.remembered_selected) remembered_min,bool_or(b.remembered_selected) remembered_max
 from current_leaves l left join private.bpay_next_selection_mode_memory b on b.run_id=p_baseline and b.row_kind='LEAF' and b.leaf_key=l.leaf_key
 group by l.candidate_id,l.work_id,l.revision_id,l.approved_line_id,l.case_component_id,l.direction,l.basis->>'component_key'),
 units as (select u.*,case when u.changed then null else
  private.bpay_next_selection_remembered_unit_v1(u.leaf_count,u.remembered_count,u.remembered_min,u.remembered_max) end remembered_selected from unit_facts u),
 defaults as (
 select l.*,'{}'::jsonb basis,
  case when p_baseline is null then coalesce(p_intent->>'mode','ALL_MATCHING')='ALL_MATCHING'
   when l.changed then true
   when private.bpay_next_selection_reset_matches_v1(p_baseline,l.candidate_id,l.work_id,l.revision_id,l.approved_line_id,l.case_component_id)
    then case when p_intent->>'mode'='NONE' and h.mode<>'NONE' then false else true end
   when l.remembered_selected is not null and(p_intent->>'mode' is null or p_intent->>'mode'=h.mode) then l.remembered_selected
   when coalesce(p_intent->>'mode',h.mode)='NONE' then false
   else not exists(select 1 from private.bpay_next_selection_exclusion_memory e
     join private.bpay_next_selection_mode_memory original on original.run_id=e.basis_ref_run_id
       and original.row_kind='LEAF' and original.candidate_id=l.candidate_id
       and (original.work_id=l.work_id and original.approved_line_id=l.approved_line_id or original.case_component_id=l.case_component_id)
     where e.run_id=p_baseline and not e.selected and e.candidate_id=l.candidate_id
      and not exists(select 1 from current_leaves current_leaf where current_leaf.candidate_id=l.candidate_id
       and (current_leaf.approved_line_id=l.approved_line_id or current_leaf.case_component_id=l.case_component_id)
       and not exists(select 1 from private.bpay_next_selection_mode_memory original_leaf where original_leaf.run_id=e.basis_ref_run_id
        and original_leaf.row_kind='LEAF' and original_leaf.leaf_key=current_leaf.leaf_key and original_leaf.basis=current_leaf.basis))
      and not exists(select 1 from private.bpay_next_selection_mode_memory original_leaf where original_leaf.run_id=e.basis_ref_run_id and original_leaf.row_kind='LEAF'
       and (original_leaf.approved_line_id=l.approved_line_id or original_leaf.case_component_id=l.case_component_id)
       and not exists(select 1 from current_leaves current_leaf where current_leaf.leaf_key=original_leaf.leaf_key and current_leaf.basis=original_leaf.basis))
      and (e.intent_kind='candidates' or e.intent_kind='works' and e.work_id=l.work_id
       or e.intent_kind='components' and e.approved_line_id=original.approved_line_id
       or e.intent_kind='cases' and e.case_component_id=l.case_component_id)) end default_selected
 from units l left join private.bpay_next_selection_mode_memory h on h.run_id=p_baseline and h.row_kind='HEADER'
 ), chosen as (
 select l.*,candidate.value candidate_choice,work.value work_choice,component.value component_choice,case_choice.value case_choice
 from defaults l
 left join lateral(select value from jsonb_array_elements(coalesce(p_intent->'candidates','[]'::jsonb)) where value->>'candidate_id'=l.candidate_id::text) candidate on true
 left join lateral(select value from jsonb_array_elements(coalesce(p_intent->'works','[]'::jsonb)) where value->>'work_id'=l.work_id::text) work on true
 left join lateral(select value from jsonb_array_elements(coalesce(p_intent->'components','[]'::jsonb)) where value->>'approved_line_id'=l.approved_line_id::text) component on true
 left join lateral(select value from jsonb_array_elements(coalesce(p_intent->'cases','[]'::jsonb)) where value->>'case_component_id'=l.case_component_id::text) case_choice on true
 ) select l.unit_key,l.candidate_id,l.work_id,l.revision_id,l.approved_line_id,l.case_component_id,l.direction,l.basis,
 case when l.candidate_choice->'selected'='false'::jsonb or l.work_choice->'selected'='false'::jsonb then false
  when l.case_component_id is not null then coalesce((l.case_choice->>'selected')::boolean,(l.candidate_choice->>'selected')::boolean,l.default_selected)
  when l.work_choice->>'mode'='SUBSET' and l.work_choice->'selected'='true'::jsonb then coalesce((l.component_choice->>'selected')::boolean,false)
  else coalesce((l.component_choice->>'selected')::boolean,
   case when l.work_choice->>'mode'='ALL' then (l.work_choice->>'selected')::boolean end,
   (l.candidate_choice->>'selected')::boolean,l.default_selected) end,
 p_baseline is not null and l.changed from chosen l;
$function$;


create or replace function private.bpay_next_selection_memory_capture_v1(p_run uuid,p_descriptor jsonb)
returns void language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_ns jsonb:=p_descriptor->'namespace';v_baseline uuid:=(p_descriptor->>'memory_baseline_run_id')::uuid;v_kind text;v_row jsonb;v_id uuid;v_leaf record;v_group text;v_next_group text;v_rows bigint:=0;v_bytes bigint:=0;v_encoded jsonb;
begin
 insert into private.bpay_next_selection_mode_memory(run_id,row_kind,leaf_key,agency_id,owner_epoch,actor_user_id,official_pay_date,scope,mode,intent_revision,baseline_run_id,basis,raw_intent,accepted_context)
 values(p_run,'HEADER','HEADER',(v_ns->>'agency_id')::uuid,(v_ns->>'owner_epoch')::bigint,(v_ns->>'actor_user_id')::uuid,(v_ns->>'official_pay_date')::date,v_ns->'scope',p_descriptor->'intent'->>'mode',(p_descriptor->>'revision')::bigint,v_baseline,'{}',p_descriptor->'intent',p_descriptor-'intent');
 -- Finite per-component proof, streamed without a global Draft cap.
 for v_leaf in with choices as materialized(
   select * from private.bpay_next_selection_memory_choices_v1(v_ns->'scope',v_baseline,p_descriptor->'intent'))
  select l.*,c.selected remembered_selected from private.bpay_next_selection_memory_leaves_v1(v_ns->'scope') l
  left join choices c on c.candidate_id=l.candidate_id and c.work_id is not distinct from l.work_id
   and c.revision_id is not distinct from l.revision_id and c.approved_line_id is not distinct from l.approved_line_id
   and c.case_component_id is not distinct from l.case_component_id and c.direction=l.direction
  order by l.candidate_id,l.work_id,l.approved_line_id,l.case_component_id,l.leaf_key loop
  if v_leaf.remembered_selected is null then
   raise exception using errcode='23514',message='BPAY_NEXT_SELECTION_MEMORY_UNIT_MISSING';end if;
  v_next_group:=jsonb_build_array(v_leaf.candidate_id,v_leaf.work_id,v_leaf.approved_line_id,v_leaf.case_component_id)::text;
  if v_group is distinct from v_next_group then v_group:=v_next_group;v_rows:=0;v_bytes:=0;end if;
  v_encoded:=jsonb_build_object('run_id',p_run,'row_kind','LEAF','leaf_key',v_leaf.leaf_key,
   'agency_id',v_ns->'agency_id','owner_epoch',v_ns->'owner_epoch','actor_user_id',v_ns->'actor_user_id',
   'official_pay_date',v_ns->'official_pay_date','scope',v_ns->'scope','mode',p_descriptor->'intent'->'mode',
   'intent_revision',p_descriptor->'revision','baseline_run_id',v_baseline,
   'candidate_id',v_leaf.candidate_id,'work_id',v_leaf.work_id,'approved_line_id',v_leaf.approved_line_id,
   'case_component_id',v_leaf.case_component_id,'basis',v_leaf.basis,'remembered_selected',v_leaf.remembered_selected);
  v_rows:=v_rows+1;v_bytes:=v_bytes+octet_length(v_encoded::text);
  if v_rows>10000 or v_bytes>8388608 then
   raise exception using errcode='54000',message='BPAY_NEXT_RESOLUTION_ACCEPTED_SCOPE_TOO_LARGE';end if;
  insert into private.bpay_next_selection_mode_memory(run_id,row_kind,leaf_key,agency_id,owner_epoch,actor_user_id,official_pay_date,scope,mode,intent_revision,baseline_run_id,candidate_id,work_id,approved_line_id,case_component_id,basis,remembered_selected)
  values(p_run,'LEAF',v_leaf.leaf_key,(v_ns->>'agency_id')::uuid,(v_ns->>'owner_epoch')::bigint,(v_ns->>'actor_user_id')::uuid,(v_ns->>'official_pay_date')::date,v_ns->'scope',p_descriptor->'intent'->>'mode',(p_descriptor->>'revision')::bigint,v_baseline,v_leaf.candidate_id,v_leaf.work_id,v_leaf.approved_line_id,v_leaf.case_component_id,v_leaf.basis,v_leaf.remembered_selected);
 end loop;
 -- Carry the original basis reference; never requalify inherited unticks.
 insert into private.bpay_next_selection_exclusion_memory
 select p_run,e.agency_id,e.owner_epoch,e.actor_user_id,e.official_pay_date,e.scope,e.intent_kind,e.native_id,e.candidate_id,e.work_id,e.expected_revision_id,e.approved_line_id,e.case_component_id,e.selected,e.basis_ref_run_id,e.intent_json,transaction_timestamp()
 from private.bpay_next_selection_exclusion_memory e where e.run_id=v_baseline
  and not exists(select 1 from jsonb_array_elements(p_descriptor->'intent'->e.intent_kind) raw
   where coalesce(raw->>'case_component_id',raw->>'approved_line_id',raw->>'work_id',raw->>'candidate_id')=e.native_id::text)
  and not exists(select 1 from jsonb_array_elements(p_descriptor->'intent'->'candidates') raw
   where raw->>'candidate_id'=e.candidate_id::text and raw->'selected'='true'::jsonb)
  and not (e.intent_kind='components' and exists(select 1 from jsonb_array_elements(p_descriptor->'intent'->'works') raw
   where raw->>'work_id'=e.work_id::text and raw->'selected'='true'::jsonb and raw->>'mode'='ALL'));
 foreach v_kind in array array['candidates','works','components','cases'] loop
  for v_row in select value from jsonb_array_elements(p_descriptor->'intent'->v_kind) loop
   v_id:=(coalesce(v_row->>'case_component_id',v_row->>'approved_line_id',v_row->>'work_id',v_row->>'candidate_id'))::uuid;
   insert into private.bpay_next_selection_exclusion_memory(run_id,agency_id,owner_epoch,actor_user_id,official_pay_date,scope,intent_kind,native_id,candidate_id,work_id,expected_revision_id,approved_line_id,case_component_id,selected,basis_ref_run_id,intent_json)
   values(p_run,(v_ns->>'agency_id')::uuid,(v_ns->>'owner_epoch')::bigint,(v_ns->>'actor_user_id')::uuid,(v_ns->>'official_pay_date')::date,v_ns->'scope',v_kind,v_id,(v_row->>'candidate_id')::uuid,(v_row->>'work_id')::uuid,(v_row->>'expected_revision_id')::uuid,(v_row->>'approved_line_id')::uuid,(v_row->>'case_component_id')::uuid,(v_row->>'selected')::boolean,p_run,v_row);
  end loop;
 end loop;
end
$function$;


alter function private.bpay_next_selection_remembered_unit_v1(bigint,bigint,boolean,boolean) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_selection_remembered_unit_v1(bigint,bigint,boolean,boolean) from public,anon,authenticated,service_role;
alter function private.bpay_next_selection_reset_matches_v1(uuid,uuid,uuid,uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_selection_reset_matches_v1(uuid,uuid,uuid,uuid,uuid,uuid) from public,anon,authenticated,service_role;
alter function private.bpay_next_selection_memory_choices_v1(jsonb,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_selection_memory_choices_v1(jsonb,uuid,jsonb) from public,anon,authenticated,service_role;
alter function private.bpay_next_selection_memory_capture_v1(uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_selection_memory_capture_v1(uuid,jsonb) from public,anon,authenticated,service_role;

-- WB28 bounded immutable disclosure over the frozen closure; never live rediscovery.
create or replace function private.bpay_next_decisions_clear_result_v1(p_request uuid,p_cursor jsonb default null)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,private
as $function$
declare o private.bpay_next_decisions_clear_operation%rowtype;v_rows jsonb:='[]';v_next jsonb;n record;v_count integer:=0;v_bytes integer:=0;v_value jsonb;
begin
 select x.* into strict o from private.bpay_next_decisions_clear_operation x where x.request_id=p_request;
 for n in with parents as materialized(
   select x.* from private.bpay_next_decisions_clear_member x where x.request_id=p_request
    and x.member_no>=coalesce((p_cursor->>'member_no')::bigint,1) order by x.member_no limit 11
  ) select m.member_no,ord.ordinality owner_no,m.work_id,m.candidate_id,m.owner_family,m.exclusion_code,m.subject,
   pg.outcome_code,pg.native_receipt is not null cleared,ord.value owner
  from parents m
  cross join lateral jsonb_array_elements(case when jsonb_array_length(m.owners)=0 then '[null]'::jsonb else m.owners end) with ordinality ord(value,ordinality)
  left join private.bpay_next_decisions_clear_page pg on pg.request_id=p_request and pg.phase='APPLY' and pg.step_no=m.member_no-1
  where(p_cursor is null or(m.member_no,ord.ordinality)>((p_cursor->>'member_no')::bigint,(p_cursor->>'owner_no')::bigint))
  order by m.member_no,ord.ordinality limit 11 loop
  if v_count=10 then v_next:=jsonb_build_object('member_no',(v_rows->(v_count-1)->>'member_no'),'owner_no',(v_rows->(v_count-1)->>'owner_no'));exit;end if;
  v_value:=jsonb_build_object('member_no',n.member_no::text,'owner_no',n.owner_no::text,'candidate_id',n.candidate_id,'work_id',n.work_id,
   'owner_family',n.owner_family,'exclusion_code',n.exclusion_code,'subject',n.subject,
   'outcome_code',n.outcome_code,'cleared',n.cleared and n.owner->>'clear_class'='RESOLVED_AND_CLEARABLE','owner',case when n.owner is null or n.owner='null'::jsonb then null else jsonb_build_object(
    'owner_id',n.owner->'owner_id','owner_version',n.owner->'owner_version','approved_line_id',n.owner->'approved_line_id',
    'rate_family',n.owner->'rate_family','rate_code',n.owner->'rate_code','amount_ex_vat',n.owner->'amount_ex_vat',
    'clear_class',n.owner->'clear_class','exclusion_code',n.owner->'exclusion_code','target_pay_channel',n.owner->'target_pay_channel',
    'resolution_mode',n.owner#>'{signature,resolution_mode}','manual_replacement_rate',n.owner#>'{signature,manual_replacement_rate}',
    'manual_amount_ex_vat',n.owner#>'{signature,manual_amount_ex_vat}') end);
  if v_bytes+octet_length(v_value::text)>110000 then
   if v_count=0 then raise exception using errcode='54000',message='BPAY_NEXT_DECISIONS_CLEAR_SCOPE_TOO_LARGE';end if;
   v_next:=jsonb_build_object('member_no',(v_rows->(v_count-1)->>'member_no'),'owner_no',(v_rows->(v_count-1)->>'owner_no'));exit;end if;
  v_bytes:=v_bytes+octet_length(v_value::text);
  v_rows:=v_rows||jsonb_build_array(v_value);v_count:=v_count+1;
 end loop;
 return jsonb_build_object('request_id',o.request_id,'agency_id',o.agency_id,'actor_user_id',o.actor_user_id,'owner_epoch',o.owner_epoch::text,
  'official_pay_date',o.official_pay_date::text,'scope',o.scope,'expected_workbench_revision',o.expected_workbench_revision::text,'state',o.state,
  'scope_summary',o.scope_summary,'candidate_count',o.candidate_count::text,'work_count',o.work_count::text,'owner_count',o.owner_count::text,'excluded_count',o.excluded_count::text,
  'affected_amount',o.affected_amount::text,'cleared_count',o.cleared_count::text,'refused_count',o.refused_count::text,'cleared_amount',o.cleared_amount::text,
  'freeze_step',o.freeze_step::text,'apply_step',o.apply_step::text,'reset_sequence',o.reset_sequence::text,'rows',v_rows,'next_cursor',v_next);
end
$function$;

create or replace function private.bpay_next_decisions_clear_command_v1(p_actor uuid,p_args jsonb,p_readback boolean)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,private,public
as $function$
declare
 o private.bpay_next_decisions_clear_operation%rowtype;pg private.bpay_next_decisions_clear_page%rowtype;
 m private.bpay_next_decisions_clear_member%rowtype;prev private.bpay_next_decisions_clear_page%rowtype;
 w private.bpay_next_work%rowtype;d private.bpay_next_component_resolution%rowtype;v_pair record;
 v_request uuid;v_phase text;v_step bigint;v_epoch bigint;v_header jsonb;v_scope jsonb;v_read jsonb;v_base jsonb;v_result jsonb;v_response jsonb;
 v_owners jsonb;v_rows jsonb;v_native jsonb;v_receipt jsonb;v_owner jsonb;v_current jsonb;v_carry jsonb;
 v_revision uuid;v_line uuid;v_effective uuid;v_effective_version bigint;v_subrequest uuid;v_code text;v_sequence bigint;v_count bigint;v_excluded bigint;
 v_sum numeric;v_clear_count bigint:=0;v_clear_sum numeric:=0;v_reason text;v_ready boolean;v_context jsonb;v_after jsonb;
 v_resolved boolean;v_member_count bigint;v_bytes bigint:=0;v_physical integer:=0;
 v_frozen boolean;v_facts jsonb;v_subject jsonb;v_one jsonb;i private.bpay_next_workbench_item%rowtype;r private.bpay_next_work_revision%rowtype;
 v_approval uuid;v_source_event uuid;v_after_book jsonb;v_book_after jsonb;v_compare jsonb;v_original jsonb;v_page_base jsonb;
 v_unsupported boolean;v_scope_channel text;
begin
 if p_readback is null or jsonb_typeof(p_args) is distinct from 'object' or octet_length(p_args::text)>4096
  or not(p_args?&array['request_id','scope','owner_epoch','official_pay_date','expected_workbench_revision','phase','step','cursor','confirmed'])
  or p_args-array['request_id','scope','owner_epoch','official_pay_date','expected_workbench_revision','phase','step','cursor','confirmed']<>'{}'::jsonb
  or jsonb_typeof(p_args->'request_id') is distinct from 'string' or p_args->>'request_id'!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or jsonb_typeof(p_args->'expected_workbench_revision') is distinct from 'string' or p_args->>'expected_workbench_revision'!~'^(0|[1-9][0-9]{0,18})$'
  or jsonb_typeof(p_args->'owner_epoch') is distinct from 'string' or p_args->>'owner_epoch'!~'^[1-9][0-9]{0,18}$'
  or (p_args->>'owner_epoch')::numeric>9223372036854775807
  or jsonb_typeof(p_args->'official_pay_date') is distinct from 'string' or p_args->>'official_pay_date'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  or (p_args->>'official_pay_date')::date::text is distinct from p_args->>'official_pay_date'
  or jsonb_typeof(p_args->'step') is distinct from 'string' or p_args->>'step'!~'^(0|[1-9][0-9]{0,18})$'
  or (p_args->>'expected_workbench_revision')::numeric>9223372036854775807 or (p_args->>'step')::numeric>9223372036854775807
  or jsonb_typeof(p_args->'phase') is distinct from 'string' or p_args->>'phase' not in('FREEZE','VIEW','APPLY')
  or jsonb_typeof(p_args->'confirmed') is distinct from 'boolean'
  or ((p_args->>'confirmed')::boolean is distinct from (p_args->>'phase'='APPLY')) then
  raise exception using errcode='22023',message='BPAY_NEXT_DECISIONS_CLEAR_REQUEST_INVALID';end if;
 v_scope:=p_args->'scope';
 if jsonb_typeof(v_scope) is distinct from 'object' or not(v_scope?&array['candidate_id','client_id','channel'])
  or v_scope-array['candidate_id','client_id','channel']<>'{}'::jsonb or jsonb_typeof(v_scope->'channel') is distinct from 'string'
  or v_scope->>'channel' not in('ALL','PAYE','UMBRELLA')
  or exists(select 1 from unnest(array['candidate_id','client_id']) k where jsonb_typeof(v_scope->k) not in('null','string')
   or(v_scope->k<>'null'::jsonb and v_scope->>k!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$')) then
  raise exception using errcode='22023',message='BPAY_NEXT_DECISIONS_CLEAR_REQUEST_INVALID';end if;
 if p_args->'cursor'<>'null'::jsonb and(p_args->>'phase'<>'VIEW' or jsonb_typeof(p_args->'cursor')<>'object'
  or not(p_args->'cursor'?&array['member_no','owner_no']) or(p_args->'cursor')-array['member_no','owner_no']<>'{}'::jsonb
  or (p_args->'cursor'->>'owner_no')::numeric>100
  or exists(select 1 from unnest(array['member_no','owner_no']) k where jsonb_typeof(p_args->'cursor'->k)<>'string'
