-- Repeatable CloudTMS function/view authority: healthroster_timesheet_correction_requests_v1
-- Use CREATE OR REPLACE and preserve owner, security, search_path, and ACL contracts.





create or replace function private.timesheet_correction_actor_allowed_v1(p_actor_user_id uuid)
returns boolean language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_allowed boolean:=false;
begin
  if p_actor_user_id is null or not exists(select 1 from public.tms_users u
    where u.id=p_actor_user_id and coalesce(u.is_active,false)) then return false; end if;
  if to_regprocedure('private.weekly_source_pay_actor_allowed_v1(uuid)') is null then return false; end if;
  execute 'select private.weekly_source_pay_actor_allowed_v1($1)' into v_allowed using p_actor_user_id;
  return v_allowed is true;
end;
$function$;

-- Preserve source terms and signature/business authority across later normal
-- authorisation and document bookkeeping. Unknown future fields stay frozen.
create or replace function private.timesheet_correction_timesheet_authority_hash_v1(p_timesheet jsonb)
returns text language sql immutable security definer
set search_path to 'pg_catalog','extensions','pg_temp'
as $function$
  select encode(extensions.digest((p_timesheet-array['authorised_at_server','updated_at',
    'document_revision','document_state','current_document_version_id','active_document_operation_id','last_document_error_json',
    'generated_pdf_at_utc','generated_pdf_refs_sig','generated_pdf_refs_snapshot_json','generated_pdf_refs_captured_at_utc'])::text,
    'sha256'),'hex');
$function$;

create or replace function private.timesheet_correction_actor_assert_v1(p_actor_user_id uuid)
returns void language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_allowed boolean:=false;
begin
  perform 1 from public.tms_users u where u.id=p_actor_user_id for share;
  if p_actor_user_id is null or not exists(select 1 from public.tms_users u
    where u.id=p_actor_user_id and coalesce(u.is_active,false)) then
    raise exception 'CORRECTION_ACTOR_NOT_ALLOWED' using errcode='42501';
  end if;
  if to_regprocedure('private.weekly_source_pay_actor_allowed_v1(uuid)') is null then
    raise exception 'CORRECTION_PAY_ACTOR_HELPER_UNAVAILABLE' using errcode='55000';
  end if;
  execute 'select private.weekly_source_pay_actor_allowed_v1($1)' into v_allowed using p_actor_user_id;
  if v_allowed is distinct from true then
    raise exception 'CORRECTION_ACTOR_NOT_ALLOWED' using errcode='42501';
  end if;
end;
$function$;

-- Economic source identity is separate from later authorisation, invoice
-- placement and cash/notice bookkeeping. All monetary/policy/component facts
-- and every undeclared future field remain fingerprinted.
create or replace function private.timesheet_correction_financial_authority_hash_v1(p_snapshot jsonb)
returns text language sql immutable security definer
set search_path to 'pg_catalog','extensions','pg_temp'
as $function$
  select encode(extensions.digest((
    (p_snapshot-array['is_current','is_stale','stale_reason','computed_at_utc','locked_by_invoice_id','locked_at_utc',
      'unlocked_by_credit_note_id','created_at','updated_at','processing_status','candidate_assignment','paid_at_utc',
      'paid_by_user_id','payment_reference','remittance_last_sent_at_utc','remittance_send_count','processed_by_user_id',
      'processed_at_utc','authorised_by_user_id','authorised_at_utc','pay_on_hold','pay_on_hold_reason','pay_on_hold_since_utc'])
      -array['hr_crosscheck_status','hr_crosscheck_issues','external_source_rows_json']
    ||jsonb_build_object('invoice_breakdown_json',case when jsonb_typeof(p_snapshot#>'{invoice_breakdown_json,segments}')='array'
      then jsonb_set(p_snapshot->'invoice_breakdown_json','{segments}',coalesce((select jsonb_agg(
        s.value-array['invoice_locked_invoice_id','invoice_locked_at_utc','pay_locked','pay_locked_at_utc'] order by s.ordinality)
        from jsonb_array_elements(p_snapshot#>'{invoice_breakdown_json,segments}') with ordinality s(value,ordinality)),'[]'::jsonb),true)
      else p_snapshot->'invoice_breakdown_json' end)
  )::text,'sha256'),'hex');
$function$;

create or replace function private.timesheet_correction_origin_v1(p_timesheet_id uuid)
returns text language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_agency boolean:=false;
  v_signed boolean:=false;
begin
  if to_regprocedure('private.weekly_source_agency_invoice_check_only_v1(uuid)') is not null then
    execute 'select private.weekly_source_agency_invoice_check_only_v1($1)' into v_agency using p_timesheet_id;
    if v_agency is true then return 'AGENCY_INVOICE_CORRECTION'; end if;
  end if;
  if to_regprocedure('private.weekly_source_signed_check_only_v1(uuid)') is not null then
    execute 'select private.weekly_source_signed_check_only_v1($1)' into v_signed using p_timesheet_id;
    if v_signed is true then return 'SIGNED_TIMESHEET_CORRECTION'; end if;
  end if;
  return null;
exception when sqlstate '55000' or sqlstate '22023' then return null;
end;
$function$;

-- Signature authority is the immutable approval/component pair, never Office
-- authorisation text, a worker signature alone, paper/manual key or QR field.
create or replace function private.timesheet_correction_signed_witness_v1(p_timesheet_id uuid,p_lock_rows boolean default false)
returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare
  v_ts public.timesheets%rowtype;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_approval public.candidate_approval_requests%rowtype;
  v_hours public.candidate_submission_components%rowtype;
  v_candidate public.candidate_submission_components%rowtype;
  v_manager public.candidate_submission_components%rowtype;
begin
  select t.* into v_ts from public.timesheets t where t.timesheet_id=p_timesheet_id;
  if v_ts.timesheet_id is null or v_ts.submission_mode::text<>'ELECTRONIC'
    or v_ts.candidate_workflow_id is null or v_ts.candidate_workflow_generation is null then
    raise exception 'CORRECTION_MANAGER_SIGNED_TIMESHEET_REQUIRED' using errcode='55000';
  end if;
  if p_lock_rows then
    perform 1 from public.candidate_submission_workflows w where w.id=v_ts.candidate_workflow_id for update;
    perform 1 from public.candidate_approval_requests a where a.workflow_id=v_ts.candidate_workflow_id
      order by a.id for update;
    perform 1 from public.candidate_submission_components c where c.workflow_id=v_ts.candidate_workflow_id
      and c.workflow_generation=v_ts.candidate_workflow_generation order by c.id for update;
  end if;
  select w.* into v_workflow from public.candidate_submission_workflows w
    where w.id=v_ts.candidate_workflow_id and w.generation=v_ts.candidate_workflow_generation
      and w.route in('EMAIL','PHONE') and w.state='FINALISED'
      and w.workflow_kind in('CONTRACT_HOURS','CONTRACT_COMBINED','DAILY')
      and w.manager_approved_at_utc is not null;
  if (select count(*) from public.candidate_approval_requests a
    where a.workflow_id=v_workflow.id and a.workflow_generation=v_workflow.generation and a.state='APPROVED')<>1
    or (select count(*) from public.candidate_submission_components c
      where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
        and c.component_kind='HOURS_TIMESHEET' and c.required and c.state='IMMUTABLE')<>1 then
    raise exception 'CORRECTION_MANAGER_SIGNATURE_WITNESS_AMBIGUOUS' using errcode='55000';
  end if;
  select a.* into v_approval from public.candidate_approval_requests a
    where a.workflow_id=v_workflow.id and a.workflow_generation=v_workflow.generation
      and a.state='APPROVED' order by a.id limit 1;
  select c.* into v_hours from public.candidate_submission_components c
    where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
      and c.component_kind='HOURS_TIMESHEET' and c.required and c.state='IMMUTABLE';
  select c.* into v_candidate from public.candidate_submission_components c
    where c.id=v_workflow.candidate_signature_component_id and c.workflow_id=v_workflow.id
      and c.workflow_generation=v_workflow.generation and c.document_role='CANDIDATE_SIGNATURE' and c.state='IMMUTABLE';
  select c.* into v_manager from public.candidate_submission_components c
    where c.id=v_workflow.manager_signature_component_id and c.workflow_id=v_workflow.id
      and c.workflow_generation=v_workflow.generation and c.document_role='MANAGER_SIGNATURE'
      and c.state='IMMUTABLE' and c.approval_request_id=v_approval.id;
  if v_workflow.id is null or v_approval.id is null or v_hours.id is null or v_candidate.id is null or v_manager.id is null
    or nullif(btrim(v_candidate.storage_key),'') is null or nullif(btrim(v_manager.storage_key),'') is null
    or octet_length(v_candidate.source_content_sha256) is distinct from 32
    or octet_length(v_manager.source_content_sha256) is distinct from 32
    or v_hours.review_render_state is distinct from 'READY' or v_hours.final_signed_render_state is distinct from 'READY'
    or nullif(btrim(v_hours.final_signed_storage_key),'') is null
    or octet_length(v_hours.final_signed_content_sha256) is distinct from 32
    or coalesce(v_hours.final_signed_page_count,0)<=0 or coalesce(v_hours.final_signed_byte_size,0)<=0
    or v_hours.review_render_input_sha256 is distinct from v_hours.final_signed_render_input_sha256
    or v_candidate.source_content_sha256 is distinct from v_workflow.candidate_signature_sha256
    or v_manager.source_content_sha256 is distinct from v_workflow.manager_signature_sha256
    or v_ts.r2_nurse_key is distinct from v_candidate.storage_key or v_ts.r2_auth_key is distinct from v_manager.storage_key
    or v_ts.img_sha256_nurse is distinct from encode(v_candidate.source_content_sha256,'hex')
    or v_ts.img_sha256_auth is distinct from encode(v_manager.source_content_sha256,'hex') then
    raise exception 'CORRECTION_MANAGER_SIGNATURE_WITNESS_INVALID' using errcode='55000';
  end if;
  return jsonb_build_object('workflow_id',v_workflow.id,'workflow_generation',v_workflow.generation,
    'approval_request_id',v_approval.id,'hours_component_id',v_hours.id,
    'candidate_component_id',v_candidate.id,'manager_component_id',v_manager.id,
    'candidate_sha256',encode(v_candidate.source_content_sha256,'hex'),
    'manager_sha256',encode(v_manager.source_content_sha256,'hex'),
    'manager_approved_at_utc',v_workflow.manager_approved_at_utc,
    'document_version_id',v_ts.current_document_version_id);
end;
$function$;

create or replace function private.timesheet_correction_request_guard_v1()
returns trigger language plpgsql security definer
set search_path to 'pg_catalog','private','public','pg_temp'
as $function$
begin
  if tg_op='DELETE' then raise exception 'CORRECTION_REQUEST_AUDIT_RETAINED' using errcode='55000'; end if;
  if tg_op='UPDATE' then
    if old.state<>'WAITING' then raise exception 'CORRECTION_REQUEST_TERMINAL_IMMUTABLE' using errcode='55000'; end if;
    if (to_jsonb(new)-array['state','state_revision','reversal_timesheet_id','reversal_booking_id','reversal_week_id',
        'workflow_id','workflow_generation','terminal_receipt_json','updated_at_utc','applied_at_utc','cancelled_at_utc'])
      is distinct from (to_jsonb(old)-array['state','state_revision','reversal_timesheet_id','reversal_booking_id','reversal_week_id',
        'workflow_id','workflow_generation','terminal_receipt_json','updated_at_utc','applied_at_utc','cancelled_at_utc']) then
      raise exception 'CORRECTION_REQUEST_ORIGINAL_PROPOSAL_IMMUTABLE' using errcode='55000';
    end if;
    if new.state_revision is distinct from old.state_revision+1 then
      raise exception 'CORRECTION_REQUEST_CAS_INVALID' using errcode='40001';
    end if;
  end if;
  return new;
end;
$function$;
drop trigger if exists timesheet_correction_request_guard_v1 on private.timesheet_correction_requests;
create trigger timesheet_correction_request_guard_v1 before update or delete
on private.timesheet_correction_requests for each row execute function private.timesheet_correction_request_guard_v1();

create or replace function private.timesheet_correction_whole_state_guard_v1()
returns trigger language plpgsql security definer
set search_path to 'pg_catalog','private','public','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype; v_r public.timesheets%rowtype; v_p public.timesheets%rowtype;
begin
  if new.correction_kind not in('WHOLE_TIMESHEET_REVERSAL','WHOLE_TIMESHEET_REPLACEMENT')
    or new.correction_kind is null then
    if tg_op='UPDATE' then
      if old.correction_kind in('WHOLE_TIMESHEET_REVERSAL','WHOLE_TIMESHEET_REPLACEMENT') then
        raise exception 'WHOLE_CORRECTION_MEMBER_IDENTITY_IMMUTABLE' using errcode='23514';
      end if;
    end if;
    return new;
  end if;
  select request.* into v_request from private.timesheet_correction_requests request
    where request.correction_id=new.correction_id;
  if v_request.id is null then raise exception 'WHOLE_CORRECTION_REQUEST_REQUIRED' using errcode='23514'; end if;
  if new.timesheet_id not in(v_request.replacement_timesheet_id,coalesce(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id))
    or new.parent_timesheet_id is distinct from v_request.root_timesheet_id
    or new.adjustment_origin is distinct from v_request.origin
    or (new.timesheet_id=v_request.replacement_timesheet_id and
      (new.correction_kind<>'WHOLE_TIMESHEET_REPLACEMENT' or new.booking_id<>v_request.replacement_booking_id))
    or (new.timesheet_id=v_request.reversal_timesheet_id and
      (new.correction_kind<>'WHOLE_TIMESHEET_REVERSAL' or new.booking_id<>v_request.reversal_booking_id)) then
    raise exception 'WHOLE_CORRECTION_REQUEST_MEMBER_INVALID' using errcode='23514';
  end if;
  select t.* into v_p from public.timesheets t where t.timesheet_id=v_request.replacement_timesheet_id;
  select t.* into v_r from public.timesheets t where t.timesheet_id=v_request.reversal_timesheet_id;
  if v_request.state='WAITING' and (v_p.authorised_at_server is not null or v_r.authorised_at_server is not null) then
    raise exception 'WHOLE_CORRECTION_REQUIRES_ATOMIC_APPROVAL' using errcode='23514';
  end if;
  if v_request.state='APPLIED' and (v_r.timesheet_id is null or v_p.timesheet_id is null
    or (select count(*) from public.timesheets_financials tf where tf.timesheet_id in(v_r.timesheet_id,v_p.timesheet_id)
      and tf.is_current)<>2
    or (v_r.authorised_at_server is null) is distinct from (v_p.authorised_at_server is null)
    or exists(select 1 from public.timesheets_financials tf where tf.timesheet_id in(v_r.timesheet_id,v_p.timesheet_id)
      and tf.is_current and (tf.authorised_at_utc is null) is distinct from
        (case when tf.timesheet_id=v_r.timesheet_id then v_r.authorised_at_server is null else v_p.authorised_at_server is null end))) then
    raise exception 'WHOLE_CORRECTION_PAIR_STATE_INVALID' using errcode='23514';
  end if;
  return new;
end;
$function$;
drop trigger if exists zz_timesheet_correction_whole_state_guard_v1 on public.timesheets;
create constraint trigger zz_timesheet_correction_whole_state_guard_v1 after insert or update on public.timesheets
deferrable initially deferred for each row
execute function private.timesheet_correction_whole_state_guard_v1();

create or replace function private.timesheet_correction_week_allocate_v1(
  p_contract_id uuid,p_week_ending date,p_submission public.submission_mode_enum,p_planned_id uuid,p_now timestamptz
) returns uuid language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_seq integer; v_id uuid:=coalesce(p_planned_id,gen_random_uuid());
begin
  perform pg_advisory_xact_lock(hashtextextended('CORRECTION_ADJUSTMENT_WEEK|'||p_contract_id||'|'||p_week_ending,0));
  perform 1 from public.contract_weeks w where w.contract_id=p_contract_id and w.week_ending_date=p_week_ending
    order by w.id for update;
  select coalesce(max(w.additional_seq),0)+1 into v_seq from public.contract_weeks w
    where w.contract_id=p_contract_id and w.week_ending_date=p_week_ending;
  insert into public.contract_weeks(id,contract_id,week_ending_date,additional_seq,is_adjustment,submission_mode_snapshot,status,created_at,updated_at)
    values(v_id,p_contract_id,p_week_ending,v_seq,true,p_submission,'SUBMITTED',p_now,p_now);
  return v_id;
end;
$function$;

create or replace function public.timesheet_correction_workflow_projection_v1(p_workflow_id uuid,p_candidate_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_workflow public.candidate_submission_workflows%rowtype; v_request private.timesheet_correction_requests%rowtype;
begin
  select w.* into v_workflow from public.candidate_submission_workflows w
    where w.id=p_workflow_id and w.candidate_id=p_candidate_id;
  if not found then return null; end if;
  select request.* into v_request from private.timesheet_correction_requests request
    where request.candidate_id=p_candidate_id
      and request.replacement_timesheet_id in(v_workflow.target_timesheet_id,v_workflow.anchor_timesheet_id)
    order by request.created_at_utc desc,request.id desc limit 1;
  if not found then return null; end if;
  return private.timesheet_correction_projection_by_request_v1(v_request.id,p_candidate_id);
end;
$function$;

-- Physical family allocation follows the existing adjustment-week owner shape.
-- The booking below is physical identity only; original_booking_id remains
-- immutable business authority and no economic-key derivation is introduced.
create or replace function private.timesheet_correction_leg_create_v1(
  p_request private.timesheet_correction_requests,p_kind text,p_schedule jsonb,p_now timestamptz
) returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare v_original public.timesheets%rowtype; v_id uuid; v_booking text; v_week uuid; v_seq integer; v_json jsonb;
begin
  if p_kind not in('WHOLE_TIMESHEET_REVERSAL','WHOLE_TIMESHEET_REPLACEMENT') or jsonb_typeof(p_schedule)<>'array' then
    raise exception 'CORRECTION_LEG_SHAPE_INVALID' using errcode='22023';
  end if;
  select t.* into strict v_original from public.timesheets t where t.timesheet_id=p_request.reversed_timesheet_id;
  v_id:=case when p_kind='WHOLE_TIMESHEET_REPLACEMENT' then p_request.replacement_timesheet_id
    else(p_request.frozen_original_json->>'planned_reversal_timesheet_id')::uuid end;
  v_booking:=case when p_kind='WHOLE_TIMESHEET_REPLACEMENT' then p_request.replacement_booking_id
    else 'bk_awc_'||substr(encode(digest(p_request.id::text||'|R0','sha256'),'hex'),1,24) end;
  if v_original.sheet_scope::text='WEEKLY' then
    if p_request.contract_id is null then raise exception 'CORRECTION_WEEKLY_CONTRACT_REQUIRED' using errcode='55000'; end if;
    if p_kind='WHOLE_TIMESHEET_REPLACEMENT' then
      v_week:=p_request.replacement_week_id;
      if not exists(select 1 from public.contract_weeks w where w.id=v_week and w.contract_id=p_request.contract_id
        and w.week_ending_date=p_request.week_ending_date and w.is_adjustment and w.timesheet_id is null) then
        raise exception 'CORRECTION_P0_WEEK_AUTHORITY_INVALID' using errcode='55000';
      end if;
    else
      v_week:=private.timesheet_correction_week_allocate_v1(p_request.contract_id,p_request.week_ending_date,
        v_original.submission_mode,(p_request.frozen_original_json->>'planned_reversal_week_id')::uuid,p_now);
    end if;
  end if;
  v_json:=to_jsonb(v_original)||jsonb_build_object(
    'timesheet_id',v_id,'booking_id',v_booking,'version',1,'is_current',true,'status','RECEIVED',
    'is_adjustment',true,'parent_timesheet_id',p_request.root_timesheet_id,'correction_id',p_request.correction_id,
    'correction_kind',p_kind,'adjustment_origin',p_request.origin,'actual_schedule_json',p_schedule,
    'additional_units_week','{}'::jsonb,'additional_units_per_day','{}'::jsonb,
    'authorised_at_server',null,'auth_name',null,'auth_job_title',null,'r2_nurse_key',null,'r2_auth_key',null,
    'img_sha256_nurse',null,'img_sha256_auth',null,'manual_pdf_r2_key',null,'manual_document_asset_id',null,
    'qr_status',null,'qr_token',null,'qr_payload_json','{}'::jsonb,'qr_signed_hash',null,'qr_signed_at_utc',null,
    'qr_generated_at',null,'qr_scanned_at',null,'qr_scan_info_json',null,'qr_r2_key',null,
    'qr_last_sent_hash',null,'qr_last_sent_at_utc',null,'qr_sent_refs_sig',null,'qr_sent_refs_snapshot_json',null,
    'qr_sent_refs_captured_at_utc',null,'generated_pdf_at_utc',null,'generated_pdf_refs_sig',null,
    'generated_pdf_refs_snapshot_json',null,'generated_pdf_refs_captured_at_utc',null)
    ||jsonb_build_object(
    'revoked_at',null,'revoked_reason',null,'revoked_by',null,'archived_at_utc',null,'archived_by_user_id',null,
    'archived_reason_code',null,'idempotency_key',null,'client_hash',null,'client_ua',null,
    'worked_start_iso',null,'worked_end_iso',null,'break_start_iso',null,'break_end_iso',null,'break_minutes',null,'worked_minutes',null,
    'document_revision',1,'document_state','STALE','current_document_version_id',null,'active_document_operation_id',null,
    'last_document_error_json',null,'candidate_workflow_id',null,'candidate_workflow_generation',null,
    'candidate_manager_approved_at_utc',null,'candidate_submission_route_intent',null,
    'reference_number',null,'reference_set_at',null,'day_references_json',null,'created_at',p_now,'updated_at',p_now,
    'candidate_hint_text',jsonb_build_object('timesheet_correction_request',jsonb_build_object(
      'request_id',p_request.id,'root_timesheet_id',p_request.root_timesheet_id,'original_booking_id',p_request.original_booking_id,
      'reversed_timesheet_id',p_request.reversed_timesheet_id,'target_revision',p_request.target_revision,
      'candidate_id',p_request.candidate_id,'client_id',p_request.client_id,'work_date',p_request.work_date),
      'daily_receipt',p_request.frozen_original_json->'daily_receipt'));
  insert into public.timesheets select (jsonb_populate_record(null::public.timesheets,v_json)).*;
  if v_week is not null then update public.contract_weeks set timesheet_id=v_id where id=v_week; end if;
  return jsonb_build_object('timesheet_id',v_id,'booking_id',v_booking,'contract_week_id',v_week);
end;
$function$;

create or replace function public.timesheet_correction_send_v1(p_request jsonb,p_actor_user_id uuid,p_now_utc timestamptz default now())
returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now()); v_id uuid; v_root uuid; v_ts public.timesheets%rowtype;
  v_fin public.timesheets_financials%rowtype; v_req private.timesheet_correction_requests%rowtype;
  v_existing private.timesheet_correction_requests%rowtype; v_origin text; v_chain jsonb; v_witness jsonb;
  v_invoice uuid; v_invoice_status text; v_key text; v_hash text; v_leg jsonb; v_candidate uuid; v_client uuid; v_date date;
begin
  perform private.timesheet_correction_actor_assert_v1(p_actor_user_id);
  if jsonb_typeof(p_request)<>'object' or not pg_input_is_valid(p_request->>'timesheet_id','uuid')
    or not pg_input_is_valid(p_request->>'expected_version','integer')
    or jsonb_typeof(p_request->'proposal') is distinct from 'object'
    or jsonb_typeof(p_request#>'{proposal,schedule}') is distinct from 'array'
    or length(btrim(coalesce(p_request->>'reason',''))) not between 1 and 1000 or nullif(btrim(p_request->>'request_key'),'') is null
    or exists(select 1 from jsonb_object_keys(p_request) k where k not in('timesheet_id','expected_version','proposal','reason','request_key')) then
    raise exception 'CORRECTION_SEND_SHAPE_INVALID' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_object_keys(p_request->'proposal') k where k not in('schedule','changed_dates'))
    or exists(select 1 from jsonb_array_elements(p_request#>'{proposal,schedule}') s where jsonb_typeof(s) is distinct from 'object')
    or (p_request#>'{proposal,changed_dates}' is not null and jsonb_typeof(p_request#>'{proposal,changed_dates}') is distinct from 'array') then
    raise exception 'CORRECTION_SEND_SHAPE_INVALID' using errcode='22023';
  end if;
  v_id:=(p_request->>'timesheet_id')::uuid; v_key:=p_request->>'request_key';
  v_hash:=encode(digest(jsonb_build_object('actor',p_actor_user_id,'request',p_request)::text,'sha256'),'hex');
  -- Serialize exact command receipt before checking it. Concurrent same-key
  -- Send never allocates a second P0 or loses replay to the unique index.
  perform pg_advisory_xact_lock(hashtextextended('CORRECTION_SEND|'||v_key,13102026));
  select request.* into v_existing from private.timesheet_correction_requests request where request.request_key=v_key;
  if found then
    if v_existing.request_fingerprint is distinct from v_hash or v_existing.created_by_user_id is distinct from p_actor_user_id then
      raise exception 'CORRECTION_SEND_REPLAY_CONFLICT' using errcode='40001';
    end if;
    return jsonb_build_object('ok',true,'request_id',v_existing.id,'state',v_existing.state,
      'replacement_timesheet_id',v_existing.replacement_timesheet_id,'state_revision',v_existing.state_revision,'replayed',true);
  end if;
  -- Lock every existing invoice first, using the same authority as all credit writers.
  perform i.id from public.invoices i where i.id in(select distinct l.invoice_id from public.invoice_lines l
    where l.timesheet_id=v_id) order by i.id for update;
  v_chain:=public.timesheet_correction_chain_scope_v1(v_id,false,32,100);
  if (v_chain->>'valid')::boolean is distinct from true or v_chain->>'latest_positive_timesheet_id' is distinct from v_id::text then
    raise exception 'CORRECTION_LATEST_POSITIVE_REQUIRED' using errcode='55000';
  end if;
  v_root:=(v_chain->>'root_timesheet_id')::uuid;
  perform pg_advisory_xact_lock(hashtextextended('CORRECTION_CHAIN|'||v_root::text,21072026));
  v_chain:=public.timesheet_correction_chain_scope_v1(v_id,false,32,100);
  if (v_chain->>'valid')::boolean is distinct from true or v_chain->>'latest_positive_timesheet_id' is distinct from v_id::text then
    raise exception 'CORRECTION_LATEST_POSITIVE_REQUIRED' using errcode='40001';
  end if;
  select t.* into strict v_ts from public.timesheets t where t.timesheet_id=v_id;
  -- The workflow lock precedes Timesheet/TSFIN locks, matching native Candidate owners.
  if v_ts.candidate_workflow_id is not null then
    perform 1 from public.candidate_submission_workflows w where w.id=v_ts.candidate_workflow_id for update;
  end if;
  select t.* into strict v_ts from public.timesheets t where t.timesheet_id=v_id for update;
  if not v_ts.is_current or v_ts.archived_at_utc is not null or v_ts.version<>(p_request->>'expected_version')::integer then
    raise exception 'CORRECTION_ORIGINAL_CHANGED' using errcode='40001';
  end if;
  v_origin:=private.timesheet_correction_origin_v1(v_id);
  if v_origin is null then raise exception 'CORRECTION_ORIGIN_NOT_ALLOWED' using errcode='55000'; end if;
  if v_origin='SIGNED_TIMESHEET_CORRECTION' then v_witness:=private.timesheet_correction_signed_witness_v1(v_id,true); end if;
  select tf.* into v_fin from public.timesheets_financials tf where tf.timesheet_id=v_id and tf.is_current for update;
  select summary.candidate_id,summary.client_id into v_candidate,v_client from public.v_timesheets_summary_base summary
    where summary.timesheet_id=v_id;
  if v_candidate is null or v_client is null then raise exception 'CORRECTION_BUSINESS_SCOPE_UNPROVED' using errcode='55000'; end if;
  select l.invoice_id,i.status::text into v_invoice,v_invoice_status from public.invoice_lines l
    join public.invoices i on i.id=l.invoice_id where l.timesheet_id=v_id and i.type='INVOICE'
      and i.status in('DRAFT','ISSUED','PAID') group by l.invoice_id,i.status;
  if (select count(distinct l.invoice_id) from public.invoice_lines l join public.invoices i on i.id=l.invoice_id
    where l.timesheet_id=v_id and i.type='INVOICE' and i.status in('DRAFT','ISSUED','PAID'))>1 then
    raise exception 'CORRECTION_ORIGINAL_SPLIT_INVOICES' using errcode='55000';
  end if;
  if v_origin='AGENCY_INVOICE_CORRECTION' and coalesce(v_invoice_status,'') not in('ISSUED','PAID') then
    raise exception 'AGENCY_WHOLE_CORRECTION_REQUIRES_ISSUED_PARENT' using errcode='55000';
  end if;
  v_date:=case when v_ts.sheet_scope::text='DAILY' then coalesce(
    case when pg_input_is_valid(v_ts.candidate_hint_text#>>'{daily_receipt,work_date}','date')
      then(v_ts.candidate_hint_text#>>'{daily_receipt,work_date}')::date end,
    (v_ts.worked_start_iso at time zone 'Europe/London')::date) else v_ts.week_ending_date end;
  if v_date is null then raise exception 'CORRECTION_WORK_DATE_UNPROVED' using errcode='55000'; end if;
  v_req.id:=gen_random_uuid(); v_req.correction_id:='awc:'||v_root||':'||v_req.id;
  v_req.origin:=v_origin; v_req.state:='WAITING'; v_req.state_revision:=1; v_req.proposal_revision:=1;
  v_req.root_timesheet_id:=v_root;
  select t.booking_id into v_req.original_booking_id from public.timesheets t where t.timesheet_id=v_root;
  v_req.reversed_timesheet_id:=v_id; v_req.reversed_version:=v_ts.version; v_req.reversed_financial_id:=v_fin.id;
  v_req.candidate_id:=v_candidate; v_req.client_id:=v_client; v_req.contract_id:=v_ts.contract_id;
  v_req.work_date:=v_date; v_req.week_ending_date:=v_ts.week_ending_date;
  v_req.replacement_timesheet_id:=gen_random_uuid();
  v_req.replacement_booking_id:='bk_awc_'||substr(encode(digest(v_req.id::text||'|P0','sha256'),'hex'),1,24);
  v_req.request_key:=v_key; v_req.request_fingerprint:=v_hash; v_req.reason:=btrim(p_request->>'reason');
  v_req.frozen_original_json:=jsonb_build_object('timesheet',to_jsonb(v_ts),
    'financial_snapshot',case when v_fin.id is not null then to_jsonb(v_fin) end,
    'financial_authority_hash',case when v_fin.id is not null then private.timesheet_correction_financial_authority_hash_v1(to_jsonb(v_fin)) end,
    'planned_reversal_timesheet_id',gen_random_uuid(),
    'planned_reversal_week_id',case when v_ts.sheet_scope::text='WEEKLY' then gen_random_uuid() end,
    'schedule',coalesce(v_ts.actual_schedule_json,'[]'::jsonb),'manager_signed_witness',v_witness,
    'daily_receipt',v_ts.candidate_hint_text->'daily_receipt');
  v_req.proposal_json:=p_request->'proposal';
  v_req.target_revision:=encode(digest(jsonb_build_object('request',v_req.id,'root',v_root,'original_booking',v_req.original_booking_id,
    'reversed',v_id,'version',v_ts.version,'candidate',v_candidate,'client',v_client,'date',v_date,
    'original',v_req.frozen_original_json,'proposal',v_req.proposal_json)::text,'sha256'),'hex');
  v_req.original_invoice_id:=case when v_invoice_status in('ISSUED','PAID') then v_invoice end;
  v_req.return_invoice_id:=case when v_invoice_status='DRAFT' then v_invoice end;
  v_req.created_by_user_id:=p_actor_user_id; v_req.created_at_utc:=v_now; v_req.updated_at_utc:=v_now;
  if v_ts.sheet_scope::text='WEEKLY' then
    v_req.replacement_week_id:=private.timesheet_correction_week_allocate_v1(v_req.contract_id,v_req.week_ending_date,
      v_ts.submission_mode,null,v_now);
  end if;
  -- The exact request exists before native overlap/derived triggers see P0.
  insert into private.timesheet_correction_requests select (v_req).*;
  v_leg:=private.timesheet_correction_leg_create_v1(v_req,'WHOLE_TIMESHEET_REPLACEMENT',
    case when v_origin='SIGNED_TIMESHEET_CORRECTION' then '[]'::jsonb else v_req.proposal_json->'schedule' end,v_now);
  insert into public.audit_events(ts_utc,actor_user_id,object_type,object_id_text,action,after_json,reason)
    values(v_now,p_actor_user_id,'timesheets',v_id::text,'TIMESHEET_CORRECTION_SENT',
      jsonb_build_object('request_id',v_req.id,'replacement_timesheet_id',v_req.replacement_timesheet_id),v_req.reason);
  return jsonb_build_object('ok',true,'request_id',v_req.id,'state','WAITING','state_revision',1,
    'replacement_timesheet_id',v_req.replacement_timesheet_id,'replacement_booking_id',v_req.replacement_booking_id,
    'target_revision',v_req.target_revision,'proposal_revision',1);
end;
$function$;

create or replace function private.timesheet_correction_projection_by_request_v1(p_request_id uuid,p_candidate_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','private','public','pg_temp'
as $function$
declare v_req private.timesheet_correction_requests%rowtype;
begin
  select request.* into v_req from private.timesheet_correction_requests request
    where request.id=p_request_id and request.candidate_id=p_candidate_id;
  if not found then return null; end if;
  return jsonb_build_object('schema_version',1,'request_id',v_req.id,'correction_id',v_req.correction_id,
    'origin',v_req.origin,'state',v_req.state,'state_revision',v_req.state_revision,'proposal_revision',1,
    'target_revision',v_req.target_revision,'root_timesheet_id',v_req.root_timesheet_id,'reversed_timesheet_id',v_req.reversed_timesheet_id,
    'original_booking_id',v_req.original_booking_id,'replacement_timesheet_id',v_req.replacement_timesheet_id,
    'replacement_booking_id',v_req.replacement_booking_id,'replacement_week_id',v_req.replacement_week_id,
    'candidate_id',v_req.candidate_id,'reason',v_req.reason,
    'original_schedule',v_req.frozen_original_json->'schedule','proposed_schedule',v_req.proposal_json->'schedule',
    'frozen_daily_receipt',v_req.frozen_original_json->'daily_receipt',
    'frozen_daily_shift',case when v_req.frozen_original_json#>>'{timesheet,sheet_scope}'='DAILY' then jsonb_build_object(
      'booking_id',v_req.original_booking_id,'work_date',v_req.work_date,'week_ending_date',v_req.week_ending_date,
      'hospital',v_req.frozen_original_json#>'{timesheet,hospital_norm}',
      'ward',v_req.frozen_original_json#>'{timesheet,ward_norm}',
      'job_title',v_req.frozen_original_json#>'{timesheet,job_title_norm}',
      'shift_type',v_req.frozen_original_json#>'{timesheet,shift_label_norm}',
      'shift_starts_at',v_req.frozen_original_json#>'{timesheet,scheduled_start_iso}',
      'shift_ends_at',v_req.frozen_original_json#>'{timesheet,scheduled_end_iso}') end,
    'original_manager_approved_at_utc',v_req.frozen_original_json#>'{manager_signed_witness,manager_approved_at_utc}',
    'changed_dates',coalesce(v_req.proposal_json->'changed_dates','[]'::jsonb),
    'draft_scope',jsonb_build_object('kind','TIMESHEET_CORRECTION','request_id',v_req.id,
      'replacement_timesheet_id',v_req.replacement_timesheet_id,
      'allowed_timesheet_aliases',case when v_req.state='WAITING' then jsonb_build_array(v_req.replacement_timesheet_id) else '[]'::jsonb end,
      'allowed_booking_aliases',case when v_req.state='WAITING' then jsonb_build_array(v_req.replacement_booking_id) else '[]'::jsonb end));
end;
$function$;

create or replace function public.timesheet_correction_request_projection_v1(p_timesheet_id uuid,p_candidate_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','private','public','pg_temp'
as $function$
declare v_request_id uuid;
begin
  select request.id into v_request_id from private.timesheet_correction_requests request
    where request.candidate_id=p_candidate_id
      and p_timesheet_id in(request.root_timesheet_id,request.reversed_timesheet_id,request.replacement_timesheet_id,request.reversal_timesheet_id)
    order by case when request.state='WAITING' then 0 else 1 end,request.created_at_utc desc,request.id desc limit 1;
  if not found then return null; end if;
  return private.timesheet_correction_projection_by_request_v1(v_request_id,p_candidate_id);
end;
$function$;

-- CREATE has no workflow yet. An owned physical P0 selector proves only this
-- purpose context; all ordinary validation and errors remain with CREATE.
create or replace function public.timesheet_correction_create_projection_v1(
  p_candidate_id uuid,p_contract_week_id uuid default null,p_target_timesheet_id uuid default null,p_anchor_timesheet_id uuid default null
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','private','public','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype; v_p public.timesheets%rowtype;
begin
  select request.* into v_request from private.timesheet_correction_requests request
    where request.candidate_id=p_candidate_id
      and ((p_contract_week_id is not null and request.replacement_week_id=p_contract_week_id)
        or (p_target_timesheet_id is not null and request.replacement_timesheet_id=p_target_timesheet_id)
        or (p_anchor_timesheet_id is not null and request.replacement_timesheet_id=p_anchor_timesheet_id))
    order by request.created_at_utc desc,request.id desc limit 1;
  if not found then return null; end if;
  if (p_contract_week_id is not null and p_contract_week_id is distinct from v_request.replacement_week_id)
    or (p_target_timesheet_id is not null and p_target_timesheet_id is distinct from v_request.replacement_timesheet_id)
    or (p_anchor_timesheet_id is not null and p_anchor_timesheet_id is distinct from v_request.replacement_timesheet_id) then
    raise exception 'CANDIDATE_CONTEXT_STALE' using errcode='40001';
  end if;
  if v_request.state<>'CANCELLED' then
    select t.* into v_p from public.timesheets t where t.timesheet_id=v_request.replacement_timesheet_id;
    if v_p.timesheet_id is null or not v_p.is_current or v_p.archived_at_utc is not null
      or v_p.booking_id is distinct from v_request.replacement_booking_id
      or v_p.contract_id is distinct from v_request.contract_id
      or v_p.parent_timesheet_id is distinct from v_request.root_timesheet_id
      or v_p.correction_id is distinct from v_request.correction_id
      or v_p.correction_kind is distinct from 'WHOLE_TIMESHEET_REPLACEMENT' then
      raise exception 'CANDIDATE_CONTEXT_STALE' using errcode='40001';
    end if;
  end if;
  return private.timesheet_correction_projection_by_request_v1(v_request.id,p_candidate_id);
end;
$function$;

create or replace function private.timesheet_correction_invoice_route_v1(p_timesheet_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype;
begin
  select request.* into v_request from private.timesheet_correction_requests request
    where request.state='APPLIED' and request.reversed_timesheet_id=p_timesheet_id order by request.applied_at_utc desc limit 1;
  if found then return jsonb_build_object('route','BLOCKED','blocker_code','AGENCY_INVOICE_SUPERSEDED','request_id',v_request.id); end if;
  select request.* into v_request from private.timesheet_correction_requests request
    where p_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id);
  if not found then return null; end if;
  if v_request.state<>'APPLIED' then
    return jsonb_build_object('route','BLOCKED','blocker_code','CORRECTION_REQUEST_NOT_APPLIED','request_id',v_request.id);
  end if;
  if p_timesheet_id=v_request.reversal_timesheet_id then
    if v_request.original_invoice_id is null then return jsonb_build_object('route','NO_INVOICE_PLACEMENT','request_id',v_request.id); end if;
    return jsonb_build_object('route','TIMESHEET_CREDIT','request_id',v_request.id,'original_invoice_id',v_request.original_invoice_id,
      'credit_scope',jsonb_build_object('reversal_timesheet_id',v_request.reversal_timesheet_id));
  end if;
  if private.timesheet_correction_replacement_empty_v1(v_request.id) then
    return jsonb_build_object('route','NO_INVOICE_PLACEMENT','request_id',v_request.id);
  end if;
  return jsonb_build_object('route',case when v_request.return_invoice_id is not null then 'RETURN_TO_SAME_DRAFT' else 'NORMAL' end,
    'request_id',v_request.id,'return_invoice_id',v_request.return_invoice_id);
end;
$function$;

create or replace function private.timesheet_correction_invoice_scope_v1(
  p_timesheet_id uuid,p_target_invoice_id uuid,p_actor_user_id uuid,p_lock_rows boolean,p_max_members integer
) returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_request private.timesheet_correction_requests%rowtype; v_rfin public.timesheets_financials%rowtype;
  v_pfin public.timesheets_financials%rowtype; v_target public.invoices%rowtype; v_cn public.invoices%rowtype;
  v_empty boolean; v_errors jsonb:='[]'::jsonb; v_placement text:='UNPLACED'; v_complete boolean:=false;
  v_p_invoice uuid; v_p_invoice_count integer; v_p_count integer; v_component_keys integer; v_net numeric; v_pay numeric;
  v_h_day numeric; v_h_night numeric; v_h_sat numeric; v_h_sun numeric; v_h_bh numeric; v_credit_count integer;
  v_original_line_count integer; v_clone_count integer; v_credit_valid boolean:=false; v_source_lines jsonb;
begin
  select request.* into v_request from private.timesheet_correction_requests request
    where p_timesheet_id in(request.reversal_timesheet_id,request.replacement_timesheet_id)
      and request.correction_id=(select t.correction_id from public.timesheets t where t.timesheet_id=p_timesheet_id);
  if not found then return null; end if;
  if p_actor_user_id is not null and private.timesheet_correction_actor_allowed_v1(p_actor_user_id) is distinct from true then
    raise exception 'CORRECTION_ACTOR_NOT_ALLOWED' using errcode='42501';
  end if;
  if p_max_members<2 then raise exception 'INVOICE_CORRECTION_MEMBER_LIMIT_INVALID' using errcode='22023'; end if;
  if p_lock_rows then
    perform 1 from public.invoices i where i.id in(v_request.original_invoice_id,v_request.return_invoice_id,p_target_invoice_id)
      or i.id in(select l.invoice_id from public.invoice_lines l where l.timesheet_id=v_request.replacement_timesheet_id)
      or (i.original_invoice_id=v_request.original_invoice_id and i.header_snapshot_json#>>'{credit_scope,reversal_timesheet_id}'=v_request.reversal_timesheet_id::text)
      order by i.id for update;
    perform 1 from private.timesheet_correction_requests request where request.id=v_request.id for update;
    perform 1 from public.timesheets t where t.timesheet_id in(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id)
      order by t.timesheet_id for update;
    perform 1 from public.timesheets_financials tf where tf.timesheet_id in(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id)
      and tf.is_current order by tf.timesheet_id,tf.id for update;
  end if;
  if v_request.state<>'APPLIED' then v_errors:=jsonb_build_array(jsonb_build_object('code','CORRECTION_REQUEST_NOT_APPLIED')); end if;
  if v_request.state='APPLIED' then perform private.timesheet_correction_applied_assert_v1(v_request.id); end if;
  select tf.* into v_rfin from public.timesheets_financials tf where tf.timesheet_id=v_request.reversal_timesheet_id and tf.is_current;
  select tf.* into v_pfin from public.timesheets_financials tf where tf.timesheet_id=v_request.replacement_timesheet_id and tf.is_current;
  if v_rfin.id is null or v_pfin.id is null or v_rfin.authorised_at_utc is null or v_pfin.authorised_at_utc is null
    or v_pfin.client_id is distinct from v_request.client_id or v_rfin.client_id is distinct from v_request.client_id then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','WHOLE_CORRECTION_UNIT_NOT_AUTHORISED'));
  end if;
  v_empty:=private.timesheet_correction_replacement_empty_v1(v_request.id);
  select count(*)::integer,count(distinct l.invoice_id)::integer,count(distinct l.source_key)::integer,
    sum(l.total_charge_ex_vat),sum(l.total_pay_ex_vat),sum(l.hours_day),sum(l.hours_night),sum(l.hours_sat),sum(l.hours_sun),sum(l.hours_bh),
    (array_agg(l.invoice_id order by l.invoice_id))[1]
    into v_p_count,v_p_invoice_count,v_component_keys,v_net,v_pay,v_h_day,v_h_night,v_h_sat,v_h_sun,v_h_bh,v_p_invoice
  from public.invoice_lines l join public.invoices i on i.id=l.invoice_id
    where l.timesheet_id=v_request.replacement_timesheet_id and i.type='INVOICE';
  -- Multiple native components on one invoice are one placement. A split,
  -- repeated source key, stale financial cut or missing monetary/hour part is
  -- refused; there is deliberately no one-line-per-member assumption.
  if v_p_invoice_count>1 or v_p_count<>v_component_keys
    or (v_p_count>0 and (v_net is distinct from v_pfin.total_charge_ex_vat or v_pay is distinct from v_pfin.total_pay_ex_vat
      or v_h_day is distinct from v_pfin.hours_day or v_h_night is distinct from v_pfin.hours_night
      or v_h_sat is distinct from v_pfin.hours_sat or v_h_sun is distinct from v_pfin.hours_sun or v_h_bh is distinct from v_pfin.hours_bh
      or exists(select 1 from public.invoice_lines l where l.timesheet_id=v_request.replacement_timesheet_id and l.invoice_id=v_p_invoice
        and l.meta_json#>>'{tsfin_id}' is distinct from v_pfin.id::text)))
    or (v_empty and v_p_count<>0) then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','WHOLE_CORRECTION_REPLACEMENT_COMPONENT_PLACEMENT_INVALID'));
  end if;
  if exists(select 1 from public.invoice_lines l where l.timesheet_id=v_request.reversal_timesheet_id) then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','WHOLE_CORRECTION_REVERSAL_NORMAL_LINE_FORBIDDEN'));
  end if;
  if p_target_invoice_id is not null then
    select i.* into v_target from public.invoices i where i.id=p_target_invoice_id;
    if p_timesheet_id<>v_request.replacement_timesheet_id or v_target.type is distinct from 'INVOICE'
      or v_target.status not in('DRAFT','ON_HOLD') or v_target.issued_at_utc is not null or v_target.paid_at_utc is not null
      or v_target.client_id is distinct from v_request.client_id or (v_request.return_invoice_id is not null and p_target_invoice_id<>v_request.return_invoice_id)
      or (v_p_invoice is not null and v_p_invoice<>p_target_invoice_id) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','WHOLE_CORRECTION_TARGET_INVOICE_INCOMPATIBLE'));
    end if;
  end if;
  if v_request.original_invoice_id is null then
    if exists(select 1 from public.invoice_lines l where l.timesheet_id=v_request.reversed_timesheet_id) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','WHOLE_CORRECTION_UNINVOICED_PARENT_HAS_LINE'));
    end if;
    if v_empty or v_p_count>0 then v_placement:='COMPLETE_UNINVOICED_PARENT'; v_complete:=true; end if;
  else
    select count(*)::integer into v_credit_count from public.invoices cn where cn.type='CREDIT_NOTE'
      and cn.original_invoice_id=v_request.original_invoice_id
      and cn.header_snapshot_json#>>'{credit_scope,reversal_timesheet_id}'=v_request.reversal_timesheet_id::text
      and cn.status in('DRAFT','ISSUED','PAID');
    if v_credit_count>1 then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','WHOLE_CORRECTION_DUPLICATE_CREDIT_PLACEMENT')); end if;
    if v_credit_count=1 then
      select cn.* into v_cn from public.invoices cn where cn.type='CREDIT_NOTE'
        and cn.original_invoice_id=v_request.original_invoice_id
        and cn.header_snapshot_json#>>'{credit_scope,reversal_timesheet_id}'=v_request.reversal_timesheet_id::text
        and cn.status in('DRAFT','ISSUED','PAID');
      select count(*)::integer into v_original_line_count from public.invoice_lines l
        where l.invoice_id=v_request.original_invoice_id and l.timesheet_id=v_request.reversed_timesheet_id;
      select count(*)::integer,count(distinct l.meta_json->>'original_invoice_line_id')::integer into v_clone_count,v_component_keys
        from public.invoice_lines l where l.invoice_id=v_cn.id;
      v_credit_valid:=v_clone_count=v_original_line_count and v_clone_count=v_component_keys and v_clone_count>0
        and not exists(select 1 from public.invoice_lines l left join public.invoice_lines original
          on original.id::text=l.meta_json->>'original_invoice_line_id' and original.invoice_id=v_request.original_invoice_id
            and original.timesheet_id=v_request.reversed_timesheet_id
          where l.invoice_id=v_cn.id and (original.id is null or l.timesheet_id is distinct from original.timesheet_id
            or l.meta_json->>'reversal_timesheet_id' is distinct from v_request.reversal_timesheet_id::text
            or l.source_key is distinct from original.source_key or l.booking_id is distinct from original.booking_id
            or l.total_charge_ex_vat is distinct from -original.total_charge_ex_vat or l.total_pay_ex_vat is distinct from -original.total_pay_ex_vat
            or l.vat_amount is distinct from -original.vat_amount or l.total_inc_vat is distinct from -original.total_inc_vat))
        and v_rfin.locked_by_invoice_id is not distinct from v_cn.id
        and not exists(select 1 from jsonb_array_elements(case when jsonb_typeof(v_rfin.invoice_breakdown_json->'segments')='array'
          then v_rfin.invoice_breakdown_json->'segments' else '[]'::jsonb end) s
          where s->>'invoice_locked_invoice_id' is distinct from v_cn.id::text);
      if v_credit_valid is distinct from true then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','WHOLE_CORRECTION_CREDIT_COMPONENT_PLACEMENT_INVALID')); end if;
      if v_credit_valid and v_cn.status in('ISSUED','PAID') and exists(select 1 from public.invoice_document_versions d
        where d.id=v_cn.issued_document_version_id and d.entity_type='INVOICE' and d.entity_id=v_cn.id and d.purpose='FINAL_ISSUE'
          and d.status='READY' and d.verified_at_utc is not null and nullif(d.r2_key,'') is not null
          and d.sha256~'^[0-9a-f]{64}$' and d.page_count>0 and d.size_bytes>0)
        and (v_empty or v_p_count>0) then
        v_placement:='COMPLETE_BY_TIMESHEET_CREDIT'; v_complete:=true;
      end if;
    end if;
  end if;
  return jsonb_build_object('ok',true,'valid',jsonb_array_length(v_errors)=0,'root_timesheet_id',v_request.root_timesheet_id,
    'request_id',v_request.id,'correction_id',v_request.correction_id,'correction_shape','WHOLE_REVERSAL_REPLACEMENT',
    'expected_member_count',2,'pair_timesheet_ids',jsonb_build_array(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id),
    'target_invoice_id',p_target_invoice_id,'target_appendable',jsonb_array_length(v_errors)=0,
    'invoice_stream','NORMAL','placement_state',v_placement,'placement_complete',v_complete and jsonb_array_length(v_errors)=0,
    'placement_compatible',jsonb_array_length(v_errors)=0,'credit_note_id',v_cn.id,'replacement_invoice_id',v_p_invoice,
    'replacement_component_count',v_p_count,'empty_replacement',v_empty,'errors',v_errors);
end;
$function$;

create or replace function private.timesheet_correction_replacement_empty_v1(p_request_id uuid)
returns boolean language sql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
  select coalesce((select jsonb_typeof(t.actual_schedule_json)='array' and jsonb_array_length(t.actual_schedule_json)=0
    and tf.total_hours=0 and tf.total_pay_ex_vat=0 and tf.total_charge_ex_vat=0
    and tf.additional_pay_ex_vat=0 and tf.additional_charge_ex_vat=0
    and tf.expenses_pay_ex_vat=0 and tf.expenses_charge_ex_vat=0
    and tf.mileage_pay_ex_vat=0 and tf.mileage_charge_ex_vat=0
  from private.timesheet_correction_requests request join public.timesheets t on t.timesheet_id=request.replacement_timesheet_id
    join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
  where request.id=p_request_id),false);
$function$;

-- A return hold is a fact of this same request and actual placement. It does
-- not require another queue/table or mutation of a terminal request receipt.
create or replace function private.timesheet_correction_draft_holds_v1(p_invoice_id uuid)
returns jsonb language sql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
  select coalesce(jsonb_agg(jsonb_build_object('request_id',request.id,'replacement_timesheet_id',request.replacement_timesheet_id,
    'return_invoice_id',request.return_invoice_id,'blocker_code','AGENCY_INVOICE_TIMESHEET_RETURNING') order by request.id),'[]'::jsonb)
  from private.timesheet_correction_requests request
  where request.return_invoice_id=p_invoice_id and request.state='APPLIED'
    and not private.timesheet_correction_replacement_empty_v1(request.id)
    and not coalesce((private.timesheet_correction_invoice_scope_v1(request.replacement_timesheet_id,p_invoice_id,null,false,100)
      ->>'placement_complete')::boolean,false);
$function$;

create or replace function private.timesheet_correction_draft_round_trip_v1(p_request_id uuid,p_action text,p_actor_user_id uuid)
returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare
  v_request private.timesheet_correction_requests%rowtype; v_invoice public.invoices%rowtype; v_action text:=upper(btrim(p_action));
  v_unrelated jsonb; v_lines jsonb; v_result jsonb; v_scope jsonb; v_fin public.timesheets_financials%rowtype;
begin
  perform private.timesheet_correction_actor_assert_v1(p_actor_user_id);
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id;
  if v_request.return_invoice_id is null then return jsonb_build_object('ok',true,'not_required',true); end if;
  select i.* into strict v_invoice from public.invoices i where i.id=v_request.return_invoice_id for update;
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id for update;
  if v_action not in('REMOVE','RETURN') or v_invoice.type<>'INVOICE' or v_invoice.status not in('DRAFT','ON_HOLD')
    or v_invoice.paid_at_utc is not null or v_invoice.client_id is distinct from v_request.client_id then
    raise exception 'AGENCY_ROUND_TRIP_INVOICE_NOT_DRAFT' using errcode='55000';
  end if;
  select coalesce(jsonb_agg(to_jsonb(l) order by l.id),'[]'::jsonb) into v_unrelated from public.invoice_lines l
    where l.invoice_id=v_invoice.id and l.timesheet_id is distinct from v_request.reversed_timesheet_id
      and l.timesheet_id is distinct from v_request.replacement_timesheet_id;
  if v_action='REMOVE' then
    if v_request.state<>'WAITING' or jsonb_array_length(private.timesheet_correction_draft_holds_v1(v_invoice.id))>0 then
      raise exception 'AGENCY_ROUND_TRIP_RETURN_HOLD_EXISTS' using errcode='55000';
    end if;
    if exists(select 1 from public.invoice_lines l where l.timesheet_id=v_request.reversed_timesheet_id and l.invoice_id<>v_invoice.id) then
      raise exception 'AGENCY_ROUND_TRIP_TARGET_MISMATCH' using errcode='55000';
    end if;
    select coalesce(jsonb_agg(l.id order by l.id),'[]'::jsonb) into v_lines from public.invoice_lines l
      where l.invoice_id=v_invoice.id and l.timesheet_id=v_request.reversed_timesheet_id;
    if jsonb_array_length(v_lines)=0 then raise exception 'AGENCY_ROUND_TRIP_ORIGINAL_PLACEMENT_CHANGED' using errcode='40001'; end if;
    v_result:=public.invoice_apply_edits(v_invoice.id,jsonb_build_object('remove_invoice_line_ids',v_lines),p_actor_user_id);
    if exists(select 1 from public.invoice_lines l where l.timesheet_id=v_request.reversed_timesheet_id) then
      raise exception 'AGENCY_ROUND_TRIP_REMOVE_NOT_PROVED' using errcode='55000';
    end if;
  else
    if v_request.state<>'APPLIED' then raise exception 'AGENCY_ROUND_TRIP_REQUEST_NOT_APPLIED' using errcode='55000'; end if;
    if exists(select 1 from public.invoice_lines l where l.timesheet_id in(v_request.reversed_timesheet_id,v_request.reversal_timesheet_id))
      or exists(select 1 from public.invoice_lines l where l.timesheet_id=v_request.replacement_timesheet_id and l.invoice_id<>v_invoice.id) then
      raise exception 'AGENCY_ROUND_TRIP_TARGET_MISMATCH' using errcode='55000';
    end if;
    if private.timesheet_correction_replacement_empty_v1(v_request.id) then
      if exists(select 1 from public.invoice_lines l where l.timesheet_id=v_request.replacement_timesheet_id) then
        raise exception 'AGENCY_ROUND_TRIP_EMPTY_REPLACEMENT_HAS_LINE' using errcode='55000';
      end if;
      return jsonb_build_object('ok',true,'return_invoice_id',v_invoice.id,'empty_replacement',true,'return_pending',false);
    end if;
    select tf.* into strict v_fin from public.timesheets_financials tf
      where tf.timesheet_id=v_request.replacement_timesheet_id and tf.is_current for update;
    if v_fin.authorised_at_utc is null or v_fin.is_stale or v_fin.processing_status<>'READY_FOR_INVOICE' then
      return jsonb_build_object('ok',true,'return_invoice_id',v_invoice.id,'return_pending',true,
        'blocker_code','AGENCY_INVOICE_TIMESHEET_RETURNING');
    end if;
    if exists(select 1 from public.invoice_lines l where l.invoice_id=v_invoice.id and l.timesheet_id=v_request.replacement_timesheet_id) then
      v_scope:=private.timesheet_correction_invoice_scope_v1(v_request.replacement_timesheet_id,v_invoice.id,p_actor_user_id,false,100);
      if (v_scope->>'valid')::boolean is distinct from true or (v_scope->>'placement_complete')::boolean is distinct from true then
        raise exception 'AGENCY_ROUND_TRIP_RETURN_COMPONENTS_UNPROVED' using errcode='55000';
      end if;
      return jsonb_build_object('ok',true,'return_invoice_id',v_invoice.id,'return_pending',false,'replayed',true);
    end if;
    v_result:=public.invoice_apply_edits(v_invoice.id,jsonb_build_object('add_timesheet_ids',jsonb_build_array(v_request.replacement_timesheet_id)),p_actor_user_id);
    if not exists(select 1 from public.invoice_lines l where l.invoice_id=v_invoice.id and l.timesheet_id=v_request.replacement_timesheet_id)
      or v_fin.locked_by_invoice_id is not null and v_fin.locked_by_invoice_id<>v_invoice.id then
      raise exception 'AGENCY_ROUND_TRIP_RETURN_NOT_PROVED' using errcode='55000';
    end if;
    v_scope:=private.timesheet_correction_invoice_scope_v1(v_request.replacement_timesheet_id,v_invoice.id,p_actor_user_id,false,100);
    if (v_scope->>'valid')::boolean is distinct from true or (v_scope->>'placement_complete')::boolean is distinct from true then
      raise exception 'AGENCY_ROUND_TRIP_RETURN_COMPONENTS_UNPROVED' using errcode='55000';
    end if;
  end if;
  if v_result->>'ok'='false' or v_result->>'success'='false'
    or (select i.invoice_no from public.invoices i where i.id=v_invoice.id) is distinct from v_invoice.invoice_no
    or (select coalesce(jsonb_agg(to_jsonb(l) order by l.id),'[]'::jsonb) from public.invoice_lines l
      where l.invoice_id=v_invoice.id and l.timesheet_id is distinct from v_request.reversed_timesheet_id
        and l.timesheet_id is distinct from v_request.replacement_timesheet_id) is distinct from v_unrelated then
    raise exception 'AGENCY_ROUND_TRIP_UNRELATED_PLACEMENT_CHANGED' using errcode='55000';
  end if;
  return jsonb_build_object('ok',true,'request_id',v_request.id,'action',v_action,'return_invoice_id',v_invoice.id,
    'invoice_no',v_invoice.invoice_no,'return_pending',v_action='REMOVE');
end;
$function$;

create or replace function public.timesheet_correction_return_to_draft_v1(p_request_id uuid,p_actor_user_id uuid)
returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
begin
  return private.timesheet_correction_draft_round_trip_v1(p_request_id,'RETURN',p_actor_user_id);
end;
$function$;

create or replace function public.invoice_correction_pair_scope_v1(
  p_timesheet_id uuid,
  p_target_invoice_id uuid default null,
  p_actor_user_id uuid default null,
  p_lock_rows boolean default true,
  p_max_members integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','extensions','pg_temp'
as $function$
declare
  v_chain jsonb;
  v_unit jsonb;
  v_envelope jsonb;
  v_ids uuid[]:=array[]::uuid[];
  v_expected_count integer;
  v_ready_count integer:=0;
  v_line_member_count integer:=0;
  v_line_invoice_count integer:=0;
  v_client_count integer:=0;
  v_contract_count integer:=0;
  v_week_count integer:=0;
  v_stream_count integer:=0;
  v_target public.invoices%rowtype;
  v_rows jsonb:='[]'::jsonb;
  v_errors jsonb:='[]'::jsonb;
  r record;
  v_leg jsonb;
  v_policy_ready boolean;
  v_expected_stream text;
  v_current_stream text;
  v_target_stream text;
  v_line_policy_mismatch_count integer:=0;
  v_reversal_line_count integer:=0;
  v_replacement_line_count integer:=0;
  v_reversal_invoice_ids uuid[]:=array[]::uuid[];
  v_replacement_invoice_ids uuid[]:=array[]::uuid[];
  v_placement_state text:='MALFORMED_PAIR';
  v_placement_compatible boolean:=false;
  v_placement_invoices jsonb:='[]'::jsonb;
  v_compatibility_mode text;
  v_operation public.import_apply_operations%rowtype;
  v_operation_unit jsonb;
  v_operation_unit_count integer:=0;
  v_balance jsonb;
  v_balance_row_count integer:=0;
  v_timesheet public.timesheets%rowtype;
  v_pair_correction_id text;
  v_pair_parent_id uuid;
  v_pair_operation_id uuid;
  v_pair_unit_fingerprint text;
  v_pair_source_identity text;
  v_pair_envelope_count integer:=0;
  v_pair_parent_count integer:=0;
  v_pair_member_count integer:=0;
  v_pair_reversal_count integer:=0;
  v_pair_replacement_count integer:=0;
  v_missing_ids uuid[]:=array[]::uuid[];
  v_recomputed_unit_fingerprint text;
begin
  v_unit:=private.timesheet_correction_invoice_scope_v1(p_timesheet_id,p_target_invoice_id,p_actor_user_id,p_lock_rows,p_max_members);
  if v_unit is not null then return v_unit; end if;
  if p_timesheet_id is null then raise exception 'INVOICE_CORRECTION_TIMESHEET_ID_REQUIRED' using errcode='22023'; end if;
  if p_max_members<1 or p_max_members>100 then raise exception 'INVOICE_CORRECTION_MEMBER_LIMIT_INVALID' using errcode='22023'; end if;
  if p_actor_user_id is not null then
    perform 1 from public.tms_users u where u.id=p_actor_user_id and coalesce(u.is_active,false);
    if not found then raise exception 'INVOICE_CORRECTION_ACTOR_INVALID' using errcode='42501'; end if;
  end if;

  v_chain:=public.timesheet_correction_chain_scope_v1(p_timesheet_id,p_lock_rows,32,p_max_members);
  if coalesce((v_chain->>'valid')::boolean,false) is not true then
    -- The ordinary whole-chain validator remains authoritative.  This narrowly
    -- gated fallback exists only for a current pair committed by the reviewed
    -- authoritative-import reconciliation path when an older issued row was
    -- physically removed but its frozen invoice evidence remains provable.
    select * into v_timesheet from public.timesheets
    where timesheet_id=p_timesheet_id and is_current and archived_at_utc is null;
    if v_timesheet.timesheet_id is null
       or not coalesce(v_timesheet.is_adjustment,false)
       or upper(coalesce(v_timesheet.adjustment_origin,''))<>'IMPORT_CORRECTION'
       or v_timesheet.correction_kind not in ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')
       or v_timesheet.correction_id is null
       or coalesce(v_timesheet.candidate_hint_text#>>'{import_authoritative_reconciliation,operation_id}','')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception 'INVOICE_CORRECTION_CHAIN_INVALID' using errcode='P0001',detail=v_chain::text;
    end if;
    v_pair_correction_id:=v_timesheet.correction_id;
    v_pair_operation_id:=(v_timesheet.candidate_hint_text#>>'{import_authoritative_reconciliation,operation_id}')::uuid;
    v_pair_unit_fingerprint:=nullif(v_timesheet.candidate_hint_text#>>'{import_authoritative_reconciliation,unit_fingerprint}','');
    v_pair_source_identity:=nullif(v_timesheet.candidate_hint_text#>>'{import_authoritative_reconciliation,source_identity}','');

    select * into v_operation from public.import_apply_operations o
    where o.id=v_pair_operation_id and o.state='COMPLETE' and o.committed_at_utc is not null;
    if v_operation.id is null then
      raise exception 'INVOICE_CORRECTION_CHAIN_INVALID' using errcode='P0001',detail=v_chain::text;
    end if;
    select count(*)::integer,min(u::text)::jsonb into v_operation_unit_count,v_operation_unit
    from jsonb_array_elements(case when jsonb_typeof(v_operation.response_json->'reconciliation_units')='array'
      then v_operation.response_json->'reconciliation_units' else '[]'::jsonb end) u
    where u->>'schema_version'='IMPORT_AUTHORITATIVE_RECONCILIATION_V1'
      and u->>'correction_id'=v_pair_correction_id
      and u->>'source_identity'=v_pair_source_identity
      and u->>'unit_fingerprint'=v_pair_unit_fingerprint
      and u->>'route' in ('AMEND_EXISTING_REPLACEMENT','CREATE_REVERSAL_REPLACEMENT');
    if v_operation_unit_count<>1 then
      raise exception 'INVOICE_CORRECTION_CHAIN_INVALID' using errcode='P0001',detail=v_chain::text;
    end if;

    select public._import_review_hash_v1(concat_ws('|','unit-v1',
      v_operation_unit->>'action_id',v_operation_unit->>'source_identity',v_operation_unit->>'route',
      v_operation_unit->>'reconciliation_fingerprint',outcome.evidence_fingerprint))
    into v_recomputed_unit_fingerprint
    from public.import_review_action_outcomes outcome
    where outcome.operation_id=v_operation.id and outcome.action_id=v_operation_unit->>'action_id';
    if v_recomputed_unit_fingerprint is distinct from v_operation_unit->>'unit_fingerprint' then
      raise exception 'INVOICE_CORRECTION_RECONCILIATION_STALE' using errcode='40001';
    end if;

    select count(*)::integer,
      count(*) filter(where t.correction_kind='CHANGED_HOURS_REVERSAL')::integer,
      count(*) filter(where t.correction_kind='CHANGED_HOURS_REPLACEMENT')::integer,
      count(distinct t.parent_timesheet_id)::integer,
      min(t.parent_timesheet_id),
      count(distinct coalesce(
        t.candidate_hint_text#>>'{correction_financials_policy_envelope,envelope_fingerprint}',
        tf.policy_snapshot_json#>>'{correction_financials_policy_envelope,envelope_fingerprint}'
      ))::integer,
      coalesce(array_agg(t.timesheet_id order by t.correction_kind,t.timesheet_id),array[]::uuid[])
    into v_pair_member_count,v_pair_reversal_count,v_pair_replacement_count,
      v_pair_parent_count,v_pair_parent_id,v_pair_envelope_count,v_ids
    from public.timesheets t
    left join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
    where t.correction_id=v_pair_correction_id and t.is_current and t.archived_at_utc is null
      and t.correction_kind in ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')
      and t.adjustment_origin='IMPORT_CORRECTION'
      and t.candidate_hint_text#>>'{import_authoritative_reconciliation,operation_id}'=v_operation.id::text
      and t.candidate_hint_text#>>'{import_authoritative_reconciliation,unit_fingerprint}'=v_pair_unit_fingerprint
      and t.candidate_hint_text#>>'{import_authoritative_reconciliation,source_identity}'=v_pair_source_identity;
    if v_pair_member_count<>2 or v_pair_reversal_count<>1 or v_pair_replacement_count<>1
       or v_pair_parent_count<>1 or v_pair_parent_id is null or v_pair_envelope_count<>1
       or v_pair_parent_id is distinct from (v_operation_unit->>'parent_timesheet_id')::uuid
       or not exists(select 1 from public.timesheets parent_ts where parent_ts.timesheet_id=v_pair_parent_id
          and parent_ts.is_current and parent_ts.archived_at_utc is null) then
      raise exception 'INVOICE_CORRECTION_CHAIN_INVALID' using errcode='P0001',detail=v_chain::text;
    end if;
    if exists(select 1 from public.timesheets t left join public.timesheets_financials tf
        on tf.timesheet_id=t.timesheet_id and tf.is_current
      where t.timesheet_id=any(v_ids) and (
        t.contract_id is distinct from (v_operation_unit->>'contract_id')::uuid
        or t.week_ending_date is distinct from (v_operation_unit->>'week_ending_date')::date
        or tf.candidate_id is distinct from (v_operation_unit->>'candidate_id')::uuid
        or tf.client_id is distinct from (v_operation_unit->>'client_id')::uuid
        or jsonb_typeof(t.actual_schedule_json)<>'array'
        or jsonb_array_length(t.actual_schedule_json)<>1
        or not t.actual_schedule_json @> jsonb_build_array(jsonb_build_object(
          'shift_id',v_operation_unit->>'source_shift_id','external_row_key',v_operation_unit->>'source_identity'))
        or (t.correction_kind='CHANGED_HOURS_REVERSAL' and (
          (t.actual_schedule_json#>>'{0,start_utc}')::timestamptz is distinct from (v_operation_unit#>>'{B_standard_schedule_json,0,start_utc}')::timestamptz
          or (t.actual_schedule_json#>>'{0,end_utc}')::timestamptz is distinct from (v_operation_unit#>>'{B_standard_schedule_json,0,end_utc}')::timestamptz
          or coalesce((t.actual_schedule_json#>>'{0,break_mins}')::integer,0) is distinct from coalesce((v_operation_unit#>>'{B_standard_schedule_json,0,break_mins}')::integer,0)))
        or (t.correction_kind='CHANGED_HOURS_REPLACEMENT' and (
          (t.actual_schedule_json#>>'{0,start_utc}')::timestamptz is distinct from (v_operation_unit#>>'{A_schedule_json,0,start_utc}')::timestamptz
          or (t.actual_schedule_json#>>'{0,end_utc}')::timestamptz is distinct from (v_operation_unit#>>'{A_schedule_json,0,end_utc}')::timestamptz
          or coalesce((t.actual_schedule_json#>>'{0,break_mins}')::integer,0) is distinct from coalesce((v_operation_unit#>>'{A_schedule_json,0,break_mins}')::integer,0)))
      )) then
      raise exception 'INVOICE_CORRECTION_RECONCILIATION_STALE' using errcode='40001';
    end if;

    select coalesce(array_agg(x.value::uuid order by x.value::uuid),array[]::uuid[]) into v_missing_ids
    from jsonb_array_elements_text(coalesce(v_operation_unit->'historical_missing_timesheet_ids','[]'::jsonb)) x(value);
    if cardinality(v_missing_ids)=0
       or exists(select 1 from unnest(v_missing_ids) missing_id
          where exists(select 1 from public.timesheets t where t.timesheet_id=missing_id)
             or not exists(select 1 from public.invoice_lines il join public.invoices i on i.id=il.invoice_id
               where (il.timesheet_id=missing_id or il.meta_json->>'timesheet_id'=missing_id::text)
                 and i.status in ('ISSUED','PAID','ON_HOLD') and i.issued_at_utc is not null)
             or not exists(select 1 from public.audit_events ae where ae.object_type='timesheets'
               and ae.object_id_text=missing_id::text
               and ae.action in ('NHSP_IMPORT_CORRECTION_APPLIED','HR_IMPORT_CORRECTION_APPLIED')))
       or exists(select 1 from jsonb_array_elements(coalesce(v_chain->'errors','[]'::jsonb)) e
          where e->>'code'<>'CORRECTION_UNIT_INVALID') then
      raise exception 'INVOICE_CORRECTION_CHAIN_INVALID' using errcode='P0001',detail=v_chain::text;
    end if;

    select count(*)::integer,min(b.balance_json::text)::jsonb into v_balance_row_count,v_balance
    from public._import_review_effective_invoice_balance_core_v1(
      v_operation.import_id,
      jsonb_build_array(jsonb_build_object(
        'source_identity',v_operation_unit->>'source_identity','source_system',v_operation_unit->>'source_system',
        'source_shift_id',v_operation_unit->>'source_shift_id','external_row_key',v_operation_unit->>'source_identity',
        'hr_row_id',v_operation_unit->>'hr_row_id','source_timesheet_id',v_operation_unit->>'source_timesheet_id',
        'candidate_id',v_operation_unit->>'candidate_id','client_id',v_operation_unit->>'client_id',
        'contract_id',v_operation_unit->>'contract_id','week_ending_date',v_operation_unit->>'week_ending_date',
        'invoice_stream',v_operation_unit->>'invoice_stream','authoritative_import_id',v_operation.import_id,
        'authoritative_schedule_json',v_operation_unit->'A_schedule_json','authoritative_hours',v_operation_unit->'A_hours'
      )),1,512,256,128
    ) b;
    if v_balance_row_count<>1 or nullif(v_balance->>'blocking_code','') is not null
       or v_balance->>'effective_invoice_fingerprint' is distinct from v_operation_unit->>'B_invoice_fingerprint'
       or v_balance->'historical_missing_timesheet_ids' is distinct from to_jsonb(v_missing_ids) then
      raise exception 'INVOICE_CORRECTION_RECONCILIATION_STALE' using errcode='40001';
    end if;
    if exists(select 1 from public.timesheets t join public.timesheets_financials tf
        on tf.timesheet_id=t.timesheet_id and tf.is_current
      where t.timesheet_id=any(v_ids) and (
        coalesce(tf.is_stale,true) or coalesce(tf.has_rate_issue,false) or coalesce(tf.has_pay_channel_issue,false)
        or (t.correction_kind='CHANGED_HOURS_REVERSAL' and (
          tf.hours_day<>-coalesce((v_operation_unit#>>'{B_hours,hours_day}')::numeric,0)
          or tf.hours_night<>-coalesce((v_operation_unit#>>'{B_hours,hours_night}')::numeric,0)
          or tf.hours_sat<>-coalesce((v_operation_unit#>>'{B_hours,hours_sat}')::numeric,0)
          or tf.hours_sun<>-coalesce((v_operation_unit#>>'{B_hours,hours_sun}')::numeric,0)
          or tf.hours_bh<>-coalesce((v_operation_unit#>>'{B_hours,hours_bh}')::numeric,0)
          or tf.total_pay_ex_vat<>-coalesce((v_operation_unit#>>'{B_financials,pay_ex_vat}')::numeric,0)
          or tf.total_charge_ex_vat<>-coalesce((v_operation_unit#>>'{B_financials,charge_ex_vat}')::numeric,0)
          or tf.margin_ex_vat<>-coalesce((v_operation_unit#>>'{B_financials,margin_ex_vat}')::numeric,0)))
        or (t.correction_kind='CHANGED_HOURS_REPLACEMENT' and (
          tf.hours_day<>coalesce((v_operation_unit#>>'{A_hours,hours_day}')::numeric,0)
          or tf.hours_night<>coalesce((v_operation_unit#>>'{A_hours,hours_night}')::numeric,0)
          or tf.hours_sat<>coalesce((v_operation_unit#>>'{A_hours,hours_sat}')::numeric,0)
          or tf.hours_sun<>coalesce((v_operation_unit#>>'{A_hours,hours_sun}')::numeric,0)
          or tf.hours_bh<>coalesce((v_operation_unit#>>'{A_hours,hours_bh}')::numeric,0)))
      )) then
      raise exception 'INVOICE_CORRECTION_RECONCILIATION_STALE' using errcode='40001';
    end if;

    v_envelope:=public._ctms_correction_policy_envelope_read_v1(p_timesheet_id);
    v_unit:=jsonb_build_object('valid',true,'correction_id',v_pair_correction_id,
      'correction_shape','REVERSAL_REPLACEMENT','expected_member_count',2,
      'member_ids',to_jsonb(v_ids),'policy_envelope',v_envelope);
    v_chain:=jsonb_build_object('root_timesheet_id',v_envelope->>'root_timesheet_id');
    v_compatibility_mode:='IMPORT_AUTHORITATIVE_RECONCILIATION_V1';
  else
    v_unit:=v_chain->'requested_correction_unit';
  end if;
  if jsonb_typeof(v_unit)<>'object' or coalesce((v_unit->>'valid')::boolean,false) is not true then
    raise exception 'INVOICE_CORRECTION_UNIT_INVALID' using errcode='P0001';
  end if;
  v_envelope:=v_unit->'policy_envelope';
  v_expected_stream:=upper(btrim(coalesce(v_envelope->>'invoice_stream','')));
  if v_expected_stream not in ('NORMAL','SELF_BILL') then
    raise exception 'INVOICE_CORRECTION_FROZEN_STREAM_INVALID' using errcode='P0001';
  end if;
  v_expected_count:=(v_unit->>'expected_member_count')::integer;
  select coalesce(array_agg(value::uuid order by value::text),array[]::uuid[])
  into v_ids from jsonb_array_elements_text(v_unit->'member_ids');
  if cardinality(v_ids)<>v_expected_count then raise exception 'INVOICE_CORRECTION_MEMBER_COUNT_MISMATCH' using errcode='P0001'; end if;

  if p_lock_rows then
    perform 1 from public.timesheets ts where ts.timesheet_id=any(v_ids) order by ts.timesheet_id for update;
    perform 1 from public.timesheets_financials tf where tf.timesheet_id=any(v_ids) and tf.is_current=true
      order by tf.timesheet_id,tf.id for update;
  end if;

  if p_target_invoice_id is not null then
    if p_lock_rows then select * into v_target from public.invoices where id=p_target_invoice_id for update;
    else select * into v_target from public.invoices where id=p_target_invoice_id; end if;
    if not found then raise exception 'INVOICE_CORRECTION_TARGET_NOT_FOUND' using errcode='P0002'; end if;
    if upper(coalesce(v_target.status::text,''))<>'DRAFT' or v_target.issued_at_utc is not null then
      raise exception 'INVOICE_CORRECTION_TARGET_NOT_APPENDABLE' using errcode='P0001',
        detail=jsonb_build_object('invoice_id',p_target_invoice_id,'status',v_target.status,'issued_at_utc',v_target.issued_at_utc)::text;
    end if;
    v_target_stream:=case
      when lower(coalesce(v_target.header_snapshot_json#>>'{meta,self_bill}','false'))='true'
        then 'SELF_BILL' else 'NORMAL' end;
    if v_target_stream is distinct from v_expected_stream then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'code','INVOICE_CORRECTION_TARGET_STREAM_MISMATCH',
        'expected_stream',v_expected_stream,
        'target_stream',v_target_stream
      ));
    end if;
  end if;

  for r in
    select ts.timesheet_id,ts.correction_kind,ts.contract_id,ts.week_ending_date,
      tf.id tsfin_id,tf.client_id,tf.basis,tf.processing_status,tf.is_stale,
      tf.policy_snapshot_json,tf.rate_source_refs_json,tf.pay_vat_rate_pct_snapshot,
      c.self_bill
    from public.timesheets ts
    left join public.timesheets_financials tf on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
    left join public.contracts c on c.id=ts.contract_id
    where ts.timesheet_id=any(v_ids)
    order by ts.timesheet_id
  loop
    v_leg:=public._ctms_correction_policy_leg_read_v1(r.timesheet_id);
    v_current_stream:=case
      when upper(coalesce(r.basis::text,'')) in (
        'NHSP','NHSP_ADJUSTMENT',
        'HEALTHROSTER_SELF_BILL','HEALTHROSTER_ADJUSTMENT'
      ) then 'SELF_BILL'
      else 'NORMAL'
    end;
    v_policy_ready:=
      coalesce(r.policy_snapshot_json->>'correction_financials_policy_envelope_fingerprint',
               r.policy_snapshot_json#>>'{correction_financials_policy_envelope,envelope_fingerprint}',
               r.rate_source_refs_json->>'correction_financials_policy_envelope_fingerprint')
        is not distinct from v_envelope->>'envelope_fingerprint'
      and coalesce(r.policy_snapshot_json->>'correction_leg_fingerprint',r.rate_source_refs_json->>'correction_leg_fingerprint')
        is not distinct from v_leg->>'leg_fingerprint'
      and coalesce(r.policy_snapshot_json->>'correction_tsfin_policy_fingerprint',r.rate_source_refs_json->>'correction_tsfin_policy_fingerprint')
        is not distinct from v_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}'
      and coalesce(r.policy_snapshot_json->>'correction_invoice_policy_fingerprint',r.rate_source_refs_json->>'correction_invoice_policy_fingerprint')
        is not distinct from v_leg#>>'{invoice_policy,invoice_policy_fingerprint}'
      and r.policy_snapshot_json->'correction_invoice_policy'
        is not distinct from v_leg->'invoice_policy'
      and upper(btrim(coalesce(r.policy_snapshot_json->>'correction_invoice_stream','')))
        is not distinct from v_expected_stream
      and upper(btrim(coalesce(v_leg#>>'{invoice_policy,invoice_stream}','')))
        is not distinct from v_expected_stream
      and v_current_stream is not distinct from v_expected_stream;
    if r.tsfin_id is not null and not coalesce(r.is_stale,false)
       and r.processing_status='READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
       and v_policy_ready then v_ready_count:=v_ready_count+1; end if;
    if not v_policy_ready then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','INVOICE_CORRECTION_POLICY_NOT_FROZEN','timesheet_id',r.timesheet_id)); end if;
    v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
      'timesheet_id',r.timesheet_id,'correction_kind',r.correction_kind,'tsfin_id',r.tsfin_id,
      'client_id',r.client_id,'contract_id',r.contract_id,'week_ending_date',r.week_ending_date,
       'invoice_stream',v_expected_stream,'current_contract_stream',v_current_stream,
       'processing_status',r.processing_status,'policy_ready',v_policy_ready,
       'invoice_vat_chargeable',v_leg#>'{invoice_policy,invoice_vat_chargeable}',
       'invoice_vat_rate_pct',v_leg#>'{invoice_policy,applied_vat_rate_pct}',
       'invoice_policy_fingerprint',v_leg#>>'{invoice_policy,invoice_policy_fingerprint}',
       'leg_fingerprint',v_leg->>'leg_fingerprint'));
  end loop;

  select count(distinct tf.client_id),count(distinct ts.contract_id),count(distinct ts.week_ending_date),
    count(distinct case
      when upper(coalesce(tf.basis::text,'')) in (
        'NHSP','NHSP_ADJUSTMENT',
        'HEALTHROSTER_SELF_BILL','HEALTHROSTER_ADJUSTMENT'
      ) then 'SELF_BILL'
      else 'NORMAL'
    end)
  into v_client_count,v_contract_count,v_week_count,v_stream_count
  from public.timesheets ts
  join public.timesheets_financials tf on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
  where ts.timesheet_id=any(v_ids);

  select count(distinct il.timesheet_id),count(distinct il.invoice_id)
  into v_line_member_count,v_line_invoice_count
  from public.invoice_lines il
  join public.invoices i on i.id=il.invoice_id
  where il.timesheet_id=any(v_ids)
    and upper(coalesce(i.type::text,''))<>'CREDIT_NOTE';

  select
    count(il.invoice_id) filter(where ts.correction_kind='CHANGED_HOURS_REVERSAL')::integer,
    count(il.invoice_id) filter(where ts.correction_kind='CHANGED_HOURS_REPLACEMENT')::integer,
    coalesce(array_agg(il.invoice_id order by il.invoice_id)
      filter(where ts.correction_kind='CHANGED_HOURS_REVERSAL'),array[]::uuid[]),
    coalesce(array_agg(il.invoice_id order by il.invoice_id)
      filter(where ts.correction_kind='CHANGED_HOURS_REPLACEMENT'),array[]::uuid[])
  into v_reversal_line_count,v_replacement_line_count,
       v_reversal_invoice_ids,v_replacement_invoice_ids
  from public.timesheets ts
  left join public.invoice_lines il on il.timesheet_id=ts.timesheet_id
    and exists(select 1 from public.invoices active_invoice where active_invoice.id=il.invoice_id
      and upper(coalesce(active_invoice.type::text,''))<>'CREDIT_NOTE')
  where ts.timesheet_id=any(v_ids);

  select coalesce(jsonb_agg(jsonb_build_object(
    'invoice_id',i.id,'status',i.status,'issued_at_utc',i.issued_at_utc,
    'client_id',i.client_id,
    'invoice_stream',case when lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false'))='true'
      then 'SELF_BILL' else 'NORMAL' end,
    'currency',upper(coalesce(nullif(i.header_snapshot_json->>'currency',''),nullif(i.header_snapshot_json#>>'{meta,currency}',''),'GBP')),
    'invoice_week',coalesce(i.header_snapshot_json#>>'{meta,invoice_week_start}',
      i.header_snapshot_json->>'week_ending_date',i.header_snapshot_json#>>'{meta,week_ending_date}'))
    order by i.id),'[]'::jsonb)
  into v_placement_invoices
  from public.invoices i
  where i.id=any(v_reversal_invoice_ids||v_replacement_invoice_ids);

  if v_expected_count<>2 then
    v_placement_state:='MALFORMED_PAIR';
  elsif v_reversal_line_count>1 or v_replacement_line_count>1 then
    v_placement_state:='DUPLICATE_PLACEMENT';
  elsif v_reversal_line_count=0 and v_replacement_line_count=0 then
    v_placement_state:='UNPLACED';
    v_placement_compatible:=true;
  elsif (v_reversal_line_count=1 and v_replacement_line_count=0)
     or (v_reversal_line_count=0 and v_replacement_line_count=1) then
    v_placement_state:='INCOMPLETE_MOVE';
    v_placement_compatible:=true;
  elsif v_reversal_invoice_ids[1]=v_replacement_invoice_ids[1] then
    v_placement_state:='COMPLETE_SAME_INVOICE';
    v_placement_compatible:=true;
  else
    select count(distinct i.client_id)=1
       and count(distinct case when lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false'))='true'
         then 'SELF_BILL' else 'NORMAL' end)=1
       and count(distinct upper(coalesce(nullif(i.header_snapshot_json->>'currency',''),
         nullif(i.header_snapshot_json#>>'{meta,currency}',''),'GBP')))=1
       and count(distinct coalesce(i.header_snapshot_json#>>'{meta,invoice_week_start}',i.header_snapshot_json->>'week_ending_date',
         i.header_snapshot_json#>>'{meta,week_ending_date}',(select min(ts.week_ending_date)::text
           from public.timesheets ts where ts.timesheet_id=any(v_ids))))=1
    into v_placement_compatible
    from public.invoices i
    where i.id=any(v_reversal_invoice_ids||v_replacement_invoice_ids);
    v_placement_state:=case when v_placement_compatible then 'COMPLETE_SPLIT_INVOICES'
      else 'INCOMPATIBLE_PLACEMENT' end;
  end if;

  select count(*)::integer into v_line_policy_mismatch_count
  from public.invoice_lines il
  cross join lateral (
    select public._ctms_correction_policy_leg_read_v1(il.timesheet_id) leg
  ) expected
  where il.timesheet_id=any(v_ids)
    and (p_target_invoice_id is null or il.invoice_id=p_target_invoice_id)
    and il.vat_rate_pct is distinct from
      (expected.leg#>>'{invoice_policy,applied_vat_rate_pct}')::numeric;

  if v_ready_count<>v_expected_count then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','INVOICE_CORRECTION_TSFIN_NOT_READY','ready_count',v_ready_count)); end if;
  if v_client_count<>1 or v_contract_count<>1 or v_week_count<>1 or v_stream_count<>1 then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','INVOICE_CORRECTION_SCOPE_MIXED'));
  end if;
  if exists (
    select 1
    from public.timesheets ts
    join public.timesheets_financials tf
      on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
    where ts.timesheet_id=any(v_ids)
      and (case
        when upper(coalesce(tf.basis::text,'')) in (
          'NHSP','NHSP_ADJUSTMENT',
          'HEALTHROSTER_SELF_BILL','HEALTHROSTER_ADJUSTMENT'
        ) then 'SELF_BILL'
        else 'NORMAL'
      end)
        is distinct from v_expected_stream
  ) then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
      'code','INVOICE_CORRECTION_FROZEN_STREAM_DRIFT',
      'expected_stream',v_expected_stream
    ));
  end if;
  if v_placement_state='DUPLICATE_PLACEMENT' then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','INVOICE_CORRECTION_PAIR_DUPLICATE_PLACEMENT'));
  elsif v_placement_state='INCOMPATIBLE_PLACEMENT' then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','INVOICE_CORRECTION_PAIR_INCOMPATIBLE_PLACEMENT'));
  elsif v_placement_state='MALFORMED_PAIR' then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','INVOICE_CORRECTION_PAIR_MALFORMED'));
  end if;
  if v_line_policy_mismatch_count<>0 then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
      'code','INVOICE_CORRECTION_LINE_VAT_POLICY_MISMATCH',
      'mismatching_line_count',v_line_policy_mismatch_count
    ));
  end if;
  if p_target_invoice_id is not null and v_target.client_id is distinct from (select tf.client_id from public.timesheets_financials tf where tf.timesheet_id=v_ids[1] and tf.is_current=true) then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','INVOICE_CORRECTION_TARGET_CLIENT_MISMATCH'));
  end if;
  if p_target_invoice_id is not null and v_placement_state='INCOMPLETE_MOVE'
     and exists (
       select 1
       from public.invoices placed
       where placed.id=any(v_reversal_invoice_ids||v_replacement_invoice_ids)
         and placed.id<>p_target_invoice_id
         and (
           placed.client_id is distinct from v_target.client_id
           or (case when lower(coalesce(placed.header_snapshot_json#>>'{meta,self_bill}','false'))='true'
                 then 'SELF_BILL' else 'NORMAL' end) is distinct from v_target_stream
           or upper(coalesce(nullif(placed.header_snapshot_json->>'currency',''),
                nullif(placed.header_snapshot_json#>>'{meta,currency}',''),'GBP'))
              is distinct from upper(coalesce(nullif(v_target.header_snapshot_json->>'currency',''),
                nullif(v_target.header_snapshot_json#>>'{meta,currency}',''),'GBP'))
           or coalesce(placed.header_snapshot_json#>>'{meta,invoice_week_start}',placed.header_snapshot_json->>'week_ending_date',
                placed.header_snapshot_json#>>'{meta,week_ending_date}',(select min(ts.week_ending_date)::text from public.timesheets ts where ts.timesheet_id=any(v_ids)))
              is distinct from coalesce(v_target.header_snapshot_json#>>'{meta,invoice_week_start}',v_target.header_snapshot_json->>'week_ending_date',
                v_target.header_snapshot_json#>>'{meta,week_ending_date}',(select min(ts.week_ending_date)::text from public.timesheets ts where ts.timesheet_id=any(v_ids)))
         )
     ) then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
      'code','INVOICE_CORRECTION_TARGET_INCOMPATIBLE_WITH_PARTNER'));
  end if;

  return jsonb_build_object(
    'ok',true,'valid',jsonb_array_length(v_errors)=0,'root_timesheet_id',v_chain->>'root_timesheet_id',
    'correction_id',v_unit->>'correction_id','correction_shape',v_unit->>'correction_shape',
    'expected_member_count',v_expected_count,'pair_timesheet_ids',to_jsonb(v_ids),
    'target_invoice_id',p_target_invoice_id,'target_appendable',p_target_invoice_id is null or jsonb_array_length(v_errors)=0,
    'correction_financials_policy_envelope',v_envelope,
    'correction_financials_policy_envelope_fingerprint',v_envelope->>'envelope_fingerprint',
    'invoice_stream',v_expected_stream,
    'pair_rows',v_rows,'ready_count',v_ready_count,'existing_line_member_count',v_line_member_count,
    'existing_line_invoice_count',v_line_invoice_count,
    'placement_state',v_placement_state,
    'placement_complete',v_placement_state in ('COMPLETE_SAME_INVOICE','COMPLETE_SPLIT_INVOICES'),
    'placement_compatible',v_placement_compatible,
    'placement_invoices',v_placement_invoices,
    'reversal_invoice_ids',to_jsonb(v_reversal_invoice_ids),
    'replacement_invoice_ids',to_jsonb(v_replacement_invoice_ids),
    'missing_member_kind',case
      when v_placement_state='INCOMPLETE_MOVE' and v_reversal_line_count=0 then 'CHANGED_HOURS_REVERSAL'
      when v_placement_state='INCOMPLETE_MOVE' and v_replacement_line_count=0 then 'CHANGED_HOURS_REPLACEMENT' end,
    'line_policy_mismatch_count',v_line_policy_mismatch_count,'errors',v_errors,
    'compatibility_mode',v_compatibility_mode);
end;
$function$;

-- The Worker supplies output from the existing bounded canonical producer.
-- This file validates authority and delegates; it contains no rate calculator.
-- Exact sign-copy only. For missing A0 this runs inside the approval unit,
-- after the unchanged canonical writer has produced the real stored original.
create or replace function private.timesheet_correction_component_negate_v1(p_value jsonb,p_path text[] default array[]::text[])
returns jsonb language plpgsql immutable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare result jsonb; item record; key_name text; signed_value boolean;
begin
  if cardinality(p_path)>32 then raise exception 'CORRECTION_REVERSAL_COMPONENT_DEPTH_INVALID' using errcode='55000'; end if;
  if jsonb_typeof(p_value)='object' then
    result:='{}'::jsonb;
    for item in select key,value from jsonb_each(p_value) loop
      if item.key not in('invoice_locked_invoice_id','invoice_locked_at_utc','pay_locked','pay_locked_at_utc','is_reversal') then
        result:=result||jsonb_build_object(item.key,private.timesheet_correction_component_negate_v1(item.value,p_path||item.key));
      end if;
    end loop;
    if p_value?'is_reversal' then result:=result||jsonb_build_object('is_reversal',true); end if;
    return result;
  elsif jsonb_typeof(p_value)='array' then
    select coalesce(jsonb_agg(private.timesheet_correction_component_negate_v1(value,p_path||ordinality::text) order by ordinality),'[]'::jsonb)
      into result from jsonb_array_elements(p_value) with ordinality;
    return result;
  end if;
  key_name:=p_path[cardinality(p_path)];
  signed_value:=key_name in('hours_day','hours_night','hours_sat','hours_sun','hours_bh','hours_total','total_hours',
    'pay_amount','charge_amount','pay_ex_vat','charge_ex_vat','margin_ex_vat','total_pay_ex_vat','total_charge_ex_vat',
    'unit_count','units','total_units','units_total','pay_cost_ex_vat_including_erni','vat_amount','total_inc_vat')
    or (cardinality(p_path)>1 and p_path[cardinality(p_path)-1]='days')
    or (cardinality(p_path)>1 and p_path[cardinality(p_path)-1]='base_hours' and key_name in('day','night','sat','sun','bh'));
  if signed_value and jsonb_typeof(p_value)<>'null' then
    if not pg_input_is_valid(p_value#>>'{}','numeric') then raise exception 'CORRECTION_REVERSAL_COMPONENT_NUMERIC_INVALID' using errcode='55000'; end if;
    return case when jsonb_typeof(p_value)='string' then to_jsonb((-(p_value#>>'{}')::numeric)::text)
      else to_jsonb(-(p_value#>>'{}')::numeric) end;
  end if;
  return p_value;
end;
$function$;

create or replace function private.timesheet_correction_native_original_reversal_v1(p_original jsonb,p_reversal_id uuid)
returns jsonb language plpgsql immutable security definer
set search_path to 'pg_catalog','private','pg_temp'
as $function$
declare result jsonb; key_name text;
begin
  if jsonb_typeof(p_original) is distinct from 'object' or p_reversal_id is null
    or jsonb_typeof(p_original->'invoice_breakdown_json') is distinct from 'object' then
    raise exception 'CORRECTION_NATIVE_ORIGINAL_REVERSAL_CONTEXT_INVALID' using errcode='55000';
  end if;
  result:=p_original-array['id','created_at','updated_at','computed_at_utc','processed_at_utc','processed_by_user_id',
    'payment_reference','remittance_last_sent_at_utc','remittance_send_count','unlocked_by_credit_note_id'];
  foreach key_name in array array['hours_day','hours_night','hours_sat','hours_sun','hours_bh','total_hours',
    'total_pay_ex_vat','total_charge_ex_vat','margin_ex_vat','pay_vat_amount_snapshot','pay_total_inc_vat_snapshot',
    'expenses_pay_ex_vat','expenses_charge_ex_vat','travel_pay_ex_vat','travel_charge_ex_vat',
    'accommodation_pay_ex_vat','accommodation_charge_ex_vat','other_pay_ex_vat','other_charge_ex_vat',
    'mileage_units','mileage_pay_ex_vat','mileage_charge_ex_vat','additional_pay_ex_vat','additional_charge_ex_vat','additional_margin_ex_vat'] loop
    if result?key_name and jsonb_typeof(result->key_name)<>'null' then
      if not pg_input_is_valid(result->>key_name,'numeric') then raise exception 'CORRECTION_NATIVE_ORIGINAL_AMOUNT_INVALID' using errcode='55000',detail=key_name; end if;
      result:=jsonb_set(result,array[key_name],case when jsonb_typeof(result->key_name)='string'
        then to_jsonb((-(result->>key_name)::numeric)::text) else to_jsonb(-(result->>key_name)::numeric) end,true);
    end if;
  end loop;
  result:=result||jsonb_build_object('timesheet_id',p_reversal_id,'timesheet_version',1,'processing_status','PENDING_AUTH',
    'authorised_at_utc',null,'authorised_by_user_id',null,'paid_at_utc',null,'paid_by_user_id',null,
    'locked_by_invoice_id',null,'locked_at_utc',null,'pay_on_hold',false,'pay_on_hold_reason',null,'pay_on_hold_since_utc',null,
    'is_current',true,'is_stale',false,'stale_reason',null,
    'invoice_breakdown_json',private.timesheet_correction_component_negate_v1(p_original->'invoice_breakdown_json'),
    'additional_units_json',private.timesheet_correction_component_negate_v1(p_original->'additional_units_json',array['additional_units_json']));
  return result;
end;
$function$;

create or replace function private.timesheet_correction_snapshot_identity_assert_v1(
  p_snapshot jsonb,p_timesheet_id uuid,p_version integer,p_candidate uuid,p_client uuid
) returns void language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
begin
  if jsonb_typeof(p_snapshot) is distinct from 'object'
    or p_snapshot->>'timesheet_id' is distinct from p_timesheet_id::text
    or p_snapshot->>'timesheet_version' is distinct from p_version::text
    or p_snapshot->>'candidate_id' is distinct from p_candidate::text
    or p_snapshot->>'client_id' is distinct from p_client::text
    or coalesce((p_snapshot->>'is_stale')::boolean,true)
    or coalesce((p_snapshot->>'has_rate_issue')::boolean,true)
    or coalesce((p_snapshot->>'has_pay_channel_issue')::boolean,true)
    or nullif(btrim(p_snapshot->>'pay_method'),'') is null
    or jsonb_typeof(p_snapshot->'invoice_breakdown_json') is distinct from 'object'
    or nullif(p_snapshot->>'authorised_at_utc','') is not null
    or nullif(p_snapshot->>'paid_at_utc','') is not null
    or nullif(p_snapshot->>'locked_by_invoice_id','') is not null then
    raise exception 'CORRECTION_CANONICAL_SNAPSHOT_INVALID' using errcode='55000';
  end if;
end;
$function$;

-- Compare monetary/hour facts, historic policy/rate identity and every exact
-- component. The caller, rather than SQL, creates the canonical reversal.
create or replace function private.timesheet_correction_reversal_component_assert_v1(
  p_original jsonb,p_reversal jsonb,p_path text[] default array[]::text[]
) returns void language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_original jsonb; v_reversal jsonb; v_row record; v_key text; v_signed boolean;
begin
  if cardinality(p_path)>32 or jsonb_typeof(p_original) is distinct from jsonb_typeof(p_reversal) then
    raise exception 'CORRECTION_REVERSAL_COMPONENT_SHAPE_MISMATCH' using errcode='55000';
  end if;
  if jsonb_typeof(p_original)='object' then
    v_original:=p_original-array['invoice_locked_invoice_id','invoice_locked_at_utc','pay_locked','pay_locked_at_utc','is_reversal'];
    v_reversal:=p_reversal-array['invoice_locked_invoice_id','invoice_locked_at_utc','pay_locked','pay_locked_at_utc','is_reversal'];
    if (select array_agg(k order by k) from jsonb_object_keys(v_original) k)
      is distinct from (select array_agg(k order by k) from jsonb_object_keys(v_reversal) k)
      or (p_reversal?'is_reversal' and p_reversal->>'is_reversal' is distinct from 'true') then
      raise exception 'CORRECTION_REVERSAL_COMPONENT_SET_MISMATCH' using errcode='55000';
    end if;
    for v_row in select key,value from jsonb_each(v_original) loop
      perform private.timesheet_correction_reversal_component_assert_v1(v_row.value,v_reversal->v_row.key,p_path||v_row.key);
    end loop;
  elsif jsonb_typeof(p_original)='array' then
    if jsonb_array_length(p_original)<>jsonb_array_length(p_reversal) then
      raise exception 'CORRECTION_REVERSAL_COMPONENT_SET_MISMATCH' using errcode='55000';
    end if;
    for v_row in select o.value original,r.value reversal,o.n from jsonb_array_elements(p_original) with ordinality o(value,n)
      join jsonb_array_elements(p_reversal) with ordinality r(value,n) using(n) loop
      perform private.timesheet_correction_reversal_component_assert_v1(v_row.original,v_row.reversal,p_path||v_row.n::text);
    end loop;
  else
    v_key:=p_path[cardinality(p_path)];
    v_signed:=v_key in('hours_day','hours_night','hours_sat','hours_sun','hours_bh','hours_total','total_hours',
      'pay_amount','charge_amount','pay_ex_vat','charge_ex_vat','margin_ex_vat','total_pay_ex_vat','total_charge_ex_vat',
      'unit_count','units','total_units','units_total',
      'pay_cost_ex_vat_including_erni','vat_amount','total_inc_vat')
      or (cardinality(p_path)>1 and p_path[cardinality(p_path)-1]='days')
      or (cardinality(p_path)>1 and p_path[cardinality(p_path)-1]='base_hours'
        and v_key in('day','night','sat','sun','bh'));
    if v_signed and jsonb_typeof(p_original)<>'null' then
      if not pg_input_is_valid(p_original#>>'{}','numeric') or not pg_input_is_valid(p_reversal#>>'{}','numeric')
        or (p_reversal#>>'{}')::numeric is distinct from -(p_original#>>'{}')::numeric then
        raise exception 'CORRECTION_REVERSAL_COMPONENT_PENCE_MISMATCH' using errcode='55000',detail=array_to_string(p_path,'.');
      end if;
    elsif p_original is distinct from p_reversal then
      raise exception 'CORRECTION_REVERSAL_COMPONENT_IDENTITY_MISMATCH' using errcode='55000',detail=array_to_string(p_path,'.');
    end if;
  end if;
end;
$function$;

create or replace function private.timesheet_correction_reversal_assert_v1(p_original jsonb,p_reversal jsonb)
returns void language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare
  v_key text; v_original jsonb; v_reversed jsonb; v_row record;
  v_signed_fields text[]:=array['hours_day','hours_night','hours_sat','hours_sun','hours_bh','total_hours',
    'total_pay_ex_vat','total_charge_ex_vat','margin_ex_vat','pay_vat_amount_snapshot','pay_total_inc_vat_snapshot',
    'expenses_pay_ex_vat','expenses_charge_ex_vat','travel_pay_ex_vat','travel_charge_ex_vat',
    'accommodation_pay_ex_vat','accommodation_charge_ex_vat','other_pay_ex_vat','other_charge_ex_vat',
    'mileage_units','mileage_pay_ex_vat','mileage_charge_ex_vat','additional_pay_ex_vat','additional_charge_ex_vat','additional_margin_ex_vat'];
  v_component_fields text[]:=array['hours_day','hours_night','hours_sat','hours_sun','hours_bh','hours_total',
    'total_hours','pay_amount','charge_amount','pay_ex_vat','charge_ex_vat','margin_ex_vat',
    'pay_cost_ex_vat_including_erni','vat_amount','total_inc_vat'];
  v_lock_fields text[]:=array['invoice_locked_invoice_id','invoice_locked_at_utc','pay_locked','pay_locked_at_utc'];
begin
  if jsonb_typeof(p_original) is distinct from 'object' or jsonb_typeof(p_reversal) is distinct from 'object'
    or p_original->'policy_snapshot_json' is distinct from p_reversal->'policy_snapshot_json'
    or p_original->'rate_source_refs_json' is distinct from p_reversal->'rate_source_refs_json'
    or p_original->'pay_method' is distinct from p_reversal->'pay_method'
    or p_original->'pay_vat_rate_pct_snapshot' is distinct from p_reversal->'pay_vat_rate_pct_snapshot'
    or p_original->'pay_wtr_rate_pct_snapshot' is distinct from p_reversal->'pay_wtr_rate_pct_snapshot' then
    raise exception 'CORRECTION_REVERSAL_HISTORIC_AUTHORITY_MISMATCH' using errcode='55000';
  end if;
  foreach v_key in array array['pay_day','pay_night','pay_sat','pay_sun','pay_bh','charge_day','charge_night','charge_sat','charge_sun','charge_bh',
    'mileage_pay_rate','mileage_charge_rate','basis','role','band','occupant_key_norm'] loop
    if p_original->v_key is distinct from p_reversal->v_key then
      raise exception 'CORRECTION_REVERSAL_HISTORIC_AUTHORITY_MISMATCH' using errcode='55000',detail=v_key;
    end if;
  end loop;
  perform private.timesheet_correction_reversal_component_assert_v1(p_original->'invoice_breakdown_json',p_reversal->'invoice_breakdown_json');
  perform private.timesheet_correction_reversal_component_assert_v1(p_original->'additional_units_json',p_reversal->'additional_units_json',array['additional_units_json']);
  foreach v_key in array v_signed_fields loop
    if coalesce((p_reversal->>v_key)::numeric,0) is distinct from -coalesce((p_original->>v_key)::numeric,0) then
      raise exception 'CORRECTION_REVERSAL_ORIGINAL_PENCE_MISMATCH' using errcode='55000',detail=v_key;
    end if;
  end loop;
  if p_original#>>'{invoice_breakdown_json,mode}' is distinct from p_reversal#>>'{invoice_breakdown_json,mode}' then
    raise exception 'CORRECTION_REVERSAL_COMPONENT_MODE_MISMATCH' using errcode='55000';
  end if;
  if p_original#>>'{invoice_breakdown_json,mode}'='SEGMENTS' then
    if jsonb_typeof(p_original#>'{invoice_breakdown_json,segments}') is distinct from 'array'
      or jsonb_typeof(p_reversal#>'{invoice_breakdown_json,segments}') is distinct from 'array'
      or jsonb_array_length(p_original#>'{invoice_breakdown_json,segments}')
        <>jsonb_array_length(p_reversal#>'{invoice_breakdown_json,segments}') then
      raise exception 'CORRECTION_REVERSAL_COMPONENT_SET_MISMATCH' using errcode='55000';
    end if;
    for v_row in select o.value original,s.value reversed from
      jsonb_array_elements(p_original#>'{invoice_breakdown_json,segments}') with ordinality o(value,n)
      join jsonb_array_elements(p_reversal#>'{invoice_breakdown_json,segments}') with ordinality s(value,n) using(n)
    loop
      v_original:=v_row.original; v_reversed:=v_row.reversed;
      if (v_original-v_component_fields-v_lock_fields-'is_reversal') is distinct from (v_reversed-v_component_fields-v_lock_fields-'is_reversal')
        or (nullif(p_reversal->>'authorised_at_utc','') is null
          and exists(select 1 from unnest(v_lock_fields) k where nullif(v_reversed->>k,'') is not null
            and not (k='pay_locked' and v_reversed->>k='false'))) then
        raise exception 'CORRECTION_REVERSAL_COMPONENT_IDENTITY_MISMATCH' using errcode='55000';
      end if;
      foreach v_key in array v_component_fields loop
        if (v_original?v_key) is distinct from (v_reversed?v_key)
          or (v_original?v_key and (v_reversed->>v_key)::numeric is distinct from -(v_original->>v_key)::numeric) then
          raise exception 'CORRECTION_REVERSAL_COMPONENT_PENCE_MISMATCH' using errcode='55000',detail=v_key;
        end if;
      end loop;
    end loop;
  else
    foreach v_key in array array['pay_ex_vat','charge_ex_vat','margin_ex_vat'] loop
      if coalesce((p_reversal#>>array['invoice_breakdown_json','base_hours',v_key])::numeric,0)
        is distinct from -coalesce((p_original#>>array['invoice_breakdown_json','base_hours',v_key])::numeric,0) then
        raise exception 'CORRECTION_REVERSAL_BASE_PENCE_MISMATCH' using errcode='55000',detail=v_key;
      end if;
    end loop;
  end if;
end;
$function$;

create or replace function public.timesheet_correction_prepare_v1(p_request_id uuid,p_actor_user_id uuid)
returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_request private.timesheet_correction_requests%rowtype; v_original public.timesheets%rowtype;
  v_p0 public.timesheets%rowtype; v_fin public.timesheets_financials%rowtype; v_pfin public.timesheets_financials%rowtype;
  v_witness jsonb; v_context jsonb; v_hash text;
begin
  if private.timesheet_correction_actor_allowed_v1(p_actor_user_id) is distinct from true then
    raise exception 'CORRECTION_ACTOR_NOT_ALLOWED' using errcode='42501';
  end if;
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id;
  if v_request.state<>'WAITING' then return v_request.terminal_receipt_json||jsonb_build_object('replayed',true); end if;
  select t.* into strict v_original from public.timesheets t where t.timesheet_id=v_request.reversed_timesheet_id;
  select t.* into strict v_p0 from public.timesheets t where t.timesheet_id=v_request.replacement_timesheet_id;
  select tf.* into v_fin from public.timesheets_financials tf where tf.timesheet_id=v_original.timesheet_id and tf.is_current;
  select tf.* into v_pfin from public.timesheets_financials tf where tf.timesheet_id=v_p0.timesheet_id and tf.is_current;
  if private.timesheet_correction_origin_v1(v_original.timesheet_id) is distinct from v_request.origin
    or v_original.version<>v_request.reversed_version or not v_original.is_current or v_original.archived_at_utc is not null
    or v_original.booking_id is distinct from v_request.frozen_original_json#>>'{timesheet,booking_id}'
    or private.timesheet_correction_timesheet_authority_hash_v1(to_jsonb(v_original))
      is distinct from private.timesheet_correction_timesheet_authority_hash_v1(v_request.frozen_original_json->'timesheet')
    or v_fin.id is distinct from v_request.reversed_financial_id
    or (v_fin.id is not null and private.timesheet_correction_financial_authority_hash_v1(to_jsonb(v_fin))
      is distinct from v_request.frozen_original_json->>'financial_authority_hash')
    or v_p0.correction_id is distinct from v_request.correction_id
    or v_p0.correction_kind is distinct from 'WHOLE_TIMESHEET_REPLACEMENT'
    or v_p0.booking_id is distinct from v_request.replacement_booking_id
    or v_p0.parent_timesheet_id is distinct from v_request.root_timesheet_id
    or not v_p0.is_current or v_p0.archived_at_utc is not null or v_p0.authorised_at_server is not null
    or v_pfin.authorised_at_utc is not null or v_pfin.paid_at_utc is not null or v_pfin.locked_by_invoice_id is not null
    or exists(select 1 from public.invoice_lines l where l.timesheet_id=v_p0.timesheet_id) then
    raise exception 'CORRECTION_PREPARE_AUTHORITY_CHANGED' using errcode='40001';
  end if;
  if v_request.original_invoice_id is not null and not exists(select 1 from public.invoices i
    where i.id=v_request.original_invoice_id and i.type='INVOICE' and i.status in('ISSUED','PAID')
      and exists(select 1 from public.invoice_lines l where l.invoice_id=i.id and l.timesheet_id=v_original.timesheet_id)) then
    raise exception 'CORRECTION_ORIGINAL_INVOICE_CHANGED' using errcode='40001';
  end if;
  if v_request.origin='SIGNED_TIMESHEET_CORRECTION' then
    if (private.timesheet_correction_signed_witness_v1(v_original.timesheet_id,false)-'document_version_id')
      is distinct from (v_request.frozen_original_json->'manager_signed_witness'-'document_version_id') then
      raise exception 'CORRECTION_ORIGINAL_SIGNATURE_CHANGED' using errcode='40001';
    end if;
    v_witness:=private.timesheet_correction_signed_witness_v1(v_p0.timesheet_id,false);
  end if;
  v_context:=jsonb_build_object('request_id',v_request.id,'state_revision',v_request.state_revision,
    'target_revision',v_request.target_revision,'proposal_revision',1,
    'root_timesheet_id',v_request.root_timesheet_id,'origin',v_request.origin,
    'original_timesheet_id',v_original.timesheet_id,'original_timesheet_version',v_original.version,
    'original_financial_id',v_fin.id,'original_financial_authority_hash',v_request.frozen_original_json->>'financial_authority_hash',
    'replacement_timesheet_id',v_p0.timesheet_id,'replacement_version',v_p0.version,
    'replacement_financial_id',v_pfin.id,'replacement_financial_authority_hash',
      case when v_pfin.id is not null then private.timesheet_correction_financial_authority_hash_v1(to_jsonb(v_pfin)) end,
    'replacement_schedule',v_p0.actual_schedule_json,'replacement_signed_witness',v_witness,
    'planned_reversal_timesheet_id',v_request.frozen_original_json->>'planned_reversal_timesheet_id',
    'planned_reversal_week_id',v_request.frozen_original_json->>'planned_reversal_week_id',
    'original_invoice_id',v_request.original_invoice_id,'return_invoice_id',v_request.return_invoice_id);
  v_hash:=encode(extensions.digest(v_context::text,'sha256'),'hex');
  -- Internal service DTO only. Original frozen snapshot and exact P0 context
  -- go to existing producer/preloader; Candidate detail never exposes these.
  return jsonb_build_object('ok',true,'contract_version','TIMESHEET_CORRECTION_PREPARE_V1',
    'prepare_fingerprint',v_hash,'authority',v_context,'candidate_id',v_request.candidate_id,'client_id',v_request.client_id,
    'frozen_original',v_request.frozen_original_json,'replacement_timesheet',to_jsonb(v_p0),
    'original_current_snapshot',case when v_fin.id is not null then to_jsonb(v_fin) end,
    'replacement_current_snapshot',case when v_pfin.id is not null then to_jsonb(v_pfin) end,
    'original_materialisation_required',v_fin.id is null,'original_authorisation_required',v_original.authorised_at_server is null);
end;
$function$;

create or replace function public.timesheet_correction_authorise_atomic_v1(
  p_request_id uuid,p_expected_state_revision bigint,p_prepared jsonb,p_actor_user_id uuid,p_now_utc timestamptz default now()
) returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_request private.timesheet_correction_requests%rowtype; v_prepare jsonb; v_original jsonb; v_leg jsonb;
  v_r uuid; v_p uuid; v_items jsonb; v_result jsonb; v_write jsonb; v_receipt jsonb; v_now timestamptz:=coalesce(p_now_utc,now());
  v_original_before jsonb; v_original_fin_before jsonb; v_after_fin jsonb; v_t0_authorise boolean; v_version integer;
  v_claim jsonb; v_batch_result record; v_reversal_snapshot jsonb;
begin
  perform private.timesheet_correction_actor_assert_v1(p_actor_user_id);
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id;
  perform 1 from public.invoices i where i.id in(v_request.original_invoice_id,v_request.return_invoice_id) order by i.id for update;
  perform pg_advisory_xact_lock(hashtextextended('CORRECTION_CHAIN|'||v_request.root_timesheet_id::text,21072026));
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id for update;
  if v_request.state<>'WAITING' then return v_request.terminal_receipt_json||jsonb_build_object('replayed',true); end if;
  if v_request.state_revision is distinct from p_expected_state_revision then
    raise exception 'CORRECTION_REQUEST_CAS_STALE' using errcode='40001';
  end if;
  perform 1 from public.candidate_submission_workflows w where w.id in(select t.candidate_workflow_id from public.timesheets t
    where t.timesheet_id in(v_request.reversed_timesheet_id,v_request.replacement_timesheet_id)) order by w.id for update;
  perform 1 from public.contract_weeks w where w.id=v_request.replacement_week_id order by w.id for update;
  perform 1 from public.timesheets t where t.timesheet_id in(v_request.reversed_timesheet_id,v_request.replacement_timesheet_id)
    order by t.timesheet_id for update;
  perform 1 from public.timesheets_financials tf where tf.timesheet_id in(v_request.reversed_timesheet_id,v_request.replacement_timesheet_id)
    order by tf.timesheet_id,tf.id for update;
  v_prepare:=public.timesheet_correction_prepare_v1(p_request_id,p_actor_user_id);
  if jsonb_typeof(p_prepared) is distinct from 'object'
    or p_prepared->>'prepare_fingerprint' is distinct from v_prepare->>'prepare_fingerprint' then
    raise exception 'CORRECTION_PREPARED_RESULT_STALE' using errcode='40001';
  end if;
  select to_jsonb(t) into v_original_before from public.timesheets t where t.timesheet_id=v_request.reversed_timesheet_id;
  v_original_fin_before:=v_prepare->'original_current_snapshot';
  v_t0_authorise:=(v_prepare->>'original_authorisation_required')::boolean;
  v_original:=case when jsonb_typeof(v_original_fin_before)='object' then v_original_fin_before else p_prepared->'original_snapshot' end;
  if v_request.return_invoice_id is not null then
    if v_t0_authorise then raise exception 'CORRECTION_D1_UNAUTHORISED_PARENT_INVALID' using errcode='55000'; end if;
    perform private.timesheet_correction_draft_round_trip_v1(v_request.id,'REMOVE',p_actor_user_id);
  end if;
  if (v_prepare->>'original_materialisation_required')::boolean then
    if not v_t0_authorise then raise exception 'CORRECTION_AUTHORISED_ORIGINAL_FINANCE_MISSING' using errcode='55000'; end if;
    perform private.timesheet_correction_snapshot_identity_assert_v1(v_original,v_request.reversed_timesheet_id,
      v_request.reversed_version,v_request.candidate_id,v_request.client_id);
    v_write:=public.tsfin_write_current_snapshot_single_bounded(v_request.reversed_timesheet_id,v_request.reversed_version,
      v_original,p_actor_user_id,v_now);
    if coalesce((v_write->>'ok')::boolean,false) is not true then
      raise exception 'CORRECTION_ORIGINAL_WRITE_FAILED' using errcode='55000',detail=v_write::text;
    end if;
    -- Native normalisation is authoritative for a newly materialised A0.
    -- Sign-copy may now use the actual stored output inside this same unit;
    -- no separate materialisation transaction or guessed normalisation exists.
    select to_jsonb(tf) into strict v_original from public.timesheets_financials tf
      where tf.timesheet_id=v_request.reversed_timesheet_id and tf.is_current;
  end if;
  v_p:=v_request.replacement_timesheet_id;
  select t.version into v_version from public.timesheets t where t.timesheet_id=v_p;
  perform private.timesheet_correction_snapshot_identity_assert_v1(p_prepared->'replacement_snapshot',v_p,v_version,
    v_request.candidate_id,v_request.client_id);
  v_write:=public.tsfin_write_current_snapshot_single_bounded(v_p,v_version,
    (p_prepared->'replacement_snapshot')||jsonb_build_object('processing_status','PENDING_AUTH'),p_actor_user_id,v_now);
  if coalesce((v_write->>'ok')::boolean,false) is not true then
    raise exception 'CORRECTION_REPLACEMENT_WRITE_FAILED' using errcode='55000',detail=v_write::text;
  end if;
  v_leg:=private.timesheet_correction_leg_create_v1(v_request,'WHOLE_TIMESHEET_REVERSAL','[]'::jsonb,v_now);
  v_r:=(v_leg->>'timesheet_id')::uuid;
  v_reversal_snapshot:=case when (v_prepare->>'original_materialisation_required')::boolean
      and (p_prepared->'reversal_snapshot' is null or p_prepared->'reversal_snapshot'='null'::jsonb)
    then private.timesheet_correction_native_original_reversal_v1(v_original,v_r)
    else p_prepared->'reversal_snapshot' end;
  perform private.timesheet_correction_snapshot_identity_assert_v1(v_reversal_snapshot,v_r,1,
    v_request.candidate_id,v_request.client_id);
  perform private.timesheet_correction_reversal_assert_v1(v_original,v_reversal_snapshot);
  -- Use the existing real queue/targeted lease and canonical batch writer.
  -- The single writer intentionally clamps mileage units and is unsuitable
  -- for the frozen negative reversal. No fake outbox id or writer bypass.
  perform public.enqueue_ts_financials(v_r,'MANUAL'::public.ts_fin_reason_enum);
  select coalesce(jsonb_agg(to_jsonb(claimed) order by claimed.id),'[]'::jsonb) into v_claim
    from public.tsfin_dequeue_specific(array[v_r],1) claimed;
  if jsonb_array_length(v_claim)<>1 or v_claim#>>'{0,timesheet_id}' is distinct from v_r::text
    or v_claim#>>'{0,reason}' is distinct from 'MANUAL'
    or not exists(select 1 from public.ts_financials_outbox o where o.id=(v_claim#>>'{0,id}')::uuid
      and o.timesheet_id=v_r and o.reason='MANUAL' and o.attempt_count>0 and o.next_attempt_at>now()) then
    raise exception 'CORRECTION_REVERSAL_CANONICAL_CLAIM_UNPROVED' using errcode='55000';
  end if;
  select * into strict v_batch_result from public.tsfin_write_snapshots_and_complete(jsonb_build_array(jsonb_build_object(
    'outbox_id',v_claim#>>'{0,id}','timesheet_id',v_r,'snapshot',
    v_reversal_snapshot||jsonb_build_object('processing_status','PENDING_AUTH'))));
  if v_batch_result.ok_count is distinct from 1 or v_batch_result.fail_count is distinct from 0
    or v_batch_result.errors is distinct from '[]'::jsonb
    or exists(select 1 from public.ts_financials_outbox o where o.id=(v_claim#>>'{0,id}')::uuid) then
    raise exception 'CORRECTION_REVERSAL_WRITE_FAILED' using errcode='55000',detail=to_jsonb(v_batch_result)::text;
  end if;
  select to_jsonb(tf) into strict v_after_fin from public.timesheets_financials tf where tf.timesheet_id=v_r and tf.is_current;
  -- The bounded writer normalises totals. Check its actual output against the
  -- frozen source again so any pence/component drift aborts the entire unit.
  perform private.timesheet_correction_reversal_assert_v1(v_original,v_after_fin);
  v_receipt:=jsonb_build_object('ok',true,'state','APPLIED','request_id',v_request.id,'correction_id',v_request.correction_id,
    'reversed_timesheet_id',v_request.reversed_timesheet_id,'reversal_timesheet_id',v_r,'replacement_timesheet_id',v_p,
    'state_revision',v_request.state_revision+1,'prepare_fingerprint',v_prepare->>'prepare_fingerprint',
    'original_authorisation_required',v_t0_authorise,
    'original_materialised_in_unit',(v_prepare->>'original_materialisation_required')::boolean,
    'original_timesheet_authority_hash',private.timesheet_correction_timesheet_authority_hash_v1(v_original_before),
    'reversal_timesheet_authority_hash',private.timesheet_correction_timesheet_authority_hash_v1((select to_jsonb(t)
      from public.timesheets t where t.timesheet_id=v_r)),
    'replacement_timesheet_authority_hash',private.timesheet_correction_timesheet_authority_hash_v1((select to_jsonb(t)
      from public.timesheets t where t.timesheet_id=v_p)),
    'original_financial_id',(select tf.id from public.timesheets_financials tf where tf.timesheet_id=v_request.reversed_timesheet_id and tf.is_current),
    'original_financial_authority_hash',private.timesheet_correction_financial_authority_hash_v1((select to_jsonb(tf) from public.timesheets_financials tf
      where tf.timesheet_id=v_request.reversed_timesheet_id and tf.is_current)),
    'reversal_financial_id',(select tf.id from public.timesheets_financials tf where tf.timesheet_id=v_r and tf.is_current),
    'reversal_financial_authority_hash',private.timesheet_correction_financial_authority_hash_v1(v_after_fin),
    'replacement_financial_id',(select tf.id from public.timesheets_financials tf where tf.timesheet_id=v_p and tf.is_current),
    'replacement_financial_authority_hash',private.timesheet_correction_financial_authority_hash_v1((select to_jsonb(tf) from public.timesheets_financials tf
      where tf.timesheet_id=v_p and tf.is_current)),
    'ordinary_notification_timesheet_ids',jsonb_build_array(v_p));
  update private.timesheet_correction_requests request set state='APPLIED',state_revision=state_revision+1,
    reversal_timesheet_id=v_r,reversal_booking_id=v_leg->>'booking_id',reversal_week_id=(v_leg->>'contract_week_id')::uuid,
    workflow_id=(v_prepare#>>'{authority,replacement_signed_witness,workflow_id}')::uuid,
    workflow_generation=(v_prepare#>>'{authority,replacement_signed_witness,workflow_generation}')::integer,
    terminal_receipt_json=v_receipt,applied_at_utc=v_now,updated_at_utc=v_now where request.id=v_request.id;
  select jsonb_agg(jsonb_build_object('timesheet_id',t.timesheet_id,'expected_timesheet_id',t.timesheet_id,
    'expected_version',t.version,'lifecycle_group_id','correction:'||v_request.correction_id,
    'lifecycle_group_size',case when v_t0_authorise then 3 else 2 end) order by t.timesheet_id) into v_items
  from public.timesheets t where t.timesheet_id in(v_r,v_p) or (v_t0_authorise and t.timesheet_id=v_request.reversed_timesheet_id);
  -- This generic owner is pinned/call-only. Returned partial failures must
  -- raise, just like exceptions, to roll back rows, workflows and receipts.
  v_result:=public.timesheet_authorise_bulk_atomic(v_items,p_actor_user_id,v_now);
  if coalesce((v_result->>'all_success')::boolean,false) is not true
    or (v_result->>'success_count')::integer is distinct from (case when v_t0_authorise then 3 else 2 end)
    or exists(select 1 from jsonb_array_elements(coalesce(v_result->'results','[]'::jsonb)) r
      where coalesce((r->>'success')::boolean,false) is not true)
    or (select count(*) from public.timesheets t join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
      where t.timesheet_id in(v_r,v_p) and t.authorised_at_server is not null and tf.authorised_at_utc is not null)<>2 then
    raise exception 'CORRECTION_COMPLETE_UNIT_AUTHORISATION_FAILED' using errcode='55000',detail=v_result::text;
  end if;
  if not v_t0_authorise and ((select to_jsonb(t) from public.timesheets t where t.timesheet_id=v_request.reversed_timesheet_id)
      is distinct from v_original_before or (select to_jsonb(tf) from public.timesheets_financials tf
        where tf.timesheet_id=v_request.reversed_timesheet_id and tf.is_current) is distinct from v_original_fin_before)
      and v_request.return_invoice_id is null then
    raise exception 'CORRECTION_ISSUED_ORIGINAL_MUTATED' using errcode='55000';
  end if;
  if v_request.return_invoice_id is not null then
    if private.timesheet_correction_timesheet_authority_hash_v1((select to_jsonb(t) from public.timesheets t
      where t.timesheet_id=v_request.reversed_timesheet_id))
      is distinct from private.timesheet_correction_timesheet_authority_hash_v1(v_original_before)
      or private.timesheet_correction_financial_authority_hash_v1((select to_jsonb(tf) from public.timesheets_financials tf
      where tf.timesheet_id=v_request.reversed_timesheet_id and tf.is_current))
      is distinct from v_request.frozen_original_json->>'financial_authority_hash' then
      raise exception 'CORRECTION_D1_ORIGINAL_ECONOMICS_CHANGED' using errcode='55000';
    end if;
    v_write:=private.timesheet_correction_draft_round_trip_v1(v_request.id,'RETURN',p_actor_user_id);
    return v_receipt||jsonb_build_object('authorisation',v_result,'draft_return',v_write);
  end if;
  return v_receipt||jsonb_build_object('authorisation',v_result);
end;
$function$;

create or replace function private.timesheet_correction_applied_assert_v1(p_request_id uuid)
returns void language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype; v_row record; v_role text;
begin
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id;
  if v_request.state<>'APPLIED' then return; end if;
  if (select count(*) from public.timesheets t where t.timesheet_id in(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id)
      and t.is_current and t.archived_at_utc is null and t.correction_id=v_request.correction_id
      and t.parent_timesheet_id=v_request.root_timesheet_id and t.adjustment_origin=v_request.origin)<>2
    or (select count(*) from public.timesheets t join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
      where t.timesheet_id in(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id,v_request.reversed_timesheet_id)
        and t.is_current)<>3
    or (select count(*) from public.timesheets t join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
      where t.timesheet_id in(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id))<>2
    or exists(select 1 from public.timesheets r join public.timesheets p on p.timesheet_id=v_request.replacement_timesheet_id
      where r.timesheet_id=v_request.reversal_timesheet_id
        and (r.authorised_at_server is null) is distinct from (p.authorised_at_server is null)) then
    raise exception 'WHOLE_CORRECTION_COMPLETE_UNIT_REQUIRED' using errcode='23514';
  end if;
  for v_row in select t.timesheet_id,t.authorised_at_server,to_jsonb(t) timesheet,to_jsonb(tf) financial,tf.id financial_id,tf.authorised_at_utc
    from public.timesheets t join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
    where t.timesheet_id in(v_request.reversal_timesheet_id,v_request.replacement_timesheet_id,v_request.reversed_timesheet_id)
  loop
    v_role:=case when v_row.timesheet_id=v_request.reversal_timesheet_id then 'reversal'
      when v_row.timesheet_id=v_request.replacement_timesheet_id then 'replacement' else 'original' end;
    if v_row.financial_id::text is distinct from v_request.terminal_receipt_json->>(v_role||'_financial_id')
      or private.timesheet_correction_timesheet_authority_hash_v1(v_row.timesheet)
        is distinct from v_request.terminal_receipt_json->>(v_role||'_timesheet_authority_hash')
      or private.timesheet_correction_financial_authority_hash_v1(v_row.financial)
        is distinct from v_request.terminal_receipt_json->>(v_role||'_financial_authority_hash')
      or (v_role<>'original' and (v_row.authorised_at_server is null) is distinct from (v_row.authorised_at_utc is null))
      or (v_role='original' and coalesce((v_request.terminal_receipt_json->>'original_authorisation_required')::boolean,false)
        and (v_row.authorised_at_server is null or v_row.authorised_at_utc is null)) then
      raise exception 'WHOLE_CORRECTION_FROZEN_FINANCIAL_IDENTITY_CHANGED' using errcode='23514',detail=v_role;
    end if;
  end loop;
end;
$function$;

create or replace function private.timesheet_correction_financial_guard_v1()
returns trigger language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_id uuid; v_old_id uuid; v_request record;
begin
  v_id:=case when tg_op='DELETE' then old.timesheet_id else new.timesheet_id end;
  if tg_op in('UPDATE','DELETE') then v_old_id:=old.timesheet_id; end if;
  for v_request in select request.id from private.timesheet_correction_requests request
    where request.state='APPLIED' and (v_id in(request.reversed_timesheet_id,request.replacement_timesheet_id,request.reversal_timesheet_id)
      or v_old_id in(request.reversed_timesheet_id,request.replacement_timesheet_id,request.reversal_timesheet_id))
    order by request.id loop
    perform private.timesheet_correction_applied_assert_v1(v_request.id);
  end loop;
  return null;
end;
$function$;
drop trigger if exists zz_timesheet_correction_financial_guard_v1 on public.timesheets_financials;
create constraint trigger zz_timesheet_correction_financial_guard_v1 after insert or update or delete on public.timesheets_financials
  deferrable initially deferred for each row execute function private.timesheet_correction_financial_guard_v1();
drop trigger if exists zz_timesheet_correction_applied_timesheet_guard_v1 on public.timesheets;
create constraint trigger zz_timesheet_correction_applied_timesheet_guard_v1 after insert or update or delete on public.timesheets
  deferrable initially deferred for each row execute function private.timesheet_correction_financial_guard_v1();

create or replace function private.timesheet_correction_terminal_guard_v1()
returns trigger language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
begin
  perform private.timesheet_correction_applied_assert_v1(new.id);
  return null;
end;
$function$;
drop trigger if exists zz_timesheet_correction_terminal_guard_v1 on private.timesheet_correction_requests;
create constraint trigger zz_timesheet_correction_terminal_guard_v1 after insert or update on private.timesheet_correction_requests
  deferrable initially deferred for each row execute function private.timesheet_correction_terminal_guard_v1();

-- Service-only enrichment after the existing manager channel has established
-- its exact workflow/generation/approval/manifest. No cross-auth fetch exists.
create or replace function public.timesheet_correction_manager_summary_v1(
  p_workflow_id uuid,p_workflow_generation integer,p_approval_request_id uuid,p_manifest_sha256 text
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype; v_workflow public.candidate_submission_workflows%rowtype;
  v_approval public.candidate_approval_requests%rowtype; v_hours public.candidate_submission_components%rowtype;
  v_render_input jsonb; v_schedule jsonb;
begin
  select w.* into v_workflow from public.candidate_submission_workflows w
    where w.id=p_workflow_id and w.generation=p_workflow_generation;
  select request.* into v_request from private.timesheet_correction_requests request
    where request.origin in('SIGNED_TIMESHEET_CORRECTION','AGENCY_INVOICE_CORRECTION') and request.state='WAITING'
      and request.replacement_timesheet_id=v_workflow.target_timesheet_id
      and request.candidate_id=v_workflow.candidate_id;
  if not found then return null; end if;
  select a.* into v_approval from public.candidate_approval_requests a
    where a.id=p_approval_request_id and a.workflow_id=p_workflow_id and a.workflow_generation=p_workflow_generation
      and a.state in('PENDING','APPROVED') and a.review_manifest_sha256=v_workflow.review_manifest_sha256
      and encode(a.review_manifest_sha256,'hex')=p_manifest_sha256;
  select c.* into v_hours from public.candidate_submission_components c
    where c.id=v_approval.manager_review_timesheet_component_id and c.workflow_id=p_workflow_id
      and c.workflow_generation=p_workflow_generation and c.component_kind='HOURS_TIMESHEET'
      and c.required and c.state='IMMUTABLE' and c.review_render_state='READY'
      and c.review_content_sha256=v_approval.manager_review_timesheet_sha256;
  if v_approval.id is null or v_hours.id is null
    or v_workflow.review_manifest_sha256 is null or v_workflow.immutable_submission_sha256 is null
    or private._candidate_sha256_jsonb_v1(v_workflow.immutable_submission_json) is distinct from v_workflow.immutable_submission_sha256 then
    raise exception 'CORRECTION_MANAGER_REVIEW_WITNESS_CHANGED' using errcode='40001';
  end if;
  v_render_input:=private._candidate_component_render_input_v1(p_workflow_id,p_workflow_generation,v_hours.id);
  if v_render_input->>'render_input_sha256' is distinct from encode(v_hours.review_render_input_sha256,'hex') then
    raise exception 'CORRECTION_MANAGER_REVIEW_INPUT_CHANGED' using errcode='40001';
  end if;
  v_schedule:=coalesce(v_workflow.immutable_submission_json#>'{timesheet_patch_json,actual_schedule_json}',
    v_workflow.immutable_submission_json#>'{hours_submission,timesheet_patch_json,actual_schedule_json}');
  if jsonb_typeof(v_schedule) is distinct from 'array' then
    raise exception 'CORRECTION_MANAGER_REVIEW_PROPOSAL_UNPROVED' using errcode='55000';
  end if;
  return jsonb_build_object('schema_version',1,'request_id',v_request.id,'correction_id',v_request.correction_id,
    'reason',v_request.reason,'original_schedule',v_request.frozen_original_json->'schedule',
    'reviewed_schedule',v_schedule,'review_witness',jsonb_build_object('workflow_id',p_workflow_id,
      'workflow_generation',p_workflow_generation,'approval_request_id',p_approval_request_id,
      'manifest_sha256',p_manifest_sha256,'hours_component_id',v_hours.id,
      'review_render_input_sha256',encode(v_hours.review_render_input_sha256,'hex'),
      'review_content_sha256',encode(v_hours.review_content_sha256,'hex')));
end;
$function$;

-- Adjacent request authority; no widening of the import correction classifier.
create or replace function private.timesheet_correction_whole_transition_v1(
  p_timesheet_id uuid,p_action text,p_actor_user_id uuid,p_expected_chain_fingerprint text,p_lock_rows boolean,p_max_members integer
) returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_request private.timesheet_correction_requests%rowtype; v_chain jsonb; v_ids uuid[];
  v_rows jsonb; v_items jsonb; v_authorised integer; v_unauthorised integer; v_ready integer; v_paid integer; v_invoiced integer;
  v_action text:=upper(btrim(p_action)); v_errors jsonb:='[]'::jsonb; v_include_original boolean:=false; v_count integer;
begin
  select request.* into v_request from private.timesheet_correction_requests request
    where p_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id)
      and request.correction_id=(select t.correction_id from public.timesheets t where t.timesheet_id=p_timesheet_id);
  if not found then return null; end if;
  if private.timesheet_correction_actor_allowed_v1(p_actor_user_id) is distinct from true then
    raise exception 'CORRECTION_ACTOR_NOT_ALLOWED' using errcode='42501';
  end if;
  if v_action not in('AUTHORISE','UNAUTHORISE','PROCESS','UNPROCESS') then
    raise exception 'CORRECTION_TRANSITION_ACTION_INVALID' using errcode='22023';
  end if;
  if p_lock_rows then
    perform 1 from public.invoices i where i.id in(v_request.original_invoice_id,v_request.return_invoice_id) order by i.id for update;
    perform pg_advisory_xact_lock(hashtextextended('CORRECTION_CHAIN|'||v_request.root_timesheet_id::text,21072026));
    select request.* into v_request from private.timesheet_correction_requests request where request.id=v_request.id for update;
  end if;
  if v_request.state<>'APPLIED' then
    return jsonb_build_object('ok',true,'valid',false,'action_ready',false,'correction_id',v_request.correction_id,
      'expected_member_count',2,'errors',jsonb_build_array(jsonb_build_object('code','CORRECTION_REQUEST_NOT_APPLIED')));
  end if;
  v_include_original:=v_action='AUTHORISE'
    and coalesce((v_request.terminal_receipt_json->>'original_authorisation_required')::boolean,false)
    and exists(select 1 from public.timesheets t where t.timesheet_id=v_request.reversed_timesheet_id
      and t.authorised_at_server is null);
  v_ids:=array[v_request.reversal_timesheet_id,v_request.replacement_timesheet_id];
  if v_include_original then v_ids:=array_append(v_ids,v_request.reversed_timesheet_id); end if;
  v_count:=cardinality(v_ids);
  if v_count>p_max_members then raise exception 'CORRECTION_TRANSITION_MEMBER_LIMIT_INVALID' using errcode='22023'; end if;
  if p_lock_rows then
    perform 1 from public.candidate_submission_workflows w where w.id in(select t.candidate_workflow_id from public.timesheets t
      where t.timesheet_id=any(v_ids)) order by w.id for update;
    perform 1 from public.timesheets t where t.timesheet_id=any(v_ids) order by t.timesheet_id for update;
    perform 1 from public.timesheets_financials tf where tf.timesheet_id=any(v_ids) and tf.is_current
      order by tf.timesheet_id,tf.id for update;
  end if;
  v_chain:=public.timesheet_correction_chain_scope_v1(p_timesheet_id,false,32,p_max_members);
  if (v_chain->>'valid')::boolean is distinct from true
    or (p_expected_chain_fingerprint is not null and p_expected_chain_fingerprint is distinct from v_chain->>'chain_fingerprint') then
    raise exception 'CORRECTION_TRANSITION_CHAIN_STALE' using errcode='40001';
  end if;
  select count(*) filter(where t.authorised_at_server is not null and tf.authorised_at_utc is not null),
    count(*) filter(where t.authorised_at_server is null and tf.authorised_at_utc is null),
    count(*) filter(where tf.id is not null and not coalesce(tf.is_stale,true) and tf.candidate_id=v_request.candidate_id
      and tf.client_id=v_request.client_id and nullif(btrim(tf.pay_method),'') is not null
      and not coalesce(tf.has_rate_issue,true) and not coalesce(tf.has_pay_channel_issue,true)),
    count(*) filter(where tf.paid_at_utc is not null),
    count(*) filter(where tf.locked_by_invoice_id is not null or exists(select 1 from public.invoice_lines l where l.timesheet_id=t.timesheet_id)
      or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
        then tf.invoice_breakdown_json->'segments' else '[]'::jsonb end) s where nullif(s->>'invoice_locked_invoice_id','') is not null)),
    jsonb_agg(jsonb_build_object('timesheet_id',t.timesheet_id,'correction_kind',t.correction_kind,
      'timesheet_authorised',t.authorised_at_server is not null,'tsfin_authorised',tf.authorised_at_utc is not null,
      'tsfin_id',tf.id,'processing_status',tf.processing_status,'policy_ready',not coalesce(tf.is_stale,true)) order by t.timesheet_id),
    jsonb_agg(jsonb_build_object('timesheet_id',t.timesheet_id,'expected_timesheet_id',t.timesheet_id,
      'expected_version',t.version) order by t.timesheet_id)
    into v_authorised,v_unauthorised,v_ready,v_paid,v_invoiced,v_rows,v_items
  from public.timesheets t left join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
    where t.timesheet_id=any(v_ids) and t.is_current and t.archived_at_utc is null;
  if jsonb_array_length(coalesce(v_rows,'[]'::jsonb))<>v_count or v_paid<>0 or v_invoiced<>0
    or (v_action='AUTHORISE' and not(v_authorised=v_count or (v_unauthorised=v_count and v_ready=v_count)))
    or (v_action='UNAUTHORISE' and not(v_authorised=v_count or v_unauthorised=v_count)) then
    v_errors:=jsonb_build_array(jsonb_build_object('code','CORRECTION_UNIT_ACTION_STATE_INVALID'));
  end if;
  if v_action in('PROCESS','UNPROCESS') then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','WHOLE_CORRECTION_FINANCE_FROZEN'));
  end if;
  return jsonb_build_object('ok',true,'valid',jsonb_array_length(v_errors)=0,'action',v_action,
    'action_ready',jsonb_array_length(v_errors)=0,'root_timesheet_id',v_request.root_timesheet_id,
    'correction_id',v_request.correction_id,'request_id',v_request.id,'correction_shape','WHOLE_REVERSAL_REPLACEMENT',
    'expected_member_count',v_count,'pair_timesheet_ids',to_jsonb(v_ids),'pair_rows',coalesce(v_rows,'[]'::jsonb),
    'transition_items',coalesce(v_items,'[]'::jsonb),'chain_fingerprint',v_chain->>'chain_fingerprint',
    'authorised_count',v_authorised,'unauthorised_count',v_unauthorised,'ready_count',v_ready,
    'paid_count',v_paid,'invoice_lined_count',v_invoiced,'errors',v_errors,
    'correction_financials_policy_envelope',null,'correction_financials_policy_envelope_fingerprint',null,
    'required_backend_rpc',case when v_action='AUTHORISE' then 'timesheet_authorise_bulk_atomic' else 'timesheet_unauthorise_bulk_atomic' end);
end;
$function$;

create or replace function public.timesheet_correction_chain_scope_v1(
  p_timesheet_id uuid,
  p_lock_rows boolean default false,
  p_max_depth integer default 32,
  p_max_members integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'extensions', 'pg_temp'
as $function$
declare
  v_root_id uuid;
  v_member_ids uuid[] := array[]::uuid[];
  v_member_count integer := 0;
  v_cycle boolean := false;
  v_truncated boolean := false;
  v_units jsonb := '[]'::jsonb;
  v_members jsonb := '[]'::jsonb;
  v_errors jsonb := '[]'::jsonb;
  v_latest_positive uuid;
  v_fingerprint_payload jsonb;
  v_chain_fingerprint text;
  v_requested_unit jsonb;
  v_requested_operation_id text;
begin
  if p_timesheet_id is null then
    raise exception 'CORRECTION_CHAIN_TIMESHEET_ID_REQUIRED' using errcode='22023';
  end if;
  if p_max_depth < 1 or p_max_depth > 32 then
    raise exception 'CORRECTION_CHAIN_MAX_DEPTH_OUT_OF_RANGE' using errcode='22023';
  end if;
  if p_max_members < 1 or p_max_members > 100 then
    raise exception 'CORRECTION_CHAIN_MAX_MEMBERS_OUT_OF_RANGE' using errcode='22023';
  end if;
  if not exists (select 1 from public.timesheets where timesheet_id=p_timesheet_id) then
    raise exception 'CORRECTION_CHAIN_TIMESHEET_NOT_FOUND' using errcode='P0002';
  end if;

  with recursive ancestors as (
    select ts.timesheet_id, ts.parent_timesheet_id, 0 depth,
           array[ts.timesheet_id]::uuid[] path, false cycle
    from public.timesheets ts where ts.timesheet_id=p_timesheet_id
    union all
    select p.timesheet_id, p.parent_timesheet_id, a.depth+1,
           a.path||p.timesheet_id, p.timesheet_id=any(a.path)
    from ancestors a
    join public.timesheets p on p.timesheet_id=a.parent_timesheet_id
    where a.parent_timesheet_id is not null and not a.cycle and a.depth<p_max_depth
  )
  select a.timesheet_id,
         coalesce(bool_or(a.cycle) over (),false)
  into v_root_id, v_cycle
  from ancestors a
  order by a.depth desc
  limit 1;

  with recursive descendants as (
    select ts.timesheet_id, ts.parent_timesheet_id, 0 depth,
           array[ts.timesheet_id]::uuid[] path, false cycle
    from public.timesheets ts where ts.timesheet_id=v_root_id
    union all
    select c.timesheet_id, c.parent_timesheet_id, d.depth+1,
           d.path||c.timesheet_id, c.timesheet_id=any(d.path)
    from descendants d
    join public.timesheets c on c.parent_timesheet_id=d.timesheet_id
    where not d.cycle and d.depth<p_max_depth
  ), picked as (
    select distinct d.timesheet_id from descendants d where not d.cycle
  )
  select coalesce(array_agg(p.timesheet_id order by p.timesheet_id),array[]::uuid[]),
         count(*)::integer,
         exists(select 1 from descendants where cycle),
         exists(
           select 1 from public.timesheets child
           join descendants edge on edge.timesheet_id=child.parent_timesheet_id
           where edge.depth=p_max_depth
         )
  into v_member_ids,v_member_count,v_cycle,v_truncated
  from picked p;

  if v_member_count>p_max_members then
    raise exception 'CORRECTION_CHAIN_MEMBER_LIMIT_EXCEEDED'
      using errcode='22023', detail=jsonb_build_object('count',v_member_count,'max',p_max_members)::text;
  end if;
  if p_lock_rows then
    if not pg_try_advisory_xact_lock(hashtextextended('CORRECTION_CHAIN|'||v_root_id::text,21072026)) then
      raise exception 'CORRECTION_CHAIN_LOCK_BUSY' using errcode='55P03';
    end if;
    perform 1 from public.timesheets ts
    where ts.timesheet_id=any(v_member_ids) order by ts.timesheet_id for update;
  end if;

  with member_rows as (
    select ts.*,
      public._ctms_import_correction_classify_v1(ts.timesheet_id) as class_json,
      case when upper(btrim(coalesce(ts.adjustment_origin,''))) in ('IMPORT_CORRECTION','IMPORT_CANCELLATION')
        then public._ctms_correction_policy_envelope_read_v1(ts.timesheet_id) else null end as envelope
    from public.timesheets ts where ts.timesheet_id=any(v_member_ids)
  ), unit_members as (
    select mr.*,
      mr.envelope#>>'{operation,operation_id}' operation_id,
      mr.envelope->>'correction_chain_id' correction_chain_id,
      case
        when upper(btrim(coalesce(mr.correction_kind,''))) in
          ('CHANGED_HOURS_REVERSAL','CANCELLATION_REVERSAL') then 'REVERSAL'
        when upper(btrim(coalesce(mr.correction_kind,''))) in
          ('CHANGED_HOURS_REPLACEMENT','CANCELLATION_REPLACEMENT') then 'REPLACEMENT'
        else 'INVALID'
      end member_role
    from member_rows mr
    where coalesce((mr.class_json->>'is_import_authoritative_correction')::boolean,false)=true
  ), unit_rows as (
    select operation_id,correction_chain_id,
      min(correction_id) correction_id,
      count(distinct correction_id)::integer correction_id_count,
      count(*) filter (where member_role='REVERSAL')::integer reversal_count,
      count(*) filter (where member_role='REPLACEMENT')::integer replacement_count,
      count(*)::integer actual_member_count,
      jsonb_agg(member_role order by case member_role when 'REVERSAL' then 1 when 'REPLACEMENT' then 2 else 3 end) actual_member_roles,
      array_agg(timesheet_id order by timesheet_id) member_ids,
      count(distinct envelope->>'envelope_fingerprint')::integer envelope_count,
      count(distinct envelope->>'root_timesheet_id')::integer envelope_root_count,
      min(envelope->>'envelope_fingerprint') envelope_fingerprint,
      min(envelope::text)::jsonb envelope
    from unit_members
    where nullif(btrim(coalesce(operation_id,'')),'') is not null
      and nullif(btrim(coalesce(correction_chain_id,'')),'') is not null
    group by operation_id,correction_chain_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'correction_id',u.correction_id,
    'correction_operation_id',u.operation_id,
    'correction_chain_id',u.correction_chain_id,
    'correction_shape',u.envelope->>'correction_shape',
    'expected_member_count',(u.envelope->>'expected_member_count')::integer,
    'expected_member_roles',u.envelope->'expected_member_roles',
    'actual_member_count',u.actual_member_count,
    'actual_member_roles',u.actual_member_roles,
    'member_ids',to_jsonb(u.member_ids),
    'reversal_count',u.reversal_count,
    'replacement_count',u.replacement_count,
    'envelope_fingerprint',u.envelope_fingerprint,
    'policy_envelope',u.envelope,
    'valid',u.operation_id is not null
      and u.correction_chain_id is not null
      and u.correction_id_count=1
      and u.envelope_count=1
      and u.envelope_root_count=1
      and u.envelope->>'root_timesheet_id' is not distinct from v_root_id::text
      and u.envelope->>'correction_shape' in ('REVERSAL_ONLY','REVERSAL_REPLACEMENT')
      and u.actual_member_count=(u.envelope->>'expected_member_count')::integer
      and u.actual_member_roles=u.envelope->'expected_member_roles'
      and u.reversal_count=1
      and u.replacement_count=case when u.envelope->>'correction_shape'='REVERSAL_ONLY' then 0 else 1 end
  ) order by u.operation_id),'[]'::jsonb)
  into v_units
  from unit_rows u;

  -- WHOLE requests are adjacent units; immutable request ownership replaces
  -- import policy envelopes only for this exact purpose.
  select v_units||coalesce(jsonb_agg(jsonb_build_object(
    'correction_id',request.correction_id,'correction_operation_id',request.id,
    'correction_chain_id',request.root_timesheet_id,'request_id',request.id,
    'correction_shape','WHOLE_REVERSAL_REPLACEMENT','expected_member_count',2,
    'expected_member_roles',jsonb_build_array('REVERSAL','REPLACEMENT'),
    'actual_member_count',(select count(*) from public.timesheets member where member.timesheet_id
      in(request.reversal_timesheet_id,request.replacement_timesheet_id) and member.is_current
      and member.correction_id=request.correction_id and member.parent_timesheet_id=request.root_timesheet_id),
    'member_ids',jsonb_build_array(request.reversal_timesheet_id,request.replacement_timesheet_id),
    'valid',exists(select 1 from public.timesheets r join public.timesheets p on p.timesheet_id=request.replacement_timesheet_id
      where r.timesheet_id=request.reversal_timesheet_id and r.correction_kind='WHOLE_TIMESHEET_REVERSAL'
      and p.correction_kind='WHOLE_TIMESHEET_REPLACEMENT' and r.correction_id=request.correction_id
      and p.correction_id=request.correction_id and r.parent_timesheet_id=request.root_timesheet_id
      and p.parent_timesheet_id=request.root_timesheet_id and r.is_current and p.is_current)
  ) order by request.created_at_utc,request.id),'[]'::jsonb) into v_units
  from private.timesheet_correction_requests request where request.root_timesheet_id=v_root_id and request.state='APPLIED';

  select coalesce(jsonb_agg(jsonb_build_object(
    'timesheet_id',ts.timesheet_id,
    'parent_timesheet_id',ts.parent_timesheet_id,
    'booking_id',ts.booking_id,
    'is_current',ts.is_current,
    'status',ts.status,
    'correction_id',ts.correction_id,
    'correction_kind',ts.correction_kind,
    'adjustment_origin',ts.adjustment_origin,
    'policy_envelope_fingerprint',coalesce(
      ts.candidate_hint_text#>>'{correction_financials_policy_envelope,envelope_fingerprint}',
      tf.policy_snapshot_json#>>'{correction_financials_policy_envelope,envelope_fingerprint}'
    ),
    'current_tsfin_id',tf.id,
    'processing_status',tf.processing_status,
    'paid_at_utc',tf.paid_at_utc,
    'locked_by_invoice_id',tf.locked_by_invoice_id
  ) order by ts.created_at,ts.timesheet_id),'[]'::jsonb)
  into v_members
  from public.timesheets ts
  left join public.timesheets_financials tf on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
  where ts.timesheet_id=any(v_member_ids);

  if v_cycle then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_CHAIN_CYCLE')); end if;
  if v_truncated then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_CHAIN_DEPTH_EXCEEDED')); end if;
  if exists(select 1 from jsonb_array_elements(v_units) u where coalesce((u->>'valid')::boolean,false)=false) then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_UNIT_INVALID'));
  end if;
  if exists (
    select 1
    from public.timesheets ts
    where ts.timesheet_id=any(v_member_ids)
      and upper(btrim(coalesce(ts.adjustment_origin,''))) in ('IMPORT_CORRECTION','IMPORT_CANCELLATION')
      and not coalesce((public._ctms_import_correction_classify_v1(ts.timesheet_id)->>'is_import_authoritative_correction')::boolean,false)
  ) then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_MEMBER_CONTRACT_INVALID'));
  end if;

  select ts.timesheet_id into v_latest_positive
  from public.timesheets ts
  where ts.timesheet_id=any(v_member_ids)
    and (
      ts.timesheet_id=v_root_id
      or upper(btrim(coalesce(ts.correction_kind,''))) in ('CHANGED_HOURS_REPLACEMENT','CANCELLATION_REPLACEMENT')
      or (ts.correction_kind='WHOLE_TIMESHEET_REPLACEMENT' and exists(select 1 from private.timesheet_correction_requests request
        where request.replacement_timesheet_id=ts.timesheet_id and request.state='APPLIED'))
    )
  order by ts.created_at desc,ts.timesheet_id desc limit 1;

  if coalesce((public._ctms_import_correction_classify_v1(p_timesheet_id)->>'is_import_authoritative_correction')::boolean,false) then
    v_requested_operation_id:=public._ctms_correction_policy_envelope_read_v1(p_timesheet_id)#>>'{operation,operation_id}';
    select u into v_requested_unit
    from jsonb_array_elements(v_units) u
    where u->>'correction_operation_id'=v_requested_operation_id
    limit 1;
  end if;

  if exists(select 1 from private.timesheet_correction_requests request
    where request.state='APPLIED' and p_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id)) then
    select u into v_requested_unit from jsonb_array_elements(v_units) u
      where u->>'request_id'=(select request.id::text from private.timesheet_correction_requests request
        where request.state='APPLIED' and p_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id));
  end if;

  v_fingerprint_payload:=jsonb_build_object(
    'root_timesheet_id',v_root_id,'member_ids',to_jsonb(v_member_ids),
    'correction_units',v_units,'latest_positive_timesheet_id',v_latest_positive
  );
  v_chain_fingerprint:=encode(extensions.digest(convert_to(v_fingerprint_payload::text,'UTF8'),'sha256'::text),'hex');

  return jsonb_build_object(
    'ok',jsonb_array_length(v_errors)=0,
    'valid',jsonb_array_length(v_errors)=0,
    'requested_timesheet_id',p_timesheet_id,
    'root_timesheet_id',v_root_id,
    'latest_positive_timesheet_id',v_latest_positive,
    'member_count',v_member_count,'member_ids',to_jsonb(v_member_ids),
    'member_timesheet_ids',to_jsonb(v_member_ids),'members',v_members,
    'correction_units',v_units,'pairs',v_units,'requested_correction_unit',v_requested_unit,
    'correction_shape',v_requested_unit->>'correction_shape',
    'correction_financials_policy_required',v_requested_unit->'policy_envelope' is not null,
    'correction_financials_policy_envelope_required',v_requested_unit->'policy_envelope' is not null,
    'correction_financials_policy_envelope',v_requested_unit->'policy_envelope',
    'correction_financials_policy_envelope_fingerprint',v_requested_unit->>'envelope_fingerprint',
    'chain_fingerprint',v_chain_fingerprint,'errors',v_errors
  );
end;
$function$;

create or replace function public.timesheet_correction_pair_transition_v1(
  p_timesheet_id uuid,
  p_action text,
  p_actor_user_id uuid,
  p_operation_id uuid default null,
  p_expected_chain_fingerprint text default null,
  p_lock_rows boolean default true,
  p_max_members integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','extensions','pg_temp'
as $function$
declare
  v_action text:=upper(btrim(coalesce(p_action,'')));
  v_chain jsonb;
  v_unit jsonb;
  v_envelope jsonb;
  v_ids uuid[]:=array[]::uuid[];
  v_expected_count integer;
  v_rows jsonb:='[]'::jsonb;
  v_items jsonb:='[]'::jsonb;
  v_errors jsonb:='[]'::jsonb;
  v_authorised integer:=0;
  v_unauthorised integer:=0;
  v_ready integer:=0;
  v_processed integer:=0;
  v_unprocessed integer:=0;
  v_paid integer:=0;
  v_invoiced integer:=0;
  v_action_ready boolean:=false;
  v_idempotent boolean:=false;
  v_required_rpc text;
  r record;
  v_leg jsonb;
  v_actual_envelope_fingerprint text;
  v_actual_leg_fingerprint text;
  v_values_match boolean;
begin
  v_unit:=private.timesheet_correction_whole_transition_v1(p_timesheet_id,p_action,p_actor_user_id,
    p_expected_chain_fingerprint,p_lock_rows,p_max_members);
  if v_unit is not null then
    if p_operation_id is not null then raise exception 'WHOLE_CORRECTION_IMPORT_OPERATION_FORBIDDEN' using errcode='22023'; end if;
    return v_unit;
  end if;
  if p_timesheet_id is null or p_actor_user_id is null then
    raise exception 'CORRECTION_TRANSITION_REQUIRED_ARGUMENT_MISSING' using errcode='22023';
  end if;
  if v_action not in ('AUTHORISE','UNAUTHORISE','PROCESS','UNPROCESS') then
    raise exception 'CORRECTION_TRANSITION_ACTION_INVALID' using errcode='22023';
  end if;
  if p_max_members<1 or p_max_members>100 then
    raise exception 'CORRECTION_TRANSITION_MEMBER_LIMIT_INVALID' using errcode='22023';
  end if;
  perform 1 from public.tms_users u where u.id=p_actor_user_id and coalesce(u.is_active,false);
  if not found then raise exception 'CORRECTION_TRANSITION_ACTOR_INVALID' using errcode='42501'; end if;

  if p_operation_id is not null then
    perform 1 from public.import_apply_operations o
    where o.id=p_operation_id and o.actor_user_id=p_actor_user_id
      and o.state in ('PREPARED','SOURCE_COMMITTED_TSFIN_PENDING','FINANCIALISED_PENDING_FINALISATION')
    for update;
    if not found then raise exception 'CORRECTION_TRANSITION_OPERATION_INVALID' using errcode='P0001'; end if;
  end if;

  v_chain:=public.timesheet_correction_chain_scope_v1(p_timesheet_id,p_lock_rows,32,p_max_members);
  if coalesce((v_chain->>'valid')::boolean,false) is not true then
    raise exception 'CORRECTION_TRANSITION_CHAIN_INVALID' using errcode='P0001',detail=v_chain::text;
  end if;
  if nullif(btrim(coalesce(p_expected_chain_fingerprint,'')),'') is not null
     and p_expected_chain_fingerprint is distinct from v_chain->>'chain_fingerprint' then
    raise exception 'CORRECTION_TRANSITION_CHAIN_STALE' using errcode='40001';
  end if;
  v_unit:=v_chain->'requested_correction_unit';
  if jsonb_typeof(v_unit)<>'object' then
    raise exception 'CORRECTION_TRANSITION_UNIT_NOT_FOUND' using errcode='22023';
  end if;
  if coalesce((v_unit->>'valid')::boolean,false) is not true then
    raise exception 'CORRECTION_TRANSITION_UNIT_INVALID' using errcode='P0001',detail=v_unit::text;
  end if;
  v_envelope:=v_unit->'policy_envelope';
  v_expected_count:=(v_unit->>'expected_member_count')::integer;
  select coalesce(array_agg(value::uuid order by value::text),array[]::uuid[])
  into v_ids from jsonb_array_elements_text(v_unit->'member_ids');
  if cardinality(v_ids)<>v_expected_count then
    raise exception 'CORRECTION_TRANSITION_MEMBER_COUNT_MISMATCH' using errcode='P0001';
  end if;

  if p_lock_rows then
    perform 1 from public.timesheets ts where ts.timesheet_id=any(v_ids)
    order by ts.timesheet_id for update;
    perform 1 from public.timesheets_financials tf
    where tf.timesheet_id=any(v_ids) and tf.is_current=true
    order by tf.timesheet_id,tf.id for update;
  end if;

  for r in
    select ts.*,tf.id tsfin_id,tf.processing_status,tf.processed_at_utc,
      tf.authorised_at_utc,tf.is_stale,tf.paid_at_utc,tf.locked_by_invoice_id,
      tf.candidate_id,tf.client_id,tf.pay_method,tf.has_rate_issue,tf.has_pay_channel_issue,
      tf.policy_snapshot_json,tf.rate_source_refs_json,tf.pay_vat_rate_pct_snapshot,
      exists(select 1 from public.invoice_lines il where il.timesheet_id=ts.timesheet_id) invoice_lined
    from public.timesheets ts
    left join public.timesheets_financials tf on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
    where ts.timesheet_id=any(v_ids)
    order by ts.timesheet_id
  loop
    v_leg:=public._ctms_correction_policy_leg_read_v1(r.timesheet_id);
    v_actual_envelope_fingerprint:=coalesce(
      r.policy_snapshot_json->>'correction_financials_policy_envelope_fingerprint',
      r.policy_snapshot_json#>>'{correction_financials_policy_envelope,envelope_fingerprint}',
      r.rate_source_refs_json->>'correction_financials_policy_envelope_fingerprint'
    );
    v_actual_leg_fingerprint:=coalesce(
      r.policy_snapshot_json->>'correction_leg_fingerprint',
      r.rate_source_refs_json->>'correction_leg_fingerprint'
    );
    v_values_match:=
      v_actual_envelope_fingerprint is not distinct from v_envelope->>'envelope_fingerprint'
      and v_actual_leg_fingerprint is not distinct from v_leg->>'leg_fingerprint'
      and case when coalesce(r.policy_snapshot_json->>'erni_pct','')~'^-?[0-9]+([.][0-9]+)?$'
        then (r.policy_snapshot_json->>'erni_pct')::numeric is not distinct from (v_leg#>>'{tsfin_policy,erni_pct}')::numeric else false end
      and upper(btrim(coalesce(r.policy_snapshot_json->>'apply_erni_to','')))=upper(btrim(coalesce(v_leg#>>'{tsfin_policy,apply_erni_to}','')))
      and coalesce(r.pay_vat_rate_pct_snapshot,
        case when coalesce(r.policy_snapshot_json->>'pay_vat_rate_pct','')~'^-?[0-9]+([.][0-9]+)?$'
          then (r.policy_snapshot_json->>'pay_vat_rate_pct')::numeric else null end)
        is not distinct from (v_leg#>>'{tsfin_policy,applied_pay_vat_rate_pct}')::numeric
      and coalesce(r.policy_snapshot_json->>'correction_tsfin_policy_fingerprint','')
        is not distinct from v_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}'
      and coalesce(r.policy_snapshot_json->>'correction_invoice_policy_fingerprint','')
        is not distinct from v_leg#>>'{invoice_policy,invoice_policy_fingerprint}';

    if r.authorised_at_server is not null and r.authorised_at_utc is not null then v_authorised:=v_authorised+1; end if;
    if r.authorised_at_server is null and r.authorised_at_utc is null then v_unauthorised:=v_unauthorised+1; end if;
    if r.tsfin_id is not null and not coalesce(r.is_stale,false)
       and r.candidate_id is not null and r.client_id is not null
       and nullif(btrim(coalesce(r.pay_method,'')),'') is not null
       and not coalesce(r.has_rate_issue,false) and not coalesce(r.has_pay_channel_issue,false)
       and v_values_match then v_ready:=v_ready+1; end if;
    if r.processed_at_utc is not null or r.processing_status in (
      'READY_FOR_HR'::public.ts_fin_processing_status_enum,
      'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum,
      'PENDING_AUTH'::public.ts_fin_processing_status_enum) then v_processed:=v_processed+1; end if;
    if r.processed_at_utc is null and r.processing_status='UNPROCESSED'::public.ts_fin_processing_status_enum then v_unprocessed:=v_unprocessed+1; end if;
    if r.paid_at_utc is not null then v_paid:=v_paid+1; end if;
    if r.invoice_lined or r.locked_by_invoice_id is not null then v_invoiced:=v_invoiced+1; end if;
    if not v_values_match then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_LEG_POLICY_NOT_FROZEN','timesheet_id',r.timesheet_id));
    end if;
    v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
      'timesheet_id',r.timesheet_id,'correction_kind',r.correction_kind,
      'timesheet_authorised',r.authorised_at_server is not null,
      'tsfin_authorised',r.authorised_at_utc is not null,'tsfin_id',r.tsfin_id,
      'processing_status',r.processing_status,'policy_ready',v_values_match,
      'leg_fingerprint',v_leg->>'leg_fingerprint'));
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'timesheet_id',r.timesheet_id,'expected_timesheet_id',r.timesheet_id,
      'expected_version',r.version,
      'expected_policy_envelope_fingerprint',v_envelope->>'envelope_fingerprint',
      'expected_leg_fingerprint',v_leg->>'leg_fingerprint'));
  end loop;

  case v_action
    when 'AUTHORISE' then
      v_idempotent:=v_authorised=v_expected_count;
      v_action_ready:=v_idempotent or (v_unauthorised=v_expected_count and v_ready=v_expected_count);
      v_required_rpc:=case when v_idempotent then null else 'timesheet_authorise_bulk_atomic' end;
    when 'UNAUTHORISE' then
      v_idempotent:=v_unauthorised=v_expected_count;
      v_action_ready:=v_idempotent or v_authorised=v_expected_count;
      v_required_rpc:=case when v_idempotent then null else 'timesheet_unauthorise_bulk_atomic' end;
    when 'PROCESS' then
      v_idempotent:=v_processed=v_expected_count;
      v_action_ready:=v_idempotent or v_unprocessed=v_expected_count;
      v_required_rpc:=case when v_idempotent then null else 'contract_week_manual_upsert_bulk_process_atomic' end;
    when 'UNPROCESS' then
      v_idempotent:=v_unprocessed=v_expected_count;
      v_action_ready:=v_idempotent or v_processed=v_expected_count;
      v_required_rpc:=case when v_idempotent then null else 'contract_week_manual_unprocess_atomic' end;
  end case;
  if not v_action_ready then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_UNIT_ACTION_STATE_INVALID')); end if;

  return jsonb_build_object(
    'ok',true,'valid',jsonb_array_length(v_errors)=0,'action',v_action,
    'action_ready',v_action_ready and jsonb_array_length(v_errors)=0,'idempotent_state',v_idempotent,
    'operation_id',p_operation_id,'root_timesheet_id',v_chain->>'root_timesheet_id',
    'correction_id',v_unit->>'correction_id','correction_shape',v_unit->>'correction_shape',
    'expected_member_count',v_expected_count,'pair_timesheet_ids',to_jsonb(v_ids),
    'correction_financials_policy_envelope',v_envelope,
    'correction_financials_policy_envelope_fingerprint',v_envelope->>'envelope_fingerprint',
    'chain_fingerprint',v_chain->>'chain_fingerprint','pair_rows',v_rows,
    'transition_items',v_items,'required_backend_rpc',v_required_rpc,
    'authorised_count',v_authorised,'unauthorised_count',v_unauthorised,
    'ready_count',v_ready,'processed_count',v_processed,'unprocessed_count',v_unprocessed,
    'paid_count',v_paid,'invoice_lined_count',v_invoiced,'errors',v_errors);
end;
$function$;

create or replace function public.timesheet_correction_pair_lifecycle_preview_v1(
  p_items jsonb,
  p_action text,
  p_actor_user_id uuid,
  p_max_members integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','extensions','pg_temp'
as $function$
declare
  v_action text:=upper(btrim(coalesce(p_action,'')));
  v_item jsonb;
  v_id_text text;
  v_id uuid;
  v_class jsonb;
  v_transition jsonb;
  v_group jsonb;
  v_groups jsonb:='[]'::jsonb;
  v_seen text[]:=array[]::text[];
  v_selected_count integer:=0;
  v_affected_count integer:=0;
  v_ordinary_count integer:=0;
  v_valid boolean:=true;
  v_repairable_mixed boolean:=false;
  v_already_target_state boolean:=false;
  v_group_ready boolean:=false;
  v_group_fingerprint text;
  v_members jsonb;
  v_errors jsonb;
begin
  if v_action not in ('AUTHORISE','UNAUTHORISE') then
    raise exception 'CORRECTION_LIFECYCLE_ACTION_INVALID' using errcode='22023';
  end if;
  if p_actor_user_id is null then
    raise exception 'CORRECTION_LIFECYCLE_ACTOR_REQUIRED' using errcode='22023';
  end if;
  if p_max_members<1 or p_max_members>100
     or jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array'
     or jsonb_array_length(coalesce(p_items,'[]'::jsonb))>p_max_members then
    raise exception 'CORRECTION_LIFECYCLE_ITEMS_INVALID' using errcode='22023';
  end if;

  v_selected_count:=jsonb_array_length(coalesce(p_items,'[]'::jsonb));
  for v_item in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb))
  loop
    v_id_text:=nullif(btrim(coalesce(
      v_item->>'timesheet_id',v_item->>'timesheetId',
      v_item->>'current_timesheet_id',v_item->>'currentTimesheetId',
      v_item->>'requested_timesheet_id',v_item->>'requestedTimesheetId',
      case when coalesce(v_item->>'row_key','') like 'timesheet:%'
        then substring(v_item->>'row_key' from 11) end,'')), '');
    if v_id_text is null or v_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_valid:=false;
      v_groups:=v_groups||jsonb_build_array(jsonb_build_object(
        'valid',false,'action_ready',false,'errors',jsonb_build_array(
          jsonb_build_object('code','TIMESHEET_ID_REQUIRED'))));
      continue;
    end if;

    v_id:=v_id_text::uuid;
    v_class:=public._ctms_import_correction_classify_v1(v_id);
    if exists(select 1 from private.timesheet_correction_requests request
      where v_id in(request.replacement_timesheet_id,request.reversal_timesheet_id)
        and request.correction_id=(select t.correction_id from public.timesheets t where t.timesheet_id=v_id)) then
      select jsonb_build_object('is_import_authoritative_correction',true,'correction_id',request.correction_id)
        into v_class from private.timesheet_correction_requests request
        where v_id in(request.replacement_timesheet_id,request.reversal_timesheet_id);
    end if;
    if coalesce((v_class->>'is_import_authoritative_correction')::boolean,false) is not true then
      v_ordinary_count:=v_ordinary_count+1;
      continue;
    end if;
    if nullif(v_class->>'correction_id','')=any(v_seen) then continue; end if;
    v_seen:=array_append(v_seen,v_class->>'correction_id');

    v_transition:=public.timesheet_correction_pair_transition_v1(
      v_id,v_action,p_actor_user_id,null::uuid,null::text,false,p_max_members);
    v_errors:=coalesce(v_transition->'errors','[]'::jsonb);
    v_repairable_mixed:=
      coalesce((v_transition->>'expected_member_count')::integer,0)=2
      and coalesce((v_transition->>'authorised_count')::integer,0)>0
      and coalesce((v_transition->>'unauthorised_count')::integer,0)>0
      and coalesce((v_transition->>'authorised_count')::integer,0)
          +coalesce((v_transition->>'unauthorised_count')::integer,0)=2
      and coalesce((v_transition->>'paid_count')::integer,0)=0
      and coalesce((v_transition->>'invoice_lined_count')::integer,0)=0
      and (select count(*)=1 and bool_and(e->>'code'='CORRECTION_UNIT_ACTION_STATE_INVALID')
           from jsonb_array_elements(v_errors) e)
      and (v_action='UNAUTHORISE'
        or coalesce((v_transition->>'ready_count')::integer,0)=2);
    v_already_target_state:=coalesce((v_transition->>'expected_member_count')::integer,0)=2
      and coalesce((v_transition->>'paid_count')::integer,0)=0
      and coalesce((v_transition->>'invoice_lined_count')::integer,0)=0
      and ((v_action='AUTHORISE' and coalesce((v_transition->>'authorised_count')::integer,0)=2)
        or (v_action='UNAUTHORISE' and coalesce((v_transition->>'unauthorised_count')::integer,0)=2));
    v_group_ready:=coalesce((v_transition->>'action_ready')::boolean,false)
      or v_repairable_mixed or v_already_target_state;

    select coalesce(jsonb_agg(
      row_json||jsonb_build_object(
        'signed_hours',jsonb_build_object(
          'day',coalesce(tf.hours_day,0),'night',coalesce(tf.hours_night,0),
          'sat',coalesce(tf.hours_sat,0),'sun',coalesce(tf.hours_sun,0),
          'bh',coalesce(tf.hours_bh,0),
          'total',coalesce(tf.hours_day,0)+coalesce(tf.hours_night,0)+coalesce(tf.hours_sat,0)+coalesce(tf.hours_sun,0)+coalesce(tf.hours_bh,0)),
        'current_state',case when coalesce((row_json->>'timesheet_authorised')::boolean,false)
          and coalesce((row_json->>'tsfin_authorised')::boolean,false) then 'AUTHORISED' else 'UNAUTHORISED' end,
        'resulting_state',case when v_action='AUTHORISE' then 'AUTHORISED' else 'UNAUTHORISED' end)
      order by case row_json->>'correction_kind' when 'CHANGED_HOURS_REVERSAL' then 1 else 2 end),
      '[]'::jsonb)
    into v_members
    from jsonb_array_elements(coalesce(v_transition->'pair_rows','[]'::jsonb)) row_json
    left join public.timesheets_financials tf
      on tf.timesheet_id=nullif(row_json->>'timesheet_id','')::uuid and tf.is_current=true;

    v_group_fingerprint:=public._import_review_hash_v1(concat_ws('|',
      'correction-lifecycle-preview-v1',v_action,v_transition->>'chain_fingerprint',
      v_transition->>'correction_id',v_members::text,v_group_ready));
    v_group:=v_transition||jsonb_build_object(
      'valid',v_group_ready,'action_ready',v_group_ready,
      'repairing_legacy_mixed_state',v_repairable_mixed,
      'already_in_target_state',v_already_target_state,
      'source_system',case
        when exists(select 1 from jsonb_array_elements(v_members) m
          join public.timesheets t on t.timesheet_id=(m->>'timesheet_id')::uuid
          left join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
          where upper(coalesce(
            t.candidate_hint_text#>>'{correction_financials_policy_envelope,classification,source_system}',
            tf.policy_snapshot_json#>>'{correction_financials_policy_envelope,classification,source_system}',
            tf.rate_source_refs_json#>>'{correction_financials_policy_envelope,classification,source_system}',
            case when tf.basis in ('NHSP','NHSP_ADJUSTMENT') then 'NHSP' end,''))='NHSP')
        then 'NHSP' else 'HealthRoster' end,
      'members',v_members,'pair_fingerprint',v_group_fingerprint,
      'errors',case when v_repairable_mixed or v_already_target_state then '[]'::jsonb else v_errors end);
    v_groups:=v_groups||jsonb_build_array(v_group);
    v_affected_count:=v_affected_count+coalesce((v_transition->>'expected_member_count')::integer,0);
    if not v_group_ready then v_valid:=false; end if;
  end loop;

  return jsonb_build_object(
    'ok',true,'valid',v_valid,'action',v_action,
    'selected_count',v_selected_count,
    'ordinary_timesheet_count',v_ordinary_count,
    'correction_pair_count',jsonb_array_length(v_groups),
    'affected_timesheet_count',v_ordinary_count+v_affected_count,
    'groups',v_groups,
    'preview_fingerprint',public._import_review_hash_v1(concat_ws('|',
      'correction-lifecycle-batch-preview-v1',v_action,v_selected_count,v_groups::text)));
end;
$function$;

create or replace function public._ctms_expand_lifecycle_items_v1(
  p_items jsonb,
  p_action text,
  p_actor_user_id uuid,
  p_max_members integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'extensions', 'pg_temp'
as $function$
declare
  v_action text := upper(btrim(coalesce(p_action, '')));
  v_result jsonb := '[]'::jsonb;
  v_seen_correction_ids text[] := array[]::text[];
  v_item jsonb;
  v_id_text text;
  v_id uuid;
  v_class jsonb;
  v_transition jsonb;
  v_preview jsonb;
  v_group jsonb;
  v_transition_item jsonb;
  v_expected_pair_fingerprint text;
  v_correction_id text;
begin
  if v_action not in ('AUTHORISE', 'UNAUTHORISE') then
    raise exception 'CORRECTION_LIFECYCLE_ACTION_INVALID' using errcode = '22023';
  end if;
  if p_actor_user_id is null then
    raise exception 'CORRECTION_LIFECYCLE_ACTOR_REQUIRED' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_items, '[]'::jsonb)) > p_max_members then
    raise exception 'CORRECTION_LIFECYCLE_ITEMS_INVALID' using errcode = '22023';
  end if;

  for v_item in
    select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
  loop
    v_id_text := nullif(btrim(coalesce(
      v_item ->> 'timesheet_id', v_item ->> 'timesheetId',
      v_item ->> 'current_timesheet_id', v_item ->> 'currentTimesheetId',
      v_item ->> 'requested_timesheet_id', v_item ->> 'requestedTimesheetId',
      case when coalesce(v_item ->> 'row_key', '') like 'timesheet:%'
        then substring(v_item ->> 'row_key' from 11) end,
      ''
    )), '');

    if v_id_text is null
       or v_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_result := v_result || jsonb_build_array(v_item);
      continue;
    end if;

    v_id := v_id_text::uuid;
    if exists(select 1 from private.timesheet_correction_requests request
      where request.state='APPLIED' and request.reversed_timesheet_id=v_id) then
      if v_action='AUTHORISE' and exists(select 1 from private.timesheet_correction_requests request
        where request.state='APPLIED' and request.reversed_timesheet_id=v_id
          and coalesce((request.terminal_receipt_json->>'original_authorisation_required')::boolean,false)
          and exists(select 1 from public.timesheets t where t.timesheet_id=v_id and t.authorised_at_server is null)
          and (request.replacement_timesheet_id=any(public._ctms_payload_timesheet_ids_v1(p_items,p_max_members))
            or request.reversal_timesheet_id=any(public._ctms_payload_timesheet_ids_v1(p_items,p_max_members)))) then
        -- The adjacent WHOLE arm adds this A0 member exactly once. T0-only
        -- ordinary Authorise remains available while the request is WAITING.
        continue;
      end if;
      raise exception 'AGENCY_INVOICE_SUPERSEDED' using errcode='55000';
    end if;
    v_class := public._ctms_import_correction_classify_v1(v_id);
    if exists(select 1 from private.timesheet_correction_requests request
      where v_id in(request.replacement_timesheet_id,request.reversal_timesheet_id)
        and request.correction_id=(select t.correction_id from public.timesheets t where t.timesheet_id=v_id)) then
      select jsonb_build_object('is_import_authoritative_correction',true,'correction_id',request.correction_id)
        into v_class from private.timesheet_correction_requests request
        where v_id in(request.replacement_timesheet_id,request.reversal_timesheet_id);
    end if;
    if coalesce((v_class ->> 'is_import_authoritative_correction')::boolean, false) is not true then
      v_result := v_result || jsonb_build_array(v_item);
      continue;
    end if;

    v_correction_id := nullif(v_class ->> 'correction_id', '');
    if v_correction_id = any(v_seen_correction_ids) then
      continue;
    end if;

    v_preview:=public.timesheet_correction_pair_lifecycle_preview_v1(
      jsonb_build_array(v_item),v_action,p_actor_user_id,p_max_members);
    v_group:=v_preview#>'{groups,0}';
    v_transition:=public.timesheet_correction_pair_transition_v1(
      v_id,v_action,p_actor_user_id,null::uuid,v_group->>'chain_fingerprint',true,p_max_members);
    v_expected_pair_fingerprint:=nullif(btrim(coalesce(
      v_item->>'expected_pair_fingerprint',v_item->>'pair_fingerprint','')),'');
    if v_expected_pair_fingerprint is not null
       and v_expected_pair_fingerprint is distinct from v_group->>'pair_fingerprint' then
      raise exception 'CORRECTION_UNIT_LIFECYCLE_PREVIEW_STALE'
        using errcode='40001',detail=v_group::text;
    end if;
    if coalesce((v_group->>'valid')::boolean,false) is not true
       or coalesce((v_group->>'action_ready')::boolean,false) is not true then
      raise exception 'CORRECTION_UNIT_LIFECYCLE_TRANSITION_BLOCKED'
        using errcode = 'P0001', detail = v_group::text;
    end if;

    v_seen_correction_ids := array_append(v_seen_correction_ids, v_correction_id);
    for v_transition_item in
      select value from jsonb_array_elements(coalesce(v_transition->'transition_items','[]'::jsonb))
    loop
      v_result:=v_result||jsonb_build_array(v_transition_item||jsonb_build_object(
        'lifecycle_group_id','correction:'||v_correction_id,
        'lifecycle_group_size',coalesce((v_transition->>'expected_member_count')::integer,2),
        'pair_fingerprint',v_group->>'pair_fingerprint',
        'selected_timesheet_id',v_id,
        'repairing_legacy_mixed_state',coalesce((v_group->>'repairing_legacy_mixed_state')::boolean,false)
      ));
    end loop;
  end loop;

  if jsonb_array_length(v_result) > p_max_members then
    raise exception 'CORRECTION_LIFECYCLE_EXPANSION_TOO_LARGE' using errcode = '22023';
  end if;
  return v_result;
end;
$function$;

create or replace function private._timesheet_cross_record_overlap_assert_v1(
  p_candidate_id uuid,
  p_submission_json jsonb,
  p_actual_schedule_json jsonb,
  p_worked_start_iso timestamptz,
  p_worked_end_iso timestamptz,
  p_exclude_workflow_id uuid,
  p_exclude_timesheet_id uuid,
  p_exclude_booking_id text
) returns void language plpgsql volatile security definer
set search_path='public','private','pg_temp' as $function$
declare
  v_new_count integer:=0;
  v_conflict_kind text;
  v_conflict_id uuid;
  v_conflict_start timestamptz;
  v_conflict_end timestamptz;
  v_exact_chain jsonb;
  v_exact_correction_member_ids uuid[]:=array[]::uuid[];
  v_exact_correction_member_count integer:=0;
begin
  if p_candidate_id is null then
    raise exception using errcode='PT409',message='TIMESHEET_CANDIDATE_IDENTITY_REQUIRED_FOR_OVERLAP_CHECK';
  end if;

  select count(*)::integer into v_new_count
  from private._timesheet_work_intervals_v1(
    COALESCE(p_submission_json,'{}'::jsonb),p_actual_schedule_json,
    p_worked_start_iso,p_worked_end_iso
  );
  if v_new_count=0 then return; end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'timesheet-cross-record-overlap:'||p_candidate_id::text,31082026
  ));

  -- The correction-chain authority is consulted only for a current row that it
  -- classifies as an authoritative import correction. The exclusion activates
  -- only when every member of the resolved chain is accounted for by the root
  -- plus valid correction units and the requested unit is itself exact. This
  -- prevents an ordinary child, incomplete/tampered pair, duplicate leg or
  -- unrelated overlapping Timesheet from entering the exclusion set.
  if p_exclude_timesheet_id is not null
     and COALESCE((
       public._ctms_import_correction_classify_v1(p_exclude_timesheet_id)
         ->>'is_import_authoritative_correction'
     )::boolean,false) then
    v_exact_chain:=public.timesheet_correction_chain_scope_v1(
      p_exclude_timesheet_id,false,32,100
    );

    if COALESCE((v_exact_chain->>'valid')::boolean,false)
       and jsonb_typeof(v_exact_chain->'requested_correction_unit')='object'
       and COALESCE((
         v_exact_chain->'requested_correction_unit'->>'valid'
       )::boolean,false)
       and not exists (
         select 1
         from jsonb_array_elements(
           COALESCE(v_exact_chain->'correction_units','[]'::jsonb)
         ) correction_unit(unit_json)
         where COALESCE((correction_unit.unit_json->>'valid')::boolean,false) is not true
       ) then
      select COALESCE(
               array_agg(distinct exact_member.member_id order by exact_member.member_id),
               array[]::uuid[]
             )
      into v_exact_correction_member_ids
      from (
        select nullif(v_exact_chain->>'root_timesheet_id','')::uuid as member_id
        union all
        select correction_member.member_id_text::uuid
        from jsonb_array_elements(
          COALESCE(v_exact_chain->'correction_units','[]'::jsonb)
        ) correction_unit(unit_json)
        cross join lateral jsonb_array_elements_text(
          COALESCE(correction_unit.unit_json->'member_ids','[]'::jsonb)
        ) correction_member(member_id_text)
        where COALESCE((correction_unit.unit_json->>'valid')::boolean,false)
      ) exact_member
      where exact_member.member_id is not null;

      v_exact_correction_member_count:=COALESCE(
        (v_exact_chain->>'member_count')::integer,0
      );
      if v_exact_correction_member_count<>cardinality(v_exact_correction_member_ids)
         or p_exclude_timesheet_id<>all(v_exact_correction_member_ids) then
        v_exact_correction_member_ids:=array[]::uuid[];
      end if;
    end if;
  end if;

  -- Exact request membership is available before the P0/R0 row insert.
  -- Include historic applied WHOLE members of this immutable root so repeated
  -- corrections do not conflict with their own original signed workflows.
  if exists(select 1 from private.timesheet_correction_requests request
    where request.candidate_id=p_candidate_id and request.state in('WAITING','APPLIED')
      and (p_exclude_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id)
        or p_exclude_timesheet_id::text=request.frozen_original_json->>'planned_reversal_timesheet_id')
      and (p_exclude_booking_id is null or p_exclude_booking_id in(request.replacement_booking_id,request.reversal_booking_id)
        or p_exclude_timesheet_id::text=request.frozen_original_json->>'planned_reversal_timesheet_id')) then
    select coalesce(array_agg(distinct member order by member),array[]::uuid[]) into v_exact_correction_member_ids
      from private.timesheet_correction_requests owner
      join private.timesheet_correction_requests request on request.root_timesheet_id=owner.root_timesheet_id
        and request.candidate_id=owner.candidate_id and request.state in('WAITING','APPLIED')
      cross join lateral unnest(array[request.root_timesheet_id,request.reversed_timesheet_id,
        request.replacement_timesheet_id,request.reversal_timesheet_id,
        (request.frozen_original_json->>'planned_reversal_timesheet_id')::uuid]) member
      where owner.candidate_id=p_candidate_id and owner.state in('WAITING','APPLIED')
        and (p_exclude_timesheet_id in(owner.replacement_timesheet_id,owner.reversal_timesheet_id)
          or p_exclude_timesheet_id::text=owner.frozen_original_json->>'planned_reversal_timesheet_id') and member is not null;
  end if;

  with new_intervals as materialized (
    select * from private._timesheet_work_intervals_v1(
      COALESCE(p_submission_json,'{}'::jsonb),p_actual_schedule_json,
      p_worked_start_iso,p_worked_end_iso
    )
  )
  select 'WORKFLOW',w.id,existing.work_start_utc,existing.work_end_utc
  into v_conflict_kind,v_conflict_id,v_conflict_start,v_conflict_end
  from public.candidate_submission_workflows w
  cross join lateral private._timesheet_work_intervals_v1(
    COALESCE(w.immutable_submission_json,'{}'::jsonb),null,null,null
  ) existing
  join new_intervals proposed
    on proposed.work_start_utc<existing.work_end_utc
   and existing.work_start_utc<proposed.work_end_utc
  where w.candidate_id=p_candidate_id
    and w.id is distinct from p_exclude_workflow_id
    and not (coalesce(w.target_timesheet_id=any(v_exact_correction_member_ids),false) or coalesce(w.anchor_timesheet_id=any(v_exact_correction_member_ids),false))
    and w.worker_submitted_at_utc is not null
    and w.state in (
      'WORKER_SUBMITTED','WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',
      'READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL',
      'MANAGER_APPROVED','MANAGER_APPROVED_PENDING_FINAL_DOCUMENT',
      'READY_TO_FINALISE','AWAITING_PAPER_RETURN','RECEIVED','FINALISED'
    )
    and not (
      p_exclude_booking_id is not null and exists(
        select 1 from public.timesheets linked
        where linked.timesheet_id in (w.target_timesheet_id,w.anchor_timesheet_id)
          and linked.booking_id=p_exclude_booking_id
      )
    )
  order by existing.work_start_utc,w.id
  limit 1;

  if v_conflict_id is null then
    with new_intervals as materialized (
      select * from private._timesheet_work_intervals_v1(
        COALESCE(p_submission_json,'{}'::jsonb),p_actual_schedule_json,
        p_worked_start_iso,p_worked_end_iso
      )
    ), accepted_timesheets as materialized (
      select t.timesheet_id,t.booking_id,t.actual_schedule_json,
        t.worked_start_iso,t.worked_end_iso
      from public.timesheets_financials f
      join public.timesheets t on t.timesheet_id=f.timesheet_id
      where f.candidate_id=p_candidate_id and f.is_current=true
        and t.is_current=true and t.revoked_at is null
        and (t.authorised_at_server is not null or f.authorised_at_utc is not null)
      union
      select t.timesheet_id,t.booking_id,t.actual_schedule_json,
        t.worked_start_iso,t.worked_end_iso
      from public.contracts c
      join public.timesheets t on t.contract_id=c.id
      where c.candidate_id=p_candidate_id and t.is_current=true
        and t.revoked_at is null and t.authorised_at_server is not null
      union
      select t.timesheet_id,t.booking_id,t.actual_schedule_json,
        t.worked_start_iso,t.worked_end_iso
      from public.candidates c
      join public.timesheets t on t.occupant_key_norm=c.key_norm
      where c.id=p_candidate_id and c.key_norm is not null
        and t.is_current=true and t.revoked_at is null
        and t.authorised_at_server is not null
    )
    select 'TIMESHEET',t.timesheet_id,existing.work_start_utc,existing.work_end_utc
    into v_conflict_kind,v_conflict_id,v_conflict_start,v_conflict_end
    from accepted_timesheets t
    cross join lateral private._timesheet_work_intervals_v1(
      '{}'::jsonb,t.actual_schedule_json,t.worked_start_iso,t.worked_end_iso
    ) existing
    join new_intervals proposed
      on proposed.work_start_utc<existing.work_end_utc
     and existing.work_start_utc<proposed.work_end_utc
    where t.timesheet_id is distinct from p_exclude_timesheet_id
      and not (t.timesheet_id=any(v_exact_correction_member_ids))
      and (p_exclude_booking_id is null or t.booking_id<>p_exclude_booking_id)
    order by existing.work_start_utc,t.timesheet_id
    limit 1;
  end if;

  if v_conflict_id is not null then
    raise exception using
      errcode='PT409',
      message='TIMESHEET_WORK_INTERVAL_OVERLAP',
      detail=jsonb_build_object(
        'error_code','TIMESHEET_WORK_INTERVAL_OVERLAP',
        'conflicting_record_kind',v_conflict_kind,
        'conflicting_record_id',v_conflict_id,
        'conflicting_start_utc',v_conflict_start,
        'conflicting_end_utc',v_conflict_end
      )::text;
  end if;
end;$function$;

-- Owner-created, transaction-bound capability. It is not a client flag or a
-- broad workflow retirement exemption and contains no durable business store.
create or replace function private.timesheet_correction_cancel_capability_v1(p_timesheet_id uuid,p_actor_user_id uuid default null)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_cap jsonb; v_request private.timesheet_correction_requests%rowtype; v_p public.timesheets%rowtype;
begin
  if to_regclass('pg_temp.timesheet_correction_cancel_capability_v1') is null
    or not exists(select 1 from pg_class c where c.oid=to_regclass('pg_temp.timesheet_correction_cancel_capability_v1')
      and c.relowner=(select p.proowner from pg_proc p where p.oid='private.timesheet_correction_cancel_capability_v1(uuid,uuid)'::regprocedure)) then
    return null;
  end if;
  execute 'select to_jsonb(cap) from pg_temp.timesheet_correction_cancel_capability_v1 cap where cap.timesheet_id=$1 and cap.backend_pid=pg_backend_pid() and cap.transaction_id=txid_current()'
    into v_cap using p_timesheet_id;
  if v_cap is null or (p_actor_user_id is not null and v_cap->>'actor_user_id' is distinct from p_actor_user_id::text) then return null; end if;
  select request.* into v_request from private.timesheet_correction_requests request where request.id=(v_cap->>'request_id')::uuid;
  select t.* into v_p from public.timesheets t where t.timesheet_id=p_timesheet_id;
  if v_request.state is distinct from 'WAITING' or v_request.state_revision::text is distinct from v_cap->>'state_revision'
    or v_request.replacement_timesheet_id is distinct from p_timesheet_id
    or v_p.timesheet_id is null or not v_p.is_current or v_p.authorised_at_server is not null
    or v_p.booking_id is distinct from v_request.replacement_booking_id
    or v_p.contract_id is distinct from v_request.contract_id
    or v_p.week_ending_date is distinct from v_request.week_ending_date
    or v_p.parent_timesheet_id is distinct from v_request.root_timesheet_id
    or v_p.correction_id is distinct from v_request.correction_id
    or v_p.correction_kind is distinct from 'WHOLE_TIMESHEET_REPLACEMENT'
    or v_p.candidate_workflow_id::text is distinct from v_cap->>'workflow_id'
    or v_p.candidate_workflow_generation::text is distinct from v_cap->>'workflow_generation'
    or exists(select 1 from public.invoice_lines l where l.timesheet_id=p_timesheet_id)
    or exists(select 1 from public.timesheets_financials tf where tf.timesheet_id=p_timesheet_id
      and (tf.authorised_at_utc is not null or tf.paid_at_utc is not null or tf.locked_by_invoice_id is not null
        or tf.unlocked_by_credit_note_id is not null or tf.processed_at_utc is not null
        or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
          then tf.invoice_breakdown_json->'segments' else '[]'::jsonb end) s
          where nullif(s->>'invoice_locked_invoice_id','') is not null or nullif(s->>'invoice_locked_at_utc','') is not null
            or s->>'pay_locked'='true' or nullif(s->>'pay_locked_at_utc','') is not null)))
    or private.timesheet_correction_actor_allowed_v1((v_cap->>'actor_user_id')::uuid) is distinct from true then return null; end if;
  return v_cap;
end;
$function$;

create or replace function public.timesheet_correction_cancel_atomic_v1(
  p_environment text,p_request_id uuid,p_expected_state_revision bigint,p_actor_user_id uuid,p_now_utc timestamptz default now()
) returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare
  v_environment text:=private._candidate_assert_environment(p_environment); v_request private.timesheet_correction_requests%rowtype;
  v_p public.timesheets%rowtype; v_original_before jsonb; v_original_fin_before jsonb; v_preview jsonb; v_pending jsonb;
  v_signature jsonb; v_signature_text text; v_result jsonb; v_retirement jsonb; v_receipt jsonb;
  v_week_ids uuid[]; v_preserved_ts uuid[]; v_preserved_weeks uuid[]; v_kind text;
  v_component_audit jsonb; v_retained_assets text[];
  v_opened boolean:=false; v_delete_operation uuid:=gen_random_uuid(); v_now timestamptz:=coalesce(p_now_utc,now());
begin
  perform private.timesheet_correction_actor_assert_v1(p_actor_user_id);
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id;
  perform 1 from public.invoices i where i.id in(v_request.original_invoice_id,v_request.return_invoice_id) order by i.id for update;
  perform pg_advisory_xact_lock(hashtextextended('CORRECTION_CHAIN|'||v_request.root_timesheet_id::text,21072026));
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id for update;
  if v_request.state<>'WAITING' then return v_request.terminal_receipt_json||jsonb_build_object('replayed',true); end if;
  if v_request.state_revision is distinct from p_expected_state_revision then
    raise exception 'CORRECTION_REQUEST_CAS_STALE' using errcode='40001';
  end if;
  -- No independent actor can retire a neighbouring workflow/week. Capture
  -- every related workflow first, then refuse anything outside exact P0.
  perform 1 from public.candidate_submission_workflows w where w.target_timesheet_id=v_request.replacement_timesheet_id
    or w.anchor_timesheet_id=v_request.replacement_timesheet_id or w.contract_week_id=v_request.replacement_week_id
    order by w.id for update;
  perform 1 from public.contract_weeks w where w.id=v_request.replacement_week_id for update;
  perform 1 from public.timesheets t where t.timesheet_id in(v_request.reversed_timesheet_id,v_request.replacement_timesheet_id)
    order by t.timesheet_id for update;
  perform 1 from public.timesheets_financials tf where tf.timesheet_id in(v_request.reversed_timesheet_id,v_request.replacement_timesheet_id)
    order by tf.timesheet_id,tf.id for update;
  select t.* into strict v_p from public.timesheets t where t.timesheet_id=v_request.replacement_timesheet_id;
  if exists(select 1 from public.candidate_submission_workflows w
    where (w.target_timesheet_id=v_p.timesheet_id or w.anchor_timesheet_id=v_p.timesheet_id or w.contract_week_id=v_request.replacement_week_id)
      and (w.id is distinct from v_p.candidate_workflow_id or w.generation is distinct from v_p.candidate_workflow_generation)) then
    raise exception 'CORRECTION_CANCEL_WORKFLOW_SCOPE_UNPROVED' using errcode='55000';
  end if;
  if to_regclass('pg_temp.timesheet_correction_cancel_capability_v1') is not null then
    raise exception 'CORRECTION_CANCEL_CONTEXT_CONFLICT' using errcode='55000';
  end if;
  create temp table pg_temp.timesheet_correction_cancel_capability_v1(
    request_id uuid primary key,timesheet_id uuid unique not null,state_revision bigint not null,
    actor_user_id uuid not null,workflow_id uuid,workflow_generation integer,contract_week_id uuid,
    delete_operation_id uuid not null,backend_pid integer not null,transaction_id bigint not null
  ) on commit drop;
  revoke all on pg_temp.timesheet_correction_cancel_capability_v1 from public,anon,authenticated,service_role;
  insert into pg_temp.timesheet_correction_cancel_capability_v1 values(v_request.id,v_p.timesheet_id,v_request.state_revision,
    p_actor_user_id,v_p.candidate_workflow_id,v_p.candidate_workflow_generation,v_request.replacement_week_id,
    v_delete_operation,pg_backend_pid(),txid_current());
  v_opened:=true;
  if private.timesheet_correction_cancel_capability_v1(v_p.timesheet_id,p_actor_user_id) is null then
    raise exception 'CORRECTION_CANCEL_P0_AUTHORITY_INVALID' using errcode='55000';
  end if;
  select to_jsonb(t) into v_original_before from public.timesheets t where t.timesheet_id=v_request.reversed_timesheet_id;
  select coalesce(jsonb_agg(to_jsonb(tf) order by tf.id),'[]'::jsonb) into v_original_fin_before
    from public.timesheets_financials tf where tf.timesheet_id=v_request.reversed_timesheet_id;
  -- Native deletion inventories TS signature keys for cleanup. Preserve the
  -- exact immutable P0 audit assets before retirement clears live TS links.
  perform 1 from public.candidate_submission_components c where c.workflow_id=v_p.candidate_workflow_id
    and c.workflow_generation=v_p.candidate_workflow_generation and c.state='IMMUTABLE' order by c.id for update;
  select coalesce(jsonb_agg(to_jsonb(c)-'timesheet_id' order by c.id),'[]'::jsonb) into v_component_audit
    from public.candidate_submission_components c where c.workflow_id=v_p.candidate_workflow_id
      and c.workflow_generation=v_p.candidate_workflow_generation and c.state='IMMUTABLE';
  select coalesce(array_agg(distinct asset_key order by asset_key),array[]::text[]) into v_retained_assets
    from public.candidate_submission_components c cross join lateral unnest(array[
      c.storage_key,c.review_storage_key,c.final_signed_storage_key,c.paper_return_page_key]) asset(asset_key)
    where c.workflow_id=v_p.candidate_workflow_id and c.workflow_generation=v_p.candidate_workflow_generation
      and c.state='IMMUTABLE' and nullif(btrim(asset_key),'') is not null;
  v_week_ids:=case when v_request.replacement_week_id is null then array[]::uuid[] else array[v_request.replacement_week_id] end;
  v_signature:=public.timesheet_lifecycle_guard_signature_v1(v_p.timesheet_id,v_request.replacement_week_id,false);
  v_signature_text:=coalesce(v_signature->>'backend_row_signature',v_signature->>'row_signature');
  v_kind:=case when v_p.sheet_scope::text='WEEKLY' then 'WEEKLY_MANUAL_ADJUSTMENT_DELETE' else 'STANDARD_DELETE' end;
  v_preview:=case when v_kind='WEEKLY_MANUAL_ADJUSTMENT_DELETE'
    then public.timesheet_weekly_manual_adjustment_delete_preview(v_p.timesheet_id,p_actor_user_id)
    else public.timesheet_standard_delete_preview_v1(v_p.timesheet_id,p_actor_user_id,v_p.timesheet_id,v_signature_text) end;
  if v_preview->'timesheet_ids' is distinct from jsonb_build_array(v_p.timesheet_id)
    or v_preview->'contract_week_ids' is distinct from to_jsonb(v_week_ids)
    or v_preview->>'decision' not in('PERMANENT_DELETE','ARCHIVE_REQUIRED') then
    raise exception 'CORRECTION_CANCEL_LAWFUL_REMOVAL_UNPROVED' using errcode='55000',detail=v_preview::text;
  end if;
  select coalesce(array_agg(id::uuid order by id),array[]::uuid[]) into v_preserved_ts
    from jsonb_array_elements_text(coalesce(v_preview->'preserved_source_timesheet_ids','[]'::jsonb)) item(id);
  select coalesce(array_agg(id::uuid order by id),array[]::uuid[]) into v_preserved_weeks
    from jsonb_array_elements_text(coalesce(v_preview->'preserved_source_contract_week_ids','[]'::jsonb)) item(id);
  v_pending:=private._timesheet_pending_expense_delete_context_v1(v_environment,array[v_p.timesheet_id],true);
  if coalesce((v_pending->>'cancellation_required')::boolean,false)
    or coalesce((v_pending->>'delete_blocked')::boolean,false) then
    raise exception 'CORRECTION_CANCEL_EXTERNAL_EXPENSE_SCOPE_UNPROVED' using errcode='55000',detail=v_pending::text;
  end if;
  if v_preview->>'decision'='ARCHIVE_REQUIRED' then
    v_retirement:=private._candidate_timesheet_delete_retire_workflows_v1(v_environment,array[v_p.timesheet_id],v_week_ids,
      array[]::uuid[],p_actor_user_id,v_delete_operation,v_now);
    v_signature:=public.timesheet_lifecycle_guard_signature_v1(v_p.timesheet_id,v_request.replacement_week_id,false);
    v_result:=public.timesheet_archive_transition_v1(v_p.timesheet_id,'ARCHIVE',v_kind,p_actor_user_id,v_p.timesheet_id,
      coalesce(v_signature->>'backend_row_signature',v_signature->>'row_signature'),v_now);
  else
    v_result:=public.timesheet_delete_with_candidate_submission_guard_apply_v1(v_environment,v_kind,v_p.timesheet_id,p_actor_user_id,
      v_p.timesheet_id,v_signature_text,array[v_p.timesheet_id],v_week_ids,array[]::uuid[],v_preserved_ts,v_preserved_weeks,
      v_pending->>'context_sha256',v_delete_operation,v_now);
  end if;
  if jsonb_typeof(v_result->'r2_cleanup_keys')='array' then
    v_result:=jsonb_set(v_result,'{r2_cleanup_keys}',coalesce((select jsonb_agg(key.value order by key.value)
      from jsonb_array_elements_text(v_result->'r2_cleanup_keys') key(value)
      where not (key.value=any(v_retained_assets))),'[]'::jsonb),true);
    if v_result?'r2_cleanup_required' then
      v_result:=jsonb_set(v_result,'{r2_cleanup_required}',to_jsonb(jsonb_array_length(v_result->'r2_cleanup_keys')>0),true);
    end if;
  end if;
  if v_result->>'ok'='false' or v_result->>'success'='false'
    or exists(select 1 from public.timesheets t where t.timesheet_id=v_p.timesheet_id and t.archived_at_utc is null)
    or exists(select 1 from public.timesheets t where t.booking_id=v_request.replacement_booking_id
      and t.timesheet_id<>v_request.replacement_timesheet_id and t.is_current and t.archived_at_utc is null)
    or (v_preview->>'decision'='PERMANENT_DELETE' and exists(select 1 from public.contract_weeks w where w.id=v_request.replacement_week_id))
    or (v_preview->>'decision'='ARCHIVE_REQUIRED' and v_request.replacement_week_id is not null
      and not exists(select 1 from public.contract_weeks w join public.timesheets t on t.timesheet_id=w.timesheet_id
        where w.id=v_request.replacement_week_id and w.timesheet_id=v_request.replacement_timesheet_id and t.archived_at_utc is not null))
    or exists(select 1 from public.candidate_submission_workflows w where w.id=v_p.candidate_workflow_id
      and (w.target_timesheet_id is not null or w.anchor_timesheet_id is not null or w.contract_week_id is not null or w.state<>'CANCELLED'))
    or exists(select 1 from public.candidate_approval_requests a where a.workflow_id=v_p.candidate_workflow_id and a.state='PENDING')
    or (select coalesce(jsonb_agg(to_jsonb(c)-'timesheet_id' order by c.id),'[]'::jsonb)
      from public.candidate_submission_components c where c.workflow_id=v_p.candidate_workflow_id
        and c.workflow_generation=v_p.candidate_workflow_generation and c.state='IMMUTABLE') is distinct from v_component_audit
    or (select to_jsonb(t) from public.timesheets t where t.timesheet_id=v_request.reversed_timesheet_id) is distinct from v_original_before
    or (select coalesce(jsonb_agg(to_jsonb(tf) order by tf.id),'[]'::jsonb) from public.timesheets_financials tf
      where tf.timesheet_id=v_request.reversed_timesheet_id) is distinct from v_original_fin_before then
    raise exception 'CORRECTION_CANCEL_COMPLETE_UNIT_FAILED' using errcode='55000',detail=v_result::text;
  end if;
  v_receipt:=jsonb_build_object('ok',true,'state','CANCELLED','request_id',v_request.id,'state_revision',v_request.state_revision+1,
    'replacement_timesheet_id',v_p.timesheet_id,'delete_operation_id',v_delete_operation,'lawful_removal',v_result,
    'retained_immutable_component_asset_count',cardinality(v_retained_assets));
  update private.timesheet_correction_requests request set state='CANCELLED',state_revision=state_revision+1,
    cancelled_at_utc=v_now,updated_at_utc=v_now,terminal_receipt_json=v_receipt where request.id=v_request.id;
  drop table pg_temp.timesheet_correction_cancel_capability_v1;
  v_opened:=false;
  return v_receipt;
exception when others then
  if v_opened then drop table if exists pg_temp.timesheet_correction_cancel_capability_v1; end if;
  raise;
end;
$function$;

create or replace function private._timesheet_candidate_submission_delete_guard_v1(
  p_environment text,
  p_timesheet_ids uuid[],
  p_lock_workflows boolean default false
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_environment text:=private._candidate_assert_environment(p_environment);
  v_timesheet_ids uuid[];
  v_timesheet_id uuid;
  v_target_context jsonb;
  v_target jsonb;
  v_guard_items jsonb:='[]'::jsonb;
  v_all_workflow_ids uuid[]:=array[]::uuid[];
  v_linked_pending_expense_workflow_ids uuid[]:=array[]::uuid[];
  v_stage text;
  v_linked_pending_expense_count integer:=0;
begin
  select coalesce(array_agg(distinct supplied_id order by supplied_id),array[]::uuid[])
  into v_timesheet_ids
  from unnest(coalesce(p_timesheet_ids,array[]::uuid[])) supplied(supplied_id)
  where supplied_id is not null;

  if cardinality(v_timesheet_ids)<1 or cardinality(v_timesheet_ids)>64 then
    raise exception 'CANDIDATE_SUBMISSION_DELETE_TARGET_SET_INVALID' using errcode='22023';
  end if;

  foreach v_timesheet_id in array v_timesheet_ids loop
    v_target_context:=private._candidate_office_rejection_targets_v2(
      v_environment,v_timesheet_id
    );
    for v_target in
      select value from jsonb_array_elements(coalesce(
        v_target_context->'target_workflows','[]'::jsonb
      )) target(value)
    loop
      if not ((v_target->>'workflow_id')::uuid=any(v_all_workflow_ids)) then
        v_all_workflow_ids:=array_append(
          v_all_workflow_ids,(v_target->>'workflow_id')::uuid
        );
      end if;
      if coalesce((v_target->>'delete_guard_applicable')::boolean,false)
         and coalesce((v_target->>'linked_pending_expense')::boolean,false)
         and not ((v_target->>'workflow_id')::uuid
           =any(v_linked_pending_expense_workflow_ids)) then
        v_linked_pending_expense_workflow_ids:=array_append(
          v_linked_pending_expense_workflow_ids,(v_target->>'workflow_id')::uuid
        );
      end if;
      if coalesce((v_target->>'delete_guard_applicable')::boolean,false)
         and not (private.timesheet_correction_cancel_capability_v1(v_timesheet_id,null) is not null
           and v_target->>'workflow_id'=private.timesheet_correction_cancel_capability_v1(v_timesheet_id,null)->>'workflow_id')
         and v_target->>'candidate_submission_stage'<>'DRAFT'
         and not exists(
           select 1 from jsonb_array_elements(v_guard_items) existing(item)
           where existing.item->>'workflow_id'=v_target->>'workflow_id'
         ) then
        v_guard_items:=v_guard_items||jsonb_build_array(
          v_target||jsonb_build_object('rejection_timesheet_id',v_timesheet_id)
        );
      end if;
    end loop;
  end loop;

  if p_lock_workflows and cardinality(v_all_workflow_ids)>0 then
    perform 1
    from public.candidate_submission_workflows workflow_row
    where workflow_row.id=any(v_all_workflow_ids)
    order by workflow_row.id
    for update;
    return private._timesheet_candidate_submission_delete_guard_v1(
      v_environment,v_timesheet_ids,false
    );
  end if;

  v_stage:=case
    when exists(
      select 1 from jsonb_array_elements(v_guard_items) item
      where item->>'candidate_submission_stage'='MANAGER_APPROVED'
    ) then 'MANAGER_APPROVED'
    when jsonb_array_length(v_guard_items)>0 then 'CANDIDATE_SUBMITTED'
    else null
  end;
  v_linked_pending_expense_count:=cardinality(
    v_linked_pending_expense_workflow_ids
  );

  return jsonb_build_object(
    'ok',true,
    'contract_version','TIMESHEET_CANDIDATE_SUBMISSION_DELETE_GUARD_V1',
    'environment',v_environment,
    'timesheet_ids',to_jsonb(v_timesheet_ids),
    'candidate_submission_rejection_required',jsonb_array_length(v_guard_items)>0,
    'candidate_submission_stage',v_stage,
    'guarded_workflow_count',jsonb_array_length(v_guard_items),
    'guarded_workflows',v_guard_items,
    'related_workflow_ids',to_jsonb(v_all_workflow_ids),
    'linked_pending_expense_claim_count',v_linked_pending_expense_count
  );
end;
$function$;

create or replace function private._candidate_timesheet_delete_retire_workflows_v1(
  p_environment text,
  p_timesheet_ids uuid[],
  p_contract_week_ids uuid[],
  p_excluded_workflow_ids uuid[],
  p_actor_user_id uuid,
  p_delete_operation_id uuid,
  p_now_utc timestamptz default now()
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_environment text:=private._candidate_assert_environment(p_environment);
  v_timesheet_ids uuid[];
  v_contract_week_ids uuid[];
  v_excluded_workflow_ids uuid[];
  v_workflow public.candidate_submission_workflows%rowtype;
  v_expense_component public.candidate_expense_components%rowtype;
  v_expense_before jsonb;
  v_retired_workflow_ids uuid[]:=array[]::uuid[];
  v_previous_state text;
  v_correction_cap jsonb;
begin
  select coalesce(array_agg(distinct supplied_id order by supplied_id),array[]::uuid[])
  into v_timesheet_ids
  from unnest(coalesce(p_timesheet_ids,array[]::uuid[])) supplied(supplied_id)
  where supplied_id is not null;
  select coalesce(array_agg(distinct supplied_id order by supplied_id),array[]::uuid[])
  into v_contract_week_ids
  from unnest(coalesce(p_contract_week_ids,array[]::uuid[])) supplied(supplied_id)
  where supplied_id is not null;
  select coalesce(array_agg(distinct supplied_id order by supplied_id),array[]::uuid[])
  into v_excluded_workflow_ids
  from unnest(coalesce(p_excluded_workflow_ids,array[]::uuid[])) supplied(supplied_id)
  where supplied_id is not null;

  if p_actor_user_id is null or p_delete_operation_id is null
     or cardinality(v_timesheet_ids)<1 or cardinality(v_timesheet_ids)>64
     or cardinality(v_contract_week_ids)>64
     or cardinality(v_excluded_workflow_ids)>20 then
    raise exception 'CANDIDATE_TIMESHEET_DELETE_RETIREMENT_INVALID'
      using errcode='22023';
  end if;

  for v_workflow in
    select workflow_row.*
    from public.candidate_submission_workflows workflow_row
    where workflow_row.environment=v_environment
      and workflow_row.workflow_kind in (
        'CONTRACT_HOURS','CONTRACT_EXPENSE','CONTRACT_COMBINED','DAILY'
      )
      and (workflow_row.workflow_kind<>'DAILY' or exists(select 1 from unnest(v_timesheet_ids) id
        where private.timesheet_correction_cancel_capability_v1(id,p_actor_user_id)->>'workflow_id'=workflow_row.id::text))
      and not (workflow_row.id=any(v_excluded_workflow_ids))
      and (
        workflow_row.target_timesheet_id=any(v_timesheet_ids)
        or workflow_row.anchor_timesheet_id=any(v_timesheet_ids)
        or workflow_row.contract_week_id=any(v_contract_week_ids)
      )
    order by workflow_row.id
    for update
  loop
    v_correction_cap:=null;
    select private.timesheet_correction_cancel_capability_v1(id,p_actor_user_id) into v_correction_cap
      from unnest(v_timesheet_ids) id where private.timesheet_correction_cancel_capability_v1(id,p_actor_user_id)->>'workflow_id'=v_workflow.id::text;
    if v_correction_cap is not null and (cardinality(v_timesheet_ids)<>1
      or v_correction_cap->>'delete_operation_id' is distinct from p_delete_operation_id::text
      or v_correction_cap->>'workflow_generation' is distinct from v_workflow.generation::text
      or to_jsonb(v_contract_week_ids) is distinct from case when v_correction_cap->>'contract_week_id' is null
        then '[]'::jsonb else jsonb_build_array((v_correction_cap->>'contract_week_id')::uuid) end) then
      raise exception 'CORRECTION_CANCEL_RETIREMENT_SCOPE_CHANGED' using errcode='40001';
    end if;
    if v_correction_cap is null and v_workflow.state not in (
      'CREATED','WORKER_DRAFT','REFUSED','REJECTED','CANCELLED','EXPIRED','SUPERSEDED'
    ) then
      raise exception 'CANDIDATE_SUBMISSION_REJECTION_REQUIRED'
        using errcode='55000',detail=jsonb_build_object(
          'workflow_id',v_workflow.id,
          'workflow_state',v_workflow.state
        )::text;
    end if;
    v_previous_state:=v_workflow.state;

    update public.candidate_approval_requests approval
    set state='CANCELLED',
        cancelled_at_utc=coalesce(approval.cancelled_at_utc,p_now_utc),
        updated_at_utc=p_now_utc
    where approval.workflow_id=v_workflow.id
      and approval.state='PENDING';

    -- The stable category ledger must be retired before the owning Timesheet
    -- FK is released.  Otherwise a draft component can survive the generic
    -- Office delete with no owner and still project a Candidate Remove action.
    -- Only components proved to belong to this deletion unit (or an unowned
    -- component on the exact deleted workflow anchor) are affected.
    for v_expense_component in
      select component.*
      from public.candidate_expense_components component
      where component.workflow_id=v_workflow.id
        and component.lifecycle_state not in (
          'MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED'
        )
        and (
          component.owning_timesheet_id=any(v_timesheet_ids)
          or (
            component.owning_timesheet_id is null
            and (
              v_workflow.target_timesheet_id=any(v_timesheet_ids)
              or v_workflow.anchor_timesheet_id=any(v_timesheet_ids)
            )
          )
        )
      order by component.expense_component_id
      for update
    loop
      v_expense_before:=to_jsonb(v_expense_component);
      update public.candidate_expense_components component set
        component_generation=component.component_generation+1,
        owning_timesheet_id=null,
        lifecycle_state='CANCELLED',
        manager_approval_state=case
          when component.manager_approval_state in ('APPROVED','REFUSED')
            then component.manager_approval_state
          else 'NOT_REQUESTED' end,
        approval_request_id=case
          when component.manager_approval_state in ('APPROVED','REFUSED')
            then component.approval_request_id
          else null end,
        removed_at_utc=coalesce(component.removed_at_utc,p_now_utc),
        updated_at_utc=p_now_utc
      where component.expense_component_id=v_expense_component.expense_component_id
      returning component.* into v_expense_component;
      insert into public.candidate_expense_component_events(
        expense_component_id,workflow_id,component_generation,event_type,
        actor_kind,actor_id,before_state_json,after_state_json,idempotency_key,
        occurred_at_utc
      ) values (
        v_expense_component.expense_component_id,v_workflow.id,
        v_expense_component.component_generation,'CANCELLED','OFFICE',
        p_actor_user_id,v_expense_before,to_jsonb(v_expense_component),
        'office-timesheet-delete:'||p_delete_operation_id::text||':'
          ||v_expense_component.expense_component_id::text,p_now_utc
      ) on conflict(expense_component_id,idempotency_key) do nothing;
    end loop;

    update public.candidate_submission_components component
    set timesheet_id=null,
        state=case
          when v_previous_state in ('CREATED','WORKER_DRAFT')
            and component.state not in ('SUPERSEDED','REJECTED','ABANDONED')
            then 'ABANDONED'
          else component.state
        end,
        superseded_at_utc=case
          when v_previous_state in ('CREATED','WORKER_DRAFT')
            then coalesce(component.superseded_at_utc,p_now_utc)
          else component.superseded_at_utc
        end
    where component.workflow_id=v_workflow.id
      and component.timesheet_id=any(v_timesheet_ids);

    update public.candidate_notifications notification
    set timesheet_id=null,
        deep_link_json=(coalesce(notification.deep_link_json,'{}'::jsonb)
          -'timesheet_id'-'contract_week_id')||jsonb_build_object(
            'type','workflow','workflow_id',v_workflow.id
          ),
        state='DISMISSED',
        dismissed_at_utc=coalesce(notification.dismissed_at_utc,p_now_utc),
        push_state=case
          when notification.push_state in ('PENDING','FAILED','CLAIMED') then 'SKIPPED'
          else notification.push_state end
    where notification.workflow_id=v_workflow.id;

    update public.candidate_submission_workflows workflow_row
    set state=case
          when v_correction_cap is not null or workflow_row.state in ('CREATED','WORKER_DRAFT')
            then 'CANCELLED'
          else workflow_row.state
        end,
        contract_week_id=null,
        anchor_timesheet_id=null,
        target_timesheet_id=null,
        cancelled_at_utc=case
          when v_correction_cap is not null or workflow_row.state in ('CREATED','WORKER_DRAFT')
            then coalesce(workflow_row.cancelled_at_utc,p_now_utc)
          else workflow_row.cancelled_at_utc
        end,
        input_snapshot_json=coalesce(workflow_row.input_snapshot_json,'{}'::jsonb)
          ||jsonb_build_object(
            'office_permanent_delete_tombstone',jsonb_build_object(
              'delete_operation_id',p_delete_operation_id,
              'deleted_timesheet_ids',to_jsonb(v_timesheet_ids),
              'deleted_contract_week_ids',to_jsonb(v_contract_week_ids),
              'previous_contract_week_id',v_workflow.contract_week_id,
              'previous_anchor_timesheet_id',v_workflow.anchor_timesheet_id,
              'previous_target_timesheet_id',v_workflow.target_timesheet_id,
              'retired_at_utc',p_now_utc
            )
          ),
        issue_codes=case
          when workflow_row.issue_codes
            @> '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
            then workflow_row.issue_codes
          else workflow_row.issue_codes
            ||'["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
        end,
        updated_at_utc=p_now_utc
    where workflow_row.id=v_workflow.id;

    insert into public.audit_events(
      actor_user_id,object_type,object_id_text,action,before_json,after_json,
      reason,correlation_id,ts_utc
    ) values (
      p_actor_user_id,'candidate_submission_workflows',v_workflow.id::text,
      'CANDIDATE_WORKFLOW_RETAINED_AFTER_TIMESHEET_DELETE',
      jsonb_build_object(
        'state',v_previous_state,
        'contract_week_id',v_workflow.contract_week_id,
        'anchor_timesheet_id',v_workflow.anchor_timesheet_id,
        'target_timesheet_id',v_workflow.target_timesheet_id
      ),
      jsonb_build_object(
        'state',case when v_correction_cap is not null or v_previous_state in ('CREATED','WORKER_DRAFT')
          then 'CANCELLED' else v_previous_state end,
        'live_timesheet_links_released',true,
        'terminal_audit_retained',true
      ),
      'OFFICE_PERMANENTLY_DELETED_TIMESHEET',p_delete_operation_id,p_now_utc
    );
    v_retired_workflow_ids:=array_append(
      v_retired_workflow_ids,v_workflow.id
    );
  end loop;

  return jsonb_build_object(
    'ok',true,
    'contract_version','CANDIDATE_TIMESHEET_DELETE_WORKFLOW_RETIREMENT_V1',
    'retired_workflow_count',cardinality(v_retired_workflow_ids),
    'retired_workflow_ids',to_jsonb(v_retired_workflow_ids)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.timesheet_weekly_manual_adjustment_delete_preview(p_timesheet_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_in_ts public.timesheets%rowtype;
  v_current_ts public.timesheets%rowtype;

  v_booking_id text := null;

  v_timesheet_ids uuid[] := array[]::uuid[];
  v_contract_week_ids uuid[] := array[]::uuid[];
  v_contract_week_id uuid := null;
  v_preserved_source_contract_week_ids uuid[] := array[]::uuid[];
  v_preserved_source_timesheet_ids uuid[] := array[]::uuid[];
  v_effective_manual_adjustment boolean := false;
  v_linked_adjustment_contract_week_exists boolean := false;
  v_has_base_contract_week_target boolean := false;

  v_blocked jsonb := '[]'::jsonb;

  v_history jsonb := '{}'::jsonb;
  v_decision text := 'BLOCKED';

  v_delete_items jsonb := '[]'::jsonb;
begin
  if p_timesheet_id is null then
    raise exception 'timesheet_weekly_manual_adjustment_delete_preview: timesheet_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception using message = 'ACTOR_USER_ID_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.tms_users as actor
    where actor.id = p_actor_user_id
      and actor.is_active = true
  ) then
    raise exception using message = 'ACTOR_NOT_FOUND_OR_INACTIVE';
  end if;

  select input_timesheet.*
  into v_in_ts
  from public.timesheets as input_timesheet
  where input_timesheet.timesheet_id = p_timesheet_id;

  if not found then
    raise exception 'timesheet_weekly_manual_adjustment_delete_preview: timesheet % not found', p_timesheet_id;
  end if;

  v_booking_id := v_in_ts.booking_id;

  select current_timesheet.*
  into v_current_ts
  from public.timesheets as current_timesheet
  where current_timesheet.booking_id = v_booking_id
  order by current_timesheet.is_current desc, current_timesheet.version desc, current_timesheet.updated_at desc nulls last, current_timesheet.created_at desc nulls last, current_timesheet.timesheet_id desc
  limit 1;

  if not found then
    raise exception 'timesheet_weekly_manual_adjustment_delete_preview: booking_id % not found', v_booking_id;
  end if;

  select coalesce(array_agg(all_versions.timesheet_id order by all_versions.version asc nulls last, all_versions.created_at asc nulls last, all_versions.timesheet_id asc), array[]::uuid[])
  into v_timesheet_ids
  from public.timesheets as all_versions
  where all_versions.booking_id = v_current_ts.booking_id;

  select
    coalesce(bool_or(coalesce(linked_contract_week.is_adjustment, false) = true or coalesce(linked_contract_week.additional_seq, 0) > 0), false),
    coalesce(bool_or(coalesce(linked_contract_week.is_adjustment, false) = false or coalesce(linked_contract_week.additional_seq, 0) <= 0), false)
  into v_linked_adjustment_contract_week_exists,
       v_has_base_contract_week_target
  from public.contract_weeks as linked_contract_week
  where linked_contract_week.timesheet_id = any(v_timesheet_ids);

  select coalesce(array_agg(distinct adjustment_contract_week.id order by adjustment_contract_week.id), array[]::uuid[])
  into v_contract_week_ids
  from public.contract_weeks as adjustment_contract_week
  where adjustment_contract_week.timesheet_id = any(v_timesheet_ids)
    and coalesce(adjustment_contract_week.is_adjustment, false) = true
    and coalesce(adjustment_contract_week.additional_seq, 0) > 0;

  v_effective_manual_adjustment :=
    coalesce(v_current_ts.is_adjustment, false) = true
    or coalesce(v_linked_adjustment_contract_week_exists, false) = true
    or v_current_ts.parent_timesheet_id is not null
    or v_current_ts.correction_id is not null
    or nullif(btrim(coalesce(v_current_ts.correction_kind, '')), '') is not null
    or upper(coalesce(v_current_ts.adjustment_origin, '')) in ('MANUAL_ADJUSTMENT', 'IMPORT_CORRECTION', 'IMPORT_CANCELLATION');

  if coalesce(array_length(v_contract_week_ids, 1), 0) > 0 then
    v_contract_week_id := v_contract_week_ids[1];
  end if;

  select coalesce(array_agg(distinct source_contract_week.id order by source_contract_week.id), array[]::uuid[])
  into v_preserved_source_contract_week_ids
  from public.contract_weeks as adjustment_contract_week_for_source
  join public.contract_weeks as source_contract_week
    on source_contract_week.contract_id = adjustment_contract_week_for_source.contract_id
   and source_contract_week.week_ending_date = adjustment_contract_week_for_source.week_ending_date
   and coalesce(source_contract_week.additional_seq, 0) = 0
   and coalesce(source_contract_week.is_adjustment, false) = false
  where adjustment_contract_week_for_source.id = any(v_contract_week_ids);

  select coalesce(array_agg(distinct preserved_timesheet_id order by preserved_timesheet_id), array[]::uuid[])
  into v_preserved_source_timesheet_ids
  from (
    select source_contract_week_for_ts.timesheet_id as preserved_timesheet_id
    from public.contract_weeks as source_contract_week_for_ts
    where source_contract_week_for_ts.id = any(v_preserved_source_contract_week_ids)
      and source_contract_week_for_ts.timesheet_id is not null
    union
    select v_current_ts.parent_timesheet_id as preserved_timesheet_id
    where v_current_ts.parent_timesheet_id is not null
  ) as preserved_source_timesheet_ids
  where preserved_source_timesheet_ids.preserved_timesheet_id is not null;

  if v_current_ts.sheet_scope <> 'WEEKLY'::public.timesheet_scope_enum then
    v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
      'code','NOT_WEEKLY',
      'message','Manual adjustment delete applies only to WEEKLY adjustment timesheets.',
      'timesheet_id', v_current_ts.timesheet_id::text
    ));
  end if;

  if coalesce(v_effective_manual_adjustment, false) is not true then
    v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
      'code','NOT_ADJUSTMENT',
      'message','Timesheet is not an adjustment/additional manual row; this preview is only for WEEKLY manual adjustment deletes.',
      'timesheet_id', v_current_ts.timesheet_id::text,
      'contract_week_ids', to_jsonb(coalesce(v_contract_week_ids, array[]::uuid[]))
    ));
  end if;

  if private.timesheet_correction_cancel_capability_v1(v_current_ts.timesheet_id,p_actor_user_id) is null and (
    upper(coalesce(v_current_ts.adjustment_origin,'')) in ('IMPORT_CORRECTION','IMPORT_CANCELLATION')
    or nullif(btrim(coalesce(v_current_ts.correction_kind,'')),'') is not null
    or v_current_ts.correction_id is not null
  ) then
    v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
      'code','IMPORT_DERIVED_CHILD',
      'message','Import-derived adjustments cannot be deleted directly; they must be deleted via the WEEKLY parent-chain delete.',
      'timesheet_id', v_current_ts.timesheet_id::text,
      'adjustment_origin', v_current_ts.adjustment_origin,
      'correction_id', v_current_ts.correction_id,
      'correction_kind', v_current_ts.correction_kind
    ));
  end if;

  if coalesce(array_length(v_contract_week_ids,1),0) = 0 then
    v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
      'code','MISSING_CONTRACT_WEEK',
      'message','No linked additional/manual adjustment contract_week found for this weekly manual adjustment; refusing delete to avoid orphan/corruption.',
      'timesheet_id', v_current_ts.timesheet_id::text
    ));
  end if;

  if coalesce(v_has_base_contract_week_target, false) = true then
    v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
      'code','BASE_CONTRACT_WEEK_TARGETED',
      'message','Delete preview resolved a base/source contract_week for a manual adjustment delete; refusing delete to protect the parent/source row.',
      'contract_week_ids', to_jsonb(coalesce(v_contract_week_ids, array[]::uuid[])),
      'preserved_source_contract_week_ids', to_jsonb(coalesce(v_preserved_source_contract_week_ids, array[]::uuid[]))
    ));
  end if;

  v_history := public.timesheet_removal_financial_history_v1(
    v_timesheet_ids,
    ARRAY[v_current_ts.booking_id],
    v_contract_week_ids
  );

  v_blocked := v_blocked || COALESCE(v_history -> 'blockers', '[]'::jsonb);

  IF jsonb_array_length(v_blocked) > 0 THEN
    v_decision := 'BLOCKED';
  ELSIF COALESCE((v_history ->> 'archive_required')::boolean, false) THEN
    v_decision := 'ARCHIVE_REQUIRED';
  ELSE
    v_decision := 'PERMANENT_DELETE';
  END IF;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'timesheet_id', v_current_ts.timesheet_id::text,
        'booking_id', v_current_ts.booking_id,
        'week_ending_date', v_current_ts.week_ending_date::text,
        'status', v_current_ts.status::text,
        'is_adjustment', coalesce(v_effective_manual_adjustment, false),
        'adjustment_origin', v_current_ts.adjustment_origin,
        'correction_id', v_current_ts.correction_id,
        'correction_kind', v_current_ts.correction_kind,
        'display_role', 'MANUAL_ADJUSTMENT',
        'total_hours', coalesce(selected_tsfin.total_hours, 0),
        'total_pay_ex_vat', coalesce(selected_tsfin.total_pay_ex_vat, 0),
        'total_charge_ex_vat', coalesce(selected_tsfin.total_charge_ex_vat, 0)
      )
      order by selected_tsfin.id
    ),
    '[]'::jsonb
  )
  into v_delete_items
  from public.timesheets_financials as selected_tsfin
  where selected_tsfin.timesheet_id = v_current_ts.timesheet_id
    and selected_tsfin.is_current is true;

  if jsonb_array_length(v_delete_items) = 0 then
    v_delete_items := jsonb_build_array(jsonb_build_object(
      'timesheet_id', v_current_ts.timesheet_id::text,
      'booking_id', v_current_ts.booking_id,
      'week_ending_date', v_current_ts.week_ending_date::text,
      'status', v_current_ts.status::text,
      'is_adjustment', coalesce(v_effective_manual_adjustment, false),
      'adjustment_origin', v_current_ts.adjustment_origin,
      'correction_id', v_current_ts.correction_id,
      'correction_kind', v_current_ts.correction_kind,
      'display_role', 'MANUAL_ADJUSTMENT',
      'total_hours', 0,
      'total_pay_ex_vat', 0,
      'total_charge_ex_vat', 0
    ));
  end if;

  return jsonb_build_object(
    'kind', 'WEEKLY_MANUAL_ADJUSTMENT_DELETE',
    'requested_timesheet_id', p_timesheet_id::text,
    'current_timesheet_id', v_current_ts.timesheet_id::text,
    'booking_id', v_current_ts.booking_id,
    'contract_week_id', case when v_contract_week_id is null then null else v_contract_week_id::text end,
    'contract_week_ids', to_jsonb(coalesce(v_contract_week_ids, array[]::uuid[])),
    'timesheet_ids', to_jsonb(coalesce(v_timesheet_ids, array[]::uuid[])),
    'preserved_source_timesheet_ids', to_jsonb(coalesce(v_preserved_source_timesheet_ids, array[]::uuid[])),
    'preserved_source_contract_week_ids', to_jsonb(coalesce(v_preserved_source_contract_week_ids, array[]::uuid[])),
    'delete_items', v_delete_items,
    'decision', v_decision,
    'eligible', (v_decision = 'PERMANENT_DELETE'),
    'blocked_reasons', v_blocked,
    'blockers', v_blocked,
    'retention_reasons', COALESCE(v_history -> 'retention_reasons', '[]'::jsonb),
    'advance', COALESCE(v_history -> 'advance', '{}'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.timesheet_standard_delete_preview_v1(p_timesheet_id uuid, p_actor_user_id uuid, p_expected_timesheet_id uuid DEFAULT NULL::uuid, p_expected_row_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_requested public.timesheets%ROWTYPE;
  v_current public.timesheets%ROWTYPE;
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_contract_week_ids uuid[] := ARRAY[]::uuid[];
  v_nhsp_shift_ids uuid[] := ARRAY[]::uuid[];
  v_preserved_source_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_preserved_source_contract_week_ids uuid[] := ARRAY[]::uuid[];
  v_primary_contract_week_id uuid := NULL;
  v_history jsonb := '{}'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_decision text := 'BLOCKED';
  v_signature_payload jsonb := '{}'::jsonb;
  v_current_signature text := NULL;
  v_class jsonb := '{}'::jsonb;
  v_chain jsonb := '{}'::jsonb;
  v_unit jsonb := '{}'::jsonb;
  v_is_correction_pair boolean := false;
  v_pair_fingerprint text := NULL;
  v_pair_members jsonb := '[]'::jsonb;
  v_pair_net_hours numeric := 0;
BEGIN
  IF p_timesheet_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_ID_REQUIRED';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'ACTOR_USER_ID_REQUIRED';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.tms_users AS actor
    WHERE actor.id = p_actor_user_id
      AND actor.is_active = true
  ) THEN
    RAISE EXCEPTION USING MESSAGE = 'ACTOR_NOT_FOUND_OR_INACTIVE';
  END IF;

  SELECT t.*
    INTO v_requested
  FROM public.timesheets AS t
  WHERE t.timesheet_id = p_timesheet_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'kind', 'STANDARD_DELETE',
      'decision', 'BLOCKED',
      'eligible', false,
      'blockers', jsonb_build_array(jsonb_build_object('code', 'TARGET_NOT_FOUND')),
      'blocked_reasons', jsonb_build_array(jsonb_build_object('code', 'TARGET_NOT_FOUND')),
      'timesheet_ids', '[]'::jsonb,
      'contract_week_ids', '[]'::jsonb,
      'nhsp_shift_ids', '[]'::jsonb,
      'preserved_source_timesheet_ids', '[]'::jsonb,
      'preserved_source_contract_week_ids', '[]'::jsonb,
      'retention_reasons', '[]'::jsonb,
      'advance', jsonb_build_object(
        'active', false,
        'clearable', false,
        'consumed', false,
        'historical', false
      )
    );
  END IF;

  SELECT t.*
    INTO v_current
  FROM public.timesheets AS t
  WHERE t.booking_id = v_requested.booking_id
    AND t.is_current = true
  ORDER BY t.version DESC NULLS LAST,
           t.updated_at DESC NULLS LAST,
           t.created_at DESC NULLS LAST,
           t.timesheet_id DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'kind', 'STANDARD_DELETE',
      'decision', 'BLOCKED',
      'eligible', false,
      'requested_timesheet_id', p_timesheet_id,
      'blockers', jsonb_build_array(jsonb_build_object('code', 'CURRENT_TIMESHEET_NOT_FOUND')),
      'blocked_reasons', jsonb_build_array(jsonb_build_object('code', 'CURRENT_TIMESHEET_NOT_FOUND')),
      'timesheet_ids', '[]'::jsonb,
      'contract_week_ids', '[]'::jsonb,
      'nhsp_shift_ids', '[]'::jsonb,
      'preserved_source_timesheet_ids', '[]'::jsonb,
      'preserved_source_contract_week_ids', '[]'::jsonb,
      'retention_reasons', '[]'::jsonb,
      'advance', jsonb_build_object(
        'active', false,
        'clearable', false,
        'consumed', false,
        'historical', false
      )
    );
  END IF;

  -- Import-authoritative changed-hours members are one exact two-row removal
  -- unit.  Resolve the requested correction generation, never the wider Weekly
  -- parent chain or a neighbouring generation.
  v_class:=public._ctms_import_correction_classify_v1(v_current.timesheet_id);
  IF COALESCE((v_class->>'is_import_authoritative_correction')::boolean,false) THEN
    v_chain:=public.timesheet_correction_chain_scope_v1(v_current.timesheet_id,false,32,100);
    v_unit:=v_chain->'requested_correction_unit';
    IF COALESCE((v_chain->>'valid')::boolean,false) IS TRUE
       AND COALESCE((v_unit->>'valid')::boolean,false) IS TRUE
       AND v_unit->>'correction_shape'='REVERSAL_REPLACEMENT'
       AND COALESCE((v_unit->>'expected_member_count')::integer,0)=2 THEN
      SELECT COALESCE(array_agg(value::uuid ORDER BY value::uuid),ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM jsonb_array_elements_text(v_unit->'member_ids') member(value);
      v_is_correction_pair:=cardinality(v_timesheet_ids)=2;
      v_pair_fingerprint:=public._import_review_hash_v1(concat_ws('|',
        'correction-pair-removal-v1',v_chain->>'chain_fingerprint',v_unit->>'correction_id',
        array_to_string(v_timesheet_ids,',')));
    ELSE
      -- Archived pairs are intentionally excluded from some active-chain
      -- projections.  Their exact durable correction identity remains enough
      -- to support an atomic Unarchive preview, but never a guessed role.
      SELECT COALESCE(array_agg(t.timesheet_id ORDER BY t.timesheet_id),ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM public.timesheets t
      WHERE t.correction_id=v_current.correction_id AND t.is_current
        AND t.correction_kind IN ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT');
      IF cardinality(v_timesheet_ids)=2
         AND (SELECT count(*) FROM public.timesheets t WHERE t.timesheet_id=ANY(v_timesheet_ids)
                AND t.correction_kind='CHANGED_HOURS_REVERSAL')=1
         AND (SELECT count(*) FROM public.timesheets t WHERE t.timesheet_id=ANY(v_timesheet_ids)
                AND t.correction_kind='CHANGED_HOURS_REPLACEMENT')=1 THEN
        v_is_correction_pair:=true;
        v_unit:=jsonb_build_object('valid',true,'correction_id',v_current.correction_id,
          'correction_shape','REVERSAL_REPLACEMENT','expected_member_count',2,
          'member_ids',to_jsonb(v_timesheet_ids));
        v_pair_fingerprint:=public._import_review_hash_v1(concat_ws('|',
          'correction-pair-removal-v1',v_current.correction_id,array_to_string(v_timesheet_ids,',')));
      ELSE
        v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object(
          'code','CORRECTION_PAIR_MALFORMED','detail',v_chain));
      END IF;
    END IF;
  END IF;
  IF NOT v_is_correction_pair THEN
    -- Ordinary and non-authoritative paths keep the installed single-row unit.
    v_timesheet_ids:=ARRAY[v_current.timesheet_id]::uuid[];
  END IF;

  SELECT COALESCE(array_agg(DISTINCT cw.id ORDER BY cw.id), ARRAY[]::uuid[])
    INTO v_contract_week_ids
  FROM public.contract_weeks AS cw
  WHERE cw.timesheet_id = ANY(v_timesheet_ids);

  SELECT cw.id INTO v_primary_contract_week_id
  FROM public.contract_weeks cw
  WHERE cw.timesheet_id=v_current.timesheet_id
  ORDER BY cw.id LIMIT 1;

  SELECT COALESCE(array_agg(DISTINCT nhsp_shift.id ORDER BY nhsp_shift.id), ARRAY[]::uuid[])
    INTO v_nhsp_shift_ids
  FROM public.nhsp_shifts AS nhsp_shift
  WHERE nhsp_shift.timesheet_id = ANY(v_timesheet_ids);

  SELECT COALESCE(array_agg(DISTINCT source_contract_week.id ORDER BY source_contract_week.id), ARRAY[]::uuid[])
    INTO v_preserved_source_contract_week_ids
  FROM public.contract_weeks AS target_contract_week
  JOIN public.contract_weeks AS source_contract_week
    ON source_contract_week.contract_id = target_contract_week.contract_id
   AND source_contract_week.week_ending_date = target_contract_week.week_ending_date
   AND COALESCE(source_contract_week.additional_seq, 0) = 0
   AND COALESCE(source_contract_week.is_adjustment, false) = false
  WHERE target_contract_week.id = ANY(v_contract_week_ids)
    AND source_contract_week.id <> ALL(v_contract_week_ids);

  SELECT COALESCE(array_agg(DISTINCT preserved_row.preserved_timesheet_id ORDER BY preserved_row.preserved_timesheet_id), ARRAY[]::uuid[])
    INTO v_preserved_source_timesheet_ids
  FROM (
    SELECT source_contract_week.timesheet_id AS preserved_timesheet_id
    FROM public.contract_weeks AS source_contract_week
    WHERE source_contract_week.id = ANY(v_preserved_source_contract_week_ids)
      AND source_contract_week.timesheet_id IS NOT NULL

    UNION

    SELECT target_timesheet.parent_timesheet_id AS preserved_timesheet_id
    FROM public.timesheets AS target_timesheet
    WHERE target_timesheet.timesheet_id = ANY(v_timesheet_ids)
      AND target_timesheet.parent_timesheet_id IS NOT NULL
  ) AS preserved_row
  WHERE preserved_row.preserved_timesheet_id IS NOT NULL
    AND preserved_row.preserved_timesheet_id <> ALL(v_timesheet_ids);

  IF p_expected_timesheet_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'EXPECTED_TIMESHEET_ID_REQUIRED',
      'current_timesheet_id', v_current.timesheet_id,
      'message', 'The current Timesheet identity is required. Refresh before continuing.'
    ));
  ELSIF p_expected_timesheet_id IS DISTINCT FROM v_current.timesheet_id THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'EXPECTED_TIMESHEET_MISMATCH',
      'expected_timesheet_id', p_expected_timesheet_id,
      'current_timesheet_id', v_current.timesheet_id
    ));
  END IF;

  v_signature_payload := public.timesheet_lifecycle_guard_signature_v1(
    v_current.timesheet_id,
    v_primary_contract_week_id,
    false
  );
  v_current_signature := NULLIF(BTRIM(COALESCE(
    v_signature_payload ->> 'backend_row_signature',
    v_signature_payload ->> 'row_signature',
    v_signature_payload ->> 'signature',
    ''
  )), '');

  IF NULLIF(BTRIM(COALESCE(p_expected_row_signature, '')), '') IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'EXPECTED_ROW_SIGNATURE_REQUIRED',
      'current_row_signature', v_current_signature,
      'message', 'The current Timesheet lifecycle signature is required. Refresh before continuing.'
    ));
  ELSIF v_current_signature IS DISTINCT FROM BTRIM(p_expected_row_signature) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'ROW_SIGNATURE_MISMATCH',
      'expected_row_signature', BTRIM(p_expected_row_signature),
      'current_row_signature', v_current_signature
    ));
  END IF;

  IF NOT v_is_correction_pair AND v_current.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum THEN
    IF COALESCE(v_current.is_adjustment, false)
       OR EXISTS (
         SELECT 1
         FROM public.contract_weeks AS cw
         WHERE cw.timesheet_id = v_current.timesheet_id
           AND (COALESCE(cw.is_adjustment, false) OR COALESCE(cw.additional_seq, 0) > 0)
       ) THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'WEEKLY_MANUAL_ADJUSTMENT_PREVIEW_REQUIRED'
      ));
    ELSE
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'WEEKLY_CHAIN_PREVIEW_REQUIRED'
      ));
    END IF;
  END IF;

  IF NOT v_is_correction_pair AND private.timesheet_correction_cancel_capability_v1(v_current.timesheet_id,p_actor_user_id) is null AND (UPPER(COALESCE(v_current.adjustment_origin, '')) IN ('IMPORT_CORRECTION', 'IMPORT_CANCELLATION')
     OR NULLIF(BTRIM(COALESCE(v_current.correction_kind, '')), '') IS NOT NULL
     OR v_current.correction_id IS NOT NULL) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'IMPORT_DERIVED_CHILD',
      'message', 'Import-derived children must be handled through the parent-chain removal path.'
    ));
  END IF;

  IF v_is_correction_pair THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'timesheet_id',t.timesheet_id,'correction_kind',t.correction_kind,
      'signed_hours',COALESCE(tf.hours_day,0)+COALESCE(tf.hours_night,0)+COALESCE(tf.hours_sat,0)+COALESCE(tf.hours_sun,0)+COALESCE(tf.hours_bh,0),
      'authorised',t.authorised_at_server IS NOT NULL OR tf.authorised_at_utc IS NOT NULL,
      'invoice_linked',EXISTS(SELECT 1 FROM public.invoice_lines il WHERE il.timesheet_id=t.timesheet_id),
      'paid',tf.paid_at_utc IS NOT NULL,'archived',t.archived_at_utc IS NOT NULL)
      ORDER BY CASE t.correction_kind WHEN 'CHANGED_HOURS_REVERSAL' THEN 1 ELSE 2 END),'[]'::jsonb),
      COALESCE(sum(COALESCE(tf.hours_day,0)+COALESCE(tf.hours_night,0)+COALESCE(tf.hours_sat,0)+COALESCE(tf.hours_sun,0)+COALESCE(tf.hours_bh,0)),0)
    INTO v_pair_members,v_pair_net_hours
    FROM public.timesheets t
    LEFT JOIN public.timesheets_financials tf ON tf.timesheet_id=t.timesheet_id AND tf.is_current=true
    WHERE t.timesheet_id=ANY(v_timesheet_ids);

    IF (SELECT count(*) FROM public.timesheets t WHERE t.timesheet_id=ANY(v_timesheet_ids)
          AND t.archived_at_utc IS NOT NULL)=1 THEN
      v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','CORRECTION_PAIR_PARTIAL_ARCHIVE'));
    END IF;
    IF EXISTS(SELECT 1 FROM public.timesheets t LEFT JOIN public.timesheets_financials tf
        ON tf.timesheet_id=t.timesheet_id AND tf.is_current=true
      WHERE t.timesheet_id=ANY(v_timesheet_ids)
        AND (t.authorised_at_server IS NOT NULL OR tf.authorised_at_utc IS NOT NULL)) THEN
      v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','CORRECTION_PAIR_MUST_BE_UNAUTHORISED'));
    END IF;
    IF EXISTS(
      SELECT 1 FROM public.timesheets later
      WHERE later.is_current AND later.archived_at_utc IS NULL
        AND later.adjustment_origin='IMPORT_CORRECTION'
        AND later.parent_timesheet_id=(
          SELECT replacement.timesheet_id FROM public.timesheets replacement
          WHERE replacement.timesheet_id=ANY(v_timesheet_ids)
            AND replacement.correction_kind='CHANGED_HOURS_REPLACEMENT' LIMIT 1)
        AND later.timesheet_id<>ALL(v_timesheet_ids)
    ) THEN
      v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','CORRECTION_PAIR_HAS_LATER_GENERATION'));
    END IF;
  END IF;

  v_history := public.timesheet_removal_financial_history_v1(
    v_timesheet_ids,
    ARRAY[v_current.booking_id]::text[],
    v_contract_week_ids
  );

  v_blockers := v_blockers || COALESCE(v_history -> 'blockers', '[]'::jsonb);

  IF jsonb_array_length(v_blockers) > 0 THEN
    v_decision := 'BLOCKED';
  ELSIF COALESCE((v_history ->> 'archive_required')::boolean, false) THEN
    v_decision := 'ARCHIVE_REQUIRED';
  ELSE
    v_decision := 'PERMANENT_DELETE';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'kind', 'STANDARD_DELETE',
    'decision', v_decision,
    'eligible', v_decision = 'PERMANENT_DELETE',
    'requested_timesheet_id', p_timesheet_id,
    'current_timesheet_id', v_current.timesheet_id,
    'was_stale', v_current.timesheet_id IS DISTINCT FROM p_timesheet_id,
    'booking_id', v_current.booking_id,
    'timesheet_ids', to_jsonb(v_timesheet_ids),
    'contract_week_ids', to_jsonb(v_contract_week_ids),
    'nhsp_shift_ids', to_jsonb(v_nhsp_shift_ids),
    'preserved_source_timesheet_ids', to_jsonb(v_preserved_source_timesheet_ids),
    'preserved_source_contract_week_ids', to_jsonb(v_preserved_source_contract_week_ids),
    'blockers', v_blockers,
    'blocked_reasons', v_blockers,
    'retention_reasons', COALESCE(v_history -> 'retention_reasons', '[]'::jsonb),
    'advance', COALESCE(v_history -> 'advance', '{}'::jsonb),
    'current_row_signature', v_current_signature,
    'correction_pair',v_is_correction_pair,
    'source_system',CASE WHEN v_is_correction_pair THEN CASE
      WHEN upper(coalesce(
        v_current.candidate_hint_text#>>'{correction_financials_policy_envelope,classification,source_system}',
        v_current.adjustment_origin,'')) like 'NHSP%' THEN 'NHSP'
      ELSE 'HEALTHROSTER' END END,
    'correction_id',CASE WHEN v_is_correction_pair THEN v_unit->>'correction_id' END,
    'pair_timesheet_ids',CASE WHEN v_is_correction_pair THEN to_jsonb(v_timesheet_ids) ELSE '[]'::jsonb END,
    'pair_fingerprint',v_pair_fingerprint,
    'members',CASE WHEN v_is_correction_pair THEN v_pair_members ELSE '[]'::jsonb END,
    'pair_net_position',CASE WHEN v_is_correction_pair THEN jsonb_build_object('hours',v_pair_net_hours) ELSE NULL END,
    'resulting_financial_position',CASE WHEN v_is_correction_pair THEN jsonb_build_object('pair_removed_hours',v_pair_net_hours) ELSE NULL END
  );
END;
$function$;

create or replace function public.timesheet_delete_with_pending_expense_apply_v1(
  p_environment text,
  p_delete_kind text,
  p_timesheet_id uuid,
  p_actor_user_id uuid,
  p_expected_timesheet_id uuid,
  p_expected_row_signature text,
  p_expected_timesheet_ids uuid[],
  p_expected_contract_week_ids uuid[],
  p_expected_nhsp_shift_ids uuid[],
  p_expected_preserved_source_timesheet_ids uuid[],
  p_expected_preserved_source_contract_week_ids uuid[],
  p_expected_pending_expense_context_sha256 text,
  p_delete_operation_id uuid,
  p_now_utc timestamptz default now()
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_environment text:=private._candidate_assert_environment(p_environment);
  v_kind text:=upper(btrim(coalesce(p_delete_kind,'')));
  v_context jsonb;
  v_claim jsonb;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_cancel_result jsonb;
  v_cancel_results jsonb:='[]'::jsonb;
  v_notification_id uuid;
  v_notification_ids uuid[]:=array[]::uuid[];
  v_settings jsonb;
  v_template jsonb;
  v_terminal_mail jsonb;
  v_apply_result jsonb;
  v_delete_candidate_ids uuid[]:=array[]::uuid[];
  v_delete_candidate_id uuid;
  v_candidate_lock_key bigint;
  v_banking_dirty_result jsonb:='{}'::jsonb;
begin
  if p_actor_user_id is null or p_timesheet_id is null or p_expected_timesheet_id is null
     or p_delete_operation_id is null or nullif(btrim(coalesce(p_expected_row_signature,'')),'') is null
     or coalesce(p_expected_pending_expense_context_sha256,'') !~ '^[0-9a-f]{64}$'
     or v_kind not in (
       'STANDARD_DELETE','DAILY_ABANDONED_RECEIPT_DELETE',
       'WEEKLY_CHAIN_DELETE_PARENT','WEEKLY_MANUAL_ADJUSTMENT_DELETE'
     ) then
    raise exception 'PENDING_EXPENSE_DELETE_APPLY_INVALID' using errcode='22023';
  end if;

  perform 1
  from public.timesheets delete_timesheet
  where delete_timesheet.timesheet_id=any(p_expected_timesheet_ids)
  order by delete_timesheet.timesheet_id
  for update;

  v_context:=private._timesheet_pending_expense_delete_context_v1(
    v_environment,p_expected_timesheet_ids,true
  );
  if lower(v_context->>'context_sha256') is distinct from
       lower(p_expected_pending_expense_context_sha256) then
    raise exception 'PENDING_EXPENSE_DELETE_CONTEXT_CHANGED'
      using errcode='40001',detail=v_context::text;
  end if;
  if coalesce((v_context->>'delete_blocked')::boolean,false) then
    raise exception 'PENDING_EXPENSE_DELETE_BLOCKED'
      using errcode='55000',detail=v_context::text;
  end if;

  -- Every supported removal unit belongs to one Candidate. Capture and lock
  -- that owner while the Timesheets still exist so deletion cannot leave a
  -- stale Banking Pay view or try to validate a Timesheet after it is gone.
  select coalesce(array_agg(distinct owner.candidate_id order by owner.candidate_id),array[]::uuid[])
  into v_delete_candidate_ids
  from (
    select contract_row.candidate_id
    from public.timesheets timesheet_row
    join public.contracts contract_row on contract_row.id=timesheet_row.contract_id
    where timesheet_row.timesheet_id=any(p_expected_timesheet_ids)
    union all
    select financial_row.candidate_id
    from public.timesheets_financials financial_row
    where financial_row.timesheet_id=any(p_expected_timesheet_ids)
      and financial_row.is_current
    union all
    select request.candidate_id from private.timesheet_correction_requests request
    where request.replacement_timesheet_id=any(p_expected_timesheet_ids)
      and private.timesheet_correction_cancel_capability_v1(request.replacement_timesheet_id,p_actor_user_id) is not null
  ) owner
  where owner.candidate_id is not null;
  if cardinality(v_delete_candidate_ids)<>1 then
    raise exception 'TIMESHEET_DELETE_CANDIDATE_OWNERSHIP_INVALID'
      using errcode='23514',detail=jsonb_build_object(
        'candidate_count',cardinality(v_delete_candidate_ids)
      )::text;
  end if;
  v_delete_candidate_id:=v_delete_candidate_ids[1];
  v_candidate_lock_key:=pg_catalog.hashtextextended(
    public._pay_workbench_candidate_serial_key(v_delete_candidate_id),24062027
  );
  perform pg_catalog.pg_advisory_xact_lock(v_candidate_lock_key);

  if coalesce((v_context->>'cancellation_required')::boolean,false) then
    v_settings:=public.candidate_manager_email_settings_get_v1();
    v_template:=v_settings#>'{templates,EXPENSE_CLAIM,CANCELLATION}';
    v_terminal_mail:=jsonb_build_object(
      'subject',v_template->>'subject',
      'body_text',v_template->>'body_text',
      'body_html',v_template->>'body_html',
      'manager_template_version',v_settings->'version',
      'manager_template_sha256',v_settings->>'semantic_sha256_hex',
      'manager_submission_type','EXPENSE_CLAIM'
    );
  end if;

  for v_claim in
    select value from jsonb_array_elements(coalesce(
      v_context->'pending_expense_claims','[]'::jsonb
    )) items(value)
  loop
    select workflow_row.* into strict v_workflow
    from public.candidate_submission_workflows workflow_row
    where workflow_row.id=(v_claim->>'workflow_id')::uuid
      and workflow_row.generation=(v_claim->>'generation')::integer
      and workflow_row.environment=v_environment
      and workflow_row.workflow_kind='CONTRACT_EXPENSE'
      and workflow_row.target_timesheet_id is null
    for update;

    perform 1 from public.candidate_notifications notification
    where notification.workflow_id=v_workflow.id
       or notification.timesheet_id=any(p_expected_timesheet_ids)
    order by notification.id
    for update;

    perform private._candidate_office_service_context_open_v1(
      v_environment,p_actor_user_id,'delete_timesheet','CANCEL',p_now_utc
    );
    v_cancel_result:=public.candidate_workflow_cancel_atomic_v2(
      null,v_environment,v_workflow.id,v_workflow.generation,
      jsonb_build_object(
        'service_office_action',true,
        'actor_user_id',p_actor_user_id,
        'reason_note','Pending expense claim cancelled because its Timesheet was deleted.',
        'reason_code','TIMESHEET_DELETED',
        'manager_terminal_mail',v_terminal_mail
      ),
      'office-timesheet-delete:'||p_delete_operation_id::text||':'||v_workflow.id::text,
      p_now_utc
    );
    perform private._candidate_office_service_context_close_v1();

    update public.candidate_submission_components component
    set timesheet_id=null
    where component.workflow_id=v_workflow.id
      and component.timesheet_id=any(p_expected_timesheet_ids);

    update public.candidate_notifications notification
    set timesheet_id=null,
        deep_link_json=(coalesce(notification.deep_link_json,'{}'::jsonb)
          -'timesheet_id'-'contract_week_id')||jsonb_build_object(
            'type','workflow','workflow_id',v_workflow.id
          ),
        state='DISMISSED',
        dismissed_at_utc=coalesce(notification.dismissed_at_utc,p_now_utc),
        push_state=case
          when notification.push_state in ('PENDING','FAILED','CLAIMED') then 'SKIPPED'
          else notification.push_state
        end
    where notification.workflow_id=v_workflow.id;

    update public.candidate_submission_workflows workflow_row
    set contract_week_id=null,
        anchor_timesheet_id=null,
        target_timesheet_id=null,
        input_snapshot_json=coalesce(workflow_row.input_snapshot_json,'{}'::jsonb)
          ||jsonb_build_object(
            'office_permanent_delete_tombstone',jsonb_build_object(
              'delete_operation_id',p_delete_operation_id,
              'deleted_timesheet_ids',to_jsonb(p_expected_timesheet_ids),
              'deleted_contract_week_ids',to_jsonb(p_expected_contract_week_ids),
              'previous_contract_week_id',v_workflow.contract_week_id,
              'previous_anchor_timesheet_id',v_workflow.anchor_timesheet_id,
              'previous_target_timesheet_id',v_workflow.target_timesheet_id,
              'retired_at_utc',p_now_utc
            )
          ),
        issue_codes=(case
          when workflow_row.issue_codes @> '["OFFICE_TIMESHEET_DELETED_EXPENSE_CANCELLED"]'::jsonb
            then workflow_row.issue_codes
          else workflow_row.issue_codes||'["OFFICE_TIMESHEET_DELETED_EXPENSE_CANCELLED"]'::jsonb
        end)||(case
          when workflow_row.issue_codes @> '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
            then '[]'::jsonb
          else '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
        end),
        updated_at_utc=p_now_utc
    where workflow_row.id=v_workflow.id
      and workflow_row.state='CANCELLED'
      and workflow_row.target_timesheet_id is null;
    if not found then
      raise exception 'PENDING_EXPENSE_CANCELLATION_NOT_PROVEN' using errcode='40001';
    end if;

    insert into public.candidate_notifications(
      account_id,candidate_id,workflow_id,timesheet_id,event_type,preference_category,
      template_key,template_params,deep_link_json,state,push_state,dedupe_key,created_at_utc
    )
    select
      v_workflow.account_id,v_workflow.candidate_id,v_workflow.id,null,
      'EXPENSE_CLAIM_CANCELLED','timesheet_expense_attention',
      'candidate-expense-claim-cancelled-timesheet-delete-v1',
      jsonb_build_object(
        'workflow_id',v_workflow.id,
        'reason_code','TIMESHEET_DELETED'
      ),
      jsonb_build_object('type','workflow','workflow_id',v_workflow.id),
      'UNREAD',
      case
        when account.status='ACTIVE'
          and coalesce((account.notification_preferences_json->>'push')::boolean,true)
          and coalesce(
            (account.notification_preferences_json->>'timesheet_expense_attention')::boolean,
            (account.notification_preferences_json->>'office_rejection')::boolean,
            true
          )
          then 'PENDING'
        else 'SKIPPED'
      end,
      'CANDIDATE_EXPENSE_CLAIM_CANCELLED_TIMESHEET_DELETE_V1:'
        ||v_workflow.id::text||':'||v_workflow.generation::text,
      p_now_utc
    from public.candidate_app_accounts account
    where account.id=v_workflow.account_id
    on conflict(dedupe_key) do update set dedupe_key=excluded.dedupe_key
    returning id into v_notification_id;

    v_notification_ids:=array_append(v_notification_ids,v_notification_id);
    v_cancel_results:=v_cancel_results||jsonb_build_array(jsonb_build_object(
      'workflow_id',v_workflow.id,
      'previous_generation',v_workflow.generation,
      'state','CANCELLED',
      'notification_id',v_notification_id,
      'cancellation',v_cancel_result
    ));
  end loop;

  -- The established Timesheet delete removes financial rows before the
  -- Timesheet. Suppress only the duplicate row-level delete signals for this
  -- one locked Candidate, then issue one complete Candidate refresh after the
  -- authoritative delete has been proved. This uses the existing sealed
  -- Banking Pay suppression boundary and changes no financial truth.
  if pg_catalog.to_regclass('pg_temp._bpay_candidate_delete_context_v1') is not null then
    raise exception 'PAY_WORKBENCH_CANDIDATE_DELETE_CONTEXT_CONFLICT' using errcode='23514';
  end if;
  create temp table pg_temp._bpay_candidate_delete_context_v1(
    candidate_id uuid primary key,
    delete_operation_id uuid unique not null,
    candidate_lock_key bigint not null,
    backend_pid integer not null,
    transaction_id bigint not null,
    created_at_utc timestamptz not null,
    suppress boolean not null check(suppress)
  ) on commit drop;
  insert into pg_temp._bpay_candidate_delete_context_v1 values(
    v_delete_candidate_id,p_delete_operation_id,v_candidate_lock_key,
    pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),p_now_utc,true
  );

  if v_kind='STANDARD_DELETE' then
    v_apply_result:=public.timesheet_standard_delete_apply_v1(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_id,p_expected_row_signature
    );
  elsif v_kind='DAILY_ABANDONED_RECEIPT_DELETE' then
    v_apply_result:=public.timesheet_daily_abandoned_receipt_delete_apply_v1(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_id,p_expected_row_signature
    );
  elsif v_kind='WEEKLY_CHAIN_DELETE_PARENT' then
    v_apply_result:=public.timesheet_weekly_chain_delete_apply(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_ids,
      p_expected_contract_week_ids,p_expected_nhsp_shift_ids,p_expected_row_signature
    );
  else
    v_apply_result:=public.timesheet_weekly_manual_adjustment_delete_apply(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_ids,
      p_expected_contract_week_ids,p_expected_preserved_source_timesheet_ids,
      p_expected_preserved_source_contract_week_ids,p_expected_row_signature
    );
  end if;

  if coalesce((v_apply_result->>'apply_performed')::boolean,false) is not true
     or upper(coalesce(v_apply_result->>'decision',''))<>'PERMANENT_DELETE' then
    raise exception 'TIMESHEET_DELETE_AFTER_EXPENSE_CANCELLATION_NOT_PROVEN'
      using errcode='40001',detail=coalesce(v_apply_result,'{}'::jsonb)::text;
  end if;

  drop table pg_temp._bpay_candidate_delete_context_v1;
  v_banking_dirty_result:=public.pay_workbench_dirty_event_enqueue(
    p_job_type=>'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    p_scope_kind=>'CANDIDATE',
    p_scope_id=>v_delete_candidate_id::text,
    p_candidate_id=>v_delete_candidate_id,
    p_targeted_timesheet_ids=>array[]::uuid[],
    p_linked_timesheet_ids=>array[]::uuid[],
    p_payload_json=>jsonb_build_object(
      'trigger_table','timesheets',
      'trigger_op','DELETE',
      'trigger_operation','DELETE',
      'delete_operation_id',p_delete_operation_id,
      'deleted_timesheet_ids',coalesce(v_apply_result->'deleted_timesheet_ids','[]'::jsonb),
      'scope_resolution','CANDIDATE_FULL_AFTER_TIMESHEET_DELETE',
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH',
      'economic_truth_mutation_allowed',false
    ),
    p_reason=>'DIRTY_TRIGGER:TIMESHEETS:DELETE',
    p_priority=>-1000,
    p_run_at_utc=>p_now_utc
  );
  if coalesce((v_banking_dirty_result->>'ok')::boolean,false) is not true then
    raise exception 'TIMESHEET_DELETE_BANKING_REFRESH_NOT_PROVEN'
      using errcode='40001',detail=coalesce(v_banking_dirty_result,'{}'::jsonb)::text;
  end if;

  return v_apply_result||jsonb_build_object(
    'pending_expense_context_sha256',v_context->>'context_sha256',
    'cancelled_pending_expense_claim_count',jsonb_array_length(v_cancel_results),
    'cancelled_pending_expense_claims',v_cancel_results,
    'candidate_notification_ids',to_jsonb(v_notification_ids),
    'banking_pay_candidate_refresh',v_banking_dirty_result
  );
exception when others then
  perform private._candidate_office_service_context_close_v1();
  raise;
end;
$function$;

