-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function public.invoice_render_manifest(p_invoice_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_invoice_debug boolean := false;
  v_dbg_started timestamptz := now();
  v_manifest jsonb := null;

  v_lines_count int := 0;
  v_timesheet_ids_count int := 0;
  v_evidence_count int := 0;
  v_ts_evidence_count int := 0;
  v_ev_other_count int := 0;
  v_history_count int := 0;
  v_seg_keys_count int := 0;

  v_sqlstate text := null;
  v_err text := null;
begin
  -- Load invoice_debug flag (safe even if column not yet present)
  begin
    select coalesce(sd.invoice_debug, false)
    into v_invoice_debug
    from public.settings_defaults sd
    where sd.id = 1
    limit 1;
  exception when undefined_column then
    v_invoice_debug := false;
  end;

  with inv as (
    select
      i.*,
      (i.header_snapshot_json->'attach_policy') as attach_policy
    from public.invoices i
    where i.id = p_invoice_id
    limit 1
  ),
  lines as (
    select
      l.*,
      ts.manual_pdf_r2_key,
      coalesce(
        l.paper_ts_r2_key,
        ts.manual_pdf_r2_key,
        case
          when l.timesheet_id is not null
            then ('docs-pdf/timesheets/ts_' || l.timesheet_id::text || '.pdf')
          else null
        end
      ) as effective_paper_ts_r2_key
    from public.invoice_lines l
    left join public.timesheets ts
      on ts.timesheet_id = l.timesheet_id
    where l.invoice_id = p_invoice_id
    order by l.created_at asc
  ),
  ts_ids as (
    select distinct
      case
        when l.timesheet_id is not null then l.timesheet_id
        when l.meta_json is not null
          and nullif(btrim(coalesce(l.meta_json->>'timesheet_id','')), '') is not null
          and nullif(btrim(coalesce(l.meta_json->>'timesheet_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        then nullif(btrim(coalesce(l.meta_json->>'timesheet_id','')), '')::uuid
        else null
      end as timesheet_id
    from lines l
    where
      l.timesheet_id is not null
      or (
        l.meta_json is not null
        and nullif(btrim(coalesce(l.meta_json->>'timesheet_id','')), '') is not null
        and nullif(btrim(coalesce(l.meta_json->>'timesheet_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
  ),

  -- ✅ UPDATED: reference rows joined to candidate display name (for UI display)
  -- Hardened candidate resolution via COALESCE(contract candidate vs TSFIN candidate).
  ref_rows_joined as (
    select
      r.*,
      con0.id as contract_id,
      coalesce(con0.candidate_id, tf0.candidate_id) as candidate_id,
      coalesce(
        nullif(btrim(coalesce(cand_contract.display_name,'')), ''),
        nullif(btrim(coalesce(cand_tf.display_name,'')), '')
      ) as candidate_display
    from public.invoice_reference_rows(p_invoice_id) r
    left join public.timesheets ts0
      on ts0.timesheet_id = r.timesheet_id
    left join public.contracts con0
      on con0.id = ts0.contract_id
    left join public.timesheets_financials tf0
      on tf0.timesheet_id = r.timesheet_id
     and tf0.is_current = true
    left join public.candidates cand_contract
      on cand_contract.id = con0.candidate_id
    left join public.candidates cand_tf
      on cand_tf.id = tf0.candidate_id
  ),

  -- ✅ additional timesheet ids referenced by reference rows (may include ids not present in lines)
  ref_ts_ids as (
    select distinct r.timesheet_id
    from ref_rows_joined r
    where r.timesheet_id is not null
  ),

  -- ✅ union set for reference-source hydration
  ts_ids_for_ref_sources as (
    select timesheet_id from ts_ids
    union
    select timesheet_id from ref_ts_ids
  ),

  -- ✅ TSFIN sources for timesheets that may have SEGMENTS refs (NHSP/HR/etc)
  tsfin_ref_sources as (
    select
      tf.timesheet_id,
      tf.invoice_breakdown_json
    from public.timesheets_financials tf
    where tf.is_current = true
      and tf.timesheet_id in (select timesheet_id from ts_ids_for_ref_sources)
  ),

  -- ✅ sources needed by FE to rebuild reference update payloads without extra calls
  --   - If timesheets.actual_schedule_json is present and non-empty, use it.
  --   - Else if TSFIN is SEGMENTS mode, derive an editable schedule-like array from TSFIN segments
  --     so multi-shift/day (NHSP/HR/manual) works via segment_id/start/end matching.
  ts_reference_sources as (
    select
      t.timesheet_id,
      t.reference_number,
      t.day_references_json,
      case
        when tf.invoice_breakdown_json is not null
          and jsonb_typeof(tf.invoice_breakdown_json) = 'object'
          and upper(coalesce(tf.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
          and jsonb_typeof(tf.invoice_breakdown_json->'segments') = 'array'
        then coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'segment_id', seg->>'segment_id',
              'date', seg->>'date',
              'start_utc', seg->>'start_utc',
              'end_utc', seg->>'end_utc',
              -- legacy-friendly aliases (FE/DB matching may use either)
              'start', seg->>'start_utc',
              'end', seg->>'end_utc',
              'ref_num', seg->>'ref_num',
              'source_system', seg->>'source_system'
            )
            order by
              coalesce(seg->>'date',''),
              coalesce(seg->>'start_utc',''),
              coalesce(seg->>'segment_id','')
          )
          from jsonb_array_elements(tf.invoice_breakdown_json->'segments') seg
        ), '[]'::jsonb)

        when t.actual_schedule_json is not null
          and jsonb_typeof(t.actual_schedule_json) = 'array'
          and jsonb_array_length(t.actual_schedule_json) > 0
        then t.actual_schedule_json

        else '[]'::jsonb
      end as actual_schedule_json
    from public.timesheets t
    left join tsfin_ref_sources tf
      on tf.timesheet_id = t.timesheet_id
    where t.timesheet_id in (select timesheet_id from ts_ids_for_ref_sources)
  ),

  -- ✅ NEW: per-timesheet deterministic current refs signature (invoice-scoped)
  ref_sig_by_timesheet as (
    select
      r.timesheet_id,
      encode(
        extensions.digest(
          coalesce(
            string_agg(
              (
                concat_ws(
                  '|',
                  r.timesheet_id::text,
                  r.ref_target,
                  coalesce(r.segment_id,''),
                  coalesce(r.day_ymd::text,''),
                  coalesce(r.start_utc::text,''),
                  coalesce(r.end_utc::text,'')
                )
                || '=' || coalesce(r.current_reference,'')
              ),
              '||'
              ORDER BY
                concat_ws(
                  '|',
                  r.timesheet_id::text,
                  r.ref_target,
                  coalesce(r.segment_id,''),
                  coalesce(r.day_ymd::text,''),
                  coalesce(r.start_utc::text,''),
                  coalesce(r.end_utc::text,'')
                )
            ),
            ''
          ),
          'sha256'
        ),
        'hex'
      ) as current_refs_sig
    from ref_rows_joined r
    where r.timesheet_id is not null
    group by r.timesheet_id
  ),

  -- ✅ NEW: summary-derived exclusion flags (NHSP / no_timesheet_required) per timesheet
  ts_summary_flags as (
    select
      v.timesheet_id,
      coalesce(v.client_is_nhsp, false) as client_is_nhsp,
      coalesce(v.client_no_timesheet_required, false) as client_no_timesheet_required
    from public.v_timesheets_summary_base v
    where v.timesheet_id in (select timesheet_id from ts_ids)
  ),

  -- ✅ NEW: per-timesheet document flags (electronic regen + QR refs changed)
  -- ✅ FIX: exclude NHSP / no_timesheet_required from BOTH electronic and QR flags
  timesheet_doc_flags as (
    select
      ts.timesheet_id,
      jsonb_build_object(
        'electronic_refs_changed', flags.electronic_changed,
        'electronic_pdf_regen_required', flags.electronic_changed,
        'qr_refs_changed', flags.qr_changed,
        'reasons', reasons.reasons_json
      ) as flags_json
    from ts_ids tid
    join public.timesheets ts
      on ts.timesheet_id = tid.timesheet_id
    left join ref_sig_by_timesheet rs
      on rs.timesheet_id = ts.timesheet_id
    left join ts_summary_flags sf
      on sf.timesheet_id = ts.timesheet_id
    cross join lateral (
      select
        (
          (not x.is_excluded)
          and upper(coalesce(ts.submission_mode::text,'')) = 'ELECTRONIC'
          and ts.manual_pdf_r2_key is null
          and rs.current_refs_sig is not null
          and (ts.generated_pdf_refs_sig is null or ts.generated_pdf_refs_sig <> rs.current_refs_sig)
        ) as electronic_changed,

        (
          (not x.is_excluded)
          and (
            (
              ts.qr_status is not null
              or ts.qr_token is not null
              or ts.qr_last_sent_hash is not null
              or ts.qr_last_sent_at_utc is not null
            )
          )
          and rs.current_refs_sig is not null
          and (ts.qr_sent_refs_sig is null or ts.qr_sent_refs_sig <> rs.current_refs_sig)
        ) as qr_changed
      from (
        select
          (
            coalesce(sf.client_is_nhsp, false) = true
            or coalesce(sf.client_no_timesheet_required, false) = true
          ) as is_excluded
      ) x
    ) flags
    cross join lateral (
      select coalesce(jsonb_agg(z.reason) filter (where z.reason is not null), '[]'::jsonb) as reasons_json
      from (
        select
          case
            when flags.electronic_changed and ts.generated_pdf_refs_sig is null then 'ELECTRONIC_REFS_SIG_MISSING'
            when flags.electronic_changed then 'ELECTRONIC_REFS_SIG_DIFFERENT'
            else null
          end as reason
        union all
        select
          case
            when flags.qr_changed and ts.qr_sent_refs_sig is null then 'QR_REFS_SIG_MISSING'
            when flags.qr_changed then 'QR_REFS_SIG_DIFFERENT'
            else null
          end as reason
      ) z
    ) reasons
  ),

  ev as (
    select
      e.timesheet_id,
      e.kind,
      e.display_name,
      e.storage_key,
      e.created_at
    from public.timesheet_evidence e
    where e.timesheet_id in (select timesheet_id from ts_ids)
    order by e.created_at asc
  ),
  hr_cache as (
    select
      r.invoice_id,
      r.source_system,
      r.import_id,
      r.header_rows,
      r.header_columns,
      r.rows_json
    from public.invoice_hr_source_rows r
    where r.invoice_id = p_invoice_id
  ),
  tsfin as (
    select
      tf.id as tsfin_id,
      tf.timesheet_id,
      tf.external_source_rows_json,

      -- ✅ Mileage fields for invoice itemisation
      tf.mileage_units,
      tf.mileage_pay_rate,
      tf.mileage_charge_rate
    from public.timesheets_financials tf
    where tf.is_current = true
      and tf.timesheet_id in (select timesheet_id from ts_ids)
  ),

  tsfin_segments as (
    select
      tf.id as tsfin_id,
      tf.timesheet_id,
      tf.invoice_breakdown_json
    from public.timesheets_financials tf
    where tf.is_current = true
      and tf.timesheet_id in (select timesheet_id from ts_ids)
  ),
  seg_stats as (
    select
      t.timesheet_id,
      t.tsfin_id,

      -- ONLY segments on THIS invoice
      coalesce(
        jsonb_agg(
          s.seg
          order by coalesce(s.seg->>'date',''), coalesce(s.seg->>'segment_id','')
        ) filter (
          where s.seg is not null
            and s.locked_text = p_invoice_id::text
        ),
        '[]'::jsonb
      ) as invoiced_segments,

      -- counts (do not return the segments)
      (count(*) filter (where s.seg is not null and s.locked_text is null))::int
        as uninvoiced_segment_count,

      (count(*) filter (where s.seg is not null and s.locked_text is not null and s.locked_text <> p_invoice_id::text))::int
        as locked_elsewhere_segment_count

    from tsfin_segments t

    left join lateral (
      select
        value as seg,
        nullif(btrim(coalesce(value->>'invoice_locked_invoice_id','')), '') as locked_text
      from jsonb_array_elements(
        case
          when t.invoice_breakdown_json is not null
            and jsonb_typeof(t.invoice_breakdown_json) = 'object'
            and jsonb_typeof(t.invoice_breakdown_json->'segments') = 'array'
          then t.invoice_breakdown_json->'segments'
          else '[]'::jsonb
        end
      ) value
    ) s on true

    where upper(coalesce(t.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'

    group by t.timesheet_id, t.tsfin_id
  ),
  hist_audit as (
    select
      ae.id,
      ae.ts_utc,
      ae.actor_user_id,
      coalesce(ae.actor_display, tu.display_name, tu.email, 'CloudTMS server') as actor_display,
      coalesce(ae.actor_role_at_time, tu.role, 'system') as actor_role_at_time,
      ae.object_type,
      ae.object_id_text,
      ae.action,
      ae.before_json,
      ae.after_json,
      ae.reason,
      ae.ip,
      ae.user_agent,
      ae.correlation_id
    from public.audit_events ae
    left join public.tms_users tu
      on tu.id = ae.actor_user_id
    where ae.object_type in ('invoice','invoices')
      and ae.object_id_text = p_invoice_id::text
    order by ae.ts_utc desc, ae.id desc
    limit 500
  ),
  hist_mail as (
    select
      m.id as mail_outbox_id,
      m.created_at_utc as ts_utc,
      m.status,
      m."to" as to_email,
      m.subject,
      m.reference
    from public.mail_outbox m
    where upper(coalesce(m.type,'')) = 'INVOICE'
      and m.attachments is not null
      and jsonb_typeof(m.attachments) = 'array'
      and exists (
        select 1
        from jsonb_array_elements(m.attachments) a
        where btrim(coalesce(a->>'invoice_id','')) = p_invoice_id::text
      )
    order by m.created_at_utc desc, m.id desc
    limit 200
  ),
  history as (
    select
      jsonb_build_object(
        'kind','AUDIT',
        'id', ae.id::text,
        'ts_utc', to_jsonb(ae.ts_utc),
        'actor_user_id', case when ae.actor_user_id is null then null else ae.actor_user_id::text end,
        'actor_display', ae.actor_display,
        'actor_role_at_time', ae.actor_role_at_time,
        'action', ae.action,
        'reason', ae.reason,
        'object_type', ae.object_type,
        'object_id_text', ae.object_id_text,
        'before_json', ae.before_json,
        'after_json', ae.after_json,
        'ip', ae.ip,
        'user_agent', ae.user_agent,
        'correlation_id', ae.correlation_id
      ) as row_json,
      ae.ts_utc as ts_sort
    from hist_audit ae

    union all

    select
      jsonb_build_object(
        'kind','EMAIL',
        'mail_outbox_id', m.mail_outbox_id::text,
        'ts_utc', to_jsonb(m.ts_utc),
        'status', m.status::text,
        'to', m.to_email,
        'subject', m.subject,
        'reference', m.reference
      ) as row_json,
      m.ts_utc as ts_sort
    from hist_mail m
  ),
  email_summary as (
    select
      count(*)::int as email_count,
      max(m.created_at_utc) as last_email_at_utc
    from public.mail_outbox m
    where upper(coalesce(m.type,'')) = 'INVOICE'
      and m.attachments is not null
      and jsonb_typeof(m.attachments) = 'array'
      and exists (
        select 1
        from jsonb_array_elements(m.attachments) a
        where btrim(coalesce(a->>'invoice_id','')) = p_invoice_id::text
      )
  )
  select jsonb_build_object(
    'invoice', to_jsonb(inv.*),
    'header_snapshot_json', coalesce((select inv.header_snapshot_json from inv), '{}'::jsonb),
    'attach_policy', coalesce((select inv.attach_policy from inv), null),

    'lines', coalesce((
      select jsonb_agg(
        to_jsonb(l.*)
        || jsonb_build_object('paper_ts_r2_key', l.effective_paper_ts_r2_key)
        || jsonb_build_object('is_adjustment', (l.timesheet_id is null or upper(coalesce(l.meta_json->>'line_type','')) = 'ADJUSTMENT'))
        || jsonb_build_object('line_type_norm', upper(coalesce(l.meta_json->>'line_type','')))
        order by l.created_at
      )
      from lines l where l.meta_json->>'presentation_disposition' is distinct from 'SUPPRESS_ZERO_ROUNDING_AUTHORITY'
        or private.weekly_source_invoice_rounding_suppression_witness_v1(l.id) is null
    ), '[]'::jsonb),

    'timesheet_ids', coalesce((select jsonb_agg(t.timesheet_id::text) from ts_ids t), '[]'::jsonb),

    -- ✅ NEW: per-timesheet document flags for renderer (electronic regen + QR refs changed)
    'timesheet_doc_flags_by_id', coalesce((
      select jsonb_object_agg(
        f.timesheet_id::text,
        f.flags_json
      )
      from timesheet_doc_flags f
    ), '{}'::jsonb),

    -- ✅ mapping needed for segment edits (tsfin_id is invoice_apply_edits input)
    'tsfin_id_by_timesheet_id', coalesce((
      select jsonb_object_agg(
        t.timesheet_id::text,
        t.tsfin_id::text
      )
      from tsfin t
    ), '{}'::jsonb),

    -- ✅ mileage units/rates per timesheet (for PDF builder / UI without scanning lines)
    'mileage_by_timesheet_id', coalesce((
      select jsonb_object_agg(
        t.timesheet_id::text,
        jsonb_build_object(
          'mileage_units', t.mileage_units,
          'mileage_pay_rate', t.mileage_pay_rate,
          'mileage_charge_rate', t.mileage_charge_rate
        )
      )
      from tsfin t
    ), '{}'::jsonb),

    -- ✅ reference sources needed by FE to build reference update payloads with no extra calls
    'timesheet_reference_sources_by_id', coalesce((
      select jsonb_object_agg(
        s.timesheet_id::text,
        jsonb_build_object(
          'reference_number', s.reference_number,
          'day_references_json', s.day_references_json,
          'actual_schedule_json', s.actual_schedule_json
        )
      )
      from ts_reference_sources s
    ), '{}'::jsonb),

    -- ✅ UPDATED: embed reference edit rows for zero-subrequest ref modal
    -- Adds candidate_display for UI rendering and deterministic row_key to stabilise FE staging identity.
    'reference_rows', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'row_key', concat_ws(
            '::',
            r.timesheet_id::text,
            r.ref_target,
            coalesce(r.segment_id,''),
            coalesce(r.day_ymd::text,''),
            coalesce(r.start_utc::text,''),
            coalesce(r.end_utc::text,'')
          ),
          'timesheet_id', r.timesheet_id::text,
          'candidate_id', case when r.candidate_id is null then null else r.candidate_id::text end,
          'candidate_display', r.candidate_display,
          'sheet_scope', r.sheet_scope,
          'submission_mode', r.submission_mode,
          'ref_target', r.ref_target,
          'segment_id', r.segment_id,
          'day_ymd', r.day_ymd,
          'start_utc', r.start_utc,
          'end_utc', r.end_utc,
          'current_reference', r.current_reference,
          'is_required', r.is_required
        )
        order by
          r.timesheet_id::text,
          r.ref_target,
          r.day_ymd nulls last,
          r.start_utc nulls last,
          r.end_utc nulls last,
          r.segment_id nulls last
      )
      from ref_rows_joined r
    ), '[]'::jsonb),

    -- SEGMENTS: segment info for invoice modal expansion
    'segments_by_timesheet', coalesce((
      select jsonb_object_agg(
        s.timesheet_id::text,
        jsonb_build_object(
          'tsfin_id', case when s.tsfin_id is null then null else s.tsfin_id::text end,
          'invoiced_segments', coalesce(s.invoiced_segments, '[]'::jsonb),
          'uninvoiced_segment_count', coalesce(s.uninvoiced_segment_count, 0),
          'locked_elsewhere_segment_count', coalesce(s.locked_elsewhere_segment_count, 0)
        )
      )
      from seg_stats s
    ), '{}'::jsonb),

    -- Alias required by brief
    'segments_on_invoice_by_timesheet', coalesce((
      select jsonb_object_agg(
        s.timesheet_id::text,
        jsonb_build_object(
          'tsfin_id', case when s.tsfin_id is null then null else s.tsfin_id::text end,
          'invoiced_segments', coalesce(s.invoiced_segments, '[]'::jsonb),
          'uninvoiced_segment_count', coalesce(s.uninvoiced_segment_count, 0),
          'locked_elsewhere_segment_count', coalesce(s.locked_elsewhere_segment_count, 0)
        )
      )
      from seg_stats s
    ), '{}'::jsonb),

    -- Backward compatible aggregate (all evidence)
    'evidence', coalesce((
      select jsonb_agg(to_jsonb(ev.*) order by ev.created_at)
      from ev
    ), '[]'::jsonb),

    -- New explicit splits
    'timesheet_evidence', coalesce((
      select jsonb_agg(to_jsonb(ev.*) order by ev.created_at)
      from ev
      where upper(coalesce(ev.kind,'')) = 'TIMESHEET'
    ), '[]'::jsonb),

    'evidence_other', coalesce((
      select jsonb_agg(to_jsonb(ev.*) order by ev.created_at)
      from ev
      where upper(coalesce(ev.kind,'')) <> 'TIMESHEET'
    ), '[]'::jsonb),

    'hr_source_rows_cache', coalesce((select jsonb_agg(to_jsonb(h.*)) from hr_cache h), '[]'::jsonb),
    'tsfin_external_source_rows', coalesce((select jsonb_agg(to_jsonb(t.*)) from tsfin t), '[]'::jsonb),

    -- Invoice history
    'history', coalesce((
      select jsonb_agg(h.row_json order by h.ts_sort desc)
      from history h
    ), '[]'::jsonb),

    -- email summary for UI label (Email vs Re-email)
    'email_summary', jsonb_build_object(
      'emailed_once', (coalesce((select email_count from email_summary),0) > 0),
      'email_count', coalesce((select email_count from email_summary),0),
      'last_email_at_utc', (select last_email_at_utc from email_summary)
    )
  )
  into v_manifest
  from inv;

  if v_manifest is null then
    v_manifest := '{}'::jsonb;
  end if;

  -- Extract simple counts for debug
  begin
    v_lines_count := coalesce(jsonb_array_length(coalesce(v_manifest->'lines','[]'::jsonb)), 0);
  exception when others then
    v_lines_count := 0;
  end;

  begin
    v_timesheet_ids_count := coalesce(jsonb_array_length(coalesce(v_manifest->'timesheet_ids','[]'::jsonb)), 0);
  exception when others then
    v_timesheet_ids_count := 0;
  end;

  begin
    v_evidence_count := coalesce(jsonb_array_length(coalesce(v_manifest->'evidence','[]'::jsonb)), 0);
  exception when others then
    v_evidence_count := 0;
  end;

  begin
    v_ts_evidence_count := coalesce(jsonb_array_length(coalesce(v_manifest->'timesheet_evidence','[]'::jsonb)), 0);
  exception when others then
    v_ts_evidence_count := 0;
  end;

  begin
    v_ev_other_count := coalesce(jsonb_array_length(coalesce(v_manifest->'evidence_other','[]'::jsonb)), 0);
  exception when others then
    v_ev_other_count := 0;
  end;

  begin
    v_history_count := coalesce(jsonb_array_length(coalesce(v_manifest->'history','[]'::jsonb)), 0);
  exception when others then
    v_history_count := 0;
  end;

  begin
    select coalesce(count(*),0)
    into v_seg_keys_count
    from jsonb_object_keys(coalesce(v_manifest->'segments_by_timesheet','{}'::jsonb)) k;
  exception when others then
    v_seg_keys_count := 0;
  end;

  if v_invoice_debug then
    perform public._inv_write_audit(
      null,
      'INVOICE_RENDER_MANIFEST_DEBUG',
      jsonb_build_object(
        'invoice_id', p_invoice_id::text,
        'run_started_at_utc', public._inv_iso_utc(v_dbg_started),
        'run_finished_at_utc', public._inv_iso_utc(now()),
        'counts', jsonb_build_object(
          'lines', v_lines_count,
          'timesheet_ids', v_timesheet_ids_count,
          'evidence', v_evidence_count,
          'timesheet_evidence', v_ts_evidence_count,
          'evidence_other', v_ev_other_count,
          'history', v_history_count,
          'segments_by_timesheet_keys', v_seg_keys_count
        )
      ),
      'invoices',
      p_invoice_id::text,
      null,
      'INVOICE_DEBUG',
      null,
      null,
      null
    );
  end if;

  v_manifest:=v_manifest||private.weekly_source_invoice_legacy_render_support_v1(p_invoice_id);
  return v_manifest;

exception when others then
  v_sqlstate := sqlstate;
  v_err := sqlerrm;

  if v_invoice_debug then
    perform public._inv_write_audit(
      null,
      'INVOICE_RENDER_MANIFEST_ERROR',
      jsonb_build_object(
        'invoice_id', p_invoice_id::text,
        'run_started_at_utc', public._inv_iso_utc(v_dbg_started),
        'run_failed_at_utc', public._inv_iso_utc(now()),
        'error', jsonb_build_object(
          'sqlstate', v_sqlstate,
          'message', v_err
        )
      ),
      'invoices',
      p_invoice_id::text,
      null,
      'INVOICE_DEBUG',
      null,
      null,
      null
    );
  end if;

  raise;
end;
$$;

notify pgrst,'reload schema';


-- CONTACT_PREPARER_UNIT 119 repeatable supabase/repeatable/13102026_1705_weekly_source_invoice_adjustments_v1.sql SHA256 82c4664300bb18c7f4ad0a690c9865c02655311699c065f7f336a1f323475177
-- Complete F4 authority beside current native window/Money/Report owners.


-- Proposal only. Root integrates beside the current Money/Report/PP owners.
-- Existing invoice_lines/meta/audit/document invalidation own all persistence.
create or replace function private.weekly_source_invoice_adjustment_authority_v1(p_invoice_id uuid,p_binding_ids uuid[] default null)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare inv public.invoices%rowtype; v_ids uuid[]; v_count integer; v_rates integer; v_null_rates integer;
  v_rate numeric; v_records jsonb; v_payload jsonb; v_group uuid; v_versions uuid[];
begin
  select * into inv from public.invoices where id=p_invoice_id;
  if not found or inv.type::text is distinct from 'INVOICE'
    or inv.header_snapshot_json->>'schema_version' is distinct from 'WEEKLY_SOURCE_SELF_BILL_INVOICE_V1'
    or inv.header_snapshot_json#>>'{meta,source}' is distinct from 'WEEKLY_FINAL_SOURCE' then
    return jsonb_build_object('allowed',false); end if;
  if pg_input_is_valid(inv.header_snapshot_json#>>'{meta,source_group_id}','uuid') is distinct from true then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_AUTHORITY_UNAVAILABLE' using errcode='55000'; end if;
  v_group:=(inv.header_snapshot_json#>>'{meta,source_group_id}')::uuid;
  if p_binding_ids is null then
    select array_agg(id order by id) into v_ids from public.weekly_source_invoice_line_bindings where invoice_id=inv.id and state='CURRENT';
  else
    if cardinality(p_binding_ids)=0 or array_position(p_binding_ids,null::uuid) is not null then
      raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_AUTHORITY_UNAVAILABLE' using errcode='55000'; end if;
    select array_agg(distinct id order by id) into v_ids from unnest(p_binding_ids) id;
  end if;
  if v_ids is null or cardinality(v_ids)=0 then return jsonb_build_object('allowed',false); end if;
  -- CURRENT proves new edit admission. A sealed existing adjustment can retain
  -- its exact SUPERSEDED binding history after an ordinary Source move; it
  -- never follows the movement to another invoice or chooses a new tax rate.
  select count(*) into v_count from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement on movement.id=binding.billing_movement_id
    join public.weekly_source_final_revisions revision on revision.id=binding.original_final_revision_id and revision.id=movement.final_revision_id
    join public.weekly_source_cycles cycle on cycle.id=binding.original_cycle_id and cycle.id=revision.source_cycle_id
    join public.weekly_source_rule_set_versions rules on rules.id=revision.rule_set_version_id
    where binding.id=any(v_ids) and binding.invoice_id=inv.id and binding.state in('CURRENT','SUPERSEDED')
      and binding.client_id=inv.client_id and movement.actual_client_id=inv.client_id and cycle.source_group_id=v_group
      and rules.values_json->>'invoice_sender'='CLIENT_SELF_BILL'
      and rules.values_json->>'negative_adjustment_policy'='NEGATIVE_ADJUSTMENT_LINE';
  if v_count<>cardinality(v_ids) then return jsonb_build_object('allowed',false); end if;
  select count(distinct movement.vat_rate_pct),count(*) filter(where movement.vat_rate_pct is null),min(movement.vat_rate_pct)
    into v_rates,v_null_rates,v_rate from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement on movement.id=binding.billing_movement_id
    where binding.id=any(v_ids) and movement.source_line_kind<>'INVOICE_VAT_ROUNDING';
  if v_rates<>1 or v_null_rates<>0 or v_rate is null or v_rate<0 then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_VAT_UNAVAILABLE' using errcode='55000'; end if;
  select jsonb_agg(jsonb_build_object('binding_id',binding.id,'movement_id',movement.id,
      'final_revision_id',revision.id,'source_cycle_id',cycle.id,'manifest_hash',encode(binding.manifest_hash,'hex'),
      'rule_set_version_id',rules.id,'rule_values_sha256',rules.values_sha256,'vat_rate_pct',movement.vat_rate_pct) order by binding.id),
    array_agg(distinct rules.id order by rules.id) into v_records,v_versions
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement on movement.id=binding.billing_movement_id
    join public.weekly_source_final_revisions revision on revision.id=binding.original_final_revision_id
    join public.weekly_source_cycles cycle on cycle.id=binding.original_cycle_id
    join public.weekly_source_rule_set_versions rules on rules.id=revision.rule_set_version_id where binding.id=any(v_ids);
  v_payload:=jsonb_build_object('schema_version','WEEKLY_SOURCE_INVOICE_ADJUSTMENT_AUTHORITY_V1','allowed',true,
    'invoice_id',inv.id,'client_id',inv.client_id,'source_group_id',v_group,'binding_ids',to_jsonb(v_ids),
    'rule_set_version_ids',to_jsonb(v_versions),'vat_rate_pct',v_rate,'bound_movements',v_records);
  return v_payload||jsonb_build_object('authority_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_AUTHORITY_V1',v_payload),'hex'));
end;
$function$;
alter function private.weekly_source_invoice_adjustment_authority_v1(uuid,uuid[]) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_invoice_adjustment_authority_v1(uuid,uuid[]) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_invoice_adjustment_line_valid_v1(p_invoice_line_id uuid,p_invoice_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare line public.invoice_lines%rowtype; v_authority jsonb; v_actual jsonb; v_ids uuid[]; v_meta jsonb;
begin
  select * into line from public.invoice_lines where id=p_invoice_line_id and invoice_id=p_invoice_id;
  if not found or line.timesheet_id is not null or line.booking_id is not null or line.source_key not like 'ADJ:%'
    or line.meta_json->>'line_type' is distinct from 'ADJUSTMENT' or line.total_pay_ex_vat is distinct from 0
    or line.total_charge_ex_vat is null or line.total_charge_ex_vat>=0 or line.margin_ex_vat is distinct from line.total_charge_ex_vat
    or (line.hours_day,line.hours_night,line.hours_sat,line.hours_sun,line.hours_bh) is distinct from (0::numeric,0::numeric,0::numeric,0::numeric,0::numeric)
    or (line.pay_day,line.pay_night,line.pay_sat,line.pay_sun,line.pay_bh,line.charge_day,line.charge_night,line.charge_sat,line.charge_sun,line.charge_bh)
      is distinct from (null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,null::numeric)
    or line.vat_amount is null or line.vat_rate_pct is null
    or line.total_inc_vat is distinct from round(line.total_charge_ex_vat+line.vat_amount,2)
    or line.meta_json ? 'credited_work_event_id' then return false; end if;
  v_authority:=line.meta_json->'weekly_source_adjustment_authority';
  if jsonb_typeof(v_authority) is distinct from 'object' or jsonb_typeof(v_authority->'binding_ids') is distinct from 'array' then return false; end if;
  select array_agg(value::uuid order by value::uuid) into v_ids from jsonb_array_elements_text(v_authority->'binding_ids') value;
  v_actual:=private.weekly_source_invoice_adjustment_authority_v1(p_invoice_id,v_ids);
  v_meta:=line.meta_json;
  if exists(select 1 from jsonb_object_keys(v_meta) k where k not in(
    'line_type','client_token','description','amount_ex_vat','vat_rate_pct','vat_amount','vat_chargeable',
    'vat_overridden','weekly_source_adjustment_authority')) then return false; end if;
  return coalesce(v_actual->>'allowed'='true' and v_actual=v_authority
    and line.vat_rate_pct=(v_actual->>'vat_rate_pct')::numeric
    and line.source_key='ADJ:'||(v_meta->>'client_token') and line.description=v_meta->>'description'
    and line.total_charge_ex_vat=(v_meta->>'amount_ex_vat')::numeric and line.vat_amount=(v_meta->>'vat_amount')::numeric
    and jsonb_typeof(v_meta->'vat_overridden')='boolean'
    and jsonb_typeof(v_meta->'vat_chargeable')='boolean'
    and (v_meta->>'vat_chargeable')::boolean=(line.vat_rate_pct<>0)
    and ((v_meta->>'vat_overridden')::boolean or line.vat_amount=public._inv_round2(line.total_charge_ex_vat*line.vat_rate_pct/100)),false);
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;
end;
$function$;
alter function private.weekly_source_invoice_adjustment_line_valid_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_invoice_adjustment_line_valid_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- Used only to exempt this adjustment-only branch from the existing generic
-- import-correction financial-edit prohibition. The actual writer rechecks
-- admission and all line facts after the native invoice UPDATE lock.
create or replace function private.weekly_source_invoice_adjustment_payload_admit_v1(p_invoice_id uuid,p_payload jsonb)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
begin
  if jsonb_typeof(p_payload) is distinct from 'object' then return false; end if;
  if exists(select 1 from jsonb_object_keys(p_payload) k where k not in('add_adjustments','remove_invoice_line_ids')) then return false; end if;
  return coalesce(private.weekly_source_invoice_adjustment_authority_v1(p_invoice_id,null)->>'allowed'='true',false);
end;
$function$;
alter function private.weekly_source_invoice_adjustment_payload_admit_v1(uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_invoice_adjustment_payload_admit_v1(uuid,jsonb) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_invoice_adjustments_apply_v1(p_invoice_id uuid,p_payload jsonb,p_actor_user_id uuid)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare inv public.invoices%rowtype; line public.invoice_lines%rowtype; v_authority jsonb; item jsonb; v_rate numeric;
  v_ex numeric; v_vat numeric; v_token text; v_description text; v_meta jsonb; v_ids uuid[]; v_id uuid; v_result jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if not exists(select 1 from public.tms_users where id=p_actor_user_id and is_active and lower(btrim(role))='admin') then
    raise exception 'WEEKLY_SOURCE_OFFICE_ADMIN_REQUIRED' using errcode='42501'; end if;
  perform public._ctms_assert_invoice_mutable_draft_v1(p_invoice_id,'INVOICE_APPLY_EDITS',true);
  select * into strict inv from public.invoices where id=p_invoice_id for update;
  v_authority:=private.weekly_source_invoice_adjustment_authority_v1(p_invoice_id,null);
  if v_authority->>'allowed' is distinct from 'true' then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENTS_NOT_ALLOWED' using errcode='55000'; end if;
  if jsonb_typeof(p_payload) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_payload) k
    where k not in('add_adjustments','remove_invoice_line_ids')) then
    raise exception 'WEEKLY_SOURCE_INVOICE_EDIT_ADJUSTMENT_ONLY' using errcode='22023'; end if;
  if p_payload ? 'remove_invoice_line_ids' then
    if jsonb_typeof(p_payload->'remove_invoice_line_ids') is distinct from 'array' then
      raise exception 'WEEKLY_SOURCE_INVOICE_EDIT_ADJUSTMENT_ONLY' using errcode='22023'; end if;
    for v_id in select value::uuid from jsonb_array_elements_text(p_payload->'remove_invoice_line_ids') value loop
      select * into strict line from public.invoice_lines where id=v_id and invoice_id=p_invoice_id for update;
      if private.weekly_source_invoice_adjustment_line_valid_v1(line.id,p_invoice_id) is distinct from true then
        raise exception 'WEEKLY_SOURCE_INVOICE_EDIT_ADJUSTMENT_ONLY' using errcode='22023'; end if;
      delete from public.invoice_lines where id=line.id;
    end loop;
  end if;
  v_rate:=(v_authority->>'vat_rate_pct')::numeric;
  if p_payload ? 'add_adjustments' then
    if jsonb_typeof(p_payload->'add_adjustments') is distinct from 'array' then
      raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_INVALID' using errcode='22023'; end if;
    for item in select value from jsonb_array_elements(p_payload->'add_adjustments') loop
      if jsonb_typeof(item) is distinct from 'object' or exists(select 1 from jsonb_object_keys(item) k
        where k not in('client_token','description','amount_ex_vat','vat_amount','credited_work_event_id')) then
        raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_INVALID' using errcode='22023'; end if;
      if item ? 'credited_work_event_id' then
        raise exception 'WEEKLY_SOURCE_CREDITED_SHIFT_AUTHORITY_UNAVAILABLE' using errcode='55000'; end if;
      v_token:=btrim(item->>'client_token'); v_description:=btrim(item->>'description');
      if coalesce(v_token,'') !~ '^[A-Za-z0-9:_-]{1,200}$' or length(coalesce(v_description,'')) not between 1 and 1000
        or coalesce(item->>'amount_ex_vat','') !~ '^-[0-9]+([.][0-9]{1,2})?$'
        or (item ? 'vat_amount' and coalesce(item->>'vat_amount','') !~ '^[+-]?[0-9]+([.][0-9]{1,2})?$') then
        raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_INVALID' using errcode='22023'; end if;
      v_ex:=(item->>'amount_ex_vat')::numeric;
      v_vat:=case when item ? 'vat_amount' then (item->>'vat_amount')::numeric else public._inv_round2(v_ex*v_rate/100) end;
      if v_ex>=0 or abs(v_ex)>9999999999.99 or abs(v_vat)>9999999999.99 then
        raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_INVALID' using errcode='22023'; end if;
      v_meta:=jsonb_build_object('line_type','ADJUSTMENT','client_token',v_token,'description',v_description,
        'amount_ex_vat',v_ex,'vat_rate_pct',v_rate,'vat_amount',v_vat,'vat_chargeable',v_rate<>0,
        'vat_overridden',item ? 'vat_amount','weekly_source_adjustment_authority',v_authority);
      select * into line from public.invoice_lines where invoice_id=p_invoice_id and source_key='ADJ:'||v_token;
      if found then
        if line.meta_json is distinct from v_meta or private.weekly_source_invoice_adjustment_line_valid_v1(line.id,p_invoice_id) is distinct from true then
          raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENT_REPLAY_CONFLICT' using errcode='23505'; end if;
      else
        insert into public.invoice_lines(invoice_id,timesheet_id,booking_id,description,hours_day,hours_night,hours_sat,hours_sun,hours_bh,
          pay_day,pay_night,pay_sat,pay_sun,pay_bh,charge_day,charge_night,charge_sat,charge_sun,charge_bh,
          total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,meta_json,source_key)
          values(p_invoice_id,null,null,v_description,0,0,0,0,0,null,null,null,null,null,null,null,null,null,null,
            0,v_ex,v_ex,v_rate,v_vat,round(v_ex+v_vat,2),v_meta,'ADJ:'||v_token);
      end if;
    end loop;
  end if;
  perform public.invoice_recompute_totals(p_invoice_id);
  perform private.weekly_source_invoice_allocation_assert_v1(p_invoice_id);
  perform public._audit_insert('invoices',p_invoice_id::text,'INVOICE_ADJUSTMENTS_APPLIED',null,
    jsonb_build_object('source','WEEKLY_FINAL_SOURCE','payload',p_payload),'Trust credit',p_actor_user_id);
  select jsonb_build_object('invoice_id',id,'status',status,'subtotal_ex_vat',subtotal_ex_vat,'vat_amount',vat_amount,'total_inc_vat',total_inc_vat,
    'document_revision',document_revision,'document_state',document_state,'preview_document_version_id',preview_document_version_id,
    'active_document_operation_id',active_document_operation_id,'issue_state',issue_state,'active_issue_operation_id',active_issue_operation_id,
    'reference_updates_applied',0,'timesheet_location_updates_applied',0,'timesheet_source_changed',false,
    'source_edit_queue_contract',null,'changed_timesheet_ids','[]'::jsonb,'changed_timesheet_revisions','[]'::jsonb,
    'source_edit_preexisting_preview',false,'invoice_replacement_required',false,'accepted_operations','[]'::jsonb,'document_queue_requested',false)
    into v_result from public.invoices where id=p_invoice_id;
  return v_result;
end;
$function$;
alter function private.weekly_source_invoice_adjustments_apply_v1(uuid,jsonb,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_invoice_adjustments_apply_v1(uuid,jsonb,uuid) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.invoice_apply_edits(p_invoice_id uuid, p_payload jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();
  v_anchor_ymd date := (now() at time zone 'Europe/London')::date;


-- =====================================================
-- DEBUG (invoice_debug): single audit row per RPC call
-- =====================================================
v_invoice_debug boolean := false;
v_dbg_started_at timestamptz := now();
v_dbg_steps jsonb := '[]'::jsonb;
v_dbg_sqlstate text := null;
v_dbg_error text := null;
v_dbg_stats jsonb := '{}'::jsonb;


v_dbg_lines_deleted int := 0;
v_dbg_timesheets_unlocked int := 0;
v_dbg_seg_add_refs int := 0;
v_dbg_seg_remove_refs int := 0;
v_dbg_seg_tsfins int := 0;
v_dbg_seg_timesheets_rebuilt int := 0;
v_dbg_seg_timesheets_removed int := 0;
v_dbg_add_timesheets_found int := 0;
v_dbg_add_timesheets_skipped int := 0;

v_rc int := 0;

  v_inv record;
  v_week_start date;
  v_week_end date;

  v_remove_ids uuid[];
  v_add_ts_ids uuid[];

-- segment move payload (explicit segment add/remove)
v_remove_seg_refs jsonb;
v_add_seg_refs jsonb;
v_has_seg_ops boolean := false;
v_refresh_hr_cache boolean := false;
v_seg_tsfin_ids uuid[] := array[]::uuid[];
v_seg_ts_ids uuid[] := array[]::uuid[];
v_seg_refs_to_lock jsonb := '[]'::jsonb;
v_ref jsonb;
v_tsfin_id uuid;
v_seg_id text;
v_has_additional boolean;
v_has_expense_or_mileage boolean;

  -- reference updates (refs-to-issue)
  v_reference_updates jsonb;
  v_refupd jsonb;
  v_refupd_ts_id uuid;
  v_refupd_count int := 0;
  v_refupd_applied int := 0;
  v_refupd_set_refnum boolean;
  v_refupd_set_dayrefs boolean;
  v_refupd_set_sched boolean;
  v_refupd_dayrefs jsonb;
  v_refupd_sched jsonb;
  v_refupd_refnum text;

  -- timesheet hospital / ward source edits
  v_location_updates jsonb;
  v_location_update jsonb;
  v_location_ts_id uuid;
  v_location_count int := 0;
  v_location_applied int := 0;
  v_location_set_hospital boolean;
  v_location_set_ward boolean;
  v_location_hospital_norm text;
  v_location_ward_norm text;
  v_location_ts_ids uuid[] := array[]::uuid[];
  -- Source-edit contract state. Reference and location inputs are merged into
  -- one desired row per timesheet, then written by one statement so the
  -- statement-level invalidation trigger advances each source exactly once.
  v_source_updates_map jsonb := '{}'::jsonb;
  v_source_update jsonb;
  v_source_edit_key text;
  v_source_expected_revision bigint;
  v_source_changed_ts_ids uuid[] := array[]::uuid[];
  v_source_changed_revisions jsonb := '[]'::jsonb;
  v_source_edit_requested boolean := false;
  v_allowed_reference_fields text[]:=array[
    'timesheet_id','expected_document_revision','reference_number',
    'day_references_json','actual_schedule_json'];
  v_allowed_location_fields text[]:=array[
    'timesheet_id','expected_document_revision','hospital_norm','ward_norm'];
  v_allowed_reference_segment_fields text[]:=array[
    'segment_id','date','start_utc','end_utc','start','end','ref_num',
    'source_system'];
  v_source_unsupported_field text;
  v_source_financial_id uuid;
  v_source_mode text;
  v_source_ib jsonb;
  v_source_payload_schedule jsonb;
  v_source_canonical_schedule jsonb;
  v_source_new_segments jsonb;
  v_source_segment_updates jsonb;
  v_source_segment_reference_changed boolean;
  v_source_timesheet_row_changed boolean;
  v_source_match_count integer;
  v_source_match_segment jsonb;
  v_source_payload_segment jsonb;
  v_source_current_segment jsonb;
  v_source_payload_ord bigint;
  v_source_start timestamptz;
  v_source_end timestamptz;
  v_source_marker_rows jsonb:='{}'::jsonb;
  v_source_marker jsonb:='{}'::jsonb;
  v_source_edit_preexisting_preview boolean := false;
  v_source_edit_invoice_replacement_required boolean := false;
  v_pre_edit_invoice_revision bigint;
  v_pre_edit_preview_document_version_id uuid;
  v_pre_edit_active_document_operation_id uuid;
  v_expected_command_count int := 0;
  v_operation_result jsonb;
  v_operation_id uuid;
  v_document_version_id uuid;
  v_command_no int;
  v_command_type text;
  v_operation_status text;
  v_operation_input jsonb;
  v_validated_operations jsonb := '[]'::jsonb;
  v_document_commands jsonb := '[]'::jsonb;
  v_started_operations jsonb := '[]'::jsonb;

  -- reference update side-effects (meta refresh / segment ref sync)
  v_refupd_ts_ids uuid[] := array[]::uuid[];
  v_refupd_ts_ids_distinct uuid[] := array[]::uuid[];
  v_refupd_meta_rows_updated int := 0;
  v_refupd_tsfin_rows_updated int := 0;
  v_refupd_tsfin_segments_updated int := 0;
  v_refupd_invoice_fallback_invalidated boolean := false;

  -- temp vars for reference-derived meta and optional tsfin segment ref sync
  v_ref_ts_id uuid;
  v_ref_ts record;
  v_ref_schedule_refs jsonb := '[]'::jsonb;
  v_ref_schedule_refs_distinct jsonb := '[]'::jsonb;
  v_ref_sched_map jsonb := '{}'::jsonb;
  v_ref_seen_keys jsonb := '{}'::jsonb;
  v_ref_sched_key text;
  v_ref_sched_ref text;
  v_ref_tsfin_id uuid;
  v_ref_ib jsonb;
  v_ref_new_segments jsonb := '[]'::jsonb;
  v_ref_seg_obj jsonb;
  v_ref_seg_start text;
  v_ref_seg_end text;
    v_ref_seg_id text;
v_ref_seg_cur_ref text;
  v_ref_seg_new_ref text;
  v_ref_seg_has_update boolean := false;
  v_ref_seg_updates_this_ts int := 0;
  v_ref_seg_matches_this_ts int := 0;

  -- audit (history) accumulators (NOT debug-only)
  v_hist_adj jsonb := '[]'::jsonb;
  v_hist_seg_add jsonb := '[]'::jsonb;
  v_hist_seg_remove jsonb := '[]'::jsonb;
  v_hist_lines_removed jsonb := '[]'::jsonb;
  v_hist_add_ts jsonb := '[]'::jsonb;

  -- contract week status touch set
  v_cw_ts_ids uuid[] := array[]::uuid[];

  v_ts_ids_touched uuid[] := array[]::uuid[];
  -- FIX: timesheets fully removed from this invoice (no remaining invoice_lines) should be unlocked
  v_ts_ids_fully_removed uuid[] := array[]::uuid[];

  v_vat_chargeable boolean := true;
  v_vat_rate numeric := 0;

  -- adjustments
  adj jsonb;
  v_adj_token text;
  v_adj_desc text;
  v_adj_ex numeric;
  v_adj_vat numeric;
  v_adj_inc numeric;
  v_adj_source_key text;
  v_meta jsonb;

  -- timesheet loop
  tsid uuid;
  snap record;
  ts record;
  pc record;
  contract_id uuid;
  v_settings_authority jsonb;
  c_daily_calc boolean := false;
  c_bucket_labels jsonb := null;
  c_role text := null;
  c_display_site text := null;
  c_ward_hint text := null;

  -- segment filtering
  v_seg jsonb;
  segments jsonb := '[]'::jsonb;
  seg_target date;
  seg_date text;
  natural_start date;
  seg_locked text;
  seg_ref text;

  -- aggregation for weekly line
  h_day numeric; h_night numeric; h_sat numeric; h_sun numeric; h_bh numeric;
  pay_ex numeric; chg_ex numeric; margin_ex numeric;
  vat_amt numeric; inc_amt numeric;
  line_desc text;
  v_source_key text;
  v_exact_timesheet_document_r2_key text;

  -- daily aggregation record
  r_day record;

  -- segment refs for locking
  seg_refs jsonb := '[]'::jsonb;

  -- additional units
  kv record;
  ex jsonb;
  code text;
  unit_count numeric;
  bucket_name text;
  unit_name text;

  -- expenses notes
  v_note_travel text;
  v_note_accom text;
  v_note_other text;

  -- recompute totals
  v_new_ex numeric := 0;
  v_new_vat numeric := 0;
  v_new_inc numeric := 0;

  -- header meta counters (keep header_snapshot_json.meta in sync with current invoice state)
  v_hdr_ts_count_lines int := 0;
  v_hdr_ts_count_seglocks int := 0;
  v_hdr_seg_locked_count int := 0;
  v_hdr_meta_timesheet_count int := 0;
  v_hdr_meta_segment_count int := 0;

  v_manifest jsonb;
  v_correction_placement_only boolean:=false;
  v_correction_placement_ts_id uuid:=null;
  v_correction_placement_scope jsonb:='{}'::jsonb;
  v_correction_placement_states jsonb:='[]'::jsonb;
  v_service boolean:=coalesce(auth.role(),'')='service_role';
  v_actor_role text;
begin

  if not v_service
     and(auth.uid() is null or auth.uid() is distinct from p_actor_user_id) then
    raise exception using errcode='42501',
      message='AUTHENTICATED_ACTOR_MISMATCH';
  end if;
  select lower(btrim(coalesce(u.role,''))) into v_actor_role
  from public.tms_users u
  where u.id=p_actor_user_id and u.is_active;
  if(not found or v_actor_role<>'admin') and not v_service then
    raise exception using errcode='42501',
      message='INVOICE_ADMINISTRATOR_PERMISSION_REQUIRED';
  end if;

  perform public._ctms_assert_invoice_mutable_draft_v1(
    p_invoice_id,'INVOICE_APPLY_EDITS',true
  );
  v_correction_placement_only:=
    jsonb_typeof(coalesce(p_payload,'{}'::jsonb))='object'
    and not exists(select 1 from jsonb_object_keys(coalesce(p_payload,'{}'::jsonb)) payload_key
      where payload_key not in ('remove_invoice_line_ids','add_timesheet_ids'))
    and coalesce(jsonb_array_length(case when jsonb_typeof(p_payload->'remove_invoice_line_ids')='array'
      then p_payload->'remove_invoice_line_ids' else '[]'::jsonb end),0)
      +coalesce(jsonb_array_length(case when jsonb_typeof(p_payload->'add_timesheet_ids')='array'
      then p_payload->'add_timesheet_ids' else '[]'::jsonb end),0)=1
    and (
      (case when coalesce(p_payload#>>'{remove_invoice_line_ids,0}','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then exists(
          select 1 from public.invoice_lines placement_line
          where placement_line.id=(p_payload#>>'{remove_invoice_line_ids,0}')::uuid
            and placement_line.invoice_id=p_invoice_id
            and coalesce((public._ctms_import_correction_classify_v1(placement_line.timesheet_id)
              ->>'is_import_authoritative_correction')::boolean,false)) else false end)
      or
      (case when coalesce(p_payload#>>'{add_timesheet_ids,0}','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        coalesce((public._ctms_import_correction_classify_v1(
          (p_payload#>>'{add_timesheet_ids,0}')::uuid)->>'is_import_authoritative_correction')::boolean,false)
        else false end)
    );
  if public._ctms_invoice_payload_has_financial_edit_v1(p_payload)
     and not v_correction_placement_only
     and not private.weekly_source_invoice_adjustment_payload_admit_v1(p_invoice_id,p_payload)
     and exists (
       select 1 from public.invoice_lines il
       where il.invoice_id=p_invoice_id and il.timesheet_id is not null
         and coalesce((public._ctms_import_correction_classify_v1(il.timesheet_id)
           ->>'is_import_authoritative_correction')::boolean,false)
     ) then
    raise exception 'IMPORT_CORRECTION_INVOICE_FINANCIAL_EDIT_FORBIDDEN'
      using errcode='P0001',detail=jsonb_build_object('invoice_id',p_invoice_id)::text;
  end if;
-- Load invoice_debug flag (safe even if column not yet present)
begin
  select coalesce(sd.invoice_debug, false)
  into v_invoice_debug
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;
exception when undefined_column then
  v_invoice_debug := false;
end;

if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','start',
      'at_utc', public._inv_iso_utc(v_dbg_started_at),
      'invoice_id', p_invoice_id::text
    )
  );
end if;

  if p_invoice_id is null then
    raise exception 'invoice_id is required';
  end if;

  select *
  into v_inv
  from public.invoices i
  where i.id = p_invoice_id
  for update
  limit 1;

  if not found then
    raise exception 'Invoice not found';
  end if;

  -- Editable gate: DRAFT/ON_HOLD and unpaid
  if v_inv.status::text not in ('DRAFT','ON_HOLD') then
    raise exception 'Invoice is not editable (status=%)', v_inv.status::text;
  end if;

  if v_inv.paid_at_utc is not null then
    raise exception 'Invoice is not editable (already paid)';
  end if;



if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','invoice_loaded',
      'status', coalesce(v_inv.status::text,''),
      'paid_at_utc', case when v_inv.paid_at_utc is null then null else public._inv_iso_utc(v_inv.paid_at_utc) end
    )
  );
end if;

  -- F4: exact new Source header plus frozen S15 only. All ordinary code below
  -- remains the native owner, including older self-bill and NHSP refusal.
  if v_inv.header_snapshot_json->>'schema_version'='WEEKLY_SOURCE_SELF_BILL_INVOICE_V1'
     and v_inv.header_snapshot_json#>>'{meta,source}'='WEEKLY_FINAL_SOURCE' then
    if private.weekly_source_invoice_adjustment_authority_v1(p_invoice_id,null)->>'allowed'='true' then
      return private.weekly_source_invoice_adjustments_apply_v1(p_invoice_id,p_payload,p_actor_user_id);
    end if;
    if p_payload ? 'add_adjustments' or p_payload ? 'remove_invoice_line_ids' then
      raise exception 'WEEKLY_SOURCE_INVOICE_ADJUSTMENTS_NOT_ALLOWED' using errcode='55000';
    end if;
  end if;

  -- Require invoice_week_start in header_snapshot_json.meta
  if v_inv.header_snapshot_json is null
     or btrim(coalesce(v_inv.header_snapshot_json #>> '{meta,invoice_week_start}','')) = ''
     or (v_inv.header_snapshot_json #>> '{meta,invoice_week_start}') !~ '^\d{4}-\d{2}-\d{2}$'
  then
    raise exception 'Invoice header_snapshot_json.meta.invoice_week_start is required for edits';
  end if;

  v_week_start := (v_inv.header_snapshot_json #>> '{meta,invoice_week_start}')::date;
  v_week_end := (v_week_start + interval '6 days')::date;


if v_invoice_debug then
  v_dbg_steps := v_dbg_steps || jsonb_build_array(
    jsonb_build_object(
      'step','invoice_week_loaded',
      'invoice_week_start', v_week_start::text,
      'invoice_week_end', v_week_end::text
    )
  );
end if;

  -- VAT settings from invoice snapshot
  if jsonb_typeof(v_inv.header_snapshot_json->'vat_chargeable') = 'boolean' then
    v_vat_chargeable := (v_inv.header_snapshot_json->>'vat_chargeable')::boolean;
  else
    v_vat_chargeable := true;
  end if;

  if (v_inv.header_snapshot_json ? 'applied_vat_rate_pct') then
    begin
      v_vat_rate := (v_inv.header_snapshot_json->>'applied_vat_rate_pct')::numeric;
    exception when others then
      v_vat_rate := 0;
    end;
  else
    v_vat_rate := 0;
  end if;

  if v_vat_chargeable = false then
    v_vat_rate := 0;
  end if;

  -- Parse payload arrays
  v_remove_ids := null;
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'remove_invoice_line_ids') then
    select array_agg((x)::uuid)
    into v_remove_ids
    from jsonb_array_elements_text(coalesce(p_payload->'remove_invoice_line_ids','[]'::jsonb)) x
    where nullif(btrim(coalesce(x,'')),'') is not null;
  end if;

  v_add_ts_ids := null;
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_timesheet_ids') then
    select array_agg((x)::uuid)
    into v_add_ts_ids
    from jsonb_array_elements_text(coalesce(p_payload->'add_timesheet_ids','[]'::jsonb)) x
    where nullif(btrim(coalesce(x,'')),'') is not null;
  end if;

  IF v_correction_placement_only THEN
    IF COALESCE(cardinality(v_remove_ids),0)=1 THEN
      SELECT il.timesheet_id INTO v_correction_placement_ts_id
      FROM public.invoice_lines il
      WHERE il.id=v_remove_ids[1] AND il.invoice_id=p_invoice_id
      FOR UPDATE;
      IF v_correction_placement_ts_id IS NULL
         OR COALESCE((public._ctms_import_correction_classify_v1(v_correction_placement_ts_id)
             ->>'is_import_authoritative_correction')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_TARGET_INVALID' USING ERRCODE='P0001';
      END IF;
      v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
        v_correction_placement_ts_id,null::uuid,p_actor_user_id,true,100);
      IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
         OR v_correction_placement_scope->>'placement_state' NOT IN (
           'COMPLETE_SAME_INVOICE','COMPLETE_SPLIT_INVOICES') THEN
        RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_MOVE_NOT_STARTABLE'
          USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
      END IF;
    ELSIF COALESCE(cardinality(v_add_ts_ids),0)=1 THEN
      v_correction_placement_ts_id:=v_add_ts_ids[1];
      IF COALESCE((public._ctms_import_correction_classify_v1(v_correction_placement_ts_id)
             ->>'is_import_authoritative_correction')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_TARGET_INVALID' USING ERRCODE='P0001';
      END IF;
      v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
        v_correction_placement_ts_id,p_invoice_id,p_actor_user_id,true,100);
      IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
         OR v_correction_placement_scope->>'placement_state'<>'INCOMPLETE_MOVE'
         OR v_correction_placement_scope->>'missing_member_kind' IS DISTINCT FROM
              (SELECT t.correction_kind FROM public.timesheets t
               WHERE t.timesheet_id=v_correction_placement_ts_id)
         OR COALESCE((v_correction_placement_scope->>'target_appendable')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_TARGET_INVALID'
          USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
      END IF;
    ELSE
      RAISE EXCEPTION 'IMPORT_CORRECTION_PLACEMENT_ONLY_PAYLOAD_INVALID' USING ERRCODE='22023';
    END IF;
  END IF;


-- Parse segment move payloads (tsfin_id + segment_id)
v_remove_seg_refs := null;
if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'remove_segment_refs') then
  v_remove_seg_refs := coalesce(p_payload->'remove_segment_refs','[]'::jsonb);
  if jsonb_typeof(v_remove_seg_refs) <> 'array' then
    v_remove_seg_refs := '[]'::jsonb;
  end if;
end if;

v_add_seg_refs := null;
if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_segment_refs') then
  v_add_seg_refs := coalesce(p_payload->'add_segment_refs','[]'::jsonb);
  if jsonb_typeof(v_add_seg_refs) <> 'array' then
    v_add_seg_refs := '[]'::jsonb;
  end if;
end if;



-- Parse and strictly validate source edits. The expected source revision is
-- mandatory because values displayed by an older modal must never overwrite a
-- newer timesheet revision.
v_reference_updates := null;
if p_payload is not null and jsonb_typeof(p_payload)='object'
   and p_payload ? 'reference_updates' then
  v_reference_updates:=p_payload->'reference_updates';
  if jsonb_typeof(v_reference_updates)<>'array' then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
      detail=jsonb_build_object('field','reference_updates','reason','ARRAY_REQUIRED')::text;
  end if;
  v_refupd_count:=jsonb_array_length(v_reference_updates);
  for v_refupd in select value from jsonb_array_elements(v_reference_updates) value loop
    if v_refupd is not null and jsonb_typeof(v_refupd)='object' then
      select min(field_name) into v_source_unsupported_field
      from jsonb_object_keys(v_refupd) field_name
      where not (field_name=any(v_allowed_reference_fields));
      if v_source_unsupported_field is not null then
        raise exception using errcode='22023',
          message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
          detail=jsonb_build_object(
            'field','reference_updates','reason','UNSUPPORTED_FIELD',
            'unsupported_field',v_source_unsupported_field)::text;
      end if;
    end if;
    if v_refupd is null or jsonb_typeof(v_refupd)<>'object'
       or nullif(btrim(coalesce(v_refupd->>'timesheet_id','')),'') is null
       or coalesce(v_refupd->>'timesheet_id','') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       or coalesce(v_refupd->>'expected_document_revision','') !~ '^[1-9][0-9]*$'
       or not (
         v_refupd ? 'reference_number'
         or v_refupd ? 'day_references_json'
         or v_refupd ? 'actual_schedule_json'
       )
       or (
         v_refupd ? 'reference_number'
         and jsonb_typeof(v_refupd->'reference_number') not in('string','null')
       )
       or (
         v_refupd ? 'day_references_json'
         and jsonb_typeof(v_refupd->'day_references_json') not in('object','null')
       )
       or (
         v_refupd ? 'actual_schedule_json'
         and jsonb_typeof(v_refupd->'actual_schedule_json') not in('array','null')
       )
    then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
        detail=jsonb_build_object('field','reference_updates','reason','INVALID_ITEM')::text;
    end if;
    v_source_edit_key:=lower(v_refupd->>'timesheet_id');
    if v_source_updates_map ? v_source_edit_key then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_DUPLICATE_TIMESHEET',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'field','reference_updates')::text;
    end if;
    v_source_updates_map:=jsonb_set(
      v_source_updates_map,array[v_source_edit_key],
      jsonb_build_object(
        'timesheet_id',v_source_edit_key,
        'expected_document_revision',(v_refupd->>'expected_document_revision')::bigint,
        'has_reference_number',v_refupd ? 'reference_number',
        'reference_number',case when v_refupd ? 'reference_number'
          then to_jsonb(nullif(btrim(coalesce(v_refupd->>'reference_number','')),''))
          else 'null'::jsonb end,
        'has_day_references_json',v_refupd ? 'day_references_json',
        'day_references_json',case
          when not (v_refupd ? 'day_references_json') then 'null'::jsonb
          when jsonb_typeof(v_refupd->'day_references_json')='null' then 'null'::jsonb
          else v_refupd->'day_references_json' end,
        'has_actual_schedule_json',v_refupd ? 'actual_schedule_json',
        'actual_schedule_json',case
          when not (v_refupd ? 'actual_schedule_json') then 'null'::jsonb
          when jsonb_typeof(v_refupd->'actual_schedule_json')='null' then 'null'::jsonb
          else v_refupd->'actual_schedule_json' end,
        'has_hospital_norm',false,
        'has_ward_norm',false),
      true);
  end loop;
end if;

-- Hospital/ward edits merge into the same desired source row. A source may
-- appear once in each array, but both items must carry the same revision.
v_location_updates:=null;
if p_payload is not null and jsonb_typeof(p_payload)='object'
   and p_payload ? 'timesheet_location_updates' then
  v_location_updates:=p_payload->'timesheet_location_updates';
  if jsonb_typeof(v_location_updates)<>'array' then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
      detail=jsonb_build_object('field','timesheet_location_updates','reason','ARRAY_REQUIRED')::text;
  end if;
  v_location_count:=jsonb_array_length(v_location_updates);
  for v_location_update in select value from jsonb_array_elements(v_location_updates) value loop
    if v_location_update is not null and jsonb_typeof(v_location_update)='object' then
      select min(field_name) into v_source_unsupported_field
      from jsonb_object_keys(v_location_update) field_name
      where not (field_name=any(v_allowed_location_fields));
      if v_source_unsupported_field is not null then
        raise exception using errcode='22023',
          message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
          detail=jsonb_build_object(
            'field','timesheet_location_updates','reason','UNSUPPORTED_FIELD',
            'unsupported_field',v_source_unsupported_field)::text;
      end if;
    end if;
    if v_location_update is null or jsonb_typeof(v_location_update)<>'object'
       or nullif(btrim(coalesce(v_location_update->>'timesheet_id','')),'') is null
       or coalesce(v_location_update->>'timesheet_id','') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       or coalesce(v_location_update->>'expected_document_revision','') !~ '^[1-9][0-9]*$'
       or not (v_location_update ? 'hospital_norm' or v_location_update ? 'ward_norm')
       or (
         v_location_update ? 'hospital_norm'
         and jsonb_typeof(v_location_update->'hospital_norm') not in('string','null')
       )
       or (
         v_location_update ? 'ward_norm'
         and jsonb_typeof(v_location_update->'ward_norm') not in('string','null')
       )
    then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
        detail=jsonb_build_object('field','timesheet_location_updates','reason','INVALID_ITEM')::text;
    end if;
    v_source_edit_key:=lower(v_location_update->>'timesheet_id');
    v_source_expected_revision:=(v_location_update->>'expected_document_revision')::bigint;
    if v_source_updates_map ? v_source_edit_key
       and (
         coalesce((v_source_updates_map#>>
           array[v_source_edit_key,'has_hospital_norm'])::boolean,false)
         or coalesce((v_source_updates_map#>>
           array[v_source_edit_key,'has_ward_norm'])::boolean,false)
       ) then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_DUPLICATE_TIMESHEET',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'field','timesheet_location_updates')::text;
    end if;
    if v_source_updates_map ? v_source_edit_key
       and (v_source_updates_map#>>array[v_source_edit_key,'expected_document_revision'])::bigint
           is distinct from v_source_expected_revision then
      raise exception using errcode='40001',
        message='INVOICE_SOURCE_EDIT_STALE_REVISION',
        detail=jsonb_build_object('timesheet_id',v_source_edit_key,'reason','EXPECTED_REVISION_CONFLICT')::text;
    end if;
    v_source_update:=coalesce(v_source_updates_map->v_source_edit_key,
      jsonb_build_object(
        'timesheet_id',v_source_edit_key,
        'expected_document_revision',v_source_expected_revision,
        'has_reference_number',false,
        'has_day_references_json',false,
        'has_actual_schedule_json',false));
    v_source_update:=v_source_update||jsonb_build_object(
      'has_hospital_norm',v_location_update ? 'hospital_norm',
      'hospital_norm',case when v_location_update ? 'hospital_norm'
        then to_jsonb(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'hospital_norm','')),
          '[[:space:]]+',' ','g')))
        else 'null'::jsonb end,
      'has_ward_norm',v_location_update ? 'ward_norm',
      'ward_norm',case when v_location_update ? 'ward_norm'
        then to_jsonb(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'ward_norm','')),
          '[[:space:]]+',' ','g')))
        else 'null'::jsonb end);
    v_source_updates_map:=jsonb_set(v_source_updates_map,array[v_source_edit_key],v_source_update,true);
  end loop;
end if;
v_source_edit_requested:=v_source_updates_map<>'{}'::jsonb;
v_has_seg_ops :=
  (v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0)
  or (v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0);

  v_refresh_hr_cache := (coalesce(array_length(v_add_ts_ids,1),0) > 0) or coalesce(v_has_seg_ops,false);

  if v_invoice_debug then
    v_dbg_stats := v_dbg_stats || jsonb_build_object(
      'remove_invoice_line_ids_count', coalesce(array_length(v_remove_ids,1),0),
      'add_timesheet_ids_count', coalesce(array_length(v_add_ts_ids,1),0),
      'add_adjustments_count', case when p_payload is not null and jsonb_typeof(p_payload)='object' and (p_payload ? 'add_adjustments') and jsonb_typeof(p_payload->'add_adjustments')='array' then jsonb_array_length(p_payload->'add_adjustments') else 0 end,
      'remove_segment_refs_count', case when v_remove_seg_refs is null then 0 else jsonb_array_length(coalesce(v_remove_seg_refs,'[]'::jsonb)) end,
      'add_segment_refs_count', case when v_add_seg_refs is null then 0 else jsonb_array_length(coalesce(v_add_seg_refs,'[]'::jsonb)) end,
      'timesheet_location_updates_count',v_location_count,
      'has_segment_ops', v_has_seg_ops
    );
    v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','payload_parsed','stats',v_dbg_stats));
  end if;

  if v_source_edit_requested then
    -- Source edits are a narrower authority than ordinary draft edits.
    if v_inv.issued_at_utc is not null then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_ISSUED';
    end if;
    if v_inv.paid_at_utc is not null then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_PAID';
    end if;
    if v_inv.active_issue_operation_id is not null
       or upper(coalesce(v_inv.issue_state,'')) in
          ('VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
       or exists(
         select 1
         from public.invoice_operation_chunks c
         where c.chunk_type='ISSUE_INVOICE'
           and c.entity_type='INVOICE'
           and c.entity_id=p_invoice_id
           and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
       )
    then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_ISSUE_IN_PROGRESS';
    end if;

    v_pre_edit_invoice_revision:=v_inv.document_revision;
    v_pre_edit_preview_document_version_id:=v_inv.preview_document_version_id;
    v_pre_edit_active_document_operation_id:=v_inv.active_document_operation_id;

    -- Only an exact current-revision V8 preview is authoritative. Legacy PDF
    -- summary fields do not independently force or suppress replacement.
    select exists(
      select 1
      from public.invoice_document_versions dv
      left join public.invoice_operations op on op.id=dv.operation_id
      where dv.entity_type='INVOICE'
        and dv.entity_id=p_invoice_id
        and dv.purpose='DRAFT_PREVIEW'
        and dv.source_revision=v_pre_edit_invoice_revision::text
        and (
          (dv.status='READY'
            and nullif(btrim(coalesce(dv.r2_key,'')),'') is not null
            and nullif(btrim(coalesce(dv.sha256,'')),'') is not null
            and coalesce(dv.size_bytes,0)>0
            and coalesce(dv.page_count,0)>0)
          or (
            dv.id=v_pre_edit_preview_document_version_id
            and dv.status in(
              'PLANNING','WAITING_FOR_INPUTS','RENDERING',
              'ASSEMBLING','VERIFYING','READY'))
          or (
            dv.operation_id=v_pre_edit_active_document_operation_id
            and op.operation_type='BUILD_DOCUMENT'
            and op.entity_type='INVOICE'
            and op.entity_id=p_invoice_id
            and op.source_revision=v_pre_edit_invoice_revision::text
            and coalesce(op.input_json->>'purpose','')='DRAFT_PREVIEW'
            and op.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
        )
    ) into v_source_edit_preexisting_preview;

    -- Clear any caller-controlled or earlier transaction-local value before
    -- establishing this function's exact-once invalidation marker.
    perform set_config('cloudtms.invoice_source_edit_marker','{}',true);

    -- Lock every target and its current financial snapshot in deterministic
    -- order before validating ownership, revisions or segment identities.
    for v_ref_ts in
      select t.*
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired on true
      where t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      order by t.timesheet_id
      for update of t
    loop
      null;
    end loop;
    for v_ref_ts in
      select tf.id
      from public.timesheets_financials tf
      join jsonb_each(v_source_updates_map) desired
        on tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where tf.is_current
      order by tf.timesheet_id,tf.id
      for update of tf
    loop
      null;
    end loop;

    if (
      select count(*)
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where t.is_current
    )<>(select count(*) from jsonb_each(v_source_updates_map)) then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_SOURCE_NOT_CURRENT';
    end if;

    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      join public.timesheets t
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      where t.document_revision is distinct from
        (desired.value->>'expected_document_revision')::bigint
    ) then
      raise exception using errcode='40001',
        message='INVOICE_SOURCE_EDIT_STALE_REVISION';
    end if;

    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where not exists(
        select 1
        from public.invoice_lines owned_line
        where owned_line.invoice_id=p_invoice_id
          and (
            owned_line.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              owned_line.timesheet_id is null
              and coalesce(owned_line.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (owned_line.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
    ) then
      raise exception using errcode='55000',
        message='INVOICE_SOURCE_EDIT_SOURCE_NOT_OWNED';
    end if;

    -- Preserve the established import-authoritative correction lock across
    -- both supported source carriers.
    if exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where coalesce((
        public._ctms_import_correction_classify_v1(
          (desired.value->>'timesheet_id')::uuid)
          ->>'is_import_authoritative_correction')::boolean,false)
    ) then
      raise exception using errcode='55000',
        message='IMPORT_AUTHORITATIVE_CORRECTION_SOURCE_EDIT_FORBIDDEN';
    end if;

    -- Reject a mixed command that edits a source while removing every carrier
    -- for that source in the same Save.
    if coalesce(array_length(v_remove_ids,1),0)>0 and exists(
      select 1
      from jsonb_each(v_source_updates_map) desired
      where exists(
        select 1
        from public.invoice_lines carrier
        where carrier.invoice_id=p_invoice_id
          and (
            carrier.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              carrier.timesheet_id is null
              and coalesce(carrier.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (carrier.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
      and not exists(
        select 1
        from public.invoice_lines retained
        where retained.invoice_id=p_invoice_id
          and not (retained.id=any(v_remove_ids))
          and (
            retained.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              retained.timesheet_id is null
              and coalesce(retained.meta_json->>'timesheet_id','') ~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (retained.meta_json->>'timesheet_id')::uuid=
                  (desired.value->>'timesheet_id')::uuid
            )
          )
      )
    ) then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND';
    end if;

    -- Classify each source from the locked current financial snapshot. A
    -- SEGMENTS payload is an editable reference projection only: it can never
    -- replace timesheets.actual_schedule_json or any financial segment object.
    for v_ref_ts in
      select t.*,desired.value desired_value,
        tf.id financial_id,tf.invoice_breakdown_json financial_breakdown
      from public.timesheets t
      join jsonb_each(v_source_updates_map) desired
        on t.timesheet_id=(desired.value->>'timesheet_id')::uuid
      left join lateral(
        select f.id,f.invoice_breakdown_json
        from public.timesheets_financials f
        where f.timesheet_id=t.timesheet_id and f.is_current
        order by f.updated_at desc nulls last,f.created_at desc nulls last,f.id desc
        limit 1
      ) tf on true
      where t.is_current
      order by t.timesheet_id
    loop
      v_source_update:=v_ref_ts.desired_value;
      v_source_financial_id:=v_ref_ts.financial_id;
      v_source_ib:=v_ref_ts.financial_breakdown;
      v_source_mode:=upper(coalesce(v_source_ib->>'mode',''));
      v_source_payload_schedule:=v_source_update->'actual_schedule_json';
      v_source_canonical_schedule:=v_ref_ts.actual_schedule_json;
      v_source_new_segments:=null;
      v_source_segment_updates:='[]'::jsonb;
      v_source_segment_reference_changed:=false;

      if (v_source_update->>'has_actual_schedule_json')::boolean then
        if jsonb_typeof(v_source_payload_schedule)<>'array' then
          raise exception using errcode='22023',
            message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
            detail=jsonb_build_object(
              'field','actual_schedule_json','reason','ARRAY_REQUIRED',
              'timesheet_id',v_ref_ts.timesheet_id)::text;
        end if;

        if v_source_mode='SEGMENTS' then
          if v_source_financial_id is null
             or jsonb_typeof(v_source_ib->'segments')<>'array' then
            raise exception using errcode='55000',
              message='INVOICE_SOURCE_EDIT_SOURCE_NOT_CURRENT';
          end if;

          v_ref_seen_keys:='{}'::jsonb;
          for v_source_payload_segment,v_source_payload_ord in
            select value,ord
            from jsonb_array_elements(v_source_payload_schedule)
              with ordinality payload(value,ord)
          loop
            if jsonb_typeof(v_source_payload_segment)<>'object' then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','INVALID_SEGMENT',
                  'ordinal',v_source_payload_ord)::text;
            end if;
            select min(field_name) into v_source_unsupported_field
            from jsonb_object_keys(v_source_payload_segment) field_name
            where not (field_name=any(v_allowed_reference_segment_fields));
            if v_source_unsupported_field is not null then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','UNSUPPORTED_FIELD',
                  'unsupported_field',v_source_unsupported_field,
                  'ordinal',v_source_payload_ord)::text;
            end if;
            if not (v_source_payload_segment ? 'ref_num') then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','REFERENCE_REQUIRED',
                  'ordinal',v_source_payload_ord)::text;
            end if;

            v_ref_seg_id:=nullif(btrim(coalesce(
              v_source_payload_segment->>'segment_id','')),'');
            v_source_match_count:=0;
            v_source_match_segment:=null;
            if v_ref_seg_id is not null then
              select count(*),min(seg.value::text)::jsonb
              into v_source_match_count,v_source_match_segment
              from jsonb_array_elements(v_source_ib->'segments') seg(value)
              where nullif(btrim(coalesce(seg.value->>'segment_id','')),'')=v_ref_seg_id
                and nullif(btrim(coalesce(
                  seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text;
            end if;

            if v_source_match_count=0 then
              begin
                v_source_start:=nullif(btrim(coalesce(
                  v_source_payload_segment->>'start_utc',
                  v_source_payload_segment->>'start','')),'')::timestamptz;
                v_source_end:=nullif(btrim(coalesce(
                  v_source_payload_segment->>'end_utc',
                  v_source_payload_segment->>'end','')),'')::timestamptz;
              exception when others then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                  detail=jsonb_build_object(
                    'field','actual_schedule_json','reason','INVALID_SEGMENT_TIME',
                    'ordinal',v_source_payload_ord)::text;
              end;
              if v_source_start is null or v_source_end is null then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                  detail=jsonb_build_object(
                    'field','actual_schedule_json','reason','SEGMENT_IDENTITY_REQUIRED',
                    'ordinal',v_source_payload_ord)::text;
              end if;
              select count(*),min(seg.value::text)::jsonb
              into v_source_match_count,v_source_match_segment
              from jsonb_array_elements(v_source_ib->'segments') seg(value)
              where nullif(btrim(coalesce(
                    seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
                and nullif(btrim(coalesce(
                    seg.value->>'start_utc',seg.value->>'start','')),'')::timestamptz
                    =v_source_start
                and nullif(btrim(coalesce(
                    seg.value->>'end_utc',seg.value->>'end','')),'')::timestamptz
                    =v_source_end;
            end if;

            if v_source_match_count<>1 or v_source_match_segment is null then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts.timesheet_id,
                  'ordinal',v_source_payload_ord,
                  'match_count',v_source_match_count)::text;
            end if;

            v_ref_sched_key:=coalesce(
              'SID:'||nullif(btrim(coalesce(
                v_source_match_segment->>'segment_id','')),''),
              'SE:'||coalesce(v_source_match_segment->>'start_utc',
                v_source_match_segment->>'start','')||'|'||
                coalesce(v_source_match_segment->>'end_utc',
                  v_source_match_segment->>'end',''));
            if v_ref_seen_keys ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts.timesheet_id,
                  'reason','DUPLICATE_IDENTITY')::text;
            end if;
            v_ref_seen_keys:=jsonb_set(
              v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
            v_ref_seg_new_ref:=nullif(btrim(coalesce(
              v_source_payload_segment->>'ref_num','')),'');
            v_source_segment_reference_changed:=
              v_source_segment_reference_changed or (
                nullif(btrim(coalesce(
                  v_source_match_segment->>'ref_num','')),'')
                is distinct from v_ref_seg_new_ref);
            v_source_segment_updates:=v_source_segment_updates||
              jsonb_build_array(jsonb_build_object(
                'segment_id',nullif(btrim(coalesce(
                  v_source_match_segment->>'segment_id','')),''),
                'start_identity',coalesce(v_source_match_segment->>'start_utc',
                  v_source_match_segment->>'start'),
                'end_identity',coalesce(v_source_match_segment->>'end_utc',
                  v_source_match_segment->>'end'),
                'ref_num',v_ref_seg_new_ref));
          end loop;

          v_source_new_segments:='[]'::jsonb;
          for v_source_current_segment in
            select value
            from jsonb_array_elements(v_source_ib->'segments')
              with ordinality current_segment(value,ord)
            order by ord
          loop
            v_source_payload_segment:=null;
            select update_item.value into v_source_payload_segment
            from jsonb_array_elements(v_source_segment_updates) update_item(value)
            where (
              nullif(update_item.value->>'segment_id','') is not null
              and nullif(btrim(coalesce(
                v_source_current_segment->>'segment_id','')),'')
                  =nullif(update_item.value->>'segment_id','')
            ) or (
              nullif(update_item.value->>'segment_id','') is null
              and coalesce(v_source_current_segment->>'start_utc',
                    v_source_current_segment->>'start')
                  is not distinct from update_item.value->>'start_identity'
              and coalesce(v_source_current_segment->>'end_utc',
                    v_source_current_segment->>'end')
                  is not distinct from update_item.value->>'end_identity'
            )
            limit 1;
            if v_source_payload_segment is not null then
              v_source_current_segment:=jsonb_set(
                v_source_current_segment,'{ref_num}',
                coalesce(v_source_payload_segment->'ref_num','null'::jsonb),true);
            end if;
            v_source_new_segments:=v_source_new_segments||
              jsonb_build_array(v_source_current_segment);
          end loop;
        else
          v_source_canonical_schedule:=coalesce(
            v_ref_ts.actual_schedule_json,'[]'::jsonb);
          if jsonb_typeof(v_source_canonical_schedule)<>'array'
             or jsonb_array_length(v_source_payload_schedule)
                <>jsonb_array_length(v_source_canonical_schedule) then
            raise exception using errcode='22023',
              message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
              detail=jsonb_build_object(
                'field','actual_schedule_json','reason','STRUCTURE_MISMATCH',
                'timesheet_id',v_ref_ts.timesheet_id)::text;
          end if;
          v_ref_new_segments:='[]'::jsonb;
          for v_source_payload_segment,v_source_current_segment,v_source_payload_ord in
            select p.value,c.value,p.ord
            from jsonb_array_elements(v_source_payload_schedule)
              with ordinality p(value,ord)
            join jsonb_array_elements(v_source_canonical_schedule)
              with ordinality c(value,ord) using(ord)
            order by p.ord
          loop
            if jsonb_typeof(v_source_payload_segment)<>'object'
               or jsonb_typeof(v_source_current_segment)<>'object'
               or not (v_source_payload_segment ? 'ref_num')
               or (v_source_payload_segment-'ref_num') is distinct from
                  (v_source_current_segment-'ref_num') then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_PAYLOAD_INVALID',
                detail=jsonb_build_object(
                  'field','actual_schedule_json','reason','STRUCTURE_MISMATCH',
                  'ordinal',v_source_payload_ord)::text;
            end if;
            v_ref_new_segments:=v_ref_new_segments||jsonb_build_array(
              jsonb_set(v_source_current_segment,'{ref_num}',
                coalesce(v_source_payload_segment->'ref_num','null'::jsonb),true));
          end loop;
          v_source_canonical_schedule:=v_ref_new_segments;
        end if;
      end if;

      v_source_timesheet_row_changed:=(
        ((v_source_update->>'has_reference_number')::boolean
          and v_ref_ts.reference_number is distinct from
            nullif(btrim(coalesce(v_source_update->>'reference_number','')),''))
        or ((v_source_update->>'has_day_references_json')::boolean
          and v_ref_ts.day_references_json is distinct from
            case when jsonb_typeof(v_source_update->'day_references_json')='null'
              then null else v_source_update->'day_references_json' end)
        or ((v_source_update->>'has_actual_schedule_json')::boolean
          and v_source_mode<>'SEGMENTS'
          and v_ref_ts.actual_schedule_json is distinct from
            v_source_canonical_schedule)
        or ((v_source_update->>'has_hospital_norm')::boolean
          and lower(regexp_replace(
                btrim(coalesce(v_ref_ts.hospital_norm,'')),
                '[[:space:]]+',' ','g')) is distinct from
            coalesce(v_source_update->>'hospital_norm',''))
        or ((v_source_update->>'has_ward_norm')::boolean
          and lower(regexp_replace(
                btrim(coalesce(v_ref_ts.ward_norm,'')),
                '[[:space:]]+',' ','g')) is distinct from
            coalesce(v_source_update->>'ward_norm',''))
      );
      v_source_update:=v_source_update||jsonb_build_object(
        'source_mode',v_source_mode,
        'financial_id',v_source_financial_id,
        'canonical_actual_schedule_json',v_source_canonical_schedule,
        'new_financial_segments',v_source_new_segments,
        'segment_updates',v_source_segment_updates,
        'segment_reference_changed',v_source_segment_reference_changed,
        'timesheet_row_changed',v_source_timesheet_row_changed);
      v_source_updates_map:=jsonb_set(
        v_source_updates_map,array[v_ref_ts.timesheet_id::text],
        v_source_update,true);
    end loop;

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_source_changed_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_row_changed')::boolean
       or (desired.value->>'segment_reference_changed')::boolean;

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_refupd_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_id')::uuid=any(v_source_changed_ts_ids)
      and (
        (desired.value->>'has_reference_number')::boolean
        or (desired.value->>'has_day_references_json')::boolean
        or (
          (desired.value->>'has_actual_schedule_json')::boolean
          and (
            (desired.value->>'timesheet_row_changed')::boolean
            or (desired.value->>'segment_reference_changed')::boolean
          )
        )
      );

    select coalesce(array_agg(
      (desired.value->>'timesheet_id')::uuid order by desired.key),
      array[]::uuid[])
    into v_location_ts_ids
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_row_changed')::boolean
      and (
        (desired.value->>'has_hospital_norm')::boolean
        or (desired.value->>'has_ward_norm')::boolean
      );

    if exists(
      select 1 from jsonb_each(v_source_updates_map) desired
      where (desired.value->>'timesheet_row_changed')::boolean
    ) then
      with desired as materialized(
        select (value->>'timesheet_id')::uuid as timesheet_id,value
        from jsonb_each(v_source_updates_map)
      )
      update public.timesheets t
      set updated_at=v_now,
          reference_number=case when (d.value->>'has_reference_number')::boolean
            then nullif(btrim(coalesce(d.value->>'reference_number','')),'')
            else t.reference_number end,
          day_references_json=case when (d.value->>'has_day_references_json')::boolean
            then case when jsonb_typeof(d.value->'day_references_json')='null'
              then null else d.value->'day_references_json' end
            else t.day_references_json end,
          actual_schedule_json=case
            when (d.value->>'has_actual_schedule_json')::boolean
              and d.value->>'source_mode'<>'SEGMENTS'
            then d.value->'canonical_actual_schedule_json'
            else t.actual_schedule_json end,
          hospital_norm=case when (d.value->>'has_hospital_norm')::boolean
            then coalesce(d.value->>'hospital_norm','') else t.hospital_norm end,
          ward_norm=case when (d.value->>'has_ward_norm')::boolean
            then coalesce(d.value->>'ward_norm','') else t.ward_norm end
      from desired d
      where t.timesheet_id=d.timesheet_id
        and (d.value->>'timesheet_row_changed')::boolean
        and t.is_current;
    end if;

    v_refupd_applied:=cardinality(v_refupd_ts_ids);
    v_location_applied:=cardinality(v_location_ts_ids);

    -- Marker rows exist only where the timesheet statement has already advanced
    -- the source revision and the following SEGMENTS ref update would otherwise
    -- invalidate the same source a second time.
    select coalesce(jsonb_object_agg(
      t.timesheet_id::text,
      jsonb_build_object('expected_revision',t.document_revision)),
      '{}'::jsonb)
    into v_source_marker_rows
    from jsonb_each(v_source_updates_map) desired
    join public.timesheets t
      on t.timesheet_id=(desired.value->>'timesheet_id')::uuid and t.is_current
    where (desired.value->>'timesheet_row_changed')::boolean
      and (desired.value->>'segment_reference_changed')::boolean
      and t.document_revision=
        (desired.value->>'expected_document_revision')::bigint+1;
    if (select count(*) from jsonb_each(v_source_marker_rows))<>(
      select count(*) from jsonb_each(v_source_updates_map) desired
      where (desired.value->>'timesheet_row_changed')::boolean
        and (desired.value->>'segment_reference_changed')::boolean
    ) then
      raise exception using errcode='55000',
        message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
        detail=jsonb_build_object(
          'reason','SOURCE_REVISION_ADVANCE_NOT_EXACT')::text;
    end if;
    v_source_marker:=jsonb_build_object(
      'txid',txid_current()::text,'rows',v_source_marker_rows);
    perform set_config(
      'cloudtms.invoice_source_edit_marker',v_source_marker::text,true);

    -- The legacy per-array loops below remain structurally compatible for old
    -- payload code, but the strict merged statement above is now the sole
    -- execution path for accepted source edits.
    v_reference_updates:=null;
    v_location_updates:=null;
  end if;





  -- 0) Apply reference updates to timesheets (does NOT recompute TSFIN; it updates the source timesheet refs)
  if v_reference_updates is not null and jsonb_typeof(v_reference_updates)='array' and jsonb_array_length(v_reference_updates) > 0 then
    for v_refupd in
      select value from jsonb_array_elements(v_reference_updates) value
    loop
      if v_refupd is null or jsonb_typeof(v_refupd) <> 'object' then
        continue;
      end if;

      if nullif(btrim(coalesce(v_refupd->>'timesheet_id','')), '') is null then
        continue;
      end if;

      v_refupd_ts_id := (v_refupd->>'timesheet_id')::uuid;

      v_refupd_set_refnum := (v_refupd ? 'reference_number');
      v_refupd_set_dayrefs := (v_refupd ? 'day_references_json');
      v_refupd_set_sched := (v_refupd ? 'actual_schedule_json');

      v_refupd_refnum := null;
      if v_refupd_set_refnum then
        v_refupd_refnum := nullif(btrim(coalesce(v_refupd->>'reference_number','')), '');
      end if;

      v_refupd_dayrefs := null;
      if v_refupd_set_dayrefs then
        v_refupd_dayrefs := v_refupd->'day_references_json';
        if v_refupd_dayrefs is not null and jsonb_typeof(v_refupd_dayrefs) = 'null' then
          v_refupd_dayrefs := null;
        end if;
      end if;

      v_refupd_sched := null;
      if v_refupd_set_sched then
        v_refupd_sched := v_refupd->'actual_schedule_json';
        if v_refupd_sched is not null and jsonb_typeof(v_refupd_sched) = 'null' then
          v_refupd_sched := null;
        end if;
      end if;

      update public.timesheets tsu
      set
        updated_at = v_now,
        reference_number = case when v_refupd_set_refnum then v_refupd_refnum else tsu.reference_number end,
        day_references_json = case when v_refupd_set_dayrefs then v_refupd_dayrefs else tsu.day_references_json end,
        actual_schedule_json = case when v_refupd_set_sched then v_refupd_sched else tsu.actual_schedule_json end
      where tsu.timesheet_id = v_refupd_ts_id
        and tsu.is_current = true
        and exists(
          select 1
          from public.invoice_lines owned_line
          where owned_line.invoice_id=p_invoice_id
            and (
              owned_line.timesheet_id=tsu.timesheet_id
              or (
                owned_line.timesheet_id is null
                and coalesce(owned_line.meta_json->>'timesheet_id','')
                  ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                and (owned_line.meta_json->>'timesheet_id')::uuid=tsu.timesheet_id
              )
            )
        )
        and (
          (v_refupd_set_refnum and tsu.reference_number is distinct from v_refupd_refnum)
          or (v_refupd_set_dayrefs and tsu.day_references_json is distinct from v_refupd_dayrefs)
          or (v_refupd_set_sched and tsu.actual_schedule_json is distinct from v_refupd_sched)
        );

      get diagnostics v_rc = row_count;
      if coalesce(v_rc,0) > 0 then
        v_refupd_applied := v_refupd_applied + 1;
        v_refupd_ts_ids := v_refupd_ts_ids || v_refupd_ts_id;
      end if;

    end loop;

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object('step','reference_updates_applied','count_requested',v_refupd_count,'count_applied',v_refupd_applied)
      );
    end if;
  end if;

  -- 0a) Apply only material hospital/ward changes to current timesheets that
  -- are owned by this invoice. Identical canonical values perform no UPDATE,
  -- so they cannot dirty documents or queue replacement work.
  if v_location_updates is not null
     and jsonb_typeof(v_location_updates)='array'
     and jsonb_array_length(v_location_updates)>0 then
    for v_location_update in
      select value from jsonb_array_elements(v_location_updates) value
    loop
      if v_location_update is null
         or jsonb_typeof(v_location_update)<>'object'
         or nullif(btrim(coalesce(v_location_update->>'timesheet_id','')),'') is null then
        continue;
      end if;

      v_location_ts_id := (v_location_update->>'timesheet_id')::uuid;
      v_location_set_hospital := v_location_update ? 'hospital_norm';
      v_location_set_ward := v_location_update ? 'ward_norm';
      if not v_location_set_hospital and not v_location_set_ward then
        continue;
      end if;

      v_location_hospital_norm := null;
      if v_location_set_hospital then
        v_location_hospital_norm := nullif(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'hospital_norm','')),
          '[[:space:]]+',' ','g')), '');
      end if;
      v_location_ward_norm := null;
      if v_location_set_ward then
        v_location_ward_norm := nullif(lower(regexp_replace(
          btrim(coalesce(v_location_update->>'ward_norm','')),
          '[[:space:]]+',' ','g')), '');
      end if;

      update public.timesheets tsu
      set updated_at=v_now,
          hospital_norm=case when v_location_set_hospital
            then v_location_hospital_norm else tsu.hospital_norm end,
          ward_norm=case when v_location_set_ward
            then v_location_ward_norm else tsu.ward_norm end
      where tsu.timesheet_id=v_location_ts_id
        and tsu.is_current=true
        and exists(
          select 1
          from public.invoice_lines owned_line
          where owned_line.invoice_id=p_invoice_id
            and (
              owned_line.timesheet_id=tsu.timesheet_id
              or (
                owned_line.timesheet_id is null
                and coalesce(owned_line.meta_json->>'timesheet_id','')
                  ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                and (owned_line.meta_json->>'timesheet_id')::uuid=tsu.timesheet_id
              )
            )
        )
        and (
          (v_location_set_hospital
            and tsu.hospital_norm is distinct from v_location_hospital_norm)
          or (v_location_set_ward
            and tsu.ward_norm is distinct from v_location_ward_norm)
        );

      get diagnostics v_rc=row_count;
      if coalesce(v_rc,0)>0 then
        v_location_applied:=v_location_applied+1;
        v_location_ts_ids:=v_location_ts_ids||v_location_ts_id;
      end if;
    end loop;

    if v_invoice_debug then
      v_dbg_steps:=v_dbg_steps||jsonb_build_array(jsonb_build_object(
        'step','timesheet_location_updates_applied',
        'count_requested',v_location_count,
        'count_applied',v_location_applied));
    end if;
  end if;
  -- 0b) After reference updates: refresh invoice_lines meta (ts_reference_number / schedule_ref_nums) and
  -- synchronise only the approved ref_num fields into the locked SEGMENTS
  -- financial projection. The full financial objects and their order are
  -- preserved from the locked current snapshot.
  if v_refupd_ts_ids is not null and coalesce(array_length(v_refupd_ts_ids,1),0) > 0 then

    with desired as materialized(
      select value
      from jsonb_each(v_source_updates_map)
      where (value->>'segment_reference_changed')::boolean
    )
    update public.timesheets_financials tf
    set invoice_breakdown_json=jsonb_set(
      coalesce(tf.invoice_breakdown_json,'{}'::jsonb),
      '{segments}',d.value->'new_financial_segments',true)
    from desired d
    where tf.id=(d.value->>'financial_id')::uuid
      and tf.is_current
      and tf.timesheet_id=(d.value->>'timesheet_id')::uuid
      and upper(coalesce(tf.invoice_breakdown_json->>'mode',''))='SEGMENTS'
      and tf.invoice_breakdown_json->'segments'
        is distinct from d.value->'new_financial_segments';
    get diagnostics v_refupd_tsfin_rows_updated=row_count;
    select coalesce(sum(jsonb_array_length(
      coalesce(value->'segment_updates','[]'::jsonb))),0)::integer
    into v_refupd_tsfin_segments_updated
    from jsonb_each(v_source_updates_map)
    where (value->>'segment_reference_changed')::boolean;

    -- The marker has served its single synchronisation statement. Clear it so
    -- no later statement in this transaction can inherit suppression authority.
    perform set_config('cloudtms.invoice_source_edit_marker','{}',true);

    select array_agg(distinct x)
    into v_refupd_ts_ids_distinct
    from unnest(v_refupd_ts_ids) x
    where x is not null;

    v_refupd_ts_ids_distinct := coalesce(v_refupd_ts_ids_distinct, array[]::uuid[]);

    foreach v_ref_ts_id in array v_refupd_ts_ids_distinct loop
      if v_ref_ts_id is null then
        continue;
      end if;

      select tsu.*
      into v_ref_ts
      from public.timesheets tsu
      where tsu.timesheet_id = v_ref_ts_id
        and tsu.is_current = true
      limit 1;

      if not found then
        continue;
      end if;
      v_source_update:=v_source_updates_map->v_ref_ts_id::text;
      v_source_mode:=upper(coalesce(v_source_update->>'source_mode',''));
      v_source_canonical_schedule:=case when v_source_mode='SEGMENTS'
        then coalesce(v_source_update->'new_financial_segments','[]'::jsonb)
        else coalesce(v_ref_ts.actual_schedule_json,'[]'::jsonb) end;

      -- Build the cache from the exact authority used by this invoice. SEGMENTS
      -- refs come from invoice-owned financial segments; other modes use the
      -- structurally preserved timesheet schedule.
      v_ref_schedule_refs := '[]'::jsonb;

      if nullif(btrim(coalesce(v_ref_ts.reference_number,'')), '') is not null then
        v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(nullif(btrim(v_ref_ts.reference_number),'')));
      end if;

      if v_ref_ts.day_references_json is not null and jsonb_typeof(v_ref_ts.day_references_json) = 'object' then
        for kv in
          select key as k, value as v
          from jsonb_each_text(v_ref_ts.day_references_json)
        loop
          if nullif(btrim(coalesce(kv.v,'')), '') is not null then
            v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(nullif(btrim(kv.v),'')));
          end if;
        end loop;
      end if;

      if jsonb_typeof(v_source_canonical_schedule)='array' then
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_source_canonical_schedule) value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            continue;
          end if;
          v_ref_sched_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
          if v_ref_sched_ref is not null then
            v_ref_schedule_refs := v_ref_schedule_refs || jsonb_build_array(to_jsonb(v_ref_sched_ref));
          end if;
        end loop;
      end if;

      select coalesce(jsonb_agg(to_jsonb(x) order by x), '[]'::jsonb)
      into v_ref_schedule_refs_distinct
      from (
        select distinct btrim(t.x) as x
        from jsonb_array_elements_text(coalesce(v_ref_schedule_refs,'[]'::jsonb)) as t(x)
        where nullif(btrim(coalesce(t.x,'')), '') is not null
      ) q;

      -- Refresh meta_json on all invoice lines for this timesheet
      update public.invoice_lines ilu
      set meta_json = coalesce(ilu.meta_json, '{}'::jsonb) || jsonb_build_object(
        'ts_reference_number', nullif(btrim(coalesce(v_ref_ts.reference_number,'')), ''),
        'schedule_ref_nums', coalesce(v_ref_schedule_refs_distinct, '[]'::jsonb),
        'schedule_ref_count', jsonb_array_length(coalesce(v_ref_schedule_refs_distinct, '[]'::jsonb))
      )
      where ilu.invoice_id = p_invoice_id
        and (
          ilu.timesheet_id=v_ref_ts_id
          or (
            ilu.timesheet_id is null
            and coalesce(ilu.meta_json->>'timesheet_id','') ~
              '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            and (ilu.meta_json->>'timesheet_id')::uuid=v_ref_ts_id
          )
        )
        and (
          ilu.meta_json->'ts_reference_number' is distinct from
            coalesce(to_jsonb(nullif(btrim(coalesce(v_ref_ts.reference_number,'')),'')),'null'::jsonb)
          or ilu.meta_json->'schedule_ref_nums' is distinct from
            coalesce(v_ref_schedule_refs_distinct,'[]'::jsonb)
          or ilu.meta_json->'schedule_ref_count' is distinct from
            to_jsonb(jsonb_array_length(coalesce(v_ref_schedule_refs_distinct,'[]'::jsonb)))
        );

      get diagnostics v_rc = row_count;
      v_refupd_meta_rows_updated := v_refupd_meta_rows_updated + coalesce(v_rc,0);

      -- Best-effort sync: update tsfin.invoice_breakdown_json segments[].ref_num by matching start/end fields
      v_ref_seg_updates_this_ts := 0;
      v_ref_seg_matches_this_ts := 0;
      v_ref_tsfin_id := null;
      v_ref_ib := null;

        select tfu.id, tfu.invoice_breakdown_json
      into v_ref_tsfin_id, v_ref_ib
      from public.timesheets_financials tfu
      where tfu.timesheet_id = v_ref_ts_id
        and tfu.is_current = true
      limit 1
      for update;


      if v_ref_tsfin_id is not null
         and v_source_mode<>'SEGMENTS'
         and v_ref_ib is not null
         and jsonb_typeof(v_ref_ib) = 'object'
         and upper(coalesce(v_ref_ib->>'mode','')) = 'SEGMENTS'
         and jsonb_typeof(v_ref_ib->'segments') = 'array'
         and v_ref_ts.actual_schedule_json is not null
         and jsonb_typeof(v_ref_ts.actual_schedule_json) = 'array'
       then
         -- Build a map of segment_id (preferred) or start|end -> ref_num from actual_schedule_json
        v_ref_sched_map := '{}'::jsonb;
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_ref_ts.actual_schedule_json) value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            continue;
          end if;

          v_ref_sched_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
          v_ref_seg_id := nullif(btrim(coalesce(v_ref_seg_obj->>'segment_id','')), '');
          if v_ref_seg_id is not null then
            v_ref_sched_key := 'SID:' || v_ref_seg_id;
            if v_ref_sched_map ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                  'side','TIMESHEET_SCHEDULE')::text;
            end if;
            v_ref_sched_map := jsonb_set(v_ref_sched_map, array[v_ref_sched_key], case when v_ref_sched_ref is null then 'null'::jsonb else to_jsonb(v_ref_sched_ref) end, true);
            continue;
          end if;

          v_ref_seg_start := nullif(btrim(coalesce(v_ref_seg_obj->>'start_utc', v_ref_seg_obj->>'start', '')), '');
          v_ref_seg_end := nullif(btrim(coalesce(v_ref_seg_obj->>'end_utc', v_ref_seg_obj->>'end', '')), '');
          if v_ref_seg_start is null or v_ref_seg_end is null then
            continue;
          end if;

          v_ref_sched_key := 'SE:' || v_ref_seg_start || '|' || v_ref_seg_end;
          if v_ref_sched_map ? v_ref_sched_key then
            raise exception using errcode='22023',
              message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
              detail=jsonb_build_object(
                'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                'side','TIMESHEET_SCHEDULE')::text;
          end if;
          v_ref_sched_map := jsonb_set(v_ref_sched_map, array[v_ref_sched_key], case when v_ref_sched_ref is null then 'null'::jsonb else to_jsonb(v_ref_sched_ref) end, true);
        end loop;

        v_ref_new_segments := '[]'::jsonb;
        v_ref_seen_keys := '{}'::jsonb;
        for v_ref_seg_obj in
          select value
          from jsonb_array_elements(v_ref_ib->'segments') value
        loop
          if v_ref_seg_obj is null or jsonb_typeof(v_ref_seg_obj) <> 'object' then
            v_ref_new_segments := v_ref_new_segments || jsonb_build_array(v_ref_seg_obj);
            continue;
          end if;

          v_ref_seg_new_ref := null;
          v_ref_seg_has_update := false;

          v_ref_seg_id := nullif(btrim(coalesce(v_ref_seg_obj->>'segment_id','')), '');
          if v_ref_seg_id is not null then
            v_ref_sched_key := 'SID:' || v_ref_seg_id;
            if v_ref_seen_keys ? v_ref_sched_key then
              raise exception using errcode='22023',
                message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                detail=jsonb_build_object(
                  'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                  'side','FINANCIAL_SEGMENTS')::text;
            end if;
            v_ref_seen_keys:=jsonb_set(v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
            if v_ref_sched_map ? v_ref_sched_key then
              v_ref_seg_new_ref := nullif(btrim(coalesce(v_ref_sched_map->>v_ref_sched_key,'')), '');
              v_ref_seg_has_update := true;
              v_ref_seg_matches_this_ts := v_ref_seg_matches_this_ts + 1;
            end if;
          end if;

          if not v_ref_seg_has_update then
            v_ref_seg_start := nullif(btrim(coalesce(v_ref_seg_obj->>'start_utc', v_ref_seg_obj->>'start', '')), '');
            v_ref_seg_end := nullif(btrim(coalesce(v_ref_seg_obj->>'end_utc', v_ref_seg_obj->>'end', '')), '');

            if v_ref_seg_start is not null and v_ref_seg_end is not null then
              v_ref_sched_key := 'SE:' || v_ref_seg_start || '|' || v_ref_seg_end;
              if v_ref_seen_keys ? v_ref_sched_key then
                raise exception using errcode='22023',
                  message='INVOICE_SOURCE_EDIT_SEGMENT_REFERENCE_AMBIGUOUS',
                  detail=jsonb_build_object(
                    'timesheet_id',v_ref_ts_id,'identity',v_ref_sched_key,
                    'side','FINANCIAL_SEGMENTS')::text;
              end if;
              v_ref_seen_keys:=jsonb_set(v_ref_seen_keys,array[v_ref_sched_key],'true'::jsonb,true);
              if v_ref_sched_map ? v_ref_sched_key then
                v_ref_seg_new_ref := nullif(btrim(coalesce(v_ref_sched_map->>v_ref_sched_key,'')), '');
                v_ref_seg_has_update := true;
                v_ref_seg_matches_this_ts := v_ref_seg_matches_this_ts + 1;
              end if;
            end if;
          end if;

          if v_ref_seg_has_update then
            v_ref_seg_cur_ref := nullif(btrim(coalesce(v_ref_seg_obj->>'ref_num','')), '');
            if v_ref_seg_cur_ref is distinct from v_ref_seg_new_ref then
              v_ref_seg_obj := jsonb_set(
                v_ref_seg_obj,
                '{ref_num}',
                case when v_ref_seg_new_ref is null then 'null'::jsonb else to_jsonb(v_ref_seg_new_ref) end,
                true
              );
              v_ref_seg_updates_this_ts := v_ref_seg_updates_this_ts + 1;
            end if;
          end if;

          v_ref_new_segments := v_ref_new_segments || jsonb_build_array(v_ref_seg_obj);
        end loop;



        if v_ref_sched_map is not null
           and jsonb_typeof(v_ref_sched_map) = 'object'
           and v_ref_sched_map <> '{}'::jsonb
           and coalesce(jsonb_array_length(coalesce(v_ref_ib->'segments','[]'::jsonb)),0) > 0
           and coalesce(v_ref_seg_matches_this_ts,0) = 0
        then
          raise exception 'SEGMENTS reference sync failed: no segments matched schedule keys (timesheet_id=% tsfin_id=%)', v_ref_ts_id, v_ref_tsfin_id;
        end if;

        if v_ref_seg_updates_this_ts > 0 then
              update public.timesheets_financials tfu2
          set invoice_breakdown_json = jsonb_set(coalesce(tfu2.invoice_breakdown_json, '{}'::jsonb), '{segments}', v_ref_new_segments, true)
          where tfu2.id = v_ref_tsfin_id
            and tfu2.is_current = true;


          get diagnostics v_rc = row_count;
          if coalesce(v_rc,0) > 0 then
            v_refupd_tsfin_rows_updated := v_refupd_tsfin_rows_updated + 1;
            v_refupd_tsfin_segments_updated := v_refupd_tsfin_segments_updated + v_ref_seg_updates_this_ts;
          end if;
        end if;

      end if;

    end loop;

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','reference_updates_meta_refreshed',
          'timesheets_count', coalesce(array_length(v_refupd_ts_ids_distinct,1),0),
          'invoice_line_rows_updated', v_refupd_meta_rows_updated,
          'tsfin_rows_updated', v_refupd_tsfin_rows_updated,
          'tsfin_segments_refnum_updated', v_refupd_tsfin_segments_updated
        )
      );
    end if;
  end if;

  -- 1) Removals (by invoice_line_id)
  if v_remove_ids is not null and coalesce(array_length(v_remove_ids,1),0) > 0 then
    -- collect timesheet_ids touched (any)
    select array_agg(distinct l.timesheet_id) filter (where l.timesheet_id is not null)
    into v_ts_ids_touched
    from public.invoice_lines l
    where l.invoice_id = p_invoice_id
      and l.id = any(v_remove_ids);

    -- record removed lines for history
    v_hist_lines_removed := coalesce(p_payload->'remove_invoice_line_ids','[]'::jsonb);

    -- Only unlock TSFIN when HOURS lines were removed (prevents accidental unlock when deleting only expenses/other lines)
    -- IMPORTANT: compute BEFORE deletion because we match on the removed invoice_line ids.
    select array_agg(distinct l.timesheet_id) filter (where l.timesheet_id is not null)
    into v_cw_ts_ids
    from public.invoice_lines l
    where l.invoice_id = p_invoice_id
      and l.id = any(v_remove_ids)
      and upper(coalesce(l.meta_json->>'line_type','')) in ('HOURS_WEEKLY','HOURS_DAILY');

    v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);



    if coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
      v_refresh_hr_cache := true;
    end if;
delete from public.invoice_lines
    where invoice_id = p_invoice_id
      and id = any(v_remove_ids);
    get diagnostics v_rc = row_count;
    v_dbg_lines_deleted := v_dbg_lines_deleted + coalesce(v_rc,0);

    if v_invoice_debug then
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','lines_removed',
          'rows_deleted', coalesce(v_rc,0),
          'timesheets_touched', coalesce(array_length(v_ts_ids_touched,1),0),
          'timesheets_to_unlock_count', coalesce(array_length(v_cw_ts_ids,1),0)
        )
      );
    end if;

    -- FIX: if a touched timesheet now has NO remaining invoice_lines on this invoice,
    -- unlock it even if the removed lines were expenses/mileage/additional (expense-only/SEGMENTS-empty case).
    v_ts_ids_fully_removed := array[]::uuid[];
    select array_agg(distinct x)
    into v_ts_ids_fully_removed
    from unnest(coalesce(v_ts_ids_touched, array[]::uuid[])) x
    where x is not null
      and not exists (
        select 1
        from public.invoice_lines l2
        where l2.invoice_id = p_invoice_id
          and l2.timesheet_id = x
      );

    v_ts_ids_fully_removed := coalesce(v_ts_ids_fully_removed, array[]::uuid[]);

    if coalesce(array_length(v_ts_ids_fully_removed,1),0) > 0 then
      -- unlock any segments locked to this invoice (safe no-op for SEGMENTS-empty)
      perform public._inv_unlock_segments_for_invoice(p_invoice_id, v_ts_ids_fully_removed);

      -- clear whole-timesheet lock if it was set for this invoice (SEGMENTS-empty / non-segments / pseudo segment_id null locks)
      update public.timesheets_financials tfu_lock
      set
        locked_by_invoice_id = null,
        locked_at_utc = null,
        updated_at = v_now
      where tfu_lock.is_current = true
        and tfu_lock.timesheet_id = any(v_ts_ids_fully_removed)
        and tfu_lock.locked_by_invoice_id = p_invoice_id;

      get diagnostics v_rc = row_count;
      v_dbg_timesheets_unlocked := v_dbg_timesheets_unlocked + coalesce(v_rc,0);

      v_refresh_hr_cache := true;

      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(
          jsonb_build_object(
            'step','timesheets_unlocked_after_full_removal',
            'timesheets_fully_removed_count', coalesce(array_length(v_ts_ids_fully_removed,1),0),
            'tsfin_rows_unlocked_count', coalesce(v_rc,0)
          )
        );
      end if;
    end if;

    v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);

    if v_cw_ts_ids is not null and coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
      perform public._inv_unlock_segments_for_invoice(p_invoice_id, v_cw_ts_ids);
      v_dbg_timesheets_unlocked := v_dbg_timesheets_unlocked + coalesce(array_length(v_cw_ts_ids,1),0);

      -- Cleanup: if no segments remain on THIS invoice for a touched timesheet, remove ALL remaining invoice lines for that timesheet
      foreach tsid in array v_cw_ts_ids loop
        if tsid is null then continue; end if;

        -- detect if any segments are still locked to THIS invoice
        select tf.*
        into snap
        from public.timesheets_financials tf
        where tf.is_current = true
          and tf.timesheet_id = tsid
        limit 1;

        if not found then
          continue;
        end if;

        segments := '[]'::jsonb;
        if snap.invoice_breakdown_json is not null
           and jsonb_typeof(snap.invoice_breakdown_json)='object'
           and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
           and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
        then
          for v_seg in
            select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
          loop
            if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
              continue;
            end if;
            seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
            if seg_locked = p_invoice_id::text then
              segments := segments || jsonb_build_array(v_seg);
            end if;
          end loop;

          if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
            delete from public.invoice_lines
            where invoice_id = p_invoice_id
              and timesheet_id = tsid;
          end if;
        else
          -- Non-segments: if snapshot is no longer locked to this invoice, remove all remaining invoice lines for this timesheet
          if snap.locked_by_invoice_id is null then
            delete from public.invoice_lines
            where invoice_id = p_invoice_id
              and timesheet_id = tsid;
          end if;
        end if;
      end loop;
    end if;

    -- History event (always)
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_LINES_REMOVED',
      null,
      jsonb_build_object('remove_invoice_line_ids', v_hist_lines_removed, 'timesheet_ids_touched', coalesce(to_jsonb(v_ts_ids_touched), '[]'::jsonb)),
      null,
      p_actor_user_id
    );

  end if;


  -- 1b) Segment edits (SEGMENTS mode only)
-- NOTE: Segment moves are NOT allowed when additional rates OR expenses/mileage exist on the TSFIN snapshot.
-- Payload contract uses tsfin_id + segment_id.
if v_has_seg_ops then

  v_dbg_seg_add_refs := case when v_add_seg_refs is null then 0 else jsonb_array_length(coalesce(v_add_seg_refs,'[]'::jsonb)) end;
  v_dbg_seg_remove_refs := case when v_remove_seg_refs is null then 0 else jsonb_array_length(coalesce(v_remove_seg_refs,'[]'::jsonb)) end;

  if v_invoice_debug then
    v_dbg_steps := v_dbg_steps || jsonb_build_array(
      jsonb_build_object(
        'step','segment_ops_start',
        'add_segment_refs_count', v_dbg_seg_add_refs,
        'remove_segment_refs_count', v_dbg_seg_remove_refs
      )
    );
  end if;

  -- Collect distinct tsfin_ids involved in segment ops
  select array_agg(distinct (x->>'tsfin_id')::uuid)
  into v_seg_tsfin_ids
  from (
    select value as x
    from jsonb_array_elements(coalesce(v_remove_seg_refs,'[]'::jsonb))
    union all
    select value as x
    from jsonb_array_elements(coalesce(v_add_seg_refs,'[]'::jsonb))
  ) u
  where jsonb_typeof(x) = 'object'
    and nullif(btrim(coalesce(x->>'tsfin_id','')), '') is not null;

  v_seg_tsfin_ids := coalesce(v_seg_tsfin_ids, array[]::uuid[]);

  v_dbg_seg_tsfins := coalesce(array_length(v_seg_tsfin_ids,1),0);
  if v_invoice_debug then
    v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','segment_ops_targets','tsfin_count',v_dbg_seg_tsfins));
  end if;

  if coalesce(array_length(v_seg_tsfin_ids,1),0) > 0 then

    -- Validate that each snapshot is current SEGMENTS mode and has NO additional/expenses/mileage
    foreach v_tsfin_id in array v_seg_tsfin_ids loop
      select *
      into snap
      from public.timesheets_financials tf
      where tf.id = v_tsfin_id
      limit 1;

      if not found then
        raise exception 'Segment edit refers to unknown tsfin_id %', v_tsfin_id;
      end if;

      if snap.is_current is not true then
        raise exception 'Segment edit requires current tsfin snapshot (tsfin_id=%)', v_tsfin_id;
      end if;

      if snap.client_id is distinct from v_inv.client_id then
        raise exception 'Segment edit timesheet client mismatch (tsfin_id=%)', v_tsfin_id;
      end if;

      if snap.invoice_breakdown_json is null
         or jsonb_typeof(snap.invoice_breakdown_json) <> 'object'
         or upper(coalesce(snap.invoice_breakdown_json->>'mode','')) <> 'SEGMENTS'
         or jsonb_typeof(snap.invoice_breakdown_json->'segments') <> 'array'
      then
        raise exception 'Segment edit is only supported for SEGMENTS timesheets (tsfin_id=%)', v_tsfin_id;
      end if;

      v_has_additional :=
        public._inv_round2(coalesce(snap.additional_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.additional_charge_ex_vat,0)) <> 0
        or (snap.additional_units_json is not null and jsonb_typeof(snap.additional_units_json)='object' and snap.additional_units_json <> '{}'::jsonb);

      v_has_expense_or_mileage :=
        public._inv_round2(coalesce(snap.expenses_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.expenses_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.mileage_units,0)) <> 0
        or public._inv_round2(coalesce(snap.travel_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.travel_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.accommodation_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.accommodation_charge_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.other_pay_ex_vat,0)) <> 0
        or public._inv_round2(coalesce(snap.other_charge_ex_vat,0)) <> 0;

      if v_has_additional then
        raise exception 'Segments cannot be moved when additional rates exist (timesheet_id=% tsfin_id=%)', snap.timesheet_id, v_tsfin_id;
      end if;

      if v_has_expense_or_mileage then
        raise exception 'Segments cannot be moved when expenses or mileage exist (timesheet_id=% tsfin_id=%)', snap.timesheet_id, v_tsfin_id;
      end if;
    end loop;

    -- Validate and apply add_segment_refs (lock selected segments)
    v_seg_refs_to_lock := '[]'::jsonb;
    if v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0 then
      for v_ref in
        select value from jsonb_array_elements(v_add_seg_refs) value
      loop
        if v_ref is null or jsonb_typeof(v_ref) <> 'object' then
          continue;
        end if;

        if nullif(btrim(coalesce(v_ref->>'tsfin_id','')), '') is null then
          continue;
        end if;

        v_tsfin_id := (v_ref->>'tsfin_id')::uuid;
        v_seg_id := nullif(btrim(coalesce(v_ref->>'segment_id','')), '');

        if v_seg_id is null then
          raise exception 'add_segment_refs requires segment_id (tsfin_id=%)', v_tsfin_id;
        end if;

          -- Load snapshot + timesheet + precheck (must be OK)
        select
          tf.*,
          tsr.sheet_scope::text as sheet_scope,
          coalesce(tsr.submission_mode::text,'') as submission_mode,
          tsr.day_references_json,
          tsr.actual_schedule_json,
          tsr.week_ending_date,
          cw.contract_id
        into snap
        from public.timesheets_financials tf
        join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
        left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
        join public.v_ts_invoice_precheck pcv on pcv.timesheet_id = tf.timesheet_id
        where tf.id = v_tsfin_id
          and tf.is_current = true
          and tf.client_id = v_inv.client_id
          and upper(coalesce(pcv.precheck_status,''))
            in ('OK','BLOCK_NO_PDF')
        limit 1;

        if not found then
          raise exception 'Segment add failed eligibility (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        natural_start := (snap.week_ending_date::date - 6);

        -- Locate the segment object
        v_seg := null;
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;
          if nullif(btrim(coalesce(v_seg->>'segment_id','')), '') = v_seg_id then
            exit;
          end if;
          v_seg := null;
        end loop;

        if v_seg is null then
          raise exception 'Segment not found (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
        if seg_locked is not null then
          raise exception 'Segment already invoiced (tsfin_id=% segment_id=%)', v_tsfin_id, v_seg_id;
        end if;

        seg_target := nullif(btrim(coalesce(v_seg->>'invoice_target_week_start','')), '')::date;
        seg_ref := btrim(coalesce(v_seg->>'ref_num',''));

        -- segment-level ref gating if required
        select * into pc from public.v_ts_invoice_precheck where timesheet_id = snap.timesheet_id limit 1;
        if pc.require_reference_to_invoice is true and seg_ref = '' then
          raise exception 'Segment missing reference number (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
        end if;

        -- Week eligibility
        if seg_target is null or seg_target = natural_start then
          if v_week_start <> natural_start then
            raise exception 'Segment not eligible for this invoice week (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
        else
          if v_week_start <> seg_target then
            raise exception 'Delayed segment not eligible for this invoice week (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
          if seg_target > v_anchor_ymd then
            raise exception 'Delayed segment cannot be invoiced early (timesheet_id=% segment_id=%)', snap.timesheet_id, v_seg_id;
          end if;
        end if;

        v_seg_refs_to_lock := v_seg_refs_to_lock || jsonb_build_array(
          jsonb_build_object(
            'tsfin_id', v_tsfin_id::text,
            'segment_id', v_seg_id
          )
        );
      end loop;

      if jsonb_typeof(v_seg_refs_to_lock) = 'array' and jsonb_array_length(v_seg_refs_to_lock) > 0 then
        perform public._inv_lock_segments_for_invoice(p_invoice_id, v_seg_refs_to_lock);
      end if;
    end if;

      -- Apply remove_segment_refs (unlock selected segments on THIS invoice)
    if v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0 then
      perform public._inv_unlock_segment_refs_for_invoice(p_invoice_id, v_remove_seg_refs::jsonb, p_actor_user_id);
    end if;



    -- History: segment ops (always)
    if v_add_seg_refs is not null and jsonb_typeof(v_add_seg_refs)='array' and jsonb_array_length(v_add_seg_refs) > 0 then
      perform public._audit_insert(
        'invoices',
        p_invoice_id::text,
        'INVOICE_SEGMENTS_ADDED',
        null,
        jsonb_build_object('add_segment_refs', v_add_seg_refs),
        null,
        p_actor_user_id
      );
    end if;
    if v_remove_seg_refs is not null and jsonb_typeof(v_remove_seg_refs)='array' and jsonb_array_length(v_remove_seg_refs) > 0 then
      perform public._audit_insert(
        'invoices',
        p_invoice_id::text,
        'INVOICE_SEGMENTS_REMOVED',
        null,
        jsonb_build_object('remove_segment_refs', v_remove_seg_refs),
        null,
        p_actor_user_id
      );
    end if;

    -- Rebuild HOURS lines for touched timesheets on this invoice
    select array_agg(distinct tf.timesheet_id)
    into v_seg_ts_ids
    from public.timesheets_financials tf
    where tf.id = any(v_seg_tsfin_ids);

    v_seg_ts_ids := coalesce(v_seg_ts_ids, array[]::uuid[]);

    foreach tsid in array v_seg_ts_ids loop
      if tsid is null then
        continue;
      end if;

      -- Load snapshot + timesheet + contract (no READY_FOR_INVOICE restriction; this is an invoice edit)
      select
        tf.*,
        tsr.booking_id,
        tsr.week_ending_date,
        tsr.reference_number,
        tsr.sheet_scope::text as sheet_scope,
        coalesce(tsr.submission_mode::text,'') as submission_mode,
        tsr.day_references_json,
        tsr.actual_schedule_json,
        cw.contract_id
      into snap
      from public.timesheets_financials tf
      join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
      left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
      where tf.timesheet_id = tsid
        and tf.is_current = true
      limit 1;

      if not found then
        v_dbg_add_timesheets_skipped := v_dbg_add_timesheets_skipped + 1;
        if v_invoice_debug then
          v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_skipped','timesheet_id',tsid::text));
        end if;
        continue;
      end if;

      v_dbg_add_timesheets_found := v_dbg_add_timesheets_found + 1;
      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_loaded','timesheet_id',tsid::text,'tsfin_id',snap.id::text));
      end if;

      select v.r2_key
      into v_exact_timesheet_document_r2_key
      from public.timesheets t
      join public.invoice_document_versions v
        on v.entity_type='TIMESHEET'
       and v.entity_id=t.timesheet_id
       and v.purpose='TIMESHEET'
       and v.source_revision=t.document_revision::text
       and v.status='READY'
       and nullif(v.r2_key,'') is not null
       and nullif(v.sha256,'') is not null
       and coalesce(v.size_bytes,0)>0
       and coalesce(v.page_count,0)>0
      where t.timesheet_id=tsid and t.is_current
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1;


      contract_id := snap.contract_id;
      c_daily_calc := false;
      c_bucket_labels := null;
      c_display_site := null;

      if contract_id is not null then
        select
          nullif(btrim(coalesce(display_site,'')), '')
        into
          c_display_site
        from public.contracts
        where id = contract_id
        limit 1;
      end if;

      v_settings_authority := private._timesheet_settings_authority_frozen_v1(tsid);
      c_daily_calc := coalesce(
        (v_settings_authority#>>'{values,daily_calc_of_invoices}')::boolean,
        false
      );
      c_bucket_labels := case
        when coalesce((v_settings_authority->>'override_client_settings')::boolean,false)
          then v_settings_authority#>'{values,bucket_labels_json}'
        else null
      end;

      if c_bucket_labels is null then
        c_bucket_labels := jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH');
      end if;

      -- Build segment set locked to THIS invoice
      segments := '[]'::jsonb;
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
         and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
      then
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
          if seg_locked = p_invoice_id::text then
            segments := segments || jsonb_build_array(v_seg);
          end if;
        end loop;
      end if;

      if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
        -- If no segments remain on this invoice for this timesheet, remove ALL invoice lines for that timesheet
        delete from public.invoice_lines
        where invoice_id = p_invoice_id
          and timesheet_id = tsid;
        v_dbg_seg_timesheets_removed := v_dbg_seg_timesheets_removed + 1;
        continue;
      end if;

      v_dbg_seg_timesheets_rebuilt := v_dbg_seg_timesheets_rebuilt + 1;

      -- Replace HOURS lines for this timesheet on this invoice
      delete from public.invoice_lines
      where invoice_id = p_invoice_id
        and timesheet_id = tsid
        and upper(coalesce(meta_json->>'line_type','')) in ('HOURS_WEEKLY','HOURS_DAILY');
        -- HOURS lines
        if c_daily_calc then
          -- Daily: group by segment.date
          for r_day in
            with rows as (
              select
                nullif(btrim(coalesce(seg_el->>'date','')), '') as ymd,
                coalesce((seg_el->>'hours_day')::numeric,0)   as h_day,
                coalesce((seg_el->>'hours_night')::numeric,0) as h_night,
                coalesce((seg_el->>'hours_sat')::numeric,0)   as h_sat,
                coalesce((seg_el->>'hours_sun')::numeric,0)   as h_sun,
                coalesce((seg_el->>'hours_bh')::numeric,0)    as h_bh,
                coalesce((seg_el->>'pay_amount')::numeric,0)  as pay_ex,
                coalesce((seg_el->>'charge_amount')::numeric,0) as chg_ex
              from jsonb_array_elements(segments) seg_el
            ),
            agg as (
              select
                ymd,
                sum(rows.h_day)::numeric as hours_day,
                sum(rows.h_night)::numeric as hours_night,
                sum(rows.h_sat)::numeric as hours_sat,
                sum(rows.h_sun)::numeric as hours_sun,
                sum(rows.h_bh)::numeric as hours_bh,
                sum(rows.pay_ex)::numeric as pay_ex,
                sum(rows.chg_ex)::numeric as chg_ex
              from rows
              where ymd is not null and ymd ~ '^\d{4}-\d{2}-\d{2}$'
              group by ymd
            )
            select * from agg order by ymd
          loop
          chg_ex := public._inv_round2(r_day.chg_ex);
if chg_ex = 0 then continue; end if;

if (coalesce(r_day.hours_day,0)+coalesce(r_day.hours_night,0)+coalesce(r_day.hours_sat,0)+coalesce(r_day.hours_sun,0)+coalesce(r_day.hours_bh,0)) = 0 then
  continue;
end if;


            pay_ex := public._inv_round2(r_day.pay_ex);
            margin_ex := public._inv_round2(chg_ex - pay_ex);
            vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
            inc_amt := public._inv_round2(chg_ex + vat_amt);

            line_desc := coalesce(nullif(btrim(coalesce(c_display_site,'')) ,''), ('TS '||tsid::text)) ||
                         ' – '|| r_day.ymd || ' – W/E '|| coalesce(snap.week_ending_date::text,'');

            v_meta := jsonb_build_object(
              'line_type','HOURS_DAILY',
              'timesheet_id', tsid::text,
              'tsfin_id', snap.id::text,
              'candidate_display', coalesce(nullif(btrim(coalesce(c_display_site,'')),''), null),
              'role', c_role,
              'hospital', c_display_site,
              'ward', c_ward_hint,
              'week_ending_date', snap.week_ending_date::text,
              'date', r_day.ymd,
              'bucket_labels', c_bucket_labels
            );

            v_source_key := 'TS:' || tsid::text || ':HOURS:' || r_day.ymd;

            insert into public.invoice_lines(
              invoice_id, timesheet_id, booking_id, description,
              hours_day, hours_night, hours_sat, hours_sun, hours_bh,
              pay_day, pay_night, pay_sat, pay_sun, pay_bh,
              charge_day, charge_night, charge_sat, charge_sun, charge_bh,
              total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
              vat_rate_pct, vat_amount, total_inc_vat,
              paper_ts_r2_key, meta_json, source_key
            )
            values (
              p_invoice_id, tsid, snap.booking_id, line_desc,
              public._inv_round2(r_day.hours_day), public._inv_round2(r_day.hours_night), public._inv_round2(r_day.hours_sat), public._inv_round2(r_day.hours_sun), public._inv_round2(r_day.hours_bh),
              null,null,null,null,null,
              null,null,null,null,null,
              pay_ex, chg_ex, margin_ex,
              v_vat_rate, vat_amt, inc_amt,
              v_exact_timesheet_document_r2_key,
              v_meta,
              v_source_key
            )
            on conflict (invoice_id, source_key) do nothing;
          end loop;
        else
          -- Weekly hours line
          select
            public._inv_round2(coalesce(sum((seg_el->>'hours_day')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_night')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_sat')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_sun')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'hours_bh')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'pay_amount')::numeric),0)),
            public._inv_round2(coalesce(sum((seg_el->>'charge_amount')::numeric),0))
          into h_day, h_night, h_sat, h_sun, h_bh, pay_ex, chg_ex
          from jsonb_array_elements(segments) seg_el;

       if chg_ex <> 0 and (coalesce(h_day,0)+coalesce(h_night,0)+coalesce(h_sat,0)+coalesce(h_sun,0)+coalesce(h_bh,0)) <> 0 then
  margin_ex := public._inv_round2(chg_ex - pay_ex);
  vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
  inc_amt := public._inv_round2(chg_ex + vat_amt);

  line_desc := coalesce(nullif(btrim(coalesce(c_display_site,'')) ,''), ('TS '||tsid::text)) ||
               ' – W/E '|| coalesce(snap.week_ending_date::text,'');

  v_meta := jsonb_build_object(
    'line_type','HOURS_WEEKLY',
    'timesheet_id', tsid::text,
    'tsfin_id', snap.id::text,
    'week_ending_date', snap.week_ending_date::text,
    'bucket_labels', c_bucket_labels
  );

  v_source_key := 'TS:' || tsid::text || ':HOURS:WEEK';

  insert into public.invoice_lines(
    invoice_id, timesheet_id, booking_id, description,
    hours_day, hours_night, hours_sat, hours_sun, hours_bh,
    pay_day, pay_night, pay_sat, pay_sun, pay_bh,
    charge_day, charge_night, charge_sat, charge_sun, charge_bh,
    total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
    vat_rate_pct, vat_amount, total_inc_vat,
    paper_ts_r2_key, meta_json, source_key
  )
  values (
    p_invoice_id, tsid, snap.booking_id, line_desc,
    h_day, h_night, h_sat, h_sun, h_bh,
    null,null,null,null,null,
    null,null,null,null,null,
    pay_ex, chg_ex, margin_ex,
    v_vat_rate, vat_amt, inc_amt,
    v_exact_timesheet_document_r2_key,
    v_meta,
    v_source_key
  )
  on conflict (invoice_id, source_key) do nothing;
end if;

        end if;

        -- Additional rates


    end loop;
  end if;
end if;

  -- 2) Add adjustments
  if p_payload is not null and jsonb_typeof(p_payload) = 'object' and (p_payload ? 'add_adjustments') then
    if jsonb_typeof(p_payload->'add_adjustments') = 'array' then
      for adj in
        select value from jsonb_array_elements(p_payload->'add_adjustments') value
      loop
        if adj is null or jsonb_typeof(adj) <> 'object' then
          continue;
        end if;

        v_adj_token := nullif(btrim(coalesce(adj->>'client_token','')), '');
        v_adj_desc  := nullif(btrim(coalesce(adj->>'description','')), '');
        begin
          v_adj_ex := (adj->>'amount_ex_vat')::numeric;
        exception when others then
          v_adj_ex := null;
        end;

        if v_adj_token is null or v_adj_desc is null or v_adj_ex is null then
          continue;
        end if;

        v_adj_vat := public._inv_round2(v_adj_ex * v_vat_rate / 100);
        if v_vat_rate = 0 then v_adj_vat := 0; end if;
        v_adj_inc := public._inv_round2(v_adj_ex + v_adj_vat);

        v_adj_source_key := 'ADJ:' || v_adj_token;

        v_meta := jsonb_build_object(
          'line_type','ADJUSTMENT',
          'client_token', v_adj_token,
          'description', v_adj_desc,
          'amount_ex_vat', public._inv_round2(v_adj_ex),
          'vat_rate_pct', v_vat_rate,
          'vat_chargeable', v_vat_chargeable
        );

        v_hist_adj := v_hist_adj || jsonb_build_array(v_meta);

        insert into public.invoice_lines(
          invoice_id, timesheet_id, booking_id, description,
          hours_day, hours_night, hours_sat, hours_sun, hours_bh,
          pay_day, pay_night, pay_sat, pay_sun, pay_bh,
          charge_day, charge_night, charge_sat, charge_sun, charge_bh,
          total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
          vat_rate_pct, vat_amount, total_inc_vat,
          paper_ts_r2_key, meta_json, source_key
        )
        values (
          p_invoice_id, null, null, v_adj_desc,
          0,0,0,0,0,
          null,null,null,null,null,
          null,null,null,null,null,
          0, public._inv_round2(v_adj_ex), public._inv_round2(v_adj_ex),
          v_vat_rate, v_adj_vat, v_adj_inc,
          null,
          v_meta,
          v_adj_source_key
        )
        on conflict (invoice_id, source_key) do nothing;
      end loop;
    end if;
  end if;

  -- History: adjustments added (always)
  if jsonb_typeof(v_hist_adj)='array' and jsonb_array_length(v_hist_adj) > 0 then
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_ADJUSTMENTS_ADDED',
      null,
      jsonb_build_object('adjustments', v_hist_adj),
      null,
      p_actor_user_id
    );
  end if;


  -- 3) Add timesheets (full parity: hours + additional + expenses + mileage), for THIS invoice week_start
  if v_add_ts_ids is not null and coalesce(array_length(v_add_ts_ids,1),0) > 0 then
    foreach tsid in array v_add_ts_ids loop
      if tsid is null then
        continue;
      end if;

      -- Load snapshot + timesheet + precheck
      select
        tf.*,
        tsr.booking_id,
        tsr.week_ending_date,
        tsr.reference_number,
        tsr.sheet_scope::text as sheet_scope,
        coalesce(tsr.submission_mode::text,'') as submission_mode,
        tsr.day_references_json,
        tsr.actual_schedule_json,
        cw.contract_id
      into snap
      from public.timesheets_financials tf
      join public.timesheets tsr on tsr.timesheet_id = tf.timesheet_id and tsr.is_current = true
      left join public.contract_weeks cw on cw.timesheet_id = tf.timesheet_id
      join public.v_ts_invoice_precheck pcv on pcv.timesheet_id = tf.timesheet_id
      where tf.timesheet_id = tsid
        and tf.is_current = true
        and tf.locked_by_invoice_id is null
        and tf.processing_status = 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
        and upper(coalesce(pcv.precheck_status,''))
          in ('OK','BLOCK_NO_PDF')
        and tf.client_id = v_inv.client_id
        and (
          pcv.require_reference_to_invoice is not true
          or public._inv_timesheet_has_invoice_reference(
                tsr.sheet_scope::text,
                coalesce(tsr.submission_mode::text,''),
                tsr.reference_number,
                tsr.day_references_json,
                tsr.actual_schedule_json
             )
        )
      limit 1;

      if not found then
        v_dbg_add_timesheets_skipped := v_dbg_add_timesheets_skipped + 1;
        if v_invoice_debug then
          v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_skipped','timesheet_id',coalesce(tsid::text,'')));
        end if;
        continue;
      end if;

      v_dbg_add_timesheets_found := v_dbg_add_timesheets_found + 1;
      if v_invoice_debug then
        v_dbg_steps := v_dbg_steps || jsonb_build_array(jsonb_build_object('step','add_timesheet_loaded','timesheet_id',coalesce(tsid::text,''),'tsfin_id',coalesce(snap.id::text,'')));
      end if;

      select v.r2_key
      into v_exact_timesheet_document_r2_key
      from public.timesheets t
      join public.invoice_document_versions v
        on v.entity_type='TIMESHEET'
       and v.entity_id=t.timesheet_id
       and v.purpose='TIMESHEET'
       and v.source_revision=t.document_revision::text
       and v.status='READY'
       and nullif(v.r2_key,'') is not null
       and nullif(v.sha256,'') is not null
       and coalesce(v.size_bytes,0)>0
       and coalesce(v.page_count,0)>0
      where t.timesheet_id=tsid and t.is_current
      order by v.ready_at_utc desc nulls last,v.id desc
      limit 1;
      contract_id := snap.contract_id;
      c_daily_calc := false;
      c_bucket_labels := null;
      c_role := null;
      c_display_site := null;
      c_ward_hint := null;

      if contract_id is not null then
        select
          nullif(btrim(coalesce(role,'')), ''),
          nullif(btrim(coalesce(display_site,'')), ''),
          nullif(btrim(coalesce(ward_hint,'')), '')
        into
          c_role, c_display_site, c_ward_hint
        from public.contracts
        where id = contract_id
        limit 1;
      end if;

      v_settings_authority := private._timesheet_settings_authority_frozen_v1(tsid);
      c_daily_calc := coalesce(
        (v_settings_authority#>>'{values,daily_calc_of_invoices}')::boolean,
        false
      );
      c_bucket_labels := case
        when coalesce((v_settings_authority->>'override_client_settings')::boolean,false)
          then v_settings_authority#>'{values,bucket_labels_json}'
        else null
      end;

      if c_bucket_labels is null then
        c_bucket_labels := jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH');
      end if;

      natural_start := (snap.week_ending_date::date - 6);

      segments := '[]'::jsonb;

      -- Build invoiceable segment set for THIS invoice week_start
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
         and jsonb_typeof(snap.invoice_breakdown_json->'segments')='array'
      then
        for v_seg in
          select value from jsonb_array_elements(snap.invoice_breakdown_json->'segments') value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_locked := nullif(btrim(coalesce(v_seg->>'invoice_locked_invoice_id','')), '');
          if seg_locked is not null then
            continue; -- already invoiced
          end if;

          seg_target := nullif(btrim(coalesce(v_seg->>'invoice_target_week_start','')), '')::date;
          seg_ref := btrim(coalesce(v_seg->>'ref_num',''));

          -- segment-level ref gating if required
          select * into pc from public.v_ts_invoice_precheck where timesheet_id = tsid limit 1;
          if pc.require_reference_to_invoice is true and seg_ref = '' then
            continue;
          end if;

          -- delayed detection
          if seg_target is null or seg_target = natural_start then
            -- not delayed: belongs to natural week only
            if v_week_start <> natural_start then
              continue;
            end if;
            -- allow early is implicit for invoice edits (invoice is already being edited)
            segments := segments || jsonb_build_array(v_seg);
          else
            -- delayed: only if this invoice week matches target AND target has arrived (no early invoicing for delayed)
            if v_week_start = seg_target and seg_target <= v_anchor_ymd then
              segments := segments || jsonb_build_array(v_seg);
            end if;
          end if;
        end loop;
      else
        -- Non-segments: include only when invoice week matches natural week
        if v_week_start = natural_start then
          segments := jsonb_build_array(
            jsonb_build_object(
              'segment_id', null,
              'date', coalesce(snap.week_ending_date::text, v_week_start::text),
              'hours_day', public._inv_round2(coalesce(snap.hours_day,0)),
              'hours_night', public._inv_round2(coalesce(snap.hours_night,0)),
              'hours_sat', public._inv_round2(coalesce(snap.hours_sat,0)),
              'hours_sun', public._inv_round2(coalesce(snap.hours_sun,0)),
              'hours_bh', public._inv_round2(coalesce(snap.hours_bh,0)),
              'pay_amount', public._inv_round2(
                coalesce(snap.total_pay_ex_vat,0)
                - coalesce(snap.additional_pay_ex_vat,0)
                - coalesce(snap.expenses_pay_ex_vat,0)
                - coalesce(snap.mileage_pay_ex_vat,0)
              ),
              'charge_amount', public._inv_round2(
                coalesce(snap.total_charge_ex_vat,0)
                - coalesce(snap.additional_charge_ex_vat,0)
                - coalesce(snap.expenses_charge_ex_vat,0)
                - coalesce(snap.mileage_charge_ex_vat,0)
              ),
              'ref_num', coalesce(snap.reference_number,'')
            )
          );
        end if;
      end if;

      if jsonb_array_length(coalesce(segments,'[]'::jsonb)) = 0 then
        continue;
      end if;

      -- Build the exact invoice-line economics from the frozen current financial snapshot.
      -- This mirrors Invoice Async V8 generation and never derives economics from mutable live rows.
      select p.vat_rate
      into v_vat_rate
      from private._invoice_generation_vat_policy_batch(jsonb_build_array(jsonb_build_object(
        'source_member_key','invoice-edit:'||tsid::text,
        'source_type','TIMESHEET',
        'source_id',tsid,
        'timesheet_id',tsid,
        'effective_date',snap.week_ending_date
      ))) p
      where p.source_member_key='invoice-edit:'||tsid::text
        and p.valid
        and p.vat_rate is not null
      limit 1;

      if not found then
        raise exception 'INVOICE_EDIT_VAT_POLICY_UNRESOLVED'
          using errcode='P0001',detail=jsonb_build_object(
            'invoice_id',p_invoice_id,'timesheet_id',tsid)::text;
      end if;

      insert into public.invoice_lines(
        invoice_id,timesheet_id,booking_id,description,
        hours_day,hours_night,hours_sat,hours_sun,hours_bh,
        pay_day,pay_night,pay_sat,pay_sun,pay_bh,
        charge_day,charge_night,charge_sat,charge_sun,charge_bh,
        total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,
        vat_rate_pct,vat_amount,total_inc_vat,
        paper_ts_r2_key,meta_json,source_key
      )
      with base as materialized (
        select coalesce(
          (select nullif(btrim(coalesce(cd.display_name,'')),'')
             from public.candidates cd where cd.id=snap.candidate_id limit 1),
          'TS '||tsid::text
        ) candidate_display
      ),
      segment_rows as materialized (
        select
          case when left(coalesce(s.value->>'date',''),10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
            then left(s.value->>'date',10) end work_date,
          case when pg_input_is_valid(s.value->>'hours_day','numeric') then (s.value->>'hours_day')::numeric else 0 end h_day,
          case when pg_input_is_valid(s.value->>'hours_night','numeric') then (s.value->>'hours_night')::numeric else 0 end h_night,
          case when pg_input_is_valid(s.value->>'hours_sat','numeric') then (s.value->>'hours_sat')::numeric else 0 end h_sat,
          case when pg_input_is_valid(s.value->>'hours_sun','numeric') then (s.value->>'hours_sun')::numeric else 0 end h_sun,
          case when pg_input_is_valid(s.value->>'hours_bh','numeric') then (s.value->>'hours_bh')::numeric else 0 end h_bh,
          case
            when pg_input_is_valid(s.value->>'pay_amount','numeric') then (s.value->>'pay_amount')::numeric
            when pg_input_is_valid(s.value->>'pay_ex_vat','numeric') then (s.value->>'pay_ex_vat')::numeric
            else 0 end pay_ex,
          case
            when pg_input_is_valid(s.value->>'charge_amount','numeric') then (s.value->>'charge_amount')::numeric
            when pg_input_is_valid(s.value->>'charge_ex_vat','numeric') then (s.value->>'charge_ex_vat')::numeric
            else 0 end charge_ex
        from jsonb_array_elements(segments) s(value)
      ),
      hour_daily as materialized (
        select s.work_date,sum(s.h_day) h_day,sum(s.h_night) h_night,sum(s.h_sat) h_sat,
          sum(s.h_sun) h_sun,sum(s.h_bh) h_bh,sum(s.pay_ex) pay_ex,sum(s.charge_ex) charge_ex
        from segment_rows s
        where c_daily_calc and s.work_date is not null
        group by s.work_date
      ),
      hour_weekly as materialized (
        select sum(s.h_day) h_day,sum(s.h_night) h_night,sum(s.h_sat) h_sat,
          sum(s.h_sun) h_sun,sum(s.h_bh) h_bh,sum(s.pay_ex) pay_ex,sum(s.charge_ex) charge_ex
        from segment_rows s
        having not c_daily_calc or not exists(select 1 from segment_rows d where d.work_date is not null)
      ),
      additional_source as materialized (
        select upper(a.key) code,a.value unit
        from jsonb_each(case when jsonb_typeof(snap.additional_units_json)='object'
          then snap.additional_units_json else '{}'::jsonb end) a
        where jsonb_typeof(a.value)='object' and btrim(a.key)<>''
      ),
      additional_daily as materialized (
        select a.code,left(d.key,10) work_date,
          case when pg_input_is_valid(d.value,'numeric') then d.value::numeric else 0 end units,
          case when pg_input_is_valid(a.unit->>'pay_rate','numeric') then (a.unit->>'pay_rate')::numeric else 0 end pay_rate,
          case when pg_input_is_valid(a.unit->>'charge_rate','numeric') then (a.unit->>'charge_rate')::numeric else 0 end charge_rate,
          coalesce(nullif(a.unit->>'bucket_name',''),a.code) bucket_name,
          coalesce(nullif(a.unit->>'unit_name',''),'units') unit_name,
          a.unit->'frequency' frequency
        from additional_source a
        cross join lateral jsonb_each_text(case when jsonb_typeof(a.unit->'days')='object'
          then a.unit->'days' else '{}'::jsonb end) d
        where c_daily_calc
          and left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
          and pg_input_is_valid(d.value,'numeric')
          and d.value::numeric<>0
          and exists(select 1 from segment_rows where work_date is not null)
      ),
      additional_weekly as materialized (
        select a.code,
          case when pg_input_is_valid(a.unit->>'unit_count','numeric') then (a.unit->>'unit_count')::numeric else 0 end units,
          case when pg_input_is_valid(a.unit->>'pay_rate','numeric') then (a.unit->>'pay_rate')::numeric else 0 end pay_rate,
          case when pg_input_is_valid(a.unit->>'charge_rate','numeric') then (a.unit->>'charge_rate')::numeric else 0 end charge_rate,
          case when pg_input_is_valid(a.unit->>'pay_ex_vat','numeric') then (a.unit->>'pay_ex_vat')::numeric else 0 end pay_ex,
          case when pg_input_is_valid(a.unit->>'charge_ex_vat','numeric') then (a.unit->>'charge_ex_vat')::numeric else 0 end charge_ex,
          coalesce(nullif(a.unit->>'bucket_name',''),a.code) bucket_name,
          coalesce(nullif(a.unit->>'unit_name',''),'units') unit_name,
          a.unit->'frequency' frequency
        from additional_source a
        where not(c_daily_calc
          and exists(select 1 from jsonb_each_text(case when jsonb_typeof(a.unit->'days')='object'
            then a.unit->'days' else '{}'::jsonb end) d
            where left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(d.value,'numeric') and d.value::numeric<>0))
          and (
            (case when pg_input_is_valid(a.unit->>'pay_ex_vat','numeric') then (a.unit->>'pay_ex_vat')::numeric else 0 end)<>0
            or (case when pg_input_is_valid(a.unit->>'charge_ex_vat','numeric') then (a.unit->>'charge_ex_vat')::numeric else 0 end)<>0
          )
      ),
      expense_lines as materialized (
        select e.code,e.pay_ex,e.charge_ex
        from (values
          ('TRAVEL',coalesce(snap.travel_pay_ex_vat,0),coalesce(snap.travel_charge_ex_vat,0)),
          ('ACCOMMODATION',coalesce(snap.accommodation_pay_ex_vat,0),coalesce(snap.accommodation_charge_ex_vat,0)),
          ('OTHER',coalesce(snap.other_pay_ex_vat,0),coalesce(snap.other_charge_ex_vat,0)),
          ('EXPENSES_FALLBACK',
            case when coalesce(snap.travel_pay_ex_vat,0)+coalesce(snap.accommodation_pay_ex_vat,0)+coalesce(snap.other_pay_ex_vat,0)=0
              then coalesce(snap.expenses_pay_ex_vat,0) else 0 end,
            case when coalesce(snap.travel_charge_ex_vat,0)+coalesce(snap.accommodation_charge_ex_vat,0)+coalesce(snap.other_charge_ex_vat,0)=0
              then coalesce(snap.expenses_charge_ex_vat,0) else 0 end),
          ('MILEAGE',coalesce(snap.mileage_pay_ex_vat,0),coalesce(snap.mileage_charge_ex_vat,0))
        ) e(code,pay_ex,charge_ex)
        where e.pay_ex<>0 or e.charge_ex<>0
      ),
      line_union as materialized (
        select b.candidate_display||' - '||h.work_date||' - W/E '||coalesce(snap.week_ending_date::text,'' ) description,
          h.h_day,h.h_night,h.h_sat,h.h_sun,h.h_bh,h.pay_ex,h.charge_ex,
          'HOURS_DAILY' line_type,'TS:'||tsid::text||':HOURS:'||h.work_date source_key,
          jsonb_build_object('date',h.work_date) detail
        from hour_daily h cross join base b
        union all
        select b.candidate_display||' - W/E '||coalesce(snap.week_ending_date::text,''),
          h.h_day,h.h_night,h.h_sat,h.h_sun,h.h_bh,h.pay_ex,h.charge_ex,
          'HOURS_WEEKLY','TS:'||tsid::text||':HOURS:WEEK','{}'::jsonb
        from hour_weekly h cross join base b
        union all
        select b.candidate_display||' - '||a.bucket_name||' - '||a.work_date||' - '||a.units||' '||a.unit_name,
          0,0,0,0,0,round(a.units*a.pay_rate,2),round(a.units*a.charge_rate,2),
          'ADDITIONAL_RATE_DAILY','TS:'||tsid::text||':ADD:'||a.code||':'||a.work_date,
          jsonb_build_object('date',a.work_date,'bucket',jsonb_build_object(
            'code',a.code,'bucket_name',a.bucket_name,'unit_name',a.unit_name,'frequency',a.frequency),
            'units',jsonb_build_object('unit_count',a.units,'pay_rate',a.pay_rate,'charge_rate',a.charge_rate))
        from additional_daily a cross join base b
        union all
        select b.candidate_display||' - '||a.bucket_name||' - '||a.units||' '||a.unit_name,
          0,0,0,0,0,a.pay_ex,a.charge_ex,
          'ADDITIONAL_RATE','TS:'||tsid::text||':ADD:'||a.code||':WEEK',
          jsonb_build_object('bucket',jsonb_build_object(
            'code',a.code,'bucket_name',a.bucket_name,'unit_name',a.unit_name,'frequency',a.frequency),
            'units',jsonb_build_object('unit_count',a.units,'pay_rate',a.pay_rate,'charge_rate',a.charge_rate))
        from additional_weekly a cross join base b
        union all
        select case when e.code='MILEAGE' then 'Mileage - '||coalesce(snap.mileage_units,0)||' miles (W/E '||coalesce(snap.week_ending_date::text,'')||')'
          when e.code='EXPENSES_FALLBACK' then 'Expenses (W/E '||coalesce(snap.week_ending_date::text,'')||')'
          else initcap(replace(e.code,'_',' '))||' expenses (W/E '||coalesce(snap.week_ending_date::text,'')||')' end,
          0,0,0,0,0,e.pay_ex,e.charge_ex,
          case when e.code='MILEAGE' then 'MILEAGE'
            when e.code='EXPENSES_FALLBACK' then 'EXPENSES_TOTAL'
            else 'EXPENSE_'||e.code end,
          case when e.code='MILEAGE' then 'TS:'||tsid::text||':MILEAGE'
            when e.code='EXPENSES_FALLBACK' then 'TS:'||tsid::text||':EXP:TOTAL'
            else 'TS:'||tsid::text||':EXP:'||e.code end,
          jsonb_build_object('expense',case when e.code='MILEAGE' then jsonb_build_object(
            'category','MILEAGE','mileage_units',snap.mileage_units,
            'pay_rate',snap.mileage_pay_rate,'charge_rate',snap.mileage_charge_rate,
            'evidence_r2_key',snap.mileage_evidence_r2_key,'evidence_manifest',snap.mileage_evidence_manifest)
            else jsonb_build_object('category',e.code,'note',snap.expenses_description,
              'evidence_r2_key',snap.expenses_evidence_r2_key,'evidence_manifest',snap.expenses_evidence_manifest) end)
        from expense_lines e
      )
      select p_invoice_id,tsid,snap.booking_id,l.description,
        round(l.h_day,2),round(l.h_night,2),round(l.h_sat,2),round(l.h_sun,2),round(l.h_bh,2),
        null,null,null,null,null,
        snap.charge_day,snap.charge_night,snap.charge_sat,snap.charge_sun,snap.charge_bh,
        round(l.pay_ex,2),round(l.charge_ex,2),round(l.charge_ex-l.pay_ex,2),v_vat_rate,
        round(l.charge_ex*v_vat_rate/100,2),round(l.charge_ex+(l.charge_ex*v_vat_rate/100),2),
        v_exact_timesheet_document_r2_key,
        jsonb_build_object('line_type',l.line_type,'timesheet_id',tsid,'tsfin_id',snap.id,
          'candidate_display',l.description,'week_ending_date',snap.week_ending_date,
          'role',c_role,'hospital',c_display_site,'ward',c_ward_hint,'bucket_labels',c_bucket_labels,
          'totals',jsonb_build_object('line_pay_ex_vat',round(l.pay_ex,2),
            'line_charge_ex_vat',round(l.charge_ex,2),'margin_ex_vat',round(l.charge_ex-l.pay_ex,2),
            'vat_rate_pct',v_vat_rate,'vat_amount',round(l.charge_ex*v_vat_rate/100,2),
            'total_inc_vat',round(l.charge_ex+(l.charge_ex*v_vat_rate/100),2)))||l.detail,
        l.source_key
      from line_union l
      on conflict(invoice_id,source_key) do nothing;
      -- Build segment refs to lock
      if snap.invoice_breakdown_json is not null
         and jsonb_typeof(snap.invoice_breakdown_json)='object'
         and coalesce(snap.invoice_breakdown_json->>'mode','')='SEGMENTS'
      then
        for v_seg in
          select value from jsonb_array_elements(segments) value
        loop
          if v_seg is null or jsonb_typeof(v_seg) <> 'object' then
            continue;
          end if;

          seg_refs := seg_refs || jsonb_build_array(
            jsonb_build_object(
              'tsfin_id', snap.id::text,
              'segment_id', nullif(btrim(coalesce(v_seg->>'segment_id','')), '')
            )
          );
        end loop;
      else
        -- lock whole for non-segments
        seg_refs := seg_refs || jsonb_build_array(
          jsonb_build_object('tsfin_id', snap.id::text, 'segment_id', null)
        );
      end if;
    end loop;

    -- Apply segment locks for the exact selected source rows.
    if jsonb_typeof(seg_refs) = 'array' and jsonb_array_length(seg_refs) > 0 then
      perform public._inv_lock_segments_for_invoice(p_invoice_id, seg_refs);
    end if;

    -- History: timesheets added (always; includes requested ids)
    perform public._audit_insert(
      'invoices',
      p_invoice_id::text,
      'INVOICE_TIMESHEETS_ADDED',
      null,
      jsonb_build_object('add_timesheet_ids', coalesce(to_jsonb(v_add_ts_ids), '[]'::jsonb)),
      null,
      p_actor_user_id
    );
  end if;

  -- 3c) Contract week status: set INVOICED only when timesheet is FULLY invoiced (segment-aware), and revert INVOICED -> AUTHORISED if no longer fully invoiced.
  -- Touch set = union of: add_timesheet_ids, line-removal touched (hours), segment-op touched.
  v_cw_ts_ids := array[]::uuid[];
  if v_add_ts_ids is not null and coalesce(array_length(v_add_ts_ids,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_add_ts_ids;
  end if;
  if v_ts_ids_touched is not null and coalesce(array_length(v_ts_ids_touched,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_ts_ids_touched;
  end if;
  if v_seg_ts_ids is not null and coalesce(array_length(v_seg_ts_ids,1),0) > 0 then
    v_cw_ts_ids := v_cw_ts_ids || v_seg_ts_ids;
  end if;

  -- de-dup
  select array_agg(distinct x)
  into v_cw_ts_ids
  from unnest(coalesce(v_cw_ts_ids, array[]::uuid[])) x
  where x is not null;

  v_cw_ts_ids := coalesce(v_cw_ts_ids, array[]::uuid[]);

  if coalesce(array_length(v_cw_ts_ids,1),0) > 0 then
    with src as (
      select
        cw.timesheet_id,
        cw.status as cw_status,
        tf.locked_by_invoice_id,
        tf.invoice_breakdown_json,
        (
          case
            when tf.invoice_breakdown_json is not null
             and jsonb_typeof(tf.invoice_breakdown_json)='object'
             and coalesce(tf.invoice_breakdown_json->>'mode','')='SEGMENTS'
             and jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
             and jsonb_array_length(tf.invoice_breakdown_json->'segments') > 0
            then
              not exists (
                select 1
                from jsonb_array_elements(tf.invoice_breakdown_json->'segments') s(seg)
                where nullif(btrim(coalesce(s.seg->>'invoice_locked_invoice_id','')), '') is null
              )
            else
              (tf.locked_by_invoice_id is not null)
          end
        ) as fully_invoiced
      from public.contract_weeks cw
      join public.timesheets_financials tf
        on tf.is_current = true
       and tf.timesheet_id = cw.timesheet_id
      where cw.timesheet_id = any(v_cw_ts_ids)
    )
    update public.contract_weeks cw
    set status = case
      when src.fully_invoiced then 'INVOICED'::public.contract_week_status_enum
      when cw.status = 'INVOICED'::public.contract_week_status_enum then 'AUTHORISED'::public.contract_week_status_enum
      else cw.status
    end
    from src
    where cw.timesheet_id = src.timesheet_id;
  end if;


  -- 4) Recompute invoice totals from invoice_lines and clear PDF key
  select
    public._inv_round2(coalesce(sum(coalesce(l.total_charge_ex_vat,0)),0)),
    public._inv_round2(coalesce(sum(coalesce(l.vat_amount,0)),0)),
    public._inv_round2(coalesce(sum(coalesce(l.total_inc_vat,0)),0))
  into v_new_ex, v_new_vat, v_new_inc
  from public.invoice_lines l
  where l.invoice_id = p_invoice_id;


  perform public.invoice_recompute_totals(p_invoice_id);

  -- Recompute header_snapshot_json.meta counters to avoid stale values after edits
  select count(distinct l.timesheet_id)
  into v_hdr_ts_count_lines
  from public.invoice_lines l
  where l.invoice_id = p_invoice_id
    and l.timesheet_id is not null;

  select count(*)
  into v_hdr_seg_locked_count
  from public.timesheets_financials tf
  cross join lateral jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) as seg(seg_obj)
  where tf.is_current = true
    and coalesce(seg.seg_obj->>'invoice_locked_invoice_id','') = p_invoice_id::text;

  select count(distinct tf.timesheet_id)
  into v_hdr_ts_count_seglocks
  from public.timesheets_financials tf
  where tf.is_current = true
    and exists (
      select 1
      from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) as seg(seg_obj)
      where coalesce(seg.seg_obj->>'invoice_locked_invoice_id','') = p_invoice_id::text
    );

  if coalesce(v_hdr_seg_locked_count,0) > 0 then
    v_hdr_meta_timesheet_count := coalesce(v_hdr_ts_count_seglocks,0);
    v_hdr_meta_segment_count := coalesce(v_hdr_seg_locked_count,0);
  else
    v_hdr_meta_timesheet_count := coalesce(v_hdr_ts_count_lines,0);
    v_hdr_meta_segment_count := coalesce(v_hdr_meta_timesheet_count,0);
  end if;

  -- The statement triggers are the sole document/issue invalidation authority.
  -- This update changes only the authoritative business snapshot counters.
  update public.invoices invu
  set header_snapshot_json=jsonb_set(jsonb_set(coalesce(invu.header_snapshot_json,'{}'::jsonb),
      '{meta,timesheet_count}',to_jsonb(v_hdr_meta_timesheet_count),true),
      '{meta,segment_count}',to_jsonb(v_hdr_meta_segment_count),true),
    updated_at=now()
  where invu.id=p_invoice_id;

-- Refresh invoice-level NHSP/HR cache after timesheet/segment changes
  if coalesce(v_refresh_hr_cache,false) = true then
    perform 1
    from public.invoice_source_rows_collect(p_invoice_id, true) sr
    limit 1;
  end if;

  -- Revalidate ownership after every line and segment move in this Save. A
  -- source edit must not queue work for a source that was detached later in the
  -- same transaction, and every edited SEGMENTS identity must still be locked
  -- to this exact invoice.
  if cardinality(v_source_changed_ts_ids)>0 and exists(
    select 1
    from jsonb_each(v_source_updates_map) desired
    where (desired.value->>'timesheet_id')::uuid=any(v_source_changed_ts_ids)
      and not exists(
        select 1 from public.invoice_lines carrier
        where carrier.invoice_id=p_invoice_id
          and (
            carrier.timesheet_id=(desired.value->>'timesheet_id')::uuid
            or (
              carrier.timesheet_id is null
              and coalesce(carrier.meta_json->>'timesheet_id','')~
                '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              and (carrier.meta_json->>'timesheet_id')::uuid=
                (desired.value->>'timesheet_id')::uuid
            )
          )
      )
      and not exists(
        select 1
        from public.timesheets_financials tf
        cross join lateral jsonb_array_elements(
          coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) seg(value)
        where tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
          and tf.is_current
          and nullif(btrim(coalesce(
            seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
      )
  ) then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND',
      detail=jsonb_build_object('reason','POST_EDIT_SOURCE_DETACHED')::text;
  end if;

  if cardinality(v_source_changed_ts_ids)>0 and exists(
    select 1
    from jsonb_each(v_source_updates_map) desired
    cross join lateral jsonb_array_elements(
      coalesce(desired.value->'segment_updates','[]'::jsonb)) requested(value)
    where desired.value->>'source_mode'='SEGMENTS'
      and not exists(
        select 1
        from public.timesheets_financials tf
        cross join lateral jsonb_array_elements(
          coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) seg(value)
        where tf.id=(desired.value->>'financial_id')::uuid
          and tf.is_current
          and tf.timesheet_id=(desired.value->>'timesheet_id')::uuid
          and nullif(btrim(coalesce(
            seg.value->>'invoice_locked_invoice_id','')),'')=p_invoice_id::text
          and (
            (
              nullif(requested.value->>'segment_id','') is not null
              and nullif(btrim(coalesce(seg.value->>'segment_id','')),'')
                =nullif(requested.value->>'segment_id','')
            ) or (
              nullif(requested.value->>'segment_id','') is null
              and coalesce(seg.value->>'start_utc',seg.value->>'start')
                is not distinct from requested.value->>'start_identity'
              and coalesce(seg.value->>'end_utc',seg.value->>'end')
                is not distinct from requested.value->>'end_identity'
            )
          )
      )
  ) then
    raise exception using errcode='22023',
      message='INVOICE_SOURCE_EDIT_CONFLICTING_COMMAND',
      detail=jsonb_build_object('reason','POST_EDIT_SEGMENT_DETACHED')::text;
  end if;

  -- A material source edit always starts or reuses the exact replacement
  -- timesheet work. Replacement of an existing invoice preview is derived from
  -- the locked pre-edit V8 state; browser flags cannot suppress it.
  if cardinality(v_source_changed_ts_ids)>0 then
    select coalesce(jsonb_agg(jsonb_build_object(
      'command_type','VIEW_TIMESHEET_DOCUMENT',
      'timesheet_id',changed_id,
      'purpose','TIMESHEET',
      'priority_reason','SOURCE_EDIT_REPLACEMENT',
      'template_version','timesheet-professional-v2')
      order by changed_id),'[]'::jsonb)
    into v_document_commands
    from unnest(v_source_changed_ts_ids) changed_id;

    v_source_edit_invoice_replacement_required:=
      v_source_edit_preexisting_preview
      or lower(coalesce(p_payload->>'request_preview','false'))
           in('true','1','yes','on');
    if v_source_edit_invoice_replacement_required then
      v_document_commands:=v_document_commands||jsonb_build_array(
        jsonb_build_object(
          'command_type','VIEW_INVOICE_DOCUMENT',
          'invoice_id',p_invoice_id,
          'purpose','DRAFT_PREVIEW',
          'priority_reason',case when v_source_edit_preexisting_preview
            then 'SOURCE_EDIT_REPLACEMENT' else 'VIEW_NOW' end,
          'template_version','invoice-professional-v2'));
    end if;

    v_expected_command_count:=jsonb_array_length(v_document_commands);
    if v_expected_command_count>1000 then
      raise exception using errcode='22023',
        message='INVOICE_SOURCE_EDIT_TOO_MANY_REPLACEMENTS';
    end if;

    v_started_operations:=public.invoice_operation_start_batch(
      v_document_commands,p_actor_user_id,v_now);

    if jsonb_typeof(v_started_operations)<>'array'
       or jsonb_array_length(v_started_operations)<>v_expected_command_count then
      raise exception using errcode='55000',
        message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
        detail=jsonb_build_object(
          'reason','RESULT_COUNT',
          'expected',v_expected_command_count,
          'actual',case when jsonb_typeof(v_started_operations)='array'
            then jsonb_array_length(v_started_operations) else null end)::text;
    end if;

    for v_command_no in 1..v_expected_command_count loop
      select value into v_operation_result
      from jsonb_array_elements(v_started_operations) value
      where coalesce(value->>'command_no','')~'^[1-9][0-9]*$'
        and (value->>'command_no')::int=v_command_no;

      if not found or (
        select count(*)
        from jsonb_array_elements(v_started_operations) value
        where coalesce(value->>'command_no','')~'^[1-9][0-9]*$'
          and (value->>'command_no')::int=v_command_no
      )<>1 then
        raise exception using errcode='55000',
          message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
          detail=jsonb_build_object('reason','COMMAND_NO','command_no',v_command_no)::text;
      end if;

      v_source_update:=v_document_commands->(v_command_no-1);
      v_command_type:=v_source_update->>'command_type';
      if v_operation_result->>'command_type' is distinct from v_command_type
         or lower(coalesce(v_operation_result->>'accepted','false'))
              not in('true','1','yes','on')
         or lower(coalesce(v_operation_result->>'blocked','false'))
              in('true','1','yes','on') then
        raise exception using errcode='55000',
          message=case
            when lower(coalesce(v_operation_result->>'blocked','false'))
                   in('true','1','yes','on')
              then 'SOURCE_EDIT_REPLACEMENT_BLOCKED'
            else 'SOURCE_EDIT_REPLACEMENT_REJECTED' end,
          detail=jsonb_build_object(
            'command_no',v_command_no,
            'terminal_error',v_operation_result->'terminal_error')::text;
      end if;

      v_operation_status:=upper(coalesce(v_operation_result->>'status',''));
      v_operation_id:=case when coalesce(v_operation_result->>'operation_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (v_operation_result->>'operation_id')::uuid end;
      v_document_version_id:=case when coalesce(v_operation_result->>'document_version_id','')~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        then (v_operation_result->>'document_version_id')::uuid end;

      if v_operation_status='READY' then
        if v_document_version_id is null or v_operation_id is not null
           or not exists(
             select 1
             from public.invoice_document_versions dv
             where dv.id=v_document_version_id
               and dv.entity_type=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'INVOICE' end
               and dv.entity_id=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (v_source_update->>'timesheet_id')::uuid else p_invoice_id end
               and dv.purpose=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'DRAFT_PREVIEW' end
               and dv.source_revision=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (
                   select t.document_revision::text from public.timesheets t
                   where t.timesheet_id=(v_source_update->>'timesheet_id')::uuid
                     and t.is_current)
                 else (
                   select i.document_revision::text from public.invoices i
                   where i.id=p_invoice_id)
                 end
               and dv.template_version=v_source_update->>'template_version'
               and dv.status='READY'
               and nullif(btrim(coalesce(dv.r2_key,'')),'') is not null
               and nullif(btrim(coalesce(dv.sha256,'')),'') is not null
               and coalesce(dv.size_bytes,0)>0
               and coalesce(dv.page_count,0)>0
           ) then
          raise exception using errcode='55000',
            message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
            detail=jsonb_build_object(
              'reason','READY_IDENTITY','command_no',v_command_no)::text;
        end if;
      else
        if v_operation_id is null
           or v_operation_status not in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
           or not exists(
             select 1
             from public.invoice_operations op
             where op.id=v_operation_id
               and op.operation_type='BUILD_DOCUMENT'
               and op.entity_type=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then 'TIMESHEET' else 'INVOICE' end
               and op.entity_id=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (v_source_update->>'timesheet_id')::uuid else p_invoice_id end
               and op.source_revision=case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                 then (
                   select t.document_revision::text from public.timesheets t
                   where t.timesheet_id=(v_source_update->>'timesheet_id')::uuid
                     and t.is_current)
                 else (
                   select i.document_revision::text from public.invoices i
                   where i.id=p_invoice_id)
                 end
               and op.template_version=v_source_update->>'template_version'
               and coalesce(op.input_json->>'purpose','')=
                 case when v_command_type='VIEW_TIMESHEET_DOCUMENT'
                   then 'TIMESHEET' else 'DRAFT_PREVIEW' end
               and op.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
           ) then
          raise exception using errcode='55000',
            message='SOURCE_EDIT_REPLACEMENT_RESULT_INVALID',
            detail=jsonb_build_object(
              'reason','ACTIVE_IDENTITY','command_no',v_command_no)::text;
        end if;
      end if;

      v_validated_operations:=v_validated_operations||jsonb_build_array(v_operation_result);
    end loop;

    select coalesce(jsonb_agg(jsonb_build_object(
      'timesheet_id',t.timesheet_id,
      'document_revision',t.document_revision)
      order by t.timesheet_id),'[]'::jsonb)
    into v_source_changed_revisions
    from public.timesheets t
    where t.timesheet_id=any(v_source_changed_ts_ids) and t.is_current;
  end if;

-- Return compact state only; never build a manifest or PDF here.
  select jsonb_build_object('invoice_id',i.id,'status',i.status,
    'subtotal_ex_vat',i.subtotal_ex_vat,'vat_amount',i.vat_amount,'total_inc_vat',i.total_inc_vat,
    'document_revision',i.document_revision,'document_state',i.document_state,
    'preview_document_version_id',i.preview_document_version_id,
    'active_document_operation_id',i.active_document_operation_id,
    'issue_state',i.issue_state,'active_issue_operation_id',i.active_issue_operation_id,
    'reference_updates_applied',v_refupd_applied,
    'timesheet_location_updates_applied',v_location_applied,
    'timesheet_source_changed',
      cardinality(v_source_changed_ts_ids)>0,
    'source_edit_queue_contract',case when v_source_edit_requested
      then 'INVOICE_SOURCE_EDIT_QUEUE_V1' else null end,
    'changed_timesheet_ids',coalesce(to_jsonb(v_source_changed_ts_ids),'[]'::jsonb),
    'changed_timesheet_revisions',coalesce(v_source_changed_revisions,'[]'::jsonb),
    'source_edit_preexisting_preview',v_source_edit_preexisting_preview,
    'invoice_replacement_required',v_source_edit_invoice_replacement_required,
    'accepted_operations',coalesce(v_validated_operations,'[]'::jsonb),
    'document_queue_requested',jsonb_array_length(v_document_commands)>0)
  into v_manifest from public.invoices i where i.id=p_invoice_id;

  if v_invoice_debug then
    begin
      -- attach finish marker (avoid extra heavy queries here)
      v_dbg_steps := v_dbg_steps || jsonb_build_array(
        jsonb_build_object(
          'step','finish',
          'at_utc', public._inv_iso_utc(now()),
          'invoice_total_charge_ex_vat', v_new_ex,
          'invoice_vat_amount', v_new_vat,
          'invoice_total_inc_vat', v_new_inc
        )
      );

      v_dbg_stats := v_dbg_stats || jsonb_build_object(
        'lines_deleted', v_dbg_lines_deleted,
        'timesheets_unlocked_via_line_removal', v_dbg_timesheets_unlocked,
        'segment_add_refs', v_dbg_seg_add_refs,
        'segment_remove_refs', v_dbg_seg_remove_refs,
        'segment_tsfin_count', v_dbg_seg_tsfins,
        'segment_timesheets_rebuilt', v_dbg_seg_timesheets_rebuilt,
        'segment_timesheets_removed', v_dbg_seg_timesheets_removed,
        'add_timesheets_found', v_dbg_add_timesheets_found,
        'add_timesheets_skipped', v_dbg_add_timesheets_skipped
      );

      perform public._inv_write_audit(
        p_actor_user_id,
        'INVOICE_APPLY_EDITS_DEBUG',
        jsonb_build_object(
          'invoice_id', p_invoice_id::text,
          'week_start', v_week_start::text,
          'week_end', v_week_end::text,
          'stats', v_dbg_stats,
          'steps', v_dbg_steps
        ),
        'invoices',
        p_invoice_id::text,
        null,
        'INVOICE_DEBUG',
        null, null, null
      );
    exception when others then
      null;
    end;
  end if;

  perform public._ctms_assert_invoice_correction_lines_v1(
    p_invoice_id,p_actor_user_id,false,'INVOICE_APPLY_EDITS_RESULT'
  );

  IF v_correction_placement_ts_id IS NOT NULL THEN
    v_correction_placement_scope:=public.invoice_correction_pair_scope_v1(
      v_correction_placement_ts_id,null::uuid,p_actor_user_id,false,100);
    IF COALESCE((v_correction_placement_scope->>'valid')::boolean,false) IS NOT TRUE
       OR v_correction_placement_scope->>'placement_state' NOT IN (
         'COMPLETE_SAME_INVOICE','COMPLETE_SPLIT_INVOICES','INCOMPLETE_MOVE','UNPLACED') THEN
      RAISE EXCEPTION 'INVOICE_CORRECTION_PAIR_PLACEMENT_RESULT_INVALID'
        USING ERRCODE='P0001',DETAIL=v_correction_placement_scope::text;
    END IF;
    v_correction_placement_states:=jsonb_build_array(jsonb_build_object(
      'correction_id',v_correction_placement_scope->>'correction_id',
      'pair_timesheet_ids',v_correction_placement_scope->'pair_timesheet_ids',
      'placement_state',v_correction_placement_scope->>'placement_state',
      'missing_member_kind',v_correction_placement_scope->>'missing_member_kind',
      'placement_invoices',v_correction_placement_scope->'placement_invoices'));
    v_manifest:=v_manifest||jsonb_build_object(
      'correction_pair_placement_states',v_correction_placement_states);
  END IF;

  return v_manifest;

exception when others then
  v_dbg_sqlstate := SQLSTATE;
  v_dbg_error := SQLERRM;

  if v_invoice_debug then
    begin
      perform public._inv_write_audit(
        p_actor_user_id,
        'INVOICE_APPLY_EDITS_ERROR',
        jsonb_build_object(
          'invoice_id', coalesce(p_invoice_id::text,''),
          'sqlstate', v_dbg_sqlstate,
          'error', v_dbg_error,
          'stats', v_dbg_stats,
          'steps', v_dbg_steps
        ),
        'invoices',
        coalesce(p_invoice_id::text,''),
        null,
        'INVOICE_DEBUG',
        null, null, null
      );
    exception when others then
      null;
    end;
  end if;

  raise;
end;
$function$;

revoke all on function public.invoice_apply_edits(uuid,jsonb,uuid)
  from public,anon,authenticated,service_role,supabase_admin;
grant execute on function public.invoice_apply_edits(uuid,jsonb,uuid)
  to CURRENT_USER,service_role;


create or replace function private.weekly_source_invoice_allocation_assert_v1(
  p_invoice_id uuid
) returns jsonb
language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_invoice public.invoices%rowtype;
  v_line_count integer;
  v_binding_count integer;
  v_has_source_header boolean;
begin
  select * into v_invoice from public.invoices where id=p_invoice_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_INVOICE_NOT_FOUND' using errcode='22023';
  end if;
  select pg_catalog.count(*)::integer into v_binding_count
  from public.weekly_source_invoice_line_bindings binding
  where binding.invoice_id=p_invoice_id and binding.state='CURRENT';
  v_has_source_header:=coalesce(
    v_invoice.header_snapshot_json#>>'{meta,source}'='WEEKLY_FINAL_SOURCE'
    and v_invoice.header_snapshot_json#>>'{meta,self_bill}'='true',false
  );
  if v_binding_count=0 then
    if not v_has_source_header then
      return pg_catalog.jsonb_build_object(
        'ok',true,'is_source_invoice',false,'invoice_id',p_invoice_id
      );
    end if;
    select pg_catalog.count(*)::integer into v_line_count
    from public.invoice_lines invoice_line where invoice_line.invoice_id=p_invoice_id;
    if exists(select 1 from public.invoice_lines invoice_line where invoice_line.invoice_id=p_invoice_id
      and private.weekly_source_invoice_adjustment_line_valid_v1(invoice_line.id,p_invoice_id) is distinct from true) then
      raise exception 'WEEKLY_SOURCE_INVOICE_EXTRA_LINE' using errcode='55000';
    end if;
    if v_invoice.subtotal_ex_vat is distinct from (select round(coalesce(sum(total_charge_ex_vat),0),2) from public.invoice_lines where invoice_id=p_invoice_id)
      or v_invoice.vat_amount is distinct from (select round(coalesce(sum(vat_amount),0),2) from public.invoice_lines where invoice_id=p_invoice_id)
      or v_invoice.total_inc_vat is distinct from (select round(coalesce(sum(total_inc_vat),0),2) from public.invoice_lines where invoice_id=p_invoice_id) then
      raise exception 'WEEKLY_SOURCE_INVOICE_TOTAL_MISMATCH' using errcode='55000';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'is_source_invoice',true,'invoice_id',p_invoice_id,
      'line_count',v_line_count,'binding_count',0,'empty',v_line_count=0
    );
  end if;
  if not v_has_source_header then
    raise exception 'WEEKLY_SOURCE_INVOICE_HEADER_INVALID' using errcode='55000';
  end if;
  select pg_catalog.count(*)::integer into v_line_count
  from public.invoice_lines invoice_line where invoice_line.invoice_id=p_invoice_id;

  if exists(
    select 1 from public.invoice_lines invoice_line
    where invoice_line.invoice_id=p_invoice_id
      and not exists(
        select 1 from public.weekly_source_invoice_line_bindings binding
        where binding.invoice_line_id=invoice_line.id
          and binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      )
      and private.weekly_source_invoice_adjustment_line_valid_v1(invoice_line.id,p_invoice_id) is distinct from true
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_EXTRA_LINE' using errcode='55000';
  end if;

  perform private.weekly_source_invoice_receipt_projection_assert_v1(p_invoice_id);
  if exists(
    select 1
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement
      on movement.id=binding.billing_movement_id
    join public.weekly_source_invoice_presentation_lines presentation
      on presentation.id=binding.presentation_line_id
    join public.invoice_lines invoice_line on invoice_line.id=binding.invoice_line_id
    join public.weekly_source_invoice_placements placement
      on placement.billing_movement_id=movement.id and placement.is_current
    join public.weekly_source_manifest_movements manifest_movement
      on manifest_movement.billing_movement_id=movement.id
    join public.weekly_source_client_manifests manifest
      on manifest.id=manifest_movement.client_manifest_id
    where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      and (
        invoice_line.invoice_id is distinct from p_invoice_id
        or placement.invoice_id is distinct from p_invoice_id
        or placement.invoice_line_id is distinct from invoice_line.id
        or placement.placement_state<>'PLACED'
        or placement.original_automatic_cycle_id is distinct from coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)
        or private.weekly_source_invoice_movement_window_id_v1(movement.id) is distinct from coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)
        or binding.client_id is distinct from v_invoice.client_id
        or movement.actual_client_id is distinct from v_invoice.client_id
        or presentation.client_id is distinct from v_invoice.client_id
        or manifest.client_id is distinct from v_invoice.client_id
        or manifest_movement.movement_hash is distinct from movement.movement_economic_hash
        or binding.manifest_hash is distinct from manifest.manifest_hash
        or presentation.client_manifest_id is distinct from manifest.id
        or presentation.final_revision_id is distinct from movement.final_revision_id
        or presentation.original_finalisation_cycle_id is distinct from movement.finalisation_cycle_id
        or invoice_line.timesheet_id is distinct from movement.invoice_timesheet_id
        or invoice_line.total_pay_ex_vat is distinct from presentation.total_pay_ex_vat
        or invoice_line.total_charge_ex_vat is distinct from presentation.total_charge_ex_vat
        or invoice_line.vat_rate_pct is distinct from presentation.vat_rate_pct
        or invoice_line.vat_amount is distinct from presentation.vat_amount
        or invoice_line.total_inc_vat is distinct from presentation.total_inc_vat
        or (presentation.invoice_hold_release_id is not null and (presentation.source_hash is distinct from
          private.weekly_source_invoice_presentation_source_hash_v1((select array_agg(b.billing_movement_id order by b.billing_movement_id)
            from public.weekly_source_invoice_line_bindings b where b.presentation_line_id=presentation.id and b.state='CURRENT'),presentation.invoice_hold_release_id)
          or invoice_line.meta_json->'invoice_hold_release_authority' is distinct from private.weekly_source_invoice_presentation_release_authority_v1(
            (select array_agg(b.billing_movement_id order by b.billing_movement_id) from public.weekly_source_invoice_line_bindings b
              where b.presentation_line_id=presentation.id and b.state='CURRENT'),presentation.invoice_hold_release_id)))
      )
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_ALLOCATION_MISMATCH' using errcode='55000';
  end if;

  if exists(
    select 1
    from (
      select binding.invoice_line_id,
             pg_catalog.count(*)::integer as member_count,
             pg_catalog.count(distinct movement.correction_unit_id) as correction_count,
             pg_catalog.count(distinct movement.work_event_id) as event_count,
             pg_catalog.count(distinct movement.final_revision_id) as revision_count,
             pg_catalog.count(distinct movement.finalisation_cycle_id) as cycle_count,
             pg_catalog.count(distinct movement.actual_client_id) as client_count,
             pg_catalog.count(*) filter(where movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT') as nhsp_count,
             pg_catalog.array_agg(movement.movement_role order by movement.movement_role) as roles,
             pg_catalog.min(presentation.correction_role) as correction_role
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      group by binding.invoice_line_id
    ) grouped
    where grouped.member_count not in (1,2)
       or (grouped.member_count=2 and (
         grouped.correction_count<>1 or grouped.event_count<>1
         or grouped.revision_count<>1 or grouped.cycle_count<>1
         or grouped.client_count<>1 or grouped.nhsp_count<>0
         or grouped.correction_role is distinct from 'NET_DIFFERENCE'
         or grouped.roles not in (
           array['REPLACEMENT','REVERSAL']::text[],
           array['EXPENSE_REPLACEMENT','EXPENSE_REVERSAL']::text[]
         )
       ))
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_NET_CARDINALITY_INVALID' using errcode='55000';
  end if;

  if v_invoice.subtotal_ex_vat is distinct from (
       select pg_catalog.round(coalesce(pg_catalog.sum(line.total_charge_ex_vat),0),2)
       from public.invoice_lines line where line.invoice_id=p_invoice_id
     )
     or v_invoice.vat_amount is distinct from (
       select pg_catalog.round(coalesce(pg_catalog.sum(line.vat_amount),0),2)
       from public.invoice_lines line where line.invoice_id=p_invoice_id
     )
     or v_invoice.total_inc_vat is distinct from (
       select pg_catalog.round(coalesce(pg_catalog.sum(line.total_inc_vat),0),2)
       from public.invoice_lines line where line.invoice_id=p_invoice_id
     ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_TOTAL_MISMATCH' using errcode='55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'is_source_invoice',true,'invoice_id',p_invoice_id,
    'line_count',v_line_count,'binding_count',v_binding_count
  );
end;
$function$;

create or replace function private.weekly_source_invoice_issue_validate_v1(
  p_invoice_id uuid
) returns jsonb
language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_invoice public.invoices%rowtype;
  v_has_source_header boolean;
  v_binding_count integer;
  v_line_count integer;
  v_codes text[]:=array[]::text[];
  v_detail jsonb:='{}'::jsonb;
  v_assert jsonb;
  v_assert_code text;
  -- The immutable header's source group, read ONCE and only when it really is a
  -- uuid.  A malformed value must fail this invoice closed, never abort the
  -- batch that this invoice happens to share with other invoices.
  v_header_source_group_id uuid;
  v_header_source_group_valid boolean;
  v_validator_error text;
  -- HANDOVER 2 round 5, Part E: the three financial-record states, recorded
  -- separately on the verdict this owner returns.
  v_tsfin jsonb;
  -- WP-28: the enforced and the withheld halves of that ruling, computed by
  -- private.weekly_source_invoice_tsfin_refusal_v1 from the state above.
  v_tsfin_refusal jsonb;
  -- WP-33: the R8A section 1 admission-predicate boundary, applied once, here.
  v_wholly_sealed boolean;
  v_tsfin_codes jsonb;
  v_tsfin_deferred jsonb;
  v_tsfin_disposition text;
begin
  if p_invoice_id is null then
    return pg_catalog.jsonb_build_object('is_source_invoice',false);
  end if;
  select * into v_invoice from public.invoices where id=p_invoice_id;
  if not found then
    -- The ordinary owner already has an exact "not found" behaviour; never
    -- pre-empt it and never claim the source branch for a missing invoice.
    return pg_catalog.jsonb_build_object('is_source_invoice',false);
  end if;

  v_has_source_header:=coalesce(
    v_invoice.header_snapshot_json#>>'{meta,source}'='WEEKLY_FINAL_SOURCE'
    and v_invoice.header_snapshot_json#>>'{meta,self_bill}'='true',false
  );
  select pg_catalog.count(*)::integer into v_binding_count
  from public.weekly_source_invoice_line_bindings binding
  where binding.invoice_id=p_invoice_id and binding.state='CURRENT';

  if not v_has_source_header and v_binding_count=0 then
    return pg_catalog.jsonb_build_object('is_source_invoice',false);
  end if;

  select pg_catalog.count(*)::integer into v_line_count
  from public.invoice_lines invoice_line where invoice_line.invoice_id=p_invoice_id;

  -- Everything from here to the aggregation below is wrapped in ONE handler.
  -- This function is called from inside private._invoice_issue_validate_batch,
  -- which evaluates EVERY invoice of a batch in one statement, so an
  -- unexpected error raised here would abort the verdict of every other
  -- invoice in that batch, including ordinary invoices that have nothing to do
  -- with this one.  An unexpected error is therefore converted into a blocking
  -- code on THIS invoice and nothing else.  It cannot mask an ordinary
  -- invoice: the two "is_source_invoice: false" returns above are outside the
  -- handler, so an ordinary invoice never enters it.
  begin

  -- 24 section 11 qualification list -------------------------------------
  -- "its immutable header says source = WEEKLY_FINAL_SOURCE and self_bill = true"
  if not v_has_source_header then
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_HEADER_INVALID'::text;
  end if;
  v_header_source_group_valid:=pg_catalog.pg_input_is_valid(
    coalesce(v_invoice.header_snapshot_json#>>'{meta,source_group_id}',''),'uuid');
  if v_header_source_group_valid then
    v_header_source_group_id:=(v_invoice.header_snapshot_json#>>'{meta,source_group_id}')::uuid;
  else
    -- 24 section 11: the source group is part of the immutable header the
    -- source branch is entered on.  A missing or malformed value is this
    -- invoice's own explicit failure.
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_HEADER_INVALID'::text;
    v_detail:=v_detail||pg_catalog.jsonb_build_object(
      'header_source_group_id_invalid',true
    );
  end if;
  -- "it contains at least one source binding"
  if v_binding_count=0 then
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_NO_SOURCE_BINDING'::text;
  end if;
  -- "no empty invoice"
  if v_line_count=0 then
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_EMPTY_INVOICE'::text;
  end if;
  -- "no extra ordinary or unbound line is present"
  if exists(
    select 1 from public.invoice_lines invoice_line
    where invoice_line.invoice_id=p_invoice_id
      and not exists(
        select 1 from public.weekly_source_invoice_line_bindings binding
        where binding.invoice_line_id=invoice_line.id
          and binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      )
      and private.weekly_source_invoice_adjustment_line_valid_v1(invoice_line.id,p_invoice_id) is distinct from true
  ) then
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_UNBOUND_LINE'::text;
  end if;

  -- The established rule body.  weekly_source_invoice_allocation_assert_v1
  -- proves the header shape, extra/unbound lines, manifest hash, movement,
  -- presentation and placement binding, Contract and Client allocation, exact
  -- signed line amounts, VAT, header totals and the net-presentation
  -- cardinality.  It raises; here that becomes a blocker so the real entry
  -- points can report rather than abort.
  begin
    v_assert:=private.weekly_source_invoice_allocation_assert_v1(p_invoice_id);
    if coalesce((v_assert->>'empty')::boolean,false)
       and not (v_codes @> array['WEEKLY_SOURCE_ISSUE_EMPTY_INVOICE']) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_EMPTY_INVOICE'::text;
    end if;
  exception when others then
    get stacked diagnostics v_assert_code=message_text;
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_ALLOCATION_INVALID'::text;
    v_detail:=v_detail||pg_catalog.jsonb_build_object(
      'allocation_assert_error',pg_catalog.left(coalesce(v_assert_code,''),200)
    );
  end;

  if v_binding_count>0 then
    -- "current manifest and final source revision" -------------------------
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_manifest_movements manifest_movement
        on manifest_movement.billing_movement_id=binding.billing_movement_id
      join public.weekly_source_client_manifests manifest
        on manifest.id=manifest_movement.client_manifest_id
      join public.weekly_source_final_revisions revision
        on revision.id=manifest.final_revision_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and revision.state<>'CURRENT'
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_STALE_FINAL_REVISION'::text;
    end if;
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_manifest_movements manifest_movement
        on manifest_movement.billing_movement_id=binding.billing_movement_id
      join public.weekly_source_client_manifests manifest
        on manifest.id=manifest_movement.client_manifest_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          binding.manifest_hash is distinct from manifest.manifest_hash
          or binding.original_final_revision_id is distinct from manifest.final_revision_id
          or binding.original_cycle_id is distinct from manifest.source_cycle_id
          or manifest.invoice_state not in ('PARTLY_ADMITTED','ADMITTED')
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_STALE_MANIFEST'::text;
    end if;

    -- "exact presentation, binding and placement hashes" --------------------
    -- Every hash below is rebuilt from immutable identity text only, so the
    -- comparison is exact.  The presentation source hash is the admission
    -- owner's WEEKLY_SOURCE_INVOICE_PRESENTATION_SOURCE_V1 digest over the
    -- movement set the presentation actually binds, which is also the proof
    -- that the allocation carries no missing or duplicate movement.
    if exists(
      select 1
      from (
        select presentation.id,presentation.source_hash,
          private.weekly_source_invoice_presentation_expected_source_hash_v1(presentation.id) rebuilt
        from public.weekly_source_invoice_line_bindings binding
        join public.weekly_source_invoice_presentation_lines presentation
          on presentation.id=binding.presentation_line_id
        join public.weekly_source_billing_movements movement
          on movement.id=binding.billing_movement_id
        where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        group by presentation.id,presentation.source_hash,presentation.invoice_hold_release_id
      ) rebuilt_presentation
      where rebuilt_presentation.rebuilt is distinct from rebuilt_presentation.source_hash
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_PRESENTATION_HASH_INVALID'::text;
    end if;
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and binding.materialised_line_hash is distinct from
          private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_INVOICE_BINDING_V1',
            case when binding.binding_version=1 then
              pg_catalog.jsonb_build_object(
                'movement_id',binding.billing_movement_id,
                'presentation_line_id',binding.presentation_line_id,
                'invoice_line_id',binding.invoice_line_id,
                'invoice_id',binding.invoice_id,
                'manifest_hash',pg_catalog.encode(binding.manifest_hash,'hex'),
                'binding_version',1
              )
            else
              pg_catalog.jsonb_build_object(
                'movement_id',binding.billing_movement_id,
                'presentation_line_id',binding.presentation_line_id,
                'invoice_line_id',binding.invoice_line_id,
                'invoice_id',binding.invoice_id,
                'manifest_hash',pg_catalog.encode(binding.manifest_hash,'hex'),
                'binding_version',binding.binding_version,
                'prior_binding_id',binding.prior_binding_id
              )
            end
          )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_BINDING_HASH_INVALID'::text;
    end if;
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_placements placement
        on placement.billing_movement_id=binding.billing_movement_id
       and placement.is_current
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and placement.placement_hash is distinct from
          private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_INVOICE_PLACEMENT_V1',
            case when placement.placement_revision=1 then
              pg_catalog.jsonb_build_object(
                'movement_id',placement.billing_movement_id,
                'invoice_id',placement.invoice_id,
                'invoice_line_id',placement.invoice_line_id,
                'placement_revision',1,
                'placement_reason',placement.placement_reason
              )
            else
              pg_catalog.jsonb_build_object(
                'movement_id',placement.billing_movement_id,
                'invoice_id',placement.invoice_id,
                'invoice_line_id',placement.invoice_line_id,
                'placement_revision',placement.placement_revision,
                'placement_reason',placement.placement_reason,
                'prior_placement_id',placement.prior_placement_id,
                'source_invoice_version_fingerprint',
                  pg_catalog.encode(placement.source_invoice_version_fingerprint,'hex'),
                'destination_invoice_version_fingerprint',
                  pg_catalog.encode(placement.destination_invoice_version_fingerprint,'hex')
              )
            end
          )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_PLACEMENT_HASH_INVALID'::text;
    end if;

    -- "complete allocation with no missing or duplicate movement" ----------
    -- Every movement of every manifest this invoice draws on is either bound
    -- here or bound CURRENT somewhere else; none is bound twice; and the
    -- invoice never carries a movement its manifest does not contain.
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      group by binding.billing_movement_id
      having pg_catalog.count(*)>1
    ) or exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and not exists(
          select 1 from public.weekly_source_manifest_movements manifest_movement
          where manifest_movement.billing_movement_id=binding.billing_movement_id
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_DUPLICATE_MOVEMENT'::text;
    end if;
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      join public.weekly_source_invoice_line_bindings sibling
        on sibling.presentation_line_id=presentation.id
       and sibling.state='CURRENT'
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and sibling.invoice_id is distinct from p_invoice_id
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_MISSING_MOVEMENT'::text;
    end if;

    -- Every bound movement is still placed on this invoice and has not been
    -- voided by a later Correct Final Source.
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      left join public.weekly_source_invoice_placements placement
        on placement.billing_movement_id=movement.id and placement.is_current
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          movement.placement_state not in ('PLACED','ISSUED')
          or placement.id is null
          or placement.placement_state<>'PLACED'
          or placement.invoice_id is distinct from p_invoice_id
          or placement.invoice_line_id is distinct from binding.invoice_line_id
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_MOVEMENT_NOT_PLACED'::text;
    end if;

    -- "Client, source group, cycle, currency and VAT consistency" -----------
    -- CloudTMS invoices carry no per-invoice currency column, so currency
    -- consistency is structural: one Client, one source group.  Cycle
    -- consistency is deliberately NOT one cycle per invoice: 24 section 12
    -- allows a confirmed cross-week move, and the header records every
    -- contained cycle.  What must hold is that the header's contained sets
    -- describe exactly the manifests the bindings actually reference.
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_manifest_movements manifest_movement
        on manifest_movement.billing_movement_id=binding.billing_movement_id
      join public.weekly_source_client_manifests manifest
        on manifest.id=manifest_movement.client_manifest_id
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          manifest.client_id is distinct from v_invoice.client_id
          or movement.actual_client_id is distinct from v_invoice.client_id
          or presentation.client_id is distinct from v_invoice.client_id
          or binding.client_id is distinct from v_invoice.client_id
          or manifest.source_group_id is distinct from v_header_source_group_id
        )
    ) or exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_manifest_movements manifest_movement
        on manifest_movement.billing_movement_id=binding.billing_movement_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and not (
          coalesce(
            v_invoice.header_snapshot_json#>'{meta,contained_client_manifest_ids}',
            '[]'::jsonb
          ) @> pg_catalog.to_jsonb(manifest_movement.client_manifest_id)
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_SCOPE_INCONSISTENT'::text;
    end if;
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      join public.invoice_lines invoice_line on invoice_line.id=binding.invoice_line_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and invoice_line.vat_rate_pct is distinct from presentation.vat_rate_pct
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_SCOPE_INCONSISTENT'::text;
    end if;

    -- Immutable automatic invoice windows remain distinct from original Source
    -- cycle witnesses. The header must describe the actual complete bound set.
    if coalesce(v_invoice.header_snapshot_json#>'{meta,contained_invoice_window_cycle_ids}',
        v_invoice.header_snapshot_json#>'{meta,contained_source_cycle_ids}','[]'::jsonb)
      is distinct from coalesce((select jsonb_agg(window_id order by window_id) from (
        select distinct coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id) window_id
          from public.weekly_source_invoice_line_bindings binding
          join public.weekly_source_manifest_movements mm on mm.billing_movement_id=binding.billing_movement_id
          join public.weekly_source_client_manifests manifest on manifest.id=mm.client_manifest_id
          where binding.invoice_id=p_invoice_id and binding.state='CURRENT') actual),'[]'::jsonb) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_WINDOW_SCOPE_INCONSISTENT'::text;
    end if;
    -- "NHSP physical negative and positive independence" (24 section 10) -----
    -- An NHSP physical row is one movement, one presentation, one visible line;
    -- it is never netted with another physical row.
    if exists(
      select 1
      from public.weekly_source_invoice_presentation_lines presentation
      join public.weekly_source_invoice_line_bindings binding
        on binding.presentation_line_id=presentation.id
       and binding.state='CURRENT'
      where binding.invoice_id=p_invoice_id
        and presentation.origin_kind='NHSP_PHYSICAL_ROW'
      group by presentation.id,binding.invoice_line_id
      having pg_catalog.count(*)<>1
    ) or exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          (presentation.origin_kind='NHSP_PHYSICAL_ROW')
            <>(movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT')
          or (presentation.origin_kind='NHSP_PHYSICAL_ROW'
              and presentation.correction_role='NET_DIFFERENCE')
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_NHSP_NETTING_DETECTED'::text;
    end if;

    -- "the configured non-NHSP correction shape" (24 section 10) ------------
    -- FULL pair: one movement per presentation, correction_role REVERSAL or
    -- REPLACEMENT.  NET: exactly the reversal/replacement pair of one
    -- correction unit on one visible line, correction_role NET_DIFFERENCE.
    if exists(
      select 1
      from (
        select presentation.id,presentation.correction_role,
          pg_catalog.count(*)::integer member_count,
          pg_catalog.count(distinct movement.correction_unit_id) correction_count,
          pg_catalog.array_agg(movement.movement_role order by movement.movement_role) roles
        from public.weekly_source_invoice_line_bindings binding
        join public.weekly_source_invoice_presentation_lines presentation
          on presentation.id=binding.presentation_line_id
        join public.weekly_source_billing_movements movement
          on movement.id=binding.billing_movement_id
        where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        group by presentation.id,presentation.correction_role
      ) shaped
      where shaped.member_count not in (1,2)
        or (shaped.member_count=2 and (
          shaped.correction_role is distinct from 'NET_DIFFERENCE'
          or shaped.correction_count<>1
          or shaped.roles not in (
            array['REPLACEMENT','REVERSAL']::text[],
            array['EXPENSE_REPLACEMENT','EXPENSE_REVERSAL']::text[]
          )
        ))
        or (shaped.member_count=1 and shaped.correction_role='NET_DIFFERENCE')
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_CORRECTION_SHAPE_INVALID'::text;
    end if;

    -- "source price comparison success" (24 section 13) ---------------------
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          (presentation.origin_kind='NHSP_PHYSICAL_ROW'
            and (presentation.price_check_result not in (
                'EXACT','SOURCE_ROUNDING_EQUIVALENT','ACCEPTED_DISPARITY','ACCEPTED_ZERO'
              )
              or presentation.amount_authority<>'VALIDATED_SOURCE_PENCE'
              or presentation.source_validation_charge_pence is null
              or presentation.invoice_presentation_charge_pence
                 is distinct from presentation.source_validation_charge_pence
              or presentation.charge_acceptance_id is distinct from movement.charge_acceptance_id
              or (presentation.price_check_result in ('ACCEPTED_DISPARITY','ACCEPTED_ZERO')
                and not exists(
                  select 1 from public.weekly_source_charge_acceptances acceptance
                  where acceptance.id=presentation.charge_acceptance_id
                    and acceptance.acceptance_kind=presentation.price_check_result
                    and acceptance.upload_row_id=movement.nhsp_upload_row_id
                    and acceptance.contract_id=movement.contract_id
                    and acceptance.charge_calculation_fingerprint=movement.price_check_fingerprint
                    and acceptance.acceptance_policy_fingerprint=
                      private.weekly_source_charge_acceptance_policy_fingerprint_v1()
                ))))
          or (presentation.origin_kind='SOURCE_FIXED_EXPENSE'
            and (presentation.price_check_result<>'NOT_APPLICABLE'
              or presentation.amount_authority<>'VALIDATED_SOURCE_PENCE'))
          or (presentation.amount_authority='VALIDATED_SOURCE_PENCE' and movement.source_line_kind in ('SOURCE_ORDINARY','SOURCE_REPLACEMENT','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION') and private.weekly_source_invoice_source_amount_movement_valid_v1(movement.id) is distinct from true)
          or (presentation.origin_kind not in ('NHSP_PHYSICAL_ROW','SOURCE_FIXED_EXPENSE')
            and not (private.weekly_source_invoice_source_amount_movement_valid_v1(movement.id)
              and presentation.amount_authority='VALIDATED_SOURCE_PENCE')
            and presentation.amount_authority<>'CLOUDTMS_CALCULATION')
          or (movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT'
            and movement.price_check_result
              not in ('EXACT','SOURCE_ROUNDING_EQUIVALENT','ACCEPTED_DISPARITY','ACCEPTED_ZERO'))
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_PRICE_CHECK_FAILED'::text;
    end if;

    -- "exact signed line amounts, VAT and header total" ---------------------
    -- The allocation assert already compares the visible line with its
    -- presentation and the header with the sum of its lines.  What it does not
    -- do is tie the presentation back to the immutable movements it binds.
    if exists(
      select 1
      from (
        select presentation.id,
          presentation.total_pay_ex_vat,presentation.total_charge_ex_vat,
          presentation.vat_amount,presentation.total_inc_vat,
          presentation.invoice_presentation_charge_pence,
          presentation.calculated_comparison_charge_pence,
          pg_catalog.sum(movement.total_pay_ex_vat) movement_pay,
          pg_catalog.sum((private.weekly_source_invoice_admitted_member_money_v1(presentation.id,movement.id)->>'vat_pence')::numeric/100) movement_vat,
          pg_catalog.sum((private.weekly_source_invoice_admitted_member_money_v1(presentation.id,movement.id)->>'gross_pence')::numeric/100) movement_total,
          pg_catalog.sum(movement.invoice_presentation_charge_pence) movement_pence,
          pg_catalog.sum(movement.calculated_comparison_charge_pence) movement_calc_pence
        from public.weekly_source_invoice_line_bindings binding
        join public.weekly_source_invoice_presentation_lines presentation
          on presentation.id=binding.presentation_line_id
        join public.weekly_source_billing_movements movement
          on movement.id=binding.billing_movement_id
        where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        group by presentation.id,presentation.total_pay_ex_vat,
          presentation.total_charge_ex_vat,presentation.vat_amount,
          presentation.total_inc_vat,presentation.invoice_presentation_charge_pence,
          presentation.calculated_comparison_charge_pence
      ) amounts
      where amounts.total_pay_ex_vat is distinct from amounts.movement_pay
        or amounts.vat_amount is distinct from amounts.movement_vat
        or amounts.total_inc_vat is distinct from amounts.movement_total
        or amounts.invoice_presentation_charge_pence is distinct from amounts.movement_pence
        or amounts.calculated_comparison_charge_pence is distinct from amounts.movement_calc_pence
        or amounts.invoice_presentation_charge_pence
           is distinct from (amounts.total_charge_ex_vat*100)::bigint
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_AMOUNT_MISMATCH'::text;
    end if;
    if v_invoice.subtotal_ex_vat is distinct from (
         select pg_catalog.round(coalesce(pg_catalog.sum(line.total_charge_ex_vat),0),2)
         from public.invoice_lines line where line.invoice_id=p_invoice_id
       )
       or v_invoice.vat_amount is distinct from (
         select pg_catalog.round(coalesce(pg_catalog.sum(line.vat_amount),0),2)
         from public.invoice_lines line where line.invoice_id=p_invoice_id
       )
       or v_invoice.total_inc_vat is distinct from (
         select pg_catalog.round(coalesce(pg_catalog.sum(line.total_inc_vat),0),2)
         from public.invoice_lines line where line.invoice_id=p_invoice_id
       ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_TOTAL_MISMATCH'::text;
    end if;

    -- "Timesheet relationship where required for navigation, without treating
    -- Candidate evidence as invoice authority" (24 section 11; proof/34 section 9).
    -- The visible line keeps the immutable Timesheet identity the movement was
    -- written against.  Nothing here reads authorisation, signature, PDF or
    -- any other Candidate evidence, and nothing re-points a line.
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      join public.invoice_lines invoice_line on invoice_line.id=binding.invoice_line_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          (invoice_line.timesheet_id is null and not (movement.invoice_timesheet_id is null and (movement.source_line_kind='INVOICE_VAT_ROUNDING'
            or (movement.source_line_kind='SELF_BILL_REPORT_LINE' and movement.movement_role='STANDALONE_NEGATIVE'))))
          or invoice_line.timesheet_id is distinct from movement.invoice_timesheet_id
          or invoice_line.invoice_id is distinct from p_invoice_id
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_TIMESHEET_LINK_INVALID'::text;
    end if;
  end if;

    -- HANDOVER 2 round 5, Part E "Invoice and TSFIN outcomes": the three
    -- financial-record states are RECORDED SEPARATELY on the verdict so a
    -- consumer of this owner can tell them apart without reading this body.
    v_tsfin:=private.weekly_source_invoice_tsfin_state_v1(p_invoice_id);
    v_detail:=v_detail||pg_catalog.jsonb_build_object('tsfin',v_tsfin);

  exception when others then
    get stacked diagnostics v_validator_error=message_text;
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_VALIDATOR_ERROR'::text;
    v_detail:=v_detail||pg_catalog.jsonb_build_object(
      'validator_error',pg_catalog.left(coalesce(v_validator_error,''),200)
    );
  end;

  select pg_catalog.array_agg(distinct code order by code)
    into v_codes from pg_catalog.unnest(v_codes) code;
  v_codes:=coalesce(v_codes,array[]::text[]);

  -- WP-28.  The financial-record refusal is computed OUTSIDE the handler above,
  -- so a validator that blew up leaves v_tsfin null and the predicate returns
  -- WEEKLY_SOURCE_ISSUE_TSFIN_STATE_UNDETERMINED rather than nothing.
  --
  -- WP-33, HANDOVER 2 round 8 Part 2.1.  The predicate now answers several
  -- separate questions from the one state document, and this verdict carries
  -- each of them on its own key because the ruling keeps them apart:
  --   tsfin_blocker_codes          what ACTUALLY stops the INVOICE today;
  --   tsfin_invoice_disposition    the explicit typed invoice outcome, which is
  --                                what both seams consume - an omission is not
  --                                an outcome, so a seam that cannot read this
  --                                key fails closed;
  --   tsfin_payment_blocker_codes  the RETAINED expected-but-missing fact, which
  --                                is non-empty for the exempt case too so that
  --                                payment and financial publication stay
  --                                fail-closed while the invoice issues;
  --   tsfin_deferred_blocker_codes the expected-but-missing INVOICE refusal that
  --                                round 8 Part 2.1 requires and sealed pack 02
  --                                section 15 forbids.  Computed, named, NOT
  --                                enforced, with a reason that is true today.
  --
  -- The WP-28 tsfin_withheld_* keys are RETIRED and deliberately not renamed
  -- back into use: their reason named the round-6 question, and the approver has
  -- answered that question.  Standing rule 12 forbids shipping a fail-closed
  -- reason that is no longer true, so the deferred keys above carry the reason
  -- that IS true - an outstanding admission-predicate boundary correction.
  --
  -- It is carried on its OWN key and is deliberately NOT folded into
  -- blocker_codes, so `ok` keeps its exact 24 section 11 meaning - "the exact
  -- source branch passes" - and an admitted source invoice still skips only the
  -- four irrelevant ordinary evidence categories.  Folding a Candidate
  -- financial-record refusal into `ok` would additionally (a) stop the direct
  -- owner skipping public._ctms_assert_invoice_correction_lines_v1, turning an
  -- ON_HOLD into a raised exception, and (b) re-impose every ordinary evidence
  -- requirement the pack says is irrelevant to source self-billing.  Both seams
  -- append this array unconditionally, in the ok and the not-ok branch alike.
  v_tsfin_refusal:=private.weekly_source_invoice_tsfin_refusal_v1(v_tsfin);

  -- =========================================================================
  -- WP-33, HANDOVER 2 CORRECTION ADDENDUM R8A section 1 - the ADMISSION
  -- PREDICATE BOUNDARY.  This is the one place the boundary is applied, and it
  -- is applied to a verdict whose source-side truth has ALREADY been decided
  -- immediately above.
  --
  -- R8A section 1 is LATER authority than round 8 and is accepted by the
  -- product owner.  It withdraws round 8 Part 2.2 and Part 6 item 6 for a
  -- wholly sealed source-backed self-bill, word for word:
  --
  --   "Candidate Timesheet authorisation, Candidate-pay TSFIN existence/
  --    currentness/status, READY_FOR_INVOICE, pay holds, advances, settlement
  --    and pay query/reconciliation state are never self-bill admission
  --    predicates."
  --   "A stale or missing Candidate-pay TSFIN likewise does not block an
  --    otherwise-valid immutable final-source invoice movement.  It blocks
  --    Candidate-pay publication, readiness or reconciliation wherever those
  --    owners require current pay evidence."
  --
  -- and restores 02 CONTROLLING POLICY section 15 and acceptance row ISS-013
  -- ("Source invoice while Candidate pay pending/protected/frozen" -> ISSUED).
  --
  -- WHOLLY SEALED IS A POSITIVE TEST, and R8A's first precision point says so:
  -- "This must be implemented as a positive test of sealed status, never
  -- inherited by anything partially sealed or merely source-adjacent."  The
  -- test is cardinality(v_codes)=0 - the exact 24 section 11 branch, every
  -- source-side limb proved: current manifest and final source revision, exact
  -- presentation/binding/placement hashes, complete allocation with no missing
  -- or duplicate movement, every line bound, no extra ordinary line, exact
  -- signed amounts, VAT and header total, Client/group/cycle/currency/VAT
  -- consistency, NHSP physical independence, the configured correction shape,
  -- source price comparison success and a non-empty invoice.  It is the SAME
  -- value returned as `ok`, computed here and not re-read, so the two can never
  -- drift apart.
  --
  -- IF IT IS NOT PROVED, THE OLD BEHAVIOUR STANDS: every Candidate-pay TSFIN
  -- code remains an invoice blocker exactly as WP-28 installed it.  A mixed,
  -- unbound, tampered or partly sealed invoice is already failing closed on its
  -- own source codes and gains nothing here.
  --
  -- WHAT MOVES, AND WHAT DOES NOT.  For a wholly sealed self-bill every
  -- Candidate-pay TSFIN code moves from tsfin_blocker_codes to
  -- tsfin_deferred_blocker_codes - stale, expected-but-missing and the
  -- undetermined/disagreement codes alike, because each of them is a judgement
  -- about the Candidate financial record and R8A names that whole class.
  -- tsfin_payment_blocker_codes is NOT touched by any of this: it already
  -- carries the same facts and it is what keeps Candidate-pay publication,
  -- readiness and reconciliation fail-closed.  The invoice moves; the payment
  -- does not.  Nothing in v_codes - the source-side truth - is touched either.
  -- =========================================================================
  v_wholly_sealed:=cardinality(v_codes)=0;
  v_tsfin_codes:=coalesce(v_tsfin_refusal->'blocker_codes','[]'::jsonb);
  v_tsfin_deferred:=coalesce(v_tsfin_refusal->'deferred_blocker_codes','[]'::jsonb);
  v_tsfin_disposition:=coalesce(v_tsfin_refusal->>'invoice_disposition','');
  if v_wholly_sealed and pg_catalog.jsonb_typeof(v_tsfin_codes)='array'
     and pg_catalog.jsonb_typeof(v_tsfin_deferred)='array' then
    if pg_catalog.jsonb_array_length(v_tsfin_codes)>0 then
      -- The sorted union of the two arrays, so the deferred record stays a set
      -- and its order can never carry meaning.
      select coalesce(pg_catalog.jsonb_agg(code order by code),'[]'::jsonb)
        into v_tsfin_deferred
      from (
        select distinct element.value code
        from pg_catalog.jsonb_array_elements_text(
          v_tsfin_codes||v_tsfin_deferred) as element(value)
      ) merged;
      v_tsfin_codes:='[]'::jsonb;
      -- The typed outcome.  The proved first-authorisation state keeps its own
      -- name, because R8A names it separately and round 8 Part 2.1 requires an
      -- explicit typed disposition for it; every other Candidate-pay condition
      -- on a wholly sealed self-bill gets the boundary's own name.
      if v_tsfin_disposition
           <>'WEEKLY_SOURCE_INVOICE_TSFIN_AWAITING_FIRST_AUTHORISATION_EXEMPT' then
        v_tsfin_disposition:=
          'WEEKLY_SOURCE_INVOICE_TSFIN_CANDIDATE_PAY_NOT_ADMISSION_PREDICATE';
      end if;
    elsif v_tsfin_disposition
            ='WEEKLY_SOURCE_INVOICE_TSFIN_EXPECTED_BUT_MISSING_NOT_ENFORCED' then
      v_tsfin_disposition:=
        'WEEKLY_SOURCE_INVOICE_TSFIN_CANDIDATE_PAY_NOT_ADMISSION_PREDICATE';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'is_source_invoice',true,
    'ok',cardinality(v_codes)=0,
    'invoice_id',p_invoice_id,
    'line_count',v_line_count,
    'binding_count',v_binding_count,
    'wholly_sealed_source_self_bill',v_wholly_sealed,
    'blocker_codes',pg_catalog.to_jsonb(v_codes),
    'tsfin_blocker_codes',v_tsfin_codes,
    'tsfin_invoice_disposition',v_tsfin_disposition,
    'tsfin_payment_blocker_codes',
      coalesce(v_tsfin_refusal->'payment_blocker_codes','[]'::jsonb),
    'tsfin_deferred_blocker_codes',v_tsfin_deferred,
    'tsfin_deferred_reason',
      case when pg_catalog.jsonb_array_length(v_tsfin_deferred)>0
        then case when v_wholly_sealed
          then 'WEEKLY_SOURCE_TSFIN_CANDIDATE_PAY_NOT_A_SELF_BILL_ADMISSION_PREDICATE'
          else v_tsfin_refusal->>'deferred_reason' end end,
    'tsfin_deferred_authority',
      case when pg_catalog.jsonb_array_length(v_tsfin_deferred)>0
        then case when v_wholly_sealed
          then 'HANDOVER 2 CORRECTION ADDENDUM R8A section 1, later authority than '
            ||'round 8 and accepted by the product owner; sealed pack '
            ||'02 CONTROLLING POLICY section 15, annex FTI-013 and acceptance row '
            ||'ISS-013. The fact is retained for Candidate-pay publication, '
            ||'readiness and reconciliation in tsfin_payment_blocker_codes'
          else v_tsfin_refusal->>'deferred_authority' end end,
    'detail',v_detail
  );
end;
$function$;

create or replace function public.weekly_source_invoice_move_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_allowed_keys constant text[]:=array[
    'actor_user_id','source_invoice_id','destination_invoice_id',
    'presentation_line_id','invoice_line_id','expected_presentation_hash',
    'expected_source_document_revision',
    'expected_destination_document_revision','reason'
  ]::text[];
  v_required_keys constant text[]:=array[
    'actor_user_id','source_invoice_id','destination_invoice_id',
    'expected_presentation_hash','expected_source_document_revision',
    'expected_destination_document_revision','reason'
  ]::text[];
  v_unknown text;
  v_actor uuid;
  v_source_invoice_id uuid;
  v_destination_invoice_id uuid;
  v_presentation_line_id uuid;
  v_invoice_line_id uuid;
  v_expected_presentation_hash bytea;
  v_expected_source_revision bigint;
  v_expected_destination_revision bigint;
  v_reason text;
  v_selected public.weekly_source_invoice_presentation_lines%rowtype;
  v_presentation_ids uuid[];
  v_companion_count integer;
  v_source public.invoices%rowtype;
  v_destination public.invoices%rowtype;
  v_source_manifest public.weekly_source_client_manifests%rowtype;
  v_destination_manifest public.weekly_source_client_manifests%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_source_fingerprint bytea;
  v_destination_fingerprint bytea;
  v_line_ids uuid[];
  v_line_count integer;
  v_updated_line_count integer;
  v_movement_count integer;
  v_binding_invoice_ids uuid[];
  v_binding record;
  v_placement public.weekly_source_invoice_placements%rowtype;
  v_new_binding_version integer;
  v_new_placement_revision integer;
  v_binding_hash bytea;
  v_placement_hash bytea;
  v_replay_count integer;
begin
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role','')
       <>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown from pg_catalog.jsonb_object_keys(p_request) key
  where not (key=any(v_allowed_keys)) order by key limit 1;
  if v_unknown is not null then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_UNKNOWN_FIELD'
      using errcode='22023',detail=v_unknown;
  end if;
  if not (p_request ?& v_required_keys) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_REQUEST_INVALID' using errcode='22023';
  end if;
  -- 24 section 12 is a contract over VALUES; ?& above proves only that a key
  -- EXISTS.  A key present with a JSON null passes ?&, and ->> on a JSON null
  -- yields SQL NULL, which no cast rejects, so a null would reach a predicate
  -- and be swallowed by three-valued logic.  Every required value is therefore
  -- type-gated here, before anything is parsed.  The two optional identity keys
  -- may be JSON null, which is how "not supplied" has always been expressed,
  -- but may not be any other non-string type.
  if pg_catalog.jsonb_typeof(p_request->'actor_user_id') is distinct from 'string'
     or pg_catalog.jsonb_typeof(p_request->'source_invoice_id') is distinct from 'string'
     or pg_catalog.jsonb_typeof(p_request->'destination_invoice_id') is distinct from 'string'
     or pg_catalog.jsonb_typeof(p_request->'expected_presentation_hash') is distinct from 'string'
     or pg_catalog.jsonb_typeof(p_request->'reason') is distinct from 'string'
     or pg_catalog.jsonb_typeof(p_request->'expected_source_document_revision')
          is distinct from 'number'
     or pg_catalog.jsonb_typeof(p_request->'expected_destination_document_revision')
          is distinct from 'number'
     or coalesce(pg_catalog.jsonb_typeof(p_request->'presentation_line_id'),'null')
          not in ('string','null')
     or coalesce(pg_catalog.jsonb_typeof(p_request->'invoice_line_id'),'null')
          not in ('string','null') then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_VALUE_INVALID' using errcode='22023';
  end if;
  -- Exactly one of the two identities 24 section 12 allows.
  if ((nullif(p_request->>'presentation_line_id','') is not null)::integer
     +(nullif(p_request->>'invoice_line_id','') is not null)::integer)<>1 then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_IDENTITY_REQUIRED' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_source_invoice_id:=(p_request->>'source_invoice_id')::uuid;
    v_destination_invoice_id:=(p_request->>'destination_invoice_id')::uuid;
    v_presentation_line_id:=nullif(p_request->>'presentation_line_id','')::uuid;
    v_invoice_line_id:=nullif(p_request->>'invoice_line_id','')::uuid;
    v_expected_source_revision:=(p_request->>'expected_source_document_revision')::bigint;
    v_expected_destination_revision:=(p_request->>'expected_destination_document_revision')::bigint;
    if coalesce(p_request->>'expected_presentation_hash','') !~ '^[0-9a-f]{64}$' then
      raise exception 'invalid presentation hash';
    end if;
    v_expected_presentation_hash:=pg_catalog.decode(
      p_request->>'expected_presentation_hash','hex'
    );
  exception when others then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_VALUE_INVALID' using errcode='22023';
  end;
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  if v_source_invoice_id=v_destination_invoice_id
     or coalesce(v_expected_source_revision,0)<1
     or coalesce(v_expected_destination_revision,0)<1
     or pg_catalog.char_length(v_reason) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_VALUE_INVALID' using errcode='22023';
  end if;
  v_source_fingerprint:=private.weekly_source_invoice_expected_version_fingerprint_v1(
    v_source_invoice_id,v_expected_source_revision
  );
  v_destination_fingerprint:=private.weekly_source_invoice_expected_version_fingerprint_v1(
    v_destination_invoice_id,v_expected_destination_revision
  );

  -- Resolve the selected presentation line.  The invoice-line identity is the
  -- alternative 24 section 12 allows; it resolves to exactly one presentation,
  -- otherwise the selection is ambiguous and is refused.
  if v_presentation_line_id is null then
    select pg_catalog.count(distinct binding.presentation_line_id)::integer,
           pg_catalog.min(binding.presentation_line_id::text)::uuid
      into v_companion_count,v_presentation_line_id
    from public.weekly_source_invoice_line_bindings binding
    where binding.invoice_line_id=v_invoice_line_id and binding.state='CURRENT';
    if coalesce(v_companion_count,0)<>1 then
      raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_FOUND' using errcode='22023';
    end if;
  end if;
  select * into v_selected from public.weekly_source_invoice_presentation_lines
  where id=v_presentation_line_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_FOUND' using errcode='22023';
  end if;
  -- The expected presentation hash is the Office's proof that it is moving the
  -- immutable line it was shown.
  if v_selected.presentation_hash is distinct from v_expected_presentation_hash then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_PRESENTATION_HASH_MISMATCH'
      using errcode='40001';
  end if;
  if v_invoice_line_id is not null and not exists(
    select 1 from public.weekly_source_invoice_line_bindings binding
    where binding.presentation_line_id=v_selected.id and binding.state='CURRENT'
      and binding.invoice_line_id=v_invoice_line_id
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_FOUND' using errcode='22023';
  end if;
  -- A source-fixed expense follows its companion; it is never the unit of
  -- selection while it has one.  The Office moves the shift presentation and
  -- the expense goes with it.
  if v_selected.companion_presentation_line_id is not null then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_COMPANION_REQUIRED'
      using errcode='55000',detail=v_selected.companion_presentation_line_id::text;
  end if;
  select pg_catalog.array_agg(distinct member.id)
    into v_presentation_ids
  from public.weekly_source_invoice_presentation_lines member
  where member.id=v_selected.id
     or member.companion_presentation_line_id=v_selected.id;
  -- Nothing unrelated: every member is the selected line or an expense that
  -- declared it as its companion, on the same work event.
  if exists(
    select 1 from public.weekly_source_invoice_presentation_lines member
    where member.id=any(v_presentation_ids)
      and (member.work_event_id is distinct from v_selected.work_event_id
        or member.client_manifest_id is distinct from v_selected.client_manifest_id
        or (member.id<>v_selected.id and member.line_kind<>'SOURCE_FIXED_EXPENSE'))
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_COMPANION_INVALID' using errcode='55000';
  end if;

  perform 1 from public.invoices invoice
  where invoice.id=any(array[v_source_invoice_id,v_destination_invoice_id])
  order by invoice.id for update;
  if (select pg_catalog.count(*) from public.invoices invoice
      where invoice.id=any(array[v_source_invoice_id,v_destination_invoice_id]))<>2 then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_INVOICE_NOT_FOUND' using errcode='22023';
  end if;
  select * into strict v_source from public.invoices where id=v_source_invoice_id;
  select * into strict v_destination from public.invoices where id=v_destination_invoice_id;

  -- Gate 13 finding F6.  `->>` and `#>>` yield SQL NULL for an ABSENT key, and
  -- `NULL <> 'X'` is NULL, not true, so each of these four limbs evaluated to
  -- NULL and the whole `if` was not taken.  Executed on a build from empty
  -- before the change: with `schema_version` removed from either header the
  -- move was ACCEPTED and COMMITTED (`status=MOVED`); with `{meta,source}`
  -- removed it was refused only by the neighbouring G7-4 header trigger
  -- (`WEEKLY_SOURCE_INVOICE_HEADER_INVALID`), never by this guard.
  -- `is distinct from` is null-safe, so absent, JSON null and wrong value are
  -- all unsafe, exactly as the self_bill and manifest-id limbs beside them
  -- already treat them. PHD-003 intentionally has no cross-week confirmation
  -- gate: same Client plus two idle, unissued Draft invoices is the complete
  -- business compatibility rule.
  if v_source.header_snapshot_json->>'schema_version'
       is distinct from 'WEEKLY_SOURCE_SELF_BILL_INVOICE_V1'
     or v_destination.header_snapshot_json->>'schema_version'
       is distinct from 'WEEKLY_SOURCE_SELF_BILL_INVOICE_V1'
     or v_source.header_snapshot_json#>>'{meta,source}'
       is distinct from 'WEEKLY_FINAL_SOURCE'
     or v_destination.header_snapshot_json#>>'{meta,source}'
       is distinct from 'WEEKLY_FINAL_SOURCE'
     or v_source.header_snapshot_json#>>'{meta,self_bill}' is distinct from 'true'
     or v_destination.header_snapshot_json#>>'{meta,self_bill}' is distinct from 'true'
     or not pg_catalog.pg_input_is_valid(
          coalesce(v_source.header_snapshot_json#>>'{meta,client_manifest_id}',''),'uuid')
     or not pg_catalog.pg_input_is_valid(
          coalesce(v_destination.header_snapshot_json#>>'{meta,client_manifest_id}',''),'uuid') then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_SOURCE_INVOICE_REQUIRED' using errcode='55000';
  end if;
  select * into strict v_source_manifest
  from public.weekly_source_client_manifests
  where id=(v_source.header_snapshot_json#>>'{meta,client_manifest_id}')::uuid;
  select * into strict v_destination_manifest
  from public.weekly_source_client_manifests
  where id=(v_destination.header_snapshot_json#>>'{meta,client_manifest_id}')::uuid;
  select * into strict v_event from public.weekly_work_events
  where id=v_selected.work_event_id;
  if v_source.client_id is distinct from v_destination.client_id
     or v_source.client_id is distinct from v_source_manifest.client_id
     or v_destination.client_id is distinct from v_destination_manifest.client_id
     or v_source.client_id is distinct from v_event.client_id
     or v_source.client_id is distinct from v_selected.client_id
     or v_source.type::text<>'INVOICE' or v_destination.type::text<>'INVOICE' then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_SCOPE_INVALID' using errcode='55000';
  end if;

  perform private.weekly_source_office_authority_v1(
    v_actor,'MOVE_SOURCE_INVOICE',v_source_manifest.source_group_id,
    v_source.client_id,v_event.work_date
  );
  if exists(select 1 from public.weekly_source_invoice_line_bindings binding join public.weekly_source_billing_movements movement on movement.id=binding.billing_movement_id
    where binding.invoice_id in (v_source_invoice_id,v_destination_invoice_id) and binding.state='CURRENT'
      and private.weekly_source_frozen_rule_values_v1(movement.final_revision_id)->>'invoice_sender'='CLIENT_SELF_BILL'
      and private.weekly_source_frozen_rule_values_v1(movement.final_revision_id)->>'invoice_vat_method'<>'SUM_OF_LINES') then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_VAT_MEMBERSHIP_LOCKED' using errcode='55000'; end if;

  -- Where do the selected presentations currently live?  The presentation
  -- identity is immutable, so this answers the replay question without needing
  -- the bindings to still be on the source invoice.
  select pg_catalog.array_agg(distinct binding.invoice_id)
    into v_binding_invoice_ids
  from public.weekly_source_invoice_line_bindings binding
  where binding.presentation_line_id=any(v_presentation_ids)
    and binding.state='CURRENT';
  if v_binding_invoice_ids is null then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_FOUND' using errcode='22023';
  end if;

  if v_binding_invoice_ids=array[v_destination_invoice_id]::uuid[] then
    select pg_catalog.count(*)::integer into v_replay_count
    from public.weekly_source_invoice_placements placement
    join public.weekly_source_invoice_placements prior
      on prior.id=placement.prior_placement_id
    join public.weekly_source_invoice_line_bindings binding
      on binding.billing_movement_id=placement.billing_movement_id
     and binding.state='CURRENT'
    where placement.is_current
      and binding.presentation_line_id=any(v_presentation_ids)
      and placement.invoice_id=v_destination_invoice_id
      and prior.invoice_id=v_source_invoice_id
      and placement.source_invoice_version_fingerprint=v_source_fingerprint
      and placement.destination_invoice_version_fingerprint=v_destination_fingerprint
      and placement.placement_reason='OFFICE_MOVE_BETWEEN_UNISSUED_INVOICES';
    if v_replay_count>0 then
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','MOVED','idempotent',true,
        'source_invoice_id',v_source_invoice_id,
        'destination_invoice_id',v_destination_invoice_id,
        'presentation_line_id',v_selected.id,
        'presentation_line_ids',pg_catalog.to_jsonb(v_presentation_ids),
        'movement_count',v_replay_count
      );
    end if;
  end if;
  if v_binding_invoice_ids<>array[v_source_invoice_id]::uuid[] then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_ON_SOURCE_INVOICE'
      using errcode='55000';
  end if;

  if v_source.document_revision is distinct from v_expected_source_revision
     or v_destination.document_revision is distinct from v_expected_destination_revision then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_STALE_REVISION' using errcode='40001';
  end if;
  if v_source.status::text<>'DRAFT' or v_destination.status::text<>'DRAFT'
     or v_source.issued_at_utc is not null or v_destination.issued_at_utc is not null
     or v_source.paid_at_utc is not null or v_destination.paid_at_utc is not null
     or v_source.active_document_operation_id is not null
     or v_destination.active_document_operation_id is not null
     or v_source.active_issue_operation_id is not null
     or v_destination.active_issue_operation_id is not null
     or pg_catalog.upper(coalesce(v_source.issue_state,'')) in (
       'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE'
     )
     or pg_catalog.upper(coalesce(v_destination.issue_state,'')) in (
       'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE'
     )
     or exists(
       select 1 from public.invoice_operation_chunks chunk
       where chunk.entity_type='INVOICE'
         and chunk.entity_id=any(array[v_source_invoice_id,v_destination_invoice_id])
         and chunk.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
     ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_REQUIRES_IDLE_DRAFTS' using errcode='55000';
  end if;
  -- PHD-003: same Client and both invoices unissued are the only business
  -- compatibility restrictions. Source group, cycle, week, report, profile
  -- and original batch remain immutable lineage on the presentation but never
  -- prevent its deliberate Office placement on another same-Client Draft.

  perform private.weekly_source_invoice_allocation_assert_v1(v_source_invoice_id);
  perform private.weekly_source_invoice_allocation_assert_v1(v_destination_invoice_id);

  perform 1
  from public.weekly_source_invoice_line_bindings binding
  join public.weekly_source_billing_movements movement
    on movement.id=binding.billing_movement_id
  where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
    and binding.presentation_line_id=any(v_presentation_ids)
  order by movement.id
  for update of binding,movement;
  select pg_catalog.count(*)::integer into v_movement_count
  from public.weekly_source_invoice_line_bindings binding
  join public.weekly_source_billing_movements movement
    on movement.id=binding.billing_movement_id
  where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
    and binding.presentation_line_id=any(v_presentation_ids)
    and movement.placement_state='PLACED';
  if v_movement_count=0 then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_FOUND' using errcode='22023';
  end if;
  if exists(
    select 1
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement
      on movement.id=binding.billing_movement_id
    where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
      and binding.presentation_line_id=any(v_presentation_ids)
      and movement.placement_state<>'PLACED'
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_PLACEMENT_INVALID' using errcode='55000';
  end if;
  select pg_catalog.array_agg(lines.invoice_line_id order by lines.invoice_line_id),
         pg_catalog.count(*)::integer
    into v_line_ids,v_line_count
  from (
    select distinct binding.invoice_line_id
    from public.weekly_source_invoice_line_bindings binding
    where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
      and binding.presentation_line_id=any(v_presentation_ids)
  ) lines;
  -- An indivisible presentation moves whole: no visible line in the move set
  -- may keep a CURRENT binding that is not part of the move set, and no member
  -- of the move set may sit on a line outside it.
  if exists(
    select 1
    from public.weekly_source_invoice_line_bindings binding
    where binding.invoice_line_id=any(v_line_ids) and binding.state='CURRENT'
      and (binding.invoice_id<>v_source_invoice_id
        or not (binding.presentation_line_id=any(v_presentation_ids)))
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_PARTIAL_LINE_REFUSED' using errcode='55000';
  end if;
  perform 1 from public.weekly_source_invoice_placements placement
  where placement.billing_movement_id in (
    select binding.billing_movement_id
    from public.weekly_source_invoice_line_bindings binding
    where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
      and binding.invoice_line_id=any(v_line_ids)
  ) and placement.is_current
  order by placement.billing_movement_id for update;

  perform pg_catalog.set_config(
    'cloudtms.weekly_source_invoice_owner','MOVE_SOURCE_INVOICE',true
  );
  update public.invoice_lines
  set invoice_id=v_destination_invoice_id
  where id=any(v_line_ids) and invoice_id=v_source_invoice_id;
  get diagnostics v_updated_line_count=row_count;
  if v_updated_line_count is distinct from v_line_count then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_CAS_LOST' using errcode='40001';
  end if;

  for v_binding in
    select binding.*,presentation.source_shift_group_id
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_invoice_presentation_lines presentation
      on presentation.id=binding.presentation_line_id
    where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
      and binding.presentation_line_id=any(v_presentation_ids)
    order by binding.billing_movement_id
  loop
    update public.weekly_source_invoice_line_bindings
    set state='SUPERSEDED',superseded_at_utc=pg_catalog.statement_timestamp()
    where id=v_binding.id and state='CURRENT';
    if not found then
      raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_BINDING_CAS_LOST' using errcode='40001';
    end if;
    v_new_binding_version:=v_binding.binding_version+1;
    v_binding_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_INVOICE_BINDING_V1',pg_catalog.jsonb_build_object(
        'movement_id',v_binding.billing_movement_id,
        'presentation_line_id',v_binding.presentation_line_id,
        'invoice_line_id',v_binding.invoice_line_id,
        'invoice_id',v_destination_invoice_id,
        'manifest_hash',pg_catalog.encode(v_binding.manifest_hash,'hex'),
        'binding_version',v_new_binding_version,
        'prior_binding_id',v_binding.id
      )
    );
    insert into public.weekly_source_invoice_line_bindings(
      billing_movement_id,presentation_line_id,invoice_line_id,invoice_id,
      original_final_revision_id,original_cycle_id,client_id,correction_root_id,
      correction_role,manifest_hash,materialised_line_hash,binding_version,
      prior_binding_id,state
    ) values (
      v_binding.billing_movement_id,v_binding.presentation_line_id,
      v_binding.invoice_line_id,v_destination_invoice_id,
      v_binding.original_final_revision_id,v_binding.original_cycle_id,
      v_binding.client_id,v_binding.correction_root_id,v_binding.correction_role,
      v_binding.manifest_hash,v_binding_hash,v_new_binding_version,v_binding.id,'CURRENT'
    );

    select * into strict v_placement
    from public.weekly_source_invoice_placements placement
    where placement.billing_movement_id=v_binding.billing_movement_id
      and placement.is_current;
    if v_placement.invoice_id is distinct from v_source_invoice_id
       or v_placement.invoice_line_id is distinct from v_binding.invoice_line_id
       or v_placement.placement_state<>'PLACED' then
      raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_PLACEMENT_INVALID' using errcode='55000';
    end if;
    update public.weekly_source_invoice_placements
    set is_current=false where id=v_placement.id and is_current;
    if not found then
      raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_PLACEMENT_CAS_LOST' using errcode='40001';
    end if;
    v_new_placement_revision:=v_placement.placement_revision+1;
    v_placement_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_INVOICE_PLACEMENT_V1',pg_catalog.jsonb_build_object(
        'movement_id',v_binding.billing_movement_id,
        'invoice_id',v_destination_invoice_id,
        'invoice_line_id',v_binding.invoice_line_id,
        'placement_revision',v_new_placement_revision,
        'placement_reason','OFFICE_MOVE_BETWEEN_UNISSUED_INVOICES',
        'prior_placement_id',v_placement.id,
        'source_invoice_version_fingerprint',pg_catalog.encode(v_source_fingerprint,'hex'),
        'destination_invoice_version_fingerprint',pg_catalog.encode(v_destination_fingerprint,'hex')
      )
    );
    insert into public.weekly_source_invoice_placements(
      billing_movement_id,source_shift_group_id,invoice_id,invoice_line_id,
      placement_revision,placement_state,is_current,original_automatic_cycle_id,
      current_target_cycle_id,placement_reason,actor_user_id,prior_placement_id,
      source_invoice_version_fingerprint,destination_invoice_version_fingerprint,
      placement_hash
    ) values (
      v_binding.billing_movement_id,v_binding.source_shift_group_id,
      v_destination_invoice_id,v_binding.invoice_line_id,
      v_new_placement_revision,'PLACED',true,v_placement.original_automatic_cycle_id,
      coalesce(v_destination_manifest.invoice_window_cycle_id,v_destination_manifest.source_cycle_id),'OFFICE_MOVE_BETWEEN_UNISSUED_INVOICES',
      v_actor,v_placement.id,v_source_fingerprint,v_destination_fingerprint,
      v_placement_hash
    );
  end loop;

  perform private.weekly_source_invoice_header_refresh_v1(v_source_invoice_id);
  perform private.weekly_source_invoice_header_refresh_v1(v_destination_invoice_id);
  perform public.invoice_recompute_totals(v_source_invoice_id);
  perform public.invoice_recompute_totals(v_destination_invoice_id);
  perform private.weekly_source_invoice_allocation_assert_v1(v_source_invoice_id);
  perform private.weekly_source_invoice_allocation_assert_v1(v_destination_invoice_id);
  perform pg_catalog.set_config('cloudtms.weekly_source_invoice_owner','',true);

  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_source_invoice_presentation_lines',v_selected.id::text,
         'WEEKLY_SOURCE_PRESENTATION_LINE_MOVED_BETWEEN_DRAFT_INVOICES',
         pg_catalog.jsonb_build_object(
           'source_invoice_id',v_source_invoice_id,
           'source_document_revision',v_expected_source_revision,
           'presentation_line_id',v_selected.id,
           'expected_presentation_hash',
             pg_catalog.encode(v_expected_presentation_hash,'hex')
         ),
         pg_catalog.jsonb_build_object(
           'destination_invoice_id',v_destination_invoice_id,
           'destination_document_revision',v_expected_destination_revision,
           'presentation_line_ids',pg_catalog.to_jsonb(v_presentation_ids),
           'work_event_id',v_selected.work_event_id,
           'line_count',v_line_count,'movement_count',v_movement_count,
           'different_finalised_week',
             v_source_manifest.source_cycle_id is distinct from coalesce(v_destination_manifest.invoice_window_cycle_id,v_destination_manifest.source_cycle_id)
         ),v_reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'status','MOVED','idempotent',false,
    'source_invoice_id',v_source_invoice_id,
    'destination_invoice_id',v_destination_invoice_id,
    'presentation_line_id',v_selected.id,
    'presentation_line_ids',pg_catalog.to_jsonb(v_presentation_ids),
    'line_count',v_line_count,'movement_count',v_movement_count
  );
end;
$function$;

create or replace function public.weekly_source_invoice_edit_context_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_invoice_id uuid;
  v_invoice public.invoices%rowtype;
  v_manifest public.weekly_source_client_manifests%rowtype;
  v_result jsonb;
  v_adjustment_authority jsonb;
  v_adjustments_allowed boolean:=false;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
       where key not in ('actor_user_id','invoice_id')) then
    raise exception 'WEEKLY_SOURCE_INVOICE_EDIT_CONTEXT_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_invoice_id:=(p_request->>'invoice_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_INVOICE_EDIT_CONTEXT_INVALID' using errcode='22023';
  end;
  select * into v_invoice from public.invoices where id=v_invoice_id;
  if not found or v_invoice.header_snapshot_json->>'schema_version'<>'WEEKLY_SOURCE_SELF_BILL_INVOICE_V1' then
    return pg_catalog.jsonb_build_object('is_weekly_source_invoice',false);
  end if;
  if not pg_catalog.pg_input_is_valid(
    coalesce(v_invoice.header_snapshot_json#>>'{meta,client_manifest_id}',''),'uuid'
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_EDIT_CONTEXT_INVALID' using errcode='22023';
  end if;
  select * into strict v_manifest from public.weekly_source_client_manifests
  where id=(v_invoice.header_snapshot_json#>>'{meta,client_manifest_id}')::uuid;
  perform private.weekly_source_office_authority_v1(
    v_actor,'VIEW_SOURCE_PROGRESS',v_manifest.source_group_id,
    v_manifest.client_id,v_manifest.finalisation_week_ending
  );

  v_adjustment_authority:=private.weekly_source_invoice_adjustment_authority_v1(v_invoice.id,null);
  v_adjustments_allowed:=coalesce(v_adjustment_authority->>'allowed'='true',false)
    and v_invoice.status='DRAFT' and v_invoice.issued_at_utc is null and v_invoice.paid_at_utc is null
    and v_invoice.active_document_operation_id is null and v_invoice.active_issue_operation_id is null
    and pg_catalog.upper(coalesce(v_invoice.issue_state,'')) not in('VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE')
    and exists(select 1 from public.tms_users u where u.id=v_actor and u.is_active and lower(btrim(u.role))='admin');

  select pg_catalog.jsonb_build_object(
    'is_weekly_source_invoice',true,
    'adjustments',pg_catalog.jsonb_build_object('contract_version','WEEKLY_SOURCE_INVOICE_ADJUSTMENTS_V1',
      'allowed',v_adjustments_allowed,'credits_shift_available',false,
      'default_vat_rate_pct',case when v_adjustments_allowed then v_adjustment_authority->>'vat_rate_pct' else null end),
    'invoice_id',v_invoice.id,'invoice_number',v_invoice.invoice_no,
    'document_revision',v_invoice.document_revision,
    'source_cycle_id',v_manifest.source_cycle_id,
    'invoice_window_cycle_id',coalesce(v_manifest.invoice_window_cycle_id,v_manifest.source_cycle_id),
    'finalisation_week_ending',v_manifest.finalisation_week_ending,
    'report_number',v_manifest.backing_report_number,
    'report_numbers',coalesce(
      v_invoice.header_snapshot_json#>'{meta,backing_report_numbers}',
      case when v_manifest.backing_report_number is null then '[]'::jsonb
        else pg_catalog.jsonb_build_array(v_manifest.backing_report_number) end
    ),
    'editable',v_invoice.status='DRAFT'
      and v_invoice.issued_at_utc is null and v_invoice.paid_at_utc is null
      and v_invoice.active_document_operation_id is null
      and v_invoice.active_issue_operation_id is null
      and pg_catalog.upper(coalesce(v_invoice.issue_state,'')) not in (
        'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE'
      ),
    -- Gate 7 item G7-2 (24 section 12; 25 section 8 Removed).
    -- The unit of movement offered to the Office is ONE immutable source
    -- presentation line, never a work event: "Moving by whole work-event ID is
    -- prohibited because it can move more than the Office selected."  Each row
    -- carries the presentation-line id and the expected presentation hash the
    -- move owner demands, plus the facts the Office needs to understand what
    -- will travel with it: an NHSP physical row is independently movable, a
    -- non-NHSP net presentation is indivisible, and a source-fixed expense
    -- follows its declared companion rather than being selected on its own.
    'movable_lines',coalesce((
      select pg_catalog.jsonb_agg(movable.row_json order by movable.work_date,
        movable.start_at_local,movable.candidate_display,movable.presentation_line_id)
      from (
        select presentation.id presentation_line_id,presentation.work_date,
          presentation.start_at_local,
          presentation.candidate_display_snapshot candidate_display,
          pg_catalog.jsonb_build_object(
            'presentation_line_id',presentation.id,
            'presentation_hash',pg_catalog.encode(presentation.presentation_hash,'hex'),
            'invoice_line_id',pg_catalog.min(binding.invoice_line_id::text)::uuid,
            'line_kind',presentation.line_kind,
            'origin_kind',presentation.origin_kind,
            'correction_role',presentation.correction_role,
            'work_event_id',presentation.work_event_id,
            'candidate',presentation.candidate_display_snapshot,
            'work_date',presentation.work_date,
            'start_at_local',presentation.start_at_local,
            'end_at_local',presentation.end_at_local,
            'break_minutes',presentation.break_minutes,
            -- Display-only source facts. Never use reference, ward or band as
            -- a movement identity or as an invoice amount authority.
            'source_reference',case when pg_catalog.count(distinct source_row.id)=1
              then pg_catalog.min(source_row.bounded_raw_columns_json->>'reference_number')
              else presentation.booking_reference_snapshot end,
            'source_ward',case when pg_catalog.count(distinct source_row.id)=1
              then pg_catalog.min(source_row.bounded_raw_columns_json->>'ward') else null end,
            'source_trust',case when pg_catalog.count(distinct source_row.id)=1
              then pg_catalog.min(source_row.bounded_raw_columns_json->>'trust') else null end,
            'source_hospital',case when pg_catalog.count(distinct source_row.id)=1
              then pg_catalog.min(source_row.bounded_raw_columns_json->>'hospital') else null end,
            'source_band',case when pg_catalog.count(distinct source_row.id)=1
              then pg_catalog.min(source_row.role_band_source) else null end,
            'timesheet_id',case when pg_catalog.count(distinct movement.invoice_timesheet_id)=1
              then pg_catalog.min(movement.invoice_timesheet_id::text)::uuid else null end,
            'description',presentation.description_snapshot,
            'bound_movement_count',pg_catalog.count(*)::integer,
            -- A presentation that binds more than one movement is the narrowly
            -- supported non-NHSP net presentation: it moves as one.
            'indivisible_presentation',pg_catalog.count(*)>1,
            'independently_movable',
              presentation.companion_presentation_line_id is null,
            'follows_companion_presentation_line_id',
              presentation.companion_presentation_line_id,
            'companion_presentation_line_ids',coalesce((
              select pg_catalog.jsonb_agg(companion.id order by companion.id)
              from public.weekly_source_invoice_presentation_lines companion
              where companion.companion_presentation_line_id=presentation.id
            ),'[]'::jsonb),
            'released_after_dispute',exists(
              select 1 from public.weekly_discrepancy_incidents incident
              where incident.source_group_id=v_manifest.source_group_id
                and incident.work_event_id=presentation.work_event_id
            )
          ) row_json
        from public.weekly_source_invoice_line_bindings binding
        join public.weekly_source_invoice_presentation_lines presentation
          on presentation.id=binding.presentation_line_id
        join public.weekly_source_billing_movements movement
          on movement.id=binding.billing_movement_id
        left join public.weekly_source_upload_rows source_row
          on source_row.id=movement.nhsp_upload_row_id
        where binding.invoice_id=v_invoice.id and binding.state='CURRENT'
        group by presentation.id,presentation.presentation_hash,presentation.line_kind,
          presentation.origin_kind,presentation.correction_role,presentation.work_event_id,
          presentation.candidate_display_snapshot,presentation.work_date,
          presentation.start_at_local,presentation.end_at_local,
          presentation.break_minutes,presentation.description_snapshot,
          presentation.companion_presentation_line_id
      ) movable
    ),'[]'::jsonb),
    'compatible_destinations',coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'invoice_id',destination.id,'invoice_number',destination.invoice_no,
        'document_revision',destination.document_revision,
        'finalisation_week_ending',destination_manifest.finalisation_week_ending,
        'report_numbers',coalesce(destination.header_snapshot_json#>'{meta,backing_report_numbers}','[]'::jsonb),
        'total_inc_vat',destination.total_inc_vat
      ) order by destination_manifest.finalisation_week_ending desc,destination.invoice_no,destination.id)
      from public.invoices destination
      join public.weekly_source_client_manifests destination_manifest
        on destination_manifest.id=case
          when pg_catalog.pg_input_is_valid(
            coalesce(destination.header_snapshot_json#>>'{meta,client_manifest_id}',''),'uuid'
          ) then (destination.header_snapshot_json#>>'{meta,client_manifest_id}')::uuid
          else null
        end
      where destination.id<>v_invoice.id
        and destination.header_snapshot_json->>'schema_version'='WEEKLY_SOURCE_SELF_BILL_INVOICE_V1'
        and destination.client_id=v_invoice.client_id
        and destination.status='DRAFT'
        and destination.issued_at_utc is null and destination.paid_at_utc is null
        and destination.active_document_operation_id is null
        and destination.active_issue_operation_id is null
        and pg_catalog.upper(coalesce(destination.issue_state,'')) not in (
          'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE'
        )
    ),'[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$function$;

-- The current invoice editor is re-included by later July repeatables. Reassert
-- its final service-only ACL after the frozen-settings source change so NEW and
-- UPGRADE installations end with the same browser-isolated authority.

alter function public.invoice_apply_edits(uuid,jsonb,uuid) OWNER TO CURRENT_USER;

revoke all on function public.invoice_apply_edits(uuid,jsonb,uuid)
  from public,anon,authenticated,service_role,supabase_admin;

grant execute on function public.invoice_apply_edits(uuid,jsonb,uuid)
  to CURRENT_USER,service_role;

alter function public.invoice_detail_get(uuid,uuid) OWNER TO CURRENT_USER;

revoke all on function public.invoice_detail_get(uuid,uuid)
  from public,anon,authenticated,service_role,supabase_admin;

grant execute on function public.invoice_detail_get(uuid,uuid)
  to CURRENT_USER,service_role;


alter function private.weekly_source_invoice_allocation_assert_v1(uuid) OWNER TO CURRENT_USER;
alter function private.weekly_source_invoice_issue_validate_v1(uuid) OWNER TO CURRENT_USER;
alter function public.weekly_source_invoice_move_atomic_v1(jsonb) OWNER TO CURRENT_USER;
alter function public.weekly_source_invoice_edit_context_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_invoice_allocation_assert_v1(uuid) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_invoice_issue_validate_v1(uuid) from public,anon,authenticated,service_role;
revoke all on function public.weekly_source_invoice_move_atomic_v1(jsonb) from public,anon,authenticated,service_role;
revoke all on function public.weekly_source_invoice_edit_context_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_source_invoice_move_atomic_v1(jsonb) to service_role;
grant execute on function public.weekly_source_invoice_edit_context_v1(jsonb) to service_role;



-- CONTACT_PREPARER_UNIT 120 repeatable supabase/repeatable/13102026_1706_healthroster_automatic_credit_candidates_v1.sql SHA256 abb5dce28a07ffa0491a818a0a6e164f838e402a436bb8a9dc93f63221eab924
-- Exact APPLIED scoped-credit read; activation/API/document qualification required.


-- PROPOSAL. Existing request and scoped credit owners remain the authority.
-- This bounded, purpose-only projection contains no financial snapshot or new
-- correction, query, comparison, document, payment or idempotency store.
create or replace function public.timesheet_correction_credit_candidates_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_actor uuid; v_after uuid; v_query jsonb; f jsonb; r record; v_scope jsonb;
  v_rows jsonb:='[]'::jsonb; v_more boolean:=false; v_next uuid; v_count integer:=0;
  v_code text; v_revision text; v_fact jsonb; v_facts jsonb:='[]'::jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if jsonb_typeof(p_request) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_request) k
    where k not in('actor_user_id','query','after_request_id'))
    or pg_input_is_valid(p_request->>'actor_user_id','uuid') is distinct from true
    or (p_request->>'after_request_id' is not null and pg_input_is_valid(p_request->>'after_request_id','uuid') is distinct from true) then
    raise exception 'CORRECTION_CREDIT_QUERY_INVALID' using errcode='22023'; end if;
  v_actor:=(p_request->>'actor_user_id')::uuid; v_after:=(p_request->>'after_request_id')::uuid;
  if not exists(select 1 from public.tms_users u where u.id=v_actor and u.is_active and lower(btrim(u.role))='admin') then
    raise exception 'INVOICE_ADMINISTRATOR_PERMISSION_REQUIRED' using errcode='42501'; end if;
  v_query:=private._invoice_batch_query_validate_v2(p_request->'query','GENERATE'); f:=v_query->'filters';
  if v_query->>'mode'='EXPLICIT_KEYS' then
    raise exception 'CORRECTION_CREDIT_EXPLICIT_SELECTION_FORBIDDEN' using errcode='22023'; end if;
  for r in
    select request.*,invoice.invoice_no,coalesce(nullif(candidate.display_name,''),
      nullif(concat_ws(' ',candidate.first_name,candidate.last_name),''),candidate.tms_ref,candidate.id::text) candidate_name,
      client.name client_name
    from private.timesheet_correction_requests request
    join public.invoices invoice on invoice.id=request.original_invoice_id and invoice.type='INVOICE' and invoice.status in('ISSUED','PAID')
      and invoice.client_id=request.client_id
    join public.candidates candidate on candidate.id=request.candidate_id
    join public.clients client on client.id=request.client_id
    where request.state='APPLIED' and request.origin in('SIGNED_TIMESHEET_CORRECTION','AGENCY_INVOICE_CORRECTION')
      and request.reversal_timesheet_id is not null and (v_after is null or request.id>v_after)
      and not exists(select 1 from public.invoices cn join public.invoice_lines l on l.invoice_id=cn.id
        where cn.original_invoice_id=invoice.id and cn.type='CREDIT_NOTE' and l.meta_json->>'reversal_timesheet_id'=request.reversal_timesheet_id::text)
      and (jsonb_array_length(coalesce(f->'client_ids','[]'::jsonb))=0 or request.client_id::text in(select jsonb_array_elements_text(f->'client_ids')))
      and (jsonb_array_length(coalesce(f->'candidate_ids','[]'::jsonb))=0 or request.candidate_id::text in(select jsonb_array_elements_text(f->'candidate_ids')))
      and (jsonb_array_length(coalesce(f->'week_endings','[]'::jsonb))=0 or request.week_ending_date::text in(select jsonb_array_elements_text(f->'week_endings')))
      and (nullif(f->>'week_ending_from','') is null or request.week_ending_date>=(f->>'week_ending_from')::date)
      and (nullif(f->>'week_ending_to','') is null or request.week_ending_date<=(f->>'week_ending_to')::date)
      and (jsonb_array_length(coalesce(f->'invoice_streams','[]'::jsonb))=0 or exists(select 1 from jsonb_array_elements_text(f->'invoice_streams') stream
        where stream=upper(coalesce(nullif(invoice.header_snapshot_json#>>'{meta,invoice_stream}',''),
          nullif(invoice.header_snapshot_json->>'invoice_stream',''),case when lower(coalesce(invoice.header_snapshot_json#>>'{meta,self_bill}','false'))
          in('true','t','1','yes') then 'SELF_BILL' else 'NORMAL' end))))
      and (nullif(btrim(f->>'search'),'') is null or concat_ws(' ',invoice.invoice_no,candidate.display_name,candidate.first_name,
        candidate.last_name,candidate.tms_ref,client.name,request.week_ending_date::text) ilike '%'||btrim(f->>'search')||'%')
    order by request.id
  loop
    -- A read error blocks this row truthfully. No missing-document or signed
    -- evidence becomes a fabricated READY row or an invoice-wide exception.
    begin
      v_scope:=private.invoice_credit_scope_context_v1(r.original_invoice_id,r.reversal_timesheet_id,null,null,false);
      v_code:=case when v_scope->>'valid'='true' then null else coalesce(v_scope->>'blocker','CREDIT_SCOPE_AUTHORITY_UNPROVED') end;
      v_revision:=v_scope->>'revision';
      if v_code is null and (v_scope->>'request_id' is distinct from r.id::text
        or v_scope->>'correction_id' is distinct from r.correction_id
        or v_scope->>'root_timesheet_id' is distinct from r.root_timesheet_id::text
        or v_scope->>'reversal_timesheet_id' is distinct from r.reversal_timesheet_id::text
        or v_scope->>'reversed_timesheet_id' is distinct from r.reversed_timesheet_id::text
        or v_scope->>'replacement_timesheet_id' is distinct from r.replacement_timesheet_id::text
        or v_scope->>'origin' is distinct from r.origin) then
        v_code:='CREDIT_SCOPE_AUTHORITY_UNPROVED';v_revision:=null;
      end if;
    exception when others then v_code:='CREDIT_SCOPE_AUTHORITY_UNAVAILABLE';v_revision:=null; end;
    -- No READY without the exact immutable native scoped revision.
    if coalesce(v_revision,'') !~ '^[0-9a-f]{64}$' then
      v_code:=coalesce(v_code,'CREDIT_SCOPE_AUTHORITY_UNPROVED');v_revision:=null;
    end if;
    if jsonb_array_length(coalesce(f->'status_codes','[]'::jsonb))>0 and not exists(select 1 from jsonb_array_elements_text(f->'status_codes') s
      where s=case when v_code is null then 'READY' else 'BLOCKED' end) then continue; end if;
    if coalesce(f->>'display_mode','ALL')<>'ALL' and f->>'display_mode'<>case when v_code is null then 'READY' else 'BLOCKED' end then continue; end if;
    if jsonb_array_length(coalesce(f->'blocker_codes','[]'::jsonb))>0 and not exists(select 1 from jsonb_array_elements_text(f->'blocker_codes') s where s=v_code) then continue; end if;
    if v_count=250 then v_more:=true;exit;end if;
    if v_revision is not null and v_revision !~ '^[0-9a-f]{64}$' then
      raise exception 'CORRECTION_CREDIT_PROJECTION_INVALID' using errcode='55000'; end if;
    v_fact:=jsonb_build_object('request_id',r.id,'root_timesheet_id',r.root_timesheet_id,'correction_id',r.correction_id,'state_revision',r.state_revision::text,
      'source_revision',v_revision,'original_invoice_id',r.original_invoice_id,'reversal_timesheet_id',r.reversal_timesheet_id,
      'reversed_timesheet_id',r.reversed_timesheet_id,'replacement_timesheet_id',r.replacement_timesheet_id,
      'client_id',r.client_id,'candidate_id',r.candidate_id,'week_ending_date',r.week_ending_date,
      'candidate_name',r.candidate_name,'invoice_number',r.invoice_no,'blocker_code',v_code);
    v_rows:=v_rows||jsonb_build_array(v_fact||jsonb_build_object('selection_key','healthroster-credit:'||r.original_invoice_id||':'||r.reversal_timesheet_id,
      'selectable',false,'automatic',true));
    v_facts:=v_facts||jsonb_build_array(v_fact);v_count:=v_count+1;v_next:=r.id;
  end loop;
  return jsonb_build_object('contract_version','TIMESHEET_CORRECTION_CREDIT_CANDIDATES_V1','rows',v_rows,
    'snapshot_hash',encode(private.weekly_source_sha256_jsonb_v1('TIMESHEET_CORRECTION_CREDIT_CANDIDATES_V1',
      jsonb_build_object('query',v_query,'after_request_id',v_after,'facts',v_facts)),'hex'),
    'page',jsonb_build_object('returned_count',v_count,'has_more',v_more,'next_request_id',case when v_more then v_next else null end));
end;
$function$;
alter function public.timesheet_correction_credit_candidates_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.timesheet_correction_credit_candidates_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.timesheet_correction_credit_candidates_v1(jsonb) to service_role;



-- CONTACT_PREPARER_UNIT 121 repeatable supabase/repeatable/13102026_1730_healthroster_checklist_private_read_v1.sql SHA256 92f6a8e35f442d2231d33e5efc86ec8bfae2f0e9f815f230dab68f5c838e75b2
-- Adjacent owner-private facts for the single native Checklist; no public route.


-- WP-U3 private read proposal. Not a repeatable root and not installed.
-- No public Checklist owner, ledger/store, writes, source shadow materialisation or rate lookup.
create or replace function private.weekly_source_actual_timesheet_submission_v1(p_timesheet_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare t public.timesheets%rowtype; c public.contracts%rowtype; f public.timesheets_financials%rowtype;
  w public.candidate_submission_workflows%rowtype; h public.candidate_submission_components%rowtype;
  sig public.candidate_submission_components%rowtype; v_client uuid; v_candidate uuid;
  v_count integer; v_date date; v_input jsonb; v_patch jsonb; v_evidence jsonb; v_reason text;
begin
  select * into t from public.timesheets where timesheet_id=p_timesheet_id;
  if t.timesheet_id is null or not t.is_current or t.archived_at_utc is not null or t.revoked_at is not null
    or t.status::text in('REVOKED','ARCHIVED','CANCELLED') or t.line_type::text<>'HOURS' or t.sheet_scope::text not in('WEEKLY','DAILY') then
    return jsonb_build_object('actual_submitted',false,'support_state','NOT_SUBMITTED','reason','NO_CURRENT_HOURS_TIMESHEET');
  end if;
  -- A waiting Office proposal is never a worker submission. Applied pair
  -- selection excludes displaced original and reversal before aggregation.
  if t.correction_kind='WHOLE_TIMESHEET_REVERSAL'
    or exists(select 1 from private.timesheet_correction_requests r where
      (r.state='WAITING' and r.replacement_timesheet_id=t.timesheet_id)
      or (r.state='APPLIED' and r.reversed_timesheet_id=t.timesheet_id)) then
    return jsonb_build_object('actual_submitted',false,'support_state','NOT_SUBMITTED','reason','CORRECTION_MEMBER_NOT_COUNTED');
  end if;
  select count(*),(array_agg(id order by id))[1] into v_count,f.id from public.timesheets_financials
    where timesheet_id=t.timesheet_id and is_current and timesheet_version=t.version;
  if v_count>1 then
    return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','CURRENT_FINANCIAL_IDENTITY_AMBIGUOUS');
  end if;
  if f.id is not null then select * into f from public.timesheets_financials where id=f.id; end if;
  if t.contract_id is not null then
    select * into c from public.contracts where id=t.contract_id;
    if c.id is null then
      return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','ACTUAL_CONTRACT_UNAVAILABLE');
    end if;
    v_client:=c.client_id; v_candidate:=c.candidate_id;
    if f.id is not null and (f.client_id is distinct from v_client or f.candidate_id is distinct from v_candidate) then
      return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','ACTUAL_FINANCIAL_OWNER_MISMATCH');
    end if;
  elsif t.sheet_scope::text='DAILY' and f.id is not null then
    v_client:=f.client_id; v_candidate:=f.candidate_id;
  else
    return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','NULL_CONTRACT_DAILY_OWNER_UNAVAILABLE');
  end if;
  if v_client is null or v_candidate is null or (nullif(t.settings_authority_json->>'client_id','') is not null
    and lower(t.settings_authority_json->>'client_id') is distinct from v_client::text) then
    return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','ACTUAL_OWNER_UNAVAILABLE');
  end if;
  -- Exact target binding can precede final TS workflow bookkeeping. Require
  -- one real submitted HOURS workflow for the actual Candidate and target.
  select count(*),(array_agg(id order by id))[1] into v_count,w.id
  from public.candidate_submission_workflows wf where wf.target_timesheet_id=t.timesheet_id
    and wf.candidate_id=v_candidate and wf.workflow_kind in('CONTRACT_HOURS','CONTRACT_COMBINED','DAILY')
    and wf.state in('WORKER_SUBMITTED','WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT','READY_FOR_MANAGER_APPROVAL',
      'AWAITING_MANAGER_APPROVAL','MANAGER_APPROVED','MANAGER_APPROVED_PENDING_FINAL_DOCUMENT',
      'READY_TO_FINALISE','AWAITING_PAPER_RETURN','RECEIVED','FINALISED')
    and wf.worker_submitted_at_utc is not null and wf.cancelled_at_utc is null
    and (t.candidate_workflow_id is null or (wf.id=t.candidate_workflow_id and wf.generation=t.candidate_workflow_generation));
  if v_count>1 then
    return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','SUBMISSION_WORKFLOW_AMBIGUOUS');
  end if;
  if w.id is not null then
    select * into w from public.candidate_submission_workflows where id=w.id;
    if jsonb_typeof(w.immutable_submission_json) is distinct from 'object'
      or octet_length(w.immutable_submission_sha256) is distinct from 32
      or private._candidate_sha256_jsonb_v1(w.immutable_submission_json) is distinct from w.immutable_submission_sha256
      or w.contract_id is distinct from t.contract_id or w.week_ending_date is distinct from t.week_ending_date
      or w.scope is distinct from t.sheet_scope::text
      or (t.sheet_scope::text='DAILY') is distinct from (w.workflow_kind='DAILY') then
      return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','IMMUTABLE_SUBMISSION_IDENTITY_UNPROVED');
    end if;
    v_input:=coalesce(w.immutable_submission_json->'hours_submission',w.immutable_submission_json);
    if jsonb_typeof(v_input) is distinct from 'object' then
      return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','IMMUTABLE_HOURS_SUBMISSION_UNAVAILABLE');
    end if;
    v_patch:=coalesce(v_input->'timesheet_patch_json',v_input);
    if jsonb_typeof(v_patch) is distinct from 'object' or (t.sheet_scope::text='WEEKLY'
      and jsonb_typeof(coalesce(v_patch->'actual_schedule_json',v_input#>'{canonical_tsfin_snapshot,actual_schedule_json}')) is distinct from 'array') then
      return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','FROZEN_WORKER_HOURS_CLAIM_UNAVAILABLE');
    end if;
    select count(*),(array_agg(id order by id))[1] into v_count,h.id
    from public.candidate_submission_components component where component.workflow_id=w.id
      and component.workflow_generation=w.generation and component.component_kind='HOURS_TIMESHEET'
      and component.required and component.state='IMMUTABLE' and component.immutable_at_utc is not null
      and (component.timesheet_id is null or component.timesheet_id=t.timesheet_id);
    if v_count<>1 then
      return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','IMMUTABLE_HOURS_COMPONENT_UNPROVED');
    end if;
    select * into h from public.candidate_submission_components where id=h.id;
    -- Electronic submission requires its native immutable Candidate signature.
    -- Paper workflows without that receipt remain a precise engineering gate;
    -- a later verified manual/QR source can qualify through the legacy arm.
    select * into sig from public.candidate_submission_components where id=w.candidate_signature_component_id
      and workflow_id=w.id and workflow_generation=w.generation and document_role='CANDIDATE_SIGNATURE'
      and state='IMMUTABLE' and immutable_at_utc is not null;
    if sig.id is null or w.candidate_signed_at_utc is null or nullif(btrim(sig.storage_key),'') is null
      or octet_length(sig.source_content_sha256) is distinct from 32
      or sig.source_content_sha256 is distinct from w.candidate_signature_sha256 then
      v_reason:='CANDIDATE_SUBMISSION_SIGNATURE_UNPROVED';
    else
      if t.sheet_scope::text='DAILY' then
        -- This unchanged native helper performs the actual submitted-hours
        -- patch projection; no guessed Daily JSON layout or booked fallback.
        v_patch:=private._candidate_daily_canonical_save_input_v1(w.id,w.generation)->'timesheet_patch_json';
        if not pg_input_is_valid(coalesce(v_patch->>'worked_start_iso',''),'timestamp with time zone')
          or not pg_input_is_valid(coalesce(v_patch->>'worked_end_iso',''),'timestamp with time zone') then
          return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','SUBMITTED_DAILY_WORK_DATE_UNAVAILABLE');
        end if;
        v_date:=( (v_patch->>'worked_start_iso')::timestamptz at time zone 'Europe/London')::date;
        if v_date is distinct from w.work_date or v_date<t.week_ending_date-6 or v_date>t.week_ending_date then
          return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','SUBMITTED_DAILY_WORK_DATE_MISMATCH');
        end if;
      else v_date:=t.week_ending_date; end if;
      return jsonb_build_object('actual_submitted',true,'support_state','PROVED','authority','CANDIDATE_IMMUTABLE_HOURS',
        'timesheet_id',t.timesheet_id,'timesheet_version',t.version,'client_id',v_client,'candidate_id',v_candidate,
        'contract_id',t.contract_id,'sheet_scope',t.sheet_scope,'week_ending_date',t.week_ending_date,'work_date',v_date,
        'workflow_id',w.id,'workflow_generation',w.generation,'submission_sha256',encode(w.immutable_submission_sha256,'hex'),
        'hours_component_id',h.id,'candidate_signature_component_id',sig.id,'submitted_at_utc',w.worker_submitted_at_utc,
        'manager_approved_at_utc',w.manager_approved_at_utc,'workflow_state',w.state);
    end if;
  end if;
  -- Reuse the normal read-only complete source/document contract. A manual
  -- key, planned clocks or bare schedule alone can never qualify this arm.
  v_evidence:=public._import_review_query_evidence_core_v1(t.timesheet_id);
  if coalesce((v_evidence->>'source_complete')::boolean,false)
    and coalesce((v_evidence->>'document_ready')::boolean,false) then
    v_date:=case when t.sheet_scope::text='DAILY' then (t.worked_start_iso at time zone 'Europe/London')::date else t.week_ending_date end;
    if v_date is null or v_date<t.week_ending_date-6 or v_date>t.week_ending_date then
      return jsonb_build_object('actual_submitted',false,'support_state','UNPROVED','reason','LEGACY_ACTUAL_WORK_DATE_UNAVAILABLE');
    end if;
    return jsonb_build_object('actual_submitted',true,'support_state','PROVED','authority','VERIFIED_LEGACY_SOURCE_DOCUMENT',
      'timesheet_id',t.timesheet_id,'timesheet_version',t.version,'client_id',v_client,'candidate_id',v_candidate,
      'contract_id',t.contract_id,'sheet_scope',t.sheet_scope,'week_ending_date',t.week_ending_date,'work_date',v_date,
      'document_version_id',v_evidence->'document_version_id','source_evidence_fingerprint',v_evidence->'evidence_fingerprint');
  end if;
  return jsonb_build_object('actual_submitted',false,'support_state',case when w.id is null
    and not coalesce((v_evidence->>'source_complete')::boolean,false) then 'NOT_SUBMITTED' else 'UNPROVED' end,
    'reason',coalesce(v_reason,'ACTUAL_SUBMISSION_SOURCE_WITNESS_UNAVAILABLE'));
end;
$function$;
alter function private.weekly_source_actual_timesheet_submission_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_actual_timesheet_submission_v1(uuid) from public,anon,authenticated,service_role;

-- Adjacent read admission only (§28.8). The F1 legal signed query/correction
-- predicate stays unchanged. An actual immutable worker Daily claim can remain
-- visible while native TS clocks are not materialised; no action becomes legal.
create or replace function private.weekly_source_signed_submission_read_context_v1(
  p_timesheet_id uuid,p_source_group_id uuid
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare t public.timesheets%rowtype; v_witness jsonb; v_client uuid; v_work_date date;
  v_policy jsonb; v_route record; v_native boolean;
begin
  v_witness:=private.weekly_source_actual_timesheet_submission_v1(p_timesheet_id);
  if (v_witness->>'actual_submitted')::boolean is distinct from true then
    return jsonb_build_object('eligible',false,'submission_witness',v_witness,'read_only',true);
  end if;
  select * into t from public.timesheets where timesheet_id=p_timesheet_id;
  v_client:=(v_witness->>'client_id')::uuid; v_work_date:=(v_witness->>'work_date')::date;
  if not exists(select 1 from public.weekly_source_groups g
    join public.weekly_source_group_clients member on member.source_group_id=g.id and member.client_id=v_client
    join public.weekly_source_client_policies policy on policy.source_group_id=g.id and policy.client_id=v_client
    join public.weekly_source_group_rule_assignments assignment on assignment.source_group_id=g.id
      and assignment.feature_enabled and assignment.feature_purpose='SIGNED_CHECK_ONLY' and assignment.rule_set_version_id is null
    where g.id=p_source_group_id and g.active and g.source_family='ROSTER'
      and v_work_date between member.valid_from and coalesce(member.valid_to,'infinity'::date)
      and t.week_ending_date between member.valid_from and coalesce(member.valid_to,'infinity'::date)
      and v_work_date between policy.effective_from and coalesce(policy.effective_to,'infinity'::date)
      and t.week_ending_date between assignment.effective_from_week_ending and coalesce(assignment.effective_to_week_ending,'infinity'::date)
      and policy.authority_mode='TIMESHEET_AUTHORITY' and policy.document_mode='INVOICE_EVIDENCE_REQUIRED' and not policy.self_bill_enabled) then
    return jsonb_build_object('eligible',false,'submission_witness',v_witness,'read_only',true);
  end if;
  v_native:=private.weekly_source_signed_check_only_v1(p_timesheet_id);
  if v_native then
    return jsonb_build_object('eligible',true,'read_only',true,'submission_witness',v_witness,
      'route_state','NATIVE_ROUTE_AVAILABLE','query_route_available',true,'pending_materialisation',false);
  end if;
  -- This exception admits an actual submitted record to a read, never query,
  -- manager/correction/Send/Authorise or financial mutation. Client/Contract,
  -- Candidate, work date, workflow/generation and signature are already proved
  -- by the unchanged canonical submitted-hours projection in the witness.
  if t.sheet_scope::text<>'DAILY' or t.worked_start_iso is not null
    or v_witness->>'authority' is distinct from 'CANDIDATE_IMMUTABLE_HOURS' then
    return jsonb_build_object('eligible',false,'submission_witness',v_witness,'read_only',true);
  end if;
  v_policy:=private._weekly_source_effective_policy_v1(v_client,t.contract_id,v_work_date);
  select * into v_route from public._import_review_effective_authority_core_v1('HR_DAILY',t.contract_id,v_client,v_work_date);
  if v_policy->>'source_family' is distinct from 'ROSTER' or v_policy->>'authority_mode' is distinct from 'TIMESHEET_AUTHORITY'
    or v_policy->>'document_mode' is distinct from 'INVOICE_EVIDENCE_REQUIRED'
    or coalesce((v_policy->>'self_bill_enabled')::boolean,true)
    or not coalesce(v_route.route_eligible,false) or not coalesce(v_route.validation_eligible,false)
    or coalesce(v_route.import_authoritative,true) or v_route.authority_mode is distinct from 'VALIDATION_ONLY'
    or coalesce(v_route.effective_is_nhsp,true) or coalesce(v_route.effective_no_timesheet_required,true) then
    return jsonb_build_object('eligible',false,'submission_witness',v_witness,'read_only',true);
  end if;
  return jsonb_build_object('eligible',true,'read_only',true,'submission_witness',v_witness,
    'route_state','SUBMITTED_PENDING_NATIVE_MATERIALISATION','query_route_available',false,
    'pending_materialisation',true,'actions_held',true,'action_hold_reason','NATIVE_DAILY_MATERIALISATION_PENDING');
end;
$function$;
alter function private.weekly_source_signed_submission_read_context_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_signed_submission_read_context_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- One private Source projection reused by Queries and Checklist. No query
-- store, discrepancy calculator, email send, validation mutation or public reader.
create or replace function private.weekly_source_check_only_query_rows_v1(
  p_source_cycle_id uuid,p_client_id uuid,p_filters jsonb
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; v_actor uuid; v_week date; v_limit integer:=50;
  v_cursor jsonb; v_binding text; v_revision text; v_rows jsonb; v_more boolean; v_last jsonb; v_admin boolean;
begin
  perform private._weekly_source_settings_assert_request_v1(p_filters,
    array['actor_user_id','source_group_id','week_ending','cursor','limit'], 'WEEKLY_SOURCE_CHECK_ONLY_FILTER_INVALID');
  v_actor:=nullif(p_filters->>'actor_user_id','')::uuid;
  if nullif(p_filters->>'week_ending','') is null or not pg_input_is_valid(p_filters->>'week_ending','date') then
    raise exception 'WEEKLY_SOURCE_CHECK_ONLY_FILTER_INVALID' using errcode='22023';
  end if;
  v_week:=(p_filters->>'week_ending')::date;
  select * into c from public.weekly_source_cycles where id=p_source_cycle_id;
  if c.id is null or p_client_id is null or (c.scope_client_id is not null and c.scope_client_id<>p_client_id)
    or v_week not between c.finalisation_week_ending-6 and c.finalisation_week_ending
    or (nullif(p_filters->>'source_group_id','') is not null and (p_filters->>'source_group_id')::uuid<>c.source_group_id) then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_NATIVE_SCOPE_UNAVAILABLE' using errcode='22023';
  end if;
  select lower(btrim(coalesce(role,'')))='admin' into v_admin from public.tms_users where id=v_actor and is_active;
  perform private.weekly_source_office_authority_v1(v_actor,case when v_admin then 'VIEW_SOURCE_PROGRESS' else 'VIEW_PAY_WORK' end,
    c.source_group_id,p_client_id,c.finalisation_week_ending);
  v_limit:=coalesce((p_filters->>'limit')::integer,50);
  if v_limit not between 1 and 100 then raise exception 'WEEKLY_SOURCE_CHECK_ONLY_FILTER_INVALID' using errcode='22023'; end if;
  v_binding:=encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_CHECK_ONLY_BINDING_V1',
    jsonb_build_object('actor',v_actor,'view',case when v_admin then 'ADMIN' else 'PAY_READONLY' end,
      'cycle',c.id,'client',p_client_id,'filters',p_filters-'cursor'-'limit')),'hex');
  if nullif(p_filters->>'cursor','') is not null then
    begin
      if length(p_filters->>'cursor')>4096 then raise exception 'cursor'; end if;
      v_cursor:=convert_from(decode(p_filters->>'cursor','base64'),'UTF8')::jsonb;
      if v_cursor->>'contract' is distinct from 'WEEKLY_SOURCE_CHECK_ONLY_CURSOR_V1' or v_cursor->>'binding' is distinct from v_binding
        or jsonb_typeof(v_cursor->'after') is distinct from 'array' or jsonb_array_length(v_cursor->'after')<>3
        or coalesce(v_cursor->>'read_revision','')!~'^[0-9a-f]{64}$'
        or jsonb_typeof(v_cursor#>'{after,0}') is distinct from 'string'
        or jsonb_typeof(v_cursor#>'{after,1}') is distinct from 'string'
        or jsonb_typeof(v_cursor#>'{after,2}') is distinct from 'string'
        or not pg_input_is_valid(coalesce(v_cursor#>>'{after,1}',''),'date')
        or length(coalesce(v_cursor#>>'{after,2}','')) not between 1 and 512 then raise exception 'cursor'; end if;
      perform private._weekly_source_settings_assert_request_v1(v_cursor,array['contract','binding','read_revision','after'],'CURSOR');
    exception when others then raise exception 'WEEKLY_SOURCE_CHECKLIST_ANCHORED_REFRESH_REQUIRED' using errcode='40001'; end;
  end if;
  with actual as materialized (
    select t.*,s.witness,rctx.route_read,cl.name client_name,coalesce(nullif(btrim(ca.first_name||' '||ca.last_name),''),ca.id::text) worker_name,
      private.weekly_source_query_ascii_fold_v1(coalesce(nullif(btrim(ca.first_name||' '||ca.last_name),''),ca.id::text)) collate "C" worker_sort,
      (s.witness->>'work_date')::date actual_work_date
    from public.timesheets t
    cross join lateral(select private.weekly_source_signed_submission_read_context_v1(t.timesheet_id,c.source_group_id) route_read) rctx
    cross join lateral(select rctx.route_read->'submission_witness' witness) s
    join public.clients cl on cl.id=p_client_id join public.candidates ca on ca.id=(s.witness->>'candidate_id')::uuid
    where (s.witness->>'actual_submitted')::boolean is true and s.witness->>'client_id'=p_client_id::text
      and t.week_ending_date between c.finalisation_week_ending-6 and c.finalisation_week_ending
      and t.week_ending_date=v_week
      and (rctx.route_read->>'eligible')::boolean is true
      and exists(select 1 from public.weekly_source_groups g
        join public.weekly_source_group_clients gc on gc.source_group_id=g.id and gc.client_id=p_client_id
        join public.weekly_source_client_policies cp on cp.source_group_id=g.id and cp.client_id=gc.client_id
        join public.weekly_source_group_rule_assignments ga on ga.source_group_id=g.id and ga.feature_enabled
          and ga.feature_purpose='SIGNED_CHECK_ONLY' and ga.rule_set_version_id is null
        where g.id=c.source_group_id and g.active and g.source_family='ROSTER'
          and (s.witness->>'work_date')::date between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)
          and t.week_ending_date between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)
          and (s.witness->>'work_date')::date between cp.effective_from and coalesce(cp.effective_to,'infinity'::date)
          and t.week_ending_date between ga.effective_from_week_ending and coalesce(ga.effective_to_week_ending,'infinity'::date)
          and cp.authority_mode='TIMESHEET_AUTHORITY' and cp.document_mode='INVOICE_EVIDENCE_REQUIRED' and not cp.self_bill_enabled)
  ), context as materialized (
    select a.*,tv.id validation_id,tv.status::text validation_status,tv.reason_code validation_reason,
      tv.last_source validation_import_id,tv.validated_at_utc,tf.id financial_id,tf.processing_status::text processing_status,
      r.id request_id,r.state request_state,r.state_revision request_state_revision,r.replacement_timesheet_id,
      pw.id replacement_workflow_id,pw.generation replacement_workflow_generation,pw.state replacement_workflow_state,
      pw.worker_submitted_at_utc replacement_submitted_at,pw.manager_approved_at_utc replacement_manager_approved_at,
      qi.id query_import_id,qi.uploaded_at_utc query_import_uploaded_at,qs.preview_generation,qs.state_version,
      qs.preview_fingerprint,qi.import_scope,qi.source_file_sha256,
      case when (a.route_read->>'query_route_available')::boolean is not true then null
        when qi.id is not null then private.weekly_source_issued_signed_query_evidence_v1(a.timesheet_id,qi.id)
        else public._import_review_query_evidence_core_v1(a.timesheet_id) end query_evidence
    from actual a
    left join lateral(select * from public.timesheet_validations v where v.timesheet_id=a.timesheet_id
      order by v.updated_at desc,v.created_at desc,v.id desc limit 1) tv on true
    left join public.timesheets_financials tf on tf.timesheet_id=a.timesheet_id and tf.is_current and tf.timesheet_version=a.version
    left join lateral(select * from private.timesheet_correction_requests request where request.state='WAITING'
      and request.reversed_timesheet_id=a.timesheet_id order by request.id limit 1) r on true
    left join public.timesheets pt on pt.timesheet_id=r.replacement_timesheet_id
    left join public.candidate_submission_workflows pw on pw.id=pt.candidate_workflow_id and pw.generation=pt.candidate_workflow_generation
    left join lateral(select hi.* from public.hr_imports hi
      where hi.pruned_at is null and hi.source_system::text in('HEALTHROSTER','HEALTHROSTER_DAILY')
        and (hi.client_id is null or hi.client_id=p_client_id)
        and (hi.id=tv.last_source or exists(select 1 from public.import_review_decisions d join public.import_review_states st on st.import_id=d.import_id
          and st.preview_generation=d.preview_generation and st.superseded_at_utc is null and st.abandoned_at_utc is null
          where d.import_id=hi.id and d.timesheet_id=a.timesheet_id and d.client_id=p_client_id and d.is_current))
      order by hi.uploaded_at_utc desc,hi.id desc limit 1) qi on true
    left join public.import_review_states qs on qs.import_id=qi.id
  ), rows as materialized (
    select x.worker_sort,x.actual_work_date,('timesheet:'||x.timesheet_id) collate "C" item_sort,
      jsonb_build_object('item_id','timesheet:'||x.timesheet_id,'timesheet_id',x.timesheet_id,'item_kind','ACTUAL_TIMESHEET',
      'source_group_id',c.source_group_id,'source_cycle_id',c.id,'client_id',p_client_id,'client',x.client_name,
      'candidate_id',x.witness->'candidate_id','worker',x.worker_name,'week_ending',x.week_ending_date,
      'work_date',x.actual_work_date,'sheet_scope',x.sheet_scope,'submission_witness',x.witness,
      'submission_read_context',x.route_read,
      'validation',jsonb_build_object('id',x.validation_id,'status',x.validation_status,'reason_code',x.validation_reason,
        'last_source',x.validation_import_id,'validated_at_utc',x.validated_at_utc),
      'ordinary_authorised',x.authorised_at_server is not null,'financial_id',x.financial_id,'processing_status',x.processing_status,
      'correction_owns_read_item',x.request_id is not null,'ordinary_query_reminder_suppressed',x.request_id is not null,
      'correction',case when x.request_id is not null then jsonb_build_object('request_id',x.request_id,'state',x.request_state,
        'state_revision',x.request_state_revision,'replacement_timesheet_id',x.replacement_timesheet_id,
        'workflow_id',x.replacement_workflow_id,'workflow_generation',x.replacement_workflow_generation,
        'workflow_state',x.replacement_workflow_state,'worker_submitted_at_utc',x.replacement_submitted_at,
        'manager_approved_at_utc',x.replacement_manager_approved_at) end,
      -- Pay work remains available for native subject admission, but invoice
      -- query evidence, recipients and delivery history are admin-only.
      'query_import_id',case when v_admin then x.query_import_id end,
      'query_evidence',case when v_admin then x.query_evidence end,
      'native_issues',case when v_admin and (x.route_read->>'query_route_available')::boolean is true
        then coalesce(issues.value,'[]'::jsonb) else '[]'::jsonb end,
      'unfinished_daily_review',case when x.sheet_scope::text='DAILY' and x.query_import_id is not null
        and upper(coalesce(x.import_scope,''))='HR_DAILY' then exists(select 1 from public.import_review_states ds
          where ds.import_id=x.query_import_id and ds.applied_at_utc is null and ds.superseded_at_utc is null and ds.abandoned_at_utc is null) else false end,
      'engineering_gate',case when x.validation_reason is not null and x.validation_status<>'VALIDATION_OK'
        and x.query_import_id is null then 'CURRENT_IMPORT_REVIEW_ISSUE_SNAPSHOT_UNAVAILABLE' end) value
    from context x
    left join lateral(select jsonb_agg(jsonb_build_object('action_id',d.action_id,'action_kind',d.action_kind,
      'evidence_fingerprint',d.evidence_fingerprint,'reason_code',d.summary_json->'reason_code','summary',d.summary_json,
      'issue_id',e.id,'issue_fingerprint',e.issue_fingerprint,'recipient_scope',e.recipient_scope,
      'sent_verified',e.delivery_history_status='SENT_VERIFIED' and delivery.status='SENT'
        and delivery.accepted_at_utc is not null and delivery.marked_at_utc is not null
        and item.marked_sent_at_utc is not null and (upper(mail.status::text)='SENT' or mail.sent_at is not null),
      'last_sent_at',e.last_sent_at,'sent_count',e.sent_count,'delivery_id',delivery.id,
      'recipient_email',delivery.recipient_email,'reminder_sequence',delivery.reminder_sequence,
      'mail_outbox_id',mail.id,'mail_status',mail.status,'accepted_at_utc',delivery.accepted_at_utc) order by d.action_id) value
      from public.import_review_decisions d
      left join public.hr_issue_emails e on e.issue_fingerprint=coalesce(nullif(d.summary_json->>'issue_fingerprint',''),d.source_identity)
        and e.timesheet_id=x.timesheet_id and e.client_id=p_client_id
      left join public.hr_issue_email_deliveries delivery on delivery.id=e.last_successful_delivery_id
      left join public.hr_issue_email_delivery_items item on item.delivery_id=delivery.id and item.issue_id=e.id
        and item.issue_fingerprint=e.issue_fingerprint and item.action_id=d.action_id
      left join public.mail_outbox mail on mail.id=delivery.mail_outbox_id and mail.deterministic_outbox_key=delivery.deterministic_outbox_key
      where d.import_id=x.query_import_id and d.preview_generation=x.preview_generation and d.is_current
        and d.timesheet_id=x.timesheet_id and d.client_id=p_client_id
        and d.action_kind in('EMAIL_WEEKLY_ISSUES','EMAIL_DAILY_ISSUES','EMAIL_MISSING_FROM_IMPORT')) issues on true
  ), source_information as materialized (
    -- R-254 is informational inside an admitted actual-submission row. Native
    -- missing-source advisories never create a Checklist row or Timesheet count.
    -- They carry native action identity/reason, with no fabricated TS target.
    select private.weekly_source_query_ascii_fold_v1(coalesce(nullif(btrim(ca.first_name||' '||ca.last_name),''),
        d.summary_json->>'candidate_name',hr.staff_raw,hr.staff_norm)) collate "C" worker_sort,
      hr.date_local actual_work_date,('native-action:'||d.action_id) collate "C" item_sort,
      jsonb_build_object('item_id','native-action:'||d.action_id,'item_kind','SOURCE_INFORMATION',
        'timesheet_id',null,'counted_timesheet_id',null,'counts_for_row_admission',false,
        'source_group_id',c.source_group_id,'source_cycle_id',c.id,'client_id',p_client_id,
        'client',cl.name,'candidate_id',d.candidate_id,
        'worker',coalesce(nullif(btrim(ca.first_name||' '||ca.last_name),''),d.summary_json->>'candidate_name',hr.staff_raw,hr.staff_norm),
        'work_date',hr.date_local,'week_ending',own_week.week_ending_date,
        'sheet_scope',case when upper(coalesce(d.summary_json->>'source_route','')) like '%DAILY%' then 'DAILY' else 'WEEKLY' end,
        'query_import_id',d.import_id,'hr_row_id',d.hr_row_id,'action_id',d.action_id,
        'action_kind',d.action_kind,'evidence_fingerprint',d.evidence_fingerprint,'summary',d.summary_json,
        'native_reason_code',d.summary_json->>'reason_code','writable_action',null) value
    from public.import_review_decisions d
    join public.import_review_states st on st.import_id=d.import_id and st.preview_generation=d.preview_generation
      and st.superseded_at_utc is null and st.abandoned_at_utc is null
    join public.hr_imports hi on hi.id=d.import_id and hi.pruned_at is null
      and hi.source_system::text in('HEALTHROSTER','HEALTHROSTER_DAILY') and (hi.client_id is null or hi.client_id=p_client_id)
    join public.hr_rows hr on hr.id=d.hr_row_id and hr.import_id=d.import_id
    join lateral(select min(admitted.week_ending_date) week_ending_date from actual admitted
      where hr.date_local between admitted.week_ending_date-6 and admitted.week_ending_date
      having count(distinct admitted.week_ending_date)=1) own_week on true
    join public.clients cl on cl.id=p_client_id left join public.candidates ca on ca.id=d.candidate_id
    where v_admin and d.client_id=p_client_id and d.timesheet_id is null and d.is_current
      and d.action_kind='ADVISORY' and d.summary_json->>'authority_mode'='VALIDATION_ONLY'
      and d.summary_json->>'reason_code' in('DAILY_TIMESHEET_NOT_SUBMITTED','WEEKLY_TIMESHEET_NOT_SUBMITTED',
        'WEEKLY_TIMESHEET_AWAITING_MANAGER_APPROVAL','WEEKLY_TIMESHEET_COMPLETING')
      and own_week.week_ending_date between c.finalisation_week_ending-6 and c.finalisation_week_ending
      and own_week.week_ending_date=v_week
      and exists(select 1 from actual admitted where admitted.week_ending_date=own_week.week_ending_date)
      and exists(select 1 from public.weekly_source_group_clients member
        join public.weekly_source_client_policies policy on policy.source_group_id=member.source_group_id and policy.client_id=member.client_id
        where member.source_group_id=c.source_group_id and member.client_id=p_client_id
          and hr.date_local between member.valid_from and coalesce(member.valid_to,'infinity'::date)
          and hr.date_local between policy.effective_from and coalesce(policy.effective_to,'infinity'::date)
          and policy.authority_mode='TIMESHEET_AUTHORITY' and policy.document_mode='INVOICE_EVIDENCE_REQUIRED' and not policy.self_bill_enabled)
      and hi.id=(select latest.id from public.hr_imports latest
        join public.import_review_states latest_state on latest_state.import_id=latest.id
          and latest_state.superseded_at_utc is null and latest_state.abandoned_at_utc is null
        where latest.pruned_at is null and latest.source_system=hi.source_system
          and (latest.client_id is null or latest.client_id=p_client_id)
          and exists(select 1 from public.import_review_decisions latest_decision
            left join public.hr_rows latest_row on latest_row.id=latest_decision.hr_row_id and latest_row.import_id=latest.id
            where latest_decision.import_id=latest.id and latest_decision.preview_generation=latest_state.preview_generation
              and latest_decision.is_current and latest_decision.client_id=p_client_id
              and (latest_row.date_local between own_week.week_ending_date-6 and own_week.week_ending_date
                or exists(select 1 from actual latest_actual where latest_actual.timesheet_id=latest_decision.timesheet_id
                  and latest_actual.week_ending_date=own_week.week_ending_date)))
        order by latest.uploaded_at_utc desc,latest.id desc limit 1)
  ), all_rows as materialized (
    select * from rows union all select * from source_information
  ), version as (
    select encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_CHECK_ONLY_READ_REVISION_V1',
      coalesce(jsonb_agg(value order by worker_sort,actual_work_date,item_sort),'[]'::jsonb)),'hex') hash from all_rows
  ), page as (
    select * from all_rows where v_cursor is null or (worker_sort,actual_work_date,item_sort)>
      (v_cursor#>>'{after,0}',(v_cursor#>>'{after,1}')::date,v_cursor#>>'{after,2}')
    order by worker_sort,actual_work_date,item_sort limit v_limit+1
  ) select (select hash from version),coalesce(jsonb_agg(value order by worker_sort,actual_work_date,item_sort),'[]'::jsonb),count(*)>v_limit
    into v_revision,v_rows,v_more from page;
  if v_cursor is not null and v_cursor->>'read_revision' is distinct from v_revision then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_ANCHORED_REFRESH_REQUIRED' using errcode='40001';
  end if;
  if v_more then v_rows:=v_rows-(jsonb_array_length(v_rows)-1); end if;
  v_last:=v_rows->(jsonb_array_length(v_rows)-1);
  return jsonb_build_object('ok',true,'contract','WEEKLY_SOURCE_CHECK_ONLY_QUERY_ROWS_V1','rows',v_rows,
    'read_only',true,'invoice_subjects_hidden',not coalesce(v_admin,false),
    'read_revision',v_revision,'binding',v_binding,'has_more',v_more,'next_cursor',case when v_more then
      encode(convert_to(jsonb_build_object('contract','WEEKLY_SOURCE_CHECK_ONLY_CURSOR_V1','binding',v_binding,'read_revision',v_revision,
        'after',jsonb_build_array(private.weekly_source_query_ascii_fold_v1(v_last->>'worker'),v_last->'work_date',v_last->'item_id'))::text,'UTF8'),'base64') end);
end;
$function$;
alter function private.weekly_source_check_only_query_rows_v1(uuid,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_check_only_query_rows_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;

-- Calendar read only. The canonical settings owner supplies the Client weekday.
-- No Timesheet, financial, source, or application record is created here.
create or replace function private.weekly_source_checklist_client_calendar_v1(
  p_client_id uuid,p_local_today date
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare authority jsonb; weekday integer; latest_week date;
begin
  if p_client_id is null or p_local_today is null then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_CLIENT_WEEK_AUTHORITY_UNAVAILABLE' using errcode='22023';
  end if;
  authority:=private._contract_settings_effective_core_v1(p_client_id,null,p_local_today,'OFFICE',null);
  if authority->>'authority_version' is distinct from 'CONTRACT_SETTINGS_AUTHORITY_V1'
    or authority->>'client_id' is distinct from p_client_id::text
    or not pg_input_is_valid(coalesce(authority#>>'{values,week_ending_weekday}',''),'integer')
    or coalesce(authority->>'authority_fingerprint','')!~'^[0-9a-f]{64}$' then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_CLIENT_WEEK_AUTHORITY_UNAVAILABLE' using errcode='55000';
  end if;
  weekday:=(authority#>>'{values,week_ending_weekday}')::integer;
  if weekday not between 0 and 6 then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_CLIENT_WEEK_AUTHORITY_UNAVAILABLE' using errcode='55000';
  end if;
  -- A week ending today has not ended yet. Walk back from yesterday.
  latest_week:=p_local_today-1-((extract(dow from p_local_today-1)::integer-weekday+7)%7);
  return jsonb_build_object('contract','WEEKLY_SOURCE_CHECKLIST_CLIENT_CALENDAR_V1',
    'client_id',p_client_id,'local_today',p_local_today,'week_ending_weekday',weekday,
    'latest_ended_week',latest_week,'authority_fingerprint',authority->>'authority_fingerprint');
end;
$function$;
alter function private.weekly_source_checklist_client_calendar_v1(uuid,date) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_checklist_client_calendar_v1(uuid,date) from public,anon,authenticated,service_role;

-- Private Source leaf for the one Banking/native Checklist owner after root
-- integration. This returns read facts, never financial classification or paid.
create or replace function private.weekly_source_healthroster_checklist_leaf_v1(p_request jsonb)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  v_actor uuid; v_client uuid; v_week date; v_today date; v_admin boolean; v_rule jsonb;
  v_route text; v_actual jsonb; v_facts jsonb; v_unproved jsonb; v_gate jsonb:='[]'::jsonb;
  v_latest_week date; v_latest_timesheet_week date; v_calendar_authority jsonb;
  v_open integer; v_earlier_open integer; v_count integer; v_wait integer:=0; v_wait_fact jsonb; v_event record;
begin
  perform private._weekly_source_settings_assert_request_v1(p_request,
    array['actor_user_id','source_cycle_id','source_group_id','client_id','week_ending','command','cursor','limit'],
    'WEEKLY_SOURCE_CHECKLIST_LEAF_REQUEST_INVALID');
  v_actor:=(p_request->>'actor_user_id')::uuid; v_client:=(p_request->>'client_id')::uuid;
  if coalesce(p_request->>'command','CONTEXT') not in('CONTEXT','ISSUES') then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_LEAF_REQUEST_INVALID' using errcode='22023';
  end if;
  v_week:=(p_request->>'week_ending')::date;
  select * into c from public.weekly_source_cycles where id=(p_request->>'source_cycle_id')::uuid;
  select * into g from public.weekly_source_groups where id=c.source_group_id and active;
  if c.id is null or g.id is null or v_client is null or v_week is null
    or v_week not between c.finalisation_week_ending-6 and c.finalisation_week_ending
    or (c.scope_client_id is not null and c.scope_client_id<>v_client)
    or (nullif(p_request->>'source_group_id','') is not null and (p_request->>'source_group_id')::uuid<>g.id)
    or not exists(select 1 from public.weekly_source_group_clients membership where membership.source_group_id=g.id
      and membership.client_id=v_client and v_week between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)) then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_NATIVE_SCOPE_UNAVAILABLE' using errcode='22023';
  end if;
  select lower(btrim(coalesce(role,'')))='admin' into v_admin from public.tms_users where id=v_actor and is_active;
  perform private.weekly_source_office_authority_v1(v_actor,case when v_admin then 'VIEW_SOURCE_PROGRESS' else 'VIEW_PAY_WORK' end,g.id,v_client,v_week);
  v_today:=(statement_timestamp() at time zone g.timezone)::date;
  if g.source_family<>'ROSTER' then return jsonb_build_object('applies',false,'preserve_native',true); end if;
  v_rule:=private.weekly_source_effective_rule_set_v1(v_client,c.id);
  v_route:=case when v_rule is not null then case when v_rule#>>'{values,invoice_sender}'='AGENCY_INVOICE'
    then 'AGENCY_INVOICE' else 'SELF_BILL' end end;
  if v_route is null and exists(select 1 from public.weekly_source_group_rule_assignments a
    join public.weekly_source_client_policies p on p.source_group_id=a.source_group_id and p.client_id=v_client
    where a.source_group_id=g.id and a.feature_enabled and a.feature_purpose='SIGNED_CHECK_ONLY' and a.rule_set_version_id is null
      and v_week between a.effective_from_week_ending and coalesce(a.effective_to_week_ending,'infinity'::date)
      and v_week between p.effective_from and coalesce(p.effective_to,'infinity'::date)
      and p.authority_mode='TIMESHEET_AUTHORITY' and p.document_mode='INVOICE_EVIDENCE_REQUIRED' and not p.self_bill_enabled) then
    v_route:='SIGNED_TIMESHEETS';
  end if;
  if v_route is null then return jsonb_build_object('applies',false,'preserve_native',true); end if;
  -- R-252 retains the client's latest ended calendar week, not its latest
  -- week containing a Timesheet. A completed old week must disappear even
  -- when no worker submitted a newer week. Reuse the native settings owner.
  v_calendar_authority:=private.weekly_source_checklist_client_calendar_v1(v_client,v_today);
  v_latest_week:=(v_calendar_authority->>'latest_ended_week')::date;
  -- Only actual Client authority narrows the witness scan. There is no booked
  -- Client/booking-name or live current-setting substitute for nullable Daily.
  with scoped as materialized (
    select t.*,s.witness,rctx.route_read,tv.status::text validation_status,tv.last_source validation_import_id,tf.processing_status::text processing_status,
      exists(select 1 from private.timesheet_correction_requests r where r.state='WAITING'
        and r.reversed_timesheet_id=t.timesheet_id) correction_waiting
    from public.timesheets t left join public.contracts con on con.id=t.contract_id
    left join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current and tf.timesheet_version=t.version
    cross join lateral(select case when v_route='SIGNED_TIMESHEETS'
      then private.weekly_source_signed_submission_read_context_v1(t.timesheet_id,g.id)
      else jsonb_build_object('eligible',true,'submission_witness',private.weekly_source_actual_timesheet_submission_v1(t.timesheet_id)) end route_read) rctx
    cross join lateral(select rctx.route_read->'submission_witness' witness) s
    left join lateral(select * from public.timesheet_validations v where v.timesheet_id=t.timesheet_id
      order by v.updated_at desc,v.created_at desc,v.id desc limit 1) tv on true
    where t.is_current and t.archived_at_utc is null and t.revoked_at is null
      and coalesce(con.client_id,case when t.contract_id is null and t.sheet_scope::text='DAILY' then tf.client_id end)=v_client
      and t.week_ending_date<v_today
      and exists(select 1 from public.weekly_source_group_clients m where m.source_group_id=g.id and m.client_id=v_client
        and t.week_ending_date between m.valid_from and coalesce(m.valid_to,'infinity'::date))
  ), counted as (
    select *,authorised_at_server is null or validation_status is distinct from 'VALIDATION_OK'
      or processing_status='READY_FOR_HR' or correction_waiting
      or exists(select 1 from public.import_review_decisions d join public.import_review_states st on st.import_id=d.import_id
          and st.preview_generation=d.preview_generation and st.superseded_at_utc is null and st.abandoned_at_utc is null
        join public.hr_imports hi on hi.id=d.import_id and hi.pruned_at is null
        where d.timesheet_id=scoped.timesheet_id and d.client_id=v_client and d.is_current
          and d.action_kind in('EMAIL_WEEKLY_ISSUES','EMAIL_DAILY_ISSUES','EMAIL_MISSING_FROM_IMPORT')
          and hi.id=(select current_import.id from public.hr_imports current_import
            where current_import.pruned_at is null and (current_import.id=scoped.validation_import_id
              or exists(select 1 from public.import_review_decisions current_decision
              join public.import_review_states current_state on current_state.import_id=current_decision.import_id
                and current_state.preview_generation=current_decision.preview_generation
                and current_state.superseded_at_utc is null and current_state.abandoned_at_utc is null
              where current_decision.import_id=current_import.id and current_decision.timesheet_id=scoped.timesheet_id
                and current_decision.client_id=v_client and current_decision.is_current))
            order by current_import.uploaded_at_utc desc,current_import.id desc limit 1)) open_read_item
    from scoped where (witness->>'actual_submitted')::boolean is true and (route_read->>'eligible')::boolean is true
  ) select max(week_ending_date),count(*) filter(where week_ending_date=v_week)::integer,
    count(*) filter(where week_ending_date=v_week and open_read_item)::integer,
    coalesce(jsonb_agg(jsonb_build_object('timesheet_id',timesheet_id,'witness',witness,'submission_read_context',route_read,
      'ordinary_authorised',authorised_at_server is not null,'validation_status',validation_status,
      'processing_status',processing_status,'correction_waiting',correction_waiting,'open_read_item',open_read_item)
      order by timesheet_id) filter(where week_ending_date=v_week),'[]'::jsonb),
    count(distinct week_ending_date) filter(where open_read_item and week_ending_date<v_latest_week)::integer,
    coalesce((select jsonb_agg(jsonb_build_object('code',reason,'unproved_timesheet_count',number) order by reason)
      from(select witness->>'reason' reason,count(distinct timesheet_id) number from scoped
        where week_ending_date=v_week and witness->>'support_state'='UNPROVED'
        group by witness->>'reason') unproved),'[]'::jsonb)
    into v_latest_timesheet_week,v_count,v_open,v_actual,v_earlier_open,v_unproved from counted;
  v_gate:=v_gate||v_unproved;
  if v_route='SIGNED_TIMESHEETS' and (v_count=0 or (v_week<>v_latest_week and v_open=0)) then
    return jsonb_build_object('applies',true,'admitted',false,'route',v_route,'preserve_native',false,
      'actual_timesheet_count',v_count,'engineering_gates',v_gate);
  end if;
  -- This cell duty is process completion, not cash settlement. Keep every
  -- final scope/revision receipt; a CURRENT client completion is not enough
  -- for separate export pay plus invoice report history.
  select jsonb_build_object(
    'expected_contract_weeks',coalesce((select jsonb_agg(jsonb_build_object('contract_week_id',cw.id,
      'contract_id',cw.contract_id,'status',cw.status,'week_ending',cw.week_ending_date,'timesheet_id',cw.timesheet_id) order by cw.id)
      from public.contract_weeks cw join public.contracts con on con.id=cw.contract_id and con.client_id=v_client
      where cw.week_ending_date=v_week and cw.additional_seq=0 and not cw.is_adjustment
        and cw.status::text in('PLANNED','OPEN','SUBMITTED')),'[]'::jsonb),
    'accepted_checking_uploads',coalesce((select jsonb_agg(jsonb_build_object('upload_id',u.id,'uploaded_at_utc',u.uploaded_at_utc,
      'coverage_start',u.confirmed_coverage_start_local_date,'coverage_end',u.confirmed_coverage_end_local_date,
      'coverage_confirmed_at_utc',u.coverage_confirmed_at_utc,'coverage_confirmed_by',u.coverage_confirmed_by_user_id,
      'covers_whole_week',u.confirmed_coverage_start_local_date<=v_week-6 and u.confirmed_coverage_end_local_date>=v_week,
      'state',u.state,'accepted_attempt_id',attempt.id,'import_use',u.file_metadata_json->'import_use') order by u.uploaded_at_utc desc,u.id)
      from public.weekly_source_uploads u
      join lateral(select a.id from public.weekly_source_upload_attempts a where a.logical_upload_id=u.id and a.result='ACCEPTED'
        order by a.attempted_at_utc desc,a.id desc limit 1) attempt on true
      where u.source_cycle_id=c.id and u.report_scope_id is null and u.state in('CURRENT','SUPERSEDED')
        and upper(coalesce(u.file_metadata_json->>'import_use',''))='CHECKING'
        and (c.scope_client_id=v_client or exists(select 1 from public.weekly_source_row_resolutions rr
          where rr.upload_row_id in(select ur.id from public.weekly_source_upload_rows ur where ur.upload_id=u.id)
            and rr.client_id=v_client and rr.mapping_state='RESOLVED'))),'[]'::jsonb),
    'completion_history',coalesce((select jsonb_agg(to_jsonb(completion) order by completion.completion_generation,completion.id)
      from public.weekly_source_client_cycle_completions completion where completion.source_cycle_id=c.id and completion.client_id=v_client),'[]'::jsonb),
    'final_revision_history',coalesce((select jsonb_agg(jsonb_build_object('final_revision_id',fr.id,'authority_scope_kind',fr.authority_scope_kind,
      'report_scope_id',fr.report_scope_id,'state',fr.state,'revision_number',fr.revision_number,'finalised_at_utc',fr.finalised_at_utc,
      'manifest_hash',encode(fr.manifest_hash,'hex'),'client_manifest_id',cm.id,'invoice_state',cm.invoice_state) order by fr.revision_number,fr.id)
      from public.weekly_source_final_revisions fr join public.weekly_source_client_manifests cm on cm.final_revision_id=fr.id and cm.client_id=v_client
      where fr.source_cycle_id=c.id),'[]'::jsonb),
    'report_scopes',coalesce((select jsonb_agg(jsonb_build_object('report_scope_id',rs.id,'self_bill_report_id',rs.self_bill_report_id,
      'version',rs.version,'current_complete_upload_id',rs.current_complete_upload_id,'current_projection_publication_id',rs.current_projection_publication_id,
      'current_final_revision_id',rs.current_final_revision_id) order by rs.id) from public.weekly_source_report_scopes rs
      where rs.source_cycle_id=c.id and rs.client_id=v_client),'[]'::jsonb)
  ) into v_facts;
  if v_week>=v_today then return jsonb_build_object('applies',true,'admitted',false,'route',v_route); end if;
  if v_route<>'SIGNED_TIMESHEETS' and jsonb_array_length(v_facts->'expected_contract_weeks')=0
    and jsonb_array_length(v_facts->'accepted_checking_uploads')=0 and jsonb_array_length(v_facts->'completion_history')=0
    and jsonb_array_length(v_facts->'report_scopes')=0 then
    return jsonb_build_object('applies',true,'admitted',false,'route',v_route);
  end if;
  if v_route='SIGNED_TIMESHEETS' and coalesce(p_request->>'command','CONTEXT')='ISSUES' then
    return private.weekly_source_check_only_query_rows_v1(c.id,v_client,jsonb_build_object('actor_user_id',v_actor,
      'source_group_id',g.id,'week_ending',v_week,'cursor',p_request->'cursor','limit',coalesce(p_request->'limit','50'::jsonb)));
  end if;
  -- A proved WAIT is an approved Source decision, never paid=true. Missing or
  -- partial proof stays unknown; it is not quietly reduced to zero waiting.
  if to_regprocedure('private.weekly_source_protected_wait_witness_v1(uuid,uuid)') is null then
    v_wait:=null; v_gate:=v_gate||jsonb_build_array('QUALIFIED_WAIT_READER_UNAVAILABLE');
  else
    for v_event in select e.id from public.weekly_work_events e where e.client_id=v_client
      and e.first_source_group_id=g.id and e.work_date between v_week-6 and v_week order by e.id loop
      begin
        execute 'select private.weekly_source_protected_wait_witness_v1($1,$2)' into v_wait_fact using v_event.id,c.id;
        if v_wait_fact is not null then
          if v_wait_fact->>'state' is distinct from 'QUALIFIED_WAIT' then raise exception 'WAIT'; end if;
          v_wait:=v_wait+1;
        end if;
      exception when sqlstate '55000' then
        v_wait:=null; v_gate:=v_gate||jsonb_build_array(jsonb_build_object('code','QUALIFIED_WAIT_WITNESS_UNAVAILABLE','work_event_id',v_event.id));
      end;
    end loop;
  end if;
  return jsonb_build_object('applies',true,'admitted',true,'contract','WEEKLY_SOURCE_HEALTHROSTER_CHECKLIST_CONTEXT_V1',
    'scope',jsonb_build_object('source_group_id',g.id,'source_cycle_id',c.id,'client_id',v_client,
      'week_ending',v_week,'cycle_week_ending',c.finalisation_week_ending),'route',v_route,
    'permission_view',case when v_admin then 'ADMIN' else 'PAY_READONLY' end,
    'source_cycle_version',c.version,'effective_rule',v_rule,'native_process_facts',v_facts,
    'checking_due_local_date',v_week+(8-extract(isodow from v_week)::integer),
    'checking_due',v_today>=v_week+(8-extract(isodow from v_week)::integer),
    'actual_timesheet_count',v_count,'actual_timesheet_authority_hash',
      encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_CHECKLIST_ACTUAL_SET_V1',v_actual),'hex'),
    'most_recent_ended_timesheet_week',v_latest_timesheet_week,
    'most_recent_ended_client_week',v_latest_week,
    'client_week_authority_fingerprint',v_calendar_authority->>'authority_fingerprint','open_timesheet_read_items',v_open,
    'earlier_open_weeks',v_earlier_open,
    'qualified_waiting_count',v_wait,'engineering_gates',v_gate,
    'pay_financial_evidence_required',true,'root_checklist_union_required',true,
    'read_revision',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_HEALTHROSTER_CHECKLIST_CONTEXT_V1',
      jsonb_build_object('scope',p_request-'cursor'-'limit','cycle_version',c.version,'actual',v_actual,'facts',v_facts,
        'latest_week',v_latest_week,'latest_timesheet_week',v_latest_timesheet_week,
        'client_week_authority_fingerprint',v_calendar_authority->>'authority_fingerprint',
        'earlier_open_weeks',v_earlier_open,'actual_count',v_count,'open_read_items',v_open,
        'wait_count',v_wait,'gates',v_gate)),'hex'));
end;
$function$;
alter function private.weekly_source_healthroster_checklist_leaf_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_healthroster_checklist_leaf_v1(jsonb) from public,anon,authenticated,service_role;



-- CONTACT_PREPARER_UNIT 122 repeatable supabase/repeatable/13102026_1745_weekly_source_owned_stage_self_bill_facts_v1.sql SHA256 eb8b641f489b45af989aa98b69b0e0486f638c98a5032cf8750b0e01422bbd19
-- Exact scoped native own-stage exception; normal four facts retain full predicates.


create or replace function private.weekly_source_bulk_own_stage_event_excluded_v1(
  p_work_event_id uuid,p_source_cycle_id uuid,p_context jsonb
) returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare current_context jsonb; matching integer;
begin
  if p_context is null then return false; end if;
  if p_work_event_id is null or p_source_cycle_id is null
    or not private.weekly_exceptional_json_keys_exact_v1(p_context,array['schema_version','source_cycle_id','actor_user_id',
      'bulk_request_key','selection_sha256','source_cas_sha256','client_ids','exclusions'])
    or not(p_context ?& array['schema_version','source_cycle_id','actor_user_id','bulk_request_key','selection_sha256','source_cas_sha256','client_ids','exclusions'])
    or p_context->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_OWN_STAGE_CONTEXT_V1'
    or p_context->>'source_cycle_id' is distinct from p_source_cycle_id::text
    or jsonb_typeof(p_context->'client_ids') is distinct from 'array'
    or jsonb_typeof(p_context->'exclusions') is distinct from 'array'
    or jsonb_array_length(p_context->'exclusions')=0
    or coalesce(p_context->>'selection_sha256','') !~ '^[0-9a-f]{64}$'
    or coalesce(p_context->>'source_cas_sha256','') !~ '^[0-9a-f]{64}$'
    or nullif(btrim(p_context->>'bulk_request_key'),'') is null
    or not pg_input_is_valid(coalesce(p_context->>'actor_user_id',''),'uuid') then
    raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000'; end if;
  -- Rebuild from actual READY/PENDING_C1 requests, generation/vector/proof,
  -- approval/run/family/WAIT/signed claim and current Source CAS owners.
  -- No supplied exclusion, receipt or field is accepted on its own.
  current_context:=private.weekly_source_bulk_own_stage_context_v1(p_source_cycle_id,
    (p_context->>'actor_user_id')::uuid,p_context->>'bulk_request_key',
    p_context->>'selection_sha256',p_context->>'source_cas_sha256');
  if current_context is null or current_context is distinct from p_context then
    raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000'; end if;
  select count(*) into matching from jsonb_array_elements(current_context->'exclusions') item
    where item->>'work_event_id'=p_work_event_id::text;
  if matching>1 then raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000'; end if;
  return matching=1;
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then
  raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_report_shift_facts_v1(p_work_event_id uuid,p_cycle_or_report uuid,p_own_stage_context jsonb)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare e public.weekly_work_events%rowtype; c public.weekly_source_cycles%rowtype; s public.weekly_source_report_scopes%rowtype;
  v_on boolean:=false; v_bound boolean:=false; v_ready boolean:=false; v_protected boolean:=false; v_wait jsonb;
  v_pay_export_worked boolean:=false; v_own_stage_excluded boolean:=false;
begin
  select * into e from public.weekly_work_events where id=p_work_event_id;
  if not found then raise exception 'WEEKLY_SOURCE_SELF_BILL_EVENT_NOT_FOUND' using errcode='22023'; end if;
  select * into c from public.weekly_source_cycles where id=p_cycle_or_report;
  if not found then
    select * into s from public.weekly_source_report_scopes where id=p_cycle_or_report and self_bill_report_id is not null;
    if not found then raise exception 'WEEKLY_SOURCE_SELF_BILL_SCOPE_NOT_FOUND' using errcode='22023'; end if;
    if s.client_id is distinct from e.client_id then
      raise exception 'WEEKLY_SOURCE_SELF_BILL_SCOPE_MISMATCH' using errcode='22023'; end if;
    select * into strict c from public.weekly_source_cycles where id=s.source_cycle_id;
  end if;
  if e.first_source_group_id is distinct from c.source_group_id
    or (c.scope_client_id is not null and c.scope_client_id is distinct from e.client_id)
    or (s.id is not null and (s.source_group_id is distinct from c.source_group_id
      or not exists(select 1 from public.weekly_source_groups source_group where source_group.id=c.source_group_id
        and source_group.agency_id=s.agency_id and source_group.environment=s.environment))) then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_SCOPE_MISMATCH' using errcode='22023'; end if;
  -- The actual event's client is the F1 helper's first parameter.
  if private.weekly_source_effective_rule_set_v1(e.client_id,c.id)#>>'{values,self_bill_source}' is distinct from 'SEPARATE_FINAL_REPORT' then
    return jsonb_build_object('on_accepted_report',false,'bound_to_finalised_export',false,'invoice_ready',false,'s25_pay_selected',false); end if;
  select coalesce(bool_or(true),false),coalesce(bool_or(b.id is not null and er.row_finalisation_state='SOURCE_WORKED'
      and nullif(btrim(er.finalised_by),'') is not null),false),
    coalesce(bool_or(b.id is not null and er.row_finalisation_state='SOURCE_WORKED' and nullif(btrim(er.finalised_by),'') is not null
      and private.weekly_source_self_bill_report_pay_witness_v1(b.id) is not null),false)
    into v_on,v_bound,v_ready
    from public.weekly_source_report_scopes rs
    join public.weekly_source_projection_publications rp on rp.id=rs.current_projection_publication_id
      and rp.upload_id=rs.current_complete_upload_id and rp.report_scope_id=rs.id and rp.state='CURRENT'
      and rp.authority_scope_kind='SELF_BILL_REPORT_SCOPE' and rp.authority_scope_version=rs.version
    join public.weekly_source_uploads ru on ru.id=rp.upload_id and ru.state='CURRENT'
    join public.weekly_source_upload_rows rr on rr.upload_id=ru.id and rr.row_finalisation_state='SOURCE_REPORT_LINE'
    left join public.weekly_source_self_bill_report_line_bindings b on b.report_row_id=rr.id and b.state='CURRENT'
    left join public.weekly_source_upload_rows er on er.id=b.export_upload_row_id
    where rs.source_group_id=c.source_group_id and rs.client_id=e.client_id
      and (s.id is null or rs.id=s.id) and (b.work_event_id=e.id
        or (e.profile_external_key is not null and rr.external_source_key=e.profile_external_key));
  v_own_stage_excluded:=private.weekly_source_bulk_own_stage_event_excluded_v1(e.id,c.id,p_own_stage_context);
  v_wait:=case when v_own_stage_excluded then null else private.weekly_source_protected_wait_witness_v1(e.id,c.id) end;
  v_protected:=v_wait is not null and v_wait->>'state'='QUALIFIED_WAIT';
  select exists(select 1 from public.weekly_source_projection_publications ep
    join public.weekly_source_uploads eu on eu.id=ep.upload_id and eu.state='CURRENT'
    join public.weekly_source_upload_rows er on er.upload_id=eu.id and er.row_finalisation_state='SOURCE_WORKED'
      and nullif(btrim(er.finalised_by),'') is not null and er.work_date<=c.finalisation_week_ending
    join public.weekly_source_row_resolutions rr on rr.upload_row_id=er.id and rr.mapping_state='RESOLVED'
      and rr.work_event_id=e.id and rr.client_id=e.client_id and rr.generation=coalesce(ep.projection_generation,ep.authority_scope_version)
    where ep.id=c.current_projection_publication_id and ep.upload_id=c.current_complete_upload_id
      and ep.authority_scope_kind='CYCLE' and ep.state='CURRENT') into v_pay_export_worked;
  return jsonb_build_object('on_accepted_report',v_on,'bound_to_finalised_export',v_bound,
    'invoice_ready',v_bound and v_ready,'s25_pay_selected',v_protected or (v_bound and v_pay_export_worked));
end;
$function$;
create or replace function private.weekly_source_report_shift_facts_v1(p_work_event_id uuid,p_cycle_or_report uuid)
returns jsonb language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$ select private.weekly_source_report_shift_facts_v1(p_work_event_id,p_cycle_or_report,null::jsonb); $function$;

create or replace function private.weekly_source_shift_on_self_bill_context_v1(p_work_event_id uuid,p_cycle_or_report uuid,p_own_stage_context jsonb)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare cycle public.weekly_source_cycles%rowtype; scope public.weekly_source_report_scopes%rowtype;
  event public.weekly_work_events%rowtype; rules jsonb;
begin
  if p_own_stage_context is null then return private.weekly_source_shift_on_self_bill_v1(p_work_event_id,p_cycle_or_report); end if;
  select * into strict event from public.weekly_work_events where id=p_work_event_id;
  select * into cycle from public.weekly_source_cycles where id=p_cycle_or_report;
  if cycle.id is null then
    select * into strict scope from public.weekly_source_report_scopes where id=p_cycle_or_report;
    select * into strict cycle from public.weekly_source_cycles where id=scope.source_cycle_id;
    if scope.client_id is distinct from event.client_id or scope.source_group_id is distinct from cycle.source_group_id
      or not exists(select 1 from public.weekly_source_groups g where g.id=cycle.source_group_id
        and g.agency_id=scope.agency_id and g.environment=scope.environment) then
      raise exception 'WEEKLY_SOURCE_SELF_BILL_SCOPE_MISMATCH' using errcode='22023'; end if;
  end if;
  if event.first_source_group_id is distinct from cycle.source_group_id
    or (cycle.scope_client_id is not null and cycle.scope_client_id is distinct from event.client_id) then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_SCOPE_MISMATCH' using errcode='22023'; end if;
  perform private.weekly_source_bulk_own_stage_event_excluded_v1(event.id,cycle.id,p_own_stage_context);
  rules:=private.weekly_source_effective_rule_set_v1(event.client_id,cycle.id)->'values';
  if rules->>'invoice_sender'='CLIENT_SELF_BILL' and rules->>'self_bill_source'='SEPARATE_FINAL_REPORT' then
    if scope.id is not null and scope.self_bill_report_id is null then
      raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_SCOPE_REQUIRED' using errcode='22023'; end if;
    return private.weekly_source_report_shift_facts_v1(event.id,p_cycle_or_report,p_own_stage_context);
  end if;
  return private.weekly_source_shift_on_self_bill_v1(event.id,p_cycle_or_report);
end;
$function$;

alter function private.weekly_source_bulk_own_stage_event_excluded_v1(uuid,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_bulk_own_stage_event_excluded_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;
alter function private.weekly_source_report_shift_facts_v1(uuid,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_report_shift_facts_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;
alter function private.weekly_source_report_shift_facts_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_report_shift_facts_v1(uuid,uuid) from public,anon,authenticated,service_role;
alter function private.weekly_source_shift_on_self_bill_context_v1(uuid,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_shift_on_self_bill_context_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;


-- CONTACT_PREPARER_UNIT 123 repeatable supabase/repeatable/13102026_1755_weekly_source_publication_comparison_family_union_v1.sql SHA256 db2be00b1c2d7a19a80c0a3d75ef034a7f26dd12efa7a8d20daae03abe4a89e3
-- Complete current Report/Protection publication and comparison owner union.


create or replace function private.weekly_source_publication_signed_family_fence_v1(
  p_publication_id uuid,p_before jsonb default null
) returns jsonb language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_publication public.weekly_source_projection_publications%rowtype;
  v_upload public.weekly_source_uploads%rowtype; v_cycle public.weekly_source_cycles%rowtype;
  v_roots uuid[]; v_lock jsonb; v_proof jsonb;
begin
  select * into strict v_publication from public.weekly_source_projection_publications where id=p_publication_id;
  select * into strict v_upload from public.weekly_source_uploads where id=v_publication.upload_id;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_publication.source_cycle_id;
  if v_upload.source_cycle_id is distinct from v_cycle.id then
    raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_CHANGED' using errcode='55000'; end if;
  v_roots:=private.weekly_source_publication_signed_roots_v1(v_publication.id);
  v_proof:=jsonb_build_object('publication_id',v_publication.id,'source_cycle_id',v_cycle.id,
    'source_group_id',v_cycle.source_group_id,'upload_id',v_upload.id,'report_scope_id',v_publication.report_scope_id,
    'authority_scope_kind',v_publication.authority_scope_kind,'authority_scope_version',v_publication.authority_scope_version,
    'projection_generation',v_publication.projection_generation,'correction_session_id',v_publication.correction_session_id,
    'source_format_profile_id',v_upload.source_format_profile_id,'coverage_start',v_upload.confirmed_coverage_start_local_date,
    'coverage_end',v_upload.confirmed_coverage_end_local_date,
    'client_id',private.weekly_source_checking_client_scope_v1(v_publication.id),'signed_root_ids',to_jsonb(v_roots),
    'publication_before',to_jsonb(v_publication),'upload_before',to_jsonb(v_upload),'cycle_before',to_jsonb(v_cycle),
    'group_before',(select to_jsonb(g) from public.weekly_source_groups g where g.id=v_cycle.source_group_id));
  if p_before is not null then
    if p_before is distinct from v_proof then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_SIGNED_ROOT_SET_CHANGED' using errcode='40001'; end if;
    return v_proof;
  end if;
  perform private.weekly_source_pay_query_admit_v2();
  if cardinality(v_roots)>0 then
    v_lock:=private.weekly_source_lock_family_rows_v1(v_roots,null);
    if v_lock->>'ok' is distinct from 'true' then
      raise exception '%',coalesce(v_lock->>'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE') using errcode='55000'; end if;
  end if;
  return v_proof;
end;
$function$;

create or replace function private.weekly_source_candidate_submission_compare_sync_v1(
  p_candidate_generation_id uuid,
  p_projection_publication_id uuid,
  p_membership_id uuid,
  p_timesheet_id uuid,
  p_timesheet_hash bytea,
  p_now_utc timestamptz default pg_catalog.transaction_timestamp()
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_generation public.weekly_candidate_outreach_generations%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_profile_code text;
  v_submission public.weekly_timesheet_submission_requests%rowtype;
  v_membership public.weekly_timesheet_submission_request_memberships%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_contract public.contracts%rowtype;
  v_candidate_row jsonb;
  v_source_json jsonb;
  v_source record;
  v_candidate_start timestamp without time zone;
  v_candidate_end timestamp without time zone;
  v_candidate_break integer;
  v_candidate_shift_hash bytea;
  v_durable_identity_hash bytea;
  v_prior_work_event_id uuid;
  v_work_event public.weekly_work_events%rowtype;
  v_issue jsonb;
  v_issues jsonb:='[]'::jsonb;
  v_used_source_rows uuid[]:='{}'::uuid[];
  v_seen_work_events uuid[]:='{}'::uuid[];
  v_tie_count integer;
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_comparison public.weekly_issue_comparison_revisions%rowtype;
  v_policy jsonb;
  v_episode integer;
  v_revision integer;
  v_fingerprint bytea;
  v_is_new boolean;
  v_issue_family text;
  v_presence text;
  v_new_count integer:=0;
  v_changed_count integer:=0;
  v_unchanged_count integer:=0;
  v_resolved_count integer:=0;
  v_open_count integer:=0;
  v_import_authoritative boolean:=false;
  v_scope_client_id uuid;
  v_source_question_changed boolean:=false;
  v_discovered_cycle_id uuid; v_discovered_group_id uuid; v_discovered_cycle jsonb;
  v_discovered_timesheet public.timesheets%rowtype; v_locked_timesheet public.timesheets%rowtype;
  v_family_lock jsonb; v_publication_i1_context jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_projection_publication_id is null or p_timesheet_id is null
     or p_timesheet_hash is null or pg_catalog.octet_length(p_timesheet_hash)<>32 then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_REQUEST_INVALID' using errcode='22023';
  end if;

  -- Plain scope/physical discovery precedes this owner's first business lock.
  select * into strict v_publication from public.weekly_source_projection_publications
    where id=p_projection_publication_id and state='CURRENT';
  select * into strict v_cycle from public.weekly_source_cycles where id=v_publication.source_cycle_id;
  v_discovered_cycle_id:=v_cycle.id; v_discovered_group_id:=v_cycle.source_group_id; v_discovered_cycle:=to_jsonb(v_cycle);
  select * into strict v_discovered_timesheet from public.timesheets where timesheet_id=p_timesheet_id;
  if nullif(current_setting('cloudtms.weekly_source_publication_i1_context',true),'') is not null then
    v_publication_i1_context:=current_setting('cloudtms.weekly_source_publication_i1_context',true)::jsonb;
    if v_publication_i1_context->>'schema_version' is distinct from 'WEEKLY_SOURCE_PUBLICATION_I1_CONTEXT_V1'
      or v_publication_i1_context->>'publication_id' is distinct from p_projection_publication_id::text
      or jsonb_typeof(v_publication_i1_context->'root_ids') is distinct from 'array'
      or not(v_publication_i1_context->'root_ids' ? p_timesheet_id::text) then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_SIGNED_ROOT_SET_CHANGED' using errcode='40001'; end if;
  end if;
  perform private.weekly_source_pay_query_admit_v2();
  v_family_lock:=private.weekly_source_lock_family_rows_v1(array[p_timesheet_id],null);
  if v_family_lock->>'ok' is distinct from 'true' then
    raise exception '%',coalesce(v_family_lock->>'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE') using errcode='55000'; end if;
  select * into strict v_locked_timesheet from public.timesheets where timesheet_id=p_timesheet_id;
  if to_jsonb(v_locked_timesheet) is distinct from to_jsonb(v_discovered_timesheet) then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_TIMESHEET_STALE' using errcode='40001'; end if;
  perform 1 from public.weekly_source_groups where id=v_discovered_group_id for update;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_discovered_cycle_id for update;
  if to_jsonb(v_cycle) is distinct from v_discovered_cycle or v_cycle.source_group_id is distinct from v_discovered_group_id then
    raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_CHANGED' using errcode='40001'; end if;
  if p_candidate_generation_id is null then
    -- A newly published checking source must recompare already-signed weekly
    -- evidence even when no submission request was needed or remains active.
    if p_membership_id is not null then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_REQUEST_INVALID' using errcode='22023';
    end if;
    select * into strict v_publication
    from public.weekly_source_projection_publications
    where id=p_projection_publication_id and state='CURRENT';
    select * into strict v_cycle from public.weekly_source_cycles
    where id=v_publication.source_cycle_id for update;
    select * into strict v_timesheet from public.timesheets
    where timesheet_id=p_timesheet_id and is_current
      and revoked_at is null and archived_at_utc is null
      and sheet_scope='WEEKLY' and line_type='HOURS'
      and authorised_at_server is null
      and r2_nurse_key is not null and img_sha256_nurse is not null
    for update;
    select * into strict v_contract from public.contracts
    where id=v_timesheet.contract_id;
    v_generation.candidate_id:=v_contract.candidate_id;
    v_membership.contract_id:=v_contract.id;
    v_membership.client_id:=v_contract.client_id;
    v_membership.week_ending:=v_timesheet.week_ending_date;
  else
    if p_membership_id is null then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_REQUEST_INVALID' using errcode='22023';
    end if;
    select * into strict v_generation
    from public.weekly_candidate_outreach_generations
    where id=p_candidate_generation_id and request_kind='SUBMIT_TIMESHEET'
      and state='ACTIVE'
    for update;
    if v_generation.source_cycle_id is distinct from v_discovered_cycle_id then
      raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_CHANGED' using errcode='40001'; end if;
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_generation.source_cycle_id
    for update;
  end if;
  perform private.weekly_source_query_current_publication_v1(
    v_cycle.id,p_projection_publication_id
  );
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  select * into strict v_publication
  from public.weekly_source_projection_publications
  where id=p_projection_publication_id
    and source_cycle_id=v_cycle.id and state='CURRENT';
  select * into strict v_upload from public.weekly_source_uploads
  where id=v_publication.upload_id and source_cycle_id=v_cycle.id;
  select profile.profile_code into strict v_profile_code
  from public.weekly_source_format_profiles profile
  where profile.id=v_upload.source_format_profile_id;
  if v_profile_code='NHSP_PREFINAL_RELEASED_V1'
     and (v_upload.confirmed_coverage_start_local_date is null
       or v_upload.confirmed_coverage_end_local_date is null) then
    raise exception 'WEEKLY_SOURCE_PREFINAL_COVERAGE_INVALID' using errcode='55000';
  end if;
  if p_candidate_generation_id is not null then
    select * into strict v_submission
    from public.weekly_timesheet_submission_requests
    where candidate_cohort_id=v_generation.candidate_cohort_id
      and candidate_id=v_generation.candidate_id
      and source_cycle_id=v_cycle.id
      and current_projection_publication_id=v_publication.id
      and state in ('ACTIVE','OVERDUE','PARTLY_SUBMITTED')
    for update;
    select * into strict v_membership
    from public.weekly_timesheet_submission_request_memberships
    where id=p_membership_id and submission_request_id=v_submission.id
      and state='WAITING'
    for update;
    select * into strict v_contract from public.contracts
    where id=v_membership.contract_id
      and candidate_id=v_generation.candidate_id
      and client_id=v_membership.client_id;
    select * into strict v_timesheet from public.timesheets
    where timesheet_id=p_timesheet_id and contract_id=v_membership.contract_id
      and week_ending_date=v_membership.week_ending
      and is_current and revoked_at is null and archived_at_utc is null
      and sheet_scope='WEEKLY' and line_type='HOURS'
      and authorised_at_server is null
      and r2_nurse_key is not null and img_sha256_nurse is not null
    for update;
  end if;
  v_scope_client_id:=private.weekly_source_checking_client_scope_v1(v_publication.id);
  if v_scope_client_id is not null and v_scope_client_id is distinct from v_contract.client_id then
    raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_INVALID' using errcode='55000';
  end if;
  if v_timesheet.version<1
     or private.weekly_source_query_candidate_timesheet_hash_v1(v_timesheet.timesheet_id)
          is distinct from p_timesheet_hash then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_TIMESHEET_STALE' using errcode='40001';
  end if;
  v_import_authoritative:=private.weekly_source_is_import_authoritative_v1(
    v_contract.client_id,v_contract.id,v_membership.week_ending);
  if v_import_authoritative and (v_upload.confirmed_coverage_start_local_date is null
    or v_upload.confirmed_coverage_end_local_date is null) then
    raise exception 'WEEKLY_SOURCE_PREFINAL_COVERAGE_INVALID' using errcode='55000'; end if;
  v_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_membership.week_ending
  );
  if v_policy->>'source_group_id' is distinct from v_group.id::text
     or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or v_policy->>'document_mode'<>'CHECK_ONLY' then
    raise exception 'WEEKLY_SOURCE_SECURE_QUERY_NOT_APPLICABLE' using errcode='55000';
  end if;
  if exists(
    select 1
    from private.weekly_source_candidate_current_rows_v1(
      v_publication.id,v_generation.candidate_id,v_membership.client_id,
      v_membership.contract_id,v_membership.week_ending
    ) source_row
    where source_row.row_finalisation_state in (
      'BLOCK_FINALISATION_DISAGREEMENT','BLOCK_ACTUAL_TUPLE'
    )
  ) then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_SOURCE_SCOPE_BLOCKED' using errcode='55000';
  end if;

  for v_candidate_row in
    select value
    from pg_catalog.jsonb_array_elements(
      private.weekly_source_candidate_app_schedule_v1(
        v_timesheet.actual_schedule_json,v_timesheet.additional_units_per_day
      )
    ) candidate_row
    where (v_profile_code<>'NHSP_PREFINAL_RELEASED_V1' and not v_import_authoritative)
      or (candidate_row.value->>'date')::date between
        v_upload.confirmed_coverage_start_local_date
        and v_upload.confirmed_coverage_end_local_date
    order by value->>'date',value->>'start',value->>'end',
      coalesce(value->>'row_key','') collate "C"
  loop
    v_candidate_start:=(v_candidate_row->>'date')::date+
      (v_candidate_row->>'start')::time;
    v_candidate_end:=(v_candidate_row->>'date')::date+
      (v_candidate_row->>'end')::time;
    if v_candidate_end<=v_candidate_start then
      v_candidate_end:=v_candidate_end+interval '1 day';
    end if;
    v_candidate_break:=coalesce(
      nullif(v_candidate_row#>>'{break_entry,break_minutes}','')::integer,
      nullif(v_candidate_row#>>'{break_entry,calculated_break_minutes}','')::integer,0
    );
    v_candidate_shift_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_CANDIDATE_SHIFT_V1',
      pg_catalog.jsonb_build_object(
        'timesheet_id',v_timesheet.timesheet_id,'timesheet_revision',v_timesheet.version,
        'row_key',v_candidate_row->>'row_key','work_date',v_candidate_row->>'date',
        'start_at_local',v_candidate_start,'end_at_local',v_candidate_end,
        'break_minutes',v_candidate_break,
        'additional_units',coalesce(v_candidate_row->'additional_units','[]'::jsonb)
      )
    );

    select pg_catalog.jsonb_build_object(
      'source_row_id',source_row.source_row_id,'source_link_id',source_row.source_link_id,
      'source_link_kind',(select link.link_kind
        from public.weekly_work_event_source_links link
        where link.id=source_row.source_link_id),
      'work_event_id',source_row.work_event_id,'work_date',source_row.work_date,
      'start_at_local',source_row.start_at_local,'end_at_local',source_row.end_at_local,
      'break_minutes',source_row.break_minutes,
      'row_finalisation_state',source_row.row_finalisation_state
    ) into v_source_json
    from private.weekly_source_candidate_current_rows_v1(
      v_publication.id,v_generation.candidate_id,v_membership.client_id,
      v_membership.contract_id,v_membership.week_ending
    ) source_row
    where not (source_row.source_row_id=any(v_used_source_rows))
      and source_row.row_finalisation_state in (
        'NOT_APPLICABLE','SOURCE_WORKED','SOURCE_UNFINALISED'
      )
      and (select link.link_kind from public.weekly_work_event_source_links link
           where link.id=source_row.source_link_id)
            not in ('FULL_NEGATIVE_SOURCE','ZERO_SOURCE')
      and source_row.work_date=(v_candidate_row->>'date')::date
      and source_row.start_at_local=v_candidate_start
      and source_row.end_at_local=v_candidate_end
      and coalesce(source_row.break_minutes,0)=v_candidate_break
    order by source_row.source_row_id limit 1;

    if v_source_json is null then
      with possible as (
        select source_row.*,
          (select link.link_kind from public.weekly_work_event_source_links link
           where link.id=source_row.source_link_id) as source_link_kind,
          case
            when source_row.start_at_local is null or source_row.end_at_local is null
              then 1000000000::numeric
            else
              pg_catalog.abs(pg_catalog.date_part('epoch',
                source_row.start_at_local-v_candidate_start)/60)
              +pg_catalog.abs(pg_catalog.date_part('epoch',
                source_row.end_at_local-v_candidate_end)/60)
              +pg_catalog.abs(coalesce(source_row.break_minutes,0)-v_candidate_break)
          end as distance
        from private.weekly_source_candidate_current_rows_v1(
          v_publication.id,v_generation.candidate_id,v_membership.client_id,
          v_membership.contract_id,v_membership.week_ending
        ) source_row
        where not (source_row.source_row_id=any(v_used_source_rows))
          and source_row.work_date=(v_candidate_row->>'date')::date
          and source_row.row_finalisation_state in (
            'NOT_APPLICABLE','SOURCE_WORKED','SOURCE_ABSENT_ZERO','SOURCE_UNFINALISED'
          )
      ),minimum as (select pg_catalog.min(distance) distance from possible)
      select pg_catalog.count(*)::integer into v_tie_count
      from possible,minimum where possible.distance=minimum.distance;
      if v_tie_count>1 then
        raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_AMBIGUOUS' using errcode='55000';
      elsif v_tie_count=1 then
        with possible as (
          select source_row.*,
            (select link.link_kind from public.weekly_work_event_source_links link
             where link.id=source_row.source_link_id) as source_link_kind,
            case
              when source_row.start_at_local is null or source_row.end_at_local is null
                then 1000000000::numeric
              else
                pg_catalog.abs(pg_catalog.date_part('epoch',
                  source_row.start_at_local-v_candidate_start)/60)
                +pg_catalog.abs(pg_catalog.date_part('epoch',
                  source_row.end_at_local-v_candidate_end)/60)
                +pg_catalog.abs(coalesce(source_row.break_minutes,0)-v_candidate_break)
            end as distance
          from private.weekly_source_candidate_current_rows_v1(
            v_publication.id,v_generation.candidate_id,v_membership.client_id,
            v_membership.contract_id,v_membership.week_ending
          ) source_row
          where not (source_row.source_row_id=any(v_used_source_rows))
            and source_row.work_date=(v_candidate_row->>'date')::date
            and source_row.row_finalisation_state in (
              'NOT_APPLICABLE','SOURCE_WORKED','SOURCE_ABSENT_ZERO','SOURCE_UNFINALISED'
            )
        )
        select pg_catalog.jsonb_build_object(
          'source_row_id',source_row_id,'source_link_id',source_link_id,
          'source_link_kind',source_link_kind,
          'work_event_id',work_event_id,'work_date',work_date,
          'start_at_local',start_at_local,'end_at_local',end_at_local,
          'break_minutes',break_minutes,'row_finalisation_state',row_finalisation_state
        ) into v_source_json
        from possible order by distance,source_row_id limit 1;
      end if;
    end if;

    if v_source_json is null then
      -- A replacement NHSP file may omit a previously linked shift. Reuse
      -- that durable event instead of inventing a new issue/notification clock.
      v_prior_work_event_id:=null;
      if p_candidate_generation_id is null then
        with prior_events as (
          select link.work_event_id,
            pg_catalog.min(
              pg_catalog.abs(pg_catalog.date_part('epoch',
                source_row.start_at_local-v_candidate_start)/60)
              +pg_catalog.abs(pg_catalog.date_part('epoch',
                source_row.end_at_local-v_candidate_end)/60)
              +pg_catalog.abs(coalesce(source_row.break_minutes,0)-v_candidate_break)
            ) as distance
          from public.weekly_source_uploads historical_upload
          join public.weekly_source_upload_rows source_row
            on source_row.upload_id=historical_upload.id
          join public.weekly_source_row_resolutions resolution
            on resolution.upload_row_id=source_row.id
           and resolution.mapping_state='RESOLVED'
          join public.weekly_work_event_source_links link
            on link.upload_row_id=source_row.id
           and link.row_resolution_id=resolution.id
           and link.work_event_id=resolution.work_event_id
          join public.weekly_work_events work_event
            on work_event.id=link.work_event_id
          where historical_upload.source_cycle_id=v_cycle.id
            and historical_upload.id<>v_upload.id
            -- A provisional check must not choose a final backing-report
            -- event as the identity of a missing provisional shift.
            and historical_upload.source_format_profile_id=v_upload.source_format_profile_id
            and source_row.work_date=(v_candidate_row->>'date')::date
            and source_row.start_at_local is not null
            and source_row.end_at_local is not null
            and resolution.candidate_id=v_generation.candidate_id
            and resolution.client_id=v_membership.client_id
            and resolution.contract_id=v_membership.contract_id
            and work_event.first_source_group_id=v_group.id
          group by link.work_event_id
        ), nearest as (
          select work_event_id,distance,
            pg_catalog.count(*) over (partition by distance) as tie_count
          from prior_events
        )
        select work_event_id,tie_count
        into v_prior_work_event_id,v_tie_count
        from nearest order by distance,work_event_id limit 1;
        if v_tie_count>1 then
          raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_AMBIGUOUS' using errcode='55000';
        end if;
      end if;
      if v_prior_work_event_id is null then
        v_durable_identity_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_WORK_EVENT_SCHEDULE_TUPLE_V1',
        pg_catalog.jsonb_build_object(
          'source_group_id',v_group.id,
          'source_format_profile_id',v_upload.source_format_profile_id,
          'candidate_id',v_generation.candidate_id,
          'client_id',v_membership.client_id,
          'work_date',(v_candidate_row->>'date')::date,
          'start_at_local',v_candidate_start,'end_at_local',v_candidate_end
        )
      );
        insert into public.weekly_work_events(
        candidate_id,client_id,work_date,identity_kind,profile_external_key,
        durable_identity_hash,first_source_group_id,source_format_profile_id
      ) values (
        v_generation.candidate_id,v_membership.client_id,
        (v_candidate_row->>'date')::date,'SCHEDULE_TUPLE',null,
        v_durable_identity_hash,v_group.id,v_upload.source_format_profile_id
      ) on conflict (durable_identity_hash) do nothing;
        select * into strict v_work_event from public.weekly_work_events
        where durable_identity_hash=v_durable_identity_hash;
        if v_work_event.candidate_id is distinct from v_generation.candidate_id
           or v_work_event.client_id is distinct from v_membership.client_id
           or v_work_event.work_date is distinct from (v_candidate_row->>'date')::date
           or v_work_event.first_source_group_id is distinct from v_group.id then
          raise exception 'WEEKLY_SOURCE_WORK_EVENT_IDENTITY_COLLISION' using errcode='55000';
        end if;
      else
        select * into strict v_work_event from public.weekly_work_events
        where id=v_prior_work_event_id;
      end if;
      v_issue:=pg_catalog.jsonb_build_object(
        'work_event_id',v_work_event.id,
        'candidate_timesheet_id',v_timesheet.timesheet_id,
        'candidate_timesheet_revision',v_timesheet.version,
        'candidate_shift_fingerprint',pg_catalog.encode(v_candidate_shift_hash,'hex'),
        'source_row_id',null,'source_work_event_link_id',null,
        'contract_id',v_membership.contract_id,
        'issue_family','SOURCE_MISSING_OR_NOT_AUTHORISED','source_presence','ABSENT',
        'candidate_start_at_local',v_candidate_start,
        'candidate_end_at_local',v_candidate_end,
        'candidate_break_minutes',v_candidate_break,
        'system_start_at_local',null,'system_end_at_local',null,
        'system_break_minutes',null
      );
      v_issues:=v_issues||pg_catalog.jsonb_build_array(v_issue);
    else
      v_used_source_rows:=pg_catalog.array_append(
        v_used_source_rows,(v_source_json->>'source_row_id')::uuid
      );
      if v_source_json->>'source_link_kind' in ('FULL_NEGATIVE_SOURCE','ZERO_SOURCE')
         or v_source_json->>'row_finalisation_state'='SOURCE_ABSENT_ZERO' then
        v_issue_family:='SOURCE_MISSING_OR_NOT_AUTHORISED';
        v_presence:='ABSENT';
      elsif v_source_json->>'row_finalisation_state'='SOURCE_UNFINALISED' then
        v_issue_family:='HEALTHROSTER_NOT_FINALISED';
        v_presence:='UNFINALISED';
      elsif nullif(v_source_json->>'start_at_local','')::timestamp=v_candidate_start
         and nullif(v_source_json->>'end_at_local','')::timestamp=v_candidate_end
         and coalesce(nullif(v_source_json->>'break_minutes','')::integer,0)=v_candidate_break then
        v_issue_family:=null;
        v_presence:='PRESENT';
      else
        v_issue_family:='SOURCE_HOURS_DIFFER';
        v_presence:='PRESENT';
      end if;
      if v_issue_family is not null then
        v_issue:=pg_catalog.jsonb_build_object(
          'work_event_id',(v_source_json->>'work_event_id')::uuid,
          'candidate_timesheet_id',v_timesheet.timesheet_id,
          'candidate_timesheet_revision',v_timesheet.version,
          'candidate_shift_fingerprint',pg_catalog.encode(v_candidate_shift_hash,'hex'),
          'source_row_id',(v_source_json->>'source_row_id')::uuid,
          'source_work_event_link_id',(v_source_json->>'source_link_id')::uuid,
          'contract_id',v_membership.contract_id,
          'issue_family',v_issue_family,'source_presence',v_presence,
          'candidate_start_at_local',v_candidate_start,
          'candidate_end_at_local',v_candidate_end,
          'candidate_break_minutes',v_candidate_break,
          'system_start_at_local',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
            then nullif(v_source_json->>'start_at_local','')::timestamp end,
          'system_end_at_local',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
            then nullif(v_source_json->>'end_at_local','')::timestamp end,
          'system_break_minutes',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
            then nullif(v_source_json->>'break_minutes','')::integer end
        );
        v_issues:=v_issues||pg_catalog.jsonb_build_array(v_issue);
      end if;
    end if;
  end loop;

  for v_source in
    select *
    from private.weekly_source_candidate_current_rows_v1(
      v_publication.id,v_generation.candidate_id,v_membership.client_id,
      v_membership.contract_id,v_membership.week_ending
    ) source_row
    where not (source_row.source_row_id=any(v_used_source_rows))
      and source_row.row_finalisation_state<>'SOURCE_ABSENT_ZERO'
      and (not v_import_authoritative or source_row.work_date between
        v_upload.confirmed_coverage_start_local_date and v_upload.confirmed_coverage_end_local_date)
      and (select link.link_kind from public.weekly_work_event_source_links link
           where link.id=source_row.source_link_id)
            not in ('FULL_NEGATIVE_SOURCE','ZERO_SOURCE')
    order by source_row.work_date,source_row.start_at_local,
      source_row.end_at_local,source_row.source_row_id
  loop
    v_candidate_shift_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_CANDIDATE_SHIFT_V1',
      pg_catalog.jsonb_build_object(
        'timesheet_id',v_timesheet.timesheet_id,
        'timesheet_revision',v_timesheet.version,
        'work_event_id',v_source.work_event_id,'worked',false
      )
    );
    if v_source.row_finalisation_state='SOURCE_UNFINALISED' then
      if v_import_authoritative and not exists(select 1 from public.contract_weeks expected
        where expected.contract_id=v_contract.id and expected.additional_seq=0
          and not coalesce(expected.is_adjustment,false) and expected.status<>'CANCELLED'
          and v_source.work_date between expected.week_ending_date-6 and expected.week_ending_date) then continue; end if;
      v_issue_family:='HEALTHROSTER_NOT_FINALISED';
      v_presence:='UNFINALISED';
    elsif v_source.row_finalisation_state in ('NOT_APPLICABLE','SOURCE_WORKED') then
      v_issue_family:='SOURCE_HOURS_DIFFER';
      v_presence:='PRESENT';
    else
      raise exception 'WEEKLY_SOURCE_CANDIDATE_SOURCE_SCOPE_BLOCKED' using errcode='55000';
    end if;
    v_issue:=pg_catalog.jsonb_build_object(
      'work_event_id',v_source.work_event_id,
      'candidate_timesheet_id',v_timesheet.timesheet_id,
      'candidate_timesheet_revision',v_timesheet.version,
      'candidate_shift_fingerprint',pg_catalog.encode(v_candidate_shift_hash,'hex'),
      'source_row_id',v_source.source_row_id,
      'source_work_event_link_id',v_source.source_link_id,
      'contract_id',v_membership.contract_id,
      'issue_family',v_issue_family,'source_presence',v_presence,
      'candidate_start_at_local',null,'candidate_end_at_local',null,
      'candidate_break_minutes',null,
      'system_start_at_local',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
        then v_source.start_at_local end,
      'system_end_at_local',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
        then v_source.end_at_local end,
      'system_break_minutes',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
        then v_source.break_minutes end
    );
    v_issues:=v_issues||pg_catalog.jsonb_build_array(v_issue);
  end loop;

  for v_issue in
    select value from pg_catalog.jsonb_array_elements(v_issues)
    order by value->>'work_event_id'
  loop
    select * into strict v_work_event from public.weekly_work_events
    where id=(v_issue->>'work_event_id')::uuid
      and candidate_id=v_generation.candidate_id
      and client_id=v_membership.client_id
      and first_source_group_id=v_group.id;
    if v_work_event.id=any(v_seen_work_events) then
      raise exception 'WEEKLY_SOURCE_QUERY_DUPLICATE_WORK_EVENT' using errcode='22023';
    end if;
    v_seen_work_events:=pg_catalog.array_append(v_seen_work_events,v_work_event.id);
    v_issue_family:=v_issue->>'issue_family';
    v_presence:=v_issue->>'source_presence';
    v_policy:=private._weekly_source_effective_policy_v1(
      v_membership.client_id,v_membership.contract_id,v_work_event.work_date
    );
    if v_policy->>'source_group_id' is distinct from v_group.id::text
       or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
       or v_policy->>'document_mode'<>'CHECK_ONLY' then
      raise exception 'WEEKLY_SOURCE_SECURE_QUERY_NOT_APPLICABLE' using errcode='55000';
    end if;

    perform 1 from public.weekly_work_events where id=v_work_event.id for update;
    if private.weekly_source_query_resolved_decision_matches_v1(v_group.id,v_work_event.id,v_issue) then
      v_unchanged_count:=v_unchanged_count+1;
      continue;
    end if;
    select * into v_incident
    from public.weekly_discrepancy_incidents
    where source_group_id=v_group.id and work_event_id=v_work_event.id
      and state='OPEN'
    for update;
    v_is_new:=not found;
    if v_is_new then
      select coalesce(pg_catalog.max(episode_number),0)+1 into v_episode
      from public.weekly_discrepancy_incidents
      where source_group_id=v_group.id and work_event_id=v_work_event.id;
      insert into public.weekly_discrepancy_incidents(
        source_group_id,work_event_id,episode_number,candidate_id,client_id,
        source_cycle_id,state,reconciliation_state,candidate_action_state,
        manager_potential_state,manager_action_state,waiting_source_state
      ) values (
        v_group.id,v_work_event.id,v_episode,v_generation.candidate_id,
        v_membership.client_id,v_cycle.id,'OPEN','UNRESOLVED',
        case when v_issue_family='HEALTHROSTER_NOT_FINALISED' and v_import_authoritative then 'NOT_REQUIRED'
          when p_candidate_generation_id is null
          and coalesce((v_policy->>'candidate_queries_enabled')::boolean,false)
          then 'NOT_ASKED' else 'NOT_REQUIRED' end,
        case when coalesce((v_policy->>'manager_queries_enabled')::boolean,false)
                   and nullif(v_policy->>'manager_query_recipient','') is not null
          then 'AVAILABLE' else 'NOT_AVAILABLE' end,
        case when coalesce((v_policy->>'manager_queries_enabled')::boolean,false)
                   and nullif(v_policy->>'manager_query_recipient','') is not null
          then 'NOT_SENT' else 'NOT_REQUIRED' end,
        'NOT_WAITING'
      ) returning * into v_incident;
      v_comparison.id:=null;
      v_new_count:=v_new_count+1;
    else
      if v_incident.candidate_id is distinct from v_generation.candidate_id
         or v_incident.client_id is distinct from v_membership.client_id
         or v_incident.source_cycle_id is distinct from v_cycle.id
         or v_incident.current_comparison_revision_id is null then
        raise exception 'WEEKLY_SOURCE_CANDIDATE_INCIDENT_SCOPE_CONFLICT' using errcode='55000';
      end if;
      select * into strict v_comparison from public.weekly_issue_comparison_revisions
      where id=v_incident.current_comparison_revision_id;
      if v_comparison.contract_id is distinct from v_membership.contract_id then
        raise exception 'WEEKLY_SOURCE_CANDIDATE_INCIDENT_SCOPE_CONFLICT' using errcode='55000';
      end if;
      v_episode:=v_incident.episode_number;
    end if;

    v_source_question_changed:=v_import_authoritative and v_comparison.id is not null
      and (v_comparison.issue_family,v_comparison.source_presence,v_comparison.system_start_at_local,
        v_comparison.system_end_at_local,v_comparison.system_break_minutes)
      is distinct from (v_issue_family,v_presence,nullif(v_issue->>'system_start_at_local','')::timestamp,
        nullif(v_issue->>'system_end_at_local','')::timestamp,nullif(v_issue->>'system_break_minutes','')::integer);
    v_fingerprint:=private.weekly_source_query_comparison_fingerprint_v1(
      v_incident.id,v_episode,v_work_event.id,v_issue
    );
    if not v_is_new and v_comparison.material_comparison_fingerprint<>v_fingerprint then
      -- A re-signed candidate week changes the current comparison but not the
      -- identity or outreach clock of an already-open work-event incident.
      v_changed_count:=v_changed_count+1;
    end if;
    if v_comparison.id is not null
       and v_comparison.material_comparison_fingerprint=v_fingerprint then
      v_unchanged_count:=v_unchanged_count+1;
    else
      select coalesce(pg_catalog.max(revision_number),0)+1 into v_revision
      from public.weekly_issue_comparison_revisions
      where incident_id=v_incident.id;
      insert into public.weekly_issue_comparison_revisions(
        incident_id,revision_number,projection_publication_id,comparison_upload_id,
        final_revision_id,candidate_timesheet_id,candidate_timesheet_revision,
        candidate_shift_fingerprint,source_row_id,source_work_event_link_id,
        contract_id,issue_family,source_presence,candidate_start_at_local,
        candidate_end_at_local,candidate_break_minutes,system_start_at_local,
        system_end_at_local,system_break_minutes,material_comparison_fingerprint
      ) values (
        v_incident.id,v_revision,v_publication.id,v_upload.id,null,
        v_timesheet.timesheet_id,v_timesheet.version,
        private.weekly_source_query_hex32_v1(
          v_issue->>'candidate_shift_fingerprint',
          'WEEKLY_SOURCE_CANDIDATE_SHIFT_HASH_INVALID'
        ),nullif(v_issue->>'source_row_id','')::uuid,
        nullif(v_issue->>'source_work_event_link_id','')::uuid,
        v_membership.contract_id,v_issue_family,v_presence,
        nullif(v_issue->>'candidate_start_at_local','')::timestamp,
        nullif(v_issue->>'candidate_end_at_local','')::timestamp,
        nullif(v_issue->>'candidate_break_minutes','')::integer,
        nullif(v_issue->>'system_start_at_local','')::timestamp,
        nullif(v_issue->>'system_end_at_local','')::timestamp,
        nullif(v_issue->>'system_break_minutes','')::integer,v_fingerprint
      ) returning * into v_comparison;
      update public.weekly_discrepancy_incidents
      set current_comparison_revision_id=v_comparison.id,
        candidate_action_state=case when v_issue_family='HEALTHROSTER_NOT_FINALISED' and v_import_authoritative
          then 'NOT_REQUIRED' else candidate_action_state end,
        manager_action_state=case when v_source_question_changed and manager_potential_state='AVAILABLE'
          then 'NOT_SENT' else manager_action_state end,
        waiting_source_state=case when v_source_question_changed then 'NOT_WAITING' else waiting_source_state end,
        reconciliation_state=case when v_source_question_changed then 'UNRESOLVED' else reconciliation_state end
      where id=v_incident.id;
      insert into public.weekly_discrepancy_events(
        incident_id,issue_episode,projection_publication_id,
        expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,
        idempotency_key
      ) values (
        v_incident.id,v_incident.episode_number,v_publication.id,v_fingerprint,
        'SOURCE_RECHECKED','SYSTEM',
        pg_catalog.jsonb_build_object(
          'issue_family',v_issue_family,'source_presence',v_presence,
          'comparison_revision_id',v_comparison.id,
          'origin','CANDIDATE_TIMESHEET_SUBMISSION'
        ),
        'SOURCE_RECHECKED:'||v_incident.id::text||':'||pg_catalog.encode(v_fingerprint,'hex')
      ) on conflict (event_kind,idempotency_key) do nothing;
    end if;
  end loop;

  for v_incident in
    select incident.*
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    where incident.source_group_id=v_group.id
      and incident.source_cycle_id=v_cycle.id
      and incident.candidate_id=v_generation.candidate_id
      and incident.client_id=v_membership.client_id
      and comparison.contract_id=v_membership.contract_id
      and work_event.work_date between v_membership.week_ending-6 and v_membership.week_ending
      and ((v_profile_code<>'NHSP_PREFINAL_RELEASED_V1' and not v_import_authoritative)
        or work_event.work_date between v_upload.confirmed_coverage_start_local_date
          and v_upload.confirmed_coverage_end_local_date)
      and incident.state='OPEN'
      and not (incident.work_event_id=any(v_seen_work_events))
    order by incident.id for update of incident
  loop
    update public.weekly_discrepancy_incidents
    set state='RESOLVED',reconciliation_state='RECONCILED',
      candidate_action_state='NOT_REQUIRED',manager_potential_state='NOT_REQUIRED',
      manager_action_state='NOT_REQUIRED',waiting_source_state='SOURCE_MATCHED',
      resolved_at_utc=p_now_utc,resolution_kind='SOURCE_MATCHED'
    where id=v_incident.id;
    update public.weekly_candidate_outreach_memberships set state='RESOLVED'
    where incident_id=v_incident.id and state in ('ACTIONABLE','ANSWERED');
    update public.weekly_manager_review_items set response_state='FILTERED_RESOLVED'
    where incident_id=v_incident.id and response_state='UNANSWERED';
    update public.office_action_notifications
    set operational_state='RESOLVED',resolved_at_utc=p_now_utc
    where issue_id=v_incident.id and operational_state='OPEN';
    insert into public.weekly_discrepancy_events(
      incident_id,issue_episode,projection_publication_id,
      expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,
      idempotency_key
    ) values (
      v_incident.id,v_incident.episode_number,v_publication.id,null,
      'RESOLVED','SYSTEM',
      pg_catalog.jsonb_build_object(
        'resolution','SOURCE_MATCHED','origin','CANDIDATE_TIMESHEET_SUBMISSION'
      ),
      'SOURCE_MATCHED:'||v_incident.id::text||':'||v_publication.id::text
    ) on conflict (event_kind,idempotency_key) do nothing;
    v_resolved_count:=v_resolved_count+1;
  end loop;

  select pg_catalog.count(*)::integer into v_open_count
  from public.weekly_discrepancy_incidents incident
  join public.weekly_issue_comparison_revisions comparison
    on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work_event on work_event.id=incident.work_event_id
  where incident.source_cycle_id=v_cycle.id
    and incident.candidate_id=v_generation.candidate_id
    and incident.client_id=v_membership.client_id
    and comparison.contract_id=v_membership.contract_id
    and work_event.work_date between v_membership.week_ending-6 and v_membership.week_ending
    and incident.state='OPEN';

  return pg_catalog.jsonb_build_object(
    'ok',true,'outcome',case when v_open_count=0 then 'MATCHED' else 'ISSUES' end,
    'open_issue_count',v_open_count,'new_incidents',v_new_count,
    'changed_comparisons',v_changed_count,'unchanged_incidents',v_unchanged_count,
    'resolved_incidents',v_resolved_count
  );
exception when no_data_found or too_many_rows then
  raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_STALE' using errcode='40001';
end;
$function$;

create or replace function private.weekly_source_candidate_prefinal_publish_recheck_v1(
  p_actor_user_id uuid,
  p_projection_publication_id uuid
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_publication public.weekly_source_projection_publications%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_profile_code text;
  v_profile_id uuid;
  v_upload public.weekly_source_uploads%rowtype;
  v_signed record;
  v_result jsonb;
  v_checked integer:=0;
  v_new integer:=0;
  v_changed integer:=0;
  v_resolved integer:=0;
  v_restart_keys text[]:='{}'::text[];
  v_restart_key text;
  v_not_compared integer:=0; v_refusal text; v_unsigned jsonb;
  v_publication_i1_context jsonb; v_locked_root_ids uuid[]; v_observed_root_ids uuid[];
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict v_publication
  from public.weekly_source_projection_publications
  where id=p_projection_publication_id and state='CURRENT';
  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_publication.source_cycle_id;
  select profile.profile_code,profile.id into strict v_profile_code,v_profile_id
  from public.weekly_source_uploads upload
  join public.weekly_source_format_profiles profile
    on profile.id=upload.source_format_profile_id
  where upload.id=v_publication.upload_id;
  if (v_profile_code<>'NHSP_PREFINAL_RELEASED_V1' and not exists(select 1 from public.weekly_source_groups g
       where g.id=v_cycle.source_group_id and g.source_family='ROSTER'))
     or v_publication.authority_scope_kind<>'CYCLE'
     or v_cycle.current_projection_publication_id is distinct from v_publication.id then
    raise exception 'WEEKLY_SOURCE_PREFINAL_RECHECK_SCOPE_INVALID' using errcode='55000';
  end if;
  select * into strict v_upload from public.weekly_source_uploads
  where id=v_publication.upload_id and source_cycle_id=v_cycle.id;
  if v_upload.confirmed_coverage_start_local_date is null
     or v_upload.confirmed_coverage_end_local_date is null then
    raise exception 'WEEKLY_SOURCE_PREFINAL_COVERAGE_INVALID' using errcode='55000';
  end if;
  perform private.weekly_source_office_authority_v1(
    p_actor_user_id,'RECHECK_SOURCE',v_cycle.source_group_id,null,
    v_cycle.finalisation_week_ending
  );

  if nullif(current_setting('cloudtms.weekly_source_publication_i1_context',true),'') is not null then
    v_publication_i1_context:=current_setting('cloudtms.weekly_source_publication_i1_context',true)::jsonb;
    if v_publication_i1_context->>'schema_version' is distinct from 'WEEKLY_SOURCE_PUBLICATION_I1_CONTEXT_V1'
      or v_publication_i1_context->>'publication_id' is distinct from v_publication.id::text
      or jsonb_typeof(v_publication_i1_context->'root_ids') is distinct from 'array' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_SIGNED_ROOT_SET_CHANGED' using errcode='40001'; end if;
    select coalesce(array_agg(value::uuid order by value::uuid),'{}'::uuid[]) into v_locked_root_ids
      from jsonb_array_elements_text(v_publication_i1_context->'root_ids') value;
    v_observed_root_ids:=private.weekly_source_publication_signed_roots_v1(v_publication.id);
    if v_observed_root_ids is distinct from v_locked_root_ids then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_SIGNED_ROOT_SET_CHANGED' using errcode='40001'; end if;
  end if;
  -- Recheck signed weeks only for days in this upload's confirmed export
  -- period. A week may straddle that period; compare_sync applies the same
  -- day boundary to candidate rows and incident resolution.
  for v_signed in
    select sheet.timesheet_id,sheet.week_ending_date,sheet.actual_schedule_json,sheet.additional_units_per_day,contract.candidate_id,contract.client_id,contract.id as contract_id
    from public.timesheets sheet join public.contracts contract on contract.id=sheet.contract_id
    where sheet.timesheet_id=any(private.weekly_source_publication_signed_roots_v1(v_publication.id))
    order by sheet.timesheet_id
  loop
    -- Growth refusal is OUTSIDE per-sheet isolation: never log it as a harmless
    -- NOT_COMPARED and then acquire a second physical family out of order.
    if v_locked_root_ids is not null and not(v_signed.timesheet_id=any(v_locked_root_ids)) then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_SIGNED_ROOT_SET_CHANGED' using errcode='40001'; end if;
    -- Each sheet is one native subtransaction. A refusal rolls back only its
    -- comparison effects; the native append-only audit records NOT_COMPARED.
    begin
      if not (exists (
        select 1
        from public.weekly_source_uploads historical_upload
        join public.weekly_source_upload_rows source_row
          on source_row.upload_id=historical_upload.id
        join public.weekly_source_row_resolutions resolution
          on resolution.upload_row_id=source_row.id
         and resolution.mapping_state='RESOLVED'
        where historical_upload.source_cycle_id=v_cycle.id
          and historical_upload.source_format_profile_id=v_profile_id
          and source_row.work_date between v_signed.week_ending_date-6
            and v_signed.week_ending_date
          and source_row.work_date between
            v_upload.confirmed_coverage_start_local_date
            and v_upload.confirmed_coverage_end_local_date
          and resolution.candidate_id=v_signed.candidate_id
          and resolution.client_id=v_signed.client_id
          and resolution.contract_id=v_signed.contract_id
      ) or exists (
        select 1
        from pg_catalog.jsonb_array_elements(
          private.weekly_source_candidate_app_schedule_v1(
            v_signed.actual_schedule_json,v_signed.additional_units_per_day
          )
        ) candidate_shift
        where (candidate_shift.value->>'date')::date between
          v_upload.confirmed_coverage_start_local_date
          and v_upload.confirmed_coverage_end_local_date
          and private._weekly_source_effective_policy_v1(
            v_signed.client_id,v_signed.contract_id,(candidate_shift.value->>'date')::date
          )->>'source_group_id'=v_cycle.source_group_id::text
      )) then continue; end if;
      v_result:=private.weekly_source_candidate_submission_compare_sync_v1(
        null,v_publication.id,null,v_signed.timesheet_id,
        private.weekly_source_query_candidate_timesheet_hash_v1(v_signed.timesheet_id));
      perform private.weekly_source_publication_comparison_record_v1(v_publication.id,v_signed.timesheet_id,'COMPARED',null);
    exception when others then
      v_refusal:=coalesce(substring(sqlerrm from '^[A-Z][A-Z0-9_]{0,119}$'),'WEEKLY_SOURCE_COMPARISON_REFUSED');
      perform private.weekly_source_publication_comparison_record_v1(v_publication.id,v_signed.timesheet_id,'NOT_COMPARED',v_refusal);
      v_not_compared:=v_not_compared+1;
      continue;
    end;
    v_checked:=v_checked+1;
    v_new:=v_new+(v_result->>'new_incidents')::integer;
    v_changed:=v_changed+(v_result->>'changed_comparisons')::integer;
    v_resolved:=v_resolved+(v_result->>'resolved_incidents')::integer;
    if (v_result->>'new_incidents')::integer+(v_result->>'changed_comparisons')::integer>0 then
      v_restart_keys:=pg_catalog.array_append(
        v_restart_keys,v_signed.candidate_id::text||':'||v_signed.client_id::text
      );
    end if;
  end loop;
  for v_restart_key in
    select distinct key_value collate "C"
    from pg_catalog.unnest(v_restart_keys) key_value
    order by key_value
  loop
    perform private.weekly_source_query_restart_activated_cohort_v1(
      v_cycle.id,pg_catalog.split_part(v_restart_key,':',1)::uuid,
      pg_catalog.split_part(v_restart_key,':',2)::uuid,v_publication.id
    );
  end loop;
  if v_profile_code<>'NHSP_PREFINAL_RELEASED_V1' then
    v_unsigned:=private.weekly_source_expected_week_unsigned_materialise_v1(v_publication.id);
    v_new:=v_new+(v_unsigned->>'new_incidents')::integer;
    v_changed:=v_changed+(v_unsigned->>'changed_comparisons')::integer;
    v_resolved:=v_resolved+(v_unsigned->>'resolved_incidents')::integer;
    perform private.weekly_source_not_finalised_dispatch_v1(v_publication.id);
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'not_compared',v_not_compared,'signed_weeks_checked',v_checked,'new_incidents',v_new,
    'changed_comparisons',v_changed,'resolved_incidents',v_resolved
  );
end;
$function$;

create or replace function public.weekly_source_projection_publish_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_publication_id uuid;
  v_expected_comparison bytea;
  v_expected_issue bytea;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_scope_version bigint;
  v_scope_upload uuid;
  v_client_id uuid;
  v_comparison_hash bytea;
  v_issue_hash bytea;
  v_fingerprint bytea;
  v_resolution_count integer;
  v_generation integer;
  v_ready_session_version bigint;
  v_signed_fence jsonb; v_prior_publication_i1_context text:=current_setting('cloudtms.weekly_source_publication_i1_context',true);
begin
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(
       select 1 from pg_catalog.jsonb_object_keys(p_request) key
       where key not in ('actor_user_id','publication_id',
         'expected_comparison_manifest_hash','expected_issue_set_hash')
     ) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_PUBLISH_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_publication_id:=(p_request->>'publication_id')::uuid;
  exception when invalid_text_representation then
    raise exception 'WEEKLY_SOURCE_PROJECTION_PUBLISH_REQUEST_INVALID' using errcode='22023';
  end;
  if v_actor is null or v_publication_id is null then
    raise exception 'WEEKLY_SOURCE_PROJECTION_PUBLISH_REQUEST_INVALID' using errcode='22023';
  end if;
  v_expected_comparison:=case
    when nullif(p_request->>'expected_comparison_manifest_hash','') is null then null
    else private.weekly_source_hex32_v1(
      p_request->>'expected_comparison_manifest_hash',
      'WEEKLY_SOURCE_COMPARISON_MANIFEST_HASH_INVALID'
    ) end;
  v_expected_issue:=case
    when nullif(p_request->>'expected_issue_set_hash','') is null then null
    else private.weekly_source_hex32_v1(
      p_request->>'expected_issue_set_hash','WEEKLY_SOURCE_ISSUE_SET_HASH_INVALID'
    ) end;

  select * into v_publication
  from public.weekly_source_projection_publications
  where id=v_publication_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_NOT_FOUND' using errcode='22023';
  end if;
  select * into strict v_upload
  from public.weekly_source_uploads where id=v_publication.upload_id;
  select * into strict v_cycle
  from public.weekly_source_cycles where id=v_publication.source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups where id=v_cycle.source_group_id;
  if v_publication.authority_scope_kind='CYCLE' then
    v_scope_version:=v_cycle.version;
    v_scope_upload:=v_cycle.current_complete_upload_id;
    begin
      v_client_id:=nullif(v_upload.file_metadata_json->>'client_id','')::uuid;
    exception when invalid_text_representation then
      raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_INVALID' using errcode='55000';
    end;
  else
    select * into strict v_scope
    from public.weekly_source_report_scopes
    where id=v_publication.report_scope_id;
    v_scope_version:=v_scope.version;
    v_scope_upload:=v_scope.current_complete_upload_id;
    v_client_id:=v_scope.client_id;
  end if;
  perform private.weekly_source_pay_query_admit_v2();
  if v_publication.authority_scope_kind='CYCLE' and v_publication.correction_session_id is null then
    -- Full signed set, including an empty set, captured before any business lock.
    v_signed_fence:=private.weekly_source_publication_signed_family_fence_v1(v_publication.id,null);
    perform set_config('cloudtms.weekly_source_publication_i1_context',jsonb_build_object('schema_version','WEEKLY_SOURCE_PUBLICATION_I1_CONTEXT_V1',
      'publication_id',v_publication.id,'root_ids',v_signed_fence->'signed_root_ids')::text,true);
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.encode(v_upload.declared_scope_fingerprint,'hex'),73241837)
  );
  -- Retain the native scope advisory before group/cycle to match upload owners.
  -- Signed physical I-1 was acquired above. Binding's group lock is pre-held.
  select * into strict v_group from public.weekly_source_groups where id=v_group.id for update;
  perform 1 from public.weekly_source_cycles where id=v_cycle.id for update;
  if v_publication.authority_scope_kind='SELF_BILL_REPORT_SCOPE' then
    perform private.weekly_source_self_bill_report_seal_assert_v1(v_upload.id);
  end if;
  if v_publication.authority_scope_kind='CYCLE' then
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_publication.source_cycle_id for update;
    v_scope_version:=v_cycle.version;
    v_scope_upload:=v_cycle.current_complete_upload_id;
  else
    -- Each NHSP Trust publishes independently under its report-scope head.
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_publication.source_cycle_id;
    select * into strict v_scope
    from public.weekly_source_report_scopes
    where id=v_publication.report_scope_id for update;
    if v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id
       or v_scope.environment is distinct from v_group.environment
       or v_scope.agency_id is distinct from v_group.agency_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc then
      raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_CHANGED' using errcode='55000';
    end if;
    v_scope_version:=v_scope.version;
    v_scope_upload:=v_scope.current_complete_upload_id;
    v_client_id:=v_scope.client_id;
  end if;
  select * into strict v_publication
  from public.weekly_source_projection_publications
  where id=v_publication_id for update;
  select * into strict v_upload
  from public.weekly_source_uploads where id=v_publication.upload_id;
  if v_signed_fence is not null then
    perform private.weekly_source_publication_signed_family_fence_v1(v_publication.id,v_signed_fence);
  end if;
  if private.weekly_source_scope_fingerprint_v1(
       v_group.environment,v_group.agency_id,v_group.id,v_cycle.id,
       v_publication.report_scope_id,v_client_id
     ) is distinct from v_upload.declared_scope_fingerprint then
    raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_CHANGED' using errcode='55000';
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'RECHECK_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  if v_publication.correction_session_id is not null then
    select * into v_correction
    from public.weekly_final_source_correction_sessions
    where id=v_publication.correction_session_id for update;
    if not found
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from v_publication.authority_scope_kind
       or v_correction.report_scope_id is distinct from v_publication.report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.actor_user_id is distinct from v_actor
       or v_upload.purpose<>'FINAL_SOURCE_CORRECTION'
       or v_upload.state<>'CORRECTION_READY'
       or v_scope_version<>v_publication.authority_scope_version
       or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
            is distinct from v_correction.expected_current_final_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PUBLICATION_STALE' using errcode='40001';
    end if;
    if v_publication.state='CORRECTION_READY' then
      if v_correction.replacement_projection_publication_id is distinct from v_publication.id
         or (v_publication.rebuild_idempotency_key is not null
             and v_publication.ready_session_version is null) then
        raise exception 'WEEKLY_SOURCE_CORRECTION_PUBLICATION_STALE' using errcode='40001';
      end if;
      if (v_expected_comparison is not null
            and v_expected_comparison<>v_publication.comparison_manifest_hash)
         or (v_expected_issue is not null
            and v_expected_issue<>v_publication.issue_set_hash) then
        raise exception 'WEEKLY_SOURCE_PUBLICATION_HASH_MISMATCH' using errcode='40001';
      end if;
      v_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_PUBLICATION_FINGERPRINT_V1',
        pg_catalog.jsonb_build_object(
          'publication_id',v_publication.id,'upload_id',v_publication.upload_id,
          'authority_scope_version',v_publication.authority_scope_version,
          'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
          'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex')
        )
      );
      perform set_config('cloudtms.weekly_source_publication_i1_context',coalesce(v_prior_publication_i1_context,''),true);
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','CORRECTION_READY','publication_id',v_publication.id,
        'upload_id',v_publication.upload_id,
        'authority_scope_version',v_publication.authority_scope_version,
        'projection_generation',v_publication.projection_generation,
        'ready_session_version',v_publication.ready_session_version,
        'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
        'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex'),
        'publication_fingerprint',pg_catalog.encode(v_fingerprint,'hex'),'idempotent',true
      );
    end if;
    if (v_publication.rebuild_idempotency_key is null and (
         v_correction.state<>'READY'
         or v_correction.replacement_projection_publication_id is not null
       ))
       or (v_publication.rebuild_idempotency_key is not null and (
         v_publication.projection_generation is null
         or v_publication.ready_session_version is null
         or v_correction.state<>'REVIEWED'
         or v_correction.version<>v_publication.ready_session_version
         or v_correction.replacement_projection_publication_id is null
         or v_correction.replacement_projection_publication_id=v_publication.id
       )) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PUBLICATION_STALE' using errcode='40001';
    end if;
  end if;
  if v_publication.state='CURRENT'
      and v_publication.correction_session_id is null
      and v_scope_upload=v_publication.upload_id
      and v_scope_version=v_publication.authority_scope_version then
    if (v_expected_comparison is not null
          and v_expected_comparison<>v_publication.comparison_manifest_hash)
       or (v_expected_issue is not null
          and v_expected_issue<>v_publication.issue_set_hash) then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_HASH_MISMATCH' using errcode='40001';
    end if;
    v_fingerprint:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_PUBLICATION_FINGERPRINT_V1',
      pg_catalog.jsonb_build_object(
        'publication_id',v_publication.id,'upload_id',v_publication.upload_id,
        'authority_scope_version',v_publication.authority_scope_version,
        'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
        'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex')
      )
    );
    perform set_config('cloudtms.weekly_source_publication_i1_context',coalesce(v_prior_publication_i1_context,''),true);
    return pg_catalog.jsonb_build_object(
      'ok',true,'status',v_publication.state,'publication_id',v_publication.id,
      'upload_id',v_publication.upload_id,
      'authority_scope_version',v_publication.authority_scope_version,
      'projection_generation',v_publication.projection_generation,
      'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
      'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex'),
      'publication_fingerprint',pg_catalog.encode(v_fingerprint,'hex'),'idempotent',true
    );
  end if;
  if v_publication.state not in ('BUILDING','FAILED')
     or v_scope_version<>v_publication.authority_scope_version
     or (v_publication.correction_session_id is null and (
       v_scope_upload is distinct from v_publication.upload_id
       or v_upload.state<>'CURRENT'
     )) then
    if v_publication.state in ('BUILDING','FAILED') then
      update public.weekly_source_projection_publications
      set state='STALE',failure_code='AUTHORITY_SCOPE_CHANGED'
      where id=v_publication.id;
    end if;
    perform set_config('cloudtms.weekly_source_publication_i1_context',coalesce(v_prior_publication_i1_context,''),true);
    return pg_catalog.jsonb_build_object(
      'ok',false,'status','STALE','reason_code','WEEKLY_SOURCE_PUBLICATION_CAS_STALE',
      'publication_id',v_publication.id,'current_upload_id',v_scope_upload,
      'current_authority_scope_version',v_scope_version
    );
  end if;

  if v_publication.authority_scope_version>2147483647
     or coalesce(v_publication.projection_generation,0)>2147483647 then
    raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003';
  end if;
  v_generation:=coalesce(
    v_publication.projection_generation,
    v_publication.authority_scope_version::integer
  );
  select pg_catalog.count(*)::integer into v_resolution_count
  from public.weekly_source_row_resolutions resolution
  join public.weekly_source_upload_rows source_row
    on source_row.id=resolution.upload_row_id
  where source_row.upload_id=v_upload.id
    and resolution.generation=v_generation;
  if v_resolution_count<>(select count(*) from public.weekly_source_upload_rows r
       where r.upload_id=v_upload.id and r.row_finalisation_state<>'SOURCE_REPORT_LINE')
     or exists(
       select 1
       from public.weekly_source_upload_rows source_row
       where source_row.upload_id=v_upload.id
         and source_row.row_finalisation_state<>'SOURCE_REPORT_LINE'
         and not exists(
           select 1
            from public.weekly_source_row_resolutions resolution
            where resolution.upload_row_id=source_row.id
              and resolution.generation=v_generation
              and resolution.source_row_fingerprint=source_row.normalised_row_hash
         )
     )
     or (v_publication.projection_generation is null and exists(
        select 1
        from public.weekly_source_row_resolutions resolution
       join public.weekly_source_upload_rows source_row
         on source_row.id=resolution.upload_row_id
        where source_row.upload_id=v_upload.id
          and resolution.generation<>v_generation
     )) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_RESOLUTION_CENSUS_INCOMPLETE'
      using errcode='55000';
  end if;

  v_comparison_hash:=private.weekly_source_projection_comparison_manifest_hash_v1(
    v_publication.id
  );
  v_issue_hash:=private.weekly_source_projection_issue_set_hash_v1(v_publication.id);
  if (v_expected_comparison is not null and v_expected_comparison<>v_comparison_hash)
     or (v_expected_issue is not null and v_expected_issue<>v_issue_hash) then
    update public.weekly_source_projection_publications
    set state='FAILED',failure_code='PUBLICATION_HASH_MISMATCH'
    where id=v_publication.id;
    if v_publication.correction_session_id is not null then
      update public.weekly_final_source_correction_sessions
      set updated_at_utc=pg_catalog.transaction_timestamp()
      where id=v_publication.correction_session_id;
    elsif v_publication.authority_scope_kind='CYCLE' then
      update public.weekly_source_cycles
      set projection_state='FAILED',current_projection_publication_id=null
      where id=v_cycle.id and current_complete_upload_id=v_publication.upload_id
        and version=v_publication.authority_scope_version;
    else
      update public.weekly_source_report_scopes
      set projection_state='FAILED',current_projection_publication_id=null,
          updated_at_utc=pg_catalog.transaction_timestamp()
      where id=v_scope.id and current_complete_upload_id=v_publication.upload_id
        and version=v_publication.authority_scope_version;
    end if;
    perform set_config('cloudtms.weekly_source_publication_i1_context',coalesce(v_prior_publication_i1_context,''),true);
    return pg_catalog.jsonb_build_object(
      'ok',false,'status','FAILED','reason_code','WEEKLY_SOURCE_PUBLICATION_HASH_MISMATCH',
      'publication_id',v_publication.id
    );
  end if;

  v_ready_session_version:=case when v_publication.correction_session_id is null then null
    else v_correction.version+1 end;
  update public.weekly_source_projection_publications
  set comparison_manifest_hash=v_comparison_hash,issue_set_hash=v_issue_hash,
      state=case when v_publication.correction_session_id is null
        then 'CURRENT' else 'CORRECTION_READY' end,
      ready_session_version=v_ready_session_version,
      failure_code=null,published_at_utc=pg_catalog.transaction_timestamp()
  where id=v_publication.id;
  if v_publication.correction_session_id is not null then
    if v_publication.rebuild_idempotency_key is null then
      update public.weekly_final_source_correction_sessions
      set replacement_projection_publication_id=v_publication.id,
          version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
      where id=v_publication.correction_session_id and state='READY'
        and version=v_correction.version
        and replacement_correction_upload_id=v_publication.upload_id
        and replacement_projection_publication_id is null;
    else
      update public.weekly_final_source_correction_sessions
      set replacement_projection_publication_id=v_publication.id,
          state='READY',review_idempotency_key=null,review_request_hash=null,
          review_result_json=null,review_result_hash=null,
          version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
      where id=v_publication.correction_session_id and state='REVIEWED'
        and version=v_publication.ready_session_version
        and replacement_correction_upload_id=v_publication.upload_id
        and replacement_projection_publication_id is not null
        and replacement_projection_publication_id<>v_publication.id;
    end if;
    if not found then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PUBLICATION_CAS_LOST' using errcode='40001';
    end if;
  elsif v_publication.authority_scope_kind='CYCLE' then
    update public.weekly_source_cycles
    set projection_state='CURRENT',current_projection_publication_id=v_publication.id
    where id=v_cycle.id and current_complete_upload_id=v_publication.upload_id
      and version=v_publication.authority_scope_version;
  else
    update public.weekly_source_report_scopes
    set projection_state='CURRENT',current_projection_publication_id=v_publication.id,
        updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_scope.id and current_complete_upload_id=v_publication.upload_id
      and version=v_publication.authority_scope_version;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_CAS_LOST' using errcode='40001';
  end if;
  if v_publication.correction_session_id is null and exists (
    select 1 from public.weekly_source_format_profiles profile
    where profile.id=v_upload.source_format_profile_id
      and (profile.profile_code='NHSP_PREFINAL_RELEASED_V1'
        or (v_group.source_family='ROSTER' and profile.profile_code in (
          'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1','HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1','ROSTER_WEEKLY_SUMMARY_ACTUAL_V1')))
  ) and v_publication.authority_scope_kind='CYCLE' then
    -- Recheck already-signed candidate evidence in the same publication
    -- transaction. This writes comparison/query evidence only: no source
    -- financial movement or Timesheet hours are created here.
    perform private.weekly_source_candidate_prefinal_publish_recheck_v1(
      v_actor,v_publication.id
    );
  end if;
  if v_publication.correction_session_id is null then
    perform private.weekly_source_self_bill_report_bind_v1(v_publication.id);
  end if;
  if v_publication.correction_session_id is null and v_publication.authority_scope_kind<>'SELF_BILL_REPORT_SCOPE' then
    perform private.weekly_source_import_outreach_v1(v_publication.id);
  end if;
  v_fingerprint:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_PUBLICATION_FINGERPRINT_V1',
    pg_catalog.jsonb_build_object(
      'publication_id',v_publication.id,'upload_id',v_publication.upload_id,
      'authority_scope_version',v_publication.authority_scope_version,
      'comparison_manifest_hash',pg_catalog.encode(v_comparison_hash,'hex'),
      'issue_set_hash',pg_catalog.encode(v_issue_hash,'hex')
    )
  );
  perform set_config('cloudtms.weekly_source_publication_i1_context',coalesce(v_prior_publication_i1_context,''),true);
  return pg_catalog.jsonb_build_object(
    'ok',true,'status',case when v_publication.correction_session_id is null
      then 'CURRENT' else 'CORRECTION_READY' end,
    'publication_id',v_publication.id,
    'upload_id',v_publication.upload_id,
    'authority_scope_version',v_publication.authority_scope_version,
    'projection_generation',v_publication.projection_generation,
    'ready_session_version',v_ready_session_version,
    'comparison_manifest_hash',pg_catalog.encode(v_comparison_hash,'hex'),
    'issue_set_hash',pg_catalog.encode(v_issue_hash,'hex'),
    'publication_fingerprint',pg_catalog.encode(v_fingerprint,'hex'),
    'idempotent',false
  );
exception when others then
  perform set_config('cloudtms.weekly_source_publication_i1_context',coalesce(v_prior_publication_i1_context,''),true);
  raise;
end;
$function$;
alter function private.weekly_source_publication_signed_family_fence_v1(uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_publication_signed_family_fence_v1(uuid,jsonb) from public,anon,authenticated,service_role;
alter function private.weekly_source_candidate_submission_compare_sync_v1(uuid,uuid,uuid,uuid,bytea,timestamp with time zone) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_candidate_submission_compare_sync_v1(uuid,uuid,uuid,uuid,bytea,timestamp with time zone) from public,anon,authenticated,service_role;
alter function private.weekly_source_candidate_prefinal_publish_recheck_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_candidate_prefinal_publish_recheck_v1(uuid,uuid) from public,anon,authenticated,service_role;
alter function public.weekly_source_projection_publish_atomic_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_projection_publish_atomic_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_source_projection_publish_atomic_v1(jsonb) to service_role;
notify pgrst,'reload schema';


-- CONTACT_PREPARER_UNIT 124 repeatable supabase/repeatable/13102026_2025_healthroster_lineage_own_created_root_v1.sql SHA256 e5242b76df512551953d11f21b37a5f8107380ded25291878db5a22a56c79f71
-- Complete native lineage successor: genuine own-created LEGACY root only.


-- Root-review complete forward Source owner; no frozen input edited.
create or replace function public.weekly_source_timesheet_lineage_ensure_atomic_v1(
  p_row_resolution_id uuid,
  p_actor_user_id uuid
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_resolution public.weekly_source_row_resolutions%rowtype;
  v_source_row public.weekly_source_upload_rows%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_contract public.contracts%rowtype;
  v_candidate public.candidates%rowtype;
  v_client public.clients%rowtype;
  v_expense_policy public.weekly_source_row_expense_policy_snapshots%rowtype;
  v_policy jsonb;
  v_contract_week public.contract_weeks%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_lineage public.weekly_source_row_timesheet_lineages%rowtype;
  v_guard jsonb;
  v_contract_week_settings jsonb;
  v_timesheet_settings jsonb;
  v_week_ending_date date;
  v_weekday integer;
  v_booking_id text;
  v_booking_material text;
  v_occupant_norm text;
  v_hospital_norm text;
  v_ward_norm text;
  v_role_norm text;
  v_lineage_fingerprint bytea;
  v_expected_expense_policy_hash bytea;
  v_created_timesheet boolean:=false;
  v_existing_lineage boolean:=false;
  v_is_correction boolean:=false;
  v_lock_result jsonb;
  v_lineage_lock_phase integer;
  v_lineage_discovery jsonb;
  v_lineage_observed jsonb;
  v_family jsonb;
  v_known_root_timesheet_id uuid;
  v_root_authorisation jsonb;
  v_bound_timesheet_id uuid;
  v_finalisation_root_set text;
  v_legacy_root_set_now text;
  v_legacy_root_ids uuid[];
  v_finalisation_lock_operation_text text;
  v_finalisation_lock_operation private.bpay_next_source_current_lock_operations%rowtype;
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_row_resolution_id is null or p_actor_user_id is null then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_LINEAGE_INPUT_REQUIRED' using errcode='22023';
  end if;

  select * into v_resolution
  from public.weekly_source_row_resolutions
  where id=p_row_resolution_id;
  if not found or v_resolution.mapping_state<>'RESOLVED' then
    raise exception 'WEEKLY_SOURCE_RESOLUTION_NOT_CURRENT' using errcode='55000';
  end if;

  select * into strict v_source_row
  from public.weekly_source_upload_rows
  where id=v_resolution.upload_row_id;
  select * into strict v_upload
  from public.weekly_source_uploads
  where id=v_source_row.upload_id;

  perform private.weekly_source_pay_query_admit_v2();
  -- G1 standalone and inherited FIN paths share the same physical I-1 owner.
  -- Phase1 is plain key/scope admission plus its unchanged family call. Phase2
  -- locks discovered group -> cycle and revalidates every selector before DML.
  for v_lineage_lock_phase in 1..2 loop
    if v_lineage_lock_phase=2 then
      select * into v_group from public.weekly_source_groups
      where id=(v_lineage_discovery#>>'{group,id}')::uuid for share;
      if not found or to_jsonb(v_group) is distinct from v_lineage_discovery->'group' then
        raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
    end if;
  if v_lineage_lock_phase=2 then
  select * into v_cycle
  from public.weekly_source_cycles
  where id=v_upload.source_cycle_id
  for update;
    if not found or to_jsonb(v_cycle) is distinct from v_lineage_discovery->'cycle' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_cycle
  from public.weekly_source_cycles
  where id=v_upload.source_cycle_id;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_CYCLE_NOT_FOUND' using errcode='55000';
  end if;

  if v_upload.report_scope_id is not null then
    if v_lineage_lock_phase=2 then
  select * into v_scope
    from public.weekly_source_report_scopes
    where id=v_upload.report_scope_id
    for update;
    if not found or to_jsonb(v_scope) is distinct from v_lineage_discovery->'scope' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_scope
    from public.weekly_source_report_scopes
    where id=v_upload.report_scope_id;
  end if;
    if not found or v_scope.source_cycle_id is distinct from v_cycle.id then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_NOT_CURRENT' using errcode='55000';
    end if;
  end if;

  if v_lineage_lock_phase=2 then
  select * into v_upload
  from public.weekly_source_uploads
  where id=v_source_row.upload_id
    and source_cycle_id=v_cycle.id
  for share;
    if not found or to_jsonb(v_upload) is distinct from v_lineage_discovery->'upload' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_upload
  from public.weekly_source_uploads
  where id=v_source_row.upload_id
    and source_cycle_id=v_cycle.id;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_UPLOAD_NOT_CURRENT' using errcode='55000';
  end if;

  if v_lineage_lock_phase=2 then
  select * into v_publication
  from public.weekly_source_projection_publications publication
  where publication.source_cycle_id=v_cycle.id
    and publication.upload_id=v_upload.id
    and publication.authority_scope_version=v_resolution.generation
    and (
      (
        publication.state='CURRENT'
        and v_upload.purpose='ORDINARY'
        and v_upload.correction_session_id is null
        and (
          (v_upload.report_scope_id is null
           and publication.authority_scope_kind='CYCLE'
           and publication.report_scope_id is null
           and v_cycle.current_projection_publication_id=publication.id
           and v_cycle.current_complete_upload_id=v_upload.id)
          or
          (v_upload.report_scope_id is not null
           and publication.authority_scope_kind='NHSP_REPORT_SCOPE'
           and publication.report_scope_id=v_upload.report_scope_id
           and v_scope.current_projection_publication_id=publication.id
           and v_scope.current_complete_upload_id=v_upload.id)
        )
      )
      or (
        publication.state='CORRECTION_READY'
        and v_upload.state='CORRECTION_READY'
        and v_upload.purpose='FINAL_SOURCE_CORRECTION'
        and v_upload.correction_session_id is not null
        and publication.correction_session_id=v_upload.correction_session_id
        and (
          (v_upload.report_scope_id is null
           and publication.authority_scope_kind='CYCLE'
           and publication.report_scope_id is null)
          or
          (v_upload.report_scope_id is not null
           and publication.authority_scope_kind='NHSP_REPORT_SCOPE'
           and publication.report_scope_id=v_upload.report_scope_id)
        )
      )
    )
  for share;
    if not found or to_jsonb(v_publication) is distinct from v_lineage_discovery->'publication' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_publication
  from public.weekly_source_projection_publications publication
  where publication.source_cycle_id=v_cycle.id
    and publication.upload_id=v_upload.id
    and publication.authority_scope_version=v_resolution.generation
    and (
      (
        publication.state='CURRENT'
        and v_upload.purpose='ORDINARY'
        and v_upload.correction_session_id is null
        and (
          (v_upload.report_scope_id is null
           and publication.authority_scope_kind='CYCLE'
           and publication.report_scope_id is null
           and v_cycle.current_projection_publication_id=publication.id
           and v_cycle.current_complete_upload_id=v_upload.id)
          or
          (v_upload.report_scope_id is not null
           and publication.authority_scope_kind='NHSP_REPORT_SCOPE'
           and publication.report_scope_id=v_upload.report_scope_id
           and v_scope.current_projection_publication_id=publication.id
           and v_scope.current_complete_upload_id=v_upload.id)
        )
      )
      or (
        publication.state='CORRECTION_READY'
        and v_upload.state='CORRECTION_READY'
        and v_upload.purpose='FINAL_SOURCE_CORRECTION'
        and v_upload.correction_session_id is not null
        and publication.correction_session_id=v_upload.correction_session_id
        and (
          (v_upload.report_scope_id is null
           and publication.authority_scope_kind='CYCLE'
           and publication.report_scope_id is null)
          or
          (v_upload.report_scope_id is not null
           and publication.authority_scope_kind='NHSP_REPORT_SCOPE'
           and publication.report_scope_id=v_upload.report_scope_id)
        )
      )
    );
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_PROJECTION_NOT_CURRENT' using errcode='55000';
  end if;

  v_is_correction:=v_publication.state='CORRECTION_READY';
  if v_is_correction then
    if v_lineage_lock_phase=2 then
  select * into v_correction
    from public.weekly_final_source_correction_sessions correction
    where correction.id=v_upload.correction_session_id
    for share;
    if not found or to_jsonb(v_correction) is distinct from v_lineage_discovery->'correction' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_correction
    from public.weekly_final_source_correction_sessions correction
    where correction.id=v_upload.correction_session_id;
  end if;
    if not found or v_correction.state<>'PREPARING'
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from
          (case when v_upload.report_scope_id is null then 'CYCLE'
                else 'NHSP_REPORT_SCOPE' end)
       or v_correction.report_scope_id is distinct from v_upload.report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.replacement_projection_publication_id is distinct from v_publication.id
       or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
            is distinct from v_correction.expected_current_final_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
    end if;
  else
    v_guard:=private.weekly_source_current_publication_guard_v1(
      v_cycle.id,
      case when v_upload.report_scope_id is null then 'CYCLE' else 'NHSP_REPORT_SCOPE' end,
      v_upload.report_scope_id,
      v_upload.id,
      v_publication.id,
      v_publication.authority_scope_version
    );
    if coalesce((v_guard->>'ok')::boolean,false) is not true
       or v_upload.purpose is distinct from 'ORDINARY'
       or v_upload.correction_session_id is not null then
      raise exception 'WEEKLY_SOURCE_PROJECTION_NOT_CURRENT' using errcode='55000';
    end if;
  end if;

  if v_lineage_lock_phase=2 then
  select * into v_resolution
  from public.weekly_source_row_resolutions
  where id=p_row_resolution_id
    and upload_row_id=v_source_row.id
    and generation=v_publication.authority_scope_version
  for update;
    if not found or to_jsonb(v_resolution) is distinct from v_lineage_discovery->'resolution' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_resolution
  from public.weekly_source_row_resolutions
  where id=p_row_resolution_id
    and upload_row_id=v_source_row.id
    and generation=v_publication.authority_scope_version;
  end if;
  if not found or v_resolution.mapping_state<>'RESOLVED' then
    raise exception 'WEEKLY_SOURCE_RESOLUTION_NOT_CURRENT' using errcode='55000';
  end if;
  select * into strict v_source_row
  from public.weekly_source_upload_rows
  where id=v_resolution.upload_row_id and upload_id=v_upload.id;

  select * into strict v_profile
  from public.weekly_source_format_profiles
  where id=v_upload.source_format_profile_id;
  select * into strict v_group
  from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  select * into strict v_event
  from public.weekly_work_events
  where id=v_resolution.work_event_id;
  select * into v_contract
  from public.contracts
  where id=v_resolution.contract_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CONTRACT_NOT_FOUND' using errcode='55000';
  end if;

  if v_upload.report_scope_id is not null and not v_is_correction then
    if v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.client_id is distinct from v_resolution.client_id
       or v_scope.current_projection_publication_id is distinct from v_publication.id
       or v_scope.current_complete_upload_id is distinct from v_upload.id then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_NOT_CURRENT' using errcode='55000';
    end if;
  end if;

  if not v_profile.active
     or v_profile.profile_code not in (
       'NHSP_FINAL_BACKING_V1',
       'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
       'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1',
       'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1'
     )
     or v_source_row.row_finalisation_state not in (
       'NOT_APPLICABLE','SOURCE_WORKED','SOURCE_ABSENT_ZERO'
     )
     or (v_source_row.row_finalisation_state='SOURCE_ABSENT_ZERO'
         and v_profile.profile_code<>'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1')
     or v_resolution.work_event_id is distinct from v_event.id
     or v_resolution.candidate_id is distinct from v_event.candidate_id
     or v_resolution.client_id is distinct from v_event.client_id
     or v_source_row.work_date is distinct from v_event.work_date
     or v_resolution.client_id is distinct from v_contract.client_id
     or v_resolution.candidate_id is distinct from v_contract.candidate_id
     or v_source_row.work_date not between v_contract.start_date and v_contract.end_date then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_LINEAGE_SCOPE_INVALID' using errcode='55000';
  end if;

  v_policy:=private._weekly_source_effective_policy_v1(
    v_resolution.client_id,v_resolution.contract_id,v_source_row.work_date
  );
  if v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true
     or v_policy->>'c1_source_mode' not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or private.weekly_source_projection_hex32_v1(
          v_policy->>'policy_sha256','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
        ) is distinct from v_resolution.effective_policy_fingerprint
     or (v_group.source_family='NHSP') is distinct from
        (v_policy->>'c1_source_mode'='NHSP_WEEKLY')
     or (v_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT') is distinct from
        (v_group.source_family='NHSP') then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_LINEAGE_POLICY_INVALID' using errcode='55000';
  end if;

  if v_source_row.row_finalisation_state='SOURCE_ABSENT_ZERO' then
    if coalesce((v_policy->>'source_fixed_expenses_enabled')::boolean,false) is not true
       or v_source_row.source_expense_parse_state<>'VALID'
       or coalesce(v_source_row.source_expense_pence,0)<=0
       or v_source_row.actual_net_minutes<>0
       or v_source_row.start_at_local is null
       or v_source_row.end_at_local is null
       or v_source_row.end_at_local<=v_source_row.start_at_local
       or v_source_row.break_minutes is null
       or exists(
         select 1 from public.weekly_source_row_economic_snapshots economic
         where economic.row_resolution_id=v_resolution.id
       ) then
      raise exception 'WEEKLY_SOURCE_ZERO_HOUR_EXPENSE_LINEAGE_INVALID' using errcode='55000';
    end if;

    select * into v_expense_policy
    from public.weekly_source_row_expense_policy_snapshots expense_policy
    where expense_policy.row_resolution_id=v_resolution.id;
    if not found or (
      select pg_catalog.count(*)
      from public.weekly_source_row_expense_policy_snapshots expense_policy
      where expense_policy.row_resolution_id=v_resolution.id
    )<>1 then
      raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_SNAPSHOT_CARDINALITY' using errcode='55000';
    end if;
    v_expected_expense_policy_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_ROW_EXPENSE_POLICY_SNAPSHOT_V1',
      pg_catalog.jsonb_build_object(
        'row_resolution_id',v_resolution.id,'upload_row_id',v_source_row.id,
        'generation',v_resolution.generation,'work_event_id',v_resolution.work_event_id,
        'candidate_id',v_resolution.candidate_id,'client_id',v_resolution.client_id,
        'contract_id',v_resolution.contract_id,
        'row_finalisation_state',v_source_row.row_finalisation_state,
        'source_expense_pence',v_source_row.source_expense_pence,
        'source_expense_parse_state',v_source_row.source_expense_parse_state,
        'source_expense_vat_enabled',v_expense_policy.source_expense_vat_enabled,
        'invoice_vat_chargeable',v_expense_policy.invoice_vat_chargeable,
        'invoice_vat_rate_pct',v_expense_policy.invoice_vat_rate_pct,
        'correction_presentation',v_expense_policy.correction_presentation,
        'effective_policy_fingerprint',
          pg_catalog.encode(v_expense_policy.effective_policy_fingerprint,'hex'),
        'invoice_vat_policy_fingerprint',
          pg_catalog.encode(v_expense_policy.invoice_vat_policy_fingerprint,'hex')
      )
    );
    if v_expense_policy.upload_row_id is distinct from v_source_row.id
       or v_expense_policy.generation is distinct from v_resolution.generation
       or v_expense_policy.work_event_id is distinct from v_resolution.work_event_id
       or v_expense_policy.candidate_id is distinct from v_resolution.candidate_id
       or v_expense_policy.client_id is distinct from v_resolution.client_id
       or v_expense_policy.contract_id is distinct from v_resolution.contract_id
       or v_expense_policy.source_expense_pence is distinct from v_source_row.source_expense_pence
       or v_expense_policy.source_expense_parse_state is distinct from v_source_row.source_expense_parse_state
       or v_expense_policy.effective_policy_fingerprint is distinct from
          v_resolution.effective_policy_fingerprint
       or v_expense_policy.source_expense_vat_enabled is distinct from
          coalesce((v_policy->>'source_expense_vat_enabled')::boolean,false)
       or v_expense_policy.correction_presentation is distinct from
          pg_catalog.upper(pg_catalog.btrim(coalesce(
            v_policy->>'self_bill_correction_presentation',''
          )))
       or v_expense_policy.snapshot_hash is distinct from v_expected_expense_policy_hash then
      raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_SNAPSHOT_INVALID' using errcode='55000';
    end if;
  elsif (select pg_catalog.count(*)
         from public.weekly_source_row_economic_snapshots economic
         where economic.row_resolution_id=v_resolution.id)<>1 then
    raise exception 'WEEKLY_SOURCE_ECONOMIC_SNAPSHOT_CARDINALITY' using errcode='55000';
  end if;

  perform private.weekly_source_office_authority_v1(
    p_actor_user_id,'FINALISE_WEEK',v_group.id,v_resolution.client_id,
    v_cycle.finalisation_week_ending
  );

  v_weekday:=v_contract.week_ending_weekday_snapshot;
  if v_weekday not between 0 and 6 then
    raise exception 'WEEKLY_SOURCE_WEEK_ENDING_POLICY_INVALID' using errcode='55000';
  end if;
  v_week_ending_date:=v_source_row.work_date+
    ((v_weekday-extract(dow from v_source_row.work_date)::integer+7)%7);

  -- Note on the Candidate serial gate (proof/32 section 6 step 1): this owner
  -- binds a resolved source row to its ordinary base Weekly Timesheet.  It is
  -- not one of the four pinned Weekly Source job types (first authorisation,
  -- first-authorisation withdrawal, entitlement publication, pending release),
  -- so it does not take the gate; the first-authorisation owner does, through
  -- interface I-1.  It does take the full rotation lock set below.

  -- Review F1 and F4.  Every installed rotation owner takes the family advisory
  -- key and then the family rows, and only then contract_weeks (core
  -- 08082026_2035_...:126-131 then :190-193; legacy 16122025_...:844-849;
  -- confirmed route :2374-2376 then :2384-2385).  This owner previously locked
  -- the Contract Week, the Contract and the root row FIRST and asked for the
  -- family advisory keys afterwards, which is the reverse order and a proven
  -- deadlock (reproductions D1 and D2).  The root is therefore discovered with a
  -- PLAIN read, the I-1 lock set is taken FIRST, and every other lock follows.
  select contract_week.timesheet_id into v_known_root_timesheet_id
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_resolution.contract_id
    and contract_week.week_ending_date=v_week_ending_date
    and contract_week.additional_seq=0;

  if v_lineage_lock_phase=2 and v_known_root_timesheet_id is distinct from
      nullif(v_lineage_discovery->>'root_timesheet_id','')::uuid then
    raise exception 'WEEKLY_SOURCE_BASE_WEEK_ROOT_CHANGED_DURING_LOCK' using errcode='40001'; end if;

  -- Review G2, the finalisation side of the same rule.  When a finalisation has
  -- already taken the complete sorted family lock set for this cycle, it
  -- publishes that set here.  A root this owner discovers that the set does not
  -- contain would be locked out of that sorted order, so refuse retryably
  -- instead.  Outside a finalisation the setting is absent and nothing changes.
  v_finalisation_lock_operation_text:=nullif(pg_catalog.btrim(coalesce(
    pg_catalog.current_setting('cloudtms.weekly_source_finalisation_lock_operation',true),''
  )), '');
  if v_finalisation_lock_operation_text is not null
     and (select active_owner from private.bpay_next_module_control where id=1)='NEXT' then
    -- One owner-private operation UUID replaces the whole-root CSV only for
    -- NEXT. It is not authority by itself: bind transaction and actual Source
    -- upload/publication/generation/exact old correction revision first.
    select o.* into v_finalisation_lock_operation
    from private.bpay_next_source_current_lock_operations o
    where o.id=v_finalisation_lock_operation_text::uuid
      and o.transaction_id=pg_catalog.pg_current_xact_id()
      and o.upload_id=v_upload.id and o.projection_publication_id=v_publication.id
      and o.generation=v_resolution.generation
      and o.old_revision_id is not distinct from case when v_is_correction
        then v_correction.expected_current_final_revision_id else null end
      and o.source_group_id=v_group.id and o.client_id=v_resolution.client_id;
    if not found then
      raise exception 'WEEKLY_SOURCE_FINALISATION_LOCK_OPERATION_UNBOUND' using errcode='40001';
    end if;
    if v_known_root_timesheet_id is not null and not exists(
      select 1 from private.bpay_next_source_current_lock_members m
      join public.timesheets t on t.timesheet_id=m.root_timesheet_id
      where m.operation_id=v_finalisation_lock_operation.id
        and m.root_timesheet_id=v_known_root_timesheet_id and m.raw_booking_id=t.booking_id
    ) then
      raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK' using errcode='40001';
    end if;
  else
  -- Retain the unrelated/default OFF Source guard exactly as before.
  v_finalisation_root_set:=nullif(pg_catalog.btrim(coalesce(
    pg_catalog.current_setting('cloudtms.weekly_source_finalisation_root_set',true),''
  )),'');
  if v_finalisation_root_set is not null
     and v_known_root_timesheet_id is not null
     and (v_finalisation_root_set='EMPTY_LOCKED_SET'
       or not (v_known_root_timesheet_id::text
              =any(pg_catalog.string_to_array(v_finalisation_root_set,',')))) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'code','WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK',
          'observed_root_timesheet_id',v_known_root_timesheet_id
        )::text;
  end if;
  end if;

  if v_known_root_timesheet_id is not null and v_lineage_lock_phase=1 then
    v_lock_result:=private.weekly_source_lock_family_rows_v1(
      array[v_known_root_timesheet_id]::uuid[],v_resolution.candidate_id
    );
    if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
      raise exception '%',v_lock_result->>'code'
        using errcode='55000',detail=v_lock_result::text;
    end if;
    v_family:=v_lock_result->'families'->0;
  end if;

  v_lineage_observed:=jsonb_build_object('cycle',to_jsonb(v_cycle),'group',to_jsonb(v_group),
    'scope',to_jsonb(v_scope),'upload',to_jsonb(v_upload),'publication',to_jsonb(v_publication),
    'correction',to_jsonb(v_correction),'resolution',to_jsonb(v_resolution),'source_row',to_jsonb(v_source_row),
    'profile',to_jsonb(v_profile),'event',to_jsonb(v_event),'contract',to_jsonb(v_contract),
    'policy',v_policy,'expense_policy',to_jsonb(v_expense_policy),
    'week_ending_date',v_week_ending_date,'root_timesheet_id',v_known_root_timesheet_id);
  if v_lineage_lock_phase=1 then v_lineage_discovery:=v_lineage_observed;
  elsif v_lineage_observed is distinct from v_lineage_discovery then
    raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  end loop;

  -- A missing base Contract Week has no row to lock, so use the same scoped
  -- advisory lock before selecting/inserting it.  This is not a business key
  -- or an externally visible lock, and it is now taken after the family keys.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'WEEKLY_SOURCE_BASE_WEEK|'||v_resolution.contract_id::text||'|'||v_week_ending_date::text,
    0
  ));

  insert into public.contract_weeks(
    contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id,is_adjustment,created_at,updated_at
  ) values (
    v_resolution.contract_id,v_week_ending_date,0,
    'SUBMITTED'::public.contract_week_status_enum,
    'MANUAL'::public.submission_mode_enum,null,false,
    pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()
  ) on conflict (contract_id,week_ending_date,additional_seq) do nothing;

  select * into strict v_contract_week
  from public.contract_weeks
  where contract_id=v_resolution.contract_id
    and week_ending_date=v_week_ending_date
    and additional_seq=0
  for update;

  -- Existing manual week owners lock the base week before the Contract.  Keep
  -- that order, then revalidate every mutable Contract fact and recompute the
  -- week end while both rows are protected.
  select * into v_contract
  from public.contracts
  where id=v_resolution.contract_id
  for update;
  if not found
     or v_resolution.client_id is distinct from v_contract.client_id
     or v_resolution.candidate_id is distinct from v_contract.candidate_id
     or v_source_row.work_date not between v_contract.start_date and v_contract.end_date
     or v_contract.week_ending_weekday_snapshot not between 0 and 6
     or v_week_ending_date is distinct from v_source_row.work_date+
        ((v_contract.week_ending_weekday_snapshot-
          extract(dow from v_source_row.work_date)::integer+7)%7) then
    raise exception 'WEEKLY_SOURCE_CONTRACT_CHANGED_DURING_LINEAGE' using errcode='55000';
  end if;

  if v_contract_week.contract_id is distinct from v_resolution.contract_id
     or v_contract_week.week_ending_date is distinct from v_week_ending_date
     or v_contract_week.additional_seq<>0
     or v_contract_week.is_adjustment
     or v_contract_week.status='CANCELLED'::public.contract_week_status_enum then
    raise exception 'WEEKLY_SOURCE_BASE_CONTRACT_WEEK_INVALID' using errcode='55000';
  end if;

  -- Under the locks, the Contract Week must still name the root whose family
  -- this transaction locked.  If it now names a different root, or gained one
  -- after the plain read found none, the family locks would be the wrong ones:
  -- refuse retryably rather than take a second family lock set out of order.
  if v_contract_week.timesheet_id is distinct from v_known_root_timesheet_id then
    raise exception 'WEEKLY_SOURCE_BASE_WEEK_ROOT_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'expected_root_timesheet_id',v_known_root_timesheet_id,
          'observed_root_timesheet_id',v_contract_week.timesheet_id
        )::text;
  end if;

  if v_contract_week.timesheet_id is not null then
    -- The family rows are already locked by the I-1 lock set above, so this is
    -- a re-entrant read of a row this transaction holds, not a new lock order.
    select * into v_timesheet
    from public.timesheets
    where timesheet_id=v_contract_week.timesheet_id
    for update;
    -- proof/34 rule 6 and section 5 step 3: a stored contract-week Timesheet id
    -- that is no longer the current version is a ROTATION, not an invalid
    -- Timesheet.  It is classified below, after the rotation lock set has been
    -- taken, so it carries the exact
    -- WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION refusal (ROT-001).
    if not found
       or v_timesheet.contract_id is distinct from v_resolution.contract_id
       or v_timesheet.week_ending_date is distinct from v_week_ending_date
       or v_timesheet.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum
       or v_timesheet.line_type<>'HOURS'::public.timesheet_line_type_enum
       or v_timesheet.is_adjustment
       or v_timesheet.revoked_at is not null
       or v_timesheet.archived_at_utc is not null then
      raise exception 'WEEKLY_SOURCE_EXISTING_TIMESHEET_INVALID' using errcode='55000';
    end if;
  else
    if v_contract_week.status in (
      'AUTHORISED'::public.contract_week_status_enum,
      'INVOICED'::public.contract_week_status_enum,
      'CANCELLED'::public.contract_week_status_enum
    ) then
      raise exception 'WEEKLY_SOURCE_FINAL_WEEK_TIMESHEET_MISSING' using errcode='55000';
    end if;

    select * into strict v_candidate
    from public.candidates where id=v_resolution.candidate_id;
    select * into strict v_client
    from public.clients where id=v_resolution.client_id;

    v_occupant_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_candidate.tms_ref),''),
      nullif(pg_catalog.btrim(v_candidate.display_name),''),
      v_candidate.id::text
    ));
    v_hospital_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.display_site),''),
      nullif(pg_catalog.btrim(v_client.name),''),
      v_client.id::text
    ));
    v_ward_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.ward_hint),''),'contract'
    ));
    v_role_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.role),''),'weekly'
    ));
    v_booking_material:='weekly-source|'||v_resolution.contract_id::text||'|'||
      v_week_ending_date::text;
    v_booking_id:='bk_'||pg_catalog.substr(pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(v_booking_material,'UTF8'),'sha256'),'hex'
    ),1,24);

    if exists(
      select 1
      from public.timesheets existing
      where existing.booking_id=v_booking_id
        and existing.is_current
    ) then
      raise exception 'WEEKLY_SOURCE_BOOKING_ID_COLLISION' using errcode='55000';
    end if;

    insert into public.timesheets(
      booking_id,version,is_current,status,sheet_scope,submission_mode,line_type,
      occupant_key_norm,hospital_norm,ward_norm,job_title_norm,shift_label_norm,
      week_ending_date,contract_id,actual_schedule_json,qr_payload_json,
      is_adjustment,created_at,updated_at
    ) values (
      v_booking_id,1,true,'RECEIVED'::public.timesheet_status_enum,
      'WEEKLY'::public.timesheet_scope_enum,'MANUAL'::public.submission_mode_enum,
      'HOURS'::public.timesheet_line_type_enum,v_occupant_norm,v_hospital_norm,
      v_ward_norm,v_role_norm,'weekly-0',v_week_ending_date,
      v_resolution.contract_id,'[]'::jsonb,'{}'::jsonb,false,
      pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()
    ) returning * into v_timesheet;
    v_created_timesheet:=true;

    if v_finalisation_lock_operation.id is not null then
      -- Only this genuine INSERT RETURNING may add a new private root; never
      -- a lookup/fallback or a root that appeared externally. No pre-existing
      -- booking key is invented: retain the Source base-week creation serial
      -- policy. Subsequent WORK/expense rows can re-enter this exact own root.
      insert into private.bpay_next_source_current_lock_members(
        operation_id,root_timesheet_id,raw_booking_id,canonical_booking_id
      ) values(v_finalisation_lock_operation.id,v_timesheet.timesheet_id,
        v_timesheet.booking_id,pg_catalog.btrim(v_timesheet.booking_id));
    end if;

    update public.contract_weeks
    set timesheet_id=v_timesheet.timesheet_id,
        status=case when status='AUTHORISED'::public.contract_week_status_enum
          then status else 'SUBMITTED'::public.contract_week_status_enum end,
        updated_at=pg_catalog.statement_timestamp()
    where id=v_contract_week.id
    returning * into v_contract_week;

    insert into public.audit_events(
      ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,before_json,after_json,reason
    )
    select
      pg_catalog.statement_timestamp(),p_actor_user_id,actor.display_name,actor.role,
      'timesheets',v_timesheet.timesheet_id::text,
      'WEEKLY_SOURCE_BASE_TIMESHEET_CREATED',null,
      pg_catalog.jsonb_build_object(
        'source_cycle_id',v_cycle.id,
        'row_resolution_id',v_resolution.id,
        'work_event_id',v_resolution.work_event_id,
        'contract_id',v_resolution.contract_id,
        'contract_week_id',v_contract_week.id,
        'candidate_id',v_resolution.candidate_id,
        'client_id',v_resolution.client_id,
        'week_ending_date',v_week_ending_date
      ),'FINAL_SOURCE_LINEAGE'
    from public.tms_users actor
    where actor.id=p_actor_user_id;

    if not found then
      raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
    end if;
  end if;

  -- proof/34 section 5 step 2: the deadlock-free rotation lock set and a
  -- re-resolution of the canonical current version through the installed
  -- Workbench authority.  A stored or newly minted physical id is only a lookup
  -- key; it is never trusted on its own (rule 6).
  --
  -- For an existing root the lock set was already taken, before every other
  -- lock, so this call is re-entrant and re-resolves under the locks.  For a
  -- root this transaction has just minted, no other session can know the
  -- booking id yet, so taking the family keys here cannot join a cycle.
  v_lock_result:=private.weekly_source_lock_family_rows_v1(
    array[v_timesheet.timesheet_id]::uuid[],v_resolution.candidate_id
  );
  if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
    raise exception '%',v_lock_result->>'code'
      using errcode='55000',detail=v_lock_result::text;
  end if;
  v_family:=v_lock_result->'families'->0;

  -- Only the native INSERT RETURNING above can extend this transaction's
  -- already complete LEGACY lock census. It owns this previously invisible
  -- root, and the unchanged native I-1 call has now succeeded. A lookup,
  -- replay, external root, rotation or nonempty unbound NEXT operation cannot
  -- enter this branch. Existing discovery/root-set growth 40001 guards remain.
  if v_created_timesheet and v_finalisation_lock_operation.id is null
     and v_finalisation_lock_operation_text is null
     and v_finalisation_root_set is not null
     and (select active_owner from private.bpay_next_module_control where id=1)='LEGACY' then
    v_legacy_root_set_now:=nullif(pg_catalog.btrim(coalesce(
      pg_catalog.current_setting('cloudtms.weekly_source_finalisation_root_set',true),''
    )),'');
    if v_legacy_root_set_now is distinct from v_finalisation_root_set
       or v_known_root_timesheet_id is not null
       or v_timesheet.timesheet_id is null
       or v_timesheet.booking_id is distinct from v_booking_id
       or v_timesheet.contract_id is distinct from v_resolution.contract_id
       or v_timesheet.week_ending_date is distinct from v_week_ending_date then
      raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK' using errcode='40001';
    end if;
    -- EMPTY_LOCKED_SET is an explicit complete empty census, never a UUID.
    if v_legacy_root_set_now='EMPTY_LOCKED_SET' then
      v_legacy_root_ids:=array[]::uuid[];
    else
      begin
        v_legacy_root_ids:=pg_catalog.string_to_array(v_legacy_root_set_now,',')::uuid[];
      exception when invalid_text_representation then
        raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK' using errcode='40001';
      end;
      if pg_catalog.array_position(v_legacy_root_ids,null::uuid) is not null then
        raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK' using errcode='40001';
      end if;
    end if;
    select array_agg(own_root order by own_root) into v_legacy_root_ids
    from (select distinct own_root from unnest(
      v_legacy_root_ids||array[v_timesheet.timesheet_id]::uuid[]) own_root) own_roots;
    perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set',
      pg_catalog.array_to_string(v_legacy_root_ids,','),true);
  end if;

  -- Review F5 / proof/34 rule 7: an approved decision is never silently
  -- transferred from one physical Timesheet id to another.  If the family
  -- already carries a live root authorisation on a member that is NOT the
  -- canonical row, the authorised root has rotated: refuse rather than bind a
  -- new source row to the new physical id and report success.
  v_root_authorisation:=private.weekly_source_root_authorisation_state_v1(
    (v_family->>'canonical_timesheet_id')::uuid,
    (select pg_catalog.array_agg(member.value::uuid)
     from pg_catalog.jsonb_array_elements_text(
       v_family->'member_timesheet_ids'
     ) member(value))
  );
  -- Review G8: the guard treats a missing authorisation relation as "cannot
  -- tell" and fails closed; this owner must point the same way, not bind.
  if coalesce((v_root_authorisation->>'relation_present')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',
        detail=pg_catalog.jsonb_build_object(
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
          'reason',coalesce(v_root_authorisation->>'reason',
                            'ROOT_AUTHORISATION_RELATION_MISSING')
        )::text;
  end if;
  if coalesce((v_root_authorisation->>'live_on_other_member_count')::integer,0)>0 then
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',
        detail=pg_catalog.jsonb_build_object(
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
          'reason','AUTHORISED_ROOT_NOT_CANONICAL',
          'canonical_timesheet_id',v_family->>'canonical_timesheet_id',
          'authorised_timesheet_id',
            v_root_authorisation->>'live_on_other_member_timesheet_id'
        )::text;
  end if;

  -- proof/34 section 5 step 3: a changed current id before first authorisation
  -- makes the request stale.  Write nothing and never authorise the older id.
  if coalesce((v_family->>'requested_is_canonical')::boolean,false) is not true
     or coalesce((v_family->>'family_is_current')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION'
      using errcode='55000',detail=v_family::text;
  end if;

  -- The family rows are locked now, so re-read the root under the lock before
  -- any fact derived from it is frozen into the lineage record.
  select * into strict v_timesheet
  from public.timesheets
  where timesheet_id=v_timesheet.timesheet_id;
  if v_timesheet.booking_id is distinct from (v_family->>'family_booking_id')
     or v_timesheet.version is distinct from (v_family->>'canonical_version')::integer
     or not v_timesheet.is_current then
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',detail=v_family::text;
  end if;

  -- Decision D8: this owner writes a BINDING record, never an authorisation.
  -- The row signature at authorisation, the authorisation generation and the
  -- entitlement head pointer all belong to
  -- public.weekly_source_root_authorisations, written only by the
  -- first-authorisation owner (interface I-6) after the ordinary Authorise
  -- succeeds, and marked withdrawn only by the withdrawal owner.  This owner
  -- therefore computes and stores no signature at all.

  v_contract_week_settings:=
    private.weekly_source_contract_week_settings_authority_assert_v1(v_contract_week.id);
  v_timesheet_settings:=
    private._timesheet_settings_authority_frozen_v1(v_timesheet.timesheet_id);
  if v_timesheet.settings_authority_resolved_at is null
     or (v_timesheet_settings->>'resolved_at_utc')::timestamptz is distinct from
        v_timesheet.settings_authority_resolved_at
     or v_timesheet.settings_authority_fingerprint is distinct from
        v_contract_week.settings_authority_fingerprint
     or v_timesheet_settings->>'authority_fingerprint' is distinct from
        v_contract_week_settings->>'authority_fingerprint' then
    raise exception 'WEEKLY_SOURCE_SETTINGS_AUTHORITY_NOT_FROZEN' using errcode='55000';
  end if;

  v_lineage_fingerprint:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ROW_TIMESHEET_LINEAGE_V1',
    pg_catalog.jsonb_build_object(
      'row_resolution_id',v_resolution.id,
      'source_cycle_id',v_cycle.id,
      'work_event_id',v_resolution.work_event_id,
      'candidate_id',v_resolution.candidate_id,
      'client_id',v_resolution.client_id,
      'contract_id',v_resolution.contract_id,
      'contract_week_id',v_contract_week.id,
      'timesheet_id',v_timesheet.timesheet_id,
      'week_ending_date',v_week_ending_date
    )
  );

  -- Decision D8: one binding row per resolution.  A replay is a no-op; this
  -- owner never writes an authorisation generation, and re-authorisation after
  -- a withdrawal appends a row to public.weekly_source_root_authorisations,
  -- written only by the first-authorisation owner (interface I-6).
  select exists(
    select 1 from public.weekly_source_row_timesheet_lineages lineage
    where lineage.row_resolution_id=v_resolution.id
  ) into v_existing_lineage;

  -- Decision D8: the binding record.  It carries the binding-time family
  -- identity and physical version, which stale detection needs, and no
  -- authorisation fact of any kind.
  insert into public.weekly_source_row_timesheet_lineages(
    row_resolution_id,source_cycle_id,work_event_id,candidate_id,client_id,
    contract_id,contract_week_id,timesheet_id,family_booking_id,timesheet_version,
    week_ending_date,lineage_fingerprint
  ) values (
    v_resolution.id,v_cycle.id,v_resolution.work_event_id,v_resolution.candidate_id,
    v_resolution.client_id,v_resolution.contract_id,v_contract_week.id,
    v_timesheet.timesheet_id,v_timesheet.booking_id,v_timesheet.version,
    v_week_ending_date,v_lineage_fingerprint
  ) on conflict (row_resolution_id) do nothing;

  -- Review G3 / proof/34 section 5 step 3 and section 6.  A binding that already
  -- exists on a DIFFERENT physical id means the base Timesheet rotated since it
  -- was bound.  Before first authorisation that is permitted and rotation WINS
  -- (rule 2): the request is STALE, so refuse with
  -- WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION and say that the
  -- resolution must be rebuilt at a new generation.  Only when the family
  -- carries a live authorisation record is it the section 6 integrity failure,
  -- which the assert below raises.  Without this the immutable binding would
  -- make that source row impossible to finalise ever again.
  select lineage.timesheet_id into v_bound_timesheet_id
  from public.weekly_source_row_timesheet_lineages lineage
  where lineage.row_resolution_id=v_resolution.id;
  if v_bound_timesheet_id is distinct from v_timesheet.timesheet_id then
    if coalesce((v_root_authorisation->>'live_on_canonical')::boolean,false) is not true
       and coalesce((v_root_authorisation->>'live_on_other_member_count')::integer,0)=0 then
      raise exception 'WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION'
        using errcode='55000',
          detail=pg_catalog.jsonb_build_object(
            'code','WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION',
            'reason','BOUND_ROOT_ROTATED_BEFORE_AUTHORISATION',
            'bound_timesheet_id',v_bound_timesheet_id,
            'canonical_timesheet_id',v_timesheet.timesheet_id,
            'rebuild','REBUILD_RESOLUTION_AT_A_NEW_GENERATION'
          )::text;
    end if;
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',
        detail=pg_catalog.jsonb_build_object(
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
          'reason','AUTHORISED_ROOT_ROTATED_AFTER_AUTHORISATION',
          'bound_timesheet_id',v_bound_timesheet_id,
          'canonical_timesheet_id',v_timesheet.timesheet_id
        )::text;
  end if;

  v_lineage:=private.weekly_source_timesheet_lineage_assert_v1(v_resolution.id);
  if v_lineage.lineage_fingerprint is distinct from v_lineage_fingerprint then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_LINEAGE_CONFLICT' using errcode='55000';
  end if;

  if not v_existing_lineage then
    insert into public.audit_events(
      ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,before_json,after_json,reason
    )
    select
      pg_catalog.statement_timestamp(),p_actor_user_id,actor.display_name,actor.role,
      'weekly_source_row_timesheet_lineages',v_lineage.id::text,
      'WEEKLY_SOURCE_TIMESHEET_LINEAGE_CREATED',null,
      pg_catalog.jsonb_build_object(
        'source_cycle_id',v_lineage.source_cycle_id,
        'row_resolution_id',v_lineage.row_resolution_id,
        'work_event_id',v_lineage.work_event_id,
        'contract_id',v_lineage.contract_id,
        'contract_week_id',v_lineage.contract_week_id,
        'timesheet_id',v_lineage.timesheet_id,
        'candidate_id',v_lineage.candidate_id,
        'client_id',v_lineage.client_id,
        'week_ending_date',v_lineage.week_ending_date,
        'created_timesheet',v_created_timesheet
      ),'FINAL_SOURCE_LINEAGE'
    from public.tms_users actor
    where actor.id=p_actor_user_id;

    if not found then
      raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'row_resolution_id',v_resolution.id,
    'source_cycle_id',v_cycle.id,
    'contract_week_id',v_lineage.contract_week_id,
    'timesheet_id',v_lineage.timesheet_id,
    'week_ending_date',v_lineage.week_ending_date,
    'created_timesheet',v_created_timesheet,
    'idempotent_replay',v_existing_lineage
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_LINEAGE_SCOPE_INVALID' using errcode='55000';
end;
$function$;

alter function public.weekly_source_timesheet_lineage_ensure_atomic_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_timesheet_lineage_ensure_atomic_v1(uuid,uuid) from public,anon,authenticated,service_role;
grant execute on function public.weekly_source_timesheet_lineage_ensure_atomic_v1(uuid,uuid) to service_role;

notify pgrst, 'reload schema';


-- CONTACT_PREPARER_UNIT 125 repeatable supabase/repeatable/13102026_2110_healthroster_report_native_fin_worker_v1.sql SHA256 33cbd8b9b8c31428d041cbda7e0bc1a6adcae71bce3ac584905a4d4215c36d8f
-- Complete native Report reads, internal FIN overload and upload context.
-- Operational A/B dispatch remains held pending real release-bound proof.


-- Review-only private read. Reproduce the controlling receipt owner's exact
-- domain and field set; never interpret a TSFIN status as a receipt.
create or replace function private.weekly_source_report_projection_receipt_assert_v1(
  p_receipt public.weekly_source_ordinary_pay_projection_receipts
) returns boolean language sql stable set search_path to 'pg_catalog','pg_temp'
as $function$
  select p_receipt.receipt_hash is not null
    and p_receipt.source_unit_count=jsonb_array_length(p_receipt.source_unit_outcomes_json)
    and p_receipt.source_unit_manifest_hash=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_ORDINARY_UNIT_MANIFEST_V1',p_receipt.source_unit_outcomes_json)
    and p_receipt.source_expense_manifest_hash=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_ORDINARY_SOURCE_EXPENSE_MANIFEST_V1',p_receipt.source_expense_authorities_json)
    and p_receipt.receipt_hash=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_ORDINARY_PAY_PROJECTION_RECEIPT_V1',jsonb_build_object(
        'final_revision_id',p_receipt.final_revision_id,'source_cycle_id',p_receipt.source_cycle_id,
        'client_id',p_receipt.client_id,'root_timesheet_id',p_receipt.root_timesheet_id,
        'published_timesheet_financial_id',p_receipt.published_timesheet_financial_id,
        'source_profile_kind',p_receipt.source_profile_kind,'source_mode',p_receipt.source_mode,
        'outcome',p_receipt.outcome,'source_units',p_receipt.source_unit_outcomes_json,
        'source_unit_manifest_hash',encode(p_receipt.source_unit_manifest_hash,'hex'),
        'source_expense_authorities',p_receipt.source_expense_authorities_json,
        'source_expense_manifest_hash',encode(p_receipt.source_expense_manifest_hash,'hex'),
        'final_manifest_hash',encode(p_receipt.final_manifest_hash,'hex'),
        'final_policy_fingerprint',encode(p_receipt.final_policy_fingerprint,'hex'),
        'service_snapshot_hash',encode(p_receipt.service_snapshot_hash,'hex'),
        'server_calculation_fingerprint',encode(p_receipt.server_calculation_fingerprint,'hex'),
        'root_before_hash',encode(p_receipt.root_before_hash,'hex'),
        'root_after_hash',encode(p_receipt.root_after_hash,'hex'),
        'request_hash',encode(p_receipt.request_hash,'hex'),'actor_user_id',p_receipt.actor_user_id));
$function$;

-- Review-only complete native read. The bound export is immutable permission
-- provenance; Report lines do not become pay entitlements. No row/advisory
-- locks or writer/claim/drain calls are permitted in this leaf's call graph.
create or replace function private.weekly_source_self_bill_report_pay_authority_v1(p_binding_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  b public.weekly_source_self_bill_report_line_bindings%rowtype;
  rr public.weekly_source_row_resolutions%rowtype; er public.weekly_source_upload_rows%rowtype;
  ep public.weekly_source_projection_publications%rowtype; ec public.weekly_source_cycles%rowtype;
  fr public.weekly_source_final_revisions%rowtype; fs public.weekly_source_final_snapshot_lines%rowtype;
  lineage public.weekly_source_row_timesheet_lineages%rowtype;
  receipt public.weekly_source_ordinary_pay_projection_receipts%rowtype;
  run public.weekly_source_finalisation_pay_runs%rowtype; task public.weekly_source_finalisation_pay_tasks%rowtype;
  fin public.timesheets_financials%rowtype; root public.timesheets%rowtype;
  head public.weekly_source_entitlement_heads%rowtype;
  bundle public.weekly_source_entitlement_decision_bundles%rowtype;
  publication private.weekly_source_entitlement_publication_receipts%rowtype;
  generation public.weekly_exceptional_pay_generations%rowtype;
  approval public.weekly_exceptional_payment_approvals%rowtype;
  local_receipt private.weekly_source_local_protected_decision_receipts%rowtype;
  c1_request public.weekly_exceptional_c1_publication_requests%rowtype;
  count_rows integer; witness jsonb; inventory jsonb; basis jsonb;
  current_receipt jsonb; current_event uuid; current_approval uuid; current_root uuid;
  identity jsonb; result jsonb; run_contexts jsonb; prepared_context jsonb; expected_run_hash bytea;
  native_origin jsonb; next_application jsonb; submission jsonb;
  ready boolean:=false; position text:='UNPROVED'; reason text:='NATIVE_PAY_RECEIPT_UNAVAILABLE';
  active_amount text:=null; prepared_amount text:=null; publication_fin uuid; member integer;
begin
  select * into b from public.weekly_source_self_bill_report_line_bindings where id=p_binding_id;
  if not found or b.state is distinct from 'CURRENT' then return null; end if;
  -- Accepted means the exact current Report publication, never metadata alone.
  if not exists(select 1 from public.weekly_source_upload_rows report_row
    join public.weekly_source_uploads upload on upload.id=report_row.upload_id and upload.state='CURRENT'
    join public.weekly_source_report_scopes rs on rs.current_complete_upload_id=upload.id
      and rs.id=upload.report_scope_id and rs.self_bill_report_id=b.self_bill_report_id
    join public.weekly_source_projection_publications rp on rp.id=rs.current_projection_publication_id
      and rp.upload_id=upload.id and rp.report_scope_id=rs.id and rp.authority_scope_kind='SELF_BILL_REPORT_SCOPE'
      and rp.authority_scope_version=rs.version and rp.state='CURRENT'
    where report_row.id=b.report_row_id and report_row.self_bill_report_id=b.self_bill_report_id
      and report_row.row_finalisation_state='SOURCE_REPORT_LINE') then return null; end if;
  select * into strict er from public.weekly_source_upload_rows where id=b.export_upload_row_id;
  select * into strict rr from public.weekly_source_row_resolutions where id=b.bound_row_resolution_id;
  select * into strict ep from public.weekly_source_projection_publications where id=b.export_projection_publication_id;
  select * into strict ec from public.weekly_source_cycles where id=ep.source_cycle_id;
  if er.row_finalisation_state is distinct from 'SOURCE_WORKED' or nullif(btrim(er.finalised_by),'') is null
    or rr.upload_row_id is distinct from er.id or rr.work_event_id is distinct from b.work_event_id
    or rr.mapping_state is distinct from 'RESOLVED' or rr.generation is distinct from coalesce(ep.projection_generation,ep.authority_scope_version)
    or ep.upload_id is distinct from er.upload_id or ep.authority_scope_kind is distinct from 'CYCLE'
    or ep.state is distinct from 'CURRENT' or ep.id is distinct from ec.current_projection_publication_id
    or ep.upload_id is distinct from ec.current_complete_upload_id or ep.authority_scope_version is distinct from ec.version
    or not exists(select 1 from public.weekly_source_uploads u where u.id=er.upload_id and u.state='CURRENT'
      and u.source_cycle_id=ec.id and u.report_scope_id is null)
    or not exists(select 1 from public.weekly_source_report_scopes rs where rs.self_bill_report_id=b.self_bill_report_id
      and rs.source_group_id=ec.source_group_id and rs.client_id=rr.client_id)
    then return null; end if;
  select * into fr from public.weekly_source_final_revisions where id=ec.current_final_revision_id;
  if not found or fr.state is distinct from 'CURRENT' or fr.authority_scope_kind is distinct from 'CYCLE'
    or fr.source_cycle_id is distinct from ec.id or fr.upload_id is distinct from ep.upload_id
    or fr.report_scope_id is not null then return null; end if;
  select count(*) into count_rows from public.weekly_source_final_snapshot_lines s
    where s.final_revision_id=fr.id and s.row_resolution_id=rr.id and s.upload_row_id=er.id
      and s.work_event_id=b.work_event_id and s.client_id=rr.client_id and s.contract_id=rr.contract_id;
  if count_rows=0 then return null; end if;
  if count_rows<>1 then raise exception 'WEEKLY_SOURCE_REPORT_PAY_WITNESS_AMBIGUOUS' using errcode='55000'; end if;
  select * into strict fs from public.weekly_source_final_snapshot_lines s
    where s.final_revision_id=fr.id and s.row_resolution_id=rr.id and s.upload_row_id=er.id
      and s.work_event_id=b.work_event_id and s.client_id=rr.client_id and s.contract_id=rr.contract_id;
  select count(*) into count_rows from public.weekly_source_row_timesheet_lineages l
    where l.row_resolution_id=rr.id and l.work_event_id=b.work_event_id and l.client_id=rr.client_id and l.contract_id=rr.contract_id;
  if count_rows<>1 then raise exception 'WEEKLY_SOURCE_REPORT_PAY_WITNESS_AMBIGUOUS' using errcode='55000'; end if;
  select * into strict lineage from public.weekly_source_row_timesheet_lineages l
    where l.row_resolution_id=rr.id and l.work_event_id=b.work_event_id and l.client_id=rr.client_id and l.contract_id=rr.contract_id;
  select * into strict root from public.timesheets where timesheet_id=lineage.timesheet_id;
  if root.contract_id is distinct from fs.contract_id or not exists(select 1 from public.contracts c
    where c.id=root.contract_id and c.client_id=fs.client_id and c.candidate_id=fs.candidate_id) then return null; end if;
  identity:=jsonb_build_object('bound_pay_snapshot_line_id',fs.id,'bound_pay_final_revision_id',fr.id,
    'bound_pay_projection_receipt_id',null,'published_timesheet_financial_id',null,
    'invoice_timesheet_id',lineage.timesheet_id,'candidate_id',fs.candidate_id,'client_id',fs.client_id,
    'contract_id',fs.contract_id,'work_event_id',fs.work_event_id);
  select count(*) into count_rows from public.weekly_source_ordinary_pay_projection_receipts r
    where r.final_revision_id=fr.id and r.root_timesheet_id=lineage.timesheet_id and r.client_id=fs.client_id;
  if count_rows>1 then raise exception 'WEEKLY_SOURCE_REPORT_PAY_WITNESS_AMBIGUOUS' using errcode='55000'; end if;
  if count_rows=1 then
    select * into strict receipt from public.weekly_source_ordinary_pay_projection_receipts r
      where r.final_revision_id=fr.id and r.root_timesheet_id=lineage.timesheet_id and r.client_id=fs.client_id;
    select * into run from public.weekly_source_finalisation_pay_runs r where r.final_revision_id=fr.id;
    select * into task from public.weekly_source_finalisation_pay_tasks t
      where t.run_id=run.id and t.projection_receipt_id=receipt.id;
    -- The native run is orchestration proof only. Every immutable task/context,
    -- receipt digest and run manifest must match; COMPLETE alone proves no pay.
    select coalesce(jsonb_agg(t.prepared_context_json||jsonb_build_object(
      'prepared_context_hash',encode(t.prepared_context_hash,'hex')) order by t.root_timesheet_id),'[]'::jsonb)
      into run_contexts from public.weekly_source_finalisation_pay_tasks t where t.run_id=run.id;
    expected_run_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_FINALISATION_PAY_RUN_V1',jsonb_build_object(
      'final_revision_id',run.final_revision_id,'source_cycle_id',run.source_cycle_id,
      'requested_by_user_id',run.requested_by_user_id,'final_revision_manifest_hash',encode(run.final_revision_manifest_hash,'hex'),
      'task_manifest_hash',encode(run.task_manifest_hash,'hex'),'task_count',run.task_count));
    prepared_context:=task.prepared_context_json;
    if private.weekly_source_report_projection_receipt_assert_v1(receipt) is distinct from true
      or receipt.final_manifest_hash is distinct from fr.manifest_hash or receipt.final_policy_fingerprint is distinct from fr.policy_fingerprint
      or run.id is null or run.source_cycle_id is distinct from ec.id or run.state is distinct from 'COMPLETE'
      or run.completed_at_utc is null or not isfinite(run.completed_at_utc)
      or run.final_revision_manifest_hash is distinct from fr.manifest_hash or run.run_hash is distinct from expected_run_hash
      or run.task_count<1 or run.task_count is distinct from jsonb_array_length(run_contexts)
      or run.terminal_task_count is distinct from run.task_count or run.action_required_task_count is distinct from 0
      or run.task_manifest_hash is distinct from private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_FINALISATION_PAY_TASK_MANIFEST_V1',run_contexts)
      or exists(select 1 from public.weekly_source_finalisation_pay_tasks t where t.run_id=run.id and
        (t.state not in ('PREPARED_FOR_AUTHORISATION','PROPOSED','NO_OP_FIRST_NEGATIVE','TARGET_MANAGED_SUPPRESSED')
          or t.completed_at_utc is null or not isfinite(t.completed_at_utc)))
      or task.id is null or task.state is distinct from receipt.outcome or task.root_timesheet_id is distinct from lineage.timesheet_id
      or task.root_family_booking_id is distinct from root.booking_id or task.projection_idempotency_key is distinct from receipt.idempotency_key
      or receipt.actor_user_id is distinct from run.requested_by_user_id
      or task.prepared_context_hash is distinct from private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_FINALISATION_PAY_ROOT_CONTEXT_V1',prepared_context)
      or prepared_context->>'schema_version' is distinct from 'WEEKLY_SOURCE_FINALISATION_PAY_ROOT_CONTEXT_V1'
      or prepared_context->>'final_revision_id' is distinct from fr.id::text
      or prepared_context->>'source_cycle_id' is distinct from ec.id::text
      or prepared_context->>'client_id' is distinct from fs.client_id::text
      or prepared_context->>'root_timesheet_id' is distinct from lineage.timesheet_id::text
      or not exists(select 1 from public.weekly_source_client_manifests m where m.id=task.client_manifest_id
        and m.id::text=prepared_context->>'client_manifest_id' and m.final_revision_id=fr.id and m.client_id=fs.client_id
        and coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id
        and encode(m.manifest_hash,'hex')=prepared_context#>>'{expected_rate_source_refs,client_manifest_hash}')
      or prepared_context#>>'{expected_rate_source_refs,final_manifest_hash}' is distinct from encode(fr.manifest_hash,'hex')
      or prepared_context#>>'{expected_rate_source_refs,source_unit_manifest_hash}' is distinct from encode(receipt.source_unit_manifest_hash,'hex')
      or prepared_context#>>'{expected_rate_source_refs,source_expense_manifest_hash}' is distinct from encode(receipt.source_expense_manifest_hash,'hex')
      then reason:='NATIVE_PAY_ORCHESTRATION_UNPROVED';
    else
      identity:=identity||jsonb_build_object('bound_pay_projection_receipt_id',receipt.id);
      if receipt.outcome='PREPARED_FOR_AUTHORISATION' then
        select * into fin from public.timesheets_financials where id=receipt.published_timesheet_financial_id;
        if fin.id is not null and fin.timesheet_id=lineage.timesheet_id and fin.candidate_id=fs.candidate_id
          and fin.client_id=fs.client_id and fin.timesheet_version=task.root_timesheet_version then
          ready:=true; position:='PREPARED_FOR_AUTHORISATION'; reason:=null; publication_fin:=fin.id;
          -- Native receipt seals the submitted service snapshot, not an
          -- immutable retained copy of this mutable financial row's amount.
          -- Preserve historical writer identity/invoice provenance, but leave
          -- saved prepared amount unknown without exact retained output proof.
          -- Active amount is available only through the existing approved
          -- inventory certificate; a prepared unsigned row does not fake zero.
          inventory:=private.weekly_source_effective_inventory_v1(lineage.timesheet_id);
          basis:=inventory->'approval_basis';
          if basis->'coverage_complete'='true'::jsonb then active_amount:=basis->>'approved_pay_ex_vat'; end if;
        else reason:='NATIVE_PREPARED_WRITER_IDENTITY_UNPROVED'; end if;
      elsif receipt.outcome='PROPOSED' then
        inventory:=private.weekly_source_effective_inventory_v1(lineage.timesheet_id); basis:=inventory->'approval_basis';
        if basis->'coverage_complete'='true'::jsonb then active_amount:=basis->>'approved_pay_ex_vat'; end if;
        if basis->'coverage_complete'='true'::jsonb and inventory->>'authority'='HEAD' then
          select * into head from public.weekly_source_entitlement_heads where id=(inventory->>'head_id')::uuid;
          select * into bundle from public.weekly_source_entitlement_decision_bundles d
            where d.decision_bundle_id=head.decision_bundle_id and d.bundle_revision=head.bundle_revision;
          select count(*) into count_rows from private.weekly_source_entitlement_publication_receipts p
            where p.decision_bundle_id=head.decision_bundle_id and p.bundle_revision=head.bundle_revision and p.request_digest=bundle.request_digest;
          if count_rows=1 then
            select * into strict publication from private.weekly_source_entitlement_publication_receipts p
              where p.decision_bundle_id=head.decision_bundle_id and p.bundle_revision=head.bundle_revision and p.request_digest=bundle.request_digest;
            member:=array_position(publication.head_ids,head.id);
            native_origin:=head.source_origin_json;
            if bundle.state='COMMITTED' and bundle.bundle_kind='SINGLE_ROOT' and cardinality(publication.head_ids)=1
              and member=1 and publication.member_root_ids[member]=lineage.timesheet_id
              and publication.member_family_booking_ids[member]=root.booking_id
              and publication.member_root_versions[member]=head.root_timesheet_version
              and publication.candidate_id=fs.candidate_id and head.authority_kind='LOCKED_FINAL_SOURCE'
              and native_origin->>'final_revision_id'=fr.id::text and native_origin->>'source_cycle_id'=ec.id::text
              and native_origin->>'revision_number'=fr.revision_number::text
              and native_origin->>'manifest_hash'=encode(fr.manifest_hash,'hex')
              and native_origin->>'policy_fingerprint'=encode(fr.policy_fingerprint,'hex')
              and head.source_generation_digest=private.weekly_source_publication_request_digest_v1(native_origin)
              and bundle.source_revision_digest=head.source_generation_digest
              and head.decision_bundle_id=private.weekly_source_entitlement_derived_uuid_v1(
                'WEEKLY_SOURCE_DECISION_BUNDLE_V1',btrim(root.booking_id)||'|'||fr.id::text) then
              ready:=true; position:='PUBLISHED_SOURCE_HEAD'; reason:=null; active_amount:=basis->>'approved_pay_ex_vat';
            end if;
          end if;
        end if;
        if not ready then position:='PROPOSED'; reason:='PROPOSED_SOURCE_NOT_PUBLISHED'; end if;
      end if;
      if not ready and receipt.outcome in ('PROPOSED','TARGET_MANAGED_SUPPRESSED') then
        witness:=private.weekly_source_protected_wait_witness_v1(b.work_event_id,ec.id);
        if witness is not null and exists(select 1 from public.timesheets t
          where t.timesheet_id=(witness->>'root_timesheet_id')::uuid and t.booking_id=root.booking_id
            and t.contract_id=root.contract_id and t.week_ending_date=root.week_ending_date
            and t.sheet_scope='WEEKLY' and t.line_type='HOURS' and t.is_adjustment is false) then
          current_root:=(witness->>'root_timesheet_id')::uuid;
          select * into strict generation from public.weekly_exceptional_pay_generations where id=(witness->>'current_generation_id')::uuid;
          -- Qualify the CURRENT vector's own native financial publication too;
          -- an accepted old sibling WAIT cannot manufacture current authority.
          select count(*),(array_agg(t.approval_id))[1] into count_rows,current_approval
            from public.weekly_exceptional_pay_target_events t where t.family_id=(witness->>'family_id')::uuid
              and t.financial_generation_id=generation.id;
          if count_rows=1 then
            select * into strict approval from public.weekly_exceptional_payment_approvals where id=current_approval;
            select count(*),(array_agg(e.id))[1] into count_rows,current_event
              from public.weekly_exceptional_pay_family_events e where e.family_id=approval.pay_target_family_id
                and e.durable_work_event_id=approval.work_event_id and e.evidence_approval_id=approval.id and e.state='WAIT'
                and not exists(select 1 from public.weekly_exceptional_pay_family_events n where n.family_id=e.family_id
                  and n.durable_work_event_id=e.durable_work_event_id and n.event_sequence>e.event_sequence);
            if count_rows=1 then current_receipt:=private.weekly_source_protected_wait_receipt_v1(current_root,current_event)->'accepted_receipt'; end if;
          end if;
          if current_receipt->>'receipt_state' in ('COMPLETE','PUBLISHED')
            and current_receipt->>'generation_id'=generation.id::text
            and approval.candidate_id=fs.candidate_id and approval.client_id=fs.client_id and approval.contract_id=fs.contract_id then
            if current_receipt->>'lane'='SOURCE_LOCAL' then
              select * into local_receipt from private.weekly_source_local_protected_decision_receipts l
                where l.generation_id=generation.id and l.publication_request_id=(current_receipt->>'publication_request_id')::uuid;
              inventory:=private.weekly_source_effective_inventory_v1(current_root); basis:=inventory->'approval_basis';
              if basis->'coverage_complete'='true'::jsonb and basis#>>'{scope,candidate_id}'=fs.candidate_id::text
                and basis#>>'{scope,client_id}'=fs.client_id::text and basis#>>'{scope,contract_id}'=fs.contract_id::text then
                if local_receipt.result_json->>'authority'='COMMON_ENTITLEMENT_HEAD'
                  and basis#>>'{origin,source_revision,generation_id}'=generation.id::text
                  and basis#>>'{origin,source_revision,publication_request_id}'=local_receipt.publication_request_id::text then
                  ready:=true; position:='LOCAL_PUBLISHED_SOURCE_HEAD'; active_amount:=basis->>'approved_pay_ex_vat';
                elsif local_receipt.result_json->>'authority'='UNAUTHORISED_TSFIN'
                  and basis#>>'{origin,financial_snapshot_id}'=local_receipt.result_json->>'timesheet_financials_id' then
                  ready:=true; position:='LOCAL_FIRST_AUTHORISED'; active_amount:=basis->>'approved_pay_ex_vat';
                  publication_fin:=(basis#>>'{origin,financial_snapshot_id}')::uuid;
                end if;
              end if;
            elsif current_receipt->>'lane'='RETAINED_C1' then
              -- The unchanged full native helper proves actual PUBLISH/checkpoint
              -- and COMPLETE_C1_PUBLICATION, not a guessed current TF status.
              select * into c1_request from public.weekly_exceptional_c1_publication_requests
                where id=(current_receipt->>'publication_request_id')::uuid and generation_id=generation.id;
              if c1_request.state='PUBLISHED' and c1_request.financial_row_id is not null then
                ready:=true; position:='RETAINED_C1_PUBLISHED'; publication_fin:=c1_request.financial_row_id;
                -- No active Banking amount is inferred from C1 acceptance.
              end if;
            elsif current_receipt->>'lane'='DIRECT_NEXT' then
              -- Full unchanged Direct NEXT receipt joins approval/sealed WORK/
              -- revision/command/publication/COMPLETE native step. This is
              -- accepted invoice provenance; it makes no settlement claim.
              ready:=true; position:='DIRECT_NEXT_PUBLISHED';
              -- The controlling I3 currently excludes headless PROTECTED origins.
              -- Do not replace that named admission with a status-only shortcut.
              next_application:=private.bpay_next_source_origin_state_v1(
                (current_receipt->>'work_id')::uuid,(current_receipt->>'revision_id')::uuid);
            end if;
          end if;
          if ready then reason:=null; else reason:='PROTECTED_EFFECTIVE_PUBLICATION_UNPROVED'; end if;
        else reason:='PROTECTED_WAIT_NOT_QUALIFIED'; end if;
      elsif receipt.outcome not in ('PREPARED_FOR_AUTHORISATION','PROPOSED','TARGET_MANAGED_SUPPRESSED') then
        reason:='NATIVE_PAY_OUTCOME_NOT_INVOICE_READY';
      end if;
    end if;
  end if;
  submission:=private.weekly_source_actual_timesheet_submission_v1(lineage.timesheet_id);
  result:=identity||jsonb_build_object('published_timesheet_financial_id',publication_fin,
    'schema_version','WEEKLY_SOURCE_REPORT_PAY_AUTHORITY_V1','binding_id',b.id,
    'bound_row_resolution_id',rr.id,'bound_export_projection_publication_id',ep.id,
    'invoice_ready',ready,'native_pay_position',position,'unavailable_reason',reason,
    'native_projection_receipt_hash',encode(receipt.receipt_hash,'hex'),
    'native_pay_run_id',run.id,'native_pay_task_id',task.id,
    'approved_inventory_basis',basis,'qualified_wait',witness,'current_publication_receipt',current_receipt,
    'next_application',next_application,'actual_submission',submission,
    'prepared_pay_ex_vat',prepared_amount,'prepared_amount_known',false,
    'prepared_amount_unavailable_reason',case when position='PREPARED_FOR_AUTHORISATION'
      then 'NATIVE_PREPARED_AMOUNT_RETENTION_UNPROVED' else null end,
    'active_pay_ex_vat',active_amount,'active_amount_scope','ROOT_FAMILY',
    'withheld_pay_ex_vat',null,'withheld_amount_known',false);
  return result||jsonb_build_object('authority_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_REPORT_PAY_AUTHORITY_V1',result),'hex'));
exception when no_data_found or too_many_rows or invalid_text_representation or numeric_value_out_of_range then
  raise exception 'WEEKLY_SOURCE_REPORT_PAY_WITNESS_UNAVAILABLE' using errcode='55000';
end;
$function$;

-- Complete successor: retain the invoice producer's compact old DTO keys.
-- The detailed authority is separate; bound_* provenance never implies pay.
create or replace function private.weekly_source_self_bill_report_pay_witness_v1(p_binding_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare a jsonb;
begin
  a:=private.weekly_source_self_bill_report_pay_authority_v1(p_binding_id);
  if a is null or a->'invoice_ready' is distinct from 'true'::jsonb then return null; end if;
  return jsonb_build_object('bound_pay_snapshot_line_id',a->'bound_pay_snapshot_line_id',
    'bound_pay_final_revision_id',a->'bound_pay_final_revision_id',
    'bound_pay_projection_receipt_id',a->'bound_pay_projection_receipt_id',
    'published_timesheet_financial_id',a->'published_timesheet_financial_id',
    'invoice_timesheet_id',a->'invoice_timesheet_id','candidate_id',a->'candidate_id',
    'client_id',a->'client_id','contract_id',a->'contract_id','work_event_id',a->'work_event_id');
end;
$function$;

-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function private.weekly_source_finalise_engine_v1(
  p_request jsonb,
  p_correction_session_id uuid,
  p_prepare_only boolean,
  p_report_vat_rounding_variant text
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_allowed_keys constant text[]:=array[
    'actor_user_id','source_cycle_id','authority_scope_kind','report_scope_id',
    'upload_id','projection_publication_id','expected_authority_scope_version',
    'expected_row_manifest_hash','expected_comparison_manifest_hash',
    'expected_issue_set_hash','exclude_unfinalised_acknowledged'
  ]::text[];
  v_unknown_key text;
  v_actor uuid;
  v_cycle_id uuid;
  v_scope_kind text;
  v_report_scope_id uuid;
  v_upload_id uuid;
  v_publication_id uuid;
  v_scope_version bigint;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_existing_revision public.weekly_source_final_revisions%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_guard jsonb;
  v_client_id uuid;
  v_resolved_client_id uuid;
  v_resolved_client_count integer;
  v_source_profile_kind text;
  v_source_mode text;
  v_generation integer;
  v_coverage_start date;
  v_coverage_end date;
  v_prior_revision_id uuid;
  v_revision_number integer;
  v_revision_id uuid;
  v_revision_manifest_hash bytea;
  v_policy_fingerprint bytea;
  v_finalised_at timestamptz:=pg_catalog.transaction_timestamp();
  v_row record;
  v_finalisation_root_ids uuid[];
  v_finalisation_root_recheck uuid[];
  v_finalisation_lock_result jsonb;
  v_lock_phase integer;
  v_lock_discovery jsonb;
  v_window_discovery jsonb; v_window_observed jsonb; v_window_lock record;
  v_invoice_window_ids uuid[]; v_round_scope record; v_round_id uuid;
  v_lock_observed jsonb;
  v_finalisation_lock_context boolean:=false;
  v_next_source_hooks boolean:=false;
  v_finalisation_lock_operation uuid;
  v_prior_finalisation_lock_operation text;
  v_prior_finalisation_root_set text;
  v_economic_id uuid;
  v_timesheet_id uuid;
  v_economic public.weekly_source_row_economic_snapshots%rowtype;
  v_snapshot_id uuid;
  v_snapshot_hash bytea;
  v_mapping_fingerprint bytea;
  v_pay_vector jsonb;
  v_charge_vector jsonb;
  v_transition record;
  v_prior_snapshot public.weekly_source_final_snapshot_lines%rowtype;
  v_current_snapshot public.weekly_source_final_snapshot_lines%rowtype;
  v_prior_state bytea;
  v_current_state bytea;
  v_outcome text;
  v_transition_id uuid;
  v_transition_fingerprint bytea;
  v_prior_movement public.weekly_source_billing_movements%rowtype;
  v_correction_unit_id uuid;
  v_charge_check public.weekly_source_charge_checks%rowtype;
  v_charge_acceptance public.weekly_source_charge_acceptances%rowtype;
  v_price_admission_result text;
  v_movement_id uuid;
  v_backing_report_number text;
  v_source_total_cost bigint;
  v_source_commission bigint;
  v_source_invoice_total bigint;
  v_line_count integer;
  v_manifest record;
  v_client_manifest_id uuid;
  v_client_manifest_hash bytea;
  v_completion_generation integer;
  v_completion_hash bytea;
  v_expense_observation record;
  v_target_expense_pence bigint;
  v_target_expense_vat boolean;
  v_target_expense_contract_id uuid;
  v_expense_observation_kind text;
  v_current_expense public.weekly_expense_authority_generations%rowtype;
  v_expense_policy public.weekly_source_row_expense_policy_snapshots%rowtype;
  v_expense_generation integer;
  v_expense_hash bytea;
  v_expense_authority_id uuid;
  v_prior_expense_authority_id uuid;
  v_expense_timesheet_id uuid;
  v_expense_policy_id uuid;
  v_expense_movement_result jsonb;
  v_rule_set jsonb;
  v_rule_values jsonb;
  v_rule_version uuid;
  v_invoice_amounts jsonb;
  v_invoice_correction jsonb;
  v_effective_policy jsonb;
  v_authority_subset jsonb;
  v_prior_authority_subset jsonb;
  v_current_authority_subset jsonb;
  v_comparison_current_authority jsonb;
  v_correction_presentation text;
  v_movement_count integer:=0;
  v_transition_count integer:=0;
  v_snapshot_count integer:=0;
  v_unchanged_count integer:=0;
  v_expense_generation_count integer:=0;
begin
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_prepare_only is null
     or (p_prepare_only and p_correction_session_id is null)
     or (not p_prepare_only and p_correction_session_id is not null) then
    raise exception 'WEEKLY_SOURCE_FINALISE_EXECUTION_MODE_INVALID' using errcode='22023';
  end if;
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_FINALISE_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown_key
  from pg_catalog.jsonb_object_keys(p_request) key
  where not (key=any(v_allowed_keys))
  order by key limit 1;
  if v_unknown_key is not null then
    raise exception 'WEEKLY_SOURCE_FINALISE_REQUEST_UNKNOWN_FIELD'
      using errcode='22023',detail=v_unknown_key;
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_scope_kind:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'authority_scope_kind','')));
    v_report_scope_id:=nullif(p_request->>'report_scope_id','')::uuid;
    v_upload_id:=(p_request->>'upload_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
    v_scope_version:=(p_request->>'expected_authority_scope_version')::bigint;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'WEEKLY_SOURCE_FINALISE_REQUEST_INVALID' using errcode='22023';
  end;
  if v_actor is null or v_cycle_id is null or v_upload_id is null
     or v_publication_id is null or v_scope_version is null or v_scope_version<1
     or v_scope_kind not in ('CYCLE','NHSP_REPORT_SCOPE','SELF_BILL_REPORT_SCOPE')
     or (v_scope_kind in ('NHSP_REPORT_SCOPE','SELF_BILL_REPORT_SCOPE')) is distinct from (v_report_scope_id is not null) then
    raise exception 'WEEKLY_SOURCE_FINALISE_SCOPE_INVALID' using errcode='22023';
  end if;
  v_expected_row_hash:=private.weekly_source_finalisation_hex32_v1(
    p_request->>'expected_row_manifest_hash','WEEKLY_SOURCE_ROW_MANIFEST_HASH_REQUIRED'
  );
  v_expected_comparison_hash:=private.weekly_source_finalisation_hex32_v1(
    p_request->>'expected_comparison_manifest_hash','WEEKLY_SOURCE_COMPARISON_HASH_REQUIRED'
  );
  v_expected_issue_hash:=private.weekly_source_finalisation_hex32_v1(
    p_request->>'expected_issue_set_hash','WEEKLY_SOURCE_ISSUE_HASH_REQUIRED'
  );

  -- Fresh Final admission precedes the first cycle/business lock. Recursive
  -- lineage/current-publication owners inherit this transaction's admission.
  perform private.weekly_source_pay_query_admit_v2();

  -- Internal Report delegate only AFTER unchanged payload/ID/hash/admission.
  -- This arm writes invoice-only Report authority and acquires no I-1 family
  -- locks. The native complete ordinary lock ladder below is unchanged.
  if v_scope_kind='SELF_BILL_REPORT_SCOPE' then
    select * into v_scope from public.weekly_source_report_scopes where id=v_report_scope_id;
    select * into v_cycle from public.weekly_source_cycles where id=v_cycle_id;
    if v_scope.id is null or v_cycle.id is null or v_scope.self_bill_report_id is null
      or v_scope.source_cycle_id is distinct from v_cycle.id
      or v_scope.source_group_id is distinct from v_cycle.source_group_id then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_MISMATCH' using errcode='22023'; end if;
    perform private.weekly_source_office_authority_v1(v_actor,
      case when p_prepare_only then 'CORRECT_FINAL_SOURCE' else 'FINALISE_WEEK' end,
      v_cycle.source_group_id,v_scope.client_id,v_cycle.finalisation_week_ending);
    if p_prepare_only or p_correction_session_id is not null then
      raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000'; end if;
    -- NULL is a held operational variant, never an implicit A choice.
    return private.weekly_source_self_bill_report_finalise_v1(p_request,p_report_vat_rounding_variant);
  end if;

  -- G1 plain scope discovery -> native complete I-1 -> group -> cycle.
  -- Repeat the same guards under locks; changed source/rules/roots retry before any mutation.
  for v_lock_phase in 1..2 loop
  if v_lock_phase=2 then
    -- Use the discovered exact group, never a fresh group chosen after I-1.
    select * into v_group from public.weekly_source_groups
    where id=(v_lock_discovery#>>'{group,id}')::uuid for update;
    if not found or to_jsonb(v_group) is distinct from v_lock_discovery->'group' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
    -- Complete source + candidate invoice windows were discovered BEFORE I-1.
    -- Take every cycle in UUID order, then compare full original row witnesses.
    for v_window_lock in select cycle.* from public.weekly_source_cycles cycle
      where cycle.id=any(v_invoice_window_ids) order by cycle.id for update
    loop
      if to_jsonb(v_window_lock) is distinct from v_window_discovery->'cycles'->v_window_lock.id::text then
        raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SET_CHANGED_DURING_LOCK' using errcode='40001'; end if;
    end loop;
    if (select count(*) from public.weekly_source_cycles cycle where cycle.id=any(v_invoice_window_ids))<>cardinality(v_invoice_window_ids) then
      raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SET_CHANGED_DURING_LOCK' using errcode='40001'; end if;
    select * into v_cycle from public.weekly_source_cycles where id=v_cycle_id;
    if not found or to_jsonb(v_cycle) is distinct from v_lock_discovery->'cycle' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
    select * into v_cycle from public.weekly_source_cycles where id=v_cycle_id;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select * into strict v_group
  from public.weekly_source_groups where id=v_cycle.source_group_id;
  if v_scope_kind='NHSP_REPORT_SCOPE' then
  if v_lock_phase=2 then
    select * into v_scope from public.weekly_source_report_scopes where id=v_report_scope_id for update;
    if not found or to_jsonb(v_scope) is distinct from v_lock_discovery->'scope' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
    select * into v_scope from public.weekly_source_report_scopes where id=v_report_scope_id;
  end if;
    if not found or v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id
       or v_scope.environment is distinct from v_group.environment
       or v_scope.agency_id is distinct from v_group.agency_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_MISMATCH' using errcode='22023';
    end if;
  end if;
  if v_lock_phase=2 then
    select * into v_upload from public.weekly_source_uploads where id=v_upload_id for share;
    if not found or to_jsonb(v_upload) is distinct from v_lock_discovery->'upload' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
    select * into v_upload from public.weekly_source_uploads where id=v_upload_id;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_UPLOAD_NOT_FOUND' using errcode='22023';
  end if;
  if v_lock_phase=2 then
    select * into v_publication from public.weekly_source_projection_publications where id=v_publication_id for share;
    if not found or to_jsonb(v_publication) is distinct from v_lock_discovery->'publication' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
    select * into strict v_publication from public.weekly_source_projection_publications where id=v_publication_id;
  end if;
  select * into strict v_profile
  from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;
  if v_lock_phase=2 and to_jsonb(v_profile) is distinct from v_lock_discovery->'profile' then
    raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;

  if p_prepare_only then
  if v_lock_phase=2 then
    select * into v_correction from public.weekly_final_source_correction_sessions where id=p_correction_session_id for share;
    if not found or to_jsonb(v_correction) is distinct from v_lock_discovery->'correction' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
    select * into v_correction from public.weekly_final_source_correction_sessions where id=p_correction_session_id;
  end if;
    if not found or v_correction.state<>'PREPARING'
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from v_scope_kind
       or v_correction.report_scope_id is distinct from v_report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.replacement_projection_publication_id is distinct from v_publication.id
       or v_upload.purpose<>'FINAL_SOURCE_CORRECTION'
       or v_upload.correction_session_id is distinct from v_correction.id
       or v_upload.state<>'CORRECTION_READY'
       or v_publication.state<>'CORRECTION_READY'
       or v_publication.correction_session_id is distinct from v_correction.id
       or v_publication.upload_id is distinct from v_upload.id
       or v_publication.authority_scope_version is distinct from v_scope_version then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
    end if;
    v_guard:=pg_catalog.jsonb_build_object(
      'row_manifest_hash',pg_catalog.encode(v_upload.row_manifest_hash,'hex'),
      'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
      'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex')
    );
  else
    v_guard:=private.weekly_source_current_publication_guard_v1(
      v_cycle.id,v_scope_kind,v_report_scope_id,v_upload.id,v_publication.id,v_scope_version
    );
  end if;
  if private.weekly_source_finalisation_hex32_v1(
       v_guard->>'row_manifest_hash','WEEKLY_SOURCE_GUARD_ROW_HASH_INVALID'
     ) is distinct from v_expected_row_hash
     or private.weekly_source_finalisation_hex32_v1(
       v_guard->>'comparison_manifest_hash','WEEKLY_SOURCE_GUARD_COMPARISON_HASH_INVALID'
     ) is distinct from v_expected_comparison_hash
     or private.weekly_source_finalisation_hex32_v1(
       v_guard->>'issue_set_hash','WEEKLY_SOURCE_GUARD_ISSUE_HASH_INVALID'
     ) is distinct from v_expected_issue_hash then
    raise exception 'WEEKLY_SOURCE_FINALISE_PREVIEW_CHANGED' using errcode='40001';
  end if;

  v_client_id:=case when v_scope_kind='NHSP_REPORT_SCOPE' then v_scope.client_id
    else nullif(v_upload.file_metadata_json->>'client_id','')::uuid end;
  perform private.weekly_source_office_authority_v1(
    v_actor,case when p_prepare_only then 'CORRECT_FINAL_SOURCE' else 'FINALISE_WEEK' end,
    v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  if p_correction_session_id is null then
    if v_upload.purpose<>'ORDINARY' or v_upload.correction_session_id is not null then
      raise exception 'WEEKLY_SOURCE_CORRECTION_REQUIRES_DEDICATED_OWNER' using errcode='55000';
    end if;
  else
    if v_correction.id is null or v_correction.state<>'PREPARING'
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from v_scope_kind
       or v_correction.report_scope_id is distinct from v_report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.replacement_projection_publication_id is distinct from v_publication.id
       or v_upload.purpose<>'FINAL_SOURCE_CORRECTION'
       or v_upload.correction_session_id is distinct from v_correction.id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
    end if;
  end if;
  perform private.weekly_source_final_upload_assert_v1(v_upload.id);
  if not private.weekly_source_import_is_prepared_v1(v_upload.id) then
    raise exception 'WEEKLY_SOURCE_CHECKING_FILE_NOT_FINALISABLE' using errcode='55000';
  end if;
  if v_profile.profile_code in ('HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1','HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1')
    and exists(select 1 from public.weekly_source_upload_rows source_row
      where source_row.upload_id=v_upload.id and source_row.row_finalisation_state='SOURCE_UNFINALISED')
    and p_request->'exclude_unfinalised_acknowledged' is distinct from 'true'::jsonb then
    raise exception 'WEEKLY_SOURCE_UNFINALISED_EXCLUSION_ACKNOWLEDGEMENT_REQUIRED' using errcode='55000';
  end if;
  if v_finalised_at<coalesce(v_scope.cutoff_at_utc,v_cycle.cutoff_at_utc)
    and v_profile.profile_code not in ('HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1','HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1') then
    raise exception 'WEEKLY_SOURCE_CUTOFF_NOT_REACHED' using errcode='55000';
  end if;

  if v_upload.state<>(case when p_prepare_only then 'CORRECTION_READY' else 'CURRENT' end)
     or v_upload.row_manifest_hash is null
     or v_upload.blocked_count<>0 or v_upload.blocking_economic_duplicate_count<>0
     or v_upload.malformed_count<>0
     or v_upload.physical_row_count<>
       v_upload.header_count+v_upload.trailer_count+v_upload.continuation_count+
       v_upload.accepted_count+v_upload.blocking_economic_duplicate_count+v_upload.malformed_count
     or (select pg_catalog.count(*) from public.weekly_source_upload_rows
         where upload_id=v_upload.id)<>v_upload.accepted_count then
    raise exception 'WEEKLY_SOURCE_UPLOAD_NOT_FINALISABLE' using errcode='55000';
  end if;
  -- WP-54, pack 03 section 7: "Overlapping candidate work events are checked
  -- BEFORE FINALISATION.  The system does not assume two overlapping records
  -- are valid because their references differ."  The same guard runs at the
  -- seal, where a refused report never becomes CURRENT.  It runs again here
  -- because this is the owner the pack names and because the rows this engine
  -- is about to turn into movements are the rows that must satisfy it -- pack
  -- 14 section 8.1, the database decides source authority, never the browser.
  -- Deliberately NOT accompanied by a cutoff re-check: NHSP-BR-006 governs the
  -- cutoff occurrence Office confirms when the report is accepted, and the
  -- seal is where that confirmation is made authoritative.
  perform private.weekly_source_overlap_admission_assert_v1(v_upload.id);
  if v_scope_version>2147483647
     or coalesce(v_publication.projection_generation,0)>2147483647 then
    raise exception 'WEEKLY_SOURCE_GENERATION_OVERFLOW' using errcode='22003';
  end if;
  v_generation:=coalesce(
    v_publication.projection_generation,
    v_scope_version::integer
  );
  if (select pg_catalog.count(*)
      from public.weekly_source_row_resolutions resolution
      join public.weekly_source_upload_rows source_row on source_row.id=resolution.upload_row_id
      where source_row.upload_id=v_upload.id and resolution.generation=v_generation)
       <>v_upload.accepted_count
     or exists(
       select 1
       from public.weekly_source_upload_rows source_row
       left join public.weekly_source_row_resolutions resolution
         on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
       where source_row.upload_id=v_upload.id
         and (resolution.id is null or resolution.mapping_state<>'RESOLVED')
     )
     or (v_profile.final_authority_kind<>'NHSP_TRUST_BACKING_REPORT' and exists(
       select 1
       from public.weekly_source_row_resolutions resolution
       join public.weekly_source_upload_rows source_row on source_row.id=resolution.upload_row_id
       where source_row.upload_id=v_upload.id and resolution.generation=v_generation
       group by resolution.work_event_id having pg_catalog.count(*)<>1
     )) then
    raise exception 'WEEKLY_SOURCE_RESOLUTION_CENSUS_NOT_FINALISABLE' using errcode='55000';
  end if;
  if v_scope_kind='CYCLE' then
    select pg_catalog.count(distinct resolution.client_id)::integer,
           pg_catalog.min(resolution.client_id::text)::uuid
    into v_resolved_client_count,v_resolved_client_id
    from public.weekly_source_row_resolutions resolution
    join public.weekly_source_upload_rows source_row on source_row.id=resolution.upload_row_id
    where source_row.upload_id=v_upload.id and resolution.generation=v_generation;
    if v_resolved_client_count>1 then
      raise exception 'WEEKLY_SOURCE_SINGLE_CLIENT_RESOLUTION_REQUIRED' using errcode='55000';
    end if;
    if v_resolved_client_count=1 and v_client_id is not null
       and v_client_id is distinct from v_resolved_client_id then
      raise exception 'WEEKLY_SOURCE_UPLOAD_CLIENT_MISMATCH' using errcode='55000';
    end if;
    v_client_id:=coalesce(v_resolved_client_id,v_client_id);
    if v_cycle.scope_client_id is not null and v_cycle.scope_client_id is distinct from v_client_id then
      raise exception 'WEEKLY_SOURCE_FINAL_CLIENT_SCOPE_REQUIRED' using errcode='55000';
    end if;
    if v_client_id is null or not exists(
      select 1
      from public.weekly_source_group_clients group_client
      where group_client.source_group_id=v_group.id
        and group_client.client_id=v_client_id
        and v_cycle.finalisation_week_ending between group_client.valid_from
          and coalesce(group_client.valid_to,'infinity'::date)
    ) then
      raise exception 'WEEKLY_SOURCE_FINAL_CLIENT_SCOPE_REQUIRED' using errcode='55000';
    end if;
    perform private.weekly_source_office_authority_v1(
      v_actor,case when p_prepare_only then 'CORRECT_FINAL_SOURCE' else 'FINALISE_WEEK' end,
      v_group.id,v_client_id,v_cycle.finalisation_week_ending
    );
  elsif not exists(
    select 1
    from public.weekly_source_group_clients group_client
    where group_client.source_group_id=v_group.id
      and group_client.client_id=v_client_id
      and v_cycle.finalisation_week_ending between group_client.valid_from
        and coalesce(group_client.valid_to,'infinity'::date)
  ) then
    raise exception 'WEEKLY_SOURCE_FINAL_CLIENT_SCOPE_REQUIRED' using errcode='55000';
  end if;

  v_rule_set:=private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle.id);
  v_rule_values:=v_rule_set->'values'; v_rule_version:=nullif(v_rule_set->>'rule_set_version_id','')::uuid;
  v_source_profile_kind:=v_profile.final_authority_kind;
  if v_profile.profile_code='NHSP_FINAL_BACKING_V1' then
    if v_scope_kind<>'NHSP_REPORT_SCOPE' or v_group.source_family<>'NHSP'
       or v_source_profile_kind<>'NHSP_TRUST_BACKING_REPORT'
       or v_profile.omission_meaning<>'NO_INFERENCE'
       or not v_profile.report_number_required or not v_profile.fmc_must_equal_zero
       or v_client_id is null
       or exists(select 1 from public.weekly_source_upload_rows source_row
         where source_row.upload_id=v_upload.id
           and (source_row.row_finalisation_state not in ('NOT_APPLICABLE','SOURCE_WORKED')
              or source_row.source_money_parse_state<>'VALID'
              or source_row.source_shift_charge_pence is null
              or source_row.source_expense_parse_state<>'NOT_APPLICABLE'
             or source_row.source_expense_pence is not null)) then
      raise exception 'WEEKLY_SOURCE_NHSP_FINAL_NOT_FINALISABLE' using errcode='55000';
    end if;
    v_source_mode:='NHSP_WEEKLY';
    v_coverage_start:=null;
    v_coverage_end:=null;
    v_backing_report_number:=private.weekly_source_canonical_report_number_v1(
      v_upload.file_metadata_json->>'nhsp_report_number'
    );
    if v_backing_report_number is null then
      raise exception 'WEEKLY_SOURCE_NHSP_REPORT_NUMBER_REQUIRED' using errcode='55000';
    end if;
  elsif v_profile.profile_code in (
    'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1','HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1'
  ) then
    if v_scope_kind<>'CYCLE' or v_group.source_family<>'ROSTER'
       or v_source_profile_kind<>'HEALTHROSTER_ACTUAL_ROWS'
       or v_profile.omission_meaning<>'CANCEL_INSIDE_CONFIRMED_COVERAGE'
       or v_client_id is null
       or exists(select 1 from public.weekly_source_upload_rows source_row
         where source_row.upload_id=v_upload.id
           and (source_row.row_finalisation_state not in ('SOURCE_WORKED','SOURCE_UNFINALISED')
             or source_row.source_expense_parse_state<>'NOT_APPLICABLE'
             or source_row.source_expense_pence is not null)) then
      raise exception 'WEEKLY_SOURCE_HEALTHROSTER_NOT_FINALISABLE' using errcode='55000';
    end if;
    v_source_mode:='HEALTHROSTER_WEEKLY';
    v_coverage_start:=v_upload.confirmed_coverage_start_local_date;
    v_coverage_end:=v_upload.confirmed_coverage_end_local_date;
  elsif v_profile.profile_code='ROSTER_WEEKLY_SUMMARY_ACTUAL_V1' then
    if v_scope_kind<>'CYCLE' or v_group.source_family<>'ROSTER'
       or v_source_profile_kind<>'GENERIC_COMPLETE_SNAPSHOT'
       or v_profile.omission_meaning<>'CANCEL_INSIDE_CONFIRMED_COVERAGE'
       or v_client_id is null
       or exists(select 1 from public.weekly_source_upload_rows source_row
         where source_row.upload_id=v_upload.id
           and (source_row.row_finalisation_state not in ('NOT_APPLICABLE','SOURCE_WORKED','SOURCE_ABSENT_ZERO')
             or source_row.source_expense_parse_state not in ('NOT_APPLICABLE','VALID','OMITTED_ZERO')
             or (source_row.source_expense_parse_state='NOT_APPLICABLE')
                  is distinct from (source_row.source_expense_pence is null)
             or (source_row.source_expense_parse_state='OMITTED_ZERO'
                 and source_row.source_expense_pence<>0))) then
      raise exception 'WEEKLY_SOURCE_ROSTER_COMPLETE_NOT_FINALISABLE' using errcode='55000';
    end if;
    v_source_mode:='HEALTHROSTER_WEEKLY';
    v_coverage_start:=v_upload.confirmed_coverage_start_local_date;
    v_coverage_end:=v_upload.confirmed_coverage_end_local_date;
  else
    raise exception 'WEEKLY_SOURCE_PROFILE_NOT_FINAL_AUTHORITY' using errcode='55000';
  end if;
  if v_scope_kind='CYCLE' and (
    v_upload.coverage_state<>'COMPLETE' or v_upload.coverage_timezone<>'Europe/London'
    or v_coverage_start is null or v_coverage_end is null or v_coverage_start>v_coverage_end
  ) then
    raise exception 'WEEKLY_SOURCE_CONFIRMED_COVERAGE_REQUIRED' using errcode='55000';
  end if;
  if exists(
    select 1
    from public.weekly_source_row_resolutions resolution
    join public.weekly_source_upload_rows source_row on source_row.id=resolution.upload_row_id
    where source_row.upload_id=v_upload.id and resolution.generation=v_generation
      and (resolution.client_id is distinct from v_client_id
        or source_row.work_date<coalesce(v_coverage_start,source_row.work_date)
        or source_row.work_date>coalesce(v_coverage_end,source_row.work_date))
  ) then
    raise exception 'WEEKLY_SOURCE_RESOLUTION_OUTSIDE_FINAL_SCOPE' using errcode='55000';
  end if;

  v_window_observed:=private.weekly_source_invoice_window_lock_inventory_v1(v_upload.id,v_generation,v_cycle.id,v_client_id);
  if v_lock_phase=1 then
    v_window_discovery:=v_window_observed;
    select array_agg(key::uuid order by key::uuid) into v_invoice_window_ids
      from jsonb_object_keys(v_window_discovery->'cycles') key;
  elsif v_window_observed is distinct from v_window_discovery then
    raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SET_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  v_lock_observed:=jsonb_build_object(
    'group',to_jsonb(v_group),'cycle',to_jsonb(v_cycle),'scope',to_jsonb(v_scope),
    'upload',to_jsonb(v_upload),'publication',to_jsonb(v_publication),
    'profile',to_jsonb(v_profile),'correction',to_jsonb(v_correction),
    'client_id',v_client_id,'generation',v_generation,'coverage_start',v_coverage_start,
    'coverage_end',v_coverage_end,'source_profile_kind',v_source_profile_kind,
    'rule_set',v_rule_set,'resolutions',coalesce((select jsonb_agg(to_jsonb(r) order by r.id)
      from public.weekly_source_row_resolutions r join public.weekly_source_upload_rows s on s.id=r.upload_row_id
      where s.upload_id=v_upload.id and r.generation=v_generation),'[]'::jsonb));
  if v_lock_phase=1 then
    v_lock_discovery:=v_lock_observed;
  -- Review F2.  Finalisation calls the lineage ensure owner once per source row
  -- inside ONE transaction, so without this it accumulates family lock sets in
  -- source_row_ordinal order rather than the (btrim(booking_id), booking_id)
  -- order proof/32 section 6 step 2 fixes.  That is an A-B / B-A cycle against
  -- any sorted I-1 caller -- a publication, a release tick or a first
  -- authorisation -- and the I-1 caller was the victim (reproduction D3).
  --
  -- The complete set of roots this cycle will touch is therefore locked ONCE,
  -- up front, through the same helper, which sorts them.  Every later per-row
  -- call then re-enters locks this transaction already holds.
  --
  -- The Candidate serial gate is deliberately NOT taken here.  proof/32
  -- section 6 step 1 makes the gate per Candidate and pins it to four job
  -- types: first authorisation, first-authorisation withdrawal, entitlement
  -- publication and pending release.  Finalisation is none of them -- it
  -- authorises nothing and publishes no entitlement -- and one finalisation
  -- spans many Candidates, so a single gate call cannot cover it and a gate per
  -- Candidate would invent a lock ladder the pack does not describe.
  -- proof/34 section 5 asks this path only for the family lock set and the
  -- resolver, which is exactly what it takes.
  v_prior_finalisation_lock_operation:=coalesce(pg_catalog.current_setting('cloudtms.weekly_source_finalisation_lock_operation',true),'');
  v_prior_finalisation_root_set:=coalesce(pg_catalog.current_setting('cloudtms.weekly_source_finalisation_root_set',true),'');
  v_finalisation_lock_context:=true;
  select active_owner='NEXT' into v_next_source_hooks
  from private.bpay_next_module_control where id=1 for share;
  if coalesce(v_next_source_hooks,false) then

  -- Include prior-only CURRENT HR cancellation and positive-expense omission
  -- roots BEFORE taking any booking key. Current partial indexes provide the
  -- coverage inventory; only this upload/exact corrected revision contributes
  -- immutable emitted roots. No historical chooser is added here.
  v_finalisation_lock_operation:=private.bpay_next_source_current_lock_inventory_v1(
    v_upload.id,v_generation,case when p_prepare_only then v_correction.expected_current_final_revision_id else null end,
    v_group.id,v_client_id,v_coverage_start,v_coverage_end
  );
  perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation',v_finalisation_lock_operation::text,true);
  perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set','',true);
  else
  -- Retained default LEGACY / DISABLED Source path: no selector inventory,
  -- no assumption that pre-existing Source facts have been bootstrapped.
  select pg_catalog.array_agg(distinct contract_week.timesheet_id order by contract_week.timesheet_id)
  into v_finalisation_root_ids
  from public.weekly_source_upload_rows source_row
  join public.weekly_source_row_resolutions resolution
    on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
  join public.contract_weeks contract_week
    on contract_week.contract_id=resolution.contract_id
   and contract_week.additional_seq=0
   and contract_week.week_ending_date=source_row.work_date+
       ((coalesce((
          select contract.week_ending_weekday_snapshot
          from public.contracts contract where contract.id=resolution.contract_id
        ),0)-extract(dow from source_row.work_date)::integer+7)%7)
  where source_row.upload_id=v_upload.id
    and contract_week.timesheet_id is not null;

  if v_finalisation_root_ids is not null
     and pg_catalog.array_length(v_finalisation_root_ids,1) is not null then
    v_finalisation_lock_result:=private.weekly_source_lock_family_rows_v1(
      v_finalisation_root_ids,null
    );
    if coalesce((v_finalisation_lock_result->>'ok')::boolean,false) is not true then
      raise exception '%',v_finalisation_lock_result->>'code'
        using errcode='55000',detail=v_finalisation_lock_result::text;
    end if;
  end if;

  -- Review G2.  The set above was computed from an UNLOCKED read filtered on a
  -- non-null Contract Week Timesheet id, so a root another owner commits between
  -- that read and the loop would be locked later, in source-row order, out of
  -- the sorted order proof/32 section 6 step 2 fixes.  Recompute it under the
  -- family locks now held; if it grew, refuse retryably (40001) rather than take
  -- a second lock set out of order.  A retry recomputes the larger set up front.
  select pg_catalog.array_agg(distinct contract_week.timesheet_id order by contract_week.timesheet_id)
  into v_finalisation_root_recheck
  from public.weekly_source_upload_rows source_row
  join public.weekly_source_row_resolutions resolution
    on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
  join public.contract_weeks contract_week
    on contract_week.contract_id=resolution.contract_id
   and contract_week.additional_seq=0
   and contract_week.week_ending_date=source_row.work_date+
       ((coalesce((
          select contract.week_ending_weekday_snapshot
          from public.contracts contract where contract.id=resolution.contract_id
        ),0)-extract(dow from source_row.work_date)::integer+7)%7)
  where source_row.upload_id=v_upload.id
    and contract_week.timesheet_id is not null;

  if coalesce(v_finalisation_root_recheck,array[]::uuid[])
     <>coalesce(v_finalisation_root_ids,array[]::uuid[]) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'locked_root_count',
            coalesce(pg_catalog.array_length(v_finalisation_root_ids,1),0),
          'observed_root_count',
            coalesce(pg_catalog.array_length(v_finalisation_root_recheck,1),0)
        )::text;
  end if;

  -- Publish the locked set for the per-row calls.  The lineage ensure owner
  -- refuses 40001 when it discovers a root this set does not contain, so a root
  -- that appears after the recheck can never be locked out of order either.
  -- This is a Weekly-Source-private setting, never a Workbench-owned one.
  perform pg_catalog.set_config(
    'cloudtms.weekly_source_finalisation_root_set',
    coalesce(pg_catalog.array_to_string(v_finalisation_root_ids,','),'EMPTY_LOCKED_SET'),
    true
  );
  perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation','',true);
  end if;


  else
    if v_lock_observed is distinct from v_lock_discovery then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
    if v_finalisation_lock_operation is not null then
      perform private.bpay_next_source_current_lock_recheck_v1(v_finalisation_lock_operation);
    else
  -- Review G2.  The set above was computed from an UNLOCKED read filtered on a
  -- non-null Contract Week Timesheet id, so a root another owner commits between
  -- that read and the loop would be locked later, in source-row order, out of
  -- the sorted order proof/32 section 6 step 2 fixes.  Recompute it under the
  -- family locks now held; if it grew, refuse retryably (40001) rather than take
  -- a second lock set out of order.  A retry recomputes the larger set up front.
  select pg_catalog.array_agg(distinct contract_week.timesheet_id order by contract_week.timesheet_id)
  into v_finalisation_root_recheck
  from public.weekly_source_upload_rows source_row
  join public.weekly_source_row_resolutions resolution
    on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
  join public.contract_weeks contract_week
    on contract_week.contract_id=resolution.contract_id
   and contract_week.additional_seq=0
   and contract_week.week_ending_date=source_row.work_date+
       ((coalesce((
          select contract.week_ending_weekday_snapshot
          from public.contracts contract where contract.id=resolution.contract_id
        ),0)-extract(dow from source_row.work_date)::integer+7)%7)
  where source_row.upload_id=v_upload.id
    and contract_week.timesheet_id is not null;

  if coalesce(v_finalisation_root_recheck,array[]::uuid[])
     <>coalesce(v_finalisation_root_ids,array[]::uuid[]) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'locked_root_count',
            coalesce(pg_catalog.array_length(v_finalisation_root_ids,1),0),
          'observed_root_count',
            coalesce(pg_catalog.array_length(v_finalisation_root_recheck,1),0)
        )::text;
  end if;


    end if;
  end if;
  end loop;

  -- One transaction at a time may decide the final order for a logical
  -- group/Client/source-authority history.  Both supported HealthRoster
  -- layouts share the same final_authority_kind and therefore the same lock.
  -- The lock is acquired only after the exact current publication and Client
  -- have been resolved; no other owner acquires this finaliser-only domain.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly_source_finalise_order:'||v_group.id::text||':'||v_client_id::text||':'||v_source_profile_kind,
    0
  ));

  if p_prepare_only then
    if coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
         is distinct from v_correction.expected_current_final_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
    end if;
  elsif coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id) is not null then
    select * into strict v_existing_revision
    from public.weekly_source_final_revisions
    where id=coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id);
    if v_existing_revision.upload_id=v_upload.id
       and v_existing_revision.authority_scope_kind=v_scope_kind
       and v_existing_revision.report_scope_id is not distinct from v_report_scope_id
       and v_existing_revision.state='CURRENT' then
      -- Native operation is transaction-local, including exact immutable replay.
      if v_finalisation_lock_operation is not null then
        perform private.bpay_next_source_current_lock_release_v1(v_finalisation_lock_operation);
      end if;
      if v_finalisation_lock_context then
    perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation',v_prior_finalisation_lock_operation,true);
    perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set',v_prior_finalisation_root_set,true);
      end if;
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','FINALISED','idempotent',true,
        'final_revision_id',v_existing_revision.id,'source_cycle_id',v_cycle.id,
        'authority_scope_kind',v_scope_kind,'report_scope_id',v_report_scope_id,
        'upload_id',v_upload.id
      );
    end if;
    raise exception 'WEEKLY_SOURCE_SCOPE_ALREADY_FINALISED' using errcode='55000';
  end if;

  if v_scope_kind='CYCLE' and exists(
    select 1
    from public.weekly_source_final_revisions later_revision
    join public.weekly_source_cycles later_cycle
      on later_cycle.id=later_revision.source_cycle_id
    join public.weekly_source_client_manifests later_manifest
      on coalesce(later_manifest.invoice_window_cycle_id,later_manifest.source_cycle_id)=later_manifest.source_cycle_id and later_manifest.final_revision_id=later_revision.id
     and later_manifest.client_id=v_client_id
    join public.weekly_source_uploads later_upload
      on later_upload.id=later_revision.upload_id
    join public.weekly_source_format_profiles later_profile
      on later_profile.id=later_upload.source_format_profile_id
    where later_revision.authority_scope_kind='CYCLE'
      and later_revision.state='CURRENT'
      and later_cycle.source_group_id=v_group.id
      and later_cycle.finalisation_week_ending>v_cycle.finalisation_week_ending
      and later_profile.final_authority_kind=v_source_profile_kind
  ) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_OUT_OF_ORDER' using errcode='55000';
  end if;

  -- The source Timesheet owner is the only component permitted to create or
  -- reuse ordinary Timesheet lineage.  Finalisation calls it, then validates
  -- the resulting immutable binding; it never accepts a caller-owned id.
  for v_row in
    select resolution.id as resolution_id,source_row.row_finalisation_state
    from public.weekly_source_upload_rows source_row
    join public.weekly_source_row_resolutions resolution
      on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
    where source_row.upload_id=v_upload.id
      and (v_rule_values is null or v_rule_values->>'invoice_sender'<>'CLIENT_SELF_BILL' or v_rule_values->>'self_bill_source'<>'SAME_FILE'
          or coalesce((private.weekly_source_shift_on_self_bill_v1(resolution.work_event_id,v_cycle.id)->>'s25_pay_selected')::boolean,false))
      and (v_source_profile_kind='NHSP_TRUST_BACKING_REPORT'
        or source_row.row_finalisation_state='SOURCE_WORKED'
        or (v_source_profile_kind='GENERIC_COMPLETE_SNAPSHOT'
          and source_row.row_finalisation_state='NOT_APPLICABLE'))
    order by source_row.source_row_ordinal
  loop
    perform public.weekly_source_timesheet_lineage_ensure_atomic_v1(v_row.resolution_id,v_actor);
    v_economic_id:=private.weekly_source_finalisation_economic_assert_v1(
      v_row.resolution_id,v_cycle.id,v_source_mode
    );
    v_timesheet_id:=private.weekly_source_finalisation_lineage_assert_v1(
      v_row.resolution_id,v_cycle.id
    );
  end loop;

  if v_scope_kind='CYCLE' then
    select revision.id into v_prior_revision_id
    from public.weekly_source_final_revisions revision
    join public.weekly_source_cycles prior_cycle on prior_cycle.id=revision.source_cycle_id
    join public.weekly_source_client_manifests prior_manifest
      on coalesce(prior_manifest.invoice_window_cycle_id,prior_manifest.source_cycle_id)=prior_manifest.source_cycle_id and prior_manifest.final_revision_id=revision.id and prior_manifest.client_id=v_client_id
    join public.weekly_source_uploads prior_upload on prior_upload.id=revision.upload_id
    join public.weekly_source_format_profiles prior_profile
      on prior_profile.id=prior_upload.source_format_profile_id
    where revision.authority_scope_kind='CYCLE' and revision.state='CURRENT'
      and prior_cycle.source_group_id=v_group.id and prior_cycle.id<>v_cycle.id
      and prior_cycle.finalisation_week_ending<v_cycle.finalisation_week_ending
      and prior_profile.final_authority_kind=v_source_profile_kind
    order by prior_cycle.finalisation_week_ending desc,revision.finalised_at_utc desc,revision.id desc
    limit 1;
  end if;

  select coalesce(pg_catalog.max(revision.revision_number),0)+1 into v_revision_number
  from public.weekly_source_final_revisions revision
  where revision.source_cycle_id=v_cycle.id
    and revision.authority_scope_kind=v_scope_kind
    and revision.report_scope_id is not distinct from v_report_scope_id;
  select private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_FINAL_POLICY_SET_V1',
    pg_catalog.jsonb_build_object(
      'profile_code',v_profile.profile_code,'profile_version',v_profile.version,
      'source_profile_kind',v_source_profile_kind,'source_mode',v_source_mode,
      'economics',coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'row_resolution_id',resolution.id,
        'contract_and_rate_fingerprint',case when economic.id is null then null
          else pg_catalog.encode(economic.contract_and_rate_fingerprint,'hex') end,
        'effective_policy_fingerprint',case when economic.id is null then null
          else pg_catalog.encode(economic.effective_policy_fingerprint,'hex') end,
        'invoice_vat_policy_fingerprint',case when economic.id is null then null
          else pg_catalog.encode(economic.invoice_vat_policy_fingerprint,'hex') end,
        'calculation_fingerprint',case when economic.id is null then null
          else pg_catalog.encode(economic.calculation_fingerprint,'hex') end,
        'expense_policy_snapshot_id',expense_policy.id,
        'expense_policy_snapshot_hash',case when expense_policy.id is null then null
          else pg_catalog.encode(expense_policy.snapshot_hash,'hex') end
      ) order by source_row.source_row_ordinal),'[]'::jsonb)
    )
  ) into v_policy_fingerprint
  from public.weekly_source_upload_rows source_row
  join public.weekly_source_row_resolutions resolution
    on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
  left join public.weekly_source_row_economic_snapshots economic
    on economic.row_resolution_id=resolution.id
  left join public.weekly_source_row_expense_policy_snapshots expense_policy
    on expense_policy.row_resolution_id=resolution.id
  where source_row.upload_id=v_upload.id;
  v_revision_manifest_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_FINAL_REVISION_MANIFEST_V1',
    pg_catalog.jsonb_build_object(
      'source_cycle_id',v_cycle.id,'authority_scope_kind',v_scope_kind,
      'report_scope_id',v_report_scope_id,'revision_number',v_revision_number,
      'upload_id',v_upload.id,'authority_scope_version',v_scope_version,
      'row_manifest_hash',pg_catalog.encode(v_expected_row_hash,'hex'),
      'comparison_manifest_hash',pg_catalog.encode(v_expected_comparison_hash,'hex'),
      'issue_set_hash',pg_catalog.encode(v_expected_issue_hash,'hex'),
      'profile_code',v_profile.profile_code,'profile_version',v_profile.version,
      'coverage_start_local_date',v_coverage_start,'coverage_end_local_date',v_coverage_end,
      'reason',case when p_correction_session_id is null then 'INITIAL_FINALISATION'
        else 'CORRECT_FINAL_SOURCE' end,
      'predecessor_revision_id',case when p_correction_session_id is null then null
        else v_correction.expected_current_final_revision_id end,
      'prior_state_cutoff_revision_id',v_prior_revision_id,
      'policy_fingerprint',pg_catalog.encode(v_policy_fingerprint,'hex')
    )||case when v_rule_version is null then '{}'::jsonb else jsonb_build_object(
      'rule_set_version_id',v_rule_version,'rule_set_values_sha256',v_rule_set->>'values_sha256') end
  );
  insert into public.weekly_source_final_revisions(
    source_cycle_id,authority_scope_kind,report_scope_id,revision_number,upload_id,
    predecessor_revision_id,coverage_start_local_date,coverage_end_local_date,
    coverage_timezone,prior_state_cutoff_revision_id,reason,finalised_by_user_id,
    finalised_at_utc,manifest_hash,policy_fingerprint,state,rule_set_version_id
  ) values (
    v_cycle.id,v_scope_kind,v_report_scope_id,v_revision_number,v_upload.id,
    case when p_correction_session_id is null then null
      else v_correction.expected_current_final_revision_id end,
    v_coverage_start,v_coverage_end,
    case when v_scope_kind='CYCLE' then 'Europe/London' else null end,
    v_prior_revision_id,
    case when p_correction_session_id is null then 'INITIAL_FINALISATION'
      else 'CORRECT_FINAL_SOURCE' end,
    v_actor,v_finalised_at,
    v_revision_manifest_hash,v_policy_fingerprint,
    case when p_prepare_only then 'PREPARED' else 'CURRENT' end,v_rule_version
  ) returning id into v_revision_id;

  if v_source_profile_kind in ('GENERIC_COMPLETE_SNAPSHOT','HEALTHROSTER_ACTUAL_ROWS') then
    for v_row in
      select source_row.*,resolution.id as resolution_id,
             resolution.work_event_id,resolution.candidate_id,resolution.client_id,
             resolution.contract_id,resolution.work_event_match_kind,
             resolution.work_event_match_fingerprint
      from public.weekly_source_upload_rows source_row
      join public.weekly_source_row_resolutions resolution
        on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
      where source_row.upload_id=v_upload.id
        and (v_rule_values is null or v_rule_values->>'invoice_sender'<>'CLIENT_SELF_BILL' or v_rule_values->>'self_bill_source'<>'SAME_FILE'
          or coalesce((private.weekly_source_shift_on_self_bill_v1(resolution.work_event_id,v_cycle.id)->>'s25_pay_selected')::boolean,false))
        and (source_row.row_finalisation_state='SOURCE_WORKED'
          or (v_source_profile_kind='GENERIC_COMPLETE_SNAPSHOT'
            and source_row.row_finalisation_state='NOT_APPLICABLE'))
      order by source_row.source_row_ordinal
    loop
      v_economic_id:=private.weekly_source_finalisation_economic_assert_v1(
        v_row.resolution_id,v_cycle.id,'HEALTHROSTER_WEEKLY'
      );
      v_timesheet_id:=private.weekly_source_finalisation_lineage_assert_v1(
        v_row.resolution_id,v_cycle.id
      );
      select * into strict v_economic
      from public.weekly_source_row_economic_snapshots where id=v_economic_id;
      v_pay_vector:=private.weekly_source_finalisation_vector_v1(v_economic.id,'PAY',1::smallint);
      v_charge_vector:=private.weekly_source_finalisation_vector_v1(v_economic.id,'CHARGE',1::smallint);
      v_mapping_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_FINAL_MAPPING_V1',
        pg_catalog.jsonb_build_object(
          'work_event_id',v_row.work_event_id,'candidate_id',v_row.candidate_id,
          'client_id',v_row.client_id,'contract_id',v_row.contract_id
        )
      );
      -- Freeze only the four authority fields for this exact new snapshot.
      -- The full economic/provenance hashes remain unchanged below.
      v_effective_policy:=private._weekly_source_effective_policy_v1(
        v_row.client_id,v_row.contract_id,v_row.work_date
      );
      if (v_effective_policy->>'authority_mode') is distinct from 'SOURCE_AUTHORITY'
         or coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) is not true
         or (v_effective_policy->>'source_group_id')::uuid is distinct from v_group.id then
        raise exception 'WEEKLY_SOURCE_FINALISATION_POLICY_STALE' using errcode='40001';
      end if;
      v_authority_subset:=private.weekly_source_authority_subset_v1(v_effective_policy);
      v_snapshot_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_FINAL_SNAPSHOT_LINE_V1',
        pg_catalog.jsonb_build_object(
          'final_revision_id',v_revision_id,'upload_row_id',v_row.id,
          'row_resolution_id',v_row.resolution_id,'work_event_id',v_row.work_event_id,
          'candidate_id',v_row.candidate_id,'client_id',v_row.client_id,
          'contract_id',v_row.contract_id,'work_date',v_row.work_date,
          'start_at_local',v_row.start_at_local,'end_at_local',v_row.end_at_local,
          'break_minutes',v_row.break_minutes,'actual_net_minutes',v_row.actual_net_minutes,
          'pay_vector',v_pay_vector,'charge_vector',v_charge_vector,
          'source_expense_pence',v_row.source_expense_pence,
          'source_fingerprint',pg_catalog.encode(v_row.normalised_row_hash,'hex'),
          'mapping_fingerprint',pg_catalog.encode(v_mapping_fingerprint,'hex'),
          'rate_fingerprint',pg_catalog.encode(v_economic.calculation_fingerprint,'hex'),
          'policy_fingerprint',pg_catalog.encode(v_economic.effective_policy_fingerprint,'hex')
        )
      );
      insert into public.weekly_source_final_snapshot_lines(
        final_revision_id,upload_row_id,row_resolution_id,charge_check_id,
        source_profile_kind,work_event_id,external_event_identity,candidate_id,
        client_id,contract_id,work_date,start_at_local,end_at_local,break_minutes,
        actual_net_minutes,source_classifications_json,pay_vector_json,charge_vector_json,
        source_expense_pence,source_fingerprint,mapping_fingerprint,rate_fingerprint,
        policy_fingerprint,snapshot_line_hash,authority_subset_json,authority_subset_sha256,invoice_economics_sha256
      ) values (
        v_revision_id,v_row.id,v_row.resolution_id,null,v_source_profile_kind,
        v_row.work_event_id,v_row.external_source_key,v_row.candidate_id,v_row.client_id,
        v_row.contract_id,v_row.work_date,v_row.start_at_local,v_row.end_at_local,
        v_row.break_minutes,v_row.actual_net_minutes,v_economic.canonical_result_json,
        v_pay_vector,v_charge_vector,v_row.source_expense_pence,v_row.normalised_row_hash,
        v_mapping_fingerprint,v_economic.calculation_fingerprint,
        v_economic.effective_policy_fingerprint,v_snapshot_hash,v_authority_subset,
        private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_AUTHORITY_SUBSET_V1',v_authority_subset),
        case when v_rule_values is not null and v_rule_values->>'invoice_sender'='CLIENT_SELF_BILL' and v_rule_values->>'invoice_amount_basis'='SOURCE_AMOUNT' and v_rule_values->>'source_amount_basis'='EXPORT_ACTUAL_COST_INC_VAT_NET_AGENCY_WORKER_PAY'
          then private.weekly_source_invoice_economics_fingerprint_v1(jsonb_build_object('source_shift_charge_pence',v_row.source_shift_charge_pence,
            'source_gross_pence',v_row.source_gross_pence,'source_vat_pence',v_row.source_vat_pence),v_rule_values->>'line_vat_method',
            case when v_economic.invoice_vat_chargeable then v_economic.invoice_vat_rate_pct else 0 end) else null end
      ) returning id into v_snapshot_id;
      v_snapshot_count:=v_snapshot_count+1;
    end loop;

    for v_transition in
      with prior_states as (
        select distinct on (prior_transition.work_event_id)
               prior_transition.work_event_id,
               prior_transition.new_snapshot_line_id
        from public.weekly_source_state_transitions prior_transition
        join public.weekly_source_final_revisions prior_revision
          on prior_revision.id=prior_transition.final_revision_id
         and prior_revision.state='CURRENT'
        join public.weekly_source_cycles prior_cycle
          on prior_cycle.id=prior_transition.finalisation_cycle_id
        join public.weekly_source_client_manifests prior_manifest
          on coalesce(prior_manifest.invoice_window_cycle_id,prior_manifest.source_cycle_id)=prior_manifest.source_cycle_id and prior_manifest.final_revision_id=prior_revision.id
         and prior_manifest.client_id=v_client_id
        where prior_transition.source_profile_kind=v_source_profile_kind
          and prior_cycle.source_group_id=v_group.id
          and prior_cycle.finalisation_week_ending<v_cycle.finalisation_week_ending
        order by prior_transition.work_event_id,
                 prior_cycle.finalisation_week_ending desc,
                 prior_revision.finalised_at_utc desc,
                 prior_revision.revision_number desc,
                 prior_transition.created_at_utc desc,
                 prior_transition.id desc
      ), prior_lines as (
        select prior_line.id,prior_state.work_event_id
        from prior_states prior_state
        join public.weekly_source_final_snapshot_lines prior_line
          on prior_line.id=prior_state.new_snapshot_line_id
        where prior_line.client_id=v_client_id
          and not (v_rule_values is not null and v_rule_values->>'invoice_sender'='CLIENT_SELF_BILL' and v_rule_values->>'self_bill_source'='SAME_FILE'
            and coalesce((private.weekly_source_shift_on_self_bill_v1(prior_line.work_event_id,v_cycle.id)->>'bound_to_finalised_export')::boolean,false)
            and not coalesce((private.weekly_source_shift_on_self_bill_v1(prior_line.work_event_id,v_cycle.id)->>'s25_pay_selected')::boolean,false))
          and (
            prior_line.work_date between v_coverage_start and v_coverage_end
            or exists(
              select 1
              from public.weekly_source_row_resolutions current_resolution
              join public.weekly_source_upload_rows current_row
                on current_row.id=current_resolution.upload_row_id
              where current_row.upload_id=v_upload.id
                and current_resolution.generation=v_generation
                and current_resolution.work_event_id=prior_line.work_event_id
            )
          )
      ), current_lines as (
        select current_line.id,current_line.work_event_id
        from public.weekly_source_final_snapshot_lines current_line
        where current_line.final_revision_id=v_revision_id
      )
      select coalesce(prior_lines.work_event_id,current_lines.work_event_id) as work_event_id,
             prior_lines.id as prior_snapshot_id,current_lines.id as current_snapshot_id
      from prior_lines full join current_lines using(work_event_id)
      order by coalesce(prior_lines.work_event_id,current_lines.work_event_id)
    loop
      select * into v_prior_snapshot
      from public.weekly_source_final_snapshot_lines
      where id=v_transition.prior_snapshot_id;
      select * into v_current_snapshot
      from public.weekly_source_final_snapshot_lines
      where id=v_transition.current_snapshot_id;
      v_effective_policy:=private._weekly_source_effective_policy_v1(
        coalesce(v_current_snapshot.client_id,v_prior_snapshot.client_id),
        coalesce(v_current_snapshot.contract_id,v_prior_snapshot.contract_id),
        coalesce(v_current_snapshot.work_date,v_prior_snapshot.work_date)
      );
      if (v_effective_policy->>'authority_mode') is distinct from 'SOURCE_AUTHORITY'
         or coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) is not true
         or (v_effective_policy->>'source_group_id')::uuid is distinct from v_group.id then
        raise exception 'WEEKLY_SOURCE_FINALISATION_POLICY_STALE' using errcode='40001';
      end if;
      v_authority_subset:=private.weekly_source_authority_subset_v1(v_effective_policy);
      v_prior_authority_subset:=private.weekly_source_snapshot_authority_subset_v1(v_transition.prior_snapshot_id);
      v_current_authority_subset:=private.weekly_source_snapshot_authority_subset_v1(v_transition.current_snapshot_id);
      if (v_effective_policy->>'authority_mode') is distinct from 'SOURCE_AUTHORITY'
         or coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) is not true
         or (v_effective_policy->>'source_group_id')::uuid is distinct from v_group.id
         or (coalesce(v_current_authority_subset,v_prior_authority_subset) is not null
           and v_authority_subset is distinct from coalesce(v_current_authority_subset,v_prior_authority_subset))
         or (coalesce(v_current_authority_subset,v_prior_authority_subset) is null
           and private.weekly_source_finalisation_hex32_v1(
              v_effective_policy->>'policy_sha256','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
            ) is distinct from coalesce(
              v_current_snapshot.policy_fingerprint,v_prior_snapshot.policy_fingerprint
            )) then
        raise exception 'WEEKLY_SOURCE_FINALISATION_POLICY_STALE' using errcode='40001';
      end if;
      v_correction_presentation:=pg_catalog.upper(pg_catalog.btrim(coalesce(
        v_effective_policy->>'self_bill_correction_presentation',''
      )));
      if v_correction_presentation not in (
        'FULL_REVERSAL_REPLACEMENT','NET_DIFFERENCE_PRESENTATION'
      ) then
        raise exception 'WEEKLY_SOURCE_SELF_BILL_CORRECTION_POLICY_REQUIRED'
          using errcode='55000';
      end if;
      -- Unknown pre-upgrade authority keeps the whole-hash fence. Equality
      -- proves compatibility without inventing historical four-field JSON.
      v_comparison_current_authority:=v_current_authority_subset;
      if v_transition.prior_snapshot_id is not null and v_prior_authority_subset is null
         and v_transition.current_snapshot_id is not null then
        if private.weekly_source_finalisation_hex32_v1(
             v_effective_policy->>'policy_sha256','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
           ) is distinct from v_prior_snapshot.policy_fingerprint then
          raise exception 'WEEKLY_SOURCE_FINALISATION_POLICY_STALE' using errcode='40001';
        end if;
        v_comparison_current_authority:=null;
      end if;
      v_prior_state:=private.weekly_source_snapshot_value_fingerprint_v1(
        v_transition.prior_snapshot_id,v_prior_authority_subset
      );
      v_current_state:=private.weekly_source_snapshot_value_fingerprint_v1(
        v_transition.current_snapshot_id,v_comparison_current_authority
      );
      v_outcome:=case
        when v_transition.prior_snapshot_id is null then 'ADD'
        when v_transition.current_snapshot_id is null then 'CANCEL'
        when v_prior_state=v_current_state then 'NO_CHANGE'
        else 'AMEND' end;
      v_transition_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_STATE_TRANSITION_V1',
        pg_catalog.jsonb_build_object(
          'final_revision_id',v_revision_id,'work_event_id',v_transition.work_event_id,
          'previous_snapshot_line_id',v_transition.prior_snapshot_id,
          'new_snapshot_line_id',v_transition.current_snapshot_id,
          'outcome',v_outcome,
          'prior_state_fingerprint',case when v_prior_state is null then null
            else pg_catalog.encode(v_prior_state,'hex') end,
          'new_state_fingerprint',case when v_current_state is null then null
            else pg_catalog.encode(v_current_state,'hex') end
        )
      );
      insert into public.weekly_source_state_transitions(
        final_revision_id,finalisation_cycle_id,source_profile_kind,work_event_id,
        previous_present,new_present,previous_snapshot_line_id,new_snapshot_line_id,
        outcome,identity_match_kind,match_confidence,prior_state_fingerprint,
        new_state_fingerprint,transition_fingerprint,
        ordinary_source_entitlement_projection_state
      ) values (
        v_revision_id,v_cycle.id,v_source_profile_kind,v_transition.work_event_id,
        v_transition.prior_snapshot_id is not null,v_transition.current_snapshot_id is not null,
        v_transition.prior_snapshot_id,v_transition.current_snapshot_id,v_outcome,
        (select event.identity_kind from public.weekly_work_events event
          where event.id=v_transition.work_event_id),
        case when (select event.identity_kind from public.weekly_work_events event
          where event.id=v_transition.work_event_id)='PROFILE_EXTERNAL_KEY'
          then 'EXACT_PROFILE_KEY' else 'EXACT_DURABLE_LINEAGE' end,
        v_prior_state,v_current_state,v_transition_fingerprint,
        case when v_outcome='NO_CHANGE' then 'NOT_APPLICABLE' else 'PENDING' end
      ) returning id into v_transition_id;
      v_transition_count:=v_transition_count+1;

      if v_outcome='NO_CHANGE' then
        v_unchanged_count:=v_unchanged_count+1;
        if v_transition.new_snapshot_line_id is not null and v_transition.previous_snapshot_line_id is not null and exists(select 1 from public.weekly_source_final_snapshot_lines current_line join public.weekly_source_final_snapshot_lines prior_line on prior_line.id=v_transition.previous_snapshot_line_id where current_line.id=v_transition.new_snapshot_line_id and current_line.external_event_identity is distinct from prior_line.external_event_identity) then
          if private.weekly_source_rebill_movement_insert_v1(v_transition_id,v_revision_id) is not null then v_movement_count:=v_movement_count+1; end if;
        else
          v_invoice_correction:=private.weekly_source_invoice_correction_insert_v1(v_transition_id,v_transition.work_event_id,v_revision_id);
          v_movement_count:=v_movement_count+coalesce((v_invoice_correction->>'movement_count')::integer,0);
        end if;
      else
        if v_outcome in ('AMEND','CANCEL') then
          select movement.* into v_prior_movement
          from public.weekly_source_billing_movements movement
          join public.weekly_source_final_revisions movement_revision
            on movement_revision.id=movement.final_revision_id
          join public.weekly_source_cycles movement_cycle
            on movement_cycle.id=movement.finalisation_cycle_id
          where movement.work_event_id=v_transition.work_event_id
            and movement.source_profile_kind=v_source_profile_kind
            and movement.movement_role in ('POSITIVE','REPLACEMENT')
            and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
            and movement.final_revision_id<>v_revision_id
            and movement_cycle.finalisation_week_ending<v_cycle.finalisation_week_ending
          order by movement_cycle.finalisation_week_ending desc,
                   movement_revision.finalised_at_utc desc,movement.created_at_utc desc,movement.id desc
          limit 1;
          if not found then
            raise exception 'WEEKLY_SOURCE_PRIOR_MOVEMENT_MISSING' using errcode='55000';
          end if;
          v_correction_unit_id:=pg_catalog.gen_random_uuid();
          v_movement_id:=private.weekly_source_finalisation_insert_reversal_v1(
            v_transition_id,v_revision_id,v_cycle.id,v_prior_movement.id,
            v_correction_unit_id,v_source_profile_kind,
            pg_catalog.jsonb_build_object(
              'schema_version','WEEKLY_SOURCE_GENERATED_REVERSAL_FACTS_V1',
              'outcome',v_outcome,'prior_snapshot_line_id',v_transition.prior_snapshot_id,
              'prior_movement_id',v_prior_movement.id,
              'correction_presentation',v_correction_presentation
            )
          );
          v_movement_count:=v_movement_count+1;
          if private.weekly_source_invoice_correction_unwind_v1(v_transition_id,v_transition.work_event_id,v_revision_id) is not null then v_movement_count:=v_movement_count+1; end if;
        else
          v_correction_unit_id:=null;
          v_prior_movement.id:=null;
        end if;
        if v_outcome in ('ADD','AMEND') then
          select resolution.id as resolution_id into strict v_row
          from public.weekly_source_row_resolutions resolution
          where resolution.id=v_current_snapshot.row_resolution_id;
          v_economic_id:=private.weekly_source_finalisation_economic_assert_v1(
            v_row.resolution_id,v_cycle.id,'HEALTHROSTER_WEEKLY'
          );
          v_timesheet_id:=private.weekly_source_finalisation_lineage_assert_v1(
            v_row.resolution_id,v_cycle.id
          );
          select * into strict v_economic
          from public.weekly_source_row_economic_snapshots where id=v_economic_id;
          v_invoice_amounts:=private.weekly_source_invoice_line_amounts_v1(v_row.resolution_id,v_revision_id);
          v_movement_id:=private.weekly_source_finalisation_insert_current_movement_v1(
            v_transition_id,null,v_revision_id,v_cycle.id,v_source_profile_kind,
            case when v_outcome='ADD' then 'POSITIVE' else 'REPLACEMENT' end,
            case when v_outcome='ADD' then 'SOURCE_ORDINARY' else 'SOURCE_REPLACEMENT' end,
            v_row.resolution_id,v_economic.id,v_timesheet_id,case when (v_invoice_amounts->>'source_amount')::boolean then (v_invoice_amounts->>'net_pence')::bigint else null end,
            (v_invoice_amounts->>'net_pence')::bigint,v_invoice_amounts->>'price_check_result',case when (v_invoice_amounts->>'source_amount')::boolean then v_economic.calculation_fingerprint else null end,
            nullif(v_invoice_amounts->>'charge_acceptance_id','')::uuid,
            pg_catalog.jsonb_build_object(
              'schema_version','WEEKLY_SOURCE_CURRENT_FACTS_V1','outcome',v_outcome,
              'snapshot_line_id',v_current_snapshot.id,
              'upload_row_id',v_current_snapshot.upload_row_id,
              'row_resolution_id',v_current_snapshot.row_resolution_id,
              'correction_presentation',v_correction_presentation
            ),v_correction_unit_id,
            case when v_outcome='AMEND' then v_prior_movement.id else null end
          );
          v_movement_count:=v_movement_count+1;
        end if;
      end if;

    end loop;

    if v_profile.profile_code='ROSTER_WEEKLY_SUMMARY_ACTUAL_V1' then
      -- The profile can serve Clients with or without source-fixed expenses.
      -- A snapshot is mandatory exactly where the sealed effective policy
      -- enables that route, and forbidden otherwise.  This prevents both a
      -- missing configured expense and accidental contamination of ordinary
      -- evidence-led expenses.
      for v_row in
        select source_row.work_date,resolution.id as resolution_id,
               resolution.client_id,resolution.contract_id,
               resolution.effective_policy_fingerprint,
               expense_policy.id as expense_policy_snapshot_id
        from public.weekly_source_upload_rows source_row
        join public.weekly_source_row_resolutions resolution
          on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
        left join public.weekly_source_row_expense_policy_snapshots expense_policy
          on expense_policy.row_resolution_id=resolution.id
        where source_row.upload_id=v_upload.id
        order by source_row.source_row_ordinal
      loop
        v_effective_policy:=private._weekly_source_effective_policy_v1(
          v_row.client_id,v_row.contract_id,v_row.work_date
        );
        if (v_effective_policy->>'authority_mode') is distinct from 'SOURCE_AUTHORITY'
           or coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) is not true
           or (v_effective_policy->>'source_group_id')::uuid is distinct from v_group.id
           or private.weekly_source_finalisation_hex32_v1(
                v_effective_policy->>'policy_sha256','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
              ) is distinct from v_row.effective_policy_fingerprint then
          raise exception 'WEEKLY_SOURCE_FINALISATION_POLICY_STALE' using errcode='40001';
        end if;
        if coalesce((v_effective_policy->>'source_fixed_expenses_enabled')::boolean,false) then
          if v_row.expense_policy_snapshot_id is null
             or private.weekly_source_finalisation_expense_policy_assert_v1(
                  v_row.resolution_id,v_cycle.id
                ) is distinct from v_row.expense_policy_snapshot_id then
            raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_SNAPSHOT_CARDINALITY'
              using errcode='55000';
          end if;
        elsif v_row.expense_policy_snapshot_id is not null then
          raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_NOT_ENABLED' using errcode='55000';
        end if;
      end loop;

      for v_expense_observation in
        with current_observation as (
          select expense_policy.id as expense_policy_snapshot_id,
                 expense_policy.row_resolution_id,expense_policy.work_event_id,
                 expense_policy.contract_id,expense_policy.source_expense_pence,
                 expense_policy.source_expense_vat_enabled,
                 expense_policy.correction_presentation
          from public.weekly_source_row_expense_policy_snapshots expense_policy
          join public.weekly_source_row_resolutions resolution
            on resolution.id=expense_policy.row_resolution_id
          join public.weekly_source_upload_rows source_row
            on source_row.id=resolution.upload_row_id
          where source_row.upload_id=v_upload.id and resolution.generation=v_generation
        ), prior_authority as (
          select
                 case when p_prepare_only
                           and authority.final_revision_id=v_correction.expected_current_final_revision_id
                        then baseline.id else authority.id end as prior_authority_id,
                 authority.work_event_id,
                 case when p_prepare_only
                           and authority.final_revision_id=v_correction.expected_current_final_revision_id
                        then baseline.contract_id else authority.contract_id end as contract_id,
                 case when p_prepare_only
                           and authority.final_revision_id=v_correction.expected_current_final_revision_id
                        then baseline.source_expense_pence else authority.source_expense_pence end
                   as source_expense_pence,
                 case when p_prepare_only
                           and authority.final_revision_id=v_correction.expected_current_final_revision_id
                        then baseline.source_expense_vat_enabled
                        else authority.source_expense_vat_enabled end
                   as source_expense_vat_enabled,
                 case when p_prepare_only
                           and authority.final_revision_id=v_correction.expected_current_final_revision_id
                        then baseline.correction_presentation
                        else authority.correction_presentation end
                   as correction_presentation,
                 event.work_date
          from public.weekly_expense_authority_generations authority
          join public.weekly_work_events event on event.id=authority.work_event_id
          left join public.weekly_expense_authority_generations baseline
            on p_prepare_only
           and authority.final_revision_id=v_correction.expected_current_final_revision_id
           and baseline.id=authority.prior_expense_authority_generation_id
          where authority.state='CURRENT'
            and event.first_source_group_id=v_group.id
            and event.client_id=v_client_id
            and not (
              p_prepare_only
              and authority.final_revision_id=v_correction.expected_current_final_revision_id
              and baseline.id is null
            )
            and (
              event.work_date between v_coverage_start and v_coverage_end
              or exists(
                select 1 from current_observation current_match
                where current_match.work_event_id=authority.work_event_id
              )
            )
        )
        select coalesce(current_observation.work_event_id,prior_authority.work_event_id) as work_event_id,
               current_observation.expense_policy_snapshot_id,
               current_observation.row_resolution_id,
               current_observation.contract_id as current_contract_id,
               current_observation.source_expense_pence as current_expense_pence,
               current_observation.source_expense_vat_enabled as current_expense_vat_enabled,
               current_observation.correction_presentation as current_correction_presentation,
               prior_authority.prior_authority_id,
               prior_authority.contract_id as prior_contract_id,
               prior_authority.source_expense_pence as prior_expense_pence,
               prior_authority.source_expense_vat_enabled as prior_expense_vat_enabled,
               prior_authority.correction_presentation as prior_correction_presentation
        from current_observation
        full join prior_authority using(work_event_id)
        order by coalesce(current_observation.work_event_id,prior_authority.work_event_id)
      loop
        v_expense_policy_id:=v_expense_observation.expense_policy_snapshot_id;
        v_prior_expense_authority_id:=v_expense_observation.prior_authority_id;
        v_expense_authority_id:=null;
        v_expense_timesheet_id:=null;
        v_current_expense.id:=null;
        if v_expense_policy_id is not null then
          if private.weekly_source_finalisation_expense_policy_assert_v1(
               v_expense_observation.row_resolution_id,v_cycle.id
             ) is distinct from v_expense_policy_id then
            raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_SNAPSHOT_INVALID' using errcode='55000';
          end if;
          select * into strict v_expense_policy
          from public.weekly_source_row_expense_policy_snapshots
          where id=v_expense_policy_id;
          v_target_expense_pence:=v_expense_policy.source_expense_pence;
          v_target_expense_vat:=v_expense_policy.source_expense_vat_enabled;
          v_target_expense_contract_id:=v_expense_policy.contract_id;
          v_expense_observation_kind:='ROW_PRESENT';
          v_correction_presentation:=v_expense_policy.correction_presentation;
          if v_target_expense_pence>0 then
            perform public.weekly_source_timesheet_lineage_ensure_atomic_v1(
              v_expense_policy.row_resolution_id,v_actor
            );
            v_expense_timesheet_id:=private.weekly_source_finalisation_lineage_assert_v1(
              v_expense_policy.row_resolution_id,v_cycle.id
            );
          end if;
        else
          v_target_expense_pence:=0;
          v_target_expense_vat:=v_expense_observation.prior_expense_vat_enabled;
          v_target_expense_contract_id:=v_expense_observation.prior_contract_id;
          v_expense_observation_kind:='OMITTED_IN_COMPLETE_COVERAGE';
          v_correction_presentation:=v_expense_observation.prior_correction_presentation;
        end if;
        if v_prior_expense_authority_id is not null then
          select * into strict v_current_expense
          from public.weekly_expense_authority_generations expense
          where expense.id=v_prior_expense_authority_id
            and expense.state in ('CURRENT','SUPERSEDED')
            and expense.work_event_id=v_expense_observation.work_event_id
          for update;
        end if;
        if v_prior_expense_authority_id is null
           or v_current_expense.source_expense_pence is distinct from v_target_expense_pence
           or v_current_expense.source_expense_vat_enabled is distinct from v_target_expense_vat
           or v_current_expense.contract_id is distinct from v_target_expense_contract_id
           or v_current_expense.source_observation_kind is distinct from v_expense_observation_kind then
          if v_prior_expense_authority_id is not null then
            if not p_prepare_only then
              update public.weekly_expense_authority_generations
              set state='SUPERSEDED' where id=v_prior_expense_authority_id;
            end if;
          end if;
          select coalesce(pg_catalog.max(expense.generation),0)+1 into v_expense_generation
          from public.weekly_expense_authority_generations expense
          where expense.work_event_id=v_expense_observation.work_event_id;
          v_expense_hash:=private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_EXPENSE_AUTHORITY_GENERATION_V1',
            pg_catalog.jsonb_build_object(
              'final_revision_id',v_revision_id,
              'work_event_id',v_expense_observation.work_event_id,
              'contract_id',v_target_expense_contract_id,
              'row_expense_policy_snapshot_id',v_expense_policy_id,
              'prior_expense_authority_generation_id',v_prior_expense_authority_id,
              'generation',v_expense_generation,
              'source_observation_kind',v_expense_observation_kind,
              'correction_presentation',v_correction_presentation,
              'source_expense_pence',v_target_expense_pence,
              'source_expense_vat_enabled',v_target_expense_vat
            )
          );
          insert into public.weekly_expense_authority_generations(
            final_revision_id,work_event_id,contract_id,row_expense_policy_snapshot_id,
            prior_expense_authority_generation_id,generation,source_observation_kind,
            correction_presentation,source_expense_pence,source_expense_vat_enabled,
            candidate_reimbursement_ex_vat,client_charge_ex_vat,authority_hash,state
          ) values (
            v_revision_id,v_expense_observation.work_event_id,v_target_expense_contract_id,
            v_expense_policy_id,v_prior_expense_authority_id,v_expense_generation,
            v_expense_observation_kind,v_correction_presentation,v_target_expense_pence,
            v_target_expense_vat,v_target_expense_pence::numeric/100,
            v_target_expense_pence::numeric/100,v_expense_hash,
            case when p_prepare_only then 'PREPARED' else 'CURRENT' end
          ) returning id into v_expense_authority_id;
          v_expense_movement_result:=
            private.weekly_source_finalisation_materialise_expense_invoice_v1(
              v_revision_id,v_cycle.id,v_source_profile_kind,
              v_expense_authority_id,v_prior_expense_authority_id,
              v_expense_policy_id,v_expense_timesheet_id,
              v_correction_presentation
            );
          v_movement_count:=v_movement_count+
            coalesce((v_expense_movement_result->>'movement_count')::integer,0);
          v_expense_generation_count:=v_expense_generation_count+1;
        end if;
        v_current_expense.id:=null;
      end loop;
    end if;
  else
    v_source_total_cost:=0;
    v_source_commission:=0;
    v_source_invoice_total:=0;
    v_line_count:=0;
    for v_row in
      select source_row.*,resolution.id as resolution_id,
             resolution.work_event_id,resolution.candidate_id,resolution.client_id,
             resolution.contract_id
      from public.weekly_source_upload_rows source_row
      join public.weekly_source_row_resolutions resolution
        on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
      where source_row.upload_id=v_upload.id
      order by source_row.source_row_ordinal
    loop
      v_economic_id:=private.weekly_source_finalisation_economic_assert_v1(
        v_row.resolution_id,v_cycle.id,'NHSP_WEEKLY'
      );
      v_timesheet_id:=private.weekly_source_finalisation_lineage_assert_v1(
        v_row.resolution_id,v_cycle.id
      );
      select * into strict v_economic
      from public.weekly_source_row_economic_snapshots where id=v_economic_id;
      select * into v_charge_check
      from public.weekly_source_charge_checks charge_check
      where charge_check.upload_row_id=v_row.id
        and charge_check.row_resolution_id=v_row.resolution_id
        and charge_check.generation=v_generation;
      v_charge_acceptance.id:=null;
      if found and v_charge_check.comparison_result in ('MISMATCH','ZERO_SOURCE_CHARGE') then
        select * into v_charge_acceptance
        from public.weekly_source_charge_acceptances acceptance
        where acceptance.charge_check_id=v_charge_check.id
          and acceptance.upload_row_id=v_row.id
          and acceptance.row_resolution_id=v_row.resolution_id
          and acceptance.source_upload_id=v_upload.id
          and acceptance.contract_id=v_row.contract_id
          and acceptance.acceptance_kind=case v_charge_check.comparison_result
            when 'ZERO_SOURCE_CHARGE' then 'ACCEPTED_ZERO' else 'ACCEPTED_DISPARITY' end
          and acceptance.source_upload_hash=v_upload.content_sha256
          and acceptance.source_row_fingerprint=(select resolution.source_row_fingerprint
            from public.weekly_source_row_resolutions resolution where resolution.id=v_row.resolution_id)
          and acceptance.contract_and_rate_fingerprint=v_economic.contract_and_rate_fingerprint
          and acceptance.effective_policy_fingerprint=v_economic.effective_policy_fingerprint
          and acceptance.charge_calculation_fingerprint=v_economic.calculation_fingerprint
          and acceptance.acceptance_policy_fingerprint=
            private.weekly_source_charge_acceptance_policy_fingerprint_v1();
      end if;
      v_price_admission_result:=case v_charge_check.comparison_result
        when 'ZERO_SOURCE_CHARGE' then 'ACCEPTED_ZERO'
        when 'MISMATCH' then 'ACCEPTED_DISPARITY'
        else v_charge_check.comparison_result end;
      if not found or (select pg_catalog.count(*)
          from public.weekly_source_charge_checks charge_check
          where charge_check.upload_row_id=v_row.id
            and charge_check.row_resolution_id=v_row.resolution_id
            and charge_check.generation=v_generation)<>1
         or v_charge_check.source_commission_pence is distinct from v_row.source_commission_pence
         or v_charge_check.source_total_cost_pence is distinct from v_row.source_total_cost_pence
         or v_charge_check.source_shift_charge_pence is distinct from v_row.source_shift_charge_pence
         or v_charge_check.calculated_segment_charge_pence is distinct from v_economic.calculated_charge_pence
         or v_charge_check.source_charge_difference_pence is distinct from
              (v_row.source_shift_charge_pence-v_economic.calculated_charge_pence)
         or v_charge_check.charge_calculation_fingerprint is distinct from
              v_economic.calculation_fingerprint
         or v_charge_check.comparison_profile_version<>'NHSP_TWO_COMPONENT_PENCE_V1'
         or v_charge_check.comparison_result not in (
              'EXACT','SOURCE_ROUNDING_EQUIVALENT','MISMATCH','ZERO_SOURCE_CHARGE'
            )
         or not (
           (v_charge_check.comparison_result='EXACT'
             and v_charge_check.source_charge_difference_pence=0)
           or (v_charge_check.comparison_result='SOURCE_ROUNDING_EQUIVALENT'
             and v_charge_check.row_sign_kind in ('POSITIVE','FULL_NEGATIVE')
             and (v_charge_check.source_charge_difference_pence=1
               or v_charge_check.source_charge_difference_pence=-1)
             and ((v_charge_check.source_shift_charge_pence>0
                   and v_charge_check.calculated_segment_charge_pence>0)
               or (v_charge_check.source_shift_charge_pence<0
                   and v_charge_check.calculated_segment_charge_pence<0)))
           or (v_charge_check.comparison_result='MISMATCH'
             and v_charge_acceptance.id is not null
             and v_charge_acceptance.acceptance_kind='ACCEPTED_DISPARITY')
           or (v_charge_check.comparison_result='ZERO_SOURCE_CHARGE'
             and v_charge_check.source_commission_pence=0
             and v_charge_check.source_total_cost_pence=0
             and v_charge_check.source_shift_charge_pence=0
             and v_charge_check.calculated_segment_charge_pence>0
             and v_charge_acceptance.id is not null
             and v_charge_acceptance.acceptance_kind='ACCEPTED_ZERO')
         )
         or v_charge_check.row_sign_kind is distinct from (case
              when v_economic.row_sign=1 then 'POSITIVE' else 'FULL_NEGATIVE' end)
         or v_charge_check.phase_severity='FINALISATION_BLOCKER'
         or v_charge_check.blocker_code is not null then
        raise exception 'WEEKLY_SOURCE_NHSP_PRICE_GATE_FAILED'
          using errcode='55000',detail=v_row.source_row_ordinal::text;
      end if;
      v_movement_id:=private.weekly_source_finalisation_insert_current_movement_v1(
        null,v_row.id,v_revision_id,v_cycle.id,'NHSP_TRUST_BACKING_REPORT',
        case when v_economic.row_sign=1 then 'POSITIVE' else 'REVERSAL' end,
        case when v_economic.row_sign=1
          then 'NHSP_PHYSICAL_POSITIVE' else 'NHSP_PHYSICAL_FULL_NEGATIVE' end,
        v_row.resolution_id,v_economic.id,v_timesheet_id,
        v_row.source_shift_charge_pence,v_row.source_shift_charge_pence,
        v_price_admission_result,v_charge_check.charge_calculation_fingerprint,
        v_charge_acceptance.id,
        pg_catalog.jsonb_build_object(
          'schema_version','WEEKLY_SOURCE_NHSP_PHYSICAL_FACTS_V1',
          'backing_report_number',v_backing_report_number,
          'report_scope_id',v_report_scope_id,'source_row_ordinal',v_row.source_row_ordinal,
          'upload_row_id',v_row.id,'row_resolution_id',v_row.resolution_id,
          'work_date',v_row.work_date,'start_at_local',v_row.start_at_local,
          'end_at_local',v_row.end_at_local,'break_minutes',v_row.break_minutes,
          'actual_net_minutes',v_row.actual_net_minutes,
          'source_commission_pence',v_row.source_commission_pence,
          'source_total_cost_pence',v_row.source_total_cost_pence,
          'source_shift_charge_pence',v_row.source_shift_charge_pence,
          'calculated_comparison_charge_pence',v_economic.calculated_charge_pence,
          'comparison_result',v_charge_check.comparison_result,
          'price_admission_result',v_price_admission_result,
          'charge_acceptance_id',v_charge_acceptance.id,
          'physical_sign',case when v_economic.row_sign=1
            then 'POSITIVE' else 'FULL_NEGATIVE' end
        ),null,null
      );
      v_source_total_cost:=v_source_total_cost+v_row.source_total_cost_pence;
      v_source_commission:=v_source_commission+v_row.source_commission_pence;
      v_source_invoice_total:=v_source_invoice_total+v_row.source_shift_charge_pence;
      v_line_count:=v_line_count+1;
      v_movement_count:=v_movement_count+1;
    end loop;
    if v_line_count<>v_upload.accepted_count
       or v_source_invoice_total<>v_source_total_cost+v_source_commission then
      raise exception 'WEEKLY_SOURCE_NHSP_REPORT_TOTAL_INVALID' using errcode='55000';
    end if;
    insert into public.weekly_source_nhsp_backing_reports(
      report_scope_id,final_revision_id,upload_id,client_id,backing_report_number,
      cutoff_at_utc,physical_line_count,source_total_cost_pence,
      source_commission_pence,source_invoice_total_pence,row_manifest_hash
    ) values (
      v_report_scope_id,v_revision_id,v_upload.id,v_client_id,v_backing_report_number,
      v_scope.cutoff_at_utc,v_line_count,v_source_total_cost,v_source_commission,
      v_source_invoice_total,v_upload.row_manifest_hash
    );
  end if;

  for v_round_scope in select distinct movement.actual_client_id client_id,
      private.weekly_source_invoice_movement_window_id_v1(movement.id) invoice_window_cycle_id
    from public.weekly_source_billing_movements movement where movement.final_revision_id=v_revision_id
      and movement.source_line_kind<>'INVOICE_VAT_ROUNDING'
    order by client_id,invoice_window_cycle_id
  loop
    if not(v_round_scope.invoice_window_cycle_id=any(v_invoice_window_ids)) then
      raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SET_GREW_AFTER_LOCK' using errcode='40001'; end if;
    v_round_id:=private.weekly_source_vat_rounding_movement_insert_v1(v_revision_id,v_round_scope.client_id,null,v_round_scope.invoice_window_cycle_id);
    if v_round_id is not null then v_movement_count:=v_movement_count+1; end if;
  end loop;
  for v_manifest in
    select scope.client_id,scope.invoice_window_cycle_id,actual.finalisation_week_ending as invoice_week_ending
    from (select movement.actual_client_id as client_id,
      private.weekly_source_invoice_movement_window_id_v1(movement.id) as invoice_window_cycle_id
      from public.weekly_source_billing_movements movement where movement.final_revision_id=v_revision_id
      union select v_client_id,v_cycle.id) scope
    join public.weekly_source_cycles actual on actual.id=scope.invoice_window_cycle_id
    where scope.client_id is not null order by scope.client_id,scope.invoice_window_cycle_id
  loop
    select private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_CLIENT_MANIFEST_V1',
      pg_catalog.jsonb_build_object(
        'final_revision_id',v_revision_id,'source_group_id',v_group.id,
        'source_cycle_id',v_cycle.id,'client_id',v_manifest.client_id,
        'finalisation_week_ending',v_manifest.invoice_week_ending,
        'backing_report_number',v_backing_report_number,
        'movements',coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'movement_id',movement.id,
          'movement_economic_hash',pg_catalog.encode(movement.movement_economic_hash,'hex')
        ) order by pg_catalog.encode(movement.movement_economic_hash,'hex')),
        '[]'::jsonb),
        'expense_authorities',coalesce((
          select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'expense_authority_generation_id',expense.id,
            'authority_hash',pg_catalog.encode(expense.authority_hash,'hex')
          ) order by pg_catalog.encode(expense.authority_hash,'hex'))
          from public.weekly_expense_authority_generations expense
          join public.weekly_work_events event on event.id=expense.work_event_id
          where expense.final_revision_id=v_revision_id and event.client_id=v_manifest.client_id
            and v_manifest.invoice_window_cycle_id=v_cycle.id
        ),'[]'::jsonb)
      )||case when v_manifest.invoice_window_cycle_id=v_cycle.id then '{}'::jsonb else jsonb_build_object('invoice_window_cycle_id',v_manifest.invoice_window_cycle_id) end
      ||case when v_rule_version is null then '{}'::jsonb else jsonb_build_object('rule_set_version_id',v_rule_version,'rule_set_values_sha256',v_rule_set->>'values_sha256') end
    ) into v_client_manifest_hash
    from public.weekly_source_billing_movements movement
    where movement.final_revision_id=v_revision_id
      and movement.actual_client_id=v_manifest.client_id
      and private.weekly_source_invoice_movement_window_id_v1(movement.id)=v_manifest.invoice_window_cycle_id;
    insert into public.weekly_source_client_manifests(
      final_revision_id,source_group_id,source_cycle_id,invoice_window_cycle_id,client_id,
      finalisation_week_ending,backing_report_number,manifest_hash,movement_count,
      unchanged_snapshot_count,expense_line_count,invoice_state
    ) values (
      v_revision_id,v_group.id,v_cycle.id,case when v_manifest.invoice_window_cycle_id=v_cycle.id then null else v_manifest.invoice_window_cycle_id end,v_manifest.client_id,
      v_manifest.invoice_week_ending,v_backing_report_number,v_client_manifest_hash,
      (select pg_catalog.count(*)::integer
       from public.weekly_source_billing_movements movement
       where movement.final_revision_id=v_revision_id
         and movement.actual_client_id=v_manifest.client_id
         and private.weekly_source_invoice_movement_window_id_v1(movement.id)=v_manifest.invoice_window_cycle_id),
      (select pg_catalog.count(*)::integer
       from public.weekly_source_state_transitions transition_row
       join public.weekly_source_final_snapshot_lines snapshot_line
         on snapshot_line.id=transition_row.new_snapshot_line_id
       where transition_row.final_revision_id=v_revision_id
         and transition_row.outcome='NO_CHANGE'
         and snapshot_line.client_id=v_manifest.client_id
         and v_manifest.invoice_window_cycle_id=v_cycle.id),
      (select pg_catalog.count(*)::integer
       from public.weekly_expense_authority_generations expense
       join public.weekly_work_events event on event.id=expense.work_event_id
       where expense.final_revision_id=v_revision_id
         and event.client_id=v_manifest.client_id
         and v_manifest.invoice_window_cycle_id=v_cycle.id),
      'READY'
    ) returning id into v_client_manifest_id;
    insert into public.weekly_source_manifest_movements(
      client_manifest_id,billing_movement_id,manifest_ordinal,movement_hash
    )
    select v_client_manifest_id,movement.id,
           pg_catalog.row_number() over(
             order by pg_catalog.encode(movement.movement_economic_hash,'hex')
           )::integer,
           movement.movement_economic_hash
    from public.weekly_source_billing_movements movement
    where movement.final_revision_id=v_revision_id
      and movement.actual_client_id=v_manifest.client_id
      and private.weekly_source_invoice_movement_window_id_v1(movement.id)=v_manifest.invoice_window_cycle_id;
  end loop;


  if v_finalisation_lock_operation is not null then
    -- Includes the later positive-expense lineage calls. Advisory/row locks
    -- remain transaction-held; remove only this operation's working copies.
    perform private.bpay_next_source_current_lock_release_v1(v_finalisation_lock_operation);
  end if;
  if v_finalisation_lock_context then
    perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation',v_prior_finalisation_lock_operation,true);
    perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set',v_prior_finalisation_root_set,true);
  end if;

  if p_prepare_only then
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','PREPARED','idempotent',false,
      'final_revision_id',v_revision_id,'source_cycle_id',v_cycle.id,
      'authority_scope_kind',v_scope_kind,'report_scope_id',v_report_scope_id,
      'upload_id',v_upload.id,'profile_code',v_profile.profile_code,
      'client_id',v_client_id,'snapshot_count',v_snapshot_count,
      'transition_count',v_transition_count,'movement_count',v_movement_count,
      'unchanged_count',v_unchanged_count,
      'expense_generation_count',v_expense_generation_count
    );
  end if;

  update public.weekly_source_client_cycle_completions completion
  set state='SUPERSEDED',superseded_at_utc=v_finalised_at
  where completion.source_cycle_id=v_cycle.id
    and completion.client_id=v_client_id and completion.state='CURRENT';
  select coalesce(pg_catalog.max(completion.completion_generation),0)+1
  into v_completion_generation
  from public.weekly_source_client_cycle_completions completion
  where completion.source_cycle_id=v_cycle.id and completion.client_id=v_client_id;
  v_completion_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CLIENT_CYCLE_COMPLETION_V1',
    pg_catalog.jsonb_build_object(
      'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
      'client_id',v_client_id,'completion_generation',v_completion_generation,
      'completion_kind','FINAL_SOURCE','final_revision_id',v_revision_id,
      'actor_user_id',v_actor
    )
  );
  insert into public.weekly_source_client_cycle_completions(
    source_cycle_id,source_group_id,client_id,completion_generation,
    completion_kind,final_revision_id,attested_by_user_id,attested_at_utc,
    attestation_text,completion_hash,state
  ) values (
    v_cycle.id,v_group.id,v_client_id,v_completion_generation,
    'FINAL_SOURCE',v_revision_id,v_actor,v_finalised_at,null,v_completion_hash,'CURRENT'
  );

  if v_scope_kind='CYCLE' then
    update public.weekly_source_cycles
    set current_final_revision_id=v_revision_id,state='FINALISED',
        finalised_at_utc=v_finalised_at,finalised_by_user_id=v_actor
    where id=v_cycle.id and current_complete_upload_id=v_upload.id
      and current_projection_publication_id=v_publication.id
      and version=v_scope_version and current_final_revision_id is null;
    if not found then
      raise exception 'WEEKLY_SOURCE_FINALISE_CAS_LOST' using errcode='40001';
    end if;
  else
    update public.weekly_source_report_scopes
    set current_final_revision_id=v_revision_id,state='FINALISED',
        updated_at_utc=v_finalised_at
    where id=v_scope.id and current_complete_upload_id=v_upload.id
      and current_projection_publication_id=v_publication.id
      and version=v_scope_version and current_final_revision_id is null;
    if not found then
      raise exception 'WEEKLY_SOURCE_FINALISE_CAS_LOST' using errcode='40001';
    end if;
    if not exists(
      select 1
      from public.weekly_source_group_clients membership
      where membership.source_group_id=v_group.id
        and v_cycle.finalisation_week_ending between membership.valid_from
          and coalesce(membership.valid_to,'infinity'::date)
        and not exists(
          select 1
          from public.weekly_source_client_cycle_completions completion
          where completion.source_cycle_id=v_cycle.id
            and completion.client_id=membership.client_id
            and completion.state='CURRENT'
        )
    ) then
      update public.weekly_source_cycles
      set state='FINALISED',finalised_at_utc=v_finalised_at,
          finalised_by_user_id=v_actor
      where id=v_cycle.id;
    else
      update public.weekly_source_cycles
      set state='FINALISABLE'
      where id=v_cycle.id and state in ('OPEN','FINALISABLE');
    end if;
  end if;

  -- Only this genuine new CURRENT transition may resolve contained manual
  -- queries. PREPARED and retained Final replay returned earlier. Query-only
  -- resolution shares this transaction; it never changes frozen pay or money.
  perform private.weekly_source_manual_reviews_finalised_v1(v_revision_id,v_actor);

  -- PREPARED returned above and remains invisible. Capture only AFTER the
  -- real cycle/report CURRENT CAS; any failure rolls back Source and selector
  -- together. The same immutable economic/lineage facts remain authoritative.
  if coalesce(v_next_source_hooks,false) then
    perform private.bpay_next_source_current_publish_revision_v1(v_revision_id);
  end if;

  if p_correction_session_id is null and exists(
    select 1
    from public.weekly_source_cycles cycle
    where cycle.id=v_cycle.id and cycle.state='FINALISED'
  ) then
    perform private._weekly_source_settings_ensure_open_cycle_v1(
      v_group.id,v_finalised_at
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'status',case when p_correction_session_id is null
      then 'FINALISED' else 'CORRECTED' end,'idempotent',false,
    'final_revision_id',v_revision_id,'source_cycle_id',v_cycle.id,
    'authority_scope_kind',v_scope_kind,'report_scope_id',v_report_scope_id,
    'upload_id',v_upload.id,'profile_code',v_profile.profile_code,
    'client_id',v_client_id,'snapshot_count',v_snapshot_count,
    'transition_count',v_transition_count,'movement_count',v_movement_count,
    'unchanged_count',v_unchanged_count,
    'expense_generation_count',v_expense_generation_count
  );
exception
  when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then
    -- The function subtransaction already rolled back Source/cache/control
    -- writes on entry to this handler. Restore only the caller's exact GUCs.
    if v_finalisation_lock_context then
      perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation',v_prior_finalisation_lock_operation,true);
      perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set',v_prior_finalisation_root_set,true);
    end if;
    raise exception 'WEEKLY_SOURCE_FINALISE_VALUE_INVALID' using errcode='22023';
  when others then
    if v_finalisation_lock_context then
      perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation',v_prior_finalisation_lock_operation,true);
      perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set',v_prior_finalisation_root_set,true);
    end if;
    raise;
end;
$function$;

-- Complete F8/NHSP released-client owner plus exact report branch.
create or replace function public.weekly_source_upload_context_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_allowed constant text[]:=array[
    'operation','actor_user_id','source_group_id','source_cycle_id',
    'report_scope_id','client_id','upload_id'
  ]::text[];
  v_operation text;
  v_actor uuid;
  v_group_id uuid;
  v_cycle_id uuid;
  v_report_scope_id uuid;
  v_client_id uuid;
  v_row_client_id uuid;
  v_upload_id uuid;
  v_group public.weekly_source_groups%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_source_row public.weekly_source_upload_rows%rowtype;
  v_office_choice private.weekly_source_office_row_choices%rowtype;
  v_source_name text;
  v_source_id text;
  v_source_id_2 text;
  v_source_id_3 text;
  v_source_client text;
  v_norm_name text;
  v_norm_compact text;
  v_candidate_ids uuid[];
  v_candidate_id uuid;
  v_candidate_matches jsonb;
  v_contracts jsonb;
  v_prior_contract_id uuid;
  v_prior_work_event_id uuid;
  -- WP-37: the `24 §9` step-2 compatible-schedule set, counted explicitly.
  v_prior_candidate_count integer;
  v_rows jsonb:='[]'::jsonb;
  v_client_name text;
  v_client_choices jsonb:='[]'::jsonb;
  v_client_choice_count integer:=0;
  v_unknown text;
  v_coverage_context jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CONTEXT_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown
  from pg_catalog.jsonb_object_keys(p_request) key
  where not key=any(v_allowed)
  order by key limit 1;
  if v_unknown is not null then
    raise exception 'WEEKLY_SOURCE_CONTEXT_UNKNOWN_FIELD'
      using errcode='22023',detail=v_unknown;
  end if;
  begin
    v_operation:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'operation','')));
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_group_id:=nullif(p_request->>'source_group_id','')::uuid;
    v_cycle_id:=nullif(p_request->>'source_cycle_id','')::uuid;
    v_report_scope_id:=nullif(p_request->>'report_scope_id','')::uuid;
    v_client_id:=nullif(p_request->>'client_id','')::uuid;
    v_upload_id:=nullif(p_request->>'upload_id','')::uuid;
  exception when invalid_text_representation then
    raise exception 'WEEKLY_SOURCE_CONTEXT_REQUEST_INVALID' using errcode='22023';
  end;
  if v_actor is null or v_operation not in ('DISCOVER_SCOPE','BUILD_PROJECTION') then
    raise exception 'WEEKLY_SOURCE_CONTEXT_REQUEST_INVALID' using errcode='22023';
  end if;

  if v_operation='BUILD_PROJECTION' then
    if v_upload_id is null then
      raise exception 'WEEKLY_SOURCE_CONTEXT_UPLOAD_REQUIRED' using errcode='22023';
    end if;
    select * into v_upload from public.weekly_source_uploads where id=v_upload_id;
    if not found or v_upload.state not in ('CURRENT','CORRECTION_READY')
       or v_upload.row_manifest_hash is null then
      raise exception 'WEEKLY_SOURCE_CONTEXT_UPLOAD_NOT_SEALED' using errcode='55000';
    end if;
    v_cycle_id:=v_upload.source_cycle_id;
    v_report_scope_id:=v_upload.report_scope_id;
  elsif v_cycle_id is null then
    raise exception 'WEEKLY_SOURCE_CONTEXT_SCOPE_REQUIRED' using errcode='22023';
  end if;

  select * into v_cycle from public.weekly_source_cycles where id=v_cycle_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CONTEXT_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select * into v_group from public.weekly_source_groups where id=v_cycle.source_group_id;
  if not found or not v_group.active
     or (v_group_id is not null and v_group.id is distinct from v_group_id) then
    raise exception 'WEEKLY_SOURCE_CONTEXT_GROUP_MISMATCH' using errcode='22023';
  end if;
  v_group_id:=v_group.id;

  if v_report_scope_id is not null then
    select * into v_scope
    from public.weekly_source_report_scopes where id=v_report_scope_id;
    if not found or not ((v_group.source_family='NHSP' and v_scope.self_bill_report_id is null)
      or (v_group.source_family='ROSTER' and v_scope.self_bill_report_id is not null))
       or v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id
       or v_scope.environment is distinct from v_group.environment
       or v_scope.agency_id is distinct from v_group.agency_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc
       or (v_client_id is not null and v_scope.client_id is distinct from v_client_id) then
      raise exception 'WEEKLY_SOURCE_CONTEXT_REPORT_SCOPE_MISMATCH' using errcode='22023';
    end if;
    v_client_id:=v_scope.client_id;
    if v_scope.self_bill_report_id is not null then
      perform private.weekly_source_self_bill_report_rules_assert_v1(v_client_id,v_cycle.id);
    end if;
  else
    if v_group.source_family='NHSP' and v_operation='BUILD_PROJECTION'
       and exists(
         select 1 from public.weekly_source_format_profiles profile
         where profile.id=v_upload.source_format_profile_id
           and profile.profile_code='NHSP_FINAL_BACKING_V1'
       ) then
      raise exception 'WEEKLY_SOURCE_CONTEXT_REPORT_SCOPE_REQUIRED' using errcode='22023';
    end if;
    if v_operation='BUILD_PROJECTION' then
      begin
        v_client_id:=nullif(v_upload.file_metadata_json->>'client_id','')::uuid;
      exception when invalid_text_representation then
        raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_INVALID' using errcode='55000';
      end;
    end if;
    if v_client_id is not null and not exists(
      select 1 from public.weekly_source_group_clients membership
      where membership.source_group_id=v_group.id
        and membership.client_id=v_client_id
        and v_cycle.finalisation_week_ending between membership.valid_from
          and coalesce(membership.valid_to,'infinity'::date)
    ) then
      raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_SCOPE_MISMATCH' using errcode='22023';
    end if;
  end if;
  if v_client_id is not null then
    if v_operation='BUILD_PROJECTION' and v_cycle.scope_client_id is not null and v_cycle.scope_client_id<>v_client_id then
      raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_SCOPE_MISMATCH' using errcode='22023';
    end if;
    select client.name into strict v_client_name
    from public.clients client where client.id=v_client_id;
  elsif v_group.source_family='ROSTER' then
    select pg_catalog.count(*),coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object('client_id',client.id,'client_name',client.name)
      order by client.name,client.id
    ),'[]'::jsonb)
      into v_client_choice_count,v_client_choices
    from public.weekly_source_group_clients membership
    join public.clients client on client.id=membership.client_id
    where membership.source_group_id=v_group.id
      and v_cycle.finalisation_week_ending between membership.valid_from
        and coalesce(membership.valid_to,'infinity'::date);
    if v_client_choice_count=1 then
      v_client_id:=(v_client_choices->0->>'client_id')::uuid;
      v_client_name:=v_client_choices->0->>'client_name';
    elsif v_client_choice_count=0 then
      raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_NOT_FOUND' using errcode='22023';
    end if;
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,
    case when v_operation='DISCOVER_SCOPE' then 'UPLOAD_SOURCE' else 'RECHECK_SOURCE' end,
    v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );

  if v_operation='BUILD_PROJECTION' and v_scope.self_bill_report_id is not null then
    perform private.weekly_source_self_bill_report_seal_assert_v1(v_upload.id);
    select * into strict v_publication from public.weekly_source_projection_publications
      where upload_id=v_upload.id and authority_scope_kind='SELF_BILL_REPORT_SCOPE'
        and report_scope_id=v_scope.id and authority_scope_version=v_scope.version and state in ('BUILDING','CURRENT');
    return jsonb_build_object('ok',true,'context_version','WEEKLY_SOURCE_UPLOAD_CONTEXT_V1',
      'environment',v_group.environment,'agency_id',v_group.agency_id,'source_family',v_group.source_family,
      'source_group_id',v_group.id,'source_cycle_id',v_cycle.id,'report_scope_id',v_scope.id,
      'client_id',v_client_id,'client_name',v_client_name,'upload_id',v_upload.id,
      'authority_scope_kind','SELF_BILL_REPORT_SCOPE','authority_scope_version',v_scope.version,
      'profile_id','ACACIUM_SELF_BILL_REPORT_V1','self_bill_report_id',v_scope.self_bill_report_id,
      'effective_rule_set',private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle.id),
      'row_manifest_hash',encode(v_upload.row_manifest_hash,'hex'),
      'projection_publication_id',v_publication.id,'projection_state',v_publication.state,
      'comparison_manifest_hash',encode(v_publication.comparison_manifest_hash,'hex'),
      'issue_set_hash',encode(v_publication.issue_set_hash,'hex'),'invoice_only',true,'rows','[]'::jsonb);
  end if;
  if v_operation='DISCOVER_SCOPE' then
    if v_scope.self_bill_report_id is null then
      v_coverage_context:=private.weekly_source_upload_coverage_context_v1(v_client_id,v_cycle.id);
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'context_version','WEEKLY_SOURCE_UPLOAD_CONTEXT_V1',
      'environment',v_group.environment,'agency_id',v_group.agency_id,
      'source_group_id',v_group.id,'source_group_code',v_group.code,
      'source_group_name',v_group.display_name,'source_family',v_group.source_family,
      'source_cycle_id',v_cycle.id,'finalisation_week_ending',v_cycle.finalisation_week_ending,
      'cutoff_at_utc',v_cycle.cutoff_at_utc,'cycle_state',v_cycle.state,
      'previous_coverage',(
        select pg_catalog.jsonb_build_object(
          'start_local_date',prior.confirmed_coverage_start_local_date,
          'end_local_date',prior.confirmed_coverage_end_local_date
        )
        from public.weekly_source_uploads prior
        where prior.id=case when v_report_scope_id is null then v_cycle.current_complete_upload_id else v_scope.current_complete_upload_id end
          and prior.state='CURRENT'
      ),
      'report_scope_id',v_report_scope_id,'client_id',v_client_id,
      'client_name',v_client_name,'nhsp_report_heading_name',v_group.nhsp_report_heading_name,
      'effective_rule_set',private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle.id),
      'client_selection_required',v_group.source_family='ROSTER' and v_client_id is null,
      'client_choices',v_client_choices,
      'authority_scope_version',case when v_report_scope_id is null then v_cycle.version else v_scope.version end,
      'authority_scope_kind',case when v_report_scope_id is null then 'CYCLE'
        when v_scope.self_bill_report_id is null then 'NHSP_REPORT_SCOPE' else 'SELF_BILL_REPORT_SCOPE' end
    )||case when v_scope.self_bill_report_id is null then '{}'::jsonb
      else jsonb_build_object('self_bill_report_id',v_scope.self_bill_report_id) end
      ||case when v_coverage_context is null then '{}'::jsonb
      else jsonb_build_object('coverage_context',v_coverage_context) end;
  end if;

  select * into strict v_profile
  from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;

  for v_source_row in
    select source_row.*
    from public.weekly_source_upload_rows source_row
    where source_row.upload_id=v_upload.id
    order by source_row.source_row_ordinal,source_row.id
  loop
    -- Released reports identify the client on each row. A legacy upload-level
    -- client hint must not silently assign every row to that one client.
    v_row_client_id:=case when v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1'
      then null else v_client_id end;
    select * into v_office_choice from private.weekly_source_office_row_choices
      where upload_row_id=v_source_row.id order by id desc limit 1;
    v_source_name:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'worker_name',
      v_source_row.bounded_raw_columns_json->>'candidate',
      v_source_row.source_candidate_identity
    )), '');
    v_source_id:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'worker_unique_id',
      v_source_row.bounded_raw_columns_json->>'candidate_id',''
    )), '');
    v_source_id_2:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'candidate_uid',''
    )), '');
    v_source_id_3:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'payroll_number',''
    )), '');
    v_source_client:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'trust',
      v_source_row.source_client_identity
    )), '');
    if v_row_client_id is null and v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1' then
      select case when pg_catalog.count(*)=1 then pg_catalog.min(client.id::text)::uuid end
        into v_row_client_id
      from public.clients client
      where private.weekly_source_upload_client_eligible_v1(
          v_upload.id,client.id,v_source_row.work_date)
        and pg_catalog.lower(pg_catalog.btrim(client.name))=
          pg_catalog.lower(pg_catalog.btrim(coalesce(v_source_client,'')));
    end if;
    if v_office_choice.client_id is not null then
      select client.id into v_row_client_id
      from public.clients client
      where client.id=v_office_choice.client_id
        and private.weekly_source_upload_client_eligible_v1(
          v_upload.id,client.id,v_source_row.work_date);
    end if;
    v_norm_name:=pg_catalog.lower(pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(v_source_name,'')),'[[:space:]]+',' ','g'
    ));
    v_norm_compact:=pg_catalog.regexp_replace(v_norm_name,'[^a-z0-9]+','','g');

    select coalesce(pg_catalog.array_agg(candidate_id order by candidate_id),'{}'::uuid[])
      into v_candidate_ids
    from (
      select distinct candidate.id as candidate_id
      from public.candidates candidate
      where candidate.active
        and (
          (v_source_id is not null and pg_catalog.lower(pg_catalog.btrim(candidate.tms_ref))=
             pg_catalog.lower(v_source_id))
          or (v_source_id_2 is not null and pg_catalog.lower(pg_catalog.btrim(candidate.tms_ref))=
             pg_catalog.lower(v_source_id_2))
          or (v_source_id_3 is not null and pg_catalog.lower(pg_catalog.btrim(candidate.tms_ref))=
             pg_catalog.lower(v_source_id_3))
          or exists(
            select 1
            from pg_catalog.jsonb_array_elements_text(
              case when pg_catalog.jsonb_typeof(candidate.nhsp_hr_name_aliases)='array'
                then candidate.nhsp_hr_name_aliases else '[]'::jsonb end
            ) alias(value)
            where pg_catalog.lower(pg_catalog.btrim(alias.value))=v_norm_name
               or pg_catalog.regexp_replace(pg_catalog.lower(alias.value),'[^a-z0-9]+','','g')=v_norm_compact
          )
          or exists(
            select 1 from public.hr_name_mappings mapping
            where mapping.active and mapping.candidate_id=candidate.id
              and (
                pg_catalog.lower(pg_catalog.btrim(mapping.hr_name_norm))=v_norm_name
                or pg_catalog.regexp_replace(pg_catalog.lower(mapping.hr_name_norm),'[^a-z0-9]+','','g')=v_norm_compact
              )
              and (nullif(pg_catalog.btrim(coalesce(mapping.hospital_or_trust,'')),'') is null
                or pg_catalog.lower(pg_catalog.btrim(mapping.hospital_or_trust))=
                   pg_catalog.lower(pg_catalog.btrim(coalesce(v_source_client,''))))
          )
        )
    ) exact_saved;
    if v_office_choice.candidate_id is not null then
      select coalesce(pg_catalog.array_agg(id),'{}'::uuid[]) into v_candidate_ids
        from public.candidates where id=v_office_choice.candidate_id and active;
    end if;
    v_candidate_id:=case when pg_catalog.cardinality(v_candidate_ids)=1 then v_candidate_ids[1] end;
    select coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'candidate_id',candidate.id,'display_name',coalesce(nullif(candidate.display_name,''),
          pg_catalog.btrim(coalesce(candidate.first_name,'')||' '||coalesce(candidate.last_name,''))),
        'tms_ref',candidate.tms_ref
      ) order by candidate.id
    ),'[]'::jsonb) into v_candidate_matches
    from public.candidates candidate where candidate.id=any(v_candidate_ids);

    v_contracts:='[]'::jsonb;
    v_prior_contract_id:=null;
    v_prior_work_event_id:=null;
    v_prior_candidate_count:=0;
    if v_candidate_id is not null and v_row_client_id is not null then
      select coalesce(pg_catalog.jsonb_agg(contract_item order by contract_item->>'contract_id'),'[]'::jsonb)
        into v_contracts
      from (
        select pg_catalog.jsonb_build_object(
          'contract_id',contract.id,
          'candidate_id',contract.candidate_id,
          'client_id',contract.client_id,
          'valid_from',contract.start_date,
          'valid_to',contract.end_date,
          'display_label',pg_catalog.concat_ws(' · ',nullif(contract.role,''),nullif(contract.band,''),nullif(contract.display_site,'')),
          'role',contract.role,'band',contract.band,
          'pay_type',contract.pay_method_snapshot,
          'rates_json',contract.rates_json,
          'contract_updated_at',contract.updated_at,
          'weekly_source_applicable',true,
          'schedule_compatible',private.weekly_source_schedule_compatible_v1(
            contract.std_schedule_json,v_source_row.work_date
          ),
          'verified_role_band_match',private.weekly_source_verified_role_band_match_v1(
            case when v_profile.profile_code in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1')
              then 'NHSP' else 'HR_WEEKLY' end,
            v_source_row.role_band_source,v_candidate_id,v_row_client_id,
            contract.id,contract.band,v_source_row.work_date
          ),
          'effective_policy',private._weekly_source_effective_policy_v1(
            v_row_client_id,contract.id,v_source_row.work_date
          ),
          'effective_rule_set',private.weekly_source_effective_rule_set_v1(v_row_client_id,v_cycle.id),
          'settings_authority',private._contract_settings_effective_core_v1(
            v_row_client_id,contract.id,v_source_row.work_date,'IMPORT',null
          )
        ) contract_item
        from public.contracts contract
        where contract.candidate_id=v_candidate_id
          and contract.client_id=v_row_client_id
          and v_source_row.work_date between contract.start_date and coalesce(contract.end_date,'infinity'::date)
      ) eligible;

      -- G6-13 / XSG-010.  Only the three roster profiles use the source
      -- system's own line identity as the durable work-event key.  An NHSP
      -- Reference Number is evidence, never sole durable identity
      -- (`24 §9`; `25 §7` Removed), so NHSP lineage resolves through the
      -- schedule tuple below, exactly as the publication owner now keys it.
      if v_profile.profile_code in (
        'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
        'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1',
        'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1'
      ) and nullif(pg_catalog.btrim(coalesce(v_source_row.external_source_key,'')),'') is not null then
        select event.id,resolution.contract_id
          into v_prior_work_event_id,v_prior_contract_id
        from public.weekly_work_events event
        left join lateral (
          select saved.contract_id
          from public.weekly_source_row_resolutions saved
          where saved.work_event_id=event.id and saved.mapping_state='RESOLVED'
          order by saved.created_at_utc desc,saved.id desc limit 1
        ) resolution on true
        where event.first_source_group_id=v_group.id
          and event.source_format_profile_id=v_profile.id
          and event.identity_kind='PROFILE_EXTERNAL_KEY'
          and event.profile_external_key=v_source_row.external_source_key
          and event.candidate_id=v_candidate_id and event.client_id=v_row_client_id
        order by event.created_at_utc,event.id limit 1;
      else
        -- WP-37, against `24 §9` step 2.  The pack keys identity on "exact
        -- Candidate, actual Client, worked date and **compatible** schedule",
        -- so lineage must NOT demand exact Actual start and end: `24 §6.2`
        -- ("Paid eight hours becomes nine") is a later source change on ONE
        -- root, and an NHSP correction routinely moves the times.  The
        -- cardinality is checked explicitly: none means new work, and more than
        -- one is `24 §9` step 4 (Office confirmation), where nothing is
        -- suggested and the server refuses to guess.
        select pg_catalog.count(*)::integer,
               pg_catalog.min(event.id::text)::uuid
          into v_prior_candidate_count,v_prior_work_event_id
        from public.weekly_work_events event
        where event.first_source_group_id=v_group.id
          and event.source_format_profile_id=v_profile.id
          and event.identity_kind='SCHEDULE_TUPLE'
          and event.candidate_id=v_candidate_id and event.client_id=v_row_client_id
          and event.work_date=v_source_row.work_date
          and private.weekly_source_work_event_schedule_compatible_v1(
                event.id,v_source_row.start_at_local,v_source_row.end_at_local
              );
        if v_prior_candidate_count<>1 then
          v_prior_work_event_id:=null;
        else
          -- The Contract is a SUGGESTION only: `weekly_source_projection_build_v1`
          -- re-proves DURABLE_LINEAGE against a prior RESOLVED resolution for
          -- this same work event before it will accept the selection method.
          select saved.contract_id into v_prior_contract_id
          from public.weekly_source_row_resolutions saved
          where saved.work_event_id=v_prior_work_event_id
            and saved.mapping_state='RESOLVED'
          order by saved.created_at_utc desc,saved.id desc limit 1;
        end if;
      end if;
    end if;

    v_rows:=v_rows||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'upload_row_id',v_source_row.id,
      'source_row_ordinal',v_source_row.source_row_ordinal,
      'external_source_key',v_source_row.external_source_key,
      'source_candidate_identity',v_source_row.source_candidate_identity,
      'source_client_identity',v_source_row.source_client_identity,
      'work_date',v_source_row.work_date,
      'start_at_local',v_source_row.start_at_local,
      'end_at_local',v_source_row.end_at_local,
      'break_minutes',v_source_row.break_minutes,
      'actual_net_minutes',v_source_row.actual_net_minutes,
      'row_finalisation_state',v_source_row.row_finalisation_state,
      'role_band_source',v_source_row.role_band_source,
      'source_commission_pence',v_source_row.source_commission_pence,
      'source_total_cost_pence',v_source_row.source_total_cost_pence,
      'source_shift_charge_pence',v_source_row.source_shift_charge_pence,
      'source_gross_pence',v_source_row.source_gross_pence,'source_vat_pence',v_source_row.source_vat_pence,
      'finalised_at_utc',v_source_row.finalised_at_utc,
      'source_money_parse_state',v_source_row.source_money_parse_state,
      'source_expense_pence',v_source_row.source_expense_pence,
      'source_expense_parse_state',v_source_row.source_expense_parse_state,
      'candidate_match_count',pg_catalog.cardinality(v_candidate_ids),
      'candidate_matches',v_candidate_matches,
      'candidate_id',v_candidate_id,
      'office_selected_contract_id',v_office_choice.contract_id,
      'office_selected_work_event_id',v_office_choice.work_event_id,
      'office_separate_shift',coalesce(v_office_choice.separate_shift,false),
      'protected_matches',private.weekly_source_protected_match_candidates_v1(v_source_row.id,v_candidate_id,v_row_client_id),
      'client_id',v_row_client_id,
      'contracts',v_contracts,
      'prior_accepted_contract_id',v_prior_contract_id,
      'prior_work_event_id',v_prior_work_event_id,
      -- `24 §9` step 4.  True means more than one plausible existing work
      -- record remains, so Office must confirm the relationship; the server
      -- refuses to publish the row until it does.
      'prior_work_event_ambiguous',v_prior_candidate_count>1
    ));
  end loop;

  if v_upload.correction_session_id is not null then
    select publication.* into v_publication
    from public.weekly_final_source_correction_sessions correction
    join public.weekly_source_projection_publications publication
      on publication.id=correction.replacement_projection_publication_id
    where correction.id=v_upload.correction_session_id
      and correction.replacement_correction_upload_id=v_upload.id
      and publication.upload_id=v_upload.id
      and publication.correction_session_id=correction.id
      and publication.state='CORRECTION_READY';
  else
    select publication.* into v_publication
    from public.weekly_source_projection_publications publication
    where publication.upload_id=v_upload.id
      and publication.state='CURRENT'
    order by publication.published_at_utc desc nulls last,publication.id desc
    limit 1;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'context_version','WEEKLY_SOURCE_PROJECTION_CONTEXT_V1',
    'environment',v_group.environment,'agency_id',v_group.agency_id,
    'source_group_id',v_group.id,'source_family',v_group.source_family,
    'source_cycle_id',v_cycle.id,'report_scope_id',v_report_scope_id,
    'client_id',v_client_id,'client_name',v_client_name,
    'profile_id',v_profile.profile_code,'profile_version',v_profile.version,
    'upload_id',v_upload.id,
    'row_manifest_hash',case when v_upload.row_manifest_hash is null then null
      else pg_catalog.encode(v_upload.row_manifest_hash,'hex') end,
    'projection_publication_id',v_publication.id,
    'projection_state',v_publication.state,
    'comparison_manifest_hash',case when v_publication.comparison_manifest_hash is null then null
      else pg_catalog.encode(v_publication.comparison_manifest_hash,'hex') end,
    'issue_set_hash',case when v_publication.issue_set_hash is null then null
      else pg_catalog.encode(v_publication.issue_set_hash,'hex') end,
    'correction_session_id',v_upload.correction_session_id,
    'correction_session_version',case when v_upload.correction_session_id is null then null else (
      select correction.version
      from public.weekly_final_source_correction_sessions correction
      where correction.id=v_upload.correction_session_id
    ) end,
    'authority_scope_kind',case when v_report_scope_id is null then 'CYCLE' else 'NHSP_REPORT_SCOPE' end,
    'authority_scope_version',coalesce(v_scope.version,v_cycle.version),
    'rows',v_rows
  );
end;
$function$;

-- No public/API surface. Preserve the controlling three-argument FIN ACL.
alter function private.weekly_source_report_projection_receipt_assert_v1(public.weekly_source_ordinary_pay_projection_receipts) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_report_projection_receipt_assert_v1(public.weekly_source_ordinary_pay_projection_receipts) from public,anon,authenticated,service_role;
alter function private.weekly_source_self_bill_report_pay_authority_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_self_bill_report_pay_authority_v1(uuid) from public,anon,authenticated,service_role;
alter function private.weekly_source_self_bill_report_pay_witness_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_self_bill_report_pay_witness_v1(uuid) from public,anon,authenticated,service_role;
alter function private.weekly_source_finalise_engine_v1(jsonb,uuid,boolean,text) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_finalise_engine_v1(jsonb,uuid,boolean,text) from public,anon,authenticated,service_role;
alter function private.weekly_source_self_bill_report_movement_insert_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_self_bill_report_movement_insert_v1(uuid,uuid) from public,anon,authenticated,service_role;
alter function private.weekly_source_self_bill_report_finalise_v1(jsonb,text) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_self_bill_report_finalise_v1(jsonb,text) from public,anon,authenticated,service_role;
alter function private.weekly_source_report_shift_facts_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_report_shift_facts_v1(uuid,uuid) from public,anon,authenticated,service_role;
-- Exact existing public service-only ACL, with no new service surface.
alter function public.weekly_source_upload_context_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_upload_context_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_source_upload_context_v1(jsonb) to CURRENT_USER,service_role;
alter function public.weekly_source_projection_rows_apply_atomic_v1(uuid,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_projection_rows_apply_atomic_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_source_projection_rows_apply_atomic_v1(uuid,uuid,jsonb) to CURRENT_USER,service_role;

notify pgrst, 'reload schema';


-- CONTACT_PREPARER_UNIT 126 repeatable supabase/repeatable/13102026_2205_weekly_source_automatic_native_delta_v1.sql SHA256 b8694c29481d352370363f44d1d2c25b1a8340846f23371d019f75455ae3c563
-- Proposed destination: supabase/repeatable/13102026_2205_weekly_source_automatic_native_delta_v1.sql
-- Root must rebase chronological naming if a later controlling owner exists.


-- Source-only proposal. No receipt, store, calculator, readiness or exposure.
-- Decode only the actual immutable native C1 records and sealed parts. Their
-- transport UUIDs are provenance, never native I1 entitlement component IDs.
create or replace function private.weekly_source_staged_source_documents_v1(p_request_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare r public.weekly_exceptional_c1_publication_requests%rowtype; s record;
  v_payload bytea; v_document jsonb; v_count integer; v_bytes bigint; v_parts integer;
  v_result jsonb:='[]'::jsonb; v_total_bytes bigint:=0; v_ordinal integer:=0;
begin
  select * into strict r from public.weekly_exceptional_c1_publication_requests where id=p_request_id;
  select count(*) into v_count from public.weekly_exceptional_c1_source_records where publication_request_id=r.id;
  if v_count is distinct from r.expected_source_count or v_count<1 then
    raise exception 'WEEKLY_SOURCE_STAGED_SOURCE_UNAVAILABLE' using errcode='55000'; end if;
  for s in select source.* from public.weekly_exceptional_c1_source_records source
    where source.publication_request_id=r.id order by source.source_ordinal loop
    v_ordinal:=v_ordinal+1;
    if s.source_ordinal is distinct from v_ordinal or s.root_timesheet_id is distinct from r.root_timesheet_id
      or s.candidate_id is distinct from r.candidate_id or s.contract_id is distinct from r.contract_id
      or octet_length(s.source_document_sha256) is distinct from 32 or octet_length(s.source_row_sha256) is distinct from 32
      or s.payload_bytes not between 1 and 16384 or s.part_count not between 1 and 6 then
      raise exception 'WEEKLY_SOURCE_STAGED_SOURCE_UNAVAILABLE' using errcode='55000'; end if;
    select count(*),coalesce(sum(octet_length(part.payload_utf8)),0),
      decode(coalesce(string_agg(encode(part.payload_utf8,'hex'),'' order by part.part_ordinal),''),'hex')
      into v_parts,v_bytes,v_payload from public.weekly_exceptional_c1_source_parts part
      where part.publication_request_id=r.id and part.source_record_id=s.id;
    if v_parts is distinct from s.part_count or v_bytes is distinct from s.payload_bytes::bigint
      or exists(select 1 from public.weekly_exceptional_c1_source_parts part
        where part.publication_request_id=r.id and part.source_record_id=s.id
          and (part.source_ordinal is distinct from s.source_ordinal or part.part_ordinal not between 1 and s.part_count
            or octet_length(part.payload_utf8) not between 1 and 3072
            or extensions.digest(part.payload_utf8,'sha256') is distinct from part.fragment_sha256))
      or exists(select 1 from public.weekly_exceptional_c1_source_parts part
        where part.publication_request_id=r.id and part.source_record_id=s.id group by part.part_ordinal having count(*)<>1) then
      raise exception 'WEEKLY_SOURCE_STAGED_SOURCE_UNAVAILABLE' using errcode='55000'; end if;
    v_document:=convert_from(v_payload,'UTF8')::jsonb;
    if jsonb_typeof(v_document) is distinct from 'object'
      or v_document->>'contract' is distinct from ('C1_'||s.authority_kind||'_V1')
      or v_document->>'source_id' is distinct from s.id::text
      or v_document->>'source_system' is distinct from s.source_system
      or v_document->>'external_identity' is distinct from s.external_identity
      or v_document->>'external_revision' is distinct from s.external_revision
      or v_document->>'root_timesheet_id' is distinct from r.root_timesheet_id::text
      or v_document->>'candidate_id' is distinct from r.candidate_id::text
      or v_document->>'contract_id' is distinct from r.contract_id::text
      or v_document->>'week_ending_date' is distinct from r.week_ending_date::text
      or v_document->>'document_sha256' is distinct from encode(s.source_document_sha256,'hex') then
      raise exception 'WEEKLY_SOURCE_STAGED_SOURCE_UNAVAILABLE' using errcode='55000'; end if;
    v_total_bytes:=v_total_bytes+v_bytes;
    v_result:=v_result||jsonb_build_array(jsonb_build_object('source_id',s.id,'source_ordinal',s.source_ordinal,
      'authority_kind',s.authority_kind,'source_system',s.source_system,'external_identity',s.external_identity,
      'external_revision',s.external_revision,'source_document_sha256',encode(s.source_document_sha256,'hex'),
      'source_row_sha256',encode(s.source_row_sha256,'hex'),'payload_bytes',s.payload_bytes,'part_count',s.part_count,
      'work_date',s.work_date,'document',v_document));
  end loop;
  if v_total_bytes is distinct from r.expected_payload_bytes::bigint
    or exists(select 1 from public.weekly_exceptional_c1_source_parts part where part.publication_request_id=r.id
      and not exists(select 1 from public.weekly_exceptional_c1_source_records source
        where source.id=part.source_record_id and source.publication_request_id=r.id)) then
    raise exception 'WEEKLY_SOURCE_STAGED_SOURCE_UNAVAILABLE' using errcode='55000'; end if;
  return v_result;
exception when no_data_found or too_many_rows or invalid_text_representation or character_not_in_repertoire then
  raise exception 'WEEKLY_SOURCE_STAGED_SOURCE_UNAVAILABLE' using errcode='55000';
end;
$function$;
alter function private.weekly_source_staged_source_documents_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_staged_source_documents_v1(uuid) from public,anon,authenticated,service_role;

-- Common actual stage proof extracted from Local v2, usable before a real
-- PREPARING receipt exists. It does not create or pretend that receipt exists.
-- Normalise only the fully proved own K -> K+1 stage increment; every other
-- byte of the complete current-vs-sealed native I1 inventory must match.
create or replace function private.weekly_source_staged_publication_context_v1(p_request_id uuid,p_actor_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare r public.weekly_exceptional_c1_publication_requests%rowtype;
  g public.weekly_exceptional_pay_generations%rowtype; prior public.weekly_exceptional_pay_generations%rowtype;
  family public.weekly_exceptional_pay_target_families%rowtype; run public.weekly_exceptional_orchestration_runs%rowtype;
  a public.weekly_exceptional_payment_approvals%rowtype; event public.weekly_exceptional_pay_family_events%rowtype;
  target public.weekly_exceptional_pay_target_events%rowtype; fin public.timesheets_financials%rowtype;
  stage public.weekly_exceptional_orchestration_steps%rowtype; local_receipt private.weekly_source_local_protected_decision_receipts%rowtype;
  v_scope jsonb; v_inventory jsonb; v_before jsonb; v_snapshot jsonb; v_context jsonb; v_documents jsonb;
  v_before_bound bigint; v_stage_hash bytea; v_policy_hash bytea; v_qualification jsonb; v_count integer;
begin
  if p_request_id is null or p_actor_id is null then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='22023'; end if;
  select * into strict r from public.weekly_exceptional_c1_publication_requests where id=p_request_id;
  select * into strict g from public.weekly_exceptional_pay_generations where id=r.generation_id and family_id=r.family_id;
  select * into strict family from public.weekly_exceptional_pay_target_families where id=r.family_id;
  select * into strict run from public.weekly_exceptional_orchestration_runs where id=r.orchestration_run_id and family_id=family.id;
  select * into strict a from public.weekly_exceptional_payment_approvals
    where creation_orchestration_run_id=run.id and pay_target_family_id=family.id;
  v_scope:=private.weekly_source_pay_query_scope_v1(r.root_timesheet_id);
  if v_scope is null or r.state is distinct from 'READY' or g.lifecycle_state is distinct from 'PENDING_C1'
    or run.state is distinct from 'RUNNING' or run.requested_by_user_id is distinct from p_actor_id
    or a.approved_by_user_id is distinct from p_actor_id or a.withdrawn_at_utc is not null
    or r.agency_id is distinct from family.agency_id or r.candidate_id is distinct from family.candidate_id
    or r.contract_id is distinct from family.contract_id or r.root_timesheet_id is distinct from family.root_timesheet_id
    or r.week_ending_date is distinct from family.week_ending_date or family.root_family_booking_id is distinct from v_scope->>'family_booking_id'
    or v_scope->>'target_family_id' is distinct from family.id::text or v_scope->>'candidate_id' is distinct from family.candidate_id::text
    or v_scope->>'contract_id' is distinct from family.contract_id::text or v_scope->>'client_id' is distinct from a.client_id::text
    or v_scope->>'week_ending_date' is distinct from family.week_ending_date::text
    or a.candidate_id is distinct from family.candidate_id or a.contract_id is distinct from family.contract_id
    or a.week_ending is distinct from family.week_ending_date
    or r.c1_operation_id is not null or r.c1_publication_id is not null or r.c1_head_revision is not null or r.c1_receipt_sha256 is not null
    or family.c1_publication_state is distinct from 'PENDING'
    or family.current_generation_id is distinct from g.prior_generation_id
    or family.current_generation_number+1 is distinct from g.generation_number or r.request_sequence is distinct from g.generation_number::bigint
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',g.complete_next_vector_json)
      is distinct from g.complete_next_vector_hash
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',g.complete_prior_vector_json)
      is distinct from g.complete_prior_vector_hash then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  -- Automatic reconciliation has a real published predecessor. An empty or
  -- initial unapproved family cannot invent an I1 before-position here.
  select * into strict prior from public.weekly_exceptional_pay_generations where id=g.prior_generation_id and family_id=family.id;
  if prior.lifecycle_state is distinct from 'PUBLISHED' or prior.published_at_utc is null or not isfinite(prior.published_at_utc)
    or prior.result_hash is null or prior.generation_number is distinct from family.current_generation_number
    or prior.complete_next_vector_hash is distinct from family.current_complete_target_vector_hash
    or prior.complete_next_vector_json is distinct from g.complete_prior_vector_json
    or prior.complete_next_vector_hash is distinct from g.prior_generation_hash then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  select * into strict event from public.weekly_exceptional_pay_family_events e
    where e.family_id=family.id and e.evidence_approval_id=a.id and e.durable_work_event_id=a.work_event_id
      and not exists(select 1 from public.weekly_exceptional_pay_family_events newer where newer.family_id=e.family_id
        and newer.durable_work_event_id=e.durable_work_event_id and newer.event_sequence>e.event_sequence);
  if event.office_actor_user_id is distinct from p_actor_id or event.work_date is distinct from a.protected_work_date
    or (event.start_at_local,event.end_at_local,event.break_minutes) is distinct from
      (a.protected_start_at_local,a.protected_end_at_local,a.protected_break_minutes)
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_SOURCE_PROPOSAL_V1',event.source_proposal_snapshot_json)
      is distinct from event.source_proposal_hash
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_SCHEDULE_V1',event.fixed_office_target_snapshot_json)
      is distinct from a.signed_schedule_fact_hash or event.fixed_office_target_hash is distinct from a.signed_schedule_fact_hash
    or not exists(select 1 from public.weekly_work_events w where w.id=a.work_event_id and w.candidate_id=family.candidate_id
      and w.client_id=a.client_id and w.work_date=a.protected_work_date) then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  select count(*) into v_count from public.weekly_exceptional_pay_target_events t
    where t.family_id=family.id and t.approval_id=a.id and t.financial_generation_id=g.id
      and t.complete_prior_family_vector_fingerprint=g.complete_prior_vector_hash
      and t.complete_next_family_vector_fingerprint=g.complete_next_vector_hash
      and t.fixed_target_component_snapshot=a.approved_target_pay_components_json;
  if v_count<>1 then raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  select * into strict target from public.weekly_exceptional_pay_target_events
    where financial_generation_id=g.id and family_id=family.id;
  select * into strict fin from public.timesheets_financials where id=r.financial_row_id and timesheet_id=r.root_timesheet_id;
  if not exists(select 1 from public.weekly_exceptional_pay_family_events predecessor
      where predecessor.family_id=event.family_id and predecessor.event_sequence=event.event_sequence-1
        and predecessor.event_hash=event.prior_event_hash)
    or event.event_hash is distinct from private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_FAMILY_EVENT_V1',jsonb_build_object(
      'family_id',family.id,'event_sequence',event.event_sequence,'work_event_id',a.work_event_id,'approval_id',a.id,
      'schedule',event.fixed_office_target_snapshot_json,'source_proposal_hash',encode(event.source_proposal_hash,'hex'),
      'target_vector_hash',encode(g.complete_next_vector_hash,'hex'),'prior_event_hash',encode(event.prior_event_hash,'hex')))
    or target.event_hash is distinct from private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_TARGET_EVENT_V1',jsonb_build_object(
      'family_id',family.id,'event_sequence',target.event_sequence,'approval_id',a.id,'generation_id',g.id,
      'prior_vector_hash',encode(g.complete_prior_vector_hash,'hex'),'next_vector_hash',encode(g.complete_next_vector_hash,'hex'),
      'reason',g.reason,'actor_user_id',p_actor_id))
    or g.fixed_target_source_state_fingerprint is distinct from private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_FIXED_SOURCE_STATE_V1',
      jsonb_build_object('source_cycle_id',a.source_cycle_id,'comparison_revision_id',a.comparison_revision_id,
        'final_revision_id',a.final_revision_id,'source_proposal_hash',encode(event.source_proposal_hash,'hex'),
        'financial_row_id',fin.id,'financial_timesheet_version',fin.timesheet_version))
    or a.approval_hash is distinct from private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_APPROVAL_V1',jsonb_build_object(
      'family_id',family.id,'work_event_id',a.work_event_id,'candidate_id',family.candidate_id,'client_id',a.client_id,
      'contract_id',family.contract_id,'week_ending_date',family.week_ending_date,'schedule_hash',encode(a.signed_schedule_fact_hash,'hex'),
      'evidence_timesheet_id',a.evidence_timesheet_id,'signed_hash',encode(a.signed_submission_hash,'hex'),
      'issue_ids_hash',encode(a.contributing_issue_episode_ids_hash,'hex'),
      'rate_policy_hash',encode(a.contract_rate_policy_source_fingerprint,'hex'),'target_vector_hash',encode(g.complete_next_vector_hash,'hex'),
      'actor_user_id',p_actor_id,'reason',a.approval_reason)) then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  v_snapshot:=g.complete_next_vector_json#>'{target_snapshot,tsfin_snapshot_json}';
  if jsonb_typeof(v_snapshot) is distinct from 'object' or v_snapshot is distinct from a.approved_target_pay_components_json->'tsfin_snapshot_json'
    or a.approved_target_pay_components_json is distinct from g.complete_next_vector_json->'target_snapshot'
    or v_snapshot->>'timesheet_id' is distinct from r.root_timesheet_id::text
    or v_snapshot->>'timesheet_version' is distinct from v_scope->>'root_version' then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  v_before:=g.complete_next_vector_json->'prior_effective_inventory';
  if v_before->>'ok' is distinct from 'true' or v_before#>>'{approval_basis,coverage_complete}' is distinct from 'true'
    or coalesce(v_before#>>'{approval_basis,scope,family_bound_version}','')!~'^(0|[1-9][0-9]*)$'
    or v_before#>>'{approval_basis,scope,target_family_id}' is distinct from family.id::text then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  v_before_bound:=(v_before#>>'{approval_basis,scope,family_bound_version}')::bigint;
  if g.complete_next_vector_json#>>'{protected_component_identity_basis,schema_version}' is distinct from 'WEEKLY_PROTECTED_COMPONENT_MANIFEST_V1'
    or g.complete_next_vector_json#>>'{protected_component_identity_basis,family_id}' is distinct from family.id::text
    or g.complete_next_vector_json#>>'{protected_component_identity_basis,root_timesheet_id}' is distinct from r.root_timesheet_id::text
    or g.complete_next_vector_json#>>'{protected_component_identity_basis,contract_id}' is distinct from family.contract_id::text
    or g.complete_next_vector_json#>>'{protected_component_identity_basis,candidate_id}' is distinct from family.candidate_id::text
    or g.complete_next_vector_json#>>'{protected_component_identity_basis,accepted_schedule_sha256}' is distinct from
      encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPONENT_ACCEPTED_SCHEDULE_V1',
        g.complete_next_vector_json#>'{target_snapshot,actual_schedule_json}'),'hex')
    or g.complete_next_vector_json#>>'{protected_component_identity_basis,calculated_segments_sha256}' is distinct from
      encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPONENT_CALCULATED_SEGMENTS_V1',v_snapshot#>'{invoice_breakdown_json,segments}'),'hex')
    or g.complete_next_vector_json#>>'{protected_component_identity_basis,approved_components_sha256}' is distinct from
      encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPONENT_APPROVED_COMPONENTS_V1',v_before->'components'),'hex') then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  select * into strict stage from public.weekly_exceptional_orchestration_steps
    where orchestration_run_id=run.id and step_kind='STAGE_C1_REQUEST';
  v_stage_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_C1_STAGED_STATE_V1',jsonb_build_object(
    'family_id',family.id,'generation_id',g.id,'publication_request_id',r.id,'request_sha256',encode(r.request_sha256,'hex'),
    'new_bound_version',v_before_bound+1));
  if stage.outcome is distinct from 'COMPLETE' or stage.completed_at_utc is null or not isfinite(stage.completed_at_utc)
    or stage.allowlisted_owner_name is distinct from 'public.weekly_exceptional_pay_stage_c1_request_v1'
    or stage.allowlisted_owner_signature is distinct from 'jsonb->jsonb'
    or stage.before_state_fingerprint is distinct from run.before_state_fingerprint
    or octet_length(stage.bounded_request_hash) is distinct from 32
    or stage.after_state_fingerprint is distinct from v_stage_hash or stage.owner_response_hash is distinct from v_stage_hash
    or stage.bounded_owner_response_json is distinct from jsonb_build_object('publication_request_id',r.id,'generation_id',g.id,
      'request_sha256',encode(r.request_sha256,'hex')) or family.bound_version is distinct from v_before_bound+1 then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  v_inventory:=private.weekly_source_effective_inventory_v1(r.root_timesheet_id);
  v_inventory:=jsonb_set(v_inventory,'{approval_basis,scope,family_bound_version}',
    v_before#>'{approval_basis,scope,family_bound_version}',false);
  if v_inventory is distinct from v_before
    or v_inventory#>>'{approval_basis,scope,root_timesheet_id}' is distinct from r.root_timesheet_id::text
    or v_inventory#>>'{approval_basis,scope,family_booking_id}' is distinct from v_scope->>'family_booking_id'
    or v_inventory#>>'{approval_basis,scope,root_version}' is distinct from v_scope->>'root_version'
    or v_inventory#>>'{approval_basis,scope,candidate_id}' is distinct from v_scope->>'candidate_id'
    or v_inventory#>>'{approval_basis,scope,client_id}' is distinct from v_scope->>'client_id'
    or v_inventory#>>'{approval_basis,scope,contract_id}' is distinct from v_scope->>'contract_id'
    or v_inventory#>>'{approval_basis,scope,week_ending_date}' is distinct from v_scope->>'week_ending_date' then
    raise exception 'WEEKLY_SOURCE_STAGED_BEFORE_POSITION_CHANGED' using errcode='40001'; end if;
  v_context:=private.weekly_source_protected_final_source_context_v1(family.id,a.source_cycle_id,a.work_event_id);
  if v_context->'source_proposal' is distinct from event.source_proposal_snapshot_json then
    raise exception 'WEEKLY_SOURCE_STAGED_SOURCE_CHANGED' using errcode='40001'; end if;
  select private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_RATE_POLICY_V1',jsonb_build_object(
    'contract_id',family.contract_id,'rates_json',contract.rates_json,
    'policy',private._weekly_source_effective_policy_v1(a.client_id,family.contract_id,a.protected_work_date),
    'classification',event.rate_classification_json)) into strict v_policy_hash
    from public.contracts contract where contract.id=family.contract_id;
  if v_policy_hash is distinct from a.contract_rate_policy_source_fingerprint then
    raise exception 'WEEKLY_SOURCE_STAGED_RATE_POLICY_CHANGED' using errcode='40001'; end if;
  -- A receipt is optional here. If one exists, only this real transaction's
  -- matching PREPARING row can coexist with this unaccepted stage.
  select * into local_receipt from private.weekly_source_local_protected_decision_receipts where publication_request_id=r.id;
  if found and (local_receipt.state is distinct from 'PREPARING' or local_receipt.preparing_transaction_id is distinct from pg_current_xact_id()
    or local_receipt.actor_user_id is distinct from p_actor_id or local_receipt.generation_id is distinct from g.id
    or local_receipt.family_id is distinct from family.id or local_receipt.root_timesheet_id is distinct from r.root_timesheet_id
    or local_receipt.request_sha256 is distinct from r.request_sha256 or local_receipt.prior_financial_id is distinct from r.financial_row_id) then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  if exists(select 1 from public.weekly_exceptional_c1_publication_checkpoints where publication_request_id=r.id)
    or exists(select 1 from public.weekly_exceptional_c1_unknown_outcomes where publication_request_id=r.id) then
    raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000'; end if;
  v_documents:=private.weekly_source_staged_source_documents_v1(r.id);
  if (select count(*) from jsonb_array_elements(v_documents) source where source->>'authority_kind'='ROOT_FINANCIAL')<>1
    or (select count(*) from jsonb_array_elements(v_documents) source where source->>'authority_kind'='PROVIDER')<>1
    or (select count(*) from jsonb_array_elements(v_documents) source where source->>'authority_kind'='OFFICE_APPROVAL')<>1
    or not exists(select 1 from jsonb_array_elements(v_documents) source where source->>'authority_kind'='CLIENT_SOURCE'
      and source#>>'{document,source_complete}'='true')
    or exists(select 1 from jsonb_array_elements(v_documents) source where source->>'authority_kind'='ROOT_FINANCIAL'
      and source#>>'{document,financial_row_id}' is distinct from r.financial_row_id::text) then
    raise exception 'WEEKLY_SOURCE_STAGED_SOURCE_UNAVAILABLE' using errcode='55000'; end if;
  v_qualification:=jsonb_build_object('schema_version','WEEKLY_SOURCE_STAGED_PUBLICATION_CONTEXT_V1',
    'publication_request_id',r.id,'generation_id',g.id,'family_id',family.id,'actor_user_id',p_actor_id,'scope',v_scope,
    'source_cycle_id',a.source_cycle_id,'work_event_id',a.work_event_id,'approval_id',a.id,'family_event_id',event.id,
    'family_event_sequence',event.event_sequence::text,'request_sha256',encode(r.request_sha256,'hex'),
    'stage_step_id',stage.id,'stage_step_request_sha256',encode(stage.bounded_request_hash,'hex'),
    'stage_step_sha256',encode(v_stage_hash,'hex'),'before_bound_version',v_before_bound::text,
    'staged_bound_version',(v_before_bound+1)::text,'prior_inventory',v_before,'target_snapshot',g.complete_next_vector_json->'target_snapshot',
    'complete_next_vector_sha256',encode(g.complete_next_vector_hash,'hex'),'policy_fingerprint',encode(v_policy_hash,'hex'),
    'source_proposal',event.source_proposal_snapshot_json,'next_source_segments',v_context->'next_source_segments','source_documents',v_documents);
  return v_qualification||jsonb_build_object('qualification_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_STAGED_PUBLICATION_CONTEXT_V1',v_qualification),'hex'));
exception when no_data_found or too_many_rows or invalid_text_representation or numeric_value_out_of_range then
  raise exception 'WEEKLY_SOURCE_STAGED_OWNERSHIP_UNAVAILABLE' using errcode='55000';
end;
$function$;
alter function private.weekly_source_staged_publication_context_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_staged_publication_context_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- Read the actual evidence already qualified by approval_basis_v2. This is
-- not a current-TSFIN fallback: the I1 origin chooses one exact approved row
-- or exact committed HEAD detail. The native domains and identities stay intact.
create or replace function private.weekly_source_approved_detail_evidence_v1(p_root_id uuid,p_inventory jsonb)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_basis jsonb:=p_inventory->'approval_basis'; v_origin jsonb:=p_inventory#>'{approval_basis,origin}';
  f public.timesheets_financials%rowtype; h public.weekly_source_entitlement_heads%rowtype;
  v_details jsonb; v_policy jsonb; v_detail jsonb; v_component jsonb; v_count integer;
begin
  if p_inventory->>'ok' is distinct from 'true' or v_basis->>'coverage_complete' is distinct from 'true'
    or v_basis#>>'{scope,root_timesheet_id}' is distinct from p_root_id::text
    or private.weekly_source_inventory_approval_basis_v2(p_root_id,p_inventory) is distinct from v_basis then
    raise exception 'WEEKLY_SOURCE_APPROVED_DETAIL_UNAVAILABLE' using errcode='55000'; end if;
  if v_origin->>'kind'='INITIAL_AUTHORISED_TSFIN_V1' then
    select * into strict f from public.timesheets_financials where id=(v_origin->>'financial_snapshot_id')::uuid
      and timesheet_id=p_root_id and authorised_at_utc is not null and timesheet_version=(v_basis#>>'{scope,root_version}')::integer;
    v_details:=jsonb_build_object('segments',f.invoice_breakdown_json->'segments','additional_units',f.additional_units_json,
      'actual_schedule',f.actual_schedule_json,'rate_source_refs',f.rate_source_refs_json);
    v_policy:=f.policy_snapshot_json;
    if private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_APPROVED_FINANCIAL_SNAPSHOT_V2',jsonb_build_object(
      'policy',v_policy,'details',v_details,'components',p_inventory->'components'))
      is distinct from decode(v_origin->>'financial_snapshot_digest','hex')
      or private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_APPROVED_POLICY_V2',v_policy)
        is distinct from decode(v_basis->>'policy_fingerprint','hex') then
      raise exception 'WEEKLY_SOURCE_APPROVED_DETAIL_UNAVAILABLE' using errcode='55000'; end if;
  elsif v_origin->>'kind'='COMMITTED_SOURCE_HEAD_V1' then
    select * into strict h from public.weekly_source_entitlement_heads where id=(v_origin->>'head_id')::uuid and state='COMMITTED_CURRENT';
    v_policy:=h.source_origin_json;v_details:='[]'::jsonb;
    for v_component in select value from jsonb_array_elements(p_inventory->'components') loop
      if v_component->>'component_kind'='WORKED_TIME' then
        if to_regclass('private.bpay_next_source_chosen_detail') is null then
          raise exception 'WEEKLY_SOURCE_APPROVED_DETAIL_UNAVAILABLE' using errcode='55000'; end if;
        execute 'select count(*),jsonb_agg(to_jsonb(d))->0 from private.bpay_next_source_chosen_detail d
          where d.head_id=$1 and d.component_id=$2 and d.decision_bundle_id=$3 and d.bundle_revision=$4'
          into v_count,v_detail using h.id,(v_component->>'component_id')::uuid,h.decision_bundle_id,h.bundle_revision;
        if v_count<>1 or v_detail->>'component_sha256' is distinct from ('\x'||(v_component->>'component_sha256'))
          or v_detail->>'detail_sha256' is distinct from ('\x'||encode(sha256(convert_to((v_detail->'detail_json')::text,'UTF8')),'hex')) then
          raise exception 'WEEKLY_SOURCE_APPROVED_DETAIL_UNAVAILABLE' using errcode='55000'; end if;
        v_details:=v_details||jsonb_build_array(jsonb_build_object('component_id',v_component->'component_id','detail',v_detail->'detail_json'));
      else
        v_details:=v_details||jsonb_build_array(jsonb_build_object('component_id',v_component->'component_id','detail',v_component-'component_sha256'));
      end if;
    end loop;
  else raise exception 'WEEKLY_SOURCE_APPROVED_DETAIL_UNAVAILABLE' using errcode='55000'; end if;
  if private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_APPROVED_DETAIL_V2',v_details)
    is distinct from decode(v_basis->>'detail_digest','hex') then
    raise exception 'WEEKLY_SOURCE_APPROVED_DETAIL_UNAVAILABLE' using errcode='55000'; end if;
  return jsonb_build_object('approval_basis',v_basis,'details',v_details,'policy',v_policy,
    'financial_rate_evidence',case when v_origin->>'kind'='INITIAL_AUTHORISED_TSFIN_V1' then
      jsonb_build_object('pay',jsonb_build_object('day',f.pay_day,'night',f.pay_night,'sat',f.pay_sat,'sun',f.pay_sun,'bh',f.pay_bh),
        'charge',jsonb_build_object('day',f.charge_day,'night',f.charge_night,'sat',f.charge_sat,'sun',f.charge_sun,'bh',f.charge_bh)) else null end);
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_APPROVED_DETAIL_UNAVAILABLE' using errcode='55000';
end;
$function$;
alter function private.weekly_source_approved_detail_evidence_v1(uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_approved_detail_evidence_v1(uuid,jsonb) from public,anon,authenticated,service_role;

-- Complete native receipt successors. Ordinary calls retain the latest-event path.
-- Explicit historical events are private and must be qualified as the exact own-stage predecessor.

create or replace function private.weekly_source_pay_query_local_receipt_event_v1(
  p_root_timesheet_id uuid,p_approval_id uuid,p_generation_id uuid,p_family_event_id uuid
) returns jsonb
language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_scope jsonb;
  v_approval public.weekly_exceptional_payment_approvals%rowtype;
  v_generation public.weekly_exceptional_pay_generations%rowtype;
  v_local private.weekly_source_local_protected_decision_receipts%rowtype;
  v_request public.weekly_exceptional_c1_publication_requests%rowtype;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_event public.weekly_exceptional_pay_family_events%rowtype;
  v_original_event public.weekly_exceptional_pay_family_events%rowtype;
  v_publication private.weekly_source_entitlement_publication_receipts%rowtype;
  v_pending public.weekly_source_pending_entitlement_bundles%rowtype;
  v_head public.weekly_source_entitlement_heads%rowtype;
  v_canonical jsonb;
  v_choice jsonb;
  v_entitlement jsonb;
  v_components jsonb;
  v_origin jsonb;
  v_basis jsonb;
  v_snapshot jsonb;
  v_publication_root public.timesheets%rowtype;
  v_publication_version integer;
  v_prior_inventory jsonb;
  v_before_origin jsonb;
  v_qualification jsonb;
  v_result_hash bytea;
  v_member integer;
begin
  if p_root_timesheet_id is null or p_approval_id is null or p_generation_id is null then
    raise exception 'WEEKLY_SOURCE_PAY_QUERY_LOCAL_RECEIPT_IDENTITY_REQUIRED' using errcode='22023';
  end if;
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_timesheet_id);
  if v_scope is null or v_scope->>'target_family_id' is null then return null; end if;
  select a.* into v_approval from public.weekly_exceptional_payment_approvals a
    where a.id=p_approval_id;
  if not found or v_approval.withdrawn_at_utc is not null
     or v_approval.pay_target_family_id::text is distinct from v_scope->>'target_family_id'
     or v_approval.candidate_id::text is distinct from v_scope->>'candidate_id'
     or v_approval.client_id::text is distinct from v_scope->>'client_id'
     or v_approval.contract_id::text is distinct from v_scope->>'contract_id'
     or to_char(v_approval.week_ending,'YYYY-MM-DD') is distinct from v_scope->>'week_ending_date'
     or v_approval.protected_work_date not between
        (v_scope->>'week_ending_date')::date-6 and (v_scope->>'week_ending_date')::date then return null; end if;
  if not exists(select 1 from public.weekly_work_events w
    where w.id=v_approval.work_event_id and w.candidate_id=v_approval.candidate_id
      and w.client_id=v_approval.client_id and w.work_date=v_approval.protected_work_date) then return null; end if;
  -- Latest actual event sequence, not a timestamp or a search through JSON.
  select e.* into v_event from public.weekly_exceptional_pay_family_events e
    where e.family_id=v_approval.pay_target_family_id
      and e.durable_work_event_id=v_approval.work_event_id
      and (p_family_event_id is null or e.id=p_family_event_id)
    order by e.event_sequence desc limit 1;
  if not found or v_event.evidence_approval_id is distinct from v_approval.id
     or v_event.state is distinct from 'WAIT'
     or v_event.work_date is distinct from v_approval.protected_work_date then return null; end if;
  select g.* into v_generation from public.weekly_exceptional_pay_generations g
    where g.id=p_generation_id and g.family_id=v_approval.pay_target_family_id;
  if not found or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',
       v_generation.complete_next_vector_json) is distinct from v_generation.complete_next_vector_hash
     or not exists(select 1 from public.weekly_exceptional_pay_target_events t
       where t.family_id=v_approval.pay_target_family_id and t.approval_id=v_approval.id
         and t.financial_generation_id=v_generation.id
         and t.complete_next_family_vector_fingerprint=v_generation.complete_next_vector_hash) then return null; end if;
  select l.* into v_local from private.weekly_source_local_protected_decision_receipts l
    where l.generation_id=v_generation.id;
  if not found or v_local.family_id is distinct from v_approval.pay_target_family_id
     or v_local.actor_user_id is distinct from v_approval.approved_by_user_id
     or v_local.state not in ('COMPLETE','PENDING_FREEZE')
     or v_local.completed_at_utc is null or not isfinite(v_local.completed_at_utc) then return null; end if;
  -- Accepted evidence belongs to its original physical root/version. A lawful
  -- later rotation must not invalidate the same raw booking family's receipt.
  -- Point-read that pinned root; never choose an arbitrary historical winner.
  select t.* into v_publication_root from public.timesheets t
    where t.timesheet_id=v_local.root_timesheet_id;
  if not found or v_publication_root.booking_id is distinct from v_scope->>'family_booking_id'
     or v_publication_root.contract_id is distinct from v_approval.contract_id
     or v_publication_root.week_ending_date is distinct from v_approval.week_ending
     or v_publication_root.sheet_scope is distinct from 'WEEKLY'
     or v_publication_root.line_type is distinct from 'HOURS'
     or v_publication_root.is_adjustment is distinct from false
     or v_local.approved_snapshot_json->>'timesheet_id' is distinct from v_local.root_timesheet_id::text
     or jsonb_typeof(v_local.approved_snapshot_json->'timesheet_version') is distinct from 'number'
     or coalesce(v_local.approved_snapshot_json->>'timesheet_version','') !~ '^[1-9][0-9]*$'
     or (v_local.approved_snapshot_json->>'timesheet_version')::numeric>2147483647 then return null; end if;
  v_publication_version:=(v_local.approved_snapshot_json->>'timesheet_version')::integer;
  if v_publication_root.version is distinct from v_publication_version then return null; end if;
  select r.* into v_request from public.weekly_exceptional_c1_publication_requests r
    where r.id=v_local.publication_request_id;
  if not found or v_request.state is distinct from 'RETIRED'
     or v_request.completed_at_utc is null or not isfinite(v_request.completed_at_utc)
     or v_request.family_id is distinct from v_local.family_id
     or v_request.generation_id is distinct from v_generation.id
     or v_request.orchestration_run_id is distinct from v_approval.creation_orchestration_run_id
     or v_request.root_timesheet_id is distinct from v_local.root_timesheet_id
     or v_request.candidate_id is distinct from v_approval.candidate_id
     or v_request.contract_id is distinct from v_approval.contract_id
     or v_request.week_ending_date is distinct from v_approval.week_ending
     or v_request.request_sha256 is distinct from v_local.request_sha256
     or v_request.typed_result_json is distinct from v_local.result_json
     or v_request.c1_operation_id is not null or v_request.c1_publication_id is not null
     or v_request.c1_head_revision is not null or v_request.c1_receipt_sha256 is not null then return null; end if;
  select r.* into v_run from public.weekly_exceptional_orchestration_runs r
    where r.id=v_approval.creation_orchestration_run_id;
  v_result_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_LOCAL_RESULT_V1',v_local.result_json);
  if not found or v_run.family_id is distinct from v_local.family_id
     or v_run.requested_by_user_id is distinct from v_local.actor_user_id
     or v_run.state is distinct from 'COMPLETE' or v_run.completed_at_utc is null
     or not isfinite(v_run.completed_at_utc)
     or v_run.after_state_fingerprint is distinct from v_result_hash
     or v_local.result_json->'ok' is distinct from 'true'::jsonb
     or v_local.result_json->'idempotent_replay' is distinct from 'false'::jsonb
     or v_local.result_json->>'family_id' is distinct from v_local.family_id::text
     or v_local.result_json->>'generation_id' is distinct from v_generation.id::text
     or v_local.result_json->>'publication_request_id' is distinct from v_request.id::text
     or coalesce(v_local.result_json->>'family_bound_version','') !~ '^[1-9][0-9]*$'
     or (v_local.result_json->>'family_bound_version')::numeric>
          (v_scope->>'family_bound_version')::numeric then return null; end if;
  v_snapshot:=v_generation.complete_next_vector_json#>'{target_snapshot,tsfin_snapshot_json}';
  if jsonb_typeof(v_snapshot) is distinct from 'object'
     or v_snapshot is distinct from v_approval.approved_target_pay_components_json->'tsfin_snapshot_json' then return null; end if;
  if v_local.state='COMPLETE' then
    -- A different sibling may have superseded this accepted generation. Its
    -- immutable published proof is still needed for this unchanged WAIT event.
    if v_generation.lifecycle_state not in ('PUBLISHED','SUPERSEDED')
       or v_generation.published_at_utc is null or not isfinite(v_generation.published_at_utc)
       or v_generation.result_hash is distinct from v_result_hash
       or v_local.result_json->>'outcome' is distinct from 'PUBLISHED'
       or v_local.result_json->>'state' is distinct from 'LIVE' then return null; end if;
  elsif v_generation.lifecycle_state is distinct from 'PENDING_C1'
     or v_generation.published_at_utc is not null or v_generation.result_hash is not null
     or v_local.result_json->>'outcome' is distinct from 'SAVED_PENDING_FREEZE'
     or v_local.result_json->>'state' is distinct from 'PENDING' then return null;
  end if;
  if v_local.result_json->>'authority'='UNAUTHORISED_TSFIN' then
    if v_local.state<>'COMPLETE'
       or v_local.result_json->'requires_first_authorisation' is distinct from 'true'::jsonb then return null; end if;
    v_basis:=v_local.approved_snapshot_json->'saved_unauthorised_basis';
    if private.weekly_exceptional_json_keys_exact_v1(v_basis,array['schema_version',
       'financial_snapshot_id','financial_snapshot_sha256','detail_sha256','inventory_sha256',
       'root_version','family_booking_id']) is distinct from true
       or not (v_basis ?& array['schema_version','financial_snapshot_id','financial_snapshot_sha256',
          'detail_sha256','inventory_sha256','root_version','family_booking_id'])
       or v_basis->>'schema_version' is distinct from 'SAVED_UNAUTHORISED_LOCAL_V1'
       or v_basis->>'family_booking_id' is distinct from v_scope->>'family_booking_id'
       or v_basis->>'root_version' is distinct from v_publication_version::text
       or v_basis->>'financial_snapshot_id' is distinct from v_local.result_json->>'timesheet_financials_id'
       or coalesce(v_basis->>'financial_snapshot_sha256','') !~ '^[0-9a-f]{64}$'
       or coalesce(v_basis->>'detail_sha256','') !~ '^[0-9a-f]{64}$'
       or v_basis->>'inventory_sha256' is distinct from encode(v_generation.complete_next_vector_hash,'hex')
       or (v_local.approved_snapshot_json-'saved_unauthorised_basis') is distinct from
          (v_snapshot||jsonb_build_object('timesheet_id',v_local.root_timesheet_id::text,
           'timesheet_version',v_publication_version,'actual_schedule_json',
           v_generation.complete_next_vector_json#>'{target_snapshot,actual_schedule_json}'))
       or not exists(select 1 from public.timesheets_financials f
         where f.id::text=v_basis->>'financial_snapshot_id'
           and f.timesheet_id=v_local.root_timesheet_id
           and f.timesheet_version=v_publication_version
           and f.candidate_id=v_approval.candidate_id and f.client_id=v_approval.client_id) then return null; end if;
    -- This is accepted decision evidence, not current financial eligibility.
    -- First Authorise can legitimately change current TSFIN. Do not compare
    -- today's mutable finance row to the original sealed pre-authorise hash.
  elsif v_local.result_json->>'authority'='COMMON_ENTITLEMENT_HEAD' then
    if v_local.result_json->'requires_first_authorisation' is distinct from 'false'::jsonb
       or v_local.approved_snapshot_json->>'common_decision_bundle_id'
          is distinct from v_local.result_json->>'decision_bundle_id'
       or v_local.common_decision_bundle_id::text is distinct from v_local.result_json->>'decision_bundle_id'
       or v_local.common_bundle_revision is null
       or v_local.publication_origin_kind is distinct from 'PROTECTED_LOCAL_DECISION_V1'
       or v_local.publication_origin_digest is null
       or v_local.source_qualification_digest is null then return null; end if;
    if v_local.state='PENDING_FREEZE' then
      select p.* into v_pending from public.weekly_source_pending_entitlement_bundles p
        where p.id::text=v_local.result_json#>>'{publication,pending_bundle_verified}';
      if not found or v_pending.state not in ('PENDING','RELEASING','MANUAL_REVIEW')
         or v_pending.decision_bundle_id::text is distinct from v_local.result_json->>'decision_bundle_id'
         or v_pending.bundle_revision is distinct from v_local.common_bundle_revision
         or v_pending.decided_by_user_id is distinct from v_local.actor_user_id
         or v_pending.candidate_id is distinct from v_approval.candidate_id
         or v_local.result_json#>'{publication,ok}' is distinct from 'true'::jsonb
         or v_local.result_json#>'{publication,published}' is distinct from 'false'::jsonb
         or v_local.result_json#>>'{publication,code}' is distinct from 'WEEKLY_SOURCE_PUBLICATION_DEFERRED_PENDING_FREEZE'
         or v_pending.request_digest is distinct from private.weekly_source_publication_request_digest_v1(
             private.weekly_source_publication_request_canonical_v1(v_pending.request_json,'DEFERRED',v_pending.id)) then return null; end if;
      v_member:=array_position(v_pending.member_root_ids,v_local.root_timesheet_id);
      if v_member is null or v_pending.member_family_booking_ids[v_member] is distinct from v_scope->>'family_booking_id'
         or v_pending.member_root_versions[v_member] is distinct from v_publication_version then return null; end if;
      v_canonical:=private.weekly_source_publication_request_canonical_v1(v_pending.request_json,'DEFERRED',v_pending.id);
      -- A self-consistent request digest does not prove that its identities
      -- agree with the separately stored pending row. Bind the complete member
      -- mapping before using the pending row's ordinal to select an entitlement.
      if v_canonical->>'decision_bundle_id' is distinct from v_pending.decision_bundle_id::text
         or (v_canonical->>'bundle_revision')::bigint is distinct from v_pending.bundle_revision
         or v_canonical->>'candidate_id' is distinct from v_pending.candidate_id::text
         or v_canonical->'member_root_ids' is distinct from to_jsonb(v_pending.member_root_ids)
         or v_canonical->'member_family_booking_ids' is distinct from to_jsonb(v_pending.member_family_booking_ids)
         or v_canonical->'member_root_versions' is distinct from to_jsonb(v_pending.member_root_versions)
         or v_canonical->'head_ids' is distinct from to_jsonb(v_pending.proposed_head_ids)
         or v_canonical->>'decision_id' is distinct from v_pending.decision_id::text
         or v_canonical->'member_root_ids'->>(v_member-1) is distinct from v_local.root_timesheet_id::text
         or v_canonical->'member_family_booking_ids'->>(v_member-1) is distinct from v_scope->>'family_booking_id'
         or (v_canonical->'member_root_versions'->>(v_member-1))::integer
            is distinct from v_publication_version then return null; end if;
      select c.value into strict v_choice from jsonb_array_elements(
        v_canonical#>'{financial_request,contract_choices}') c(value)
        where (c.value->>'root_ordinal')::integer=v_member;
      if v_choice->>'contract_id' is distinct from v_scope->>'contract_id'
         or v_choice->>'week_ending_date' is distinct from v_scope->>'week_ending_date' then return null; end if;
      select e.value into strict v_entitlement from jsonb_array_elements(
        v_canonical#>'{financial_request,member_entitlements}') e(value)
        where (e.value->>'root_ordinal')::integer=v_member;
      if v_entitlement->>'authority_kind' is distinct from 'PROTECTED'
         or (v_entitlement->>'component_count')::integer is distinct from jsonb_array_length(v_entitlement->'components') then return null; end if;
      v_components:=v_entitlement->'components';
      v_origin:=v_canonical#>'{financial_request,source_revision}';
    else
      select r.* into v_publication from private.weekly_source_entitlement_publication_receipts r
        where r.id::text=v_local.result_json#>>'{publication,receipt,id}';
      if not found or v_publication.decision_bundle_id::text is distinct from v_local.result_json->>'decision_bundle_id'
         or v_publication.bundle_revision is distinct from v_local.common_bundle_revision
         or v_publication.candidate_id is distinct from v_approval.candidate_id
         or v_publication.decided_by_user_id is distinct from v_local.actor_user_id
         or v_local.result_json#>'{publication,ok}' is distinct from 'true'::jsonb
         or v_local.result_json#>'{publication,published}' is distinct from 'true'::jsonb
         or v_local.result_json#>'{publication,receipt}' is distinct from
            private.weekly_source_publication_receipt_json_v1(v_publication.id) then return null; end if;
      v_member:=array_position(v_publication.member_root_ids,v_local.root_timesheet_id);
      if v_member is null or v_publication.member_family_booking_ids[v_member] is distinct from v_scope->>'family_booking_id'
         or v_publication.member_root_versions[v_member] is distinct from v_publication_version
         or not exists(select 1 from public.weekly_source_entitlement_heads h
           where h.id=v_publication.head_ids[v_member] and h.root_timesheet_id=v_local.root_timesheet_id
             and h.root_family_booking_id=v_scope->>'family_booking_id'
             and h.root_timesheet_version=v_publication_version
             and h.decision_bundle_id=v_publication.decision_bundle_id
             and h.bundle_revision=v_publication.bundle_revision
             and h.state in ('COMMITTED_CURRENT','SUPERSEDED')) then return null; end if;
      select h.* into strict v_head from public.weekly_source_entitlement_heads h
        where h.id=v_publication.head_ids[v_member];
      if v_head.authority_kind is distinct from 'PROTECTED'
         or v_head.candidate_id is distinct from v_approval.candidate_id
         or v_head.contract_id is distinct from v_approval.contract_id
         or v_head.week_ending_date is distinct from v_approval.week_ending then return null; end if;
      select coalesce(jsonb_agg(private.weekly_source_publication_component_canonical_v1(
        (to_jsonb(c)-array['id','head_id','decision_bundle_id','bundle_revision','component_sha256','created_at_utc'])
          ||jsonb_build_object('work_date',to_char(c.work_date,'YYYY-MM-DD'),
            'hours_day',c.hours_day::text,'hours_night',c.hours_night::text,
            'hours_sat',c.hours_sat::text,'hours_sun',c.hours_sun::text,
            'hours_bh',c.hours_bh::text,'unit_count',c.unit_count::text,
            'unit_pay_rate',c.unit_pay_rate::text,'unit_charge_rate',c.unit_charge_rate::text,
            'pay_ex_vat',c.pay_ex_vat::text,'charge_ex_vat',c.charge_ex_vat::text),
        'query.local.accepted_component') order by c.component_ordinal),'[]'::jsonb)
        into v_components from public.weekly_source_entitlement_head_components c where c.head_id=v_head.id;
      if jsonb_array_length(v_components) is distinct from v_head.component_count
         or exists(select 1 from public.weekly_source_entitlement_head_components c
           where c.head_id=v_head.id and c.component_sha256 is distinct from
             private.weekly_source_publication_request_digest_v1(private.weekly_source_publication_component_content_v1(
               private.weekly_source_publication_component_canonical_v1((to_jsonb(c)-array['id','head_id',
                 'decision_bundle_id','bundle_revision','component_sha256','created_at_utc'])
                   ||jsonb_build_object('work_date',to_char(c.work_date,'YYYY-MM-DD'),
                     'hours_day',c.hours_day::text,'hours_night',c.hours_night::text,
                     'hours_sat',c.hours_sat::text,'hours_sun',c.hours_sun::text,
                     'hours_bh',c.hours_bh::text,'unit_count',c.unit_count::text,
                     'unit_pay_rate',c.unit_pay_rate::text,'unit_charge_rate',c.unit_charge_rate::text,
                     'pay_ex_vat',c.pay_ex_vat::text,'charge_ex_vat',c.charge_ex_vat::text),
                 'query.local.accepted_component')))) then return null; end if;
      v_origin:=v_head.source_origin_json;
      if v_head.source_generation_digest is distinct from private.weekly_source_publication_request_digest_v1(v_origin) then return null; end if;
    end if;
    -- Compatible V4 local publisher must supply this real closed origin.
    -- The old current-Final constructor is deliberately NOT an accepted
    -- substitute, even if it published a genuine same-root/actor Source HEAD.
    if private.weekly_exceptional_json_keys_exact_v1(v_origin,array['origin_kind','publication_request_id',
       'generation_id','request_sha256','source_qualification_digest','policy_fingerprint',
       'before_origin','before_inventory_digest']) is distinct from true
       or not (v_origin ?& array['origin_kind','publication_request_id','generation_id','request_sha256',
          'source_qualification_digest','policy_fingerprint','before_origin','before_inventory_digest'])
       or v_origin->>'origin_kind' is distinct from 'PROTECTED_LOCAL_DECISION_V1'
       or v_origin->>'publication_request_id' is distinct from v_request.id::text
       or v_origin->>'generation_id' is distinct from v_generation.id::text
       or v_origin->>'request_sha256' is distinct from encode(v_request.request_sha256,'hex')
       or private.weekly_source_publication_request_digest_v1(v_origin)
          is distinct from v_local.publication_origin_digest
       or v_origin->>'source_qualification_digest'
          is distinct from encode(v_local.source_qualification_digest,'hex')
       or coalesce(v_origin->>'source_qualification_digest','') !~ '^[0-9a-f]{64}$'
       or coalesce(v_origin->>'policy_fingerprint','') !~ '^[0-9a-f]{64}$'
       or coalesce(v_origin->>'before_inventory_digest','') !~ '^[0-9a-f]{64}$'
       or jsonb_typeof(v_origin->'before_origin') is distinct from 'object'
       or v_local.approved_snapshot_json->'local_publication_origin' is distinct from v_origin
       or private.weekly_source_sha256_jsonb_v1('PROTECTED_LOCAL_SOURCE_QUALIFICATION_V2',
          v_local.approved_snapshot_json->'local_source_qualification')
          is distinct from v_local.source_qualification_digest
       or coalesce(v_local.approved_snapshot_json->>'common_components_digest','') !~ '^[0-9a-f]{64}$'
       or v_local.approved_snapshot_json->>'common_components_digest' is distinct from encode(
          private.weekly_source_publication_request_digest_v1(v_components),'hex') then return null; end if;
    -- The retained qualification must belong to this exact accepted action.
    -- A later WAIT can reuse this approval with a different source proposal:
    -- point-read the original immutable event, never compare it to latest WAIT.
    v_qualification:=v_local.approved_snapshot_json->'local_source_qualification';
    if private.weekly_exceptional_json_keys_exact_v1(v_qualification,array[
         'schema_version','publication_request_id','generation_id','scope','source_cycle_id',
         'work_event_id','approval_id','actor_user_id','family_event_sequence','source_proposal_hash',
         'complete_vector_hash','rate_policy_fingerprint','prepared_sources']) is distinct from true
       or not (v_qualification ?& array['schema_version','publication_request_id','generation_id',
         'scope','source_cycle_id','work_event_id','approval_id','actor_user_id','family_event_sequence',
         'source_proposal_hash','complete_vector_hash','rate_policy_fingerprint','prepared_sources'])
       or v_qualification->>'schema_version' is distinct from 'PROTECTED_LOCAL_SOURCE_QUALIFICATION_V2'
       or v_qualification->>'publication_request_id' is distinct from v_request.id::text
       or v_qualification->>'generation_id' is distinct from v_generation.id::text
       or v_qualification->>'source_cycle_id' is distinct from v_approval.source_cycle_id::text
       or v_qualification->>'work_event_id' is distinct from v_approval.work_event_id::text
       or v_qualification->>'approval_id' is distinct from v_approval.id::text
       or v_qualification->>'actor_user_id' is distinct from v_local.actor_user_id::text
       or v_qualification->>'complete_vector_hash' is distinct from encode(v_generation.complete_next_vector_hash,'hex')
       or v_qualification->>'rate_policy_fingerprint' is distinct from encode(v_approval.contract_rate_policy_source_fingerprint,'hex')
       or v_origin->>'policy_fingerprint' is distinct from v_qualification->>'rate_policy_fingerprint'
       or v_qualification#>>'{scope,root_timesheet_id}' is distinct from v_local.root_timesheet_id::text
       or v_qualification#>>'{scope,root_version}' is distinct from v_publication_version::text
       or v_qualification#>>'{scope,family_booking_id}' is distinct from v_scope->>'family_booking_id'
       or v_qualification#>>'{scope,target_family_id}' is distinct from v_local.family_id::text
       or v_qualification#>>'{scope,candidate_id}' is distinct from v_approval.candidate_id::text
       or v_qualification#>>'{scope,client_id}' is distinct from v_approval.client_id::text
       or v_qualification#>>'{scope,contract_id}' is distinct from v_approval.contract_id::text
       or v_qualification#>>'{scope,week_ending_date}' is distinct from to_char(v_approval.week_ending,'YYYY-MM-DD')
       or coalesce(v_qualification->>'family_event_sequence','') !~ '^[1-9][0-9]*$'
       or (v_qualification->>'family_event_sequence')::numeric>9223372036854775807
       or coalesce(v_qualification->>'source_proposal_hash','') !~ '^[0-9a-f]{64}$'
       or jsonb_typeof(v_qualification->'prepared_sources') is distinct from 'array' then return null; end if;
    select e.* into v_original_event from public.weekly_exceptional_pay_family_events e
      where e.family_id=v_local.family_id
        and e.event_sequence=(v_qualification->>'family_event_sequence')::bigint;
    if not found or v_original_event.durable_work_event_id is distinct from v_approval.work_event_id
       or v_original_event.evidence_approval_id is distinct from v_approval.id
       or v_original_event.office_actor_user_id is distinct from v_local.actor_user_id
       or v_original_event.work_date is distinct from v_approval.protected_work_date
       or v_original_event.source_proposal_hash is distinct from decode(v_qualification->>'source_proposal_hash','hex')
       or v_original_event.source_proposal_hash is distinct from private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_PROTECTED_SOURCE_PROPOSAL_V1',v_original_event.source_proposal_snapshot_json) then return null; end if;
    -- Qualify the original sealed before-position, never today's HEAD/root.
    -- The complete vector was sealed by the actual stage owner. A later
    -- sibling amendment or physical rotation cannot replace this evidence.
    v_prior_inventory:=v_generation.complete_next_vector_json->'prior_effective_inventory';
    v_before_origin:=v_prior_inventory#>'{approval_basis,origin}';
    if v_prior_inventory->'ok' is distinct from 'true'::jsonb
       or v_prior_inventory#>'{approval_basis,coverage_complete}' is distinct from 'true'::jsonb
       or coalesce(v_before_origin->>'kind','') not in ('INITIAL_AUTHORISED_TSFIN_V1','COMMITTED_SOURCE_HEAD_V1')
       or v_prior_inventory#>>'{approval_basis,scope,root_timesheet_id}' is distinct from v_local.root_timesheet_id::text
       or v_prior_inventory#>>'{approval_basis,scope,root_version}' is distinct from v_publication_version::text
       or v_prior_inventory#>>'{approval_basis,scope,family_booking_id}' is distinct from v_scope->>'family_booking_id'
       or v_prior_inventory#>>'{approval_basis,scope,target_family_id}' is distinct from v_local.family_id::text
       or v_prior_inventory#>>'{approval_basis,scope,candidate_id}' is distinct from v_scope->>'candidate_id'
       or v_prior_inventory#>>'{approval_basis,scope,client_id}' is distinct from v_scope->>'client_id'
       or v_prior_inventory#>>'{approval_basis,scope,contract_id}' is distinct from v_scope->>'contract_id'
       or v_prior_inventory#>>'{approval_basis,scope,week_ending_date}' is distinct from v_scope->>'week_ending_date'
       or v_origin->>'before_inventory_digest' is distinct from v_prior_inventory->>'inventory_digest' then return null; end if;
    if v_before_origin->>'kind'='COMMITTED_SOURCE_HEAD_V1' then
      v_before_origin:=v_before_origin-'source_revision';
    end if;
    if v_origin->'before_origin' is distinct from v_before_origin
       or private.weekly_source_local_origin_canonical_v2(v_origin) is distinct from v_origin then return null; end if;
  else return null;
  end if;
  return jsonb_build_object('lane','SOURCE_LOCAL','publication_request_id',v_request.id,
    'orchestration_run_id',v_run.id,'generation_id',v_generation.id,
    'request_sha256',encode(v_local.request_sha256,'hex'),'receipt_state',v_local.state);
end;
$function$;
alter function private.weekly_source_pay_query_local_receipt_event_v1(uuid,uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_pay_query_local_receipt_event_v1(uuid,uuid,uuid,uuid) from public,anon,authenticated,service_role;
create or replace function private.weekly_source_pay_query_local_receipt_v1(p_root_timesheet_id uuid,p_approval_id uuid,p_generation_id uuid)
returns jsonb language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$ select private.weekly_source_pay_query_local_receipt_event_v1(p_root_timesheet_id,p_approval_id,p_generation_id,null); $function$;
alter function private.weekly_source_pay_query_local_receipt_v1(uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_pay_query_local_receipt_v1(uuid,uuid,uuid) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_pay_query_c1_receipt_event_v1(
  p_root_timesheet_id uuid,p_approval_id uuid,p_generation_id uuid,p_family_event_id uuid
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_scope jsonb;
  v_approval public.weekly_exceptional_payment_approvals%rowtype;
  v_generation public.weekly_exceptional_pay_generations%rowtype;
  v_request public.weekly_exceptional_c1_publication_requests%rowtype;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_event public.weekly_exceptional_pay_family_events%rowtype;
  v_checkpoint public.weekly_exceptional_c1_publication_checkpoints%rowtype;
  v_step public.weekly_exceptional_orchestration_steps%rowtype;
  v_publication_root public.timesheets%rowtype;
  v_publication_fin public.timesheets_financials%rowtype;
  v_after_hash bytea;
  v_count integer;
begin
  if p_root_timesheet_id is null or p_approval_id is null or p_generation_id is null then
    raise exception 'WEEKLY_SOURCE_PAY_QUERY_C1_RECEIPT_IDENTITY_REQUIRED' using errcode='22023'; end if;
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_timesheet_id);
  if v_scope is null or v_scope->>'target_family_id' is null then return null; end if;
  select a.* into v_approval from public.weekly_exceptional_payment_approvals a where a.id=p_approval_id;
  if not found or v_approval.withdrawn_at_utc is not null
     or v_approval.pay_target_family_id::text is distinct from v_scope->>'target_family_id'
     or v_approval.candidate_id::text is distinct from v_scope->>'candidate_id'
     or v_approval.client_id::text is distinct from v_scope->>'client_id'
     or v_approval.contract_id::text is distinct from v_scope->>'contract_id'
     or to_char(v_approval.week_ending,'YYYY-MM-DD') is distinct from v_scope->>'week_ending_date'
     or v_approval.protected_work_date not between
       (v_scope->>'week_ending_date')::date-6 and (v_scope->>'week_ending_date')::date
     or not exists(select 1 from public.weekly_work_events e where e.id=v_approval.work_event_id
       and e.candidate_id=v_approval.candidate_id and e.client_id=v_approval.client_id
       and e.work_date=v_approval.protected_work_date) then return null; end if;
  select e.* into v_event from public.weekly_exceptional_pay_family_events e
    where e.family_id=v_approval.pay_target_family_id and e.durable_work_event_id=v_approval.work_event_id
      and (p_family_event_id is null or e.id=p_family_event_id)
    order by e.event_sequence desc limit 1;
  if not found or v_event.state is distinct from 'WAIT'
     or v_event.evidence_approval_id is distinct from v_approval.id
     or v_event.work_date is distinct from v_approval.protected_work_date then return null; end if;
  select g.* into v_generation from public.weekly_exceptional_pay_generations g
    where g.id=p_generation_id and g.family_id=v_approval.pay_target_family_id;
  if not found or v_generation.lifecycle_state not in ('PUBLISHED','SUPERSEDED')
     or v_generation.published_at_utc is null or not isfinite(v_generation.published_at_utc)
     or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',
       v_generation.complete_next_vector_json) is distinct from v_generation.complete_next_vector_hash
     or v_generation.complete_next_vector_json->'target_snapshot' is distinct from v_approval.approved_target_pay_components_json
     or not exists(select 1 from public.weekly_exceptional_pay_target_events e
       where e.family_id=v_approval.pay_target_family_id and e.approval_id=v_approval.id
         and e.financial_generation_id=v_generation.id
         and e.complete_next_family_vector_fingerprint=v_generation.complete_next_vector_hash)
     or exists(select 1 from private.weekly_source_local_protected_decision_receipts r
       where r.generation_id=v_generation.id) then return null; end if;
  select count(*) into v_count from public.weekly_exceptional_c1_publication_requests r
    where r.generation_id=v_generation.id;
  if v_count<>1 then return null; end if;
  select r.* into v_request from public.weekly_exceptional_c1_publication_requests r
    where r.generation_id=v_generation.id;
  if v_request.family_id is distinct from v_approval.pay_target_family_id
     or v_request.orchestration_run_id is distinct from v_approval.creation_orchestration_run_id
     or v_request.candidate_id is distinct from v_approval.candidate_id
     or v_request.contract_id is distinct from v_approval.contract_id
     or v_request.week_ending_date is distinct from v_approval.week_ending
     or v_request.agency_id is distinct from (select f.agency_id
       from public.weekly_exceptional_pay_target_families f where f.id=v_approval.pay_target_family_id)
     or v_request.state is distinct from 'PUBLISHED' or v_request.completed_at_utc is null
     or not isfinite(v_request.completed_at_utc)
     or v_request.c1_publication_id is null or v_request.c1_head_revision is null or v_request.c1_head_revision<1
     or v_request.c1_receipt_sha256 is null
     or v_generation.result_hash is distinct from v_request.c1_receipt_sha256 then return null; end if;
  -- The request retains its genuine publication-time physical root. A later
  -- lawful rotation does not invalidate that accepted same raw booking family.
  -- Point-read the pinned rows; never rank arbitrary historical alternatives.
  select t.* into v_publication_root from public.timesheets t
    where t.timesheet_id=v_request.root_timesheet_id;
  if not found or v_publication_root.booking_id is distinct from v_scope->>'family_booking_id'
     or v_publication_root.contract_id is distinct from v_approval.contract_id
     or v_publication_root.week_ending_date is distinct from v_approval.week_ending
     or v_publication_root.sheet_scope is distinct from 'WEEKLY'
     or v_publication_root.line_type is distinct from 'HOURS'
     or v_publication_root.is_adjustment is distinct from false
     or v_publication_root.version is null or v_publication_root.version<1 then return null; end if;
  select f.* into v_publication_fin from public.timesheets_financials f
    where f.id=v_request.financial_row_id;
  if not found or v_publication_fin.timesheet_id is distinct from v_publication_root.timesheet_id
     or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_SOURCE_PROPOSAL_V1',
       v_event.source_proposal_snapshot_json) is distinct from v_event.source_proposal_hash
     -- Financial and physical Timesheet versions are separate domains. Prove
     -- the original stage owner's fixed-source seal, not an invented equality.
     or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_FIXED_SOURCE_STATE_V1',
       jsonb_build_object('source_cycle_id',v_approval.source_cycle_id,
         'comparison_revision_id',v_approval.comparison_revision_id,
         'final_revision_id',v_approval.final_revision_id,
         'source_proposal_hash',encode(v_event.source_proposal_hash,'hex'),
         'financial_row_id',v_publication_fin.id,
         'financial_timesheet_version',v_publication_fin.timesheet_version))
       is distinct from v_generation.fixed_target_source_state_fingerprint then return null; end if;
  select r.* into v_run from public.weekly_exceptional_orchestration_runs r where r.id=v_request.orchestration_run_id;
  if not found or v_run.family_id is distinct from v_approval.pay_target_family_id
     or v_run.requested_by_user_id is distinct from v_approval.approved_by_user_id
     or v_run.state is distinct from 'COMPLETE' or v_run.completed_at_utc is null
     or not isfinite(v_run.completed_at_utc)
     or v_run.after_state_fingerprint is distinct from v_request.c1_receipt_sha256 then return null; end if;
  select c.* into v_checkpoint from public.weekly_exceptional_c1_publication_checkpoints c
    where c.publication_request_id=v_request.id order by c.checkpoint_sequence desc limit 1;
  if not found or v_checkpoint.phase is distinct from 'PUBLISH'
     or upper(v_checkpoint.result_json->>'status') is distinct from 'PUBLISHED'
     or v_checkpoint.result_json->'has_more' is distinct from 'false'::jsonb
     or v_checkpoint.result_json is distinct from v_request.typed_result_json
     or (v_checkpoint.result_json->>'publication_id')::uuid is distinct from v_request.c1_publication_id
     or (v_checkpoint.result_json->>'head_revision')::bigint is distinct from v_request.c1_head_revision
     or private.weekly_exceptional_hex_sha256_v1(v_checkpoint.result_json->>'request_sha256')
       is distinct from v_request.request_sha256
     or private.weekly_exceptional_hex_sha256_v1(v_checkpoint.result_json->>'receipt_sha256')
       is distinct from v_request.c1_receipt_sha256
     or (v_request.c1_operation_id is not null
       and (v_checkpoint.result_json->>'operation_id')::uuid is distinct from v_request.c1_operation_id) then return null; end if;
  v_after_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_C1_COMPLETE_AFTER_V1',
    jsonb_build_object('family_id',v_request.family_id,'generation_id',v_generation.id,
      'target_vector_hash',encode(v_generation.complete_next_vector_hash,'hex'),
      'c1_publication_id',v_request.c1_publication_id,'c1_head_revision',v_request.c1_head_revision::text,
      'c1_receipt_sha256',encode(v_request.c1_receipt_sha256,'hex')));
  select count(*) into v_count from public.weekly_exceptional_orchestration_steps s
    where s.orchestration_run_id=v_run.id and s.step_kind='COMPLETE_C1_PUBLICATION';
  if v_count<>1 then return null; end if;
  select s.* into v_step from public.weekly_exceptional_orchestration_steps s
    where s.orchestration_run_id=v_run.id and s.step_kind='COMPLETE_C1_PUBLICATION';
  if v_step.outcome is distinct from 'COMPLETE' or v_step.completed_at_utc is null
     or not isfinite(v_step.completed_at_utc)
     or v_step.allowlisted_owner_name is distinct from 'C1.weekly_source_publish_c1'
     or v_step.allowlisted_owner_signature is distinct from 'sealed C1 V1'
     or v_step.bounded_request_hash is distinct from v_request.request_sha256
     or v_step.bounded_owner_response_json is distinct from v_request.typed_result_json
     or v_step.owner_response_hash is distinct from v_request.c1_receipt_sha256
     or v_step.after_state_fingerprint is distinct from v_after_hash then return null; end if;
  return jsonb_build_object('lane','RETAINED_C1','publication_request_id',v_request.id,
    'orchestration_run_id',v_run.id,'generation_id',v_generation.id,
    'request_sha256',encode(v_request.request_sha256,'hex'),'c1_publication_id',v_request.c1_publication_id,
    'c1_head_revision',v_request.c1_head_revision::text,'c1_receipt_sha256',encode(v_request.c1_receipt_sha256,'hex'),
    'receipt_state','PUBLISHED');
end;
$function$;
alter function private.weekly_source_pay_query_c1_receipt_event_v1(uuid,uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_pay_query_c1_receipt_event_v1(uuid,uuid,uuid,uuid) from public,anon,authenticated,service_role;
create or replace function private.weekly_source_pay_query_c1_receipt_v1(p_root_timesheet_id uuid,p_approval_id uuid,p_generation_id uuid)
returns jsonb language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$ select private.weekly_source_pay_query_c1_receipt_event_v1(p_root_timesheet_id,p_approval_id,p_generation_id,null); $function$;
alter function private.weekly_source_pay_query_c1_receipt_v1(uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_pay_query_c1_receipt_v1(uuid,uuid,uuid) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_pay_query_next_receipt_event_v1(
  p_root_timesheet_id uuid,p_approval_id uuid,p_generation_id uuid,p_family_event_id uuid
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_scope jsonb; v_receipts jsonb;
begin
  if p_root_timesheet_id is null or p_approval_id is null or p_generation_id is null then
    raise exception 'WEEKLY_SOURCE_PAY_QUERY_NEXT_RECEIPT_IDENTITY_REQUIRED' using errcode='22023'; end if;
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_timesheet_id);
  if v_scope is null or v_scope->>'target_family_id' is null then return null; end if;
  select jsonb_agg(jsonb_build_object(
    'lane','DIRECT_NEXT','orchestration_run_id',r.orchestration_run_id,
    'generation_id',r.generation_id,'work_id',r.work_id,'revision_id',r.revision_id,
    'command_id',r.command_id,'agency_sequence',r.agency_sequence::text,
    'accepted_family_bound_version',r.accepted_family_bound_version::text,
    'prepared_request_sha256',encode(r.prepared_request_sha256,'hex'),
    'publication_request_sha256',encode(r.publication_request_sha256,'hex'),
    'source_manifest_sha256',encode(r.source_manifest_sha256,'hex'),'receipt_state','COMPLETE'))
  into v_receipts
  from public.weekly_exceptional_payment_approvals a
  join private.bpay_next_protected_source_receipt r on r.approval_id=a.id and r.generation_id=p_generation_id
  join public.weekly_exceptional_pay_target_families f on f.id=r.family_id
  join public.weekly_exceptional_orchestration_runs o on o.id=r.orchestration_run_id
  join public.weekly_exceptional_pay_generations g on g.id=r.generation_id
  join private.bpay_next_work w on w.id=r.work_id
  join private.bpay_next_work_revision v on v.work_id=w.id and v.id=r.revision_id
  join private.bpay_next_publication p on p.command_id=r.command_id and p.work_id=w.id
    and p.revision_id=v.id and p.candidate_id=w.candidate_id
  join private.bpay_next_command c on c.id=p.command_id
  join private.bpay_next_command_member m on m.command_id=c.id and m.candidate_id=w.candidate_id
  join lateral (select e.* from public.weekly_exceptional_pay_family_events e
    where e.family_id=f.id and e.durable_work_event_id=a.work_event_id
      and (p_family_event_id is null or e.id=p_family_event_id)
    order by e.event_sequence desc limit 1) e on true
  where a.id=p_approval_id and f.id::text=v_scope->>'target_family_id'
    and a.pay_target_family_id=f.id and g.family_id=f.id and o.family_id=f.id
    and a.withdrawn_at_utc is null
    and a.candidate_id::text=v_scope->>'candidate_id' and a.client_id::text=v_scope->>'client_id'
    and a.contract_id::text=v_scope->>'contract_id'
    and a.week_ending=(v_scope->>'week_ending_date')::date
    and a.protected_work_date between a.week_ending-6 and a.week_ending
    and exists(select 1 from public.weekly_work_events d where d.id=a.work_event_id
      and d.candidate_id=a.candidate_id and d.client_id=a.client_id and d.work_date=a.protected_work_date)
    and e.state='WAIT' and e.evidence_approval_id=a.id and e.work_date=a.protected_work_date
    and e.office_actor_user_id=a.approved_by_user_id
    and e.start_at_local=a.protected_start_at_local and e.end_at_local=a.protected_end_at_local
    and e.break_minutes=a.protected_break_minutes
    and e.fixed_office_target_hash=a.signed_schedule_fact_hash
    and private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_SCHEDULE_V1',
      e.fixed_office_target_snapshot_json)=a.signed_schedule_fact_hash
    and a.creation_orchestration_run_id=o.id
    and o.requested_by_user_id=r.actor_user_id and a.approved_by_user_id=r.actor_user_id
    and o.request_fingerprint=r.prepared_request_sha256
    and o.state='COMPLETE' and o.completed_at_utc is not null and isfinite(o.completed_at_utc)
    and o.after_state_fingerprint=r.publication_request_sha256
    and g.lifecycle_state in ('PUBLISHED','SUPERSEDED')
    and g.published_at_utc is not null and isfinite(g.published_at_utc)
    and g.result_hash=r.publication_request_sha256
    and g.complete_next_vector_json=a.approved_target_pay_components_json
    and private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',
      g.complete_next_vector_json)=g.complete_next_vector_hash
    and g.fixed_target_source_state_fingerprint=r.source_manifest_sha256
    and e.source_proposal_hash=r.source_manifest_sha256
    and private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_SOURCE_PROPOSAL_V1',
      e.source_proposal_snapshot_json)=r.source_manifest_sha256
    and (select count(*) from public.weekly_exceptional_pay_target_events t
      where t.family_id=f.id and t.approval_id=a.id and t.financial_generation_id=g.id)=1
    and exists(select 1 from public.weekly_exceptional_pay_target_events t
      where t.family_id=f.id and t.approval_id=a.id and t.financial_generation_id=g.id
        and t.complete_next_family_vector_fingerprint=g.complete_next_vector_hash
        and t.fixed_target_component_snapshot=g.complete_next_vector_json
        and t.current_source_proposal_snapshot=e.source_proposal_snapshot_json)
    and r.accepted_family_bound_version>0 and r.accepted_family_bound_version<=f.bound_version
    and w.candidate_id=a.candidate_id and w.contract_id=a.contract_id
    and w.booking_id=v_scope->>'family_booking_id' and w.work_kind='SOURCE'
    and w.week_ending_date=a.week_ending and v.week_ending_date=w.week_ending_date
    and v.source_kind='PROTECTED' and v.source_event_id=a.id
    and v.source_head_id is null and v.financial_snapshot_id is null
    and v.approved_at_utc is not null and isfinite(v.approved_at_utc)
    and v.sealed_at_utc is not null and isfinite(v.sealed_at_utc)
    and v.approved_source_ex_vat=a.approved_target_gross
    -- Both exact retained physical identities must belong to the raw family;
    -- neither needs to remain current or equal today's canonical physical root.
    and exists(select 1 from public.timesheets t where t.timesheet_id=w.original_timesheet_id
      and t.booking_id=w.booking_id and t.contract_id=w.contract_id
      and t.week_ending_date=w.week_ending_date and t.sheet_scope='WEEKLY'
      and t.line_type='HOURS' and t.is_adjustment is false and t.version>=1)
    and exists(select 1 from public.timesheets t where t.timesheet_id=v.physical_timesheet_id
      and t.booking_id=w.booking_id and t.contract_id=w.contract_id
      and t.week_ending_date=w.week_ending_date and t.sheet_scope='WEEKLY'
      and t.line_type='HOURS' and t.is_adjustment is false and t.version=v.physical_timesheet_version)
    and p.revision_no=v.revision_no and c.agency_sequence=r.agency_sequence
    and c.command_kind='POSITION_APPLY' and c.expected_member_count=1 and m.member_no=1
    and c.sealed_at_utc is not null and isfinite(c.sealed_at_utc)
    and c.id=private.bpay_next_source_command_id_v1(a.id)
    -- A job is created by later enrolment, not by publication acceptance.
    and not exists(select 1 from private.bpay_next_job j where j.command_id=c.id
      and (j.candidate_id<>w.candidate_id or j.job_kind<>'POSITION_APPLY'
        or j.command_sequence<>c.agency_sequence or j.module_epoch<>c.module_epoch))
    and (select count(*) from public.weekly_exceptional_orchestration_steps s
      where s.orchestration_run_id=o.id and s.step_kind='PUBLISH_NEXT')=1
    and exists(select 1 from public.weekly_exceptional_orchestration_steps s
      where s.orchestration_run_id=o.id and s.step_kind='PUBLISH_NEXT'
        and s.outcome='COMPLETE' and s.completed_at_utc is not null and isfinite(s.completed_at_utc)
        and s.allowlisted_owner_name='public.weekly_exceptional_pay_publish_next_v1'
        and s.allowlisted_owner_signature='jsonb->jsonb'
        and s.bounded_request_hash=r.publication_request_sha256
        and s.owner_response_hash=r.publication_request_sha256
        and s.after_state_fingerprint=r.publication_request_sha256
        and s.before_state_fingerprint=o.before_state_fingerprint
        and s.bounded_owner_response_json=private.bpay_next_protected_receipt_json_v1(o.id,false));
  if jsonb_array_length(v_receipts) is distinct from 1 then return null; end if;
  return v_receipts->0;
end;
$function$;
alter function private.weekly_source_pay_query_next_receipt_event_v1(uuid,uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_pay_query_next_receipt_event_v1(uuid,uuid,uuid,uuid) from public,anon,authenticated,service_role;
create or replace function private.weekly_source_pay_query_next_receipt_v1(p_root_timesheet_id uuid,p_approval_id uuid,p_generation_id uuid)
returns jsonb language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$ select private.weekly_source_pay_query_next_receipt_event_v1(p_root_timesheet_id,p_approval_id,p_generation_id,null); $function$;
alter function private.weekly_source_pay_query_next_receipt_v1(uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_pay_query_next_receipt_v1(uuid,uuid,uuid) from public,anon,authenticated,service_role;

-- Complete native receipt count and transport qualification; exact own-stage predecessor only.
create or replace function private.weekly_source_staged_prior_wait_receipt_v1(
  p_request_id uuid,p_actor_id uuid
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_stage jsonb; v_wait jsonb; p_root_timesheet_id uuid; p_family_event_id uuid;
  v_scope jsonb; v_latest public.weekly_exceptional_pay_family_events%rowtype;
  v_generation uuid; v_count integer; v_approval_run uuid; v_invalid_wait_audit boolean;
  v_local_count integer; v_c1_count integer; v_next_count integer; v_audit_count integer;
  v_local jsonb; v_c1 jsonb; v_next jsonb; v_receipt jsonb; v_exception jsonb; v_unavailable boolean:=false;
begin
  v_stage:=private.weekly_source_staged_publication_context_v1(p_request_id,p_actor_id);
  select generation.complete_next_vector_json#>'{automatic_reconcile_proof,qualified_wait}' into strict v_wait
    from public.weekly_exceptional_c1_publication_requests request
    join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id and generation.family_id=request.family_id
    where request.id=p_request_id;
  p_root_timesheet_id:=(v_stage#>>'{scope,root_timesheet_id}')::uuid; p_family_event_id:=(v_wait->>'event_id')::uuid;
  if v_wait->>'state' is distinct from 'QUALIFIED_WAIT' or v_wait->>'family_id' is distinct from v_stage->>'family_id'
    or exists(select 1 from public.weekly_exceptional_pay_family_events e where e.family_id=(v_stage->>'family_id')::uuid
      and e.durable_work_event_id=(v_stage->>'work_event_id')::uuid and e.event_sequence>(v_wait->>'event_sequence')::bigint
      and e.id is distinct from (v_stage->>'family_event_id')::uuid) then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_PRIOR_WAIT_CHANGED' using errcode='40001'; end if;
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_timesheet_id);
  if v_scope is null or v_scope->>'target_family_id' is null then return null; end if;
  select event.* into v_latest from public.weekly_exceptional_pay_family_events event
  where event.id=p_family_event_id and event.family_id=(v_scope->>'target_family_id')::uuid
    and event.state='WAIT'
    and event.durable_work_event_id=(v_stage->>'work_event_id')::uuid
    and event.evidence_approval_id=(v_wait->>'approval_id')::uuid
    and event.event_sequence=(v_wait->>'event_sequence')::bigint;
  if not found then return null; end if;
      -- Choose the actual approval's UNIQUE financial target-generation link.
      -- The Wait owner also appends generation-less, money-neutral audit rows
      -- for that same approval. They are not second payment publications, but
      -- must be genuine unchanged-vector WAIT evidence, never arbitrary nulls.
      -- A sibling publication may supersede the original financial generation;
      -- today's current_generation is not the immutable approval's pin.
      select count(*) filter (where t.financial_generation_id is not null),
        (array_agg(t.financial_generation_id) filter (where t.financial_generation_id is not null))[1],
        coalesce(bool_or(t.financial_generation_id is null and (
          t.reason is distinct from 'WAIT'
          or t.resulting_lifecycle_state is distinct from 'WAITING_SOURCE'
          or t.actor_user_id is null
          or t.complete_prior_family_vector_fingerprint is distinct from t.complete_next_family_vector_fingerprint
          or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',
            t.fixed_target_component_snapshot) is distinct from t.complete_next_family_vector_fingerprint
          or jsonb_typeof(t.current_source_proposal_snapshot) is distinct from 'object'
          or t.event_hash is distinct from private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_PROTECTED_TARGET_EVENT_V1',jsonb_build_object(
              'family_id',t.family_id,'event_sequence',t.event_sequence,
              'approval_id',t.approval_id,'generation_id',null,
              'prior_vector_hash',encode(t.complete_prior_family_vector_fingerprint,'hex'),
              'next_vector_hash',encode(t.complete_next_family_vector_fingerprint,'hex'),
              'reason','WAIT','actor_user_id',t.actor_user_id))
        )),false)
        into v_count,v_generation,v_invalid_wait_audit
        from public.weekly_exceptional_pay_target_events t
        where t.family_id=v_latest.family_id and t.approval_id=v_latest.evidence_approval_id;
      if v_latest.evidence_approval_id is null or v_count<>1 or v_generation is null or v_invalid_wait_audit then
        v_unavailable:=true;
      else
        v_local:=private.weekly_source_pay_query_local_receipt_event_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation,v_latest.id);
        v_c1:=private.weekly_source_pay_query_c1_receipt_event_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation,v_latest.id);
        v_next:=private.weekly_source_pay_query_next_receipt_event_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation,v_latest.id);
        v_count:=(v_local is not null)::integer+(v_c1 is not null)::integer+(v_next is not null)::integer;
        select a.creation_orchestration_run_id into v_approval_run
          from public.weekly_exceptional_payment_approvals a where a.id=v_latest.evidence_approval_id;
        -- Count partial evidence too. A local RETIRED request is its audit row,
        -- not a second transport lane; unrelated sibling/history stays excluded.
        select count(*) into v_local_count
          from private.weekly_source_local_protected_decision_receipts l
          join public.weekly_exceptional_c1_publication_requests r on r.id=l.publication_request_id
          where l.generation_id=v_generation or r.orchestration_run_id=v_approval_run;
        select count(*),count(*) filter (where
          (v_local is not null and r.id::text=v_local->>'publication_request_id' and r.state='RETIRED')
          or (v_c1 is not null and r.id::text=v_c1->>'publication_request_id' and r.state='PUBLISHED'))
          into v_c1_count,v_audit_count
          from public.weekly_exceptional_c1_publication_requests r
          where r.generation_id=v_generation or r.orchestration_run_id=v_approval_run;
        select count(*) into v_next_count from private.bpay_next_protected_source_receipt r
          where r.approval_id=v_latest.evidence_approval_id or r.generation_id=v_generation
            or r.orchestration_run_id=v_approval_run;
        if v_count<>1 or v_approval_run is null
           or (v_local is not null and (v_local_count<>1 or v_c1_count<>1 or v_audit_count<>1 or v_next_count<>0))
           or (v_c1 is not null and (v_local_count<>0 or v_c1_count<>1 or v_audit_count<>1 or v_next_count<>0))
           or (v_next is not null and (v_local_count<>0 or v_c1_count<>0 or v_next_count<>1)) then v_unavailable:=true;
        else
          v_receipt:=coalesce(v_local,v_c1,v_next);
          v_exception:=jsonb_build_object('family_id',v_latest.family_id,
            'bound_version',v_scope->>'family_bound_version','event_sequence',v_latest.event_sequence::text,
            'state','WAIT','evidence_approval_id',v_latest.evidence_approval_id,'accepted_receipt',v_receipt);
        end if;
      end if;

  if v_unavailable or v_exception is null or v_exception->'accepted_receipt' is distinct from v_wait->'accepted_receipt'
    or v_exception#>>'{accepted_receipt,generation_id}' is distinct from v_wait->>'accepted_generation_id'
    or coalesce(v_exception#>>'{accepted_receipt,receipt_state}','') not in ('COMPLETE','PUBLISHED') then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_PRIOR_WAIT_UNAVAILABLE' using errcode='55000'; end if;
  return v_exception;
end;
$function$;
alter function private.weekly_source_staged_prior_wait_receipt_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_staged_prior_wait_receipt_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- Point-read immutable expense authorities selected by real approved evidence.
-- The existing complete native movement assertion owns lineage, policy hashes,
-- arithmetic and movement admission. This reader never reprices an expense.
create or replace function private.weekly_source_expense_authority_evidence_v1(p_root_id uuid,p_authority_ids jsonb)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_id jsonb; a public.weekly_expense_authority_generations%rowtype;
  p public.weekly_source_row_expense_policy_snapshots%rowtype; v_scope jsonb; m record;
  v_result jsonb:='[]'; v_policy jsonb; v_count integer; v_family uuid[];
begin
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_id);
  v_family:=private.weekly_source_invoice_family_timesheet_ids_v1(p_root_id);
  if v_scope is null or cardinality(v_family) is null or cardinality(v_family)=0
    or jsonb_typeof(p_authority_ids) is distinct from 'array'
    or exists(select 1 from jsonb_array_elements(p_authority_ids) x group by x having count(*)<>1) then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_UNAVAILABLE' using errcode='55000'; end if;
  for v_id in select value from jsonb_array_elements(p_authority_ids) loop
    select * into strict a from public.weekly_expense_authority_generations where id=(v_id#>>'{}')::uuid;
    select * into strict p from public.weekly_source_row_expense_policy_snapshots where id=a.row_expense_policy_snapshot_id;
    if a.contract_id::text is distinct from v_scope->>'contract_id' or a.source_expense_pence<=0
      or a.source_observation_kind is distinct from 'ROW_PRESENT' or a.work_event_id is distinct from p.work_event_id
      or p.candidate_id::text is distinct from v_scope->>'candidate_id' or p.client_id::text is distinct from v_scope->>'client_id'
      or p.contract_id is distinct from a.contract_id then
      raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_UNAVAILABLE' using errcode='55000'; end if;
    select count(*) into v_count from public.weekly_source_billing_movements movement
      join public.weekly_source_manifest_movements membership on membership.billing_movement_id=movement.id
      where movement.expense_authority_generation_id=a.id and movement.final_revision_id=a.final_revision_id
        and movement.invoice_timesheet_id=any(v_family) and movement.movement_role in ('EXPENSE_POSITIVE','EXPENSE_REPLACEMENT')
        and movement.source_line_kind='SOURCE_FIXED_EXPENSE';
    if v_count<>1 then raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_UNAVAILABLE' using errcode='55000'; end if;
    select movement.*,membership.client_manifest_id into strict m from public.weekly_source_billing_movements movement
      join public.weekly_source_manifest_movements membership on membership.billing_movement_id=movement.id
      where movement.expense_authority_generation_id=a.id and movement.final_revision_id=a.final_revision_id
        and movement.invoice_timesheet_id=any(v_family) and movement.movement_role in ('EXPENSE_POSITIVE','EXPENSE_REPLACEMENT')
        and movement.source_line_kind='SOURCE_FIXED_EXPENSE';
    if private.weekly_source_ordinary_projection_expense_movement_assert_v1(m.id,m.final_revision_id,
        m.finalisation_cycle_id,m.client_manifest_id,m.invoice_timesheet_id) is distinct from true then
      raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_UNAVAILABLE' using errcode='55000'; end if;
    -- Remove only storage/version/transport identities. Preserve every frozen
    -- policy value and the economic owner scope. Raw authority and raw policy
    -- remain in the qualification digest as separate immutable provenance.
    v_policy:=to_jsonb(p)-array['id','row_resolution_id','upload_row_id','generation','snapshot_hash','created_at_utc'];
    v_result:=v_result||jsonb_build_array(jsonb_build_object('work_event_id',a.work_event_id,
      'authority_id',a.id,'authority_hash',encode(a.authority_hash,'hex'),'movement_id',m.id,
      'final_revision_id',a.final_revision_id,'policy_snapshot_id',p.id,'policy',v_policy,
      'authority',to_jsonb(a)-array['state','created_at_utc'],'policy_snapshot',to_jsonb(p),
      'source_observation_kind',a.source_observation_kind,'candidate_reimbursement_ex_vat',a.candidate_reimbursement_ex_vat,
      'client_charge_ex_vat',a.client_charge_ex_vat));
  end loop;
  if exists(select 1 from jsonb_array_elements(v_result) x group by x->>'work_event_id' having count(*)<>1) then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_UNAVAILABLE' using errcode='55000'; end if;
  return (select coalesce(jsonb_agg(x order by x->>'work_event_id'),'[]') from jsonb_array_elements(v_result) x);
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_UNAVAILABLE' using errcode='55000';
end;
$function$;
alter function private.weekly_source_expense_authority_evidence_v1(uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_expense_authority_evidence_v1(uuid,jsonb) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_approved_expense_evidence_v1(p_root_id uuid,p_inventory jsonb)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_origin jsonb:=p_inventory#>'{approval_basis,origin}'; v_ids jsonb; v_result jsonb;
  v_source jsonb; v_components jsonb:=p_inventory->'components';
begin
  -- The complete native approval basis is required even for an empty expense set.
  if p_inventory#>>'{approval_basis,coverage_complete}' is distinct from 'true'
    or private.weekly_source_inventory_approval_basis_v2(p_root_id,p_inventory) is distinct from p_inventory->'approval_basis' then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_UNAVAILABLE' using errcode='55000'; end if;
  if v_origin->>'kind'='INITIAL_AUTHORISED_TSFIN_V1' then
    select coalesce(jsonb_agg(m.expense_authority_generation_id order by m.expense_authority_generation_id),'[]') into v_ids
      from public.weekly_source_expense_pay_materialisations m where m.root_timesheet_id=p_root_id
        and m.candidate_timesheet_financial_id=(v_origin->>'financial_snapshot_id')::uuid;
  elsif v_origin->>'kind'='COMMITTED_SOURCE_HEAD_V1' then
    v_source:=v_origin->'source_revision';
    if v_source->>'origin_kind'='PROTECTED_LOCAL_DECISION_V1' then
      select coalesce(jsonb_agg(x#>'{document,source_expense_id}' order by x#>>'{document,source_expense_id}'),'[]') into v_ids
        from jsonb_array_elements(private.weekly_source_staged_source_documents_v1((v_source->>'publication_request_id')::uuid)) x
        where x->>'authority_kind'='SOURCE_EXPENSE';
    elsif v_source->>'final_revision_id' is not null and coalesce(v_source->>'origin_kind','CURRENT_FINAL_SOURCE_V1')='CURRENT_FINAL_SOURCE_V1' then
      select coalesce(jsonb_agg(x->'expense_authority_generation_id' order by x->>'expense_authority_generation_id'),'[]') into v_ids
        from jsonb_array_elements(private.weekly_source_ordinary_projection_current_expenses_v1(
          p_root_id,(v_source->>'final_revision_id')::uuid)) x;
    else raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_UNAVAILABLE' using errcode='55000'; end if;
  else raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_UNAVAILABLE' using errcode='55000'; end if;
  v_result:=private.weekly_source_expense_authority_evidence_v1(p_root_id,v_ids);
  if jsonb_array_length(v_result)<>(select count(*) from jsonb_array_elements(v_components) x where x->>'component_kind'='SOURCE_FIXED_EXPENSE')
    or exists(select 1 from jsonb_array_elements(v_components) c where c->>'component_kind'='SOURCE_FIXED_EXPENSE'
      and (select count(*) from jsonb_array_elements(v_result) e where e->>'work_event_id'=c->>'component_member_identity'
        and e->>'source_observation_kind'=c->>'expense_code'
        and (e->>'candidate_reimbursement_ex_vat')::numeric=(c->>'pay_ex_vat')::numeric
        and (e->>'client_charge_ex_vat')::numeric=(c->>'charge_ex_vat')::numeric)<>1) then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_UNAVAILABLE' using errcode='55000'; end if;
  return v_result;
end;
$function$;
alter function private.weekly_source_approved_expense_evidence_v1(uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_approved_expense_evidence_v1(uuid,jsonb) from public,anon,authenticated,service_role;

-- One producer for both the assertion and the actual authorised Local arm.
-- I1 components come only from native stable-ID composers. C1 UUIDs remain
-- transport identities, separately checked against the sealed native snapshot.
create or replace function private.weekly_source_staged_entitlement_components_v1(p_request_id uuid,p_actor_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_context jsonb; v_snapshot jsonb; v_segments jsonb; v_expenses jsonb; v_ids jsonb; v_evidence jsonb;
  v_components jsonb; v_expected jsonb:='[]'; v_common jsonb; v_item jsonb; v_raw jsonb; v_row jsonb; v_doc jsonb; v_stored jsonb;
  v_entry record; t public.weekly_exceptional_c1_component_records%rowtype;
  r public.weekly_exceptional_c1_publication_requests%rowtype; a public.weekly_exceptional_payment_approvals%rowtype;
  v_code text; v_source_key text; v_count integer; v_key text; v_i integer:=0; v_ordinal integer:=0;
begin
  v_context:=private.weekly_source_staged_publication_context_v1(p_request_id,p_actor_id);
  select * into strict r from public.weekly_exceptional_c1_publication_requests where id=p_request_id;
  select * into strict a from public.weekly_exceptional_payment_approvals where id=(v_context->>'approval_id')::uuid;
  v_snapshot:=v_context#>'{target_snapshot,tsfin_snapshot_json}'; v_segments:=v_snapshot#>'{invoice_breakdown_json,segments}';
  if jsonb_typeof(v_segments) is distinct from 'array' or v_snapshot#>>'{invoice_breakdown_json,mode}' is distinct from 'SEGMENTS'
    or jsonb_array_length(v_segments)>100 or jsonb_typeof(v_snapshot->'additional_units_json') is distinct from 'object' then
    raise exception 'WEEKLY_SOURCE_STAGED_COMPONENTS_UNAVAILABLE' using errcode='55000'; end if;
  -- This is the exact current native Local expense selection, not an arbitrary
  -- later resolution. Each selected ID must also exist in the sealed C1 source.
  select coalesce(jsonb_agg(expense.id order by expense.work_event_id),'[]') into v_ids from (
    select authority.*,row_number() over(partition by authority.work_event_id order by cycle.finalisation_week_ending desc,
      revision.finalised_at_utc desc,authority.generation desc,authority.id desc) event_rank
    from public.weekly_expense_authority_generations authority
    join public.weekly_source_final_revisions revision on revision.id=authority.final_revision_id and revision.state='CURRENT'
    join public.weekly_source_cycles cycle on cycle.id=revision.source_cycle_id
    join public.weekly_source_cycles action_cycle on action_cycle.id=a.source_cycle_id
    where authority.contract_id=r.contract_id and authority.state='CURRENT' and cycle.source_group_id=action_cycle.source_group_id
      and exists(select 1 from public.weekly_source_row_timesheet_lineages lineage where lineage.work_event_id=authority.work_event_id
        and lineage.contract_id=authority.contract_id and lineage.timesheet_id=any(private.weekly_source_invoice_family_timesheet_ids_v1(r.root_timesheet_id)))
  ) expense where expense.event_rank=1 and expense.source_expense_pence>0;
  v_evidence:=private.weekly_source_expense_authority_evidence_v1(r.root_timesheet_id,v_ids);
  if jsonb_array_length(v_evidence)<>(select count(*) from jsonb_array_elements(v_context->'source_documents') x where x->>'authority_kind'='SOURCE_EXPENSE')
    or exists(select 1 from jsonb_array_elements(v_evidence) e where
      (select count(*) from jsonb_array_elements(v_context->'source_documents') d where d->>'authority_kind'='SOURCE_EXPENSE'
        and d#>>'{document,source_expense_id}'=e->>'authority_id' and d->>'external_identity'=e->>'authority_id'
        and d->>'source_document_sha256'=e->>'authority_hash'
        and d#>>'{document,expense_code}'=upper('SOURCE_SUPPLIED:'||(e->>'work_event_id'))
        and (d#>>'{document,pay_ex_vat}')::numeric=(e->>'candidate_reimbursement_ex_vat')::numeric
        and (d#>>'{document,charge_ex_vat}')::numeric=(e->>'client_charge_ex_vat')::numeric)<>1) then
    raise exception 'WEEKLY_SOURCE_STAGED_EXPENSE_CHANGED' using errcode='40001'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('work_event_id',e->'work_event_id','source_observation_kind',e->'source_observation_kind',
    'candidate_reimbursement_ex_vat',e->'candidate_reimbursement_ex_vat','client_charge_ex_vat',e->'client_charge_ex_vat') order by e->>'work_event_id'),'[]')
    into v_expenses from jsonb_array_elements(v_evidence) e;
  v_components:=private.weekly_source_initial_additional_components_v2(
    private.weekly_source_entitlement_components_v1(v_segments,v_expenses),v_snapshot->'additional_units_json',
    (v_snapshot->>'additional_pay_ex_vat')::numeric,(v_snapshot->>'additional_charge_ex_vat')::numeric,
    v_context#>>'{scope,family_booking_id}');
  if exists(select 1 from jsonb_array_elements(v_components) c group by c->>'component_id' having count(*)<>1)
    or (select coalesce(sum((c->>'pay_ex_vat')::numeric) filter(where not (c->>'exclude_from_pay')::boolean),0)
      from jsonb_array_elements(v_components) c) is distinct from a.approved_target_gross then
    raise exception 'WEEKLY_SOURCE_STAGED_COMPONENTS_UNAVAILABLE' using errcode='55000'; end if;
  -- Exact existing C1 carrier projection. No total-only equivalence or reuse
  -- of transport IDs in the I1 component namespace.
  v_common:=jsonb_build_object('component_id',null,'component_kind',null,'economic_key_type',null,'economic_key_value',null,
    'component_member_identity',null,'segment_id',null,'segment_key',null,'segment_stable_key',null,'work_date',null,'reference_number',null,
    'hours_day',null,'hours_night',null,'hours_sat',null,'hours_sun',null,'hours_bh',null,'additional_code_raw',null,
    'unit_count',null,'unit_pay_rate',null,'unit_charge_rate',null,'expense_code',null,'pay_ex_vat','0.00','charge_ex_vat',null,
    'exclude_from_pay',false,'origin','WEEKLY_SOURCE_APPROVED_TARGET','movement_id',null,'movement_group_id',null);
  for v_raw in select value from jsonb_array_elements(v_segments) loop
    v_i:=v_i+1; v_source_key:='10:'||r.root_timesheet_id::text||':SEGMENT:'||lpad(v_i::text,12,'0');
    v_item:=v_common||jsonb_build_object('source_key',v_source_key,'component_kind','WORKED_TIME','economic_key_type','TS_DAY',
      'economic_key_value',v_raw->>'date','component_member_identity',coalesce(v_raw->>'segment_stable_key',v_raw->>'segment_id',v_raw->>'segment_key'),
      'segment_id',v_raw->>'segment_id','segment_key',coalesce(v_raw->>'segment_key',v_raw->>'segment_id'),
      'segment_stable_key',coalesce(v_raw->>'segment_stable_key',v_raw->>'segment_id',v_raw->>'segment_key'),
      'work_date',v_raw->>'date','reference_number',nullif(btrim(v_raw->>'ref_num'),''),
      'pay_ex_vat',case when v_raw->'exclude_from_pay'='true'::jsonb then '0.00' else v_raw->>'pay_amount' end,
      'charge_ex_vat',v_raw->>'charge_amount','exclude_from_pay',coalesce((v_raw->>'exclude_from_pay')::boolean,false));
    foreach v_key in array array['day','night','sat','sun','bh'] loop
      v_item:=v_item||jsonb_build_object('hours_'||v_key,coalesce(v_raw->>('hours_'||v_key),'0'));
    end loop;
    v_expected:=v_expected||jsonb_build_array(v_item);
  end loop;
  for v_entry in select key,value from jsonb_each(v_snapshot->'additional_units_json') loop
    v_raw:=v_entry.value; v_code:=btrim(v_entry.key);
    if (coalesce(v_raw->>'pay_ex_vat',v_raw->>'amount_ex_vat'))::numeric=0 then continue; end if;
    v_source_key:='10:'||r.root_timesheet_id::text||':ADDITIONAL:'||lpad(octet_length(convert_to(v_code,'UTF8'))::text,10,'0')||':'||encode(convert_to(v_code,'UTF8'),'hex');
    v_expected:=v_expected||jsonb_build_array(v_common||jsonb_build_object('source_key',v_source_key,'component_kind','ADDITIONAL_UNIT',
      'economic_key_type','ADDITIONAL_CODE','economic_key_value',upper(v_code),'component_member_identity','additional:'||upper(v_code),
      'additional_code_raw',v_code,'unit_count',coalesce(v_raw->>'unit_count',v_raw->>'units_week'),
      'unit_pay_rate',coalesce(v_raw->>'pay_rate',v_raw->>'rate'),'unit_charge_rate',v_raw->>'charge_rate',
      'pay_ex_vat',coalesce(v_raw->>'pay_ex_vat',v_raw->>'amount_ex_vat'),'charge_ex_vat',coalesce(v_raw->>'charge_ex_vat',v_raw->>'charge_amount_ex_vat')));
  end loop;
  for v_raw in select value from jsonb_array_elements(v_evidence) loop
    v_code:=upper('SOURCE_SUPPLIED:'||(v_raw->>'work_event_id'));
    v_expected:=v_expected||jsonb_build_array(v_common||jsonb_build_object('source_key','10:'||r.root_timesheet_id::text||':EXPENSE:'||v_code,
      'component_kind','EXPENSE','economic_key_type','EXPENSE_CODE','economic_key_value',v_code,'component_member_identity','expense:'||v_code,
      'expense_code',v_code,'pay_ex_vat',v_raw->>'candidate_reimbursement_ex_vat','charge_ex_vat',v_raw->>'client_charge_ex_vat'));
  end loop;
  -- Ordinary non-source expenses have no native I1 mapper in this publisher.
  -- Refuse an unmapped authority; never discard it to make a zero-delta claim.
  if exists(select 1 from jsonb_array_elements(v_context->'source_documents') x where x->>'authority_kind'='ORDINARY_EXPENSE') then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_ORDINARY_EXPENSE_UNMAPPED' using errcode='55000'; end if;
  if (select count(*) from public.weekly_exceptional_c1_component_records where publication_request_id=r.id)
      is distinct from r.expected_component_count or jsonb_array_length(v_expected) is distinct from r.expected_component_count then
    raise exception 'WEEKLY_SOURCE_STAGED_TRANSPORT_COMPONENTS_CHANGED' using errcode='40001'; end if;
  for v_item in select value from jsonb_array_elements(v_expected) order by value->>'source_key' collate "C" loop
    v_ordinal:=v_ordinal+1;
    select * into strict t from public.weekly_exceptional_c1_component_records where publication_request_id=r.id and source_key=v_item->>'source_key';
    select x into strict v_row from public.weekly_exceptional_c1_publication_requests request
      join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id
      cross join lateral jsonb_array_elements(generation.complete_next_vector_json->'components') x
      where request.id=r.id and x->>'component_id'=t.component_id::text;
    v_doc:=null;
    select x into strict v_doc from jsonb_array_elements(v_context->'source_documents') x where (x->>'source_ordinal')::integer=t.source_ordinal;
    v_stored:=(to_jsonb(t)-array['id','publication_request_id','created_at_utc','component_sha256','source_ordinal','source_key'])
      ||jsonb_build_object('movement_id',null,'movement_group_id',null);
    -- The native closed component codec requires decimal STRINGS. SQL numeric
    -- columns are losslessly cast to text before invoking that existing codec.
    foreach v_key in array array['hours_day','hours_night','hours_sat','hours_sun','hours_bh',
      'unit_count','unit_pay_rate','unit_charge_rate','pay_ex_vat','charge_ex_vat'] loop
      v_stored:=v_stored||jsonb_build_object(v_key,to_jsonb(t)->>v_key);
    end loop;
    if t.component_ordinal is distinct from v_ordinal or t.component_sha256 is distinct from decode(v_row->>'component_sha256','hex')
      or v_row->>'source_key' is distinct from t.source_key or (v_row->>'source_ordinal')::integer is distinct from t.source_ordinal
      or private.weekly_source_publication_component_canonical_v1(v_stored,'staged.transport.row') is distinct from
        private.weekly_source_publication_component_canonical_v1(
          (v_row-array['source_ordinal','source_key','component_sha256','record_type'])
            ||jsonb_build_object('movement_id',null,'movement_group_id',null),'staged.transport.vector')
      or private.weekly_source_publication_component_canonical_v1(
        (v_item-'source_key')||jsonb_build_object('component_id',t.component_id,'component_ordinal',v_ordinal),'staged.transport.expected') is distinct from
        private.weekly_source_publication_component_canonical_v1(
          (v_row-array['source_ordinal','source_key','component_sha256','record_type'])
            ||jsonb_build_object('movement_id',null,'movement_group_id',null),'staged.transport.vector') then
      raise exception 'WEEKLY_SOURCE_STAGED_TRANSPORT_COMPONENTS_CHANGED' using errcode='40001'; end if;
    if t.component_kind in ('WORKED_TIME','ADDITIONAL_UNIT') then
      if v_doc->>'authority_kind' is distinct from 'APPROVED_COMPONENT' or v_doc->>'external_identity' is distinct from t.component_id::text
        or v_doc#>>'{document,source_key}' is distinct from t.source_key
        or (v_doc#>>'{document,source_ordinal}')::integer is distinct from t.source_ordinal
        or private.weekly_source_publication_component_canonical_v1(
          (v_doc->'document'-array['contract','source_id','source_system','external_identity','external_revision','root_timesheet_id','candidate_id','contract_id','week_ending_date','document_sha256','source_ordinal','source_key'])
            ||jsonb_build_object('movement_id',null,'movement_group_id',null),'staged.transport.document') is distinct from
          private.weekly_source_publication_component_canonical_v1(
            (v_row-array['source_ordinal','source_key','component_sha256','record_type'])
              ||jsonb_build_object('movement_id',null,'movement_group_id',null),'staged.transport.vector') then
        raise exception 'WEEKLY_SOURCE_STAGED_TRANSPORT_COMPONENTS_CHANGED' using errcode='40001'; end if;
    elsif t.component_kind='EXPENSE' then
      if v_doc->>'authority_kind' is distinct from 'SOURCE_EXPENSE' or v_doc#>>'{document,expense_code}' is distinct from t.expense_code
        or (v_doc#>>'{document,pay_ex_vat}')::numeric is distinct from t.pay_ex_vat
        or (v_doc#>>'{document,charge_ex_vat}')::numeric is distinct from t.charge_ex_vat then
        raise exception 'WEEKLY_SOURCE_STAGED_TRANSPORT_COMPONENTS_CHANGED' using errcode='40001'; end if;
    else raise exception 'WEEKLY_SOURCE_STAGED_TRANSPORT_COMPONENTS_CHANGED' using errcode='40001'; end if;
  end loop;
  if (select count(*) from jsonb_array_elements(v_context->'source_documents') x where x->>'authority_kind'='APPROVED_COMPONENT')<>
      (select count(*) from jsonb_array_elements(v_expected) x where x->>'component_kind' in ('WORKED_TIME','ADDITIONAL_UNIT')) then
    raise exception 'WEEKLY_SOURCE_STAGED_TRANSPORT_COMPONENTS_CHANGED' using errcode='40001'; end if;
  return jsonb_build_object('context',v_context,'components',v_components,'expenses',v_expenses,'expense_evidence',v_evidence,
    'transport_component_count',v_ordinal);
exception when no_data_found or too_many_rows or invalid_text_representation or numeric_value_out_of_range then
  raise exception 'WEEKLY_SOURCE_STAGED_COMPONENTS_UNAVAILABLE' using errcode='55000';
end;
$function$;
alter function private.weekly_source_staged_entitlement_components_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_staged_entitlement_components_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- Actual sealed native stage -> complete native I1 line/component proof.
-- Seven-field certificate stays compatible with Source27. The qualification
-- digest commits to every component, frozen detail, source and expense proof.
create or replace function private.weekly_source_automatic_reconcile_delta_assert_v1(p_request_id uuid,p_actor_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare r public.weekly_exceptional_c1_publication_requests%rowtype; g public.weekly_exceptional_pay_generations%rowtype;
  run public.weekly_exceptional_orchestration_runs%rowtype; event public.weekly_exceptional_pay_family_events%rowtype;
  old_approval public.weekly_exceptional_payment_approvals%rowtype; approval public.weekly_exceptional_payment_approvals%rowtype;
  v_produced jsonb; v_context jsonb; v_proof jsonb; v_wait jsonb; v_prior_receipt jsonb; v_current jsonb; v_before jsonb;
  v_detail jsonb; v_expenses_before jsonb; v_snapshot jsonb; v_components jsonb; v_before_component jsonb; v_next_component jsonb;
  v_old_raw jsonb; v_raw jsonb; v_source jsonb; v_before_rate jsonb; v_before_charge_rate jsonb; v_key text;
  v_prior_work_count integer; v_count integer; v_component_proofs jsonb:='[]'; v_expense_proofs jsonb:='[]'; v_policy jsonb;
  v_rules jsonb; v_cas jsonb; v_facts jsonb; v_qualification jsonb; v_before_expense jsonb; v_next_expense jsonb;
begin
  if p_request_id is null or p_actor_id is null then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='22023'; end if;
  select * into strict r from public.weekly_exceptional_c1_publication_requests where id=p_request_id;
  select * into strict g from public.weekly_exceptional_pay_generations where id=r.generation_id and family_id=r.family_id;
  select * into strict run from public.weekly_exceptional_orchestration_runs where id=r.orchestration_run_id and family_id=r.family_id;
  v_proof:=g.complete_next_vector_json->'automatic_reconcile_proof'; v_wait:=v_proof->'qualified_wait';
  -- Same actor/date/rules/release owner as native Source27, never a parallel capability classifier.
  perform private.weekly_source_automatic_reconcile_capability_assert_v1((v_proof->>'source_cycle_id')::uuid);
  v_produced:=private.weekly_source_staged_entitlement_components_v1(r.id,p_actor_id);
  v_context:=v_produced->'context'; v_before:=v_context->'prior_inventory'; v_components:=v_produced->'components';
  v_snapshot:=v_context#>'{target_snapshot,tsfin_snapshot_json}';
  select * into strict event from public.weekly_exceptional_pay_family_events where id=(v_context->>'family_event_id')::uuid;
  select * into strict approval from public.weekly_exceptional_payment_approvals where id=(v_context->>'approval_id')::uuid;
  select * into strict old_approval from public.weekly_exceptional_payment_approvals where id=(v_wait->>'approval_id')::uuid;
  if run.request_kind is distinct from 'RECONCILE' or event.state is distinct from 'ACCEPTED_SOURCE'
    or not private.weekly_exceptional_json_keys_exact_v1(v_proof,array['schema_version','eligible','actor_user_id','source_cycle_id',
      'work_event_id','qualified_wait','rule_set_version_id','rule_values_sha256','source_proposal','self_bill_facts','source_cas',
      'approved_inventory_basis','selection_sha256'])
    or not(v_proof ?& array['schema_version','eligible','actor_user_id','source_cycle_id','work_event_id','qualified_wait',
      'rule_set_version_id','rule_values_sha256','source_proposal','self_bill_facts','source_cas','approved_inventory_basis','selection_sha256'])
    or v_proof->>'schema_version' is distinct from 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SELECTION_V1'
    or v_proof->>'eligible' is distinct from 'true' or v_proof->>'actor_user_id' is distinct from p_actor_id::text
    or v_proof->>'source_cycle_id' is distinct from v_context->>'source_cycle_id'
    or v_proof->>'work_event_id' is distinct from v_context->>'work_event_id'
    or v_proof->'source_proposal' is distinct from v_context->'source_proposal'
    or v_proof->'approved_inventory_basis' is distinct from v_before->'approval_basis'
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SELECTION_V1',v_proof-'selection_sha256')
      is distinct from private.weekly_exceptional_hex_sha256_v1(v_proof->>'selection_sha256')
    or v_wait->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_V1' or v_wait->>'state' is distinct from 'QUALIFIED_WAIT'
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_V1',v_wait-'qualification_sha256')
      is distinct from private.weekly_exceptional_hex_sha256_v1(v_wait->>'qualification_sha256')
    or v_wait->>'root_timesheet_id' is distinct from r.root_timesheet_id::text or v_wait->>'family_id' is distinct from r.family_id::text
    or v_wait->>'work_event_id' is distinct from event.durable_work_event_id::text
    or v_wait->>'candidate_id' is distinct from v_context#>>'{scope,candidate_id}'
    or v_wait->>'client_id' is distinct from v_context#>>'{scope,client_id}' or v_wait->>'contract_id' is distinct from r.contract_id::text
    or v_wait->>'family_bound_version' is distinct from v_context->>'before_bound_version'
    or v_wait->>'current_generation_id' is distinct from g.prior_generation_id::text
    or (v_wait->>'current_generation_number')::integer is distinct from g.generation_number-1
    or old_approval.withdrawn_at_utc is not null or old_approval.pay_target_family_id is distinct from r.family_id
    or old_approval.work_event_id is distinct from event.durable_work_event_id
    or old_approval.contract_rate_policy_source_fingerprint is distinct from approval.contract_rate_policy_source_fingerprint
    or (old_approval.protected_work_date,old_approval.protected_start_at_local,old_approval.protected_end_at_local,old_approval.protected_break_minutes)
      is distinct from (approval.protected_work_date,approval.protected_start_at_local,approval.protected_end_at_local,approval.protected_break_minutes) then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
  v_prior_receipt:=private.weekly_source_staged_prior_wait_receipt_v1(r.id,p_actor_id);
  if v_prior_receipt is null or v_prior_receipt->'accepted_receipt' is distinct from v_wait->'accepted_receipt' then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_PRIOR_WAIT_UNAVAILABLE' using errcode='55000'; end if;
  -- Source CAS deliberately excludes pending protected stage mutations. Do not
  -- normalize any Source/export/report/economic/expense/hold authority changes.
  v_cas:=private.weekly_source_bulk_source_cas_assert_v1((v_proof->>'source_cycle_id')::uuid,array[(v_context#>>'{scope,client_id}')::uuid]);
  v_rules:=private.weekly_source_effective_rule_set_v1((v_context#>>'{scope,client_id}')::uuid,(v_proof->>'source_cycle_id')::uuid);
  v_facts:=private.weekly_source_shift_on_self_bill_v1((v_proof->>'work_event_id')::uuid,(v_proof->>'source_cycle_id')::uuid);
  if v_cas is distinct from v_proof->'source_cas' or v_rules->'rule_set_version_id' is distinct from v_proof->'rule_set_version_id'
    or v_rules->'values_sha256' is distinct from v_proof->'rule_values_sha256' or v_facts is distinct from v_proof->'self_bill_facts' then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SOURCE_CHANGED' using errcode='40001'; end if;
  -- Read the real current approved position at K+1, qualified above against the
  -- sealed K position. Passing a hand-normalized inventory to approval_basis
  -- would be a false proof, so only staged_context performs the K adjustment.
  v_current:=private.weekly_source_effective_inventory_v1(r.root_timesheet_id);
  v_detail:=private.weekly_source_approved_detail_evidence_v1(r.root_timesheet_id,v_current);
  v_expenses_before:=private.weekly_source_approved_expense_evidence_v1(r.root_timesheet_id,v_current);
  if v_detail#>>'{approval_basis,detail_digest}' is distinct from v_before#>>'{approval_basis,detail_digest}'
    or jsonb_array_length(v_components) is distinct from jsonb_array_length(v_before->'components') then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_COMPONENT_DELTA_NONZERO' using errcode='40001'; end if;
  select count(*) into v_prior_work_count from jsonb_array_elements(v_before->'components') c where c->>'component_kind'='WORKED_TIME';
  if v_current#>>'{approval_basis,origin,kind}'='INITIAL_AUTHORISED_TSFIN_V1'
    and (v_snapshot->'policy_snapshot_json' is distinct from v_detail->'policy'
      or v_snapshot->'rate_source_refs_json' is distinct from v_detail#>'{details,rate_source_refs}') then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_FROZEN_POLICY_CHANGED' using errcode='40001'; end if;
  for v_before_component in select value from jsonb_array_elements(v_before->'components') loop
    select value into strict v_next_component from jsonb_array_elements(v_components)
      where value->>'component_id'=v_before_component->>'component_id';
    v_before_component:=private.weekly_source_publication_component_canonical_v1(v_before_component-'component_sha256','automatic.before');
    v_next_component:=private.weekly_source_publication_component_canonical_v1(v_next_component,'automatic.next');
    foreach v_key in array array['component_kind','economic_key_type','economic_key_value','component_member_identity','segment_id','segment_key','segment_stable_key',
      'work_date','reference_number','additional_code_raw','expense_code','exclude_from_pay','origin','movement_id','movement_group_id'] loop
      if v_before_component->v_key is distinct from v_next_component->v_key then
        raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_COMPONENT_IDENTITY_CHANGED' using errcode='40001'; end if;
    end loop;
    foreach v_key in array array['hours_day','hours_night','hours_sat','hours_sun','hours_bh','unit_count','unit_pay_rate','unit_charge_rate','pay_ex_vat','charge_ex_vat'] loop
      if (v_before_component->>v_key)::numeric is distinct from (v_next_component->>v_key)::numeric then
        raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_COMPONENT_DELTA_NONZERO' using errcode='40001',
          detail=jsonb_build_object('component_id',v_before_component->'component_id','field',v_key)::text; end if;
    end loop;
    v_old_raw:=null; v_source:=null;
    if v_before_component->>'component_kind'='WORKED_TIME' then
      select value into strict v_raw from jsonb_array_elements(v_snapshot#>'{invoice_breakdown_json,segments}')
        where value->>'segment_id'=v_next_component->>'segment_id';
      if v_current#>>'{approval_basis,origin,kind}'='INITIAL_AUTHORISED_TSFIN_V1' then
        select value into strict v_old_raw from jsonb_array_elements(v_detail#>'{details,segments}')
          where value->>'segment_id'=v_before_component->>'segment_id';
        foreach v_key in array array['date','start','end','overnight','break_mins','breaks','start_utc','end_utc'] loop
          if v_old_raw->v_key is distinct from v_raw->v_key then
            raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_APPROVED_DETAIL_CHANGED' using errcode='40001'; end if;
        end loop;
      else
        select value->'detail' into strict v_old_raw from jsonb_array_elements(v_detail->'details')
          where value->>'component_id'=v_before_component->>'component_id';
        if v_old_raw->>'work_date' is distinct from v_raw->>'date' or v_old_raw->>'start' is distinct from v_raw->>'start'
          or v_old_raw->>'end' is distinct from v_raw->>'end' or v_old_raw->'overnight' is distinct from v_raw->'overnight'
          or v_old_raw->'breaks' is distinct from v_raw->'breaks'
          or (jsonb_array_length(v_raw->'breaks')=0 and (v_old_raw->>'break_minutes')::integer is distinct from (v_raw->>'break_mins')::integer)
          or (jsonb_array_length(v_raw->'breaks')>0 and (v_raw->>'break_mins')::integer is distinct from 0)
          or v_old_raw->'start_utc' is distinct from v_raw->'start_utc' or v_old_raw->'end_utc' is distinct from v_raw->'end_utc' then
          raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_APPROVED_DETAIL_CHANGED' using errcode='40001'; end if;
      end if;
      -- Native Local capture uses the sealed snapshot's band rates; initial
      -- approved basis uses its own exact Source vectors/single frozen TSFIN.
      -- HEAD basis uses the real chosen-detail row qualified by approval_basis.
      foreach v_key in array array['day','night','sat','sun','bh'] loop
        if v_current#>>'{approval_basis,origin,kind}'='INITIAL_AUTHORISED_TSFIN_V1' then
          v_before_rate:=case when jsonb_typeof(v_old_raw->'weekly_source')='object' then v_old_raw#>array['weekly_source','pay_vector','rates',v_key]
            when v_prior_work_count=1 then v_detail#>array['financial_rate_evidence','pay',v_key] else null end;
          v_before_charge_rate:=case when jsonb_typeof(v_old_raw->'weekly_source')='object' then v_old_raw#>array['weekly_source','charge_vector','rates',v_key]
            when v_prior_work_count=1 then v_detail#>array['financial_rate_evidence','charge',v_key] else null end;
        else v_before_rate:=v_old_raw#>array['rates',v_key]; v_before_charge_rate:=v_old_raw#>array['charge_rates',v_key]; end if;
        if ((v_next_component->>('hours_'||v_key))::numeric<>0 and ((v_before_rate#>>'{}')::numeric is null
            and not (v_next_component->>'exclude_from_pay')::boolean or (v_before_charge_rate#>>'{}')::numeric is null))
          or (v_before_rate#>>'{}')::numeric is distinct from (v_snapshot->>('pay_'||v_key))::numeric
          or (v_before_charge_rate#>>'{}')::numeric is distinct from (v_snapshot->>('charge_'||v_key))::numeric then
          raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_APPROVED_RATE_CHANGED' using errcode='40001'; end if;
      end loop;
      -- This selected shift is now ACCEPTED_SOURCE. Its actual immutable
      -- Source economics must equal the saved producer output, not only clocks.
      if v_next_component->>'component_member_identity'=v_context->>'work_event_id' then
        select value into strict v_source from jsonb_array_elements(v_context->'next_source_segments')
          where value#>>'{weekly_source,work_event_id}'=v_context->>'work_event_id';
        if v_source->>'segment_id' is distinct from v_raw->>'segment_id' or v_source->>'date' is distinct from v_raw->>'date'
          or v_source->>'start' is distinct from v_raw->>'start' or v_source->>'end' is distinct from v_raw->>'end'
          or (v_source->>'break_mins')::integer is distinct from (v_raw->>'break_mins')::integer
          or (v_source->>'pay_amount')::numeric is distinct from (v_raw->>'pay_amount')::numeric
          or (v_source->>'charge_amount')::numeric is distinct from (v_raw->>'charge_amount')::numeric
          or v_source->'weekly_source' is distinct from v_raw->'weekly_source' then
          raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SOURCE_VECTOR_CHANGED' using errcode='40001'; end if;
        foreach v_key in array array['day','night','sat','sun','bh'] loop
          if (v_source->>('hours_'||v_key))::numeric is distinct from (v_raw->>('hours_'||v_key))::numeric
            or (v_source#>>array['weekly_source','pay_vector','rates',v_key])::numeric is distinct from (v_snapshot->>('pay_'||v_key))::numeric
            or (v_source#>>array['weekly_source','charge_vector','rates',v_key])::numeric is distinct from (v_snapshot->>('charge_'||v_key))::numeric then
            raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SOURCE_VECTOR_CHANGED' using errcode='40001'; end if;
        end loop;
      end if;
    elsif v_before_component->>'component_kind' not in ('ADDITIONAL_UNIT','SOURCE_FIXED_EXPENSE') then
      raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_COMPONENT_UNMAPPED' using errcode='55000';
    end if;
    v_component_proofs:=v_component_proofs||jsonb_build_array(jsonb_build_object('before',v_before_component,'next',v_next_component,
      'approved_detail',v_old_raw,'next_detail',case when v_before_component->>'component_kind'='WORKED_TIME' then v_raw else null end,
      'source_evidence',v_source));
  end loop;
  if jsonb_array_length(v_expenses_before) is distinct from jsonb_array_length(v_produced->'expense_evidence') then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_POLICY_CHANGED' using errcode='40001'; end if;
  for v_before_expense in select value from jsonb_array_elements(v_expenses_before) loop
    select value into strict v_next_expense from jsonb_array_elements(v_produced->'expense_evidence')
      where value->>'work_event_id'=v_before_expense->>'work_event_id';
    if v_before_expense->'policy' is distinct from v_next_expense->'policy'
      or v_before_expense->'source_observation_kind' is distinct from v_next_expense->'source_observation_kind' then
      raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_EXPENSE_POLICY_CHANGED' using errcode='40001'; end if;
    v_expense_proofs:=v_expense_proofs||jsonb_build_array(jsonb_build_object('before',v_before_expense,'next',v_next_expense));
  end loop;
  -- The outer certificate reports zero only after every actual native component
  -- passed its identity/quantity/rate/money/policy comparison independently.
  v_qualification:=jsonb_build_object('schema_version','WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_QUALIFICATION_V1',
    'publication_request_id',r.id,'actor_user_id',p_actor_id,'stage_context',v_context,'automatic_selection',v_proof,
    'prior_wait_receipt',v_prior_receipt,'approved_basis',v_detail,'source_cas',v_cas,'component_proofs',v_component_proofs,
    'expense_proofs',v_expense_proofs,'native_next_components',v_components);
  return jsonb_build_object('schema_version','WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_V1','publication_request_id',r.id,
    'actor_user_id',p_actor_id,'prior_inventory_digest',v_before->'inventory_digest',
    'complete_next_vector_sha256',encode(g.complete_next_vector_hash,'hex'),'delta_pay_ex_vat','0.00',
    'qualification_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_QUALIFICATION_V1',v_qualification),'hex'));
exception when no_data_found or too_many_rows or invalid_text_representation or numeric_value_out_of_range then
  raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000';
end;
$function$;
alter function private.weekly_source_automatic_reconcile_delta_assert_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_automatic_reconcile_delta_assert_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- Complete native owner successor; only sealed automatic requests use the common producer.
create or replace function public.weekly_exceptional_pay_complete_local_v1(p_request jsonb)
returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
set lock_timeout to '2500ms'
set statement_timeout to '30s'
as $function$
declare
  v_keys constant text[]:=array['schema_version','actor_user_id','publication_request_id',
    'expected_request_sha256','idempotency_key'];
  v_actor uuid;
  v_request_id uuid;
  v_hash bytea;
  v_key text;
  v_request public.weekly_exceptional_c1_publication_requests%rowtype;
  v_generation public.weekly_exceptional_pay_generations%rowtype;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_approval public.weekly_exceptional_payment_approvals%rowtype;
  v_root public.timesheets%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_receipt private.weekly_source_local_protected_decision_receipts%rowtype;
  v_locks jsonb;
  v_snapshot jsonb;
  v_result jsonb;
  v_write jsonb;
  v_proposal jsonb;
  v_components jsonb;
  v_automatic_components jsonb;
  v_expenses jsonb;
  v_head_request jsonb;
  v_target_state text;
  v_source_hash bytea;
  v_result_hash bytea;
  v_live_authorisations integer;
  v_bundle_id uuid;
  v_local_context jsonb;
  v_local_origin jsonb;
  v_pending boolean:=false;
  v_manual_review_id uuid;
  v_rate_policy_hash bytea;
  v_scope_date date; v_scope_group uuid; v_scope_client uuid;
begin
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,v_keys)
     or not (p_request ?& v_keys)
     or p_request->>'schema_version'<>'WEEKLY_PROTECTED_LOCAL_COMPLETE_V1' then
    raise exception 'WEEKLY_PROTECTED_LOCAL_COMPLETE_INVALID' using errcode='22023';
  end if;
  v_actor:=(p_request->>'actor_user_id')::uuid;
  v_request_id:=(p_request->>'publication_request_id')::uuid;
  v_hash:=private.weekly_exceptional_hex_sha256_v1(p_request->>'expected_request_sha256');
  v_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  if v_actor is null or v_request_id is null or pg_catalog.char_length(v_key) not between 16 and 240
     or not private.weekly_source_pay_actor_allowed_v1(v_actor) then
    raise exception 'WEEKLY_PROTECTED_LOCAL_COMPLETE_SCOPE_INVALID' using errcode='42501';
  end if;

  -- Exact committed receipt precedes freshness checks, locks and publication.
  select * into v_receipt from private.weekly_source_local_protected_decision_receipts
    where publication_request_id=v_request_id;
  -- The retained action's own report cutoff remains the Office authority,
  -- including exact replay. Work date and a later unrelated upload are not it.
  select c.finalisation_week_ending,c.source_group_id,a.client_id
    into strict v_scope_date,v_scope_group,v_scope_client
    from public.weekly_exceptional_c1_publication_requests r
    join public.weekly_exceptional_payment_approvals a
      on a.creation_orchestration_run_id=r.orchestration_run_id and a.pay_target_family_id=r.family_id
    join public.weekly_source_cycles c on c.id=a.source_cycle_id
    where r.id=v_request_id;
  perform private.weekly_source_office_authority_v1(v_actor,'APPROVE_PROTECTED_PAY',
    v_scope_group,v_scope_client,v_scope_date);
  -- SELECT INTO above changes FOUND; test the retained receipt identity itself.
  if v_receipt.publication_request_id is not null then
    if v_receipt.actor_user_id is distinct from v_actor or v_receipt.request_sha256 is distinct from v_hash
       or v_receipt.idempotency_key is distinct from v_key or v_receipt.state='PREPARING' then
      raise exception 'WEEKLY_PROTECTED_LOCAL_REPLAY_CONFLICT' using errcode='55000';
    end if;
    return v_receipt.result_json||jsonb_build_object('idempotent_replay',true);
  end if;
  perform private.weekly_source_pay_query_admit_v2();
  select * into strict v_request from public.weekly_exceptional_c1_publication_requests where id=v_request_id;
  -- I-1: Candidate serial gate, then all canonical family members, then rows.
  v_locks:=private.weekly_source_lock_and_resolve_families_v1(v_request.candidate_id,
    array[v_request.root_timesheet_id],'WORKBENCH_CANDIDATE_ENTITLEMENT_PUBLICATION',
    v_request.id,'WEEKLY_SOURCE_ENTITLEMENT_PUBLICATION');
  if coalesce((v_locks->>'ok')::boolean,false) is not true then
    return v_locks||jsonb_build_object('ok',false);
  end if;
  select * into v_receipt from private.weekly_source_local_protected_decision_receipts
    where publication_request_id=v_request_id;
  if found then
    if v_receipt.actor_user_id is distinct from v_actor or v_receipt.request_sha256 is distinct from v_hash
       or v_receipt.idempotency_key is distinct from v_key or v_receipt.state='PREPARING' then
      raise exception 'WEEKLY_PROTECTED_LOCAL_REPLAY_CONFLICT' using errcode='55000';
    end if;
    return v_receipt.result_json||jsonb_build_object('idempotent_replay',true);
  end if;
  select * into strict v_family from public.weekly_exceptional_pay_target_families
    where id=v_request.family_id for update;
  select * into strict v_request from public.weekly_exceptional_c1_publication_requests
    where id=v_request_id for update;
  select * into strict v_generation from public.weekly_exceptional_pay_generations
    where id=v_request.generation_id and family_id=v_family.id for update;
  select * into strict v_run from public.weekly_exceptional_orchestration_runs
    where id=v_request.orchestration_run_id and family_id=v_family.id for update;
  select * into strict v_approval from public.weekly_exceptional_payment_approvals
    where creation_orchestration_run_id=v_run.id and pay_target_family_id=v_family.id for share;
  select * into strict v_root from public.timesheets where timesheet_id=v_family.root_timesheet_id for update;
  select * into strict v_fin from public.timesheets_financials
    where timesheet_id=v_root.timesheet_id and is_current for update;
  if v_hash is distinct from v_request.request_sha256 or v_run.requested_by_user_id is distinct from v_actor
     or v_request.state<>'READY' or v_run.state<>'RUNNING' or v_generation.lifecycle_state<>'PENDING_C1'
     or v_request.c1_operation_id is not null or v_request.c1_publication_id is not null
     or v_request.c1_head_revision is not null or v_request.c1_receipt_sha256 is not null
     or exists(select 1 from public.weekly_exceptional_c1_publication_checkpoints c where c.publication_request_id=v_request.id)
     or exists(select 1 from public.weekly_exceptional_c1_unknown_outcomes u
                where u.publication_request_id=v_request.id and u.state='RECOVERY_REQUIRED')
     or v_family.current_generation_id is distinct from v_generation.prior_generation_id
     or v_family.current_generation_number+1 is distinct from v_generation.generation_number
     or v_fin.id is distinct from v_request.financial_row_id
     or not v_root.is_current or v_root.revoked_at is not null or v_root.archived_at_utc is not null
     or v_root.contract_id is distinct from v_family.contract_id
     or v_root.week_ending_date is distinct from v_family.week_ending_date
     or v_root.version is distinct from (v_generation.complete_next_vector_json#>>'{target_snapshot,tsfin_snapshot_json,timesheet_version}')::integer
     or v_approval.withdrawn_at_utc is not null
     or exists(select 1 from private.weekly_source_local_protected_decision_receipts r
               where r.family_id=v_family.id and r.state='PENDING_FREEZE') then
    raise exception 'WEEKLY_PROTECTED_LOCAL_STATE_CHANGED' using errcode='55000';
  end if;
  select target.resulting_lifecycle_state into strict v_target_state
    from public.weekly_exceptional_pay_target_events target
    where target.financial_generation_id=v_generation.id and target.family_id=v_family.id;
  select event.source_proposal_hash into strict v_source_hash
    from public.weekly_exceptional_pay_family_events event
    where event.evidence_approval_id=v_approval.id and event.family_id=v_family.id;
  select private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_RATE_POLICY_V1',
    jsonb_build_object('contract_id',v_family.contract_id,'rates_json',contract.rates_json,
      'policy',private._weekly_source_effective_policy_v1(v_approval.client_id,v_family.contract_id,
        v_approval.protected_work_date),'classification',event.rate_classification_json))
    into strict v_rate_policy_hash
    from public.weekly_exceptional_pay_family_events event
    join public.contracts contract on contract.id=v_family.contract_id
    where event.evidence_approval_id=v_approval.id and event.family_id=v_family.id;
  if v_rate_policy_hash is distinct from v_approval.contract_rate_policy_source_fingerprint then
    raise exception 'WEEKLY_PROTECTED_LOCAL_RATE_POLICY_CHANGED' using errcode='40001';
  end if;
  v_snapshot:=v_generation.complete_next_vector_json#>'{target_snapshot,tsfin_snapshot_json}';
  if jsonb_typeof(v_snapshot) is distinct from 'object'
     or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',
        v_generation.complete_next_vector_json) is distinct from v_generation.complete_next_vector_hash
     or v_snapshot is distinct from v_approval.approved_target_pay_components_json->'tsfin_snapshot_json' then
    raise exception 'WEEKLY_PROTECTED_LOCAL_SNAPSHOT_INVALID' using errcode='55000';
  end if;
  v_snapshot:=v_snapshot||jsonb_build_object('timesheet_id',v_root.timesheet_id::text,
    'timesheet_version',v_root.version,'actual_schedule_json',
    v_generation.complete_next_vector_json#>'{target_snapshot,actual_schedule_json}');
  -- Reconfirm the staged identity proof before either mutable first-approval
  -- TSFIN or the common HEAD writer. Immutable old requests without this new
  -- metadata retain their existing route; they are not silently remapped.
  if v_generation.complete_next_vector_json ? 'protected_component_identity_basis'
     or exists(select 1 from jsonb_array_elements(v_snapshot#>'{invoice_breakdown_json,segments}') r
       where r ? 'weekly_protected_component_identity') then
    if v_generation.complete_next_vector_json#>>'{protected_component_identity_basis,schema_version}'
          is distinct from 'WEEKLY_PROTECTED_COMPONENT_MANIFEST_V1'
       or v_generation.complete_next_vector_json#>>'{protected_component_identity_basis,family_id}'
          is distinct from v_family.id::text
       or v_generation.complete_next_vector_json#>>'{protected_component_identity_basis,root_timesheet_id}'
          is distinct from v_root.timesheet_id::text
       or v_generation.complete_next_vector_json#>>'{protected_component_identity_basis,contract_id}'
          is distinct from v_family.contract_id::text
       or v_generation.complete_next_vector_json#>>'{protected_component_identity_basis,candidate_id}'
          is distinct from v_family.candidate_id::text
       or v_generation.complete_next_vector_json#>>'{protected_component_identity_basis,accepted_schedule_sha256}'
          is distinct from encode(private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_PROTECTED_COMPONENT_ACCEPTED_SCHEDULE_V1',v_snapshot->'actual_schedule_json'),'hex')
       or v_generation.complete_next_vector_json#>>'{protected_component_identity_basis,calculated_segments_sha256}'
          is distinct from encode(private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_PROTECTED_COMPONENT_CALCULATED_SEGMENTS_V1',v_snapshot#>'{invoice_breakdown_json,segments}'),'hex')
       or v_generation.complete_next_vector_json#>>'{protected_component_identity_basis,approved_components_sha256}'
          is distinct from encode(private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_PROTECTED_COMPONENT_APPROVED_COMPONENTS_V1',
            case when v_generation.complete_next_vector_json ? 'prior_effective_inventory'
              then v_generation.complete_next_vector_json#>'{prior_effective_inventory,components}'
              else '[]'::jsonb end),'hex') then
      raise exception 'WEEKLY_PROTECTED_COMPONENT_MANIFEST_UNAVAILABLE' using errcode='55000'; end if;
  end if;
  -- A manually invoked native Local owner cannot bypass the sealed automatic
  -- request's per-component zero-delta proof. This is before PREPARING insert.
  if v_generation.complete_next_vector_json ? 'automatic_reconcile_proof' then
    perform private.weekly_source_automatic_reconcile_delta_assert_v1(v_request.id,v_actor);
  end if;
  select count(*) into v_live_authorisations from public.weekly_source_root_authorisations authority
    where authority.root_timesheet_id=v_root.timesheet_id and authority.withdrawn_at_utc is null;
  -- Exact accepted replay has already returned. Before admitting a NEW
  -- authorised decision, hold the existing owner share lock and require the
  -- same actual NEXT Local writer capabilities as the winning common core.
  -- Otherwise an old freeze could park a decision that cannot later publish.
  -- First Save remains the unauthorised TSFIN path and needs no Bank owner.
  if v_live_authorisations=1 and v_root.authorised_at_server is not null then
    if pg_catalog.to_regclass('private.bpay_next_module_control') is null
       or pg_catalog.to_regprocedure('private.bpay_next_legacy_callback_enabled_v1()') is null then
      raise exception 'WEEKLY_PROTECTED_LOCAL_PUBLICATION_OWNER_NOT_READY' using errcode='55000';
    end if;
    perform private.bpay_next_legacy_callback_enabled_v1();
    if (select active_owner from private.bpay_next_module_control where id=1) is distinct from 'NEXT'
       or pg_catalog.to_regprocedure(
         'private.weekly_source_local_publication_context_v2(uuid,uuid,uuid)') is null
       or pg_catalog.to_regprocedure(
         'private.weekly_source_entitlement_proposal_request_v2(uuid,jsonb,text,uuid,bigint,uuid,uuid,jsonb,text)') is null
       or pg_catalog.to_regprocedure(
         'private.bpay_next_capture_local_source_detail_v1(uuid,uuid,bigint,uuid,uuid,uuid,jsonb)') is null then
      raise exception 'WEEKLY_PROTECTED_LOCAL_PUBLICATION_OWNER_NOT_READY' using errcode='55000';
    end if;
  end if;
  insert into private.weekly_source_local_protected_decision_receipts(
    publication_request_id,generation_id,family_id,root_timesheet_id,actor_user_id,
    request_sha256,idempotency_key,preparing_transaction_id,prior_financial_id,approved_snapshot_json,state
  ) values(v_request.id,v_generation.id,v_family.id,v_root.timesheet_id,v_actor,
    v_hash,v_key,pg_current_xact_id(),v_fin.id,v_snapshot,'PREPARING');
  if v_live_authorisations=0 and v_root.authorised_at_server is null then
    -- 24 section 4.1: mutable unauthorised TSFIN, not a fabricated Authorise.
    if v_fin.authorised_at_utc is not null or v_fin.processing_status<>'PENDING_AUTH'
       or v_snapshot->>'processing_status' is distinct from 'PENDING_AUTH'
       or nullif(v_snapshot->>'authorised_at_utc','') is not null then
      raise exception 'WEEKLY_PROTECTED_LOCAL_AUTHORISATION_CONTRADICTION' using errcode='55000';
    end if;
    v_write:=public.tsfin_write_current_snapshot_single_bounded(v_root.timesheet_id,
      v_root.version,v_snapshot,v_actor,statement_timestamp());
    if coalesce((v_write->>'ok')::boolean,false) is not true then
      raise exception 'WEEKLY_PROTECTED_LOCAL_SNAPSHOT_WRITE_REFUSED' using errcode='55000';
    end if;
    -- V4 permits display of this confirmed decision before first Authorise,
    -- but never admission to Banking. Seal the actual written row, not the
    -- proposed input or an hours-only total. Old receipts are not backfilled.
    select * into strict v_fin from public.timesheets_financials financial
      where financial.id=(v_write->>'timesheet_financials_id')::uuid
        and financial.timesheet_id=v_root.timesheet_id and financial.is_current;
    if v_fin.authorised_at_utc is not null or v_fin.processing_status<>'PENDING_AUTH'
       or v_fin.paid_at_utc is not null or v_fin.locked_by_invoice_id is not null then
      raise exception 'WEEKLY_PROTECTED_LOCAL_SAVED_BASIS_INVALID' using errcode='55000';
    end if;
    update private.weekly_source_local_protected_decision_receipts
      set approved_snapshot_json=v_snapshot||jsonb_build_object('saved_unauthorised_basis',
        jsonb_build_object('schema_version','SAVED_UNAUTHORISED_LOCAL_V1',
          'financial_snapshot_id',v_fin.id,
          'financial_snapshot_sha256',encode(private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_SAVED_UNAUTHORISED_FINANCIAL_V1',to_jsonb(v_fin)),'hex'),
          'detail_sha256',encode(private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_SAVED_UNAUTHORISED_DETAIL_V1',jsonb_build_object(
              'segments',v_fin.invoice_breakdown_json->'segments',
              'actual_schedule',v_fin.actual_schedule_json,
              'additional_units',v_fin.additional_units_json)),'hex'),
          'inventory_sha256',encode(v_generation.complete_next_vector_hash,'hex'),
          'root_version',v_root.version,'family_booking_id',v_root.booking_id))
      where publication_request_id=v_request.id and state='PREPARING'
        and preparing_transaction_id=pg_current_xact_id();
    if not found then
      raise exception 'WEEKLY_PROTECTED_LOCAL_SAVED_BASIS_INVALID' using errcode='55000';
    end if;
    v_result:=jsonb_build_object('authority','UNAUTHORISED_TSFIN',
      'timesheet_financials_id',v_write->'timesheet_financials_id','requires_first_authorisation',true);
  elsif v_live_authorisations=1 and v_root.authorised_at_server is not null then
    -- Already authorised: the only later entitlement writer is the existing
    -- common-head publisher. Never rotate TSFIN, change Drafts or invoke C1.
    -- The real stage advances its own family bound version after sealing the
    -- old entitlement. The factual context proves that exact stage and the
    -- unchanged whole inventory, rather than treating the own increment as
    -- an unrelated intervening financial change.
    v_local_context:=private.weekly_source_local_publication_context_v2(v_request.id,v_generation.id,v_root.timesheet_id);
    if v_local_context is null then
      raise exception 'WEEKLY_PROTECTED_LOCAL_SOURCE_QUALIFICATION_UNAVAILABLE' using errcode='55000'; end if;
    if v_generation.complete_next_vector_json ? 'automatic_reconcile_proof' then
      -- Exactly the producer used by delta_assert; no separately guessed vector.
      v_automatic_components:=private.weekly_source_staged_entitlement_components_v1(v_request.id,v_actor);
      v_components:=v_automatic_components->'components';
      v_expenses:=v_automatic_components->'expenses';
    else
    select coalesce(jsonb_agg(jsonb_build_object('work_event_id',expense.work_event_id,
      'source_observation_kind',expense.source_observation_kind,
      'candidate_reimbursement_ex_vat',expense.candidate_reimbursement_ex_vat,
      'client_charge_ex_vat',expense.client_charge_ex_vat) order by expense.work_event_id),'[]'::jsonb)
      into v_expenses from (
        select authority.*,row_number() over(partition by authority.work_event_id
          order by cycle.finalisation_week_ending desc,revision.finalised_at_utc desc,
            authority.generation desc,authority.id desc) event_rank
        from public.weekly_expense_authority_generations authority
        join public.weekly_source_final_revisions revision on revision.id=authority.final_revision_id and revision.state='CURRENT'
        join public.weekly_source_cycles cycle on cycle.id=revision.source_cycle_id
        join public.weekly_source_cycles action_cycle on action_cycle.id=v_approval.source_cycle_id
        where authority.contract_id=v_family.contract_id and authority.state='CURRENT'
          and cycle.source_group_id=action_cycle.source_group_id
          and exists(select 1 from public.weekly_source_row_timesheet_lineages lineage
            where lineage.work_event_id=authority.work_event_id and lineage.contract_id=authority.contract_id
              and lineage.timesheet_id=any(private.weekly_source_invoice_family_timesheet_ids_v1(v_root.timesheet_id)))
      ) expense where expense.event_rank=1 and expense.source_expense_pence>0;
    v_components:=private.weekly_source_entitlement_components_v1(
      v_snapshot#>'{invoice_breakdown_json,segments}',v_expenses);
    -- Reuse the existing pure approved-additional mapper on the sealed
    -- calculator snapshot. It validates exact saved units/rates/totals and
    -- booking-family identity; it does not read or reprice live financial data.
    v_components:=private.weekly_source_initial_additional_components_v2(v_components,
      v_snapshot->'additional_units_json',
      (v_snapshot->>'additional_pay_ex_vat')::numeric,
      (v_snapshot->>'additional_charge_ex_vat')::numeric,v_root.booking_id);
    end if;
    -- Source expenses must be the same approved observations and money, not
    -- a newer expense silently composed into an older protected decision.
    if (select coalesce(sum((item.value->>'pay_ex_vat')::numeric)
        filter(where not (item.value->>'exclude_from_pay')::boolean),0)
        from jsonb_array_elements(v_components) item(value)) is distinct from v_approval.approved_target_gross
       or (select coalesce(jsonb_agg(jsonb_build_object('code',upper('SOURCE_SUPPLIED:'||(item.value->>'work_event_id')),
          'pay',(item.value->>'candidate_reimbursement_ex_vat')::numeric,
          'charge',(item.value->>'client_charge_ex_vat')::numeric) order by item.value->>'work_event_id'),'[]'::jsonb)
          from jsonb_array_elements(v_expenses) item(value)) is distinct from
          (select coalesce(jsonb_agg(jsonb_build_object('code',upper(component.expense_code),
            'pay',component.pay_ex_vat,'charge',component.charge_ex_vat)
            order by component.expense_code),'[]'::jsonb)
            from public.weekly_exceptional_c1_component_records component
            where component.publication_request_id=v_request.id and component.component_kind='EXPENSE') then
      raise exception 'WEEKLY_PROTECTED_LOCAL_COMPLETE_ENTITLEMENT_CHANGED' using errcode='40001';
    end if;
    v_local_origin:=private.weekly_source_local_origin_canonical_v2(jsonb_build_object(
      'origin_kind','PROTECTED_LOCAL_DECISION_V1','publication_request_id',v_request.id,
      'generation_id',v_generation.id,'request_sha256',encode(v_request.request_sha256,'hex'),
      'source_qualification_digest',v_local_context->'source_qualification_digest',
      'policy_fingerprint',v_local_context->'policy_fingerprint','before_origin',v_local_context->'before_origin',
      'before_inventory_digest',v_local_context->'before_inventory_digest'));
    v_bundle_id:=pg_catalog.gen_random_uuid();
    update private.weekly_source_local_protected_decision_receipts set approved_snapshot_json=v_snapshot||jsonb_build_object(
      'common_decision_bundle_id',v_bundle_id,
      'local_source_qualification',v_local_context->'qualification','local_publication_origin',v_local_origin,
      'common_components_digest',encode(private.weekly_source_publication_request_digest_v1(
        (select coalesce(jsonb_agg(private.weekly_source_publication_component_canonical_v1(item.value,'protected.component')
          order by item.ordinality),'[]'::jsonb) from jsonb_array_elements(v_components) with ordinality item(value,ordinality))),'hex')),
      common_decision_bundle_id=v_bundle_id,common_bundle_revision=1,
      publication_origin_kind='PROTECTED_LOCAL_DECISION_V1',
      publication_origin_digest=private.weekly_source_publication_request_digest_v1(v_local_origin),
      source_qualification_digest=decode(v_local_context->>'source_qualification_digest','hex')
      where publication_request_id=v_request.id and state='PREPARING' and preparing_transaction_id=pg_current_xact_id();
    if not found then raise exception 'WEEKLY_PROTECTED_LOCAL_ORIGIN_SEAL_REFUSED' using errcode='55000'; end if;
    v_head_request:=private.weekly_source_entitlement_proposal_request_v2(v_root.timesheet_id,
      v_local_origin,'PROTECTED',v_bundle_id,1,pg_catalog.gen_random_uuid(),
      pg_catalog.gen_random_uuid(),v_components);
    v_proposal:=private.weekly_source_entitlement_proposal_record_v1(v_head_request,v_family.agency_id,
      v_family.contract_id,v_family.week_ending_date,v_actor);
    if coalesce((v_proposal->>'ok')::boolean,false) is not true then
      raise exception 'WEEKLY_PROTECTED_LOCAL_PROPOSAL_REFUSED' using errcode='55000';
    end if;
    v_write:=private.weekly_source_entitlement_publish_immediate_v1(v_head_request);
    if coalesce((v_write->>'ok')::boolean,false) is not true then
      raise exception '%',coalesce(v_write->>'code','WEEKLY_PROTECTED_LOCAL_HEAD_REFUSED') using errcode='55000';
    end if;
    v_pending:=coalesce((v_write->>'published')::boolean,false) is not true;
    if v_pending and v_write->>'code'<>'WEEKLY_SOURCE_PUBLICATION_DEFERRED_PENDING_FREEZE' then
      raise exception 'WEEKLY_PROTECTED_LOCAL_HEAD_RESULT_INVALID' using errcode='55000';
    end if;
    v_result:=jsonb_build_object('authority','COMMON_ENTITLEMENT_HEAD',
      'decision_bundle_id',v_bundle_id,'publication',v_write,'requires_first_authorisation',false);
  else
    raise exception 'WEEKLY_PROTECTED_LOCAL_AUTHORISATION_CONTRADICTION' using errcode='55000';
  end if;

  v_result:=v_result||jsonb_build_object('ok',true,'outcome',case when v_pending
    then 'SAVED_PENDING_FREEZE' else 'PUBLISHED' end,'idempotent_replay',false,
    'family_id',v_family.id,'generation_id',v_generation.id,'publication_request_id',v_request.id,
    'state',case when v_pending then 'PENDING' else 'LIVE' end,
    'family_bound_version',v_family.bound_version+1);
  v_result_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_LOCAL_RESULT_V1',v_result);
  if not v_pending then
    if v_family.current_generation_id is not null then
      update public.weekly_exceptional_pay_generations set lifecycle_state='SUPERSEDED',
        superseded_by_generation_id=v_generation.id,superseded_at_utc=statement_timestamp()
        where id=v_family.current_generation_id and lifecycle_state='PUBLISHED';
      if not found then raise exception 'WEEKLY_PROTECTED_LOCAL_PRIOR_GENERATION_INVALID' using errcode='55000'; end if;
    end if;
    update public.weekly_exceptional_pay_generations set lifecycle_state='PUBLISHED',
      published_at_utc=statement_timestamp(),result_hash=v_result_hash where id=v_generation.id;
    update public.weekly_exceptional_pay_target_families set current_generation_id=v_generation.id,
      current_generation_number=v_generation.generation_number,
      current_complete_target_vector_hash=v_generation.complete_next_vector_hash,
      current_source_proposal_hash=v_source_hash,current_lifecycle_state=v_target_state,
      current_component_count=v_request.expected_component_count,c1_publication_state='NONE',
      bound_version=bound_version+1 where id=v_family.id;
  else
    -- Previous effective family/head remains current while the existing frozen
    -- bundle owner holds the newly approved decision. No pretend live receipt.
    update public.weekly_exceptional_pay_target_families set c1_publication_state='NONE',
      bound_version=bound_version+1 where id=v_family.id;
  end if;
  update public.weekly_exceptional_c1_publication_requests set state='RETIRED',
    typed_result_json=v_result,completed_at_utc=statement_timestamp() where id=v_request.id;
  update public.weekly_exceptional_orchestration_runs set state='COMPLETE',
    after_state_fingerprint=v_result_hash,completed_at_utc=statement_timestamp() where id=v_run.id;
  update private.weekly_source_local_protected_decision_receipts set state=case when v_pending
    then 'PENDING_FREEZE' else 'COMPLETE' end,result_json=v_result,completed_at_utc=statement_timestamp()
    where publication_request_id=v_request.id;
  -- Finish the existing manual pay query atomically with its approved decision.
  -- The UI needs no second query command: only this accepted publication can
  -- clear the hold, using its exact retained approval and generation evidence.
  select review.id into v_manual_review_id from private.weekly_source_manual_reviews review
    join public.weekly_source_cycles cycle on cycle.id=v_approval.source_cycle_id
    where review.source_group_id=cycle.source_group_id
      and review.work_event_id=v_approval.work_event_id and review.state='OPEN'
      and review.contract_id=v_family.contract_id and review.candidate_id=v_family.candidate_id;
  insert into public.weekly_exceptional_payment_events(family_id,approval_id,event_kind,
    lifecycle_view,bounded_payload_json,idempotency_key) values(v_family.id,v_approval.id,
    'PROTECTED_STATE_OBSERVED',case when v_pending then 'PENDING' else 'LIVE' end,v_result,v_key||':payment-event');
  insert into public.weekly_exceptional_orchestration_steps(orchestration_run_id,sequence,
    step_kind,idempotency_key,allowlisted_owner_name,allowlisted_owner_signature,bounded_request_hash,
    before_state_fingerprint,bounded_owner_response_json,owner_response_hash,after_state_fingerprint,outcome,completed_at_utc)
    select v_run.id,coalesce(max(step.sequence),0)+1,'COMPLETE_LOCAL_PROTECTED_DECISION',v_key,
      'CloudTMS.weekly_exceptional_pay_complete_local_v1','jsonb',v_hash,v_run.before_state_fingerprint,
      v_result,v_result_hash,v_result_hash,case when v_pending then 'PENDING' else 'COMPLETE' end,statement_timestamp()
    from public.weekly_exceptional_orchestration_steps step where step.orchestration_run_id=v_run.id;
  -- Finish the actual completion evidence before any query resolution or
  -- accepted-status read, in this same outer transaction; a refusal rolls back
  -- the decision, publication, completion step and query together.
  if v_manual_review_id is not null and v_run.request_kind in ('APPROVE','AMEND') then
    perform public.weekly_source_manual_review_resolve_v1(jsonb_build_object('actor_user_id',v_actor,
      'review_id',v_manual_review_id,'resolution_kind','PROTECTED_PAY',
      'command_id',v_request.id,'accepted_approval_id',v_approval.id,
      'accepted_generation_id',v_generation.id));
  elsif v_manual_review_id is not null and v_run.request_kind in ('WITHDRAW','RECONCILE') then
    perform public.weekly_source_manual_review_resolve_v1(jsonb_build_object('actor_user_id',v_actor,
      'review_id',v_manual_review_id,'resolution_kind','OFFICE_ACCEPTED_SOURCE',
      'command_id',v_request.id,'accepted_approval_id',v_approval.id,
      'accepted_generation_id',v_generation.id));
  end if;
  -- Accepted pending approval is not publication. The existing release
  -- trigger retires its contacts only after the deferred receipt is proved.
  if not v_pending then
    perform private.weekly_source_protected_contact_retire_v1(v_family.id,v_approval.work_event_id);
  end if;
  return v_result;
exception when no_data_found or too_many_rows then
  raise exception 'WEEKLY_PROTECTED_LOCAL_COMPLETE_SCOPE_INVALID' using errcode='55000';
end;
$function$;
alter function public.weekly_exceptional_pay_complete_local_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_exceptional_pay_complete_local_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_exceptional_pay_complete_local_v1(jsonb) to service_role;

-- Root union: complete F1/F8/PP/Report/Money registry; identical final contracts.
-- Root reasserts the FINAL combined ACL gate after all report/PP/F8 owners.



create or replace function private._weekly_source_acl_table_contract_v1()
returns table(table_name text, record_class text)
language sql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
  values
    ('office_action_notifications', 'IMMUTABLE_FACTS_WITH_LIFECYCLE'),
    ('weekly_candidate_app_mutation_receipts', 'IMMUTABLE_APPEND_ONLY'),
    ('weekly_candidate_cohorts', 'STATEFUL_SERVER_OWNED'),
    ('weekly_candidate_message_notifications', 'IMMUTABLE_FACTS_WITH_LIFECYCLE'),
    ('weekly_candidate_outreach_generations', 'STATEFUL_SERVER_OWNED'),
    ('weekly_candidate_outreach_memberships', 'STATEFUL_SERVER_OWNED'),
    ('weekly_candidate_response_draft_items', 'STATEFUL_SERVER_OWNED'),
    ('weekly_candidate_response_drafts', 'STATEFUL_SERVER_OWNED'),
    ('weekly_completed_pack_copy_events', 'IMMUTABLE_FACTS_WITH_LIFECYCLE'),
    ('weekly_discrepancy_events', 'IMMUTABLE_APPEND_ONLY'),
    ('weekly_discrepancy_incidents', 'STATEFUL_SERVER_OWNED'),
    ('weekly_exceptional_c1_component_records', 'IMMUTABLE_APPEND_ONLY'),
    ('weekly_exceptional_c1_publication_checkpoints', 'IMMUTABLE_APPEND_ONLY'),
    ('weekly_exceptional_c1_publication_requests', 'STATEFUL_SERVER_OWNED'),
    ('weekly_exceptional_c1_source_parts', 'IMMUTABLE_APPEND_ONLY'),
    ('weekly_exceptional_c1_source_records', 'IMMUTABLE_APPEND_ONLY'),
    ('weekly_exceptional_c1_unknown_outcomes', 'IMMUTABLE_FACTS_WITH_LIFECYCLE'),
    ('weekly_exceptional_orchestration_runs', 'STATEFUL_SERVER_OWNED'),
    ('weekly_exceptional_orchestration_steps', 'STATEFUL_SERVER_OWNED'),
    ('weekly_exceptional_pay_family_events', 'IMMUTABLE_APPEND_ONLY'),
