-- CONTACT_PREPARER_UNIT 128 repeatable supabase/repeatable/14102026_0410_healthroster_protected_source_prerequisites_v1.sql SHA256 62f1a00cf32896e8b7c2511934d373e5cbbbad6321852e7bd3d7ea6b2512db1d
-- Complete reviewed original qualification prerequisites.
-- Final current-native0420, Money0430, Report and canonical registry/seal gates remain required.

-- Complete original prerequisite source stage only. No calls or activation.
-- Root final five current-native owners, Money47, Report and final registry/ACL must follow.
-- Complete isolated source proposal. Root review and native proofs pending.
-- Root-review owner-private Source census. It never reads protection-stage
-- tables or mutable Timesheet/TSFIN lifecycle, and never makes a pay decision.
create or replace function private.weekly_source_bulk_source_facts_v1(p_cycle_id uuid,p_client_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  p public.weekly_source_projection_publications%rowtype; u public.weekly_source_uploads%rowtype;
  clients uuid[]; facts jsonb; actual_client uuid;
begin
  if p_cycle_id is null or p_client_ids is null or array_position(p_client_ids,null::uuid) is not null then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='22023'; end if;
  select coalesce(array_agg(distinct value order by value),'{}'::uuid[]) into clients from unnest(p_client_ids) value;
  if cardinality(clients)>100 then raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_SCOPE_TOO_LARGE' using errcode='54000'; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  select * into strict p from public.weekly_source_projection_publications where id=c.current_projection_publication_id
    and source_cycle_id=c.id and state='CURRENT' and authority_scope_kind='CYCLE' and correction_session_id is null and report_scope_id is null;
  select * into strict u from public.weekly_source_uploads where id=c.current_complete_upload_id and id=p.upload_id
    and source_cycle_id=c.id and state='CURRENT' and report_scope_id is null;
  perform private.weekly_source_query_current_publication_v1(c.id,p.id);
  actual_client:=private.weekly_source_checking_client_scope_v1(p.id);
  if exists(select 1 from unnest(clients) client where (actual_client is not null and actual_client<>client)
    or not exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=g.id and member.client_id=client
      and daterange(member.valid_from,coalesce(member.valid_to,'infinity'::date),'[]')
        && daterange(coalesce(u.confirmed_coverage_start_local_date,c.finalisation_week_ending-6),
          coalesce(u.confirmed_coverage_end_local_date,c.finalisation_week_ending),'[]'))) then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_CLIENT_SCOPE_CHANGED' using errcode='40001'; end if;
  -- CTE scope comes from saved Source parents. Incident IDs contribute stable
  -- work-event scope irrespective of OPEN/CLOSED; their mutable rows do not.
  with report_scopes as materialized (
    select scope.* from public.weekly_source_report_scopes scope where scope.source_group_id=g.id
      and scope.client_id=any(clients) and scope.self_bill_report_id is not null
  ), report_bindings as materialized (
    select binding.* from public.weekly_source_self_bill_report_line_bindings binding
      join public.weekly_source_self_bill_reports report on report.id=binding.self_bill_report_id
      where report.source_group_id=g.id and report.client_id=any(clients) and binding.state='CURRENT'
  ), publications as materialized (
    select publication.* from public.weekly_source_projection_publications publication where publication.id=p.id
      or publication.id in(select current_projection_publication_id from report_scopes)
      or publication.id in(select export_projection_publication_id from report_bindings)
  ), uploads as materialized (
    select upload.* from public.weekly_source_uploads upload where upload.id=u.id
      or upload.id in(select upload_id from publications)
  ), source_rows as materialized (
    select row_data.* from public.weekly_source_upload_rows row_data where row_data.upload_id in(select id from uploads)
  ), resolutions as materialized (
    select resolution.* from public.weekly_source_row_resolutions resolution
      join source_rows row_data on row_data.id=resolution.upload_row_id
      join publications publication on publication.upload_id=row_data.upload_id
        and resolution.generation=coalesce(publication.projection_generation,publication.authority_scope_version)
      where resolution.client_id=any(clients)
      union select resolution.* from public.weekly_source_row_resolutions resolution
        join report_bindings binding on binding.bound_row_resolution_id=resolution.id
  ), events as materialized (
    select event.* from public.weekly_work_events event where event.first_source_group_id=g.id and event.client_id=any(clients)
      and (event.id in(select work_event_id from resolutions) or event.id in(select work_event_id from report_bindings)
        or exists(select 1 from public.weekly_discrepancy_incidents incident where incident.source_cycle_id=c.id
          and incident.work_event_id=event.id and incident.client_id=event.client_id))
  ), revisions as materialized (
    select revision.* from public.weekly_source_final_revisions revision
      join public.weekly_source_cycles source_cycle on source_cycle.id=revision.source_cycle_id and source_cycle.source_group_id=g.id
      where revision.state in ('CURRENT','PREPARED','SUPERSEDED') and (
        revision.source_cycle_id=c.id or revision.report_scope_id in(select id from report_scopes)
        or exists(select 1 from public.weekly_source_final_snapshot_lines snapshot where snapshot.final_revision_id=revision.id
          and snapshot.work_event_id in(select id from events)))
  ), snapshots as materialized (
    select snapshot.* from public.weekly_source_final_snapshot_lines snapshot where snapshot.final_revision_id in(select id from revisions)
      and snapshot.client_id=any(clients)
  ), lineages as materialized (
    select lineage.* from public.weekly_source_row_timesheet_lineages lineage where lineage.client_id=any(clients)
      and (lineage.row_resolution_id in(select id from resolutions) or lineage.work_event_id in(select id from events))
  ), pay_receipts as materialized (
    select receipt.* from public.weekly_source_ordinary_pay_projection_receipts receipt where receipt.client_id=any(clients)
      and receipt.final_revision_id in(select id from revisions)
  ), financial_identities as materialized (
    -- The Source receipt is immutable and already pins all published economics
    -- and root-before/after/service hashes. Protection may replace currentness
    -- on the same native family; the Source financial identity stays exact.
    select financial.id,financial.timesheet_id,financial.client_id,financial.candidate_id,financial.contract_id
      from public.timesheets_financials financial where financial.id in(select published_timesheet_financial_id from pay_receipts)
  ), root_identities as materialized (
    select root.timesheet_id,root.client_id,root.candidate_id,root.contract_id,root.family_booking_id
      from public.timesheets root where root.timesheet_id in(select root_timesheet_id from pay_receipts)
  ), cycles as materialized (
    select cycle.* from public.weekly_source_cycles cycle where cycle.id=c.id or cycle.id in(select source_cycle_id from publications)
      or cycle.id in(select source_cycle_id from revisions)
  ), contracts as materialized (
    select contract.* from public.contracts contract where contract.client_id=any(clients)
      and (daterange(contract.start_date,contract.end_date,'[]') && daterange(
        coalesce(u.confirmed_coverage_start_local_date,c.finalisation_week_ending-6),
        coalesce(u.confirmed_coverage_end_local_date,c.finalisation_week_ending),'[]')
        or contract.id in(select contract_id from resolutions) or contract.id in(select contract_id from snapshots)
        or exists(select 1 from public.weekly_issue_comparison_revisions comparison
          join public.weekly_discrepancy_incidents incident on incident.current_comparison_revision_id=comparison.id
          where incident.source_cycle_id=c.id and incident.client_id=contract.client_id and comparison.contract_id=contract.id))
  ), policy_dates as materialized (
    select client client_id,null::uuid contract_id,c.finalisation_week_ending work_date from unnest(clients) client
    union select client_id,contract_id,work_date from snapshots
    union select resolution.client_id,resolution.contract_id,row_data.work_date from resolutions resolution
      join source_rows row_data on row_data.id=resolution.upload_row_id
    union select client_id,null::uuid,work_date from events
    union select contract.client_id,contract.id,greatest(contract.start_date,
      coalesce(u.confirmed_coverage_start_local_date,c.finalisation_week_ending-6)) from contracts contract
  ), resolved_policies as materialized (
    select client_id,contract_id,work_date,private._weekly_source_effective_policy_v1(client_id,contract_id,work_date) policy
      from policy_dates
  )
  select jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_SOURCE_FACTS_V1','source_cycle_id',c.id,
    'client_ids',to_jsonb(clients),'group',to_jsonb(g),
    'cycles',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from cycles x),'[]'::jsonb),
    'clients',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.clients x where x.id=any(clients)),'[]'::jsonb),
    'memberships',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.valid_from,x.id)
      from public.weekly_source_group_clients x where x.source_group_id=g.id and x.client_id=any(clients)),'[]'::jsonb),
    'client_policies',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.effective_from,x.id)
      from public.weekly_source_client_policies x where x.source_group_id=g.id and x.client_id=any(clients)),'[]'::jsonb),
    'client_settings',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.id) from public.client_settings x where x.client_id=any(clients)),'[]'::jsonb),
    'contracts',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from contracts x),'[]'::jsonb),
    'contract_policies',coalesce((select jsonb_agg(to_jsonb(x) order by x.contract_id,x.effective_from,x.id)
      from public.weekly_source_contract_policies x where x.contract_id in(select id from contracts)),'[]'::jsonb),
    'global_settings',coalesce((select jsonb_agg(to_jsonb(x)) from public.weekly_source_global_settings x where x.singleton),'[]'::jsonb),
    'resolved_policies',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.contract_id nulls first,x.work_date) from resolved_policies x),'[]'::jsonb),
    'assignments',coalesce((select jsonb_agg(to_jsonb(x) order by x.effective_from_week_ending,x.id)
      from public.weekly_source_group_rule_assignments x where x.source_group_id=g.id),'[]'::jsonb),
    'rule_versions',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.weekly_source_rule_set_versions x
      where x.id in(select rule_set_version_id from public.weekly_source_group_rule_assignments where source_group_id=g.id)
        or x.id in(select rule_set_version_id from revisions)),'[]'::jsonb),
    'effective_rules',coalesce((select jsonb_agg(jsonb_build_object('client_id',client,
      'effective_rule_set',private.weekly_source_effective_rule_set_v1(client,c.id)) order by client) from unnest(clients) client),'[]'::jsonb),
    'profiles',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.weekly_source_format_profiles x
      where x.id in(select source_format_profile_id from uploads)),'[]'::jsonb),
    'uploads',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from uploads x),'[]'::jsonb),
    'publications',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from publications x),'[]'::jsonb),
    'rows',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_id,x.source_row_ordinal,x.id) from source_rows x),'[]'::jsonb),
    'resolutions',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_row_id,x.generation,x.id) from resolutions x),'[]'::jsonb),
    'economics',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id) from public.weekly_source_row_economic_snapshots x
      where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'expense_policy_snapshots',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id)
      from public.weekly_source_row_expense_policy_snapshots x where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'expense_authorities',coalesce((select jsonb_agg(to_jsonb(x) order by x.work_event_id,x.generation,x.id)
      from public.weekly_expense_authority_generations x where x.final_revision_id in(select id from revisions)
        and x.work_event_id in(select id from events)),'[]'::jsonb),
    'expense_cell_evidence',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_id,x.source_row_ordinal,x.id)
      from public.weekly_source_expense_cell_evidence x where x.upload_id in(select id from uploads)),'[]'::jsonb),
    'charge_checks',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id)
      from public.weekly_source_charge_checks x where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'charge_acceptances',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id)
      from public.weekly_source_charge_acceptances x where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'invoice_hold_releases',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_row_id,x.hold_kind,x.id)
      from public.weekly_source_invoice_hold_releases x where x.upload_row_id in(select id from source_rows)),'[]'::jsonb),
    'transitions',coalesce((select jsonb_agg(to_jsonb(x) order by x.final_revision_id,x.work_event_id,x.id)
      from public.weekly_source_state_transitions x where x.final_revision_id in(select id from revisions)
        and x.work_event_id in(select id from events)),'[]'::jsonb),
    'report_scopes',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from report_scopes x),'[]'::jsonb),
    'reports',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.weekly_source_self_bill_reports x
      where x.source_group_id=g.id and x.client_id=any(clients)),'[]'::jsonb),
    'report_bindings',coalesce((select jsonb_agg(to_jsonb(x) order by x.report_row_id,x.id) from report_bindings x),'[]'::jsonb),
    'events',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from events x),'[]'::jsonb),
    'revisions',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from revisions x),'[]'::jsonb),
    'snapshots',coalesce((select jsonb_agg(to_jsonb(x) order by x.final_revision_id,x.work_event_id,x.id) from snapshots x),'[]'::jsonb),
    'lineages',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from lineages x),'[]'::jsonb),
    'pay_receipts',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from pay_receipts x),'[]'::jsonb),
    'financial_identities',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from financial_identities x),'[]'::jsonb),
    'root_identities',coalesce((select jsonb_agg(to_jsonb(x) order by x.timesheet_id) from root_identities x),'[]'::jsonb)) into facts;
  if (select count(*) from public.clients where id=any(clients))<>cardinality(clients)
    or exists(select 1 from jsonb_array_elements(facts->'pay_receipts') receipt
      where receipt->>'published_timesheet_financial_id' is not null and not exists(
        select 1 from jsonb_array_elements(facts->'financial_identities') financial
          where financial->>'id'=receipt->>'published_timesheet_financial_id'
            and financial->>'timesheet_id'=receipt->>'root_timesheet_id' and financial->>'client_id'=receipt->>'client_id'
            and exists(select 1 from jsonb_array_elements(facts->'root_identities') root
              join jsonb_array_elements(facts->'contracts') contract on contract->>'id'=financial->>'contract_id'
              where root->>'timesheet_id'=financial->>'timesheet_id'
                and root->>'candidate_id'=financial->>'candidate_id' and root->>'contract_id'=financial->>'contract_id'
                and (root->>'client_id' is null or root->>'client_id'=financial->>'client_id')
                and contract->>'client_id'=financial->>'client_id' and contract->>'candidate_id'=financial->>'candidate_id'))) then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_FINANCIAL_IDENTITY_INVALID' using errcode='55000'; end if;
  if octet_length(convert_to(facts::text,'UTF8'))>8388608 then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_SCOPE_TOO_LARGE' using errcode='54000'; end if;
  return facts;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_SCOPE_UNAVAILABLE' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_bulk_source_cas_v1(p_cycle_id uuid,p_client_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare facts jsonb;
begin
  facts:=private.weekly_source_bulk_source_facts_v1(p_cycle_id,p_client_ids);
  return jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_SOURCE_CAS_V1','source_cycle_id',p_cycle_id,
    'client_ids',facts->'client_ids','source_cas_sha256',encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_BULK_SOURCE_CAS_V1',facts),'hex'));
end;
$function$;


-- Complete isolated source proposal. Root review and native proofs pending.
-- All new capability evidence lives in the existing release/assignment receipt.
-- Qualification is installed by root's protected managed-release evidence
-- workflow after actual native prerequisite journeys, never by a browser flag.
create or replace function private.weekly_source_protected_capability_release_evidence_v1(
  p_group_id uuid,p_from date,p_to date,p_expected_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare g public.weekly_source_groups%rowtype; r private.cloudtms_database_releases%rowtype;
  q jsonb; entry jsonb; count_rows integer; needed text[]; cap text;
begin
  select * into strict g from public.weekly_source_groups where id=p_group_id and active and source_family='ROSTER';
  select * into r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if not found or r.status<>'VERIFIED' or r.completed_at_utc is null
    or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or g.environment<>'TEST' or current_database()<>'cloudtms_test_clone'
    or not exists(select 1 from private.cloudtms_database_identity where singleton and environment=g.environment)
    or r.evidence_json#>>'{managed_release,environment}' is distinct from g.environment
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or jsonb_typeof(r.evidence_json->'weekly_source_protected_capability_qualifications') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  select count(*),jsonb_agg(value)->0 into count_rows,q
    from jsonb_array_elements(r.evidence_json->'weekly_source_protected_capability_qualifications') value
    where value->>'source_group_id'=g.id::text and value->>'effective_from_week_ending'=p_from::text
      and value->>'effective_to_week_ending' is not distinct from p_to::text;
  if count_rows<>1 or not private.weekly_exceptional_json_keys_exact_v1(q,array[
      'schema_version','release_id','git_commit','contract_sha256','agency_id','environment','source_group_id',
      'effective_from_week_ending','effective_to_week_ending','capabilities','gate_receipts','qualification_sha256'])
    or not(q ?& array['schema_version','release_id','git_commit','contract_sha256','agency_id','environment','source_group_id',
      'effective_from_week_ending','effective_to_week_ending','capabilities','gate_receipts','qualification_sha256'])
    or q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1'
    or q->>'release_id' is distinct from r.release_id or q->>'git_commit' is distinct from r.git_commit
    or q->>'contract_sha256' is distinct from r.installed_contract_sha256
    or q->>'agency_id' is distinct from g.agency_id::text or q->>'environment' is distinct from g.environment
    or coalesce(q->>'qualification_sha256','') !~ '^[0-9a-f]{64}$'
    or q->>'qualification_sha256' is distinct from p_expected_sha256
    or encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1',q-'qualification_sha256'),'hex')
      is distinct from q->>'qualification_sha256'
    or jsonb_typeof(q->'capabilities') is distinct from 'array' or jsonb_array_length(q->'capabilities') not between 1 and 2
    or exists(select 1 from jsonb_array_elements(q->'capabilities') value where jsonb_typeof(value)<>'string'
      or value#>>'{}' not in ('BULK_SIGNED','AUTOMATIC_RECONCILE'))
    or (select count(distinct value) from jsonb_array_elements(q->'capabilities') value)<>jsonb_array_length(q->'capabilities')
    or (q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb and not(q->'capabilities' @> '["BULK_SIGNED"]'::jsonb))
    or jsonb_typeof(q->'gate_receipts') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  needed:=array['SOURCE_CAS_NATIVE','NATIVE_PROTECTION','SECURITY','LEGACY_PAY','NEXT_PAY','CLIENT_API','DOCUMENT','OWN_STAGE_CAS','SOURCE_ROUTING'];
  if q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb then needed:=array_append(needed,'AUTOMATIC_COMPONENT_DELTA'); end if;
  if jsonb_array_length(q->'gate_receipts')<>cardinality(needed)
    or (select count(distinct value->>'gate') from jsonb_array_elements(q->'gate_receipts') value)<>cardinality(needed) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  for entry in select value from jsonb_array_elements(q->'gate_receipts') value loop
    if not private.weekly_exceptional_json_keys_exact_v1(entry,array['gate','status','execution','database','receipt_id','receipt_sha256',
        'source_commit','contract_sha256','source_group_id','agency_id','environment'])
      or not(entry ?& array['gate','status','execution','database','receipt_id','receipt_sha256',
        'source_commit','contract_sha256','source_group_id','agency_id','environment'])
      or not(coalesce(entry->>'gate','')=any(needed)) or entry->>'status' is distinct from 'PASS'
      or entry->>'execution' is distinct from 'AGENCY_TEST_NATIVE' or entry->>'database' is distinct from current_database()
      or entry->>'source_commit' is distinct from r.git_commit or entry->>'contract_sha256' is distinct from r.installed_contract_sha256
      or entry->>'source_group_id' is distinct from g.id::text or entry->>'agency_id' is distinct from g.agency_id::text
      or entry->>'environment' is distinct from g.environment or nullif(btrim(entry->>'receipt_id'),'') is null
      or char_length(entry->>'receipt_id')>256 or coalesce(entry->>'receipt_sha256','') !~ '^[0-9a-f]{64}$' then
      raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  end loop;
  return q;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000';
end;
$function$;

-- Read-only exact pre-existing policy admission. It does not legalise or rewrite
-- any Client setting, signed preset, Source amount/pricing rule or NHSP route.
create or replace function private.weekly_source_protected_source_activation_scope_v1(p_group_id uuid,p_from date,p_to date)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare g public.weekly_source_groups%rowtype; v_boundary record; policy jsonb; count_rows integer:=0;
begin
  select * into strict g from public.weekly_source_groups where id=p_group_id and active and source_family='ROSTER';
  for v_boundary in
    with members as materialized(select * from public.weekly_source_group_clients where source_group_id=g.id
      and daterange(valid_from,coalesce(valid_to,'infinity'::date),'[]') && daterange(p_from-6,coalesce(p_to,'infinity'::date),'[]')),
    dates as (
      select client_id,greatest(valid_from,p_from-6) scope_date from members
      union select member.client_id,cp.effective_from from members member join public.weekly_source_client_policies cp
        on cp.client_id=member.client_id and cp.source_group_id=g.id where cp.effective_from>=p_from-6
          and cp.effective_from<=coalesce(p_to,'infinity'::date) and cp.effective_from between member.valid_from and coalesce(member.valid_to,'infinity'::date)
      union select member.client_id,cp.effective_to+1 from members member join public.weekly_source_client_policies cp
        on cp.client_id=member.client_id and cp.source_group_id=g.id where cp.effective_to is not null and cp.effective_to+1>=p_from-6
          and cp.effective_to+1<=coalesce(p_to,'infinity'::date) and cp.effective_to+1 between member.valid_from and coalesce(member.valid_to,'infinity'::date)
    ) select dates.client_id,null::uuid contract_id,dates.scope_date from dates
    union select contract.client_id,contract.id,dates.scope_date
      from public.contracts contract join dates on dates.client_id=contract.client_id
      where dates.scope_date between contract.start_date and contract.end_date
    union select contract.client_id,contract.id,greatest(contract.start_date,member.valid_from,p_from-6)
      from public.contracts contract join members member on member.client_id=contract.client_id
      where daterange(contract.start_date,contract.end_date,'[]') && daterange(greatest(member.valid_from,p_from-6),
        least(coalesce(member.valid_to,'infinity'::date),coalesce(p_to,'infinity'::date)),'[]')
    union select contract.client_id,contract.id,boundary.scope_date
      from public.contracts contract join members member on member.client_id=contract.client_id
      join public.weekly_source_contract_policies cp on cp.contract_id=contract.id
      cross join lateral (values(cp.effective_from),(cp.effective_to+1)) boundary(scope_date)
      where boundary.scope_date between greatest(contract.start_date,member.valid_from,p_from-6)
        and least(contract.end_date,coalesce(member.valid_to,'infinity'::date),coalesce(p_to,'infinity'::date))
    order by client_id,contract_id nulls first,scope_date
  loop
    count_rows:=count_rows+1;
    policy:=private._weekly_source_effective_policy_v1(v_boundary.client_id,v_boundary.contract_id,v_boundary.scope_date);
    if policy->>'source_group_id' is distinct from g.id::text or private.weekly_source_is_import_authoritative_v1(
      v_boundary.client_id,v_boundary.contract_id,v_boundary.scope_date) is distinct from true then
      raise exception 'WEEKLY_SOURCE_PROTECTED_SOURCE_SCOPE_NOT_IMPORT_AUTHORITATIVE' using errcode='22023'; end if;
  end loop;
  if count_rows=0 then raise exception 'WEEKLY_SOURCE_RULE_GROUP_MEMBERS_REQUIRED' using errcode='22023'; end if;
end;
$function$;

create or replace function private.weekly_source_protected_capability_receipt_v1(p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  a public.weekly_source_group_rule_assignments%rowtype; q jsonb; receipt jsonb;
begin
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  select * into strict a from public.weekly_source_group_rule_assignments where source_group_id=g.id and feature_enabled
    and c.finalisation_week_ending between effective_from_week_ending and coalesce(effective_to_week_ending,'infinity'::date);
  receipt:=a.feature_receipt_json;
  if a.feature_purpose is null or a.feature_purpose not in ('RULE_SET','PROTECTED_SOURCE')
    or (a.feature_purpose='PROTECTED_SOURCE' and a.rule_set_version_id is not null)
    or receipt->>'contract' is distinct from 'WEEKLY_SOURCE_RULE_FEATURE_RECEIPT_V1'
    or receipt->>'assignment_id' is distinct from a.id::text or receipt->>'assignment_version' is distinct from a.version::text
    or receipt->>'source_group_id' is distinct from g.id::text
    or receipt->>'rule_set_version_id' is distinct from a.rule_set_version_id::text
    or receipt->>'feature_purpose' is distinct from a.feature_purpose or receipt->'feature_enabled' is distinct from 'true'::jsonb
    or receipt->>'actor_user_id' is distinct from a.feature_changed_by_user_id::text
    or receipt->>'request_id' is distinct from a.feature_request_id::text or receipt->>'release_id' is distinct from a.feature_release_id
    or receipt->>'effective_from_week_ending' is distinct from a.effective_from_week_ending::text
    or a.feature_request_sha256 is null or a.feature_changed_at_utc is null
    or not exists(select 1 from public.tms_users actor where actor.id=a.feature_changed_by_user_id and actor.is_active and actor.role='admin') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_ACTIVATION_UNQUALIFIED' using errcode='55000'; end if;
  q:=private.weekly_source_protected_capability_release_evidence_v1(g.id,a.effective_from_week_ending,a.effective_to_week_ending,
    receipt#>>'{protected_capability_qualification,qualification_sha256}');
  if q is distinct from receipt->'protected_capability_qualification' or q->>'release_id' is distinct from a.feature_release_id then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_ACTIVATION_UNQUALIFIED' using errcode='55000'; end if;
  return q;
end;
$function$;

create or replace function private.weekly_source_bulk_producer_ready_v1(p_cycle_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare q jsonb;
begin
  q:=private.weekly_source_protected_capability_receipt_v1(p_cycle_id);
  return q->'capabilities' @> '["BULK_SIGNED"]'::jsonb;
exception when no_data_found or too_many_rows or sqlstate '55000' then return false;
end;
$function$;

create or replace function private.weekly_source_automatic_reconcile_producer_ready_v1(p_cycle_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare q jsonb; c public.weekly_source_cycles%rowtype; actual_client uuid; rules jsonb;
begin
  q:=private.weekly_source_protected_capability_receipt_v1(p_cycle_id);
  if not(q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb) then return false; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  actual_client:=private.weekly_source_checking_client_scope_v1(c.current_projection_publication_id);
  if actual_client is not null then
    rules:=private.weekly_source_effective_rule_set_v1(actual_client,c.id)->'values';
    return coalesce(rules->>'invoice_sender'='CLIENT_SELF_BILL' and rules->>'equal_protected_hours'='CLEAR_AUTOMATICALLY',false);
  end if;
  -- Legacy group-wide scope is retained. Each actual event's S18b rule check
  -- remains in the normal selection owner; readiness grants no event permission.
  return exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=c.source_group_id
    and c.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date)
    and private.weekly_source_effective_rule_set_v1(member.client_id,c.id)#>>'{values,invoice_sender}'='CLIENT_SELF_BILL'
    and private.weekly_source_effective_rule_set_v1(member.client_id,c.id)#>>'{values,equal_protected_hours}'='CLEAR_AUTOMATICALLY');
exception when no_data_found or too_many_rows or sqlstate '55000' then return false;
end;
$function$;


-- Complete isolated source proposal. Root review and native proofs pending.
-- Only a native authoritative admitted command supplies this census. Browser
-- requests never gain a client_ids property. Replay retains its original scope.
create or replace function private.weekly_source_bulk_original_client_ids_v1(p_cycle_id uuid,p_actor_id uuid,p_bulk_key text)
returns uuid[] language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare command jsonb; selection jsonb; cas_value jsonb; clients uuid[]; item jsonb;
begin
  if p_cycle_id is null or p_actor_id is null or coalesce(p_bulk_key,'') !~ '^[A-Za-z0-9:_-]{16,120}$' then
    raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_INVALID' using errcode='22023'; end if;
  select audit.after_json into command from public.audit_events audit
    where audit.object_type='weekly_source_bulk_signed_command'
      and audit.object_id_text=p_cycle_id::text||':'||p_actor_id::text||':'||p_bulk_key
      and audit.action='WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED' and audit.event_sequence_is_authoritative
    order by audit.event_sequence desc limit 1;
  selection:=command->'initial_selection'; cas_value:=selection->'source_cas';
  if command->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_COMMAND_V1'
    or command->>'actor_user_id' is distinct from p_actor_id::text or command->>'source_cycle_id' is distinct from p_cycle_id::text
    or command->>'bulk_request_key' is distinct from p_bulk_key
    or selection->>'contract' is distinct from 'WEEKLY_SOURCE_BULK_SIGNED_SELECTION_V1'
    or selection->>'source_cycle_id' is distinct from p_cycle_id::text
    or coalesce(selection->>'selection_sha256','') !~ '^[0-9a-f]{64}$'
    or encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_SIGNED_SELECTION_V1',
      selection-array['selection_sha256','eligible_count','skipped_count']),'hex') is distinct from selection->>'selection_sha256'
    or not private.weekly_exceptional_json_keys_exact_v1(cas_value,array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or not(cas_value ?& array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or cas_value->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_SOURCE_CAS_V1'
    or cas_value->>'source_cycle_id' is distinct from p_cycle_id::text
    or coalesce(cas_value->>'source_cas_sha256','') !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(cas_value->'client_ids') is distinct from 'array' or jsonb_array_length(cas_value->'client_ids')>100 then
    raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_INVALID' using errcode='55000'; end if;
  for item in select value from jsonb_array_elements(cas_value->'client_ids') value loop
    if jsonb_typeof(item) is distinct from 'string' or item#>>'{}' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_INVALID' using errcode='55000'; end if;
  end loop;
  select coalesce(array_agg(distinct value::uuid order by value::uuid),'{}'::uuid[]) into clients
    from jsonb_array_elements_text(cas_value->'client_ids') value;
  if to_jsonb(clients) is distinct from cas_value->'client_ids' then
    raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_INVALID' using errcode='55000'; end if;
  return clients;
exception when invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_INVALID' using errcode='55000';
end;
$function$;


-- Complete isolated source proposal. Root review and native proofs pending.
-- Purpose-specific admission only. Effective policy, c1_source_mode in that
-- policy, policy_sha256, Contract prices and ordinary Source selection stay
-- byte-identical. Existing self-bill/NHSP callers keep their native mode.
create or replace function private.weekly_source_protected_non_self_bill_mode_v1(
  p_client_id uuid,p_contract_id uuid,p_work_date date,p_cycle_id uuid
) returns text language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; policy jsonb; qualification jsonb; declared_client uuid;
begin
  if p_client_id is null or p_contract_id is null or p_work_date is null or p_cycle_id is null then return null; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  policy:=private._weekly_source_effective_policy_v1(p_client_id,p_contract_id,p_work_date);
  if policy->'self_bill_enabled' is distinct from 'false'::jsonb or policy->>'c1_source_mode' is not null
    or policy->>'source_group_id' is distinct from c.source_group_id::text
    or policy->>'source_family' is distinct from 'ROSTER'
    or private.weekly_source_is_import_authoritative_v1(p_client_id,p_contract_id,p_work_date) is distinct from true
    or not exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=c.source_group_id
      and member.client_id=p_client_id and c.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date)) then return null; end if;
  declared_client:=private.weekly_source_checking_client_scope_v1(c.current_projection_publication_id);
  if declared_client is not null and declared_client<>p_client_id then return null; end if;
  qualification:=private.weekly_source_protected_capability_receipt_v1(c.id);
  if not(qualification->'capabilities' @> '["BULK_SIGNED"]'::jsonb) then return null; end if;
  return 'HEALTHROSTER_WEEKLY';
exception when no_data_found or too_many_rows or sqlstate '55000' then return null;
end;
$function$;


-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_source_group_rule_feature_set_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_actor uuid; v_agency uuid; v_environment text; v_group_id uuid; v_assignment_id uuid; v_version_id uuid;
  v_request_id uuid; v_expected bigint; v_enabled boolean; v_from date; v_release_id text; v_reason text; v_purpose text; v_hash text; v_receipt jsonb;
  v_group public.weekly_source_groups%rowtype; v_assignment public.weekly_source_group_rule_assignments%rowtype;
  v_latest private.cloudtms_database_releases%rowtype; v_values jsonb;
  v_member record; v_manifest jsonb; v_shape jsonb; v_result jsonb; v_changes jsonb:='[]'::jsonb;
  v_entry jsonb; v_apply_values jsonb; v_scope_date date; v_agency_invoice boolean:=false; v_qualification jsonb;
begin
  perform private._weekly_source_settings_assert_request_v1(p_request,array['actor_user_id','agency_id','environment','source_group_id','assignment_id',
    'rule_set_version_id','effective_from_week_ending','expected_assignment_version','feature_enabled','feature_purpose','release_id','reason','request_id',
    'client_settings_versions','protected_capability_qualification_sha256'],'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID');
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid; v_agency:=(p_request->>'agency_id')::uuid; v_group_id:=(p_request->>'source_group_id')::uuid;
    v_assignment_id:=(p_request->>'assignment_id')::uuid; v_version_id:=nullif(p_request->>'rule_set_version_id','')::uuid;
    v_request_id:=(p_request->>'request_id')::uuid; v_expected:=(p_request->>'expected_assignment_version')::bigint;
    v_enabled:=(p_request->>'feature_enabled')::boolean; v_from:=(p_request->>'effective_from_week_ending')::date;
    v_release_id:=p_request->>'release_id'; v_reason:=btrim(p_request->>'reason'); v_purpose:=p_request->>'feature_purpose';
  exception when others then raise exception 'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID' using errcode='22023'; end;
  perform private._weekly_source_settings_require_admin_v1(v_actor);
  v_environment:=private._weekly_source_settings_deployment_v1(v_agency,p_request->>'environment');
  if v_group_id is null or v_assignment_id is null or v_request_id is null or v_expected is null or v_from is null
    or jsonb_typeof(p_request->'feature_enabled') is distinct from 'boolean'
    or not p_request ? 'rule_set_version_id' or v_release_id is null or v_reason is null or char_length(v_reason) not between 1 and 500
    or v_purpose is null or v_purpose not in ('RULE_SET','SIGNED_CHECK_ONLY','PROTECTED_SOURCE') or (v_version_id is null)<>(v_purpose in ('SIGNED_CHECK_ONLY','PROTECTED_SOURCE'))
    or p_request->>'effective_from_week_ending'<>to_char(v_from,'YYYY-MM-DD') then
    raise exception 'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID' using errcode='22023'; end if;
  if p_request ? 'protected_capability_qualification_sha256' and
    (jsonb_typeof(p_request->'protected_capability_qualification_sha256') is distinct from 'string'
      or coalesce(p_request->>'protected_capability_qualification_sha256','') !~ '^[0-9a-f]{64}$') then
    raise exception 'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID' using errcode='22023'; end if;
  if v_purpose='PROTECTED_SOURCE' and v_enabled and not(p_request ? 'protected_capability_qualification_sha256') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  if v_purpose='SIGNED_CHECK_ONLY' and p_request ? 'protected_capability_qualification_sha256' then
    raise exception 'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID' using errcode='22023'; end if;
  v_hash:=encode(extensions.digest(convert_to(p_request::text,'UTF8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('weekly-source-cycle-lifecycle:'||v_group_id::text,0));
  -- Match the Client owner's client-before-group lock order. Recheck the exact
  -- dated membership after taking the group/assignment locks below.
  if (select count(distinct gc.client_id) from public.weekly_source_group_clients gc
    where gc.source_group_id=v_group_id and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]')
      && daterange(v_from-6,'infinity'::date,'[]'))>100 then
    raise exception 'WEEKLY_SOURCE_RULE_ACTIVATION_SCOPE_TOO_LARGE' using errcode='22023'; end if;
  for v_member in select distinct gc.client_id from public.weekly_source_group_clients gc
    where gc.source_group_id=v_group_id and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]')
      && daterange(v_from-6,'infinity'::date,'[]') order by gc.client_id
  loop
    perform pg_advisory_xact_lock(hashtextextended('weekly-source-settings-client:'||v_member.client_id::text,0));
  end loop;
  select * into v_group from public.weekly_source_groups where id=v_group_id for update;
  if not found or v_group.agency_id<>v_agency or v_group.environment<>v_environment or not v_group.active or v_group.source_family<>'ROSTER' then
    raise exception 'WEEKLY_SOURCE_RULE_GROUP_NOT_APPLICABLE' using errcode='22023'; end if;
  select * into v_assignment from public.weekly_source_group_rule_assignments where id=v_assignment_id and source_group_id=v_group_id for update;
  if not found or v_assignment.rule_set_version_id is distinct from v_version_id or v_assignment.effective_from_week_ending<>v_from then
    raise exception 'WEEKLY_SOURCE_RULE_ASSIGNMENT_NOT_FOUND' using errcode='22023'; end if;
  -- Latest record, not latest successful record: an APPLYING/FAILED successor holds activation.
  select * into v_latest from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if not found or v_latest.release_id<>v_release_id or v_latest.status<>'VERIFIED'
    or v_latest.completed_at_utc is null or v_latest.installed_contract_sha256 is distinct from v_latest.repository_contract_sha256 then
    raise exception 'WEEKLY_SOURCE_RULE_VERIFIED_RELEASE_REQUIRED' using errcode='55000'; end if;
  if v_assignment.feature_request_id=v_request_id then
    if v_assignment.feature_request_sha256<>v_hash then raise exception 'WEEKLY_SOURCE_RULE_REQUEST_REUSED' using errcode='22023'; end if;
    return v_assignment.feature_receipt_json||jsonb_build_object('replayed',true);
  end if;
  if v_assignment.version<>v_expected then raise exception 'WEEKLY_SOURCE_RULE_ASSIGNMENT_STALE' using errcode='40001'; end if;
  perform 1 from public.clients c where exists(select 1 from public.weekly_source_group_clients gc
    where gc.client_id=c.id and gc.source_group_id=v_group_id
      and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]'))
    order by c.id for update;
  perform 1 from public.client_settings cs where exists(select 1 from public.weekly_source_group_clients gc
    where gc.client_id=cs.client_id and gc.source_group_id=v_group_id
      and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]'))
    order by cs.id for update;
  perform 1 from public.contracts c where exists(select 1 from public.weekly_source_group_clients gc
    where gc.client_id=c.client_id and gc.source_group_id=v_group_id
      and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]'))
    order by c.id for share;
  -- Same owner requalification is metadata-only. Exact current assignment CAS,
  -- actor/deployment/latest VERIFIED and locked Client/Contract gates above stay.
  if v_enabled and p_request ? 'protected_capability_qualification_sha256' then
    v_qualification:=private.weekly_source_protected_capability_release_evidence_v1(v_group_id,v_from,
      v_assignment.effective_to_week_ending,p_request->>'protected_capability_qualification_sha256');
  elsif p_request ? 'protected_capability_qualification_sha256' then
    raise exception 'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID' using errcode='22023'; end if;
  if v_assignment.feature_enabled=v_enabled then
    if not v_enabled or v_qualification is null or v_assignment.feature_purpose is distinct from v_purpose then
      raise exception 'WEEKLY_SOURCE_RULE_FEATURE_ALREADY_SET' using errcode='22023'; end if;
    if v_purpose='PROTECTED_SOURCE' then
      perform private.weekly_source_protected_source_activation_scope_v1(v_group_id,v_from,v_assignment.effective_to_week_ending);
    else
      select values_json into strict v_values from public.weekly_source_rule_set_versions where id=v_version_id;
      perform private._weekly_source_rule_group_context_v1(v_group_id,v_from,v_assignment.effective_to_week_ending,v_values,true);
    end if;
    if p_request ? 'client_settings_versions' and p_request->'client_settings_versions'<>'[]'::jsonb then
      raise exception 'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_INVALID' using errcode='22023'; end if;
    -- Preserve the exact AGENCY restore receipt, without calling Client save.
    v_receipt:=v_assignment.feature_receipt_json||jsonb_build_object('assignment_version',v_assignment.version+1,
      'release_id',v_release_id,'actor_user_id',v_actor,'changed_at_utc',transaction_timestamp(),'reason',v_reason,
      'request_id',v_request_id,'protected_capability_qualification',v_qualification,'requalification',true,'replayed',false);
    update public.weekly_source_group_rule_assignments set feature_changed_by_user_id=v_actor,
      feature_changed_at_utc=transaction_timestamp(),feature_change_reason=v_reason,feature_release_id=v_release_id,
      feature_request_id=v_request_id,feature_request_sha256=v_hash,feature_receipt_json=v_receipt,version=version+1 where id=v_assignment_id;
    return v_receipt;
  end if;
  select v.values_json into v_values from public.weekly_source_rule_set_versions v join public.weekly_source_rule_sets r on r.id=v.rule_set_id
    where v.id=v_version_id and r.agency_id=v_agency and r.environment=v_environment;
  if v_version_id is not null and not found then raise exception 'WEEKLY_SOURCE_RULE_VERSION_NOT_FOUND' using errcode='22023'; end if;
  v_agency_invoice:=coalesce(v_values->>'invoice_sender'='AGENCY_INVOICE',false);
  if v_agency_invoice then
    v_manifest:=p_request->'client_settings_versions';
    if jsonb_typeof(v_manifest) is distinct from 'array' or jsonb_array_length(v_manifest) not between 1 and 100 then
      raise exception 'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_REQUIRED' using errcode='22023'; end if;
    for v_entry in select value from jsonb_array_elements(v_manifest) loop
      perform private._weekly_source_settings_assert_request_v1(v_entry,array['client_id','expected_settings_version'],'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_INVALID');
      if jsonb_typeof(v_entry->'client_id') is distinct from 'string' or v_entry->>'client_id' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
        or jsonb_typeof(v_entry->'expected_settings_version') is distinct from 'string'
        or v_entry->>'expected_settings_version' !~ '^[0-9a-f]{64}$' then
        raise exception 'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_INVALID' using errcode='22023'; end if;
    end loop;
    if (select count(distinct value->>'client_id') from jsonb_array_elements(v_manifest))<>jsonb_array_length(v_manifest)
      or (select count(distinct gc.client_id) from public.weekly_source_group_clients gc where gc.source_group_id=v_group_id
        and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]'))<>jsonb_array_length(v_manifest)
      or exists(select 1 from jsonb_array_elements(v_manifest) x where not exists(select 1 from public.weekly_source_group_clients gc
        where gc.source_group_id=v_group_id and gc.client_id=(x.value->>'client_id')::uuid
          and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]'))) then
      raise exception 'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_INVALID' using errcode='22023'; end if;
    for v_member in select gc.client_id,greatest(v_from-6,min(gc.valid_from)) as scope_date
      from public.weekly_source_group_clients gc where gc.source_group_id=v_group_id
        and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]')
      group by gc.client_id order by gc.client_id
    loop
      v_scope_date:=v_member.scope_date;
      if v_scope_date<(transaction_timestamp() at time zone 'Europe/London')::date then
        raise exception 'WEEKLY_SOURCE_RULE_FUTURE_WEEK_REQUIRED' using errcode='22023'; end if;
      v_shape:=private._weekly_source_settings_client_shape_v1(v_agency,v_environment,v_member.client_id,v_scope_date);
      if v_shape->>'settings_version'<>(select value->>'expected_settings_version' from jsonb_array_elements(v_manifest) where (value->>'client_id')::uuid=v_member.client_id) then
        raise exception 'WEEKLY_SOURCE_RULE_CLIENT_SETTINGS_STALE' using errcode='40001'; end if;
      if v_enabled then
        if exists(select 1 from public.weekly_source_client_policies cp where cp.source_group_id=v_group_id and cp.client_id=v_member.client_id
          and cp.effective_from>v_scope_date and cp.effective_from<=coalesce(v_assignment.effective_to_week_ending,'infinity'::date)) then
          raise exception 'WEEKLY_SOURCE_RULE_ACTIVATION_FUTURE_SETTINGS_REFUSED' using errcode='22023'; end if;
        v_changes:=v_changes||jsonb_build_array(jsonb_build_object('client_id',v_member.client_id,'scope_date',v_scope_date,
          'before_values',v_shape->'settings','before_settings_version',v_shape->>'settings_version',
          'before_policy_id',(select cp.id from public.weekly_source_client_policies cp where cp.source_group_id=v_group_id and cp.client_id=v_member.client_id
            and v_scope_date between cp.effective_from and coalesce(cp.effective_to,'infinity'::date))));
      else
        select value into v_entry from jsonb_array_elements(v_assignment.feature_receipt_json->'client_changes')
          where (value->>'client_id')::uuid=v_member.client_id;
        if not found or v_entry->>'after_settings_version' is distinct from v_shape->>'settings_version'
          or (v_entry->>'scope_date')::date<>v_scope_date then
          raise exception 'WEEKLY_SOURCE_RULE_CLIENT_RESTORE_STALE' using errcode='40001'; end if;
        v_changes:=v_changes||jsonb_build_array(v_entry);
      end if;
    end loop;
  elsif p_request ? 'client_settings_versions' and p_request->'client_settings_versions'<>'[]'::jsonb then
    raise exception 'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_INVALID' using errcode='22023';
  end if;
  if v_enabled then
    if v_from<(transaction_timestamp() at time zone 'Europe/London')::date then
      raise exception 'WEEKLY_SOURCE_RULE_FUTURE_WEEK_REQUIRED' using errcode='22023'; end if;
    perform 1 from public.weekly_source_cycles c where c.source_group_id=v_group_id
      and c.finalisation_week_ending between v_from and coalesce(v_assignment.effective_to_week_ending,'infinity'::date) order by c.id for update;
    if exists(select 1 from public.weekly_source_cycles c where c.source_group_id=v_group_id
      and c.finalisation_week_ending between v_from and coalesce(v_assignment.effective_to_week_ending,'infinity'::date)
      and (c.current_final_revision_id is not null or c.state in ('FINALISING','FINALISED','CORRECTION_IN_PROGRESS')
        or exists(select 1 from public.weekly_source_final_revisions f where f.source_cycle_id=c.id))) then
      raise exception 'WEEKLY_SOURCE_RULE_FINALISED_WEEK_REFUSED' using errcode='55000'; end if;
    if v_purpose='PROTECTED_SOURCE' then
      perform private.weekly_source_protected_source_activation_scope_v1(v_group_id,v_from,v_assignment.effective_to_week_ending);
    else
      perform private._weekly_source_rule_group_context_v1(v_group_id,v_from,v_assignment.effective_to_week_ending,v_values,not v_agency_invoice);
    end if;
  end if;
  -- Publish the gate and the approved Client policy transition together. The
  -- feature receipt and Client writes cannot survive any refusal below.
  update public.weekly_source_group_rule_assignments set feature_enabled=v_enabled,feature_purpose=v_purpose,
    feature_changed_by_user_id=v_actor,feature_changed_at_utc=transaction_timestamp(),feature_change_reason=v_reason,feature_release_id=v_release_id,
    feature_request_id=v_request_id,feature_request_sha256=v_hash,feature_receipt_json='{}'::jsonb where id=v_assignment_id;
  if v_agency_invoice then
    v_manifest:='[]'::jsonb;
    for v_entry in select value from jsonb_array_elements(v_changes) order by value->>'client_id' loop
      v_scope_date:=(v_entry->>'scope_date')::date;
      v_shape:=private._weekly_source_settings_client_shape_v1(v_agency,v_environment,(v_entry->>'client_id')::uuid,v_scope_date);
      v_apply_values:=v_entry->'before_values'||jsonb_build_object('effective_from',v_scope_date);
      if v_enabled then v_apply_values:=v_apply_values||jsonb_build_object('authority_mode','SOURCE_AUTHORITY','document_mode','CHECK_ONLY','self_bill_enabled',false); end if;
      v_result:=public.weekly_source_client_settings_save_atomic_v1(jsonb_build_object('actor_user_id',v_actor,'agency_id',v_agency,'environment',v_environment,
        'client_id',v_entry->>'client_id','expected_settings_version',v_shape->>'settings_version','settings',v_apply_values));
      if coalesce((v_result->>'ok')::boolean,false) is not true then raise exception 'WEEKLY_SOURCE_RULE_CLIENT_TRANSITION_FAILED' using errcode='55000'; end if;
      v_shape:=private._weekly_source_settings_client_shape_v1(v_agency,v_environment,(v_entry->>'client_id')::uuid,v_scope_date);
      v_manifest:=v_manifest||jsonb_build_array(v_entry||jsonb_build_object(
        case when v_enabled then 'after_values' else 'restored_values' end,v_shape->'settings',
        case when v_enabled then 'after_settings_version' else 'restored_settings_version' end,v_shape->>'settings_version',
        case when v_enabled then 'after_policy_id' else 'restored_policy_id' end,(select cp.id from public.weekly_source_client_policies cp
          where cp.source_group_id=v_group_id and cp.client_id=(v_entry->>'client_id')::uuid
            and v_scope_date between cp.effective_from and coalesce(cp.effective_to,'infinity'::date))));
    end loop;
    v_changes:=v_manifest;
    if v_enabled then perform private._weekly_source_rule_group_context_v1(v_group_id,v_from,v_assignment.effective_to_week_ending,v_values,true); end if;
  end if;
  v_receipt:=jsonb_build_object('contract','WEEKLY_SOURCE_RULE_FEATURE_RECEIPT_V1','assignment_id',v_assignment_id,
    'assignment_version',v_assignment.version+1,'source_group_id',v_group_id,'rule_set_version_id',v_version_id,
    'effective_from_week_ending',v_from,'feature_enabled',v_enabled,'feature_purpose',v_purpose,'release_id',v_release_id,
    'actor_user_id',v_actor,'changed_at_utc',transaction_timestamp(),'reason',v_reason,'request_id',v_request_id,'client_changes',v_changes,'replayed',false)||case when v_qualification is null then '{}'::jsonb else
      jsonb_build_object('protected_capability_qualification',v_qualification) end;
  update public.weekly_source_group_rule_assignments set feature_enabled=v_enabled,feature_purpose=v_purpose,
    feature_changed_by_user_id=v_actor,feature_changed_at_utc=transaction_timestamp(),feature_change_reason=v_reason,feature_release_id=v_release_id,
    feature_request_id=v_request_id,feature_request_sha256=v_hash,feature_receipt_json=v_receipt,version=version+1 where id=v_assignment_id;
  return v_receipt;
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function private.weekly_source_protect_all_signed_selection_v1(p_source_cycle_id uuid,p_actor_user_id uuid,p_own_stage_context jsonb,p_original_client_ids uuid[])
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_cycle public.weekly_source_cycles%rowtype; v_publication public.weekly_source_projection_publications%rowtype;
  v_row record; v_claim jsonb; v_facts jsonb; v_witness jsonb; v_selection jsonb; v_key text;
  v_eligible jsonb:='[]'::jsonb; v_skipped jsonb:='[]'::jsonb; v_reason text; v_code text; v_count integer; v_clients uuid[]:='{}'::uuid[]; v_cas jsonb; v_own_stage boolean;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict v_cycle from public.weekly_source_cycles where id=p_source_cycle_id;
  perform private.weekly_source_office_authority_v1(p_actor_user_id,'APPROVE_PROTECTED_PAY',v_cycle.source_group_id,null,v_cycle.finalisation_week_ending);
  select * into strict v_publication from public.weekly_source_projection_publications
    where id=v_cycle.current_projection_publication_id and source_cycle_id=v_cycle.id and state='CURRENT'
      and authority_scope_kind='CYCLE' and correction_session_id is null;
  perform private.weekly_source_query_current_publication_v1(v_cycle.id,v_publication.id);
  for v_row in select incident.id as incident_id,incident.episode_number,incident.candidate_id,incident.client_id,
      incident.work_event_id,comparison.id as comparison_id,comparison.contract_id,comparison.issue_family,
      comparison.material_comparison_fingerprint,work.work_date
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      and comparison.incident_id=incident.id
    join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id
      and work.client_id=incident.client_id and work.first_source_group_id=v_cycle.source_group_id
    join public.contracts contract on contract.id=comparison.contract_id and contract.candidate_id=incident.candidate_id
      and contract.client_id=incident.client_id
    where incident.source_cycle_id=v_cycle.id and incident.state='OPEN'
      and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work.work_date)
      and (private.weekly_source_checking_client_scope_v1(v_publication.id) is null
        or incident.client_id=private.weekly_source_checking_client_scope_v1(v_publication.id))
    order by incident.candidate_id,work.id,incident.id
  loop
    v_code:=null; v_reason:=null; v_claim:=null;
    if not (v_row.client_id=any(v_clients)) then v_clients:=array_append(v_clients,v_row.client_id); end if;
    if v_row.issue_family not in ('HEALTHROSTER_NOT_FINALISED','SOURCE_MISSING_OR_NOT_AUTHORISED') then
      v_code:='DECIDE_INDIVIDUALLY'; v_reason:=case v_row.issue_family when 'SOURCE_HOURS_DIFFER'
        then 'Hours differ - decide individually' else 'Review this shift individually' end;
    elsif private.weekly_source_covered_hours_incident_v1(v_row.incident_id) then
      v_code:='ALREADY_PROTECTED'; v_reason:='Already protected';
    else
      -- A bare or partial WAIT is unknown, never treated as unprotected.
      v_own_stage:=exists(select 1 from jsonb_array_elements(p_own_stage_context->'exclusions') exclusion
        where exclusion->>'work_event_id'=v_row.work_event_id::text);
      v_witness:=case when v_own_stage then null else private.weekly_source_protected_wait_witness_v1(v_row.work_event_id,v_cycle.id) end;
      if v_witness is not null then v_code:='ALREADY_PROTECTED'; v_reason:='Already protected'; end if;
      if v_code is null then
        if p_own_stage_context is null then
          v_facts:=private.weekly_source_shift_on_self_bill_v1(v_row.work_event_id,v_cycle.id);
        else
          if to_regprocedure('private.weekly_source_shift_on_self_bill_context_v1(uuid,uuid,jsonb)') is null then
            raise exception 'WEEKLY_SOURCE_BULK_PRODUCER_UNAVAILABLE' using errcode='55000'; end if;
          execute 'select private.weekly_source_shift_on_self_bill_context_v1($1,$2,$3)' into v_facts
            using v_row.work_event_id,v_cycle.id,p_own_stage_context;
        end if;
        if jsonb_typeof(v_facts) is distinct from 'object' or not (v_facts ?& array['on_accepted_report','bound_to_finalised_export','invoice_ready','s25_pay_selected'])
          or exists(select 1 from unnest(array['on_accepted_report','bound_to_finalised_export','invoice_ready','s25_pay_selected']) field
            where jsonb_typeof(v_facts->field) is distinct from 'boolean') then
          raise exception 'WEEKLY_SOURCE_SELF_BILL_FACTS_UNAVAILABLE' using errcode='55000'; end if;
        if (v_facts->>'s25_pay_selected')::boolean or (v_facts->>'on_accepted_report')::boolean then
          v_code:='ON_SELF_BILL'; v_reason:='Already on the client self-bill';
        end if;
      end if;
      if v_code is null then
        begin
          v_claim:=private.weekly_source_bulk_signed_claim_v1(v_row.comparison_id);
          if v_claim->>'eligible' is distinct from 'true' then v_code:=v_claim->>'code'; v_reason:=v_claim->>'reason'; end if;
        exception when others then
          if sqlerrm='WEEKLY_PROTECTED_EVIDENCE_UNSIGNED' then v_code:='NO_SIGNED_SUBMISSION'; v_reason:='No signed submission';
          elsif sqlerrm='WEEKLY_PROTECTED_EVIDENCE_INVALID' then v_code:='SIGNED_SUBMISSION_UNAVAILABLE'; v_reason:='Signed submission changed - protect individually';
          else raise; end if;
        end;
      end if;
    end if;
    if v_code is not null then
      v_skipped:=v_skipped||jsonb_build_array(jsonb_build_object('incident_id',v_row.incident_id,'work_event_id',v_row.work_event_id,
        'work_date',v_row.work_date,'code',v_code,'reason',v_reason));
    else
      v_eligible:=v_eligible||jsonb_build_array(jsonb_build_object('incident_id',v_row.incident_id,'issue_episode',v_row.episode_number,
        'comparison_revision_id',v_row.comparison_id,'comparison_fingerprint',encode(v_row.material_comparison_fingerprint,'hex'),
        'candidate_id',v_row.candidate_id,'client_id',v_row.client_id,'contract_id',v_row.contract_id,
        'work_event_id',v_row.work_event_id,'claim',v_claim,'self_bill_facts',v_facts));
    end if;
  end loop;
  -- Protected/skipped questions retain their Client in the Source CAS census.
  -- Completing a round must not shrink its original relevant Client authority.
  select coalesce(array_agg(item order by item),'{}'::uuid[]) into v_clients from unnest(v_clients) item;
  if p_original_client_ids is not null then
    if array_position(p_original_client_ids,null::uuid) is not null or cardinality(p_original_client_ids)>100
      or exists(select 1 from unnest(v_clients) client where not(client=any(p_original_client_ids))) then
      raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_CHANGED' using errcode='40001'; end if;
    select coalesce(array_agg(distinct client order by client),'{}'::uuid[]) into v_clients from unnest(p_original_client_ids) client;
  end if;
  v_cas:=private.weekly_source_bulk_source_cas_assert_v1(v_cycle.id,v_clients);
  v_count:=jsonb_array_length(v_eligible);
  v_selection:=jsonb_build_object('contract','WEEKLY_SOURCE_BULK_SIGNED_SELECTION_V1','source_cycle_id',v_cycle.id,
    'source_cycle_version',v_cycle.version,'projection_publication_id',v_publication.id,
    'source_cas',v_cas,'eligible',v_eligible,'skipped',v_skipped);
  return v_selection||jsonb_build_object('selection_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_BULK_SIGNED_SELECTION_V1',v_selection),'hex'),'eligible_count',v_count,
    'skipped_count',jsonb_array_length(v_skipped));
end;
$function$;

create or replace function private.weekly_source_protect_all_signed_selection_v1(p_source_cycle_id uuid,p_actor_user_id uuid,p_own_stage_context jsonb default null)
returns jsonb language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
  select private.weekly_source_protect_all_signed_selection_v1(p_source_cycle_id,p_actor_user_id,p_own_stage_context,null::uuid[]);
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function private.weekly_source_bulk_stage_proof_v1(p_stage jsonb,p_financial_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_request jsonb:=p_stage->'bulk_signed_selection_proof'; v_context jsonb; v_selection jsonb; v_item jsonb; v_proof jsonb;
  v_count integer; v_original_clients uuid[]; v_run public.weekly_exceptional_orchestration_runs%rowtype;
begin
  if not private.weekly_exceptional_json_keys_exact_v1(v_request,array['expected_selection_sha256','expected_source_cas_sha256','incident_id','bulk_request_key'])
    or not(v_request ?& array['expected_selection_sha256','expected_source_cas_sha256','incident_id','bulk_request_key'])
    or coalesce(v_request->>'expected_selection_sha256','') !~ '^[0-9a-f]{64}$'
    or coalesce(v_request->>'expected_source_cas_sha256','') !~ '^[0-9a-f]{64}$'
    or coalesce(v_request->>'bulk_request_key','') !~ '^[A-Za-z0-9:_-]{16,120}$' then
    raise exception 'WEEKLY_SOURCE_BULK_STAGE_PROOF_INVALID' using errcode='22023'; end if;
  select * into strict v_run from public.weekly_exceptional_orchestration_runs where id=(p_stage->>'orchestration_run_id')::uuid;
  if v_run.request_kind not in ('APPROVE','AMEND') or v_run.state is distinct from 'RUNNING'
    or v_run.requested_by_user_id::text is distinct from p_stage->>'actor_user_id' then
    raise exception 'WEEKLY_SOURCE_BULK_STAGE_PROOF_INVALID' using errcode='55000'; end if;
  v_context:=private.weekly_source_bulk_own_stage_context_v1((p_stage->>'source_cycle_id')::uuid,(p_stage->>'actor_user_id')::uuid,
    v_request->>'bulk_request_key',v_request->>'expected_selection_sha256',v_request->>'expected_source_cas_sha256');
  if v_context is not null then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_ALREADY_STAGED' using errcode='55000'; end if;
  v_original_clients:=private.weekly_source_bulk_original_client_ids_v1((p_stage->>'source_cycle_id')::uuid,
    (p_stage->>'actor_user_id')::uuid,v_request->>'bulk_request_key');
  v_selection:=private.weekly_source_protect_all_signed_selection_v1((p_stage->>'source_cycle_id')::uuid,(p_stage->>'actor_user_id')::uuid,v_context,v_original_clients);
  if v_selection->>'selection_sha256' is distinct from v_request->>'expected_selection_sha256'
    or v_selection#>>'{source_cas,source_cas_sha256}' is distinct from v_request->>'expected_source_cas_sha256' then
    raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
  select count(*),jsonb_agg(value)->0 into v_count,v_item from jsonb_array_elements(v_selection->'eligible') value
    where value->>'incident_id'=v_request->>'incident_id';
  if v_count<>1 or v_item->>'work_event_id' is distinct from p_stage->>'work_event_id'
    or v_item->>'client_id' is distinct from p_stage->>'client_id'
    or v_item#>>'{claim,evidence_timesheet_id}' is distinct from p_stage->>'evidence_timesheet_id'
    or v_item->>'comparison_revision_id' is distinct from p_stage->>'current_comparison_revision_id'
    or (v_item#>>'{claim,work_date}')::date is distinct from (p_stage#>>'{protected_schedule,work_date}')::date
    or (v_item#>>'{claim,start_at_local}')::timestamp is distinct from (p_stage#>>'{protected_schedule,start_at_local}')::timestamp
    or (v_item#>>'{claim,end_at_local}')::timestamp is distinct from (p_stage#>>'{protected_schedule,end_at_local}')::timestamp
    or (v_item#>>'{claim,break_minutes}')::integer is distinct from (p_stage#>>'{protected_schedule,break_minutes}')::integer then
    raise exception 'WEEKLY_SOURCE_BULK_STAGE_PROOF_INVALID' using errcode='55000'; end if;
  v_proof:=jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_STAGED_PROOF_V1','actor_user_id',p_stage->>'actor_user_id',
    'source_cycle_id',p_stage->>'source_cycle_id','bulk_request_key',v_request->>'bulk_request_key',
    'selection_sha256',v_selection->>'selection_sha256','source_cas',v_selection->'source_cas',
    'eligible_claim',v_item,'financial_row_id',p_financial_id,
    'request_sha256',p_stage#>>'{c1_request,request_sha256}','target_snapshot_sha256',
    encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_TARGET_SNAPSHOT_V1',p_stage->'target_snapshot'),'hex'));
  return v_proof||jsonb_build_object('proof_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_STAGED_PROOF_V1',v_proof),'hex'));
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_source_protect_all_signed_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_actor uuid; v_cycle_id uuid; v_mode text; v_phase text; v_key text; v_object text; v_initial jsonb;
  v_cycle public.weekly_source_cycles%rowtype; v_group uuid; v_selection jsonb; v_context jsonb; v_stage jsonb;
  v_request public.weekly_exceptional_c1_publication_requests%rowtype; v_generation public.weekly_exceptional_pay_generations%rowtype;
  v_proof jsonb; v_own jsonb; v_lock jsonb; v_gate jsonb; v_result jsonb; v_response jsonb; v_refusal text;
  v_claim jsonb; v_remaining jsonb:='[]'::jsonb; v_done jsonb:='[]'::jsonb; v_current jsonb; v_count integer;
  v_round_key text; v_source_cas text; v_selection_sha text; v_completed boolean; v_initial_claim jsonb; v_original_clients uuid[];
begin
  perform private.weekly_source_query_require_service_v1();
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,array['actor_user_id','source_cycle_id','mode','phase',
    'bulk_request_key','expected_selection_sha256','staged'])
    or jsonb_typeof(p_request) is distinct from 'object' or octet_length(convert_to(p_request::text,'UTF8'))>262144 then
    raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end if;
  begin v_actor:=(p_request->>'actor_user_id')::uuid; v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
  exception when invalid_text_representation then raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end;
  v_mode:=p_request->>'mode'; v_phase:=coalesce(p_request->>'phase','ADMIT'); v_key:=p_request->>'bulk_request_key';
  select * into strict v_cycle from public.weekly_source_cycles where id=v_cycle_id;
  perform private.weekly_source_office_authority_v1(v_actor,'APPROVE_PROTECTED_PAY',v_cycle.source_group_id,null,v_cycle.finalisation_week_ending);
  if v_mode='PREVIEW' then
    if p_request ? 'staged' or p_request ? 'phase' then raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end if;
    return jsonb_build_object('ok',true,'mode','PREVIEW')||private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,null);
  end if;
  if v_mode is distinct from 'COMMIT' or v_phase not in ('ADMIT','ROUND','APPLY')
    or coalesce(v_key,'') !~ '^[A-Za-z0-9:_-]{16,120}$' then
    raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end if;
  v_object:=v_cycle_id::text||':'||v_actor::text||':'||v_key;
  select audit.after_json into v_initial from public.audit_events audit
    where audit.object_type='weekly_source_bulk_signed_command' and audit.object_id_text=v_object
      and audit.action='WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED' and audit.event_sequence_is_authoritative
    order by audit.event_sequence desc limit 1;
  if v_phase='ADMIT' then
    -- No family/gate call is made in this phase. The original cycle mutex owns
    -- admission idempotence, and is released before Worker preparation starts.
    perform 1 from public.weekly_source_groups where id=v_cycle.source_group_id for share;
    v_group:=v_cycle.source_group_id;
    select * into strict v_cycle from public.weekly_source_cycles where id=v_cycle_id for update;
    if v_cycle.source_group_id is distinct from v_group then
      raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
    select audit.after_json into v_initial from public.audit_events audit
      where audit.object_type='weekly_source_bulk_signed_command' and audit.object_id_text=v_object
        and audit.action='WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED' and audit.event_sequence_is_authoritative
      order by audit.event_sequence desc limit 1;
    if v_initial is not null then
      if v_initial#>>'{initial_selection,selection_sha256}' is distinct from p_request->>'expected_selection_sha256' then
        raise exception 'WEEKLY_SOURCE_BULK_REPLAY_CONFLICT' using errcode='23505'; end if;
      return jsonb_build_object('ok',true,'phase','ADMITTED','idempotent_replay',true,'initial_selection',v_initial->'initial_selection');
    end if;
    v_selection:=private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,null);
    if v_selection->>'selection_sha256' is distinct from p_request->>'expected_selection_sha256' then
      raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
    v_initial:=jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_COMMAND_V1','actor_user_id',v_actor,
      'source_cycle_id',v_cycle_id,'bulk_request_key',v_key,'initial_selection',v_selection);
    perform public._audit_insert('weekly_source_bulk_signed_command',v_object,'WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED',
      null,v_initial,'Protect signed MyTMS submissions',v_actor);
    return jsonb_build_object('ok',true,'phase','ADMITTED','idempotent_replay',false,'initial_selection',v_selection);
  end if;
  if v_initial is null then raise exception 'WEEKLY_SOURCE_BULK_COMMAND_NOT_ADMITTED' using errcode='55000'; end if;
  v_original_clients:=private.weekly_source_bulk_original_client_ids_v1(v_cycle_id,v_actor,v_key);
  if v_phase='ROUND' then
    -- Resume the exact pending generation before deriving another round.
    select generation.complete_next_vector_json->'bulk_signed_selection_proof' into v_proof
      from public.weekly_exceptional_c1_publication_requests request
      join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id
      where generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,bulk_request_key}'=v_key
        and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,actor_user_id}'=v_actor::text
        and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,source_cycle_id}'=v_cycle_id::text
        and request.state='READY' and generation.lifecycle_state='PENDING_C1'
      order by request.id limit 1;
    if v_proof is not null then
      v_context:=private.weekly_source_bulk_own_stage_context_v1(v_cycle_id,v_actor,v_key,
        v_proof->>'selection_sha256',v_proof#>>'{source_cas,source_cas_sha256}');
    end if;
    v_selection:=private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,v_context,v_original_clients);
    if v_selection#>>'{source_cas,source_cas_sha256}' is distinct from v_initial#>>'{initial_selection,source_cas,source_cas_sha256}' then
      raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
    for v_initial_claim in select value from jsonb_array_elements(v_initial#>'{initial_selection,eligible}') loop
      -- A completed disposition is accepted only from this command's actual
      -- immutable native stage proof and local completion receipt.
      select exists(select 1 from public.weekly_exceptional_c1_publication_requests request
        join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id
        join private.weekly_source_local_protected_decision_receipts receipt on receipt.publication_request_id=request.id
          and receipt.actor_user_id=v_actor and receipt.request_sha256=request.request_sha256 and receipt.state in ('COMPLETE','PENDING_FREEZE')
        where generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,bulk_request_key}'=v_key
          and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,actor_user_id}'=v_actor::text
          and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,source_cycle_id}'=v_cycle_id::text
          and generation.complete_next_vector_json#>'{bulk_signed_selection_proof,eligible_claim}'=v_initial_claim
          and private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',generation.complete_next_vector_json)=generation.complete_next_vector_hash
          and receipt.result_json->>'ok'='true') into v_completed;
      if v_completed then v_done:=v_done||jsonb_build_array(v_initial_claim->'work_event_id'); continue; end if;
      select count(*),jsonb_agg(value)->0 into v_count,v_current from jsonb_array_elements(v_selection->'eligible') value
        where value->>'work_event_id'=v_initial_claim->>'work_event_id';
      if v_count<>1 or v_current is distinct from v_initial_claim then
        raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLAIM_CHANGED' using errcode='40001'; end if;
      v_remaining:=v_remaining||jsonb_build_array(v_current);
    end loop;
    return jsonb_build_object('ok',true,'phase','ROUND','selection',v_selection,'remaining',v_remaining,'completed_work_event_ids',v_done,
      'pending_stages',coalesce(v_context->'exclusions','[]'::jsonb),'max_stages_per_round',1);
  end if;
  if jsonb_typeof(p_request->'staged') is distinct from 'array' or jsonb_array_length(p_request->'staged')<>1 then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_INVALID' using errcode='22023'; end if;
  v_stage:=p_request#>'{staged,0}';
  if not private.weekly_exceptional_json_keys_exact_v1(v_stage,array['publication_request_id','request_sha256'])
    or not(v_stage ?& array['publication_request_id','request_sha256']) then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_INVALID' using errcode='22023'; end if;
  select * into strict v_request from public.weekly_exceptional_c1_publication_requests where id=(v_stage->>'publication_request_id')::uuid;
  select * into strict v_generation from public.weekly_exceptional_pay_generations where id=v_request.generation_id;
  v_proof:=v_generation.complete_next_vector_json->'bulk_signed_selection_proof';
  v_selection_sha:=v_proof->>'selection_sha256'; v_source_cas:=v_proof#>>'{source_cas,source_cas_sha256}';
  v_round_key:=v_request.id::text;
  -- Exact audit replay precedes mutable freshness checks and locks.
  select audit.after_json into v_response from public.audit_events audit where audit.object_type='weekly_source_bulk_signed_command'
    and audit.object_id_text=v_object and audit.action='WEEKLY_SOURCE_BULK_SIGNED_ROUND_COMPLETED'
    and audit.after_json->>'publication_request_id'=v_round_key and audit.event_sequence_is_authoritative
    order by audit.event_sequence desc limit 1;
  if v_response is not null then
    if v_response->>'request_sha256' is distinct from v_stage->>'request_sha256' then
      raise exception 'WEEKLY_SOURCE_BULK_REPLAY_CONFLICT' using errcode='23505'; end if;
    return v_response||jsonb_build_object('idempotent_replay',true);
  end if;
  -- Complete round has one real family. Every Candidate gate comes first;
  -- native I-1 still receives the complete round set and owns its raw order.
  perform private.weekly_source_pay_query_admit_v2();
  v_gate:=private.weekly_source_candidate_serial_gate_v1(v_request.candidate_id,'WORKBENCH_CANDIDATE_ENTITLEMENT_PUBLICATION',
    v_request.id,'WEEKLY_SOURCE_ENTITLEMENT_PUBLICATION');
  if v_gate->>'ok' is distinct from 'true' then return v_gate||jsonb_build_object('phase','BLOCKED','accepted',false); end if;
  if not exists(select 1 from public.timesheets sheet join public.contracts contract on contract.id=sheet.contract_id
    where sheet.timesheet_id=v_request.root_timesheet_id and contract.candidate_id=v_request.candidate_id) then
    raise exception 'WEEKLY_SOURCE_BULK_ROOT_CANDIDATE_MISMATCH' using errcode='55000'; end if;
  v_lock:=private.weekly_source_lock_family_rows_v1(array[v_request.root_timesheet_id],null);
  if v_lock->>'ok' is distinct from 'true' then return v_lock||jsonb_build_object('phase','BLOCKED','accepted',false); end if;
  v_group:=v_cycle.source_group_id;
  perform 1 from public.weekly_source_groups where id=v_group and active for update;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_cycle_id for update;
  if v_cycle.source_group_id is distinct from v_group then raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
  v_own:=private.weekly_source_bulk_own_stage_v1(v_request.id,v_actor,v_cycle_id,v_key,v_selection_sha,v_source_cas);
  if v_request.request_sha256 is distinct from private.weekly_exceptional_hex_sha256_v1(v_stage->>'request_sha256')
    or not exists(select 1 from jsonb_array_elements(v_initial#>'{initial_selection,eligible}') original
      where original=v_proof->'eligible_claim') then
    raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLAIM_CHANGED' using errcode='40001'; end if;
  v_context:=private.weekly_source_bulk_own_stage_context_v1(v_cycle_id,v_actor,v_key,v_selection_sha,v_source_cas);
  if jsonb_array_length(v_context->'exclusions') is distinct from 1
    or v_context#>>'{exclusions,0,publication_request_id}' is distinct from v_request.id::text then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_INVALID' using errcode='55000'; end if;
  v_selection:=private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,v_context,v_original_clients);
  if v_selection->>'selection_sha256' is distinct from v_selection_sha
    or v_source_cas is distinct from v_initial#>>'{initial_selection,source_cas,source_cas_sha256}' then
    raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
  begin
    v_result:=public.weekly_exceptional_pay_complete_local_v1(jsonb_build_object('schema_version','WEEKLY_PROTECTED_LOCAL_COMPLETE_V1',
      'actor_user_id',v_actor,'publication_request_id',v_request.id,'expected_request_sha256',v_stage->>'request_sha256',
      'idempotency_key',(select idempotency_key from public.weekly_exceptional_orchestration_runs where id=v_request.orchestration_run_id)||':local-complete'));
    if v_result->>'ok' is distinct from 'true' or v_result->>'outcome' not in ('PUBLISHED','SAVED_PENDING_FREEZE') then
      raise exception 'WEEKLY_SOURCE_BULK_NATIVE_COMPLETE_REFUSED' using errcode='55000'; end if;
  exception when others then
    v_refusal:=coalesce(substring(sqlerrm from '^[A-Z][A-Z0-9_]{0,119}$'),'PROTECTION_REFUSED');
    return jsonb_build_object('ok',false,'phase','PARTIAL','publication_request_id',v_request.id,
      'work_event_id',v_proof#>'{eligible_claim,work_event_id}','code',v_refusal,'completed',false,'retryable',true);
  end;
  v_response:=jsonb_build_object('ok',true,'phase','ROUND_COMPLETED','publication_request_id',v_request.id,
    'request_sha256',v_stage->>'request_sha256','work_event_id',v_proof#>'{eligible_claim,work_event_id}',
    'native_result',v_result,'whole_command_atomic',false);
  perform public._audit_insert('weekly_source_bulk_signed_command',v_object,'WEEKLY_SOURCE_BULK_SIGNED_ROUND_COMPLETED',
    null,v_response,'Protected from the signed MyTMS submission',v_actor);
  return v_response;
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_exceptional_pay_prepare_family_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_allowed_keys constant text[]:=array[
    'actor_user_id','source_cycle_id','candidate_id','client_id','contract_id',
    'week_ending_date','work_event_id','work_date','start_at_local',
    'end_at_local','break_minutes','evidence_timesheet_id','reason',
    'idempotency_key'
  ];
  v_actor_user_id uuid;
  v_source_cycle_id uuid;
  v_candidate_id uuid;
  v_client_id uuid;
  v_contract_id uuid;
  v_week_ending_date date;
  v_week_start_date date;
  v_work_event_id uuid;
  v_work_date date;
  v_start_at_local timestamp without time zone;
  v_end_at_local timestamp without time zone;
  v_break_minutes integer;
  v_evidence_timesheet_id uuid;
  v_reason text;
  v_idempotency_key text;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_contract public.contracts%rowtype;
  v_contract_week public.contract_weeks%rowtype;
  v_root public.timesheets%rowtype;
  v_evidence public.timesheets%rowtype;
  v_signed_evidence jsonb;
  v_candidate public.candidates%rowtype;
  v_client public.clients%rowtype;
  v_policy jsonb;
  v_source_mode text; v_activated_source_mode text;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_occupant_norm text;
  v_hospital_norm text;
  v_ward_norm text;
  v_role_norm text;
  v_booking_material text;
  v_booking_id text;
  v_work_event_hash bytea;
  v_first_evidence_hash bytea;
  v_request_hash bytea;
  v_before_hash bytea;
  v_created_root boolean:=false;
  v_created_family boolean:=false;
  v_created_event boolean:=false;
  v_replay boolean:=false;
  v_request_kind text:='APPROVE';
  v_lock_result jsonb;
  v_family_identity jsonb;
  v_known_root_timesheet_id uuid;
  v_saved_route jsonb;
  v_lock_group uuid;
begin
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,v_allowed_keys)
     or not (p_request ?& array[
       'actor_user_id','source_cycle_id','candidate_id','client_id','contract_id',
       'week_ending_date','work_date','start_at_local','end_at_local',
       'break_minutes','reason','idempotency_key'
     ]) then
    raise exception 'WEEKLY_PROTECTED_FAMILY_REQUEST_INVALID' using errcode='22023';
  end if;

  begin
    v_actor_user_id:=(p_request->>'actor_user_id')::uuid;
    v_source_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_candidate_id:=(p_request->>'candidate_id')::uuid;
    v_client_id:=(p_request->>'client_id')::uuid;
    v_contract_id:=(p_request->>'contract_id')::uuid;
    v_week_ending_date:=(p_request->>'week_ending_date')::date;
    v_work_event_id:=nullif(p_request->>'work_event_id','')::uuid;
    v_work_date:=(p_request->>'work_date')::date;
    v_start_at_local:=(p_request->>'start_at_local')::timestamp without time zone;
    v_end_at_local:=(p_request->>'end_at_local')::timestamp without time zone;
    v_break_minutes:=(p_request->>'break_minutes')::integer;
    v_evidence_timesheet_id:=nullif(p_request->>'evidence_timesheet_id','')::uuid;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_FAMILY_REQUEST_INVALID' using errcode='22023';
  end;
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_week_start_date:=v_week_ending_date-6;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PREPARE_FAMILY_REQUEST_V1',p_request
  );

  if v_break_minutes is null or v_break_minutes<0
     or v_end_at_local<=v_start_at_local
     or v_break_minutes>=extract(epoch from (v_end_at_local-v_start_at_local))/60
     or v_work_date<>v_start_at_local::date
     or v_work_date>(pg_catalog.clock_timestamp() at time zone 'Europe/London')::date
     or v_work_date not between v_week_start_date and v_week_ending_date
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_idempotency_key) not between 16 and 200 then
    raise exception 'WEEKLY_PROTECTED_FAMILY_REQUEST_INVALID' using errcode='22023';
  end if;

  v_saved_route:=private.weekly_source_protected_saved_prepare_route_v1(p_request,
    'WEEKLY_PROTECTED_PREPARE_FAMILY_REQUEST_V1','APPROVE');
  if v_saved_route is not null then return v_saved_route; end if;
  perform private.weekly_source_pay_query_admit_v2();
  -- Review F1 and F4. After query admission, the I-1 lock set precedes the
  -- existing business locks this owner
  -- takes: no row lock, no FOR UPDATE and no other advisory key before it,
  -- because every installed rotation owner takes the family advisory key and
  -- the family rows before anything else (core 08082026_2035_...:126-131,
  -- legacy 16122025_...:844-849, confirmed route :2374-2376).  This owner
  -- previously locked the orchestration run, the cycle, the Contract and the
  -- Contract Week first and asked for the family keys afterwards, which is a
  -- proven deadlock (reproductions D1b and D2).  The root is discovered with a
  -- PLAIN read from the request's Contract and week.
  select contract_week.timesheet_id into v_known_root_timesheet_id
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_contract_id
    and contract_week.week_ending_date=v_week_ending_date
    and contract_week.additional_seq=0;

  if v_known_root_timesheet_id is not null then
    v_lock_result:=private.weekly_source_lock_family_rows_v1(
      array[v_known_root_timesheet_id]::uuid[],v_candidate_id
    );
    if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
      raise exception '%',v_lock_result->>'code'
        using errcode='55000',detail=v_lock_result::text;
    end if;
  end if;

  -- Serialize the global idempotency namespace before looking up the run.
  -- Without this lock, two first attempts can both observe no row and the
  -- loser receives a raw unique violation rather than an exact replay.  It is
  -- a Weekly-Source-private key that no rotation owner takes, and it is now
  -- requested after the family keys.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly-exceptional-orchestration|'||v_idempotency_key,0
  ));

  -- A replay is recognized before any mutable work, but every immutable scope
  -- fact is still compared below.  A reused key can never name another family.
  select run.* into v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.idempotency_key=v_idempotency_key
  for update;
  if found then
    v_replay:=true;
  end if;

  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_source_cycle_id);
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle
  where cycle.id=v_source_cycle_id
  for update;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id
    and source_group.active
  for share;

  perform private.weekly_source_office_authority_v1(
    v_actor_user_id,'APPROVE_PROTECTED_PAY',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );

  -- The source cycle records when Office discovered or is reconciling the
  -- protected item.  It is deliberately not required to be the work week:
  -- a missing or queried historic shift can remain protected for later cycles.
  if not exists(
       select 1 from public.weekly_source_group_clients membership
       where membership.source_group_id=v_group.id
         and membership.client_id=v_client_id
         and v_cycle.finalisation_week_ending between membership.valid_from
           and coalesce(membership.valid_to,'infinity'::date)
     ) then
    raise exception 'WEEKLY_PROTECTED_FAMILY_SCOPE_INVALID' using errcode='55000';
  end if;

  select contract.* into strict v_contract
  from public.contracts contract
  where contract.id=v_contract_id
  for update;
  if v_contract.candidate_id is distinct from v_candidate_id
     or v_contract.client_id is distinct from v_client_id
     or v_work_date not between v_contract.start_date and v_contract.end_date
     or v_contract.week_ending_weekday_snapshot not between 0 and 6
     or v_week_ending_date<>v_work_date+
       ((v_contract.week_ending_weekday_snapshot-
         extract(dow from v_work_date)::integer+7)%7) then
    raise exception 'WEEKLY_PROTECTED_CONTRACT_SCOPE_INVALID' using errcode='55000';
  end if;

  v_policy:=private._weekly_source_effective_policy_v1(
    v_client_id,v_contract_id,v_work_date
  );
  v_activated_source_mode:=private.weekly_source_protected_non_self_bill_mode_v1(v_client_id,v_contract_id,v_work_date,v_cycle.id);
  v_source_mode:=coalesce(v_policy->>'c1_source_mode',v_activated_source_mode);
  if v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or (coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true and v_activated_source_mode is null)
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_PROTECTED_POLICY_INVALID' using errcode='55000';
  end if;

  select candidate.* into strict v_candidate
  from public.candidates candidate where candidate.id=v_candidate_id;
  select client.* into strict v_client
  from public.clients client where client.id=v_client_id;

  -- G6-9 / WB-016.  Note on the Candidate serial gate (proof/32 section 6
  -- step 1): preparing the protected-pay family is not one of the four pinned
  -- Weekly Source job types, so this owner does not take the gate; the
  -- first-authorisation, publication and release owners do, through interface
  -- I-1.  It does take the full rotation lock set below (proof/34 rules 1, 6
  -- and 11), and adds no lock of its own on any Banking Pay table.

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'WEEKLY_SOURCE_BASE_WEEK|'||v_contract_id::text||'|'||v_week_ending_date::text,0
  ));
  insert into public.contract_weeks(
    contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id,is_adjustment,created_at,updated_at
  ) values (
    v_contract_id,v_week_ending_date,0,'SUBMITTED'::public.contract_week_status_enum,
    'MANUAL'::public.submission_mode_enum,null,false,
    pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()
  ) on conflict (contract_id,week_ending_date,additional_seq) do nothing;
  select contract_week.* into strict v_contract_week
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_contract_id
    and contract_week.week_ending_date=v_week_ending_date
    and contract_week.additional_seq=0
  for update;
  if v_contract_week.is_adjustment
     or v_contract_week.status='CANCELLED'::public.contract_week_status_enum then
    raise exception 'WEEKLY_PROTECTED_BASE_WEEK_INVALID' using errcode='55000';
  end if;

  -- Review G1.  Under the locks the Contract Week must still name the root
  -- whose family this transaction locked FIRST - including the null to non-null
  -- case, where the week gained a root between the plain read and here.  The
  -- earlier form guarded this with "v_known_root_timesheet_id is not null", so
  -- that case fell through to "select timesheet ... for update" before the
  -- family advisory keys, which is the reverse of every installed rotation
  -- owner and a proven deadlock.  This is the ensure owner's own unconditional
  -- check, in the same place relative to the locked read.
  if v_contract_week.timesheet_id is distinct from v_known_root_timesheet_id then
    raise exception 'WEEKLY_SOURCE_BASE_WEEK_ROOT_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'expected_root_timesheet_id',v_known_root_timesheet_id,
          'observed_root_timesheet_id',v_contract_week.timesheet_id
        )::text;
  end if;

  if v_contract_week.timesheet_id is null then
    if v_contract_week.status in (
      'AUTHORISED'::public.contract_week_status_enum,
      'INVOICED'::public.contract_week_status_enum,
      'CANCELLED'::public.contract_week_status_enum
    ) then
      raise exception 'WEEKLY_PROTECTED_FINAL_WEEK_TIMESHEET_MISSING' using errcode='55000';
    end if;
    v_occupant_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_candidate.tms_ref),''),
      nullif(pg_catalog.btrim(v_candidate.display_name),''),v_candidate.id::text
    ));
    v_hospital_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.display_site),''),
      nullif(pg_catalog.btrim(v_client.name),''),v_client.id::text
    ));
    v_ward_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.ward_hint),''),'contract'
    ));
    v_role_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.role),''),'weekly'
    ));
    v_booking_material:='weekly-source|'||v_contract_id::text||'|'||v_week_ending_date::text;
    v_booking_id:='bk_'||pg_catalog.substr(pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(v_booking_material,'UTF8'),'sha256'),'hex'
    ),1,24);
    -- A minted booking id must not collide with an existing family, and must
    -- not differ from an existing one by surrounding whitespace only: the
    -- confirmed rotation route serialises on the trimmed key while family
    -- membership is by the raw value, so such a pair is an ambiguous family.
    if exists(
      select 1 from public.timesheets existing
      where (existing.booking_id=v_booking_id and existing.is_current)
         or pg_catalog.btrim(existing.booking_id)=v_booking_id
    ) then
      raise exception 'WEEKLY_SOURCE_BOOKING_ID_COLLISION' using errcode='55000';
    end if;
    insert into public.timesheets(
      booking_id,version,is_current,status,sheet_scope,submission_mode,line_type,
      occupant_key_norm,hospital_norm,ward_norm,job_title_norm,shift_label_norm,
      week_ending_date,contract_id,actual_schedule_json,qr_payload_json,
      is_adjustment,created_at,updated_at
    ) values (
      v_booking_id,1,true,'RECEIVED'::public.timesheet_status_enum,
      'WEEKLY'::public.timesheet_scope_enum,'MANUAL'::public.submission_mode_enum,
      'HOURS'::public.timesheet_line_type_enum,v_occupant_norm,v_hospital_norm,
      v_ward_norm,v_role_norm,'weekly-0',v_week_ending_date,v_contract_id,
      '[]'::jsonb,'{}'::jsonb,false,
      pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()
    ) returning * into v_root;
    v_created_root:=true;
    update public.contract_weeks
    set timesheet_id=v_root.timesheet_id,
        status='SUBMITTED'::public.contract_week_status_enum,
        updated_at=pg_catalog.statement_timestamp()
    where id=v_contract_week.id
    returning * into v_contract_week;
  else
    select timesheet.* into strict v_root
    from public.timesheets timesheet
    where timesheet.timesheet_id=v_contract_week.timesheet_id
    for update;
  end if;

  -- G6-9 / proof/34 section 5 step 2 and rule 6.  A stored contract-week
  -- Timesheet id, or a freshly minted one, is only a lookup key: take the
  -- deadlock-free rotation lock set (trimmed key, raw key when different, raw
  -- booking family rows FOR UPDATE) and re-resolve the canonical current
  -- version through the installed Workbench authority before trusting it.
  -- For an existing root the lock set was already taken, before every other
  -- lock, so this call is re-entrant and re-resolves under the locks.  For a
  -- root this transaction has just minted, no other session can know the
  -- booking id yet, so taking the family keys here cannot join a cycle.
  v_lock_result:=private.weekly_source_lock_family_rows_v1(
    array[v_root.timesheet_id]::uuid[],v_candidate_id
  );
  if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
    raise exception '%',v_lock_result->>'code'
      using errcode='55000',detail=v_lock_result::text;
  end if;
  v_family_identity:=v_lock_result->'families'->0;

  -- The root this owner ends up holding must still be the one whose family was
  -- locked first, unless this transaction minted it itself.
  if not v_created_root
     and v_root.timesheet_id is distinct from v_known_root_timesheet_id then
    raise exception 'WEEKLY_SOURCE_BASE_WEEK_ROOT_CHANGED_DURING_LOCK'
      using errcode='40001';
  end if;

  -- proof/34 section 5 step 3: a changed current id makes the request stale.
  -- The older id is never used and nothing is written.
  if coalesce((v_family_identity->>'requested_is_canonical')::boolean,false) is not true
     or coalesce((v_family_identity->>'family_is_current')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION'
      using errcode='55000',detail=v_family_identity::text;
  end if;

  -- Re-read the root under the lock before any fact derived from it is frozen.
  select timesheet.* into strict v_root
  from public.timesheets timesheet
  where timesheet.timesheet_id=v_root.timesheet_id;
  if v_root.booking_id is distinct from (v_family_identity->>'family_booking_id')
     or v_root.version is distinct from (v_family_identity->>'canonical_version')::integer then
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',detail=v_family_identity::text;
  end if;

  if v_root.contract_id is distinct from v_contract_id
     or v_root.week_ending_date is distinct from v_week_ending_date
     or v_root.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum
     or v_root.line_type<>'HOURS'::public.timesheet_line_type_enum
     or v_root.is_adjustment
     or not v_root.is_current
     or v_root.revoked_at is not null
     or v_root.archived_at_utc is not null then
    raise exception 'WEEKLY_PROTECTED_ROOT_INVALID' using errcode='55000';
  end if;

  if v_evidence_timesheet_id is not null then
    v_signed_evidence:=private.weekly_exceptional_candidate_signed_evidence_v1(
      v_evidence_timesheet_id
    );
    if (v_signed_evidence->>'contract_id')::uuid is distinct from v_contract_id
       or (v_signed_evidence->>'week_ending_date')::date is distinct from v_week_ending_date then
      raise exception 'WEEKLY_PROTECTED_EVIDENCE_INVALID' using errcode='55000';
    end if;
  end if;

  if v_work_event_id is not null then
    select event.id into strict v_work_event_id
    from public.weekly_work_events event
    where event.id=v_work_event_id
      and event.candidate_id=v_candidate_id
      and event.client_id=v_client_id
      and event.work_date=v_work_date
    for share;
  else
    v_work_event_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_OFFICE_PROTECTED_WORK_EVENT_V1',
      pg_catalog.jsonb_build_object(
        'agency_id',v_group.agency_id,'candidate_id',v_candidate_id,
        'client_id',v_client_id,'work_date',v_work_date,
        'start_at_local',v_start_at_local,'end_at_local',v_end_at_local,
        'break_minutes',v_break_minutes
      )
    );
    -- The new-shift editor cannot silently create another payable identity for
    -- work already recorded on this day. Exact replay keeps its original hash;
    -- changed hours must name the existing shift and use its protected owner.
    if not v_replay and exists(
      select 1 from public.weekly_work_events existing
      where existing.candidate_id=v_candidate_id
        and existing.work_date between v_work_date-1 and v_work_date+1
        and existing.durable_identity_hash<>v_work_event_hash
        and (
          (existing.work_date=v_work_date and existing.client_id=v_client_id
            and existing.first_source_group_id=v_group.id
            and existing.identity_kind='OFFICE_PROTECTED_SHIFT'
            and not exists(select 1 from public.weekly_exceptional_pay_family_events recorded
              where recorded.durable_work_event_id=existing.id))
          or
          private.weekly_source_work_event_schedule_compatible_v1(existing.id,v_start_at_local,v_end_at_local)
          or exists(select 1 from public.weekly_exceptional_pay_family_events protected
            where protected.durable_work_event_id=existing.id
              and protected.start_at_local<v_end_at_local and v_start_at_local<protected.end_at_local)
          or exists(select 1 from public.weekly_discrepancy_incidents incident
            join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
            where incident.work_event_id=existing.id
              and comparison.candidate_start_at_local<v_end_at_local
              and v_start_at_local<comparison.candidate_end_at_local)
        )
    ) then
      raise exception 'WEEKLY_PROTECTED_EXISTING_SHIFT_SELECTION_REQUIRED' using errcode='55000';
    end if;
    insert into public.weekly_work_events(
      candidate_id,client_id,work_date,identity_kind,profile_external_key,
      durable_identity_hash,first_source_group_id,source_format_profile_id
    ) values (
      v_candidate_id,v_client_id,v_work_date,'OFFICE_PROTECTED_SHIFT',null,
      v_work_event_hash,v_group.id,null
    ) on conflict (durable_identity_hash) do nothing
    returning id into v_work_event_id;
    if found then
      v_created_event:=true;
    else
      select event.id into strict v_work_event_id
      from public.weekly_work_events event
      where event.durable_identity_hash=v_work_event_hash
        and event.candidate_id=v_candidate_id
        and event.client_id=v_client_id
        and event.work_date=v_work_date
        and event.identity_kind='OFFICE_PROTECTED_SHIFT';
    end if;
  end if;

  v_first_evidence_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_FIRST_EVIDENCE_V1',
    pg_catalog.jsonb_build_object(
      'agency_id',v_group.agency_id,'candidate_id',v_candidate_id,
      'client_id',v_client_id,'contract_id',v_contract_id,
      'week_ending_date',v_week_ending_date,'root_timesheet_id',v_root.timesheet_id,
      'evidence_timesheet_id',v_evidence_timesheet_id,'work_event_id',v_work_event_id,
      'work_date',v_work_date,'start_at_local',v_start_at_local,
      'end_at_local',v_end_at_local,'break_minutes',v_break_minutes
    )
  );

  select family.* into v_family
  from public.weekly_exceptional_pay_target_families family
  where family.agency_id=v_group.agency_id
    and family.candidate_id=v_candidate_id
    and family.contract_id=v_contract_id
    and family.week_ending_date=v_week_ending_date
  for update;
  if found then
    if v_family.root_timesheet_id is distinct from v_root.timesheet_id
       or v_family.week_start_date is distinct from v_week_start_date
       or v_family.agency_id is distinct from v_group.agency_id
       or v_family.candidate_id is distinct from v_candidate_id
       or v_family.contract_id is distinct from v_contract_id
       or (v_replay and v_run.family_id is distinct from v_family.id) then
      raise exception 'WEEKLY_PROTECTED_FAMILY_SCOPE_INVALID' using errcode='55000';
    end if;
    -- One family is the complete Candidate + Contract + week entitlement.
    -- A later protected shift or an amended protected schedule is another
    -- immutable orchestration run against that same family, never a second
    -- public Timesheet and never a duplicate family.
    if v_replay then
      if v_run.request_kind not in ('APPROVE','AMEND') then
        raise exception 'WEEKLY_PROTECTED_REPLAY_SCOPE_INVALID' using errcode='55000';
      end if;
      v_request_kind:=v_run.request_kind;
    else
      if v_family.c1_publication_state in ('PENDING','PUBLISHING') then
        raise exception 'WEEKLY_PROTECTED_PUBLICATION_BUSY' using errcode='55000';
      end if;
      -- Preparing a family is not a published pay decision. A failed first
      -- attempt can leave this identity present with no generation to amend.
      v_request_kind:=case when v_family.current_generation_id is null
        then 'APPROVE' else 'AMEND' end;
    end if;
  else
    if v_replay then
      raise exception 'WEEKLY_PROTECTED_REPLAY_SCOPE_INVALID' using errcode='55000';
    end if;
    insert into public.weekly_exceptional_pay_target_families(
      agency_id,candidate_id,contract_id,week_start_date,week_ending_date,
      root_timesheet_id,ownership_state,first_signed_evidence_fingerprint,
      current_lifecycle_state,c1_publication_state,creation_idempotency_key
    ) values (
      v_group.agency_id,v_candidate_id,v_contract_id,v_week_start_date,
      v_week_ending_date,v_root.timesheet_id,'TARGET_MANAGED',v_first_evidence_hash,
      'PENDING_APPROVAL','NONE',v_idempotency_key
    ) returning * into v_family;
    v_created_family:=true;
    v_request_kind:='APPROVE';
  end if;

  v_before_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PREPARE_BEFORE_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'bound_version',v_family.bound_version,
      'root_timesheet_id',v_root.timesheet_id,
      'root_version',v_root.version,'contract_week_id',v_contract_week.id,
      'current_generation_id',v_family.current_generation_id,
      'current_generation_number',v_family.current_generation_number,
      'family_bound_version',v_family.bound_version,
      'work_event_id',v_work_event_id,
      'work_date',v_work_date,'start_at_local',v_start_at_local,
      'end_at_local',v_end_at_local,'break_minutes',v_break_minutes,
      'evidence_timesheet_id',v_evidence_timesheet_id,
      'request_kind',v_request_kind
    )
  );
  if not v_replay then
    insert into public.weekly_exceptional_orchestration_runs(
      family_id,request_kind,idempotency_key,requested_by_user_id,state,
      request_fingerprint,before_state_fingerprint
    ) values (
      v_family.id,v_request_kind,v_idempotency_key,v_actor_user_id,'RUNNING',
      v_request_hash,v_before_hash
    ) returning * into v_run;
  elsif v_run.request_kind<>v_request_kind
     or v_run.requested_by_user_id is distinct from v_actor_user_id
     or v_run.request_fingerprint is distinct from v_request_hash then
    raise exception 'WEEKLY_PROTECTED_REPLAY_SCOPE_INVALID' using errcode='55000';
  end if;

  select financial.* into v_fin
  from public.timesheets_financials financial
  where financial.timesheet_id=v_root.timesheet_id
    and financial.is_current
  for share;

  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,
    object_type,object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor_user_id,actor.display_name,actor.role,
    'weekly_exceptional_pay_target_families',v_family.id::text,
    case when v_created_family then 'WEEKLY_PROTECTED_FAMILY_PREPARED'
      else 'WEEKLY_PROTECTED_FAMILY_PREPARE_REPLAY' end,
    null,pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'source_cycle_id',v_source_cycle_id,
      'work_event_id',v_work_event_id,'root_timesheet_id',v_root.timesheet_id,
      'contract_week_id',v_contract_week.id,'candidate_id',v_candidate_id,
      'client_id',v_client_id,'contract_id',v_contract_id,
      'week_ending_date',v_week_ending_date,'source_mode',v_source_mode,
      'request_kind',v_request_kind,
      'created_root',v_created_root,'created_work_event',v_created_event,
      'requires_zero_financial',v_fin.id is null
    ),v_reason
  from public.tms_users actor where actor.id=v_actor_user_id;

  return pg_catalog.jsonb_build_object(
    'family_id',v_family.id,'orchestration_run_id',v_run.id,
    'source_cycle_id',v_source_cycle_id,'source_group_id',v_group.id,
    'agency_id',v_group.agency_id,'candidate_id',v_candidate_id,
    'client_id',v_client_id,'contract_id',v_contract_id,
    'contract_week_id',v_contract_week.id,'root_timesheet_id',v_root.timesheet_id,
    'work_event_id',v_work_event_id,'week_start_date',v_week_start_date,
    'week_ending_date',v_week_ending_date,'source_mode',v_source_mode,
    'root_version',v_root.version,'financial_row_id',v_fin.id,
    'requires_zero_financial',v_fin.id is null,
    'created_root',v_created_root,'created_family',v_created_family,
    'created_work_event',v_created_event,'idempotent_replay',v_replay,
    'family_bound_version',v_family.bound_version,'request_kind',v_request_kind,
    'run_state',v_run.state
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_FAMILY_SCOPE_INVALID' using errcode='55000';
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_exceptional_pay_prepare_action_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_keys constant text[]:=array[
    'schema_version','actor_user_id','family_id','source_cycle_id','work_event_id',
    'action','expected_family_bound_version','protected_schedule','reason',
    'idempotency_key'
  ];
  v_schedule_keys constant text[]:=array[
    'work_date','start_at_local','end_at_local','break_minutes'
  ];
  v_actor uuid;
  v_family_id uuid;
  v_cycle_id uuid;
  v_event_id uuid;
  v_expected_version bigint;
  v_action text;
  v_reason text;
  v_key text;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_lock_family jsonb; v_lock_group uuid;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_contract public.contracts%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_latest_event public.weekly_exceptional_pay_family_events%rowtype;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_request_hash bytea;
  v_before bytea;
  v_source_mode text; v_activated_source_mode text;
  v_policy jsonb;
  v_schedule jsonb;
  v_work_date date;
  v_start timestamp without time zone;
  v_end timestamp without time zone;
  v_break integer;
  v_replay boolean:=false;
  v_review_source jsonb;
  v_saved_route jsonb;
begin
  if pg_catalog.jsonb_typeof(p_request)<>'object'
     or not private.weekly_exceptional_json_keys_exact_v1(p_request,
       v_keys||array['expected_source_hash','expected_source_revision'])
     or not (p_request ?& v_keys)
     or p_request->>'schema_version'<>'WEEKLY_PROTECTED_ACTION_PREPARE_V1' then
    raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_family_id:=(p_request->>'family_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_event_id:=(p_request->>'work_event_id')::uuid;
    v_expected_version:=(p_request->>'expected_family_bound_version')::bigint;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
  end;
  v_action:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'action','')));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PREPARE_ACTION_REQUEST_V1',p_request
  );
  if v_action not in ('AMEND','WITHDRAW','WAIT','RECONCILE','RECORD_NOT_WORKED')
     or v_expected_version<1
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_key) not between 16 and 200 then
    raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
  end if;

  v_saved_route:=private.weekly_source_protected_saved_prepare_route_v1(p_request,
    'WEEKLY_PROTECTED_PREPARE_ACTION_REQUEST_V1',v_action);
  if v_saved_route is not null then return v_saved_route; end if;
  perform private.weekly_source_pay_query_admit_v2();
  v_lock_family:=private.weekly_source_protected_family_lock_v1(v_family_id);
  -- Share the same global idempotency lock as first approval.  Concurrent
  -- first attempts for one key therefore become one write plus one exact
  -- replay instead of leaking the ledger's unique constraint.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly-exceptional-orchestration|'||v_key,0
  ));

  select run.* into v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.idempotency_key=v_key for update;
  v_replay:=found;

  select family.* into strict v_family
  from public.weekly_exceptional_pay_target_families family
  where family.id=v_family_id for update;
  if (v_family.root_timesheet_id::text,v_family.candidate_id::text,v_family.contract_id::text,v_family.week_ending_date::text)
    is distinct from (v_lock_family->>'root_timesheet_id',v_lock_family->>'candidate_id',
      v_lock_family->>'contract_id',v_lock_family->>'week_ending_date') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_cycle_id);
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle where cycle.id=v_cycle_id for share;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id and source_group.active for share;
  select contract.* into strict v_contract
  from public.contracts contract where contract.id=v_family.contract_id for share;
  select work_event.* into strict v_event
  from public.weekly_work_events work_event
  where work_event.id=v_event_id
    and work_event.candidate_id=v_family.candidate_id
    and work_event.client_id=v_contract.client_id
    and work_event.work_date between v_family.week_start_date and v_family.week_ending_date
  for share;
  select family_event.* into strict v_latest_event
  from public.weekly_exceptional_pay_family_events family_event
  where family_event.family_id=v_family.id
    and family_event.durable_work_event_id=v_event.id
  order by family_event.event_sequence desc
  limit 1
  for share;

  if v_action='AMEND' then
    if pg_catalog.jsonb_typeof(p_request->'protected_schedule')<>'object'
       or not private.weekly_exceptional_json_keys_exact_v1(
         p_request->'protected_schedule',v_schedule_keys
       )
       or not ((p_request->'protected_schedule') ?& v_schedule_keys) then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_INVALID' using errcode='22023';
    end if;
    v_schedule:=p_request->'protected_schedule';
    begin
      v_work_date:=(v_schedule->>'work_date')::date;
      v_start:=(v_schedule->>'start_at_local')::timestamp without time zone;
      v_end:=(v_schedule->>'end_at_local')::timestamp without time zone;
      v_break:=(v_schedule->>'break_minutes')::integer;
    exception when others then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_INVALID' using errcode='22023';
    end;
    if v_work_date<>v_event.work_date or v_start::date<>v_work_date
       or v_end<=v_start or v_break<0
       or v_break>=extract(epoch from (v_end-v_start))/60 then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_INVALID' using errcode='22023';
    end if;
  else
    if p_request->'protected_schedule'<>'null'::jsonb then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_FORBIDDEN' using errcode='22023';
    end if;
    v_schedule:=pg_catalog.jsonb_build_object(
      'work_date',v_latest_event.work_date,
      'start_at_local',v_latest_event.start_at_local,
      'end_at_local',v_latest_event.end_at_local,
      'break_minutes',v_latest_event.break_minutes
    );
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'APPROVE_PROTECTED_PAY',v_group.id,v_contract.client_id,v_cycle.finalisation_week_ending
  );
  v_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_event.work_date
  );
  v_activated_source_mode:=private.weekly_source_protected_non_self_bill_mode_v1(v_contract.client_id,v_contract.id,v_event.work_date,v_cycle.id);
  v_source_mode:=coalesce(v_policy->>'c1_source_mode',v_activated_source_mode);
  if v_family.agency_id is distinct from v_group.agency_id
     or v_family.root_timesheet_id is null
     or v_family.ownership_state<>'TARGET_MANAGED'
     or v_contract.candidate_id is distinct from v_family.candidate_id
     or not exists(
       select 1 from public.weekly_source_group_clients membership
       where membership.source_group_id=v_group.id
         and membership.client_id=v_contract.client_id
         and v_cycle.finalisation_week_ending between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)
     )
     or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or (coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true and v_activated_source_mode is null)
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY')
     or v_latest_event.id is null then
    raise exception 'WEEKLY_PROTECTED_ACTION_SCOPE_INVALID' using errcode='55000';
  end if;

  if v_replay then
    if v_run.family_id is distinct from v_family.id
       or v_run.request_kind is distinct from v_action
       or v_run.requested_by_user_id is distinct from v_actor
       or v_run.request_fingerprint is distinct from v_request_hash then
      raise exception 'WEEKLY_PROTECTED_ACTION_IDEMPOTENCY_COLLISION' using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'outcome','PREPARED','family_id',v_family.id,
      'orchestration_run_id',v_run.id,'source_cycle_id',v_cycle.id,
      'source_group_id',v_group.id,'agency_id',v_group.agency_id,
      'candidate_id',v_family.candidate_id,'client_id',v_contract.client_id,
      'contract_id',v_family.contract_id,'root_timesheet_id',v_family.root_timesheet_id,
      'work_event_id',v_event.id,'week_start_date',v_family.week_start_date,
      'week_ending_date',v_family.week_ending_date,'source_mode',v_source_mode,
      'family_bound_version',v_expected_version,'request_kind',v_action,
      'protected_schedule',v_schedule,'run_state',v_run.state,
      'idempotent_replay',true
    );
  end if;

  if v_family.current_generation_id is null
     or v_family.current_lifecycle_state not in (
       'PROTECTED','WAITING_SOURCE','READY_TO_RECONCILE','RECONCILED','NOT_WORKED','ACTION_REQUIRED'
     )
     or v_family.c1_publication_state in ('PENDING','PUBLISHING')
     or v_family.bound_version<>v_expected_version then
    -- A business-version refusal is not a retryable PostgreSQL serialization
    -- failure. PostgREST 14 retries 40001, so return the same refusal as HTTP
    -- conflict without repeating the request or creating an orchestration run.
    raise exception 'WEEKLY_PROTECTED_ACTION_STALE' using errcode='PT409';
  end if;

  -- A new Office review is bound to the exact final-source observation shown.
  -- Refuse before creating a run; old callers and exact saved replays retain
  -- their original request shape and fingerprint.
  if p_request ? 'expected_source_hash' or p_request ? 'expected_source_revision' then
    if v_action<>'RECONCILE'
      or coalesce(p_request->>'expected_source_hash','') !~ '^[0-9a-f]{64}$'
      or coalesce(p_request->>'expected_source_revision','') !~ '^[0-9a-f-]{36}$' then
      raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
    end if;
    v_review_source:=private.weekly_source_protected_final_source_context_v1(v_family.id,v_cycle.id,v_event.id);
    if not coalesce((v_review_source->>'source_observed')::boolean,false)
      or v_review_source#>>'{source_proposal,source_hash}' is distinct from p_request->>'expected_source_hash'
      or v_review_source#>>'{source_proposal,source_revision}' is distinct from p_request->>'expected_source_revision' then
      raise exception 'WEEKLY_PROTECTED_REVIEW_SOURCE_CHANGED' using errcode='40001';
    end if;
  end if;

  v_before:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_ACTION_PREPARE_BEFORE_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'family_bound_version',v_family.bound_version,
      'current_generation_id',v_family.current_generation_id,
      'current_generation_number',v_family.current_generation_number,
      'current_target_vector_hash',pg_catalog.encode(v_family.current_complete_target_vector_hash,'hex'),
      'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
      'work_event_id',v_event.id,'action',v_action,'actor_user_id',v_actor,
      'protected_schedule',v_schedule,'reason',v_reason
    )
  );
  insert into public.weekly_exceptional_orchestration_runs(
    family_id,request_kind,idempotency_key,requested_by_user_id,state,
    request_fingerprint,before_state_fingerprint
  ) values (
    v_family.id,v_action,v_key,v_actor,'RUNNING',v_request_hash,v_before
  ) returning * into v_run;
  return pg_catalog.jsonb_build_object(
    'ok',true,'outcome','PREPARED','family_id',v_family.id,
    'orchestration_run_id',v_run.id,'source_cycle_id',v_cycle.id,
    'source_group_id',v_group.id,'agency_id',v_group.agency_id,
    'candidate_id',v_family.candidate_id,'client_id',v_contract.client_id,
    'contract_id',v_family.contract_id,'root_timesheet_id',v_family.root_timesheet_id,
    'work_event_id',v_event.id,'week_start_date',v_family.week_start_date,
    'week_ending_date',v_family.week_ending_date,'source_mode',v_source_mode,
    'family_bound_version',v_family.bound_version,'request_kind',v_action,
    'protected_schedule',v_schedule,'run_state',v_run.state,
    'idempotent_replay',v_replay
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_ACTION_SCOPE_INVALID' using errcode='55000';
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_exceptional_pay_action_context_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_keys constant text[]:=array[
    'schema_version','actor_user_id','family_id','orchestration_run_id',
    'source_cycle_id','work_event_id','protected_schedule','evidence_timesheet_id'
  ];
  v_schedule_keys constant text[]:=array[
    'work_date','start_at_local','end_at_local','break_minutes'
  ];
  v_actor uuid;
  v_family_id uuid;
  v_run_id uuid;
  v_cycle_id uuid;
  v_event_id uuid;
  v_evidence_id uuid;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_lock_family jsonb; v_lock_group uuid;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_contract public.contracts%rowtype;
  v_contract_week public.contract_weeks%rowtype;
  v_root public.timesheets%rowtype;
  -- WP-30 (WP-27 sweep finding N4), standing rule 3.  The expense-authority
  -- selection below decides which SOURCE_EXPENSE authorities belong to this
  -- protected root through the source-row lineage binding, which is a fact
  -- about the Timesheet FAMILY.  Keyed on the physical root id a rotated
  -- family's authorities were SILENTLY DROPPED from the projection rather than
  -- refused — fail open by omission.  EXECUTED on a rotated family: 0
  -- authorities selected by the physical id against 4 by the family.
  v_root_family uuid[];
  v_fin public.timesheets_financials%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_schedule jsonb;
  v_work_date date;
  v_start timestamp without time zone;
  v_end timestamp without time zone;
  v_break integer;
  v_policy jsonb;
  v_root_policy jsonb;
  v_settings jsonb;
  v_source_mode text; v_activated_source_mode text;
  v_source_segments jsonb:='[]'::jsonb;
  v_client_sources jsonb:='[]'::jsonb;
  v_decisions jsonb:='[]'::jsonb;
  v_source_expenses jsonb:='[]'::jsonb;
  v_current_final uuid;
  v_comparison uuid;
  v_signed jsonb;
  v_candidate_submission jsonb;
  v_selected_source_present boolean:=false;
  v_selected_source_minutes integer:=0;
  v_selected_source_revision text;
  v_selected_source_hash text;
  v_source_head_revision uuid;
  v_source_head_count integer:=0;
  v_ambiguous_event_count integer:=0;
  v_fin_hash text;
  v_provider_hash text;
  v_rate_refs jsonb;
  v_component_identity_inventory jsonb;
  v_component_identity_components jsonb;
  v_final_source jsonb;
  v_next_context boolean:=false;
begin
  if pg_catalog.jsonb_typeof(p_request)<>'object'
     or not private.weekly_exceptional_json_keys_exact_v1(p_request,v_keys)
     or not (p_request ?& v_keys)
     or p_request->>'schema_version'<>'WEEKLY_PROTECTED_ACTION_CONTEXT_V1'
     or pg_catalog.jsonb_typeof(p_request->'protected_schedule')<>'object'
     or not private.weekly_exceptional_json_keys_exact_v1(
       p_request->'protected_schedule',v_schedule_keys
     )
     or not ((p_request->'protected_schedule') ?& v_schedule_keys) then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_family_id:=(p_request->>'family_id')::uuid;
    v_run_id:=(p_request->>'orchestration_run_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_event_id:=(p_request->>'work_event_id')::uuid;
    v_evidence_id:=nullif(p_request->>'evidence_timesheet_id','')::uuid;
    v_schedule:=p_request->'protected_schedule';
    v_work_date:=(v_schedule->>'work_date')::date;
    v_start:=(v_schedule->>'start_at_local')::timestamp without time zone;
    v_end:=(v_schedule->>'end_at_local')::timestamp without time zone;
    v_break:=(v_schedule->>'break_minutes')::integer;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_INVALID' using errcode='22023';
  end;
  if v_end<=v_start or v_start::date<>v_work_date or v_break<0
     or v_break>=extract(epoch from (v_end-v_start))/60 then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_INVALID' using errcode='22023';
  end if;

  -- Fresh context has no immutable decision receipt exemption. Admission
  -- precedes its first family/business lock and is reentrant for an owner.
  perform private.weekly_source_pay_query_admit_v2();

  v_lock_family:=private.weekly_source_protected_family_lock_v1(v_family_id);
  select family.* into strict v_family
  from public.weekly_exceptional_pay_target_families family
  where family.id=v_family_id for share;
  select run.* into strict v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.id=v_run_id and run.family_id=v_family.id for share;
  if (v_family.root_timesheet_id::text,v_family.candidate_id::text,v_family.contract_id::text,v_family.week_ending_date::text)
    is distinct from (v_lock_family->>'root_timesheet_id',v_lock_family->>'candidate_id',
      v_lock_family->>'contract_id',v_lock_family->>'week_ending_date') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_cycle_id);
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle where cycle.id=v_cycle_id for share;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id and source_group.active for share;
  select contract.* into strict v_contract
  from public.contracts contract where contract.id=v_family.contract_id for share;
  select contract_week.* into strict v_contract_week
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_family.contract_id
    and contract_week.week_ending_date=v_family.week_ending_date
    and contract_week.additional_seq=0 for share;
  -- WP-30, standing rule 3.  The family is resolved and its rows are locked
  -- BEFORE the family-scoped state below is read, in the SAME mode and the same
  -- timesheet_id order the installed code here already uses (`for share`), and
  -- before the root's own `for share` so no new lock ordering is introduced.
  v_next_context:=(select active_owner from private.bpay_next_module_control where id=1)='NEXT'
    and private.bpay_next_protected_owner_route_v1(v_family.id)='NEXT';
  if v_next_context then
    v_root_family:=array[v_family.root_timesheet_id];
  else
    v_root_family:=private.weekly_source_invoice_family_timesheet_ids_v1(v_family.root_timesheet_id);
  end if;
  -- Standing rule 3's fail-closed branch: an explicit cardinality test, never a
  -- `limit`.  This owner already refuses on every other unprovable scope fact.
  if v_root_family is null or pg_catalog.cardinality(v_root_family)=0 then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_FAMILY_UNRESOLVED'
      using errcode='55000';
  end if;
  perform 1 from public.timesheets lock_row
  where lock_row.timesheet_id=any(v_root_family)
  order by lock_row.timesheet_id for share;
  select timesheet.* into strict v_root
  from public.timesheets timesheet
  where timesheet.timesheet_id=v_family.root_timesheet_id for share;
  select financial.* into v_fin
  from public.timesheets_financials financial
  where financial.timesheet_id=v_root.timesheet_id and financial.is_current
  order by financial.computed_at_utc desc nulls last,
           financial.updated_at desc nulls last,financial.id desc limit 1;
  select work_event.* into strict v_event
  from public.weekly_work_events work_event
  where work_event.id=v_event_id
    and work_event.candidate_id=v_family.candidate_id
    and work_event.client_id=v_contract.client_id for share;

  perform private.weekly_source_office_authority_v1(
    v_actor,'APPROVE_PROTECTED_PAY',v_group.id,v_contract.client_id,v_event.work_date
  );
  v_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_event.work_date
  );
  -- The selected shift uses its work-date policy, but the zero-value root
  -- financial is a weekly Timesheet. Its rate-source fingerprint must match
  -- the root prepare owner's week-ending policy exactly.
  v_root_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_family.week_ending_date
  );
  v_settings:=(private._timesheet_settings_authority_frozen_v1(v_root.timesheet_id)->'values')
    -'resolved_at_utc';
  v_activated_source_mode:=private.weekly_source_protected_non_self_bill_mode_v1(v_contract.client_id,v_contract.id,v_event.work_date,v_cycle.id);
  v_source_mode:=coalesce(v_policy->>'c1_source_mode',v_activated_source_mode);
  if v_run.requested_by_user_id is distinct from v_actor
     or v_run.state not in ('RUNNING','COMPLETE')
     or v_run.request_kind not in ('APPROVE','AMEND','WITHDRAW','WAIT','RECONCILE','RECORD_NOT_WORKED')
     or v_family.agency_id is distinct from v_group.agency_id
     or v_contract.candidate_id is distinct from v_family.candidate_id
     or v_contract_week.timesheet_id is distinct from v_root.timesheet_id
     or v_root.contract_id is distinct from v_contract.id
     or (v_next_context and v_root.booking_id is distinct from v_family.root_family_booking_id)
     or v_root.week_ending_date is distinct from v_family.week_ending_date
     or not v_root.is_current or v_root.is_adjustment
     or v_root.revoked_at is not null or v_root.archived_at_utc is not null
     or v_event.work_date<>v_work_date
     or v_work_date not between v_family.week_start_date and v_family.week_ending_date
     or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or (coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true and v_activated_source_mode is null)
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_SCOPE_INVALID' using errcode='55000';
  end if;

  -- Read the same final-source authority shown in the Office review.
  v_final_source:=private.weekly_source_protected_final_source_context_v1(v_family.id,v_cycle.id,v_event.id);
  v_source_segments:=v_final_source->'source_segments';
  v_client_sources:=v_final_source->'client_sources';
  v_current_final:=(v_final_source->>'current_final_revision_id')::uuid;
  v_selected_source_present:=(v_final_source#>>'{source_proposal,source_present}')::boolean;
  v_selected_source_minutes:=(v_final_source#>>'{source_proposal,source_minutes}')::integer;
  v_selected_source_revision:=v_final_source#>>'{source_proposal,source_revision}';
  v_selected_source_hash:=v_final_source#>>'{source_proposal,source_hash}';

  with latest as (
    select family_event.*,
      pg_catalog.row_number() over (
        partition by family_event.durable_work_event_id
        order by family_event.event_sequence desc
      ) as event_rank
    from public.weekly_exceptional_pay_family_events family_event
    where family_event.family_id=v_family.id
  ), decisions as (
    select latest.durable_work_event_id as work_event_id,
      case when latest.durable_work_event_id=v_event.id then case
        when v_run.request_kind in ('APPROVE','AMEND','WAIT') then 'WAIT'
        when v_run.request_kind in ('WITHDRAW','RECONCILE') then 'ACCEPTED_SOURCE'
        else 'NOT_WORKED' end
      else latest.state end as decision_state,
      case when latest.durable_work_event_id=v_event.id
             and v_run.request_kind in ('APPROVE','AMEND','WAIT')
        then v_schedule
        else pg_catalog.jsonb_build_object(
          'work_date',latest.work_date,'start_at_local',latest.start_at_local,
          'end_at_local',latest.end_at_local,'break_minutes',latest.break_minutes
        ) end as fixed_schedule
    from latest where latest.event_rank=1
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'work_event_id',decision.work_event_id,'state',decision.decision_state,
    'fixed_schedule',case when decision.decision_state='WAIT' then pg_catalog.jsonb_build_object(
      'date',decision.fixed_schedule->>'work_date',
      'start',pg_catalog.to_char((decision.fixed_schedule->>'start_at_local')::timestamp,'HH24:MI'),
      'end',pg_catalog.to_char((decision.fixed_schedule->>'end_at_local')::timestamp,'HH24:MI'),
      'break_mins',(decision.fixed_schedule->>'break_minutes')::integer
    ) else null end
  ) order by decision.work_event_id),'[]'::jsonb)
  into v_decisions from decisions decision;
  if not exists(
    select 1 from pg_catalog.jsonb_array_elements(v_decisions) d(value)
    where (d.value->>'work_event_id')::uuid=v_event.id
  ) then
    v_decisions:=v_decisions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'work_event_id',v_event.id,
      'state',case when v_run.request_kind in ('APPROVE','AMEND','WAIT') then 'WAIT'
        when v_run.request_kind in ('WITHDRAW','RECONCILE') then 'ACCEPTED_SOURCE'
        else 'NOT_WORKED' end,
      'fixed_schedule',case when v_run.request_kind in ('APPROVE','AMEND','WAIT')
        then pg_catalog.jsonb_build_object(
          'date',v_work_date,'start',pg_catalog.to_char(v_start,'HH24:MI'),
          'end',pg_catalog.to_char(v_end,'HH24:MI'),'break_mins',v_break
        ) else null end
    ));
  end if;

  if v_run.request_kind='RECORD_NOT_WORKED' and v_selected_source_present then
    raise exception 'WEEKLY_PROTECTED_NOT_WORKED_SOURCE_PRESENT' using errcode='55000';
  end if;

  select comparison.id into v_comparison
  from public.weekly_issue_comparison_revisions comparison
  join public.weekly_discrepancy_incidents incident on incident.id=comparison.incident_id
  where incident.work_event_id=v_event.id and incident.candidate_id=v_family.candidate_id
    and incident.client_id=v_contract.client_id
  order by comparison.created_at_utc desc,comparison.id desc limit 1;

  if v_evidence_id is null then
    select approval.evidence_timesheet_id into v_evidence_id
    from public.weekly_exceptional_payment_approvals approval
    where approval.pay_target_family_id=v_family.id
      and approval.work_event_id=v_event.id
    order by approval.approved_at_utc desc,approval.id desc limit 1;
  end if;
  if v_evidence_id is not null then
    v_signed:=private.weekly_exceptional_candidate_signed_evidence_v1(v_evidence_id);
    v_candidate_submission:=pg_catalog.jsonb_build_object(
      'source_system','CLOUDTMS_CANDIDATE_TIMESHEET',
      'external_identity',v_evidence_id::text,
      'external_revision',v_signed->>'timesheet_version',
      'document_sha256',v_signed->>'signature_sha256',
      'work_date',v_event.work_date,'submitted_by_candidate_id',v_family.candidate_id,
      'submission_id',v_evidence_id,'submitted_at_utc',v_signed->>'signed_at_utc',
      'submitted_minutes',extract(epoch from (v_end-v_start))::integer/60-v_break
    );
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'expense_code','SOURCE_SUPPLIED:'||authority.work_event_id::text,
    'authority_kind','SOURCE_EXPENSE','source_expense_id',authority.id,
    'document_sha256',pg_catalog.encode(authority.authority_hash,'hex'),
    'pay_ex_vat',authority.candidate_reimbursement_ex_vat::text,
    'charge_ex_vat',authority.client_charge_ex_vat::text
  )||case when v_final_source ? 'next_source_segments'
    then pg_catalog.jsonb_build_object('work_event_id',authority.work_event_id,
      'final_revision_id',authority.final_revision_id,
      'source_observation_kind',authority.source_observation_kind) else '{}'::jsonb end
   order by authority.work_event_id),'[]'::jsonb)
  into v_source_expenses
  from (
    select authority.*,
      pg_catalog.row_number() over (
        partition by authority.work_event_id order by source_cycle.finalisation_week_ending desc,
          revision.finalised_at_utc desc,authority.generation desc,authority.id desc
      ) as event_rank
    from public.weekly_expense_authority_generations authority
    join public.weekly_source_final_revisions revision
      on revision.id=authority.final_revision_id and revision.state='CURRENT'
    join public.weekly_source_cycles source_cycle on source_cycle.id=revision.source_cycle_id
    where authority.contract_id=v_family.contract_id and authority.state='CURRENT'
      and source_cycle.source_group_id=v_group.id
      and ((not v_next_context and authority.source_expense_pence>0 and exists(
          select 1 from public.weekly_source_row_timesheet_lineages lineage
          where lineage.work_event_id=authority.work_event_id and lineage.contract_id=authority.contract_id
            and lineage.timesheet_id=any(v_root_family)))
        or (v_next_context and exists(
          select 1 from public.weekly_work_events event where event.id=authority.work_event_id
            and event.candidate_id=v_family.candidate_id and event.client_id=v_contract.client_id
            and event.work_date between v_family.week_start_date and v_family.week_ending_date
        ) and ((authority.source_observation_kind='OMITTED_IN_COMPLETE_COVERAGE' and authority.source_expense_pence=0)
          or exists(
            select 1 from public.weekly_source_row_expense_policy_snapshots expense_snapshot
            join public.weekly_source_row_timesheet_lineages lineage on lineage.row_resolution_id=expense_snapshot.row_resolution_id
            where expense_snapshot.id=authority.row_expense_policy_snapshot_id
              and lineage.family_booking_id=v_family.root_family_booking_id
              and lineage.work_event_id=authority.work_event_id and lineage.candidate_id=v_family.candidate_id
              and lineage.client_id=v_contract.client_id and lineage.contract_id=v_family.contract_id
              and lineage.week_ending_date=v_family.week_ending_date))))
  ) authority where authority.event_rank=1 and authority.source_expense_pence>0;

  v_fin_hash:=case when v_fin.id is null then null else pg_catalog.encode(
    private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_PROTECTED_ROOT_FINANCIAL_V1',pg_catalog.to_jsonb(v_fin)
    ),'hex') end;
  v_provider_hash:=pg_catalog.encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PROVIDER_V1',
    pg_catalog.jsonb_build_object(
      'contract_id',v_contract.id,'pay_method',v_contract.pay_method_snapshot,
      'umbrella_id',pg_catalog.to_jsonb(v_contract)->>'umbrella_id',
      'candidate_id',v_contract.candidate_id
    )
  ),'hex');
  v_rate_refs:=pg_catalog.jsonb_build_object(
    'schema_version','WEEKLY_SOURCE_TARGET_MANAGED_ZERO_RATE_SOURCE_V1',
    'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
    'source_family',v_group.source_family,'source_mode',v_source_mode,
    'source_profile_domain',case when v_source_mode='NHSP_WEEKLY'
      then 'NHSP_TRUST_BACKING_REPORT' else 'ROSTER_FINAL_AUTHORITY' end,
    'target_family_id',v_family.id,'root_timesheet_id',v_root.timesheet_id,
    'effective_policy_sha256',v_root_policy->>'policy_sha256'
  );

  -- Local/common identity admission is independent of Banking work completion.
  -- An already authorised root requires its genuine complete current I1 basis;
  -- an actual unauthorised first Save must not invent that approved basis.
  if v_family.target_domain_version='C1_V1' then
    if v_root.authorised_at_server is not null then
      v_component_identity_inventory:=private.weekly_source_effective_inventory_v1(v_root.timesheet_id);
      if v_component_identity_inventory->>'ok' is distinct from 'true'
         or v_component_identity_inventory#>>'{approval_basis,coverage_complete}' is distinct from 'true'
         or v_component_identity_inventory#>>'{approval_basis,scope,root_timesheet_id}'
              is distinct from v_root.timesheet_id::text
         or jsonb_typeof(v_component_identity_inventory->'components') is distinct from 'array' then
        raise exception 'WEEKLY_PROTECTED_COMPONENT_APPROVED_BASIS_UNAVAILABLE' using errcode='55000'; end if;
      v_component_identity_components:=v_component_identity_inventory->'components';
    else
      if exists(select 1 from public.weekly_source_root_authorisations a
          where a.family_booking_id=v_root.booking_id)
         or exists(select 1 from public.weekly_source_entitlement_heads h
          where h.root_family_booking_id=v_root.booking_id and h.state='COMMITTED_CURRENT') then
        raise exception 'WEEKLY_PROTECTED_COMPONENT_APPROVED_BASIS_UNAVAILABLE' using errcode='55000'; end if;
      v_component_identity_components:='[]'::jsonb;
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'contract','WEEKLY_PROTECTED_ACTION_CONTEXT_V1',
    'action',v_run.request_kind,'family_id',v_family.id,
    'orchestration_run_id',v_run.id,'family_bound_version',v_family.bound_version,
    'current_target_vector_sha256',case
      when v_family.current_complete_target_vector_hash is null then null
      else pg_catalog.encode(v_family.current_complete_target_vector_hash,'hex') end,
    'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
    'agency_id',v_group.agency_id,'candidate_id',v_family.candidate_id,
    'client_id',v_contract.client_id,'contract_id',v_contract.id,
    'contract_week_id',v_contract_week.id,'root_timesheet_id',v_root.timesheet_id,
    'work_event_id',v_event.id,'week_ending_date',v_family.week_ending_date,
    'source_mode',v_source_mode,'policy',v_settings,
    'timesheet',pg_catalog.to_jsonb(v_root),'contract_week',pg_catalog.to_jsonb(v_contract_week),
    'contract_record',pg_catalog.to_jsonb(v_contract),
    'current_financial',case when v_fin.id is null then null else pg_catalog.to_jsonb(v_fin) end,
    'approved_component_identity_components',v_component_identity_components,
    'requires_zero_financial',v_fin.id is null,
    'protected_schedule',v_schedule,'source_segments',v_source_segments,
    'protected_decisions',v_decisions,'source_proposal',pg_catalog.jsonb_build_object(
      'selected_work_event_id',v_event.id,'source_present',v_selected_source_present,
      'source_minutes',v_selected_source_minutes,'source_revision',v_selected_source_revision,
      'source_hash',v_selected_source_hash,'source_segments',v_source_segments
    ),
    'client_sources',v_client_sources,'source_expenses',v_source_expenses,
    'candidate_submission',v_candidate_submission,
    'current_comparison_revision_id',v_comparison,
    'current_final_revision_id',v_current_final,
    'root_financial',case when v_fin.id is null then null else pg_catalog.jsonb_build_object(
      'source_system','CLOUDTMS_TIMESHEET_FINANCIAL','external_identity',v_fin.id::text,
      'external_revision',v_fin.timesheet_version::text,'document_sha256',v_fin_hash,
      'financial_row_id',v_fin.id,'root_version',v_root.version,
      'financial_timesheet_version',v_fin.timesheet_version,
      'financial_revision_digest',v_fin_hash
    ) end,
    'provider',pg_catalog.jsonb_build_object(
      'source_system','CLOUDTMS_CONTRACT_PROVIDER','external_identity',v_contract.id::text,
      'external_revision',v_root.version::text,'document_sha256',v_provider_hash,
      'source_pay_method',v_contract.pay_method_snapshot,
      'umbrella_id',nullif(pg_catalog.to_jsonb(v_contract)->>'umbrella_id','')::uuid,
      'provider_authority_sha256',v_provider_hash,
      'target_pay_method',v_contract.pay_method_snapshot,
      'target_umbrella_id',nullif(pg_catalog.to_jsonb(v_contract)->>'umbrella_id','')::uuid,
      'target_enabled',true,'target_vat_chargeable',null
    ),
    'expected_head_revision',coalesce((
      select generation.generation_number::bigint
      from private.weekly_source_local_protected_decision_receipts receipt
      join public.weekly_exceptional_pay_generations generation on generation.id=receipt.generation_id
      where receipt.family_id=v_family.id and receipt.state='COMPLETE'
        and generation.id=v_family.current_generation_id
    ),(
      select request.c1_head_revision
      from public.weekly_exceptional_c1_publication_requests request
      where request.family_id=v_family.id and request.state='PUBLISHED'
      order by request.request_sequence desc limit 1
    ),0)::text,
    'request_sequence',(v_family.current_generation_number+1)::text,
    'zero_rate_source_refs',v_rate_refs
  )||case when v_final_source ? 'next_source_segments'
    then pg_catalog.jsonb_build_object('next_source_segments',v_final_source->'next_source_segments',
      'family_bound_version',v_family.bound_version::text) else '{}'::jsonb end;
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_SCOPE_INVALID' using errcode='55000';
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_exceptional_pay_stage_c1_request_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_top_keys constant text[]:=array[
    'schema_version','actor_user_id','family_id','orchestration_run_id',
    'source_cycle_id','client_id','work_event_id','evidence_timesheet_id',
    'expected_family_bound_version','protected_schedule','rate_classification',
    'source_proposal','target_snapshot','current_comparison_revision_id',
    'current_final_revision_id','c1_request','c1_sources','c1_components',
    'reason','idempotency_key'
  ];
  v_c1_keys constant text[]:=array[
    'request_id','request_sequence','actor_user_id','candidate_id','contract_id',
    'root_timesheet_id','week_ending_date','source_mode',
    'expected_head_revision','expected_source_count','expected_component_count',
    'expected_payload_bytes','source_manifest_sha256','entitlement_sha256',
    'approval_sha256','is_zero_entitlement','financial_row_id','request_sha256'
  ];
  v_source_keys constant text[]:=array[
    'source_ordinal','source_id','authority_kind','source_system',
    'external_identity','external_revision','source_document_sha256',
    'payload_bytes','part_count','work_date','root_timesheet_id','candidate_id',
    'contract_id','source_row_sha256','record_type','parts'
  ];
  v_part_keys constant text[]:=array[
    'source_ordinal','part_ordinal','payload_utf8','fragment_sha256','record_type'
  ];
  v_component_keys constant text[]:=array[
    'component_ordinal','component_id','source_ordinal','source_key',
    'component_kind','economic_key_type','economic_key_value',
    'component_member_identity','segment_id','segment_key','segment_stable_key',
    'work_date','reference_number','hours_day','hours_night','hours_sat',
    'hours_sun','hours_bh','additional_code_raw','unit_count','unit_pay_rate',
    -- S7 (WB-007, WB-013, 24 section 5): `adjustment_id` is deliberately absent
    -- from this exact-key allowlist and from the C1 component relation.  An
    -- adjustment is never copied into a head, because an adjustment created
    -- later would make the snapshot stale and create a second owner.  A caller
    -- that still sends the key now fails closed here.
    'unit_charge_rate','expense_code','pay_ex_vat',
    'charge_ex_vat','exclude_from_pay','origin','component_sha256','record_type'
  ];
  v_schedule_keys constant text[]:=array[
    'work_date','start_at_local','end_at_local','break_minutes'
  ];
  v_actor_user_id uuid;
  v_family_id uuid;
  v_run_id uuid;
  v_source_cycle_id uuid;
  v_client_id uuid;
  v_work_event_id uuid;
  v_evidence_timesheet_id uuid;
  v_expected_bound_version bigint;
  v_comparison_revision_id uuid;
  v_final_revision_id uuid;
  v_reason text;
  v_idempotency_key text;
  v_schedule jsonb;
  v_rate_classification jsonb;
  v_source_proposal jsonb;
  v_selected_source_witness jsonb;
  v_target_snapshot jsonb;
  v_component_identity_context jsonb;
  v_component_identity_basis jsonb;
  v_bulk_signed_proof jsonb;
  v_automatic_reconcile_proof jsonb;
  v_start jsonb;
  v_sources jsonb;
  v_components jsonb;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_lock_family jsonb; v_lock_group uuid;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_root public.timesheets%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_evidence public.timesheets%rowtype;
  v_signed_evidence jsonb;
  v_event public.weekly_work_events%rowtype;
  v_prior_generation public.weekly_exceptional_pay_generations%rowtype;
  v_approval public.weekly_exceptional_payment_approvals%rowtype;
  v_generation public.weekly_exceptional_pay_generations%rowtype;
  v_publication public.weekly_exceptional_c1_publication_requests%rowtype;
  v_policy jsonb;
  v_source_mode text; v_activated_source_mode text;
  v_work_date date;
  v_start_at timestamp without time zone;
  v_end_at timestamp without time zone;
  v_break_minutes integer;
  v_expected_source_count integer;
  v_expected_component_count integer;
  v_expected_payload_bytes integer;
  v_request_sequence bigint;
  v_expected_head_revision bigint;
  v_financial_row_id uuid;
  v_request_id uuid;
  v_source_manifest_hash bytea;
  v_entitlement_hash bytea;
  v_outer_approval_hash bytea;
  v_c1_request_hash bytea;
  v_rate_policy_hash bytea;
  v_schedule_hash bytea;
  v_source_proposal_hash bytea;
  v_prior_vector jsonb;
  v_prior_vector_hash bytea;
  v_next_vector jsonb;
  v_next_vector_hash bytea;
  v_fixed_source_hash bytea;
  v_local_approval_hash bytea;
  v_family_event_hash bytea;
  v_target_event_hash bytea;
  v_prior_family_event_hash bytea;
  v_prior_target_event_hash bytea;
  v_issue_ids uuid[]:='{}'::uuid[];
  v_issue_ids_hash bytea;
  v_signed_revision integer;
  v_signed_hash bytea;
  v_signed_at timestamptz;
  v_generation_number integer;
  v_generation_reason text;
  v_family_event_state text;
  v_resulting_lifecycle_state text;
  v_pending_outcome text;
  v_payment_event_kind text;
  v_other_wait_count integer:=0;
  v_family_event_sequence bigint;
  v_family_event_id uuid;
  v_target_event_sequence bigint;
  v_total_pay numeric(12,2):=0;
  v_payload_total bigint:=0;
  v_previous_source_key text:=null;
  v_source_entry jsonb;
  v_part_entry jsonb;
  v_component_entry jsonb;
  v_source_id uuid;
  v_source_ordinal integer;
  v_source_counter integer:=0;
  v_part_ordinal integer;
  v_component_ordinal integer;
  v_part_payload bytea;
  v_part_concat bytea;
  v_source_part_count integer;
  v_source_payload_bytes integer;
  v_source_kind text;
  v_source_document jsonb;
  v_count_client integer:=0;
  v_count_candidate integer:=0;
  v_count_root integer:=0;
  v_count_provider integer:=0;
  v_count_office integer:=0;
  v_step_sequence integer;
  v_request_body_hash bytea;
  v_before_hash bytea;
  v_after_hash bytea;
begin
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,v_top_keys||array['bulk_signed_selection_proof','automatic_reconcile_selection_sha256'])
     or not (p_request ?& v_top_keys)
     or p_request->>'schema_version'<>'WEEKLY_PROTECTED_C1_STAGE_REQUEST_V1'
     or pg_catalog.jsonb_typeof(p_request->'protected_schedule')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'rate_classification')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'source_proposal')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'target_snapshot')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'c1_request')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'c1_sources')<>'array'
     or pg_catalog.jsonb_typeof(p_request->'c1_components')<>'array' then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_INVALID' using errcode='22023';
  end if;
  if pg_catalog.octet_length(pg_catalog.convert_to(p_request::text,'UTF8'))>4194304 then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_TOO_LARGE' using errcode='54000';
  end if;
  begin
    v_actor_user_id:=(p_request->>'actor_user_id')::uuid;
    v_family_id:=(p_request->>'family_id')::uuid;
    v_run_id:=(p_request->>'orchestration_run_id')::uuid;
    v_source_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_client_id:=(p_request->>'client_id')::uuid;
    v_work_event_id:=(p_request->>'work_event_id')::uuid;
    v_evidence_timesheet_id:=nullif(p_request->>'evidence_timesheet_id','')::uuid;
    v_expected_bound_version:=(p_request->>'expected_family_bound_version')::bigint;
    v_comparison_revision_id:=nullif(p_request->>'current_comparison_revision_id','')::uuid;
    v_final_revision_id:=nullif(p_request->>'current_final_revision_id','')::uuid;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_INVALID' using errcode='22023';
  end;
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  if pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_idempotency_key) not between 16 and 240 then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_INVALID' using errcode='22023';
  end if;

  v_schedule:=p_request->'protected_schedule';
  if not private.weekly_exceptional_json_keys_exact_v1(v_schedule,v_schedule_keys)
     or not (v_schedule ?& v_schedule_keys) then
    raise exception 'WEEKLY_PROTECTED_SCHEDULE_INVALID' using errcode='22023';
  end if;
  begin
    v_work_date:=(v_schedule->>'work_date')::date;
    v_start_at:=(v_schedule->>'start_at_local')::timestamp without time zone;
    v_end_at:=(v_schedule->>'end_at_local')::timestamp without time zone;
    v_break_minutes:=(v_schedule->>'break_minutes')::integer;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_SCHEDULE_INVALID' using errcode='22023';
  end;
  if v_end_at<=v_start_at or v_start_at::date<>v_work_date
     or v_break_minutes<0
     or v_break_minutes>=extract(epoch from (v_end_at-v_start_at))/60 then
    raise exception 'WEEKLY_PROTECTED_SCHEDULE_INVALID' using errcode='22023';
  end if;
  v_rate_classification:=p_request->'rate_classification';
  v_source_proposal:=p_request->'source_proposal';
  v_target_snapshot:=p_request->'target_snapshot';
  if pg_catalog.octet_length(pg_catalog.convert_to(v_rate_classification::text,'UTF8'))>65536
     or pg_catalog.octet_length(pg_catalog.convert_to(v_source_proposal::text,'UTF8'))>65536
     or pg_catalog.octet_length(pg_catalog.convert_to(v_target_snapshot::text,'UTF8'))>1048576 then
    raise exception 'WEEKLY_PROTECTED_TARGET_TOO_LARGE' using errcode='54000';
  end if;

  v_start:=p_request->'c1_request';
  v_sources:=p_request->'c1_sources';
  v_components:=p_request->'c1_components';
  if not private.weekly_exceptional_json_keys_exact_v1(v_start,v_c1_keys)
     or not (v_start ?& v_c1_keys)
     or pg_catalog.jsonb_array_length(v_sources) not between 1 and 65536
     or pg_catalog.jsonb_array_length(v_components)>65536 then
    raise exception 'WEEKLY_PROTECTED_C1_STREAM_INVALID' using errcode='22023';
  end if;
  begin
    v_request_id:=(v_start->>'request_id')::uuid;
    v_request_sequence:=(v_start->>'request_sequence')::bigint;
    v_expected_head_revision:=(v_start->>'expected_head_revision')::bigint;
    v_expected_source_count:=(v_start->>'expected_source_count')::integer;
    v_expected_component_count:=(v_start->>'expected_component_count')::integer;
    v_expected_payload_bytes:=(v_start->>'expected_payload_bytes')::integer;
    v_financial_row_id:=(v_start->>'financial_row_id')::uuid;
    v_source_manifest_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'source_manifest_sha256');
    v_entitlement_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'entitlement_sha256');
    v_outer_approval_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'approval_sha256');
    v_c1_request_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'request_sha256');
  exception when others then
    raise exception 'WEEKLY_PROTECTED_C1_STREAM_INVALID' using errcode='22023';
  end;
  if v_request_sequence<1 or v_expected_head_revision<0
     or v_expected_source_count<>pg_catalog.jsonb_array_length(v_sources)
     or v_expected_component_count<>pg_catalog.jsonb_array_length(v_components)
     or v_expected_payload_bytes<1
     or ((v_start->>'is_zero_entitlement')::boolean is distinct from
         (v_expected_component_count=0)) then
    raise exception 'WEEKLY_PROTECTED_C1_STREAM_COUNT_INVALID' using errcode='22023';
  end if;

  -- An exact staged request is the idempotency authority even after the family
  -- version advances.  A UUID collision with different bytes always refuses.
  select request.* into v_publication
  from public.weekly_exceptional_c1_publication_requests request
  where request.id=v_request_id;
  if found then
    if v_publication.family_id is distinct from v_family_id
       or v_publication.orchestration_run_id is distinct from v_run_id
       or v_publication.request_sha256 is distinct from v_c1_request_hash then
      raise exception 'WEEKLY_PROTECTED_C1_REQUEST_ID_COLLISION' using errcode='23505';
    end if;
    perform private.weekly_source_bulk_stage_replay_assert_v1(v_publication.id,p_request);
    perform private.weekly_source_automatic_reconcile_stage_replay_assert_v1(v_publication.id,p_request);
    return pg_catalog.jsonb_build_object(
      'ok',true,'outcome','STAGED','idempotent_replay',true,
      'family_id',v_publication.family_id,'generation_id',v_publication.generation_id,
      'publication_request_id',v_publication.id,'request_sha256',
      pg_catalog.encode(v_publication.request_sha256,'hex'),
      'state',v_publication.state
    );
  end if;

  v_lock_family:=private.weekly_source_protected_family_lock_v1(v_family_id);
  -- An exact staged request is the idempotency authority even after the family
  -- version advances.  A UUID collision with different bytes always refuses.
  select request.* into v_publication
  from public.weekly_exceptional_c1_publication_requests request
  where request.id=v_request_id
  for update;
  if found then
    if v_publication.family_id is distinct from v_family_id
       or v_publication.orchestration_run_id is distinct from v_run_id
       or v_publication.request_sha256 is distinct from v_c1_request_hash then
      raise exception 'WEEKLY_PROTECTED_C1_REQUEST_ID_COLLISION' using errcode='23505';
    end if;
    perform private.weekly_source_bulk_stage_replay_assert_v1(v_publication.id,p_request);
    perform private.weekly_source_automatic_reconcile_stage_replay_assert_v1(v_publication.id,p_request);
    return pg_catalog.jsonb_build_object(
      'ok',true,'outcome','STAGED','idempotent_replay',true,
      'family_id',v_publication.family_id,'generation_id',v_publication.generation_id,
      'publication_request_id',v_publication.id,'request_sha256',
      pg_catalog.encode(v_publication.request_sha256,'hex'),
      'state',v_publication.state
    );
  end if;

  select family.* into strict v_family
  from public.weekly_exceptional_pay_target_families family
  where family.id=v_family_id
  for update;
  select run.* into strict v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.id=v_run_id and run.family_id=v_family.id
  for update;
  if (v_family.root_timesheet_id::text,v_family.candidate_id::text,v_family.contract_id::text,v_family.week_ending_date::text)
    is distinct from (v_lock_family->>'root_timesheet_id',v_lock_family->>'candidate_id',
      v_lock_family->>'contract_id',v_lock_family->>'week_ending_date') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_source_cycle_id);
  if p_request ? 'bulk_signed_selection_proof' or p_request ? 'automatic_reconcile_selection_sha256' then
    -- The new one-shift round seals one pending proof at a time using the
    -- existing cycle mutex; the individual path retains its native SHARE.
    select cycle.* into strict v_cycle from public.weekly_source_cycles cycle
      where cycle.id=v_source_cycle_id for update;
  else
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle
  where cycle.id=v_source_cycle_id
  for share;
  end if;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id and source_group.active
  for share;
  perform private.weekly_source_office_authority_v1(
    v_actor_user_id,'APPROVE_PROTECTED_PAY',v_group.id,v_client_id,v_work_date
  );

  if v_run.requested_by_user_id is distinct from v_actor_user_id
     or v_run.state<>'RUNNING'
     or v_run.request_kind not in (
       'APPROVE','AMEND','WITHDRAW','RECONCILE','RECORD_NOT_WORKED'
     )
     or v_family.bound_version<>v_expected_bound_version
     or v_family.c1_publication_state in ('PENDING','PUBLISHING')
     or v_family.agency_id is distinct from v_group.agency_id
     or v_family.root_timesheet_id is null
     or v_work_date not between v_family.week_start_date and v_family.week_ending_date
     or not exists(
       select 1 from public.weekly_source_group_clients membership
       where membership.source_group_id=v_group.id
         and membership.client_id=v_client_id
         and v_work_date between membership.valid_from
           and coalesce(membership.valid_to,'infinity'::date)
     ) then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_SCOPE_INVALID' using errcode='55000';
  end if;

  select timesheet.* into strict v_root
  from public.timesheets timesheet
  where timesheet.timesheet_id=v_family.root_timesheet_id
  for share;
  select financial.* into strict v_fin
  from public.timesheets_financials financial
  where financial.id=v_financial_row_id
    and financial.timesheet_id=v_root.timesheet_id
    and financial.is_current
  for share;
  select event.* into strict v_event
  from public.weekly_work_events event
  where event.id=v_work_event_id
    and event.candidate_id=v_family.candidate_id
    and event.client_id=v_client_id
    and event.work_date=v_work_date
  for share;
  if v_root.contract_id is distinct from v_family.contract_id
     or v_root.week_ending_date is distinct from v_family.week_ending_date
     or v_root.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum
     or v_root.line_type<>'HOURS'::public.timesheet_line_type_enum
     or v_root.is_adjustment or not v_root.is_current
     or v_root.revoked_at is not null or v_root.archived_at_utc is not null then
    raise exception 'WEEKLY_PROTECTED_C1_ROOT_INVALID' using errcode='55000';
  end if;

  v_policy:=private._weekly_source_effective_policy_v1(
    v_client_id,v_family.contract_id,v_work_date
  );
  v_activated_source_mode:=private.weekly_source_protected_non_self_bill_mode_v1(v_client_id,v_family.contract_id,v_work_date,v_cycle.id);
  v_source_mode:=coalesce(v_policy->>'c1_source_mode',v_activated_source_mode);
  if v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or (coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true and v_activated_source_mode is null)
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_PROTECTED_C1_POLICY_INVALID' using errcode='55000';
  end if;

  -- Existing WITHDRAW/RECONCILE actions accept actual Source, including
  -- certified absence; this does not define any other removal action. A
  -- Final-only synthetic zero proposal is not proof that Source is absent.
  -- Keep replay above this fresh admission check; do not reinterpret a saved
  -- decision after subsequent imports or change the Banking publication owner.
  if v_run.request_kind in ('WITHDRAW','RECONCILE') then
    v_selected_source_witness:=private.weekly_source_selected_source_witness_v1(
      v_family.id,v_cycle.id,v_event.id
    );
    if v_selected_source_witness is null
       or v_selected_source_witness->'source_proposal' is distinct from v_source_proposal
       or (v_selected_source_witness->>'kind'='CURRENT_ROW' and (
         v_selected_source_witness#>>'{basis,final_revision_id}' is null
         or v_selected_source_witness#>>'{basis,final_revision_id}' is distinct from v_source_proposal->>'source_revision'
         or v_source_proposal->'source_present' is distinct from 'true'::jsonb
       ))
       or (v_selected_source_witness->>'kind'='CERTIFIED_ABSENCE' and (
         v_source_proposal->'source_present' is distinct from 'false'::jsonb
         or v_source_proposal->>'source_minutes' is distinct from '0'
       ))
       or coalesce(v_selected_source_witness->>'kind' not in ('CURRENT_ROW','CERTIFIED_ABSENCE'),true) then
      raise exception 'WEEKLY_PROTECTED_C1_SELECTED_SOURCE_UNAVAILABLE' using errcode='55000';
    end if;
  end if;

  if (v_start->>'actor_user_id')::uuid is distinct from v_actor_user_id
     or (v_start->>'candidate_id')::uuid is distinct from v_family.candidate_id
     or (v_start->>'contract_id')::uuid is distinct from v_family.contract_id
     or (v_start->>'root_timesheet_id')::uuid is distinct from v_root.timesheet_id
     or (v_start->>'week_ending_date')::date is distinct from v_family.week_ending_date
     or v_start->>'source_mode'<>v_source_mode
     or v_financial_row_id is distinct from v_fin.id
     or v_request_sequence<>v_family.current_generation_number+1 then
    raise exception 'WEEKLY_PROTECTED_C1_START_SCOPE_INVALID' using errcode='55000';
  end if;
  if v_family.current_generation_id is null then
    if v_expected_head_revision<>0 then
      raise exception 'WEEKLY_PROTECTED_C1_HEAD_INVALID' using errcode='55000';
    end if;
  else
    select generation.* into strict v_prior_generation
    from public.weekly_exceptional_pay_generations generation
    where generation.id=v_family.current_generation_id
      and generation.family_id=v_family.id
      and generation.lifecycle_state='PUBLISHED'
    for share;
    select request.* into strict v_publication
    from public.weekly_exceptional_c1_publication_requests request
    where request.generation_id=v_prior_generation.id
      and request.family_id=v_family.id
      and (request.state='PUBLISHED' or (request.state='RETIRED' and exists(
        select 1 from private.weekly_source_local_protected_decision_receipts receipt
        where receipt.publication_request_id=request.id and receipt.generation_id=v_prior_generation.id
          and receipt.state='COMPLETE')));
    if (case when v_publication.state='RETIRED' then v_prior_generation.generation_number::bigint
             else v_publication.c1_head_revision end) is distinct from v_expected_head_revision then
      raise exception 'WEEKLY_PROTECTED_C1_HEAD_INVALID' using errcode='55000';
    end if;
    v_publication.id:=null;
  end if;

  if v_evidence_timesheet_id is not null then
    select evidence.* into strict v_evidence
    from public.timesheets evidence
    where evidence.timesheet_id=v_evidence_timesheet_id
      and evidence.contract_id=v_family.contract_id
      and evidence.week_ending_date=v_family.week_ending_date
      and evidence.sheet_scope='WEEKLY'::public.timesheet_scope_enum
      and evidence.is_current and evidence.revoked_at is null
      and evidence.archived_at_utc is null;
    v_signed_evidence:=private.weekly_exceptional_candidate_signed_evidence_v1(
      v_evidence_timesheet_id
    );
    v_signed_at:=(v_signed_evidence->>'signed_at_utc')::timestamptz;
    v_signed_revision:=(v_signed_evidence->>'timesheet_version')::integer;
    v_signed_hash:=private.weekly_exceptional_hex_sha256_v1(
      v_signed_evidence->>'signature_sha256'
    );
  end if;

  select coalesce(pg_catalog.array_agg(incident.id order by incident.id),'{}'::uuid[])
    into v_issue_ids
  from public.weekly_discrepancy_incidents incident
  where incident.source_group_id=v_group.id
    and incident.work_event_id=v_work_event_id
    and incident.candidate_id=v_family.candidate_id
    and incident.client_id=v_client_id;
  v_issue_ids_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_ISSUE_SET_V1',pg_catalog.to_jsonb(v_issue_ids)
  );
  v_schedule_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_SCHEDULE_V1',v_schedule
  );
  v_rate_policy_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_RATE_POLICY_V1',
    pg_catalog.jsonb_build_object(
      'contract_id',v_family.contract_id,
      'rates_json',(select contract.rates_json from public.contracts contract where contract.id=v_family.contract_id),
      'policy',v_policy,'classification',v_rate_classification
    )
  );
  v_source_proposal_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_SOURCE_PROPOSAL_V1',v_source_proposal
  );

  if v_comparison_revision_id is not null and not exists(
    select 1
    from public.weekly_issue_comparison_revisions comparison
    join public.weekly_discrepancy_incidents incident on incident.id=comparison.incident_id
    where comparison.id=v_comparison_revision_id
      and comparison.contract_id=v_family.contract_id
      and incident.source_group_id=v_group.id
      and incident.work_event_id=v_work_event_id
      and incident.candidate_id=v_family.candidate_id
      and incident.client_id=v_client_id
  ) then
    raise exception 'WEEKLY_PROTECTED_COMPARISON_SCOPE_INVALID' using errcode='55000';
  end if;
  if v_final_revision_id is not null and not exists(
    select 1 from public.weekly_source_final_revisions final_revision
    where final_revision.id=v_final_revision_id
      and final_revision.source_cycle_id=v_source_cycle_id
      and final_revision.state='CURRENT'
  ) then
    raise exception 'WEEKLY_PROTECTED_FINAL_SCOPE_INVALID' using errcode='55000';
  end if;

  -- Validate and persist the complete normalized C1 source stream.  The C1
  -- owner independently replays its TLV hashes before certification; these
  -- local checks prevent truncation, reordering or cross-root substitution.
  for v_source_entry in
    select value from pg_catalog.jsonb_array_elements(v_sources)
  loop
    v_source_counter:=v_source_counter+1;
    if not private.weekly_exceptional_json_keys_exact_v1(v_source_entry,v_source_keys)
       or not (v_source_entry ?& v_source_keys)
       or v_source_entry->>'record_type'<>'SOURCE'
       or pg_catalog.jsonb_typeof(v_source_entry->'parts')<>'array' then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_INVALID' using errcode='22023';
    end if;
    begin
      v_source_ordinal:=(v_source_entry->>'source_ordinal')::integer;
      v_source_id:=(v_source_entry->>'source_id')::uuid;
      v_source_payload_bytes:=(v_source_entry->>'payload_bytes')::integer;
      v_source_part_count:=(v_source_entry->>'part_count')::integer;
    exception when others then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_INVALID' using errcode='22023';
    end;
    if v_source_ordinal<>v_source_counter
       or v_source_ordinal not between 1 and v_expected_source_count
       or (v_source_entry->>'root_timesheet_id')::uuid is distinct from v_root.timesheet_id
       or (v_source_entry->>'candidate_id')::uuid is distinct from v_family.candidate_id
       or (v_source_entry->>'contract_id')::uuid is distinct from v_family.contract_id
       or v_source_payload_bytes not between 1 and 16384
       or v_source_part_count<>pg_catalog.jsonb_array_length(v_source_entry->'parts')
       or v_source_part_count not between 1 and 6 then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_SCOPE_INVALID' using errcode='55000';
    end if;
    v_source_kind:=v_source_entry->>'authority_kind';
    if v_source_kind not in (
      'CANDIDATE_SUBMISSION','CLIENT_SOURCE','OFFICE_APPROVAL','ROOT_FINANCIAL',
      'PROVIDER','SOURCE_EXPENSE','ORDINARY_EXPENSE','APPROVED_COMPONENT'
    ) then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_KIND_INVALID' using errcode='22023';
    end if;
    v_count_client:=v_count_client+(v_source_kind='CLIENT_SOURCE')::integer;
    v_count_candidate:=v_count_candidate+(v_source_kind='CANDIDATE_SUBMISSION')::integer;
    v_count_root:=v_count_root+(v_source_kind='ROOT_FINANCIAL')::integer;
    v_count_provider:=v_count_provider+(v_source_kind='PROVIDER')::integer;
    v_count_office:=v_count_office+(v_source_kind='OFFICE_APPROVAL')::integer;
    v_part_concat:=''::bytea;
    v_part_ordinal:=0;
    for v_part_entry in
      select value from pg_catalog.jsonb_array_elements(v_source_entry->'parts')
    loop
      v_part_ordinal:=v_part_ordinal+1;
      if not private.weekly_exceptional_json_keys_exact_v1(v_part_entry,v_part_keys)
         or not (v_part_entry ?& v_part_keys)
         or v_part_entry->>'record_type'<>'PART'
         or (v_part_entry->>'source_ordinal')::integer<>v_source_ordinal
         or (v_part_entry->>'part_ordinal')::integer<>v_part_ordinal
         or coalesce(v_part_entry->>'payload_utf8','')!~'^(?:[0-9a-f]{2})+$' then
        raise exception 'WEEKLY_PROTECTED_C1_PART_INVALID' using errcode='22023';
      end if;
      v_part_payload:=pg_catalog.decode(v_part_entry->>'payload_utf8','hex');
      if pg_catalog.octet_length(v_part_payload) not between 1 and 3072
         or extensions.digest(v_part_payload,'sha256') is distinct from
            private.weekly_exceptional_hex_sha256_v1(v_part_entry->>'fragment_sha256') then
        raise exception 'WEEKLY_PROTECTED_C1_PART_HASH_INVALID' using errcode='22023';
      end if;
      v_part_concat:=v_part_concat||v_part_payload;
    end loop;
    if v_part_ordinal<>v_source_part_count
       or pg_catalog.octet_length(v_part_concat)<>v_source_payload_bytes then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_PAYLOAD_INVALID' using errcode='22023';
    end if;
    begin
      v_source_document:=pg_catalog.convert_from(v_part_concat,'UTF8')::jsonb;
    exception when others then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_DOCUMENT_INVALID' using errcode='22023';
    end;
    if pg_catalog.jsonb_typeof(v_source_document)<>'object'
       or (v_source_document->>'root_timesheet_id')::uuid is distinct from v_root.timesheet_id
       or (v_source_document->>'candidate_id')::uuid is distinct from v_family.candidate_id
       or (v_source_document->>'contract_id')::uuid is distinct from v_family.contract_id
       or (v_source_document->>'week_ending_date')::date is distinct from v_family.week_ending_date
       or v_source_document->>'document_sha256' is distinct from
          v_source_entry->>'source_document_sha256' then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_DOCUMENT_SCOPE_INVALID' using errcode='55000';
    end if;
    if v_source_kind='CLIENT_SOURCE'
       and coalesce((v_source_document->>'source_complete')::boolean,false) is not true then
      raise exception 'WEEKLY_PROTECTED_C1_CLIENT_SOURCE_INCOMPLETE' using errcode='55000';
    elsif v_source_kind='ROOT_FINANCIAL'
       and (v_source_document->>'financial_row_id')::uuid is distinct from v_fin.id then
      raise exception 'WEEKLY_PROTECTED_C1_ROOT_FINANCIAL_INVALID' using errcode='55000';
    elsif v_source_kind='OFFICE_APPROVAL'
       and (
         (v_source_document->>'actor_user_id')::uuid is distinct from v_actor_user_id
         or (v_source_document->>'request_id')::uuid is distinct from v_request_id
         or v_source_document->>'entitlement_sha256' is distinct from
            v_start->>'entitlement_sha256'
         or v_source_document->>'decision'<>'APPROVE_ENTITLEMENT'
       ) then
      raise exception 'WEEKLY_PROTECTED_C1_OFFICE_SOURCE_INVALID' using errcode='55000';
    end if;
    v_payload_total:=v_payload_total+v_source_payload_bytes;
  end loop;
  if v_source_counter<>v_expected_source_count
     or v_count_client<1 or v_count_root<>1 or v_count_provider<>1 or v_count_office<>1
     or (v_evidence_timesheet_id is null and v_count_candidate<>0)
     or (v_evidence_timesheet_id is not null and v_count_candidate<>1)
     or v_payload_total<>v_expected_payload_bytes then
    raise exception 'WEEKLY_PROTECTED_C1_SOURCE_CARDINALITY_INVALID' using errcode='55000';
  end if;

  v_component_ordinal:=0;
  for v_component_entry in
    select value from pg_catalog.jsonb_array_elements(v_components)
  loop
    v_component_ordinal:=v_component_ordinal+1;
    if not private.weekly_exceptional_json_keys_exact_v1(v_component_entry,v_component_keys)
       or not (v_component_entry ?& v_component_keys)
       or v_component_entry->>'record_type'<>'COMPONENT'
       or (v_component_entry->>'component_ordinal')::integer<>v_component_ordinal
       or (v_component_entry->>'source_ordinal')::integer not between 1 and v_expected_source_count
       or coalesce(v_component_entry->>'source_key','')=''
       or (v_previous_source_key is not null and v_component_entry->>'source_key'<=v_previous_source_key) then
      raise exception 'WEEKLY_PROTECTED_C1_COMPONENT_INVALID' using errcode='22023';
    end if;
    if nullif(v_component_entry->>'work_date','') is not null
       and (v_component_entry->>'work_date')::date not between
           v_family.week_start_date and v_family.week_ending_date then
      raise exception 'WEEKLY_PROTECTED_C1_COMPONENT_WEEK_INVALID' using errcode='55000';
    end if;
    v_total_pay:=v_total_pay+(v_component_entry->>'pay_ex_vat')::numeric;
    perform private.weekly_exceptional_hex_sha256_v1(v_component_entry->>'component_sha256');
    v_previous_source_key:=v_component_entry->>'source_key';
  end loop;
  if v_component_ordinal<>v_expected_component_count then
    raise exception 'WEEKLY_PROTECTED_C1_COMPONENT_COUNT_INVALID' using errcode='22023';
  end if;
  v_total_pay:=pg_catalog.round(v_total_pay,2);

  if v_family.current_generation_id is null then
    -- Before the prepare owner distinguished empty from published families,
    -- a retry could be recorded as AMEND even though nothing was published.
    -- Preserve that immutable request and permit only its first generation;
    -- never treat an existing staged/published entitlement as an initial one.
    if v_run.request_kind not in ('APPROVE','AMEND')
       or v_family.current_generation_number<>0
       or v_family.current_lifecycle_state<>'PENDING_APPROVAL'
       or exists(select 1 from public.weekly_exceptional_pay_generations existing
         where existing.family_id=v_family.id) then
      raise exception 'WEEKLY_PROTECTED_C1_INITIAL_ACTION_INVALID' using errcode='55000';
    end if;
    v_prior_vector:=pg_catalog.jsonb_build_object(
      'schema_version','WEEKLY_PROTECTED_TARGET_VECTOR_V1',
      'components',pg_catalog.jsonb_build_array(),
      'component_count',0,'is_zero_entitlement',true
    );
    v_generation_number:=1;
    v_generation_reason:='INITIAL_APPROVAL';
  else
    v_prior_vector:=v_prior_generation.complete_next_vector_json;
    v_generation_number:=v_prior_generation.generation_number+1;
    v_generation_reason:=case v_run.request_kind
      when 'AMEND' then 'OFFICE_AMENDMENT'
      when 'WITHDRAW' then 'WITHDRAW'
      when 'RECONCILE' then 'RECONCILE'
      when 'RECORD_NOT_WORKED' then 'RECORD_NOT_WORKED'
      else null end;
    if v_generation_reason is null then
      raise exception 'WEEKLY_PROTECTED_C1_ACTION_INVALID' using errcode='55000';
    end if;
  end if;
  v_family_event_state:=case
    when v_run.request_kind in ('APPROVE','AMEND') then 'WAIT'
    when v_run.request_kind in ('WITHDRAW','RECONCILE') then 'ACCEPTED_SOURCE'
    else 'NOT_WORKED' end;
  if v_run.request_kind='RECORD_NOT_WORKED'
     and coalesce((v_source_proposal->>'source_present')::boolean,true) then
    raise exception 'WEEKLY_PROTECTED_NOT_WORKED_SOURCE_PRESENT' using errcode='55000';
  end if;
  with latest as (
    select family_event.durable_work_event_id,family_event.state,
      pg_catalog.row_number() over (
        partition by family_event.durable_work_event_id
        order by family_event.event_sequence desc
      ) as event_rank
    from public.weekly_exceptional_pay_family_events family_event
    where family_event.family_id=v_family.id
      and family_event.durable_work_event_id<>v_work_event_id
  )
  select pg_catalog.count(*)::integer into v_other_wait_count
  from latest where event_rank=1 and state='WAIT';
  v_resulting_lifecycle_state:=case
    when v_family_event_state='WAIT' or v_other_wait_count>0 then 'WAITING_SOURCE'
    when v_run.request_kind='RECORD_NOT_WORKED' then 'NOT_WORKED'
    else 'RECONCILED' end;
  v_pending_outcome:=case v_family_event_state
    when 'WAIT' then 'WAIT'
    when 'ACCEPTED_SOURCE' then 'ACCEPT_SOURCE'
    else 'RECORD_NOT_WORKED' end;
  v_payment_event_kind:=case v_run.request_kind
    when 'APPROVE' then 'APPROVED'
    when 'AMEND' then 'APPROVED'
    when 'RECORD_NOT_WORKED' then 'RECORDED_NOT_WORKED'
    else 'MATCH_ACCEPTED' end;
  v_prior_vector_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',v_prior_vector
  );
  v_next_vector:=pg_catalog.jsonb_build_object(
    'schema_version','WEEKLY_PROTECTED_TARGET_VECTOR_V1',
    'target_snapshot',v_target_snapshot,
    'components',v_components,
    'component_count',v_expected_component_count,
    'is_zero_entitlement',(v_expected_component_count=0),
    'entitlement_sha256',v_start->>'entitlement_sha256',
    'approved_pay_ex_vat',pg_catalog.to_char(v_total_pay,'FM9999999990.00')
  );
  -- Identity metadata is admitted only against this fresh, actual server
  -- context under the established stage locks, never the caller's manifest.
  -- Matching clocks are not a historical identity-derivation fallback.
  v_component_identity_context:=public.weekly_exceptional_pay_action_context_v1(
    jsonb_build_object('schema_version','WEEKLY_PROTECTED_ACTION_CONTEXT_V1',
      'actor_user_id',v_actor_user_id,'family_id',v_family.id,
      'orchestration_run_id',v_run.id,'source_cycle_id',v_cycle.id,
      'work_event_id',v_event.id,'protected_schedule',v_schedule,
      'evidence_timesheet_id',v_evidence_timesheet_id));
  if v_component_identity_context->>'root_timesheet_id' is distinct from v_root.timesheet_id::text
     or v_component_identity_context#>>'{current_financial,id}' is distinct from v_fin.id::text
     or v_component_identity_context->>'family_bound_version' is distinct from v_expected_bound_version::text
     or v_component_identity_context->'source_proposal' is distinct from v_source_proposal then
    raise exception 'WEEKLY_PROTECTED_COMPONENT_MANIFEST_UNAVAILABLE' using errcode='55000'; end if;
  v_component_identity_basis:=private.weekly_source_protected_component_manifest_v1(
    v_component_identity_context,v_target_snapshot);
  v_next_vector:=v_next_vector||jsonb_build_object(
    'protected_component_identity_basis',v_component_identity_basis);
  -- Seal the common before-position at approval. A later authorised amendment
  -- must not silently replace an entitlement published after this calculation.
  if v_root.authorised_at_server is not null then
    v_next_vector:=v_next_vector||pg_catalog.jsonb_build_object(
      'prior_effective_inventory',private.weekly_source_effective_inventory_v1(v_root.timesheet_id));
  end if;
  if p_request ? 'bulk_signed_selection_proof' then
    v_bulk_signed_proof:=private.weekly_source_bulk_stage_proof_v1(p_request,v_fin.id);
    v_next_vector:=v_next_vector||jsonb_build_object('bulk_signed_selection_proof',v_bulk_signed_proof);
  end if;
  if p_request ? 'automatic_reconcile_selection_sha256' then
    v_automatic_reconcile_proof:=private.weekly_source_automatic_reconcile_stage_proof_v1(p_request);
    v_next_vector:=v_next_vector||jsonb_build_object('automatic_reconcile_proof',v_automatic_reconcile_proof);
  end if;
  v_next_vector_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',v_next_vector
  );
  v_fixed_source_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_FIXED_SOURCE_STATE_V1',
    pg_catalog.jsonb_build_object(
      'source_cycle_id',v_source_cycle_id,
      'comparison_revision_id',v_comparison_revision_id,
      'final_revision_id',v_final_revision_id,
      'source_proposal_hash',pg_catalog.encode(v_source_proposal_hash,'hex'),
      'financial_row_id',v_fin.id,'financial_timesheet_version',v_fin.timesheet_version
    )
  );
  v_local_approval_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_APPROVAL_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'work_event_id',v_work_event_id,
      'candidate_id',v_family.candidate_id,'client_id',v_client_id,
      'contract_id',v_family.contract_id,'week_ending_date',v_family.week_ending_date,
      'schedule_hash',pg_catalog.encode(v_schedule_hash,'hex'),
      'evidence_timesheet_id',v_evidence_timesheet_id,
      'signed_hash',case when v_signed_hash is null then null else pg_catalog.encode(v_signed_hash,'hex') end,
      'issue_ids_hash',pg_catalog.encode(v_issue_ids_hash,'hex'),
      'rate_policy_hash',pg_catalog.encode(v_rate_policy_hash,'hex'),
      'target_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'actor_user_id',v_actor_user_id,'reason',v_reason
    )
  );

  insert into public.weekly_exceptional_payment_approvals(
    pay_target_family_id,work_event_id,evidence_timesheet_id,candidate_id,
    client_id,contract_id,week_ending,protected_work_date,
    protected_start_at_local,protected_end_at_local,protected_break_minutes,
    signed_submission_timesheet_id,signed_submission_revision,
    signed_submission_hash,signed_at_utc,contributing_issue_episode_ids,
    contributing_issue_episode_ids_hash,signed_schedule_fact_hash,
    contract_rate_policy_source_fingerprint,approved_by_user_id,
    approval_reason,source_cycle_id,comparison_revision_id,final_revision_id,
    approved_target_pay_components_json,approved_target_gross,
    creation_orchestration_run_id,approval_hash,creation_idempotency_key
  ) values (
    v_family.id,v_work_event_id,v_evidence_timesheet_id,v_family.candidate_id,
    v_client_id,v_family.contract_id,v_family.week_ending_date,v_work_date,
    v_start_at,v_end_at,v_break_minutes,
    v_evidence_timesheet_id,v_signed_revision,v_signed_hash,v_signed_at,v_issue_ids,
    v_issue_ids_hash,v_schedule_hash,v_rate_policy_hash,v_actor_user_id,
    v_reason,v_source_cycle_id,v_comparison_revision_id,v_final_revision_id,
    v_target_snapshot,v_total_pay,v_run.id,v_local_approval_hash,
    v_idempotency_key||':approval'
  ) returning * into v_approval;

  insert into public.weekly_exceptional_pay_generations(
    family_id,generation_number,prior_generation_id,prior_generation_hash,
    request_idempotency_key,reason,complete_prior_vector_json,
    complete_prior_vector_hash,complete_next_vector_json,complete_next_vector_hash,
    fixed_target_source_state_fingerprint,lifecycle_state
  ) values (
    v_family.id,v_generation_number,v_family.current_generation_id,
    case when v_family.current_generation_id is null then null else v_prior_vector_hash end,
    v_idempotency_key||':generation',v_generation_reason,v_prior_vector,
    v_prior_vector_hash,v_next_vector,v_next_vector_hash,v_fixed_source_hash,'PENDING_C1'
  ) returning * into v_generation;

  select coalesce(max(event_sequence),0)+1,
         (array_agg(event_hash order by event_sequence desc))[1]
    into v_family_event_sequence,v_prior_family_event_hash
  from public.weekly_exceptional_pay_family_events
  where family_id=v_family.id;
  v_family_event_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_FAMILY_EVENT_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'event_sequence',v_family_event_sequence,
      'work_event_id',v_work_event_id,'approval_id',v_approval.id,
      'schedule',v_schedule,'source_proposal_hash',pg_catalog.encode(v_source_proposal_hash,'hex'),
      'target_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'prior_event_hash',case when v_prior_family_event_hash is null then null
        else pg_catalog.encode(v_prior_family_event_hash,'hex') end
    )
  );
  insert into public.weekly_exceptional_pay_family_events(
    family_id,event_sequence,durable_work_event_id,evidence_approval_id,
    work_date,start_at_local,end_at_local,break_minutes,rate_classification_json,
    source_proposal_snapshot_json,source_proposal_hash,
    fixed_office_target_snapshot_json,fixed_office_target_hash,state,
    current_comparison_revision_id,current_final_revision_id,office_actor_user_id,
    office_reason,prior_event_hash,event_hash
  ) values (
    v_family.id,v_family_event_sequence,v_work_event_id,v_approval.id,
    v_work_date,v_start_at,v_end_at,v_break_minutes,v_rate_classification,
    v_source_proposal,v_source_proposal_hash,v_schedule,v_schedule_hash,v_family_event_state,
    v_comparison_revision_id,v_final_revision_id,v_actor_user_id,v_reason,
    v_prior_family_event_hash,v_family_event_hash
  ) returning id into v_family_event_id;
  if (select active_owner from private.bpay_next_module_control where id=1)='NEXT' then
    perform private.bpay_next_protected_current_decision_capture_v1(v_family_event_id);
  end if;

  select coalesce(max(event_sequence),0)+1,
         (array_agg(event_hash order by event_sequence desc))[1]
    into v_target_event_sequence,v_prior_target_event_hash
  from public.weekly_exceptional_pay_target_events
  where family_id=v_family.id;
  v_target_event_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_TARGET_EVENT_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'event_sequence',v_target_event_sequence,
      'approval_id',v_approval.id,'generation_id',v_generation.id,
      'prior_vector_hash',pg_catalog.encode(v_prior_vector_hash,'hex'),
      'next_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'reason',v_generation_reason,'actor_user_id',v_actor_user_id
    )
  );
  insert into public.weekly_exceptional_pay_target_events(
    family_id,approval_id,event_sequence,triggering_comparison_revision_id,
    triggering_final_revision_id,prior_event_fingerprint,
    fixed_target_component_snapshot,current_source_proposal_snapshot,
    complete_prior_family_vector_fingerprint,
    complete_next_family_vector_fingerprint,reason,resulting_lifecycle_state,
    financial_generation_id,actor_user_id,event_hash,idempotency_key
  ) values (
    v_family.id,v_approval.id,v_target_event_sequence,v_comparison_revision_id,
    v_final_revision_id,v_prior_target_event_hash,v_target_snapshot,v_source_proposal,
    v_prior_vector_hash,v_next_vector_hash,v_generation_reason,v_resulting_lifecycle_state,
    v_generation.id,v_actor_user_id,v_target_event_hash,v_idempotency_key||':target-event'
  );
  update public.weekly_exceptional_pending_reconciliation_targets target
  set state=case when v_run.request_kind='WITHDRAW' then 'WITHDRAWN' else 'CONSUMED' end,
      completed_at_utc=pg_catalog.statement_timestamp()
  where target.family_id=v_family.id
    and target.durable_work_event_id=v_work_event_id
    and target.state='ACTIVE';
  if v_family_event_state='WAIT' then
    insert into public.weekly_exceptional_pending_reconciliation_targets(
      family_id,approval_id,durable_work_event_id,incident_id,current_final_revision_id,
      intended_outcome,source_action_policy_target_fingerprint,state
    ) values (
      v_family.id,v_approval.id,v_work_event_id,
      (select incident.id from public.weekly_discrepancy_incidents incident
       where incident.source_group_id=v_group.id and incident.work_event_id=v_work_event_id
       order by incident.episode_number desc limit 1),
      v_final_revision_id,v_pending_outcome,v_fixed_source_hash,'ACTIVE'
    );
  end if;
  insert into public.weekly_exceptional_payment_events(
    family_id,approval_id,event_kind,lifecycle_view,bounded_payload_json,
    idempotency_key
  ) values (
    v_family.id,v_approval.id,v_payment_event_kind,'PENDING_C1',
    pg_catalog.jsonb_build_object(
      'work_event_id',v_work_event_id,'generation_id',v_generation.id,
      'target_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'approved_pay_ex_vat',pg_catalog.to_char(v_total_pay,'FM9999999990.00')
    ),v_idempotency_key||':payment-event'
  );

  insert into public.weekly_exceptional_c1_publication_requests(
    id,family_id,generation_id,orchestration_run_id,agency_id,candidate_id,
    contract_id,root_timesheet_id,week_ending_date,source_mode,request_sequence,
    expected_head_revision,expected_source_count,expected_component_count,
    expected_payload_bytes,source_manifest_sha256,entitlement_sha256,
    approval_sha256,is_zero_entitlement,financial_row_id,request_sha256,state
  ) values (
    v_request_id,v_family.id,v_generation.id,v_run.id,v_family.agency_id,
    v_family.candidate_id,v_family.contract_id,v_root.timesheet_id,
    v_family.week_ending_date,v_source_mode,v_request_sequence,
    v_expected_head_revision,v_expected_source_count,v_expected_component_count,
    v_expected_payload_bytes,v_source_manifest_hash,v_entitlement_hash,
    v_outer_approval_hash,(v_expected_component_count=0),v_fin.id,
    v_c1_request_hash,'READY'
  ) returning * into v_publication;

  for v_source_entry in select value from pg_catalog.jsonb_array_elements(v_sources)
  loop
    v_source_ordinal:=(v_source_entry->>'source_ordinal')::integer;
    v_source_id:=(v_source_entry->>'source_id')::uuid;
    insert into public.weekly_exceptional_c1_source_records(
      id,publication_request_id,source_ordinal,authority_kind,source_system,
      external_identity,external_revision,source_document_sha256,payload_bytes,
      part_count,work_date,root_timesheet_id,candidate_id,contract_id,
      source_row_sha256
    ) values (
      v_source_id,v_publication.id,v_source_ordinal,v_source_entry->>'authority_kind',
      v_source_entry->>'source_system',v_source_entry->>'external_identity',
      v_source_entry->>'external_revision',
      private.weekly_exceptional_hex_sha256_v1(v_source_entry->>'source_document_sha256'),
      (v_source_entry->>'payload_bytes')::integer,
      (v_source_entry->>'part_count')::integer,
      nullif(v_source_entry->>'work_date','')::date,v_root.timesheet_id,
      v_family.candidate_id,v_family.contract_id,
      private.weekly_exceptional_hex_sha256_v1(v_source_entry->>'source_row_sha256')
    );
    for v_part_entry in select value from pg_catalog.jsonb_array_elements(v_source_entry->'parts')
    loop
      insert into public.weekly_exceptional_c1_source_parts(
        publication_request_id,source_record_id,source_ordinal,part_ordinal,
        payload_utf8,fragment_sha256
      ) values (
        v_publication.id,v_source_id,v_source_ordinal,
        (v_part_entry->>'part_ordinal')::integer,
        pg_catalog.decode(v_part_entry->>'payload_utf8','hex'),
        private.weekly_exceptional_hex_sha256_v1(v_part_entry->>'fragment_sha256')
      );
    end loop;
  end loop;

  for v_component_entry in select value from pg_catalog.jsonb_array_elements(v_components)
  loop
    insert into public.weekly_exceptional_c1_component_records(
      publication_request_id,component_ordinal,component_id,source_ordinal,
      source_key,component_kind,economic_key_type,economic_key_value,
      component_member_identity,segment_id,segment_key,segment_stable_key,
      work_date,reference_number,hours_day,hours_night,hours_sat,hours_sun,
      hours_bh,additional_code_raw,unit_count,unit_pay_rate,unit_charge_rate,
      expense_code,pay_ex_vat,charge_ex_vat,exclude_from_pay,
      origin,component_sha256
    ) values (
      v_publication.id,(v_component_entry->>'component_ordinal')::integer,
      (v_component_entry->>'component_id')::uuid,
      (v_component_entry->>'source_ordinal')::integer,
      v_component_entry->>'source_key',v_component_entry->>'component_kind',
      v_component_entry->>'economic_key_type',v_component_entry->>'economic_key_value',
      v_component_entry->>'component_member_identity',nullif(v_component_entry->>'segment_id',''),
      nullif(v_component_entry->>'segment_key',''),nullif(v_component_entry->>'segment_stable_key',''),
      nullif(v_component_entry->>'work_date','')::date,nullif(v_component_entry->>'reference_number',''),
      nullif(v_component_entry->>'hours_day','')::numeric,
      nullif(v_component_entry->>'hours_night','')::numeric,
      nullif(v_component_entry->>'hours_sat','')::numeric,
      nullif(v_component_entry->>'hours_sun','')::numeric,
      nullif(v_component_entry->>'hours_bh','')::numeric,
      nullif(v_component_entry->>'additional_code_raw',''),
      nullif(v_component_entry->>'unit_count','')::numeric,
      nullif(v_component_entry->>'unit_pay_rate','')::numeric,
      nullif(v_component_entry->>'unit_charge_rate','')::numeric,
      nullif(v_component_entry->>'expense_code',''),
      (v_component_entry->>'pay_ex_vat')::numeric,
      nullif(v_component_entry->>'charge_ex_vat','')::numeric,
      (v_component_entry->>'exclude_from_pay')::boolean,
      v_component_entry->>'origin',
      private.weekly_exceptional_hex_sha256_v1(v_component_entry->>'component_sha256')
    );
  end loop;

  update public.weekly_exceptional_pay_target_families
  set c1_publication_state='PENDING',bound_version=bound_version+1
  where id=v_family.id;

  v_request_body_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_C1_STAGE_REQUEST_BODY_V1',p_request
  );
  v_before_hash:=v_run.before_state_fingerprint;
  v_after_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_C1_STAGED_STATE_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'generation_id',v_generation.id,
      'publication_request_id',v_publication.id,'request_sha256',
      pg_catalog.encode(v_c1_request_hash,'hex'),'new_bound_version',v_family.bound_version+1
    )
  );
  select coalesce(max(sequence),0)+1 into v_step_sequence
  from public.weekly_exceptional_orchestration_steps where orchestration_run_id=v_run.id;
  insert into public.weekly_exceptional_orchestration_steps(
    orchestration_run_id,sequence,step_kind,idempotency_key,
    allowlisted_owner_name,allowlisted_owner_signature,bounded_request_hash,
    before_state_fingerprint,bounded_owner_response_json,owner_response_hash,
    after_state_fingerprint,outcome,completed_at_utc
  ) values (
    v_run.id,v_step_sequence,'STAGE_C1_REQUEST',v_idempotency_key,
    'public.weekly_exceptional_pay_stage_c1_request_v1','jsonb->jsonb',
    v_request_body_hash,v_before_hash,
    pg_catalog.jsonb_build_object(
      'publication_request_id',v_publication.id,'generation_id',v_generation.id,
      'request_sha256',pg_catalog.encode(v_c1_request_hash,'hex')
    ),v_after_hash,v_after_hash,'COMPLETE',pg_catalog.statement_timestamp()
  );

  if p_request ? 'automatic_reconcile_selection_sha256' then
    -- The assertion reads the actual sealed complete vector and native rows.
    -- Any refusal rolls back this entire stage, including its unaccepted event.
    perform private.weekly_source_automatic_reconcile_certificate_v1(v_publication.id,v_actor_user_id,v_cycle.id);
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'outcome','STAGED','idempotent_replay',false,
    'family_id',v_family.id,'generation_id',v_generation.id,
    'approval_id',v_approval.id,'publication_request_id',v_publication.id,
    'request_sha256',pg_catalog.encode(v_publication.request_sha256,'hex'),
    'source_count',v_expected_source_count,
    'component_count',v_expected_component_count,
    'approved_pay_ex_vat',pg_catalog.to_char(v_total_pay,'FM9999999990.00'),
    'new_family_bound_version',v_family.bound_version+1,'state','READY'
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_SCOPE_INVALID' using errcode='55000';
end;
$function$;

-- Complete native canonical catalogue exporter, no table-row reads.
create or replace function private.weekly_source_protected_qualification_current_catalogue_v1()
returns jsonb language sql stable security definer set search_path to 'pg_catalog','public'
as $function$
with
app_namespaces as (
  select oid, nspname, nspowner, nspacl
  from pg_catalog.pg_namespace
  where nspname in ('public', 'private')
),
contract_role_names as (
  select oid, case when rolname=current_user then 'postgres' else rolname end as logical_name
  from pg_catalog.pg_roles
),
extensions_contract as (
  select jsonb_agg(
    jsonb_build_object('name', e.extname, 'schema', n.nspname)
    order by e.extname collate "C"
  ) as value
  from pg_catalog.pg_extension e
  join pg_catalog.pg_namespace n on n.oid = e.extnamespace
  where e.extname in ('btree_gist', 'pgcrypto', 'pg_trgm', 'uuid-ossp')
),
enum_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'name', t.typname,
      'labels', (
        select jsonb_agg(e.enumlabel order by e.enumsortorder)
        from pg_catalog.pg_enum e
        where e.enumtypid = t.oid
      )
    ) order by n.nspname collate "C", t.typname collate "C"
  ) as value
  from pg_catalog.pg_type t
  join app_namespaces n on n.oid = t.typnamespace
  where t.typtype = 'e'
),
relation_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'name', c.relname,
      'kind', c.relkind,
      'owner', (select logical_name from contract_role_names where oid=c.relowner),
      'rls', c.relrowsecurity,
      'force_rls', c.relforcerowsecurity,
      'options', coalesce(to_jsonb(c.reloptions), '[]'::jsonb),
      'acl', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'grantee', expanded_acl.grantee,
            'privilege', expanded_acl.privilege,
            'grantable', expanded_acl.grantable
          ) order by expanded_acl.grantee collate "C",
                     expanded_acl.privilege collate "C", expanded_acl.grantable
        )
        from (
          select distinct
            case when a.grantee = 0 then 'PUBLIC'
              else (select logical_name from contract_role_names where oid=a.grantee) end as grantee,
            a.privilege_type as privilege,
            a.is_grantable as grantable
          from pg_catalog.aclexplode(coalesce(
            c.relacl,
            pg_catalog.acldefault(
              case when c.relkind = 'S' then 's'::"char" else 'r'::"char" end,
              c.relowner
            )
          )) a
        ) expanded_acl
      ), '[]'::jsonb),
      'columns', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'name', a.attname,
            'type', pg_catalog.format_type(a.atttypid, a.atttypmod),
            'not_null', a.attnotnull,
            'identity', a.attidentity,
            'generated', a.attgenerated,
            'default', pg_catalog.pg_get_expr(d.adbin, d.adrelid)
          ) order by a.attname collate "C"
        )
        from pg_catalog.pg_attribute a
        left join pg_catalog.pg_attrdef d
          on d.adrelid = a.attrelid and d.adnum = a.attnum
        where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
      ), '[]'::jsonb),
      'constraints', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'name', con.conname,
            'type', con.contype,
            'definition', pg_catalog.pg_get_constraintdef(con.oid, true),
            'deferrable', con.condeferrable,
            'deferred', con.condeferred,
            'validated', con.convalidated
          ) order by con.conname collate "C"
        )
        from pg_catalog.pg_constraint con
        where con.conrelid = c.oid
          -- PostgreSQL 18 also represents an ordinary column NOT NULL
          -- specification as a relation pg_constraint row (contype = 'n').
          -- The portable contract already seals that enforceable authority in
          -- columns[].not_null; it deliberately does not treat the generated
          -- constraint name as separate application authority.  Exclude only
          -- the exact ordinary duplicate shape.  Any future or malformed
          -- NOT NULL constraint metadata remains visible and therefore causes
          -- contract drift rather than being silently normalised away.
          and not (
            con.contype = 'n'
            and con.contypid = 0::oid
            and con.conindid = 0::oid
            and con.conparentid = 0::oid
            and con.confrelid = 0::oid
            and not con.condeferrable
            and not con.condeferred
            and con.convalidated
            and con.conislocal
            and con.coninhcount = 0
            and not con.connoinherit
            and con.conkey is not null
            and pg_catalog.cardinality(con.conkey) = 1
            and con.confkey is null
            and con.conpfeqop is null
            and con.conppeqop is null
            and con.conffeqop is null
            and con.conexclop is null
            and con.conbin is null
            and exists (
              select 1
              from pg_catalog.pg_attribute not_null_column
              where not_null_column.attrelid = con.conrelid
                and not_null_column.attnum = con.conkey[1]
                and not_null_column.attnum > 0
                and not not_null_column.attisdropped
                and not_null_column.attnotnull
            )
          )
      ), '[]'::jsonb),
      'indexes', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'name', i.relname,
            'definition', pg_catalog.pg_get_indexdef(i.oid)
          ) order by i.relname collate "C"
        )
        from pg_catalog.pg_index ix
        join pg_catalog.pg_class i on i.oid = ix.indexrelid
        where ix.indrelid = c.oid
      ), '[]'::jsonb),
      'view_definition_sha256', case when c.relkind = 'v' then
        pg_catalog.encode(
          extensions.digest(
            pg_catalog.convert_to(pg_catalog.pg_get_viewdef(c.oid, true), 'UTF8'),
            'sha256'
          ), 'hex'
        )
      else null end
    ) order by n.nspname collate "C", c.relkind, c.relname collate "C"
  ) as value
  from pg_catalog.pg_class c
  join app_namespaces n on n.oid = c.relnamespace
  where c.relkind in ('r', 'p', 'v', 'S')
    and not (
      n.nspname = 'private'
      and c.relname in (
        'cloudtms_database_identity',
        'cloudtms_database_releases',
        'cloudtms_migration_ledger',
        'cloudtms_repeatable_ledger'
      )
    )
),
routine_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'identity', p.proname || '(' || pg_catalog.pg_get_function_identity_arguments(p.oid) || ')',
      'owner', (select logical_name from contract_role_names where oid=p.proowner),
      'security_definer', p.prosecdef,
      'volatility', p.provolatile,
      'parallel', p.proparallel,
      -- plpgsql_check is development instrumentation and is not installed by
      -- every PostgreSQL provider. Its routine-local settings are excluded
      -- from the provider-neutral application contract; search_path and every
      -- other routine configuration remain authoritative.
      'config', coalesce((
        select jsonb_agg(config_value order by config_value collate "C")
        from pg_catalog.unnest(coalesce(p.proconfig, array[]::text[])) config_value
        where config_value !~ '^plpgsql_check[.]'
      ), '[]'::jsonb),
      'acl', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'grantee', expanded_acl.grantee,
            'privilege', expanded_acl.privilege,
            'grantable', expanded_acl.grantable
          ) order by expanded_acl.grantee collate "C",
                     expanded_acl.privilege collate "C", expanded_acl.grantable
        )
        from (
          select distinct
            case when a.grantee = 0 then 'PUBLIC'
              else (select logical_name from contract_role_names where oid=a.grantee) end as grantee,
            a.privilege_type as privilege,
            a.is_grantable as grantable
          from pg_catalog.aclexplode(coalesce(
            p.proacl,
            pg_catalog.acldefault('f'::"char", p.proowner)
          )) a
        ) expanded_acl
        where not (
          p.proname = 'cloudtms_data_api_mfa_gate'
          and expanded_acl.grantee = 'authenticator'
        )
      ), '[]'::jsonb),
      'definition_sha256', pg_catalog.encode(
        extensions.digest(
          pg_catalog.convert_to(
            pg_catalog.replace(
              pg_catalog.regexp_replace(
                pg_catalog.pg_get_functiondef(p.oid),
                E'\n SET "plpgsql_check\\.[^"]+" TO ''[^'']*''',
                '',
                'g'
              ),
              E'\r\n',
              E'\n'
            ),
            'UTF8'
          ),
          'sha256'
        ), 'hex'
      )
    ) order by n.nspname collate "C", p.proname collate "C",
               pg_catalog.pg_get_function_identity_arguments(p.oid) collate "C"
  ) as value
  from pg_catalog.pg_proc p
  join app_namespaces n on n.oid = p.pronamespace
  where not exists (
    select 1
    from pg_catalog.pg_depend d
    where d.classid = 'pg_proc'::regclass
      and d.objid = p.oid
      and d.deptype = 'e'
  )
),
trigger_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'table', c.relname,
      'name', t.tgname,
      'definition', pg_catalog.pg_get_triggerdef(t.oid, true),
      'enabled', t.tgenabled
    ) order by n.nspname collate "C", c.relname collate "C", t.tgname collate "C"
  ) as value
  from pg_catalog.pg_trigger t
  join pg_catalog.pg_class c on c.oid = t.tgrelid
  join app_namespaces n on n.oid = c.relnamespace
  where not t.tgisinternal
),
policy_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', schemaname,
      'table', tablename,
      'name', policyname,
      'permissive', permissive,
      'roles', coalesce((
        select jsonb_agg(
          case when role_name::text=current_user then 'postgres' else role_name::text end
          order by (case when role_name::text=current_user then 'postgres' else role_name::text end) collate "C"
        )
        from pg_catalog.unnest(roles) with ordinality as policy_role(role_name,ordinality)
      ), '[]'::jsonb),
      'command', cmd,
      'using', qual,
      'check', with_check
    ) order by schemaname collate "C", tablename collate "C", policyname collate "C"
  ) as value
  from pg_catalog.pg_policies
  where schemaname in ('public', 'private')
),
schema_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'owner', (select logical_name from contract_role_names where oid=n.nspowner),
      'acl', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'grantee', expanded_acl.grantee,
            'privilege', expanded_acl.privilege,
            'grantable', expanded_acl.grantable
          ) order by expanded_acl.grantee collate "C",
                     expanded_acl.privilege collate "C", expanded_acl.grantable
        )
        from (
          select distinct
            case when a.grantee = 0 then 'PUBLIC'
              else (select logical_name from contract_role_names where oid=a.grantee) end as grantee,
            a.privilege_type as privilege,
            a.is_grantable as grantable
          from pg_catalog.aclexplode(coalesce(
            n.nspacl,
            pg_catalog.acldefault('n'::"char", n.nspowner)
          )) a
        ) expanded_acl
      ), '[]'::jsonb)
    ) order by n.nspname collate "C"
  ) as value
  from app_namespaces n
),
default_acl_rows as (
  select
    owner_role.logical_name as owner_name,
    n.nspname as schema_name,
    d.defaclobjtype as object_kind,
    jsonb_build_object(
      'owner', owner_role.logical_name,
      'schema', n.nspname,
      'kind', d.defaclobjtype,
      'acl', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'grantee', expanded_acl.grantee,
            'privilege', expanded_acl.privilege,
            'grantable', expanded_acl.grantable
          ) order by expanded_acl.grantee collate "C",
                     expanded_acl.privilege collate "C", expanded_acl.grantable
        )
        from (
          select distinct
            case when a.grantee = 0 then 'PUBLIC'
              else (select logical_name from contract_role_names where oid=a.grantee) end as grantee,
            a.privilege_type as privilege,
            a.is_grantable as grantable
          from pg_catalog.aclexplode(coalesce(
            d.defaclacl,
            pg_catalog.acldefault(d.defaclobjtype, d.defaclrole)
          )) a
        ) expanded_acl
      ), '[]'::jsonb)
    ) as contract_row
  from pg_catalog.pg_default_acl d
  join app_namespaces n on n.oid = d.defaclnamespace
  join contract_role_names owner_role on owner_role.oid=d.defaclrole
  -- Default privileges are installation authority only for the exact role
  -- running this release.  A provider image can also contain a physical role
  -- literally named `postgres`; when CURRENT_USER is the generated service
  -- owner, importing that bootstrap role's defaults would merge two different
  -- security postures under one logical owner.
  where d.defaclrole = (
    select role_row.oid
    from pg_catalog.pg_roles role_row
    where role_row.rolname = current_user
  )
),
default_acl_contract as (
  -- Collapse byte-identical rows defensively while preserving every distinct
  -- default privilege owned by the exact installation role above.
  select jsonb_agg(
    contract_row order by owner_name collate "C",
                          schema_name collate "C", object_kind
  ) as value
  from (
    select distinct owner_name, schema_name, object_kind, contract_row
    from default_acl_rows
  ) canonical_default_acl_rows
)
select jsonb_build_object(
  'contract_version', 5,
  'extensions', coalesce((select value from extensions_contract), '[]'::jsonb),
  'schemas', coalesce((select value from schema_contract), '[]'::jsonb),
  'enums', coalesce((select value from enum_contract), '[]'::jsonb),
  'relations', coalesce((select value from relation_contract), '[]'::jsonb),
  'routines', coalesce((select value from routine_contract), '[]'::jsonb),
  'triggers', coalesce((select value from trigger_contract), '[]'::jsonb),
  'policies', coalesce((select value from policy_contract), '[]'::jsonb),
  'default_acls', coalesce((select value from default_acl_contract), '[]'::jsonb)
);
$function$;

-- SOURCE PROPOSAL ONLY. Root integrates and proves; no operational activation.
-- The only persisted relation named here is the existing audit_events owner.
-- Its scope is transaction-bound and cannot authorize another transaction.
create or replace function private.weekly_source_protected_qualification_owner_v1()
returns void language plpgsql stable security invoker set search_path to 'pg_catalog','pg_temp'
as $function$
declare owner_name name;
begin
  select pg_get_userbyid(proowner) into strict owner_name from pg_proc
    where oid='private.weekly_source_protected_qualification_owner_v1()'::regprocedure;
  if session_user is distinct from owner_name or current_user is distinct from owner_name then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_OWNER_REQUIRED' using errcode='42501'; end if;
  perform private.weekly_source_query_require_service_v1();
end;
$function$;

create or replace function private.weekly_source_protected_qualification_release_v1()
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare r private.cloudtms_database_releases%rowtype; i private.cloudtms_database_identity%rowtype;
begin
  select * into strict i from private.cloudtms_database_identity where singleton and environment='TEST';
  select * into strict r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if current_database()<>'cloudtms_test_clone' or r.status is distinct from 'VERIFIED'
    or r.completed_at_utc is null or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or r.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,schema_version}'
      is distinct from 'WEEKLY_SOURCE_QUALIFICATION_INSTALLED_CATALOGUE_V1'
    or r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,contract_sha256}' is distinct from r.installed_contract_sha256
    or r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}' is distinct from encode(
      private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_QUALIFICATION_INSTALLED_CATALOGUE_V1',
        private.weekly_source_protected_qualification_current_catalogue_v1()),'hex') then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_INSTALLED_RELEASE_REQUIRED' using errcode='55000'; end if;
  return jsonb_build_object('release_id',r.release_id,'source_commit',r.git_commit,
    'contract_sha256',r.installed_contract_sha256,'installation_id',i.installation_id,
    'environment',i.environment,'database',current_database(),
    'managed_manifest_sha256',r.evidence_json#>>'{managed_release,manifest_sha256}',
    'installed_catalogue_jsonb_sha256',r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}');
exception when no_data_found or too_many_rows then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_INSTALLED_RELEASE_REQUIRED' using errcode='55000';
end;
$function$;

-- Plain discovery only. Original signed physical identities and immutable
-- Source pay roots are sealed. Protection family/current-generation state is
-- not made a second Source authority, and a completed Client is never removed.
create or replace function private.weekly_source_protected_qualification_census_v1(p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; p public.weekly_source_projection_publications%rowtype;
  clients uuid[]; facts jsonb; cas_value jsonb; roots jsonb; items jsonb; census jsonb;
begin
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict p from public.weekly_source_projection_publications
    where id=c.current_projection_publication_id and source_cycle_id=c.id and state='CURRENT'
      and authority_scope_kind='CYCLE' and correction_session_id is null and report_scope_id is null;
  perform private.weekly_source_query_current_publication_v1(c.id,p.id);
  select coalesce(array_agg(distinct incident.client_id order by incident.client_id),'{}'::uuid[])
    into clients from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      and comparison.incident_id=incident.id
    join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id
      and work.client_id=incident.client_id and work.first_source_group_id=c.source_group_id
    join public.contracts contract on contract.id=comparison.contract_id and contract.candidate_id=work.candidate_id
      and contract.client_id=work.client_id
    where incident.source_cycle_id=c.id and incident.state='OPEN'
      and private.weekly_source_is_import_authoritative_v1(work.client_id,contract.id,work.work_date)
      and (private.weekly_source_checking_client_scope_v1(p.id) is null
        or incident.client_id=private.weekly_source_checking_client_scope_v1(p.id));
  if cardinality(clients) not between 1 and 100 then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_ORIGINAL_CLIENTS_REQUIRED' using errcode='55000'; end if;
  facts:=private.weekly_source_bulk_source_facts_v1(c.id,clients);
  cas_value:=private.weekly_source_bulk_source_cas_v1(c.id,clients);
  select coalesce(jsonb_agg(jsonb_build_object('incident_id',incident.id,'work_event_id',work.id,
    'client_id',work.client_id,'candidate_id',work.candidate_id,'contract_id',contract.id,'work_date',work.work_date,
    'comparison_revision_id',comparison.id,'evidence_timesheet_id',comparison.candidate_timesheet_id)
    order by work.candidate_id,work.id,incident.id),'[]'::jsonb) into items
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      and comparison.incident_id=incident.id
    join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id
      and work.client_id=incident.client_id and work.first_source_group_id=c.source_group_id
    join public.contracts contract on contract.id=comparison.contract_id and contract.candidate_id=work.candidate_id
      and contract.client_id=work.client_id
    where incident.source_cycle_id=c.id and incident.state='OPEN' and work.client_id=any(clients)
      and private.weekly_source_is_import_authoritative_v1(work.client_id,contract.id,work.work_date);
  if exists(select 1 from jsonb_array_elements(items) item where item->>'evidence_timesheet_id' is not null
    and not exists(select 1 from public.timesheets sheet join public.contracts contract on contract.id=sheet.contract_id
      where sheet.timesheet_id=(item->>'evidence_timesheet_id')::uuid
        and contract.id=(item->>'contract_id')::uuid and contract.candidate_id=(item->>'candidate_id')::uuid
        and contract.client_id=(item->>'client_id')::uuid
        and (sheet.client_id is null or sheet.client_id=contract.client_id))) then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SIGNED_ROOT_SCOPE_INVALID' using errcode='55000'; end if;
  with ids as (
    select (item->>'evidence_timesheet_id')::uuid id from jsonb_array_elements(items) item
      where item->>'evidence_timesheet_id' is not null
    union select (item->>'timesheet_id')::uuid from jsonb_array_elements(facts->'root_identities') item
  ) select coalesce(jsonb_agg(jsonb_build_object('timesheet_id',sheet.timesheet_id,'booking_id',sheet.booking_id,
    'contract_id',contract.id,'candidate_id',contract.candidate_id,'client_id',contract.client_id)
    order by sheet.timesheet_id),'[]'::jsonb) into roots from ids
    join public.timesheets sheet on sheet.timesheet_id=ids.id join public.contracts contract on contract.id=sheet.contract_id;
  census:=jsonb_build_object('schema_version','WEEKLY_SOURCE_QUALIFICATION_CENSUS_V1','source_cycle_id',c.id,
    'source_group_id',c.source_group_id,'week_ending',c.finalisation_week_ending,'original_client_ids',to_jsonb(clients),
    'original_root_identities',roots,'original_items',items,'source_cas',cas_value);
  return census||jsonb_build_object('census_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_QUALIFICATION_CENSUS_V1',census),'hex'));
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_SOURCE_UNAVAILABLE' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_protected_qualification_begin_v1(p_request jsonb)
returns jsonb language plpgsql volatile security invoker set search_path to 'pg_catalog','pg_temp'
as $function$
declare actor uuid; cycle_id uuid; scope_id uuid; c public.weekly_source_cycles%rowtype;
  g public.weekly_source_groups%rowtype; census jsonb; execution jsonb; scope_value jsonb; existing_count integer;
begin
  perform private.weekly_source_protected_qualification_owner_v1();
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,array['scope_id','actor_user_id','source_cycle_id',
      'expected_execution','expected_census_sha256','capabilities','reason','turn_backend_pid'])
    or not(p_request ?& array['scope_id','actor_user_id','source_cycle_id','expected_execution','expected_census_sha256','capabilities','reason','turn_backend_pid'])
    or jsonb_typeof(p_request->'capabilities') is distinct from 'array'
    or p_request->'capabilities' not in ('["BULK_SIGNED"]'::jsonb,'["AUTOMATIC_RECONCILE","BULK_SIGNED"]'::jsonb)
    or char_length(coalesce(p_request->>'reason','')) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_REQUEST_INVALID' using errcode='22023'; end if;
  actor:=(p_request->>'actor_user_id')::uuid; cycle_id:=(p_request->>'source_cycle_id')::uuid; scope_id:=(p_request->>'scope_id')::uuid;
  if actor is null or cycle_id is null or scope_id is null then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_REQUEST_INVALID' using errcode='22023'; end if;
  if not exists(select 1 from pg_locks lock_row where lock_row.locktype='advisory' and lock_row.granted
    and lock_row.mode='ExclusiveLock' and lock_row.classid=20261013::oid and lock_row.objid=1::oid and lock_row.objsubid=2
    and lock_row.pid=(p_request->>'turn_backend_pid')::integer and lock_row.pid<>pg_backend_pid()) then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SHARED_TURN_REQUIRED' using errcode='55000'; end if;
  perform private._weekly_source_settings_require_admin_v1(actor);
  select * into strict c from public.weekly_source_cycles where id=cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  perform private._weekly_source_settings_deployment_v1(g.agency_id,g.environment);
  if g.environment<>'TEST' then raise exception 'WEEKLY_SOURCE_QUALIFICATION_TEST_ONLY' using errcode='42501'; end if;
  perform private.weekly_source_office_authority_v1(actor,'APPROVE_PROTECTED_PAY',g.id,null,c.finalisation_week_ending);
  execution:=private.weekly_source_protected_qualification_release_v1();
  if execution is distinct from p_request->'expected_execution' then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_EXECUTION_CHANGED' using errcode='40001'; end if;
  if private.weekly_source_bulk_producer_ready_v1(c.id) or private.weekly_source_automatic_reconcile_producer_ready_v1(c.id) then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_OPERATIONAL_SCOPE_REFUSED' using errcode='55000'; end if;
  census:=private.weekly_source_protected_qualification_census_v1(c.id);
  if census->>'census_sha256' is distinct from p_request->>'expected_census_sha256' then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SOURCE_CHANGED' using errcode='40001'; end if;
  select count(*) into existing_count from public.audit_events audit
    where audit.object_type='weekly_source_protected_qualification' and audit.action='WEEKLY_SOURCE_QUALIFICATION_SCOPE_ADMITTED'
      and audit.after_json->>'transaction_id'=pg_current_xact_id()::text
      and audit.after_json->>'backend_pid'=pg_backend_pid()::text;
  if existing_count<>0 then raise exception 'WEEKLY_SOURCE_QUALIFICATION_SCOPE_ALREADY_ADMITTED' using errcode='23505'; end if;
  scope_value:=jsonb_build_object('schema_version','WEEKLY_SOURCE_TEST_ROLLBACK_QUALIFICATION_SCOPE_V1','scope_id',scope_id,
    'transaction_id',pg_current_xact_id()::text,'backend_pid',pg_backend_pid()::text,'database',current_database(),
    'turn_backend_pid',p_request->>'turn_backend_pid',
    'execution',execution,'actor_user_id',actor,'agency_id',g.agency_id,'source_group_id',g.id,'source_cycle_id',c.id,
    'current_local_date',(clock_timestamp() at time zone 'Europe/London')::date,'week_ending',c.finalisation_week_ending,
    'capabilities',p_request->'capabilities','original_census',census,'operational_ready',false,'max_native_steps',64);
  scope_value:=scope_value||jsonb_build_object('scope_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_TEST_ROLLBACK_QUALIFICATION_SCOPE_V1',scope_value),'hex'));
  perform public._audit_insert('weekly_source_protected_qualification',scope_id::text,'WEEKLY_SOURCE_QUALIFICATION_SCOPE_ADMITTED',
    null,scope_value,p_request->>'reason',actor);
  return scope_value;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_SCOPE_INVALID' using errcode='55000';
end;
$function$;

-- This is not producer_ready. It can be consumed only below the private,
-- owner-session dispatcher. Actual public service/API calls cannot enter it.
create or replace function private.weekly_source_protected_qualification_assert_v1(
  p_scope_id uuid,p_cycle_id uuid,p_client_ids uuid[],p_capability text
) returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare scope_value jsonb; c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  clients uuid[]; actual_cas jsonb; context_value text; scopes integer; rules jsonb; original jsonb; actual jsonb;
begin
  perform private.weekly_source_protected_qualification_owner_v1();
  get diagnostics context_value=pg_context;
  if context_value !~ 'PL/pgSQL function (private\.)?weekly_source_protected_qualification_step_v1\(uuid,text,jsonb\)' then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_CALLER_REQUIRED' using errcode='42501'; end if;
  select count(*),jsonb_agg(audit.after_json)->0 into scopes,scope_value from public.audit_events audit
    where audit.object_type='weekly_source_protected_qualification' and audit.action='WEEKLY_SOURCE_QUALIFICATION_SCOPE_ADMITTED'
      and audit.event_sequence_is_authoritative
      and audit.after_json->>'transaction_id'=pg_current_xact_id()::text
      and audit.after_json->>'backend_pid'=pg_backend_pid()::text
      and (p_scope_id is null or audit.object_id_text=p_scope_id::text);
  if scopes<>1 or scope_value->>'schema_version' is distinct from 'WEEKLY_SOURCE_TEST_ROLLBACK_QUALIFICATION_SCOPE_V1'
    or scope_value->>'database' is distinct from current_database()
    or scope_value->'operational_ready' is distinct from 'false'::jsonb
    or scope_value->>'source_cycle_id' is distinct from p_cycle_id::text
    or scope_value->>'current_local_date' is distinct from ((clock_timestamp() at time zone 'Europe/London')::date)::text
    or scope_value->>'scope_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_TEST_ROLLBACK_QUALIFICATION_SCOPE_V1',scope_value-'scope_sha256'),'hex')
    or scope_value->'execution' is distinct from private.weekly_source_protected_qualification_release_v1()
    or not exists(select 1 from pg_locks lock_row where lock_row.locktype='advisory' and lock_row.granted
      and lock_row.mode='ExclusiveLock' and lock_row.classid=20261013::oid and lock_row.objid=1::oid and lock_row.objsubid=2
      and lock_row.pid=(scope_value->>'turn_backend_pid')::integer and lock_row.pid<>pg_backend_pid())
    or p_capability not in ('BULK_SIGNED','AUTOMATIC_RECONCILE')
    or not(scope_value->'capabilities' @> jsonb_build_array(p_capability)) then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SCOPE_UNAVAILABLE' using errcode='55000'; end if;
  perform private._weekly_source_settings_require_admin_v1((scope_value->>'actor_user_id')::uuid);
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  if (g.id::text,g.agency_id::text,g.environment,c.finalisation_week_ending::text) is distinct from
    (scope_value->>'source_group_id',scope_value->>'agency_id','TEST',scope_value->>'week_ending') then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SOURCE_CHANGED' using errcode='40001'; end if;
  perform private._weekly_source_settings_deployment_v1(g.agency_id,g.environment);
  perform private.weekly_source_office_authority_v1((scope_value->>'actor_user_id')::uuid,'APPROVE_PROTECTED_PAY',g.id,null,c.finalisation_week_ending);
  select array_agg(value::uuid order by value::uuid) into clients
    from jsonb_array_elements_text(scope_value#>'{original_census,original_client_ids}') value;
  if p_client_ids is not null and to_jsonb(p_client_ids) is distinct from to_jsonb(clients) then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_ORIGINAL_CLIENT_CENSUS_CHANGED' using errcode='40001'; end if;
  actual_cas:=private.weekly_source_bulk_source_cas_v1(c.id,clients);
  if actual_cas is distinct from scope_value#>'{original_census,source_cas}' then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SOURCE_CHANGED' using errcode='40001'; end if;
  -- No mutable family/current-generation state is compared. Every original
  -- physical root identity remains; native signed/stage/inventory guards do
  -- their own version/signature/currentness work without a qualification waiver.
  for original in select value from jsonb_array_elements(scope_value#>'{original_census,original_root_identities}') value loop
    select jsonb_build_object('timesheet_id',sheet.timesheet_id,'booking_id',sheet.booking_id,'contract_id',contract.id,
      'candidate_id',contract.candidate_id,'client_id',contract.client_id) into actual
      from public.timesheets sheet join public.contracts contract on contract.id=sheet.contract_id
      where sheet.timesheet_id=(original->>'timesheet_id')::uuid and (sheet.client_id is null or sheet.client_id=contract.client_id);
    if actual is distinct from original then
      raise exception 'WEEKLY_SOURCE_QUALIFICATION_ORIGINAL_ROOT_CHANGED' using errcode='40001'; end if;
  end loop;
  if p_capability='AUTOMATIC_RECONCILE' then
    if cardinality(clients)<>1 then raise exception 'WEEKLY_SOURCE_QUALIFICATION_AUTOMATIC_SCOPE_INVALID' using errcode='55000'; end if;
    rules:=private.weekly_source_effective_rule_set_v1(clients[1],c.id)->'values';
    if rules is null or rules->>'invoice_sender' is distinct from 'CLIENT_SELF_BILL'
      or rules->>'equal_protected_hours' is distinct from 'CLEAR_AUTOMATICALLY'
      or (select automatic_reconcile_actor_user_id from public.weekly_source_global_settings where singleton)
        is distinct from (scope_value->>'actor_user_id')::uuid then
      raise exception 'WEEKLY_SOURCE_QUALIFICATION_AUTOMATIC_SCOPE_INVALID' using errcode='55000'; end if;
  end if;
  return scope_value;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_SCOPE_UNAVAILABLE' using errcode='55000';
end;
$function$;

-- Owner-only bounded native prerequisite dispatcher, never a Worker RPC.
create or replace function private.weekly_source_protected_qualification_step_v1(
  p_scope_id uuid,p_operation text,p_request jsonb
) returns jsonb language plpgsql volatile security invoker set search_path to 'pg_catalog','pg_temp'
as $function$
declare scope_value jsonb; cycle_id uuid; actor uuid; request_value jsonb; result_value jsonb;
  item jsonb; selected_event uuid; family_id uuid; request_id uuid; contract_id uuid; client_id uuid;
  candidate_id uuid; root_id uuid; native_cycle uuid; step_count integer; receipt jsonb; capability text;
begin
  perform private.weekly_source_protected_qualification_owner_v1();
  if p_scope_id is null or p_operation not in ('BULK_PREVIEW','BULK_ADMIT','BULK_ROUND','BULK_APPLY',
      'PREPARE_FAMILY','PREPARE_ACTION','ACTION_CONTEXT','STAGE_C1_REQUEST','COMPLETE_LOCAL',
      'AUTOMATIC_PREVIEW','AUTOMATIC_COMPLETE')
    or jsonb_typeof(p_request) is distinct from 'object' or octet_length(convert_to(p_request::text,'UTF8'))>262144 then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
  select (audit.after_json->>'source_cycle_id')::uuid into strict cycle_id from public.audit_events audit
    where audit.object_type='weekly_source_protected_qualification' and audit.object_id_text=p_scope_id::text
      and audit.action='WEEKLY_SOURCE_QUALIFICATION_SCOPE_ADMITTED' and audit.event_sequence_is_authoritative
      and audit.after_json->>'transaction_id'=pg_current_xact_id()::text and audit.after_json->>'backend_pid'=pg_backend_pid()::text;
  capability:=case when p_operation like 'AUTOMATIC_%' then 'AUTOMATIC_RECONCILE' else 'BULK_SIGNED' end;
  scope_value:=private.weekly_source_protected_qualification_assert_v1(p_scope_id,cycle_id,null,capability);
  actor:=(scope_value->>'actor_user_id')::uuid;
  select count(*) into step_count from public.audit_events audit
    where audit.object_type='weekly_source_protected_qualification' and audit.object_id_text=p_scope_id::text
      and audit.action='WEEKLY_SOURCE_QUALIFICATION_NATIVE_STEP_COMPLETED'
      and audit.after_json->>'transaction_id'=pg_current_xact_id()::text;
  if step_count>=(scope_value->>'max_native_steps')::integer then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_LIMIT' using errcode='54000'; end if;
  if p_request ? 'actor_user_id' and p_request->>'actor_user_id' is distinct from actor::text then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_ACTOR_MISMATCH' using errcode='42501'; end if;
  if p_operation like 'AUTOMATIC_%' then request_value:=p_request;
  else request_value:=p_request||jsonb_build_object('actor_user_id',actor); end if;
  if p_operation<>'COMPLETE_LOCAL' and request_value->>'source_cycle_id' is distinct from cycle_id::text then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_CYCLE_MISMATCH' using errcode='42501'; end if;
  if p_operation not in ('BULK_PREVIEW','BULK_ADMIT','BULK_ROUND','BULK_APPLY') then
    if p_operation in ('COMPLETE_LOCAL','AUTOMATIC_COMPLETE') then
      request_id:=(request_value->>'publication_request_id')::uuid;
      select approval.work_event_id,approval.client_id,request.contract_id,request.candidate_id,
        request.root_timesheet_id,approval.source_cycle_id into strict selected_event,client_id,contract_id,candidate_id,root_id,native_cycle
        from public.weekly_exceptional_c1_publication_requests request
        join public.weekly_exceptional_payment_approvals approval on approval.creation_orchestration_run_id=request.orchestration_run_id
          and approval.pay_target_family_id=request.family_id where request.id=request_id;
      if native_cycle is distinct from cycle_id or (p_operation='AUTOMATIC_COMPLETE'
        and request_value->>'work_event_id' is distinct from selected_event::text) then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_CYCLE_MISMATCH' using errcode='42501'; end if;
    else
      selected_event:=(request_value->>'work_event_id')::uuid;
      if p_operation='PREPARE_FAMILY' then
        contract_id:=(request_value->>'contract_id')::uuid; client_id:=(request_value->>'client_id')::uuid;
        candidate_id:=(request_value->>'candidate_id')::uuid;
      elsif p_operation<>'AUTOMATIC_PREVIEW' then
        family_id:=(request_value->>'family_id')::uuid;
        select family.contract_id,family.candidate_id,family.root_timesheet_id,contract.client_id
          into strict contract_id,candidate_id,root_id,client_id
          from public.weekly_exceptional_pay_target_families family join public.contracts contract on contract.id=family.contract_id
          where family.id=family_id and contract.candidate_id=family.candidate_id;
      end if;
    end if;
    select value into strict item from jsonb_array_elements(scope_value#>'{original_census,original_items}') value
      where value->>'work_event_id'=selected_event::text;
    if p_operation<>'AUTOMATIC_PREVIEW' and
      (item->>'contract_id',item->>'candidate_id',item->>'client_id') is distinct from
        (contract_id::text,candidate_id::text,client_id::text) then
      raise exception 'WEEKLY_SOURCE_QUALIFICATION_ORIGINAL_ITEM_CHANGED' using errcode='40001'; end if;
    if p_operation in ('PREPARE_FAMILY','ACTION_CONTEXT','STAGE_C1_REQUEST')
      and request_value->>'evidence_timesheet_id' is distinct from item->>'evidence_timesheet_id' then
      raise exception 'WEEKLY_SOURCE_QUALIFICATION_SIGNED_ROOT_SCOPE_INVALID' using errcode='42501'; end if;
    if root_id is not null and not exists(select 1 from public.timesheets sheet
      join public.contracts contract on contract.id=sheet.contract_id where sheet.timesheet_id=root_id
        and contract.id=contract_id and contract.candidate_id=candidate_id and contract.client_id=client_id
        and (sheet.client_id is null or sheet.client_id=client_id)) then
      raise exception 'WEEKLY_SOURCE_QUALIFICATION_NATIVE_ROOT_SCOPE_INVALID' using errcode='55000'; end if;
  end if;
  -- No arbitrary routine text or dynamic EXECUTE. Native owners retain payload,
  -- actor/signature/rates/financial/I-1/CAS/replay guards and existing side effects.
  case p_operation
    when 'BULK_PREVIEW' then
      if request_value->>'mode' is distinct from 'PREVIEW' then raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_protect_all_signed_atomic_v1(request_value);
    when 'BULK_ADMIT' then
      if request_value->>'mode' is distinct from 'COMMIT' or coalesce(request_value->>'phase','ADMIT')<>'ADMIT' then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_protect_all_signed_atomic_v1(request_value);
    when 'BULK_ROUND' then
      if request_value->>'mode' is distinct from 'COMMIT' or request_value->>'phase' is distinct from 'ROUND' then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_protect_all_signed_atomic_v1(request_value);
    when 'BULK_APPLY' then
      if request_value->>'mode' is distinct from 'COMMIT' or request_value->>'phase' is distinct from 'APPLY' then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_protect_all_signed_atomic_v1(request_value);
    when 'PREPARE_FAMILY' then result_value:=public.weekly_exceptional_pay_prepare_family_v1(request_value);
    when 'PREPARE_ACTION' then result_value:=public.weekly_exceptional_pay_prepare_action_v1(request_value);
    when 'ACTION_CONTEXT' then result_value:=public.weekly_exceptional_pay_action_context_v1(request_value);
    when 'STAGE_C1_REQUEST' then result_value:=public.weekly_exceptional_pay_stage_c1_request_v1(request_value);
    when 'COMPLETE_LOCAL' then result_value:=public.weekly_exceptional_pay_complete_local_v1(request_value);
    when 'AUTOMATIC_PREVIEW' then
      if request_value->>'mode' is distinct from 'PREVIEW' then raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_automatic_reconcile_atomic_v1(request_value);
    when 'AUTOMATIC_COMPLETE' then
      if request_value->>'mode' is distinct from 'COMPLETE' then raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_automatic_reconcile_atomic_v1(request_value);
  end case;
  -- Own native stage may change its protected state, not immutable Source CAS.
  perform private.weekly_source_protected_qualification_assert_v1(p_scope_id,cycle_id,null,capability);
  receipt:=jsonb_build_object('schema_version','WEEKLY_SOURCE_TEST_ROLLBACK_NATIVE_STEP_V1',
    'scope_id',p_scope_id,'scope_sha256',scope_value->>'scope_sha256','transaction_id',pg_current_xact_id()::text,
    'execution',scope_value->'execution','operation',p_operation,'actor_user_id',actor,'source_cycle_id',cycle_id,
    'request_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_QUALIFICATION_NATIVE_REQUEST_V1',request_value),'hex'),
    'result_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_QUALIFICATION_NATIVE_RESULT_V1',result_value),'hex'),
    'source_cas',scope_value#>'{original_census,source_cas}','operational_replay',false);
  perform public._audit_insert('weekly_source_protected_qualification',p_scope_id::text,
    'WEEKLY_SOURCE_QUALIFICATION_NATIVE_STEP_COMPLETED',null,receipt,'Bounded owner-run native prerequisite',actor);
  return jsonb_build_object('qualification_step',receipt,'native_result',result_value);
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_NATIVE_SCOPE_UNAVAILABLE' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_bulk_source_cas_assert_v1(p_cycle_id uuid,p_client_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_ready boolean; v_cas jsonb; v_clients uuid[];
begin
  if p_client_ids is null or array_position(p_client_ids,null::uuid) is not null then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='22023'; end if;
  select coalesce(array_agg(distinct item order by item),'{}'::uuid[]) into v_clients from unnest(p_client_ids) item;
  if to_regprocedure('private.weekly_source_bulk_producer_ready_v1(uuid)') is null
    or to_regprocedure('private.weekly_source_bulk_source_cas_v1(uuid,uuid[])') is null then
    raise exception 'WEEKLY_SOURCE_BULK_PRODUCER_UNAVAILABLE' using errcode='55000'; end if;
  execute 'select private.weekly_source_bulk_producer_ready_v1($1)' into v_ready using p_cycle_id;
  if v_ready is distinct from true then
    begin
      perform private.weekly_source_protected_qualification_assert_v1(null,p_cycle_id,v_clients,'BULK_SIGNED');
    exception when sqlstate '42501' or sqlstate '55000' then
      raise exception 'WEEKLY_SOURCE_BULK_PRODUCER_UNAVAILABLE' using errcode='55000';
    end;
  end if;
  execute 'select private.weekly_source_bulk_source_cas_v1($1,$2)' into v_cas using p_cycle_id,v_clients;
  if not private.weekly_exceptional_json_keys_exact_v1(v_cas,array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or not(v_cas ?& array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or v_cas->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_SOURCE_CAS_V1'
    or v_cas->>'source_cycle_id' is distinct from p_cycle_id::text
    or v_cas->'client_ids' is distinct from to_jsonb(v_clients)
    or coalesce(v_cas->>'source_cas_sha256','') !~ '^[0-9a-f]{64}$' then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='55000'; end if;
  return v_cas;
end;
$function$;

create or replace function private.weekly_source_protected_non_self_bill_mode_v1(
  p_client_id uuid,p_contract_id uuid,p_work_date date,p_cycle_id uuid
) returns text language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; policy jsonb; qualification jsonb; declared_client uuid;
begin
  if p_client_id is null or p_contract_id is null or p_work_date is null or p_cycle_id is null then return null; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  policy:=private._weekly_source_effective_policy_v1(p_client_id,p_contract_id,p_work_date);
  if policy->'self_bill_enabled' is distinct from 'false'::jsonb or policy->>'c1_source_mode' is not null
    or policy->>'source_group_id' is distinct from c.source_group_id::text
    or policy->>'source_family' is distinct from 'ROSTER'
    or private.weekly_source_is_import_authoritative_v1(p_client_id,p_contract_id,p_work_date) is distinct from true
    or not exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=c.source_group_id
      and member.client_id=p_client_id and c.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date)) then return null; end if;
  declared_client:=private.weekly_source_checking_client_scope_v1(c.current_projection_publication_id);
  if declared_client is not null and declared_client<>p_client_id then return null; end if;
  begin
    qualification:=private.weekly_source_protected_capability_receipt_v1(c.id);
  exception when sqlstate '55000' or no_data_found or too_many_rows then
    begin
      qualification:=private.weekly_source_protected_qualification_assert_v1(null,c.id,null,'BULK_SIGNED');
    exception when sqlstate '42501' or sqlstate '55000' then return null;
    end;
    if not(qualification#>'{original_census,original_client_ids}' @> jsonb_build_array(p_client_id)) then return null; end if;
  end;
  if not(qualification->'capabilities' @> '["BULK_SIGNED"]'::jsonb) then return null; end if;
  return 'HEALTHROSTER_WEEKLY';
exception when no_data_found or too_many_rows or sqlstate '55000' then return null;
end;
$function$;

create or replace function private.weekly_source_automatic_reconcile_capability_assert_v1(p_cycle_id uuid)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_ready boolean;
begin
  if to_regprocedure('private.weekly_source_automatic_reconcile_producer_ready_v1(uuid)') is null
    or to_regprocedure('private.weekly_source_automatic_reconcile_delta_assert_v1(uuid,uuid)') is null then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
  execute 'select private.weekly_source_automatic_reconcile_producer_ready_v1($1)' into v_ready using p_cycle_id;
  if v_ready is distinct from true then
    begin
      perform private.weekly_source_protected_qualification_assert_v1(null,p_cycle_id,null,'AUTOMATIC_RECONCILE');
    exception when sqlstate '42501' or sqlstate '55000' then
      raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000';
    end;
  end if;
end;
$function$;

-- Protected writer alone records these real R1 receipts on R2. The R1
-- identity is retained, and the writer compares the complete committed native
-- source set byte-for-byte. No ledger/status/receipt is edited by this reader.
create or replace function private.weekly_source_protected_prerequisite_release_assert_v2(
  p_q jsonb,p_group_id uuid,p_from date,p_to date,p_expected_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare g public.weekly_source_groups%rowtype; r private.cloudtms_database_releases%rowtype;
  executed private.cloudtms_database_releases%rowtype; q jsonb:=p_q; entry jsonb; needed text[]; source_value jsonb;
begin
  select * into strict g from public.weekly_source_groups where id=p_group_id and active and source_family='ROSTER';
  select * into strict r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  select * into strict executed from private.cloudtms_database_releases where release_id=q#>>'{execution_identity,release_id}';
  if not private.weekly_exceptional_json_keys_exact_v1(q,array['schema_version','phase','release_id','git_commit','contract_sha256',
      'agency_id','environment','source_group_id','effective_from_week_ending','effective_to_week_ending','capabilities',
      'execution_identity','source_equivalence','gate_receipts','required_operational_replay','qualification_sha256'])
    or not(q ?& array['schema_version','phase','release_id','git_commit','contract_sha256','agency_id','environment','source_group_id',
      'effective_from_week_ending','effective_to_week_ending','capabilities','execution_identity','source_equivalence','gate_receipts',
      'required_operational_replay','qualification_sha256'])
    or q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_PREREQUISITE_QUALIFICATION_V2'
    or q->>'phase' is distinct from 'PREREQUISITES_QUALIFIED_OPERATIONAL_REPLAY_PENDING'
    or current_database()<>'cloudtms_test_clone' or g.environment<>'TEST'
    or r.status<>'VERIFIED' or r.completed_at_utc is null or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or r.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or not private.weekly_exceptional_json_keys_exact_v1(q->'execution_identity',array['release_id','source_commit','contract_sha256',
      'installation_id','agency_id','environment','database','managed_manifest_sha256','installed_catalogue_jsonb_sha256'])
    or q->>'release_id' is distinct from r.release_id or q->>'git_commit' is distinct from r.git_commit
    or q->>'contract_sha256' is distinct from r.installed_contract_sha256
    or q->>'agency_id' is distinct from g.agency_id::text or q->>'source_group_id' is distinct from g.id::text
    or q->>'environment' is distinct from 'TEST' or q->>'effective_from_week_ending' is distinct from p_from::text
    or q->>'effective_to_week_ending' is distinct from p_to::text
    or q->>'qualification_sha256' is distinct from p_expected_sha256
    or coalesce(q->>'qualification_sha256','') !~ '^[0-9a-f]{64}$'
    or encode(private.weekly_source_sha256_jsonb_v1(q->>'schema_version',q-'qualification_sha256'),'hex')
      is distinct from q->>'qualification_sha256'
    or executed.release_id=r.release_id or executed.status<>'VERIFIED' or executed.completed_at_utc is null
    or executed.git_commit is distinct from q#>>'{execution_identity,source_commit}'
    or executed.installed_contract_sha256 is distinct from executed.repository_contract_sha256
    or executed.installed_contract_sha256 is distinct from r.installed_contract_sha256
    or executed.installed_contract_sha256 is distinct from q#>>'{execution_identity,contract_sha256}'
    or q#>>'{execution_identity,managed_manifest_sha256}' is distinct from executed.evidence_json#>>'{managed_release,manifest_sha256}'
    or q#>>'{execution_identity,installed_catalogue_jsonb_sha256}'
      is distinct from executed.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}'
    or q#>>'{execution_identity,installed_catalogue_jsonb_sha256}'
      is distinct from r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}'
    or q#>>'{execution_identity,agency_id}' is distinct from g.agency_id::text
    or q#>>'{execution_identity,environment}' is distinct from 'TEST'
    or q#>>'{execution_identity,database}' is distinct from current_database()
    or not exists(select 1 from private.cloudtms_database_identity identity where identity.singleton and identity.environment='TEST'
      and identity.installation_id::text=q#>>'{execution_identity,installation_id}')
    or executed.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or executed.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or q->'required_operational_replay' is distinct from '["CONTROLLED_ACTIVATION_POSITIVE_NEGATIVE_CAS", "REAL_CLIENT_API_PREVIEW_COMMIT_RETRY_ERROR_ORDER", "REAL_OFFICE_UI_DEEP_LINK_ACTIONS", "REAL_MYTMS_SIGNED_DOCUMENT_AND_APP", "REAL_POST_ACTIVATION_NATIVE_LEGACY_NEXT_REPLAY", "REAL_POST_ACTIVATION_SOURCE_ROUTING"]'::jsonb then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  source_value:=q->'source_equivalence';
  if not private.weekly_exceptional_json_keys_exact_v1(source_value,array['schema_version','execution_source_commit',
      'installation_source_commit','files','source_equivalence_sha256'])
    or source_value->>'schema_version' is distinct from 'WEEKLY_SOURCE_COMMITTED_NATIVE_SOURCE_EQUIVALENCE_V1'
    or source_value->>'execution_source_commit' is distinct from executed.git_commit
    or source_value->>'installation_source_commit' is distinct from r.git_commit
    or jsonb_typeof(source_value->'files') is distinct from 'array'
    or case when jsonb_typeof(source_value->'files')='array' then jsonb_array_length(source_value->'files')=0 else true end
    or source_value->>'source_equivalence_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_COMMITTED_NATIVE_SOURCE_EQUIVALENCE_V1',source_value-'source_equivalence_sha256'),'hex')
    or (select count(distinct file->>'path') from jsonb_array_elements(source_value->'files') file)
      <>jsonb_array_length(source_value->'files')
    or exists(select 1 from jsonb_array_elements(source_value->'files') file where
      not private.weekly_exceptional_json_keys_exact_v1(file,array['path','sha256'])
      or not(file ?& array['path','sha256']) or nullif(file->>'path','') is null
      or coalesce(file->>'sha256','') !~ '^[0-9a-f]{64}$')
    or jsonb_typeof(q->'capabilities') is distinct from 'array'
    or q->'capabilities' not in ('["BULK_SIGNED"]'::jsonb,'["AUTOMATIC_RECONCILE","BULK_SIGNED"]'::jsonb)
    or jsonb_typeof(q->'gate_receipts') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  needed:=array['SOURCE_CAS_NATIVE','NATIVE_PROTECTION','SECURITY','LEGACY_PAY','NEXT_PAY','CLIENT_API','DOCUMENT','OWN_STAGE_CAS','SOURCE_ROUTING'];
  if q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb then needed:=array_append(needed,'AUTOMATIC_COMPONENT_DELTA'); end if;
  if jsonb_array_length(q->'gate_receipts')<>cardinality(needed)
    or (select count(distinct value->>'gate') from jsonb_array_elements(q->'gate_receipts') value)<>cardinality(needed) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  for entry in select value from jsonb_array_elements(q->'gate_receipts') value loop
    if not private.weekly_exceptional_json_keys_exact_v1(entry,array['gate','status','execution','receipt_id','receipt_sha256',
        'execution_release_id','execution_source_commit','execution_contract_sha256','execution_installation_id','scope_id',
        'scope_sha256','transaction_id','source_cycle_id','week_ending','original_census_sha256','source_cas_sha256'])
      or not(entry ?& array['gate','status','execution','receipt_id','receipt_sha256','execution_release_id','execution_source_commit',
        'execution_contract_sha256','execution_installation_id','scope_id','scope_sha256','transaction_id','source_cycle_id','week_ending','original_census_sha256','source_cas_sha256'])
      or not(coalesce(entry->>'gate','')=any(needed)) or entry->>'status' is distinct from 'PREREQUISITE_PASS'
      or entry->>'execution' is distinct from 'AGENCY_TEST_NATIVE_ROLLBACK'
      or entry->>'execution_release_id' is distinct from executed.release_id
      or entry->>'execution_source_commit' is distinct from executed.git_commit
      or entry->>'execution_contract_sha256' is distinct from executed.installed_contract_sha256
      or entry->>'execution_installation_id' is distinct from q#>>'{execution_identity,installation_id}'
      or coalesce(entry->>'scope_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or coalesce(entry->>'transaction_id','') !~ '^[0-9]+$'
      or coalesce(entry->>'source_cycle_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or coalesce(entry->>'week_ending','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      or (entry->>'week_ending')::date<p_from or (p_to is not null and (entry->>'week_ending')::date>p_to)
      or nullif(entry->>'receipt_id','') is null
      or exists(select 1 from unnest(array['receipt_sha256','scope_sha256','original_census_sha256','source_cas_sha256']) field
        where coalesce(entry->>field,'') !~ '^[0-9a-f]{64}$') then
      raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  end loop;
  return q;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_protected_capability_release_evidence_v1(
  p_group_id uuid,p_from date,p_to date,p_expected_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare g public.weekly_source_groups%rowtype; r private.cloudtms_database_releases%rowtype;
  q jsonb; entry jsonb; count_rows integer; needed text[]; cap text;
begin
  select * into strict g from public.weekly_source_groups where id=p_group_id and active and source_family='ROSTER';
  select * into r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if not found or r.status<>'VERIFIED' or r.completed_at_utc is null
    or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or g.environment<>'TEST' or current_database()<>'cloudtms_test_clone'
    or not exists(select 1 from private.cloudtms_database_identity where singleton and environment=g.environment)
    or r.evidence_json#>>'{managed_release,environment}' is distinct from g.environment
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or jsonb_typeof(r.evidence_json->'weekly_source_protected_capability_qualifications') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  select count(*),jsonb_agg(value)->0 into count_rows,q
    from jsonb_array_elements(r.evidence_json->'weekly_source_protected_capability_qualifications') value
    where value->>'source_group_id'=g.id::text and value->>'effective_from_week_ending'=p_from::text
      and value->>'effective_to_week_ending' is not distinct from p_to::text;
  if count_rows=1 and q->>'schema_version'='WEEKLY_SOURCE_PROTECTED_CAPABILITY_PREREQUISITE_QUALIFICATION_V2' then
    return private.weekly_source_protected_prerequisite_release_assert_v2(q,p_group_id,p_from,p_to,p_expected_sha256);
  end if;
  if count_rows<>1 or not private.weekly_exceptional_json_keys_exact_v1(q,array[
      'schema_version','release_id','git_commit','contract_sha256','agency_id','environment','source_group_id',
      'effective_from_week_ending','effective_to_week_ending','capabilities','gate_receipts','qualification_sha256'])
    or not(q ?& array['schema_version','release_id','git_commit','contract_sha256','agency_id','environment','source_group_id',
      'effective_from_week_ending','effective_to_week_ending','capabilities','gate_receipts','qualification_sha256'])
    or q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1'
    or q->>'release_id' is distinct from r.release_id or q->>'git_commit' is distinct from r.git_commit
    or q->>'contract_sha256' is distinct from r.installed_contract_sha256
    or q->>'agency_id' is distinct from g.agency_id::text or q->>'environment' is distinct from g.environment
    or coalesce(q->>'qualification_sha256','') !~ '^[0-9a-f]{64}$'
    or q->>'qualification_sha256' is distinct from p_expected_sha256
    or encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1',q-'qualification_sha256'),'hex')
      is distinct from q->>'qualification_sha256'
    or jsonb_typeof(q->'capabilities') is distinct from 'array' or jsonb_array_length(q->'capabilities') not between 1 and 2
    or exists(select 1 from jsonb_array_elements(q->'capabilities') value where jsonb_typeof(value)<>'string'
      or value#>>'{}' not in ('BULK_SIGNED','AUTOMATIC_RECONCILE'))
    or (select count(distinct value) from jsonb_array_elements(q->'capabilities') value)<>jsonb_array_length(q->'capabilities')
    or (q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb and not(q->'capabilities' @> '["BULK_SIGNED"]'::jsonb))
    or jsonb_typeof(q->'gate_receipts') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  needed:=array['SOURCE_CAS_NATIVE','NATIVE_PROTECTION','SECURITY','LEGACY_PAY','NEXT_PAY','CLIENT_API','DOCUMENT','OWN_STAGE_CAS','SOURCE_ROUTING'];
  if q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb then needed:=array_append(needed,'AUTOMATIC_COMPONENT_DELTA'); end if;
  if jsonb_array_length(q->'gate_receipts')<>cardinality(needed)
    or (select count(distinct value->>'gate') from jsonb_array_elements(q->'gate_receipts') value)<>cardinality(needed) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  for entry in select value from jsonb_array_elements(q->'gate_receipts') value loop
    if not private.weekly_exceptional_json_keys_exact_v1(entry,array['gate','status','execution','database','receipt_id','receipt_sha256',
        'source_commit','contract_sha256','source_group_id','agency_id','environment'])
      or not(entry ?& array['gate','status','execution','database','receipt_id','receipt_sha256',
        'source_commit','contract_sha256','source_group_id','agency_id','environment'])
      or not(coalesce(entry->>'gate','')=any(needed)) or entry->>'status' is distinct from 'PASS'
      or entry->>'execution' is distinct from 'AGENCY_TEST_NATIVE' or entry->>'database' is distinct from current_database()
      or entry->>'source_commit' is distinct from r.git_commit or entry->>'contract_sha256' is distinct from r.installed_contract_sha256
      or entry->>'source_group_id' is distinct from g.id::text or entry->>'agency_id' is distinct from g.agency_id::text
      or entry->>'environment' is distinct from g.environment or nullif(btrim(entry->>'receipt_id'),'') is null
      or char_length(entry->>'receipt_id')>256 or coalesce(entry->>'receipt_sha256','') !~ '^[0-9a-f]{64}$' then
      raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  end loop;
  return q;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000';
end;
$function$;

-- Complete native canonical catalogue exporter, no table-row reads.
create or replace function private.weekly_source_protected_qualification_current_catalogue_v1()
returns jsonb language sql stable security definer set search_path to 'pg_catalog','public'
as $function$
with
app_namespaces as (
  select oid, nspname, nspowner, nspacl
  from pg_catalog.pg_namespace
  where nspname in ('public', 'private')
),
contract_role_names as (
  select oid, case when rolname=current_user then 'postgres' else rolname end as logical_name
  from pg_catalog.pg_roles
),
extensions_contract as (
  select jsonb_agg(
    jsonb_build_object('name', e.extname, 'schema', n.nspname)
    order by e.extname collate "C"
  ) as value
  from pg_catalog.pg_extension e
  join pg_catalog.pg_namespace n on n.oid = e.extnamespace
  where e.extname in ('btree_gist', 'pgcrypto', 'pg_trgm', 'uuid-ossp')
),
enum_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'name', t.typname,
      'labels', (
        select jsonb_agg(e.enumlabel order by e.enumsortorder)
        from pg_catalog.pg_enum e
        where e.enumtypid = t.oid
      )
    ) order by n.nspname collate "C", t.typname collate "C"
  ) as value
  from pg_catalog.pg_type t
  join app_namespaces n on n.oid = t.typnamespace
  where t.typtype = 'e'
),
relation_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'name', c.relname,
      'kind', c.relkind,
      'owner', (select logical_name from contract_role_names where oid=c.relowner),
      'rls', c.relrowsecurity,
      'force_rls', c.relforcerowsecurity,
      'options', coalesce(to_jsonb(c.reloptions), '[]'::jsonb),
      'acl', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'grantee', expanded_acl.grantee,
            'privilege', expanded_acl.privilege,
            'grantable', expanded_acl.grantable
          ) order by expanded_acl.grantee collate "C",
                     expanded_acl.privilege collate "C", expanded_acl.grantable
        )
        from (
          select distinct
            case when a.grantee = 0 then 'PUBLIC'
              else (select logical_name from contract_role_names where oid=a.grantee) end as grantee,
            a.privilege_type as privilege,
            a.is_grantable as grantable
          from pg_catalog.aclexplode(coalesce(
            c.relacl,
            pg_catalog.acldefault(
              case when c.relkind = 'S' then 's'::"char" else 'r'::"char" end,
              c.relowner
            )
          )) a
        ) expanded_acl
      ), '[]'::jsonb),
      'columns', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'name', a.attname,
            'type', pg_catalog.format_type(a.atttypid, a.atttypmod),
            'not_null', a.attnotnull,
            'identity', a.attidentity,
            'generated', a.attgenerated,
            'default', pg_catalog.pg_get_expr(d.adbin, d.adrelid)
          ) order by a.attname collate "C"
        )
        from pg_catalog.pg_attribute a
        left join pg_catalog.pg_attrdef d
          on d.adrelid = a.attrelid and d.adnum = a.attnum
        where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
      ), '[]'::jsonb),
      'constraints', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'name', con.conname,
            'type', con.contype,
            'definition', pg_catalog.pg_get_constraintdef(con.oid, true),
            'deferrable', con.condeferrable,
            'deferred', con.condeferred,
            'validated', con.convalidated
          ) order by con.conname collate "C"
        )
        from pg_catalog.pg_constraint con
        where con.conrelid = c.oid
          -- PostgreSQL 18 also represents an ordinary column NOT NULL
          -- specification as a relation pg_constraint row (contype = 'n').
          -- The portable contract already seals that enforceable authority in
          -- columns[].not_null; it deliberately does not treat the generated
          -- constraint name as separate application authority.  Exclude only
          -- the exact ordinary duplicate shape.  Any future or malformed
          -- NOT NULL constraint metadata remains visible and therefore causes
          -- contract drift rather than being silently normalised away.
          and not (
            con.contype = 'n'
            and con.contypid = 0::oid
            and con.conindid = 0::oid
            and con.conparentid = 0::oid
            and con.confrelid = 0::oid
            and not con.condeferrable
            and not con.condeferred
            and con.convalidated
            and con.conislocal
            and con.coninhcount = 0
            and not con.connoinherit
            and con.conkey is not null
            and pg_catalog.cardinality(con.conkey) = 1
            and con.confkey is null
            and con.conpfeqop is null
            and con.conppeqop is null
            and con.conffeqop is null
            and con.conexclop is null
            and con.conbin is null
            and exists (
              select 1
              from pg_catalog.pg_attribute not_null_column
              where not_null_column.attrelid = con.conrelid
                and not_null_column.attnum = con.conkey[1]
                and not_null_column.attnum > 0
                and not not_null_column.attisdropped
                and not_null_column.attnotnull
            )
          )
      ), '[]'::jsonb),
      'indexes', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'name', i.relname,
            'definition', pg_catalog.pg_get_indexdef(i.oid)
          ) order by i.relname collate "C"
        )
        from pg_catalog.pg_index ix
        join pg_catalog.pg_class i on i.oid = ix.indexrelid
        where ix.indrelid = c.oid
      ), '[]'::jsonb),
      'view_definition_sha256', case when c.relkind = 'v' then
        pg_catalog.encode(
          extensions.digest(
            pg_catalog.convert_to(pg_catalog.pg_get_viewdef(c.oid, true), 'UTF8'),
            'sha256'
          ), 'hex'
        )
      else null end
    ) order by n.nspname collate "C", c.relkind, c.relname collate "C"
  ) as value
  from pg_catalog.pg_class c
  join app_namespaces n on n.oid = c.relnamespace
  where c.relkind in ('r', 'p', 'v', 'S')
    and not (
      n.nspname = 'private'
      and c.relname in (
        'cloudtms_database_identity',
        'cloudtms_database_releases',
        'cloudtms_migration_ledger',
        'cloudtms_repeatable_ledger'
      )
    )
),
routine_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'identity', p.proname || '(' || pg_catalog.pg_get_function_identity_arguments(p.oid) || ')',
      'owner', (select logical_name from contract_role_names where oid=p.proowner),
      'security_definer', p.prosecdef,
      'volatility', p.provolatile,
      'parallel', p.proparallel,
      -- plpgsql_check is development instrumentation and is not installed by
      -- every PostgreSQL provider. Its routine-local settings are excluded
      -- from the provider-neutral application contract; search_path and every
      -- other routine configuration remain authoritative.
      'config', coalesce((
        select jsonb_agg(config_value order by config_value collate "C")
        from pg_catalog.unnest(coalesce(p.proconfig, array[]::text[])) config_value
        where config_value !~ '^plpgsql_check[.]'
      ), '[]'::jsonb),
      'acl', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'grantee', expanded_acl.grantee,
            'privilege', expanded_acl.privilege,
            'grantable', expanded_acl.grantable
          ) order by expanded_acl.grantee collate "C",
                     expanded_acl.privilege collate "C", expanded_acl.grantable
        )
        from (
          select distinct
            case when a.grantee = 0 then 'PUBLIC'
              else (select logical_name from contract_role_names where oid=a.grantee) end as grantee,
            a.privilege_type as privilege,
            a.is_grantable as grantable
          from pg_catalog.aclexplode(coalesce(
            p.proacl,
            pg_catalog.acldefault('f'::"char", p.proowner)
          )) a
        ) expanded_acl
        where not (
          p.proname = 'cloudtms_data_api_mfa_gate'
          and expanded_acl.grantee = 'authenticator'
        )
      ), '[]'::jsonb),
      'definition_sha256', pg_catalog.encode(
        extensions.digest(
          pg_catalog.convert_to(
            pg_catalog.replace(
              pg_catalog.regexp_replace(
                pg_catalog.pg_get_functiondef(p.oid),
                E'\n SET "plpgsql_check\\.[^"]+" TO ''[^'']*''',
                '',
                'g'
              ),
              E'\r\n',
              E'\n'
            ),
            'UTF8'
          ),
          'sha256'
        ), 'hex'
      )
    ) order by n.nspname collate "C", p.proname collate "C",
               pg_catalog.pg_get_function_identity_arguments(p.oid) collate "C"
  ) as value
  from pg_catalog.pg_proc p
  join app_namespaces n on n.oid = p.pronamespace
  where not exists (
    select 1
    from pg_catalog.pg_depend d
    where d.classid = 'pg_proc'::regclass
      and d.objid = p.oid
      and d.deptype = 'e'
  )
),
trigger_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'table', c.relname,
      'name', t.tgname,
      'definition', pg_catalog.pg_get_triggerdef(t.oid, true),
      'enabled', t.tgenabled
    ) order by n.nspname collate "C", c.relname collate "C", t.tgname collate "C"
  ) as value
  from pg_catalog.pg_trigger t
  join pg_catalog.pg_class c on c.oid = t.tgrelid
  join app_namespaces n on n.oid = c.relnamespace
  where not t.tgisinternal
),
policy_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', schemaname,
      'table', tablename,
      'name', policyname,
      'permissive', permissive,
      'roles', coalesce((
        select jsonb_agg(
          case when role_name::text=current_user then 'postgres' else role_name::text end
          order by (case when role_name::text=current_user then 'postgres' else role_name::text end) collate "C"
        )
        from pg_catalog.unnest(roles) with ordinality as policy_role(role_name,ordinality)
      ), '[]'::jsonb),
      'command', cmd,
      'using', qual,
      'check', with_check
    ) order by schemaname collate "C", tablename collate "C", policyname collate "C"
  ) as value
  from pg_catalog.pg_policies
  where schemaname in ('public', 'private')
),
schema_contract as (
  select jsonb_agg(
    jsonb_build_object(
      'schema', n.nspname,
      'owner', (select logical_name from contract_role_names where oid=n.nspowner),
      'acl', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'grantee', expanded_acl.grantee,
            'privilege', expanded_acl.privilege,
            'grantable', expanded_acl.grantable
          ) order by expanded_acl.grantee collate "C",
                     expanded_acl.privilege collate "C", expanded_acl.grantable
        )
        from (
          select distinct
            case when a.grantee = 0 then 'PUBLIC'
              else (select logical_name from contract_role_names where oid=a.grantee) end as grantee,
            a.privilege_type as privilege,
            a.is_grantable as grantable
          from pg_catalog.aclexplode(coalesce(
            n.nspacl,
            pg_catalog.acldefault('n'::"char", n.nspowner)
          )) a
        ) expanded_acl
      ), '[]'::jsonb)
    ) order by n.nspname collate "C"
  ) as value
  from app_namespaces n
),
default_acl_rows as (
  select
    owner_role.logical_name as owner_name,
    n.nspname as schema_name,
    d.defaclobjtype as object_kind,
    jsonb_build_object(
      'owner', owner_role.logical_name,
      'schema', n.nspname,
      'kind', d.defaclobjtype,
      'acl', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'grantee', expanded_acl.grantee,
            'privilege', expanded_acl.privilege,
            'grantable', expanded_acl.grantable
          ) order by expanded_acl.grantee collate "C",
                     expanded_acl.privilege collate "C", expanded_acl.grantable
        )
        from (
          select distinct
            case when a.grantee = 0 then 'PUBLIC'
              else (select logical_name from contract_role_names where oid=a.grantee) end as grantee,
            a.privilege_type as privilege,
            a.is_grantable as grantable
          from pg_catalog.aclexplode(coalesce(
            d.defaclacl,
            pg_catalog.acldefault(d.defaclobjtype, d.defaclrole)
          )) a
        ) expanded_acl
      ), '[]'::jsonb)
    ) as contract_row
  from pg_catalog.pg_default_acl d
  join app_namespaces n on n.oid = d.defaclnamespace
  join contract_role_names owner_role on owner_role.oid=d.defaclrole
  -- Default privileges are installation authority only for the exact role
  -- running this release.  A provider image can also contain a physical role
  -- literally named `postgres`; when CURRENT_USER is the generated service
  -- owner, importing that bootstrap role's defaults would merge two different
  -- security postures under one logical owner.
  where d.defaclrole = (
    select role_row.oid
    from pg_catalog.pg_roles role_row
    where role_row.rolname = current_user
  )
),
default_acl_contract as (
  -- Collapse byte-identical rows defensively while preserving every distinct
  -- default privilege owned by the exact installation role above.
  select jsonb_agg(
    contract_row order by owner_name collate "C",
                          schema_name collate "C", object_kind
  ) as value
  from (
    select distinct owner_name, schema_name, object_kind, contract_row
    from default_acl_rows
  ) canonical_default_acl_rows
)
select jsonb_build_object(
  'contract_version', 5,
  'extensions', coalesce((select value from extensions_contract), '[]'::jsonb),
  'schemas', coalesce((select value from schema_contract), '[]'::jsonb),
  'enums', coalesce((select value from enum_contract), '[]'::jsonb),
  'relations', coalesce((select value from relation_contract), '[]'::jsonb),
  'routines', coalesce((select value from routine_contract), '[]'::jsonb),
  'triggers', coalesce((select value from trigger_contract), '[]'::jsonb),
  'policies', coalesce((select value from policy_contract), '[]'::jsonb),
  'default_acls', coalesce((select value from default_acl_contract), '[]'::jsonb)
);
$function$;

-- Complete forward schema correction; frozen predecessor remains evidence.
-- Root-review owner-private Source census. It never reads protection-stage
-- tables or mutable Timesheet/TSFIN lifecycle, and never makes a pay decision.
create or replace function private.weekly_source_bulk_source_facts_v1(p_cycle_id uuid,p_client_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  p public.weekly_source_projection_publications%rowtype; u public.weekly_source_uploads%rowtype;
  clients uuid[]; facts jsonb; actual_client uuid;
begin
  if p_cycle_id is null or p_client_ids is null or array_position(p_client_ids,null::uuid) is not null then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='22023'; end if;
  select coalesce(array_agg(distinct value order by value),'{}'::uuid[]) into clients from unnest(p_client_ids) value;
  if cardinality(clients)>100 then raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_SCOPE_TOO_LARGE' using errcode='54000'; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  select * into strict p from public.weekly_source_projection_publications where id=c.current_projection_publication_id
    and source_cycle_id=c.id and state='CURRENT' and authority_scope_kind='CYCLE' and correction_session_id is null and report_scope_id is null;
  select * into strict u from public.weekly_source_uploads where id=c.current_complete_upload_id and id=p.upload_id
    and source_cycle_id=c.id and state='CURRENT' and report_scope_id is null;
  perform private.weekly_source_query_current_publication_v1(c.id,p.id);
  actual_client:=private.weekly_source_checking_client_scope_v1(p.id);
  if exists(select 1 from unnest(clients) client where (actual_client is not null and actual_client<>client)
    or not exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=g.id and member.client_id=client
      and daterange(member.valid_from,coalesce(member.valid_to,'infinity'::date),'[]')
        && daterange(coalesce(u.confirmed_coverage_start_local_date,c.finalisation_week_ending-6),
          coalesce(u.confirmed_coverage_end_local_date,c.finalisation_week_ending),'[]'))) then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_CLIENT_SCOPE_CHANGED' using errcode='40001'; end if;
  -- CTE scope comes from saved Source parents. Incident IDs contribute stable
  -- work-event scope irrespective of OPEN/CLOSED; their mutable rows do not.
  with report_scopes as materialized (
    select scope.* from public.weekly_source_report_scopes scope where scope.source_group_id=g.id
      and scope.client_id=any(clients) and scope.self_bill_report_id is not null
  ), report_bindings as materialized (
    select binding.* from public.weekly_source_self_bill_report_line_bindings binding
      join public.weekly_source_self_bill_reports report on report.id=binding.self_bill_report_id
      where report.source_group_id=g.id and report.client_id=any(clients) and binding.state='CURRENT'
  ), publications as materialized (
    select publication.* from public.weekly_source_projection_publications publication where publication.id=p.id
      or publication.id in(select current_projection_publication_id from report_scopes)
      or publication.id in(select export_projection_publication_id from report_bindings)
  ), uploads as materialized (
    select upload.* from public.weekly_source_uploads upload where upload.id=u.id
      or upload.id in(select upload_id from publications)
  ), source_rows as materialized (
    select row_data.* from public.weekly_source_upload_rows row_data where row_data.upload_id in(select id from uploads)
  ), resolutions as materialized (
    select resolution.* from public.weekly_source_row_resolutions resolution
      join source_rows row_data on row_data.id=resolution.upload_row_id
      join publications publication on publication.upload_id=row_data.upload_id
        and resolution.generation=coalesce(publication.projection_generation,publication.authority_scope_version)
      where resolution.client_id=any(clients)
      union select resolution.* from public.weekly_source_row_resolutions resolution
        join report_bindings binding on binding.bound_row_resolution_id=resolution.id
  ), events as materialized (
    select event.* from public.weekly_work_events event where event.first_source_group_id=g.id and event.client_id=any(clients)
      and (event.id in(select work_event_id from resolutions) or event.id in(select work_event_id from report_bindings)
        or exists(select 1 from public.weekly_discrepancy_incidents incident where incident.source_cycle_id=c.id
          and incident.work_event_id=event.id and incident.client_id=event.client_id))
  ), revisions as materialized (
    select revision.* from public.weekly_source_final_revisions revision
      join public.weekly_source_cycles source_cycle on source_cycle.id=revision.source_cycle_id and source_cycle.source_group_id=g.id
      where revision.state in ('CURRENT','PREPARED','SUPERSEDED') and (
        revision.source_cycle_id=c.id or revision.report_scope_id in(select id from report_scopes)
        or exists(select 1 from public.weekly_source_final_snapshot_lines snapshot where snapshot.final_revision_id=revision.id
          and snapshot.work_event_id in(select id from events)))
  ), snapshots as materialized (
    select snapshot.* from public.weekly_source_final_snapshot_lines snapshot where snapshot.final_revision_id in(select id from revisions)
      and snapshot.client_id=any(clients)
  ), lineages as materialized (
    select lineage.* from public.weekly_source_row_timesheet_lineages lineage where lineage.client_id=any(clients)
      and (lineage.row_resolution_id in(select id from resolutions) or lineage.work_event_id in(select id from events))
  ), pay_receipts as materialized (
    select receipt.* from public.weekly_source_ordinary_pay_projection_receipts receipt where receipt.client_id=any(clients)
      and receipt.final_revision_id in(select id from revisions)
  ), financial_identities as materialized (
    -- The Source receipt is immutable and already pins all published economics
    -- and root-before/after/service hashes. Protection may replace currentness
    -- on the same native family; the Source financial identity stays exact.
    select financial.id,financial.timesheet_id,financial.client_id,financial.candidate_id,
      (select min(m.contract_id::text)::uuid
        from pay_receipts receipt
        cross join lateral jsonb_array_elements(case when jsonb_typeof(receipt.source_unit_outcomes_json)='array'
          then receipt.source_unit_outcomes_json else '[]'::jsonb end) unit
        join public.weekly_source_billing_movements m on m.id=(unit->>'movement_id')::uuid
          and m.final_revision_id=receipt.final_revision_id and m.invoice_timesheet_id=receipt.root_timesheet_id
          and m.actual_client_id=receipt.client_id and m.candidate_id=financial.candidate_id
          and encode(m.movement_economic_hash,'hex')=unit->>'movement_economic_hash'
          and m.source_profile_kind<>'SELF_BILL_REPORT'
          and m.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
        where receipt.published_timesheet_financial_id=financial.id
        having count(distinct m.contract_id)=1) as contract_id
      from public.timesheets_financials financial where financial.id in(select published_timesheet_financial_id from pay_receipts)
  ), root_identities as materialized (
    select root.timesheet_id,root.client_id,contract.candidate_id,root.contract_id,root.booking_id
      from public.timesheets root join public.contracts contract on contract.id=root.contract_id
      where root.timesheet_id in(select root_timesheet_id from pay_receipts)
  ), cycles as materialized (
    select cycle.* from public.weekly_source_cycles cycle where cycle.id=c.id or cycle.id in(select source_cycle_id from publications)
      or cycle.id in(select source_cycle_id from revisions)
  ), contracts as materialized (
    select contract.* from public.contracts contract where contract.client_id=any(clients)
      and (daterange(contract.start_date,contract.end_date,'[]') && daterange(
        coalesce(u.confirmed_coverage_start_local_date,c.finalisation_week_ending-6),
        coalesce(u.confirmed_coverage_end_local_date,c.finalisation_week_ending),'[]')
        or contract.id in(select contract_id from resolutions) or contract.id in(select contract_id from snapshots)
        or exists(select 1 from public.weekly_issue_comparison_revisions comparison
          join public.weekly_discrepancy_incidents incident on incident.current_comparison_revision_id=comparison.id
          where incident.source_cycle_id=c.id and incident.client_id=contract.client_id and comparison.contract_id=contract.id))
  ), policy_dates as materialized (
    select client client_id,null::uuid contract_id,c.finalisation_week_ending work_date from unnest(clients) client
    union select client_id,contract_id,work_date from snapshots
    union select resolution.client_id,resolution.contract_id,row_data.work_date from resolutions resolution
      join source_rows row_data on row_data.id=resolution.upload_row_id
    union select client_id,null::uuid,work_date from events
    union select contract.client_id,contract.id,greatest(contract.start_date,
      coalesce(u.confirmed_coverage_start_local_date,c.finalisation_week_ending-6)) from contracts contract
  ), resolved_policies as materialized (
    select client_id,contract_id,work_date,private._weekly_source_effective_policy_v1(client_id,contract_id,work_date) policy
      from policy_dates
  )
  select jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_SOURCE_FACTS_V1','source_cycle_id',c.id,
    'client_ids',to_jsonb(clients),'group',to_jsonb(g),
    'cycles',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from cycles x),'[]'::jsonb),
    'clients',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.clients x where x.id=any(clients)),'[]'::jsonb),
    'memberships',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.valid_from,x.id)
      from public.weekly_source_group_clients x where x.source_group_id=g.id and x.client_id=any(clients)),'[]'::jsonb),
    'client_policies',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.effective_from,x.id)
      from public.weekly_source_client_policies x where x.source_group_id=g.id and x.client_id=any(clients)),'[]'::jsonb),
    'client_settings',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.id) from public.client_settings x where x.client_id=any(clients)),'[]'::jsonb),
    'contracts',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from contracts x),'[]'::jsonb),
    'contract_policies',coalesce((select jsonb_agg(to_jsonb(x) order by x.contract_id,x.effective_from,x.id)
      from public.weekly_source_contract_policies x where x.contract_id in(select id from contracts)),'[]'::jsonb),
    'global_settings',coalesce((select jsonb_agg(to_jsonb(x)) from public.weekly_source_global_settings x where x.singleton),'[]'::jsonb),
    'resolved_policies',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.contract_id nulls first,x.work_date) from resolved_policies x),'[]'::jsonb),
    'assignments',coalesce((select jsonb_agg(to_jsonb(x) order by x.effective_from_week_ending,x.id)
      from public.weekly_source_group_rule_assignments x where x.source_group_id=g.id),'[]'::jsonb),
    'rule_versions',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.weekly_source_rule_set_versions x
      where x.id in(select rule_set_version_id from public.weekly_source_group_rule_assignments where source_group_id=g.id)
        or x.id in(select rule_set_version_id from revisions)),'[]'::jsonb),
    'effective_rules',coalesce((select jsonb_agg(jsonb_build_object('client_id',client,
      'effective_rule_set',private.weekly_source_effective_rule_set_v1(client,c.id)) order by client) from unnest(clients) client),'[]'::jsonb),
    'profiles',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.weekly_source_format_profiles x
      where x.id in(select source_format_profile_id from uploads)),'[]'::jsonb),
    'uploads',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from uploads x),'[]'::jsonb),
    'publications',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from publications x),'[]'::jsonb),
    'rows',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_id,x.source_row_ordinal,x.id) from source_rows x),'[]'::jsonb),
    'resolutions',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_row_id,x.generation,x.id) from resolutions x),'[]'::jsonb),
    'economics',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id) from public.weekly_source_row_economic_snapshots x
      where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'expense_policy_snapshots',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id)
      from public.weekly_source_row_expense_policy_snapshots x where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'expense_authorities',coalesce((select jsonb_agg(to_jsonb(x) order by x.work_event_id,x.generation,x.id)
      from public.weekly_expense_authority_generations x where x.final_revision_id in(select id from revisions)
        and x.work_event_id in(select id from events)),'[]'::jsonb),
    'expense_cell_evidence',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_id,x.source_row_ordinal,x.id)
      from public.weekly_source_expense_cell_evidence x where x.upload_id in(select id from uploads)),'[]'::jsonb),
    'charge_checks',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id)
      from public.weekly_source_charge_checks x where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'charge_acceptances',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id)
      from public.weekly_source_charge_acceptances x where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'invoice_hold_releases',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_row_id,x.hold_kind,x.id)
      from public.weekly_source_invoice_hold_releases x where x.upload_row_id in(select id from source_rows)),'[]'::jsonb),
    'transitions',coalesce((select jsonb_agg(to_jsonb(x) order by x.final_revision_id,x.work_event_id,x.id)
      from public.weekly_source_state_transitions x where x.final_revision_id in(select id from revisions)
        and x.work_event_id in(select id from events)),'[]'::jsonb),
    'report_scopes',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from report_scopes x),'[]'::jsonb),
    'reports',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.weekly_source_self_bill_reports x
      where x.source_group_id=g.id and x.client_id=any(clients)),'[]'::jsonb),
    'report_bindings',coalesce((select jsonb_agg(to_jsonb(x) order by x.report_row_id,x.id) from report_bindings x),'[]'::jsonb),
    'events',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from events x),'[]'::jsonb),
    'revisions',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from revisions x),'[]'::jsonb),
    'snapshots',coalesce((select jsonb_agg(to_jsonb(x) order by x.final_revision_id,x.work_event_id,x.id) from snapshots x),'[]'::jsonb),
    'lineages',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from lineages x),'[]'::jsonb),
    'pay_receipts',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from pay_receipts x),'[]'::jsonb),
    'financial_identities',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from financial_identities x),'[]'::jsonb),
    'root_identities',coalesce((select jsonb_agg(to_jsonb(x) order by x.timesheet_id) from root_identities x),'[]'::jsonb)) into facts;
  if exists(select 1 from jsonb_array_elements(facts->'pay_receipts') receipt
    where receipt->>'published_timesheet_financial_id' is not null and (
      jsonb_typeof(receipt->'source_unit_outcomes_json') is distinct from 'array'
      or case when jsonb_typeof(receipt->'source_unit_outcomes_json')='array'
        then jsonb_array_length(receipt->'source_unit_outcomes_json')=0 else true end
      or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(receipt->'source_unit_outcomes_json')='array'
          then receipt->'source_unit_outcomes_json' else '[]'::jsonb end) unit
        where not exists(select 1 from public.weekly_source_billing_movements m
          where m.id=(unit->>'movement_id')::uuid and m.final_revision_id=(receipt->>'final_revision_id')::uuid
            and m.invoice_timesheet_id=(receipt->>'root_timesheet_id')::uuid
            and m.actual_client_id=(receipt->>'client_id')::uuid
            and exists(select 1 from jsonb_array_elements(facts->'financial_identities') financial
              where financial->>'id'=receipt->>'published_timesheet_financial_id'
                and financial->>'candidate_id'=m.candidate_id::text
                and financial->>'contract_id'=m.contract_id::text)
            and encode(m.movement_economic_hash,'hex')=unit->>'movement_economic_hash'
            and m.source_profile_kind<>'SELF_BILL_REPORT'
            and m.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION'))))) then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_FINANCIAL_IDENTITY_INVALID' using errcode='55000'; end if;
  if (select count(*) from public.clients where id=any(clients))<>cardinality(clients)
    or exists(select 1 from jsonb_array_elements(facts->'pay_receipts') receipt
      where receipt->>'published_timesheet_financial_id' is not null and not exists(
        select 1 from jsonb_array_elements(facts->'financial_identities') financial
          where financial->>'id'=receipt->>'published_timesheet_financial_id'
            and financial->>'timesheet_id'=receipt->>'root_timesheet_id' and financial->>'client_id'=receipt->>'client_id'
            and exists(select 1 from jsonb_array_elements(facts->'root_identities') root
              join jsonb_array_elements(facts->'contracts') contract on contract->>'id'=financial->>'contract_id'
              where root->>'timesheet_id'=financial->>'timesheet_id'
                and root->>'candidate_id'=financial->>'candidate_id' and root->>'contract_id'=financial->>'contract_id'
                and (root->>'client_id' is null or root->>'client_id'=financial->>'client_id')
                and contract->>'client_id'=financial->>'client_id' and contract->>'candidate_id'=financial->>'candidate_id'))) then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_FINANCIAL_IDENTITY_INVALID' using errcode='55000'; end if;
  if octet_length(convert_to(facts::text,'UTF8'))>8388608 then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_SCOPE_TOO_LARGE' using errcode='54000'; end if;
  return facts;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_SCOPE_UNAVAILABLE' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_bulk_source_cas_v1(p_cycle_id uuid,p_client_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare facts jsonb;
begin
  facts:=private.weekly_source_bulk_source_facts_v1(p_cycle_id,p_client_ids);
  return jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_SOURCE_CAS_V1','source_cycle_id',p_cycle_id,
    'client_ids',facts->'client_ids','source_cas_sha256',encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_BULK_SOURCE_CAS_V1',facts),'hex'));
end;
$function$;

-- All new capability evidence lives in the existing release/assignment receipt.
-- Qualification is installed by root's protected managed-release evidence
-- workflow after actual native prerequisite journeys, never by a browser flag.
create or replace function private.weekly_source_protected_capability_release_evidence_v1(
  p_group_id uuid,p_from date,p_to date,p_expected_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare g public.weekly_source_groups%rowtype; r private.cloudtms_database_releases%rowtype;
  q jsonb; entry jsonb; count_rows integer; needed text[]; cap text;
begin
  select * into strict g from public.weekly_source_groups where id=p_group_id and active and source_family='ROSTER';
  select * into r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if not found or r.status<>'VERIFIED' or r.completed_at_utc is null
    or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or g.environment<>'TEST' or current_database()<>'cloudtms_test_clone'
    or not exists(select 1 from private.cloudtms_database_identity where singleton and environment=g.environment)
    or r.evidence_json#>>'{managed_release,environment}' is distinct from g.environment
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or jsonb_typeof(r.evidence_json->'weekly_source_protected_capability_qualifications') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  select count(*),jsonb_agg(value)->0 into count_rows,q
    from jsonb_array_elements(r.evidence_json->'weekly_source_protected_capability_qualifications') value
    where value->>'source_group_id'=g.id::text and value->>'effective_from_week_ending'=p_from::text
      and value->>'effective_to_week_ending' is not distinct from p_to::text;
  if count_rows<>1 or not private.weekly_exceptional_json_keys_exact_v1(q,array[
      'schema_version','release_id','git_commit','contract_sha256','agency_id','environment','source_group_id',
      'effective_from_week_ending','effective_to_week_ending','capabilities','gate_receipts','qualification_sha256'])
    or not(q ?& array['schema_version','release_id','git_commit','contract_sha256','agency_id','environment','source_group_id',
      'effective_from_week_ending','effective_to_week_ending','capabilities','gate_receipts','qualification_sha256'])
    or q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1'
    or q->>'release_id' is distinct from r.release_id or q->>'git_commit' is distinct from r.git_commit
    or q->>'contract_sha256' is distinct from r.installed_contract_sha256
    or q->>'agency_id' is distinct from g.agency_id::text or q->>'environment' is distinct from g.environment
    or coalesce(q->>'qualification_sha256','') !~ '^[0-9a-f]{64}$'
    or q->>'qualification_sha256' is distinct from p_expected_sha256
    or encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1',q-'qualification_sha256'),'hex')
      is distinct from q->>'qualification_sha256'
    or jsonb_typeof(q->'capabilities') is distinct from 'array' or jsonb_array_length(q->'capabilities') not between 1 and 2
    or exists(select 1 from jsonb_array_elements(q->'capabilities') value where jsonb_typeof(value)<>'string'
      or value#>>'{}' not in ('BULK_SIGNED','AUTOMATIC_RECONCILE'))
    or (select count(distinct value) from jsonb_array_elements(q->'capabilities') value)<>jsonb_array_length(q->'capabilities')
    or (q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb and not(q->'capabilities' @> '["BULK_SIGNED"]'::jsonb))
    or jsonb_typeof(q->'gate_receipts') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  needed:=array['SOURCE_CAS_NATIVE','NATIVE_PROTECTION','SECURITY','LEGACY_PAY','NEXT_PAY','CLIENT_API','DOCUMENT','OWN_STAGE_CAS','SOURCE_ROUTING'];
  if q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb then needed:=array_append(needed,'AUTOMATIC_COMPONENT_DELTA'); end if;
  if jsonb_array_length(q->'gate_receipts')<>cardinality(needed)
    or (select count(distinct value->>'gate') from jsonb_array_elements(q->'gate_receipts') value)<>cardinality(needed) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  for entry in select value from jsonb_array_elements(q->'gate_receipts') value loop
    if not private.weekly_exceptional_json_keys_exact_v1(entry,array['gate','status','execution','database','receipt_id','receipt_sha256',
        'source_commit','contract_sha256','source_group_id','agency_id','environment'])
      or not(entry ?& array['gate','status','execution','database','receipt_id','receipt_sha256',
        'source_commit','contract_sha256','source_group_id','agency_id','environment'])
      or not(coalesce(entry->>'gate','')=any(needed)) or entry->>'status' is distinct from 'PASS'
      or entry->>'execution' is distinct from 'AGENCY_TEST_NATIVE' or entry->>'database' is distinct from current_database()
      or entry->>'source_commit' is distinct from r.git_commit or entry->>'contract_sha256' is distinct from r.installed_contract_sha256
      or entry->>'source_group_id' is distinct from g.id::text or entry->>'agency_id' is distinct from g.agency_id::text
      or entry->>'environment' is distinct from g.environment or nullif(btrim(entry->>'receipt_id'),'') is null
      or char_length(entry->>'receipt_id')>256 or coalesce(entry->>'receipt_sha256','') !~ '^[0-9a-f]{64}$' then
      raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  end loop;
  return q;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000';
end;
$function$;

-- Read-only exact pre-existing policy admission. It does not legalise or rewrite
-- any Client setting, signed preset, Source amount/pricing rule or NHSP route.
create or replace function private.weekly_source_protected_source_activation_scope_v1(p_group_id uuid,p_from date,p_to date)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare g public.weekly_source_groups%rowtype; v_boundary record; policy jsonb; count_rows integer:=0;
begin
  select * into strict g from public.weekly_source_groups where id=p_group_id and active and source_family='ROSTER';
  for v_boundary in
    with members as materialized(select * from public.weekly_source_group_clients where source_group_id=g.id
      and daterange(valid_from,coalesce(valid_to,'infinity'::date),'[]') && daterange(p_from-6,coalesce(p_to,'infinity'::date),'[]')),
    dates as (
      select client_id,greatest(valid_from,p_from-6) scope_date from members
      union select member.client_id,cp.effective_from from members member join public.weekly_source_client_policies cp
        on cp.client_id=member.client_id and cp.source_group_id=g.id where cp.effective_from>=p_from-6
          and cp.effective_from<=coalesce(p_to,'infinity'::date) and cp.effective_from between member.valid_from and coalesce(member.valid_to,'infinity'::date)
      union select member.client_id,cp.effective_to+1 from members member join public.weekly_source_client_policies cp
        on cp.client_id=member.client_id and cp.source_group_id=g.id where cp.effective_to is not null and cp.effective_to+1>=p_from-6
          and cp.effective_to+1<=coalesce(p_to,'infinity'::date) and cp.effective_to+1 between member.valid_from and coalesce(member.valid_to,'infinity'::date)
    ) select dates.client_id,null::uuid contract_id,dates.scope_date from dates
    union select contract.client_id,contract.id,dates.scope_date
      from public.contracts contract join dates on dates.client_id=contract.client_id
      where dates.scope_date between contract.start_date and contract.end_date
    union select contract.client_id,contract.id,greatest(contract.start_date,member.valid_from,p_from-6)
      from public.contracts contract join members member on member.client_id=contract.client_id
      where daterange(contract.start_date,contract.end_date,'[]') && daterange(greatest(member.valid_from,p_from-6),
        least(coalesce(member.valid_to,'infinity'::date),coalesce(p_to,'infinity'::date)),'[]')
    union select contract.client_id,contract.id,boundary.scope_date
      from public.contracts contract join members member on member.client_id=contract.client_id
      join public.weekly_source_contract_policies cp on cp.contract_id=contract.id
      cross join lateral (values(cp.effective_from),(cp.effective_to+1)) boundary(scope_date)
      where boundary.scope_date between greatest(contract.start_date,member.valid_from,p_from-6)
        and least(contract.end_date,coalesce(member.valid_to,'infinity'::date),coalesce(p_to,'infinity'::date))
    order by client_id,contract_id nulls first,scope_date
  loop
    count_rows:=count_rows+1;
    policy:=private._weekly_source_effective_policy_v1(v_boundary.client_id,v_boundary.contract_id,v_boundary.scope_date);
    if policy->>'source_group_id' is distinct from g.id::text or private.weekly_source_is_import_authoritative_v1(
      v_boundary.client_id,v_boundary.contract_id,v_boundary.scope_date) is distinct from true then
      raise exception 'WEEKLY_SOURCE_PROTECTED_SOURCE_SCOPE_NOT_IMPORT_AUTHORITATIVE' using errcode='22023'; end if;
  end loop;
  if count_rows=0 then raise exception 'WEEKLY_SOURCE_RULE_GROUP_MEMBERS_REQUIRED' using errcode='22023'; end if;
end;
$function$;

create or replace function private.weekly_source_protected_capability_receipt_v1(p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  a public.weekly_source_group_rule_assignments%rowtype; q jsonb; receipt jsonb;
begin
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  select * into strict a from public.weekly_source_group_rule_assignments where source_group_id=g.id and feature_enabled
    and c.finalisation_week_ending between effective_from_week_ending and coalesce(effective_to_week_ending,'infinity'::date);
  receipt:=a.feature_receipt_json;
  if a.feature_purpose is null or a.feature_purpose not in ('RULE_SET','PROTECTED_SOURCE')
    or (a.feature_purpose='PROTECTED_SOURCE' and a.rule_set_version_id is not null)
    or receipt->>'contract' is distinct from 'WEEKLY_SOURCE_RULE_FEATURE_RECEIPT_V1'
    or receipt->>'assignment_id' is distinct from a.id::text or receipt->>'assignment_version' is distinct from a.version::text
    or receipt->>'source_group_id' is distinct from g.id::text
    or receipt->>'rule_set_version_id' is distinct from a.rule_set_version_id::text
    or receipt->>'feature_purpose' is distinct from a.feature_purpose or receipt->'feature_enabled' is distinct from 'true'::jsonb
    or receipt->>'actor_user_id' is distinct from a.feature_changed_by_user_id::text
    or receipt->>'request_id' is distinct from a.feature_request_id::text or receipt->>'release_id' is distinct from a.feature_release_id
    or receipt->>'effective_from_week_ending' is distinct from a.effective_from_week_ending::text
    or a.feature_request_sha256 is null or a.feature_changed_at_utc is null
    or not exists(select 1 from public.tms_users actor where actor.id=a.feature_changed_by_user_id and actor.is_active and actor.role='admin') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_ACTIVATION_UNQUALIFIED' using errcode='55000'; end if;
  q:=private.weekly_source_protected_capability_release_evidence_v1(g.id,a.effective_from_week_ending,a.effective_to_week_ending,
    receipt#>>'{protected_capability_qualification,qualification_sha256}');
  if q is distinct from receipt->'protected_capability_qualification' or q->>'release_id' is distinct from a.feature_release_id then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_ACTIVATION_UNQUALIFIED' using errcode='55000'; end if;
  return q;
end;
$function$;

create or replace function private.weekly_source_bulk_producer_ready_v1(p_cycle_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare q jsonb;
begin
  q:=private.weekly_source_protected_capability_receipt_v1(p_cycle_id);
  return q->'capabilities' @> '["BULK_SIGNED"]'::jsonb;
exception when no_data_found or too_many_rows or sqlstate '55000' then return false;
end;
$function$;

create or replace function private.weekly_source_automatic_reconcile_producer_ready_v1(p_cycle_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare q jsonb; c public.weekly_source_cycles%rowtype; actual_client uuid; rules jsonb;
begin
  q:=private.weekly_source_protected_capability_receipt_v1(p_cycle_id);
  if not(q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb) then return false; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  actual_client:=private.weekly_source_checking_client_scope_v1(c.current_projection_publication_id);
  if actual_client is not null then
    rules:=private.weekly_source_effective_rule_set_v1(actual_client,c.id)->'values';
    return coalesce(rules->>'invoice_sender'='CLIENT_SELF_BILL' and rules->>'equal_protected_hours'='CLEAR_AUTOMATICALLY',false);
  end if;
  -- Legacy group-wide scope is retained. Each actual event's S18b rule check
  -- remains in the normal selection owner; readiness grants no event permission.
  return exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=c.source_group_id
    and c.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date)
    and private.weekly_source_effective_rule_set_v1(member.client_id,c.id)#>>'{values,invoice_sender}'='CLIENT_SELF_BILL'
    and private.weekly_source_effective_rule_set_v1(member.client_id,c.id)#>>'{values,equal_protected_hours}'='CLEAR_AUTOMATICALLY');
exception when no_data_found or too_many_rows or sqlstate '55000' then return false;
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
-- Only a native authoritative admitted command supplies this census. Browser
-- requests never gain a client_ids property. Replay retains its original scope.
create or replace function private.weekly_source_bulk_original_client_ids_v1(p_cycle_id uuid,p_actor_id uuid,p_bulk_key text)
returns uuid[] language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare command jsonb; selection jsonb; cas_value jsonb; clients uuid[]; item jsonb;
begin
  if p_cycle_id is null or p_actor_id is null or coalesce(p_bulk_key,'') !~ '^[A-Za-z0-9:_-]{16,120}$' then
    raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_INVALID' using errcode='22023'; end if;
  select audit.after_json into command from public.audit_events audit
    where audit.object_type='weekly_source_bulk_signed_command'
      and audit.object_id_text=p_cycle_id::text||':'||p_actor_id::text||':'||p_bulk_key
      and audit.action='WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED' and audit.event_sequence_is_authoritative
    order by audit.event_sequence desc limit 1;
  selection:=command->'initial_selection'; cas_value:=selection->'source_cas';
  if command->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_COMMAND_V1'
    or command->>'actor_user_id' is distinct from p_actor_id::text or command->>'source_cycle_id' is distinct from p_cycle_id::text
    or command->>'bulk_request_key' is distinct from p_bulk_key
    or selection->>'contract' is distinct from 'WEEKLY_SOURCE_BULK_SIGNED_SELECTION_V1'
    or selection->>'source_cycle_id' is distinct from p_cycle_id::text
    or coalesce(selection->>'selection_sha256','') !~ '^[0-9a-f]{64}$'
    or encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_SIGNED_SELECTION_V1',
      selection-array['selection_sha256','eligible_count','skipped_count']),'hex') is distinct from selection->>'selection_sha256'
    or not private.weekly_exceptional_json_keys_exact_v1(cas_value,array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or not(cas_value ?& array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or cas_value->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_SOURCE_CAS_V1'
    or cas_value->>'source_cycle_id' is distinct from p_cycle_id::text
    or coalesce(cas_value->>'source_cas_sha256','') !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(cas_value->'client_ids') is distinct from 'array' or jsonb_array_length(cas_value->'client_ids')>100 then
    raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_INVALID' using errcode='55000'; end if;
  for item in select value from jsonb_array_elements(cas_value->'client_ids') value loop
    if jsonb_typeof(item) is distinct from 'string' or item#>>'{}' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_INVALID' using errcode='55000'; end if;
  end loop;
  select coalesce(array_agg(distinct value::uuid order by value::uuid),'{}'::uuid[]) into clients
    from jsonb_array_elements_text(cas_value->'client_ids') value;
  if to_jsonb(clients) is distinct from cas_value->'client_ids' then
    raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_INVALID' using errcode='55000'; end if;
  return clients;
exception when invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_INVALID' using errcode='55000';
end;
$function$;


create or replace function private.weekly_source_protected_non_self_bill_mode_v1(
  p_client_id uuid,p_contract_id uuid,p_work_date date,p_cycle_id uuid
) returns text language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; policy jsonb; qualification jsonb; declared_client uuid;
begin
  if p_client_id is null or p_contract_id is null or p_work_date is null or p_cycle_id is null then return null; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  policy:=private._weekly_source_effective_policy_v1(p_client_id,p_contract_id,p_work_date);
  if policy->'self_bill_enabled' is distinct from 'false'::jsonb or policy->>'c1_source_mode' is not null
    or policy->>'source_group_id' is distinct from c.source_group_id::text
    or policy->>'source_family' is distinct from 'ROSTER'
    or private.weekly_source_is_import_authoritative_v1(p_client_id,p_contract_id,p_work_date) is distinct from true
    or not exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=c.source_group_id
      and member.client_id=p_client_id and c.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date)) then return null; end if;
  declared_client:=private.weekly_source_checking_client_scope_v1(c.current_projection_publication_id);
  if declared_client is not null and declared_client<>p_client_id then return null; end if;
  begin
    qualification:=private.weekly_source_protected_capability_receipt_v1(c.id);
  exception when sqlstate '55000' or no_data_found or too_many_rows then
    begin
      qualification:=private.weekly_source_protected_qualification_assert_v1(null,c.id,null,'BULK_SIGNED');
    exception when sqlstate '42501' or sqlstate '55000' then return null;
    end;
    if not(qualification#>'{original_census,original_client_ids}' @> jsonb_build_array(p_client_id)) then return null; end if;
  end;
  if not(qualification->'capabilities' @> '["BULK_SIGNED"]'::jsonb) then return null; end if;
  return 'HEALTHROSTER_WEEKLY';
exception when no_data_found or too_many_rows or sqlstate '55000' then return null;
end;
$function$;

-- Owner-only bounded native prerequisite dispatcher, never a Worker RPC.
create or replace function private.weekly_source_protected_qualification_step_v1(
  p_scope_id uuid,p_operation text,p_request jsonb
) returns jsonb language plpgsql volatile security invoker set search_path to 'pg_catalog','pg_temp'
as $function$
declare scope_value jsonb; cycle_id uuid; actor uuid; request_value jsonb; result_value jsonb;
  item jsonb; selected_event uuid; family_id uuid; request_id uuid; contract_id uuid; client_id uuid;
  candidate_id uuid; root_id uuid; native_cycle uuid; step_count integer; receipt jsonb; capability text;
begin
  perform private.weekly_source_protected_qualification_owner_v1();
  if p_scope_id is null or p_operation not in ('BULK_PREVIEW','BULK_ADMIT','BULK_ROUND','BULK_APPLY',
      'PREPARE_FAMILY','PREPARE_ACTION','ACTION_CONTEXT','STAGE_C1_REQUEST','COMPLETE_LOCAL',
      'AUTOMATIC_PREVIEW','AUTOMATIC_COMPLETE')
    or jsonb_typeof(p_request) is distinct from 'object' or octet_length(convert_to(p_request::text,'UTF8'))>262144 then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
  select (audit.after_json->>'source_cycle_id')::uuid into strict cycle_id from public.audit_events audit
    where audit.object_type='weekly_source_protected_qualification' and audit.object_id_text=p_scope_id::text
      and audit.action='WEEKLY_SOURCE_QUALIFICATION_SCOPE_ADMITTED' and audit.event_sequence_is_authoritative
      and audit.after_json->>'transaction_id'=pg_current_xact_id()::text and audit.after_json->>'backend_pid'=pg_backend_pid()::text;
  capability:=case when p_operation like 'AUTOMATIC_%' then 'AUTOMATIC_RECONCILE' else 'BULK_SIGNED' end;
  scope_value:=private.weekly_source_protected_qualification_assert_v1(p_scope_id,cycle_id,null,capability);
  actor:=(scope_value->>'actor_user_id')::uuid;
  select count(*) into step_count from public.audit_events audit
    where audit.object_type='weekly_source_protected_qualification' and audit.object_id_text=p_scope_id::text
      and audit.action='WEEKLY_SOURCE_QUALIFICATION_NATIVE_STEP_COMPLETED'
      and audit.after_json->>'transaction_id'=pg_current_xact_id()::text;
  if step_count>=(scope_value->>'max_native_steps')::integer then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_LIMIT' using errcode='54000'; end if;
  if p_request ? 'actor_user_id' and p_request->>'actor_user_id' is distinct from actor::text then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_ACTOR_MISMATCH' using errcode='42501'; end if;
  if p_operation like 'AUTOMATIC_%' then request_value:=p_request;
  else request_value:=p_request||jsonb_build_object('actor_user_id',actor); end if;
  if p_operation<>'COMPLETE_LOCAL' and request_value->>'source_cycle_id' is distinct from cycle_id::text then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_CYCLE_MISMATCH' using errcode='42501'; end if;
  if p_operation not in ('BULK_PREVIEW','BULK_ADMIT','BULK_ROUND','BULK_APPLY') then
    if p_operation in ('COMPLETE_LOCAL','AUTOMATIC_COMPLETE') then
      request_id:=(request_value->>'publication_request_id')::uuid;
      select approval.work_event_id,approval.client_id,request.contract_id,request.candidate_id,
        request.root_timesheet_id,approval.source_cycle_id into strict selected_event,client_id,contract_id,candidate_id,root_id,native_cycle
        from public.weekly_exceptional_c1_publication_requests request
        join public.weekly_exceptional_payment_approvals approval on approval.creation_orchestration_run_id=request.orchestration_run_id
          and approval.pay_target_family_id=request.family_id where request.id=request_id;
      if native_cycle is distinct from cycle_id or (p_operation='AUTOMATIC_COMPLETE'
        and request_value->>'work_event_id' is distinct from selected_event::text) then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_CYCLE_MISMATCH' using errcode='42501'; end if;
    else
      selected_event:=(request_value->>'work_event_id')::uuid;
      if p_operation='PREPARE_FAMILY' then
        contract_id:=(request_value->>'contract_id')::uuid; client_id:=(request_value->>'client_id')::uuid;
        candidate_id:=(request_value->>'candidate_id')::uuid;
      elsif p_operation<>'AUTOMATIC_PREVIEW' then
        family_id:=(request_value->>'family_id')::uuid;
        select family.contract_id,family.candidate_id,family.root_timesheet_id,contract.client_id
          into strict contract_id,candidate_id,root_id,client_id
          from public.weekly_exceptional_pay_target_families family join public.contracts contract on contract.id=family.contract_id
          where family.id=family_id and contract.candidate_id=family.candidate_id;
      end if;
    end if;
    select value into strict item from jsonb_array_elements(scope_value#>'{original_census,original_items}') value
      where value->>'work_event_id'=selected_event::text;
    if p_operation<>'AUTOMATIC_PREVIEW' and
      (item->>'contract_id',item->>'candidate_id',item->>'client_id') is distinct from
        (contract_id::text,candidate_id::text,client_id::text) then
      raise exception 'WEEKLY_SOURCE_QUALIFICATION_ORIGINAL_ITEM_CHANGED' using errcode='40001'; end if;
    if p_operation in ('PREPARE_FAMILY','ACTION_CONTEXT','STAGE_C1_REQUEST')
      and request_value->>'evidence_timesheet_id' is distinct from item->>'evidence_timesheet_id' then
      raise exception 'WEEKLY_SOURCE_QUALIFICATION_SIGNED_ROOT_SCOPE_INVALID' using errcode='42501'; end if;
    if root_id is not null and not exists(select 1 from public.timesheets sheet
      join public.contracts contract on contract.id=sheet.contract_id where sheet.timesheet_id=root_id
        and contract.id=contract_id and contract.candidate_id=candidate_id and contract.client_id=client_id
        and (sheet.client_id is null or sheet.client_id=client_id)) then
      raise exception 'WEEKLY_SOURCE_QUALIFICATION_NATIVE_ROOT_SCOPE_INVALID' using errcode='55000'; end if;
  end if;
  -- No arbitrary routine text or dynamic EXECUTE. Native owners retain payload,
  -- actor/signature/rates/financial/I-1/CAS/replay guards and existing side effects.
  case p_operation
    when 'BULK_PREVIEW' then
      if request_value->>'mode' is distinct from 'PREVIEW' then raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_protect_all_signed_atomic_v1(request_value);
    when 'BULK_ADMIT' then
      if request_value->>'mode' is distinct from 'COMMIT' or coalesce(request_value->>'phase','ADMIT')<>'ADMIT' then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_protect_all_signed_atomic_v1(request_value);
    when 'BULK_ROUND' then
      if request_value->>'mode' is distinct from 'COMMIT' or request_value->>'phase' is distinct from 'ROUND' then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_protect_all_signed_atomic_v1(request_value);
    when 'BULK_APPLY' then
      if request_value->>'mode' is distinct from 'COMMIT' or request_value->>'phase' is distinct from 'APPLY' then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_protect_all_signed_atomic_v1(request_value);
    when 'PREPARE_FAMILY' then result_value:=public.weekly_exceptional_pay_prepare_family_v1(request_value);
    when 'PREPARE_ACTION' then result_value:=public.weekly_exceptional_pay_prepare_action_v1(request_value);
    when 'ACTION_CONTEXT' then result_value:=public.weekly_exceptional_pay_action_context_v1(request_value);
    when 'STAGE_C1_REQUEST' then result_value:=public.weekly_exceptional_pay_stage_c1_request_v1(request_value);
    when 'COMPLETE_LOCAL' then result_value:=public.weekly_exceptional_pay_complete_local_v1(request_value);
    when 'AUTOMATIC_PREVIEW' then
      if request_value->>'mode' is distinct from 'PREVIEW' then raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_automatic_reconcile_atomic_v1(request_value);
    when 'AUTOMATIC_COMPLETE' then
      if request_value->>'mode' is distinct from 'COMPLETE' then raise exception 'WEEKLY_SOURCE_QUALIFICATION_STEP_INVALID' using errcode='22023'; end if;
      result_value:=public.weekly_source_automatic_reconcile_atomic_v1(request_value);
  end case;
  -- Own native stage may change its protected state, not immutable Source CAS.
  perform private.weekly_source_protected_qualification_assert_v1(p_scope_id,cycle_id,null,capability);
  receipt:=jsonb_build_object('schema_version','WEEKLY_SOURCE_TEST_ROLLBACK_NATIVE_STEP_V1',
    'scope_id',p_scope_id,'scope_sha256',scope_value->>'scope_sha256','transaction_id',pg_current_xact_id()::text,
    'execution',scope_value->'execution','operation',p_operation,'actor_user_id',actor,'source_cycle_id',cycle_id,
    'request_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_QUALIFICATION_NATIVE_REQUEST_V1',request_value),'hex'),
    'result_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_QUALIFICATION_NATIVE_RESULT_V1',result_value),'hex'),
    'source_cas',scope_value#>'{original_census,source_cas}','operational_replay',false);
  perform public._audit_insert('weekly_source_protected_qualification',p_scope_id::text,
    'WEEKLY_SOURCE_QUALIFICATION_NATIVE_STEP_COMPLETED',null,receipt,'Bounded owner-run native prerequisite',actor);
  return jsonb_build_object('qualification_step',receipt,'native_result',result_value);
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_NATIVE_SCOPE_UNAVAILABLE' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_automatic_reconcile_capability_assert_v1(p_cycle_id uuid)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_ready boolean;
begin
  if to_regprocedure('private.weekly_source_automatic_reconcile_producer_ready_v1(uuid)') is null
    or to_regprocedure('private.weekly_source_automatic_reconcile_delta_assert_v1(uuid,uuid)') is null then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
  execute 'select private.weekly_source_automatic_reconcile_producer_ready_v1($1)' into v_ready using p_cycle_id;
  if v_ready is distinct from true then
    begin
      perform private.weekly_source_protected_qualification_assert_v1(null,p_cycle_id,null,'AUTOMATIC_RECONCILE');
    exception when sqlstate '42501' or sqlstate '55000' then
      raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000';
    end;
  end if;
end;
$function$;

create or replace function private.weekly_source_qualification_closed_object_v1(p_value jsonb,p_keys text[])
returns boolean language sql immutable security invoker set search_path to 'pg_catalog','pg_temp'
as $function$
  select coalesce(jsonb_typeof(p_value)='object' and p_value ?& p_keys
    and private.weekly_exceptional_json_keys_exact_v1(p_value,p_keys),false)
$function$;

-- All operational callers use this full certificate. V1-native-only and V2
-- prerequisite certificates cannot enter activation, receipt or readiness.
create or replace function private.weekly_source_protected_operational_certificate_assert_v1(
  p_q jsonb,p_group_id uuid,p_from date,p_to date,p_expected_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare q jsonb:=p_q; g public.weekly_source_groups%rowtype; r private.cloudtms_database_releases%rowtype;
  executed private.cloudtms_database_releases%rowtype; native jsonb; row_value jsonb; closure jsonb;
  needed text[]; keys text[]; remote_needed text[]:=array['CLIENT_HTTP','OFFICE_UI','MYTMS_PHONE']; origin text; n integer;
begin
  select * into strict g from public.weekly_source_groups where id=p_group_id and active and source_family='ROSTER' and environment='TEST';
  select * into strict r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if current_database()<>'cloudtms_test_clone' or r.status<>'VERIFIED' or r.completed_at_utc is null
    or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or r.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or not private.weekly_source_qualification_closed_object_v1(q,array['schema_version','phase','release_id','git_commit','contract_sha256',
      'agency_id','environment','source_group_id','effective_from_week_ending','effective_to_week_ending','capabilities',
      'native_execution_qualification','remote_gate_receipts','test_setup_closure','source_equivalence','qualification_sha256'])
    or q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_OPERATIONAL_QUALIFICATION_V1'
    or q->>'phase' is distinct from 'ALL_PRE_SWITCH_GATES_QUALIFIED'
    or q->>'release_id' is distinct from r.release_id or q->>'git_commit' is distinct from r.git_commit
    or q->>'contract_sha256' is distinct from r.installed_contract_sha256 or q->>'agency_id' is distinct from g.agency_id::text
    or q->>'source_group_id' is distinct from g.id::text or q->>'environment' is distinct from g.environment
    or q->>'effective_from_week_ending' is distinct from p_from::text or q->>'effective_to_week_ending' is distinct from p_to::text
    or coalesce(p_expected_sha256,'') !~ '^[0-9a-f]{64}$' or q->>'qualification_sha256' is distinct from p_expected_sha256
    or q->>'qualification_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_PROTECTED_CAPABILITY_OPERATIONAL_QUALIFICATION_V1',q-'qualification_sha256'),'hex')
    or q->'capabilities' not in ('["BULK_SIGNED"]'::jsonb,'["AUTOMATIC_RECONCILE","BULK_SIGNED"]'::jsonb) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  native:=q->'native_execution_qualification';closure:=q->'test_setup_closure';
  select * into strict executed from private.cloudtms_database_releases where release_id=native->>'release_id';
  if executed.release_id=r.release_id or executed.status<>'VERIFIED' or executed.completed_at_utc is null
    or executed.git_commit is distinct from native->>'git_commit'
    or executed.installed_contract_sha256 is distinct from executed.repository_contract_sha256
    or executed.installed_contract_sha256 is distinct from r.installed_contract_sha256
    or executed.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}'
      is distinct from r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}'
    or private.weekly_source_protected_qualification_release_v1()->>'release_id' is distinct from r.release_id
    or not private.weekly_source_qualification_closed_object_v1(native,array['schema_version','release_id','git_commit','contract_sha256','agency_id','environment',
      'source_group_id','effective_from_week_ending','effective_to_week_ending','capabilities','gate_receipts','qualification_sha256'])
    or native->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1'
    or native->>'contract_sha256' is distinct from r.installed_contract_sha256
    or native->>'agency_id' is distinct from g.agency_id::text or native->>'source_group_id' is distinct from g.id::text
    or native->>'environment' is distinct from 'TEST' or native->>'effective_from_week_ending' is distinct from p_from::text
    or native->>'effective_to_week_ending' is distinct from p_to::text or native->'capabilities' is distinct from q->'capabilities'
    or native->>'qualification_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1',native-'qualification_sha256'),'hex') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  needed:=array['SOURCE_CAS_NATIVE','NATIVE_PROTECTION','SECURITY','LEGACY_PAY','NEXT_PAY','CLIENT_API','DOCUMENT','OWN_STAGE_CAS','SOURCE_ROUTING'];
  if q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb then needed:=array_append(needed,'AUTOMATIC_COMPONENT_DELTA'); end if;
  if jsonb_typeof(native->'gate_receipts') is distinct from 'array' or jsonb_array_length(native->'gate_receipts')<>cardinality(needed)
    or (select count(distinct value->>'gate') from jsonb_array_elements(native->'gate_receipts') value)<>cardinality(needed) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  for row_value in select value from jsonb_array_elements(native->'gate_receipts') value loop
    if not private.weekly_source_qualification_closed_object_v1(row_value,array['gate','status','execution','database','receipt_id','receipt_sha256',
        'source_commit','contract_sha256','source_group_id','agency_id','environment'])
      or not(coalesce(row_value->>'gate','')=any(needed)) or row_value->>'status' is distinct from 'PASS'
      or row_value->>'execution' is distinct from 'AGENCY_TEST_NATIVE' or row_value->>'database' is distinct from current_database()
      or row_value->>'source_commit' is distinct from executed.git_commit or row_value->>'contract_sha256' is distinct from executed.installed_contract_sha256
      or row_value->>'source_group_id' is distinct from g.id::text or row_value->>'agency_id' is distinct from g.agency_id::text
      or row_value->>'environment' is distinct from 'TEST' or nullif(row_value->>'receipt_id','') is null
      or coalesce(row_value->>'receipt_sha256','') !~ '^[0-9a-f]{64}$' then
      raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  end loop;
  if not private.weekly_source_qualification_closed_object_v1(closure,array['scope_id','scope_sha256','setup_authorization_sha256',
      'original_census_sha256','actor_user_id','source_cycle_id','week_ending','execution_release_id','execution_source_commit',
      'execution_contract_sha256','closure_audit_id','closure_audit_sha256','state','closed_at_utc','all_assignments_disabled','all_operational_producers_false'])
    or exists(select 1 from unnest(array['scope_id','actor_user_id','source_cycle_id','closure_audit_id']) k
      where coalesce(closure->>k,'') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
    or exists(select 1 from unnest(array['scope_sha256','setup_authorization_sha256','original_census_sha256','closure_audit_sha256']) k
      where coalesce(closure->>k,'') !~ '^[0-9a-f]{64}$')
    or coalesce(closure->>'week_ending','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    or coalesce(closure->>'closed_at_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
    or closure->>'state' is distinct from 'CLOSED' or closure->'all_assignments_disabled' is distinct from 'true'::jsonb
    or closure->'all_operational_producers_false' is distinct from 'true'::jsonb
    or closure->>'execution_release_id' is distinct from executed.release_id
    or closure->>'execution_source_commit' is distinct from executed.git_commit
    or closure->>'execution_contract_sha256' is distinct from executed.installed_contract_sha256
    or (closure->>'week_ending')::date<p_from or (p_to is not null and (closure->>'week_ending')::date>p_to)
    or not exists(select 1 from public.audit_events a where a.id=(closure->>'closure_audit_id')::uuid
      and a.object_type='weekly_source_protected_test_journey' and a.object_id_text=closure->>'scope_id'
      and a.action='WEEKLY_SOURCE_TEST_JOURNEY_CLOSED' and a.event_sequence_is_authoritative
      and a.after_json=closure-'closure_audit_id'-'closure_audit_sha256'
      and encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_TEST_JOURNEY_CLOSED_V1',a.after_json),'hex')=closure->>'closure_audit_sha256') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  if jsonb_typeof(q->'remote_gate_receipts') is distinct from 'array' or jsonb_array_length(q->'remote_gate_receipts')<>3
    or (select count(distinct value->>'gate') from jsonb_array_elements(q->'remote_gate_receipts') value)<>3 then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  for row_value in select value from jsonb_array_elements(q->'remote_gate_receipts') value loop
    origin:=case row_value->>'gate' when 'CLIENT_HTTP' then 'AUTHENTICATED_DEPLOYED_HTTP'
      when 'OFFICE_UI' then 'DEPLOYED_OFFICE_BROWSER_UI' when 'MYTMS_PHONE' then 'PHYSICAL_TESTFLIGHT_MYTMS_PHONE' end;
    keys:=case row_value->>'gate'
      when 'CLIENT_HTTP' then array['real_authenticated_session','trusted_actor_injected','closed_browser_payload','native_preview_commit_retry',
        'native_source_cas_error_order','foreign_actor_and_scope_refused','operational_readiness_false']
      when 'OFFICE_UI' then array['actual_deployed_bundle','deep_link_scope','actual_preview_and_confirmation','native_partial_retry_display',
        'unauthorised_controls_absent','operational_readiness_false']
      when 'MYTMS_PHONE' then array['actual_installed_test_build','actual_candidate_authenticated_session','genuine_signed_submission_bytes',
        'native_signature_authority','actual_approved_hours_display','actual_document_bytes_and_hash','operational_readiness_false'] end;
    if not private.weekly_source_qualification_closed_object_v1(row_value,array['schema_version','gate','origin','execution_release_id',
        'execution_source_commit','execution_contract_sha256','environment','database','agency_id','source_group_id','source_cycle_id',
        'actor_user_id','week_ending','scope_id','scope_sha256','original_census_sha256','server_request_ids','server_trace_sha256',
        'native_result_receipts_sha256','capture_sha256','deployments','assertions','receipt_id','receipt_sha256'])
      or origin is null or row_value->>'origin' is distinct from origin
      or row_value->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_REMOTE_GATE_RECEIPT_V1'
      or row_value->>'execution_release_id' is distinct from executed.release_id or row_value->>'execution_source_commit' is distinct from executed.git_commit
      or row_value->>'execution_contract_sha256' is distinct from executed.installed_contract_sha256
      or row_value->>'source_group_id' is distinct from g.id::text or row_value->>'agency_id' is distinct from g.agency_id::text
      or row_value->>'environment' is distinct from 'TEST' or row_value->>'database' is distinct from current_database()
      or exists(select 1 from unnest(array['source_cycle_id','actor_user_id','week_ending','scope_id','scope_sha256','original_census_sha256']) k
        where row_value->>k is distinct from closure->>k)
      or not private.weekly_source_qualification_closed_object_v1(row_value->'assertions',keys)
      or exists(select 1 from unnest(keys) k where row_value#>array['assertions',k] is distinct from 'true'::jsonb)
      or exists(select 1 from unnest(array['receipt_sha256','server_trace_sha256','native_result_receipts_sha256','capture_sha256']) k
        where coalesce(row_value->>k,'') !~ '^[0-9a-f]{64}$')
      or coalesce(row_value->>'receipt_id','') !~ '^[A-Za-z0-9_./:@-]{1,256}$'
      or jsonb_typeof(row_value->'server_request_ids') is distinct from 'array'
      or jsonb_array_length(row_value->'server_request_ids') not between 1 and 100
      or (select count(distinct value) from jsonb_array_elements(row_value->'server_request_ids') value)
        <>jsonb_array_length(row_value->'server_request_ids')
      or exists(select 1 from jsonb_array_elements(row_value->'server_request_ids') request_id
        where jsonb_typeof(request_id)<>'string' or request_id#>>'{}' !~ '^[A-Za-z0-9:_-]{1,128}$')
      or not private.weekly_source_qualification_closed_object_v1(row_value->'deployments',array['worker_script','worker_version_id',
        'worker_source_commit','office_source_commit','office_bundle_sha256','mytms_source_commit','mytms_build_id',
        'mytms_bundle_identifier','mytms_build_artifact_sha256'])
      or coalesce(row_value#>>'{deployments,worker_version_id}','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or exists(select 1 from unnest(array['office_source_commit','mytms_source_commit']) k
        where coalesce(row_value#>>array['deployments',k],'') !~ '^[0-9a-f]{40}$')
      or exists(select 1 from unnest(array['office_bundle_sha256','mytms_build_artifact_sha256']) k
        where coalesce(row_value#>>array['deployments',k],'') !~ '^[0-9a-f]{64}$')
      or nullif(row_value#>>'{deployments,mytms_build_id}','') is null
      or row_value#>>'{deployments,worker_script}' is distinct from 'test-cloudtms-backend'
      or row_value#>>'{deployments,worker_source_commit}' is distinct from executed.git_commit
      or row_value#>>'{deployments,mytms_bundle_identifier}' is distinct from 'net.cloudtms.mytms.test' then
      raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  end loop;
  if (select count(distinct value->'deployments') from jsonb_array_elements(q->'remote_gate_receipts') value)<>1 then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  perform private.weekly_source_protected_execution_tree_assert_v2(q->'source_equivalence',executed.git_commit,r.git_commit);
  return q;
exception when no_data_found or too_many_rows or invalid_text_representation or datetime_field_overflow then
  raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_protected_execution_tree_assert_v2(p_proof jsonb,p_execution_commit text,p_installation_commit text)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare file jsonb;
begin
  -- PostgreSQL cannot read Git objects. This asserts the closed receipt DTO;
  -- the protected managed writer MUST remeasure the literal complete Git tree.
  -- A caller JSON/hash assertion is never source equivalence authority.
  if not private.weekly_source_qualification_closed_object_v1(p_proof,array['schema_version','execution_source_commit','installation_source_commit',
      'inventory_schema','files','receipt_bindings','source_equivalence_sha256'])
    or p_proof->>'schema_version' is distinct from 'WEEKLY_SOURCE_COMMITTED_EXECUTION_TREE_EQUIVALENCE_V2'
    or p_proof->>'inventory_schema' is distinct from 'WEEKLY_SOURCE_NATIVE_RELEASE_TOOLCHAIN_VERIFIER_INVENTORY_V2'
    or p_proof->>'execution_source_commit' is distinct from p_execution_commit
    or p_proof->>'installation_source_commit' is distinct from p_installation_commit
    or p_proof->>'source_equivalence_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_COMMITTED_EXECUTION_TREE_EQUIVALENCE_V2',p_proof-'source_equivalence_sha256'),'hex')
    or jsonb_typeof(p_proof->'files') is distinct from 'array' or jsonb_array_length(p_proof->'files')=0
    or jsonb_typeof(p_proof->'receipt_bindings') is distinct from 'array'
    or (select count(distinct value->>'path') from jsonb_array_elements(p_proof->'files') value)<>jsonb_array_length(p_proof->'files')
    or exists(select 1 from unnest(array['.node-version','.github/workflows/database-release.yml','supabase/release/export_contract.sql',
      'supabase/release/current-release.json','supabase/release/current-contract.json','scripts/cloudtms-db-release.mjs']) required_path
      where not exists(select 1 from jsonb_array_elements(p_proof->'files') item where item->>'path'=required_path)) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_EXECUTION_TREE_CHANGED' using errcode='55000'; end if;
  for file in select value from jsonb_array_elements(p_proof->'files') value loop
    if not private.weekly_source_qualification_closed_object_v1(file,array['path','git_mode','git_type','execution_blob_oid','installation_blob_oid',
        'execution_sha256','installation_sha256','comparison','comparison_sha256'])
      or nullif(file->>'path','') is null or file->>'git_mode' not in ('100644','100755') or file->>'git_type' is distinct from 'blob'
      or exists(select 1 from unnest(array['execution_sha256','installation_sha256','comparison_sha256']) k
        where coalesce(file->>k,'') !~ '^[0-9a-f]{64}$')
      or exists(select 1 from unnest(array['execution_blob_oid','installation_blob_oid']) k where coalesce(file->>k,'') !~ '^[0-9a-f]{40}$')
      or (file->>'path'<>'supabase/release/current-release.json' and
        (file->>'comparison' is distinct from 'EXACT_GIT_OBJECT' or file->>'execution_blob_oid' is distinct from file->>'installation_blob_oid'
          or file->>'execution_sha256' is distinct from file->>'installation_sha256'))
      or (file->>'path'='supabase/release/current-release.json'
        and file->>'comparison' is distinct from 'RELEASE_AUTHORITY_EXCEPT_CLOSED_RECEIPT_DESCRIPTORS') then
      raise exception 'WEEKLY_SOURCE_PROTECTED_EXECUTION_TREE_CHANGED' using errcode='55000'; end if;
  end loop;
end;
$function$;

-- SOURCE PROPOSAL ONLY. Root integrates and proves; no operational activation.
-- The only persisted relation named here is the existing audit_events owner.
-- Its scope is transaction-bound and cannot authorize another transaction.
create or replace function private.weekly_source_protected_qualification_owner_v1()
returns void language plpgsql stable security invoker set search_path to 'pg_catalog','pg_temp'
as $function$
declare owner_name name;
begin
  select pg_get_userbyid(proowner) into strict owner_name from pg_proc
    where oid='private.weekly_source_protected_qualification_owner_v1()'::regprocedure;
  if session_user is distinct from owner_name or current_user is distinct from owner_name then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_OWNER_REQUIRED' using errcode='42501'; end if;
  perform private.weekly_source_query_require_service_v1();
end;
$function$;

create or replace function private.weekly_source_protected_qualification_release_v1()
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare r private.cloudtms_database_releases%rowtype; i private.cloudtms_database_identity%rowtype;
begin
  select * into strict i from private.cloudtms_database_identity where singleton and environment='TEST';
  select * into strict r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if current_database()<>'cloudtms_test_clone' or r.status is distinct from 'VERIFIED'
    or r.completed_at_utc is null or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or r.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,schema_version}'
      is distinct from 'WEEKLY_SOURCE_QUALIFICATION_INSTALLED_CATALOGUE_V1'
    or r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,contract_sha256}' is distinct from r.installed_contract_sha256
    or r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}' is distinct from encode(
      private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_QUALIFICATION_INSTALLED_CATALOGUE_V1',
        private.weekly_source_protected_qualification_current_catalogue_v1()),'hex') then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_INSTALLED_RELEASE_REQUIRED' using errcode='55000'; end if;
  return jsonb_build_object('release_id',r.release_id,'source_commit',r.git_commit,
    'contract_sha256',r.installed_contract_sha256,'installation_id',i.installation_id,
    'environment',i.environment,'database',current_database(),
    'managed_manifest_sha256',r.evidence_json#>>'{managed_release,manifest_sha256}',
    'installed_catalogue_jsonb_sha256',r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}');
exception when no_data_found or too_many_rows then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_INSTALLED_RELEASE_REQUIRED' using errcode='55000';
end;
$function$;

-- Plain discovery only. Original signed physical identities and immutable
-- Source pay roots are sealed. Protection family/current-generation state is
-- not made a second Source authority, and a completed Client is never removed.
create or replace function private.weekly_source_protected_qualification_census_v1(p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; p public.weekly_source_projection_publications%rowtype;
  clients uuid[]; facts jsonb; cas_value jsonb; roots jsonb; items jsonb; census jsonb;
begin
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict p from public.weekly_source_projection_publications
    where id=c.current_projection_publication_id and source_cycle_id=c.id and state='CURRENT'
      and authority_scope_kind='CYCLE' and correction_session_id is null and report_scope_id is null;
  perform private.weekly_source_query_current_publication_v1(c.id,p.id);
  select coalesce(array_agg(distinct incident.client_id order by incident.client_id),'{}'::uuid[])
    into clients from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      and comparison.incident_id=incident.id
    join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id
      and work.client_id=incident.client_id and work.first_source_group_id=c.source_group_id
    join public.contracts contract on contract.id=comparison.contract_id and contract.candidate_id=work.candidate_id
      and contract.client_id=work.client_id
    where incident.source_cycle_id=c.id and incident.state='OPEN'
      and private.weekly_source_is_import_authoritative_v1(work.client_id,contract.id,work.work_date)
      and (private.weekly_source_checking_client_scope_v1(p.id) is null
        or incident.client_id=private.weekly_source_checking_client_scope_v1(p.id));
  if cardinality(clients) not between 1 and 100 then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_ORIGINAL_CLIENTS_REQUIRED' using errcode='55000'; end if;
  facts:=private.weekly_source_bulk_source_facts_v1(c.id,clients);
  cas_value:=private.weekly_source_bulk_source_cas_v1(c.id,clients);
  select coalesce(jsonb_agg(jsonb_build_object('incident_id',incident.id,'work_event_id',work.id,
    'client_id',work.client_id,'candidate_id',work.candidate_id,'contract_id',contract.id,'work_date',work.work_date,
    'comparison_revision_id',comparison.id,'evidence_timesheet_id',comparison.candidate_timesheet_id)
    order by work.candidate_id,work.id,incident.id),'[]'::jsonb) into items
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      and comparison.incident_id=incident.id
    join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id
      and work.client_id=incident.client_id and work.first_source_group_id=c.source_group_id
    join public.contracts contract on contract.id=comparison.contract_id and contract.candidate_id=work.candidate_id
      and contract.client_id=work.client_id
    where incident.source_cycle_id=c.id and incident.state='OPEN' and work.client_id=any(clients)
      and private.weekly_source_is_import_authoritative_v1(work.client_id,contract.id,work.work_date);
  if exists(select 1 from jsonb_array_elements(items) item where item->>'evidence_timesheet_id' is not null
    and not exists(select 1 from public.timesheets sheet join public.contracts contract on contract.id=sheet.contract_id
      where sheet.timesheet_id=(item->>'evidence_timesheet_id')::uuid
        and contract.id=(item->>'contract_id')::uuid and contract.candidate_id=(item->>'candidate_id')::uuid
        and contract.client_id=(item->>'client_id')::uuid
        and (sheet.client_id is null or sheet.client_id=contract.client_id))) then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SIGNED_ROOT_SCOPE_INVALID' using errcode='55000'; end if;
  with ids as (
    select (item->>'evidence_timesheet_id')::uuid id from jsonb_array_elements(items) item
      where item->>'evidence_timesheet_id' is not null
    union select (item->>'timesheet_id')::uuid from jsonb_array_elements(facts->'root_identities') item
  ) select coalesce(jsonb_agg(jsonb_build_object('timesheet_id',sheet.timesheet_id,'booking_id',sheet.booking_id,
    'contract_id',contract.id,'candidate_id',contract.candidate_id,'client_id',contract.client_id)
    order by sheet.timesheet_id),'[]'::jsonb) into roots from ids
    join public.timesheets sheet on sheet.timesheet_id=ids.id join public.contracts contract on contract.id=sheet.contract_id;
  census:=jsonb_build_object('schema_version','WEEKLY_SOURCE_QUALIFICATION_CENSUS_V1','source_cycle_id',c.id,
    'source_group_id',c.source_group_id,'week_ending',c.finalisation_week_ending,'original_client_ids',to_jsonb(clients),
    'original_root_identities',roots,'original_items',items,'source_cas',cas_value);
  return census||jsonb_build_object('census_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_QUALIFICATION_CENSUS_V1',census),'hex'));
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_SOURCE_UNAVAILABLE' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_protected_qualification_begin_v1(p_request jsonb)
returns jsonb language plpgsql volatile security invoker set search_path to 'pg_catalog','pg_temp'
as $function$
declare actor uuid; cycle_id uuid; scope_id uuid; c public.weekly_source_cycles%rowtype;
  g public.weekly_source_groups%rowtype; census jsonb; execution jsonb; scope_value jsonb; existing_count integer;
begin
  perform private.weekly_source_protected_qualification_owner_v1();
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,array['scope_id','actor_user_id','source_cycle_id',
      'expected_execution','expected_census_sha256','capabilities','reason','turn_backend_pid'])
    or not(p_request ?& array['scope_id','actor_user_id','source_cycle_id','expected_execution','expected_census_sha256','capabilities','reason','turn_backend_pid'])
    or jsonb_typeof(p_request->'capabilities') is distinct from 'array'
    or p_request->'capabilities' not in ('["BULK_SIGNED"]'::jsonb,'["AUTOMATIC_RECONCILE","BULK_SIGNED"]'::jsonb)
    or char_length(coalesce(p_request->>'reason','')) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_REQUEST_INVALID' using errcode='22023'; end if;
  actor:=(p_request->>'actor_user_id')::uuid; cycle_id:=(p_request->>'source_cycle_id')::uuid; scope_id:=(p_request->>'scope_id')::uuid;
  if actor is null or cycle_id is null or scope_id is null then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_REQUEST_INVALID' using errcode='22023'; end if;
  if not exists(select 1 from pg_locks lock_row where lock_row.locktype='advisory' and lock_row.granted
    and lock_row.mode='ExclusiveLock' and lock_row.classid=20261013::oid and lock_row.objid=1::oid and lock_row.objsubid=2
      and lock_row.database=(select oid from pg_database where datname=current_database())
    and lock_row.pid=(p_request->>'turn_backend_pid')::integer and lock_row.pid<>pg_backend_pid()) then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SHARED_TURN_REQUIRED' using errcode='55000'; end if;
  perform private._weekly_source_settings_require_admin_v1(actor);
  select * into strict c from public.weekly_source_cycles where id=cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  perform private._weekly_source_settings_deployment_v1(g.agency_id,g.environment);
  if g.environment<>'TEST' then raise exception 'WEEKLY_SOURCE_QUALIFICATION_TEST_ONLY' using errcode='42501'; end if;
  perform private.weekly_source_office_authority_v1(actor,'APPROVE_PROTECTED_PAY',g.id,null,c.finalisation_week_ending);
  execution:=private.weekly_source_protected_qualification_release_v1();
  if execution is distinct from p_request->'expected_execution' then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_EXECUTION_CHANGED' using errcode='40001'; end if;
  if private.weekly_source_bulk_producer_ready_v1(c.id) or private.weekly_source_automatic_reconcile_producer_ready_v1(c.id) then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_OPERATIONAL_SCOPE_REFUSED' using errcode='55000'; end if;
  census:=private.weekly_source_protected_qualification_census_v1(c.id);
  if census->>'census_sha256' is distinct from p_request->>'expected_census_sha256' then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SOURCE_CHANGED' using errcode='40001'; end if;
  select count(*) into existing_count from public.audit_events audit
    where audit.object_type='weekly_source_protected_qualification' and audit.action='WEEKLY_SOURCE_QUALIFICATION_SCOPE_ADMITTED'
      and audit.after_json->>'transaction_id'=pg_current_xact_id()::text
      and audit.after_json->>'backend_pid'=pg_backend_pid()::text;
  if existing_count<>0 then raise exception 'WEEKLY_SOURCE_QUALIFICATION_SCOPE_ALREADY_ADMITTED' using errcode='23505'; end if;
  scope_value:=jsonb_build_object('schema_version','WEEKLY_SOURCE_TEST_ROLLBACK_QUALIFICATION_SCOPE_V1','scope_id',scope_id,
    'transaction_id',pg_current_xact_id()::text,'backend_pid',pg_backend_pid()::text,'database',current_database(),
    'turn_backend_pid',p_request->>'turn_backend_pid',
    'execution',execution,'actor_user_id',actor,'agency_id',g.agency_id,'source_group_id',g.id,'source_cycle_id',c.id,
    'current_local_date',(clock_timestamp() at time zone 'Europe/London')::date,'week_ending',c.finalisation_week_ending,
    'capabilities',p_request->'capabilities','original_census',census,'operational_ready',false,'max_native_steps',64);
  scope_value:=scope_value||jsonb_build_object('scope_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_TEST_ROLLBACK_QUALIFICATION_SCOPE_V1',scope_value),'hex'));
  perform public._audit_insert('weekly_source_protected_qualification',scope_id::text,'WEEKLY_SOURCE_QUALIFICATION_SCOPE_ADMITTED',
    null,scope_value,p_request->>'reason',actor);
  return scope_value;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_SCOPE_INVALID' using errcode='55000';
end;
$function$;

-- This is not producer_ready. It can be consumed only below the private,
-- owner-session dispatcher. Actual public service/API calls cannot enter it.
create or replace function private.weekly_source_protected_qualification_assert_v1(
  p_scope_id uuid,p_cycle_id uuid,p_client_ids uuid[],p_capability text
) returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare scope_value jsonb; c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  clients uuid[]; actual_cas jsonb; context_value text; scopes integer; rules jsonb; original jsonb; actual jsonb;
begin
  perform private.weekly_source_protected_qualification_owner_v1();
  get diagnostics context_value=pg_context;
  if context_value !~ 'PL/pgSQL function (private\.)?weekly_source_protected_qualification_step_v1\(uuid,text,jsonb\)' then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_CALLER_REQUIRED' using errcode='42501'; end if;
  select count(*),jsonb_agg(audit.after_json)->0 into scopes,scope_value from public.audit_events audit
    where audit.object_type='weekly_source_protected_qualification' and audit.action='WEEKLY_SOURCE_QUALIFICATION_SCOPE_ADMITTED'
      and audit.event_sequence_is_authoritative
      and audit.after_json->>'transaction_id'=pg_current_xact_id()::text
      and audit.after_json->>'backend_pid'=pg_backend_pid()::text
      and (p_scope_id is null or audit.object_id_text=p_scope_id::text);
  if scopes<>1 or scope_value->>'schema_version' is distinct from 'WEEKLY_SOURCE_TEST_ROLLBACK_QUALIFICATION_SCOPE_V1'
    or scope_value->>'database' is distinct from current_database()
    or scope_value->'operational_ready' is distinct from 'false'::jsonb
    or scope_value->>'source_cycle_id' is distinct from p_cycle_id::text
    or scope_value->>'current_local_date' is distinct from ((clock_timestamp() at time zone 'Europe/London')::date)::text
    or scope_value->>'scope_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_TEST_ROLLBACK_QUALIFICATION_SCOPE_V1',scope_value-'scope_sha256'),'hex')
    or scope_value->'execution' is distinct from private.weekly_source_protected_qualification_release_v1()
    or not exists(select 1 from pg_locks lock_row where lock_row.locktype='advisory' and lock_row.granted
      and lock_row.mode='ExclusiveLock' and lock_row.classid=20261013::oid and lock_row.objid=1::oid and lock_row.objsubid=2
      and lock_row.database=(select oid from pg_database where datname=current_database())
      and lock_row.pid=(scope_value->>'turn_backend_pid')::integer and lock_row.pid<>pg_backend_pid())
    or p_capability not in ('BULK_SIGNED','AUTOMATIC_RECONCILE')
    or not(scope_value->'capabilities' @> jsonb_build_array(p_capability)) then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SCOPE_UNAVAILABLE' using errcode='55000'; end if;
  perform private._weekly_source_settings_require_admin_v1((scope_value->>'actor_user_id')::uuid);
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  if (g.id::text,g.agency_id::text,g.environment,c.finalisation_week_ending::text) is distinct from
    (scope_value->>'source_group_id',scope_value->>'agency_id','TEST',scope_value->>'week_ending') then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SOURCE_CHANGED' using errcode='40001'; end if;
  perform private._weekly_source_settings_deployment_v1(g.agency_id,g.environment);
  perform private.weekly_source_office_authority_v1((scope_value->>'actor_user_id')::uuid,'APPROVE_PROTECTED_PAY',g.id,null,c.finalisation_week_ending);
  select array_agg(value::uuid order by value::uuid) into clients
    from jsonb_array_elements_text(scope_value#>'{original_census,original_client_ids}') value;
  if p_client_ids is not null and to_jsonb(p_client_ids) is distinct from to_jsonb(clients) then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_ORIGINAL_CLIENT_CENSUS_CHANGED' using errcode='40001'; end if;
  actual_cas:=private.weekly_source_bulk_source_cas_v1(c.id,clients);
  if actual_cas is distinct from scope_value#>'{original_census,source_cas}' then
    raise exception 'WEEKLY_SOURCE_QUALIFICATION_SOURCE_CHANGED' using errcode='40001'; end if;
  -- No mutable family/current-generation state is compared. Every original
  -- physical root identity remains; native signed/stage/inventory guards do
  -- their own version/signature/currentness work without a qualification waiver.
  for original in select value from jsonb_array_elements(scope_value#>'{original_census,original_root_identities}') value loop
    select jsonb_build_object('timesheet_id',sheet.timesheet_id,'booking_id',sheet.booking_id,'contract_id',contract.id,
      'candidate_id',contract.candidate_id,'client_id',contract.client_id) into actual
      from public.timesheets sheet join public.contracts contract on contract.id=sheet.contract_id
      where sheet.timesheet_id=(original->>'timesheet_id')::uuid and (sheet.client_id is null or sheet.client_id=contract.client_id);
    if actual is distinct from original then
      raise exception 'WEEKLY_SOURCE_QUALIFICATION_ORIGINAL_ROOT_CHANGED' using errcode='40001'; end if;
  end loop;
  if p_capability='AUTOMATIC_RECONCILE' then
    if cardinality(clients)<>1 then raise exception 'WEEKLY_SOURCE_QUALIFICATION_AUTOMATIC_SCOPE_INVALID' using errcode='55000'; end if;
    rules:=private.weekly_source_effective_rule_set_v1(clients[1],c.id)->'values';
    if rules is null or rules->>'invoice_sender' is distinct from 'CLIENT_SELF_BILL'
      or rules->>'equal_protected_hours' is distinct from 'CLEAR_AUTOMATICALLY'
      or (select automatic_reconcile_actor_user_id from public.weekly_source_global_settings where singleton)
        is distinct from (scope_value->>'actor_user_id')::uuid then
      raise exception 'WEEKLY_SOURCE_QUALIFICATION_AUTOMATIC_SCOPE_INVALID' using errcode='55000'; end if;
  end if;
  return scope_value;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_QUALIFICATION_SCOPE_UNAVAILABLE' using errcode='55000';
end;
$function$;

-- Protected writer alone records these real R1 receipts on R2. The R1
-- identity is retained, and the writer compares the complete committed native
-- source set byte-for-byte. No ledger/status/receipt is edited by this reader.
create or replace function private.weekly_source_protected_prerequisite_release_assert_v2(
  p_q jsonb,p_group_id uuid,p_from date,p_to date,p_expected_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare g public.weekly_source_groups%rowtype; r private.cloudtms_database_releases%rowtype;
  executed private.cloudtms_database_releases%rowtype; q jsonb:=p_q; entry jsonb; needed text[]; source_value jsonb;
begin
  select * into strict g from public.weekly_source_groups where id=p_group_id and active and source_family='ROSTER';
  select * into strict r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  select * into strict executed from private.cloudtms_database_releases where release_id=q#>>'{execution_identity,release_id}';
  if not private.weekly_exceptional_json_keys_exact_v1(q,array['schema_version','phase','release_id','git_commit','contract_sha256',
      'agency_id','environment','source_group_id','effective_from_week_ending','effective_to_week_ending','capabilities',
      'execution_identity','source_equivalence','gate_receipts','required_operational_replay','qualification_sha256'])
    or not(q ?& array['schema_version','phase','release_id','git_commit','contract_sha256','agency_id','environment','source_group_id',
      'effective_from_week_ending','effective_to_week_ending','capabilities','execution_identity','source_equivalence','gate_receipts',
      'required_operational_replay','qualification_sha256'])
    or q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_PREREQUISITE_QUALIFICATION_V2'
    or q->>'phase' is distinct from 'PREREQUISITES_QUALIFIED_OPERATIONAL_REPLAY_PENDING'
    or current_database()<>'cloudtms_test_clone' or g.environment<>'TEST'
    or r.status<>'VERIFIED' or r.completed_at_utc is null or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or r.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or not private.weekly_exceptional_json_keys_exact_v1(q->'execution_identity',array['release_id','source_commit','contract_sha256',
      'installation_id','agency_id','environment','database','managed_manifest_sha256','installed_catalogue_jsonb_sha256'])
    or q->>'release_id' is distinct from r.release_id or q->>'git_commit' is distinct from r.git_commit
    or q->>'contract_sha256' is distinct from r.installed_contract_sha256
    or q->>'agency_id' is distinct from g.agency_id::text or q->>'source_group_id' is distinct from g.id::text
    or q->>'environment' is distinct from 'TEST' or q->>'effective_from_week_ending' is distinct from p_from::text
    or q->>'effective_to_week_ending' is distinct from p_to::text
    or q->>'qualification_sha256' is distinct from p_expected_sha256
    or coalesce(q->>'qualification_sha256','') !~ '^[0-9a-f]{64}$'
    or encode(private.weekly_source_sha256_jsonb_v1(q->>'schema_version',q-'qualification_sha256'),'hex')
      is distinct from q->>'qualification_sha256'
    or executed.release_id=r.release_id or executed.status<>'VERIFIED' or executed.completed_at_utc is null
    or executed.git_commit is distinct from q#>>'{execution_identity,source_commit}'
    or executed.installed_contract_sha256 is distinct from executed.repository_contract_sha256
    or executed.installed_contract_sha256 is distinct from r.installed_contract_sha256
    or executed.installed_contract_sha256 is distinct from q#>>'{execution_identity,contract_sha256}'
    or q#>>'{execution_identity,managed_manifest_sha256}' is distinct from executed.evidence_json#>>'{managed_release,manifest_sha256}'
    or q#>>'{execution_identity,installed_catalogue_jsonb_sha256}'
      is distinct from executed.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}'
    or q#>>'{execution_identity,installed_catalogue_jsonb_sha256}'
      is distinct from r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}'
    or q#>>'{execution_identity,agency_id}' is distinct from g.agency_id::text
    or q#>>'{execution_identity,environment}' is distinct from 'TEST'
    or q#>>'{execution_identity,database}' is distinct from current_database()
    or not exists(select 1 from private.cloudtms_database_identity identity where identity.singleton and identity.environment='TEST'
      and identity.installation_id::text=q#>>'{execution_identity,installation_id}')
    or executed.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or executed.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or q->'required_operational_replay' is distinct from '["CONTROLLED_ACTIVATION_POSITIVE_NEGATIVE_CAS", "REAL_CLIENT_API_PREVIEW_COMMIT_RETRY_ERROR_ORDER", "REAL_OFFICE_UI_DEEP_LINK_ACTIONS", "REAL_MYTMS_SIGNED_DOCUMENT_AND_APP", "REAL_POST_ACTIVATION_NATIVE_LEGACY_NEXT_REPLAY", "REAL_POST_ACTIVATION_SOURCE_ROUTING"]'::jsonb then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  perform private.weekly_source_protected_execution_tree_assert_v2(q->'source_equivalence',executed.git_commit,r.git_commit);
  if jsonb_typeof(q->'capabilities') is distinct from 'array'
    or q->'capabilities' not in ('["BULK_SIGNED"]'::jsonb,'["AUTOMATIC_RECONCILE","BULK_SIGNED"]'::jsonb)
    or jsonb_typeof(q->'gate_receipts') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  needed:=array['SOURCE_CAS_NATIVE','NATIVE_PROTECTION','SECURITY','LEGACY_PAY','NEXT_PAY','CLIENT_API','DOCUMENT','OWN_STAGE_CAS','SOURCE_ROUTING'];
  if q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb then needed:=array_append(needed,'AUTOMATIC_COMPONENT_DELTA'); end if;
  if jsonb_array_length(q->'gate_receipts')<>cardinality(needed)
    or (select count(distinct value->>'gate') from jsonb_array_elements(q->'gate_receipts') value)<>cardinality(needed) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  for entry in select value from jsonb_array_elements(q->'gate_receipts') value loop
    if not private.weekly_exceptional_json_keys_exact_v1(entry,array['gate','status','execution','receipt_id','receipt_sha256',
        'execution_release_id','execution_source_commit','execution_contract_sha256','execution_installation_id','scope_id',
        'scope_sha256','transaction_id','source_cycle_id','week_ending','original_census_sha256','source_cas_sha256'])
      or not(entry ?& array['gate','status','execution','receipt_id','receipt_sha256','execution_release_id','execution_source_commit',
        'execution_contract_sha256','execution_installation_id','scope_id','scope_sha256','transaction_id','source_cycle_id','week_ending','original_census_sha256','source_cas_sha256'])
      or not(coalesce(entry->>'gate','')=any(needed)) or entry->>'status' is distinct from 'PREREQUISITE_PASS'
      or entry->>'execution' is distinct from 'AGENCY_TEST_NATIVE_ROLLBACK'
      or entry->>'execution_release_id' is distinct from executed.release_id
      or entry->>'execution_source_commit' is distinct from executed.git_commit
      or entry->>'execution_contract_sha256' is distinct from executed.installed_contract_sha256
      or entry->>'execution_installation_id' is distinct from q#>>'{execution_identity,installation_id}'
      or coalesce(entry->>'scope_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or coalesce(entry->>'transaction_id','') !~ '^[0-9]+$'
      or coalesce(entry->>'source_cycle_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or coalesce(entry->>'week_ending','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      or (entry->>'week_ending')::date<p_from or (p_to is not null and (entry->>'week_ending')::date>p_to)
      or nullif(entry->>'receipt_id','') is null
      or exists(select 1 from unnest(array['receipt_sha256','scope_sha256','original_census_sha256','source_cas_sha256']) field
        where coalesce(entry->>field,'') !~ '^[0-9a-f]{64}$') then
      raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  end loop;
  return q;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000';
end;
$function$;

-- Source proposal: explicit, expiring, fixture-only TEST admission in the
-- EXISTING audit log. No assignment/readiness mutation, table or service grant.
-- Only the existing controlled feature setup RPC calls the write owner.
create or replace function private.weekly_source_protected_test_authorization_v1(p_authorization_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare r private.cloudtms_database_releases%rowtype; auth jsonb; n integer;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if current_database()<>'cloudtms_test_clone' or r.status<>'VERIFIED' or r.completed_at_utc is null
    or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or r.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or jsonb_typeof(r.evidence_json->'weekly_source_protected_test_setup_authorizations') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_AUTHORIZATION_REQUIRED' using errcode='55000'; end if;
  select count(*),jsonb_agg(value)->0 into n,auth
    from jsonb_array_elements(r.evidence_json->'weekly_source_protected_test_setup_authorizations') value
    where value->>'authorization_id'=p_authorization_id::text;
  if n<>1 or not private.weekly_source_qualification_closed_object_v1(auth,array['schema_version','authorization_id','scope_id',
      'release_id','source_commit','contract_sha256','agency_id','source_group_id','source_cycle_id','setup_actor_user_id',
      'journey_actor_user_id','week_ending','expires_at_utc','fixture_namespace','fixture_manifest','original_census',
      'prerequisite_qualification_sha256','capabilities','authorization_sha256'])
    or auth->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_TEST_SETUP_AUTHORIZATION_V1'
    or auth->>'release_id' is distinct from r.release_id or auth->>'source_commit' is distinct from r.git_commit
    or auth->>'contract_sha256' is distinct from r.installed_contract_sha256
    or auth->'capabilities' is distinct from '["BULK_SIGNED"]'::jsonb
    or auth->>'fixture_namespace' is distinct from 'WSQ_TEST_'
    or auth->>'authorization_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_PROTECTED_TEST_SETUP_AUTHORIZATION_V1',auth-'authorization_sha256'),'hex') then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_AUTHORIZATION_REQUIRED' using errcode='55000'; end if;
  -- This is an observed latest installed release, not function-presence READY.
  if private.weekly_source_protected_qualification_release_v1()->>'release_id' is distinct from r.release_id then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_INSTALLED_RELEASE_REQUIRED' using errcode='55000'; end if;
  return auth;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_AUTHORIZATION_REQUIRED' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_protected_test_scope_assert_v1(
  p_cycle_id uuid,p_actor_user_id uuid,p_original_client_ids uuid[],p_work_event_id uuid default null
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare lease jsonb; auth jsonb; n integer; c public.weekly_source_cycles%rowtype;
  g public.weekly_source_groups%rowtype; clients uuid[]; expected jsonb; item jsonb; actual jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER' and environment='TEST';
  perform private.weekly_source_office_authority_v1(p_actor_user_id,'APPROVE_PROTECTED_PAY',g.id,null,c.finalisation_week_ending);
  select count(*),jsonb_agg(a.after_json)->0 into n,lease from public.audit_events a
    where a.object_type='weekly_source_protected_test_journey' and a.action='WEEKLY_SOURCE_TEST_JOURNEY_OPENED'
      and a.event_sequence_is_authoritative and a.after_json->>'source_cycle_id'=c.id::text
      and a.after_json->>'journey_actor_user_id'=p_actor_user_id::text
      and not exists(select 1 from public.audit_events closed where closed.object_type=a.object_type
        and closed.object_id_text=a.object_id_text and closed.event_sequence_is_authoritative
        and closed.action in ('WEEKLY_SOURCE_TEST_JOURNEY_CLOSED','WEEKLY_SOURCE_TEST_JOURNEY_REVOKED'));
  if n<>1 or lease->>'contract' is distinct from 'WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_V1'
    or lease->'operational_ready' is distinct from 'false'::jsonb
    or lease->>'scope_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_V1',lease-'scope_sha256'),'hex') then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_UNAVAILABLE' using errcode='55000'; end if;
  auth:=private.weekly_source_protected_test_authorization_v1((lease->>'authorization_id')::uuid);
  if lease->>'authorization_sha256' is distinct from auth->>'authorization_sha256'
    or lease->>'scope_id' is distinct from auth->>'scope_id'
    or lease->>'source_cycle_id' is distinct from auth->>'source_cycle_id'
    or lease->>'journey_actor_user_id' is distinct from auth->>'journey_actor_user_id'
    or lease->>'week_ending' is distinct from c.finalisation_week_ending::text
    or auth->>'agency_id' is distinct from g.agency_id::text or auth->>'source_group_id' is distinct from g.id::text
    or clock_timestamp()>=(auth->>'expires_at_utc')::timestamptz
    or (clock_timestamp() at time zone 'Europe/London')::date is distinct from (lease->>'opened_local_date')::date
    or exists(select 1 from public.weekly_source_group_rule_assignments a where a.source_group_id=g.id and a.feature_enabled
      and c.finalisation_week_ending between a.effective_from_week_ending and coalesce(a.effective_to_week_ending,'infinity'::date))
    or private.weekly_source_bulk_producer_ready_v1(c.id) or private.weekly_source_automatic_reconcile_producer_ready_v1(c.id) then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_UNAVAILABLE' using errcode='55000'; end if;
  select array_agg(value::uuid order by value::uuid) into clients
    from jsonb_array_elements_text(auth#>'{original_census,original_client_ids}') value;
  if p_original_client_ids is not null and to_jsonb(p_original_client_ids) is distinct from to_jsonb(clients) then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_ORIGINAL_CENSUS_CHANGED' using errcode='40001'; end if;
  if private.weekly_source_bulk_source_cas_v1(c.id,clients) is distinct from auth#>'{original_census,source_cas}' then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_SOURCE_CHANGED' using errcode='40001'; end if;
  for item in select value from jsonb_array_elements(auth#>'{original_census,original_root_identities}') value loop
    select jsonb_build_object('timesheet_id',s.timesheet_id,'booking_id',s.booking_id,'contract_id',k.id,
      'candidate_id',k.candidate_id,'client_id',k.client_id) into actual
      from public.timesheets s join public.contracts k on k.id=s.contract_id
      where s.timesheet_id=(item->>'timesheet_id')::uuid and (s.client_id is null or s.client_id=k.client_id);
    if actual is distinct from item then raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_ORIGINAL_ROOT_CHANGED' using errcode='40001'; end if;
  end loop;
  if p_work_event_id is not null and not exists(select 1 from jsonb_array_elements(auth#>'{original_census,original_items}') item
    where item->>'work_event_id'=p_work_event_id::text) then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_FOREIGN_EVENT_REFUSED' using errcode='42501'; end if;
  return lease||jsonb_build_object('original_census',auth->'original_census','capabilities',auth->'capabilities');
exception when no_data_found or too_many_rows or invalid_text_representation or datetime_field_overflow then
  raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_UNAVAILABLE' using errcode='55000';
end;
$function$;

-- This write helper is not a new public/service RPC. The existing admin-only
-- feature setup owner dispatches OPEN/CLOSE/REVOKE, always before feature writes.
create or replace function private.weekly_source_protected_test_setup_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare actor uuid; auth jsonb; lease jsonb; result jsonb; c public.weekly_source_cycles%rowtype;
  g public.weekly_source_groups%rowtype; action text; manifest jsonb; census jsonb; n integer; q jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if not private.weekly_source_qualification_closed_object_v1(p_request,array['actor_user_id','agency_id','environment','qualification_action',
      'authorization_id','expected_authorization_sha256','reason'])
    or not(p_request ?& array['actor_user_id','agency_id','environment','qualification_action','authorization_id','expected_authorization_sha256','reason'])
    or char_length(coalesce(p_request->>'reason','')) not between 1 and 500 then
    raise exception 'WEEKLY_SOURCE_TEST_SETUP_REQUEST_INVALID' using errcode='22023'; end if;
  actor:=(p_request->>'actor_user_id')::uuid;action:=p_request->>'qualification_action';
  perform private._weekly_source_settings_require_admin_v1(actor);
  if private._weekly_source_settings_deployment_v1((p_request->>'agency_id')::uuid,p_request->>'environment')<>'TEST'
    or action not in ('OPEN','CLOSE','REVOKE') then raise exception 'WEEKLY_SOURCE_TEST_SETUP_REQUEST_INVALID' using errcode='22023'; end if;
  auth:=private.weekly_source_protected_test_authorization_v1((p_request->>'authorization_id')::uuid);
  if auth->>'authorization_sha256' is distinct from p_request->>'expected_authorization_sha256'
    or auth->>'setup_actor_user_id' is distinct from actor::text or auth->>'agency_id' is distinct from p_request->>'agency_id' then
    raise exception 'WEEKLY_SOURCE_TEST_SETUP_AUTHORIZATION_CHANGED' using errcode='40001'; end if;
  perform pg_advisory_xact_lock(hashtextextended('weekly-source-test-journey:'||auth->>'scope_id',0));
  select * into strict c from public.weekly_source_cycles where id=(auth->>'source_cycle_id')::uuid;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and id=(auth->>'source_group_id')::uuid
    and active and source_family='ROSTER' and environment='TEST';
  if g.code is distinct from auth#>>'{fixture_manifest,group_code}' or g.code !~ '^WSQ_TEST_[A-Z0-9_]+$'
    or g.agency_id::text is distinct from auth->>'agency_id'
    or c.finalisation_week_ending::text is distinct from auth->>'week_ending' then
    raise exception 'WEEKLY_SOURCE_TEST_SETUP_FIXTURE_SCOPE_INVALID' using errcode='42501'; end if;
  select count(*),jsonb_agg(a.after_json)->0 into n,lease from public.audit_events a
    where a.object_type='weekly_source_protected_test_journey' and a.object_id_text=auth->>'scope_id'
      and a.action='WEEKLY_SOURCE_TEST_JOURNEY_OPENED' and a.event_sequence_is_authoritative;
  if exists(select 1 from public.audit_events a where a.object_type='weekly_source_protected_test_journey'
    and a.object_id_text=auth->>'scope_id' and a.event_sequence_is_authoritative
    and a.action in ('WEEKLY_SOURCE_TEST_JOURNEY_CLOSED','WEEKLY_SOURCE_TEST_JOURNEY_REVOKED')) then
    raise exception 'WEEKLY_SOURCE_TEST_SETUP_SCOPE_TERMINAL' using errcode='55000'; end if;
  if action='OPEN' then
    perform private.weekly_source_office_authority_v1((auth->>'journey_actor_user_id')::uuid,'APPROVE_PROTECTED_PAY',g.id,null,c.finalisation_week_ending);
    if n<>0 or (auth->>'expires_at_utc')::timestamptz<=clock_timestamp()
      or (auth->>'expires_at_utc')::timestamptz>clock_timestamp()+interval '2 hours'
      or exists(select 1 from public.weekly_source_group_rule_assignments a where a.source_group_id=g.id and a.feature_enabled
        and c.finalisation_week_ending between a.effective_from_week_ending and coalesce(a.effective_to_week_ending,'infinity'::date))
      or private.weekly_source_bulk_producer_ready_v1(c.id) or private.weekly_source_automatic_reconcile_producer_ready_v1(c.id) then
      raise exception 'WEEKLY_SOURCE_TEST_SETUP_OPEN_REFUSED' using errcode='55000'; end if;
    census:=private.weekly_source_protected_qualification_census_v1(c.id);
    if census is distinct from auth->'original_census' then raise exception 'WEEKLY_SOURCE_TEST_SETUP_CENSUS_CHANGED' using errcode='40001'; end if;
    manifest:=auth->'fixture_manifest';
    if manifest->'client_ids' is distinct from census->'original_client_ids'
      or (select coalesce(jsonb_agg(distinct item->'candidate_id' order by item->'candidate_id'),'[]'::jsonb)
        from jsonb_array_elements(census->'original_items') item) is distinct from manifest->'candidate_ids'
      or (select coalesce(jsonb_agg(distinct item->'contract_id' order by item->'contract_id'),'[]'::jsonb)
        from jsonb_array_elements(census->'original_items') item) is distinct from manifest->'contract_ids'
      or (select coalesce(jsonb_agg(distinct item->'work_event_id' order by item->'work_event_id'),'[]'::jsonb)
        from jsonb_array_elements(census->'original_items') item) is distinct from manifest->'work_event_ids'
      or (select coalesce(jsonb_agg(item->'timesheet_id' order by item->'timesheet_id'),'[]'::jsonb)
        from jsonb_array_elements(census->'original_root_identities') item) is distinct from manifest->'original_root_ids'
      or (select coalesce(jsonb_agg(item->'client_id' order by item->'client_id'),'[]'::jsonb)
        from jsonb_array_elements(manifest->'client_refs') item) is distinct from manifest->'client_ids'
      or (select coalesce(jsonb_agg(item->'candidate_id' order by item->'candidate_id'),'[]'::jsonb)
        from jsonb_array_elements(manifest->'candidate_refs') item) is distinct from manifest->'candidate_ids'
      or exists(select 1 from jsonb_array_elements(manifest->'client_refs') item
        where coalesce(item->>'cli_ref','') !~ '^CLI-913013[0-9]{2}$'
          or not exists(select 1 from public.clients client where client.id=(item->>'client_id')::uuid and client.cli_ref=item->>'cli_ref'))
      or exists(select 1 from jsonb_array_elements(manifest->'candidate_refs') item
        where coalesce(item->>'tms_ref','') !~ '^CCR-913013[0-9]{2}$'
          or not exists(select 1 from public.candidates candidate where candidate.id=(item->>'candidate_id')::uuid and candidate.tms_ref=item->>'tms_ref')) then
      raise exception 'WEEKLY_SOURCE_TEST_SETUP_FIXTURE_SCOPE_INVALID' using errcode='42501'; end if;
    -- Explicit prerequisite evidence stays NON-OPERATIONAL. Its NEXT_PAY row
    -- must be a genuine installed Banking prerequisite; root's managed writer
    -- binds the artifact/record. Function presence is never accepted here.
    select value into strict q from private.cloudtms_database_releases r,
      lateral jsonb_array_elements(r.evidence_json->'weekly_source_protected_capability_qualifications') value
      where r.release_id=auth->>'release_id' and value->>'qualification_sha256'=auth->>'prerequisite_qualification_sha256';
    perform private.weekly_source_protected_prerequisite_release_assert_v2(q,g.id,
      (q->>'effective_from_week_ending')::date,(q->>'effective_to_week_ending')::date,auth->>'prerequisite_qualification_sha256');
    if q->'capabilities' is distinct from '["BULK_SIGNED"]'::jsonb
      or not exists(select 1 from jsonb_array_elements(q->'gate_receipts') receipt
        where receipt->>'gate'='NEXT_PAY' and receipt->>'status'='PREREQUISITE_PASS') then
      raise exception 'WEEKLY_SOURCE_TEST_SETUP_NEXT_PREREQUISITE_REQUIRED' using errcode='55000'; end if;
    lease:=jsonb_build_object('contract','WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_V1','scope_id',auth->>'scope_id',
      'authorization_id',auth->>'authorization_id','authorization_sha256',auth->>'authorization_sha256',
      'source_group_id',g.id,'source_cycle_id',c.id,'agency_id',g.agency_id,'week_ending',c.finalisation_week_ending,
      'journey_actor_user_id',auth->>'journey_actor_user_id','setup_actor_user_id',actor,'expires_at_utc',auth->>'expires_at_utc',
      'opened_local_date',(clock_timestamp() at time zone 'Europe/London')::date,'operational_ready',false);
    lease:=lease||jsonb_build_object('scope_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_V1',lease),'hex'));
    perform public._audit_insert('weekly_source_protected_test_journey',auth->>'scope_id','WEEKLY_SOURCE_TEST_JOURNEY_OPENED',null,lease,p_request->>'reason',actor);
    return lease;
  end if;
  if n<>1 then raise exception 'WEEKLY_SOURCE_TEST_SETUP_SCOPE_UNAVAILABLE' using errcode='55000'; end if;
  if action='CLOSE' then
    perform private.weekly_source_protected_test_scope_assert_v1(c.id,(auth->>'journey_actor_user_id')::uuid,null,null);
    result:=jsonb_build_object('scope_id',auth->>'scope_id','scope_sha256',lease->>'scope_sha256','setup_authorization_sha256',auth->>'authorization_sha256',
      'original_census_sha256',auth#>>'{original_census,census_sha256}','actor_user_id',auth->>'journey_actor_user_id',
      'source_cycle_id',c.id,'week_ending',c.finalisation_week_ending,'execution_release_id',auth->>'release_id',
      'execution_source_commit',auth->>'source_commit','execution_contract_sha256',auth->>'contract_sha256',
      'state','CLOSED','closed_at_utc',clock_timestamp(),'all_assignments_disabled',true,'all_operational_producers_false',true);
  else
    result:=jsonb_build_object('scope_id',auth->>'scope_id','state','REVOKED','closed_at_utc',clock_timestamp(),'operational_ready',false);
  end if;
  perform public._audit_insert('weekly_source_protected_test_journey',auth->>'scope_id',
    case when action='CLOSE' then 'WEEKLY_SOURCE_TEST_JOURNEY_CLOSED' else 'WEEKLY_SOURCE_TEST_JOURNEY_REVOKED' end,
    lease,result,p_request->>'reason',actor);
  return result;
exception when no_data_found or too_many_rows or invalid_text_representation or datetime_field_overflow then
  raise exception 'WEEKLY_SOURCE_TEST_SETUP_REQUEST_INVALID' using errcode='22023';
end;
$function$;

create or replace function private.weekly_source_protected_capability_release_evidence_v1(
  p_group_id uuid,p_from date,p_to date,p_expected_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare g public.weekly_source_groups%rowtype; r private.cloudtms_database_releases%rowtype;
  q jsonb; entry jsonb; count_rows integer; needed text[]; cap text;
begin
  select * into strict g from public.weekly_source_groups where id=p_group_id and active and source_family='ROSTER';
  select * into r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if not found or r.status<>'VERIFIED' or r.completed_at_utc is null
    or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or g.environment<>'TEST' or current_database()<>'cloudtms_test_clone'
    or not exists(select 1 from private.cloudtms_database_identity where singleton and environment=g.environment)
    or r.evidence_json#>>'{managed_release,environment}' is distinct from g.environment
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or jsonb_typeof(r.evidence_json->'weekly_source_protected_capability_qualifications') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  select count(*),jsonb_agg(value)->0 into count_rows,q
    from jsonb_array_elements(r.evidence_json->'weekly_source_protected_capability_qualifications') value
    where value->>'source_group_id'=g.id::text and value->>'effective_from_week_ending'=p_from::text
      and value->>'effective_to_week_ending' is not distinct from p_to::text;
  if count_rows<>1 then raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  return private.weekly_source_protected_operational_certificate_assert_v1(q,p_group_id,p_from,p_to,p_expected_sha256);
  -- The original V1-only validator remains unreachable evidence below. It
  -- cannot admit native-only or pending certificates into an operational path.
  if count_rows<>1 or not private.weekly_exceptional_json_keys_exact_v1(q,array[
      'schema_version','release_id','git_commit','contract_sha256','agency_id','environment','source_group_id',
      'effective_from_week_ending','effective_to_week_ending','capabilities','gate_receipts','qualification_sha256'])
    or not(q ?& array['schema_version','release_id','git_commit','contract_sha256','agency_id','environment','source_group_id',
      'effective_from_week_ending','effective_to_week_ending','capabilities','gate_receipts','qualification_sha256'])
    or q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1'
    or q->>'release_id' is distinct from r.release_id or q->>'git_commit' is distinct from r.git_commit
    or q->>'contract_sha256' is distinct from r.installed_contract_sha256
    or q->>'agency_id' is distinct from g.agency_id::text or q->>'environment' is distinct from g.environment
    or coalesce(q->>'qualification_sha256','') !~ '^[0-9a-f]{64}$'
    or q->>'qualification_sha256' is distinct from p_expected_sha256
    or encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1',q-'qualification_sha256'),'hex')
      is distinct from q->>'qualification_sha256'
    or jsonb_typeof(q->'capabilities') is distinct from 'array' or jsonb_array_length(q->'capabilities') not between 1 and 2
    or exists(select 1 from jsonb_array_elements(q->'capabilities') value where jsonb_typeof(value)<>'string'
      or value#>>'{}' not in ('BULK_SIGNED','AUTOMATIC_RECONCILE'))
    or (select count(distinct value) from jsonb_array_elements(q->'capabilities') value)<>jsonb_array_length(q->'capabilities')
    or (q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb and not(q->'capabilities' @> '["BULK_SIGNED"]'::jsonb))
    or jsonb_typeof(q->'gate_receipts') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  needed:=array['SOURCE_CAS_NATIVE','NATIVE_PROTECTION','SECURITY','LEGACY_PAY','NEXT_PAY','CLIENT_API','DOCUMENT','OWN_STAGE_CAS','SOURCE_ROUTING'];
  if q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb then needed:=array_append(needed,'AUTOMATIC_COMPONENT_DELTA'); end if;
  if jsonb_array_length(q->'gate_receipts')<>cardinality(needed)
    or (select count(distinct value->>'gate') from jsonb_array_elements(q->'gate_receipts') value)<>cardinality(needed) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  for entry in select value from jsonb_array_elements(q->'gate_receipts') value loop
    if not private.weekly_exceptional_json_keys_exact_v1(entry,array['gate','status','execution','database','receipt_id','receipt_sha256',
        'source_commit','contract_sha256','source_group_id','agency_id','environment'])
      or not(entry ?& array['gate','status','execution','database','receipt_id','receipt_sha256',
        'source_commit','contract_sha256','source_group_id','agency_id','environment'])
      or not(coalesce(entry->>'gate','')=any(needed)) or entry->>'status' is distinct from 'PASS'
      or entry->>'execution' is distinct from 'AGENCY_TEST_NATIVE' or entry->>'database' is distinct from current_database()
      or entry->>'source_commit' is distinct from r.git_commit or entry->>'contract_sha256' is distinct from r.installed_contract_sha256
      or entry->>'source_group_id' is distinct from g.id::text or entry->>'agency_id' is distinct from g.agency_id::text
      or entry->>'environment' is distinct from g.environment or nullif(btrim(entry->>'receipt_id'),'') is null
      or char_length(entry->>'receipt_id')>256 or coalesce(entry->>'receipt_sha256','') !~ '^[0-9a-f]{64}$' then
      raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  end loop;
  return q;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_protected_capability_receipt_v1(p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  a public.weekly_source_group_rule_assignments%rowtype; q jsonb; receipt jsonb;
begin
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  select * into strict a from public.weekly_source_group_rule_assignments where source_group_id=g.id and feature_enabled
    and c.finalisation_week_ending between effective_from_week_ending and coalesce(effective_to_week_ending,'infinity'::date);
  receipt:=a.feature_receipt_json;
  if a.feature_purpose is null or a.feature_purpose not in ('RULE_SET','PROTECTED_SOURCE')
    or (a.feature_purpose='PROTECTED_SOURCE' and a.rule_set_version_id is not null)
    or receipt->>'contract' is distinct from 'WEEKLY_SOURCE_RULE_FEATURE_RECEIPT_V1'
    or receipt->>'assignment_id' is distinct from a.id::text or receipt->>'assignment_version' is distinct from a.version::text
    or receipt->>'source_group_id' is distinct from g.id::text
    or receipt->>'rule_set_version_id' is distinct from a.rule_set_version_id::text
    or receipt->>'feature_purpose' is distinct from a.feature_purpose or receipt->'feature_enabled' is distinct from 'true'::jsonb
    or receipt->>'actor_user_id' is distinct from a.feature_changed_by_user_id::text
    or receipt->>'request_id' is distinct from a.feature_request_id::text or receipt->>'release_id' is distinct from a.feature_release_id
    or receipt->>'effective_from_week_ending' is distinct from a.effective_from_week_ending::text
    or a.feature_request_sha256 is null or a.feature_changed_at_utc is null
    or not exists(select 1 from public.tms_users actor where actor.id=a.feature_changed_by_user_id and actor.is_active and actor.role='admin') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_ACTIVATION_UNQUALIFIED' using errcode='55000'; end if;
  q:=private.weekly_source_protected_capability_release_evidence_v1(g.id,a.effective_from_week_ending,a.effective_to_week_ending,
    receipt#>>'{protected_capability_qualification,qualification_sha256}');
  if q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_OPERATIONAL_QUALIFICATION_V1'
    or q->>'phase' is distinct from 'ALL_PRE_SWITCH_GATES_QUALIFIED'
    or q is distinct from receipt->'protected_capability_qualification' or q->>'release_id' is distinct from a.feature_release_id then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_ACTIVATION_UNQUALIFIED' using errcode='55000'; end if;
  return q;
end;
$function$;

create or replace function private.weekly_source_bulk_producer_ready_v1(p_cycle_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare q jsonb;
begin
  q:=private.weekly_source_protected_capability_receipt_v1(p_cycle_id);
  return coalesce(q->>'schema_version'='WEEKLY_SOURCE_PROTECTED_CAPABILITY_OPERATIONAL_QUALIFICATION_V1'
    and q->>'phase'='ALL_PRE_SWITCH_GATES_QUALIFIED' and q->'capabilities' @> '["BULK_SIGNED"]'::jsonb,false);
exception when no_data_found or too_many_rows or sqlstate '55000' then return false;
end;
$function$;

create or replace function private.weekly_source_automatic_reconcile_producer_ready_v1(p_cycle_id uuid)
returns boolean language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare q jsonb; c public.weekly_source_cycles%rowtype; actual_client uuid; rules jsonb;
begin
  q:=private.weekly_source_protected_capability_receipt_v1(p_cycle_id);
  if q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_OPERATIONAL_QUALIFICATION_V1'
    or q->>'phase' is distinct from 'ALL_PRE_SWITCH_GATES_QUALIFIED'
    or not(q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb) then return false; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  actual_client:=private.weekly_source_checking_client_scope_v1(c.current_projection_publication_id);
  if actual_client is not null then
    rules:=private.weekly_source_effective_rule_set_v1(actual_client,c.id)->'values';
    return coalesce(rules->>'invoice_sender'='CLIENT_SELF_BILL' and rules->>'equal_protected_hours'='CLEAR_AUTOMATICALLY',false);
  end if;
  -- Legacy group-wide scope is retained. Each actual event's S18b rule check
  -- remains in the normal selection owner; readiness grants no event permission.
  return exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=c.source_group_id
    and c.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date)
    and private.weekly_source_effective_rule_set_v1(member.client_id,c.id)#>>'{values,invoice_sender}'='CLIENT_SELF_BILL'
    and private.weekly_source_effective_rule_set_v1(member.client_id,c.id)#>>'{values,equal_protected_hours}'='CLEAR_AUTOMATICALLY');
exception when no_data_found or too_many_rows or sqlstate '55000' then return false;
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_source_group_rule_feature_set_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_actor uuid; v_agency uuid; v_environment text; v_group_id uuid; v_assignment_id uuid; v_version_id uuid;
  v_request_id uuid; v_expected bigint; v_enabled boolean; v_from date; v_release_id text; v_reason text; v_purpose text; v_hash text; v_receipt jsonb;
  v_group public.weekly_source_groups%rowtype; v_assignment public.weekly_source_group_rule_assignments%rowtype;
  v_latest private.cloudtms_database_releases%rowtype; v_values jsonb;
  v_member record; v_manifest jsonb; v_shape jsonb; v_result jsonb; v_changes jsonb:='[]'::jsonb;
  v_entry jsonb; v_apply_values jsonb; v_scope_date date; v_agency_invoice boolean:=false; v_qualification jsonb;
begin
  if p_request ? 'qualification_action' then
    return private.weekly_source_protected_test_setup_atomic_v1(p_request);
  end if;
  perform private._weekly_source_settings_assert_request_v1(p_request,array['actor_user_id','agency_id','environment','source_group_id','assignment_id',
    'rule_set_version_id','effective_from_week_ending','expected_assignment_version','feature_enabled','feature_purpose','release_id','reason','request_id',
    'client_settings_versions','protected_capability_qualification_sha256'],'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID');
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid; v_agency:=(p_request->>'agency_id')::uuid; v_group_id:=(p_request->>'source_group_id')::uuid;
    v_assignment_id:=(p_request->>'assignment_id')::uuid; v_version_id:=nullif(p_request->>'rule_set_version_id','')::uuid;
    v_request_id:=(p_request->>'request_id')::uuid; v_expected:=(p_request->>'expected_assignment_version')::bigint;
    v_enabled:=(p_request->>'feature_enabled')::boolean; v_from:=(p_request->>'effective_from_week_ending')::date;
    v_release_id:=p_request->>'release_id'; v_reason:=btrim(p_request->>'reason'); v_purpose:=p_request->>'feature_purpose';
  exception when others then raise exception 'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID' using errcode='22023'; end;
  perform private._weekly_source_settings_require_admin_v1(v_actor);
  v_environment:=private._weekly_source_settings_deployment_v1(v_agency,p_request->>'environment');
  if v_group_id is null or v_assignment_id is null or v_request_id is null or v_expected is null or v_from is null
    or jsonb_typeof(p_request->'feature_enabled') is distinct from 'boolean'
    or not p_request ? 'rule_set_version_id' or v_release_id is null or v_reason is null or char_length(v_reason) not between 1 and 500
    or v_purpose is null or v_purpose not in ('RULE_SET','SIGNED_CHECK_ONLY','PROTECTED_SOURCE') or (v_version_id is null)<>(v_purpose in ('SIGNED_CHECK_ONLY','PROTECTED_SOURCE'))
    or p_request->>'effective_from_week_ending'<>to_char(v_from,'YYYY-MM-DD') then
    raise exception 'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID' using errcode='22023'; end if;
  if p_request ? 'protected_capability_qualification_sha256' and
    (jsonb_typeof(p_request->'protected_capability_qualification_sha256') is distinct from 'string'
      or coalesce(p_request->>'protected_capability_qualification_sha256','') !~ '^[0-9a-f]{64}$') then
    raise exception 'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID' using errcode='22023'; end if;
  if v_purpose='PROTECTED_SOURCE' and v_enabled and not(p_request ? 'protected_capability_qualification_sha256') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_RELEASE_UNQUALIFIED' using errcode='55000'; end if;
  if v_purpose='SIGNED_CHECK_ONLY' and p_request ? 'protected_capability_qualification_sha256' then
    raise exception 'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID' using errcode='22023'; end if;
  v_hash:=encode(extensions.digest(convert_to(p_request::text,'UTF8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('weekly-source-cycle-lifecycle:'||v_group_id::text,0));
  -- Match the Client owner's client-before-group lock order. Recheck the exact
  -- dated membership after taking the group/assignment locks below.
  if (select count(distinct gc.client_id) from public.weekly_source_group_clients gc
    where gc.source_group_id=v_group_id and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]')
      && daterange(v_from-6,'infinity'::date,'[]'))>100 then
    raise exception 'WEEKLY_SOURCE_RULE_ACTIVATION_SCOPE_TOO_LARGE' using errcode='22023'; end if;
  for v_member in select distinct gc.client_id from public.weekly_source_group_clients gc
    where gc.source_group_id=v_group_id and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]')
      && daterange(v_from-6,'infinity'::date,'[]') order by gc.client_id
  loop
    perform pg_advisory_xact_lock(hashtextextended('weekly-source-settings-client:'||v_member.client_id::text,0));
  end loop;
  select * into v_group from public.weekly_source_groups where id=v_group_id for update;
  if not found or v_group.agency_id<>v_agency or v_group.environment<>v_environment or not v_group.active or v_group.source_family<>'ROSTER' then
    raise exception 'WEEKLY_SOURCE_RULE_GROUP_NOT_APPLICABLE' using errcode='22023'; end if;
  select * into v_assignment from public.weekly_source_group_rule_assignments where id=v_assignment_id and source_group_id=v_group_id for update;
  if not found or v_assignment.rule_set_version_id is distinct from v_version_id or v_assignment.effective_from_week_ending<>v_from then
    raise exception 'WEEKLY_SOURCE_RULE_ASSIGNMENT_NOT_FOUND' using errcode='22023'; end if;
  -- Latest record, not latest successful record: an APPLYING/FAILED successor holds activation.
  select * into v_latest from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if not found or v_latest.release_id<>v_release_id or v_latest.status<>'VERIFIED'
    or v_latest.completed_at_utc is null or v_latest.installed_contract_sha256 is distinct from v_latest.repository_contract_sha256 then
    raise exception 'WEEKLY_SOURCE_RULE_VERIFIED_RELEASE_REQUIRED' using errcode='55000'; end if;
  if v_assignment.feature_request_id=v_request_id then
    if v_assignment.feature_request_sha256<>v_hash then raise exception 'WEEKLY_SOURCE_RULE_REQUEST_REUSED' using errcode='22023'; end if;
    if v_assignment.feature_enabled and v_assignment.feature_receipt_json ? 'protected_capability_qualification' then
      perform private.weekly_source_protected_operational_certificate_assert_v1(
        v_assignment.feature_receipt_json->'protected_capability_qualification',v_group_id,v_from,v_assignment.effective_to_week_ending,
        v_assignment.feature_receipt_json#>>'{protected_capability_qualification,qualification_sha256}');
    end if;
    return v_assignment.feature_receipt_json||jsonb_build_object('replayed',true);
  end if;
  if v_assignment.version<>v_expected then raise exception 'WEEKLY_SOURCE_RULE_ASSIGNMENT_STALE' using errcode='40001'; end if;
  perform 1 from public.clients c where exists(select 1 from public.weekly_source_group_clients gc
    where gc.client_id=c.id and gc.source_group_id=v_group_id
      and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]'))
    order by c.id for update;
  perform 1 from public.client_settings cs where exists(select 1 from public.weekly_source_group_clients gc
    where gc.client_id=cs.client_id and gc.source_group_id=v_group_id
      and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]'))
    order by cs.id for update;
  perform 1 from public.contracts c where exists(select 1 from public.weekly_source_group_clients gc
    where gc.client_id=c.client_id and gc.source_group_id=v_group_id
      and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]'))
    order by c.id for share;
  -- Same owner requalification is metadata-only. Exact current assignment CAS,
  -- actor/deployment/latest VERIFIED and locked Client/Contract gates above stay.
  if v_enabled and p_request ? 'protected_capability_qualification_sha256' then
    v_qualification:=private.weekly_source_protected_capability_release_evidence_v1(v_group_id,v_from,
      v_assignment.effective_to_week_ending,p_request->>'protected_capability_qualification_sha256');
    perform private.weekly_source_protected_operational_certificate_assert_v1(v_qualification,v_group_id,v_from,
      v_assignment.effective_to_week_ending,p_request->>'protected_capability_qualification_sha256');
  elsif p_request ? 'protected_capability_qualification_sha256' then
    raise exception 'WEEKLY_SOURCE_RULE_FEATURE_REQUEST_INVALID' using errcode='22023'; end if;
  if v_assignment.feature_enabled=v_enabled then
    if not v_enabled or v_qualification is null or v_assignment.feature_purpose is distinct from v_purpose then
      raise exception 'WEEKLY_SOURCE_RULE_FEATURE_ALREADY_SET' using errcode='22023'; end if;
    if v_purpose='PROTECTED_SOURCE' then
      perform private.weekly_source_protected_source_activation_scope_v1(v_group_id,v_from,v_assignment.effective_to_week_ending);
    else
      select values_json into strict v_values from public.weekly_source_rule_set_versions where id=v_version_id;
      perform private._weekly_source_rule_group_context_v1(v_group_id,v_from,v_assignment.effective_to_week_ending,v_values,true);
    end if;
    if p_request ? 'client_settings_versions' and p_request->'client_settings_versions'<>'[]'::jsonb then
      raise exception 'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_INVALID' using errcode='22023'; end if;
    -- Preserve the exact AGENCY restore receipt, without calling Client save.
    v_receipt:=v_assignment.feature_receipt_json||jsonb_build_object('assignment_version',v_assignment.version+1,
      'release_id',v_release_id,'actor_user_id',v_actor,'changed_at_utc',transaction_timestamp(),'reason',v_reason,
      'request_id',v_request_id,'protected_capability_qualification',v_qualification,'requalification',true,'replayed',false);
    update public.weekly_source_group_rule_assignments set feature_changed_by_user_id=v_actor,
      feature_changed_at_utc=transaction_timestamp(),feature_change_reason=v_reason,feature_release_id=v_release_id,
      feature_request_id=v_request_id,feature_request_sha256=v_hash,feature_receipt_json=v_receipt,version=version+1 where id=v_assignment_id;
    return v_receipt;
  end if;
  select v.values_json into v_values from public.weekly_source_rule_set_versions v join public.weekly_source_rule_sets r on r.id=v.rule_set_id
    where v.id=v_version_id and r.agency_id=v_agency and r.environment=v_environment;
  if v_version_id is not null and not found then raise exception 'WEEKLY_SOURCE_RULE_VERSION_NOT_FOUND' using errcode='22023'; end if;
  v_agency_invoice:=coalesce(v_values->>'invoice_sender'='AGENCY_INVOICE',false);
  if v_agency_invoice then
    v_manifest:=p_request->'client_settings_versions';
    if jsonb_typeof(v_manifest) is distinct from 'array' or jsonb_array_length(v_manifest) not between 1 and 100 then
      raise exception 'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_REQUIRED' using errcode='22023'; end if;
    for v_entry in select value from jsonb_array_elements(v_manifest) loop
      perform private._weekly_source_settings_assert_request_v1(v_entry,array['client_id','expected_settings_version'],'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_INVALID');
      if jsonb_typeof(v_entry->'client_id') is distinct from 'string' or v_entry->>'client_id' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
        or jsonb_typeof(v_entry->'expected_settings_version') is distinct from 'string'
        or v_entry->>'expected_settings_version' !~ '^[0-9a-f]{64}$' then
        raise exception 'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_INVALID' using errcode='22023'; end if;
    end loop;
    if (select count(distinct value->>'client_id') from jsonb_array_elements(v_manifest))<>jsonb_array_length(v_manifest)
      or (select count(distinct gc.client_id) from public.weekly_source_group_clients gc where gc.source_group_id=v_group_id
        and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]'))<>jsonb_array_length(v_manifest)
      or exists(select 1 from jsonb_array_elements(v_manifest) x where not exists(select 1 from public.weekly_source_group_clients gc
        where gc.source_group_id=v_group_id and gc.client_id=(x.value->>'client_id')::uuid
          and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]'))) then
      raise exception 'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_INVALID' using errcode='22023'; end if;
    for v_member in select gc.client_id,greatest(v_from-6,min(gc.valid_from)) as scope_date
      from public.weekly_source_group_clients gc where gc.source_group_id=v_group_id
        and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]') && daterange(v_from-6,coalesce(v_assignment.effective_to_week_ending,'infinity'::date),'[]')
      group by gc.client_id order by gc.client_id
    loop
      v_scope_date:=v_member.scope_date;
      if v_scope_date<(transaction_timestamp() at time zone 'Europe/London')::date then
        raise exception 'WEEKLY_SOURCE_RULE_FUTURE_WEEK_REQUIRED' using errcode='22023'; end if;
      v_shape:=private._weekly_source_settings_client_shape_v1(v_agency,v_environment,v_member.client_id,v_scope_date);
      if v_shape->>'settings_version'<>(select value->>'expected_settings_version' from jsonb_array_elements(v_manifest) where (value->>'client_id')::uuid=v_member.client_id) then
        raise exception 'WEEKLY_SOURCE_RULE_CLIENT_SETTINGS_STALE' using errcode='40001'; end if;
      if v_enabled then
        if exists(select 1 from public.weekly_source_client_policies cp where cp.source_group_id=v_group_id and cp.client_id=v_member.client_id
          and cp.effective_from>v_scope_date and cp.effective_from<=coalesce(v_assignment.effective_to_week_ending,'infinity'::date)) then
          raise exception 'WEEKLY_SOURCE_RULE_ACTIVATION_FUTURE_SETTINGS_REFUSED' using errcode='22023'; end if;
        v_changes:=v_changes||jsonb_build_array(jsonb_build_object('client_id',v_member.client_id,'scope_date',v_scope_date,
          'before_values',v_shape->'settings','before_settings_version',v_shape->>'settings_version',
          'before_policy_id',(select cp.id from public.weekly_source_client_policies cp where cp.source_group_id=v_group_id and cp.client_id=v_member.client_id
            and v_scope_date between cp.effective_from and coalesce(cp.effective_to,'infinity'::date))));
      else
        select value into v_entry from jsonb_array_elements(v_assignment.feature_receipt_json->'client_changes')
          where (value->>'client_id')::uuid=v_member.client_id;
        if not found or v_entry->>'after_settings_version' is distinct from v_shape->>'settings_version'
          or (v_entry->>'scope_date')::date<>v_scope_date then
          raise exception 'WEEKLY_SOURCE_RULE_CLIENT_RESTORE_STALE' using errcode='40001'; end if;
        v_changes:=v_changes||jsonb_build_array(v_entry);
      end if;
    end loop;
  elsif p_request ? 'client_settings_versions' and p_request->'client_settings_versions'<>'[]'::jsonb then
    raise exception 'WEEKLY_SOURCE_RULE_CLIENT_CAS_MANIFEST_INVALID' using errcode='22023';
  end if;
  if v_enabled then
    if v_from<(transaction_timestamp() at time zone 'Europe/London')::date then
      raise exception 'WEEKLY_SOURCE_RULE_FUTURE_WEEK_REQUIRED' using errcode='22023'; end if;
    perform 1 from public.weekly_source_cycles c where c.source_group_id=v_group_id
      and c.finalisation_week_ending between v_from and coalesce(v_assignment.effective_to_week_ending,'infinity'::date) order by c.id for update;
    if exists(select 1 from public.weekly_source_cycles c where c.source_group_id=v_group_id
      and c.finalisation_week_ending between v_from and coalesce(v_assignment.effective_to_week_ending,'infinity'::date)
      and (c.current_final_revision_id is not null or c.state in ('FINALISING','FINALISED','CORRECTION_IN_PROGRESS')
        or exists(select 1 from public.weekly_source_final_revisions f where f.source_cycle_id=c.id))) then
      raise exception 'WEEKLY_SOURCE_RULE_FINALISED_WEEK_REFUSED' using errcode='55000'; end if;
    if v_purpose='PROTECTED_SOURCE' then
      perform private.weekly_source_protected_source_activation_scope_v1(v_group_id,v_from,v_assignment.effective_to_week_ending);
    else
      perform private._weekly_source_rule_group_context_v1(v_group_id,v_from,v_assignment.effective_to_week_ending,v_values,not v_agency_invoice);
    end if;
  end if;
  -- Publish the gate and the approved Client policy transition together. The
  -- feature receipt and Client writes cannot survive any refusal below.
  update public.weekly_source_group_rule_assignments set feature_enabled=v_enabled,feature_purpose=v_purpose,
    feature_changed_by_user_id=v_actor,feature_changed_at_utc=transaction_timestamp(),feature_change_reason=v_reason,feature_release_id=v_release_id,
    feature_request_id=v_request_id,feature_request_sha256=v_hash,feature_receipt_json='{}'::jsonb where id=v_assignment_id;
  if v_agency_invoice then
    v_manifest:='[]'::jsonb;
    for v_entry in select value from jsonb_array_elements(v_changes) order by value->>'client_id' loop
      v_scope_date:=(v_entry->>'scope_date')::date;
      v_shape:=private._weekly_source_settings_client_shape_v1(v_agency,v_environment,(v_entry->>'client_id')::uuid,v_scope_date);
      v_apply_values:=v_entry->'before_values'||jsonb_build_object('effective_from',v_scope_date);
      if v_enabled then v_apply_values:=v_apply_values||jsonb_build_object('authority_mode','SOURCE_AUTHORITY','document_mode','CHECK_ONLY','self_bill_enabled',false); end if;
      v_result:=public.weekly_source_client_settings_save_atomic_v1(jsonb_build_object('actor_user_id',v_actor,'agency_id',v_agency,'environment',v_environment,
        'client_id',v_entry->>'client_id','expected_settings_version',v_shape->>'settings_version','settings',v_apply_values));
      if coalesce((v_result->>'ok')::boolean,false) is not true then raise exception 'WEEKLY_SOURCE_RULE_CLIENT_TRANSITION_FAILED' using errcode='55000'; end if;
      v_shape:=private._weekly_source_settings_client_shape_v1(v_agency,v_environment,(v_entry->>'client_id')::uuid,v_scope_date);
      v_manifest:=v_manifest||jsonb_build_array(v_entry||jsonb_build_object(
        case when v_enabled then 'after_values' else 'restored_values' end,v_shape->'settings',
        case when v_enabled then 'after_settings_version' else 'restored_settings_version' end,v_shape->>'settings_version',
        case when v_enabled then 'after_policy_id' else 'restored_policy_id' end,(select cp.id from public.weekly_source_client_policies cp
          where cp.source_group_id=v_group_id and cp.client_id=(v_entry->>'client_id')::uuid
            and v_scope_date between cp.effective_from and coalesce(cp.effective_to,'infinity'::date))));
    end loop;
    v_changes:=v_manifest;
    if v_enabled then perform private._weekly_source_rule_group_context_v1(v_group_id,v_from,v_assignment.effective_to_week_ending,v_values,true); end if;
  end if;
  v_receipt:=jsonb_build_object('contract','WEEKLY_SOURCE_RULE_FEATURE_RECEIPT_V1','assignment_id',v_assignment_id,
    'assignment_version',v_assignment.version+1,'source_group_id',v_group_id,'rule_set_version_id',v_version_id,
    'effective_from_week_ending',v_from,'feature_enabled',v_enabled,'feature_purpose',v_purpose,'release_id',v_release_id,
    'actor_user_id',v_actor,'changed_at_utc',transaction_timestamp(),'reason',v_reason,'request_id',v_request_id,'client_changes',v_changes,'replayed',false)||case when v_qualification is null then '{}'::jsonb else
      jsonb_build_object('protected_capability_qualification',v_qualification) end;
  update public.weekly_source_group_rule_assignments set feature_enabled=v_enabled,feature_purpose=v_purpose,
    feature_changed_by_user_id=v_actor,feature_changed_at_utc=transaction_timestamp(),feature_change_reason=v_reason,feature_release_id=v_release_id,
    feature_request_id=v_request_id,feature_request_sha256=v_hash,feature_receipt_json=v_receipt,version=version+1 where id=v_assignment_id;
  return v_receipt;
end;
$function$;

create or replace function private.weekly_source_bulk_source_cas_assert_v1(p_cycle_id uuid,p_client_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_ready boolean; v_cas jsonb; v_clients uuid[];
begin
  if p_client_ids is null or array_position(p_client_ids,null::uuid) is not null then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='22023'; end if;
  select coalesce(array_agg(distinct item order by item),'{}'::uuid[]) into v_clients from unnest(p_client_ids) item;
  if to_regprocedure('private.weekly_source_bulk_producer_ready_v1(uuid)') is null
    or to_regprocedure('private.weekly_source_bulk_source_cas_v1(uuid,uuid[])') is null then
    raise exception 'WEEKLY_SOURCE_BULK_PRODUCER_UNAVAILABLE' using errcode='55000'; end if;
  execute 'select private.weekly_source_bulk_producer_ready_v1($1)' into v_ready using p_cycle_id;
  if v_ready is distinct from true then
    begin
      perform private.weekly_source_protected_qualification_assert_v1(null,p_cycle_id,v_clients,'BULK_SIGNED');
    exception when sqlstate '42501' or sqlstate '55000' then
      raise exception 'WEEKLY_SOURCE_BULK_PRODUCER_UNAVAILABLE' using errcode='55000';
    end;
  end if;
  execute 'select private.weekly_source_bulk_source_cas_v1($1,$2)' into v_cas using p_cycle_id,v_clients;
  if not private.weekly_exceptional_json_keys_exact_v1(v_cas,array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or not(v_cas ?& array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or v_cas->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_SOURCE_CAS_V1'
    or v_cas->>'source_cycle_id' is distinct from p_cycle_id::text
    or v_cas->'client_ids' is distinct from to_jsonb(v_clients)
    or coalesce(v_cas->>'source_cas_sha256','') !~ '^[0-9a-f]{64}$' then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='55000'; end if;
  return v_cas;
end;
$function$;

create or replace function private.weekly_source_bulk_source_cas_assert_v1(p_cycle_id uuid,p_client_ids uuid[],p_actor_user_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare clients uuid[]; result jsonb;
begin
  begin return private.weekly_source_bulk_source_cas_assert_v1(p_cycle_id,p_client_ids);
  exception when sqlstate '55000' then
    if sqlerrm<>'WEEKLY_SOURCE_BULK_PRODUCER_UNAVAILABLE' then raise; end if;
  end;
  if p_client_ids is null or array_position(p_client_ids,null::uuid) is not null then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='22023'; end if;
  select coalesce(array_agg(distinct item order by item),'{}'::uuid[]) into clients from unnest(p_client_ids) item;
  perform private.weekly_source_protected_test_scope_assert_v1(p_cycle_id,p_actor_user_id,clients,null);
  result:=private.weekly_source_bulk_source_cas_v1(p_cycle_id,clients);
  if result->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_SOURCE_CAS_V1'
    or result->>'source_cycle_id' is distinct from p_cycle_id::text or result->'client_ids' is distinct from to_jsonb(clients)
    or coalesce(result->>'source_cas_sha256','') !~ '^[0-9a-f]{64}$' then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='55000'; end if;
  return result;
end;
$function$;

create or replace function private.weekly_source_protected_non_self_bill_mode_v1(
  p_client_id uuid,p_contract_id uuid,p_work_date date,p_cycle_id uuid,p_actor_user_id uuid,p_work_event_id uuid
) returns text language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; policy jsonb; qualification jsonb; declared_client uuid;
begin
  if p_client_id is null or p_contract_id is null or p_work_date is null or p_cycle_id is null then return null; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  policy:=private._weekly_source_effective_policy_v1(p_client_id,p_contract_id,p_work_date);
  if policy->'self_bill_enabled' is distinct from 'false'::jsonb or policy->>'c1_source_mode' is not null
    or policy->>'source_group_id' is distinct from c.source_group_id::text
    or policy->>'source_family' is distinct from 'ROSTER'
    or private.weekly_source_is_import_authoritative_v1(p_client_id,p_contract_id,p_work_date) is distinct from true
    or not exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=c.source_group_id
      and member.client_id=p_client_id and c.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date)) then return null; end if;
  declared_client:=private.weekly_source_checking_client_scope_v1(c.current_projection_publication_id);
  if declared_client is not null and declared_client<>p_client_id then return null; end if;
  begin
    qualification:=private.weekly_source_protected_capability_receipt_v1(c.id);
  exception when sqlstate '55000' or no_data_found or too_many_rows then
    begin
      qualification:=private.weekly_source_protected_qualification_assert_v1(null,c.id,null,'BULK_SIGNED');
    exception when sqlstate '42501' or sqlstate '55000' then
      if p_work_event_id is null then return null; end if;
      begin qualification:=private.weekly_source_protected_test_scope_assert_v1(c.id,p_actor_user_id,null,p_work_event_id);
      exception when sqlstate '42501' or sqlstate '55000' then return null; end;
      if not exists(select 1 from jsonb_array_elements(qualification#>'{original_census,original_items}') item
        where item->>'client_id'=p_client_id::text and item->>'contract_id'=p_contract_id::text
          and item->>'work_date'=p_work_date::text and item->>'work_event_id'=p_work_event_id::text) then return null; end if;
    end;
    if not(qualification#>'{original_census,original_client_ids}' @> jsonb_build_array(p_client_id)) then return null; end if;
  end;
  if not(qualification->'capabilities' @> '["BULK_SIGNED"]'::jsonb) then return null; end if;
  return 'HEALTHROSTER_WEEKLY';
exception when no_data_found or too_many_rows or sqlstate '55000' then return null;
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function private.weekly_source_protect_all_signed_selection_v1(p_source_cycle_id uuid,p_actor_user_id uuid,p_own_stage_context jsonb,p_original_client_ids uuid[])
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_cycle public.weekly_source_cycles%rowtype; v_publication public.weekly_source_projection_publications%rowtype;
  v_row record; v_claim jsonb; v_facts jsonb; v_witness jsonb; v_selection jsonb; v_key text;
  v_eligible jsonb:='[]'::jsonb; v_skipped jsonb:='[]'::jsonb; v_reason text; v_code text; v_count integer; v_clients uuid[]:='{}'::uuid[]; v_cas jsonb; v_own_stage boolean;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict v_cycle from public.weekly_source_cycles where id=p_source_cycle_id;
  perform private.weekly_source_office_authority_v1(p_actor_user_id,'APPROVE_PROTECTED_PAY',v_cycle.source_group_id,null,v_cycle.finalisation_week_ending);
  select * into strict v_publication from public.weekly_source_projection_publications
    where id=v_cycle.current_projection_publication_id and source_cycle_id=v_cycle.id and state='CURRENT'
      and authority_scope_kind='CYCLE' and correction_session_id is null;
  perform private.weekly_source_query_current_publication_v1(v_cycle.id,v_publication.id);
  for v_row in select incident.id as incident_id,incident.episode_number,incident.candidate_id,incident.client_id,
      incident.work_event_id,comparison.id as comparison_id,comparison.contract_id,comparison.issue_family,
      comparison.material_comparison_fingerprint,work.work_date
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      and comparison.incident_id=incident.id
    join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id
      and work.client_id=incident.client_id and work.first_source_group_id=v_cycle.source_group_id
    join public.contracts contract on contract.id=comparison.contract_id and contract.candidate_id=incident.candidate_id
      and contract.client_id=incident.client_id
    where incident.source_cycle_id=v_cycle.id and incident.state='OPEN'
      and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work.work_date)
      and (private.weekly_source_checking_client_scope_v1(v_publication.id) is null
        or incident.client_id=private.weekly_source_checking_client_scope_v1(v_publication.id))
    order by incident.candidate_id,work.id,incident.id
  loop
    v_code:=null; v_reason:=null; v_claim:=null;
    if not (v_row.client_id=any(v_clients)) then v_clients:=array_append(v_clients,v_row.client_id); end if;
    if v_row.issue_family not in ('HEALTHROSTER_NOT_FINALISED','SOURCE_MISSING_OR_NOT_AUTHORISED') then
      v_code:='DECIDE_INDIVIDUALLY'; v_reason:=case v_row.issue_family when 'SOURCE_HOURS_DIFFER'
        then 'Hours differ - decide individually' else 'Review this shift individually' end;
    elsif private.weekly_source_covered_hours_incident_v1(v_row.incident_id) then
      v_code:='ALREADY_PROTECTED'; v_reason:='Already protected';
    else
      -- A bare or partial WAIT is unknown, never treated as unprotected.
      v_own_stage:=exists(select 1 from jsonb_array_elements(p_own_stage_context->'exclusions') exclusion
        where exclusion->>'work_event_id'=v_row.work_event_id::text);
      v_witness:=case when v_own_stage then null else private.weekly_source_protected_wait_witness_v1(v_row.work_event_id,v_cycle.id) end;
      if v_witness is not null then v_code:='ALREADY_PROTECTED'; v_reason:='Already protected'; end if;
      if v_code is null then
        if p_own_stage_context is null then
          v_facts:=private.weekly_source_shift_on_self_bill_v1(v_row.work_event_id,v_cycle.id);
        else
          if to_regprocedure('private.weekly_source_shift_on_self_bill_context_v1(uuid,uuid,jsonb)') is null then
            raise exception 'WEEKLY_SOURCE_BULK_PRODUCER_UNAVAILABLE' using errcode='55000'; end if;
          execute 'select private.weekly_source_shift_on_self_bill_context_v1($1,$2,$3)' into v_facts
            using v_row.work_event_id,v_cycle.id,p_own_stage_context;
        end if;
        if jsonb_typeof(v_facts) is distinct from 'object' or not (v_facts ?& array['on_accepted_report','bound_to_finalised_export','invoice_ready','s25_pay_selected'])
          or exists(select 1 from unnest(array['on_accepted_report','bound_to_finalised_export','invoice_ready','s25_pay_selected']) field
            where jsonb_typeof(v_facts->field) is distinct from 'boolean') then
          raise exception 'WEEKLY_SOURCE_SELF_BILL_FACTS_UNAVAILABLE' using errcode='55000'; end if;
        if (v_facts->>'s25_pay_selected')::boolean or (v_facts->>'on_accepted_report')::boolean then
          v_code:='ON_SELF_BILL'; v_reason:='Already on the client self-bill';
        end if;
      end if;
      if v_code is null then
        begin
          v_claim:=private.weekly_source_bulk_signed_claim_v1(v_row.comparison_id);
          if v_claim->>'eligible' is distinct from 'true' then v_code:=v_claim->>'code'; v_reason:=v_claim->>'reason'; end if;
        exception when others then
          if sqlerrm='WEEKLY_PROTECTED_EVIDENCE_UNSIGNED' then v_code:='NO_SIGNED_SUBMISSION'; v_reason:='No signed submission';
          elsif sqlerrm='WEEKLY_PROTECTED_EVIDENCE_INVALID' then v_code:='SIGNED_SUBMISSION_UNAVAILABLE'; v_reason:='Signed submission changed - protect individually';
          else raise; end if;
        end;
      end if;
    end if;
    if v_code is not null then
      v_skipped:=v_skipped||jsonb_build_array(jsonb_build_object('incident_id',v_row.incident_id,'work_event_id',v_row.work_event_id,
        'work_date',v_row.work_date,'code',v_code,'reason',v_reason));
    else
      v_eligible:=v_eligible||jsonb_build_array(jsonb_build_object('incident_id',v_row.incident_id,'issue_episode',v_row.episode_number,
        'comparison_revision_id',v_row.comparison_id,'comparison_fingerprint',encode(v_row.material_comparison_fingerprint,'hex'),
        'candidate_id',v_row.candidate_id,'client_id',v_row.client_id,'contract_id',v_row.contract_id,
        'work_event_id',v_row.work_event_id,'claim',v_claim,'self_bill_facts',v_facts));
    end if;
  end loop;
  -- Protected/skipped questions retain their Client in the Source CAS census.
  -- Completing a round must not shrink its original relevant Client authority.
  select coalesce(array_agg(item order by item),'{}'::uuid[]) into v_clients from unnest(v_clients) item;
  if p_original_client_ids is not null then
    if array_position(p_original_client_ids,null::uuid) is not null or cardinality(p_original_client_ids)>100
      or exists(select 1 from unnest(v_clients) client where not(client=any(p_original_client_ids))) then
      raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLIENT_CENSUS_CHANGED' using errcode='40001'; end if;
    select coalesce(array_agg(distinct client order by client),'{}'::uuid[]) into v_clients from unnest(p_original_client_ids) client;
  end if;
  v_cas:=private.weekly_source_bulk_source_cas_assert_v1(v_cycle.id,v_clients,p_actor_user_id);
  v_count:=jsonb_array_length(v_eligible);
  v_selection:=jsonb_build_object('contract','WEEKLY_SOURCE_BULK_SIGNED_SELECTION_V1','source_cycle_id',v_cycle.id,
    'source_cycle_version',v_cycle.version,'projection_publication_id',v_publication.id,
    'source_cas',v_cas,'eligible',v_eligible,'skipped',v_skipped);
  return v_selection||jsonb_build_object('selection_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_BULK_SIGNED_SELECTION_V1',v_selection),'hex'),'eligible_count',v_count,
    'skipped_count',jsonb_array_length(v_skipped));
end;
$function$;

create or replace function private.weekly_source_protect_all_signed_selection_v1(p_source_cycle_id uuid,p_actor_user_id uuid,p_own_stage_context jsonb default null)
returns jsonb language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
  select private.weekly_source_protect_all_signed_selection_v1(p_source_cycle_id,p_actor_user_id,p_own_stage_context,null::uuid[]);
$function$;

create or replace function private.weekly_source_bulk_own_stage_v1(
  p_request_id uuid,p_actor_id uuid,p_cycle_id uuid,p_bulk_key text,p_selection_sha256 text,p_source_cas_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare r public.weekly_exceptional_c1_publication_requests%rowtype;
  g public.weekly_exceptional_pay_generations%rowtype; a public.weekly_exceptional_payment_approvals%rowtype;
  run public.weekly_exceptional_orchestration_runs%rowtype; family public.weekly_exceptional_pay_target_families%rowtype;
  v_proof jsonb; v_claim jsonb; v_cas jsonb; v_clients uuid[]; v_event uuid; v_count integer;
begin
  select * into strict r from public.weekly_exceptional_c1_publication_requests where id=p_request_id;
  select * into strict g from public.weekly_exceptional_pay_generations where id=r.generation_id and family_id=r.family_id;
  select * into strict run from public.weekly_exceptional_orchestration_runs where id=r.orchestration_run_id and family_id=r.family_id;
  select * into strict family from public.weekly_exceptional_pay_target_families where id=r.family_id;
  select * into strict a from public.weekly_exceptional_payment_approvals
    where creation_orchestration_run_id=run.id and pay_target_family_id=family.id;
  v_proof:=g.complete_next_vector_json->'bulk_signed_selection_proof';
  v_claim:=v_proof->'eligible_claim';
  if v_proof->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_STAGED_PROOF_V1'
    or v_proof->>'actor_user_id' is distinct from p_actor_id::text
    or v_proof->>'source_cycle_id' is distinct from p_cycle_id::text
    or v_proof->>'bulk_request_key' is distinct from p_bulk_key
    or v_proof->>'selection_sha256' is distinct from p_selection_sha256
    or v_proof#>>'{source_cas,source_cas_sha256}' is distinct from p_source_cas_sha256
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_STAGED_PROOF_V1',v_proof-'proof_sha256')
      is distinct from private.weekly_exceptional_hex_sha256_v1(v_proof->>'proof_sha256')
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',g.complete_next_vector_json)
      is distinct from g.complete_next_vector_hash
    or r.state is distinct from 'READY' or g.lifecycle_state is distinct from 'PENDING_C1'
    or run.state is distinct from 'RUNNING' or run.request_kind not in ('APPROVE','AMEND')
    or run.requested_by_user_id is distinct from p_actor_id or a.approved_by_user_id is distinct from p_actor_id
    or a.source_cycle_id is distinct from p_cycle_id or a.withdrawn_at_utc is not null
    or r.candidate_id is distinct from a.candidate_id or r.contract_id is distinct from a.contract_id
    or r.root_timesheet_id is distinct from family.root_timesheet_id
    or r.request_sha256 is distinct from private.weekly_exceptional_hex_sha256_v1(v_proof->>'request_sha256')
    or r.financial_row_id::text is distinct from v_proof->>'financial_row_id'
    or a.work_event_id::text is distinct from v_claim->>'work_event_id'
    or a.comparison_revision_id::text is distinct from v_claim->>'comparison_revision_id'
    or a.signed_submission_timesheet_id::text is distinct from v_claim#>>'{claim,evidence_timesheet_id}'
    or a.signed_submission_revision::text is distinct from v_claim#>>'{claim,timesheet_revision}'
    or encode(a.signed_submission_hash,'hex') is distinct from v_claim#>>'{claim,signature_sha256}'
    or v_claim#>>'{claim,signature_kind}' is distinct from 'CANDIDATE_WORKFLOW'
    or a.approved_target_pay_components_json is distinct from g.complete_next_vector_json->'target_snapshot'
    or encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_TARGET_SNAPSHOT_V1',a.approved_target_pay_components_json),'hex')
      is distinct from v_proof->>'target_snapshot_sha256'
    or family.current_generation_id is distinct from g.prior_generation_id
    or family.current_generation_number+1 is distinct from g.generation_number
    or exists(select 1 from private.weekly_source_local_protected_decision_receipts receipt where receipt.publication_request_id=r.id)
    or exists(select 1 from public.weekly_exceptional_c1_publication_checkpoints checkpoint where checkpoint.publication_request_id=r.id)
    or exists(select 1 from public.weekly_exceptional_c1_unknown_outcomes outcome where outcome.publication_request_id=r.id and outcome.state='RECOVERY_REQUIRED') then
    raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000'; end if;
  select count(*),min(event.id::text)::uuid into v_count,v_event from public.weekly_exceptional_pay_family_events event
    where event.family_id=family.id and event.evidence_approval_id=a.id and event.durable_work_event_id=a.work_event_id and event.state='WAIT'
      and not exists(select 1 from public.weekly_exceptional_pay_family_events newer where newer.family_id=family.id
        and newer.durable_work_event_id=a.work_event_id and newer.event_sequence>event.event_sequence);
  if v_count<>1 or (a.protected_work_date,a.protected_start_at_local,a.protected_end_at_local,a.protected_break_minutes)
    is distinct from ((v_claim#>>'{claim,work_date}')::date,(v_claim#>>'{claim,start_at_local}')::timestamp,
      (v_claim#>>'{claim,end_at_local}')::timestamp,(v_claim#>>'{claim,break_minutes}')::integer) then
    raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000'; end if;
  if private.weekly_source_bulk_signed_claim_v1(a.comparison_revision_id) is distinct from v_claim->'claim' then
    raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
  select array_agg(value::uuid order by value::uuid) into v_clients from jsonb_array_elements_text(v_proof#>'{source_cas,client_ids}') value;
  v_cas:=private.weekly_source_bulk_source_cas_assert_v1(p_cycle_id,v_clients,p_actor_id);
  if v_cas is distinct from v_proof->'source_cas' then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
  return jsonb_build_object('work_event_id',a.work_event_id,'publication_request_id',r.id,'generation_id',g.id,
    'approval_id',a.id,'family_id',family.id,'proof_sha256',v_proof->>'proof_sha256');
exception when no_data_found or too_many_rows or invalid_text_representation or numeric_value_out_of_range then
  raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000';
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_exceptional_pay_prepare_family_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_allowed_keys constant text[]:=array[
    'actor_user_id','source_cycle_id','candidate_id','client_id','contract_id',
    'week_ending_date','work_event_id','work_date','start_at_local',
    'end_at_local','break_minutes','evidence_timesheet_id','reason',
    'idempotency_key'
  ];
  v_actor_user_id uuid;
  v_source_cycle_id uuid;
  v_candidate_id uuid;
  v_client_id uuid;
  v_contract_id uuid;
  v_week_ending_date date;
  v_week_start_date date;
  v_work_event_id uuid;
  v_work_date date;
  v_start_at_local timestamp without time zone;
  v_end_at_local timestamp without time zone;
  v_break_minutes integer;
  v_evidence_timesheet_id uuid;
  v_reason text;
  v_idempotency_key text;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_contract public.contracts%rowtype;
  v_contract_week public.contract_weeks%rowtype;
  v_root public.timesheets%rowtype;
  v_evidence public.timesheets%rowtype;
  v_signed_evidence jsonb;
  v_candidate public.candidates%rowtype;
  v_client public.clients%rowtype;
  v_policy jsonb;
  v_source_mode text; v_activated_source_mode text;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_occupant_norm text;
  v_hospital_norm text;
  v_ward_norm text;
  v_role_norm text;
  v_booking_material text;
  v_booking_id text;
  v_work_event_hash bytea;
  v_first_evidence_hash bytea;
  v_request_hash bytea;
  v_before_hash bytea;
  v_created_root boolean:=false;
  v_created_family boolean:=false;
  v_created_event boolean:=false;
  v_replay boolean:=false;
  v_request_kind text:='APPROVE';
  v_lock_result jsonb;
  v_family_identity jsonb;
  v_known_root_timesheet_id uuid;
  v_saved_route jsonb;
  v_lock_group uuid;
begin
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,v_allowed_keys)
     or not (p_request ?& array[
       'actor_user_id','source_cycle_id','candidate_id','client_id','contract_id',
       'week_ending_date','work_date','start_at_local','end_at_local',
       'break_minutes','reason','idempotency_key'
     ]) then
    raise exception 'WEEKLY_PROTECTED_FAMILY_REQUEST_INVALID' using errcode='22023';
  end if;

  begin
    v_actor_user_id:=(p_request->>'actor_user_id')::uuid;
    v_source_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_candidate_id:=(p_request->>'candidate_id')::uuid;
    v_client_id:=(p_request->>'client_id')::uuid;
    v_contract_id:=(p_request->>'contract_id')::uuid;
    v_week_ending_date:=(p_request->>'week_ending_date')::date;
    v_work_event_id:=nullif(p_request->>'work_event_id','')::uuid;
    v_work_date:=(p_request->>'work_date')::date;
    v_start_at_local:=(p_request->>'start_at_local')::timestamp without time zone;
    v_end_at_local:=(p_request->>'end_at_local')::timestamp without time zone;
    v_break_minutes:=(p_request->>'break_minutes')::integer;
    v_evidence_timesheet_id:=nullif(p_request->>'evidence_timesheet_id','')::uuid;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_FAMILY_REQUEST_INVALID' using errcode='22023';
  end;
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_week_start_date:=v_week_ending_date-6;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PREPARE_FAMILY_REQUEST_V1',p_request
  );

  if v_break_minutes is null or v_break_minutes<0
     or v_end_at_local<=v_start_at_local
     or v_break_minutes>=extract(epoch from (v_end_at_local-v_start_at_local))/60
     or v_work_date<>v_start_at_local::date
     or v_work_date>(pg_catalog.clock_timestamp() at time zone 'Europe/London')::date
     or v_work_date not between v_week_start_date and v_week_ending_date
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_idempotency_key) not between 16 and 200 then
    raise exception 'WEEKLY_PROTECTED_FAMILY_REQUEST_INVALID' using errcode='22023';
  end if;

  v_saved_route:=private.weekly_source_protected_saved_prepare_route_v1(p_request,
    'WEEKLY_PROTECTED_PREPARE_FAMILY_REQUEST_V1','APPROVE');
  if v_saved_route is not null then return v_saved_route; end if;
  perform private.weekly_source_pay_query_admit_v2();
  -- Review F1 and F4. After query admission, the I-1 lock set precedes the
  -- existing business locks this owner
  -- takes: no row lock, no FOR UPDATE and no other advisory key before it,
  -- because every installed rotation owner takes the family advisory key and
  -- the family rows before anything else (core 08082026_2035_...:126-131,
  -- legacy 16122025_...:844-849, confirmed route :2374-2376).  This owner
  -- previously locked the orchestration run, the cycle, the Contract and the
  -- Contract Week first and asked for the family keys afterwards, which is a
  -- proven deadlock (reproductions D1b and D2).  The root is discovered with a
  -- PLAIN read from the request's Contract and week.
  select contract_week.timesheet_id into v_known_root_timesheet_id
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_contract_id
    and contract_week.week_ending_date=v_week_ending_date
    and contract_week.additional_seq=0;

  if v_known_root_timesheet_id is not null then
    v_lock_result:=private.weekly_source_lock_family_rows_v1(
      array[v_known_root_timesheet_id]::uuid[],v_candidate_id
    );
    if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
      raise exception '%',v_lock_result->>'code'
        using errcode='55000',detail=v_lock_result::text;
    end if;
  end if;

  -- Serialize the global idempotency namespace before looking up the run.
  -- Without this lock, two first attempts can both observe no row and the
  -- loser receives a raw unique violation rather than an exact replay.  It is
  -- a Weekly-Source-private key that no rotation owner takes, and it is now
  -- requested after the family keys.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly-exceptional-orchestration|'||v_idempotency_key,0
  ));

  -- A replay is recognized before any mutable work, but every immutable scope
  -- fact is still compared below.  A reused key can never name another family.
  select run.* into v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.idempotency_key=v_idempotency_key
  for update;
  if found then
    v_replay:=true;
  end if;

  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_source_cycle_id);
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle
  where cycle.id=v_source_cycle_id
  for update;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id
    and source_group.active
  for share;

  perform private.weekly_source_office_authority_v1(
    v_actor_user_id,'APPROVE_PROTECTED_PAY',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );

  -- The source cycle records when Office discovered or is reconciling the
  -- protected item.  It is deliberately not required to be the work week:
  -- a missing or queried historic shift can remain protected for later cycles.
  if not exists(
       select 1 from public.weekly_source_group_clients membership
       where membership.source_group_id=v_group.id
         and membership.client_id=v_client_id
         and v_cycle.finalisation_week_ending between membership.valid_from
           and coalesce(membership.valid_to,'infinity'::date)
     ) then
    raise exception 'WEEKLY_PROTECTED_FAMILY_SCOPE_INVALID' using errcode='55000';
  end if;

  select contract.* into strict v_contract
  from public.contracts contract
  where contract.id=v_contract_id
  for update;
  if v_contract.candidate_id is distinct from v_candidate_id
     or v_contract.client_id is distinct from v_client_id
     or v_work_date not between v_contract.start_date and v_contract.end_date
     or v_contract.week_ending_weekday_snapshot not between 0 and 6
     or v_week_ending_date<>v_work_date+
       ((v_contract.week_ending_weekday_snapshot-
         extract(dow from v_work_date)::integer+7)%7) then
    raise exception 'WEEKLY_PROTECTED_CONTRACT_SCOPE_INVALID' using errcode='55000';
  end if;

  v_policy:=private._weekly_source_effective_policy_v1(
    v_client_id,v_contract_id,v_work_date
  );
  v_activated_source_mode:=private.weekly_source_protected_non_self_bill_mode_v1(v_client_id,v_contract_id,v_work_date,v_cycle.id,v_actor_user_id,v_work_event_id);
  v_source_mode:=coalesce(v_policy->>'c1_source_mode',v_activated_source_mode);
  if v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or (coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true and v_activated_source_mode is null)
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_PROTECTED_POLICY_INVALID' using errcode='55000';
  end if;

  select candidate.* into strict v_candidate
  from public.candidates candidate where candidate.id=v_candidate_id;
  select client.* into strict v_client
  from public.clients client where client.id=v_client_id;

  -- G6-9 / WB-016.  Note on the Candidate serial gate (proof/32 section 6
  -- step 1): preparing the protected-pay family is not one of the four pinned
  -- Weekly Source job types, so this owner does not take the gate; the
  -- first-authorisation, publication and release owners do, through interface
  -- I-1.  It does take the full rotation lock set below (proof/34 rules 1, 6
  -- and 11), and adds no lock of its own on any Banking Pay table.

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'WEEKLY_SOURCE_BASE_WEEK|'||v_contract_id::text||'|'||v_week_ending_date::text,0
  ));
  insert into public.contract_weeks(
    contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id,is_adjustment,created_at,updated_at
  ) values (
    v_contract_id,v_week_ending_date,0,'SUBMITTED'::public.contract_week_status_enum,
    'MANUAL'::public.submission_mode_enum,null,false,
    pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()
  ) on conflict (contract_id,week_ending_date,additional_seq) do nothing;
  select contract_week.* into strict v_contract_week
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_contract_id
    and contract_week.week_ending_date=v_week_ending_date
    and contract_week.additional_seq=0
  for update;
  if v_contract_week.is_adjustment
     or v_contract_week.status='CANCELLED'::public.contract_week_status_enum then
    raise exception 'WEEKLY_PROTECTED_BASE_WEEK_INVALID' using errcode='55000';
  end if;

  -- Review G1.  Under the locks the Contract Week must still name the root
  -- whose family this transaction locked FIRST - including the null to non-null
  -- case, where the week gained a root between the plain read and here.  The
  -- earlier form guarded this with "v_known_root_timesheet_id is not null", so
  -- that case fell through to "select timesheet ... for update" before the
  -- family advisory keys, which is the reverse of every installed rotation
  -- owner and a proven deadlock.  This is the ensure owner's own unconditional
  -- check, in the same place relative to the locked read.
  if v_contract_week.timesheet_id is distinct from v_known_root_timesheet_id then
    raise exception 'WEEKLY_SOURCE_BASE_WEEK_ROOT_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'expected_root_timesheet_id',v_known_root_timesheet_id,
          'observed_root_timesheet_id',v_contract_week.timesheet_id
        )::text;
  end if;

  if v_contract_week.timesheet_id is null then
    if v_contract_week.status in (
      'AUTHORISED'::public.contract_week_status_enum,
      'INVOICED'::public.contract_week_status_enum,
      'CANCELLED'::public.contract_week_status_enum
    ) then
      raise exception 'WEEKLY_PROTECTED_FINAL_WEEK_TIMESHEET_MISSING' using errcode='55000';
    end if;
    v_occupant_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_candidate.tms_ref),''),
      nullif(pg_catalog.btrim(v_candidate.display_name),''),v_candidate.id::text
    ));
    v_hospital_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.display_site),''),
      nullif(pg_catalog.btrim(v_client.name),''),v_client.id::text
    ));
    v_ward_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.ward_hint),''),'contract'
    ));
    v_role_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.role),''),'weekly'
    ));
    v_booking_material:='weekly-source|'||v_contract_id::text||'|'||v_week_ending_date::text;
    v_booking_id:='bk_'||pg_catalog.substr(pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(v_booking_material,'UTF8'),'sha256'),'hex'
    ),1,24);
    -- A minted booking id must not collide with an existing family, and must
    -- not differ from an existing one by surrounding whitespace only: the
    -- confirmed rotation route serialises on the trimmed key while family
    -- membership is by the raw value, so such a pair is an ambiguous family.
    if exists(
      select 1 from public.timesheets existing
      where (existing.booking_id=v_booking_id and existing.is_current)
         or pg_catalog.btrim(existing.booking_id)=v_booking_id
    ) then
      raise exception 'WEEKLY_SOURCE_BOOKING_ID_COLLISION' using errcode='55000';
    end if;
    insert into public.timesheets(
      booking_id,version,is_current,status,sheet_scope,submission_mode,line_type,
      occupant_key_norm,hospital_norm,ward_norm,job_title_norm,shift_label_norm,
      week_ending_date,contract_id,actual_schedule_json,qr_payload_json,
      is_adjustment,created_at,updated_at
    ) values (
      v_booking_id,1,true,'RECEIVED'::public.timesheet_status_enum,
      'WEEKLY'::public.timesheet_scope_enum,'MANUAL'::public.submission_mode_enum,
      'HOURS'::public.timesheet_line_type_enum,v_occupant_norm,v_hospital_norm,
      v_ward_norm,v_role_norm,'weekly-0',v_week_ending_date,v_contract_id,
      '[]'::jsonb,'{}'::jsonb,false,
      pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()
    ) returning * into v_root;
    v_created_root:=true;
    update public.contract_weeks
    set timesheet_id=v_root.timesheet_id,
        status='SUBMITTED'::public.contract_week_status_enum,
        updated_at=pg_catalog.statement_timestamp()
    where id=v_contract_week.id
    returning * into v_contract_week;
  else
    select timesheet.* into strict v_root
    from public.timesheets timesheet
    where timesheet.timesheet_id=v_contract_week.timesheet_id
    for update;
  end if;

  -- G6-9 / proof/34 section 5 step 2 and rule 6.  A stored contract-week
  -- Timesheet id, or a freshly minted one, is only a lookup key: take the
  -- deadlock-free rotation lock set (trimmed key, raw key when different, raw
  -- booking family rows FOR UPDATE) and re-resolve the canonical current
  -- version through the installed Workbench authority before trusting it.
  -- For an existing root the lock set was already taken, before every other
  -- lock, so this call is re-entrant and re-resolves under the locks.  For a
  -- root this transaction has just minted, no other session can know the
  -- booking id yet, so taking the family keys here cannot join a cycle.
  v_lock_result:=private.weekly_source_lock_family_rows_v1(
    array[v_root.timesheet_id]::uuid[],v_candidate_id
  );
  if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
    raise exception '%',v_lock_result->>'code'
      using errcode='55000',detail=v_lock_result::text;
  end if;
  v_family_identity:=v_lock_result->'families'->0;

  -- The root this owner ends up holding must still be the one whose family was
  -- locked first, unless this transaction minted it itself.
  if not v_created_root
     and v_root.timesheet_id is distinct from v_known_root_timesheet_id then
    raise exception 'WEEKLY_SOURCE_BASE_WEEK_ROOT_CHANGED_DURING_LOCK'
      using errcode='40001';
  end if;

  -- proof/34 section 5 step 3: a changed current id makes the request stale.
  -- The older id is never used and nothing is written.
  if coalesce((v_family_identity->>'requested_is_canonical')::boolean,false) is not true
     or coalesce((v_family_identity->>'family_is_current')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION'
      using errcode='55000',detail=v_family_identity::text;
  end if;

  -- Re-read the root under the lock before any fact derived from it is frozen.
  select timesheet.* into strict v_root
  from public.timesheets timesheet
  where timesheet.timesheet_id=v_root.timesheet_id;
  if v_root.booking_id is distinct from (v_family_identity->>'family_booking_id')
     or v_root.version is distinct from (v_family_identity->>'canonical_version')::integer then
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',detail=v_family_identity::text;
  end if;

  if v_root.contract_id is distinct from v_contract_id
     or v_root.week_ending_date is distinct from v_week_ending_date
     or v_root.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum
     or v_root.line_type<>'HOURS'::public.timesheet_line_type_enum
     or v_root.is_adjustment
     or not v_root.is_current
     or v_root.revoked_at is not null
     or v_root.archived_at_utc is not null then
    raise exception 'WEEKLY_PROTECTED_ROOT_INVALID' using errcode='55000';
  end if;

  if v_evidence_timesheet_id is not null then
    v_signed_evidence:=private.weekly_exceptional_candidate_signed_evidence_v1(
      v_evidence_timesheet_id
    );
    if (v_signed_evidence->>'contract_id')::uuid is distinct from v_contract_id
       or (v_signed_evidence->>'week_ending_date')::date is distinct from v_week_ending_date then
      raise exception 'WEEKLY_PROTECTED_EVIDENCE_INVALID' using errcode='55000';
    end if;
  end if;

  if v_work_event_id is not null then
    select event.id into strict v_work_event_id
    from public.weekly_work_events event
    where event.id=v_work_event_id
      and event.candidate_id=v_candidate_id
      and event.client_id=v_client_id
      and event.work_date=v_work_date
    for share;
  else
    v_work_event_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_OFFICE_PROTECTED_WORK_EVENT_V1',
      pg_catalog.jsonb_build_object(
        'agency_id',v_group.agency_id,'candidate_id',v_candidate_id,
        'client_id',v_client_id,'work_date',v_work_date,
        'start_at_local',v_start_at_local,'end_at_local',v_end_at_local,
        'break_minutes',v_break_minutes
      )
    );
    -- The new-shift editor cannot silently create another payable identity for
    -- work already recorded on this day. Exact replay keeps its original hash;
    -- changed hours must name the existing shift and use its protected owner.
    if not v_replay and exists(
      select 1 from public.weekly_work_events existing
      where existing.candidate_id=v_candidate_id
        and existing.work_date between v_work_date-1 and v_work_date+1
        and existing.durable_identity_hash<>v_work_event_hash
        and (
          (existing.work_date=v_work_date and existing.client_id=v_client_id
            and existing.first_source_group_id=v_group.id
            and existing.identity_kind='OFFICE_PROTECTED_SHIFT'
            and not exists(select 1 from public.weekly_exceptional_pay_family_events recorded
              where recorded.durable_work_event_id=existing.id))
          or
          private.weekly_source_work_event_schedule_compatible_v1(existing.id,v_start_at_local,v_end_at_local)
          or exists(select 1 from public.weekly_exceptional_pay_family_events protected
            where protected.durable_work_event_id=existing.id
              and protected.start_at_local<v_end_at_local and v_start_at_local<protected.end_at_local)
          or exists(select 1 from public.weekly_discrepancy_incidents incident
            join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
            where incident.work_event_id=existing.id
              and comparison.candidate_start_at_local<v_end_at_local
              and v_start_at_local<comparison.candidate_end_at_local)
        )
    ) then
      raise exception 'WEEKLY_PROTECTED_EXISTING_SHIFT_SELECTION_REQUIRED' using errcode='55000';
    end if;
    insert into public.weekly_work_events(
      candidate_id,client_id,work_date,identity_kind,profile_external_key,
      durable_identity_hash,first_source_group_id,source_format_profile_id
    ) values (
      v_candidate_id,v_client_id,v_work_date,'OFFICE_PROTECTED_SHIFT',null,
      v_work_event_hash,v_group.id,null
    ) on conflict (durable_identity_hash) do nothing
    returning id into v_work_event_id;
    if found then
      v_created_event:=true;
    else
      select event.id into strict v_work_event_id
      from public.weekly_work_events event
      where event.durable_identity_hash=v_work_event_hash
        and event.candidate_id=v_candidate_id
        and event.client_id=v_client_id
        and event.work_date=v_work_date
        and event.identity_kind='OFFICE_PROTECTED_SHIFT';
    end if;
  end if;

  v_first_evidence_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_FIRST_EVIDENCE_V1',
    pg_catalog.jsonb_build_object(
      'agency_id',v_group.agency_id,'candidate_id',v_candidate_id,
      'client_id',v_client_id,'contract_id',v_contract_id,
      'week_ending_date',v_week_ending_date,'root_timesheet_id',v_root.timesheet_id,
      'evidence_timesheet_id',v_evidence_timesheet_id,'work_event_id',v_work_event_id,
      'work_date',v_work_date,'start_at_local',v_start_at_local,
      'end_at_local',v_end_at_local,'break_minutes',v_break_minutes
    )
  );

  select family.* into v_family
  from public.weekly_exceptional_pay_target_families family
  where family.agency_id=v_group.agency_id
    and family.candidate_id=v_candidate_id
    and family.contract_id=v_contract_id
    and family.week_ending_date=v_week_ending_date
  for update;
  if found then
    if v_family.root_timesheet_id is distinct from v_root.timesheet_id
       or v_family.week_start_date is distinct from v_week_start_date
       or v_family.agency_id is distinct from v_group.agency_id
       or v_family.candidate_id is distinct from v_candidate_id
       or v_family.contract_id is distinct from v_contract_id
       or (v_replay and v_run.family_id is distinct from v_family.id) then
      raise exception 'WEEKLY_PROTECTED_FAMILY_SCOPE_INVALID' using errcode='55000';
    end if;
    -- One family is the complete Candidate + Contract + week entitlement.
    -- A later protected shift or an amended protected schedule is another
    -- immutable orchestration run against that same family, never a second
    -- public Timesheet and never a duplicate family.
    if v_replay then
      if v_run.request_kind not in ('APPROVE','AMEND') then
        raise exception 'WEEKLY_PROTECTED_REPLAY_SCOPE_INVALID' using errcode='55000';
      end if;
      v_request_kind:=v_run.request_kind;
    else
      if v_family.c1_publication_state in ('PENDING','PUBLISHING') then
        raise exception 'WEEKLY_PROTECTED_PUBLICATION_BUSY' using errcode='55000';
      end if;
      -- Preparing a family is not a published pay decision. A failed first
      -- attempt can leave this identity present with no generation to amend.
      v_request_kind:=case when v_family.current_generation_id is null
        then 'APPROVE' else 'AMEND' end;
    end if;
  else
    if v_replay then
      raise exception 'WEEKLY_PROTECTED_REPLAY_SCOPE_INVALID' using errcode='55000';
    end if;
    insert into public.weekly_exceptional_pay_target_families(
      agency_id,candidate_id,contract_id,week_start_date,week_ending_date,
      root_timesheet_id,ownership_state,first_signed_evidence_fingerprint,
      current_lifecycle_state,c1_publication_state,creation_idempotency_key
    ) values (
      v_group.agency_id,v_candidate_id,v_contract_id,v_week_start_date,
      v_week_ending_date,v_root.timesheet_id,'TARGET_MANAGED',v_first_evidence_hash,
      'PENDING_APPROVAL','NONE',v_idempotency_key
    ) returning * into v_family;
    v_created_family:=true;
    v_request_kind:='APPROVE';
  end if;

  v_before_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PREPARE_BEFORE_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'bound_version',v_family.bound_version,
      'root_timesheet_id',v_root.timesheet_id,
      'root_version',v_root.version,'contract_week_id',v_contract_week.id,
      'current_generation_id',v_family.current_generation_id,
      'current_generation_number',v_family.current_generation_number,
      'family_bound_version',v_family.bound_version,
      'work_event_id',v_work_event_id,
      'work_date',v_work_date,'start_at_local',v_start_at_local,
      'end_at_local',v_end_at_local,'break_minutes',v_break_minutes,
      'evidence_timesheet_id',v_evidence_timesheet_id,
      'request_kind',v_request_kind
    )
  );
  if not v_replay then
    insert into public.weekly_exceptional_orchestration_runs(
      family_id,request_kind,idempotency_key,requested_by_user_id,state,
      request_fingerprint,before_state_fingerprint
    ) values (
      v_family.id,v_request_kind,v_idempotency_key,v_actor_user_id,'RUNNING',
      v_request_hash,v_before_hash
    ) returning * into v_run;
  elsif v_run.request_kind<>v_request_kind
     or v_run.requested_by_user_id is distinct from v_actor_user_id
     or v_run.request_fingerprint is distinct from v_request_hash then
    raise exception 'WEEKLY_PROTECTED_REPLAY_SCOPE_INVALID' using errcode='55000';
  end if;

  select financial.* into v_fin
  from public.timesheets_financials financial
  where financial.timesheet_id=v_root.timesheet_id
    and financial.is_current
  for share;

  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,
    object_type,object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor_user_id,actor.display_name,actor.role,
    'weekly_exceptional_pay_target_families',v_family.id::text,
    case when v_created_family then 'WEEKLY_PROTECTED_FAMILY_PREPARED'
      else 'WEEKLY_PROTECTED_FAMILY_PREPARE_REPLAY' end,
    null,pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'source_cycle_id',v_source_cycle_id,
      'work_event_id',v_work_event_id,'root_timesheet_id',v_root.timesheet_id,
      'contract_week_id',v_contract_week.id,'candidate_id',v_candidate_id,
      'client_id',v_client_id,'contract_id',v_contract_id,
      'week_ending_date',v_week_ending_date,'source_mode',v_source_mode,
      'request_kind',v_request_kind,
      'created_root',v_created_root,'created_work_event',v_created_event,
      'requires_zero_financial',v_fin.id is null
    ),v_reason
  from public.tms_users actor where actor.id=v_actor_user_id;

  return pg_catalog.jsonb_build_object(
    'family_id',v_family.id,'orchestration_run_id',v_run.id,
    'source_cycle_id',v_source_cycle_id,'source_group_id',v_group.id,
    'agency_id',v_group.agency_id,'candidate_id',v_candidate_id,
    'client_id',v_client_id,'contract_id',v_contract_id,
    'contract_week_id',v_contract_week.id,'root_timesheet_id',v_root.timesheet_id,
    'work_event_id',v_work_event_id,'week_start_date',v_week_start_date,
    'week_ending_date',v_week_ending_date,'source_mode',v_source_mode,
    'root_version',v_root.version,'financial_row_id',v_fin.id,
    'requires_zero_financial',v_fin.id is null,
    'created_root',v_created_root,'created_family',v_created_family,
    'created_work_event',v_created_event,'idempotent_replay',v_replay,
    'family_bound_version',v_family.bound_version,'request_kind',v_request_kind,
    'run_state',v_run.state
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_FAMILY_SCOPE_INVALID' using errcode='55000';
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_exceptional_pay_prepare_action_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_keys constant text[]:=array[
    'schema_version','actor_user_id','family_id','source_cycle_id','work_event_id',
    'action','expected_family_bound_version','protected_schedule','reason',
    'idempotency_key'
  ];
  v_schedule_keys constant text[]:=array[
    'work_date','start_at_local','end_at_local','break_minutes'
  ];
  v_actor uuid;
  v_family_id uuid;
  v_cycle_id uuid;
  v_event_id uuid;
  v_expected_version bigint;
  v_action text;
  v_reason text;
  v_key text;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_lock_family jsonb; v_lock_group uuid;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_contract public.contracts%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_latest_event public.weekly_exceptional_pay_family_events%rowtype;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_request_hash bytea;
  v_before bytea;
  v_source_mode text; v_activated_source_mode text;
  v_policy jsonb;
  v_schedule jsonb;
  v_work_date date;
  v_start timestamp without time zone;
  v_end timestamp without time zone;
  v_break integer;
  v_replay boolean:=false;
  v_review_source jsonb;
  v_saved_route jsonb;
begin
  if pg_catalog.jsonb_typeof(p_request)<>'object'
     or not private.weekly_exceptional_json_keys_exact_v1(p_request,
       v_keys||array['expected_source_hash','expected_source_revision'])
     or not (p_request ?& v_keys)
     or p_request->>'schema_version'<>'WEEKLY_PROTECTED_ACTION_PREPARE_V1' then
    raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_family_id:=(p_request->>'family_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_event_id:=(p_request->>'work_event_id')::uuid;
    v_expected_version:=(p_request->>'expected_family_bound_version')::bigint;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
  end;
  v_action:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'action','')));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PREPARE_ACTION_REQUEST_V1',p_request
  );
  if v_action not in ('AMEND','WITHDRAW','WAIT','RECONCILE','RECORD_NOT_WORKED')
     or v_expected_version<1
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_key) not between 16 and 200 then
    raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
  end if;

  v_saved_route:=private.weekly_source_protected_saved_prepare_route_v1(p_request,
    'WEEKLY_PROTECTED_PREPARE_ACTION_REQUEST_V1',v_action);
  if v_saved_route is not null then return v_saved_route; end if;
  perform private.weekly_source_pay_query_admit_v2();
  v_lock_family:=private.weekly_source_protected_family_lock_v1(v_family_id);
  -- Share the same global idempotency lock as first approval.  Concurrent
  -- first attempts for one key therefore become one write plus one exact
  -- replay instead of leaking the ledger's unique constraint.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly-exceptional-orchestration|'||v_key,0
  ));

  select run.* into v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.idempotency_key=v_key for update;
  v_replay:=found;

  select family.* into strict v_family
  from public.weekly_exceptional_pay_target_families family
  where family.id=v_family_id for update;
  if (v_family.root_timesheet_id::text,v_family.candidate_id::text,v_family.contract_id::text,v_family.week_ending_date::text)
    is distinct from (v_lock_family->>'root_timesheet_id',v_lock_family->>'candidate_id',
      v_lock_family->>'contract_id',v_lock_family->>'week_ending_date') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_cycle_id);
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle where cycle.id=v_cycle_id for share;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id and source_group.active for share;
  select contract.* into strict v_contract
  from public.contracts contract where contract.id=v_family.contract_id for share;
  select work_event.* into strict v_event
  from public.weekly_work_events work_event
  where work_event.id=v_event_id
    and work_event.candidate_id=v_family.candidate_id
    and work_event.client_id=v_contract.client_id
    and work_event.work_date between v_family.week_start_date and v_family.week_ending_date
  for share;
  select family_event.* into strict v_latest_event
  from public.weekly_exceptional_pay_family_events family_event
  where family_event.family_id=v_family.id
    and family_event.durable_work_event_id=v_event.id
  order by family_event.event_sequence desc
  limit 1
  for share;

  if v_action='AMEND' then
    if pg_catalog.jsonb_typeof(p_request->'protected_schedule')<>'object'
       or not private.weekly_exceptional_json_keys_exact_v1(
         p_request->'protected_schedule',v_schedule_keys
       )
       or not ((p_request->'protected_schedule') ?& v_schedule_keys) then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_INVALID' using errcode='22023';
    end if;
    v_schedule:=p_request->'protected_schedule';
    begin
      v_work_date:=(v_schedule->>'work_date')::date;
      v_start:=(v_schedule->>'start_at_local')::timestamp without time zone;
      v_end:=(v_schedule->>'end_at_local')::timestamp without time zone;
      v_break:=(v_schedule->>'break_minutes')::integer;
    exception when others then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_INVALID' using errcode='22023';
    end;
    if v_work_date<>v_event.work_date or v_start::date<>v_work_date
       or v_end<=v_start or v_break<0
       or v_break>=extract(epoch from (v_end-v_start))/60 then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_INVALID' using errcode='22023';
    end if;
  else
    if p_request->'protected_schedule'<>'null'::jsonb then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_FORBIDDEN' using errcode='22023';
    end if;
    v_schedule:=pg_catalog.jsonb_build_object(
      'work_date',v_latest_event.work_date,
      'start_at_local',v_latest_event.start_at_local,
      'end_at_local',v_latest_event.end_at_local,
      'break_minutes',v_latest_event.break_minutes
    );
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'APPROVE_PROTECTED_PAY',v_group.id,v_contract.client_id,v_cycle.finalisation_week_ending
  );
  v_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_event.work_date
  );
  v_activated_source_mode:=private.weekly_source_protected_non_self_bill_mode_v1(v_contract.client_id,v_contract.id,v_event.work_date,v_cycle.id,v_actor,v_event.id);
  v_source_mode:=coalesce(v_policy->>'c1_source_mode',v_activated_source_mode);
  if v_family.agency_id is distinct from v_group.agency_id
     or v_family.root_timesheet_id is null
     or v_family.ownership_state<>'TARGET_MANAGED'
     or v_contract.candidate_id is distinct from v_family.candidate_id
     or not exists(
       select 1 from public.weekly_source_group_clients membership
       where membership.source_group_id=v_group.id
         and membership.client_id=v_contract.client_id
         and v_cycle.finalisation_week_ending between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)
     )
     or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or (coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true and v_activated_source_mode is null)
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY')
     or v_latest_event.id is null then
    raise exception 'WEEKLY_PROTECTED_ACTION_SCOPE_INVALID' using errcode='55000';
  end if;

  if v_replay then
    if v_run.family_id is distinct from v_family.id
       or v_run.request_kind is distinct from v_action
       or v_run.requested_by_user_id is distinct from v_actor
       or v_run.request_fingerprint is distinct from v_request_hash then
      raise exception 'WEEKLY_PROTECTED_ACTION_IDEMPOTENCY_COLLISION' using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'outcome','PREPARED','family_id',v_family.id,
      'orchestration_run_id',v_run.id,'source_cycle_id',v_cycle.id,
      'source_group_id',v_group.id,'agency_id',v_group.agency_id,
      'candidate_id',v_family.candidate_id,'client_id',v_contract.client_id,
      'contract_id',v_family.contract_id,'root_timesheet_id',v_family.root_timesheet_id,
      'work_event_id',v_event.id,'week_start_date',v_family.week_start_date,
      'week_ending_date',v_family.week_ending_date,'source_mode',v_source_mode,
      'family_bound_version',v_expected_version,'request_kind',v_action,
      'protected_schedule',v_schedule,'run_state',v_run.state,
      'idempotent_replay',true
    );
  end if;

  if v_family.current_generation_id is null
     or v_family.current_lifecycle_state not in (
       'PROTECTED','WAITING_SOURCE','READY_TO_RECONCILE','RECONCILED','NOT_WORKED','ACTION_REQUIRED'
     )
     or v_family.c1_publication_state in ('PENDING','PUBLISHING')
     or v_family.bound_version<>v_expected_version then
    -- A business-version refusal is not a retryable PostgreSQL serialization
    -- failure. PostgREST 14 retries 40001, so return the same refusal as HTTP
    -- conflict without repeating the request or creating an orchestration run.
    raise exception 'WEEKLY_PROTECTED_ACTION_STALE' using errcode='PT409';
  end if;

  -- A new Office review is bound to the exact final-source observation shown.
  -- Refuse before creating a run; old callers and exact saved replays retain
  -- their original request shape and fingerprint.
  if p_request ? 'expected_source_hash' or p_request ? 'expected_source_revision' then
    if v_action<>'RECONCILE'
      or coalesce(p_request->>'expected_source_hash','') !~ '^[0-9a-f]{64}$'
      or coalesce(p_request->>'expected_source_revision','') !~ '^[0-9a-f-]{36}$' then
      raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
    end if;
    v_review_source:=private.weekly_source_protected_final_source_context_v1(v_family.id,v_cycle.id,v_event.id);
    if not coalesce((v_review_source->>'source_observed')::boolean,false)
      or v_review_source#>>'{source_proposal,source_hash}' is distinct from p_request->>'expected_source_hash'
      or v_review_source#>>'{source_proposal,source_revision}' is distinct from p_request->>'expected_source_revision' then
      raise exception 'WEEKLY_PROTECTED_REVIEW_SOURCE_CHANGED' using errcode='40001';
    end if;
  end if;

  v_before:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_ACTION_PREPARE_BEFORE_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'family_bound_version',v_family.bound_version,
      'current_generation_id',v_family.current_generation_id,
      'current_generation_number',v_family.current_generation_number,
      'current_target_vector_hash',pg_catalog.encode(v_family.current_complete_target_vector_hash,'hex'),
      'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
      'work_event_id',v_event.id,'action',v_action,'actor_user_id',v_actor,
      'protected_schedule',v_schedule,'reason',v_reason
    )
  );
  insert into public.weekly_exceptional_orchestration_runs(
    family_id,request_kind,idempotency_key,requested_by_user_id,state,
    request_fingerprint,before_state_fingerprint
  ) values (
    v_family.id,v_action,v_key,v_actor,'RUNNING',v_request_hash,v_before
  ) returning * into v_run;
  return pg_catalog.jsonb_build_object(
    'ok',true,'outcome','PREPARED','family_id',v_family.id,
    'orchestration_run_id',v_run.id,'source_cycle_id',v_cycle.id,
    'source_group_id',v_group.id,'agency_id',v_group.agency_id,
    'candidate_id',v_family.candidate_id,'client_id',v_contract.client_id,
    'contract_id',v_family.contract_id,'root_timesheet_id',v_family.root_timesheet_id,
    'work_event_id',v_event.id,'week_start_date',v_family.week_start_date,
    'week_ending_date',v_family.week_ending_date,'source_mode',v_source_mode,
    'family_bound_version',v_family.bound_version,'request_kind',v_action,
    'protected_schedule',v_schedule,'run_state',v_run.state,
    'idempotent_replay',v_replay
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_ACTION_SCOPE_INVALID' using errcode='55000';
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_exceptional_pay_action_context_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_keys constant text[]:=array[
    'schema_version','actor_user_id','family_id','orchestration_run_id',
    'source_cycle_id','work_event_id','protected_schedule','evidence_timesheet_id'
  ];
  v_schedule_keys constant text[]:=array[
    'work_date','start_at_local','end_at_local','break_minutes'
  ];
  v_actor uuid;
  v_family_id uuid;
  v_run_id uuid;
  v_cycle_id uuid;
  v_event_id uuid;
  v_evidence_id uuid;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_lock_family jsonb; v_lock_group uuid;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_contract public.contracts%rowtype;
  v_contract_week public.contract_weeks%rowtype;
  v_root public.timesheets%rowtype;
  -- WP-30 (WP-27 sweep finding N4), standing rule 3.  The expense-authority
  -- selection below decides which SOURCE_EXPENSE authorities belong to this
  -- protected root through the source-row lineage binding, which is a fact
  -- about the Timesheet FAMILY.  Keyed on the physical root id a rotated
  -- family's authorities were SILENTLY DROPPED from the projection rather than
  -- refused — fail open by omission.  EXECUTED on a rotated family: 0
  -- authorities selected by the physical id against 4 by the family.
  v_root_family uuid[];
  v_fin public.timesheets_financials%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_schedule jsonb;
  v_work_date date;
  v_start timestamp without time zone;
  v_end timestamp without time zone;
  v_break integer;
  v_policy jsonb;
  v_root_policy jsonb;
  v_settings jsonb;
  v_source_mode text; v_activated_source_mode text;
  v_source_segments jsonb:='[]'::jsonb;
  v_client_sources jsonb:='[]'::jsonb;
  v_decisions jsonb:='[]'::jsonb;
  v_source_expenses jsonb:='[]'::jsonb;
  v_current_final uuid;
  v_comparison uuid;
  v_signed jsonb;
  v_candidate_submission jsonb;
  v_selected_source_present boolean:=false;
  v_selected_source_minutes integer:=0;
  v_selected_source_revision text;
  v_selected_source_hash text;
  v_source_head_revision uuid;
  v_source_head_count integer:=0;
  v_ambiguous_event_count integer:=0;
  v_fin_hash text;
  v_provider_hash text;
  v_rate_refs jsonb;
  v_component_identity_inventory jsonb;
  v_component_identity_components jsonb;
  v_final_source jsonb;
  v_next_context boolean:=false;
begin
  if pg_catalog.jsonb_typeof(p_request)<>'object'
     or not private.weekly_exceptional_json_keys_exact_v1(p_request,v_keys)
     or not (p_request ?& v_keys)
     or p_request->>'schema_version'<>'WEEKLY_PROTECTED_ACTION_CONTEXT_V1'
     or pg_catalog.jsonb_typeof(p_request->'protected_schedule')<>'object'
     or not private.weekly_exceptional_json_keys_exact_v1(
       p_request->'protected_schedule',v_schedule_keys
     )
     or not ((p_request->'protected_schedule') ?& v_schedule_keys) then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_family_id:=(p_request->>'family_id')::uuid;
    v_run_id:=(p_request->>'orchestration_run_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_event_id:=(p_request->>'work_event_id')::uuid;
    v_evidence_id:=nullif(p_request->>'evidence_timesheet_id','')::uuid;
    v_schedule:=p_request->'protected_schedule';
    v_work_date:=(v_schedule->>'work_date')::date;
    v_start:=(v_schedule->>'start_at_local')::timestamp without time zone;
    v_end:=(v_schedule->>'end_at_local')::timestamp without time zone;
    v_break:=(v_schedule->>'break_minutes')::integer;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_INVALID' using errcode='22023';
  end;
  if v_end<=v_start or v_start::date<>v_work_date or v_break<0
     or v_break>=extract(epoch from (v_end-v_start))/60 then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_INVALID' using errcode='22023';
  end if;

  -- Fresh context has no immutable decision receipt exemption. Admission
  -- precedes its first family/business lock and is reentrant for an owner.
  perform private.weekly_source_pay_query_admit_v2();

  v_lock_family:=private.weekly_source_protected_family_lock_v1(v_family_id);
  select family.* into strict v_family
  from public.weekly_exceptional_pay_target_families family
  where family.id=v_family_id for share;
  select run.* into strict v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.id=v_run_id and run.family_id=v_family.id for share;
  if (v_family.root_timesheet_id::text,v_family.candidate_id::text,v_family.contract_id::text,v_family.week_ending_date::text)
    is distinct from (v_lock_family->>'root_timesheet_id',v_lock_family->>'candidate_id',
      v_lock_family->>'contract_id',v_lock_family->>'week_ending_date') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_cycle_id);
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle where cycle.id=v_cycle_id for share;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id and source_group.active for share;
  select contract.* into strict v_contract
  from public.contracts contract where contract.id=v_family.contract_id for share;
  select contract_week.* into strict v_contract_week
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_family.contract_id
    and contract_week.week_ending_date=v_family.week_ending_date
    and contract_week.additional_seq=0 for share;
  -- WP-30, standing rule 3.  The family is resolved and its rows are locked
  -- BEFORE the family-scoped state below is read, in the SAME mode and the same
  -- timesheet_id order the installed code here already uses (`for share`), and
  -- before the root's own `for share` so no new lock ordering is introduced.
  v_next_context:=(select active_owner from private.bpay_next_module_control where id=1)='NEXT'
    and private.bpay_next_protected_owner_route_v1(v_family.id)='NEXT';
  if v_next_context then
    v_root_family:=array[v_family.root_timesheet_id];
  else
    v_root_family:=private.weekly_source_invoice_family_timesheet_ids_v1(v_family.root_timesheet_id);
  end if;
  -- Standing rule 3's fail-closed branch: an explicit cardinality test, never a
  -- `limit`.  This owner already refuses on every other unprovable scope fact.
  if v_root_family is null or pg_catalog.cardinality(v_root_family)=0 then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_FAMILY_UNRESOLVED'
      using errcode='55000';
  end if;
  perform 1 from public.timesheets lock_row
  where lock_row.timesheet_id=any(v_root_family)
  order by lock_row.timesheet_id for share;
  select timesheet.* into strict v_root
  from public.timesheets timesheet
  where timesheet.timesheet_id=v_family.root_timesheet_id for share;
  select financial.* into v_fin
  from public.timesheets_financials financial
  where financial.timesheet_id=v_root.timesheet_id and financial.is_current
  order by financial.computed_at_utc desc nulls last,
           financial.updated_at desc nulls last,financial.id desc limit 1;
  select work_event.* into strict v_event
  from public.weekly_work_events work_event
  where work_event.id=v_event_id
    and work_event.candidate_id=v_family.candidate_id
    and work_event.client_id=v_contract.client_id for share;

  perform private.weekly_source_office_authority_v1(
    v_actor,'APPROVE_PROTECTED_PAY',v_group.id,v_contract.client_id,v_event.work_date
  );
  v_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_event.work_date
  );
  -- The selected shift uses its work-date policy, but the zero-value root
  -- financial is a weekly Timesheet. Its rate-source fingerprint must match
  -- the root prepare owner's week-ending policy exactly.
  v_root_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_family.week_ending_date
  );
  v_settings:=(private._timesheet_settings_authority_frozen_v1(v_root.timesheet_id)->'values')
    -'resolved_at_utc';
  v_activated_source_mode:=private.weekly_source_protected_non_self_bill_mode_v1(v_contract.client_id,v_contract.id,v_event.work_date,v_cycle.id,v_actor,v_event.id);
  v_source_mode:=coalesce(v_policy->>'c1_source_mode',v_activated_source_mode);
  if v_run.requested_by_user_id is distinct from v_actor
     or v_run.state not in ('RUNNING','COMPLETE')
     or v_run.request_kind not in ('APPROVE','AMEND','WITHDRAW','WAIT','RECONCILE','RECORD_NOT_WORKED')
     or v_family.agency_id is distinct from v_group.agency_id
     or v_contract.candidate_id is distinct from v_family.candidate_id
     or v_contract_week.timesheet_id is distinct from v_root.timesheet_id
     or v_root.contract_id is distinct from v_contract.id
     or (v_next_context and v_root.booking_id is distinct from v_family.root_family_booking_id)
     or v_root.week_ending_date is distinct from v_family.week_ending_date
     or not v_root.is_current or v_root.is_adjustment
     or v_root.revoked_at is not null or v_root.archived_at_utc is not null
     or v_event.work_date<>v_work_date
     or v_work_date not between v_family.week_start_date and v_family.week_ending_date
     or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or (coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true and v_activated_source_mode is null)
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_SCOPE_INVALID' using errcode='55000';
  end if;

  -- Read the same final-source authority shown in the Office review.
  v_final_source:=private.weekly_source_protected_final_source_context_v1(v_family.id,v_cycle.id,v_event.id);
  v_source_segments:=v_final_source->'source_segments';
  v_client_sources:=v_final_source->'client_sources';
  v_current_final:=(v_final_source->>'current_final_revision_id')::uuid;
  v_selected_source_present:=(v_final_source#>>'{source_proposal,source_present}')::boolean;
  v_selected_source_minutes:=(v_final_source#>>'{source_proposal,source_minutes}')::integer;
  v_selected_source_revision:=v_final_source#>>'{source_proposal,source_revision}';
  v_selected_source_hash:=v_final_source#>>'{source_proposal,source_hash}';

  with latest as (
    select family_event.*,
      pg_catalog.row_number() over (
        partition by family_event.durable_work_event_id
        order by family_event.event_sequence desc
      ) as event_rank
    from public.weekly_exceptional_pay_family_events family_event
    where family_event.family_id=v_family.id
  ), decisions as (
    select latest.durable_work_event_id as work_event_id,
      case when latest.durable_work_event_id=v_event.id then case
        when v_run.request_kind in ('APPROVE','AMEND','WAIT') then 'WAIT'
        when v_run.request_kind in ('WITHDRAW','RECONCILE') then 'ACCEPTED_SOURCE'
        else 'NOT_WORKED' end
      else latest.state end as decision_state,
      case when latest.durable_work_event_id=v_event.id
             and v_run.request_kind in ('APPROVE','AMEND','WAIT')
        then v_schedule
        else pg_catalog.jsonb_build_object(
          'work_date',latest.work_date,'start_at_local',latest.start_at_local,
          'end_at_local',latest.end_at_local,'break_minutes',latest.break_minutes
        ) end as fixed_schedule
    from latest where latest.event_rank=1
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'work_event_id',decision.work_event_id,'state',decision.decision_state,
    'fixed_schedule',case when decision.decision_state='WAIT' then pg_catalog.jsonb_build_object(
      'date',decision.fixed_schedule->>'work_date',
      'start',pg_catalog.to_char((decision.fixed_schedule->>'start_at_local')::timestamp,'HH24:MI'),
      'end',pg_catalog.to_char((decision.fixed_schedule->>'end_at_local')::timestamp,'HH24:MI'),
      'break_mins',(decision.fixed_schedule->>'break_minutes')::integer
    ) else null end
  ) order by decision.work_event_id),'[]'::jsonb)
  into v_decisions from decisions decision;
  if not exists(
    select 1 from pg_catalog.jsonb_array_elements(v_decisions) d(value)
    where (d.value->>'work_event_id')::uuid=v_event.id
  ) then
    v_decisions:=v_decisions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'work_event_id',v_event.id,
      'state',case when v_run.request_kind in ('APPROVE','AMEND','WAIT') then 'WAIT'
        when v_run.request_kind in ('WITHDRAW','RECONCILE') then 'ACCEPTED_SOURCE'
        else 'NOT_WORKED' end,
      'fixed_schedule',case when v_run.request_kind in ('APPROVE','AMEND','WAIT')
        then pg_catalog.jsonb_build_object(
          'date',v_work_date,'start',pg_catalog.to_char(v_start,'HH24:MI'),
          'end',pg_catalog.to_char(v_end,'HH24:MI'),'break_mins',v_break
        ) else null end
    ));
  end if;

  if v_run.request_kind='RECORD_NOT_WORKED' and v_selected_source_present then
    raise exception 'WEEKLY_PROTECTED_NOT_WORKED_SOURCE_PRESENT' using errcode='55000';
  end if;

  select comparison.id into v_comparison
  from public.weekly_issue_comparison_revisions comparison
  join public.weekly_discrepancy_incidents incident on incident.id=comparison.incident_id
  where incident.work_event_id=v_event.id and incident.candidate_id=v_family.candidate_id
    and incident.client_id=v_contract.client_id
  order by comparison.created_at_utc desc,comparison.id desc limit 1;

  if v_evidence_id is null then
    select approval.evidence_timesheet_id into v_evidence_id
    from public.weekly_exceptional_payment_approvals approval
    where approval.pay_target_family_id=v_family.id
      and approval.work_event_id=v_event.id
    order by approval.approved_at_utc desc,approval.id desc limit 1;
  end if;
  if v_evidence_id is not null then
    v_signed:=private.weekly_exceptional_candidate_signed_evidence_v1(v_evidence_id);
    v_candidate_submission:=pg_catalog.jsonb_build_object(
      'source_system','CLOUDTMS_CANDIDATE_TIMESHEET',
      'external_identity',v_evidence_id::text,
      'external_revision',v_signed->>'timesheet_version',
      'document_sha256',v_signed->>'signature_sha256',
      'work_date',v_event.work_date,'submitted_by_candidate_id',v_family.candidate_id,
      'submission_id',v_evidence_id,'submitted_at_utc',v_signed->>'signed_at_utc',
      'submitted_minutes',extract(epoch from (v_end-v_start))::integer/60-v_break
    );
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'expense_code','SOURCE_SUPPLIED:'||authority.work_event_id::text,
    'authority_kind','SOURCE_EXPENSE','source_expense_id',authority.id,
    'document_sha256',pg_catalog.encode(authority.authority_hash,'hex'),
    'pay_ex_vat',authority.candidate_reimbursement_ex_vat::text,
    'charge_ex_vat',authority.client_charge_ex_vat::text
  )||case when v_final_source ? 'next_source_segments'
    then pg_catalog.jsonb_build_object('work_event_id',authority.work_event_id,
      'final_revision_id',authority.final_revision_id,
      'source_observation_kind',authority.source_observation_kind) else '{}'::jsonb end
   order by authority.work_event_id),'[]'::jsonb)
  into v_source_expenses
  from (
    select authority.*,
      pg_catalog.row_number() over (
        partition by authority.work_event_id order by source_cycle.finalisation_week_ending desc,
          revision.finalised_at_utc desc,authority.generation desc,authority.id desc
      ) as event_rank
    from public.weekly_expense_authority_generations authority
    join public.weekly_source_final_revisions revision
      on revision.id=authority.final_revision_id and revision.state='CURRENT'
    join public.weekly_source_cycles source_cycle on source_cycle.id=revision.source_cycle_id
    where authority.contract_id=v_family.contract_id and authority.state='CURRENT'
      and source_cycle.source_group_id=v_group.id
      and ((not v_next_context and authority.source_expense_pence>0 and exists(
          select 1 from public.weekly_source_row_timesheet_lineages lineage
          where lineage.work_event_id=authority.work_event_id and lineage.contract_id=authority.contract_id
            and lineage.timesheet_id=any(v_root_family)))
        or (v_next_context and exists(
          select 1 from public.weekly_work_events event where event.id=authority.work_event_id
            and event.candidate_id=v_family.candidate_id and event.client_id=v_contract.client_id
            and event.work_date between v_family.week_start_date and v_family.week_ending_date
        ) and ((authority.source_observation_kind='OMITTED_IN_COMPLETE_COVERAGE' and authority.source_expense_pence=0)
          or exists(
            select 1 from public.weekly_source_row_expense_policy_snapshots expense_snapshot
            join public.weekly_source_row_timesheet_lineages lineage on lineage.row_resolution_id=expense_snapshot.row_resolution_id
            where expense_snapshot.id=authority.row_expense_policy_snapshot_id
              and lineage.family_booking_id=v_family.root_family_booking_id
              and lineage.work_event_id=authority.work_event_id and lineage.candidate_id=v_family.candidate_id
              and lineage.client_id=v_contract.client_id and lineage.contract_id=v_family.contract_id
              and lineage.week_ending_date=v_family.week_ending_date))))
  ) authority where authority.event_rank=1 and authority.source_expense_pence>0;

  v_fin_hash:=case when v_fin.id is null then null else pg_catalog.encode(
    private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_PROTECTED_ROOT_FINANCIAL_V1',pg_catalog.to_jsonb(v_fin)
    ),'hex') end;
  v_provider_hash:=pg_catalog.encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PROVIDER_V1',
    pg_catalog.jsonb_build_object(
      'contract_id',v_contract.id,'pay_method',v_contract.pay_method_snapshot,
      'umbrella_id',pg_catalog.to_jsonb(v_contract)->>'umbrella_id',
      'candidate_id',v_contract.candidate_id
    )
  ),'hex');
  v_rate_refs:=pg_catalog.jsonb_build_object(
    'schema_version','WEEKLY_SOURCE_TARGET_MANAGED_ZERO_RATE_SOURCE_V1',
    'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
    'source_family',v_group.source_family,'source_mode',v_source_mode,
    'source_profile_domain',case when v_source_mode='NHSP_WEEKLY'
      then 'NHSP_TRUST_BACKING_REPORT' else 'ROSTER_FINAL_AUTHORITY' end,
    'target_family_id',v_family.id,'root_timesheet_id',v_root.timesheet_id,
    'effective_policy_sha256',v_root_policy->>'policy_sha256'
  );

  -- Local/common identity admission is independent of Banking work completion.
  -- An already authorised root requires its genuine complete current I1 basis;
  -- an actual unauthorised first Save must not invent that approved basis.
  if v_family.target_domain_version='C1_V1' then
    if v_root.authorised_at_server is not null then
      v_component_identity_inventory:=private.weekly_source_effective_inventory_v1(v_root.timesheet_id);
      if v_component_identity_inventory->>'ok' is distinct from 'true'
         or v_component_identity_inventory#>>'{approval_basis,coverage_complete}' is distinct from 'true'
         or v_component_identity_inventory#>>'{approval_basis,scope,root_timesheet_id}'
              is distinct from v_root.timesheet_id::text
         or jsonb_typeof(v_component_identity_inventory->'components') is distinct from 'array' then
        raise exception 'WEEKLY_PROTECTED_COMPONENT_APPROVED_BASIS_UNAVAILABLE' using errcode='55000'; end if;
      v_component_identity_components:=v_component_identity_inventory->'components';
    else
      if exists(select 1 from public.weekly_source_root_authorisations a
          where a.family_booking_id=v_root.booking_id)
         or exists(select 1 from public.weekly_source_entitlement_heads h
          where h.root_family_booking_id=v_root.booking_id and h.state='COMMITTED_CURRENT') then
        raise exception 'WEEKLY_PROTECTED_COMPONENT_APPROVED_BASIS_UNAVAILABLE' using errcode='55000'; end if;
      v_component_identity_components:='[]'::jsonb;
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'contract','WEEKLY_PROTECTED_ACTION_CONTEXT_V1',
    'action',v_run.request_kind,'family_id',v_family.id,
    'orchestration_run_id',v_run.id,'family_bound_version',v_family.bound_version,
    'current_target_vector_sha256',case
      when v_family.current_complete_target_vector_hash is null then null
      else pg_catalog.encode(v_family.current_complete_target_vector_hash,'hex') end,
    'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
    'agency_id',v_group.agency_id,'candidate_id',v_family.candidate_id,
    'client_id',v_contract.client_id,'contract_id',v_contract.id,
    'contract_week_id',v_contract_week.id,'root_timesheet_id',v_root.timesheet_id,
    'work_event_id',v_event.id,'week_ending_date',v_family.week_ending_date,
    'source_mode',v_source_mode,'policy',v_settings,
    'timesheet',pg_catalog.to_jsonb(v_root),'contract_week',pg_catalog.to_jsonb(v_contract_week),
    'contract_record',pg_catalog.to_jsonb(v_contract),
    'current_financial',case when v_fin.id is null then null else pg_catalog.to_jsonb(v_fin) end,
    'approved_component_identity_components',v_component_identity_components,
    'requires_zero_financial',v_fin.id is null,
    'protected_schedule',v_schedule,'source_segments',v_source_segments,
    'protected_decisions',v_decisions,'source_proposal',pg_catalog.jsonb_build_object(
      'selected_work_event_id',v_event.id,'source_present',v_selected_source_present,
      'source_minutes',v_selected_source_minutes,'source_revision',v_selected_source_revision,
      'source_hash',v_selected_source_hash,'source_segments',v_source_segments
    ),
    'client_sources',v_client_sources,'source_expenses',v_source_expenses,
    'candidate_submission',v_candidate_submission,
    'current_comparison_revision_id',v_comparison,
    'current_final_revision_id',v_current_final,
    'root_financial',case when v_fin.id is null then null else pg_catalog.jsonb_build_object(
      'source_system','CLOUDTMS_TIMESHEET_FINANCIAL','external_identity',v_fin.id::text,
      'external_revision',v_fin.timesheet_version::text,'document_sha256',v_fin_hash,
      'financial_row_id',v_fin.id,'root_version',v_root.version,
      'financial_timesheet_version',v_fin.timesheet_version,
      'financial_revision_digest',v_fin_hash
    ) end,
    'provider',pg_catalog.jsonb_build_object(
      'source_system','CLOUDTMS_CONTRACT_PROVIDER','external_identity',v_contract.id::text,
      'external_revision',v_root.version::text,'document_sha256',v_provider_hash,
      'source_pay_method',v_contract.pay_method_snapshot,
      'umbrella_id',nullif(pg_catalog.to_jsonb(v_contract)->>'umbrella_id','')::uuid,
      'provider_authority_sha256',v_provider_hash,
      'target_pay_method',v_contract.pay_method_snapshot,
      'target_umbrella_id',nullif(pg_catalog.to_jsonb(v_contract)->>'umbrella_id','')::uuid,
      'target_enabled',true,'target_vat_chargeable',null
    ),
    'expected_head_revision',coalesce((
      select generation.generation_number::bigint
      from private.weekly_source_local_protected_decision_receipts receipt
      join public.weekly_exceptional_pay_generations generation on generation.id=receipt.generation_id
      where receipt.family_id=v_family.id and receipt.state='COMPLETE'
        and generation.id=v_family.current_generation_id
    ),(
      select request.c1_head_revision
      from public.weekly_exceptional_c1_publication_requests request
      where request.family_id=v_family.id and request.state='PUBLISHED'
      order by request.request_sequence desc limit 1
    ),0)::text,
    'request_sequence',(v_family.current_generation_number+1)::text,
    'zero_rate_source_refs',v_rate_refs
  )||case when v_final_source ? 'next_source_segments'
    then pg_catalog.jsonb_build_object('next_source_segments',v_final_source->'next_source_segments',
      'family_bound_version',v_family.bound_version::text) else '{}'::jsonb end;
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_SCOPE_INVALID' using errcode='55000';
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_exceptional_pay_stage_c1_request_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_top_keys constant text[]:=array[
    'schema_version','actor_user_id','family_id','orchestration_run_id',
    'source_cycle_id','client_id','work_event_id','evidence_timesheet_id',
    'expected_family_bound_version','protected_schedule','rate_classification',
    'source_proposal','target_snapshot','current_comparison_revision_id',
    'current_final_revision_id','c1_request','c1_sources','c1_components',
    'reason','idempotency_key'
  ];
  v_c1_keys constant text[]:=array[
    'request_id','request_sequence','actor_user_id','candidate_id','contract_id',
    'root_timesheet_id','week_ending_date','source_mode',
    'expected_head_revision','expected_source_count','expected_component_count',
    'expected_payload_bytes','source_manifest_sha256','entitlement_sha256',
    'approval_sha256','is_zero_entitlement','financial_row_id','request_sha256'
  ];
  v_source_keys constant text[]:=array[
    'source_ordinal','source_id','authority_kind','source_system',
    'external_identity','external_revision','source_document_sha256',
    'payload_bytes','part_count','work_date','root_timesheet_id','candidate_id',
    'contract_id','source_row_sha256','record_type','parts'
  ];
  v_part_keys constant text[]:=array[
    'source_ordinal','part_ordinal','payload_utf8','fragment_sha256','record_type'
  ];
  v_component_keys constant text[]:=array[
    'component_ordinal','component_id','source_ordinal','source_key',
    'component_kind','economic_key_type','economic_key_value',
    'component_member_identity','segment_id','segment_key','segment_stable_key',
    'work_date','reference_number','hours_day','hours_night','hours_sat',
    'hours_sun','hours_bh','additional_code_raw','unit_count','unit_pay_rate',
    -- S7 (WB-007, WB-013, 24 section 5): `adjustment_id` is deliberately absent
    -- from this exact-key allowlist and from the C1 component relation.  An
    -- adjustment is never copied into a head, because an adjustment created
    -- later would make the snapshot stale and create a second owner.  A caller
    -- that still sends the key now fails closed here.
    'unit_charge_rate','expense_code','pay_ex_vat',
    'charge_ex_vat','exclude_from_pay','origin','component_sha256','record_type'
  ];
  v_schedule_keys constant text[]:=array[
    'work_date','start_at_local','end_at_local','break_minutes'
  ];
  v_actor_user_id uuid;
  v_family_id uuid;
  v_run_id uuid;
  v_source_cycle_id uuid;
  v_client_id uuid;
  v_work_event_id uuid;
  v_evidence_timesheet_id uuid;
  v_expected_bound_version bigint;
  v_comparison_revision_id uuid;
  v_final_revision_id uuid;
  v_reason text;
  v_idempotency_key text;
  v_schedule jsonb;
  v_rate_classification jsonb;
  v_source_proposal jsonb;
  v_selected_source_witness jsonb;
  v_target_snapshot jsonb;
  v_component_identity_context jsonb;
  v_component_identity_basis jsonb;
  v_bulk_signed_proof jsonb;
  v_automatic_reconcile_proof jsonb;
  v_start jsonb;
  v_sources jsonb;
  v_components jsonb;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_lock_family jsonb; v_lock_group uuid;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_root public.timesheets%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_evidence public.timesheets%rowtype;
  v_signed_evidence jsonb;
  v_event public.weekly_work_events%rowtype;
  v_prior_generation public.weekly_exceptional_pay_generations%rowtype;
  v_approval public.weekly_exceptional_payment_approvals%rowtype;
  v_generation public.weekly_exceptional_pay_generations%rowtype;
  v_publication public.weekly_exceptional_c1_publication_requests%rowtype;
  v_policy jsonb;
  v_source_mode text; v_activated_source_mode text;
  v_work_date date;
  v_start_at timestamp without time zone;
  v_end_at timestamp without time zone;
  v_break_minutes integer;
  v_expected_source_count integer;
  v_expected_component_count integer;
  v_expected_payload_bytes integer;
  v_request_sequence bigint;
  v_expected_head_revision bigint;
  v_financial_row_id uuid;
  v_request_id uuid;
  v_source_manifest_hash bytea;
  v_entitlement_hash bytea;
  v_outer_approval_hash bytea;
  v_c1_request_hash bytea;
  v_rate_policy_hash bytea;
  v_schedule_hash bytea;
  v_source_proposal_hash bytea;
  v_prior_vector jsonb;
  v_prior_vector_hash bytea;
  v_next_vector jsonb;
  v_next_vector_hash bytea;
  v_fixed_source_hash bytea;
  v_local_approval_hash bytea;
  v_family_event_hash bytea;
  v_target_event_hash bytea;
  v_prior_family_event_hash bytea;
  v_prior_target_event_hash bytea;
  v_issue_ids uuid[]:='{}'::uuid[];
  v_issue_ids_hash bytea;
  v_signed_revision integer;
  v_signed_hash bytea;
  v_signed_at timestamptz;
  v_generation_number integer;
  v_generation_reason text;
  v_family_event_state text;
  v_resulting_lifecycle_state text;
  v_pending_outcome text;
  v_payment_event_kind text;
  v_other_wait_count integer:=0;
  v_family_event_sequence bigint;
  v_family_event_id uuid;
  v_target_event_sequence bigint;
  v_total_pay numeric(12,2):=0;
  v_payload_total bigint:=0;
  v_previous_source_key text:=null;
  v_source_entry jsonb;
  v_part_entry jsonb;
  v_component_entry jsonb;
  v_source_id uuid;
  v_source_ordinal integer;
  v_source_counter integer:=0;
  v_part_ordinal integer;
  v_component_ordinal integer;
  v_part_payload bytea;
  v_part_concat bytea;
  v_source_part_count integer;
  v_source_payload_bytes integer;
  v_source_kind text;
  v_source_document jsonb;
  v_count_client integer:=0;
  v_count_candidate integer:=0;
  v_count_root integer:=0;
  v_count_provider integer:=0;
  v_count_office integer:=0;
  v_step_sequence integer;
  v_request_body_hash bytea;
  v_before_hash bytea;
  v_after_hash bytea;
begin
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,v_top_keys||array['bulk_signed_selection_proof','automatic_reconcile_selection_sha256'])
     or not (p_request ?& v_top_keys)
     or p_request->>'schema_version'<>'WEEKLY_PROTECTED_C1_STAGE_REQUEST_V1'
     or pg_catalog.jsonb_typeof(p_request->'protected_schedule')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'rate_classification')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'source_proposal')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'target_snapshot')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'c1_request')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'c1_sources')<>'array'
     or pg_catalog.jsonb_typeof(p_request->'c1_components')<>'array' then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_INVALID' using errcode='22023';
  end if;
  if pg_catalog.octet_length(pg_catalog.convert_to(p_request::text,'UTF8'))>4194304 then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_TOO_LARGE' using errcode='54000';
  end if;
  begin
    v_actor_user_id:=(p_request->>'actor_user_id')::uuid;
    v_family_id:=(p_request->>'family_id')::uuid;
    v_run_id:=(p_request->>'orchestration_run_id')::uuid;
    v_source_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_client_id:=(p_request->>'client_id')::uuid;
    v_work_event_id:=(p_request->>'work_event_id')::uuid;
    v_evidence_timesheet_id:=nullif(p_request->>'evidence_timesheet_id','')::uuid;
    v_expected_bound_version:=(p_request->>'expected_family_bound_version')::bigint;
    v_comparison_revision_id:=nullif(p_request->>'current_comparison_revision_id','')::uuid;
    v_final_revision_id:=nullif(p_request->>'current_final_revision_id','')::uuid;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_INVALID' using errcode='22023';
  end;
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  if pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_idempotency_key) not between 16 and 240 then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_INVALID' using errcode='22023';
  end if;

  v_schedule:=p_request->'protected_schedule';
  if not private.weekly_exceptional_json_keys_exact_v1(v_schedule,v_schedule_keys)
     or not (v_schedule ?& v_schedule_keys) then
    raise exception 'WEEKLY_PROTECTED_SCHEDULE_INVALID' using errcode='22023';
  end if;
  begin
    v_work_date:=(v_schedule->>'work_date')::date;
    v_start_at:=(v_schedule->>'start_at_local')::timestamp without time zone;
    v_end_at:=(v_schedule->>'end_at_local')::timestamp without time zone;
    v_break_minutes:=(v_schedule->>'break_minutes')::integer;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_SCHEDULE_INVALID' using errcode='22023';
  end;
  if v_end_at<=v_start_at or v_start_at::date<>v_work_date
     or v_break_minutes<0
     or v_break_minutes>=extract(epoch from (v_end_at-v_start_at))/60 then
    raise exception 'WEEKLY_PROTECTED_SCHEDULE_INVALID' using errcode='22023';
  end if;
  v_rate_classification:=p_request->'rate_classification';
  v_source_proposal:=p_request->'source_proposal';
  v_target_snapshot:=p_request->'target_snapshot';
  if pg_catalog.octet_length(pg_catalog.convert_to(v_rate_classification::text,'UTF8'))>65536
     or pg_catalog.octet_length(pg_catalog.convert_to(v_source_proposal::text,'UTF8'))>65536
     or pg_catalog.octet_length(pg_catalog.convert_to(v_target_snapshot::text,'UTF8'))>1048576 then
    raise exception 'WEEKLY_PROTECTED_TARGET_TOO_LARGE' using errcode='54000';
  end if;

  v_start:=p_request->'c1_request';
  v_sources:=p_request->'c1_sources';
  v_components:=p_request->'c1_components';
  if not private.weekly_exceptional_json_keys_exact_v1(v_start,v_c1_keys)
     or not (v_start ?& v_c1_keys)
     or pg_catalog.jsonb_array_length(v_sources) not between 1 and 65536
     or pg_catalog.jsonb_array_length(v_components)>65536 then
    raise exception 'WEEKLY_PROTECTED_C1_STREAM_INVALID' using errcode='22023';
  end if;
  begin
    v_request_id:=(v_start->>'request_id')::uuid;
    v_request_sequence:=(v_start->>'request_sequence')::bigint;
    v_expected_head_revision:=(v_start->>'expected_head_revision')::bigint;
    v_expected_source_count:=(v_start->>'expected_source_count')::integer;
    v_expected_component_count:=(v_start->>'expected_component_count')::integer;
    v_expected_payload_bytes:=(v_start->>'expected_payload_bytes')::integer;
    v_financial_row_id:=(v_start->>'financial_row_id')::uuid;
    v_source_manifest_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'source_manifest_sha256');
    v_entitlement_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'entitlement_sha256');
    v_outer_approval_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'approval_sha256');
    v_c1_request_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'request_sha256');
  exception when others then
    raise exception 'WEEKLY_PROTECTED_C1_STREAM_INVALID' using errcode='22023';
  end;
  if v_request_sequence<1 or v_expected_head_revision<0
     or v_expected_source_count<>pg_catalog.jsonb_array_length(v_sources)
     or v_expected_component_count<>pg_catalog.jsonb_array_length(v_components)
     or v_expected_payload_bytes<1
     or ((v_start->>'is_zero_entitlement')::boolean is distinct from
         (v_expected_component_count=0)) then
    raise exception 'WEEKLY_PROTECTED_C1_STREAM_COUNT_INVALID' using errcode='22023';
  end if;

  -- An exact staged request is the idempotency authority even after the family
  -- version advances.  A UUID collision with different bytes always refuses.
  select request.* into v_publication
  from public.weekly_exceptional_c1_publication_requests request
  where request.id=v_request_id;
  if found then
    if v_publication.family_id is distinct from v_family_id
       or v_publication.orchestration_run_id is distinct from v_run_id
       or v_publication.request_sha256 is distinct from v_c1_request_hash then
      raise exception 'WEEKLY_PROTECTED_C1_REQUEST_ID_COLLISION' using errcode='23505';
    end if;
    perform private.weekly_source_bulk_stage_replay_assert_v1(v_publication.id,p_request);
    perform private.weekly_source_automatic_reconcile_stage_replay_assert_v1(v_publication.id,p_request);
    return pg_catalog.jsonb_build_object(
      'ok',true,'outcome','STAGED','idempotent_replay',true,
      'family_id',v_publication.family_id,'generation_id',v_publication.generation_id,
      'publication_request_id',v_publication.id,'request_sha256',
      pg_catalog.encode(v_publication.request_sha256,'hex'),
      'state',v_publication.state
    );
  end if;

  v_lock_family:=private.weekly_source_protected_family_lock_v1(v_family_id);
  -- An exact staged request is the idempotency authority even after the family
  -- version advances.  A UUID collision with different bytes always refuses.
  select request.* into v_publication
  from public.weekly_exceptional_c1_publication_requests request
  where request.id=v_request_id
  for update;
  if found then
    if v_publication.family_id is distinct from v_family_id
       or v_publication.orchestration_run_id is distinct from v_run_id
       or v_publication.request_sha256 is distinct from v_c1_request_hash then
      raise exception 'WEEKLY_PROTECTED_C1_REQUEST_ID_COLLISION' using errcode='23505';
    end if;
    perform private.weekly_source_bulk_stage_replay_assert_v1(v_publication.id,p_request);
    perform private.weekly_source_automatic_reconcile_stage_replay_assert_v1(v_publication.id,p_request);
    return pg_catalog.jsonb_build_object(
      'ok',true,'outcome','STAGED','idempotent_replay',true,
      'family_id',v_publication.family_id,'generation_id',v_publication.generation_id,
      'publication_request_id',v_publication.id,'request_sha256',
      pg_catalog.encode(v_publication.request_sha256,'hex'),
      'state',v_publication.state
    );
  end if;

  select family.* into strict v_family
  from public.weekly_exceptional_pay_target_families family
  where family.id=v_family_id
  for update;
  select run.* into strict v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.id=v_run_id and run.family_id=v_family.id
  for update;
  if (v_family.root_timesheet_id::text,v_family.candidate_id::text,v_family.contract_id::text,v_family.week_ending_date::text)
    is distinct from (v_lock_family->>'root_timesheet_id',v_lock_family->>'candidate_id',
      v_lock_family->>'contract_id',v_lock_family->>'week_ending_date') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_source_cycle_id);
  if p_request ? 'bulk_signed_selection_proof' or p_request ? 'automatic_reconcile_selection_sha256' then
    -- The new one-shift round seals one pending proof at a time using the
    -- existing cycle mutex; the individual path retains its native SHARE.
    select cycle.* into strict v_cycle from public.weekly_source_cycles cycle
      where cycle.id=v_source_cycle_id for update;
  else
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle
  where cycle.id=v_source_cycle_id
  for share;
  end if;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id and source_group.active
  for share;
  perform private.weekly_source_office_authority_v1(
    v_actor_user_id,'APPROVE_PROTECTED_PAY',v_group.id,v_client_id,v_work_date
  );

  if v_run.requested_by_user_id is distinct from v_actor_user_id
     or v_run.state<>'RUNNING'
     or v_run.request_kind not in (
       'APPROVE','AMEND','WITHDRAW','RECONCILE','RECORD_NOT_WORKED'
     )
     or v_family.bound_version<>v_expected_bound_version
     or v_family.c1_publication_state in ('PENDING','PUBLISHING')
     or v_family.agency_id is distinct from v_group.agency_id
     or v_family.root_timesheet_id is null
     or v_work_date not between v_family.week_start_date and v_family.week_ending_date
     or not exists(
       select 1 from public.weekly_source_group_clients membership
       where membership.source_group_id=v_group.id
         and membership.client_id=v_client_id
         and v_work_date between membership.valid_from
           and coalesce(membership.valid_to,'infinity'::date)
     ) then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_SCOPE_INVALID' using errcode='55000';
  end if;

  select timesheet.* into strict v_root
  from public.timesheets timesheet
  where timesheet.timesheet_id=v_family.root_timesheet_id
  for share;
  select financial.* into strict v_fin
  from public.timesheets_financials financial
  where financial.id=v_financial_row_id
    and financial.timesheet_id=v_root.timesheet_id
    and financial.is_current
  for share;
  select event.* into strict v_event
  from public.weekly_work_events event
  where event.id=v_work_event_id
    and event.candidate_id=v_family.candidate_id
    and event.client_id=v_client_id
    and event.work_date=v_work_date
  for share;
  if v_root.contract_id is distinct from v_family.contract_id
     or v_root.week_ending_date is distinct from v_family.week_ending_date
     or v_root.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum
     or v_root.line_type<>'HOURS'::public.timesheet_line_type_enum
     or v_root.is_adjustment or not v_root.is_current
     or v_root.revoked_at is not null or v_root.archived_at_utc is not null then
    raise exception 'WEEKLY_PROTECTED_C1_ROOT_INVALID' using errcode='55000';
  end if;

  v_policy:=private._weekly_source_effective_policy_v1(
    v_client_id,v_family.contract_id,v_work_date
  );
  v_activated_source_mode:=private.weekly_source_protected_non_self_bill_mode_v1(v_client_id,v_family.contract_id,v_work_date,v_cycle.id,v_actor_user_id,v_work_event_id);
  v_source_mode:=coalesce(v_policy->>'c1_source_mode',v_activated_source_mode);
  if v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or (coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true and v_activated_source_mode is null)
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_PROTECTED_C1_POLICY_INVALID' using errcode='55000';
  end if;

  -- Existing WITHDRAW/RECONCILE actions accept actual Source, including
  -- certified absence; this does not define any other removal action. A
  -- Final-only synthetic zero proposal is not proof that Source is absent.
  -- Keep replay above this fresh admission check; do not reinterpret a saved
  -- decision after subsequent imports or change the Banking publication owner.
  if v_run.request_kind in ('WITHDRAW','RECONCILE') then
    v_selected_source_witness:=private.weekly_source_selected_source_witness_v1(
      v_family.id,v_cycle.id,v_event.id
    );
    if v_selected_source_witness is null
       or v_selected_source_witness->'source_proposal' is distinct from v_source_proposal
       or (v_selected_source_witness->>'kind'='CURRENT_ROW' and (
         v_selected_source_witness#>>'{basis,final_revision_id}' is null
         or v_selected_source_witness#>>'{basis,final_revision_id}' is distinct from v_source_proposal->>'source_revision'
         or v_source_proposal->'source_present' is distinct from 'true'::jsonb
       ))
       or (v_selected_source_witness->>'kind'='CERTIFIED_ABSENCE' and (
         v_source_proposal->'source_present' is distinct from 'false'::jsonb
         or v_source_proposal->>'source_minutes' is distinct from '0'
       ))
       or coalesce(v_selected_source_witness->>'kind' not in ('CURRENT_ROW','CERTIFIED_ABSENCE'),true) then
      raise exception 'WEEKLY_PROTECTED_C1_SELECTED_SOURCE_UNAVAILABLE' using errcode='55000';
    end if;
  end if;

  if (v_start->>'actor_user_id')::uuid is distinct from v_actor_user_id
     or (v_start->>'candidate_id')::uuid is distinct from v_family.candidate_id
     or (v_start->>'contract_id')::uuid is distinct from v_family.contract_id
     or (v_start->>'root_timesheet_id')::uuid is distinct from v_root.timesheet_id
     or (v_start->>'week_ending_date')::date is distinct from v_family.week_ending_date
     or v_start->>'source_mode'<>v_source_mode
     or v_financial_row_id is distinct from v_fin.id
     or v_request_sequence<>v_family.current_generation_number+1 then
    raise exception 'WEEKLY_PROTECTED_C1_START_SCOPE_INVALID' using errcode='55000';
  end if;
  if v_family.current_generation_id is null then
    if v_expected_head_revision<>0 then
      raise exception 'WEEKLY_PROTECTED_C1_HEAD_INVALID' using errcode='55000';
    end if;
  else
    select generation.* into strict v_prior_generation
    from public.weekly_exceptional_pay_generations generation
    where generation.id=v_family.current_generation_id
      and generation.family_id=v_family.id
      and generation.lifecycle_state='PUBLISHED'
    for share;
    select request.* into strict v_publication
    from public.weekly_exceptional_c1_publication_requests request
    where request.generation_id=v_prior_generation.id
      and request.family_id=v_family.id
      and (request.state='PUBLISHED' or (request.state='RETIRED' and exists(
        select 1 from private.weekly_source_local_protected_decision_receipts receipt
        where receipt.publication_request_id=request.id and receipt.generation_id=v_prior_generation.id
          and receipt.state='COMPLETE')));
    if (case when v_publication.state='RETIRED' then v_prior_generation.generation_number::bigint
             else v_publication.c1_head_revision end) is distinct from v_expected_head_revision then
      raise exception 'WEEKLY_PROTECTED_C1_HEAD_INVALID' using errcode='55000';
    end if;
    v_publication.id:=null;
  end if;

  if v_evidence_timesheet_id is not null then
    select evidence.* into strict v_evidence
    from public.timesheets evidence
    where evidence.timesheet_id=v_evidence_timesheet_id
      and evidence.contract_id=v_family.contract_id
      and evidence.week_ending_date=v_family.week_ending_date
      and evidence.sheet_scope='WEEKLY'::public.timesheet_scope_enum
      and evidence.is_current and evidence.revoked_at is null
      and evidence.archived_at_utc is null;
    v_signed_evidence:=private.weekly_exceptional_candidate_signed_evidence_v1(
      v_evidence_timesheet_id
    );
    v_signed_at:=(v_signed_evidence->>'signed_at_utc')::timestamptz;
    v_signed_revision:=(v_signed_evidence->>'timesheet_version')::integer;
    v_signed_hash:=private.weekly_exceptional_hex_sha256_v1(
      v_signed_evidence->>'signature_sha256'
    );
  end if;

  select coalesce(pg_catalog.array_agg(incident.id order by incident.id),'{}'::uuid[])
    into v_issue_ids
  from public.weekly_discrepancy_incidents incident
  where incident.source_group_id=v_group.id
    and incident.work_event_id=v_work_event_id
    and incident.candidate_id=v_family.candidate_id
    and incident.client_id=v_client_id;
  v_issue_ids_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_ISSUE_SET_V1',pg_catalog.to_jsonb(v_issue_ids)
  );
  v_schedule_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_SCHEDULE_V1',v_schedule
  );
  v_rate_policy_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_RATE_POLICY_V1',
    pg_catalog.jsonb_build_object(
      'contract_id',v_family.contract_id,
      'rates_json',(select contract.rates_json from public.contracts contract where contract.id=v_family.contract_id),
      'policy',v_policy,'classification',v_rate_classification
    )
  );
  v_source_proposal_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_SOURCE_PROPOSAL_V1',v_source_proposal
  );

  if v_comparison_revision_id is not null and not exists(
    select 1
    from public.weekly_issue_comparison_revisions comparison
    join public.weekly_discrepancy_incidents incident on incident.id=comparison.incident_id
    where comparison.id=v_comparison_revision_id
      and comparison.contract_id=v_family.contract_id
      and incident.source_group_id=v_group.id
      and incident.work_event_id=v_work_event_id
      and incident.candidate_id=v_family.candidate_id
      and incident.client_id=v_client_id
  ) then
    raise exception 'WEEKLY_PROTECTED_COMPARISON_SCOPE_INVALID' using errcode='55000';
  end if;
  if v_final_revision_id is not null and not exists(
    select 1 from public.weekly_source_final_revisions final_revision
    where final_revision.id=v_final_revision_id
      and final_revision.source_cycle_id=v_source_cycle_id
      and final_revision.state='CURRENT'
  ) then
    raise exception 'WEEKLY_PROTECTED_FINAL_SCOPE_INVALID' using errcode='55000';
  end if;

  -- Validate and persist the complete normalized C1 source stream.  The C1
  -- owner independently replays its TLV hashes before certification; these
  -- local checks prevent truncation, reordering or cross-root substitution.
  for v_source_entry in
    select value from pg_catalog.jsonb_array_elements(v_sources)
  loop
    v_source_counter:=v_source_counter+1;
    if not private.weekly_exceptional_json_keys_exact_v1(v_source_entry,v_source_keys)
       or not (v_source_entry ?& v_source_keys)
       or v_source_entry->>'record_type'<>'SOURCE'
       or pg_catalog.jsonb_typeof(v_source_entry->'parts')<>'array' then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_INVALID' using errcode='22023';
    end if;
    begin
      v_source_ordinal:=(v_source_entry->>'source_ordinal')::integer;
      v_source_id:=(v_source_entry->>'source_id')::uuid;
      v_source_payload_bytes:=(v_source_entry->>'payload_bytes')::integer;
      v_source_part_count:=(v_source_entry->>'part_count')::integer;
    exception when others then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_INVALID' using errcode='22023';
    end;
    if v_source_ordinal<>v_source_counter
       or v_source_ordinal not between 1 and v_expected_source_count
       or (v_source_entry->>'root_timesheet_id')::uuid is distinct from v_root.timesheet_id
       or (v_source_entry->>'candidate_id')::uuid is distinct from v_family.candidate_id
       or (v_source_entry->>'contract_id')::uuid is distinct from v_family.contract_id
       or v_source_payload_bytes not between 1 and 16384
       or v_source_part_count<>pg_catalog.jsonb_array_length(v_source_entry->'parts')
       or v_source_part_count not between 1 and 6 then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_SCOPE_INVALID' using errcode='55000';
    end if;
    v_source_kind:=v_source_entry->>'authority_kind';
    if v_source_kind not in (
      'CANDIDATE_SUBMISSION','CLIENT_SOURCE','OFFICE_APPROVAL','ROOT_FINANCIAL',
      'PROVIDER','SOURCE_EXPENSE','ORDINARY_EXPENSE','APPROVED_COMPONENT'
    ) then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_KIND_INVALID' using errcode='22023';
    end if;
    v_count_client:=v_count_client+(v_source_kind='CLIENT_SOURCE')::integer;
    v_count_candidate:=v_count_candidate+(v_source_kind='CANDIDATE_SUBMISSION')::integer;
    v_count_root:=v_count_root+(v_source_kind='ROOT_FINANCIAL')::integer;
    v_count_provider:=v_count_provider+(v_source_kind='PROVIDER')::integer;
    v_count_office:=v_count_office+(v_source_kind='OFFICE_APPROVAL')::integer;
    v_part_concat:=''::bytea;
    v_part_ordinal:=0;
    for v_part_entry in
      select value from pg_catalog.jsonb_array_elements(v_source_entry->'parts')
    loop
      v_part_ordinal:=v_part_ordinal+1;
      if not private.weekly_exceptional_json_keys_exact_v1(v_part_entry,v_part_keys)
         or not (v_part_entry ?& v_part_keys)
         or v_part_entry->>'record_type'<>'PART'
         or (v_part_entry->>'source_ordinal')::integer<>v_source_ordinal
         or (v_part_entry->>'part_ordinal')::integer<>v_part_ordinal
         or coalesce(v_part_entry->>'payload_utf8','')!~'^(?:[0-9a-f]{2})+$' then
        raise exception 'WEEKLY_PROTECTED_C1_PART_INVALID' using errcode='22023';
      end if;
      v_part_payload:=pg_catalog.decode(v_part_entry->>'payload_utf8','hex');
      if pg_catalog.octet_length(v_part_payload) not between 1 and 3072
         or extensions.digest(v_part_payload,'sha256') is distinct from
            private.weekly_exceptional_hex_sha256_v1(v_part_entry->>'fragment_sha256') then
        raise exception 'WEEKLY_PROTECTED_C1_PART_HASH_INVALID' using errcode='22023';
      end if;
      v_part_concat:=v_part_concat||v_part_payload;
    end loop;
    if v_part_ordinal<>v_source_part_count
       or pg_catalog.octet_length(v_part_concat)<>v_source_payload_bytes then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_PAYLOAD_INVALID' using errcode='22023';
    end if;
    begin
      v_source_document:=pg_catalog.convert_from(v_part_concat,'UTF8')::jsonb;
    exception when others then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_DOCUMENT_INVALID' using errcode='22023';
    end;
    if pg_catalog.jsonb_typeof(v_source_document)<>'object'
       or (v_source_document->>'root_timesheet_id')::uuid is distinct from v_root.timesheet_id
       or (v_source_document->>'candidate_id')::uuid is distinct from v_family.candidate_id
       or (v_source_document->>'contract_id')::uuid is distinct from v_family.contract_id
       or (v_source_document->>'week_ending_date')::date is distinct from v_family.week_ending_date
       or v_source_document->>'document_sha256' is distinct from
          v_source_entry->>'source_document_sha256' then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_DOCUMENT_SCOPE_INVALID' using errcode='55000';
    end if;
    if v_source_kind='CLIENT_SOURCE'
       and coalesce((v_source_document->>'source_complete')::boolean,false) is not true then
      raise exception 'WEEKLY_PROTECTED_C1_CLIENT_SOURCE_INCOMPLETE' using errcode='55000';
    elsif v_source_kind='ROOT_FINANCIAL'
       and (v_source_document->>'financial_row_id')::uuid is distinct from v_fin.id then
      raise exception 'WEEKLY_PROTECTED_C1_ROOT_FINANCIAL_INVALID' using errcode='55000';
    elsif v_source_kind='OFFICE_APPROVAL'
       and (
         (v_source_document->>'actor_user_id')::uuid is distinct from v_actor_user_id
         or (v_source_document->>'request_id')::uuid is distinct from v_request_id
         or v_source_document->>'entitlement_sha256' is distinct from
            v_start->>'entitlement_sha256'
         or v_source_document->>'decision'<>'APPROVE_ENTITLEMENT'
       ) then
      raise exception 'WEEKLY_PROTECTED_C1_OFFICE_SOURCE_INVALID' using errcode='55000';
    end if;
    v_payload_total:=v_payload_total+v_source_payload_bytes;
  end loop;
  if v_source_counter<>v_expected_source_count
     or v_count_client<1 or v_count_root<>1 or v_count_provider<>1 or v_count_office<>1
     or (v_evidence_timesheet_id is null and v_count_candidate<>0)
     or (v_evidence_timesheet_id is not null and v_count_candidate<>1)
     or v_payload_total<>v_expected_payload_bytes then
    raise exception 'WEEKLY_PROTECTED_C1_SOURCE_CARDINALITY_INVALID' using errcode='55000';
  end if;

  v_component_ordinal:=0;
  for v_component_entry in
    select value from pg_catalog.jsonb_array_elements(v_components)
  loop
    v_component_ordinal:=v_component_ordinal+1;
    if not private.weekly_exceptional_json_keys_exact_v1(v_component_entry,v_component_keys)
       or not (v_component_entry ?& v_component_keys)
       or v_component_entry->>'record_type'<>'COMPONENT'
       or (v_component_entry->>'component_ordinal')::integer<>v_component_ordinal
       or (v_component_entry->>'source_ordinal')::integer not between 1 and v_expected_source_count
       or coalesce(v_component_entry->>'source_key','')=''
       or (v_previous_source_key is not null and v_component_entry->>'source_key'<=v_previous_source_key) then
      raise exception 'WEEKLY_PROTECTED_C1_COMPONENT_INVALID' using errcode='22023';
    end if;
    if nullif(v_component_entry->>'work_date','') is not null
       and (v_component_entry->>'work_date')::date not between
           v_family.week_start_date and v_family.week_ending_date then
      raise exception 'WEEKLY_PROTECTED_C1_COMPONENT_WEEK_INVALID' using errcode='55000';
    end if;
    v_total_pay:=v_total_pay+(v_component_entry->>'pay_ex_vat')::numeric;
    perform private.weekly_exceptional_hex_sha256_v1(v_component_entry->>'component_sha256');
    v_previous_source_key:=v_component_entry->>'source_key';
  end loop;
  if v_component_ordinal<>v_expected_component_count then
    raise exception 'WEEKLY_PROTECTED_C1_COMPONENT_COUNT_INVALID' using errcode='22023';
  end if;
  v_total_pay:=pg_catalog.round(v_total_pay,2);

  if v_family.current_generation_id is null then
    -- Before the prepare owner distinguished empty from published families,
    -- a retry could be recorded as AMEND even though nothing was published.
    -- Preserve that immutable request and permit only its first generation;
    -- never treat an existing staged/published entitlement as an initial one.
    if v_run.request_kind not in ('APPROVE','AMEND')
       or v_family.current_generation_number<>0
       or v_family.current_lifecycle_state<>'PENDING_APPROVAL'
       or exists(select 1 from public.weekly_exceptional_pay_generations existing
         where existing.family_id=v_family.id) then
      raise exception 'WEEKLY_PROTECTED_C1_INITIAL_ACTION_INVALID' using errcode='55000';
    end if;
    v_prior_vector:=pg_catalog.jsonb_build_object(
      'schema_version','WEEKLY_PROTECTED_TARGET_VECTOR_V1',
      'components',pg_catalog.jsonb_build_array(),
      'component_count',0,'is_zero_entitlement',true
    );
    v_generation_number:=1;
    v_generation_reason:='INITIAL_APPROVAL';
  else
    v_prior_vector:=v_prior_generation.complete_next_vector_json;
    v_generation_number:=v_prior_generation.generation_number+1;
    v_generation_reason:=case v_run.request_kind
      when 'AMEND' then 'OFFICE_AMENDMENT'
      when 'WITHDRAW' then 'WITHDRAW'
      when 'RECONCILE' then 'RECONCILE'
      when 'RECORD_NOT_WORKED' then 'RECORD_NOT_WORKED'
      else null end;
    if v_generation_reason is null then
      raise exception 'WEEKLY_PROTECTED_C1_ACTION_INVALID' using errcode='55000';
    end if;
  end if;
  v_family_event_state:=case
    when v_run.request_kind in ('APPROVE','AMEND') then 'WAIT'
    when v_run.request_kind in ('WITHDRAW','RECONCILE') then 'ACCEPTED_SOURCE'
    else 'NOT_WORKED' end;
  if v_run.request_kind='RECORD_NOT_WORKED'
     and coalesce((v_source_proposal->>'source_present')::boolean,true) then
    raise exception 'WEEKLY_PROTECTED_NOT_WORKED_SOURCE_PRESENT' using errcode='55000';
  end if;
  with latest as (
    select family_event.durable_work_event_id,family_event.state,
      pg_catalog.row_number() over (
        partition by family_event.durable_work_event_id
        order by family_event.event_sequence desc
      ) as event_rank
    from public.weekly_exceptional_pay_family_events family_event
    where family_event.family_id=v_family.id
      and family_event.durable_work_event_id<>v_work_event_id
  )
  select pg_catalog.count(*)::integer into v_other_wait_count
  from latest where event_rank=1 and state='WAIT';
  v_resulting_lifecycle_state:=case
    when v_family_event_state='WAIT' or v_other_wait_count>0 then 'WAITING_SOURCE'
    when v_run.request_kind='RECORD_NOT_WORKED' then 'NOT_WORKED'
    else 'RECONCILED' end;
  v_pending_outcome:=case v_family_event_state
    when 'WAIT' then 'WAIT'
    when 'ACCEPTED_SOURCE' then 'ACCEPT_SOURCE'
    else 'RECORD_NOT_WORKED' end;
  v_payment_event_kind:=case v_run.request_kind
    when 'APPROVE' then 'APPROVED'
    when 'AMEND' then 'APPROVED'
    when 'RECORD_NOT_WORKED' then 'RECORDED_NOT_WORKED'
    else 'MATCH_ACCEPTED' end;
  v_prior_vector_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',v_prior_vector
  );
  v_next_vector:=pg_catalog.jsonb_build_object(
    'schema_version','WEEKLY_PROTECTED_TARGET_VECTOR_V1',
    'target_snapshot',v_target_snapshot,
    'components',v_components,
    'component_count',v_expected_component_count,
    'is_zero_entitlement',(v_expected_component_count=0),
    'entitlement_sha256',v_start->>'entitlement_sha256',
    'approved_pay_ex_vat',pg_catalog.to_char(v_total_pay,'FM9999999990.00')
  );
  -- Identity metadata is admitted only against this fresh, actual server
  -- context under the established stage locks, never the caller's manifest.
  -- Matching clocks are not a historical identity-derivation fallback.
  v_component_identity_context:=public.weekly_exceptional_pay_action_context_v1(
    jsonb_build_object('schema_version','WEEKLY_PROTECTED_ACTION_CONTEXT_V1',
      'actor_user_id',v_actor_user_id,'family_id',v_family.id,
      'orchestration_run_id',v_run.id,'source_cycle_id',v_cycle.id,
      'work_event_id',v_event.id,'protected_schedule',v_schedule,
      'evidence_timesheet_id',v_evidence_timesheet_id));
  if v_component_identity_context->>'root_timesheet_id' is distinct from v_root.timesheet_id::text
     or v_component_identity_context#>>'{current_financial,id}' is distinct from v_fin.id::text
     or v_component_identity_context->>'family_bound_version' is distinct from v_expected_bound_version::text
     or v_component_identity_context->'source_proposal' is distinct from v_source_proposal then
    raise exception 'WEEKLY_PROTECTED_COMPONENT_MANIFEST_UNAVAILABLE' using errcode='55000'; end if;
  v_component_identity_basis:=private.weekly_source_protected_component_manifest_v1(
    v_component_identity_context,v_target_snapshot);
  v_next_vector:=v_next_vector||jsonb_build_object(
    'protected_component_identity_basis',v_component_identity_basis);
  -- Seal the common before-position at approval. A later authorised amendment
  -- must not silently replace an entitlement published after this calculation.
  if v_root.authorised_at_server is not null then
    v_next_vector:=v_next_vector||pg_catalog.jsonb_build_object(
      'prior_effective_inventory',private.weekly_source_effective_inventory_v1(v_root.timesheet_id));
  end if;
  if p_request ? 'bulk_signed_selection_proof' then
    v_bulk_signed_proof:=private.weekly_source_bulk_stage_proof_v1(p_request,v_fin.id);
    v_next_vector:=v_next_vector||jsonb_build_object('bulk_signed_selection_proof',v_bulk_signed_proof);
  end if;
  if p_request ? 'automatic_reconcile_selection_sha256' then
    v_automatic_reconcile_proof:=private.weekly_source_automatic_reconcile_stage_proof_v1(p_request);
    v_next_vector:=v_next_vector||jsonb_build_object('automatic_reconcile_proof',v_automatic_reconcile_proof);
  end if;
  v_next_vector_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',v_next_vector
  );
  v_fixed_source_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_FIXED_SOURCE_STATE_V1',
    pg_catalog.jsonb_build_object(
      'source_cycle_id',v_source_cycle_id,
      'comparison_revision_id',v_comparison_revision_id,
      'final_revision_id',v_final_revision_id,
      'source_proposal_hash',pg_catalog.encode(v_source_proposal_hash,'hex'),
      'financial_row_id',v_fin.id,'financial_timesheet_version',v_fin.timesheet_version
    )
  );
  v_local_approval_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_APPROVAL_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'work_event_id',v_work_event_id,
      'candidate_id',v_family.candidate_id,'client_id',v_client_id,
      'contract_id',v_family.contract_id,'week_ending_date',v_family.week_ending_date,
      'schedule_hash',pg_catalog.encode(v_schedule_hash,'hex'),
      'evidence_timesheet_id',v_evidence_timesheet_id,
      'signed_hash',case when v_signed_hash is null then null else pg_catalog.encode(v_signed_hash,'hex') end,
      'issue_ids_hash',pg_catalog.encode(v_issue_ids_hash,'hex'),
      'rate_policy_hash',pg_catalog.encode(v_rate_policy_hash,'hex'),
      'target_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'actor_user_id',v_actor_user_id,'reason',v_reason
    )
  );

  insert into public.weekly_exceptional_payment_approvals(
    pay_target_family_id,work_event_id,evidence_timesheet_id,candidate_id,
    client_id,contract_id,week_ending,protected_work_date,
    protected_start_at_local,protected_end_at_local,protected_break_minutes,
    signed_submission_timesheet_id,signed_submission_revision,
    signed_submission_hash,signed_at_utc,contributing_issue_episode_ids,
    contributing_issue_episode_ids_hash,signed_schedule_fact_hash,
    contract_rate_policy_source_fingerprint,approved_by_user_id,
    approval_reason,source_cycle_id,comparison_revision_id,final_revision_id,
    approved_target_pay_components_json,approved_target_gross,
    creation_orchestration_run_id,approval_hash,creation_idempotency_key
  ) values (
    v_family.id,v_work_event_id,v_evidence_timesheet_id,v_family.candidate_id,
    v_client_id,v_family.contract_id,v_family.week_ending_date,v_work_date,
    v_start_at,v_end_at,v_break_minutes,
    v_evidence_timesheet_id,v_signed_revision,v_signed_hash,v_signed_at,v_issue_ids,
    v_issue_ids_hash,v_schedule_hash,v_rate_policy_hash,v_actor_user_id,
    v_reason,v_source_cycle_id,v_comparison_revision_id,v_final_revision_id,
    v_target_snapshot,v_total_pay,v_run.id,v_local_approval_hash,
    v_idempotency_key||':approval'
  ) returning * into v_approval;

  insert into public.weekly_exceptional_pay_generations(
    family_id,generation_number,prior_generation_id,prior_generation_hash,
    request_idempotency_key,reason,complete_prior_vector_json,
    complete_prior_vector_hash,complete_next_vector_json,complete_next_vector_hash,
    fixed_target_source_state_fingerprint,lifecycle_state
  ) values (
    v_family.id,v_generation_number,v_family.current_generation_id,
    case when v_family.current_generation_id is null then null else v_prior_vector_hash end,
    v_idempotency_key||':generation',v_generation_reason,v_prior_vector,
    v_prior_vector_hash,v_next_vector,v_next_vector_hash,v_fixed_source_hash,'PENDING_C1'
  ) returning * into v_generation;

  select coalesce(max(event_sequence),0)+1,
         (array_agg(event_hash order by event_sequence desc))[1]
    into v_family_event_sequence,v_prior_family_event_hash
  from public.weekly_exceptional_pay_family_events
  where family_id=v_family.id;
  v_family_event_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_FAMILY_EVENT_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'event_sequence',v_family_event_sequence,
      'work_event_id',v_work_event_id,'approval_id',v_approval.id,
      'schedule',v_schedule,'source_proposal_hash',pg_catalog.encode(v_source_proposal_hash,'hex'),
      'target_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'prior_event_hash',case when v_prior_family_event_hash is null then null
        else pg_catalog.encode(v_prior_family_event_hash,'hex') end
    )
  );
  insert into public.weekly_exceptional_pay_family_events(
    family_id,event_sequence,durable_work_event_id,evidence_approval_id,
    work_date,start_at_local,end_at_local,break_minutes,rate_classification_json,
    source_proposal_snapshot_json,source_proposal_hash,
    fixed_office_target_snapshot_json,fixed_office_target_hash,state,
    current_comparison_revision_id,current_final_revision_id,office_actor_user_id,
    office_reason,prior_event_hash,event_hash
  ) values (
    v_family.id,v_family_event_sequence,v_work_event_id,v_approval.id,
    v_work_date,v_start_at,v_end_at,v_break_minutes,v_rate_classification,
    v_source_proposal,v_source_proposal_hash,v_schedule,v_schedule_hash,v_family_event_state,
    v_comparison_revision_id,v_final_revision_id,v_actor_user_id,v_reason,
    v_prior_family_event_hash,v_family_event_hash
  ) returning id into v_family_event_id;
  if (select active_owner from private.bpay_next_module_control where id=1)='NEXT' then
    perform private.bpay_next_protected_current_decision_capture_v1(v_family_event_id);
  end if;

  select coalesce(max(event_sequence),0)+1,
         (array_agg(event_hash order by event_sequence desc))[1]
    into v_target_event_sequence,v_prior_target_event_hash
  from public.weekly_exceptional_pay_target_events
  where family_id=v_family.id;
  v_target_event_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_TARGET_EVENT_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'event_sequence',v_target_event_sequence,
      'approval_id',v_approval.id,'generation_id',v_generation.id,
      'prior_vector_hash',pg_catalog.encode(v_prior_vector_hash,'hex'),
      'next_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'reason',v_generation_reason,'actor_user_id',v_actor_user_id
    )
  );
  insert into public.weekly_exceptional_pay_target_events(
    family_id,approval_id,event_sequence,triggering_comparison_revision_id,
    triggering_final_revision_id,prior_event_fingerprint,
    fixed_target_component_snapshot,current_source_proposal_snapshot,
    complete_prior_family_vector_fingerprint,
    complete_next_family_vector_fingerprint,reason,resulting_lifecycle_state,
    financial_generation_id,actor_user_id,event_hash,idempotency_key
  ) values (
    v_family.id,v_approval.id,v_target_event_sequence,v_comparison_revision_id,
    v_final_revision_id,v_prior_target_event_hash,v_target_snapshot,v_source_proposal,
    v_prior_vector_hash,v_next_vector_hash,v_generation_reason,v_resulting_lifecycle_state,
    v_generation.id,v_actor_user_id,v_target_event_hash,v_idempotency_key||':target-event'
  );
  update public.weekly_exceptional_pending_reconciliation_targets target
  set state=case when v_run.request_kind='WITHDRAW' then 'WITHDRAWN' else 'CONSUMED' end,
      completed_at_utc=pg_catalog.statement_timestamp()
  where target.family_id=v_family.id
    and target.durable_work_event_id=v_work_event_id
    and target.state='ACTIVE';
  if v_family_event_state='WAIT' then
    insert into public.weekly_exceptional_pending_reconciliation_targets(
      family_id,approval_id,durable_work_event_id,incident_id,current_final_revision_id,
      intended_outcome,source_action_policy_target_fingerprint,state
    ) values (
      v_family.id,v_approval.id,v_work_event_id,
      (select incident.id from public.weekly_discrepancy_incidents incident
       where incident.source_group_id=v_group.id and incident.work_event_id=v_work_event_id
       order by incident.episode_number desc limit 1),
      v_final_revision_id,v_pending_outcome,v_fixed_source_hash,'ACTIVE'
    );
  end if;
  insert into public.weekly_exceptional_payment_events(
    family_id,approval_id,event_kind,lifecycle_view,bounded_payload_json,
    idempotency_key
  ) values (
    v_family.id,v_approval.id,v_payment_event_kind,'PENDING_C1',
    pg_catalog.jsonb_build_object(
      'work_event_id',v_work_event_id,'generation_id',v_generation.id,
      'target_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'approved_pay_ex_vat',pg_catalog.to_char(v_total_pay,'FM9999999990.00')
    ),v_idempotency_key||':payment-event'
  );

  insert into public.weekly_exceptional_c1_publication_requests(
    id,family_id,generation_id,orchestration_run_id,agency_id,candidate_id,
    contract_id,root_timesheet_id,week_ending_date,source_mode,request_sequence,
    expected_head_revision,expected_source_count,expected_component_count,
    expected_payload_bytes,source_manifest_sha256,entitlement_sha256,
    approval_sha256,is_zero_entitlement,financial_row_id,request_sha256,state
  ) values (
    v_request_id,v_family.id,v_generation.id,v_run.id,v_family.agency_id,
    v_family.candidate_id,v_family.contract_id,v_root.timesheet_id,
    v_family.week_ending_date,v_source_mode,v_request_sequence,
    v_expected_head_revision,v_expected_source_count,v_expected_component_count,
    v_expected_payload_bytes,v_source_manifest_hash,v_entitlement_hash,
    v_outer_approval_hash,(v_expected_component_count=0),v_fin.id,
    v_c1_request_hash,'READY'
  ) returning * into v_publication;

  for v_source_entry in select value from pg_catalog.jsonb_array_elements(v_sources)
  loop
    v_source_ordinal:=(v_source_entry->>'source_ordinal')::integer;
    v_source_id:=(v_source_entry->>'source_id')::uuid;
    insert into public.weekly_exceptional_c1_source_records(
      id,publication_request_id,source_ordinal,authority_kind,source_system,
      external_identity,external_revision,source_document_sha256,payload_bytes,
      part_count,work_date,root_timesheet_id,candidate_id,contract_id,
      source_row_sha256
    ) values (
      v_source_id,v_publication.id,v_source_ordinal,v_source_entry->>'authority_kind',
      v_source_entry->>'source_system',v_source_entry->>'external_identity',
      v_source_entry->>'external_revision',
      private.weekly_exceptional_hex_sha256_v1(v_source_entry->>'source_document_sha256'),
      (v_source_entry->>'payload_bytes')::integer,
      (v_source_entry->>'part_count')::integer,
      nullif(v_source_entry->>'work_date','')::date,v_root.timesheet_id,
      v_family.candidate_id,v_family.contract_id,
      private.weekly_exceptional_hex_sha256_v1(v_source_entry->>'source_row_sha256')
    );
    for v_part_entry in select value from pg_catalog.jsonb_array_elements(v_source_entry->'parts')
    loop
      insert into public.weekly_exceptional_c1_source_parts(
        publication_request_id,source_record_id,source_ordinal,part_ordinal,
        payload_utf8,fragment_sha256
      ) values (
        v_publication.id,v_source_id,v_source_ordinal,
        (v_part_entry->>'part_ordinal')::integer,
        pg_catalog.decode(v_part_entry->>'payload_utf8','hex'),
        private.weekly_exceptional_hex_sha256_v1(v_part_entry->>'fragment_sha256')
      );
    end loop;
  end loop;

  for v_component_entry in select value from pg_catalog.jsonb_array_elements(v_components)
  loop
    insert into public.weekly_exceptional_c1_component_records(
      publication_request_id,component_ordinal,component_id,source_ordinal,
      source_key,component_kind,economic_key_type,economic_key_value,
      component_member_identity,segment_id,segment_key,segment_stable_key,
      work_date,reference_number,hours_day,hours_night,hours_sat,hours_sun,
      hours_bh,additional_code_raw,unit_count,unit_pay_rate,unit_charge_rate,
      expense_code,pay_ex_vat,charge_ex_vat,exclude_from_pay,
      origin,component_sha256
    ) values (
      v_publication.id,(v_component_entry->>'component_ordinal')::integer,
      (v_component_entry->>'component_id')::uuid,
      (v_component_entry->>'source_ordinal')::integer,
      v_component_entry->>'source_key',v_component_entry->>'component_kind',
      v_component_entry->>'economic_key_type',v_component_entry->>'economic_key_value',
      v_component_entry->>'component_member_identity',nullif(v_component_entry->>'segment_id',''),
      nullif(v_component_entry->>'segment_key',''),nullif(v_component_entry->>'segment_stable_key',''),
      nullif(v_component_entry->>'work_date','')::date,nullif(v_component_entry->>'reference_number',''),
      nullif(v_component_entry->>'hours_day','')::numeric,
      nullif(v_component_entry->>'hours_night','')::numeric,
      nullif(v_component_entry->>'hours_sat','')::numeric,
      nullif(v_component_entry->>'hours_sun','')::numeric,
      nullif(v_component_entry->>'hours_bh','')::numeric,
      nullif(v_component_entry->>'additional_code_raw',''),
      nullif(v_component_entry->>'unit_count','')::numeric,
      nullif(v_component_entry->>'unit_pay_rate','')::numeric,
      nullif(v_component_entry->>'unit_charge_rate','')::numeric,
      nullif(v_component_entry->>'expense_code',''),
      (v_component_entry->>'pay_ex_vat')::numeric,
      nullif(v_component_entry->>'charge_ex_vat','')::numeric,
      (v_component_entry->>'exclude_from_pay')::boolean,
      v_component_entry->>'origin',
      private.weekly_exceptional_hex_sha256_v1(v_component_entry->>'component_sha256')
    );
  end loop;

  update public.weekly_exceptional_pay_target_families
  set c1_publication_state='PENDING',bound_version=bound_version+1
  where id=v_family.id;

  v_request_body_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_C1_STAGE_REQUEST_BODY_V1',p_request
  );
  v_before_hash:=v_run.before_state_fingerprint;
  v_after_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_C1_STAGED_STATE_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'generation_id',v_generation.id,
      'publication_request_id',v_publication.id,'request_sha256',
      pg_catalog.encode(v_c1_request_hash,'hex'),'new_bound_version',v_family.bound_version+1
    )
  );
  select coalesce(max(sequence),0)+1 into v_step_sequence
  from public.weekly_exceptional_orchestration_steps where orchestration_run_id=v_run.id;
  insert into public.weekly_exceptional_orchestration_steps(
    orchestration_run_id,sequence,step_kind,idempotency_key,
    allowlisted_owner_name,allowlisted_owner_signature,bounded_request_hash,
    before_state_fingerprint,bounded_owner_response_json,owner_response_hash,
    after_state_fingerprint,outcome,completed_at_utc
  ) values (
    v_run.id,v_step_sequence,'STAGE_C1_REQUEST',v_idempotency_key,
    'public.weekly_exceptional_pay_stage_c1_request_v1','jsonb->jsonb',
    v_request_body_hash,v_before_hash,
    pg_catalog.jsonb_build_object(
      'publication_request_id',v_publication.id,'generation_id',v_generation.id,
      'request_sha256',pg_catalog.encode(v_c1_request_hash,'hex')
    ),v_after_hash,v_after_hash,'COMPLETE',pg_catalog.statement_timestamp()
  );

  if p_request ? 'automatic_reconcile_selection_sha256' then
    -- The assertion reads the actual sealed complete vector and native rows.
    -- Any refusal rolls back this entire stage, including its unaccepted event.
    perform private.weekly_source_automatic_reconcile_certificate_v1(v_publication.id,v_actor_user_id,v_cycle.id);
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'outcome','STAGED','idempotent_replay',false,
    'family_id',v_family.id,'generation_id',v_generation.id,
    'approval_id',v_approval.id,'publication_request_id',v_publication.id,
    'request_sha256',pg_catalog.encode(v_publication.request_sha256,'hex'),
    'source_count',v_expected_source_count,
    'component_count',v_expected_component_count,
    'approved_pay_ex_vat',pg_catalog.to_char(v_total_pay,'FM9999999990.00'),
    'new_family_bound_version',v_family.bound_version+1,'state','READY'
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_SCOPE_INVALID' using errcode='55000';
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function private.weekly_source_bulk_stage_proof_v1(p_stage jsonb,p_financial_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_request jsonb:=p_stage->'bulk_signed_selection_proof'; v_context jsonb; v_selection jsonb; v_item jsonb; v_proof jsonb;
  v_count integer; v_original_clients uuid[]; v_run public.weekly_exceptional_orchestration_runs%rowtype;
begin
  if not private.weekly_exceptional_json_keys_exact_v1(v_request,array['expected_selection_sha256','expected_source_cas_sha256','incident_id','bulk_request_key'])
    or not(v_request ?& array['expected_selection_sha256','expected_source_cas_sha256','incident_id','bulk_request_key'])
    or coalesce(v_request->>'expected_selection_sha256','') !~ '^[0-9a-f]{64}$'
    or coalesce(v_request->>'expected_source_cas_sha256','') !~ '^[0-9a-f]{64}$'
    or coalesce(v_request->>'bulk_request_key','') !~ '^[A-Za-z0-9:_-]{16,120}$' then
    raise exception 'WEEKLY_SOURCE_BULK_STAGE_PROOF_INVALID' using errcode='22023'; end if;
  select * into strict v_run from public.weekly_exceptional_orchestration_runs where id=(p_stage->>'orchestration_run_id')::uuid;
  if v_run.request_kind not in ('APPROVE','AMEND') or v_run.state is distinct from 'RUNNING'
    or v_run.requested_by_user_id::text is distinct from p_stage->>'actor_user_id' then
    raise exception 'WEEKLY_SOURCE_BULK_STAGE_PROOF_INVALID' using errcode='55000'; end if;
  v_context:=private.weekly_source_bulk_own_stage_context_v1((p_stage->>'source_cycle_id')::uuid,(p_stage->>'actor_user_id')::uuid,
    v_request->>'bulk_request_key',v_request->>'expected_selection_sha256',v_request->>'expected_source_cas_sha256');
  if v_context is not null then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_ALREADY_STAGED' using errcode='55000'; end if;
  v_original_clients:=private.weekly_source_bulk_original_client_ids_v1((p_stage->>'source_cycle_id')::uuid,
    (p_stage->>'actor_user_id')::uuid,v_request->>'bulk_request_key');
  v_selection:=private.weekly_source_protect_all_signed_selection_v1((p_stage->>'source_cycle_id')::uuid,(p_stage->>'actor_user_id')::uuid,v_context,v_original_clients);
  if v_selection->>'selection_sha256' is distinct from v_request->>'expected_selection_sha256'
    or v_selection#>>'{source_cas,source_cas_sha256}' is distinct from v_request->>'expected_source_cas_sha256' then
    raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
  select count(*),jsonb_agg(value)->0 into v_count,v_item from jsonb_array_elements(v_selection->'eligible') value
    where value->>'incident_id'=v_request->>'incident_id';
  if v_count<>1 or v_item->>'work_event_id' is distinct from p_stage->>'work_event_id'
    or v_item->>'client_id' is distinct from p_stage->>'client_id'
    or v_item#>>'{claim,evidence_timesheet_id}' is distinct from p_stage->>'evidence_timesheet_id'
    or v_item->>'comparison_revision_id' is distinct from p_stage->>'current_comparison_revision_id'
    or (v_item#>>'{claim,work_date}')::date is distinct from (p_stage#>>'{protected_schedule,work_date}')::date
    or (v_item#>>'{claim,start_at_local}')::timestamp is distinct from (p_stage#>>'{protected_schedule,start_at_local}')::timestamp
    or (v_item#>>'{claim,end_at_local}')::timestamp is distinct from (p_stage#>>'{protected_schedule,end_at_local}')::timestamp
    or (v_item#>>'{claim,break_minutes}')::integer is distinct from (p_stage#>>'{protected_schedule,break_minutes}')::integer then
    raise exception 'WEEKLY_SOURCE_BULK_STAGE_PROOF_INVALID' using errcode='55000'; end if;
  v_proof:=jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_STAGED_PROOF_V1','actor_user_id',p_stage->>'actor_user_id',
    'source_cycle_id',p_stage->>'source_cycle_id','bulk_request_key',v_request->>'bulk_request_key',
    'selection_sha256',v_selection->>'selection_sha256','source_cas',v_selection->'source_cas',
    'eligible_claim',v_item,'financial_row_id',p_financial_id,
    'request_sha256',p_stage#>>'{c1_request,request_sha256}','target_snapshot_sha256',
    encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_TARGET_SNAPSHOT_V1',p_stage->'target_snapshot'),'hex'));
  return v_proof||jsonb_build_object('proof_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_STAGED_PROOF_V1',v_proof),'hex'));
end;
$function$;

-- Complete isolated source proposal. Root review and native proofs pending.
create or replace function public.weekly_source_protect_all_signed_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_actor uuid; v_cycle_id uuid; v_mode text; v_phase text; v_key text; v_object text; v_initial jsonb;
  v_cycle public.weekly_source_cycles%rowtype; v_group uuid; v_selection jsonb; v_context jsonb; v_stage jsonb;
  v_request public.weekly_exceptional_c1_publication_requests%rowtype; v_generation public.weekly_exceptional_pay_generations%rowtype;
  v_proof jsonb; v_own jsonb; v_lock jsonb; v_gate jsonb; v_result jsonb; v_response jsonb; v_refusal text;
  v_claim jsonb; v_remaining jsonb:='[]'::jsonb; v_done jsonb:='[]'::jsonb; v_current jsonb; v_count integer;
  v_round_key text; v_source_cas text; v_selection_sha text; v_completed boolean; v_initial_claim jsonb; v_original_clients uuid[];
begin
  perform private.weekly_source_query_require_service_v1();
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,array['actor_user_id','source_cycle_id','mode','phase',
    'bulk_request_key','expected_selection_sha256','staged'])
    or jsonb_typeof(p_request) is distinct from 'object' or octet_length(convert_to(p_request::text,'UTF8'))>262144 then
    raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end if;
  begin v_actor:=(p_request->>'actor_user_id')::uuid; v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
  exception when invalid_text_representation then raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end;
  v_mode:=p_request->>'mode'; v_phase:=coalesce(p_request->>'phase','ADMIT'); v_key:=p_request->>'bulk_request_key';
  select * into strict v_cycle from public.weekly_source_cycles where id=v_cycle_id;
  perform private.weekly_source_office_authority_v1(v_actor,'APPROVE_PROTECTED_PAY',v_cycle.source_group_id,null,v_cycle.finalisation_week_ending);
  if v_mode='PREVIEW' then
    if p_request ? 'staged' or p_request ? 'phase' then raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end if;
    v_selection:=private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,null);
    if not private.weekly_source_bulk_producer_ready_v1(v_cycle_id) then
      v_context:=private.weekly_source_protected_test_scope_assert_v1(v_cycle_id,v_actor,null,null);
      return jsonb_build_object('ok',true,'mode','PREVIEW','qualification',jsonb_build_object(
        'contract','WEEKLY_SOURCE_TEST_JOURNEY_PRESENTATION_V1','scope_id',v_context->>'scope_id',
        'scope_sha256',v_context->>'scope_sha256','expires_at_utc',v_context->>'expires_at_utc',
        'source_cycle_id',v_cycle_id,'actor_user_id',v_actor,'operational_ready',false,
        'allowed_action','PROTECT_ALL_SIGNED'))||v_selection;
    end if;
    return jsonb_build_object('ok',true,'mode','PREVIEW')||v_selection;
  end if;
  if v_mode is distinct from 'COMMIT' or v_phase not in ('ADMIT','ROUND','APPLY')
    or coalesce(v_key,'') !~ '^[A-Za-z0-9:_-]{16,120}$' then
    raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end if;
  v_object:=v_cycle_id::text||':'||v_actor::text||':'||v_key;
  select audit.after_json into v_initial from public.audit_events audit
    where audit.object_type='weekly_source_bulk_signed_command' and audit.object_id_text=v_object
      and audit.action='WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED' and audit.event_sequence_is_authoritative
    order by audit.event_sequence desc limit 1;
  if v_phase='ADMIT' then
    -- No family/gate call is made in this phase. The original cycle mutex owns
    -- admission idempotence, and is released before Worker preparation starts.
    perform 1 from public.weekly_source_groups where id=v_cycle.source_group_id for share;
    v_group:=v_cycle.source_group_id;
    select * into strict v_cycle from public.weekly_source_cycles where id=v_cycle_id for update;
    if v_cycle.source_group_id is distinct from v_group then
      raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
    select audit.after_json into v_initial from public.audit_events audit
      where audit.object_type='weekly_source_bulk_signed_command' and audit.object_id_text=v_object
        and audit.action='WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED' and audit.event_sequence_is_authoritative
      order by audit.event_sequence desc limit 1;
    if v_initial is not null then
      if v_initial#>>'{initial_selection,selection_sha256}' is distinct from p_request->>'expected_selection_sha256' then
        raise exception 'WEEKLY_SOURCE_BULK_REPLAY_CONFLICT' using errcode='23505'; end if;
      return jsonb_build_object('ok',true,'phase','ADMITTED','idempotent_replay',true,'initial_selection',v_initial->'initial_selection');
    end if;
    v_selection:=private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,null);
    if v_selection->>'selection_sha256' is distinct from p_request->>'expected_selection_sha256' then
      raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
    v_initial:=jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_COMMAND_V1','actor_user_id',v_actor,
      'source_cycle_id',v_cycle_id,'bulk_request_key',v_key,'initial_selection',v_selection);
    perform public._audit_insert('weekly_source_bulk_signed_command',v_object,'WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED',
      null,v_initial,'Protect signed MyTMS submissions',v_actor);
    return jsonb_build_object('ok',true,'phase','ADMITTED','idempotent_replay',false,'initial_selection',v_selection);
  end if;
  if v_initial is null then raise exception 'WEEKLY_SOURCE_BULK_COMMAND_NOT_ADMITTED' using errcode='55000'; end if;
  v_original_clients:=private.weekly_source_bulk_original_client_ids_v1(v_cycle_id,v_actor,v_key);
  if v_phase='ROUND' then
    -- Resume the exact pending generation before deriving another round.
    select generation.complete_next_vector_json->'bulk_signed_selection_proof' into v_proof
      from public.weekly_exceptional_c1_publication_requests request
      join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id
      where generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,bulk_request_key}'=v_key
        and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,actor_user_id}'=v_actor::text
        and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,source_cycle_id}'=v_cycle_id::text
        and request.state='READY' and generation.lifecycle_state='PENDING_C1'
      order by request.id limit 1;
    if v_proof is not null then
      v_context:=private.weekly_source_bulk_own_stage_context_v1(v_cycle_id,v_actor,v_key,
        v_proof->>'selection_sha256',v_proof#>>'{source_cas,source_cas_sha256}');
    end if;
    v_selection:=private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,v_context,v_original_clients);
    if v_selection#>>'{source_cas,source_cas_sha256}' is distinct from v_initial#>>'{initial_selection,source_cas,source_cas_sha256}' then
      raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
    for v_initial_claim in select value from jsonb_array_elements(v_initial#>'{initial_selection,eligible}') loop
      -- A completed disposition is accepted only from this command's actual
      -- immutable native stage proof and local completion receipt.
      select exists(select 1 from public.weekly_exceptional_c1_publication_requests request
        join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id
        join private.weekly_source_local_protected_decision_receipts receipt on receipt.publication_request_id=request.id
          and receipt.actor_user_id=v_actor and receipt.request_sha256=request.request_sha256 and receipt.state in ('COMPLETE','PENDING_FREEZE')
        where generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,bulk_request_key}'=v_key
          and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,actor_user_id}'=v_actor::text
          and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,source_cycle_id}'=v_cycle_id::text
          and generation.complete_next_vector_json#>'{bulk_signed_selection_proof,eligible_claim}'=v_initial_claim
          and private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',generation.complete_next_vector_json)=generation.complete_next_vector_hash
          and receipt.result_json->>'ok'='true') into v_completed;
      if v_completed then v_done:=v_done||jsonb_build_array(v_initial_claim->'work_event_id'); continue; end if;
      select count(*),jsonb_agg(value)->0 into v_count,v_current from jsonb_array_elements(v_selection->'eligible') value
        where value->>'work_event_id'=v_initial_claim->>'work_event_id';
      if v_count<>1 or v_current is distinct from v_initial_claim then
        raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLAIM_CHANGED' using errcode='40001'; end if;
      v_remaining:=v_remaining||jsonb_build_array(v_current);
    end loop;
    return jsonb_build_object('ok',true,'phase','ROUND','selection',v_selection,'remaining',v_remaining,'completed_work_event_ids',v_done,
      'pending_stages',coalesce(v_context->'exclusions','[]'::jsonb),'max_stages_per_round',1);
  end if;
  if jsonb_typeof(p_request->'staged') is distinct from 'array' or jsonb_array_length(p_request->'staged')<>1 then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_INVALID' using errcode='22023'; end if;
  v_stage:=p_request#>'{staged,0}';
  if not private.weekly_exceptional_json_keys_exact_v1(v_stage,array['publication_request_id','request_sha256'])
    or not(v_stage ?& array['publication_request_id','request_sha256']) then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_INVALID' using errcode='22023'; end if;
  select * into strict v_request from public.weekly_exceptional_c1_publication_requests where id=(v_stage->>'publication_request_id')::uuid;
  select * into strict v_generation from public.weekly_exceptional_pay_generations where id=v_request.generation_id;
  v_proof:=v_generation.complete_next_vector_json->'bulk_signed_selection_proof';
  v_selection_sha:=v_proof->>'selection_sha256'; v_source_cas:=v_proof#>>'{source_cas,source_cas_sha256}';
  v_round_key:=v_request.id::text;
  -- Exact audit replay precedes mutable freshness checks and locks.
  select audit.after_json into v_response from public.audit_events audit where audit.object_type='weekly_source_bulk_signed_command'
    and audit.object_id_text=v_object and audit.action='WEEKLY_SOURCE_BULK_SIGNED_ROUND_COMPLETED'
    and audit.after_json->>'publication_request_id'=v_round_key and audit.event_sequence_is_authoritative
    order by audit.event_sequence desc limit 1;
  if v_response is not null then
    if v_response->>'request_sha256' is distinct from v_stage->>'request_sha256' then
      raise exception 'WEEKLY_SOURCE_BULK_REPLAY_CONFLICT' using errcode='23505'; end if;
    return v_response||jsonb_build_object('idempotent_replay',true);
  end if;
  -- Complete round has one real family. Every Candidate gate comes first;
  -- native I-1 still receives the complete round set and owns its raw order.
  perform private.weekly_source_pay_query_admit_v2();
  v_gate:=private.weekly_source_candidate_serial_gate_v1(v_request.candidate_id,'WORKBENCH_CANDIDATE_ENTITLEMENT_PUBLICATION',
    v_request.id,'WEEKLY_SOURCE_ENTITLEMENT_PUBLICATION');
  if v_gate->>'ok' is distinct from 'true' then return v_gate||jsonb_build_object('phase','BLOCKED','accepted',false); end if;
  if not exists(select 1 from public.timesheets sheet join public.contracts contract on contract.id=sheet.contract_id
    where sheet.timesheet_id=v_request.root_timesheet_id and contract.candidate_id=v_request.candidate_id) then
    raise exception 'WEEKLY_SOURCE_BULK_ROOT_CANDIDATE_MISMATCH' using errcode='55000'; end if;
  v_lock:=private.weekly_source_lock_family_rows_v1(array[v_request.root_timesheet_id],null);
  if v_lock->>'ok' is distinct from 'true' then return v_lock||jsonb_build_object('phase','BLOCKED','accepted',false); end if;
  v_group:=v_cycle.source_group_id;
  perform 1 from public.weekly_source_groups where id=v_group and active for update;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_cycle_id for update;
  if v_cycle.source_group_id is distinct from v_group then raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
  v_own:=private.weekly_source_bulk_own_stage_v1(v_request.id,v_actor,v_cycle_id,v_key,v_selection_sha,v_source_cas);
  if v_request.request_sha256 is distinct from private.weekly_exceptional_hex_sha256_v1(v_stage->>'request_sha256')
    or not exists(select 1 from jsonb_array_elements(v_initial#>'{initial_selection,eligible}') original
      where original=v_proof->'eligible_claim') then
    raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLAIM_CHANGED' using errcode='40001'; end if;
  v_context:=private.weekly_source_bulk_own_stage_context_v1(v_cycle_id,v_actor,v_key,v_selection_sha,v_source_cas);
  if jsonb_array_length(v_context->'exclusions') is distinct from 1
    or v_context#>>'{exclusions,0,publication_request_id}' is distinct from v_request.id::text then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_INVALID' using errcode='55000'; end if;
  v_selection:=private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,v_context,v_original_clients);
  if v_selection->>'selection_sha256' is distinct from v_selection_sha
    or v_source_cas is distinct from v_initial#>>'{initial_selection,source_cas,source_cas_sha256}' then
    raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
  begin
    v_result:=public.weekly_exceptional_pay_complete_local_v1(jsonb_build_object('schema_version','WEEKLY_PROTECTED_LOCAL_COMPLETE_V1',
      'actor_user_id',v_actor,'publication_request_id',v_request.id,'expected_request_sha256',v_stage->>'request_sha256',
      'idempotency_key',(select idempotency_key from public.weekly_exceptional_orchestration_runs where id=v_request.orchestration_run_id)||':local-complete'));
    if v_result->>'ok' is distinct from 'true' or v_result->>'outcome' not in ('PUBLISHED','SAVED_PENDING_FREEZE') then
      raise exception 'WEEKLY_SOURCE_BULK_NATIVE_COMPLETE_REFUSED' using errcode='55000'; end if;
  exception when others then
    v_refusal:=coalesce(substring(sqlerrm from '^[A-Z][A-Z0-9_]{0,119}$'),'PROTECTION_REFUSED');
    return jsonb_build_object('ok',false,'phase','PARTIAL','publication_request_id',v_request.id,
      'work_event_id',v_proof#>'{eligible_claim,work_event_id}','code',v_refusal,'completed',false,'retryable',true);
  end;
  v_response:=jsonb_build_object('ok',true,'phase','ROUND_COMPLETED','publication_request_id',v_request.id,
    'request_sha256',v_stage->>'request_sha256','work_event_id',v_proof#>'{eligible_claim,work_event_id}',
    'native_result',v_result,'whole_command_atomic',false);
  perform public._audit_insert('weekly_source_bulk_signed_command',v_object,'WEEKLY_SOURCE_BULK_SIGNED_ROUND_COMPLETED',
    null,v_response,'Protected from the signed MyTMS submission',v_actor);
  return v_response;
end;
$function$;

-- All operational callers use this full certificate. V1-native-only and V2
-- prerequisite certificates cannot enter activation, receipt or readiness.
create or replace function private.weekly_source_protected_operational_certificate_assert_v1(
  p_q jsonb,p_group_id uuid,p_from date,p_to date,p_expected_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare q jsonb:=p_q; g public.weekly_source_groups%rowtype; r private.cloudtms_database_releases%rowtype;
  executed private.cloudtms_database_releases%rowtype; native jsonb; row_value jsonb; closure jsonb;
  needed text[]; keys text[]; remote_needed text[]:=array['CLIENT_HTTP','OFFICE_UI','MYTMS_PHONE']; origin text; n integer;
begin
  select * into strict g from public.weekly_source_groups where id=p_group_id and active and source_family='ROSTER' and environment='TEST';
  select * into strict r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if current_database()<>'cloudtms_test_clone' or r.status<>'VERIFIED' or r.completed_at_utc is null
    or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or r.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or not private.weekly_source_qualification_closed_object_v1(q,array['schema_version','phase','release_id','git_commit','contract_sha256',
      'agency_id','environment','source_group_id','effective_from_week_ending','effective_to_week_ending','capabilities',
      'native_execution_qualification','remote_gate_receipts','test_setup_closure','source_equivalence','qualification_sha256'])
    or q->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_OPERATIONAL_QUALIFICATION_V1'
    or q->>'phase' is distinct from 'ALL_PRE_SWITCH_GATES_QUALIFIED'
    or q->>'release_id' is distinct from r.release_id or q->>'git_commit' is distinct from r.git_commit
    or q->>'contract_sha256' is distinct from r.installed_contract_sha256 or q->>'agency_id' is distinct from g.agency_id::text
    or q->>'source_group_id' is distinct from g.id::text or q->>'environment' is distinct from g.environment
    or q->>'effective_from_week_ending' is distinct from p_from::text or q->>'effective_to_week_ending' is distinct from p_to::text
    or coalesce(p_expected_sha256,'') !~ '^[0-9a-f]{64}$' or q->>'qualification_sha256' is distinct from p_expected_sha256
    or q->>'qualification_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_PROTECTED_CAPABILITY_OPERATIONAL_QUALIFICATION_V1',q-'qualification_sha256'),'hex')
    or q->'capabilities' not in ('["BULK_SIGNED"]'::jsonb,'["AUTOMATIC_RECONCILE","BULK_SIGNED"]'::jsonb) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  native:=q->'native_execution_qualification';closure:=q->'test_setup_closure';
  select * into strict executed from private.cloudtms_database_releases where release_id=native->>'release_id';
  if executed.release_id=r.release_id or executed.status<>'VERIFIED' or executed.completed_at_utc is null
    or executed.git_commit is distinct from native->>'git_commit'
    or executed.installed_contract_sha256 is distinct from executed.repository_contract_sha256
    or executed.installed_contract_sha256 is distinct from r.installed_contract_sha256
    or executed.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}'
      is distinct from r.evidence_json#>>'{weekly_source_protected_qualification_catalogue,jsonb_sha256}'
    or private.weekly_source_protected_qualification_release_v1()->>'release_id' is distinct from r.release_id
    or not private.weekly_source_qualification_closed_object_v1(native,array['schema_version','release_id','git_commit','contract_sha256','agency_id','environment',
      'source_group_id','effective_from_week_ending','effective_to_week_ending','capabilities','gate_receipts','qualification_sha256'])
    or native->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1'
    or native->>'contract_sha256' is distinct from r.installed_contract_sha256
    or native->>'agency_id' is distinct from g.agency_id::text or native->>'source_group_id' is distinct from g.id::text
    or native->>'environment' is distinct from 'TEST' or native->>'effective_from_week_ending' is distinct from p_from::text
    or native->>'effective_to_week_ending' is distinct from p_to::text or native->'capabilities' is distinct from q->'capabilities'
    or native->>'qualification_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_PROTECTED_CAPABILITY_QUALIFICATION_V1',native-'qualification_sha256'),'hex') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  needed:=array['SOURCE_CAS_NATIVE','NATIVE_PROTECTION','SECURITY','LEGACY_PAY','NEXT_PAY','CLIENT_API','DOCUMENT','OWN_STAGE_CAS','SOURCE_ROUTING'];
  if q->'capabilities' @> '["AUTOMATIC_RECONCILE"]'::jsonb then needed:=array_append(needed,'AUTOMATIC_COMPONENT_DELTA'); end if;
  if jsonb_typeof(native->'gate_receipts') is distinct from 'array' or jsonb_array_length(native->'gate_receipts')<>cardinality(needed)
    or (select count(distinct value->>'gate') from jsonb_array_elements(native->'gate_receipts') value)<>cardinality(needed) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  for row_value in select value from jsonb_array_elements(native->'gate_receipts') value loop
    if not private.weekly_source_qualification_closed_object_v1(row_value,array['gate','status','execution','database','receipt_id','receipt_sha256',
        'source_commit','contract_sha256','source_group_id','agency_id','environment'])
      or not(coalesce(row_value->>'gate','')=any(needed)) or row_value->>'status' is distinct from 'PASS'
      or row_value->>'execution' is distinct from 'AGENCY_TEST_NATIVE' or row_value->>'database' is distinct from current_database()
      or row_value->>'source_commit' is distinct from executed.git_commit or row_value->>'contract_sha256' is distinct from executed.installed_contract_sha256
      or row_value->>'source_group_id' is distinct from g.id::text or row_value->>'agency_id' is distinct from g.agency_id::text
      or row_value->>'environment' is distinct from 'TEST' or nullif(row_value->>'receipt_id','') is null
      or coalesce(row_value->>'receipt_sha256','') !~ '^[0-9a-f]{64}$' then
      raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  end loop;
  if not private.weekly_source_qualification_closed_object_v1(closure,array['scope_id','scope_sha256','setup_authorization_sha256',
      'original_census_sha256','actor_user_id','source_cycle_id','week_ending','execution_release_id','execution_source_commit',
      'execution_contract_sha256','closure_audit_id','closure_audit_sha256','state','closed_at_utc','all_assignments_disabled','all_operational_producers_false'])
    or exists(select 1 from unnest(array['scope_id','actor_user_id','source_cycle_id','closure_audit_id']) k
      where coalesce(closure->>k,'') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
    or exists(select 1 from unnest(array['scope_sha256','setup_authorization_sha256','original_census_sha256','closure_audit_sha256']) k
      where coalesce(closure->>k,'') !~ '^[0-9a-f]{64}$')
    or coalesce(closure->>'week_ending','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    or coalesce(closure->>'closed_at_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
    or closure->>'state' is distinct from 'CLOSED' or closure->'all_assignments_disabled' is distinct from 'true'::jsonb
    or closure->'all_operational_producers_false' is distinct from 'true'::jsonb
    or closure->>'execution_release_id' is distinct from executed.release_id
    or closure->>'execution_source_commit' is distinct from executed.git_commit
    or closure->>'execution_contract_sha256' is distinct from executed.installed_contract_sha256
    or (closure->>'week_ending')::date<p_from or (p_to is not null and (closure->>'week_ending')::date>p_to)
    or not exists(select 1 from public.audit_events a where a.id=(closure->>'closure_audit_id')::uuid
      and a.object_type='weekly_source_protected_test_journey' and a.object_id_text=closure->>'scope_id'
      and a.action='WEEKLY_SOURCE_TEST_JOURNEY_CLOSED' and a.event_sequence_is_authoritative
      and a.after_json=closure-'closure_audit_id'-'closure_audit_sha256'
      and encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_TEST_JOURNEY_CLOSED_V1',a.after_json),'hex')=closure->>'closure_audit_sha256') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  if jsonb_typeof(q->'remote_gate_receipts') is distinct from 'array' or jsonb_array_length(q->'remote_gate_receipts')<>3
    or (select count(distinct value->>'gate') from jsonb_array_elements(q->'remote_gate_receipts') value)<>3 then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  for row_value in select value from jsonb_array_elements(q->'remote_gate_receipts') value loop
    origin:=case row_value->>'gate' when 'CLIENT_HTTP' then 'AUTHENTICATED_DEPLOYED_HTTP'
      when 'OFFICE_UI' then 'DEPLOYED_OFFICE_BROWSER_UI' when 'MYTMS_PHONE' then 'PHYSICAL_TESTFLIGHT_MYTMS_PHONE' end;
    keys:=case row_value->>'gate'
      when 'CLIENT_HTTP' then array['real_authenticated_session','trusted_actor_injected','closed_browser_payload','native_preview_commit_retry',
        'native_source_cas_error_order','foreign_actor_and_scope_refused','operational_readiness_false']
      when 'OFFICE_UI' then array['actual_deployed_bundle','deep_link_scope','actual_preview_and_confirmation','native_partial_retry_display',
        'unauthorised_controls_absent','operational_readiness_false']
      when 'MYTMS_PHONE' then array['actual_installed_test_build','actual_candidate_authenticated_session','genuine_signed_submission_bytes',
        'native_signature_authority','actual_approved_hours_display','actual_document_bytes_and_hash','operational_readiness_false'] end;
    if not private.weekly_source_qualification_closed_object_v1(row_value,array['schema_version','gate','origin','execution_release_id',
        'execution_source_commit','execution_contract_sha256','environment','database','agency_id','source_group_id','source_cycle_id',
        'actor_user_id','week_ending','scope_id','scope_sha256','original_census_sha256','server_request_ids','server_trace_sha256',
        'native_result_receipts_sha256','capture_sha256','deployments','assertions','receipt_id','receipt_sha256'])
      or origin is null or row_value->>'origin' is distinct from origin
      or row_value->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_REMOTE_GATE_RECEIPT_V1'
      or row_value->>'execution_release_id' is distinct from executed.release_id or row_value->>'execution_source_commit' is distinct from executed.git_commit
      or row_value->>'execution_contract_sha256' is distinct from executed.installed_contract_sha256
      or row_value->>'source_group_id' is distinct from g.id::text or row_value->>'agency_id' is distinct from g.agency_id::text
      or row_value->>'environment' is distinct from 'TEST' or row_value->>'database' is distinct from current_database()
      or exists(select 1 from unnest(array['source_cycle_id','actor_user_id','week_ending','scope_id','scope_sha256','original_census_sha256']) k
        where row_value->>k is distinct from closure->>k)
      or not private.weekly_source_qualification_closed_object_v1(row_value->'assertions',keys)
      or exists(select 1 from unnest(keys) k where row_value#>array['assertions',k] is distinct from 'true'::jsonb)
      or exists(select 1 from unnest(array['receipt_sha256','server_trace_sha256','native_result_receipts_sha256','capture_sha256']) k
        where coalesce(row_value->>k,'') !~ '^[0-9a-f]{64}$')
      or coalesce(row_value->>'receipt_id','') !~ '^[A-Za-z0-9_./:@-]{1,256}$'
      or jsonb_typeof(row_value->'server_request_ids') is distinct from 'array'
      or jsonb_array_length(row_value->'server_request_ids') not between 1 and 100
      or (select count(distinct value) from jsonb_array_elements(row_value->'server_request_ids') value)
        <>jsonb_array_length(row_value->'server_request_ids')
      or exists(select 1 from jsonb_array_elements(row_value->'server_request_ids') request_id
        where jsonb_typeof(request_id)<>'string' or request_id#>>'{}' !~ '^[A-Za-z0-9:_-]{1,128}$')
      or not private.weekly_source_qualification_closed_object_v1(row_value->'deployments',array['worker_script','worker_version_id',
        'worker_source_commit','office_source_commit','office_bundle_sha256','mytms_source_commit','mytms_build_id',
        'mytms_bundle_identifier','mytms_build_artifact_sha256'])
      or coalesce(row_value#>>'{deployments,worker_version_id}','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or exists(select 1 from unnest(array['office_source_commit','mytms_source_commit']) k
        where coalesce(row_value#>>array['deployments',k],'') !~ '^[0-9a-f]{40}$')
      or exists(select 1 from unnest(array['office_bundle_sha256','mytms_build_artifact_sha256']) k
        where coalesce(row_value#>>array['deployments',k],'') !~ '^[0-9a-f]{64}$')
      or nullif(row_value#>>'{deployments,mytms_build_id}','') is null
      or row_value#>>'{deployments,worker_script}' is distinct from 'test-cloudtms-backend'
      or row_value#>>'{deployments,worker_source_commit}' is distinct from executed.git_commit
      or row_value#>>'{deployments,mytms_bundle_identifier}' is distinct from 'net.cloudtms.mytms.test' then
      raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  end loop;
  if (select count(distinct value->'deployments') from jsonb_array_elements(q->'remote_gate_receipts') value)<>1 then
    raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000'; end if;
  perform private.weekly_source_protected_execution_tree_assert_v2(q->'source_equivalence',executed.git_commit,r.git_commit);
  return q;
exception when no_data_found or too_many_rows or invalid_text_representation or datetime_field_overflow then
  raise exception 'WEEKLY_SOURCE_PROTECTED_OPERATIONAL_GATES_REQUIRED' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_protected_execution_tree_assert_v2(p_proof jsonb,p_execution_commit text,p_installation_commit text)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare file jsonb;
begin
  -- PostgreSQL cannot read Git objects. This asserts the closed receipt DTO;
  -- the protected managed writer MUST remeasure the literal complete Git tree.
  -- A caller JSON/hash assertion is never source equivalence authority.
  if not private.weekly_source_qualification_closed_object_v1(p_proof,array['schema_version','execution_source_commit','installation_source_commit',
      'inventory_schema','files','receipt_bindings','source_equivalence_sha256'])
    or p_proof->>'schema_version' is distinct from 'WEEKLY_SOURCE_COMMITTED_EXECUTION_TREE_EQUIVALENCE_V2'
    or p_proof->>'inventory_schema' is distinct from 'WEEKLY_SOURCE_NATIVE_RELEASE_TOOLCHAIN_VERIFIER_INVENTORY_V2'
    or p_proof->>'execution_source_commit' is distinct from p_execution_commit
    or p_proof->>'installation_source_commit' is distinct from p_installation_commit
    or p_proof->>'source_equivalence_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_COMMITTED_EXECUTION_TREE_EQUIVALENCE_V2',p_proof-'source_equivalence_sha256'),'hex')
    or jsonb_typeof(p_proof->'files') is distinct from 'array' or jsonb_array_length(p_proof->'files')=0
    or jsonb_typeof(p_proof->'receipt_bindings') is distinct from 'array'
    or (select count(distinct value->>'path') from jsonb_array_elements(p_proof->'files') value)<>jsonb_array_length(p_proof->'files')
    or exists(select 1 from unnest(array['.node-version','.gitattributes','osv-scanner.toml','.github/workflows/database-release.yml','supabase/release/export_contract.sql',
      'supabase/release/current-release.json','supabase/release/current-contract.json','scripts/cloudtms-db-release.mjs']) required_path
      where not exists(select 1 from jsonb_array_elements(p_proof->'files') item where item->>'path'=required_path)) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_EXECUTION_TREE_CHANGED' using errcode='55000'; end if;
  for file in select value from jsonb_array_elements(p_proof->'files') value loop
    if not private.weekly_source_qualification_closed_object_v1(file,array['path','git_mode','git_type','execution_blob_oid','installation_blob_oid',
        'execution_sha256','installation_sha256','comparison','comparison_sha256'])
      or nullif(file->>'path','') is null or file->>'git_mode' not in ('100644','100755') or file->>'git_type' is distinct from 'blob'
      or exists(select 1 from unnest(array['execution_sha256','installation_sha256','comparison_sha256']) k
        where coalesce(file->>k,'') !~ '^[0-9a-f]{64}$')
      or exists(select 1 from unnest(array['execution_blob_oid','installation_blob_oid']) k where coalesce(file->>k,'') !~ '^[0-9a-f]{40}$')
      or (file->>'path'<>'supabase/release/current-release.json' and
        (file->>'comparison' is distinct from 'EXACT_GIT_OBJECT' or file->>'execution_blob_oid' is distinct from file->>'installation_blob_oid'
          or file->>'execution_sha256' is distinct from file->>'installation_sha256'))
      or (file->>'path'='supabase/release/current-release.json'
        and file->>'comparison' is distinct from 'RELEASE_AUTHORITY_EXCEPT_CLOSED_RECEIPT_DESCRIPTORS') then
      raise exception 'WEEKLY_SOURCE_PROTECTED_EXECUTION_TREE_CHANGED' using errcode='55000'; end if;
  end loop;
end;
$function$;

-- Source proposal: explicit, expiring, fixture-only TEST admission in the
-- EXISTING audit log. No assignment/readiness mutation, table or service grant.
-- Only the existing controlled feature setup RPC calls the write owner.
create or replace function private.weekly_source_protected_test_authorization_v1(p_authorization_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare r private.cloudtms_database_releases%rowtype; auth jsonb; n integer;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict r from private.cloudtms_database_releases order by started_at_utc desc,release_id desc limit 1;
  if current_database()<>'cloudtms_test_clone' or r.status<>'VERIFIED' or r.completed_at_utc is null
    or r.installed_contract_sha256 is distinct from r.repository_contract_sha256
    or r.evidence_json#>>'{managed_release,environment}' is distinct from 'TEST'
    or r.evidence_json#>>'{managed_release,expected_database}' is distinct from current_database()
    or jsonb_typeof(r.evidence_json->'weekly_source_protected_test_setup_authorizations') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_AUTHORIZATION_REQUIRED' using errcode='55000'; end if;
  select count(*),jsonb_agg(value)->0 into n,auth
    from jsonb_array_elements(r.evidence_json->'weekly_source_protected_test_setup_authorizations') value
    where value->>'authorization_id'=p_authorization_id::text;
  if n<>1 or not private.weekly_source_qualification_closed_object_v1(auth,array['schema_version','authorization_id','scope_id',
      'release_id','source_commit','contract_sha256','agency_id','source_group_id','source_cycle_id','setup_actor_user_id',
      'journey_actor_user_id','week_ending','expires_at_utc','fixture_namespace','fixture_manifest','original_census',
      'prerequisite_qualification_sha256','capabilities','authorization_sha256'])
    or auth->>'schema_version' is distinct from 'WEEKLY_SOURCE_PROTECTED_TEST_SETUP_AUTHORIZATION_V1'
    or auth->>'release_id' is distinct from r.release_id or auth->>'source_commit' is distinct from r.git_commit
    or auth->>'contract_sha256' is distinct from r.installed_contract_sha256
    or auth->'capabilities' is distinct from '["BULK_SIGNED"]'::jsonb
    or auth->>'fixture_namespace' is distinct from 'WSQ_TEST_'
    or auth->>'authorization_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_PROTECTED_TEST_SETUP_AUTHORIZATION_V1',auth-'authorization_sha256'),'hex') then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_AUTHORIZATION_REQUIRED' using errcode='55000'; end if;
  -- This is an observed latest installed release, not function-presence READY.
  if private.weekly_source_protected_qualification_release_v1()->>'release_id' is distinct from r.release_id then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_INSTALLED_RELEASE_REQUIRED' using errcode='55000'; end if;
  return auth;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_AUTHORIZATION_REQUIRED' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_protected_test_scope_assert_v1(
  p_cycle_id uuid,p_actor_user_id uuid,p_original_client_ids uuid[],p_work_event_id uuid default null
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare lease jsonb; auth jsonb; n integer; c public.weekly_source_cycles%rowtype;
  g public.weekly_source_groups%rowtype; clients uuid[]; expected jsonb; item jsonb; actual jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER' and environment='TEST';
  perform private.weekly_source_office_authority_v1(p_actor_user_id,'APPROVE_PROTECTED_PAY',g.id,null,c.finalisation_week_ending);
  select count(*),jsonb_agg(a.after_json)->0 into n,lease from public.audit_events a
    where a.object_type='weekly_source_protected_test_journey' and a.action='WEEKLY_SOURCE_TEST_JOURNEY_OPENED'
      and a.event_sequence_is_authoritative and a.after_json->>'source_cycle_id'=c.id::text
      and a.after_json->>'journey_actor_user_id'=p_actor_user_id::text
      and not exists(select 1 from public.audit_events closed where closed.object_type=a.object_type
        and closed.object_id_text=a.object_id_text and closed.event_sequence_is_authoritative
        and closed.action in ('WEEKLY_SOURCE_TEST_JOURNEY_CLOSED','WEEKLY_SOURCE_TEST_JOURNEY_REVOKED'));
  if n<>1 or lease->>'contract' is distinct from 'WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_V1'
    or lease->'operational_ready' is distinct from 'false'::jsonb
    or lease->>'scope_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_V1',lease-'scope_sha256'),'hex') then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_UNAVAILABLE' using errcode='55000'; end if;
  auth:=private.weekly_source_protected_test_authorization_v1((lease->>'authorization_id')::uuid);
  if lease->>'authorization_sha256' is distinct from auth->>'authorization_sha256'
    or lease->>'scope_id' is distinct from auth->>'scope_id'
    or lease->>'source_cycle_id' is distinct from auth->>'source_cycle_id'
    or lease->>'journey_actor_user_id' is distinct from auth->>'journey_actor_user_id'
    or lease->>'week_ending' is distinct from c.finalisation_week_ending::text
    or auth->>'agency_id' is distinct from g.agency_id::text or auth->>'source_group_id' is distinct from g.id::text
    or clock_timestamp()>=(auth->>'expires_at_utc')::timestamptz
    or (clock_timestamp() at time zone 'Europe/London')::date is distinct from (lease->>'opened_local_date')::date
    or exists(select 1 from public.weekly_source_group_rule_assignments a where a.source_group_id=g.id and a.feature_enabled
      and c.finalisation_week_ending between a.effective_from_week_ending and coalesce(a.effective_to_week_ending,'infinity'::date))
    or private.weekly_source_bulk_producer_ready_v1(c.id) or private.weekly_source_automatic_reconcile_producer_ready_v1(c.id) then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_UNAVAILABLE' using errcode='55000'; end if;
  select array_agg(value::uuid order by value::uuid) into clients
    from jsonb_array_elements_text(auth#>'{original_census,original_client_ids}') value;
  if p_original_client_ids is not null and to_jsonb(p_original_client_ids) is distinct from to_jsonb(clients) then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_ORIGINAL_CENSUS_CHANGED' using errcode='40001'; end if;
  if private.weekly_source_bulk_source_cas_v1(c.id,clients) is distinct from auth#>'{original_census,source_cas}' then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_SOURCE_CHANGED' using errcode='40001'; end if;
  for item in select value from jsonb_array_elements(auth#>'{original_census,original_root_identities}') value loop
    select jsonb_build_object('timesheet_id',s.timesheet_id,'booking_id',s.booking_id,'contract_id',k.id,
      'candidate_id',k.candidate_id,'client_id',k.client_id) into actual
      from public.timesheets s join public.contracts k on k.id=s.contract_id
      where s.timesheet_id=(item->>'timesheet_id')::uuid and (s.client_id is null or s.client_id=k.client_id);
    if actual is distinct from item then raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_ORIGINAL_ROOT_CHANGED' using errcode='40001'; end if;
  end loop;
  if p_work_event_id is not null and not exists(select 1 from jsonb_array_elements(auth#>'{original_census,original_items}') item
    where item->>'work_event_id'=p_work_event_id::text) then
    raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_FOREIGN_EVENT_REFUSED' using errcode='42501'; end if;
  return lease||jsonb_build_object('original_census',auth->'original_census','capabilities',auth->'capabilities');
exception when no_data_found or too_many_rows or invalid_text_representation or datetime_field_overflow then
  raise exception 'WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_UNAVAILABLE' using errcode='55000';
end;
$function$;

-- This write helper is not a new public/service RPC. The existing admin-only
-- feature setup owner dispatches OPEN/CLOSE/REVOKE, always before feature writes.
create or replace function private.weekly_source_protected_test_setup_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare actor uuid; auth jsonb; lease jsonb; result jsonb; c public.weekly_source_cycles%rowtype;
  g public.weekly_source_groups%rowtype; action text; manifest jsonb; census jsonb; n integer; q jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if not private.weekly_source_qualification_closed_object_v1(p_request,array['actor_user_id','agency_id','environment','qualification_action',
      'authorization_id','expected_authorization_sha256','reason'])
    or not(p_request ?& array['actor_user_id','agency_id','environment','qualification_action','authorization_id','expected_authorization_sha256','reason'])
    or char_length(coalesce(p_request->>'reason','')) not between 1 and 500 then
    raise exception 'WEEKLY_SOURCE_TEST_SETUP_REQUEST_INVALID' using errcode='22023'; end if;
  actor:=(p_request->>'actor_user_id')::uuid;action:=p_request->>'qualification_action';
  perform private._weekly_source_settings_require_admin_v1(actor);
  if private._weekly_source_settings_deployment_v1((p_request->>'agency_id')::uuid,p_request->>'environment')<>'TEST'
    or action not in ('OPEN','CLOSE','REVOKE') then raise exception 'WEEKLY_SOURCE_TEST_SETUP_REQUEST_INVALID' using errcode='22023'; end if;
  auth:=private.weekly_source_protected_test_authorization_v1((p_request->>'authorization_id')::uuid);
  if auth->>'authorization_sha256' is distinct from p_request->>'expected_authorization_sha256'
    or auth->>'setup_actor_user_id' is distinct from actor::text or auth->>'agency_id' is distinct from p_request->>'agency_id' then
    raise exception 'WEEKLY_SOURCE_TEST_SETUP_AUTHORIZATION_CHANGED' using errcode='40001'; end if;
  perform pg_advisory_xact_lock(hashtextextended('weekly-source-test-journey:'||(auth->>'scope_id'),0));
  select * into strict c from public.weekly_source_cycles where id=(auth->>'source_cycle_id')::uuid;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and id=(auth->>'source_group_id')::uuid
    and active and source_family='ROSTER' and environment='TEST';
  if g.code is distinct from auth#>>'{fixture_manifest,group_code}' or g.code !~ '^WSQ_TEST_[A-Z0-9_]+$'
    or g.agency_id::text is distinct from auth->>'agency_id'
    or c.finalisation_week_ending::text is distinct from auth->>'week_ending' then
    raise exception 'WEEKLY_SOURCE_TEST_SETUP_FIXTURE_SCOPE_INVALID' using errcode='42501'; end if;
  select count(*),jsonb_agg(a.after_json)->0 into n,lease from public.audit_events a
    where a.object_type='weekly_source_protected_test_journey' and a.object_id_text=auth->>'scope_id'
      and a.action='WEEKLY_SOURCE_TEST_JOURNEY_OPENED' and a.event_sequence_is_authoritative;
  if exists(select 1 from public.audit_events a where a.object_type='weekly_source_protected_test_journey'
    and a.object_id_text=auth->>'scope_id' and a.event_sequence_is_authoritative
    and a.action in ('WEEKLY_SOURCE_TEST_JOURNEY_CLOSED','WEEKLY_SOURCE_TEST_JOURNEY_REVOKED')) then
    raise exception 'WEEKLY_SOURCE_TEST_SETUP_SCOPE_TERMINAL' using errcode='55000'; end if;
  if action='OPEN' then
    perform private.weekly_source_office_authority_v1((auth->>'journey_actor_user_id')::uuid,'APPROVE_PROTECTED_PAY',g.id,null,c.finalisation_week_ending);
    if n<>0 or (auth->>'expires_at_utc')::timestamptz<=clock_timestamp()
      or (auth->>'expires_at_utc')::timestamptz>clock_timestamp()+interval '2 hours'
      or exists(select 1 from public.weekly_source_group_rule_assignments a where a.source_group_id=g.id and a.feature_enabled
        and c.finalisation_week_ending between a.effective_from_week_ending and coalesce(a.effective_to_week_ending,'infinity'::date))
      or private.weekly_source_bulk_producer_ready_v1(c.id) or private.weekly_source_automatic_reconcile_producer_ready_v1(c.id) then
      raise exception 'WEEKLY_SOURCE_TEST_SETUP_OPEN_REFUSED' using errcode='55000'; end if;
    census:=private.weekly_source_protected_qualification_census_v1(c.id);
    if census is distinct from auth->'original_census' then raise exception 'WEEKLY_SOURCE_TEST_SETUP_CENSUS_CHANGED' using errcode='40001'; end if;
    manifest:=auth->'fixture_manifest';
    if manifest->'client_ids' is distinct from census->'original_client_ids'
      or (select coalesce(jsonb_agg(distinct item->'candidate_id' order by item->'candidate_id'),'[]'::jsonb)
        from jsonb_array_elements(census->'original_items') item) is distinct from manifest->'candidate_ids'
      or (select coalesce(jsonb_agg(distinct item->'contract_id' order by item->'contract_id'),'[]'::jsonb)
        from jsonb_array_elements(census->'original_items') item) is distinct from manifest->'contract_ids'
      or (select coalesce(jsonb_agg(distinct item->'work_event_id' order by item->'work_event_id'),'[]'::jsonb)
        from jsonb_array_elements(census->'original_items') item) is distinct from manifest->'work_event_ids'
      or (select coalesce(jsonb_agg(item->'timesheet_id' order by item->'timesheet_id'),'[]'::jsonb)
        from jsonb_array_elements(census->'original_root_identities') item) is distinct from manifest->'original_root_ids'
      or (select coalesce(jsonb_agg(item->'client_id' order by item->'client_id'),'[]'::jsonb)
        from jsonb_array_elements(manifest->'client_refs') item) is distinct from manifest->'client_ids'
      or (select coalesce(jsonb_agg(item->'candidate_id' order by item->'candidate_id'),'[]'::jsonb)
        from jsonb_array_elements(manifest->'candidate_refs') item) is distinct from manifest->'candidate_ids'
      or exists(select 1 from jsonb_array_elements(manifest->'client_refs') item
        where coalesce(item->>'cli_ref','') !~ '^CLI-913013[0-9]{2}$'
          or not exists(select 1 from public.clients client where client.id=(item->>'client_id')::uuid and client.cli_ref=item->>'cli_ref'))
      or exists(select 1 from jsonb_array_elements(manifest->'candidate_refs') item
        where coalesce(item->>'tms_ref','') !~ '^CCR-913013[0-9]{2}$'
          or not exists(select 1 from public.candidates candidate where candidate.id=(item->>'candidate_id')::uuid and candidate.tms_ref=item->>'tms_ref')) then
      raise exception 'WEEKLY_SOURCE_TEST_SETUP_FIXTURE_SCOPE_INVALID' using errcode='42501'; end if;
    -- Explicit prerequisite evidence stays NON-OPERATIONAL. Its NEXT_PAY row
    -- must be a genuine installed Banking prerequisite; root's managed writer
    -- binds the artifact/record. Function presence is never accepted here.
    select value into strict q from private.cloudtms_database_releases r,
      lateral jsonb_array_elements(r.evidence_json->'weekly_source_protected_capability_qualifications') value
      where r.release_id=auth->>'release_id' and value->>'qualification_sha256'=auth->>'prerequisite_qualification_sha256';
    perform private.weekly_source_protected_prerequisite_release_assert_v2(q,g.id,
      (q->>'effective_from_week_ending')::date,(q->>'effective_to_week_ending')::date,auth->>'prerequisite_qualification_sha256');
    if q->'capabilities' is distinct from '["BULK_SIGNED"]'::jsonb
      or not exists(select 1 from jsonb_array_elements(q->'gate_receipts') receipt
        where receipt->>'gate'='NEXT_PAY' and receipt->>'status'='PREREQUISITE_PASS') then
      raise exception 'WEEKLY_SOURCE_TEST_SETUP_NEXT_PREREQUISITE_REQUIRED' using errcode='55000'; end if;
    lease:=jsonb_build_object('contract','WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_V1','scope_id',auth->>'scope_id',
      'authorization_id',auth->>'authorization_id','authorization_sha256',auth->>'authorization_sha256',
      'source_group_id',g.id,'source_cycle_id',c.id,'agency_id',g.agency_id,'week_ending',c.finalisation_week_ending,
      'journey_actor_user_id',auth->>'journey_actor_user_id','setup_actor_user_id',actor,'expires_at_utc',auth->>'expires_at_utc',
      'opened_local_date',(clock_timestamp() at time zone 'Europe/London')::date,'operational_ready',false);
    lease:=lease||jsonb_build_object('scope_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_TEST_JOURNEY_SCOPE_V1',lease),'hex'));
    perform public._audit_insert('weekly_source_protected_test_journey',auth->>'scope_id','WEEKLY_SOURCE_TEST_JOURNEY_OPENED',null,lease,p_request->>'reason',actor);
    return lease;
  end if;
  if n<>1 then raise exception 'WEEKLY_SOURCE_TEST_SETUP_SCOPE_UNAVAILABLE' using errcode='55000'; end if;
  if action='CLOSE' then
    perform private.weekly_source_protected_test_scope_assert_v1(c.id,(auth->>'journey_actor_user_id')::uuid,null,null);
    result:=jsonb_build_object('scope_id',auth->>'scope_id','scope_sha256',lease->>'scope_sha256','setup_authorization_sha256',auth->>'authorization_sha256',
      'original_census_sha256',auth#>>'{original_census,census_sha256}','actor_user_id',auth->>'journey_actor_user_id',
      'source_cycle_id',c.id,'week_ending',c.finalisation_week_ending,'execution_release_id',auth->>'release_id',
      'execution_source_commit',auth->>'source_commit','execution_contract_sha256',auth->>'contract_sha256',
      'state','CLOSED','closed_at_utc',clock_timestamp(),'all_assignments_disabled',true,'all_operational_producers_false',true);
  else
    result:=jsonb_build_object('scope_id',auth->>'scope_id','state','REVOKED','closed_at_utc',clock_timestamp(),'operational_ready',false);
  end if;
  perform public._audit_insert('weekly_source_protected_test_journey',auth->>'scope_id',
    case when action='CLOSE' then 'WEEKLY_SOURCE_TEST_JOURNEY_CLOSED' else 'WEEKLY_SOURCE_TEST_JOURNEY_REVOKED' end,
    lease,result,p_request->>'reason',actor);
  return result;
exception when no_data_found or too_many_rows or invalid_text_representation or datetime_field_overflow then
  raise exception 'WEEKLY_SOURCE_TEST_SETUP_REQUEST_INVALID' using errcode='22023';
end;
$function$;

-- Complete forward schema correction; frozen predecessor remains evidence.
-- Root-review owner-private Source census. It never reads protection-stage
-- tables or mutable Timesheet/TSFIN lifecycle, and never makes a pay decision.
create or replace function private.weekly_source_bulk_source_facts_v1(p_cycle_id uuid,p_client_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare c public.weekly_source_cycles%rowtype; g public.weekly_source_groups%rowtype;
  p public.weekly_source_projection_publications%rowtype; u public.weekly_source_uploads%rowtype;
  clients uuid[]; facts jsonb; actual_client uuid;
begin
  if p_cycle_id is null or p_client_ids is null or array_position(p_client_ids,null::uuid) is not null then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='22023'; end if;
  select coalesce(array_agg(distinct value order by value),'{}'::uuid[]) into clients from unnest(p_client_ids) value;
  if cardinality(clients)>100 then raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_SCOPE_TOO_LARGE' using errcode='54000'; end if;
  select * into strict c from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict g from public.weekly_source_groups where id=c.source_group_id and active and source_family='ROSTER';
  select * into strict p from public.weekly_source_projection_publications where id=c.current_projection_publication_id
    and source_cycle_id=c.id and state='CURRENT' and authority_scope_kind='CYCLE' and correction_session_id is null and report_scope_id is null;
  select * into strict u from public.weekly_source_uploads where id=c.current_complete_upload_id and id=p.upload_id
    and source_cycle_id=c.id and state='CURRENT' and report_scope_id is null;
  perform private.weekly_source_query_current_publication_v1(c.id,p.id);
  actual_client:=private.weekly_source_checking_client_scope_v1(p.id);
  if exists(select 1 from unnest(clients) client where (actual_client is not null and actual_client<>client)
    or not exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=g.id and member.client_id=client
      and daterange(member.valid_from,coalesce(member.valid_to,'infinity'::date),'[]')
        && daterange(coalesce(u.confirmed_coverage_start_local_date,c.finalisation_week_ending-6),
          coalesce(u.confirmed_coverage_end_local_date,c.finalisation_week_ending),'[]'))) then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_CLIENT_SCOPE_CHANGED' using errcode='40001'; end if;
  -- CTE scope comes from saved Source parents. Incident IDs contribute stable
  -- work-event scope irrespective of OPEN/CLOSED; their mutable rows do not.
  with report_scopes as materialized (
    select scope.* from public.weekly_source_report_scopes scope where scope.source_group_id=g.id
      and scope.client_id=any(clients) and scope.self_bill_report_id is not null
  ), report_bindings as materialized (
    select binding.* from public.weekly_source_self_bill_report_line_bindings binding
      join public.weekly_source_self_bill_reports report on report.id=binding.self_bill_report_id
      where report.source_group_id=g.id and report.client_id=any(clients) and binding.state='CURRENT'
  ), publications as materialized (
    select publication.* from public.weekly_source_projection_publications publication where publication.id=p.id
      or publication.id in(select current_projection_publication_id from report_scopes)
      or publication.id in(select export_projection_publication_id from report_bindings)
  ), uploads as materialized (
    select upload.* from public.weekly_source_uploads upload where upload.id=u.id
      or upload.id in(select upload_id from publications)
  ), source_rows as materialized (
    select row_data.* from public.weekly_source_upload_rows row_data where row_data.upload_id in(select id from uploads)
  ), resolutions as materialized (
    select resolution.* from public.weekly_source_row_resolutions resolution
      join source_rows row_data on row_data.id=resolution.upload_row_id
      join publications publication on publication.upload_id=row_data.upload_id
        and resolution.generation=coalesce(publication.projection_generation,publication.authority_scope_version)
      where resolution.client_id=any(clients)
      union select resolution.* from public.weekly_source_row_resolutions resolution
        join report_bindings binding on binding.bound_row_resolution_id=resolution.id
  ), events as materialized (
    select event.* from public.weekly_work_events event where event.first_source_group_id=g.id and event.client_id=any(clients)
      and (event.id in(select work_event_id from resolutions) or event.id in(select work_event_id from report_bindings)
        or exists(select 1 from public.weekly_discrepancy_incidents incident where incident.source_cycle_id=c.id
          and incident.work_event_id=event.id and incident.client_id=event.client_id))
  ), revisions as materialized (
    select revision.* from public.weekly_source_final_revisions revision
      join public.weekly_source_cycles source_cycle on source_cycle.id=revision.source_cycle_id and source_cycle.source_group_id=g.id
      where revision.state in ('CURRENT','PREPARED','SUPERSEDED') and (
        revision.source_cycle_id=c.id or revision.report_scope_id in(select id from report_scopes)
        or exists(select 1 from public.weekly_source_final_snapshot_lines snapshot where snapshot.final_revision_id=revision.id
          and snapshot.work_event_id in(select id from events)))
  ), snapshots as materialized (
    select snapshot.* from public.weekly_source_final_snapshot_lines snapshot where snapshot.final_revision_id in(select id from revisions)
      and snapshot.client_id=any(clients)
  ), lineages as materialized (
    select lineage.* from public.weekly_source_row_timesheet_lineages lineage where lineage.client_id=any(clients)
      and (lineage.row_resolution_id in(select id from resolutions) or lineage.work_event_id in(select id from events))
  ), pay_receipts as materialized (
    select receipt.* from public.weekly_source_ordinary_pay_projection_receipts receipt where receipt.client_id=any(clients)
      and receipt.final_revision_id in(select id from revisions)
  ), financial_identities as materialized (
    -- The Source receipt is immutable and already pins all published economics
    -- and root-before/after/service hashes. Protection may replace currentness
    -- on the same native family; the Source financial identity stays exact.
    select financial.id,financial.timesheet_id,financial.client_id,financial.candidate_id,
      (select min(m.contract_id::text)::uuid
        from pay_receipts receipt
        cross join lateral jsonb_array_elements(case when jsonb_typeof(receipt.source_unit_outcomes_json)='array'
          then receipt.source_unit_outcomes_json else '[]'::jsonb end) unit
        join public.weekly_source_billing_movements m on m.id=(unit->>'movement_id')::uuid
          and m.final_revision_id=receipt.final_revision_id and m.invoice_timesheet_id=receipt.root_timesheet_id
          and m.actual_client_id=receipt.client_id and m.candidate_id=financial.candidate_id
          and encode(m.movement_economic_hash,'hex')=unit->>'movement_economic_hash'
          and m.source_profile_kind<>'SELF_BILL_REPORT'
          and m.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
        where receipt.published_timesheet_financial_id=financial.id
        having count(distinct m.contract_id)=1) as contract_id
      from public.timesheets_financials financial where financial.id in(select published_timesheet_financial_id from pay_receipts)
  ), root_identities as materialized (
    select root.timesheet_id,root.client_id,contract.candidate_id,root.contract_id,root.booking_id
      from public.timesheets root join public.contracts contract on contract.id=root.contract_id
      where root.timesheet_id in(select root_timesheet_id from pay_receipts)
  ), cycles as materialized (
    select cycle.* from public.weekly_source_cycles cycle where cycle.id=c.id or cycle.id in(select source_cycle_id from publications)
      or cycle.id in(select source_cycle_id from revisions)
  ), contracts as materialized (
    select contract.* from public.contracts contract where contract.client_id=any(clients)
      and (daterange(contract.start_date,contract.end_date,'[]') && daterange(
        coalesce(u.confirmed_coverage_start_local_date,c.finalisation_week_ending-6),
        coalesce(u.confirmed_coverage_end_local_date,c.finalisation_week_ending),'[]')
        or contract.id in(select contract_id from resolutions) or contract.id in(select contract_id from snapshots)
        or exists(select 1 from public.weekly_issue_comparison_revisions comparison
          join public.weekly_discrepancy_incidents incident on incident.current_comparison_revision_id=comparison.id
          where incident.source_cycle_id=c.id and incident.client_id=contract.client_id and comparison.contract_id=contract.id))
  ), policy_dates as materialized (
    select client client_id,null::uuid contract_id,c.finalisation_week_ending work_date from unnest(clients) client
    union select client_id,contract_id,work_date from snapshots
    union select resolution.client_id,resolution.contract_id,row_data.work_date from resolutions resolution
      join source_rows row_data on row_data.id=resolution.upload_row_id
    union select client_id,null::uuid,work_date from events
    union select contract.client_id,contract.id,greatest(contract.start_date,
      coalesce(u.confirmed_coverage_start_local_date,c.finalisation_week_ending-6)) from contracts contract
  ), resolved_policies as materialized (
    select client_id,contract_id,work_date,private._weekly_source_effective_policy_v1(client_id,contract_id,work_date) policy
      from policy_dates
  )
  select jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_SOURCE_FACTS_V1','source_cycle_id',c.id,
    'client_ids',to_jsonb(clients),'group',to_jsonb(g),
    'cycles',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from cycles x),'[]'::jsonb),
    'clients',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.clients x where x.id=any(clients)),'[]'::jsonb),
    'memberships',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.valid_from,x.id)
      from public.weekly_source_group_clients x where x.source_group_id=g.id and x.client_id=any(clients)),'[]'::jsonb),
    'client_policies',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.effective_from,x.id)
      from public.weekly_source_client_policies x where x.source_group_id=g.id and x.client_id=any(clients)),'[]'::jsonb),
    'client_settings',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.id) from public.client_settings x where x.client_id=any(clients)),'[]'::jsonb),
    'contracts',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from contracts x),'[]'::jsonb),
    'contract_policies',coalesce((select jsonb_agg(to_jsonb(x) order by x.contract_id,x.effective_from,x.id)
      from public.weekly_source_contract_policies x where x.contract_id in(select id from contracts)),'[]'::jsonb),
    'global_settings',coalesce((select jsonb_agg(to_jsonb(x)) from public.weekly_source_global_settings x where x.singleton),'[]'::jsonb),
    'resolved_policies',coalesce((select jsonb_agg(to_jsonb(x) order by x.client_id,x.contract_id nulls first,x.work_date) from resolved_policies x),'[]'::jsonb),
    'assignments',coalesce((select jsonb_agg(to_jsonb(x) order by x.effective_from_week_ending,x.id)
      from public.weekly_source_group_rule_assignments x where x.source_group_id=g.id),'[]'::jsonb),
    'rule_versions',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.weekly_source_rule_set_versions x
      where x.id in(select rule_set_version_id from public.weekly_source_group_rule_assignments where source_group_id=g.id)
        or x.id in(select rule_set_version_id from revisions)),'[]'::jsonb),
    'effective_rules',coalesce((select jsonb_agg(jsonb_build_object('client_id',client,
      'effective_rule_set',private.weekly_source_effective_rule_set_v1(client,c.id)) order by client) from unnest(clients) client),'[]'::jsonb),
    'profiles',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.weekly_source_format_profiles x
      where x.id in(select source_format_profile_id from uploads)),'[]'::jsonb),
    'uploads',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from uploads x),'[]'::jsonb),
    'publications',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from publications x),'[]'::jsonb),
    'rows',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_id,x.source_row_ordinal,x.id) from source_rows x),'[]'::jsonb),
    'resolutions',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_row_id,x.generation,x.id) from resolutions x),'[]'::jsonb),
    'economics',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id) from public.weekly_source_row_economic_snapshots x
      where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'expense_policy_snapshots',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id)
      from public.weekly_source_row_expense_policy_snapshots x where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'expense_authorities',coalesce((select jsonb_agg(to_jsonb(x) order by x.work_event_id,x.generation,x.id)
      from public.weekly_expense_authority_generations x where x.final_revision_id in(select id from revisions)
        and x.work_event_id in(select id from events)),'[]'::jsonb),
    'expense_cell_evidence',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_id,x.source_row_ordinal,x.id)
      from public.weekly_source_expense_cell_evidence x where x.upload_id in(select id from uploads)),'[]'::jsonb),
    'charge_checks',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id)
      from public.weekly_source_charge_checks x where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'charge_acceptances',coalesce((select jsonb_agg(to_jsonb(x) order by x.row_resolution_id,x.id)
      from public.weekly_source_charge_acceptances x where x.row_resolution_id in(select id from resolutions)),'[]'::jsonb),
    'invoice_hold_releases',coalesce((select jsonb_agg(to_jsonb(x) order by x.upload_row_id,x.hold_kind,x.id)
      from public.weekly_source_invoice_hold_releases x where x.upload_row_id in(select id from source_rows)),'[]'::jsonb),
    'transitions',coalesce((select jsonb_agg(to_jsonb(x) order by x.final_revision_id,x.work_event_id,x.id)
      from public.weekly_source_state_transitions x where x.final_revision_id in(select id from revisions)
        and x.work_event_id in(select id from events)),'[]'::jsonb),
    'report_scopes',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from report_scopes x),'[]'::jsonb),
    'reports',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from public.weekly_source_self_bill_reports x
      where x.source_group_id=g.id and x.client_id=any(clients)),'[]'::jsonb),
    'report_bindings',coalesce((select jsonb_agg(to_jsonb(x) order by x.report_row_id,x.id) from report_bindings x),'[]'::jsonb),
    'events',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from events x),'[]'::jsonb),
    'revisions',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from revisions x),'[]'::jsonb),
    'snapshots',coalesce((select jsonb_agg(to_jsonb(x) order by x.final_revision_id,x.work_event_id,x.id) from snapshots x),'[]'::jsonb),
    'lineages',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from lineages x),'[]'::jsonb),
    'pay_receipts',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from pay_receipts x),'[]'::jsonb),
    'financial_identities',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from financial_identities x),'[]'::jsonb),
    'root_identities',coalesce((select jsonb_agg(to_jsonb(x) order by x.timesheet_id) from root_identities x),'[]'::jsonb)) into facts;
  if exists(select 1 from jsonb_array_elements(facts->'pay_receipts') receipt
    where receipt->>'published_timesheet_financial_id' is not null and (
      jsonb_typeof(receipt->'source_unit_outcomes_json') is distinct from 'array'
      or case when jsonb_typeof(receipt->'source_unit_outcomes_json')='array'
        then jsonb_array_length(receipt->'source_unit_outcomes_json')=0 else true end
      or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(receipt->'source_unit_outcomes_json')='array'
          then receipt->'source_unit_outcomes_json' else '[]'::jsonb end) unit
        where not exists(select 1 from public.weekly_source_billing_movements m
          where m.id=(unit->>'movement_id')::uuid and m.final_revision_id=(receipt->>'final_revision_id')::uuid
            and m.invoice_timesheet_id=(receipt->>'root_timesheet_id')::uuid
            and m.actual_client_id=(receipt->>'client_id')::uuid
            and exists(select 1 from jsonb_array_elements(facts->'financial_identities') financial
              where financial->>'id'=receipt->>'published_timesheet_financial_id'
                and financial->>'candidate_id'=m.candidate_id::text
                and financial->>'contract_id'=m.contract_id::text)
            and encode(m.movement_economic_hash,'hex')=unit->>'movement_economic_hash'
            and m.source_profile_kind<>'SELF_BILL_REPORT'
            and m.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION'))))) then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_FINANCIAL_IDENTITY_INVALID' using errcode='55000'; end if;
  if (select count(*) from public.clients where id=any(clients))<>cardinality(clients)
    or exists(select 1 from jsonb_array_elements(facts->'pay_receipts') receipt
      where receipt->>'published_timesheet_financial_id' is not null and not exists(
        select 1 from jsonb_array_elements(facts->'financial_identities') financial
          where financial->>'id'=receipt->>'published_timesheet_financial_id'
            and financial->>'timesheet_id'=receipt->>'root_timesheet_id' and financial->>'client_id'=receipt->>'client_id'
            and exists(select 1 from jsonb_array_elements(facts->'root_identities') root
              join jsonb_array_elements(facts->'contracts') contract on contract->>'id'=financial->>'contract_id'
              where root->>'timesheet_id'=financial->>'timesheet_id'
                and root->>'candidate_id'=financial->>'candidate_id' and root->>'contract_id'=financial->>'contract_id'
                and (root->>'client_id' is null or root->>'client_id'=financial->>'client_id')
                and contract->>'client_id'=financial->>'client_id' and contract->>'candidate_id'=financial->>'candidate_id'))) then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_FINANCIAL_IDENTITY_INVALID' using errcode='55000'; end if;
  if octet_length(convert_to(facts::text,'UTF8'))>8388608 then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_SCOPE_TOO_LARGE' using errcode='54000'; end if;
  return facts;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_SCOPE_UNAVAILABLE' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_bulk_source_cas_v1(p_cycle_id uuid,p_client_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare facts jsonb;
begin
  facts:=private.weekly_source_bulk_source_facts_v1(p_cycle_id,p_client_ids);
  return jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_SOURCE_CAS_V1','source_cycle_id',p_cycle_id,
    'client_ids',facts->'client_ids','source_cas_sha256',encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_BULK_SOURCE_CAS_V1',facts),'hex'));
end;
$function$;

-- Root-review complete forward Source owner; no frozen input edited.
create or replace function public.weekly_source_timesheet_lineage_ensure_atomic_v1(
  p_row_resolution_id uuid,
  p_actor_user_id uuid
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_resolution public.weekly_source_row_resolutions%rowtype;
  v_source_row public.weekly_source_upload_rows%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_contract public.contracts%rowtype;
  v_candidate public.candidates%rowtype;
  v_client public.clients%rowtype;
  v_expense_policy public.weekly_source_row_expense_policy_snapshots%rowtype;
  v_policy jsonb;
  v_contract_week public.contract_weeks%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_lineage public.weekly_source_row_timesheet_lineages%rowtype;
  v_guard jsonb;
  v_contract_week_settings jsonb;
  v_timesheet_settings jsonb;
  v_week_ending_date date;
  v_weekday integer;
  v_booking_id text;
  v_booking_material text;
  v_occupant_norm text;
  v_hospital_norm text;
  v_ward_norm text;
  v_role_norm text;
  v_lineage_fingerprint bytea;
  v_expected_expense_policy_hash bytea;
  v_created_timesheet boolean:=false;
  v_existing_lineage boolean:=false;
  v_is_correction boolean:=false;
  v_lock_result jsonb;
  v_lineage_lock_phase integer;
  v_lineage_discovery jsonb;
  v_lineage_observed jsonb;
  v_family jsonb;
  v_known_root_timesheet_id uuid;
  v_root_authorisation jsonb;
  v_bound_timesheet_id uuid;
  v_finalisation_root_set text;
  v_legacy_root_set_now text;
  v_legacy_root_ids uuid[];
  v_finalisation_lock_operation_text text;
  v_finalisation_lock_operation private.bpay_next_source_current_lock_operations%rowtype;
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_row_resolution_id is null or p_actor_user_id is null then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_LINEAGE_INPUT_REQUIRED' using errcode='22023';
  end if;

  select * into v_resolution
  from public.weekly_source_row_resolutions
  where id=p_row_resolution_id;
  if not found or v_resolution.mapping_state<>'RESOLVED' then
    raise exception 'WEEKLY_SOURCE_RESOLUTION_NOT_CURRENT' using errcode='55000';
  end if;

  select * into strict v_source_row
  from public.weekly_source_upload_rows
  where id=v_resolution.upload_row_id;
  select * into strict v_upload
  from public.weekly_source_uploads
  where id=v_source_row.upload_id;

  perform private.weekly_source_pay_query_admit_v2();
  -- G1 standalone and inherited FIN paths share the same physical I-1 owner.
  -- Phase1 is plain key/scope admission plus its unchanged family call. Phase2
  -- locks discovered group -> cycle and revalidates every selector before DML.
  for v_lineage_lock_phase in 1..2 loop
    if v_lineage_lock_phase=2 then
      select * into v_group from public.weekly_source_groups
      where id=(v_lineage_discovery#>>'{group,id}')::uuid for share;
      if not found or to_jsonb(v_group) is distinct from v_lineage_discovery->'group' then
        raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
    end if;
  if v_lineage_lock_phase=2 then
  select * into v_cycle
  from public.weekly_source_cycles
  where id=v_upload.source_cycle_id
  for update;
    if not found or to_jsonb(v_cycle) is distinct from v_lineage_discovery->'cycle' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_cycle
  from public.weekly_source_cycles
  where id=v_upload.source_cycle_id;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_CYCLE_NOT_FOUND' using errcode='55000';
  end if;

  if v_upload.report_scope_id is not null then
    if v_lineage_lock_phase=2 then
  select * into v_scope
    from public.weekly_source_report_scopes
    where id=v_upload.report_scope_id
    for update;
    if not found or to_jsonb(v_scope) is distinct from v_lineage_discovery->'scope' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_scope
    from public.weekly_source_report_scopes
    where id=v_upload.report_scope_id;
  end if;
    if not found or v_scope.source_cycle_id is distinct from v_cycle.id then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_NOT_CURRENT' using errcode='55000';
    end if;
  end if;

  if v_lineage_lock_phase=2 then
  select * into v_upload
  from public.weekly_source_uploads
  where id=v_source_row.upload_id
    and source_cycle_id=v_cycle.id
  for share;
    if not found or to_jsonb(v_upload) is distinct from v_lineage_discovery->'upload' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_upload
  from public.weekly_source_uploads
  where id=v_source_row.upload_id
    and source_cycle_id=v_cycle.id;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_UPLOAD_NOT_CURRENT' using errcode='55000';
  end if;

  if v_lineage_lock_phase=2 then
  select * into v_publication
  from public.weekly_source_projection_publications publication
  where publication.source_cycle_id=v_cycle.id
    and publication.upload_id=v_upload.id
    and publication.authority_scope_version=v_resolution.generation
    and (
      (
        publication.state='CURRENT'
        and v_upload.purpose='ORDINARY'
        and v_upload.correction_session_id is null
        and (
          (v_upload.report_scope_id is null
           and publication.authority_scope_kind='CYCLE'
           and publication.report_scope_id is null
           and v_cycle.current_projection_publication_id=publication.id
           and v_cycle.current_complete_upload_id=v_upload.id)
          or
          (v_upload.report_scope_id is not null
           and publication.authority_scope_kind='NHSP_REPORT_SCOPE'
           and publication.report_scope_id=v_upload.report_scope_id
           and v_scope.current_projection_publication_id=publication.id
           and v_scope.current_complete_upload_id=v_upload.id)
        )
      )
      or (
        publication.state='CORRECTION_READY'
        and v_upload.state='CORRECTION_READY'
        and v_upload.purpose='FINAL_SOURCE_CORRECTION'
        and v_upload.correction_session_id is not null
        and publication.correction_session_id=v_upload.correction_session_id
        and (
          (v_upload.report_scope_id is null
           and publication.authority_scope_kind='CYCLE'
           and publication.report_scope_id is null)
          or
          (v_upload.report_scope_id is not null
           and publication.authority_scope_kind='NHSP_REPORT_SCOPE'
           and publication.report_scope_id=v_upload.report_scope_id)
        )
      )
    )
  for share;
    if not found or to_jsonb(v_publication) is distinct from v_lineage_discovery->'publication' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_publication
  from public.weekly_source_projection_publications publication
  where publication.source_cycle_id=v_cycle.id
    and publication.upload_id=v_upload.id
    and publication.authority_scope_version=v_resolution.generation
    and (
      (
        publication.state='CURRENT'
        and v_upload.purpose='ORDINARY'
        and v_upload.correction_session_id is null
        and (
          (v_upload.report_scope_id is null
           and publication.authority_scope_kind='CYCLE'
           and publication.report_scope_id is null
           and v_cycle.current_projection_publication_id=publication.id
           and v_cycle.current_complete_upload_id=v_upload.id)
          or
          (v_upload.report_scope_id is not null
           and publication.authority_scope_kind='NHSP_REPORT_SCOPE'
           and publication.report_scope_id=v_upload.report_scope_id
           and v_scope.current_projection_publication_id=publication.id
           and v_scope.current_complete_upload_id=v_upload.id)
        )
      )
      or (
        publication.state='CORRECTION_READY'
        and v_upload.state='CORRECTION_READY'
        and v_upload.purpose='FINAL_SOURCE_CORRECTION'
        and v_upload.correction_session_id is not null
        and publication.correction_session_id=v_upload.correction_session_id
        and (
          (v_upload.report_scope_id is null
           and publication.authority_scope_kind='CYCLE'
           and publication.report_scope_id is null)
          or
          (v_upload.report_scope_id is not null
           and publication.authority_scope_kind='NHSP_REPORT_SCOPE'
           and publication.report_scope_id=v_upload.report_scope_id)
        )
      )
    );
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_PROJECTION_NOT_CURRENT' using errcode='55000';
  end if;

  v_is_correction:=v_publication.state='CORRECTION_READY';
  if v_is_correction then
    if v_lineage_lock_phase=2 then
  select * into v_correction
    from public.weekly_final_source_correction_sessions correction
    where correction.id=v_upload.correction_session_id
    for share;
    if not found or to_jsonb(v_correction) is distinct from v_lineage_discovery->'correction' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_correction
    from public.weekly_final_source_correction_sessions correction
    where correction.id=v_upload.correction_session_id;
  end if;
    if not found or v_correction.state<>'PREPARING'
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from
          (case when v_upload.report_scope_id is null then 'CYCLE'
                else 'NHSP_REPORT_SCOPE' end)
       or v_correction.report_scope_id is distinct from v_upload.report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.replacement_projection_publication_id is distinct from v_publication.id
       or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
            is distinct from v_correction.expected_current_final_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
    end if;
  else
    v_guard:=private.weekly_source_current_publication_guard_v1(
      v_cycle.id,
      case when v_upload.report_scope_id is null then 'CYCLE' else 'NHSP_REPORT_SCOPE' end,
      v_upload.report_scope_id,
      v_upload.id,
      v_publication.id,
      v_publication.authority_scope_version
    );
    if coalesce((v_guard->>'ok')::boolean,false) is not true
       or v_upload.purpose is distinct from 'ORDINARY'
       or v_upload.correction_session_id is not null then
      raise exception 'WEEKLY_SOURCE_PROJECTION_NOT_CURRENT' using errcode='55000';
    end if;
  end if;

  if v_lineage_lock_phase=2 then
  select * into v_resolution
  from public.weekly_source_row_resolutions
  where id=p_row_resolution_id
    and upload_row_id=v_source_row.id
    and generation=v_publication.authority_scope_version
  for update;
    if not found or to_jsonb(v_resolution) is distinct from v_lineage_discovery->'resolution' then
      raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
  select * into v_resolution
  from public.weekly_source_row_resolutions
  where id=p_row_resolution_id
    and upload_row_id=v_source_row.id
    and generation=v_publication.authority_scope_version;
  end if;
  if not found or v_resolution.mapping_state<>'RESOLVED' then
    raise exception 'WEEKLY_SOURCE_RESOLUTION_NOT_CURRENT' using errcode='55000';
  end if;
  select * into strict v_source_row
  from public.weekly_source_upload_rows
  where id=v_resolution.upload_row_id and upload_id=v_upload.id;

  select * into strict v_profile
  from public.weekly_source_format_profiles
  where id=v_upload.source_format_profile_id;
  select * into strict v_group
  from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  select * into strict v_event
  from public.weekly_work_events
  where id=v_resolution.work_event_id;
  select * into v_contract
  from public.contracts
  where id=v_resolution.contract_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CONTRACT_NOT_FOUND' using errcode='55000';
  end if;

  if v_upload.report_scope_id is not null and not v_is_correction then
    if v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.client_id is distinct from v_resolution.client_id
       or v_scope.current_projection_publication_id is distinct from v_publication.id
       or v_scope.current_complete_upload_id is distinct from v_upload.id then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_NOT_CURRENT' using errcode='55000';
    end if;
  end if;

  if not v_profile.active
     or v_profile.profile_code not in (
       'NHSP_FINAL_BACKING_V1',
       'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
       'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1',
       'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1'
     )
     or v_source_row.row_finalisation_state not in (
       'NOT_APPLICABLE','SOURCE_WORKED','SOURCE_ABSENT_ZERO'
     )
     or (v_source_row.row_finalisation_state='SOURCE_ABSENT_ZERO'
         and v_profile.profile_code<>'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1')
     or v_resolution.work_event_id is distinct from v_event.id
     or v_resolution.candidate_id is distinct from v_event.candidate_id
     or v_resolution.client_id is distinct from v_event.client_id
     or v_source_row.work_date is distinct from v_event.work_date
     or v_resolution.client_id is distinct from v_contract.client_id
     or v_resolution.candidate_id is distinct from v_contract.candidate_id
     or v_source_row.work_date not between v_contract.start_date and v_contract.end_date then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_LINEAGE_SCOPE_INVALID' using errcode='55000';
  end if;

  v_policy:=private._weekly_source_effective_policy_v1(
    v_resolution.client_id,v_resolution.contract_id,v_source_row.work_date
  );
  if v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true
     or v_policy->>'c1_source_mode' not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or private.weekly_source_projection_hex32_v1(
          v_policy->>'policy_sha256','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
        ) is distinct from v_resolution.effective_policy_fingerprint
     or (v_group.source_family='NHSP') is distinct from
        (v_policy->>'c1_source_mode'='NHSP_WEEKLY')
     or (v_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT') is distinct from
        (v_group.source_family='NHSP') then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_LINEAGE_POLICY_INVALID' using errcode='55000';
  end if;

  if v_source_row.row_finalisation_state='SOURCE_ABSENT_ZERO' then
    if coalesce((v_policy->>'source_fixed_expenses_enabled')::boolean,false) is not true
       or v_source_row.source_expense_parse_state<>'VALID'
       or coalesce(v_source_row.source_expense_pence,0)<=0
       or v_source_row.actual_net_minutes<>0
       or v_source_row.start_at_local is null
       or v_source_row.end_at_local is null
       or v_source_row.end_at_local<=v_source_row.start_at_local
       or v_source_row.break_minutes is null
       or exists(
         select 1 from public.weekly_source_row_economic_snapshots economic
         where economic.row_resolution_id=v_resolution.id
       ) then
      raise exception 'WEEKLY_SOURCE_ZERO_HOUR_EXPENSE_LINEAGE_INVALID' using errcode='55000';
    end if;

    select * into v_expense_policy
    from public.weekly_source_row_expense_policy_snapshots expense_policy
    where expense_policy.row_resolution_id=v_resolution.id;
    if not found or (
      select pg_catalog.count(*)
      from public.weekly_source_row_expense_policy_snapshots expense_policy
      where expense_policy.row_resolution_id=v_resolution.id
    )<>1 then
      raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_SNAPSHOT_CARDINALITY' using errcode='55000';
    end if;
    v_expected_expense_policy_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_ROW_EXPENSE_POLICY_SNAPSHOT_V1',
      pg_catalog.jsonb_build_object(
        'row_resolution_id',v_resolution.id,'upload_row_id',v_source_row.id,
        'generation',v_resolution.generation,'work_event_id',v_resolution.work_event_id,
        'candidate_id',v_resolution.candidate_id,'client_id',v_resolution.client_id,
        'contract_id',v_resolution.contract_id,
        'row_finalisation_state',v_source_row.row_finalisation_state,
        'source_expense_pence',v_source_row.source_expense_pence,
        'source_expense_parse_state',v_source_row.source_expense_parse_state,
        'source_expense_vat_enabled',v_expense_policy.source_expense_vat_enabled,
        'invoice_vat_chargeable',v_expense_policy.invoice_vat_chargeable,
        'invoice_vat_rate_pct',v_expense_policy.invoice_vat_rate_pct,
        'correction_presentation',v_expense_policy.correction_presentation,
        'effective_policy_fingerprint',
          pg_catalog.encode(v_expense_policy.effective_policy_fingerprint,'hex'),
        'invoice_vat_policy_fingerprint',
          pg_catalog.encode(v_expense_policy.invoice_vat_policy_fingerprint,'hex')
      )
    );
    if v_expense_policy.upload_row_id is distinct from v_source_row.id
       or v_expense_policy.generation is distinct from v_resolution.generation
       or v_expense_policy.work_event_id is distinct from v_resolution.work_event_id
       or v_expense_policy.candidate_id is distinct from v_resolution.candidate_id
       or v_expense_policy.client_id is distinct from v_resolution.client_id
       or v_expense_policy.contract_id is distinct from v_resolution.contract_id
       or v_expense_policy.source_expense_pence is distinct from v_source_row.source_expense_pence
       or v_expense_policy.source_expense_parse_state is distinct from v_source_row.source_expense_parse_state
       or v_expense_policy.effective_policy_fingerprint is distinct from
          v_resolution.effective_policy_fingerprint
       or v_expense_policy.source_expense_vat_enabled is distinct from
          coalesce((v_policy->>'source_expense_vat_enabled')::boolean,false)
       or v_expense_policy.correction_presentation is distinct from
          pg_catalog.upper(pg_catalog.btrim(coalesce(
            v_policy->>'self_bill_correction_presentation',''
          )))
       or v_expense_policy.snapshot_hash is distinct from v_expected_expense_policy_hash then
      raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_SNAPSHOT_INVALID' using errcode='55000';
    end if;
  elsif (select pg_catalog.count(*)
         from public.weekly_source_row_economic_snapshots economic
         where economic.row_resolution_id=v_resolution.id)<>1 then
    raise exception 'WEEKLY_SOURCE_ECONOMIC_SNAPSHOT_CARDINALITY' using errcode='55000';
  end if;

  perform private.weekly_source_office_authority_v1(
    p_actor_user_id,'FINALISE_WEEK',v_group.id,v_resolution.client_id,
    v_cycle.finalisation_week_ending
  );

  v_weekday:=v_contract.week_ending_weekday_snapshot;
  if v_weekday not between 0 and 6 then
    raise exception 'WEEKLY_SOURCE_WEEK_ENDING_POLICY_INVALID' using errcode='55000';
  end if;
  v_week_ending_date:=v_source_row.work_date+
    ((v_weekday-extract(dow from v_source_row.work_date)::integer+7)%7);

  -- Note on the Candidate serial gate (proof/32 section 6 step 1): this owner
  -- binds a resolved source row to its ordinary base Weekly Timesheet.  It is
  -- not one of the four pinned Weekly Source job types (first authorisation,
  -- first-authorisation withdrawal, entitlement publication, pending release),
  -- so it does not take the gate; the first-authorisation owner does, through
  -- interface I-1.  It does take the full rotation lock set below.

  -- Review F1 and F4.  Every installed rotation owner takes the family advisory
  -- key and then the family rows, and only then contract_weeks (core
  -- 08082026_2035_...:126-131 then :190-193; legacy 16122025_...:844-849;
  -- confirmed route :2374-2376 then :2384-2385).  This owner previously locked
  -- the Contract Week, the Contract and the root row FIRST and asked for the
  -- family advisory keys afterwards, which is the reverse order and a proven
  -- deadlock (reproductions D1 and D2).  The root is therefore discovered with a
  -- PLAIN read, the I-1 lock set is taken FIRST, and every other lock follows.
  select contract_week.timesheet_id into v_known_root_timesheet_id
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_resolution.contract_id
    and contract_week.week_ending_date=v_week_ending_date
    and contract_week.additional_seq=0;

  if v_lineage_lock_phase=2 and v_known_root_timesheet_id is distinct from
      nullif(v_lineage_discovery->>'root_timesheet_id','')::uuid then
    raise exception 'WEEKLY_SOURCE_BASE_WEEK_ROOT_CHANGED_DURING_LOCK' using errcode='40001'; end if;

  -- Review G2, the finalisation side of the same rule.  When a finalisation has
  -- already taken the complete sorted family lock set for this cycle, it
  -- publishes that set here.  A root this owner discovers that the set does not
  -- contain would be locked out of that sorted order, so refuse retryably
  -- instead.  Outside a finalisation the setting is absent and nothing changes.
  v_finalisation_lock_operation_text:=nullif(pg_catalog.btrim(coalesce(
    pg_catalog.current_setting('cloudtms.weekly_source_finalisation_lock_operation',true),''
  )), '');
  if v_finalisation_lock_operation_text is not null
     and (select active_owner from private.bpay_next_module_control where id=1)='NEXT' then
    -- One owner-private operation UUID replaces the whole-root CSV only for
    -- NEXT. It is not authority by itself: bind transaction and actual Source
    -- upload/publication/generation/exact old correction revision first.
    select o.* into v_finalisation_lock_operation
    from private.bpay_next_source_current_lock_operations o
    where o.id=v_finalisation_lock_operation_text::uuid
      and o.transaction_id=pg_catalog.pg_current_xact_id()
      and o.upload_id=v_upload.id and o.projection_publication_id=v_publication.id
      and o.generation=v_resolution.generation
      and o.old_revision_id is not distinct from case when v_is_correction
        then v_correction.expected_current_final_revision_id else null end
      and o.source_group_id=v_group.id and o.client_id=v_resolution.client_id;
    if not found then
      raise exception 'WEEKLY_SOURCE_FINALISATION_LOCK_OPERATION_UNBOUND' using errcode='40001';
    end if;
    if v_known_root_timesheet_id is not null and not exists(
      select 1 from private.bpay_next_source_current_lock_members m
      join public.timesheets t on t.timesheet_id=m.root_timesheet_id
      where m.operation_id=v_finalisation_lock_operation.id
        and m.root_timesheet_id=v_known_root_timesheet_id and m.raw_booking_id=t.booking_id
    ) then
      raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK' using errcode='40001';
    end if;
  else
  -- Retain the unrelated/default OFF Source guard exactly as before.
  v_finalisation_root_set:=nullif(pg_catalog.btrim(coalesce(
    pg_catalog.current_setting('cloudtms.weekly_source_finalisation_root_set',true),''
  )),'');
  if v_finalisation_root_set is not null
     and v_known_root_timesheet_id is not null
     and (v_finalisation_root_set='EMPTY_LOCKED_SET'
       or not (v_known_root_timesheet_id::text
              =any(pg_catalog.string_to_array(v_finalisation_root_set,',')))) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'code','WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK',
          'observed_root_timesheet_id',v_known_root_timesheet_id
        )::text;
  end if;
  end if;

  if v_known_root_timesheet_id is not null and v_lineage_lock_phase=1 then
    v_lock_result:=private.weekly_source_lock_family_rows_v1(
      array[v_known_root_timesheet_id]::uuid[],v_resolution.candidate_id
    );
    if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
      raise exception '%',v_lock_result->>'code'
        using errcode='55000',detail=v_lock_result::text;
    end if;
    v_family:=v_lock_result->'families'->0;
  end if;

  v_lineage_observed:=jsonb_build_object('cycle',to_jsonb(v_cycle),'group',to_jsonb(v_group),
    'scope',to_jsonb(v_scope),'upload',to_jsonb(v_upload),'publication',to_jsonb(v_publication),
    'correction',to_jsonb(v_correction),'resolution',to_jsonb(v_resolution),'source_row',to_jsonb(v_source_row),
    'profile',to_jsonb(v_profile),'event',to_jsonb(v_event),'contract',to_jsonb(v_contract),
    'policy',v_policy,'expense_policy',to_jsonb(v_expense_policy),
    'week_ending_date',v_week_ending_date,'root_timesheet_id',v_known_root_timesheet_id);
  if v_lineage_lock_phase=1 then v_lineage_discovery:=v_lineage_observed;
  elsif v_lineage_observed is distinct from v_lineage_discovery then
    raise exception 'WEEKLY_SOURCE_LINEAGE_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  end loop;

  -- A missing base Contract Week has no row to lock, so use the same scoped
  -- advisory lock before selecting/inserting it.  This is not a business key
  -- or an externally visible lock, and it is now taken after the family keys.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'WEEKLY_SOURCE_BASE_WEEK|'||v_resolution.contract_id::text||'|'||v_week_ending_date::text,
    0
  ));

  insert into public.contract_weeks(
    contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id,is_adjustment,created_at,updated_at
  ) values (
    v_resolution.contract_id,v_week_ending_date,0,
    'SUBMITTED'::public.contract_week_status_enum,
    'MANUAL'::public.submission_mode_enum,null,false,
    pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()
  ) on conflict (contract_id,week_ending_date,additional_seq) do nothing;

  select * into strict v_contract_week
  from public.contract_weeks
  where contract_id=v_resolution.contract_id
    and week_ending_date=v_week_ending_date
    and additional_seq=0
  for update;

  -- Existing manual week owners lock the base week before the Contract.  Keep
  -- that order, then revalidate every mutable Contract fact and recompute the
  -- week end while both rows are protected.
  select * into v_contract
  from public.contracts
  where id=v_resolution.contract_id
  for update;
  if not found
     or v_resolution.client_id is distinct from v_contract.client_id
     or v_resolution.candidate_id is distinct from v_contract.candidate_id
     or v_source_row.work_date not between v_contract.start_date and v_contract.end_date
     or v_contract.week_ending_weekday_snapshot not between 0 and 6
     or v_week_ending_date is distinct from v_source_row.work_date+
        ((v_contract.week_ending_weekday_snapshot-
          extract(dow from v_source_row.work_date)::integer+7)%7) then
    raise exception 'WEEKLY_SOURCE_CONTRACT_CHANGED_DURING_LINEAGE' using errcode='55000';
  end if;

  if v_contract_week.contract_id is distinct from v_resolution.contract_id
     or v_contract_week.week_ending_date is distinct from v_week_ending_date
     or v_contract_week.additional_seq<>0
     or v_contract_week.is_adjustment
     or v_contract_week.status='CANCELLED'::public.contract_week_status_enum then
    raise exception 'WEEKLY_SOURCE_BASE_CONTRACT_WEEK_INVALID' using errcode='55000';
  end if;

  -- Under the locks, the Contract Week must still name the root whose family
  -- this transaction locked.  If it now names a different root, or gained one
  -- after the plain read found none, the family locks would be the wrong ones:
  -- refuse retryably rather than take a second family lock set out of order.
  if v_contract_week.timesheet_id is distinct from v_known_root_timesheet_id then
    raise exception 'WEEKLY_SOURCE_BASE_WEEK_ROOT_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'expected_root_timesheet_id',v_known_root_timesheet_id,
          'observed_root_timesheet_id',v_contract_week.timesheet_id
        )::text;
  end if;

  if v_contract_week.timesheet_id is not null then
    -- The family rows are already locked by the I-1 lock set above, so this is
    -- a re-entrant read of a row this transaction holds, not a new lock order.
    select * into v_timesheet
    from public.timesheets
    where timesheet_id=v_contract_week.timesheet_id
    for update;
    -- proof/34 rule 6 and section 5 step 3: a stored contract-week Timesheet id
    -- that is no longer the current version is a ROTATION, not an invalid
    -- Timesheet.  It is classified below, after the rotation lock set has been
    -- taken, so it carries the exact
    -- WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION refusal (ROT-001).
    if not found
       or v_timesheet.contract_id is distinct from v_resolution.contract_id
       or v_timesheet.week_ending_date is distinct from v_week_ending_date
       or v_timesheet.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum
       or v_timesheet.line_type<>'HOURS'::public.timesheet_line_type_enum
       or v_timesheet.is_adjustment
       or v_timesheet.revoked_at is not null
       or v_timesheet.archived_at_utc is not null then
      raise exception 'WEEKLY_SOURCE_EXISTING_TIMESHEET_INVALID' using errcode='55000';
    end if;
  else
    if v_contract_week.status in (
      'AUTHORISED'::public.contract_week_status_enum,
      'INVOICED'::public.contract_week_status_enum,
      'CANCELLED'::public.contract_week_status_enum
    ) then
      raise exception 'WEEKLY_SOURCE_FINAL_WEEK_TIMESHEET_MISSING' using errcode='55000';
    end if;

    select * into strict v_candidate
    from public.candidates where id=v_resolution.candidate_id;
    select * into strict v_client
    from public.clients where id=v_resolution.client_id;

    v_occupant_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_candidate.tms_ref),''),
      nullif(pg_catalog.btrim(v_candidate.display_name),''),
      v_candidate.id::text
    ));
    v_hospital_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.display_site),''),
      nullif(pg_catalog.btrim(v_client.name),''),
      v_client.id::text
    ));
    v_ward_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.ward_hint),''),'contract'
    ));
    v_role_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.role),''),'weekly'
    ));
    v_booking_material:='weekly-source|'||v_resolution.contract_id::text||'|'||
      v_week_ending_date::text;
    v_booking_id:='bk_'||pg_catalog.substr(pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(v_booking_material,'UTF8'),'sha256'),'hex'
    ),1,24);

    if exists(
      select 1
      from public.timesheets existing
      where existing.booking_id=v_booking_id
        and existing.is_current
    ) then
      raise exception 'WEEKLY_SOURCE_BOOKING_ID_COLLISION' using errcode='55000';
    end if;

    insert into public.timesheets(
      booking_id,version,is_current,status,sheet_scope,submission_mode,line_type,
      occupant_key_norm,hospital_norm,ward_norm,job_title_norm,shift_label_norm,
      week_ending_date,contract_id,actual_schedule_json,qr_payload_json,
      is_adjustment,created_at,updated_at
    ) values (
      v_booking_id,1,true,'RECEIVED'::public.timesheet_status_enum,
      'WEEKLY'::public.timesheet_scope_enum,'MANUAL'::public.submission_mode_enum,
      'HOURS'::public.timesheet_line_type_enum,v_occupant_norm,v_hospital_norm,
      v_ward_norm,v_role_norm,'weekly-0',v_week_ending_date,
      v_resolution.contract_id,'[]'::jsonb,'{}'::jsonb,false,
      pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()
    ) returning * into v_timesheet;
    v_created_timesheet:=true;

    if v_finalisation_lock_operation.id is not null then
      -- Only this genuine INSERT RETURNING may add a new private root; never
      -- a lookup/fallback or a root that appeared externally. No pre-existing
      -- booking key is invented: retain the Source base-week creation serial
      -- policy. Subsequent WORK/expense rows can re-enter this exact own root.
      insert into private.bpay_next_source_current_lock_members(
        operation_id,root_timesheet_id,raw_booking_id,canonical_booking_id
      ) values(v_finalisation_lock_operation.id,v_timesheet.timesheet_id,
        v_timesheet.booking_id,pg_catalog.btrim(v_timesheet.booking_id));
    end if;

    update public.contract_weeks
    set timesheet_id=v_timesheet.timesheet_id,
        status=case when status='AUTHORISED'::public.contract_week_status_enum
          then status else 'SUBMITTED'::public.contract_week_status_enum end,
        updated_at=pg_catalog.statement_timestamp()
    where id=v_contract_week.id
    returning * into v_contract_week;

    insert into public.audit_events(
      ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,before_json,after_json,reason
    )
    select
      pg_catalog.statement_timestamp(),p_actor_user_id,actor.display_name,actor.role,
      'timesheets',v_timesheet.timesheet_id::text,
      'WEEKLY_SOURCE_BASE_TIMESHEET_CREATED',null,
      pg_catalog.jsonb_build_object(
        'source_cycle_id',v_cycle.id,
        'row_resolution_id',v_resolution.id,
        'work_event_id',v_resolution.work_event_id,
        'contract_id',v_resolution.contract_id,
        'contract_week_id',v_contract_week.id,
        'candidate_id',v_resolution.candidate_id,
        'client_id',v_resolution.client_id,
        'week_ending_date',v_week_ending_date
      ),'FINAL_SOURCE_LINEAGE'
    from public.tms_users actor
    where actor.id=p_actor_user_id;

    if not found then
      raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
    end if;
  end if;

  -- proof/34 section 5 step 2: the deadlock-free rotation lock set and a
  -- re-resolution of the canonical current version through the installed
  -- Workbench authority.  A stored or newly minted physical id is only a lookup
  -- key; it is never trusted on its own (rule 6).
  --
  -- For an existing root the lock set was already taken, before every other
  -- lock, so this call is re-entrant and re-resolves under the locks.  For a
  -- root this transaction has just minted, no other session can know the
  -- booking id yet, so taking the family keys here cannot join a cycle.
  v_lock_result:=private.weekly_source_lock_family_rows_v1(
    array[v_timesheet.timesheet_id]::uuid[],v_resolution.candidate_id
  );
  if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
    raise exception '%',v_lock_result->>'code'
      using errcode='55000',detail=v_lock_result::text;
  end if;
  v_family:=v_lock_result->'families'->0;

  -- Only the native INSERT RETURNING above can extend this transaction's
  -- already complete LEGACY lock census. It owns this previously invisible
  -- root, and the unchanged native I-1 call has now succeeded. A lookup,
  -- replay, external root, rotation or nonempty unbound NEXT operation cannot
  -- enter this branch. Existing discovery/root-set growth 40001 guards remain.
  if v_created_timesheet and v_finalisation_lock_operation.id is null
     and v_finalisation_lock_operation_text is null
     and v_finalisation_root_set is not null
     and (select active_owner from private.bpay_next_module_control where id=1)='LEGACY' then
    v_legacy_root_set_now:=nullif(pg_catalog.btrim(coalesce(
      pg_catalog.current_setting('cloudtms.weekly_source_finalisation_root_set',true),''
    )),'');
    if v_legacy_root_set_now is distinct from v_finalisation_root_set
       or v_known_root_timesheet_id is not null
       or v_timesheet.timesheet_id is null
       or v_timesheet.booking_id is distinct from v_booking_id
       or v_timesheet.contract_id is distinct from v_resolution.contract_id
       or v_timesheet.week_ending_date is distinct from v_week_ending_date then
      raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK' using errcode='40001';
    end if;
    -- EMPTY_LOCKED_SET is an explicit complete empty census, never a UUID.
    if v_legacy_root_set_now='EMPTY_LOCKED_SET' then
      v_legacy_root_ids:=array[]::uuid[];
    else
      begin
        v_legacy_root_ids:=pg_catalog.string_to_array(v_legacy_root_set_now,',')::uuid[];
      exception when invalid_text_representation then
        raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK' using errcode='40001';
      end;
      if pg_catalog.array_position(v_legacy_root_ids,null::uuid) is not null then
        raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK' using errcode='40001';
      end if;
    end if;
    select array_agg(own_root order by own_root) into v_legacy_root_ids
    from (select distinct own_root from unnest(
      v_legacy_root_ids||array[v_timesheet.timesheet_id]::uuid[]) own_root) own_roots;
    perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set',
      pg_catalog.array_to_string(v_legacy_root_ids,','),true);
  end if;

  -- Review F5 / proof/34 rule 7: an approved decision is never silently
  -- transferred from one physical Timesheet id to another.  If the family
  -- already carries a live root authorisation on a member that is NOT the
  -- canonical row, the authorised root has rotated: refuse rather than bind a
  -- new source row to the new physical id and report success.
  v_root_authorisation:=private.weekly_source_root_authorisation_state_v1(
    (v_family->>'canonical_timesheet_id')::uuid,
    (select pg_catalog.array_agg(member.value::uuid)
     from pg_catalog.jsonb_array_elements_text(
       v_family->'member_timesheet_ids'
     ) member(value))
  );
  -- Review G8: the guard treats a missing authorisation relation as "cannot
  -- tell" and fails closed; this owner must point the same way, not bind.
  if coalesce((v_root_authorisation->>'relation_present')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',
        detail=pg_catalog.jsonb_build_object(
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
          'reason',coalesce(v_root_authorisation->>'reason',
                            'ROOT_AUTHORISATION_RELATION_MISSING')
        )::text;
  end if;
  if coalesce((v_root_authorisation->>'live_on_other_member_count')::integer,0)>0 then
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',
        detail=pg_catalog.jsonb_build_object(
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
          'reason','AUTHORISED_ROOT_NOT_CANONICAL',
          'canonical_timesheet_id',v_family->>'canonical_timesheet_id',
          'authorised_timesheet_id',
            v_root_authorisation->>'live_on_other_member_timesheet_id'
        )::text;
  end if;

  -- proof/34 section 5 step 3: a changed current id before first authorisation
  -- makes the request stale.  Write nothing and never authorise the older id.
  if coalesce((v_family->>'requested_is_canonical')::boolean,false) is not true
     or coalesce((v_family->>'family_is_current')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION'
      using errcode='55000',detail=v_family::text;
  end if;

  -- The family rows are locked now, so re-read the root under the lock before
  -- any fact derived from it is frozen into the lineage record.
  select * into strict v_timesheet
  from public.timesheets
  where timesheet_id=v_timesheet.timesheet_id;
  if v_timesheet.booking_id is distinct from (v_family->>'family_booking_id')
     or v_timesheet.version is distinct from (v_family->>'canonical_version')::integer
     or not v_timesheet.is_current then
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',detail=v_family::text;
  end if;

  -- Decision D8: this owner writes a BINDING record, never an authorisation.
  -- The row signature at authorisation, the authorisation generation and the
  -- entitlement head pointer all belong to
  -- public.weekly_source_root_authorisations, written only by the
  -- first-authorisation owner (interface I-6) after the ordinary Authorise
  -- succeeds, and marked withdrawn only by the withdrawal owner.  This owner
  -- therefore computes and stores no signature at all.

  v_contract_week_settings:=
    private.weekly_source_contract_week_settings_authority_assert_v1(v_contract_week.id);
  v_timesheet_settings:=
    private._timesheet_settings_authority_frozen_v1(v_timesheet.timesheet_id);
  if v_timesheet.settings_authority_resolved_at is null
     or (v_timesheet_settings->>'resolved_at_utc')::timestamptz is distinct from
        v_timesheet.settings_authority_resolved_at
     or v_timesheet.settings_authority_fingerprint is distinct from
        v_contract_week.settings_authority_fingerprint
     or v_timesheet_settings->>'authority_fingerprint' is distinct from
        v_contract_week_settings->>'authority_fingerprint' then
    raise exception 'WEEKLY_SOURCE_SETTINGS_AUTHORITY_NOT_FROZEN' using errcode='55000';
  end if;

  v_lineage_fingerprint:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ROW_TIMESHEET_LINEAGE_V1',
    pg_catalog.jsonb_build_object(
      'row_resolution_id',v_resolution.id,
      'source_cycle_id',v_cycle.id,
      'work_event_id',v_resolution.work_event_id,
      'candidate_id',v_resolution.candidate_id,
      'client_id',v_resolution.client_id,
      'contract_id',v_resolution.contract_id,
      'contract_week_id',v_contract_week.id,
      'timesheet_id',v_timesheet.timesheet_id,
      'week_ending_date',v_week_ending_date
    )
  );

  -- Decision D8: one binding row per resolution.  A replay is a no-op; this
  -- owner never writes an authorisation generation, and re-authorisation after
  -- a withdrawal appends a row to public.weekly_source_root_authorisations,
  -- written only by the first-authorisation owner (interface I-6).
  select exists(
    select 1 from public.weekly_source_row_timesheet_lineages lineage
    where lineage.row_resolution_id=v_resolution.id
  ) into v_existing_lineage;

  -- Decision D8: the binding record.  It carries the binding-time family
  -- identity and physical version, which stale detection needs, and no
  -- authorisation fact of any kind.
  insert into public.weekly_source_row_timesheet_lineages(
    row_resolution_id,source_cycle_id,work_event_id,candidate_id,client_id,
    contract_id,contract_week_id,timesheet_id,family_booking_id,timesheet_version,
    week_ending_date,lineage_fingerprint
  ) values (
    v_resolution.id,v_cycle.id,v_resolution.work_event_id,v_resolution.candidate_id,
    v_resolution.client_id,v_resolution.contract_id,v_contract_week.id,
    v_timesheet.timesheet_id,v_timesheet.booking_id,v_timesheet.version,
    v_week_ending_date,v_lineage_fingerprint
  ) on conflict (row_resolution_id) do nothing;

  -- Review G3 / proof/34 section 5 step 3 and section 6.  A binding that already
  -- exists on a DIFFERENT physical id means the base Timesheet rotated since it
  -- was bound.  Before first authorisation that is permitted and rotation WINS
  -- (rule 2): the request is STALE, so refuse with
  -- WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION and say that the
  -- resolution must be rebuilt at a new generation.  Only when the family
  -- carries a live authorisation record is it the section 6 integrity failure,
  -- which the assert below raises.  Without this the immutable binding would
  -- make that source row impossible to finalise ever again.
  select lineage.timesheet_id into v_bound_timesheet_id
  from public.weekly_source_row_timesheet_lineages lineage
  where lineage.row_resolution_id=v_resolution.id;
  if v_bound_timesheet_id is distinct from v_timesheet.timesheet_id then
    if coalesce((v_root_authorisation->>'live_on_canonical')::boolean,false) is not true
       and coalesce((v_root_authorisation->>'live_on_other_member_count')::integer,0)=0 then
      raise exception 'WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION'
        using errcode='55000',
          detail=pg_catalog.jsonb_build_object(
            'code','WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION',
            'reason','BOUND_ROOT_ROTATED_BEFORE_AUTHORISATION',
            'bound_timesheet_id',v_bound_timesheet_id,
            'canonical_timesheet_id',v_timesheet.timesheet_id,
            'rebuild','REBUILD_RESOLUTION_AT_A_NEW_GENERATION'
          )::text;
    end if;
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',
        detail=pg_catalog.jsonb_build_object(
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
          'reason','AUTHORISED_ROOT_ROTATED_AFTER_AUTHORISATION',
          'bound_timesheet_id',v_bound_timesheet_id,
          'canonical_timesheet_id',v_timesheet.timesheet_id
        )::text;
  end if;

  v_lineage:=private.weekly_source_timesheet_lineage_assert_v1(v_resolution.id);
  if v_lineage.lineage_fingerprint is distinct from v_lineage_fingerprint then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_LINEAGE_CONFLICT' using errcode='55000';
  end if;

  if not v_existing_lineage then
    insert into public.audit_events(
      ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,before_json,after_json,reason
    )
    select
      pg_catalog.statement_timestamp(),p_actor_user_id,actor.display_name,actor.role,
      'weekly_source_row_timesheet_lineages',v_lineage.id::text,
      'WEEKLY_SOURCE_TIMESHEET_LINEAGE_CREATED',null,
      pg_catalog.jsonb_build_object(
        'source_cycle_id',v_lineage.source_cycle_id,
        'row_resolution_id',v_lineage.row_resolution_id,
        'work_event_id',v_lineage.work_event_id,
        'contract_id',v_lineage.contract_id,
        'contract_week_id',v_lineage.contract_week_id,
        'timesheet_id',v_lineage.timesheet_id,
        'candidate_id',v_lineage.candidate_id,
        'client_id',v_lineage.client_id,
        'week_ending_date',v_lineage.week_ending_date,
        'created_timesheet',v_created_timesheet
      ),'FINAL_SOURCE_LINEAGE'
    from public.tms_users actor
    where actor.id=p_actor_user_id;

    if not found then
      raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'row_resolution_id',v_resolution.id,
    'source_cycle_id',v_cycle.id,
    'contract_week_id',v_lineage.contract_week_id,
    'timesheet_id',v_lineage.timesheet_id,
    'week_ending_date',v_lineage.week_ending_date,
    'created_timesheet',v_created_timesheet,
    'idempotent_replay',v_existing_lineage
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_LINEAGE_SCOPE_INVALID' using errcode='55000';
end;
$function$;

