  v_worker text;
  v_target public.weekly_message_dispatch_targets%rowtype;
  v_command public.weekly_message_dispatch_commands%rowtype;
  v_intent public.weekly_message_intents%rowtype;
  v_render public.weekly_message_renders%rowtype;
  v_attempt public.weekly_message_target_attempts%rowtype;
  v_attempt_number integer;
  v_reason text;
  v_contact jsonb;
  v_agency uuid;
  v_environment text;
  v_next timestamptz;
begin
  perform private.weekly_source_query_require_service_v1();
  perform private.weekly_contact_assert_closed_v1(p_request,
    array['dispatch_target_id','lease_token','worker_id','agency_id','environment'],
    array['dispatch_target_id','lease_token','worker_id','agency_id','environment'],
    'WEEKLY_SOURCE_TARGET_START_REQUEST_INVALID');
  if jsonb_typeof(p_request->'worker_id') is distinct from 'string'
    or char_length(p_request->>'worker_id') not between 1 and 200
    or p_request->>'environment' is null or p_request->>'environment' not in('TEST','LIVE') then
    raise exception 'WEEKLY_SOURCE_TARGET_START_REQUEST_INVALID' using errcode='22023';end if;
  begin
    v_target_id:=private.weekly_contact_uuid_v1(p_request->'dispatch_target_id');
    v_lease_token:=private.weekly_contact_uuid_v1(p_request->'lease_token');
    v_agency:=private.weekly_contact_uuid_v1(p_request->'agency_id');
    v_environment:=p_request->>'environment';
    v_worker:=p_request->>'worker_id';
  exception when others then
    raise exception 'WEEKLY_SOURCE_TARGET_START_REQUEST_INVALID' using errcode='22023';
  end;
  -- Read-only recovery never admits/resends or acquires a later lower-order
  -- lock. Exact old lease replay and any still-unknown native attempt return
  -- the original identity, even after a lease was reclaimed by another worker.
  perform private.weekly_contact_context_v1(v_agency,v_environment);
  select * into strict v_target from public.weekly_message_dispatch_targets where id=v_target_id;
  select * into strict v_command from public.weekly_message_dispatch_commands where id=v_target.dispatch_command_id;
  if v_command.agency_id is distinct from v_agency or v_command.environment is distinct from v_environment then
    raise exception 'CONTACT_DISPATCH_SCOPE_INVALID' using errcode='42501';end if;
  select * into v_attempt from public.weekly_message_target_attempts
  where dispatch_target_id=v_target.id and(completed_at_utc is null
    or(lease_token=v_lease_token and lease_owner=v_worker))
  order by attempt_number desc limit 1;
  if found then
    return jsonb_build_object('ok',true,'replay',true,'provider_attempt_id',v_attempt.id,
      'call_once',false,'reason','CHECK_ORIGINAL_ATTEMPT');end if;
  -- The common entry takes deployment -> PUSH policy -> sorted scopes ->
  -- required calendar row locks BEFORE the original target/command locks.
  -- It derives channel and memberships from these genuine native rows.
  v_contact:=public.weekly_contact_submission_start_v1(jsonb_build_object(
    'version','CONTACT_START_V1','owner_kind','WEEKLY_SOURCE_TARGET',
    'dispatch_target_id',v_target_id,'lease_token',v_lease_token,'worker_id',v_worker,
    'agency_id',v_agency,'environment',v_environment));
  if v_contact->'ok' is distinct from 'true'::jsonb then
    select * into strict v_target from public.weekly_message_dispatch_targets where id=v_target_id for update;
    select * into strict v_command from public.weekly_message_dispatch_commands where id=v_target.dispatch_command_id for update;
    if v_contact->>'reason' not in('NOT_STARTED_PAUSED','NOT_STARTED_QUIET','EXPIRED_TIMING','OBSOLETE')
      or v_contact->>'reason' is null or v_contact->>'dispatch_target_id' is distinct from v_target.id::text
      or v_contact->>'channel' is distinct from v_target.channel then
      raise exception 'CONTACT_DISPATCH_SCOPE_INVALID' using errcode='42501';end if;
    if v_contact->>'reason'='NOT_STARTED_QUIET'
      or(v_contact->>'reason'='NOT_STARTED_PAUSED' and v_target.channel='PUSH') then
      v_next:=(v_contact->>'next_eligible_at_utc')::timestamptz;
      if v_next is null or not isfinite(v_next) then
        raise exception 'CONTACT_DISPATCH_SCOPE_INVALID' using errcode='42501';end if;
      update public.weekly_message_dispatch_targets set state='TRANSIENT_FAILURE',
        next_attempt_at_utc=v_next,terminal_at_utc=null,terminal_reason=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null where id=v_target.id;
    else
      update public.weekly_message_dispatch_targets set state='RETIRED',terminal_at_utc=clock_timestamp(),
        terminal_reason=v_contact->>'reason',next_attempt_at_utc=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null where id=v_target.id;
      if v_target.channel='EMAIL' then
        -- Retire the whole unsent frozen manager body/link, never filter its
        -- members under that same body. Original recheck/recomposition owns
        -- any later eligible-only render with unchanged logical allowances.
        update public.weekly_manager_review_batches set state='REVOKED'
          where message_render_id=v_command.message_render_id and state='ACTIVE';
        update public.weekly_manager_route_receipts r set state='REVOKED',revoked_at_utc=clock_timestamp()
          from public.weekly_manager_review_batches b
          where r.review_batch_id=b.id and b.message_render_id=v_command.message_render_id and r.state='ACTIVE';
        update public.weekly_manager_review_items m set response_state='OBSOLETE'
          from public.weekly_manager_review_batches b
          where m.review_batch_id=b.id and b.message_render_id=v_command.message_render_id and m.response_state='UNANSWERED';
      end if;
    end if;
    perform private.weekly_source_delivery_aggregate_command_v1(v_command.id);
    return v_contact;
  end if;
  select * into strict v_target from public.weekly_message_dispatch_targets
  where id=v_target_id for update;
  select * into strict v_command from public.weekly_message_dispatch_commands
  where id=v_target.dispatch_command_id for update;
  select * into strict v_intent from public.weekly_message_intents
  where id=v_command.message_intent_id;
  select * into strict v_render from public.weekly_message_renders
  where id=v_command.message_render_id;
  select * into v_attempt from public.weekly_message_target_attempts
  where dispatch_target_id=v_target.id and completed_at_utc is null
  order by attempt_number desc limit 1;
  if found and v_target.state='SUBMISSION_STARTED' then
    return pg_catalog.jsonb_build_object(
      'ok',true,'replay',true,'provider_attempt_id',v_attempt.id,
      'call_once',false,'reason','CHECK_ORIGINAL_ATTEMPT'
    );
  end if;
  if v_target.state<>'LEASED' or v_target.lease_token<>v_lease_token
     or v_target.lease_owner<>v_worker
     or v_target.lease_expires_at_utc<=pg_catalog.transaction_timestamp()
     or v_intent.state<>'RENDERED' or v_render.state<>'CURRENT' then
    raise exception 'WEEKLY_SOURCE_TARGET_LEASE_STALE' using errcode='40001';
  end if;
  begin
    perform private.weekly_source_query_current_publication_v1(
      v_command.source_cycle_id,v_command.projection_publication_id
    );
  exception when others then
    update public.weekly_message_dispatch_targets
    set state='RETIRED',terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason='CURRENT_HOURS_CHANGED',next_attempt_at_utc=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    perform private.weekly_source_delivery_aggregate_command_v1(v_command.id);
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason','CURRENT_HOURS_CHANGED',
      'dispatch_target_id',v_target.id,'dispatch_command_id',v_command.id
    );
  end;
  if v_target.channel='PUSH' and not exists(
    select 1 from public.weekly_candidate_message_notifications message_notification
    join public.candidate_notifications notification on notification.id=message_notification.notification_id
    where message_notification.message_intent_id=v_intent.id and notification.state='UNREAD'
      and private.candidate_notification_visible_v1(notification,pg_catalog.transaction_timestamp())
  ) then
    update public.weekly_message_dispatch_targets
    set state='RETIRED',terminal_at_utc=pg_catalog.transaction_timestamp(),terminal_reason='NOTIFICATION_NO_LONGER_ACTIONABLE',
      next_attempt_at_utc=null,lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    perform private.weekly_source_delivery_aggregate_command_v1(v_command.id);
    return pg_catalog.jsonb_build_object('ok',false,'reason','NOTIFICATION_NO_LONGER_ACTIONABLE',
      'dispatch_target_id',v_target.id,'dispatch_command_id',v_command.id);
  end if;
  if v_intent.audience_kind='CANDIDATE' and not exists(
    select 1 from public.weekly_candidate_outreach_generations generation
    join public.weekly_candidate_cohorts cohort on cohort.id=generation.candidate_cohort_id
    where generation.id=v_command.candidate_generation_id and generation.state='ACTIVE'
      and private.weekly_source_candidate_generation_current_v1(generation.id)
  ) then
    update public.weekly_message_dispatch_targets
    set state='RETIRED',terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason='CANDIDATE_GENERATION_CHANGED',next_attempt_at_utc=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    perform private.weekly_source_delivery_aggregate_command_v1(v_command.id);
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason','CANDIDATE_GENERATION_CHANGED',
      'dispatch_target_id',v_target.id,'dispatch_command_id',v_command.id
    );
  elsif v_intent.audience_kind='CANDIDATE' and not exists(
    select 1
    from public.weekly_candidate_outreach_memberships membership
    join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
    where membership.candidate_generation_id=v_command.candidate_generation_id
      and membership.state='ACTIONABLE' and incident.state='OPEN'
  ) and not exists(
    select 1
    from public.weekly_candidate_outreach_generations generation
    join public.weekly_timesheet_submission_requests submission
      on submission.candidate_cohort_id=generation.candidate_cohort_id
     and submission.state in ('ACTIVE','OVERDUE','PARTLY_SUBMITTED')
    join public.weekly_timesheet_submission_request_memberships membership
      on membership.submission_request_id=submission.id and membership.state='WAITING'
    where generation.id=v_command.candidate_generation_id
      and generation.request_kind='SUBMIT_TIMESHEET'
  ) then
    update public.weekly_message_dispatch_targets
    set state='RETIRED',terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason='REQUEST_RESOLVED',next_attempt_at_utc=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    perform private.weekly_source_delivery_aggregate_command_v1(v_command.id);
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason','REQUEST_RESOLVED',
      'dispatch_target_id',v_target.id,'dispatch_command_id',v_command.id
    );
  elsif v_intent.audience_kind='MANAGER' and not exists(
    select 1
    from public.weekly_manager_recipient_generations generation
    join public.weekly_manager_recipient_routes route on route.id=generation.recipient_route_id
    join public.weekly_manager_review_batches batch
      on batch.recipient_generation_id=generation.id
     and batch.message_render_id=v_render.id and batch.state='ACTIVE'
    where generation.id=v_intent.recipient_generation_id and generation.state='ACTIVE'
      and route.current_generation_id=generation.id
  ) then
    v_reason:='REVIEW_REPLACED';
  elsif v_intent.audience_kind='MANAGER' and (
    exists(
      select 1
      from public.weekly_manager_review_batches batch
      join public.weekly_manager_review_items item on item.review_batch_id=batch.id
      join public.weekly_discrepancy_incidents incident on incident.id=item.incident_id
      join public.weekly_issue_comparison_revisions comparison
        on comparison.id=incident.current_comparison_revision_id
      where batch.message_render_id=v_render.id
        and (
          item.response_state<>'UNANSWERED' or incident.state<>'OPEN'
          or item.incident_episode<>incident.episode_number
          or item.sent_comparison_revision_id<>incident.current_comparison_revision_id
          or item.sent_comparison_fingerprint<>comparison.material_comparison_fingerprint
        )
    ) or not exists(
      select 1
      from public.weekly_manager_review_batches batch
      join public.weekly_manager_review_items item on item.review_batch_id=batch.id
      join public.weekly_discrepancy_incidents incident on incident.id=item.incident_id
      where batch.message_render_id=v_render.id
        and item.response_state='UNANSWERED' and incident.state='OPEN'
    )
  ) then
    v_reason:='REVIEW_CHANGED';
  end if;
  if v_reason is not null then
    update public.weekly_message_dispatch_targets
    set state='RETIRED',terminal_at_utc=pg_catalog.transaction_timestamp(),
        terminal_reason=v_reason,next_attempt_at_utc=null,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null
    where id=v_target.id;
    update public.weekly_manager_review_batches
    set state='REVOKED'
    where message_render_id=v_render.id and state='ACTIVE';
    update public.weekly_manager_route_receipts receipt
    set state='REVOKED',revoked_at_utc=pg_catalog.transaction_timestamp()
    from public.weekly_manager_review_batches batch
    where receipt.review_batch_id=batch.id and batch.message_render_id=v_render.id
      and receipt.state='ACTIVE';
    update public.weekly_manager_review_items item
    set response_state='OBSOLETE'
    from public.weekly_manager_review_batches batch
    where item.review_batch_id=batch.id and batch.message_render_id=v_render.id
      and item.response_state='UNANSWERED';
    perform private.weekly_source_delivery_aggregate_command_v1(v_command.id);
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason',v_reason,
      'dispatch_target_id',v_target.id,'dispatch_command_id',v_command.id
    );
  end if;
  select coalesce(pg_catalog.max(attempt_number),0)+1 into v_attempt_number
  from public.weekly_message_target_attempts where dispatch_target_id=v_target.id;
  if v_attempt_number>v_target.maximum_attempts then
    raise exception 'WEEKLY_SOURCE_TARGET_RETRIES_EXHAUSTED' using errcode='55000';
  end if;
  insert into public.weekly_message_target_attempts(
    dispatch_target_id,attempt_number,provider_idempotency_key,
    lease_owner,lease_token,submission_started_at_utc
  ) values (
    v_target.id,v_attempt_number,
    v_target.provider_idempotency_key||'/attempt-'||v_attempt_number::text,
    v_worker,v_lease_token,(v_contact#>>'{admission,admitted_at_utc}')::timestamptz
  ) returning * into v_attempt;
  update public.weekly_message_dispatch_targets
  set state='SUBMISSION_STARTED',attempt_count=v_attempt_number
  where id=v_target.id;
  update public.weekly_message_dispatch_commands set state='SUBMISSION_STARTED'
  where id=v_command.id;
  update public.weekly_message_renders set state='SUBMISSION_STARTED'
  where id=v_render.id;
  return private.weekly_contact_source_permit_v1(v_target.id,v_attempt.id,v_contact->'admission');
end;
$function$;

alter function public.weekly_source_message_dispatch_target_start_atomic_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_message_dispatch_target_start_atomic_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_source_message_dispatch_target_start_atomic_v1(jsonb) to service_role;

notify pgrst,'reload schema';



-- CONTACT_PREPARER_UNIT 146 repeatable supabase/repeatable/16102026_0244_weekly_contact_global_timing_v1.sql SHA256 85c7d47c9a3508de8f8ccd0369f08ead4ec77bd25c39b4bf1ab4200fc084dad0
-- V6 global timing policy: complete current owners after historical repeatables.


create or replace function private.weekly_source_manager_interval_valid_v1(p_value integer,p_unit text,p_zero boolean)
returns boolean language sql immutable security definer set search_path='pg_catalog','pg_temp'
as $function$
 select coalesce(p_value>=case when p_zero then 0 else 1 end and
  ((p_unit='HOURS' and p_value<=8784) or (p_unit in('CALENDAR_DAYS','CLIENT_WORKING_DAYS') and p_value<=366)),false)
$function$;

create or replace function private.weekly_source_manager_followups_valid_v1(p_vector jsonb)
returns boolean language plpgsql immutable security definer set search_path='pg_catalog','private','pg_temp'
as $function$
declare row jsonb;n integer:=0;
begin
 if jsonb_typeof(p_vector) is distinct from 'array' or jsonb_array_length(p_vector)>10 then return false;end if;
 for row in select value from jsonb_array_elements(p_vector) loop
  n:=n+1;
  if jsonb_typeof(row) is distinct from 'object' or not(row ?& array['sequence','interval_value','interval_unit','mode'])
   or row-array['sequence','interval_value','interval_unit','mode']<>'{}'::jsonb
   or jsonb_typeof(row->'sequence') is distinct from 'number' or row->>'sequence' !~ '^[0-9]+$'
   or jsonb_typeof(row->'interval_value') is distinct from 'number' or row->>'interval_value' !~ '^[0-9]+$'
   or length(row->>'interval_value')>4 or row->>'sequence'<>n::text
   or not coalesce(row->>'mode' in('MANUAL','AUTOMATIC'),false)
   or jsonb_typeof(row->'interval_unit') is distinct from 'string' then return false;end if;
  if not private.weekly_source_manager_interval_valid_v1((row->>'interval_value')::integer,row->>'interval_unit',false) then return false;end if;
 end loop;
 return true;
end;
$function$;

alter function private.weekly_source_manager_interval_valid_v1(integer,text,boolean) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_interval_valid_v1(integer,text,boolean) from public,anon,authenticated,service_role;
alter function private.weekly_source_manager_followups_valid_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_followups_valid_v1(jsonb) from public,anon,authenticated,service_role;

-- Existing global settings singleton/GET/save are the sole authority.
create or replace function public.weekly_source_global_settings_get_v1(p_request jsonb)
returns jsonb language plpgsql stable security definer set search_path='pg_catalog','private','pg_temp'
as $function$
declare actor uuid;agency uuid;s public.weekly_source_global_settings%rowtype;
begin
 perform private._weekly_source_settings_assert_request_v1(p_request,array['actor_user_id','agency_id','environment'],'WEEKLY_SOURCE_GLOBAL_SETTINGS_GET_REQUEST_INVALID');
 actor:=private.weekly_contact_uuid_v1(p_request->'actor_user_id');agency:=private.weekly_contact_uuid_v1(p_request->'agency_id');
 perform private._weekly_source_settings_require_admin_v1(actor);
 if jsonb_typeof(p_request->'environment') is distinct from 'string' or not coalesce(p_request->>'environment' in('TEST','LIVE'),false) then
  raise exception 'WEEKLY_SOURCE_SETTINGS_DEPLOYMENT_INVALID' using errcode='22023';end if;
 perform private._weekly_source_settings_deployment_v1(agency,p_request->>'environment');
 select x.* into strict s from public.weekly_source_global_settings x where x.singleton;
 return jsonb_build_object('ok',true,'settings_version',s.version::text,'policy_revision',s.version::text,
  'settings',jsonb_build_object(
   'candidate_reminder_minutes',extract(epoch from s.candidate_reminder_after)::bigint/60,
   'candidate_response_deadline_minutes',extract(epoch from s.candidate_response_deadline_after)::bigint/60,
   'manager_digest_minutes',extract(epoch from s.manager_partial_digest_after)::bigint/60,
   'manager_manual_resend_cooldown_minutes',extract(epoch from s.manager_manual_send_cooldown)::bigint/60,
   'candidate_manual_reminder_cooldown_minutes',extract(epoch from s.candidate_manual_reminder_cooldown)::bigint/60,
   'manager_secure_link_days',extract(epoch from s.manager_secure_link_lifetime)::bigint/86400,
   'automatic_reconcile_actor_user_id',s.automatic_reconcile_actor_user_id,
   'manager_first_delay_value',s.manager_first_delay_value,'manager_first_delay_unit',s.manager_first_delay_unit,
   'manager_followups',s.manager_followups,'manager_recent_completed_weeks',s.manager_recent_completed_weeks,
   'manager_max_work_age_days',s.manager_max_work_age_days),
  'cutoff',jsonb_build_object('kind','CLIENT_CUTOFF_PRECEDENCE','editable',false,
   'explanation','The actual Client cut-off overrides these routine contact limits.'),
  'actions',jsonb_build_array(jsonb_build_object('action','SAVE_GLOBAL_CONTACT_TIMING','enabled',true,'reason',null)));
end;
$function$;

create or replace function public.weekly_source_global_settings_save_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path='pg_catalog','private','pg_temp'
as $function$
declare actor uuid;agency uuid;v_request_id uuid;expected bigint;settings jsonb;key text;digest bytea;receipt public.weekly_source_global_settings_receipts%rowtype;
 s public.weekly_source_global_settings%rowtype;next_s public.weekly_source_global_settings%rowtype;result jsonb;v_now timestamptz:=transaction_timestamp();
 required text[]:=array['candidate_reminder_minutes','candidate_response_deadline_minutes','manager_digest_minutes',
  'manager_manual_resend_cooldown_minutes','candidate_manual_reminder_cooldown_minutes','manager_secure_link_days',
  'manager_first_delay_value','manager_first_delay_unit','manager_followups','manager_recent_completed_weeks','manager_max_work_age_days'];
begin
 perform private.weekly_contact_assert_closed_v1(p_request,array['actor_user_id','agency_id','environment','request_id','expected_settings_version','settings'],
  array['actor_user_id','agency_id','environment','request_id','expected_settings_version','settings'],'WEEKLY_SOURCE_GLOBAL_SETTINGS_SAVE_REQUEST_INVALID');
 actor:=private.weekly_contact_uuid_v1(p_request->'actor_user_id');agency:=private.weekly_contact_uuid_v1(p_request->'agency_id');
 v_request_id:=private.weekly_contact_uuid_v1(p_request->'request_id');expected:=private.weekly_contact_revision_v1(p_request->'expected_settings_version',true);
 perform private._weekly_source_settings_require_admin_v1(actor);
 if jsonb_typeof(p_request->'environment') is distinct from 'string' or not coalesce(p_request->>'environment' in('TEST','LIVE'),false) then
  raise exception 'WEEKLY_SOURCE_SETTINGS_DEPLOYMENT_INVALID' using errcode='22023';end if;
 perform private._weekly_source_settings_deployment_v1(agency,p_request->>'environment');
 settings:=p_request->'settings';
 perform private.weekly_contact_assert_closed_v1(settings,required||array['automatic_reconcile_actor_user_id'],required,'WEEKLY_SOURCE_GLOBAL_SETTINGS_VALUES_INVALID');
 foreach key in array array['candidate_reminder_minutes','candidate_response_deadline_minutes','manager_digest_minutes',
  'manager_manual_resend_cooldown_minutes','candidate_manual_reminder_cooldown_minutes','manager_secure_link_days',
  'manager_first_delay_value','manager_recent_completed_weeks','manager_max_work_age_days'] loop
  if jsonb_typeof(settings->key) is distinct from 'number' or settings->>key !~ '^[0-9]+$' or length(settings->>key)>5 then
   raise exception 'WEEKLY_SOURCE_GLOBAL_SETTINGS_VALUES_INVALID' using errcode='22023';end if;
 end loop;
 if not private.weekly_source_manager_followups_valid_v1(settings->'manager_followups')
  or not private.weekly_source_manager_interval_valid_v1((settings->>'manager_first_delay_value')::integer,settings->>'manager_first_delay_unit',true)
  or (settings->>'candidate_reminder_minutes')::integer not between 1 and 719
  or (settings->>'candidate_response_deadline_minutes')::integer not between (settings->>'candidate_reminder_minutes')::integer+1 and 10080
  or (settings->>'manager_digest_minutes')::integer not between 1 and 10080
  or (settings->>'manager_manual_resend_cooldown_minutes')::integer not between 5 and 1440
  or (settings->>'candidate_manual_reminder_cooldown_minutes')::integer not between 60 and 10080
  or (settings->>'manager_secure_link_days')::integer not between 1 and 30
  or (settings->>'manager_recent_completed_weeks')::integer not between 1 and 52
  or (settings->>'manager_max_work_age_days')::integer not between 1 and 366 then
  raise exception 'WEEKLY_SOURCE_GLOBAL_SETTINGS_VALUES_INVALID' using errcode='22023';end if;
 if settings?'automatic_reconcile_actor_user_id' and settings->'automatic_reconcile_actor_user_id'<>'null'::jsonb then
  perform 1 from public.tms_users u where u.id=private.weekly_contact_uuid_v1(settings->'automatic_reconcile_actor_user_id');
  if not found then raise exception 'WEEKLY_SOURCE_GLOBAL_SETTINGS_VALUES_INVALID' using errcode='22023';end if;
 end if;
 digest:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_GLOBAL_SETTINGS_SAVE_V1',p_request);
 -- One singleton lock serializes first-use request journals and the actual CAS.
 select x.* into strict s from public.weekly_source_global_settings x where x.singleton for update;
 select x.* into receipt from public.weekly_source_global_settings_receipts x where x.request_id=v_request_id;
 if found then
  if receipt.request_digest is distinct from digest or receipt.actor_user_id<>actor or receipt.agency_id<>agency
   or receipt.environment is distinct from p_request->>'environment' then raise exception 'WEEKLY_SOURCE_SETTINGS_REQUEST_REUSED' using errcode='40001';end if;
  return receipt.response_json;
 end if;
 if s.version<>expected then raise exception 'WEEKLY_SOURCE_SETTINGS_STALE' using errcode='40001';end if;
 next_s:=s;
 next_s.candidate_reminder_after:=make_interval(mins=>(settings->>'candidate_reminder_minutes')::integer);
 next_s.candidate_response_deadline_after:=make_interval(mins=>(settings->>'candidate_response_deadline_minutes')::integer);
 next_s.manager_partial_digest_after:=make_interval(mins=>(settings->>'manager_digest_minutes')::integer);
 next_s.manager_manual_send_cooldown:=make_interval(mins=>(settings->>'manager_manual_resend_cooldown_minutes')::integer);
 next_s.candidate_manual_reminder_cooldown:=make_interval(mins=>(settings->>'candidate_manual_reminder_cooldown_minutes')::integer);
 next_s.manager_secure_link_lifetime:=make_interval(days=>(settings->>'manager_secure_link_days')::integer);
 if settings?'automatic_reconcile_actor_user_id' then next_s.automatic_reconcile_actor_user_id:=(settings->>'automatic_reconcile_actor_user_id')::uuid;end if;
 next_s.manager_first_delay_value:=(settings->>'manager_first_delay_value')::integer;next_s.manager_first_delay_unit:=settings->>'manager_first_delay_unit';
 next_s.manager_followups:=settings->'manager_followups';next_s.manager_recent_completed_weeks:=(settings->>'manager_recent_completed_weeks')::integer;
 next_s.manager_max_work_age_days:=(settings->>'manager_max_work_age_days')::integer;
 if to_jsonb(next_s) is distinct from to_jsonb(s) then
  if s.version=9223372036854775807 then raise exception 'WEEKLY_SOURCE_SETTINGS_VERSION_EXHAUSTED' using errcode='22003';end if;
  update public.weekly_source_global_settings set candidate_reminder_after=next_s.candidate_reminder_after,
   candidate_response_deadline_after=next_s.candidate_response_deadline_after,manager_partial_digest_after=next_s.manager_partial_digest_after,
   manager_manual_send_cooldown=next_s.manager_manual_send_cooldown,candidate_manual_reminder_cooldown=next_s.candidate_manual_reminder_cooldown,
   manager_secure_link_lifetime=next_s.manager_secure_link_lifetime,automatic_reconcile_actor_user_id=next_s.automatic_reconcile_actor_user_id,
   manager_first_delay_value=next_s.manager_first_delay_value,manager_first_delay_unit=next_s.manager_first_delay_unit,
   manager_followups=next_s.manager_followups,manager_recent_completed_weeks=next_s.manager_recent_completed_weeks,
   manager_max_work_age_days=next_s.manager_max_work_age_days,version=version+1,updated_by_user_id=actor,updated_at_utc=v_now where singleton;
 end if;
 result:=public.weekly_source_global_settings_get_v1(jsonb_build_object('actor_user_id',actor,'agency_id',agency,'environment',p_request->>'environment'));
 insert into public.weekly_source_global_settings_receipts(request_id,agency_id,environment,actor_user_id,request_digest,
  expected_settings_version,accepted_settings_version,response_json,created_at_utc,completed_at_utc)
 values(v_request_id,agency,p_request->>'environment',actor,digest,expected,(result->>'settings_version')::bigint,result,v_now,v_now);
 return result;
end;
$function$;

-- Native timing readers only. Admission/current need/pause/cutoff remain final START owners.
create or replace function private.weekly_source_manager_interval_due_v1(
 p_client_id uuid,p_from_utc timestamptz,p_value integer,p_unit text
) returns timestamptz language plpgsql stable security definer set search_path='pg_catalog','private','pg_temp'
as $function$
declare local_start timestamp;d date;remaining integer:=p_value;searched integer:=0;effective jsonb;holidays jsonb;
begin
 if p_client_id is null or p_from_utc is null or not private.weekly_source_manager_interval_valid_v1(p_value,p_unit,true)
  or not exists(select 1 from public.clients c where c.id=p_client_id) then
  raise exception 'WEEKLY_SOURCE_MANAGER_TIMING_INVALID' using errcode='22023';end if;
 if p_value=0 then return p_from_utc;end if;
 if p_unit='HOURS' then return p_from_utc+make_interval(hours=>p_value);end if;
 local_start:=p_from_utc at time zone 'Europe/London';d:=local_start::date;
 if p_unit='CALENDAR_DAYS' then d:=d+p_value;
 else
  -- Read the same actual Client effective holiday list; its core already
  -- normalizes bh_list UNION bh_feed_list. No second calendar/feed/store.
  while remaining>0 loop
   searched:=searched+1;if searched>1098 then raise exception 'WEEKLY_SOURCE_MANAGER_CALENDAR_UNAVAILABLE' using errcode='P0001';end if;
   d:=d+1;
   if extract(isodow from d) in(6,7) then continue;end if;
   effective:=private._contract_settings_effective_core_v1(p_client_id,null,d,'OFFICE',null);
   holidays:=effective->'values'->'bh_list';
   if jsonb_typeof(holidays) is distinct from 'array' then raise exception 'WEEKLY_SOURCE_MANAGER_CALENDAR_UNAVAILABLE' using errcode='P0001';end if;
   if not(holidays?d::text) then remaining:=remaining-1;end if;
  end loop;
 end if;
 -- Shared London gap/overlap rule, retaining the genuine start's seconds.
 return private.weekly_contact_london_boundary_v1(d,date_trunc('minute',local_start)::time,false)
  +(local_start-date_trunc('minute',local_start));
end;
$function$;

create or replace function private.weekly_source_manager_matching_pending_v1(p_incident_id uuid)
returns boolean language sql stable security definer set search_path='pg_catalog','private','pg_temp'
as $function$
 select exists(
  select 1 from public.weekly_discrepancy_incidents i
  join public.weekly_issue_comparison_revisions c on c.id=i.current_comparison_revision_id
  join public.weekly_work_events w on w.id=i.work_event_id
  join public.timesheets t on t.timesheet_id=c.candidate_timesheet_id
   and t.version=c.candidate_timesheet_revision and t.contract_id=c.contract_id
  join public.contracts contract on contract.id=t.contract_id
   and contract.candidate_id=i.candidate_id and contract.client_id=i.client_id
  where i.id=p_incident_id and i.state='OPEN' and c.candidate_timesheet_id is not null
   and c.source_presence='UNFINALISED' and c.candidate_start_at_local is not null and c.candidate_end_at_local is not null
   and exists(select 1 from private.weekly_source_candidate_current_rows_v1(
    c.projection_publication_id,i.candidate_id,i.client_id,c.contract_id,
    t.week_ending_date) r
    where r.work_event_id=w.id and r.source_row_id=c.source_row_id and r.source_link_id=c.source_work_event_link_id
     and r.row_finalisation_state='SOURCE_UNFINALISED' and r.work_date=w.work_date
     and r.start_at_local=c.candidate_start_at_local and r.end_at_local=c.candidate_end_at_local
     and r.break_minutes is not distinct from c.candidate_break_minutes))
$function$;

create or replace function private.weekly_source_manager_initial_purpose_v1(p_incident_id uuid,p_route_mode text)
returns text language sql stable security definer set search_path='pg_catalog','private','pg_temp'
as $function$
 select case when p_route_mode='MANAGER_DIRECT' or private.weekly_source_manager_matching_pending_v1(p_incident_id)
  then 'MANAGER_DIRECT' when p_route_mode='CANDIDATE_FIRST' then 'CANDIDATE_FIRST' else null end
$function$;

-- An accepted native membership is the provenance; callers cannot invent an
-- accepted timestamp, reset a step, or use a generation/publication as budget.
create or replace function private.weekly_source_manager_followup_timing_v1(p_accepted_membership_id uuid,p_at_utc timestamptz)
returns jsonb language plpgsql stable security definer set search_path='pg_catalog','private','pg_temp'
as $function$
declare m public.weekly_contact_delivery_memberships%rowtype;i public.weekly_discrepancy_incidents%rowtype;
 w public.weekly_work_events%rowtype;s public.weekly_source_global_settings%rowtype;last_ordinal integer;accepted_count integer;
 last_at timestamptz;step jsonb;due timestamptz;local_today date;last_completed_sunday date;routine boolean;reason text;
begin
 if p_at_utc is null then raise exception 'WEEKLY_SOURCE_MANAGER_TIMING_INVALID' using errcode='22023';end if;
 select x.* into strict m from public.weekly_contact_delivery_memberships x where x.id=p_accepted_membership_id;
 if m.audience<>'MANAGER' or m.accepted_at_utc is null or m.incident_id is null then
  raise exception 'WEEKLY_SOURCE_MANAGER_ACCEPTED_SCOPE_INVALID' using errcode='42501';end if;
 select x.* into strict i from public.weekly_discrepancy_incidents x where x.id=m.incident_id;
 select x.* into strict w from public.weekly_work_events x where x.id=i.work_event_id;
 if m.candidate_id<>i.candidate_id or m.client_id<>i.client_id or m.work_event_id is distinct from i.work_event_id
  or m.incident_episode is distinct from i.episode_number then
  raise exception 'WEEKLY_SOURCE_MANAGER_ACCEPTED_SCOPE_INVALID' using errcode='42501';end if;
 if exists(select 1 from public.weekly_contact_delivery_memberships x where x.logical_contact_key=m.logical_contact_key
  and (x.audience<>'MANAGER' or x.incident_id is distinct from m.incident_id or x.incident_episode is distinct from m.incident_episode
   or x.candidate_id<>m.candidate_id or x.client_id<>m.client_id or x.work_event_id is distinct from m.work_event_id
   or x.purpose<>m.purpose or x.budget_owner_key<>m.budget_owner_key)) then
  raise exception 'WEEKLY_SOURCE_MANAGER_ACCEPTED_SCOPE_INVALID' using errcode='42501';end if;
 select max(x.send_ordinal),count(*) into last_ordinal,accepted_count
 from public.weekly_contact_delivery_memberships x where x.logical_contact_key=m.logical_contact_key and x.accepted_at_utc is not null;
 if accepted_count<>last_ordinal then raise exception 'WEEKLY_SOURCE_MANAGER_ACCEPTED_SEQUENCE_INVALID' using errcode='55000';end if;
 select x.accepted_at_utc into strict last_at from public.weekly_contact_delivery_memberships x
 where x.logical_contact_key=m.logical_contact_key and x.send_ordinal=last_ordinal and x.accepted_at_utc is not null;
 if last_at>p_at_utc or exists(select 1 from public.weekly_contact_delivery_memberships a
  join public.weekly_contact_delivery_memberships b on b.logical_contact_key=a.logical_contact_key and b.send_ordinal=a.send_ordinal+1
  where a.logical_contact_key=m.logical_contact_key and a.accepted_at_utc is not null and b.accepted_at_utc<a.accepted_at_utc) then
  raise exception 'WEEKLY_SOURCE_MANAGER_ACCEPTED_SEQUENCE_INVALID' using errcode='55000';end if;
 select x.* into strict s from public.weekly_source_global_settings x where x.singleton;
 step:=s.manager_followups->(last_ordinal-1);
 local_today:=(p_at_utc at time zone 'Europe/London')::date;
 last_completed_sunday:=local_today-extract(isodow from local_today)::integer;
 routine:=i.state='OPEN' and i.manager_action_state in('NOT_SENT','DUE','SENT')
  and w.work_date<=last_completed_sunday and w.work_date>last_completed_sunday-7*s.manager_recent_completed_weeks
  and w.work_date>=local_today-s.manager_max_work_age_days;
 reason:=case when not routine then 'OUTSIDE_ROUTINE_SCOPE' when step is null then 'FOLLOWUPS_COMPLETE' else 'SCHEDULED' end;
 if step is not null then due:=private.weekly_source_manager_interval_due_v1(m.client_id,last_at,(step->>'interval_value')::integer,step->>'interval_unit');end if;
 return jsonb_build_object('version','MANAGER_FOLLOWUP_TIMING_V1','policy_revision',s.version::text,
  'logical_contact_key',encode(m.logical_contact_key,'hex'),'incident_id',i.id,'incident_episode',i.episode_number,
  'last_accepted_at_utc',to_char(last_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'next_send_ordinal',case when step is null then null else last_ordinal+1 end,'mode',step->>'mode',
  'due_at_utc',case when due is null then null else to_char(due at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end,
  'routine_in_scope',routine,'reason',reason,'requires_current_start_admission',true);
end;
$function$;

-- Complete native scope predicate; exact (a) revision does not broaden a cohort.
create or replace function private.weekly_source_manager_due_event_covers_v1(p_event_id uuid,p_incident_id uuid)
returns boolean language sql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
  select exists(
    select 1 from public.weekly_manager_cohort_due_events event
    join public.weekly_candidate_cohorts cohort on cohort.id=event.candidate_cohort_id
    join public.weekly_discrepancy_incidents incident
      on incident.id=p_incident_id and incident.candidate_id=cohort.candidate_id
      and incident.source_cycle_id=cohort.source_cycle_id and incident.client_id=cohort.client_id
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    left join public.weekly_timesheet_submission_request_memberships requested on requested.id=event.requested_week_membership_id
    where event.id=p_event_id and not private.weekly_source_covered_hours_incident_v1(incident.id)
      and (case when event.not_finalised_comparison_revision_id is not null then
        event.not_finalised_comparison_revision_id=comparison.id
        and (comparison.issue_family='HEALTHROSTER_NOT_FINALISED' or private.weekly_source_expected_week_question_v1(incident.id))
        and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work_event.work_date)
        else not ((comparison.issue_family='HEALTHROSTER_NOT_FINALISED' or private.weekly_source_expected_week_question_v1(incident.id))
          and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work_event.work_date))
          or private.weekly_source_manager_matching_pending_v1(incident.id) end)
      -- New initial events are purpose tagged using their saved immutable native
      -- identity. Legacy EARLY_ALL/all-responded/requested-week scopes retain
      -- their existing predicate; this does not retag historical events.
      and (case
        when event.trigger_hash=private.weekly_source_sha256_jsonb_v1('WEEKLY_MANAGER_INITIAL_PURPOSE_DUE_V1',
          jsonb_build_object('recipient_generation_id',event.recipient_generation_id,'candidate_cohort_id',event.candidate_cohort_id,
            'event_kind',event.event_kind,'due_at_utc',to_char(event.due_at_utc at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'initial_purpose','MANAGER_DIRECT'))
          then exists(select 1 from public.weekly_manager_recipient_memberships m
            join public.weekly_route_activations a on a.id=m.route_activation_id
            where m.recipient_generation_id=event.recipient_generation_id and m.incident_id=incident.id
              and private.weekly_source_manager_initial_purpose_v1(incident.id,a.route_mode)='MANAGER_DIRECT')
        when event.trigger_hash=private.weekly_source_sha256_jsonb_v1('WEEKLY_MANAGER_INITIAL_PURPOSE_DUE_V1',
          jsonb_build_object('recipient_generation_id',event.recipient_generation_id,'candidate_cohort_id',event.candidate_cohort_id,
            'event_kind',event.event_kind,'due_at_utc',to_char(event.due_at_utc at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'initial_purpose','CANDIDATE_FIRST'))
          then exists(select 1 from public.weekly_manager_recipient_memberships m
            join public.weekly_route_activations a on a.id=m.route_activation_id
            where m.recipient_generation_id=event.recipient_generation_id and m.incident_id=incident.id
              and private.weekly_source_manager_initial_purpose_v1(incident.id,a.route_mode)='CANDIDATE_FIRST')
        else true end)
      and (event.requested_week_membership_id is null
      or (requested.state='SUBMITTED_WITH_ISSUES' and requested.client_id=incident.client_id
        and requested.contract_id=comparison.contract_id
        and work_event.work_date>requested.week_ending-7 and work_event.work_date<=requested.week_ending
        and incident.candidate_action_state='NOT_REQUIRED'))
  );
$function$;
alter function private.weekly_source_manager_due_event_covers_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_due_event_covers_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- Complete native generation owner; only unsigned import-authoritative (a) joins the existing secure manager path.
create or replace function private.weekly_source_query_manager_generation_v1(
  p_recipient_route_id uuid,
  p_trigger_kind text,
  p_started_at_utc timestamptz,
  p_force_new boolean default false
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_route public.weekly_manager_recipient_routes%rowtype;
  v_old public.weekly_manager_recipient_generations%rowtype;
  v_new public.weekly_manager_recipient_generations%rowtype;
  v_membership jsonb;
  v_hash bytea;
  v_generation integer;
  v_ordinal integer:=0;
  v_row record;
  v_candidate_generation public.weekly_candidate_outreach_generations%rowtype;
  v_settings public.weekly_source_global_settings%rowtype;
  v_event_kind text;
  v_due timestamptz;
  v_trigger_hash bytea;
begin
  if p_trigger_kind not in (
    'OFFICE_DIRECT','EARLY_ALL','T6_RESPONDED','T12_REMAINDER','NEW_INCIDENT','MANUAL_RESEND'
  ) or p_started_at_utc is null then
    raise exception 'WEEKLY_SOURCE_MANAGER_TRIGGER_INVALID' using errcode='22023';
  end if;
  select * into strict v_route
  from public.weekly_manager_recipient_routes
  where id=p_recipient_route_id for update;
  select * into v_old
  from public.weekly_manager_recipient_generations
  where id=v_route.current_generation_id and state='ACTIVE'
  for update;
  v_membership:=coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'activation_id',activation.id,
        'candidate_cohort_id',cohort.id,
        'candidate_generation_id',cohort.current_generation_id,
        'incident_id',incident.id,
        'comparison_revision_id',incident.current_comparison_revision_id,
        'initial_purpose',private.weekly_source_manager_initial_purpose_v1(incident.id,activation.route_mode)
      ) order by private.weekly_source_query_ascii_fold_v1(client.name) collate "C",
                 client.id::text collate "C",
                 private.weekly_source_query_ascii_fold_v1(coalesce(
                   nullif(candidate.display_name,''),
                   pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name)
                 )) collate "C",
                 candidate.id::text collate "C",work_event.work_date,
                 comparison.system_start_at_local,incident.id
    )
    from public.weekly_candidate_cohorts cohort
    join public.weekly_route_activations activation
      on activation.source_cycle_id=cohort.source_cycle_id
     and activation.candidate_id=cohort.candidate_id
     and activation.client_id=cohort.client_id
     and activation.audience_route='MANAGER'
     and activation.route_mode in ('CANDIDATE_FIRST','MANAGER_DIRECT')
    join public.weekly_discrepancy_incidents incident
      on incident.source_cycle_id=cohort.source_cycle_id
     and incident.candidate_id=cohort.candidate_id
     and incident.client_id=cohort.client_id
     and incident.state='OPEN'
     and incident.manager_potential_state='AVAILABLE'
      -- 04A section 6: "Resolved and manager-answered/waiting-source items are
      -- not reintroduced", and section 1: an item "already answered by the
      -- manager but waiting for a later source remains visible to Office and is
      -- never included again".  A genuinely new EPISODE of the same incident is
      -- different work, and the recheck owner already resets manager_action_state
      -- when it raises the episode; nothing else may resurrect an answer.
      and incident.manager_action_state in ('NOT_SENT','DUE','SENT')
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
     and (comparison.candidate_timesheet_id is not null
       or private.weekly_source_expected_week_question_v1(incident.id)
       or (comparison.issue_family='HEALTHROSTER_NOT_FINALISED' and private.weekly_source_is_import_authoritative_v1(
         incident.client_id,comparison.contract_id,(select work.work_date from public.weekly_work_events work where work.id=incident.work_event_id))))
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    join public.clients client on client.id=incident.client_id
    join public.candidates candidate on candidate.id=incident.candidate_id
    where cohort.source_cycle_id=v_route.source_cycle_id
      and cohort.manager_recipient_route_key=v_route.normalised_recipient_hash
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
  ),'[]'::jsonb);
  if pg_catalog.jsonb_array_length(v_membership)=0 then
    return pg_catalog.jsonb_build_object('ok',true,'status','NO_MANAGER_ACTIONABLE_INCIDENTS');
  end if;
  v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_MANAGER_MEMBERSHIP_V1',v_membership);
  if v_old.id is not null and v_old.membership_hash=v_hash and not p_force_new then
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','UNCHANGED','recipient_generation_id',v_old.id,
      'recipient_route_id',v_route.id,'membership_hash',pg_catalog.encode(v_hash,'hex')
    );
  end if;
  if v_old.id is not null then
    update public.weekly_manager_recipient_routes set current_generation_id=null where id=v_route.id;
    update public.weekly_manager_recipient_generations
    set state='SUPERSEDED',superseded_at_utc=pg_catalog.transaction_timestamp()
    where id=v_old.id;
    -- 04A section 8: "A later cohort merely becoming due is not a revocation
    -- event for an earlier accepted batch", and section 1: a later generation
    -- "cannot broaden, alter, supersede or revoke an already accepted earlier
    -- batch merely by becoming due".  The only express revocation the pack names
    -- is correcting a final source.  So an ACCEPTED batch and its live secure
    -- link survive this rotation untouched, and section 8's promise -- the
    -- manager "may answer some items, close the page and return later" -- keeps
    -- holding.
    --
    -- A batch whose render never reached provider submission (section 9) was
    -- never accepted: nothing was sent, its command and intent are retired just
    -- below, and the delivery start guard would refuse it anyway.  That batch is
    -- revoked here so its rows return to the unsent pool rather than being
    -- silently owned by an email nobody received.
    update public.weekly_manager_review_batches batch
    set state='REVOKED'
    from public.weekly_message_renders render
    where render.id=batch.message_render_id
      and batch.recipient_generation_id=v_old.id and batch.state='ACTIVE'
      and render.state not in ('SUBMISSION_STARTED','ACCEPTED','AMBIGUOUS');
    update public.weekly_manager_route_receipts receipt
    set state='REVOKED',revoked_at_utc=pg_catalog.transaction_timestamp()
    from public.weekly_manager_review_batches batch
    where batch.id=receipt.review_batch_id
      and receipt.recipient_generation_id=v_old.id and receipt.state='ACTIVE'
      and batch.state='REVOKED';
    update public.weekly_manager_review_items item
    set response_state='OBSOLETE'
    from public.weekly_manager_review_batches batch
    where batch.id=item.review_batch_id
      and batch.recipient_generation_id=v_old.id and batch.state='REVOKED'
      and item.response_state='UNANSWERED';
    update public.weekly_manager_cohort_due_events
    set state='RETIRED' where recipient_generation_id=v_old.id and state='PENDING';
    update public.weekly_message_intents
    set state='RETIRED'
    where recipient_generation_id=v_old.id and state in ('DUE','RENDERED');
    update public.weekly_message_dispatch_commands command
    set state='RETIRED'
    from public.weekly_message_intents intent
    where command.message_intent_id=intent.id
      and intent.recipient_generation_id=v_old.id
      and command.state in ('READY','LEASED');
    update public.weekly_message_renders render
    set state='STALE'
    from public.weekly_message_intents intent
    where render.message_intent_id=intent.id and intent.recipient_generation_id=v_old.id
      and render.state='CURRENT';
  end if;
  select coalesce(pg_catalog.max(generation_number),0)+1 into v_generation
  from public.weekly_manager_recipient_generations where recipient_route_id=v_route.id;
  insert into public.weekly_manager_recipient_generations(
    recipient_route_id,generation_number,trigger_kind,state,membership_hash
  ) values (v_route.id,v_generation,p_trigger_kind,'ACTIVE',v_hash)
  returning * into v_new;
  for v_row in
    select
      activation.id as activation_id,cohort.id as cohort_id,
      cohort.current_generation_id as candidate_generation_id,
      incident.id as incident_id,incident.current_comparison_revision_id
    from public.weekly_candidate_cohorts cohort
    join public.weekly_route_activations activation
      on activation.source_cycle_id=cohort.source_cycle_id
     and activation.candidate_id=cohort.candidate_id
     and activation.client_id=cohort.client_id
     and activation.audience_route='MANAGER'
     and activation.route_mode in ('CANDIDATE_FIRST','MANAGER_DIRECT')
    join public.weekly_discrepancy_incidents incident
      on incident.source_cycle_id=cohort.source_cycle_id
     and incident.candidate_id=cohort.candidate_id
     and incident.client_id=cohort.client_id
      and incident.state='OPEN' and incident.manager_potential_state='AVAILABLE'
      -- 04A section 6: "Resolved and manager-answered/waiting-source items are
      -- not reintroduced", and section 1: an item "already answered by the
      -- manager but waiting for a later source remains visible to Office and is
      -- never included again".  A genuinely new EPISODE of the same incident is
      -- different work, and the recheck owner already resets manager_action_state
      -- when it raises the episode; nothing else may resurrect an answer.
      and incident.manager_action_state in ('NOT_SENT','DUE','SENT')
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
     and (comparison.candidate_timesheet_id is not null
       or private.weekly_source_expected_week_question_v1(incident.id)
       or (comparison.issue_family='HEALTHROSTER_NOT_FINALISED' and private.weekly_source_is_import_authoritative_v1(
         incident.client_id,comparison.contract_id,(select work.work_date from public.weekly_work_events work where work.id=incident.work_event_id))))
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    join public.clients client on client.id=incident.client_id
    join public.candidates candidate on candidate.id=incident.candidate_id
    where cohort.source_cycle_id=v_route.source_cycle_id
      and cohort.manager_recipient_route_key=v_route.normalised_recipient_hash
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
    order by private.weekly_source_query_ascii_fold_v1(client.name) collate "C",
             client.id::text collate "C",
             private.weekly_source_query_ascii_fold_v1(coalesce(
               nullif(candidate.display_name,''),
               pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name)
             )) collate "C",
             candidate.id::text collate "C",work_event.work_date,
             comparison.system_start_at_local,incident.id
  loop
    -- A due-but-unsent row returns to the unsent pool, because the intent,
    -- command and render that made it due are retired above and this generation
    -- must be able to drive it again.  A SENT row stays SENT and a RESPONDED row
    -- keeps its answer: 04A section 1 forbids a later generation from altering
    -- an already accepted batch, and section 6 forbids reintroducing a
    -- manager-answered or waiting-source item.
    if p_trigger_kind='NEW_INCIDENT' then
      update public.weekly_discrepancy_incidents
      set manager_action_state='NOT_SENT',waiting_source_state='NOT_WAITING',
          reconciliation_state='UNRESOLVED'
      where id=v_row.incident_id
        and manager_action_state='DUE'
        and not private.weekly_source_query_manager_row_owned_v1(
          v_route.id,id,episode_number
        );
    end if;
    v_ordinal:=v_ordinal+1;
    insert into public.weekly_manager_recipient_memberships(
      recipient_generation_id,route_activation_id,candidate_outreach_generation_id,
      candidate_cohort_id,incident_id,comparison_revision_id,membership_role,ordinal
    ) values (
      v_new.id,v_row.activation_id,v_row.candidate_generation_id,v_row.cohort_id,
      v_row.incident_id,v_row.current_comparison_revision_id,'MANAGER_ACTIONABLE',v_ordinal
    );
  end loop;
  update public.weekly_manager_recipient_routes
  set current_generation_id=v_new.id where id=v_route.id;

  select * into strict v_settings from public.weekly_source_global_settings where singleton;
  for v_row in
    select distinct membership.candidate_cohort_id,cohort.client_id,
      private.weekly_source_manager_initial_purpose_v1(membership.incident_id,activation.route_mode) as route_mode
    from public.weekly_manager_recipient_memberships membership
    join public.weekly_route_activations activation on activation.id=membership.route_activation_id
    join public.weekly_candidate_cohorts cohort on cohort.id=membership.candidate_cohort_id
    where membership.recipient_generation_id=v_new.id
    order by membership.candidate_cohort_id,route_mode
  loop
    v_candidate_generation.id:=null;
    v_candidate_generation.started_at_utc:=null;
    v_candidate_generation.deadline_at_utc:=null;
    if v_row.route_mode='MANAGER_DIRECT' then
      v_event_kind:='EARLY_ALL';
      v_due:=private.weekly_source_manager_interval_due_v1(v_row.client_id,p_started_at_utc,v_settings.manager_first_delay_value,v_settings.manager_first_delay_unit);
    else
      select * into v_candidate_generation
      from public.weekly_candidate_outreach_generations
      where id=(select current_generation_id from public.weekly_candidate_cohorts where id=v_row.candidate_cohort_id);
      if not found then
        continue;
      end if;
      v_event_kind:='T6_RESPONDED';
      v_due:=v_candidate_generation.started_at_utc+v_settings.manager_partial_digest_after;
    end if;
    v_trigger_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_MANAGER_INITIAL_PURPOSE_DUE_V1',
      pg_catalog.jsonb_build_object(
        'recipient_generation_id',v_new.id,'candidate_cohort_id',v_row.candidate_cohort_id,
        'event_kind',v_event_kind,'due_at_utc',to_char(v_due at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'initial_purpose',v_row.route_mode
      )
    );
    insert into public.weekly_manager_cohort_due_events(
      recipient_generation_id,candidate_cohort_id,event_kind,cohort_started_at_utc,
      due_at_utc,state,trigger_hash
    ) values (
      v_new.id,v_row.candidate_cohort_id,v_event_kind,
      coalesce(v_candidate_generation.started_at_utc,p_started_at_utc),v_due,'PENDING',v_trigger_hash
    ) on conflict (recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
    if v_row.route_mode='CANDIDATE_FIRST' then
      v_event_kind:='T12_REMAINDER';
      v_due:=v_candidate_generation.deadline_at_utc;
      v_trigger_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_MANAGER_INITIAL_PURPOSE_DUE_V1',
        pg_catalog.jsonb_build_object(
          'recipient_generation_id',v_new.id,'candidate_cohort_id',v_row.candidate_cohort_id,
          'event_kind',v_event_kind,'due_at_utc',to_char(v_due at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'initial_purpose',v_row.route_mode
        )
      );
      insert into public.weekly_manager_cohort_due_events(
        recipient_generation_id,candidate_cohort_id,event_kind,cohort_started_at_utc,
        due_at_utc,state,trigger_hash
      ) values (
        v_new.id,v_row.candidate_cohort_id,v_event_kind,
        v_candidate_generation.started_at_utc,v_due,'PENDING',v_trigger_hash
      ) on conflict (recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
    end if;
  end loop;
  -- A requested signed week is a bounded exception, not a persistent route
  -- override. Recreate its exact due scope on generation rotation without
  -- changing its original completion time or touching Office choices.
  insert into public.weekly_manager_cohort_due_events(
    recipient_generation_id,candidate_cohort_id,event_kind,cohort_started_at_utc,
    due_at_utc,state,trigger_hash,requested_week_membership_id
  )
  select distinct v_new.id,membership.candidate_cohort_id,'EARLY_ALL',requested.completed_at_utc,
    requested.completed_at_utc,'PENDING',private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_REQUESTED_WEEK_MANAGER_DUE_V1',pg_catalog.jsonb_build_object(
        'recipient_generation_id',v_new.id,'requested_week_membership_id',requested.id)),requested.id
  from public.weekly_manager_recipient_memberships membership
  join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
  join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work_event on work_event.id=incident.work_event_id
  join public.weekly_timesheet_submission_requests request
    on request.source_cycle_id=incident.source_cycle_id and request.candidate_id=incident.candidate_id
  join public.weekly_timesheet_submission_request_memberships requested
    on requested.submission_request_id=request.id and requested.client_id=incident.client_id
    and requested.contract_id=comparison.contract_id and work_event.work_date>requested.week_ending-7
    and work_event.work_date<=requested.week_ending and requested.state='SUBMITTED_WITH_ISSUES'
  where membership.recipient_generation_id=v_new.id and incident.state='OPEN'
    and incident.candidate_action_state='NOT_REQUIRED'
    and not private.weekly_source_query_manager_row_owned_v1(v_route.id,incident.id,incident.episode_number)
  on conflict(recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
  return pg_catalog.jsonb_build_object(
    'ok',true,'status','CREATED','recipient_route_id',v_route.id,
    'recipient_generation_id',v_new.id,
    'membership_hash',pg_catalog.encode(v_new.membership_hash,'hex')
  );
end;
$function$;
alter function private.weekly_source_query_manager_generation_v1(uuid,text,timestamptz,boolean) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_query_manager_generation_v1(uuid,text,timestamptz,boolean) from public,anon,authenticated,service_role;

-- Publication-time manager-only dispatch on the existing secure QD queue.
-- Deferred questions create audit evidence only; no future-due mail is staged.
create or replace function private.weekly_source_not_finalised_dispatch_v1(p_publication_id uuid)
returns jsonb language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_publication public.weekly_source_projection_publications%rowtype;
  v_cycle public.weekly_source_cycles%rowtype; v_row record; v_context jsonb; v_generation jsonb;
  v_week date; v_count integer; v_monday timestamptz; v_key text; v_trigger bytea;
  v_route uuid; v_generation_id uuid; v_due_id uuid; v_intent uuid; v_due timestamptz;
  v_settings public.weekly_source_global_settings%rowtype;
  v_deferred integer:=0; v_queued integer:=0; v_no_route integer:=0;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict v_publication from public.weekly_source_projection_publications
    where id=p_publication_id and state='CURRENT' and authority_scope_kind='CYCLE' and correction_session_id is null;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_publication.source_cycle_id for update;
  perform private.weekly_source_query_current_publication_v1(v_cycle.id,v_publication.id);
  if v_publication.published_at_utc is null or not isfinite(v_publication.published_at_utc) then
    raise exception 'WEEKLY_SOURCE_NOT_FINALISED_PUBLICATION_CLOCK_INVALID' using errcode='55000'; end if;
  for v_row in
    select incident.*,comparison.id as comparison_id,comparison.contract_id,comparison.candidate_timesheet_id,
      comparison.material_comparison_fingerprint,work.work_date,sheet.week_ending_date as signed_week_ending
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      and comparison.incident_id=incident.id
      and (comparison.issue_family='HEALTHROSTER_NOT_FINALISED' or private.weekly_source_expected_week_question_v1(incident.id))
    join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id
      and work.client_id=incident.client_id and work.first_source_group_id=incident.source_group_id
    left join public.timesheets sheet on sheet.timesheet_id=comparison.candidate_timesheet_id
      and sheet.contract_id=comparison.contract_id and work.work_date between sheet.week_ending_date-6 and sheet.week_ending_date
    where incident.source_cycle_id=v_cycle.id and incident.state='OPEN'
      and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work.work_date)
      and (private.weekly_source_checking_client_scope_v1(v_publication.id) is null
        or incident.client_id=private.weekly_source_checking_client_scope_v1(v_publication.id))
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
    order by incident.id for update of incident
  loop
    update public.weekly_discrepancy_incidents set candidate_action_state='NOT_REQUIRED' where id=v_row.id;
    v_week:=v_row.signed_week_ending;
    if v_row.candidate_timesheet_id is not null and v_week is null then
      raise exception 'WEEKLY_SOURCE_NOT_FINALISED_WEEK_UNAVAILABLE' using errcode='55000'; end if;
    if v_week is null then
      select count(*),min(expected.week_ending_date) into v_count,v_week from public.contract_weeks expected
        where expected.contract_id=v_row.contract_id and expected.additional_seq=0 and not coalesce(expected.is_adjustment,false)
          and expected.status in ('PLANNED','OPEN','SUBMITTED')
          and v_row.work_date between expected.week_ending_date-6 and expected.week_ending_date;
      if v_count<>1 then raise exception 'WEEKLY_SOURCE_NOT_FINALISED_WEEK_UNAVAILABLE' using errcode='55000'; end if;
    end if;
    v_monday:=((v_week+(8-extract(isodow from v_week)::integer))::timestamp at time zone 'Europe/London');
    v_key:='NOT_FINALISED_DISPATCH:'||v_row.id::text||':'||v_row.comparison_id::text;
    if v_publication.published_at_utc<v_monday then
      if not exists(select 1 from public.audit_events audit where audit.action='WEEKLY_SOURCE_NOT_FINALISED_DISPATCH_DEFERRED'
        and audit.object_type='weekly_discrepancy_incident' and audit.object_id_text=v_row.id::text
        and audit.after_json->>'idempotency_key'=v_key and audit.event_sequence_is_authoritative) then
        perform public._audit_insert('weekly_discrepancy_incident',v_row.id::text,'WEEKLY_SOURCE_NOT_FINALISED_DISPATCH_DEFERRED',
          null,jsonb_build_object('idempotency_key',v_key,'comparison_revision_id',v_row.comparison_id,
            'projection_publication_id',v_publication.id,'week_ending_date',v_week,'first_monday_at_utc',v_monday),
          'Manager question waits for the first checking file on or after Monday',null);
      end if;
      v_deferred:=v_deferred+1; continue;
    end if;
    v_context:=private.weekly_source_query_cohort_ensure_v1(v_cycle.id,v_row.candidate_id,v_row.client_id,v_row.contract_id,v_row.work_date);
    if not coalesce((v_context->>'manager_queries_enabled')::boolean,false) or nullif(v_context->>'manager_route_id','') is null then
      v_no_route:=v_no_route+1; continue; end if;
    v_route:=(v_context->>'manager_route_id')::uuid;
    if private.weekly_source_query_manager_row_owned_v1(v_route,v_row.id,v_row.episode_number) then continue; end if;
    if exists(select 1 from public.weekly_route_activations activation where activation.source_cycle_id=v_cycle.id
      and activation.candidate_id=v_row.candidate_id and activation.client_id=v_row.client_id
      and activation.audience_route='MANAGER' and activation.route_mode in ('DISABLED','MANUAL_ONLY')) then
      v_no_route:=v_no_route+1; continue; end if;
    insert into public.weekly_route_activations(source_cycle_id,candidate_id,client_id,audience_route,route_mode,activated_at_utc,updated_at_utc)
    values(v_cycle.id,v_row.candidate_id,v_row.client_id,'MANAGER','CANDIDATE_FIRST',transaction_timestamp(),transaction_timestamp())
    on conflict(source_cycle_id,candidate_id,client_id,audience_route) do nothing;
    v_generation:=private.weekly_source_query_manager_generation_v1(v_route,'EARLY_ALL',v_publication.published_at_utc,false);
    v_generation_id:=nullif(v_generation->>'recipient_generation_id','')::uuid;
    if v_generation_id is null then raise exception 'WEEKLY_SOURCE_NOT_FINALISED_GENERATION_UNAVAILABLE' using errcode='55000'; end if;
    -- Native13 already owns the matching pending member's purpose-qualified
    -- direct event. Do not create a second immediate ingress for the same work.
    -- Unmatched not-finalised work retains this original exact revision scope.
    if private.weekly_source_manager_matching_pending_v1(v_row.id) then continue; end if;
    select * into strict v_settings from public.weekly_source_global_settings where singleton;
    v_due:=private.weekly_source_manager_interval_due_v1(v_row.client_id,v_publication.published_at_utc,
      v_settings.manager_first_delay_value,v_settings.manager_first_delay_unit);
    v_trigger:=private.weekly_source_sha256_jsonb_v1('WEEKLY_NOT_FINALISED_MANAGER_DUE_V1',
      jsonb_build_object('incident_id',v_row.id,'comparison_revision_id',v_row.comparison_id,
        'week_ending_date',v_week,'first_monday_at_utc',v_monday));
    insert into public.weekly_manager_cohort_due_events(recipient_generation_id,candidate_cohort_id,event_kind,
      cohort_started_at_utc,due_at_utc,state,trigger_hash,not_finalised_comparison_revision_id)
    values(v_generation_id,(v_context->>'cohort_id')::uuid,'EARLY_ALL',v_publication.published_at_utc,
      v_due,'PENDING',v_trigger,v_row.comparison_id)
    on conflict(recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
    select id into strict v_due_id from public.weekly_manager_cohort_due_events where recipient_generation_id=v_generation_id
      and candidate_cohort_id=(v_context->>'cohort_id')::uuid and event_kind='EARLY_ALL' and trigger_hash=v_trigger;
    if exists(select 1 from public.weekly_manager_cohort_due_events where id=v_due_id and state='CONSUMED') then continue; end if;
    -- A future event remains with the existing scheduler; it is not staged as
    -- a future-due email and it consumes no send allowance here.
    if v_due>clock_timestamp() then v_deferred:=v_deferred+1; continue; end if;
    if not private.weekly_source_manager_due_event_covers_v1(v_due_id,v_row.id) then
      raise exception 'WEEKLY_SOURCE_NOT_FINALISED_DUE_SCOPE_INVALID' using errcode='55000'; end if;
    v_intent:=private.weekly_source_query_manager_intent_v1(v_route,v_generation_id,array[v_due_id],
      'MANAGER_EARLY_ALL',1,v_publication.published_at_utc);
    update public.weekly_manager_cohort_due_events set state='CONSUMED' where id=v_due_id;
    update public.weekly_discrepancy_incidents set manager_action_state='DUE' where id=v_row.id and manager_action_state<>'RESPONDED';
    v_queued:=v_queued+1;
  end loop;
  return jsonb_build_object('ok',true,'deferred',v_deferred,'manager_intents_queued',v_queued,'manager_route_unavailable',v_no_route);
end;
$function$;
alter function private.weekly_source_not_finalised_dispatch_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_not_finalised_dispatch_v1(uuid) from public,anon,authenticated,service_role;

alter function private.weekly_source_manager_interval_valid_v1(integer,text,boolean) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_interval_valid_v1(integer,text,boolean) from public,anon,authenticated,service_role;
alter function private.weekly_source_manager_followups_valid_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_followups_valid_v1(jsonb) from public,anon,authenticated,service_role;
alter function private.weekly_source_global_settings_receipt_guard_v1() OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_global_settings_receipt_guard_v1() from public,anon,authenticated,service_role;
alter function private.weekly_source_manager_interval_due_v1(uuid,timestamptz,integer,text) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_interval_due_v1(uuid,timestamptz,integer,text) from public,anon,authenticated,service_role;
alter function private.weekly_source_manager_matching_pending_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_matching_pending_v1(uuid) from public,anon,authenticated,service_role;
alter function private.weekly_source_manager_initial_purpose_v1(uuid,text) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_initial_purpose_v1(uuid,text) from public,anon,authenticated,service_role;
alter function private.weekly_source_manager_followup_timing_v1(uuid,timestamptz) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_followup_timing_v1(uuid,timestamptz) from public,anon,authenticated,service_role;
alter function public.weekly_source_global_settings_get_v1(jsonb) OWNER TO CURRENT_USER;
alter function public.weekly_source_global_settings_save_atomic_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_global_settings_get_v1(jsonb),public.weekly_source_global_settings_save_atomic_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_source_global_settings_get_v1(jsonb),public.weekly_source_global_settings_save_atomic_v1(jsonb) to service_role;

notify pgrst, 'reload schema';


-- CONTACT_PREPARER_UNIT 147 repeatable supabase/repeatable/16102026_0319_weekly_contact_office_projection_v1.sql SHA256 1bec4c6eaaede70f25ccd35d563c54540f188afad63d2afbde3656eb2b47a631
-- Complete native combined read owner from b192e0433cd24c4e7027ec1ca91470a715e57584.
-- Original function SHA256 5d8b766785991b508a582b7ca80f82ac41a959f2866341e1ffcebd0891474b85; one bounded read-projection call.


-- Read projection only. Contact actions do not grant financial authority or
-- change issue status/counts. Each opening still uses current native GET.
create or replace function private.weekly_contact_office_rows_v1(p_rows jsonb,p_owners jsonb,p_actor uuid)
returns jsonb language plpgsql stable security definer
set search_path='pg_catalog','private','pg_temp'
as $function$
declare item jsonb;owner jsonb;result jsonb:='[]';candidate uuid;client uuid;
 source_group public.weekly_source_groups%rowtype;scope public.weekly_contact_pause_scopes%rowtype;
 at_utc timestamptz:=statement_timestamp();worker_paused boolean;manager_paused boolean;actions jsonb;summary jsonb;
begin
 perform private.weekly_source_query_require_service_v1();
 perform private._weekly_source_settings_require_admin_v1(p_actor);
 if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows)>100
  or jsonb_typeof(p_owners) is distinct from 'array' then raise exception 'CONTACT_DEPENDENCY_UNAVAILABLE' using errcode='P0001';end if;
 for item in select value from jsonb_array_elements(p_rows) loop
  -- Unresolved file-level rows have no actual worker/client contact scope.
  if item->>'candidate_id' is null or item->>'client_id' is null or item->>'scope_key' is null then
   result:=result||jsonb_build_array(item);continue;end if;
  candidate:=private.weekly_contact_uuid_v1(item->'candidate_id');client:=private.weekly_contact_uuid_v1(item->'client_id');
  select x into owner from jsonb_array_elements(p_owners)x where x->>'key'=item->>'scope_key';
  if not found then result:=result||jsonb_build_array(item);continue;end if;
  if (select count(*) from jsonb_array_elements(p_owners)x where x->>'key'=item->>'scope_key')<>1 then
   raise exception 'CONTACT_DEPENDENCY_UNAVAILABLE' using errcode='P0001';end if;
  -- The owner scope comes from the current authenticated native workspace,
  -- not a browser field, a manager address or a guessed adjacent Client.
  select g.* into strict source_group from public.weekly_source_cycles c
   join public.weekly_source_groups g on g.id=c.source_group_id
   where c.id=private.weekly_contact_uuid_v1(owner#>'{scope,source_cycle_id}')
    and g.id=private.weekly_contact_uuid_v1(owner#>'{scope,source_group_id}');
  select x.* into scope from public.weekly_contact_pause_scopes x
   where x.environment=source_group.environment and x.agency_id=source_group.agency_id
    and x.candidate_id=candidate and x.client_id=client;
  worker_paused:=coalesce(scope.worker_paused_until_utc>at_utc,false);
  manager_paused:=coalesce(scope.manager_paused_until_utc>at_utc,false);
  actions:=jsonb_build_array(jsonb_build_object('operation','PAUSE','label','Pause messages'));
  if worker_paused or manager_paused then actions:=actions||jsonb_build_array(jsonb_build_object('operation','RESUME','label','Resume messages'));end if;
  summary:=jsonb_build_object('version','CONTACT_CONTROLS_ROW_V1','candidate_id',candidate,'client_id',client,
   'scope_revision',coalesce(scope.revision,0)::text,
   'worker',jsonb_build_object('paused',worker_paused,'until_local',case when worker_paused then
    to_char(scope.worker_paused_until_utc at time zone 'Europe/London','DD/MM/YYYY HH24:MI')||' (UK)' end),
   'manager',jsonb_build_object('paused',manager_paused,'until_local',case when manager_paused then
    to_char(scope.manager_paused_until_utc at time zone 'Europe/London','DD/MM/YYYY HH24:MI')||' (UK)' end),
   'actions',actions);
  result:=result||jsonb_build_array(item||jsonb_build_object('contact_controls',summary));
 end loop;
 return result;
end;
$function$;
alter function private.weekly_contact_office_rows_v1(jsonb,jsonb,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_contact_office_rows_v1(jsonb,jsonb,uuid) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.weekly_source_combined_review_workspace_v1(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_pay_view boolean;
  v_result jsonb;
  v_request jsonb; v_scope_page jsonb; v_scopes jsonb:='[]'; v_scope jsonb;
  v_workspace jsonb; v_owner_request jsonb; v_rows jsonb:='[]'; v_item jsonb;
  v_manual_children jsonb; v_question_children jsonb; v_child jsonb;
  v_follow_workspace jsonb; v_follow_up jsonb;
  v_versions jsonb:='[]'; v_owners jsonb:='[]'; v_summary jsonb;
  v_tab text:=coalesce(nullif(p_request->>'tab',''),'queries');
  v_section text:=coalesce(nullif(p_request->>'section',''),'questions');
  v_sort text:=coalesce(nullif(p_request->>'sort_key',''),case when nullif(p_request->>'client_id','') is null then 'client' else 'candidate' end);
  v_direction text:=coalesce(nullif(p_request->>'sort_direction',''),'asc');
  v_seek text:=private.weekly_source_query_ascii_fold_v1(coalesce(p_request->>'seek',''));
  v_limit integer:=coalesce((p_request->>'limit')::integer,50);
  v_offset integer:=0; v_base integer:=0; v_total integer; v_page jsonb; v_counts jsonb;
  v_version text; v_cursor jsonb; v_client uuid; v_seen text[]:='{}'; v_key text; v_owner_key text;
  v_attention jsonb; v_attention_first boolean:=coalesce((p_request->>'attention_first')::boolean,false);
  v_attention_kind text:=coalesce(p_request->>'attention_kind','');
  v_released_scope record;
  v_pending record; v_pending_checks jsonb:='[]'::jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  perform private._weekly_source_settings_assert_request_v1(p_request,
    array['actor_user_id','source_group_id','client_id','week_ending','tab','section',
      'sort_key','sort_direction','seek','cursor','limit','report_key','attention_first','attention_kind'],'WEEKLY_SOURCE_COMBINED_REQUEST_INVALID');
  v_pay_view:=not exists(select 1 from public.tms_users actor
    where actor.id=(p_request->>'actor_user_id')::uuid and lower(btrim(coalesce(actor.role,'')))='admin');
  if v_pay_view then
    perform private.weekly_source_office_authority_v1((p_request->>'actor_user_id')::uuid,'VIEW_PAY_WORK');
    if v_tab<>'queries' or v_section not in ('questions','checks','protected') then
      raise exception 'WEEKLY_SOURCE_OFFICE_ADMIN_REQUIRED' using errcode='42501';
    end if;
  end if;
  if v_tab='history' then
    return public.weekly_source_report_history_v1(p_request-'tab'-'section');
  end if;
  if p_request ? 'report_key' then
    raise exception 'WEEKLY_SOURCE_COMBINED_REQUEST_INVALID' using errcode='22023';
  end if;
  if v_tab not in ('imports','queries') or v_section not in ('questions','checks','protected','current','archive')
    or v_sort not in ('client','candidate','day_date','status','file','uploaded')
    or v_direction not in ('asc','desc') or v_limit not between 1 and 100 or length(v_seek)>100
    or v_attention_kind not in ('','missing_source','questions','checks','protected')
    or (p_request ? 'attention_first' and jsonb_typeof(p_request->'attention_first')<>'boolean') then
    raise exception 'WEEKLY_SOURCE_COMBINED_REQUEST_INVALID' using errcode='22023';
  end if;
  v_client:=nullif(p_request->>'client_id','')::uuid;
  v_request:=p_request-'tab'-'section'-'sort_key'-'sort_direction'-'seek'-'cursor'-'limit'-'attention_first'-'attention_kind';
  loop
    v_scope_page:=public.weekly_source_workspace_scopes_v1(v_request);
    v_summary:=v_scope_page-'rows'-'next_cursor'-'has_more';
    v_scopes:=v_scopes||(v_scope_page->'rows');
    exit when not (v_scope_page->>'has_more')::boolean;
    v_request:=v_request||jsonb_build_object('cursor',v_scope_page->>'next_cursor');
  end loop;

  -- Checking-only released NHSP files have row-wise client authority. These
  -- review scopes are not report obligations and must never feed Finalise.
  -- Keep contract, charge and Hours questions visible for eligible row clients
  -- even when they are outside the final backing report's source membership.
  if v_tab='queries' then
    for v_released_scope in
      select distinct cycle.id cycle_id,cycle.source_group_id,
        cycle.finalisation_week_ending,cycle.cutoff_at_utc,
        source_group.display_name source_name,resolution.client_id,client.name client_name,
        upload.id upload_id,publication.id publication_id
      from public.weekly_source_cycles cycle
      join public.weekly_source_groups source_group on source_group.id=cycle.source_group_id
      join public.weekly_source_uploads upload on upload.id=cycle.current_complete_upload_id
        and upload.source_cycle_id=cycle.id and upload.state='CURRENT' and upload.report_scope_id is null
      join public.weekly_source_format_profiles profile on profile.id=upload.source_format_profile_id
      join public.weekly_source_projection_publications publication on publication.upload_id=upload.id
        and publication.source_cycle_id=cycle.id and publication.authority_scope_kind='CYCLE'
        and publication.report_scope_id is null and publication.authority_scope_version=cycle.version
      left join private.weekly_source_office_rechecks recheck on recheck.publication_id=publication.id
      left join public.weekly_source_projection_publications prior_publication on prior_publication.id=recheck.prior_publication_id
      join public.weekly_source_upload_rows source_row on source_row.upload_id=upload.id
      join public.weekly_source_row_resolutions resolution on resolution.upload_row_id=source_row.id
        and resolution.generation=case when publication.state='CURRENT'
          then coalesce(publication.projection_generation,publication.authority_scope_version)
          else coalesce(prior_publication.projection_generation,prior_publication.authority_scope_version) end
      join public.clients client on client.id=resolution.client_id
      where source_group.active and source_group.source_family='NHSP'
        and profile.profile_code='NHSP_PREFINAL_RELEASED_V1'
        and profile.row_finalisation_capability='CHECKING_ONLY' and not profile.single_client_required
        and ((publication.state='CURRENT' and cycle.current_projection_publication_id=publication.id)
          or (publication.state='BUILDING' and recheck.upload_id=upload.id))
        and (nullif(p_request->>'source_group_id','') is null or cycle.source_group_id=(p_request->>'source_group_id')::uuid)
        and (v_client is null or resolution.client_id=v_client)
        and (nullif(p_request->>'week_ending','') is null or cycle.finalisation_week_ending=(p_request->>'week_ending')::date)
        and private.weekly_source_upload_client_eligible_v1(upload.id,resolution.client_id,source_row.work_date)
        and not exists(select 1 from jsonb_array_elements(v_scopes) existing
          where existing->>'source_cycle_id'=cycle.id::text and existing->>'client_id'=resolution.client_id::text)
      order by cycle.id,resolution.client_id,publication.id
    loop
      perform private.weekly_source_office_authority_v1((p_request->>'actor_user_id')::uuid,
        case when v_pay_view then 'VIEW_PAY_WORK' else 'VIEW_SOURCE_PROGRESS' end,v_released_scope.source_group_id);
      v_scopes:=v_scopes||jsonb_build_array(jsonb_build_object(
        'key',v_released_scope.cycle_id::text||':'||v_released_scope.client_id::text||':RELEASED_REVIEW',
        'source_group_id',v_released_scope.source_group_id,'source_cycle_id',v_released_scope.cycle_id,
        'report_scope_id',null,'client_id',v_released_scope.client_id,'client',v_released_scope.client_name,
        'source',v_released_scope.source_name,'source_family','NHSP',
        'week_ending',v_released_scope.finalisation_week_ending,
        'period',to_char(v_released_scope.finalisation_week_ending,'FMDD Mon YYYY'),
        'cutoff',v_released_scope.cutoff_at_utc,'upload_id',v_released_scope.upload_id,
        'projection_publication_id',v_released_scope.publication_id,
        'review_only',true,'prepared',false,'completed',false,'completion_kind',null,
        'missing_previous_report',false));
    end loop;
  end if;

  -- A cycle publication is shared across its client scopes. If it has no
  -- cycle publication, each NHSP client's current report scope can instead
  -- own distinct query work. Visit each such scope exactly once.
  for v_scope in select distinct on (item->>'source_cycle_id',
      case when v_tab='queries' and cycle.current_projection_publication_id is null then item->>'client_id' else '' end)
      item||jsonb_build_object('cycle_publication_id',cycle.current_projection_publication_id)
    from jsonb_array_elements(v_scopes) item
    join public.weekly_source_cycles cycle on cycle.id=(item->>'source_cycle_id')::uuid
    order by item->>'source_cycle_id',
      case when v_tab='queries' and cycle.current_projection_publication_id is null then item->>'client_id' else '' end,
      case when item->>'report_scope_id' is null then 1 else 0 end,
      item->>'cutoff' desc nulls last,item->>'key'
  loop
    v_owner_request:=jsonb_build_object('actor_user_id',p_request->>'actor_user_id',
      'tab',v_tab,'source_group_id',v_scope->>'source_group_id',
      'source_cycle_id',v_scope->>'source_cycle_id','limit',100);
    if v_scope->>'source_family'='ROSTER' or
      (v_tab='queries' and v_scope->>'source_family'='NHSP' and v_scope->>'cycle_publication_id' is null
        and v_scope->>'report_scope_id' is not null) then
      v_owner_request:=v_owner_request||jsonb_build_object('client_id',v_scope->>'client_id');
    end if;
    if v_tab='queries' and v_scope->>'source_family'='NHSP' and v_scope->>'cycle_publication_id' is null
      and v_scope->>'report_scope_id' is not null then
      v_owner_request:=v_owner_request||jsonb_build_object('report_scope_id',v_scope->>'report_scope_id');
    end if;
    loop
      v_workspace:=public.weekly_source_office_workspace_v1(v_owner_request);
      v_owner_key:=case when v_tab='imports' then v_scope->>'source_cycle_id'
        else (v_scope->>'source_cycle_id')||':'||
          coalesce(v_workspace#>>'{selected,projection_publication_id}','none') end;
      v_versions:=v_versions||jsonb_build_array(jsonb_build_array(v_scope->>'source_cycle_id',v_workspace->>'workspace_version'));
      if not (v_owner_request ? 'cursor') then
        v_owners:=v_owners||jsonb_build_array(jsonb_build_object('key',v_owner_key,
          'source',v_scope->>'source','period',v_scope->>'period','scope',v_workspace->'selected',
          'bulk_actions',v_workspace#>'{queries,bulk_actions}',
          'protected_pay_enabled',v_workspace#>'{queries,protected_pay_enabled}'));
      end if;
      for v_item in select item from jsonb_array_elements(coalesce(v_workspace#>array[v_tab,'rows'],'[]')) item
      loop
        v_key:=v_tab||':'||v_owner_key;
        v_key:=v_key||':'||(v_item->>'row_key');
        if v_key=any(v_seen) then continue; end if;
        v_seen:=array_append(v_seen,v_key);
        if nullif(v_item->>'client_id','') is not null and not exists(select 1
          from jsonb_array_elements(v_scopes) permitted where permitted->>'source_cycle_id'=v_scope->>'source_cycle_id'
            and permitted->>'client_id'=v_item->>'client_id') then continue; end if;
        if v_client is not null and nullif(v_item->>'client_id','') is not null
          and (v_item->>'client_id')::uuid<>v_client then continue; end if;
        if v_tab='imports' then
          -- Upload errors remain in their immediate review receipt, not an
          -- ever-growing archive. Retain only accepted current work here.
          if v_item->>'state' is distinct from 'CURRENT' then continue; end if;
          if exists(select 1 from public.weekly_source_final_revisions revision
            join public.weekly_source_client_manifests manifest on manifest.final_revision_id=revision.id
            where revision.upload_id=(v_item->>'row_key')::uuid
              and revision.state in ('CURRENT','SUPERSEDED')
              and (nullif(v_item->>'client_id','') is null
                or manifest.client_id=(v_item->>'client_id')::uuid))
            and not exists(select 1 from jsonb_array_elements(v_scopes) sibling
              where sibling->>'upload_id'=v_item->>'row_key'
                and not coalesce((sibling->>'completed')::boolean,false)) then continue; end if;
        end if;
        if v_tab='queries' then
          -- An Office-created pay review is an Office check, not a request for
          -- candidate/manager hours evidence. Split only those children so a
          -- mixed group can retain its genuine Hours questions independently.
          select coalesce(jsonb_agg(child.value order by child.ordinality)
              filter(where child.value ? 'manual_review_id'),'[]'::jsonb),
            coalesce(jsonb_agg(child.value order by child.ordinality)
              filter(where not (child.value ? 'manual_review_id')),'[]'::jsonb)
            into v_manual_children,v_question_children
          from jsonb_array_elements(coalesce(v_item->'children','[]'::jsonb))
            with ordinality child(value,ordinality);
          for v_child in select value from jsonb_array_elements(v_manual_children)
          loop
            v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
              'combined_key','manual-check:'||(v_child->>'manual_review_id'),
              'row_key',v_child->>'row_key','section','checks',
              'scope_key',v_owner_key,
              'source',v_scope->>'source','source_family',v_scope->>'source_family',
              'period',v_scope->>'period',
              'client',v_item->>'client','client_id',v_item->>'client_id',
              'candidate',v_item->>'candidate','candidate_id',v_item->>'candidate_id',
              'day_date',v_child->>'day_date','system_hours',v_child->>'system_hours',
              'status',v_child->'status','manual_query',v_child->'manual_query',
              'problem','Accept current source hours or protect pay.',
              'pay_blocking',true,'actions',v_child->'actions'));
          end loop;
          if jsonb_array_length(v_question_children)=0 then continue; end if;
          if jsonb_array_length(v_manual_children)>0 then
            v_item:=jsonb_set(v_item,'{actions,0,payload,detail,shifts}',v_question_children,false)
              ||jsonb_build_object('children',v_question_children,
                'issues',greatest(0,coalesce((v_item->>'issues')::integer,0)
                  -jsonb_array_length(v_manual_children)));
          end if;
        end if;
        v_rows:=v_rows||jsonb_build_array(v_item||jsonb_build_object(
          'combined_key',v_key,'scope_key',v_owner_key,'source',v_scope->>'source',
          'source_family',v_scope->>'source_family',
          'period',v_scope->>'period','section',case when v_tab='queries' then 'questions' else 'current' end,
          'client',coalesce(nullif(v_item->>'client',''),(select name from public.clients
            where id=nullif(v_item->>'client_id','')::uuid),'Source-wide file')));
      end loop;
      if v_tab='queries' and not (v_owner_request ? 'cursor') then
        for v_item in
          select item||jsonb_build_object('section','checks') from jsonb_array_elements(coalesce(v_workspace#>'{queries,office_checks,rows}','[]')) item
          union all
          select item||jsonb_build_object('section','protected') from jsonb_array_elements(coalesce(v_workspace#>'{queries,protected_shifts,rows}','[]')) item
        loop
          v_key:=case when v_item->>'section'='protected' then
            'protected:'||(v_item->>'family_id')||':'||(v_item->>'work_event_id')
            else (v_item->>'section')||':'||v_owner_key||':'||(v_item->>'row_key') end;
          if v_key=any(v_seen) then continue; end if;
          v_seen:=array_append(v_seen,v_key);
          if nullif(v_item->>'client_id','') is not null and not exists(select 1
            from jsonb_array_elements(v_scopes) permitted where permitted->>'source_group_id'=v_scope->>'source_group_id'
              and permitted->>'client_id'=v_item->>'client_id') then continue; end if;
          if v_client is not null and nullif(v_item->>'client_id','') is not null
            and (v_item->>'client_id')::uuid<>v_client then continue; end if;
          v_rows:=v_rows||jsonb_build_array(v_item||jsonb_build_object('combined_key',v_key,
            'scope_key',v_owner_key,'source',v_scope->>'source','period',
              case when v_item->>'section'='protected' then 'Awaiting source period' else v_scope->>'period' end));
        end loop;
      end if;
      exit when not coalesce((v_workspace#>>array[v_tab,'has_more'])::boolean,false);
      v_owner_request:=v_owner_request||jsonb_build_object('cursor',v_workspace#>>array[v_tab,'next_cursor']);
    end loop;
  end loop;
  -- Finalisation does not complete its separately tracked approved-hours work.
  -- Keep that exact owner/action reachable from outstanding Office checks.
  if v_tab='queries' and not v_pay_view then
    for v_scope in select item from jsonb_array_elements(v_scopes) item
      where item->>'completion_kind'='FINAL_SOURCE'
    loop
      v_follow_workspace:=public.weekly_source_office_workspace_v1(jsonb_build_object(
        'actor_user_id',p_request->>'actor_user_id','tab','finalise',
        'source_group_id',v_scope->>'source_group_id','source_cycle_id',v_scope->>'source_cycle_id',
        'client_id',v_scope->>'client_id','report_scope_id',v_scope->>'report_scope_id'));
      v_follow_up:=v_follow_workspace#>'{finalise,approved_hours_follow_up}';
      if nullif(v_follow_up->>'title','') is null then continue; end if;
      v_key:='approved-hours:'||(v_scope->>'key');
      v_versions:=v_versions||jsonb_build_array(jsonb_build_array(v_key,v_follow_workspace->>'workspace_version',v_follow_up));
      v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
        'combined_key',v_key,'row_key',v_key,'section','checks',
        'client',v_scope->>'client','client_id',v_scope->>'client_id',
        'source',v_scope->>'source','period',v_scope->>'period',
        'candidate','Report follow-up','requires_attention',
          v_follow_up->>'state' in ('ACTION_REQUIRED','RECOVERY_REQUIRED')
          or jsonb_typeof(v_follow_up->'action')='object',
        'status',jsonb_build_object('text',v_follow_up->>'title'),
        'problem',v_follow_up->>'body','follow_up_scope',v_follow_workspace->'selected','actions','[]'::jsonb));
    end loop;
  end if;
  -- Rechecks invalidate the old authority before the replacement is ready.
  -- Retain old unresolved rows as explicitly non-actionable history, with only
  -- the exact saved recheck available. Never treat a missing CURRENT pointer
  -- as proof that Office has no work remaining.
  if v_tab='queries' and not v_pay_view then
    for v_pending in
      select recheck.request_id,recheck.actor_user_id,recheck.request_json,
        recheck.upload_id,recheck.publication_id,source_row.id as upload_row_id,
        source_row.work_date,source_row.source_client_identity,source_row.source_candidate_identity,
        source_row.external_source_key,source_row.start_at_local,source_row.end_at_local,source_row.break_minutes,
        coalesce(candidate.display_name,source_row.bounded_raw_columns_json->>'worker_name',
          source_row.bounded_raw_columns_json->>'candidate',source_row.source_candidate_identity) as candidate_name,
        resolution.mapping_state,charge.phase_severity,cycle.source_group_id,cycle.finalisation_week_ending,
        (select item->>'source' from jsonb_array_elements(v_scopes) item
          where item->>'source_cycle_id'=cycle.id::text limit 1) as source_name
      from private.weekly_source_office_rechecks recheck
      join public.weekly_source_projection_publications publication on publication.id=recheck.publication_id
      join public.weekly_source_projection_publications prior_publication on prior_publication.id=recheck.prior_publication_id
      join public.weekly_source_uploads upload on upload.id=recheck.upload_id
      join public.weekly_source_cycles cycle on cycle.id=upload.source_cycle_id
      left join public.weekly_source_report_scopes scope on scope.id=upload.report_scope_id
      join public.weekly_source_upload_rows source_row on source_row.upload_id=upload.id
      join public.weekly_source_row_resolutions resolution on resolution.upload_row_id=source_row.id
        and resolution.generation=coalesce(prior_publication.projection_generation,prior_publication.authority_scope_version)
      left join public.weekly_source_charge_checks charge on charge.upload_row_id=source_row.id
        and charge.generation=resolution.generation
      left join public.candidates candidate on candidate.id=coalesce(
        (select choice.candidate_id from private.weekly_source_office_row_choices choice
          where choice.upload_row_id=source_row.id order by choice.id desc limit 1),resolution.candidate_id)
      where publication.state='BUILDING' and upload.state='CURRENT'
        and publication.authority_scope_version=case when upload.report_scope_id is null then cycle.version else scope.version end
        and upload.id=case when upload.report_scope_id is null then cycle.current_complete_upload_id else scope.current_complete_upload_id end
        and exists(select 1 from jsonb_array_elements(v_scopes) item where item->>'source_cycle_id'=cycle.id::text)
        and (v_client is null or resolution.client_id=v_client or scope.client_id=v_client)
      order by recheck.request_id,source_row.source_row_ordinal
    loop
      v_key:='recheck:'||v_pending.request_id::text||':'||v_pending.upload_row_id::text;
      v_pending_checks:=v_pending_checks||jsonb_build_array(jsonb_build_object(
        'combined_key',v_key,'row_key',v_key,'section','checks','recheck_pending',true,
        'client',v_pending.source_client_identity,'candidate',v_pending.candidate_name,
        'source_reference',v_pending.source_candidate_identity,'booking_reference',v_pending.external_source_key,
        'source',v_pending.source_name,'period',to_char(v_pending.finalisation_week_ending,'FMDD Mon YYYY'),
        'work_date',v_pending.work_date,'day_date',to_char(v_pending.work_date,'FMDD Mon YYYY'),
        'system_hours',to_char(v_pending.start_at_local,'HH24:MI')||'–'||to_char(v_pending.end_at_local,'HH24:MI')
          ||' · '||v_pending.break_minutes::text||' min break',
        'pay_blocking',v_pending.mapping_state<>'RESOLVED',
        'status',jsonb_build_object('text','Recheck incomplete'),
        'problem',case when v_pending.mapping_state<>'RESOLVED' then 'Previous linking check — selection saved; replacement check incomplete.'
          when v_pending.phase_severity in ('PROVISIONAL_WARNING','FINALISATION_BLOCKER') then 'Previous contract charge warning — replacement check incomplete.'
          else 'Previous check — replacement check incomplete.' end,
        'actions',jsonb_build_array(jsonb_build_object('label','Retry recheck',
          'enabled',v_pending.actor_user_id=(p_request->>'actor_user_id')::uuid,
          'command','RECHECK_SOURCE','payload',v_pending.request_json-'actor_user_id'))));
    end loop;
    v_rows:=v_rows||v_pending_checks;
    v_summary:=v_summary||jsonb_build_object('recheck_pending_count',jsonb_array_length(v_pending_checks));
  end if;
  -- Classify the complete permitted collection before counting or paging.
  -- A waiting signature alone is informational; red unresolved work and green
  -- charge/reconciliation decisions remain visible and count as Office work.
  select coalesce(jsonb_agg(item||jsonb_build_object(
    'attention_missing_source_count',case when item->>'section'='questions' then
      (select count(*) from jsonb_array_elements(coalesce(item->'children','[]')) child
        where child->'candidate_shift_absent_from_import'='true'::jsonb) else 0 end,
    'attention_question_count',case when item->>'section'='questions' then
      (select count(*) from jsonb_array_elements(coalesce(item->'children','[]')) child
        where child->>'issue' is distinct from 'Timesheet missing'
          and child->'candidate_shift_absent_from_import' is distinct from 'true'::jsonb) else 0 end,
    'requires_attention',case
    when item->>'section'='questions' then exists(select 1
      from jsonb_array_elements(coalesce(item->'children','[]')) child
      where child->>'issue' is distinct from 'Timesheet missing')
    when item->>'section'='checks' then case when item ? 'follow_up_scope'
      then coalesce((item->>'requires_attention')::boolean,false) else true end
    when item->>'section'='protected' then coalesce((item->>'requires_attention')::boolean,false)
    else false end)),'[]') into v_rows from jsonb_array_elements(v_rows) item;
  select jsonb_build_object('missing_source',coalesce(sum((item->>'attention_missing_source_count')::integer),0),
    'questions',coalesce(sum((item->>'attention_question_count')::integer),0),
    'checks',count(*) filter(where item->>'section'='checks'),
    'protected',count(*) filter(where item->>'section'='protected'),
    'total',coalesce(sum((item->>'attention_missing_source_count')::integer
      +(item->>'attention_question_count')::integer),0)
      +count(*) filter(where item->>'section' in ('checks','protected')),'complete',true) into v_attention
  from jsonb_array_elements(v_rows) item where item->'requires_attention'='true'::jsonb;
  select jsonb_build_object('questions',count(*) filter(where item->>'section'='questions'),
    'checks',count(*) filter(where item->>'section'='checks'),'protected',count(*) filter(where item->>'section'='protected'),
    'current',count(*) filter(where item->>'section'='current'),'archive',count(*) filter(where item->>'section'='archive'))
    into v_counts from jsonb_array_elements(v_rows) item;
  v_version:=encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_COMBINED_REVIEW_V1',
    jsonb_build_object('scopes',v_summary->>'version','owners',v_versions,'attention_rows',v_rows,
      'filters',p_request-'cursor'-'limit')),'hex');
  -- Attention is an exact view filter, not a tab-total alias. The full census
  -- above stays intact; only this page collection is narrowed. Never rewrite
  -- server-owned action selections or comparison/financial proof payloads.
  if v_attention_kind<>'' then
    select coalesce(jsonb_agg(item),'[]') into v_rows from jsonb_array_elements(v_rows) item
    where item->'requires_attention'='true'::jsonb and case v_attention_kind
      when 'missing_source' then item->>'section'='questions' and (item->>'attention_missing_source_count')::integer>0
      when 'questions' then item->>'section'='questions' and (item->>'attention_question_count')::integer>0
      when 'checks' then item->>'section'='checks'
      when 'protected' then item->>'section'='protected'
      else false end;
    if v_attention_kind in ('missing_source','questions') then
      for v_item in select item from jsonb_array_elements(v_rows) item
      loop
        select coalesce(jsonb_agg(child.value order by child.ordinality),'[]') into v_question_children
          from jsonb_array_elements(v_item->'children') with ordinality child(value,ordinality)
          where child.value->>'issue' is distinct from 'Timesheet missing' and case v_attention_kind
            when 'missing_source' then child.value->'candidate_shift_absent_from_import'='true'::jsonb
            else child.value->'candidate_shift_absent_from_import' is distinct from 'true'::jsonb end;
        v_item:=v_item||jsonb_build_object('children',v_question_children,'issues',jsonb_array_length(v_question_children),
          'actions',(select coalesce(jsonb_agg(case when action->>'label'='Open'
            then jsonb_set(action,'{payload,detail,shifts}',v_question_children,false) else action end),'[]')
            from jsonb_array_elements(coalesce(v_item->'actions','[]')) action));
        select coalesce(jsonb_agg(case when item->>'combined_key'=v_item->>'combined_key' then v_item else item end),'[]')
          into v_rows from jsonb_array_elements(v_rows) item;
      end loop;
    end if;
  end if;
  if nullif(p_request->>'cursor','') is not null then
    begin
      v_cursor:=convert_from(decode(p_request->>'cursor','base64'),'UTF8')::jsonb;
      v_offset:=(v_cursor->>'offset')::integer;
      if v_offset is null or v_offset<0 or v_cursor->>'version' is distinct from v_version then raise exception 'stale'; end if;
    exception when others then raise exception 'WEEKLY_SOURCE_WORKSPACE_CURSOR_STALE' using errcode='40001'; end;
  end if;
  with keyed as (
    select item,private.weekly_source_query_ascii_fold_v1(coalesce(case v_sort
      when 'candidate' then coalesce(item->>'candidate_sort',item->>'candidate') when 'client' then item->>'client'
      when 'day_date' then item->>'work_date' when 'file' then item->>'file' when 'uploaded' then item->>'uploaded_at'
      when 'status' then item#>>'{status,text}' end,'')) sort_value
    from jsonb_array_elements(v_rows) item where item->>'section'=v_section
  ), ordered as (
    select *,row_number() over(order by case when v_attention_first and v_seek='' then
      case v_attention_kind when 'missing_source' then ((item->>'attention_missing_source_count')::integer>0)::integer
        when 'questions' then ((item->>'attention_question_count')::integer>0)::integer
        else 0 end else 0 end desc,
      case when v_attention_first and v_seek=''
      then coalesce((item->>'requires_attention')::boolean,false)::integer else 0 end desc,
      case when v_direction='asc' then sort_value end collate "C" asc,
      case when v_direction='desc' then sort_value end collate "C" desc,
      private.weekly_source_query_ascii_fold_v1(item->>'client') collate "C",
      private.weekly_source_query_ascii_fold_v1(coalesce(item->>'candidate_sort',item->>'candidate')) collate "C",
      item->>'work_date',item->>'combined_key') ordinal from keyed
  ), origin as (select coalesce(min(ordinal) filter(where v_seek<>'' and starts_with(sort_value,v_seek)),1)-1 base from ordered)
  select count(*)::integer,coalesce(max(origin.base),0)::integer,coalesce(jsonb_agg(item order by ordinal)
    filter(where ordinal>origin.base+v_offset and ordinal<=origin.base+v_offset+v_limit),'[]')
    into v_total,v_base,v_page from ordered cross join origin;
  -- Pause controls enrich only the permitted current page. Payment-only
  -- projections never expose contact controls; their current guards remain.
  if not v_pay_view then
    v_page:=private.weekly_contact_office_rows_v1(v_page,v_owners,(p_request->>'actor_user_id')::uuid);
  end if;
  v_result:=jsonb_build_object('ok',true,'contract','WEEKLY_SOURCE_COMBINED_REVIEW_V1','tab',v_tab,'section',v_section,
    'version',v_version,'rows',v_page,'total_count',v_total,'owners',v_owners,'scope_options',v_scopes,
    'summary',v_summary,'counts',v_counts,'attention',v_attention,
    'attention_kind',v_attention_kind,
    'sort_key',v_sort,'sort_direction',v_direction,
    'has_more',v_base+v_offset+v_limit<v_total,'next_cursor',case when v_base+v_offset+v_limit<v_total
      then encode(convert_to(jsonb_build_object('version',v_version,'offset',v_offset+v_limit)::text,'UTF8'),'base64') else '' end);
  if v_pay_view then
    v_result:=v_result-array['attention','summary'];
    v_result:=v_result||jsonb_build_object('permissions',jsonb_build_object(
      'contract','WEEKLY_SOURCE_PAYMENT_VIEW_V1','view','PAY',
      'allowed_tabs',jsonb_build_array('queries'),
      'allowed_sections',jsonb_build_array('questions','checks','protected'),
      'landing_tab','queries','can_upload',false,'can_finalise',false,'can_manage_settings',false,
      'checklist',jsonb_build_object('available',false,'read_only',true,'pay_only',true,'action_links',false)));
  end if;
  return v_result;
end;
$function$;
alter function public.weekly_source_combined_review_workspace_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_combined_review_workspace_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_source_combined_review_workspace_v1(jsonb) to service_role;
notify pgrst,'reload schema';


-- CONTACT_PREPARER_UNIT 148 repeatable supabase/repeatable/16102026_0339_weekly_contact_query_native_lifecycle_v1.sql SHA256 ee5ed11006cb2bc1443d91038cbba214463a9cc5c8f16c01c768951c1e5d83ca
-- Complete native query contact lifecycle and original owner compatibility.
-- One-time trigger installation belongs solely to the atomic0339 migration.


create or replace function private.weekly_contact_query_member_v1(p_delivery_id uuid,p_item_id uuid)
returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare v_delivery public.hr_issue_email_deliveries%rowtype;v_item public.hr_issue_email_delivery_items%rowtype;
 v_action public.import_review_decisions%rowtype;v_issue public.hr_issue_emails%rowtype;v_ts public.timesheets%rowtype;
 v_current boolean:=true;v_route jsonb;v_evidence jsonb;
begin
 select * into strict v_delivery from public.hr_issue_email_deliveries where id=p_delivery_id;
 select * into strict v_item from public.hr_issue_email_delivery_items where id=p_item_id and delivery_id=p_delivery_id;
  select * into strict v_action from public.import_review_decisions where action_id=v_item.action_id;
  select * into strict v_issue from public.hr_issue_emails where id=v_item.issue_id;
  select * into strict v_ts from public.timesheets where timesheet_id=v_action.timesheet_id;
  if v_action.import_id is distinct from v_delivery.import_id or v_issue.import_id is distinct from v_delivery.import_id
   -- A first native enqueue creates the issue after the immutable action was
   -- catalogued, and fills only its native temporary issue projection. Its
   -- saved action may therefore genuinely have no issue_id yet. The real
   -- delivery item + exact immutable fingerprint still bind that new issue.
   or (v_action.issue_id is not null and v_action.issue_id is distinct from v_issue.id)
   or v_action.timesheet_id is distinct from v_issue.timesheet_id
   or v_action.client_id is distinct from v_issue.client_id or v_action.contract_id is distinct from v_issue.contract_id
   or v_action.candidate_id is null
   or v_action.client_id is null or v_item.issue_fingerprint is distinct from v_issue.issue_fingerprint
   or v_item.issue_fingerprint is distinct from coalesce(nullif(v_action.summary_json->>'issue_fingerprint',''),v_action.source_identity)
   or v_action.action_kind not in('EMAIL_ISSUE','EMAIL_REMINDER')
   or not exists(select 1 from public.import_review_action_outcomes o
    where o.import_id=v_delivery.import_id and o.operation_id=v_delivery.operation_id and o.action_id=v_action.action_id) then
   raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='42501';end if;
  -- The physical Timesheet has no candidate_id column. Weekly identity is
  -- its real Contract; a genuine contractless Daily uses the same exact
  -- native import identity view that produced the reviewed action.
  if v_ts.contract_id is not null then
   if not exists(select 1 from public.contracts c where c.id=v_ts.contract_id
    and c.candidate_id=v_action.candidate_id and c.client_id=v_action.client_id) then
    raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='42501';end if;
  elsif v_ts.sheet_scope::text<>'DAILY'
   or (select count(*) from public.v_timesheets_daily_match d where d.timesheet_id=v_ts.timesheet_id)<>1
   or not exists(select 1 from public.v_timesheets_daily_match d where d.timesheet_id=v_ts.timesheet_id
    and d.candidate_id=v_action.candidate_id and d.client_id=v_action.client_id) then
   raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='42501';
  end if;
  v_route:=public._timesheet_query_recipient_resolve_core_v1(v_action.client_id,v_action.contract_id);
  v_evidence:=private.weekly_source_issued_signed_query_evidence_v1(v_action.timesheet_id,v_delivery.import_id);
  if v_route->>'recipient_email' is distinct from v_delivery.recipient_email
   or v_route->>'recipient_scope_key' is distinct from v_action.summary_json->>'recipient_scope_key'
   or v_route->>'route_fingerprint' is distinct from v_action.summary_json->>'recipient_route_fingerprint' then
   v_current:=false;end if;
  if v_action.is_current is distinct from true or v_action.selected is distinct from true
   or v_action.requires_reconfirmation is distinct from false or v_item.marked_sent_at_utc is not null
   or v_evidence->>'reason_code' is not null
   or v_evidence->'document_ready' is distinct from 'true'::jsonb
   or v_evidence->'source_complete' is distinct from 'true'::jsonb
   or v_evidence->>'evidence_fingerprint' is distinct from v_action.summary_json->>'attachment_fingerprint' then
   v_current:=false;end if;

 return jsonb_build_object('current',v_current,'route_fingerprint',v_route->>'route_fingerprint',
  'issue_witness',jsonb_build_object('timesheet_id',v_action.timesheet_id,'issue_fingerprint',v_item.issue_fingerprint,
   'evidence_fingerprint',v_evidence->>'evidence_fingerprint','r2_key',v_evidence->>'attachment_r2_key','filename',v_evidence->>'attachment_filename'),
  'pair',jsonb_build_object('candidate_id',v_action.candidate_id,'client_id',v_action.client_id),
  'member',jsonb_build_object('action_id',v_action.action_id,'issue_id',v_issue.id,'issue_fingerprint',v_item.issue_fingerprint,
   'candidate_id',v_action.candidate_id,'client_id',v_action.client_id));
end;
$function$;

create or replace function private.weekly_contact_query_saved_payload_v1(p_outbox_id uuid,p_delivery_id uuid)
returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare v_mail public.mail_outbox%rowtype;v_delivery public.hr_issue_email_deliveries%rowtype;v_root public.hr_issue_email_deliveries%rowtype;
 v_members jsonb;v_content jsonb;v_content_hash bytea;v_recipient bytea;
begin
 select * into strict v_mail from public.mail_outbox where id=p_outbox_id;
 select * into strict v_delivery from public.hr_issue_email_deliveries where id=p_delivery_id;
 select * into strict v_root from public.hr_issue_email_deliveries where id=v_delivery.original_delivery_id;
 if v_delivery.mail_outbox_id is distinct from v_mail.id or v_mail.type is distinct from 'TIMESHEET_QUERY'
  or v_mail.context_kind is distinct from 'TIMESHEET_QUERY_DELIVERY' or v_mail.context_id is distinct from v_delivery.id
  or v_mail.deterministic_outbox_key is distinct from v_delivery.deterministic_outbox_key or v_mail.reference is distinct from v_delivery.deterministic_outbox_key
  or v_mail.created_by is distinct from v_delivery.created_by_user_id or v_mail."to" is distinct from v_delivery.recipient_email
  or v_mail.email_type is distinct from 'TIMESHEET_QUERY' or v_root.original_delivery_id is distinct from v_root.id or v_root.payload_revision<>1
  or v_root.import_id is distinct from v_delivery.import_id or v_root.operation_id is distinct from v_delivery.operation_id
  or v_root.created_by_user_id is distinct from v_delivery.created_by_user_id or v_root.recipient_email is distinct from v_delivery.recipient_email
  or v_root.reminder_sequence is distinct from v_delivery.reminder_sequence
  or (v_delivery.id=v_root.id) is distinct from (v_delivery.payload_revision=1) then
  raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='42501';end if;
 if exists(select 1 from public.hr_issue_email_delivery_items child where child.delivery_id=v_delivery.id and not exists(
  select 1 from public.hr_issue_email_delivery_items original where original.delivery_id=v_root.id and original.action_id=child.action_id
   and original.issue_id=child.issue_id and original.issue_fingerprint=child.issue_fingerprint)) then
  raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('action_id',x.action_id,'issue_id',x.issue_id,'issue_fingerprint',x.issue_fingerprint,
  'candidate_id',a.candidate_id,'client_id',a.client_id) order by x.action_id,x.id),'[]'::jsonb) into v_members
 from public.hr_issue_email_delivery_items x join public.import_review_decisions a on a.action_id=x.action_id
 where x.delivery_id=v_delivery.id;
 if jsonb_array_length(v_members)=0 or jsonb_array_length(v_members)>500 then raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='42501';end if;
 v_content:=jsonb_build_object('mail_outbox_id',v_mail.id,'query_delivery_id',v_delivery.id,
  'original_delivery_id',v_delivery.original_delivery_id,'payload_revision',v_delivery.payload_revision::text,'type',v_mail.type,'to',v_mail."to",'cc',v_mail.cc,'bcc',v_mail.bcc,'reply_to',v_mail.reply_to,
  'subject',v_mail.subject,'body_html',v_mail.body_html,'body_text',v_mail.body_text,'attachments',v_mail.attachments,
  'importance',v_mail.importance,'attachment_delivery_policy',v_mail.attachment_delivery_policy,
  'recipient_kind',v_mail.recipient_kind,'recipient_id',v_mail.recipient_id,
  'context_kind',v_mail.context_kind,'context_id',v_mail.context_id,'email_type',v_mail.email_type,
  'reference',v_mail.reference,'deterministic_outbox_key',v_mail.deterministic_outbox_key,
  'created_by',v_mail.created_by,'delivery_items',v_members);
 v_content_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_QUERY_CONTENT_V1',v_content);
 v_recipient:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_QUERY_RECIPIENT_V1',jsonb_build_object(
  'to',v_mail."to",'cc',v_mail.cc,'bcc',v_mail.bcc,'reply_to',v_mail.reply_to,
  'recipient_route_fingerprint',v_delivery.recipient_route_fingerprint));

 return jsonb_build_object('mail_outbox_id',v_mail.id,'query_delivery_id',v_delivery.id,'original_delivery_id',v_root.id,
  'payload_revision',v_delivery.payload_revision::text,'content_hash',encode(v_content_hash,'hex'),
  'recipient_hash',encode(v_recipient,'hex'),'members',v_members);
end;
$function$;

create or replace function private.weekly_contact_query_enqueue_core_v1(
  p_import_id uuid,p_operation_id uuid,p_selected_action_ids jsonb,p_actor_user_id uuid default null,
  p_max_actions integer default 5000,p_max_groups integer default 100,p_source_delivery_id uuid default null,p_payload_revision bigint default 1
)
returns jsonb language plpgsql security definer set search_path to 'public','extensions','pg_temp' as $function$
declare
  v_source public.hr_issue_email_deliveries%rowtype;
  v_state public.import_review_states%rowtype; v_operation public.import_apply_operations%rowtype;
  v_ids text[]; v_db_ids text[]; v_group record; v_route jsonb;
  v_issue_ids uuid[]; v_issue_set_hash text; v_outbox_key text; v_delivery_id uuid; v_outbox_id uuid;
  v_html text; v_text text; v_subject text; v_results jsonb:='[]'; v_group_count integer:=0; v_reminder integer;
  v_new_delivery_count integer:=0; v_group_replay boolean; v_recipient_group_key text;
  v_attachments jsonb:='[]'::jsonb; v_greeting text; v_agency_name text;
begin
  perform public._import_review_assert_actor_v1(p_actor_user_id);
  if p_import_id is null or p_operation_id is null or jsonb_typeof(coalesce(p_selected_action_ids,'[]'))<>'array'
    or p_max_actions<1 or p_max_actions>5000 or p_max_groups<1 or p_max_groups>100
    or jsonb_array_length(coalesce(p_selected_action_ids,'[]'))>p_max_actions then
    raise exception 'TIMESHEET_QUERY_ENQUEUE_INPUT_INVALID' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(coalesce(p_selected_action_ids,'[]'))x where jsonb_typeof(x)<>'string' or trim(both '"' from x::text)!~'^[0-9a-f]{64}$') then
    raise exception 'TIMESHEET_QUERY_ACTION_ID_INVALID' using errcode='22023'; end if;
  select coalesce(array_agg(distinct value order by value),array[]::text[]) into v_ids from jsonb_array_elements_text(coalesce(p_selected_action_ids,'[]'))value;
  if cardinality(v_ids)<>jsonb_array_length(coalesce(p_selected_action_ids,'[]')) then raise exception 'TIMESHEET_QUERY_ACTION_ID_DUPLICATE' using errcode='22023'; end if;
  select * into v_state from public.import_review_states where import_id=p_import_id for update;
  select * into v_operation from public.import_apply_operations
  where id=p_operation_id and import_id=p_import_id for update;
  if v_state.import_id is null
    or v_state.status not in ('IN_REVIEW','BLOCKED','READY','APPLIED')
    or v_state.last_operation_id is distinct from p_operation_id
    or v_operation.id is null
    or v_operation.committed_at_utc is null
    or v_operation.state not in ('SOURCE_COMMITTED_TSFIN_PENDING','COMPLETE') then
    raise exception 'TIMESHEET_QUERY_REVIEW_NOT_APPLIED' using errcode='55000'; end if;
  select coalesce(array_agg(value order by value),array[]::text[]) into v_db_ids
  from jsonb_array_elements_text(coalesce(v_operation.response_json->'post_commit_email_action_ids','[]'::jsonb)) value;
  if p_source_delivery_id is null then
    if p_payload_revision<>1 or v_ids is distinct from v_db_ids then raise exception 'TIMESHEET_QUERY_SELECTED_ACTION_SET_MISMATCH' using errcode='40001';end if;
  else
    select * into strict v_source from public.hr_issue_email_deliveries where id=p_source_delivery_id for update;
    if v_source.original_delivery_id<>v_source.id or v_source.payload_revision<>1 or v_source.import_id<>p_import_id
      or v_source.operation_id<>p_operation_id or v_source.created_by_user_id is distinct from p_actor_user_id or p_payload_revision<2
      or exists(select 1 from unnest(v_ids)x where not exists(select 1 from public.hr_issue_email_delivery_items item
        where item.delivery_id=v_source.id and item.action_id=x)) then
      raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='42501';end if;
  end if;
  if exists(
    select 1
    from unnest(v_ids) x
    left join public.import_review_decisions d
      on d.action_id=x and d.import_id=p_import_id
    left join public.import_review_action_outcomes o
      on o.action_id=x and o.import_id=p_import_id and o.operation_id=p_operation_id
    where d.action_id is null or not d.selected
      or d.action_kind not in ('EMAIL_ISSUE','EMAIL_REMINDER')
      or o.action_id is null
  ) then
    raise exception 'TIMESHEET_QUERY_ACTION_STALE' using errcode='40001'; end if;

  -- A committed original operation already froze its true grouped ordinal.
  -- Replay those actual roots before reading mutable successful-send counts;
  -- otherwise Alex's accepted child could manufacture a fresh original and
  -- refill Taylor's ordinal when the same post-commit enqueue retries.
  if p_source_delivery_id is null and exists(select 1 from public.hr_issue_email_deliveries d
    where d.operation_id=p_operation_id and d.original_delivery_id=d.id) then
    select array_agg(x.action_id order by x.action_id) into v_db_ids from(
      select distinct item.action_id from public.hr_issue_email_deliveries d
      join public.hr_issue_email_delivery_items item on item.delivery_id=d.id
      where d.operation_id=p_operation_id and d.original_delivery_id=d.id
    )x;
    if v_ids is distinct from coalesce(v_db_ids,array[]::text[]) then
      raise exception 'CONTACT_QUERY_ORIGINAL_ACTION_SET_CHANGED' using errcode='40001';end if;
    select count(*)::integer,coalesce(jsonb_agg(jsonb_build_object('delivery_id',d.id,'mail_outbox_id',d.mail_outbox_id,
      'recipient_scope',d.recipient_scope,'recipient_scope_key',d.recipient_scope_key,
      'business_route_count',(select count(distinct a.summary_json->>'recipient_scope_key') from public.hr_issue_email_delivery_items item
        join public.import_review_decisions a on a.action_id=item.action_id where item.delivery_id=d.id),
      'issue_count',(select count(*) from public.hr_issue_email_delivery_items item where item.delivery_id=d.id),
      'reminder_sequence',d.reminder_sequence,'replay',true) order by d.recipient_email,d.id),'[]'::jsonb)
    into v_group_count,v_results from public.hr_issue_email_deliveries d where d.operation_id=p_operation_id and d.original_delivery_id=d.id;
    return jsonb_build_object('ok',true,'import_id',p_import_id,'operation_id',p_operation_id,'group_count',v_group_count,'groups',v_results,
      'new_delivery_count',0,'replay',true,'follow_up_status',v_state.follow_up_status,'state_version',v_state.state_version);
  end if;

  drop table if exists pg_temp.query_email_issues;
  create temporary table pg_temp.query_email_issues on commit drop as
  select d.*,coalesce(nullif(d.summary_json->>'issue_fingerprint',''),d.source_identity) issue_fingerprint,
    public._timesheet_query_recipient_resolve_core_v1(d.client_id,d.contract_id) route,
    evidence.evidence_json attachment_evidence
  from public.import_review_decisions d
  cross join lateral (select private.weekly_source_issued_signed_query_evidence_v1(d.timesheet_id,p_import_id) evidence_json) evidence
  where d.import_id=p_import_id and d.action_id=any(v_ids) order by d.action_id;
  if exists(select 1 from pg_temp.query_email_issues where route->>'recipient_scope_key' is distinct from summary_json->>'recipient_scope_key'
    or route->>'route_fingerprint' is distinct from summary_json->>'recipient_route_fingerprint') then
    raise exception 'TIMESHEET_QUERY_RECIPIENT_ROUTE_CHANGED' using errcode='40001'; end if;
  if exists(select 1 from pg_temp.query_email_issues
    where not coalesce((attachment_evidence->>'document_ready')::boolean,false)
      or attachment_evidence->>'evidence_fingerprint' is distinct from summary_json->>'attachment_fingerprint') then
    raise exception 'TIMESHEET_QUERY_ATTACHMENT_EVIDENCE_STALE' using errcode='40001'; end if;

  select coalesce(nullif(btrim(agency_name),''),'CloudTMS') into v_agency_name
  from public.settings_defaults order by agency_name nulls last limit 1;
  v_agency_name:=coalesce(v_agency_name,'CloudTMS');
  v_greeting:=case when (statement_timestamp() at time zone 'Europe/London')::time<time '12:00'
    then 'Good morning' else 'Good afternoon' end;

  -- Create/reuse issue identities without changing successful-send history.
  insert into public.hr_issue_emails(source_system,import_id,client_id,contract_id,timesheet_id,hr_row_id,staff_norm,work_date,
    reason_code,issue_fingerprint,last_sent_at,recipient_scope,recipient_scope_key,delivery_history_status)
  select hi.source_system::text,p_import_id,q.client_id,q.contract_id,q.timesheet_id,q.hr_row_id,q.summary_json->>'candidate_name',
    nullif(q.summary_json->>'work_date','')::date,coalesce(q.summary_json->>'reason_code','VALIDATION_MISMATCH'),q.issue_fingerprint,
    null,q.route->>'recipient_scope',q.route->>'recipient_scope_key','PENDING'
  from pg_temp.query_email_issues q join public.hr_imports hi on hi.id=p_import_id
  on conflict(issue_fingerprint) do update set contract_id=excluded.contract_id,recipient_scope=excluded.recipient_scope,
    recipient_scope_key=excluded.recipient_scope_key,updated_at=now();
  update pg_temp.query_email_issues q set issue_id=e.id from public.hr_issue_emails e where e.issue_fingerprint=q.issue_fingerprint;

  for v_group in
    select lower(route->>'recipient_email') recipient_email,
      case when count(distinct route->>'recipient_scope_key')=1 then min(route->>'recipient_scope') else 'CONTRACT_OVERRIDE' end recipient_scope,
      public._import_review_hash_v1(string_agg(distinct route->>'route_fingerprint','|' order by route->>'route_fingerprint')) route_fingerprint,
      count(distinct route->>'recipient_scope_key') business_route_count,
      count(*) issue_count,max(coalesce(e.sent_count,0))+case when bool_or(q.action_kind='EMAIL_REMINDER') then 1 else 0 end reminder_sequence
    from pg_temp.query_email_issues q join public.hr_issue_emails e on e.id=q.issue_id
    group by lower(route->>'recipient_email')
    order by lower(route->>'recipient_email')
  loop
    v_group_count:=v_group_count+1; if v_group_count>p_max_groups then raise exception 'TIMESHEET_QUERY_GROUP_LIMIT_EXCEEDED' using errcode='54000'; end if;
    v_recipient_group_key:='RECIPIENT_EMAIL:'||public._import_review_hash_v1(v_group.recipient_email);
    select array_agg(q.issue_id order by q.issue_id),
      public._import_review_hash_v1(string_agg(q.issue_fingerprint||':'||(q.attachment_evidence->>'evidence_fingerprint'),'|' order by q.issue_fingerprint)),
      coalesce((select jsonb_agg(jsonb_build_object(
        'r2_key',attachment_row.attachment_evidence->>'attachment_r2_key',
        'filename',attachment_row.attachment_evidence->>'attachment_filename'
      ) order by attachment_row.timesheet_id)
      from (
        select distinct on (q2.timesheet_id) q2.timesheet_id,q2.attachment_evidence
        from pg_temp.query_email_issues q2
        where lower(q2.route->>'recipient_email')=v_group.recipient_email
        order by q2.timesheet_id,q2.action_id
      ) attachment_row),'[]'::jsonb)
      into v_issue_ids,v_issue_set_hash,v_attachments
    from pg_temp.query_email_issues q
    where lower(q.route->>'recipient_email')=v_group.recipient_email;
    v_reminder:=case when p_source_delivery_id is null then v_group.reminder_sequence else v_source.reminder_sequence end;
    v_outbox_key:='TIMESHEET_QUERY:'||public._import_review_hash_v1(case when p_source_delivery_id is null
      then concat_ws('|',p_operation_id,v_recipient_group_key,v_issue_set_hash,v_reminder)
      else concat_ws('|','CONTACT_RECOMPOSITION_V1',p_operation_id,v_recipient_group_key,v_issue_set_hash,v_reminder,v_source.id,p_payload_revision) end);
    v_delivery_id:=null;v_outbox_id:=null;v_group_replay:=false;
    select d.id,d.mail_outbox_id into v_delivery_id,v_outbox_id from public.hr_issue_email_deliveries d where d.deterministic_outbox_key=v_outbox_key for update;
    if not found then
      v_new_delivery_count:=v_new_delivery_count+1;
      v_delivery_id:=gen_random_uuid();
      v_subject:=case when v_reminder>0 then 'Reminder: timesheet corrections required' else 'Timesheet corrections required' end;
      with lines as (
        select q.action_id||':'||row_number() over(partition by q.action_id order by cx.value->>'comparison_key') sort_key,
          coalesce(nullif(cl.name,''),nullif(q.summary_json->>'client_name',''),'Client') client_name,
          coalesce(q.contract_id::text,'client-default') contract_sort,
          case when q.contract_id is null then 'Client default'
            else coalesce(nullif(concat_ws(' · ',nullif(ct.display_site,''),nullif(ct.role,''),nullif(ct.band,'')),''),'Contract')
              ||case when ct.start_date is not null then ' ('||to_char(ct.start_date,'FMDD Mon YYYY')||'–'||to_char(ct.end_date,'FMDD Mon YYYY')||')' else '' end
          end contract_label,
          q.summary_json->>'candidate_name' candidate_name,
          coalesce(nullif(cx.value->>'work_date',''),nullif(q.summary_json->>'work_date','')) work_date,
          coalesce(nullif(cx.value->>'match_status',''),nullif(q.summary_json->>'reason_code','')) issue_code,
          concat_ws(' ',nullif(cx.value->>'timesheet_start','')||case when nullif(cx.value->>'timesheet_end','') is null then '' else '–'||(cx.value->>'timesheet_end') end,
            case when nullif(cx.value->>'timesheet_break_mins','') is not null then 'break '||(cx.value->>'timesheet_break_mins')||' min' end,
            case when nullif(cx.value->>'timesheet_start','') is null then concat_ws('–',q.summary_json->>'start_time',q.summary_json->>'end_time') end,
            case when nullif(q.summary_json->>'hours_worked','') is not null then (q.summary_json->>'hours_worked')||' hours' end) timesheet_detail,
          concat_ws(' ',nullif(cx.value->>'healthroster_start','')||case when nullif(cx.value->>'healthroster_end','') is null then '' else '–'||(cx.value->>'healthroster_end') end,
            case when nullif(cx.value->>'healthroster_break_mins','') is not null then 'break '||(cx.value->>'healthroster_break_mins')||' min' end) import_detail,
          concat_ws(' · ',nullif(cx.value->>'healthroster_hospital',''),nullif(cx.value->>'healthroster_unit','')) source_location,
          nullif(cx.value->>'healthroster_request_grade','') request_grade,
          case
            when nullif(cx.value->>'ref_before','') is not null
              and cx.value->>'ref_before'=cx.value->>'ref_after' then cx.value->>'ref_before'
            when nullif(cx.value->>'ref_before','') is not null and nullif(cx.value->>'ref_after','') is not null
              then (cx.value->>'ref_before')||' → '||(cx.value->>'ref_after')
            else coalesce(nullif(cx.value->>'ref_after',''),nullif(cx.value->>'ref_before',''))
          end reference_detail
        from pg_temp.query_email_issues q
        left join public.clients cl on cl.id=q.client_id
        left join public.contracts ct on ct.id=q.contract_id
        cross join lateral (
          select c.value from jsonb_array_elements(coalesce(q.summary_json->'comparisons','[]'::jsonb)) c(value)
          where coalesce(c.value->>'match_status','')<>'MATCH'
             or coalesce(c.value->>'ref_before','')<>coalesce(c.value->>'ref_after','')
          union all
          select '{}'::jsonb where not exists(
            select 1 from jsonb_array_elements(coalesce(q.summary_json->'comparisons','[]'::jsonb)) c2(value)
            where coalesce(c2.value->>'match_status','')<>'MATCH'
               or coalesce(c2.value->>'ref_before','')<>coalesce(c2.value->>'ref_after',''))
        ) cx
        where lower(q.route->>'recipient_email')=v_group.recipient_email
      ), rendered_rows as (
        select l.*,'<tr><td style="padding:8px;border:1px solid #dbe2ea">'||public._import_review_html_escape_v1(l.candidate_name)||'</td><td style="padding:8px;border:1px solid #dbe2ea;white-space:nowrap">'||
          public._import_review_html_escape_v1(case when l.work_date~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then to_char(l.work_date::date,'FMDD Mon YYYY') else l.work_date end)||'</td><td style="padding:8px;border:1px solid #dbe2ea">'||
          public._import_review_html_escape_v1(replace(initcap(lower(l.issue_code)),'_',' '))||'</td><td style="padding:8px;border:1px solid #dbe2ea">'||
          public._import_review_html_escape_v1(l.timesheet_detail)||'</td><td style="padding:8px;border:1px solid #dbe2ea">'||public._import_review_html_escape_v1(l.import_detail)||
          '</td><td style="padding:8px;border:1px solid #dbe2ea">'||public._import_review_html_escape_v1(l.source_location)||
          '</td><td style="padding:8px;border:1px solid #dbe2ea">'||public._import_review_html_escape_v1(l.request_grade)||
          '</td><td style="padding:8px;border:1px solid #dbe2ea">'||
          public._import_review_html_escape_v1(l.reference_detail)||'</td></tr>' row_html
        from lines l
      ), contract_tables as (
        select client_name,contract_sort,contract_label,
          '<h4 style="margin:18px 0 8px;color:#334155;font-size:14px">'||public._import_review_html_escape_v1(contract_label)||'</h4>'||
          '<table role="table" cellspacing="0" cellpadding="0" style="width:100%;border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px"><thead><tr style="background:#eef2f7;color:#1e293b"><th style="padding:8px;border:1px solid #dbe2ea;text-align:left">Worker</th><th style="padding:8px;border:1px solid #dbe2ea;text-align:left">Date</th><th style="padding:8px;border:1px solid #dbe2ea;text-align:left">Issue</th><th style="padding:8px;border:1px solid #dbe2ea;text-align:left">Timesheet</th><th style="padding:8px;border:1px solid #dbe2ea;text-align:left">HealthRoster</th><th style="padding:8px;border:1px solid #dbe2ea;text-align:left">Unit / ward</th><th style="padding:8px;border:1px solid #dbe2ea;text-align:left">Request grade</th><th style="padding:8px;border:1px solid #dbe2ea;text-align:left">Reference</th></tr></thead><tbody>'||
          string_agg(row_html,'' order by sort_key)||'</tbody></table>' contract_html
        from rendered_rows group by client_name,contract_sort,contract_label
      ), client_sections as (
        select client_name,'<section style="margin:24px 0"><h3 style="margin:0 0 10px;color:#0f172a;font-size:17px">'||
          public._import_review_html_escape_v1(client_name)||'</h3>'||string_agg(contract_html,'' order by contract_label,contract_sort)||'</section>' client_html
        from contract_tables group by client_name
      )
      select '<div style="font-family:Arial,sans-serif;color:#0f172a;line-height:1.45"><p>'||
        public._import_review_html_escape_v1(v_greeting)||',</p><p>Please can you kindly make amendments on HealthRoster for the below shifts. The relevant timesheets have been attached to this email.</p>'||
        string_agg(client_html,'' order by client_name)||'<p>Many thanks,<br>'||
        public._import_review_html_escape_v1(v_agency_name)||'</p></div>' into v_html from client_sections;
      with lines as (
        select q.action_id||':'||row_number() over(partition by q.action_id order by cx.value->>'comparison_key') sort_key,
          coalesce(nullif(cl.name,''),nullif(q.summary_json->>'client_name',''),'Client') client_name,
          case when q.contract_id is null then 'Client default'
            else coalesce(nullif(concat_ws(' · ',nullif(ct.display_site,''),nullif(ct.role,''),nullif(ct.band,'')),''),'Contract') end contract_label,
          q.summary_json->>'candidate_name' candidate_name,
          coalesce(nullif(cx.value->>'work_date',''),nullif(q.summary_json->>'work_date','')) work_date,
          coalesce(nullif(cx.value->>'match_status',''),nullif(q.summary_json->>'reason_code','')) issue_code,
          concat_ws(' ',cx.value->>'timesheet_start',cx.value->>'timesheet_end',cx.value->>'healthroster_start',cx.value->>'healthroster_end',
            q.summary_json->>'start_time',q.summary_json->>'end_time',q.summary_json->>'hours_worked',
            case when nullif(cx.value->>'healthroster_hospital','') is not null or nullif(cx.value->>'healthroster_unit','') is not null
              then 'Unit / ward: '||concat_ws(' · ',nullif(cx.value->>'healthroster_hospital',''),nullif(cx.value->>'healthroster_unit','')) end,
            case when nullif(cx.value->>'healthroster_request_grade','') is not null
              then 'Request grade: '||(cx.value->>'healthroster_request_grade') end) detail
        from pg_temp.query_email_issues q
        left join public.clients cl on cl.id=q.client_id
        left join public.contracts ct on ct.id=q.contract_id
        cross join lateral (
          select c.value from jsonb_array_elements(coalesce(q.summary_json->'comparisons','[]'::jsonb)) c(value)
          where coalesce(c.value->>'match_status','')<>'MATCH'
             or coalesce(c.value->>'ref_before','')<>coalesce(c.value->>'ref_after','')
          union all
          select '{}'::jsonb where not exists(
            select 1 from jsonb_array_elements(coalesce(q.summary_json->'comparisons','[]'::jsonb)) c2(value)
            where coalesce(c2.value->>'match_status','')<>'MATCH'
               or coalesce(c2.value->>'ref_before','')<>coalesce(c2.value->>'ref_after',''))
        ) cx
        where lower(q.route->>'recipient_email')=v_group.recipient_email
      )
      select v_greeting||E',\n\nPlease can you kindly make amendments on HealthRoster for the below shifts. The relevant timesheets have been attached to this email.\n\n'||
        string_agg(concat_ws(' | ',l.client_name,l.contract_label,l.candidate_name,l.work_date,l.issue_code,l.detail),'\n' order by l.client_name,l.contract_label,l.sort_key)
        ||E'\n\nMany thanks,\n'||v_agency_name into v_text from lines l;
      if length(v_html)>262144 or length(v_text)>131072 then raise exception 'TIMESHEET_QUERY_BODY_LIMIT_EXCEEDED' using errcode='54000'; end if;
      insert into public.mail_outbox(type,"to",subject,body_html,body_text,attachments,status,created_by,reference,recipient_kind,recipient_id,
        context_kind,context_id,email_type,deterministic_outbox_key,payment_scope_json)
      values('TIMESHEET_QUERY',v_group.recipient_email,v_subject,v_html,v_text,v_attachments,'QUEUED'::public.mail_status_enum,p_actor_user_id,
        v_outbox_key,'TIMESHEET_QUERY_EMAIL',null,
        'TIMESHEET_QUERY_DELIVERY',v_delivery_id,'TIMESHEET_QUERY',v_outbox_key,'{}'::jsonb)
      on conflict do nothing;
      select id into v_outbox_id from public.mail_outbox where deterministic_outbox_key=v_outbox_key;
      if v_outbox_id is null then raise exception 'TIMESHEET_QUERY_OUTBOX_CLAIM_FAILED' using errcode='23505'; end if;
      insert into public.hr_issue_email_deliveries(id,import_id,operation_id,recipient_scope,recipient_scope_key,recipient_route_fingerprint,
        recipient_email,reminder_sequence,issue_set_fingerprint,deterministic_outbox_key,mail_outbox_id,status,created_by_user_id,original_delivery_id,payload_revision,contact_managed)
      values(v_delivery_id,p_import_id,p_operation_id,v_group.recipient_scope,v_recipient_group_key,v_group.route_fingerprint,
        v_group.recipient_email,v_reminder,v_issue_set_hash,v_outbox_key,v_outbox_id,'QUEUED',p_actor_user_id,coalesce(p_source_delivery_id,v_delivery_id),p_payload_revision,true);
      insert into public.hr_issue_email_delivery_items(delivery_id,issue_id,action_id,issue_fingerprint)
      select v_delivery_id,q.issue_id,q.action_id,q.issue_fingerprint from pg_temp.query_email_issues q
      where lower(q.route->>'recipient_email')=v_group.recipient_email order by q.action_id;
    else
      v_group_replay:=true;
    end if;
    v_results:=v_results||jsonb_build_array(jsonb_build_object('delivery_id',v_delivery_id,'mail_outbox_id',v_outbox_id,
      'recipient_scope',v_group.recipient_scope,'recipient_scope_key',v_recipient_group_key,
      'business_route_count',v_group.business_route_count,'issue_count',v_group.issue_count,
      'reminder_sequence',v_reminder,'replay',v_group_replay));
  end loop;
  if v_new_delivery_count>0 then
    update public.import_review_states set follow_up_status='PENDING',state_version=state_version+1,
      updated_at_utc=now(),updated_by_user_id=p_actor_user_id where import_id=p_import_id returning * into v_state;
    insert into public.import_review_events(import_id,state_version,operation_id,event_code,actor_user_id,event_context_json)
    values(p_import_id,v_state.state_version,p_operation_id,'QUERY_EMAILS_ENQUEUED',p_actor_user_id,
      jsonb_build_object('group_count',v_group_count,'new_delivery_count',v_new_delivery_count,'action_count',cardinality(v_ids)));
  else select * into v_state from public.import_review_states where import_id=p_import_id; end if;
  return jsonb_build_object('ok',true,'import_id',p_import_id,'operation_id',p_operation_id,'group_count',v_group_count,'groups',v_results,
    'new_delivery_count',v_new_delivery_count,'replay',v_group_count>0 and v_new_delivery_count=0,
    'follow_up_status',v_state.follow_up_status,'state_version',v_state.state_version);
end $function$;

create or replace function private.weekly_contact_query_recompose_v1(
 p_delivery_id uuid,p_agency uuid,p_environment text,p_claimed_outbox uuid default null,p_claim_token text default null
) returns jsonb language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare requested public.hr_issue_email_deliveries%rowtype;root public.hr_issue_email_deliveries%rowtype;
 d public.hr_issue_email_deliveries%rowtype;o public.mail_outbox%rowtype;item public.hr_issue_email_delivery_items%rowtype;
 pair record;fact jsonb;guard jsonb;logical bytea;ordinal integer;eligible text[]:='{}';excluded jsonb:='[]';
 unknown_count integer:=0;accepted_count integer:=0;paused_count integer:=0;next_at timestamptz;at_utc timestamptz;
 target_id uuid;target_mail uuid;revision bigint;native_result jsonb;saved jsonb;ids text[];outcome text;reason text;
begin
 perform private.weekly_source_query_require_service_v1();
 perform private.weekly_contact_deployment_lock_v1(p_agency,p_environment);
 perform private.weekly_contact_context_v1(p_agency,p_environment);
 select * into strict requested from public.hr_issue_email_deliveries where id=p_delivery_id;
 select * into strict root from public.hr_issue_email_deliveries where id=requested.original_delivery_id;
 if root.original_delivery_id<>root.id or root.payload_revision<>1 or root.import_id<>requested.import_id
  or root.operation_id<>requested.operation_id then raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='42501';end if;
 -- Discover all genuine original scopes before acquiring any native row lock.
 for pair in select distinct a.candidate_id,a.client_id from public.hr_issue_email_delivery_items i
  join public.import_review_decisions a on a.action_id=i.action_id where i.delivery_id=root.id order by a.candidate_id,a.client_id loop
  if pair.candidate_id is null or pair.client_id is null then raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='42501';end if;
  perform private.weekly_contact_scope_lock_v1(p_agency,p_environment,pair.candidate_id,pair.client_id);
 end loop;
 -- Original outbox first, then the finite actual family, then delivery rows.
 perform 1 from public.mail_outbox where id=root.mail_outbox_id for update;
 perform 1 from public.mail_outbox m join public.hr_issue_email_deliveries x on x.mail_outbox_id=m.id
  where x.original_delivery_id=root.id order by m.id for update of m;
 select * into strict root from public.hr_issue_email_deliveries where id=root.id for update;
 perform 1 from public.hr_issue_email_deliveries x where x.original_delivery_id=root.id order by x.id for update;
 select * into strict requested from public.hr_issue_email_deliveries where id=p_delivery_id;
 perform public._import_review_assert_actor_v1(root.created_by_user_id);
 if p_claimed_outbox is not null then
  select * into strict o from public.mail_outbox where id=p_claimed_outbox;
  if requested.mail_outbox_id<>o.id or o.attempt_lease_token is distinct from p_claim_token
   or o.attempt_lease_expires_at_utc is null or o.attempt_lease_expires_at_utc<=clock_timestamp() then
   raise exception 'CONTACT_QUERY_LEASE_STALE' using errcode='40001';end if;
 end if;
 at_utc:=clock_timestamp();ordinal:=root.reminder_sequence+1;
 for item in select * from public.hr_issue_email_delivery_items where delivery_id=root.id order by action_id,id loop
  fact:=private.weekly_contact_query_member_v1(root.id,item.id);reason:=null;
  logical:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_QUERY_MEMBERSHIP_V1',jsonb_build_object('issue_id',item.issue_id,'purpose','TIMESHEET_QUERY'));
  if exists(select 1 from public.weekly_contact_delivery_memberships m where m.logical_contact_key=logical and m.send_ordinal=ordinal and m.accepted_at_utc is not null)
   or exists(select 1 from public.hr_issue_email_delivery_items i join public.hr_issue_email_deliveries x on x.id=i.delivery_id
    where i.action_id=item.action_id and i.marked_sent_at_utc is not null and x.status='SENT') then
   accepted_count:=accepted_count+1;reason:='ALREADY_ACCEPTED';
  elsif exists(select 1 from public.weekly_contact_delivery_memberships m join public.weekly_contact_submission_permits p on p.query_delivery_id=m.delivery_id
   where m.logical_contact_key=logical and m.send_ordinal=ordinal and p.owner_kind='TIMESHEET_QUERY_OUTBOX' and p.status in('PREPARED','STARTED','AMBIGUOUS'))
   or exists(select 1 from public.hr_issue_email_delivery_items i join public.hr_issue_email_deliveries x on x.id=i.delivery_id
    where i.action_id=item.action_id and x.legacy_claim_lease_token is not null and x.status<>'SENT')
   or exists(select 1 from public.hr_issue_email_delivery_items i join public.hr_issue_email_deliveries x on x.id=i.delivery_id
    join public.mail_outbox mail on mail.id=x.mail_outbox_id where i.action_id=item.action_id and mail.provider_status='DELIVERY_UNCERTAIN') then
   unknown_count:=unknown_count+1;reason:='CHECK_ORIGINAL_ATTEMPT';
  elsif fact->'current' is distinct from 'true'::jsonb then reason:='OBSOLETE';
  else
   guard:=private.weekly_contact_scope_guard_v1((fact->'pair'->>'candidate_id')::uuid,(fact->'pair'->>'client_id')::uuid,'MANAGER',at_utc);
   if guard->'allow' is distinct from 'true'::jsonb then
    if guard->>'next_allowed_utc' is null then raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='42501';end if;
    paused_count:=paused_count+1;reason:='CONTACT_PAUSED';next_at:=least(next_at,(guard->>'next_allowed_utc')::timestamptz);
   end if;
  end if;
  if reason is null then eligible:=array_append(eligible,item.action_id);
  else excluded:=excluded||jsonb_build_array(jsonb_build_object('action_id',item.action_id,'issue_id',item.issue_id,'reason',reason));end if;
 end loop;
 -- A shared immutable PDF key cannot be carried through after another worker
 -- using that key was excluded. Request genuine per-Timesheet native evidence;
 -- do not invent a PDF, strip pages or claim a multi-worker attachment is safe.
 if exists(select 1 from public.hr_issue_email_delivery_items a join public.import_review_decisions da on da.action_id=a.action_id
  join public.hr_issue_email_delivery_items b on b.delivery_id=a.delivery_id and b.action_id<>a.action_id
  join public.import_review_decisions db on db.action_id=b.action_id
  where a.delivery_id=root.id and a.action_id=any(eligible) and not(b.action_id=any(eligible))
   and da.candidate_id is distinct from db.candidate_id
   and private.weekly_source_issued_signed_query_evidence_v1(da.timesheet_id,root.import_id)->>'attachment_r2_key'
    =private.weekly_source_issued_signed_query_evidence_v1(db.timesheet_id,root.import_id)->>'attachment_r2_key') then
  raise exception 'CONTACT_QUERY_SHARED_ATTACHMENT_REQUIRES_NATIVE_REBUILD' using errcode='55000';end if;
 if cardinality(eligible)>0 then
  for d in select * from public.hr_issue_email_deliveries x where x.original_delivery_id=root.id and x.status='QUEUED' and x.retired_at_utc is null order by payload_revision loop
   select array_agg(i.action_id order by i.action_id) into ids from public.hr_issue_email_delivery_items i where i.delivery_id=d.id;
   if ids=eligible and private.weekly_contact_query_content_v1(d.mail_outbox_id,d.id)->'current'='true'::jsonb then
    if target_id is not null then raise exception 'CONTACT_QUERY_ACTIVE_PAYLOAD_DUPLICATE' using errcode='40001';end if;
    target_id:=d.id;target_mail:=d.mail_outbox_id;
   end if;
  end loop;
  if target_id is null then
   revision:=root.next_payload_revision;
   if revision=9223372036854775807 then raise exception 'CONTACT_QUERY_REVISION_EXHAUSTED' using errcode='22003';end if;
   native_result:=private.weekly_contact_query_enqueue_core_v1(root.import_id,root.operation_id,to_jsonb(eligible),root.created_by_user_id,5000,100,root.id,revision);
   if native_result->>'group_count'<>'1' then raise exception 'CONTACT_QUERY_RECOMPOSITION_GROUP_CHANGED' using errcode='40001';end if;
   target_id:=(native_result->'groups'->0->>'delivery_id')::uuid;target_mail:=(native_result->'groups'->0->>'mail_outbox_id')::uuid;
   update public.hr_issue_email_deliveries set next_payload_revision=revision+1 where id=root.id;
   saved:=private.weekly_contact_query_content_v1(target_mail,target_id);
   if saved->'current' is distinct from 'true'::jsonb then raise exception 'CONTACT_QUERY_RECOMPOSITION_STALE' using errcode='40001';end if;
  end if;
 end if;
 -- Only never-admitted payloads may retire. Retain original START/unknown
 -- ownership even after a lease expires; an expiry is no provider evidence.
 for d in select * from public.hr_issue_email_deliveries x where x.original_delivery_id=root.id and x.status='QUEUED'
  and x.id is distinct from target_id order by x.id loop
  if exists(select 1 from public.weekly_contact_submission_permits p where p.query_delivery_id=d.id and p.status in('PREPARED','STARTED','AMBIGUOUS','ACCEPTED')) then continue;end if;
  select * into strict o from public.mail_outbox where id=d.mail_outbox_id;
  if o.status::text='SENT' or o.sent_at is not null or o.provider_status='DELIVERY_UNCERTAIN' or d.legacy_claim_lease_token is not null then continue;end if;
  update public.hr_issue_email_deliveries set status='RETIRED',retired_at_utc=at_utc,
   retirement_reason=case when target_id is not null then 'CONTACT_RECOMPOSED' when paused_count>0 then 'CONTACT_PAUSED'
    when accepted_count>0 then 'CONTACT_ACCEPTED_ELSEWHERE' else 'CONTACT_OBSOLETE' end,updated_at_utc=at_utc where id=d.id;
  update public.mail_outbox set status='FAILED',provider_status='CONTACT_RETIRED_NOT_SENT',last_error='CONTACT_PAYLOAD_RETIRED',
   attempt_lease_token=null,attempt_leased_at_utc=null,attempt_lease_expires_at_utc=null,next_attempt_at_utc=next_at where id=o.id;
 end loop;
 update public.hr_issue_email_deliveries set contact_rechecked_at_utc=at_utc where id=root.id;
 if root.status='RETIRED' or exists(select 1 from public.hr_issue_email_deliveries x where x.id=root.id and x.status='RETIRED') then
  update public.mail_outbox set next_attempt_at_utc=case when next_at is not null then next_at when unknown_count>0 then at_utc+interval '15 minutes' else null end where id=root.mail_outbox_id;
 end if;
 perform private.weekly_contact_query_complete_v1(root.import_id,root.operation_id,root.created_by_user_id);
 outcome:=case when target_id=requested.id then 'CURRENT' when target_id is not null then 'RECOMPOSED'
  when unknown_count>0 then 'CHECK_ORIGINAL_ATTEMPT' when paused_count>0 then 'PAUSED' else 'OBSOLETE' end;
 return jsonb_build_object('ok',true,'version','TIMESHEET_QUERY_RECOMPOSE_RESULT_V1','mail_outbox_id',requested.mail_outbox_id,'query_delivery_id',requested.id,
  'original_delivery_id',root.id,'disposition',outcome,'replacements',case when target_id is null then '[]'::jsonb
   else jsonb_build_array(jsonb_build_object('mail_outbox_id',target_mail,'query_delivery_id',target_id)) end,
  'excluded',excluded,'next_eligible_at_utc',case when next_at is null then null else to_char(next_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end);
end;
$function$;

create or replace function public.timesheet_query_email_enqueue_v1(
 p_import_id uuid,p_operation_id uuid,p_selected_action_ids jsonb,p_actor_user_id uuid default null,p_max_actions integer default 5000,p_max_groups integer default 100
) returns jsonb language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare deployment public.candidate_push_timing_policy%rowtype;pair record;r jsonb;group_row jsonb;prepared jsonb;results jsonb:='[]';
begin
 perform private.weekly_source_query_require_service_v1();perform public._import_review_assert_actor_v1(p_actor_user_id);
 select * into strict deployment from public.candidate_push_timing_policy where deployment_slot;
 perform private.weekly_contact_deployment_lock_v1(deployment.agency_id,deployment.environment);
 perform private.weekly_contact_context_v1(deployment.agency_id,deployment.environment);
 -- Native core still validates the exact whole committed operation action set.
 for pair in select distinct a.candidate_id,a.client_id from public.import_review_decisions a
  join public.import_review_action_outcomes x on x.action_id=a.action_id and x.operation_id=p_operation_id and x.import_id=p_import_id
  where a.import_id=p_import_id and a.action_kind in('EMAIL_ISSUE','EMAIL_REMINDER')
  and a.action_id in(select value from jsonb_array_elements_text(p_selected_action_ids)) order by a.candidate_id,a.client_id loop
  perform private.weekly_contact_scope_lock_v1(deployment.agency_id,deployment.environment,pair.candidate_id,pair.client_id);
 end loop;
 perform 1 from public.mail_outbox o join public.hr_issue_email_deliveries d on d.mail_outbox_id=o.id
  where d.operation_id=p_operation_id order by o.id for update of o;
 perform 1 from public.hr_issue_email_deliveries d where d.operation_id=p_operation_id order by d.id for update;
 r:=private.weekly_contact_query_enqueue_core_v1(p_import_id,p_operation_id,p_selected_action_ids,p_actor_user_id,p_max_actions,p_max_groups,null,1);
 for group_row in select value from jsonb_array_elements(r->'groups') loop
  prepared:=private.weekly_contact_query_recompose_v1((group_row->>'delivery_id')::uuid,deployment.agency_id,deployment.environment);
  results:=results||jsonb_build_array(prepared);
 end loop;
 return r||jsonb_build_object('contact_recomposition',results);
end;
$function$;

create or replace function public.timesheet_query_email_recompose_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
begin
 perform private.weekly_source_query_require_service_v1();
 perform private.weekly_contact_assert_closed_v1(p_request,array['version','mail_outbox_id','query_delivery_id','attempt_lease_token','worker_id','agency_id','environment'],
  array['version','mail_outbox_id','query_delivery_id','attempt_lease_token','worker_id','agency_id','environment'],'CONTACT_REQUEST_INVALID');
 if p_request->>'version' is distinct from 'TIMESHEET_QUERY_RECOMPOSE_V1' or not coalesce(p_request->>'environment' in('TEST','LIVE'),false)
  or jsonb_typeof(p_request->'attempt_lease_token') is distinct from 'string' or char_length(p_request->>'attempt_lease_token') not between 1 and 500
  or jsonb_typeof(p_request->'worker_id') is distinct from 'string' or char_length(p_request->>'worker_id') not between 1 and 200 then
  raise exception 'CONTACT_REQUEST_INVALID' using errcode='22023';end if;
 return private.weekly_contact_query_recompose_v1(private.weekly_contact_uuid_v1(p_request->'query_delivery_id'),
  private.weekly_contact_uuid_v1(p_request->'agency_id'),p_request->>'environment',
  private.weekly_contact_uuid_v1(p_request->'mail_outbox_id'),p_request->>'attempt_lease_token');
end;
$function$;

-- Bounded native wake at the existing drain: no second sender or queue. Early
-- RESUME is discovered from the real scope revision's update time; expiry from
-- the actual retired root's next native recheck time. Neither implies outcome.
create or replace function public.timesheet_query_email_recompose_ready_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare v_agency uuid;v_environment text;v_limit integer;row record;results jsonb:='[]';r jsonb;
begin
 perform private.weekly_source_query_require_service_v1();
 perform private.weekly_contact_assert_closed_v1(p_request,array['version','limit','worker_id','agency_id','environment'],array['version','limit','worker_id','agency_id','environment'],'CONTACT_REQUEST_INVALID');
 if p_request->>'version' is distinct from 'TIMESHEET_QUERY_RECOMPOSE_READY_V1' or jsonb_typeof(p_request->'limit') is distinct from 'number'
  or p_request->>'limit'!~'^[0-9]{1,3}$' or (p_request->>'limit')::integer not between 1 and 100
  or not coalesce(p_request->>'environment' in('TEST','LIVE'),false) or jsonb_typeof(p_request->'worker_id') is distinct from 'string'
  or char_length(p_request->>'worker_id') not between 1 and 200 then raise exception 'CONTACT_REQUEST_INVALID' using errcode='22023';end if;
 v_agency:=private.weekly_contact_uuid_v1(p_request->'agency_id');v_environment:=p_request->>'environment';v_limit:=(p_request->>'limit')::integer;
 perform private.weekly_contact_deployment_lock_v1(v_agency,v_environment);perform private.weekly_contact_context_v1(v_agency,v_environment);
 for row in select d.id from public.hr_issue_email_deliveries d join public.mail_outbox o on o.id=d.mail_outbox_id
  where d.original_delivery_id=d.id and d.status='RETIRED' and d.contact_managed
   and ((o.next_attempt_at_utc is not null and o.next_attempt_at_utc<=clock_timestamp()) or exists(
    select 1 from public.hr_issue_email_delivery_items item join public.import_review_decisions a on a.action_id=item.action_id
    join public.weekly_contact_pause_scopes s on s.candidate_id=a.candidate_id and s.client_id=a.client_id and s.agency_id=v_agency and s.environment=v_environment
    where item.delivery_id=d.id and s.updated_at_utc>coalesce(d.contact_rechecked_at_utc,d.created_at_utc)))
  order by coalesce(o.next_attempt_at_utc,d.retired_at_utc),d.id limit v_limit loop
  begin
   r:=private.weekly_contact_query_recompose_v1(row.id,v_agency,v_environment);results:=results||jsonb_build_array(r);
  exception when sqlstate '42501' or sqlstate '55000' or sqlstate '40001' then
   results:=results||jsonb_build_array(jsonb_build_object('query_delivery_id',row.id,'disposition','HELD_NATIVE_RECHECK','reason',sqlerrm));
  end;
 end loop;
 return jsonb_build_object('ok',true,'version','TIMESHEET_QUERY_RECOMPOSE_READY_RESULT_V1','results',results);
end;
$function$;

create or replace function public.timesheet_query_email_contact_result_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare permit public.weekly_contact_submission_permits%rowtype;mail public.mail_outbox%rowtype;delivery public.hr_issue_email_deliveries%rowtype;
 pair jsonb;saved jsonb;provider jsonb;at_utc timestamptz;receipt jsonb;marked jsonb;logical bytea;member jsonb;ordinal integer;
 agency uuid;environment text;permit_id uuid;outbox_id uuid;v_delivery_id uuid;provider_identity text;
begin
 perform private.weekly_source_query_require_service_v1();
 perform private.weekly_contact_assert_closed_v1(p_request,array['version','contact_permit_id','mail_outbox_id','query_delivery_id','attempt_lease_token','worker_id','content_hash','provider_result','agency_id','environment'],
  array['version','contact_permit_id','mail_outbox_id','query_delivery_id','attempt_lease_token','worker_id','content_hash','provider_result','agency_id','environment'],'CONTACT_REQUEST_INVALID');
 provider:=p_request->'provider_result';
 perform private.weekly_contact_assert_closed_v1(provider,array['status','provider_message_id','error'],array['status','provider_message_id','error'],'CONTACT_REQUEST_INVALID');
 if p_request->>'version' is distinct from 'TIMESHEET_QUERY_RESULT_V1' or not coalesce(provider->>'status' in('SUCCESS','FAILED','UNKNOWN'),false)
  or jsonb_typeof(p_request->'attempt_lease_token') is distinct from 'string' or char_length(p_request->>'attempt_lease_token') not between 1 and 500
  or jsonb_typeof(p_request->'worker_id') is distinct from 'string' or char_length(p_request->>'worker_id') not between 1 and 200
  or jsonb_typeof(p_request->'content_hash') is distinct from 'string' or not coalesce(p_request->>'content_hash'~'^[0-9a-f]{64}$',false) or not coalesce(p_request->>'environment' in('TEST','LIVE'),false)
  or (provider->'provider_message_id'<>'null'::jsonb and(jsonb_typeof(provider->'provider_message_id')<>'string' or char_length(provider->>'provider_message_id') not between 1 and 500))
  or (provider->'error'<>'null'::jsonb and(jsonb_typeof(provider->'error')<>'string' or char_length(provider->>'error')>1000)) then
  raise exception 'CONTACT_REQUEST_INVALID' using errcode='22023';end if;
 agency:=private.weekly_contact_uuid_v1(p_request->'agency_id');environment:=p_request->>'environment';
 permit_id:=private.weekly_contact_uuid_v1(p_request->'contact_permit_id');outbox_id:=private.weekly_contact_uuid_v1(p_request->'mail_outbox_id');
 v_delivery_id:=private.weekly_contact_uuid_v1(p_request->'query_delivery_id');
 perform private.weekly_contact_deployment_lock_v1(agency,environment);perform private.weekly_contact_context_v1(agency,environment);
 select * into strict permit from public.weekly_contact_submission_permits where id=permit_id;
 for pair in select value from jsonb_array_elements(permit.scope_revisions_json) order by value->>'candidate_id',value->>'client_id' loop
  perform private.weekly_contact_scope_lock_v1(agency,environment,(pair->>'candidate_id')::uuid,(pair->>'client_id')::uuid);
 end loop;
 select * into strict mail from public.mail_outbox where id=outbox_id for update;
 select * into strict delivery from public.hr_issue_email_deliveries where id=v_delivery_id for update;
 select * into strict permit from public.weekly_contact_submission_permits where id=permit_id for update;
 if permit.owner_kind<>'TIMESHEET_QUERY_OUTBOX' or permit.mail_outbox_id<>mail.id or permit.query_delivery_id<>delivery.id
  or permit.agency_id<>agency or permit.environment<>environment or permit.lease_token is distinct from p_request->>'attempt_lease_token'
  or permit.lease_owner is distinct from p_request->>'worker_id' or permit.content_hash<>decode(p_request->>'content_hash','hex')
  or permit.status not in('STARTED','AMBIGUOUS','ACCEPTED') or permit.admitted_at_utc is null or permit.consumed_at_utc is null
  or not delivery.contact_managed or delivery.status='RETIRED' then raise exception 'CONTACT_QUERY_RESULT_SCOPE_INVALID' using errcode='42501';end if;
 -- Original immutable ownership is re-read, without demanding live eligibility
 -- or the creator's later permission. A pause/reply/permission loss after START
 -- cannot erase a genuine acceptance. The original lease identity must match;
 -- its expiry never proves submission or failure and never creates a new one.
 saved:=private.weekly_contact_query_saved_payload_v1(mail.id,delivery.id);
 if saved->>'content_hash'<>encode(permit.content_hash,'hex') or saved->>'recipient_hash'<>encode(permit.recipient_hash,'hex') then
  raise exception 'CONTACT_QUERY_RESULT_SCOPE_INVALID' using errcode='42501';end if;
 if permit.status='ACCEPTED' then
  if permit.accepted_result_json->'provider_result' is distinct from provider then raise exception 'CONTACT_QUERY_RESULT_CONFLICT' using errcode='40001';end if;
  return permit.accepted_result_json->'receipt';
 end if;
 at_utc:=clock_timestamp();ordinal:=delivery.reminder_sequence+1;provider_identity:=nullif(btrim(provider->>'provider_message_id'),'');
 for member in select value from jsonb_array_elements(saved->'members') loop
  logical:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_QUERY_MEMBERSHIP_V1',jsonb_build_object('issue_id',member->'issue_id','purpose','TIMESHEET_QUERY'));
  if not exists(select 1 from public.weekly_contact_delivery_memberships m where m.delivery_id=delivery.id and m.logical_contact_key=logical
   and m.send_ordinal=ordinal and m.payload_revision=(saved->>'payload_revision')::bigint and m.content_hash=permit.content_hash and m.candidate_id=(member->>'candidate_id')::uuid
   and m.client_id=(member->>'client_id')::uuid and m.accepted_at_utc is null
   and exists(select 1 from jsonb_array_elements(permit.scope_revisions_json)s where (s->>'scope_id')::uuid=m.scope_id
    and (s->>'candidate_id')::uuid=m.candidate_id and(s->>'client_id')::uuid=m.client_id and s->>'audience'='MANAGER'
    and(s->>'revision')::bigint=m.scope_revision)) then raise exception 'CONTACT_QUERY_RESULT_SCOPE_INVALID' using errcode='42501';end if;
 end loop;
 if (select count(*) from public.weekly_contact_delivery_memberships m where m.delivery_id=delivery.id and m.content_hash=permit.content_hash and m.send_ordinal=ordinal)
  <>jsonb_array_length(saved->'members') then raise exception 'CONTACT_QUERY_RESULT_SCOPE_INVALID' using errcode='42501';end if;
 receipt:=jsonb_build_object('ok',true,'version','TIMESHEET_QUERY_RESULT_RECORDED_V1','contact_permit_id',permit.id,
  'mail_outbox_id',mail.id,'query_delivery_id',delivery.id,'disposition',case when provider->>'status'='SUCCESS' then 'ACCEPTED' else 'AMBIGUOUS' end);
 if provider->>'status'='SUCCESS' then
  update public.weekly_contact_submission_permits set status='ACCEPTED',accepted_at_utc=at_utc,
   provider_idempotency_identity=provider_identity,accepted_result_json=jsonb_build_object('provider_result',provider,'receipt',receipt) where id=permit.id;
  update public.weekly_contact_delivery_memberships set accepted_at_utc=at_utc where delivery_id=delivery.id and content_hash=permit.content_hash and send_ordinal=ordinal and accepted_at_utc is null;
  update public.mail_outbox set status='SENT',sent_at=at_utc,provider_status='ACCEPTED',provider_message_id=provider_identity,
   last_error=null,failed_at=null,attempt_lease_token=null,attempt_leased_at_utc=null,attempt_lease_expires_at_utc=null where id=mail.id;
  marked:=public._timesheet_query_email_delivery_mark_core_v1(mail.id,provider_identity,'ACCEPTED',at_utc,delivery.created_by_user_id);
 else
  -- The inspected provider FAILED vocabulary does not certify NOT_SUBMITTED.
  -- Preserve the same admitted attempt for missing/failed/unknown responses.
  update public.weekly_contact_submission_permits set status='AMBIGUOUS' where id=permit.id;
  update public.mail_outbox set status='FAILED',provider_status='DELIVERY_UNCERTAIN',last_error=coalesce(provider->>'error','Provider outcome is being checked'),
   attempt_lease_token=null,attempt_leased_at_utc=null,attempt_lease_expires_at_utc=null where id=mail.id;
  update public.hr_issue_email_deliveries set status='FAILED',provider_status='DELIVERY_UNCERTAIN',updated_at_utc=at_utc where id=delivery.id;
 end if;
 return receipt;
end;
$function$;

-- Existing native lifecycle reconciliation, using real accepted action
-- coverage rather than requiring retired audit parents to become SENT.
create or replace function private.weekly_contact_query_complete_v1(p_import_id uuid,p_operation_id uuid,p_actor_user_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare state public.import_review_states%rowtype;op public.import_apply_operations%rowtype;result jsonb;
begin
 select * into strict state from public.import_review_states where import_id=p_import_id for update;
 select * into strict op from public.import_apply_operations where id=p_operation_id and import_id=p_import_id for update;
 if state.last_operation_id is distinct from op.id then return null;end if;
 if exists(select 1 from jsonb_array_elements_text(coalesce(op.response_json->'post_commit_email_action_ids','[]'::jsonb)) planned(action_id)
  join public.import_review_decisions a on a.action_id=planned.action_id and a.import_id=p_import_id
  where a.is_current and a.selected and not exists(
   select 1 from public.hr_issue_email_delivery_items item join public.hr_issue_email_deliveries d on d.id=item.delivery_id
   where item.action_id=a.action_id and item.marked_sent_at_utc is not null and d.status='SENT')) then return null;end if;
 if op.response_json->>'review_email_follow_up_status'='COMPLETE' then return jsonb_build_object('follow_up_status',state.follow_up_status);end if;
 update public.import_apply_operations set response_json=response_json||jsonb_build_object('review_email_follow_up_status','COMPLETE'),updated_at_utc=clock_timestamp() where id=op.id;
 result:=public._import_review_follow_up_reconcile_core_v1(p_import_id,p_operation_id,p_actor_user_id);
 select * into strict state from public.import_review_states where import_id=p_import_id;
 insert into public.import_review_events(import_id,state_version,operation_id,event_code,actor_user_id,event_context_json)
 values(p_import_id,state.state_version,p_operation_id,'QUERY_EMAIL_FOLLOW_UP_COMPLETE',p_actor_user_id,
  jsonb_build_object('contact_disposition','ACCEPTED_OR_NO_CURRENT_ACTION','changes_sent_history',false));
 return result;
end;
$function$;

create or replace function public._timesheet_query_email_delivery_mark_core_v1(
  p_mail_outbox_id uuid,p_provider_message_id text,p_provider_status text,p_accepted_at_utc timestamptz,p_actor_user_id uuid
)
returns jsonb language plpgsql security definer set search_path to 'public','pg_temp' as $function$
declare d public.hr_issue_email_deliveries%rowtype; o public.mail_outbox%rowtype; v_marked integer:=0; v_state public.import_review_states%rowtype; v_reconcile jsonb;
begin
  select * into o from public.mail_outbox where id=p_mail_outbox_id for update;
  select * into d from public.hr_issue_email_deliveries where mail_outbox_id=p_mail_outbox_id for update;
  if o.id is null or d.id is null then raise exception 'TIMESHEET_QUERY_DELIVERY_NOT_FOUND' using errcode='P0002'; end if;
  if upper(coalesce(o.status::text,''))<>'SENT' and o.sent_at is null then raise exception 'TIMESHEET_QUERY_OUTBOX_NOT_SENT' using errcode='55000'; end if;
  if nullif(btrim(coalesce(o.provider_message_id,'')),'') is not null and nullif(btrim(coalesce(p_provider_message_id,'')),'') is not null
    and o.provider_message_id<>btrim(p_provider_message_id) then raise exception 'TIMESHEET_QUERY_PROVIDER_ID_MISMATCH' using errcode='22023'; end if;
  if d.status='RETIRED' then raise exception 'CONTACT_QUERY_RETIRED_DELIVERY' using errcode='42501';end if;
  if d.contact_managed and not exists(select 1 from public.weekly_contact_submission_permits p
    where p.owner_kind='TIMESHEET_QUERY_OUTBOX' and p.query_delivery_id=d.id and p.mail_outbox_id=o.id and p.status='ACCEPTED'
     and p.content_hash=decode(private.weekly_contact_query_saved_payload_v1(o.id,d.id)->>'content_hash','hex')
     and p.accepted_at_utc is not distinct from o.sent_at and p.accepted_result_json->'provider_result'->>'status'='SUCCESS') then
    raise exception 'CONTACT_QUERY_ACCEPTED_PROOF_REQUIRED' using errcode='42501';end if;
  if d.status='SENT' then return jsonb_build_object('ok',true,'replay',true,'delivery_id',d.id,'marked_issue_count',0); end if;
  update public.hr_issue_email_delivery_items set marked_sent_at_utc=coalesce(p_accepted_at_utc,o.sent_at,now())
  where delivery_id=d.id and marked_sent_at_utc is null;
  get diagnostics v_marked=row_count;
  update public.hr_issue_emails e set last_sent_at=coalesce(p_accepted_at_utc,o.sent_at,now()),sent_count=e.sent_count+1,
    last_successful_delivery_id=d.id,delivery_history_status='SENT_VERIFIED',updated_at=now()
  where e.id in (select di.issue_id from public.hr_issue_email_delivery_items di where di.delivery_id=d.id and di.marked_sent_at_utc is not null)
    and e.last_successful_delivery_id is distinct from d.id;
  update public.hr_issue_email_deliveries set status='SENT',provider_message_id=coalesce(nullif(btrim(p_provider_message_id),''),o.provider_message_id),
    provider_status=coalesce(nullif(btrim(p_provider_status),''),o.provider_status,'ACCEPTED'),accepted_at_utc=coalesce(p_accepted_at_utc,o.sent_at,now()),marked_at_utc=now(),updated_at_utc=now()
  where id=d.id returning * into d;
  v_reconcile:=private.weekly_contact_query_complete_v1(d.import_id,d.operation_id,p_actor_user_id);
  return jsonb_build_object('ok',true,'replay',false,'delivery_id',d.id,'marked_issue_count',v_marked,'status',d.status,
    'follow_up_status',coalesce(v_reconcile->>'follow_up_status',(select s.follow_up_status from public.import_review_states s where s.import_id=d.import_id)));
end $function$;

create or replace function private.weekly_contact_query_integrity_v1()
returns trigger language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare d public.hr_issue_email_deliveries%rowtype;r public.hr_issue_email_deliveries%rowtype;p public.weekly_contact_submission_permits%rowtype;
begin
 if tg_table_name='hr_issue_email_deliveries' then
  -- The original enqueue may run during DB-first runtime compatibility. Its
  -- genuine initial native INSERT owns this actual ID and revision1. It need
  -- not know the additive column to obtain the same explicit self lineage.
  if tg_op='INSERT' and new.original_delivery_id is null and new.payload_revision=1 then new.original_delivery_id:=new.id;end if;
  if tg_op='UPDATE' and (old.original_delivery_id,old.payload_revision,old.contact_managed,old.import_id,old.operation_id,old.recipient_scope,
    old.recipient_scope_key,old.recipient_route_fingerprint,old.recipient_email,old.reminder_sequence,old.issue_set_fingerprint,
    old.deterministic_outbox_key,old.mail_outbox_id,old.created_by_user_id,old.created_at_utc,old.legacy_claim_lease_token,old.legacy_claim_leased_at_utc,old.legacy_claim_expires_at_utc)
   is distinct from(new.original_delivery_id,new.payload_revision,new.contact_managed,new.import_id,new.operation_id,new.recipient_scope,
    new.recipient_scope_key,new.recipient_route_fingerprint,new.recipient_email,new.reminder_sequence,new.issue_set_fingerprint,
    new.deterministic_outbox_key,new.mail_outbox_id,new.created_by_user_id,new.created_at_utc,new.legacy_claim_lease_token,new.legacy_claim_leased_at_utc,new.legacy_claim_expires_at_utc) then
   raise exception 'CONTACT_QUERY_LINEAGE_IMMUTABLE' using errcode='23514';end if;
  if tg_op='UPDATE' and old.status='RETIRED' and(new.status,old.retired_at_utc,old.retirement_reason) is distinct from(old.status,new.retired_at_utc,new.retirement_reason) then
   raise exception 'CONTACT_QUERY_RETIRED_DELIVERY' using errcode='23514';end if;
  if new.original_delivery_id=new.id then
   if new.payload_revision<>1 then raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='23514';end if;
  else
   select * into strict r from public.hr_issue_email_deliveries where id=new.original_delivery_id;
   if r.original_delivery_id<>r.id or r.payload_revision<>1 or new.payload_revision<2 or new.import_id<>r.import_id
    or new.operation_id<>r.operation_id or new.reminder_sequence<>r.reminder_sequence or new.created_by_user_id is distinct from r.created_by_user_id then
    raise exception 'CONTACT_QUERY_SCOPE_INVALID' using errcode='23514';end if;
  end if;
  return new;
 elsif tg_table_name='hr_issue_email_delivery_items' then
  if tg_op='DELETE' or (old.delivery_id,old.issue_id,old.action_id,old.issue_fingerprint) is distinct from(new.delivery_id,new.issue_id,new.action_id,new.issue_fingerprint) then
   raise exception 'CONTACT_QUERY_FROZEN_ITEMS_IMMUTABLE' using errcode='23514';end if;
  select * into strict d from public.hr_issue_email_deliveries where id=new.delivery_id;
  if d.contact_managed and old.marked_sent_at_utc is distinct from new.marked_sent_at_utc and not exists(
   select 1 from public.weekly_contact_submission_permits x where x.query_delivery_id=d.id and x.status='ACCEPTED'
    and x.accepted_at_utc is not distinct from new.marked_sent_at_utc) then raise exception 'CONTACT_QUERY_ACCEPTED_PROOF_REQUIRED' using errcode='42501';end if;
  return new;
 elsif tg_table_name='mail_outbox' then
  if new.type<>'TIMESHEET_QUERY' then return new;end if;
  select * into strict d from public.hr_issue_email_deliveries where mail_outbox_id=new.id;
  if old.status::text='SENT' or old.sent_at is not null then
   if new.status::text<>'SENT' or new.sent_at is distinct from old.sent_at or new.provider_message_id is distinct from old.provider_message_id then
    raise exception 'CONTACT_QUERY_ACCEPTED_HISTORY_IMMUTABLE' using errcode='23514';end if;
   -- Genuine later delivery/read callbacks retain their existing metadata.
   return new;
  end if;
  if new.status::text<>'SENT' and new.sent_at is null then return new;end if;
  if not d.contact_managed then
   if d.legacy_claim_lease_token is null or d.legacy_claim_leased_at_utc is null or d.legacy_claim_expires_at_utc is null
    or d.legacy_claim_expires_at_utc<=d.legacy_claim_leased_at_utc or old.attempt_lease_token is distinct from d.legacy_claim_lease_token
    or old.attempt_leased_at_utc is distinct from d.legacy_claim_leased_at_utc
    or old.attempt_lease_expires_at_utc is distinct from d.legacy_claim_expires_at_utc
    or new.status::text<>'SENT' or new.sent_at is null or new.provider_status is distinct from 'ACCEPTED' then
    raise exception 'CONTACT_QUERY_LEGACY_CLAIM_PROOF_REQUIRED' using errcode='42501';end if;
   return new;
  end if;
  select * into p from public.weekly_contact_submission_permits x where x.query_delivery_id=d.id and x.mail_outbox_id=new.id and x.status='ACCEPTED';
  if p.id is null or d.status='RETIRED' or p.accepted_at_utc is distinct from new.sent_at or new.provider_status is distinct from 'ACCEPTED'
   or p.provider_idempotency_identity is distinct from new.provider_message_id
   or p.content_hash<>decode(private.weekly_contact_query_saved_payload_v1(old.id,d.id)->>'content_hash','hex') then
   raise exception 'CONTACT_QUERY_ACCEPTED_PROOF_REQUIRED' using errcode='42501';end if;
  return new;
 end if;
 raise exception 'CONTACT_QUERY_GUARD_SCOPE_INVALID' using errcode='23514';
end;
$function$;

-- Existing native claim provenance only. This is not provider admission.
-- The real picked CTE has already locked these exact mail rows with the native
-- queue predicates/order/bounds. Fixed deployment/service checks are repeated.
create or replace function public._email_outbox_contact_claim_stamp_v1(p_ids uuid[],p_token text,p_at timestamptz,p_expires timestamptz,p_agency uuid,p_environment text)
returns boolean language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
begin
 perform private.weekly_source_query_require_service_v1();
 perform private.weekly_contact_context_v1(p_agency,p_environment);
 if cardinality(p_ids)>500 or nullif(btrim(p_token),'') is null or p_at is distinct from transaction_timestamp()
  or p_expires<=p_at or p_expires>p_at+interval '30 minutes' then raise exception 'CONTACT_QUERY_CLAIM_INVALID' using errcode='22023';end if;
 update public.hr_issue_email_deliveries d set contact_claim_backend_pid=pg_backend_pid(),contact_claim_transaction_id=pg_current_xact_id(),
  contact_claim_token=p_token,contact_claim_at_utc=p_at,contact_claim_expires_at_utc=p_expires
 from public.mail_outbox o,public.hr_issue_email_deliveries original
 where o.id=any(p_ids) and d.mail_outbox_id=o.id and o.type='TIMESHEET_QUERY' and d.contact_managed and d.legacy_claim_lease_token is null
  and d.status='QUEUED' and d.retired_at_utc is null and original.id=d.original_delivery_id and original.original_delivery_id=original.id and original.payload_revision=1
  and o.status::text='QUEUED' and o.sent_at is null and o.delivered_at is null and o.read_at is null
  and coalesce(o.next_attempt_at_utc,o.scheduled_for_utc,o.created_at_utc)<=p_at
  and(o.attempt_lease_token is null or o.attempt_lease_expires_at_utc is null or o.attempt_lease_expires_at_utc<=p_at)
  and d.contact_claim_backend_pid is null and d.contact_claim_transaction_id is null and d.contact_claim_token is null
  and d.contact_claim_at_utc is null and d.contact_claim_expires_at_utc is null;
 return true;
end;
$function$;

create or replace function public._email_outbox_contact_claim_cleanup_v1(p_token text)
returns void language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
begin
 perform private.weekly_source_query_require_service_v1();
 update public.hr_issue_email_deliveries set contact_claim_backend_pid=null,contact_claim_transaction_id=null,contact_claim_token=null,
  contact_claim_at_utc=null,contact_claim_expires_at_utc=null
 where contact_claim_backend_pid=pg_backend_pid() and contact_claim_transaction_id=pg_current_xact_id_if_assigned() and contact_claim_token=p_token;
end;
$function$;

create or replace function private.weekly_contact_query_claim_guard_v1()
returns trigger language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare d public.hr_issue_email_deliveries%rowtype;
begin
 if tg_table_name='hr_issue_email_deliveries' then
  -- Deferred final state, including update-then-clear within the same claim.
  if exists(select 1 from public.hr_issue_email_deliveries x where x.id=new.id and
   (x.contact_claim_backend_pid is not null or x.contact_claim_transaction_id is not null or x.contact_claim_token is not null
    or x.contact_claim_at_utc is not null or x.contact_claim_expires_at_utc is not null)) then
   raise exception 'CONTACT_QUERY_CLAIM_STAMP_SURVIVED' using errcode='23514';end if;
  return null;
 end if;
 if new.type<>'TIMESHEET_QUERY' or new.attempt_lease_token is null
  or(new.attempt_lease_token,new.attempt_leased_at_utc,new.attempt_lease_expires_at_utc)
   is not distinct from(old.attempt_lease_token,old.attempt_leased_at_utc,old.attempt_lease_expires_at_utc) then return new;end if;
 select * into strict d from public.hr_issue_email_deliveries where mail_outbox_id=new.id;
 if not d.contact_managed or d.legacy_claim_lease_token is not null or d.status<>'QUEUED' or d.retired_at_utc is not null
  or d.contact_claim_backend_pid is distinct from pg_backend_pid() or d.contact_claim_transaction_id is distinct from pg_current_xact_id_if_assigned()
  or d.contact_claim_token is distinct from new.attempt_lease_token or d.contact_claim_at_utc is distinct from new.attempt_leased_at_utc
  or d.contact_claim_expires_at_utc is distinct from new.attempt_lease_expires_at_utc or new.attempt_leased_at_utc is distinct from transaction_timestamp()
  or new.status::text<>'QUEUED' or new.sent_at is not null or new.delivered_at is not null or new.read_at is not null then
  raise exception 'CONTACT_QUERY_CURRENT_CLAIM_BRIDGE_REQUIRED' using errcode='42501';end if;
 return new;
end;
$function$;

create or replace function public._email_outbox_contact_claim_core_v1(
  p_limit integer,
  p_attempt_lease_token text,
  p_lease_minutes integer default 5,p_contact_bridge boolean default false,p_agency uuid default null,p_environment text default null
) returns setof public.mail_outbox
language plpgsql
security invoker
set search_path to 'public','pg_temp'
as $function$
declare
  v_now timestamptz:=now();
  v_limit integer:=greatest(0,least(coalesce(p_limit,0),500));
  v_lease integer:=greatest(1,least(coalesce(p_lease_minutes,5),30));
begin
  if coalesce(btrim(p_attempt_lease_token),'')='' then raise exception 'attempt_lease_token is required'; end if;
  if v_limit=0 then return; end if;

  return query
  with picked as materialized (
    select mo.id
    from public.mail_outbox mo
    where (mo.type<>'TIMESHEET_QUERY' or(p_contact_bridge and exists(
      select 1 from public.hr_issue_email_deliveries d join public.hr_issue_email_deliveries original on original.id=d.original_delivery_id
      where d.mail_outbox_id=mo.id and d.contact_managed and d.legacy_claim_lease_token is null
       and d.status='QUEUED' and d.retired_at_utc is null and original.original_delivery_id=original.id and original.payload_revision=1)))
      and mo.status='QUEUED' and mo.sent_at is null and mo.delivered_at is null and mo.read_at is null
      and coalesce(mo.next_attempt_at_utc,mo.scheduled_for_utc,mo.created_at_utc)<=v_now
      and (mo.attempt_lease_token is null or mo.attempt_lease_expires_at_utc is null
        or mo.attempt_lease_expires_at_utc<=v_now)
      and (
        not (
          nullif(btrim(coalesce(mo.payment_scope_json->>'candidate_workflow_id','')),'') is not null
          or mo.payment_scope_json ? 'candidate_workflow_generation'
          or mo.payment_scope_json ? 'paper_return_manifest_sha256'
          or mo.payment_scope_json ? 'candidate_paper_pack_ready'
          or mo.payment_scope_json ? 'candidate_complete_pack_storage_key'
          or upper(coalesce(mo.payment_scope_json->>'mail_hold_reason',''))
            ='CANDIDATE_PAPER_PACK_PENDING'
          or upper(coalesce(mo.payment_scope_json->>'candidate_mail_authority',''))
            ='MANAGER_APPROVAL_V1'
        )
        or (
          coalesce(mo.payment_scope_json->>'candidate_workflow_id','') ~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          and coalesce(mo.payment_scope_json->>'candidate_workflow_generation','')
            ~ '^[1-9][0-9]{0,8}$'
          and lower(coalesce(mo.payment_scope_json->>'paper_return_manifest_sha256',''))
            ~ '^[0-9a-f]{64}$'
          and lower(coalesce(mo.payment_scope_json->>'candidate_paper_pack_ready','false'))
            in('true','t','1','yes')
          and lower(coalesce(mo.payment_scope_json->>'candidate_paper_generation_retired','false'))
            in('false','f','0','no')
          and lower(coalesce(mo.payment_scope_json->>'mail_held_until_pdf_rendered','true'))
            in('false','f','0','no')
          and nullif(btrim(coalesce(mo.payment_scope_json->>'mail_hold_reason','')),'') is null
          and jsonb_typeof(mo.attachments)='array'
          and jsonb_array_length(mo.attachments)=1
          and nullif(btrim(coalesce(mo.attachments->0->>'r2_key','')),'') is not null
          and lower(coalesce(mo.attachments->0->>'sha256','')) ~ '^[0-9a-f]{64}$'
          and coalesce(mo.attachments->0->>'size_bytes','') ~ '^[1-9][0-9]{0,18}$'
          and coalesce(mo.attachments->0->>'page_count','') ~ '^[1-9][0-9]{0,8}$'
          and lower(coalesce(mo.attachments->0->>'content_type',''))='application/pdf'
          and mo.attachments->0->>'r2_key'
            =mo.payment_scope_json->>'candidate_complete_pack_storage_key'
          and lower(mo.attachments->0->>'sha256')
            =lower(mo.payment_scope_json->>'candidate_complete_pack_sha256')
          and mo.attachments->0->>'size_bytes'
            =mo.payment_scope_json->>'candidate_complete_pack_size_bytes'
          and mo.attachments->0->>'page_count'
            =mo.payment_scope_json->>'candidate_complete_pack_page_count'
          and lower(coalesce(mo.payment_scope_json->>'candidate_complete_pack_media_type',''))
            ='application/pdf'
          and mo.attachments->0->>'candidate_workflow_id'
            =mo.payment_scope_json->>'candidate_workflow_id'
          and mo.attachments->0->>'candidate_workflow_generation'
            =mo.payment_scope_json->>'candidate_workflow_generation'
          and lower(mo.attachments->0->>'paper_return_manifest_sha256')
            =lower(mo.payment_scope_json->>'paper_return_manifest_sha256')
          and exists(
            select 1
            from public.candidate_submission_workflows workflow
            where workflow.id=case
                when coalesce(mo.payment_scope_json->>'candidate_workflow_id','') ~*
                  '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                then (mo.payment_scope_json->>'candidate_workflow_id')::uuid
                else null::uuid end
              and workflow.generation=case
                when coalesce(mo.payment_scope_json->>'candidate_workflow_generation','')
                  ~ '^[1-9][0-9]{0,8}$'
                then (mo.payment_scope_json->>'candidate_workflow_generation')::integer
                else null::integer end
              and workflow.route='PAPER'
              and workflow.state='AWAITING_PAPER_RETURN'
              and encode(workflow.paper_return_manifest_sha256,'hex')
                =lower(mo.payment_scope_json->>'paper_return_manifest_sha256')
              and coalesce(workflow.target_timesheet_id,workflow.anchor_timesheet_id)=mo.context_id
          )
        )
        or (
          upper(coalesce(mo.payment_scope_json->>'candidate_mail_authority',''))
            ='MANAGER_APPROVAL_V1'
          and upper(coalesce(mo.payment_scope_json->>'candidate_manager_mail_kind',''))
            in ('INITIAL','REMINDER','RENEWAL','WITHDRAWAL','CANCELLATION')
          and lower(coalesce(mo.payment_scope_json->>'candidate_manager_mail_retired','false'))
            in ('false','f','0','no')
          and coalesce(mo.payment_scope_json->>'candidate_manager_workflow_id','') ~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          and coalesce(mo.payment_scope_json->>'candidate_manager_workflow_generation','')
            ~ '^[1-9][0-9]{0,8}$'
          and coalesce(mo.payment_scope_json->>'candidate_approval_request_id','') ~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          and coalesce(mo.payment_scope_json->>'candidate_approval_request_generation','')
            ~ '^[1-9][0-9]{0,8}$'
          and (
            upper(mo.payment_scope_json->>'candidate_manager_mail_kind') in ('WITHDRAWAL','CANCELLATION')
            or (
              coalesce(mo.payment_scope_json->>'candidate_manager_route_receipt_id','') ~*
                '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              and coalesce(mo.payment_scope_json->>'candidate_manager_route_ticket_id','') ~*
                '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              and coalesce(mo.payment_scope_json->>'candidate_manager_route_revision','')
                ~ '^[1-9][0-9]{0,18}$'
              and lower(coalesce(
                    mo.payment_scope_json->>'candidate_manager_route_registration_sha256',''))
                ~ '^[0-9a-f]{64}$'
              and private._candidate_manager_email_claim_route_current_v1(
                (mo.payment_scope_json->>'candidate_manager_route_receipt_id')::uuid,
                (mo.payment_scope_json->>'candidate_manager_route_ticket_id')::uuid,
                (mo.payment_scope_json->>'candidate_manager_route_revision')::bigint,
                mo.payment_scope_json->>'candidate_manager_route_registration_sha256',
                mo.context_id,
                (mo.payment_scope_json->>'candidate_approval_request_id')::uuid,
                (mo.payment_scope_json->>'candidate_approval_request_generation')::integer
              )
            )
          )
          and mo.context_kind='CANDIDATE_WORKFLOW'
          and mo.context_id=(mo.payment_scope_json->>'candidate_manager_workflow_id')::uuid
          and exists (
            select 1
            from public.candidate_approval_requests request_row
            join public.candidate_submission_workflows workflow
              on workflow.id=request_row.workflow_id
            where request_row.id=(mo.payment_scope_json->>'candidate_approval_request_id')::uuid
              and request_row.workflow_id=mo.context_id
              and request_row.workflow_generation=
                    (mo.payment_scope_json->>'candidate_manager_workflow_generation')::integer
              and request_row.request_generation=
                    (mo.payment_scope_json->>'candidate_approval_request_generation')::integer
              and request_row.method='EMAIL'
              and request_row.manager_email_normalized=mo."to"
              and (
                (
                  upper(mo.payment_scope_json->>'candidate_manager_mail_kind')
                    in ('INITIAL','REMINDER','RENEWAL')
                  and request_row.state='PENDING'
                  and request_row.expires_at_utc>v_now
                  and workflow.generation=request_row.workflow_generation
                  and workflow.route='EMAIL'
                  and workflow.state='AWAITING_MANAGER_APPROVAL'
                  and workflow.review_manifest_sha256=request_row.review_manifest_sha256
                )
                or (
                  upper(mo.payment_scope_json->>'candidate_manager_mail_kind') in ('WITHDRAWAL','CANCELLATION')
                  and request_row.state in ('CANCELLED','SUPERSEDED','EXPIRED','REFUSED')
                )
              )
          )
        )
        or (
          -- The completed Weekly Timesheet copy is informational, not a
          -- manager-approval or paper-return command.  Admit only the exact
          -- immutable completion event and its single rendered PDF; leave
          -- every existing Candidate and payment-mail branch unchanged.
          mo.email_type='WEEKLY_COMPLETED_TIMESHEET_COPY'
          and mo.type='TIMESHEET_GENERAL'
          and mo.recipient_kind='CLIENT_INFORMATIONAL_COPY'
          and mo.context_kind='timesheets'
          and mo.attachments_ready=true
          and mo.attachment_delivery_policy='ATTACH'
          and mo.payment_scope_json->>'completed_pack_copy_authority'
            ='WEEKLY_COMPLETED_PACK_COPY_V1'
          and mo.payment_scope_json->>'informational_only'='true'
          and mo.payment_scope_json->>'changes_pay'='false'
          and mo.payment_scope_json->>'changes_invoice'='false'
          and nullif(btrim(coalesce(
            mo.payment_scope_json->>'candidate_mail_authority','')),'') is null
          and not (mo.payment_scope_json ? 'paper_return_manifest_sha256')
          and not (mo.payment_scope_json ? 'candidate_manager_mail_kind')
          and mo.body_html !~* 'href=|https?://'
          and mo.body_text !~* 'https?://'
          and jsonb_typeof(mo.attachments)='array'
          and jsonb_array_length(mo.attachments)=1
          and nullif(btrim(coalesce(mo.attachments->0->>'r2_key','')),'') is not null
          and lower(coalesce(mo.attachments->0->>'content_type',''))='application/pdf'
          and coalesce(mo.attachments->0->>'sha256','') ~ '^[0-9a-f]{64}$'
          and coalesce(mo.attachments->0->>'size_bytes','') ~ '^[1-9][0-9]{0,18}$'
          and coalesce(mo.attachments->0->>'page_count','') ~ '^[1-9][0-9]{0,8}$'
          and private._weekly_source_completed_pack_copy_claim_event_valid_v1(mo)
        )
      )
      and (
        upper(coalesce(mo.type,''))<>'INVOICE'
        or (
          mo.attachments_ready=true and mo.waiting_invoice_operation_id is null
          and jsonb_typeof(mo.attachments)='array' and jsonb_array_length(mo.attachments)>0
          and not exists (
            select 1 from jsonb_array_elements(mo.attachments) a
            left join lateral (
              select
                case when coalesce(a->>'document_version_id','') ~*
                  '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                  then(a->>'document_version_id')::uuid end document_version_id,
                case when coalesce(a->>'invoice_id','') ~*
                  '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                  then(a->>'invoice_id')::uuid end invoice_id,
                case when coalesce(a->>'size_bytes','') ~ '^[0-9]{1,18}$'
                  then(a->>'size_bytes')::bigint end size_bytes,
                case when coalesce(a->>'page_count','') ~ '^[0-9]{1,9}$'
                  then(a->>'page_count')::integer end page_count,
                upper(coalesce(nullif(a->>'delivery_mode',''),
                  'ATTACHMENT')) delivery_mode,
                lower(coalesce(a->>'secure_link_required','false'))
                  in('true','t','1','yes') secure_link_required
            ) parsed on true
            left join public.invoice_document_versions v
              on v.id=parsed.document_version_id
            left join public.invoices i on i.id=parsed.invoice_id
            where parsed.document_version_id is null or parsed.invoice_id is null
              or parsed.delivery_mode not in('ATTACHMENT','SECURE_LINK')
              or nullif(a->>'sha256','') is null
              or nullif(a->>'filename','') is null
              or coalesce(parsed.size_bytes,0)<=0 or coalesce(parsed.page_count,0)<=0
              or v.id is null or v.status<>'READY' or v.superseded_at_utc is not null
              or v.purpose<>'FINAL_ISSUE' or v.entity_type<>'INVOICE'
              or v.entity_id is distinct from parsed.invoice_id
              or i.id is null or i.status<>'ISSUED'
              or i.issued_document_version_id is distinct from v.id
              or v.sha256 is distinct from a->>'sha256'
              or v.size_bytes is distinct from parsed.size_bytes
              or v.page_count is distinct from parsed.page_count
              or(parsed.delivery_mode='ATTACHMENT' and(
                nullif(a->>'r2_key','') is null
                or nullif(a->>'mime_type','') is null
                or v.r2_key is distinct from a->>'r2_key'))
              or(parsed.delivery_mode='SECURE_LINK' and(
                parsed.secure_link_required is not true
                or nullif(a->>'r2_key','') is not null))
          )
        )
      )
    order by coalesce(mo.next_attempt_at_utc,mo.scheduled_for_utc,mo.created_at_utc),
      mo.created_at_utc,mo.id
    for update skip locked limit v_limit
  ),
  contact_claim as materialized (
    select case when p_contact_bridge then public._email_outbox_contact_claim_stamp_v1(
      coalesce(array_agg(p.id),'{}'::uuid[]),p_attempt_lease_token,v_now,v_now+make_interval(mins=>v_lease),p_agency,p_environment) else null end proof
    from picked p
  ),
  updated as (
    update public.mail_outbox mo set attempt_lease_token=p_attempt_lease_token,
      attempt_leased_at_utc=v_now,attempt_lease_expires_at_utc=v_now+make_interval(mins=>v_lease)
    from picked p cross join contact_claim proof where mo.id=p.id returning mo.*
  )
  select u.* from updated u
  order by coalesce(u.next_attempt_at_utc,u.scheduled_for_utc,u.created_at_utc),u.created_at_utc,u.id;
  if p_contact_bridge then perform public._email_outbox_contact_claim_cleanup_v1(p_attempt_lease_token);end if;
end;
$function$;

-- Preserve original generic signature, INVOKER role/RLS, bounds and non-query
-- behavior. The same selection/lease kernel excludes managed query work here.
create or replace function public.email_outbox_claim_ready_batch(p_limit integer,p_attempt_lease_token text,p_lease_minutes integer default 5)
returns setof public.mail_outbox language plpgsql security invoker set search_path='public','pg_temp'
as $function$
begin return query select * from public._email_outbox_contact_claim_core_v1(p_limit,p_attempt_lease_token,p_lease_minutes,false);end;
$function$;

-- This narrow read-only fixed-deployment assertion permits the claim bridge to
-- retain the original INVOKER queue/RLS semantics. It allocates no work/permit.
create or replace function public._email_outbox_contact_claim_deployment_v1(p_agency uuid,p_environment text)
returns void language plpgsql volatile security definer set search_path='pg_catalog','private','pg_temp'
as $function$
begin
 perform private.weekly_source_query_require_service_v1();
 perform private.weekly_contact_context_v1(p_agency,p_environment);
end;
$function$;

create or replace function public.email_outbox_claim_ready_batch_contact_v1(p_request jsonb)
returns setof public.mail_outbox language plpgsql security invoker set search_path='pg_catalog','public','pg_temp'
as $function$
begin
 -- Closed syntax here; actual authenticated fixed deployment is verified by
 -- the audited service-only context assertion. The mode is a native lease
 -- selector, never provider permission: Root START/SENT guards remain required.
 if p_request is null or jsonb_typeof(p_request)<>'object' or not(p_request?&array['version','limit','attempt_lease_token','lease_minutes','worker_id','agency_id','environment'])
  or p_request-array['version','limit','attempt_lease_token','lease_minutes','worker_id','agency_id','environment']<>'{}'::jsonb
  or p_request->>'version' is distinct from 'EMAIL_OUTBOX_CONTACT_CLAIM_V1'
  or jsonb_typeof(p_request->'limit') is distinct from 'number' or p_request->>'limit'!~'^[0-9]{1,3}$' or(p_request->>'limit')::integer>500
  or jsonb_typeof(p_request->'lease_minutes') is distinct from 'number' or p_request->>'lease_minutes'!~'^[0-9]{1,2}$' or(p_request->>'lease_minutes')::integer not between 1 and 30
  or jsonb_typeof(p_request->'attempt_lease_token') is distinct from 'string' or char_length(p_request->>'attempt_lease_token') not between 1 and 500
  or jsonb_typeof(p_request->'worker_id') is distinct from 'string' or char_length(p_request->>'worker_id') not between 1 and 200
  or jsonb_typeof(p_request->'agency_id') is distinct from 'string' or not coalesce(p_request->>'agency_id'~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',false)
  or not coalesce(p_request->>'environment' in('TEST','LIVE'),false) then raise exception 'CONTACT_REQUEST_INVALID' using errcode='22023';end if;
 perform public._email_outbox_contact_claim_deployment_v1((p_request->>'agency_id')::uuid,p_request->>'environment');
 return query select * from public._email_outbox_contact_claim_core_v1((p_request->>'limit')::integer,p_request->>'attempt_lease_token',(p_request->>'lease_minutes')::integer,true,(p_request->>'agency_id')::uuid,p_request->>'environment');
end;
$function$;

-- Preview/in-flight hook for root's closed union. A real prior native claim is
-- explicitly distinct from a START permit; expiry cannot retire its unknown.
create or replace function private.weekly_contact_query_legacy_claims_v1(p_candidate uuid,p_client uuid,p_agency uuid,p_environment text)
returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare result jsonb;
begin
 perform private.weekly_source_query_require_service_v1();
 select coalesce(jsonb_agg(jsonb_build_object('kind','LEGACY_QUERY_CLAIM','mail_outbox_id',x.mail_outbox_id,'query_delivery_id',x.id,
  'claim_identity_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_QUERY_LEGACY_CLAIM_V1',jsonb_build_object(
   'mail_outbox_id',x.mail_outbox_id,'query_delivery_id',x.id,'lease_token',x.legacy_claim_lease_token)),'hex'),
  'claimed_at_utc',case when x.legacy_claim_leased_at_utc is null then null else to_char(x.legacy_claim_leased_at_utc at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end,
  'lease_expires_at_utc',case when x.legacy_claim_expires_at_utc is null then null else to_char(x.legacy_claim_expires_at_utc at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end,
  'status','CHECKING_ORIGINAL_LEGACY_CLAIM','provider_submission_established',false,'can_auto_resend',false) order by x.id),'[]'::jsonb)
 into result from public.hr_issue_email_deliveries x join public.mail_outbox o on o.id=x.mail_outbox_id
 where x.legacy_claim_lease_token is not null and not x.contact_managed and x.status<>'SENT' and o.sent_at is null and o.status::text<>'SENT'
  and exists(select 1 from public.hr_issue_email_delivery_items item join public.import_review_decisions a on a.action_id=item.action_id
   where item.delivery_id=x.id and a.candidate_id=p_candidate and a.client_id=p_client)
  and exists(select 1 from public.candidate_push_timing_policy policy where policy.agency_id=p_agency and policy.environment=p_environment and policy.deployment_slot);
 return result;
end;
$function$;

-- Complete final-repeatable successor after083; original0802 bytes remain intact.
create or replace function private.weekly_contact_pause_inflight_v1(
 p_agency uuid,p_environment text,p_candidate uuid,p_client uuid
) returns jsonb
language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
 select (select coalesce(jsonb_agg(x.summary order by x.started_at,x.permit_id),'[]'::jsonb) from(
  select p.id permit_id,p.admitted_at_utc started_at,jsonb_build_object(
   'permit_id',p.id,'owner_kind',p.owner_kind,'delivery_id',coalesce(p.dispatch_target_id,p.query_delivery_id),
   'provider_attempt_id',p.provider_attempt_id,'channel',p.channel,'status',p.status,
   'started_at_utc',to_char(p.admitted_at_utc at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   'memberships',(select jsonb_agg(m order by m->>'scope_id',m->>'audience') from jsonb_array_elements(p.scope_revisions_json)m
    where m->>'candidate_id'=p_candidate::text and m->>'client_id'=p_client::text)
  )summary
  from public.weekly_contact_submission_permits p where p.environment=p_environment and p.agency_id=p_agency
   and p.status in ('STARTED','AMBIGUOUS') and exists(select 1 from jsonb_array_elements(p.scope_revisions_json)m
    where m->>'candidate_id'=p_candidate::text and m->>'client_id'=p_client::text)
 )x) || private.weekly_contact_query_legacy_claims_v1(p_candidate,p_client,p_agency,p_environment);
$function$;
