-- CONTACT_PREPARER_UNIT 149 repeatable supabase/repeatable/16102026_0403_weekly_contact_source_memberships_v1.sql SHA256 b2b12f9958f6ca5c1cde34aeab9ff1515de83144a3670ec8b44f3182822448f7
-- Actual Source logical membership is recorded once; device transports remain native.
-- Reviewed proposal3b6adeb3f4db02cf35d62a887fed88af54a51212. No schema or sender.


-- Immutable native command/render lineage only. Current eligibility remains
-- Root0214/native START. Replies, pause and publication changes after START
-- must not erase genuine provider results for the original saved members.
create or replace function private.weekly_contact_source_logical_members_v1(p_command_id uuid)
returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare c public.weekly_message_dispatch_commands%rowtype;i public.weekly_message_intents%rowtype;
 r public.weekly_message_renders%rowtype;g public.weekly_candidate_outreach_generations%rowtype;
 request public.weekly_timesheet_submission_requests%rowtype;b public.weekly_manager_review_batches%rowtype;
 member record;members jsonb:='[]';identity jsonb;logical bytea;budget bytea;audience text;purpose text;ordinal integer;expected_count integer;
begin
 select * into strict c from public.weekly_message_dispatch_commands where id=p_command_id;
 select * into strict i from public.weekly_message_intents where id=c.message_intent_id;
 select * into strict r from public.weekly_message_renders where id=c.message_render_id;
 if r.message_intent_id<>i.id or i.environment<>c.environment or i.agency_id<>c.agency_id
  or i.source_cycle_id<>c.source_cycle_id or i.tranche_kind<>c.tranche_kind or i.tranche_sequence<>c.tranche_sequence
  or r.rendered_content_hash<>c.rendered_content_hash or r.membership_hash<>c.membership_hash
  or r.render_sequence<1 then raise exception 'CONTACT_SOURCE_NATIVE_LINEAGE_INVALID' using errcode='23514';end if;
 if i.audience_kind='CANDIDATE' then
  audience:='WORKER';
  select * into strict g from public.weekly_candidate_outreach_generations where id=c.candidate_generation_id;
  if i.candidate_generation_id<>g.id or i.candidate_cohort_id<>g.candidate_cohort_id or g.source_cycle_id<>c.source_cycle_id
   or g.membership_hash<>c.membership_hash then raise exception 'CONTACT_SOURCE_NATIVE_LINEAGE_INVALID' using errcode='23514';end if;
  purpose:=g.request_kind;
  if purpose='CHECK_HOURS' then
   select count(*) into expected_count from public.weekly_candidate_outreach_memberships where candidate_generation_id=g.id;
   ordinal:=case when c.tranche_kind='CANDIDATE_INITIAL' and c.tranche_sequence=1 then 1
    when c.tranche_kind='CANDIDATE_REMINDER_6H' and c.tranche_sequence=1 then 2
    when c.tranche_kind='CANDIDATE_MANUAL_REMINDER' and c.tranche_sequence<=2147483645 then c.tranche_sequence+2 end;
   for member in select m.id native_member_id,incident.id incident_id,incident.episode_number incident_episode,
    incident.work_event_id,g.candidate_id candidate_id,incident.client_id,
    jsonb_build_object('kind','CANDIDATE_CHECK_HOURS_MEMBER_V1','membership_id',m.id,'candidate_generation_id',g.id,
     'comparison_revision_id',comparison.id,'comparison_fingerprint',encode(comparison.material_comparison_fingerprint,'hex')) native_basis
    from public.weekly_candidate_outreach_memberships m join public.weekly_discrepancy_incidents incident on incident.id=m.incident_id
    join public.weekly_issue_comparison_revisions comparison on comparison.id=m.comparison_revision_id and comparison.incident_id=incident.id
    join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id and work.client_id=incident.client_id
    where m.candidate_generation_id=g.id and incident.candidate_id=g.candidate_id and incident.client_id=g.client_id
     and incident.source_cycle_id=g.source_cycle_id order by m.id loop
    identity:=jsonb_build_object('work_event_id',member.work_event_id,'incident_id',member.incident_id,'incident_episode',member.incident_episode);
    logical:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_SOURCE_LOGICAL_V1',jsonb_build_object('environment',c.environment,
     'agency_id',c.agency_id,'candidate_id',member.candidate_id,'client_id',member.client_id,'purpose',purpose,'audience',audience,'identity',identity));
    budget:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_SOURCE_BUDGET_V1',jsonb_build_object('logical_contact_key',encode(logical,'hex')));
    members:=members||jsonb_build_array(to_jsonb(member)||jsonb_build_object('logical_contact_key',encode(logical,'hex'),
     'budget_owner_key',encode(budget,'hex'),'purpose',purpose,'audience',audience,'send_ordinal',ordinal));
   end loop;
  elsif purpose='SUBMIT_TIMESHEET' then
   ordinal:=case when c.tranche_kind='TIMESHEET_SUBMISSION_INITIAL' and c.tranche_sequence=1 then 1
    when c.tranche_kind='TIMESHEET_SUBMISSION_REMINDER_6H' and c.tranche_sequence<=2147483646 then c.tranche_sequence+1 end;
   -- The real native request writer binds request_generation to this genuine
   -- outreach generation. No latest/max request or synthetic expected week.
   select * into strict request from public.weekly_timesheet_submission_requests x
    where x.candidate_cohort_id=g.candidate_cohort_id and x.candidate_id=g.candidate_id and x.source_cycle_id=g.source_cycle_id
     and x.request_generation=g.generation_number and x.membership_hash=g.membership_hash and x.environment=c.environment and x.agency_id=c.agency_id;
   select count(*) into expected_count from public.weekly_timesheet_submission_request_memberships where submission_request_id=request.id;
   for member in select m.id native_member_id,null::uuid incident_id,null::integer incident_episode,null::uuid work_event_id,
    request.candidate_id,m.client_id,
    jsonb_build_object('kind','NATIVE_EXPECTED_WEEK_MEMBER_V1','submission_request_id',request.id,'membership_id',m.id,
     'candidate_generation_id',g.id,'contract_id',m.contract_id,'week_ending',m.week_ending,
     'expected_source_fingerprint',encode(m.expected_source_fingerprint,'hex')) native_basis
    from public.weekly_timesheet_submission_request_memberships m join public.contracts contract on contract.id=m.contract_id
     and contract.candidate_id=request.candidate_id and contract.client_id=m.client_id
    where m.submission_request_id=request.id order by m.id loop
    identity:=jsonb_build_object('contract_id',member.native_basis->'contract_id','week_ending',member.native_basis->'week_ending');
    -- The saved fingerprint stays in actual native evidence, but reimport's
    -- publication/generation/fingerprint does not renew this week's allowance.
    logical:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_SOURCE_LOGICAL_V1',jsonb_build_object('environment',c.environment,
     'agency_id',c.agency_id,'candidate_id',member.candidate_id,'client_id',member.client_id,'purpose',purpose,'audience',audience,'identity',identity));
    budget:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_SOURCE_BUDGET_V1',jsonb_build_object('logical_contact_key',encode(logical,'hex')));
    members:=members||jsonb_build_array(to_jsonb(member)||jsonb_build_object('logical_contact_key',encode(logical,'hex'),
     'budget_owner_key',encode(budget,'hex'),'purpose',purpose,'audience',audience,'send_ordinal',ordinal));
   end loop;
  else raise exception 'CONTACT_SOURCE_NATIVE_PURPOSE_UNPROVIDED' using errcode='55000';end if;
 elsif i.audience_kind='MANAGER' then
  audience:='MANAGER';purpose:='CHECK_HOURS';
  -- All actual initial writers use sequence1. MANAGER_MANUAL_SELECTED claims
  -- unsent rows only. No current native MANAGER_MANUAL_RESEND producer exists;
  -- neither max accepted nor a new generation can invent its ordinal.
  if c.tranche_kind in('MANAGER_EARLY_ALL','MANAGER_T6_RESPONDED','MANAGER_T12_REMAINDER','MANAGER_MANUAL_SELECTED') and c.tranche_sequence=1 then ordinal:=1;end if;
  select * into strict b from public.weekly_manager_review_batches where message_render_id=r.id;
  select count(*) into expected_count from public.weekly_manager_review_items where review_batch_id=b.id;
  if b.recipient_generation_id<>i.recipient_generation_id or b.original_membership_hash<>c.membership_hash or b.sent_content_hash<>r.rendered_content_hash
   or c.recipient_route_id<>i.recipient_route_id then raise exception 'CONTACT_SOURCE_NATIVE_LINEAGE_INVALID' using errcode='23514';end if;
  for member in select m.id native_member_id,incident.id incident_id,m.incident_episode,incident.work_event_id,incident.candidate_id,incident.client_id,
   jsonb_build_object('kind','MANAGER_REVIEW_ITEM_V1','review_batch_id',b.id,'review_item_id',m.id,
    'comparison_revision_id',comparison.id,'comparison_fingerprint',encode(m.sent_comparison_fingerprint,'hex')) native_basis
   from public.weekly_manager_review_items m join public.weekly_discrepancy_incidents incident on incident.id=m.incident_id
   join public.weekly_issue_comparison_revisions comparison on comparison.id=m.sent_comparison_revision_id and comparison.incident_id=incident.id
    and comparison.material_comparison_fingerprint=m.sent_comparison_fingerprint
   join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id and work.client_id=incident.client_id
   where m.review_batch_id=b.id and incident.source_cycle_id=c.source_cycle_id order by m.id loop
   identity:=jsonb_build_object('work_event_id',member.work_event_id,'incident_id',member.incident_id,'incident_episode',member.incident_episode);
   logical:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_SOURCE_LOGICAL_V1',jsonb_build_object('environment',c.environment,
    'agency_id',c.agency_id,'candidate_id',member.candidate_id,'client_id',member.client_id,'purpose',purpose,'audience',audience,'identity',identity));
   budget:=private.weekly_source_sha256_jsonb_v1('WEEKLY_CONTACT_SOURCE_BUDGET_V1',jsonb_build_object('logical_contact_key',encode(logical,'hex')));
   members:=members||jsonb_build_array(to_jsonb(member)||jsonb_build_object('logical_contact_key',encode(logical,'hex'),
    'budget_owner_key',encode(budget,'hex'),'purpose',purpose,'audience',audience,'send_ordinal',ordinal));
  end loop;
 else raise exception 'CONTACT_SOURCE_NATIVE_PURPOSE_UNPROVIDED' using errcode='55000';end if;
 if ordinal is null then raise exception 'CONTACT_SOURCE_NATIVE_ORDINAL_UNPROVIDED' using errcode='55000';end if;
 if jsonb_array_length(members) not between 1 and 500 or jsonb_array_length(members) is distinct from expected_count
  or exists(select 1 from jsonb_array_elements(members)m group by m->>'logical_contact_key' having count(*)<>1) then
  raise exception 'CONTACT_SOURCE_NATIVE_LINEAGE_INVALID' using errcode='23514';end if;
 return jsonb_build_object('version','SOURCE_LOGICAL_MEMBERS_V1','dispatch_command_id',c.id,'payload_revision',r.render_sequence::text,
  'content_hash',encode(c.rendered_content_hash,'hex'),'members',members);
end;
$function$;

-- Called while common START already owns every actual sorted checking scope,
-- before native attempt allocation. A device of the SAME original command is
-- independent transport, never a duplicate new logical command.
create or replace function private.weekly_contact_source_budget_v1(p_command_id uuid)
returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare current_members jsonb:=private.weekly_contact_source_logical_members_v1(p_command_id);
 c public.weekly_message_dispatch_commands%rowtype;other_command record;other_members jsonb;member jsonb;checked integer:=0;
begin
 select * into strict c from public.weekly_message_dispatch_commands where id=p_command_id;
 for member in select value from jsonb_array_elements(current_members->'members') loop
  if exists(select 1 from public.weekly_contact_delivery_memberships m where m.logical_contact_key=decode(member->>'logical_contact_key','hex')
   and m.send_ordinal=(member->>'send_ordinal')::integer and m.delivery_id<>c.id) then
   return jsonb_build_object('allowed',false,'reason','ORIGINAL_LOGICAL_OWNER','logical_contact_key',member->'logical_contact_key');end if;
 end loop;
 -- Preserve genuine pre-install native ownership without inventing a pause
 -- revision, START permit or accepted timestamp for historical submissions.
 -- Only exact incident or expected Contract/week candidates are inspected;
 -- an unstarted old publication/render alone spends no send allowance.
 for other_command in
  select old.id from public.weekly_message_dispatch_commands old join public.weekly_message_intents intent on intent.id=old.message_intent_id
  where old.id<>c.id and old.agency_id=c.agency_id and old.environment=c.environment
   and (exists(select 1 from public.weekly_message_dispatch_targets t join public.weekly_message_target_attempts a on a.dispatch_target_id=t.id where t.dispatch_command_id=old.id)
    or exists(select 1 from public.weekly_message_provider_attempts a where a.dispatch_command_id=old.id))
   and exists(select 1 from jsonb_array_elements(current_members->'members')m where
    ((m->>'audience'='WORKER' and intent.audience_kind='CANDIDATE') or(m->>'audience'='MANAGER' and intent.audience_kind='MANAGER')) and(
    (m->>'incident_id' is not null and(
     exists(select 1 from public.weekly_candidate_outreach_memberships membership where membership.candidate_generation_id=old.candidate_generation_id and membership.incident_id=(m->>'incident_id')::uuid)
     or exists(select 1 from public.weekly_manager_review_batches batch join public.weekly_manager_review_items item on item.review_batch_id=batch.id
      where batch.message_render_id=old.message_render_id and item.incident_id=(m->>'incident_id')::uuid and item.incident_episode=(m->>'incident_episode')::integer)))
    or(m->>'purpose'='SUBMIT_TIMESHEET' and exists(
     select 1 from public.weekly_candidate_outreach_generations generation join public.weekly_timesheet_submission_requests request
      on request.candidate_cohort_id=generation.candidate_cohort_id and request.request_generation=generation.generation_number
       and request.candidate_id=generation.candidate_id and request.source_cycle_id=generation.source_cycle_id and request.membership_hash=generation.membership_hash
     join public.weekly_timesheet_submission_request_memberships membership on membership.submission_request_id=request.id
     where generation.id=old.candidate_generation_id and generation.request_kind='SUBMIT_TIMESHEET' and request.candidate_id=(m->>'candidate_id')::uuid
      and membership.client_id=(m->>'client_id')::uuid and membership.contract_id=(m->'native_basis'->>'contract_id')::uuid
      and membership.week_ending=(m->'native_basis'->>'week_ending')::date))))
  order by old.id limit 1001 loop
  checked:=checked+1;if checked>1000 then raise exception 'CONTACT_SOURCE_NATIVE_HISTORY_BOUND_EXCEEDED' using errcode='54000';end if;
  other_members:=private.weekly_contact_source_logical_members_v1(other_command.id);
  if exists(select 1 from jsonb_array_elements(current_members->'members')a cross join jsonb_array_elements(other_members->'members')b
   where a->>'logical_contact_key'=b->>'logical_contact_key' and a->'send_ordinal'=b->'send_ordinal') then
   return jsonb_build_object('allowed',false,'reason','ORIGINAL_NATIVE_ATTEMPT_OWNER','dispatch_command_id',other_command.id);end if;
 end loop;
 return jsonb_build_object('allowed',true,'reason','CURRENT_ORIGINAL_COMMAND');
end;
$function$;

-- True only at original native START after its real attempt + bound permit.
-- False only inside the original native result, after it classified that same
-- real consumed permit ACCEPTED. No provider call or target state mutation.
create or replace function private.weekly_contact_source_memberships_v1(p_permit_id uuid,p_enrol boolean)
returns void language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare p public.weekly_contact_submission_permits%rowtype;t public.weekly_message_dispatch_targets%rowtype;
 a public.weekly_message_target_attempts%rowtype;c public.weekly_message_dispatch_commands%rowtype;
 saved public.weekly_contact_delivery_memberships%rowtype;facts jsonb;member jsonb;scope jsonb;expected jsonb;actual jsonb;count_members integer;
begin
 perform private.weekly_source_query_require_service_v1();
 select * into strict p from public.weekly_contact_submission_permits where id=p_permit_id;
 select * into strict a from public.weekly_message_target_attempts where id=p.provider_attempt_id;
 select * into strict t from public.weekly_message_dispatch_targets where id=a.dispatch_target_id;
 select * into strict c from public.weekly_message_dispatch_commands where id=t.dispatch_command_id for update;
 if p_enrol is null or p.owner_kind<>'WEEKLY_SOURCE_TARGET' or p.dispatch_target_id<>t.id or p.dispatch_command_id<>c.id
  or p.agency_id<>c.agency_id or p.environment<>c.environment or p.channel<>t.channel or p.provider<>t.provider
  or p.content_hash<>t.rendered_content_hash or p.content_hash<>c.rendered_content_hash or p.recipient_hash<>t.keyed_target_fingerprint
  or p.lease_owner<>a.lease_owner or p.lease_token<>a.lease_token::text or p.provider_idempotency_identity is distinct from a.provider_idempotency_key
  or a.completed_at_utc is not null or t.state<>'SUBMISSION_STARTED' or t.attempt_count<>a.attempt_number
  or(p_enrol and p.status<>'STARTED') or(not p_enrol and(p.status<>'ACCEPTED' or p.consumed_at_utc is null or p.accepted_at_utc is null)) then
  raise exception 'CONTACT_SOURCE_NATIVE_RESULT_SCOPE_INVALID' using errcode='42501';end if;
 facts:=private.weekly_contact_source_logical_members_v1(c.id);
 for member in select value from jsonb_array_elements(facts->'members') order by value->>'logical_contact_key' loop
  select value into strict scope from jsonb_array_elements(p.scope_revisions_json)x(value)
   where value->>'candidate_id'=member->>'candidate_id' and value->>'client_id'=member->>'client_id' and value->>'audience'=member->>'audience';
  if not exists(select 1 from public.weekly_contact_pause_scopes s where s.id=(scope->>'scope_id')::uuid
   and s.agency_id=c.agency_id and s.environment=c.environment and s.candidate_id=(member->>'candidate_id')::uuid and s.client_id=(member->>'client_id')::uuid) then
   raise exception 'CONTACT_SOURCE_NATIVE_RESULT_SCOPE_INVALID' using errcode='42501';end if;
  if p_enrol then
   insert into public.weekly_contact_delivery_memberships(logical_contact_key,work_event_id,incident_id,incident_episode,purpose,audience,
    candidate_id,client_id,scope_id,scope_revision,delivery_id,payload_revision,content_hash,send_ordinal,budget_owner_key)
   values(decode(member->>'logical_contact_key','hex'),(member->>'work_event_id')::uuid,(member->>'incident_id')::uuid,(member->>'incident_episode')::integer,
    member->>'purpose',member->>'audience',(member->>'candidate_id')::uuid,(member->>'client_id')::uuid,(scope->>'scope_id')::uuid,
    private.weekly_contact_revision_v1(scope->'revision',false),c.id,(facts->>'payload_revision')::bigint,c.rendered_content_hash,
    (member->>'send_ordinal')::integer,decode(member->>'budget_owner_key','hex'))
   on conflict(delivery_id,logical_contact_key,send_ordinal) do nothing;
  end if;
  select * into strict saved from public.weekly_contact_delivery_memberships m where m.delivery_id=c.id
   and m.logical_contact_key=decode(member->>'logical_contact_key','hex') and m.send_ordinal=(member->>'send_ordinal')::integer for update;
  expected:=jsonb_build_object('logical_contact_key',decode(member->>'logical_contact_key','hex'),'work_event_id',member->'work_event_id',
   'incident_id',member->'incident_id','incident_episode',member->'incident_episode','purpose',member->'purpose','audience',member->'audience',
   'candidate_id',member->'candidate_id','client_id',member->'client_id','scope_id',scope->'scope_id','delivery_id',c.id,
   'payload_revision',(facts->>'payload_revision')::bigint,'content_hash',c.rendered_content_hash,'send_ordinal',member->'send_ordinal',
   'budget_owner_key',decode(member->>'budget_owner_key','hex'),'supersedes_unsubmitted_delivery_id',null);
  actual:=to_jsonb(saved)-array['id','scope_revision','accepted_at_utc','created_at_utc'];
  -- A later sibling can START after another pause revision. Its own permit
  -- captures that current revision; the membership retains its genuine first
  -- registration revision rather than rewriting earlier accepted provenance.
  if actual is distinct from expected or not exists(select 1 from public.weekly_contact_submission_permits previous
   cross join lateral jsonb_array_elements(previous.scope_revisions_json)s where previous.dispatch_command_id=c.id
    and previous.owner_kind='WEEKLY_SOURCE_TARGET' and previous.content_hash=c.rendered_content_hash
    and s->>'scope_id'=saved.scope_id::text and s->>'candidate_id'=saved.candidate_id::text and s->>'client_id'=saved.client_id::text
    and s->>'audience'=saved.audience and s->>'revision'=saved.scope_revision::text) then
   raise exception 'CONTACT_SOURCE_FROZEN_MEMBERSHIP_CHANGED' using errcode='23514';end if;
 end loop;
 select count(*) into count_members from public.weekly_contact_delivery_memberships where delivery_id=c.id;
 if count_members<>jsonb_array_length(facts->'members') then raise exception 'CONTACT_SOURCE_FROZEN_MEMBERSHIP_CHANGED' using errcode='23514';end if;
end;
$function$;

create or replace function private.weekly_contact_source_membership_accept_v1(p_attempt_id uuid)
returns void language plpgsql volatile security definer set search_path='pg_catalog','public','private','pg_temp'
as $function$
declare p public.weekly_contact_submission_permits%rowtype;m public.weekly_contact_delivery_memberships%rowtype;
begin
 perform private.weekly_source_query_require_service_v1();
 select * into strict p from public.weekly_contact_submission_permits where provider_attempt_id=p_attempt_id;
 -- This assertion locks the original command and validates the real current
 -- attempt/target, consumed ACCEPTED permit and every frozen native member.
 -- It never rechecks later pause/reply/current-publication or creates a row.
 perform private.weekly_contact_source_memberships_v1(p.id,false);
 for m in select x.* from public.weekly_contact_delivery_memberships x where x.delivery_id=p.dispatch_command_id order by x.logical_contact_key for update loop
  if m.accepted_at_utc is null then
   update public.weekly_contact_delivery_memberships set accepted_at_utc=p.accepted_at_utc where id=m.id;
  elsif not exists(select 1 from public.weekly_contact_submission_permits previous
   join public.weekly_message_target_attempts attempt on attempt.id=previous.provider_attempt_id
   join public.weekly_message_dispatch_targets target on target.id=previous.dispatch_target_id
   where previous.owner_kind='WEEKLY_SOURCE_TARGET' and previous.dispatch_command_id=p.dispatch_command_id
    and previous.status='ACCEPTED' and previous.accepted_at_utc=m.accepted_at_utc and previous.consumed_at_utc is not null
    and previous.content_hash=p.content_hash and attempt.dispatch_target_id=target.id and target.dispatch_command_id=p.dispatch_command_id
    and attempt.completed_at_utc is not null and attempt.outcome='ACCEPTED') then
   raise exception 'CONTACT_SOURCE_ACCEPTED_OWNER_INVALID' using errcode='23514';
  end if;
 end loop;
 -- Command-level acceptance is recorded once. The existing native result
 -- remains the only writer of this target and aggregate/sibling transport.
end;
$function$;

alter function private.weekly_contact_source_logical_members_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_contact_source_logical_members_v1(uuid) from public,anon,authenticated,service_role;
alter function private.weekly_contact_source_budget_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_contact_source_budget_v1(uuid) from public,anon,authenticated,service_role;
alter function private.weekly_contact_source_memberships_v1(uuid,boolean) OWNER TO CURRENT_USER;
revoke all on function private.weekly_contact_source_memberships_v1(uuid,boolean) from public,anon,authenticated,service_role;
alter function private.weekly_contact_source_membership_accept_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_contact_source_membership_accept_v1(uuid) from public,anon,authenticated,service_role;

notify pgrst,'reload schema';


